INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'No princípio criou Deus os céus e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'E a terra estava desordenada e vazia, e as trevas estavam sobre a face do abismo, e o Espírito de Deus se movia sobre a face das águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'E disse Deus: Haja luz; e houve luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'E viu Deus que a luz era boa: e separou Deus a luz das trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'E chamou Deus à luz Dia, e às trevas chamou Noite: e foi a tarde e a manhã o primeiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'E disse Deus: Haja expansão em meio das águas, e separe as águas das águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'E fez Deus a expansão, e separou as águas que estavam debaixo da expansão, das águas que estavam sobre a expansão: e foi assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'E chamou Deus à expansão Céus: e foi a tarde e a manhã, o dia segundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'E disse Deus: Juntem-se as águas que estão debaixo dos céus em um lugar, e descubra-se a porção seca; e foi assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'E chamou Deus à porção seca Terra, e à reunião das águas chamou Mares; e viu Deus que era bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'E disse Deus: Produza a terra erva verde, erva que dê semente; árvore de fruto que dê fruto segundo a sua espécie, que sua semente esteja nela, sobre a terra: e foi assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'E produziu a terra erva verde, erva que dá semente segundo sua natureza, e árvore que dá fruto, cuja semente está nele, segundo a sua espécie; e viu Deus que era bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'E foi a tarde e a manhã, o dia terceiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'E disse Deus: Haja luminares na expansão dos céus para separar o dia e a noite: e sejam por sinais, e para as estações, e para dias e anos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'E sejam por luminares na expansão dos céus para iluminar sobre a terra: e foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'E fez Deus os dois grandes luminares; o luminar maior para que exerça domínio no dia, e o luminar menor para que exerça domínio na noite; fez também as estrelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'E as pôs Deus na expansão dos céus, para iluminar sobre a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'E para exercer domínio no dia e na noite, e para separar a luz e as trevas: e viu Deus que era bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'E foi a tarde e a manhã, o dia quarto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'E disse Deus: Produzam as águas répteis de alma vivente, e aves que voem sobre a terra, na expansão aberta dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'E criou Deus as grandes criaturas marinhas, e toda coisa viva que anda arrastando, que as águas produziram segundo a sua espécie, e toda ave de asas segundo sua espécie: e viu Deus que era bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'E Deus os abençoou dizendo: Frutificai e multiplicai, e enchei as águas nos mares, e as aves se multipliquem na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'E foi a tarde e a manhã, o dia quinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'E disse Deus: Produza a terra seres viventes segundo a sua espécie, animais e serpentes e animais da terra segundo sua espécie: e foi assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'E fez Deus animais da terra segundo a sua espécie, e gado segundo a sua espécie, e todo animal que anda arrastando sobre a terra segundo sua espécie: e viu Deus que era bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'E disse Deus: Façamos ao ser humano à nossa imagem, conforme nossa semelhança; e domine os peixes do mar, e as aves dos céus, e os animais, e toda a terra, e todo animal que anda arrastando sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'E criou Deus o ser humano à sua imagem, à imagem de Deus o criou; macho e fêmea os criou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'E Deus os abençoou; e disse-lhes Deus: Frutificai e multiplicai, e enchei a terra, e subjugai-a, e dominai os peixes do mar, as aves dos céus, e todos os animais que se movem sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'E disse Deus: Eis que vos dei toda erva que dá semente, que está sobre a face de toda a terra; e toda árvore em que há fruto de árvore que dá semente, vos será para comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'E a todo animal da terra, e a todas as aves dos céus, e a tudo o que se move sobre a terra, em que há vida, toda erva verde lhes será para comer: e foi assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'E viu Deus tudo o que havia feito, e eis que era bom em grande maneira. E foi a tarde e a manhã, o dia sexto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'E foram concluídos os céus e a terra, e tudo o que neles há.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'E acabou Deus no dia sétimo sua obra que fez, e repousou o dia sétimo de toda sua obra que havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'E abençoou Deus ao dia sétimo, e o santificou, porque nele repousou de toda sua obra que havia Deus criado e feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Estas são as origens dos céus e da terra quando foram criados, no dia que o SENHOR Deus fez a terra e os céus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'E antes que toda planta do campo existisse na terra, e antes que toda erva do campo nascesse; porque ainda não havia o SENHOR Deus feito chover sobre a terra, nem havia homem para que lavrasse a terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Mas subia da terra um vapor, que regava toda a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Formou, pois, o SENHOR Deus ao homem do pó da terra, e assoprou em seu nariz sopro de vida; e foi o homem em alma vivente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'E havia o SENHOR Deus plantado um jardim em Éden ao oriente, e pôs ali ao homem que havia formado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'E havia o SENHOR Deus feito nascer da terra toda árvore agradável à vista, e boa para comer: também a árvore da vida em meio do jardim, e a árvore do conhecimento do bem e do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'E saía de Éden um rio para regar o jardim, e dali se repartia em quatro ramificações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'O nome de um era Pisom: este é o que cerca toda a terra de Havilá, onde há ouro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'E o ouro daquela terra é bom; há ali também bdélio e pedra ônix.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'O nome do segundo rio é Giom; este é o que rodeia toda a terra de Cuxe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'E o nome do terceiro rio é Tigre; este é o que vai diante da Assíria. E o quarto rio é o Eufrates.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Tomou, pois, o SENHOR Deus ao homem, e o pôs no jardim de Éden, para que o lavrasse e o guardasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'E mandou o SENHOR Deus ao homem, dizendo: De toda árvore do jardim comerás;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Mas da árvore do conhecimento do bem e do mal não comerás dela; porque no dia que dela comeres, morrerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'E disse o SENHOR Deus: Não é bom que o homem esteja só; farei para ele ajuda idônea para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Formou, pois, o SENHOR Deus da terra todo animal do campo, e toda ave dos céus, e trouxe-os a Adão, para que visse como lhes havia de chamar; e tudo o que Adão chamou aos animais viventes, esse é seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'E pôs Adão nomes a todo animal e ave dos céus e a todo animal do campo: mas para Adão não achou ajuda que estivesse idônea para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'E o SENHOR Deus fez cair sonho sobre Adão, e ele adormeceu: então tomou uma de suas costelas, e fechou a carne em seu lugar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'E da costela que o SENHOR Deus tomou do homem, fez uma mulher, e trouxe-a ao homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'E disse Adão: Esta é agora osso de meus ossos, e carne de minha carne: esta será chamada Mulher, porque do homem foi tomada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Portanto, deixará o homem a seu pai e a sua mãe, e se achegará à sua mulher, e serão uma só carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'E estavam ambos nus, Adão e sua mulher, e não se envergonhavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Porém a serpente era astuta, mais que todos os animais do campo que o SENHOR Deus havia feito; a qual disse à mulher: Deus vos disse: Não comais de toda árvore do jardim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'E a mulher respondeu à serpente: Do fruto das árvores do jardim comemos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Mas do fruto da árvore que está em meio do jardim disse Deus: Não comereis dele, nem o tocareis, para que não morrais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Então a serpente disse à mulher: Não morrereis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Mas sabe Deus que no dia que comerdes dele, serão abertos vossos olhos, e sereis como deuses sabendo o bem e o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'E viu a mulher que a árvore era boa para comer, e que era agradável aos olhos, e árvore cobiçável para alcançar a sabedoria; e tomou de seu fruto, e comeu; e deu também a seu marido, o qual comeu assim como ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'E foram abertos os olhos de ambos, e conheceram que estavam nus: então coseram folhas de figueira, e fizeram para si aventais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'E ouviram a voz do SENHOR Deus que se passeava no jardim ao esfriar do dia: e escondeu-se o homem e sua mulher da presença do SENHOR Deus entre as árvores do jardim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'E chamou o SENHOR Deus ao homem, e lhe disse: Onde estás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'E ele respondeu: Ouvi tua voz no jardim, e tive medo, porque estava nu; e me escondi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'E disse-lhe: Quem te ensinou que estavas nu? Comeste da árvore de que eu te mandei não comesses?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'E o homem respondeu: A mulher que me deste por companheira me deu da árvore, e eu comi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Então o SENHOR Deus disse à mulher: Que é o que fizeste? E disse a mulher: A serpente me enganou, e comi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'E o SENHOR Deus disse à serpente: Porquanto isto fizeste, maldita serás entre todos os animais selvagens e entre todos os animais do campo; sobre teu peito andarás, e pó comerás todos os dias de tua vida:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'E inimizade porei entre ti e a mulher, e entre tua descendência e a descendência dela; esta te ferirá na cabeça, e tu lhe ferirás no calcanhar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'À mulher disse: Multiplicarei em grande maneira tuas dores e teus sofrimentos de parto; com dor darás à luz os filhos; e a teu marido será teu desejo, e ele exercerá domínio sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'E ao homem disse: Porquanto obedeceste à voz de tua mulher, e comeste da árvore de que te mandei dizendo, Não comerás dela; maldita será a terra por causa de ti; com dor comerás dela todos os dias de tua vida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Espinhos e cardos te produzirá, e comerás erva do campo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'No suor de teu rosto comerás o pão até que voltes à terra; porque dela foste tomado: pois pó és, e ao pó voltarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'E chamou o homem o nome de sua mulher, Eva; porquanto ela era mãe de todos o viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'E o SENHOR Deus fez ao homem e à sua mulher túnicas de peles, e vestiu-as.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'E disse o SENHOR Deus: Eis que o homem é como um de Nos sabendo o bem e o mal: agora, pois, para que não estenda sua mão, e tome também da árvore da vida, e coma, e viva para sempre:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'E tirou-o o SENHOR do jardim de Éden, para que lavrasse a terra de que foi tomado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Lançou, pois, fora ao homem, e pôs ao oriente do jardim de Éden querubins, e uma espada acesa que se revolvia a todos os lados, para guardar o caminho da árvore da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'E conheceu Adão a sua mulher Eva, a qual concebeu e deu à luz a Caim, e disse: Adquiri um homem pelo SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'E depois deu à luz a seu irmão Abel. E foi Abel pastor de ovelhas, e Caim foi lavrador da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'E aconteceu decorrendo o tempo, que Caim trouxe do fruto da terra uma oferta ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'E Abel trouxe também dos primogênitos de suas ovelhas, e de sua gordura. E olhou o SENHOR com agrado a Abel e à sua oferta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Mas não olhou com bons olhos a Caim e à sua oferta. E irritou-se Caim em grande maneira, e decaiu seu semblante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Então o SENHOR disse a Caim: Por que te irritaste, e por que se mudou teu rosto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Se bem fizeres, não serás aceito? E se não fizeres bem, o pecado está à porta; contra ti será o seu desejo, porém tu deves dominá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'E falou Caim a seu irmão Abel; e aconteceu que estando eles no campo, Caim se levantou contra seu irmão Abel, e o matou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'E o SENHOR disse a Caim: Onde está Abel teu irmão? E ele respondeu: Não sei; sou eu guarda de meu irmão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'E ele lhe disse: Que fizeste? A voz do sangue de teu irmão clama a mim desde a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Agora, pois, maldito sejas tu da terra que abriu sua boca para receber o sangue de teu irmão de tua mão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Quando lavrares a terra, não te voltará a dar sua força: errante e fugitivo serás na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'E disse Caim ao SENHOR: Grande é minha iniquidade para ser perdoada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Eis que me expulsas hoje da face da terra, e de tua presença me esconderei; e serei errante e fugitivo na terra; e sucederá que qualquer um que me achar, me matará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'E respondeu-lhe o SENHOR: Certo que qualquer um que matar a Caim, sete vezes será castigado. Então o SENHOR pôs sinal em Caim, para que não o ferisse qualquer um que o achasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'E saiu Caim de diante do SENHOR, e habitou na terra de Node, ao oriente de Éden.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'E conheceu Caim a sua mulher, a qual concebeu e deu à luz a Enoque: e edificou uma cidade, e chamou o nome da cidade do nome de seu filho, Enoque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'E a Enoque nasceu Irade, e Irade gerou a Meujael, e Meujael gerou a Metusael, e Metusael gerou a Lameque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'E tomou para si Lameque duas mulheres; o nome de uma foi Ada, e o nome da outra Zilá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'E Ada deu à luz a Jabal, o qual foi pai dos que habitam em tendas, e criam gados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'E o nome de seu irmão foi Jubal, o qual foi pai de todos os que manejam harpa e flauta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'E Zilá também deu à luz a Tubalcaim, feitor de toda obra de bronze e de ferro: e a irmã de Tubalcaim foi Naamá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'E disse Lameque a suas mulheres: Ada e Zilá, ouvi minha voz; Mulheres de Lameque, escutai meu dito: Que matei um homem por ter me ferido, E um rapaz por ter me golpeado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Se sete vezes será vingado Caim, Lameque em verdade setenta vezes sete o será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'E conheceu de novo Adão à sua mulher, a qual deu à luz um filho, e chamou seu nome Sete: Porque Deus (disse ela) me substituiu outra descendência em lugar de Abel, a quem matou Caim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'E a Sete também lhe nasceu um filho, e chamou seu nome Enos. Então os homens começaram a invocar o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Este é o livro das gerações de Adão. No dia em que criou Deus ao ser humano, à semelhança de Deus o fez;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Macho e fêmea os criou; e os abençoou, e chamou o nome deles Adão, no dia em que foram criados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'E viveu Adão cento e trinta anos, e gerou um filho à sua semelhança, conforme sua imagem, e chamou seu nome Sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'E foram os dias de Adão, depois que gerou a Sete, oitocentos anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'E foram todos os dias que viveu Adão novecentos e trinta anos, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'E viveu Sete cento e cinco anos, e gerou a Enos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'E viveu Sete, depois que gerou a Enos, oitocentos e sete anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'E foram todos os dias de Sete novecentos e doze anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'E viveu Enos noventa anos, e gerou a Cainã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'E viveu Enos depois que gerou a Cainã, oitocentos e quinze anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'E foram todos os dias de Enos novecentos e cinco anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'E viveu Cainã setenta anos, e gerou a Maalalel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'E viveu Cainã, depois que gerou a Maalalel, oitocentos e quarenta anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'E foram todos os dias de Cainã novecentos e dez anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'E viveu Maalalel sessenta e cinco anos, e gerou a Jarede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'E viveu Maalalel, depois que gerou a Jarede, oitocentos e trinta anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'E foram todos os dias de Maalalel oitocentos noventa e cinco anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'E viveu Jarede cento e sessenta e dois anos, e gerou a Enoque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'E viveu Jarede, depois que gerou a Enoque, oitocentos anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'E foram todos os dias de Jarede novecentos e sessenta e dois anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'E viveu Enoque sessenta e cinco anos, e gerou a Matusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'E caminhou Enoque com Deus, depois que gerou a Matusalém, trezentos anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'E foram todos os dias de Enoque trezentos sessenta e cinco anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Caminhou, pois, Enoque com Deus, e desapareceu, porque Deus o levou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'E viveu Matusalém cento e oitenta e sete anos, e gerou a Lameque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'E viveu Matusalém, depois que gerou a Lameque, setecentos e oitenta e dois anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Foram, pois, todos os dias de Matusalém, novecentos e sessenta e nove anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'E viveu Lameque cento e oitenta e dois anos, e gerou um filho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'E chamou seu nome Noé, dizendo: Este nos aliviará de nossas obras, e do trabalho de nossas mãos, por causa da terra que o SENHOR amaldiçoou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'E viveu Lameque, depois que gerou a Noé, quinhentos noventa e cinco anos: e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'E foram todos os dias de Lameque setecentos e setenta e sete anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'E sendo Noé de quinhentos anos, gerou a Sem, Cam, e a Jafé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'E aconteceu que, quando começaram os homens a multiplicar-se sobre a face da terra, e lhes nasceram filhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Vendo os filhos de Deus que as filhas dos homens eram belas, tomaram para si mulheres, escolhendo entre todas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'E disse o SENHOR: Não brigará meu espírito com o ser humano para sempre, porque certamente ele é carne: mas serão seus dias cento e vinte anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Havia gigantes na terra naqueles dias, e também depois que entraram os filhos de Deus às filhas dos homens, e lhes geraram filhos: estes foram os valentes que desde a antiguidade foram homens de renome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'E viu o SENHOR que a malícia dos seres humanos era muito na terra, e que todo desígnio dos pensamentos do coração deles era continuamente somente o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'E arrependeu-se o SENHOR de haver feito o ser humano na terra, e pesou-lhe em seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'E disse o SENHOR: Apagarei os seres humanos que criei de sobre a face da terra, desde o ser humano até o animal, e até o réptil e as aves do céu: porque me arrependo de havê-los feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Porém Noé achou favor aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Estas são as gerações de Noé: Noé, homem justo, foi íntegro em suas gerações; Noé andava com Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'E gerou Noé três filhos: a Sem, a Cam, e a Jafé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'E corrompeu-se a terra diante de Deus, e estava a terra cheia de violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'E olhou Deus a terra, e eis que estava contaminada; porque toda carne havia corrompido seu caminho sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'E disse Deus a Noé: O fim de toda carne veio diante de mim; porque a terra está cheia de violência por causa deles; e eis que eu os destruirei com a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Faze-te uma arca de madeira de gôfer: farás aposentos na arca e a selarás com betume por dentro e por fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'E desta maneira a farás: de trezentos côvados o comprimento da arca, de cinquenta côvados sua largura, e de trinta côvados sua altura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Uma janela farás à arca, e a acabarás a um côvado de elevação pela parte de cima: e porás a porta da arca a seu lado; e lhe farás piso abaixo, segundo e terceiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'E eu, eis que eu trago um dilúvio de águas sobre a terra, para destruir toda carne em que haja espírito de vida debaixo do céu; tudo o que há na terra morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mas estabelecerei meu pacto contigo, e entrarás na arca tu, e teus filhos e tua mulher, e as mulheres de teus filhos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'E de tudo o que vive, de toda carne, dois de cada espécie porás na arca, para que tenham vida contigo; macho e fêmea serão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Das aves segundo sua espécie, e dos animais segundo sua espécie, de todo réptil da terra segundo sua espécie, dois de cada espécie entrarão contigo para que tenham vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'E toma contigo de toda comida que se come, e traga-a a ti; servirá de alimento para ti e para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'E o fez assim Noé; fez conforme tudo o que Deus lhe mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'E o SENHOR disse a Noé: Entra tu e toda tua casa na arca porque a ti vi justo diante de mim nesta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De todo animal limpo tomarás de sete em sete, macho e sua fêmea; mas dos animais que não são limpos, dois, macho e sua fêmea.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Também das aves dos céus de sete em sete, macho e fêmea; para guardar em vida a descendência sobre a face de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Porque passados ainda sete dias, eu farei chover sobre a terra quarenta dias e quarenta noites; e apagarei toda criatura que fiz de sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'E fez Noé conforme tudo o que lhe mandou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'E sendo Noé de seiscentos anos, o dilúvio das águas foi sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'E veio Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele à arca, por causa das águas do dilúvio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Dos animais limpos, e dos animais que não eram limpos, e das aves, e de todo o que anda arrastando sobre a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'De dois em dois entraram a Noé na arca: macho e fêmea, como mandou Deus a Noé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'E sucedeu que ao sétimo dia as águas do dilúvio foram sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'No ano seiscentos da vida de Noé, no mês segundo, no dia dezessete do mês, naquele dia foram rompidas todas as fontes do grande abismo, e as comportas dos céus foram abertas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'E houve chuva sobre a terra quarenta dias e quarenta noites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Neste mesmo dia entrou Noé, e Sem, e Cam e Jafé, filhos de Noé, a mulher de Noé, e as três mulheres de seus filhos com ele na arca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Eles e todos os animais silvestres segundo suas espécies, e todos os animais mansos segundo suas espécies, e todo réptil que anda arrastando sobre a terra segundo sua espécie, e toda ave segundo sua espécie, todo pássaro, toda espécie de animal voador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'E vieram a Noé à arca, de dois em dois de toda carne em que havia espírito de vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'E os que vieram, macho e fêmea de toda carne vieram, como lhe havia mandado Deus: e o SENHOR lhe fechou a porta');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'E foi o dilúvio quarenta dias sobre a terra; e as águas cresceram, e levantaram a arca, e se elevou sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'E prevaleceram as águas, e cresceram em grande maneira sobre a terra; e andava a arca sobre a face das águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'E as águas prevaleceram muito em extremo sobre a terra; e todos os montes altos que havia debaixo de todos os céus, foram cobertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Quinze côvados em altura prevaleceram as águas; e foram cobertos os montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'E morreu toda carne que se move sobre a terra, tanto de aves como de gados, e de animais, e de todo réptil que anda arrastando sobre a terra, e todo ser humano:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Tudo o que tinha fôlego de espírito de vida em suas narinas, de tudo o que havia na terra, morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Assim foi destruída toda criatura que vivia sobre a face da terra, desde o ser humano até o animal, e os répteis, e as aves do céu; e foram apagados da terra; e restou somente Noé, e os que com ele estavam na arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'E prevaleceram as águas sobre a terra cento e cinquenta dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'E lembrou-se Deus de Noé, e de todos os animais, selvagens e domésticos que estavam com ele na arca; e fez passar Deus um vento sobre a terra, e diminuíram as águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'E se fecharam as fontes do abismo, e as comportas dos céus; e a chuva dos céus foi detida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'E voltaram-se as águas de sobre a terra, indo e voltando; e decresceram as águas ao fim de cento e cinquenta dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'E repousou a arca no mês sétimo, a dezessete dias do mês, sobre os montes de Ararate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'E as águas foram decrescendo até o mês décimo: no décimo, ao primeiro dia do mês, se revelaram os cumes dos montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'E sucedeu que, ao fim de quarenta dias, abriu Noé a janela da arca que havia feito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'E enviou ao corvo, o qual saiu, e esteve indo e voltando até que as águas se secaram de sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Enviou também de si à pomba, para ver se as águas se haviam retirado de sobre a face da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'E não achou a pomba onde sentar a planta de seu pé, e voltou-se a ele à arca, porque as águas estavam ainda sobre a face de toda a terra: então ele estendeu sua mão e recolhendo-a, a fez entrar consigo na arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'E esperou ainda outros sete dias, e voltou a enviar a pomba fora da arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'E a pomba voltou a ele à hora da tarde; e eis que trazia uma folha de oliveira tomada em seu bico; então Noé entendeu que as águas haviam se retirado de sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'E esperou ainda outros sete dias, e enviou a pomba, a qual não voltou já mais a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'E sucedeu que no ano seiscentos e um de Noé, no mês primeiro, ao primeiro do mês, as águas se enxugaram de sobre a terra e tirou Noé a cobertura da arca, e olhou, e eis que a face da terra estava enxuta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'E no mês segundo, aos vinte e sete dias do mês, se secou a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'E falou Deus a Noé dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sai da arca tu, a tua mulher, os teus filhos, e as mulheres dos teus filhos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Todos os animais que estão contigo de toda carne, de aves e de animais e de todo réptil que anda arrastando sobre a terra, tirarás contigo; e vão pela terra, e frutifiquem, e multipliquem-se sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Então saiu Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Todos os animais, e todo réptil e toda ave, tudo o que se move sobre a terra segundo suas espécies, saíram da arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'E edificou Noé um altar ao SENHOR e tomou de todo animal limpo e de toda ave limpa, e ofereceu holocausto no altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'E percebeu o SENHOR cheiro suave; e disse o SENHOR em seu coração: Não voltarei mais a amaldiçoar a terra por causa do ser humano; porque o intento do coração do ser humano é mau desde sua juventude: nem voltarei mais a destruir todo vivente, como fiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Enquanto a terra durar, a sementeira e a colheita, o frio e calor, verão e inverno, dia e noite, não cessarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'E Deus abençoou Noé e seus filhos, e disse-lhes: Frutificai, e multiplicai, e enchei a terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'E vosso temor e vosso pavor será sobre todo animal da terra, e sobre toda ave dos céus, em tudo o que se mover na terra, e em todos os peixes do mar: em vossa mão são entregues.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Tudo o que se move e vive vos será para mantimento: assim como os legumes e ervas, vos dei disso tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Porém a carne com sua vida, que é seu sangue, não comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Porque certamente exigirei o sangue de vossas vidas; da mão de todo animal o exigirei, e da mão do ser humano; da mão do homem seu irmão exigirei a vida do ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'O que derramar sangue humano, pelo ser humano seu sangue será derramado; porque à imagem de Deus o ser humano foi feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Mas vós frutificai, e multiplicai-vos; procriai abundantemente na terra, e multiplicai-vos nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'E falou Deus a Noé e a seus filhos com ele, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Eis que eu mesmo estabeleço meu pacto convosco, e com vossa descendência depois de vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'E com toda alma vivente que está convosco, de aves, de animais, e de toda fera da terra que está convosco; desde todos os que saíram da arca até todo animal da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Estabelecerei meu pacto convosco, e não será mais exterminada toda carne com águas de dilúvio; nem haverá mais dilúvio para destruir a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'E disse Deus: Este será o sinal do pacto que estabeleço entre mim e vós e toda alma vivente que está convosco, por tempos perpétuos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Meu arco porei nas nuvens, o qual será por sinal de aliança entre mim e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'E será que quando fizer vir nuvens sobre a terra, se deixará ver então meu arco nas nuvens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'E me lembrarei do meu pacto, que há entre mim e vós e toda alma vivente de toda carne; e não serão mais as águas por dilúvio para destruir toda carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'E estará o arco nas nuvens, e o verei para me lembrar do pacto perpétuo entre Deus e toda alma vivente, com toda carne que há sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Disse, pois, Deus a Noé: Este será o sinal do pacto que estabeleci entre mim e toda carne que está sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'E os filhos de Noé que saíram da arca foram Sem, Cam e Jafé: e Cam é o pai de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Estes três são os filhos de Noé; e deles foi cheia toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'E começou Noé a lavrar a terra, e plantou uma vinha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'E bebeu do vinho, e se embriagou, e estava descoberto dentro de sua tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'E Cam, pai de Canaã, viu a nudez de seu pai, e disse-o aos seus dois irmãos do lado de fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Então Sem e Jafé tomaram a roupa, e a puseram sobre seus próprios ombros, e andando para trás, cobriram a nudez de seu pai tendo seus rostos virados, e assim não viram a nudez de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'E despertou Noé de seu vinho, e soube o que havia feito com ele seu filho o mais jovem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'E disse: Maldito seja Canaã; Servo de servos será a seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Disse mais: Bendito o SENHOR o Deus de Sem, E seja-lhe Canaã servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Engrandeça Deus a Jafé, E habite nas tendas de Sem, E seja-lhe Canaã servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'E viveu Noé depois do dilúvio trezentos e cinquenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'E foram todos os dias de Noé novecentos e cinquenta anos; e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Estas são as gerações dos filhos de Noé: Sem, Cam e Jafé, aos quais nasceram filhos depois do dilúvio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Os filhos de Jafé: Gômer, e Magogue, e Madai, e Javã, e Tubal, e Meseque, e Tiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'E os filhos de Gômer: Asquenaz, e Rifate, e Togarma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'E os filhos de Javã: Elisá, e Társis, Quitim, e Dodanim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Por estes foram repartidas as ilhas das nações em suas terras, cada qual segundo sua língua, conforme suas famílias em suas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Os filhos de Cam: Cuxe, e Mizraim, e Pute, e Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'E os filhos de Cuxe: Sebá, Havilá, e Sabtá, e Raamá, e Sabtecá. E os filhos de Raamá: Sabá e Dedã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'E Cuxe gerou a Ninrode, este começou a ser poderoso na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Este foi vigoroso caçador diante do SENHOR; pelo qual se diz: Assim como Ninrode, vigoroso caçador diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'E foi a cabeceira de seu reino Babel, e Ereque, e Acade, e Calné, na terra de Sinear.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De esta terra saiu Assur, e edificou a Nínive, e a Reobote-Ir, e a Calá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'E a Resém entre Nínive e Calá; a qual é cidade grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'E Mizraim gerou a Ludim, e a Anamim, e a Leabim, e a Naftuim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'E a Patrusim, e a Casluim de onde saíram os filisteus, e a Caftorim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'E Canaã gerou a Sidom, seu primogênito e a Hete,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'E aos jebuseus, e aos amorreus, e aos gergeseus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'E aos heveus, e aos arqueus, e aos sineus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'E aos arvadeus e aos zemareus, e aos hamateus: e depois se derramaram as famílias dos cananeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'E foi o termo dos cananeus desde Sidom, vindo a Gerar até Gaza, até entrar em Sodoma e Gomorra, Admá, e Zeboim até Lasa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Estes são os filhos de Cam por suas famílias, por suas línguas, em suas terras, em suas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Também lhe nasceram filhos a Sem, pai de todos os filhos de Héber, e irmão mais velho de Jafé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'E os filhos de Sem: Elão, e Assur, e Arfaxade, e Lude, e Arã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'E os filhos de Arã: Uz, e Hul, e Géter, e Mas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'E Arfaxade gerou a Salá, e Salá gerou a Héber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'E a Héber nasceram dois filhos: o nome de um foi Pelegue, porque em seus dias foi repartida a terra; e o nome de seu irmão, Joctã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'E Joctã gerou a Almodá, e a Salefe, e Hazarmavé, e a Jerá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'E a Hadorão, e a Uzal, e a Dicla,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'E a Obal, e a Abimael, e a Sabá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'E a Ofir, e a Havilá, e a Jobabe: todos estes foram filhos de Joctã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'E foi sua habitação desde Messa vindo de Sefar, monte à parte do oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Estes foram os filhos de Sem por suas famílias, por suas línguas, em suas terras, em suas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Estas são as famílias de Noé por suas descendências, em suas nações; e destes foram divididas os povos na terra depois do dilúvio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Era, então, toda a terra de uma língua e umas mesmas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'E aconteceu que, quando se partiram do oriente, acharam um vale na terra de Sinear; e ali passaram a habitar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'E disseram uns aos outros: Vinde, façamos tijolos e o cozamos com fogo. E foi-lhes os tijolos em lugar de pedra, e o betume em lugar de argamassa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'E disseram: Vamos, edifiquemo-nos uma cidade e uma torre, cuja ponta chegue ao céu; e façamo-nos um nome, para que não sejamos espalhados sobre a face de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'E desceu o SENHOR para ver a cidade e a torre que edificavam os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'E disse o SENHOR: Eis que o povo é um, e todos estes têm uma língua; e começaram a agir, e nada lhes restringirá agora do que pensaram fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Agora, pois, desçamos, e confundamos ali suas línguas, para que ninguém entenda a fala de seu companheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Assim os espalhou o SENHOR desde ali sobre a face de toda a terra, e deixaram de edificar a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Por isto foi chamado o nome dela Babel, porque ali confundiu o SENHOR a língua de toda a terra, e desde ali os espalhou sobre a face de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Estas são as gerações de Sem: Sem, de idade de cem anos, gerou a Arfaxade, dois anos depois do dilúvio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'E viveu Sem, depois que gerou a Arfaxade quinhentos anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'E Arfaxade viveu trinta e cinco anos, e gerou a Salá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'E viveu Arfaxade, depois que gerou a Salá, quatrocentos e três anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'E viveu Salá trinta anos, e gerou a Héber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'E viveu Salá, depois que gerou a Héber, quatrocentos e três anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'E viveu Héber trinta e quatro anos, e gerou a Pelegue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'E viveu Héber, depois que gerou a Pelegue, quatrocentos e trinta anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'E viveu Pelegue, trinta anos, e gerou a Reú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'E viveu Pelegue, depois que gerou a Reú, duzentos e nove anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'E Reú viveu trinta e dois anos, e gerou a Serugue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'E viveu Reú, depois que gerou a Serugue, duzentos e sete anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'E viveu Serugue trinta anos, e gerou a Naor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'E viveu Serugue, depois que gerou a Naor, duzentos anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'E viveu Naor vinte e nove anos, e gerou a Terá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'E viveu Naor, depois que gerou a Terá, cento e dezenove anos, e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'E viveu Terá setenta anos, e gerou a Abrão, e a Naor, e a Harã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Estas são as gerações de Terá: Terá gerou a Abrão, e a Naor, e a Harã; e Harã gerou a Ló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'E morreu Harã antes que seu pai Terá na terra de seu nascimento, em Ur dos caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'E tomaram Abrão e Naor para si mulheres: o nome da mulher de Abrão foi Sarai, e o nome da mulher de Naor, Milca, filha de Harã, pai de Milca e de Iscá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Mas Sarai era estéril, e não tinha filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'E tomou Terá a Abrão seu filho, e a Ló filho de Harã, filho de seu filho, e a Sarai sua nora, mulher de Abrão seu filho: e saiu com eles de Ur dos caldeus, para ir à terra de Canaã: e vieram até Harã, e assentaram ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'E foram os dias de Terá duzentos e cinco anos; e morreu Terá em Harã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Porém o SENHOR disse a Abrão: Vai-te de tua terra e de tua parentela, e da casa de teu pai, à terra que te mostrarei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'E farei de ti uma grande nação, e te abençoarei, e engrandecerei teu nome, e serás bênção:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'E abençoarei aos que te abençoarem, e aos que te amaldiçoarem amaldiçoarei: e serão benditas em ti todas as famílias da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'E foi-se Abrão, como o SENHOR lhe disse; e foi com ele Ló: e era Abrão de idade de setenta e cinco anos quando saiu de Harã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'E tomou Abrão a Sarai sua mulher, e a Ló filho de seu irmão, e todos os seus pertences que haviam ganhado, e as almas que haviam adquirido em Harã, e saíram para ir à terra de Canaã; e à terra de Canaã chegaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'E passou Abrão por aquela terra até o lugar de Siquém, até o carvalho de Moré: e os cananeus estavam então na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'E apareceu o SENHOR a Abrão, e lhe disse: À tua descendência darei esta terra. E edificou ali um altar ao SENHOR, que lhe havia aparecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'E passou-se dali a um monte ao oriente de Betel, e estendeu sua tenda, tendo a Betel ao ocidente e Ai ao oriente: e edificou ali altar ao SENHOR e invocou o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'E moveu Abrão dali, caminhando e indo até o Sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'E houve fome na terra, e desceu Abrão ao Egito para peregrinar ali; porque era grande a fome na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'E aconteceu que quando estava para entrar no Egito, disse a Sarai sua mulher: Eis que, agora conheço que és mulher bela à vista;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'E será que quando te houverem visto os egípcios, dirão: Sua mulher é: e matarão a mim, e a ti te preservarão a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Agora, pois, dize que és minha irmã, para que eu vá bem por tua causa, e viva minha alma por causa de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'E aconteceu que, quando entrou Abrão no Egito, os egípcios viram a mulher que era bela em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Viram-na também os príncipes de Faraó, e a elogiaram; e foi levada a mulher a casa de Faraó:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'E fez bem a Abrão por causa dela; e teve ovelhas, e vacas, e asnos, e servos, e criadas, e asnas e camelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mas o SENHOR feriu a Faraó e à sua casa com grandes pragas, por causa de Sarai mulher de Abrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Então Faraó chamou a Abrão e lhe disse: Que é isto que fizeste comigo? Por que não me declaraste que era tua mulher?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Por que disseste: “É minha irmã”, pondo-me em risco de tomá-la para mim por mulher? Agora, pois, eis aqui tua mulher, toma-a e vai-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Então Faraó deu ordem a seus homens acerca de Abrão; e lhe acompanharam, e à sua mulher com tudo o que tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Subiu, pois, Abrão do Egito até o Sul de Canaã, ele e sua mulher, com tudo o que tinha, e com ele Ló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'E Abrão era riquíssimo em gado, em prata e ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'E voltou por suas jornadas da parte do Sul até Betel, até o lugar onde havia estado antes sua tenda entre Betel e Ai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Ao lugar do altar que havia feito ali antes: e invocou ali Abrão o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'E também Ló, que andava com Abrão, tinha ovelhas, e vacas, e tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'E a terra não os podia sustentar para que habitassem juntos; porque a riqueza deles era muita, e não podiam morar num mesmo lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'E houve briga entre os pastores do gado de Abrão e os pastores do gado de Ló: e os cananeus e os ferezeus habitavam então na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Então Abrão disse a Ló: Não haja agora briga entre mim e ti, entre meus pastores e os teus, porque somos irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Não está toda a terra diante de ti? Eu te rogo que te separes de mim. Se fores à esquerda, eu irei à direita: e se tu à direita, eu irei à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'E levantou Ló seus olhos, e viu toda a planície do Jordão, que toda ela era bem regada, antes que destruísse o SENHOR a Sodoma e a Gomorra, como o jardim do SENHOR, como a terra do Egito entrando em Zoar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Então Ló escolheu para si toda a planície do Jordão: e partiu-se Ló ao Oriente, e separaram-se um do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abrão assentou na terra de Canaã, e Ló assentou nas cidades da planície, e foi pondo suas tendas até Sodoma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Mas os homens de Sodoma eram maus e pecadores para com o SENHOR em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'E o SENHOR disse a Abrão, depois que Ló se separou dele: Levanta agora teus olhos, e olha desde o lugar onde estás até o norte, e ao sul, e ao oriente e ao ocidente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Porque toda a terra que vês, a darei a ti e à tua descendência para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'E farei tua descendência como o pó da terra: que se alguém puder contar o pó da terra, também tua descendência será contada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Levanta-te, vai pela terra ao longo dela e à sua largura; porque a ti a tenho de dar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Abrão, pois, removendo sua tenda, veio e morou nos carvalhos de Manre, que é em Hebrom, e edificou ali altar ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'E aconteceu nos dias de Anrafel, rei de Sinear, Arioque, rei de Elasar, Quedorlaomer, rei de Elão, e Tidal, rei de nações,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Que estes fizeram guerra contra Bera, rei de Sodoma, e contra Birsa, rei de Gomorra, e contra Sinabe, rei de Admá, e contra Semeber, rei de Zeboim, e contra o rei de Belá, a qual é Zoar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Todos estes se juntaram no vale de Sidim, que é o mar salgado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Doze anos haviam servido a Quedorlaomer, e ao décimo terceiro ano se rebelaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'E no ano décimo quarto veio Quedorlaomer, e os reis que estavam de sua parte, e derrotaram aos refains em Asterote-Carnaim, aos zuzins em Hã, e aos emins em Savé-Quiriataim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'E aos horeus no monte de Seir, até a El-Parã, que está junto ao deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'E voltaram e vieram a En-Mispate, que é Cades, e devastaram todas as terras dos amalequitas, e também aos amorreus, que habitavam em Hazazom-Tamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'E saiu o rei de Sodoma, e o rei de Gomorra, e o rei de Admá, e o rei de Zeboim, e o rei de Belá, que é Zoar, e ordenaram contra eles batalha no vale de Sidim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'A saber, contra Quedorlaomer, rei de Elão, e Tidal, rei de nações, e Anrafel, rei de Sinear, e Arioque, rei de Elasar; quatro reis contra cinco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'E o vale de Sidim estava cheio de poços de betume: e fugiram o rei de Sodoma e o de Gomorra, e caíram ali; e os demais fugiram ao monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'E tomaram toda a riqueza de Sodoma e de Gomorra, e todos os seus mantimentos, e se foram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Tomaram também Ló, filho do irmão de Abrão, que morava em Sodoma, e sua riqueza, e se foram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'E veio um dos que escaparam, e denunciou-o a Abrão o hebreu, que habitava no vale de Manre, amorreu, irmão de Escol e irmão de Aner, os quais tinham feito pacto com Abrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'E ouviu Abrão que seu irmão estava prisioneiro, e armou seus criados, os criados de sua casa, trezentos e dezoito, e seguiu-os até Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'E derramou-se sobre eles de noite ele e seus servos, e feriu-os, e foi os seguindo até Hobá, que está à esquerda de Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'E recuperou todos os bens, e também a Ló seu irmão e sua riqueza, e também as mulheres e gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'E saiu o rei de Sodoma a recebê-lo, quando voltava da derrota de Quedorlaomer e dos reis que com ele estavam, ao vale de Savé, que é o vale do Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Então Melquisedeque, rei de Salém, tirou pão e vinho; o qual era sacerdote do Deus altíssimo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'E abençoou-lhe, e disse: Bendito seja Abrão do Deus altíssimo, possuidor dos céus e da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'E bendito seja o Deus altíssimo, que entregou teus inimigos em tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Então o rei de Sodoma disse a Abrão: Dá-me as pessoas, e toma para ti a riqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'E respondeu Abrão ao rei de Sodoma: Levantei minha mão ao SENHOR Deus altíssimo, possuidor dos céus e da terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Que desde um fio até a correia de um calçado, nada tomarei de tudo o que é teu, para que não digas: Eu enriqueci a Abrão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Tirando somente o que os rapazes comeram, e a porção dos homens que foram comigo, Aner, Escol, e Manre; eles tomem a sua parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Depois destas coisas a palavra do SENHOR veio a Abrão em visão, dizendo: Não temas, Abrão; eu sou o teu escudo; a tua recompensa será muito grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abrão respondeu: Senhor DEUS, que me darás, sendo que não tenho filho, e o herdeiro da minha casa é Eliézer de Damasco?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Disse mais Abrão: Eis que não me deste descendência, e eis que meu herdeiro é um nascido em minha casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'E logo a palavra do SENHOR veio a ele dizendo: Não esse não herdará de ti, mas sim o que sairá de tuas entranhas será o que de ti herdará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'E tirou-lhe fora, e disse: Olha agora aos céus, e conta as estrelas, se as podes contar. E lhe disse: Assim será tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'E creu ao SENHOR, e contou-lhe por justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'E disse-lhe: Eu sou o SENHOR, que te tirei de Ur dos caldeus, para dar-te a herdar esta terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'E ele respondeu: Senhor DEUS, com que saberei que a vou herdar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'E lhe disse: Separa-me uma bezerra de três anos, e uma cabra de três anos, e um carneiro de três anos, uma rolinha também, e um pombinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'E tomou ele todas estas coisas, e partiu-as pela metade, e pôs cada metade uma em frente de outra; mas não partiu as aves.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'E desciam aves sobre os corpos mortos, e enxotava-as Abrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Mas ao pôr do sol veio o sono a Abrão, e eis que o pavor de uma grande escuridão caiu sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Então disse a Abrão: Tem certeza que a tua descendência será peregrina em terra que não é sua, e serão escravizados e afligidos por quatrocentos anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mas também a nação a quem servirão, eu julgarei; e depois disto sairão com grande riqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Tu, porém, virás aos teus pais em paz, e serás sepultado em boa velhice.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'E na quarta geração voltarão para cá; porque ainda não está completa a maldade dos amorreus até aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'E sucedeu que, depois de posto o sol, e já estando escuro, apareceu um fogo fumegando, e uma tocha de fogo que passou por entre os animais divididos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Naquele dia fez o SENHOR um pacto com Abrão dizendo: À tua descendência darei esta terra desde o rio do Egito até o rio grande, o rio Eufrates;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Os queneus, e os quenezeus, e os cadmoneus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'E os heteus, e os perizeus, e os refains,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'E os amorreus, e os cananeus, e os girgaseus, e os jebuseus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'E Sarai, mulher de Abrão não lhe dava filho: e ela tinha uma serva egípcia, que se chamava Agar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Disse, pois, Sarai a Abrão: Já vês que o SENHOR me fez estéril: rogo-te que entres a minha serva; talvez terei filhos dela. E atendeu Abrão ao dito de Sarai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'E Sarai, mulher de Abrão, tomou a Agar sua serva egípcia, ao fim de dez anos que havia habitado Abrão na terra de Canaã, e deu-a a Abrão seu marido por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'E ele se deitou com Agar, a qual concebeu: e quando viu que havia concebido, olhava com desprezo à sua senhora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Então Sarai disse a Abrão: Minha afronta seja sobre ti; eu pus minha serva em teus braços, e vendo-se grávida, me olha com desprezo; julgue o SENHOR entre mim e ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'E respondeu Abrão a Sarai: Eis aí tua serva em tua mão, faze com ela o que bem te parecer. E quando Sarai a afligiu, fugiu de sua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'E o anjo do SENHOR a achou junto a uma fonte de água no deserto, junto à fonte que está no caminho de Sur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'E lhe disse: Agar, serva de Sarai, de onde vens tu, e para onde vais? E ela respondeu: Fujo de diante de Sarai, minha senhora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'E disse-lhe o anjo do SENHOR: Volta à tua senhora, e põe-te submissa sob a mão dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Disse-lhe também o anjo do SENHOR: Multiplicarei tanto tua linhagem, que não será contada por causa da multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Disse-lhe ainda o anjo do SENHOR: Eis que concebeste, e darás à luz um filho, e chamarás seu nome Ismael, porque o SENHOR ouviu a tua aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'E ele será homem como um jumento selvagem; sua mão será contra todos, as mãos de todos serão contra ele, e habitará à margem de todos os seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Então chamou o nome do SENHOR que com ela falava: Tu és o Deus da vista; porque disse: Não vi também aqui ao que me vê?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Pelo qual chamou ao poço, Poço do Vivente que me vê. Eis que está entre Cades e Berede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'E Agar deu à luz um filho a Abrão, e Abrão chamou o nome do seu filho que Agar lhe deu à luz Ismael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'E era Abrão de idade de oitenta e seis anos, quando deu à luz Agar a Ismael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Quando Abrão tinha a idade de noventa e nove anos, o SENHOR lhe apareceu, e disse-lhe: Eu sou o Deus Todo-Poderoso; anda diante de mim, e sê íntegro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'E constituirei meu pacto entre mim e ti, e te multiplicarei em grandíssima maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Então Abrão prostrou-se com o rosto ao chão, e Deus falou com ele, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Quanto a mim, este é o meu pacto contigo: Serás pai de multidão de nações:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'E não se chamará mais teu nome Abrão, mas sim que será teu nome Abraão, porque te pus por pai de multidão de nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'E te multiplicarei muito em grande maneira, e te porei em nações, e reis sairão de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'E estabelecerei meu pacto entre mim e ti, e tua descendência depois de ti em suas gerações, por aliança perpétua, para ser para ti por Deus, e à tua descendência depois de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'E darei a ti, e à tua descendência depois de ti, a terra de tuas peregrinações, toda a terra de Canaã em herança perpétua; e serei o Deus deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Disse de novo Deus a Abraão: Tu, porém, guardarás meu pacto, tu e tua descendência depois de ti por suas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Este será meu pacto, que guardareis entre mim e vós e tua descendência depois de ti: Será circuncidado todo macho dentre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Circuncidareis, pois, a carne de vosso prepúcio, e será por sinal do pacto entre mim e vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'E de idade de oito dias será circuncidado todo macho entre vós por vossas gerações: o nascido em casa, e o comprado a dinheiro de qualquer estrangeiro, que não for de tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Deve ser circuncidado o nascido em tua casa, e o comprado por teu dinheiro: e estará meu pacto em vossa carne para aliança perpétua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'E o macho incircunciso que não houver circuncidado a carne de seu prepúcio, aquela pessoa será exterminada de seu povo; violou meu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Disse também Deus a Abraão: A Sarai tua mulher não a chamarás Sarai, mas Sara será seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'E a abençoarei, e também te darei dela filho; sim, a abençoarei, e virá a ser mãe de nações; dela surgirão reis de povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Então Abraão postrou-se com o rosto ao chão, riu, e disse em seu coração: A um homem de cem anos nasceráfilho? E Sara, já de noventa anos, há de dar à luz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'E disse Abraão a Deus: Que Ismael viva diante de ti!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'E respondeu Deus: Certamente Sara tua mulher te dará à luz um filho, e chamarás seu nome Isaque; e confirmarei meu pacto com ele por aliança perpétua para sua descendência depois dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'E quanto a Ismael, também te ouvi; eis que o abençoarei, e lhe farei frutificar e multiplicar em grandíssima maneira; doze príncipes gerará, e dele farei grande nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mas meu pacto estabelecerei com Isaque, ao qual Sara te dará à luz por este tempo no ano seguinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'E acabou de falar com ele, e Deus subiu da presença de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Então tomou Abraão a Ismael seu filho, e a todos os servos nascidos em sua casa, e a todos os comprados por seu dinheiro, a todo homem entre os domésticos da casa de Abraão, e circuncidou a carne do prepúcio deles naquele mesmo dia, como Deus lhe havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Era Abraão de idade de noventa e nove anos quando circuncidou a carne de seu prepúcio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'E Ismael seu filho era de treze anos quando foi circuncidada a carne de seu prepúcio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'No mesmo dia foi circuncidado Abraão e Ismael seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'E todos os homens de sua casa, o servo nascido em casa, e o comprado por dinheiro do estrangeiro, foram circuncidados com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'E apareceu-lhe o SENHOR nos carvalhos de Manre, estando ele sentado à porta de sua tenda no calor do dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'E levantou seus olhos e olhou, e eis que três homens que estavam junto a ele: e quando os viu, saiu correndo da porta de sua tenda a recebê-los, e inclinou-se até a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'E disse: Senhor, se agora achei favor aos teus olhos, rogo-te que não passes de teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Que se traga agora um pouco de água, e lavai vossos pés; e recostai-vos debaixo de uma árvore,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'E trarei um bocado de pão, e confortai vosso coração; depois passareis; pois por isso passastes perto de vosso servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Então Abraão foi depressa à tenda a Sara, e lhe disse: Toma logo três medidas de flor de farinha, amassa e faze pães cozidos debaixo das cinzas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'E correu Abraão às vacas, e tomou um bezerro tenro e bom, e deu-o ao jovem, e deu-se este pressa a prepará-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Tomou também manteiga e leite, e o bezerro que havia preparado, e o pôs diante deles; e ele estava junto a eles debaixo da árvore; e comeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'E lhe disseram: Onde está Sara tua mulher? E ele respondeu: Aqui na tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Então disse: De certo voltarei a ti segundo o tempo da vida, e eis que Sara, tua mulher, terá um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraão e Sara eram idosos, avançados em dias; a Sara já havia cessado o costume das mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Riu, pois, Sara consigo mesma, dizendo: Depois que envelheci terei prazer, sendo também meu senhor já velho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Então o SENHOR disse a Abraão: Por que Sara riu dizendo: Será verdade que darei à luz, sendo já velha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Há para Deus alguma coisa difícil? Ao tempo assinalado voltarei a ti, segundo o tempo da vida, e Sara terá um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Então Sara negou dizendo: Não ri; pois teve medo. Mas ele disse: Não é assim, mas riste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'E os homens se levantaram dali, e olharam até Sodoma: e Abraão ia com eles acompanhando-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'E o SENHOR disse: Encobrirei eu a Abraão o que vou a fazer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Havendo de ser Abraão em uma nação grande e forte, e havendo de ser benditas nele todas as nações da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Porque eu o conheci, sei que mandará a seus filhos e a sua casa depois de si, que guardem o caminho do SENHOR, fazendo justiça e juízo, para que faça vir o SENHOR sobre Abraão o que falou acerca dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Então o SENHOR lhe disse: Porquanto o clamor de Sodoma e Gomorra se aumenta mais e mais, e o pecado deles se agravou em extremo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Descerei agora, e verei se consumaram sua obra segundo o clamor que veio até mim; e se não, eu o saberei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'E apartaram-se dali os homens, e foram até Sodoma: mas Abraão estava ainda diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'E aproximou-se Abraão e disse: Destruirás também ao justo com o ímpio?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Talvez haja cinquenta justos dentro da cidade: destruirás também e não perdoarás ao lugar por cinquenta justos que estejam dentro dela?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Longe de ti o fazer tal, que faças morrer ao justo com o ímpio e que seja o justo tratado como o ímpio; nunca faças tal. O juiz de toda a terra, não há de fazer o que é justo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Então respondeu o SENHOR: Se achar em Sodoma cinquenta justos dentro da cidade, perdoarei a todo este lugar por causa deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'E Abraão replicou e disse: Eis que agora que comecei a falar a meu Senhor, ainda que sou pó e cinza:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Talvez faltem de cinquenta justos cinco; destruirás por aqueles cinco toda a cidade? E disse: Não a destruirei, se achar ali quarenta e cinco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'E voltou a falar-lhe, e disse: Talvez se acharão ali quarenta. E respondeu: Não o farei por causa dos quarenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'E disse: Não se ire agora meu Senhor, se falar: talvez se achem ali trinta. E respondeu: Não o farei se achar ali trinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'E disse: Eis que agora que me empreendi em falar a meu Senhor: talvez se achem ali vinte. Não a destruirei, respondeu, por causa dos vinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'E voltou a dizer: Não se ire agora meu Senhor, se falar somente uma vez: talvez se achem ali dez. Não a destruirei, respondeu, por causa dos dez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'E foi-se o SENHOR, logo que acabou de falar a Abraão: e Abraão se voltou a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Chegaram, pois, os dois anjos a Sodoma ao cair da tarde; e Ló estava sentado à porta de Sodoma. E vendo-os Ló, levantou-se a recebê-los, e inclinou-se até o chão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'E disse: Agora, pois, meus senhores, vos rogo que venhais à casa de vosso servo e vos hospedeis, e lavareis vossos pés: e pela manhã vos levantareis, e seguireis vosso caminho. E eles responderam: Não, que na praça nos ficaremos esta noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mas ele insistiu com eles muito, e se vieram com ele, e entraram em sua casa; e fez-lhes banquete, e cozeu pães sem levedura e comeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'E antes que se deitassem, cercaram a casa os homens da cidade, os homens de Sodoma, todo o povo junto, desde o mais jovem até o mais velho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'E chamaram a Ló, e lhe disseram: Onde estão os homens que vieram a ti esta noite? tira-os a nós, para que os conheçamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Então Ló saiu a eles à porta, e fechou as portas atrás de si,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'E disse: Eu vos rogo, meus irmãos, que não façais tal maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Eis aqui agora eu tenho duas filhas que não conheceram homem; eu as tirarei fora para vós, e fazei delas como bem vos parecer: somente a estes homens não façais nada, pois que vieram à sombra de meu telhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'E eles responderam: Sai daí: e acrescentaram: Veio este aqui para habitar como um estrangeiro, e haverá de levantar-se como juiz? Agora te faremos mais mal que a eles. E faziam grande violência ao homem, a Ló, e se aproximaram para romper as portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Então os homens estenderam a mão, e meteram a Ló em casa com eles, e fecharam as portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'E aos homens que estavam à porta da casa desde o menor até o maior, feriram com cegueira; mas eles se cansavam tentando achar a porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'E disseram os homens a Ló: Tens aqui alguém mais? Genros, e teus filhos e tuas filhas, e tudo o que tens na cidade, tira-o deste lugar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Porque vamos destruir este lugar, porquanto o clamor deles subiu demais diante do SENHOR; portanto o SENHOR nos enviou para destruí-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Então saiu Ló, e falou a seus genros, os que haviam de se casar com suas filhas, e lhes disse: Levantai-vos, saí deste lugar; porque o SENHOR vai destruir esta cidade. Mas pareceu a seus genros como que se ridicularizava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'E ao raiar a alva, os anjos davam pressa a Ló, dizendo: Levanta-te, toma tua mulher, e teus dois filhas que se acham aqui, para que não pereças no castigo da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'E demorando-se ele, os homens pegaram por sua mão, e pela mão de sua mulher, e pelas mãos de suas duas filhas segundo a misericórdia do SENHOR para com ele; e o tiraram, e o puseram fora da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'E foi que quando os tirou fora, disse: Escapa por tua vida; não olhes atrás de ti, nem pares toda esta planície; escapa ao monte, não seja que pereças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'E Ló lhes disse: Não, eu vos rogo, senhores meus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Eis que agora achou teu servo favor em teus olhos, e engrandeceste tua misericórdia que fizeste comigo dando-me a vida; mas eu não poderei escapar ao monte, não seja caso que me alcance o mal e morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Eis que agora esta cidade está próxima para fugir ali, a qual é pequena; escaparei agora ali, (não é ela pequena?) e viverá minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'E lhe respondeu: Eis que recebi também tua súplica sobre isto, e não destruirei a cidade de que falaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Apressa-te, escapa-te ali; porque nada poderei fazer até que ali tenhas chegado. Por isto foi chamado o nome da cidade, Zoar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'O sol saía sobre a terra, quando Ló chegou a Zoar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Então choveu o SENHOR sobre Sodoma e sobre Gomorra enxofre e fogo da parte do SENHOR desde os céus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'E destruiu as cidades, e toda aquela planície, com todos os moradores daquelas cidades, e o fruto da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Então a mulher de Ló olhou atrás, às costas dele, e se tornou estátua de sai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'E subiu Abraão pela manhã ao lugar onde havia estado diante do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'E olhou até Sodoma e Gomorra, e até toda a terra daquela planície olhou; e eis que a fumaça subia da terra como a fumaça de um forno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Assim foi que, quando destruiu Deus as cidades da planície, lembrou-se Deus de Abraão, e enviou fora a Ló do meio da destruição, ao assolar as cidades onde Ló estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Porém Ló subiu de Zoar, e assentou no monte, e suas duas filhas com ele; porque teve medo de ficar em Zoar, e se abrigou em uma caverna ele e suas duas filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Então a maior disse à menor: Nosso pai é velho, e não resta homem na terra que entre a nós conforme o costume de toda a terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Vem, demos a beber vinho a nosso pai, e durmamos com ele, e conservaremos de nosso pai geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'E deram a beber vinho a seu pai aquela noite: e entrou a maior, e dormiu com seu pai; mas ele não sentiu quando se deitou com ela nem quando se levantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'O dia seguinte disse a maior à menor: Eis que eu dormi a noite passada com meu pai; demos a ele de beber vinho também esta noite, e entra e dorme com ele, para que conservemos de nosso pai geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'E deram a beber vinho a seu pai também aquela noite: e levantou-se a menor, e dormiu com ele; mas não conseguiu perceber quando se deitou com ela, nem quando se levantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'E conceberam as duas filhas de Ló, de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'E deu à luz a maior um filho, e chamou seu nome Moabe, o qual é pai dos moabitas até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'A menor também deu à luz um filho, e chamou seu nome Ben-Ami, o qual é pai dos amonitas até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'De ali partiu Abraão à terra do Sul, e assentou entre Cades e Sur, e habitou como peregrino em Gerar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'E disse Abraão de Sara sua mulher: É minha irmã. E Abimeleque, rei de Gerar, enviou e tomou a Sara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Porém Deus veio a Abimeleque em sonhos de noite, e lhe disse: Eis que morto és por causa da mulher que tomaste, a qual é casada com marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Mas Abimeleque não havia chegado a ela, e disse: Senhor, matarás também a gente justa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Não me disse ele: É minha irmã; e ela também disse: É meu irmão? Com sinceridade de meu coração, e com limpeza de minhas mãos fiz isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'E disse-lhe Deus em sonhos: Eu também sei que com integridade de teu coração fizeste isto; e eu também te detive de pecar contra mim, e assim não te permiti que a tocasses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Agora, pois, devolve a mulher a seu marido; porque é profeta, e orará por ti, e viverás. E se tu não a devolveres, sabe que certamente morrerás, com tudo o que for teu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Então Abimeleque se levantou de manhã, e chamou a todos os seus servos, e disse todas estas palavras aos ouvidos deles; e temeram os homens em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Depois chamou Abimeleque a Abraão e lhe disse: Que nos fizeste? e em que pequei eu contra ti, que atraíste sobre mim e sobre meu reino tão grande pecado? o que não devias fazer fizeste comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'E disse mais Abimeleque a Abraão: Que viste para que fizesses isto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'E Abraão respondeu: Porque disse para mim: Certamente não há temor de Deus neste lugar, e me matarão por causa de minha mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'E na verdade também é minha irmã, filha de meu pai, mas não filha de minha mãe, e tomei-a por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'E foi que, quando Deus me fez sair sem rumo da casa de meu pai, eu lhe disse: Esta é a lealdade que tu me farás, que em todos os lugares onde chegarmos, digas de mim: É meu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Então Abimeleque tomou ovelhas e vacas, e servos e servas, e deu-o a Abraão, e devolveu-lhe a Sara sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'E disse Abimeleque: Eis que minha terra está diante de ti, habita onde bem te parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'E a Sara disse: Eis que dei mil moedas de prata a teu irmão; olha que ele te é por véu de olhos para todos os que estão contigo, e para com todos: assim foi repreendida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Então Abraão orou a Deus; e Deus sanou a Abimeleque e a sua mulher, e a suas servas, e voltaram a ter filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Porque havia por completo fechado o SENHOR toda madre da casa de Abimeleque, por causa de Sara, mulher de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'E o SENHOR visitou Sara, como disse, e o SENHOR fez com Sara como havia falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'E concebeu e deu à luz Sara a Abraão um filho em sua velhice, no tempo que Deus lhe havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'E chamou Abraão o nome de seu filho que lhe nasceu, que lhe deu à luz Sara, Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'E circuncidou Abraão a seu filho Isaque de oito dias, como Deus lhe havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'E era Abraão de cem anos, quando lhe nasceu Isaque seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Então disse Sara: Deus me fez rir, e qualquer um que o ouvir, se rirá comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'E acrescentou: Quem diria a Abraão que Sara havia de dar de mamar a filhos? pois que lhe dei um filho em sua velhice.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'E cresceu o menino, e foi desmamado; e fez Abraão grande banquete no dia que foi desmamado Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'E viu Sara ao filho de Agar a egípcia, o qual havia esta dado a Abraão, que o ridicularizava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Portanto disse a Abraão: Expulsa a esta serva e a seu filho; que o filho desta serva não herdará com meu filho, com Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Este dito pareceu grave em grande maneira a Abraão por causa de seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Então disse Deus a Abraão: Não te pareça grave por causa do jovem e de tua serva; em tudo o que te disser Sara, ouve sua voz, porque em Isaque será chamada tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'E também do filho da serva farei nação, porque é descendência tua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Então Abraão se levantou manhã muito cedo, e tomou pão, e um odre de água, e deu-o a Agar, pondo-o sobre seu ombro, e entregou-lhe o jovem, e despediu-a. E ela partiu, e andava errante pelo deserto de Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'E faltou a água do odre, e deitou ao jovem debaixo de uma árvore;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'E foi-se e sentou-se em frente, afastando-se como um tiro de arco; porque dizia: Não verei quando o jovem morrer: e sentou-se em frente, e levantou sua voz e chorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'E ouviu Deus a voz do jovem; e o anjo de Deus chamou a Agar desde o céu, e lhe disse: Que tens, Agar? Não temas; porque Deus ouviu a voz do jovem onde está.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Levanta-te, ergue ao jovem, e pegue-o por tua mão, porque farei dele uma grande nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Então abriu Deus os olhos dela, e ela viu uma fonte de água; e foi, e encheu o odre de água, e deu de beber ao jovem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'E foi Deus com o jovem; e cresceu, e habitou no deserto, e foi atirador de arco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'E habitou no deserto de Parã; e sua mãe lhe tomou mulher da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'E aconteceu naquele mesmo tempo que falou Abimeleque, e Ficol, príncipe de seu exército, a Abraão dizendo: Deus é contigo em tudo quanto fazes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Agora, pois, jura-me aqui por Deus, que não tratarás com falsidade a mim, nem a meu filho, nem a meu neto; mas sim que conforme a bondade que eu fiz contigo, farás tu comigo e com a terra onde peregrinaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'E respondeu Abraão: Eu jurarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'E Abraão reclamou com Abimeleque por causa de um poço de água, que os servos de Abimeleque lhe haviam tirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'E respondeu Abimeleque: Não sei quem tenha feito isto, nem tampouco tu me fizeste saber, nem eu o ouvi até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'E tomou Abraão ovelhas e vacas, e deu a Abimeleque; e fizeram ambos aliança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'E pôs Abraão sete cordeiras do rebanho à parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'E disse Abimeleque a Abraão: Que significam essas sete cordeiras que puseste à parte?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'E ele respondeu: Que estas sete cordeiras tomarás de minha mão, para que me sejam em testemunho de que eu cavei este poço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Por isto chamou a aquele lugar Berseba; porque ali ambos juraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Assim fizeram aliança em Berseba: e levantaram-se Abimeleque e Ficol, príncipe de seu exército, e se voltaram à terra dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'E plantou Abraão um bosque em Berseba, e invocou ali o nome do SENHOR Deus eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'E morou Abraão na terra dos filisteus por muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'E aconteceu depois destas coisas, que provou Deus a Abraão, e lhe disse: Abraão. E ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'E disse: Toma agora teu filho, teu único, Isaque, a quem amas, e vai-te à terra de Moriá, e oferece-o ali em holocausto sobre um dos montes que eu te direi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'E Abraão se levantou manhã muito cedo, e preparou seu asno, e tomou consigo dois servos seus, e a Isaque seu filho: e cortou lenha para o holocausto, e levantou-se, e foi ao lugar que Deus lhe disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Ao terceiro dia levantou Abraão seus olhos, e viu o lugar de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Então disse Abraão a seus servos: Esperai aqui com o asno, e eu e o jovem iremos até ali, e adoraremos, e voltaremos a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'E tomou Abraão a lenha do holocausto, e a pôs sobre Isaque seu filho: e ele tomou em sua mão o fogo e a espada; e foram ambos juntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Então falou Isaque a Abraão seu pai, e disse: Meu pai. e ele respondeu: Eis-me aqui, meu filho. E ele disse: Eis aqui o fogo e a lenha; mas onde está o cordeiro para o holocausto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'E respondeu Abraão: Deus se proverá de cordeiro para o holocausto, filho meu. E iam juntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'E quando chegaram ao lugar que Deus lhe havia dito, edificou ali Abraão um altar, e compôs a lenha, e amarrou a Isaque seu filho, e pôs-lhe no altar sobre a lenha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'E estendeu Abraão sua mão, e tomou a espada, para degolar a seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Então o anjo do SENHOR lhe gritou do céu, e disse: Abraão, Abraão. E ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'E disse: Não estendas tua mão sobre o jovem, nem lhe faças nada; que já conheço que temes a Deus, pois que não me recusaste o teu filho, o teu único;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Então levantou Abraão seus olhos, e olhou, e eis um carneiro a suas costas preso em um arbusto por seus chifres: e foi Abraão, e tomou o carneiro, e ofereceu-lhe em holocausto em lugar de seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'E chamou Abraão o nome daquele lugar, O SENHOR proverá. Portanto se diz hoje: No monte do SENHOR se proverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'E chamou o anjo do SENHOR a Abraão segunda vez desde o céu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'E disse: Por mim mesmo jurei, diz o SENHOR, que porquanto fizeste isto, e não me recusaste teu filho, teu único;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'certamente te abençoarei, e multiplicarei tua descendência como as estrelas do céu, e como a areia que está na beira do mar; e tua descendência possuirá as portas de seus inimigos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Em tua descendência serão abençoadas todas as nações da terra, porquanto obedeceste à minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'E voltou Abraão a seus servos, e levantaram-se e se foram juntos a Berseba; e habitou Abraão em Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'E aconteceu depois destas coisas, que foi dada notícia a Abraão, dizendo: Eis que também Milca havia dado à luz filhos a Naor teu irmão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'A Uz seu primogênito, e a Buz seu irmão, e a Quemuel pai de Arã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'E a Quésede, e a Hazo, e a Pildas, e a Jidlafe, e a Betuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'E Betuel gerou a Rebeca. Estes oito deu à luz Milca a Naor, irmão de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'E sua concubina, que se chamava Reumá, deu à luz também a Tebá, e a Gaã, e a Taás, e a Maaca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'E foi a vida de Sara cento e vinte e sete anos; estes foram os anos da vida de Sara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'E morreu Sara em Quiriate-Arba, que é Hebrom, na terra de Canaã; e Abraão veio para ficar de luto por Sara e para chorar por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'E levantou-se Abraão de diante de sua morta, e falou aos filhos de Hete, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Peregrino e estrangeiro sou entre vós; dá-me propriedade de sepultura convosco, e sepultarei minha falecida de diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'E responderam os filhos de Hete a Abraão, e disseram-lhe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Ouve-nos, senhor meu, és um príncipe de Deus entre nós; no melhor de nossas sepulturas sepulta a tua falecida; nenhum de nós te impedirá sua sepultura, para que enterres tua falecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'E Abraão se levantou, e inclinou-se ao povo daquela terra, aos filhos de Hete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'E falou com eles, dizendo: Se queres que eu sepulte minha falecida de diante de mim, ouvi-me, e intercedei por mim com Efrom, filho de Zoar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Para que me dê a caverna de Macpela, que tem na extremidade de sua propriedade: que por seu justo preço a dê a mim, para possessão de sepultura em meio de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Este Efrom achava-se entre os filhos de Hete: e respondeu Efrom Heteu a Abraão, aos ouvidos dos filhos de Hete, de todos os que entravam pela porta de sua cidade, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Não, senhor meu, ouve-me: eu te dou a propriedade, e te dou também a caverna que está nela; diante dos filhos de meu povo a dou a ti; sepulta tua falecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'E Abraão se inclinou diante do povo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'E respondeu a Efrom aos ouvidos do povo da terra, dizendo: Antes, se for do teu agrado, rogo-te que me ouças; eu darei o preço da propriedade, toma-o de mim, e sepultarei nela minha falecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'E respondeu Efrom a Abraão, dizendo-lhe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Senhor meu, escuta-me: a terra vale quatrocentos siclos de prata: que é isto entre mim e ti? Enterra, pois, tua falecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Então Abraão concordou com Efrom, e pesou Abraão a Efrom o dinheiro que disse, ouvindo-o os filhos de Hete, quatrocentos siclos de prata, de acordo com o padrão dos mercadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'E ficou a propriedade de Efrom que estava em Macpela em frente de Manre, a propriedade e a caverna que estava nela, e todas as árvores que havia na herança, e em todo o seu termo ao derredor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Para Abraão em possessão, à vista dos filhos de Hete, e de todos os que entravam pela porta da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'E depois disto sepultou Abraão a Sara, sua mulher, na caverna da propriedade de Macpela em frente de Manre, que é Hebrom na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'E ficou a propriedade e a caverna que nela havia, para Abraão, em possessão de sepultura adquirida dos filhos de Hete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'E Abraão era velho, e cheio de dias; e o SENHOR havia abençoado a Abraão em tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'E disse Abraão a um criado seu, o mais velho de sua casa, que era o que governava em tudo o que tinha: Põe agora tua mão debaixo de minha coxa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'E te juramentarei pelo SENHOR, Deus dos céus e Deus da terra, que não tomarás mulher para meu filho das filhas dos cananeus, entre os quais eu habito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Em vez disso irás à minha terra e à minha parentela, e tomarás mulher para meu filho Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'E o criado lhe respondeu: Talvez a mulher não queira vir atrás de mim a esta terra; farei voltar, pois, teu filho à terra de onde saíste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'E Abraão lhe disse: Guarda-te que não faças voltar a meu filho ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'O SENHOR, Deus dos céus, que me tomou da casa de meu pai e da terra de minha parentela, e me falou e me jurou, dizendo: À tua descendência darei esta terra; ele enviará seu anjo diante de ti, e tu tomarás dali mulher para meu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'E se a mulher não quiser vir atrás de ti, serás livre deste meu juramento; somente que não faças voltar ali a meu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Então o criado pôs sua mão debaixo da coxa de Abraão seu senhor, e jurou-lhe sobre este negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'E o criado tomou dez camelos dos camelos de seu senhor, e foi-se, pois tinha à sua disposição todos os bens de seu senhor: e posto em caminho, chegou à Mesopotâmia, à cidade de Naor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'E fez ajoelhar os camelos fora da cidade, junto a um poço de água, à hora da tarde, à hora em que saem as moças por água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'E disse: SENHOR, Deus de meu senhor Abraão, dá-me, te rogo, o ter hoje bom encontro, e faze misericórdia com meu senhor Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Eis que eu estou junto à fonte de água, e as filhas dos homens desta cidade saem por água:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Seja, pois, que a moça a quem eu disser: Baixa teu cântaro, te rogo, para que eu beba; e ela responder: Bebe, e também darei de beber a teus camelos: que seja esta a que tu destinaste para teu servo Isaque; e nisto conhecerei que haverás feito misericórdia com meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'E aconteceu que antes que ele acabasse de falar, eis que Rebeca, que havia nascido a Betuel, filho de Milca, mulher de Naor irmão de Abraão, a qual saía com seu cântaro sobre seu ombro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'E a moça era de muito belo aspecto, virgem, à que homem não havia conhecido; a qual desceu à fonte, e encheu seu cântaro, e se voltava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Então o criado correu até ela, e disse: Rogo-te que me dês a beber um pouco de água de teu cântaro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'E ela respondeu: Bebe, meu senhor; e apressou-se a baixar seu cântaro sobre sua mão, e lhe deu a beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'E quando acabou de dar-lhe de beber, disse: Também para teus camelos tirarei água, até que acabem de beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'E apressou-se, e esvaziou seu cântaro no bebedouro, e correu outra vez ao poço para tirar água, e tirou para todos os seus camelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'E o homem estava maravilhado dela, permanecendo calado, para saber se o SENHOR havia prosperado ou não sua viagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'E foi que quando os camelos acabaram de beber, presenteou-lhe o homem um pendente de ouro que pesava meio siclo, e dois braceletes que pesavam dez;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'E disse: De quem és filha? Rogo-te me digas, há lugar em casa de teu pai onde possamos passar a noite?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'E ela respondeu: Sou filha de Betuel, filho de Milca, o qual deu à luz ela a Naor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'E acrescentou: Também há em nossa casa palha e muita forragem, e lugar para passar a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'O homem então se inclinou, e adorou ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'E disse: Bendito seja o SENHOR, Deus de meu senhor Abraão, que não afastou sua misericórdia e sua verdade de meu senhor, guiando-me o SENHOR no caminho à casa dos irmãos de meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'E a moça correu, e fez saber na casa de sua mãe estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'E Rebeca tinha um irmão que se chamava Labão, o qual correu fora ao homem, à fonte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'E foi que quando viu o pendente e os braceletes nas mãos de sua irmã, que dizia, Assim me falou aquele homem; veio a ele: e eis que estava junto aos camelos à fonte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'E disse-lhe: Vem, bendito do SENHOR; por que estás fora? eu limpei a casa, e o lugar para os camelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Então o homem veio à casa, e Labão desatou os camelos; e deu-lhes palha e forragem, e água para lavar os pés dele, e os pés dos homens que com ele vinham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'E puseram diante dele comida; mas ele disse: Não comerei até que tenha dito minha mensagem. E ele lhe disse: Fala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Então disse: Eu sou criado de Abraão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'E o SENHOR abençoou muito a meu senhor, e ele se engrandeceu: e lhe deu ovelhas e vacas, prata e ouro, servos e servas, camelos e asnos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'E Sara, mulher de meu senhor, deu à luz em sua velhice um filho a meu senhor, quem lhe deu tudo quanto tem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'E meu senhor me fez jurar, dizendo: Não tomarás mulher para meu filho das filhas dos cananeus, em cuja terra habito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Em vez disso irás à casa de meu pai, e à minha parentela, e tomarás mulher para meu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'E eu disse: Talvez a mulher não queira me seguir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Então ele me respondeu: O SENHOR, em cuja presença tenho andado, enviará seu anjo contigo, e fará teu caminho ser bem-sucedido; e tomarás mulher para meu filho de minha linhagem e da casa de meu pai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Então serás livre de meu juramento, quando houveres chegado à minha linhagem; e se não a derem a ti, serás livre de meu juramento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Cheguei, pois, hoje à fonte, e disse: SENHOR, Deus de meu senhor Abraão, se tu fazes bem-sucedido agora meu caminho pelo qual ando;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Eis que eu estou junto à fonte de água; seja, pois, que a virgem que sair por água, à qual disser: Dá-me de beber, te rogo, um pouco de água de teu cântaro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'E ela me responder, Bebe tu, e também para teus camelos tirarei água: esta seja a mulher que destinou o SENHOR para o filho de meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'E antes que acabasse de falar em meu coração, eis que Rebeca saía com seu cântaro sobre seu ombro; e desceu à fonte, e tirou água; e lhe disse: Rogo-te que me dês de beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'E prontamente baixou seu cântaro de cima de si, e disse: Bebe, e também a teus camelos darei a beber. E bebi, e deu também de beber a meus camelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Então lhe perguntei, e disse: De quem és filha? E ela respondeu: Filha de Betuel, filho de Naor, que Milca lhe deu. Então pus nela um pendente sobre seu nariz, e braceletes sobre suas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'E inclinei-me, e adorei ao SENHOR, e bendisse ao SENHOR, Deus de meu senhor Abraão, que me havia guiado pelo caminho de verdade para tomar a filha do irmão de meu senhor para seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Agora, pois, se vós fazeis misericórdia e verdade com meu senhor, declarai-o a mim; e se não, declarai-o a mim; e irei embora à direita ou à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Então Labão e Betuel responderam e disseram: Do SENHOR saiu isto; não podemos falar-te mal nem bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Eis aí Rebeca diante de ti; toma-a e vai-te, e seja mulher do filho de teu senhor, como o disse o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'E foi, que quando o criado de Abraão ouviu suas palavras, inclinou-se à terra ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'E o criado tirou objetos de prata, objetos de ouro e roupas, e deu a Rebeca: também deu coisas preciosas a seu irmão e a sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'E comeram e beberam ele e os homens que vinham com ele, e dormiram; e levantando-se de manhã, disse: Autorizai-me voltar a meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Então respondeu seu irmão e sua mãe: Espere a moça conosco ao menos dez dias, e depois irá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'E ele lhes disse: Não me detenhais, pois que o SENHOR fez prosperar meu caminho; despede-me para que me vá a meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Eles responderam então: Chamemos a moça e perguntemos a ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'E chamaram a Rebeca, e disseram-lhe: Irás tu com este homem? E ela respondeu: Sim, irei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Então deixaram ir a Rebeca sua irmã, e à sua criada, e ao criado de Abraão e a seus homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'E abençoaram a Rebeca, e disseram-lhe: És nossa irmã; sejas em milhares de milhares, e tua geração possua a porta de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Levantou-se então Rebeca e suas moças, e subiram sobre os camelos, e seguiram ao homem; e o criado tomou a Rebeca, e foi embora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'E vinha Isaque do poço do Vivente que me vê; porque ele habitava na terra do Sul;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'E havia saído Isaque a orar ao campo, à hora da tarde; e levantando seus olhos, olhou, e eis os camelos que vinham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebeca também levantou seus olhos, e viu a Isaque, e desceu do camelo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Porque havia perguntado ao criado: Quem é este homem que vem pelo campo até nós? E o servo havia respondido: Este é meu senhor. Ela então tomou o véu, e cobriu-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Então o criado contou a Isaque tudo o que havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'E trouxe-a Isaque à tenda de sua mãe Sara, e tomou a Rebeca por mulher; e amou-a: e consolou-se Isaque depois da morte de sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'E Abraão tomou outra mulher, cujo nome foi Quetura;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'A qual lhe deu à luz a Zinrã, e a Jocsã, e a Medã, e a Midiã, e a Jisbaque, e a Suá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'E Jocsã gerou a Seba, e a Dedã: e filhos de Dedã foram Assurim, e Letusim, e Leummim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'E filhos de Midiã: Efá, e Efer, e Enoque, e Abida, e Elda. Todos estes foram filhos de Quetura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Mas Abraão deu tudo quanto tinha a Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'E aos filhos de suas concubinas deu Abraão presentes, e enviou-os para longe de Isaque seu filho, enquanto ele vivia, até o oriente, à terra oriental.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'E estes foram os dias de vida que viveu Abraão: cento e setenta e cinco anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'E expirou, e morreu Abraão em boa velhice, ancião e cheio de dias e foi unido a seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'E sepultaram-no Isaque e Ismael seus filhos na caverna de Macpela, na propriedade de Efrom, filho de Zoar Heteu, que está em frente de Manre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Herança que comprou Abraão dos filhos de Hete; ali foi Abraão sepultado, e Sara sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'E sucedeu, depois de morto Abraão, que Deus abençoou a Isaque seu filho: e habitou Isaque junto a Beer-Laai-Roi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'E estas são as gerações de Ismael, filho de Abraão, que lhe deu à luz Agar egípcia, serva de Sara:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Estes, pois, são os nomes dos filhos de Ismael, por seus nomes, por suas linhagens: O primogênito de Ismael, Nebaiote; logo Quedar, e Adbeel, e Mibsão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'E Misma, e Dumá, e Massá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadade, e Tema, e Jetur, e Nafis, e Quedemá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Estes são os filhos de Ismael, e estes seus nomes por suas vilas e por seus acampamentos; doze príncipes por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'E estes foram os anos da vida de Ismael, cento e trinta e sete anos: e expirou Ismael, e morreu; e foi unido a seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'E habitaram desde Havilá até Sur, que está em frente do Egito vindo a Assíria; e morreu em presença de todos os seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'E estas são as gerações de Isaque, filho de Abraão. Abraão gerou a Isaque:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'E era Isaque de quarenta anos quando tomou por mulher a Rebeca, filha de Betuel arameu de Padã-Arã, irmã de Labão arameu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'E orou Isaque ao SENHOR por sua mulher, que era estéril; e aceitou-o o SENHOR, e concebeu Rebeca sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'E os filhos se combatiam dentro dela; e disse: Se é assim para que vivo eu? E foi consultar ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'E respondeu-lhe o SENHOR: Duas nações há em teu ventre, E dois povos serão divididos desde tuas entranhas: E um povo será mais forte que o outro povo, e o maior servirá ao menor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'E quando se cumpriram seus dias para dar à luz, eis que havia gêmeos em seu ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'E saiu o primeiro ruivo, e todo ele peludo como uma veste; e chamaram seu nome Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'E depois saiu seu irmão, pegando com sua mão o calcanhar de Esaú: e foi chamado seu nome Jacó. E era Isaque de idade de sessenta anos quando ela os deu à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'E cresceram os meninos, e Esaú foi hábil na caça, homem do campo: Jacó porém era homem quieto, que habitava em tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'E amou Isaque a Esaú, porque comia de sua caça; mas Rebeca amava a Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'E cozinhou Jacó um guisado; e voltando Esaú do campo cansado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Disse a Jacó: Rogo-te que me dês a comer disso vermelho, pois estou muito cansado. Portanto foi chamado seu nome Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'E Jacó respondeu: Vende-me neste dia tua primogenitura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Então disse Esaú: Eis que vou morrer; para que, pois, me servirá a primogenitura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'E disse Jacó: Jura-me hoje. E ele lhe jurou, e vendeu a Jacó sua primogenitura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Então Jacó deu a Esaú pão e do guisado das lentilhas; e ele comeu e bebeu, e levantou-se, e foi-se. Assim menosprezou Esaú a primogenitura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'E houve fome na terra, além da primeira fome que foi nos dias de Abraão: e foi-se Isaque a Abimeleque rei dos filisteus, em Gerar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'E apareceu-lhe o SENHOR, e disse-lhe: Não desças ao Egito: habita na terra que eu te disser;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Habita nesta terra, e serei contigo, e te abençoarei; porque a ti e à tua descendência darei todas estas terras, e confirmarei o juramento que jurei a Abraão teu pai:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'E multiplicarei tua descendência como as estrelas do céu, e darei à tua descendência todas estas terras; e todas as nações da terra serão abençoadas em tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Porquanto ouviu Abraão minha voz, e guardou meu preceito, meus mandamentos, meus estatutos e minhas leis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Habitou, pois, Isaque em Gerar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'E os homens daquele lugar lhe perguntaram acerca de sua mulher; e ele respondeu: É minha irmã; porque teve medo de dizer: É minha mulher; que talvez, disse, os homens do lugar me matem por causa de Rebeca; porque era de belo aspecto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'E sucedeu que, depois que ele esteve ali muitos dias, Abimeleque, rei dos filisteus, olhando por uma janela, viu a Isaque que acariciava Rebeca sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'E chamou Abimeleque a Isaque, e disse: Eis que ela é certamente tua mulher: como, pois, disseste: É minha irmã? E Isaque lhe respondeu: Porque disse: Talvez eu morra por causa dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'E Abimeleque disse: Por que nos fizeste isto? Por pouco haveria dormido alguém do povo com tua mulher, e haverias trazido sobre nós o pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Então Abimeleque mandou a todo o povo, dizendo: O que tocar a este homem ou a sua mulher certamente morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'E semeou Isaque naquela terra, e achou aquele ano cem por um: e o SENHOR o abençoou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'E o homem se engrandeceu, e foi engrandecendo-se cada vez mais, até fazer-se muito poderoso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'E teve rebanho de ovelhas, e rebanho de vacas, e grande número de servos; e os filisteus tiveram inveja dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'E todos os poços que os criados de Abraão seu pai haviam aberto em seus dias, os filisteus os haviam fechado e enchido da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'E disse Abimeleque a Isaque: Aparta-te de nós, porque muito mais poderoso que nós te fizeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'E Isaque se foi dali; e assentou suas tendas no vale de Gerar, e habitou ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'E voltou a abrir Isaque os poços de água que haviam aberto nos dias de Abraão seu pai, e que os filisteus haviam fechado, depois de Abraão ter morrido; e chamou-os pelos nomes que seu pai os havia chamado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'E os servos de Isaque cavaram no vale, e acharam ali um poço de águas vivas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'E os pastores de Gerar brigaram com os pastores de Isaque, dizendo: A água é nossa: por isso chamou o nome do poço Eseque, porque haviam brigado com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'E abriram outro poço, e também brigaram sobre ele: e chamou seu nome Sitna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'E apartou-se dali, e abriu outro poço, e não brigaram sobre ele: e chamou seu nome Reobote, e disse: Porque agora nos fez alargar o SENHOR e frutificaremos na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'E dali subiu a Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'E apareceu-lhe o SENHOR aquela noite, e disse: Eu sou o Deus de Abraão teu pai: não temas, que eu sou contigo, e eu te abençoarei, e multiplicarei tua descendência por causa do meu servo Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'E edificou ali um altar, e invocou o nome do SENHOR, e estendeu ali sua tenda: e abriram ali os servos de Isaque um poço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'E Abimeleque veio a ele desde Gerar, e Auzate, amigo seu, e Ficol, capitão de seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'E disse-lhes Isaque: Por que vindes a mim, pois que haveis me odiado, e me expulsastes dentre vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'E eles responderam: Vimos que o SENHOR é contigo; e dissemos: Haja agora juramento entre nós, entre nós e ti, e faremos aliança contigo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Que não nos faças mal, como nós não te tocamos, y como somente te fizemos bem, e te enviamos em paz: tu agora, bendito do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Então ele lhes fez banquete, e comeram e beberam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'E se levantaram de madrugada, e juraram um ao outro; e Isaque os despediu, e eles se partiram dele em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'E naquele dia sucedeu que vieram os criados de Isaque, e deram-lhe notícias acerca do poço que haviam aberto, e lhe disseram: Achamos água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'E chamou-o Seba: por cuja causa o nome daquela cidade é Berseba até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'E quando Esaú foi de quarenta anos, tomou por mulher a Judite filha de Beeri heteu, e a Basemate filha de Elom heteu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'E foram amargura de espírito a Isaque e a Rebeca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'E aconteceu que quando havia Isaque envelhecido, e seus olhos se ofuscaram ficando sem vista, chamou a Esaú, seu filho o maior, e disse-lhe: Meu filho. E ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'E ele disse: Eis que já sou velho, não sei o dia de minha morte:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Toma, pois, agora tuas armas, tua aljava e teu arco, e sai ao campo, e pega-me caça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'E faze-me um guisado, como eu gosto, e traze-o a mim, e comerei: para que te abençoe minha alma antes que morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'E Rebeca estava ouvindo, quando falava Isaque a Esaú seu filho: e foi-se Esaú ao campo para pegar a caça que havia de trazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Então Rebeca falou a Jacó seu filho, dizendo: Eis que eu ouvi a teu pai que falava com Esaú teu irmão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Traze-me caça, e faze-me um guisado, para que coma, e te abençoe diante do SENHOR antes que eu morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Agora, pois, filho meu, obedece à minha voz no que te mando;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Vai agora ao gado, e traze-me dali dois bons cabritos das cabras, e farei deles iguarias para teu pai, como ele gosta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'E tu as levarás a teu pai, e comerá, para que te abençoe antes de sua morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'E Jacó disse a Rebeca sua mãe: Eis que Esaú meu irmão é homem peludo, e eu liso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Talvez meu pai me apalpe, e me terá por enganador, e trarei sobre mim maldição e não bênção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'E sua mãe respondeu: Filho meu, sobre mim tua maldição: somente obedece à minha voz, e vai e traze-os a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Então ele foi, e tomou, e trouxe-os à sua mãe: e sua mãe fez guisados, como seu pai gostava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'E tomou Rebeca as roupas de Esaú seu filho maior, as melhores, que ela tinha em casa, e vestiu a Jacó seu filho menor:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'E fez-lhe vestir sobre suas mãos e sobre o pescoço onde não tinha pelo, as peles dos cabritos das cabras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'E entregou os guisados e o pão que havia preparado, em mão de Jacó seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'E ele foi a seu pai, e disse: Meu pai: e ele respondeu: Eis-me aqui, quem és, filho meu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'E Jacó disse a seu pai: Eu sou Esaú teu primogênito; fiz como me disseste: levanta-te agora, e senta, e come de minha caça, para que me abençoe tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Então Isaque disse a seu filho: Como é que a achaste tão depressa, filho meu? E ele respondeu: Porque o SENHOR teu Deus fez que se encontrasse diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'E Isaque disse a Jacó: Aproxima-te agora, e te apalparei, filho meu, para que eu saiba se és meu filho Esaú ou não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'E chegou-se Jacó a seu pai Isaque; e ele lhe apalpou, e disse: A voz é a voz de Jacó, mas as mãos, as mãos de Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'E não lhe reconheceu, porque suas mãos eram peludas como as mãos de Esaú: e lhe abençoou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'E disse: És tu meu filho Esaú? E ele respondeu: Eu sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'E disse: Aproxima-a a mim, e comerei da caça de meu filho, para que te abençoe minha alma; e ele a aproximou, e comeu: trouxe-lhe também vinho, e bebeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'E disse-lhe Isaque seu pai: Aproxima-te agora, e beija-me, filho meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'E ele se chegou, e lhe beijou; e cheirou Isaque o cheiro de suas roupas, e lhe abençoou, e disse: Eis que o cheiro de meu filho é como o cheiro do campo que o SENHOR abençoou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Deus, pois, te dê do orvalho do céu, e das gorduras da terra, e abundância de trigo e de mosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Sirvam-te povos, E nações se inclinem a ti: Sê senhor de teus irmãos, e inclinem-se a ti os filhos de tua mãe; malditos os que te amaldiçoarem, e benditos os que te abençoarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'E aconteceu, logo que havia Isaque de abençoar a Jacó, e apenas havia saído Jacó de diante de Isaque seu pai, que Esaú seu irmão veio de sua caça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'E também ele fez guisado, e trouxe a seu pai, e disse-lhe: Levante-se meu pai, e coma da caça de seu filho, para que me abençoe tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Então Isaque seu pai lhe disse: Quem és tu? E ele disse: Eu sou teu filho, teu primogênito, Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'E Estremeceu-se Isaque com grande estremecimento, e disse: Quem é o que veio aqui, que agarrou caça, e me trouxe, e comi de tudo antes que viesses? Eu o abençoei, e será bendito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Quando Esaú ouviu as palavras de seu pai clamou com uma muito grande e muito amarga exclamação, e lhe disse: Abençoa também a mim, meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'E ele disse: Veio teu irmão com engano, e tomou tua bênção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'E ele respondeu: Bem chamaram seu nome Jacó, que já me enganou duas vezes; tirou minha primogenitura, e eis que agora tomou minha bênção. E disse: Não guardaste bênção para mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaque respondeu e disse a Esaú: Eis que eu o pus por senhor teu, e lhe dei por servos a todos os seus irmãos: de trigo e de vinho lhe provi: que, pois, farei a ti agora, filho meu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'E Esaú respondeu a seu pai: Não tens mais que uma só bênção, meu pai? Abençoa também a mim, meu pai. E levantou Esaú sua voz, e chorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Então Isaque seu pai falou e disse-lhe: Eis que será tua habitação sem gorduras da terra, E sem orvalho dos céus de acima;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'E por tua espada viverás, e a teu irmão servirás: E sucederá quando te dominares, Que descarregarás seu jugo de teu pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'E odiou Esaú a Jacó pela bênção com que lhe havia abençoado, e disse em seu coração: Chegarão os dias do luto de meu pai, e eu matarei a Jacó meu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'E foram ditas a Rebeca as palavras de Esaú seu filho mais velho: e ela enviou e chamou a Jacó seu filho mais novo, e disse-lhe: Eis que, Esaú teu irmão se consola acerca de ti com a ideia de matar-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Agora, pois, filho meu, obedece à minha voz; levanta-te, e foge-te a Labão meu irmão, a Harã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'E mora com ele alguns dias, até que a ira de teu irmão se diminua;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Até que se aplaque a ira de teu irmão contra ti, e se esqueça do que lhe fizeste: eu enviarei então, e te trarei dali: por que serei privada de vós ambos em um dia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'E disse Rebeca a Isaque: Desgosto tenho de minha vida, por causa das filhas de Hete. Se Jacó toma mulher das filhas de Hete, como estas, das filhas desta terra, para que quero a vida?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Então Isaque chamou a Jacó, e o abençoou, e mandou-lhe dizendo: Não tomes mulher das filhas de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Levanta-te, vai a Padã-Arã, à casa de Betuel, pai de tua mãe, e toma ali mulher das filhas de Labão, irmão de tua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'E o Deus Todo-Poderoso te abençoe e te faça frutificar, e te multiplique, até vir a ser congregação de povos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'E te dê a bênção de Abraão, e à tua descendência contigo, para que herdes a terra de tuas peregrinações, que Deus deu a Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Assim enviou Isaque a Jacó, o qual foi a Padã-Arã, a Labão, filho de Betuel arameu, irmão de Rebeca, mãe de Jacó e de Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'E viu Esaú como Isaque havia abençoado a Jacó, e lhe havia enviado a Padã-Arã, para tomar para si mulher dali; e que quando lhe abençoou, lhe havia mandado, dizendo: Não tomarás mulher das filhas de Canaã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'E que Jacó havia obedecido a seu pai e a sua mãe, e se havia ido a Padã-Arã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Viu também Esaú que as filhas de Canaã pareciam mal a Isaque seu pai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'E foi-se Esaú a Ismael, e tomou para si por mulher a Maalate, filha de Ismael, filho de Abraão, irmã de Nebaiote, além de suas outras mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'E saiu Jacó de Berseba, e foi a Harã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'E encontrou com um lugar, e dormiu ali porque já o sol se havia posto: e tomou das pedras daquele lugar e pôs à sua cabeceira, e deitou-se naquele lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'E sonhou, e eis uma escada que estava apoiada em terra, e seu topo tocava no céu: e eis que anjos de Deus subiam e desciam por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'E eis que o SENHOR estava no alto dela, o qual disse: Eu sou o SENHOR, o Deus de Abraão teu pai, e o Deus de Isaque: a terra em que estás deitado a darei a ti e à tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'E será tua descendência como o pó da terra, e te estenderás ao ocidente, e ao oriente, e ao norte, e ao sul; e todas as famílias da terra serão abençoadas em ti e em tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'E eis que eu sou contigo, e te guardarei por onde quer que fores, e te farei voltar a esta terra; porque não te deixarei até tanto que tenha feito o que te disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'E despertou Jacó de seu sonho disse: Certamente o SENHOR está neste lugar, e eu não o sabia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'E teve medo, e disse: Quão terrível é este lugar! Não é outra coisa que casa de Deus, e porta do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'E levantou-se Jacó de manhã, e tomou a pedra que havia posto de cabeceira, e levantou-a por coluna, e derramou azeite sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'E chamou o nome daquele lugar Betel, ainda que o nome da cidade antes era Luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'E fez Jacó voto, dizendo: Se for Deus comigo, e me guardar nesta viagem que vou, e me der pão para comer e roupa para vestir,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'E se voltar em paz à casa de meu pai, o SENHOR será meu Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'E esta pedra que pus por coluna, será casa de Deus; e de tudo o que me deres, darei o dízimo a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'E seguiu Jacó seu caminho, e foi à terra dos orientais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'E olhou, e viu um poço no campo: e eis três rebanhos de ovelhas que estavam deitados próximo dele; porque daquele poço davam de beber aos gados: e havia uma grande pedra sobre a boca do poço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'E juntavam-se ali todos os rebanhos; e revolviam a pedra de sobre a boca do poço, e davam de beber às ovelhas; e voltavam a pedra sobre a boca do poço a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'E disse-lhes Jacó: Irmãos meus, de onde sois? E eles responderam: De Harã somos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'E ele lhes disse: Conheceis a Labão, filho de Naor? E eles disseram: Sim, nós o conhecemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'E ele lhes disse: Ele está bem? E eles disseram: Está bem; e eis que Raquel sua filha vem com o gado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'E ele disse: Eis que ainda é cedo do dia; não é hora de recolher o gado; dai de beber às ovelhas, e ide apascentá-las.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'E eles responderam: Não podemos, até que se juntem todos os gados, e removam a pedra de sobre a boca do poço, para que demos de beber às ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Estando ainda ele falando com eles Raquel veio com o gado de seu pai, porque ela era a pastora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'E sucedeu que, quando Jacó viu Raquel, filha de Labão irmão de sua mãe, e as ovelhas de Labão, o irmão de sua mãe, chegou-se Jacó, e removeu a pedra de sobre a boca do poço, e deu de beber ao gado de Labão irmão de sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'E Jacó beijou a Raquel, e levantou sua voz, e chorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'E Jacó disse a Raquel como ele era irmão de seu pai, e como era filho de Rebeca: e ela correu, e deu as novas a seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'E assim que ouviu Labão as novas de Jacó, filho de sua irmã, correu a recebê-lo, e abraçou-o, e beijou-o, e trouxe-lhe à sua casa: e ele contou a Labão todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'E Labão lhe disse: Certamente és osso meu e carne minha. E esteve com ele durante um mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Então disse Labão a Jacó: Por ser tu meu irmão, me hás de servir de graça? Declara-me o que será teu salário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'E Labão tinha duas filhas: o nome da mais velha era Lia, e o nome da mais nova, Raquel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'E os olhos de Lia eram tenros, mas Raquel era de lindo semblante e de bela aparência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'E Jacó amou a Raquel, e disse: Eu te servirei sete anos por Raquel tua filha mais nova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'E Labão respondeu: Melhor é que a dê a ti, que não que a dê a outro homem: fica-te comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Assim serviu Jacó por Raquel sete anos: e pareceram-lhe como poucos dias, porque a amava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'E disse Jacó a Labão: Dá-me minha mulher, porque meu tempo é cumprido para que me deite com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Então Labão juntou a todos os homens daquele lugar, e fez banquete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'E sucedeu que à noite tomou sua filha Lia, e a trouxe; e ele se deitou com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'E deu Labão sua serva Zilpa à sua filha Lia por criada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'E vinda a manhã, eis que era Lia: e ele disse a Labão: Que é isto que me fizeste? Não te servi por Raquel? Por que, pois, me enganaste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'E Labão respondeu: Não se faz assim em nosso lugar, que se dê a mais nova antes da mais velha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Cumpre a semana desta, e se te dará também a outra, pelo serviço que fizeres comigo por outros sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'E fez Jacó assim, e cumpriu a semana daquela; e ele lhe deu a sua filha Raquel por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'E deu Labão a Raquel sua filha por criada a sua serva Bila.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'E deitou-se também com Raquel: e amou-a também mais que a Lia: e serviu a ele ainda outros sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'E viu o SENHOR que Lia era mal-amada, e abriu sua madre; mas Raquel era estéril.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'E concebeu Lia, e deu à luz um filho, e chamou seu nome Rúben, porque disse: Já que olhou o SENHOR minha aflição; agora, portanto, meu marido me amará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'E concebeu outra vez, e deu à luz um filho, e disse: Porquanto ouviu o SENHOR que eu era mal-amada, me deu também este. E chamou seu nome Simeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'E concebeu outra vez, e deu à luz um filho, e disse: Agora esta vez meu marido se apegará a mim, porque lhe dei três filhos; portanto, chamou seu nome Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'E concebeu outra vez, e deu à luz um filho, e disse: Esta vez louvarei ao SENHOR; por isto chamou seu nome Judá; e deixou de dar à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'E vendo Raquel que não dava filhos a Jacó, teve inveja de sua irmã, e dizia a Jacó: Dá-me filhos, ou senão, morro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'E Jacó se irritava contra Raquel, e dizia: Estou eu em lugar de Deus, que te impediu o fruto de teu ventre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'E ela disse: Eis aqui minha serva Bila; deita-te com ela, e dará à luz sobre meus joelhos, e eu também terei filhos por meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Assim lhe deu a Bila sua serva por mulher; e Jacó se deitou com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'E concebeu Bila, e deu à luz a Jacó um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'E disse Raquel: Julgou-me Deus, e também ouviu minha voz, e deu-me um filho. Portanto chamou seu nome Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'E concebeu outra vez Bila, a serva de Raquel, e deu à luz o segundo filho a Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'E disse Raquel: Com lutas de Deus disputei com minha irmã, e venci. E chamou seu nome Naftali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'E vendo Lia que havia deixado de dar à luz, tomou a Zilpa sua serva, e deu-a a Jacó por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'E Zilpa, serva de Lia, deu à luz a Jacó um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'E disse Lia: Veio a boa sorte. E chamou seu nome Gade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'E Zilpa, a sirva de Lia, deu à luz outro filho a Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'E disse Lia: Para alegria minha; porque as mulheres me chamarão de feliz; e chamou seu nome Aser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'E foi Rúben em tempo da colheita dos trigos, e achou mandrágoras no campo, e trouxe-as a sua mãe Lia; e disse Raquel a Lia: Rogo-te que me dês das mandrágoras de teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'E ela respondeu: É pouco que tenhas tomado meu marido, mas também levarás as mandrágoras de meu filho? E disse Raquel: Ele, pois, dormirá contigo esta noite pelas mandrágoras de teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'E quando Jacó voltava do campo à tarde, Lia saiu ao encontro dele, e lhe disse: Deitarás comigo, porque em verdade te aluguei em troca das mandrágoras de meu filho. E dormiu com ela naquela noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'E ouviu Deus a Lia; e concebeu, e deu à luz a Jacó o quinto filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'E disse Lia: Deus me deu minha recompensa, porque dei minha serva a meu marido; por isso chamou seu nome Issacar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'E concebeu Lia outra vez, e deu à luz o sexto filho a Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'E disse Lia: Deus me deu uma boa dádiva: agora meu marido morará comigo, porque lhe dei seis filhos; e chamou seu nome Zebulom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'E depois deu à luz uma filha, e chamou seu nome Diná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'E lembrou-se Deus de Raquel, e Deus a ouviu, e abriu sua madre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'E concebeu, e deu à luz um filho: e disse: Deus tirou minha humilhação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'E chamou seu nome José, dizendo: Acrescente-me o SENHOR outro filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'E aconteceu, quando Raquel havia dado à luz a José, que Jacó disse a Labão: Permite-me ir embora, e irei a meu lugar, e à minha terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Dá-me minhas mulheres e meus filhos, pelas quais servi contigo, e deixa-me ir; pois tu sabes os serviços que te fiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'E Labão lhe respondeu: Ache eu agora favor em teus olhos, e fica-te; experimentei que o SENHOR me abençoou por tua causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'E disse: Define-me teu salário, que eu o darei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'E ele respondeu: Tu sabes como te servi, e como esteve teu gado comigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Porque pouco tinhas antes de minha vinda, e cresceu em grande número; e o SENHOR te abençoou com minha chegada: e agora quando tenho de fazer eu também por minha própria casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'E ele disse: Que te darei? E respondeu Jacó: Não me dês nada; se fizeres por mim isto, voltarei a apascentar tuas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Eu passarei hoje por todas tuas ovelhas, pondo à parte todas as reses manchadas e de cor variada, e todas as reses de cor escura entre as ovelhas, e as manchadas e de cor variada entre as cabras; e isto será meu salário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Assim responderá por mim minha justiça amanhã quando me vier meu salário diante de ti: toda a que não for pintada nem manchada nas cabras e de cor escura nas ovelhas minhas, se me há de ter para furto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'E disse Labão: Eis que seja como tu dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Porém ele separou naquele mesmo dia os machos de bode rajados e manchados; e todas as cabras manchadas e de cor variada, e toda rês que tinha em si algo de branco, e todas as de cor escura entre as ovelhas, e as pôs em mãos de seus filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'E pôs três dias de caminho entre si e Jacó: e Jacó apascentava as outras ovelhas de Labão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'E tomou para si Jacó varas de álamo verdes, e de aveleira, e de plátano, e descascou nelas mondaduras brancas, descobrindo assim o branco das varas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'E pôs as varas que havia riscado nos bebedouros, diante do gado, nos bebedouros da água aonde vinham a beber as ovelhas, as quais se aqueciam vindo a beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'E concebiam as ovelhas diante das varas, e geravam crias listradas, pintadas e salpicadas de diversas cores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'E separava Jacó os cordeiros, e os punha com seu rebanho, os listradas, e tudo o que era escuro no rebanho de Labão. E punha seu rebanho à parte, e não o punha com as ovelhas de Labão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'E sucedia que quantas vezes se aqueciam as fortes, Jacó punha as varas diante das ovelhas nos bebedouros, para que concebessem à vista das varas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'E quando vinham as ovelhas fracas, não as punha: assim eram as fracas para Labão, e as fortes para Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'E cresceu o homem muito, e teve muitas ovelhas, e servas, servos, camelos, e asnos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'E ouvia ele as palavras dos filhos de Labão que diziam: Jacó tomou tudo o que era de nosso pai; e do que era de nosso pai adquiriu toda esta grandeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Olhava também Jacó o semblante de Labão, e via que não era para com ele como antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Também o SENHOR disse a Jacó: Volta-te à terra de teus pais, e à tua parentela; que eu serei contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'E enviou Jacó, e chamou a Raquel e a Lia ao campo a suas ovelhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'E disse-lhes: Vejo que o semblante de vosso pai não é para comigo como antes: mas o Deus de meu pai tem sido comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'E vós sabeis que com todas minhas forças servi a vosso pai:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'E vosso pai me enganou, e me mudou o salário dez vezes: mas Deus não lhe permitiu que me fizesse mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Se ele dizia assim: Os pintados serão teu salário; então todas as ovelhas geravam pintados: e se dizia assim: Os listrados serão teu salário; então todas as ovelhas geravam listrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Assim tirou Deus o gado de vosso pai, e deu-o a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'E sucedeu que ao tempo que as ovelhas se aqueciam, levantei eu meus olhos e vi em sonhos, e eis que os machos que cobriam às fêmeas eram listrados, pintados e malhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'E disse-me o anjo de Deus em sonhos: Jacó. E eu disse: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'E ele disse: Levanta agora teus olhos, e verás todos os machos que cobrem às ovelhas são listrados, pintados e malhados; porque eu vi tudo o que Labão te fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Eu sou o Deus de Betel, onde tu ungiste a coluna, e onde me fizeste um voto. Levanta-te agora, e sai desta terra, e volta-te à terra de teu nascimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'E respondeu Raquel e Lia, e disseram-lhe: Temos ainda parte ou herança na casa de nosso pai?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Não nos tem já como por estranhas, pois que nos vendeu, e ainda consumiu de todo nosso valor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Porque toda a riqueza que Deus tirou a nosso pai, nossa é e de nossos filhos: agora, pois, faze tudo o que Deus te disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Então se levantou Jacó, e subiu seus filhos e suas mulheres sobre os camelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'E pôs em caminho todo seu gado, e todos os seus pertences que havia adquirido, o gado de seu ganho que havia obtido em Padã-Arã, para voltar-se a Isaque seu pai na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'E Labão havia ido tosquiar suas ovelhas; e Raquel furtou os ídolos de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'E enganou Jacó o coração de Labão arameu, em não lhe fazer saber que se fugia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Fugiu, pois, com tudo o que tinha; e levantou-se, e passou o rio, e pôs seu rosto ao monte de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'E foi dito a Labão ao terceiro dia como Jacó havia fugido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Então tomou a seus irmãos consigo, e foi atrás dele caminho de sete dias, e alcançou-lhe no monte de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'E veio Deus a Labão arameu em sonhos aquela noite, e lhe disse: Guarda-te que não fales a Jacó descomedidamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Alcançou, pois, Labão a Jacó, e este havia fixado sua tenda no monte: e Labão pôs a sua com seus irmãos no monte de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'E disse Labão a Jacó: Que fizeste, que me furtaste o coração, e trouxeste a minhas filhas como prisioneiras de guerra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Por que te escondeste para fugir, e me furtaste, e não me deste notícia, para que eu te enviasse com alegria e com cantares, com tamborim e harpa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Que ainda não me deixaste beijar meus filhos e minhas filhas. Agora loucamente fizeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Poder há em minha mão para fazer-vos mal; mas o Deus de vosso pai me falou de noite dizendo: Guarda-te que não fales a Jacó descomedidamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'E já que te ias, porque tinhas saudade da casa de teu pai, por que me furtaste meus deuses?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'E Jacó respondeu, e disse a Labão: Pois tive medo; porque disse, que talvez me tirasse à força tuas filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Em quem achares teus deuses, não viva: diante de nossos irmãos reconhece o que eu tiver teu, e leva-o. Jacó não sabia que Raquel havia os furtado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'E entrou Labão na tenda de Jacó, e na tenda de Lia, e na tenda das duas servas, e não os achou, e saiu da tenda de Lia, e veio à tenda de Raquel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'E tomou Raquel os ídolos, e os pôs em uma albarda de um camelo, e sentou-se sobre eles: e provou Labão toda a tenda e não os achou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'E ela disse a seu pai: Não se ire meu senhor, porque não me posso levantar diante de ti; pois estou com o costume das mulheres. E ele buscou, mas não achou os ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Então Jacó se irou, e brigou com Labão; e respondeu Jacó e disse a Labão: Que transgressão é a minha? Qual é meu pecado, que com tanto ardor vieste a me perseguir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Depois que apalpaste todos os meus móveis, acaso achaste algum dos objetos de tua casa? Põe-o aqui diante de meus irmãos e teus, e julguem entre nós ambos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Estes vinte anos estive contigo; tuas ovelhas e tuas cabras nunca abortaram, nem eu comi carneiro de tuas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Nunca te trouxe o arrebatado pelas feras; eu pagava o dano; o furtado tanto de dia como de noite, de minha mão o exigias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'De dia me consumia o calor, e de noite a geada, e o sono se fugia de meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Assim estive vinte anos em tua casa: catorze anos te servi por tuas duas filhas, e seis anos por teu gado; e mudaste meu salário dez vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Se o Deus de meu pai, o Deus de Abraão, e o temor de Isaque, não fossem comigo, certamente me enviarias agora vazio; Deus viu minha aflição e o trabalho de minhas mãos, e repreendeu-te de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'E respondeu Labão, e disse a Jacó: As filhas são filhas minhas, e os filhos, filhos meus são, e as ovelhas são minhas ovelhas, e tudo o que tu vês é meu; e que posso eu fazer hoje a estas minhas filhas, ou a seus filhos que elas geraram?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Vem, pois, agora, façamos aliança eu e tu; e seja em testemunho entre mim e ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Então Jacó tomou uma pedra, e levantou-a por coluna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'E disse Jacó a seus irmãos: Recolhei pedras. E tomaram pedras e fizeram um amontoado; e comeram ali sobre aquele amontoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'E Labão o chamou Jegar-Saaduta; e Jacó o chamou Galeede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Porque Labão disse: Este amontoado é testemunha hoje entre mim e entre ti; por isso foi chamado seu nome Galeede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'E Mispá, porquanto disse: Vigie o SENHOR entre mim e entre ti, quando nos separarmos um do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Se afligires minhas filhas, ou se tomares outras mulheres além de minhas filhas, ninguém está conosco; olha, Deus é testemunha entre mim e ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Disse mais Labão a Jacó: Eis que este amontoado, e eis que esta coluna, que erigi entre mim e ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Testemunha seja este amontoado, e testemunha seja esta coluna, que nem eu passarei contra ti este amontoado, nem tu passarás contra mim este amontoado nem esta coluna, para o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'O Deus de Abraão, e o Deus de Naor julgue entre nós, o Deus de seus pais. E Jacó jurou pelo temor de Isaque seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Então Jacó ofereceu sacrifícios no monte, e chamou seus parentes para comer pão; e comeram pão, e dormiram aquela noite no monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'E levantou-se Labão de manhã, beijou seus filhos e suas filhas, e os abençoou; e retrocedeu e voltou a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'E Jacó se foi seu caminho, e saíram-lhe ao encontro anjos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'E disse Jacó quando os viu: Este é o acampamento de Deus; e chamou o nome daquele lugar Maanaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'E enviou Jacó mensageiros diante de si a Esaú seu irmão, à terra de Seir, campo de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'E mandou-lhes dizendo: Assim direis a mim senhor Esaú: Assim diz teu servo Jacó: Com Labão morei, e detive-me até agora;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'E tenho vacas, e asnos, e ovelhas, e servos, e servas; e envio a dizê-lo a meu senhor, para achar favor em teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'E os mensageiros voltaram a Jacó, dizendo: Viemos a teu irmão Esaú, e ele também veio a receber-te, e quatrocentos homens com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Então Jacó teve grande temor, e angustiou-se; e partiu o povo que tinha consigo, e as ovelhas e as vacas e os camelos, em dois grupos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'E disse: Se vier Esaú a um grupo e o ferir, o outro grupo escapará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'E disse Jacó: Deus de meu pai Abraão, e Deus de meu pai Isaque, o SENHOR, que me disseste: Volta-te à tua terra e à tua parentela, e eu te farei bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Menor sou que todas as misericórdias, e que toda a verdade que usaste para com teu servo; que com meu bordão passei este Jordão, e agora estou sobre dois grupos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Livra-me agora da mão de meu irmão, da mão de Esaú, porque o temo; não venha talvez, e me fira a mãe com os filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'E tu disseste: Eu te farei bem, e tornarei tua descendência como a areia do mar, que não se pode contar de tão numerosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'E dormiu ali aquela noite, e tomou do que lhe veio à mão um presente para seu irmão Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Duzentas cabras e vinte machos de bode, duzentas ovelhas e vinte carneiros,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Trinta camelas de cria, com seus filhotes, quarenta vacas e dez novilhos, vinte asnas e dez jumentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'E entregou-o em mão de seus servos, cada manada à parte; e disse a seus servos: Passai diante de mim, e ponde espaço entre manada e manada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'E mandou ao primeiro, dizendo: Se meu irmão Esaú te encontrar, e te perguntar, dizendo De quem és? E: Para onde vais? E: para quem é isto que levas diante de ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Então dirás: Presente é de teu servo Jacó, que envia a meu senhor Esaú; e eis que também ele vem atrás de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'E mandou também ao segundo, e ao terceiro, e a todos os que iam atrás aquelas manadas, dizendo: Conforme isto falareis a Esaú, quando o achardes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'E direis também: Eis que teu servo Jacó vem atrás de nós. Porque disse: Apaziguarei sua ira com o presente que vai adiante de mim, e depois verei seu rosto; talvez lhe serei aceito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'E passou o presente adiante dele; e ele dormiu aquela noite no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'E levantou-se aquela noite, e tomou suas duas mulheres, e suas duas servas, e seus onze filhos, e passou o vau de Jaboque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Tomou-os, pois, e passou-os o ribeiro, e fez passar o que tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'E ficou Jacó sozinho, e lutou com ele um homem até que raiava a alva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'E quando viu que não podia com ele, tocou no lugar da juntura de sua coxa, e desconjuntou-se a coxa de Jacó enquanto com ele lutava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'E disse: Deixa-me, que raia a alva. E ele disse: Não te deixarei, se não me abençoares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'E ele lhe disse: Qual é teu nome? E ele respondeu: Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'E ele disse: Não se dirá mais teu nome Jacó, mas sim Israel: porque lutaste com Deus e com os homens, e venceste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Então Jacó lhe perguntou, e disse: Declara-me agora teu nome. E ele respondeu: Por que perguntas por meu nome? E abençoou-o ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'E chamou Jacó o nome daquele lugar Peniel: porque vi a Deus face a face, e foi livrada minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'E saiu-lhe o sol quando passou a Peniel; e andava mancando de sua coxa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Por isto até o dia de hoje os filhos de Israel não comem do tendão que se contrai, o qual está na juntura da coxa; porque o homem tocou a Jacó este lugar de sua coxa no tendão que se contrai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'E levantando Jacó seus olhos, olhou, e eis que vinha Esaú, e os quatrocentos homens com ele: então repartiu ele os filhos entre Lia e Raquel e as duas servas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'E pôs as servas e seus filhos adiante; logo a Lia e a seus filhos; e a Raquel e a José os últimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'E ele passou diante deles, e inclinou-se à terra sete vezes, até que chegou a seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'E Esaú correu a seu encontro, e abraçou-lhe, e lançou-se sobre seu pescoço, e o beijou; e choraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'E levantou seus olhos, e viu as mulheres e os filhos, e disse: Quem são estes que estão contigo? E ele respondeu: São os filhos que Deus deu a teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'E se chegaram as servas, elas e seus meninos, e inclinaram-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'E chegou-se Lia com seus filhos, e inclinaram-se: e depois chegou José e Raquel, e também se inclinaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'E ele disse: Qual é a tua intenção com todos estes grupos que encontrei? E ele respondeu: Achar favor aos olhos de meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'E disse Esaú: Tenho o bastante, meu irmão; seja para ti o que é teu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'E disse Jacó: Não, eu te rogo, se achei agora favor em teus olhos, toma meu presente de minha mão, pois vi teu rosto como se houvesse visto o rosto de Deus; e me aceitaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Toma, eu te rogo, minha dádiva que te é trazida; porque Deus me fez misericórdia, e tudo o que há aqui é meu. E insistiu com ele, e tomou-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'E disse: Anda, e vamos; e eu irei adiante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'E ele lhe disse: Meu senhor sabe que os meninos são tenros, e que tenho ovelhas e vacas de cria; e se as cansam, em um dia morrerão todas as ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Passe agora meu senhor diante de seu servo, e eu me irei pouco a pouco ao passo do gado que vai adiante de mim, e à passagem dos meninos, até que chegue a meu senhor a Seir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'E Esaú disse: Deixarei agora contigo da gente que vem comigo. E ele disse: Para que isto? ache eu favor aos olhos de meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Assim se voltou Esaú aquele dia por seu caminho a Seir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'E Jacó se partiu a Sucote, e edificou ali casa para si, e fez abrigos para seu gado; por isso chamou o nome daquele lugar Sucote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'E veio Jacó são à cidade de Siquém, que está na terra de Canaã, quando vinha de Padã-Arã; e acampou diante da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'E comprou uma parte do campo, onde estendeu sua tenda, da mão dos filhos de Hamor, pai de Siquém, por cem peças de moeda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'E erigiu ali um altar, e chamou-lhe: Deus, o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'E saiu Diná a filha de Lia, a qual esta havia dado a Jacó, para ver as mulheres nativas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'E viu-a Siquém, filho de Hamor heveu, príncipe daquela terra, e tomou-a, e deitou-se com ela, e a desonrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Mas sua alma se apegou a Diná a filha de Lia, e apaixonou-se pela moça, e falou ao coração da jovem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'E falou Siquém a Hamor seu pai, dizendo: Toma-me por mulher esta moça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'E ouviu Jacó que havia Siquém violado a Diná sua filha: e estando seus filhos com seu gado no campo, Jacó ficou em silêncio até que eles viessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'E dirigiu-se Hamor pai de Siquém a Jacó, para falar com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'E os filhos de Jacó vieram do campo quando o souberam; e se entristeceram os homens, e se irritaram muito, porque fez depravação em Israel por ter se deitado com a filha de Jacó, o que não se devia haver feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'E Hamor falou com eles, dizendo: A alma de meu filho Siquém se apegou à vossa filha; rogo-vos que a deis por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'E aparentai-vos conosco; dai-nos vossas filhas, e tomai vós as nossas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'E habitai conosco; porque a terra estará diante de vós; morai e negociai nela, e tomai nela possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Siquém também disse a seu pai e a seus irmãos: Ache eu favor em vossos olhos, e darei o que me disserdes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Aumentai muito a exigência de meu dote e presentes, que eu darei quanto me disserdes, e dá-me a moça por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'E responderam os filhos de Jacó a Siquém e a Hamor seu pai com engano; e falaram, porquanto havia violado a sua irmã Diná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'E disseram-lhes: Não podemos fazer isto de dar nossa irmã a homem que tem prepúcio; porque entre nós é abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Mas com esta condição vos consentiremos: se haveis de ser como nós, que se circuncide entre vós todo homem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Então vos daremos nossas filhas, e tomaremos nós as vossas; e habitaremos convosco, e seremos um povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mas se não nos prestardes ouvido para vos circuncidar, tomaremos nossa filha, e nos iremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'E pareceram bem seus palavras a Hamor e a Siquém, filho de Hamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'E não tardou o jovem fazer aquilo, porque a filha de Jacó lhe havia agradado: e ele era o mais honrado de toda a casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Então Hamor e Siquém seu filho vieram à porta de sua cidade, e falaram aos homens de sua cidade, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Estes homens são pacíficos conosco, e habitarão no país, e comercializarão nele; pois eis que a terra é bastante ampla para eles; nós tomaremos suas filhas por mulheres, e lhes daremos as nossas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mas com esta condição nos estes homens consentirão em habitar conosco, para que sejamos um povo: se se circuncidar em nós todo homem, assim como eles são circuncidados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Seus gados, e sua riqueza e todos seus animais, serão nossas; somente concordemos com eles, e habitarão conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'E obedeceram a Hamor e a Siquém seu filho todos os que saíam pela porta da cidade, e circuncidaram a todo homem, dentre os que saíam pela porta de sua cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'E sucedeu que ao terceiro dia, quando sentiam eles a maior dor, os dois filhos de Jacó, Simeão e Levi, irmãos de Diná, tomaram cada um sua espada, e vieram contra a cidade animosamente, e mataram a todo homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'E a Hamor e a seu filho Siquém mataram a fio de espada; e tomaram a Diná de casa de Siquém, e saíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'E os filhos de Jacó vieram aos mortos e saquearam a cidade; porquanto haviam violado à sua irmã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Tomaram suas ovelhas e vacas e seus asnos, e o que havia na cidade e no campo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'E todos os seus pertences; se levaram cativos a todos as suas crianças e suas mulheres, e roubaram tudo o que havia nas casas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Então disse Jacó a Simeão e a Levi: Vós me perturbastes em fazer-me detestável aos moradores desta terra, os cananeus e os ferezeus; e tendo eu poucos homens, se juntarão contra mim, e me ferirão, e serei destruído eu e minha casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'E eles responderam Havia ele de tratar à nossa irmã como à uma prostituta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'E disse Deus a Jacó: Levanta-te, sobe a Betel, e fica ali; e faze ali um altar ao Deus que te apareceu quando fugias de teu irmão Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Então Jacó disse à sua família e a todos os que com ele estavam: Tirai os deuses alheios que há entre vós, e limpai-vos, e mudai vossas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'E levantemo-nos, e subamos a Betel; e farei ali altar ao Deus que me respondeu no dia de minha angústia, e foi comigo no caminho que andei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Assim deram a Jacó todos os deuses alheios que havia em poder deles, e os brincos que estavam em suas orelhas; e Jacó os escondeu debaixo de um carvalho, que estava junto a Siquém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'E partiram-se, e o terror de Deus foi sobre as cidades que havia em seus arredores, e não seguiram atrás dos filhos de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'E chegou Jacó a Luz, que está em terra de Canaã, (esta é Betel) ele e todo o povo que com ele estava;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'E edificou ali um altar, e chamou o lugar El-Betel, porque ali lhe havia aparecido Deus, quando fugia de seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Então morreu Débora, ama de Rebeca, e foi sepultada às raízes de Betel, debaixo de um carvalho: e chamou-se seu nome Alom-Bacute.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'E apareceu-se outra vez Deus a Jacó, quando se havia voltado de Padã-Arã, e abençoou-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'E disse-lhe Deus: Teu nome é Jacó; não se chamará mais teu nome Jacó, mas sim Israel será teu nome: e chamou seu nome Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'E disse-lhe Deus: Eu sou o Deus Todo-Poderoso: cresce e multiplica-te; uma nação e conjunto de nações procederá de ti, e reis sairão de teus lombos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'E a terra que eu dei a Abraão e a Isaque, a darei a ti: e à tua descendência depois de ti darei a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'E foi-se dele Deus, do lugar onde com ele havia falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'E Jacó erigiu uma coluna no lugar onde havia falado com ele, uma coluna de pedra, e derramou sobre ela libação, e deitou sobre ela azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'E chamou Jacó o nome daquele lugar onde Deus havia falado com ele, Betel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'E partiram de Betel, e havia ainda como alguma distância para chegar a Efrata, quando deu à luz Raquel, e houve trabalho em seu parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'E aconteceu, que quando havia trabalho em seu parto, disse-lhe a parteira: Não temas, que também terás este filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'E aconteceu que ao sair dela a alma, (pois morreu) chamou seu nome Benoni; mas seu pai o chamou Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Assim morreu Raquel, e foi sepultada no caminho de Efrata, a qual é Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'E pôs Jacó uma coluna sobre sua sepultura: esta é a coluna da sepultura de Raquel até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'E partiu Israel, e estendeu sua tenda da outra parte de Migdal-Eder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'E aconteceu, morando Israel naquela terra, que foi Rúben e dormiu com Bila a concubina de seu pai; o qual chegou a entender Israel. Agora bem, os filhos de Israel foram doze:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Os filhos de Lia: Rúben o primogênito de Jacó, e Simeão, e Levi, e Judá, e Issacar, e Zebulom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Os filhos de Raquel: José, e Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'E os filhos de Bila, serva de Raquel: Dã, e Naftali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'E os filhos de Zilpa, serva de Lia: Gade, e Aser. Estes foram os filhos de Jacó, que lhe nasceram em Padã-Arã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'E veio Jacó a Isaque seu pai a Manre, à cidade de Arba, que é Hebrom, onde habitaram Abraão e Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'E foram os dias de Isaque cento e oitenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'E expirou Isaque, e morreu, e foi recolhido a seus povos, velho e farto de dias; e sepultaram-no Esaú e Jacó seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'E estas são as gerações de Esaú, o qual é Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esaú tomou suas mulheres das filhas de Canaã: a Ada, filha de Elom heteu, e a Oolibama, filha de Aná, filha de Zibeão os heveus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'E a Basemate, filha de Ismael, irmã de Nebaiote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'E Ada deu à luz de Esaú a Elifaz; e Basemate deu à luz a Reuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'E Oolibama deu à luz a Jeús, e a Jalão, e a Corá: estes são os filhos de Esaú, que lhe nasceram na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'E Esaú tomou suas mulheres, e seus filhos, e suas filhas, e todas as pessoas de sua casa, e seus gados, e todos seus animais, e todos os seus pertences que havia adquirido na terra de Canaã, e foi-se a outra terra de diante de Jacó seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Porque a riqueza deles era grande, e não podiam habitar juntos, nem a terra de sua peregrinação os podia sustentar por causa de seus gados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'E Esaú habitou no monte de Seir: Esaú é Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Estas são as linhagens de Esaú, pai de Edom, no monte de Seir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Estes são os nomes dos filhos de Esaú: Elifaz, filho de Ada, mulher de Esaú; Reuel, filho de Basemate, mulher de Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'E os filhos de Elifaz foram Temã, Omar, Zefô, Gatã, e Quenaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'E Timna foi concubina de Elifaz, filho de Esaú, a qual lhe deu à luz a Amaleque: estes são os filhos de Ada, mulher de Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'E os filhos de Reuel foram Naate, Zerá, Samá, e Mizá: estes são os filhos de Basemate, mulher de Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Estes foram os filhos de Oolibama, mulher de Esaú, filha de Aná, que foi filha de Zibeão: ela deu à luz de Esaú a Jeús, Jalão, e Corá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Estes são os duques dos filhos de Esaú. Filhos de Elifaz, primogênito de Esaú: o duque Temã, o duque Omar, o duque Zefô, o duque Quenaz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'O duque Corá, o duque Gatã, e o duque Amaleque: estes são os duques de Elifaz na terra de Edom; estes foram os filhos de Ada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'E estes são os filhos de Reuel, filho de Esaú: o duque Naate, o duque Zerá, o duque Samá, e o duque Mizá: estes são os duques da linha de Reuel na terra de Edom; estes filhos vêm de Basemate, mulher de Esaú.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'E estes são os filhos de Oolibama, mulher de Esaú: o duque Jeús, o duque Jalão, e o duque Corá: estes foram os duques que saíram de Oolibama, mulher de Esaú, filha de Aná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Estes, pois, são os filhos de Esaú, e seus duques: ele é Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'E estes são os filhos de Seir horeu, moradores daquela terra: Lotã, Sobal, Zibeão, Aná,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Disom, Eser, e Disã: estes são os duques dos horeus, filhos de Seir na terra de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Os filhos de Lotã foram Hori e Hemã; e Timna foi irmã de Lotã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'E os filhos de Sobal foram Alvã, Manaate, Ebal, Sefô, e Onã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'E os filhos de Zibeão foram Aiá, e Aná. Este Aná é o que descobriu as fontes termais no deserto, quando apascentava os asnos de Zibeão seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Os filhos de Aná foram Disom, e Oolibama, filha de Aná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'E estes foram os filhos de Disom: Hendã, Esbã, Itrã, e Querã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'E estes foram os filhos de Eser: Bilã, Zaavã, e Acã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Estes foram os filhos de Disã: Uz, e Harã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'E estes foram os duques dos horeus: o duque Lotã, o duque Sobal, o duque Zibeão, o duque Aná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'O duque Disom, o duque Eser, o duque Disã: estes foram os duques dos horeus: por seus ducados na terra de Seir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'E os reis que reinaram na terra de Edom, antes que reinasse rei sobre os filhos de Israel, foram estes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Belá, filho de Beor, reinou em Edom: e o nome de sua cidade foi Dinabá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'E morreu Belá, e reinou em seu lugar Jobabe, filho de Zerá, de Bozra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'E morreu Jobabe, e em seu lugar reinou Husão, da terra de Temã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'E morreu Husão, e reinou em seu lugar Hadade, filho de Bedade, o que feriu a Midiã no campo de Moabe: e o nome de sua cidade foi Avite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'E morreu Hadade, e em seu lugar reinou Samlá, de Masreca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'E morreu Samlá, e reinou em seu lugar Saul, de Reobote do rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'E morreu Saul, e em seu lugar reinou Baal-Hanã, filho de Acbor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'E morreu Baal-Hanã, filho de Acbor, e reinou Hadar em seu lugar: e o nome de sua cidade foi Paú; e o nome de sua mulher Meetabel, filha de Matrede, filha de Mezaabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Estes, pois, são os nomes dos duques de Esaú por suas linhagens, por seus lugares, e seus nomes: o duque Timna, o duque Alva, o duque Jetete,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'O duque Oolibama, o duque Elá, o duque Pinom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'O duque Quenaz, o duque Temã, o duque Mibzar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'O duque Magdiel, e o duque Hirão. Estes foram os duques de Edom por suas habitações na terra de sua possessão. Edom é o mesmo Esaú, pai dos edomitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'E habitou Jacó na terra onde peregrinou seu pai, na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Estas foram as gerações de Jacó. José, sendo de idade de dezessete anos apascentava as ovelhas com seus irmãos; e o jovem estava com os filhos de Bila, e com os filhos de Zilpa, mulheres de seu pai: e contava José a seu pai as más notícias acerca deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'E amava Israel a José mais que a todos os seus filhos, porque lhe havia tido em sua velhice: e lhe fez uma roupa de diversas cores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'E vendo seus irmãos que seu pai o amava mais que a todos os seus irmãos, odiavam-lhe, e não lhe podiam falar pacificamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'E sonhou José um sonho e contou-o a seus irmãos; e eles vieram a odiar-lhe mais ainda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'E ele lhes disse: Ouvi agora este sonho que sonhei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Eis que atávamos feixes no meio do campo, e eis que meu feixe se levantava, e estava em pé, e que vossos feixes estavam ao redor, e se inclinavam ao meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'E responderam-lhe seus irmãos: Reinarás tu sobre nós, ou serás tu senhor sobre nós? E o odiaram ainda mais por causa de seus sonhos e de suas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'E sonhou ainda outro sonho, e contou-o a seus irmãos, dizendo: Eis que sonhei outro sonho, e eis que o sol e a lua e onze estrelas se inclinavam a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'E contou-o a seu pai e a seus irmãos: e seu pai lhe repreendeu, e disse-lhe: Que sonho é este que sonhaste? Viremos eu e tua mãe, e teus irmãos, a nos inclinarmos a ti em terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'E seus irmãos lhe tinham inveja, mas seu pai guardava isso em mente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'E foram seus irmãos a apascentar as ovelhas de seu pai em Siquém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'E disse Israel a José: Teus irmãos apascentam as ovelhas em Siquém: vem, e te enviarei a eles. E ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'E ele lhe disse: Vai agora, olha como estão teus irmãos e como estão as ovelhas, e traze-me a resposta. E enviou-o do vale de Hebrom, e chegou a Siquém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'E achou-o um homem, andando ele perdido pelo campo, e perguntou-lhe aquele homem, dizendo: Que buscas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'E ele respondeu: Busco a meus irmãos: rogo-te que me mostres onde apascentam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'E aquele homem respondeu: Já se foram daqui; eu lhes ouvi dizer: Vamos a Dotã. Então José foi atrás de seus irmãos, e achou-os em Dotã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'E quando eles o viram de longe, antes que perto deles chegasse, tramaram contra ele para matar-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'E disseram um ao outro: Eis que vem o sonhador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Agora, pois, vinde, e o matemos e o lancemos em uma cisterna, e diremos: Alguma fera selvagem o devorou: e veremos que serão seus sonhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'E quando Rúben ouviu isto, livrou-o de suas mãos e disse: Não o matemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'E disse-lhes Rúben: Não derrameis sangue; lançai-o nesta cisterna que está no deserto, e não ponhais mão nele; para livrá-lo assim de suas mãos, para fazê-lo virar a seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'E sucedeu que, quando chegou José a seus irmãos, eles fizeram desnudar a José sua roupa, a roupa de cores que tinha sobre si;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'E tomaram-no, e lançaram-lhe na cisterna; mas a cisterna estava vazia, não havia nela água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'E sentaram-se a comer pão: e levantando os olhos olharam, e eis uma companhia de ismaelitas que vinha de Gileade, e seus camelos traziam aromas e bálsamo e mirra, e iam a levá-lo ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Então Judá disse a seus irmãos: Que proveito há em que matemos a nosso irmão e encubramos sua morte?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Vinde, e o vendamos aos ismaelitas, e não seja nossa mão sobre ele; que nosso irmão é nossa carne. E seus irmãos concordaram com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'E quando passavam os midianitas mercadores, tiraram eles a José da cisterna, e trouxeram-lhe acima, e o venderam aos ismaelitas por vinte peças de prata. E levaram a José ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'E Rúben voltou à cisterna, e não achou a José dentro, e rasgou suas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'E voltou a seus irmãos e disse: O jovem não aparece; e eu, aonde irei eu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Então eles tomaram a roupa de José, e degolaram um cabrito das cabras, e tingiram a roupa com o sangue;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'E enviaram a roupa de cores e trouxeram-na a seu pai, e disseram: Achamos isto, reconhece agora se é ou não a roupa de teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'E ele a reconheceu, e disse: A roupa de meu filho é; alguma fera selvagem o devorou; José foi despedaçado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Então Jacó rasgou suas roupas, e pôs saco sobre seus lombos, e fez luto por seu filho muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'E levantaram-se todos os seus filhos e todas as suas filhas para consolá-lo; mas ele não quis tomar consolação, e disse: Porque eu tenho de descer a meu filho com luto até à sepultura. E chorou por ele seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'E os midianitas o venderam no Egito a Potifar, oficial de Faraó, capitão dos da guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'E aconteceu naquele tempo, que Judá desceu da presença de seus irmãos, e foi-se a um homem adulamita, que se chamava Hira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'E viu ali Judá a filha de um homem cananeu, o qual se chamava Sua; e tomou-a, e se deitou com ela:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'A qual concebeu, e deu à luz um filho; e chamou seu nome Er.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'E concebeu outra vez, e deu à luz um filho, e chamou seu nome Onã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'E voltou a conceber, e deu à luz um filho, e chamou seu nome Selá. E estava em Quezibe quando o deu à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'E Judá tomou mulher para seu primogênito Er, a qual se chamava Tamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'E Er, o primogênito de Judá, foi mau aos olhos do SENHOR, e tirou-lhe o SENHOR a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Então Judá disse a Onã: Deita-te com mulher de teu irmão, e casa-te com ela, e suscita descendência a teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'E sabendo Onã que a descendência não havia de ser sua, sucedia que quando se deitava com mulher de seu irmão derramava em terra, para não dar descendência a seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'E desagradou aos olhos do SENHOR o que fazia, e também tirou a ele a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'E Judá disse a Tamar sua nora: Fica-te viúva em casa de teu pai, até que cresça Selá meu filho; porque disse: Para que não aconteça que morra ele também como seus irmãos. E foi-se Tamar, e ficou em casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'E passaram muitos dias, e morreu a filha de Sua, mulher de Judá; e Judá se consolou, e subia aos tosquiadores de suas ovelhas a Timna, ele e seu amigo Hira o adulamita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'E foi dado aviso a Tamar, dizendo: Eis que teu sogro sobe a Timna a tosquiar suas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Então tirou ela de sobre si as roupas de sua viuvez, e cobriu-se com um véu, e envolveu-se, e se pôs à porta das águas que estão junto ao caminho de Timna; porque via que havia crescido Selá, e ela não era dada a ele por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'E viu-a Judá, e teve-a por prostituta, porque havia ela coberto seu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'E desviou-se do caminho até ela, e disse-lhe: Eia, pois, agora deitarei contigo; porque não sabia que era sua nora; e ela disse: Que me darás, se deitares comigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Ele respondeu: Eu te enviarei do gado um cabrito das cabras. E ela disse: Terás de me dar penhor até que o envies.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Então ele disse: Que penhor te darei? Ela respondeu: Teu anel, e teu manto, e teu bordão que tens em tua mão. E ele lhe deu, e se deitou com ela, a qual concebeu dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'E levantou-se, e foi-se: e tirou o véu de sobre si, e vestiu-se das roupas de sua viuvez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'E Judá enviou o cabrito das cabras por meio de seu amigo o adulamita, para que tomasse o penhor da mão da mulher; mas não a achou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'E perguntou aos homens daquele lugar, dizendo: Onde está a prostituta das águas junto ao caminho? E eles lhe disseram: Não esteve aqui prostituta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Então ele se voltou a Judá, e disse: Não a achei; e também os homens do lugar disseram: Aqui não esteve prostituta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'E Judá disse: Tome ela dessas coisas para si, para que não sejamos menosprezados: eis que eu enviei este cabrito, e tu não a achaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'E aconteceu que ao fim de uns três meses foi dado aviso a Judá, dizendo: Tamar tua nora cometeu imoralidade sexual, e além disso está grávida das promiscuidades. E Judá disse: Tirai-a, e seja queimada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'E ela quando a tiravam, enviou a dizer a seu sogro: Do homem a quem pertence estas coisas, estou grávida: e disse mais: Olha agora a quem pertence estas coisas, o anel, e o manto, e o bordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Então Judá os reconheceu, e disse: Mais justa é que eu, porquanto não a dei a Selá meu filho. E nunca mais a conheceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'E aconteceu que ao tempo de dar à luz, eis que havia dois em seu ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'E sucedeu, quando dava à luz, que tirou a mão um, e a parteira tomou e amarrou à sua mão um fio de escarlate, dizendo: Este saiu primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Porém foi que voltando ele a recolher a mão, eis que seu irmão saiu; e ela disse: Como fizeste sobre ti rompimento? E chamou seu nome Perez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'E depois saiu seu irmão, o que tinha em sua mão o fio de escarlate, e chamou seu nome Zerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'E levado José ao Egito, comprou-o Potifar, oficial de Faraó, capitão dos da guarda, homem egípcio, da mão dos ismaelitas que o haviam levado ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Mas o SENHOR foi com José, e foi homem próspero: e estava na casa de seu senhor o egípcio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'E viu seu senhor que o SENHOR era com ele, e que tudo o que ele fazia, o SENHOR o fazia prosperar em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Assim achou José favor em seus olhos, e servia-lhe; e ele lhe fez mordomo de sua casa, e entregou em seu poder tudo o que tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'E aconteceu que, desde quando lhe deu o encargo de sua casa, e de tudo o que tinha, o SENHOR abençoou a casa do egípcio por causa de José; e a bênção do SENHOR foi sobre tudo o que tinha, tanto em casa como no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'E deixou tudo o que tinha em mão de José; nem com ele sabia de nada mais que do pão que comia. E era José de belo semblante e bela presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'E aconteceu depois disto, que a mulher de seu senhor pôs seus olhos em José, e disse: Dorme comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'E ele não quis, e disse à mulher de seu senhor: Eis que meu senhor não sabe comigo o que há em casa, e pôs em minha mão tudo o que tem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Não há outro maior que eu nesta casa, e nenhuma coisa me há reservado a não ser a ti, porquanto tu és sua mulher; como, pois, faria eu este grande mal e pecaria contra Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'E foi que falando ela a José cada dia, e não escutando-a ele para deitar-se ao lado dela, para estar com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Aconteceu que entrou ele um dia em casa para fazer seu ofício, e não havia ninguém dos da casa ali em casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'E pegou-o ela por sua roupa, dizendo: Dorme comigo. Então ele deixou sua roupa nas mãos dela, e fugiu, e saiu-se fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'E aconteceu que quando viu ela que lhe havia deixado sua roupa em suas mãos, e havia fugido fora,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Chamou aos de casa, e falou-lhes dizendo: Olhai que ele nos trouxe um hebreu, para que fizesse zombaria de nós: veio ele a mim para dormir comigo, e eu dei grandes vozes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'E vendo que eu erguia a voz e gritava, deixou junto a mim sua roupa, e fugiu, e saiu-se fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'E ela pôs junto a si a roupa dele, até que veio seu senhor à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Então lhe falou ela semelhantes palavras, dizendo: O servo hebreu que nos trouxeste, veio a mim para desonrar-me;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'E quando eu levantei minha voz e gritei, ele deixou sua roupa junto a mim, e fugiu fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'E sucedeu que quando ouviu seu senhor as palavras que sua mulher lhe falara, dizendo: Assim me tratou teu servo; acendeu-se seu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'E tomou seu senhor a José, e pôs-lhe na casa do cárcere, onde estavam os presos do rei, e esteve ali na casa do cárcere.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mas o SENHOR foi com José, e estendeu a ele sua misericórdia, e deu-lhe favor aos olhos do chefe da casa do cárcere.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'E o chefe da casa do cárcere entregou em mão de José todos os presos que havia naquela prisão; tudo o que faziam ali, ele o fazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Não via o chefe do cárcere coisa alguma que em sua mão estava; porque o SENHOR era com ele, e o que ele fazia, o SENHOR o fazia prosperar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'E aconteceu depois destas coisas, que o copeiro do rei do Egito e o padeiro transgrediram contra seu senhor o rei do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'E irou-se Faraó contra seus dois eunucos, contra o principal dos copeiros, e contra o principal dos padeiros:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'E os pôs em prisão na casa do capitão dos da guarda, na casa do cárcere onde José estava preso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'E o capitão dos da guarda deu responsabilidade deles a José, e ele lhes servia: e estiveram dias na prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'E ambos, o copeiro e o padeiro do rei do Egito, que estavam detidos na prisão, viram um sonho, cada um seu sonho em uma mesma noite, cada um conforme a declaração de seu sonho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'E veio a eles José pela manhã, e olhou-os, e eis que estavam tristes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'E ele perguntou àqueles oficiais de Faraó, que estavam com ele na prisão da casa de seu senhor, dizendo: Por que parecem hoje mal vossos semblantes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'E eles lhe disseram: Tivemos um sonho, e não há quem o declare. Então lhes disse José: Não são de Deus as interpretações? Contai-o a mim agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Então o chefe dos copeiros contou seu sonho a José, e disse-lhe: Eu sonhava que via uma vide diante de mim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'E na vide três sarmentos; e ela como que brotava, e surgia sua flor, vindo a amadurecer seus cachos de uvas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'E que o copo de Faraó estava em minha mão, e tomava eu as uvas, e as espremia no copo de Faraó, e dava eu o copo em mão de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'E disse-lhe José: Esta é sua declaração: Os três sarmentos são três dias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Ao fim de três dias Faraó te fará levantar a cabeça, e te restituirá a teu posto: e darás o copo a Faraó em sua mão, como costumavas quando eras seu copeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Lembra-te, pois, de mim para contigo quando tiveres esse bem, e rogo-te que uses comigo de misericórdia, e faças menção de mim a Faraó, e me tires desta prisão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Porque furtado fui da terra dos hebreus; e tampouco fiz aqui para que me houvessem de pôr no cárcere.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'E vendo o chefe dos padeiros que havia interpretado para o bem, disse a José: Também eu sonhava que via três cestos brancos sobre minha cabeça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'E no cesto mais alto havia de todos os alimentos de Faraó, obra de padeiro; e que as aves as comiam do cesto de sobre minha cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Então respondeu José, e disse: Esta é sua declaração: Os três cestos três dias são;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Ao fim de três dias tirará Faraó tua cabeça de sobre ti, e te fará enforcar na forca, e as aves comerão tua carne de sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'E foi o terceiro dia o dia do aniversário de Faraó, e fez banquete a todos os seus servos: e levantou a cabeça do chefe dos copeiros, e a cabeça do chefe dos padeiros, entre seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'E fez voltar a seu ofício ao chefe dos copeiros; e deu ele o copo em mão de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Mas fez enforcar ao principal dos padeiros, como lhe havia declarado José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'E o chefe dos copeiros não se lembrou de José, ao invés disso lhe esqueceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'E aconteceu que passados dois anos teve Faraó um sonho: Parecia-lhe que estava junto ao rio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'E que do rio subiam sete vacas, belas à vista, e muito gordas, e pastavam entre os juncos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'E que outras sete vacas subiam depois delas do rio, de feia aparência, e magras de carne, e pararam perto das vacas belas à beira do rio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'E que as vacas de feia aparência e magras de carne devoravam as sete vacas belas e muito gordas. E despertou Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Dormiu de novo, e sonhou a segunda vez: Que sete espigas cheias e belas subiam de uma só haste:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'E que outras sete espigas miúdas e abatidas do vento oriental, saíam depois delas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'E as sete espigas miúdas devoravam as sete espigas espessas e cheias. E despertou Faraó, e eis que era sonho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'E aconteceu que à manhã estava movido seu espírito; e enviou e fez chamar a todos os magos do Egito, e a todos os seus sábios: e contou-lhes Faraó seus sonhos, mas não havia quem a Faraó os interpretasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Então o chefe dos copeiros falou a Faraó, dizendo: Lembro-me hoje de minhas faltas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraó se irou contra seus servos, e a mim me lançou à prisão da casa do capitão dos da guarda, a mim e ao chefe dos padeiros:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'E eu e ele vimos um sonho uma mesma noite: cada um sonhou conforme a interpretação de seu sonho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'E estava ali conosco um jovem hebreu, servente do capitão dos da guarda; e o contamos a ele, e ele nos interpretou nossos sonhos, e interpretou a cada um conforme seu sonho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'E aconteceu que como ele nos interpretou, assim foi: a mim me fez voltar a meu posto, e fez enforcar ao outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Então Faraó enviou e chamou a José; e fizeram-lhe sair correndo do cárcere; e ele rapou-se a barba, mudou-se de roupas, e veio a Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'E disse Faraó a José: Eu tive um sonho, e não há quem o interprete; mas ouvi dizer de ti, que ouves sonhos para os interpretar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'E respondeu José a Faraó, dizendo: Não está em mim; Deus será o que responda paz a Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Então Faraó disse a José: Em meu sonho parecia-me que estava à beira do rio:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'E que do rio subiam sete vacas de gordas carnes e bela aparência, que pastavam entre os juncos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'E que outras sete vacas subiam depois delas, magras e de muito feio aspecto; tão abatidas, que não vi outras semelhantes em toda a terra do Egito em feiura:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'E as vacas magras e feias devoravam as sete primeiras vacas gordas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'E entravam em suas entranhas, mas não se conhecia que houvesse entrado nelas, porque sua aparência era ainda má, como de antes. E eu despertei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Vi também sonhando, que sete espigas subiam em uma mesma haste, cheias e belas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'E que outras sete espigas miúdas, definhadas, abatidas do vento oriental, subiam depois delas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'E as espigas miúdas devoravam as sete espigas belas: e disse-o aos magos, mas não há quem o interprete a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Então respondeu José a Faraó: O sonho de Faraó é um mesmo: Deus mostrou a Faraó o que vai fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'As sete vacas belas são sete anos, e as espigas belas são sete anos; o sonho é um mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Também as sete vacas magras e feias que subiam atrás elas, são sete anos; e as sete espigas miúdas e definhadas do vento oriental serão sete anos de fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Isto é o que respondo a Faraó. O que Deus vai fazer, mostrou-o a Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Eis que vêm sete anos de grande fartura toda a terra do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'E se levantarão depois eles sete anos de fome; e toda a fartura será esquecida na terra do Egito; e a fome consumirá a terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'E aquela abundância não mais será vista por causa da fome seguinte, a qual será gravíssima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'E o suceder o sonho a Faraó duas vezes, significa que a coisa é firme da parte de Deus, e que Deus se apressa a fazê-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Portanto, providencie Faraó agora um homem prudente e sábio, e ponha-o sobre a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Faça isto Faraó, e ponha governadores sobre o país, e tome a quinta parte da terra do Egito nos sete anos da fartura;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'E juntem toda a provisão destes bons anos que vêm, e acumulem o trigo sob a mão de Faraó para mantimento das cidades; e guardem-no.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'E esteja aquela provisão em depósito para o país, para os sete anos de fome que serão na terra do Egito; e o país não perecerá de fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'E o negócio pareceu bem a Faraó, e a seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'E disse Faraó a seus servos: Acharemos outro homem como este, em quem haja espírito de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'E disse Faraó a José: Pois que Deus te fez saber tudo isto, não há entendido nem sábio como tu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tu serás sobre minha casa, e pelo que disseres se governará todo o meu povo; somente no trono serei eu maior que tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Disse mais Faraó a José: Eis que te pus sobre toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Então Faraó tirou seu anel de sua mão, e o pôs na mão de José, e fez-lhe vestir de roupas de linho finíssimo, e pôs um colar de ouro em seu pescoço;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'E o fez subir em seu segundo carro, e proclamaram diante dele: Dobrai os joelhos; e pôs-lhe sobre toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'E disse Faraó a José: Eu sou Faraó; e sem ti ninguém levantará sua mão nem seu pé toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'E chamou Faraó o nome de José, Zefenate-Paneia; e deu-lhe por mulher a Azenate, filha de Potífera, sacerdote de Om. E saiu José por toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'E era José de idade de trinta anos quando foi apresentado diante de Faraó, rei do Egito: e saiu José de diante de Faraó, e transitou por toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'E fez a terra naqueles sete anos de fartura a amontoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'E ele juntou todo o mantimento dos sete anos que foram na terra do Egito, e guardou mantimento nas cidades, pondo em cada cidade o mantimento do campo de seus arredores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'E ajuntou José trigo como areia do mar, muito em extremo, até não se poder contar, porque não tinha número.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'E nasceram a José dois filhos antes que viesse o primeiro ano da fome, os quais lhe deu à luz Azenate, filha de Potífera, sacerdote de Om.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'E chamou José o nome do primogênito Manassés; porque disse: Deus me fez esquecer todo o meu sofrimento, e toda a casa de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'E o nome do segundo chamou-o Efraim; porque disse: “Deus me fez frutífero na terra de minha aflição”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'E cumpriram-se os sete anos da fartura, que houve na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'E começaram a vir os sete anos de fome, como José havia dito; e houve fome em todos os países, mas em toda a terra do Egito havia pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'E quando se sentiu a fome toda a terra do Egito, o povo clamou a Faraó por pão. E disse Faraó a todos os egípcios: Ide a José, e fazei o que ele vos disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'E a fome estava por toda a extensão do país. Então abriu José todo depósito de grãos onde havia, e vendia aos egípcios; porque havia crescido a fome na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'E toda a terra vinha ao Egito para comprar de José, porque por toda a terra havia aumentado a fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'E vendo Jacó que no Egito havia alimentos, disse a seus filhos: Por que estais olhando uns para os outros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'E disse: Eis que, eu ouvi que há alimentos no Egito; descei ali, e comprai dali para nós, para que possamos viver, e não nos morramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'E desceram os dez irmãos de José a comprar trigo ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mas Jacó não enviou a Benjamim irmão de José com seus irmãos; porque disse: Não seja acaso que lhe aconteça algum desastre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'E vieram os filhos de Israel a comprar entre os que vinham: porque havia fome na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'E José era o senhor da terra, que vendia a todo o povo da terra: e chegaram os irmãos de José, e inclinaram-se a ele rosto por terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'E José quando viu seus irmãos, reconheceu-os; mas fez que não os conhecesse, e falou-lhes asperamente, e lhes disse: De onde viestes? Eles responderam: Da terra de Canaã, para comprar alimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'José, pois, reconheceu a seus irmãos; mas eles não o reconheceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Então se lembrou José dos sonhos que havia tido deles, e disse-lhes: Sois espias; viestes ver a fraqueza do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'E eles lhe responderam: Não, meu senhor; teus servos vieram comprar alimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Todos nós somos filhos de um homem; somos homens honestos; teus servos nunca foram espias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'E ele lhes disse: Não; viestes ver a fraqueza do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'E eles responderam: Teus servos somos doze irmãos, filhos de um homem na terra de Canaã; e eis que o menor está hoje com nosso pai, e outro desapareceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'E José lhes disse: Isso é o que vos disse, afirmando que sois espias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Nisto sereis provados: Vive Faraó que não saireis daqui, a não ser quando vosso irmão menor vier aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Enviai um de vós, e traga a vosso irmão; e vós ficai presos, e vossas palavras serão provadas, se há verdade convosco: e se não, vive Faraó, que sois espias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'E juntou-os no cárcere por três dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'E ao terceiro dia disse-lhes José: Fazei isto, e vivei; eu temo a Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Se sois homens honestos, fique preso na casa de vosso cárcere um de vossos irmãos; e vós ide, levai o alimento para a fome de vossa casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Porém haveis de trazer-me a vosso irmão mais novo, e serão comprovadas vossas palavras, e não morrereis. E eles o fizeram assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'E diziam um ao outro: Verdadeiramente pecamos contra nosso irmão, que vimos a angústia de sua alma quando nos rogava, e não o ouvimos; por isso veio sobre nós esta angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Então Rúben lhes respondeu, dizendo: Não vos falei eu e disse: Não pequeis contra o jovem; e não escutastes? Eis que também o sangue dele é requerido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'E eles não sabiam que os entendia José, porque havia intérprete entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'E apartou-se ele deles, e chorou: depois voltou a eles, e lhes falou, e tomou dentre eles a Simeão, e aprisionou-lhe à vista deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'E mandou José que enchessem seus sacos de trigo, e devolvessem o dinheiro de cada um deles, pondo-o em seu saco, e lhes dessem comida para o caminho; e fez-se assim com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'E eles puseram seu trigo sobre seus asnos, e foram-se dali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'E abrindo um deles seu saco para dar de comer a seu asno no lugar de parada, viu seu dinheiro que estava na boca de seu saco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'E disse a seus irmãos: Meu dinheiro se me foi devolvido, e ainda ei-lo aqui em meu saco. Alarmou-se, então, o coração deles e, espantados, disseram um ao outro: Que é isto que Deus nos fez?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'E vindos a Jacó seu pai em terra de Canaã, contaram-lhe tudo o que lhes havia acontecido, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Aquele homem, senhor da terra, nos falou asperamente, e nos tratou como espias da terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'E nós lhe dissemos: Somos homens honestos, nunca fomos espias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Somos doze irmãos, filhos de nosso pai; um desapareceu, e o menor está hoje com nosso pai na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'E aquele homem, senhor da terra, nos disse: Nisto conhecerei que sois homens honestos; deixai comigo um de vossos irmãos, e tomai para a fome de vossas casas, e ide,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'E trazei-me a vosso irmão o mais novo, para que eu saiba que não sois espias, mas sim homens honestos: assim vos darei a vosso irmão, e negociareis na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'E aconteceu que esvaziando eles seus sacos, eis que no saco de cada um estava o pacote de seu dinheiro: e vendo eles e seu pai os pacotes de seu dinheiro, tiveram temor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Então seu pai Jacó lhes disse: Vós me privastes de meus filhos; José desapareceu, nem Simeão tampouco, e a Benjamim o levareis; contra mim são todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'E Rúben falou a seu pai, dizendo: Podes matar meus dois filhos, se eu não o devolver a ti; entrega-o em minha mão, que eu o devolverei a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'E ele disse: Não descerá meu filho convosco; que seu irmão é morto, e ele somente restou; e se lhe acontecer algum desastre no caminho por onde vades, fareis descer minhas cãs com dor ao mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'E a fome era grande na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'E aconteceu que quando acabaram de comer o trigo que trouxeram do Egito, disse-lhes seu pai: Voltai, e comprai para nós um pouco de alimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'E respondeu Judá, dizendo: Aquele homem nos advertiu com ânimo decidido, dizendo: Não vereis meu rosto sem vosso irmão convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Se enviares a nosso irmão conosco, desceremos e te compraremos alimento:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Porém se não lhe enviares, não desceremos: porque aquele homem nos disse: Não vereis meu rosto sem vosso irmão convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'E disse Israel: Por que me fizestes tanto mal, declarando ao homem que tínheis mais irmão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'E eles responderam: Aquele homem nos perguntou expressamente por nós, e por nossa parentela, dizendo: Vive ainda vosso pai? Tendes outro irmão? E lhe declaramos conforme estas palavras. Podíamos nós saber que havia de dizer: Fazei vir a vosso irmão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Então Judá disse a Israel seu pai: Envia ao jovem comigo, e nos levantaremos e iremos, a fim que vivamos e não morramos nós, e tu, e nossos filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Eu sou fiador dele; a mim me pedirás conta dele; se eu não o devolver a ti e o puser diante de ti, serei para ti o culpado todos os dias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Que se não nos tivéssemos detido, certo agora teríamos já voltado duas vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Então Israel seu pai lhes respondeu: Pois que assim é, fazei-o; tomai do melhor da terra em vossos vasos, e levai àquele homem um presente, um pouco de bálsamo, e um pouco de mel, aromas e mirra, nozes e amêndoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'E tomai em vossas mãos dobrado dinheiro, e levai em vossa mão o dinheiro que voltou nas bocas de vossos sacos; talvez tenha sido erro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Tomai também a vosso irmão, e levantai-vos, e voltai àquele homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'E o Deus Todo-Poderoso vos dê misericórdias diante daquele homem, e vos solte ao outro vosso irmão, e a este Benjamim. E se eu tiver de ser privado de meus filhos, assim seja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Então tomaram aqueles homens o presente, e tomaram em sua mão dobrado dinheiro, e a Benjamim; e se levantaram, e desceram ao Egito, e apresentaram-se diante de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'E viu José a Benjamim com eles, e disse ao mordomo de sua casa: Mete em casa a esses homens, e degola um animal, e prepara-o; porque estes homens comerão comigo ao meio-dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'E fez o homem como José disse; e meteu aquele homem aos homens em casa de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'E aqueles homens tiveram temor, quando foram metidos na casa de José, e diziam: Pelo dinheiro que voltou em nossos sacos a primeira vez nos trouxeram aqui, para virem contra nós, e nos atacar, e tomar por servos a nós, e a nossos asnos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'E aproximaram-se do mordomo da casa de José, e lhe falaram à entrada da casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'E disseram: Ai, senhor meu, nós em realidade de verdade descemos ao princípio a comprar alimentos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'E aconteceu que quando viemos ao lugar de parada e abrimos nossos sacos, eis que o dinheiro de cada um estava na boca de seu saco, nosso dinheiro em seu justo peso; e o devolvemos em nossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Trouxemos também em nossas mãos outro dinheiro para comprar alimentos: nós não sabemos quem pôs nosso dinheiro em nossos sacos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'E ele respondeu: Paz a vós, não temais; vosso Deus e o Deus de vosso pai vos deu o tesouro em vossos sacos: vosso dinheiro veio a mim. E tirou a Simeão a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'E aquele homem levou àqueles homens na casa de José: e deu-lhes água, e lavaram seus pés: e deu de comer a seus asnos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'E eles prepararam o presente antes que viesse José ao meio-dia, porque haviam ouvido que ali haviam de comer pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'E veio José a casa, e eles lhe trouxeram o presente que tinham em sua mão dentro de casa, e inclinaram-se a ele em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Então ele lhes perguntou como estavam, e disse: Vosso pai, o ancião que dissestes, passa bem? Vive ainda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'E eles responderam: Bem vai a teu servo nosso pai; ainda vive. E se inclinaram, e fizeram reverência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'E levantando ele seus olhos viu Benjamim seu irmão, filho de sua mãe, e disse: É este vosso irmão mais novo, de quem me falastes? E disse: Deus tenha misericórdia de ti, filho meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Então José se apressou, porque se comoveram suas entranhas por causa de seu irmão, e procurou onde chorar: e entrou-se em sua câmara, e chorou ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'E lavou seu rosto, e saiu fora, e controlou-se, e disse: Ponde pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'E puseram para ele à parte, e separadamente para eles, e à parte para os egípcios que com ele comiam: porque os egípcios não podem comer pão com os hebreus, o qual é abominação aos egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'E sentaram-se diante dele, o mais velho conforme sua primogenitura, e o mais novo conforme sua idade menor; e estavam aqueles homens atônitos olhando-se um ao outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'E ele tomou iguarias de diante de si para eles; mas a porção de Benjamim era cinco vezes como qualquer uma das deles. E beberam, e alegraram-se com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'E mandou José ao mordomo de sua casa, dizendo: Enche os sacos destes homens de alimentos, quanto puderem levar, e põe o dinheiro de cada um na boca de seu saco:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'E porás meu copo, o copo de prata, na boca do saco do mais novo, com o dinheiro de seu trigo. E ele fez como disse José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Vinda a manhã, os homens foram despedidos com seus asnos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Havendo eles saído da cidade, da qual ainda não haviam se afastado, disse José a seu mordomo: Levanta-te, e segue a esses homens; e quando os alcançares, dize-lhes: Por que retribuístes com o mal pelo bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Não é isto no que bebe meu senhor, e pelo que costuma adivinhar? Fizestes mal no que fizestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'E quando ele os alcançou, disse-lhes estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'E eles lhe responderam: Por que diz meu senhor tais coisas? Nunca tal façam teus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Eis que, o dinheiro que achamos na boca de nossos sacos, o voltamos a trazer a ti desde a terra de Canaã; como, pois, havíamos de furtar da casa de teu senhor prata nem ouro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Aquele de teus servos em quem for achado o copo, que morra, e ainda nós seremos servos de meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'E ele disse: Também agora seja conforme vossas palavras; aquele em quem se achar, será meu servo, e vós sereis sem culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Eles então se deram pressa, e derrubando cada um seu saco em terra, abriu cada qual o seu saco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'E buscou; desde o mais velho começou, e acabou no mais novo; e o copo foi achado no saco de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Então eles rasgaram suas roupas, e carregou cada um seu asno, e voltaram à cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'E chegou Judá com seus irmãos à casa de José, que ainda estava ali, e prostraram-se diante dele em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'E disse-lhes José: Que obra é esta que fizestes? Não sabeis que um homem como eu sabe adivinhar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Então disse Judá: Que diremos a meu senhor? Que falaremos? Ou com que nos justificaremos? Deus achou a maldade de teus servos: eis que, nós somos servos de meu senhor, nós, e também aquele em cujo poder foi achado o copo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'E ele respondeu: Nunca eu tal faça: o homem em cujo poder foi achado o copo, ele será meu servo; vós ide em paz a vosso pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Então Judá se chegou a ele, e disse: Ai senhor meu, rogo-te que fale teu servo uma palavra aos ouvidos de meu senhor, e não se acenda tua ira contra teu servo, pois que tu és como Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Meu senhor perguntou a seus servos, dizendo: Tendes pai ou irmão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'E nós respondemos a meu senhor: Temos um pai ancião, e um jovem que lhe nasceu em sua velhice, pequeno ainda; e um irmão seu morreu, e ele restou sozinho de sua mãe, e seu pai o ama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'E tu disseste a teus servos: Trazei-o a mim, e porei meus olhos sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'E nós dissemos a meu senhor: O jovem não pode deixar a seu pai, porque se o deixar, seu pai morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'E disseste a teus servos: Se vosso irmão mais novo não descer convosco, não vejais mais meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Aconteceu, pois, que quando chegamos a meu pai teu servo, nós lhe contamos as palavras de meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'E disse nosso pai: Voltai a comprar-nos um pouco de alimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'E nós respondemos: Não podemos ir: se nosso irmão for conosco, iremos; porque não podemos ver o rosto do homem, não estando conosco nosso irmão o mais novo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Então teu servo meu pai nos disse: Vós sabeis que dois me deu minha mulher;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'E um saiu de minha presença, e penso certamente que foi despedaçado, e até agora não o vi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'E se tomardes também este de diante de mim, e lhe acontecer algum desastre, fareis descer minhas cãs com dor ao mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Agora, pois, quando chegar eu a teu servo meu pai, e o jovem não for comigo, como sua alma está ligada à alma dele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Sucederá que quando perceber a ausência do jovem, morrerá; e teus servos farão descer as cãs de teu servo nosso pai com dor ao mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Como teu servo saiu por fiador do jovem com meu pai, dizendo: Se eu não o devolver a ti, então eu serei culpável para meu pai todos os dias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Rogo-te, portanto, que fique agora teu servo pelo jovem por servo de meu senhor, e que o jovem vá com seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Porque como irei eu a meu pai sem o jovem? Não poderei, por não ver o mal que sobrevirá a meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Não podia já José se conter diante de todos os que estavam ao seu lado, e clamou: Fazei sair de minha presença a todos. E não ficou ninguém com ele, ao dar-se a conhecer José a seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Então se deu a chorar por voz em grito; e ouviram os egípcios, e ouviu também a casa de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'E disse José a seus irmãos: Eu sou José: vive ainda meu pai? E seus irmãos não puderam lhe responder, porque estavam perturbados diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Então disse José a seus irmãos: Achegai-vos agora a mim. E eles se achegaram. E ele disse: Eu sou José vosso irmão o que vendestes para o Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Agora, pois, não vos entristeçais, nem vos pese de haver me vendido aqui; que para preservação de vida me enviou Deus diante de vós:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Que já houve dois anos de fome em meio da terra, e ainda restam cinco anos em que nem haverá arada nem colheita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'E Deus me enviou adiante de vós, para que vós restásseis na terra, e para vos dar vida por meio de grande salvamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Assim, pois, não me enviastes vós aqui, mas sim Deus, que me pôs por pai de Faraó, e por senhor de toda sua casa, e por governador de toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Apressai-vos, ide a meu pai e dizei-lhe: Assim diz teu filho José: Deus me pôs por senhor de todo Egito; vem a mim, não te detenhas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'E habitarás na terra de Gósen, e estarás perto de mim, tu e teus filhos, e os filhos de teus filhos, teus gados e tuas vacas, e tudo o que tens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'E ali te alimentarei, pois ainda restam cinco anos de fome, para que não pereças de pobreza tu e tua casa, e tudo o que tens:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'E eis que, vossos olhos veem, e os olhos de meu irmão Benjamim, que meu boca vos fala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Fareis pois saber a meu pai toda minha glória no Egito, e tudo o que vistes: e apressai-vos, e trazei a meu pai aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'E lançou-se sobre o pescoço de Benjamim seu irmão, e chorou; e também Benjamim chorou sobre seu pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'E beijou a todos os seus irmãos, e chorou sobre eles: e depois seus irmãos falaram com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'E ouviu-se a notícia na casa de Faraó, dizendo: Os irmãos de José vieram. E pareceu bem aos olhos de Faraó e de seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'E disse Faraó a José: Dize a teus irmãos: Fazei isto: carregai vossos animais, e ide, voltai à terra de Canaã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'E tomai a vosso pai e vossas famílias, e vinde a mim, que eu vos darei o bom da terra do Egito e comereis a gordura da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'E tu manda: Fazei isto: tomai para vós da terra do Egito carros para vossos filhos e vossas mulheres; e tomai a vosso pai, e vinde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'E não se vos dê nada de vossos pertences, porque o bem da terra do Egito será vosso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'E fizeram-no assim os filhos de Israel: e deu-lhes José carros conforme a ordem de Faraó, e deu alimentos para o caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'A cada um de todos eles deu mudas de roupas, e a Benjamim deu trezentas peças de prata, e cinco mudas de roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'E a seu pai enviou isto: dez asnos carregados do melhor do Egito, e dez asnas carregadas de trigo, e pão e comida, para seu pai no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'E despediu a seus irmãos, e foram-se. E ele lhes disse: Não brigais pelo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'E subiram do Egito, e chegaram à terra de Canaã a Jacó seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'E deram-lhe as novas, dizendo: José vive ainda; e ele é senhor toda a terra do Egito. E seu coração se desmaiou; pois não cria neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'E eles lhe contaram todas as palavras de José, que ele lhes havia falado; e vendo ele os carros que José enviava para levá-lo, o espírito de Jacó seu pai reviveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Então disse Israel: Basta; José meu filho vive ainda: irei, e lhe verei antes que eu morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'E partiu-se Israel com tudo o que tinha, e veio a Berseba, e ofereceu sacrifícios ao Deus de seu pai Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'E falou Deus a Israel em visões de noite, e disse: Jacó, Jacó. E ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'E disse: Eu sou Deus, o Deus de teu pai; não temas de descer ao Egito, porque eu te farei ali em grande nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Eu descerei contigo ao Egito, e eu também te farei voltar; e José porá sua mão sobre teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'E levantou-se Jacó de Berseba; e tomaram os filhos de Israel a seu pai Jacó, e a seus filhos, e a suas mulheres, nos carros que Faraó havia enviado para levá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'E tomaram seus gados, e sua riqueza que havia adquirido na terra de Canaã, e vieram-se ao Egito, Jacó, e toda sua descendência consigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Seus filhos, e os filhos de seus filhos consigo; suas filhas, e as filhas de seus filhos, e a toda sua descendência trouxe consigo ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'E estes são os nomes dos filhos de Israel, que entraram no Egito, Jacó e seus filhos: Rúben, o primogênito de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'E os filhos de Rúben: Enoque, e Palu, e Hezrom, e Carmi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'E os filhos de Simeão: Jemuel, e Jamim, e Oade, e Jaquim, e Zoar, e Saul, filho da cananeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'E os filhos de Levi: Gérson, Coate, e Merari.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'E os filhos de Judá: Er, e Onã, e Selá, e Perez, e Zerá: mas Er e Onã, morreram na terra de Canaã. E os filhos de Perez foram Hezrom e Hamul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'E os filhos de Issacar: Tola, e Puva, e Jó, e Sinrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'E os filhos de Zebulom: Serede e Elom, e Jaleel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Estes foram os filhos de Lia, os que deu a Jacó em Padã-Arã, e além de sua filha Diná: trinta e três as almas todas de seus filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'E os filhos de Gade: Zifiom, e Hagi, e Suni, e Ezbom, e Eri, e Arodi, e Areli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'E os filhos de Aser: Imna, e Isva, e Isvi y Berias, e Sera, irmã deles. Os filhos de Berias: Héber, e Malquiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Estes foram os filhos de Zilpa, a que Labão deu a sua filha Lia, e deu estes a Jacó; todas dezesseis almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'E os filhos de Raquel, mulher de Jacó: José e Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'E nasceram a José na terra do Egito Manassés e Efraim, os que lhe deu Azenate, filha Potífera, sacerdote de Om.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'E os filhos de Benjamim foram Belá, e Bequer e Asbel, e Gera, e Naamã, e Eí, e Rôs e Mupim, e Hupim, e Arde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Estes foram os filhos de Raquel, que nasceram a Jacó: ao todo, catorze almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'E os filhos de Dã: Husim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'E os filhos de Naftali: Jazeel, e Guni, e Jezer, e Silém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Estes foram os filhos de Bila, a que deu Labão a Raquel sua filha, e ela deu à luz estes a Jacó; todas sete almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Todas as pessoas que vieram com Jacó ao Egito, procedentes de seus lombos, sem as mulheres dos filhos de Jacó, todas as pessoas foram sessenta e seis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'E os filhos de José, que lhe nasceram no Egito, duas pessoas. Todas as almas da casa de Jacó, que entraram no Egito, foram setenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'E enviou a Judá adiante de si a José, para que lhe viesse a ver a Gósen; e chegaram à terra de Gósen.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'E José preparou seu carro e veio a receber a Israel seu pai a Gósen; e se manifestou a ele, e lançou-se sobre seu pescoço, e chorou sobre seu pescoço bastante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Então Israel disse a José: Morra eu agora, já que vi teu rosto, pois ainda vives.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'E José disse a seus irmãos, e à casa de seu pai: Subirei e farei saber a Faraó, e lhe direi: Meus irmãos e a casa de meu pai, que estavam na terra de Canaã, vieram a mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'E os homens são pastores de ovelhas, porque são homens criadores de gado: e trouxeram suas ovelhas e suas vacas, e tudo o que tinham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'E quando Faraó vos chamar e disser: qual é vosso ofício?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Então direis: Homens de criação de gado foram teus servos desde nossa juventude até agora, nós e nossos pais; a fim que moreis na terra de Gósen, porque os egípcios abominam todo pastor de ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'E José veio, e fez saber a Faraó, e disse: Meu pai e meus irmãos, e suas ovelhas e suas vacas, com tudo o que têm, vieram da terra de Canaã, e eis que, estão na terra de Gósen.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'E dentre seus irmãos tomou cinco homens, e os apresentou diante de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'E Faraó disse a seus irmãos: Qual é vosso ofício? E eles responderam a Faraó: Pastores de ovelhas são teus servos, tanto nós como nossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Disseram ademais a Faraó: Por morar nesta terra viemos; porque não há pasto para as ovelhas de teus servos, pois a fome é grave na terra de Canaã: portanto, te rogamos agora que habitem teus servos na terra de Gósen.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Então Faraó falou a José, dizendo: Teu pai e teus irmãos vieram a ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'A terra do Egito diante de ti está; no melhor da terra faze habitar a teu pai e a teus irmãos; habitem na terra de Gósen; e se entendes que há entre eles homens competentes, põe-os por administradores do meu gado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'E José introduziu a seu pai, e apresentou-o diante de Faraó; e Jacó abençoou a Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'E disse Faraó a Jacó: Quantos são os dias dos anos de tua vida?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'E Jacó respondeu a Faraó: Os dias dos anos de minha peregrinação são cento e trinta anos; poucos e maus foram os dias dos anos de minha vida, e não chegaram aos dias dos anos da vida de meus pais nos dias de sua peregrinação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'E Jacó abençoou a Faraó, e saiu-se de diante de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Assim José fez habitar a seu pai e a seus irmãos, e deu-lhes possessão na terra do Egito, no melhor da terra, na terra de Ramessés como mandou Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'E alimentava José a seu pai e a seus irmãos, e a toda a casa de seu pai, de pão, segundo o número de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'E não havia pão toda a terra, e a fome era muito grave; pelo que desfaleceu de fome a terra do Egito e a terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'E recolheu José todo o dinheiro que se achou na terra do Egito e na terra de Canaã, pelos alimentos que dele compravam; e meteu José o dinheiro na casa de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'E acabado o dinheiro da terra do Egito e da terra de Canaã, veio todo Egito a José dizendo: Dá-nos pão: por que morreremos diante de ti, por haver-se acabado o dinheiro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'E José disse: Dai vossos gados, e eu vos darei por vossos gados, se se acabou o dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'E eles trouxeram seus gados a José; e José lhes deu alimentos por cavalos, e pelo rebanho das ovelhas, e pelo rebanho das vacas, e por asnos: e sustentou-os de pão por todos os seus gados aquele ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'E acabado aquele ano, vieram a ele o segundo ano, e lhe disseram: Não encobriremos a nosso senhor que o dinheiro certamente se acabou; também o gado é já de nosso senhor; nada restou diante de nosso senhor a não ser nossos corpos e nossa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Por que morreremos diante de teus olhos, tanto nós como nossa terra? Compra a nós e a nossa terra por pão, e seremos nós e nossa terra servos de Faraó; e dá-nos semente para que vivamos e não morramos, e não seja assolada a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Então comprou José toda a terra do Egito para Faraó; pois os egípcios venderam cada um suas terras, porque se agravou a fome sobre eles: e a terra veio a ser de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'E ao povo o fez passar às cidades desde um fim do termo do Egito até o outro fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Somente a terra dos sacerdotes não comprou, porquanto os sacerdotes tinham ração de Faraó, e eles comiam sua ração que Faraó lhes dava: por isso não venderam sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'E José disse ao povo: Eis que comprei hoje vós e vossa terra para Faraó: vede aqui semente, e semeareis a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'E será que dos frutos dareis o quinto a Faraó, e as quatro partes serão vossas para semear as terras, e para vosso mantimento, e dos que estão em vossas casas, e para que comam vossos meninos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'E eles responderam: A vida nos deste: achemos favor aos olhos de meu senhor, e sejamos servos de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Então José o pôs por estatuto até hoje sobre a terra do Egito, assinalando para Faraó o quinto; exceto somente a terra dos sacerdotes, que não foi de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Assim habitou Israel na terra do Egito, na terra de Gósen; e apossaram-se nela, y se aumentaram, e multiplicaram em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'E viveu Jacó na terra do Egito dezessete anos: e foram os dias de Jacó, os anos de sua vida, cento quarenta e sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'E achegaram-se os dias de Israel para morrer, e chamou a José seu filho, e lhe disse: Se achei agora favor em teus olhos, rogo-te que ponhas tua mão debaixo de minha coxa, e farás comigo misericórdia e verdade; rogo-te que não me enterres no Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Mas quando dormir com meus pais, me levarás de Egito, e me sepultarás no sepulcro deles. E ele respondeu: Eu farei como tu dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'E ele disse: Jura-me isso. E ele lhe jurou. Então Israel se inclinou sobre a cabeceira da cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'E sucedeu depois destas coisas que foi dito a José: Eis que teu pai está enfermo. E ele tomou consigo seus dois filhos Manassés e Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'E se fez saber a Jacó, dizendo: Eis que teu filho José vem a ti. Então se esforçou Israel, e sentou-se sobre a cama;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'E disse a José: O Deus Todo-Poderoso me apareceu em Luz na terra de Canaã, e me abençoou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'E disse-me: Eis que, eu te farei crescer, e te multiplicarei, e te porei por conjunto de povos: e darei esta terra à tua descendência depois de ti por herança perpétua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'E agora teus dois filhos Efraim e Manassés, que te nasceram na terra do Egito, antes que viesse a ti à terra do Egito, meus são; como Rúben e Simeão, serão meus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'E os que depois deles geraste, serão teus; pelo nome de seus irmãos serão chamados em suas propriedades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Porque quando eu vinha de Padã-Arã, se me morreu Raquel na terra de Canaã, no caminho, como certa distância vindo a Efrata; e sepultei-a ali no caminho de Efrata, que é Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'E viu Israel os filhos de José, e disse: Quem são estes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'E respondeu José a seu pai: São meus filhos, que Deus me deu aqui. E ele disse: Achegai-os agora a mim, e os abençoarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'E os olhos de Israel estavam tão agravados da velhice, que não podia ver. Fez-lhes, pois, chegar a ele, e ele os beijou e abraçou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'E disse Israel a José: Não pensava eu ver teu rosto, e eis que Deus me fez ver também tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Então José os tirou dentre seus joelhos, e inclinou-se à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'E tomou-os José a ambos, Efraim à sua direita, à esquerda de Israel; e a Manassés à sua esquerda, à direita de Israel; e fez-lhes chegar a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Então Israel estendeu sua mão direita, e a pôs sobre a cabeça de Efraim, que era o mais novo, e sua esquerda sobre a cabeça de Manassés, colocando assim suas mãos propositadamente, ainda que Manassés era o primogênito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'E abençoou a José, e disse: O Deus em cuja presença andaram meus pais Abraão e Isaque, o Deus que me mantém desde que eu sou até hoje,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'O Anjo que me liberta de todo mal abençoe a estes moços: e meu nome seja chamado neles, e o nome de meus pais Abraão e Isaque: e multipliquem em grande maneira em meio da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Então vendo José que seu pai punha a direita sobre a cabeça de Efraim, causou-lhe isto desgosto; e pegou a mão de seu pai, para mudá-la de sobre a cabeça de Efraim à cabeça de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'E disse José a seu pai: Não assim, meu pai, porque este é o primogênito; põe tua mão direita sobre sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mas seu pai não quis, e disse: Eu sei, meu filho, eu sei: também ele virá a ser um povo, e será também acrescentado; porém seu irmão mais novo será maior que ele, e sua descendência será plenitude de povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'E abençoou-os aquele dia, dizendo: Em ti Israel abençoará, dizendo: Deus faça de ti Deus como a Efraim e como a Manassés. E pôs a Efraim diante de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'E disse Israel a José: Eis que eu morro, mas Deus será convosco, e vos fará voltar à terra de vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'E eu dei a ti uma parte sobre teus irmãos, a qual tomei eu da mão dos amorreus com minha espada e com meu arco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'E chamou Jacó a seus filhos, e disse: Juntai-vos, e vos declararei o que vos há de acontecer nos últimos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Juntai-vos e ouvi, filhos de Jacó; E escutai a vosso pai Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rúben, tu és meu primogênito, minha força, e o princípio do meu vigor; Principal em dignidade, principal em poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Corrente como as águas, não sejas o principal; Porquanto subiste ao leito de teu pai: Então te contaminaste, subindo a meu estrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeão e Levi, irmãos: Armas de violência são suas armas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Em seu secreto não entre minha alma, nem minha honra se junte em sua companhia; Que em seu furor mataram homem, E em sua vontade aleijaram bois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maldito seu furor, que foi bravio; E sua ira, que foi dura: Eu os dividirei em Jacó, E os espalharei em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judá, teus irmãos te louvarão: Tua mão esterá sobre o pescoço de teus inimigos: Os filhos de teu pai se inclinarão a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Jovem leão é Judá: Da presa subiste, filho meu: Encurvou-se, lançou-se como leão, Assim como leão velho; quem o despertará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Não será tirado o cetro de Judá, E o legislador dentre seus pés, Até que venha Siló; E a ele se congregarão os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Atando à vide seu jumentinho, E à videira o filho de sua jumenta, Lavou no veio sua roupa, E no sangue de uvas seu manto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Seus olhos mais vermelhos que o vinho, E os dentes mais brancos que o leite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulom em portos de mar habitará, E será para porto de navios; E seu termo até Sidom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issacar, asno de forte estrutura deitado entre dois apriscos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'E viu que o descanso era bom, E que a terra era deleitosa; E baixou seu ombro para levar, E serviu em tributo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dã julgará a seu povo, Como uma das tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Será Dã serpente junto ao caminho, víbora junto à vereda, que morde os calcanhares dos cavalos, e faz cair por detrás ao cavaleiro deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Tua salvação espero, ó SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gade, exército o atacará; mas ele contra-atacará ao fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'O pão de Aser será espesso, E ele dará deleites ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali, serva solta, que diz belas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Ramo frutífero é José, ramo frutífero é junto à fonte, cujos ramos se estendem sobre o muro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'E causaram-lhe amargura, e flecharam-lhe, e os arqueiros o odiaram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mas seu arco manteve-se forte, E os braços de suas mãos se fortaleceram pelas mãos do Forte de Jacó, (Dali é o Pastor, e a Pedra de Israel,)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Do Deus de teu pai, o qual te ajudará, E do Todo-Poderoso, o qual te abençoará com bênçãos dos céus de acima, com bênçãos do abismo que está abaixo, Com bênçãos do seio e da madre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'As bênçãos de teu pai Foram maiores que as bênçãos de meus progenitores: Até o termo das colinas eternas serão sobre a cabeça de José, E sobre o topo da cabeça do que foi separado de seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamim, lobo arrebatador; de manhã comerá a presa, e à tarde repartirá os despojos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Todos estes foram as doze tribos de Israel: e isto foi o que seu pai lhes disse, e os abençoou; a cada um por sua bênção os abençoou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Mandou-lhes logo, e disse-lhes: Eu vou a ser reunido com meu povo: sepultai-me com meus pais na caverna que está no campo de Efrom os heteus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'Na caverna que está no campo de Macpela, que está diante de Manre na terra de Canaã, a qual comprou Abraão com o mesmo campo de Efrom os heteus, para herança de sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Ali sepultaram a Abraão e a Sara sua mulher; ali sepultaram a Isaque e a Rebeca sua mulher; ali também sepultei Lia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'O campo e a cova que nele está foram comprados dos filhos de Hete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'E quando acabou Jacó de dar ordens a seus filhos, encolheu seus pés na cama, e expirou; e foi reunido com seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Então se lançou José sobre o rosto de seu pai, e chorou sobre ele, e o beijou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'E mandou José a seus servos médicos que embalsamassem a seu pai; e os médicos embalsamaram a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'E cumpriam-lhe quarenta dias, porque assim cumpriam os dias dos embalsamados, e choraram-no os egípcios setenta dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'E passados os dias de seu luto, falou José aos da casa de Faraó, dizendo: Se achei agora favor em vossos olhos, vos rogo que faleis aos ouvidos de Faraó, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Meu pai me fez jurar dizendo: Eis que eu morro; em meu sepulcro que eu cavei para mim na terra de Canaã, ali me sepultarás; rogo, pois, que vá eu agora, e sepultarei a meu pai, e voltarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'E Faraó disse: Vai, e sepulta a teu pai, como ele te fez jurar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Então José subiu a sepultar a seu pai; e subiram com ele todos os servos de Faraó, os anciãos de sua casa, e todos os anciãos da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'E toda a casa de José, e seus irmãos, e a casa de seu pai: somente deixaram na terra de Gósen seus filhos, e suas ovelhas e suas vacas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'E subiram também com ele carros e cavaleiros, e fez-se um esquadrão muito grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'E chegaram até a eira de Atade, que está à outra parte do Jordão, e lamentaram ali com grande e muito grave lamentação: e José fez a seu pai luto por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'E vendo os moradores da terra, os cananeus, o pranto na eira de Atade, disseram: Pranto grande é este dos egípcios: por isso foi chamado seu nome Abel-Mizraim, que está à outra parte do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Fizeram, pois, seus filhos com ele, segundo lhes havia mandado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Pois seus filhos o levaram à terra de Canaã, e o sepultaram na caverna do campo de Macpela, a que havia comprado Abraão com o mesmo campo, para herança de sepultura, de Efrom o heteu, diante de Manre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'E voltou José ao Egito, ele e seus irmãos, e todos os que subiram com ele a sepultar a seu pai, depois que o sepultou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'E vendo os irmãos de José que seu pai era morto, disseram: Talvez José nos odeie, e nos retribua de todo o mal que lhe fizemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'E enviaram a dizer a José: Teu pai mandou antes de sua morte, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Assim direis a José: Rogo-te que perdoes agora a maldade de teus irmãos e seu pecado, porque mal te trataram: portanto agora te rogamos que perdoes a maldade dos servos do Deus de teu pai. E José chorou enquanto falavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'E vieram também seus irmãos, e prostraram-se diante dele, e disseram: Eis-nos aqui por teus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'E respondeu-lhes José: Não temais: estou eu em lugar de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vós pensastes mal sobre mim, mas Deus o encaminhou para o bem, para fazer o que vemos hoje, para manter em vida muito povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Agora, pois, não tenhais medo; eu sustentarei a vós e a vossos filhos. Assim os consolou, e lhes falou ao coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'E esteve José no Egito, ele e a casa de seu pai; e viveu José cento dez anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'E viu José os filhos de Efraim até a terceira geração: também os filhos de Maquir, filho de Manassés, foram criados sobre os joelhos de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'E José disse a seus irmãos: Eu me morro; mas Deus certamente vos visitará, e vos fará subir desta terra à terra que jurou a Abraão, a Isaque, e a Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'E fez jurar José aos filhos de Israel, dizendo: Deus certamente vos visitará, e fareis levar daqui meus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'E morreu José da idade de cento e dez anos; e embalsamaram-no, e foi posto num caixão no Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Estes são os nomes dos filhos de Israel que entraram em Egito com Jacó; cada um entrou com sua família:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rúben, Simeão, Levi e Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issacar, Zebulom e Benjamim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dã e Naftali, Gade e Aser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Assim, todas as pessoas que descenderam do corpo de Jacó foram setenta. Porém José estava no Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Depois que morreram José, todos os seus irmãos, e toda aquela geração,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'os filhos de Israel cresceram e multiplicaram, e foram aumentados e fortalecidos grandemente; de maneira que a terra encheu-se deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Levantou-se, entretanto, um novo rei sobre o Egito, que não conhecia José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Ele disse ao seu povo: Eis que o povo dos filhos de Israel é maior e mais forte que nós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Agora, pois, sejamos astutos para com ele, a fim de que não se multiplique, e aconteça que caso venha guerra, ele se alie com nossos inimigos, lute contra nós, e saia do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Então puseram sobre o povo de Israel capatazes para os oprimirem com trabalhos forçados; e edificaram a Faraó as cidades de armazenamento, Pitom e Ramessés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Porém, quanto mais os oprimiam, mais se multiplicavam e cresciam. Por isso eles detestavam os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Assim os egípcios fizeram os filhos de Israel servirem duramente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'e amargaram a vida deles com dura servidão, em fazerem barro e tijolos, em todo trabalho do campo, e em todo o seu serviço, ao qual os obrigavam com rigor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'E o rei do Egito falou às parteiras das hebreias, uma das quais se chamava Sifrá, e outra Puá, e disse-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Quando fizerdes o parto das hebreias, e olhardes os assentos, se for filho, matai-o; e se for filha, então viva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mas as parteiras temeram a Deus, e não fizeram como o rei do Egito lhes mandara; em vez disso, preservaram a vida dos meninos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'E o rei do Egito mandou chamar às parteiras e lhes perguntou: Por que fizestes isto, que preservastes a vida dos meninos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'As parteiras responderam a Faraó: As mulheres hebreias não são como as egípcias; pois são fortes, de maneira que dão à luz antes que a parteira chegue a elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'E Deus fez bem às parteiras. E o povo se multiplicou, e se fortaleceu muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'E por as parteiras terem temido a Deus, ele constituiu famílias a elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Então Faraó deu a todo o seu povo a seguinte ordem: Lançai no rio todo filho que nascer, e a toda filha preservai a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Um homem da família de Levi foi, e tomou por mulher uma filha de Levi:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'A qual concebeu, e deu à luz um filho: e vendo-o que era belo, teve-lhe escondido três meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Porém não podendo ocultar-lhe mais tempo, tomou uma cesta de juncos, e vedou-a com piche e betume, e colocou nela ao menino, e o pôs entre os juncos à beira do rio:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'E ficou parada uma irmã sua ao longe, para ver o que lhe aconteceria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'E a filha de Faraó desceu a lavar-se ao rio, e passeando suas virgens pela beira do rio, viu ela a cesta entre os juncos, e enviou uma criada sua a que a tomasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'E quando a abriu, viu ao menino; e eis que o menino chorava. E tendo compaixão dele, disse: Dos meninos dos hebreus é este.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Então sua irmã disse à filha de Faraó: Irei a chamar-te uma ama das hebreias, para que te crie este menino?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'E a filha de Faraó respondeu: Vai. Então foi a virgem, e chamou à mãe do menino;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'À qual disse a filha de Faraó: Leva este menino, e cria-o para mim, e eu te o pagarei. E a mulher tomou ao menino, e o criou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'E quando cresceu o menino, ela o trouxe à filha de Faraó, a qual o adotou, e pôs-lhe por nome Moisés, dizendo: Porque das águas o tirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'E naqueles dias aconteceu que, crescido já Moisés, saiu a seus irmãos, e viu suas cargas: e observou a um egípcio que feria a um dos hebreus, seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'E olhou a todas as partes, e vendo que não parecia ninguém, matou ao egípcio, e escondeu-o na areia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'E saiu ao dia seguinte, e vendo a dois hebreus que brigavam, disse ao que fazia a injúria: Por que feres a teu próximo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'E ele respondeu: Quem te pôs a ti por príncipe e juiz sobre nós? Pensas matar-me como mataste ao egípcio? Então Moisés teve medo, e disse: Certamente esta coisa é descoberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'E ouvindo Faraó este negócio, procurou matar a Moisés: mas Moisés fugiu de diante de Faraó, e habitou na terra de Midiã; e sentou-se junto a um poço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Tinha o sacerdote de Midiã sete filhas, as quais vieram a tirar água, para encher os bebedouros e dar de beber as ovelhas de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mas os pastores vieram, e expulsaram-nas: Então Moisés se levantou e defendeu-as, e deu de beber às suas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'E voltando elas a Reuel seu pai, disse-lhes ele: Por que viestes hoje tão cedo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'E elas responderam: Um homem egípcio nos defendeu da mão dos pastores, e também tirou a água, e deu de beber as as ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'E disse a suas filhas: E onde está? Por que deixastes esse homem? Chamai-lhe para que coma pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'E Moisés concordou em morar com aquele homem; e ele deu a Moisés a sua filha Zípora:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'A qual lhe deu à luz um filho, e ele lhe pôs por nome Gérson: porque disse: Peregrino sou em terra alheia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'E aconteceu que depois de muitos dias morreu o rei do Egito, e os filhos de Israel suspiraram por causa da servidão, e clamaram: e subiu a Deus o clamor deles com motivo de sua servidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'E ouviu Deus o gemido deles, e lembrou-se de seu pacto com Abraão, Isaque e Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Deus olhou os filhos de Israel, e Deus os reconheceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'E apascentando Moisés as ovelhas de Jetro seu sogro, sacerdote de Midiã, levou as ovelhas ao outro lado do deserto, e veio a Horebe, monte de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'E apareceu-lhe o anjo do SENHOR em uma chama de fogo em meio de uma sarça: e ele olhou, e viu que a sarça ardia em fogo, e a sarça não se consumia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Então Moisés disse: Irei eu agora, e verei esta grande visão, por que causa a sarça não se queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'E quando o SENHOR viu que ia ver, Deus o chamou do meio da sarça, e disse: Moisés, Moisés! E ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'E disse: Não te aproximes daqui; tira teus calçados de teus pés, porque o lugar em que estás é terra santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'E disse: Eu sou o Deus de teu pai, Deus de Abraão, Deus de Isaque, Deus de Jacó. Então Moisés cobriu seu rosto, porque teve medo de olhar a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'E disse o SENHOR: Vi a aflição de meu povo que está no Egito, e ouvi seu clamor por causa de seus opressores; pois conheço suas angústias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'E desci para livrá-los da mão dos egípcios, e tirá-los daquela terra a uma terra boa e larga, a terra que flui leite e mel, aos lugares dos cananeus, dos heteus, dos amorreus, dos perizeus, dos heveus, e dos jebuseus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'O clamor, pois, dos filhos de Israel veio diante de mim, e também vi a opressão com que os egípcios os oprimem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Vem, pois, agora, e te enviarei a Faraó, para que tires meu povo, os filhos de Israel, do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Então Moisés respondeu a Deus: Quem sou eu, para que vá a Faraó, e tire do Egito aos filhos de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'E ele lhe respondeu: Vai, porque eu serei contigo; e isto te será por sinal de que eu te enviei: logo que houveres tirado este povo do Egito, servireis a Deus sobre este monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'E disse Moisés a Deus: Eis que, quando eu chegar aos filhos de Israel, e lhes disser, O Deus de vossos pais me enviou a vós; se eles me perguntarem: Qual é seu nome? que lhes responderei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Deus respondeu a Moisés: EU SOU O QUE SOU. E disse: Assim dirás aos filhos de Israel: EU SOU me enviou a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'E disse mais Deus a Moisés: Assim dirás aos filhos de Israel: o SENHOR, o Deus de vossos pais, o Deus de Abraão, Deus de Isaque e Deus de Jacó, me enviou a vós. Este é meu nome para sempre, este é meu memorial por todos os séculos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Vai, e junta os anciãos de Israel, e dize-lhes: O SENHOR, o Deus de vossos pais, o Deus de Abraão, de Isaque, e de Jacó, me apareceu, dizendo: Certamente vos visitei, e vi o que se faz convosco no Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'E disse: Eu vos tirarei da aflição do Egito à terra dos cananeus, e dos heteus, e dos amorreus, e dos perizeus, e dos heveus, e dos jebuseus, a uma terra que flui leite e mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'E ouvirão tua voz; e irás tu, e os anciãos de Israel, ao rei do Egito, e lhe direis: O SENHOR, o Deus dos hebreus, nos encontrou; portanto nós iremos agora caminho de três dias pelo deserto, para que sacrifiquemos ao SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Mas eu sei que o rei do Egito não vos deixará ir a não ser por mão forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Porém eu estenderei minha mão, e ferirei ao Egito com todas minhas maravilhas que farei nele, e então vos deixará ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'E eu darei a este povo favor aos olhos dos egípcios, para que quando vos partirdes, não saiais vazios:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Em vez disso pedirá cada mulher à sua vizinha e à sua visitante vasos de prata, vasos de ouro, e roupas; os quais poreis sobre vossos filhos e vossas filhas, e despojareis ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Então Moisés respondeu, e disse: Eis que eles não crerão em mim, nem ouvirão minha voz; porque dirão: O SENHOR não apareceu a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'E o SENHOR disse: Que é isso que tens em tua mão? E ele respondeu: Uma vara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'E ele lhe disse: Lança-a em terra. E ele a lançou em terra, e tornou-se uma cobra: e Moisés fugia dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Então disse o SENHOR a Moisés: Estende tua mão, e toma-a pela cauda. E ele estendeu sua mão, e tomou-a, e tornou-se vara em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Por isto crerão que se te apareceu o SENHOR, o Deus de teus pais, o Deus de Abraão, Deus de Isaque, e Deus de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'E disse-lhe mais o SENHOR: Mete agora tua mão em teu peito. E ele meteu a mão em seu peito; e quando a tirou, eis que sua mão estava leprosa como a neve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'E disse: Volta a meter tua mão em teu peito; e ele voltou a meter sua mão em seu peito; e voltando-a a tirar do peito, eis que se havia voltado como a outra carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Se acontecer, que não te crerem, nem obedecerem à voz do primeiro sinal, crerão à voz do último.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'E se ainda não crerem nestes dois sinais, nem ouvirem tua voz, tomarás das águas do rio, e as derramará em terra; e se tornarão aquelas águas que tomarás do rio, se tornarão sangue na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Então disse Moisés ao SENHOR: Ai Senhor! Eu não sou homem de palavras de ontem nem de anteontem, nem ainda desde que tu falas a teu servo; porque sou lento no fala e incômodo de língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'E o SENHOR lhe respondeu: Quem deu a boca ao homem? Ou quem fez ao mudo e ao surdo, ao que vai e ao cego? não sou eu, o SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Agora pois, vai, que eu serei em tua boca, e te ensinarei o que tenhas de falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'E ele disse: Ai Senhor! envia por meio do que hás de enviar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Então o SENHOR se irou contra Moisés, e disse: Não conheço eu a teu irmão Arão, levita, e que ele fala bem? E ainda eis que ele sairá para te receber, e vendo-te, se alegrará em seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Tu falarás a ele, e porás em sua boca as palavras, e eu serei em tua boca e na sua, e vos ensinarei o que deveis fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'E ele falará por ti ao povo; e ele te será a ti em lugar de boca, e tu serás para ele em lugar de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'E tomarás esta vara em tua mão, com a qual farás os sinais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Assim se foi Moisés, e voltando a seu sogro Jetro, disse-lhe: Irei agora, e voltarei a meus irmãos que estão em Egito, para ver se ainda vivem. E Jetro disse a Moisés: Vai em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Disse também o SENHOR a Moisés em Midiã: Vai, e volta-te ao Egito, porque mataram todos os que procuravam tua morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Então Moisés tomou sua mulher e seus filhos, e os pôs sobre um asno, e voltou-se à terra do Egito: tomou também Moisés a vara de Deus em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'E disse o SENHOR a Moisés: Quando houverdes voltado ao Egito, olha que faças diante de Faraó todas as maravilhas que pus em tua mão: eu, porém, endurecerei seu coração, de modo que não deixará ir ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'E dirás a Faraó: O SENHOR disse assim: Israel é meu filho, meu primogênito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Já te disse que deixes ir a meu filho, para que me sirva, mas não quiseste deixá-lo ir: eis que eu vou a matar a teu filho, o teu primogênito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'E aconteceu no caminho, que em uma parada o SENHOR lhe saiu ao encontro, e quis matá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Então Zípora agarrou uma pedra afiada, e cortou o prepúcio de seu filho, e lançou-o a seus pés, dizendo: Em verdade tu me és um esposo de sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Assim lhe deixou logo ir. E ela disse: Esposo de sangue, por causa da circuncisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'E o SENHOR disse a Arão: Vai receber a Moisés ao deserto. E ele foi, e encontrou-o no monte de Deus, e beijou-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Então contou Moisés a Arão todas as palavras do SENHOR que lhe enviava, e todas o sinais que lhe havia dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'E foram Moisés e Arão, e juntaram todos os anciãos dos filhos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'E falou Arão todas as palavras que o SENHOR havia dito a Moisés, e fez o sinais diante dos olhos do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'E o povo creu; e ouvindo que o SENHOR havia visitado os filhos de Israel, e que havia visto sua aflição, inclinaram-se e adoraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Depois entraram Moisés e Arão a Faraó, e lhe disseram: O SENHOR, o Deus de Israel, disse assim: Deixa ir meu povo a celebrar-me festa no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'E Faraó respondeu: Quem é o SENHOR, para que eu ouça sua voz e deixe ir a Israel? Não conheço o SENHOR, nem tampouco deixarei Israel ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'E eles disseram: O Deus dos hebreus nos encontrou: iremos, pois, agora caminho de três dias pelo deserto, e sacrificaremos ao SENHOR nosso Deus; para que não venha sobre nós com pestilência ou com espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Então o rei do Egito lhes disse: Moisés e Arão, por que fazeis cessar ao povo de sua obra? Ide a vossas cargas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Disse também Faraó: Eis que o povo da terra é agora muito, e vós lhes fazeis cessar de suas cargas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'E mandou Faraó aquele mesmo dia aos capatazes do povo que o tinham à sua responsabilidade, e a seus governadores, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'De aqui adiante não dareis palha ao povo para fazer tijolos, como ontem e antes de ontem; vão eles e recolham por si mesmos a palha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'E haveis de pôr-lhes a tarefa dos tijolos que faziam antes, e não lhes diminuireis nada; porque estão ociosos, e por isso levantam a voz dizendo: Vamos e sacrificaremos a nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Agrave-se a servidão sobre eles, para que se ocupem nela, e não atendam a palavras de mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'E saindo os capatazes do povo e seus governadores, falaram ao povo, dizendo: Assim disse Faraó: Eu não vos dou palha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Ide vós, e recolhei palha de onde a achardes; que nada se diminuirá de vossa tarefa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Então o povo se espalhou por toda a terra do Egito a colher restolho em lugar de palha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'E os capatazes os apressavam, dizendo: Acabai vossa obra, a tarefa do dia em seu dia, como quando se vos dava palha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'E açoitavam aos supervisores dos filhos de Israel, que os capatazes de Faraó haviam posto sobre eles, dizendo: Por que não cumpristes vossa tarefa de tijolos nem ontem nem hoje, como antes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'E os supervisores dos filhos de Israel vieram a Faraó, e se queixaram a ele, dizendo: Por que o fazes assim com teus servos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Não se dá palha a teus servos, e, contudo, nos dizem: Fazei os tijolos. E eis que teus servos são açoitados, e teu povo cai em falta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'E ele respondeu: Estais ociosos, sim, ociosos, e por isso dizeis: Vamos e sacrifiquemos ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Ide, pois, agora, e trabalhai. Não se vos dará palha, e haveis de dar a tarefa dos tijolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Então os supervisores dos filhos de Israel se viram em aflição, tendo lhes dito: Não se diminuirá nada de vossos tijolos, da tarefa de cada dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'E encontrando a Moisés e a Arão, que estavam à vista deles quando saíam de Faraó,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Disseram-lhes: Olhe o SENHOR sobre vós, e julgue; pois nos fizestes repulsivos diante de Faraó e de seus servos, dando-lhes a espada nas mãos para que nos matem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Então Moisés se voltou ao SENHOR, e disse: Senhor, por que afliges a este povo? para que me enviaste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Porque desde que vim a Faraó para falar-lhe em teu nome, afligiu a este povo; e tu tampouco livraste a teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'O SENHOR respondeu a Moisés: Agora verás o que eu farei a Faraó; porque com mão forte os deixará ir; e com mão forte os expulsará de sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Falou, todavia, Deus a Moisés, e disse-lhe: Eu sou o SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'E apareci a Abraão, a Isaque e a Jacó sob o nome de Deus Todo-Poderoso, mas em meu nome, EU-SOU, não me notifiquei a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'E também estabeleci meu pacto com eles, de dar-lhes a terra de Canaã, a terra em que foram estrangeiros, e na qual peregrinaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'E também eu ouvi o gemido dos filhos de Israel, aos quais fazem servir os egípcios, e lembrei-me de meu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Portanto dirás aos filhos de Israel: EU SOU O SENHOR; e eu vos tirarei de debaixo das cargas do Egito, e vos livrarei de sua servidão, e vos resgatarei com braço estendido, e com grandes juízos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'E vos tomarei por meu povo e serei vosso Deus: e vós sabereis que eu sou o SENHOR vosso Deus, que vos tiro de debaixo das cargas do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'E vos meterei na terra, pela qual levantei minha mão que a daria a Abraão, a Isaque e a Jacó: e eu vos a darei por herança. EU SOU O SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Desta maneira falou Moisés aos filhos de Israel: mas eles não escutavam a Moisés por causa da angústia de espírito, e da dura servidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Entra, e fala a Faraó rei do Egito, que deixe ir de sua terra aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'E respondeu Moisés diante do SENHOR, dizendo: Eis que os filhos de Israel não me escutam: como, pois, me escutará Faraó, ainda mais sendo eu incircunciso de lábios?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Então o SENHOR falou a Moisés e a Arão, e deu-lhes mandamento para os filhos de Israel, e para Faraó rei do Egito, para que tirassem aos filhos de Israel da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Estes são os chefes das famílias de seus pais. Os filhos de Rúben, o primogênito de Israel: Enoque e Palu, Hezrom e Carmi: estas são as famílias de Rúben.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Os filhos de Simeão: Jemuel, e Jamim, e Oade, e Jaquim, e Zoar, e Saul, filho de uma cananeia: estas são as famílias de Simeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'E estes são os nomes dos filhos de Levi por suas linhagens: Gérson, e Coate, e Merari: E os anos da vida de Levi foram cento trinta e sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'E os filhos de Gérson: Libni, e Simei, por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'E os filhos de Coate: Anrão, e Izar, e Hebrom, e Uziel. E os anos da vida de Coate foram cento e trinta e três anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'E os filhos de Merari: Mali, e Musi: estas são as famílias de Levi por suas linhagens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'E Anrão tomou por mulher a Joquebede sua tia, a qual lhe deu à luz a Arão e a Moisés. E os anos da vida de Anrão foram cento e trinta e sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'E os filhos de Izar: Corá, e Nefegue e Zicri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'E os filhos de Uziel: Misael, e Elzafã e Sitri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'E tomou para si Arão por mulher a Eliseba, filha de Aminadabe, irmã de Naassom; a qual lhe deu à luz a Nadabe, e a Abiú, e a Eleazar, e a Itamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'E os filhos de Corá: Assir, e Elcana, e Abiasafe: estas são as famílias dos coraítas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'E Eleazar, filho de Arão, tomou para si mulher das filhas de Putiel, a qual lhe deu à luz a Fineias: E estes são os chefes dos pais dos levitas por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Este é aquele Arão e aquele Moisés, aos quais o SENHOR disse: Tirai aos filhos de Israel da terra do Egito por seus esquadrões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Estes são os que falaram a Faraó rei do Egito, para tirar do Egito aos filhos de Israel. Moisés e Arão foram estes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Quando o SENHOR falou a Moisés na terra do Egito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Então o SENHOR falou a Moisés, dizendo: Eu sou o SENHOR; dize a Faraó rei do Egito todas as coisas que eu te digo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'E Moisés respondeu diante do SENHOR: Eis que sou incircunciso de lábios; como, pois, Faraó me ouvirá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'O SENHOR disse a Moisés: Olha, eu te constituí como um deus para Faraó, e teu irmão Arão será teu profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tu dirás todas as coisas que eu te mandarei, e Arão teu irmão falará a Faraó, para que deixe os filhos de Israel saírem de sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'E eu endurecerei o coração de Faraó, e multiplicarei na terra do Egito meus sinais e minhas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'E Faraó não vos ouvirá; mas eu porei minha mão sobre o Egito, e tirarei meus exércitos, meu povo, os filhos de Israel, da terra do Egito, com grandes juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'E os egípcios saberão que eu sou o SENHOR, quando eu estender minha mão sobre o Egito, e tirar os filhos de Israel do meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'E fez Moisés e Arão como o SENHOR lhes mandou; fizeram-no assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'E era Moisés de idade de oitenta anos, e Arão de idade de oitenta e três, quando falaram a Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'E falou o SENHOR a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Se Faraó vos responder dizendo, Mostrai milagre; dirás a Arão: Toma tua vara, e lança-a diante de Faraó, para que se torne cobra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Vieram, pois, Moisés e Arão a Faraó, e fizeram como o SENHOR o havia mandado; e Arão lançou sua vara diante de Faraó e de seus servos, e tornou-se cobra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Então Faraó chamou também sábios e encantadores; e os encantadores do Egito com seus encantamentos fizeram também o mesmo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Pois lançou cada um sua vara, as quais se tornaram cobras; mas a vara de Arão devorou as varas deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'E o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Então o SENHOR disse a Moisés: O coração de Faraó está endurecido, que não quer deixar o povo ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Vai pela manhã a Faraó, eis que ele estará saindo às águas; e põe-te à beira do rio diante dele, e toma em tua mão a vara que se tornou cobra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'E dize-lhe: O SENHOR, o Deus dos hebreus, me enviou a ti, dizendo: Deixa meu povo ir, para que me sirvam no deserto; e eis que até agora não quiseste ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Assim disse o SENHOR: Nisto conhecerás que eu sou o SENHOR: eis que ferirei com a vara que tenho em minha mão a água que está no rio, e se converterá em sangue:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'E os peixes que há no rio morrerão, e federá o rio, e os egípcios terão asco de beber a água do rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'E o SENHOR disse a Moisés: Dize a Arão: Toma tua vara, e estende tua mão sobre as águas do Egito, sobre seus rios, sobre seus ribeiros e sobre seus tanques, e sobre todos os seus depósitos de águas, para que se convertam em sangue, e haja sangue por toda a região do Egito, tanto nos vasos de madeira como nos de pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'E Moisés e Arão fizeram como o SENHOR havia mandado; e levantando a vara feriu as águas que havia no rio, em presença de Faraó e de seus servos; e todas as águas que havia no rio se converteram em sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Assim os peixes que havia no rio morreram; e o rio se contaminou, que os egípcios não podiam beber dele; e houve sangue por toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'E os encantadores do Egito fizeram o mesmo com seus encantamentos: e o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'E Faraó, tornando, voltou-se a sua casa, e não pôs seu coração ainda nisto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'E por todo o Egito fizeram poços ao redor do rio para beber, porque não podiam beber das águas do rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'E cumpriram-se sete dias depois que o SENHOR feriu o rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Então o SENHOR disse a Moisés: Entra à presença de Faraó, e dize-lhe: O SENHOR disse assim: Deixa meu povo ir, para que me sirvam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'E se não o quiseres deixar ir, eis que ferirei com rãs todo os teu território;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'E o rio criará rãs, que subirão, e entrarão em tua casa, e no teu quarto, e sobre tua cama, e nas casas de teus servos, e em teu povo, e em teus fornos, e em tuas amassadeiras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'E as rãs subirão sobre ti, e sobre teu povo, e sobre todos os teus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'E o SENHOR disse a Moisés: Dize a Arão: Estende tua mão com tua vara sobre os rios, ribeiros, e tanques, para que faça vir rãs sobre a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Então Arão estendeu sua mão sobre as águas do Egito, e subiram rãs que cobriram a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'E os encantadores fizeram o mesmo com seus encantamentos, e fizeram vir rãs sobre a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Então Faraó chamou Moisés e Arão, e disse-lhes: Orai ao SENHOR que tire as rãs de mim e de meu povo; e deixarei ir ao povo, para que sacrifique ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'E disse Moisés a Faraó: Tem a honra em meu lugar de dizer quando orarei por ti, e por teus servos, e por teu povo, para que as rãs sejam tiradas de ti, e de tuas casas, e que somente se restem no rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'E ele disse: Amanhã. E Moisés respondeu: Será feito conforme tua palavra, para que conheças que não há ninguém como o SENHOR nosso Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'E as rãs se irão de ti, e de tuas casas, e de teus servos, e de teu povo, e somente se ficarão no rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Então saíram Moisés e Arão da presença de Faraó, e clamou Moisés ao SENHOR acerca das rãs que havia posto a Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'E o SENHOR fez conforme a palavra de Moisés, e morreram as rãs das casas, dos pátios, e dos campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'E as juntaram em amontoados, e faziam cheirar mal a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'E vendo Faraó que lhe haviam dado repouso, agravou seu coração, e não os escutou; como o SENHOR o havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Então o SENHOR disse a Moisés: Dize a Arão: Estende tua vara, e fere o pó da terra, para que se voltem piolhos por todo o país do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'E eles o fizeram assim; e Arão estendeu sua mão com sua vara, e feriu o pó da terra, o qual se tornou piolhos, tanto nos homens como nos animais: todo o pó da terra se tornou piolhos ao todo o país do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'E os encantadores tentaram fizeram assim também, para tirar piolhos com seus encantamentos; mas não puderam. E havia piolhos tanto nos homens como nos animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Então os magos disseram a Faraó: Dedo de Deus é este. Mas o coração de Faraó se endureceu, e não os escutou; como o SENHOR o havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'E o SENHOR disse a Moisés: Levanta-te de manhã e põe-te diante de Faraó, eis que ele estará saindo às águas; e dize-lhe: o SENHOR disse assim: Deixa meu povo ir, para que me sirva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Porque se não deixares meu povo ir, eis que enviarei sobre ti, e sobre teus servos, e sobre teu povo, e sobre tuas casas toda variedade de moscas; e as casas dos egípcios se encherão de toda variedade de moscas, e também a terra onde eles estiverem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'E naquele dia separarei a terra de Gósen, na qual meu povo habita, para que nenhuma variedade de moscas haja nela; a fim de que saibas que eu sou o SENHOR no meio da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'E eu porei remissão entre meu povo e o teu. Amanhã será este sinal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'E o SENHOR o fez assim: veio toda variedade de moscas incômodas sobre a casa de Faraó, e sobre as casas de seus servos, e sobre todo o país do Egito; e a terra foi contaminada por causa delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Então Faraó chamou a Moisés e a Arão, e disse-lhes: Andai, sacrificai a vosso Deus nesta terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'E Moisés respondeu: Não convém que façamos assim, porque sacrificaríamos ao SENHOR nosso Deus a abominação dos egípcios. Eis que, se sacrificássemos a abominação dos egípcios diante deles, não nos apedrejariam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Caminho de três dias iremos pelo deserto, e sacrificaremos ao SENHOR nosso Deus, como ele nos dirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'E disse Faraó: Eu vos deixarei ir para que sacrifiqueis ao SENHOR vosso Deus no deserto, contanto que não vades mais longe; orai por mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'E respondeu Moisés: Eis que, quando eu sair de tua presença, rogarei ao SENHOR que as diversas variedades de moscas se afastem de Faraó, e de seus servos, e de seu povo amanhã; contanto que Faraó não falte mais, não deixando o povo ir sacrificar ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Então Moisés saiu da presença de Faraó, e orou ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'E o SENHOR fez conforme a palavra de Moisés; e tirou todas aquelas moscas de Faraó, e de seus servos, e de seu povo, sem que restasse uma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mas Faraó agravou ainda esta vez seu coração, e não deixou o povo ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Então o SENHOR disse a Moisés: Entra a Faraó, e dize-lhe: o SENHOR, o Deus dos hebreus, diz assim: Deixa ir a meu povo, para que me sirvam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Porque se não o queres deixar ir, e os detiverdes ainda,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Eis que a mão do SENHOR será sobre teus gados que estão no campo, cavalos, asnos, camelos, vacas e ovelhas, com pestilência gravíssima:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'E o SENHOR fará separação entre os gados de Israel e os do Egito, de modo que nada morra de todo o dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'E o SENHOR assinalou tempo, dizendo: Amanhã fará o SENHOR esta coisa na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'E o dia seguinte o SENHOR fez aquilo, e morreu todo o gado do Egito; mas do gado dos filhos de Israel não morreu um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Então Faraó enviou, e eis que do gado dos filhos de Israel não havia um morto sequer. Mas o coração de Faraó se agravou, e não deixou ir ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'E o SENHOR disse a Moisés e a Arão: Tomai punhados de cinza de um forno, e espalha-a Moisés até o céu diante de Faraó:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'E virá a ser pó sobre toda a terra do Egito, o qual originará sarna que cause feridas com ulcerações nos homens e nos animais, por todo o país do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'E tomaram a cinza do forno, e puseram-se diante de Faraó, e espalhou-a Moisés até o céu; e veio uma sarna que causava feridas com ulcerações tanto nos homens como nos animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'E os magos não podiam estar diante de Moisés por causa das feridas, porque houve sarna nos magos e em todos os egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'E o SENHOR endureceu o coração de Faraó, e não os ouviu; como o SENHOR o disse a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Então o SENHOR disse a Moisés: Levanta-te de manhã, e põe-te diante de Faraó, e dize-lhe: o SENHOR, o Deus dos hebreus, disse assim: Deixa ir a meu povo, para que me sirva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Porque eu enviarei esta vez todas minhas pragas a teu coração, sobre teus servos, e sobre teu povo, para que entendas que não há outro como eu em toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Porque agora eu estenderei minha mão para ferir a ti e a teu povo de pestilência, e serás tirado da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'E à verdade eu te pus para declarar em ti meu poder, e que meu Nome seja contado em toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Todavia te exaltas tu contra meu povo, para não deixá-los ir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Eis que amanhã a estas horas eu farei chover granizo muito grave, qual nunca foi em Egito, desde o dia que se fundou até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Envia, pois, a recolher teu gado, e tudo o que tens no campo; porque todo homem ou animal que se achar no campo, e não for recolhido a casa, o granizo descerá sobre ele, e morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Dos servos de Faraó o que temeu a palavra do SENHOR, fez fugir seus criados e seu gado a casa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Mas o que não pôs em seu coração a palavra do SENHOR, deixou seus criados e seus gados no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'E o SENHOR disse a Moisés: Estende tua mão até o céu, para que venha granizo em toda a terra do Egito sobre os homens, e sobre os animais, e sobre toda a erva do campo no país do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'E Moisés estendeu sua vara até o céu, e o SENHOR fez trovejar e cair granizo, e o fogo corria pela terra; e choveu o SENHOR granizo sobre a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Houve, pois, granizo, e fogo misturado com o granizo, tão grande, qual nunca houve em toda a terra do Egito desde que foi habitada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'E aquele granizo feriu em toda a terra do Egito todo o que estava no campo, tanto homens como animais; também feriu o granizo toda a erva do campo, e quebrou os galhos de todas as árvores do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Somente na terra de Gósen, onde os filhos de Israel estavam, não houve granizo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Então Faraó mandou chamar a Moisés e a Arão, e lhes disse: Pequei esta vez: o SENHOR é justo, e eu e meu povo ímpios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Orai ao SENHOR: e cessem os trovões de Deus e o granizo; e eu vos deixarei ir, e não vos detereis mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'E respondeu-lhe Moisés: Em saindo eu da cidade estenderei minhas mãos ao SENHOR, e os trovões cessarão, e não haverá mais granizo; para que saibas que do SENHOR é a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mas eu sei que nem tu nem teus servos temereis todavia a presença do Deus o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'O linho, pois, e a cevada foram feridos; porque a cevada estava já espigada, e o linho em flor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mas o trigo e o centeio não foram feridos; porque eram tardios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'E saído Moisés da presença de Faraó da cidade, estendeu suas mãos ao SENHOR, e cessaram os trovões e o granizo; e a chuva não caiu mais sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'E vendo Faraó que a chuva havia cessado e o granizo e os trovões, perseverou em pecar, e agravou seu coração, ele e seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'E o coração de Faraó se endureceu, e não deixou ir aos filhos de Israel; como o SENHOR o havia dito por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'E o SENHOR disse a Moisés: Vai à presença de Faraó; porque agravei o coração dele, e o coração de seus servos, para fazer entre eles estes meus sinais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'e para que contes a teus filhos e a teus netos as coisas que eu fiz em Egito, e meus sinais que realizei entre eles; e para que saibais que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Então vieram Moisés e Arão a Faraó, e lhe disseram: O SENHOR, o Deus dos hebreus disse assim: Até quando não quererás te humilhar diante de mim? Deixa ir a meu povo para que me sirvam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'E se ainda recusas deixá-lo ir, eis que trarei amanhã gafanhotos em teu território,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'os quais cobrirão a face da terra, de modo que não se possa ver a terra; e ela comerá o que restou salvo, o que vos restou do granizo; comerão também toda árvore que vos produz fruto no campo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'e encherão tuas casas, e as casas de todos os teus servos, e as casas de todos os egípcios, que nunca viram teus pais nem teus avós, desde que eles existiram sobre a terra até hoje. E voltou-se, e saiu da presença de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Então os servos de Faraó lhe disseram: Até quando este nos será por laço? Deixa ir a estes homens, para que sirvam ao SENHOR seu Deus; ainda não sabes que Egito está destruído?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'E Moisés e Arão voltaram a ser chamados a Faraó, o qual lhes disse: Andai, servi ao SENHOR vosso Deus. Quem e quem são os que irão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'E Moisés respondeu: Iremos com nossos meninos e com nossos idosos, com nossos filhos e com nossas filhas; iremos com nossas ovelhas e com nossas vacas, porque temos solenidade do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'E ele lhes disse: Assim esteja o SENHOR convosco se eu vos deixar ir a vós e a vossos meninos; olhai como o mal está diante de vosso rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Não será assim: ide agora vós, os homens, e servi ao SENHOR; pois isto é o que vós pedistes. E eles foram expulsos de diante de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Então o SENHOR disse a Moisés: Estende tua mão sobre a terra do Egito para gafanhotos, a fim de que subam sobre o país do Egito, e consumam tudo o que o granizo deixou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'E estendeu Moisés sua vara sobre a terra do Egito, e o SENHOR trouxe um vento oriental sobre o país todo aquele dia e toda aquela noite; e na manhã o vento oriental trouxe os gafanhotos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'E os gafanhotos subiram sobre toda a terra do Egito, e pousaram em todos os termos do Egito, em gravíssima maneira; antes dela não houve gafanhotos semelhantes, nem depois deles vieram outros tais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'E cobriram a face de todo o país, e escureceu-se a terra; e consumiram toda a erva da terra, e todo o fruto das árvores que o granizo havia deixado; que não restou coisa verde em árvores nem em erva do campo, por toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Então Faraó fez chamar depressa a Moisés e a Arão, e disse: Pequei contra o SENHOR vosso Deus, e contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Mas rogo agora que perdoes meu pecado somente esta vez, e que oreis ao SENHOR vosso Deus que tire de mim somente esta morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'E saiu da presença de Faraó, e orou ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'E o SENHOR voltou um vento ocidental fortíssimo, e tirou os gafanhotos, e lançou-os ao mar Vermelho; nem um gafanhoto restou ao todo o território do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mas o SENHOR endureceu o coração de Faraó; e não permitiu a saída dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'E o SENHOR disse a Moisés: Estende tua mão até o céu, para que haja trevas sobre a terra do Egito, tão intensas que qualquer um as apalpe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'E estendeu Moisés sua mão até o céu, e houve densas durante trevas três dias por toda a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Nenhum podia ver seu próximo, nem ninguém se levantou de seu lugar em três dias; mas todos os filhos de Israel tinham luz em suas habitações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Então Faraó fez chamar a Moisés, e disse: Ide, servi ao SENHOR; somente restem vossas ovelhas e vossas vacas; vão também vossas crianças convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'E Moisés respondeu: Tu também nos entregarás sacrifícios e holocaustos para que sacrifiquemos ao SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Nossos gados irão também conosco; não ficará nem uma casco; porque deles tomaremos para servir ao SENHOR nosso Deus; e não sabemos com que serviremos ao SENHOR, até que cheguemos ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mas o SENHOR endureceu o coração de Faraó, e não quis deixá-los ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'E disse-lhe Faraó: Retira-te de mim; guarda-te que não vejas mais meu rosto, porque em qualquer dia que vires meu rosto, morrerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'E Moisés respondeu: Bem disseste; não verei mais teu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'E o SENHOR disse a Moisés: Uma praga trarei ainda sobre Faraó, e sobre o Egito; depois da qual ele vos deixará ir daqui; e seguramente vos expulsará daqui de todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Fala agora ao povo, e que cada um peça a seu vizinho, e cada uma à sua vizinha, objetos de prata e de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'E o SENHOR fez o povo ser favorecido aos olhos dos egípcios. Também Moisés era muito grande homem na terra do Egito, aos olhos dos servos de Faraó, e aos olhos do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'E disse Moisés: o SENHOR disse assim: À meia noite eu sairei por meio do Egito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'E morrerá todo primogênito na terra do Egito, desde o primogênito de Faraó que se assenta em seu trono, até o primogênito da serva que está atrás do moinho; e todo primogênito dos animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'E haverá grande clamor por toda a terra do Egito, qual nunca foi, nem jamais será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mas entre todos os filhos de Israel, desde o homem até o animal, nem um cão moverá sua língua; para que saibais que o SENHOR fará diferença entre os egípcios e os israelitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'E descerão a mim todos estes teus servos, e inclinados diante de mim dirão: Sai tu, e todo o povo que está abaixo de ti; e depois disto eu sairei. E saiu-se muito irado da presença de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'E o SENHOR disse a Moisés: Faraó não vos ouvirá, para que minhas maravilhas se multipliquem na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'E Moisés e Arão fizeram todos estes prodígios diante de Faraó: mas o SENHOR havia endurecido o coração de Faraó, e não permitiu que os filhos de Israel saíssem de seu país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'E falou o SENHOR a Moisés e a Arão na terra do Egito, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Este mês vos será o princípio dos meses; será este para vós o primeiro nos meses do ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Falai a toda a congregação de Israel, dizendo: No dia dez deste mês tome para si cada um um cordeiro pelas famílias dos pais, um cordeiro por família:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Mas se a família for pequena que não seja capaz de comer o cordeiro inteiro, então tomará a seu vizinho imediato à sua casa, e segundo o número das pessoas, cada um conforme seu comer, fareis a conta sobre o cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'O cordeiro será sem defeito, macho de um ano; vós o tomareis das ovelhas ou das cabras:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'E o guardareis até o dia catorze desse mês; e toda a congregação do povo de Israel o imolará ao entardecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'E tomarão do sangue, e o porão nos dois postes e na verga das casas em que o comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'E naquela noite comerão a carne assada ao fogo, e pães sem levedura; com ervas amargas o comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Nenhuma coisa comereis dele crua, nem cozida em água, mas sim assada ao fogo; sua cabeça com seus pés e seus intestinos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Nenhuma coisa deixareis dele até a manhã; e o que houver restado até a manhã, queimareis no fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'E assim tereis de comê-lo: cingidos vossos lombos, vossos calçados em vossos pés, e vosso bordão em vossa mão; e o comereis apressadamente: é a Páscoa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Pois eu passarei naquela noite pela terra do Egito, e ferirei todo primogênito na terra do Egito, tanto nos homens como nos animais; e executarei juízos em todos os deuses do Egito. EU SOU O SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'E o sangue vos será por sinal nas casas onde vós estejais; e verei o sangue, e passarei de vós, e não haverá em vós praga de mortandade, quando ferirei a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'E hoje vos será em memória, e tereis de celebrá-lo como solenidade ao SENHOR durante vossas gerações; por estatuto perpétuo o celebrareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sete dias comereis pães sem levedura; e assim o primeiro dia fareis que não haja levedura em vossas casas; porque qualquer um que comer levedado desde o primeiro dia até o sétimo, aquela alma será eliminada de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'No primeiro dia haverá santa convocação, e também no sétimo dia tereis uma santa convocação; nenhuma obra se fará neles, exceto somente que prepareis o que cada qual houver de comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'E guardareis a festa dos pães ázimos, porque em este mesmo dia tirei vossos exércitos da terra do Egito: portanto guardareis hoje em vossas gerações por costume perpétuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'No mês primeiro, o dia catorze do mês pela tarde, comereis os pães sem levedura, até o vinte e um do mês pela tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Por sete dias não se achará levedura em vossas casas, porque qualquer um que comer algo levedado, tanto estrangeiro como natural do país, aquela alma será eliminada da congregação de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nenhuma coisa levedada comereis; em todas as vossas habitações comereis pães sem levedura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'E Moisés convocou a todos os anciãos de Israel, e disse-lhes: Tirai, e tomai para vós cordeiros por vossas famílias, e sacrificai a páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'E tomai um molho de hissopo, e molhai-lhe no sangue que estará em uma bacia, e untai a verga e os dois postes com o sangue que estará na bacia; e nenhum de vós saia das portas de sua casa até a manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Porque o SENHOR passará ferindo os egípcios; e quando vir o sangue na verga e nos dois postes, passará o SENHOR aquela porta, e não deixará entrar o feridor em vossas casas para ferir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'E guardareis isto por estatuto para vós e para vossos filhos para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'E será que quando houverdes entrado na terra que o SENHOR vos dará, como tem falado, que guardareis este rito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'E quando vos perguntarem vossos filhos: Que rito é este vosso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Respondereis: É o sacrifício da Páscoa do SENHOR, que passou nas casas dos filhos de Israel no Egito, quando feriu os egípcios, e livrou nossas casas. Então o povo se inclinou e adorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'E os filhos de Israel se foram, e fizeram exatamente assim, como o SENHOR havia mandado a Moisés e a Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'E aconteceu que à meia-noite o SENHOR feriu todo primogênito na terra do Egito, desde o primogênito de Faraó que se sentava sobre seu trono, até o primogênito do prisioneiro que estava no cárcere, e todo primogênito dos animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'E levantou-se naquela noite Faraó, ele e todos os seus servos, e todos os egípcios; e havia um grande clamor no Egito, porque não havia casa onde não houvesse morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'E fez chamar a Moisés e a Arão de noite, e disse-lhes: Saí do meio de meu povo vós, e os filhos de Israel; e ide, servi ao SENHOR, como dissestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tomai também vossas ovelhas e vossas vacas, como dissestes, e ide; e abençoai também a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'E os egípcios apressavam ao povo, dando pressa a expulsá-los da terra; porque diziam: Todos seremos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'E levou o povo sua massa antes que se levedasse, suas massas envoltas em suas mantas sobre seus ombros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'E fizeram os filhos de Israel conforme o mandamento de Moisés, pedindo aos egípcios objetos de prata, e objetos de ouro, e roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'E o SENHOR deu favor ao povo diante dos egípcios, e deram-lhes; e eles despojaram os egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'E partiram os filhos de Israel de Ramessés a Sucote, como seiscentos mil homens a pé, sem contar os meninos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'E também subiu com eles grande multidão de diversa variedade de gentes; e ovelhas, e gados muito muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'E cozeram tortas sem levedura da massa que haviam tirado do Egito; porque não havia levedado, porquanto expulsando-os os egípcios, não haviam podido deter-se, nem ainda preparar para si comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'O tempo que os filhos de Israel habitaram no Egito foi quatrocentos e trinta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'E passados quatrocentos e trinta anos, no mesmo dia saíram todos os exércitos do SENHOR da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'É noite de guardar ao SENHOR, por havê-los tirado nela da terra do Egito. Esta noite devem guardar ao SENHOR todos os filhos de Israel em suas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'E o SENHOR disse a Moisés e a Arão: Esta é a ordenança da Páscoa: Nenhum estrangeiro comerá dela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Mas todo servo humano comprado por dinheiro, comerá dela depois que o houveres circuncidado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'O estrangeiro e o assalariado não comerão dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Em uma casa se comerá, e não levarás daquela carne fora de casa, nem quebrareis osso seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toda a congregação de Israel o sacrificará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Mas se algum estrangeiro peregrinar contigo, e quiser fazer a páscoa ao SENHOR, seja-lhe circuncidado todo homem, e então se chegará a fazê-la, e será como o natural da terra; mas nenhum incircunciso comerá dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'A mesma lei será para o natural e para o estrangeiro que peregrinar entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Assim o fizeram todos os filhos de Israel; como mandou o SENHOR a Moisés e a Arão, assim o fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'E naquele mesmo dia o SENHOR tirou os filhos de Israel da terra do Egito, agrupados em seus esquadrões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Santifica para mim todo primogênito, qualquer um que abre madre entre os filhos de Israel, tanto dos homens como dos animais: meu é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'E Moisés disse ao povo: Tende memória deste dia, no qual saístes do Egito, da casa de servidão; pois o SENHOR vos tirou daqui com mão forte; portanto, não comereis levedado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Vós saís hoje no mês de Abibe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'E quando o SENHOR te houver posto na terra dos cananeus, e dos heteus, e dos amorreus, e dos heveus, e dos jebuseus, a qual jurou a teus pais que te daria, terra que destila leite e mel, farás este serviço em este mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sete dias comerás sem levedar, e o sétimo dia será festa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Por os sete dias se comerão os pães sem levedura; e não se verá contigo levedado, nem levedura ao todo teu termo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'E contarás naquele dia a teu filho, dizendo: Isto se faz por causa do que o SENHOR fez comigo quando me tirou do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'E será para ti como um sinal sobre tua mão, e como uma memória diante de teus olhos, para que a lei do SENHOR esteja na tua boca; pois com mão forte te tirou o SENHOR do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Portanto, tu guardarás este rito em seu tempo de ano em ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'E quando o SENHOR te houver posto na terra dos cananeus, como jurou a ti e a teus pais, e quando te a houver dado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Farás passar ao SENHOR todo o que abrir a madre, também todo primeiro que abrir a madre de teus animais: os machos serão do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mas todo primogênito de asno resgatarás com um cordeiro; e se não o resgatares, o degolarás: também resgatarás todo homem primogênito de teus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'E quando amanhã te perguntar teu filho, dizendo: Que é isto? Tu lhe dirás: o SENHOR tirou com mão forte do Egito, de casa de servidão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'E endurecendo-se Faraó em não nos deixar ir, o SENHOR matou na terra do Egito a todo primogênito, desde o primogênito homem até o primogênito do animal; e por esta causa eu sacrifico ao SENHOR todo primogênito macho, e resgato todo primogênito de meus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Será para ti, pois, como um sinal sobre tua mão, e por uma memória diante de teus olhos; já que o SENHOR tirou do Egito com mão forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'E logo que Faraó deixou ir ao povo, Deus não os levou pelo caminho da terra dos filisteus, que estava próxima; porque disse Deus: Que talvez não se arrependa o povo quando virem a guerra, e se voltem ao Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Mas fez Deus ao povo que rodeasse pelo caminho do deserto do mar Vermelho. E subiram os filhos de Israel do Egito armados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Tomou também consigo Moisés os ossos de José, o qual havia juramentado aos filhos de Israel, dizendo: Deus certamente vos visitará, e fareis subir meus ossos daqui convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'E partidos de Sucote, assentaram acampamento em Etã, à entrada do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'E o SENHOR ia diante deles de dia em uma coluna de nuvem, para guiá-los pelo caminho; e de noite em uma coluna de fogo para iluminá-los, a fim de que andassem de dia e de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nunca se partiu de diante do povo a coluna de nuvem de dia, nem de noite a coluna de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Fala aos filhos de Israel que deem a volta, e assentem seu acampamento diante de Pi-Hairote, entre Migdol e o mar até Baal-Zefom: diante dele assentareis o campo, junto ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Porque Faraó dirá dos filhos de Israel: Estão andando confusos na terra, o deserto os encurralou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'E eu endurecerei o coração de Faraó para que os siga; e serei glorificado em Faraó e em todo o seu exército; e saberão os egípcios que eu sou o SENHOR. E eles o fizeram assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'E foi dado aviso ao rei do Egito como o povo se fugia: e o coração de Faraó e de seus servos se voltou contra o povo, e disseram: Como fizemos isto de haver deixado ir a Israel, para que não nos sirva?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'E preparou seu carro, e tomou consigo seu povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'e tomou seiscentos carros escolhidos, e todos os carros do Egito, e os capitães sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'E endureceu o SENHOR o coração de Faraó rei do Egito, e seguiu aos filhos de Israel; mas os filhos de Israel haviam saído com mão poderosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Seguindo-os, pois, os egípcios, com toda a cavalaria e carros de Faraó, seus cavaleiros, e todo seu exército, alcançaram-nos assentando o acampamento junto ao mar, ao lado de Pi-Hairote, diante de Baal-Zefom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'E quando Faraó se aproximou, os filhos de Israel levantaram seus olhos, e eis que os egípcios vinham atrás deles; por isso temeram muito, e os filhos de Israel clamaram ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'E disseram a Moisés: Não havia sepulcros no Egito, que nos tiraste para morrermos no deserto? Por que o fizeste assim conosco, que nos tiraste do Egito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Não é isto o que te falamos no Egito, dizendo: Deixa-nos servir aos egípcios? Pois melhor nos teria sido servir aos egípcios, que morrermos no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'E Moisés disse ao povo: Não temais; ficai quietos, e vede a salvação do SENHOR, que ele fará hoje convosco; porque os egípcios que hoje vistes, nunca mais para sempre os vereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'O SENHOR lutará por vós, e vós ficai quietos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Então o SENHOR disse a Moisés: Por que clamas a mim? Diz aos filhos de Israel que marchem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'E tu ergue tua vara, e estende tua mão sobre o mar, e divide-o; e entrem os filhos de Israel por meio do mar em seco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'E eu, eis que eu endurecerei o coração dos egípcios, para que os sigam: e eu me glorificarei em Faraó, e em todo o seu exército, e em seus carros, e em sua cavalaria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'E saberão os egípcios que eu sou o SENHOR, quando eu me glorificar em Faraó, em seus carros, e em seus cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'E o anjo de Deus que ia diante do acampamento de Israel, se separou, e ia após eles; e também a coluna de nuvem que ia diante deles, se separou, e pôs-se a suas costas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'E ia entre o acampamento dos egípcios e o acampamento de Israel; e era nuvem e trevas para aqueles, e iluminava a Israel de noite: e em toda aquela noite nunca chegaram os uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'E estendeu Moisés sua mão sobre o mar, e fez o SENHOR que o mar se retirasse por forte vento oriental toda aquela noite; e tornou o mar em seco, e as águas restaram divididas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Então os filhos de Israel entraram por meio do mar em seco, tendo as águas como muro à sua direita e à sua esquerda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'E seguindo-os os egípcios, entraram atrás deles até o meio do mar, toda a cavalaria de Faraó, seus carros, e seus cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'E aconteceu à vigília da manhã, que o SENHOR olhou ao campo dos egípcios desde a coluna de fogo e nuvem, e perturbou o acampamento dos egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'E tirou-lhes as rodas de seus carros, e transtornou-os gravemente. Então os egípcios disseram: Fujamos de diante de Israel, porque o SENHOR luta por eles contra os egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'E o SENHOR disse a Moisés: Estende tua mão sobre o mar, para que as águas voltem sobre os egípcios, sobre seus carros, e sobre sua cavalaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'E Moisés estendeu sua mão sobre o mar, e o mar se voltou em sua força quando amanhecia; e os egípcios iam até ela: e o SENHOR derrubou aos egípcios em meio do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'E voltaram as águas, e cobriram os carros e a cavalaria, e todo o exército de Faraó que havia entrado atrás eles no mar; não restou deles nenhum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'E os filhos de Israel foram por meio do mar em seco, tendo as águas por muro à sua direita e à sua esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Assim salvou o SENHOR aquele dia a Israel da mão dos egípcios; e Israel viu aos egípcios mortos à beira do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'E viu Israel aquele grande feito que o SENHOR executou contra os egípcios: e o povo temeu ao SENHOR, e creram no SENHOR e em Moisés seu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Então cantou Moisés e os filhos de Israel este cântico ao SENHOR, e disseram: Cantarei eu ao SENHOR, porque se triunfou grandemente, Lançando no mar ao cavalo e ao que nele subia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'O SENHOR é minha força, e minha canção, E foi-me por salvação: Este é meu Deus, e a este engrandecerei; Deus de meu pai, e a este exaltarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'O SENHOR, homem de guerra; o SENHOR é seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Os carros de Faraó e a seu exército lançou no mar; E seus escolhidos príncipes foram afundados no mar Vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Os abismos os cobriram; Como pedra desceram aos profundos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Tua mão direita, ó SENHOR, foi engrandecida em força; Tua mão direita, ó SENHOR, quebrantou ao inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'E com a grandeza de tua poder transtornaste aos que se levantaram contra ti: Enviaste teu furor; os tragou como o restolho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Com o sopro de tuas narinas se amontoaram as águas; Pararam-se as correntezas como em um amontoado; Os abismos se solidificaram em meio do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'O inimigo disse: Perseguirei, prenderei, repartirei despojos; Minha alma se encherá deles; Tirarei minha espada, minha mão os destruirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Sopraste com teu vento, cobriu-os o mar: Afundaram-se como chumbo nas impetuosas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Quem como tu, SENHOR, entre os deuses? Quem como tu, magnífico em santidade, Terrível em louvores, autor de maravilhas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Estendeste a tua mão direita; a terra os tragou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Conduziste em tua misericórdia a este povo, ao qual salvaste; Levaste-o com tua força à habitação de teu santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Ouviram-no os povos, e tremerão; Dor se apoderará dos moradores da filístia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Então os príncipes de Edom se perturbarão; Aos robustos de Moabe os ocupará tremor; Todos os moradores de Canaã se abaterão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Caia sobre eles tremor e espanto; À grandeza de teu braço emudeçam como uma pedra; Até que tenha passado teu povo, ó SENHOR, Até que tenha passado este povo que tu resgataste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tu os introduzirás e os plantarás no monte de tua herança, No lugar de tua morada, que tu preparaste, ó SENHOR; No santuário do Senhor, que firmaram tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'O SENHOR reinará pelos séculos dos séculos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Porque Faraó entrou cavalgando com seus carros e seus cavaleiros no mar, e o SENHOR voltou a trazer as águas do mar sobre eles; mas os filhos de Israel foram a seco por meio do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'E Miriã a profetisa, irmã de Arão, tomou um pandeiro em sua mão, e todas as mulheres saíram atrás dela com pandeiros e danças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'E Miriã lhes respondia: Cantai ao SENHOR; porque em extremo se engrandeceu, Lançando no mar ao cavalo, e ao que nele subia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'E fez Moisés que partisse Israel do mar Vermelho, e saíram ao deserto de Sur; e andaram três dias pelo deserto sem achar água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'E chegaram a Mara, e não puderam beber as águas de Mara, porque eram amargas; por isso lhe puseram o nome de Mara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Então o povo murmurou contra Moisés, e disse: Que beberemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'E Moisés clamou ao SENHOR; e o SENHOR lhe mostrou uma árvore, a qual quando a meteu dentro das águas, as águas se tornaram doces. Ali lhes deu estatutos e ordenanças, e ali os provou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'E disse: Se ouvires atentamente a voz do SENHOR teu Deus, e fizeres o correto diante de seus olhos, e deres ouvido a seus mandamentos, e guardares todos os seus estatutos, nenhuma enfermidade das que enviei aos egípcios te enviarei a ti; porque eu sou o SENHOR que te sara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'E chegaram a Elim, onde havia doze fontes de águas, e setenta palmeiras; e assentaram ali junto às águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Depois que partiram de Elim, toda a congregação dos filhos de Israel veio ao deserto de Sim, que está entre Elim e Sinai, aos quinze dias do segundo mês depois que saíram da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'E toda a congregação dos filhos de Israel murmurou contra Moisés e Arão no deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'E diziam-lhes os filhos de Israel: Bom seria se tivéssemos morrido por meio do SENHOR na terra do Egito, quando nos sentávamos junto às panelas das carnes, quando comíamos pão em fartura; pois nos tirastes a este deserto, para matar de fome a toda esta multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'E o SENHOR disse a Moisés: Eis que eu vos farei chover pão do céu; e o povo sairá, e colherá para cada um dia, para que eu lhe prove se anda em minha lei, ou não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Mas ao sexto dia prepararão o que coletarem, que será o dobro do que costumam colher cada dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Então disse Moisés e Arão a todos os filhos de Israel: À tarde sabereis que o SENHOR vos tirou da terra do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'E à próxima manhã vereis a glória do SENHOR; porque ele ouviu as vossas murmurações contra o SENHOR; pois quem somos nós, para que vós murmureis contra nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'E disse Moisés: o SENHOR vos dará à tarde carne para comer, e à manhã pão em fartura; pois o SENHOR ouviu as vossas murmurações com que murmurais contra ele; pois quem somos nós? As vossas murmurações não são contra nós, mas sim contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'E disse Moisés a Arão: Dize a toda a congregação dos filhos de Israel: Aproximai-vos à presença do SENHOR; que ele ouviu vossas murmurações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'E falando Arão a toda a congregação dos filhos de Israel, olharam até o deserto, e eis a glória do SENHOR, que apareceu na nuvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Eu ouvi as murmurações dos filhos de Israel; fala-lhes, dizendo: Ao entardecer comereis carne, e pela manhã vos fartareis de pão, e sabereis que eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'E vinda a tarde subiram codornizes que cobriram o acampamento; e à manhã desceu orvalho em derredor do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'E quando o orvalho cessou de descer, eis sobre a face do deserto uma coisa miúda, redonda, miúda como uma geada sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'E vendo-o os filhos de Israel, se disseram uns aos outros: Que é isto? porque não sabiam que era. Então Moisés lhes disse: É o pão que o SENHOR vos dá para comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Isto é o que o SENHOR mandou: Colhereis dele cada um segundo puder comer; um gômer por cabeça, conforme o número de vossas pessoas, tomareis cada um para os que estão em sua tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'E os filhos de Israel o fizeram assim: e recolheram uns mais, outros menos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'E mediam-no por gômer, e não sobrava ao que havia recolhido muito, nem faltava ao que havia recolhido pouco: cada um recolheu conforme o que havia de comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'E disse-lhes Moisés: Nenhum deixe nada disso para amanhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mas eles não obedeceram a Moisés, mas sim que alguns deixaram dele para outro dia, e criou bichos, e apodreceu-se; e irou-se contra eles Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'E recolhiam-no cada manhã, cada um segundo o que havia de comer: e logo que o sol aquecia, derretia-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'No sexto dia recolheram comida em dobro, dois gômeres para cada um; e todos os príncipes da congregação vieram a Moisés, e contaram-lhe isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'E ele lhes disse: Isto é o que o SENHOR disse: Amanhã é o repouso, o santo sábado do SENHOR; o que houverdes de assar, assai-o hoje, e o que houverdes de cozinhar, cozinhai-o; e tudo o que vos sobrar, guardai-o para amanhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'E eles o guardaram até a manhã, segundo que Moisés havia mandado, e não se apodreceu, nem houve nele bicho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'E disse Moisés: Comei-o hoje, porque hoje é sábado do SENHOR: hoje não achareis no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Nos seis dias o recolhereis; mas o sétimo dia é sábado, no qual não se achará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'E aconteceu que alguns do povo saíram no sétimo dia a recolher, e não acharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'E o SENHOR disse a Moisés: Até quando não querereis guardar meus mandamentos e minhas leis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Olhai que o SENHOR vos deu o sábado, e por isso vos dá no sexto dia pão para dois dias. Fique, pois, cada um em sua morada, e ninguém saia de seu lugar no sétimo dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Assim o povo repousou o sétimo dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'E a casa de Israel o chamou maná; e era como semente de coentro, branco, e seu sabor como de bolos com mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'E disse Moisés: Isto é o que o SENHOR mandou: Encherás um gômer dele para que se guarde para vossos descendentes, a fim de que vejam o pão que eu vos dei a comer no deserto, quando eu vos tirei da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'E disse Moisés a Arão: Toma um vaso e põe nele um gômer cheio de maná, e põe-o diante do SENHOR, para que seja guardado para vossos descendentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'E Arão o pôs diante do testemunho para guardá-lo, como o SENHOR o mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Assim os filhos de Israel comeram maná por quarenta anos, até que entraram em terra habitada; comeram maná até que chegaram ao limite da terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'E um gômer é a décima parte do efa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'E toda a congregação dos filhos de Israel partiu do deserto de Sim, por suas jornadas, ao mandamento do SENHOR, e assentaram o acampamento em Refidim: e não havia água para que o povo bebesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'E brigou o povo com Moisés, e disseram: Dá-nos água que bebamos. E Moisés lhes disse: Por que brigais comigo? Por que tentais ao SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Assim que o povo teve ali sede de água, e murmurou contra Moisés, e disse: Por que nos fizeste subir do Egito para matar-nos de sede a nós, e a nossos filhos e a nossos gados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Então clamou Moisés ao SENHOR, dizendo: Que farei com este povo? Daqui um pouco me apedrejarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'E o SENHOR disse a Moisés: Passa diante do povo, e toma contigo dos anciãos de Israel; e toma também em tua mão tua vara, com que feriste o rio, e vai:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Eis que eu estou diante de ti ali sobre a rocha em Horebe; e ferirás a rocha, e sairão dela águas, e beberá o povo. E Moisés o fez assim em presença dos anciãos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'E chamou o nome daquele lugar Massá e Meribá, pela briga dos filhos de Israel, e porque tentaram ao SENHOR, dizendo: Está, pois, o SENHOR entre nós, ou não?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'E veio Amaleque e lutou com Israel em Refidim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'E disse Moisés a Josué: Escolhe para nós homens, e sai, luta com Amaleque: amanhã eu estarei sobre o cume do morro, e a vara de Deus em minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'E fez Josué como lhe disse Moisés, lutando com Amaleque; e Moisés e Arão e Hur subiram ao cume do morro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'E sucedia que quando erguia Moisés sua mão, Israel prevalecia; mas quando ele baixava sua mão, prevalecia Amaleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'E as mãos de Moisés estavam pesadas; pelo que tomaram uma pedra, e puseram-na debaixo dele, e se sentou sobre ela; e Arão e Hur sustentavam suas mãos, o um de uma parte e o outro de outra; assim houve em suas mãos firmeza até que se pôs o sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'E Josué derrotou a Amaleque e a seu povo a fio de espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'E o SENHOR disse a Moisés: Escreve isto para memória em um livro, e dize a Josué que de todo tenho de apagar a memória de Amaleque de debaixo do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'E Moisés edificou um altar, e chamou seu nome O SENHOR é minha bandeira;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'E disse: Porquanto há mão sobre o trono do SENHOR, o SENHOR terá guerra com Amaleque de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'E ouviu Jetro, sacerdote de Midiã, sogro de Moisés, todas as coisas que Deus havia feito com Moisés, e com Israel seu povo, e como o SENHOR havia tirado a Israel do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'E tomou Jetro, sogro de Moisés a Zípora a mulher de Moisés, depois que ele a enviou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'E a seus dois filhos; um se chamava Gérson, porque disse: Peregrino fui em terra alheia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'E o outro se chamava Eliézer, porque disse, O Deus de meu pai me ajudou, e me livrou da espada de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'E Jetro o sogro de Moisés, com seus filhos e sua mulher, chegou a Moisés no deserto, onde tinha o acampamento junto ao monte de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'E disse a Moisés: Eu teu sogro Jetro venho a ti, com tua mulher, e seus dois filhos com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'E Moisés saiu a receber a seu sogro, e inclinou-se, e beijou-o: e perguntaram-se um ao outro como estavam, e vieram à tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'E Moisés contou a seu sogro todas as coisas que o SENHOR havia feito a Faraó e aos egípcios por causa de Israel, e todo o trabalho que haviam passado no caminho, e como os havia livrado o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'E alegrou-se Jetro de todo o bem que o SENHOR havia feito a Israel, que o havia livrado da mão dos egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'E Jetro disse: Bendito seja o SENHOR, que vos livrou da mão dos egípcios, e da mão de Faraó, e que livrou ao povo da mão dos egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Agora conheço que o SENHOR é maior que todos os deuses, até naquilo em que se vangloriavam contra o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'E tomou Jetro, sogro de Moisés, holocaustos e sacrifícios para Deus: e veio Arão e todos os anciãos de Israel a comer pão com o sogro de Moisés diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'E aconteceu que outro dia se sentou Moisés a julgar ao povo; e o povo esteve diante de Moisés desde a manhã até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'E vendo o sogro de Moisés tudo o que ele fazia com o povo, disse: Que é isto que fazes tu com o povo? por que te sentas tu sozinho, e todo o povo está diante de ti desde a manhã até à tarde?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'E Moisés respondeu a seu sogro: Porque o povo vem a mim para consultar a Deus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Quando têm negócios, vem a mim; e eu julgo entre o um e o outro, e declaro as ordenanças de Deus e suas leis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Então o sogro de Moisés lhe disse: Não fazes bem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Desfalecerás de todo, tu, e também este povo que está contigo; porque o negócio é demasiado pesado para ti; não poderás fazê-lo tu sozinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Ouve agora minha voz; eu te aconselharei, e Deus será contigo. Está tu pelo povo diante de Deus, e traze tu os negócios a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'E ensina a eles as ordenanças e as leis, e mostra-lhes o caminho por onde andem, e o que hão de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Ademais busca dentre todo o povo homens de virtude, temerosos de Deus, homens de verdade, que odeiem a ganância; e constituirás a estes sobre eles líderes sobre mil, sobre cem, sobre cinquenta e sobre dez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Os quais julgarão ao povo ao todo tempo; e será que todo negócio grave o trarão a ti, e eles julgarão todo negócio pequeno: alivia assim a carga de sobre ti, e eles a levarão contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Se isto fizeres, e Deus te o mandar, tu poderás persistir, e todo este povo se irá também em paz a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'E ouviu Moisés a voz de seu sogro, e fez tudo o que disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'E escolheu Moisés homens de virtude de todo Israel, e os pôs por chefes sobre o povo, líderes sobre mil, sobre cem, sobre cinquenta, e sobre dez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'E julgavam ao povo ao todo tempo; o negócio árduo traziam-no a Moisés, e eles julgavam todo negócio pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'E despediu Moisés a seu sogro, e foi-se à sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Ao mês terceiro da saída dos filhos de Israel da terra do Egito, naquele dia vieram ao deserto de Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Porque partiram de Refidim, e chegaram ao deserto de Sinai, e assentaram no deserto; e acampou ali Israel diante do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'E Moisés subiu a Deus; e o SENHOR o chamou desde o monte, dizendo: Assim dirás à casa de Jacó, e anunciarás aos filhos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vós vistes o que fiz aos egípcios, e como vos tomei sobre asas de águas, e vos trouxe a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Agora pois, se deres ouvido à minha voz, e guardardes meu pacto, vós sereis meu especial tesouro sobre todos os povos; porque minha é toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'E vós sereis meu reino de sacerdotes, e gente santa. Estas são as palavras que dirás aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Então veio Moisés, e chamou aos anciãos do povo, e propôs em presença deles todas estas palavras que o SENHOR lhe havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'E todo o povo respondeu em unidade, e disseram: Tudo o que o SENHOR disse faremos. E Moisés referiu as palavras do povo ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'E o SENHOR disse a Moisés: Eis que, eu venho a ti em uma nuvem espessa, para que o povo ouça enquanto eu falo contigo, e também para que te creiam para sempre. E Moisés anunciou as palavras do povo ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'E o SENHOR disse a Moisés: Vai ao povo, e santifica-os hoje e amanhã, e lavem suas roupas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'E estejam prontos para o dia terceiro, porque ao terceiro dia o SENHOR descerá, à vista de todo o povo, sobre o monte de Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'E assinalarás termo ao povo em derredor, dizendo: Guardai-vos, não subais ao monte, nem toqueis a seu termo: qualquer um que tocar o monte, certamente morrerá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Não lhe tocará mão, mas será apedrejado ou flechado; seja animal ou seja homem, não viverá. Em havendo soado longamente a trombeta, subirão ao monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'E desceu Moisés do monte ao povo, e santificou ao povo; e lavaram suas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'E disse ao povo: Estai prontos para o terceiro dia; não chegueis a mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'E aconteceu ao terceiro dia quando veio a manhã, que vieram trovões e relâmpagos, e espessa nuvem sobre o monte, e som de trombeta muito forte; e estremeceu-se todo o povo que estava no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'E Moisés tirou do acampamento ao povo a receber a Deus; e puseram-se ao abaixo do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'E todo o monte de Sinai fumegava, porque o SENHOR havia descido sobre ele em fogo: e a fumaça dele subia como a fumaça de um forno, e todo o monte se estremeceu em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'E o som da trombeta ia fortalecendo-se em extremo: Moisés falava, e Deus lhe respondia em voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'E desceu o SENHOR sobre o monte de Sinai, sobre o cume do monte: e chamou o SENHOR a Moisés ao cume do monte, e Moisés subiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'E o SENHOR disse a Moisés: Desce, exige ao povo que não ultrapassem o termo para ver ao SENHOR, para que não caia multidão deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'E também os sacerdotes que se achegam ao SENHOR, se santifiquem, para que o SENHOR não faça neles dano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'E Moisés disse ao SENHOR: O povo não poderá subir ao monte de Sinai, porque tu nos hás exigiste dizendo: Assinala termos ao monte, e santifica-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'E o SENHOR lhe disse: Vai, desce, e subirás tu, e Arão contigo: mas os sacerdotes e o povo não ultrapassem o termo para subir ao SENHOR, para que não faça neles dano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Então Moisés desceu ao povo e falou com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'E falou Deus todas estas palavras, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Eu sou o SENHOR teu Deus, que te tirei da terra do Egito, de casa de servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Não terás deuses alheios diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Não te farás imagem, nem nenhuma semelhança de coisa que esteja acima no céu, nem abaixo na terra, nem nas águas debaixo da terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Não te inclinarás a elas, nem as honrarás; porque eu sou o SENHOR teu Deus, forte, zeloso, que visito a maldade dos pais sobre os filhos, sobre os terceiros e sobre os quartos, aos que me aborrecem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'E que faço misericórdia em milhares aos que me amam, e guardam meus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Não tomarás o nome do SENHOR teu Deus em vão; porque não dará por inocente o SENHOR ao que tomar seu nome em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Tu te lembrarás do dia do repouso, para santificá-lo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Seis dias trabalharás, e farás toda tua obra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mas o sétimo dia será repouso para o SENHOR teu Deus: não faças nele obra alguma, tu, nem teu filho, nem tua filha, nem teu servo, nem tua criada, nem teu animal, nem teu estrangeiro que está dentro de tuas portas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Porque em seis dias fez o SENHOR os céus e a terra, o mar e todas as coisas que neles há, e repousou no sétimo dia: portanto o SENHOR abençoou o dia do repouso e o santificou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honra a teu pai e a tua mãe, para que teus dias se alarguem na terra que o SENHOR teu Deus te dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Não cometerás homicídio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Não cometerás adultério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Não furtarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Não falarás contra teu próximo falso testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Não cobiçarás a casa de teu próximo, não cobiçarás a mulher de teu próximo, nem seu servo, nem sua criada, nem seu boi, nem seu asno, nem coisa alguma de teu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Todo o povo considerava as vozes, e as chamas, e o som da trombeta, e o monte que fumegava: e vendo-o o povo, tremeram, e puseram-se de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'E disseram a Moisés: Fala tu conosco, que nós ouviremos; mas não fale Deus conosco, para que não morramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'E Moisés respondeu ao povo: Não temais; que para provar-vos veio Deus, e para que seu temor esteja em vossa presença para que não pequeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Então o povo se pôs de longe, e Moisés se chegou à escuridão na qual estava Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'E o SENHOR disse a Moisés: Assim dirás aos filhos de Israel: Vós vistes que falei desde o céu convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Não façais comigo deuses de prata, nem deuses de ouro vos fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Da terra farás altar para mim, e sacrificarás sobre ele teus holocaustos e tuas ofertas pacíficas, tuas ovelhas e tuas vacas: em qualquer lugar onde eu fizer que esteja a memória de meu nome, virei a ti, e te abençoarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'E se me fizeres altar de pedras, não as faças lavradas; porque se levantares teu buril sobre ele, tu o profanarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'E não subirás por degraus a meu altar, para que tua nudez não seja junto a ele descoberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'E estas são as ordenanças que lhes proporás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Se comprares servo hebreu, seis anos servirá; mas ao sétimo sairá livre de graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Se entrou sozinho, sozinho sairá: se tinha mulher, sairá ele e sua mulher com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Se seu amo lhe houver dado mulher, e ela lhe houver dado à luz filhos ou filhas, a mulher e seus filhos serão de seu amo, e ele sairá sozinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'E se o servo disser: Eu amo a meu senhor, a minha mulher e a meus filhos, não sairei livre:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Então seu amo o fará chegar aos juízes, e o fará chegar à porta ou ao umbral; e seu amo lhe furará a orelha com ferramenta pontiaguda, e será seu servo para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'E quando alguém vender sua filha por serva, não sairá como costumam sair os servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Se ela não agradar ao seu senhor, o qual não a tomou por esposa, permitirá a ela que se resgate, e ela não a poderá vender a povo estrangeiro, visto que não cumpriu seu compromisso com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Mas se a houver desposado com seu filho, fará com ela segundo o costume das filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Se tomar para si outra, não diminuirá seu alimento, nem sua porção de roupa, nem o direito conjugal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'E se nenhuma destas três coisas fizer, ela sairá de graça, e não terá que lhe pagar dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'O que ferir á alguém, fazendo-lhe assim morrer, ele morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mas o que não armou ciladas, mas sim que Deus o pôs em suas mãos, então eu te assinalarei lugar ao qual há de fugir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Além disso, se alguém se ensoberbecer contra seu próximo, e o matar traiçoeiramente, de meu altar o tirarás para que morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'E o que ferir a seu pai ou a sua mãe, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Também o que roubar uma pessoa, e a vender, ou se achar em suas mãos, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Igualmente o que amaldiçoar a seu pai ou a sua mãe, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Ademais, se alguns brigarem, e algum ferir a seu próximo com pedra ou com o punho, e não morrer, mas cair em cama;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Se se levantar e andar fora sobre seu cajado, então será o que lhe feriu absolvido: somente lhe pagará o tempo que esteve parado, e fará que lhe curem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'E se alguém ferir a seu servo ou a sua serva com pau, e morrer sob sua mão, será castigado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Mas se durar por um dia ou dois, não será castigado, porque seu dinheiro é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Se alguns brigarem, e ferissem a mulher grávida, e esta abortar, mas sem haver morte, será multado conforme o que lhe impuser o marido da mulher e julgarem os juízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mas se houver morte, então pagarás vida por vida,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Olho por olho, dente por dente, mão por meio, pé por pé,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Queimadura por queimadura, ferida por ferida, golpe por golpe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'E quando alguém ferir o olho de seu servo, ou o olho de sua serva, e o destruir, lhe dará liberdade por razão de seu olho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'E se tirar o dente de seu servo, ou o dente de sua serva, por seu dente lhe deixará ir livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Se um boi chifrar homem ou mulher, e de resultado morrer, o boi será apedrejado, e não se comerá sua carne; mas o dono do boi será absolvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Porém se o boi era chifrador desde o passado, e a seu dono lhe foi feito advertência, e não o houver guardado, e matar homem ou mulher, o boi será apedrejado, e também morrerá seu dono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Se lhe for imposto resgate, então dará pelo resgate de sua pessoa quanto lhe for imposto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Quer tenha chifrado filho, ou tenha chifrado filha, conforme este juízo se fará com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Se o boi chifrar servo ou serva, pagará trinta siclos de prata seu senhor, e o boi será apedrejado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'E se alguém abrir fosso, ou cavar cisterna, e não a cobrir, e cair ali boi ou asno,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'O dono da cisterna pagará o dinheiro, ressarcindo a seu dono, e o que foi morto será seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'E se o boi de alguém ferir ao boi de seu próximo, e este morrer, então venderão o boi vivo, e partirão o dinheiro dele, e também partirão o morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Mas se era notório que o boi era chifrador desde o passado, e seu dono não o houver guardado, pagará boi por boi, e o morto será seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Quando alguém furtar boi ou ovelha, e lhe degolar ou vender, por aquele boi pagará cinco bois, e por aquela ovelha quatro ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Se o ladrão for achado arrombando uma casa, e for ferido e morrer, o que lhe feriu não será culpado de sua morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Se o sol houver sobre ele saído, o matador será réu de homicídio: o ladrão haverá de restituir completamente; se não tiver, será vendido por seu furto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Se for achado com o furto na mão, seja boi ou asno ou ovelha vivos, pagará o dobro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Se alguém fizer pastar campo ou vinha, e meter seu animal, e comer a terra de outro, do melhor de sua terra e do melhor de sua vinha pagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Quando irromper um fogo, e achar espinhos, e for queimado amontoado, ou plantação, ou campo, o que acendeu o fogo pagará o queimado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Quando alguém der a seu próximo prata ou joias a guardar, e for furtado da casa daquele homem, se o ladrão se achar, pagará o dobro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Se o ladrão não se achar, então o dono da casa será apresentado aos juízes, para ver se pôs sua mão na riqueza de seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Sobre todo negócio de fraude, sobre boi, sobre asno, sobre ovelha, sobre roupa, sobre toda coisa perdida, quando um disser: Isto é meu, a causa de ambos virá diante dos juízes; e o que os juízes condenarem, pagará o dobro a seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Se alguém houver dado a seu próximo asno, ou boi, ou ovelha, ou qualquer outro animal a guardar, e se morrer ou se for aleijado, ou for levado sem vê-lo ninguém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Juramento do SENHOR terá lugar entre ambos de que não lançou sua mão à riqueza de seu próximo: e seu dono o aceitará, e o outro não pagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Mas se lhe houver sido furtado, ressarcirá a seu dono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'E se lhe houver sido arrebatado por fera, trará a ele testemunho, e não pagará o arrebatado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Porém se alguém houver tomado emprestado animal de seu próximo, e for ferido ou morto, ausente seu dono, deverá pagá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Se o dono estava presente, não o pagará. Se era alugado, ele virá por seu aluguel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'E se alguém enganar a alguma virgem que não for desposada, e dormir com ela, deverá pagar o dote por ela e tomá-la por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Se seu pai não quiser dá-la a ele, ele lhe pesará prata conforme o dote das virgens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'À feiticeira não deixarás que viva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Qualquer um que tiver ajuntamento com animal, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'O que sacrificar a deuses, exceto a somente o SENHOR, será morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'E ao estrangeiro não enganarás, nem angustiarás, porque estrangeiros fostes vós na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'A nenhuma viúva nem órfão afligireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Que se tu chegas a afligir-lhe, e ele a mim clamar, certamente ouvirei eu seu clamor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'E meu furor se acenderá, e vos matarei a espada, e vossas mulheres serão viúvas, e órfãos vossos filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Se deres a meu povo dinheiro emprestado, ao pobre que está contigo, não te portarás com ele como agiota, nem lhe imporás juros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Se tomares em penhor a roupa de teu próximo, a pôr do sol o devolverás a ele:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Porque somente aquilo é sua coberta, é aquela a roupa para cobrir suas carnes, no que há de dormir: e será que quando ele a mim clamar, eu então lhe ouvirei, porque sou misericordioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Não insultarás aos juízes, nem amaldiçoarás ao príncipe de teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Não adiarás as primícias de tua colheita, nem de teu licor, me darás o primogênito de teus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Assim farás com o de teu boi e de tua ovelha: sete dias estará com sua mãe, e ao oitavo dia me o darás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'E haveis de ser para mim homens santos: e não comereis carne arrebatada das feras no campo; aos cães a lançareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Não admitirás falso rumor. Não serás cúmplice com o ímpio para ser falsa testemunha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Não seguirás aos muitos para mal fazer; nem responderás em litigio inclinando-te à maioria para fazer injustiças;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'nem ao pobre privilegiarás em sua causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Se encontrares o boi de teu inimigo ou seu asno extraviado, traze-o de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Se vires o asno do que te aborrece caído debaixo de sua carga, lhe deixarás então desamparado? Sem falta ajudarás com ele a levantá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Não perverterás o direito de teu pobre em seu pleito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'De palavra de mentira te afastarás, e não matarás ao inocente e justo; porque eu não justificarei ao ímpio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Não receberás suborno; porque o suborno cega aos que veem, e perverte as palavras justas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'E não angustiarás ao estrangeiro: pois vós sabeis como se acha a alma do estrangeiro, já que estrangeiros fostes na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Seis anos semearás tua terra, e recolherás sua colheita:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mas no sétimo a deixarás vazia e liberarás, para que comam os pobres de teu povo; e do que restar comerão os animais do campo; assim farás de tua vinha e de teu olival.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Seis dias farás teus negócios, e ao sétimo dia folgarás, a fim que descanse teu boi e teu asno, e tome refrigério o filho de tua serva, e o estrangeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'E em tudo o que vos disse sereis avisados. E nome de outros deuses não mencionareis, nem se ouvirá de vossa boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Três vezes no ano me celebrareis festa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'A festa dos pães ázimos guardarás: Sete dias comerás os pães sem levedura, como eu te mandei, no tempo do mês de Abibe; porque nele saíste do Egito: e ninguém comparecerá vazio diante de mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Também a festa da colheita, os primeiros frutos de teus trabalhos que houveres semeado no campo; e a festa da colheita à saída do ano, quando haverás recolhido teus trabalhos do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Três vezes no ano comparecerá todo homem teu diante do Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Não oferecerás com pão levedado o sangue de meu sacrifício, nem a gordura de meu animal sacrificado ficará da noite até a manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'As primícias dos primeiros frutos de tua terra trarás à casa do SENHOR teu Deus. Não cozerás o cabrito com o leite de sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Eis que eu envio o anjo diante de ti para que te guarde no caminho, e te introduza no lugar que eu preparei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Guarda-te diante dele, e ouve sua voz; não lhe sejas rebelde; porque ele não perdoará vossa rebelião: porque meu nome está nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Porém se em verdade ouvires sua voz, e fizeres tudo o que eu te disser, serei inimigo a teus inimigos, e afligirei aos que te afligirem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Porque meu anjo irá adiante de ti, e te introduzirá aos amorreus, e aos heteus, e aos perizeus, e aos cananeus, e aos heveus, e aos jebuseus, aos quais eu farei destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Não te inclinarás a seus deuses, nem os servirás, nem farás como eles fazem; antes os destruirás por completo, e quebrarás inteiramente suas estátuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Mas ao SENHOR vosso Deus servireis, e ele abençoará teu pão e tuas águas; e eu tirarei toda enfermidade do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Não haverá mulher que aborte, nem estéril em tua terra; e eu cumprirei o número de teus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Eu enviarei meu terror diante de ti, e abaterei a todo povo onde tu entrares, e te darei o pescoço de todos os teus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Eu enviarei a vespa diante de ti, que lance fora aos heveus, e aos cananeus, e aos heteus, de diante de ti:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Não os expulsarei de diante de ti em ano, para que não fique a terra deserta, e se aumentem contra ti as feras do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Pouco a pouco os expulsarei de diante de ti, até que te multipliques e tomes a terra por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'E eu porei teu termo desde o mar Vermelho até o mar de filístia, e desde o deserto até o rio: porque porei em vossas mãos os moradores da terra, e tu os expulsarás de diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Não farás aliança com eles, nem com seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Em tua terra não habitarão, não seja que te façam pecar contra mim servindo a seus deuses: porque te será de tropeço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'E disse a Moisés: Sobe ao SENHOR, tu, e Arão, Nadabe, e Abiú, e setenta dos anciãos de Israel; e vos inclinareis desde longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mas Moisés somente se chegará ao SENHOR; e eles não se aproximem, nem suba com ele o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'E Moisés veio e contou ao povo todas as palavras do SENHOR, e todos os estatutos: e todo o povo respondeu em uma voz, e disseram: Executaremos todas as palavras que o SENHOR disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'E Moisés escreveu todas as palavras do SENHOR, e levantando-se de manhã edificou um altar ao pé do monte, e doze colunas, segundo as doze tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'E enviou aos rapazes dos filhos de Israel, os quais ofereceram holocaustos e sacrificaram pacíficos ao SENHOR, bezerros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'E Moisés tomou a metade do sangue, e a pôs em bacias, e espargiu a outra metade do sangue sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'E tomou o livro da aliança, e leu aos ouvidos do povo, o qual disse: Faremos todas as coisas que o SENHOR disse, e obedeceremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Então Moisés tomou o sangue, e salpicou sobre o povo, e disse: Eis o sangue da aliança que o SENHOR fez convosco sobre todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'E subiram Moisés e Arão, Nadabe e Abiú, e setenta dos anciãos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'E viram ao Deus de Israel; e havia debaixo de seus pés como um pavimento de safira, semelhante ao céu quando está claro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Mas não estendeu sua mão sobre os príncipes dos filhos de Israel: e viram a Deus, e comeram e beberam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Então o SENHOR disse a Moisés: Sobe a mim ao monte, e espera ali, e te darei tábuas de pedra, e a lei, e mandamentos que escrevi para ensiná-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'E levantou-se Moisés, e Josué seu assistente; e Moisés subiu ao monte de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'E disse aos anciãos: Esperai-nos aqui até que voltemos a vós: e eis que Arão e Hur estão convosco: o que tiver negócios chegue-se a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Então Moisés subiu ao monte, e uma nuvem cobriu o monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'E a glória do SENHOR repousou sobre o monte Sinai, e a nuvem o cobriu por seis dias: e ao sétimo dia chamou a Moisés do meio da nuvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'E a aparência da glória do SENHOR era como um fogo abrasador no cume do monte, aos olhos dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'E entrou Moisés em meio da nuvem, e subiu ao monte: e esteve Moisés no monte quarenta dias e quarenta noites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Dize aos filhos de Israel que tomem para mim oferta: de todo homem que a der de sua vontade, de coração, tomareis minha oferta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'E esta é a oferta que tomareis deles: Ouro, e prata, e bronze,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'E material azul, e púrpura, e carmesim, e linho fino, e pelo de cabras,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'E couros de carneiros tingidos de vermelho, e couros finos, e madeira de acácia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Azeite para a luminária, especiarias para o azeite da unção, e para o incenso aromático;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Pedras de ônix, e pedras de engastes, para o éfode, e para o peitoral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'E farão para mim um santuário, e eu habitarei entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Conforme tudo o que eu te mostrar, o desenho do tabernáculo, e o desenho de todos os seus objetos, assim o fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Farão também uma arca de madeira de acácia, cujo comprimento será de dois côvados e meio, e sua largura de côvado e meio, e sua altura de côvado e meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'E a cobrirás de ouro puro; por dentro e por fora a cobrirás; e farás sobre ela uma borda de ouro ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'E para ela farás de fundição quatro anéis de ouro, que porás a seus quatro cantos; dois anéis ao um lado dela, e dois anéis ao outro lado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'E farás umas varas de madeira de acácia, as quais cobrirás de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'E meterás as varas pelos anéis aos lados da arca, para levar a arca com elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'As varas se estarão nos anéis da arca: não se tirarão dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'E porás no arca o testemunho que eu te darei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'E farás uma coberta de ouro fino, cujo comprimento será de dois côvados e meio, e sua largura de côvado e meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Farás também dois querubins de ouro, lavrados a martelo os farás, nas duas extremidades do propiciatório.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Farás, pois, um querubim ao extremo de um lado, e um querubim ao outro extremo do lado oposto: da qualidade do propiciatório farás os querubins em suas duas extremidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'E os querubins estenderão por encima as asas, cobrindo com suas asas o propiciatório: suas faces a uma em frente da outra, olhando ao propiciatório as faces dos querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'E porás o propiciatório encima da arca, e no arca porás o testemunho que eu te darei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'E dali me declararei a ti, e falarei contigo de sobre o propiciatório, dentre os dois querubins que estão sobre a arca do testemunho, tudo o que eu te mandarei para os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Farás também uma mesa de madeira de acácia: seu comprimento será de dois côvados, e de um côvado sua largura, e sua altura de côvado e meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'E a cobrirás de ouro puro, e lhe farás uma borda de ouro ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Farás também para ele também uma moldura ao redor, da largura de uma mão, à qual moldura farás uma borda de ouro ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'E lhe farás quatro anéis de ouro, os quais porás aos quatro cantos que correspondem a seus quatro pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Os anéis estarão antes da moldura, por lugares das varas, para levar a mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'E farás as varas de madeira de acácia, e as cobrirás de ouro, e com elas será levada a mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Farás também seus pratos, e suas colheres, e seus jarros, e suas bacias, com que se fará libações: de ouro fino os farás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'E porás sobre a mesa o pão da proposição diante de mim continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Farás também um candelabro de ouro puro; lavrado a martelo se fará o candelabro: seu pé, e sua cana, seus copos, seus botões, e suas flores, serão do mesmo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'E sairão seis braços de seus lados: três braços do candelabro do um lado seu, e três braços do candelabro do outro seu lado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Três copos em forma de amêndoas em um braço, um botão e uma flor; e três copos, forma de amêndoas no outro braço, um botão e uma flor: assim, pois, nos seis braços que saem do candelabro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'E no candelabro quatro copos em forma de amêndoas, seus botões e suas flores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Haverá um botão debaixo dos dois braços do mesmo, outro botão debaixo dos outros dois braços do mesmo, e outra botão debaixo dos outros dois braços do mesmo, em conformidade aos seis braços que saem do candelabro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Seus botões e seus braços serão do mesmo, todo ele uma peça lavrada a martelo, de ouro puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'E farás para ele sete lâmpadas, as quais acenderás para que iluminem à parte de sua dianteira:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Também suas tenazes e seus apagadores, de ouro puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'De um talento de ouro fino o farás, com todos estes objetos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'E olha, e faze-os conforme seu modelo, que te foi mostrado no monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'E farás o tabernáculo de dez cortinas de linho torcido, azul, e púrpura, e carmesim: e farás querubins de obra delicada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'O comprimento da uma cortina de vinte e oito côvados, e a largura da mesma cortina de quatro côvados: todas as cortinas terão uma medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinco cortinas estarão juntas a uma com a outra, e cinco cortinas unidas a uma com a outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'E farás laçadas de azul na beira da uma cortina, na margem, na juntura: e assim farás na beira da última cortina na juntura segunda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Cinquenta laçadas farás na uma cortina, e cinquenta laçadas farás na margem da cortina que está na segunda juntura: as laçadas estarão contrapostas a uma à outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Farás também cinquenta colchetes de ouro, com os quais juntarás as cortinas a uma com a outra, e se formará um tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Farás também cortinas de pelo de cabras para uma tenda sobre o tabernáculo; onze cortinas farás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'O comprimento de uma cortina será de trinta côvados, e a largura da mesma cortina de quatro côvados: uma medida terão as onze cortinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'E juntarás as cinco cortinas à parte e as outras seis cortinas separadamente; e dobrarás a sexta cortina diante da face do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'E farás cinquenta laçadas na orla de uma cortina, à extremidade na juntura, e cinquenta laçadas na orla da segunda cortina na outra juntura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Farás também cinquenta colchetes de alambre, os quais meterás pelas laçadas: e juntarás a tenda, para que se faça uma só cobertura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'E o excedente que resulta nas cortinas da tenda, a metade da uma cortina que sobra, ficará às costas do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'E um côvado da uma parte, e outro côvado da outra que sobra no comprimento das cortinas da tenda, pendurará sobre os lados do tabernáculo da uma parte e da outra, para cobri-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Farás também à tenda uma coberta de couros de carneiros, tingidos de vermelho, e uma coberta de couros finos encima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'E farás para o tabernáculo tábuas de madeira de acácia, que estejam na vertical.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'O comprimento de cada tábua será de dez côvados, e de côvado e meio a largura de cada tábua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Dois encaixes terá cada tábua, unidos um com o outro; assim farás todas as tábuas do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Farás, pois, as tábuas do tabernáculo: vinte tábuas ao lado do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'E farás quarenta bases de prata debaixo das vinte tábuas; duas bases debaixo de uma tábua para seus dois encaixes, e duas bases debaixo da outra tábua para seus dois encaixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'E ao outro lado do tabernáculo, à parte do norte, vinte tábuas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'E suas quarenta bases de prata: duas bases debaixo de uma tábua, e duas bases debaixo da outra tábua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'E para o lado do tabernáculo, ao ocidente, farás seis tábuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Farás também duas tábuas para as esquinas do tabernáculo nos dois ângulos posteriores;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Os quais se unirão por abaixo, e também se juntarão por seu alto a uma argola: assim será das outras duas que estarão às duas esquinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'De maneira que serão oito tábuas, com suas bases de prata, dezesseis bases; duas bases debaixo de uma tábua, e duas bases debaixo da outra tábua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Farás também cinco barras de madeira de acácia, para as tábuas de um lado do tabernáculo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'E cinco barras para as tábuas do outro lado do tabernáculo, e cinco barras para o outro lado do tabernáculo, que está ao ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'E a barra do meio passará por meio das tábuas, de uma extremidade à outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'E cobrirás as tábuas de ouro, e farás seus anéis de ouro para meter por eles as barras: também cobrirás as barras de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'E levantarás o tabernáculo conforme sua planta que te foi mostrada no monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'E farás também um véu de azul, e púrpura, e carmesim, e de linho torcido: será feito de primoroso trabalho, com querubins:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'E hás de pô-lo sobre quatro colunas de madeira de acácia cobertas de ouro; seus capitéis de ouro, sobre bases de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'E porás o véu debaixo dos colchetes, e meterás ali, do véu dentro, a arca do testemunho; e aquele véu vos fará separação entre o lugar santo e o santíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'E porás a coberta sobre a arca do testemunho no lugar santíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'E porás a mesa fora do véu, e o candelabro em frente da mesa ao lado do tabernáculo ao sul; e porás a mesa ao lado do norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'E farás à porta do tabernáculo uma cortina de azul, e púrpura, e carmesim, e linho torcido, obra de bordador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'E farás para a cortina cinco colunas de madeira de acácia, as quais cobrirás de ouro, com seus capitéis de ouro: e as farás de fundição cinco bases de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Farás também altar de madeira de acácia de cinco côvados de comprimento, e de cinco côvados de largura: será quadrado o altar, e sua altura de três côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'E farás suas pontas a seus quatro cantos; as pontas serão do mesmo; e as cobrirás de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Farás também seus caldeirões para lançar sua cinza; e suas pás, e suas bacias, e seus garfos, e seus braseiros: farás todos os seus vasos de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'E lhe farás uma grelha de bronze de obra de malha; e sobre a grelha farás quatro anéis de bronze a seus quatro cantos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'E o porás dentro da borda do altar abaixo; e chegará a grelha até o meio do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Farás também varas para o altar, varas de madeira de acácia, as quais cobrirás de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'E suas varas se meterão pelos anéis: e estarão aquelas varas a ambos lados do altar, quando houver de ser levado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'De tábuas o farás, oco: da maneira que te foi mostrado no monte, assim o farás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Também farás o átrio do tabernáculo: ao lado do sul, terá o átrio cortinas de linho torcido, de cem côvados de comprimento cada um lado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Suas vinte colunas, e suas vinte bases serão de bronze; os capitéis das colunas e suas molduras, de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'E da mesma maneira ao lado do norte haverá ao comprimento cortinas de cem côvados de comprimento, e suas vinte colunas, com suas vinte bases de bronze; os capitéis de suas colunas e suas molduras, de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'E a largura do átrio do lado ocidental terá cortinas de cinquenta côvados; suas colunas dez, com suas dez bases.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'E na largura do átrio pela parte do oriente, haverá cinquenta côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'E as cortinas de um lado serão de quinze côvados; suas colunas três, com suas três bases.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Ao outro lado quinze côvados de cortinas; suas colunas três, com suas três bases.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'E à porta do átrio haverá uma cortina de vinte côvados, de azul, e púrpura, e carmesim, e linho torcido, de obra de bordador: suas colunas quatro, com suas quatro bases.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Todas as colunas do átrio em derredor serão cingidas de prata; seus capitéis de prata, e suas bases de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'O comprimento do átrio será de cem côvados, e a largura cinquenta por um lado e cinquenta pelo outro, e a altura de cinco côvados: suas cortinas de linho torcido, e suas bases de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Todos os utensílios do tabernáculo em todo o seu serviço, e todos os seus pregos, e todos os pregos do átrio, serão de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'E tu mandarás aos filhos de Israel que te tragam azeite puro de olivas, prensado, para a luminária, para fazer arder continuamente as lâmpadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'No tabernáculo do testemunho, fora do véu que está diante do testemunho, as porá em ordem Arão e seus filhos, diante do SENHOR desde a tarde até a manhã, como estatuto perpétuo dos filhos de Israel por suas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'E tu aproxima a ti a Arão teu irmão, e a seus filhos consigo, dentre os filhos de Israel, para que sejam meus sacerdotes; a Arão, Nadabe e Abiú, Eleazar e Itamar, filhos de Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'E farás vestimentas sagradas a Arão teu irmão, para honra e formosura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'E tu falarás a todos os sábios de coração, aos quais eu enchi de espírito de sabedoria; a fim de que façam as roupas de Arão, para consagrar-lhe a que me sirva de sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'As vestimentas que farão são estes: o peitoral, e o éfode, e o manto, e a túnica bordada, a mitra, e o cinturão. Façam, pois, as sagradas vestimentas a Arão teu irmão, e a seus filhos, para que sejam meus sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Tomarão ouro, e azul, e púrpura, e carmesim, e linho torcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'E farão o éfode de ouro e azul, e púrpura, e carmesim, e linho torcido de obra de bordador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Terá duas ombreiras que se juntem a seus dois lados, e se juntará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'E o artifício de seu cinto que está sobre ele, será de sua mesma obra, do mesmo; de ouro, azul, e púrpura, e carmesim, e linho torcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'E tomarás duas pedras de ônix, e gravarás nelas os nomes dos filhos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Os seis de seus nomes em uma pedra, e os outros seis nomes na outra pedra, conforme o nascimento deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'De obra de escultor em pedra a modo de gravuras de selo, farás gravar aquelas duas pedras com os nomes dos filhos de Israel; farás para eles ao redor engastes de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'E porás aquelas duas pedras sobre os ombros do éfode, para pedras de memória aos filhos de Israel; e Arão levará os nomes deles diante do SENHOR em seus dois ombros por memória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Farás, pois, engastes de ouro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'E duas correntinhas de ouro fino; as quais farás de feitura de trança; e fixarás as correntes de feitura de trança nos engastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Farás também o peitoral do juízo de primorosa obra, lhe farás conforme a obra do éfode, de ouro, e azul, e púrpura, e carmesim, e linho torcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Será quadrado e duplo, de um palmo de comprimento e um palmo de largura:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'E o encherás de pedrarias com quatro ordens de pedras: uma ordem de uma pedra sárdio, um topázio, e um carbúnculo; será a primeira ordem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'A segunda ordem, uma esmeralda, uma safira, e um diamante;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'A terceira ordem, um rubi, uma ágata, e uma ametista;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'E a quarta ordem, um berilo, um ônix, e um jaspe: estarão engastadas em ouro em seus encaixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'E serão aquelas pedra segundo os nomes dos filhos de Israel, doze segundo seus nomes; como gravuras de selo cada uma com seu nome, virão a ser segundo as doze tribos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Farás também no peitoral correntes de feitura de tranças de ouro fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'E farás no peitoral dois anéis de ouro, os quais dois anéis porás às duas pontas do peitoral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'E porás as duas tranças de ouro nos dois anéis às duas pontas do peitoral:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'E as duas extremidades das duas tranças sobre os dois engastes, e as porás aos lados do éfode na parte dianteira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Farás também dois anéis de ouro, os quais porás às duas pontas do peitoral, em sua orla que está ao lado do éfode da parte de dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Farás também dois anéis de ouro, os quais porás aos dois lados do éfode abaixo na parte dianteira, diante de sua juntura sobre o cinto do éfode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'E juntarão o peitoral com seus anéis aos anéis do éfode com um cordão de azul, para que esteja sobre o cinto do éfode, e não se separe o peitoral do éfode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'E levará Arão os nomes dos filhos de Israel no peitoral do juízo sobre seu coração, quando entrar no santuário, para memória diante do SENHOR continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'E porás no peitoral do juízo Urim e Tumim, para que estejam sobre o coração de Arão quando entrar diante do SENHOR: e levará sempre Arão o juízo dos filhos de Israel sobre seu coração diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Farás o manto do éfode todo de material azul:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'E em meio dele por acima haverá uma abertura, a qual terá uma borda ao redor de obra de tecelão, como a abertura de um colarinho, para que não se rompa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'E abaixo em suas orlas farás romãs de material azul, e púrpura, e carmesim, por suas bordas ao redor; e entre elas sinos de ouro ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Um sino de ouro e uma granada, sino de ouro e granada, pelas orlas do manto ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'E estará sobre Arão quando ministrar; e se ouvirá seu som quando ele entrar no santuário diante do SENHOR e quando sair, porque não morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Farás também uma prancha de ouro fino, e gravarás nela gravura de selo, SANTIDADE AO SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'E a porás com um cordão de azul, e estará sobre a mitra; pela frente anterior da mitra estará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'E estará sobre a testa de Arão: e levará Arão o pecado das coisas santas, que os filhos de Israel houverem consagrado em todas as suas santas ofertas; e sobre sua testa estará continuamente para que tenham favor diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'E bordarás uma túnica de linho, e farás uma mitra de linho; farás também um cinto de obra de bordador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'E para os filhos de Arão farás túnicas; também lhes farás cintos, e lhes formarás tiaras para honra e adorno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'E com eles vestirás a Arão teu irmão, e a seus filhos com ele: e os ungirás, e os consagrarás, e santificarás, para que sejam meus sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'E lhes farás calções de linho para cobrir a carne vergonhosa; serão desde os lombos até as coxas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'E estarão sobre Arão e sobre seus filhos quando entrarem no tabernáculo de testemunho, ou quando se achegarem ao altar para servir no santuário, para que não levem pecado, e morram. Estatuto perpétuo para ele, e para sua semente depois dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'E Isto é o que lhes farás para consagrá-los, para que sejam meus sacerdotes: Toma um bezerro das vacas, e dois carneiros sem mácula;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'E pães sem levedura, e tortas sem levedura amassadas com azeite, e massas sem levedura untadas com azeite; as quais coisas farás de flor de farinha de trigo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'E as porás em um cesto, e no cesto as oferecerás, com o bezerro e os dois carneiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'E farás chegar a Arão e a seus filhos à porta do tabernáculo do testemunho, e os lavarás com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'E tomarás as vestiduras, e vestirás a Arão a túnica e o manto do éfode, e o éfode, e o peitoral, e lhe cingirás com o cinto do éfode;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'E porás a mitra sobre sua cabeça, e sobre a mitra porás a coroa santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'E tomarás o azeite da unção, e derramarás sobre sua cabeça, e lhe ungirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'E farás chegar seus filhos, e lhes vestirás as túnicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'E lhes cingirás o cinto, a Arão e a seus filhos, e lhes atarás as tiaras, e terão o sacerdócio por estatuto perpétuo: e encherás as mãos de Arão e de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'E farás chegar o bezerro diante do tabernáculo do testemunho, e Arão e seus filhos porão suas mãos sobre a cabeça do bezerro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'E matarás o bezerro diante do SENHOR à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'E tomarás do sangue do bezerro, e porás sobre as pontas do altar com teu dedo, e derramarás todo o demais sangue ao pé do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Tomarás também toda a gordura que cobre os intestinos, e o redenho de sobre o fígado, e os dois rins, e a gordura que está sobre eles, e os queimarás sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Porém consumirás a fogo fora do acampamento a carne do bezerro, e seu couro, e seu excremento: é expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Também tomarás um carneiro, e Arão e seus filhos porão suas mãos sobre a cabeça do carneiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'E matarás o carneiro, e tomarás seu sangue, e salpicarás sobre o altar ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'E cortarás o carneiro em pedaços, e lavarás seus intestinos e suas pernas, e as porás sobre seus pedaços e sobre sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'E queimarás todo o carneiro sobre o altar: é holocausto ao SENHOR, cheiro suave, é oferta queimada ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Tomarás logo o outro carneiro, e Arão e seus filhos porão suas mãos sobre a cabeça do carneiro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'E matarás o carneiro, e tomarás de seu sangue, e porás sobre a ponta da orelha direita de Arão, e sobre a ponta das orelhas de seus filhos, e sobre o dedo polegar das mãos direitas deles, e sobre o dedo polegar dos pés direitos deles, e espargirás o sangue sobre o altar ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'E tomarás do sangue que há sobre o altar, e do azeite da unção, e espargirás sobre Arão, e sobre suas vestiduras, e sobre seus filhos, e sobre as vestimentas destes; e ele será santificado, e suas vestiduras, e seus filhos, e as vestimentas de seus filhos com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Logo tomarás do carneiro a gordura, e a cauda, e a gordura que cobre os intestinos, e o redenho do fígado, e os dois rins, e a gordura que está sobre eles, e a coxa direita; porque é carneiro de consagrações:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Também uma torta de pão, e uma massa amassada com azeite, e um bolo do cesto dos pães ázimos apresentado ao SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'E o porás tudo nas mãos de Arão, e nas mãos de seus filhos; e o mexerás agitando-o diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Depois o tomarás de suas mãos, e o farás arder sobre o altar em holocausto, por cheiro agradável diante do SENHOR. É oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'E tomarás o peito do carneiro das consagrações, que foi imolado para a de Arão, e o mexerás por oferta agitada diante do SENHOR; e será porção tua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'E separarás o peito da oferta mexida, e a coxa da santificação, o que foi mexido e o que foi santificado do carneiro das consagrações de Arão e de seus filhos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'E será para Arão e para seus filhos por estatuto perpétuo dos filhos de Israel, porque é porção elevada; e será tomada dos filhos de Israel de seus sacrifícios pacíficos, porção deles elevada em oferta ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'E as vestimentas santas, que são de Arão, serão de seus filhos depois dele, para ser ungidos com elas, e para ser com elas consagrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Por sete dias as vestirá o sacerdote de seus filhos, que em seu lugar vier ao tabernáculo do testemunho a servir no santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'E tomarás o carneiro das consagrações, e cozerás sua carne no lugar do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'E Arão e seus filhos comerão a carne do carneiro, e o pão que está no cesto, à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'E comerão aquelas coisas com as quais se fez expiação, para encher suas mãos para ser santificados: mas o estrangeiro não comerá, porque é coisa santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'E se sobrar algo da carne das consagrações e do pão até a manhã, queimarás ao fogo o que houver sobrado: não se comerá, porque é coisa santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Assim, pois, farás a Arão e a seus filhos, conforme todas as coisas que eu te mandei: por sete dias os consagrarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'E sacrificarás o bezerro da expiação em cada dia para as expiações; e purificarás o altar em havendo feito expiação por ele, e o ungirás para santificá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Por sete dias expiarás o altar, e o santificarás, e será um altar santíssimo: qualquer um coisa que tocar ao altar, será santificada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'E isto é o que oferecerás sobre o altar: dois cordeiros de ano cada dia, sem interrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Oferecerás um cordeiro à manhã, e o outro cordeiro oferecerás à queda da tarde:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Também uma décima parte de um efa de flor de farinha amassada com a quarta parte de um him de azeite prensado: e a libação será a quarta parte de um him de veio com cada cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'E oferecerás o outro cordeiro à queda da tarde, fazendo conforme a oferta da manhã, e conforme sua libação, em cheiro de suavidade; será oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Isto será holocausto contínuo por vossas gerações à porta do tabernáculo do testemunho diante do SENHOR, no qual me encontrarei convosco, para falar-vos ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'E ali testificarei de mim aos filhos de Israel, e o lugar será santifiquei com minha glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'E santificarei o tabernáculo do testemunho e o altar: santificarei também a Arão e a seus filhos, para que sejam meus sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'E habitarei entre os filhos de Israel, e serei seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'E conhecerão que eu sou o SENHOR seu Deus, que os tirei da terra do Egito, para habitar em meio deles: Eu sou o SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Farás também um altar para queimar incenso: de madeira de acácia o farás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Seu comprimento será de um côvado, e sua largura de um côvado: será quadrado: e sua altura de dois côvados: e suas pontas serão do mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'E o cobrirás de ouro puro, sua parte superior, e suas paredes em derredor, e suas pontas: e lhe farás em derredor uma coroa de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Tu lhe farás também dois anéis de ouro debaixo de sua coroa a seus dois cantos em ambos lados seus, para meter as varas com que será levado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'E farás as varas de madeira de acácia, e os cobrirás de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'E o porás diante do véu que está junto à arca do testemunho, diante do propiciatório que está sobre o testemunho, onde eu te testificarei de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'E queimará sobre ele Arão incenso de aroma cada manhã quando preparar as lâmpadas o queimará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'E quando Arão acender as lâmpadas ao anoitecer, queimará o incenso: rito perpétuo diante do SENHOR por vossas idades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Não oferecereis sobre ele incenso estrangeiro, nem holocausto, nem presente; nem tampouco derramareis sobre ele libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'E sobre suas pontas fará Arão expiação uma vez no ano com o sangue da expiação para as reconciliações: uma vez no ano fará expiação sobre ele em vossas idades: será muito santo ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Quando tomares o número dos filhos de Israel conforme a conta deles, cada um dará ao SENHOR o resgate de sua pessoa, quando os contares, e não haverá neles mortandade por havê-los contado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Isto dará qualquer um que passar pela contagem, meio siclo conforme o siclo do santuário. O siclo é de vinte óbolos: a metade de um siclo será a oferta ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Qualquer um que passar pela contagem, de vinte anos acima, dará a oferta ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Nem o rico aumentará, nem o pobre diminuirá de meio siclo, quando derem a oferta ao SENHOR para fazer expiação por vossas pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'E tomarás dos filhos de Israel o dinheiro das expiações, e o darás para a obra do tabernáculo do testemunho: e será por memória aos filhos de Israel diante do SENHOR, para expiar vossas pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Falou mais o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Farás também uma pia de bronze, com sua base de bronze, para lavar; e a porás entre o tabernáculo do testemunho e o altar; e porás nela água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'E dela se lavarão Arão e seus filhos suas mãos e seus pés:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Quando entrarem no tabernáculo do testemunho, se hão de lavar com água, e não morrerão: e quando se achegarem ao altar para ministrar, para acender ao SENHOR a oferta que se há de consumir ao fogo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Também se lavarão as mãos e os pés, e não morrerão. E o terão por estatuto perpétuo ele e sua semente por suas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Falou mais o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'E tu tomarás das principais especiarias; de mirra excelente quinhentos siclos, e de canela aromática a metade, isto é, duzentos e cinquenta, e de cálamo aromático duzentos e cinquenta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'E de cássia quinhentos, ao peso do santuário, e de azeite de olivas um him:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'E farás disso o azeite da santa unção, superior unguento, obra de perfumista, o qual será o azeite da unção sagrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Com ele ungirás o tabernáculo do testemunho, e a arca do testemunho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'E a mesa, e todos os seus utensílios, e o candelabro, e todos os seus utensílios, e o altar do incenso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'E o altar do holocausto, todos os seus utensílios, e a pia e sua base.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Assim os consagrarás, e serão coisas santíssimas: tudo o que tocar neles, será santificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Ungirás também a Arão e a seus filhos, e os consagrarás para que sejam meus sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'E falarás aos filhos de Israel, dizendo: Este será meu azeite da santa unção por vossas idades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Sobre carne de homem não será untado, nem fareis outro semelhante, conforme sua composição: santo é; por santo haveis de tê-lo vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Qualquer um que compuser unguento semelhante, e que puser dele sobre estranho, será cortado de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Disse ainda o SENHOR a Moisés: Toma para ti aromas, resina de estoraque e um material odorífero e gálbano aromático e incenso limpo; de tudo em igual peso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'E farás disso uma mistura aromática de obra de perfumista, bem misturada, pura e santa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'E moerás alguma dela pulverizando-a, e a porás diante do testemunho no tabernáculo do testemunho, onde eu te testificarei de mim. Isso vos será coisa santíssima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Como a mistura que farás, não vos fareis outra segundo sua composição: te será coisa sagrada para o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Qualquer um que fizer outra como ela para cheirá-la, será cortado de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Olha, eu chamei por seu nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'E o enchi de espírito de Deus, em sabedoria, e em inteligência, e em conhecimento, e em todo artifício,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Para inventar desenhos, para trabalhar em ouro, e em prata, e em bronze,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'E em artifício de pedras para engastá-las, e em artifício de madeira; para agir em todo tipo de trabalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'E eis que eu pus com ele a Aoliabe, filho de Aisamaque, da tribo de Dã: e pus sabedoria no ânimo de todo sábio de coração, para que façam tudo o que te mandei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'O tabernáculo do testemunho, e a arca do testemunho, e o propiciatório que está sobre ela, e todos os utensílios do tabernáculo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'E a mesa e seus utensílios, e o candelabro limpo e todos os seus utensílios, e o altar do incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'E o altar do holocausto e todos os seus utensílios, e a pia e sua base;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'E as roupas do serviço, e as santas vestiduras para Arão o sacerdote, e as vestiduras de seus filhos, para que exerçam o sacerdócio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'E o azeite da unção, e o incenso aromático para o santuário: farão conforme tudo o que te mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Falou também o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'E tu falarás aos filhos de Israel, dizendo: Com tudo isso vós guardareis meus sábados: porque é sinal entre mim e vós por vossas gerações, para que saibais que eu sou o SENHOR que vos santifico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Assim guardareis o sábado, porque santo é a vós: o que o profanar, certamente morrerá; porque qualquer um que fizer obra alguma nele, aquela alma será cortada do meio de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Seis dias se fará obra, mas o dia sétimo é sábado de repouso consagrado ao SENHOR; qualquer um que fizer obra no dia do sábado certamente morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Guardarão, pois, o sábado os filhos de Israel: celebrando-o por suas gerações por pacto perpétuo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Sinal é para sempre entre mim e os filhos de Israel; porque em seis dias fez o SENHOR os céus e a terra, e no sétimo dia cessou, e repousou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'E deu a Moisés quando acabou de falar com ele no monte de Sinai, duas tábuas do testemunho, tábuas de pedra escritas com o dedo de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Mas vendo o povo que Moisés tardava em descer do monte, achegou-se então a Arão, e disseram-lhe: Levanta-te, faze-nos deuses que vão adiante de nós; porque a este Moisés, aquele homem que tirou da terra do Egito, não sabemos o que lhe aconteceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'E Arão lhes disse: Separai os pendentes de ouro que estão nas orelhas de vossas mulheres, e de vossos filhos, e de vossas filhas, e trazei-os a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Então todo o povo separou os pendentes de ouro que tinham em suas orelhas, e trouxeram-nos a Arão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'O qual os tomou das mãos deles, e formou-o com buril, e fez disso um bezerro de fundição. Então disseram: Israel, estes são teus deuses, que te tiraram da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'E vendo isto Arão, edificou um altar diante do bezerro; e apregoou Arão, e disse: Amanhã será festa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'E no dia seguinte madrugaram, e ofereceram holocaustos, e apresentaram pacíficos: e sentou-se o povo a comer e a beber, e levantaram-se a regozijar-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Então o SENHOR disse a Moisés: Anda, desce, porque teu povo que tiraste da terra do Egito se corrompeu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Logo se apartaram do caminho que eu lhes mandei, e se fizeram um bezerro de fundição, e o adoraram, e sacrificaram a ele, e disseram: Israel, estes são teus deuses, que te tiraram da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Disse mais o SENHOR a Moisés: Eu vi a este povo, que por certo é povo de dura cerviz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Agora, pois, deixa-me que se acenda meu furor neles, e os consuma: e a ti eu porei sobre grande gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Então Moisés orou à face do SENHOR seu Deus, e disse: Ó SENHOR, por que se acenderá teu furor em teu povo, que tu tiraste da terra do Egito com grande força, e com mão forte?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Por que hão de falar os egípcios, dizendo: Para o mal os tirou, para matá-los nos montes, e para exterminá-los de sobre a face da terra? Volta-te do furor de tua ira, e arrepende-te do mal de teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Lembra-te de Abraão, de Isaque, e de Israel teus servos, aos quais juraste por ti mesmo, e disse-lhes: Eu multiplicarei vossa semente como as estrelas do céu; e darei a vossa semente toda esta terra que disse, e a tomarão por herança para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Então o SENHOR se arrependeu do mal que disse que havia de fazer a seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'E virou-se Moisés, e desceu do monte trazendo em sua mão as duas tábuas do testemunho, as tábuas escritas por ambos os lados; de uma parte e de outra estavam escritas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'E as tábuas eram obra de Deus, e a escritura era escritura de Deus gravada sobre as tábuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'E ouvindo Josué o clamor do povo que gritava, disse a Moisés: Barulho de batalha há no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'E ele respondeu: Não é eco de gritos de vitória de fortes, nem eco de gritos de fracos: eu ouço barulho de cantorias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'E aconteceu, que quando chegou ele ao acampamento, e viu o bezerro e as danças, acendeu-se a ira a Moisés, e lançou as tábuas de suas mãos, e quebrou-as ao pé do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'E tomou o bezerro que fizeram, e queimou-o no fogo, e moeu-o até reduzi-lo a pó, que espalhou sobre as águas, e deu-o a beber aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'E disse Moisés a Arão: Que te fez este povo, que trouxeste sobre ele tão grande pecado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'E respondeu Arão: Não se ire meu senhor; tu conheces o povo, que é inclinado ao mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Porque me disseram: Faze-nos deuses que vão adiante de nós, que a este Moisés, o homem que tirou da terra do Egito, não sabemos o que lhe aconteceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'E eu lhes respondi: Quem tem ouro? Separai-o. E o deram a mim, e lancei-o no fogo, e saiu este bezerro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'E vendo Moisés que o povo estava descontrolado, porque Arão o havia deixado se descontrolarem para vergonha entre seus inimigos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Pôs-se Moisés à porta do acampamento, e disse: Quem é do SENHOR? junte-se comigo. E juntaram-se com ele todos os filhos de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'E ele lhes disse: Assim disse o SENHOR, o Deus de Israel: Ponde cada um sua espada sobre sua coxa: passai e voltai de porta em porta pelo acampamento, e matai cada um a seu irmão, e a seu amigo, e a seu parente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'E os filhos de Levi o fizeram conforme o dito de Moisés: e caíram do povo naquele dia como três mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Então Moisés disse: Hoje vos consagrastes ao SENHOR, porque cada um se consagrou em seu filho, e em seu irmão, para que dê ele hoje bênção sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'E aconteceu que no dia seguinte disse Moisés ao povo: Vós cometestes um grande pecado: mas eu subirei agora ao SENHOR; talvez lhe consiga apaziguar o furor acerca de vosso pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Então voltou Moisés ao SENHOR, e disse: Rogo-te, pois este povo cometeu um grande pecado, porque fizeram para si deuses de ouro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Que perdoes agora seu pecado, e se não, apaga-me agora de teu livro que escreveste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'E o SENHOR respondeu a Moisés: Ao que pecar contra mim, a este apagarei eu de meu livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Vai, pois, agora, leva a este povo aonde te disse: eis que meu anjo irá diante de ti; que no dia de minha visitação eu visitarei neles seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'E o SENHOR feriu ao povo, porque fizeram o bezerro que formou Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'E o SENHOR disse a Moisés: Vai, sobe daqui, tu e o povo que tiraste da terra do Egito, à terra da qual jurei a Abraão, Isaque, e Jacó, dizendo: À tua semente a darei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'E eu enviarei diante de ti o anjo, e lançarei fora aos cananeus e aos amorreus, e aos heteus, e aos perizeus, e aos heveus e aos jebuseus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, '(À terra que flui leite e mel); porque eu não subirei em meio de ti, porque és povo de dura cerviz, não seja que te consuma no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'E ouvindo o povo esta desagradável palavra, vestiram luto, e ninguém se pôs seus ornamentos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Pois o SENHOR disse a Moisés: Dize aos filhos de Israel: Vós sois povo de dura cerviz: em um momento subirei em meio de ti, e te consumirei: tira de ti, pois, agora teus ornamentos, que eu saberei o que te tenho de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Então os filhos de Israel se despojaram de seus ornamentos desde o monte Horebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'E Moisés tomou o tabernáculo, e estendeu-o fora do acampamento, longe do acampamento, e chamou-o o Tabernáculo do Testemunho. E foi que qualquer um que buscava ao SENHOR saía ao tabernáculo do testemunho, que estava fora do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'E sucedia que, quando saía Moisés ao tabernáculo, todo o povo se levantava, e estava cada qual em pé à porta de sua tenda, e olhavam por trás de Moisés, até que ele entrava no tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'E quando Moisés entrava no tabernáculo, a coluna de nuvem descia, e punha-se à porta do tabernáculo, e o SENHOR falava com Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'E vendo todo o povo a coluna de nuvem, que estava à porta do tabernáculo, levantava-se todo o povo, cada um à porta de sua tenda e adorava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'E falava o SENHOR a Moisés face a face, como fala qualquer um a seu companheiro. E voltava-se ao campo; mas o jovem Josué, seu criado, filho de Num, nunca se afastava do meio do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'E disse Moisés ao SENHOR: Olha, tu me dizes a mim: Tira este povo: e tu não me declaraste a quem hás de enviar comigo: porém, tu dizes: Eu te conheci por teu nome, e achaste também graça em meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Agora, pois, se achei graça em teus olhos, rogo-te que me mostres agora teu caminho, para que te conheça, para que ache graça em teus olhos: e olha que teu povo é esta gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'E ele disse: Meu rosto irá contigo, e te farei descansar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'E ele respondeu: Se teu rosto não for comigo, não nos tires daqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'E em que se conhecerá aqui que achei favor em teus olhos, eu e teu povo, se não em andar tu conosco, e que eu e teu povo sejamos separados de todos os povos que estão sobre a face da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'E o SENHOR disse a Moisés: Também farei isto que disseste, porquanto achaste favor em meus olhos, e te conheci por teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'O então disse: Rogo-te que me mostres tua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'E respondeu-lhe: Eu farei passar todo o meu bem diante de teu rosto, e proclamarei o nome do SENHOR diante de ti; e terei misericórdia do que terei misericórdia, e serei clemente para com o que serei clemente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Disse mais: Não poderás ver meu rosto: porque não me verá homem, e viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'E disse ainda o SENHOR: Eis aqui um lugar junto a mim, e tu estarás sobre a rocha:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'E será que, quando passar minha glória, eu te porei em uma brecha da rocha, e te cobrirei com minha mão até que tenha passado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Depois tirarei minha mão, e verás minhas costas; mas não se verá meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'E o SENHOR disse a Moisés: Entalha para ti duas tábuas de pedra como as primeiras, e escreverei sobre essas tábuas as palavras que estavam nas tábuas primeiras que quebraste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Prepara-te, pois, para amanhã, e sobe pela manhã ao monte de Sinai, e fica diante de mim ali sobre o cume do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'E não suba homem contigo, nem apareça alguém em todo o monte; nem ovelhas nem bois apascentem diante do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'E Moisés entalhou duas tábuas de pedra como as primeiras; e levantou-se pela manhã, e subiu ao monte de Sinai, como lhe mandou o SENHOR, e levou em sua mão as duas tábuas de pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'E o SENHOR desceu na nuvem, e esteve ali com ele, proclamando o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'E passando o SENHOR por diante dele, proclamou: SENHOR, SENHOR, forte, misericordioso, e piedoso; tardio para a ira, e grande em benignidade e verdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Que guarda a misericórdia em milhares, que perdoa a iniquidade, a rebelião, e o pecado, e que de nenhum modo justificará ao malvado; que visita a iniquidade dos pais sobre os filhos e sobre os filhos dos filhos, sobre os de terceira, e quarta gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Então Moisés, apressando-se, baixou a cabeça até o chão e encurvou-se;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'E disse: Se agora, Senhor, achei favor em teus olhos, vá agora o Senhor em meio de nós; porque este é povo de dura cerviz; e perdoa nossa iniquidade e nosso pecado, e possui-nos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'E ele disse: Eis que, eu faço concerto diante de todo o teu povo: farei maravilhas que não foram feitas em toda a terra, nem em nação alguma; e verá todo o povo em meio do qual estás tu, a obra do SENHOR; porque será coisa terrível a que eu farei contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Guarda o que eu te mando hoje; eis que eu expulso de diante de tua presença aos amorreus, e aos cananeus, e aos heteus, e aos perizeus, e aos heveus, e aos jebuseus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Guarda-te que não faças aliança com os moradores da terra de onde hás de entrar, para que não sejam por tropeço em meio de ti:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Mas derrubareis seus altares, e quebrareis suas estátuas, e cortareis seus bosques:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Porque não te hás de inclinar a deus alheio; que o SENHOR, cujo nome é zeloso, Deus zeloso é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Portanto não farás aliança com os moradores daquela terra; pois senão fornicarão após seus deuses, e sacrificarão a seus deuses, e te chamarão, e comerás de seus sacrifícios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Ou, se tomarem de suas filhas para teus filhos, e fornicarem suas filhas após seus deuses, farão também fornicar a teus filhos atrás dos deuses delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Não farás deuses de fundição para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'A festa dos pães ázimos guardarás: sete dias comerás sem levedar, segundo te mandei, no tempo do mês de Abibe; porque no mês de Abibe saíste do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Todo o que abre madre, meu é; e de teu gado todo primeiro de vaca ou de ovelha que for macho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Porém resgatarás com cordeiro o primeiro do asno; e se não o resgatares, lhe cortarás a cabeça. Resgatarás todo primogênito de teus filhos, e não serão vistos vazios diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Seis dias trabalharás, mas no sétimo dia cessarás: cessarás ainda na arada e na colheita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'E te farás a festa das semanas aos princípios da colheita do trigo: e a festa da colheita à volta do ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Três vezes no ano será visto todo homem teu diante do Soberano SENHOR, Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Porque eu lançarei as nações de tua presença, e alargarei teu termo: e ninguém cobiçará tua terra, quando tu subires para ser visto diante do SENHOR teu Deus três vezes no ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Não oferecerás com levedado o sangue de meu sacrifício; nem ficará da noite para a manhã o sacrifício da festa da páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'A primícia dos primeiros frutos de tua terra meterás na casa do SENHOR teu Deus. Não cozerás o cabrito no leite de sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'E o SENHOR disse a Moisés: Escreve tu estas palavras; porque conforme estas palavras fiz a aliança contigo e com Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'E ele esteve ali com o SENHOR quarenta dias e quarenta noites: não comeu pão, nem bebeu água; e escreveu em tábuas as palavras da aliança, os dez dizeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'E aconteceu que, descendo Moisés do monte Sinai com as duas tábuas do testemunho em sua mão, enquanto descia do monte, não sabia ele que a pele de seu rosto resplandecia, depois que havia com ele falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'E olhou Arão e todos os filhos de Israel a Moisés, e eis que a pele de seu rosto era resplandescente; e tiveram medo de chegar-se a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'E chamou-os Moisés; e Arão e todos os príncipes da congregação voltaram-se a ele, e Moisés lhes falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'E depois se chegaram todos os filhos de Israel, aos quais mandou todas as coisas que o SENHOR lhe havia dito no monte de Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'E quando acabou Moisés de falar com eles, pôs um véu sobre seu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'E quando vinha Moisés diante do SENHOR para falar com ele, tirava-se o véu até que saía; e saindo, falava com os filhos de Israel o que lhe era mandado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'E viam os filhos de Israel o rosto de Moisés, que a pele de seu rosto era resplandescente; e voltava Moisés a pôr o véu sobre seu rosto, até que entrava a falar com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'E Moisés fez juntar toda a congregação dos filhos de Israel, e disse-lhes: Estas são as coisas que o SENHOR mandou que façais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Seis dias se fará obra, mas o dia sétimo vos será santo, sábado de repouso ao SENHOR: qualquer um que nele fizer obra morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Não acendereis fogo em todas as vossas moradas no dia do sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'E falou Moisés a toda a congregação dos filhos de Israel, dizendo: Isto é o que o SENHOR mandou, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Tomai dentre vós oferta para o SENHOR: todo generoso de coração a trará ao SENHOR: ouro, prata, bronze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'E azul, e púrpura, e carmesim, e linho fino, e pelo de cabras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'E couros vermelhos de carneiros, e couros finos, e madeira de acácia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'E azeite para a luminária, e especiarias aromáticas para o azeite da unção, e para o incenso aromático;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'E pedras de ônix, e demais pedrarias, para o éfode, e para o peitoral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'E todo sábio de coração dentre vós, virá e fará todas as coisas que o SENHOR mandou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'O tabernáculo, sua tenda, e sua coberta, e seus anéis, e suas tábuas, suas barras, suas colunas, e suas bases;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'A arca, e suas varas, o propiciatório, e o véu da tenda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'A mesa, e suas varas, e todos os seus utensílios, e o pão da proposição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'O candelabro da luminária, e seus utensílios, e suas lâmpadas, e o azeite para a luminária;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'E o altar do incenso, e suas varas, e o azeite da unção, e o incenso aromático, e a cortina da porta, para a entrada do tabernáculo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'O altar do holocausto, e sua grelha de bronze, e suas varas, e todos os seus utensílios, e a pia com sua base;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'As cortinas do átrio, suas colunas, e suas bases, e a cortina da porta do átrio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'As estacas do tabernáculo, e as estacas do átrio, e suas cordas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'As vestimentas dos serviço para ministrar no santuário, as sagradas vestimentas de Arão o sacerdote, e as vestimentas de seus filhos para servir no sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'E saiu toda a congregação dos filhos de Israel de diante de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'E veio todo homem a quem seu coração estimulou, e todo aquele a quem seu espírito lhe deu vontade, e trouxeram oferta ao SENHOR para a obra do tabernáculo do testemunho, e para toda sua confecção, e para as sagradas vestimentas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'E vieram tanto homens como mulheres, todo voluntário de coração, e trouxeram correntes e pendentes, anéis e braceletes, e toda joia de ouro; e qualquer um oferecia oferta de ouro ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Todo homem que se achava com material azul, ou púrpura, ou carmesim, ou linho fino, ou pelo de cabras, ou odres vermelhos de carneiros, ou couros finos, o trazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Qualquer um que oferecia oferta de prata ou de bronze, trazia ao SENHOR a oferta: e todo o que se achava com madeira de acácia, trazia-a para toda a obra do serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Além disso todas as mulheres sábias de coração fiavam de suas mãos, e traziam o que haviam fiado: azul, ou púrpura, ou carmesim, ou linho fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'E todas as mulheres cujo coração as levantou em sabedoria, fiaram pelos de cabras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'E os príncipes trouxeram pedras de ônix, e as pedras dos engastes para o éfode e o peitoral;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'E a especiaria aromática e azeite, para a luminária, e para o azeite da unção, e para o incenso aromático.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Dos filhos de Israel, tanto homens como mulheres, todos os que tiveram coração voluntário para trazer para toda a obra, que o SENHOR havia mandado por meio de Moisés que fizessem, trouxeram oferta voluntária ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'E disse Moisés aos filhos de Israel: Olhai, o SENHOR nomeou a Bezalel filho de Uri, filho de Hur, da tribo de Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'E o encheu de espírito de Deus, em sabedoria, em inteligência, e em conhecimento, e em todo artifício,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Para projetar inventos, para trabalhar em ouro, e em prata, e em bronze,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'E em obra de pedrarias para engastar, e em obra de madeira, para trabalhar em toda invenção engenhosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'E pôs em seu coração o que podia ensinar, tanto ele como Aoliabe filho de Aisamaque, da tribo de Dã:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'E os encheu de sabedoria de coração, para que façam toda obra de artifício, e de invenção, e de recamado em azul, e em púrpura, e em carmesim, e em linho fino, e em tear; para que façam todo trabalho, e inventem todo desenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Fez, pois, Bezalel e Aoliabe, e todo homem sábio de coração, a quem o SENHOR deu sabedoria e inteligência para que soubessem fazer toda a obra do serviço do santuário, todas as coisas que havia mandado o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'E Moisés chamou a Bezalel e a Aoliabe, e a todo homem sábio de coração, em cujo coração havia dado o SENHOR sabedoria, e a todo homem a quem seu coração lhe moveu a chegar-se à obra, para trabalhar nela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'E tomaram de diante de Moisés toda a oferta que os filhos de Israel haviam trazido para a obra do serviço do santuário, a fim de fazê-la. E eles lhe traziam ainda oferta voluntária cada manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Vieram, portanto, todos os mestres que faziam toda a obra do santuário, cada um da obra que fazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'E falaram a Moisés, dizendo: O povo traz muito mais do que é necessário para o trabalho de fazer a obra que o SENHOR mandou que se faça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Então Moisés mandou apregoar pelo acampamento, dizendo: Nenhum homem nem mulher faça mais obra para oferecer para o santuário. E assim foi o povo impedido de oferecer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Pois tinha material abundante para fazer toda a obra, e sobrava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'E todos os sábios de coração entre os que faziam a obra, fizeram o tabernáculo de dez cortinas, de linho torcido, e de material azul, e de púrpura e carmesim; as quais fizeram de obra prima, com querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'O comprimento da uma cortina era de vinte e oito côvados, e a largura de quatro côvados: todas as cortinas tinham uma mesma medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'E juntou as cinco cortinas a uma com a outra: também uniu as outras cinco cortinas uma com aa outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'E fez as laçadas de cor de material azul na orla de uma cortina, na margem, à juntura; e assim fez na orla à extremidade da segunda cortina, na juntura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Cinquenta laçadas fez em um cortina, e outras cinquenta na segunda cortina, na margem, na juntura; umas laçadas em frente das outras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Fez também cinquenta colchetes de ouro, com os quais juntou as cortinas, uma com a outra; e fez-se um tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Fez também cortinas de pelo de cabras para a tenda sobre o tabernáculo, e as fez em número de onze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'O comprimento de uma cortina era de trinta côvados, e a largura de quatro côvados: as onze cortinas tinham uma mesma medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'E juntou as cinco cortinas à parte, e as seis cortinas à parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Fez também cinquenta laçadas na orla da última cortina na juntura, e outras cinquenta laçadas na orla da outra cortina na juntura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Fez também cinquenta colchetes de bronze para juntar a tenda, de modo que fosse uma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'E fez uma coberta para a tenda de couros vermelhos de carneiros, e uma coberta encima de couros finos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Também fez as tábuas para o tabernáculo de madeira de acácia, para estarem na vertical.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'O comprimento de cada tábua de dez côvados, e de côvado e meio a largura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Cada tábua tinha dois encaixes fixos um diante do outro: assim fez todas as tábuas do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Fez, pois, as tábuas para o tabernáculo: vinte tábuas ao lado do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Fez também as quarenta bases de prata debaixo das vinte tábuas: duas bases debaixo de uma tábua para seus dois encaixes, e duas bases debaixo da outra tábua para seus dois encaixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'E para o outro lado do tabernáculo, à parte do norte, fez vinte tábuas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Com suas quarenta bases de prata: duas bases debaixo de uma tábua, e duas bases debaixo da outra tábua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'E para o lado ocidental do tabernáculo fez seis tábuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Para as esquinas do tabernáculo nos dois lados fez duas tábuas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'As quais se juntavam por baixo, e também por cima a uma argola: e assim fez à uma e à outra nos dois cantos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Eram, pois, oito tábuas, e suas bases de prata dezesseis; duas bases debaixo de cada tábua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Fez também as barras de madeira de acácia; cinco para as tábuas do um lado do tabernáculo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'E cinco barras para as tábuas do outro lado do tabernáculo, e cinco barras para as tábuas do lado do tabernáculo à parte ocidental.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'E fez que a barra do meio passasse por meio das tábuas do um extremo ao outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'E cobriu as tábuas de ouro, e fez de ouro os anéis delas por de onde passassem as barras: cobriu também de ouro as barras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Fez assim o véu de azul, e púrpura, e carmesim, e linho torcido, o qual fez com querubins de delicada obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'E para ele fez quatro colunas de madeira de acácia; e cobriu-as de ouro, os capitéis das quais eram de ouro; e fez para elas quatro bases de prata de fundição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Fez também o véu para a porta do tabernáculo, de azul, e púrpura, e carmesim, e linho torcido, obra de bordador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'E suas cinco colunas com seus capitéis: e cobriu as cabeças delas e suas molduras de ouro: mas suas cinco bases as fez de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Fez também Bezalel a arca de madeira de acácia: seu comprimento era de dois côvados e meio, e de côvado e meio sua largura, e sua altura de outro côvado e meio:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'E cobriu-a de ouro puro por de dentro e por de fora, e fez-lhe uma borda de ouro em derredor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Fez-lhe também de fundição quatro anéis de ouro a seus quatro cantos; em um lado dois anéis e no outro lado dois anéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Fez também as varas de madeira de acácia, e cobriu-as de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'E meteu as varas pelos anéis aos lados da arca, para levar a arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Fez também a coberta de ouro puro: seu comprimento de dois côvados e meio, e sua largura de côvado e meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Fez também os dois querubins de ouro, os fez lavrados a martelo, aos duas extremidades do propiciatório:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Um querubim desta parte ao um extremo, e o outro querubim da outra parte ao outro extremo do propiciatório: fez os querubins a suas duas extremidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'E os querubins estendiam suas asas por cima, cobrindo com suas asas o propiciatório: e seus rostos um em frente do outro, até o propiciatório os rostos dos querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Fez também a mesa de madeira de acácia; seu comprimento de dois côvados, e sua largura de um côvado, e de côvado e meio sua altura;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'E cobriu-a de ouro puro, e fez-lhe uma borda de ouro em derredor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Fez-lhe também uma moldura ao redor, da largura de uma mão, à qual moldura fez a borda de ouro ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Fez-lhe também de fundição quatro anéis de ouro, e os pôs aos quatro cantos que correspondiam aos quatro pés dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Diante da moldura estavam os anéis, pelos quais se metessem as varas para levar a mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'E fez as varas de madeira de acácia para levar a mesa, e cobriu-as de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Também fez os utensílios que haviam de estar sobre a mesa, seus pratos, e suas colheres, e suas tigelas e suas bacias com que se havia de fazer libações, de ouro fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Fez também o candelabro de ouro puro, e o fez lavrado a martelo: seu pé e sua haste, seus copos, seus botões e suas flores eram do mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'De seus lados saíam seis braços; três braços de um lado do candelabro, e outros três braços do outro lado do candelabro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Em um braço, três copos forma de amêndoas, um botão e uma flor; e no outro braço três copos forma de amêndoas, um botão e uma flor: e assim nos seis braços que saíam do candelabro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'E no candelabro havia quatro copos forma de amêndoas, seus botões e suas flores:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'E um botão debaixo dos dois braços do mesmo, e outro botão debaixo dos outros dois braços do mesmo, e outro botão debaixo dos outros dois braços do mesmo, conforme os seis braços que saíam dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Seus botões e seus braços eram do mesmo; tudo era uma peça lavrada a martelo, de ouro puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Fez também suas sete lâmpadas, e seus tenazes, e seus apagadores, de ouro puro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'De um talento de ouro puro o fez, com todos os seus utensílios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Fez também o altar do incenso de madeira de acácia: um côvado seu comprimento, e outro côvado sua largura, era quadrado; e sua altura de dois côvados; e suas pontas da mesma peça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'E cobriu-o de ouro puro, sua mesa e suas paredes ao redor, e suas pontas: e fez-lhe uma coroa de ouro ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Fez-lhe também dois anéis de ouro debaixo da coroa nos dois cantos aos dois lados, para passar por eles as varas com que havia de ser conduzido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'E fez as varas de madeira de acácia, e cobriu-as de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Fez também o azeite santo da unção, e o fino incenso aromático, de obra de perfumista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Igualmente fez o altar do holocausto de madeira de acácia: seu comprimento de cinco côvados, e sua largura de outros cinco côvados, quadrado, e de três côvados de altura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'E fez-lhe suas pontas a seus quatro cantos, os quais eram da mesma peça, e cobriu-o de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Fez também todos os utensílios do altar: caldeirões, e tenazes, e bacias, e garfos, e pás: todos os seus utensílios fez de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'E fez para o altar a grelha de bronze, de feitura de rede, que pôs em sua borda por debaixo até o meio do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Fez também quatro anéis de fundição aos quatro extremos da grelha de bronze, para meter as varas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'E fez as varas de madeira de acácia, e cobriu-as de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'E meteu as varas pelos anéis aos lados do altar, para levá-lo com elas: oco o fez, de tábuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Também fez a pia de bronze, com sua base de bronze, dos espelhos das que vigiavam à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Fez também o átrio; à parte sul as cortinas do átrio eram de cem côvados, de linho torcido:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Suas colunas vinte, com suas vinte bases de bronze: os capitéis das colunas e suas molduras, de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'E à parte do norte cortinas de cem côvados: suas colunas vinte, com suas vinte bases de bronze; os capitéis das colunas e suas molduras, de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'À parte do ocidente cortinas de cinquenta côvados: suas colunas dez, e suas dez bases; os capitéis das colunas e suas molduras, de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'E à parte oriental, ao levante, cortinas de cinquenta côvados:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Ao um lado cortinas de quinze côvados, suas três colunas, e suas três bases;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Ao outro lado, de uma parte e da outra da porta do átrio, cortinas de a quinze côvados, suas três colunas, e suas três bases.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Todas as cortinas do átrio ao redor eram de linho torcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'E as bases das colunas eram de bronze; os capitéis das colunas e suas molduras, de prata; também as cobertas das cabeças delas, de prata: e todas as colunas do átrio tinham molduras de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'E a cortina da porta do átrio foi de obra de bordado, de azul, e púrpura, e carmesim, e linho torcido: o comprimento de vinte côvados, e a altura na largura de cinco côvados, conforme as cortinas do átrio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'E suas colunas foram quatro com suas quatro bases de bronze: e seus capitéis de prata; e as cobertas dos capitéis delas e suas molduras, de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'E todas as estacas do tabernáculo e do átrio ao redor foram de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Estas são as contas do tabernáculo, do tabernáculo do testemunho, o que foi contado de ordem de Moisés por meio de Itamar, filho de Arão sacerdote, para o ministério dos levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'E Bezalel, filho de Uri, filho de Hur, da tribo de Judá, fez todas as coisas que o SENHOR mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'E com ele estava Aoliabe, filho de Aisamaque, da tribo de Dã, artífice, e desenhador, e bordador em material azul, e púrpura, e carmesim, e linho fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Todo o ouro gasto na obra, em toda a obra do santuário, o qual foi ouro de oferta, foi vinte e nove talentos, e setecentos e trinta siclos, segundo o siclo do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'E a prata dos contados da congregação foi cem talentos, e mil setecentos setenta e cinco siclos, segundo o siclo do santuário:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Meio por cabeça, meio siclo, segundo o siclo do santuário, a todos os que passaram por contagem de idade de vinte anos e acima, que foram seiscentos três mil quinhentos cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Houve também cem talentos de prata para fazer de fundição as bases do santuário e as bases do véu: em cem bases cem talentos, a talento por base.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'E dos mil setecentos setenta e cinco siclos fez os capitéis das colunas, e cobriu os capitéis delas, e as cingiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'E o bronze da oferta foi setenta talentos, e dois mil quatrocentos siclos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Do qual fez as bases da porta do tabernáculo do testemunho, e o altar de bronze, e sua grelha de bronze, e todos os utensílios do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'E as bases do átrio ao redor, e as bases da porta do átrio, e todas as estacas do tabernáculo, e todas as estacas do átrio ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'E do material azul, e púrpura, e carmesim, fizeram as vestimentas do ministério para ministrar no santuário, e também fizeram as vestiduras sagradas para Arão; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Fez também o éfode de ouro, de azul e púrpura e carmesim, e linho torcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'E estenderam as placas de ouro, e cortaram cachos para tecê-los entre o azul, e entre a púrpura, e entre o carmesim, e entre o linho, com delicada obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Fizeram-lhe as ombreiras que se juntassem; e uniam-se em seus dois lados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'E o cinto do éfode que estava sobre ele, era do mesmo, conforme sua obra; de ouro, material azul, e púrpura, e carmesim, e linho torcido; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'E lavraram as pedras de ônix cercadas de engastes de ouro, gravada de gravura de selo com os nomes dos filhos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'E as pôs sobre as ombreiras do éfode, por pedras de memória aos filhos de Israel; como o SENHOR o havia a Moisés mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Fez também o peitoral de primorosa obra, como a obra do éfode, de ouro, azul, e púrpura, e carmesim, e linho torcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Era quadrado; dobrado fizeram o peitoral: sua comprimento era de um palmo, e de um palmo sua largura, dobrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'E engastaram nele quatro ordens de pedras. A primeira ordem era um sárdio, um topázio, e um carbúnculo: este a primeira ordem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'A segunda ordem, uma esmeralda, uma safira, e um diamante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'A terceira ordem, um jacinto, uma ágata, e uma ametista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'E a quarta ordem, um berilo, um ônix, e um jaspe: cercadas e encaixadas em seus engastes de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'As quais pedras eram conforme os nomes dos filhos de Israel, doze segundo os nomes deles; como gravuras de selo, cada uma com seu nome segundo as doze tribos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Fizeram também sobre o peitoral as correntes pequenas de feitura de trança, de ouro puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Fizeram também os dois engastes e os dois anéis, de ouro; os quais dois anéis de ouro puseram nas duas extremidades do peitoral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'E puseram as duas tranças de ouro naqueles dois anéis aos extremos do peitoral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'E fixaram as duas extremidades das duas tranças nos dois engastes, que puseram sobre as ombreiras do éfode, na parte dianteira dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'E fizeram dois anéis de ouro, que puseram nas duas extremidades do peitoral, em sua orla, à parte baixa do éfode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Fizeram também dois anéis de ouro, os quais puseram nas duas ombreiras do éfode, abaixo na parte dianteira, diante de sua juntura, sobre o cinto do éfode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'E ataram o peitoral de seus anéis aos anéis do éfode com um cordão de material azul, para que estivesse sobre o cinto do mesmo éfode, e não se separasse o peitoral do éfode; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Fez também o manto do éfode de obra de tecelão, todo de azul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Com sua abertura em meio dele, como a abertura de um colarinho, com uma borda em derredor da abertura, para que não se rompesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'E fizeram nas orlas do manto as romãs de azul, e púrpura, e carmesim, e linho torcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Fizeram também os sinos de ouro puro, os quais sinos puseram entre as romãs pelas orlas do manto ao redor entre as romãs:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Um sino e uma romã, um sino e uma romã ao redor, nas orlas do manto, para ministrar; como o SENHOR o mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Igualmente fizeram as túnicas de linho fino de obra de tecelão, para Arão e para seus filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Também a mitra de linho fino, e os adornos das tiaras de linho fino, e os calções de linho, de linho torcido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Também o cinto de linho torcido, e de material azul, e púrpura, e carmesim, de obra de bordador; como o SENHOR o mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Fizeram também a prancha da coroa santa de ouro puro, e escreveram nela de gravura de selo, o rótulo, SANTIDADE AO SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'E puseram nela um cordão de azul, para colocá-la em alto sobre a mitra; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'E foi acabada toda a obra do tabernáculo, do tabernáculo do testemunho: e fizeram os filhos de Israel como o SENHOR o havia mandado a Moisés: assim o fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'E trouxeram o tabernáculo a Moisés, o tabernáculo e todos os seus utensílios; seus colchetes, suas tábuas, suas barras, e suas colunas, e suas bases;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'E a coberta de peles vermelhas de carneiros, e a coberta de peles finas, e o véu da cortina;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'A arca do testemunho, e suas varas, e o propiciatório;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'A mesa, todos os seus utensílios, e o pão da proposição;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'O candelabro limpo, suas lâmpadas, as lâmpadas que deviam manter-se em ordem, e todos os seus utensílios, e o azeite para a luminária;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'E o altar de ouro, e o azeite da unção, e o incenso aromático, e a cortina para a porta do tabernáculo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'O altar de bronze, com sua grelha de bronze, suas varas, e todos os seus utensílios; e a pia, e sua base;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'As cortinas do átrio, e suas colunas, e suas bases, e a cortina para a porta do átrio, e suas cordas, e suas estacas, e todos os vasos do serviço do tabernáculo, do tabernáculo do testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'As vestimentas do serviço para ministrar no santuário, as sagradas vestiduras para Arão o sacerdote, e as vestiduras de seus filhos, para ministrar no sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Em conformidade a todas as coisas que o SENHOR havia mandado a Moisés, assim fizeram os filhos de Israel toda a obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'E viu Moisés toda a obra, e eis que a fizeram como o SENHOR havia mandado; e abençoou-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'No primeiro dia do mês primeiro farás levantar o tabernáculo, o tabernáculo do testemunho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'E porás nele a arca do testemunho, e a cobrirás com o véu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'E meterás a mesa, e a porás em ordem: meterás também o candelabro e acenderás suas lâmpadas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'E porás o altar de ouro para o incenso diante da arca do testemunho, e porás a cortina diante da porta do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Depois porás o altar do holocausto diante da porta do tabernáculo, do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Logo porás a pia entre o tabernáculo do testemunho e o altar; e porás água nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Finalmente porás o átrio em derredor, e a cortina da porta do átrio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'E tomarás o azeite da unção e ungirás o tabernáculo, e tudo o que está nele; e lhe santificarás com todos os seus utensílios, e será santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ungirás também o altar do holocausto e todos os seus utensílios: e santificarás o altar, e será um altar santíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Também ungirás a pia e sua base, e a santificarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'E farás chegar a Arão e a seus filhos à porta do tabernáculo do testemunho, e os lavarás com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'E farás vestir a Arão as vestimentas sagradas, e o ungirás, e o consagrarás, para que seja meu sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Depois farás chegar seus filhos, e lhes vestirás as túnicas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'E os ungirás como ungiste a seu pai, e serão meus sacerdotes: e será que sua unção lhes servirá por sacerdócio perpétuo por suas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'E Moisés fez conforme tudo o que o SENHOR lhe mandou; assim o fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'E assim no dia primeiro do primeiro mês, no segundo ano, o tabernáculo foi erigido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'E Moisés fez levantar o tabernáculo, e assentou suas bases, e colocou suas tábuas, e pôs suas barras, e fez erguer suas colunas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'E estendeu a tenda sobre o tabernáculo, e pôs a cobertura encima do mesmo; como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'E tomou e pôs o testemunho dentro da arca, e colocou as varas na arca, e encima o propiciatório sobre a arca:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'E meteu a arca no tabernáculo, e pôs o véu da tenda, e cobriu a arca do testemunho; como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'E pôs a mesa no tabernáculo do testemunho, ao lado norte da cortina, fora do véu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'E sobre ela pôs por ordem os pães diante do SENHOR, como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'E pôs o candelabro no tabernáculo do testemunho, em frente da mesa, ao lado sul da cortina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'E acendeu as lâmpadas diante do SENHOR; como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Pôs também o altar de ouro no tabernáculo do testemunho, diante do véu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'E acendeu sobre ele o incenso aromático; como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Pôs também a cortina da porta do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'E colocou o altar do holocausto à porta do tabernáculo, do tabernáculo do testemunho; e ofereceu sobre ele holocausto e presente; como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'E pôs a pia entre o tabernáculo do testemunho e o altar; e pôs nela água para lavar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'E Moisés e Arão e seus filhos lavavam nela suas mãos e seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Quando entravam no tabernáculo do testemunho, e quando se traziam ao altar, se lavavam; como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Finalmente erigiu o átrio em derredor do tabernáculo e do altar, e pôs a cortina da porta do átrio. E assim acabou Moisés a obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Então uma nuvem cobriu o tabernáculo do testemunho, e a glória do SENHOR encheu o tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'E não podia Moisés entrar no tabernáculo do testemunho, porque a nuvem estava sobre ele, e a glória do SENHOR o tinha enchido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'E quando a nuvem se erguia do tabernáculo, os filhos de Israel se moviam em todas suas jornadas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Porém se a nuvem não se erguia, não se partiam até o dia em que ela se erguia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Porque a nuvem do SENHOR estava de dia sobre o tabernáculo, e o fogo estava de noite nele, à vista de toda a casa de Israel, em todas as suas jornadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'E chamou o SENHOR a Moisés, e falou com ele desde o tabernáculo do testemunho, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando algum dentre vós oferecer oferta ao SENHOR, de gado vacum ou ovelha fareis vossa oferta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Se sua oferta for holocausto de vacas, macho sem mácula o oferecerá: de sua vontade o oferecerá à porta do tabernáculo do testemunho diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'E porá sua mão sobre a cabeça do holocausto; e ele o aceitará para expiar-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Então degolará o bezerro na presença do SENHOR; e os sacerdotes, filhos de Arão, oferecerão o sangue, e o espargirão ao redor sobre o altar, o qual está à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'E tirará a pele do holocausto, e o dividirá em suas peças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'E os filhos de Arão sacerdote porão fogo sobre o altar, e porão a lenha sobre o fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Logo os sacerdotes, filhos de Arão, acomodarão as peças, a cabeça e o redenho, sobre a lenha que está sobre o fogo, que haverá encima do altar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'E lavará com água seus intestinos e suas pernas: e o sacerdote fará arder tudo sobre o altar: holocausto é, oferta acesa de cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'E se sua oferta para holocausto for de ovelhas, dos cordeiros, ou das cabras, macho sem defeito o oferecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'E há de degolá-lo ao lado norte do altar diante do SENHOR: e os sacerdotes, filhos de Arão, espargirão seu sangue sobre o altar ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'E o dividirá em suas peças, com sua cabeça e seu redenho; e o sacerdote as acomodará sobre a lenha que está sobre o fogo, que haverá encima do altar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'E lavará suas entranhas e suas pernas com água; e o sacerdote o oferecerá tudo, e o fará arder sobre o altar; holocausto é, oferta acesa de cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'E se o holocausto se houver de oferecer ao SENHOR de aves, apresentará sua oferta de rolinhas, ou de pombinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'E o sacerdote a oferecerá sobre o altar, e há de tirar-lhe a cabeça, e fará que arda no altar; e seu sangue será espremido sobre a parede do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'E lhe há de tirar o papo e as penas, o qual lançará junto ao altar, até o oriente, no lugar das cinzas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'E a fenderá por suas asas, mas não a dividirá em dois: e o sacerdote a fará arder sobre o altar, sobre a lenha que estará no fogo; holocausto é, oferta acesa de cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'E quando alguma pessoa oferecer oferta de grãos de presente ao SENHOR, sua oferta será flor de farinha, sobre a qual lançará azeite, e porá sobre ela incenso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'E a trará aos sacerdotes, filhos de Arão; e disso tomará o sacerdote seu punho cheio de sua flor de farinha e de seu azeite, com todo seu incenso, e o fará arder sobre o altar: oferta acesa para memorial, de cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'E a sobra da oferta será de Arão e de seus filhos: é coisa santíssima das ofertas que se queimam ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'E quando ofereceres oferta de presente cozida em forno, será de tortas de flor de farinha sem levedura, amassadas com azeite, e massas sem levedura untadas com azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Mas se teu presente for oferta de alimentos de panelas, será de flor de farinha sem levedura, amassada com azeite,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'A qual partirás em peças, e expulsarás sobre ela azeite: é presente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'E se teu presente for oferta cozida em frigideira, ela será feita de flor de farinha com azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'E trarás ao SENHOR a oferta que se fará destas coisas, e a apresentarás ao sacerdote, o qual a chegará ao altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'E tomará o sacerdote daquele presente, em memória do mesmo, e o fará arder sobre o altar; oferta acesa, de suave cheiro ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'E o restante da oferta será de Arão e de seus filhos; é coisa santíssima das ofertas que se queimam ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Nenhum presente que oferecerdes ao SENHOR, será com levedura: porque de nenhuma coisa levedada, nem de nenhum mel, se há de queimar oferta ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Na oferta das primícias as oferecereis ao SENHOR: mas não subirão sobre o altar em cheiro suave.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'E temperarás toda oferta de teu presente com sal; e não farás que falte jamais de teu presente o sal da aliança de teu Deus: em toda oferta tua oferecerás sal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'E se ofereceres ao SENHOR presente de primícias, tostarás ao fogo as espigas verdes, e o grão esmigalhado oferecerás por oferta de tuas primícias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'E porás sobre ela azeite, e porás sobre ela incenso: é presente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'E o sacerdote fará arder, em memória do presente, parte de seu grão esmigalhado, e de seu azeite com todo seu incenso; é oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'E se sua oferta for sacrifício pacífico, se houver de oferecê-lo de gado vacum, seja macho ou fêmea, sem defeito o oferecerá diante do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'E porá sua mão sobre a cabeça de sua oferta, e a degolará à porta do tabernáculo do testemunho; e os sacerdotes, filhos de Arão, espargirão seu sangue sobre o altar em derredor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Logo oferecerá do sacrifício pacífico, por oferta acesa ao SENHOR, a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'E os dois rins, e a gordura que está sobre eles, e sobre os lombos, e com os rins tirará o redenho que está sobre o fígado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'E os filhos de Arão farão arder isto no altar, sobre o holocausto que estará sobre a lenha que haverá encima do fogo; é oferta de cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Mas se de ovelhas for sua oferta para sacrifício pacífico ao SENHOR, seja macho ou fêmea, oferecê-la-á sem mácula.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Se oferecer cordeiro por sua oferta, há de oferecê-lo diante do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'E porá sua mão sobre a cabeça de sua oferta, e depois a degolará diante do tabernáculo do testemunho; e os filhos de Arão espargirão seu sangue sobre o altar em derredor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'E do sacrifício pacífico oferecerá por oferta acesa ao SENHOR, sua gordura, e a cauda inteira, a qual tirará a raiz do espinhaço, e a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Também os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos, e com os rins tirará o redenho de sobre o fígado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'E o sacerdote fará arder isto sobre o altar; comida de oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'E se for cabra sua oferta oferecê-la-á diante do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'E porá sua mão sobre a cabeça dela, e a degolará diante do tabernáculo do testemunho; e os filhos de Arão espargirão seu sangue sobre o altar em derredor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Depois oferecerá dela sua oferta acesa ao SENHOR; a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'E os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos, e com os rins tirará o redenho de sobre o fígado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'E o sacerdote fará arder isto sobre o altar; é comida de oferta que se queima em cheiro suave ao SENHOR: a gordura tudo é do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Estatuto perpétuo por vossas gerações; em todas as vossas moradas, nenhuma gordura nem nenhum sangue comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Fala aos filhos de Israel, dizendo: Quando alguma pessoa pecar por acidente em algum dos mandamentos do SENHOR sobre coisas que não se devem fazer, e agir contra algum deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Se sacerdote ungido pecar segundo o pecado do povo, oferecerá ao SENHOR, por seu pecado que houver cometido, um bezerro sem mácula para expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'E trará o bezerro à porta do tabernáculo do testemunho diante do SENHOR, e porá sua mão sobre a cabeça do bezerro, e o degolará diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'E o sacerdote ungido tomará do sangue do bezerro, e a trará ao tabernáculo do testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'E molhará o sacerdote seu dedo no sangue, e espargirá daquele sangue sete vezes diante do SENHOR, até o véu do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'E porá o sacerdote do sangue sobre as pontas do altar do incenso aromático, que está no tabernáculo do testemunho diante do SENHOR: e lançará todo o sangue do bezerro ao pé do altar do holocausto, que está à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'E tomará do bezerro para a expiação toda a sua gordura, a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'E os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos, e com os rins tirará o redenho de sobre o fígado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Da maneira que se tira do boi do sacrifício pacífico: e o sacerdote o fará arder sobre o altar do holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'E o couro do bezerro, e toda sua carne, com sua cabeça, e suas pernas, e seus intestinos, e seu excremento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Em fim, todo o bezerro tirará fora do acampamento, a um lugar limpo, onde se lançam as cinzas, e o queimará ao fogo sobre a lenha: onde se lançam as cinzas será queimado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'E se toda a congregação de Israel houver errado, e o negócio estiver oculto aos olhos do povo, e houverem feito algo contra algum dos mandamentos do SENHOR em coisas que não se devem fazer, e forem culpados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Logo que for entendido o pecado sobre que transgrediram, a congregação oferecerá um bezerro por expiação, e o trarão diante do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'E os anciãos da congregação porão suas mãos sobre a cabeça do bezerro diante do SENHOR; e em presença do SENHOR degolarão aquele bezerro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'E o sacerdote ungido meterá do sangue do bezerro no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'E molhará o sacerdote seu dedo no mesmo sangue, e espargirá sete vezes diante do SENHOR até o véu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'E daquele sangue porá sobre as pontas do altar que está diante do SENHOR no tabernáculo do testemunho, e derramará todo o sangue ao pé do altar do holocausto, que está à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'E lhe tirará toda a gordura, e a fará arder sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'E fará daquele bezerro como fez com o bezerro da expiação; o mesmo fará dele: assim fará o sacerdote expiação por eles, e obterão perdão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'E tirará o bezerro fora do acampamento, e o queimará como queimou o primeiro bezerro; expiação da congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'E quando pecar o príncipe, e fizer por acidente algo contra algum de todos os mandamentos do SENHOR seu Deus, sobre coisas que não se devem fazer, e pecar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Logo que lhe for conhecido seu pecado em que transgrediu, apresentará por sua oferta um bode macho sem defeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'E porá sua mão sobre a cabeça do bode macho, e o degolará no lugar de onde se degola o holocausto diante do SENHOR; é expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'E tomará o sacerdote com seu dedo do sangue da expiação, e porá sobre as pontas do altar do holocausto, e derramará o sangue ao pé do altar do holocausto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'E queimará toda a sua gordura sobre o altar, como a gordura do sacrifício pacífico: assim fará o sacerdote por ele a expiação de seu pecado, e terá perdão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'E se alguma pessoa comum do povo pecar por acidente, fazendo algo contra algum dos mandamentos do SENHOR em coisas que não se devem fazer, e transgredir;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Logo que lhe for conhecido seu pecado que cometeu, trará por sua oferta uma fêmea das cabras, uma cabra sem defeito, por seu pecado que haverá cometido:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'E porá sua mão sobre a cabeça da expiação, e a degolará no lugar do holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Logo tomará o sacerdote em seu dedo de seu sangue, e porá sobre as pontas do altar do holocausto, e derramará todo o seu sangue ao pé do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'E lhe tirará toda a sua gordura, da maneira que foi tirada a gordura do sacrifício pacífico; e o sacerdote a fará arder sobre o altar em cheiro suave ao SENHOR: assim fará o sacerdote expiação por ele, e será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'E se trouxer cordeiro para sua oferta pelo pecado, fêmea sem defeito trará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'E porá sua mão sobre a cabeça da expiação, e a degolará por expiação no lugar onde se degola o holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Depois tomará o sacerdote com seu dedo do sangue da expiação, e porá sobre as pontas do altar do holocausto; e derramará todo o sangue ao pé do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'E lhe tirará toda a sua gordura, como foi tirada a gordura do sacrifício pacífico, e a fará o sacerdote arder no altar sobre a oferta acesa ao SENHOR: e lhe fará o sacerdote expiação de seu pecado que haverá cometido, e será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'E quando alguma pessoa pecar, que houver ouvido a voz do que jurou, e ele for testemunha que viu, ou soube, se não o denunciar, ele levará seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Também a pessoa que houver tocado em qualquer coisa imunda, seja corpo morto de animal selvagem impuro, ou corpo morto de animal doméstico impuro, ou corpo morto de réptil impuro, ainda que não o soubesse, será impura e haverá transgredido:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Ou se tocar a homem impuro em qualquer impureza sua de que é impuro, e não o deixar de ver; se depois chega a sabê-lo, será culpável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Também a pessoa que jurar precipitadamente com seus lábios fazer mal ou bem, em quaisquer coisas que o homem profere com juramento, e ele não o conhecer; se depois o entende, será culpado em uma destas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'E será que quando pecar em alguma destas coisas, confessará aquilo em que pecou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'E para sua expiação trará ao SENHOR por seu pecado que cometeu, uma fêmea dos rebanhos, uma cordeira ou uma cabra como oferta de expiação; e o sacerdote fará expiação por ele de seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'E se não lhe alcançar para um cordeiro, trará em expiação por seu pecado que cometeu, duas rolinhas ou dois pombinhos ao SENHOR; um para expiação, e o outro para holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'E há de trazê-los ao sacerdote, o qual oferecerá primeiro o que é para expiação, e desunirá sua cabeça de seu pescoço, mas não a separará por completo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'E espargirá do sangue da expiação sobre a parede do altar; e o que sobrar do sangue o espremerá ao pé do altar; é expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'E do outro fará holocausto conforme o rito; e fará por ele o sacerdote expiação de seu pecado que cometeu, e será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Mas se sua possibilidade não alcançar para duas rolinhas, ou dois pombinhos, o que pecou trará por sua oferta a décima parte de um efa de flor de farinha por expiação. Não porá sobre ela azeite, nem sobre ela porá incenso, porque é expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Ele a trará, pois, ao sacerdote, e o sacerdote tomará dela seu punho cheio, em memória sua, e a fará arder no altar sobre as ofertas acendidas ao SENHOR: é expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'E fará o sacerdote expiação por ele de seu pecado que cometeu em alguma destas coisas, e será perdoado; e o excedente será do sacerdote, como o presente de comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Falou mais o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Quando alguma pessoa cometer falta, e pecar por acidente nas coisas santificadas ao SENHOR, trará sua expiação ao SENHOR, um carneiro sem mácula dos rebanhos, conforme tua avaliação, em siclos de prata do siclo do santuário, em oferta pelo pecado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'E pagará aquilo das coisas santas em que houver pecado, e acrescentará a ele o quinto, e o dará ao sacerdote: e o sacerdote fará expiação por ele com o carneiro do sacrifício pelo pecado, e será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Finalmente, se uma pessoa pecar, ou fizer alguma de todas aquelas coisas que por mandamento do SENHOR não se devem fazer, ainda sem fazê-lo de propósito, é culpável, e levará seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Trará, pois, ao sacerdote por expiação, segundo tu o estimes, um carneiro sem mácula dos rebanhos: e o sacerdote fará expiação por ele de seu erro que cometeu por ignorância, e será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'É infração, e certamente transgrediu contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Quando uma pessoa pecar, e fizer transgressão contra o SENHOR, e negar a seu próximo o depositado ou deixado em sua mão, ou roubar, ou extorquir a seu próximo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Ou seja que achando o perdido, depois o negar, e jurar em falso, em alguma de todas aquelas coisas em que costuma pecar o homem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Então será que, posto que haverá pecado e ofendido, restituirá aquilo que roubou, ou pelo dano da extorsão, ou o depósito que se lhe depositou, ou o perdido que achou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Ou tudo aquilo sobre que houver jurado falsamente; o restituirá, pois, por inteiro, e acrescentará a ele a quinta parte, que há de pagar a aquele a quem pertence no dia de sua expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'E por sua expiação trará ao SENHOR um carneiro sem mácula dos rebanhos, conforme tua avaliação, ao sacerdote para a expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'E o sacerdote fará expiação por ele diante do SENHOR, e obterá perdão de qualquer de todas as coisas em que costuma ofender.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Falou ainda o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Manda a Arão e a seus filhos dizendo: Esta é a lei do holocausto: (é holocausto, porque se queima sobre o altar toda a noite até a manhã, e o fogo do altar arderá nele:)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'O sacerdote se porá sua vestimenta de linho, e se vestirá calções de linho sobre sua carne; e quando o fogo houver consumido o holocausto, apartará ele as cinzas de sobre o altar, e as porá junto ao altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Depois se desnudará de suas vestimentas, e se porá outras vestiduras, e tirará as cinzas fora do acampamento ao lugar limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'E o fogo acendido sobre o altar não há de apagar-se, mas sim que o sacerdote porá nele lenha cada manhã, e acomodará sobre ele o holocausto, e queimará sobre ele a gordura pacífica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'O fogo há de arder continuamente no altar; não se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'E esta é a lei da oferta: Hão de oferecê-lo os filhos de Arão diante do SENHOR, diante do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'E tomará dele um punhado da flor de farinha da oferta, e de seu azeite, e todo o incenso que está sobre o presente, e o fará arder sobre o altar por memória, em cheiro suavíssimo ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'E o excedente dela o comerão Arão e seus filhos: sem levedura se comerá no lugar santo; no átrio do tabernáculo do testemunho o comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Não se cozerá com levedura: dei-o a eles por sua porção de minhas ofertas acendidas; é coisa santíssima, como a expiação pelo pecado, e como a expiação pela culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Todos os homens dos filhos de Arão comerão dela. Estatuto perpétuo será para vossas gerações acerca das ofertas acendidas do SENHOR: toda coisa que tocar nelas será santificada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Esta é a oferta de Arão e de seus filhos, que oferecerão ao SENHOR o dia que serão ungidos: a décima parte de um efa de flor de farinha, presente perpétuo, a metade à manhã e a metade à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Em panela se preparará com azeite; bem misturada a trarás, e os pedaços cozidos da oferta oferecerás ao SENHOR em cheiro suave.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'E o sacerdote que em lugar de Arão for ungido dentre seus filhos, fará a oferta; estatuto perpétuo do SENHOR: toda ela será queimada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'E toda a oferta de cereais de sacerdote será inteiramente queimado; não se comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Fala a Arão e a seus filhos, dizendo: Esta é a lei da expiação: no lugar de onde será degolado o holocausto, será degolada a expiação pelo pecado diante do SENHOR: é coisa santíssima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'O sacerdote que a oferecer por expiação, a comerá: no lugar santo será comida, no átrio do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Tudo o que em sua carne tocar, será santificado; e se cair de seu sangue sobre a roupa, lavarás aquilo sobre que cair, no lugar santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'E a vasilha de barro em que for cozida, será quebrada: e se for cozida em vasilha de metal, será esfregada e lavada com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Todo homem dentre os sacerdotes a comerá: é coisa santíssima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Mas não se comerá de expiação alguma, de cujo sangue se meter no tabernáculo do testemunho para reconciliar no santuário: ao fogo será queimada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Assim esta é a lei da expiação da culpa: é coisa muito santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'No lugar onde degolarem o holocausto, degolarão o sacrifício pela culpa; e espargirá seu sangue em derredor sobre o altar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'E dela oferecerá toda a sua gordura, a cauda, e a gordura que cobre os intestinos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'E os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos; e com os rins tirará o redenho de sobre o fígado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'E o sacerdote o fará arder sobre o altar; oferta acesa ao SENHOR: é expiação da culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Todo homem dentre os sacerdotes a comerá: será comida no lugar santo: é coisa muito santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Como a expiação pelo pecado, assim é a expiação da culpa: uma mesma lei terão: será do sacerdote que haverá feito a reconciliação com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'E o sacerdote que oferecer holocausto de alguém, o couro do holocausto que oferecer, será para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Também toda oferta de cereais que se cozer em forno, e tudo o que for preparado em panela, ou em frigideira, será do sacerdote que o oferecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'E toda oferta de cereais amassada com azeite, e seca, será de todos os filhos de Arão, tanto ao um como ao outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'E esta é a lei do sacrifício pacífico, que se oferecerá ao SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Se se oferecer em ação de graças, oferecerá por sacrifício de ação de graças tortas sem levedura amassadas com azeite, e massas sem levedura untadas com azeite, e flor de farinha frita em tortas amassadas com azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Com tortas de pão levedado oferecerá sua oferta no sacrifício de ação de graças de suas pazes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'E de toda a oferta apresentará uma parte para oferta elevada ao SENHOR, e será do sacerdote que espargir o sangue das ofertas pacíficas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'E a carne do sacrifício de suas ofertas pacíficas em ação de graças, se comerá no dia que for oferecida: não deixarão dela nada para outro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Mas se o sacrifício de sua oferta for voto, ou voluntário, no dia que oferecer seu sacrifício será comido; e o que dele restar, será comido no dia seguinte:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'E o que restar para o terceiro dia da carne do sacrifício, será queimado no fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'E se se comer da carne do sacrifício de suas pazes no terceiro dia, o que o oferecer não será aceito, nem lhe será imputado; abominação será, e a pessoa que dele comer levará seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'E a carne que tocar a alguma coisa impura, não se comerá; ao fogo será queimada; mas qualquer limpo comerá desta carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'E a pessoa que comer a carne do sacrifício pacífico, o qual é do SENHOR, estando impura, aquela pessoa será eliminada de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Além disso, a pessoa que tocar alguma coisa impura, em impureza de homem, ou em animal impuro, ou em qualquer abominação impura, e comer a carne do sacrifício pacífico, o qual é do SENHOR, aquela pessoa será eliminada de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Falou ainda o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Fala aos filhos de Israel, dizendo: Nenhuma gordura de boi, nem de cordeiro, nem de cabra, comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'A gordura de animal morto naturalmente, e a gordura do que foi arrebatado de feras, se preparará para qualquer outro uso, mas não o comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Porque qualquer um que comer gordura de animal, do qual se oferece ao SENHOR oferta acesa, a pessoa que o comer, será cortada de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Além disso, nenhum sangue comereis em todas as vossas habitações, tanto de aves como de animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Qualquer um pessoa que comer algum sangue, a tal pessoa será eliminada de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Falou mais o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Fala aos filhos de Israel, dizendo: O que oferecer sacrifício de suas pazes ao SENHOR, trará sua oferta do sacrifício de suas pazes ao SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Suas mãos trarão as ofertas que se hão de queimar ao SENHOR: trará a gordura com o peito: o peito para que este seja movido, como sacrifício movido diante do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'E a gordura a fará arder o sacerdote no altar, mas o peito será de Arão e de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'E dareis ao sacerdote para ser elevada em oferta, a coxa direita dos sacrifícios de vossas pazes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'O que dos filhos de Arão oferecer o sangue das ofertas pacíficas, e a gordura, dele será em porção a coxa direita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Porque tomei dos filhos de Israel, dos sacrifícios de suas ofertas pacíficas, o peito que é movido, e a coxa elevada em oferta, e o dei a Arão o sacerdote e a seus filhos, por estatuto perpétuo dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Esta é pela unção de Arão e a unção de seus filhos, a parte deles nas ofertas acendidas ao SENHOR, desde o dia que ele os apresentou para serem sacerdotes do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'O qual mandou o SENHOR que lhes dessem, desde o dia que ele os ungiu dentre os filhos de Israel, por estatuto perpétuo em suas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Esta é a lei do holocausto, da oferta, da expiação pelo pecado, e da culpa, e das consagrações, e do sacrifício pacífico:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'A qual intimou o SENHOR a Moisés, no monte Sinai, no dia que mandou aos filhos de Israel que oferecessem suas ofertas ao SENHOR no deserto de Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Toma a Arão e a seus filhos com ele, e as vestimentas, e o azeite da unção, e o bezerro da expiação, e os dois carneiros, e o cesto dos pães ázimos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'E reúne toda a congregação à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Fez, pois, Moisés como o SENHOR lhe mandou, e juntou-se a congregação à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'E disse Moisés à congregação: Isto é o que o SENHOR mandou fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Então Moisés fez chegar a Arão e a seus filhos, e lavou-os com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'E pôs sobre ele a túnica, e cingiu-o com o cinto; vestiu-lhe depois o manto, e pôs sobre ele o éfode, e cingiu-o com o cinto do éfode, e ajustou-o com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Pôs-lhe logo encima o peitoral, e nele pôs o Urim e Tumim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Depois pôs a mitra sobre sua cabeça; e sobre a mitra em sua frente dianteira pôs a placa de ouro, a coroa santa; como o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'E tomou Moisés o azeite da unção, e ungiu o tabernáculo, e todas as coisas que estavam nele, e santificou-as.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'E espargiu dele sobre o altar sete vezes, e ungiu o altar e todos os seus utensílios, e a pia e sua base, para santificá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'E derramou do azeite da unção sobre a cabeça de Arão, e ungiu-o para santificá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Depois Moisés fez chegar os filhos de Arão, e vestiu-lhes as túnicas, e cingiu-os com cintos, e ajustou-lhes as tiaras), como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Fez logo chegar o bezerro da expiação, e Arão e seus filhos puseram suas mãos sobre a cabeça do bezerro da expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'E degolou-o; e Moisés tomou o sangue, e pôs com seu dedo sobre as pontas do altar ao redor, e purificou o altar; e lançou o resto do sangue ao pé do altar, e santificou-o para fazer reconciliação sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Depois tomou toda a gordura que estava sobre os intestinos, e o redenho do fígado, e os dois rins, e a gordura deles, e o fez Moisés arder sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mas o bezerro, e seu couro, e sua carne, e seu excremento, queimou-o ao fogo fora do acampamento; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Depois fez chegar o carneiro do holocausto, e Arão e seus filhos puseram suas mãos sobre a cabeça do carneiro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'E degolou-o; e espargiu Moisés o sangue sobre o altar em derredor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'E cortou o carneiro em pedaços; e Moisés fez arder a cabeça, e os pedaços, e a gordura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Lavou logo com água os intestinos e pernas, e queimou Moisés todo o carneiro sobre o altar: holocausto em cheiro suave, oferta acesa ao SENHOR; como o havia o SENHOR mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Depois fez chegar o outro carneiro, o carneiro das consagrações, e Arão e seus filhos puseram suas mãos sobre a cabeça do carneiro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'E degolou-o; e tomou Moisés de seu sangue, e pôs sobre a ponta da orelha direita de Arão, e sobre o dedo polegar de sua mão direita, e sobre o dedo polegar de seu pé direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Fez chegar logo os filhos de Arão, e pôs Moisés do sangue sobre a ponta de suas orelhas direitas, e sobre os polegares de suas mãos direitas, e sobre os polegares de seus pés direitos: e espargiu Moisés o sangue sobre o altar em derredor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'E depois tomou a gordura, e a cauda, e toda a gordura que estava sobre os intestinos, e o redenho do fígado, e os dois rins, e a gordura deles, e a coxa direita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'E do cesto dos pães ázimos, que estava diante do SENHOR, tomou uma torta sem levedura, e uma torta de pão de azeite, e um bolo, e o pôs com a gordura e com a coxa direita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'E o pôs tudo nas mãos de Arão, e nas mãos de seus filhos, e o fez mover: oferta agitada diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Depois tomou aquelas coisas Moisés das mãos deles, e as fez arder no altar sobre o holocausto: as consagrações em cheiro suave, oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'E tomou Moisés o peito, e moveu-o, oferta movida diante do SENHOR: do carneiro das consagrações aquela foi a parte de Moisés; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Logo tomou Moisés do azeite da unção, e do sangue que estava sobre o altar, e espargiu sobre Arão, e sobre suas vestiduras, sobre seus filhos, e sobre as vestiduras de seus filhos com ele; e santificou a Arão, e suas vestiduras, e a seus filhos, e as vestiduras de seus filhos com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'E disse Moisés a Arão e a seus filhos: Comei a carne à porta do tabernáculo do testemunho; e comei-a ali com o pão que está no cesto das consagrações, segundo eu mandei, dizendo: Arão e seus filhos a comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'E o que sobrar da carne e do pão, queimareis ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Da porta do tabernáculo do testemunho não saireis em sete dias, até o dia que se cumprirem os dias de vossas consagrações: porque por sete dias sereis consagrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Da maneira que hoje se fez, mandou fazer o SENHOR para expiar-vos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'À porta, pois, do tabernáculo do testemunho estareis dia e noite por sete dias, e guardareis a ordenança diante do SENHOR, para que não morrais; porque assim me foi mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'E Arão e seus filhos fizeram todas as coisas que mandou o SENHOR por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'E foi no dia oitavo, que Moisés chamou a Arão e a seus filhos, e aos anciãos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'E disse a Arão: Toma das vacas um bezerro para expiação, e um carneiro para holocausto, sem defeito, e oferece-os diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'E aos filhos de Israel falarás, dizendo: Tomai um bode macho para expiação, e um bezerro e um cordeiro de ano, sem mácula, para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Também um boi e um carneiro para sacrifício pacífico, que imoleis diante do SENHOR; e uma oferta de cereais amassada com azeite: porque o SENHOR se aparecerá hoje a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'E levaram o que mandou Moisés diante do tabernáculo do testemunho, e chegou-se toda a congregação, e puseram-se diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Então Moisés disse: Isto é o que mandou o SENHOR; fazei-o, e a glória do SENHOR se vos aparecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'E disse Moisés a Arão: Achega-te ao altar, e faze tua expiação, e teu holocausto, e faze a reconciliação por ti e pelo povo: faze também a oferta do povo, e faze a reconciliação por eles; como mandou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Então chegou-se Arão ao altar; e degolou seu bezerro da expiação que era por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'E os filhos de Arão lhe trouxeram o sangue; e ele molhou seu dedo no sangue, e pôs sobre as pontas do altar, e derramou o resto do sangue ao pé do altar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'E a gordura e rins e redenho do fígado, da expiação, os fez arder sobre o altar; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Mas a carne e o couro os queimou ao fogo fora do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Degolou também o holocausto, e os filhos de Arão lhe apresentaram o sangue, a qual espargiu ele ao redor sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Apresentaram-lhe depois o holocausto, em pedaços, e a cabeça; e os fez queimar sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Logo lavou os intestinos e as pernas, e queimou-os sobre o holocausto no altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Ofereceu também a oferta do povo, e tomou o bode macho que era para a expiação do povo, e degolou-o, e o ofereceu pelo pecado como o primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'E ofereceu o holocausto, e fez segundo o rito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ofereceu também a oferta de cereais, e encheu dela sua mão, e o fez queimar sobre o altar, também do holocausto da manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Degolou também o boi e o carneiro em sacrifício pacífico, que era do povo: e os filhos de Arão lhe apresentaram o sangue (o qual espargiu ele sobre o altar ao redor),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'E a gordura do boi; e do carneiro a cauda com o que cobre as entranhas, e os rins, e o redenho do fígado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'E puseram a gordura sobre os peitos, e ele queimou a gordura sobre o altar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Porém os peitos, com a coxa direita, moveu-os Arão por oferta movida diante do SENHOR; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Depois levantou Arão suas mãos até o povo e abençoou-os: e desceu de fazer a expiação, e o holocausto, e o sacrifício pacífico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'E entraram Moisés e Arão no tabernáculo do testemunho; e saíram, e bendisseram ao povo: e a glória do SENHOR se apareceu a todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'E saiu fogo de diante do SENHOR, e consumiu o holocausto e a gordura sobre o altar; e vendo-o todo o povo, louvaram, e caíram sobre seus rostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'E os filhos de Arão, Nadabe e Abiú, tomaram cada um seu incensário, e puseram fogo neles, sobre o qual puseram incenso, e ofereceram diante do SENHOR fogo estranho, que ele nunca lhes mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'E saiu fogo de diante do SENHOR que os queimou, e morreram diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Então disse Moisés a Arão: Isto é o que falou o SENHOR, dizendo: Em meus achegados me santificarei, e em presença de todo o povo serei glorificado. E Arão calou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'E chamou Moisés a Misael, e a Elzafã, filhos de Uziel, tio de Arão, e disse-lhes: Achegai-vos e tirai a vossos irmãos de diante do santuário fora do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'E eles chegaram, e tiraram-nos com suas túnicas fora do acampamento, como disse Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Então Moisés disse a Arão, e a Eleazar e a Itamar, seus filhos: Não descubrais vossas cabeças, nem rasgueis vossas roupas, para que não morrais, nem se levante a ira sobre toda a congregação: porém vossos irmãos, toda a casa de Israel, lamentarão o incêndio que o SENHOR fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Nem saireis da porta do tabernáculo do testemunho, porque morrereis; porquanto o azeite da unção do SENHOR está sobre vós. E eles fizeram conforme o dito de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'E o SENHOR falou a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Tu, e teus filhos contigo, não bebereis vinho nem bebida forte, quando houverdes de entrar no tabernáculo do testemunho, para que não morrais: estatuto perpétuo por vossas gerações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'E para poder discernir entre o santo e o profano, e entre o impuro e o limpo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'E para ensinar aos filhos de Israel todos os estatutos que o SENHOR lhes disse por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'E Moisés disse a Arão, e a Eleazar e a Itamar, seus filhos que haviam restado: Tomai a oferta de cereais que resta das ofertas acendidas ao SENHOR, e comei-a sem levedura junto ao altar, porque é coisa muito santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Haveis, pois, de comê-la no lugar santo: porque isto é estatuto para ti, e estatuto para teus filhos, das ofertas acendidas ao SENHOR, pois que assim me foi mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Comereis também em lugar limpo, tu e teus filhos e tuas filhas contigo, o peito da oferta movida, e a coxa elevada, porque por estatuto para ti, e estatuto para teus filhos, são dados dos sacrifícios das ofertas pacíficas dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Com as ofertas das gorduras que se hão de acender, trarão a coxa que se há de elevar, e o peito que será movido, para que o movas por oferta movida diante do SENHOR: e será por estatuto perpétuo teu, e de teus filhos contigo, como o SENHOR o mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'E Moisés mandou o bode macho da expiação, e achou-se que era queimado: e irou-se contra Eleazar e Itamar, os filhos de Arão que haviam restado, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Por que não comestes a expiação no lugar santo? Porque é muito santa, e deu-a ele a vós para levar a iniquidade da congregação, para que sejam reconciliados diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Vedes que seu sangue não foi metido dentro do santuário: havíeis de comê-la no lugar santo, como eu mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'E respondeu Arão a Moisés: Eis que hoje ofereceram sua expiação e seu holocausto diante do SENHOR: mas me aconteceram estas coisas: pois se comesse eu hoje da expiação, Teria sido aceito ao SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'E quando Moisés ouviu isto, deu-se por satisfeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Falai aos filhos de Israel, dizendo: Estes são os animais que comereis de todos os animais que estão sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'De entre os animais, todo o de casco, e que tem as unhas fendidas, e que rumina, este comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Estes, porém, não comereis dos que ruminam e dos que têm casco: o camelo, porque rumina mas não tem casco fendido, haveis de tê-lo por impuro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Também o coelho, porque rumina, mas não tem unha fendida, o tereis por impuro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Assim a lebre, porque rumina, mas não tem unha fendida, a tereis por impura;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Também o porco, porque tem unhas, e é de unhas fendidas, mas não rumina, o tereis por impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Da carne deles não comereis, nem tocareis seu corpo morto: os tereis por impuros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Isto comereis de todas as coisas que estão nas águas: todas as coisas que têm barbatanas e escamas nas águas do mar, e nos rios, aquelas comereis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mas todas as coisas que não têm barbatanas nem escamas no mar e nos rios, tanto de todo réptil de água como de toda coisa vivente que está nas águas, as tereis em abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Vos serão, pois, em abominação: de sua carne não comereis, e abominareis seus corpos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Tudo o que não tiver barbatanas e escamas nas águas, o tereis em abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'E das aves, estas tereis em abominação; não se comerão, serão abominação: a água, o quebra-ossos, o esmerilhão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'O milhafre, e o falcão a segundo sua espécie;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Todo corvo segundo sua espécie;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'O avestruz, e a coruja, e a gaivota, e o gavião segundo sua espécie;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'E o mocho, e o corvo-marinho, e o íbis,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'E a galinha-d\'água, e o cisne, e o pelicano,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'E a cegonha, e a garça, segundo sua espécie, e a poupa, e o morcego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Todo inseto de asas que andar sobre quatro pés, tereis em abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Porém isto comereis de todo inseto de asas que anda sobre quatro patas, que tiver pernas além de suas patas para saltar com elas sobre a terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Estes comereis deles: o gafanhoto migrador segundo sua espécie, e a esperança segundo sua espécie, e o grilo segundo sua espécie, e o gafanhoto comum segundo sua espécie.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Todo réptil de asas que tenha quatro pés, tereis em abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'E por estas coisas sereis impuros: qualquer um que tocar a seus corpos mortos, será impuro até à tarde:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'E qualquer um que levar de seus corpos mortos, lavará suas roupas, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Todo animal de casco, mas que não tem unha fendida, nem rumina, tereis por impuro: qualquer um que os tocar será impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'E de todos os animais que andam a quatro patas, tereis por impuro qualquer um que ande sobre suas garras: qualquer um que tocar seus corpos mortos, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'E o que levar seus corpos mortos, lavará suas roupas, e será impuro até à tarde: haveis de tê-los por impuros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'E estes tereis por impuros dos répteis que vão arrastando sobre a terra: a doninha, e o rato, e o lagarto segundo sua espécie,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'E a lagartixa, e o lagarto pintado, e a lagartixa de parede, e a salamandra, e o camaleão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Estes tereis por impuros de todos os répteis: qualquer um que os tocar, quando estiverem mortos, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'E tudo aquilo sobre que cair algum deles depois de mortos, será impuro; tanto vaso de madeira, como roupa, ou pele, ou saco, qualquer instrumento com que se faz obra, será posto em água, e será impuro até à tarde, e assim será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'E toda vasilha de barro dentro da qual cair algum deles, tudo o que estiver nela será impuro, e quebrareis a vasilha:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Toda comida que se come, sobre a qual vier a água de tais vasilhas, será imunda: e toda bebida que se beber, será em todas essas vasilhas impura:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'E tudo aquilo sobre que cair algo do corpo morto deles, será impuro: o forno ou aquecedores se derrubarão; são impuros, e por impuros os tereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Contudo, a fonte e a cisterna onde se recolhem águas, serão limpas: mas o que houver tocado em seus corpos mortos será impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'E se cair de seus corpos mortos sobre alguma semente que se haja de semear, será limpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mas se se houver posto água na semente, e cair de seus corpos mortos sobre ela, a tereis por impura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'E se algum animal que tiverdes para comer se morrer, o que tocar seu corpo morto será impuro até à tarde:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'E o que comer de seu corpo morto, lavará suas roupas, e será impuro até à tarde: também o que tirar seu corpo morto, lavará suas roupas, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'E todo réptil que vai arrastando sobre a terra, é abominação; não se comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Tudo o que anda sobre o peito, e tudo o que anda sobre quatro ou mais patas, de todo réptil que anda arrastando sobre a terra, não o comereis, porque é abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Não torneis abomináveis vossas pessoas com nenhum réptil que anda arrastando, nem vos contamineis com eles, nem sejais impuros por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Pois que eu sou o SENHOR vosso Deus, vós portanto vos santificareis, e sereis santos, porque eu sou santo: assim que não torneis abomináveis vossas pessoas com nenhum réptil que andar arrastando sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Porque eu sou o SENHOR, que vos faço subir da terra do Egito para vos ser por Deus: sereis pois santos, porque eu sou santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Esta é a lei dos animais e das aves, e de todo ser vivente que se move nas águas, e de todo animal que anda arrastando sobre a terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Para fazer diferença entre impuro e limpo, e entre os animais que se podem comer e os animais que não se podem comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Fala aos filhos de Israel, dizendo: A mulher quando conceber e der à luz macho, será impura sete dias; conforme os dias que está separada por sua menstruação, será impura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'E ao oitavo dia circuncidará a carne de seu prepúcio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Mas ela permanecerá trinta e três dias no sangue de sua purificação: nenhuma coisa santa tocará, nem virá ao santuário, até que sejam cumpridos os dias de sua purificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'E se der à luz fêmea será impura duas semanas, conforme sua separação, e sessenta e seis dias estará purificando-se de seu sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'E quando os dias de sua purificação forem cumpridos, por filho ou por filha, trará um cordeiro de ano para holocausto, e um pombinho ou uma rolinha para expiação, à porta do tabernáculo do testemunho, ao sacerdote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'E ele oferecerá diante do SENHOR, e fará expiação por ela, e será limpa do fluxo de seu sangue. Esta é a lei da que der à luz macho ou fêmea.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'E se não alcançar sua mão o suficiente para um cordeiro, tomará então duas rolinhas ou dois pombinhos, um para holocausto, e outro para expiação: e o sacerdote fará expiação por ela, e será limpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Quando o homem tiver na pele de sua carne inchaço, ou pústula, ou mancha branca, e houver na pele de sua carne como chaga de lepra, será trazido a Arão o sacerdote, ou a um dos sacerdotes seus filhos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'E o sacerdote olhará a chaga na pele da carne: se o pelo na chaga se tornou branco, e parecer a chaga mais profunda que a pele da carne, chaga de lepra é; e o sacerdote lhe reconhecerá, e lhe dará por impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'E se na pele de sua carne houver mancha branca, mas não parecer mais profunda que a pele, nem seu pelo se houver tornado branco, então o sacerdote encerrará ao que tem chagas por sete dias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'E ao sétimo dia o sacerdote o olhará; e se a chaga a seu parecer se houver parado, não havendo-se estendido na pele, então o sacerdote lhe voltará a encerrar por outros sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'E ao sétimo dia o sacerdote lhe reconhecerá de novo; e se parece haver-se escurecido a chaga, e que não estendeu na pele, então o sacerdote o dará por limpo: era pústula; e lavará suas roupas, e será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mas se houver ido crescendo a pústula na pele, depois que foi mostrado ao sacerdote para ser limpo, será visto outra vez pelo sacerdote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'E se reconhecendo-o o sacerdote, vê que a pústula cresceu na pele, o sacerdote o dará por impuro: é lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Quando houver chaga de lepra no homem, será trazido ao sacerdote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'E o sacerdote olhará, e se parecer inchaço branco na pele, o qual tenha mudado a cor do pelo, e se descobre também a carne viva,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Lepra é envelhecida na pele de sua carne; e lhe dará por impuro o sacerdote, e não lhe encerrará, porque é impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Mas se brotar a lepra estendendo pela pele, e ela cobrir toda a pele do que tem chagas desde sua cabeça até seus pés, a toda vista de olhos do sacerdote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Então o sacerdote lhe reconhecerá; e se a lepra houver coberto toda sua carne, dará por limpo ao que tem chagas: tornou-se toda ela branca; e ele é limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mas o dia que parecer nele a carne viva, será impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'E o sacerdote olhará a carne viva, e o dará por impuro. É impura a carne viva: é lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mas quando a carne viva se mudar e tornar branca, então virá ao sacerdote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'E o sacerdote olhará, e se a chaga se houver tornado branca, o sacerdote dará por limpo ao que tinha a chaga, e será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'E quando na carne, em sua pele, houver úlcera, e se sarar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'E suceder no lugar da úlcera inchaço branco, ou mancha branca avermelhada, será mostrado ao sacerdote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'E o sacerdote olhará; e se parecer estar mais baixa que sua pele, e seu pelo se houver tornado branco, o dará o sacerdote por impuro: é chaga de lepra que se originou na úlcera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'E se o sacerdote a considerar, e não parecer nela pelo branco, nem estiver mais baixa que a pele, mas sim escura, então o sacerdote o encerrará por sete dias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'E se se for estendendo pela pele, então o sacerdote o dará por impuro: é chaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Porém se a mancha branca estiver em seu lugar, que não tenha estendido, é a cicatriz da úlcera; e o sacerdote o dará por limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Assim quando a carne tiver em sua pele queimadura de fogo, e houver no sarado do fogo mancha esbranquiçada, avermelhada ou branca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'O sacerdote a olhará; e se o pelo se houver tornado branco na mancha, e parecer estar mais profunda que a pele, é lepra que saiu na queimadura; e o sacerdote declarará ao sujeito impuro, por ser chaga de lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mas se o sacerdote a olhar, e não parecer na mancha pelo branco, nem estiver mais baixa que a pele, mas sim que está escura, lhe encerrará o sacerdote por sete dias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'E ao sétimo dia o sacerdote a reconhecerá: se se houver ido estendendo pela pele, o sacerdote o dará por impuro: é chaga de lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Porém se a mancha estiver em seu lugar, e não se houver estendido na pele, a não ser que está escura, inchaço é da queimadura: o dará o sacerdote por limpo; que sinal da queimadura é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'E ao homem ou mulher que lhe sair chaga na cabeça, ou no queixo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'O sacerdote olhará a chaga; e se parecer estar mais profunda que a pele, e o pelo nela fora ruivo e fino, então o sacerdote o dará por impuro: é tinha, é lepra da cabeça ou do queixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Mas quando o sacerdote houver olhado a chaga da tinha, e não parecer estar mais profunda que a pele, nem for nela pelo negro, o sacerdote encerrará ao que tem chagas da tinha por sete dias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'E ao sétimo dia o sacerdote olhará a chaga: e se a tinha não parecer haver-se estendido, nem houver nela pelo ruivo, nem parecer a tinha mais profunda que a pele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Então o raparão, mas não raparão o lugar da tinha: e encerrará o sacerdote ao que tem a tinha por outros sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'E ao sétimo dia olhará o sacerdote a tinha; e se a tinha não houver estendido na pele, nem parecer estar mais profunda que a pele, o sacerdote o dará por limpo; e lavará suas roupas, e será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Porém se a tinha se houver ido estendendo na pele depois de sua purificação,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Então o sacerdote a olhará; e se a tinha houver estendido na pele, não busque o sacerdote o pelo ruivo, é impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mas se lhe parecer que a tinha está detida, e que saiu nela o pelo negro, a tinha está sarada; ele está limpo, e por limpo o dará o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Também o homem ou mulher, quando na pele de sua carne tiver machas, machas brancas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'O sacerdote olhará: e se na pele de sua carne parecerem machas brancas algo escurecidas, é impigem que brotou na pele, está limpa a pessoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'E o homem, quando se lhe cair os cabelos da cabeça, é calvo, mas limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'E se à parte de seu rosto se lhe cair os cabelos da cabeça, é calvo pela frente, mas limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mas quando na calva ou na calva da frente houver chaga branca avermelhada, lepra é que brota em sua calva ou em sua calva da frente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Então o sacerdote o olhará, e se parecer a inchaço da chaga branca avermelhada em sua calva ou em sua calva da frente, como o parecer da lepra da pele da carne,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Leproso é, é impuro; o sacerdote o dará logo por impuro; em sua cabeça tem sua chaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'E o leproso em quem houver chaga, suas roupas serão derrotados e sua cabeça descoberta, e com o lábio superior coberto proclamará: -Imundo! -Imundo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Durante todo o tempo que a chaga estiver nele será imundo; estará impuro: habitará sozinho; fora do acampamento será sua morada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'E quando na roupa houver praga de lepra, em vestido de lã, ou em vestido de linho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Ou na urdidura ou em trama, de linho ou de lã, ou em pele, ou em qualquer obra de pele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'E que a praga seja verde, ou vermelha, em roupa ou em pele, ou na urdidura, ou em trama, ou em qualquer obra de pele; praga é de lepra, e se há de mostrar ao sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'E o sacerdote olhará a praga, e encerrará a coisa que tem praga por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'E ao sétimo dia olhará a praga: e se houver estendido a praga na roupa, ou urdidura, ou na trama, ou em pele, ou em qualquer obra que se faz de peles, lepra roedora é a praga; impura será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Será queimada a roupa, ou urdidura ou trama, de lã ou de linho, ou qualquer obra de peles em que houver tal praga; porque lepra roedora é; ao fogo será queimada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'E se o sacerdote olhar, e não parecer que a praga se tenha estendido na roupa, ou urdidura, ou na trama, ou em qualquer obra de peles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Então o sacerdote mandará que lavem onde está a praga, e o encerrará outra vez por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'E o sacerdote olhará depois que a praga for lavada; e se parecer que a praga não mudou seu aspecto, ainda que não tenha estendido a praga, impura é; a queimarás ao fogo; corrosão é penetrante, esteja o estragado na face ou no verso daquela coisa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mas se o sacerdote a vir, e parecer que a praga se escureceu depois que foi lavada, a cortará da roupa, ou da pele, ou da urdidura, ou da trama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'E se parecer mais no vestido, ou urdidura, ou trama, ou em qualquer coisa de peles, esverdeando nela, queimarás ao fogo aquilo onde estiver a praga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Porém a roupa, ou urdidura, ou trama, ou qualquer coisa de pele que lavares, e que se lhe tirar a praga, se lavará segunda vez, e então será limpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Esta é a lei da praga da lepra da roupa de lã ou de linho, ou da urdidura, ou da trama, ou de qualquer coisa de pele, para que seja dada por limpa ou por impura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Esta será a lei do leproso quando se limpar: Será trazido ao sacerdote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'E o sacerdote sairá fora do acampamento; e olhará o sacerdote, e vendo que está sã a praga da lepra do leproso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'O sacerdote mandará logo que se tomem para o que se purifica duas aves vivas, limpas, e pau de cedro, e carmesim, e hissopo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'E mandará o sacerdote matar uma ave em um vaso de barro sobre águas vivas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Depois tomará a ave viva, e o pau de cedro, e o carmesim, e o hissopo, e o molhará com a ave viva no sangue da ave morta sobre as águas vivas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'E espargirá sete vezes sobre o que se purifica da lepra, e lhe dará por limpo; e soltará a ave viva sobre a face do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'E o que se purifica lavará suas roupas, e rapará todos os seus pelos, e se há de lavar com água, e será limpo: e depois entrará no acampamento, e morará fora de sua tenda sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'E será, que ao sétimo dia rapará todos os seus pelos, sua cabeça, e sua barba, e as sobrancelhas de seus olhos; finalmente, rapará todo seu pelo, e lavará suas roupas, e lavará sua carne em águas, e será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'E o dia oitavo tomará dois cordeiros sem defeito, e uma cordeira de ano sem mácula; e três dízimas de flor de farinha para oferta amassada com azeite, e um logue de azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'E o sacerdote que lhe purifica apresentará com aquelas coisas ao que se há de limpar diante do SENHOR, à porta do tabernáculo do testemunho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'E tomará o sacerdote um cordeiro, e o oferecerá pela culpa, com o logue de azeite, e o moverá como oferta movida diante do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'E degolará o cordeiro no lugar onde degolam o sacrifício pelo pecado e o holocausto, no lugar do santuário: porque como o sacrifício pelo pecado, assim também o sacrifício pela culpa é do sacerdote: é coisa muito sagrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'E tomará o sacerdote do sangue do animal sacrificado pela culpa, e porá o sacerdote sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Também tomará o sacerdote do logue de azeite, e lançará sobre a palma de sua mão esquerda:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'E molhará seu dedo direito no azeite que tem em sua mão esquerda, e espargirá do azeite com seu dedo sete vezes diante do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'E do que restar do azeite que tem em sua mão, porá o sacerdote sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito, sobre o sangue da expiação pela culpa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'E o que restar do azeite que tem em sua mão, porá sobre a cabeça do que se purifica: e fará o sacerdote expiação por ele diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Oferecerá logo o sacerdote o sacrifício pelo pecado, e fará expiação pelo que se há de purificar de sua impureza, e depois degolará o holocausto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'E fará subir o sacerdote o holocausto e a oferta de cereais sobre o altar. Assim fará o sacerdote expiação por ele, e será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Mas se for pobre, que não alcançar sua mão a tanto, então tomará um cordeiro para ser oferecido como oferta movida pela culpa, para reconciliar-se, e uma dízima de flor de farinha amassada com azeite para oferta de cereais, e um logue de azeite;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'E duas rolinhas, ou dois pombinhos, o que alcançar sua mão: e um será para expiação pelo pecado, e o outro para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'As quais coisas trará ao oitavo dia de sua purificação ao sacerdote, à porta do tabernáculo do testemunho diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'E o sacerdote tomará o cordeiro da expiação pela culpa, e o logue de azeite, e o moverá o sacerdote como oferta movida diante do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Logo degolará o cordeiro da culpa, e tomará o sacerdote do sangue da culpa, e porá sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'E o sacerdote lançará do azeite sobre a palma de sua mão esquerda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'E com seu dedo direito espargirá o sacerdote do azeite que tem em sua mão esquerda, sete vezes diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Também porá o sacerdote do azeite que tem em sua mão sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito, no lugar do sangue da culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'E o que sobrar do azeite que o sacerdote tem em sua mão, o porá sobre a cabeça do que se purifica, para reconciliá-lo diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Também oferecerá uma das rolinhas, ou dos pombinhos, o que alcançar sua mão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'O um do que alcançar sua mão, em expiação pelo pecado, e o outro em holocausto, ademais da oferta: e fará o sacerdote expiação pelo que se há de purificar, diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Esta é a lei do que houver tido praga de lepra, cuja mão não alcançar o prescrito para purificar-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'E falou o SENHOR a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Quando houveres entrado na terra de Canaã, a qual eu vos dou em possessão, e puser eu praga de lepra em alguma casa da terra de vossa possessão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Virá aquele cuja for a casa, e dará aviso ao sacerdote, dizendo: Como praga apareceu em minha casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Então mandará o sacerdote, e despejarão a casa antes que o sacerdote entre a olhar a praga, para que não seja contaminado tudo o que estiver na casa: e depois o sacerdote entrará a reconhecer a casa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'E olhará a praga: e se se virem machas nas paredes da casa, cavidades esverdeadas ou vermelhas, as quais parecerem mais profundas que a parede,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'O sacerdote sairá da casa à porta dela, e fechará a casa por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'E ao sétimo dia voltará o sacerdote, e olhará: e se a praga houver crescido nas paredes da casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Então mandará o sacerdote, e arrancarão as pedras em que estiver a praga, e as lançarão fora da cidade, em lugar impuro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'E fará raspar a casa por dentro ao redor, e derramarão o pó que rasparem fora da cidade em lugar impuro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'E tomarão outras pedras, e as porão em lugar das pedras tiradas; e tomarão outro barro, e rebocarão a casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'E se a praga voltar a esverdear naquela casa, depois que fez arrancar as pedras, e raspar a casa, e depois que foi rebocada,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Então o sacerdote entrará e olhará; e se parecer haver-se estendido a praga na casa, lepra roedora está na casa: impura é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Derrubará, portanto, a tal casa, suas pedras, e seus madeiros, e toda a mistura da casa; e o tirará fora da cidade a lugar impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'E qualquer um que entrar naquela casa todos os dias que a mandou fechar, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'E o que dormir naquela casa, lavará suas roupas; também o que comer na casa, lavará suas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mas se entrar o sacerdote e olhar, e vir que a praga não se estendeu na casa depois que foi rebocada, o sacerdote dará a casa por limpa, porque a praga sarou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Então tomará para limpar a casa duas aves, e pau de cedro, e carmesim, e hissopo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'E degolará uma ave em uma vasilha de barro sobre águas vivas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'E tomará o pau de cedro, e o hissopo, e o carmesim, e a ave viva, e o molhará no sangue da ave morta e nas águas vivas, e espargirá a casa sete vezes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'E purificará a casa com o sangue da ave, e com as águas vivas, e com a ave viva, e o pau de cedro, e o hissopo, e o carmesim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Logo soltará a ave viva fora da cidade sobre a face do campo: Assim fará expiação pela casa, e será limpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Esta é a lei acerca de toda praga de lepra, e de tinha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'E da lepra da roupa, e da casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'E acerca do inchaço, e da pústula, e da mancha branca:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Para ensinar quando é impuro, e quando limpo. Esta é a lei tocante à lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Falai aos filhos de Israel, e dizei-lhes: Qualquer homem, quando seu corrimento sair de sua carne, será impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'E esta será sua impureza em seu fluxo; seja que sua carne derramou por causa de seu fluxo, ou que sua carne se obstruiu por causa de seu fluxo, ele será impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Toda cama em que se deitar o que tiver fluxo, será impura; e toda coisa sobre que se sentar, impura será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'E qualquer um que tocar em sua cama, lavará suas roupas; lavará também a si mesmo com água, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'E o que se sentar sobre aquilo em que se houver sentado o que tem fluxo, lavará suas roupas, se lavará também a si mesmo com água, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Também o que tocar a carne do que tem fluxo, lavará suas roupas, e a si mesmo se lavará com água, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'E se o que tem fluxo cuspir sobre o limpo, este lavará suas roupas, e depois de haver-se lavado com água, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'E toda sela sobre que cavalgar o que tiver fluxo, será impura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'E qualquer um que tocar qualquer coisa que tenha estado debaixo dele, será impuro até à tarde; e o que a levar, lavará suas roupas, e depois de lavar-se com água, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'E todo aquele a quem tocar o que tem fluxo, e não lavar com água suas mãos, lavará suas roupas, e a si mesmo se lavará com água, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'E a vasilha de barro em que tocar o que tem fluxo, será quebrada; e toda vasilha de madeira será lavada com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'E quando se houver limpado de seu fluxo o que tem fluxo, se há de contar sete dias desde sua purificação, e lavará suas roupas, e lavará sua carne em águas vivas, e será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'E no oitavo dia tomará duas rolinhas, ou dois pombinhos, e virá diante do SENHOR à porta do tabernáculo do testemunho, e os dará ao sacerdote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'E os fará o sacerdote, uma oferta pelo pecado, e o outro holocausto: e lhe purificará o sacerdote de seu fluxo diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'E o homem, quando dele sair derramamento seminal, lavará em águas toda sua carne, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'E toda vestimenta, ou toda pele sobre a qual houver o derramamento seminal, lavará com água, e será impura até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'E a mulher com quem o homem tiver ajuntamento seminal, ambos se lavarão com água, e serão impuros até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'E quando a mulher tiver fluxo de sangue, e seu fluxo for em sua carne, sete dias estará separada; e qualquer um que tocar nela, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'E tudo aquilo sobre que ela se deitar durante sua separação, será impuro: também tudo aquilo sobre que se sentar, será impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'E qualquer um que tocar a sua cama, lavará suas roupas, e depois de lavar-se com água, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Também qualquer um que tocar qualquer móvel sobre que ela se houver sentado, lavará suas roupas; lavará logo a si mesmo com água, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'E se estiver sobre a cama, ou sobre a cadeira em que ela se houver sentado, o que tocar nela será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'E se alguém dormir com ela, e sua menstruação for sobre ele, será impuro por sete dias; e toda cama sobre que dormir, será impura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'E a mulher, quando seguir o fluxo de seu sangue por muitos dias fora do tempo de seu costume, ou quando tiver fluxo de sangue mais de seu costume; todo o tempo do fluxo de seu imundícia, será impura como nos dias de seu costume.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Toda cama em que dormir todo o tempo de seu fluxo, lhe será como a cama de seu costume; e todo móvel sobre que se sentar, será impuro, como a impureza de seu costume.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Qualquer um que tocar em essas coisas será impuro; e lavará suas roupas, e a si mesmo se lavará com água, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'E quando for livre de seu fluxo, se há de contar sete dias, e depois será limpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'E o oitavo dia tomará consigo duas rolinhas, ou dois pombinhos, e os trará ao sacerdote, à porta do tabernáculo do testemunho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'E o sacerdote fará um oferta pelo pecado, e o outro holocausto; e a purificará o sacerdote diante do SENHOR do fluxo de sua impureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Assim separareis os filhos de Israel de suas imundícias, a fim de que não morram por suas imundícias, contaminando meu tabernáculo que está entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Esta é a lei do que tem fluxo, e do que sai derramamento seminal, vindo a ser impuro por causa disso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'E da que padece seu costume, e acerca do que tiver fluxo, seja homem ou fêmea, e do homem que dormir com mulher impura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'E falou o SENHOR a Moisés, depois que morreram os dois filhos de Arão, quando se chegaram diante do SENHOR, e morreram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'E o SENHOR disse a Moisés: Dize a Arão teu irmão, que não em todo tempo entre no santuário do véu dentro, diante do propiciatório que está sobre a arca, para que não morra: porque eu aparecerei na nuvem sobre o propiciatório.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Com isto entrará Arão no santuário: com um bezerro por expiação, e um carneiro em holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'A túnica santa de linho se vestirá, e sobre sua carne terá calções de linho, e se cingirá o cinto de linho; e com a mitra de linho se cobrirá: são as santas vestiduras: com elas, depois de lavar sua carne com água, se há de vestir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'E da congregação dos filhos de Israel tomará dois machos de bode para expiação, e um carneiro para holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'E fará achegar Arão o bezerro da expiação, que é seu, e fará a reconciliação por si e por sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Depois tomará os dois machos de bode, e os apresentará diante do SENHOR à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'E lançará sortes Arão sobre os dois machos de bode; uma sorte pelo SENHOR, e a outra sorte por Azazel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'E fará achegar Arão o bode macho sobre o qual cair a sorte pelo SENHOR, e o oferecerá em expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Mas o bode macho, sobre o qual cair a sorte por Azazel, o apresentará vivo diante do SENHOR, para fazer a reconciliação sobre ele, para enviá-lo a Azazel ao deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'E fará chegar Arão o bezerro que era seu para expiação, e fará a reconciliação por si e por sua casa, e degolará em expiação o bezerro que é seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Depois tomará o incensário cheio de brasas de fogo, do altar de diante do SENHOR, e seus punhos cheios do incenso aromático prensado, e o meterá do véu dentro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'E porá o incenso sobre o fogo diante do SENHOR, e a nuvem do incenso cobrirá o propiciatório que está sobre o testemunho, e não morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Tomará logo do sangue do bezerro, e espargirá com seu dedo até o propiciatório ao lado oriental: até o propiciatório espargirá sete vezes daquele sangue com seu dedo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Depois degolará em expiação o bode macho, que era do povo, e meterá o sangue dele do véu dentro; e fará de seu sangue como fez do sangue do bezerro, e espargirá sobre o propiciatório e diante do propiciatório:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'E limpará o santuário, das imundícias dos filhos de Israel, e de suas rebeliões, e de todos os seus pecados: da mesma maneira fará também ao tabernáculo do testemunho, o qual reside entre eles em meio de suas imundícias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'E nenhum homem estará no tabernáculo do testemunho quando ele entrar a fazer a reconciliação no santuário, até que ele saia, e haja feito a reconciliação por si, e por sua casa, e por toda a congregação de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'E sairá ao altar que está diante do SENHOR, e o expiará; e tomará do sangue do bezerro, e do sangue do bode macho, e porá sobre as pontas do altar ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'E espargirá sobre ele do sangue com seu dedo sete vezes, e o limpará, e o santificará das imundícias dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'E quando houver acabado de expiar o santuário, e o tabernáculo do testemunho, e o altar, fará chegar o bode macho vivo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'E porá Arão ambas as mãos suas sobre a cabeça do bode macho vivo, e confessará sobre ele todas as iniquidades dos filhos de Israel, e todas suas rebeliões, e todos os seus pecados, pondo-os assim sobre a cabeça do bode macho, e o enviará ao deserto por meio de um homem destinado para isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'E aquele bode macho levará sobre si todas as iniquidades deles a terra inabitada: e deixará ir o bode macho pelo deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Depois virá Arão ao tabernáculo do testemunho, e se desnudará as vestimentas de linho, que havia vestido para entrar no santuário, e as porá ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Lavará logo sua carne com água no lugar do santuário, e depois de se pôr suas roupas sairá, e fará seu holocausto, e o holocausto do povo, e fará a reconciliação por si e pelo povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'E queimará a gordura da expiação sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'E o que houver levado o bode macho a Azazel, lavará suas roupas, lavará também com água sua carne, e depois entrará no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'E tirará fora do acampamento o bezerro do pecado, e o bode macho da culpa, o sangue dos quais foi metido para fazer a expiação no santuário; e queimarão no fogo suas peles, e suas carnes, e seu excremento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'E o que os queimar, lavará suas roupas, lavará também sua carne com água, e depois entrará no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'E isto tereis por estatuto perpétuo: No mês sétimo, aos dez do mês, afligireis vossas almas, e nenhuma obra fareis, nem o natural nem o estrangeiro que peregrina entre vós:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Porque neste dia se vos reconciliará para limpar-vos; e sereis limpos de todos vossos pecados diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sábado de repouso é para vós, e afligireis vossas almas, por estatuto perpétuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'E fará a reconciliação o sacerdote que for ungido, e cuja mão houver sido cheia para ser sacerdote em lugar de seu pai; e se vestirá as vestimentas de linho, as vestiduras sagradas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'E expiará o santuário santo, e o tabernáculo do testemunho; expiará também o altar, e aos sacerdotes, e a todo o povo da congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'E isto tereis por estatuto perpétuo, para expiar aos filhos de Israel de todos os seus pecados uma vez no ano. E Moisés o fez como o SENHOR lhe mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Fala a Arão e a seus filhos, e a todos os filhos de Israel, e dize-lhes: Isto é o que mandou o SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Qualquer homem da casa de Israel que degolar boi, ou cordeiro, ou cabra, no acampamento, ou fora do acampamento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'E não o trouxer à porta do tabernáculo do testemunho, para oferecer oferta ao SENHOR diante do tabernáculo do SENHOR, sangue será imputado ao tal homem: sangue derramou; eliminado será o tal homem dentre seu povo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'A fim de que tragam os filhos de Israel seus sacrifícios, os que sacrificam sobre a face do campo, para que os tragam ao SENHOR à porta do tabernáculo do testemunho ao sacerdote, e sacrifiquem eles sacrifícios pacíficos ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'E o sacerdote espargirá o sangue sobre o altar do SENHOR, à porta do tabernáculo do testemunho, e queimará a gordura em cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'E nunca mais sacrificarão seus sacrifícios aos demônios, atrás dos quais se prostituíram: terão isto por estatuto perpétuo por suas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Tu Lhes dirás também: Qualquer homem da casa de Israel, ou dos estrangeiros que peregrinam entre vós, que oferecer holocausto ou sacrifício,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'E não o trouxer à porta do tabernáculo do testemunho, para fazê-lo ao SENHOR, o tal homem será igualmente eliminado de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'E qualquer homem da casa de Israel, ou dos estrangeiros que peregrinam entre eles, que comer algum sangue, eu porei meu rosto contra a pessoa que comer sangue, e lhe cortarei dentre seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Porque a vida da carne no sangue está: e eu vos a dei para expiar vossas pessoas sobre o altar: pelo qual o mesmo sangue expiará a pessoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Portanto, disse aos filhos de Israel: Nenhuma pessoa de vós comerá sangue, nem o estrangeiro que peregrina entre vós comerá sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'E qualquer homem dos filhos de Israel, ou dos estrangeiros que peregrinam entre eles, que recolher caça de animal ou de ave que seja de comer, derramará seu sangue e o cobrirá com terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Porque a alma de toda carne, sua vida, está em seu sangue: portanto disse aos filhos de Israel: Não comereis o sangue de nenhuma carne, porque a vida de toda carne é seu sangue; qualquer um que a comer será eliminado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'E qualquer um pessoa que comer coisa morta ou despedaçada por fera, tanto dos naturais como dos estrangeiros, lavará suas roupas e a si mesmo se lavará com água, e será impuro até à tarde; e se limpará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'E se não os lavar, nem lavar sua carne, levará sua iniquidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Fala aos filhos de Israel, e dize-lhes: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Não fareis como fazem na terra do Egito, na qual morastes; nem fareis como fazem na terra de Canaã, à qual eu vos conduzo; nem andareis em seus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Meus regulamentos poreis por obra, e meus estatutos guardareis, andando neles: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Portanto meus estatutos e meus regulamentos guardareis, os quais fazendo o homem, viverá neles: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nenhum homem se achegue a nenhuma próxima de sua carne, para descobrir sua nudez: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'A nudez de teu pai, ou a nudez de tua mãe, não descobrirás: tua mãe é, não descobrirá sua nudez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'A nudez da mulher de teu pai não descobrirás; é a nudez de teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'A nudez de tua irmã, filha de teu pai, ou filha de tua mãe, nascida em casa ou nascida fora, sua nudez não descobrirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'A nudez da filha de teu filho, ou da filha de tua filha, seu nudez não descobrirás, porque é a nudez tua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'A nudez da filha da mulher de teu pai, gerada de teu pai, tua irmã é, sua nudez não descobrirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'A nudez da irmã de teu pai não descobrirás: é parente de teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'A nudez da irmã de tua mãe não descobrirás: porque parente de tua mãe é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'A nudez do irmão de teu pai não descobrirás: não chegarás à sua mulher: é mulher do irmão de teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'A nudez de tua nora não descobrirás: mulher é de teu filho, não descobrirás sua nudez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'A nudez da mulher de teu irmão não descobrirás: é a nudez de teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'A nudez da mulher e de sua filha não descobrirás: não tomarás a filha de seu filho, nem a filha de sua filha, para descobrir sua nudez: são parentes, é maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Não tomarás mulher juntamente com sua irmã, para fazê-la sua rival, descobrindo sua nudez diante dela em sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'E não chegarás à mulher na separação de sua impureza, para descobrir sua nudez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Além disso, não terás ato carnal com a mulher de teu próximo, contaminando-te nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'E não dês de tua descendência para fazê-la passar pelo fogo a Moloque; não contamines o nome de teu Deus: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Não te deitarás com homem como com mulher: é abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Nem com nenhum animal terás ajuntamento contaminando-te com ele; nem mulher alguma se porá diante de animal para ajuntar-se com ele: é confusão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Em nenhuma destas coisas vos contaminareis; porque em todas estas coisas se poluíram as nações que eu expulso de diante de vós:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'E a terra foi contaminada; e eu visitei sua maldade sobre ela, e a terra vomitou seus moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Guardai, pois, vós meus estatutos e meus regulamentos, e não façais nenhuma de todas estas abominações: nem o natural nem o estrangeiro que peregrina entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(Porque todas estas abominações fizeram os homens da terra, que foram antes de vós, e a terra foi contaminada:)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'E a terra não vos vomitará, por havê-la contaminado, como vomitou à gente que foi antes de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Porque qualquer um que fizer alguma de todas estas abominações, as pessoas que as fizerem, serão eliminadas dentre seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Guardai, pois, minha ordenança, não fazendo das práticas abomináveis que tiveram lugar antes de vós, e não vos torneis abomináveis nelas: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Fala a toda a congregação dos filhos de Israel, e dize-lhes: Santos sereis, porque santo sou eu o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Cada um temerá a sua mãe e a seu pai, e meus sábados guardareis: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Não vos voltareis aos ídolos, nem fareis para vós deuses de fundição: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'E quando sacrificardes sacrifício pacífico ao SENHOR, de vossa vontade o sacrificareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Será comido o dia que o sacrificardes, e o dia seguinte: e o que restar para o terceiro dia, será queimado no fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'E se se comer no dia terceiro, será abominação; não será aceito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'E o que o comer, levará seu delito, porquanto profanou o santo do SENHOR; e a tal pessoa será eliminada de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Quando ceifardes na colheita de vossa terra, não acabarás de ceifar o canto de tua plantação, nem espigarás tua terra ceifada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'E não coletarás os restos de tua vinha, nem recolherás as uvas caídas de tua vinha; para o pobre e para o estrangeiro os deixarás: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Não furtareis, e não enganareis, nem mentireis ninguém a seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'E não jurareis em meu nome com mentira, nem profanarás o nome de teu Deus: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Não oprimirás a teu próximo, nem lhe roubarás. Não se deterá o trabalho do assalariado em tua casa até a manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Não amaldiçoes ao surdo, e diante do cego não ponhas tropeço, mas terás temor de teu Deus: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Não farás injustiça no juízo: não favorecerás deslealmente ao pobre, nem honrarás a face do poderoso: com justiça julgarás a teu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Não andarás propagando boatos em teus povos. Não te porás contra o sangue de teu próximo: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Não aborrecerás a teu irmão em teu coração: francamente repreenderás a teu próximo, e não consentirás sobre ele pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Não te vingarás, nem guardarás rancor aos filhos de teu povo: mas amarás a teu próximo como a ti mesmo: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Meus estatutos guardareis. A teu animal não farás ajuntar para espécies misturadas; tua plantação não semearás com mistura de sementes, e não te porás roupas com mistura de diversos materiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'E quando um homem tiver relação sexual com mulher, e ela for serva desposada com alguém, e não estiver resgatada, nem lhe houver sido dada liberdade, ambos serão açoitados: não morrerão, porquanto ela não é livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'E ele trará ao SENHOR, à porta do tabernáculo do testemunho, um carneiro em expiação por sua culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'E com o carneiro da expiação o reconciliará o sacerdote diante do SENHOR, por seu pecado que cometeu: e se lhe perdoará seu pecado que cometeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'E quando houverdes entrado na terra, e plantardes toda árvore de comer, tirareis seu prepúcio, o primeiro de seu fruto: três anos vos será incircunciso: seu fruto não se comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'E o quarto ano todo seu fruto será santidade de louvores ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Mas ao quinto ano comereis o fruto dele, para que vos faça crescer seu fruto: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Não comereis coisa alguma com sangue. Não sereis encantadores, nem fareis adivinhações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Não cortareis em redondo as extremidades de vossas cabeças, nem danificarás a ponta de tua barba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'E não fareis cortes em vossa carne por um morto, nem imprimireis em vós sinal alguma: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Não contaminarás tua filha fazendo-a se prostituir: para não se prostitua a terra, e se encha de maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Meus sábados guardareis, e meu santuário tereis em reverência: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Não vos volteis aos encantadores e aos adivinhos: não os consulteis contaminando-vos com eles: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Diante das cãs te levantarás, e honrarás o rosto do ancião, e de teu Deus terás temor: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'E quando o estrangeiro morar contigo em vossa terra, não o oprimireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Como a um natural de vós tereis ao estrangeiro que peregrinar entre vós; e ama-o como a ti mesmo; porque peregrinos fostes na terra do Egito: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Não façais injustiça no juízo, na medida da terra, nem no peso, nem em outra medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Balanças justas, pesos justos, efa justo, e him justo tereis. Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Guardai, pois, todos os meus estatutos, e todos os meus regulamentos, e os praticai. Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Dirás também aos filhos de Israel: Qualquer homem dos filhos de Israel, ou dos estrangeiros que peregrinam em Israel, que oferecer de sua descendência a Moloque, certamente morrerá: o povo da terra o apedrejará com pedras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'E eu porei meu rosto contra o tal homem, e o cortarei dentre seu povo; porquanto deu de sua descendência a Moloque, contaminando meu santuário, e profanando meu santo nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'E se o povo da terra esconder seus olhos daquele homem que houver dado de sua descendência a Moloque, para não matar-lhe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'então eu porei meu rosto contra aquele homem, e contra sua família, e lhe eliminarei dentre seu povo, com todos os que se prostituíram depois dele, prostituindo-se com Moloque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'E a pessoa que der atenção a encantadores ou adivinhos, para prostituir-se atrás deles, eu porei meu rosto contra a tal pessoa, e a eliminarei dentre seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Santificai-vos, pois, e sede santos, porque eu o SENHOR sou vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'E guardai meus estatutos, e os praticai. Eu sou o SENHOR que vos santifico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Aquele que amaldiçoar seu pai ou sua mãe certamente morrerá; a seu pai ou a sua mãe amaldiçoou; seu sangue será sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'E o homem que adulterar com a mulher de outro, o que cometer adultério com a mulher de seu próximo, inevitavelmente se fará morrer ao adúltero e à adúltera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Qualquer um que se deitar com a mulher de seu pai terá revelou a nudez de seu pai; ambos serão mortos; seu sangue será sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Qualquer um que dormir com a sua nora, ambos terão de morrer; fizeram confusão; seu sangue será sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Qualquer um que tiver ajuntamento com homem como se fosse com mulher, abominação fizeram entre ambos; terão de ser mortos; sobre eles será seu sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'E o que tomar uma mulher e a mãe dela comete depravação; queimarão em fogo ele e elas, para que não haja depravação entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Qualquer um que tiver relação sexual com animal, será morto; e matareis ao animal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'E a mulher que se achegar a algum animal, para ter ajuntamento com ele, à mulher e ao animal matarás; morrerão inevitavelmente; seu sangue será sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Qualquer um que tomar a sua irmã, filha de seu pai ou filha de sua mãe, e vir sua nudez, e ela vir a sua, coisa é execrável; portanto serão mortos à vista dos filhos de seu povo: revelou a nudez de sua irmã; levará consigo o seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Qualquer um que dormir com mulher menstruada, e descobrir sua nudez, sua fonte descobriu, e ela descobriu a fonte de seu sangue: ambos serão eliminados dentre seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'A nudez da irmã de tua mãe, ou da irmã de teu pai, não descobrirás; uma vez que descobriu sua parente, sua iniquidade levarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'E qualquer um que dormir com a mulher do irmão de seu pai, a nudez do irmão de seu pai descobriu; seu pecado levarão; morrerão sem filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'E o que tomar a mulher de seu irmão, é imundícia; a nudez de seu irmão descobriu; sem filhos serão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Guardai, pois, todos meus estatutos e todos meus regulamentos, e ponde-os por obra: e não vos vomitará a terra, na qual eu vos introduzo para que habiteis nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'E não andeis nas práticas da gente que eu lançarei de diante de vós: porque eles fizeram todas estas coisas, e os tive em abominação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Porém a vós vos disse: Vós possuireis a terra deles, e eu a darei a vós para que a possuais por herança, terra que flui leite e mel: Eu sou o SENHOR vosso Deus, que vos separei dos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Portanto, vós fareis diferença entre animal limpo e impuro, e entre ave impura e limpa: e não torneis abomináveis vossas pessoas nos animais, nem nas aves, nem em nenhuma coisa que vai arrastando pela terra, as quais vos separei por impuras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Haveis, pois, de ser para mim santos, porque eu o SENHOR sou santo, e vos separei dos povos, para que sejais meus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'E o homem ou a mulher em que houver espírito mediúnico ou de adivinhação, terão de ser mortos; os apedrejarão com pedras; seu próprio sangue será sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'E o SENHOR disse a Moisés: Fala aos sacerdotes filhos de Arão, e dize-lhes que não se contaminem por um morto em seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'A não ser por seu parente próximo a si, por sua mãe, ou por seu pai, ou por seu filho, ou por seu irmão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'ou por sua irmã virgem, a ele próxima, a qual não tenha tido marido, por ela se contaminará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Porque é líder em seu povo, não se contaminará, fazendo-se impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Não farão calva em sua cabeça, nem raparão a ponta de sua barba, nem em sua carne farão cortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Santos serão a seu Deus, e não profanarão o nome de seu Deus; porque oferecem os fogos do SENHOR e o pão de seu Deus; portanto, serão santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Mulher prostituta ou infame não tomarão: nem tomarão mulher repudiada de seu marido: porque é santo a seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'O santificarás portanto, pois o pão de teu Deus oferece: santo será para ti, porque santo sou eu o SENHOR vosso santificador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'E a filha do homem sacerdote, se começar a se prostituir, a seu pai profana: queimada será ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'E o sumo sacerdote entre seus irmãos, sobre cuja cabeça foi derramado o azeite da unção, e que encheu sua mão para vestir as vestimentas, não descobrirá sua cabeça, nem romperá suas roupas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'nem entrará onde haja alguma pessoa morta, nem por seu pai, ou por sua mãe se contaminará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'nem sairá do santuário, nem contaminará o santuário de seu Deus; porque a coroa do azeite da unção de seu Deus está sobre ele: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'E tomará ele mulher com sua virgindade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Viúva, ou repudiada, ou infame, ou prostituta, estas não tomará: mas tomará virgem de seus povos por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'E não profanará sua descendência em seus povos; porque eu o SENHOR sou o que os santifico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Fala a Arão, e dize-lhe: O homem de tua semente em suas gerações, no qual houver falta, não se achegará para oferecer o pão de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Porque nenhum homem no qual houver falta, se achegará: homem cego, ou coxo, ou rosto mutilado, ou membro deformado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Ou homem no qual houver fratura de pé ou rotura da mão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Ou corcunda, ou anão, ou que tiver visão embaçada, ou que tenha sarna, ou impigem, ou testículo mutilado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nenhum homem da descendência de Arão sacerdote, no qual houver falta, se achegará para oferecer as ofertas acendidas do SENHOR. Há falta nele; não se achegará a oferecer o pão de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'O pão de seu Deus, do muito santo e as coisas santificadas, comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Porém não entrará do véu dentro, nem se achegará ao altar, porquanto há falta nele: e não profanará meu santuário, porque eu o SENHOR sou o que os santifico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'E Moisés falou isto a Arão, e a seus filhos, e a todos os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Dize a Arão e a seus filhos, que se abstenham das coisas santas dos filhos de Israel, e que não profanem meu santo nome no que eles me santificam: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Dize-lhes: Todo homem de toda vossa descendência em vossas gerações que chegar às coisas sagradas, que os filhos de Israel consagram ao SENHOR, tendo imundícia sobre si, de diante de mim será eliminada sua alma: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Qualquer homem da semente de Arão que for leproso, ou padecer fluxo, não comerá das coisas sagradas até que esteja limpo: e o que tocar qualquer coisa impura de cadáver, ou o homem do qual houver saído derramamento de sêmen;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Ou o homem que houver tocado qualquer réptil ou inseto, pelo qual será impuro, ou homem pelo qual venha a ser impuro, conforme qualquer imundícia sua;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'A pessoa que o tocar, será impura até à tarde, e não comerá das coisas sagradas antes que tenha lavado sua carne com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'E quando o sol se puser, será limpo; e depois comerá as coisas sagradas, porque seu pão é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'O morto naturalmente nem despedaçado por fera não comerá, para contaminar-se em ele: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Guardem, pois, minha ordenança, e não levem pecado por ele, não seja que assim morram quando a profanarem: Eu sou o SENHOR que os santifico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Nenhum estranho comerá coisa sagrada; o hóspede do sacerdote, nem o empregado, não comerá coisa sagrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mas o sacerdote, quando comprar pessoa de seu dinheiro, esta comerá dela, e o nascido em sua casa: estes comerão de seu pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Porém a filha do sacerdote, quando se casar com homem estranho, ela não comerá da oferta das coisas sagradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Porém se a filha do sacerdote for viúva, ou repudiada, e não tiver descendência, e se houver voltado à casa de seu pai, como em sua juventude, comerá do pão de seu pai; mas nenhum estranho coma dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'E o que por acidente comer coisa sagrada, acrescentará a ela seu quinto, e o dará ao sacerdote com a coisa sagrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Não profanarão, pois, as coisas santas dos filhos de Israel, as quais separam para o SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'E não lhes farão levar a iniquidade do pecado, comendo as coisas santas deles: porque eu o SENHOR sou o que os santifico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Fala a Arão e a seus filhos, e a todos os filhos de Israel, e dize-lhes: Qualquer homem da casa de Israel, ou dos estrangeiros em Israel, que oferecer sua oferta por todos os seus votos, e por todas seus ofertas voluntárias que oferecerem ao SENHOR em holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'De vossa vontade oferecereis macho sem defeito dentre as vacas, dentre os cordeiros, ou dentre as cabras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Nenhuma coisa em que tenha falta oferecereis, porque não será aceito por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Também, quando alguém oferecer sacrifício pacífico ao SENHOR para presentear voto, ou oferecendo voluntariamente, seja de vacas ou de ovelhas, sem mácula será aceito; não há de haver nele falta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Cego, ou aleijado, ou mutilado, ou com verruga, ou sarnento ou com impingens, não oferecereis estes ao SENHOR, nem deles poreis oferta acesa sobre o altar do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Boi ou carneiro que tenha de mais ou de menos, poderás oferecer por oferta voluntária; mas por voto não será aceito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Ferido ou golpeado, rompido ou cortado, não oferecereis ao SENHOR, nem em vossa terra o fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'E da mão de filho de estrangeiro não oferecereis o pão de vosso Deus de todas estas coisas; porque sua corrupção está nelas: há nelas falta, não se vos aceitarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'O boi, ou o cordeiro, ou a cabra, quando nascer, sete dias estará mamando de sua mãe: mas desde o oitavo dia em adiante será aceito para oferta de sacrifício acendido ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'E seja boi ou carneiro, não degolareis em um dia a o e a seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'E quando sacrificardes sacrifício de ação de graças ao SENHOR, de vossa vontade o sacrificareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'No mesmo dia se comerá; não deixareis dele para outro dia: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Guardai pois meus mandamentos, e executai-os: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'E não profaneis meu santo nome, e eu me santificarei em meio dos filhos de Israel: Eu sou o SENHOR que vos santifico;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Que vos tirei da terra do Egito, para ser vosso Deus: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Fala aos filhos de Israel, e dize-lhes: As solenidades do SENHOR, as quais proclamareis santas convocações, aquelas serão minhas solenidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Seis dias se trabalhará, e no sétimo dia sábado de repouso será, convocação santa: nenhuma obra fareis; sábado é do SENHOR em todas as vossas habitações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Estas são as solenidades do SENHOR, as convocações santas, às quais convocareis em seus tempos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'No mês primeiro, aos catorze do mês, entre as duas tardes, páscoa é do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'E aos quinze dias deste mês é a solenidade dos pães ázimos ao SENHOR: sete dias comereis pães ázimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'O primeiro dia tereis santa convocação: nenhuma obra servil fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'E oferecereis ao SENHOR sete dias oferta acesa: no sétimo dia será santa convocação; nenhuma obra servil fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra que eu vos dou, e ceifardes seu colheita, trareis ao sacerdote um ômer por primícia dos primeiros frutos de vossa colheita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'O qual moverá o ômer diante do SENHOR, para que sejais aceitos: o dia seguinte do sábado o moverá o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'E no dia que oferecerdes o ômer, oferecereis um cordeiro de ano, sem defeito, em holocausto ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'E sua oferta de cereais será duas dízimas de flor de farinha amassada com azeite, oferta acesa ao SENHOR em cheiro suavíssimo; e sua libação de vinho, a quarta parte de um him.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'E não comereis pão, nem grão tostado, nem espiga fresca, até este mesmo dia, até que tenhais oferecido a oferta de vosso Deus; estatuto perpétuo é por vossas gerações em todas as vossas habitações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'E vos haveis de contar desde o dia seguinte do sábado, desde o dia em que oferecestes o ômer da oferta movida; sete semanas completas serão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Até o dia seguinte do sábado sétimo contareis cinquenta dias; então oferecereis nova oferta de cereais ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'De vossas habitações trareis dois pães para oferta movida, que serão de duas dízimas de flor de farinha, cozidos com levedura, por primícias ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'E oferecereis com o pão sete cordeiros de ano sem defeito, e um bezerro das vacas e dois carneiros: serão holocausto ao SENHOR, com sua oferta de cereais e suas libações; oferta acesa de suave cheiro ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Oferecereis também um macho de bode por expiação; e dois cordeiros de ano em sacrifício pacífico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'E o sacerdote os moverá em oferta movida diante do SENHOR, com o pão das primícias, e os dois cordeiros: serão coisa sagrada do SENHOR para o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'E convocareis neste mesmo dia; vos será santa convocação: nenhuma obra servil fareis: estatuto perpétuo em todas as vossas habitações por vossas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'E quando ceifardes a colheita de vossa terra, não acabarás de ceifar o canto de tua plantação, nem espigarás tua colheita; para o pobre, e para o estrangeiro a deixarás: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Fala aos filhos de Israel, e dize-lhes: No mês sétimo, ao primeiro do mês tereis sábado, uma comemoração ao são de trombetas, e uma santa convocação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Nenhuma obra servil fareis; e oferecereis oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Porém aos dez deste mês sétimo será o dia das expiações: tereis santa convocação, e afligireis vossas almas, e oferecereis oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Nenhuma obra fareis neste mesmo dia; porque é dia de expiações, para reconciliar-vos diante do SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Porque toda pessoa que não se afligir neste mesmo dia, será eliminada de seus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'E qualquer pessoa que fizer obra alguma neste mesmo dia, eu destruirei a tal pessoa dentre seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nenhuma obra fareis: estatuto perpétuo é por vossas gerações em todas as vossas habitações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Sábado de repouso será a vós, e afligireis vossas almas, começando aos nove do mês na tarde: de tarde a tarde descansareis vosso sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Fala aos filhos de Israel, e dize-lhes: Aos quinze dias deste mês sétimo será a solenidade das cabanas ao SENHOR por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'O primeiro dia haverá santa convocação: nenhuma obra servil fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sete dias oferecereis oferta acesa ao SENHOR: o oitavo dia tereis santa convocação, e oferecereis oferta acesa ao SENHOR: é festa: nenhuma obra servil fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Estas são as solenidades do SENHOR, às que convocareis santas reuniões, para oferecer oferta acesa ao SENHOR, holocausto e oferta de cereais, sacrifício e libações, cada coisa em seu tempo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Além disso dos sábados do SENHOR e além de vossos presentes, e a mais de todos vossos votos, e além de todas as vossas ofertas voluntárias, que dareis ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Porém aos quinze do mês sétimo, quando houverdes recolhido o fruto da terra, fareis festa ao SENHOR por sete dias: o primeiro dia será sábado; sábado será também o oitavo dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'E tomareis o primeiro dia galhos das mais belas árvores, ramos de palmeiras, e ramos de árvores frondosas, e salgueiros dos ribeiros; e vos regozijareis diante do SENHOR vosso Deus por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'E lhe fareis festa ao SENHOR por sete dias cada ano; será estatuto perpétuo por vossas gerações; no mês sétimo a fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Em cabanas habitareis sete dias: todo natural de Israel habitará em cabanas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Para que saibam vossos descendentes que em cabanas fiz eu habitar aos filhos de Israel, quando os tirei da terra do Egito: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Assim falou Moisés aos filhos de Israel sobre as solenidades do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Manda aos filhos de Israel que te tragam azeite de olivas claro, prensado, para a luminária, para fazer arder as lâmpadas continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Fora do véu do testemunho, no tabernáculo do testemunho, as preparará Arão desde a tarde até a manhã diante do SENHOR, continuamente: estatuto perpétuo por vossas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Sobre o candelabro limpo porá sempre em ordem as lâmpadas diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'E tomarás flor de farinha, e cozerás dela doze tortas: cada torta será de duas dízimas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'E hás de pô-las em duas ordens, seis em cada ordem, sobre a mesa limpa diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Porás também sobre cada ordem incenso limpo, e será para o pão por incenso, oferta acesa ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Cada dia de sábado o porá continuamente em ordem diante do SENHOR, dos filhos de Israel por pacto sempiterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'E será de Arão e de seus filhos, os quais o comerão no lugar santo; porque é coisa muito santa para ele, das ofertas acendidas ao SENHOR, por estatuto perpétuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Naquela muita o filho de uma mulher israelita, o qual era filho de um egípcio, saiu entre os filhos de Israel; e o filho da israelita e um homem de Israel brigaram no acampamento:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'E o filho da mulher israelita pronunciou o Nome, e amaldiçoou: então o levaram a Moisés. E sua mãe se chamava Selomite, filha de Dribi, da tribo de Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'E puseram-no no cárcere, até que lhes fosse sentenciado pela palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Tira ao blasfemo fora do acampamento, e todos os que o ouviram ponham suas mãos sobre a cabeça dele, e apedreje-o toda a congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'E aos filhos de Israel falarás, dizendo: Qualquer um que amaldiçoar a seu Deus, levará sua iniquidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'E o que blasfemar o nome do SENHOR, será morto; toda a congregação o apedrejará: tanto o estrangeiro como o natural, se blasfemar o Nome, que morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Também o homem que fere de morte a qualquer pessoa, que sofra a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'E o que fere a algum animal há de restituí-lo: animal por animal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'E o que causar lesão em seu próximo, segundo fez, assim lhe seja feito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Rompimento por rompimento, olho por olho, dente por dente: segundo a lesão que haverá feito a outro, tal se fará a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'O que fere algum animal, há de restituí-lo; mas o que fere de morte a um homem, que morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Um mesmo regulamento tereis: como o estrangeiro, assim será o natural: porque eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'E falou Moisés aos filhos de Israel, e eles tiraram ao blasfemo fora do acampamento, e apedrejaram-no com pedras. E os filhos de Israel fizeram segundo que o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'E o SENHOR falou a Moisés no monte Sinai, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra que eu vos dou, a terra fará sábado ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Seis anos semearás tua terra, e seis anos podarás tua vinha, e colherás seus frutos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'E no sétimo ano a terra terá sábado de descanso, sábado ao SENHOR: não semearás tua terra, nem podarás tua vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'O que de seu se nascer em tua terra ceifada, não o ceifarás; e as uvas de teu vinhedo não vindimarás: ano de descanso será à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Mas o sábado da terra vos será para comer a ti, e a teu servo, e a tua serva, e a tua criado, e a tua estrangeiro que morar contigo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'E a teu animal, e à animal que houver em tua terra, será todo o fruto dela para comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'E te hás de contar sete semanas de anos, sete vezes sete anos; de modo que os dias das sete semanas de anos virão a ser para ti quarenta e nove anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Então farás passar a trombeta de júbilo no mês sétimo aos dez do mês; o dia da expiação fareis passar a trombeta por toda vossa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'E santificareis o ano cinquenta, e apregoareis liberdade na terra a todos os seus moradores: este vos será jubileu; e voltareis cada um à sua possessão, e cada qual voltará à sua família.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'O ano dos cinquenta anos vos será jubileu: não semeareis, nem colhereis o que nascer de seu na terra, nem vindimareis seus vinhedos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Porque é jubileu: santo será a vós; o produto da terra comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Em este ano de jubileu voltareis cada um à sua possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'E quando venderdes algo a vosso próximo, ou comprardes da mão de vosso próximo, não engane ninguém a seu irmão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Conforme o número dos anos depois do jubileu comprarás de teu próximo; conforme o número dos anos dos frutos te venderá ele a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Conforme a abundância dos anos aumentarás o preço, e conforme a diminuição dos anos diminuirás o preço; porque segundo o número dos rendimentos te há de vender ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'E não engane ninguém a seu próximo; mas terás temor de teu Deus: porque eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Executai, pois, meus estatutos, e guardai meus regulamentos, e ponde-os por obra, e habitareis na terra seguros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'E a terra dará seu fruto, e comereis até fartura, e habitareis nela com segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'E se disserdes: Que comeremos no sétimo ano? eis que não temos de semear, nem temos de colher nossos frutos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Então eu vos enviarei minha bênção no sexto ano, e fará fruto por três anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'E semeareis no ano oitavo, e comereis do fruto alheio; até o ano nono, até que venha seu fruto comereis do alheio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'E a terra não se venderá definitivamente, porque a terra minha é; que vós peregrinos e estrangeiros sois para comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Portanto, em toda a terra de vossa possessão, outorgareis remissão à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Quando teu irmão empobrecer, e vender algo de sua possessão, virá o resgatador, seu próximo, e resgatará o que seu irmão houver vendido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'E quando o homem não tiver resgatador, se alcançar sua mão, e achar o que basta para seu resgate;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Então contará os anos de sua venda, e pagará o que restar ao homem a quem vendeu, e voltará à sua possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mas se não alcançar sua mão o que basta para que volte a ele, o que vendeu estará em poder do que o comprou até o ano do jubileu; e ao jubileu sairá, e ele voltará à sua possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'E o homem que vender casa de morada em cidade cercado, poderá resgatá-la até acabar-se o ano de sua venda: ano será o termo de se poder resgatar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'E se não for resgatada dentro de ano inteiro, a casa que estiver na cidade murada ficará para sempre por daquele que a comprou, e para seus descendentes: não sairá no jubileu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mas as casas das aldeias que não têm muro ao redor, serão estimadas como uma plantação da terra: terão remissão, e sairão no jubileu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Porém em quanto às cidades dos levitas, sempre poderão resgatar os levitas as casas das cidades que possuírem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'E o que comprar dos levitas, sairá da casa vendida, ou da cidade de sua possessão, no jubileu: porquanto as casas das cidades dos levitas é a possessão deles entre os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Mas a terra dos arredores de suas cidades não se venderá, porque é perpétua possessão deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'E quando teu irmão empobrecer, e se refugiar a ti, tu o ampararás: como peregrino e estrangeiro viverá contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Não tomarás juros dele, nem lucro; mas terás temor de teu Deus, e teu irmão viverá contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Não lhe darás teu dinheiro a juros, nem tua comida a ganho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito, para vos dar a terra de Canaã, para ser vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'E quando teu irmão empobrecer, estando contigo, e se vender a ti, não lhe farás servir como servo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Como criado, como estrangeiro estará contigo; até o ano do jubileu te servirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Então sairá de tua presença, ele e seus filhos consigo, e voltará à sua família, e à possessão de seus pais se restituirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Porque são meus servos, os quais tirei eu da terra do Egito: não serão vendidos à maneira de servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Não serás senhor dele com dureza, mas terás temor de teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Assim teu servo como tua serva que tiveres, serão das nações que estão em vosso ao redor: deles comprareis servos e servas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Também comprareis dos filhos dos forasteiros que vivem entre vós, e dos que da linhagem deles são nascidos em vossa terra, que estão convosco; os quais tereis por possessão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'E os possuireis por herança para vossos filhos depois de vós, como possessão hereditária; para sempre vos servireis deles; porém em vossos irmãos os filhos de Israel, não vos dominareis cada um sobre seu irmão com dureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'E se o peregrino ou estrangeiro que está contigo, adquirisse meios, e teu irmão que está com ele empobrecer, e se vender ao peregrino ou estrangeiro que está contigo, ou à raça da família do estrangeiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Depois que se houver vendido, poderá ser resgatado: um de seus irmãos o resgatará;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Ou seu tio, ou o filho de seu tio o resgatará, ou o próximo de sua carne, de sua linhagem, o resgatará; ou se seus meios alcançarem, ele mesmo se resgatará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'E contará com o que o comprou, desde o ano que se vendeu a ele até o ano do jubileu: e há de estabelecer preço o dinheiro de sua venda conforme o número dos anos, e se fará com ele conforme o tempo de um criado assalariado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Se ainda forem muitos anos, conforme eles voltará para seu resgate do dinheiro pelo qual se vendeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'E se restar pouco tempo até o ano do jubileu, então contará com ele, e devolverá seu resgate conforme seus anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Como com tomado a salário anualmente fará com ele: não será senhor dele com aspereza diante de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Mas se não se resgatar em esses anos, no ano do jubileu sairá, ele, e seus filhos com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Porque meus servos são os filhos de Israel; são servos meus, aos quais tirei da terra do Egito: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Não fareis para vós ídolos, nem escultura, nem levantareis para vós estátua, nem poreis em vossa terra pedra pintada para inclinar-vos a ela: porque eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Guardai meus sábados, e tende em reverência meu santuário: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Se andardes em meus decretos, e guardardes meus mandamentos, e os puserdes por obra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Eu darei vossa chuva em seu tempo, e a terra produzirá, e a árvore do campo dará seu fruto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'E a debulha vos alcançará à vindima, e a vindima alcançará à sementeira, e comereis vosso pão em fartura e habitareis seguros em vossa terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'E eu darei paz na terra, e dormireis, e não haverá quem vos espante: e farei tirar os animais ferozes de vossa terra, e não passará por vosso país a espada:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'E perseguireis a vossos inimigos, e cairão à espada diante de vós:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'E cinco de vós perseguirão a cem, e cem de vós perseguirão a dez mil, e vossos inimigos cairão à espada diante de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Porque eu me voltarei a vós, e vos farei crescer, e vos multiplicarei, e afirmarei meu pacto convosco:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'E comereis o antigo de muito tempo, e tirareis fora o antigo por causa do novo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'E porei minha morada em meio de vós, e minha alma não vos abominará:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'E andarei entre vós, e eu serei vosso Deus, e vós sereis meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito, para que não fôsseis seus servos; e rompi as barras de vosso jugo, e vos fiz andar com o rosto alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Porém se não me ouvirdes, nem fizerdes todos estes meus mandamentos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'E se abominardes meus decretos, e vossa alma menosprezar meus regulamentos, não executando todos meus mandamentos, e invalidando meu pacto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Eu também farei convosco isto: enviarei sobre vós terror, enfermidade e febre, que consumam os olhos e atormentem a alma: e semeareis em vão vossa semente, porque vossos inimigos a comerão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'E porei minha ira sobre vós, e sereis feridos diante de vossos inimigos; e os que vos aborrecem vos dominarão, e fugireis sem que haja quem vos persiga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'E se ainda com estas coisas não me ouvirdes, eu voltarei a castigar-vos sete vezes mais por vossos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'E quebrarei a soberba de vossa força, e voltarei vosso céu como ferro, e vossa terra como bronze:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'E vossa força se consumirá em vão; que vossa terra não dará seu produto, e as árvores da terra não darão seu fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'E se andardes comigo em oposição, e não me quiserdes ouvir, eu acrescentarei sobre vós sete vezes mais pragas segundo vossos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Enviarei também contra vós animais feras que vos arrebatem os filhos, e destruam vossos animais, e vos reduzam a poucos, e vossos caminhos sejam desertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'E se com estas coisas não fordes corrigidos, mas que andardes comigo em oposição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Eu também procederei convosco, em oposição e vos ferirei ainda sete vezes por vossos pecados:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'E trarei sobre vós espada vingadora, em castigo do pacto; e vos recolhereis a vossas cidades; mas eu enviarei pestilência entre vós, e sereis entregues em mão do inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Quando eu vos quebrantar o sustento de pão, cozerão dez mulheres vosso pão em um forno, e vos devolverão vosso pão por peso; e comereis, e não vos fartareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'E se com isto não me ouvirdes, mas procederdes comigo em oposição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Eu procederei convosco em contra e com ira, e vos castigarei ainda sete vezes por vossos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'E comereis as carnes de vossos filhos, e comereis as carnes de vossas filhas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'E destruirei vossos altos, e exterminarei vossas imagens, e porei vossos corpos mortos sobre os corpos mortos de vossos ídolos, e meu alma vos abominará:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'E porei vossas cidades em deserto, e assolarei vossos santuários, e não cheirarei a fragrância de vosso suave incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Eu assolarei também a terra, e se pasmarão dela vossos inimigos que nela moram:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'E a vós vos espalharei pelas nações, e desembainharei espada atrás de vós: e vossa terra estará assolada, e desertas vossas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Então a terra folgará seus sábados todos os dias que estiver assolada, e vós na terra de vossos inimigos: a terra descansará então e desfrutará seus sábados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Todo o tempo que estará assolada, folgará o que não folgou em vossos sábados enquanto habitáveis nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'E aos que restarem de vós porei em seus corações tal covardia, na terra de seus inimigos, que o som de uma folha movida os perseguirá, e fugirão como de espada, e cairão sem que ninguém os persiga:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'E tropeçarão uns nos outros, como se fugissem diante de espada, ainda que ninguém os persiga; e não podereis resistir diante de vossos inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'E perecereis entre as nações, e a terra de vossos inimigos vos consumirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'E os que restarem de vós perecerão nas terras de vossos inimigos por sua iniquidade; e pela iniquidade de seus pais perecerão com eles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'E confessarão sua iniquidade, e a iniquidade de seus pais, por sua transgressão com que transgrediram contra mim: e também porque andaram comigo em oposição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Eu também houver andado contrário a eles, e os houver metido na terra de seus inimigos: e então se humilhará seu coração incircunciso, e reconhecerão seu pecado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'E eu me lembrarei de meu pacto com Jacó, e também de meu pacto com Isaque, e também de meu pacto com Abraão me lembrarei; e farei memória da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Que a terra estará desamparada deles, e folgará seus sábados, estando deserta por causa deles; mas entretanto se submeterão ao castigo de suas iniquidades: porquanto menosprezaram meus regulamentos, e teve a alma deles ódio de meus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'E ainda com tudo isto, estando eles em terra de seus inimigos, eu não os rejeitarei, nem os abominarei para consumi-los, invalidando meu pacto com eles: porque eu o SENHOR sou seu Deus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Antes me lembrarei deles pelo pacto antigo, quando os tirei da terra do Egito aos olhos das nações, para ser seu Deus: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Estes são os decretos, regulamentos e leis que estabeleceu o SENHOR entre si e os filhos de Israel no monte Sinai por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando alguém fizer especial voto ao SENHOR, segundo a avaliação das pessoas que se hajam de resgatar, assim será tua avaliação:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Em quanto ao homem de vinte anos até sessenta, tua avaliação será cinquenta siclos de prata, segundo o siclo do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'E se for fêmea, a avaliação será trinta siclos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'E se for de cinco anos até vinte, tua avaliação será respeito ao homem vinte siclos, e à fêmea dez siclos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'E se for de um mês até cinco anos, tua avaliação será em ordem ao homem, cinco siclos de prata; e pela fêmea será tua avaliação três siclos de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Mas se for de sessenta anos acima, pelo homem tua avaliação será quinze siclos, e pela fêmea dez siclos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Porém se for mais pobre que tua avaliação, então comparecerá ante o sacerdote, e o sacerdote lhe porá valor: conforme a capacidade do votante lhe imporá valor o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'E se for animal de que se oferece oferta ao SENHOR, tudo o que se der dele ao SENHOR será santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Não será mudado nem trocado, bom por mau, nem mau por bom; e se se permutar um animal por outro, ele e o dado por ele em troca serão sagrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'E se for algum animal impuro, de que não se oferece oferta ao SENHOR, então o animal será posto diante do sacerdote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'E o sacerdote o avaliará preço, seja bom ou seja mau; conforme a avaliação do sacerdote, assim será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'E se o houverem de resgatar, acrescentarão seu quinto sobre tua avaliação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'E quando alguém santificar sua casa consagrando-a ao SENHOR, a avaliará preço o sacerdote, seja boa ou seja má: segundo a avaliar o sacerdote, assim ficará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mas se o que a santificar resgatar sua casa, acrescentará à tua avaliação o quinto do dinheiro dela, e será sua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'E se alguém santificar da terra de sua possessão ao SENHOR, tua avaliação será conforme sua semeadura: um ômer de semeadura de cevada se avaliará preço em cinquenta siclos de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'E se santificar sua terra desde o ano do jubileu, conforme tua avaliação ficará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mas se depois do jubileu santificar sua terra, então o sacerdote fará a conta do dinheiro conforme os anos que restarem até o ano do jubileu, e se diminuirá de tua avaliação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'E se o que santificou a terra quiser resgatá-la, acrescentará à tua avaliação o quinto do dinheiro dela, e ficará para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Mas se ele não resgatar a terra, e a terra se vender a outro, não a resgatará mais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Em vez disso quando sair no jubileu, a terra será santa ao SENHOR, como terra consagrada: a possessão dela será do sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'E se santificar alguém ao SENHOR a terra que ele comprou, que não era da terra de sua herança,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Então o sacerdote calculará com ele a soma de tua avaliação até o ano do jubileu, e aquele dia dará teu assinalado preço, coisa consagrada ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'No ano do jubileu, voltará a terra a aquele de quem ele a comprou, cuja é a herança da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'E tudo o que avaliares o preço será conforme o siclo do santuário: o siclo tem vinte óbolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Porém o primogênito dos animais, que pela primogenitura é do SENHOR, ninguém o santificará; seja boi ou ovelha, do SENHOR é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Mas se for dos animais impuros, o resgatarão conforme tua avaliação, e acrescentarão sobre ela seu quinto: e se não o resgatarem, se venderá conforme tua avaliação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Porém nenhuma coisa consagrada, que alguém houver santificado ao SENHOR de tudo o que tiver, de homens e animais, e das terras de sua possessão, não se venderá, nem se resgatará: todo o consagrado será coisa santíssima ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Qualquer um que for consagrado dentre o homens que for separado para a condenação não será resgatado; inevitavelmente será morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'E todos os dízimos da terra, tanto das sementes da terra como dos frutos das árvores, pertencem ao SENHOR; são coisas consagradas ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'E se alguém quiser resgatar algo de seus dízimos, acrescentará seu quinto a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'E todo dízimo de vacas ou de ovelhas, de tudo o que passa sob a vara, a décima parte será consagrada ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Não olhará se é bom ou mau, nem o trocará; e se o trocar, ele e o seu trocado serão consagrados; não se resgatará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Esses são os mandamentos que o SENHOR ordenou a Moisés para os filhos de Israel, no monte Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'E falou o SENHOR a Moisés no deserto de Sinai, no tabernáculo do testemunho, no primeiro dia do mês segundo, no segundo ano de sua saída da terra do Egito, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Tomai o censo de toda a congregação dos filhos de Israel por suas famílias, pelas casas de seus pais, com a conta dos nomes, todos os homens por suas cabeças:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'De vinte anos acima, todos os que podem sair à guerra em Israel, os contareis tu e Arão por suas tropas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'E estará convosco um homem de cada tribo, cada um chefe da casa de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'E estes são os nomes dos homens que estarão convosco: Da tribo de Rúben, Elizur filho de Sedeur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'De Simeão, Selumiel filho de Zurisadai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'De Judá, Naassom filho de Aminadabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'De Issacar, Natanael filho de Zuar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'De Zebulom, Eliabe filho de Helom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Dos filhos de José: de Efraim, Elisama filho de Amiúde; de Manassés, Gamaliel filho de Pedazur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'De Benjamim, Abidã filho de Gideoni.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'De Dã, Aiezer filho de Amisadai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'De Aser, Pagiel filho de Ocrã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'De Gade, Eliasafe filho de Deuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'De Naftali, Aira filho de Enã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Estes foram os nomeados da congregação, príncipes das tribos de seus pais, capitães dos milhares de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Tomou pois Moisés e Arão a estes homens que foram declarados por seus nomes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'E juntaram toda a congregação no primeiro dia do mês segundo, e foram reunidos suas linhagens, pelas casas de seus pais, segundo a conta dos nomes, de vinte anos acima, por suas cabeças,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Como o SENHOR o havia mandado a Moisés; e contou-os no deserto de Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'E os filhos de Rúben, primogênito de Israel, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes por suas cabeças, todos os homens de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Os contados deles, da tribo de Rúben, foram quarenta e seis mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Dos filhos de Simeão, por suas gerações, por suas famílias, pelas casas de seus pais, os contados deles conforme a conta dos nomes por suas cabeças, todos os homens de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Os contados deles, da tribo de Simeão, cinquenta e nove mil e trezentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Dos filhos de Gade, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Os contados deles, da tribo de Gade, quarenta e cinco mil seiscentos e cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Dos filhos de Judá, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Os contados deles, da tribo de Judá, setenta e quatro mil e seiscentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Dos filhos de Issacar, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Os contados deles, da tribo de Issacar, cinquenta e quatro mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Dos filhos de Zebulom, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta de seus nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Os contados deles, da tribo de Zebulom, cinquenta e sete mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Dos filhos de José: dos filhos de Efraim, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Os contados deles, da tribo de Efraim, quarenta mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Dos filhos de Manassés, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Os contados deles, da tribo de Manassés, trinta e dois mil e duzentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Dos filhos de Benjamim, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Os contados deles, da tribo de Benjamim, trinta e cinco mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Dos filhos de Dã, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Os contados deles, da tribo de Dã, sessenta e dois mil e setecentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Dos filhos de Aser, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Os contados deles, da tribo de Aser, quarenta e um mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Dos filhos de Naftali, por suas gerações, por suas famílias, pelas casas de seus pais, conforme a conta dos nomes, de vinte anos acima, todos os que podiam sair à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Os contados deles, da tribo de Naftali, cinquenta e três mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Estes foram os contados, os quais contaram Moisés e Arão, com os príncipes de Israel, que eram doze, um por cada casa de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'E foram todos os contados dos filhos de Israel pelas casas de seus pais, de vinte anos acima, todos os que podiam sair à guerra em Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Foram todos os contados seiscentos três mil quinhentos e cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Porém os levitas não foram contados entre eles segundo a tribo de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Porque falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Somente não contarás a tribo de Levi, nem tomarás a conta deles entre os filhos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Mas tu porás aos levitas no tabernáculo do testemunho, e sobre todos os seus utensílios, e sobre todas as coisas que lhe pertencem: eles levarão o tabernáculo e todos os seus utensílios, e eles servirão nele, e assentarão suas tendas ao redor do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'E quando o tabernáculo partir, os levitas o desarmarão; e quando o tabernáculo parar, os levitas o armarão: e o estranho que se chegar, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'E os filhos de Israel assentarão suas tendas cada um em seu esquadrão, e cada um junto à sua bandeira, por suas tropas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mas os levitas assentarão as suas ao redor do tabernáculo do testemunho, e não haverá ira sobre a congregação dos filhos de Israel: e os levitas terão a guarda do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'E fizeram os filhos de Israel conforme todas as coisas que mandou o SENHOR a Moisés; assim o fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Os filhos de Israel acamparão cada um junto à sua bandeira, segundo as insígnias das casas de seus pais; ao redor do tabernáculo do testemunho acamparão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Estes acamparão ao levante, ao oriente: a bandeira do exército de Judá, por seus esquadrões; e o chefe dos filhos de Judá, Naassom filho de Aminadabe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Seu exército, com os contados deles, setenta e quatro mil e seiscentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Junto a ele acamparão os da tribo de Issacar: e o chefe dos filhos de Issacar, Natanael filho de Zuar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'E seu exército, com seus contados, cinquenta e quatro mil e quatrocentos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'E a tribo de Zebulom: e o chefe dos filhos de Zebulom, Eliabe filho de Helom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'E seu exército, com seus contados, cinquenta e sete mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Todos os contados no exército de Judá, cento e oitenta e seis mil e quatrocentos, por seus esquadrões, irão diante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'A bandeira do exército de Rúben ao sul, por seus esquadrões: e o chefe dos filhos de Rúben, Elizur filho de Sedeur;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'E seu exército, seus contados, quarenta e seis mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'E acamparão junto a ele os da tribo de Simeão: e o chefe dos filhos de Simeão, Selumiel filho de Zurisadai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'E seu exército, com os contados deles, cinquenta e nove mil e trezentos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'E a tribo de Gade: e o chefe dos filhos de Gade, Eliasafe filho de Reuel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'E seu exército, com os contados deles, quarenta e cinco mil seiscentos e cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Todos os contados no exército de Rúben, cento cinquenta e um mil quatrocentos e cinquenta, por seus esquadrões, irão na segunda posição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Logo irá o tabernáculo do testemunho, o acampamento dos levitas em meio dos exércitos: da maneira que assentam o acampamento, assim caminharão, cada um em seu lugar, junto a suas bandeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'A bandeira do exército de Efraim por seus esquadrões, ao ocidente: e o chefe dos filhos de Efraim, Elisama filho de Amiúde;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'E seu exército, com os contados deles, quarenta mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Junto a ele estará a tribo de Manassés; e o chefe dos filhos de Manassés, Gamaliel filho de Pedazur;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'E seu exército, com os contados deles, trinta e dois mil e duzentos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'E a tribo de Benjamim: e o chefe dos filhos de Benjamim, Abidã filho de Gideoni;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'E seu exército, com os contados deles, trinta e cinco mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Todos os contados no exército de Efraim, cento e oito mil e cem, por seus esquadrões, irão na terceira posição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'A bandeira do exército de Dã estará ao norte, por seus esquadrões: e o chefe dos filhos de Dã, Aiezer filho de Amisadai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'E seu exército, com os contados deles, sessenta e dois mil e setecentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Junto a ele acamparão os da tribo de Aser: e o chefe dos filhos de Aser, Pagiel filho de Ocrã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'E seu exército, com os contados deles, quarenta e um mil e quinhentos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'E a tribo de Naftali: e o chefe dos filhos de Naftali, Aira filho de Enã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'E seu exército, com os contados deles, cinquenta e três mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Todos os contados no exército de Dã, cento cinquenta e sete mil e seiscentos: irão os últimos atrás de suas bandeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Estes são os contados dos filhos de Israel, pelas casas de seus pais: todos os contados por exércitos, por seus esquadrões, seiscentos três mil quinhentos e cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mas os levitas não foram contados entre os filhos de Israel; como o SENHOR o mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'E fizeram os filhos de Israel conforme todas as coisas que o SENHOR mandou a Moisés; assim assentaram o acampamento por suas bandeiras, e assim marcharam cada um por suas famílias, segundo as casas de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'E estas são as gerações de Arão e de Moisés, desde que o SENHOR falou a Moisés no monte Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'E estes são os nomes dos filhos de Arão: Nadabe o primogênito, e Abiú, Eleazar, e Itamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Estes são os nomes dos filhos de Arão, sacerdotes ungidos; cujas mãos ele encheu para administrar o sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mas Nadabe e Abiú morreram diante do SENHOR, quando ofereceram fogo estranho diante do SENHOR, no deserto de Sinai: e não tiveram filhos: e Eleazar e Itamar exerceram o sacerdócio diante de Arão seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Faze chegar à tribo de Levi, e faze-a estar diante do sacerdote Arão, para que lhe ministrem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'E desempenhem seu cargo, e o cargo de toda a congregação diante do tabernáculo do testemunho, para servir no ministério do tabernáculo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'E guardem todos os móveis do tabernáculo do testemunho, e o encarregado a eles dos filhos de Israel, e ministrem no serviço do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'E darás os levitas a Arão e a seus filhos: são inteiramente dados a eles dentre os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'E constituirás a Arão e a seus filhos, para que exerçam seu sacerdócio: e o estranho que se chegar, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'E eis que eu tomei os levitas dentre os filhos de Israel em lugar de todos os primogênitos que abrem a madre entre os filhos de Israel; serão, pois, meus os levitas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Porque meu é todo primogênito; desde o dia que eu matei todos os primogênitos na terra do Egito, eu santifiquei a mim todos os primogênitos em Israel, tanto de homens como de animais; meus serão; Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'E o SENHOR falou a Moisés no deserto de Sinai, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Conta os filhos de Levi pelas casas de seus pais, por suas famílias: contarás todos os homens de um mês acima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'E Moisés os contou conforme a palavra do SENHOR, como lhe foi mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'E os filhos de Levi foram estes por seus nomes: Gérson, e Coate, e Merari.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'E os nomes dos filhos de Gérson, por suas famílias, estes: Libni, e Simei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'E os filhos de Coate, por suas famílias: Anrão, e Izar, e Hebrom, e Uziel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'E os filhos de Merari, por suas famílias: Mali, e Musi. Estas, as famílias de Levi, pelas casas de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gérson, a família de Libni e a de Simei: estas são as famílias de Gérson.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Os contados deles conforme a conta de todos os homens de um mês acima, os contados deles, sete mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'As famílias de Gérson assentarão suas tendas à retaguarda do tabernáculo, ao ocidente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'E o chefe da casa do pai dos gersonitas, Eliasafe filho de Lael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A cargo dos filhos de Gérson, no tabernáculo do testemunho, estará o tabernáculo, e a tenda, e sua cobertura, e a cortina da porta do tabernáculo do testemunho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'E as cortinas do átrio, e a cortina da porta do átrio, que está junto ao tabernáculo e junto ao altar ao redor; também suas cordas para todo seu serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'E de Coate, a família dos anramitas, e a família dos izaritas, e a família dos hebronitas, e a família dos uzielitas: estas são as famílias coatitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Pela conta de todos os homens de um mês acima, eram oito mil e seiscentos, que tinham a guarda do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'As famílias dos filhos de Coate acamparão ao lado do tabernáculo, ao sul;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'E o chefe da casa do pai das famílias de Coate, Elisafã filho de Uziel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'E a cargo deles estará a arca, e a mesa, e o candelabro, e os altares, e os utensílios do santuário com que ministram, e o véu, com todo seu serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'E o principal dos chefes dos levitas será Eleazar, filho de Arão o sacerdote, supervisor dos que têm a guarda do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Merari, a família dos malitas e a família dos musitas: estas são as famílias de Merari.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'E os contados deles conforme a conta de todos os homens de um mês acima, foram seis mil e duzentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'E o chefe da casa do pai das famílias de Merari, Zuriel filho de Abiail: acamparão ao lado do tabernáculo, ao norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'E a cargo dos filhos de Merari estará a custódia das tábuas do tabernáculo, e suas barras, e suas colunas, e suas bases, e todos os seus utensílios, com todo seu serviço:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'E as colunas em derredor do átrio, e suas bases, e suas estacas, e suas cordas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'E os que acamparão diante do tabernáculo ao oriente, diante do tabernáculo do testemunho ao levante, serão Moisés, e Arão e seus filhos, tendo a guarda do santuário em lugar dos filhos de Israel: e o estranho que se aproximar, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Todos os contados dos levitas, que Moisés e Arão conforme a palavra do SENHOR contaram por suas famílias, todos os homens de um mês acima, foram vinte e dois mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'E o SENHOR disse a Moisés: Conta todos os primogênitos homens dos filhos de Israel de um mês acima, e toma a conta dos nomes deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'E tomarás os levitas para mim, eu o SENHOR, em lugar de todos os primogênitos dos filhos de Israel: e os animais dos levitas em lugar de todos os primogênitos dos animais dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'E contou Moisés, como o SENHOR lhe mandou, todos os primogênitos dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'E todos os primogênitos homens, conforme a conta dos nomes, de um mês acima, os contados deles foram vinte e dois mil duzentos setenta e três.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Toma os levitas em lugar de todos os primogênitos dos filhos de Israel, e os animais dos levitas em lugar de seus animais; e os levitas serão meus: Eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'E pelos resgates dos duzentos e setenta e três, que excedem aos levitas os primogênitos dos filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Tomarás cinco siclos por cabeça; conforme o siclo do santuário tomarás: o siclo tem vinte óbolos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'E darás a Arão e a seus filhos o dinheiro pelos resgates dos que deles sobram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Tomou, pois, Moisés o dinheiro do resgate dos que resultaram a mais dos resgatados pelos levitas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'E recebeu dos primogênitos dos filhos de Israel em dinheiro, mil trezentos sessenta e cinco siclos, conforme o siclo do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'E Moisés deu o dinheiro dos resgates a Arão e a seus filhos, conforme o dito do SENHOR, segundo que o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Toma a conta dos filhos de Coate dentre os filhos de Levi, por suas famílias, pelas casas de seus pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'De idade de trinta anos acima até cinquenta anos, todos os que entram em companhia, para fazer serviço no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Este será o ofício dos filhos de Coate no tabernáculo do testemunho, no lugar santíssimo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Quando se houver de mudar o acampamento, virão Arão e seus filhos, e desarmarão o véu da tenda, e cobrirão com ele a arca do testemunho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'E porão sobre ela a coberta de peles finas, e estenderão encima o pano todo de azul, e lhe porão suas varas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'E sobre a mesa da proposição estenderão o pano azul, e porão sobre ela os pratos, e as colheres, e os copos, e as taças para fazer libações: e o pão contínuo estará sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'E estenderão sobre ela o pano de carmesim colorido, e o cobrirão com a coberta de peles finas; e lhe porão suas varas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'E tomarão um pano azul, e cobrirão o candelabro da luminária; e suas lâmpadas, e suas tenazes, e seus apagadores, e todos os seus vasos do azeite com que se serve;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'E o porão com todos os seus utensílios em uma coberta de peles finos, e o colocarão sobre umas armações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'E sobre o altar de ouro estenderão o pano azul, e lhe cobrirão com a coberta de peles finas, e lhe porão suas varas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'E tomarão todos os vasos do serviço, de que fazem uso no santuário, e os porão em um pano azul, e os cobrirão com uma coberta de peles finas, e os colocarão sobre umas armações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'E tirarão a cinza do altar, e estenderão sobre ele um pano de púrpura:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'E porão sobre ele todos os seus instrumentos de que se serve: as pás, os garfos, os braseiros, e as taças, todos os utensílios do altar; e estenderão sobre ele o propiciatório de peles finas, e lhe porão também as varas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'E em acabando Arão e seus filhos de cobrir o santuário e todos os vasos do santuário, quando o acampamento se houver de mudar, virão depois disso os filhos de Coate para conduzir: mas não tocarão coisa santa, que morrerão. Estas serão as cargas dos filhos de Coate no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Porém ao cargo de Eleazar, filho de Arão o sacerdote, estará o azeite da luminária, e o incenso aromático, e a oferta de cereais contínua, e o azeite da unção; o cargo de todo o tabernáculo, e de tudo o que está nele, no santuário, e em seus utensílios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'E falou o SENHOR a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Não cortareis a tribo das famílias de Coate dentre os levitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Mas isto fareis com eles, para que vivam, e não morram quando achegarem ao lugar santíssimo: Arão e seus filhos virão e os porão a cada um em seu ofício, e em seu cargo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Não entrarão para ver, quando cobrirem as coisas santas; que morrerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'E falou o SENHOR a Moisés dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Toma também a conta dos filhos de Gérson pelas casas de seus pais, por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'De idade de trinta anos acima até cinquenta anos os contarás; todos os que entram em companhia, para fazer serviço no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Este será o ofício das famílias de Gérson, para ministrar e para levar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Levarão as cortinas do tabernáculo, e o tabernáculo do testemunho, sua coberta, e a coberta de peles finas que está sobre ele encima, e a cortina da porta do tabernáculo do testemunho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'E as cortinas do átrio, e a cortina da porta do átrio, que está próxima do tabernáculo e próxima do altar ao redor, e suas cordas, e todos os instrumentos de seu serviço, e tudo o que será feito para eles: assim servirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Segundo a ordem de Arão e de seus filhos será todo o ministério dos filhos de Gérson em todos os seus cargas, e em todo o seu serviço: e lhes atribuireis em responsabilidade todas as suas cargas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Este é o serviço das famílias dos filhos de Gérson no tabernáculo do testemunho: e a responsabilidade deles estará sob a mão de Itamar, filho de Arão o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Contarás os filhos de Merari por suas famílias, pelas casas de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Desde o de idade de trinta anos acima até o de cinquenta anos, os contarás; todos os que entram em companhia, para fazer serviço no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'E este será o dever de seu cargo para todo seu serviço no tabernáculo do testemunho: as tábuas do tabernáculo, e suas barras, e suas colunas, e suas bases,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'E as colunas do átrio ao redor, e suas bases, e suas estacas, e suas cordas com todos os seus instrumentos, e todo seu serviço; e contareis por seus nomes todos os vasos da guarda de seu cargo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Este será o serviço das famílias dos filhos de Merari para todo seu ministério no tabernáculo do testemunho, sob a mão de Itamar, filho de Arão o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Moisés, pois, e Arão, e os chefes da congregação, contaram os filhos de Coate por suas famílias, e pelas casas de seus pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos; todos os que entram em companhia, para ministrar no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'E foram os contados deles por suas famílias, dois mil setecentos e cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Estes foram os contados das famílias de Coate, todos os que ministram no tabernáculo do testemunho, os quais contaram Moisés e Arão, como o mandou o SENHOR por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'E os contados dos filhos de Gérson, por suas famílias, e pelas casas de seus pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos, todos os que entram em companhia, para ministrar no tabernáculo do testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Os contados deles por suas famílias, pelas casas de seus pais, foram dois mil seiscentos e trinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Estes são os contados das famílias dos filhos de Gérson, todos os que ministram no tabernáculo do testemunho, os quais contaram Moisés e Arão por ordem do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'E os contados das famílias dos filhos de Merari, por suas famílias, pelas casas de seus pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos, todos os que entram em companhia, para ministrar no tabernáculo do testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Os contados deles, por suas famílias, foram três mil e duzentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Estes foram os contados das famílias dos filhos de Merari, os quais contaram Moisés e Arão, segundo o mandou o SENHOR por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Todos os contados dos levitas, que Moisés e Arão e os chefes de Israel contaram por suas famílias, e pelas casas de seus pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Desde o de idade de trinta anos acima até o de idade de cinquenta anos, todos os que entravam para ministrar no serviço, e ter cargo de obra no tabernáculo do testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Os contados deles foram oito mil quinhentos e oitenta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Como o mandou o SENHOR por meio de Moisés foram contados, cada um segundo seu ofício, e segundo seu cargo; os quais contou ele, como lhe foi mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Manda aos filhos de Israel que expulsem do acampamento a todo leproso, e a todos os que sofrem de corrimento, e a todo contaminado sobre morto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Tanto homens como mulheres lançareis, fora do acampamento os expulsareis; para que não contaminem o acampamento daqueles entre os quais eu habito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'E fizeram-no assim os filhos de Israel, que os lançaram fora do acampamento: como o SENHOR disse a Moisés, assim o fizeram os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Também falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Fala aos filhos de Israel: O homem ou a mulher que cometer algum de todos os pecados dos homens, fazendo transgressão contra o SENHOR, e transgredir aquela pessoa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Confessarão seu pecado que cometeram, e compensarão sua ofensa inteiramente, e acrescentarão seu quinto sobre ele, e o darão a aquele contra quem pecaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'E se aquele homem não tiver parente ao qual seja ressarcida a ofensa, se dará a indenização da injustiça ao SENHOR, ao sacerdote, a mais do carneiro das expiações, com o qual fará expiação por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'E toda oferta de todas as coisas santas que os filhos de Israel apresentarem ao sacerdote, sua será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'E o santificado de qualquer um será seu: também o que qualquer um der ao sacerdote, seu será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Fala aos filhos de Israel, e dize-lhes: Quando a mulher de alguém se desviar, e fizer traição contra ele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Que alguém se houver deitado com ela em carnal ajuntamento, e seu marido não o houvesse visto por haver-se ela contaminado ocultamente, nem houver testemunha contra ela, nem ela houver sido pega no ato;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Se vier sobre ele espírito de ciúme, e tiver ciúmes de sua mulher, havendo-se ela contaminado; ou vier sobre ele espírito de ciúme, e tiver ciúmes de sua mulher, não havendo ela se contaminado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Então o marido trará sua mulher ao sacerdote, e trará sua oferta com ela, a dízima de um efa de farinha de cevada; não lançará sobre ela azeite, nem porá sobre ela incenso: porque é presente de ciúmes, presente de recordação, que traz o pecado em memória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'E o sacerdote a fará aproximar, e a fará pôr diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Logo tomará o sacerdote da água santa em um vaso de barro: tomará também o sacerdote do pó que houver no chão do tabernáculo, e o lançará na água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'E fará o sacerdote estar em pé à mulher diante do SENHOR, e descobrirá a cabeça da mulher, e porá sobre suas mãos o presente da recordação, que é o presente de ciúmes: e o sacerdote terá na mão as águas amargas que trazem maldição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'E o sacerdote a fará jurar, e lhe dirá: Se ninguém houver dormido contigo, e se não te afastaste de teu marido à imundícia, livre sejas destas águas amargas que trazem maldição:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mas se te desviaste de teu marido, e te contaminaste, e alguém houver tido relação contigo, fora de teu marido:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '(O sacerdote fará jurar à mulher com juramento de maldição, e dirá à mulher): O SENHOR te dê em maldição e em conspiração em meio de teu povo, fazendo o SENHOR a tua coxa que caia, e a teu ventre que se te inche;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'E estas águas que dão maldição entrem em tuas entranhas, e façam inchar teu ventre, e cair tua coxa. E a mulher dirá: Amém, Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'E o sacerdote escreverá estas maldições em um livro, e as apagará com as águas amargas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'E dará a beber à mulher as águas amargas que trazem maldição; e as águas que operam maldição entrarão nela por amargas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Depois tomará o sacerdote da mão da mulher o presente dos ciúmes, e o moverá diante do SENHOR, e o oferecerá diante do altar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'E tomará o sacerdote um punhado do presente, em memória dela, e o queimará sobre o altar, e depois dará a beber as águas à mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Dará a ela pois a beber as águas; e será, que se for imunda e houver feito traição contra seu marido, as águas que operam maldição entrarão nela em amargura, e seu ventre se inchará, e cairá sua coxa; e a mulher será por maldição em meio de seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mas se a mulher não for imunda, mas sim que estiver limpa, ela será livre, e será fértil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Esta é a lei dos ciúmes, quando a mulher fizer traição a seu marido, e se contaminar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Ou do marido, sobre o qual passar espírito de ciúme, e tiver ciúmes de sua mulher: ele a apresentará então diante do SENHOR, e o sacerdote executará nela toda esta lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'E aquele homem será livre de iniquidade, e a mulher levará seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Fala aos filhos de Israel, e dize-lhes: O homem, ou a mulher, quando se separar fazendo voto de nazireu, para dedicar-se ao SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Se absterá de vinho e de bebida forte; vinagre de vinho, nem vinagre de bebida forte não beberá, nem beberá algum licor de uvas, nem tampouco comerá uvas frescas nem secas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Todo o tempo de seu nazireado, de tudo o que se faz de vide de vinho, desde os caroços até a casca, não comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Todo o tempo do voto de seu nazireado não passará navalha sobre sua cabeça, até que sejam cumpridos os dias de sua separação ao SENHOR: santo será; deixará crescer as pontas do cabelo de sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Todo o tempo que se separar ao SENHOR, não entrará a pessoa morta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Por seu pai, nem por sua mãe, por seu irmão, nem por sua irmã, não se contaminará com eles quando morrerem; porque consagração de seu Deus tem sobre sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Todo o tempo de seu nazireado, será santo ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'E se alguém morrer muito de repente junto a ele, contaminará a cabeça de seu nazireado; portanto o dia de sua purificação rapará sua cabeça; ao sétimo dia a rapará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'E o dia oitavo trará duas rolinhas ou dois pombinhos ao sacerdote, à porta do tabernáculo do testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'E o sacerdote fará um em expiação, e o outro em holocausto: e o expiará do que pecou sobre o morto, e santificará sua cabeça naquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'E consagrará ao SENHOR os dias de seu nazireado, e trará um cordeiro de ano em expiação pela culpa; e os dias primeiros serão anulados, porquanto foi contaminado seu nazireado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Esta é, pois, a lei do nazireu no dia que se cumprir o tempo de seu nazireado: Virá à porta do tabernáculo do testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'E oferecerá sua oferta ao SENHOR, um cordeiro de ano sem mácula em holocausto, e uma cordeira de ano sem defeito em expiação, e um carneiro sem defeito por sacrifício pacífico:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Além disso um cesto de pães ázimos, tortas de flor de farinha amassadas com azeite, e massas não fermentadas untadas com azeite, e sua oferta de cereais, e suas libações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'E o sacerdote o oferecerá diante do SENHOR, e fará sua expiação e seu holocausto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'E oferecerá o carneiro em sacrifício pacífico ao SENHOR, com o cesto dos pães ázimos; oferecerá também o sacerdote sua oferta de cereais, e suas libações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Então o nazireu rapará à porta do tabernáculo do testemunho a cabeça de seu nazireado, e tomará os cabelos da cabeça de seu nazireado, e os porá sobre o fogo que está debaixo do sacrifício pacífico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Depois tomará o sacerdote a coxa cozida do carneiro, e uma torta sem levedura do cesto, e uma massa sem levedura, e as porá sobre as mãos do nazireu, depois que for estragado seu nazireado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'E o sacerdote moverá aquilo, oferta movida diante do SENHOR; o qual será coisa santa do sacerdote, a mais do peito movido e da coxa separada: e depois poderá beber vinho o nazireu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Esta é a lei do nazireu que fizer voto de sua oferta ao SENHOR por seu nazireado, a mais do que sua mão alcançar: segundo o voto que fizer, assim fará, conforme a lei de seu nazireado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Fala a Arão e a seus filhos, e dize-lhes: Assim abençoareis aos filhos de Israel, dizendo-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'O SENHOR te abençoe, e te guarde:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Faça resplandecer o SENHOR seu rosto sobre ti, e tenha de ti misericórdia:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'O SENHOR levante a ti seu rosto, e ponha em ti paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'E porão meu nome sobre os filhos de Israel, e eu os abençoarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'E aconteceu, que quando Moisés acabou de levantar o tabernáculo, e o ungido, e o santificado, com todos os seus utensílios; e também ungido e santificado o altar, com todos os seus utensílios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Então os príncipes de Israel, os chefes das casas de seus pais, os quais eram os príncipes das tribos, que estavam sobre os contados, ofereceram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'E trouxeram suas ofertas diante do SENHOR, seis carros cobertos, e doze bois; por cada dois príncipes um carro, e cada um deles um boi; o qual ofereceram diante do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Toma-o deles, e será para o serviço do tabernáculo do testemunho: e o darás aos levitas, a cada um conforme seu ministério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Então Moisés recebeu os carros e os bois, e deu-os aos levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dois carros e quatro bois, deu aos filhos de Gérson, conforme seu ministério;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'E aos filhos de Merari deu os quatro carros e oito bois, conforme seu ministério, sob a mão de Itamar, filho de Arão o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'E aos filhos de Coate não deu; porque levavam sobre si nos ombros o serviço do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'E ofereceram os príncipes à dedicação do altar o dia que foi ungido, ofereceram os príncipes sua oferta diante do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'E o SENHOR disse a Moisés: Oferecerão sua oferta, um príncipe um dia, e outro príncipe outro dia, à dedicação do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'E o que ofereceu sua oferta o primeiro dia foi Naassom filho de Aminadabe, da tribo de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'E foi sua oferta um prato de prata de peso de cento e trinta siclos, e uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Naassom, filho de Aminadabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'No segundo dia ofereceu Natanael filho de Zuar, príncipe de Issacar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Ofereceu por sua oferta um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Natanael, filho de Zuar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'No terceiro dia, Eliabe filho de Helom, príncipe dos filhos de Zebulom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Eliabe, filho de Helom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'No quarto dia, Elizur filho de Sedeur, príncipe dos filhos de Rúben:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário, ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
