INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Elizur, filho de Sedeur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'No quinto dia, Selumiel filho de Zurisadai, príncipe dos filhos de Simeão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Uma colher de ouro de dez siclos cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Selumiel, filho de Zurisadai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'No sexto dia, Eliasafe filho de Deuel, príncipe dos filhos de Gade:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano, Esta foi a oferta de Eliasafe, filho de Deuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'No sétimo dia, o príncipe dos filhos de Efraim, Elisama filho de Amiúde:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Elisama, filho de Amiúde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'No oitavo dia, o príncipe dos filhos de Manassés, Gamaliel filho de Pedazur:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'E seu oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Gamaliel, filho de Pedazur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'No nono dia, o príncipe dos filhos de Benjamim, Abidã filho de Gideoni:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Abidã, filho de Gideoni.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'No décimo dia, o príncipe dos filhos de Dã, Aiezer filho de Amisadai:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Aiezer, filho de Amisadai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'No décimo primeiro dia, o príncipe dos filhos de Aser, Pagiel filho de Ocrã:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Pagiel, filho de Ocrã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'No décimo segundo dia, o príncipe dos filhos de Naftali, Aira filho de Enã:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'E sua oferta, um prato de prata de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, ao siclo do santuário; ambos cheios de flor de farinha amassada com azeite para oferta de cereais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Uma colher de ouro de dez siclos, cheia de incenso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Um bezerro, um carneiro, um cordeiro de ano para holocausto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Um bode macho para expiação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'E para sacrifício pacífico, dois bois, cinco carneiros, cinco machos de bode, cinco cordeiros de ano. Esta foi a oferta de Aira, filho de Enã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Esta foi a dedicação do altar, no dia que foi ungido, pelos príncipes de Israel: doze pratos de prata, doze bacias de prata, doze colheres de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Cada prato de cento e trinta siclos, cada bacia de setenta: toda a prata dos vasos, dois mil e quatrocentos siclos, ao siclo do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'As doze colheres de ouro cheias de incenso, de dez siclos cada colher, ao siclo do santuário: todo o ouro das colheres, cento e vinte siclos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Todos os bois para holocausto, doze bezerros; doze os carneiros, doze os cordeiros de ano, com sua oferta de cereais: e doze os machos de bode, para expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'E todos os bois do sacrifício pacífico vinte e quatro novilhos, sessenta os carneiros, sessenta os machos de bode, sessenta os cordeiros de ano. Esta foi a dedicação do altar, depois que foi ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'E quando entrava Moisés no tabernáculo do testemunho, para falar com Ele, ouvia a Voz que lhe falava de cima do propiciatório que estava sobre a arca do testemunho, dentre os dois querubins: e falava com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Fala a Arão, e dize-lhe: Quando acenderes as lâmpadas, as sete lâmpadas iluminarão de frente à frente do candelabro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'E Arão o fez assim; que acendeu em frente do candelabro suas lâmpadas, como o SENHOR o mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'E esta era a feitura do candelabro: de ouro lavrado a martelo; desde seu pé até suas flores era lavrado a martelo: conforme o modelo que o SENHOR mostrou a Moisés, assim fez o candelabro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Toma aos levitas dentre os filhos de Israel, e expia-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'E assim lhes farás para expiá-los: esparge sobre eles a água da expiação, e face passar a navalha sobre toda sua carne, e lavarão suas roupas, e serão expiados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Logo tomarão um novilho, com sua oferta de cereais de flor de farinha amassada com azeite; e tomarás outro novilho para expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'E farás chegar os levitas diante do tabernáculo do testemunho, e juntarás toda a congregação dos filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'E quando haverás feito chegar os levitas diante do SENHOR, porão os filhos de Israel suas mãos sobre os levitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'E oferecerá Arão os levitas diante do SENHOR em oferta dos filhos de Israel, e servirão no ministério do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'E os levitas porão suas mãos sobre as cabeças dos novilhos: e oferecerás um por expiação, e o outro em holocausto ao SENHOR, para expiar os levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'E farás presentear os levitas diante de Arão, e diante de seus filhos, e os oferecerás em oferta ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Assim separarás os levitas dentre os filhos de Israel; e serão meus os levitas');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'E depois disso virão os levitas a ministrar no tabernáculo do testemunho: os expiarás pois, e os oferecerás em oferta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Porque inteiramente são a mim dados os levitas dentre os filhos de Israel, em lugar de todo aquele que abre madre; ei-los tomado para mim em lugar dos primogênitos de todos os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Porque meu é todo primogênito nos filhos de Israel, tanto de homens como de animais; desde o dia que eu feri todo primogênito na terra do Egito, os santifiquei para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'E tomei os levitas em lugar de todos os primogênitos nos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'E eu dei em presente os levitas a Arão e a seus filhos dentre os filhos de Israel, para que sirvam o ministério dos filhos de Israel no tabernáculo do testemunho, e reconciliem aos filhos de Israel; porque não haja praga nos filhos de Israel, chegando os filhos de Israel ao santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'E Moisés, e Arão, e toda a congregação dos filhos de Israel, fizeram dos levitas conforme todas as coisas que mandou o SENHOR a Moisés acerca dos levitas; assim fizeram deles os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'E os levitas se purificaram, e lavaram suas roupas; e Arão os ofereceu em oferta diante do SENHOR, e fez Arão expiação por eles para purificá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'E assim vieram depois os levitas para servir em seu ministério no tabernáculo do testemunho, diante de Arão e diante de seus filhos: da maneira que mandou o SENHOR a Moisés acerca dos levitas, assim fizeram com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Isto quanto aos levitas: de vinte e cinco anos acima entrarão a fazer seu ofício no serviço do tabernáculo do testemunho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Mas desde os cinquenta anos voltarão do ofício de seu ministério, e nunca mais servirão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Porém servirão com seus irmãos no tabernáculo do testemunho, para fazer a guarda, ainda que não servirão no ministério. Assim farás dos levitas quanto a seus ofícios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'E falou o SENHOR a Moisés no deserto de Sinai, no segundo ano de sua saída da terra do Egito, no mês primeiro, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Os filhos de Israel farão a páscoa a seu tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'No décimo quarto dia deste mês, entre as duas tardes, a fareis a seu tempo: conforme todos os seus ritos, e conforme todas suas leis a fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'E falou Moisés aos filhos de Israel, para que fizessem a páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'E fizeram a páscoa no mês primeiro, aos catorze dias do mês, entre as duas tardes, no deserto de Sinai: conforme todas as coisas que mandou o SENHOR a Moisés, assim fizeram os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'E houve alguns que estavam impuros por causa de morto, e não puderam fazer a páscoa aquele dia; e chegaram diante de Moisés e diante de Arão aquele dia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'E disseram-lhe aqueles homens: Nós somos impuros por causa de morto; por que seremos impedidos de oferecer oferta ao SENHOR a seu tempo entre os filhos de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'E Moisés lhes respondeu: Esperai, e ouvirei que mandará o SENHOR acerca de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Fala aos filhos de Israel, dizendo: Qualquer um de vós ou de vossas gerações, que for impuro por causa de morto ou estiver de viajem longe, fará páscoa ao SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'No mês segundo, aos catorze dias do mês, entre as duas tardes, a farão: com pães ázimos e ervas amargas a comerão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Não deixarão dele para a manhã, nem quebrarão osso nele: conforme todos os ritos da páscoa a farão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Mas o que estiver limpo, e não estiver de viajem, se deixar de fazer a páscoa, a tal pessoa será eliminada de seus povos: porquanto não ofereceu a seu tempo a oferta do SENHOR, o tal homem levará seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'E se morar convosco peregrino, e fizer a páscoa ao SENHOR, conforme o rito da páscoa e conforme suas leis assim a fará: um mesmo rito tereis, tanto o peregrino como o natural da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'E no dia que o tabernáculo foi levantado, a nuvem cobriu o tabernáculo sobre a tenda do testemunho; e à tarde havia sobre o tabernáculo como uma aparência de fogo, até a manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Assim era continuamente: a nuvem o cobria, e de noite a aparência de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'E segundo que se erguia a nuvem do tabernáculo, os filhos de Israel se partiam: e no lugar onde a nuvem parava, ali alojavam os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'À ordem do SENHOR os filhos de Israel se partiam: e à ordem do SENHOR assentavam o acampamento: todos os dias que a nuvem estava sobre o tabernáculo, eles estavam parados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'E quando a nuvem se detinha sobre o tabernáculo muitos dias, então os filhos de Israel guardavam a ordenança do SENHOR e não partiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'E quando sucedia que a nuvem estava sobre o tabernáculo poucos dias, ao dito do SENHOR alojavam, e ao dito do SENHOR partiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'E quando era que a nuvem se detinha desde a tarde até a manhã, quando à manhã a nuvem se levantava, eles partiam: ou se havia estado no dia, e à noite a nuvem se levantava, então partiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Ou se dois dias, ou um mês, ou ano, enquanto a nuvem se detinha sobre o tabernáculo ficando sobre ele, os filhos de Israel se estavam acampados e não moviam: mas quando ela se erguia, eles moviam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Ao dito do SENHOR assentavam, e ao dito do SENHOR partiam, guardando a ordenança do SENHOR, como o havia o SENHOR dito por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Faze para ti duas trombetas de prata; de obra de martelo as farás, as quais te servirão para convocar a congregação, e para fazer mover o acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'E quando as tocarem, toda a congregação se juntará a ti à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Mas quando tocarem somente uma, então se congregarão a ti os príncipes, os chefes dos milhares de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'E quando tocardes alarme, então moverão o acampamento dos que estão alojados ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'E quando tocardes alarme a segunda vez, então moverão o acampamento dos que estão alojados ao sul: alarme tocarão à suas partidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Porém quando houverdes de juntar a congregação, tocareis, mas não com som de alarme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'E os filhos de Arão, os sacerdotes, tocarão as trombetas; e as tereis por estatuto perpétuo por vossas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'E quando vierdes à guerra em vossa terra contra o inimigo que vos oprimir, tocareis alarme com as trombetas: e sereis em memória diante do SENHOR vosso Deus, e sereis salvos de vossos inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'E no dia de vossa alegria, e em vossas solenidades, e nos princípios de vossos meses, tocareis as trombetas sobre vossos holocaustos, e sobre os sacrifícios de vossas pazes, e vos serão por memória diante de vosso Deus: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'E foi no ano segundo, no mês segundo, aos vinte do mês, que a nuvem se levantou do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'E moveram os filhos de Israel por suas partidas do deserto de Sinai; e parou a nuvem no deserto de Parã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'E moveram a primeira vez ao dito do SENHOR por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'E a bandeira do acampamento dos filhos de Judá começou a marchar primeiro, por seus esquadrões: e Naassom, filho de Aminadabe, era sobre seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'E sobre o exército da tribo dos filhos de Issacar, Natanael filho de Zuar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'E sobre o exército da tribo dos filhos de Zebulom, Eliabe filho de Helom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'E depois que estava já desarmado o tabernáculo, moveram os filhos de Gérson e os filhos de Merari, que o levavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Logo começou a marchar a bandeira do acampamento de Rúben por seus esquadrões: e Elizur, filho de Sedeur, era sobre seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'E sobre o exército da tribo dos filhos de Simeão, Selumiel filho de Zurisadai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'E sobre o exército da tribo dos filhos de Gade, Eliasafe filho de Deuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Logo começaram a marchar os coatitas levando o santuário; e enquanto que eles traziam, os outros levantavam o tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Depois começou a marchar a bandeira do acampamento dos filhos de Efraim por seus esquadrões: e Elisama, filho de Amiúde, era sobre seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'E sobre o exército da tribo dos filhos de Manassés, Gamaliel filho de Pedazur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'E sobre o exército da tribo dos filhos de Benjamim, Abidã filho de Gideoni.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Logo começou a marchar a bandeira do campo dos filhos de Dã por seus esquadrões, recolhendo todos os acampamentos: e Aiezer, filho de Amisadai, era sobre seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'E sobre o exército da tribo dos filhos de Aser, Pagiel filho de Ocrã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'E sobre o exército da tribo dos filhos de Naftali, Aira filho de Enã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Estas são as partidas dos filhos de Israel por seus exércitos, quando se moviam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Então disse Moisés a Hobabe, filho de Reuel midianita, seu sogro: Nós nos partimos para o lugar do qual o SENHOR disse: Eu a vós o darei. Vem conosco, e te faremos bem: porque o SENHOR falou bem a respeito de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'E ele lhe respondeu: Eu não irei, mas sim que me marcharei à minha terra e à minha parentela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'E ele lhe disse: Rogo-te que não nos deixes; porque tu conheces nossos alojamentos no deserto, e nos serás em lugar de olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'E será, que se vieres conosco, quando tivermos o bem que o SENHOR nos há de fazer, nós te faremos bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Assim partiram do monte do SENHOR, caminho de três dias; e a arca da aliança do SENHOR foi diante deles caminho de três dias, buscando-lhes lugar de descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'E a nuvem do SENHOR ia sobre eles de dia, desde que partiram do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'E foi, que em movendo a arca, Moisés dizia: Levanta-te, o SENHOR, e sejam dissipados teus inimigos, e fujam de tua presença os que te aborrecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'E quando ela assentava, dizia: Volta, SENHOR, aos milhares de milhares de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'E aconteceu que o povo se queixou aos ouvidos do SENHOR: e ouviu-o o SENHOR, e ardeu seu furor, e acendeu-se neles fogo do SENHOR e consumiu um extremo do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Então o povo clamou a Moisés, e Moisés orou ao SENHOR, e apagou-se o fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'E chamou a aquele lugar Taberá; porque o fogo do SENHOR se acendeu neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'E o vulgo que havia em meio teve um vivo desejo, e voltaram-se, e ainda choraram os filhos de Israel, e disseram: Quem nos dera a comer carne!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Nos lembramos do peixe que comíamos no Egito de graça, dos pepinos, e dos melões, e dos alhos-porós, e das cebolas, e dos alhos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'E agora nossa alma se seca; que nada a não ser maná vem diante dos nossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'E era o maná como semente de coentro, e sua cor como cor de bdélio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Espalhava-se o povo, e recolhiam, e moíam em moinhos, ou malhavam em pilões, e o coziam em caldeira, ou faziam dele tortas: e seu sabor era como sabor de azeite novo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'E quando descia o orvalho sobre o acampamento de noite, o maná descia de sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'E ouviu Moisés ao povo, que chorava por suas famílias, cada um à porta de sua tenda: e o furor do SENHOR se acendeu em grande maneira; também pareceu mal a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'E disse Moisés ao SENHOR: Por que fizeste mal a teu servo? e por que não achei favor em teus olhos, que puseste a carga de todo este povo sobre mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Concebi eu a todo este povo? Gerei-o eu, para que me digas: Leva-o em teu peito, como leva a que cria ao que mama, à terra da qual juraste a seus pais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'De onde tenho eu carne para dar a todo este povo? porque choram a mim, dizendo: Dá-nos carne para comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Não posso eu sozinho suportar a todo este povo, que me é pesado em excesso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'E se assim o fazes tu comigo, eu te rogo que me dês a morte, se achei favor em teus olhos; e que eu não veja meu mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Então o SENHOR disse a Moisés: Junta-me setenta homens dos anciãos de Israel, de quem sabes que são anciãos do povo e seus oficiais; e traze-os à porta do tabernáculo do testemunho, e esperem ali contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'E eu descerei e falarei ali contigo; e tomarei do espírito que está em ti, e porei neles; e levarão contigo a carga do povo, e não a levarás tu sozinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Porém dirás ao povo: Santificai-vos para amanhã, e comereis carne: pois que chorastes em ouvidos do SENHOR, dizendo: Quem nos dera a comer carne! Certamente melhor nos ia no Egito! O SENHOR, pois, vos dará carne, e comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Não comereis um dia, nem dois dias, nem cinco dias, nem dez dias, nem vinte dias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Mas sim até um mês de tempo, até que vos saia pelas narinas, e vos seja em aborrecimento: porquanto menosprezastes ao SENHOR que está em meio de vós, e chorastes diante dele, dizendo: Para que saímos aqui do Egito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Então disse Moisés: Seiscentos mil a pé é o povo em meio do qual eu estou; e tu dizes: Lhes darei carne, e comerão o tempo de um mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Se degolarão para eles ovelhas e bois que lhes bastem? ou se juntarão para eles todos os peixes do mar para que tenham o suficiente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Então o SENHOR respondeu a Moisés: Encurtou-se a mão do SENHOR? agora verás se te sucede meu dito, ou não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'E saiu Moisés, e disse ao povo as palavras do SENHOR: e juntou os setenta homens dos anciãos do povo, e os fez estar ao redor do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Então o SENHOR desceu na nuvem, e falou-lhe; e tomou do espírito que estava nele, e o pôs nos setenta homens anciãos; e foi que, quando pousou sobre eles o espírito, profetizaram, e não cessaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'E haviam ficado no acampamento dois homens, chamado um Eldade e o outro Medade, sobre os quais também repousou o espírito: estavam estes entre os inscritos, mas não haviam saído ao tabernáculo; e profetizaram no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'E correu um jovem, e deu aviso a Moisés, e disse: Eldade e Medade profetizam no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Então respondeu Josué filho de Num, assistente de Moisés, um de seus rapazes, e disse: Senhor meu Moisés, impede-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'E Moisés lhe respondeu: Tens tu ciúmes por mim? mas bom seria se todo o povo do SENHOR fossem profetas, que o SENHOR pusesse seu espírito sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'E recolheu-se Moisés ao acampamento, ele e os anciãos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'E saiu um vento do SENHOR, e trouxe codornizes do mar, e deixou-as sobre o acampamento, um dia de caminho de uma parte, e um dia de caminho da outra, em derredor do acampamento, e quase dois côvados sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Então o povo esteve levantado todo aquele dia, e toda a noite, e todo o dia seguinte, e recolheram para si codornizes: o que menos, recolheu dez amontoados; e as estenderam para si ao comprimento em derredor do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Ainda estava a carne entre os dentes deles, antes que fosse mastigada, quando o furor do SENHOR se acendeu no povo, e feriu o SENHOR ao povo com uma muito grande praga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'E chamou o nome daquele lugar Quibrote-Hataavá, porquanto ali sepultaram ao povo cobiçoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'De Quibrote-Hataavá moveu o povo a Hazerote, e pararam em Hazerote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'E falaram Miriã e Arão contra Moisés por causa da mulher cuxita que havia tomado: porque ele havia tomado mulher cuxita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'E disseram: Somente por Moisés falou o SENHOR? Não falou também por nós? E ouviu-o o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'E aquele homem Moisés era muito manso, mais que todos os homens que havia sobre a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'E logo disse o SENHOR a Moisés, e a Arão, e a Miriã: Saí vós três ao tabernáculo do testemunho. E saíram eles três.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Então o SENHOR desceu na coluna da nuvem, e pôs-se à porta do tabernáculo, e chamou a Arão e a Miriã; e saíram eles ambos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'E ele lhes disse: Ouvi agora minhas palavras: se tiverdes profeta do SENHOR, lhe aparecerei em visão, em sonhos falarei com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Não assim a meu servo Moisés, que é fiel em toda minha casa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Face a face falarei com ele, e às claras, e não por figuras; e verá a aparência do SENHOR: por que pois não tivestes temor de falar contra meu servo Moisés?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Então o furor do SENHOR se acendeu neles; e ele se foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'E a nuvem se afastou do tabernáculo: e eis que Miriã era leprosa como a neve; e olhou Arão a Miriã, e eis que estava leprosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'E disse Arão a Moisés: Ah! Senhor meu, não ponhas agora sobre nós pecado; porque loucamente o fizemos, e pecamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Não seja ela agora como o que sai morto do ventre de sua mãe, consumida a metade de sua carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Então Moisés clamou ao SENHOR, dizendo: Rogo-te, ó Deus, que a sares agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Respondeu o SENHOR a Moisés: Pois se seu pai houvesse cuspido em sua face, não se envergonharia por sete dias?: seja lançada fora do acampamento por sete dias, e depois se reunirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Assim Miriã foi lançada do acampamento sete dias; e o povo não passou adiante até que se lhe reuniu Miriã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'E Depois moveu o povo de Hazerote, e assentaram o acampamento no deserto de Parã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Envia tu homens que reconheçam a terra de Canaã, a qual eu dou aos filhos de Israel: de cada tribo de seus pais enviareis um homem, cada um príncipe entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'E Moisés os envio desde o deserto de Parã, conforme a palavra do SENHOR: e todos aqueles homens eram príncipes dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Os nomes dos quais são estes: Da tribo de Rúben, Samua filho de Zacur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Da tribo de Simeão, Safate filho de Hori.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Da tribo de Judá, Calebe filho de Jefoné.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Da tribo de Issacar, Jigeal filho de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Da tribo de Efraim, Oseias filho de Num.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Da tribo de Benjamim, Palti filho de Rafu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Da tribo de Zebulom, Gadiel filho de Sodi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Da tribo de José, da tribo de Manassés, Gadi filho de Susi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Da tribo de Dã, Amiel filho de Gemali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Da tribo de Aser, Setur filho de Micael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Da tribo de Naftali, Nabi filho de Vofsi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Da tribo de Gade, Guel filho de Maqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Estes são os nomes dos homens que Moisés enviou a reconhecer a terra: e a Oseias filho de Num, lhe pôs Moisés o nome de Josué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Enviou-os, pois, Moisés a reconhecer a terra de Canaã, dizendo-lhes: Subi por aqui, pelo sul, e subi ao monte:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'E observai a terra que tal é; e o povo que a habita, se é forte ou débil, se pouco ou numeroso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Que tal a terra habitada, se é boa ou má; e que tais são as cidades habitadas, se de tendas ou de fortalezas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'E qual seja o terreno, se é fértil ou fraco, se nele há ou não árvores: e esforçai-vos, e colhei do fruto do país. E o tempo era o tempo das primeiras uvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'E eles subiram, e reconheceram a terra desde o deserto de Zim até Reobe, entrando em Hamate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'E subiram pelo sul, e vieram até Hebrom: e ali estavam Aimã, e Sesai, e Talmai, filhos de Anaque. Hebrom foi edificada sete anos antes de Zoã, a do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'E chegaram até o ribeiro de Escol, e dali cortaram um ramo com um cacho de uvas, o qual trouxeram dois em uma vara, e das romãs e dos figos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'E chamou-se aquele lugar vale de Escol pelo cacho que cortaram dali os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'E voltaram de reconhecer a terra ao fim de quarenta dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'E andaram e vieram a Moisés e a Arão, e a toda a congregação dos filhos de Israel, no deserto de Parã, em Cades, e deram-lhes a resposta, e a toda a congregação, e lhes mostraram o fruto da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'E lhe contaram, e disseram: Nós chegamos à terra à qual nos enviaste, a que certamente flui leite e mel; e este é o fruto dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Mas o povo que habita aquela terra é forte, e as cidades muito grandes e fortes; e também vimos ali os filhos de Anaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amaleque habita a terra do sul; e os heteus, e os jebuseus, e os amorreus, habitam no monte; e os cananeus habitam junto ao mar, e à beira do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Então Calebe fez calar o povo diante de Moisés, e disse: Subamos logo, e passemos a ela; que mais poderemos que ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Mas os homens que subiram com ele, disseram: Não poderemos subir contra aquele povo; porque é mais forte que nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'E falaram mal entre os filhos de Israel da terra que haviam reconhecido, dizendo: A terra por de onde passamos para reconhecê-la, é terra que consome a seus moradores; e todo o povo que vimos em meio dela, são homens de grande estatura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Também vimos ali gigantes, filhos de Anaque, raça dos gigantes: e éramos nós, à nossa aparência, como gafanhotos; e assim lhes parecíamos a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Então toda a congregação levantaram grito, e deram vozes: e o povo chorou aquela noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'E queixaram-se contra Moisés e contra Arão todos os filhos de Israel; e disse-lhes toda a multidão: Melhor seria se tivéssemos morrido na terra do Egito; ou melhor seria se tivéssemos morrido neste deserto!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'E por que nos traze o SENHOR a esta terra para cair à espada e que nossas mulheres e nossos meninos sejam por presa? não nos seria melhor voltarmos ao Egito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'E diziam um ao outro: Façamos um capitão, e voltemos ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Então Moisés e Arão caíram sobre seus rostos diante de toda a multidão da congregação dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'E Josué filho de Num, e Calebe filho de Jefoné, que eram dos que haviam reconhecido a terra, rasgaram suas roupas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'E falaram a toda a congregação dos filhos de Israel, dizendo: A terra por de onde passamos para reconhecê-la, é terra em grande maneira boa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Se o SENHOR se agradar de nós, ele nos porá nesta terra, e a entregará a nós; terra que flui leite e mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Portanto, não sejais rebeldes contra o SENHOR, nem temais ao povo desta terra, porque nosso pão são: seu amparo se afastou deles, e conosco está o SENHOR: não os temais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Então toda a multidão falou de apedrejá-los com pedras. Mas a glória do SENHOR se mostrou no tabernáculo do testemunho a todos os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'E o SENHOR disse a Moisés: Até quando me há de irritar este povo? até quando não me há de crer com todos os sinais que fiz em meio deles?.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Eu lhe ferirei de mortandade, e o destruirei, e a ti te porei sobre gente grande e mais forte que eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'E Moisés respondeu ao SENHOR: Logo os egípcios o ouvirão, porque do meio deles tiraste a este povo com tua força:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'E o dirão aos habitantes desta terra; os quais ouviram que tu, ó SENHOR, estavas em meio deste povo, que olho a olho aparecias tu, ó SENHOR, e que tua nuvem estava sobre eles, e que de dia ias diante deles em coluna de nuvem, e de noite em coluna de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'E que fizeste morrer a este povo como a um homem: e as nações que houverem ouvido tua fama falarão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Porque não pôde o SENHOR meter este povo na terra da qual lhes havia jurado, os matou no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Agora, pois, eu te rogo que seja engrandecida a força do Senhor, como o falaste, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'O SENHOR, tardio de ira e grande em misericórdia, que perdoa a iniquidade e a rebelião, e deixa impune o culpado; que visita a maldade dos pais sobre os filhos até a terceira geração e até a quarta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Perdoa agora a iniquidade deste povo segundo a grandeza de tua misericórdia, e como perdoaste a este povo desde Egito até aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Então o SENHOR disse: Eu o perdoei conforme tu dito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mas, certamente vivo eu e minha glória inche toda a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Que todos os que viram minha glória e meus sinais que fiz no Egito e no deserto, e me tentaram já dez vezes, e não ouviram minha voz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Não verão a terra da qual jurei a seus pais: não, nenhum dos que me irritaram a verá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Porém meu servo Calebe, porquanto houve nele outro espírito, e cumpriu de ir após mim, eu o porei na terra onde entrou e sua descendência a receberá em herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Agora bem, os amalequitas e os cananeus habitam no vale; voltai-vos amanhã, e parti-vos ao deserto, caminho do mar Vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'E o SENHOR falou a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Até quando ouvirei esta depravada multidão que murmura contra mim, as queixas dos filhos de Israel, que de mim se queixam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Dize-lhes: Vivo eu, diz o SENHOR, que segundo falastes a meus ouvidos, assim farei eu convosco:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Neste deserto cairão vossos corpos; todos vossos contados segundo toda vossa contagem, de vinte anos acima, os quais murmurastes contra mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Vós à verdade não entrareis na terra, pela qual levantei minha mão de fazer-vos habitar nela; exceto a Calebe filho de Jefoné, e a Josué filho de Num.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Mas vossos meninos, dos quais dissestes que seriam por presa, eu os introduzirei, e eles conhecerão a terra que vós desprezastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'E quanto a vós, vossos corpos cairão neste deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'E vossos filhos andarão pastoreando no deserto quarenta anos, e eles levarão vossas prostituições, até que vossos corpos sejam consumidos no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Conforme o número dos dias, dos quarenta dias em que reconhecestes a terra, levareis vossas iniquidades quarenta anos, ano por cada dia; e conhecereis meu castigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Eu sou o SENHOR falei; assim farei a toda esta multidão perversa que se juntou contra mim; neste deserto serão consumidos, e ali morrerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'E os homens que Moisés enviou a reconhecer a terra, e depois de voltarem fizeram murmurar contra ele a toda a congregação, desacreditando aquele país,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Aqueles homens que haviam falado mal da terra, morreram de praga diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Mas Josué filho de Num, e Calebe filho de Jefoné, restaram com vida dentre aqueles homens que haviam ido a reconhecer a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'E Moisés disse estas coisas a todos os filhos de Israel, e o povo ficou em muito luto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'E levantaram-se pela manhã, e subiram ao cume do monte, dizendo: Eis-nos aqui para subir ao lugar do qual falou o SENHOR; porque pecamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'E disse Moisés: Por que quebrantais o dito do SENHOR? Isto tampouco vos sucederá bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Não subais, porque o SENHOR não está em meio de vós, não sejais feridos diante de vossos inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Porque os amalequitas e os cananeus estão ali diante de vós, e caireis à espada: pois porquanto vos desviastes de seguir ao SENHOR, por isso não será o SENHOR convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Todavia, se insistiram em subir por cima do monte: mas a arca da aliança do SENHOR, e Moisés, não se apartaram do meio do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'E desceram os amalequitas e os cananeus, que habitavam naquele monte, e os feriram e os derrotaram, perseguindo-os até Hormá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra de vossas habitações, que eu vos dou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'E fizerdes oferta de queima ao SENHOR, holocausto, ou sacrifício, por especial voto, ou de vossa vontade, ou para fazer em vossas solenidades cheiro suave ao SENHOR, de vacas ou de ovelhas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Então o que oferecer sua oferta ao SENHOR, trará por oferta de cereais uma dízima de um efa de flor de farinha, amassada com a quarta parte de um him de azeite;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'E de veio para a libação oferecerás a quarta parte de um him, além do holocausto ou do sacrifício, por cada cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'E para cada carneiro farás oferta de cereais de duas dízimas de flor de farinha, amassada com o terço de um him de azeite:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'E de vinho para a libação oferecerás o terço de um him, em cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'E quando oferecerdes novilho em holocausto ou sacrifício, por especial voto, ou pacífico ao SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Oferecerás com o novilho uma oferta de cereais de três dízimas de flor de farinha, amassada com a metade de um him de azeite:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'E de vinho para a libação oferecerás a metade de um him, em oferta de queima de cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Assim se fará com cada um boi, ou carneiro, ou cordeiro, o mesmo de ovelhas que de cabras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Conforme o número assim fareis com cada um segundo o número deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Todo natural fará estas coisas assim, para oferecer oferta de queima de cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'E quando habitar convosco estrangeiro, ou qualquer um que estiver entre vós por vossas gerações, se fizer oferta de queima de cheiro suave ao SENHOR, como vós fizerdes, assim fará ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Um mesmo estatuto tereis, vós da congregação e o estrangeiro que convosco mora; estatuto que será perpétuo por vossas gerações: como vós, assim será o peregrino diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Uma mesma lei e um mesmo regulamento tereis, vós e o peregrino que convosco mora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra à qual eu vos levo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Será que quando começardes a comer o pão da terra, oferecereis oferta ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Da primeira parte que amassardes, oferecereis um bolo como oferta; como a oferta da eira, assim o oferecereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Das primícias de vossas massas dareis ao SENHOR oferta por vossas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'E quando errardes, e não fizerdes todos estes mandamentos que o SENHOR disse a Moisés,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Todas as coisas que o SENHOR vos mandou pela mão de Moisés, desde o dia que o SENHOR o mandou, e em adiante por vossas gerações,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Será que, se o pecado foi feito por acidente com ignorância da congregação, toda a congregação oferecerá um novilho por holocausto, em cheiro suave ao SENHOR, com sua oferta de cereais e sua libação, conforme a lei; e um bode macho em expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'E o sacerdote fará expiação por toda a congregação dos filhos de Israel; e lhes será perdoado, porque acidente é: e eles trarão seus ofertas, oferta de queima ao SENHOR, e suas expiações diante do SENHOR, por seus erros:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'E será perdoado a toda a congregação dos filhos de Israel, e ao estrangeiro que peregrina entre eles, porquanto é acidente de todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'E se uma pessoa pecar por acidente, oferecerá uma cabra de ano por expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'E o sacerdote fará expiação pela pessoa que haverá pecado por acidente, quando pecar por acidente diante do SENHOR, a reconciliará, e lhe será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'O natural entre os filhos de Israel, e o peregrino que habitar entre eles, uma mesma lei tereis para o que fizer algo por acidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mas a pessoa que fizer algo com mão soberba, tanto o natural como o estrangeiro, ao SENHOR blasfemou; e a tal pessoa será eliminada do meio de seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Porquanto teve em pouco a palavra do SENHOR, e deu por nulo seu mandamento, inteiramente será eliminada a tal pessoa: sua iniquidade será sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'E estando os filhos de Israel no deserto, acharam um homem que recolhia lenha em dia de sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'E os que lhe acharam recolhendo lenha trouxeram-lhe a Moisés e a Arão, e a toda a congregação:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'E puseram-no no cárcere, porque não estava declarado que lhe haviam de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'E o SENHOR disse a Moisés: Invariavelmente morra aquele homem; apedreje-o com pedras toda a congregação fora do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Então o tirou a congregação fora do acampamento, e apedrejaram-no com pedras, e morreu; como o SENHOR mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Fala aos filhos de Israel, e dize-lhes que se façam franjas) nos arremates de suas roupas, por suas gerações; e ponham em cada franja dos arremates um cordão de azul:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'E vos servirá de franja, para que quando o virdes, vos lembreis de todos os mandamentos do SENHOR, para praticá-los; e não olheis segundo vosso coração e vossos olhos, atrás dos quais prostituís:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Para que vos lembreis, e façais todos meus mandamentos, e sejais santos a vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito, para ser vosso Deus: Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'E Coré, filho de Izar, filho de Coate, filho de Levi; e Datã e Abirão, filhos de Eliabe; e Om, filho de Pelete, dos filhos de Rúben, tomaram gente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'E levantaram-se contra Moisés com duzentos e cinquenta homens dos filhos de Israel, príncipes da congregação, dos do conselho, homens de renome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'E se juntaram contra Moisés e Arão, e lhes disseram: Basta-vos, porque toda a congregação, todos eles são santos, e em meio deles está o SENHOR: por que, pois, vos levantais vós sobre a congregação do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'E quando o ouviu Moisés, lançou-se sobre seu rosto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'E falou a Coré e a todo o seu grupo, dizendo: Amanhã mostrará o SENHOR quem é seu, e ao santo o fará chegar a si; e ao que ele escolher, ele o achegará a si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Fazei isto: tomai incensários, Coré e todo o seu grupo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'E ponde fogo neles, e ponde neles incenso diante do SENHOR amanhã; e será que o homem a quem o SENHOR escolher, aquele será o santo: basta-vos isto, filhos de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Disse mais Moisés a Coré: Ouvi agora, filhos de Levi:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Vos é pouco que o Deus de Israel vos haja apartado da congregação de Israel, fazendo-vos achegar a si para que ministrasses no serviço do tabernáculo do SENHOR, e estivésseis diante da congregação para ministrar-lhes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'E que te fez aproximar a ti, e a todos os teus irmãos os filhos de Levi contigo; para que procureis também o sacerdócio?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Portanto, tu e todo o teu grupo sois os que vos juntais contra o SENHOR: pois Arão, que é para que contra ele murmureis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'E enviou Moisés a chamar a Datã e Abirão, filhos de Eliabe; mas eles responderam: Não iremos lá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'É pouco que nos tenhas feito vir de uma terra que destila leite e mel, para fazer-nos morrer no deserto, mas que também te faças senhor de nós autoritariamente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Nem tampouco nos puseste tu em terra que flua leite e mel, nem nos deste propriedades de terras e vinhas: hás de arrancar os olhos destes homens? Não subiremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Então Moisés se irou em grande maneira, e disse ao SENHOR: Não olhes a sua oferta: nem ainda um asno tomei deles, nem a nenhum deles fiz mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Depois disse Moisés a Coré: Tu e todo o teu grupo, ponde-vos amanhã diante do SENHOR; tu, e eles, e Arão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'E tomai cada um seu incensário, e ponde incenso neles, e achegai diante do SENHOR cada um seu incensário: duzentos e cinquenta incensários: tu também, e Arão, cada um com seu incensário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'E tomaram cada um seu incensário, e puseram neles fogo, e lançaram neles incenso, e puseram-se à porta do tabernáculo do testemunho com Moisés e Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Já Coré havia feito juntar contra eles toda a congregação à porta do tabernáculo do testemunho: então a glória do SENHOR apareceu a toda a congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'E o SENHOR falou a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Apartai-vos dentre esta congregação, e os consumirei em um momento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'E eles se lançaram sobre seus rostos, e disseram: Deus, Deus dos espíritos de toda carne, não é um homem o que pecou? E te irarás tu contra toda a congregação?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Então o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Fala à congregação, dizendo: Apartai-vos de em derredor da tenda de Coré, Datã, e Abirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'E Moisés se levantou, e foi a Datã e Abirão; e os anciãos de Israel foram atrás dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'E ele falou à congregação, dizendo: Apartai-vos agora das tendas destes ímpios homens, e não toqueis nenhuma coisa sua, porque não pereçais em todos os seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'E apartaram-se das tendas de Coré, de Datã, e de Abirão em derredor: e Datã e Abirão saíram e puseram-se às portas de suas tendas, com suas mulheres, e seus filhos, e suas crianças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'E disse Moisés: Em isto conhecereis que o SENHOR me enviou para que fizesse todas estas coisas: que não de meu coração as fiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Se como morrem todos os homens morrerem estes, ou se forem eles visitados à maneira de todos os homens, o SENHOR não me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Mas se o SENHOR fizer uma nova coisa, e a terra abrir sua boca, e os tragar com todas suas coisas, e descerem vivos ao mundo dos mortos, então conhecereis que estes homens irritaram ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'E aconteceu, que em acabando ele de falar todas estas palavras, rompeu-se a terra que estava debaixo deles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'E abriu a terra sua boca, e tragou-os a eles, e a suas casas, e a todos os homens de Coré, e a todos os seus pertences.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'E eles, com tudo o que tinham, desceram vivos ao mundo dos mortos, e cobriu-os a terra, e pereceram do meio da congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'E todo Israel, os que estavam em derredor deles, fugiram ao grito deles; porque diziam: Não nos trague também a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'E saiu fogo do SENHOR, e consumiu os duzentos e cinquenta homens que ofereciam o incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Então o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Dize a Eleazar, filho de Arão sacerdote, que tome os incensários do meio do incêndio, e derrame mais ali o fogo; porque são santificados:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Os incensários destes pecadores contra suas almas: e farão deles placas estendidas para cobrir o altar: porquanto ofereceram com eles diante do SENHOR, são santificados; e serão por sinal aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'E o sacerdote Eleazar tomou os incensários de bronze com que os queimados haviam oferecido; e estenderam-nos para cobrir o altar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Em memorial aos filhos de Israel que nenhum estranho que não seja da descendência de Arão, chegue a oferecer incenso diante do SENHOR, para que não seja como Coré, e como seu grupo; segundo se o disse o SENHOR por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'No dia seguinte toda a congregação dos filhos de Israel murmurou contra Moisés e Arão, dizendo: Vós haveis matado ao povo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'E aconteceu que, quando se juntou a congregação contra Moisés e Arão, olharam até o tabernáculo do testemunho, e eis que a nuvem o havia coberto, e apareceu a glória do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'E vieram Moisés e Arão diante do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Apartai-vos do meio desta congregação, e os consumirei em um momento. E eles se lançaram sobre seus rostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'E disse Moisés A Arão: Toma o incensário, e põe nele fogo do altar, e sobre ele põe incenso, e vai logo à congregação, e faze expiação por eles; porque o furor saiu de diante da face do SENHOR: a mortandade começou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Então tomou Arão o incensário, como Moisés disse, e correu em meio da congregação: e eis que a mortandade havia começado no povo: e ele pôs incenso, e fez expiação pelo povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'E pôs-se entre os mortos e os vivos, e cessou a mortandade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'E os que morreram naquela mortandade foram catorze mil e setecentos, sem os mortos pelo negócio de Coré.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Depois se voltou Arão a Moisés à porta do tabernáculo do testemunho, quando a mortandade havia cessado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Fala aos filhos de Israel, e toma deles uma vara por cada casa dos pais, de todos os príncipes deles, doze varas conforme as casas de seus pais; e escreverás o nome de cada um sobre sua vara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'E escreverás o nome de Arão sobre a vara de Levi; porque cada cabeça de família de seus pais terá uma vara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'E as porás no tabernáculo do testemunho diante do testemunho, onde eu me declararei a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'E será, que o homem que eu escolher, sua vara florescerá: e farei cessar de sobre mim as queixas dos filhos de Israel, com que murmuram contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'E Moisés falou aos filhos de Israel, e todos os príncipes deles lhe deram varas; cada príncipe pelas casas de seus pais uma vara, em todas doze varas; e a vara de Arão estava entre as varas deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'E Moisés pôs as varas diante do SENHOR no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'E aconteceu que no dia seguinte veio Moisés ao tabernáculo do testemunho; e eis que a vara de Arão da casa de Levi havia brotado, e produzido flores, e lançado renovos, e produzido amêndoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Então tirou Moisés todas as varas de diante do SENHOR a todos os filhos de Israel; e eles o viram, e tomaram cada um sua vara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'E o SENHOR disse a Moisés: Volta a vara de Arão diante do testemunho, para que se guarde por sinal aos filhos rebeldes; e farás cessar suas queixas de sobre mim, para que não morram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'E o fez Moisés: como lhe mandou o SENHOR, assim fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Então os filhos de Israel falaram a Moisés, dizendo: Eis que nós somos mortos, perdidos somos, todos nós somos perdidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Qualquer um que se chegar, o que se aproximar ao tabernáculo do SENHOR morrerá: Acabaremos de perecer todos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'E o SENHOR disse a Arão: Tu e teus filhos, e a casa de teu pai contigo, levareis o pecado do santuário: e tu e teus filhos contigo levareis o pecado de vosso sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'E a teus irmãos também, a tribo de Levi, a tribo de teu pai, faze-os chegar a ti, e juntem-se contigo, e te servirão; e tu e teus filhos contigo servireis diante do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'E guardarão o que tu ordenares, e o cargo de todo o tabernáculo: mas não chegarão aos utensílios santos nem ao altar, para que não morram eles e vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Eles se juntarão, pois, contigo, e terão o cargo do tabernáculo do testemunho em todo o serviço do tabernáculo; nenhum estranho se há de chegar a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'E tereis a guarda do santuário, e a guarda do altar, para que não seja mais a ira sobre os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Porque eis que eu tomei a vossos irmãos os levitas dentre os filhos de Israel, dados a vós em presente do SENHOR, para que sirvam no ministério do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Mas tu e teus filhos contigo guardareis vosso sacerdócio em todo negócio do altar, e do véu dentro, e ministrareis. Eu vos dei como presente o serviço de vosso sacerdócio; e o estranho que se chegar, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Disse mais o SENHOR a Arão: Eis que eu te dei também a guarda de minhas ofertas: todas as coisas consagradas dos filhos de Israel te dei por razão da unção, e a teus filhos, por estatuto perpétuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Isto será teu da oferta das coisas santas reservadas do fogo: toda oferta deles, toda oferta de cereais sua, e toda expiação pelo pecado deles, que me hão de presentear, será coisa muito santa para ti e para teus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'No santuário a comerás; todo homem comerá dela: coisa santa será para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Isto também será teu: a oferta elevada de seus presentes, e todas as ofertas movidas dos filhos de Israel, dei a ti, e a teus filhos, e a tuas filhas contigo, por estatuto perpétuo: todo limpo em tua casa comerá delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'De azeite, e de mosto, e de trigo, tudo o mais escolhido, as primícias disso, que apresentarão ao SENHOR, a ti as dei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'As primícias de todas as coisas da terra deles, as quais trarão ao SENHOR, serão tuas: todo limpo em tua casa comerá delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Todo o consagrado por voto em Israel será teu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Todo o que abrir madre em toda carne que oferecerão ao SENHOR, tanto de homens como de animais, será teu: mas farás resgatar o primogênito do homem: também farás resgatar o primogênito de animal impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'E de um mês farás efetuar o resgate deles, conforme tua avaliação, por preço de cinco siclos, ao siclo do santuário, que é de vinte óbolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Mas o primogênito de vaca, e o primogênito de ovelha, e o primogênito de cabra, não resgatarás; santificados são: o sangue deles espargirás sobre o altar, e queimarás a gordura deles, oferta de queima em cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'E a carne deles será tua: como o peito da oferta movida e como a coxa direita, será tua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Todas as ofertas elevadas das coisas santas, que os filhos de Israel oferecerem ao SENHOR, dei-as a ti, e a teus filhos e a tuas filhas contigo, por estatuto perpétuo: pacto de sal perpétuo é diante do SENHOR para ti e para tua descendência contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'E o SENHOR disse a Arão: Da terra deles não terás herança, nem entre eles terás parte: Eu sou tua parte e tua herança em meio dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'E eis que eu dei aos filhos de Levi todos os dízimos em Israel por herança, por seu ministério, porquanto eles servem no ministério do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'E não chegarão mais os filhos de Israel ao tabernáculo do testemunho, para que não levem pecado, pelo qual morram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Mas os levitas farão o serviço do tabernáculo do testemunho, e eles levarão sua iniquidade: estatuto perpétuo por vossas gerações; e não possuirão herança entre os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Porque aos levitas dei por herança os dízimos dos filhos de Israel, que oferecerão ao SENHOR em oferta: pelo qual lhes disse: Entre os filhos de Israel não possuirão herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Assim falarás aos levitas, e lhes dirás: Quando tomardes dos filhos de Israel os dízimos que vos dei deles por vossa herança, vós apresentareis deles em oferta movida ao SENHOR o dízimo dos dízimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'E se vos contará vossa oferta como grão da eira, e como plenitude do lagar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Assim oferecereis também vós oferta ao SENHOR de todos vossos dízimos que houverdes recebido dos filhos de Israel; e dareis deles a oferta do SENHOR a Arão o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'De todos vossos presentes oferecereis toda oferta ao SENHOR; de todo o melhor deles oferecereis a porção que será consagrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'E lhes dirás: Quando oferecerdes o melhor deles, será contado aos levitas por fruto da era, e como fruto do lagar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'E o comereis em qualquer lugar, vós e vossa família: pois é vossa remuneração por vosso ministério no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'E quando vós houverdes oferecido disso o melhor seu, não levareis por ele pecado: e não haveis de contaminar as coisas santas dos filhos de Israel, e não morrereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'E o SENHOR falou a Moisés e a Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Esta é a ordenança da lei que o SENHOR prescreveu, dizendo: Dize aos filhos de Israel que te tragam uma novilha vermelha, sem defeito, que não tenha mancha, sobre a qual não se tenha posto jugo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'e a dareis ao sacerdote Eleazar. Ele a tirará fora do acampamento, e a fará degolar em sua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'E tomará Eleazar o sacerdote de seu sangue com seu dedo, e espargirá até a dianteira do tabernáculo do testemunho com o sangue dela sete vezes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'E fará queimar a vaca ante seus olhos: seu couro e sua carne e seu sangue, com seu excremento, fará queimar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Logo tomará o sacerdote pau de cedro, e hissopo, e escarlata, e o lançará em meio do fogo em que arde a vaca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'O sacerdote lavará logo suas roupas, lavará também sua carne com água, e depois entrará no acampamento; e será impuro o sacerdote até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Também o que a queimou, lavará suas roupas em água, também lavará em água sua carne, e será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'E um homem limpo recolherá as cinzas da vaca, e as porá fora do acampamento em lugar limpo, e as guardará a congregação dos filhos de Israel para a água de separação: é uma expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'E o que recolheu as cinzas da vaca, lavará suas roupas, e será impuro até à tarde: e será aos filhos de Israel, e ao estrangeiro que peregrina entre eles, por estatuto perpétuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'O que tocar morto de qualquer pessoa humana, sete dias será impuro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Este se purificará ao terceiro dia com esta água, e ao sétimo dia será limpo; e se ao terceiro dia não se purificar, não será limpo ao sétimo dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Qualquer um que tocar em morto, em pessoa de homem que estiver morto, e não se purificar, o tabernáculo do SENHOR contaminou; e aquela pessoa será eliminada de Israel: porquanto a água da separação não foi espargida sobre ele, impuro será; e seu impureza será sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Esta é a lei para quando alguém morrer na tenda: qualquer um que entrar na tenda e todo o que estiver nela, será impuro sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'E todo vaso aberto, sobre o qual não houver tampa bem ajustada, sera impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'E qualquer um que tocar em morto à espada sobre a face do campo, ou em morto, ou em osso humano, ou em sepulcro, sete dias será impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'E para o impuro tomarão da cinza da queimada vaca da expiação, e lançarão sobre ela água viva em um vaso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'E um homem limpo tomará hissopo. e o molhará na água, e espargirá sobre a tenda, e sobre todos os móveis, e sobre as pessoas que ali estiverem, e sobre aquele que houver tocado o osso, ou o matado, ou o cadáver, ou o sepulcro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'E o limpo espargirá sobre o impuro ao terceiro e ao sétimo dia: e quando o haverá purificado ao dia sétimo, ele lavará logo suas roupas, e a si mesmo se lavará com água, e será limpo à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'E o que for impuro, e não se purificar, a tal pessoa será eliminada dentre a congregação, porquanto contaminou o tabernáculo do SENHOR: não foi espargida sobre ele a água de separação, é impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'E lhes será por estatuto perpétuo: também o que espargir a água da separação lavará suas roupas; e o que tocar a água da separação, será impuro até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'E todo o que o impuro tocar, será impuro: e a pessoa que o tocar, será impura até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'E chegaram os filhos de Israel, toda a congregação, ao deserto de Zim, no mês primeiro, e assentou o povo em Cades; e ali morreu Miriã, e foi ali sepultada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'E como não havia água para a congregação, juntaram-se contra Moisés e Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'E brigou o povo com Moisés, e falaram dizendo: Antes que nós tivéssemos morrido quando pereceram nossos irmãos diante do SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'E por que fizeste vir a congregação do SENHOR a este deserto, para que morramos aqui nós e nossos animais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'E por que nos fizeste subir do Egito, para trazer-nos a este mal lugar? Não é lugar de sementeira, de figueiras, de vinhas, nem romãs: nem ainda de água para beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'E foram-se Moisés e Arão de diante da congregação à porta do tabernáculo do testemunho, e lançaram-se sobre seus rostos; e a glória do SENHOR apareceu sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Toma a vara e reúne a congregação, tu e Arão teu irmão, e falai à rocha em olhos deles; e ela dará sua água, e lhes tirarás águas da rocha, e darás de beber à congregação, e a seus animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Então Moisés tomou a vara de diante do SENHOR, como ele lhe mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'E juntaram Moisés e Arão a congregação diante da rocha, e disse-lhes: Ouvi agora, rebeldes: Faremos para vós sair águas desta rocha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Então levantou Moisés sua mão, e feriu a rocha com sua vara duas vezes: e saíram muitas águas, e bebeu a congregação, e seus animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'E o SENHOR disse a Moisés e a Arão: Porquanto não crestes em mim, para santificar-me aos olhos dos filhos de Israel, portanto, não poreis esta congregação na terra que lhes dei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Estas são as águas da briga, pelas quais contenderam os filhos de Israel com o SENHOR, e ele se santificou neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'E enviou Moisés embaixadores ao rei de Edom desde Cades: Assim diz Israel teu irmão: Tu soubeste todo o trabalho que nos veio:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Como nossos pais desceram ao Egito, e estivemos no Egito longo tempo, e os egípcios nos maltrataram, e a nossos pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'E clamamos ao SENHOR, o qual ouviu nossa voz, e enviou anjo, e tirou-nos do Egito; e eis que estamos em Cades, cidade ao extremo de teus confins:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Rogamo-te que passemos por tua terra; não passaremos por lavoura, nem por vinha, nem beberemos água de poços: pelo caminho real iremos, sem apartar-nos à direita nem à esquerda, até que havemos passado teu termo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'E Edom lhe respondeu: Não passarás por meu país, de outra maneira sairei contra ti armado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'E os filhos de Israel disseram: Pelo caminho seguido iremos; e se bebermos tuas águas eu e meus gados, darei o preço delas: certamente sem fazer outra coisa, passarei de seguida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'E ele respondeu: Não passarás. E saiu Edom contra ele com muito povo, e mão forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Não quis, pois, Edom deixar passar a Israel por seu termo, e apartou-se Israel dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'E partidos de Cades os filhos de Israel, toda aquela congregação, vieram ao monte de Hor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'E o SENHOR falou a Moisés e Arão no monte de Hor, nos confins da terra de Edom, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Arão será reunido a seus povos; pois não entrará na terra que eu dize aos filhos de Israel, porquanto fostes rebeldes a meu mandamento nas águas da briga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Toma a Arão e a Eleazar seu filho, e faze-os subir ao monte de Hor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'E faze desnudar a Arão suas roupas, e viste delas a Eleazar seu filho; porque Arão será reunido a seus povos, e ali morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'E Moisés fez como o SENHOR lhe mandou: e subiram ao monte de Hor à vista de toda a congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'E Moisés fez desnudar a Arão de suas roupas e vestiu-as a Eleazar seu filho: e Arão morreu ali no cume do monte: e Moisés e Eleazar desceram do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'E vendo toda a congregação que Arão era morto, fizeram-lhe luto por trinta dias todas as famílias de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'E quando o cananeu, o rei de Arade, que habitava ao sul, ouviu falar que Israel vinha pelo caminho de Atarim, lutou contra Israel, e dele levou alguns como prisioneiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Então Israel fez voto ao SENHOR, e disse: Se com efeito entregares a este povo em minha mão, eu destruirei suas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'E o SENHOR escutou a voz de Israel, e entregou aos cananeus, e destruiu-os a eles e a suas cidades; e chamou o nome daquele lugar Hormá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'E partiram do monte de Hor, caminho do mar Vermelho, para rodear a terra de Edom; e abateu-se o ânimo do povo pelo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'E falou o povo contra Deus e Moisés: Por que nos fizeste subir do Egito para que morrêssemos neste deserto? que nem há pão, nem água, e nossa alma tem ódio deste pão tão miserável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'E o SENHOR enviou entre o povo serpentes ardentes, que mordiam ao povo: e morreu muito povo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Então o povo veio a Moisés, e disseram: Pecado temos por haver falado contra o SENHOR, e contra ti: roga ao SENHOR que tire de nós estas serpentes. E Moisés orou pelo povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'E o SENHOR disse a Moisés: Faze-te uma serpente ardente, e põe-a sobre a haste: e será que qualquer um que for mordido e olhar a ela, viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'E Moisés fez uma serpente de bronze, e a pôs sobre a haste, e foi, que quando alguma serpente mordia a algum, olhava à serpente de bronze, e vivia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'E partiram os filhos de Israel, e assentaram acampamento em Obote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'E partidos de Obote, assentaram em Ijé-Abarim, no deserto que está diante de Moabe, ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Partidos dali, assentaram no vale de Zerede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'De ali moveram, e assentaram da outra parte de Arnom, que está no deserto, e que sai do termo dos amorreus; porque Arnom é termo de Moabe, entre Moabe e os amorreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Por isso se diz no livro das batalhas do SENHOR: Vaebe em Sufa, e nos ribeiros de Arnom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'E à corrente dos ribeiros que vai a parar em Ar, e descansa no termo de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'E dali vieram a Beer: este é o poço do qual o SENHOR disse a Moisés: Junta ao povo, e lhes darei água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Então cantou Israel esta canção: Sobe, ó poço; a ele cantai:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Poço, o qual cavaram os senhores; Cavaram-no os príncipes do povo, E o legislador, com seus bordões. E do deserto partiram para Matana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'E de Mataná a Naaliel: e de Naaliel a Bamote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'E de Bamote ao vale que está nos campos de Moabe, e ao cume de Pisga, que está voltado a Jesimom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'E enviou Israel embaixadores a Seom, rei dos amorreus, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Deixa-me passar por tua terra: não nos desviaremos pelos campos, nem pelas vinhas; não beberemos as águas dos poços; pelo caminho real iremos, até que passemos os teus termos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mas Seom não deixou passar a Israel por seus termos: antes juntou Seom todo seu povo, e saiu contra Israel no deserto: e veio a Jaza, e lutou contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Mas Israel o feriu a fio de espada, e tomou sua terra desde Arnom até Jaboque, até os filhos de Amom: porque o termo dos filhos de Amom era forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'E tomou Israel todas estas cidades: e habitou Israel em todas as cidades dos amorreus, em Hesbom e em todas suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Porque Hesbom era a cidade de Seom, rei dos amorreus; o qual havia tido guerra antes com o rei de Moabe, e tomado de seu poder toda a sua terra até Arnom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Portanto, dizem os proverbistas: Vinde a Hesbom, Edifique-se e repare-se a cidade de Seom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Que fogo saiu de Hesbom, E chama da cidade de Seom, E consumiu a Ar de Moabe, aos senhores dos altos de Arnom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Ai de ti, Moabe! Pereceste, povo de Camos: Pôs seus filhos em fuga, E suas filhas em cativeiro, por Seom rei dos amorreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Mas devastamos o reino deles; pereceu Hesbom até Dibom, E destruímos até Nofá e Medeba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Assim habitou Israel na terra dos amorreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'E enviou Moisés a reconhecer a Jazer; e tomaram suas aldeias, e expulsaram aos amorreus que estavam ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'E voltaram, e subiram caminho de Basã. E Ogue, rei de Basã, ele e todo o seu povo, saíram contra eles, para lutar em Edrei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Então o SENHOR disse a Moisés: Não tenhas medo dele, que em tua mão o dei, a o e a todo seu povo, e a sua terra; e farás dele como fizeste de Seom, rei dos amorreus, que habitava em Hesbom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'E feriram a ele, e a seus filhos, e a toda sua gente, sem que lhe restasse um, e possuíram sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Depois os filhos de Israel partiram, e se assentaram nos campos de Moabe, desta parte do Jordão de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'E viu Balaque, filho de Zipor, tudo o que Israel havia feito aos amorreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'E Moabe temeu muito por causa do povo que era muito; e angustiou-se Moabe por causa dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'E disse Moabe aos anciãos de Midiã: Agora lamberá esta gente todos nossos entornos, como lambe o boi a grama do campo. E Balaque, filho de Zipor, era então rei de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Portanto enviou mensageiros a Balaão filho de Beor, a Petor, que está junto ao rio na terra dos filhos de seu povo, para que o chamassem, dizendo: Um povo saiu do Egito, e eis que cobre a face da terra, e habita diante de mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Vem pois agora, te rogo, amaldiçoa para mim este povo, porque é mais forte que eu: talvez poderei eu feri-lo, e lançá-lo da terra: que eu sei que o que tu abençoares, será bendito, e o que tu amaldiçoares, será maldito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'E foram os anciãos de Moabe e os anciãos de Midiã, com o pagamento pela adivinhação em sua mão, e chegaram a Balaão, e lhe disseram as palavras de Balaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'E ele lhes disse: Repousai aqui esta noite, e eu vos referirei as palavras, como o SENHOR me falar. Assim os príncipes de Moabe se restaram com Balaão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'E veio Deus a Balaão, e disse-lhe: Que homens são estes que estão contigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'E Balaão respondeu a Deus: Balaque filho de Zipor, rei de Moabe, enviou a mim dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Eis que este povo que saiu do Egito, cobre a face da terra: vem pois agora, e amaldiçoa-o para mim; talvez poderei lutar com ele, e expulsá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Então disse Deus a Balaão: Não vás com eles, nem amaldiçoes ao povo; porque é bendito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Assim Balaão se levantou pela manhã, e disse aos príncipes de Balaque: Voltai-vos à vossa terra, porque o SENHOR não me quer deixar ir convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'E os príncipes de Moabe se levantaram, e vieram a Balaque, e disseram: Balaão não quis vir conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'E voltou Balaque a enviar outra vez mais príncipes, e mais nobres que os outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Os quais vieram a Balaão, e disseram-lhe: Assim diz Balaque, filho de Zipor: Rogo-te que não deixes de vir a mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Porque sem dúvida te honrarei muito, e farei tudo o que me disseres: vem pois agora, almaldiçoa para mim a este povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'E Balaão respondeu, e disse aos servos de Balaque: Ainda que Balaque me desse sua casa cheia de prata e ouro, não posso transgredir a palavra do SENHOR meu Deus, para fazer coisa pequena nem grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Rogo-vos, portanto, agora, que repouseis aqui esta noite, para que eu saiba que me volta a dizer o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'E veio Deus a Balaão de noite, e disse-lhe: Se homens vierem a te chamar, levanta-te e vai com eles: porém farás o que eu te disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Assim Balaão se levantou pela manhã, e preparou sua jumenta, e foi com os príncipes de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'E o furor de Deus se acendeu porque ele ia; e o anjo do SENHOR se pôs no caminho por adversário seu. Ia, pois, ele montado sobre sua jumenta, e com ele dois servos seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'E a jumenta viu o anjo do SENHOR, que estava no caminho com sua espada exposta em sua mão; então a jumenta desviou-se do caminho, e foi pelo campo. Em seguida, Balaão espancou a jumenta para fazê-la voltar ao caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Mas o anjo do SENHOR se pôs em uma vereda de vinhas que tinha parede de uma parte e parede de outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'E quando a jumenta viu o anjo do SENHOR, apegou-se à parede, e apertou contra a parede o pé de Balaão: e ele voltou a espancá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'E o anjo do SENHOR passou mais ali, e pôs-se em um lugar estreito, onde não havia caminho para desviar-se nem à direita nem à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'E vendo a jumenta ao anjo do SENHOR, lançou-se debaixo de Balaão: e irou-se Balaão, e feriu à jumenta com um bordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Então o SENHOR abriu a boca da jumenta, a qual disse a Balaão: Que te fiz, que me feriste estas três vezes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'E Balaão respondeu à jumenta: Porque te zombaste de mim: bom seria se eu tivesse espada em minha mão, que agora te mataria!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'E a jumenta disse a Balaão: Não sou eu tua jumenta? Sobre mim montaste desde que tu me tens até hoje; costumei a fazê-lo assim contigo? E ele respondeu: Não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Então o SENHOR abriu os olhos a Balaão, e viu ao anjo do SENHOR que estava no caminho, e tinha sua espada nua em sua mão. E Balaão fez reverência, e inclinou-se sobre seu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'E o anjo do SENHOR lhe disse: Por que feriste tua jumenta estas três vezes? eis que eu saí para me opor a ti, porque teu caminho é perverso diante de mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'A jumenta me viu, e afastou-se logo de diante de mim estas três vezes: e se de mim não se houvesse afastado, eu também agora mataria a ti, e a ela deixaria viva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Então Balaão disse ao anjo do SENHOR: Pequei, que não sabia que tu te punhas diante de mim no caminho: mas agora, se te parece mal, eu me voltarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'E o anjo do SENHOR disse a Balaão: Vai com esses homens: porém a palavra que eu te disser, essa falarás. Assim Balaão foi com os príncipes de Balaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'E ouvindo Balaque que Balaão vinha, saiu a recebê-lo à cidade de Moabe, que está junto ao termo de Arnom, que é a extremidade das fronteiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'E Balaque disse a Balaão: Não enviei eu a ti a chamar-te? por que não vieste a mim? não posso eu te honrar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'E Balaão respondeu a Balaque: Eis que eu vim a ti: mas poderei agora falar alguma coisa? A palavra que Deus puser em minha boca, essa falarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'E foi Balaão com Balaque, e vieram à Quiriate-Huzote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'E Balaque fez matar bois e ovelhas, e enviou a Balaão, e aos príncipes que estavam com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'E no dia seguinte Balaque tomou a Balaão, e o fez subir aos lugares altos de Baal, e desde ali viu a extremidade do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'E Balaão disse a Balaque: Edifica para mim aqui sete altares, e prepara-me aqui sete bezerros e sete carneiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'E Balaque fez como lhe disse Balaão: e ofereceram Balaque e Balaão um bezerro e um carneiro em cada altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'E Balaão disse a Balaque: Põe-te junto a teu holocausto, e eu irei: talvez o SENHOR me virá ao encontro, e qualquer um coisa que me mostrar, eu a contarei a ti. E assim se foi só.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'E veio Deus ao encontro de Balaão, e este lhe disse: Sete altares ordenei, e em cada altar ofereci um bezerro e um carneiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'E o SENHOR pôs palavra na boca de Balaão, e disse-lhe: Volta a Balaque, e hás de falar assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'E voltou a ele, e eis que estava ele junto a seu holocausto, ele e todos os príncipes de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'E ele tomou sua parábola, e disse: De Arã me trouxe Balaque, rei de Moabe, dos montes do oriente: Vem, amaldiçoa para mim a Jacó; E vem, condena a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Por que amaldiçoarei eu ao que Deus não amaldiçoou? E por que condenarei ao que o SENHOR não condenou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Porque do cume das penhas o verei, E desde as colinas o olharei: Eis aqui um povo que habitará confiante, e não será contado entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Quem contará o pó de Jacó, Ou o número da quarta parte de Israel? Morra minha pessoa da morte dos corretos, E meu fim seja como o seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Então Balaque disse a Balaão: Que me fizeste? Tomei-te para que amaldiçoes a meus inimigos, e eis que proferiste bênçãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'E ele respondeu, e disse: Não observarei eu o que o SENHOR puser em minha boca para dizê-lo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'E disse Balaque: Rogo-te que venhas comigo a outro lugar desde o qual o vejas; sua extremidade somente verás, que não o verás todo; e desde ali me o amaldiçoarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'E levou-o ao campo de Zofim, ao cume de Pisga, e edificou sete altares, e ofereceu um bezerro e um carneiro em cada altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Então ele disse a Balaque: Põe-te aqui junto a teu holocausto, e eu irei a encontrar a Deus ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'E o SENHOR saiu ao encontro de Balaão, e pôs palavra em sua boca, e disse-lhe: Volta a Balaque, e assim dirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'E veio a ele, e eis que ele estava junto a seu holocausto, e com ele os príncipes de Moabe: e disse-lhe Balaque: Que disse o SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Então ele tomou sua parábola, e disse: Balaque, levanta-te e ouve; Escuta minhas palavras, filho de Zipor:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Deus não é homem, para que minta; nem filho de homem para que se arrependa: ele disse, e não fará?; Falou, e não o executará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Eis que, eu tomei bênção: E ele abençoou, e não poderei revogá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Não notou iniquidade em Jacó, nem viu perversidade em Israel: o SENHOR seu Deus é com ele, E júbilo de rei nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Deus os tirou do Egito; Tem forças como de boi selvagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Porque em Jacó não há agouro, nem adivinhação em Israel: Como agora, será dito de Jacó e de Israel: O que fez Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Eis que o povo, que como leão se levantará, E como leão se erguerá: Não se deitará até que coma a presa, E beba o sangue dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Então Balaque disse a Balaão: Já que não o amaldiçoas, nem tampouco o abençoes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'E Balaão respondeu, e disse a Balaque: Não te disse que tudo o que o SENHOR me disser, aquilo tenho de fazer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'E disse Balaque a Balaão: Rogo-te que venhas, te levarei a outro lugar; porventura comparecerá bem a Deus que desde ali me o amaldiçoes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'E Balaque levou a Balaão ao cume de Peor, que está voltado até Jesimom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Então Balaão disse a Balaque: Edifica para mim aqui sete altares, e prepara-me aqui sete bezerros e sete carneiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'E Balaque fez como Balaão lhe disse; e ofereceu um bezerro e um carneiro em cada altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'E quando viu Balaão que parecia bem ao SENHOR que o abençoasse a Israel, não foi, como a primeira e segunda vez, a encontro de agouros, mas sim que pôs seu rosto até o deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'E levantando seus olhos, viu a Israel alojado por suas tribos; e o espírito de Deus veio sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Então tomou sua parábola, e disse: Disse Balaão filho de Beor, E disse o homem de olhos abertos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Disse o que ouviu os ditos de Deus, O que viu a visão do Todo-Poderoso; caído, mas abertos os olhos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Quão belas são tuas tendas, ó Jacó, Tuas habitações, ó Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Como ribeiros estão estendidas, Como jardins junto ao rio, Como aloés plantados pelo SENHOR, Como cedros junto às águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'De suas mãos destilarão águas, E sua descendência será em muitas águas: E se levantará seu rei mais que Agague, E seu reino será exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Deus o tirou do Egito; Tem forças como de boi selvagem: Comerá às nações suas inimigas, E esmiuçará seus ossos, E perfurará com suas flechas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Se encurvará para deitar-se como leão, E como leoa; quem o despertará? Benditos os que te abençoarem, E malditos os que te amaldiçoarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Então se acendeu a ira de Balaque contra Balaão, e batendo suas palmas lhe disse: Para amaldiçoar a meus inimigos te chamei, e eis que os abençoaste insistentemente já três vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Foge-te, portanto, agora a teu lugar: eu disse que te honraria, mas eis que o SENHOR te privou de honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'E Balaão lhe respondeu: Não o declarei eu também a teus mensageiros que me enviaste, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Se Balaque me desse sua casa cheia de prata e ouro, eu não poderei transgredir o dito do SENHOR para fazer coisa boa nem má de minha vontade; mas o que o SENHOR falar, isso direi eu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Eis que eu me vou agora a meu povo: portanto, vem, te indicarei o que este povo há de fazer a teu povo nos últimos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'E tomou sua parábola, e disse: Disse Balaão filho de Beor, Disse o homem de olhos abertos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Disse o que ouviu os ditos do SENHOR, E o que sabe o conhecimento do Altíssimo, o que viu a visão do Todo-Poderoso; caído, mas abertos os olhos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Verei, mas não agora: O olharei, mas não de perto: Sairá estrela de Jacó, E se levantará cetro de Israel, E ferirá os cantos de Moabe, E destruirá a todos os filhos de Sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'E será tomada Edom, Será também tomada Seir por seus inimigos, E Israel se portará corajosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'E o de Jacó será dominador, E destruirá da cidade o que restar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'E vendo a Amaleque, tomou sua parábola, e disse: Amaleque, cabeça de nações; Mas seu fim perecerá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'E vendo aos queneus, tomou sua parábola, e disse: Forte é tua habitação, Põe na rocha tua ninho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Que os queneus serão expulsos, Quando Assur te levará cativo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Todavia tomou sua parábola, e disse: Ai! quem viverá quando fizer Deus estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'E virão navios da costa de Quitim, E afligirão a Assur, afligirão também a Éber: Mas ele também perecerá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Então se levantou Balaão, e se foi, e voltou-se a seu lugar: e também Balaque se foi por seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'E repousou Israel em Sitim, e o povo começou a se prostituir com as filhas de Moabe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'As quais chamaram ao povo aos sacrifícios de seus deuses: e o povo comeu, e inclinou-se a seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'E achegou-se o povo a Baal-Peor; e o furor do SENHOR se acendeu contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'E o SENHOR disse a Moisés: Toma todos os príncipes do povo, e enforca-os ao SENHOR diante do sol; e a ira do furor do SENHOR se apartará de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Então Moisés disse aos juízes de Israel: Matai cada um àqueles dos seus que se recolheram a Baal-Peor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'E eis que um homem dos filhos de Israel veio e trouxe uma midianita a seus irmãos, à vista de Moisés e de toda a congregação dos filhos de Israel, chorando eles à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'E viu-o Fineias, filho de Eleazar, filho de Arão o sacerdote, e levantou-se do meio da congregação, e tomou uma lança em sua mão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'E foi atrás do homem de Israel à tenda, e perfurou com a lança a ambos, ao homem de Israel, e à mulher por seu ventre. E cessou a mortandade dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'E morreram daquela mortandade vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Então o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Fineias, filho de Eleazar, filho de Arão o sacerdote, fez afastar meu furor dos filhos de Israel, levado de zelo entre eles: pelo qual eu não consumi em meu zelo aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Portanto dize lhes: Eis que eu estabeleço meu pacto de paz com ele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'E terá ele, e sua descendência depois dele, o pacto do sacerdócio perpétuo; porquanto teve zelo por seu Deus, e fez expiação pelos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'E o nome do homem morto, que foi morto com a midianita, era Zinri filho de Salu, chefe de uma família da tribo de Simeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'E o nome da mulher midianita morta, era Cosbi, filha de Zur, príncipe de povos, pai de família em Midiã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Sereis hostis aos midianitas, e os ferireis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Porquanto eles vos afligiram com suas astúcias, com que vos enganaram no negócio de Peor, e no negócio de Cosbi, filha do príncipe de Midiã, sua irmã, a qual foi morta no dia da mortandade por causa de Peor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'E aconteceu depois da mortandade, que o SENHOR falou a Moisés, e a Eleazar filho do sacerdote Arão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Tomai a soma de toda a congregação dos filhos de Israel, de vinte anos acima, pelas casas de seus pais, todos os que possam sair à guerra em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'E Moisés e Eleazar o sacerdote falaram com eles nos campos de Moabe, junto ao Jordão de Jericó, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Contareis o povo de vinte anos acima, como mandou o SENHOR a Moisés e aos filhos de Israel, que haviam saído da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Rúben primogênito de Israel: os filhos de Rúben: Enoque, do qual era a família dos enoquitas; de Palu, a família dos paluítas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'De Hezrom, a família dos hezronitas; de Carmi, a família dos carmitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Estas são as famílias dos rubenitas: e seus contados foram quarenta e três mil setecentos e trinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'E os filhos de Palu: Eliabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'E os filhos de Eliabe: Nemuel, e Datã, e Abirão. Estes Datã e Abirão foram os do conselho da congregação, que fizeram o motim contra Moisés e Arão com a companhia de Coré, quando se amotinaram contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Que a terra abriu sua boca e tragou a eles e a Coré, quando aquela companhia morreu, quando consumiu o fogo duzentos e cinquenta homens, os quais foram por sinal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Mas os filhos de Coré não morreram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Os filhos de Simeão por suas famílias: de Nemuel, a família dos nemuelitas; de Jamim, a família dos jaminitas; de Jaquim, a família dos jaquinitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'De Zerá, a família dos zeraítas; de Saul, a família dos saulitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Estas são as famílias dos simeonitas, vinte e dois mil e duzentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Os filhos de Gade por suas famílias: de Zefom, a família dos zefonitas; de Hagi, a família dos hagitas; de Suni, a família dos sunitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'De Ozni, a família dos oznitas; de Eri, a família dos eritas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'De Arodi, a família dos aroditas; de Areli, a família dos arelitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Estas são as famílias de Gade, por seus contados, quarenta mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Os filhos de Judá: Er e Onã; e Er e Onã morreram na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'E foram os filhos de Judá por suas famílias: de Selá, a família dos selanitas; de Perez, a família dos perezitas; de Zerá, a família dos zeraítas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'E foram os filhos de Perez: de Hezrom, a família dos hezronitas; de Hamul, a família dos hamulitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Estas são as famílias de Judá, por seus contados, setenta e seis mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Os filhos de Issacar por suas famílias: de Tola, a família dos tolaítas; de Puá a família dos puvitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'De Jasube, a família dos jasubitas; de Sinrom, a família dos sinronitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Estas são as famílias de Issacar, por seus contados, sessenta e quatro mil e trezentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Os filhos de Zebulom por suas famílias: de Serede, a família dos sereditas; de Elom, a família dos elonitas; de Jaleel, a família dos jaleelitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Estas são as famílias dos zebulonitas, por seus contados, sessenta mil e quinhentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Os filhos de José por suas famílias: Manassés e Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Os filhos de Manassés: de Maquir, a família dos maquiritas; e Maquir gerou a Gileade; de Gileade, a família dos gileaditas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Estes são os filhos de Gileade: de Jezer, a família dos jezeritas; de Heleque, a família dos helequitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'De Asriel, a família dos asrielitas: de Siquém, a família dos siquemitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'De Semida, a família dos semidaítas; de Héfer, a família dos heferitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'E Zelofeade, filho de Héfer, não teve filhos somente filhas: e os nomes das filhas de Zelofeade foram Maalá, e Noa, e Hogla, e Milca, e Tirza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Estas são as famílias de Manassés; e seus contados, cinquenta e dois mil e setecentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Estes são os filhos de Efraim por suas famílias: de Sutela, a família dos sutelaítas; de Bequer, a família dos bequeritas; de Taã, a família dos taanitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'E estes são os filhos de Sutela: de Erã, a família dos eranitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Estas são as famílias dos filhos de Efraim, por seus contados, trinta e dois mil e quinhentos. Estes são os filhos de José por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Os filhos de Benjamim por suas famílias: de Belá, a família dos belaítas; de Asbel, a família dos asbelitas; de Airã, a família dos airamitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'De Sufã, a família dos sufamitas; de Hufã, a família dos hufamitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'E os filhos de Belá foram Arde e Naamã: de Arde, a família dos arditas; de Naamã, a família dos naamanitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Estes são os filhos de Benjamim por suas famílias; e seus contados, quarenta e cinco mil e seiscentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Estes são os filhos de Dã por suas famílias: de Suã, a família dos suamitas. Estas são as famílias de Dã por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Todas as famílias dos suamitas, por seus contados, sessenta e quatro mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Os filhos de Aser por suas famílias: de Imna, a família dos imnaítas; de Isvi, a família dos isvitas; de Berias, a família dos beriitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Os filhos de Berias: de Héber, a família dos heberitas; de Malquiel, a família dos malquielitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'E o nome da filha de Aser foi Sera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Estas são as famílias dos filhos de Aser, por seus contados, cinquenta e três mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Os filhos de Naftali por suas famílias: de Jazeel, a família dos jazeelitas; de Guni, a família dos gunitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'De Jezer, a família dos jezeritas; de Silém, a família dos silemitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Estas são as famílias de Naftali por suas famílias; e seus contados, quarenta e cinco mil e quatrocentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Estes são os contados dos filhos de Israel, seiscentos e um mil setecentos e trinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'A estes se repartirá a terra em herança, pela conta dos nomes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Aos mais darás maior herança, e aos menos menor; e a cada um se lhe dará sua herança conforme seus contados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Porém a terra será repartida por sorteio; e pelos nomes das tribos de seus pais herdarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Conforme a sorte será repartida sua herança entre o grande e o pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'E os contados dos levitas por suas famílias são estes: de Gérson, a família dos gersonitas; de Coate, a família dos coatitas; de Merari, a família dos meraritas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Estas são as famílias dos levitas: a família dos libnitas, a família dos hebronitas, a família dos malitas, a família dos musitas, a família dos coraítas. E Coate gerou a Anrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'E a mulher de Anrão se chamou Joquebede, filha de Levi, a qual nasceu a Levi no Egito: esta deu à luz de Anrão a Arão e a Moisés, e a Miriã sua irmã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'E a Arão nasceram Nadabe e Abiú, Eleazar e Itamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Mas Nadabe e Abiú morreram, quando ofereceram fogo estranho diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'E os contados dos levitas foram vinte e três mil, todos homens de um mês acima: porque não foram contados entre os filhos de Israel, porquanto não lhes havia de ser dada herança entre os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Estes são os contados por Moisés e Eleazar o sacerdote, os quais contaram os filhos de Israel nos campos de Moabe, junto ao Jordão de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'E entre estes ninguém havia dos contados por Moisés e Arão o sacerdote, os quais contaram aos filhos de Israel no deserto de Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Porque o SENHOR lhes disse: Hão de morrer no deserto: e não restou homem deles, a não ser Calebe filho de Jefoné, e Josué filho de Num.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'E as filhas de Zelofeade, filho de Héfer, filho de Gileade, filho de Maquir, filho de Manassés, das famílias de Manassés, filho de José, os nomes das quais eram Maalá, e Noa, e Hogla, e Milca, e Tirza, chegaram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'E apresentaram-se diante de Moisés, e diante do sacerdote Eleazar, e diante dos príncipes, e de toda a congregação, à porta do tabernáculo do testemunho, e disseram:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Nosso pai morreu no deserto, o qual não esteve na junta que se reuniu contra o SENHOR na companhia de Coré: mas sim que em seu pecado morreu, e não teve filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Por que será tirado o nome de nosso pai dentre sua família, por não haver tido filho? Dá-nos herança entre os irmãos de nosso pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'E Moisés levou sua causa diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'E o SENHOR respondeu a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Bem dizem as filhas de Zelofeade: hás de dar-lhes possessão de herança entre os irmãos de seu pai; e passarás a herança de seu pai a elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'E aos filhos de Israel falarás, dizendo: Quando alguém morrer sem filhos, passareis sua herança à sua filha:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'E se não tiver filha, dareis sua herança a seus irmãos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'E se não tiver irmãos, dareis sua herança aos irmãos de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'E se seu pai não tiver irmãos, dareis sua herança a seu parente mais próximo de sua linhagem, o qual a possuirá: e será aos filhos de Israel por estatuto de regulamento, como o SENHOR mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'E o SENHOR disse a Moisés: Sobe a este monte Abarim, e verás a terra que dei aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'E depois que a houverdes visto, tu também serás recolhido ao teus povo, como foi reunido o teu irmão Arão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'pois fostes rebeldes no deserto de Zim, no conflito da congregação, ao meu mandado de me santificar nas águas à vista deles. Essas são as águas do conflito de Cades no deserto de Zim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Então Moisés respondeu ao SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Que o SENHOR, Deus dos espíritos de toda carne, ponha um homem sobre a congregação,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'que saia diante deles, que entre diante deles, que os faça sair e os faça entrar; para que a congregação do SENHOR não seja como ovelhas sem pastor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'E o SENHOR disse a Moisés: Toma a Josué filho de Num, homem no qual há espírito, e porás tua mão sobre ele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'E o porás diante de Eleazar o sacerdote, e diante de toda a congregação; e lhe darás ordens em presença deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'E porás de tua dignidade sobre ele, para que toda a congregação dos filhos de Israel lhe obedeçam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'E ele estará diante de Eleazar o sacerdote, e a ele perguntará pelo juízo do Urim diante do SENHOR: pelo dito dele sairão, e pelo dito dele entrarão, ele, e todos os filhos de Israel com ele, e toda a congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'E Moisés fez como o SENHOR lhe havia mandado; que tomou a Josué, e lhe pôs diante de Eleazar o sacerdote, e de toda a congregação:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'E pôs sobre ele suas mãos, e deu-lhe ordens, como o SENHOR havia mandado por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Manda aos filhos de Israel, e dize-lhes: Da minha oferta, do meu pão com as minhas ofertas de queima em cheiro a mim agradável, tereis cuidado, para as oferecer a mim no tempo devido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'E lhes dirás: Esta é a oferta de queima que oferecereis ao SENHOR: dois cordeiros sem mácula de ano, cada dia, será o holocausto contínuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Um cordeiro oferecerás pela manhã, e o outro cordeiro oferecerás entre as duas tardes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'E a décima de um efa de flor de farinha, amassada com uma quarta parte de um him de azeite prensado, em oferta de cereais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'É holocausto contínuo, que foi feito no monte Sinai em cheiro suave, oferta de queima ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'E sua libação, a quarta parte de um him com cada cordeiro: derramarás libação de superior vinho ao SENHOR no santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'E oferecerás o segundo cordeiro entre as duas tardes: conforme a oferta da manhã, e conforme sua libação oferecerás, oferta de queima em cheiro suave ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Mas no dia do sábado dois cordeiros de ano sem defeito, e duas dízimas de flor de farinha amassada com azeite, por oferta de cereais, com sua libação:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'É o holocausto do sábado em cada sábado, além do holocausto contínuo e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'E nos princípios de vossos meses oferecereis em holocausto ao SENHOR dois bezerros das vacas, e um carneiro, e sete cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'E três dízimas de flor de farinha amassada com azeite, por oferta de cereais com cada bezerro; e duas dízimas de flor de farinha amassada com azeite, por oferta de cereais com cada carneiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'E uma dízima de flor de farinha amassada com azeite, em oferta de cereais com cada cordeiro: holocausto de cheiro suave, oferta de queima ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'E suas libações de vinho, meio him com cada bezerro, e o terço de um him com cada carneiro, e a quarta parte de um him com cada cordeiro. Este é o holocausto de cada mês por todos os meses do ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'E um bode macho em expiação se oferecerá ao SENHOR, além do holocausto contínuo com sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Mas no mês primeiro, aos catorze do mês será a páscoa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'E aos quinze dias deste mês, a solenidade: por sete dias se comerão pães ázimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'No primeiro dia, santa convocação; nenhuma obra servil fareis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'E oferecereis por oferta de queima em holocausto ao SENHOR dois bezerros das vacas, e um carneiro, e sete cordeiros de ano: sem defeito os tomareis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'E sua oferta de cereais de farinha amassada com azeite: três dízimas com cada bezerro, e duas dízimas com cada carneiro oferecereis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Com cada um dos sete cordeiros oferecereis uma dízima;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'E um bode macho por expiação, para reconciliar-vos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Isto oferecereis além do holocausto da manhã, que é o holocausto contínuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Conforme isto oferecereis cada um dos sete dias, comida e oferta de queima em cheiro suave ao SENHOR; oferecer-se há, além do holocausto contínuo, com sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'E no sétimo dia tereis santa convocação: nenhuma obra servil fareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Também o dia das primícias, quando oferecerdes oferta de cereais nova ao SENHOR em vossas semanas, tereis santa convocação: nenhuma obra servil fareis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'E oferecereis em holocausto, em cheiro suave ao SENHOR, dois bezerros das vacas, um carneiro, sete cordeiros de ano:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'E a oferta de cereais deles, flor de farinha amassada com azeite, três dízimas com cada bezerro, duas dízimas com cada carneiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Com cada um dos sete cordeiros uma dízima;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Um bode macho, para fazer expiação por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Os oferecereis, além do holocausto contínuo com suas ofertas de cereais, e suas libações: sem defeito os tomareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'E no sétimo mês, ao primeiro do mês tereis santa convocação: nenhuma obra servil fareis; vos será dia de soar as trombetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'E oferecereis holocausto por cheiro suave ao SENHOR, um bezerro das vacas, um carneiro, sete cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'E a oferta de cereais deles, de flor de farinha amassada com azeite, três dízimas com cada bezerro, duas dízimas com cada carneiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'E com cada um dos sete cordeiros, uma dízima;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'E um bode macho por expiação, para reconciliar-vos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Além do holocausto do mês, e sua oferta de cereais, e o holocausto contínuo e sua oferta de cereais, e suas libações, conforme sua lei, por oferta de queima ao SENHOR em cheiro suave.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'E no dez deste mês sétimo tereis santa convocação, e afligireis vossas almas: nenhuma obra fareis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'E oferecereis em holocausto ao SENHOR por cheiro suave, um bezerro das vacas, um carneiro, sete cordeiros de ano; sem defeito os tomareis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'E suas ofertas de cereais, flor de farinha amassada com azeite, três dízimas com cada bezerro, duas dízimas com cada carneiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'E com cada um dos sete cordeiros, uma dízima;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Um bode macho por expiação: além da oferta das expiações pelo pecado, e do holocausto contínuo, e de suas ofertas de cereais, e de suas libações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Também aos quinze dias do mês sétimo tereis santa convocação; nenhuma obra servil fareis, e celebrareis solenidade ao SENHOR por sete dias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'E oferecereis em holocausto, em oferta de queima ao SENHOR em cheiro suave, treze bezerros das vacas, dois carneiros, catorze cordeiros de ano: hão de ser sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'E as ofertas de cereais deles, de flor de farinha amassada com azeite, três dízimas com cada um dos treze bezerros, duas dízimas com cada um dos dois carneiros,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'E com cada um dos catorze cordeiros, uma dízima;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'E um bode macho por expiação: além do holocausto contínuo, sua oferta de cereais e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'E no segundo dia, doze bezerros das vacas, dois carneiros, catorze cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'E um bode macho por expiação: além do holocausto contínuo, e sua oferta de cereais e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'E no dia terceiro, onze bezerros, dois carneiros, catorze cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'E um bode macho por expiação: além do holocausto contínuo, e sua presente e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'E no quarto dia, dez bezerros, dois carneiros, catorze cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'E um bode macho por expiação: além do holocausto contínuo, sua oferta de cereais e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'E no quinto dia, nove bezerros, dois carneiros, catorze cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'E um bode macho por expiação: além do holocausto contínuo, sua oferta de cereais e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'E no sexto dia, oito bezerros, dois carneiros, catorze cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'E um bode macho por expiação: além do holocausto contínuo, sua oferta de cereais e suas libações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'E no sétimo dia, sete bezerros, dois carneiros, catorze cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'E um bode macho por expiação: além do holocausto contínuo, com sua oferta de cereais e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'No oitavo dia tereis solenidade: nenhuma obra servil fareis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'E oferecereis em holocausto, em oferta de queima de cheiro suave ao SENHOR, um novilho, um carneiro, sete cordeiros de ano sem defeito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Suas ofertas de cereais e suas libações com o novilho, com o carneiro, e com os cordeiros, segundo o número deles, conforme a lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'E um bode macho por expiação: além do holocausto contínuo, com sua oferta de cereais e sua libação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Estas coisas oferecereis ao SENHOR em vossas solenidades, além de vossos votos, e de vossas ofertas livres, para vossos holocaustos, e para vossas ofertas de cereais, e para vossas libações e para vossas ofertas pacíficas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'E Moisés disse aos filhos de Israel, conforme tudo o que o SENHOR lhe havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'E falou Moisés aos príncipes das tribos dos filhos de Israel, dizendo: Isto é o que o SENHOR mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Quando alguém fizer voto ao SENHOR, ou fizer juramento ligando sua alma com obrigação, não violará sua palavra: fará conforme tudo o que saiu de sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Mas a mulher, quando fizer voto ao SENHOR, e se ligar com obrigação em casa de seu pai, em sua juventude;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Se seu pai ouvir seu voto, e a obrigação com que ligou sua alma, e seu pai calar a isso, todos os votos dela serão firmes, e toda obrigação com que houver ligado sua alma, firme será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Mas se seu pai lhe vedar no dia que ouvir todos os seus votos e suas obrigações, com que ela houver ligado sua alma, não serão firmes; e o SENHOR a perdoará, porquanto seu pai lhe vedou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Porém se for casada, e fizer votos, ou pronunciar de seus lábios coisa com que obriga sua alma;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Se seu marido o ouvir, e quando o ouvir calar a isso, os votos dela serão firmes, e a obrigação com que ligou sua alma, firme será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Porém se quando seu marido o ouviu, lhe vedou, então o voto que ela fez, e o que pronunciou de seus lábios com que ligou sua alma, será nulo; e o SENHOR o perdoará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Mas todo voto de viúva, ou repudiada, com que ligar sua alma, será firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'E se houver feito voto em casa de seu marido, e houver ligado sua alma com obrigação de juramento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Se seu marido ouviu, e calou a isso, e não lhe vedou; então todos os seus votos serão firmes, e toda obrigação com que houver ligado sua alma, firme será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Mas se seu marido os anulou no dia que os ouviu; tudo o que saiu de seus lábios quanto a seus votos, e quanto à obrigação de sua alma, será nulo; seu marido os anulou, e o SENHOR a perdoará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Todo voto, ou todo juramento obrigando-se a afligir a alma, seu marido o confirmará, ou seu marido o anulará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Porém se seu marido calar a isso de dia em dia, então confirmou todos os seus votos, e todas as obrigações que estão sobre ela: confirmou-as, porquanto calou a isso o dia que o ouviu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Mas se as anular depois de havê-las ouvido, então ele levará o pecado dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Estas são as ordenanças que o SENHOR mandou a Moisés entre o homem e sua mulher, entre o pai e sua filha, durante sua juventude em casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Faze a vingança dos filhos de Israel sobre os midianitas; depois serás recolhido a teus povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Então Moisés falou ao povo, dizendo: Armai-vos alguns de vós para a guerra, e irão contra Midiã, e farão a vingança do SENHOR em Midiã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Mil de cada tribo de todas as tribos dos filhos de Israel, enviareis à guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Assim foram dados dos milhares de Israel, mil cada tribo, doze mil a ponto de guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'E Moisés os enviou à guerra: mil cada tribo enviou: e Fineias, filho de Eleazar sacerdote, foi à guerra com os santos instrumentos, com as trombetas em sua mão para tocar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'E lutaram contra Midiã, como o SENHOR o mandou a Moisés, e mataram a todo homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Mataram também, entre os mortos deles, aos reis de Midiã: Evi, e Requém, e Zur, e Hur, e Reba, cinco reis de Midiã; a Balaão também, filho de Beor, mataram à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'E levaram cativas os filhos de Israel as mulheres dos midianitas, e suas crianças e todos suas animais, e todos os seus gados; e arrebataram todos os seus pertences.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'E abrasaram com fogo todas suas cidades, aldeias e castelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'E tomaram todo o despojo, e toda a presa, tanto de homens como de animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'E trouxeram a Moisés, e a Eleazar o sacerdote, e à congregação dos filhos de Israel, os cativos e a presa e os despojos, ao acampamento nas planícies de Moabe, que estão junto ao Jordão de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'E saíram Moisés e Eleazar o sacerdote, e todos os príncipes da congregação, a recebê-los fora do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'E irou-se Moisés contra os capitães do exército, contra os comandantes de mil e comandantes de cem que voltavam da guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'E disse-lhes Moisés: Todas as mulheres preservastes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Eis que elas foram aos filhos de Israel, por conselho de Balaão, para causar transgressão contra o SENHOR no negócio de Peor; pelo que houve mortandade na congregação do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Matai, pois, agora todos os machos entre as crianças: matai também toda mulher que tenha conhecido homem carnalmente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'E todas as meninas entre as mulheres, que não tenham conhecido ajuntamento de homem, vos preservareis vivas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'E vós ficai fora do acampamento sete dias: e todos os que houverem matado pessoa, e qualquer um que houver tocado morto, vos purificareis ao terceiro e ao sétimo dia, vós e vossos cativos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Também purificareis toda roupa, e todo artigo de peles, e toda obra de pelos de cabra, e todo vaso de madeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'E Eleazar o sacerdote disse aos homens de guerra que vinham da guerra: Esta é a ordenança da lei que o SENHOR mandou a Moisés:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Certamente o ouro, e a prata, bronze, ferro, estanho, e chumbo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Tudo o que resiste ao fogo, por fogo o fareis passar, e será limpo, ainda que nas águas de purificação haverá de purificar-se: mas fareis passar por água tudo o que não aguenta o fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Além disso lavareis vossas roupas no sétimo dia, e assim sereis limpos; e depois entrareis no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Toma a contagem da presa que se fez, tanto das pessoas como dos animais, tu e o sacerdote Eleazar, e os chefes dos pais da congregação:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'E partirás pela metade a presa entre os que lutaram, os que saíram à guerra, e toda a congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'E separarás para o SENHOR o tributo dos homens de guerra, que saíram à guerra: de quinhentos um, tanto das pessoas como dos bois, dos asnos, e das ovelhas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Da metade deles o tomarás; e darás a Eleazar o sacerdote a oferta do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'E da metade pertencente aos filhos de Israel tomarás um de cinquenta, das pessoas, dos bois, dos asnos, e das ovelhas, de todo animal; e os darás aos levitas, que têm a guarda do tabernáculo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'E fizeram Moisés e Eleazar o sacerdote como o SENHOR mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'E foi a presa, o resto da presa que tomaram os homens de guerra, seiscentas e setenta e cinco mil ovelhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'E setenta e dois mil bois,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'E setenta e um mil asnos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'E quanto às pessoas, de mulheres que não conheciam ajuntamento de homem, ao todo trinta e duas mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'E a metade, a parte dos que haviam saído à guerra, foi o número de trezentas trinta e sete mil e quinhentas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'E o tributo para o SENHOR das ovelhas foi seiscentas e setenta e cinco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'E dos bois, trinta e seis mil: e deles o tributo para o SENHOR, setenta e dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'E dos asnos, trinta mil e quinhentos: e deles o tributo para o SENHOR, setenta e um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'E das pessoas, dezesseis mil: e delas o tributo para o SENHOR, trinta e duas pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'E deu Moisés o tributo, por elevada oferta ao SENHOR, a Eleazar o sacerdote, como o SENHOR o mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'E da metade para os filhos de Israel, que separou Moisés dos homens que haviam ido à guerra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(A metade para a congregação foi: das ovelhas, trezentas e trinta e sete mil e quinhentas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'E dos bois, trinta e seis mil;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'E dos asnos, trinta mil e quinhentos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'E das pessoas, dezesseis mil:)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Da metade, pois, para os filhos de Israel tomou Moisés um de cada cinquenta, tanto das pessoas como dos animais, e deu-os aos levitas, que tinham a guarda do tabernáculo do SENHOR; como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'E chegaram a Moisés os chefes dos milhares daquele exército, os comandantes de mil e comandantes de cem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'E disseram a Moisés: Teus servos tomaram a soma dos homens de guerra que estão em nosso poder, e nenhum faltou de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Pelo qual temos oferecido ao SENHOR oferta, cada um do que achou, objetos de ouro, braceletes, pulseiras, anéis, pendentes, e correntes, para fazer expiação por nossas almas diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'E Moisés e o sacerdote Eleazar receberam o ouro deles, joias, todas elaboradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'E todo o ouro da oferta que ofereceram ao SENHOR dos comandantes de mil e comandantes de cem, foi dezesseis mil setecentos e cinquenta siclos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Os homens do exército haviam despojado cada um para si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Receberam, pois, Moisés e o sacerdote Eleazar, o ouro dos comandantes de mil e comandantes de cem, e trouxeram-no ao tabernáculo do testemunho, por memória dos filhos de Israel diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'E os filhos de Rúben e os filhos de Gade tinham uma muito grande abundância de gado; os quais vendo a terra de Jazer e de Gileade, pareceu-lhes o país lugar de gado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'E vieram os filhos de Gade e os filhos de Rúben, e falaram a Moisés, e a Eleazar o sacerdote, e aos príncipes da congregação, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarote, e Dibom, e Jazer, e Ninra, e Hesbom, e Eleale, e Sebã, e Nebo, e Beom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'A terra que o SENHOR feriu diante da congregação de Israel, é terra de gado, e teus servos têm gado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Portanto, disseram, se achamos favor em teus olhos, seja dada esta terra a teus servos em herança, e não nos faças passar o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'E respondeu Moisés aos filhos de Gade e aos filhos de Rúben: Virão vossos irmãos à guerra, e vós ficareis aqui?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'E por que desencorajais o ânimo dos filhos de Israel, para que não passem à terra que lhes deu o SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Assim fizeram vossos pais, quando os enviei desde Cades-Barneia para que vissem a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Que subiram até o vale de Escol, e depois que viram a terra, preocuparam o ânimo dos filhos de Israel, para que não viessem à terra que o SENHOR lhes havia dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'E o furor do SENHOR se acendeu então, e jurou dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Os homens que subiram do Egito de vinte anos acima não verão a terra pela qual jurei a Abraão, Isaque, e Jacó, pois não me seguiram por completo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'exceto Calebe, filho do quenezeu Jefoné, e Josué filho de Num, que seguiram por completo ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'E o furor do SENHOR se acendeu em Israel, e os fez andar errantes quarenta anos pelo deserto, até que foi acabada toda aquela geração, que havia feito mal diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'E eis que vós sucedestes em lugar de vossos pais, descendência de homens pecadores, para acrescentar ainda à ira do SENHOR contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Se vos deixardes de segui-lo, ele voltará outra vez a deixar-vos no deserto, e destruireis a todo este povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Então eles se achegaram a ele e disseram: Edificaremos aqui currais para nosso gado, e cidades para nossas crianças;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'E nós nos armaremos, e iremos com empenho diante dos filhos de Israel, até que os ponhamos em seu lugar: e nossas crianças ficarão em cidades fortes por causa dos moradores do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Não voltaremos a nossas casas até que os filhos de Israel possuam cada um sua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Porque não tomaremos herança com eles ao outro lado do Jordão nem adiante, porquanto teremos já nossa herança da outra parte do Jordão ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Então lhes respondeu Moisés: Se o fizerdes assim, se vos preparardes para ir diante do SENHOR à guerra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'E passardes todos vós armados o Jordão diante do SENHOR, até que tenha expulsado a seus inimigos de diante de si,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'E seja o país subjugado diante do SENHOR; logo voltareis, e sereis livres de culpa para com o SENHOR, e para com Israel; e esta terra será vossa em herança diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mas se assim não o fizerdes, eis que havereis pecado ao SENHOR; e sabei que vos alcançará vosso pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Edificai-vos cidades para vossas crianças, e currais para vossas ovelhas, e fazei o que saiu de vossa boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'E falaram os filhos de Gade e os filhos de Rúben a Moisés, dizendo: Teus servos farão como meu senhor mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Nossas crianças, nossas mulheres, nossos gados, e todos nossos animais, estarão aí nas cidades de Gileade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'E teus servos, armados todos de guerra, passarão diante do SENHOR à guerra, da maneira que meu senhor disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Então os encomendou Moisés a Eleazar o sacerdote, e a Josué filho de Num, e aos príncipes dos pais das tribos dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'E disse-lhes Moisés: Se os filhos de Gade e os filhos de Rúben, passarem convosco o Jordão, armados todos de guerra diante do SENHOR, logo que o país for subjugado diante de vós, lhes dareis a terra de Gileade em possessão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Mas se não passarem armados convosco, então terão possessão entre vós na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'E os filhos de Gade e os filhos de Rúben responderam, dizendo: Faremos o que o SENHOR disse a teus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Nós passaremos armados diante do SENHOR à terra de Canaã, e a possessão de nossa herança será desta parte do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Assim lhes deu Moisés aos filhos de Gade e aos filhos de Rúben, e à meia tribo de Manassés filho de José, o reino de Seom rei amorreu, e o reino de Ogue rei de Basã, a terra com suas cidades e termos, as cidades do país ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'E os filhos de Gade edificaram a Dibom, e a Atarote, e a Aroer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'E a Atarote-Sofã, e a Jazer, e a Jogbeá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'E a Bete-Ninra, e a Bete-Harã: cidades fortificadas, e também currais para ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'E os filhos de Rúben edificaram a Hesbom, e a Eleale, e a Quiriataim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'E a Nebo, e a Baal-Meom, (mudados os nomes), e a Sibma: e puseram nomes às cidades que edificaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'E os filhos de Maquir filho de Manassés foram a Gileade, e tomaram-na, e expulsaram aos amorreus que estavam nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'E Moisés deu Gileade a Maquir filho de Manassés, o qual habitou nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Também Jair filho de Manassés foi e tomou suas aldeias, e pôs-lhes por nome Havote-Jair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Também Noba foi e tomou a Quenate e suas aldeias, e chamou-lhe Noba, conforme seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Estas são as jornadas dos filhos de Israel, os quais saíram da terra do Egito por seus esquadrões, sob a condução de Moisés e Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'E Moisés escreveu suas saídas conforme suas jornadas por ordem do SENHOR. Estas, pois, são suas jornadas conforme suas partidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'De Ramessés partiram no mês primeiro, aos quinze dias do mês primeiro: no segundo dia da páscoa saíram os filhos de Israel com mão alta, à vista de todos os egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Estavam enterrando os egípcios os que o SENHOR havia matado deles, a todo primogênito; havendo o SENHOR feito também juízos em seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Partiram, pois, os filhos de Israel de Ramessés, e assentaram acampamento em Sucote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'E partindo de Sucote, assentaram em Etã, que está ao extremo do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'E partindo de Etã, voltaram sobre Pi-Hairote, que está diante de Baal-Zefom, e assentaram diante de Migdol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'E partindo de Pi-Hairote, passaram por meio do mar ao deserto, e andaram caminho de três dias pelo deserto de Etã, e assentaram em Mara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'E partindo de Mara, vieram a Elim, de onde havia doze fontes de águas, e setenta palmeiras; e assentaram ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'E partidos de Elim, assentaram junto ao mar Vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'E partidos do mar Vermelho, assentaram no deserto de Sim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'E partidos do deserto de Sim, assentaram em Dofca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'E partidos de Dofca, assentaram em Alus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'E partidos de Alus, assentaram em Refidim, onde o povo não teve águas para beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'E partidos de Refidim, assentaram no deserto de Sinai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'E partidos do deserto de Sinai, assentaram em Quibrote-Taavá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'E partidos de Quibrote-Taavá, assentaram em Hazerote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'E partidos de Hazerote, assentaram em Ritmá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'E partidos de Ritmá, assentaram em Rimom-Perez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'E partidos de Rimom-Perez, assentaram em Libna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'E partidos de Libna, assentaram em Rissa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'E partidos de Rissa, assentaram em Queelata,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'E partidos de Queelata, assentaram no monte de Séfer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'E partidos do monte de Séfer, assentaram em Harada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'E partidos de Harada, assentaram em Maquelote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'E partidos de Maquelote, assentaram em Taate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'E partidos de Taate, assentaram em Tera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'E partidos de Tera, assentaram em Mitca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'E partidos de Mitca, assentaram em Hasmona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'E partidos de Hasmona, assentaram em Moserote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'E partidos de Moserote, assentaram em Bene-Jaacã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'E partidos de Bene-Jaacã, assentaram em Hor-Gidgade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'E partidos de Hor-Gidgade, assentaram em Jotbatá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'E partidos de Jotbatá, assentaram em Abrona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'E partidos de Abrona, assentaram em Eziom-Geber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'E partidos de Eziom-Geber, assentaram no deserto de Zim, que é Cades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'E partidos de Cades, assentaram no monte de Hor, na extremidade do país de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'E subiu Arão o sacerdote ao monte de Hor, conforme o dito do SENHOR, e ali morreu aos quarenta anos da saída dos filhos de Israel da terra do Egito, no mês quinto, no primeiro dia do mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'E era Arão de idade de cento e vinte e três anos, quando morreu no monte de Hor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'E o cananeu, rei de Arade, que habitava ao sul na terra de Canaã, ouviu como haviam vindo os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'E partidos do monte de Hor, assentaram em Zalmona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'E partidos de Zalmona, assentaram em Punom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'E partidos de Punom, assentaram em Obote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'E partidos de Obote, assentaram em Ijé-Abarim; no termo de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'E partidos de Ijé-Abarim, assentaram em Dibom-Gade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'E partidos de Dibom-Gade, assentaram em Almom-Diblataim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'E partidos de Almom-Diblataim, assentaram nos montes de Abarim, diante de Nebo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'E partidos dos montes de Abarim, assentaram nos campos de Moabe, junto ao Jordão de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Finalmente assentaram junto ao Jordão, desde Bete-Jesimote até Abel-Sitim, nos campos de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'E falou o SENHOR a Moisés nos campos de Moabe junto ao Jordão de Jericó, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes passado o Jordão à terra de Canaã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Expulsareis a todos os moradores do país de diante de vós, e destruireis todas suas imagens esculpidas, e todas suas imagens de fundição, e arruinareis todos os seus altos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'E expulsareis os moradores da terra, e habitareis nela; porque eu a dei a vós para que a possuais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'E herdareis a terra por sortes por vossas famílias: aos muitos dareis muito por sua herança, e aos poucos dareis menos por herança sua: onde lhe sair a sorte, ali a terá cada um: pelas tribos de vossos pais herdareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'E se não expulsardes os moradores do país de diante de vós, sucederá que os que deixardes deles serão por aguilhões em vossos olhos, e por espinhos em vossos lados, e vos afligirão sobre a terra em que vós habitardes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Será também, que farei a vós como eu pensei fazer a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'E o SENHOR falou a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Manda aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra de Canaã, a saber, a terra que vos há de cair em herança, a terra de Canaã segundo seus termos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Tereis o lado do sul desde o deserto de Zim até os termos de Edom; e vos será o termo do sul ao extremo do mar salgado até o oriente:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'E este termo vos irá rodeando desde o sul até a subida de Acrabim, e passará até Zim; e suas saídas serão do sul a Cades-Barneia; e sairá a Hazar-Adar, e passará até Azmom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'E rodeará este termo, desde Azmom até o ribeiro do Egito, e seus limites serão ao ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'E o termo ocidental vos será o grande mar: este termo vos será o termo ocidental.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'E o termo do norte será este: desde o grande mar vos assinalareis o monte de Hor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Do monte de Hor assinalareis à entrada de Hamate, e serão as saídas daquele termo a Zedade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'E sairá este termo a Zifrom, e serão seus limites em Hazar-Enã: este vos será o termo do norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'E por termo ao oriente vos assinalareis desde Hazar-Enã até Sefã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'E baixará este termo desde Sefã a Ribla, ao oriente de Aim: e descerá o termo, e chegará à costa do mar de Quinerete ao oriente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Depois descerá este termo ao Jordão, e serão suas saídas ao mar Salgado: esta será vossa terra: por seus termos ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'E mandou Moisés aos filhos de Israel, dizendo: Esta é a terra que herdareis por sorte, a qual mandou o SENHOR que desse às nove tribos, e à meia tribo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Porque a tribo dos filhos de Rúben segundo as casas de seus pais, e a tribo dos filhos de Gade segundo as casas de seus pais, e a meia tribo de Manassés, tomaram sua herança:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Duas tribos e meia tomaram sua herança desta parte do Jordão de Jericó ao oriente, ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Estes são os nomes dos homens que vos possuirão a terra: Eleazar o sacerdote, e Josué filho de Num.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Tomareis também de cada tribo um príncipe, para dar a possessão da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'E estes são os nomes dos homens: Da tribo de Judá, Calebe filho de Jefoné.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'E da tribo dos filhos de Simeão, Samuel filho de Amiúde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Da tribo de Benjamim; Elidade filho de Quislom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'E da tribo dos filhos de Dã, o príncipe Buqui filho de Jogli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Dos filhos de José: da tribo dos filhos de Manassés, o príncipe Haniel filho de Éfode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'E da tribo dos filhos de Efraim, o príncipe Quemuel filho de Siftã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'E da tribo dos filhos de Zebulom, o príncipe Elizafã filho de Parnaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'E da tribo dos filhos de Issacar, o príncipe Paltiel filho de Azã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'E da tribo dos filhos de Aser, o príncipe Aiúde filho de Selomi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'E da tribo dos filhos de Naftali, o príncipe Pedael filho de Amiúde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Estes são aos que mandou o SENHOR que fizessem a partição da herança aos filhos de Israel na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'E falou o SENHOR a Moisés nos campos de Moabe, junto ao Jordão de Jericó, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Manda aos filhos de Israel, que deem aos levitas da possessão de sua herança cidades em que habitem: Também dareis aos levitas campos de essas cidades ao redor delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'E terão eles as cidades para habitar, e os campos delas serão para seus animais, e para seus gados, e para todos seus animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'E os campos das cidades que dareis aos levitas, serão mil côvados ao redor, desde o muro da cidade para fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Logo medireis fora da cidade à parte do oriente dois mil côvados, e à parte do sul dois mil côvados, e à parte do ocidente dois mil côvados, e à parte do norte dois mil côvados, e a cidade em meio: isto terão pelos campos das cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'E das cidades que dareis aos levitas, seis cidades serão de refúgio, as quais dareis para que o homicida se acolha ali: e também destas dareis quarenta e duas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Todas as cidades que dareis aos levitas serão quarenta e oito cidades; elas com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'E as cidades que deres da herança dos filhos de Israel, do que muito tomareis muito, e do que pouco tomareis pouco: cada um dará de suas cidades aos levitas segundo a possessão que herdará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'E falou o SENHOR a Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes passado o Jordão à terra de Canaã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Assinalareis para vós cidades, tereis cidades de refúgio, para onde fuja o homicida que ferir a algum de morte por acidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'E vos serão aquelas cidades por refúgio do parente, e não morrerá o homicida até que esteja a juízo diante da congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Das cidades, pois, que dareis, tereis seis cidades de refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Três cidades dareis desta parte do Jordão, e três cidades dareis na terra de Canaã; as quais serão cidades de refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Estas seis cidades serão para refúgio aos filhos de Israel, e ao peregrino, e ao que morar entre eles, para que fuja ali qualquer um que ferir de morte a outro por acidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'E se com instrumento de ferro o ferir e morrer, homicida é; o homicida morrerá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'E se com pedra da mão, de que podia morrer, o ferir, e morrer, homicida é; o homicida morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'E se com instrumento de madeira da mão, de que podia morrer, o ferir, e morrer, homicida é; o homicida morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'O parente do morto, ele matará ao homicida: quando o encontrar, ele lhe matará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'E se por ódio o empurrou, ou lançou sobre ele alguma coisa por ciladas, e morre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Ou por inimizade o feriu com sua mão, e morreu: o feridor morrerá; é homicida; o parente do morto matará ao homicida, quando o encontrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mas se casualmente o empurrou sem inimizades, ou lançou sobre ele qualquer instrumento sem más intenções,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Ou bem, sem vê-lo, fez cair sobre ele alguma pedra, de que possa morrer, e morrer, e ele não era seu inimigo, nem procurava seu mal;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Então a congregação julgará entre o feridor e o parente do morto conforme estas leis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'E a congregação livrará ao homicida da mão do parente do morto, e a congregação o fará voltar à seu cidade de refúgio, à qual se havia acolhido; e morará nela até que morra o sumo sacerdote, o qual foi ungido com o azeite santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'E se o homicida sair fora do termo de sua cidade de refúgio, à qual se refugiou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'E o parente do morto lhe achar fora do termo da cidade de sua acolhida, e o parente do morto ao homicida matar, não se lhe culpará por isso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Pois em sua cidade de refúgio deverá aquele habitar até que morra o sumo sacerdote: e depois que morrer o sumo sacerdote, o homicida voltará à terra de sua possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'E estas coisas vos serão por ordenança de regulamento por vossas gerações, em todas as vossas habitações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Qualquer um que ferir a alguém, por dito de testemunhas, morrerá o homicida: mas uma só testemunha não fará fé contra alguma pessoa para que morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'E não tomareis preço pela vida do homicida; porque está condenado a morte: mas inevitavelmente morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Nem tampouco tomareis preço do que fugiu à sua cidade de refúgio, para que volte a viver em sua terra, até que morra o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'E não contaminareis a terra onde estiverdes: porque este sangue profanará a terra: e a terra não será expiada do sangue que foi derramado nela, a não ser pelo sangue do que a derramou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Não contamineis, pois, a terra onde habitais, em meio da qual eu habito; porque eu o SENHOR habito em meio dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'E chegaram os príncipes dos pais da família de Gileade, filho de Maquir, filho de Manassés, das famílias dos filhos de José; e falaram diante de Moisés, e dos príncipes, cabeças de pais dos filhos de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'E disseram: o SENHOR mandou a meu senhor que por sorte desse a terra aos filhos de Israel em possessão: também mandou o SENHOR a meu senhor, que dê a possessão de Zelofeade nosso irmão a suas filhas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'As quais, se se casarem com alguns dos filhos das outras tribos dos filhos de Israel, a herança delas será assim tirada da herança de nossos pais, e será acrescentada à herança da tribo a que serão unidas: e será removida da porção de nossa herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'E quando vier o jubileu dos filhos de Israel, a herança delas será acrescentada à herança da tribo de seus maridos; e assim a herança delas será removida da herança da tribo de nossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Então Moisés mandou aos filhos de Israel por dito do SENHOR, dizendo: A tribo dos filhos de José fala corretamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Isto é o que mandou o SENHOR acerca das filhas de Zelofeade, dizendo: Casem-se como a elas lhes satisfizer, porém na família da tribo de seu pai se casarão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Para que a herança dos filhos de Israel não seja passada de tribo em tribo; porque cada um dos filhos de Israel se achegará à herança da tribo de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'E qualquer filha que possuir herança das tribos dos filhos de Israel, com algum da família da tribo de seu pai se casará, para que os filhos de Israel possuam cada um a herança de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'E não ande a herança rodando de uma tribo a outra: mas cada uma das tribos dos filhos de Israel se chegue à sua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Como o SENHOR mandou a Moisés, assim fizeram as filhas de Zelofeade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'E assim Maalá, e Tirsa, e Hogla, e Milca, e Noa, filhas de Zelofeade, se casaram com filhos de seus tios:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Da família dos filhos de Manassés, filho de José, foram mulheres; e a herança delas ficou na tribo da família de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Estes são os mandamentos e os estatutos que mandou o SENHOR por meio de Moisés aos filhos de Israel nos campos de Moabe, junto ao Jordão de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Estas são as palavras que falou Moisés a todo Israel desta parte do Jordão no deserto, na planície diante do mar Vermelho, entre Parã, e Tofel, e Labã, e Hazerote, e Di-Zaabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Onze jornadas há desde Horebe, caminho do monte de Seir, até Cades-Barneia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'E foi, que aos quarenta anos, no mês décimo primeiro, ao primeiro dia do mês, Moisés falou aos filhos de Israel conforme todas as coisas que o SENHOR lhe havia mandado acerca deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Depois que feriu a Seom rei dos amorreus, que habitava em Hesbom, e a Ogue rei de Basã, que habitava em Astarote em Edrei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Desta parte do Jordão, em terra de Moabe, resolveu Moisés declarar esta lei, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'O SENHOR nosso Deus nos falou em Horebe, dizendo: Demais haveis estado neste monte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Voltai-vos, parti-vos e ide ao monte dos amorreus, e a todos seus vizinhos, na planície, no monte, e nos vales, e ao sul, e à costa do mar, à terra dos cananeus, e o Líbano, até o grande rio, o rio Eufrates.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Olhai, eu dei a terra em vossa presença; entrai e possuí a terra que o SENHOR jurou a vossos pais Abraão, Isaque, e Jacó, que lhes daria a eles e à sua descendência depois deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'E eu vos falei então, dizendo: Eu não posso vos levar só:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'O SENHOR vosso Deus vos multiplicou, e eis que sois hoje vós como as estrelas do céu em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'O SENHOR Deus de vossos pais acrescente sobre vós como sois mil vezes, e vos abençoe, como vos prometeu!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Como levarei eu só vossos problemas, vossas cargas, e vossos pleitos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Dai-me dentre vós, de vossas tribos, homens sábios e entendidos e experientes, para que eu os ponha por vossos chefes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'E me respondestes, e dissestes: Bom é fazer o que disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'E tomei os principais de vossas tribos, homens sábios e experientes, e os pus por chefes sobre vós, chefes de milhares, e chefes de centenas, e chefes de cinquenta, e líderes de dez, e governadores a vossas tribos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'E então mandei a vossos juízes, dizendo: Ouvi entre vossos irmãos, e julgai justamente entre o homem e seu irmão, e o que lhe é estrangeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Não tenhais acepção de pessoas no juízo: tanto ao pequeno como ao grande ouvireis: não tereis temor de ninguém, porque o juízo é de Deus: e a causa que vos for difícil, a trareis a mim, e eu a ouvirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Eu vos mandei, pois, naquele tempo tudo o que havíeis de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'E partidos de Horebe, andamos todo aquele grande e terrível deserto que vistes, pelo caminho do monte dos amorreus, como o SENHOR nosso Deus nos mandou; e chegamos até Cades-Barneia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Então vos disse: Chegastes ao monte dos amorreus, o qual o SENHOR nosso Deus nos dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Olha, o SENHOR teu Deus deu diante de ti a terra: sobe e possui-a, como o SENHOR o Deus de teus pais te disse; não temas nem desmaies.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'E aproximastes a mim todos vós, e dissestes: Enviemos homens diante de nós, que nos reconheçam a terra e nos tragam de volta relato do caminho por onde temos de subir, e das cidades aonde temos de chegar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'E o dito me apareceu bem: e tomei doze homens de vós, um homem por tribo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'E se encaminharam, e subiram ao monte, e chegaram até o vale de Escol, e reconheceram a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'E tomaram em suas mãos do fruto do país, e o trouxeram a nós, e nos contaram, e disseram: É boa a terra que o SENHOR nosso Deus nos dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Porém não quisestes subir, antes fostes rebeldes ao dito do SENHOR vosso Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'E murmurastes em vossas tendas, dizendo: Porque o SENHOR nos aborrecia, nos tirou da terra do Egito, para entregar-nos em mão dos amorreus para nos destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Para onde subimos? Nossos irmãos fizeram desfalecer nosso coração, dizendo: Este povo é maior e mais alto que nós, as cidades grandes e muradas até o céu; e também vimos ali filhos de gigantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Então vos disse: Não temais, nem tenhais medo deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'O SENHOR vosso Deus, o qual vai diante de vós, ele lutará por vós, conforme todas as coisas que fez por vós no Egito diante vossos olhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'E no deserto viste que o SENHOR teu Deus te trouxe, como traz o homem a seu filho, por todo o caminho que andastes, até que viestes a este lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'E ainda com isto não crestes no SENHOR vosso Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'O qual ia diante de vós pelo caminho, para reconhecer-vos o lugar onde havíeis de assentar o acampamento, com fogo de noite para vos mostrar o caminho por onde andásseis, e com nuvem de dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'E ouviu o SENHOR a voz de vossas palavras, e irou-se, e jurou dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Não verá homem algum destes desta má geração, a boa terra que jurei havia de dar a vossos pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Exceto Calebe filho de Jefoné: ele a verá, e a ele lhe darei a terra que pisou, e a seus filhos; porque cumpriu em seguir ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'E também contra mim se irou o SENHOR por vós, dizendo: Tampouco tu entrarás ali:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josué filho de Num, que está diante de ti, ele entrará ali: anima-o; porque ele a fará herdar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'E vossas crianças, das quais dissestes serão por presa, e vossos filhos que não sabem hoje bem nem mal, eles entrarão ali, e a eles a darei, e eles a herdarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'E vós voltai-vos, e parti-vos ao deserto caminho do mar Vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Então respondestes e me dissestes: Pecado temos contra o SENHOR; nós subiremos e lutaremos, conforme tudo o que o SENHOR nosso Deus nos mandou. E vos armastes cada um de suas armas de guerra, e vos preparastes para subir ao monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'E o SENHOR me disse: Dize-lhes: Não subais, nem luteis, pois não estou entre vós; para que não sejais feridos diante de vossos inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'E vos falei, e não destes ouvido; antes fostes rebeldes ao dito do SENHOR, e persistindo com altivez, subistes ao monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'E saíram os amorreus, que habitavam naquele monte, a vosso encontro, e vos perseguiram, como fazem as vespas, e vos derrotaram em Seir, perseguindo-vos até Hormá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'E voltastes, e chorastes diante do SENHOR; mas o SENHOR não escutou vossa voz, nem vos prestou ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'E estivestes em Cades por muitos dias, como nos dias que estivestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'E voltamos, e partimo-nos ao deserto caminho do mar Vermelho, como o SENHOR me havia dito; e rodeamos o monte de Seir por muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'E o SENHOR me falou, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Demais rodeastes este monte; voltai-vos ao norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'E manda ao povo, dizendo: Passando vós pelo termo de vossos irmãos os filhos de Esaú, que habitam em Seir, eles terão medo de vós; mas vós guardai-vos muito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Não vos metais com eles; que não vos darei de sua terra nem ainda a pisadura da planta de um pé; porque eu dei por herança a Esaú o monte de Seir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Comprareis deles por dinheiro os alimentos, e comereis; e também comprareis deles a água, e bebereis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Pois o SENHOR teu Deus te abençoou em toda obra de tuas mãos: ele sabe que andas por este grande deserto: estes quarenta anos o SENHOR teu Deus foi contigo; e nenhuma coisa te faltou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'E passamos por nossos irmãos os filhos de Esaú, que habitavam em Seir, pelo caminho da planície de Elate e de Eziom-Geber. E voltamos, e passamos caminho do deserto de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'E o SENHOR me disse: Não perturbeis a Moabe, nem te empenhes com eles em guerra, que não te darei possessão de sua terra; porque eu dei a Ar por herança aos filhos de Ló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Os emins habitaram nela antes, povo grande, e numeroso, e alto como gigantes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Por gigantes eram eles também contados, como os anaquins; e os moabitas os chamam emins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'E em Seir habitaram antes os horeus, aos quais os filhos de Esaú expulsaram; e os destruíram de diante de si, e moraram em lugar deles; como fez Israel na terra de sua possessão que lhes deu o SENHOR.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Levantai-vos agora, e passai o ribeiro de Zerede. E passamos o ribeiro de Zerede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'E os dias que andamos de Cades-Barneia até que passamos o ribeiro de Zerede, foram trinta e oito anos; até que se acabou toda a geração dos homens de guerra do meio do acampamento, como o SENHOR lhes havia jurado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'E também a mão do SENHOR foi sobre eles para destruí-los do meio do campo, até acabá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'E aconteceu que quando se acabaram de morrer todos os homens de guerra dentre o povo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'O SENHOR me falou, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tu passarás hoje o termo de Moabe, a Ar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'E te aproximarás diante dos filhos de Amom: não os perturbeis, nem te metas com eles; porque não te tenho de dar possessão da terra dos filhos de Amom; que aos filhos de Ló a dei por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Por terra de gigantes foi também ela tida: habitaram nela gigantes em outro tempo, aos quais os amonitas chamavam zanzumins;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Povo grande, e numeroso, e alto, como os anaquins; aos quais o SENHOR destruiu de diante dos amonitas, os quais lhes sucederam, e habitaram em seu lugar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Como fez com os filhos de Esaú, que habitavam em Seir, de diante dos quais destruiu aos horeus; e eles lhes sucederam, e habitaram em seu lugar até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'E aos aveus que habitavam em vilas até Gaza, os caftoreus que saíram de Caftor os destruíram, e habitaram em seu lugar.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Levantai-vos, parti, e passai o ribeiro de Arnom: eis que dei em tua mão a Seom rei de Hesbom, amorreu, e a sua terra: começa a tomar possessão, e empenha-te com ele em guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Hoje começarei a pôr teu medo e teu espanto sobre os povos debaixo de todo o céu, os quais ouvirão tua fama, e tremerão, e se angustiarão diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'E enviei mensageiros desde o deserto de Quedemote a Seom rei de Hesbom, com palavras de paz, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Passarei por tua terra pelo caminho: pelo caminho irei, sem apartar-me à direita nem à esquerda:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'A comida me venderás por dinheiro e comerei: a água também me darás por dinheiro, e beberei: somente passarei a pé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Como o fizeram comigo os filhos de Esaú que habitavam em Seir, e os moabitas que habitavam em Ar; até que passe o Jordão à terra que nos dá o SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Mas Seom rei de Hesbom não quis que passássemos pelo território seu; porque o SENHOR teu Deus havia endurecido seu espírito, e obstinado seu coração para entregá-lo em tua mão, como hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'E disse-me o SENHOR: Eis que eu comecei a dar diante de ti a Seom e a sua terra; começa a tomar possessão, para que herdes sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'E saiu-nos Seom ao encontro, ele e todo seu povo, para lutar em Jaza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Mas o SENHOR nosso Deus o entregou diante de nós; e ferimos a ele e a seus filhos, e a todo seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'E tomamos então todas suas cidades, e destruímos todas as cidades, homens, e mulheres, e crianças; não deixamos ninguém:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Somente tomamos para nós os animais, e os despojos das cidades que havíamos tomado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Desde Aroer, que está junto à beira do ribeiro de Arnom, e a cidade que está no ribeiro, até Gileade, não houve cidade que escapasse de nós: todas as entregou o SENHOR nosso Deus em nosso poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Somente à terra dos filhos de Amom não chegaste, nem a tudo o que está à beira do ribeiro de Jaboque nem às cidades do monte, nem a lugar algum que o SENHOR nosso Deus havia proibido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'E voltamos, e subimos caminho de Basã, e saiu-nos ao encontro Ogue rei de Basã para lutar, ele e todo seu povo, em Edrei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'E disse-me o SENHOR: Não tenhas medo dele, porque em tua mão entreguei a ele e a todo seu povo, e sua terra: e farás com ele como fizeste com Seom rei amorreu, que habitava em Hesbom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'E o SENHOR nosso Deus entregou também em nossa mão a Ogue rei de Basã, e a todo seu povo, ao qual ferimos até não restar dele ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'E tomamos então todas suas cidades; não restou cidade que não lhes tomássemos: sessenta cidades, toda a terra de Argobe, do reino de Ogue em Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Todas estas eram cidades fortificadas com alto muro, com portas e barras; sem outras muito muitas cidades sem muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'E as destruímos, como fizemos a Seom rei de Hesbom, destruindo em toda cidade homens, mulheres, e crianças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'E tomamos para nós todos os animais, e os despojos das cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Também tomamos naquele tempo da mão de dois reis amorreus que estavam desta parte do Jordão, a terra desde o ribeiro de Arnom até o monte de Hermom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Os sidônios chamam a Hermom Siriom; e os amorreus, Senir:)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Todas as cidades da planície, e todo Gileade, e todo Basã até Salcá e Edrei, cidades do reino de Ogue em Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Porque somente Ogue rei de Basã havia restado dos gigantes que restaram. Eis que sua cama, uma cama de ferro, não está em Rabá dos filhos de Amom?; o comprimento dela de nove côvados, e sua largura de quatro côvados, ao côvado de um homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'E esta terra que herdamos então desde Aroer, que está ao ribeiro de Arnom, e a metade do monte de Gileade com suas cidades, dei aos rubenitas e aos gaditas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'E o resto de Gileade, e todo Basã, do reino de Ogue, dei o à meia tribo de Manassés; toda a terra de Argobe, todo Basã, que se chamava a terra dos gigantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair filho de Manassés tomou toda a terra de Argobe até o termo dos gessuritas e dos maacatitas; e chamou-a de seu nome Basã-Havote-Jair, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'E a Maquir dei a Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'E aos rubenitas e gaditas dei de Gileade até o ribeiro de Arnom, o meio do ribeiro por termo; até o ribeiro de Jaboque, termo dos filhos de Amom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Assim como a campina, e o Jordão, e o termo, desde Quinerete até o mar da planície, o mar Salgado, as encostas abaixo do Pisga ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'E vos mandei então, dizendo: O SENHOR vosso Deus vos deu esta terra para que a possuais: passareis armados diante de vossos irmãos os filhos de Israel todos os valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Somente vossas mulheres, vossas crianças, e vossos gados, (eu sei que tendes muito gado,) ficarão em vossas cidades que vos dei,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Até que o SENHOR dê repouso a vossos irmãos, assim como a vós, e herdem também eles a terra que o SENHOR vosso Deus lhes dá à outra parte do Jordão: então vos voltareis cada um a sua herança que eu vos dei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Mandei também a Josué então, dizendo: Teus olhos viram tudo o que o SENHOR vosso Deus fez àqueles dois reis: assim fará o SENHOR a todos os reinos aos quais passarás tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Não os temais; que o SENHOR vosso Deus, ele é o que luta por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'E orei ao SENHOR naquele tempo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Senhor DEUS, tu começaste a mostrar a teu servo tua grandeza, e tua mão forte: porque que deus há no céu nem na terra que faça segundo tuas obras, e segundo tuas valentias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Passe eu, rogo-te, e veja aquela terra boa, que está à parte ali do Jordão, aquele bom monte, e o Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mas o SENHOR se havia irado contra mim por causa de vós, pelo qual não me ouviu: e disse-me o SENHOR: Basta-te, não me fales mais deste negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Sobe ao cume do Pisga, e ergue teus olhos ao ocidente, e ao norte, e ao sul, e ao oriente, e vê por teus olhos: porque não passarás este Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'E manda a Josué, e anima-o, e conforta-o; porque ele há de passar diante deste povo, e ele lhes fará herdar a terra que verás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'E paramos no vale diante de Bete-Peor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Agora, pois, ó Israel, ouve os estatutos e regulamentos que eu vos ensino, para que os executeis, e vivais, e entreis, e possuais a terra que o SENHOR o Deus de vossos pais te dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Não acrescentareis à palavra que eu vos mando, nem diminuireis dela, para que guardeis os mandamentos do SENHOR vosso Deus que eu vos ordeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vossos olhos viram o que fez o SENHOR por motivo de Baal-Peor; que a todo homem que foi atrás de Baal-Peor destruiu o SENHOR teu Deus do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Mas vós que vos achegastes ao SENHOR vosso Deus, todos estais vivos hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Olhai, eu vos ensinei estatutos e regulamentos, como o SENHOR meu Deus me mandou, para que façais assim em meio da terra na qual entrais para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Guardai-os, pois, e ponde-os por obra: porque esta é vossa sabedoria e vossa inteligência aos olhos dos povos, os quais ouvirão todos estes estatutos, e dirão: Certamente povo sábio e entendido, gente grande é esta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Porque que gente grande há que tenha os deuses próximo a si, como o está o SENHOR nosso Deus em tudo quanto lhe pedimos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'E que gente grande há que tenha estatutos e regulamentos justos, como é toda esta lei que eu ponho hoje diante de vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Portanto, guarda-te, e guarda tua alma com empenho, que não te esqueças das coisas que teus olhos viram, nem se apartem de teu coração todos os dias de tua vida: e as ensinarás a teus filhos, e aos filhos de teus filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'No dia que estiveste diante do SENHOR teu Deus em Horebe, quando o SENHOR me disse: Junta-me o povo, para que eu lhes faça ouvir minhas palavras, as quais aprenderão, para temer-me todos os dias que viverem sobre a terra: e as ensinarão a seus filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'E vos aproximastes, e vos pusestes ao pé do monte; e o monte ardia em fogo até em meio dos céus com trevas, nuvem, e escuridão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'E falou o SENHOR convosco do meio do fogo: ouvistes a voz de suas palavras, mas a exceção de ouvir a voz, nenhuma forma vistes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'E ele vos anunciou seu pacto, o qual vos mandou pôr por obra, os dez mandamentos; e escreveu-os em duas tábuas de pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'A mim também me mandou o SENHOR então ensinar-vos os estatutos e regulamentos, para que os pusestes por obra na terra à qual passais para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Guardai pois muito vossas almas: pois nenhuma forma vistes no dia que o SENHOR falou convosco do meio do fogo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Para que não vos corrompais, e façais para vós escultura, imagem de forma alguma, efígie de macho ou fêmea,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Figura de algum animal que seja na terra, forma de ave alguma de asas que voe pelo ar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Figura de nenhum animal que vá arrastando pela terra, forma de peixe algum que haja na água debaixo da terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'E para que levantando teus olhos ao céu, e vendo o sol e a lua e as estrelas, e todo o exército do céu, não sejas incitado, e te inclines a eles, e lhes sirvas; que o SENHOR teu Deus os concedeu a todos os povos debaixo de todos os céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Porém a vós o SENHOR vos tomou, e vos tirou do forno de ferro, do Egito, para que lhe sejais por povo de herança como neste dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'E o SENHOR se irou contra mim sobre vossos negócios, e jurou que eu não passaria o Jordão, nem entraria na boa terra, que o SENHOR teu Deus te dá por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Assim eu vou a morrer nesta terra; e não passo o Jordão: mas vós passareis, e possuireis aquela boa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Guardai-vos que não vos esqueçais do pacto do SENHOR vosso Deus, que ele estabeleceu convosco, e vos façais escultura ou imagem de qualquer coisa, que o SENHOR teu Deus te proibiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Porque o SENHOR teu Deus é fogo que consome, Deus zeloso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Quando houverdes gerado filhos e netos, e houverdes envelhecido na terra, e vos corromperdes, e fizerdes escultura ou imagem de qualquer coisa, e fizerdes mal aos olhos do SENHOR vosso Deus, para irá-lo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Eu ponho hoje por testemunhas ao céu e à terra, que logo perecereis totalmente da terra até a qual passais o Jordão para possuí-la: não estareis nela longos dias sem que sejais destruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'E o SENHOR vos espalhará entre os povos, e restareis poucos em número entre as nações às quais vos levará o SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'E servireis ali a deuses feitos das mãos de homens, a madeira e a pedra, que não vem, nem ouvem, nem comem, nem cheiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Mas se desde ali buscares ao SENHOR teu Deus, o acharás, se o buscares de todo teu coração e de toda tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Quando estiveres em angústia, e te alcançarem todas estas coisas, se nos últimos dias te voltares ao SENHOR teu Deus, e ouvires sua voz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Porque Deus misericordioso é o SENHOR teu Deus; não te deixará, nem te destruirá, nem se esquecerá do pacto de teus pais que lhes jurou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Porque pergunta agora dos tempos passados, que foram antes de ti, desde o dia que criou Deus ao homem sobre a terra, e desde um fim do céu ao outro, se se fez coisa semelhante a esta grande coisa, ou se tenha ouvido outra como ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Ouviu povo a voz de Deus, que falasse do meio do fogo, como tu a ouviste, e viveste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Ou experimentou Deus a vir a tomar para si nação do meio de outra nação, com provas, com sinais, com milagres, e com guerra, e mão forte, e braço estendido, e grandes espantos, segundo todas as coisas que fez convosco o SENHOR vosso Deus no Egito diante de teus olhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'A ti te foi mostrado, para que soubesses que o SENHOR ele é Deus; não há mais além dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Dos céus te fez ouvir sua voz, para ensinar-te: e sobre a terra te mostrou seu grande fogo: e ouviste suas palavras do meio do fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'E porquanto ele amou a teus pais, escolheu sua descendência depois deles, e te tirou diante de si do Egito com seu grande poder;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Para lançar de diante de ti nações grandes e mais fortes que tu, e para te introduzir, e dar-te sua terra por herança, como hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Aprende pois hoje, e medita em teu coração que o SENHOR ele é o Deus acima no céu, e abaixo sobre a terra; não há outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'E guarda seus estatutos e seus mandamentos, que eu te mando hoje, para que te vá bem a ti e a teus filhos depois de ti, e prolongues teus dias sobre a terra que o SENHOR teu Deus te dá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Então separou Moisés três cidades desta parte do Jordão ao oriente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Para que fugisse ali o homicida que matasse a seu próximo por acidente, sem haver tido inimizade com ele desde ontem nem antes de ontem; e que fugindo de uma vez destas cidades salvara a vida:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'A Bezer no deserto, em terra da planície, dos rubenitas; e a Ramote em Gileade, dos gaditas; e a Golã em Basã, dos de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Esta, pois, é a lei que Moisés propôs diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Estes são os testemunhos, e os estatutos, e os regulamentos, que Moisés notificou aos filhos de Israel, quando houveram saído do Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Desta parte do Jordão, no vale diante de Bete-Peor, na terra de Seom rei dos amorreus, que habitava em Hesbom, ao qual feriu Moisés com os filhos de Israel, quando saíram do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'E possuíram sua terra, e a terra de Ogue rei de Basã; dois reis dos amorreus que estavam desta parte do Jordão, ao oriente:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Desde Aroer, que está junto à beira do ribeiro de Arnom, até o monte de Sião, que é Hermom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'E toda a planície desta parte do Jordão, ao oriente, até o mar da planície, as encostas das águas abaixo do Pisga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'E chamou Moisés a todo Israel, e disse-lhes: Ouve, Israel, os estatutos e regulamentos que eu pronuncio hoje em vossos ouvidos: e aprendei-os, e guardai-os, para praticá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'O SENHOR nosso Deus fez pacto conosco em Horebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Não com nossos pais fez o SENHOR este pacto, a não ser conosco todos os que estamos aqui hoje vivos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Face a face falou o SENHOR convosco no monte do meio do fogo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(Eu estava então entre o SENHOR e vós, para vos anunciar a palavra do SENHOR; porque vós tivestes temor do fogo, e não subistes ao monte;) dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Eu sou o SENHOR teu Deus, que te tirei da terra do Egito, de casa de servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Não terás deuses estranhos diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Não farás para ti escultura, nem imagem alguma de coisa que está acima nos céus, ou abaixo na terra, ou nas águas debaixo da terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Não te inclinarás a elas nem lhes servirás: porque eu sou o SENHOR teu Deus, forte, zeloso, que visito a iniquidade dos pais sobre os filhos, e sobre a terceira geração, e sobre a quarta, aos que me aborrecem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'E que faço misericórdia a milhares aos que me amam, e guardam meus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Não tomarás em vão o nome do SENHOR teu Deus; porque o SENHOR não dará por inocente ao que tomar em vão seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Guardarás o dia do repouso para santificá-lo, como o SENHOR teu Deus te mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Seis dias trabalharás e farás toda tua obra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Mas no sétimo é repouso ao SENHOR teu Deus: nenhuma obra farás tu, nem teu filho, nem tua filha, nem teu servo, nem tua serva, nem tua boi, nem tua asno, nem nenhum animal teu, nem tua peregrino que está dentro de tuas portas: para que descanse teu servo e tua serva como');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'E lembra-te que foste servo em terra do Egito, e que o SENHOR teu Deus te tirou dali com mão forte e braço estendido: pelo qual o SENHOR teu Deus te mandou que guardes no dia do repouso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Honra a teu pai e a tua mãe, como o SENHOR teu Deus te mandou, para que sejam prolongados teus dias, e para que te vá bem sobre a terra que o SENHOR teu Deus te dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Não cometerás homicídio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Não adulterarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Não furtarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Não dirás falso testemunho contra teu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Não cobiçarás a mulher de teu próximo, nem desejarás a casa de teu próximo, nem sua terra, nem seu servo, nem sua serva, nem seu boi, nem seu asno, nem nenhuma coisa que seja de teu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Estas palavras falou o SENHOR a toda vossa congregação no monte, do meio do fogo, da nuvem e da escuridão, a grande voz: e não acrescentou mais. E escreveu-os em duas tábuas de pedra, as quais deu a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'E aconteceu, que como vós ouvistes a voz do meio das trevas, e vistes ao monte que ardia em fogo, aproximastes a mim todos os príncipes de vossas tribos, e vossos anciãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'E dissestes: Eis que, o SENHOR nosso Deus nos mostrou sua glória e sua grandeza, e ouvimos sua voz do meio do fogo: hoje vimos que o SENHOR fala ao homem, e este vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Agora pois, por que morreremos? Que este grande fogo nos consumirá: se voltarmos a ouvir a voz do SENHOR nosso Deus, morreremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Porque, que é toda carne, para que ouça a voz do Deus vivente que fala do meio do fogo, como nós a ouvimos, e viva?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Chega tu, e ouve todas as coisas que disser o SENHOR nosso Deus; e tu nos dirás todo o que o SENHOR nosso Deus te disser, e nós ouviremos e faremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'E ouviu o SENHOR a voz de vossas palavras, quando me faláveis; e disse-me o SENHOR: Ouvi a voz das palavras deste povo, que eles te falaram: bem está tudo o que disseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Quem dera que tivessem tal coração, que me temessem, e guardassem todos os dias todos meus mandamentos, para que a eles e a seus filhos lhes fosse bem para sempre!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Vai, dize-lhes: Voltai-vos a vossas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'E tu fica aqui comigo, e te direi todos os mandamentos, e estatutos, e regulamentos que lhes hás de ensinar, a fim que os ponham agora por obra na terra que eu lhes dou para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Olhai, pois, que façais como o SENHOR vosso Deus vos mandou: não vos desvieis à direita nem à esquerda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Andai em todo caminho que o SENHOR vosso Deus vos mandou, para que vivais, e vos vá bem, e tenhais longos dias na terra que haveis de possuir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Estes, pois são os mandamentos, estatutos, e regulamentos que o SENHOR vosso Deus mandou que vos ensinasse, para que os ponhais por obra na terra à qual passais vós para possuí-la:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Para que temas ao SENHOR teu Deus, guardando todos os seus estatutos e seus mandamentos que eu te mando, tu, e teu filho, e o filho de teu filho, todos os dias de tua vida, e que teus dias sejam prolongados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Ouve, pois, ó Israel, e cuida de praticá-los, para que te vá bem, e sejais multiplicados, como te disse o SENHOR o Deus de teus pais, na terra que destila leite e mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Ouve, Israel: o SENHOR nosso Deus, o SENHOR um é:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'E Amarás ao SENHOR teu Deus de todo teu coração, e de toda tua alma, e com todo tua poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'E estas palavras que eu te mando hoje, estarão sobre teu coração:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'E as repetirás a teus filhos, e falarás delas estando em tua casa, e andando pelo caminho, e ao deitar-te, e quando te levantes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'E hás de atá-las por sinal em tua mão, e estarão por frontais entre teus olhos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'E as escreverás nos umbrais de tua casa, e em tuas entradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'E será, quando o SENHOR teu Deus te houver introduzido na terra que jurou a teus pais Abraão, Isaque, e Jacó, que te daria; em cidades grandes e boas que tu não edificaste,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'E casas cheias de todo ainda que tu não encheste, e cisternas cavadas, que tu não cavaste, vinhas e olivais que não plantaste: logo que comeres e te fartares,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Guarda-te que não te esqueças do SENHOR, que te tirou da terra do Egito, de casa de servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Ao SENHOR teu Deus temerás, e a ele servirás, e por seu nome jurarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Não andareis após deuses alheios, dos deuses dos povos que estão em vossos entornos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Porque o Deus zeloso, o SENHOR teu Deus, em meio de ti está; para que não se inflame o furor do SENHOR teu Deus contra ti, e te destrua de sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Não tentareis ao SENHOR vosso Deus, como o tentastes em Massá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Guardai cuidadosamente os mandamentos do SENHOR vosso Deus, e seus testemunhos, e seus estatutos, que te mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'E farás o correto e bom aos olhos do SENHOR, para que te vá bem, e entres e possuas a boa terra que o SENHOR jurou a teus pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Para que ele expulse a todos os seus inimigos de diante de ti, como o SENHOR disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Quando amanhã te perguntar teu filho, dizendo: Que significam os testemunhos, e estatutos, e regulamentos, que o SENHOR nosso Deus vos mandou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Então dirás a teu filho: Nós éramos servos de Faraó no Egito, e o SENHOR tirou do Egito com mão forte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'E deu o SENHOR sinais e milagres grandes e nocivos no Egito, sobre Faraó e sobre toda sua casa, diante de nossos olhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'E tirou-nos dali, para trazer-nos e dar-nos a terra que jurou a nossos pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'E mandou-nos o SENHOR que executássemos todos estes estatutos, e que temamos ao SENHOR nosso Deus, para que nos vá bem todos os dias, e para que nos dê vida, como hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'E teremos justiça quando cuidarmos de pôr por obra todos estes mandamentos diante do SENHOR nosso Deus, como ele nos mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Quando o SENHOR teu Deus te houver introduzido na terra na qual tu hás de entrar para possuí-la, e houver expulsado de diante de ti muitas nações, aos heteus, aos gergeseus, e aos amorreus, e aos cananeus, e aos perizeus, e aos heveus, e aos jebuseus, sete nações maiores e mais fortes que tu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'E o SENHOR teu Deus as houver entregue diante de ti, e as ferires, por completo as destruirás: não farás com eles aliança, nem as pouparás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'E não aparentarás com eles: não darás tua filha a seu filho, nem tomarás a sua filha para teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Porque desviará a teu filho de me seguir, e servirão a deuses alheios; e o furor do SENHOR se acenderá sobre vós, e te destruirá logo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Mas assim haveis de fazer com eles: destruireis seus altares, e quebrareis suas colunas sagradas, cortareis seus mastros de idolatria, e queimareis suas esculturas a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Porque tu és povo santo ao SENHOR teu Deus: o SENHOR teu Deus te escolheu para ser-lhe um povo especial, mais que todos os povos que estão sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Não por ser vós mais que todos os povos vos quis o SENHOR, e vos escolheu; porque vós éreis os menores de todos os povos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Mas sim porque o SENHOR vos amou, e quis guardar o juramento que jurou a vossos pais, vos tirou o SENHOR com mão forte, e vos resgatou de casa de servos, da mão de Faraó, rei do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Conhece, pois, que o SENHOR teu Deus é Deus, Deus fiel, que guarda o pacto e a misericórdia aos que lhe amam e guardam seus mandamentos, até as mil gerações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'E que retribui em sua face ao que lhe aborrece, destruindo-o: nem o dilatará ao que lhe odeia, em sua face lhe retribuirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Guarda portanto os mandamentos, e estatutos, e regulamentos que eu te mando hoje que cumpras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'E será que, por haver ouvido estes regulamentos, e guardado e os praticado, o SENHOR teu Deus guardará contigo o pacto e a misericórdia que jurou a teus pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'E te amará, e te abençoará, e te multiplicará, e abençoará o fruto de teu ventre, e o fruto de tua terra, e teu grão, e teu mosto, e teu azeite, a cria de tuas vacas, e os rebanhos de tuas ovelhas, na terra que jurou a teus pais que te daria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Bendito serás mais que todos os povos: não haverá em ti homem nem mulher estéril, nem em teus animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'E tirará o SENHOR de ti toda enfermidade; e todas as más pragas do Egito, que tu sabes, não as porá sobre ti, antes as porá sobre todos os que te odiarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'E consumirás a todos os povos que te dá o SENHOR teu Deus: não os perdoará teu olho; nem servirás a seus deuses, que te será tropeço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Quando disseres em teu coração: Estas nações são muitas mais que eu, como as poderei desarraigar?;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Não tenhas medo deles: lembra-te bem do que fez o SENHOR teu Deus com Faraó e com todo o Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Das grandes provas que viram teus olhos, e dos sinais e milagres, e da mão forte e braço estendido com que o SENHOR teu Deus te tirou: assim fará o SENHOR teu Deus com todos os povos de cuja presença tu temerdes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'E também enviará o SENHOR teu Deus sobre eles vespas, até que pereçam os que restarem, e os que se houverem escondido de diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Não desmaies diante deles, que o SENHOR teu Deus está em meio de ti, Deus grande e terrível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'E o SENHOR teu Deus expulsará a estas nações de diante de ti pouco a pouco: não as poderás acabar logo, para que os animais do campo não se aumentem contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Mas o SENHOR teu Deus as entregará diante de ti, e ele as quebrantará com grande destroço, até que sejam destruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'E ele entregará seus reis em tua mão, e tu destruirás o nome deles de debaixo do céu: ninguém te fará testa até que os destruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'As esculturas de seus deuses queimarás no fogo: não cobiçarás prata nem ouro de sobre elas para tomá-lo para ti, para que não tropeces nisso, pois é abominação ao SENHOR teu Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'E não meterás abominação em tua casa, para que não sejas anátema como isso; por completo o aborrecerás e o abominarás; porque é anátema.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Cuidareis de pôr por obra todo mandamento que eu vos ordeno hoje, para que vivais, e sejais multiplicados, e entreis, e possuais a terra, da qual jurou o SENHOR a vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'E te lembrarás de todo o caminho por onde te trouxe o SENHOR teu Deus estes quarenta anos no deserto, para afligir-te, para provar-te, para saber o que estava em teu coração, se havias de guardar ou não seus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'E te afligiu, e te fez ter fome, e te sustentou com maná, comida que não conhecias tu, nem teus pais a conheciam; para fazer-te saber que o homem não viverá de só pão, mas de tudo o que sai da boca do SENHOR viverá o homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Tua roupa nunca se envelheceu sobre ti, nem o pé se te inchou por estes quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Reconhece assim em teu coração, que como castiga o homem a seu filho, assim o SENHOR teu Deus te castiga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Guardarás, pois, os mandamentos do SENHOR teu Deus, andando em seus caminhos, e temendo-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Porque o SENHOR teu Deus te introduz na boa terra, terra de ribeiros, de águas, de fontes, de mananciais que brotam por planícies e montes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Terra de trigo e cevada, e de videiras, e figueiras, e romeiras; terra de olivas, de azeite, e de mel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Terra na qual não comerás o pão com escassez, não te faltará nada nela; terra que suas pedras são ferro, e de seus montes cortarás bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'E comerás e te fartarás, e bendirás ao SENHOR teu Deus pela boa terra que te haverá dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Guarda-te, que não te esqueças do SENHOR teu Deus, para não observar seus mandamentos, e seus regulamentos, e seus estatutos, que eu te ordeno hoje:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Para que não aconteça talvez que comas e te fartes, e edifiques boas casas em que mores,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'E tuas vacas e tuas ovelhas se aumentem, e a prata e o ouro se te multiplique, e tudo o que tiveres se te aumente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'E se eleve logo teu coração, e te esqueças do SENHOR teu Deus, que te tirou da terra do Egito, de casa de servos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Que te fez caminhar por um deserto grande e espantoso, de serpentes ardentes, e de escorpiões, e de sede, onde nenhuma água havia, e ele te tirou água da rocha de pederneiras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Que te sustentou com maná no deserto, comida que teus pais não conheciam, afligindo-te e provando-te, para ao fim fazer-te bem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'E digas em teu coração: Meu poder e a força de minha mão me trouxeram esta riqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Antes lembra-te do SENHOR teu Deus: porque ele te dá o poder para fazer as riquezas, a fim de confirmar seu pacto que jurou a teus pais, como neste dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Mas será, se chegares a esquecer-te do SENHOR teu Deus, e andares atrás de deuses alheios, e lhes servires, e a eles te encurvares, atesto-o hoje contra vós, que certamente perecereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Como as nações que o SENHOR destruirá diante de vós, assim perecereis; porquanto não havereis atendido à voz do SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Ouve, Israel: tu estás hoje para passar o Jordão, para entrar a possuir nações mais numerosas e mais fortes que tu, cidades grandes e fortificadas até o céu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Um povo grande e alto, filhos de gigantes, dos quais tens tu conhecimento, e ouviste dizer: Quem resistirá diante dos filhos do gigante?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Sabe, pois, hoje que o SENHOR teu Deus é o que passa diante de ti, fogo consumidor, que os destruirá e humilhará diante de ti: e tu os expulsarás, e os destruirás logo, como o SENHOR te disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Não digas em teu coração quando o SENHOR teu Deus os haverá expulsado de diante de ti, dizendo: Por minha justiça me pôs o SENHOR a possuir esta terra; pois pela impiedade destas nações o SENHOR as expulsa de diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Não por tua justiça, nem pela retidão de teu coração entras a possuir a terra deles; mas pela impiedade destas nações o SENHOR teu Deus as expulsa de diante de ti, e para confirmar a palavra que o SENHOR jurou a teus pais Abraão, Isaque, e Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Portanto, sabe que não por tua justiça o SENHOR teu Deus te dá esta boa terra para possuí-la; que povo duro de cerviz és tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Lembra-te, não te esqueças que provocaste a ira ao SENHOR teu Deus no deserto: desde o dia que saíste da terra do Egito, até que entrastes neste lugar, fostes rebeldes ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'E em Horebe provocastes à ira ao SENHOR, e irou-se o SENHOR contra vós para destruir-vos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Quando eu subi ao monte para receber as tábuas de pedra, as tábuas do pacto que o SENHOR fez convosco, estive então no monte quarenta dias e quarenta noites, sem comer pão nem beber água:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'E deu-me o SENHOR as duas tábuas de pedra escritas com o dedo de Deus; e nelas estava escrito conforme todas as palavras que vos falou o SENHOR no monte do meio do fogo, no dia da assembleia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'E foi ao fim dos quarenta dias e quarenta noites, que o SENHOR me deu as duas tábuas de pedra, as tábuas do pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'E disse-me o SENHOR: Levanta-te, desce logo daqui; que teu povo que tiraste do Egito se corrompeu: logo se apartaram do caminho que eu lhes mandei: fizeram para si uma efígie de fundição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'E falou-me o SENHOR, dizendo: Vi esse povo, e eis que ele é povo duro de cerviz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Deixa-me que os destrua, e apague seu nome de debaixo do céu; que eu te porei sobre gente forte e muito mais que eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'E voltei e desci do monte, o qual ardia em fogo, com as tábuas do pacto em minhas duas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'E olhei, e eis que havíeis pecado contra o SENHOR vosso Deus: Havíeis feito para vós um bezerro de fundição, desviando-vos logo do caminho que o SENHOR vos havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Então tomei as duas tábuas, e lancei-as de minhas duas mãos, e quebrei-as diante vossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'E prostrei-me diante do SENHOR, como antes, quarenta dias e quarenta noites: não comi pão nem bebi água, por causa de todo vosso pecado que havíeis cometido fazendo mal aos olhos do SENHOR para irá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Porque temi por causa do furor e da ira com que o SENHOR estava irritado contra vós para destruir-vos. Porém o SENHOR me ouviu ainda esta vez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Contra Arão também se irou o SENHOR em grande maneira para destruí-lo: e também orei por Arão então.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'E tomei vosso pecado, o bezerro que havíeis feito, e queimei no fogo, e o esmigalhei moendo-o muito bem, até que foi reduzido a pó: e lancei o pó dele no ribeiro que descia do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Também em Taberá, e em Massá, e em Quibrote-Hataavá, irritastes ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'E quando o SENHOR vos enviou desde Cades-Barneia, dizendo: Subi e possuí a terra que eu vos dei; também fostes rebeldes ao dito do SENHOR vosso Deus, e não o crestes, nem obedecestes à sua voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Rebeldes fostes ao SENHOR desde o dia que eu vos conheço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Prostrei-me, pois, diante do SENHOR quarenta dias e quarenta noites que estive prostrado; porque o SENHOR disse que vos havia de destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'E orei ao SENHOR, dizendo: Ó Senhor DEUS, não destruas teu povo e tua herança que resgataste com tua grandeza, ao qual tiraste do Egito com mão forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Lembra-te de teus servos Abraão, Isaque, e Jacó; não olhes à dureza deste povo, nem a sua impiedade, nem a seu pecado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Porque não digam os da terra de onde nos tiraste: Porquanto não pôde o SENHOR introduzi-los na terra que lhes havia dito, ou porque os aborrecia, os tirou para matá-los no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'E eles são teu povo e tua herança, que tiraste com tua grande força e com teu braço estendido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Naquele tempo o SENHOR me disse: Lavra para ti duas tábuas de pedra como as primeiras, e sobe a mim ao monte, e faze para ti uma arca de madeira:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'E escreverei naquelas tábuas palavras que estavam nas tábuas primeiras que quebraste; e as porás na arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'E fiz uma arca de madeira de acácia, e lavrei duas tábuas de pedra como as primeiras, e subi ao monte com as duas tábuas em minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'E escreveu nas tábuas conforme a primeira escritura, os dez mandamentos que o SENHOR vos havia falado no monte do meio do fogo, no dia da assembleia; e as deu a mim o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'E voltei e desci do monte, e pus as tábuas na arca que havia feito; e ali estão, como o SENHOR me mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, '(Depois partiram os filhos de Israel de Beerote-Bene-Jacacã a Moserá: ali morreu Arão, e ali foi sepultado; e em lugar seu teve o sacerdócio seu filho Eleazar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'De ali partiram a Gudgodá, e de Gudgodá a Jotbatá, terra de ribeiros de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Naquele tempo separou o SENHOR a tribo de Levi, para que levasse a arca do pacto do SENHOR, para que estivesse diante do SENHOR para servir-lhe, e para abençoar em seu nome, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Pelo qual Levi não teve parte nem herança com seus irmãos: o SENHOR é sua herança, como o SENHOR teu Deus lhe disse.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'E eu estive no monte como os primeiros dias, quarenta dias e quarenta noites; e o SENHOR me ouviu também esta vez, e não quis o SENHOR destruir-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'E disse-me o SENHOR: Levanta-te, anda, para que partas diante do povo, para que entrem e possuam a terra que jurei a seus pais lhes havia de dar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Agora, pois, Israel, que pede o SENHOR teu Deus de ti, a não ser que temas ao SENHOR teu Deus, que andes em todos os seus caminhos, e que o ames, e sirvas ao SENHOR teu Deus contudo teu coração, e com toda tua alma;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Que guardes os mandamentos do SENHOR e seus estatutos, que eu te prescrevo hoje, para que tenhas bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Eis que, do SENHOR teu Deus são os céus, e os céus dos céus: a terra, e todas as coisas que há nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Somente de teus pais se agradou o SENHOR para amá-los, e escolheu sua descendência depois deles, a vós, dentre todos os povos, como neste dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Circuncidai pois o prepúcio de vosso coração, e não endureçais mais vossa cerviz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Porque o SENHOR vosso Deus é Deus de deuses, e Senhor de senhores, Deus grande, poderoso, e terrível, que não faz acepção de pessoas, nem toma suborno;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Que faz justiça ao órfão e à viúva; que ama também ao estrangeiro dando-lhe pão e roupa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Amareis pois ao estrangeiro: porque estrangeiros fostes vós em terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Ao SENHOR teu Deus temerás, a ele servirás, a ele te achegarás, e por seu nome jurarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Ele é teu louvor, e ele é teu Deus, que fez contigo estas grandes e terríveis coisas que teus olhos viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Com setenta almas desceram teus pais ao Egito; e agora o SENHOR te fez como as estrelas do céu em multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Amarás, pois, ao SENHOR teu Deus, e guardarás sua ordenança, e seus estatutos e seus regulamentos e seus mandamentos, todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'E compreendei hoje: porque não falo com vossos filhos que não souberam nem viram o castigo do SENHOR vosso Deus, sua grandeza, sua mão forte, e seu braço estendido,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'E seus sinais, e suas obras que fez em meio do Egito a Faraó, rei do Egito, e à toda sua terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'E o que fez ao exército do Egito, a seus cavalos, e a seus carros; como fez vir as águas do mar Vermelho sobre eles, quando vinham atrás vós, e o SENHOR os destruiu até hoje;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'E o que fez convosco no deserto, até que chegastes a este lugar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'E o que fez com Datã e Abirão, filhos de Eliabe filho de Rúben; como abriu a terra sua boca, e tragou-se a eles e a suas casas, e suas tendas, e toda a riqueza que tinham em pé em meio de todo Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Mas vossos olhos viram todos os grandes feitos que o SENHOR executou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Guardai, pois, todos os mandamentos que eu vos prescrevo hoje, para que sejais esforçados, e entreis e possuais a terra, à qual passais para possuí-la;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'E para que vos sejam prolongados os dias sobre a terra, que jurou o SENHOR a vossos pais havia de dar a eles e à sua descendência, terra que flui leite e mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Que a terra à qual entras para possuí-la, não é como a terra do Egito de onde saístes, onde semeavas tua semente, e regavas com teu pé, como jardim de hortaliça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'A terra à qual passais para possuí-la, é terra de montes e de planícies; da chuva do céu há de beber as águas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Terra da qual o SENHOR teu Deus cuida: sempre estão sobre ela os olhos do SENHOR teu Deus, desde o princípio do ano até o fim dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'E será que, se obedecerdes cuidadosamente meus mandamentos que eu vos prescrevo hoje, amando ao SENHOR vosso Deus, e servindo-o com todo o vosso coração, e com toda vossa alma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Eu darei a chuva de vossa terra em seu tempo, a inicial e a tardia; e colherás teu grão, e teu vinho, e teu azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Darei também erva em teu campo para teus animais; e comerás, e te fartarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Guardai-vos, pois, que vosso coração não se engane, e vos desvieis, e sirvais a deuses alheios, e vos inclineis a eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'E assim se acenda o furor do SENHOR sobre vós, e feche os céus, e não haja chuva, nem a terra dê seu fruto, e pereçais logo da boa terra que vos dá o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Portanto, poreis estas minhas palavras em vosso coração e em vossa alma, e as atareis por sinal em vossa mão, e serão por frontais entre vossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'E as ensinareis a vossos filhos, falando delas, ora sentado em tua casa, ou andando pelo caminho, quando te deites, e quando te levantes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'E as escreverás nos umbrais de tua casa, e em tuas entradas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Para que sejam aumentados vossos dias, e os dias de vossos filhos, sobre a terra que jurou o SENHOR a vossos pais que lhes havia de dar, como os dias dos céus sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Porque se guardardes cuidadosamente todos estes mandamentos que eu vos prescrevo, para que os cumprais; como ameis ao SENHOR vosso Deus andando em todos os seus caminhos, e a ele vos achegardes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'O SENHOR também expulsará todas estas nações de diante de vós e possuireis nações grandes e mais fortes que vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Todo lugar que pisar a planta de vosso pé, será vosso: desde o deserto e o Líbano, desde o rio, o rio Eufrates, até o mar ocidental será vosso termo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Ninguém resistirá diante de vós: medo e temor de vós porá o SENHOR vosso Deus sobre a face de toda a terra que pisardes, como ele vos disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Eis que eu ponho hoje diante de vós a bênção e a maldição:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'A bênção, se ouvirdes os mandamentos do SENHOR vosso Deus, que eu vos prescrevo hoje;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'E a maldição, se não ouvirdes os mandamentos do SENHOR vosso Deus, e vos desviardes do caminho que eu vos ordeno hoje, para ir atrás de deuses alheios que não conhecestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'E será que, quando o SENHOR teu Deus te introduzir na terra à qual vais para possuí-la, porás a bênção sobre o monte Gerizim, e a maldição sobre o monte Ebal:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Os quais estão da outra parte do Jordão, atrás do caminho do ocidente na terra dos cananeus, que habitam na campina diante de Gilgal, junto às planícies de Moré.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Porque vós passais o Jordão, para ir a possuir a terra que vos dá o SENHOR vosso Deus; e a possuireis, e habitareis nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Cuidareis, pois, de pôr por obra todos os estatutos e direitos que eu apresento hoje diante de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Estes são os estatutos e regulamentos que cuidareis de pôr por obra, na terra que o SENHOR o Deus de teus pais te deu para que a possuas, todos os dias que vós viverdes sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Destruireis inteiramente todos os lugares onde as nações que vós herdardes serviram a seus deuses, sobre os montes altos, e sobre as colinas, e debaixo de toda árvore espessa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'E derrubareis seus altares, e quebrareis suas imagens, e seus bosques consumireis com fogo: e destruireis as esculturas de seus deuses, e extirpareis o nome delas daquele lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Não fareis assim ao SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Mas o lugar que o SENHOR vosso Deus escolher de todas as vossas tribos, para pôr ali seu nome para sua habitação, esse buscareis, e ali ireis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'E ali levareis vossos holocaustos, e vossos sacrifícios, e vossos dízimos, e a oferta elevada de vossas mãos, e vossos votos, e vossas ofertas voluntárias, e os primogênitos de vossas vacas e de vossas ovelhas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'E comereis ali diante do SENHOR vosso Deus, e vos alegrareis, vós e vossas famílias, em toda obra de vossas mãos em que o SENHOR teu Deus te houver abençoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Não fareis como tudo o que nós fazemos aqui agora, cada um o que lhe parece,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Porque ainda até agora não entrastes ao repouso e à herança que vos dá o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Mas passareis o Jordão, e habitareis na terra que o SENHOR vosso Deus vos faz herdar, e ele vos dará repouso de todos vossos inimigos ao redor, e habitareis seguros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'E ao lugar que o SENHOR vosso Deus escolher para fazer habitar nele seu nome, ali levareis todas as coisas que eu vos mando: vossos holocaustos, e vossos sacrifícios, vossos dízimos, e as ofertas elevadas de vossas mãos, e todo o escolhido de vossos votos que houveres prometido ao SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'E vos alegrareis diante do SENHOR vosso Deus, vós, e vossos filhos, e vossas filhas, e vossos servos, e vossas servas, e o levita que estiver em vossas povoações: porquanto não tem parte nem herança convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Guarda-te, que não ofereças teus holocaustos em qualquer lugar que vires;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Mas no lugar que o SENHOR escolher, em uma de tuas tribos, ali oferecerás teus holocaustos, e ali farás tudo o que eu te mando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Contudo, poderás matar e comer carne em todas tuas povoações conforme o desejo de tua alma, segundo a bênção do SENHOR teu Deus que ele te houver dado: o impuro e o limpo a comerá, como a de corço ou de cervo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Salvo que sangue não comereis; sobre a terra o derramareis como água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Nem poderás comer em tuas povoações o dízimo de teu grão, ou de teu vinho, ou de teu azeite, nem os primogênitos de tuas vacas, nem de tuas ovelhas, nem teus votos que prometeres, nem tuas ofertas voluntárias, nem as elevadas ofertas de tuas mãos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Mas diante do SENHOR teu Deus as comerás, no lugar que o SENHOR teu Deus houver escolhido, tu, e teu filho, e tua filha, e teu servo, e tua serva, e o levita que está em tuas povoações: e te alegrarás diante do SENHOR teu Deus em toda obra de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Tem cuidado de não desamparar ao levita em todos os teus dias sobre tua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Quando o SENHOR teu Deus alargar teu termo, como ele te disse, e tu disseres: Comerei carne, porque desejou tua alma comê-la, conforme todo o desejo de tua alma comerás carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Quando estiver longe de ti o lugar que o SENHOR teu Deus houver escolhido, para pôr ali seu nome, matarás de tuas vacas e de tuas ovelhas, que o SENHOR te houver dado, como te mandei eu, e comerás em tuas portas segundo tudo o que desejar tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'O mesmo que se come o corço e o cervo, assim as comerás: o impuro e o limpo comerão também delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Somente que te esforces a não comer sangue: porque o sangue é a alma; e não hás de comer a alma juntamente com sua carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Não o comerás: em terra o derramarás como água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Não comerás dele; para que vá bem a ti, e a teus filhos depois de ti, quando fizeres o correto aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Porém as coisas que tiveres tu consagradas, e teus votos, as tomarás, e virás ao lugar que o SENHOR houver escolhido:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'E oferecerás teus holocaustos, a carne e o sangue, sobre o altar do SENHOR teu Deus: e o sangue de teus sacrifícios será derramado sobre o altar do SENHOR teu Deus, e comerás a carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Guarda e escuta todas estas palavras que eu te mando, porque vá bem a ti e a teus filhos depois de ti para sempre, quando fizeres o bom e o correto aos olhos do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Quando houver devastado diante de ti o SENHOR teu Deus as nações aonde tu vais para possuí-las, e as herdares, e habitares em sua terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Guarda-te que não tropeces seguindo-as, depois que forem destruídas diante de ti: não perguntes acerca de seus deuses, dizendo: Da maneira que serviam aquelas nações a seus deuses, assim farei eu também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Não farás assim ao SENHOR teu Deus; porque tudo o que o SENHOR aborrece, fizeram eles a seus deuses; pois ainda a seus filhos e filhas queimavam no fogo a seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Cuidareis de fazer tudo o que eu vos mando: não acrescentarás a isso, nem tirarás disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Quando se levantar em meio de ti profeta, ou sonhador de sonhos, e te der sinal ou prodígio,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'E acontecer o sinal ou prodígio que ele te disse, dizendo: Vamos seguir deuses alheios, que não conheceste, e os sirvamos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Não darás ouvido às palavras de tal profeta, nem ao tal sonhador de sonhos: porque o SENHOR vosso Deus vos prova, para saber se amais ao SENHOR vosso Deus com todo o vosso coração, e com toda vossa alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Atrás do SENHOR vosso Deus andareis, e a ele temereis, e guardareis seus mandamentos, e escutareis sua voz, e a ele servireis, e a ele vos achegareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'E o tal profeta ou sonhador de sonhos, será morto; porquanto tratou de rebelião contra o SENHOR vosso Deus, que te tirou da terra do Egito, e te resgatou de casa de servos, e de tirar-te do caminho pelo que o SENHOR teu Deus te mandou que andasses; e assim tirarás o mal do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Quando te incitar teu irmão, filho de tua mãe, ou teu filho, ou tua filha, ou a mulher de teu seio, ou teu amigo que seja como tua alma, dizendo em secreto: Vamos e sirvamos a deuses alheios, que nem tu nem teus pais conhecestes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Aos deuses dos povos que estão em vossos arredores próximo a ti, ou longe de ti, desde um fim da terra até o outro fim dela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Não consentirás com ele, nem lhe darás ouvido; nem teu olho o perdoará, nem terás compaixão, nem o encobrirás:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Antes hás de matá-lo; tua mão será primeira sobre ele para matar-lhe, e depois a mão de todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'E hás de apedrejá-lo com pedras, e morrerá; porquanto procurou desviar-te do SENHOR teu Deus, que te tirou da terra do Egito, de casa de servos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Para que todo Israel ouça, e tema, e não voltem a fazer coisa semelhante a esta má coisa em meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Quando ouvires de alguma de tuas cidades que o SENHOR teu Deus te dá para que mores nelas, que se diz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Homens, filhos de impiedade, saíram do meio de ti, que instigaram aos moradores de sua cidade, dizendo: Vamos e sirvamos a deuses alheios, que vós não conhecestes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Tu investigarás, e buscarás, e preguntarás com empenho; e se parecer verdade, coisa certo, que tal abominação se fez em meio de ti,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Invariavelmente ferirás a fio de espada os moradores daquela cidade, destruindo-a contudo o que nela houver, e também seus animais a fio de espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'E juntarás todo o despojo dela em meio de sua praça, e consumirás com fogo a cidade e todo seu despojo, todo ele, ao SENHOR teu Deus: e será um amontoado para sempre: nunca mais se edificará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'E não se pegará algo a tua mão do anátema; porque o SENHOR se afaste do furor de sua ira, e te dê compaixão, e tenha misericórdia de ti, e te multiplique, como o jurou a teus pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Quando obedeceres à voz do SENHOR teu Deus, guardando todos os seus mandamentos que eu te prescrevo hoje, para fazer o correto aos olhos do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Filhos sois do SENHOR vosso Deus: não vos cortareis, nem poreis calva sobre vossos olhos por morto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Porque és povo santo ao SENHOR teu Deus, e o SENHOR te escolheu para que lhe sejas um povo singular dentre todos os povos que estão sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Nada abominável comerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Estes são os animais que comereis: o boi, a ovelha, e a cabra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'O cervo, o corço, e o búfalo, e o bode selvagem, e o antílope, e boi selvagem, e cabra selvagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'E todo animal de unhas, que tem brecha de duas unhas, e que ruminar entre os animais, esse comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Porém estes não comereis dos que ruminam, ou têm unha fendida: camelo, e lebre, e coelho, porque ruminam, mas não têm unha fendida, vos serão impuros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Nem porco: porque tem unha fendida, mas não rumina, vos será impuro. Da carne destes não comereis, nem tocareis seus corpos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Isto comereis de tudo o que está na água: todo o que tem barbatana e escama comereis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Mas todo o que não tiver barbatana e escama, não comereis: impuro vos será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Toda ave limpa comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'E estas são das que não comereis: a água, e o quebra-ossos, e o esmerilhão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'E o milhafre, e o abutre, e o falcão segundo sua espécie,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'E todo corvo segundo sua espécie,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'E o avestruz, e a coruja, e a gaivota, e o gavião segundo sua espécie,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'E o mocho, e o corujão, e a coruja-branca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'E o pelicano, e o gavião-pescador, e o corvo-marinho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'E a cegonha, e a garça segundo sua espécie, e a poupa, e o morcego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'E todo inseto de asas vos será impuro: não se comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Toda ave limpa comereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Nenhuma coisa morta comereis: ao estrangeiro que está em tuas povoações a darás, e ele a comerá: ou vende-a ao estrangeiro; porque tu és povo santo ao SENHOR teu Deus. Não cozerás o cabrito no leite de sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Indispensavelmente dizimarás todo o produto de tua semente, que render o campo cada ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'E comerás diante do SENHOR teu Deus no lugar que ele escolher para fazer habitar ali seu nome, o dízimo de teu grão, de teu vinho, e de teu azeite, e os primogênitos de tuas manadas, e de tuas gados, para que aprendas a temer ao SENHOR teu Deus todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'E se o caminho for tão longo que tu não possas levá-lo por ele, por estar longe de ti o lugar que o SENHOR teu Deus houver escolhido para pôr nele seu nome, quando o SENHOR teu Deus te abençoar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Então o venderás, e atarás o dinheiro em tua mão, e virás ao lugar que o SENHOR teu Deus escolher;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'E darás o dinheiro por tudo o que desejar tua alma, por vacas, ou por ovelhas, ou por vinho, ou por bebida forte, ou por qualquer coisa que tua alma te pedir: e comerás ali diante do SENHOR teu Deus, e te alegrarás tu e tua família.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'E não desampararás ao levita que habitar em tuas povoações; porque não tem parte nem herança contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Ao fim de cada três anos tirarás todo o dízimo de teus produtos daquele ano, e o guardarás em tuas cidades:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'E virá o levita, que não tem parte nem herança contigo, e o estrangeiro, e o órfão, e a viúva, que houver em tuas povoações, e comerão e serão saciados; para que o SENHOR teu Deus te abençoe em toda obra de tuas mãos que fizeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Ao fim de sete anos farás remissão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'E esta é a maneira da remissão: perdoará a seu devedor todo aquele que fez empréstimo de sua mão, com que obrigou a seu próximo: não o exigirá mais a seu próximo, ou a seu irmão; porque a remissão do SENHOR é proclamada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Do estrangeiro exigirás o pagamento: mas o que teu irmão tiver teu, o perdoará tua mão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Para que assim não haja em ti pobre; porque o SENHOR te abençoará com abundância na terra que o SENHOR teu Deus te dá por herança para que a possuas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Se porém escutares fielmente a voz do SENHOR teu Deus, para guardar e cumprir todos estes mandamentos que eu te intimo hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Já que o SENHOR teu Deus te haverá abençoado, como te disse, emprestarás então a muitas nações, mas tu não tomarás emprestado; e te ensenhorearás de muitas nações, mas de ti não se ensenhorearão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Quando houver em ti necessitado de algum de teus irmãos em alguma de tuas cidades, em tua terra que o SENHOR teu Deus te dá, não endurecerás teu coração, nem fecharás tua mão a teu irmão pobre:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Mas abrirás a ele tua mão generosamente, e com efeito lhe emprestarás o que basta, o que houver necessidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Guarda-te que não haja em teu coração perverso pensamento, dizendo: Próximo está o ano sétimo, o da remissão; e tua olho seja maligno sobre teu irmão necessitado para não dar-lhe: que ele poderá clamar contra ti ao SENHOR, e se te imputará a pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Sem falta lhe darás, e não seja teu coração maligno quando lhe deres: que por ele te abençoará o SENHOR teu Deus em todos os teus feitos, e em tudo o que puseres mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Porque não faltarão necessitados do meio da terra; por isso eu te mando, dizendo: Abrirás tua mão a teu irmão, a teu pobre, e a teu necessitado em tua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Quando se vender a ti teu irmão hebreu ou hebreia, e te houver servido seis anos, ao sétimo ano lhe despedirás livre de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'E quando o despedires livre de ti, não o enviarás vazio:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Tu lhe abastecerás generosamente de tuas ovelhas, de tua eira, e de teu lagar; lhe darás daquilo em que o SENHOR te houver abençoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'E te lembrarás que foste servo na terra do Egito, e que o SENHOR teu Deus te resgatou: portanto eu te mando isto hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'E será que, se ele te disser: Não sairei de tua presença; porque ama a ti e à tua casa, que lhe vai bem contigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Então tomarás uma ferramenta pontiaguda, e furarás sua orelha junto à porta, e será teu servo para sempre: assim também farás à tua criada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Não te pareça duro quando lhe enviares livre de ti; que dobrado do salário de jovem assalariado te serviu seis anos: e o SENHOR teu Deus te abençoará em tudo quanto fizeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Santificarás ao SENHOR teu Deus todo primeiro macho que nascer de tuas vacas e de tuas ovelhas: não te sirvas do primeiro de tuas vacas, nem tosquies o primeiro de tuas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Diante do SENHOR teu Deus os comerás cada ano, tu e tua família, no lugar que o SENHOR escolher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'E se houver nele mácula, cego ou coxo, ou qualquer má falta, não o sacrificarás ao SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Em tuas povoações o comerás: o impuro o mesmo que o limpo comerão dele, como de um corço ou de um cervo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Somente que não comas seu sangue: sobre a terra a derramarás como água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Guardarás o mês de Abibe, e farás páscoa ao SENHOR teu Deus: porque no mês de Abibe te tirou o SENHOR teu Deus do Egito de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'E sacrificarás a páscoa ao SENHOR teu Deus, das ovelhas e das vacas, no lugar que o SENHOR escolher para fazer habitar ali seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Não comerás com ela levedado; sete dias comerás com ela pão sem levedar, pão de aflição, porque apressadamente saíste da terra do Egito: para que te lembres do dia em que saíste da terra do Egito todos os dias de tua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'E não se deixará ver levedura contigo em todo teu termo por sete dias; e da carne que matares à tarde do primeiro dia, não ficará até a manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Não poderás sacrificar a páscoa em nenhuma de tuas cidades, que o SENHOR teu Deus te dá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Mas sim no lugar que o SENHOR teu Deus escolher para fazer habitar ali seu nome, sacrificarás a páscoa pela tarde ao pôr do sol, ao tempo que saíste do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'E a assarás e comerás no lugar que o SENHOR teu Deus houver escolhido; e pela manhã te voltarás e irás à tua morada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Seis dias comerás pães ázimos, e no sétimo dia será solenidade ao SENHOR teu Deus: não farás obra nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sete semanas te contarás: desde que começar a foice nas plantações de grãos começarás a contar as sete semanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'E farás a solenidade das semanas ao SENHOR teu Deus: da suficiência voluntária de tua mão será o que deres, segundo o SENHOR teu Deus te houver abençoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'E te alegrarás diante do SENHOR teu Deus, tu, e teu filho, e tua filha, e teu servo, e tua serva, e o levita que estiver em tuas cidades, e o estrangeiro, e o órfão, e a viúva, que estiverem em meio de ti, no lugar que o SENHOR teu Deus houver escolhido para fazer habitar ali o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'E lembra-te que foste servo no Egito; portanto guardarás e cumprirás estes estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'A solenidade das cabanas farás por sete dias, quando houveres feito a colheita de tua eira e de teu lagar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'E te alegrarás em tuas solenidades, tu, e teu filho, e tua filha, e teu servo, e tua serva, e o levita, e o estrangeiro, e o órfão, e a viúva, que estão em tuas povoações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sete dias celebrarás solenidade ao SENHOR teu Deus no lugar que o SENHOR escolher; porque te haverá abençoado o SENHOR teu Deus em todos os teus frutos, e em toda obra de tuas mãos, e estarás certamente alegre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Três vezes cada ano comparecerá todo homem teu diante do SENHOR teu Deus no lugar que ele escolher: na solenidade dos pães ázimos, e na solenidade das semanas, e na solenidade das cabanas. E não comparecerá vazio diante do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Cada um com o presente de sua mão, conforme a bênção do SENHOR teu Deus, que te houver dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Juízes e oficiais te porás em todas tuas cidades que o SENHOR teu Deus te dará em tuas tribos, os quais julgarão ao povo com justo juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Não distorças o direito; não faças acepção de pessoas, nem tomes suborno; porque o suborno cega os olhos dos sábios, e perverte as palavras dos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'A justiça, a justiça seguirás, para que vivas e herdes a terra que o SENHOR teu Deus te dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Não plantarás árvore que sirva de mastro de idolatria junto ao altar do SENHOR, teu Deus, que fizeres para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Nem levantarás para ti coluna sagrada de pedra, a qual o SENHOR, teu Deus, odeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Não sacrificarás ao SENHOR teu Deus boi, ou cordeiro, no qual haja falta ou alguma coisa má: porque é abominação ao SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Quando se achar entre ti, em alguma de tuas cidades que o SENHOR teu Deus te dá, homem, ou mulher, que tenha feito mal aos olhos do SENHOR teu Deus transgredido seu pacto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'Que houver ido e servido a deuses alheios, e se houver inclinado a eles, ora ao sol, ou à lua, ou a todo o exército do céu, o qual eu não mandei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'E te for dado aviso, e, depois que ouvires e houveres indagado bem, a coisa parece de verdade certa, que tal abominação foi feita em Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Então tirarás ao homem ou mulher que houver feito esta má coisa, a tuas portas, homem ou mulher, e os apedrejarás com pedras, e assim morrerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Por dito de duas testemunhas, ou de três testemunhas, morrerá o que houver de morrer; não morrerá pelo dito de uma só testemunha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'A mão das testemunhas será primeira sobre ele para matá-lo, e depois a mão de todo o povo: assim tirarás o mal do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Quando alguma coisa te for oculta em juízo entre sangue e sangue, entre causa e causa, e entre chaga e chaga, em negócios de litigio em tuas cidades; então te levantarás e recorrerás ao lugar que o SENHOR teu Deus escolher;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'E virás aos sacerdotes levitas, e ao juiz que for naqueles dias, e preguntarás; e te ensinarão a sentença do juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'E farás segundo a sentença que te indicarem os do lugar que o SENHOR escolher, e cuidarás de fazer segundo tudo o que te manifestarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Segundo a lei que eles te ensinarem, e segundo o juízo que te disserem, farás: não te desviarás nem à direita nem à esquerda da sentença que te mostrarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'E o homem que proceder com soberba, não obedecendo ao sacerdote que está para ministrar ali diante do SENHOR teu Deus, ou ao juiz, o tal homem morrerá: e tirarás o mal de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'E todo o povo ouvirá, e temerá, e não se ensoberbecerão mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Quando houveres entrado na terra que o SENHOR teu Deus te dá, e a possuíres, e habitares nela, e disseres: Porei rei sobre mim, como todas as nações que estão em meus arredores;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Sem dúvida porás por rei sobre ti ao que o SENHOR teu Deus escolher: dentre teus irmãos porás rei sobre ti: não poderás pôr sobre ti homem estrangeiro, que não seja teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Porém que não se aumente cavalos, nem faça voltar o povo ao Egito para acrescentar cavalos: porque o SENHOR vos disse: Não procurareis voltar mais por este caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Nem aumentará para si mulheres, para que seu coração não se desvie: nem prata nem ouro acrescentará para si em grande quantidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'E será, quando se assentar sobre o trono de seu reino, que há de escrever para si em um livro uma cópia desta lei, do original de diante dos sacerdotes levitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'E o terá consigo, e lerá nele todos os dias de sua vida, para que aprenda a temer ao SENHOR seu Deus, para guardar todas as palavras desta lei e estes estatutos, para praticá-los:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Para que não se eleve seu coração sobre seus irmãos, nem se desvie do mandamento à direita nem à esquerda; a fim que prolongue seus dias em seu reino, ele e seus filhos, em meio de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Os sacerdotes levitas, toda a tribo de Levi, não terão parte nem herança com Israel; das ofertas acendidas ao SENHOR, e da herança dele comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Não terão, pois, herança entre seus irmãos: o SENHOR é a sua herança, como ele lhes disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'E este será o direito dos sacerdotes da parte do povo, dos que oferecerem em sacrifício boi ou cordeiro: darão ao sacerdote a retaguarda, e as queixadas, e o estômago.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'As primícias de teus grãos, de teu vinho, e de teu azeite, e as primícias da lã de tuas ovelhas lhe darás:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Porque o escolheu o SENHOR teu Deus de todas tuas tribos, para que esteja para ministrar ao nome do SENHOR, ele e seus filhos para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'E quando o levita sair de alguma de tuas cidades de todo Israel, onde houver peregrinado, e vier com todo desejo de sua alma ao lugar que o SENHOR escolher,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Ministrará ao nome do SENHOR seu Deus, como todos os seus irmãos os levitas que estiverem ali diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Porção como a porção dos outros comerão, além de seus patrimônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Quando houveres entrado na terra que o SENHOR teu Deus te dá, não aprenderás a fazer segundo as abominações daquelas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Não seja achado em ti quem faça passar seu filho ou sua filha pelo fogo, nem praticante de adivinhações, nem agoureiro, nem interpretador de presságios, nem feiticeiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Nem quem fale encantamentos, nem quem pergunte a espírito, nem mágico, nem quem pergunte aos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Porque é abominação ao SENHOR qualquer um que faz estas coisas, e por estas abominações o SENHOR teu Deus as expulsou de diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Serás íntegro com o SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Pois essas nações que herdarás ouviam encantadores e feiticeiros. A ti, porém, o SENHOR teu Deus não te permitiu isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'O SENHOR teu Deus suscitará para ti um Profeta do meio de ti, de teus irmãos, como eu; a ele deverás ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Conforme tudo o que pediste ao SENHOR teu Deus em Horebe no dia da assembleia, dizendo: Não volte eu a ouvir a voz do SENHOR meu Deus, nem veja eu mais este grande fogo, para que não morra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'e o SENHOR me disse: Bem disseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Profeta lhes suscitarei do meio de seus irmãos, como tu; e porei minhas palavras em sua boca, e ele lhes falará tudo o que eu lhe mandar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Mas será, que qualquer um que não ouvir minhas palavras que ele falar em meu nome, eu lhe exigirei prestar contas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Porém o profeta que presumir falar palavra em meu nome, que eu não lhe tenha mandado falar, ou que falar em nome de deuses alheios, o tal profeta morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'E se disseres em teu coração: Como conheceremos a palavra que o SENHOR não houver falado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Quando o profeta falar em nome do SENHOR, e não for a tal coisa, nem vier, é palavra que o SENHOR não falou: com soberba a falou aquele profeta: não tenhas medo dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Quando o SENHOR teu Deus exterminar as nações, cuja terra o SENHOR teu Deus dá a ti, e tu as herdares, e habitares em suas cidades, e em suas casas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Separarás três cidades em meio de tua terra que o SENHOR teu Deus te dá para que a possuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Prepararás o caminho, e dividirás em três partes o termo de tua terra, que o SENHOR teu Deus te dará em herança, e será para que todo homicida se fuja ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'E este é o caso do homicida que há de fugir ali, e viverá: o que ferir a seu próximo por acidente, que não lhe tinha inimizade nem recente nem em passado distante:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Como o que foi com seu próximo ao monte a cortar lenha, e pondo força com sua mão no machado para cortar alguma lenha, saltou o ferro do fim, e encontrou a seu próximo, e morreu; aquele fugirá a uma daquelas cidades, e viverá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Não seja que o parente do morto vá atrás do homicida, quando se arder seu coração, e o alcance por ser longo o caminho, e o fira de morte, não devendo ser condenado à morte; porquanto não tinha inimizade nem recente nem em passado distante com o morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Portanto eu te mando, dizendo: Três cidades separarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'E se o SENHOR teu Deus alargar teu termo, como o jurou a teus pais, e te der toda a terra que disse a teus pais que havia de dar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Quando guardasses todos estes mandamentos, que eu te prescrevo hoje, para praticá-los, que ames ao SENHOR teu Deus e andes em seus caminhos todos os dias, então acrescentarás três cidades a mais destas três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Para que não seja derramado sangue inocente em meio de tua terra, que o SENHOR teu Deus te dá por herança, e seja sobre ti sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mas quando houver alguém que aborrecer a seu próximo, e o espreitar, e se levantar sobre ele, e o ferir de morte, e morrer, e fugir a alguma destas cidades;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Então os anciãos de sua cidade enviarão e o tirarão dali, e o entregarão em mão do parente do morto, e morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Não lhe perdoará teu olho: e tirarás de Israel o sangue inocente, e te irá bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Não reduzirás o termo de teu próximo, o qual assinalaram os antigos em tua herança, a que possuíres na terra que o SENHOR teu Deus te dá para que a possuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Não valerá uma testemunha contra ninguém em qualquer delito, ou em qualquer pecado, em qualquer pecado que se cometer. No dito de duas testemunhas, ou no dito de três testemunhas consistirá o negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Quando se levantar testemunha falso contra alguém, para testificar contra ele rebelião,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Então os dois homens litigantes se apresentarão diante do SENHOR, diante dos sacerdotes e juízes que forem naqueles dias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'E os juízes investigarão bem, e se parecer ser aquela testemunha falsa, que testificou falsamente contra seu irmão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Fareis a ele como ele pensou fazer a seu irmão: e tirarás o mal do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'E os que restarem ouvirão, e temerão, e não voltarão mais a fazer uma má coisa como esta, em meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'E não perdoará teu olho: vida por vida, olho por olho, dente por dente, mão por meio, pé por pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Quando saíres à guerra contra teus inimigos, e vires cavalos e carros, um povo maior que tu, não tenhas medo deles, que o SENHOR teu Deus é contigo, o qual te tirou da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'E será que, quando vos aproximardes para combater, chegará o sacerdote, e falará ao povo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'E lhes dirá: Ouve, Israel, vós vos juntais hoje em batalha contra vossos inimigos: não se amoleça vosso coração, não temais, não vos alarmeis, nem tampouco vos desanimeis diante deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Que o SENHOR vosso Deus anda convosco, para lutar por vós contra vossos inimigos, para vos salvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'E os oficiais falarão ao povo, dizendo: Quem edificou casa nova, e não a dedicou? Vá, e volte-se à sua casa, para que talvez não morra na batalha, e outro algum a dedique.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'E quem plantou vinha, e não fez comum uso dela? Vá, e volte-se à sua casa, para que talvez não morra na batalha, e outro alguém a desfrute.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'E quem se desposou com mulher, e não a tomou? Vá, e volte-se à sua casa, para que talvez não morra na batalha, e algum outro a tome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'E tornarão os oficiais a falar ao povo, e dirão: Quem é homem medroso e tenro de coração? Vá, e volte-se à sua casa, e não derreta o coração de seus irmãos, como seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'E será que, quando os oficiais acabarem de falar ao povo, então os capitães dos exércitos mandarão diante do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Quando te aproximares a uma cidade para combatê-la, lhe oferecerás a paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'E será que, se te responder, Paz, e te abrir, todo o povo que nela for achado te serão tributários, e te servirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Mas se não fizer paz contigo, e empreender contigo guerra, e a cercares,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Logo que o SENHOR teu Deus a entregar em tua mão, ferirás a todo homem seu a fio de espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Somente as mulheres e as crianças, e os animais, e todo o que houver na cidade, todos os seus despojos, tomarás para ti: e comerás do despojo de teus inimigos, os quais o SENHOR teu Deus te entregou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Assim farás a todas as cidades que estiverem muito longe de ti, que não forem das cidades destas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Porém das cidades destes povos que o SENHOR teu Deus te dá por herança, nenhuma pessoa deixarás com vida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Antes por completo os destruirás: aos heteus, e aos amorreus, e aos cananeus, e aos perizeus, e aos heveus, e aos jebuseus; como o SENHOR teu Deus te mandou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Para que não vos ensinem a fazer segundo todas suas abominações, que eles fazem a seus deuses, e pequeis contra o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Quando puseres cerco a alguma cidade, lutando contra ela muitos dias para tomá-la, não destruas seu arvoredo metendo nele machado, porque dele comerás; e não o cortarás, que não é homem a árvore do campo para vir contra ti no cerco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Mas a árvore que souberes que não é árvore para comer, o destruirás e o cortarás, e constrói baluarte contra a cidade que luta contigo, até subjugá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Quando for achado na terra que o SENHOR teu Deus te dá para que a possuas, morto deitado no campo, e não se soubesse quem o feriu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Então teus anciãos e teus juízes sairão e medirão até as cidades que estão ao redor do morto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'E será que os anciãos daquela cidade, da cidade mais próxima ao morto, tomarão das vacas uma bezerra que não tenha servido, que não tenha trazido jugo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'E os anciãos daquela cidade trarão a bezerra a um vale por onde fluam águas, que nunca tenha sido arado nem semeado, e cortarão o pescoço à bezerra ali no vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Então virão os sacerdotes filhos de Levi, porque a eles escolheu o SENHOR teu Deus para que o sirvam, e para abençoar em nome do SENHOR; e pelo dito deles se determinará todo pleito e toda ferida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'E todos os anciãos daquela cidade mais próxima ao morto lavarão suas mãos sobre a bezerra degolada no vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'E protestarão, e dirão: Nossas mãos não derramaram este sangue, nem nossos olhos o viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Expia a teu povo Israel, ao qual redimiste, ó SENHOR; e não imputes o sangue inocente derramado em meio de teu povo Israel. E o sangue lhes será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'E tu tirarás a culpa de sangue inocente do meio de ti, quando fizeres o que é correto aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Quando saíres à guerra contra teus inimigos, e o SENHOR teu Deus os entregar em tua mão, e tomares deles cativos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'E vires entre os cativos alguma mulher bela, e a cobiçares, e a tomares para ti por mulher,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Tu a meterás em tua casa; e ela rapará sua cabeça, e cortará suas unhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'E se tirará a roupa de seu cativeiro, e ficará em tua casa: e chorará a seu pai e a sua mãe no tempo de um mês: e depois entrarás a ela, e tu serás seu marido, e ela tua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'E será, se não te agradar, que a deixarás em sua liberdade; e não a venderás por dinheiro, nem farás comércio dela, porquanto a afligiste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Quando um homem tiver duas mulheres, uma amada e a outra aborrecida, e a amada e a aborrecida lhe derem à luz filhos, e o filho primogênito for da aborrecida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Será que, no dia que fizer herdar a seus filhos o que tiver, não poderá dar o direito de primogenitura aos filhos da amada em preferência ao filho da aborrecida, que é o primogênito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Mas ao filho da aborrecida reconhecerá por primogênito, para dar-lhe dois tantos de tudo o que se achar que tem: porque aquele é o princípio de sua força, o direito da primogenitura é seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Quando alguém tiver filho obstinado e rebelde, que não obedecer à voz de seu pai nem à voz de sua mãe, e havendo-o castigado, não lhes obedecer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Então o tomarão seu pai e sua mãe, e o tirarão aos anciãos de sua cidade, e à porta do lugar seu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'E dirão aos anciãos da cidade: Este nosso filho é obstinado e rebelde, não obedece à nossa voz; é comilão e beberrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Então todos os homens de sua cidade o apedrejarão com pedras, e morrerá: assim tirarás o mal do meio de ti; e todo Israel ouvirá, e temerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Quando em alguém houver pecado de sentença de morte, pelo que haja de morrer, e lhe houverdes pendurado em um madeiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Não estará seu corpo pela noite no madeiro, mas sem falta o enterrarás no mesmo dia, porque maldição de Deus é o pendurado: e não contaminarás tua terra, que o SENHOR teu Deus te dá por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Não verás o boi de teu irmão, ou seu cordeiro, perdidos, e te retirarás deles: precisamente os devolverás a teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'E se teu irmão não for teu vizinho, ou não lhe conheceres, os recolherás em tua casa, e estarão contigo até que teu irmão os busque, e os devolverás a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'E assim farás de seu asno, assim farás também de sua roupa, e o mesmo farás com toda coisa perdida de teu irmão que se lhe perder, e tu a achares: não poderás te omitir quanto a isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Não verás o asno de teu irmão, ou seu boi, caídos no caminho, e te esconderás deles: com ele hás de procurar levantá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Não vestirá a mulher roupa de homem, nem o homem vestirá roupa de mulher; porque abominação é ao SENHOR teu Deus qualquer um que isto faz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Quando achares no caminho algum ninho de ave em qualquer árvore, ou sobre a terra, com passarinhos ou ovos, e estiver a mãe reclinada sobre os passarinhos ou sobre os ovos, não tomes a mãe com os filhos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Deixarás ir à mãe, e tomarás os passarinhos para ti; para que te vá bem, e prolongues teus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Quando edificares casa nova, farás parapeito em teu terraço, para que não ponhas sangue em tua casa, se dele cair alguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Não semearás tua vinha de várias sementes, para que não se deprave a plenitude da semente que semeaste, e o fruto da vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Não ararás com boi e com asno juntamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Não te vestirás de mistura, de lã e linho juntamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Farás para ti franjas nos quatro extremos de teu manto com que te cobrires.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Quando alguém tomar mulher, e depois de haver entrado a ela a aborrecer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'E lhe puser algumas faltas, e espalhar sobre ela má fama, e disser: Esta tomei por mulher, e cheguei a ela, e não a achei virgem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Então o pai da moça e sua mãe tomarão, e tirarão os sinais da virgindade da virgem aos anciãos da cidade, na porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'E dirá o pai da moça aos anciãos: Eu dei minha filha a este homem por mulher, e ele a aborrece;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'E, eis que, ele lhe põe acusações de algumas coisas, dizendo: Não achei tua filha virgem; porém, eis aqui os sinais da virgindade de minha filha. E estenderão o lençol diante dos anciãos da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Então os anciãos da cidade tomarão ao homem e o castigarão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'E lhe hão de impor pena em cem peças de prata, as quais darão ao pai da moça, porquanto espalhou má fama sobre virgem de Israel: e a há de ter por mulher, e não poderá despedi-la em todos os seus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Mas se este negócio foi verdade, que não se houver achado virgindade na moça,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Então a tirarão à porta da casa de seu pai, e a apedrejarão com pedras os homens de sua cidade, e morrerá; porquanto fez depravação em Israel prostituindo-se em casa de seu pai: assim tirarás o mal do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Quando se surpreender alguém deitado com mulher casada com marido, ambos morrerão, o homem que se deitou com a mulher, e a mulher: assim tirarás o mal de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Quando for moça virgem desposada com alguém, e alguém a achar na cidade, e se deixar com ela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Então os tirareis a ambos à porta daquela cidade, e os apedrejareis com pedras, e morrerão; a moça porque não gritou na cidade, e o homem porque humilhou à mulher de seu próximo: assim tirarás o mal do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Mas se o homem achou uma moça desposada no campo, e ele a agarrar, e se deitar com ela, morrerá somente o homem que com ela se houver deitado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'E à moça não farás nada; não tem a moça culpa de morte: porque como quando alguém se levanta contra seu próximo, e lhe tira a vida, assim é isto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Porque ele a achou no campo: gritou a moça desposada, e não houve quem a protegesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Quando alguém achar moça virgem, que não for desposada, e a tomar, e se deitar com ela, e forem achados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Então o homem que se deitou com ela dará ao pai da moça cinquenta peças de prata, e ela será sua mulher, porquanto a humilhou: não a poderá despedir em todos os seus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Não tomará alguém a mulher de seu pai, nem descobrirá o colo de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Não entrará na congregação do SENHOR o que tiver os testículos esmagados, nem o castrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Não entrará bastardo na congregação do SENHOR: nem ainda na décima geração entrará na congregação do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Não entrará amonita nem moabita na congregação do SENHOR; nem ainda na décima geração entrará na congregação do SENHOR para sempre:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Porquanto não vos saíram a receber com pão e água ao caminho, quando saístes do Egito; e porque contratou contra ti a Balaão filho de Beor de Petor de Mesopotâmia da Síria, para que te amaldiçoasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Mas não quis o SENHOR teu Deus ouvir a Balaão; e o SENHOR teu Deus te tornou a maldição em bênção, porque o SENHOR teu Deus te amava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Não procurarás a paz deles nem seu bem em todos os dias para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Não abominarás ao edomita, que teu irmão é: não abominarás ao egípcio, que estrangeiro foste em sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Os filhos que nascerem deles, à terceira geração entrarão na congregação do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Quando saíres a campanha contra teus inimigos, guarda-te de toda coisa má.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Quando houver em ti alguém que não for limpo por acidente de noite, sairá do acampamento, e não entrará nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'E será que ao declinar da tarde se lavará com água, e quando for posto o sol, entrará no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'E terás um lugar fora do acampamento, e sairás ali fora;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Terás também uma estaca entre tuas armas; e será que, quando estiveres ali fora, cavarás com ela, e logo ao voltar cobrirás teu excremento:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Porque o SENHOR teu Deus anda por meio de teu acampamento, para livrar-te e entregar teus inimigos diante de ti; portanto será teu acampamento santo: para que ele não veja em ti coisa imunda, e se volte de trás de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Não entregarás a seu senhor o servo que se fugir a ti de seu amo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'More contigo, em meio de ti, no lugar que escolher em alguma de tuas cidades, onde bem lhe estiver: não o oprimirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Não haverá prostituta das filhas de Israel, nem haverá prostituto ritual dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Não trarás pagamento de prostituta, nem pagamento de prostituto à casa do SENHOR teu Deus por nenhum voto; porque abominação é ao SENHOR teu Deus tanto um como o outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Não tomarás de teu irmão juros de dinheiro, nem juros de comida, nem juros de coisa alguma que se costuma tomar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Do estrangeiro tomarás juros, mas de teu irmão não o tomarás, para que te abençoe o SENHOR teu Deus em toda obra de tuas mãos sobre a terra à qual entras para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Quando prometeres voto ao SENHOR teu Deus, não tardarás em pagá-lo; porque certamente o exigirá o SENHOR teu Deus de ti, e haveria em ti pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Mas quando te abstiveres de prometer, não haverá em ti pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Guardarás o que teus lábios pronunciarem; e farás, como prometeste ao SENHOR teu Deus, o que de tua vontade falaste por tua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Quando entrares na vinha de teu próximo, comerás uvas até saciar teu desejo: mas não porás em teu vaso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Quando entrares na plantação de teu próximo, poderás cortar espigas com tua mão; mas não aplicarás foice à plantação de teu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Quando algum tomar mulher e se casar com ela, se não lhe agradar por haver achado nela alguma coisa ofensiva, lhe escreverá carta de divórcio, e a entregará em sua mão, e a despedirá de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'E saída de sua casa, poderá ir e casar-se com outro homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'E se a aborrecer este último, e lhe escrever carta de divórcio, e a entregar em sua mão, e a despedir de sua casa; ou se morrer o posterior homem que a tomou para si por mulher,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Não poderá seu primeiro marido, que a despediu, trazê-la de volta a tomar para que seja sua mulher, depois que foi contaminada; porque é abominação diante do SENHOR, e não hás de perverter a terra que o SENHOR teu Deus te dá por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Quando tomar alguém mulher nova, não sairá à guerra, nem em nenhuma coisa se lhe ocupará; livre estará em sua casa por ano, para alegrar à sua mulher que tomou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Não tomarás em penhor a pedra de moinho, nem a de baixo nem a de cima: porque seria penhorar a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Quando for achado alguém que tenha furtado pessoa de seus irmãos os filhos de Israel, e houver comercializado com ela, ou a houver vendido, o tal ladrão morrerá, e tirarás o mal do meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Guarda-te de chaga de lepra, observando com empenho, e fazendo segundo tudo o que vos ensinarem os sacerdotes levitas: cuidareis de fazer como lhes mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Lembra-te do que fez o SENHOR teu Deus a Miriã no caminho, depois que saístes do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Quando deres a teu próximo alguma coisa emprestada, não entrarás em sua casa para tomar-lhe penhor:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Fora estarás, e o homem a quem emprestaste, te tirará fora o penhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'E se for homem pobre, não durmas com seu penhor:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Precisamente lhe devolverás o penhor quando o sol se ponha, para que durma em sua roupa, e te bendiga: e te será justiça diante do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Não faças injustiça ao empregado pobre e necessitado, tanto de teus irmãos como de teus estrangeiros que estão em tua terra em tuas cidades:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Em seu dia lhe darás seu salário, e não se porá o sol sem o dar a ele: pois é pobre, e com ele sustenta sua vida: para que não clame contra ti ao SENHOR, e seja em ti pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Os pais não morrerão pelos filhos, nem os filhos pelos pais; cada um morrerá por seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Não distorcerás o direito do peregrino e do órfão; nem tomarás por penhor a roupa da viúva:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Mas lembra-te que foste servo no Egito, e dali te resgatou o SENHOR teu Deus: portanto, eu te mando que faças isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Quando colheres tua plantação em teu campo, e esqueceres algum feixe no campo, não voltarás a tomá-lo: para o estrangeiro, para o órfão, e para a viúva será; para que te abençoe o SENHOR teu Deus em toda obra de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Quando sacudires tuas olivas, não recorrerás os ramos atrás de ti: para o estrangeiro, para o órfão, e para a viúva será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Quando vindimares tua vinha, não coletarás os restos de atrás de ti: para o estrangeiro, para o órfão, e para a viúva será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'E lembra-te que foste servo na terra do Egito: portanto, eu te mando que faças isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Quando houver pleito entre alguns, e vierem a juízo, e os julgarem, e absolverem ao justo e condenarem ao iníquo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Será que, se o delinquente merecer ser açoitado, então o juiz o fará lançar em terra, e o fará açoitar diante de si, segundo seu delito, por conta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Fará lhe dar quarenta açoites, não mais: não seja que, se o ferir com muitos açoites a mais destes, se humilhe teu irmão diante de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Não porás mordaça ao boi quando trilhar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Quando irmãos estiverem juntos, e morrer algum deles, e não tiver filho, a mulher do morto não se casará fora com homem estranho: seu cunhado entrará a ela, e a tomará por sua mulher, e fará com ela parentesco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'E será que o primogênito que der à luz ela, se levantará em nome de seu irmão o morto, para que o nome deste não seja apagado de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'E se o homem não quiser tomar a sua cunhada, irá então a cunhada sua à porta aos anciãos, e dirá: Meu cunhado não quer suscitar nome em Israel a seu irmão; não quer aparentar-se comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Então os anciãos daquela cidade o farão vir, e falarão com ele: e se ele se levantar, e disser, Não quero tomá-la,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Então se aproximará sua cunhada a ele diante dos anciãos, e o descalçará o sapato de seu pé, e lhe cuspirá no rosto, e falará e dirá: Assim será feito ao homem que não edificar a casa de seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'E seu nome será chamado em Israel: A casa do descalço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Quando alguns brigarem juntos um com o outro, e chegar a mulher de um para livrar a seu marido da mão do que lhe fere, e meter sua mão e lhe pegar por suas vergonhas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Tu a cortarás então a mão, não a perdoará teu olho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Não terás em tua bolsa peso grande e peso pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Não terás em tua casa efa grande e efa pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Pesos íntegros e justos terás; efa íntegro e justo terás: para que teus dias sejam prolongados sobre a terra que o SENHOR teu Deus te dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Porque abominação é ao SENHOR teu Deus qualquer um que faz isto, qualquer um que faz injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Lembra-te do que te fez Amaleque no caminho, quando saístes do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Que te saiu ao caminho, e te desbaratou a retaguarda de todos os fracos que iam detrás de ti, quando tu estavas cansado e exausto; e não temeu a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Será, pois, quando o SENHOR teu Deus te houver dado repouso de teus inimigos ao redor, na terra que o SENHOR teu Deus te dá por herdar para que a possuas, que apagarás a memória de Amaleque de debaixo do céu: não te esqueças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'E será que, quando houveres entrado na terra que o SENHOR teu Deus te dá por herança, e a possuíres, e habitares nela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Então tomarás das primícias de todos os frutos da terra, que tirares de tua terra que o SENHOR teu Deus te dá, e o porás em um cesto, e irás ao lugar que o SENHOR teu Deus escolher para fazer habitar ali seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'E chegarás ao sacerdote que for naqueles dias, e lhe dirás: Reconheço hoje ao SENHOR teu Deus que ei entrado na terra que jurou o SENHOR a nossos pais que nos havia de dar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'E o sacerdote tomará o cesto de tua mão, e o porá diante do altar do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Então falarás e dirás diante do SENHOR teu Deus: Um arameu a ponto de perecer foi meu pai, o qual desceu ao Egito e peregrinou ali com poucos homens, e ali cresceu em gente grande, forte e numerosa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'E os egípcios nos maltrataram, e nos afligiram, e puseram sobre nós dura servidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'E clamamos ao SENHOR Deus de nossos pais; e ouviu o SENHOR nossa voz, e viu nossa aflição, e nosso sofrimento, e nossa opressão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'E tirou-nos o SENHOR do Egito com mão forte, e com braço estendido, e com grande espanto, e com sinais e com milagres:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'E trouxe-nos a este lugar, e deu-nos esta terra, terra que flui leite e mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'E agora, eis que, trouxe as primícias do fruto da terra que me deste, ó SENHOR. E o deixarás diante do SENHOR teu Deus, e te inclinarás diante do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'E te alegrarás com todo o bem que o SENHOR teu Deus houver dado a ti e a tua casa, tu e o levita, e o estrangeiro que está em meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Quando houveres acabado de dizimar todo o dízimo de teus frutos no ano terceiro, o ano do dízimo, darás também ao levita, ao estrangeiro, ao órfão e à viúva; e comerão em tuas vilas, e se saciarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'E dirás diante do SENHOR teu Deus: Eu tirei o consagrado de minha casa, e também o dei ao levita, e ao estrangeiro, e ao órfão, e à viúva, conforme todos os teus mandamentos que me ordenaste: não transgredi teus mandamentos, nem me esqueci deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Não comi disso em meu luto, nem tirei disso em impureza, nem disso dei para o morto: obedeci à voz do SENHOR meu Deus, fiz conforme tudo o que me mandaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Olha desde a morada de tua santidade, desde o céu, e abençoa a teu povo Israel, e à terra que nos deste, como juraste a nossos pais, terra que flui leite e mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'O SENHOR teu Deus te manda hoje que cumpras estes estatutos e regulamentos; cuida, pois, de praticá-los com todo teu coração, e com toda tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Ao SENHOR exaltou hoje para que te seja por Deus, e para andar em seus caminhos, e para guardar seus estatutos e seus mandamentos e seus regulamentos, e para ouvir sua voz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'E o SENHOR te exaltou hoje para que lhe sejas seu privativo povo, como ele te disse, e para que guardes todos os seus mandamentos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'E para te pôr alto sobre todas as nações que fez, para louvor, e fama, e glória; e para que sejas povo santo ao SENHOR teu Deus, como ele disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'E mandou Moisés, com os anciãos de Israel, ao povo, dizendo: Guardareis todos os mandamentos que eu prescrevo hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'E será que, no dia que passardes o Jordão à terra que o SENHOR teu Deus te dá, te hás de levantar pedras grandes, as quais rebocarás com cal:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'E escreverás nelas todas as palavras desta lei, quando houveres passado para entrar na terra que o SENHOR teu Deus te dá, terra que flui leite e mel, como o SENHOR o Deus de teus pais te disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Será pois, quando houveres passado o Jordão, que levantareis estas pedras que eu vos mando hoje, no monte de Ebal, e as rebocarás com cal:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'E edificarás ali altar ao SENHOR teu Deus, altar de pedras: não levantarás sobre elas ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'De pedras inteiras edificarás o altar do SENHOR teu Deus; e oferecerás sobre ele holocausto ao SENHOR teu Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'E sacrificarás ofertas pacíficas, e comerás ali; e te alegrarás diante do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'E escreverás nas pedras todas as palavras desta lei muito claramente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'E Moisés, com os sacerdotes levitas, falou a todo Israel, dizendo: Atende e escuta, Israel: hoje és feito povo do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Ouvirás, pois, a voz do SENHOR teu Deus, e cumprirás seus mandamentos e seus estatutos, que eu te ordeno hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'E mandou Moisés ao povo naquele dia, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Estes estarão sobre o monte de Gerizim para abençoar ao povo, quando houverdes passado o Jordão: Simeão, e Levi, e Judá, e Issacar, e José e Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'E estes estarão para pronunciar a maldição no de Ebal: Rúben, Gade, e Aser, e Zebulom, Dã, e Naftali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'E falarão os levitas, e dirão a todo homem de Israel em alta voz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Maldito o homem que fizer escultura ou imagem de fundição, abominação ao SENHOR, obra da mão de artífice, e a puser em oculto. E todo o povo responderá e dirá: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Maldito o que desonrar a seu pai ou a sua mãe. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Maldito o que reduzir o termo de seu próximo. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Maldito o que fizer errar ao cego no caminho. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Maldito o que distorcer o direito do estrangeiro, do órfão, e da viúva. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Maldito o que se deitar com a mulher de seu pai; porquanto revelou o colo de seu pai. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Maldito o que tiver parte com qualquer animal. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Maldito o que se deitar com sua irmã, filha de seu pai, ou filha de sua mãe. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Maldito o que se deitar com sua sogra. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Maldito o que ferir a seu próximo ocultamente. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Maldito o que receber presente para ferir de morte ao inocente. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Maldito o que não confirmar as palavras desta lei para as cumprir. E dirá todo o povo: Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'E será que, se ouvires com empenho a voz do SENHOR teu Deus, para guardar, para praticar todos os seus mandamentos que eu te prescrevo hoje, também o SENHOR teu Deus te porá alto sobre todas as nações da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'E virão sobre ti todas estas bênçãos, e te alcançarão, quando ouvires a voz do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Bendito serás tu na cidade, e bendito tu no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Bendito o fruto de teu ventre, e o fruto de teu animal, a cria de tuas vacas, e os rebanhos de tuas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Bendito teu cesto e tua amassadeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Bendito serás em teu entrar, e bendito em teu sair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Causará o SENHOR a teus inimigos que se levantarem contra ti, que sejam derrotados diante de ti: por um caminho sairão a ti, por sete caminhos fugirão diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Enviará o SENHOR contigo a bênção em teus granários, e em tudo aquilo em que puseres tua mão; e te abençoará na terra que o SENHOR teu Deus te dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'O SENHOR te confirmará por povo seu santo, como te jurou, quando guardares os mandamentos do SENHOR teu Deus, e andares em seus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'E verão todos os povos da terra que o nome do SENHOR é chamado sobre ti, e te temerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'E te fará o SENHOR superabundar em bens, no fruto de teu ventre, e no fruto de teu animal, e no fruto de tua terra, no país que jurou o SENHOR a teus pais que te havia de dar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'O SENHRO te abrirá seu bom depósito, o céu, para dar chuva à tua terra em seu tempo, e para abençoar toda obra de tuas mãos. E emprestarás a muitas nações, e tu não tomarás emprestado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'E te porá o SENHOR por cabeça, e não por cauda: e estarás encima somente, e não estarás debaixo; quando obedeceres aos mandamentos do SENHOR teu Deus, que eu te ordeno hoje, para que os guardes e cumpras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'E não te desvies de todas as palavras que eu vos mando hoje, nem à direita nem à esquerda, para ir atrás de deuses alheios para servir-lhes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'E será, se não ouvires a voz do SENHOR teu Deus, para cuidar de praticar todos os seus mandamentos e seus estatutos, que eu te intimo hoje, que virão sobre ti todas estas maldições, e te alcançarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Maldito serás tu na cidade, e maldito no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Maldito teu cesto, e tua amassadeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Maldito o fruto de teu ventre, e o fruto de tua terra, e a cria de tuas vacas, e os rebanhos de tuas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Maldito serás em teu entrar, e maldito em teu sair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'E o SENHOR enviará contra ti a maldição, confusão e oposição em tudo quanto puseres mão e fizeres, até que sejas destruído, e pereças logo por causa da maldade de tuas obras, pelas quais me houverdes deixado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'O SENHOR fará que se te pegue mortandade, até que te consuma da terra à qual entras para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'O SENHOR te ferirá de tísica, e de febre, e de ardor, e de calor, e de espada, e de calamidade repentina, e com mofo; e te perseguirão até que pereças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'E teus céus que estão sobre tua cabeça, serão de bronze; e a terra que está debaixo de ti, de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Dará o SENHOR por chuva à tua terra pó e cinza: dos céus descerão sobre ti até que pereças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'O SENHOR te entregará ferido diante de teus inimigos: por um caminho sairás a eles, e por sete caminhos fugirás diante deles: e serás sacudido a todos os reinos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'E será teu corpo morto por comida a toda ave do céu, e animal da terra, e não haverá quem as espante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'O SENHOR te ferirá da praga do Egito, e com tumores, e com sarna, e com coceira, de que não possas ser curado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'O SENHOR te ferirá com loucura, e com cegueira, e com confusão de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'E apalparás ao meio-dia, como apalpa o cego na escuridão, e não serás próspero em teus caminhos: e nunca serás a não ser somente oprimido e roubado todos os dias, e não haverá quem te salve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Tu te casarás com mulher, e outro homem dormirá com ela; edificarás casa, e não habitarás nela; plantarás vinha, e não a vindimarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Teu boi será matado diante de teus olhos, e tu não comerás dele; teu asno será arrebatado de diante de ti, e não se te voltará; tuas ovelhas serão dadas a teus inimigos, e não terás quem te as resgate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Teus filhos e tuas filhas serão entregues a outro povo, e teus olhos o verão, e desfalecerão por eles todo o dia: e não haverá força em tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'O fruto de tua terra e todo teu trabalho comerá povo que não conheceste; e nunca serás a não ser somente oprimido e quebrantado todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'E enlouquecerás por causa do que verás com teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'O SENHOR te ferirá com maligna úlcera nos joelhos e nas pernas, sem que possas ser curado: ainda desde a planta de teu pé até o topo de tua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'O SENHOR levará a ti, e a teu rei que houveres posto sobre ti, a nação que não conheceste tu nem teus pais; e ali servirás a deuses alheios, à madeira e à pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'E serás por confusão, por exemplo e por fábula, a todos os povos aos quais te levará o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Tirarás muito semente ao campo, e colherás pouco; porque os gafanhotos o consumirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Plantarás vinhas e lavrarás, mas não beberás vinho, nem colherás uvas; porque o bicho as comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Terás olivas em todo teu termo, mas não te ungirás com o azeite; porque tua azeitona cairá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Filhos e filhas gerarás, e não serão para ti; porque irão em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Todo o teu arvoredo e o fruto de tua terra os gafanhotos consumirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'O estrangeiro que estará em meio de ti subirá sobre ti muito alto, e tu serás posto muito abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Ele emprestará a ti, e tu não emprestarás a ele: ele será por cabeça, e tu serás por cauda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'E virão sobre ti todas estas maldições, e te perseguirão, e te alcançarão até que pereças; porquanto não houverdes atendido à voz do SENHOR teu Deus, para guardar seus mandamentos e seus estatutos, que ele te mandou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'E serão em ti por sinal e por maravilha, e em tua descendência para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Porquanto não serviste ao SENHOR teu Deus com alegria e com alegria de coração, pela abundância de todas as coisas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Servirás, portanto, a teus inimigos que enviar o SENHOR contra ti, com fome e com sede e com nudez, e com falta de todas as coisas; e ele porá jugo de ferro sobre teu pescoço, até destruir-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'O SENHOR trará sobre ti nação de longe, do extremo da terra, que voe como água, nação cuja língua não entendas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Nação feroz de rosto, que não terá respeito ao ancião, nem perdoará à criança:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'E comerá o fruto de teu animal e o fruto de tua terra, até que pereças: e não te deixará grão, nem mosto, nem azeite, nem a cria de tuas vacas, nem os rebanhos de tuas ovelhas, até destruir-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'E te porá cerco em todas as tuas cidades, até que caiam teus muros altos e fortificados em que tu confias, em toda tua terra: te cercará, pois, em todas tuas cidades e em toda tua terra, que o SENHOR teu Deus te houver dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'E comerás o fruto de teu ventre, a carne de teus filhos e de tuas filhas que o SENHOR teu Deus te deu, no cerco e nos apuros com que te angustiará teu inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'O homem tenro em ti, e o muito delicado, seu olho será maligno para com seu irmão, e para com a mulher de seu seio, e para com o resto de seus filhos que lhe restarem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Para não dar a algum deles da carne de seus filhos, que ele comerá, porque nada lhe haverá restado, no cerco e nos apuros com que teu inimigo te oprimirá em todas tuas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'A tenra e a delicada entre vós, que nunca a planta de seu pé provou a sentar sobre a terra, de ternura e delicadeza, seu olho será maligno para com o marido de seu seio, e para com seu filho, e para com sua filha,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'E para com sua criança que sai dentre seus pés, e para com seus filhos que der à luz; pois os comerá ocultamente, a falta de tudo, no cerco e em apuros com que teu inimigo te oprimirá em tuas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Se não cuidares de praticar todas as palavras desta lei que estão escritas neste livro, temendo este nome glorioso e terrível, O SENHOR TEU DEUS,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'O SENHOR aumentará maravilhosamente tuas pragas e as pragas de tua descendência, pragas grandes e duradouras, e enfermidades malignas e duradouras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'E fará voltar sobre ti todos os males do Egito, diante dos quais temeste, e se te pegarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Assim como toda enfermidade e toda praga que não está escrita no livro desta lei, o SENHOR a enviará sobre ti, até que tu sejas destruído.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'E restareis em pouca gente, em lugar de haver sido como as estrelas do céu em multidão; porquanto não obedeceste à voz do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'E será que como o SENHOR se alegrou sobre vós para fazer-vos bem, e para multiplicar-vos, assim se alegrará o SENHOR sobre vós para vos arruinar, e para destruir-vos; e sereis tirados de sobre a terra, à qual entrais para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'E o SENHOR te espalhará por todos os povos, desde um extremo da terra até o outro extremo dela; e ali servirás a deuses alheios que não conheceste tu nem teus pais, à madeira e à pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'E nem ainda entre as mesmas nações descansarás, nem a planta de teu pé terá repouso; que ali te dará o SENHOR coração temeroso, e caimento de olhos, e tristeza de alma:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'E terás tua vida como suspensa diante de ti, e estarás temeroso de noite e de dia, e não confiarás de tua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Pela manhã dirás: Quem dera fosse a tarde! E à tarde dirás: Quem dera fosse a manhã! pelo medo de teu coração com que estarás amedrontado, e pelo que verão teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'E o SENHOR te fará voltar ao Egito em navios pelo caminho do qual te disse: Nunca mais voltareis: e ali sereis vendidos a vossos inimigos por escravos e por escravas, e não haverá quem vos compre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Estas são as palavras do pacto que o SENHOR mandou que Moisés fizesse com os filhos de Israel na terra de Moabe, além do pacto que estabeleceu com eles em Horebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Moisés, pois, chamou a todo Israel, e disse-lhes: Vós vistes tudo o que o SENHOR fez diante vossos olhos na terra do Egito a Faraó e a todos os seus servos, e a toda sua terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'As provas grandes que viram teus olhos, o sinais, e as grandes maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'E o SENHOR não vos deu coração para entender, nem olhos para ver, nem ouvidos para ouvir, até o dia de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'E eu vos trouxe quarenta anos pelo deserto: vossas roupas não se hão envelhecido sobre vós, nem teu sapato se envelheceu sobre teu pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Não comestes pão, nem bebestes vinho nem bebida forte: para que soubestes que eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'E chegastes a este lugar, e saiu Seom rei de Hesbom, e Ogue rei de Basã, diante de nós para lutar, e os ferimos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'E tomamos sua terra, e a demos por herança a Rúben e a Gade, e à meia tribo de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Guardareis, pois, as palavras deste pacto, e as poreis por obra, para que prospereis em tudo o que fizerdes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vós todos estais hoje diante do SENHOR vosso Deus; vossos príncipes de vossas tribos, vossos anciãos, e vossos oficiais, todos os homens de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Vossas crianças, vossas mulheres, e teus estrangeiros que habitam em meio de teu campo, desde o que corta tua lenha até o que tira tuas águas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Para que entres no pacto do SENHOR teu Deus, e em seu juramento, que o SENHOR teu Deus estabelece hoje contigo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Para te confirmar hoje por seu povo, e que ele seja a ti por Deus, da maneira que ele te disse, e como ele jurou a teus pais Abraão, Isaque, e Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'E não somente convosco estabeleço eu este pacto e este juramento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Mas sim com os que estão aqui presentes hoje conosco diante do SENHOR nosso Deus, e com os que não estão aqui hoje conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Porque vós sabeis como habitamos na terra do Egito, e como passamos por meio das nações que passastes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'E vistes suas abominações e seus ídolos, madeira e pedra, prata e ouro, que têm consigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Para que não haja entre vós homem, ou mulher, ou família, ou tribo, cujo coração se volte hoje de com o SENHOR nosso Deus, por andar a servir aos deuses daquelas nações; que não haja em vós raiz que lance veneno e amargura;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'E seja que, quando o tal ouvir as palavras desta maldição, ele se abençoe em seu coração, dizendo: Terei paz, ainda que ande segundo o pensamento de meu coração, para acrescentar a embriaguez à sede:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'O SENHOR se recusará a lhe perdoar; antes fumegará logo o furor do SENHOR e seu zelo sobre o tal homem, e se assentará sobre ele toda maldição escrita neste livro, e o SENHOR apagará seu nome de debaixo do céu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'E o SENHOR o separará de todas as tribos de Israel para o mal, conforme todas as maldições do pacto escrito neste livro da lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'E dirá a geração vindoura, vossos filhos que virão depois de vós, e o estrangeiro que virá de distantes terras, quando virem as pragas desta terra, e suas enfermidades de que o SENHOR a fez enfermar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, '(Enxofre e sal, abrasada toda sua terra: não será semeada, nem produzirá, nem crescerá nela erva nenhuma, como na destruição de Sodoma e de Gomorra, de Admá e de Zeboim, que o SENHOR destruiu em seu furor e em sua ira:)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Dirão, pois, todas as nações: Por que fez o SENHOR isto a esta terra? Que ira é esta de tão grande furor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'E responderão. Porquanto deixaram o pacto do SENHOR o Deus de seus pais, que ele estabeleceu com eles quando os tirou da terra do Egito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'E foram e serviram a deuses alheios, e inclinaram-se a eles, deuses que não conheciam, e que nenhuma coisa lhes haviam dado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Acendeu-se portanto, o furor do SENHOR contra esta terra, para trazer sobre ela todas as maldições escritas nesta livro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'E o SENHOR os desarraigou de sua terra com ira, e com indignação, e com furor grande, e os expulsou a outra terra, como hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'As coisas secretas pertencem ao SENHOR nosso Deus: mas as reveladas são para nós e para nossos filhos para sempre, para que cumpramos todas as palavras desta lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'E será que, quando te sobrevierem todas estas coisas, a bênção e a maldição que pus diante de ti, e te conscientizares em teu coração em meio de todas as nações às quais o SENHOR teu Deus te houver expulsado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'E te converteres ao SENHOR teu Deus, e obedeceres à sua voz conforme tudo o que eu te mando hoje, tu e teus filhos, com todo teu coração e com toda tua alma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'O SENHOR te restaurará de teu infortúnio, terá misericórdia de ti, e voltará a recolher-te de todos os povos aos quais o SENHOR, teu Deus, te houver disperso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Se houveres sido lançado até a extremidade dos céus, dali te recolherá o SENHOR teu Deus, e dali te tomará:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'E te fará voltar o SENHOR teu Deus à terra que herdaram teus pais, e a possuirás; e te fará bem, e te multiplicará mais que a teus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'E circuncidará o SENHOR teu Deus teu coração, e o coração de tua descendência, para que ames ao SENHOR teu Deus com todo teu coração e com toda tua alma, a fim de que tu vivas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'E porá o SENHOR teu Deus todas estas maldições sobre teus inimigos, e sobre teus aborrecedores que te perseguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'E tu voltarás, e ouvirás a voz do SENHOR, e porás por obra todos os seus mandamentos, que eu te intimo hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'E te fará o SENHOR teu Deus abundar em toda obra de tuas mãos, no fruto de teu ventre, no fruto de teu animal, e no fruto de tua terra, para o bem: porque o SENHOR voltará a se alegrar sobre ti para o bem, da maneira que se alegrou sobre teus pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Quando ouvires a voz do SENHOR teu Deus, para guardar seus mandamentos e seus estatutos escritos neste livro da lei; quando te converteres ao SENHOR teu Deus com todo teu coração e com toda tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Porque este mandamento que eu te intimo hoje, não te é encoberto, nem está longe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Não está no céu, para que digas: Quem subirá por nós ao céu, e nos o trará e o apresentará para nós, para que o cumpramos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Nem está da outra parte do mar, para que digas: Quem passará por nós o mar, para que o traga até nós e a nós o apresente, a fim de que o cumpramos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Porque muito próxima de ti está a palavra, em tua boca e em teu coração, para que a cumpras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Olha, eu pus diante de ti hoje a vida e o bem, a morte e o mal:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Porque eu te mando hoje que ames ao SENHOR teu Deus, que andes em seus caminhos, e guardes seus mandamentos e seus estatutos e seus regulamentos, para que vivas e sejas multiplicado, e o SENHOR teu Deus te abençoe na terra à qual entras para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mas se teu coração se desviar, e não ouvires, e fores incitado, e te inclinares a deuses alheios, e os servires;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Declaro-vos hoje que certamente perecereis: não tereis longos dias sobre a terra, para ir à qual passas o Jordão para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Aos céus e a terra chamo por testemunhas hoje contra vós, que pus diante de vós a vida e a morte, a bênção e a maldição: escolhe, pois, a vida, para que vivas tu e tua descendência:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Que ames ao SENHOR teu Deus, que ouças sua voz, e te achegues a ele; porque ele é tua vida, e o comprimento de teus dias; a fim de que habites sobre a terra que jurou o SENHOR a teus pais Abraão, Isaque, e Jacó, que lhes havia de dar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'E foi Moisés, e falou estas palavras a todo Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'E disse-lhes: De idade de cento e vinte anos sou hoje dia; não posso mais sair nem entrar: a mais disto o SENHOR me disse: Não passarás este Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'O SENHOR teu Deus, ele passa diante de ti; ele destruirá estas nações de diante de ti, e as herdarás: Josué será o que passará diante de ti, como o SENHOR disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'E fará o SENHOR com eles como fez com Seom e com Ogue, reis dos amorreus, e com sua terra, que os destruiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'E os entregará o SENHOR diante de vós, e fareis com eles conforme tudo o que vos mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Esforçai-vos e tende ânimo; não temais, nem tenhais medo deles: que o SENHOR teu Deus é o que vai contigo: não te deixará nem te desamparará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'E chamou Moisés a Josué, e disse-lhe à vista de todo Israel: Esforça-te e anima-te; porque tu entrarás com este povo à terra que jurou o SENHOR a seus pais que lhes havia de dar, e tu a farás herdar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'E o SENHOR é o que vai diante de ti; ele será contigo, não te deixará, nem te desamparará; não temas, nem te intimides.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'E escreveu Moisés esta lei, e deu-a aos sacerdotes, filhos de Levi, que levavam a arca do pacto do SENHOR, e a todos os anciãos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'E mandou-lhes Moisés, dizendo: Ao fim do sétimo ano, no ano da remissão, na festa das cabanas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Quando vier todo Israel a apresentar-se diante do SENHOR teu Deus no lugar que ele escolher, lerás esta lei diante de todo Israel aos ouvidos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Farás congregar o povo, homens e mulheres e crianças, e teus estrangeiros que estiverem em tuas cidades, para que ouçam e aprendam, e temam ao SENHOR vosso Deus, e cuidem de praticar todas as palavras desta lei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'E os filhos deles que não souberem ouçam, e aprendam a temer ao SENHOR vosso Deus todos os dias que viverdes sobre a terra, para ir à qual passais o Jordão para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'E o SENHOR disse a Moisés: Eis que se aproximam teus dias para que morras: chama a Josué, e esperai no tabernáculo do testemunho, e lhe mandarei. Foram pois Moisés e Josué, e esperaram no tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'E apareceu-se o SENHOR no tabernáculo, na coluna de nuvem; e a coluna de nuvem se pôs sobre a porta do tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'E o SENHOR disse a Moisés: Eis que tu vais descansar com teus pais, e este povo se levantará e se prostituirá atrás dos deuses alheios da terra aonde vai, em estando em meio dela; e me deixará, e invalidará meu pacto que estabeleci com ele:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'E meu furor se acenderá contra ele naquele dia; e os abandonarei, e esconderei deles meu rosto, e serão consumidos; e o acharão muitos males e angústias, e dirá naquele dia: Não me acharam estes males porque não está meu Deus em meio de mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Porém eu esconderei certamente meu rosto naquele dia, por todo o mal que eles houverem feito, por haver-se voltado a deuses alheios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Agora, pois, escrevei-vos este cântico, e ensina-o aos filhos de Israel: põe-o em boca deles, para que este cântico me seja por testemunha contra os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Porque eu lhe introduzirei na terra que jurei a seus pais, a qual flui leite e mel; e comerá, e se fartará, e se engordará: e se voltarão a deuses alheios, e lhes servirão, e me provocarão à ira, e invalidarão meu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'E será que quando lhe vierem muitos males e angústias, então responderá em sua face este cântico como testemunha, pois não cairá em esquecimento da boca de sua linhagem: porque eu conheço seu intento, e o que faz hoje antes que lhe introduza na terra que jurei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'E Moisés escreveu este cântico aquele dia, e ensinou-o aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'E deu ordem a Josué filho de Num, e disse: Esforça-te e anima-te, que tu porás os filhos de Israel na terra que lhes jurei, e eu serei contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'E quando acabou Moisés de escrever as palavras desta lei em um livro até concluir,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Mandou Moisés aos levitas que levavam a arca do pacto do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Tomai este livro da lei, e ponde-o ao lado da arca do pacto do SENHOR vosso Deus, e esteja ali por testemunha contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Porque eu conheço tua rebelião, e tua dura cerviz: eis que ainda vivendo eu hoje convosco, sois rebeldes ao SENHOR; e quanto mais depois que eu morrer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Congregai a mim todos os anciãos de vossas tribos, e a vossos oficiais, e falarei em seus ouvidos estas palavras, e chamarei por testemunhas contra eles os céus e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Porque eu sei que depois de minha morte, certamente vos corrompereis e vos desviareis do caminho que vos mandei; e que vos há de vir mal nos últimos dias, por haver feito mal aos olhos do SENHOR, provocando-lhe à ira com a obra de vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Então falou Moisés aos ouvidos de toda a congregação de Israel as palavras deste cântico até acabá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Escutai, céus, e falarei; E ouça a terra os ditos de minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Gotejará como a chuva minha doutrina; Destilará como o orvalho meu discurso; Como o chuvisco sobre a grama, E como as gotas sobre a erva:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Porque invocarei o nome do SENHOR; Engrandecei ao nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Ele é a Rocha, sua obra é perfeita, pois todos os seus caminhos são justos. Deus fiel, e sem imoralidade; justo e correto ele é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Corromperam-se contra ele; não são seus filhos, a falha é deles./fn/keyCorromperam-se... é deles/*keyobscuro/*fn São uma geração perversa e distorcida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'É assim que pagais ao SENHOR, ó povo tolo e insensato? Não é ele teu pai que te adquiriu, te fez, e te estabeleceu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Lembra-te dos tempos antigos; Considerai os anos de geração e geração: Pergunta a teu pai, que ele te declarará; A teus anciãos, e eles te dirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Quando o Altíssimo fez herdar às nações, Quando fez dividir os filhos dos homens, Estabeleceu os termos dos povos Segundo o número dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Porque a parte do SENHOR é seu povo; Jacó a medida de sua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Achou-o em terra de deserto, E em deserto horrível e ermo; Cercou-o, instruiu-o, Guardou-o como a menina de seu olho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Como a água desperta sua ninhada, paira sobre seus passarinhos, Estende suas asas, os toma, os leva sobre suas penas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'O SENHOR sozinho o guiou, e nenhum deus estrangeiro esteve com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Ele o fez cavalgar sobre as alturas da terra; comeu os frutos do campo, e o fez que chupar mel da rocha, e azeite da dura pederneira;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Manteiga de vacas e leite de ovelhas, Com gordura de cordeiros, E carneiros de Basã; também machos de bode, Com o melhor do trigo: E sangue de uva bebeste, vinho puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'E engordou Jesurum, e deu coices: Engordaste-te, engrossaste-te, cobriste-te: E deixou ao Deus que lhe fez, E menosprezou a Rocha de sua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Provocaram-lhe ciúmes com os deuses alheios; irritaram-lhe com abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Sacrificaram aos demônios, não a Deus; a deuses que não conheciam, a novos deuses vindos de perto, Que não haviam temido vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Abandonaste a Rocha que te gerou; e te esqueceste do Deus que te criou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'E o SENHOR o viu, e acendeu-se em ira, pelo menosprezo de seus filhos e de suas filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'E disse: esconderei deles meu rosto, verei qual será seu fim; pois são geração de perversidades, filhos sem fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Eles me provocaram ciúmes com o que não é Deus; com suas vaidades provocaram-me à ira; eu também provocarei os ciúmes com aqueles que não são povo, e com uma nação insensata eu os provocarei à ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Porque um fogo se acendeu em meu furor, e arderá até as profundezas do mundo dos mortos; e consumirá a terra e seus frutos, e abrasará os fundamentos dos montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Eu trarei males sobre eles; Gastarei neles minhas flechas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Consumidos serão de fome, e comidos de febre ardente E de amarga pestilência; Dente de animais enviarei também sobre eles, Com veneno de serpente da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'De fora desolará a espada, E dentro das câmaras o espanto: Tanto ao rapaz como à virgem, Ao que mama como o homem grisalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Disse: Eu os dispersaria do mundo, Faria cessar dentre os homens a memória deles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Se não temesse a ira do inimigo, Não seja que se envaideçam seus adversários, Não seja que digam: Nossa mão alta fez tudo isto, não o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Porque são gente de perdidos conselhos, E não há neles entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Bom seria se fossem sábios, que compreendessem isto, E entendessem seu fim!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Como poderia perseguir um a mil, E dois fariam fugir a dez mil, Se sua Rocha não os houvesse vendido, E o SENHOR não os houvesse entregue?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Que a rocha deles não é como nossa Rocha: E nossos inimigos sejam disso juízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Porque da vide de Sodoma é a vide deles, E dos sarmentos de Gomorra: As uvas deles são uvas venenosas, cachos muito amargos têm.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Veneno de serpentes é seu vinho, e peçonha cruel de áspides.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Não tenho eu isto guardado, Selado em meus tesouros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Minha é a vingança e o pagamento, Ao tempo que seu pé vacilará; Porque o dia de sua aflição está próximo, E o que lhes está preparado se apressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Porque o SENHOR julgará a seu povo, E por causa de seus servos se arrependerá, Quando vir que a força pereceu, E que não há prisioneiro nem livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'E dirá: Onde estão seus deuses, A rocha em que se refugiavam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Que comiam a gordura de seus sacrifícios, Bebiam o veio de suas libações? Levante-se, que vos ajudem E vos defendam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Vede agora que Eu, Eu Sou, e não há deus além de mim; eu trago a morte, e eu faço viver; eu firo, e eu curo; e não há quem possa escapar da minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Quando eu erguer aos céus minha mão, e disser: “Tão certo como eu vivo para sempre”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Se eu afiar minha espada reluzente, e minha mão agarrar o juízo, devolverei a vingança sobre os meus adversários, e retribuirei aos que me odeiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Embriagarei de sangue minhas flechas, e minha espada devorará carne, no sangue dos mortos e dos cativos, das cabeças dos líderes inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Jubilai, ó nações, com o povo dele, porque ele vingará o sangue dos seus servos, e devolverá a vingança sobre os seus inimigos, e expiará sua terra, pelo seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'E Moisés veio, e recitou todas as palavras deste cântico aos ouvidos do povo, ele, e Josué filho de Num.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'E acabou Moisés de recitar todas estas palavras a todo Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'E disse-lhes: Ponde vosso coração a todas as palavras que eu vos declaro hoje, para que as mandeis a vossos filhos, e cuidem de praticar todas as palavras desta lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Porque não vos é coisa vã, mas é vossa vida: e por elas fareis prolongar os dias sobre a terra, para possuir a qual passais o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'E falou o SENHOR a Moisés aquele mesmo dia, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Sobe a este monte de Abarim, ao monte Nebo, que está na terra de Moabe, que está em frente de Jericó, e olha a terra de Canaã, que eu dou por herança aos filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'E morre no monte ao qual sobes, e sê reunido a teus povos; ao modo que morreu Arão teu irmão no monte de Hor, e foi reunido a seus povos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Porquanto transgredistes contra mim em meio dos filhos de Israel nas águas da briga de Cades, no deserto de Zim; porque não me santificastes em meio dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Verás, portanto, diante de ti a terra; mas não entrarás ali, à terra que dou aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'E esta é a bênção com a qual abençoou Moisés homem de Deus aos filhos de Israel, antes que morresse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'E disse: O SENHOR veio de Sinai, E de Seir lhes iluminou; Resplandeceu do monte de Parã, E veio com dez mil santos: À sua direita a lei de fogo para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Ainda amou os povos; Todos seus santos em tua mão: Eles também se chegaram a teus pés: Receberam de teus ditos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Lei nos mandou Moisés, Herança à congregação de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'E foi rei em Jesurum, Quando se congregaram os chefes do povo Com as tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Viva Rúben, e não morra; E sejam seus homens em número.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'E esta bênção para Judá. Disse assim: Ouve, ó SENHOR, a voz de Judá, E leva-o a seu povo; suas mãos lhe bastem, E tu sejas ajuda contra seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'E a Levi disse: Teu Tumim e teu Urim, com teu bom homem Ao qual tentaste em Massá, E lhe fizeste brigar nas águas da briga;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'O que disse a seu pai e a sua mãe: Nunca os vi: nem conheceu a seus irmãos, nem conheceu a seus filhos: Pelo qual eles guardarão tuas palavras, E observarão teu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Eles ensinarão teus juízos a Jacó, E tua lei a Israel; Porão o incenso diante de ti, E o holocausto sobre teu altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Abençoa, ó SENHOR, o que fizerem, E recebe com agrado a obra de suas mãos: Fere os lombos de seus inimigos, E dos que lhe odiarem; para que nunca se levantem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'E a Benjamim disse: O amado do SENHOR habitará confiante próximo dele: Ele o cobrirá sempre, E entre seus ombros morará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'E a José disse: Bendita do SENHOR sua terra, Pelas dádivas dos céus, pelo orvalho, E pelo abismo que abaixo jaz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'E pelos excelentes frutos do sol, E pelos excelentes produtos das influências das luas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'E pelo cume dos montes antigos, E pelos excelentes produtos das colinas eternas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'E pelos excelentes produtos da terra e sua plenitude; E a graça do que habitou na sarça Venha sobre a cabeça de José, E sobre ao topo da cabeça do separado de seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Ele é preeminente como o primogênito de seu touro, E suas pontas, chifres de boi selvagem: Com eles chifrará os povos juntos até os confins da terra: E estes são as dezenas de milhares milhares de Efraim, E estes os milhares de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'E a Zebulom disse: Alegra-te, Zebulom, quando saíres: E tu Issacar, em tuas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Chamarão os povos ao monte: Ali sacrificarão sacrifícios de justiça: Pelo qual chuparão a abundância dos mares, E os tesouros escondidos da areia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'E a Gade disse: Bendito o que fez alargar a Gade: Como leão habitará, E arrebatará braço e testa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'E ele se proveu da parte primeira, Porque ali uma porção do legislador foi-lhe reservada, E veio na dianteira do povo; A justiça do SENHOR executará, E seus juízos com Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'E a Dã disse: Dã, leão jovem: Saltará desde Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'E a Naftali disse: Naftali, saciado de benevolência, E cheio da bênção do SENHOR, Possui o ocidente e o sul,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'E a Aser disse: Bendito Aser em filhos: Agradável será a seus irmãos, E molhará em azeite seu pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Ferro e bronze teu calçado, E como teus dias tua força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Não há como o Deus de Jesurum, Montado sobre os céus para tua ajuda, E sobre as nuvens com sua grandeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'O eterno Deus é teu refúgio E aqui abaixo os braços eternos; Ele expulsará de diante de ti ao inimigo, E dirá: Destrói.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'E Israel, fonte de Jacó, habitará confiante sozinho Em terra de grão e de vinho: Também seus céus destilarão orvalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Bem-aventurado tu, ó Israel, Quem como tu, Povo salvo pelo SENHOR, Escudo de teu socorro, E espada de tua excelência? Assim teus inimigos serão humilhados, E tu pisarás sobre suas alturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'E subiu Moisés dos campos de Moabe ao monte de Nebo, ao cume de Pisga, que está em frente de Jericó: e mostrou-lhe o SENHOR toda a terra de Gileade até Dã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'E a todo Naftali, e a terra de Efraim e de Manassés, toda a terra de Judá até o mar mais distante;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'E a parte sul, e a campina, o vale de Jericó, cidade das palmeiras, até Zoar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'E disse-lhe o SENHOR: Esta é a terra de que jurei a Abraão, a Isaque, e a Jacó, dizendo: À tua descendência a darei. Eu a fiz ver com teus olhos, mas não passarás ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'E morreu ali Moisés servo do SENHOR, na terra de Moabe, conforme o dito do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'E enterrou-o no vale, em terra de Moabe, em frente de Bete-Peor; e ninguém sabe seu sepulcro até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'E era Moisés de idade de cento e vinte anos quando morreu: seus olhos nunca se escureceram, nem perdeu o seu vigor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'E choraram os filhos de Israel a Moisés nos campos de Moabe trinta dias: E assim se cumpriram os dias do choro do luto de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'E Josué filho de Num foi cheio de espírito de sabedoria, porque Moisés havia posto suas mãos sobre ele: e os filhos de Israel lhe obedeceram, e fizeram como o SENHOR mandou a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'E nunca mais se levantou profeta em Israel como Moisés, a quem haja conhecido o SENHOR face a face;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Em todos os sinais e prodígios que lhe enviou o SENHOR a fazer em terra do Egito a Faraó, e a todos os seus servos, e a toda sua terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'E em toda aquela mão poderosa, e em todo o grande espanto que Moisés causou à vista de todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'E aconteceu depois da morte de Moisés servo do SENHOR, que o SENHOR falou a Josué filho de Num, assistente de Moisés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Meu servo Moisés é morto: levanta-te, pois, agora, e passa este Jordão, tu e todo este povo, à terra que eu lhes dou aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Eu vos entreguei, como o disse a Moisés, todo lugar que pisar a planta de vosso pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Desde o deserto e este Líbano até o grande rio Eufrates, toda a terra dos heteus até o grande mar do ocidente, será vosso termo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Ninguém poderá resistir a ti em todos os dias de tua vida: como eu fui com Moisés, serei contigo; não te deixarei, nem te desampararei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Esforça-te e sê valente: porque tu repartirás a este povo por herança a terra, da qual jurei a seus pais que a daria a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Somente te esforces, e sejas muito valente, para cuidar de fazer conforme toda a lei que meu servo Moisés te mandou: não te apartes dela nem à direita nem à esquerda, para que sejas próspero em todas as coisas que empreenderes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'O livro desta lei nunca se apartará de tua boca: antes de dia e de noite meditarás nele, para que guardes e faças conforme tudo o que nele está escrito: porque então farás prosperar teu caminho, e tudo te sairá bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Olha que te mando que te esforces e sejas valente: não temas nem desmaies, porque o SENHOR teu Deus será contigo onde quer que fores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'E Josué mandou aos oficiais do povo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Passai por meio do acampamento, e mandai ao povo, dizendo: Abastecei-vos de comida; porque dentro de três dias passareis o Jordão, para que entreis a possuir a terra que o SENHOR vosso Deus vos dá para que a possuais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Também falou Josué aos rubenitas e gaditas, e à meia tribo de Manassés, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Lembrai-vos da palavra que Moisés, servo do SENHOR, vos mandou dizendo: o SENHOR vosso Deus vos deu repouso, e vos deu esta terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vossas mulheres e vossos meninos e vossas animais, ficarão na terra que Moisés vos deu desta parte do Jordão; mas vós, todos os valentes e fortes, passareis armados diante de vossos irmãos, e lhes ajudareis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Até tanto que o SENHOR tenha dado repouso a vossos irmãos como a vós, e que eles também possuam a terra que o SENHOR vosso Deus lhes dá: e depois voltareis vós à terra de vossa herança, a qual Moisés servo do SENHOR vos deu, desta parte do Jordão até o oriente; e a possuireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Então responderam a Josué, dizendo: Nós faremos todas as coisas que nos mandaste, e iremos aonde quer que nos mandares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Da maneira que obedecemos a Moisés em todas as coisas, assim obedeceremos a ti: somente o SENHOR teu Deus seja contigo, como foi com Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Qualquer um que for rebelde ao teu mandamento, e não obedecer às tuas palavras em todas as coisas que lhe mandares, que morra; somente que te esforces, e sejas valente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'E Josué, filho de Num, enviou desde Sitim dois espias secretamente, dizendo-lhes: Andai, reconhecei a terra, e a Jericó. Os quais foram, e entraram em casa de uma mulher prostituta que se chamava Raabe, e passaram a noite ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'E foi dado aviso ao rei de Jericó, dizendo: Eis que homens dos filhos de Israel vieram aqui esta noite a espiar a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Então o rei de Jericó, enviou a dizer a Raabe: Tira fora os homens que vieram a ti, e entraram em tua casa; porque vieram a espiar toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Mas a mulher havia tomado os dois homens, e os havia escondido; e disse: Verdade que homens vieram a mim, mas não soube de onde eram:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'E ao fechar-se a porta, sendo já escuro, esses homens saíram, e não sei para onde se foram: segui-os depressa, que os alcançareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Mas ela os havia feito subir ao terraço, e havia os escondido entre talos de linho que naquele terraço tinha posto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'E os homens foram atrás eles pelo caminho do Jordão, até os vaus: e a porta foi fechada depois que saíram os que atrás eles iam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Mas antes que eles dormissem, ela subiu a eles ao terraço, e disse-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Sê que o SENHOR vos deu esta terra; porque o temor de vós caiu sobre nós, e todos os moradores do país estão desmaiados por causa de vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Porque ouvimos que o SENHOR fez secar as águas do mar Vermelho diante de vós, quando saístes do Egito, e o que fizestes aos dois reis pelos amorreus que estavam da parte dali do Jordão, a Seom e a Ogue, aos quais destruístes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Ouvindo isto, desmaiou nosso coração; nem restou mais espírito em alguém por causa de vós: porque o SENHOR vosso Deus é Deus acima nos céus e abaixo na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Rogo-vos, pois, agora, me jureis pelo SENHOR, que como fiz misericórdia convosco, assim a fareis vós com a casa de meu pai, do qual me dareis um sinal certo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'E que salvareis a vida a meu pai e a minha mãe, e a meus irmãos e irmãs, e a todo o que for seu; e que livrareis nossas vidas da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'E eles lhe responderam: Nossa vida esteja pela vossa até a morte, se não denunciardes este nosso negócio; e quando o SENHOR houver nos dado a terra, nós a trataremos com misericórdia e fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Então ela os fez descer com uma corda pela janela; porque sua casa estava à parede do muro, e ela vivia no muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'E disse-lhes: Marchai-vos ao monte, porque os que foram atrás vós não vos encontrem; e estai escondidos ali três dias, até que os que vos seguem tenham voltado; e depois vos ireis vosso caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'E eles lhe disseram: Nós seremos desobrigados deste juramento com que nos hás conjurado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Eis que, quando nós entrarmos na terra, tu atarás este cordão de escarlate à janela pela qual nos fizeste descer: e tu juntarás em tua casa teu pai e tua mãe, teus irmãos e toda a família de teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Qualquer um que sair fora das portas de tua casa, seu sangue será sobre sua cabeça, e nós sem culpa. Mas qualquer um que estiver em casa contigo, seu sangue será sobre nossa cabeça, se mão o tocar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'E se tu denunciares este nosso negócio, nós seremos desobrigados deste teu juramento com que nos fizeste jurar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'E ela respondeu: Seja assim como dissestes. Logo os despediu, e se foram: e ela atou o cordão de escarlate à janela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'E caminhando eles, chegaram ao monte, e estiveram ali três dias, até que os que os seguiam se houvessem voltado: e os que os seguiram, buscaram por todo aquele caminho, mas não os acharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'E voltando-se os dois homens, desceram do monte, e passaram, e vieram a Josué filho de Num, e contaram-lhe todas as coisas que lhes haviam acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'E disseram a Josué: O SENHOR entregou toda a terra em nossas mãos; e também todos os moradores do país estão desmaiados diante de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'E levantou-se Josué de manhã, e partiram de Sitim, e vieram até o Jordão, ele e todos os filhos de Israel, e repousaram ali antes que passassem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'E passados três dias, os oficiais atravessaram por meio do acampamento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'E mandaram ao povo, dizendo: Quando virdes a arca do pacto do SENHOR vosso Deus, e os sacerdotes e levitas que a levam, vós partireis de vosso lugar, e marchareis atrás dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Porém entre vós e ela haja distância como da medida de dois mil côvados: e não vos aproximareis dela, a fim de que saibais o caminho por onde haveis de ir: porquanto vós não passastes antes de agora por este caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'E Josué disse ao povo: Santificai-vos, porque o SENHOR fará amanhã entre vós maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'E falou Josué aos sacerdotes, dizendo: Tomai a arca do pacto, e passai diante do povo. E eles tomaram a arca do pacto, e foram diante do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Então o SENHOR disse a Josué: Desde este dia começarei a fazer-te grande diante dos olhos de todo Israel, para que entendam que como fui com Moisés, assim serei contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Tu, pois, mandarás aos sacerdotes que levam a arca do pacto, dizendo: Quando houverdes entrado até a borda da água do Jordão, parareis no Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'E Josué disse aos filhos de Israel: Achegai-vos aqui, e escutai as palavras do SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'E acrescentou Josué: Em isto conhecereis que o Deus vivente está em meio de vós, e que ele lançará de diante de vós aos cananeus, e aos heteus, e aos heveus, e aos perizeus, e aos gergeseus, e aos amorreus, e aos jebuseus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Eis que, a arca do pacto do Dominador de toda a terra passa o Jordão diante de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Tomai, pois, agora doze homens das tribos de Israel, de cada tribo um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'E quando as plantas dos pés dos sacerdotes que levam a arca do SENHOR Dominador de toda a terra, forem assentadas sobre as águas do Jordão, as águas do Jordão se partirão: porque as águas que vem de acima se deterão em um amontoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'E aconteceu que, partindo o povo de suas tendas para passar o Jordão, e os sacerdotes diante do povo levando a arca do pacto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Quando os que levavam a arca chegaram no Jordão, assim como os pés dos sacerdotes que levavam a arca foram molhados à beira da água, (porque o Jordão costuma transbordar sobre todas as suas margens todo aquele tempo da colheita,)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'As águas que vinham de cima pararam, e amontoaram-se bem longe, na cidade de Adã, que está ao lado de Zaretã; e as que desciam ao mar das planícies, ao mar Salgado, esgotaram-se e foram totalmente interrompidas; e o povo passou em frente de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Mas os sacerdotes que levavam a arca do pacto do SENHOR, ficaram firmes em seco, no meio do Jordão, e todo Israel passou em seco, até que todo o povo acabou de passar o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'E quando toda a nação acabou de passar o Jordão, o SENHOR falou a Josué, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Tomai do povo doze homens, de cada tribo um,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'E mandai-lhes, dizendo: Tomai-vos daqui do meio do Jordão, do lugar de onde estão firmes os pés dos sacerdotes, doze pedras, as quais passareis convosco, e as assentareis no alojamento de onde haveis de passar a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Então Josué chamou aos doze homens, os quais ele havia ordenado dentre os filhos de Israel, de cada tribo um;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'E disse-lhes Josué: Passai diante da arca do SENHOR vosso Deus ao meio do Jordão; e cada um de vós tome uma pedra sobre seu ombro, conforme ao número das tribos dos filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Para que isto seja sinal entre vós; e quando vossos filhos perguntarem a seus pais amanhã, dizendo: “Que vos significam estas pedras?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Então vós lhes respondereis: “As águas do Jordão foram interrompidas diante da arca do pacto do SENHOR; quando ela passou pelo Jordão, as águas do Jordão se separaram; e estas pedras serão por memorial aos filhos de Israel para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'E os filhos de Israel o fizeram assim como Josué havia lhes mandado, e levantaram doze pedras do meio do Jordão, como o SENHOR havia dito a Josué, conforme o número das tribos dos filhos de Israel; e levaram-nas consigo ao alojamento, e ali as puseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Josué também levantou doze pedras no meio do Jordão, no lugar onde estiveram os pés dos sacerdotes que levavam a arca do pacto; e ali estão até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Pois os sacerdotes que levavam a arca ficaram parados no meio do Jordão, até que se cumpriu tudo o que o SENHOR havia mandado a Josué dizer ao povo, conforme tudo quanto Moisés havia ordenado a Josué; e o povo apressou-se e passou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'E sucedeu quando todo o povo acabou de passar, então passaram a arca do SENHOR, e os sacerdotes, na presença do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Também os filhos de Rúben, os filhos de Gade, e a meia tribo de Manassés, passaram armados diante dos filhos de Israel, como Moisés havia lhes dito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'cerca de quarenta mil homens prontamente armados passaram ó diante do SENHOR para a batalha, às campina de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Naquele dia o SENHOR engrandeceu Josué à vista de todo Israel; e temeram-no, como haviam temido a Moisés, todos os dias de sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'E o SENHOR falou a Josué, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '“Manda os sacerdotes que levam a arca do testemunho, que subam do Jordão”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'E Josué mandou os sacerdotes, dizendo: “Subi do Jordão”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'E aconteceu que quando os sacerdotes que levavam a arca do pacto do SENHOR subiram do meio do Jordão, e as plantas dos pés dos sacerdotes estiveram em seco, as águas do Jordão voltaram ao seu lugar, correndo como antes sobre todas as suas margens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'E o povo subiu do Jordão no dia dez do mês primeiro, e assentaram o acampamento em Gilgal, ao lado oriental de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'E Josué erigiu em Gilgal as doze pedras que haviam trazido do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'E falou aos filhos de Israel, dizendo: Quando amanhã perguntarem vossos filhos a seus pais, e disserem: Que vos significam estas pedras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Declarareis a vossos filhos, dizendo: Israel passou em seco por este Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Porque o SENHOR vosso Deus secou as águas do Jordão diante de vós, até que havíeis passado, à maneira que o SENHOR vosso Deus o havia feito no mar Vermelho, ao qual secou diante de nós até que passamos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Para que todos os povos da terra conheçam a mão do SENHOR, que é forte; para que temais ao SENHOR vosso Deus todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'E quando todos os reis dos amorreus, que estavam da outra parte do Jordão ao ocidente, e todos os reis dos cananeus, que estavam próximos do mar, ouviram como o SENHOR havia secado as águas do Jordão diante dos filhos de Israel até que passaram, desfaleceu seu coração, e não houve mais espírito neles diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Naquele tempo o SENHOR disse a Josué: Faze-te facas afiadas, e volta a circuncidar a segunda vez aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'E Josué se fez facas afiadas, e circuncidou aos filhos de Israel no monte dos prepúcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Esta é a causa pela qual Josué os circuncidou: todo aquele povo que havia saído do Egito, os homens, todos os homens de guerra, haviam morrido no deserto pelo caminho, depois que saíram do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Porque todos os do povo que haviam saído, estavam circuncidados: mas todo aquele povo que havia nascido no deserto pelo caminho, depois que saíram do Egito, não estavam circuncidados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Porque os filhos de Israel andaram pelo deserto por quarenta anos, até que toda a gente dos homens de guerra que haviam saído do Egito foi consumida, porquanto não obedeceram à voz do SENHOR; pelo qual o SENHOR lhes jurou que não lhes deixaria ver a terra, da qual o SENHOR havia jurado a seus pais que não as daria, terra que flui leite e mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'E os filhos deles, que ele havia feito suceder em seu lugar, Josué os circuncidou; pois eram incircuncisos, porque não haviam sido circuncidados pelo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'E quando acabaram de circuncidar toda a gente, ficaram no mesmo lugar no acampamento, até que sararam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'E o SENHOR disse a Josué: Hoje tirei de vós a humilhação do Egito: pelo qual o nome daquele lugar foi chamado Gilgal, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'E os filhos de Israel assentaram o acampamento em Gilgal, e celebraram a páscoa aos catorze dias do mês, pela tarde, nas planícies de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'E ao outro dia da páscoa comeram do fruto da terra os pães sem levedura, e no mesmo dia espigas novas tostadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'E o maná cessou o dia seguinte, desde que começaram a comer do fruto da terra: e os filhos de Israel nunca mais tiveram maná, mas sim que comeram dos frutos da terra de Canaã aquele ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'E estando Josué próximo de Jericó, levantou seus olhos, e viu um homem que estava diante dele, o qual tinha uma espada nua em sua mão. E Josué indo até ele, lhe disse: És dos nossos, ou de nossos inimigos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'E ele respondeu: Não; mas sim Príncipe do exército do SENHOR, agora vim. Então Josué prostrando-se sobre seu rosto em terra o adorou; e disse-lhe: Que diz meu Senhor a seu servo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'E o Príncipe do exército do SENHOR respondeu a Josué: Tira teus sapatos de teus pés; porque o lugar onde estás é santo. E Josué o fez assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Porém Jericó estava fechada, bem fechada, por causa dos filhos de Israel: ninguém entrava, nem saía.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Mas o SENHOR disse a Josué: Olha, eu entreguei em tua mão a Jericó e a seu rei, com seus homens de guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Cercareis, pois, a cidade todos os homens de guerra, indo ao redor da cidade uma vez: e isto fareis seis dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'E sete sacerdotes levarão sete trombetas de chifres de carneiros diante da arca; e ao sétimo dia dareis sete voltas à cidade, e os sacerdotes tocarão as trombetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'E quando tocarem prolongadamente a trombeta de carneiro, assim que ouvirdes o som da trombeta, todo aquele povo gritará a grande voz, e o muro da cidade cairá debaixo de si: então o povo subirá cada um em frente de si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'E chamando Josué filho de Num aos sacerdotes, lhes disse: Levai a arca do pacto, e sete sacerdotes levem trombetas de chifres de carneiros diante da arca do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'E disse ao povo: Passai, e rodeai a cidade; e os que estão armados passarão diante da arca do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'E assim que Josué falou ao povo, os sete sacerdotes, levando as sete trombetas de chifres de carneiros, passaram diante da arca do SENHOR, e tocaram as trombetas: e a arca do pacto do SENHOR os seguia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'E os homens armados iam diante dos sacerdotes que tocavam as trombetas, e a gente reunida ia detrás da arca, andando e tocando trombetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'E Josué mandou ao povo, dizendo: Vós não dareis grito, nem se ouvirá vossa voz, nem sairá palavra de vossa boca, até o dia que eu vos diga: Gritai: então dareis grito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Então a arca do SENHOR deu uma volta ao redor da cidade, e vieram-se ao acampamento, no qual tiveram a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'E Josué se levantou de manhã, e os sacerdotes tomaram a arca do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'E os sete sacerdotes, levando as sete trombetas de chifres de carneiros, foram diante da arca do SENHOR, andando sempre e tocando as trombetas; e os armados iam diante deles, e a gente reunida ia detrás da arca do SENHOR, andando e tocando l');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Assim deram outra volta à cidade o segundo dia, e voltaram ao acampamento: desta maneira fizeram por seis dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'E ao sétimo dia levantaram-se quando subia a alva, e deram volta à cidade da mesma maneira sete vezes: somente este dia deram volta ao redor dela sete vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'E quando os sacerdotes tocaram as trombetas pela sétima vez, Josué disse ao povo: Dai grito, porque o SENHOR vos entregou a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Mas a cidade será anátema ao SENHOR, ela com todas as coisas que estão nela: somente Raabe a prostituta viverá, com todos os que estiverem em casa com ela, porquanto escondeu os mensageiros que enviamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Porém guardai-vos vós do anátema, que nem toqueis, nem tomeis alguma coisa do anátema, porque não façais anátema o acampamento de Israel, e o perturbeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Mas toda a prata, e o ouro, e vasos de bronze e de ferro, seja consagrado ao SENHOR, e venha ao tesouro do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Então o povo deu grito, e os sacerdotes tocaram as trombetas: e aconteceu que quando o povo ouviu o som da trombeta, deu o povo grito com grande barulho, e o muro caiu verticalmente. O povo subiu logo à cidade, cada um em frente de si, e tomaram-na.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'E destruíram tudo o que na cidade havia; homens e mulheres, moços e anciãos, até os bois, e ovelhas, e asnos, a fio de espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Mas Josué disse aos dois homens que haviam reconhecido a terra: Entrai em casa da mulher prostituta, e fazei sair dali à mulher, e a tudo o que for seu, como o jurastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'E os rapazes espias entraram, e tiraram a Raabe, e a seu pai, e a sua mãe, e a seus irmãos, e todo o que era seu; e também tiraram a toda sua parentela, e puseram-nos fora do acampamento de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'E consumiram com fogo a cidade, e tudo o que nela havia: somente puseram no tesouro da casa do SENHOR a prata, e o ouro, e os vasos de bronze e de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Mas Josué salvou a vida a Raabe a prostituta, e à casa de seu pai, e a tudo o que ela tinha: e habitou ela entre os israelitas até hoje; porquanto escondeu os mensageiros que Josué enviou a reconhecer a Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'E naquele tempo Josué lhes juramentou dizendo: Maldito diante do SENHOR o homem que se levantar e reedificar esta cidade de Jericó. Em seu primogênito lance seus alicerces, e em seu menor assente suas portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Foi, pois, o SENHOR com Josué, e seu nome se divulgou por toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Porém os filhos de Israel cometeram transgressão no anátema: porque Acã, filho de Carmi, filho de Zabdi, filho de zerá, da tribo de Judá, tomou do anátema; e a ira do SENHOR se acendeu contra os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'E Josué enviou homens desde Jericó a Ai, que estava junto a Bete-Áven até o oriente de Betel; e falou-lhes dizendo: Subi, e reconhecei a terra. E eles subiram, e reconheceram a Ai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'E voltando a Josué, disseram-lhe: Não suba todo aquele povo, mas subam como dois mil ou como três mil homens, e tomarão a Ai: não canses a todo aquele povo ali, porque são poucos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'E subiram ali do povo como três mil homens, os quais fugiram diante dos de Ai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'E os de Ai feriram deles como trinta e seis homens, e seguiram-nos desde a porta até Sebarim, e os feriram na descida: pelo que se dissolveu o coração do povo, e veio a ser como água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Então Josué rasgou suas roupas, e prostrou-se em terra sobre seu rosto diante da arca do SENHOR até à tarde, ele e os anciãos de Israel; e lançaram pó sobre suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'E Josué disse: Ah, Senhor DEUS! Por que fizeste passar a este povo o Jordão, para entregar-nos nas mãos dos amorreus, que nos destruam? Antes nos tivéssemos ficado da outra parte do Jordão!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Ai Senhor! Que direi, já que Israel virou as costas diante de seus inimigos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Porque os cananeus e todos os moradores da terra ouvirão, e nos cercarão, e apagarão nosso nome de sobre a terra: então que farás tu a teu grande nome?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'E o SENHOR disse a Josué: Levanta-te; por que te prostras assim sobre teu rosto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel pecou, e ainda quebrantou meu pacto que eu lhes havia mandado; pois ainda tomaram do anátema, e até furtaram, e também mentiram, e ainda o guardaram entre seus utensílios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Por isto os filhos de Israel não poderão estar diante de seus inimigos, mas sim que diante de seus inimigos virarão as costas; porquanto vieram a ser anátema: nem serei mais convosco, se não destruirdes o anátema do meio de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Levanta-te, santifica ao povo, e dize: Santificai-vos para amanhã, porque o SENHOR o Deus de Israel diz assim: Anátema há em meio de ti, Israel; não poderás estar diante de teus inimigos, até tanto que tenhais tirado o anátema do meio de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Vós vos achegareis, pois, amanhã por vossas tribos; e a tribo que o SENHOR tomar, se achegará por suas famílias; e a família que o SENHOR tomar, se achegará por suas casas; e a casa que o SENHOR tomar, se achegará pelos homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'E o que for colhido no anátema, será queimado a fogo, ele e tudo o que tem, porquanto quebrantou o pacto do SENHOR, e cometeu maldade em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Josué, pois, levantando-se de manhã, fez achegar a Israel por suas tribos; e foi tomada a tribo de Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'E fazendo achegar a tribo de Judá, foi tomada a família dos de Zerá; fazendo logo achegar a família dos de Zerá pelos homens, foi tomado Zabdi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'E fez achegar sua casa pelos homens, e foi tomado Acã, filho de Carmi, filho de Zabdi, filho de zerá, da tribo de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Então Josué disse a Acã: Filho meu, dá glória agora ao SENHOR o Deus de Israel, e dá-lhe louvor, e declara-me agora o que fizeste; não me o encubras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'E Acã respondeu a Josué, dizendo: Verdadeiramente eu pequei contra o SENHOR o Deus de Israel, e fiz assim e assim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Que vi entre os despojos um manto babilônico muito bom, e duzentos siclos de prata, e uma barra de ouro de peso de cinquenta siclos; o qual cobicei, e tomei: e eis que está escondido debaixo da terra no meio de minha tenda, e o dinheiro debaixo dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Josué então enviou mensageiros, os quais foram correndo à tenda; e eis que estava escondido em sua tenda, e o dinheiro debaixo disso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'E tomando-o do meio da tenda, trouxeram-no a Josué e a todos os filhos de Israel, e puseram-no diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Então Josué, e todo Israel com ele, tomou a Acã filho de zerá, e o dinheiro, e o manto, e a barra de ouro, e seus filhos, e suas filhas, e seus bois, e seus asnos, e suas ovelhas, e sua tenda, e tudo quanto tinha, e levaram-no tudo ao vale de Acor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'E disse Josué: Por que nos perturbaste? Perturbe-te o SENHOR neste dia. E todos os israelitas os apedrejaram, e os queimaram a fogo, depois de apedrejá-los com pedras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'E levantaram sobre ele um grande amontoado de pedras, até hoje. E o SENHOR se apaziguou da ira de seu furor. E por isto foi chamado aquele lugar o Vale de Acor, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'E o SENHOR disse a Josué: Não temas, nem desmaies; toma contigo toda a gente de guerra, e levanta-te e sobe a Ai. Olha, eu entreguei em tua mão ao rei de Ai, e a seu povo, a sua cidade, e a sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'E farás a Ai e a seu rei como fizeste a Jericó e a seu rei: somente que seus despojos e seus animais tomareis para vós. Porás, pois, emboscadas à cidade detrás dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'E levantou-se Josué, e toda a gente de guerra, para subir contra Ai: e escolheu Josué trinta mil homens fortes, os quais enviou de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'E mandou-lhes, dizendo: Olhai, poreis emboscada à cidade detrás dela: não vos afastareis muito da cidade, e estareis todos prontos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'E eu, e todo aquele povo que está comigo, nos aproximaremos da cidade; e quando saírem eles contra nós, como fizeram antes, fugiremos diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'E eles sairão atrás de nós, até que os tiremos da cidade; porque eles dirão: Fogem de nós como a primeira vez. Fugiremos, pois, diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Então vós vos levantareis da emboscada, e vos lançareis sobre a cidade; pois o SENHOR vosso Deus a entregará em vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'E quando a houverdes tomado, poreis fogo nela. Fareis conforme a palavra do SENHOR. Olhai que vos o mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Então Josué os enviou; e eles se foram à emboscada, e puseram-se entre Betel e Ai, ao ocidente de Ai: e Josué ficou aquela noite em meio do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'E levantando-se Josué muito de manhã, revistou ao povo, e subiu ele, com os anciãos de Israel, diante do povo contra Ai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'E toda a gente de guerra que com ele estava, subiu, e aproximou-se, e chegaram diante da cidade, e assentaram o campo à parte do norte de Ai: e o vale estava entre ele e Ai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'E tomou como cinco mil homens, e os pôs em emboscada entre Betel e Ai, à parte ocidental da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'E o povo, todo aquele acampamento que estava à parte do norte da cidade, colocado já próximo, e sua emboscada ao ocidente da cidade, veio Josué aquela noite ao meio do vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'O qual quando o rei de Ai viu, levantou-se prontamente de manhã, e saiu com a gente da cidade contra Israel, ele e todo seu povo, para combater pela planície ao tempo assinalado, não sabendo que lhe estava posta emboscada atrás da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Então Josué e todo Israel, fazendo-se de vencidos, fugiram diante deles pelo caminho do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'E todo aquele povo que estava em Ai se juntou para segui-los: e seguiram a Josué, sendo assim tirados da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'E não ficou homem em Ai e Betel, que não tivesse saído atrás de Israel; e por perseguir a Israel deixaram a cidade aberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Então o SENHOR disse a Josué: Levanta a lança que tens em tua mão até Ai, porque eu a entregarei em tua mão. E Josué levantou até a cidade a lança que em sua mão tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'E levantando-se prontamente de seu lugar os que estavam na emboscada, correram logo que ele levantou sua mão, e vieram à cidade, e a tomaram, e apressaram-se a por-lhe fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'E quando os da cidade olharam atrás, observaram, e eis que a fumaça da cidade que subia ao céu, e não puderam fugir nem a uma parte nem à outra: e o povo que ia fugindo até o deserto, se voltou contra os que o seguiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Josué e todo Israel, vendo que os da emboscada tomaram a cidade, e que a fumaça da cidade subia, voltaram, e feriram aos de Ai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'E os outros saíram da cidade a seu encontro: e assim foram cercados em meio de Israel, os uns da uma parte, e os outros da outra. E os feriram até que não restou nenhum deles que escapasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'E tomaram vivo ao rei de Ai, e trouxeram-lhe a Josué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'E quando os israelitas acabaram de matar a todos os moradores de Ai no campo, no deserto, onde eles os haviam perseguido, e que todos haviam caído a fio de espada até serem consumidos, todos os israelitas se voltaram a Ai, e também a feriram à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'E o número dos que caíram aquele dia, homens e mulheres, foi doze mil, todos os de Ai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'E Josué não retraiu sua mão que havia estendido com a lança, até que destruiu a todos os moradores de Ai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Porém os israelitas tomaram para si os animais e os despojos da cidade, conforme a palavra do SENHOR que ele havia mandado a Josué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'E Josué queimou a Ai e reduziu-a a um amontoado perpétuo, assolado até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Mas ao rei de Ai enforcou de um madeiro até à tarde: e quando o sol se pôs, mandou Josué que tirassem do madeiro seu corpo, e o lançassem à porta da cidade: e levantaram sobre ele um grande amontoado de pedras, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Então Josué edificou um altar ao SENHOR Deus de Israel no monte de Ebal,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Como Moisés, servo do SENHOR, o havia mandado aos filhos de Israel, como está escrito no livro da lei de Moisés, um altar de pedras inteiras sobre as quais ninguém levantou ferro: e ofereceram sobre ele holocaustos ao SENHOR, e sacrificaram ofertas pacíficas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Também escreveu ali em pedras a repetição da lei de Moisés, a qual ele havia escrito diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'E todo Israel, e seus anciãos, oficiais, e juízes, estavam da uma e da outra parte junto à arca, diante dos sacerdotes levitas que levam a arca do pacto do SENHOR; tanto estrangeiros como naturais, a metade deles estava até o monte de Gerizim, e a outra metade até o monte de Ebal; da maneira que Moisés, servo do SENHOR, havia lhe mandado antes, para que abençoassem primeiramente ao povo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Depois disto, leu todas as palavras da lei, as bênçãos e as maldições, conforme tudo o que está escrito no livro da lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Não houve palavra alguma de todas as coisas que mandou Moisés, que Josué não fizesse ler diante de toda a congregação de Israel, mulheres e meninos, e estrangeiros que andavam entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'E aconteceu que quando ouviram estas coisas todos os reis que estavam desta parte do Jordão, tanto nas montanhas como nas planícies, e em toda a costa do grande mar diante do Líbano, os heteus, amorreus, cananeus, perizeus, heveus, e jebuseus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Juntaram-se em unidade, de um acordo, para lutar contra Josué e Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Mas os moradores de Gibeão, quando ouviram o que Josué havia feito a Jericó e a Ai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Eles usaram também de astúcia; pois foram e fingiram-se embaixadores, e tomaram sacos anciãos sobre seus asnos, e odres anciãos de vinho, rasgados e remendados,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'E sapatos velhos e remendados em seus pés, com roupas velhas sobre si; e todo aquele pão que traziam para o caminho, seco e mofado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Assim vieram a Josué ao acampamento em Gilgal, e disseram-lhe a ele e aos de Israel: Nós viemos da terra muito distante: fazei, pois, agora conosco aliança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'E os de Israel responderam aos heveus: Talvez vós habiteis em meio de nós: como pois poderemos nós fazer aliança convosco?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'E eles responderam a Josué: Nós somos teus servos. E Josué lhes disse: Quem sois vós e de onde vindes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'E eles responderam: Teus servos vieram de muito distantes terras, pela fama do SENHOR teu Deus; porque ouvimos sua fama, e todas as coisas que fez em Egito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'E tudo o que fez aos dois reis dos amorreus que estavam da outra parte do Jordão; a Seom rei de Hesbom, e a Ogue rei de Basã, que estava em Astarote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Pelo qual nossos anciãos e todos os moradores de nossa terra nos disseram: Tomai em vossas mãos provisão para o caminho, e ide ao encontro deles, e dizei-lhes: Nós somos vossos servos, e fazei agora conosco aliança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Este nosso pão tomamos quente de nossas casas para o caminho o dia que saímos para vir a vós; e ei-lo aqui agora que está seco e mofado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Estes odres de vinho também os enchemos novos; ei-los aqui já rasgados: também estes nossas roupas e nossos sapatos estão já velhos por causa do muito longo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'E os homens de Israel tomaram de sua provisão do caminho, e não perguntaram à boca do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'E Josué fez paz com eles, e estabeleceu com eles que lhes deixaria a vida: também os príncipes da congregação lhes juraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Passados três dias depois que fizeram com eles o concerto, ouviram como eram seus vizinhos, e que habitavam em meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'E partiram-se os filhos de Israel, e ao terceiro dia chegaram a suas cidades: e suas cidades eram Gibeão, Quefira, Beerote, e Quiriate-Jearim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'E não os feriram os filhos de Israel, porquanto os príncipes da congregação lhes haviam jurado pelo SENHOR o Deus de Israel. E toda a congregação murmurava contra os príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Mas todos os príncipes responderam a toda a congregação: Nós lhes juramos pelo SENHOR Deus de Israel; portanto, agora não lhes podemos tocar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Isto faremos com eles: lhes deixaremos viver, para que não venha ira sobre nós por causa do juramento que lhes fizemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'E os príncipes lhes disseram: Vivam; mas sejam lenhadores e carregadores de água para toda a congregação, como os príncipes lhes disseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'E chamando-os Josué, lhes falou dizendo: Por que nos enganastes, dizendo, Habitamos muito longe de vós; uma vez que morais em meio de nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Vós pois agora sois malditos, e não faltará de vós servo, e quem corte a lenha e tire a água para a casa de meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'E eles responderam a Josué, e disseram: Quando foi dado a entender a teus servos, que o SENHOR teu Deus havia mandado a Moisés seu servo que vos havia de dar toda a terra, e que havia de destruir todos os moradores da terra diante de vós, por isto temos muito medo de vós por nossas vidas, e fizemos isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Agora pois, eis-nos aqui em tua mão; o que te parecer bom e correto fazer de nós, faze-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'E ele o fez assim; que os livrou da mão dos filhos de Israel, para que não os matassem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'E constituiu-os Josué aquele dia por lenhadores e carregadores de água para a congregação e para o altar do SENHOR, no lugar que ele escolhesse: o que são até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'E quando Adoni-Zedeque rei de Jerusalém ouviu que Josué havia tomado a Ai, e que a haviam assolado, (como havia feito a Jericó e a seu rei, assim fez a Ai e a seu rei;) e que os moradores de Gibeão fizeram paz com os israelitas, e que estavam entre eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Tiveram muito grande temor; porque Gibeão era uma grande cidade, como uma das cidades reais, e maior que Ai, e todos os seus homens fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Enviou, pois, a dizer Adoni-Zedeque rei de Jerusalém, a Hoão rei de Hebrom, e a Pirã rei de Jeremote, e a Jafia rei de Laquis, e a Debir rei de Eglom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Subi a mim, e ajudai-me, e combatamos a Gibeão: porque fez paz com Josué e com os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'E cinco reis dos amorreus, o rei de Jerusalém, o rei de Hebrom, o rei de Jeremote, o rei de Laquis, o rei de Eglom, se juntaram e subiram, eles com todos os seus exércitos, e assentaram acampamento sobre Gibeão, e lutaram contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'E os moradores de Gibeão enviaram a dizer a Josué ao acampamento em Gilgal: Não encolhas tuas mãos de teus servos; sobe prontamente a nós para guardar-nos e ajudar-nos: porque todos os reis dos amorreus que habitam nas montanhas, se juntaram contra nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'E subiu Josué de Gilgal, ele e todo aquele povo de guerra com ele, e todos os homens valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'E o SENHOR disse a Josué: Não tenhas medo deles: porque eu os entreguei em tua mão, e nenhum deles resistirá diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'E Josué veio a eles de repente, toda a noite subiu desde Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'E o SENHOR os perturbou diante de Israel, e feriu-os com grande mortandade em Gibeão: e seguiu-os pelo caminho que sobe a Bete-Horom, e feriu-os até Azeca e Maceda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'E quando iam fugindo dos israelitas, à descida de Bete-Horom, o SENHOR lançou sobre eles do céu grandes pedras até Azeca, e morreram: muitos mais morreram das pedras do granizo, que os que os filhos de Israel haviam matado à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Então Josué falou ao SENHOR o dia que o SENHOR entregou aos amorreus diante dos filhos de Israel, e disse em presença dos israelitas: Sol, detém-te em Gibeão; E tu, Lua, no vale de Aijalom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'E o sol se deteve e a lua se parou, Até tanto que a gente se havia vingado de seus inimigos. Não está este escrito no livro de Jasar? E o sol se parou em meio do céu, e não se apressou a se pôr quase um dia inteiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'E nunca foi tal dia antes nem depois daquele, havendo atendido o SENHOR à voz de um homem: porque o SENHOR lutava por Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'E Josué, e todo Israel com ele, voltava-se ao acampamento em Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Porém os cinco reis fugiram, e se esconderam em uma cova em Maquedá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'E foi dito a Josué que os cinco reis haviam sido achados em uma cova em Maquedá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Então Josué disse: Rolai grandes pedras à boca da cova, e ponde homens junto a ela que os guardem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'E vós não vos pareis, mas sim segui a vossos inimigos, e feri-lhes a retaguarda, sem deixar-lhes entrar em suas cidades; porque o SENHOR vosso Deus os entregou em vossa mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'E aconteceu que quando Josué e os filhos de Israel acabaram de feri-los com mortandade muito grande, até destruí-los, os que restaram deles se meteram nas cidades fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'E todo aquele povo se voltou salvo ao acampamento a Josué em Maquedá; que não houve quem movesse sua língua contra os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Então disse Josué: Abri a boca da cova, e tirai-me dela a estes cinco reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'E fizeram-no assim, e tiraram-lhe da cova aqueles cinco reis: ao rei de Jerusalém, ao rei de Hebrom, ao rei de Jeremote, ao rei de Laquis, ao rei de Eglom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'E quando tiraram estes reis a Josué, chamou Josué a todos os homens de Israel, e disse aos principais da gente de guerra que haviam vindo com ele: Chegai e ponde vossos pés sobre os pescoços destes reis. E eles se aproximaram, e puseram seus pés sobre os pescoços deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'E Josué lhes disse: Não temais, nem vos atemorizeis; sede fortes e valentes: porque assim fará o SENHOR a todos vossos inimigos contra os quais lutai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'E depois disto Josué os feriu e os matou, e os fez enforcar em cinco madeiros: e restaram enforcados nos madeiros até à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'E quando o sol se ia a pôr, mandou Josué que os tirassem dos madeiros, e os lançassem na cova de onde se haviam escondido: e puseram grandes pedras à boca da cova, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Naquele mesmo dia tomou Josué a Maquedá, e a pôs à espada, e matou a seu rei; a eles e a tudo o que nela tinha vida, sem restar nada: mas ao rei de Maquedá fez como havia feito ao rei de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'E de Maquedá passou Josué, e todo Israel com ele, a Libna; e lutou contra Libna:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'E o SENHOR a entregou também a ela, e a seu rei, em mãos de Israel; e feriu-a a fio de espada, com tudo o que nela havia vivo, sem restar nada: mas a seu rei fez da maneira que havia feito ao rei de Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'E Josué, e todo Israel com ele, passou de Libna a Laquis, e pôs acampamento contra ela, e combateu-a:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'E o SENHOR entregou a Laquis em mão de Israel, e tomou-a ao dia seguinte, e feriu-a à espada, com tudo o que nela havia vivo, como havia feito em Libna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Então Horão, rei de Gezer, subiu em ajuda de Laquis; mas a ele e a seu povo feriu Josué, até não restar nenhum deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'De Laquis passou Josué, e todo Israel com ele, a Eglom: e puseram acampamento contra ela, e combateram-na:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'E a tomaram no mesmo dia, e meteram-na à espada; e aquele dia matou a todo o que nela havia vivo, como havia feito em Laquis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Subiu logo Josué, e todo Israel com ele, de Eglom a Hebrom, e combateram-na;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'E tomando-a, feriram-na à espada, a seu rei e a todas as suas cidades, com tudo o que nela havia vivo, sem restar nada: como fizeram a Eglom, assim a destruíram com tudo o que nela havia vivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'E voltando-se Josué, e todo Israel com ele, sobre Debir, combateu-a;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'E tomou-a, e a seu rei, e a todas as suas vilas; e feriram-nos à espada, e destruíram tudo o que ali dentro havia vivo, sem restar nada; como havia feito a Hebrom, assim fez a Debir e a seu rei; e como havia feito a Libna e a seu rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Feriu pois Josué toda a região das montanhas, e do sul, e das planícies, e das costas, e a todos os seus reis, sem restar nada; tudo o que tinha vida matou, ao modo que o SENHOR Deus de Israel o havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'E feriu-os Josué desde Cades-Barneia até Gaza, e toda a terra de Gósen até Gibeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Todos estes reis e suas terras tomou Josué de uma vez; porque o SENHOR o Deus de Israel lutava por Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'E voltou Josué, e todo Israel com ele, ao acampamento em Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Ouvindo isto Jabim rei de Hazor, enviou mensagem a Jobabe rei de Madom, e ao rei de Sinrom, e ao rei de Acsafe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'E aos reis que estavam à parte do norte nas montanhas, e na planície ao sul de Quinerete, e nas planícies, e nas regiões de Dor ao ocidente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'E aos cananeus que estava ao oriente e ao ocidente, e aos amorreus, e ao Heteu, e aos perizeus, e aos jebuseus nas montanhas, e aos heveus debaixo de Hermom em terra de Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Estes saíram, e com eles todos os seus exércitos, povo muito em grande maneira, como a areia que está à beira do mar, com grande multidão de cavalos e carros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Todos estes reis se juntaram, e vindo reuniram os acampamentos junto às águas de Merom, para lutar contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Mas o SENHOR disse a Josué: Não tenhas medo deles, que amanhã a esta hora eu entregarei a todos estes, mortos diante de Israel: a seus cavalos aleijarás, e seus carros queimarás ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'E veio Josué, e com ele todo aquele povo de guerra, contra eles, e deu de repente sobre eles junto às águas de Merom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'E entregou-os o SENHOR em mãos de Israel, os quais os feriram e seguiram até a grande Sidom, e até as águas quentes, e até a planície de Mispá ao oriente, ferindo-os até que não lhes deixaram ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'E Josué fez com eles como o SENHOR lhe havia mandado: aleijou seus cavalos, e seus carros queimou ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'E voltando-se Josué, tomou no mesmo tempo a Hazor, e feriu à espada a seu rei: a qual Hazor havia sido antes cabeça de todos estes reinos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'E feriram à espada todo quanto nela havia vivo, destruindo e não deixando coisa com vida; e a Hazor puseram a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Também tomou Josué todas as cidades destes reis, e a todos os reis delas, e os meteu à espada, e os destruiu, como Moisés servo do SENHOR o havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Porém todas as cidades que estavam em suas colinas, não as queimou Israel, tirando a só Hazor, a qual queimou Josué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'E os filhos de Israel tomaram para si todos os despojos e animais daquelas cidades: mas a todos os homens feriram à espada até destruí-los, sem deixar alguém com vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Da maneira que o SENHOR o havia mandado a Moisés seu servo, assim Moisés o mandou a Josué: e assim Josué o fez, sem tirar palavra de tudo o que o SENHOR havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Tomou, pois, Josué toda aquela terra, as montanhas, e toda a região do sul, e toda a terra de Gósen, e os terrenos baixos e as planícies, e a região montanhosa de Israel e seus vales.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Desde o monte de Halaque, que sobe até Seir, até Baal-Gade na planície do Líbano, às raízes do monte Hermom: tomou também todos os seus reis, os quais feriu e matou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Por muitos dias teve guerra Josué com estes reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Não houve cidade que fizesse paz com os filhos de Israel, a não ser os heveus, que moravam em Gibeão: tudo o tomaram por guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Porque isto veio do SENHOR, que endurecia o coração deles para que resistissem com guerra a Israel, para destruí-los, e que não lhes fosse feita misericórdia, antes fossem desarraigados, como o SENHOR o havia mandado a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Também no mesmo tempo veio Josué e destruiu os anaquins dos montes, de Hebrom, de Debir, e de Anabe, e de todos os montes de Judá, e de todos os montes de Israel: Josué os destruiu a eles e a suas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nenhum dos anaquins restou na terra dos filhos de Israel; somente restaram em Gaza, em Gate, e em Asdode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Tomou, pois, Josué toda a terra, conforme todo o que o SENHOR havia dito a Moisés; e entregou-a Josué aos israelitas por herança, conforme suas repartições de suas tribos: e a terra repousou de guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Estes são os reis da terra que os filhos de Israel feriram, e cuja terra possuíram da outra parte do Jordão ao oriente, desde o ribeiro de Arnom até o monte Hermom, e toda a planície oriental:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Seom rei dos amorreus, que habitava em Hesbom, e senhoreava desde Aroer, que está à beira do ribeiro de Arnom, e desde em meio do ribeiro, e a metade de Gileade, até o ribeiro Jaboque, o termo dos filhos de Amom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'E desde a campina até o mar de Quinerete, ao oriente; e até o mar da planície, o mar Salgado, ao oriente, pelo caminho de Bete-Jesimote; e desde o sul debaixo das encostas do Pisga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'E os termos de Ogue rei de Basã, que havia restado dos refains, o qual habitava em Astarote e em Edrei,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'E senhoreava no monte de Hermom, e em Salcá, e em todo Basã até os termos de Gessuri e dos maacatitas, e a metade de Gileade, termo de Seom rei de Hesbom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'A estes feriram Moisés servo do SENHOR e os filhos de Israel; e Moisés servo do SENHOR deu aquela terra em possessão aos rubenitas, gaditas, e à meia tribo de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'E estes são os reis da terra que feriu Josué com os filhos de Israel, desta parte do Jordão ao ocidente, desde Baal-Gade na planície do Líbano até o monte de Halaque que sobe a Seir; a qual terra deu Josué em possessão às tribos de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Em montes e em vales, em planícies e em encostas, ao deserto e ao sul; os heteus, e os amorreus, e os cananeus, e os ferezeus, e os heveus, e os jebuseus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'O rei de Jericó, um: o rei de Ai, que está ao lado de Betel, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'O rei de Jerusalém, outro: o rei de Hebrom, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'O rei de Jarmute, outro: o rei de Laquis, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'O rei de Eglom, outro: o rei de Gezer, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'O rei de Debir, outro: o rei de Geder, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'O rei de Hormá, outro: o rei de Arade, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'O rei de Libna, outro: o rei de Adulão, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'O rei de Maquedá, outro: o rei de Betel, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'O rei de Tapua, outro: o rei de Héfer, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'O rei de Afeque, outro: o rei de Lasarom, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'O rei de Madom, outro: o rei de Hazor, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'O rei de Sinrom-Merom, outro: o rei de Acsafe, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'O rei de Taanaque, outro: o rei de Megido, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'O rei de Quedes, outro: o rei de Jocneão do Carmelo, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'O rei de Dor, da província de Dor, outro; o rei de nações em Gilgal, outro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'O rei de Tirsa, outro: trinta e um reis ao todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'E sendo Josué já velho, cheio de dias, o SENHOR lhe disse: Tu és já velho, de idade avançada, e resta ainda muita terra por possuir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Esta é a terra que resta; todos os termos dos filisteus, e todos os gessuritas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Desde Sior, que está diante do Egito, até o termo de Ecrom ao norte, considera-se dos cananeus: cinco províncias dos filisteus; os gazitas, asdoditas, asquelonitas, giteus, e ecronitas; e os heveus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Ao sul toda a terra dos cananeus, e Meara que é dos sidônios, até Afeque, até o termo dos amorreus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'E a terra dos gebalitas, e todo o Líbano até o oriente, desde Baal-Gade o pdo monte Hermom, até entrar em Hamate;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Todos os que habitam nas montanhas desde o Líbano até as águas quentes, todos os sidônios; eu os desarraigarei diante dos filhos de Israel: somente repartirás tu por sorte o país aos israelitas por herança, como te mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Reparte, pois, tu agora esta terra em herança às nove tribos, e à meia tribo de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Porque a outra meia recebeu sua herança com os rubenitas e gaditas, a qual lhes deu Moisés da outra parte do Jordão ao oriente, segundo que se a deu Moisés servo do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Desde Aroer, que está à beira do ribeiro de Arnom, e a cidade que está em meio do ribeiro, e toda a campina de Medeba, até Dibom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'E todas as cidades de Seom rei dos amorreus, o qual reinou em Hesbom, até os termos dos filhos de Amom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'E Gileade, e os termos dos gessuritas, e dos maacatitas, e todo o monte de Hermom, e toda a terra de Basã até Salcá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Todo o reino de Ogue em Basã, o qual reinou em Astarote e Edrei, o qual havia ficados do resto dos refains; pois Moisés os feriu, e expulsou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Mas aos dos gessuritas e dos maacatitas não expulsaram os filhos de Israel; antes Gessur e Maacate habitaram entre os israelitas até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Porém à tribo de Levi não deu herança: os sacrifícios do SENHOR Deus de Israel são sua herança, como ele lhes havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Deu, pois, Moisés à tribo dos filhos de Rúben conforme suas famílias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'E foi o termo deles desde Aroer, que está à beira do ribeiro de Arnom, e a cidade que está em meio do ribeiro, e toda a campina, até Medeba;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbom, com todas as suas vilas que estão na planície; Dibom, e Bamote-Baal, e Bete-Baal-Meom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'E Jaza, e Quedemote, e Mefaate,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'E Quiriataim, e Sibma, e Zerete-Saar no monte do vale;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'E Bete-Peor, e as encostas de Pisga, e Bete-Jesimote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'E todas as cidades da campina, e todo o reino de Seom rei dos amorreus, que reinou em Hesbom, ao qual feriu Moisés, e aos príncipes de Midiã, Evi, Requém, e Sur, e Hur, e Reba, príncipes de Seom que habitavam naquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Também mataram à espada os filhos de Israel a Balaão adivinho, filho de Beor, com os demais que mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'E foram os termos dos filhos de Rúben o Jordão com seu termo. Esta foi a herança dos filhos de Rúben conforme suas famílias, estas cidades com suas vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Deu também Moisés à tribo de Gade, aos filhos de Gade, conforme suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'E o termo deles foi Jazer, e todas as cidades de Gileade, e a metade da terra dos filhos de Amom até Aroer, que está diante de Rabá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'E desde Hesbom até Ramate-Mispa, e Betonim; e desde Maanaim até o termo de Debir:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'E a campina de Bete-Arã, e Bete-Ninra, e Sucote, e Zafom, resto do reino de Seom, rei em Hesbom: o Jordão e seu termo até a extremidade do mar de Quinerete da outra parte do Jordão ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Esta é a herança dos filhos de Gade, por suas famílias, estas cidades com suas vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Também deu Moisés herança à meia tribo de Manassés: e foi da meia tribo dos filhos de Manassés, conforme suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'O termo deles foi desde Maanaim, todo Basã, todo o reino de Ogue rei de Basã, e todas as aldeias de Jair que estão em Basã, sessenta povoações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Deram-se também a metade de Gileade, e Astarote, e Edrei, cidades do reino de Ogue em Basã, aos filhos de Maquir, filho de Manassés, à metade dos filhos de Maquir conforme suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Isto é o que Moisés repartiu em herança nas planícies de Moabe, da outra parte do Jordão de Jericó, ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Mas à tribo de Levi não deu Moisés herança: o SENHOR Deus de Israel é a herança deles como ele lhes havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Isto, pois, é o que os filhos de Israel tomaram por herança na terra de Canaã, o qual lhes repartiram Eleazar sacerdote, e Josué filho de Num, e os principais dos pais das tribos dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Por sorte deu-se a eles sua herança, como o SENHOR o havia mandado por Moisés, que desse às nove tribos e à meia tribo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Porque às duas tribos, e à meia tribo, lhes havia Moisés dado herança da outra parte do Jordão: mas aos levitas não deu herança entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Porque os filhos de José foram duas tribos, Manassés e Efraim: e não deram parte aos levitas na terra, mas sim cidades em que morassem, com seus campos para seus gados e rebanhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Da maneira que o SENHOR o havia mandado a Moisés, assim o fizeram os filhos de Israel na repartição da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'E os filhos de Judá vieram a Josué em Gilgal; e Calebe, filho de Jefoné quenezeu, lhe disse: Tu sabes o que o SENHOR disse a Moisés, homem de Deus, em Cades-Barneia, tocante a mim e a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Eu era de idade de quarenta anos, quando Moisés servo do SENHOR me enviou de Cades-Barneia a reconhecer a terra; e eu lhe mencionei o negócio como o tinha em meu coração:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Mas meus irmãos, os que haviam subido comigo, minguaram o coração do povo; porém eu cumpri seguindo ao SENHOR meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Então Moisés jurou, dizendo: Se a terra que pisou teu pé não for para ti, e para teus filhos em herança perpétua: porquanto cumpriste seguindo ao SENHOR meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Agora bem, o SENHOR me fez viver, como ele disse, estes quarenta e cinco anos, desde o tempo que o SENHOR falou estas palavras a Moisés, quando Israel andava pelo deserto: e agora, eis que sou hoje dia de oitenta e cinco anos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Porém ainda hoje estou tão forte como o dia que Moisés me enviou: qual era então minha força, tal é agora, para a guerra, e para sair e para entrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Dá-me, pois, agora este monte, do qual falou o SENHOR aquele dia; porque tu ouviste naquele dia que os anaquins estão ali, e grandes e fortes cidades. Talvez o SENHOR seja comigo, e os expulsarei como o SENHOR disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Josué então lhe abençoou, e deu a Calebe filho de Jefoné a Hebrom por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Portanto Hebrom foi de Calebe, filho de Jefoné quenezeu, em herança até hoje; porque cumpriu seguindo ao SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Mas Hebrom foi antes chamada Quiriate-Arba; foi Arba um homem grande entre os anaquins. E a terra teve repouso das guerras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'E foi a sorte da tribo dos filhos de Judá, por suas famílias, junto ao termo de Edom, do deserto de Zim ao sul, ao lado do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'E seu termo da parte do sul foi desde a costa do mar Salgado, desde a baía que está voltada ao sul;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'E saía até o sul à subida de Acrabim, passando até Zim; e subindo pelo sul até Cades-Barneia, passava a Hebrom, e subindo por Adar dava volta a Carca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'De ali passava a Azmom, e saía ao ribeiro do Egito; e sai este termo ao ocidente. Este pois vos será o termo do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'O termo do oriente é o mar Salgado até o fim do Jordão. E o termo da parte do norte, desde a baía do mar, desde o fim do Jordão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'E sobe este termo por Bete-Hogla, e passa do norte a Bete-Arabá, e daqui sobe este termo à pedra de Boã, filho de Rúben.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'E torna a subir este termo a Debir desde o vale de Acor: e ao norte olha sobre Gilgal, que está diante da subida de Adumim, a qual está ao sul do ribeiro: e passa este termo às águas de En-Semes, e sai à fonte de Rogel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'E sobe este termo pelo vale do filho de Hinom ao lado dos jebuseus ao sul: esta é Jerusalém. Logo sobe este termo pelo cume do monte que está diante do vale de Hinom até o ocidente, o qual está ao fim do vale dos gigantes ao norte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'E rodeia este termo desde o cume do monte até a fonte das águas de Neftoa, e sai às cidades do monte de Efrom, rodeando logo o mesmo termo a Baalá, a qual é Quriate-Jearim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Depois torna este termo desde Baalá até o ocidente ao monte de Seir: e passa ao lado do monte de Jearim até o norte, esta é Quesalom, e desce a Bete-Semes, e passa a Timna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Sai logo este termo ao lado de Ecrom até o norte; e rodeia o mesmo termo a Sicrom, e passa pelo monte de Baalá, e sai a Jabneel: e sai este termo ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'O termo do ocidente é o mar grande. Este, pois, é o termo dos filhos de Judá em derredor, por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Mas a Calebe, filho de Jefoné, deu parte entre os filhos de Judá, conforme o mandamento do SENHOR a Josué: isto é, a Quiriate-Arba, do pai de Anaque, que é Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'E Calebe expulsou dali três filhos de Anaque, a Sesai, Aimã, e Talmai, filhos de Anaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'De aqui subiu aos que moravam em Debir: e o nome de Debir era antes Quiriate-Sefer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'E disse Calebe: Ao que ferir a Quiriate-Sefer, e a tomar, eu lhe darei a minha filha Acsa por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'E tomou-a Otniel, filho de Quenaz, irmão de Calebe; e ele lhe deu por mulher a sua filha Acsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'E aconteceu que quando a levava, ele a persuadiu que pedisse a seu pai terras para lavrar. Ela então desceu do asno. E Calebe lhe disse: Que tens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'E ela respondeu: Dá-me bênção; pois me deste terra de secura, dá-me também fontes de águas. Ele então lhe deu as fontes de acima, e as de abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Esta, pois é a herança das tribos dos filhos de Judá por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'E foram as cidades do termo da tribo dos filhos de Judá até o termo de Edom ao sul: Cabzeel, e Éder, e Jagur,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'E Quiná, e Dimona, e Adada,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'E Quedes, e Hazor, e Itnã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zife, e Telém, Bealote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'E Hazor-Hadata, e Queriote-Hezrom, que é Hazor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amã, e Sema, e Moladá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'E Hazar-Gada, e Hesmom, e Bete-Pelete,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'E Hazar-Sual, Berseba, e Biziotiá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baalá, e Iim, e Azém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'E Eltolade, e Quesil, e Hormá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'E Ziclague, e Madmana, Sansana,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'E Lebaote, Silim, e Aim, e Rimom; em todas vinte e nove cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Nas planícies, Estaol, e Zorá, e Asná,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'E Zanoa, e En-Ganim, Tapua, e Enã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jeremote, e Adulão, Socó, e Azeca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'E Saaraim, e Aditaim, e Gederá, e Gederotaim; catorze cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenã, e Hadasa, e Migdal-Gade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'E Dileã, e Mispá, e Jocteel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Laquis, e Bozcate, e Eglom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'E Cabom, e Laamás, e Quitilis,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'E Gederote, Bete-Dagom, e Naamá, e Maquedá; dezesseis cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, e Eter, e Asã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'E Iftá, e Asná, e Nezibe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'E Queila, e Aczibe, e Maressa; nove cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ecrom com suas vilas e suas aldeias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Desde Ecrom até o mar, todas as que estão à costa de Asdode com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdode com suas vilas e suas aldeias: Gaza com suas vilas e suas aldeias até o rio do Egito, e o grande mar com seus termos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'E nas montanhas, Samir, e Jatir, e Sucote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'E Dana, e Quiriate-Saná, que é Debir,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'E Anabe, e Estemo, e Anim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'E Gósen, e Holom, e Gilo; onze cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arabe, e Dumá, e Esã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'E Janim, e Bete-Tapua, e Afeca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'E Hunta, e Quiriate-Arba, que é Hebrom, e Zior; nove cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maom, Carmelo, e Zife, e Jutá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'E Jezreel, Jocdeão, e Zanoa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Caim, Gibeá, e Timna; dez cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halul, e Bete-Zur, e Gedor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'E Maarate, e Bete-Anote, e Eltecom; seis cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Quriate-Baal, que é Quriate-Jearim, e Rabá; duas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'No deserto, Bete-Arabá, Midim, e Secacá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'E Nibsã, e a cidade do sal, e En-Gedi; seis cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Mas aos jebuseus que habitavam em Jerusalém, os filhos de Judá não os puderam desarraigar; antes restaram os jebuseus em Jerusalém com os filhos de Judá, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'E a porção dos filhos de José saiu desde o Jordão de Jericó até as águas de Jericó até o oriente, ao deserto que sobe de Jericó ao monte de Betel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'E de Betel sai a Luz, e passa ao termo dos arquitas em Atarote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'E torna a descer até o mar ao termo dos jafletitas, até o termo de Bete-Horom a de abaixo, e até Gezer; e sai ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Receberam, pois, herança os filhos de José, Manassés e Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'E foi o termo dos filhos de Efraim por suas famílias, foi o termo de sua herança à parte oriental, desde Atarote-Adar até Bete-Horom a de acima:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'E sai este termo ao mar, e a Micmetá ao norte, e dá volta este termo até o oriente a Taanate-Siló, e daqui passa ao oriente a Janoa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'E de Janoa desce a Atarote, e a Naarate, e cabe em Jericó, e sai ao Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'E de Tapua torna este termo até o mar ao ribeiro de Caná, e sai ao mar. Esta é a herança da tribo dos filhos de Efraim por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'houve também cidades que se apartaram para os filhos de Efraim em meio da herança dos filhos de Manassés, todas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'E não expulsaram aos cananeus que habitavam em Gezer; antes restaram os cananeus em meio de Efraim, até hoje, e foram tributários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'E teve também porção a tribo de Manassés, porque foi primogênito de José. Maquir, primogênito de Manassés, e pai de Gileade, o qual foi homem de guerra, teve a Gileade e a Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Tiveram também porção os outros filhos de Manassés conforme suas famílias: os filhos de Abiezer, e os filhos de Helebe, e os filhos de Asriel, e os filhos de Siquém, e os filhos de Héfer, e os filhos de Semida; estes foram os filhos homens de Manassés, filho de José, por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Porém Zelofeade, filho de Héfer, filho de Gileade, filho de Maquir, filho de Manassés, não teve filhos, somente filhas, os nomes das quais são estes: Maalá, Noa, Hogla, Milca, e Tirza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Estas vieram diante de Eleazar sacerdote, e de Josué filho de Num, e dos príncipes, e disseram: O SENHOR mandou a Moisés que nos desse herança entre nossos irmãos. E ele lhes deu herança entre os irmãos do pai delas, conforme o dito do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'E caíram a Manassés dez porções a mais da terra de Gileade e de Basã, que está da outra parte do Jordão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Porque as filhas de Manassés possuíram herança entre seus filhos: e a terra de Gileade foi dos outros filhos de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'E foi o termo de Manassés desde Aser até Micmetá, a qual está diante de Siquém; e vai este termo à direita, aos que habitam em Tapua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'E a terra de Tapua foi de Manassés; mas Tapua, que está junto ao termo de Manassés, é dos filhos de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'E desce este termo ao ribeiro de Caná, até o sul do ribeiro. Estas cidades de Efraim estão entre as cidades de Manassés: e o termo de Manassés é desde o norte do mesmo ribeiro, e suas saídas são ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Efraim ao sul, e Manassés ao norte, e o mar é seu termo: e encontram-se com Aser à parte do norte, e com Issacar ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Teve também Manassés em Issacar e em Aser a Bete-Seã e suas aldeias, e Ibleão e suas aldeias, e os moradores de Dor e suas aldeias, e os moradores de En-Dor e suas aldeias, e os moradores de Taanaque e suas aldeias, e os moradores de Megido e suas aldeias: três províncias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Mas os filhos de Manassés não puderam lançar aos daquelas cidades; antes os cananeus quis habitar na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Porém quando os filhos de Israel tomaram forças, fizeram tributários aos cananeus, mas não o expulsaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'E os filhos de José falaram a Josué, dizendo: Por que me deste por herança uma só porção e uma só parte, sendo eu um povo tão grande e que o SENHOR me abençoou assim até agora?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'E Josué lhes respondeu: Se és povo tão grande, sobe tu ao monte, e corta para ti ali na terra do ferezeus e dos gigantes, pois que o monte de Efraim é estreito para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'E os filhos de José disseram: Não nos bastará a nós este monte: e todos os cananeus que habitam a terra da campina, têm carros de ferro; os que estão em Bete-Seã e em suas aldeias, e os que estão no vale de Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Então Josué respondeu à casa de José, a Efraim e Manassés, dizendo: Tu és grande povo, e tens grande força; não terás uma só porção;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Mas aquele monte será teu; porque é bosque, e tu o cortarás, e serão teus seus termos: porque tu expulsarás aos cananeus, ainda que tenham carros de ferro, e ainda que sejam fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'E toda a congregação dos filhos de Israel se juntou em Siló, e assentaram ali o tabernáculo do testemunho, depois que a terra lhes foi sujeita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Mas haviam restado nos filhos de Israel sete tribos, às quais ainda não haviam repartido sua possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'E Josué disse aos filhos de Israel: Até quando sereis negligentes para vir a possuir a terra que vos deu o SENHOR o Deus de vossos pais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Assinalai três homens de cada tribo, para que eu os envie, e que eles se levantem, e percorram a terra, e a descrevam conforme suas propriedades, e se voltem a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'E a dividirão em sete partes: e Judá estará em seu termo ao sul, e os da casa de José estarão no seu ao norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Vós, pois, demarcareis a terra em sete partes, e me trareis a descrição aqui, e eu vos lançarei as sortes aqui diante do SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Porém os levitas nenhuma parte têm entre vós; porque o sacerdócio do SENHOR é a herança deles: Gade também e Rúben, e a meia tribo de Manassés, já receberam sua herança da outra parte do Jordão ao oriente, a qual lhes deu Moisés servo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Levantando-se, pois, aqueles homens, foram: e mandou Josué aos que iam para demarcar a terra, dizendo-lhes: Ide, percorrei a terra, e demarcai-a, e voltai a mim, para que eu vos lance as sortes aqui diante do SENHOR em Siló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Foram, pois, aqueles homens e passaram pela terra, demarcando-a por cidades em sete partes em um livro, e voltaram a Josué ao acampamento em Siló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'E Josué lhes lançou as sortes diante do SENHOR em Siló; e ali repartiu Josué a terra aos filhos de Israel por suas porções.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'E tirou-se a sorte da tribo dos filhos de Benjamim por suas famílias: e saiu o termo de sua porção entre os filhos de Judá e os filhos de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'E foi o termo deles ao lado do norte desde o Jordão: e sobe aquele termo ao lado de Jericó ao norte; sobe depois ao monte até o ocidente, e vem a sair ao deserto de Bete-Áven:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'E dali passa aquele termo a Luz, pelo lado de Luz (esta é Betel) até o sul. E desce este termo de Atarote-Adar ao monte que está ao sul de Bete-Horom a de abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'E torna este termo, e dá volta ao lado do mar, ao sul até o monte que está diante de Bete-Horom ao sul; e vem a sair a Quriate-Baal, que é Quriate-Jearim, cidade dos filhos de Judá. Este é o lado do ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'E o lado do sul é desde a extremidade de Quriate-Jearim, e sai o termo ao ocidente, e sai à fonte das águas de Neftoa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'E desce este termo ao fim do monte que está diante do vale do filho de Hinom, que está na campina dos gigantes até o norte: desce logo ao vale de Hinom, ao lado dos jebuseus ao sul, e dali desce à fonte de Rogel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'E do norte torna e sai a En-Semes, e dali sai a Gelilote, que está diante da subida de Adumim, e descia à pedra de Boã, filho de Rúben:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'E passa ao lado que está diante da campina do norte, e desce às planícies:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'E torna a passar este termo pelo lado de Bete-Hogla até o norte, e vem a sair o termo à baía do mar Salgado ao norte, ao fim do Jordão ao sul. Este é o termo do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'E o Jordão acaba este termo ao lado do oriente. Esta é a herança dos filhos de Benjamim por seus termos ao redor, conforme suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'As cidades da tribo dos filhos de Benjamim, por suas famílias, foram Jericó, Bete-Hogla, e Emeque-Queziz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bete-Arabá, Zemaraim, e Betel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'E Avim, e Pará, e Ofra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'E Quefar-Amonai, Ofni, e Geba; doze cidades com suas aldeias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeão, Ramá, Beerote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'E Mispá, Quefira, e Moza,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Requém, Irpeel e Tarala,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'E Zela, Elefe, Jebus, que é Jerusalém, Gibeá, e Quiriate; catorze cidades com suas aldeias. Esta é a herança dos filhos de Benjamim, conforme suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'A segunda porção saiu para Simeão, pela tribo dos filhos de Simeão conforme suas famílias; e sua herança foi entre a herança dos filhos de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'E tiveram em sua herdade a Berseba, Seba, e Moladá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hazar-Sual, Balá, e Azem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolade, Betul, e Hormá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ziclague, Bete-Marcabote, e Hazar-Susa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Bete-Lebaote, e Saruém; treze cidades com suas aldeias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Aim, Rimom, Eter, e Asã; quatro cidades com suas aldeias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'E todas as aldeias que estavam ao redor destas cidades até Baalate-Beer, que é Ramá do sul. Esta é a herança da tribo dos filhos de Simeão, segundo suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Da porção dos filhos de Judá foi tirada a herança dos filhos de Simeão; porquanto a parte dos filhos de Judá era escessiva para eles: assim que os filhos de Simeão tiveram sua herança em meio da deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'A terceira porção saiu pelos filhos de Zebulom conforme suas famílias: e o termo de sua herança foi até Saride.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'E seu termo sobe até o mar e até Maralá, e chega até Dabesete, e dali chega ao ribeiro que está diante de Jocneão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'E tornando de Saride até oriente, o oriente ao termo de Quislote-Tabor, sai a Daberate, e sobe a Jafia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'E passando dali até o lado oriental a Gate-Hefer e a Ete-Cazim, sai a Rimom rodeando a Neá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'E daqui torna este termo ao norte a Hanatom, vindo a sair ao vale de Iftá-El;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'E engloba Catate, e Naalal, e Sinrom, e Idala, e Belém; doze cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Esta é a herdade dos filhos de Zebulom por suas famílias; estas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'A quarta porção saiu para Issacar, pelos filhos de Issacar conforme suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'E foi seu termo Jezreel, e Quesulote, e Suném,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'E Hafaraim, e Siom, e Anaarate,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'E Rabite, e Quisiom, e Ebes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'E Remete, e En-Ganim, e En-Hadá e Bete-Pazez;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'E chega este termo até Tabor, e Saazima, e Bete-Semes; e sai seu termo ao Jordão: dezesseis cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Esta é a herança da tribo dos filhos de Issacar conforme suas famílias; estas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'E saiu a quinta porção pela tribo dos filhos de Aser por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'E seu termo foi Helcate, e Hali, e Béten, e Acsafe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'E Alameleque, e Amade, e Misal; e chega até Carmelo ao ocidente, e a Sior-Libnate;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'E tornando do oriente a Bete-Dagom, chega a Zebulom, e ao vale de Iftá-El ao norte, a Bete-Emeque, e a Neiel, e sai a Cabul à esquerda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'E engloba a Hebrom, e Reobe, e Hamom, e Caná, até a grande Sidom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'E torna dali este termo a Hormá, e até a forte cidade de Tiro, e torna este termo a Hosa, e sai ao mar desde o território de Aczibe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Engloba também Umá, e Afeque, e Reobe: vinte e duas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Esta é a herança da tribo dos filhos de Aser por suas famílias; estas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'A sexta porção saiu para os filhos de Naftali, pelos filhos de Naftali conforme suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'E foi seu termo desde Helefe, e Alom-Zaanim, e Adami-Neguebe, e Jabneel, até Lacum; e sai ao Jordão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'E tornando dali este termo até o ocidente a Aznote-Tabor, passa dali a Hucoque, e chega até Zebulom ao sul, e ao ocidente confina com Aser, e com Judá ao Jordão até o oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'E as cidades fortes são Zidim, Zer, e Hamate, Racate, e Quinerete,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'E Adama, e Ramá, e Hazor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'E Quedes, e Edrei, e En-Hazor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'E Irom, e Migdal-Ele, e Horém, e Bete-Anate, e Bete-Semes: dezenove cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Esta é a herança da tribo dos filhos de Naftali por suas famílias; estas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'A sétima porção saiu para a tribo dos filhos de Dã por suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'E foi o termo de sua herança, Zorá, e Estaol, e Ir-Semes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'E Saalabim, e Aijalom, e Itla,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'E Elom, e Timna, e Ecrom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'E Elteque, Gibetom, e Baalate,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'E Jeúde, e Bene-Beraque, e Gate-Rimom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'E Me-Jarcom, e Racom, com o termo que está diante de Jope.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'E faltou-lhes termo aos filhos de Dã; e subiram os filhos de Dã e combateram a Lesém, e tomando-a feriram-na a fio de espada, e a possuíram, e habitaram nela; e chamaram a Lesém, Dã, do nome de Dã seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Esta é a herança da tribo dos filhos de Dã conforme suas famílias; estas cidades com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'E depois que acabaram de repartir a terra em herança por seus termos, deram os filhos de Israel herança a Josué filho de Num em meio deles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Segundo a palavra do SENHOR, lhe deram a cidade que ele pediu, Timnate-Heres, no monte de Efraim; e ele reedificou a cidade, e habitou nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Estas são as propriedades que Eleazar sacerdote, e Josué filho de Num, e os principais dos pais, entregaram por sorte em possessão às tribos dos filhos de Israel em Siló diante do SENHOR, à entrada do tabernáculo do testemunho; e acabaram de repartir a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'E falou o SENHOR a Josué, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Fala aos filhos de Israel, dizendo: Assinalai-vos as cidades de refúgio, das quais eu vos falei por Moisés;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Para que se acolha ali o homicida que matar a alguém por acidente e não de propósito; que vos sejam por refúgio do vingador do morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'E o que se refugiar a alguma daquelas cidades se apresentará à porta da cidade, e dirá suas causas, ouvindo-o os anciãos daquela cidade: e eles o receberão consigo dentro da cidade, e lhe darão lugar que habite com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'E quando o vingador do morto o seguir, não entregarão em sua mão ao homicida, porquanto feriu a seu próximo por acidente, nem teve com ele antes inimizade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'E ficará naquela cidade até que compareça em juízo diante do ajuntamento, até a morte do grande sacerdote que for naquele tempo: então o homicida voltará e virá à sua cidade e à sua casa e à cidade de onde fugiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Então assinalaram a Quedes na Galileia, no monte de Naftali, e a Siquém no monte de Efraim, e a Quiriate-Arba, que é Hebrom, no monte de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'E da outra parte do Jordão de Jericó, ao oriente, assinalaram a Bezer no deserto, na planície da tribo de Rúben, e a Ramote em Gileade da tribo de Gade, e a Golã em Basã da tribo de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Estas foram as cidades assinaladas para todos os filhos de Israel, e para o estrangeiro que morasse entre eles, para que se acolhesse a elas qualquer um que ferisse pessoa por acidente, e não morresse por meio do vingador do morto, até que comparecesse diante do ajuntamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'E os principais dos pais dos levitas vieram a Eleazar sacerdote, e a Josué filho de Num, e aos principais dos pais das tribos dos filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'E falaram-lhes em Siló na terra de Canaã, dizendo: O SENHOR mandou por Moisés que nos fossem dadas vilas para habitar, com seus campos para nossos animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Então os filhos de Israel deram aos levitas de suas possessões, conforme a palavra do SENHOR, estas vilas com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'E saiu a sorte para as famílias dos coatitas; e foram dadas por porção aos filhos de Arão sacerdote, que eram dos levitas, pela tribo de Judá, pela de Simeão e pela de Benjamim, treze vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'E aos outros filhos de Coate se deram por porção dez vilas das famílias da tribo de Efraim, e da tribo de Dã, e da meia tribo de Manassés;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'E aos filhos de Gérson, pelas famílias da tribo de Issacar, e da tribo de Aser, e da tribo de Naftali, e da meia tribo de Manassés em Basã, foram dadas por porção treze vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Aos filhos de Merari por suas famílias se deram doze vilas pela tribo de Rúben, e pela tribo de Gade, e pela tribo de Zebulom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'E assim deram por sorte os filhos de Israel aos levitas estas vilas com seus campos, como o SENHOR o havia mandado por Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'E da tribo dos filhos de Judá, e da tribo dos filhos de Simeão deram estas vilas que foram nomeadas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'E a primeira porção foi dos filhos de Arão, da família de Coate, dos filhos de Levi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Aos quais deram Quiriate-Arba, do pai de Anaque, a qual é Hebrom, no monte de Judá, com seus campos em seus entornos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Mas o campo desta cidade e suas aldeias deram a Calebe filho de Jefoné, por sua possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'E aos filhos de Arão, o sacerdote, deram a cidade de refúgio para os homicidas, a Hebrom com seus campos; e a Libna com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'E a Jatir com seus campos, e a Estemoa com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'A Holom com seus campos, e a Debir com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'A Aim com seus campos, a Jutá com seus campos, e a Bete-Semes com seus campos; nove vilas destas duas tribos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'E da tribo de Benjamim, a Gibeom com seus campos, a Geba com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'A Anatote com seus campos, a Almom com seus campos: quatro vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Todas as vilas dos sacerdotes, filhos de Arão, são treze com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Mas as famílias dos filhos de Coate, levitas, os que restavam dos filhos de Coate, receberam por porção vilas da tribo de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'E deram-lhes a Siquém, vila de refúgio para os homicidas, com seus campos, no monte de Efraim; e a Gezer com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'E a Quibzaim com seus campos, e a Bete-Horom com seus campos: quatro vilas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'E da tribo de Dã a Elteque com seus campos, a Gibetom com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'A Aijalom com seus campos, a Gate-Rimom com seus campos: quatro vilas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'E da meia tribo de Manassés, a Taanaque com seus campos, e a Gate-Rimom com seus campos: duas vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Todas as vilas para o resto das famílias dos filhos de Coate foram dez com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Aos filhos de Gérson das famílias dos levitas, deram a vila de refúgio para os homicidas, da meia tribo de Manassés: a Golã em Basã com seus campos, e a Beesterá com seus campos: duas vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'E da tribo de Issacar, a Quisiom com seus campos, a Daberate com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'A Jarmute com seus campos, e a En-Ganim com seus campos: quatro vilas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'E da tribo de Aser, a Misal com seus campos, a Abdom com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'A Helcate com seus campos, e a Reobe com seus campos: quatro vilas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'E da tribo de Naftali, a vila de refúgio para os homicidas, a Quedes na Galileia com seus campos, a Hamote-Dor com seus campos, e a Cartã com seus campos: três vilas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Todas as vilas dos gersonitas por suas famílias foram treze vilas com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'E às famílias dos filhos de Merari, levitas que restavam, deu-se a eles da tribo de Zebulom, a Jocneão com seus campos, Cartá com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna com seus campos, Naalal com seus campos: quatro vilas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'E da tribo de Rúben, a Bezer com seus campos, a Jaza com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'A Quedemote com seus campos, e Mefaate com seus campos: quatro vilas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Da tribo de Gade, a vila de refúgio para os homicidas, Ramote em Gileade com seus campos, e Maanaim com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbom com seus campos, e Jazer com seus campos: quatro vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Todas as vilas dos filhos de Merari por suas famílias, que restavam das famílias dos levitas, foram por suas porções doze vilas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'E todas as vilas dos levitas em meio da possessão dos filhos de Israel, foram quarenta e oito vilas com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'E estas cidades estavam separadas a uma da outra cada qual com seus campos ao redor delas: o qual foi em todas estas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Assim deu o SENHOR a Israel toda a terra que havia jurado dar a seus pais; e possuíram-na, e habitaram nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'E o SENHOR lhes deu repouso ao redor, conforme todo o que havia jurado a seus pais: e nenhum de todos os inimigos lhes parou diante, mas sim que o SENHOR entregou em suas mãos a todos os seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Não faltou palavra de todas as boas coisas que o SENHOR falou à casa de Israel; tudo se cumpriu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Então Josué chamou aos rubenitas e aos gaditas, e à meia tribo de Manassés,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'E disse-lhes: Vós guardastes tudo o que Moisés servo do SENHOR vos mandou, e obedecestes à minha voz ao todo o que vos mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Não deixastes a vossos irmãos nestes muitos dias até hoje, antes guardastes a observância dos mandamentos do SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Agora, pois, que o SENHOR vosso Deus deu repouso a vossos irmãos, como se o havia prometido, voltai, e voltai a vossas tendas, à terra de vossas possessões, que Moisés servo do SENHOR vos deu da outra parte do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Somente que com diligência cuideis de pôr por obra o mandamento e a lei, que Moisés servo do SENHOR vos intimou: que ameis ao SENHOR vosso Deus, e andeis em todos os seus caminhos; que guardeis seus mandamentos, e vos achegueis a ele, e lhe sirvais de todo o vosso coração e de toda a vossa alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'E abençoando-os Josué, os enviou: e foram-se a suas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Também à meia tribo de Manassés havia dado Moisés possessão em Basã; mas à outra meia deu Josué herança entre seus irmãos da outra parte do Jordão ao ocidente: e também a estes enviou Josué a suas tendas, depois de havê-los abençoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'E falou-lhes, dizendo: Voltai-vos a vossas tendas com grandes riquezas, e com grande quantidade de gado, com prata, e com ouro, e bronze, e muitas vestes: reparti com vossos irmãos o despojo de vossos inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'E os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, se voltaram, e partiram-se dos filhos de Israel, de Siló, que está na terra de Canaã, para ir à terra de Gileade, à terra de suas possessões, da qual eram possuidores, segundo a palavra do SENHOR por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'E chegando aos termos do Jordão, que está na terra de Canaã, os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, edificaram ali um altar junto ao Jordão, um altar de grande aparência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'E os filhos de Israel ouviram dizer como os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, haviam edificado um altar diante da terra de Canaã, nos termos do Jordão, à passagem dos filhos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'O qual quando os filhos de Israel ouviram, juntou-se toda a congregação dos filhos de Israel em Siló, para subir a lutar contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'E enviaram os filhos de Israel aos filhos de Rúben e aos filhos de Gade e à meia tribo de Manassés na terra de Gileade, a Fineias filho de Eleazar sacerdote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'E a dez príncipes com ele; um príncipe de cada casa paterna de todas as tribos de Israel, cada um dos quais era chefe de família de seus pais na multidão de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Os quais vieram aos filhos de Rúben e aos filhos de Gade, e à meia tribo de Manassés, na terra de Gileade; e falaram-lhes, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Toda a congregação do SENHOR diz assim: Que transgressão é esta com que cometestes contra o Deus de Israel, deixando hoje de perseguir ao SENHOR, edificando para vós altar para ser hoje rebeldes contra o SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Foi-nos pouca a maldade de Peor, da qual não estamos ainda limpos até hoje, pela qual foi a mortandade na congregação do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'E vós vos desviais hoje de perseguir ao SENHOR; mas será que vós vos rebelareis hoje contra o SENHOR, e amanhã se irará ele contra toda a congregação de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Que se vos parece que a terra de vossa possessão é imunda, passai-vos à terra da possessão do SENHOR, na qual está o tabernáculo do SENHOR, e tomai possessão entre nós; mas não vos rebeleis contra o SENHOR, nem vos rebeleis contra nós, edificando para vós um altar diferente do altar do SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Não cometeu Acã, filho de zerá, transgressão no anátema, e veio ira sobre toda a congregação de Israel? E aquele homem não pereceu sozinho em sua iniquidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Então os filhos de Rúben e os filhos de Gade, e a meia tribo de Manassés, responderam e disseram aos principais da multidão de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'O Deus dos deuses, o SENHOR, o Deus dos deuses, o SENHOR, ele sabe, e saberá Israel: se por rebelião ou por transgressão contra o SENHOR (não nos salves hoje,)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Edificamos para nós altar para deixarmos de seguir o SENHOR, ou para sacrificar holocausto ou presente, ou para fazer sobre ele sacrifícios pacíficos, o mesmo o SENHOR nos demande isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'E se não o fizemos por temor disto, dizendo: Amanhã vossos filhos dirão a nossos filhos: Que tendes vós com o SENHOR o Deus de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'O SENHOR pôs por termo o Jordão entre nós e vós, ó filhos de Rúben e filhos de Gade; não tendes vós parte no SENHOR: e assim vossos filhos farão que nossos filhos não temam ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Por isto dissemos: Façamos agora para edificar-nos um altar, não para holocausto nem para sacrifício,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Mas sim para que seja um testemunho entre nós e vós, e entre os que virão depois de nós, de que podemos fazer o serviço do SENHOR diante dele com nossos holocaustos, com nossos sacrifícios, e com nossos pacíficos; e não digam amanhã vossos filhos aos nossos: Vós não tendes parte com o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Nós, pois, dissemos: Se acontecer que tal digam a nós, ou a nossas gerações no porvir, então responderemos: Olhai a réplica do altar do SENHOR, o qual fizeram nossos pais, não para holocaustos ou sacrifícios, mas sim para que fosse testemunho entre nós e vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Nunca tal aconteça que nos rebelemos contra o SENHOR, ou que nos apartemos hoje de seguir ao SENHOR, edificando altar para holocaustos, para presente, ou para sacrifício, a mais do altar do SENHOR nosso Deus que está diante de seu tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'E ouvindo Fineias o sacerdote e os príncipes da congregação, e os chefes da multidão de Israel que com ele estavam, as palavras que falaram os filhos de Rúben e os filhos de Gade e os filhos de Manassés, satisfizeram-se com isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'E disse Fineias filho do sacerdote Eleazar, aos filhos de Rúben, aos filhos de Gade, e aos filhos de Manassés: Hoje temos entendido que o SENHOR está entre nós, pois que não intentastes esta traição contra o SENHOR. Agora livrastes aos filhos d');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'E Fineias filho do sacerdote Eleazar, e os príncipes, voltaram da presença dos filhos de Rúben, e da presença dos filhos de Gade, da terra de Gileade à terra de Canaã, aos filhos de Israel: aos quais deram a resposta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'E o negócio pareceu bem aos filhos de Israel, e bendisseram a Deus os filhos de Israel; e não falaram mais de subir contra eles em guerra, para destruir a terra em que habitavam os filhos de Rúben e os filhos de Gade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'E os filhos de Rúben e os filhos de Gade puseram por nome ao altar Ede; porque é testemunho entre nós que o SENHOR é Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'E aconteceu, passados muitos dias depois que o SENHOR deu repouso a Israel de todos os seus inimigos ao redor, que Josué, sendo velho, e cheio de dias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Chamou a todo Israel, a seus anciãos, a seus príncipes, a seus juízes e a seus oficiais, e disse-lhes: Eu sou já velho e cheio de dias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'E vós vistes tudo o que o SENHOR vosso Deus fez com todas estas nações em vossa presença; porque o SENHOR vosso Deus lutou por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Eis que vos reparti por sorteio, em herança para vossas tribos, estas nações, tanto as destruídas como as que ficam, desde o Jordão até o grande mar até onde o sol se põe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'E o SENHOR vosso Deus as expulsará de diante de vós, e as lançará de vossa presença: e vós possuireis suas terras, como o SENHOR vosso Deus vos disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Esforçai-vos, pois, muito a guardar e fazer tudo o que está escrito no livro da lei de Moisés, sem apartar-vos dele nem à direita nem à esquerda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Que quando entrardes a estas nações que restaram convosco, não façais menção nem jureis pelo nome de seus deuses, nem os sirvais, nem vos inclineis a eles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Mas ao SENHOR vosso Deus vos achegareis, como fizestes até hoje;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Pois o SENHOR expulsou diante de vós grandes e fortes nações, e até hoje ninguém há podido resistir diante de vosso rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Um homem de vós perseguirá a mil: porque o SENHOR vosso Deus luta por vós, como ele vos disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Portanto, cuidai muito por vossas almas, que ameis ao SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Porque se vos apartardes, e vos achegardes ao que resta daquelas nações que restaram convosco, e se estabelecerdes com elas matrimônios, e entrardes a elas, e elas a vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Sabei que o SENHOR vosso Deus não expulsará mais estas nações diante de vós; antes vos serão por laço, e por tropeço, e por açoite para vossos lados, e por espinhos para vossos olhos, até que pereçais desta boa terra que o SENHOR vosso Deus vos deu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'E eis que eu estou para entrar hoje pelo caminho de toda a terra: reconhecei, pois, com todo o vosso coração e com toda vossa alma, que não se perdeu uma palavra de todas a boas palavras que o SENHOR vosso Deus disse de vós; todas vieram até vós, nenhuma delas se perdeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Mas será, que quando veio sobre vós toda palavra boa que o SENHOR vosso Deus vos havia dito, assim também o SENHOR trará sobre vós toda palavra má, até destruir-vos de sobre a boa terra que o SENHOR vosso Deus vos deu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Quando transgredirdes o pacto do SENHOR vosso Deus que ele vos mandou, indo e honrando deuses alheios, e inclinando-vos a eles. E o furor do SENHOR se inflamará contra vós, e logo perecereis desta boa terra que ele vos deu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'E juntando Josué todas as tribos de Israel em Siquém, chamou aos anciãos de Israel, e a seus príncipes, a seus juízes, e a seus oficiais; e apresentaram-se diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'E disse Josué a todo o povo: Assim diz o SENHOR, Deus de Israel: Vossos pais habitaram antigamente da outra parte do rio, a saber, Terá, pai de Abraão e de Naor; e serviam a deuses estranhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'E eu tomei a vosso pai Abraão da outra parte do rio, e trouxe-o por toda a terra de Canaã, e aumentei sua geração, e dei-lhe a Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'E a Isaque dei a Jacó e a Esaú: e a Esaú dei o monte de Seir, que o possuísse: mas Jacó e seus filhos desceram ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'E eu enviei a Moisés e a Arão, e feri ao Egito, ao modo que o fiz em meio dele, e depois vos tirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'E tirei a vossos pais do Egito: e quando chegaram ao mar, os egípcios seguiram a vossos pais até o mar Vermelho com carros e cavalaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'E quando eles clamaram ao SENHOR, ele pôs escuridão entre vós e os egípcios, e fez vir sobre eles o mar, a qual os cobriu: e vossos olhos viram o que fiz em Egito. Depois estivestes muitos dias no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'E vos introduzi na terra dos amorreus, que habitavam da outra parte do Jordão, os quais lutaram contra vós; mas eu os entreguei em vossas mãos, e possuístes sua terra, e os destruí de diante de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'E levantou-se depois Balaque filho de Zipor, rei dos moabitas, e lutou contra Israel; e mandou chamar a Balaão filho de Beor, para que vos amaldiçoasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mas eu não quis escutar a Balaão, antes vos abençoou repetidamente, e vos livre de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'E passado o Jordão, viestes a Jericó; e os moradores de Jericó lutaram contra vós: os amorreus, perizeus, cananeus, heteus, girgaseus, heveus, e jebuseus: e eu os entreguei em vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'E enviei vespas diante de vós, os quais os expulsaram de diante de vós, a saber, aos dois reis dos amorreus; não com tua espada, nem com teu arco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'E vos dei a terra pela qual nada trabalhastes, e as cidades que não edificastes, nas quais morais; e das vinhas e olivais que não plantastes, comeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Agora, pois, temei ao SENHOR, e servi-o com integridade e em verdade; e tirai do meio os deuses aos quais serviram vossos pais da outra parte do rio, e em Egito; e servi ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'E se mal vos parece servir ao SENHOR, escolhei hoje a quem sirvais; se aos deuses a os quais serviram vossos pais, quando estiveram da outra parte do rio, ou aos deuses dos amorreus em cuja terra habitais: que eu e minha casa serviremos ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Então o povo respondeu, e disse: Nunca tal aconteça que deixemos ao SENHOR para servir a outros deuses:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Porque o SENHOR nosso Deus é o que tirou a nós e a nossos pais da terra do Egito, da casa de escravidão; o qual diante de nossos olhos fez estas grandes sinais, e nos guardou por todo o caminho por onde andamos, e em todos os povos por entre os quais passamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'E o SENHOR expulsou de diante de nós a todos os povos, e aos amorreus que habitavam na terra: nós, pois, também serviremos ao SENHOR, porque ele é nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Então Josué disse ao povo: Não podereis servir ao SENHOR, porque ele é Deus santo, e Deus zeloso; não tolerará vossas rebeliões e vossos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Se deixardes ao SENHOR e servirdes a deuses alheios, se voltará, e vos maltratará, e vos consumirá, depois que vos fez bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'O povo então disse a Josué: Não, antes ao SENHOR serviremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'E Josué respondeu ao povo: Vós sois testemunhas contra vós mesmos, de que escolhestes para vós ao SENHOR para servir-lhe. E eles responderam: Testemunhas somos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Tirai, pois, agora os deuses alheios que estão entre vós, e inclinai vosso coração ao SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'E o povo respondeu a Josué: Ao SENHOR nosso Deus serviremos, e à sua voz obedeceremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Então Josué fez aliança com o povo o mesmo dia, e pôs-lhe ordenanças e leis em Siquém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'E escreveu Josué estas palavras no livro da lei de Deus; e tomando uma grande pedra, levantou-a ali debaixo de um carvalho que estava junto ao santuário do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'E disse Josué a todo o povo: Eis que esta pedra será entre nós por testemunha, a qual ouviu todas as palavras do SENHOR que ele falou conosco: será, pois, testemunha contra vós, para que não mintais contra vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'E enviou Josué ao povo, cada um à sua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'E depois destas coisas morreu Josué, filho de Num, servo do SENHOR sendo de cento e dez anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'E enterraram-no no termo de sua possessão em Timnate-Sera, que está no monte de Efraim, ao norte do monte de Gaás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'E serviu Israel ao SENHOR todo o tempo de Josué, e todo o tempo dos anciãos que viveram depois de Josué, e que sabiam todas as obras do SENHOR, que havia feito por Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'E enterraram em Siquém os ossos de José que os filhos de Israel haviam trazido do Egito, na parte do campo que Jacó comprou dos filhos de Hamor, pai de Siquém, por cem peças de prata; e foi em possessão aos filhos de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Também morreu Eleazar, filho de Arão; ao qual enterraram no morro de Fineias seu filho, que lhe foi dado no monte de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'E aconteceu depois da morte de Josué, que os filhos de Israel consultaram ao SENHOR, dizendo: Quem subirá por nós primeiro para lutar contra os cananeus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'E o SENHOR respondeu: Judá subirá; eis que eu entreguei a terra em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'E Judá disse a Simeão seu irmão: Sobe comigo à minha porção, e lutemos contra os cananeus, e eu também irei contigo à tua porção. E Simeão foi com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'E subiu Judá, e o SENHOR entregou em suas mãos aos cananeus e aos perizeus; e deles feriram em Bezeque dez mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'E acharam a Adoni-Bezeque em Bezeque, e lutaram contra ele: e feriram aos cananeus e aos perizeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Mas Adoni-Bezeque fugiu; e seguiram-no, e prenderam-no, e cortaram-lhe os polegares das mãos e dos pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Então disse Adoni-Bezeque: Setenta reis, cortados os polegares de suas mãos e de seus pés, colhiam as migalhas debaixo de minha mesa: como eu fiz, assim Deus me pagou. E meteram-no em Jerusalém, de onde morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'E combateram os filhos de Judá a Jerusalém, e a tomaram, e puseram à espada, e puseram a fogo a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Depois os filhos de Judá desceram para lutar contra os cananeus que habitavam nas montanhas, e ao sul, e nas planícies.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'E partiu Judá contra os cananeus que habitavam em Hebrom, a qual se chamava antes Quiriate-Arba; e feriram a Sesai, e a Aimã, e a Talmai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'E dali foi aos que habitavam em Debir, que antes se chamava Quiriate-Sefer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'E disse Calebe: O que ferir a Quiriate-Sefer, e a tomar, eu lhe darei a Acsa minha filha por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'E tomou-a Otniel filho de Quenaz, irmão menor de Calebe: e ele lhe deu a Acsa sua filha por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'E quando a levavam, persuadiu-lhe que pedisse a seu pai um campo. E ela desceu do asno, e Calebe lhe disse: Que tens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Ela então lhe respondeu: Dá-me uma bênção: pois me deste terra de secura, que me dês também fontes de águas. Então Calebe lhe deu as fontes de acima e as fontes de abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'E os filhos de queneu, sogro de Moisés, subiram da cidade das palmeiras com os filhos de Judá ao deserto de Judá, que está ao sul de Arade: e foram e habitaram com o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'E foi Judá ao seu irmão Simeão, e feriram aos cananeus que habitavam em Zefate, e assolaram-na: e puseram por nome à cidade, Hormá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Tomou também Judá a Gaza com seu termo, e a Asquelom com seu termo, e a Ecrom com seu termo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'E o SENHOR foi com Judá, e expulsaram os das montanhas; mas não puderam expulsar os que habitavam nas planícies, os quais tinham carros de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'E deram Hebrom a Calebe, como Moisés havia dito: e ele expulsou dali três filhos de Anaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Mas aos jebuseus que habitavam em Jerusalém, não expulsaram os filhos de Benjamim, e tanto os jebuseus habitaram com os filhos de Benjamim em Jerusalém até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Também os da casa de José subiram a Betel; e o SENHOR foi com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'E os da casa de José puseram espias em Betel, a qual cidade antes se chamava Luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'E os que espiavam viram um homem que saía da cidade, e disseram-lhe: Mostra-nos agora a entrada da cidade, e faremos contigo misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'E ele lhes mostrou a entrada à cidade, e feriram-na a fio de espada; mas deixaram a aquele homem com toda sua família.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'E fosse o homem à terra dos heteus, e edificou uma cidade, à qual chamou Luz; e este é seu nome até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Tampouco Manassés expulsou os de Bete-Seã, nem aos de suas aldeias, nem aos de Taanaque e suas aldeias, nem os de Dor e suas aldeias, nem os habitantes de Ibleão e suas aldeias, nem aos que habitavam em Megido e em suas aldeias; mas os cananeus quiseram habitar nessa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Porém quando Israel tomou forças fez aos cananeus tributários, mas não o expulsou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Também Efraim não expulsou os cananeus que habitavam em Gezer; antes habitaram os cananeus em meio deles em Gezer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Também Zebulom não expulsou aos que habitavam em Quitrom e aos que habitavam em Naalol; mas os cananeus habitaram no meio dele, e lhe foram tributários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Também Aser não expulsou aos que habitavam em Aco, e aos que habitavam em Sidom, Alabe, Aczibe, Helba, Afeque, e em Reobe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'em vez disso, Aser morou entre os cananeus que habitavam na terra; pois não os expulsou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Também Naftali não expulsou os que habitavam em Bete-Semes e os que habitavam em Bete-Anate, mas morou entre os cananeus que habitavam na terra; todavia, os moradores de Bete-Semes e os moradores de Bete-Anate foram-lhe tributários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Os amorreus pressionaram os filhos de Dã até as montanhas; pois não os permitiram descer ao vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'E os amorreus quiseram habitar no monte de Heres, em Aijalom e em Saalbim; mas a mão da tribo de José foi mais forte, e os fizeram tributários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'E o limite dos amorreus foi desde a subida de Acrabim, desde a rocha, e daí acima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'E o anjo do SENHOR subiu de Gilgal a Boquim, e disse: “Eu vos tirei do Egito, e vos introduzi na terra da qual havia jurado a vossos pais; e disse: ‘Não invalidarei jamais meu pacto convosco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'contanto que vós não façais aliança com os moradores desta terra, cujos altares deveis derrubar’; mas vós não atendestes à minha voz: por que fizestes isto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Por isso eu também disse: ‘Não os expulsarei de diante de vós, mas serão vossos inimigos, e seus deuses vos serão uma armadilha’”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'E quando o anjo do SENHOR falou estas palavras a todos os filhos de Israel, o povo chorou em alta voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'E chamaram por nome aquele lugar Boquim: e sacrificaram ali ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Porque já Josué havia despedido ao povo, e os filhos de Israel se haviam ido cada um à sua herança para possuí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'E o povo havia servido ao SENHOR todo aquele tempo de Josué, e todo aquele tempo dos anciãos que viveram longos dias depois de Josué, os quais viram todas as grandes obras do SENHOR, que o havia feito por Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'E morreu Josué filho de Num, servo do SENHOR, sendo de cento e dez anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'E enterraram-no no termo de sua herança em Timnate-Heres, no monte de Efraim, o norte do monte de Gaás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'E toda aquela geração foi também recolhida com seus pais. E levantou-se depois dela outra geração, que não conhecia o SENHOR, nem a obra que ele havia feito por Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'E os filhos de Israel fizeram o que era mal aos olhos do SENHOR, e serviram aos baalins;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'E abandonaram o SENHOR, o Deus de seus pais, que os havia tirado da terra do Egito, e seguiram outros deuses, os deuses dos povos que estavam em seus arredores, aos quais adoraram, e provocaram à ira ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Pois abandonaram o SENHOR, e adoraram a Baal e a Astarote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Então a fúria do SENHOR se acendeu contra Israel, e os entregou nas mãos de saqueadores que os despojaram, e os vendeu nas mãos de seus inimigos ao redor; e não puderam mais resistir diante dos seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Por de onde quer que saíssem, a mão do SENHOR era contra eles para o mal, como o SENHOR havia dito, e como o SENHOR lhes havia jurado; assim estiveram em grande aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Mas o SENHOR suscitou juízes que os livrassem da mão dos que os despojavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Mas também não ouviram aos seus juízes; em vez disso, prostituíram-se seguindo outros deuses, aos quais adoraram; desviaram-se depressa do caminho em que seus pais andaram, obedecendo aos mandamentos do SENHOR; porém eles não fizeram assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'E quando o SENHOR lhes suscitava juízes, o SENHOR era com o juiz, e os livrava da mão dos inimigos todo aquele tempo daquele juiz, porque o SENHOR se arrependia pelo gemideles, por causa dos que os oprimiam e afligiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Mas acontecia que, quando o juiz morria, eles se voltavam para trás, e se corrompiam mais que seus pais, seguindo outros deuses para os adorarem e se inclinarem diante deles; e nada cessavam de suas obras, nem de seu teimoso caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Então a ira do SENHOR se acendeu contra Israel, e disse: “Visto que este povo transgride o meu pacto que ordenei aos seus pais, e não dá ouvidos à minha voz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'eu também não expulsarei mais de diante deles a nenhuma das nações que Josué deixou quando morreu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'para que por elas eu provasse os israelitas, se guardariam o caminho do SENHOR andando por ele, como seus pais o guardaram, ou não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Por isso o SENHOR deixou aquelas nações, e não as tirou logo, nem as entregou nas mãos de Josué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Estas, pois, são as nações que o SENHOR deixou para provar com elas a Israel, a todos aqueles que não haviam conhecido todas as guerras de Canaã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Somente para que a linhagem dos filhos de Israel conhecesse, para ensiná-los na guerra, pelo menos aos que antes não a conheciam:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Cinco príncipes dos filisteus, e todos os cananeus, e os sidônios, e os heveus que habitavam no monte Líbano: desde o monte de Baal-Hermom até chegar a Hamate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Estes, pois, foram para provar por eles a Israel, para saber se obedeceriam aos mandamentos do SENHOR, que ele havia prescrito a seus pais por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Assim os filhos de Israel habitavam entre os cananeus, heteus, amorreus, perizeus, heveus, e jebuseus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'E tomaram de suas filhas por mulheres, e deram suas filhas aos filhos deles, e serviram a seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Fizeram, pois, os filhos de Israel o mal aos olhos do SENHOR: e esquecidos do SENHOR seu Deus, serviram aos baalins, e aos ídolos dos bosques.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'E a ira do SENHOR se acendeu contra Israel, e vendeu-os em mãos de Cusã-Risataim rei da Mesopotâmia; e serviram os filhos de Israel a Cusã-Risataim oito anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'E clamaram os filhos de Israel ao SENHOR; e o SENHOR suscitou salvador aos filhos de Israel e livrou-os; é, a saber, a Otniel filho de Quenaz, irmão menor de Calebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'E o espírito do SENHOR foi sobre ele, e julgou a Israel, e saiu à batalha, e o SENHOR entregou em sua mão a Cusã-Risataim, rei da Síria, e prevaleceu sua mão contra Cusã-Risataim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'E repousou a terra quarenta anos; e morreu Otniel, filho de Quenaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'E voltaram os filhos de Israel a fazer o mal ante os olhos do SENHOR; e o SENHOR esforçou a Eglom rei de Moabe contra Israel, porquanto fizeram o mal ante os olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'E Juntou consigo aos filhos de Amom e de Amaleque, e foi, e feriu a Israel, e tomou a cidade das palmeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'E serviram os filhos de Israel a Eglom rei dos moabitas dezoito anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'E clamaram os filhos de Israel ao SENHOR; e o SENHOR lhes suscitou salvador, a Eúde, filho de Gera, benjamita, o qual era canhoto. E os filhos de Israel enviaram com ele um presente a Eglom rei de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'E Eúde se havia feito um punhal de dois fios, de um côvado de comprimento; e cingiu-se com ele debaixo de suas roupas à seu lado direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'E apresentou o presente a Eglom rei de Moabe; e era Eglom homem muito gordo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'E logo que apresentou o presente, despediu à gente que o havia trazido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Mas ele se virou desde os ídolos que estão em Gilgal, e disse: Rei, uma palavra secreta tenho que dizer-te. Ele então disse: Cala. E sairam-se de com ele todos os que diante dele estavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'E chegou-se Eúde a ele, o qual estava sentado sozinho em uma sala de verão. E Eúde disse: Tenho palavra de Deus para ti. Ele então se levantou da cadeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Mas Eúde meteu sua mão esquerda, e tomou o punhal de seu lado direito, e meteu-o pelo ventre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'De tal maneira que a empunhadura entrou também atrás a lâmina, e a gordura encerrou a lâmina, que ele não tirou o punhal de seu ventre: e saiu dele fezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'E saindo Eúde ao pátio, fechou atrás si as portas da sala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'E saído ele, vieram seus servos, os quais vendo as portas da sala fechadas, disseram: Sem dúvida ele está fazendo suas necessidades na sala de verão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'E havendo esperado até estar confusos, pois que ele não abria as portas da sala, tomaram a chave e abriram: e eis que seu senhor caído em terra morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Mas enquanto que eles se demoravam, Eúde se escapou, e passando os ídolos, salvou-se em Seirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'E quando entrou, tocou a trombeta no monte de Efraim, e os filhos de Israel desceram com ele do monte, e ele ia adiante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Então ele lhes disse: Segui-me, porque o SENHOR entregou vossos inimigos os moabitas em vossas mãos. E desceram atrás dele, e tomaram os vaus do Jordão a Moabe, e não deixaram passar a ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'E naquele tempo feriram dos moabitas como dez mil homens, todos valentes e todos homens de guerra; não escapou homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Assim restou Moabe subjugado aquele dia sob a mão de Israel: e repousou a terra oitenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Depois deste foi Sangar filho de Anate, o qual feriu seiscentos homens dos filisteus com uma aguilhada de bois; e ele também salvou a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Mas os filhos de Israel voltaram a fazer o mal aos olhos do SENHOR, depois da morte de Eúde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'E o SENHOR os vendeu em mão de Jabim rei de Canaã, o qual reinou em Hazor: e o capitão de seu exército se chamava Sísera, e ele habitava em Harosete das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'E os filhos de Israel clamaram ao SENHOR, porque aquele tinha novecentos carros de ferro: e havia afligido em grande maneira aos filhos de Israel por vinte anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'E governava naquele tempo a Israel uma mulher, Débora, profetisa, mulher de Lapidote:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'A qual se sentava debaixo da palmeira de Débora entre Ramá e Betel, no monte de Efraim: e os filhos de Israel subiam a ela a juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'E ela mandou chamar a Baraque filho de Abinoão, de Quedes de Naftali, e disse-lhe: Não te mandou o SENHOR Deus de Israel, dizendo: Vai, e ajunta gente no monte de Tabor, e toma contigo dez mil homens dos filhos de Naftali, e dos filhos de Zebulom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'E eu atrairei a ti ao ribeiro de Quisom a Sísera, capitão do exército de Jabim, com seus carros e seu exército, e o entregarei em tuas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'E Baraque lhe respondeu: Se tu fores comigo, eu irei: mas se não fores comigo, não irei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'E ela disse: Irei contigo; mas não será tua honra no caminho que vais; porque por mão de mulher venderá o SENHOR a Sísera. E levantando-se Débora foi com Baraque a Quedes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'E juntou Baraque a Zebulom e a Naftali em Quedes, e subiu com dez mil homens a seu mando, e Débora subiu com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'E Héber queneu, dos filhos de Hobabe sogro de Moisés, havia se afastado dos queneus, e posto sua tenda até o vale de Zaanim, que está junto a Quedes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Vieram, pois, as notícias a Sísera como Baraque filho de Abinoão havia subido ao monte de Tabor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'E reuniu Sísera todos os seus carros, novecentos carros de ferro, com todo o povo que com ele estava, desde Harosete das Nações até o ribeiro de Quisom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Então Débora disse a Baraque: Levanta-te; porque este é o dia em que o SENHOR entregou a Sísera em tuas mãos: Não saiu o SENHOR diante de ti? E Baraque desceu do monte de Tabor, e dez mil homens atrás dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'E o SENHOR derrotou a Sísera, e a todos os seus carros e a todo seu exército, a fio de espada diante de Baraque: e Sísera desceu do carro, e fugiu a pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Mas Baraque seguiu os carros e o exército até Harosete das Nações, e todo aquele exército de Sísera caiu a fio de espada até não restar nenhum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'E Sísera se refugiou a pé à tenda de Jael mulher de Héber queneu; porque havia paz entre Jabim rei de Hazor e a casa de Héber queneu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'E saindo Jael a receber a Sísera, disse-lhe: Vem, senhor meu, vem a mim, não tenhas medo. E ele veio a ela à tenda, e ela lhe cobriu com uma manta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'E ele lhe disse: Rogo-te me dês a beber um pouco de água, que tenho sede. E ela abriu um odre de leite e deu-lhe de beber, e voltou-lhe a cobrir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'E ele lhe disse: Fica-te à porta da tenda, e se alguém vier, e te perguntar, dizendo: Há aqui alguém? Tu responderás que não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'E Jael, mulher de Héber, tomou uma estaca da tenda, e pondo uma marreta em sua mão, veio a ele caladamente, e meteu-lhe a estaca pela têmpora, e encravou-o na terra, pois ele estava carregado de sonho e cansado; e assim morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'E seguindo Baraque a Sísera, Jael saiu a recebê-lo, e disse-lhe: Vem, e te mostrarei ao homem que tu buscas. E ele entrou de onde ela estava, e eis que Sísera jazia morto com a estaca pela têmpora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Assim abateu Deus aquele dia a Jabim, rei de Canaã, diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'E a mão dos filhos de Israel começou a crescer e a fortificar-se contra Jabim rei de Canaã, até que o destruíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'E aquele dia cantou Débora, com Baraque, filho de Abinoão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Porque vingou as injúrias de Israel, Porque o povo se ofereceu de sua vontade, Louvai ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Ouvi, reis; estai atentos, ó príncipes: Eu cantarei ao SENHOR, Cantarei salmos ao SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Quando saíste de Seir, ó SENHOR, Quando te apartaste do campo de Edom, A terra tremeu, e os céus destilaram, E as nuvens gotejaram águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Os montes se derreteram diante do SENHOR, Até o Sinai, diante do SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Em os dias de Sangar filho de Anate, Em os dias de Jael, cessaram os caminhos, E os que andavam pelas sendas apartavam-se por veredas torcidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'As aldeias haviam cessado em Israel, haviam decaído; Até que eu Débora me levantei, Me levantei mãe em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Em escolhendo novos deuses, A guerra estava às portas: Se via escudo ou lança Entre quarenta mil em Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Meu coração está pelos líderes de Israel, Os que com boa vontade se ofereceram entre o povo: Louvai ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vós os que cavalgais em asnas brancas, Os que presidis em juízo, E vós os que viajais, falai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Longe do ruído dos arqueiros, nos bebedouros, Ali repetirão as justiças do SENHOR, As justiças de suas vilas em Israel; Então o povo do SENHOR desceu às portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Desperta, desperta, Débora; Desperta, desperta, profere um cântico. Levanta-te, Baraque, e leva teus cativos, filho de Abinoão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Então fez que o que restou do povo, senhoreie aos poderosos: o SENHOR me fez senhorear sobre os fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'De Efraim saiu sua raiz contra Amaleque, Depois ti, Benjamim, contra teus povos; De Maquir desceram príncipes, E de Zebulom os que costumavam manejar vara de oficial.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Príncipes também de Issacar foram com Débora; E como Issacar, também Baraque Se pôs a pé no vale. Das divisões de Rúben houve grandes impressões do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Por que te restaste entre os currais, Para ouvir os balidos dos rebanhos? Das divisões de Rúben Grandes foram os questionamentos do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gileade se restou da outra parte do Jordão: E Dã por que se esteve junto aos navios? Manteve-se Aser à beira do mar, E ficou em seus portos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'O povo de Zebulom expôs sua vida à morte, E Naftali nas alturas do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Vieram reis e lutaram: Então lutaram os reis de Canaã Em Taanaque, junto às águas de Megido, Mas não levaram despojo algum de dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Dos céus lutaram: As estrelas desde suas órbitas lutaram contra Sísera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Varreu-os o ribeiro de Quisom, O antigo ribeiro, o ribeiro de Quisom. Pisaste, ó alma minha, com força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Espancaram-se então os cascos dos cavalos pelas arremetidas, pelos galopes de seus fortes cavalos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Amaldiçoai a Meroz, disse o anjo do SENHOR: Amaldiçoai severamente a seus moradores, Porque não vieram em socorro ao SENHOR, Em socorro ao SENHOR contra os fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Bendita seja entre as mulheres Jael, Mulher de Héber queneu; Sobre as mulheres bendita seja na tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Ele pediu água, e deu-lhe ela leite; Em taça de nobres lhe apresentou manteiga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Sua mão estendeu à estaca, E sua direita a marreta de trabalhadores; E golpeou a Sísera, feriu sua cabeça, esmagou e atravessou suas têmporas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Caiu encurvado entre seus pés, ficou estendido: Entre seus pés caiu encurvado; Onde se encurvou, ali caiu morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'A mãe de Sísera olha à janela, E por entre as grades a vozes disse: Por que se detém seu carro, que não vem? Por que as rodas de seus carros se tardam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'As mais avisadas de suas damas lhe respondiam; E ainda ela se respondia a si mesma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Não acharam despojos, e os estão repartindo? A cada um uma moça, ou duas: Os despojos de cores para Sísera, Os despojos bordados de cores: A roupa de cor bordada de ambos os lados, para os pescoços dos que tomaram os despojos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Assim pereçam todos os teus inimigos, ó SENHOR: Mas os que lhe amam, sejam como o sol quando nasce em sua força. E a terra repousou quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Mas os filhos de Israel fizeram o mal aos olhos do SENHOR; e o SENHOR os entregou nas mãos de Midiã por sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'E a mão de Midiã prevaleceu contra Israel. E os filhos de Israel, por causa dos midianitas, se fizeram covas nos montes, e cavernas, e lugares fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Pois quando os de Israel haviam semeado, subiam os midianitas, e amalequitas, e os orientais: subiam contra eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'E assentando acampamento contra eles destruíam os frutos da terra, até chegar a Gaza; e não deixavam o que comer em Israel, nem ovelhas, nem bois, nem asnos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Porque subiam eles e seus gados, e vinham com suas tendas em grande multidão como gafanhotos, que não havia número neles nem em seus camelos: assim vinham à terra para devastá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Era, pois, Israel em grande maneira empobrecido pelos midianitas; e os filhos de Israel clamaram ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'E quando os filhos de Israel clamaram ao SENHOR, por causa dos midianitas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'O SENHOR enviou um homem profeta aos filhos de Israel, o qual lhes disse: Assim disse o SENHOR Deus de Israel: Eu vos fiz sair do Egito, e vos tirei da casa de servidão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Eu vos livrei da mão dos egípcios, e da mão de todos os que vos afligiram, aos quais expulsei de diante de vós, e vos dei sua terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'E disse-vos: Eu sou o SENHOR vosso Deus; não temais aos deuses dos amorreus, em cuja terra habitais; mas não obedecestes à minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'E veio o anjo do SENHOR, e sentou-se debaixo do carvalho que está em Ofra, o qual era de Joás abiezrita; e seu filho Gideão estava malhando o trigo no lagar, para fazê-lo esconder dos midianitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'E o anjo do SENHOR se lhe apareceu, e disse-lhe: O SENHOR é contigo, homem esforçado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'E Gideão lhe respondeu: Ah, Senhor meu, se o SENHOR é conosco, por que nos sobreveio tudo isto? E onde estão todas suas maravilhas, que nossos pais nos contaram, dizendo: Não nos tirou o SENHOR do Egito? E agora o SENHOR nos desamparou, e nos entregou nas mãos dos midianitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'E olhando-lhe o SENHOR, disse-lhe: Vai com esta tua força, e salvarás a Israel da mão dos midianitas. Não te envio eu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Então lhe respondeu: Ah, Senhor meu, com que tenho de salvar a Israel? Eis que minha família é pobre em Manassés, e eu o menor na casa de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'E o SENHOR lhe disse: Porque eu serei contigo, e ferirás aos midianitas como a um só homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'E ele respondeu: Eu te rogo que, se achei favor diante de ti, me dês sinal de que tu falaste comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Rogo-te que não te vás daqui, até que a ti volte, e tire meu presente, e o ponha diante de ti. E ele respondeu: Eu esperarei até que voltes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'E entrando-se Gideão preparou um cabrito, e pães sem levedura de um efa de farinha; e pôs a carne em um cesto, e o caldo em uma caçarola, e tirando-o apresentou-lhe debaixo daquele carvalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'E o anjo de Deus lhe disse: Toma a carne, e os pães sem levedura, e põe-o sobre esta penha, e derrama o caldo. E ele o fez assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'E estendendo o anjo do SENHOR o bordão que tinha em sua mão, tocou com a ponta na carne e nos pães sem levedura; e subiu fogo da penha, o qual consumiu a carne e os pães sem levedura. E o anjo do SENHOR desapareceu de diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'E vendo Gideão que era o anjo do SENHOR, disse: Ah, Senhor DEUS, que vi o anjo do SENHOR face a face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'E o SENHOR lhe disse: Paz seja contigo; não tenhas medo, não morrerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'E edificou ali Gideão altar ao SENHOR, ao que chamou O SENHOR é paz: está até hoje em Ofra dos abiezritas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'E aconteceu que a mesma noite lhe disse o SENHOR: Toma um touro do rebanho de teu pai, e outro touro de sete anos, e derruba o altar de Baal que teu pai tem, e corta também o bosque que está junto a ele:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'E edifica altar ao SENHOR teu Deus no cume deste penhasco em lugar conveniente; e tomando o segundo touro, sacrifica-o em holocausto sobre a lenha do bosque que haverás cortado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Então Gideão tomou dez homens de seus servos, e fez como o SENHOR lhe disse. Mas temendo fazê-lo de dia, pela família de seu pai e pelos homens da cidade, o fez de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'E à manhã, quando os da cidade se levantaram, eis que o altar de Baal estava derrubado, e cortado o bosque que junto a ele estava, e sacrificado aquele segundo touro em holocausto sobre o altar edificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'E diziam-se uns aos outros: Quem fez isto? E buscando e investigando, disseram-lhes: Gideão filho de Joás o fez. Então os homens da cidade disseram a Joás:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Tira fora teu filho para que morra, porquanto derrubou o altar de Baal e cortou o bosque que junto a ele estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'E Joás respondeu a todos os que estavam junto a ele: Tomareis vós a demanda por Baal? Vós o salvareis? Qualquer um que tomar a demanda por ele, que morra amanhã. Se é Deus, contenda por si mesmo com o que derrubou seu altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'E aquele dia ele chamou a Gideão Jerubaal; porque disse: Pleiteie Baal contra o que derrubou seu altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'E todos os midianitas, e amalequitas, e orientais, se juntaram de uma vez, e passando assentaram acampamento no vale de Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'E o espírito do SENHOR se investiu em Gideão, e quando este tocou a a trombeta, Abiezer se juntou com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'E enviou mensageiros por todo Manassés, o qual também se juntou com ele: também enviou mensageiros a Aser, e a Zebulom, e a Naftali, os quais saíram a encontrar-lhes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'E Gideão disse a Deus: Se hás de salvar a Israel por minha mão, como disseste,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Eis que eu porei um velo de lã na era; e se o orvalho estiver no velo somente, restando seca toda a outra terra, então entenderei que hás de salvar a Israel por minha mão, como o disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'E aconteceu assim: porque quando se levantou de manhã, espremendo o velo tirou dele o orvalho, um vaso cheio de água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Mas Gideão disse a Deus: Não se acenda tua ira contra mim, se ainda falar esta vez: somente provarei agora outra vez com o velo. Rogo-te que a secura seja somente no velo, e o orvalho sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'E aquela noite o fez Deus assim: porque a secura foi somente no velo, e em toda a terra esteve o orvalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Levantando-se, pois, de manhã Jerubaal, o qual é Gideão, e todo aquele povo que estava com ele, assentaram o acampamento junto à fonte de Harode: e tinha o acampamento dos midianitas ao norte, da outra parte do morro de Moré, no vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'E o SENHOR disse a Gideão: O povo que está contigo é muito para que eu dê aos midianitas em sua mão: para que não se glorie Israel contra mim, dizendo: Minha mão me salvou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Agora, pois, proclama aos ouvidos do povo, dizendo: Aquele que teme e se estremece, volte e retire-se do monte de Gileade. E do povo voltaram vinte e dois mil; e restaram dez mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'E o SENHOR disse a Gideão: Ainda é muito o povo; leva-os às águas, e ali eu te os provarei; e do que eu te disser: Vá este contigo, vá contigo: mas de qualquer um que eu te disser: Este não vá contigo, o tal não vá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Então levou o povo às águas: e o SENHOR disse a Gideão: Qualquer um que lamber as águas com sua língua como lambe o cão, aquele porás à parte; também qualquer um que se dobrar sobre seus joelhos para beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'E foi o número dos que lamberam as águas, achegando-a com a mão à boca, trezentos homens: e todo aquele resto do povo se dobrou sobre seus joelhos para beber as águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Então o SENHOR disse a Gideão: Com estes trezentos homens que lamberam o água vos salvarei, e entregarei aos midianitas em tuas mãos; e vá-se todo o resto do povo cada um a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Depois de tomarem a provisão do povo e suas trombetas, ele enviou todos os israelitas cada um a sua tenda, mas manteve aqueles trezentos homens; e o campo de Midiã estava no vale abaixo dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'E aconteceu que aquela noite o SENHOR lhe disse: Levanta-te, e desce ao acampamento; porque eu o entreguei em tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'E se temes descer para atacar, desce apenas tu e o teu servo Pura ao acampamento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'e ouvirás o que falam; e então tuas mãos se fortalecerão, e descerás para atacar o acampamento. E ele desceu com o seu servo Pura à extremidade dos homens armados que estavam no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'E Midiã, e Amaleque, e todos os orientais, estavam estendidos no vale como gafanhotos em multidão, e seus camelos eram inúmeros, como a areia que está à beira do mar em multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'E logo que chegou Gideão, eis que um homem estava contando a seu companheiro um sonho, dizendo: Eis que eu sonhei um sonho: que via um pão de cevada que rodava até o acampamento de Midiã, e chegava às tendas, e as feria de tal maneira que caíam, e as virava de cima abaixo, e as tendas caíam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'E seu companheiro respondeu, e disse: Isto não é outra coisa a não ser a espada de Gideão filho de Joás, homem de Israel: Deus entregou em suas mãos aos midianitas com todo o acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'E quando Gideão ouviu a história do sonho e sua interpretação, adorou; e voltado ao acampamento de Israel, disse: Levantai-vos, que o SENHOR entregou o acampamento de Midiã em vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'E repartindo os trezentos homens em três esquadrões, deu a cada um deles trombetas em suas mãos, e cântaros vazios com tochas ardendo dentro dos cântaros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'E disse-lhes: Olhai a mim, e fazei como eu fizer; eis que quando eu chegar ao princípio do acampamento, como eu fizer, assim fareis vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Eu tocarei a trombeta e todos os que estiverem comigo; e vós tocareis então as trombetas ao redor de todo aquele campo, e direis: Pelo SENHOR e Gideão!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Chegou, pois, Gideão, e os cem homens que levava consigo, ao princípio do acampamento, à entrada da vigília do meio, quando acabavam de renovar as sentinelas; e tocaram as trombetas, e quebraram os cântaros que levavam em suas mãos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'E os três esquadrões tocaram as trombetas, e quebrando os cântaros tomaram nas mãos esquerdas as tochas, e nas direitas as trombetas com que tocavam, e deram grito: A espada do SENHOR e de Gideão!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'E estiveram em seus lugares em derredor do acampamento: e todo aquele acampamento foi alvoroçado, e fugiram gritando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Mas os trezentos tocavam as trombetas: e o SENHOR pôs a espada de cada um contra seu companheiro em todo aquele acampamento. E o exército fugiu até Bete-Sita, até Zererá, e até o termo de Abel-Meolá em Tabate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'E juntando-se os de Israel, de Naftali, e de Aser, e de todo Manassés, seguiram aos midianitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Gideão também enviou mensageiros a todo aquele monte de Efraim, dizendo: Descei ao encontro dos midianitas, e tomai-lhes as águas até Bete-Bara e o Jordão. E juntos todos os homens de Efraim, tomaram as águas de Bete-Bara e o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'E tomaram dois príncipes dos midianitas, Orebe e Zeebe: e mataram a Orebe na penha de Orebe, e a Zeebe o mataram no lagar de Zeebe: e depois que seguiram aos midianitas, trouxeram as cabeças de Orebe e de Zeebe a Gideão da outra parte do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'E os de Efraim lhe disseram: Que é isto que fizeste conosco, não chamando-nos quando ias à guerra contra Midiã? E reclamaram dele fortemente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Aos quais ele respondeu: Que fiz eu agora como vós? Não são as sobras das uvas de Efraim melhor que a vindima de Abiezer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Deus entregou em vossas mãos a Orebe e a Zeebe, príncipes de Midiã: e que pude eu fazer como vós? Então a ira deles contra ele se aplacou, logo que ele falou esta palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'E veio Gideão ao Jordão para passar, ele e os trezentos homens que trazia consigo, cansados, mas ainda perseguindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'E disse aos de Sucote: Eu vos rogo que deis à gente que me segue alguns bocados de pão; porque estão cansados, e eu persigo a Zeba e a Zalmuna, reis de Midiã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'E os principais de Sucote responderam: Está já a mão de Zeba e Zalmuna em tua mão, para que havemos nós de dar pão a teu exército?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'E Gideão disse: Pois quando o SENHOR entregar em minha mão a Zeba e a Zalmuna, eu trilharei vossa carne com espinhos e abrolhos do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'E dali subiu a Peniel, e falou-lhes as mesmas palavras. E os de Peniel lhe responderam como haviam respondido os de Sucote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'E ele falou também aos de Peniel, dizendo: Quando eu voltar em paz, derrubarei esta torre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'E Zeba e Zalmuna estavam em Carcor, e com eles seu exército de como quinze mil homens, todos os que haviam restado de todo aquele acampamento dos orientais: e os mortos haviam sido cento vinte mil homens que tiravam espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'E subindo Gideão até os que habitavam em tendas, à parte oriental de Noba e de Jogbeá, feriu o acampamento, porque estava o exército desprevenido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'E fugindo Zeba e Zalmuna, ele os seguiu; e tomados os dois reis de Midiã, Zeba e Zalmuna, espantou a todo aquele exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'E Gideão filho de Joás voltou da batalha antes que o sol subisse;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'E tomou um jovem dos de Sucote, e perguntando-lhe, ele lhe deu por escrito os principais de Sucote e seus anciãos, setenta e sete homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'E entrando aos de Sucote, disse: Eis aqui a Zeba e a Zalmuna, sobre os quais me escarnecestes, dizendo: Está já a mão de Zeba e de Zalmuna em tua mão, para que demos nós pão a teus homens cansados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'E tomou aos anciãos da cidade, e espinhos e abrolhos do deserto, e castigou com eles aos de Sucote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Também derrubou a torre de Peniel, e matou aos da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Logo disse a Zeba e a Zalmuna: Que maneira de homens tinham aqueles que matastes em Tabor? E eles responderam: Como tu, tais eram aqueles nem mais nem menos, que apareciam filhos de rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'E ele disse: Meus irmãos eram, filhos de minha mãe: Vive o SENHOR, que se os tivésseis guardado em vida, eu não vos mataria!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'E disse a Jéter seu primogênito: Levanta-te, e mata-os. Mas o jovem não desembainhou sua espada, porque tinha medo; que ainda era jovem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Então disse Zeba e Zalmuna: Levanta-te tu, e mata-nos; porque como é o homem, tal é sua valentia. E Gideão se levantou, e matou a Zeba e a Zalmuna; e tomou os adornos de crescentes que seus camelos traziam ao pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'E os israelitas disseram a Gideão: Sê nosso senhor, tu, e teu filho, e teu neto; pois que nos livraste da mão de Midiã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Mas Gideão respondeu: Não serei senhor sobre vós, nem meu filho vos dominará: o SENHOR será vosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'E disse-lhes Gideão: Desejo fazer-vos uma petição, que cada um me dê os pendentes de seu despojo. (Porque traziam pendentes de ouro, que eram ismaelitas.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'E eles responderam: De boa vontade os daremos. E segurando uma roupa de vestir, lançou ali cada um os pendentes de seu despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'E foi o peso dos pendentes de ouro que ele pediu mil e setecentos siclos de ouro; sem contar os ornamentos, e as joias, e vestidos de púrpura, que traziam os reis de Midiã, e sem os colares que traziam seus camelos ao pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'E Gideão fez deles um éfode, o qual fez guardar em sua cidade de Ofra: e todo Israel prostituiu-se atrás desse éfode naquele lugar; e foi por tropeço a Gideão e a sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Assim foi humilhado Midiã diante dos filhos de Israel, e nunca mais levantaram sua cabeça. E repousou a terra quarenta anos nos dias de Gideão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'E Jerubaal filho de Joás foi, e habitou em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'E teve Gideão setenta filhos que saíram de sua coxa, porque teve muitas mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'E sua concubina que estava em Siquém, também lhe deu um filho; e pôs-lhe por nome Abimeleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'E morreu Gideão filho de Joás em boa velhice, e foi sepultado no sepulcro de seu pai Joás, em Ofra dos abiezritas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'E aconteceu que quando morreu Gideão, os filhos de Israel voltaram, e se prostituíram atrás dos baalins, e se puseram por Deus a Baal-Berite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'E os filhos de Israel não se lembraram do SENHOR seu Deus, que os havia livrado de todos os seus inimigos ao redor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Nem fizeram misericórdia com a casa de Jerubaal Gideão conforme todo aquele bem que ele havia feito a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'E foi-se Abimeleque filho de Jerubaal a Siquém, aos irmãos de sua mãe, e falou com eles, e com toda a família da casa do pai de sua mãe, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Eu vos rogo que faleis a ouvidos de todos os de Siquém: Que tendes por melhor, que vos dominem setenta homens, todos os filhos de Jerubaal; ou que vos senhoreie um homem? Lembrai-vos que eu sou osso vosso, e carne vossa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'E falaram por ele os irmãos de sua mãe a ouvidos de todos os de Siquém todas estas palavras: e o coração deles se inclinou em favor de Abimeleque, porque diziam: Nosso irmão é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'E deram-lhe setenta siclos de prata do templo de Baal-Berite, com os quais Abimeleque contratou homens ociosos e vagabundos, que lhe seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'E vindo à casa de seu pai em Ofra, matou a seus irmãos os filhos de Jerubaal, setenta homens, sobre uma pedra: mas restou Jotão, o menor filho de Jerubaal, que se escondeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'E reunidos todos os de Siquém com toda a casa de Milo, foram e elegeram a Abimeleque por rei, próximo da planície do pilar que estava em Siquém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'E quando se o disseram a Jotão, foi e pôs-se no cume do monte de Gerizim, e levantando sua voz clamou, e disse-lhes: Ouvi-me, homens de Siquém; que Deus vos ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Foram as árvores a eleger rei sobre si, e disseram à oliva: Reina sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Mas a oliveira respondeu: Tenho de deixar meu azeite, com o que por minha causa Deus e os homens são honrados, para ir a ser grande sobre as árvores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'E disseram as árvores à figueira: Anda tu, reina sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'E respondeu a figueira: Tenho de deixar minha doçura e meu bom fruto, para ir a ser grande sobre as árvores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Disseram logo as árvores à vide: Pois vem tu, reina sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'E a vide lhes respondeu: Tenho de deixar meu mosto, que alegra a Deus e aos homens, para ir a ser grande sobre as árvores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Disseram então todas as árvores ao espinheiro: Vem tu, reina sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'E o espinheiro respondeu às árvores: Se em verdade me elegeis por rei sobre vós, vinde, e assegurai-vos debaixo de minha sombra: e se não, fogo saia do espinheiro que devore os cedros do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Agora, pois, se com verdade e com integridade tendes procedido em fazer rei a Abimeleque, e se o fizestes bem com Jerubaal e com sua casa, e se lhe haveis pagado conforme a obra de suas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(Pois que meu pai lutou por vós, e expulsou longe sua vida para livrar-vos da mão de Midiã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'E vós vos levantastes hoje contra a casa de meu pai, e matastes seus filhos, setenta homens, sobre uma pedra; e pusestes por rei sobre os de Siquém a Abimeleque, filho de sua criada, porquanto é vosso irmão);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Se com verdade e com integridade agistes hoje com Jerubaal e com sua casa, alegrai-vos de Abimeleque, e ele se alegre de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'E se não, fogo saia de Abimeleque, que consuma aos de Siquém e à casa de Milo; e fogo saia dos de Siquém e da casa de Milo, que consuma a Abimeleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'E fugiu Jotão, e se escapou, e foi-se a Beer, e ali se esteve por causa de Abimeleque seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'E depois que Abimeleque dominou sobre Israel três anos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Enviou Deus um espírito mau entre Abimeleque e os homens de Siquém: que os de Siquém se levantaram contra Abimeleque:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Para que o crime dos setenta filhos de Jerubaal, e o sangue deles, viesse a se pôr sobre Abimeleque seu irmão que os matou, e sobre os homens de Siquém que corroboraram as mãos dele para matar a seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'E puseram-lhe os de Siquém emboscadores nos cumes dos montes, os quais assaltavam a todos os que passavam junto a eles pelo caminho; do que foi dado aviso a Abimeleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'E Gaal filho de Ebede veio com seus irmãos, e passaram a Siquém: e os de Siquém se confiaram nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'E saindo ao campo, vindimaram suas vinhas, e pisaram a uva, e fizeram alegrias; e entrando no templo de seus deuses, comeram e beberam, e amaldiçoaram a Abimeleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'E Gaal filho de Ebede disse: Quem é Abimeleque e que é Siquém, para que nós a ele sirvamos? não é filho de Jerubaal? e não é Zebul seu assistente? Servi aos homens de Hamor pai de Siquém: mas por que serviríamos a ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Fosse-me dado este povo abaixo de minha mão, eu expulsaria logo a Abimeleque. E dizia a Abimeleque: Aumenta teus esquadrões, e sai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'E Zebul assistente da cidade, ouvindo as palavras de Gaal filho de Ebede, acendeu-se sua ira;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'E enviou sagazmente mensageiros a Abimeleque, dizendo: Eis que Gaal filho de Ebede e seus irmãos vieram a Siquém, e eis que cercaram a cidade contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Levanta-te, pois, agora de noite, tu e o povo que está contigo, e põe emboscada no campo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'E pela manhã ao sair do sol te levantarás e atacarás a cidade: e ele e o povo que está com ele sairão contra ti, e tu farás com ele segundo que se te oferecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Levantando-se, pois, de noite Abimeleque e todo aquele povo que com ele estava, puseram emboscada contra Siquém com quatro companhias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'E Gaal filho de Ebede saiu, e pôs-se à entrada da porta da cidade: e Abimeleque e todo aquele povo que com ele estava, se levantaram da emboscada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'E vendo Gaal o povo, disse a Zebul: Eis ali povo que desce dos cumes dos montes. E Zebul lhe respondeu: A sombra dos montes te parece homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Mas Gaal voltou a falar, e disse: Eis ali um povo que desce por meio da terra, e um esquadrão vem pelo caminho da campina de Meonenim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'E Zebul lhe respondeu: Onde está agora aquele teu falar, dizendo; Quem é Abimeleque para que lhe sirvamos? Não é este o povo que menosprezavas? Sai, pois, agora, e luta com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'E Gaal saiu diante dos de Siquém, e lutou contra Abimeleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Mas perseguiu-o Abimeleque, diante do qual ele fugiu; e caíram feridos muitos até a entrada da porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'E Abimeleque ficou em Aruma; e Zebul lançou fora a Gaal e a seus irmãos, para que não morassem em Siquém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'E aconteceu ao dia seguinte, que o povo saiu ao campo: e foi dado aviso a Abimeleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'O qual, tomando gente, repartiu-a em três companhias, e pôs emboscadas no campo: e quando olhou, eis o povo que saía da cidade; e levantou-se contra eles, e feriu-os:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Pois Abimeleque e o esquadrão que estava com ele, atacaram com ímpeto, e pararam à entrada da porta da cidade; e as duas companhias atacaram a todos os que estavam no campo, e os feriram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'E depois de combater Abimeleque a cidade todo aquele dia, tomou-a, e matou o povo que nela estava, e assolou a cidade, e semeou-a de sal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Quando ouviram isto todos os que estavam na torre de Siquém, entraram na fortaleza do templo do deus Berite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'E foi dito a Abimeleque como todos os da torre de Siquém estavam reunidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Então subiu Abimeleque ao monte de Salmom, ele e toda a gente que com ele estava; e tomou Abimeleque um machado em sua mão, e cortou um ramo das árvores, levantou-o, e o pôs sobre seus ombros, dizendo ao povo que estava com ele: O que vós vedes que estou fazendo, fazei imediatamente como eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'E assim todo aquele povo cortou também cada um seu ramo, e seguiram a Abimeleque, e puseram-nas junto à fortaleza, e prenderam fogo com elas à fortaleza: por maneira que todos os da torre de Siquém morreram, como uns mil homens e mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Depois Abimeleque se foi a Tebes; e pôs cerco a Tebes, e tomou-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Em meio daquela cidade havia uma torre forte, à qual se retiraram todos os homens e mulheres, e todos os senhores da cidade; e fechando atrás de si as portas, subiram ao piso alto da torre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'E veio Abimeleque à torre, e combatendo-a, chegou-se à porta da torre para pegar-lhe fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Mas uma mulher deixou cair um pedaço de uma roda de moinho sobre a cabeça de Abimeleque, e quebrou-lhe o crânio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'E logo ele chamou a seu escudeiro, e disse-lhe: Tira tua espada e mata-me, porque não se diga de mim: Uma mulher o matou. E seu escudeiro o atravessou, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'E quando os israelitas viram morto a Abimeleque, foram-se cada um à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Assim, pois, Deus pagou a Abimeleque o mal que fez contra seu pai matando a seus setenta irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'E ainda todo aquele mal dos homens de Siquém devolveu Deus sobre suas cabeças: e a maldição de Jotão, filho de Jerubaal, veio sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'E Depois de Abimeleque levantou-se para livrar a Israel, Tolá filho de Puá, filho de Dodô, homem de Issacar, o qual habitava em Samir, no monte de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'E julgou a Israel vinte e três anos, e morreu, e foi sepultado em Samir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Depois dele se levantou Jair, gileadita, o qual julgou a Israel vinte e dois anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Este teve trinta filhos que cavalgavam sobre trinta asnos, e tinham trinta vilas, que se chamaram as vilas de Jair até hoje, as quais estão na terra de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'E morreu Jair, e foi sepultado em Camom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Mas os filhos de Israel voltaram a fazer o mal aos olhos do SENHOR, e serviram aos baalins e a Astarote, e aos deuses da Síria, e aos deuses de Sidom, e aos deuses de Moabe, e aos deuses dos filhos de Amom, e aos deuses dos filisteus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'E o SENHOR se irou contra Israel, e vendeu-os por mão dos filisteus, e por mão dos filhos de Amom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Os quais moeram e quebrantaram aos filhos de Israel naquele tempo dezoito anos, a todos os filhos de Israel que estavam da outra parte do Jordão na terra dos amorreus, que é em Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'E os filhos de Amom passaram o Jordão para fazer também guerra contra Judá, e contra Benjamim, e a casa de Efraim: e foi Israel em grande maneira afligido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'E os filhos de Israel clamaram ao SENHOR, dizendo: Nós pecamos contra ti; porque deixamos a nosso Deus, e servido aos baalins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'E o SENHOR respondeu aos filhos de Israel: Não fostes oprimidos pelo Egito, pelos amorreus, pelos amonitas, dos filisteus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Dos de Sidom, de Amaleque, e de Maom, e clamando a mim vos livrei de suas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Mas vós me deixastes, e servistes a deuses alheios: portanto, eu não vos livrarei mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Andai, e clamai aos deuses que escolhestes para vós, que vos livrem no tempo de vossa aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'E os filhos de Israel responderam ao SENHOR: Pecamos; faze tu conosco como bem te parecer: somente que agora nos livres neste dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'E tiraram dentre si os deuses alheios, e serviram ao SENHOR; e sua alma foi angustiada por causa do sofrimento de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'E juntando-se os filhos de Amom, assentaram acampamento em Gileade; juntaram-se assim os filhos de Israel, e assentaram seu acampamento em Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'E os príncipes e o povo de Gileade disseram um ao outro: Quem será o que começará a batalha contra os filhos de Amom? Ele será cabeça sobre todos os que habitam em Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Existia então Jefté, gileadita, homem valente, filho de uma prostituta, ao qual havia gerado Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'E a mulher de Gileade também lhe havia dado à luz filhos; os quais quando foram grandes, lançaram fora a Jefté, dizendo-lhe: Não herdarás na casa de nosso pai, porque és bastardo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Fugindo, pois, Jefté por causa de seus irmãos, habitou em terra de Tobe; e juntaram-se com ele homens ociosos, os quais com ele saíam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'E aconteceu que depois de dias os filhos de Amom fizeram guerra contra Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'E quando os filhos de Amom tinham guerra contra Israel, os anciãos de Gileade foram para fazer voltar a Jefté da terra de Tobe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'E disseram a Jefté: Vem, e serás nosso capitão, para que lutemos com os filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'E Jefté respondeu aos anciãos de Gileade: Não me odiastes, e me lançastes da casa de meu pai? por que pois vindes agora a mim quando estais em aflição?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'E os anciãos de Gileade responderam a Jefté: Por esta mesma causa voltamos agora a ti, para que venhas conosco, e lutes contra os filhos de Amom, e nos sejas cabeça a todos os que moramos em Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jefté então disse aos anciãos de Gileade: Se me fazeis voltar para que lute contra os filhos de Amom, e o SENHOR os entregar diante de mim, serei eu vossa cabeça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'E os anciãos de Gileade responderam a Jefté: O SENHOR ouça entre nós, se não fizermos como tu dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Então Jefté veio com os anciãos de Gileade, e o povo o elegeu por seu cabeça e príncipe; e Jefté falou todas seus palavras diante do SENHOR em Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'E enviou Jefté embaixadores ao rei dos amonitas, dizendo: Que tens tu comigo que vieste a mim para fazer guerra em minha terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'E o rei dos amonitas respondeu aos embaixadores de Jefté: Porquanto Israel tomou minha terra, quando subiu do Egito, desde Arnom até Jaboque e o Jordão; portanto, devolve-as agora em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'E Jefté voltou a enviar outros embaixadores ao rei dos amonitas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Para dizer-lhe: Jefté disse assim: Israel não tomou terra de Moabe, nem terra dos filhos de Amom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Mas subindo Israel do Egito, andou pelo deserto até o mar Vermelho, e chegou a Cades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Então Israel enviou embaixadores ao rei de Edom, dizendo: Eu te rogo que me deixes passar por tua terra. Mas o rei de Edom não os escutou. Enviou também ao rei de Moabe; o qual tampouco quis: ficou, portanto, Israel em Cades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Depois, indo pelo deserto, rodeou a terra de Edom e a terra de Moabe, e vindo pelo lado oriental da terra de Moabe, assentou seu acampamento de outra parte de Arnom, e não entraram pelo termo de Moabe: porque Arnom é termo de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'E enviou Israel embaixadores a Seom rei pelos amorreus, rei de Hesbom, dizendo-lhe: Rogo-te que me deixes passar por tua terra até meu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mas Seom não confiou em Israel para dar-lhe passagem por seu termo; antes juntando Seom toda sua gente, pôs acampamento em Jaza, e lutou contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Porém o SENHOR o Deus de Israel entregou a Seom e a todo seu povo por mão de Israel, e venceu-os: e possuiu Israel toda a terra dos amorreus que habitava naquele país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Possuíram também todo aquele termo dos amorreus desde Arnom até Jaboque, e desde o deserto até o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Assim que o SENHOR o Deus de Israel expulsou os amorreus diante de seu povo Israel: e o hás de possuir tu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Se Camos teu Deus te expulsasse algum, não o possuirias tu? Assim nós possuiremos a tudo aquilo que o SENHOR expulsou nosso Deus de diante de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'És tu agora em algo melhor que Balaque filho de Zipor, rei de Moabe? Teve ele questão contra Israel, ou fez guerra contra eles?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Quando Israel esteve habitando por trezentos anos a Hesbom e suas aldeias, a Aroer e suas aldeias, e todas as cidades que estão aos termos de Arnom, por que não as reclamaste nesse tempo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Assim que, eu nada pequei contra ti, mas tu fazes mal comigo fazendo-me guerra: o SENHOR, que é o juiz, julgue hoje entre os filhos de Israel e os filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Mas o rei dos filhos de Amom não atendeu os argumentos de Jefté que lhe enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'E o espírito do SENHOR foi sobre Jefté: e passou por Gileade e Manassés; e dali passou a Mispá de Gileade; e de Mispá de Gileade passou aos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'E Jefté fez voto ao SENHOR, dizendo: Se entregares aos amonitas em minhas mãos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Qualquer um que me sair a receber das portas de minha casa, quando voltar dos amonitas em paz, será do SENHOR, e lhe oferecerei em holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Passou, pois, Jefté aos filhos de Amom para lutar contra eles; e o SENHOR os entregou em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'E os feriu de grandíssimo dano desde Aroer até chegar a Minite, vinte cidades; e até a Abel-Queramim. Assim foram dominados os amonitas diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'E voltando Jefté a Mispá à sua casa, eis que sua filha lhe saiu a receber com adufes e danças, e era a única, a única sua; não tinha além dela outro filho nem filha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'E quando ele a viu, rompeu suas roupas dizendo: Ai, filha minha! De verdade me abateste, e tu és dos que me afligem: porque eu abri minha boca ao SENHOR, e não poderei retratar-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Ela então lhe respondeu: Pai meu, se abriste tua boca ao SENHOR, faze de mim como saiu de tua boca, pois que o SENHOR fez vingança em teus inimigos os filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'E voltou a dizer a seu pai: Faze-me isto: deixa-me por dois meses que vá e desça pelos montes, e chore minha virgindade, eu e minhas companheiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Ele então disse: Vai. E deixou-a por dois meses. E ela foi com suas companheiras, e chorou sua virgindade pelos montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Passados os dois meses, voltou a seu pai, e fez dela conforme seu voto que havia feito. E ela nunca conheceu homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'De aqui foi o costume em Israel que de ano em ano iam as virgens de Israel a lamentar à filha de Jefté gileadita, quatro dias no ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'E juntando-se os homens de Efraim, passaram até o norte, e disseram a Jefté: Por que foste a fazer guerra contra os filhos de Amom, e não nos chamaste para que fôssemos contigo? Nós queimaremos a fogo tua casa contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'E Jefté lhes respondeu: Eu tive, e meu povo, uma grande contenda com os filhos de Amom, e vos chamei, e não me defendestes de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Vendo pois que não me defendíeis, pus minha alma em minha palma, e passei contra os filhos de Amom, e o SENHOR os entregou em minha mão: por que pois subistes hoje contra mim para lutar comigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'E juntando Jefté a todos os homens de Gileade, lutou contra Efraim; e os de Gileade feriram a Efraim, porque haviam dito: Vós sois fugitivos de Efraim, vós sois gileaditas entre Efraim e Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'E os gileaditas tomaram os vaus do Jordão a Efraim; e era que, quando algum dos de Efraim que havia fugido, dizia, passarei? Os de Gileade lhe perguntavam: És tu efraimita? Se ele respondia, Não;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Então lhe diziam: Agora, pois, dize, Chibolete. E ele dizia, Sibolete; porque não podia pronunciar daquela sorte. Então lhe lançavam mão, e lhe degolavam junto aos vaus do Jordão. E morreram então dos de Efraim quarenta e dois mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'E Jefté julgou Israel por seis anos: logo morreu Jefté gileadita, e foi sepultado em uma das cidades de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Depois dele julgou a Israel Ibsã de Belém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'O qual teve trinta filhos e trinta filhas, as quais casou fora, e tomou de fora trinta filhas para seus filhos: e julgou a Israel sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'E morreu Ibsã, e foi sepultado em Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Depois dele julgou a Israel Elom, zebulonita, o qual julgou Israel por dez anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'E morreu Elom, zebulonita, e foi sepultado em Aijalom na terra de Zebulom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Depois dele julgou a Israel Abdom filho de Hilel, piratonita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Este teve quarenta filhos e trinta netos, que cavalgavam sobre setenta asnos: e julgou a Israel oito anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'E morreu Abdom filho de Hilel, piratonita, e foi sepultado em Piratom, na terra de Efraim, no monte de Amaleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'E os filhos de Israel voltaram a fazer o mal aos olhos do SENHOR; e o SENHOR os entregou por mão dos filisteus, por quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'E havia um homem de Zorá, da tribo de Dã, o qual se chamava Manoá; e sua mulher era estéril, que nunca havia dado à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'A esta mulher apareceu o anjo do SENHOR, e disse-lhe: Eis que tu és estéril, e não pariste: mas conceberás e darás à luz um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Agora, pois, olha que agora não bebas vinho, nem bebida forte, nem comas coisa imunda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Porque tu te farás grávida, e darás à luz um filho: e não subirá navalha sobre sua cabeça, porque aquele menino será nazireu a Deus desde o ventre, e ele começará a salvar a Israel da mão dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'E a mulher veio e contou-o a seu marido, dizendo: Um homem de Deus veio a mim, cujo aspecto era como o aspecto de um anjo de Deus, terrível em grande maneira; e não lhe perguntei de onde nem quem era, nem tampouco ele me disse seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'E disse-me: Eis que tu conceberás, e darás à luz um filho: portanto, agora não bebas vinho, nem bebida forte, nem comas coisa imunda; porque este menino desde o ventre será nazireu a Deus até o dia de sua morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Então orou Manoá ao SENHOR, e disse: Ah, Senhor meu, eu te rogo que aquele homem de Deus que enviaste, torne agora a vir a nós, e nos ensine o que havemos de fazer com o menino que há de nascer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'E Deus ouviu a voz de Manoá: e o anjo de Deus voltou outra vez à mulher, estando ela no campo; mas seu marido Manoá não estava com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'E a mulher correu prontamente, e noticiou-o a seu marido, dizendo-lhe: Olha que se me apareceu aquele homem que veio a mim o outro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'E levantou-se Manoá, e seguiu a sua mulher; e assim que chegou ao homem, disse-lhe: És tu aquele homem que falaste à mulher? E ele disse: Eu sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Então Manoá disse: Cumpra-se pois tua palavra. Que ordem se terá com o menino, e que deve?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'E o anjo do SENHOR respondeu a Manoá: A mulher se guardará de todas as coisas que eu lhe disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Ela não comerá coisa que proceda da vide que dá vinho; não beberá vinho nem bebida forte, e não comerá coisa imunda: há de guardar tudo o que lhe mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Então Manoá disse ao anjo do SENHOR: Rogo-te permitas que te detenhamos, e preparemos um cabrito que pôr diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'E o anjo do SENHOR respondeu a Manoá: Ainda que me detenhas não comerei de teu pão: mas se quiseres fazer holocausto, sacrifica-o ao SENHOR. E não sabia Manoá que aquele fosse anjo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Então disse Manoá ao anjo do SENHOR: Como é teu nome, para que quando se cumprir tua palavra te honremos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'E o anjo do SENHOR respondeu: Por que perguntas por meu nome, que é oculto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'E Manoá tomou um cabrito das cabras e um presente, e sacrificou-o sobre uma penha ao SENHOR: e o anjo fez milagre à vista de Manoá e de sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Porque aconteceu que quando a chama subia do altar até o céu, o anjo do SENHOR subiu na chama do altar à vista de Manoá e de sua mulher, os quais se prostraram em terra sobre seus rostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'E o anjo do SENHOR não voltou a aparecer a Manoá nem à sua mulher. Então conheceu Manoá que era o anjo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'E disse Manoá à sua mulher: Certamente morreremos, porque vimos a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'E sua mulher lhe respondeu: Se o SENHOR nos quisesse matar, não tomaria de nossas mãos o holocausto e o presente, nem nos teria mostrado todas estas coisas, nem em tal tempo nos haveria anunciado isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'E a mulher deu à luz um filho, e chamou-lhe por nome Sansão. E o menino creceu, e o SENHOR o abençoou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'E o espírito do SENHOR começou a manifestar-se nele nos acampamentos de Dã, entre Zorá e Estaol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'E descendo Sansão a Timna, viu em Timna uma mulher das filhas dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'E subiu, e declarou-o a seu pai e a sua mãe, dizendo: Eu vi em Timna uma mulher das filhas dos filisteus: rogo-vos que a deis a mim por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'E seu pai e sua mãe lhe disseram: Não há mulher entre as filhas de teus irmãos, nem em todo meu povo, para que vás tu a tomar mulher dos filisteus incircuncisos? E Sansão respondeu a seu pai: Toma-a a mim por mulher, porque esta agradou a meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Mas seu pai e sua mãe não sabiam que isto vinha do SENHOR, e que ele buscava ocasião contra os filisteus: porque naquele tempo os filisteus dominavam sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'E Sansão desceu com seu pai e com sua mãe a Timna: e quando chegaram às vinhas de Timna, eis que um leão jovem que vinha bramando até ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'E o espírito do SENHOR caiu sobre ele, e despedaçou-o como quem despedaça um cabrito, sem ter nada em sua mão: e não deu a entender a seu pai nem a sua mãe o que havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Veio, pois, e falou à mulher que havia agradado a Sansão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'E voltando depois de alguns dias para tomá-la, apartou-se para ver o corpo morto do leão, e eis que no corpo do leão um enxame de abelhas, e um favo de mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'E tomando-o em suas mãos, foi-se comendo-o pelo caminho: e chegado que houve a seu pai e a sua mãe, deu-lhes também a eles que comessem; mas não lhes revelou que havia tomado aquela mel do corpo do leão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Veio, pois, seu pai à mulher, e Sansão fez ali banquete; porque assim costumavam fazer os rapazes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'E quando eles o viram, tomaram trinta companheiros que estivessem com ele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Aos quais Sansão disse: Eu vos proporei agora um enigma, o qual se nos sete dias do banquete vós me declarardes e descobrirdes, eu vos darei trinta sábanas e trinta mudas de vestidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mas se não o souberes declarar a mim, vós me dareis as trinta mantas e as trinta mudas de vestidos. E eles responderam: Propõe-nos teu enigma, e o ouviremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Então lhes disse: Do comedor saiu comida, E do forte saiu doçura. E eles não puderam declarar-lhe o enigma em três dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'E ao sétimo dia disseram à mulher de Sansão: Induz a teu marido a que nos declare este enigma, para que não te queimemos a ti e à casa de teu pai. Chamaste-nos aqui para possuir-nos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'E chorou a mulher de Sansão diante dele, e disse: Somente me aborreces e não me amas, pois que não me declaras o enigma que propuseste aos filhos de meu povo. E ele respondeu: Eis que nem a meu pai nem a minha mãe o declarei; e havia eu de declará-lo a ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'E ela chorou diante dele os sete dias que eles tiveram banquete: mas ao sétimo dia ele o declarou a ela, porque lhe constrangeu; e ela o declarou aos filhos de seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'E ao sétimo dia, antes que o sol se pusesse, os da cidade lhe disseram: Que coisa mais doce que o mel? E que coisa mais forte que o leão? Se não arásseis com minha novilha, Nunca teríeis descoberto meu enigma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'E o espírito do SENHOR caiu sobre ele, e desceu a Asquelom, e feriu trinta homens deles; e tomando seus despojos, deu as mudas de vestidos aos que haviam explicado o enigma: e acendido em ira foi-se à casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'E a mulher de Sansão foi dada a seu companheiro, com o qual ele antes se acompanhava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'E aconteceu depois de dias, que no tempo da colheita do trigo, Sansão visitou à sua mulher com um cabrito, dizendo: Entrarei à minha mulher à câmara. Mas o pai dela não o deixou entrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'E disse o pai dela: Persuadi-me que a aborrecias, e dei-a a teu companheiro. Mas sua irmã menor, não é mais bela que ela? Toma-a, pois, em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'E Sansão lhes respondeu: Eu serei sem culpa esta vez para com os filisteus, se mal lhes fizer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'E foi Sansão e agarrou trezentas raposas, e tomando tochas, e segurando aquelas pelas caudas, pôs entre cada duas caudas uma tocha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Depois, acendendo as tochas, lançou as raposas nas plantações dos filisteus, e queimou pilhas de cereais e cereais nos pés, e vinhas e olivais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'E disseram os filisteus: Quem fez isto? E foi-lhes dito: Sansão, o genro do timnateu, porque lhe tirou sua mulher e a deu a seu companheiro. E vieram os filisteus, e queimaram a fogo a ela e a seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Então Sansão lhes disse: Assim o havíeis de fazer? Mas eu me vingarei de vós, e depois cessarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'E feriu-os perna e coxa com grande mortandade; e desceu, e ficou na caverna da penha de Etã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'E os filisteus subiram e puseram acampamento em Judá, e estenderam-se por Leí.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'E os homens de Judá lhes disseram: Por que subistes contra nós? E eles responderam: A prender a Sansão subimos, para fazer-lhe como ele nos fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'E vieram três mil homens de Judá à caverna da penha de Etã, e disseram a Sansão: Não sabes tu que os filisteus dominam sobre nós? Por que nos fizeste isto? E ele lhes respondeu: Eu lhes fiz como eles me fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Eles então lhe disseram: Nós viemos para prender-te, e entregar-te em mão dos filisteus. E Sansão lhes respondeu: Jurai-me que vós não me matareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'E eles lhe responderam, dizendo: Não, somente te prenderemos, e te entregaremos em suas mãos; mas não te mataremos. Então lhe ataram com duas cordas novas, e fizeram-lhe vir da penha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'E assim que veio até Leí, os filisteus lhe saíram a receber com gritos de vitória: e o espírito do SENHOR caiu sobre ele, e as cordas que estavam em seus braços se tornaram como linho queimado com fogo, e as amarras se caíram de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'E achando uma queixada de asno fresca, estendeu a mão e tomou-a, e feriu com ela a mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Então Sansão disse: Com a queixada de um asno, um amontoado, dois amontoados; Com a queixada de um asno feri mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'E acabando de falar, lançou de sua mão a queixada, e chamou a aquele lugar Ramate-Leí.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'E tendo grande sede, clamou logo ao SENHOR, e disse: Tu deste esta grande salvação por meio de teu servo: e morrerei eu agora de sede, e cairei em mão dos incircuncisos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Então quebrou Deus uma cavidade em Leí, e saíram dali águas, e bebeu, e recuperou seu espírito, e reanimou-se. Portanto chamou seu nome daquele lugar, En-Hacoré, o qual é em Leí, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'E julgou a Israel nos dias dos filisteus vinte anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'E foi Sansão a Gaza, e viu ali uma mulher prostituta, e se deitou com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'E foi dito aos de Gaza: Sansão veio aqui. E cercaram-no, e puseram-lhe espias toda aquela noite à porta da cidade: e estiveram calados toda aquela noite, dizendo: Até a luz da manhã; então o mataremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Mas Sansão dormiu até a meia noite; e à meia noite se levantou, e tomando as portas da cidade com seus dois pilares e seu ferrolho, lançou-as ao ombro, e foi-se, e subiu-se com elas ao cume do monte que está diante de Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Depois disto aconteceu que se apaixonou por uma mulher no vale de Soreque, a qual se chamava Dalila.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'E vieram a ela os príncipes dos filisteus, e disseram-lhe: Engana-o e sabe em que consiste sua grande força, e como o poderíamos vencer, para que o amarremos e o atormentemos; e cada um de nós te dará mil e cem siclos de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'E Dalila disse a Sansão: Eu te rogo que me declares em que consiste tua grande força, e como poderás ser acorrentado para ser atormentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'E respondeu-lhe Sansão: Se me atarem com sete vimes verdes que ainda não estejam secos, então me debilitarei, e serei como qualquer um dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'E os príncipes dos filisteus lhe trouxeram sete vimes verdes que ainda não se haviam secado, e atou-lhe com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'E estavam espias em casa dela em uma câmara. Então ela lhe disse: Sansão, os filisteus sobre ti! E ele rompeu os vimes, como se rompe uma corda de estopa quando sente o fogo: e não se soube sua força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Então Dalila disse a Sansão: Eis que tu me enganaste, e me disseste mentiras: revela-me pois agora, eu te rogo, como poderás ser acorrentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'E ele lhe disse: Se me atarem fortemente com cordas novas, com as quais nenhuma coisa se tenha feito, eu me debilitarei, e serei como qualquer um dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'E Dalila tomou cordas novas, e atou-lhe com elas, e disse-lhe: Sansão, os filisteus sobre ti! E os espias estavam em uma câmara. Mas ele as rompeu de seus braços como um fio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'E Dalila disse a Sansão: Até agora me enganas, e tratas comigo com mentiras. Revela-me pois agora como poderás ser acorrentado. Ele então lhe disse: Se teceres sete tranças de minha cabeça com a teia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'E ela fincou a estaca, e disse-lhe: Sansão, os filisteus sobre ti! Mas despertando ele de seu sonho, arrancou a estaca do tear com a teia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'E ela lhe disse: Como dizes, Eu te amo, pois que teu coração não está comigo? Já me enganaste três vezes, e não me hás ainda descoberto em que está tua grande força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'E aconteceu que, pressionando-lhe ela cada dia com suas palavras e importunando-lhe, sua alma foi reduzida à mortal angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Revelou-lhe, pois, todo seu coração, e disse-lhe: Nunca a minha cabeça chegou navalha; porque sou nazireu de Deus desde o ventre de minha mãe. Se for rapado, minha força se apartará de mim, e serei debilitado, e como todos os homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'E vendo Dalila que ele lhe havia revelado todo seu coração, mandou chamar aos príncipes dos filisteus, dizendo: Vinde esta vez, porque ele me revelou todo seu coração. E os príncipes dos filisteus vieram a ela, trazendo em sua mão o dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'E ela fez que ele dormisse sobre seus joelhos; e chamado um homem, rapou-lhe sete tranças de sua cabeça, e começou a afligi-lo, pois sua força se apartou dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'E disse-lhe: Sansão, os filisteus sobre ti! E logo que despertou ele de seu sonho, se disse: Esta vez sairei como as outras, e me escaparei: não sabendo que o SENHOR já se havia dele apartado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Mas os filisteus lançaram mão dele, e tiraram-lhe os olhos, e o levaram a Gaza; e o ataram com correntes, para que moesse no cárcere.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'E o cabelo de sua cabeça começou a crescer, depois que foi rapado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Então os príncipes dos filisteus se juntaram para oferecer sacrifício a Dagom seu deus, e para alegrar-se; e disseram: Nosso deus entregou em nossas mãos a Sansão nosso inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'E vendo-o o povo, louvaram a seu deus, dizendo: Nosso deus entregou em nossas mãos a nosso inimigo, e ao destruidor de nossa terra, o qual havia matado a muitos de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'E aconteceu que, indo-se alegrando o coração deles, disseram: Chamai a Sansão, para que divirta diante de nós. E chamaram a Sansão do cárcere, e fazia de joguete diante deles; e puseram-no entre as colunas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'E Sansão disse ao jovem que o guiava pela mão: Aproxima-me, e faze-me segurar as colunas sobre que se sustenta a casa, para que me apoie sobre elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'E a casa estava cheia de homens e mulheres: e todos os príncipes dos filisteus estavam ali; e no alto piso havia como três mil homens e mulheres, que estavam olhando o escárnio de Sansão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Então clamou Sansão ao SENHOR, e disse: Senhor DEUS, lembra-te agora de mim, e esforça-me, te rogo, somente esta vez, ó Deus, para que de uma vez tome vingança dos filisteus, por meus dois olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Agarrou logo Sansão as duas colunas do meio sobre as quais se sustentava a casa, e apoiou-se nelas, a uma com a direita, e a outra com a esquerda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'E disse Sansão: Morra eu com os filisteus. E apoiando com força, caiu a casa sobre os príncipes, e sobre todo aquele povo que estava nela. E foram muitos mais os que deles matou morrendo, que os que havia matado em sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'E desceram seus irmãos e toda a casa de seu pai, e tomaram-no, e levaram-no, e o sepultaram entre Zorá e Estaol, no sepulcro de seu pai Manoá. E ele julgou a Israel vinte anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Houve um homem do monte de Efraim, que se chamava Mica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'O qual disse à sua mãe: Os mil e cem siclos de prata que te foram furtados, pelo que tu amaldiçoavas ouvindo-o eu, eis que eu tenho este dinheiro: eu o havia tomado. Então a mãe disse: Bendito sejas do SENHOR, filho meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'E logo que ele devolveu à sua mãe os mil e cem siclos de prata, sua mãe disse: Eu dediquei este dinheiro ao SENHOR de minha mão para ti, filho meu, para que faças uma imagem de escultura e de fundição: agora, pois, eu o devolvo a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Mas voltando ele à sua mãe o dinheiro, tomou sua mãe duzentos siclos de prata, e deu-os ao fundidor: e ele lhe fez deles uma imagem de escultura e de fundição, a qual foi posta em casa de Mica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'E teve este homem Mica casa de deuses, e fez-se fazer éfode e ídolos, e consagrou um de seus filhos; e foi-lhe por sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Nestes dias não havia rei em Israel: cada um fazia como melhor lhe parecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'E havia um jovem de Belém de Judá, da tribo de Judá, o qual era levita; e peregrinava ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Este homem se havia partido da cidade de Belém de Judá, para ir a viver de onde achasse; e chegando ao monte de Efraim, veio à casa de Mica, para dali fazer seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'E Mica lhe disse: De onde vens? E o levita lhe respondeu: Sou de Belém de Judá, e vou a viver de onde achar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Então Mica lhe disse: Fica-te em minha casa, e me serás em lugar de pai e sacerdote; e eu te darei dez siclos de prata por ano, e o ordinário de vestimentas, e tua comida. E o levita ficou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Acordou, pois, o levita em morar com aquele homem, e ele o tinha como a um de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'E Mica consagrou ao levita, e aquele jovem lhe servia de sacerdote, e estava em casa de Mica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'E Mica disse: Agora sei que o SENHOR me fará bem, pois que o levita é feito meu sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Naqueles dias não havia rei em Israel. E em aqueles dias a tribo de Dã buscava possessão para si de onde morasse, porque até então não lhe havia caído sorte entre as tribos de Israel por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'E os filhos de Dã enviaram de sua tribo cinco homens de seus termos, homens valentes, de Zorá e Estaol, para que reconhecessem e explorassem bem a terra; e disseram-lhes: Ide e reconhecei a terra. Estes vieram ao monte de Efraim, até a casa de Mica, e ali passaram a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'E quando estavam próximos da casa de Mica, reconheceram a voz do jovem levita; e achegando-se ali, disseram-lhe: Quem te trouxe por aqui? e que fazes aqui? e que tens tu por aqui?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'E ele lhes respondeu: Desta e desta maneira fez comigo Mica, e me há tomado para que seja seu sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'E eles lhe disseram: Pergunta, pois, agora a Deus, para que saibamos se há de prosperar nossa viajem que fazemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'E o sacerdote lhes respondeu: Ide em paz, que vosso viajem que fazeis é diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Então aqueles cinco homens se partiram, e vieram a Laís: e viram que o povo que habitava nela estava seguro, ocioso e confiante, conforme o costume dos de Sidom; não havia ninguém naquela região que os perturbasse em coisa alguma; além disso, os sidônios estavam distantes, e não tinham negócios com ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Voltando, pois, eles a seus irmãos em Zorá e Estaol, seus irmãos lhes disseram: Que há? e eles responderam:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Levantai-vos, subamos contra eles; porque nós exploramos a região, e vimos que é muito boa: e vós vos estais quietos? Não sejais preguiçosos em vos dispor em marcha para ir a possuir a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Quando ali chegardes, vereis a uma gente segura, e a uma terra ampla; pois que Deus a entregou em vossas mãos; lugar de onde não há falta de coisa que seja na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'E partindo os de Dã dali, de Zorá e de Estaol, seiscentos homens armados de armas de guerra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Foram e assentaram acampamento em Quriate-Jearim, em Judá; de onde aquele lugar foi chamado o campo de Dã, até hoje: está detrás de Quriate-Jearim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'E passando dali ao monte de Efraim, vieram até a casa de Mica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Então aqueles cinco homens que haviam ido a reconhecer a terra de Laís, disseram a seus irmãos: Não sabeis como em estas casas há éfode e ídolos, e imagem de escultura e de fundição? Olhai pois o que haveis de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'E achegando-se ali, vieram à casa do jovem levita em casa de Mica, e perguntaram-lhe como estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'E os seiscentos homens, que eram dos filhos de Dã, estavam armados de suas armas de guerra à entrada da porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'E subindo os cinco homens que haviam ido a reconhecer a terra, entraram ali, e tomaram a imagem de escultura, e o éfode, e os ídolos, e a imagem de fundição, enquanto o sacerdote estava à entrada da porta com os seiscentos homens armados');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Entrando, pois, aqueles na casa de Mica, tomaram a imagem de escultura, o éfode, e os ídolos, e a imagem de fundição. E o sacerdote lhes disse: Que fazeis vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'E eles lhe responderam: Cala, põe a mão sobre tua boca, e vem conosco, para que sejas nosso pai e sacerdote. É melhor que tu sejas sacerdote em casa de um homem só, que de uma tribo e família de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'E alegrou-se o coração do sacerdote; o qual tomando o éfode e os ídolos, e a imagem, veio entre a gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'E eles voltaram e foram-se; e puseram os meninos, e o gado e a bagagem, diante de si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'E quando já se haviam afastado da casa de Mica, os homens que habitavam nas casas vizinhas à casa de Mica, se juntaram, e seguiram aos filhos de Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'E gritando aos de Dã, estes viraram seus rostos, e disseram a Mica: Que tens que juntaste gente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'E ele respondeu: Meus deuses que eu fiz, que levais juntamente com o sacerdote, e vos vades: que mais me resta? E a que propósito me dizeis: Que tens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'E os filhos de Dã lhe disseram: Não grites atrás de nós, não seja que os de ânimo impetuoso vos acometam, e percas também tua vida, e a vida dos teus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'E indo os filhos de Dã seu caminho, e vendo Mica que eram mais fortes que ele, voltou-se e regressou à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'E eles levando as coisas que havia feito Mica, juntamente com o sacerdote que tinha, chegaram a Laís, ao povo tranquilo e seguro; e meteram-nos à espada, e abrasaram a cidade com fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'E não houve quem os defendesse, porque estavam longe de Sidom, e não tinham comércio com ninguém. E a cidade estava no vale que há em Bete-Reobe. Logo reedificaram a cidade, e habitaram nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'E chamaram o nome daquela cidade Dã, conforme ao nome de Dã seu pai, filho de Israel, bem que antes se chamava a cidade Laís.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'E os filhos de Dã levantaram para si imagem de escultura; e Jônatas, filho de Gérson, filho de Manassés, ele e seus filhos foram sacerdotes na tribo de Dã, até o dia do cativeiro do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'E levantaram para si a imagem de Mica, a qual ele havia feito, todo aquele tempo que a casa de Deus esteve em Siló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Naqueles dias, quando não havia rei em Israel, houve um levita que morava como peregrino nos lados do monte de Efraim, o qual se havia tomado mulher concubina de Belém de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'E sua concubina adulterou contra ele, e foi-se dele à casa de seu pai, a Belém de Judá, e esteve ali por tempo de quatro meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'E levantou-se seu marido, e seguiu-a, para falar-lhe amorosamente e trazê-la de volta, levando consigo um criado seu e um par de asnos; e ela o meteu na casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'E vendo-lhe o pai da moça, saiu-lhe a receber contente; e seu sogro, pai da moça, o deteve, e ficou em sua casa três dias, comendo e bebendo, e repousando ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'E ao quarto dia, quando se levantaram de manhã, levantou-se também o levita para ir-se, e o pai da moça disse a seu genro: Conforta teu coração com um bocado de pão, e depois vos ireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'E sentaram-se eles dois juntos, e comeram e beberam. E o pai da moça disse ao homem: Eu te rogo que te queiras ficar aqui esta noite, e teu coração se alegrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'E levantando-se o homem para ir-se, o sogro lhe constrangeu a que voltasse e tivesse ali a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'E ao quinto dia levantando-se de manhã para ir-se, disse-lhe o pai da moça: Conforta agora teu coração. E havendo comido ambos a dois, detiveram-se até que já declinava o dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Levantou-se logo o homem para ir-se, ele, e sua concubina, e seu criado. Então seu sogro, o pai da moça, lhe disse: Eis que o dia declina para se pôr o sol, rogo-te que vos estejais aqui a noite; eis que o dia se acaba, passa aqui a noite, para que se alegre teu coração; e amanhã vos levantareis cedo a vosso caminho, e chegarás a tuas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mas o homem não quis ficar ali a noite, mas sim que se levantou e partiu, e chegou até em frente de Jebus, que é Jerusalém, com seu par de asnos preparados, e com sua concubina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'E estando já junto a Jebus, o dia havia declinado muito: e disse o criado a seu senhor: Vem agora, e vamo-nos a esta cidade dos jebuseus, para que tenhamos nela a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'E seu senhor lhe respondeu: Não iremos a nenhuma cidade de estrangeiros, que não seja dos filhos de Israel: antes passaremos até Gibeá. E disse a seu criado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Vem, cheguemos a um desses lugares, para ter a noite em Gibeá, ou em Ramá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Passando pois, caminharam, e o sol se pôs junto a Gibeá, que era de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'E apartaram-se do caminho para entrar a ter ali a noite em Gibeá; e entrando, sentaram-se na praça da cidade, porque não houve quem os acolhesse em casa para passar a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'E eis que um homem velho, que à tarde vinha do campo de trabalhar; o qual era do monte de Efraim, e morava como peregrino em Gibeá, mas os moradores daquele lugar eram filhos de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'E levantando o velho os olhos, viu aquele viajante na praça da cidade, e disse-lhe: Para onde vais, e de onde vens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'E ele respondeu: Passamos de Belém de Judá aos lados do monte de Efraim, de onde eu sou; e parti até Belém de Judá; e vou à casa do SENHOR, e não há quem me receba em casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Ainda que nós tenhamos palha e de comer para nossos asnos, e também temos pão e vinho para mim e para tua serva, e para o criado que está com teu servo; de nada temos falta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'E o homem velho disse: Paz seja contigo; tua necessidade toda seja somente a meu cargo, contanto que não passes a noite na praça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'E metendo-os em sua casa, deu de comer a seus asnos; e eles se lavaram os pés, e comeram e beberam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'E quando estavam jubilosos, eis que os homens daquela cidade, homens malignos, cercam a casa, e batiam as portas, dizendo ao homem velho dono da casa: Tira fora o homem que entrou em tua casa, para que o conheçamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'E saindo a eles aquele homem, amo da casa, disse-lhes: Não, irmãos meus, rogo-vos que não cometais este mal, pois que este homem entrou em minha casa, não façais esta maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Eis aqui minha filha virgem, e a concubina dele: eu as tirarei agora para vós; humilhai-as, e fazei com elas como vos parecer, e não façais a este homem coisa tão infame.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mas aqueles homens não lhe quiseram ouvir; pelo que tomando aquele homem sua concubina, tirou-a fora: e eles a conheceram, e abusaram dela toda a noite até a manhã, e deixaram-na quando apontava a alva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'E já que amanhecia, a mulher veio, e caiu diante da porta da casa daquele homem onde seu senhor estava, até que foi de dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'E levantando-se de manhã seu senhor, abriu as portas da casa, e saiu para ir seu caminho, e eis que, a mulher sua concubina estava estendida diante da porta da casa, com as mãos sobre o umbral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'E ele lhe disse: Levanta-te, e vamo-nos. Mas ela não respondeu. Então a levantou o homem, e lançando-a sobre seu asno, levantou-se e foi-se a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'E em chegando à sua casa, toma uma espada, pegou sua concubina, e despedaçou-a com seus ossos em doze partes, e enviou-as por todos os termos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'E todo aquele que o via, dizia: Jamais se fez nem visto tal coisa, desde o tempo que os filhos de Israel subiram da terra do Egito até hoje. Considerai isto, dai conselho, e falai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Então saíram todos os filhos de Israel, e reuniu-se a congregação como um só homem, desde Dã até Berseba e a terra de Gileade, ao SENHOR em Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'E os principais de todo aquele povo, de todas as tribos de Israel, se acharam presentes na reunião do povo de Deus, quatrocentos mil homens a pé que tiravam espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'E os filhos de Benjamim ouviram que os filhos de Israel haviam subido a Mispá. E disseram os filhos de Israel: Dizei como foi esta maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Então o homem levita, marido da mulher morta, respondeu e disse: Eu cheguei a Gibeá de Benjamim com minha concubina, para ter ali a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'E levantando-se contra mim os de Gibeá, cercaram sobre mim a casa de noite, com ideia de matar-me, e oprimiram minha concubina de tal maneira, que ela foi morta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Então tomando eu minha concubina, cortei-a em peças, e enviei-as por todo aquele termo da possessão de Israel: porquanto fizeram maldade e crime em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Eis que todos vós os filhos de Israel estais presentes; dai-vos aqui parecer e conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Então todo aquele povo, como um só homem, se levantou, e disseram: Nenhum de nós irá à sua tenda, nem nos apartaremos cada um à sua casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Até que façamos isto sobre Gibeá: que lancemos sortes contra ela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'E tomaremos dez homens de cada cem por todas as tribos de Israel, e de cada mil cem, e mil de cada dez mil, que levem mantimento para o povo que deve agir, indo contra Gibeá de Benjamim, conforme toda a abominação que havia cometido em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'E juntaram-se todos os homens de Israel contra a cidade, ligados como um só homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'E as tribos de Israel enviaram homens por toda a tribo de Benjamim, dizendo: Que maldade é esta que foi feita entre vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Entregai, pois, agora aqueles homens, malignos, que estão em Gibeá, para que os matemos, e varramos o mal de Israel. Mas os de Benjamim não quiseram ouvir a voz de seus irmãos os filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Antes os de Benjamim se juntaram das cidades de Gibeá, para sair a lutar contra os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'E foram contados naquele tempo os filhos de Benjamim das cidades, vinte e seis mil homens que tiravam espada, sem os que moravam em Gibeá, que foram por conta setecentos homens escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'De toda aquela gente havia setecentos homens escolhidos, que eram canhotos, todos os quais atiravam uma pedra com a funda a um fio de cabelo, e não erravam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'E foram contados os homens de Israel, fora de Benjamim, quatrocentos mil homens que tiravam espada, todos estes homens de guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Levantaram-se logo os filhos de Israel, e subiram à casa de Deus, e consultaram a Deus, dizendo: Quem subirá de nós o primeiro na guerra contra os filhos de Benjamim? E o SENHOR respondeu: Judá o primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Levantando-se, pois, de manhã os filhos de Israel, puseram acampamento contra Gibeá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'E saíram os filhos de Israel a combater contra Benjamim; e os homens de Israel ordenaram a batalha contra eles junto a Gibeá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Saindo então de Gibeá os filhos de Benjamim, derrubaram em terra aquele dia vinte e dois mil homens dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Mas reanimando-se o povo, os homens de Israel voltaram a ordenar a batalha no mesmo lugar onde a haviam ordenado o primeiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Porque os filhos de Israel subiram, e choraram diante do SENHOR até à tarde, e consultaram com o SENHOR, dizendo: Voltarei a lutar com os filhos de Benjamim meu irmão? E o SENHOR lhes respondeu: Subi contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Então os filhos de Israel se aproximaram no dia seguinte contra os filhos de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'E aquele segundo dia, saindo Benjamim de Gibeá contra eles, derrubaram por terra outros dezoito mil homens dos filhos de Israel, todos os quais tiravam espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Então subiram todos os filhos de Israel, e todo aquele povo, e vieram à casa de Deus; e choraram, e sentaram-se ali diante do SENHOR, e jejuaram naquele dia até à tarde; e sacrificaram holocaustos e pacíficos diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'E os filhos de Israel perguntaram ao SENHOR, (porque a arca do pacto de Deus estava ali naqueles dias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'E Fineias, filho de Eleazar, filho de Arão, se apresentava diante dela naqueles dias,) e disseram: Voltarei a sair em batalha contra os filhos de Benjamim meu irmão, ou ficarei quieto? E o SENHOR disse: Subi, que amanhã eu o entregarei em tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'E pôs Israel emboscadas ao redor de Gibeá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Subindo então os filhos de Israel contra os filhos de Benjamim o terceiro dia, ordenaram a batalha diante de Gibeá, como as outras vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'E saindo os filhos de Benjamim contra o povo, afastados que foram da cidade, começaram a ferir alguns do povo, matando como das outras vezes pelos caminhos, um dos quais sobe a Betel, e o outro a Gibeá no acampamento: e mataram uns trinta homens de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'E os filhos de Benjamim diziam: Derrotados são diante de nós, como antes. Mas os filhos de Israel diziam: Fugiremos, e os afastaremos da cidade até os caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Então, levantando-se todos os de Israel de seu lugar, puseram-se em ordem em Baal-Tamar: e também as emboscadas de Israel saíram de seu lugar, do prado de Gibeá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'E vieram contra Gibeá dez mil homens escolhidos de todo Israel, e a batalha começou a agravar-se: mas eles não sabiam que o mal se aproximava sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'E feriu o SENHOR a Benjamim diante de Israel; e mataram os filhos de Israel aquele dia vinte e cinco mil e cem homens de Benjamim, todos os quais tiravam espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'E viram os filhos de Benjamim que eram mortos; pois os filhos de Israel haviam dado lugar a Benjamim, porque estavam confiantes nas emboscadas que haviam posto detrás de Gibeá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Então as emboscadas atacaram prontamente Gibeá, e se estenderam, e passaram à espada toda a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Já os israelitas estavam combinados com as emboscadas, que fizessem muito fogo, para que subisse grande fumaça da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Logo, pois, que os de Israel se viraram na batalha, os de Benjamim começaram a derrubar feridos de Israel uns trinta homens, e já diziam: Certamente eles caíram diante de nós, como na primeira batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Mas quando a chama começou a subir da cidade, uma coluna de fumaça, Benjamim virou a olhar atrás; e eis que o fogo da cidade subia ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Então deram meia-volta os homens de Israel, e os de Benjamim se encheram de temor: porque viram que o mal havia vindo sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Voltaram-se, pois, de costas diante de Israel até o caminho do deserto; mas o esquadrão os alcançou, e os saídos da cidade os matavam, depois de virem ao meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Assim cercaram aos de Benjamim, e os perseguiram e pisaram, desde Menuá até em frente de Gibeá até o oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'E caíram de Benjamim dezoito mil homens, todos eles homens de guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Voltando-se logo, fugiram até o deserto, à penha de Rimom, e deles exterminaram cinco mil homens nos caminhos: foram ainda perseguindo-os até Gidom, e mataram deles dois mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Assim todos os que de Benjamim morreram aquele dia, foram vinte e cinco mil homens que tiravam espada, todos eles homens de guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Porém se voltaram e fugiram ao deserto à penha de Rimom seiscentos homens, os quais estiveram na penha de Rimom quatro meses:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'E os homens de Israel voltaram aos filhos de Benjamim, e passaram-nos à espada, a homens e animais na cidade, e tudo o que foi achado: também puseram fogo a todas as cidades que achavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'E os homens de Israel haviam jurado em Mispá, dizendo: Nenhum de nós dará sua filha aos de Benjamim por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'E veio o povo à casa de Deus, e estiveram ali até à tarde diante de Deus; e levantando sua voz fizeram grande pranto, e disseram:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Ó SENHOR Deus de Israel, por que sucedeu isto em Israel, que falte hoje de Israel uma tribo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'E ao dia seguinte o povo se levantou de manhã, e edificaram ali altar, e ofereceram holocaustos e pacíficos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'E disseram os filhos de Israel: Quem de todas as tribos de Israel não subiu à reunião próximo do SENHOR? Porque se havia feito grande juramento contra o que não subisse ao SENHOR em Mispá, dizendo: Sofrerá morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'E os filhos de Israel se arrependeram por causa de Benjamim seu irmão, e disseram: Uma tribo é hoje cortada de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Que faremos em quanto a mulheres para os que restaram? Nós juramos pelo SENHOR que não lhes temos de dar nossas filhas por mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'E disseram: Há alguém das tribos de Israel que não tenha subido ao SENHOR em Mispá? E acharam que ninguém de Jabes-Gileade havia vindo ao acampamento à reunião:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Porque o povo foi contado, e não havia ali homem dos moradores de Jabes-Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Então a congregação enviou ali doze mil homens dos mais valentes, e mandaram-lhes, dizendo: Ide e ponde à espada aos moradores de Jabes-Gileade, e as mulheres e meninos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Mas fareis desta maneira: matareis a todo homem e a toda mulher que tiver se deitado com homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'E acharam dos moradores de Jabes-Gileade quatrocentas virgens que não tinham se deitado com homem, e trouxeram-nas ao acampamento em Siló, que está na terra de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Toda a congregação enviou logo a falar aos filhos de Benjamim que estavam na penha de Rimom, e chamaram-nos em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'E voltaram então os de Benjamim; e deram-lhes por mulheres as que haviam escravo vivas das mulheres de Jabes-Gileade: mas não lhes bastaram estas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'E o povo teve dor por causa de Benjamim, de que o SENHOR houvesse feito brecha nas tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Então os anciãos da congregação disseram: Que faremos acerca de mulheres para os que restaram? Porque as mulheres tinham sido exterminadas de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'E disseram: A herança dos que escaparam será o que era de Benjamim, para que não seja uma tribo extinta de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Nós porém, não lhes podemos dar mulheres de nossas filhas, porque os filhos de Israel juraram, dizendo: Maldito o que der mulher a Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Agora bem, disseram, eis que cada ano há solenidade do SENHOR em Siló, que está ao norte de Betel, e ao lado oriental do caminho que sobe de Betel a Siquém, e ao sul de Lebona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'E mandaram aos filhos de Benjamim, dizendo: Ide, e ponde emboscadas nas vinhas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'E estai atentos: e quando virdes sair as filhas de Siló a dançar em cirandas, vós saireis das vinhas, e arrebatareis cada um mulher para si das filhas de Siló, e vos ireis à terra de Benjamim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'E quando vierem os pais delas ou seus irmãos a nos exigirem, nós lhes diremos: Tende piedade de nós em lugar deles: pois que nós na guerra não tomamos mulheres para todos: que vós não as destes a eles, para que agora sejais culpáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'E os filhos de Benjamim o fizeram assim; pois tomaram mulheres conforme seu número, tomando das que dançavam; e indo logo, voltaram-se à sua herança, e reedificaram as cidades, e habitaram nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Então os filhos de Israel se foram também dali, cada um à sua tribo e à sua família, saindo dali cada um à sua propriedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Nestes dias não havia rei em Israel; cada um fazia o que era correto diante de seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'E aconteceu nos dias que governavam os juízes, que houve fome na terra. E um homem de Belém de Judá, foi a peregrinar nos campos de Moabe, ele e sua mulher, e dois filhos seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'O nome daquele homem era Elimeleque, e o de sua mulher Noemi; e os nomes de seus dois filhos eram Malom e Quiliom, efrateus de Belém de Judá. Chegaram, pois, aos campos de Moabe, e assentaram ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'E morreu Elimeleque, marido de Noemi, e restou ela com seus dois filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Os quais tomaram para si mulheres de Moabe, o nome da uma Orfa, e o nome da outra Rute; e habitaram ali uns dez anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'E morreram também os dois, Malom e Quiliom, restando assim a mulher desamparada de seus dois filhos e de seu marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Então se levantou com suas noras, e voltou-se dos campos de Moabe: porque ouviu no campo de Moabe que o SENHOR havia visitado a seu povo para dar-lhes pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Saiu, pois, do lugar de onde havia estado, e com ela suas duas noras, e começaram em caminhar para voltar-se à terra de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'E Noemi disse a suas duas noras: Andai, voltai-vos cada uma à casa de sua mãe: o SENHOR faça convosco misericórdia, como a fizestes com os mortos e comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Dê-vos o SENHOR que acheis descanso, cada uma em casa de seu marido: beijou-as logo, e elas choraram a voz em grito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'E disseram-lhe: Certamente nós voltaremos contigo a teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'E Noemi respondeu: Voltai, filhas minhas; para que ireis comigo? Tenho eu mais filhos no ventre, que possam ser vossos maridos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Voltai, filhas minhas, e ide; que eu já sou velha para ser para me casar com homem. E ainda que dissesse: Tenho esperança; e esta noite me casasse com um homem, e ainda desse à luz filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Teríeis vós de esperá-los até que fossem grandes? Ficaríeis vós sem se casar por causa deles? Não, filhas minhas; que maior amargura tenho eu que vós, pois a mão do SENHOR saiu contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Mas elas levantando outra vez sua voz, choraram: e Orfa beijou à sua sogra, mas Rute se ficou com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'E Noemi disse: Eis que tua cunhada se voltou a seu povo e a seus deuses; volta-te atrás dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'E Rute respondeu: Não me rogues que te deixe, e que me aparte de ti: porque de onde quer que tu fores, irei eu; e de onde quer que viveres, viverei. Teu povo será meu povo, e teu Deus meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Onde tu morreres, morrerei eu, e ali serei sepultada: assim me faça o SENHOR, e assim me dê, que somente a morte fará separação entre mim e ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'E vendo Noemi que estava tão decidida a ir com ela, deixou de falar-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Andaram, pois, elas duas até que chegaram a Belém: e aconteceu que entrando em Belém, toda a cidade se comoveu por razão delas, e diziam: Não é esta Noemi?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'E ela lhes respondia: Não me chameis Noemi, mas sim me chamai Mara: porque em grande amargura me pôs o Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Eu me fui cheia, mas vazia me fez voltar o SENHOR. Por que me chamareis Noemi, já que o SENHOR deu testemunho contra mim, e o Todo-Poderoso me afligiu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Assim voltou Noemi e Rute moabita sua nora com ela; voltou dos campos de Moabe, e chegaram a Belém no princípio da colheita das cevadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'E tinha Noemi um parente de seu marido, homem poderoso e rico, da família de Elimeleque, o qual se chamava Boaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'E Rute a moabita disse a Noemi: Rogo-te que me deixes ir ao campo, e colherei espigas atrás daquele a cujos olhos achar favor. E ela lhe respondeu: Vai, filha minha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Foi, pois, e chegando, tirou espigas no campo atrás dos ceifeiros: e aconteceu porventura, que o terreno era de Boaz, o qual era da parentela de Elimeleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'E eis que Boaz veio de Belém, e disse aos ceifeiros: O SENHOR seja convosco. E eles responderam: O SENHOR te abençoe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'E Boaz disse a seu criado o supervisor dos ceifeiros: De quem é esta moça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'E o criado, supervisor dos ceifeiros, respondeu e disse: É a moça de Moabe, que voltou com Noemi dos campos de Moabe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'E disse: Rogo-te que me deixes colher e juntar atrás dos ceifeiros entre os feixes; entrou, pois, e está desde pela manhã até agora, menos um pouco que se deteve em casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Então Boaz disse á Rute: Ouve, filha minha, não vás a tirar espigas em outro campo, nem passes daqui: e aqui estarás com minhas moças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Olha bem o campo que colherem, e segue-as: porque eu mandei aos moços que não te toquem. E se tiveres sede, vai aos vasos, e bebe da água que os moços tirarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Ela então baixando seu rosto inclinou-se à terra, e disse-lhe: Por que achei favor em teus olhos para que tu me reconheças, sendo eu estrangeira?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'E respondendo Boaz, disse-lhe: Por certo se me declarou tudo o que fizeste com tua sogra depois da morte de teu marido, e que deixando teu pai e tua mãe e a terra de onde nasceste, vieste a um povo que não conheceste antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'O SENHOR recompense tua obra, e tua remuneração seja cheia pelo SENHOR Deus de Israel, que vieste para cobrir-te debaixo de suas asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'E ela disse: Senhor meu, ache eu favor diante de teus olhos; porque me consolaste, e porque falaste ao coração de tua serva, não sendo eu como uma de tuas criadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'E Boaz lhe disse à hora de comer: Achega-te aqui, e come do pão, e molha teu bocado no vinagre. E sentou-se ela junto aos ceifeiros, e ele lhe deu grãos tostados, e comeu até que se fartou e lhe sobrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Levantou-se logo para tirar espigas. E Boaz mandou a seus criados, dizendo: Colha também espigas entre os feixes, e não a envergonheis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Antes lançareis de propósito dos feixes, e a deixareis que colha, e não a repreendais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'E tirou espigas no campo até à tarde, e debulhou o que havia colhido, e foi como um efa de cevada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'E tomou-o, e veio à cidade; e sua sogra viu o que havia colhido. Tirou também logo o que lhe havia sobrado depois de farta, e deu-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'E disse-lhe sua sogra: Onde tiraste espigas hoje? e onde trabalhaste? Bendito seja o que te reconheceu. E ela declarou à sua sogra o que lhe havia acontecido com aquele, e disse: O nome do homem com quem hoje trabalhei é Boaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'E disse Noemi à sua nora: Seja ele bendito do SENHOR, pois que não recusou aos vivos a benevolência que teve para com os finados. Disse-lhe depois Noemi: Nosso parente é aquele homem, e de nossos remidores é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'E Rute moabita disse: a mais disto me disse: Junta-te com meus criados, até que tenham acabado toda minha colheita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'E Noemi respondeu a Rute sua nora: Melhor é, filha minha, que saias com suas criadas, que não que te encontrem em outro campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Esteve, pois, junto com as moças de Boaz tirando espigas, até que a colheita das cevadas e a dos trigos foi acabada; mas com sua sogra habitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'E disse-lhe sua sogra Noemi: Filha minha, não tenho de buscar descanso a ti, para que fiques bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Não é Boaz nosso parente, com cujas moças tu tens estado? Eis que ele aventa esta noite a os grãos de cevada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Tu te lavarás, pois, e te ungirás, e vestindo-te tuas vestes, passarás à eira; mas não te darás a conhecer ao homem até que ele tenha acabado de comer e de beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'E quando ele se deitar, repara tu o lugar de onde ele se deitará, e irás, e descobrirás os pés, e te deitarás ali; e ele te dirá o que tenhas de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'E lhe respondeu: Farei tudo o que tu me mandares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Desceu, pois à eira, e fez tudo o que sua sogra lhe havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'E quando Boaz havia comido e bebido, e seu coração esteve contente, retirou-se para dormir a um lado do amontoado. Então ela veio caladamente, e revelou os pés, e deitou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'E aconteceu, que à meia noite se estremeceu aquele homem, e apalpou: e eis que, a mulher que estava deitada a seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Então ele disse: Quem és? E ela respondeu: Eu sou Rute tua serva: estende a borda de tua capa sobre tua serva, porquanto és parente próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'E ele disse: Bendita sejas tu do SENHOR, filha minha; que fizeste melhor tua última bondade que a primeira, não indo atrás dos rapazes, sejam pobres ou ricos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Agora, pois, não temas, filha minha: eu farei contigo o que tu disseres, pois que toda a porta de meu povo sabe que és mulher virtuosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'E agora, ainda que seja certo que eu sou parente próximo, contudo isso há parente mais próximo que eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Repousa esta noite, e quando for de dia, se ele te redimir, bem, redima-te; mas se ele não te quiser redimir, eu te redimirei, vive o SENHOR. Descansa, pois, até a manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'E depois que repousou a seus pés até a manhã, levantou-se, antes que ninguém pudesse conhecer a outro. E ele disse: Não se saiba que tenha vindo mulher à eira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Depois lhe disse: Aproxima o lenço que trazes sobre ti, e segura-o. E enquanto ela o segurava, ele mediu seis medidas de cevada, e as pôs às costas: e veio ela à cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Assim que veio à sua sogra, esta lhe disse: Que houve, minha filha? E ela lhe declarou ela tudo o que com aquele homem lhe havia acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'E disse: Estas seis medidas de cevada me deu, dizendo-me: Porque não vás vazia à tua sogra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Então Noemi disse: Repousa, filha minha, até que saibas como a coisa se sucede; porque aquele homem não parará até que hoje conclua o negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'E Boaz subiu à porta da cidade e sentou-se ali: e eis que passava aquele parente do qual havia Boaz falado, e disse-lhe: Ei, fulano, vem aqui e senta-te. E ele veio, e sentou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Então ele tomou dez homens dos anciãos da cidade, e disse: Sentai-vos aqui. E eles se sentaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Logo disse ao parente: Noemi, que voltou do campo de Moabe, vende uma parte das terras que teve nosso irmão Elimeleque;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'E eu decidi fazê-lo saber a ti, e dizer-te que a tomes diante dos que estão aqui sentados, e diante dos anciãos de meu povo. Se houveres de redimir, redime; e se não quiseres redimir, declara-o a mim para que eu o saiba: porque não há outro que redima a não ser tu, e eu depois de ti. E ele respondeu: Eu redimirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Então replicou Boaz: O mesmo dia que tomares as terras da mão de Noemi, hás de tomar também a Rute moabita, mulher do defunto, para que suscites o nome do morto sobre sua possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'E respondeu o parente: Não posso redimir por minha parte, porque lançaria a perder minha propriedade: redime tu usando de meu direito, porque eu não poderei redimir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Havia já de longo tempo este costume em Israel na remissão ou contrato, que para a confirmação de qualquer negócio, o um se tirava o sapato e o dava a seu companheiro: e este era o testemunho em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Então o parente disse a Boaz: Toma-o tu. E descalçou seu sapato.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'E Boaz disse aos anciãos e a todo aquele povo: Vós sois hoje testemunhas de que tomo todas as coisas que foram de Elimeleque, e tudo o que foi de Quiliom e de Malom, da mão de Noemi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'E que também tomo por minha mulher a Rute moabita, mulher de Malom, para suscitar o nome do defunto sobre sua herança, para que o nome do morto não se apague dentre seus irmãos e da porta de seu lugar. Vós sois hoje testemunhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'E disseram todos os do povo que estavam à porta com os anciãos: Testemunhas somos. O SENHOR faça à mulher que entra em tua casa como a Raquel e a Lia, as quais duas edificaram a casa de Israel; e tu sejas ilustre em Efrata, e tenhas renome em Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'E da semente que o SENHOR te der desta moça, seja tua casa como a casa de Perez, o que Tamar deu a Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Então Boaz tomou a Rute, e ela foi sua mulher; e logo que entrou a ela, o SENHOR lhe deu que concebesse e desse à luz um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'E as mulheres diziam a Noemi: Louvado seja o SENHOR, que fez que não te faltasse hoje parente, cujo nome será nomeado em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'O qual será restaurador de tua alma, e o que sustentará tua velhice; pois que tua nora, a qual te ama e te vale mais que sete filhos, o fez nascer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'E tomando Noemi o filho, o pôs em seu colo, e foi-lhe sua ama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'E as vizinhas dizendo, a Noemi nasceu um filho, lhe puseram nome; e chamaram-lhe Obede. Este é pai de Jessé, pai de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'E estas são as gerações de Perez: Perez gerou a Hezrom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'E Hezrom gerou a Rão, e Rão gerou a Aminadabe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'E Aminadabe gerou a Naassom, e Naassom gerou a Salmom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'E Salmom gerou a Boaz, e Boaz gerou a Obede;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'E Obede gerou a Jessé, e Jessé gerou a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Houve um homem de Ramataim de Zofim, do monte de Efraim, que se chamava Elcana, filho de Jeroão, filho de Eliú, filho de Toú, filho de Zufe, efraimita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'E tinha ele duas mulheres; o nome da uma era Ana, e o nome da outra Penina. E Penina tinha filhos, mas Ana não os tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'E subia aquele homem todos os anos de sua cidade, a adorar e sacrificar ao SENHOR dos exércitos em Siló, de onde estavam dois filhos de Eli, Hofni e Fineias, sacerdotes do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'E quando vinha o dia, Elcana sacrificava, e dava a Penina sua mulher, e a todos seus filhos e a todas suas filhas, a cada um sua parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Mas a Ana dava uma parte escolhida; porque amava a Ana, ainda que o SENHOR houvesse fechado sua madre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'E sua concorrente a irritava, irando-a e entristecendo-a, porque o SENHOR havia fechado sua madre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'E assim fazia cada ano: quando subia à casa do SENHOR, irritava assim à outra; pelo qual ela chorava, e não comia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'E Elcana seu marido lhe disse: Ana, por que choras? Por que não comes? E por que está afligido teu coração? Não te sou eu melhor que dez filhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'E levantou-se Ana depois que havia comido e bebido em Siló; e enquanto o sacerdote Eli estava sentado em uma cadeira junto a um pilar do templo do SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Ela com amargura de alma orou ao SENHOR, e chorou abundantemente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'E fez um voto, dizendo: “SENHOR dos exércitos, se olhares a aflição da tua serva, e te lembrares de mim, e não te esqueceres da tua serva, mas deres à tua serva um filho homem, eu o dedicarei ao SENHOR todos os dias da sua vida, e não subirá navalha sobre sua cabeça”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'E sucedeu que, enquanto ela continuava a orar diante do SENHOR, Eli observava a sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Mas Ana falava em seu coração, e somente se moviam seus lábios, e sua voz não se ouvia; e pensava Eli que ela estava embriagada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Então, disse-lhe Eli: “Até quando estarás embriagada? Afasta-te do vinho”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'E Ana lhe respondeu: Não, meu senhor; eu sou uma mulher sofredora de espírito. Não bebi vinho nem bebida forte, mas tenho derramado minha alma diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Não consideres a tua serva como mulher ímpia, porque é da grandeza das minhas angústias e da minha aflição que tenho falado até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'E Eli respondeu: “Vai em paz, e o Deus de Israel te conceda o pedido que lhe fizeste”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'E ela disse: “Que a tua serva ache favor diante de teus olhos”. E a mulher se foi seu caminho, e comeu, e não esteve mais triste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'E levantando-se de manhã, adoraram diante do SENHOR, e voltaram, e vieram a sua casa em Ramá. E Elcana se deitou com sua mulher Ana, e o SENHOR se lembrou dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'E sucedeu que, corrido o tempo, depois de Ana haver concebido, deu à luz um filho, e pôs-lhe o nome de Samuel, dizendo: “Pois eu o pedi ao SENHOR”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Depois subiu o homem Elcana, com toda sua família, a sacrificar ao SENHOR o sacrifício costumeiro, e seu voto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Mas Ana não subiu, mas sim disse a seu marido: Eu não subirei até que o menino seja desmamado; para que o leve e seja apresentado diante do SENHOR, e fique ali para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'E Elcana seu marido lhe respondeu: Faze o que bem te parecer; fica-te até que o desmames; somente o SENHOR cumpra sua palavra. E ficou a mulher, e creu seu filho até que o desmamou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'E depois que o desmamou, levou-o consigo, com três bezerros, e um efa de farinha, e uma vasilha de vinho, e trouxe-o à casa do SENHOR em Siló: e o menino era pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'E matando o bezerro, trouxeram o menino a Eli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'E ela disse: Oh, senhor meu! Vive tua alma, senhor meu, eu sou aquela mulher que esteve aqui junto a ti orando ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Por este menino orava, e o SENHOR me deu o que lhe pedi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Eu, pois, o devolvo também ao SENHOR: todos os dias que viver, será do SENHOR. E adorou ali ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'E Ana orou e disse: Meu coração se regozija no SENHOR, Meu poder é exaltado no SENHOR; Minha boca fala triunfante sobre meus inimigos, Porquanto me alegrei em tua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Não há santo como o SENHOR: Porque não há ninguém além de ti; E não há refúgio como o nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Não faleis tantas coisas soberbas; Cessem as palavras arrogantes de vossa boca; Porque o Deus de todo conhecimento é o SENHOR, E a ele cabe pesar as ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Os arcos dos fortes foram quebrados, E os fracos se cingiram de força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Os fartos se alugaram por pão: E cessaram os famintos: Até a estéril deu à luz sete, E a que tinha muitos filhos enfermou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'O SENHOR mata, e ele dá vida: Ele faz descer ao sepulcro, e faz subir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'O SENHOR empobrece, e ele enriquece: Abate, e exalta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Ele levanta do pó ao pobre, E ao necessitado exalta do esterco, Para assentá-lo com os príncipes; E faz que tenham por propriedade assento de honra: Porque do SENHOR são as colunas da terra, E ele assentou sobre elas o mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Ele guarda os pés de seus santos, Mas os ímpios perecem em trevas; Porque ninguém será forte por sua força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Diante do SENHOR serão quebrantados seus adversários, E sobre eles trovejará desde os céus: o SENHOR julgará os termos da terra, E dará força a seu Rei, E exaltará o poder de seu ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'E Elcana se voltou a sua casa em Ramá; e o menino ministrava ao SENHOR diante do sacerdote Eli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Mas os filhos de Eli eram homens ímpios, e não tinham conhecimento do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'E o costume dos sacerdotes com o povo era que, quando alguém oferecia sacrifício, vinha o criado do sacerdote enquanto a carne estava a cozer, trazendo em sua mão um garfo de três ganchos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'E enfiava com ele na caldeira, ou na caçarola, ou no caldeirão, ou no pote; e tudo o que tirava o garfo, o sacerdote o tomava para si. Desta maneira faziam a todo israelita que vinha a Siló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Também, antes de queimar a gordura, vinha o criado do sacerdote, e dizia ao que sacrificava: Da carne que asse para o sacerdote; porque não tomará de ti carne cozida, mas sim crua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'E se lhe respondia o homem, Queimem logo a gordura hoje, e depois toma tanta quanto quiseres; ele respondia: Não, mas sim agora a darás: de outra maneira eu a tomarei por força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Era, pois, o pecado dos moços muito grande diante do SENHOR; porque os homens menosprezavam os sacrifícios do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'E o jovem Samuel ministrava diante do SENHOR, vestido de um éfode de linho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'E fazia-lhe sua mãe uma túnica pequena, e a trazia a ele a cada ano, quando subia com seu marido a oferecer o sacrifício costumeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'E Eli abençoou a Elcana e a sua mulher, dizendo: o SENHOR te dê semente desta mulher em lugar desta petição que fez ao SENHOR. E voltaram a sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'E visitou o SENHOR a Ana, e concebeu, e pariu três filhos, e duas filhas. E o jovem Samuel crescia diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli, porém, era muito velho, e ouviu tudo o que seus filhos faziam a todo Israel, e como dormiam com as mulheres que ficavam a postos à porta do tabernáculo do testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'E disse-lhes: Por que fazeis coisas semelhantes? Porque eu ouço de todo este povo vossos maus procederes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Não, filhos meus; porque não é boa fama a que eu ouço: que fazeis pecar ao povo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Se pecar o homem contra o homem, os juízes lhe julgarão; mas se alguém pecar contra o SENHOR, quem rogará por ele? Mas eles não ouviram a voz de seu pai, porque o SENHOR os queria matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'E o jovem Samuel ia crescendo e sendo bem estimando diante de Deus e diante dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'E veio um homem de Deus a Eli, e disse-lhe: Assim disse o SENHOR: Não me manifestei eu claramente à casa de teu pai, quando estavam em Egito em casa de Faraó?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'E eu lhe escolhi por meu sacerdote entre todas as tribos de Israel, para que oferecesse sobre meu altar, e queimasse incenso, e trouxesse éfode diante de mim; e dei à casa de teu pai todas as ofertas dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Por que pisaste meus sacrifícios e minhas ofertas, que eu mandei oferecer no tabernáculo; e honraste a teus filhos mais que a mim, engordando-vos do principal de todas as ofertas de meu povo Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Portanto, o SENHOR o Deus de Israel disse: Eu havia dito que tua casa e a casa de teu pai andariam diante de mim perpetuamente; mas agora disse o SENHOR: Nunca eu tal faça, porque eu honrarei aos que me honram, e os que me desprezarem serão rejeitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Eis que vêm dias, em que cortarei o teu braço, e o braço da casa de teu pai, para que não haja velho em tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'E verás competidor no tabernáculo, em todas as coisas em que fizer bem a Israel; e em nenhum tempo haverá velho em tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'E não te cortarei de todo homem de meu altar, para fazer-te consumir os teus olhos, e encher teu ânimo de dor; mas toda a descendência de tua casa morrerá no princípio da fase adulta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'E te será por sinal isto que acontecerá a teus dois filhos, Hofni e Fineias: ambos morrerão em um dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'E eu suscitarei para mim um sacerdote fiel, que faça conforme o meu coração e a minha alma; e eu lhe edificarei casa firme, e andará diante de meu ungido todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'E será que o que houver restado em tua casa, virá a prostrar-se-lhe por um dinheiro de prata e um bocado de pão, dizendo-lhe: Rogo-te que me constituas em algum ministério, para que coma um bocado de pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'E o jovem Samuel ministrava ao SENHOR diante de Eli: e a palavra do SENHOR era rara naqueles dias; não havia visão manifesta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'E aconteceu um dia, que estando Eli deitado em seu aposento, quando seus olhos começavam a escurecer-se, que não podia ver,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Samuel estava dormindo no templo do SENHOR, de onde a arca de Deus estava: e antes que a lâmpada de Deus fosse apagada,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'o SENHOR chamou a Samuel; e ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'E correndo logo a Eli, disse: Eis-me aqui; para que me chamaste? E Eli lhe disse: Eu não chamei; volta-te a deitar. E ele se voltou, e deitou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'E o SENHOR voltou a chamar outra vez a Samuel. E levantando-se Samuel veio a Eli, e disse: Eis-me aqui; para que me chamaste? E ele disse: Filho meu, eu não chamei; volta, e deita-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'E Samuel não havia conhecido ainda ao SENHOR, nem a palavra do SENHOR lhe havia sido revelada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'O SENHOR, então, chamou pela terceira vez a Samuel. E ele levantando-se veio a Eli, e disse: Eis-me aqui; para que me chamaste? Então entendeu Eli que o SENHOR chamava ao jovem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'E disse Eli a Samuel: Vai, e deita-te: e se te chamar, dirás: Fala, SENHOR, que teu servo ouve. Assim se foi Samuel, e deitou-se em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'E veio o SENHOR, e ficou ali, e chamou como das outras vezes: Samuel, Samuel! Então Samuel disse: Fala, que o teu servo está ouvindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'E o SENHOR disse a Samuel: Eis que farei eu uma coisa em Israel, que a quem a ouvir, lhe retinirão ambos ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Aquele dia eu despertarei contra Eli todas as coisas que disse sobre sua casa. Em começando, acabarei também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'E lhe mostrarei que eu julgarei sua casa para sempre, pela iniquidade que ele sabe; porque seus filhos se corromperam, e ele não os repreendeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'E portanto eu jurei à casa de Eli, que a iniquidade da casa de Eli não será expiada jamais, nem com sacrifícios nem com ofertas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'E Samuel esteve deitado até a manhã, e abriu as portas da casa do SENHOR. E Samuel temia revelar a visão a Eli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Chamando, pois, Eli a Samuel, disse-lhe: Filho meu, Samuel. E ele respondeu: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'E disse: Que é a palavra que te falou o SENHOR? Rogo-te que não a encubras a mim; assim te faça Deus e assim te acrescente, se me encobrires palavra de tudo o que falou contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'E Samuel se o manifestou tudo, sem encobrir-lhe nada. Então ele disse: o SENHOR é; faça o que bem lhe parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'E Samuel cresceu, e o SENHOR foi com ele, e não deixou cair por terra nenhuma de suas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'E conheceu todo Israel desde Dã até Berseba, que Samuel era fiel profeta do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Assim voltou o SENHOR a aparecer em Siló: porque o SENHOR se manifestou a Samuel em Siló com palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'E Samuel falou a todo Israel. Por aquele tempo saiu Israel a encontrar em batalha aos filisteus, e assentou campo junto a Ebenézer, e os filisteus assentaram o seu em Afeque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'E os filisteus apresentaram a batalha a Israel; e travando-se o combate, Israel foi vencido diante dos filisteus, os quais feriram na batalha pelo campo como quatro mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'E voltado que houve o povo ao acampamento, os anciãos de Israel disseram: Por que nos feriu hoje o SENHOR diante dos filisteus? Tragamos a nós de Siló a arca do pacto do SENHOR, para que vindo entre nós nos salve da mão de nossos inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'E enviou o povo a Siló, e trouxeram dali a arca do pacto do SENHOR dos exércitos, que estava assentado entre os querubins; e os dois filhos de Eli, Hofni e Fineias, estavam ali com a arca do pacto de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'E aconteceu que, quando a arca do pacto do SENHOR veio ao campo, todo Israel deu grito com tão grande júbilo, que a terra tremeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'E quando os filisteus ouviram a voz de júbilo, disseram: Que voz de grande júbilo é esta no campo dos hebreus? E souberam que a arca do SENHOR havia vindo ao campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'E os filisteus tiveram medo, porque diziam: Veio Deus ao campo. E disseram: Ai de nós! pois antes de agora não foi assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Ai de nós! Quem nos livrará das mãos destes deuses fortes? Estes são os deuses que feriram ao Egito com toda praga no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Esforçai-vos, ó filisteus, e sede homens, porque não sirvais aos hebreus, como eles vos serviram a vós: sede homens, e lutai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Lutaram, pois, os filisteus, e Israel foi vencido, e fugiram cada qual a suas tendas; e foi feita muito grande mortandade, pois caíram de Israel trinta mil homens a pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'E a arca de Deus foi tomada, e morreram os dois filhos de Eli, Hofni e Fineias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'E correndo da batalha um homem de Benjamim, veio naquele dia a Siló, com suas roupas rasgadas e com terra sobre sua cabeça:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'E quando chegou, eis que Eli que estava sentado em uma cadeira vigiando junto ao caminho; porque seu coração estava tremendo por causa da arca de Deus. Chegado pois aquele homem à cidade, e dadas as novas, toda a cidade gritou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'E quando Eli ouviu o estrondo da gritaria, disse: Que estrondo de alvoroço é este? E aquele homem veio depressa, e deu as novas a Eli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Era já Eli de idade de noventa e oito anos, e seus olhos se haviam entenebrecido, de modo que não podia ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Disse, pois, aquele homem a Eli: Eu venho da batalha, eu escapei hoje do combate. E ele disse: Que aconteceu, filho meu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'E o mensageiro respondeu, e disse: Israel fugiu diante dos filisteus, e também foi feita grande mortandade no povo; e também teus dois filhos, Hofni e Fineias, são mortos, e a arca de Deus foi tomada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'E aconteceu que quando ele fez menção da arca de Deus, Eli caiu até atrás da cadeira ao lado da porta, e o seu pescoço se quebrou, e ele morreu: porque era homem velho e pesado. E havia julgado a Israel quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'E sua nora, a mulher de Fineias, que estava grávida, próxima ao parto, ouvindo a notícia que a arca de Deus havia sido tomada, e mortos seu sogro e seu marido, encurvou-se e teve o parto; porque suas dores vieram sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'E ao tempo em que morria, diziam-lhe as que estavam junto a ela: Não tenhas medo, porque deste à luz um filho. Mas ela não respondeu, nem deu atenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'E chamou ao menino Icabode, dizendo: Passada foi a glória de Israel! Por causa arca de Deus que foi tomada, e porque era morto seu sogro, e seu marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Disse, pois: Passada foi a glória de Israel; porque a arca de Deus foi tomada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'E os filisteus, depois de tomarem a arca de Deus, trouxeram-na desde Ebenézer a Asdode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'E tomaram os filisteus a arca de Deus, e meteram-na na casa de Dagom, e puseram-na junto a Dagom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'E o seguinte dia os de Asdode se levantaram de manhã, e eis Dagom prostrado em terra diante da arca do SENHOR: e tomaram a Dagom, e voltaram-no a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'E voltando-se a levantar de manhã o dia seguinte, eis que Dagom havia caído prostrado em terra diante da arca do SENHOR; e a cabeça de Dagom, e as duas palmas de suas mãos estavam cortadas sobre o umbral, havendo restado a Dagom o tronco somente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Por esta causa os sacerdotes de Dagom, e todos os que no templo de Dagom entram, não pisam o umbral de Dagom em Asdode, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Porém agravou-se a mão do SENHOR sobre os de Asdode, e assolou-os, e feriu-os com chagas em Asdode e em todos seus termos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'E vendo isto os de Asdode, disseram: Não fique conosco a arca do Deus de Israel, porque sua mão é dura sobre nós, e sobre nosso deus Dagom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Mandaram, pois, juntar a si todos os príncipes dos filisteus, e disseram: Que faremos da arca do Deus de Israel? E eles responderam: Passe-se a arca do Deus de Israel a Gate. E passaram ali a arca do Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'E aconteceu que quando a houveram passado, a mão do SENHOR foi contra a cidade com grande tormento; e feriu os homens daquela cidade desde o pequeno até o grande, que se encheram de chagas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Então enviaram a arca de Deus a Ecrom. E quando a arca de Deus veio a Ecrom, os ecronitas deram vozes dizendo: Passaram a mim a arca do Deus de Israel para matar a mim e a meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'E enviaram a juntar todos os príncipes dos filisteus, dizendo: Despachai a arca do Deus de Israel, e torne-se a seu lugar, e não mate a mim nem a meu povo: porque havia tormento de morte em toda a cidade, e a mão de Deus se havia ali agravado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'E os que não morriam, eram feridos de chagas; e o clamor da cidade subia ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'E esteve a arca do SENHOR na terra dos filisteus sete meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Então os filisteus, chamando os sacerdotes e adivinhos, perguntaram: Que faremos da arca do SENHOR? Declarai-nos como a devemos tornar a enviar a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'E eles disseram: Se enviais a arca do Deus de Israel, não a envieis vazia; mas lhe pagareis a expiação: e então sereis sãos, e conhecereis por que não se afastou de vós sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'E eles disseram: E que será a expiação que lhe pagaremos? E eles responderam: Conforme o número dos príncipes dos filisteus, cinco chagas de ouro, e cinco ratos de ouro, porque a mesma praga que todos têm, têm também vossos príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Fareis, pois, as formas de vossas chagas, e as formas de vossos ratos que destroem a terra, e dareis glória ao Deus de Israel: talvez aliviará sua mão de sobre vós, e de sobre vossos deuses, e de sobre vossa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Mas por que endureceis vosso coração, como os egípcios e Faraó endureceram seu coração? Depois que os houve assim tratado, não os deixaram que se fossem, e se foram?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Fazei, pois, agora um carro novo, e tomai logo duas vacas que criem, às quais não haja sido posto jugo, e preparai as vacas ao carro, e fazei voltar de detrás delas seus bezerros a casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Tomareis logo a arca do SENHOR, e a poreis sobre o carro; e ponde em uma caixa ao lado dela as joias de ouro que lhe pagais em expiação: e a deixareis que se vá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'E olhai: se sobe pelo caminho de seu termo a Bete-Semes, ele nos fez este mal tão grande; e se não, teremos certeza de que não foi sua mão que nos feriu, mas nos foi coincidência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'E aqueles homens o fizeram assim; pois tomando duas vacas que criavam, prepararam-nas ao carro, e encerraram em casa seus bezerros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Logo puseram a arca do SENHOR sobre o carro, e a caixa com os ratos de ouro e com as formas de suas chagas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'E as vacas se encaminharam pelo caminho de Bete-Semes, e iam por um mesmo caminho andando e bramando, sem desviar-se nem à direita nem à esquerda: e os príncipes dos filisteus foram atrás elas até o termo de Bete-Semes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'E os de Bete-Semes ceifavam o trigo no vale; e levantando seus olhos viram a arca, e alegraram-se quando a viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'E o carro veio ao campo de Josué Bete-Semita, e parou ali porque ali havia uma grande pedra; e eles cortaram a madeira do carro, e ofereceram as vacas em holocausto ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'E os levitas baixaram a arca do SENHOR, e a caixa que estava junto a ela, na qual estavam as joias de ouro, e puseram-nas sobre aquela grande pedra; e os homens de Bete-Semes sacrificaram holocaustos e mataram vítimas ao SENHOR naquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'O qual vendo os cinco príncipes dos filisteus, voltaram a Ecrom o mesmo dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Estas, pois, são as chagas de ouro que pagaram os filisteus ao SENHOR em expiação: por Asdode uma, por Gaza uma, por Asquelom uma, por Gate uma, por Ecrom uma;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'E ratos de ouro conforme ao número de todas as cidades dos filisteus pertencentes aos cinco príncipes, desde as cidades fortes até as aldeias sem muro; e até a grande pedra sobre a qual puseram a arca do SENHOR, pedra que está no campo de Josué, bete-semita, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Então feriu Deus aos de Bete-Semes, porque haviam olhado no arca do SENHOR; feriu no povo cinquenta mil e setenta homens. E o povo pôs luto, porque o SENHOR lhe havia ferido de tão grande praga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'E disseram os de Bete-Semes: Quem poderá estar diante do SENHOR o Deus santo? e a quem subirá desde nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'E enviaram mensageiros aos de Quriate-Jearim, dizendo: Os filisteus devolveram a arca do SENHOR: descei, pois, e levai-a a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'E vieram os de Quriate-Jearim, e levaram a arca do SENHOR, e meteram-na em casa de Abinadabe, situada no morro; e santificaram a Eleazar seu filho, para que guardasse a arca do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'E aconteceu que desde o dia que chegou a arca a Quriate-Jearim passaram muito dias, vinte anos; e toda a casa de Israel se lamentou, voltando a seguir o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'E falou Samuel a toda a casa de Israel, dizendo: Se de todo vosso coração vos volteis ao SENHOR, tirai os deuses alheios e a Astarote de entre vós, e preparai vosso coração ao SENHOR, e a somente ele servi, e vos livrará da mão dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Então os filhos de Israel tiraram aos baalins e a Astarote, e serviram a somente o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'E Samuel disse: Juntai a todo Israel em Mispá, e eu orarei por vós ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'E juntando-se em Mispá, tiraram água, e derramaram-na diante do SENHOR, e jejuaram aquele dia, e disseram ali: Contra o SENHOR temos pecado. E julgou Samuel aos filhos de Israel em Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'E ouvindo os filisteus que os filhos de Israel estavam reunidos em Mispá, subiram os príncipes dos filisteus contra Israel: o qual quando houveram ouvido os filhos de Israel, tiveram temor dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'E disseram os filhos de Israel a Samuel: Não cesses de clamar por nós ao SENHOR nosso Deus, que nos guarde da mão dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'E Samuel tomou um cordeiro que ainda amamentava, e sacrificou-o inteiro ao SENHOR em holocausto: e clamou Samuel ao SENHOR por Israel, e o SENHOR lhe ouviu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'E aconteceu que estando Samuel sacrificando o holocausto, os filisteus chegaram para lutar com os filhos de Israel. Mas o SENHOR trovejou aquele dia com grande estrondo sobre os filisteus, e desbaratou-os, e foram vencidos diante de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'E saindo os filhos de Israel de Mispá, seguiram aos filisteus, ferindo-os até abaixo de Bete-Car.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Tomou logo Samuel uma pedra, e a pôs entre Mispá e Sem, e pôs-lhe por nome Ebenézer, dizendo: Até aqui nos ajudou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Foram, pois, os filisteus humilhados, que não vieram mais ao termo de Israel; e a mão do SENHOR foi contra os filisteus todo o tempo de Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'E foram restituídas aos filhos de Israel as cidades que os filisteus haviam tomado aos israelitas, desde Ecrom até Gate, com seus termos: e Israel as livrou da mão dos filisteus. E houve paz entre Israel e o amorreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'E julgou Samuel a Israel todo o tempo que viveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'E todos os anos ia e dava volta a Betel, e a Gilgal, e a Mispá, e julgava a Israel em todos estes lugares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Voltava-se depois a Ramá, porque ali estava sua casa, e ali julgava a Israel; e edificou ali altar ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'E aconteceu que havendo Samuel envelhecido, pôs seus filhos por juízes sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'E o nome de seu filho primogênito foi Joel, e o nome do segundo, Abias: foram juízes em Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Mas não andaram os filhos pelos caminhos de seu pai, antes se inclinaram atrás a ganância, recebendo suborno e pervertendo o direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Então todos os anciãos de Israel se juntaram, e vieram a Samuel em Ramá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'E disseram-lhe: Eis que tu envelheceste, e teus filhos não vão por teus caminhos: portanto, constitui-nos agora um rei que nos julgue, como todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'E descontentou a Samuel esta palavra que disseram: Dá-nos rei que nos julgue. E Samuel orou ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'E disse o SENHOR a Samuel: Ouve a voz do povo em tudo o que te disserem: porque não rejeitaram a ti, mas sim a mim me rejeitaram, para que eu não reine sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Conforme todas as obras que fizeram desde o dia que os tirei do Egito até hoje, que me deixaram e serviram a deuses alheios, assim fazem também contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Agora, pois, ouve sua voz: mas protesta contra eles declarando-lhes o direito do rei que há de reinar sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'E disse Samuel todas as palavras do SENHOR ao povo que lhe havia pedido rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Disse, pois: Este será o direito do rei que houver de reinar sobre vós: tomará vossos filhos, e os porá em seus carros, e em seus cavaleiros, para que corram diante de seu carro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'E se escolherá capitães de mil, e capitães de cinquenta: os porá também a que arem seus campos, e ceifem suas plantações, e a que façam suas armas de guerra, e os equipamentos de seus carros:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Tomará também vossas filhas para que sejam perfumistas, cozinheiras, e padeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Também tomará vossas terras, vossas vinhas, e vossos bons olivais, e os dará a seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Ele tomará o dízimo de vossas sementes e vossas vinhas, para dar a seus eunucos e a seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Ele tomará vossos servos, e vossas servas, e vossos bons rapazes, e vossos asnos, e com eles fará suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Tomará o dízimo também do vosso rebanho, e sereis seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'E clamareis aquele dia por causa de vosso rei que vos havereis escolhido, mas o SENHOR não vos ouvirá naquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Porém o povo não quis ouvir a voz de Samuel; antes disseram: Não, mas sim que haverá rei sobre nós:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'E nós seremos também como todas as nações, e nosso rei nos governará, e sairá diante de nós, e fará nossas guerras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'E ouviu Samuel todas as palavras do povo, e referiu-as aos ouvidos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'E o SENHOR disse a Samuel: Ouve sua voz, e põe rei sobre eles. Então disse Samuel aos homens de Israel: Ide-vos cada um à sua cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'E havia um homem de Benjamim, homem valente, o qual se chamava Quis, filho de Abiel, filho de Zeror, filho de Becorate, filho de Afia, filho de um homem de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'E tinha ele um filho que se chamava Saul, rapaz e belo, que entre os filhos de Israel não havia outro mais belo que ele; do ombro acima sobrepujava a qualquer um do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'E haviam-se perdido as asnas de Quis, pai de Saul; pelo que disse Quis a Saul seu filho: Toma agora contigo algum dos criados, e levanta-te, e vai a buscar as asnas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'E ele passou ao monte de Efraim, e dali à terra de Salisa, e não as acharam. Passaram logo pela terra de Saalim, e tampouco. Depois passaram pela terra de Benjamim, e não as encontraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'E quando vieram à terra de Zufe, Saul disse a seu criado que tinha consigo: Vem, voltemo-nos; porque talvez meu pai, deixado o cuidado das asnas, estará aflito por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'E ele lhe respondeu: Eis que agora há nesta cidade um homem de Deus, que é homem ilustre: todas as coisas que ele disser, sem dúvida virão a suceder. Vamos pois ali; talvez nos ensinará nosso caminho por onde havemos de ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'E Saul respondeu a seu criado: Vamos agora: mas que levaremos ao homem? Porque o pão de nossos alforjes se acabou, e não temos que presentear ao homem de Deus: que temos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Então voltou o criado a responder a Saul, dizendo: Eis que se acha em minha mão a quarta parte de um siclo de prata: isto darei ao homem de Deus, porque nos declare nosso caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Antigamente em Israel qualquer um que ia a consultar a Deus, dizia assim: Vinde e vamos até o vidente: porque o que agora se chama profeta, antigamente era chamado vidente).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Disse então Saul a seu criado: Bem dizes; eia, pois, vamos. E foram à cidade de onde estava o homem de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'E quando subiam pela encosta da cidade, acharam umas moças que saíam por água, às quais disseram: Está neste lugar o vidente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'E elas respondendo-lhes, disseram: Sim; ei-lo aqui diante de ti: apressa-te, pois, porque hoje veio à cidade porque o povo tem hoje sacrifício no alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'E quando entrardes na cidade, vós o encontrareis logo, antes que suba ao alto a comer; pois o povo não comerá até que ele tenha vindo, porquanto ele deve abençoar o sacrifício, e depois comerão os convidados. Subi, pois agora, porque agora o achareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Eles então subiram à cidade; e quando em meio da cidade estiveram, eis que Samuel que diante deles saía para subir ao alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'E um dia antes que Saul viesse, o SENHOR havia revelado ao ouvido de Samuel, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Amanhã a esta mesma hora eu enviarei a ti um homem da terra de Benjamim, ao qual ungirás por príncipe sobre meu povo Israel, e salvará meu povo da mão dos filisteus: pois eu olhei a meu povo, porque seu clamor há chegado até mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'E logo que Samuel viu a Saul, o SENHOR lhe disse: Eis que este é o homem do qual te falei; este dominará a meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'E chegando Saul a Samuel em meio da porta, disse-lhe: Rogo-te que me ensines onde está a casa do vidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'E Samuel respondeu a Saul, e disse: Eu sou o vidente: sobe diante de mim ao alto, e comei hoje comigo, e pela manhã te despacharei, e te revelarei tudo o que está em teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'E das asnas que se te perderam hoje há três dias, deixa de se preocupar com elas, porque se acharam. Mas a quem é todo o desejo de Israel, se não a ti e a toda a casa de teu pai?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'E Saul respondeu, e disse: Não sou eu filho de Benjamim, das menores tribos de Israel? e minha família não é a mais pequena de todas as famílias da tribo de Benjamim? por que pois me disseste coisa semelhante?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'E tomando Samuel a Saul e a seu criado, meteu-os na sala, e deu-lhes lugar à cabeceira dos convidados, que eram como uns trinta homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'E disse Samuel ao cozinheiro: Traze aqui a porção que te dei, a qual te disse que guardasses à parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Então levantou o cozinheiro uma coxa, com o que estava sobre ela, e a pôs diante de Saul. E Samuel disse: Eis que o que estava reservado: põe-o diante de ti, e come; porque foi intencionalmente guardado para ti, quando disse: Eu convidei ao povo. E Saul comeu aquele dia com Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'E quando houveram descido do alto à cidade, ele falou com Saul no terraço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'E ao outro dia madrugaram: e quando ao raiar da alva, Samuel chamou a Saul, que estava no terraço; e disse: Levanta-te, para que te despache. Levantou-se logo Saul, e saíram fora ambos, ele e Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'E descendo eles ao fim da cidade, disse Samuel a Saul: Dize ao jovem que vá diante, (e adiantou-se o jovem); mas espera tu um pouco para que te declare palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tomando então Samuel um frasco de azeite, derramou-o sobre sua cabeça, e beijou-o, e disse-lhe: Não foi o SENHOR que te ungiu para que sejas líder sobre sua propriedade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Hoje, depois que te tenhas apartado de mim, acharás dois homens junto ao sepulcro de Raquel, no termo de Benjamim, em Zelza, os quais te dirão: As asnas que havias ido a buscar, se acharam; teu pai pois há deixado já o negócio das asnas, porém está preocupado convosco, dizendo: Que farei acerca de meu filho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'E quando dali te fores mais adiante, e chegares à campina de Tabor, te sairão ao encontro três homens que sobem a Deus em Betel, levando o um três cabritos, e o outro três tortas de pão, e o terceiro uma vasilha de vinho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Os quais, logo que te tenham saudado, te darão dois pães, os quais tomarás das mãos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'De ali virás ao morro de Deus de onde está a guarnição dos filisteus; e quando entrares ali na cidade encontrarás uma companhia de profetas que descem do alto, e diante deles saltério, e adufe, e flauta, e harpa, e eles profetizando:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'E o espírito do SENHOR te arrebatará, e profetizarás com eles, e serás transformado em outro homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'E quando te houverem sobrevindo estas sinais, faze o que te vier à mão, porque Deus é contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'E descerás antes de mim a Gilgal; e logo descerei eu a ti para sacrificar holocaustos, e imolar sacrifícios pacíficos. Espera sete dias, até que eu venha a ti, e te ensine o que hás de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'E foi que assim quando virou ele seu ombro para partir-se de Samuel, mudou-lhe Deus seu coração; e todas estes sinais aconteceram naquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'E quando chegaram ali ao morro, eis que a companhia dos profetas que vinha a encontrar-se com ele, e o Espírito de Deus o arrebatou, e profetizou entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'E aconteceu que, quando todos os que o conheciam de antes viram como profetizava com os profetas, o povo dizia o um ao outro: Que sucedeu ao filho de Quis? Saul também entre os profetas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'E algum dali respondeu, e disse: E quem é o pai deles? Por esta causa se tornou em provérbio: Também Saul entre os profetas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'E cessou de profetizar, e chegou ao alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'E um tio de Saul disse a ele e a seu criado: Aonde fostes? E ele respondeu: A buscar as asnas; e quando vimos que não apareciam, fomos a Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'E disse o tio de Saul: Eu te rogo me declares que vos disse Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'E Saul respondeu a seu tio: Declarou-nos expressamente que as asnas haviam aparecido. Mas do negócio do reino, de que Samuel lhe havia falado, não lhe revelou nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'E Samuel convocou o povo ao SENHOR em Mispá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'E disse aos filhos de Israel: Assim disse o SENHOR o Deus de Israel: Eu tirei a Israel do Egito, e vos livre da mão dos egípcios, e da mão de todos os reinos que vos afligiram:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Mas vós rejeitastes hoje a vosso Deus, que vos guarda de todas as vossas aflições e angústias, e dissestes: Não, mas sim põe rei sobre nós. Agora pois, ponde-vos diante do SENHOR por vossas tribos e por vossos milhares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'E fazendo achegar Samuel todas as tribos de Israel, foi tomada a tribo de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'E fez chegar a tribo de Benjamim por suas linhagens, e foi tomada a família de Matri; e dela foi tomado Saul filho de Quis. E lhe buscaram, mas não foi achado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Perguntaram pois outra vez ao SENHOR, se havia ainda de vir ali aquele homem. E respondeu o SENHOR: Eis que ele está escondido entre a bagagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Então correram, e tomaram-no dali, e posto em meio do povo, desde o ombro acima era mais alto que todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'E Samuel disse a todo o povo: Vistes ao que o SENHOR escolheu, que não há semelhante a ele em todo o povo? Então o povo clamou com alegria, dizendo: Viva o rei!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Então Samuel recitou ao povo o direito do reino, e escreveu-o em um livro, o qual guardou diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'E enviou Samuel a todo o povo cada um a sua casa. E Saul também se foi a sua casa em Gibeá, e foram com ele o exército, o coração dos quais Deus havia tocado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Porém os ímpios disseram: Como nos há de salvar este? E tiveram-lhe em pouco, e não lhe trouxeram presente: mas ele dissimulou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'E subiu Naás amonita, e assentou acampamento contra Jabes de Gileade. E todos os de Jabes disseram a Naás: Faze aliança conosco, e te serviremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'E Naás amonita lhes respondeu: Com esta condição farei aliança convosco, que a cada um de todos vós tire o olho direito, e ponha esta afronta sobre todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Então os anciãos de Jabes lhe disseram: Dá-nos sete dias, para que enviemos mensageiros a todos os termos de Israel; e se ninguém houver que nos defenda, sairemos a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'E chegando os mensageiros a Gibeá de Saul, disseram estas palavras em ouvidos do povo; e todo o povo chorou a voz em grito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'E eis que Saul que vinha do campo, atrás os bois; e disse Saul: Que tem o povo, que choram? E contaram-lhe as palavras dos homens de Jabes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'E o espírito de Deus arrebatou a Saul em ouvindo estas palavras, e acendeu-se em ira em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'E tomando um par de bois, cortou-os em peças, e enviou-as por todos os termos de Israel por meio de mensageiros, dizendo: Qualquer um que não sair após Saul e após Samuel, assim será feito a seus bois. E caiu temor do SENHOR sobre o povo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'E contou-lhes em Bezeque; e foram os filhos de Israel trezentos mil, e trinta mil os homens de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'E responderam aos mensageiros que haviam vindo: Assim direis aos de Jabes de Gileade: Amanhã em aquecendo o sol, tereis salvamento. E vieram os mensageiros, e declararam-no aos de Jabes, os quais se alegraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'E os de Jabes disseram: Amanhã sairemos a vós, para que façais conosco tudo o que bem vos parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'E o dia seguinte dispôs Saul o povo em três esquadrões, e entraram em meio do acampamento à vigília da manhã, e feriram aos amonitas até que o dia aquecesse; e os que restaram foram dispersos, tal que não restaram dois deles juntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'O povo então disse a Samuel: Quem são o que diziam: Reinará Saul sobre nós? Dai-nos esses homens, e os mataremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'E Saul disse: Não morrerá hoje ninguém, porque hoje operou o SENHOR salvação em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Mas Samuel disse ao povo: Vinde, vamos a Gilgal para que renovemos ali o reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'E foi todo o povo a Gilgal, e investiram ali a Saul por rei diante do SENHOR em Gilgal. E sacrificaram ali vítimas pacíficas diante do SENHOR; e alegraram-se muito ali Saul e todos os de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'E disse Samuel a todo Israel: Eis que, eu ouvi vossa voz em todas as coisas que me haveis dito, e vos pus rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Agora, pois, eis que vosso rei vai diante de vós. Eu sou já velho e grisalho: mas meus filhos estão convosco, e eu andei diante de vós desde minha juventude até este dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Aqui estou; testemunhai contra mim diante do SENHOR e diante de seu ungido, se tomei o boi de alguém, ou se tomei o asno de alguém, ou se caluniei a alguém, ou se oprimi a alguém, ou se de alguém tomei suborno pelo qual tenha coberto meus olhos; e eu vos restituirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Então disseram: Nunca nos caluniaste, nem oprimi, nem tomaste algo da mão de nenhum homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'E ele lhes disse: o SENHOR é testemunha contra vós, e seu ungido também é testemunha neste dia, que não achastes em minha mão coisa nenhuma. E eles responderam: Assim é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Então Samuel disse ao povo: o SENHOR é quem fez a Moisés e a Arão, e que tirou a vossos pais da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Agora, pois, aguardai, e eu queixarei de vós diante do SENHOR de todas as justiças do SENHOR, que fez convosco e com vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Depois que Jacó entrou em Egito e vossos pais clamaram ao SENHOR, o SENHOR enviou a Moisés e a Arão, os quais tiraram a vossos pais do Egito, e os fizeram habitar neste lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'E esqueceram ao SENHOR seu Deus, e ele os vendeu na mão de Sísera capitão do exército de Hazor, e na mão dos filisteus, e na mão do rei de Moabe, os quais lhes fizeram guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'E eles clamaram ao SENHOR, e disseram: Pecamos, porque deixamos ao SENHOR, e servimos aos baalins e a Astarote: livra-nos, pois, agora da mão de nossos inimigos, e te serviremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Então o SENHOR enviou a Jerubaal, e a Bedã, e a Jefté, e a Samuel, e vos livrou da mão de vossos inimigos ao redor, e habitastes seguros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'E havendo visto que Naás rei dos filhos de Amom vinha contra vós, me dissestes: Não, mas sim rei reinará sobre nós; sendo vosso rei o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Agora, pois, vede aqui vosso rei que haveis escolhido, o qual pedistes; já vedes que o SENHOR pôs sobre vós rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Se temerdes ao SENHOR e o servirdes, e ouvirdes sua voz, e não fordes rebeldes à palavra do SENHOR, tanto vós como o rei que rainha sobre vós, seguireis ao SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mas se não ouvirdes a voz do SENHOR, e se fordes rebeldes às palavras do SENHOR, a mão do SENHOR será contra vós como contra vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Esperai ainda agora, e olhai esta grande coisa que o SENHOR fará diante de vossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Não é agora a colheita dos trigos? Eu clamarei ao SENHOR, e ele dará trovões e chuva; para que conheçais e vejais que é grande vossa maldade que tendes feito aos olhos do SENHOR, pedindo-vos rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'E Samuel clamou ao SENHOR; e o SENHOR deu trovões e chuva naquele dia; e todo o povo temeu em grande maneira ao SENHOR e a Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Então disse todo o povo a Samuel: Roga por teus servos ao SENHOR teu Deus, que não morramos: porque a todos os nossos pecados acrescentamos este mal de pedir rei para nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'E Samuel respondeu ao povo: Não temais: vós cometestes todo este mal; mas com tudo isso não vos desvieis de seguir ao SENHOR, mas sim servi ao SENHOR com todo o vosso coração:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Não vos desvieis a fim de seguir as vaidades que não aproveitam nem livram, porque são vaidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Pois o SENHOR não desamparará a seu povo por seu grande nome: porque o SENHOR quis fazer-vos povo seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Assim que, longe seja de mim que peque eu contra o SENHOR cessando de rogar por vós; antes eu vos ensinarei pelo caminho bom e direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Somente temei ao SENHOR, e servi-o de verdade com todo vosso coração, porque considerai quão grandes coisas fez convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Mas se perseverardes em fazer mal, vós e vosso rei perecereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Havia já Saul reinado um ano; e reinado que houve dois anos sobre Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Escolheu-se logo três mil de Israel: os dois mil estiveram com Saul em Micmás e no monte de Betel, e os mil estiveram com Jônatas em Gibeá de Benjamim; e enviou a todo o outro povo cada um a suas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'E Jônatas feriu a guarnição dos filisteus que havia no morro, e ouviram-no os filisteus. E fez Saul tocar trombetas por toda a terra, dizendo: Ouçam os hebreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'E todo Israel ouviu o que se dizia: Saul feriu a guarnição dos filisteus; e também que Israel se tornou detestável aos filisteus. E juntou-se o povo sob o comando de Saul em Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Então os filisteus se juntaram para lutar com Israel, trinta mil carros, e seis mil cavalos, e povo quando a areia que está à beira do mar em multidão; e subiram, e assentaram acampamento em Micmás, ao oriente de Bete-Áven.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Mas os homens de Israel, vendo-se postos em apuros, (porque o povo estava em dificuldades), escondeu-se o povo em covas, em fossos, em penhascos, em rochas e em cisternas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'E alguns dos hebreus passaram o Jordão à terra de Gade e de Gileade: e Saul se estava ainda em Gilgal, e todo o povo ia atrás dele tremendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'E ele esperou sete dias, conforme ao prazo que Samuel havia dito; mas Samuel não vinha a Gilgal, e o povo se lhe desertava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Então disse Saul: Trazei-me holocausto e sacrifícios pacíficos. E ofereceu o holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'E quando ele acabava de fazer o holocausto, eis que Samuel que vinha; e Saul lhe saiu a receber para saudar-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Então Samuel disse: Que fizeste? E Saul respondeu: Porque vi que o povo se me ia, e que tu não vinhas ao prazo dos dias, e que os filisteus estavam juntos em Micmás,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Disse-me: Os filisteus descerão agora contra mim a Gilgal, e eu não implorei o favor do SENHOR. Esforcei-me pois, e ofereci holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Então Samuel disse a Saul: Loucamente fizeste; não guardaste o mandamento do SENHOR teu Deus, que ele te havia intimado; porque agora o SENHOR teria confirmado teu reino sobre Israel para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Mas agora teu reino não será durável: o SENHOR buscou para si homem segundo seu coração, ao qual o SENHOR mandou que seja líder sobre seu povo, porquanto tu não guardaste o que o SENHOR te mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'E levantando-se Samuel, subiu de Gilgal a Gibeá de Benjamim. E Saul contou a gente que se achava com ele, como seiscentos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Então Saul e Jônatas seu filho, e o povo que com eles se achava, ficaram em Gibeá de Benjamim: mas os filisteus haviam posto seu acampamento em Micmás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'E saíram do acampamento dos filisteus em saque três esquadrões. O um esquadrão tirou pelo caminho de Ofra até a terra de Sual.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'O outro esquadrão marchou até Bete-Horom, e o terceiro esquadrão marchou até a região que está voltada ao vale de Zeboim até o deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'E em toda a terra de Israel não se achava ferreiro; porque os filisteus haviam dito: Para que os hebreus não façam espada ou lança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'E todos os de Israel desciam aos filisteus cada qual a amolar sua relha, sua enxada, seu machado, ou seu sacho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'E cobravam certo preço pelas relhas, pelas enxadas, e pelas forquilhas, e outro para afiar os machados, e as aguilhadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Assim aconteceu que o dia da batalha não se achou espada nem lança em mão de algum de todo o povo que estava com Saul e com Jônatas, exceto Saul e Jônatas seu filho, que as tinham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'E a guarnição dos filisteus saiu ao desfiladeiro de Micmás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'E um dia aconteceu, que Jônatas filho de Saul disse a seu criado que lhe trazia as armas: Vem, e passemos à guarnição dos filisteus, que está a aquele lado. E não o fez saber a seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'E Saul estava no termo de Gibeá, debaixo de uma romãzeira que há em Migrom, e o povo que estava com ele era como seiscentos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'E Aías filho de Aitube, irmão de Icabode, filho de Fineias, filho de Eli, sacerdote do SENHOR em Siló, levava o éfode; e não sabia o povo que Jônatas se houvesse ido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'E entre os desfiladeiros por de onde Jônatas procurava passar à guarnição dos filisteus, havia um penhasco agudo da uma parte, e outro da outra parte; o um se chamava Bozez e o outro Sené:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'O um penhasco situado ao norte até Micmás, e o outro ao sul até Gibeá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Disse, pois, Jônatas a seu criado que lhe trazia as armas: Vem, passemos à guarnição destes incircuncisos: talvez fará o SENHOR por nós; que não é difícil ao SENHOR salvar com multidão ou com pouco número.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'E seu pajem de armas lhe respondeu: Faze tudo o que tens em teu coração: vai, que aqui estou contigo à tua vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'E Jônatas disse: Eis que, nós passaremos aos homens, e nos mostraremos a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Se nos disserem assim: Esperai até que cheguemos a vós; então nos estaremos em nosso lugar, e não subiremos a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Mas se nos disserem assim: Subi a nós: então subiremos, porque o SENHOR os entregou em nossas mãos: e isto nos será por sinal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Mostraram-se, pois, ambos à guarnição dos filisteus, e os filisteus disseram: Eis que os hebreus, que saem das cavernas em que se haviam escondido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'E os homens da guarnição responderam a Jônatas e a seu pajem de armas, e disseram: Subi a nós, e vos faremos saber uma coisa. Então Jônatas disse a seu pajem de armas: Sobe atrás mim, que o SENHOR os entregou na mão de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'E subiu Jônatas escalando com suas mãos e seus pés, e atrás dele seu pajem de armas; e os que caíam diante de Jônatas, seu pajem de armas que ia atrás dele os matava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Esta foi a primeira derrota, na qual Jônatas com seu pajem de armas, mataram como uns vinte homens no espaço de uma meia jeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'E houve tremor no acampamento e pelo campo, e entre toda a gente da guarnição; e os que haviam ido a fazer saques, também eles tremeram, e alvoroçou-se a terra: houve, pois, grande pânico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'E as sentinelas de Saul viram desde Gibeá de Benjamim como a multidão estava perturbada, e ia de uma parte à outra, e era desfeita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Então Saul disse ao povo que tinha consigo: Reconhecei logo, e olhai quem tenha ido dos nossos. E depois de terem reconhecido, acharam que faltavam Jônatas e seu pajem de armas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'E Saul disse a Aías: Traze a arca de Deus. Porque a arca de Deus estava então com os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'E aconteceu que estando ainda falando Saul com o sacerdote, o alvoroço que havia no campo dos filisteus se aumentava, e ia crescendo em grande maneira. Então disse Saul ao sacerdote: Detém tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'E juntando Saul todo o povo que com ele estava, vieram até o lugar da batalha: e eis que a espada de cada um era volta contra seu companheiro, e a mortandade era grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'E os hebreus que haviam estado com os filisteus de tempo antes, e haviam vindo com eles dos arredores ao acampamento, também estes se voltaram a ser com os israelitas que estavam com Saul e com Jônatas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Também todos os israelitas que se haviam escondido no monte de Efraim, ouvindo que os filisteus fugiam, eles também os perseguiram naquela batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Assim salvou o SENHOR a Israel aquele dia. E chegou o alcance até Bete-Áven.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Porém os homens de Israel foram postos em apuros aquele dia; porque Saul havia conjurado ao povo, dizendo: Qualquer um que comer pão até a tarde, até que tenha tomado vingança de meus inimigos, seja maldito. E todo o povo não havia provado pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'E todo o povo do país chegou a um bosque de onde havia mel na superfície do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Entrou, pois, o povo no bosque, e eis que o mel corria; mas ninguém havia que chegasse a mão à sua boca: porque o povo temia o juramento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Porém Jônatas não havia ouvido quando seu pai conjurou ao povo, e estendeu a ponta de uma vara que trazia em sua mão, e molhou-a em um favo de mel, e chegou sua mão a sua boca; e seus olhos se iluminaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Então falou um do povo, dizendo: Teu pai conjurou expressamente ao povo, dizendo: Maldito seja o homem que comer hoje alimento. E o povo desfalecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'E respondeu Jônatas: Meu pai perturbou o país. Vede agora como foram aclarados meus olhos, por haver provado um pouco deste mel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Quanto mais se o povo houvesse hoje comido do despojo de seus inimigos que achou? não se haveria feito agora maior estrago nos filisteus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'E feriram aquele dia aos filisteus desde Micmás até Aijalom: mas o povo se cansou muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Tornou-se, portanto, o povo ao despojo, e tomaram ovelhas e vacas e bezerros, e mataram-nos em terra, e o povo comeu com sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'E dando-lhe disso aviso a Saul, disseram-lhe: O povo peca contra o SENHOR comendo com sangue. E ele disse: Vós cometestes transgressão; rolai-me agora aqui uma grande pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'E Saul voltou a dizer: Espalhai-vos pelo povo, e dizei-lhes que me tragam cada um sua vaca, e cada qual sua ovelha, e degolai-os aqui, e comei; e não pecareis contra o SENHOR comendo com sangue. E trouxe todo o povo cada qual por sua mão sua vaca aquela noite, e ali degolaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'E edificou Saul altar ao SENHOR, o qual altar foi o primeiro que edificou ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'E disse Saul: Desçamos de noite contra os filisteus, e os saquearemos até a manhã, e não deixaremos deles ninguém. E eles disseram: Faze o que bem te parecer. Disse logo o sacerdote: Acheguemo-nos aqui a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'E Saul consultou a Deus: Descerei atrás dos filisteus? os entregarás em mão de Israel? Mas o SENHOR não lhe deu resposta aquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Então disse Saul: Achegai-vos aqui todos os principais do povo; e sabei e olhai por quem foi hoje este pecado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Porque vive o SENHOR, que salva a Israel, que se for em meu filho Jônatas, ele morrerá de certo. E não houve em todo o povo quem lhe respondesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Disse logo a todo Israel: Vós estareis a um lado, e eu e Jônatas meu filho estaremos a outro lado. E o povo respondeu a Saul: Faze o que bem te parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Então disse Saul ao SENHOR Deus de Israel: Dá perfeição. E foram tomados Jônatas e Saul, e o povo saiu livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'E Saul disse: Lançai sorte entre mim e Jônatas meu filho. E foi tomado Jônatas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Então Saul disse a Jônatas: Declara-me que fizeste. E Jônatas se o declarou, e disse: Certo que provei com a ponta da vara que trazia em minha mão, um pouco de mel: e eis que ei de morrer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'E Saul respondeu: Assim me faça Deus e assim me acrescente, que sem dúvida morrerás, Jônatas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Mas o povo disse a Saul: Há, pois, de morrer Jônatas, o que fez esta salvação grande em Israel? Não será assim. Vive o SENHOR, que não há de cair um cabelo de sua cabeça em terra, pois que operou hoje com Deus. Assim livrou o povo a Jônatas, para que não morresse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'E Saul deixou de perseguir aos filisteus; e os filisteus se foram a seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'E ocupando Saul o reino sobre Israel, fez guerra a todos seus inimigos ao redor: contra Moabe, contra os filhos de Amom, contra Edom, contra os reis de Zobá, e contra os filisteus: e a de onde quer que se voltava era vencedor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'E reuniu um exército, e feriu a Amaleque, e livrou a Israel da mão dos que lhe roubavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'E os filhos de Saul foram Jônatas, Isvi, e Malquisua. E os nomes de suas duas filhas eram, o nome da mais velha, Merabe, e o da mais nova, Mical.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'E o nome da mulher de Saul era Ainoã, filha de Aimaás. E o nome do general de seu exército era Abner, filho de Ner tio de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Porque Quis pai de Saul, e Ner pai de Abner, foram filhos de Abiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'E a guerra foi forte contra os filisteus todo o tempo de Saul; e a qualquer um que Saul via homem valente e homem de esforço, juntava-lhe consigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'E Samuel disse a Saul: o SENHOR me enviou a que te ungisse por rei sobre seu povo Israel: ouve pois a voz das palavras do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Assim disse o SENHOR dos exércitos: Lembro-me do que fez Amaleque a Israel; que se lhe opôs no caminho, quando subia do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Vai pois, e fere a Amaleque, e destruireis nele tudo o que tiver: e não te apiedes dele: mata homens e mulheres, crianças e bebês que mamam, vacas e ovelhas, camelos e asnos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul pois juntou o povo, e reconheceu-os em Telaim, duzentos mil a pé, e dez mil homens de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'E vindo Saul à cidade de Amaleque, pôs emboscada no vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'E disse Saul aos queneus: Ide-vos, apartai-vos, e saí de entre os de Amaleque, para que não te destrua juntamente com ele: pois que tu fizeste misericórdia com todos os filhos de Israel, quando subiam do Egito. Apartaram-se, pois os queneus dentre os de Amaleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'E Saul feriu a Amaleque, desde Havilá até chegar a Sur, que está à fronteira do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'E tomou vivo a Agague rei de Amaleque, mas a todo o povo matou a fio de espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'E Saul e o povo pouparam a Agague, e a o melhor das ovelhas, e ao gado maior, aos grossos e aos carneiros, e a todo o bom: que não o quiseram destruir: mas tudo o que era vil e fraco destruíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'E veio a palavra do SENHOR a Samuel, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Pesa-me de haver posto por rei a Saul, porque se desviou de me seguir, e não cumpriu minhas palavras. E entristeceu-se Samuel, e clamou ao SENHOR toda aquela noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Madrugou logo Samuel para ir se encontrar com Saul pela manhã; e foi dado aviso a Samuel, dizendo: Saul veio ao Carmelo, e eis que ele se levantou um monumento, e depois voltando, passou e descido a Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Veio, pois, Samuel a Saul, e Saul lhe disse: Bendito sejas tu do SENHOR; eu cumpri a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel então disse: Pois que balido de gados e bramido de bois é este que eu ouço com meus ouvidos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'E Saul respondeu: De Amaleque os trouxeram; porque o povo poupou ao melhor das ovelhas e das vacas, para sacrificá-las ao SENHOR teu Deus; mas destruímos o resto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Então disse Samuel a Saul: Deixa-me declarar-te o que o SENHOR me disse esta noite. E ele lhe respondeu: Dize.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'E disse Samuel: Sendo tu pequeno em teus olhos não foste feito cabeça às tribos de Israel, e o SENHOR te ungiu por rei sobre Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'E enviou-te o SENHOR em jornada, e disse: Vai, e destrói os pecadores de Amaleque, e faze-lhes guerra até que os acabes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Por que, pois, não ouviste a voz do SENHOR, mas em vez disso te voltaste ao despojo, e fizeste o que era mau aos olhos do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'E Saul respondeu a Samuel: Antes ouvi a voz do SENHOR, e fui à jornada que o SENHOR me enviou, e trouxe a Agague rei de Amaleque, e destruí aos amalequitas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mas o povo tomou do despojo ovelhas e vacas, as primícias do anátema, para sacrificá-las ao SENHOR teu Deus em Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'E Samuel disse: Tem o SENHOR tanto contentamento com os holocaustos e vítimas, como em obedecer às palavras do SENHOR? Certamente o obedecer é melhor que os sacrifícios; e o prestar atenção que a gordura dos carneiros:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Porque como pecado de adivinhação é a rebelião, e como ídolos e idolatria o infringir. Porquanto tu rejeitaste a palavra do SENHOR, ele também te rejeitou para que não sejas rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Então Saul disse a Samuel: Eu pequei; porque violei o dito do SENHOR e tuas palavras, porque temi ao povo, consenti à voz deles. Perdoa, pois, agora meu pecado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'E volta comigo para que adore ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'E Samuel respondeu a Saul: Não voltarei contigo; porque rejeitaste a palavra do SENHOR, e o SENHOR te rejeitou para que não sejas rei sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'E voltando-se Samuel para ir-se, ele lançou mão da orla de sua capa, e rasgou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Então Samuel lhe disse: o SENHOR rasgou hoje de ti o reino de Israel, e o deu a teu próximo melhor que tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'E também o Poderoso de Israel não mentirá, nem se arrependerá: porque não é homem para que se arrependa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'E ele disse: Eu pequei: mas rogo-te que me honres diante dos anciãos de meu povo, e diante de Israel; e volta comigo para que adore ao SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'E voltou Samuel atrás de Saul, e Saul adorou ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Depois disse Samuel: Trazei-me a Agague rei de Amaleque. E Agague veio a ele delicadamente. E disse Agague: Certamente se passou a amargura da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'E Samuel disse: Como tua espada deixou as mulheres sem filhos, assim tua mãe será sem filho entre as mulheres. Então Samuel cortou em pedaços a Agague diante do SENHOR em Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Foi-se logo Samuel a Ramá, e Saul subiu a sua casa em Gibeá de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'E nunca depois viu Samuel a Saul em toda sua vida: e Samuel chorava por Saul: mas o SENHOR se havia se arrependido de haver posto a Saul por rei sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'E disse o SENHOR a Samuel: Até quando hás tu de chorar por Saul, havendo-o eu rejeitado para que não reine sobre Israel? Enche teu chifre de azeite, e vem, te enviarei a Jessé de Belém: porque de seus filhos me provi de rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'E disse Samuel: Como irei? Se Saul o entender, me matará. O SENHOR respondeu: Toma contigo uma bezerra das vacas, e dize: A sacrificar ao SENHOR vim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'E chama a Jessé ao sacrifício, e eu te ensinarei o que hás de fazer; e ungirás a mim ao que eu te disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Fez pois Samuel como lhe disse o SENHOR: e logo que ele chegou a Belém, os anciãos da cidade lhe saíram a receber com medo, e disseram: É pacífica tua vinda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'E ele respondeu: Sim, venho a sacrificar ao SENHOR; santificai-vos, e vinde comigo ao sacrifício. E santificando ele a Jessé e a seus filhos, chamou-os ao sacrifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'E aconteceu que quando eles vieram, ele viu a Eliabe, e disse: De certo diante do SENHOR está seu ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'E o SENHOR respondeu a Samuel: Não olhes à sua aparência, nem à sua grande estatura, porque eu o rejeito; porque o SENHOR olha não o que o homem olha; pois que o homem olha o que está diante de seus olhos, mas o SENHOR olha o coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Então chamou Jessé a Abinadabe, e fez-lhe passar diante de Samuel, o qual disse: nem a este o SENHOR escolheu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Fez logo passar Jessé a Samá. E ele disse: Tampouco a este o SENHOR escolheu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'E Jessé fez passar seus sete filhos diante de Samuel; mas Samuel disse a Jessé: o SENHOR não escolheu a estes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Então disse Samuel a Jessé: Acabaram-se os moços? E ele respondeu: Ainda resta o mais novo, que apascenta as ovelhas. E disse Samuel a Jessé: Envia por ele, porque não nos assentaremos à mesa até que ele venha aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Enviou, pois, por ele, e introduziu-o; o qual era ruivo, de bela aparência e de belo aspecto. Então o SENHOR disse: Levanta-te e unge-o, que este é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'E Samuel tomou o chifre do azeite, e ungiu-o dentre seus irmãos: e desde aquele dia em diante o espírito do SENHOR tomou a Davi. Levantou-se logo Samuel, e voltou-se a Ramá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'E o espírito do SENHOR se afastou de Saul, e atormentava-lhe o espírito mau da parte do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'E os criados de Saul lhe disseram: Eis que agora, que o espírito mau da parte de Deus te atormenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Diga, pois, nosso senhor a teus servos que estão diante de ti, que busquem alguém que saiba tocar a harpa; para que quando for sobre ti o espírito mau da parte de Deus, ele toque com sua mão, e tenhas alívio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'E Saul respondeu a seus criados: Buscai-me pois agora algum que toque bem, e traze-o a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Então um dos criados respondeu, dizendo: Eis que eu vi a um filho de Jessé de Belém, que sabe tocar, e é valente e vigoroso, e homem de guerra, prudente em suas palavras, e belo, e o SENHOR é com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'E Saul enviou mensageiros a Jessé, dizendo: Envia-me a Davi teu filho, o que está com as ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'E tomou Jessé um asno carregado de pão, e uma vasilha de vinho e um cabrito, e enviou-o a Saul por meio de Davi seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'E vindo Davi a Saul, esteve diante dele: e amou-o ele muito, e foi feito seu escudeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'E Saul enviou a dizer a Jessé: Eu te rogo que esteja Davi comigo; porque achou graça em meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'E quando o espírito mau da parte de Deus era sobre Saul, Davi tomava a harpa, e tocava com sua mão; e Saul tinha refrigério, e estava melhor, e o espírito mau se afastava dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'E os filisteus juntaram seus exércitos para a guerra, e congregaram-se em Socó, que é de Judá, e assentaram o campo entre Socó e Azeca, em Efes-Damim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'E também Saul e os homens de Israel se juntaram, e assentaram o acampamento no vale de Elá, e ordenaram a batalha contra os filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'E os filisteus estavam sobre o um monte da uma parte, e Israel estava sobre o outro monte da outra parte, e o vale entre eles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Saiu então um homem do acampamento dos filisteus que se pôs entre os dois campos, o qual se chamava Golias, de Gate, e tinha de altura seis côvados e um palmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'E trazia um capacete de bronze em sua cabeça, e ia vestido com couraças de placas: e era o peso da couraça cinco mil siclos de bronze:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'E sobre suas pernas trazia caneleiras de ferro, e escudo de bronze a seus ombros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'A haste de sua lança era como um lançador de tear, e tinha o ferro de sua lança seiscentos siclos de ferro: e ia seu escudeiro diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'E parou-se, e deu vozes aos esquadrões de Israel, dizendo-lhes: Para que saís a dar batalha? não sou eu o filisteu, e vós os servos de Saul? Escolhei dentre vós um homem que venha contra mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Se ele puder lutar comigo, e me vencer, nós seremos vossos servos: e se eu puder mais que ele, e o vencer, vós sereis nossos servos e nos servireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'E acrescentou o filisteu: Hoje eu desafiei o acampamento de Israel; dá-me um homem que lute comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'E ouvindo Saul e todo Israel estas palavras do filisteu, perturbaram-se, e tiveram grande medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'E Davi era filho daquele homem efrateu de Belém de Judá, cujo nome era Jessé, o qual tinha oito filhos; e era este homem no tempo de Saul, velho, e de grande idade entre os homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'E os três filhos mais velhos de Jessé haviam ido a perseguir a Saul na guerra. E os nomes de seus três filhos que haviam ido à guerra, eram, Eliabe o primogênito, o segundo Abinadabe, e o terceiro Samá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'E Davi era o mais novo. Seguiram, pois, os três maiores a Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Porém Davi ia e voltava de perto de Saul, para apascentar as ovelhas de seu pai em Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Vinha, pois, aquele filisteu pela manhã e à tarde, e apresentou-se por quarenta dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'E disse Jessé a Davi seu filho: Toma agora para teus irmãos um efá deste grão tostado, e estes dez pães, e leva-o logo ao acampamento a teus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Levarás também estes dez queijos de leite ao capitão, e cuida de ver se teus irmãos estão bem, e toma garantias deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'E Saul e eles e todos os de Israel, estavam no vale de Elá, lutando com os filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Levantou-se, pois, Davi de manhã, e deixando as ovelhas ao cuidado de um guarda, foi-se com sua carga, como Jessé lhe havia mandado; e chegou ao entrincheiramento do exército, o qual havia saído em ordem de batalha, e tocava alarme para a luta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Porque tanto os israelitas como os filisteus estavam em ordem de batalha, esquadrão contra esquadrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'E Davi deixou de sobre si a carga em mão do que guardava a bagagem, e correu ao esquadrão; e chegado que houve, perguntava por seus irmãos, se estavam bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'E estando ele falando com eles, eis que aquele homem que se punha em meio dos dois acampamentos, que se chamava Golias, o filisteu de Gate, saiu dos esquadrões dos filisteus, e falou as mesmas palavras; as quais ouviu Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'E todos os homens de Israel que viam aquele homem, fugiam de sua presença, e tinham grande temor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'E cada um dos de Israel dizia: Não vistes aquele homem que saiu? Ele se adianta para provocar a Israel. Ao que lhe vencer, o rei lhe enriquecerá com grandes riquezas, e lhe dará sua filha, e fará livre de tributos a casa de seu pai em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Então falou Davi aos que junto a ele estavam, dizendo: Que farão ao homem que vencer a este filisteu, e tirar a humilhação de Israel? Porque quem é este filisteu incircunciso, para que provoque aos esquadrões do Deus vivente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'E o povo lhe respondeu as mesmas palavras, dizendo: Assim se fará ao homem que o vencer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'E ouvindo-lhe falar Eliabe seu irmão mais velho com aqueles homens, Eliabe se acendeu em ira contra Davi, e disse: Para que hás descido aqui? e a quem deixaste aquelas poucas ovelhas no deserto? Eu conheço tua soberba e a malícia de teu coração, que vieste para ver a batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'E Davi respondeu: Que fiz eu agora? Não são estas apenas palavras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'E apartando-se dele até outros, falou o mesmo; e responderam-lhe os do povo como da primeira vez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'E foram ouvidas as palavras que Davi havia dito, as quais quando referiram diante de Saul, ele o fez vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'E disse Davi a Saul: Não desmaie ninguém por causa dele; teu servo irá e lutará com este filisteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'E disse Saul a Davi: Não poderás tu ir contra aquele filisteu, para lutar com ele; porque tu és jovem, e ele um homem de guerra desde sua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'E Davi respondeu a Saul: Teu servo era pastor das ovelhas de seu pai, e vinha um leão, ou um urso, e tomava algum cordeiro do rebanho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'E saía eu atrás dele, e feria-o, e livrava-lhe de sua boca: e se se levantava contra mim, eu o segurava pelo queixo, feria-o, e o matava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Fosse leão, fosse urso, teu servo o matava; pois este filisteu incircunciso será como um deles, porque provocou ao exército do Deus vivente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'E acrescentou Davi: o SENHOR que me livrou das garras do leão e das garras do urso, ele também me livrará da mão deste filisteu. E disse Saul a Davi: Vai, e o SENHOR seja contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'E Saul revestiu a Davi de suas roupas, e pôs sobre sua cabeça um capacete de bronze, e armou-lhe de couraça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'E cingiu Davi sua espada sobre suas roupas, e provou a andar, porque nunca havia provado. E disse Davi a Saul: Eu não posso andar com isto, porque nunca o pratiquei. E lançando de si Davi aquelas coisas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Tomou seu cajado em sua mão, e escolheu para si cinco pedras lisas do ribeiro, e as pôs no saco pastoril e na sacola que trazia, e com sua funda em sua mão foi até o filisteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'E o filisteu vinha andando e aproximando-se a Davi, e seu escudeiro diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'E quando o filisteu olhou e viu a Davi, menosprezou-o; porque era rapaz, e ruivo, e de bela aparência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'E disse o filisteu a Davi: Sou eu cão para que venhas a mim com paus? E amaldiçoou a Davi por seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Disse logo o filisteu a Davi: Vem a mim, e darei tua carne às aves do céu, e aos animais do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Então disse Davi ao filisteu: Tu vens a mim com espada e lança e escudo; mas eu venho a ti no nome do SENHOR dos exércitos, o Deus dos esquadrões de Israel, que tu provocaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'o SENHOR te entregará hoje em minha mão, e eu te vencerei, e tirarei tua cabeça de ti: e darei hoje os corpos dos filisteus às aves do céu e aos animais da terra: e saberá a terra toda que há Deus em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'E saberá toda esta congregação que o SENHOR não salva com espada e lança; porque do SENHOR é la guerra, e ele vos entregará em nossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'E aconteceu que, quando o filisteu se levantou para ir e chegar-se contra Davi, Davi se deu pressa, e correu ao combate contra o filisteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'E metendo Davi sua mão no saco, tomou dali uma pedra, e atirou-a com a funda, e feriu ao filisteu na testa: e a pedra ficou fincada na testa, e caiu em terra sobre seu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Assim venceu Davi ao filisteu com funda e pedra; e feriu ao filisteu e o matou, sem ter Davi espada em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Mas correu Davi e pôs-se sobre o filisteu, e tomando a espada dele, tirando-a de sua bainha, o matou, e cortou-lhe com ela a cabeça. E quando os filisteus viram seu gigante morto, fugiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'E levantando-se os de Israel e de Judá, deram grito, e seguiram aos filisteus até chegar ao vale, e até as portas de Ecrom. E caíram feridos dos filisteus pelo caminho de Saaraim, até Gate e Ecrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Tornando logo os filhos de Israel de perseguir os filisteus, despojaram seu acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'E Davi tomou a cabeça do filisteu, e trouxe-a a Jerusalém, mas pôs suas armas em sua tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'E quando Saul viu a Davi que saía a encontrar-se com o filisteu, disse a Abner general do exército: Abner, de quem é filho aquele rapaz? E Abner respondeu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Vive tua alma, ó rei, que não o sei. E o rei disse: Pergunta, pois, de quem é filho aquele rapaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'E quando Davi voltava de matar ao filisteu, Abner o tomou, e levou-o diante de Saul, tendo a cabeça do filisteu em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'E disse-lhe Saul: Rapaz, de quem és filho? E Davi respondeu: Eu sou filho de teu servo Jessé de Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'E assim que ele acabou de falar com Saul, a alma de Jônatas se apegou à de Davi, e Jônatas o amou como à sua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'E Saul o tomou naquele dia, e não o deixou voltar à casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'E fizeram aliança Jônatas e Davi, porque ele lhe amava como a sua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'E Jônatas despiu a roupa que tinha sobre si, e deu-a a Davi, e outras roupas suas, até sua espada, e seu arco, e seu cinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'E Davi saía para onde quer que Saul o enviasse, e portava-se prudentemente. Fê-lo, portanto, Saul capitão da gente de guerra, e era aceito aos olhos de todo o povo, e nos olhos dos criados de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'E aconteceu que quando voltavam eles, quando Davi voltou de matar ao filisteu, saíram as mulheres de todas as cidades de Israel cantando, e com danças, com tamboris, e com alegrias e adufes, a receber ao rei Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'E cantavam as mulheres que dançavam, e diziam: Saul feriu seus milhares, E Davi seus dez milhares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'E irou-se Saul em grande maneira, e desagradou esta palavra em seus olhos, e disse: A Davi deram dez milhares, e a mim milhares; não lhe falta mais que o reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'E desde aquele dia Saul olhou com desconfiança a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Outro dia aconteceu que o espírito mau da parte de Deus tomou a Saul, e mostrava-se em sua casa com trejeitos de profeta: e Davi tocava com sua mão como os outros dias; e estava uma lança à mão de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'E lançou Saul a lança, dizendo: Encravarei a Davi na parede. E duas vezes se afastou dele Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Mas Saul se temia de Davi porquanto o SENHOR era com ele, e havia se afastado de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Afastou-o, pois, Saul de si, e fez-lhe capitão de mil; e saía e entrava diante do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'E Davi se conduzia prudentemente em todos seus negócios, e o SENHOR era com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'E vendo Saul que se portava tão prudentemente, temia-se dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Mas todos os de Israel e Judá amavam a Davi, porque ele saía e entrava diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'E disse Saul a Davi: Eis que eu te darei a Merabe minha filha maior por mulher: somente que me sejas homem valente, e faças as guerras do SENHOR. Mas Saul dizia: Não será minha mão contra ele, mas a mão dos filisteus será contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'E Davi respondeu a Saul: Quem sou eu, ou que é minha vida, ou a família de meu pai em Israel, para ser genro do rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'E vindo o tempo em que Merabe, filha de Saul, se havia de dar a Davi, foi dada por mulher a Adriel meolatita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Mas Mical a outra filha de Saul amava a Davi; e foi dito a Saul, o qual foi conveniente em seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'E Saul disse: Eu a darei a ele, para que lhe seja por armadilha, e para que a mão dos filisteus seja contra ele. Disse, pois, Saul a Davi: Com a outra serás meu genro hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'E mandou Saul a seus criados: Falai em secreto a Davi, dizendo-lhe: Eis que, o rei te ama, e todos seus criados te querem bem; sê, pois, genro do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'E os criados de Saul falaram estas palavras aos ouvidos de Davi. E Davi disse: Parece-vos que é pouco ser genro do rei, sendo eu um homem pobre e de nenhuma estima?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'E os criados de Saul lhe deram a resposta dizendo: Tais palavras disse Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'E Saul disse: Dizei assim a Davi: Não está o contentamento do rei no dote, mas sim em cem prepúcios de filisteus, para que seja tomada vingança dos inimigos do rei. Mas Saul pensava lançar a Davi em mãos dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'E quando seus criados declararam a Davi estas palavras, foi conveniente a coisa nos olhos de Davi, para ser genro do rei. E quando o prazo não era ainda cumprido,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Levantou-se Davi, e partiu-se com sua gente, e feriu duzentos homens dos filisteus; e trouxe Davi os prepúcios deles, e entregaram-nos todos ao rei, para que ele fosse feito genro do rei. E Saul lhe deu a sua filha Mical por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Porém Saul, vendo e considerando que o SENHOR era com Davi, e que sua filha Mical o amava,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Temeu-se mais de Davi; e foi Saul inimigo de Davi todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'E saíam os príncipes dos filisteus; e quando eles saíam, portava-se Davi mais prudentemente que todos os servos de Saul: e era seu nome muito ilustre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'E falou Saul a Jônatas seu filho, e a todos os seus criados, para que matassem a Davi; mas Jônatas filho de Saul amava a Davi em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'E deu aviso a Davi, dizendo: Saul meu pai procura matar-te; portanto olha agora por ti até a manhã, e fica-te em lugar oculto, e esconde-te:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'E eu sairei e estarei junto a meu pai no campo de onde estiveres: e falarei de ti a meu pai, e te farei saber o que notar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'E Jônatas falou bem de Davi a Saul seu pai, e disse-lhe: Não peque o rei contra seu servo Davi, pois que nenhuma coisa cometeu contra ti: antes suas obras te foram muito boas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Porque ele pôs sua alma em sua palma, e feriu ao filisteu, e o SENHOR fez uma grande salvação a todo Israel. Tu o viste, e te alegraste: por que, pois, pecarás contra o sangue inocente, matando a Davi sem causa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'E ouvindo Saul a voz de Jônatas, jurou: Vive o SENHOR, que não morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Chamando então Jônatas a Davi, declarou-lhe todas estas palavras; e ele mesmo apresentou Davi a Saul, e esteve diante dele como antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'E voltou a fazer-se guerra: e saiu Davi e lutou contra os filisteus, e feriu-os com grande estrago, e fugiram diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'E o espírito mau da parte do SENHOR foi sobre Saul: e estando sentado em sua casa tinha uma lança à mão, enquanto Davi estava tocando harpa com sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'E Saul procurou encravar a Davi com a lança na parede; mas ele se afastou de diante de Saul, o qual feriu com a lança na parede; e Davi fugiu, e escapou-se aquela noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Saul enviou logo mensageiros à casa de Davi para que o guardassem, e o matassem à manhã. Mas Mical sua mulher o revelou a Davi, dizendo: Se não salvares tua vida esta noite, amanhã serás morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'E baixou Mical a Davi por uma janela; e ele se foi, e fugiu, e escapou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Tomou logo Mical uma estátua, e a pôs sobre a cama, e acomodou-lhe por cabeceira uma almofada de pelos de cabra, e cobriu-a com uma roupa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'E quando Saul enviou mensageiros que tomassem a Davi, ela respondeu: Está enfermo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'E voltou Saul a enviar mensageiros para que vissem a Davi, dizendo: Trazei-o a mim na cama para que o mate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'E quando os mensageiros entraram, eis que a estátua estava na cama, e uma almofada de pelos de cabra por cabeceira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Então Saul disse a Mical: Por que me enganaste assim, e deixaste escapar a meu inimigo? E Mical respondeu a Saul: Porque ele me disse: Deixa-me ir; se não, eu te matarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Fugiu, pois, Davi, e escapou-se, e veio a Samuel em Ramá, e disse-lhe tudo o que Saul havia feito com ele. E foram-se ele e Samuel, e moraram em Naiote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'E foi dado aviso a Saul, dizendo: Eis que Davi está em Naiote em Ramá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'E enviou Saul mensageiros que trouxessem a Davi, os quais viram uma companhia de profetas que profetizavam, e a Samuel que estava ali, e os presidia. E foi o espírito de Deus sobre os mensageiros de Saul, e eles também profetizaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'E feito que foi saber a Saul, ele enviou outros mensageiros, os quais também profetizaram. E Saul voltou a enviar pela terceira vez mensageiros, e eles também profetizaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Então ele mesmo veio a Ramá; e chegando ao poço grande que está em Socó, perguntou dizendo: Onde estão Samuel e Davi? E foi-lhe respondido: Eis que estão em Naiote em Ramá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'E foi ali a Naiote em Ramá; e também veio sobre ele o espírito de Deus, e ia profetizando, até que chegou a Naiote em Ramá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'E ele também se desnudou suas roupas, e profetizou igualmente diante de Samuel, e caiu nu todo aquele dia e toda aquela noite. De aqui se disse: Também Saul entre os profetas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'E Davi fugiu de Naiote que é em Ramá, e veio diante de Jônatas, e disse: Que fiz eu? qual é minha maldade, ou qual meu pecado contra teu pai, que ele busca minha vida?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'E ele lhe disse: Em nenhuma maneira; não morrerás. Eis que meu pai nenhuma coisa fará, grande nem pequena, que não a revele a mim; por que pois me encobrirá meu pai este negócio? Não será assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'E Davi voltou a jurar, dizendo: Teu pai sabe claramente que eu achei favor diante de teus olhos, e dirá: Não saiba isto Jônatas, para que não tenha pesar: e certamente, vive o SENHOR e vive tua alma, que apenas há um passo entre mim e a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'E Jônatas disse a Davi: Que diga tua alma, e eu o farei por ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'E Davi respondeu a Jônatas: Eis que amanhã será nova lua, e eu costumo sentar-me com o rei a comer: mas tu deixarás que me esconda no campo até à tarde do terceiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Se teu pai fizer menção de mim, dirás: Rogo-me muito que o deixasse ir logo a Belém sua cidade, porque todos os de sua linhagem têm ali sacrifício anual.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Se ele disser, Está bem, teu servo terá paz; mas se se irar, sabe que a malícia está nele completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Farás, pois, misericórdia com teu servo, já que trouxeste teu servo a aliança do SENHOR contigo: e se maldade há em mim mata-me tu, que não há necessidade de levar-me até teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'E Jônatas lhe disse: Nunca tal te suceda; antes bem, se eu entendesse ser completa a malícia de meu pai, para vir sobre ti, não havia eu de revelá-lo a ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Disse então Davi a Jônatas: Quem me dará aviso? Ou que se teu pai te responder asperamente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'E Jônatas disse a Davi: Vem, saiamos ao campo. E saíram ambos ao campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Então disse Jônatas a Davi: Ó SENHOR Deus de Israel, quando houver eu perguntado a meu pai amanhã a esta hora, ou depois de amanhã, e ele parecer bem para com Davi, se então não enviar a ti, e o revelar a ti,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'O SENHOR faça assim a Jônatas, e isto acrescente. Mas se a meu pai parecer bem fazer-te mal, também te o revelarei, e te enviarei, e te irás em paz: e seja o SENHOR contigo, como foi com meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'E se eu viver, farás comigo misericórdia do SENHOR; mas se for morto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Não tirarás perpetuamente tua misericórdia de minha casa, nem quando o SENHOR exterminar um por um os inimigos de Davi da face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Assim Jônatas fez aliança com a casa de Davi, dizendo: O SENHOR o exija da mão dos inimigos de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'E voltou Jônatas a jurar a Davi, porque o amava, porque o amava como à sua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Disse-lhe logo Jônatas: Amanhã é lua nova, e tua falta será percebida, porque teu assento estará vazio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Estarás, pois, três dias, e logo descerás, e virás ao lugar de onde estavas escondido o dia do incidente, e esperarás junto à pedra de Ezel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'E eu atirarei três flechas até aquele lado, como que me exercitando ao alvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'E logo enviarei o criado dizendo-lhe: Vai, busca as flechas. E se disser ao jovem: Eis ali as flechas mais aqui de ti, toma-as: tu virás, porque tens paz, e nada há de mal, vive o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Mas se eu disser ao jovem assim: Eis ali as flechas mais ali de ti: vai-te, porque o SENHOR te enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'E quanto às palavras que eu e tu falamos, seja o SENHOR entre mim e ti para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Então Davi se escondeu no campo, e vinda que foi a lua nova, sentou-se o rei a comer pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'E o rei se sentou em sua cadeira, como costumava, no assento junto à parede, e Jônatas se levantou, e sentou-se Abner ao lado de Saul, e o lugar de Davi estava vazio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Mas aquele dia Saul não disse nada, porque se dizia: Haverá lhe acontecido algo, e não está limpo; não estará purificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'O dia seguinte, o segundo dia da lua nova, aconteceu também que o assento de Davi estava vazio. E Saul disse a Jônatas seu filho: Por que não veio a comer o filho de Jessé hoje nem ontem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'E Jônatas respondeu a Saul: Davi me pediu encarecidamente lhe deixasse ir até Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'E disse: Rogo-te que me deixes ir, porque temos sacrifício os de nossa linhagem na cidade, e meu irmão mesmo me mandou; portanto, se achei graça em teus olhos, farei uma escapada agora, e visitarei a meus irmãos. Por isto, pois, não veio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Então Saul se acendeu contra Jônatas, e disse-lhe: Filho da pervertida e rebelde! Não sei eu que tu escolheste ao filho de Jessé para vergonha tua, e para vergonha da nudez de tua mãe?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Porque todo o tempo que o filho de Jessé viver sobre a terra, nem tu serás firme, nem teu reino. Envia, pois, agora, e traze-o a mim, porque morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'E Jônatas respondeu a seu pai Saul, e disse-lhe: Por que morrerá? O que ele fez?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Então Saul lhe lançou uma lança para feri-lo: de onde entendeu Jônatas que seu pai estava determinado a matar a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'E levantou-se Jônatas da mesa com exaltada ira, e não comeu pão o segundo dia da lua nova: porque tinha dor por causa de Davi, porque seu pai lhe havia afrontado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Ao outro dia de manhã, saiu Jônatas ao campo, ao tempo marcado com Davi, e um jovem pequeno com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'E disse a seu jovem: Corre e busca as flechas que eu atirar. E quando o jovem ia correndo, ele atirava a flecha que passava mais além dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'E chegando o jovem onde estava a flecha que Jônatas havia atirado, Jônatas deu vozes atrás o jovem, dizendo: Não está a flecha mais além de ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'E voltou a gritar Jônatas atrás o jovem: Apressa-te, corre, não pares. E o jovem de Jônatas agarrou as flechas, e veio a seu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Porém nenhuma coisa entendeu o jovem: somente Jônatas e Davi entendiam o negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Logo deu Jônatas suas armas a seu jovem, e disse-lhe: Vai-te e leva-as à cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'E logo que o jovem se havia ido, se levantou Davi da parte do sul, e inclinou-se três vezes prostrando-se até a terra: e beijando-se o um ao outro, choraram o um com o outro, ainda que Davi chorou mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'E Jônatas disse a Davi: Vai-te em paz, que ambos juramos pelo nome do SENHOR, dizendo: o SENHOR seja entre mim e ti, entre minha descendência e a tua descendência para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'E veio Davi a Nobe, a Aimeleque sacerdote: e surpreendeu-se Aimeleque de seu encontro, e disse-lhe: Como tu somente, e ninguém contigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'E respondeu Davi ao sacerdote Aimeleque: O rei me encomendou um negócio, e me disse: Ninguém saiba coisa alguma deste negócio a que eu te envio, e que eu te mandei; e eu assinalei aos criados certo lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Agora, pois, o que tens à mão? Dá-me cinco pães, ou o que se achar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'E o sacerdote respondeu a Davi, e disse: Não tenho pão comum à mão; somente tenho pão sagrado: mas o darei se os criados se abstiveram de mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'E Davi respondeu ao sacerdote, e disse-lhe: Certamente as mulheres nos foram afastadas desde anteontem quando saí, e os instrumentos dos moços foram santos, ainda que a jornada seja comum; quanto mais que hoje haverá outro pão santificado nos vasos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Assim o sacerdote lhe deu o pão sagrado, porque ali não havia outro pão que os pães da proposição, os quais haviam sido tirados de diante do SENHOR, para que se pusessem pães quentes o dia que os outros foram tirados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Aquele dia estava ali um dos servos de Saul detido diante do SENHOR, o nome do qual era Doegue, edomita, principal dos pastores de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'E Davi disse a Aimeleque: Não tens aqui à mão lança ou espada? Porque não tomei em minha mão minha espada nem minhas armas, porquanto o mandamento do rei era urgente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'E o sacerdote respondeu: A espada de Golias o filisteu, que tu venceste no vale de Elá, está aqui embrulhada em um véu detrás do éfode: se tu queres tomá-la, toma-a: porque aqui não há outra a não ser essa. E disse Davi: Nenhuma como ela: dá-a a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'E levantando-se Davi aquele dia, fugiu da presença de Saul, e veio a Aquis rei de Gate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'E os servos de Aquis lhe disseram: Não é este Davi, o rei da terra? Não é este a quem cantavam em danças, dizendo: Feriu Saul seus milhares, E Davi seus dez milhares?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'E Davi pôs em seu coração estas palavras, e teve grande temor de Aquis rei de Gate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'E mudou sua fala diante deles, e fingiu-se de louco entre suas mãos, e riscava nas entradas das portas, deixando escorrer sua saliva por sua barba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'E disse Aquis a seus servos: Eis que estais vendo um homem demente; por que o trouxestes a mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Faltam a mim loucos, para que trouxésseis este que fizesse de louco diante de mim? havia de vir este à minha casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'E indo-se Davi dali escapou-se à cova de Adulão; o qual quando ouviram seus irmãos e toda a casa de seu pai, vieram ali a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'E juntaram-se com ele todos os afligidos, e todo aquele que estava endividado, e todos os que se achavam em amargura de espírito, e foi feito capitão deles: e teve consigo como quatrocentos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'E foi-se Davi dali a Mispá de Moabe, e disse ao rei de Moabe: Eu te rogo que meu pai e minha mãe estejam convosco, até que saiba o que Deus fará de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Trouxe-os, pois, à presença do rei de Moabe, e habitaram com ele todo aquele tempo que Davi esteve na fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'E Gade profeta disse a Davi: Não fiques nesta fortaleza, parte-te, e vai-te à terra de Judá. E Davi se partiu, e veio ao bosque de Herete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'E ouviu Saul como havia aparecido Davi, e os que estavam com ele. Estava então Saul em Gibeá debaixo de uma árvore em Ramá, e tinha sua lança em sua mão, e todos os seus criados estavam em derredor dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'E disse Saul a seus criados que estavam em derredor dele: Ouvi agora, filhos de Benjamim: O filho de Jessé também dará a todos vós terras e vinhas, e vos fará a todos comandantes de mim e comandantes de cem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Que todos vós conspirastes contra mim, e não há quem me revele ao ouvido como meu filho fez aliança com o filho de Jessé, nem alguém de vós que se condoa de mim, e me revele como meu filho levantou meu servo contra mim, para que me prepare ciladas, como ele hoje faz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Então Doegue edomita, que era superior entre os servos de Saul, respondeu e disse: Eu vi ao filho de Jessé que veio a Nobe, a Aimeleque filho de Aitube;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'O qual consultou por ele ao SENHOR, e deu-lhe provisão, e também lhe deu a espada de Golias o filisteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'E o rei enviou pelo sacerdote Aimeleque filho de Aitube, e por toda a casa de seu pai, os sacerdotes que estavam em Nobe: e todos vieram ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'E Saul lhe disse: Ouve agora, filho de Aitube. E ele disse: Eis-me aqui, senhor meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'E disse-lhe Saul: Por que conspirastes contra mim, tu e o filho de Jessé, quando tu lhe deste pão e espada, e consultaste por ele a Deus, para que se levantasse contra mim e me armasse cilada, como o faz hoje dia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Então Aimeleque respondeu ao rei, e disse: E quem entre todos teus servos é tão fiel como Davi, genro também do rei, e que vai por teu mandado, e é ilustre em tua casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Comecei eu desde hoje a consultar por ele a Deus? Longe seja de mim: não impute o rei coisa alguma a seu servo, nem a toda a casa de meu pai; porque teu servo nenhuma coisa sabe deste negócio, grande nem pequena.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'E o rei disse: Sem dúvida morrerás, Aimeleque, tu e toda a casa de teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Então disse o rei à gente de sua guarda que estava ao redor dele: Voltai-vos e matai aos sacerdotes do SENHOR; porque também a mão deles é com Davi, pois sabendo eles que fugia, não o revelaram a mim. Mas os servos do rei não quiseram estender suas mãos para matar os sacerdotes do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Então disse o rei a Doegue: Volta tu, e arremete contra os sacerdotes. E revolvendo-se Doegue edomita, arremeteu contra os sacerdotes, e matou naquele dia oitenta e cinco homens que vestiam éfode de linho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'E a Nobe, cidade dos sacerdotes, pôs à espada: tanto a homens como a mulheres, meninos e mamantes, bois e asnos e ovelhas, tudo à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Mas um dos filhos de Aimeleque filho de Aitube, que se chamava Abiatar, escapou, e fugiu-se a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'E Abiatar noticiou a Davi como Saul havia matado os sacerdotes do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'E disse Davi a Abiatar: Eu sabia que estando ali aquele dia Doegue o edomita, ele o havia de fazer saber a Saul. Eu dei ocasião contra todas as pessoas da casa de teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Fica-te comigo, não temas: quem buscar minha vida, buscará também a tua: bem que comigo tu estarás seguro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'E deram aviso a Davi, dizendo: Eis que os filisteus combatem a Queila, e roubam as eiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'E Davi consultou ao SENHOR, dizendo: Irei a ferir a estes filisteus? E o SENHOR respondeu a Davi: Vai, fere aos filisteus, e livra a Queila.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Mas os que estavam com Davi lhe disseram: Eis que nós aqui em Judá estamos com medo; quanto mais se formos a Queila contra o exército dos filisteus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Então Davi voltou a consultar ao SENHOR. E o SENHOR lhe respondeu, e disse: Levanta-te, desce a Queila, que eu entregarei em tuas mãos aos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Partiu-se, pois Davi com seus homens a Queila, e lutou contra os filisteus, e tomou seus gados, e feriu-os com grande estrago: e livrou Davi aos de Queila.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'E aconteceu que, fugindo Abiatar filho de Aimeleque a Davi a Queila, veio também com ele o éfode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'E foi dito a Saul que Davi havia vindo a Queila. Então disse Saul: Deus o trouxe a minhas mãos; porque ele está escondido, havendo-se posto em cidade com portas e fechaduras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'E convocou Saul todo aquele povo à batalha, para descer a Queila, e pôr cerco a Davi e aos seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Mas entendendo Davi que Saul planejava o mal contra ele, disse a Abiatar sacerdote: Traze o éfode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'E disse Davi: o SENHOR Deus de Israel, teu servo tem entendido que Saul trata de vir contra Queila, a destruir a cidade por causa minha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Os vizinhos de Queila me entregarão em suas mãos? Descerá Saul, como teu servo tem ouvido? O SENHOR Deus de Israel, rogo-te que o declares a teu servo. E o SENHOR disse: Sim, descerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Disse logo Davi: Os vizinhos de Queila entregarão a mim e a meus homens em mãos de Saul? E o SENHOR respondeu: Eles te entregarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Davi então se levantou com seus homens, que eram como seiscentos, e sairam de Queila, e foram-se de uma parte à outra. E veio a nova a Saul de como Davi se havia escapado de Queila; e deixou de sair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'E Davi se estava no deserto em penhas, e habitava em um monte no deserto de Zife; e Saul o buscava todos os dias, mas Deus não o entregou em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Vendo, pois, Davi que Saul havia saído em busca de sua alma, estava-se ele no bosque no deserto de Zife.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Então se levantou Jônatas filho de Saul, e veio a Davi no bosque, e confortou sua mão em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'E disse-lhe: Não temas, porque a mão de meu pai Saul não te achará, e tu reinarás sobre Israel, e eu serei segundo depois de ti; e ainda Saul meu pai assim o sabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'E entre ambos fizeram aliança diante do SENHOR: e Davi se ficou no bosque, e Jônatas se voltou à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'E subiram os de Zife a dizer a Saul em Gibeá: Não está Davi escondido em nossa terra nas penhas do bosque, no morro de Haquilá que está à direita do deserto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Portanto, rei, desce agora logo, segundo todo aquele desejo de tua alma, e nós o entregaremos na mão do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'E Saul disse: Benditos sejais vós do SENHOR, que haveis tido compaixão de mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Ide, pois, agora, preparai ainda, considerai e vede seu lugar por onde ele passa, e quem o tenha visto ali; porque se me disse que ele é em grande maneira astuto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Considerai, pois, e vede todos os esconderijos de onde se oculta, e voltai a mim com a certeza, e eu irei convosco: que se ele estiver na terra, eu lhe buscarei entre todos os milhares de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'E eles se levantaram, e se foram a Zife diante de Saul. Mas Davi e sua gente estavam no deserto de Maom, na planície que está à direita do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'E partiu-se Saul com sua gente a buscá-lo; mas foi dado aviso a Davi, e desceu à penha, e ficou no deserto de Maom. O qual quando Saul ouviu, seguiu a Davi ao deserto de Maom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'E Saul ia pelo um lado do monte, e Davi com os seus pelo outro lado do monte: e apressava-se Davi para ir adiante de Saul; mas Saul e os seus haviam cercado a Davi e à sua gente para tomá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Então veio um mensageiro a Saul, dizendo: Vem logo, porque os filisteus fizeram uma invasão no país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Voltou-se, portanto, Saul de perseguir a Davi, e partiu contra os filisteus. Por esta causa puseram a aquele lugar por nome Selá-Hamalecote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'Então Davi subiu dali, e habitou nos lugares fortes em En-Gedi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'E quando Saul voltou dos filisteus, deram-lhe aviso dizendo: Eis que Davi está no deserto de En-Gedi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'E tomando Saul três mil homens escolhidos de todo Israel, foi em busca de Davi e dos seus, pelos cumes dos penhascos das cabras montesas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'E quando chegou a uma malhada de ovelhas no caminho, de onde havia uma cova, entrou Saul nela para fazer necessidade; e Davi e os seus estavam aos lados da cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Então os de Davi lhe disseram: Eis que o dia que te disse o SENHOR: Eis que entregou tu inimigo em tuas mãos, e farás com ele como te parecer. E levantou-se Davi, e caladamente cortou a beira do manto de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Depois do qual o coração de Davi lhe golpeava, porque havia cortado a beira do manto de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'E disse aos seus: o SENHOR me guarde de fazer tal coisa contra meu senhor, o ungido do SENHOR, que eu estenda minha mão contra ele; porque é o ungido do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Assim Davi conteve os seus com palavras, e não lhes permitiu que se levantassem contra Saul. E Saul, saindo da cova, foi-se seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Também Davi se levantou depois, e saindo da cova deu vozes às costas de Saul, dizendo: Meu senhor o rei! E quando Saul olhou atrás, Davi inclinou seu rosto em terra, e fez reverência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'E disse Davi a Saul: Por que ouves as palavras dos que dizem: Olha que Davi procura teu mal?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Eis que viram hoje teus olhos como o SENHOR te pôs hoje em minhas mãos na cova: e disseram que te matasse, mas te poupei, porque disse: Não estenderei minha mão contra meu senhor, porque ungido é do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'E olha, meu pai, olha ainda a beira de teu manto em minha mão: porque eu cortei a beira de tua manto, e não te matei. Conhece, pois, e vê que não há mal nem traição em minha mão, nem pequei contra ti; contudo, tu andas à caça de minha vida para tirá-la de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Julgue o SENHOR entre mim e ti, e vingue-me de ti o SENHOR: porém minha mão não será contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Como diz o provérbio dos antigos: Dos ímpios sairá a impiedade: assim que minha mão não será contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Atrás de quem saiu o rei de Israel? a quem persegues? a um cão morto? a uma pulga?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'O SENHOR, pois, será juiz, e ele julgará entre mim e ti. Ele veja, e sustente minha causa, e me defenda de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'E aconteceu que, quando Davi acabou de dizer estas palavras a Saul, Saul disse: Não é esta a tua voz, meu filho Davi? E Saul, levantando sua voz, chorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'E disse a Davi: Mais justo és tu que eu, que me pagaste com bem, havendo-te eu pagado com mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Tu mostraste hoje que fizeste comigo bem; pois não me mataste, havendo-me o SENHOR posto em tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Porque quem achará a seu inimigo, e o deixará ir saro e salvo? O SENHOR te pague com bem pelo que neste dia fizeste comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'E agora, como eu entendo que tu hás de reinar, e que o reino de Israel será em tua mão firme e estável,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Jura-me, pois, agora pelo SENHOR, que não cortarás minha descendência depois de mim, nem apagarás meu nome da casa de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Então Davi jurou a Saul. E foi-se Saul à sua casa, e Davi e os seus se subiram ao lugar forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'E morreu Samuel, e juntou-se todo Israel, e o choraram, e o sepultaram em sua casa em Ramá. E levantou-se Davi, e se foi ao deserto de Parã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'E em Maom havia um homem que tinha sua riqueza no Carmelo, o qual era muito rico, que tinha três mil ovelhas e mil cabras. E aconteceu achar-se tosquiando suas ovelhas no Carmelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'O nome daquele homem era Nabal, e o nome de sua mulher, Abigail. E era aquela mulher de bom entendimento e de boa aparência; mas o homem era duro e de maus feitos; e era da linhagem de Calebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'E ouviu Davi no deserto que Nabal tosquiava suas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Então enviou Davi dez criados, e disse-lhes: Subi ao Carmelo, e ide a Nabal, e saudai-lhe em meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'E dizei-lhe assim: Que vivas e seja paz a ti, e paz à tua família, e paz a tudo quanto tens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Há pouco soube que tens tosquiadores. Agora, aos pastores teus que estiveram conosco, nunca lhes maltratamos, nem lhes faltou algo em todo aquele tempo que estiveram no Carmelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Pergunta a teus criados, que eles te dirão. Portanto que estes criados achem favor em teus olhos, pois viemos em um bom dia; rogo-te que dês o que tiveres à mão a teus servos, e a teu filho Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'E quando chegaram os criados de Davi, disseram a Nabal todas estas palavras em nome de Davi, e se calaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'E Nabal respondeu aos criados de Davi, e disse: Quem é Davi? e quem é o filho de Jessé? Muitos servos há hoje que fogem de seus senhores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Tomarei eu agora meu pão, minha água, e minha carne que matei para meus tosquiadores, e a darei a homens que não sei de onde são?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'E virando-se os criados de Davi, voltaram por seu caminho, e vieram e disseram a Davi todas estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Então Davi disse a seus homens: Cinja-se cada um sua espada. E cingiu-se cada um sua espada: também Davi cingiu sua espada; e subiram atrás Davi como quatrocentos homens, e deixaram duzentos com a bagagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'E um dos criados deu aviso a Abigail mulher de Nabal, dizendo: Eis que Davi enviou mensageiros do deserto que saudassem a nosso amo, e ele os insultou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Mas aqueles homens nos foram muito bons, e nunca nos maltrataram, nem nenhuma coisa nos faltou em todo aquele tempo que convivido com eles, enquanto estivemos no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Eles nos foram por muro de dia e de noite, todos os dias que estivemos com eles apascentando as ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Agora, pois, entende e olha o que farás, porque o mal está de todo decidido contra nosso amo e contra toda sua casa: pois ele é um homem tão mau, que não há quem podia falar-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Então Abigail tomou logo duzentos pães, e dois odres de vinho, e cinco ovelhas guisadas, e cinco medidas de grão tostado, e cem cachos de uvas passas, e duzentos pães de figos secos, e carregou-o em asnos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'E disse a seus criados: Ide diante de mim, que eu vos seguirei logo. E nada declarou a seu marido Nabal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'E sentando-se sobre um asno desceu por uma parte secreta do monte, e eis que Davi e os seus que vinham de frente a ela, e ela lhes foi ao encontro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'E Davi havia dito: Certamente em vão guardei tudo o que este tem no deserto, sem que nada lhe tenha faltado de tudo quanto é seu; e ele me devolveu mal por bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Assim faça Deus, e assim acrescente aos inimigos de Davi, que daqui à amanhã não tenho de deixar de tudo o que for seu nem ainda macho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'E quando Abigail viu a Davi, desceu prontamente do asno, e prostrando-se diante de Davi sobre seu rosto, inclinou-se à terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'E lançou-se a seus pés, e disse: Senhor meu, sobre mim seja o pecado; mas rogo-te fale tua serva em teus ouvidos, e ouve as palavras de tua serva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Não ponha agora meu senhor seu coração a aquele homem grosseiro, a Nabal; porque conforme seu nome, assim é. O se chama Nabal, e a loucura está com ele: mas eu tua serva não vi os criados de meu senhor, os quais tu enviaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Agora, pois, senhor meu, vive o SENHOR e vive tua alma, que o SENHOR te impediu que viesses a derramar sangue, e vingar-te por tua própria mão. Sejam, pois, como Nabal teus inimigos, e todos os que procuram mal contra meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'E agora esta bênção que tua serva trouxe a meu senhor, seja dada aos criados que seguem a meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'E eu te rogo que perdoes a tua serva esta ofensa; pois o SENHOR de certo fará casa firme a meu senhor, porquanto meu senhor faz as guerras do SENHOR, e mal não se achou em ti em teus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Bem que alguém se tenha levantado a perseguir-te e atentar à tua vida, contudo, a alma de meu senhor será ligada no feixe dos que vivem com o SENHOR Deus teu, e ele atirará a alma de teus inimigos como de uma funda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'E acontecerá que quando o SENHOR fizer com meu senhor conforme todo aquele bem que falou de ti, e te mandar que sejas chefe sobre Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Então, senhor meu, não te será isto em tropeço e turbação de coração, o que tenhas derramado sangue sem causa, ou que meu senhor se tenha vingado por si mesmo. Guarde-se, pois, meu senhor, e quando o SENHOR fizer bem a meu senhor, lembra-te de tua serva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'E disse Davi a Abigail: Bendito seja o SENHOR Deus de Israel, que te enviou para que hoje me encontrasses;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'E bendito seja teu bom-senso, e bendita tu, que me impediste hoje de ir derramar sangue, e de vingar-me por minha própria mão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Porque, vive o SENHOR Deus de Israel que me defendeu de fazer-te mal, que se não te houvesses apressado em vir ao meu encontro, daqui a amanhã não lhe restaria a Nabal macho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'E recebeu Davi de sua mão o que lhe havia trazido, e disse-lhe: Sobe em paz à tua casa, e olha que ouvi tua voz, e te atendi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'E Abigail se veio a Nabal, e eis que ele tinha banquete em sua casa como banquete de rei: e o coração de Nabal estava alegre nele, e estava muito embriagado; pelo que ela não lhe declarou pouco nem muito, até que veio o dia seguinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Porém à manhã, quando o vinho havia saído de Nabal, referiu-lhe sua mulher aquelas coisas; e se lhe amorteceu o coração, e ficou como pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'E passados dez dias o SENHOR feriu a Nabal, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'E logo que Davi ouviu que Nabal era morto, disse: Bendito seja o SENHOR que julgou a causa de minha afronta recebida da mão de Nabal, e preservou do mal a seu servo; e o SENHOR devolveu a malícia de Nabal sobre sua própria cabeça. Depois enviou Davi a falar a Abigail, para tomá-la por sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'E os criados de Davi vieram a Abigail no Carmelo, e falaram com ela, dizendo: Davi nos enviou a ti, para tomar-te por sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'E ela se levantou, e inclinou seu rosto à terra, dizendo: Eis que tua serva, para que seja serva que lave os pés dos servos de meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'E levantando-se logo Abigail com cinco moças que a seguiam, montou-se em um asno, e seguiu os mensageiros de Davi, e foi sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Também tomou Davi a Ainoã de Jezreel, e ambas foram suas mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Porque Saul havia dado sua filha Mical mulher de Davi, a Palti filho de Laís, que era de Galim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'E vieram os zifeus a Saul em Gibeá, dizendo: Não está Davi escondido no morro de Haquilá diante do deserto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Saul então se levantou, e desceu ao deserto de Zife, levando consigo três mil homens escolhidos de Israel, para buscar a Davi no deserto de Zife.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'E assentou Saul o campo no morro de Haquilá, que está diante do deserto junto ao caminho. E estava Davi no deserto, e entendeu que Saul lhe seguia no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Davi, portanto, enviou espias, e entendeu por certo que Saul havia vindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'E levantou-se Davi, e veio ao lugar de onde Saul havia assentado o acampamento; e olhou Davi o lugar de onde dormia Saul, e Abner filho de Ner, general de seu exército. E estava Saul dormindo na trincheira, e o povo pelo acampamento em derredor dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Então falou Davi, e perguntou a Aimeleque Heteu, e a Abisai filho de Zeruia, irmão de Joabe, dizendo: Quem descerá comigo a Saul ao campo: E disse Abisai: Eu descerei contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Davi pois e Abisai vieram ao povo de noite: e eis que Saul que estava estendido dormindo na trincheira, e sua lança fincada em terra à sua cabeceira; e Abner e o povo estavam ao redor dele estendidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Então disse Abisai a Davi: Hoje Deus entregou a teu inimigo em tuas mãos: agora pois, eu o ferirei logo com a lança, fincando-lhe com a terra de um golpe, e não precisarei repetir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'E Davi respondeu a Abisai: Não lhe mates: porque quem estender sua mão contra o ungido do SENHOR, e será inocente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Disse ademais Davi: Vive o SENHOR, que se o SENHOR não o ferir, ou que seu dia chegue para que morra, ou que descendo em batalha pereça,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Guarde-me o SENHOR de estender minha mão contra o ungido do SENHOR; porém toma agora a lança que está à sua cabeceira, e a botija da água, e vamo-nos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Levou pois Davi a lança e a botija de água da cabeceira de Saul, e foram-se; que não houve ninguém que visse, nem entendesse, nem vigiasse, pois todos dormiam: porque um profundo sonho enviado do SENHOR havia caído sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'E passando Davi da outra parte, pôs-se desviado no cume do monte, havendo grande distância entre eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'E deu vozes Davi ao povo, e a Abner filho de Ner, dizendo: Não respondes, Abner? Então Abner respondeu e disse: Quem és tu que dás vozes ao rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'E disse Davi a Abner: Não és tu homem? E quem há como tu em Israel? Por que, pois, não guardaste ao teu senhor, o rei? Pois entrou um do povo para matar ao teu senhor, o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Isto que fizeste não está bem. Vive o SENHOR, que sois dignos de morte, que não guardastes a vosso senhor, ao ungido do SENHOR. Olha, pois, agora onde está a lança do rei, e a botija da água que estava à sua cabeceira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'E reconhecendo Saul a voz de Davi, disse: Não é esta tua voz, meu filho Davi? E Davi respondeu: É minha voz, ó rei, meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'E disse: Por que persegue assim meu senhor a seu servo? que fiz? que mal há em minha mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Rogo, pois, que o rei meu senhor ouça agora as palavras de seu servo. Se o SENHOR te incita contra mim, aceite um sacrifício: mas se forem filhos de homens, malditos eles na presença do SENHOR, que me expulsaram hoje para que não me junte na propriedade do SENHOR, dizendo: Vai, e serve a outros deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Não caia, pois agora meu sangue em terra diante do SENHOR: porque saiu o rei de Israel a buscar uma pulga, assim como quem persegue uma perdiz pelos montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Então disse Saul: Pequei: volta-te, filho meu Davi, que nenhum mal te farei mais, pois que minha vida foi estimada hoje em teus olhos. Eis que eu agi loucamente, e errei em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'E Davi respondeu, e disse: Eis que a lança do rei; passe aqui um dos criados, e tome-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'E o SENHOR pague a cada um sua justiça e sua lealdade: que o SENHOR havia te entregue hoje em minha mão, mas eu não quis estender minha mão sobre o ungido do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'E eis que, como tua vida foi estimada hoje em meus olhos, assim seja minha vida estimada nos olhos do SENHOR, e me livre de toda aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'E Saul disse a Davi: Bendito és tu, filho meu Davi; sem dúvida tu executarás grandes feitos, e prevalecerás. Então Davi se foi por seu caminho, e Saul voltou ao seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'E disse Davi em seu coração: Ao fim serei morto algum dia pela mão de Saul: nada portanto me será melhor que fugir à terra dos filisteus, para que Saul se deixe de mim, e não me ande buscando mais por todos os termos de Israel, e assim me escaparei de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Levantou-se, pois Davi, e com os seiscentos homens que tinha consigo passou-se a Aquis filho de Maoque, rei de Gate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'E morou Davi com Aquis em Gate, ele e os seus, cada um com sua família: Davi com suas duas mulheres, Ainoã jezreelita, e Abigail, a que foi mulher de Nabal o do Carmelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'E veio a nova a Saul que Davi se havia fugido a Gate, e não o buscou mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'E Davi disse a Aquis: Se achei agora favor em teus olhos, seja-me dado lugar em algumas das cidades da terra, de onde eu habite; por que teu servo deverá morar contigo na cidade real?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'E Aquis lhe deu aquele dia a Ziclague. De aqui foi Ziclague dos reis de Judá até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'E foi o número dos dias que Davi habitou na terra dos filisteus, quatro meses e alguns dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'E subia Davi com os seus, e faziam entradas nos gesuritas, e nos gersitas, e nos amalequitas: porque estes habitavam de longo tempo a terra, desde como se vai a Sur até a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'E feria Davi o país, e não deixava à vida homem nem mulher: e levava-se as ovelhas e as vacas e os asnos e os camelos e as roupas; e voltava, e vinha-se a Aquis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'E dizia Aquis: Onde atacastes hoje? E Davi dizia: Ao sul de Judá, e ao sul de Jerameel, ou contra o sul dos queneus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Nem homem nem mulher deixava à vida Davi, que viesse a Gate; dizendo: Porque não deem aviso de nós, dizendo: Isto fez Davi. E este era seu costume todo aquele tempo que morou em terra dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'E Aquis confiava em Davi, dizendo assim: Ele se faz abominável em seu povo de Israel, e será meu servo para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'E aconteceu que em aqueles dias os filisteus juntaram seus acampamentos para lutar contra Israel. E disse Aquis a Davi: Sabe de certo que hás de sair comigo à campanha, tu e os teus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'E Davi respondeu a Aquis: Saberás, pois, o que fará teu servo. E Aquis disse a Davi: Portanto te farei guarda de minha cabeça todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Já Samuel era morto, e todo Israel o havia lamentado, e haviam-lhe sepultado em Ramá, em sua cidade. E Saul havia lançado da terra os encantadores e adivinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Pois como os filisteus se juntaram, vieram e assentaram acampamento em Suném: e Saul juntou a todo Israel, e assentaram acampamento em Gilboa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'E quando viu Saul o acampamento dos filisteus, temeu, e perturbou-se seu coração em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'E consultou Saul ao SENHOR; mas o SENHOR não lhe respondeu, nem por sonhos, nem por Urim, nem por profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Então Saul disse a seus criados: Buscai-me uma mulher que tenha espírito de necromante, para que eu vá a ela, e por meio dela pergunte. E seus criados lhe responderam: Eis que há uma mulher em En-Dor que tem espírito de necromante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'E Saul se disfarçou, vestiu outras roupas, e foi-se com dois homens, e vieram àquela mulher de noite; e ele disse: Eu te rogo que me adivinhes pelo espírito de pitonisa, e me faças subir a quem eu te disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'E a mulher lhe disse: Eis que tu sabes o que Saul fez, como exterminou da terra os necromantes e os adivinhos; por que, pois, pões tropeço à minha vida, para me fazer morrer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Então Saul jurou a ela pelo SENHOR, dizendo: Vive o SENHOR, que nenhum mal te virá por isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'A mulher então disse: A quem te farei vir? E ele respondeu: Faze-me vir a Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'E vendo a mulher a Samuel, clamou em alta voz, e falou aquela mulher a Saul, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Por que me enganaste? que tu és Saul. E o rei lhe disse: Não temas: que viste? E a mulher respondeu a Saul: Vi deuses que sobem da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'E ele lhe disse: Qual é sua forma? E ela respondeu: Um homem ancião vem, coberto de um manto. Saul então entendeu que era Samuel, e humilhando o rosto à terra, fez grande reverência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'E Samuel disse a Saul: Por que me inquietaste fazendo-me vir? E Saul respondeu: Estou muito angustiado; pois os filisteus lutam contra mim, e Deus se afastou de mim, e não me responde mais, nem por meio de profetas, nem por sonhos: por isto te chamei, para que me declares o que tenho de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Então Samuel disse: E para que perguntas a mim, havendo-se afastado de ti o SENHOR, e é teu inimigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'o SENHOR pois fez como falou por meio de mim; pois cortou o SENHOR o reino de tua mão, e o deu a tua companheiro Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Como tu não obedeceste à voz do SENHOR, nem cumpriste o furor de sua ira sobre Amaleque, por isso o SENHOR te fez isto hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'E o SENHOR entregará a Israel também contigo nas mãos dos filisteus: e amanhã estareis comigo, tu e teus filhos; e ainda o acampamento de Israel o SENHOR entregará nas mãos dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Naquele mesmo momento Saul caiu estendido ao chão, e teve grande temor pelas palavras de Samuel; que não restou nele esforço nenhum, porque em todo aquele dia e aquela noite não havia comido pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Então a mulher veio a Saul, e vendo-lhe em grande maneira perturbado, disse-lhe: Eis que tua criada obedeceu à tua voz, e pus minha vida em minha mão, e ouvi as palavras que tu me disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Rogo-te, pois, que tu também ouças a voz de tua serva: porei eu diante de ti um bocado de pão que comas, para que te fortaleças, e vás teu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'E ele o recusou, dizendo: Não comerei. Mas seus criados juntamente com a mulher lhe obrigaram, e ele os obedeceu. Levantou-se, pois, do chão, e sentou-se sobre uma cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'E aquela mulher tinha em sua casa um bezerro gordo, o qual matou logo; e tomou farinha e amassou-a, e cozeu dela pães sem levedura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'E o trouxe diante de Saul e de seus criados; e assim que comeram, se levantaram, e partiram aquela noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'E os filisteus juntaram todos os seus acampamentos em Afeque; e Israel pôs seu acampamento junto à fonte que está em Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'E enquanto os príncipes dos filisteus revistavam suas tropas de centenas e de milhares de homens, Davi e os seus passavam na retaguarda com Aquis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'E disseram os príncipes dos filisteus: Que fazem aqui estes hebreus? E Aquis respondeu aos príncipes dos filisteus: Não é este Davi, o servo de Saul rei de Israel? Ele esteve comigo alguns dias ou alguns anos, e não achei coisa alguma nele desde o dia que ele veio a mim até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Então os príncipes dos filisteus se iraram contra ele, e disseram-lhe: Envia a este homem, que se volte ao lugar que lhe determinaste, e não venha conosco à batalha, não seja que na batalha se nos volte inimigo; pois com que coisa ele se reconciliaria com seu senhor, se não com as cabeças destes homens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Não é este Davi de quem cantavam nas danças, dizendo: Saul feriu seus milhares, E Davi seus dez milhares?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'E Aquis chamou a Davi, e disse-lhe: Vive o SENHOR, que tu foste reto, e que me pareceu bem tua saída e entrada no campo comigo, e que nenhuma coisa má achei em ti desde o dia que vieste a mim até hoje; mas aos olhos dos príncipes não agradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Volta-te, pois, e vai-te em paz; e não faças o mal aos olhos dos príncipes dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'E Davi respondeu a Aquis: Que fiz? que achaste em teu servo desde o dia que estou contigo até hoje, para que eu não vá e lute contra os inimigos de meu senhor o rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'E Aquis respondeu a Davi, e disse: Eu sei que tu és bom em meus olhos, como um anjo de Deus; mas os príncipes dos filisteus disseram: Não venha conosco à batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Levanta-te, pois de manhã, tu e os servos de teu senhor que vieram contigo; e levantando-vos de manhã, logo ao amanhecer parti-vos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'E levantou-se Davi de manhã, ele e os seus, para ir-se e voltar-se à terra dos filisteus; e os filisteus foram a Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'E Quando Davi e os seus vieram a Ziclague o terceiro dia, os de Amaleque haviam invadido o sul e a Ziclague, e haviam assolado a Ziclague, e posto-a a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'E haviam-se levado cativas às mulheres que estavam nela, desde a menor até a maior; mas a ninguém haviam matado, mas sim levado, e ido seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Veio, pois Davi com os seus à cidade, e eis que estava queimada a fogo, e suas mulheres e seus filhos e filhas levadas cativas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Então Davi e a gente que com ele estava, levantaram sua voz e choraram, até que lhes faltaram as forças para chorar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'As duas mulheres de Davi, Ainoã jezreelita e Abigail a que foi mulher de Nabal do Carmelo, também eram cativas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'E Davi foi muito angustiado, porque o povo falava de apedrejá-lo; porque todo aquele povo estava com ânimo amargo, cada um por seus filhos e por suas filhas: mas Davi se esforçou no SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'E disse Davi ao sacerdote Abiatar filho de Aimeleque: Eu te rogo que me tragas o éfode. E Abiatar trouxe o éfode a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'E Davi consultou ao SENHOR, dizendo: Seguirei esta tropa? Poderei alcançá-la? E ele lhe disse: Segue-a que de certo a alcançarás, e sem falta livrarás a presa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Partiu-se, pois, Davi, ele e os seiscentos homens que com ele estavam, e vieram até o ribeiro de Besor, de onde se restaram alguns.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'E Davi seguiu o alcance com quatrocentos homens; porque se restaram atrás duzentos, que cansados não puderam passar o ribeiro de Besor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'E acharam no acampamento um homem egípcio, o qual trouxeram a Davi, e deram-lhe pão que comesse, e a beber água;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Deram-lhe também um pedaço de massa de figos secos, e dois cachos de passas. E logo que comeu, voltou nele seu espírito; porque não havia comido pão nem bebido água em três dias e três noites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'E disse-lhe Davi: De quem és tu? E de onde és? E respondeu o jovem egípcio: Eu sou servo de um amalequita, e deixou-me meu amo hoje há três dias, porque estava enfermo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Pois fizemos uma incursão à parte do sul dos queretitas, e a Judá, e ao sul de Calebe; e pusemos fogo a Ziclague.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'E disse-lhe Davi: Tu me levarás a essa tropa? E ele disse: Faze-me juramento por Deus que não me matarás, nem me entregarás nas mãos de meu amo, e eu te levarei a essa gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Então o levou-o; e eis que estavam dispersos sobre a face de toda aquela terra, comendo e bebendo e fazendo festa, por toda aquela grande presa que haviam tomado da terra dos filisteus, e da terra de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'E feriu-os Davi desde aquela manhã até à tarde do dia seguinte: e não escapou deles nenhum, a não ser quatrocentos rapazes, que haviam subido em camelos e fugiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'E livrou Davi tudo o que os amalequitas haviam tomado: e também libertou Davi a suas duas mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'E não lhes faltou coisa pequena nem grande, tanto de filhos como de filhas, do roubo, e de todas as coisas que lhes haviam tomado: todo o recuperou Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Tomou também Davi todas as ovelhas e gados maiores; e trazendo-o todo adiante, diziam: Esta é a presa de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'E veio Davi aos duzentos homens que haviam restado cansados e não haviam podido perseguir a Davi, aos quais haviam feito restar no ribeiro de Besor; e eles saíram a receber a Davi, e ao povo que com ele estava. E quando Davi chegou à gente, saudou-os com paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Então todos os maus e perversos dentre os que haviam ido com Davi, responderam e disseram: Pois que não foram conosco, não lhes daremos da presa que tiramos, a não ser a cada um sua mulher e seus filhos; os quais tomem e se vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'E Davi disse: Não façais isso, irmãos meus, do que nos deu o SENHOR; o qual nos guardou, e entregou em nossas mãos a caterva que veio sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'E quem vos escutará neste caso? Porque igual parte será a dos que vem à batalha, e a dos que ficam com a bagagem; que repartam juntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'E desde aquele dia em diante foi isto posto por lei e ordenança em Israel, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'E quando Davi chegou a Ziclague, enviou da presa aos anciãos de Judá, seus amigos, dizendo: Eis aqui uma bênção para vós, da presa dos inimigos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Aos que estavam em Betel, e em Ramote ao sul, e aos que estavam em Jattir;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'E aos que estavam em Aroer, e em Sifmote, e aos que estavam em Estemoa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'E aos que estavam em Racal, e aos que estavam nas cidades de Jerameel, e aos que estavam nas cidades dos queneus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'E aos que estavam em Hormá, e aos que estavam em Corasã, e aos que estavam em Atace;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'E aos que estavam em Hebrom, e em todos os lugares de onde Davi havia estado com os seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Então os filisteus lutaram com Israel, e os de Israel fugiram diante dos filisteus, e caíram mortos no monte de Gilboa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'E seguindo os filisteus a Saul e a seus filhos, mataram a Jônatas, e a Abinadabe, e a Malquisua, filhos de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'E agravou-se a batalha sobre Saul, e lhe alcançaram os flecheiros; e teve grande temor dos flecheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Então disse Saul a seu escudeiro: Tira tua espada, e passa-me com ela, porque não venham estes incircuncisos, e me passem, e me escarneçam. Mas seu escudeiro não queria, porque tinha grande temor. Então Saul tomou a espada, e lançou-se sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'E vendo seu escudeiro a Saul morto, ele também se lançou sobre sua espada, e morreu com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Assim morreu Saul naquele dia, juntamente com seus três filhos, e seu escudeiro, e todos os seus homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'E os de Israel que eram da outra parte do vale, e da outra parte do Jordão, vendo que Israel havia fugido, e que Saul e seus filhos eram mortos, deixaram as cidades e fugiram; e os filisteus vieram e habitaram nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'E aconteceu o dia seguinte, que vindo os filisteus a despojar os mortos, acharam a Saul e a seus três filhos estendidos no monte de Gilboa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'E cortaram-lhe a cabeça, e tiraram-lhe as armas; e enviaram ao redor da terra dos filisteus, para que o noticiassem no templo de seus ídolos, e pelo povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'E puseram suas armas no templo de Astarote, e colocaram seu corpo no muro de Bete-Seã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Mas ouvindo os de Jabes de Gileade isto que os filisteus fizeram a Saul,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Todos os homens valentes se levantaram, e andaram toda aquela noite, e tiraram o corpo de Saul e os corpos de seus filhos do muro de Bete-Seã; e vindo a Jabes, queimaram-nos ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'E tomando seus ossos, sepultaram-nos debaixo de uma árvore em Jabes, e jejuaram durante sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'E aconteceu depois da morte de Saul, que quando Davi voltou da derrota dos amalequitas, ficou dois dias em Ziclague;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'E ao terceiro dia aconteceu, que veio um do acampamento de Saul, rasgadas suas roupas, e terra sobre sua cabeça: e chegando a Davi, prostrou-se em terra, e fez reverência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'E perguntou-lhe Davi: De onde vens? E ele respondeu: Eu me escapei do acampamento de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'E Davi lhe disse: Que aconteceu? Rogo-te que me digas. E ele respondeu: O povo fugiu da batalha, e também muitos do povo caíram e foram mortos: também Saul e Jônatas seu filho morreram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'E disse Davi àquele rapaz que lhe dava as novas: Como sabes que Saul está morto, e Jônatas seu filho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'E o rapaz que lhe dava as novas respondeu: Casualmente vim ao monte de Gilboa, e achei a Saul que estava recostado sobre sua lança, e vinham atrás dele carros e cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'E quando ele olhou atrás, viu-me e chamou-me; e eu disse: Eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'E ele me disse: Quem és tu? E eu lhe respondi: Sou amalequita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'E ele me voltou a dizer: Eu te rogo que te ponhas sobre mim, e me mates, porque me tomam angústias, e toda minha alma está ainda em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Eu então me pus sobre ele, e matei-o, porque sabia que não podia viver depois de sua queda: e tomei a coroa que tinha em sua cabeça, e o bracelete que trazia em seu braço, e trouxe-os aqui a meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Então Davi agarrando suas roupas, rompeu-os; e o mesmo fizeram os homens que estavam com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'E choraram e lamentaram, e jejuaram até à tarde, por Saul e por Jônatas seu filho, e pelo povo do SENHOR, e pela casa de Israel: porque haviam caído à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'E Davi disse a aquele rapaz que lhe havia trazido as novas: De onde és tu? E ele respondeu: Eu sou filho de um estrangeiro, amalequita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'E disse-lhe Davi: Como não tiveste temor de estender tua mão para matar ao ungido do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Então chamou Davi um dos rapazes, e disse-lhe: Chega, e mata-o. E ele o feriu, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'E Davi lhe disse: Teu sangue seja sobre tua cabeça, pois que tua boca testemunhou contra ti, dizendo: Eu matei ao ungido do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'E lamentou Davi a Saul e a Jônatas seu filho com esta lamentação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '(Disse também que ensinassem ao arco aos filhos de Judá. Eis que está escrito no livro do direito:)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Pereceu a glória de Israel sobre tuas montanhas! Como caíram os valentes!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Não o anuncieis em Gate, Não deis as novas nas praças de Asquelom; Para que não se alegrem as filhas dos filisteus, Para que não saltem de alegria as filhas dos incircuncisos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Montes de Gilboa, nem orvalho nem chuva caia sobre vós, nem sejais terras de ofertas; Porque ali foi rejeitado o escudo dos valentes, O escudo de Saul, como se não houvesse sido ungido com azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Do sangue de mortos, da gordura de valentes, o arco de Jônatas nunca retrocedeu, nem a espada de Saul voltou vazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul e Jônatas, amados e queridos em sua vida, Em sua morte tampouco foram separados: Mais ligeiros que águas, Mais fortes que leões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Filhas de Israel, chorai sobre Saul, Que vos vestia de escarlata em regozijo, Que adornava vossas roupas com ornamentos de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Como caíram os valentes em meio da batalha! Jônatas, morto em tuas alturas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Angústia tenho por ti, irmão meu Jônatas, Que me foste muito doce: Mais maravilhoso me foi o teu amor, Que o amor das mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Como caíram os valentes, E pereceram as armas de guerra!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Depois disto aconteceu que Davi consultou ao SENHOR, dizendo: Subirei a alguma das cidades de Judá? E o SENHOR lhe respondeu: Sobe. E Davi voltou a dizer: Para onde subirei? E ele lhe disse: A Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'E Davi subiu ali, e com ele suas duas mulheres, Ainoã jezreelita e Abigail, a que foi mulher de Nabal do Carmelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'E levou também Davi consigo os homens que com ele haviam estado, cada um com sua família; os quais moraram nas cidades de Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'E vieram os homens de Judá, e ungiram ali a Davi por rei sobre a casa de Judá. E deram aviso a Davi, dizendo: Os de Jabes de Gileade são os que sepultaram a Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'E Davi enviou mensageiros aos de Jabes de Gileade, dizendo-lhes: Benditos sejais vós do SENHOR, que fizestes esta misericórdia com vosso senhor Saul em haver-lhe dado sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Agora, pois, o SENHOR faça convosco misericórdia e verdade; e eu também vos farei bem por isto que fizestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Esforcem-se, pois agora vossas mãos, e sede valentes; pois que morto Saul vosso senhor, os da casa de Judá me ungiram por rei sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Mas Abner filho de Ner, general de exército de Saul, tomou a Is-Bosete filho de Saul, e o fez passar ao acampamento:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'E o constituiu rei sobre Gileade, Assuri, Jezreel, Efraim, Benjamim, e sobre todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'De quarenta anos era Is-Bosete filho de Saul, quando começou a reinar sobre Israel; e reinou dois anos. Só a casa de Judá seguia a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'E foi o número dos dias que Davi reinou em Hebrom sobre a casa de Judá, sete anos e seis meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'E Abner filho de Ner saiu de Maanaim a Gibeão com os servos de Is-Bosete filho de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'E Joabe filho de Zeruia, e os servos de Davi, saíram e encontraram-nos junto ao tanque de Gibeão: e quando se juntaram, pararam-se os uns da uma parte do tanque, e os outros da outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'E disse Abner a Joabe: Levantem-se agora os rapazes, e lutem diante de nós. E Joabe respondeu: Levante-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Então se levantaram, e em número de doze, passaram de Benjamim da parte de Is-Bosete filho de Saul; e doze dos servos de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'E cada um lançou mão da cabeça de seu companheiro, e meteu-lhe sua espada pelo lado, caindo assim de uma vez; pelo que foi chamado aquele lugar, Helcate-Hazurim, o qual está em Gibeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'E houve aquele dia uma batalha muito dura, e Abner e os homens de Israel foram vencidos pelos servos de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'E estavam ali os três filhos de Zeruia: Joabe, e Abisai, e Asael. Este Asael era veloz de pés como um corço do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'O qual Asael seguiu a Abner, indo atrás dele sem desviar-se à direita nem à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'E Abner olhou atrás, e disse: Não és tu Asael? E ele respondeu: Sim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Então Abner lhe disse: Aparta-te à direita ou à esquerda, e agarra-te algum dos rapazes, e toma para ti seus despojos. Porém Asael não quis desviar-se de detrás dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'E Abner voltou a dizer a Asael: Aparta-te de detrás de mim, porque te ferirei derrubando-te em terra, e depois como levantarei meu rosto a teu irmão Joabe?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'E não querendo ele ir-se, feriu-o Abner com a ponta da lança pela quinta costela, e saiu-lhe a lança pelas costas, e caiu ali, e morreu naquele mesmo lugar. E todos os que vinham por aquele lugar, de onde Asael havia caído e estava morto, paravam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Mas Joabe e Abisai seguiram a Abner; e o sol se pôs quando chegaram ao morro de Amá, que está diante de Gia, junto ao caminho do deserto de Gibeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'E juntaram-se os filhos de Benjamim em um esquadrão com Abner, e pararam-se no cume do morro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'E Abner deu vozes a Joabe, dizendo: Consumirá a espada perpetuamente? Não sabes tu que ao fim se segue amargura? Até quando não dirás ao povo que deixem de perseguir a seus irmãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'E Joabe respondeu: Vive Deus que se não houvesses falado, já desde esta manhã o povo haveria deixado de perseguir a seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Então Joabe tocou o chifre, e todo aquele povo se deteve, e não seguiu mais aos de Israel, nem lutou mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'E Abner e os seus caminharam pela campina toda aquela noite, e passando o Jordão cruzaram por todo Bitrom, e chegaram a Maanaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joabe também deixou de perseguir a Abner, e juntando todo aquele povo, faltaram dos servos de Davi dezenove homens, e Asael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Mas os servos de Davi feriram dos de Benjamim e dos de Abner, trezentos e sessenta homens, que morreram. Tomaram logo a Asael, e sepultaram-no no sepulcro de seu pai em Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'E caminharam toda aquela noite Joabe e os seus, e amanheceu-lhes em Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'E houve longa guerra entre a casa de Saul e a casa de Davi; mas Davi se ia fortificando, e a casa de Saul ia diminuindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'E nasceram filhos a Davi em Hebrom: seu primogênito foi Amom, de Ainoã jezreelita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Seu segundo Quileabe, de Abigail a mulher de Nabal, o do Carmelo; o terceiro, Absalão, filho de Maaca, filha de Talmai rei de Gesur:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'O quarto, Adonias filho de Hagite; o quinto, Sefatias filho de Abital;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'O sexto, Itreão, de Eglá mulher de Davi. Estes nasceram a Davi em Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'E quando havia guerra entre a casa de Saul e a de Davi, aconteceu que Abner se esforçava pela casa de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'E havia Saul tido uma concubina que se chamava Rispa, filha de Aiá. E disse Is-Bosete a Abner: Por que te deitaste com a concubina de meu pai?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'E irou-se Abner em grande maneira pelas palavras de Is-Bosete, e disse: Sou eu uma cabeça de cão pertencente a Judá? Eu fiz hoje misericórdia com a casa de Saul teu pai, com seus irmãos, e com seus amigos, e não te entreguei nas mãos de Davi; e tu me acusas de ter pecado acerca desta mulher?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Assim faça Deus a Abner e assim lhe acrescente, se como o SENHOR jurou a Davi eu não fizer assim com ele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Transferindo o reino da casa de Saul, e confirmando o trono de Davi sobre Israel e sobre Judá, desde Dã até Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'E ele não pode responder palavra a Abner, porque lhe temia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'E enviou Abner mensageiros a Davi de sua parte, dizendo: De quem é a terra? E que lhe dissessem: Faze aliança comigo, e eis que minha mão será contigo para virar a ti a todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'E Davi disse: Bem; eu farei contigo aliança: mas uma coisa te peço, e é, que não me venhas a ver sem que primeiro tragas a Mical a filha de Saul, quando vieres a ver-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Depois disto enviou Davi mensageiros a Is-Bosete filho de Saul, dizendo: Restitui-me a minha mulher Mical, a qual eu desposei comigo por cem prepúcios de filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Então Is-Bosete enviou, e tirou-a de seu marido Paltiel, filho de Laís.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'E seu marido foi com ela, seguindo-a e chorando até Baurim. E disse-lhe Abner: Anda, volta-te. Então ele se voltou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'E falou Abner com os anciãos de Israel, dizendo: Ontem e antes procuráveis que Davi fosse rei sobre vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Agora, pois, fazei-o; porque o SENHOR falou a Davi, dizendo: Pela mão de meu servo Davi livrarei a meu povo Israel da mão dos filisteus, e da mão de todos os seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'E falou também Abner aos de Benjamim: e foi também Abner a Hebrom a dizer a Davi todo aquele parecer dos de Israel e de toda a casa de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Veio, pois, Abner a Davi em Hebrom, e com ele vinte homens: e Davi fez banquete a Abner e aos que com ele haviam vindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'E disse Abner a Davi: Eu me levantarei e irei, e juntarei a meu senhor o rei a todo Israel, para que façam contigo aliança, e tu reines como desejas. Davi despediu logo a Abner, e ele se foi em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'E eis que os servos de Davi e Joabe, que vinham do acampamento, e traziam consigo grande presa. Mas Abner não estava com Davi em Hebrom, que já o havia ele despedido, e ele se havia ido em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'E logo que chegou Joabe e todo aquele exército que com ele estava, foi dado aviso a Joabe, dizendo: Abner filho de Ner veio ao rei, e ele lhe despediu, e se foi em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Então Joabe veio ao rei, e disse-lhe: Que fizeste? Eis que Abner veio a ti; por que pois o deixaste que se fosse?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Sabes tu que Abner filho de Ner veio para enganar-te, e para saber tua saída e tua entrada, e por entender tudo o que tu fazes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'E saindo Joabe da presença de Davi, enviou mensageiros atrás de Abner, os quais o fizeram voltar desde o poço de Sirá, sem que Davi soubesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'E quando Abner voltou a Hebrom, apartou-o Joabe ao meio da porta, falando com ele brandamente, e ali lhe feriu pela quinta costela, por causa da morte de Asael seu irmão, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Quando Davi soube depois isto, disse: Limpo estou eu e meu reino, pelo SENHOR, para sempre, do sangue de Abner filho de Ner.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Caia sobre a cabeça de Joabe, e sobre toda a casa de seu pai; que nunca falte da casa de Joabe quem padeça fluxo, nem leproso, nem quem ande com cajado, nem quem morra à espada, nem quem tenha falta de pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Então Joabe e Abisai seu irmão mataram a Abner, porque ele havia matado a Asael, irmão deles na batalha de Gibeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Então disse Davi a Joabe, e a todo aquele povo que com ele estava: Rompei vossas roupas, e cingi-vos de sacos, e fazei luto por causa de Abner. E o rei ia detrás do féretro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'E sepultaram a Abner em Hebrom: e levantando o rei sua voz, chorou junto ao sepulcro de Abner; e chorou também todo aquele povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'E lamentando o rei pelo mesmo Abner, dizia: Morreu Abner como morre um tolo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Tuas mãos não estavam atadas, nem teus pés ligados com grilhões; caíste como os que caem diante de homens maus. E todo aquele povo voltou a chorar por causa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'E quando todo aquele povo veio a dar de comer pão a Davi sendo ainda de dia, Davi jurou, dizendo: Assim me faça Deus e assim me acrescente, se antes que se ponha o sol provar eu pão, ou outra qualquer coisa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Soube-o assim todo aquele povo, e pareceu bem em seus olhos; porque tudo o que o rei fazia parecia bem em olhos de todo aquele povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'E todo aquele povo e todo Israel entenderam aquele dia, que não havia vindo do rei que Abner filho de Ner morresse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'E o rei disse a seus servos: Não sabeis que caiu hoje em Israel um príncipe, e grande?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Que eu agora ainda sou tenro rei ungido; e estes homens, os filhos de Zeruia, muito duros me são; o SENHOR retribua ao que faz o mal conforme sua malícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Logo que o filho de Saul ouviu que Abner havia sido morto em Hebrom, as mãos se lhe desconjuntaram, e todo Israel foi atemorizado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'E o filho de Saul tinha dois homens, os quais eram capitães de tropa, o nome de um era Baaná, e o do outro Recabe, filhos de Rimom beerotita, dos filhos de Benjamim (porque Beerote era contada com Benjamim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'esses beerotitas haviam fugido a Gitaim, e eram peregrinos ali até então).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'E Jônatas, filho de Saul, tinha um filho aleijado dos pés de idade de cinco anos, o qual, quando a notícia da morte de Saul e de Jônatas veio de Jezreel, a sua ama o tomou e fugiu; e quando ela ia fugindo depressa, o menino caiu e ficou aleijado. Seu nome era Mefibosete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Então os filhos de Rimom beerotita, Recabe e Baaná, foram e entraram no maior calor do dia na casa de Is-Bosete, o qual estava dormindo à sesta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Eles entraram no meio da casa como quem vinha buscar trigo, e lhe feriram na quinta costela. E Recabe e seu irmão Baaná escaparam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Pois, quando entraram na casa, estando ele em sua cama em seu quarto, feriram-no de morte, e cortaram-lhe a cabeça, e, havendo-a tomado, caminharam toda a noite pelo caminho da planície.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'E trouxeram a cabeça de Is-Bosete a Davi em Hebrom, e disseram ao rei: Eis aqui a cabeça de Is-Bosete, filho de Saul, teu inimigo, que procurava matar-te; e o SENHOR vingou hoje ao meu senhor, o rei, de Saul e de sua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'E Davi respondeu a Recabe e a seu irmão Baaná, filhos de Rimom beerotita, e disse-lhes: Vive o SENHOR que redimiu minha alma de toda angústia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'que, quando um me deu a notícia, dizendo: Eis que Saul é morto, imaginando que trazia uma boa notícia, eu o detive e o matei em Ziclague, por causa da notícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Quanto mais aos homens maus que mataram a um homem justo em sua casa, e sobre sua cama? Agora, pois, não tenho eu de exigir o seu sangue das vossas mãos, e exterminar-vos da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Então Davi deu ordem aos rapazes, e eles os mataram, e cortaram-lhes as mãos e os pés, e penduraram-nos sobre o tanque, em Hebrom. Depois tomaram a cabeça de Is-Bosete, e enterraram-na no sepulcro de Abner em Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'E vieram todas as tribos de Israel a Davi em Hebrom, e falaram, dizendo: Eis que nós somos teus ossos e tu carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'E ainda ontem e antes, quando Saul reinava sobre nós, tu tiravas e voltavas a Israel. Além disso, o SENHOR te disse: Tu apascentarás a meu povo Israel, e tu serás sobre Israel príncipe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Vieram, pois, todos os anciãos de Israel ao rei em Hebrom, e o rei Davi fez com eles aliança em Hebrom diante do SENHOR; e ungiram a Davi por rei sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Era Davi de trinta anos quando começou a reinar, e reinou quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Em Hebrom reinou sobre Judá sete anos e seis meses: e em Jerusalém reinou trinta e três anos sobre todo Israel e Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Então o rei e os seus foram a Jerusalém aos jebuseus que habitavam na terra; os qual falaram a Davi, dizendo: Tu não entrarás aqui, a não ser que consigas expulsar aos cegos e aos coxos; e pensavam: Davi não entrará aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Porém Davi tomou a fortaleza de Sião, a qual é a cidade de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'E disse Davi aquele dia: Quem chegará até os canais, e ferirá ao jebuseu, e aos coxos e cegos, aos quais a alma de Davi aborrece? Por isto se disse: Cego nem coxo não entrará em casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'E Davi morou na fortaleza e pôs-lhe por nome a Cidade de Davi: e edificou ao redor, desde Milo para dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'E Davi ia crescendo e aumentando-se, e o SENHOR Deus dos exércitos era com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'E Hirão rei de Tiro enviou também embaixadores a Davi, e madeira de cedro, e carpinteiros, e pedreiros para os muros, os quais edificaram a casa de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'E entendeu Davi que o SENHOR lhe havia confirmado por rei sobre Israel, e que havia exaltado seu reino por causa de seu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'E tomou Davi mais concubinas e mulheres de Jerusalém depois que veio de Hebrom, e nasceram-lhe mais filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Estes são os nomes dos que lhe nasceram em Jerusalém: Samua, e Sobabe, e Natã, e Salomão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'E Ibar, e Elisua, e Nefegue,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'E Jafia, e Elisama, e Eliada, e Elifelete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'E ouvindo os filisteus que haviam ungido a Davi por rei sobre Israel, todos os filisteus subiram a buscar a Davi: o qual quando Davi ouviu, veio à fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'E vieram os filisteus, e estenderam-se pelo vale de Refaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Então consultou Davi ao SENHOR, dizendo: Irei contra os filisteus? os entregarás em minhas mãos? E o SENHOR respondeu a Davi: Vai, porque certamente entregarei os filisteus em tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'E veio Davi a Baal-Perazim, e ali os venceu Davi, e disse: O SENHOR rompeu meus inimigos diante de mim, como o romper das águas. E por isto chamou o nome daquele lugar Baal-Perazim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'E deixaram ali seus ídolos, os quais queimou Davi e os seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'E os filisteus voltaram a vir, e estenderam-se no vale de Refaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'E consultando Davi ao SENHOR, ele lhe respondeu: Não subas; mas rodeia-os, e virás a eles por diante das amoreiras:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'E quando ouvires um estrondo que irá pelas copas das amoreiras, então te moverás; porque o SENHOR sairá diante de ti a ferir o acampamento dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'E Davi o fez assim como o SENHOR havia lhe mandado; e feriu aos filisteus desde Gibeá até chegar a Gaza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'E Davi voltou a juntar todos os escolhidos de Israel, trinta mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'E levantou-se Davi, e foi com todo o povo que tinha consigo, de Baal de Judá, para fazer passar dali a arca de Deus, sobre a qual era invocado o nome do SENHOR dos exércitos, que mora nela entre os querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'E puseram a arca de Deus sobre um carro novo, e levaram-na da casa de Abinadabe, que estava em Gibeá: e Uzá e Aiô, filhos de Abinadabe, guiavam o carro novo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'E quando o levavam da casa de Abinadabe que estava em Gibeá, com a arca de Deus, Aiô ia diante da arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'E Davi e toda a casa de Israel dançavam diante do SENHOR com toda sorte de instrumentos de madeira de faia; com harpas, saltérios, adufes, flautas e címbalos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'E quando chegaram à eira de Nacom, Uzá estendeu a mão à arca de Deus, e segurou-a; porque os bois a sacudiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'E o furor do SENHOR se acendeu contra Uzá, e feriu-o ali Deus por aquela imprudência, e caiu ali morto junto à arca de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'E entristeceu-se Davi por o SENHOR ter ferido a Uzá: e foi chamado aquele lugar Perez-Uzá, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'E temendo Davi ao SENHOR aquele dia, disse: Como há de vir a mim a arca do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Não quis, pois, Davi trazer a si a arca do SENHOR à cidade de Davi; mas levou-a Davi à casa de Obede-Edom geteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'E a arca do SENHOR esteve na casa de Obede-Edom geteu três meses: e abençoou o SENHOR a Obede-Edom e a toda sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'E foi dado aviso ao rei Davi, dizendo: o SENHOR abençoou a casa de Obede-Edom, e tudo o que tem, por causa da arca de Deus. Então Davi foi, e trouxe a arca de Deus de casa de Obede-Edom à cidade de Davi com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'E quando os que levavam a arca de Deus haviam andado seis desfiladeiros, sacrificavam um boi e um carneiro gordo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'E Davi saltava com toda sua força diante do SENHOR; e tinha vestido Davi um éfode de linho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Assim Davi e toda a casa de Israel levavam a arca do SENHOR com júbilo e som de trombeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'E quando a arca do SENHOR chegou à cidade de Davi, aconteceu que Mical filha de Saul olhou desde uma janela, e viu ao rei Davi que saltava com toda sua força diante do SENHOR: e menosprezou-lhe em seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Meteram, pois, a arca do SENHOR, e puseram-na em seu lugar em meio de uma tenda que Davi lhe havia estendido: e sacrificou Davi holocaustos e pacíficos diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'E quando Davi acabou de oferecer os holocaustos e pacíficos, abençoou ao povo no nome do SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'E repartiu a todo aquele povo, e a toda a multidão de Israel, tanto a homens como a mulheres, a cada um uma torta de pão, e um pedaço de carne, e um frasco de vinho. E foi-se todo aquele povo, cada um à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Voltou logo Davi para abençoar sua casa: e saindo Mical a receber a Davi, disse: Quão honrado foi hoje o rei de Israel, desnudando-se hoje diante das criadas de seus servos, como se desnudasse um vulgar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Então Davi respondeu a Mical: Diante do SENHOR, que me preferiu a teu pai e a toda sua casa, mandando-me que fosse príncipe sobre o povo do SENHOR, sobre Israel, dançarei diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'E ainda me farei mais vil que esta vez, e serei baixo em meus próprios olhos; e diante das criadas que disseste, diante delas serei honrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'E Mical filha de Saul nunca teve filhos até o dia de sua morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'E aconteceu que, estando já o rei assentado em sua casa, depois que o SENHOR lhe havia dado repouso de todos os seus inimigos em derredor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Disse o rei ao profeta Natã: Olha agora, eu moro em edifícios de cedro, e a arca de Deus está entre cortinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'E Natã disse ao rei: Anda, e faze tudo o que está em teu coração, que o SENHOR é contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'E aconteceu aquela noite, que veio a palavra do SENHOR a Natã, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Vai e dize a meu servo Davi: Assim disse o SENHOR: Tu me edificarás casa em que eu more?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Certamente não habitei em casas desde o dia que tirei aos filhos de Israel do Egito até hoje, mas sim que andei em tenda e em tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'E em tudo quanto andei com todos os filhos de Israel, falei palavra em alguma das tribos de Israel, a quem tenha mandado que apascente meu povo de Israel, para dizer: Por que não me edificastes casa de cedros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Agora, pois, dirás assim a meu servo Davi: Assim disse o SENHOR dos exércitos: Eu te tomei da malhada, de detrás das ovelhas, para que fosses príncipe sobre meu povo, sobre Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'E fui contigo em tudo quanto andaste, e diante de ti exterminei todos teus inimigos, e te fiz nome grande, como o nome dos grandes que são na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Além disso, eu fixarei lugar a meu povo Israel; eu o plantarei, para que habite em seu lugar, e nunca mais seja removido, nem os iníquos lhe aflijam mais, como antes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Desde o dia que pus juízes sobre meu povo Israel; e eu te darei descanso de todos teus inimigos. Também o SENHOR te faz saber, que ele te quer fazer casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'E quando teus dias forem cumpridos, e descansares com teus pais, eu establecerei tua semente depois de ti, a qual procederá de tuas entranhas, e assegurarei seu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Ele edificará casa a meu nome, e eu afirmarei para sempre o trono de seu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Eu serei a ele pai, e ele me será filho. E se ele fizer mal, eu lhe castigarei com vara de homens, e com açoites de filhos de homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Porém não removerei minha misericórdia dele, como a removi de Saul, ao qual tirei de diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'E será firmada tua casa e teu reino para sempre diante de teu rosto; e teu trono será estável eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Conforme todas estas palavras, e conforme toda esta visão, assim falou Natã a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'E entrou o rei Davi, e pôs-se diante do SENHOR, e disse: Senhor DEUS, Quem sou eu, e que é minha casa, para que tu me tragas até aqui?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'E ainda te pareceu pouco isto, Senhor DEUS, pois que também falaste da casa de teu servo no porvir. É esse o modo de agir do homem, Senhor DEUS?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'E que mais pode acrescentar Davi falando contigo? Tu, pois, conheces teu servo, Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Todas estas grandezas operaste por tua palavra e conforme teu coração, fazendo-as saber a teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Portanto tu te engrandeceste, SENHOR Deus: porquanto não há como tu, nem há Deus além de ti, conforme tudo o que ouvimos com nossos ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'E quem como teu povo, como Israel, na terra? Uma gente por causa da qual Deus fosse a resgatá-la por povo, e lhe pusesse nome, e fizesse por vós, ó Israel, grandes e espantosas obras em tua terra, por causa de teu povo, ó Deus, que tu resgataste do Egito, das nações e de seus deuses?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Porque tu confirmaste a ti teu povo Israel por povo teu para sempre: e tu, ó SENHOR, foste a eles por Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Agora, pois, SENHOR Deus, a palavra que falaste sobre teu servo e sobre sua casa, desperta-a para sempre, e faze conforme o que disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Que seja engrandecido teu nome para sempre, e diga-se: o SENHOR dos exércitos é Deus sobre Israel; e que a casa de teu servo Davi seja firme diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Porque tu, SENHOR dos exércitos, Deus de Israel, revelaste ao ouvido de teu servo, dizendo: Eu te edificarei casa. Por isto teu servo achou em seu coração para fazer diante de ti esta súplica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Agora, pois, SENHOR Deus, tu és Deus, e tuas palavras serão firmes, já que disseste a teu servo este bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Agrada-te, pois, de abençoar a casa de teu servo, para que perpetuamente permaneça diante de ti: pois que tu, SENHOR Deus, o disseste, e com tua bênção será bendita a casa de teu servo para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Depois disto aconteceu, que Davi feriu aos filisteus, e os humilhou: e tomou Davi a Metegue-Ama da mão dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Feriu também aos de Moabe, e mediu-os com cordel, fazendo-os lançar por terra; e mediu com dois cordéis para morte, e um cordel inteiro para vida; e foram os moabitas servos debaixo de tributo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Também feriu Davi a Hadadezer filho de Reobe, rei de Zobá, indo ele a estender seu termo até o rio de Eufrates.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'E tomou Davi deles mil e setecentos cavaleiros, e vinte mil homens a pé; e aleijou Davi os cavalos de todos os carros, exceto cem carros deles que deixou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'E vieram os sírios de Damasco a dar ajuda a Hadadezer rei de Zobá; e Davi feriu dos sírios vinte e dois mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Pôs logo Davi guarnição em Síria a de Damasco, e foram os sírios servos de Davi sujeitos a tributo. E o SENHOR guardou a Davi de onde quer que fosse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'E tomou Davi os escudos de ouro que traziam os servos de Hadadezer, e levou-os a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Também de Betá e de Beerote, cidades de Hadadezer, tomou o rei Davi grande quantidade de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Então ouvindo Toí, rei de Hamate, que Davi havia ferido todo aquele exército de Hadadezer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Enviou Toí a Jorão seu filho ao rei Davi, a saudar-lhe pacificamente e a bendizer-lhe, porque havia lutado com Hadadezer e o havia vencido: porque Toí era inimigo de Hadadezer. E Jorão levava em sua mão vasos de prata, e vasos de ouro, e de bronze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Os quais o rei Davi dedicou ao SENHOR, com a prata e o ouro que tinha dedicado de todas as nações que havia submetido:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Dos sírios, dos moabitas, dos amonitas, dos filisteus, dos amalequitas, e do despojo de Hadadezer filho de Reobe, rei de Zobá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'E ganhou Davi fama quando, voltando da derrota dos sírios, feriu dezoito mil homens no vale do sal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'E pôs guarnição em Edom, por toda Edom pôs guarnição; e todos os edomitas foram servos de Davi. E o SENHOR guardou a Davi por de onde quer que fosse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'E reinou Davi sobre todo Israel; e fazia Davi direito e justiça a todo seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'E Joabe filho de Zeruia era general de seu exército; e Josafá filho de Ailude, chanceler;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'E Zadoque filho de Aitube, e Aimeleque filho de Abiatar, eram sacerdotes; e Seraías era escriba;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'E Benaia filho de Joiada, era sobre os quereteus e peleteus; e os filhos de Davi eram os príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'E disse Davi: Restou algum da casa de Saul, a quem faça eu misericórdia por causa de Jônatas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'E havia um servo da casa de Saul, que se chamava Ziba, ao qual quando chamaram que viesse a Davi, o rei lhe disse: És tu Ziba? E ele respondeu: Teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'E o rei disse: Não restou ninguém da casa de Saul, a quem faça eu misericórdia de Deus? E Ziba respondeu ao rei: Ainda restou um filho de Jônatas, aleijado dos pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Então o rei lhe disse: E esse onde está? E Ziba respondeu ao rei: Eis que, está em casa de Maquir filho de Amiel, em Lo-Debar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'E enviou o rei Davi, e tomou-o de casa de Maquir filho de Amiel, de Lo-Debar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'E vindo Mefibosete, filho de Jônatas filho de Saul, a Davi, prostrou-se sobre seu rosto, e fez reverência. E disse Davi: Mefibosete. E ele respondeu: Eis aqui teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'E disse-lhe Davi: Não tenhas temor, porque eu à verdade farei contigo misericórdia por causa de Jônatas teu pai, e te devolverei todas as terras de Saul teu pai; e tu comerás sempre pão à minha mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'E ele inclinando-se, disse: Quem é teu servo, para que olhes a um cão morto como eu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Então o rei chamou a Ziba, servo de Saul, e disse-lhe: Tudo o que foi de Saul e de toda sua casa, eu o dei ao filho de teu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Tu pois lhe lavrarás as terras, tu com teus filhos, e teus servos, e colherás os frutos, para que o filho de teu senhor tenha com que se manter; mas Mefibosete, o filho de teu senhor comerá sempre pão à minha mesa. E Ziba tinha quinze filhos e vinte servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'E respondeu Ziba ao rei: Conforme tudo o que mandou meu senhor o rei a seu servo, assim teu servo o fará. Mefibosete, disse o rei, comerá à minha mesa, como um dos filhos do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'E tinha Mefibosete um filho pequeno, que se chamava Mica. E toda a família da casa de Ziba eram servos de Mefibosete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'E morava Mefibosete em Jerusalém, porque comia sempre à mesa do rei; e era coxo de ambos os pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Depois disto aconteceu, que morreu o rei dos filhos de Amom: e reinou em lugar seu Hanum seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'E disse Davi: Eu farei misericórdia com Hanum filho de Naás, como seu pai a fez comigo. E enviou Davi seus servos a consolá-lo por seu pai. Mas chegados os servos de Davi à terra dos filhos de Amom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Os príncipes dos filhos de Amom disseram a Hanum seu senhor: Parece-te que para Davi honrar a teu pai te enviou consoladores? Não enviou Davi seus servos a ti por reconhecer e inspecionar a cidade, para destruí-la?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Então Hanum tomou os servos de Davi, e rapou-lhes a metade da barba, e cortou-lhes as roupas pela metade até as nádegas, e despachou-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'O qual quando foi feito saber a Davi, enviou a encontrar-lhes, porque eles estavam em extremo envergonhados; e o rei fez dizer lhes: Ficai-vos em Jericó até que vos volte a nascer a barba, e então regressareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'E vendo os filhos de Amom que se fizeram odiosos a Davi, enviaram os filhos de Amom e alugaram aos sírios da casa de Reobe, e aos sírios de Zobá, vinte mil homens a pé: e do rei de Maaca mil homens, e de Tobe doze mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'O qual quando ouviu Davi, enviou a Joabe com todo o exército dos valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'E saindo os filhos de Amom, ordenaram seus esquadrões à entrada da porta: mas os sírios de Zobá, e de Reobe, e de Tobe, e de Maaca, estavam à parte no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Vendo, pois, Joabe que havia esquadrões diante e detrás dele, escolheu de todos os escolhidos de Israel, e pôs-se em ordem contra os sírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Entregou logo o que restou do povo em mão de Abisai seu irmão, e o pôs em ordem para encontrar aos amonitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'E disse: Se os sírios me forem superiores, tu me ajudarás; e se os filhos de Amom puderem mais que tu, eu te darei ajuda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Esforça-te, e esforcemo-nos por nosso povo, e pelas cidades de nosso Deus: e faça o SENHOR o que bem lhe parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'E aproximou-se Joabe, e o povo que com ele estava, para lutar com os sírios; mas eles fugiram diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Então os filhos de Amom, vendo que os sírios haviam fugido, fugiram também eles diante de Abisai, e entraram-se na cidade. E voltou Joabe dos filhos de Amom, e veio a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Mas vendo os sírios que haviam caído diante de Israel, voltaram a se juntar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'E enviou Hadadezer, e tirou os sírios que estavam da outra parte do rio, os quais vieram a Helã, levando por chefe a Sobaque general do exército de Hadadezer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'E quando foi dado aviso a Davi, juntou a todo Israel, e passando o Jordão veio a Helã: e os sírios se puseram em ordem contra Davi, e lutaram com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Mas os sírios fugiram diante de Israel: e feriu Davi dos sírios a gente de setecentos carros, e quarenta mil cavaleiros: feriu também a Sobaque general do exército, e morreu ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Vendo, pois todos os reis que assistiam a Hadadezer, como haviam eles sido derrotados diante de Israel, fizeram paz com Israel, e serviram-no; e dali adiante temeram os sírios de socorrer aos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'E aconteceu à volta de um ano, no tempo que saem os reis à guerra, que Davi enviou a Joabe, e a seus servos com ele, e a todo Israel; e destruíram aos amonitas, e puseram cerco a Rabá: mas Davi se ficou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'E aconteceu que levantando-se Davi de sua cama à hora da tarde, passeava-se pelo terraço da casa real, quando viu desde o terraço uma mulher que se estava lavando, a qual era muito bela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'E enviou Davi a preguntar por aquela mulher, e disseram-lhe: Aquela é Bate-Seba filha de Eliã, mulher de Urias Heteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'E Davi enviou mensageiros, e tomou-a: e assim que entrou a ele, ele dormiu com ela. Purificou-se logo ela de sua imundícia, e se voltou à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'E concebeu a mulher, e enviou-o a fazer saber a Davi, dizendo: Eu estou grávida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Então Davi enviou a dizer a Joabe: Envia-me a Urias Heteu. E enviou-o Joabe a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'E quando Urias veio a ele, perguntou-lhe Davi pela saúde de Joabe, e pela saúde do povo, e também da guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Depois disse Davi a Urias: Desce à tua casa, e lava teus pés. E saindo Urias de casa do rei, veio atrás dele um presente real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Mas Urias dormiu à porta da casa do rei com todos os servos de seu senhor, e não desceu à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'E fizeram saber isto a Davi, dizendo: Urias não desceu à sua casa. E disse Davi a Urias: Não vieste de caminho? Por que, pois, não desceste à tua casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'E Urias respondeu a Davi: A arca, e Israel e Judá, estão debaixo de tendas; e meu senhor Joabe, e os servos de meu senhor sobre a face do campo: e havia eu de entrar em minha casa para comer e beber, e a dormir com minha mulher? Por vida tua, e pela vida de tua alma, que eu não farei tal coisa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'E Davi disse a Urias: Fica-te aqui ainda hoje, e amanhã te despedirei. E ficou Urias em Jerusalém aquele dia e o seguinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'E Davi o convidou, e fez-lhe comer e beber diante de si, até embriagá-lo. E ele saiu à tarde para dormir em sua cama com os servos de seu senhor; mas não desceu à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Vinda a manhã, escreveu Davi a Joabe uma carta, a qual enviou por mão de Urias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'E escreveu na carta, dizendo: Ponde a Urias diante da força da batalha, e desamparai-o, para que seja ferido e morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Assim foi que quando Joabe cercou a cidade, pôs a Urias no lugar de onde sabia que estavam os homens mais valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'E saindo logo os da cidade, lutaram com Joabe, e caíram alguns do povo dos servos de Davi; e morreu também Urias Heteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Então enviou Joabe, e fez saber a Davi todos os negócios da guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'E mandou ao mensageiro, dizendo: Quando acabares de contar ao rei todos os negócios da guerra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Se o rei começar a irar-se, e te disser: Por que vos aproximastes à cidade lutando? Não sabíeis que eles costumam atirar do muro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Quem feriu a Abimeleque filho de Jerubusete? Não lançou uma mulher do muro um pedaço de uma roda de moinho, e morreu em Tebes? Por que vos aproximastes ao muro? Então tu lhe dirás: Também teu servo Urias Heteu é morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'E foi o mensageiro, e chegando, contou a Davi todas as coisas a que Joabe lhe havia enviado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'E disse o mensageiro a Davi: Prevaleceram contra nós os homens, que saíram a nós ao campo, bem que nós lhes fizemos retroceder até a entrada da porta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Porém os flecheiros atiraram contra teus servos desde o muro, e morreram alguns dos servos do rei; e morreu também teu servo Urias Heteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'E Davi disse ao mensageiro: Dirás assim a Joabe: Não tenhas pesar disto, que de igual e semelhante maneira costuma consumir a espada: esforça a batalha contra a cidade, até que a rendas. E tu conforta-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'E ouvindo a mulher de Urias que seu marido Urias era morto, fez luto por seu marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'E passado o luto, enviou Davi e recolheu-a à sua casa: e foi ela sua mulher, e deu-lhe à luz um filho. Mas isto que Davi havia feito, foi desagradável aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'E o SENHOR enviou Natã a Davi, o qual vindo a ele, disse-lhe: Havia dois homens em uma cidade, um rico, e o outro pobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'O rico tinha numerosas ovelhas e vacas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Mas o pobre não tinha mais que uma só cordeira, que ele havia comprado e criado, e que havia crescido com ele e com seus filhos juntamente, comendo de seu bocado, e bebendo de seu vaso, e dormindo em seu fundo: e tinha-a como de uma vez filha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'E veio um de caminho ao homem rico; e ele não quis tomar de suas ovelhas e de suas vacas, para guisar ao caminhante que lhe havia vindo, mas sim que tomou a ovelha daquele homem pobre, e preparou-a para aquele que lhe havia vindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Então se acendeu o furor de Davi em grande maneira contra aquele homem, e disse a Natã: Vive o SENHOR, que o que tal fez é digno de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'E que ele deve pagar a cordeira com quatro tantos, porque fez esta tal coisa, e não teve misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Então disse Natã a Davi: Tu és aquele homem. Assim disse o SENHOR, Deus de Israel: Eu te ungi por rei sobre Israel, e te livre da mão de Saul;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Eu te dei a casa de teu senhor, e as mulheres de teu senhor em teu fundo: demais disto te dei a casa de Israel e de Judá; e se isto é pouco, eu te acrescentarei tais e tais coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Por que, pois, tiveste em pouco a palavra do SENHOR, fazendo o que era mau diante de seus olhos? A Urias Heteu feriste à espada, e tomaste por tua mulher a sua mulher, e a ele mataste com a espada dos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Pelo qual agora não se apartará jamais de tua casa a espada; porquanto me menosprezaste, e tomaste a mulher de Urias Heteu para que fosse tua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Assim disse o SENHOR: Eis que eu levantarei sobre ti o mal de tua mesma casa, e tomarei tuas mulheres diante de teus olhos, e as darei a teu próximo, o qual se deitará com tuas mulheres à vista deste sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Porque tu o fizeste em secreto; mas eu farei isto diante de todo Israel, e diante do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Então disse Davi a Natã: Pequei contra o SENHOR. E Natã disse a Davi: Também o SENHOR removeu teu pecado: não morrerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Mas porquanto com este negócio fizeste blasfemar aos inimigos do SENHOR, o filho que te nasceu morrerá certamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'E Natã se voltou à sua casa. E o SENHOR feriu ao menino que a mulher de Urias havia dado à luz a Davi, e o fez ficar gravemente doente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Então rogou Davi a Deus pelo menino; e jejuou Davi, recolheu-se, e passou a noite deitado em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'E levantando-se os anciãos de sua casa foram a ele para fazê-lo levantar da terra; mas ele não quis, nem comeu com eles pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'E ao sétimo dia morreu o menino; mas seus servos não ousavam fazer-lhe saber que o menino era morto, dizendo entre si: Quando o menino ainda vivia, lhe falávamos, e não queria ouvir nossa voz: pois quanto mais mal lhe fará, se lhe dissermos que o menino está morto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Mas Davi vendo a seus servos falar entre si, entendeu que o menino era morto; pelo que disse Davi a seus servos: É morto o menino? E eles responderam: Morto é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Então Davi se levantou da terra, e lavou-se e ungiu-se, e mudou suas roupas, e entrou à casa do SENHOR, e adorou. E depois veio à sua casa, e mandou, e puseram-lhe pão, e comeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'E disseram-lhe seus servos: Que é isto que fizeste? Pelo menino, vivendo ainda, jejuavas e choravas; e ele morto, levantaste-te e comeste pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'E ele respondeu: Vivendo ainda o menino, eu jejuava e chorava, dizendo: Quem sabe se Deus terá compaixão de mim, por maneira que viva o menino?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mas agora que já é morto, para que tenho de jejuar? Poderei eu fazer-lhe voltar? Eu vou a ele, mas ele não voltará a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'E consolou Davi a Bate-Seba sua mulher, e entrando a ela, dormiu com ela; e deu à luz um filho, e chamou seu nome Salomão, ao qual o SENHOR amou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Que enviou por meio de Natã profeta, e chamou seu nome Jedidias, por causa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'E Joabe lutava contra Rabá dos filhos de Amom, e tomou a cidade real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Então enviou Joabe mensageiros a Davi, dizendo: Eu lutei contra Rabá, e tomei a cidade das águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Junta, pois, agora o povo que resta, e assenta acampamento contra a cidade, e toma-a; porque tomando eu a cidade, não se chame de meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'E juntando Davi todo aquele povo foi contra Rabá, e combateu-a, e tomou-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'E tomou a coroa de seu rei de sua cabeça, a qual pesava um talento de ouro, e tinha pedras preciosas; e foi posta sobre a cabeça de Davi. E trouxe muito grande despojo da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Tirou também o povo que estava nela, e o pôs ao trabalho de serras, e de trilhos de ferro, e de machados de ferro; e os fez passar por fornos de tijolos: e o mesmo fez a todas as cidades dos filhos de Amom. Voltou-se logo Davi com todo o povo a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Aconteceu depois disto, que tendo Absalão filho de Davi uma irmã bela que se chamava Tamar, apaixonou-se por ela Amnom filho de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'E estava Amnom angustiado até enfermar, por Tamar sua irmã: porque por ser ela virgem, parecia a Amnom que seria coisa difícil fazer-lhe algo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'E Amnom tinha um amigo que se chamava Jonadabe, filho de Simeia, irmão de Davi: e era Jonadabe homem muito astuto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'E este lhe disse: Filho do rei, por que de dia em dia vais assim enfraquecendo? Não o revelarás a mim? Amnom lhe respondeu: Eu amo a Tamar a irmã de Absalão meu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'E Jonadabe lhe disse: Deita-te em tua cama, e finge que estás enfermo; e quando teu pai vier a visitar-te, dize-lhe: Rogo-te que venha minha irmã Tamar, para que me conforte com alguma comida, e prepare diante de mim alguma iguaria, para que vendo eu, a coma de sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Deitou-se, pois, Amnom, e fingiu que estava enfermo, e veio o rei: a visitar-lhe: e disse Amnom ao rei: Eu te rogo que venha minha irmã Tamar, e faça diante de mim dois bolos, que coma eu de sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'E Davi enviou a Tamar a sua casa, dizendo: Vai agora à casa de teu irmão Amnom, e faze-lhe de comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'E foi Tamar à casa de seu irmão Amnom, o qual estava deitado; e tomou farinha, e amassou e fez bolos diante dele, e preparou-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Tomou logo a panela, e tirou-os diante dele: mas ele não quis comer. E disse Amnom: Lançai fora daqui a todos. E todos se saíram dali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Então Amnom disse a Tamar: Traze a comida ao quarto, para que eu coma de tua mão. E tomando Tamar os pães que havia preparado, levou-os a seu irmão Amnom ao quarto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'E quando ela se as pôs diante para que comesse, ele a agarrou, dizendo-lhe: Vem, irmã minha deita-te comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Ela então lhe respondeu: Não, meu irmão, não me forces; porque não se deve assim com Israel. Não faças tal erro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Porque onde iria eu com minha desonra? E ainda tu serias estimado como um dos perversos em Israel. Rogo-te, pois, agora, que fales ao rei, que não me negará a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Mas ele não a quis ouvir; antes podendo mais que ela a forçou, e lançou-se com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Aborreceu-a logo Amnom de tão grande aborrecimiento, que o ódio com que a aborreceu foi maior que o amor com que a havia amado. E disse-lhe Amnom: Levanta-te e vai-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'E ela lhe respondeu: Não está certo; maior mal é este de me rejeitar, que o que me fizeste. Mas ele não a quis ouvir:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Antes, chamando seu criado que lhe servia, disse: Lança-me esta ali fora, e fecha a porta atrás dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'E tinha ela sobre si uma roupa de cores, traje que as filhas virgens dos reis vestiam. Lançou-a, pois, fora seu criado, e fechou a porta atrás ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Então Tamar tomou cinza, e espalhou-a sobre sua cabeça, e rasgou sua roupa de cores de que estava vestida, e postas suas mãos sobre sua cabeça, foi-se gritando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'E disse-lhe seu irmão Absalão: Esteve contigo teu irmão Amnom? Pois cala agora, irmã minha: teu irmão é; não ponhas teu coração neste negócio. E ficou Tamar desconsolada em casa de Absalão seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'E logo que o rei Davi ouviu tudo isto, foi muito irritado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Mas Absalão não falou com Amnom nem mal nem bem, ainda que Absalão aborrecesse a Amnom, porque havia forçado a Tamar sua irmã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'E aconteceu, passados dois anos, que Absalão tinha tosquiadores em Baal-Hazor, que está junto a Efraim; e convidou Absalão a todos os filhos do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'E veio Absalão ao rei, e disse-lhe: Eis que, teu servo tem agora tosquiadores: eu rogo que venha o rei e seus servos com teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'E respondeu o rei a Absalão: Não, filho meu, não vamos todos, para não sermos pesados a ti. E ainda que tenha insistido com ele, não quis ir, mas abençoou-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Então disse Absalão: Se não, rogo-te que venha conosco Amnom meu irmão. E o rei lhe respondeu: Para que há de ir contigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'E como Absalão o importunou, deixou ir com ele a Amnom e a todos os filhos do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'E havia Absalão dado ordem a seus criados, dizendo: Agora bem, olhai quando o coração de Amnom estará alegre do vinho, e em dizendo-vos eu: Feri a Amnom, então matai-o, e não temais; que eu vos o mandei. Esforçai-vos, pois, e sede valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'E os criados de Absalão fizeram com Amnom como Absalão o havia mandado. Levantaram-se logo todos os filhos do rei, e subiram todos em seus mulos, e fugiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'E estando ainda eles no caminho, chegou a Davi o rumor que dizia: Absalão matou a todos os filhos do rei, que nenhum deles restou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Então levantando-se Davi, rasgou suas roupas, e lançou-se em terra, e todos os seus criados, rasgados suas roupas, estavam adiante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'E Jonadabe, filho de Simeia irmão de Davi, falou e disse: Não diga meu senhor que mataram a todos os jovens filhos do rei, que somente Amnom é morto: porque em boca de Absalão estava posto desde o dia que Amnom forçou a Tamar sua irmã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Portanto, agora não ponha meu senhor o rei em seu coração essa voz que disse: Todos os filhos do rei foram mortos: porque somente Amnom é morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absalão fugiu logo. Entretanto, levantando seus olhos o jovem que estava de vigia olhou, e eis que muito povo vinha por detrás de si pelo caminho da lateral do monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'E disse Jonadabe ao rei: Eis ali os filhos do rei que vem: é assim como teu servo disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'E quando ele acabou de falar, eis que os filhos do rei que vieram, e levantando sua voz choraram. E também o mesmo rei e todos os seus servos choraram com muito grandes lamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Mas Absalão fugiu, e foi-se a Talmai filho de Amiur, rei de Gesur. E Davi chorava por seu filho todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'E depois que Absalão fugiu e se foi a Gesur, esteve ali três anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'E o rei Davi desejou ver a Absalão: porque já estava consolado acerca de Amnom que era morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'E conhecendo Joabe, filho de Zeruia, que o coração do rei estava por Absalão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Enviou Joabe a Tecoa, e tomou dali uma mulher astuta, e disse-lhe: Eu te rogo que te enlutes, e te vistas de roupas de luto, e não te unjas com óleo, antes sê como mulher que há muito tempo que traze luto por algum morto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'E entrando ao rei, fala com ele desta maneira. E pôs Joabe as palavras em sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Entrou, pois, aquela mulher de Tecoa ao rei, e prostrando-se em terra sobre seu rosto fez reverência, e disse: Ó rei, socorre-me!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'E o rei disse: Que tens? E ela respondeu: Eu à verdade sou uma mulher viúva e meu marido é morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'E tua serva tinha dois filhos e os dois brigaram no campo; e não havendo quem os separasse, feriu o um à outra, e o matou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'E eis que toda a parentela se levantou contra tua serva, dizendo: Entrega ao que matou a seu irmão, para que lhe façamos morrer pela vida de seu irmão a quem ele matou, e tiremos também o herdeiro. Assim apagarão a brasa que me restou, não deixaram a meu marido nome nem remanescente sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Então o rei disse à mulher: Vai-te à tua casa, que eu mandarei acerca de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'E a mulher de Tecoa disse ao rei: Rei senhor meu, a maldade seja sobre mim e sobre a casa de meu pai; mas o rei e seu trono sem culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'E o rei disse: Ao que falar contra ti, traze-o a mim, que não te tocará mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Disse ela então: Rogo-te, ó rei, que te lembres do SENHOR teu Deus, que não deixes ao vingador do sangue aumentar o dano em destruir meu filho. E ele respondeu: Vive o SENHOR, que não cairá nem um cabelo da cabeça de teu filho em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'E a mulher disse: Rogo-te que fale tua criada uma palavra a meu senhor o rei. E ele disse: Fala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Então a mulher disse: Por que pois pensas tu outro tanto contra o povo de Deus? que falando o rei esta palavra, é como culpado, porquanto o rei não faz voltar a seu fugitivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Porque de certo morremos, e somos como águas derramadas por terra, que não podem voltar a recolher-se: nem Deus tira a vida, mas sim planeja meio para que seu desviado não seja dele excluído.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'E que eu vim agora para dizer isto ao rei meu senhor, é porque o povo me pôs medo. Mas tua serva disse: Falarei agora ao rei: talvez ele faça o que sua serva diga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Pois o rei ouvirá, para livrar à sua serva da mão do homem que me quer exterminar a mim, e a meu filho juntamente, da propriedade de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Tua serva, pois, disse: Que seja agora a resposta de meu senhor o rei para descanso; pois que meu senhor o rei é como um anjo de Deus para escutar o bem e o mal. Assim o SENHOR teu Deus seja contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Então ele respondeu, e disse à mulher: Eu te rogo que não me encubras nada do que eu te perguntar. E a mulher disse: Fale meu senhor o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'E o rei disse: Não foi a mão de Joabe contigo em todas estas coisas? E a mulher respondeu e disse: Vive tua alma, rei senhor meu, que não há que desviar-se à direita nem à esquerda de tudo o que meu senhor o rei falou: porque teu servo Joabe, ele me mandou, e ele pôs na boca de tua serva todas estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'E Joabe, teu servo o fez, modificando a aparência do assunto; mas meu senhor é sábio, conforme a sabedoria de um anjo de Deus, para conhecer o que há na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Então o rei disse a Joabe: Eis que eu faço isto: vai, e faze voltar ao jovem Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'E Joabe se prostrou em terra sobre seu rosto, e fez reverência, e depois que abençoou ao rei, disse: Hoje há entendido teu servo que achei favor em teus olhos, rei senhor meu; pois que fez o rei o que seu servo disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Levantou-se logo Joabe, e foi a Gesur, e voltou a Absalão a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Mas o rei disse: Vá-se à sua casa, e não veja meu rosto. E voltou-se Absalão à sua casa, e não viu o rosto do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'E não havia em todo Israel homem tão elogiado por sua beleza como Absalão; desde a planta de seu pé até ao topo da cabeça não havia nele defeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'E quando se cortava o cabelo, (o qual fazia ao fim de cada ano, pois lhe incomodava, e por isso se o cortava,) pesava o cabelo de sua cabeça duzentos siclos de peso real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'E nasceram-lhe a Absalão três filhos, e uma filha que se chamou Tamar, a qual era bela de ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'E esteve Absalão por espaço de dois anos em Jerusalém, e não viu a cara do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'E mandou Absalão por Joabe, para enviá-lo ao rei; mas não quis vir a ele; ele mandou mensagem ainda pela segunda vez, mas não quis vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Então disse a seus servos: Bem sabeis as terras de Joabe junto a meu lugar, de onde tem suas cevadas; ide, e pegai-lhes fogo; e os servos de Absalão pegaram fogo às terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Levantou-se, portanto, Joabe, e veio a Absalão à sua casa, e disse-lhe: Por que puseram fogo teus servos a minhas terras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'E Absalão respondeu a Joabe: Eis que, eu enviei por ti, dizendo que viesses aqui, a fim de enviar-te eu ao rei a que lhe dissesses: Para que vim de Gesur? Melhor me fora estar ainda lá. Veja eu agora a cara do rei; e se há em mim pecado, mate-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Veio, pois, Joabe ao rei, e fê-lo saber. Então chamou a Absalão, o qual veio ao rei, e inclinou seu rosto em terra diante do rei: e o rei beijou a Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Aconteceu depois disto, que Absalão se fez de carros e cavalos, e cinquenta que corressem diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'E levantava-se Absalão de manhã, e punha-se a um lado do caminho da porta; e a qualquer um que tinha pleito e vinha ao rei a juízo, Absalão lhe chamava a si, e dizia-lhe: De que cidade és? E ele respondia: Teu servo é de uma das tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Então Absalão lhe dizia: Olha que tuas palavras são boas e justas: mas não tens quem te ouça pelo rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'E dizia Absalão: Quem me dera se eu fosse constituído juiz na terra, para que viessem a mim todos os que têm pleito ou negócio, que eu lhes faria justiça!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'E acontecia que, quando alguém se chegava para inclinar-se a ele, ele estendia sua mão, e o tomava, e o beijava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'E desta maneira fazia com todo Israel que vinha ao rei a juízo: e assim roubava Absalão o coração dos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'E ao fim de quarenta anos aconteceu que Absalão disse ao rei: Eu te rogo me permitas que vá a Hebrom, a pagar meu voto que ei prometido ao SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Porque teu servo fez voto quando estava em Gesur em Síria, dizendo: Se o SENHOR me voltar a Jerusalém, eu servirei ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'E o rei disse: Vai em paz. E ele se levantou, e se foi a Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Porém enviou Absalão espias por todas as tribos de Israel, dizendo: Quando ouvirdes o som da trombeta, direis: Absalão reina em Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'E foram com Absalão duzentos homens de Jerusalém por ele convidados, os quais iam em sua ingenuidade, sem saber nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Também enviou Absalão por Aitofel gilonita, do conselho de Davi, a Gilo sua cidade, enquanto fazia seus sacrifícios. E a conspiração veio a ser grande, pois se ia aumentando o povo com Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'E veio o aviso a Davi, dizendo: O coração de todo Israel segue Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Então Davi disse a todos os seus servos que estavam com ele em Jerusalém: Levantai-vos, e fujamos, porque não poderemos escapar diante de Absalão; apressai-vos a partir, não seja que se apressando ele nos alcance, e lance o mal sobre nós, e fira a cidade a fio de espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'E os servos do rei disseram ao rei: Eis que, teus servos estão prontos a tudo que nosso senhor, o rei, decidir fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'O rei então saiu, com toda sua família depois dele. E deixou o rei dez mulheres concubinas para que guardassem a casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Saiu pois o rei com todo o povo que lhe seguia, e pararam-se em um lugar distante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'E todos os seus servos passavam a seu lado, com todos os quereteus e peleteus; e todos os giteus, seiscentos homens que haviam vindo a pé desde Gate, iam diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'E disse o rei a Itai giteu: Para que vens tu também conosco? Volta, e fica com o rei; porque tu és estrangeiro, e desterrado também de teu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Ontem vieste, e tenho-te de fazer hoje que mudes lugar para ir conosco? Eu vou como vou: tu volta, e faze voltar a teus irmãos: em ti haja misericórdia e verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'E respondeu Itai ao rei, dizendo: Vive Deus, e vive meu senhor o rei, que, ou para morte ou para vida, de onde meu senhor o rei estiver, ali estará também teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Então Davi disse a Itai: Vem, pois, e passa. E passou Itai giteu, e todos os seus homens, e toda sua família.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'E toda aquela terra chorou em alta voz; passou, logo, toda a gente o ribeiro de Cedrom; também passou o rei, e todo aquele povo passou, ao caminho que vai ao deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'E eis que, também ia Zadoque, e com ele todos os levitas que levavam a arca do pacto de Deus; e assentaram a arca do pacto de Deus. E subiu Abiatar depois que acabou de sair da cidade todo aquele povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Porém disse o rei a Zadoque: Volta a arca de Deus à cidade; que se eu achar favor aos olhos do SENHOR, ele me voltará, e me fará ver a ela e a seu tabernáculo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'E se disser: Não me agradas: aqui estou, faça de mim o que bem lhe parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Disse ainda o rei a Zadoque sacerdote: Não és tu vidente? Volta-te em paz à cidade; e convosco vossos dois filhos, teu filho Aimaás, e Jônatas filho de Abiatar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Olhai que eu me deterei nos campos do deserto, até que venha resposta de vós que me dê aviso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Então Zadoque e Abiatar trouxeram de volta a arca de Deus a Jerusalém; e estiveram ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'E Davi subiu o monte das Oliveiras; e subiu chorando, levando a cabeça coberta, e os pés descalços. Também todo aquele povo que tinha consigo cobriu cada um sua cabeça, e subiram chorando assim como subiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'E deram aviso a Davi, dizendo: Aitofel está entre os que conspiraram com Absalão. Então disse Davi: Torna loucura agora, ó SENHOR, o conselho de Aitofel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'E quando Davi chegou ao cume do monte para adorar ali a Deus, eis que Husai arquita que lhe saiu ao encontro, trazendo rasgada sua roupa, e terra sobre sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'E disse-lhe Davi: Se passares comigo, tu me serás prejudicial;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Mas se voltares à cidade, e disseres a Absalão: Rei, eu serei teu servo; como até aqui fui servo de teu pai, assim serei agora servo teu, então tu me dissiparás o conselho de Aitofel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Não estarão ali contigo Zadoque e Abiatar sacerdotes? Portanto, tudo o que ouvires na casa do rei, darás aviso disso a Zadoque e a Abiatar sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'E eis que estão com eles seus dois filhos, Aimaás o de Zadoque, e Jônatas o de Abiatar; por meio deles me enviareis aviso de tudo o que ouvirdes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Assim se veio Husai amigo de Davi à cidade; e Absalão entrou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'E quando Davi passou um pouco do cume do monte, eis que Ziba, o criado de Mefibosete, que o saía a receber com um par de asnos aprontados, e sobre eles duzentos pães, e cem cachos de passas, e cem pães de figos secos, e um odre de vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'E disse o rei a Ziba: Que é isto? E Ziba respondeu: Os asnos são para a família do rei, em que s; os pães e a passa para os criados, que comam; e o vinho, para que bebam os que se cansarem no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'E disse o rei: Onde está o filho de teu senhor? E Ziba respondeu ao rei: Eis que ele ficou em Jerusalém, porque disse: Hoje me devolverá a casa de Israel o reino de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Então o rei disse a Ziba: Eis que, seja teu tudo o que tem Mefibosete. E respondeu Ziba inclinando-se: Rei senhor meu, ache eu favor diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'E veio o rei Davi até Baurim: e eis que, saía um da família da casa de Saul, o qual se chamava Simei, filho de Gera; e saía amaldiçoando,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'E lançando pedras contra Davi, e contra todos os servos do rei Davi: e todo aquele povo, e todos os homens valentes estavam à sua direita e à sua esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'E dizia Simei, amaldiçoando-lhe: Sai, sai, homem sanguinário, e homem maligno!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'O SENHOR te retribuiu por todo o sangue da casa de Saul, em lugar do qual tu reinaste: mas o SENHOR entregou o reino em mãos de teu filho Absalão; e eis que estás em tua desgraça, porque és homem sanguinário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Então Abisai filho de Zeruia, disse ao rei: Por que almadiçoa este cão morto a meu senhor o rei? Eu te rogo que me deixes passar, e tirarei dele a cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'E o rei respondeu: Que tenho eu convosco, filhos de Zeruia? Ele almadiçoa assim, porque o SENHOR lhe disse que almadiçoasse a Davi; quem pois lhe dirá: Por que o fazes assim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'E disse Davi a Abisai e a todos os seus servos: Eis que, meu filho que saiu de minhas entranhas, busca à minha vida: quanto mais agora um filho de Benjamim? Deixai-lhe que amaldiçoe, que o SENHOR se o disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Talvez o SENHOR olhe a minha aflição, e o SENHOR me conceda o bem por suas maldições de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'E quando Davi e os seus iam pelo caminho, Simei ia pelo lado do monte diante dele, andando e amaldiçoando, e lançando pedras diante dele, e espalhando pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'E o rei e todo aquele povo que com ele estava, chegaram exaustos, e descansaram ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'E Absalão e todo aquele povo, os homens de Israel, entraram em Jerusalém, e com ele Aitofel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'E aconteceu logo, que quando Husai arquita amigo de Davi chegou a Absalão, disse-lhe Husai: Viva o rei, viva o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'E Absalão disse a Husai: Este é teu agradecimento para com teu amigo? Por que não foste com teu amigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'E Husai respondeu a Absalão: Não; mas sim a quem o SENHOR escolher, assim como este povo e todos os homens de Israel, dele serei eu, e com ele permanecerei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'E a quem havia eu de servir? Não seria a seu filho? Como servi diante de teu pai, assim serei diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Então disse Absalão a Aitofel: Consultai que faremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'E Aitofel disse a Absalão: Entra às concubinas de teu pai, que ele deixou para guardar a casa; e todo aquele povo de Israel ouvirá que te fizeste aborrecível a teu pai, e assim se esforçarão as mãos de todos os que estão contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Então puseram uma tenda a Absalão sobre o terraço, e entrou Absalão às concubinas de seu pai, em olhos de todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'E o conselho que dava Aitofel em aqueles dias, era como se consultassem a palavra de Deus. Tal era o conselho de Aitofel, assim com Davi como com Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Então Aitofel disse a Absalão: Eu escolherei agora doze mil homens, e me levantarei, e seguirei a Davi esta noite;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'E o atacarei quando ele estiver cansado e fraco das mãos; eu o atemorizarei, e todo aquele povo que está com ele fugirá, e ferirei ao rei somente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Assim farei tornar todo aquele povo a ti: e quando eles houverem voltado, (pois aquele homem é o que tu queres) todo aquele povo estará em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Esta razão apareceu bem a Absalão e a todos os anciãos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'E disse Absalão: Chama também agora a Husai arquita, para que também ouçamos o que ele dirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'E quando Husai veio a Absalão, falou-lhe Absalão, dizendo: Assim disse Aitofel; seguiremos seu conselho, ou não? Dize tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Então Husai disse a Absalão: O conselho que deu esta vez Aitofel não é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'E acrescentou Husai: Tu sabes que teu pai e os seus são homens valentes, e que estão com amargura de ânimo, como a ursa no campo quando lhe tiraram os filhos. Além disso, teu pai é homem de guerra, e não terá a noite com o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Eis que ele estará agora escondido em alguma cova, ou em outro lugar: e se ao princípio caírem alguns dos teus, ouvirá quem o ouvir, e dirá: O povo que segue a Absalão foi derrotado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Assim ainda o homem valente, cujo coração seja como coração de leão, sem dúvida desmaiará: porque todo Israel sabe que teu pai é homem valente, e que os que estão com ele são esforçados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Aconselho, pois, que todo Israel se junte a ti, desde Dã até Berseba, em multidão como a areia que está à beira do mar, e que tu em pessoa vás à batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Então lhe acometeremos em qualquer lugar que puder achar-se, e viremos contra ele como quando o orvalho cai sobre a terra, e a ninguém deixaremos dele, e de todos os que com ele estão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'E se se recolher em alguma cidade, todos os de Israel trarão cordas àquela cidade, e a arrastaremos até o ribeiro, que nunca mais apareça pedra dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Então Absalão e todos os de Israel disseram: O conselho de Husai arquita é melhor que o conselho de Aitofel. Porque o SENHOR havia ordenado que o acertado conselho de Aitofel se frustrasse, para que o SENHOR fizesse vir o mal sobre Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Disse logo Husai a Zadoque e a Abiatar sacerdotes: Assim e assim aconselhou Aitofel a Absalão e aos anciãos de Israel: e desta maneira aconselhei eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Portanto enviai imediatamente, e dai aviso a Davi, dizendo: Não fiques esta noite nos campos do deserto, mas sim passa logo o Jordão, para que o rei não seja consumido, e todo aquele povo que com ele está.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'E Jônatas e Aimaás estavam junto à fonte de Rogel, porque não podiam eles mostrar-se vindo à cidade; foi, portanto, uma criada, e deu-lhes o aviso: e eles foram, e noticiaram-no ao rei Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Porém foram vistos por um jovem, o qual deu conta a Absalão: porém os dois se apressaram em caminhar, e chegaram à casa de um homem em Baurim, que tinha um poço em seu pátio, dentro do qual se meteram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'E tomando a mulher da casa uma manta, estendeu-a sobre a boca do poço, e estendeu sobre ela o grão trilhado; e não se penetrou o negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Chegando logo os criados de Absalão à casa à mulher, disseram-lhe: Onde estão Aimaás e Jônatas? E a mulher lhes respondeu: Já passaram o vau das águas. E quando eles os buscaram e não os acharam voltaram a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'E depois que eles se houveram ido, aqueles saíram do poço, e foram-se, e deram aviso ao rei Davi; e disseram-lhe: Levantai-vos e apressai-vos a passar as águas, porque Aitofel deu tal conselho contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Então Davi se levantou, e todo aquele povo que com ele estava, e passaram o Jordão antes que amanhecesse; nem sequer faltou um que não passasse o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'E Aitofel, vendo que não se havia praticado seu conselho, preparou seu asno, e levantou-se, e foi-se à sua casa em sua cidade; e depois de dar ordens acerca de sua casa, enforcou-se e morreu, e foi sepultado no sepulcro de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'E Davi chegou a Maanaim, e Absalão passou o Jordão com toda a gente de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'E Absalão constituiu a Amasa, sobre o exército em lugar de Joabe, o qual Amasa foi filho de um homem de Israel chamado Itra, o qual havia se deitado com Abigail filha de Naás, irmã de Zeruia, mãe de Joabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'E Israel assentou acampamento com Absalão na terra de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'E logo que Davi chegou a Maanaim, Sobi filho de Naás de Rabá dos filhos de Amom, e Maquir filho de Amiel de Lo-Debar, e Barzilai gileadita de Rogelim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Trouxeram a Davi e ao povo que estava com ele, camas, e bacias, e vasilhas de barro, e trigo, e cevada, e farinha, e grão tostado, favas, lentilhas, e grãos tostados,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Mel, manteiga, ovelhas, e queijos de vacas, para que comessem; porque disseram: Aquele povo está faminto, e cansado, e terá sede no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Davi, pois, revistou o povo que tinha consigo, e pôs sobre eles comandantes de mil e comandantes de cem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'E enviou a terça parte do povo ao mando de Joabe, e outra terça parte ao mando de Abisai, filho de Zeruia, irmão de Joabe, e a outra terceira parte ao mando de Itai geteu. E disse o rei ao povo: Eu também sairei convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Mas o povo disse: Não sairás; porque se nós fugirmos, não farão caso de nós; e ainda que a metade de nós morra, não farão caso de nós: mas tu agora vales tanto quanto dez mil de nós. Será pois melhor que da cidade tu nos ajudes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Então o rei lhes disse: Eu farei o que bem vos parecer. E pôs-se o rei à entrada da porta, enquanto saía todo aquele povo de cento em cento e de mil em mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'E o rei mandou a Joabe e a Abisai e a Itai, dizendo: Tratai benignamente por causa de mim ao jovem Absalão. E todo aquele povo ouviu quando deu o rei ordem acerca de Absalão a todos os capitães.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Saiu, pois, o povo ao acampamento contra Israel, e houve a batalha no bosque de Efraim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'E ali caiu o povo de Israel diante dos servos de Davi, e fez-se uma grande matança de vinte mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'E espalhando-se ali o exército pela face de toda a terra, foram mais os que o bosque consumiu dos do povo, que os que a espada consumiu naquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'E encontrou-se Absalão com os servos de Davi: e ia Absalão sobre um mulo, e o mulo se entrou debaixo de um espesso e grande carvalho, e prendeu-lhe a cabeça ao carvalho, e ficou entre o céu e a terra; pois o mulo em que ia passou adiante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'E vendo-o um, avisou a Joabe, dizendo: Eis que vi a Absalão pendurado em um carvalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'E Joabe respondeu ao homem que lhe dava a nova: E vendo-o tu, por que não lhe feriste logo ali lançando-lhe à terra? E sobre mim, que te haveria dado dez siclos de prata, e um cinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'E o homem disse a Joabe: Ainda que me importasse em minhas mãos mil siclos de prata, não estenderia eu minha mão contra o filho do rei; porque nós o ouvimos quando o rei te mandou a ti e a Abisai e a Itai, dizendo: Olhai que ninguém toque no jovem Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Por outra parte, haveria eu feito traição contra minha vida (pois que ao rei nada se lhe esconde), e tu mesmo estarias contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'E respondeu Joabe: Não perderei tempo contigo. E tomando três dardos em suas mãos, fincou-os no coração de Absalão, que ainda estava vivo em meio do carvalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Cercando-o logo dez rapazes escudeiros de Joabe, feriram a Absalão, e acabaram-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Então Joabe tocou a trombeta, e o povo deixou de seguir a Israel, porque Joabe deteve ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Tomando depois a Absalão, lançaram-lhe em um grande fosso no bosque, e levantaram sobre ele um muito grande amontoado de pedras; e todo Israel fugiu, cada um a suas moradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'E havia Absalão em sua vida tomado e levantado-se uma coluna, a qual está no vale do rei; porque havia dito: Eu não tenho filho que conserve a memória de meu nome. E chamou aquela coluna de seu nome: e assim se chamou o Lugar de Absalão, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Então Aimaás filho de Zadoque disse: Correrei agora, e darei as novas ao rei de como o SENHOR defendeu sua causa da mão de seus inimigos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'E respondeu Joabe: Hoje não levarás as novas: as levarás outro dia: não darás hoje a nova, porque o filho do rei está morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'E Joabe disse a um cuxita: Vai tu, e dize ao rei o que viste. E o cuxita fez reverência a Joabe, e correu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Então Aimaás filho de Zadoque voltou a dizer a Joabe: Seja o que for, eu correrei agora atrás do cuxita. E Joabe disse: Filho meu, para que hás tu de escorrer, pois que não acharás prêmio pelas novas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Mas ele respondeu: Seja o que for, eu correrei. Então lhe disse: Corre. Correu, pois, Aimaás pelo caminho da planície, e passou diante do cuxita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Estava Davi naquele tempo sentado entre as duas portas; e o atalaia havia ido ao terraço de sobre a porta no muro, e levantando seus olhos, olhou, e viu a um que corria sozinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'O vigilante deu logo vozes, e o fez saber ao rei. E o rei disse: Se está sozinho, boas novas traze. Em tanto que ele vinha aproximando-se,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Viu o vigilante outro que corria; e deu vozes o vigilante ao porteiro, dizendo: Eis que outro homem que corre sozinho. E o rei disse: Este também é mensageiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'E o vigilante voltou a dizer: Parece-me o correr do primeiro como o correr de Aimaás filho de Zadoque. E respondeu o rei: Esse é homem de bem, e vem com boa nova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Então Aimaás disse em alta voz ao rei: Paz. E inclinou-se à terra diante do rei, e disse: Bendito seja o SENHOR Deus teu, que entregou aos homens que haviam levantado suas mãos contra meu senhor o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'E o rei disse: O jovem Absalão tem paz? E Aimaás respondeu: Vi eu um grande alvoroço quando enviou Joabe ao servo do rei e a mim teu servo; mas não sei que era.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'E o rei disse: Passa, e põe-te ali. E ele passou, e parou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'E logo veio o cuxita, e disse: Receba notícia, meu senhor o rei, que hoje o SENHOR defendeu tua causa da mão de todos os que se haviam levantado contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'O rei então disse ao cuxita: O jovem Absalão tem paz? E o cuxita respondeu: Sejam como aquele jovem os inimigos de meu senhor o rei, e todos os que se levantam contra ti para mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Então o rei se perturbou, e subiu-se à sala da porta, e chorou; e indo, dizia assim: Filho meu Absalão, filho meu, filho meu Absalão! Quem me dera que morresse eu em lugar de ti, Absalão, filho meu, filho meu!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'E deram aviso a Joabe: Eis que o rei chora, e faz luto por Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'E voltou-se aquele dia a vitória em luto para todo aquele povo; porque ouviu dizer o povo aquele dia que o rei tinha dor por seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Entrou-se o povo aquele dia na cidade escondidamente, como costuma entrar às escondidas o povo envergonhado que fugiu da batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Mas o rei, coberto o rosto, clamava em alta voz: Filho meu Absalão, Absalão, filho meu, filho meu!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'E entrando Joabe em casa ao rei, disse-lhe: Hoje envergonhaste o rosto de todos os teus servos, que hoje livraram tua vida, e a vida de teus filhos e de tuas filhas, e a vida de tuas mulheres, e a vida de tuas concubinas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Amando aos que te aborrecem, e aborrecendo aos que te amam: porque hoje declaraste que nada te importam teus príncipes e servos; pois hoje deste a entender que se Absalão vivesse, bem que nós todos estivéssemos hoje mortos, então te contentarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Levanta-te, pois, agora, e sai fora, e elogia a teus servos: porque juro pelo SENHOR, que se não saíres, nem um sequer ficará contigo esta noite; e disto te pesará mais que de todos os males que te sobrevieram desde tua juventude até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Então se levantou o rei, e sentou-se à porta; e foi declarado a todo aquele povo, dizendo: Eis que o rei está sentado à porta. E veio todo aquele povo diante do rei; mas Israel havia fugido, cada um a suas moradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'E todo aquele povo discutia em todas as tribos de Israel, dizendo: O rei nos livrou da mão de nossos inimigos, e ele nos salvou da mão dos filisteus; e agora havia fugido, da terra por medo de Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'E Absalão, a quem havíamos ungido sobre nós, é morto na batalha. Por que, pois, estais agora quietos em ordem a fazer voltar ao rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'E el rei Davi enviou a Zadoque e a Abiatar sacerdotes, dizendo: Falai aos anciãos de Judá e dizei-lhes: Por que sereis vós os últimos em voltar o rei à sua casa, já que a palavra de todo Israel veio ao rei de voltar-lhe à sua casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Vós sois meus irmãos; sois meus ossos e minha carne; por que, pois sereis vós os últimos em voltar ao rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Também direis a Amasa: Não és tu também osso meu e carne minha? Assim me faça Deus, e assim me acrescente, se não fores general do exército diante de mim para sempre, em lugar de Joabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Assim inclinou o coração de todos os homens de Judá, como o de um só homem, para que enviassem a dizer ao rei: Volta, com todos os teus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Voltou, pois o rei, e veio até o Jordão. E Judá veio a Gilgal, a receber ao rei e fazê-lo passar o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'E Simei filho de Gera, filho de Benjamim, que era de Baurim, apressou-se a vir com os homens de Judá a receber ao rei Davi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'E com ele vinham mil homens de Benjamim; também Ziba criado da casa de Saul, com seus quinze filhos e seus vinte servos, os quais passaram o Jordão diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Atravessou depois o barco para passar a família do rei, e para fazer o que lhe agradasse. Então Simei filho de Gera se prostrou diante do rei quando ele havia passado o Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'E disse ao rei: Não me impute meu senhor iniquidade, nem tenhas memória dos males que teu servo fez o dia que meu senhor o rei saiu de Jerusalém, para guardá-los o rei em seu coração;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Porque eu teu servo conheço haver pecado, e vim hoje o primeiro de toda a casa de José, para descer a receber a meu senhor o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'E Abisai filho de Zeruia respondeu e disse: Não morrerá por isto Simei, que amaldiçoou ao ungido do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Davi então disse: Que tendes vós comigo, filhos de Zeruia, que me haveis de ser hoje adversários? Morrerá hoje alguém em Israel? Não sei eu que hoje sou rei sobre Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'E disse o rei a Simei: Não morrerás. E o rei jurou a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Também Mefibosete filho de Saul desceu a receber ao rei: não havia lavado seus pés, nem havia cortado sua barba, nem tampouco havia lavado suas roupas, desde o dia que o rei saiu até o dia que veio em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'E logo que veio ele a Jerusalém a receber ao rei, o rei lhe disse: Mefibosete, Por que não foste comigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'E ele disse: Rei senhor meu, meu servo me enganou; pois havia teu servo dito: Prepararei um asno, e subirei nele, e irei ao rei; porque teu servo é coxo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Porém ele caluniou a teu servo diante de meu senhor o rei; mas meu senhor o rei é como um anjo de Deus: faze, pois, o que bem te parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Porque toda a casa de meu pai era digna de morte diante de meu senhor o rei, e tu puseste a teu servo entre os convidados de tua mesa. Que direito, pois, tenho ainda para queixar-me mais contra o rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'E o rei lhe disse: Para que falas mais palavras? Eu determinei que tu e Ziba repartais as terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'E Mefibosete disse ao rei: E ainda tome-as ele todas, pois que meu senhor o rei voltou em paz à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Também Barzilai gileadita desceu de Rogelim, e passou o Jordão com o rei, para acompanhar-lhe da outra parte do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'E era Barzilai muito velho, de oitenta anos, o qual havia dado provisão ao rei quando estava em Maanaim, porque era homem muito rico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'E o rei disse a Barzilai: Passa comigo, e eu te darei de comer comigo em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Mas Barzilai disse ao rei: Quantos são os dias do tempo de minha vida, para que eu suba com o rei a Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Eu sou hoje da idade de oitenta anos, que já não farei diferença entre o bem e o mal: tomará gosto agora teu servo no que comer ou beber? Ouvirei mais a voz dos cantores e das cantoras? Para que, pois, seria ainda teu servo incômodo ao meu senhor, o rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Passará teu servo um pouco o Jordão com o rei: por que me há de dar o rei tão grande recompensa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Eu te rogo que deixes voltar a teu servo, e que morra em minha cidade, junto ao sepulcro de meu pai e de minha mãe. Eis aqui teu servo Quimã; que passe ele com meu senhor o rei, e faze-lhe o que bem te parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'E o rei disse: Pois passe comigo Quimã, e eu farei com ele como bem te pareça: e tudo o que tu me pedires, eu o farei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'E todo aquele povo passou o Jordão: e logo que o rei também passou, o rei beijou a Barzilai, e abençoou-o; e ele se voltou à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'O rei então passou a Gilgal, e com ele passou Quimã; e todo aquele povo de Judá, com a metade do povo de Israel, acompanharam o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'E eis que todos os homens de Israel vieram ao rei, e lhe disseram: Por que os homens de Judá, nossos irmãos, te levaram, e fizeram passar o Jordão ao rei e à sua família, e a todos os homens de Davi com ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'E todos os homens de Judá responderam a todos os de Israel: Porque o rei é nosso parente. Mas por que vos irais vós disso? Temos nós comido algo do rei? Temos recebido dele algum presente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Então responderam os homens de Israel, e disseram aos de Judá: Nós temos no rei dez partes, e no mesmo Davi mais que vós: por que, pois, nos haveis tido em pouco? Não falamos nós primeiro em voltar a nosso rei? E o argumento dos homens de Judá prevaleceu ao dos homens de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'E aconteceu estar ali um homem perverso que se chamava Seba, filho de Bicri, homem de Benjamim, o qual tocou a trombeta, e disse: Não temos nós parte em Davi, nem herança no filho de Jessé: Israel, cada um a suas moradas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Assim deixaram de seguir Davi todos os homens de Israel, e seguiam a Seba filho de Bicri: mas os de Judá se aderiram a seu rei, desde o Jordão até Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'E logo que chegou Davi a sua casa em Jerusalém, tomou o rei as dez mulheres concubinas que havia deixado para guardar a casa, e as pôs em uma casa em guarda, e deu-lhes de comer: mas nunca mais entrou a elas, mas sim que ficaram encerradas até que morressem como viúvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Depois disse o rei a Amasa: Junta-me os homens de Judá para dentro de três dias, e acha-te tu aqui presente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Foi, pois, Amasa a juntar a Judá; mas deteve-se mais do tempo que lhe havia sido assinalado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'E disse Davi a Abisai: Seba filho de Bicri nos fará agora mais mal que Absalão: toma, pois tu os servos de teu senhor, e vai atrás dele, não seja que ache as cidades fortificadas, e escape de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Então saíram depois dele os homens de Joabe, e os quereteus e peleteus, e todos os valentes: saíram de Jerusalém para ir atrás de Seba filho de Bicri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'E estando eles próximo da grande penha que está em Gibeão, saiu-lhes Amasa ao encontro. Agora bem, a vestimenta que Joabe tinha sobreposta estava-lhe cingida, e sobre ela o cinto de um punhal apegado a seus lombos em sua bainha, da que assim quando ele avançou, o punhal caiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Então Joabe disse a Amasa: Tens paz, irmão meu? E tomou Joabe com a direita a barba de Amasa, para beijá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'E como Amasa não se cuidou do punhal que Joabe na mão tinha, feriu-lhe este com ela na quinta costela, e derramou suas entranhas por terra, e caiu morto sem dar-lhe segundo golpe. Depois Joabe e seu irmão Abisai perseguiram Seba filho de Bicri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'E um dos criados de Joabe se parou junto a ele, dizendo: Qualquer um que amar a Joabe e a Davi vá atrás de Joabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'E Amasa se havia revolvido no sangue no meio do caminho: e vendo aquele homem que todo aquele povo se parava, separou a Amasa do caminho ao campo, e lançou sobre ele uma vestimenta, porque via que todos os que vinham se paravam junto a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Logo, pois, que foi afastado do caminho, passaram todos os que seguiam a Joabe, para ir atrás de Seba filho de Bicri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'E ele passou por todas as tribos de Israel até Abel e Bete-Maaca e toda a terra dos beritas: e juntaram-se, e seguiram-no também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'E vieram e cercaram-no em Abel de Bete-Maaca, e puseram baluarte contra a cidade; e posto que foi ao muro, todo aquele povo que estava com Joabe trabalhava por derrubar a muralha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Então uma mulher sábia deu vozes na cidade, dizendo: Ouvi, ouvi; rogo-vos que digais a Joabe se chegue a aqui, para que eu fale com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'E quando ele se aproximou a ela, disse a mulher: És tu Joabe? E ele respondeu: Eu sou. E ela lhe disse: Ouve as palavras de tua serva. E ele respondeu: Ouço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Então voltou ela a falar, dizendo: Antigamente costumavam falar, dizendo: Quem perguntar, pergunte em Abel: e assim concluíam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Eu sou das pacíficas e fiéis de Israel: e tu procuras destruir uma cidade que é mãe de Israel: por que destróis a herança do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'E Joabe respondeu, dizendo: Nunca tal, nunca tal me aconteça, que eu destrua nem desfaça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'A coisa não é assim: mas um homem do monte de Efraim, que se chama Seba filho de Bicri, levantou sua mão contra o rei Davi: entregai a esse somente, e me irei da cidade. E a mulher disse a Joabe: Eis que sua cabeça te será lançada desde o muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'A mulher foi logo a todo aquele povo com sua sabedoria; e eles cortaram a cabeça a Seba filho de Bicri, e lançaram-na a Joabe. E ele tocou a trombeta, e dispersaram-se da cidade, cada um à sua morada. E Joabe se voltou ao rei a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Assim ficou Joabe sobre todo aquele exército de Israel; e Benaia filho de Joiada sobre os quereteus e peleteus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'E Adorão sobre os tributos; e Josafá filho de Ailude, o cronista;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'E Seva, escriba; e Zadoque e Abiatar, sacerdotes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'E Ira jairita foi um chefe oficial de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'E nos dias de Davi houve fome por três anos consecutivos. E Davi consultou ao SENHOR, e o SENHOR lhe disse: É por Saul, e por aquela casa de sangue; porque matou aos gibeonitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Então o rei chamou aos gibeonitas, e falou-lhes. (Os gibeonitas não eram dos filhos de Israel, mas sim do resto dos amorreus, aos quais os filhos de Israel fizeram juramento; mas Saul havia procurado matá-los com motivo de zelo pelos filhos de Israel e de Judá).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Disse, pois Davi aos gibeonitas: Que vos farei, e com que expiarei para que abençoeis à herança do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'E os gibeonitas lhe responderam: Não temos nós queixa sobre prata nem sobre ouro com Saul, e com sua casa: nem queremos que morra homem de Israel. E ele lhes disse: O que vós disserdes vos farei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'E eles responderam ao rei: Daquele homem que nos destruiu, e que tramou contra nós, para nos exterminar sem deixar nada de nós em todo aquele termo de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Deem-se a nós sete homens de seus filhos, para que os enforquemos ao SENHOR em Gibeá de Saul, o escolhido do SENHOR. E o rei disse: Eu os darei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'E perdoou o rei a Mefibosete, filho de Jônatas, filho de Saul, pelo juramento do SENHOR que havia entre eles, entre Davi e Jônatas filho de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Mas tomou o rei dois filhos de Rispa filha de Aiá, os quais ela havia dado à luz de Saul, a saber, a Armoni e a Mefibosete; e cinco filhos de Mical filha de Saul, os quais ela havia dado à luz de Adriel, filho de Barzilai meolatita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'E entregou-os em mãos dos gibeonitas, e eles os enforcaram no monte diante do SENHOR: e morreram juntos aqueles sete, os quais foram mortos no tempo da colheita, nos primeiros dias, no princípio da colheita das cevadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Tomando logo Rispa filha de Aiá um saco, estendeu-o sobre um penhasco, desde o princípio da colheita até que choveu sobre eles água do céu; e não deixou a nenhuma ave do céu assentar-se sobre eles de dia, nem animais do campo de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'E foi dito a Davi o que fazia Rispa filha de Aiá, concubina de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Então Davi foi, e tomou os ossos de Saul e os ossos de Jônatas seu filho, dos homens de Jabes de Gileade, que os haviam furtado da praça de Bete-Seã, de onde os haviam pendurado os filisteus, quando os filisteus mataram a Saul em Gilboa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'E fez levar dali os ossos de Saul e os ossos de Jônatas seu filho; e juntaram também os ossos dos enforcados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'E sepultaram os ossos de Saul e os de seu filho Jônatas em terra de Benjamim, em Selá, no sepulcro de Quis seu pai; e fizeram tudo o que o rei havia mandado. Depois se aplacou Deus com a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'E quando os filisteus voltaram a fazer guerra a Israel, desceu Davi e seus servos com ele, e lutaram com os filisteus: e Davi se cansou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Em isto Isbi-Benobe, o qual era dos filhos do gigante, e o peso de cuja lança era de trezentos siclos de bronze, e tinha ele cingida uma nova espada, tratou de ferir a Davi:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mas Abisai filho de Zeruia lhe socorreu, e feriu ao filisteu, e o matou. Então os homens de Davi lhe juraram, dizendo: Nunca mais daqui adiante sairás conosco à batalha, para que não apagues a lâmpada de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Outra segunda guerra houve depois em Gobe contra os filisteus: então Sibecai husatita feriu a Safe, que era dos filhos do gigante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Outra guerra houve em Gobe contra os filisteus, na qual Elanã, filho de Jaaré-Oregim de Belém, feriu a Golias geteu, a haste de cuja lança era como um lançador de tear.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Depois houve outra guerra em Gate, de onde houve um homem de grande altura, o qual tinha doze dedos nas mãos, e outros doze nos pés, vinte e quatro em todos: e também era dos filhos do gigante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Este desafiou a Israel, e foi morto por Jônatas, filho de Simeia irmão de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Estes quatro lhe haviam nascido ao gigante em Gate, os quais caíram pela mão de Davi e pela mão de seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'E falou Davi ao SENHOR as palavras deste cântico, o dia que o SENHOR o livrou da mão de todos os seus inimigos e da mão de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'E disse: O SENHOR é minha rocha, e minha fortaleza, e meu libertador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Deus de minha rocha, nele confiarei: Meu escudo, e o poder de minha salvação, minha fortaleza, e meu refúgio; Meu salvador, que me livrarás de violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Invocarei ao SENHOR, digno de ser louvado. E serei salvo de meus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Quando me cercaram ondas de morte, E ribeiros de iniquidade me assombraram,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'As cordas do mundo dos mortos me rodearam, e laços de morte me tomaram desprevenido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Tive angústia, invoquei ao SENHOR, E clamei a meu Deus: E ele ouviu minha voz desde seu templo; Chegou meu clamor a seus ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'A terra se moveu, e tremeu; Os fundamentos dos céus foram movidos, E se estremeceram, porque ele se irou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Subiu fumaça de suas narinas, E de sua boca fogo consumidor, Pelo qual se acenderam carvões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'E abaixo os céus, e desceu: Uma escuridão debaixo de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Subiu sobre o querubim, e voou: Apareceu-se sobre as asas do vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Armou tendas de escuridão ao redor de si; nuvens negras e espessas, carregadas de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Do resplendor de sua presença Se acenderam brasas ardentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'O SENHOR trovejou desde os céus, E o Altíssimo deu sua voz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Lançou flechas, e desbaratou-os; Relampejou, e consumiu-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Então apareceram as profundezas do mar, E os fundamentos do mundo foram descobertos, À repreensão do SENHOR, Ao sopro do vento de seu nariz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Estendeu sua mão do alto, e arrebatou-me, E tirou-me de copiosas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Livrou-me de fortes inimigos, De aqueles que me aborreciam, os quais eram mais fortes que eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Atacaram-me no dia de minha calamidade; Mas o SENHOR foi meu apoio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Tirou-me para um lugar amplo; Livrou-me, porque se agradou de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Remunerou-me o SENHOR conforme minha justiça: E conforme a limpeza de minhas mãos ele me pagou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Porque eu guardei os caminhos do SENHOR; E não me apartei impiamente de meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Porque diante de mim tenho todas suas ordenanças; E atento a seus estatutos, não me retirarei deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'E fui íntegro para com ele, E guardei-me de minha iniquidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Remunerou-me, portanto, o SENHOR conforme minha justiça, E conforme minha limpeza diante de seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Com o bom és benigno, E com o íntegro te mostras íntegro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Limpo és para com o limpo, Mas com o perverso és rígido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'E tu salvas ao povo humilde; Mas teus olhos sobre os altivos, para abatê-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Porque tu és minha lâmpada, ó SENHOR; o SENHOR dá luz às minhas trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Pois contigo avançarei contra uma tropa, e com o meu Deus saltarei uma muralha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'O caminho de Deus é perfeito; a palavra do SENHOR é purificada, é escudo é de todos os que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Porque que Deus há a não ser o SENHOR? Ou quem é forte a não ser nosso Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Deus é o que com virtude me corrobora, e o que tira os obstáculos do meu caminho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'O que faz meus pés como de cervas, E o que me assenta em minhas alturas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'O que ensina minhas mãos para a luta, e proporciona que com meus braços quebre o arco de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Tu me deste também o escudo de tua salvação, E tua benignidade me acrescentou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Tu alargaste meus desfiladeiros debaixo de mim, Para que não titubeassem meus joelhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Perseguirei a meus inimigos, e os quebrantarei; E não me voltarei até que os acabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Os consumirei, e os ferirei, e não se levantarão; E cairão debaixo de meus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Cingiste-me de força para a batalha, E fizeste prostrar debaixo de mim os que contra mim se levantaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Tu me deste o pescoço de meus inimigos, De meus aborrecedores, que eu os destruísse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Olharam, e não houve quem os livrasse; Ao SENHOR, mas não lhes respondeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Eu os esmiuçarei como pó da terra; Eu os pisarei como à lama das ruas, e os dissiparei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Tu me livraste das brigas dos povos; Tu me guardaste para eu que fosse cabeça de nações: Povos que eu não conhecia me serviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Os estrangeiros se sujeitaram a mim; ao ouvirem, me obedeciam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Os estrangeiros desfaleciam, E tremiam em seus esconderijos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Viva o SENHOR, e seja bendita minha rocha; Seja exaltado o Deus, a rocha de meu salvamento:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'O Deus que me vingou, E sujeita os povos debaixo de mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'E que me tira dentre meus inimigos: Tu me tiraste em alto dentre os que se levantaram contra mim: Livraste-me do homem de iniquidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Portanto eu te confessarei entre as nações, ó SENHOR, E cantarei a teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Ele que engrandece as saúdes de seu rei, E faz misericórdia a seu ungido, A Davi, e à sua semente, para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Estas são as últimas palavras de Davi. Disse Davi filho de Jessé, Disse aquele homem que foi levantado alto, O ungido do Deus de Jacó, O suave em cânticos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'O espírito do SENHOR falou por mim, E sua palavra foi em minha língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'O Deus de Israel disse, Falou-me o Forte de Israel: O dominador dos homens será justo. Dominador em temor de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Será como a luz da manhã quando sai o sol, Da manhã sem nuvens; Quando a erva da terra brota Por meio do resplendor depois da chuva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Não está minha casa com Deus? Pois ele fez comigo um pacto perpétuo, Ordenado em todas as coisas, e será guardado; pois não é dele que brotará toda a minha salvação e todo o meu desejo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Mas os malignos serão todos eles como espinhos arrancados, os quais ninguém toma com a mão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Em vez disso o que quer tocar neles, Arma-se de ferro e de haste de lança, e são queimados em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Estes são os nomes dos valentes que teve Davi: Josebe-Bassebete, o taquemonita, principal dos capitães: era este Adino o eznita, que matou em uma ocasião sobre oitocentos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Depois deste, Eleazar, filho de Dodô de Aoí, foi dos três valentes que estavam com Davi, quando desafiaram aos filisteus que se haviam juntado ali à batalha, e subiram os de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Este, levantando-se, feriu aos filisteus, até que sua mão se cansou, e ficou grudada em sua espada. Aquele dia o SENHOR fez grande salvação; e voltou-se o povo depois dele somente para tomar o despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Depois deste foi Samá, filho de Agé araíta: que havendo os filisteus se juntado em uma aldeia, havia ali um terreno cheio de lentilhas, e o povo havia fugido diante dos filisteus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Ele então se parou em meio do terreno e defendeu-o, e feriu aos filisteus; e o SENHOR fez uma grande salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'E três dos trinta principais desceram e vieram em tempo da colheita a Davi à cova de Adulão: e o acampamento dos filisteus estava no vale de Refaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Davi então estava na fortaleza, e a guarnição dos filisteus estava em Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'E Davi teve desejo, e disse: Quem me dera a beber da água da cisterna de Belém, que está à porta!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Então os três valentes irromperam pelo acampamento dos filisteus, e tiraram água da cisterna de Belém, que estava à porta; e tomaram, e trouxeram-na a Davi: mas ele não a quis beber, mas derramou-a ao SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Longe seja de mim, ó SENHOR, que eu faça isto. Eis de beber eu o sangue dos homens que foram com perigo de sua vida? E não quis bebê-la. Os três valentes fizeram isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'E Abisai irmão de Joabe, filho de Zeruia, foi o principal dos três; o qual levantou sua lança contra trezentos, que matou; e teve nome entre os três.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Ele era o mais preeminente dos três, e o primeiro deles; mas não chegou aos três primeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Depois, Benaia filho de Joiada, filho de um homem esforçado, grande em feitos, de Cabzeel. Este feriu dois leões de Moabe: e ele mesmo desceu, e feriu um leão em meio de um fosso no tempo da neve:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Também feriu ele a um egípcio, homem de grande estatura; e tinha o egípcio uma lança em sua mão; mas desceu a ele com um cajado, e arrebatou ao egípcio a lança da mão, e o matou com sua própria lança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Isto fez Benaia filho de Joiada, e teve nome entre os três valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Dos trinta foi o mais preeminente; mas não chegou aos três primeiros. E Davi o pôs em seu conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asael irmão de Joabe foi dos trinta; Elanã filho de Dodô de Belém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samá harodita, Elica harodita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Heles paltita, Ira, filho de Iques, de Tecoa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer de Anatote, Mebunai husatita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmom aoíta, Maarai de Netofate;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Helebe filho de Baaná de Netofate, Itai filho de Ribai de Gibeá dos filhos de Benjamim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaia piratonita, Hidai do ribeiro de Gaás;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi-Albom de Arbate, Azmavete barumita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eleaba de Saalbom, Jônatas dos filhos de Jásen;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samá de Harar, Aião filho de Sarar de Harar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelete filho de Aasbai filho do maacatita; Eliã filho de Aitofel gilonita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezrai do Carmelo, Paarai arbita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Igal filho de Natã de Zobá, Bani gadita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zeleque de Amom, Naarai de Beerote, escudeiro de Joabe filho de Zeruia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira itrita, Garebe itrita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urias, o heteu. Entre todos, trinta e sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'E voltou o furor do SENHOR a acender-se contra Israel, e incitou a Davi contra eles a que dissesse: Vai, conta a Israel e a Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'E disse o rei a Joabe, general do exército que tinha consigo: Rodeia todas as tribos de Israel, desde Dã até Berseba, e contai o povo, para que eu saiba o número da gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'E Joabe respondeu ao rei: Acrescente o SENHOR teu Deus ao povo cem vezes tanto quanto são, e que o veja meu senhor ao rei; mas para que quer isto meu senhor o rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Porém a palavra do rei pôde mais que Joabe, e que os capitães do exército. Saiu, pois, Joabe, com os capitães do exército, de diante do rei, para contar o povo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'E passando o Jordão assentaram em Aroer, à direita da cidade que está em meio do ribeiro de Gade e junto a Jazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Depois vieram a Gileade, e à terra baixa de Hodsi: e dali vieram a Dã-Jaã e ao redor de Sídon.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'E vieram logo à fortaleza de Tiro, e a todas as cidades dos heveus e dos cananeus; e saíram ao sul de Judá, a Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'E depois que andaram toda a terra, voltaram a Jerusalém ao fim de nove meses e vinte dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'E Joabe deu a conta do número do povo ao rei; e foram os de Israel oitocentos mil homens fortes que tiravam espada; e dos de Judá quinhentos mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'E depois que Davi contou o povo, sentiu-se atormentado em seu coração; e disse Davi ao SENHOR: Eu pequei gravemente por haver feito isto; mas agora, ó SENHOR, rogo-te que tires o pecado de teu servo, porque eu agi muito loucamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'E pela manhã, quando Davi se levantou, veio a palavra do SENHOR a Gade profeta, vidente de Davi, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Vai, e dize a Davi: Assim disse o SENHOR: Três coisas te ofereço: tu te escolherás uma delas, a qual eu faça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Veio, pois, Gade a Davi, e notificou-lhe, e disse-lhe: Queres que te venham sete anos de fome em tua terra? Ou que fujas três meses diante de teus inimigos, e que eles te persigam? Ou que três dias haja pestilência em tua terra? Pensa agora, e olha o que responderei ao que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Então Davi disse a Gade: Em grande angústia estou: rogo que caia na mão do SENHOR, porque suas misericórdias são muitas, e que não caia eu em mãos de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'E enviou o SENHOR pestilência a Israel desde a manhã até o tempo assinalado: e morreram do povo, desde Dã até Berseba, setenta mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'E quando o anjo estendeu sua mão sobre Jerusalém para destruí-la, o SENHOR se arrependeu daquele mal, e disse ao anjo que destruía o povo: Basta agora; detém tua mão. Então o anjo do SENHOR estava junto à eira de Araúna, o jebuseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'E Davi disse ao SENHOR, quando viu ao anjo que feria ao povo: Eu pequei, eu fiz a maldade: que fizeram estas ovelhas? Rogo-te que tua mão se torne contra mim, e contra a casa de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'E Gade veio a Davi aquele dia, e disse-lhe: Sobe, e faze um altar ao SENHOR na era de Araúna jebuseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'E subiu Davi, conforme ao dito de Gade, que o SENHOR lhe havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'E olhando Araúna, viu ao rei e a seus servos que passavam a ele. Saindo então Araúna, inclinou-se diante do rei até terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'E Araúna disse: Por que vem meu senhor o rei a seu servo? E Davi respondeu: Para comprar de ti a eira, para edificar altar ao SENHOR, a fim de que a mortandade cesse do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'E Araúna disse a Davi: Tome e sacrifique meu senhor o rei o que bem lhe parecer; eis aqui bois para o holocausto; e trilhos e outros equipamentos de bois para lenha:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Tudo isto, ó rei, Araúna dá ao rei. Logo disse Araúna ao rei: o SENHOR teu Deus se agrade de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'E o rei disse a Araúna: Não, mas por preço o comprarei de ti; porque não oferecerei ao SENHOR meu Deus holocaustos gastando nada. Então Davi comprou a eira e os bois por cinquenta siclos de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'E ali Davi edificou um altar ao SENHOR, e sacrificou holocaustos e ofertas pacíficas; e o SENHOR se aplacou com a terra, e cessou a praga de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Quando o rei Davi era velho, e de idade avançada, cobriam-lhe de roupas, mas não se aquecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Disseram-lhe portanto seus servos: Busquem a meu senhor o rei uma moça virgem, para que esteja diante do rei, e o abrigue, e durma a seu lado, e aquecerá a meu senhor o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'E buscaram uma moça formosa por todo o termo de Israel, e acharam a Abisague sunamita, e trouxeram-na ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'E a moça era formosa, a qual aquecia ao rei, e lhe servia: mas o rei nunca a conheceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Então Adonias filho de Hagite se levantou, dizendo: Eu reinarei. E preparou carros e cavaleiros, e cinquenta homens que corressem adiante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'E seu pai nunca o entristeceu em todos seus dias com dizer-lhe: Por que fazes assim? E também este era de bela aparência; e havia o gerado depois de Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'E tinha tratos com Joabe filho de Zeruia, e com Abiatar sacerdote, os quais ajudavam a Adonias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mas Zadoque sacerdote, e Benaia filho de Joiada, e Natã profeta, e Simei, e Reí, e todos os grandes de Davi, não seguiam a Adonias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'E matando Adonias ovelhas e vacas e animais engordados junto à penha de Zoelete, que está próxima da fonte de Rogel, convidou a todos seus irmãos os filhos do rei, e a todos os homens de Judá, servos do rei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Mas não convidou a Natã profeta, nem a Benaia, nem aos grandes, nem a Salomão seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'E falou Natã a Bate-Seba mãe de Salomão, dizendo: Não ouviste que reina Adonias filho de Hagite, sem sabê-lo Davi nosso senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Vem pois agora, e toma meu conselho, para que guardes tua vida, e a vida de teu filho Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Vai, e entra ao rei Davi, e dize-lhe: Rei senhor meu, não juraste tu à tua serva, dizendo: Salomão teu filho reinará depois de mim, e ele se sentará em meu trono? por que pois reina Adonias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'E estando tu ainda falando com o rei, eu entrarei atrás de ti, e acabarei teus argumentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Então Bate-Seba entrou ao rei à câmara: e o rei era muito velho; e Abisague sunamita servia ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'E Bate-Seba se inclinou, e fez reverência ao rei. E o rei disse: Que tens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'E ela lhe respondeu: Senhor meu, tu juraste à tua serva pelo SENHOR teu Deus, dizendo: Salomão teu filho reinará depois de mim, e ele se sentará em meu trono;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'E eis que agora Adonias reina: e tu, meu senhor rei, agora não o soubeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Matou bois, e animais engordados, e muitas ovelhas, e convidou a todos os filhos do rei, e a Abiatar sacerdote, e a Joabe general do exército; mas a Salomão teu servo não convidou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Entretanto, rei senhor meu, os olhos de todo Israel estão sobre ti, para que lhes declares quem se há de sentar no trono de meu senhor o rei depois dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'De outra sorte acontecerá, quando meu senhor o rei descansar com seus pais, que eu e meu filho Salomão seremos tidos por culpados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'E estando ainda falando ela com o rei, eis que Natã profeta, que veio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'E deram aviso ao rei, dizendo: Eis que Natã profeta: o qual quando entrou ao rei, prostrou-se diante do rei inclinando seu rosto à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'E disse Natã: Rei senhor meu, disseste tu: Adonias reinará depois de mim, e ele se sentará em meu trono?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Porque hoje desceu, e matou bois, e animais engordados, e muitas ovelhas, e convidou a todos os filhos do rei, e aos capitães do exército, e também a Abiatar sacerdote; e eis que, estão comendo e bebendo diante dele, e disseram: Viva o rei Adonias!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mas nem a mim teu servo, nem a Zadoque sacerdote, nem a Benaia filho de Joiada, nem a Salomão teu servo, convidou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'É este negócio ordenado por meu senhor o rei, sem haver declarado a teu servo quem se havia de sentar no trono de meu senhor o rei depois dele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Então o rei Davi respondeu, e disse: Chamai-me a Bate-Seba. E ela entrou à presença do rei, e pôs-se diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'E o rei jurou, dizendo: Vive o SENHOR, que redimiu minha alma de toda angústia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Que como eu te ei jurado pelo SENHOR Deus de Israel, dizendo: Teu filho Salomão reinará depois de mim, e ele se sentará em meu trono em lugar meu; que assim o farei hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Então Bate-Seba se inclinou ao rei, seu rosto à terra, e fazendo reverência ao rei, disse: Viva meu senhor o rei Davi para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'E o rei Davi disse: Chamai-me a Zadoque sacerdote, e a Natã profeta, e a Benaia filho de Joiada. E eles entraram à presença do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'E o rei lhes disse: Tomai convosco os servos de vosso senhor, e fazei subir a Salomão meu filho em minha mula, e levai-o a Giom:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'E ali o ungirão Zadoque sacerdote e Natã profeta por rei sobre Israel; e tocareis trombeta, dizendo: Viva o rei Salomão!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Depois ireis vós detrás dele, e virá e se sentará em meu trono, e ele reinará por mim; porque a ele ordenei para que seja príncipe sobre Israel e sobre Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Então Benaia filho de Joiada respondeu ao rei, e disse: Amém. Assim o diga o SENHOR, Deus de meu senhor o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Da maneira que o SENHOR foi com meu senhor o rei, assim seja com Salomão; e ele faça maior seu trono que o trono de meu senhor o rei Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'E desceu Zadoque sacerdote, e Natã profeta, e Benaia filho de Joiada, e os quereteus e os peleteus, e fizeram subir a Salomão na mula do rei Davi, e levaram-no a Giom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'E tomando Zadoque sacerdote o chifre do azeite do tabernáculo, ungiu a Salomão: e tocaram trombeta, e disse todo o povo: Viva o rei Salomão!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Depois subiu todo o povo depois dele, e cantava a gente com flautas, e faziam grandes alegrias, que parecia que a terra se fendia com o barulho deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'E ouviu-o Adonias, e todos os convidados que com ele estavam, quando já haviam acabado de comer. E ouvindo Joabe o som da trombeta, disse: Por que se alvoroça a cidade com estrondo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Estando ainda ele falando, eis que Jônatas filho de Abiatar sacerdote veio, ao qual disse Adonias: Entra, porque tu és homem de esforço, e trarás boas novas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'E Jônatas respondeu, e disse a Adonias: Certamente nosso senhor o rei Davi há feito rei a Salomão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'E o rei enviou com ele a Zadoque sacerdote e a Natã profeta, e a Benaia filho de Joiada, e também aos quereteus e aos peleteus, os quais lhe fizeram subir na mula do rei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'E Zadoque sacerdote e Natã profeta o ungiram em Giom por rei: e de ali subiram com alegrias, e a cidade está cheia de estrondo. Este é o alvoroço que ouvistes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'E também Salomão se há sentado no trono do reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'E ainda os servos do rei vieram a bendizer a nosso senhor o rei Davi, dizendo: Deus faça bom o nome de Salomão mais que teu nome, e faça maior seu trono que o teu. E o rei adorou na cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'E também o rei falou assim: Bendito seja o SENHOR Deus de Israel, que deu hoje quem se sente em meu trono, vendo-o meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Eles então se estremeceram, e levantaram-se todos os convidados que estavam com Adonias, e foi-se cada um por seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Mas Adonias, temendo da presença de Salomão, levantou-se e foi-se, e agarrou as pontas do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'E foi feito saber a Salomão, dizendo: Eis que que Adonias tem medo do rei Salomão: pois agarrou as pontas do altar, dizendo: Jure-me hoje o rei Salomão que não matará à espada a seu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'E Salomão disse: Se ele for virtuoso, nenhum de seus cabelos cairá em terra: mas se se achar mal nele, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'E enviou o rei Salomão, e trouxeram-no do altar; e ele veio, e inclinou-se ao rei Salomão. E Salomão lhe disse: Vai-te à tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'E achegaram-se os dias de Davi para morrer, e mandou a Salomão seu filho, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Eu vou pelo caminho de toda a terra: esforça-te, e sê homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Guarda a ordenança do SENHOR teu Deus, andando em seus caminhos, e observando seus estatutos e mandamentos, e seus direitos e seus testemunhos, da maneira que está escrito na lei de Moisés, para que sejas bem-sucedido em tudo o que fizeres, e em tudo aquilo a que te voltares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Para que confirme o SENHOR a palavra que me falou, dizendo: Se teus filhos guardarem seu caminho, andando diante de mim com verdade, de todo seu coração, e de toda sua alma, jamais, disse, faltará a ti homem do trono de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'E já sabes tu o que me fez Joabe filho de Zeruia, o que fez a dois generais do exército de Israel, a Abner filho de Ner, e a Amasa filho de Jeter, os quais ele matou, derramando em paz o sangue de guerra, e pondo o sangue de guerra em seu cinto que tinha em sua cintura, e nos sapatos que tinha em seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tu pois farás conforme a tua sabedoria; não deixarás ele descer ao mundo dos mortos na velhice em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Mas aos filhos de Barzilai gileadita farás misericórdia, que sejam dos convidados a tua mesa; porque eles vieram assim a mim, quando ia fugindo de Absalão teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Também tens contigo a Simei filho de Gera, filho de Benjamim, de Baurim, o qual me amaldiçoou com uma maldição forte o dia que eu ia a Maanaim. Mas ele mesmo desceu a receber-me ao Jordão, e eu lhe jurei pelo SENHOR, dizendo: Eu não te matarei à espada');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Porém agora não o absolverás: que homem sábio és, e sabes como te hás de haver com ele: e farás descer suas cãs com sangue à sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'E Davi descansou com seus pais, e foi sepultado na cidade de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Os dias que reinou Davi sobre Israel foram quarenta anos: sete anos reinou em Hebrom, e trinta e três anos reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'E se sentou Salomão no trono de Davi seu pai, e foi seu reino firme em grande maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Então Adonias filho de Hagite veio a Bate-Seba mãe de Salomão; e ela disse: É tua vinda de paz? E ele respondeu: Sim, de paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Em seguida disse: Uma palavra tenho que te dizer. E ela disse: Dize.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'E ele disse: Tu sabes que o reino era meu, e que todo Israel havia posto em mim seu rosto, para que eu reinasse: mas o reino foi traspassado, e veio a meu irmão; porque pelo SENHOR era seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'E agora eu te faço uma petição: não a negues a mim. E ela lhe disse: Fala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Ele então disse: Eu te rogo que fales ao rei Salomão (porque ele não negará a ti), para que me dê a Abisague, a sunamita, por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'E Bate-Seba disse: Está bem; eu falarei por ti ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'E veio Bate-Seba ao rei Salomão para falar-lhe por Adonias. E o rei se levantou a recebê-la, e inclinou-se a ela, e voltou a sentar-se em seu trono, e fez pôr uma cadeira à mãe do rei, a qual se sentou à sua direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'E ela disse: Uma pequena petição pretendo de ti; não me negues. E o rei lhe disse: Pede, minha mãe, que eu não te negarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'E ela disse: Dê-se Abisague, a sunamita, por mulher a teu irmão Adonias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'E o rei Salomão respondeu, e disse a sua mãe: Por que pedes a Abisague sunamita para Adonias? Pede também para ele o reino, porque ele é meu irmão maior; e tem também a Abiatar sacerdote, e a Joabe filho de Zeruia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'E o rei Salomão jurou pelo SENHOR, dizendo: Assim me faça Deus e assim me acrescente, que contra sua vida falou Adonias esta palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Agora, pois, vive o SENHOR, que me confirmou e me pôs sobre o trono de Davi meu pai, e que me fez casa, como me havia dito, que Adonias morrerá hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Então o rei Salomão enviou por meio de Benaia filho de Joiada, o qual o golpeou de maneira que ele morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'E a Abiatar sacerdote disse o rei: Vai-te a Anatote a tuas propriedades, que tu és digno de morte; mas não te matarei hoje, porquanto levaste a arca do Senhor DEUS diante de Davi meu pai, e, além disso, foste aflito em todas as coisas em que meu pai foi aflito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Assim expulsou Salomão a Abiatar do sacerdócio do SENHOR, para que se cumprisse a palavra do SENHOR que havia dito sobre a casa de Eli em Siló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'E veio a notícia até Joabe: porque também Joabe se havia aderido a Adonias, se bem não se havia aderido a Absalão. E fugiu Joabe ao tabernáculo do SENHOR, e agarrou-se às pontas do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'E foi feito saber a Salomão que Joabe havia fugido ao tabernáculo do SENHOR, e que estava junto ao altar. Então enviou Salomão a Benaia filho de Joiada, dizendo: Vai, e golpeia-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'E entrou Benaia ao tabernáculo do SENHOR, e disse-lhe: O rei disse que saias. E ele disse: Não, mas sim aqui morrerei. E Benaia voltou com esta resposta ao rei, dizendo: Assim falou Joabe, e assim me respondeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'E o rei lhe disse: Faze como ele disse; mata-lhe e enterra-o, e tira de mim e da casa de meu pai o sangue que Joabe derramou injustamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'E o SENHOR fará voltar seu sangue sobre sua cabeça: que ele matou dois homens mais justos e melhores que ele, aos quais matou à espada sem que meu pai Davi soubesse nada: a Abner filho de Ner, general do exército de Israel, e a Amasa filho de Jeter, general do exército de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'O sangue deles, pois, recairá sobre a cabeça de Joabe, e sobre a cabeça de sua descendência para sempre: mas sobre Davi e sobre sua descendência, e sobre sua casa e sobre seu trono, haverá perpetuamente paz da parte do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Então Benaia filho de Joiada subiu, e o golpeou, e o matou; e foi sepultado em sua casa no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'E o rei pôs em seu lugar a Benaia filho de Joiada sobre o exército: e a Zadoque pôs o rei por sacerdote em lugar de Abiatar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Depois enviou o rei, e fez vir a Simei, e disse-lhe: Edifica-te uma casa em Jerusalém, e mora ali, e não saias de lá à uma parte nem à outra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Porque sabe de certo que o dia que saíres, e passares o ribeiro de Cedrom, sem dúvida morrerás, e teu sangue será sobre tua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'E Simei disse ao rei: A palavra é boa; como o rei meu senhor disse, assim o fará teu servo. E habitou Simei em Jerusalém muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Porém passados três anos, aconteceu que se lhe fugiram a Simei dois servos a Aquis, filho de Maaca, rei de Gate. E deram aviso a Simei, dizendo: Eis que teus servos estão em Gate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Levantou-se então Simei, e preparou seu asno, e foi a Gate, a Aquis, a procurar seus servos. Foi, pois, Simei, e voltou seus servos de Gate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Disse-se logo a Salomão como Simei havia ido de Jerusalém até Gate, e que havia voltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Então o rei enviou, e fez vir a Simei, e disse-lhe: Não te conjurei eu pelo SENHOR, e te protestei, dizendo: O dia que saíres, e fordes aqui ou acolá, sabe de certo que hás de morrer? E tu me disseste: A palavra é boa, eu a obedeço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Por que, pois, não guardaste o juramento do SENHOR, e o mandamento que eu te impus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Disse ademais o rei a Simei: Tu sabes todo o mal, o qual teu coração bem sabe que cometeste contra meu pai Davi; o SENHOR, pois, retribuiu o mal sobre a tua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'E o rei Salomão será bendito, e o trono de Davi será firme perpetuamente diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Então o rei mandou a Benaia filho de Joiada, o qual saiu e feriu-lhe; e morreu. E o reino foi confirmado na mão de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'E Salomão fez parentesco com Faraó rei do Egito, porque tomou a filha de Faraó, e trouxe-a à cidade de Davi, entre tanto que acabava de edificar sua casa, e a casa do SENHOR, e os muros de Jerusalém ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Até então o povo sacrificava nos altos; porque não havia casa edificada ao nome do SENHOR até aqueles tempos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Mas Salomão amou ao SENHOR, andando nos estatutos de seu pai Davi: somente sacrificava e queimava incenso nos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'E ia o rei a Gibeão, porque aquele era o alto principal, e Salomão sacrificava ali mil holocaustos sobre aquele altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'E apareceu o SENHOR a Salomão em Gibeão uma noite em sonhos, e disse lhe Deus: Pede o que quiseres que eu te dê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'E Salomão disse: Tu fizeste grande misericórdia a teu servo Davi meu pai, segundo que ele andou diante de ti em verdade, em justiça, e com retidão de coração para contigo: e tu lhe guardaste esta tua grande misericórdia, que lhe deste filho que se sentasse em seu trono, como sucede hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Agora, pois, SENHOR Deus meu, tu puseste a mim teu servo por rei em lugar de Davi meu pai: e eu sou jovem pequeno, que não sei como entrar nem sair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'E teu servo está em meio de teu povo ao qual tu escolheste; um povo grande, que não se pode contar nem numerar por sua multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Dá, pois a teu servo coração dócil para julgar a teu povo, para discernir entre o bom e o mau: porque quem poderá governar este teu povo tão grande?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'E agradou diante do Senhor que Salomão pedisse isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'E disse-lhe Deus: Porque pediste isto, e não pediste para ti muitos dias, nem pediste para ti riquezas, nem pediste a vida de teus inimigos, mas pediste para ti inteligência para ouvir juízo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Eis que o fiz conforme a tuas palavras: eis que te dei coração sábio e entendido, tanto que não haja havido antes de ti outro como tu, nem depois de ti se levantará outro como tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'E ainda também te dei as coisas que não pediste, riquezas e glória: tal, que entre os reis ninguém haja como tu em todos teus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'E se andares em meus caminhos, guardando meus estatutos e meus mandamentos, como andou Davi teu pai, eu alargarei teus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'E quando Salomão despertou, viu que era sonho: e veio a Jerusalém, e apresentou-se diante da arca do pacto do SENHOR, e sacrificou holocaustos, e fez ofertas pacíficas; fez também banquete a todos seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Naquela muita vieram duas mulheres prostitutas ao rei, e apresentaram-se diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'E disse a uma mulher: Ah, senhor meu! Eu e esta mulher morávamos em uma mesma casa, e eu pari estando com ela na casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'E aconteceu ao terceiro dia depois que eu dei à luz, que esta deu à luz também, e morávamos nós juntas; ninguém de fora estava em casa, a não ser nós duas na casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'E uma noite o filho desta mulher morreu, porque ela se deitou sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'E levantou-se à meia noite, e tomou a meu filho de junto a mim, estando eu tua serva dormindo, e o pôs a seu lado, e pôs a meu lado seu filho morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'E quando eu me levantei pela manhã para dar o peito a meu filho, eis que que estava morto: mas observei-lhe pela manhã, e vi que não era meu filho, que eu havia dado à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Então a outra mulher disse: Não; meu filho é o que vive, e teu filho é o morto. E a outra voltou a dizer: Não; teu filho é o morto, e meu filho é o que vive. Assim falavam diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'O rei então disse: Esta disse: Meu filho é o que vive, e teu filho é o morto: e a outra disse: Não, mas o teu é o morto, e meu filho é o que vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'E disse o rei: Trazei-me uma espada. E trouxeram ao rei uma espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Em seguida o rei disse: Parti por meio o menino vivo, e dai a metade à uma, e a outra metade à outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Então a mulher cujo era o filho vivo, falou ao rei (porque suas entranhas se lhe comoveram por seu filho), e disse: Ah, senhor meu! Dai a esta o menino vivo, e não o mateis. Mas a outra disse: nem a mim nem a ti; parti-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Então o rei respondeu, e disse: Dai a aquela o filho vivo, e não o mateis: ela é sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'E todo Israel ouviu aquele juízo que havia dado o rei: e temeram ao rei, porque viram que havia nele sabedoria de Deus para julgar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Foi, pois, o rei Salomão rei sobre todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'E estes foram os príncipes que teve: Azarias filho de Zadoque, sacerdote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Eliorefe e Aías, filhos de Sisa, escribas; Josafá filho de Ailude, chanceler;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaia filho de Joiada era sobre o exército; e Zadoque e Abiatar eram os sacerdotes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarias filho de Natã era sobre os governadores; Zabude filho de Natã era principal oficial, amigo do rei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'E Aisar era mordomo; e Adonirão filho de Abda era sobre o tributo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'E tinha Salomão doze governadores sobre todo Israel, os quais mantinham ao rei e à sua casa. Cada um deles estava obrigado a abastecer por um mês no ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'E estes são os nomes deles: Ben-Hur no monte de Efraim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Ben-Dequer, em Macaz, e em Saalbim, e em Bete-Semes, e em Elom-Bete-Hanã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ben-Hesede, em Arubote; este tinha também a Socó e toda a terra de Hefer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben-Abinadabe, em toda a região de Dor: este tinha por mulher a Tafate filha de Salomão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana filho de Ailude, em Taanaque e Megido, e em toda Bete-Seã, que é próxima de Zaretã, por abaixo de Jezreel, desde Bete-Seã até Abel-Meolá, e até a outra parte de Jocmeão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ben-Geber, em Ramote de Gileade; este tinha também as cidades de Jair filho de Manassés, as quais estavam em Gileade; tinha também a província de Argobe, que era em Basã, sessenta grandes cidades com muro e fechaduras de bronze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ainadabe filho de Ido, em Maanaim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Aimaás em Naftali; este tomou também por mulher a Basemate filha de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baaná filho de Husai, em Aser e em Alote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josafá filho de Parua, em Issacar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei filho de Elá, em Benjamim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber filho de Uri, na terra de Gileade, a terra de Seom rei dos amorreus, e de Ogue rei de Basã; este era o único governador naquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Judá e Israel eram muitos, como a areia que está junto ao mar em multidão, comendo e bebendo e alegrando-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'E Salomão senhoreava sobre todos os reinos, desde o rio da terra dos filisteus até o termo do Egito: e traziam presentes, e serviram a Salomão todos os dias que viveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'E a despensa de Salomão era cada dia trinta coros de farinha refinada, e sessenta coros de farinha comum;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Dez bois engordados, e vinte bois de pasto, e cem ovelhas; sem os cervos, cabras, búfalos, e aves engordadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Porque ele senhoreava em toda a região que estava da outra parte do rio, desde Tifsa até Gaza, sobre todos os reis da outra parte do rio; e teve paz por todos os lados em derredor seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'E Judá e Israel viviam seguros, cada um debaixo de sua parreira e debaixo de sua figueira, desde Dã até Berseba, todos os dias de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Tinha ademais disto Salomão quarenta mil cavalos em seus estábulos para seus carros, e doze mil cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'E estes governadores mantinham ao rei Salomão, e a todos os que à mesa do rei Salomão vinham, a cada mês; e faziam que nada faltasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Faziam também trazer cevada e palha para os cavalos e para os animais de carga, ao lugar de onde ele estava, cada um conforme ao cargo que tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'E deu Deus a Salomão sabedoria, e prudência muito grande, e largura de coração como a areia que está à beira do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Que foi maior a sabedoria de Salomão que a de todos os orientais, e que toda a sabedoria dos egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'E ainda foi mais sábio que todos os homens; mais que Etã ezraíta, e que Hemã e Calcol e Darda, filhos de Maol: e foi nomeado entre todas as nações de ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'E propôs três mil parábolas; e seus versos foram mil e cinco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Também descreveu as árvores, desde o cedro do Líbano até o hissopo que nasce na parede. Também descreveu os animais, as aves, os répteis, e os peixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'E vinham de todos os povos a ouvir a sabedoria de Salomão, e de todos os reis da terra, de onde havia chegado a fama de sua sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Hirão rei de Tiro enviou também seus servos a Salomão, logo que ouviu que o haviam ungido por rei em lugar de seu pai: porque Hirão havia sempre amado a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Então Salomão enviou a dizer a Hirão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Tu sabes como meu pai Davi não pôde edificar casa ao nome do SENHOR seu Deus, pelas guerras que lhe cercaram, até que o SENHOR pôs seus inimigos sob as plantas de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Agora o SENHOR meu Deus me deu repouso por todas as partes; que nem há adversários, nem mal encontro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Eu, portanto, determinei agora edificar casa ao nome do SENHOR meu Deus, como o SENHOR o falou a Davi meu pai, dizendo: Teu filho, que eu porei em lugar teu em teu trono, ele edificará casa a meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Manda, pois, agora que me cortem cedros do Líbano; e meus servos estarão com os teus, e eu te darei por teus servos o salário que tu disseres: porque tu sabes bem que ninguém há entre nós que saiba lavrar a madeira como os sidônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'E quando Hirão ouviu as palavras de Salomão, alegrou-se em grande maneira, e disse: Bendito seja hoje o SENHOR, que deu filho sábio a Davi sobre este povo tão grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'E enviou Hirão a dizer a Salomão: Ouvi o que me mandaste a dizer: eu farei tudo o que te satisfizer acerca da madeira de cedro, e a madeira de faia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Meus servos a levarão desde o Líbano à mar; e eu a porei em balsas pelo mar até o lugar que tu me assinalares, e ali se desatará, e tu a tomarás: e tu farás minha vontade em dar de comer à minha família.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Deu, pois, Hirão a Salomão madeira de cedro e madeira de faia tudo o que quis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'E Salomão dava a Hirão vinte mil coros de trigo para o sustento de sua família, e vinte coros de azeite limpo: isto dava Salomão a Hirão cada um ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Deu, pois, o SENHOR a Salomão sabedoria como lhe havia dito: e havia paz entre Hirão e Salomão, e fizeram aliança entre ambos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'E o rei Salomão impôs tributo a todo Israel, e o tributo foi de trinta mil homens:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Os quais enviava ao Líbano de dez mil em dez mil, cada mês por seu turno, vindo assim a estar um mês no Líbano, e dois meses em suas casas: e Adonirão estava sobre aquele tributo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Tinha também Salomão setenta mil que levavam as cargas, e oitenta mil cortadores no monte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Sem os principais oficiais de Salomão que estavam sobre a obra, três mil e trezentos, os quais tinham cargo do povo que fazia a obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'E mandou o rei que trouxessem grandes pedras, pedras de grande valor, para os alicerces da casa, e pedras lavradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'E os pedreiros de Salomão e os de Hirão, e os preparadores, cortaram e prepararam a madeira e pedras para lavrar a casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'E foi no ano quatrocentos oitenta depois que os filhos de Israel saíram do Egito, no quarto ano do princípio do reino de Salomão sobre Israel, no mês de Zife, que é o mês segundo, que ele começou a edificar a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'A casa que o rei Salomão edificou ao SENHOR, teve sessenta côvados de comprimento e vinte de largura, e trinta côvados de altura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'E o pórtico diante do templo da casa, de vinte côvados de comprimento, segundo a largura da casa, e sua largura era de dez côvados diante da casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'E fez à casa janelas largas por de dentro, e estreitas por de fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Edificou também junto ao muro da casa aposentos ao redor, contra as paredes da casa em derredor do templo e do compartimento interno: e fez câmaras ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'O aposento de abaixo era de cinco côvados de largura, e o de em meio de seis côvados de largura, e o terceiro de sete côvados de largura: porque por de fora havia feito apoios à casa em derredor, para não introduzir as vigas nas paredes da casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'E a casa quando se edificou, fabricaram-na de pedras que traziam já acabadas; de tal maneira que quando a edificavam, nem martelos nem machados se ouviram na casa, nem nenhum outro instrumento de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'A porta do aposento de em meio estava ao lado direito da casa: e subia-se por um caracol ao de em meio, e do aposento de em meio ao terceiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Lavrou, pois, a casa, e acabou-a; e cobriu a casa com artesanatos de cedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'E edificou também o aposento em derredor de toda a casa, de altura de cinco côvados, o qual se apoiava na casa com madeiras de cedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'E foi palavra do SENHOR a Salomão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Esta casa que tu edificas, se andares em meus estatutos, e fizeres meus direitos, e guardares todos meus mandamentos andando neles, eu terei firme contigo minha palavra que falei a Davi teu pai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'E habitarei em meio dos filhos de Israel, e não deixarei a meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Assim que, Salomão preparou a casa, e acabou-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'E preparou as paredes da casa por de dentro com tábuas de cedro, revestindo-a de madeira por dentro, desde o piso da casa até as paredes do teto: cobriu também o pavimento com madeira de faia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Também fez ao fim da casa um edifício de vinte côvados de tábuas de cedro, desde o piso até o mais alto; e fabricou-se na casa um compartimento interno, que é o lugar santíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'E a casa, a saber, o templo de dentro, tinha quarenta côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'E a casa estava coberta de cedro por de dentro, e tinha entalhaduras de frutos silvestres e de botões de flores. Todo era cedro; nenhuma pedra se via.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'E adornou o compartimento interno por de dentro no meio da casa, para pôr ali a arca do pacto do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'E o compartimento interno estava na parte de dentro, o qual tinha vinte côvados de comprimento, e outros vinte de largura, e outros vinte de altura; e revestiu-o de ouro puríssimo: também cobriu o altar de cedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'De sorte que revestiu Salomão de ouro puro a casa por de dentro, e fechou a entrada do compartimento interno com correntes de ouro, e revestiu-o de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Cobriu, pois, de ouro toda a casa até o fim; e também revestiu de ouro todo o altar que estava diante do compartimento interno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Fez também no compartimento interno dois querubins de madeira de oliva, cada um de altura de dez côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'A uma asa do querubim tinha cinco côvados, e a outra asa do querubim outros cinco côvados: assim que havia dez côvados desde a ponta da uma asa até a ponta da outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Também o outro querubim tinha dez côvados; porque ambos os querubins eram de um tamanho e de uma feitura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'A altura do um era de dez côvados, e também o outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'E pôs estes querubins dentro da casa de dentro: os quais querubins estendiam suas asas, de modo que a asa do um tocava à parede, e a asa do outro querubim tocava à outra parede, e as outras duas asas se tocavam a uma à outra na metade da casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'E revestiu de ouro os querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'E esculpiu todas as paredes da casa ao redor de diversas figuras, de querubins, de palmas, e de botões de flores, por de dentro e por de fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'E cobriu de ouro o piso da casa, de dentro e de fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'E à entrada do compartimento interno fez portas de madeira de oliva; e o umbral e os postes eram de cinco esquinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'As duas portas eram de madeira de oliva; e entalhou nelas figuras de querubins e de palmas e de botões de flores, e cobriu-as de ouro: cobriu também de ouro os querubins e as palmas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Igualmente fez à porta do templo postes de madeira de oliva quadrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Porém as duas portas eram de madeira de faia; e os dois lados da uma porta eram redondos, e os outros dois lados da outra porta também redondos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'E entalhou nelas querubins e palmas e botões de flores, e cobriu-as de ouro ajustado às entalhaduras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'E edificou o átrio interior de três ordens de pedras lavradas, e de uma ordem de vigas de cedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'No quarto ano, no mês de Zife, se lançaram os alicerces da casa do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'E no décimo primeiro ano, no mês de Bul, que é o mês oitavo, foi acabada a casa com todas seus partes, e com todo o necessário. Edificou-a, pois, em sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Depois edificou Salomão sua própria casa em treze anos, e acabou de construí-la toda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Também edificou a casa do bosque do Líbano, a qual tinha cinco côvados de comprimento, e cinquenta côvados de largura, e trinta côvados de altura, sobre quatro ordens de colunas de cedro, com vigas de cedro sobre as colunas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'E estava coberta de tábuas de cedro acima sobre as vigas, que se apoiavam em quarenta e cinco colunas: cada fileira tinha quinze colunas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'E havia três ordens de janelas, uma janela contra a outra em três ordens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'E todas as portas e postes eram quadrados: e as umas janelas estavam de frente às outras em três ordens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Também fez um pórtico de colunas, que tinha de comprimento cinquenta côvados, e trinta côvados de largura; e este pórtico estava diante daquelas outras, com suas colunas e vigas correspondentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Fez também o pórtico do trono em que havia de julgar, o pórtico do juízo, e revestiu-o de cedro do chão ao teto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'E na casa em que ele morava, havia outro átrio dentro do pórtico, de obra semelhante a esta. Edificou também Salomão uma casa para a filha de Faraó, que havia tomado por mulher, da mesma obra daquele pórtico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Todas aquelas obras foram de pedras de grande valor, cortadas e serradas com serras segundo as medidas, assim por de dentro como por de fora, desde o alicerce até os topos das paredes, e também por de fora até o grande átrio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'O alicerce era de pedras de grande valor, de pedras grandes, de pedras de dez côvados, e de pedras de oito côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'De ali acima eram também pedras de grande valor, lavradas conforme a suas medidas, e obra de cedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'E no grande átrio ao redor havia três ordens de pedras lavradas, e uma ordem de vigas de cedro: e assim o átrio interior da casa do SENHOR, e o átrio da casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'E enviou o rei Salomão, e fez vir de Tiro a Hirão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Filho de uma viúva da tribo de Naftali, e seu pai havia sido de Tiro: trabalhava ele em bronze, cheio de sabedoria e de inteligência e saber em toda obra de bronze. Este pois veio ao rei Salomão, e fez toda sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'E fundiu duas colunas de bronze, a altura de cada qual era de dezoito côvados: e rodeava a uma e a outra coluna um fio de doze côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Fez também dois capitéis de fundição de bronze, para que fossem postos sobre as cabeças das colunas: a altura de um capitel era de cinco côvados, e a do outro capitel de cinco côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Havia trançados à maneira de redes, e grinaldas à maneira de correntes, para os capitéis que se haviam de pôr sobre as cabeças das colunas: sete para cada capitel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'E quando havia feito as colunas, fez também duas ordens de romãs ao redor no um enredado, para cobrir os capitéis que estavam nas cabeças das colunas com as romãs: e da mesma forma fez no outro capitel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Os capitéis que estavam sobre as colunas no pórtico, tinham trabalho de flores por quatro côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Tinham também os capitéis de sobre as duas colunas, duzentas romãs em duas ordens ao redor em cada capitel, encima da parte arredondada do capitel, o qual estava diante do trançado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Estas colunas ele erigiu no pórtico do templo: e quando havia levantado a coluna da direita, pôs-lhe por nome Jaquim: e levantando a coluna da esquerda, chamou seu nome Boaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'E pôs nas cabeças das colunas trabalho em forma de açucenas; e assim se acabou a obra das colunas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Fez também um mar de fundição, de dez côvados do um lado ao outro, redondo; sua altura era de cinco côvados, e cingia-o ao redor um cordão de trinta côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'E cercavam aquele mar por debaixo de sua borda em derredor umas bolas como frutos, dez em cada côvado, que cingiam o mar ao redor em duas ordens, as quais haviam sido fundidas quando ele foi fundido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'E estava assentado sobre doze bois: três estavam voltados ao norte, e três estavam voltados ao ocidente, e três estavam voltados ao sul, e três estavam voltados ao oriente; sobre estes se apoiava o mar, e as traseiras deles estavam até a parte de dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'A espessura do mar era de um palmo, e sua borda era lavrada como a borda de um cálice, ou de flor de lírio: e cabiam nele dois mil batos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Fez também dez bases de bronze, sendo o comprimento de cada base de quatro côvados, e a largura de quatro côvados, e de três côvados a altura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'A obra das bases era esta: tinham uns painéis, as quais estavam entre molduras:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'E sobre aqueles painéis que estavam entre as molduras, figuras de leões, e de bois, e de querubins; e sobre as molduras da base, assim encima como debaixo dos leões e dos bois, havia uns acréscimos de baixo-relevo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Cada base tinha quatro rodas de bronze com mesas de bronze; e em seus quatro eixos havia uns apoios, os quais haviam sido fundidos a cada lado com grinaldas, para estarem debaixo da fonte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'E a abertura da bacia era de um côvado no suporte que saía para acima da base; e era sua abertura redonda, da feitura do mesmo suporte, e este de côvado e meio. Havia também sobre a abertura entalhes em seus painéis, que eram quadrados, não redondas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'As quatro rodas estavam debaixo dos painéis, e os eixos das rodas estavam na mesma base. A altura de cada roda era de um côvado e meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'E a feitura das rodas era como a feitura das rodas de um carro: seus eixos, seus raios, e seus cubos, e seus aros, tudo era de fundição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Também os quatro apoios às quatro esquinas de cada base: e os apoios eram da mesma base.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'E no alto da base havia meio côvado de altura redondo por todas partes: e encima da base suas molduras e painéis, as quais eram dela mesma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'E fez nas tábuas das molduras, e nas cintas, entalhaduras de querubins, e de leões, e de palmas, com proporção no espaço de cada uma, e ao redor outros adornos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'De esta forma fez dez bases fundidas de uma mesma maneira, de uma mesma medida, e de uma mesma entalhadura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Fez também dez fontes de bronze: cada fonte continha quarenta batos, e cada uma era de quatro côvados; e assentou uma fonte sobre cada uma das dez bases.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'E pôs as cinco bases à direita da casa, e as outras cinco à esquerda: e assentou o mar ao lado direito da casa, ao oriente, até o sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Também fez Hirão fontes, e tenazes, e bacias. Assim acabou toda a obra que fez a Salomão para a casa do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'A saber, duas colunas, e os vasos redondos dos capitéis que estavam no alto das duas colunas; e duas redes que cobriam os dois vasos redondos dos capitéis que estavam sobre a cabeça das colunas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'E quatrocentas romãs para as duas redes, duas ordens de romãs em cada rede, para cobrir os dois vasos redondos que estavam sobre as cabeças das colunas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'E as dez bases, e as dez fontes sobre as bases;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'E um mar, e doze bois debaixo do mar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'E caldeiras, e pás, e bacias; e todos os vasos que Hirão fez ao rei Salomão, para a casa do SENHOR de bronze polido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Todo o fez fundir o rei na planície do Jordão, em terra argilosa, entre Sucote e Zaretã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'E deixou Salomão sem inquirir o peso do bronze de todos os vasos, pela grande abundância deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Então fez Salomão todos os vasos que pertenciam à casa do SENHOR: um altar de ouro, e uma mesa sobre a qual estavam os pães da proposição, também de ouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'E cinco candelabros de ouro puríssimo à direita, e outros cinco à esquerda, diante do oráculo; com as flores, e as lâmpadas, e tenazes de ouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Também os cântaros, vasos, bacias, colheres, e incensários, de ouro puríssimo; também de ouro as dobradiças das portas da casa de dentro, do lugar santíssimo, e os das portas do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Assim se acabou toda a obra que dispôs fazer o rei Salomão para a casa do SENHOR. E meteu Salomão o que Davi seu pai havia dedicado, é a saber, prata, e ouro, e vasos, e o pôs tudo em guarda nas tesourarias da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Então juntou Salomão os anciãos de Israel, e a todos os chefes das tribos, e aos príncipes das famílias dos filhos de Israel, ao rei Salomão em Jerusalém para trazer a arca do pacto do SENHOR da cidade de Davi, que é Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'E se juntaram ao rei Salomão todos os homens de Israel no mês de Etanim, que é o mês sétimo, no dia solene.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'E vieram todos os anciãos de Israel, e os sacerdotes tomaram a arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'E levaram a arca do SENHOR, e o tabernáculo do testemunho, e todos os vasos sagrados que estavam no tabernáculo; os quais levavam os sacerdotes e levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'E o rei Salomão, e toda a congregação de Israel que a ele se havia juntado, estavam com ele diante da arca, sacrificando ovelhas e bois, que pela abundância não se podiam contar nem numerar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'E os sacerdotes puseram a arca do pacto do SENHOR em seu lugar, no oráculo da casa, no lugar santíssimo, debaixo das asas dos querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Porque os querubins tinham estendidas as asas sobre o lugar da arca, e assim cobriam os querubins a arca e suas varas por encima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'E fizeram sair as varas, de maneira que as extremidades das varas podiam ser vistas desde o santuário diante do compartimento interno, mas não se viam desde fora: e assim ficaram até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Na arca nenhuma coisa havia mais das duas tábuas de pedra que havia ali posto Moisés em Horebe, de onde o SENHOR fez a aliança com os filhos de Israel, quando saíram da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'E quando os sacerdotes saíram do santuário, a nuvem encheu a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'E os sacerdotes não puderam estar para ministrar por causa da nuvem; porque a glória do SENHOR havia enchido a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Então disse Salomão: o SENHOR disse que ele habitaria na escuridão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Eu edifiquei casa por morada para ti, assento em que tu habites para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'E virando o rei seu rosto, abençoou a toda a congregação de Israel; e toda a congregação de Israel estava em pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'E disse: Bendito seja o SENHOR Deus de Israel, que falou de sua boca a Davi meu pai, e com sua mão o cumpriu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Desde o dia que tirei meu povo Israel do Egito, não escolhi cidade de todas as tribos de Israel para edificar casa na qual estivesse meu nome, ainda que escolhi a Davi para que presidisse em meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'E Davi meu pai teve no coração edificar casa ao nome do SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Mas o SENHOR disse a Davi meu pai: Quanto a haver tu tido no coração edificar casa a meu nome, bem fizeste em ter tal vontade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Porém tu não edificarás a casa, mas sim teu filho que sairá de teus lombos, ele edificará casa a meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'E o SENHOR verificou sua palavra que havia dito; que me levantei eu em lugar de Davi meu pai, e sentei-me no trono de Israel, como o SENHOR havia dito, e edifiquei a casa ao nome do SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'E pus nela lugar para a arca, na qual está o pacto do SENHOR, que ele fez com nossos pais quando os tirou da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Pôs-se logo Salomão diante do altar do SENHOR, em presença de toda a congregação de Israel, e estendendo suas mãos ao céu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Disse: o SENHOR Deus de Israel, não há Deus como tu, nem acima nos céus nem abaixo na terra, que guardas o pacto e a misericórdia a teus servos, os que andam diante de ti de todo seu coração;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Que guardaste a teu servo Davi meu pai o que lhe disseste: disseste-o com tua boca, e com tua mão o cumpriste, como aparece este dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Agora, pois, SENHOR Deus de Israel, cumpre a teu servo Davi meu pai o que lhe prometeste, dizendo: Não faltará homem de ti diante de mim, que se sente no trono de Israel, com tal que teus filhos guardem seu caminho, que andem diante de mim como tu tens andado diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Agora, pois, ó Deus de Israel, verifique-se tua palavra que disseste a teu servo Davi meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Porém é verdade que Deus haja de morar sobre a terra? Eis que os céus, os céus dos céus, não te podem conter: quanto menos esta casa que eu edifiquei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Contudo, tu atenderás à oração de teu servo, e a sua súplica, ó SENHOR Deus meu, ouvindo propício o clamor e oração que teu servo faz hoje diante de ti:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Que estejam teus olhos abertos de noite e de dia sobre esta casa, sobre este lugar do qual disseste: Meu nome estará ali; e que ouças a oração que teu servo fará neste lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Ouve, pois a oração de teu servo, e de teu povo Israel; quando orarem em este lugar, também tu o ouvirás no lugar de tua habitação, desde os céus: que ouças e perdoes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Quando alguém houver pecado contra seu próximo, e lhe tomarem juramento fazendo-lhe jurar, e vier o juramento diante de teu altar em esta casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Tu ouvirás desde o céu, e operarás, e julgarás a teus servos, condenando ao ímpio, tornando seu proceder sobre sua cabeça, e justificando ao justo para dar-lhe conforme a sua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Quando teu povo Israel houver caído diante de seus inimigos, por haver pecado contra ti, e a ti se voltarem, e confessarem teu nome, e orarem, e te rogarem e suplicarem nesta casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Ouve-os tu nos céus, e perdoa o pecado de teu povo Israel, e traze-os de volta à terra que deste a seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Quando o céu se fechar, e não chover, por haver eles pecado contra ti, e te rogarem em este lugar, e confessarem teu nome, e se converterem do pecado, quando os houveres afligido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Tu ouvirás nos céus, e perdoarás o pecado de teus servos e de teu povo Israel, ensinando-lhes o bom caminho em que andem; e darás chuvas sobre tua terra, a qual deste a teu povo por herdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Quando na terra houver fome, ou pestilência, ou ferrugem, ou mofo, ou locusta, ou pulgão: se seus inimigos os tiverem cercados na terra de seu domicílio; qualquer praga ou enfermidade que seja;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Toda oração e toda súplica que fizer qualquer homem, ou todo teu povo Israel, quando qualquer um sentir a praga de seu coração, e estender suas mãos a esta casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Tu ouvirás nos céus, na habitação de tua morada, e perdoarás, e operarás, e darás a cada um conforme a seus caminhos, cujo coração tu conheces; (porque somente tu conheces o coração de todos os filhos dos homens;)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Para que te temam todos os dias que viverem sobre a face da terra que tu deste a nossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Também o estrangeiro, que não é de teu povo Israel, que houver vindo de distantes terras a causa de teu nome,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Porque ouvirão de teu grande nome, e de tua mão forte, e de teu braço estendido,) e vier a orar a esta casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Tu ouvirás nos céus, na habitação de tua morada, e farás conforme a todo aquilo pelo qual o estrangeiro houver a ti clamado: para que todos os povos da terra conheçam teu nome, e te temam, como teu povo Israel, e entendam que o teu nome é invocado sobre esta casa que eu edifiquei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Se teu povo sair em batalha contra seus inimigos pelo caminho que tu os enviares, e orarem ao SENHOR até a cidade que tu escolheste, e até a casa que eu edifiquei a teu nome,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Tu ouvirás nos céus sua oração e sua súplica, e lhes farás direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Se houverem pecado contra ti, (porque não há homem que não peque) e tu estiveres irado contra eles, e os entregares diante do inimigo, para que os prendam e levem a terra inimiga, seja longe ou próxima,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'E eles converterem em si na terra de onde forem cativos; se se converterem, e orarem a ti na terra dos que os prenderam, e disserem: Pecamos, fizemos o mau, cometemos impiedade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'E se se converterem a ti de todo seu coração e de toda sua alma, na terra de seus inimigos que os houverem levado cativos, e orarem a ti até sua terra, que tu deste a seus pais, até a cidade que tu escolheste e a casa que eu edifiquei a teu nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Tu ouvirás nos céus, na habitação de tua morada, sua oração e sua súplica, e lhes farás direito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'E perdoarás a teu povo que havia pecado contra ti, e todas suas infrações com que se houverem contra ti rebelado; e farás que tenham deles misericórdia os que os houverem levado cativos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Porque eles são teu povo e tua propriedade, que tu tiraste do Egito, de em meio do forno de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Que teus olhos estejam abertos à oração de teu servo, e à súplica de teu povo Israel, para ouvi-los em tudo aquilo pelo que te invocarem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Pois que tu os separaste para ti por tua propriedade de todos os povos da terra, como o disseste por meio de Moisés teu servo, quando tiraste a nossos pais do Egito, ó Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'E foi, que quando acabou Salomão de fazer ao SENHOR toda esta oração e súplica, levantou-se de estar de joelhos diante do altar do SENHOR com suas mãos estendidas ao céu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'E posto em pé, abençoou a toda a congregação de Israel, dizendo em voz alta:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Bendito seja o SENHOR, que deu repouso a seu povo Israel, conforme a tudo o que ele havia dito; nenhuma palavra faltou de todas suas promessas que expressou por Moisés seu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Seja com nós o SENHOR nosso Deus, como foi com nossos pais; e não nos desampare, nem nos deixe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Incline nosso coração a ele, para que andemos em todos os seus caminhos, e guardemos seus mandamentos e seus estatutos e seus direitos, os quais ele mandou a nossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'E que estas minhas palavras com que orei diante do SENHOR estejam próximas do SENHOR nosso Deus de dia e de noite, para que ele proteja a causa de seu servo, e de seu povo Israel, cada coisa em seu tempo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'A fim de que todos os povos da terra saibam que o SENHOR é Deus, e que não há outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Seja, pois, o vosso coração completo com o SENHOR nosso Deus, andando em seus estatutos, e guardando seus mandamentos, como o dia de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Então o rei, e todo Israel com ele, sacrificaram vítimas diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'E sacrificou Salomão por sacrifícios pacíficos, os quais ofereceu ao SENHOR vinte e dois mil bois, e cento vinte mil ovelhas. Assim dedicaram o rei e todos os filhos de Israel a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Aquele mesmo dia santificou o rei o meio do átrio que estava diante da casa do SENHOR: porque ofereceu ali os holocaustos, e os presentes, e a gordura das ofertas pacíficas; porquanto o altar de bronze que estava diante do SENHOR era pequeno, e não couberam nele os holocaustos, os presentes, e a gordura das ofertas pacíficas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Naquele tempo Salomão fez festa, e com ele todo Israel, uma grande congregação, desde como entram em Hamate até o rio do Egito, diante do SENHOR nosso Deus, por sete dias e outros sete dias, isto é, por catorze dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'E o oitavo dia despediu ao povo: e eles bendizendo ao rei, se foram a suas moradas alegres e jubilosos de coração por todos os benefícios que o SENHOR havia feito a Davi seu servo, e a seu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'E quando Salomão havia acabado a obra da casa do SENHOR, e a casa real, e tudo o que Salomão quis fazer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'o SENHOR apareceu a Salomão a segunda vez, como lhe havia aparecido em Gibeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'E disse-lhe o SENHOR: Eu ouvido tua oração e teu rogo, que fizeste em minha presença. Eu santifiquei esta casa que tu hás edificado, para pôr meu nome nela para sempre; e nela estarão meus olhos e meu coração todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'E se tu andares diante de mim, como andou Davi teu pai, em integridade de coração e em equidade, fazendo todas as coisas que eu te ei mandado, e guardando meus estatutos e meus direitos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Eu afirmarei o trono de teu reino sobre Israel para sempre, como falei a Davi teu pai, dizendo: Não faltará de ti homem no trono de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mas se obstinadamente vos apartardes de mim vós e vossos filhos, e não guardardes meus mandamentos e meus estatutos que eu pus diante de vós, mas sim que fordes e servirdes a deuses alheios, e os adorardes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Eu cortarei a Israel de sobre a face da terra que lhes entreguei; e esta casa que santifiquei a meu nome, eu a lançarei de diante de mim, e Israel será por provérbio e fábula a todos os povos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'E esta casa que estava em estima, qualquer um que passar por ela se pasmará, e assoviará, e dirá: Por que fez assim o SENHOR a esta terra, e a esta casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'E dirão: Porquanto deixaram ao SENHOR seu Deus, que havia tirado a seus pais da terra do Egito, e lançaram mão a deuses alheios, e os adoraram, e os serviram: por isso trouxe o SENHOR sobre eles todo este mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'E aconteceu ao fim de vinte anos, em que Salomão havia edificado as duas casas, a casa do SENHOR e a casa real,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '(Para as quais Hirão rei de Tiro, havia trazido a Salomão madeira de cedro e de faia, e quanto ouro ele quis), que o rei Salomão deu a Hirão vinte cidades em terra de Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'E saiu Hirão de Tiro para ver as cidades que Salomão lhe havia dado, e não lhe contentaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'E disse: Que cidades são estas que me deste, irmão? E pôs-lhes por nome, a terra de Cabul, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'E havia Hirão enviado ao rei cento e vinte talentos de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'E esta é a razão do tributo que o rei Salomão impôs para edificar a casa do SENHOR, e sua casa, e a Milo, e o muro de Jerusalém, e a Hazor, e Megido, e Gezer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Faraó o rei do Egito havia subido e tomado a Gezer, e queimado-a, e havia morto os cananeus que habitavam a cidade, e dado-a em presente à sua filha a mulher de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Restaurou, pois Salomão a Gezer, e à baixa Bete-Horom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'E a Baalate, e a Tadmor em terra do deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'Também todas as cidades de onde Salomão tinha armazéns, e as cidades dos carros, e as cidades de cavaleiros, e tudo o que Salomão desejou edificar em Jerusalém, no Líbano, e em toda a terra de seu senhorio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'A todos os povos que restaram dos amorreus, heteus, perizeus, heveus, jebuseus, que não foram dos filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'A seus filhos que restaram na terra depois deles, que os filhos de Israel não puderam acabar, fez Salomão que servissem com tributo até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Mas a ninguém dos filhos de Israel impôs Salomão serviço, mas sim que eram homens de guerra, ou seus criados, ou seus príncipes, ou seus capitães, ou comandantes de seus carros, ou sua cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'E os que Salomão havia feito chefes e líderes sobre as obras, eram quinhentos e cinquenta, os quais estavam sobre o povo que trabalhava naquela obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'E subiu a filha de Faraó da cidade de Davi a sua casa que Salomão lhe havia edificado: então edificou ele a Milo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'E oferecia Salomão três vezes cada um ano holocaustos e pacíficos sobre o altar que ele edificou ao SENHOR, e queimava incenso sobre o que estava diante do SENHOR, depois que a casa foi acabada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Fez também o rei Salomão navios em Eziom-Geber, que é junto a Elate na beira do mar Vermelho, na terra de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'E enviou Hirão neles a seus servos, marinheiros e destros no mar, com os servos de Salomão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Os quais foram a Ofir, e tomaram dali ouro, quatrocentos e vinte talentos, e trouxeram-no ao rei Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'E ouvindo a rainha de Sabá a fama de Salomão no nome do SENHOR, veio a provar-lhe com perguntas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'E veio a Jerusalém com muito grande comitiva, com camelos carregados de especiarias, e ouro em grande abundância, e pedras preciosas: e quando veio a Salomão, propôs-lhe todo o que em seu coração tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'E Salomão lhe declarou todas suas palavras: nenhuma coisa se lhe escondeu ao rei, que não lhe declarasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'E quando a rainha de Sabá viu toda a sabedoria de Salomão, e a casa que havia edificado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Também a comida de sua mesa, o assento de seus servos, o estado e roupas dos que lhe serviam, seus mestres-salas, e seus holocaustos que sacrificava na casa do SENHOR, ficou pasma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'E disse ao rei: Verdade é o que ouvi em minha terra de tuas coisas e de tua sabedoria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Mas eu não o cria, até que vim, e meus olhos viram, que nem ainda a metade foi o que se me disse: é maior tua sabedoria e bem que a fama que eu havia ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Bem-aventurados teus homens, ditosos estes teus servos, que estão continuamente diante de ti, e ouvem tua sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'o SENHOR teu Deus seja bendito, que se agradou de ti para te pôr no trono de Israel; porque o SENHOR amou sempre a Israel, e te pôs por rei, para que faças direito e justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'E deu ela ao rei cento e vinte talentos de ouro, e muita especiaria, e pedras preciosas: nunca veio tão grande quantidade de especiarias, como a rainha de Sabá deu ao rei Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'A frota de Hirão que havia trazido o ouro de Ofir, trazia também de Ofir muita madeira de sândalo, e pedras preciosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'E da madeira de sândalo fez o rei balaústres para a casa do SENHOR, e para as casas reais, harpas também e saltérios para os cantores: nunca veio tanta madeira de sândalo, nem se há visto até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'E o rei Salomão deu à rainha de Sabá tudo o que quis, e tudo o que pediu, ademais do que Salomão lhe deu como da mão do rei Salomão. E ela se voltou, e se foi a sua terra com seus criados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'O peso do ouro que Salomão tinha de renda cada um ano era seiscentos sessenta e seis talentos de ouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Sem o dos mercadores, e da contratação de especiarias, e de todos os reis de Arábia, e dos principais da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Fez também o rei Salomão duzentos paveses de ouro estendido: seiscentos siclos de ouro gastou em cada pavês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Também trezentos escudos de ouro estendido, em cada um dos quais gastou três libras de ouro: e os pôs o rei na casa do bosque do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Fez também o rei um grande trono de marfim, o qual cobriu de ouro puríssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Seis degraus tinha o trono, e o alto dele era redondo pelo recosto: e da uma parte e da outra tinha apoios próximo do assento, junto aos quais estavam colocados dois leões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Estavam também doze leões postos ali sobre os seis degraus, da uma parte e da outra: em nenhum outro reino se havia feito trono semelhante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'E todos os vasos de beber do rei Salomão eram de ouro, e também toda a vasilha da casa do bosque do Líbano era de ouro fino: não havia prata; em tempo de Salomão não era de valor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Porque o rei tinha a frota que saía à mar, a Társis, com a frota de Hirão: uma vez em cada três anos vinha a frota de Társis, e trazia ouro, prata, marfim, macacos e pavões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Assim excedia o rei Salomão a todos os reis da terra em riquezas e em sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Toda a terra procurava ver a cara de Salomão, para ouvir sua sabedoria, a qual Deus havia posto em seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'E todos lhe levavam cada ano seus presentes: vasos de ouro, vasos de prata, roupas, armas, aromas, cavalos e mulas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'E juntou Salomão carros e cavaleiros; e tinha mil quatrocentos carros, e doze mil cavaleiros, os quais pôs nas cidades dos carros, e com o rei em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'E pôs o rei em Jerusalém prata como pedras, e cedros como os sicômoros que estão pelos campos em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'E traziam cavalos a Salomão do Egito e de Coa: porque os mercadores do rei compravam cavalos de Coa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'E vinha e saía do Egito, o carro por seiscentas peças de prata, e o cavalo por cento e cinquenta; e assim os traziam por meio deles, todos os reis dos heteus, e da Síria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Porém o rei Salomão amou, além da filha de Faraó, muitas mulheres estrangeiras: às de Moabe, às de Amom, às de Edom, às de Sidom, e às heteias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Nações das quais o SENHOR havia dito aos filhos de Israel: Não entrareis a elas, nem elas entrarão a vós; porque certamente farão inclinar vossos corações atrás seus deuses. A estas, pois, juntou-se Salomão com amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'E teve setecentas esposas princesas, e trezentas concubinas; e suas mulheres desviaram o coração dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'E aconteceu que, na velhice de Salomão, suas mulheres inclinaram o seu coração para seguir outros deuses; e o coração dele não era completo com o SENHOR seu Deus, como o coração do seu pai Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Porque Salomão seguiu Astarote, deusa dos sidônios, e a Milcom, abominação dos amonitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'E fez Salomão o que era mau aos olhos do SENHOR, e não seguiu completamente o SENHOR como o seu pai Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Então edificou Salomão um alto a Camos, abominação de Moabe, no monte que está à frente de Jerusalém; e a Moloque, abominação dos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'E assim fez para todas suas mulheres estrangeiras, as quais queimavam incenso, e sacrificavam aos seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'E o SENHOR se irou contra Salomão, pois o seu coração estava desviado do SENHOR Deus de Israel, que lhe havia aparecido duas vezes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'E lhe havia mandado acerca disto, que não seguisse outros deuses; mas ele não guardou o que o SENHOR havia lhe mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'E disse o SENHOR a Salomão: Como houve isso em ti, e não guardaste o meu pacto e os meus estatutos que eu te mandei, romperei o reino de ti, e o entregarei a teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Porém não o farei em teus dias, por amor de Davi teu pai; eu o romperei da mão de teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Todavia não romperei todo o reino, mas sim que darei uma tribo a teu filho, por amor de Davi meu servo, e por amor de Jerusalém que eu escolhi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'E o SENHOR suscitou um adversário a Salomão, a Hadade, edomita, do sangue real, o qual estava em Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Porque quando Davi estava em Edom, e subiu Joabe o general do exército a enterrar os mortos, e matou a todos os homens de Edom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(Porque seis meses habitou ali Joabe, e todo Israel, até que havia acabado a todo o sexo masculino em Edom;)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Então fugiu Hadade, e com ele alguns homens edomitas dos servos de seu pai, e foi-se ao Egito; era então Hadade jovem pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'E levantaram-se de Midiã, e vieram a Parã; e tomando consigo homens de Parã, vieram-se ao Egito, a Faraó rei do Egito, o qual lhe deu casa, e lhe assinalou alimentos, e ainda lhe deu terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'E achou Hadade grande graça diante de Faraó, o qual lhe deu por mulher à irmã de sua esposa, à irmã da rainha Tafnes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'E a irmã de Tafnes lhe deu à luz seu filho Genubate, ao qual Tafnes desmamou dentro da casa de Faraó; e estava Genubate na casa de Faraó entre os filhos de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'E ouvindo Hadade em Egito que Davi havia dormido com seus pais, e que era morto Joabe general do exército, Hadade disse a Faraó: Deixa-me ir a minha terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'E respondeu-lhe Faraó: Por que? O que te falta comigo, que procuras ir-te a tua terra? E ele respondeu: Nada; contudo, rogo-te que me deixes ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Despertou-lhe também Deus por adversário a Rezom, filho de Eliada, o qual havia fugído de seu amo Hadadezer, rei de Zobá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'E havia juntado gente contra ele, e havia-se feito capitão de uma companhia, quando Davi derrotou aos de Zobá. Depois se foram a Damasco, e habitaram ali e fizeram-lhe rei em Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'E foi adversário a Israel todos os dias de Salomão; e foi outro mal com o de Hadade, porque aborreceu a Israel, e reinou sobre a Síria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Também Jeroboão filho de Nebate, efrateu de Zeredá, servo de Salomão, (sua mãe se chamava Zerua, mulher viúva) levantou sua mão contra o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'E a causa por que este levantou mão contra o rei, foi esta: Salomão edificando a Milo, fechou a abertura da cidade de Davi seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'E o homem Jeroboão era valente e esforçado; e vendo Salomão ao rapaz que era homem ativo, encomendou-lhe todo o cargo da casa de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Aconteceu pois naquele tempo, que saindo Jeroboão de Jerusalém, encontrou-lhe no caminho o profeta Aías silonita; e ele estava coberto com uma capa nova; e estavam eles dois sós no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'E segurando Aías da capa nova que tinha sobre si, rompeu-a em doze pedaços,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'E disse a Jeroboão: Toma para ti os dez pedaços; porque assim disse o SENHOR Deus de Israel: Eis que que eu rompo o reino da mão de Salomão, e a ti darei dez tribos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(E ele terá uma tribo, por amor de Davi meu servo, e por amor de Jerusalém, cidade que eu escolhi de todas as tribos de Israel:)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Porquanto me deixaram, e adoraram a Astarote deusa dos sidônios, e a Camos deus de Moabe, e a Moloque deus dos filhos de Amom; e não andaram em meus caminhos, para fazer o reto diante de meus olhos, e meus estatutos, e meus direitos, como fez seu pai Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Porém não tirarei nada de seu reino de suas mãos, mas sim que o manterei por chefe todos os dias de sua vida, por amor de Davi meu servo, ao qual eu escolhi, e ele guardou meus mandamentos e meus estatutos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mas eu tirarei o reino da mão de seu filho, e o darei a ti, as dez tribos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'E a seu filho darei uma tribo, para que meu servo Davi tenha lâmpada todos os dias diante de mim em Jerusalém, cidade que eu me escolhi para pôr nela meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Eu pois te tomarei a ti, e tu reinarás em todas as coisas que desejar tua alma, e serás rei sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'E será que, se prestares ouvido a todas as coisas que te mandar, e andares em meus caminhos, e fizeres o reto diante de meus olhos, guardando meus estatutos e meus mandamentos, como fez Davi meu servo, eu serei contigo, e te edificarei casa firme, como a edifiquei a Davi, e eu te entregarei a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'E eu afligirei a semente de Davi por causa disto, mas não para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Procurou, portanto, Salomão de matar a Jeroboão, mas levantando-se Jeroboão, fugiu ao Egito, a Sisaque rei do Egito, e esteve em Egito até a morte de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Os demais dos feitos de Salomão, e todas as coisas que fez, e sua sabedoria, não estão escritas no livro dos feitos de Salomão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'E os dias que Salomão reinou em Jerusalém sobre todo Israel foram quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'E descansou Salomão com seus pais, e foi sepultado na cidade de seu pai Davi: e reinou em seu lugar Roboão seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'E foi Roboão a Siquém; porque todo Israel havia vindo a Siquém para fazê-lo rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'E aconteceu, que quando o ouviu Jeroboão filho de Nebate, que estava em Egito, porque havia fugido de diante do rei Salomão, e habitava em Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Enviaram e chamaram-lhe. Veio pois Jeroboão e toda a congregação de Israel, e falaram a Roboão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Teu pai agravou nosso jugo, mas agora tu diminui algo da dura servidão de teu pai, e do jugo pesado que ele pôs sobre nós, e te serviremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'E ele lhes disse: Ide, e daqui a três dias voltai a mim. E o povo se foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Então o rei Roboão tomou conselho com os anciãos que haviam estado diante de Salomão seu pai quando vivia, e disse: Como aconselhais vós que responda a este povo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'E eles lhe falaram, dizendo: Se tu fores hoje servo deste povo, e o servires, e respondendo-lhe boas palavras lhes falares, eles te servirão para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mas ele, deixado o conselho dos anciãos que eles lhe haviam dado, tomou conselho com os rapazes que se haviam criado com ele, e estavam diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'E disse-lhes: Como aconselhais vós que respondamos a este povo, que me falou, dizendo: Diminui algo do jugo que teu pai pôs sobre nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Então os rapazes que se haviam criado com ele lhe responderam, dizendo: Assim falarás a este povo que te disse estas palavras: Teu pai agravou nosso jugo; mas tu diminui-nos algo: assim lhes falarás: O menor dedo dos meus é mais espesso que os lombos de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Agora, pois, meu pai vos impôs carga de pesado jugo, mas eu acrescentarei a vosso jugo; meu pai vos feriu com açoites, mas eu vos ferirei com escorpiões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'E ao terceiro dia veio Jeroboão com todo o povo a Roboão; segundo o rei o havia mandado, dizendo: Voltai a mim ao terceiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'E o rei respondeu ao povo duramente, deixado o conselho dos anciãos que eles lhe haviam dado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'E falou-lhes conforme ao conselho dos rapazes, dizendo: Meu pai agravou vosso jugo, mas eu acrescentarei a vosso jugo; meu pai vos feriu com açoites, mas eu vos ferirei com escorpiões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'E não ouviu o rei ao povo; porque era ordenação do SENHOR, para confirmar sua palavra, que o SENHOR havia falado por meio de Aías silonita a Jeroboão filho de Nebate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'E quando todo o povo viu que o rei não lhes havia ouvido, respondeu-lhe estas palavras, dizendo: Que parte temos nós com Davi? Não temos propriedade no filho de Jessé. Israel, a tuas moradas! Provê agora em tua casa, Davi! Então Israel se foi a suas moradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Mas reinou Roboão sobre os filhos de Israel que moravam nas cidades de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'E o rei Roboão enviou a Adorão, que estava sobre os tributos; mas apedrejou-lhe todo Israel, e morreu. Então o rei Roboão se esforçou a subir em um carro, e fugir a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Assim se separou Israel da casa de Davi até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'E aconteceu que, ouvindo todo Israel que Jeroboão havia voltado, enviaram e chamaram-lhe à congregação, e fizeram-lhe rei sobre todo Israel, sem restar tribo alguma que seguisse a casa de Davi, a não ser somente a tribo de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'E quando Roboão veio a Jerusalém, juntou toda a casa de Judá e a tribo de Benjamim, cento e oitenta mil homens escolhidos de guerra, para fazer guerra à casa de Israel, e restituir o reino a Roboão filho de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mas foi palavra do SENHOR a Semaías homem de Deus, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Fala a Roboão filho de Salomão, rei de Judá, e a toda a casa de Judá e de Benjamim, e aos demais do povo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Assim disse o SENHOR: Não vades, nem luteis contra vossos irmãos os filhos de Israel; voltai-vos cada um à sua casa; porque este negócio eu o fiz. E eles ouviram a palavra de Deus, e voltaram, e foram-se, conforme à palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'E reedificou Jeroboão a Siquém no monte de Efraim, e habitou nela; e saindo dali, reedificou a Peniel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'E disse Jeroboão em seu coração: Agora se voltará o reino à casa de Davi,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Se este povo subir a sacrificar à casa do SENHOR em Jerusalém: porque o coração deste povo se converterá a seu senhor Roboão rei de Judá, e me matarão a mim, e se tornarão a Roboão rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'E havido conselho, fez o rei dois bezerros de ouro, e disse ao povo: Demais subistes a Jerusalém: eis que teus deuses, ó Israel, que te fizeram subir da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'E pôs o um em Betel, e o outro pôs em Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'E isto foi ocasião de pecado; porque o povo ia a adorar diante do um, até Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Fez também casa de altos, e fez sacerdotes da classe do povo, que não eram dos filhos de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Então instituiu Jeroboão solenidade no mês oitavo, aos quinze do mês, conforme à solenidade que se celebrava em Judá; e sacrificou sobre altar. Assim fez em Betel, sacrificando aos bezerros que havia feito. Ordenou também em Betel sacerdote');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Sacrificou pois sobre o altar que ele havia feito em Betel, aos quinze do mês oitavo, o mês que ele havia inventado de seu coração; e fez festa aos filhos de Israel, e subiu ao altar para queimar incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'E eis que um homem de Deus por palavra do SENHOR veio de Judá a Betel; e estando Jeroboão ao altar para queimar incenso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Ele clamou contra o altar por palavra do SENHOR, e disse: Altar, altar, assim disse o SENHOR: Eis que à casa de Davi nascerá um filho, chamado Josias, o qual sacrificará sobre ti aos sacerdotes dos altos que queimam sobre ti incenso; e sobre ti queimarão ossos humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'E aquele mesmo dia deu um sinal, dizendo: Esta é o sinal de que o SENHOR falou: eis que que o altar se quebrará, e a cinza que sobre ele está se derramará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'E quando o rei Jeroboão ouviu a palavra do homem de Deus, que havia clamado contra o altar de Betel, estendendo sua mão desde o altar, disse: Prendei-lhe! Mas a mão que havia estendido contra ele, se lhe secou, que não a pôde voltar a si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'E o altar se rompeu, e derramou-se a cinza do altar, conforme o sinal que o homem de Deus havia dado por palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Então respondendo o rei, disse ao homem de Deus: Peço-te que rogues à face do SENHOR teu Deus, e ora por mim, que minha mão me seja restituída. E o homem de Deus orou à face do SENHOR, e a mão do rei se lhe recuperou e tornou-se como antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'E o rei disse ao homem de Deus: Vem comigo à casa, e comerás, e eu te darei um presente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mas o homem de Deus disse ao rei: Se me desses a metade de tua casa, não iria contigo, nem comeria pão nem beberia água neste lugar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Porque assim me está mandado por palavra do SENHOR, dizendo: Não comas pão, nem bebas água, nem voltes pelo caminho que fordes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Foi-se, pois, por outro caminho, e não voltou pelo caminho por de onde havia vindo a Betel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Morava naquele tempo em Betel um velho profeta, ao qual veio seu filho, e contou-lhe tudo o que o homem de Deus havia feito aquele dia em Betel: contaram-lhe também a seu pai as palavras que havia falado ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'E seu pai lhes disse: Por que caminho foi? E seus filhos lhe mostraram o caminho por de onde se havia voltado o homem de Deus, que havia vindo de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'E ele disse a seus filhos: Preparai-me o asno. E eles lhe prepararam o asno, e subiu nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'E indo atrás o homem de Deus, achou-lhe que estava sentado debaixo de um carvalho: e disse-lhe: És tu o homem de Deus que vieste de Judá? E ele disse: Eu sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Disse-lhe então: Vem comigo à casa, e come do pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Mas ele respondeu: Não poderei voltar contigo, nem irei contigo; nem tampouco comerei pão nem beberei água contigo neste lugar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Porque por palavra de Deus me foi dito: Não comas pão nem bebas água ali, nem voltes pelo caminho que fores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'E o outro lhe disse: Eu também sou profeta como tu, e um anjo me falou pela palavra do SENHOR, dizendo: Faze-o voltar contigo à tua casa, para que coma pão e beba água. Porém mentiu-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Então voltou com ele, e comeu do pão em sua casa, e bebeu da água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'E aconteceu que, estando eles à mesa, veio a palavra do SENHOR ao profeta que lhe havia feito voltar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'E clamou ao homem de Deus que havia vindo de Judá, dizendo: Assim disse o SENHOR: Porquanto foste rebelde ao dito do SENHOR, e não guardaste o mandamento que o SENHOR teu Deus te havia prescrito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Em vez disso voltaste, e comeste do pão e bebeste da água no lugar de onde o SENHOR te havia dito não comesses pão nem bebesses água, não entrará teu corpo no sepulcro de teus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'E quando havia comido do pão e bebido, o profeta que lhe havia feito voltar lhe preparou um asno;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'E indo-se, encontrou-lhe um leão no caminho, e matou-lhe; e seu corpo estava lançado no caminho, e o asno estava junto a ele, e o leão também estava junto ao corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'E eis que uns que passavam, e viram o corpo que estava lançado no caminho, e o leão que estava junto ao corpo: e vieram, e disseram-no na cidade de onde o velho profeta habitava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'E ouvindo-o o profeta que lhe havia voltado do caminho, disse: O homem de Deus é, que foi rebelde ao dito do SENHOR: portanto o SENHOR lhe entregou ao leão, que lhe quebrantou e matou, conforme à palavra do SENHOR que ele lhe disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'E falou a seus filhos, e disse-lhes: Preparai-me um asno. E eles se o prepararam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'E ele foi, e achou seu corpo estendido no caminho, e o asno e o leão estavam junto ao corpo: o leão não havia comido o corpo, nem danificado ao asno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'E tomando o profeta o corpo do homem de Deus, o pôs sobre o asno, e o levou. E o profeta velho veio à cidade, para lamentar-lhe e enterrar-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'E pôs seu corpo em seu sepulcro; e lamentaram-lhe, dizendo: Ai, irmão meu!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'E depois que lhe houveram enterrado, falou a seus filhos, dizendo: Quando eu morrer, enterrai-me no sepulcro em que está sepultado o homem de Deus; ponde meus ossos junto aos seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Porque sem dúvida virá o que ele disse a vozes por palavra do SENHOR contra o altar que está em Betel, e contra todas as casas dos altos que estão nas cidades de Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Depois disto não se converteu Jeroboão de seu mau caminho: antes voltou a fazer sacerdotes dos altos da classe do povo, e quem queria se consagrava, e era dos sacerdotes dos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'E isto foi causa de pecado à casa de Jeroboão; pelo qual foi cortada e desraigada de sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Naquele tempo Abias filho de Jeroboão caiu enfermo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'E disse Jeroboão à sua mulher: Levanta-te agora, disfarça-te, porque não te conheçam que és a mulher de Jeroboão, e vai a Siló; que ali está Aías profeta, o que me disse que eu havia de ser rei sobre este povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'E toma em tua mão dez pães, e bolos, e uma botija de mel, e vai a ele; que te declare o que será deste jovem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'E a mulher de Jeroboão o fez assim; e levantou-se, e foi a Siló, e veio à casa de Aías. E não podia já ver Aías, que seus olhos se haviam escurecido à causa de sua velhice.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Mas o SENHOR havia dito a Aías: Eis que a mulher de Jeroboão virá a consultar-te por seu filho, que está enfermo: assim e assim lhe responderás; pois será que quando ela vier, virá dissimulada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'E quando Aías ouviu o som de seus pés quando entrava pela porta, disse: Entra, mulher de Jeroboão; por que te finges outra? Porém eu sou enviado a ti com revelação dura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Vai, e dize a Jeroboão: Assim disse o SENHOR Deus de Israel: Porquanto eu te levantei de em meio do povo, e te fiz príncipe sobre meu povo Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'E rompi o reino da casa de Davi, e o entreguei a ti; e tu não foste como Davi meu servo, que guardou meus mandamentos e andou após o mim com todo seu coração, fazendo somente o direito diante de meus olhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Antes fizeste o mau sobre todos os que foram antes de ti: que foste e te fizeste deuses alheios e de fundição para irar-me, e a mim me lançaste atrás tuas costas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Portanto, eis que eu trago mal sobre a casa de Jeroboão, e eu exterminarei de Jeroboão todo macho, tanto o escravo como o livre em Israel; e varrerei a posteridade da casa de Jeroboão, como é varrido o lixo, até que seja acabada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'O que morrer dos de Jeroboão na cidade, lhe comerão os cães; e o que morrer no campo, as aves do céu o comerão; porque o SENHOR o disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'E tu levanta-te, e vai-te à tua casa; que em entrando teu pé na cidade, morrerá o jovem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'E todo Israel o lamentará, e lhe enterrarão; porque somente ele dos de Jeroboão entrará em sepultura; porquanto se achou nele alguma coisa boa do SENHOR Deus de Israel, na casa de Jeroboão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'E o SENHOR se levantará um rei sobre Israel, o qual exterminará a casa de Jeroboão neste dia; e que, se agora?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'E o SENHOR sacudirá a Israel, ao modo que a cana se agita nas águas: e ele arrancará a Israel desta boa terra que havia dado a seus pais, e os dispersará da outra parte do rio, porquanto fizeram seus bosques, irando ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'E ele entregará a Israel pelos pecados de Jeroboão, o qual pecou, e fez pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Então a mulher de Jeroboão se levantou, e se foi, e veio a Tirsa: e entrando ela pelo umbral da casa, o jovem morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'E enterraram-no, e lamentaram-no todo Israel, conforme à palavra do SENHOR, que ele havia falado por mão de seu servo Aías profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Os outros feitos de Jeroboão, que guerras fez, e como reinou, tudo está escrito no livro das histórias dos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'O tempo que reinou Jeroboão foram vinte e dois anos; e havendo descansado com seus pais, reinou em seu lugar Nadabe seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'E Roboão filho de Salomão reinou em Judá. De quarenta e um anos era Roboão quando começou a reinar, e dezessete anos reinou em Jerusalém, cidade que o SENHOR elegeu de todas as tribos de Israel para pôr ali seu nome. O nome de sua mãe foi Naamá, amonita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'E Judá fez o que era mau aos olhos do SENHOR, e iraram-lhe mais que tudo o que seus pais haviam feito em seus pecados que cometeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Porque eles também se edificaram altos, estátuas, e bosques, em todo morro alto, e debaixo de toda árvore frondosa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'E havia também sodomitas na terra, e fizeram conforme a todas as abominações das nações que o SENHOR havia lançado diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Ao quinto ano do rei Roboão subiu Sisaque rei do Egito contra Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'E tomou os tesouros da casa do SENHOR, e os tesouros da casa real, e saqueou-o tudo: levou-se também todos os escudos de ouro que Salomão havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'E em lugar deles fez o rei Roboão escudos de bronze, e deu-os em mãos dos capitães dos da guarda, os quais guardavam a porta da casa real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'E quando o rei entrava na casa do SENHOR, os da guarda os levavam; e punham-nos depois na câmara dos da guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Os demais dos feitos de Roboão, e todas as coisas que fez, não estão escritas nas crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'E havia guerra entre Roboão e Jeroboão todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'E descansou Roboão com seus pais, e foi sepultado com seus pais na cidade de Davi. O nome de sua mãe foi Naamá, amonita. E reinou em seu lugar Abião seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'No ano dezoito do rei Jeroboão filho de Nebate, Abião começou a reinar sobre Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Reinou três anos em Jerusalém. O nome de sua mãe era Maaca, filha de Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'E andou em todos os pecados de seu pai, que havia este feito antes dele; e não foi seu coração completo com o SENHOR seu Deus, como o coração do seu pai Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mas por amor de Davi, deu-lhe o SENHOR seu Deus lâmpada em Jerusalém, levantando-lhe a seu filho depois dele, e sustentando a Jerusalém:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Porquanto Davi havia feito o que era correto diante dos olhos do SENHOR, e de nenhuma coisa que lhe mandasse se havia apartado em todos os dias de sua vida, exceto o negócio de Urias Heteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'E havia guerra entre Roboão e Jeroboão todos os dias de sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Os demais dos feitos de Abião, e todas as coisas que fez, não estão escritas no livro das crônicas dos reis de Judá? E havia guerra entre Abião e Jeroboão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'E dormiu Abião com seus pais, e sepultaram-no na cidade de Davi: e reinou Asa seu filho em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'No ano vinte de Jeroboão rei de Israel, Asa começou a reinar sobre Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'E reinou quarenta e um anos em Jerusalém; o nome de sua avó era Maaca, filha de Absalão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'E Asa fez o que era correto diante dos olhos do SENHOR, como o seu pai Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Porque tirou os sodomitas da terra, e tirou todas as imundícies que seus pais haviam feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'E também tirou de sua avó Maaca a posição de rainha-mãe, porque havia feito um ídolo num bosque. Além disso, Asa destruiu o ídolo dela, e o queimou junto ao ribeiro de Cedrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Porém os altos não foram tirados. Contudo, o coração de Asa foi completo com o SENHOR durante toda a sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Também trouxe à casa do SENHOR o que o seu pai havia dedicado, e o que ele dedicou: ouro, e prata, e utensílios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'E havia guerra entre Asa e Baasa, rei de Israel, durante todo o tempo deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'E Baasa, rei de Israel, subiu contra Judá, e edificou Ramá, para não deixar sair nem entrar a ninguém de Asa, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Então Asa tomou toda a prata e ouro que havia restado nos tesouros da casa do SENHOR, e os tesouros da casa real, entregou-os nas mãos de seus servos, e o rei Asa os enviou a Ben-Hadade, filho de Tabrimom, filho de Heziom, rei da Síria, o qual residia em Damasco, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Aliança há entre mim e ti, e entre meu pai e o teu; eis que eu te envio um presente de prata e ouro. Vai, e rompe a tua aliança com Baasa rei de Israel, para que me deixe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'E Ben-Hadade consentiu com o rei Asa, e enviou os príncipes dos exércitos que tinha contra as cidades de Israel, e feriu a Ijom, e a Dã, e a Abel-Bete-Maaca, e a toda Quinerete, com toda a terra de Naftali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'E ouvindo isto Baasa, deixou de edificar a Ramá, e ficou em Tirsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Então o rei Asa convocou a todo Judá, sem excetuar ninguém; e tiraram de Ramá a pedra e a madeira com que Baasa edificava, e edificou o rei Asa com ele a Gibeá de Benjamim, e a Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Os demais de todos os feitos de Asa, e toda sua fortaleza, e todas as coisas que fez, e as cidades que edificou, não está tudo escrito no livro das crônicas dos reis de Judá? Mas no tempo de sua velhice enfermou de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'E descansou Asa com seus pais, e foi sepultado com seus pais na cidade de Davi seu pai: e reinou em seu lugar Josafá seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'E Nadabe, filho de Jeroboão, começou a reinar sobre Israel no segundo ano de Asa rei de Judá; e reinou sobre Israel dois anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'E fez o que era mau diante dos olhos do SENHOR, andando no caminho de seu pai, e em seus pecados com que fez pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'E Baasa filho de Aías, o qual era da casa de Issacar, fez conspiração contra ele: e feriu-o Baasa em Gibetom, que era dos filisteus: porque Nadabe e todo Israel tinham cercado a Gibetom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Matou-o, pois, Baasa no terceiro ano de Asa rei de Judá, e reinou em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'E quando ele veio ao reino, feriu toda a casa de Jeroboão, sem deixar alma vivente dos de Jeroboão, até exterminá-lo, conforme à palavra do SENHOR que ele falou por seu servo Aías silonita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Por causa dos pecados de Jeroboão que ele havia cometido, e com os quais fez pecar a Israel; e por sua provocação com que provocou à ira ao SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Os demais dos feitos de Nadabe, e todas as coisas que fez, não está tudo escrito no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'E havia guerra entre Asa e Baasa, rei de Israel, durante todo o tempo deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'No terceiro ano de Asa, rei de Judá, começou a reinar Baasa, filho de Aías, sobre todo Israel em Tirsa; e reinou vinte e quatro anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'E fez o que era mau aos olhos do SENHOR, e andou no caminho de Jeroboão, e em seu pecado com que fez pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'E foi palavra do SENHOR a Jeú, filho de Hanani, contra Baasa, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Posto que te levantei do pó, e te pus por príncipe sobre meu povo Israel, e andaste no caminho de Jeroboão, e fizeste pecar a meu povo Israel, provocando-me à ira com os seus pecados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Eis que varrerei a posteridade de Baasa, e a posteridade de sua casa; e tornarei a tua casa como a casa de Jeroboão, filho de Nebate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'O que de Baasa for morto na cidade, os cães lhe comerão; e o que dele for morto no campo, as aves do céu o comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Os demais dos feitos de Baasa, e as coisas que fez, e sua fortaleza, não está tudo escrito no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'E descansou Baasa com seus pais, e foi sepultado em Tirsa; e reinou em seu lugar Elá, seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Porém a palavra do SENHOR por meio de Jeú profeta, filho de Hanani, havia sido contra Baasa e também contra sua casa, com motivo de todo o mal que fez aos olhos do SENHOR, provocando-lhe à ira com as obras de suas mãos, para que fosse feita como a casa de Jeroboão; e porque o havia ferido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'No ano vinte e seis de Asa rei de Judá, começou a reinar Elá filho de Baasa sobre Israel em Tirsa; e reinou dois anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'E fez conspiração contra ele seu servo Zinri, comandante da metade dos carros. E estando ele em Tirsa, bebendo e embriagado em casa de Arsa seu mordomo em Tirsa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Veio Zinri, e o feriu e matou, no ano vinte e sete de Asa rei de Judá; e reinou em lugar seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'E logo que chegou a reinar e esteve sentado em seu trono, feriu toda a casa de Baasa, sem deixar nela macho, nem seus parentes nem amigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Assim exterminou Zinri toda a casa de Baasa, conforme à palavra do SENHOR, que havia proferido contra Baasa por meio do profeta Jeú;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Por todos os pecados de Baasa, e os pecados de Elá seu filho, com que eles pecaram e fizeram pecar a Israel, provocando à ira ao SENHOR Deus de Israel com suas vaidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Os demais feitos de Elá, e todas as coisas que fez, não está tudo escrito no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'No ano vinte e sete de Asa rei de Judá, começou a reinar Zinri, e reinou sete dias em Tirsa; e o povo havia assentado campo sobre Gibetom, cidade dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'E o povo que estava no campo ouviu dizer: Zinri fez conspiração, e matou ao rei. Então todo Israel levantou o mesmo dia por rei sobre Israel a Onri, general do exército, no campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'E subiu Onri de Gibetom, e com ele todo Israel, e cercaram a Tirsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Mas vendo Zinri tomado a cidade, entrou no palácio da casa real, e pegou fogo à casa consigo: assim morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'Por seus pecados que ele havia cometido, fazendo o que era mau aos olhos do SENHOR, e andando nos caminhos de Jeroboão, e em seu pecado que cometeu, fazendo pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Os demais feitos de Zinri, e sua conspiração que formou, não está tudo escrito no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Então o povo de Israel foi dividido em duas partes: a metade do povo seguia a Tibni filho de Ginate, para fazê-lo rei: e a outra metade seguia a Onri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Mas o povo que seguia a Onri pôde mais que o que seguia a Tibni filho de Ginate; e Tibni morreu, e Onri foi rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'No ano trinta e um de Asa rei de Judá, começou a reinar Onri sobre Israel, e reinou doze anos: em Tirsa reinou seis anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'E ele comprou de Semer o monte de Samaria por dois talentos de prata, e edificou no monte: e chamou o nome da cidade que edificou Samaria, do nome de Semer, senhor que foi daquele monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'E Onri fez o mau aos olhos do SENHOR, e fez pior que todos os que haviam sido antes dele:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Pois andou em todos os caminhos de Jeroboão filho de Nebate, e em seu pecado com que fez pecar a Israel, provocando à ira ao SENHOR Deus de Israel com seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Os demais dos feitos de Onri, e todas as coisas que fez, e suas valentias que executou, não está tudo escrito no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'E Onri descansou com seus pais, e foi sepultado em Samaria; e reinou em lugar seu Acabe, seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'E começou a reinar Acabe filho de Onri sobre Israel o ano trinta e oito de Asa rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'E reinou Acabe filho de Onri sobre Israel em Samaria vinte e dois anos. E Acabe filho de Onri fez o que era mau aos olhos do SENHOR além de todos os que foram antes dele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Porque lhe foi pouca coisa andar nos pecados de Jeroboão filho de Nebate, e tomou por mulher a Jezabel filha de Etbaal rei dos sidônios, e foi e serviu a Baal, e o adorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'E fez altar a Baal, no templo de Baal que ele edificou em Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Fez também Acabe um bosque; e acrescentou Acabe fazendo provocar à ira ao SENHOR Deus de Israel, mais que todos os reis de Israel que antes dele haviam sido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Em seu tempo Hiel de Betel reedificou a Jericó. À custa de Abirão seu primogênito lançou o alicerce, e à custa de Segube seu filho posterior pôs suas portas, conforme à palavra do SENHOR que havia falado por Josué filho de Num.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Então Elias Tisbita, que era dos moradores de Gileade, disse a Acabe: Vive o SENHOR Deus de Israel, diante do qual estou, que não haverá chuva nem orvalho nestes anos, a não ser por minha palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'E foi a ele palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Aparta-te daqui, e volta-te ao oriente, e esconde-te no ribeiro de Querite, que está diante do Jordão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'E beberás do ribeiro; e eu ei mandado aos corvos que te deem ali de comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'E ele foi, e fez conforme à palavra do SENHOR; pois se foi e assentou junto ao ribeiro de Querite, que está antes do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'E os corvos lhe traziam pão e carne pela manhã, e pão e carne à tarde; e bebia do ribeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Passados alguns dias, secou-se o ribeiro; porque não havia chovido sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'E foi a ele palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Levanta-te, vai-te a Sarepta de Sidom, e ali morarás: eis que eu mandei ali a uma mulher viúva que te sustente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Então ele se levantou, e se foi a Sarepta. E quando chegou à porta da cidade, eis que uma mulher viúva que estava ali colhendo gravetos; e ele a chamou, e disse-lhe: Rogo-te que me tragas um pouco de água em um vaso, para que beba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'E indo ela para trazê-la, ele a voltou a chamar, e disse-lhe: Rogo-te que me tragas também um bocado de pão em tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'E ela respondeu: Vive o SENHOR Deus teu, que não tenho pão cozido; que somente um punhado de farinha tenho no jarro, e um pouco de azeite em uma botija: e agora cozia dois gravetos, para entrar-me e prepará-lo para mim e para meu filho, e que o comamos, e morramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'E Elias lhe disse: Não tenhas temor; vai, face como disseste: porém faze-me a mim primeiro disso uma pequena torta cozida debaixo da cinza, e traze-a a mim; e depois farás para ti e para teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Porque o SENHOR Deus de Israel disse assim: O jarro da farinha não esvaziará, nem se diminuirá a botija do azeite, até aquele dia que o SENHOR dará chuva sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Então ela foi, e fez como lhe disse Elias; e comeu ele, e ela e sua casa, muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'E o jarro da farinha não esvaziou, nem minguou a botija do azeite, conforme à palavra do SENHOR que havia dito por Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Depois destas coisas aconteceu que caiu enfermo o filho da ama da casa, e a enfermidade foi tão grave, que não restou nele respiração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'E ela disse a Elias: Que tenho eu contigo, homem de Deus? Vieste a mim para trazer em memória minhas iniquidades, e para fazer-me morrer meu filho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'E ele lhe disse: Dá-me aqui teu filho. Então ele o tomou de seu colo, e levou-o à câmara de onde ele estava, e pôs-lhe sobre sua cama;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'E clamando ao SENHOR, disse: SENHOR Deus meu, ainda à viúva em cuja casa eu estou hospedado afligiste, matando-lhe seu filho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'E ele se estendeu sobre o menino três vezes, e clamou ao SENHOR, e disse: SENHOR Deus meu, rogo-te que volte a alma deste menino a suas entranhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'E o SENHOR ouviu a voz de Elias, e a alma do menino voltou a suas entranhas, e reviveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Tomando logo Elias ao menino, trouxe-o da câmara à casa, e deu-o à sua mãe, e disse-lhe Elias: Olha, teu filho vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Então a mulher disse a Elias: Agora conheço que tu és homem de Deus, e que a palavra do SENHOR é verdade em tua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Passados muitos dias, veio a palavra do SENHOR a Elias no terceiro ano, dizendo: Vai, mostra-te a Acabe, e eu darei chuva sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Foi, pois, Elias a mostrar-se a Acabe. Havia naquele tempo grande fome em Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'E Acabe chamou a Obadias seu mordomo, o qual Obadias era em grande maneira temeroso do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Porque quando Jezabel destruía aos profetas do SENHOR, Obadias tomou cem profetas, os quais escondeu de cinquenta em cinquenta por covas, e sustentou-os a pão e água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'E disse Acabe a Obadias: Vai pelo país a todas as fontes de águas, e a todos os ribeiros; que acaso acharemos grama com que conservemos a vida aos cavalos e às mulas, para que não nos fiquemos sem animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'E partiram entre si o país para percorrerem-no: Acabe foi de por si por um caminho, e Obadias foi separadamente por outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'E indo Obadias pelo caminho, encontrou-se com Elias; e como lhe conheceu, prostrou-se sobre seu rosto, e disse: Não és tu meu senhor Elias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'E ele respondeu: Eu sou; vai, dize a teu amo: Eis que Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Porém ele disse: Em que ei pecado, para que tu entregues teu servo em mão de Acabe para que me mate?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Vive o SENHOR teu Deus, que não houve nação nem reino de onde meu senhor não haja enviado a buscar-te; e respondendo eles: Não está aqui, ele conjurou a reinos e nações se não te acharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'E agora tu dizes: Vai, dize a teu amo: Aqui está Elias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'E acontecerá que, logo que eu me haja partido de ti, o espírito do SENHOR te levará de onde eu não saiba; e vindo eu, e dando as novas a Acabe, e se ele não te achar, me matará; e teu servo teme ao SENHOR desde sua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Não foi dito a meu senhor o que fiz, quando Jezabel matava aos profetas do SENHOR: que escondi cem homens dos profetas do SENHOR de cinquenta em cinquenta em covas, e os mantive a pão e água?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'E agora dizes tu: Vai, dize a teu amo: Aqui está Elias: para que ele me mate?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'E disse-lhe Elias: Vive o SENHOR dos exércitos, diante do qual estou, que hoje me mostrarei a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Então Obadias foi a encontrar-se com Acabe, e deu-lhe o aviso; e Acabe veio a encontrar-se com Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'E quando Acabe viu a Elias, disse-lhe Acabe: És tu o que perturbas a Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'E ele respondeu: Eu não perturbei a Israel, mas sim tu e a casa de teu pai, deixando os mandamentos do SENHOR, e seguindo aos baalins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Envia, pois, agora e juntai-me a todo Israel no monte de Carmelo, e os quatrocentos e cinquenta profetas de Baal, e os quatrocentos profetas dos bosques, que comem da mesa de Jezabel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Então Acabe enviou a todos os filhos de Israel, e juntou os profetas no monte de Carmelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'E aproximando-se Elias a todo o povo, disse: Até quando hesitareis vós entre dois pensamentos? Se o SENHOR é Deus, segui-lhe; e se Baal, ide depois dele. E o povo não respondeu palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'E Elias converteu a dizer ao povo: Só eu restei profeta do SENHOR; mas dos profetas de Baal há quatrocentos e cinquenta homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Deem-se a nós, pois, dois bois, e escolham-se eles o um, e cortem-no em pedaços, e ponham-no sobre lenha, mas não ponham fogo debaixo; e eu prepararei o outro boi, e o porei sobre lenha, e nenhum fogo porei debaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Invocai logo vós no nome de vossos deuses, e eu invocarei no nome do SENHOR: e o Deus que responder por fogo, esse seja Deus. E todo o povo respondeu, dizendo: Bem dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Então Elias disse aos profetas de Baal: Escolhei-vos o um boi, e fazei primeiro, pois que vós sois os mais: e invocai no nome de vossos deuses, mas não ponhais fogo debaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'E eles tomaram o boi que lhes foi dado, e prepararam-no, e invocaram no nome de Baal desde a manhã até o meio dia, dizendo: Baal, responde-nos! Mas não havia voz, nem quem respondesse; entretanto, eles andavam saltando próximo do altar que haviam feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'E aconteceu ao meio dia, que Elias se ridicularizava deles, dizendo: Gritai em alta voz, que deus é: talvez esteja conversando, ou tem alguma ocupação, ou está caminhando; acaso dorme, e despertará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'E eles clamavam a grandes vozes, e cortavam-se com espadas e com lancetas conforme a seu costume, até jorrar o sangue sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'E quando passou o meio dia, e eles profetizaram até o tempo do sacrifício da oferta, e não havia voz, nem quem respondesse nem escutasse;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Elias disse então a todo o povo: Aproximai-vos a mim. E todo o povo se chegou a ele: e ele reparou o altar do SENHOR que estava arruinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'E tomando Elias doze pedras, conforme ao número das tribos dos filhos de Jacó, ao qual havia sido palavra do SENHOR, dizendo: Israel será teu nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Edificou com as pedras um altar no nome do SENHOR: depois fez uma sulco ao redor do altar, quanto cabiam duas medidas de semente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Pôs logo a lenha, e cortou o boi em pedaços, e o pôs sobre a lenha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'E disse: Enchei quatro cântaros de água, e derramai-a sobre o holocausto e sobre a lenha. E disse: Fazei-o outra vez; e outra vez o fizeram. Disse ainda: Fazei-o a terceira vez; e fizeram-no a terceira vez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'De maneira que as águas corriam ao redor do altar; e havia também enchido de água o sulco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'E quando chegou a hora de oferecer-se o holocausto, chegou-se o profeta Elias, e disse: SENHOR Deus de Abraão, de Isaque, e de Israel, seja hoje manifesto que tu és Deus em Israel, e que eu sou teu servo, e que por mandado teu fiz todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Responde-me, SENHOR, responde-me; para que conheça este povo que tu, ó SENHOR, és o Deus, e que tu voltaste atrás o coração deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Então caiu fogo do SENHOR, o qual consumiu o holocausto, e a lenha, e as pedras, e o pó, e ainda sugou as águas que estavam no sulco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'E vendo-o todo o povo, caíram sobre seus rostos, e disseram: o SENHOR é o Deus! o SENHOR é o Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'E disse-lhes Elias: Prendei aos profetas de Baal, que não escape ninguém. E eles os prenderam; e levou-os Elias ao ribeiro de Quisom, e ali os degolou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'E então Elias disse a Acabe: Sobe, come e bebe; porque uma grande chuva faz ruído.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'E Acabe subiu a comer e a beber. E Elias subiu ao cume do Carmelo; e prostrando-se em terra, pôs seu rosto entre os joelhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'E disse a seu criado: Sobe agora, e olha até o mar. E ele subiu, e olhou, e disse: Não há nada. E ele lhe voltou a dizer: Volta sete vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'E à sétima vez disse: Eu vejo uma pequena nuvem como a palma da mão de um homem, que sobe do mar. E ele disse: Vai, e dize a Acabe: Unge e desce, porque a chuva não te interrompa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'E aconteceu, estando em isto, que os céus se escureceram com nuvens e vento; e houve uma grande chuva. E subindo Acabe, veio a Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'E a mão do SENHOR foi sobre Elias, o qual cingiu seus lombos, e veio correndo diante de Acabe até chegar a Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'E Acabe deu a notícia a Jezabel de tudo o que Elias havia feito, de como havia matado à espada a todos os profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Então enviou Jezabel a Elias um mensageiro, dizendo: Assim me façam os deuses, e assim me acrescentem, se amanhã a estas horas eu não haja posto tua pessoa como a de um deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Vendo, pois, o perigo, levantou-se e foi-se por salvar sua vida, e veio a Berseba, que é em Judá, e deixou ali seu criado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'E ele se foi pelo deserto um dia de caminho, e veio e sentou-se debaixo de um junípero; e desejando morrer, disse: Basta já, ó SENHOR, tira minha alma; que não sou eu melhor que meus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'E lançando-se debaixo do junípero, ficou dormido: e eis que logo um anjo que lhe tocou, e lhe disse: Levanta-te, come.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Então ele olhou, e eis que a sua cabeceira uma torta cozida sobre as ascuas, e um vaso de água: e comeu e bebeu e voltou-se a dormir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'E voltando o anjo do SENHOR a segunda vez, tocou-lhe, dizendo: Levanta-te, come: porque grande caminho te resta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Levantou-se, pois, e comeu e bebeu; e caminhou com a força daquela comida quarenta dias e quarenta noites, até o monte de Deus, Horebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'E ali se meteu em uma cova, de onde teve a noite. E foi a ele palavra do SENHOR, o qual lhe disse: Que fazes aqui, Elias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'E ele respondeu: Tenho sentido um zelo intenso pelo SENHOR Deus dos exércitos; porque os filhos de Israel deixaram tua aliança, derrubaram teus altares, e mataram à espada teus profetas: e eu só restei, e me buscam para tirar-me a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'E ele lhe disse: Sai fora, e põe-te no monte diante do SENHOR. E eis que o SENHOR que passava, e um grande e poderoso vento que rompia os montes, e quebrava as penhas diante do SENHOR: mas o SENHOR não estava no vento. E depois do vento um terremoto: mas o SENHOR não estava no terremoto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'E depois do terremoto um fogo: mas o SENHOR não estava no fogo. E depois do fogo uma voz agradável e suave.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'E quando o ouviu Elias, cobriu seu rosto com seu manto, e saiu, e parou-se à porta da cova. E eis que chegou uma voz a ele, dizendo: Que fazes aqui, Elias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'E ele respondeu: Tenho sentido um zelo intenso pelo SENHOR Deus dos exércitos; porque os filhos de Israel deixaram tua aliança, derrubaram teus altares, e mataram à espada teus profetas: e eu só restei, e me buscam para tirar-me a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'E disse-lhe o SENHOR: Vai, volta-te por teu caminho, pelo deserto de Damasco: e chegarás, e ungirás a Hazael por rei da Síria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'E a Jeú, filho de Ninsi, ungirás por rei sobre Israel; e a Eliseu filho de Safate, de Abel-Meolá, ungirás para que seja profeta em lugar de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'E será, que o que escapar da espada, de Hazael, Jeú o matará; e o que escapar da espada de Jeú, Eliseu o matará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'E eu farei que restem em Israel sete mil; todos os joelhos que não se encurvaram a Baal, e bocas todas que não o beijaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'E partindo-se ele dali, achou a Eliseu filho de Safate, que arava com doze juntas diante de si; e ele era um dos doze trabalhadores. E passando Elias por diante dele, lançou sobre ele seu manto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Então deixando ele os bois, veio correndo após Elias, e disse: Rogo-te que me deixes beijar meu pai e minha mãe, e logo te seguirei. E ele lhe disse: Vai, volta: que te fiz eu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'E interrompeu de segui-lo, tomou um par de bois, e os matou, e com o arado dos bois cozeu a carne deles, e deu-a ao povo que comessem. Depois se levantou, e foi atrás de Elias, e o servia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Então Ben-Hadade, rei da Síria, juntou a todo seu exército, e com ele trinta e dois reis, com cavalos e carros: e subiu, e pôs cerco a Samaria, e combateu-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'E enviou mensageiros à cidade a Acabe rei de Israel, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Assim disse Ben-Hadade: Tua prata e teu ouro são meus, e tuas mulheres e teus filhos belos são meus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'E o rei de Israel respondeu, e disse: Como tu dizes, rei senhor meu, eu sou teu, e tudo o que tenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'E voltando os mensageiros outra vez, disseram: Assim disse Ben-Hadade: Eu te enviei a dizer: Tua prata e teu ouro, e tuas mulheres e teus filhos me darás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Além disso, amanhã a estas horas enviarei eu a ti meus servos, os quais vasculharão a tua casa, e as casas de teus servos; e tomarão com suas mãos, e levarão tudo o que for precioso que tiveres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Então o rei de Israel chamou a todos os anciãos da terra, e disse-lhes: Entendei, e vede agora como este não busca a não ser mal: pois que enviou a mim por minhas mulheres e meus filhos, e por minha prata e por meu ouro; e eu não se o neguei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'E todos os anciãos e todo o povo lhe responderam: Não lhe obedeças, nem faças o que te pede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Então ele respondeu aos embaixadores de Ben-Hadade: Dizei ao rei meu senhor: Farei tudo o que mandaste a teu servo ao princípio; mas isto não posso fazer. E os embaixadores foram, e deram-lhe a resposta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'E Ben-Hadade converteu a enviar-lhe a dizer: Assim me façam os deuses, e assim me acrescentem, que o pó de Samaria não bastará aos punhos de todo o povo que me segue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'E o rei de Israel respondeu, e disse: Dizei-lhe, que não se glorie o que se cinge, como o que já se descinge.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'E quando ele ouviu esta palavra, estando bebendo com os reis nas tendas, disse a seus servos: Ponde. E eles puseram contra a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'E eis que um profeta se chegou a Acabe rei de Israel; e lhe disse: Assim disse o SENHOR: Viste esta grande multidão? Eis que eu a entregarei hoje em tua mão, para que conheças que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'E respondeu Acabe: Por meio de quem? E ele disse: Assim disse o SENHOR: Por meio dos criados dos príncipes das províncias. E disse Acabe: Quem começará a batalha? E ele respondeu: Tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Então ele revistou os criados dos príncipes das províncias, os quais foram duzentos trinta e dois. Em seguida revistou todo o povo, todos os filhos de Israel, que foram sete mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'E saíram a meio dia. E estava Ben-Hadade bebendo, embriagado nas tendas, ele e os reis, os trinta e dois reis que haviam vindo em sua ajuda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'E os criados dos príncipes das províncias saíram os primeiros. E havia Ben-Hadade enviado quem lhe deu aviso, dizendo: Saíram homens de Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Ele então disse: Se saíram por paz, tomai-os vivos; e se saíram para lutar, tomai-os vivos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Saíram, pois da cidade os criados dos príncipes das províncias, e após eles o exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'E feriu cada um ao que vinha contra si: e fugiram os sírios, seguindo-os os de Israel. E o rei da Síria, Ben-Hadade, se escapou em um cavalo com alguma gente de cavalaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'E saiu o rei de Israel, e feriu a cavaleiros, e os carros; e derrotou os sírios com grande estrago.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Chegando-se logo o profeta ao rei de Israel, lhe disse: Vai, fortalece-te, e considera e olha o que hás de fazer; porque passado o ano, o rei da Síria há de vir contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'E os servos do rei da Síria lhe disseram: seus deuses são deuses dos montes, por isso nos venceram; mas se lutássemos com eles na planície, se verá se não os vencemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Faze, pois assim: Tira aos reis cada um de seu posto, e põe capitães em lugar deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'E tu, forma-te outro exército como o exército que perdeste, cavalos por cavalos, e carros por carros; logo lutaremos com eles em campo raso, e veremos se não os vencemos. E ele lhes deu ouvido, e o fez assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Passado o ano, Ben-Hadade revistou os sírios, e veio a Afeque a lutar contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'E os filhos de Israel foram também inspecionados, e tomando provisões foram-lhes ao encontro; e assentaram acampamento os filhos de Israel diante deles, como dois pequenos rebanhos de cabras; e os sírios enchiam a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Chegando-se então o homem de Deus ao rei de Israel, falou-lhe dizendo: Assim disse o SENHOR: Porquanto os sírios disseram, o SENHOR é Deus dos montes, não Deus dos vales, eu entregarei toda esta grande multidão em tua mão, para que conheçais que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Sete dias tiveram assentado o acampamento uns diante dos outros, e ao sétimo dia começou a batalha: e mataram os filhos de Israel dos sírios em um dia cem mil homens a pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Os demais fugiram a Afeque, à cidade: e o muro caiu sobre vinte e sete mil homens que haviam restado. Também Ben-Hadade veio fugindo à cidade, e escondia-se de câmara em câmara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Então seus servos lhe disseram: Eis que, ouvimos dos reis da casa de Israel que são reis clementes: ponhamos, pois, agora sacos em nossos lombos, e cordas em nossas cabeças, e saiamos ao rei de Israel: porventura te salvará a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Cingiram, pois seus lombos de sacos, e cordas a suas cabeças, e vieram ao rei de Israel, e disseram-lhe: Teu servo Ben-Hadade disse: Rogo-te que viva minha alma. E ele respondeu: Se ele vive ainda, meu irmão é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Isto tomaram aqueles homens por bom presságio, e logo tomaram esta palavra de sua boca, e disseram: Teu irmão Ben-Hadade! E ele disse: Ide, e trazei-lhe. Ben-Hadade então se apresentou a Acabe, e ele lhe fez subir em um carro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'E disse-lhe Ben-Hadade: As cidades que meu pai tomou ao teu, eu as restituirei; e faze praças em Damasco para ti, como meu pai as fez em Samaria. E eu, disse Acabe, te deixarei partir com esta aliança. Fez, pois com ele aliança, e deixou-lhe ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Então um homem dos filhos dos profetas disse a seu companheiro por palavra de Deus: Fere-me agora. Mas o outro homem não quis ferir-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'E ele lhe disse: Porquanto não obedeceste à palavra do SENHOR, eis que em apartando-te de mim, te ferirá um leão. E quando se separou dele, encontrou-lhe um leão, e feriu-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Encontrou-se logo com outro homem, e disse-lhe: Fere-me agora. E o homem lhe deu um golpe, e fez-lhe uma ferida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'E o profeta se foi, e pôs-se diante do rei no caminho, e disfarçou-se com um véu sobre os olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'E quando o rei passava, ele deu vozes ao rei, e disse: Teu servo saiu entre a tropa: e eis que um, que estava a sair, trouxe-me um homem, dizendo: Guarda a este homem, e se ele vier a faltar, tua vida será pela dele, ou pagarás um talento de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'E quando o teu servo estava ocupado à uma parte e à outra, ele desapareceu. Então o rei de Israel lhe disse: Essa será tua sentença: tu a pronunciaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Porém ele se tirou logo o véu de sobre seus olhos, e o rei de Israel conheceu que era dos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'E ele lhe disse: Assim disse o SENHOR: Porquanto soltaste da mão o homem de meu anátema, tua vida será pela sua, e teu povo pelo seu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'E o rei de Israel se foi a sua casa triste e irritado, e chegou a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Passados estes negócios, aconteceu que Nabote de Jezreel tinha em Jezreel uma vinha junto ao palácio de Acabe rei de Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'E Acabe falou a Nabote, dizendo: Dá-me tua vinha para uma horta de legumes, porque está próxima, junto a minha casa, e eu te darei por ela outra vinha melhor que esta; ou se melhor te parecer, te pagarei seu valor em dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'E Nabote respondeu a Acabe: Guarde-me o SENHOR de que eu te dê a ti a propriedade de meus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'E veio Acabe à sua casa triste e irritado, pela palavra que Nabote de Jezreel havia lhe respondido, dizendo: Não te darei a propriedade de meus pais. E deitou-se em sua cama, e virou seu rosto, e não comeu pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'E veio a ele sua mulher Jezabel, e disse-lhe: Por que está tão triste teu espírito, e não comes pão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'E ele respondeu: Porque falei com Nabote de Jezreel, e disse-lhe que me desse sua vinha por dinheiro, ou que, se mais quisesse, eu lhe daria outra vinha por ela; e ele respondeu: Eu não te darei minha vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'E sua mulher Jezabel lhe disse: És tu agora rei sobre Israel? Levanta-te, e come pão, e alegra-te: eu te darei a vinha de Nabote de Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Então ela escreveu cartas em nome de Acabe, e selou-as com seu anel e enviou-as aos anciãos e aos principais que moravam em sua cidade com Nabote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'E as cartas que escreveu diziam assim: Proclamai jejum, e ponde a Nabote em posição de destaque do povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'E ponde dois homens perversos diante dele, que testemunhem contra ele, e digam: Tu blasfemaste a Deus e ao rei. E então o tirai, e apedrejai-o, e morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'E os de sua cidade, os anciãos e os principais que moravam em sua cidade, o fizeram como Jezabel lhes mandou, conforme o escrito nas cartas que ela lhes havia enviado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'E promulgaram jejum, e assentaram a Nabote em posição de destaque do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Vieram então dois homens perversos, e sentaram-se diante dele: e aqueles homens de Belial testemunharam contra Nabote diante do povo, dizendo: Nabote blasfemou a Deus e ao rei. E tiraram-no fora da cidade, e apedrejaram-no com pedras, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Depois enviaram a dizer a Jezabel: Nabote foi apedrejado e morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'E quando Jezabel ouviu que Nabote havia sido apedrejado e morto, disse a Acabe: Levanta-te e possui a vinha de Nabote de Jezreel, que não te a quis dar por dinheiro; porque Nabote não vive, mas sim que está morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'E ouvindo Acabe que Nabote era morto, levantou-se para descer à vinha de Nabote de Jezreel, para tomar possessão dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Então veio a palavra do SENHOR a Elias Tisbita, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Levanta-te, desce a encontrar-te com Acabe rei de Israel, que está em Samaria: eis que ele está na vinha de Nabote, à qual desceu para tomar possessão dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'E falar-lhe hás, dizendo: Assim disse o SENHOR: Não mataste e também possuíste? E voltarás a falar-lhe, dizendo: Assim disse o SENHOR: No mesmo lugar de onde lamberam os cães o sangue de Nabote, os cães lamberão também teu sangue, o teu mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'E Acabe disse a Elias: Achaste-me, inimigo meu? E ele respondeu: Eu te encontrei, porque te vendeste a fazer o mal diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Eis que eu trago mal sobre ti, e varrerei tua posteridade, e exterminarei de Acabe todo macho, ao escravo e ao livre em Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'E eu porei tua casa como a casa de Jeroboão filho de Nebate, e como a casa de Baasa filho de Aías; pela provocação com que me provocaste à ira, e com que fizeste pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'De Jezabel também falou o SENHOR, dizendo: Os cães comerão a Jezabel no muro de Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'O que de Acabe for morto na cidade, cães lhe comerão: e o que for morto no campo, comê-lo-ão as aves do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '(À verdade ninguém foi como Acabe, que se vendeu a fazer o mal aos olhos do SENHOR; porque Jezabel sua mulher o incitava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Ele foi em grande maneira abominável, caminhando após o os ídolos, conforme a tudo o que fizeram os amorreus, aos quais lançou o SENHOR diante dos filhos de Israel.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'E aconteceu quando Acabe ouviu estas palavras, que rasgou suas roupas, e pôs saco sobre sua carne, e jejuou, e dormiu em saco, e andou humilhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Então veio a palavra do SENHOR a Elias Tisbita, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Não viste como Acabe se humilhou diante de mim? Pois porquanto se humilhou diante de mim, não trarei o mal em seus dias: nos dias de seu filho trarei o mal sobre sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Três anos passaram sem guerra entre os sírios e Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'E aconteceu ao terceiro ano, que Josafá rei de Judá desceu ao rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'E o rei de Israel disse a seus servos: Não sabeis que Ramote de Gileade e nossa? Porém ficamos quietos, sem a tomar da mão do rei da Síria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'E disse a Josafá: Queres vir comigo a lutar contra Ramote de Gileade? E Josafá respondeu ao rei de Israel: Como eu, assim tu; e como meu povo, assim teu povo; e como meus cavalos, teus cavalos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'E disse logo Josafá ao rei de Israel: Eu te rogo que consultes hoje a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Então o rei de Israel juntou os profetas, como quatrocentos homens, aos quais disse: Irei à guerra contra Ramote de Gileade, ou a deixarei? E eles disseram: Sobe; porque o Senhor a entregará em mão do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'E disse Josafá: Há ainda aqui algum profeta do SENHOR, pelo qual consultemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'E o rei de Israel respondeu a Josafá: Ainda há um homem pelo qual poderíamos consultar ao SENHOR, Micaías, filho de Inlá: mas eu lhe aborreço porque nunca me profetiza bem, a não ser somente mal. E Josafá disse: Não fale o rei assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Então o rei de Israel chamou a um eunuco, e disse-lhe: traze logo a Micaías filho de Inlá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'E o rei de Israel e Josafá rei de Judá estavam sentados cada um em sua cadeira, vestidos de suas roupas reais, na praça junto à entrada da porta de Samaria; e todos os profetas profetizavam diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'E Zedequias filho de Quenaaná se havia feito uns chifres de ferro, e disse: Assim disse o SENHOR: Com estes chifrarás aos siros até acabá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'E todos os profetas profetizavam da mesma maneira, dizendo: Sobe a Ramote de Gileade, e serás próspero; que o SENHOR a dará em mão do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'E o mensageiro que havia ido a chamar a Micaías, falou-lhe, dizendo: Eis que as palavras dos profetas unanimemente anunciam o bem ao rei; seja agora a tua palavra conforme à palavra de algum deles, e anuncia o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'E Micaías respondeu: Vive o SENHOR, que o que o SENHOR me falar, isso direi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Veio, pois, ao rei, e o rei lhe disse: Micaías, devemos ir lutar por Ramote de Gileade, ou a deixaremos? E ele respondeu: Sobe, que serás próspero, e o SENHOR a entregará na mão do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'E o rei lhe disse: Até quantas vezes te farei jurar que não me digas a não ser a verdade no nome do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Então ele disse: Eu vi a todo Israel disperso pelos montes, como ovelhas que não têm pastor: e o SENHOR disse: Estes não têm senhor: volte-se cada um a sua casa em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'E o rei de Israel disse a Josafá: Não te o havia eu dito? Nenhuma coisa boa profetizará ele acerca de mim, a não ser somente mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Então ele disse: Ouve, pois, a palavra do SENHOR: Eu vi o SENHOR sentado em seu trono, e todo o exército dos céus estava junto a ele, à sua direita e à sua esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'E o SENHOR disse: Quem induzirá a Acabe, para que suba e caia em Ramote de Gileade? E um dizia de uma maneira; e outro dizia de outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'E saiu um espírito, e pôs-se diante do SENHOR, e disse: Eu lhe induzirei. E o SENHOR lhe disse: De que maneira?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'E ele disse: Eu sairei, e serei espírito de mentira em boca de todos seus profetas. E ele disse: induzi-lo-ás, e ainda sairás com ele; sai, pois, e faze-o assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'E agora, eis que o SENHOR pôs espírito de mentira na boca de todos estes teus profetas, e o SENHOR decretou o mal acerca de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Chegando-se então Zedequias filho de Quenaaná, feriu a Micaías na face, dizendo: Por onde se foi de mim o espírito do SENHOR para falar a ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'E Micaías respondeu: Eis que tu o verás naquele dia, quando te irás metendo de câmara em câmara por esconder-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Então o rei de Israel disse: Toma a Micaías, e volta-o a Amom governador da cidade, e a Joás filho do rei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'E dirás: Assim disse o rei: Lançai a este no cárcere, e mantende-lhe com pão de angústia e com água de aflição, até que eu volte em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'E disse Micaías: Se chegares a voltar em paz, o SENHOR não falou por mim. Em seguida disse: Ouvi, povos todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Subiu, pois, o rei de Israel com Josafá rei de Judá a Ramote de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'E o rei de Israel disse a Josafá: Eu me disfarçarei, e entrarei na batalha: e tu veste-te tuas vestes. E o rei de Israel se disfarçou, e entrou na batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Mas o rei da Síria havia mandado a seus trinta e dois capitães dos carros, dizendo: Não luteis vós nem com grande nem com pequeno, a não ser somente contra o rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'E quando os capitães dos carros viram a Josafá, disseram: Certamente este é o rei de Israel; e vieram a ele para lutar com ele; mas o rei Josafá gritou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Vendo, então, os capitães dos carros que não era o rei de Israel, apartaram-se dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'E um homem disparando seu arco ao acaso, feriu ao rei de Israel por entre as junturas da armadura; pelo que disse ele a seu condutor do carro: Toma a volta, e tira-me do campo, que estou ferido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Mas a batalha havia se intensificado naquele dia, e o rei esteve em seu carro diante dos sírios, e à tarde morreu: e o sangue da ferida corria pelo fundo do carro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'E ao pôr do sol saiu um clamor pelo campo, dizendo: Cada um à sua cidade, e cada qual à sua terra!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'E morreu, pois, o rei, e foi trazido a Samaria; e sepultaram ao rei em Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'E lavaram o carro no tanque de Samaria, onde as prostitutas também se lavavam; e os cães lamberam seu sangue, conforme à palavra do SENHOR que havia falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Os demais dos feitos de Acabe, e todas as coisas que ele executou, e a casa de marfim que fez, e todas as cidades que edificou, não estão escritos no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'E descansou Acabe com seus pais, e reinou em seu lugar Acazias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'E Josafá filho de Asa começou a reinar sobre Judá no quarto ano de Acabe rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'E era Josafá de trinta e cinco anos quando começou a reinar, e reinou vinte e cinco anos em Jerusalém. O nome de sua mãe foi Azuba filha de Sili.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'E andou em todo o caminho de Asa seu pai, sem desviar dele, fazendo o reto nos olhos do SENHOR. Contudo isso os altos não foram tirados; que o povo sacrificava ainda, e queimava incenso nos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'E Josafá fez paz com o rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Os demais dos feitos de Josafá, e suas façanhas, e as guerras que fez, não está escrito no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Removeu também da terra o resto dos sodomitas que haviam restado no tempo de seu pai Asa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Não havia então rei em Edom; governador havia em lugar de rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Havia Josafá feito navios em Társis, os quais haviam de ir a Ofir por ouro; mas não foram, porque se romperam em Eziom-Geber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Então Acazias filho de Acabe disse a Josafá: Vão meus servos com os teus nos navios. Mas Josafá não quis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'E dormiu Josafá com seus pais, e foi sepultado com seus pais na cidade de Davi seu pai; e em seu lugar reinou Jeorão seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'E Acazias filho de Acabe começou a reinar sobre Israel em Samaria, o ano dezessete de Josafá rei de Judá; e reinou dois anos sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'E fez o que era mau aos olhos do SENHOR, e andou no caminho de seu pai, e no caminho de sua mãe, e no caminho de Jeroboão filho de Nebate, que fez pecar a Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Porque serviu a Baal, e o adorou, e provocou à ira o SENHOR Deus de Israel, conforme todas as coisas que seu pai havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Depois da morte de Acabe, Moabe rebelou-se contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'E Acazias caiu pela sacada de uma sala da casa que tinha em Samaria; e estando enfermo enviou mensageiros, e disse-lhes: Ide, e consultai a Baal-Zebube deus de Ecrom, se sararei desta minha enfermidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Então o anjo do SENHOR falou a Elias Tisbita, dizendo: Levanta-te, e sobe a encontrar-te com os mensageiros do rei de Samaria, e lhes dirás: Acaso não há Deus em Israel, para que vades a consultar Baal-Zebube, deus de Ecrom?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Portanto assim disse o SENHOR: Do leito em que subiste não descerás, antes certamente morrerás. E Elias se foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'E quando os mensageiros voltaram ao rei, ele lhes disse: Por que, pois, voltastes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'E eles lhe responderam: Encontramos um homem que nos disse: Ide, e voltai ao rei que vos enviou, e dizei-lhe: Assim disse o SENHOR: Acaso não há Deus em Israel, para que tu envias a consultar Baal-Zebube, deus de Ecrom? Portanto, do leito em que subiste não descerás, antes certamente morrerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Então ele lhes disse: Qual era a roupa daquele homem que encontrastes, e que vos disse tais palavras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'E eles lhe responderam: Um homem vestido de pelos, e cingia seus lombos com um cinto de couro. Então ele disse: É Elias, o tisbita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'E enviou logo a ele um capitão de cinquenta com seus cinquenta, o qual subiu a ele; e eis que ele estava sentado no cume do monte. E ele lhe disse: Homem de Deus, o rei disse que desças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'E Elias respondeu, e disse ao capitão de cinquenta: Se eu sou homem de Deus, desça fogo do céu, e consuma-te com teus cinquenta. E desceu fogo do céu, que o consumiu a ele e a seus cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Voltou o rei a enviar a ele outro capitão de cinquenta com seus cinquenta; e falou-lhe, e disse: Homem de Deus, o rei disse assim: Desce logo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'E respondeu-lhe Elias, e disse: Se eu sou homem de Deus, desça fogo do céu, e consuma-te com teus cinquenta. E desceu fogo do céu, que o consumiu a ele e a seus cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'E voltou a enviar o terceiro capitão de cinquenta com seus cinquenta; e subindo aquele terceiro capitão de cinquenta, ficou de joelhos diante de Elias, e rogou-lhe, dizendo: Homem de Deus, rogo-te que diante dos teus olhos seja preciosa minha vida e a vida destes teus cinquenta servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Eis que desceu fogo do céu, e consumiu os dois primeiros capitães de cinquenta, com seus cinquenta; seja agora minha vida preciosa diante de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Então o anjo do SENHOR disse a Elias: Desce com ele; não tenhas dele medo. E ele se levantou, e desceu com ele ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'E disse-lhe: Assim disse o SENHOR: Por que enviaste mensageiros a consultar Baal-Zebube, deus de Ecrom? Acaso não há Deus em Israel para consultar a sua palavra? Não descerás, portanto, do leito em que subiste, antes certamente morrerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'E morreu conforme à palavra do SENHOR que Elias havia falado; e reinou em seu lugar Jorão, no segundo ano de Jeorão, filho de Josafá rei de Judá; porque Acazias não tinha filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'E os demais dos feitos de Acazias, não estão escrito no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'E aconteceu que, quando o SENHOR quis erguer Elias num turbilhão ao céu, Elias vinha com Eliseu de Gilgal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'E disse Elias a Eliseu: Fica-te agora aqui, porque o SENHOR me enviou a Betel. E Eliseu disse: Vive o SENHOR, e vive tua alma, que não te deixarei. Desceram pois a Betel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'E saindo a Eliseu os filhos dos profetas que estavam em Betel, disseram-lhe: Sabes como o SENHOR tirará hoje o teu senhor de tua cabeça? E ele disse: Sim, eu o sei; calai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'E Elias lhe voltou a dizer: Eliseu, fica-te aqui agora, porque o SENHOR me enviou a Jericó. E ele disse: Vive o SENHOR, e vive tua alma, que não te deixarei. Vieram, pois, a Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'E achegaram-se a Eliseu os filhos dos profetas que estavam em Jericó, e disseram-lhe: Sabes como o SENHOR tirará hoje o teu senhor de tua cabeça? E ele respondeu: Sim, eu o sei; calai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'E Elias lhe disse: Rogo-te que te fiques aqui, porque o SENHOR me enviou ao Jordão. E ele disse: Vive o SENHOR, e vive tua alma, que não te deixarei. Foram, pois, ambos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'E vieram cinquenta homens dos filhos dos profetas, e pararam-se em frente a o longe: e eles dois se pararam junto ao Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Tomando então Elias seu manto, dobrou-o, e feriu as águas, as quais se apartaram a um e a outro lado, e passaram ambos em seco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'E quando houveram passado, Elias disse a Eliseu: Pede o que queres que faça por ti, antes que seja tirado de contigo. E disse Eliseu: Rogo-te que a porção dobrada de teu espírito seja sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'E ele lhe disse: Coisa difícil pediste. Se me vires quando for tirado de ti, te será assim feito; mas se não, não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'E aconteceu que, indo eles falando, eis que um carro de fogo com cavalos de fogo separou os dois; e Elias subiu ao céu num turbilhão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'E vendo-o Eliseu, clamava: Meu pai, meu pai! Carro de Israel e seus cavaleiros! E nunca mais lhe viu, e segurando de suas roupas, rompeu-os em duas partes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Levantou logo o manto de Elias que se lhe havia caído, e voltou, e parou-se à beira do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'E tomando o manto de Elias que se lhe havia caído, feriu as águas, e disse: Onde está o SENHOR, o Deus de Elias? E assim que houve do mesmo modo ferido as águas, apartaram-se a um e a outro lado, e passou Eliseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'E vendo-lhe os filhos dos profetas que estavam em Jericó da outra parte, disseram: O espírito de Elias repousou sobre Eliseu. E vieram-lhe a receber, e inclinaram-se a ele até a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'E disseram-lhe: Eis que há com teus servos cinquenta homens fortes; vão agora e busquem o teu senhor; talvez o Espírito do SENHOR o levantou, e o lançou em algum monte ou em algum vale. E ele lhes disse: Não envieis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Mas eles lhe importunaram, até que envergonhando-se, disse: Enviai. Então eles enviaram cinquenta homens, os quais o buscaram três dias, mas não o acharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'E quando voltaram a ele, que se havia restado em Jericó, ele lhes disse: Não vos disse eu que não fôsseis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'E os homens da cidade disseram a Eliseu: Eis que o assento desta cidade é bom, como meu senhor vai; mas as águas são más, e a terra enferma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Então ele disse: Trazei-me uma botija nova, e ponde nela sal. E trouxeram-na.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'E saindo ele aos mananciais das águas, lançou dentro o sal, e disse: Assim disse o SENHOR: Eu sarei estas águas, e não haverá mais nelas morte nem enfermidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'E foram saradas as águas até hoje, conforme a palavra que falou Eliseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Depois subiu dali a Betel; e subindo pelo caminho, saíram os meninos da cidade, e se ridicularizavam dele, dizendo: Sobe, calvo! Sobe, calvo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'E olhando ele atrás, viu-os, e amaldiçoou-os no nome do SENHOR. E duas ursas saíram da floresta, e despedaçaram deles quarenta e dois meninos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'De ali foi ao monte de Carmelo, e dali voltou a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'E Jorão, filho de Acabe, começou a reinar em Samaria sobre Israel o ano dezoito de Josafá rei de Judá; e reinou doze anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'E fez o que era mau aos olhos do SENHOR, ainda que não como seu pai e sua mãe; porque tirou as estátuas de Baal que seu pai havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Mas achegou-se aos pecados de Jeroboão, filho de Nebate, que fez pecar a Israel; e não se separou deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Então Messa rei de Moabe era proprietário de gados, e pagava ao rei de Israel cem mil cordeiros e cem mil carneiros com suas lãs.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Mas morto Acabe, o rei de Moabe se rebelou contra o rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'E saiu então de Samaria o rei Jorão, e inspecionou a todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'E foi e enviou a dizer a Josafá rei de Judá: O rei de Moabe se há rebelado contra mim: irás tu comigo à guerra contra Moabe? E ele respondeu: Irei, porque como eu, assim tu; como meu povo, assim teu povo; como meus cavalos, assim também teus cavalos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'E disse: Por qual caminho iremos? E ele respondeu: Pelo caminho do deserto de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Partiram, pois, o rei de Israel, e o rei de Judá, e o rei de Edom; e quando andaram rodeando pelo deserto sete dias de caminho, faltou-lhes a água para o exército, e para os animais que os seguiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Então o rei de Israel disse: Ah! Que o SENHOR chamou estes três reis para entregá-los em mãos dos moabitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Mas Josafá disse: Não há aqui profeta do SENHOR, para que consultemos ao SENHOR por ele? E um dos servos do rei de Israel respondeu e disse: Aqui está Eliseu filho de Safate, que dava água a mãos a Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'E Josafá disse: Este terá palavra do SENHOR. E desceram a ele o rei de Israel, e Josafá, e o rei de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Então Eliseu disse ao rei de Israel: Que tenho eu contigo? Vai aos profetas de teu pai, e aos profetas de tua mãe. E o rei de Israel lhe respondeu: Não; porque juntou o SENHOR estes três reis para entregá-los em mãos dos moabitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'E Eliseu disse: Vive o SENHOR dos exércitos, em cuja presença estou, que se não tivesse respeito ao rosto de Josafá rei de Judá, não olharia a ti, nem te veria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Mas agora trazei-me um músico. E enquanto o músico tocava, a mão do SENHOR foi sobre Eliseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'E disse: Assim disse o SENHOR: Fazei neste vale muitas covas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Porque o SENHOR disse assim: Não vereis vento, nem vereis chuva, e este vale será cheio de água, e bebereis vós, e vossos animais, e vossos gados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'E isto é coisa pouca aos olhos do SENHOR; dará também aos moabitas em vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'E vós ferireis a toda cidade fortalecida e a toda vila bela, e cortareis toda boa árvore, e cegareis todas as fontes de águas, e destruireis com pedras toda terra fértil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'E aconteceu que pela manhã, quando se oferece o sacrifício, eis que vieram águas pelo caminho de Edom, e a terra foi cheia de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'E todos os de Moabe, quando ouviram que os reis subiam a lutar contra eles, juntaram-se desde todos os que cingiam armas de guerra acima, e puseram-se na fronteira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'E quando se levantaram pela manhã, e luziu o sol sobre as águas, viram os de Moabe desde longe as águas vermelhas como sangue;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'E disseram: Sangue é este de espada! Os reis se revoltaram, e cada um matou a seu companheiro. Agora, pois, Moabe, à presa!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Mas quando chegaram ao campo de Israel, levantaram-se os israelitas e feriram aos de Moabe, os quais fugiram diante deles; seguiram, porém, ferindo aos de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'E assolaram as cidades, e em todas as propriedades férteis lançou cada um sua pedra, e as encheram; fecharam também todas as fontes das águas, e derrubaram todas as boas árvores; até que em Quir-Haresete somente deixaram suas pedras; porque os atiradores de funda a cercaram e a feriram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'E quando o rei de Moabe viu que a batalha o vencia, tomou consigo setecentos homens que tiravam espada, para romper contra o rei de Edom, mas não conseguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Então arrebatou a seu primogênito que havia de reinar em seu lugar, e sacrificou-lhe em holocausto sobre o muro. E havia grande ira em Israel; e retiraram-se dele, e voltaram a sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Uma mulher, das mulheres dos filhos dos profetas, clamou a Eliseu, dizendo: Teu servo, meu marido, é morto; e tu sabes que teu servo era temeroso ao SENHOR; e veio o credor para tomar-se dois filhos meus por servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'E Eliseu lhe disse: que te farei eu? Declara-me o que tens em casa. E ela disse: Tua serva nenhuma coisa tem em casa, a não ser uma botija de azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'E ele lhe disse: Vai, e pede para ti vasos emprestados de todos teus vizinhos, vasos vazios, não poucos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Entra logo, e fecha a porta atrás de ti e atrás teus filhos; e deita em todos os vasos, e em estando um cheio, põe-o à parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'E partiu-se a mulher dele, e fechou a porta atrás si e atrás seus filhos; e eles lhe traziam os vasos, e ela deitava do azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'E quando os vasos foram cheios, disse a um filho seu: Traze-me ainda outro vaso. E ele disse: Não há mais vasos. Então cessou o azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Veio ela logo, e contou-o ao homem de Deus, o qual disse: Vai, e vende o azeite, e paga a teus credores; e tu e teus filhos vivei do que restar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'E aconteceu também que um dia passava Eliseu por Suném; e havia ali uma mulher rica, a qual lhe constrangeu a que comesse do pão; e quando por ali passava, vinha-se à sua casa a comer do pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'E ela disse a seu marido: Eis que agora, eu entendo que este que sempre passa por nossa casa, é homem de Deus santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Eu te rogo que faças uma pequena câmara de paredes, e ponhamos nela cama, e mesa, e cadeira, e candelabro, para que quando vier a nós, se recolha nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'E aconteceu que um dia veio ele por ali, e recolheu-se naquela câmara, e dormiu nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Então disse a Geazi seu criado: Chama a esta sunamita. E quando ele a chamou, ela se apresentou diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'E disse ele a Geazi: Dize-lhe: Eis que tu tens sido prestativa por nós com todo este esmero: que queres que eu faça por ti? Tens necessidade que fale por ti ao rei, ou ao general do exército? E ela respondeu: Eu habito em meio de meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'E ele disse: Que, pois, faremos por ela? E Geazi respondeu: Eis que ela não tem filho, e seu marido é velho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Disse então: Chama-a. E ele a chamou, e ela se parou à porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'E ele lhe disse: A este tempo segundo o tempo da vida, abraçarás um filho. E ela disse: Não, senhor meu, homem de Deus, não mintas para tua serva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Mas a mulher concebeu, e pariu um filho a aquele tempo que Eliseu lhe havia dito, segundo o tempo da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'E quando o menino foi grande, aconteceu que um dia saiu a seu pai, aos ceifeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'E disse a seu pai: Minha cabeça, minha cabeça! E ele disse a um criado: Leva-o a sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'E havendo-lhe ele tomado, e trazido-o a sua mãe, esteve sentado sobre seus joelhos até meio dia, e morreu-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Ela então subiu, e o pôs sobre a cama do homem de Deus, e fechando-lhe a porta, saiu-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Chamando logo a seu marido, disse-lhe: Rogo-te que envies comigo a algum dos criados e uma das asnas, para que eu vá correndo ao homem de Deus, e volte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'E ele disse: Para que hás de ir a ele hoje? Não é nova lua, nem sábado. E ela respondeu: Paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Depois fez preparar uma jumenta, e disse ao jovem: Guia e anda; e não me faças deter para que suba, a não ser quando eu te disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Partiu-se, pois, e veio ao homem de Deus ao monte do Carmelo. E quando o homem de Deus a viu de longe, disse a seu criado Geazi: Eis que a sunamita:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Rogo-te que vás agora correndo a recebê-la, e dize-lhe: Há paz contigo, com teu marido, e com teu filho? E ela disse: Paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'E logo que chegou ao homem de Deus no monte, pegou seus pés. E chegou-se Geazi para tirá-la; mas o homem de Deus lhe disse: Deixa-a, porque sua alma está em amargura, e o SENHOR me encobriu o motivo, e não me revelou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'E ela disse: Pedi eu filho a meu senhor? Não disse eu, que não me enganasses?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Então disse ele a Geazi: Cinge teus lombos, e toma meu bordão em tua mão, e vai; e se alguém te encontrar, não o saúdes; e se alguém te saudar, não lhe respondas: e porás meu bordão sobre o rosto do menino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'E disse a mãe do menino: Vive o SENHOR, e vive tua alma, que não te deixarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Ele então se levantou, e seguiu-a. E Geazi havia ido diante deles, e havia posto o bordão sobre o rosto do menino, mas nem tinha voz nem sentido; e assim se havia voltado para encontrar a Eliseu; e declarou-o a ele, dizendo: O jovem não desperta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'E vindo Eliseu à casa, eis que o menino que estava estendido morto sobre sua cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Entrando ele então, fechou a porta sobre ambos, e orou ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Depois subiu, e lançou-se sobre o menino, pondo sua boca sobre a boca dele, e seus olhos sobre seus olhos, e suas mãos sobre as mãos suas; assim se estendeu sobre ele, e aqueceu a carne do jovem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Voltando-se logo, andou pela casa a uma parte e a outra, e depois subiu, e estendeu-se sobre ele; e o jovem espirrou sete vezes, e abriu seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Então ele chamou a Geazi, e disse-lhe: Chama a esta sunamita. E ele a chamou. E entrando ela, ele lhe disse: Toma teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'E assim que ela entrou, lançou-se a seus pés, e inclinou-se a terra: depois tomou seu filho, e saiu-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'E Eliseu se voltou a Gilgal. Havia então grande fome na terra. E os filhos dos profetas estavam com ele, pelo que disse a seu criado: Põe uma grande caçarola, e faze sopa para os filhos dos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'E saiu um ao campo a colher ervas, e achou uma como parreira selvagem, e agarrou dela uma capa de frutos silvestres; e voltou, e cortou-as na caçarola da sopa: porque não sabia o que era.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Serviu depois para que comessem os homens; mas sucedeu que comendo eles daquele guisado, deram vozes, dizendo: Homem de Deus, há morte na caçarola! E não o puderam comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Ele então disse: Trazei farinha. E espalhou-a na caçarola, e disse: Dá de comer à gente. E não houve mais mal na caçarola.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Veio então um homem de Baal-Salisa, o qual trouxe ao homem de Deus pães de primícias, vinte pães de cevada, e trigo novo em sua espiga. E ele disse: Da ao povo, para que comam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'E respondeu seu servente: Como porei isto diante de cem homens? Mas ele voltou a dizer: Da ao povo para que comam, porque assim disse o SENHOR: Comerão, e sobrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Então ele o pôs diante deles, e comeram, e sobrou-lhes, conforme a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naamã, general do exército do rei da Síria, era grande homem diante de seu senhor, e em alta estima, porque por meio dele o SENHOR havia dado salvamento à Síria. Era este homem valente em extremo, mas leproso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'E da Síria haviam saído tropas, e haviam levado cativa da terra de Israel uma menina; a qual servindo à mulher de Naamã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'disse à sua senhora: Se meu senhor rogasse ao profeta que está em Samaria, ele o sararia de sua lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'E Naamã, vindo a seu senhor, declarou-o a ele, dizendo: Assim e assim disse uma menina que é da terra de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'E disse-lhe o rei da Síria: Anda, vai, e eu enviarei cartas ao rei de Israel. Partiu, pois, ele, levando consigo dez talentos de prata, e seis mil peças de ouro, e dez mudas de roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Tomou também cartas para o rei de Israel, que diziam assim: Logo em chegando a ti estas cartas, sabe por elas que eu envio a ti meu servo Naamã, para que o sares de sua lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'E logo que o rei de Israel leu as cartas, rasgou suas roupas, e disse: Sou eu Deus, que mate e dê vida, para que este envie a mim a que sare um homem de sua lepra? Considerai agora, e vede como busca ocasião contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'E quando Eliseu, homem de Deus ouviu que o rei de Israel havia rasgado suas roupas, enviou a dizer ao rei: Por que rasgaste tuas vestes? Venha agora a mim, e saberá que há profeta em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'E veio Naamã com seus cavalos e com seu carro, e parou-se às portas da casa de Eliseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Então Eliseu lhe enviou um mensageiro, dizendo: Vai, e lava-te sete vezes no Jordão, e tua carne se te restaurará, e serás limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'E Naamã se foi irritado, dizendo: Eis que eu dizia para mim: Sairá ele logo, e estando em pé invocará o nome do SENHOR seu Deus, e levantará sua mão, e tocará o lugar, e sarará a lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Abana e Farpar, rios de Damasco, não são melhores que todas as águas de Israel? Se me lavar neles, não serei também limpo? E voltou-se, e foi-se irritado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Mas seus criados se chegaram a ele, e falaram-lhe, dizendo: Pai meu, se o profeta te mandasse alguma grande coisa, não a farias? Quanto mais, dizendo-te: Lava-te, e serás limpo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Ele então desceu, e mergulhou sete vezes no Jordão, conforme a palavra do homem de Deus; e sua carne se restaurou como a carne de um menino, e foi limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'E voltou ao homem de Deus, ele e toda sua companhia, e pôs-se diante dele, e disse: Eis que agora conheço que não há Deus em toda a terra, a não ser em Israel. Rogo-te que recebas algum presente de teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Mas ele disse: Vive o SENHOR, diante do qual estou, que não o tomarei. E insistindo-lhe que tomasse, ele não quis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Então Naamã disse: Rogo-te, pois, não se dará a teu servo uma carga de um par de mulas desta terra? Porque de agora em diante teu servo não sacrificará holocausto nem sacrifício a outros deuses, a não ser ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Em isto perdoe o SENHOR a teu servo: que quando meu senhor entrar no templo de Rimom, e para adorar nele se apoiar sobre minha mão, se eu também me inclinar no templo de Rimom, se no templo de Rimom me inclino, o SENHOR perdoe nisto a teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'E ele lhe disse: Vai em paz. Partiu-se, pois, dele, e caminhou como o espaço de uma milha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Então Geazi, criado de Eliseu o homem de Deus, disse entre si: Eis que meu senhor poupou a este sírio Naamã, não tomando de sua mão as coisas que havia trazido. Vive o SENHOR, que correrei eu atrás dele, e tomarei dele alguma coisa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'E Geazi seguiu Naamã; e quando Naamã lhe viu que vinha correndo atrás dele, desceu do carro para receber-lhe, e disse: Vai bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'E ele disse: Bem. Meu senhor me envia a dizer: Eis que vieram a mim nesta hora do monte de Efraim dois rapazes dos filhos dos profetas: rogo-te que lhes dês um talento de prata, e duas mudas de roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'E Naamã disse: Rogo-te que tomes dois talentos. E ele lhe constrangeu, e atou dois talentos de prata em dois sacos, e duas mudas de roupas, e o pôs às costas a dois de seus criados, que o levassem diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'E chegado que houve a um lugar secreto, ele o tomou da mão deles, e guardou-o em casa: logo mandou aos homens que se fossem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'E ele entrou, e pôs-se diante de seu senhor. E Eliseu lhe disse: De onde vens, Geazi? E ele disse: Teu servo não foi a nenhuma parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'O então lhe disse: Não foi também meu coração, quando o homem voltou de seu carro a receber-te? É tempo de tomar prata, e de tomar roupas, olivais, vinhas, ovelhas, bois, servos e servas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'A lepra de Naamã se apegará a ti e à tua semente para sempre. E saiu de diante dele leproso, branco como a neve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Os filhos dos profetas disseram a Eliseu: Eis que o lugar em que moramos contigo nos é estreito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Vamos agora ao Jordão, e tomemos dali cada um uma viga, e façamo-nos ali lugar em que habitemos. E ele disse: Andai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'E disse um: Rogamos-te que queiras vir com teus servos. E ele respondeu: Eu irei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Foi-se, pois, com eles; e como chegaram ao Jordão, cortaram a madeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'E aconteceu que derrubando uma árvore, caiu o machado na água; e deu vozes, dizendo: Ah, senhor meu, que era emprestada!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'E o homem de Deus disse: Onde caiu? E ele lhe mostrou o lugar. Então cortou ele um pau, e lançou-o ali; e fez flutuar o ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'E disse: Toma-o. E ele estendeu a mão, e tomou-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Tinha o rei da Síria guerra contra Israel, e consultando com seus servos, disse: Em tal e tal lugar estará meu acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'E o homem de Deus enviou a dizer ao rei de Israel: Olha que não passes por tal lugar, porque os sírios vão ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Então o rei de Israel enviou a aquele lugar que o homem de Deus havia dito e alertado-lhe; e guardou-se dali, não uma vez nem duas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'E o coração do rei da Síria foi perturbado disto; e chamando a seus servos, disse-lhes: Não me declarareis vós quem dos nossos é do rei de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Então um dos servos disse: Não, rei, senhor meu; mas sim que o profeta Eliseu está em Israel, o qual declara ao rei de Israel as palavras que tu falas em tua mais secreta câmara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'E ele disse: Ide, e olhai onde está, para que eu envie a tomá-lo. E foi-lhe dito: Eis que ele está em Dotã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Então enviou o rei ali cavaleiros, e carros, e um grande exército, os quais vieram de noite, e cercaram a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'E levantando-se de manhã o que servia ao homem de Deus, para sair, eis que o exército que tinha cercado a cidade, com cavaleiros e carros. Então seu criado lhe disse: Ah, senhor meu! Que faremos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'E ele lhe disse: Não tenhas medo: porque mais são os que estão com nós que os que estão com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'E orou Eliseu, e disse: Rogo-te, ó SENHOR, que abras seus olhos para que veja. Então o SENHOR abriu os olhos do jovem, e olhou; e eis que o monte estava cheio de cavaleiros, e de carros de fogo ao redor de Eliseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'E logo que os sírios desceram a ele, orou Eliseu ao SENHOR, e disse: Rogo-te que firas a esta gente com cegueira. E feriu-os com cegueira, conforme ao dito de Eliseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Depois lhes disse Eliseu: Não é este o caminho, nem é esta a cidade; segui-me, que eu vos guiarei ao homem que buscais. E guiou-os a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'E assim que chegaram a Samaria, disse Eliseu: SENHOR, abre os olhos destes, para que vejam. E o SENHOR abriu seus olhos, e olharam, e acharam-se em meio de Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'E quando o rei de Israel os havia visto, disse a Eliseu: Eu os ferirei, pai meu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'E ele lhe respondeu: Não os firas; feririas tu aos que tomaste cativos com tua espada e com teu arco? Põe diante deles pão e água, para que comam e bebam, e se voltem a seus senhores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Então lhes foi preparada grande comida: e quando houveram comido e bebido, enviou-os, e eles se voltaram a seu senhor. E nunca mais tropas da Síria vieram à terra de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Depois disto aconteceu, que Ben-Hadade rei da Síria juntou todo seu exército, e subiu, e pôs cerco a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'E houve grande fome em Samaria, tendo eles cerco sobre ela; tanto, que a cabeça de um asno era vendida por oitenta peças de prata, e a quarta parte de uma porção de esterco de pombas por cinco peças de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'E passando o rei de Israel pelo muro, uma mulher lhe deu vozes, e disse: Socorro, rei senhor meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'E ele disse: Se não te salva o SENHOR, de onde te tenho de salvar eu? Do granário, ou do lagar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'E disse-lhe o rei: Que tens? E ela respondeu: Esta mulher me disse: Dá aqui o teu filho, e o comamos hoje, e amanhã comeremos o meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Cozinhamos, pois, meu filho, e o comemos. O dia seguinte eu lhe disse: Dá aqui o teu filho, e o comamos. Mas ela escondeu seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'E quando o rei ouviu as palavras daquela mulher, rasgou suas roupas, e passou assim pelo muro: e chegou a ver o povo o saco que trazia interiormente sobre sua carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'E ele disse: Assim me faça Deus, e assim me acrescente, se a cabeça de Eliseu filho de Safate restar sobre ele hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Estava naquele tempo Eliseu sentado em sua casa, e com ele estavam sentados os anciãos: e o rei enviou a ele um homem. Mas antes que o mensageiro viesse a ele, disse ele aos anciãos: Não vistes como este homicida me envia a tirar a cabeça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Ainda estava ele falando com eles, e eis que o mensageiro que descia a ele; e disse: Certamente este mal vem do SENHOR. Para que tenho de esperar mais ao SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Disse então Eliseu: Ouvi palavra do SENHOR: Assim disse o SENHOR: Amanhã a estas horas valerá a medida de flor de farinha um siclo, e duas medidas de cevada um siclo, à porta de Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'E um príncipe sobre cuja mão o rei se apoiava, respondeu ao homem de Deus, e disse: Se o SENHOR fizesse agora janelas no céu, seria isto assim? E ele disse: Eis que tu o verás com teus olhos, mas não comerás disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'E havia quatro homens leprosos à entrada da porta, os quais disseram o um ao outro: Para que nos estamos aqui até que morramos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Se tratarmos de entrar na cidade, pela fome que há na cidade morreremos nela; e se nos ficamos aqui, também morreremos. Vamos pois agora, e passemo-nos ao exército dos sírios; se eles nos derem a vida, viveremos; e se nos derem a morte, morreremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Levantaram-se pois no princípio da noite, para ir-se ao campo dos sírios; e chegando aos primeiros abrigos dos sírios, não havia ali homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Porque o Senhor havia feito que no campo dos sírios se ouvisse estrondo de carros, ruído de cavalos, e barulho de grande exército; e disseram-se os uns aos outros: Eis que o rei de Israel pagou contra nós aos reis dos heteus, e aos reis dos egípcios, para que venham contra nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'E assim se haviam levantado e fugido ao princípio da noite, deixando suas tendas, seus cavalos, seus asnos, e o campo como se estava; e haviam fugido por salvar as vidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'E quando os leprosos chegaram aos primeiros abrigos, entraram-se em uma tenda, e comeram e beberam, e tomaram dali prata, e ouro, e vestido, e foram, e esconderam-no: e voltados, entraram em outra tenda, e dali também tomaram, e foram, e esconderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'E disseram-se o um ao outro: Não fazemos bem: hoje é dia de boa nova, e nós calamos: e se esperamos até a luz da manhã, nos alcançará a maldade. Vamos pois agora, entremos, e demos a nova em casa do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'E vieram, e deram vozes aos guardas da porta da cidade, e declararam-lhes, dizendo: Nós fomos ao campo dos sírios, e eis que não havia ali homem, nem voz de homem, a não ser cavalos atados, asnos também atados, e o campo como se estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'E os porteiros deram vozes, e declararam-no dentro, no palácio do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'E levantou-se o rei de noite, e disse a seus servos: Eu vos declararei o que nos fizeram os sírios. Eles sabem que temos fome, e saíram das tendas e esconderam-se no campo, dizendo: Quando houverem saído da cidade, os tomaremos vivos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Então respondeu um de seus servos, e disse: Tomem agora cinco dos cavalos que restaram na cidade, (porque eles também são como toda a multidão de Israel que restou nela; também eles são como toda a multidão de Israel que pereceu); e enviemos, e vejamos o que há.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Tomaram, pois, dois cavalos de um carro, e enviou o rei atrás o campo dos sírios, dizendo: Ide, e vede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'E eles foram, e seguiram-nos até o Jordão: e eis que, todo o caminho estava cheio de roupas e utensílios que os sírios haviam lançado com a pressa. E voltaram os mensageiros, e fizeram-no saber ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Então o povo saiu, e saquearam o campo dos sírios. E foram vendidos uma medida de flor de farinha por um siclo, e duas medidas de cevada por um siclo, conforme a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'E o rei pôs à porta a aquele príncipe sobre cuja mão ele se apoiava: e atropelou-lhe o povo à entrada, e morreu, conforme o que havia dito o homem de Deus, o que falou quando o rei desceu a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Aconteceu, pois, da maneira que o homem de Deus havia falado ao rei, dizendo: Duas medidas de cevada por um siclo, e a medida de flor de farinha será vendida por um siclo amanhã a estas horas, à porta de Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Ao qual aquele príncipe havia respondido ao homem de Deus, dizendo: Ainda que o SENHOR fizesse janelas no céu, poderia ser isso? E ele disse: Eis que tu o verás com teus olhos, mas não comerás disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'E veio-lhe assim; porque o povo lhe atropelou à entrada, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'E falou Eliseu àquela mulher a cujo filho havia feito viver, dizendo: Levanta-te, vai-te tu e toda tua casa a viver de onde puderes; porque o SENHOR chamou a fome, a qual virá também sobre a terra sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Então a mulher se levantou, e fez como o homem de Deus lhe disse: e partiu-se ela com sua família, e viveu em terra dos filisteus sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'E quando foram passados os sete anos, a mulher voltou da terra dos filisteus: depois saiu para clamar ao rei por sua casa, e por suas terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'E havia o rei falado com Geazi, criado do homem de Deus, dizendo-lhe: Rogo-te que me contes todas as maravilhas que fez Eliseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'E contando ele ao rei como havia feito viver a um morto, eis que a mulher, a cujo filho havia feito viver, que clamava ao rei por sua casa e por suas terras. Então disse Geazi: Rei senhor meu, esta é a mulher, e este é seu filho, ao qual Eliseu fez viver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'E perguntando o rei à mulher, ela lhe contou. Então o rei lhe deu um eunuco, dizendo-lhe: Faze-lhe voltar todas as coisas que eram suas, e todos os frutos das terras desde o dia que deixou o país até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Eliseu se foi logo a Damasco, e Ben-Hadade rei da Síria estava enfermo, ao qual deram aviso, dizendo: O homem de Deus veio aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'E o rei disse a Hazael: Toma em tua mão um presente, e vai a receber ao homem de Deus, e consulta por ele ao SENHOR, dizendo: Sararei desta enfermidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Tomou pois Hazael em sua mão um presente de todos os bens de Damasco, quarenta camelos carregados, e saiu-o a receber: e chegou, e pôs-se diante dele, e disse: Teu filho Ben-Hadade, rei da Síria, me enviou a ti, dizendo: Sararei desta enfermidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'E Eliseu lhe disse: Vai, dize-lhe: Seguramente viverás. Porém o SENHOR me mostrou que ele morrerá certamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'E o homem de Deus lhe voltou o rosto fixamente, até o deixar desconcertado; então o homem de Deus chorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Então disse-lhe Hazael: Por que chora meu senhor? E ele respondeu: Porque sei o mal que farás aos filhos de Israel: a suas fortalezas pegarás fogo, e a seus rapazes matarás à espada, e despedaçarás a seus meninos, e rasgarás ao meio a suas grávidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'E Hazael disse: O que é o teu servo, um cão, para que ele faça esta grande coisa? E respondeu Eliseu: o SENHOR me mostrou que tu serás rei da Síria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'E ele se partiu de Eliseu, e veio a seu senhor, o qual lhe disse: Que te disse Eliseu? E ele respondeu: Disse-me que seguramente viverás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'O dia seguinte tomou um pano grosso, e meteu-o em água, e estendeu-os sobre o rosto de Ben-Hadade, e morreu: e reinou Hazael em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'No quinto ano de Jorão filho de Acabe rei de Israel, e sendo Josafá rei de Judá, começou a reinar Jeorão filho de Josafá rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'De trinta e dois anos era quando começou a reinar, e oito anos reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'E andou no caminho dos reis de Israel, como fez a casa de Acabe, porque uma filha de Acabe foi sua mulher; e fez o que era mau aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Contudo, o SENHOR não quis destruir Judá, por amor de Davi seu servo, como lhe havia prometido dar-lhe lâmpada de seus filhos perpetuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Em seu tempo Edom rebelou-se de sob o domínio de Judá, e puseram rei sobre si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Jeorão, portanto, passou a Seir, e todos seus carros com ele: e levantando-se de noite feriu aos edomitas, os quais lhe haviam cercado, e aos capitães dos carros: e o povo fugiu a suas moradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Separou-se não obstante Edom de sob a domínio de Judá, até hoje. Rebelou-se ademais Libna no mesmo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Os demais dos feitos de Jeorão, e todas as coisas que fez, não estão escritos no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'E descansou Jeorão com seus pais, e foi sepultado com seus pais na cidade de Davi: e reinou em lugar seu Acazias, seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'No ano doze de Jeorão filho de Acabe rei de Israel, começou a reinar Acazias filho de Jeorão rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'De vinte e dois anos era Acazias quando começou a reinar, e reinou um ano em Jerusalém. O nome de sua mãe foi Atalia filha de Onri rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'E andou no caminho da casa de Acabe, e fez o que era mau aos olhos do SENHOR, como a casa de Acabe: porque era genro da casa de Acabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'E foi à guerra com Jorão filho de Acabe a Ramote de Gileade, contra Hazael rei da Síria; e os sírios feriram a Jorão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'E o rei Jorão se voltou a Jezreel, para curar-se das feridas que os sírios lhe fizeram diante de Ramote, quando lutou contra Hazael rei da Síria. E desceu Acazias filho de Jeorão rei de Judá, para visitar Jorão filho de Acabe em Jezreel, porque estava enfermo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Então o profeta Eliseu chamou a um dos filhos dos profetas, e disse-lhe: Cinge teus lombos, e toma esta vasilha de azeite em tua mão, e vai a Ramote de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'E quando chegares ali, verás ali a Jeú filho de Josafá filho de Ninsi; e entrando, faze-o se levantar dentre seus irmãos, e mete-o na recâmara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Toma logo a vasilha de azeite, e derrama-a sobre sua cabeça, e dize: Assim disse o SENHOR: Eu te ungi por rei sobre Israel. E abrindo a porta, lança-te a fugir, e não esperes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Foi, pois, o jovem, o jovem do profeta, a Ramote de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'E quando ele entrou, eis que os príncipes do exército que estavam sentados. E ele disse: Príncipe, uma palavra tenho que dizer-te. E Jeú disse: A qual de todos nós? E ele disse: A ti, príncipe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'E ele se levantou, e entrou-se em casa; e o outro derramou o azeite sobre sua cabeça, e disse-lhe: Assim disse o SENHOR Deus de Israel: Eu te ungi por rei sobre o povo do SENHOR, sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'E ferirás a casa de Acabe teu senhor, para que eu vingue o sangue de meus servos os profetas, e o sangue de todos os servos do SENHOR, da mão de Jezabel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'E perecerá toda a casa de Acabe, e exterminarei de Acabe todo macho, tanto ao escravo como ao livre em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'E eu porei a casa de Acabe como a casa de Jeroboão filho de Nebate, e como a casa de Baasa filho de Aías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'E a Jezabel comerão cães no campo de Jezreel, e não haverá quem a sepulte. Em seguida abriu a porta, e lançou a fugir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Depois saiu Jeú aos servos de seu senhor, e disseram-lhe: Há paz? para que entrou a ti aquele louco? E ele lhes disse: Vós conheceis ao homem e suas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'E eles disseram: Mentira; declara-o a nós agora. E ele disse: Assim e assim me falou, dizendo: Assim disse o SENHOR: Eu te ungi por rei sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Então tomaram prontamente sua roupa, e a pôs cada um debaixo dele em um trono alto, e tocaram trombeta, e disseram: Jeú é rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Assim conjurou Jeú filho de Josafá filho de Ninsi, contra Jorão. (Estava Jorão guardando a Ramote de Gileade com todo Israel, por causa de Hazael rei da Síria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Havia-se, porém, voltado o rei Jorão a Jezreel, para curar-se das feridas que os sírios lhe haviam feito, lutando contra Hazael rei da Síria.) E Jeú disse: Se é vossa vontade, ninguém escape da cidade, para ir a dar as novas em Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Então Jeú cavalgou, e foi-se a Jezreel, porque Jorão estava ali enfermo. Também Acazias rei de Judá havia descido a visitar a Jorão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'E o atalaia que estava na torre de Jezreel, viu a tropa de Jeú, que vinha, e disse: Eu vejo uma tropa. E Jorão disse: Toma um cavaleiro, e envia a reconhecê-los, e que lhes diga: Há paz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Foi pois o cavaleiro a reconhecê-los, e disse: O rei diz assim: Há paz? E Jeú lhe disse: Que tens tu que ver com a paz? Sai da minha frente. O atalaia deu logo aviso, dizendo: O mensageiro chegou até eles, e não volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Então enviou outro cavaleiro, o qual chegando a eles, disse: O rei diz assim: Há paz? E Jeú respondeu: Que tens tu que ver com a paz? Sai da minha frente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'O atalaia voltou a dizer: Também este chegou a eles e não volta: mas o marchar do que vem é como o marchar de Jeú filho de Ninsi, porque vem impetuosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Então Jorão disse: Prepara. E preparado que foi seu carro, saiu Jorão rei de Israel, e Acazias rei de Judá, cada um em seu carro, e saíram a encontrar a Jeú, ao qual acharam na propriedade de Nabote de Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'E em vendo Jorão a Jeú, disse: Há paz, Jeú? E ele respondeu: Que paz, com as fornicações de Jezabel tua mãe, e suas muitas feitiçarias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Então Jorão virando a mão fugiu, e disse a Acazias: Traição, Acazias!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Mas Jeú flechou seu arco, e feriu a Jorão entre as costas, e a seta saiu por seu coração, e caiu em seu carro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Disse logo Jeú a Bidcar seu capitão: Toma-o e lança-o em um lugar da propriedade de Nabote de Jezreel. Lembra-te que quando tu e eu íamos juntos com a gente de Acabe seu pai, o SENHOR pronunciou esta sentença sobre ele, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Que eu vi ontem os sangues de Nabote, e os sangues de seus filhos, disse o SENHOR; e tenho de dar-te a paga nesta propriedade, disse o SENHOR. Toma-lhe pois agora, e lança-o na propriedade, conforme à palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'E vendo isto Acazias rei de Judá, fugiu pelo caminho da casa da horta. E siguiu-o Jeú, dizendo: Feri também a este no carro. E lhe feriram à subida de Gur, junto a Ibleão. E ele fugiu a Megido, e morreu ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'E seus servos lhe levaram em um carro a Jerusalém, e ali lhe sepultaram com seus pais, em seu sepulcro na cidade de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'No décimo primeiro ano de Jorão filho de Acabe, começou a reinar Acazias sobre Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Veio depois Jeú a Jezreel: e quando Jezabel o ouviu, adornou seus olhos, enfeitou sua cabeça, e ficou observando em uma janela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'E quando entrava Jeú pela porta, ela disse: Sucedeu bem a Zinri, que matou a seu senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Levantando ele então seu rosto até a janela, disse: Quem é comigo? Quem? E olharam até ele dois ou três eunucos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'E ele lhes disse: Lançai-a abaixo. E eles a lançaram: e parte de seu sangue foi salpicado na parede, e nos cavalos; e ele a atropelou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Entrou logo, e depois que comeu e bebeu, disse: Ide agora a ver aquela maldita, e sepultai-a; que é filha de rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Porém quando foram para sepultá-la, não acharam dela mais que o crânio, e os pés, e as palmas das mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'E voltaram, e disseram-no. E ele disse: A palavra de Deus é esta, a qual ele falou por meio de seu servo Elias Tisbita, dizendo: Na propriedade de Jezreel comerão os cães as carnes de Jezabel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'E o corpo de Jezabel foi qual lixo sobre a face da terra na herdade de Jezreel; de maneira que ninguém podia dizer: Esta é Jezabel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'E tinha Acabe em Samaria setenta filhos; e escreveu cartas Jeú, e enviou-as a Samaria aos principais de Jezreel, aos anciãos e aos tutores de Acabe, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Logo em chegando estas cartas a vós o que tendes os filhos de vosso senhor, e os que tendes carros e cavaleiros, a cidade fortificada, e as armas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Olhai qual é o melhor e ele mais reto dos filhos de vosso senhor, e ponde-o no trono de seu pai, e lutai pela casa de vosso senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Mas eles tiveram grande temor, e disseram: Eis que dois reis não puderam resistir-lhe, como lhe resistiremos nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'E o mordomo, e o governador da cidade, e os anciãos, e os tutores, enviaram a dizer a Jeú: Servos teus somos, e faremos tudo o que nos mandares: não elegeremos por rei a ninguém; tu farás o que bem te parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Ele então lhes escreveu a segunda vez dizendo: Se sois meus, e quereis obedecer-me, tomai os chefes dos homens filhos de vosso senhor, e vinde amanhã a estas horas a mim a Jezreel. E os filhos do rei, setenta homens, estavam com os principais da cidade, que os criavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'E quando as cartas chegaram a eles, tomaram aos filhos do rei, e degolaram setenta homens, e puseram suas cabeças em cestos, e enviaram-nas a Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'E veio um mensageiro que lhe deu as novas, dizendo: Trouxeram as cabeças dos filhos do rei. E ele lhe disse: Ponde-as em dois amontoados à entrada da porta até a manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Vinda a manhã, saiu ele, e estando em pé disse a todo o povo: Vós sois justos: eis que eu conspirei contra meu senhor, e o mateis: mas quem matou a todos estes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Sabei agora que da palavra do SENHOR que falou sobre a casa de Acabe, nada cairá em terra: e que o SENHOR fez o que disse por seu servo Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Matou então Jeú a todos os que haviam restado da casa de Acabe em Jezreel, e a todos seus príncipes, e a todos seus familiares, e a seus sacerdotes, que não lhe restou ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'E levantou-se dali, e veio a Samaria; e chegando ele no caminho a uma casa de tosa de pastores,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Achou ali aos irmãos de Acazias rei de Judá, e disse-lhes: Quem sois vós? E eles disseram: Somos irmãos de Acazias, e viemos a saudar aos filhos do rei, e aos filhos da rainha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Então ele disse: Prendei-os vivos. E depois que os tomaram vivos, eles os degolaram junto ao poço da casa de tosa, quarenta e dois homens, sem deixar ninguém deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Partindo-se logo dali encontrou-se com Jonadabe filho de Recabe; e depois que o saudou, disse-lhe: É reto teu coração, como o meu é reto com o teu? E Jonadabe disse: O é. Pois que o é, dá-me a mão. E ele lhe deu sua mão. Fê-lo logo subir consigo no carro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'E disse-lhe: Vem comigo, e verás meu zelo pelo SENHOR. Puseram-no pois em seu carro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'E logo que havia Jeú chegado a Samaria, matou a todos os que haviam restado de Acabe em Samaria, até extirpá-los, conforme à palavra do SENHOR, que havia falado por Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'E juntou Jeú todo o povo, e disse-lhes: Acabe serviu pouco a Baal; mas Jeú o servirá muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Chamai-me, pois, logo a todos os profetas de Baal, a todos seus servos, e a todos seus sacerdotes; que não falte um, porque tenho um grande sacrifício para Baal; qualquer um que faltar, não viverá. Isto fazia Jeú com astúcia, para destruir aos que honravam a Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'E disse Jeú: Santificai um dia solene a Baal. E eles convocaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'E enviou Jeú por todo Israel, e vieram todos os servos de Baal, que não faltou ninguém que não viesse. E entraram no templo de Baal, e o templo de Baal se encheu de fim a fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Então disse ao que tinha o cargo das vestiduras: Tira vestiduras para todos os servos de Baal. E ele lhes tirou vestimentas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'E entrou Jeú com Jonadabe filho de Recabe no templo de Baal, e disse aos servos de Baal: Olhai e vede que por dita não haja aqui entre vós algum dos servos do SENHOR, a não ser somente os servos de Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'E quando eles entraram para fazer sacrifícios e holocaustos, Jeú pôs fora oitenta homens, e disse-lhes: Qualquer um que deixar vivo algum daqueles homens que eu pus em vossas mãos, sua vida será pela do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'E depois que acabaram eles de fazer o holocausto, Jeú disse aos de seu guarda e aos capitães: Entrai, e matai-os; que não escape ninguém. E os feriram à espada: e os da guarda e os capitães os lançaram fora, e foram até a cidade do templo de Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'E tiraram as estátuas da casa de Baal, e queimaram-nas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'E quebraram a estátua de Baal, e derrubaram a casa de Baal, e fizeram-na latrina, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Assim extinguiu Jeú a Baal de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Contudo isso Jeú não se separou dos pecados de Jeroboão filho de Nebate, que fez pecar a Israel; a saber, seguindo o os bezerros de ouro que estavam em Betel e em Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'E o SENHOR disse a Jeú: Porquanto fizeste bem executando o que era correto diante de meus olhos, e fizeste à casa de Acabe conforme a tudo o que estava em meu coração, teus filhos se sentarão no trono de Israel até a quarta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mas Jeú não cuidou de andar na lei do SENHOR Deus de Israel com todo seu coração, nem se separou dos pecados de Jeroboão, o que havia feito pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Em aqueles dias começou o SENHOR a diminuir o território de Israel: e feriu-os Hazael em todos os termos de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Desde o Jordão ao oriente, toda a terra de Gileade, de Gade, de Rúben, e de Manassés, desde Aroer que está junto ao ribeiro de Arnom, a Gileade e a Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Os demais dos feitos de Jeú, e todas as coisas que fez, e toda sua valentia, não estão escritos no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'E dormiu Jeú com seus pais, e sepultaram-no em Samaria: e reinou em seu lugar Jeoacaz seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'O tempo que reinou Jeú sobre Israel em Samaria, foi vinte e oito anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'E Atalia mãe de Acazias, vendo que seu filho era morto, levantou-se, e destruiu toda a semente real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Porém Jeoseba, filha do rei Jeorão, irmã de Acazias, tomando a Joás filho de Acazias, tirou-o dentre os filhos do rei, que se matavam, e ocultou-o de diante de Atalia, a ele e a sua ama, na câmara das camas, e assim não o mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'E esteve com ela escondido na casa do SENHOR seis anos: e Atalia foi rainha sobre o país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Mas ao sétimo ano enviou Joiada, e tomou comandantes de cem, capitães, e gente da guarda, e meteu-os consigo na casa do SENHOR: e fez com eles liga, juramentando-os na casa do SENHOR; e mostrou-lhes ao filho do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'E mandou-lhes, dizendo: Isto é o que haveis de fazer: a terceira parte de vós, os que entrarão o sábado, terão a guarda da casa do rei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'E a outra terceira parte estará à porta do Sur, e a outra terceira parte à porta da entrada dos da guarda: assim guardareis a casa, para que não seja invadida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'E as duas partes de vós, a saber, todos os que saem o sábado, tereis a guarda da casa do SENHOR junto ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'E estareis ao redor do rei de todas as partes, tendo cada um suas armas nas mãos, e qualquer um que entrar por estas fileiras, seja morto. E haveis de estar com o rei quando sair, e quando entrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Os comandantes de cem, pois, fizeram tudo como o sacerdote Joiada lhes mandou: e tomando cada um os seus, a saber, os que haviam de entrar o sábado, e os que haviam saído o sábado, vieram a Joiada o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'E o sacerdote deu aos comandantes de cem as lanças e os escudos que haviam sido do rei Davi, que estavam na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'E os da guarda se puseram em ordem, tendo cada um suas armas em suas mãos, desde o lado direito da casa até o lado esquerdo, junto ao altar e o templo, em derredor do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Tirando logo Joiada ao filho do rei, pôs-lhe a coroa e o testemunho, e fizeram-lhe rei ungindo-lhe; e batendo as mãos disseram: Viva o rei!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'E ouvindo Atalia o estrondo do povo que corria, entrou ao povo no templo do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'E quando olhou, eis que o rei que estava junto à coluna, conforme o costume, e os príncipes e os trombetas junto ao rei; e que todo o povo do país fazia alegrias, e que tocavam as trombetas. Então Atalia, rasgando suas roupas, clamou em gritos: Traição! Traição!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Mas o sacerdote Joiada mandou aos comandantes de cem que governavam o exército, e disse-lhes: Tirai-a fora do recinto do templo, e ao que a seguir, matai-o à espada. (Porque o sacerdote disse que não a matassem no templo do SENHOR.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Deram-lhe, pois, lugar, e quando ia o caminho por de onde entram os cavaleiros à casa do rei, ali a mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Então Joiada fez aliança entre o SENHOR e o rei e o povo, que seriam povo do SENHOR: e também entre o rei e o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'E todo o povo da terra entrou no templo de Baal, e derrubaram-no: também despedaçaram inteiramente seus altares e suas imagens, e mataram a Matã sacerdote de Baal diante dos altares. E o sacerdote pôs guarnição sobre a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Depois tomou os centuriões, e capitães, e os da guarda, e a todo o povo da terra, e levaram ao rei desde a casa do SENHOR, e vieram pelo caminho da porta dos da guarda à casa do rei; e sentou-se o rei sobre o trono dos reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'E todo o povo da terra fez alegrias, e a cidade esteve em repouso, havendo sido Atalia morta à espada junto à casa do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Era Joás de sete anos quando começou a reinar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'No sétimo ano de Jeú começou a reinar Joás, e reinou quarenta anos em Jerusalém. O nome de sua mãe foi Zíbia, de Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'E Joás fez o que era coreto aos olhos do SENHOR todo o tempo que o sacerdote Joiada o conduziu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Contudo isso os altos não se tiraram; que ainda sacrificava e queimava o povo incenso nos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'E Joás disse aos sacerdotes: Todo o dinheiro das santificações que se costuma trazer à casa do SENHOR, o dinheiro dos que passam no censo, o dinheiro pelas pessoas, cada qual segundo seu valor, e todo o dinheiro que cada um de sua própria vontade põe na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Recebam-no os sacerdotes, cada um de seus familiares, e reparem as fendas do templo de onde quer que se achar abertura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Porém o ano vinte e três do rei Joás, não haviam ainda reparado os sacerdotes as aberturas do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Chamando então o rei Joás ao sacerdote Joiada e aos sacerdotes, disse-lhes: Por que não reparais as aberturas do templo? Agora, pois, não tomeis mais o dinheiro de vossos familiares, mas sim dai-o para reparar as fendas do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'E os sacerdotes consentiram em não tomar mais dinheiro do povo, nem ter cargo de reparar as aberturas do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Mas o sacerdote Joiada tomou uma arca, e fez-lhe na tampa um furo, e a pôs junto ao altar, à direita quando se entra no templo do SENHOR; e os sacerdotes que guardavam a porta, punham ali todo o dinheiro que se metia na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'E quando viam que havia muito dinheiro no arca, vinha o notário do rei e o grande sacerdote, e contavam o dinheiro que achavam no templo do SENHOR, e guardavam-no.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'E davam o dinheiro suficiente em mão dos que faziam a obra, e dos que tinham o cargo da casa do SENHOR; e eles o gastavam em pagar os carpinteiros e mestres que reparavam a casa do SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'E os pedreiros e cortadores de pedras; e em comprar a madeira e pedra lavrada para reparar as aberturas da casa do SENHOR; e em tudo o que se gastava na casa para repará-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Mas daquele dinheiro que se trazia à casa do SENHOR, não se faziam bacias de prata, nem saltérios, nem bacias, nem trombetas; nem nenhum outro vaso de ouro nem de prata se fazia para o templo do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Porque o davam aos que faziam a obra, e com ele reparavam a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'E não se tomava em conta aos homens em cujas mãos o dinheiro era entregue, para que eles o dessem aos que faziam a obra: porque o faziam eles fielmente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'O dinheiro pelo delito, e o dinheiro pelos pecados, não se metia na casa do SENHOR; porque era dos sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Então subiu Hazael rei da Síria, e lutou contra Gate, e tomou-a; e Hazael decidiu subir contra Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Pelo que tomou Joás rei de Judá todas as ofertas que havia dedicado Josafá, e Jorão e Acazias seus pais, reis de Judá, e as que ele havia dedicado, e todo o ouro que se achou nos tesouros da casa do SENHOR, e na casa do rei, e enviou-o a Hazael, rei da Síria; e ele se partiu de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Os demais dos feitos de Joás, e todas as coisas que fez, não estão escritos no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'E seus servos se levantaram, fizeram uma conspiração, e mataram a Joás na casa de Milo, quando ele estava descendo a Sila;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Pois Jozacar filho de Simeate, e Jozabade filho de Somer, seus servos, feriram-lhe, e ele morreu. E sepultaram-lhe com seus pais na cidade de Davi, e reinou em seu lugar Amasias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'No ano vinte e três de Joás filho de Acazias, rei de Judá, começou a reinar Jeoacaz filho de Jeú sobre Israel em Samaria; e reinou dezessete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'E fez o que era mau aos olhos do SENHOR, e seguiu os pecados de Jeroboão filho de Nebate, o que fez pecar a Israel; e não se separou deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'E acendeu-se o furor do SENHOR contra Israel, e entregou-os em mão de Hazael rei da Síria, e em mão de Ben-Hadade filho de Hazael, por longo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Mas Jeoacaz orou à face do SENHOR, e o SENHOR o ouviu: porque olhou a aflição de Israel, pois o rei da Síria os afligia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, '(E deu o SENHOR salvador a Israel, e saíram de sob a mão dos sírios; e habitaram os filhos de Israel em suas moradas, como antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Contudo isso não se apartaram dos pecados da casa de Jeroboão, o que fez pecar a Israel: neles andaram; e também o bosque permaneceu em Samaria.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Porque não lhe havia restado gente a Jeoacaz, a não ser cinquenta cavaleiros, e dez carros, e dez mil homens a pé; pois o rei da Síria os havia destruído, e os havia posto como pó para pisar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Os demais dos feitos de Jeoacaz, e tudo o que fez, e suas valentias, não estão escritos no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'E descansou Jeoacaz com seus pais, e sepultaram-no em Samaria: e reinou em seu lugar Joás seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'O ano trinta e sete de Joás rei de Judá, começou a reinar Joás filho de Jeoacaz sobre Israel em Samaria; e reinou dezesseis anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'E fez o que era mau aos olhos do SENHOR: não se separou de todos os pecados de Jeroboão filho de Nebate, o que fez pecar a Israel; neles andou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Os demais dos feitos de Joás, e todas as coisas que fez, e seu esforço com que guerreou contra Amasias rei de Judá, não estão escritos no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'E dormiu Joás com seus pais, e sentou-se Jeroboão sobre seu trono: e Joás foi sepultado em Samaria com os reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Estava Eliseu enfermo daquela sua enfermidade de que morreu. E desceu a ele Joás rei de Israel, e chorando diante dele, disse: Meu pai, meu pai, carro de Israel e seus cavaleiros!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'E disse-lhe Eliseu: Toma um arco e umas flechas. Tomou ele então um arco e umas flechas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'E disse Eliseu ao rei de Israel: Põe tua mão sobre o arco. E pôs ele sua mão sobre o arco. Então pôs Eliseu suas mãos sobre as mãos do rei,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'E disse: Abre a janela de até o oriente. E quando ele a abriu disse Eliseu: Atira. E atirando ele, disse Eliseu: Flecha de salvação do SENHOR, e flecha de salvação contra Síria: porque ferirás aos sírios em Afeque, até consumi-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'E voltou-lhe a dizer: Toma as flechas. E logo que o rei de Israel as tomou, disse-lhe: Fere a terra. E ele feriu três vezes, e cessou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Então o homem de Deus, irou-se com ele, lhe disse: A ferir cinco ou seis vezes, feririas a Síria, até não restar ninguém: porém agora três vezes ferirás a Síria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'E morreu Eliseu, e sepultaram-no. Entrado o ano vieram tropas de moabitas à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'E aconteceu que ao sepultar uns um homem, subitamente viram uma tropa, e lançaram ao homem no sepulcro de Eliseu: e quando o morto chegou a tocar os ossos de Eliseu, reviveu, e levantou-se sobre seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Hazael, pois, rei da Síria, afligiu a Israel todo o tempo de Jeoacaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mas o SENHOR teve misericórdia deles, e compadeceu-se deles, e olhou-os, por amor de seu pacto com Abraão, Isaque e Jacó; e não quis destruí-los nem lançá-los de diante de si até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'E morreu Hazael rei da Síria, e reinou em seu lugar Ben-Hadade seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'E voltou Joás filho de Jeoacaz, e tomou da mão de Ben-Hadade filho de Hazael, as cidades que ele havia tomado da mão de Jeoacaz seu pai em guerra. Três vezes o bateu Joás, e restituiu as cidades a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'No ano segundo de Joás filho de Jeoacaz rei de Israel, começou a reinar Amazias filho de Joás rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Quando começou a reinar era de vinte e cinco anos, e reinou vinte e nove anos em Jerusalém: o nome de sua mãe foi Jeoadã, de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'E ele fez o que era correto aos olhos do SENHOR, ainda que não como Davi seu pai: fez conforme a todas as coisas que havia feito Joás seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Contudo isso os altos não foram tirados; que o povo ainda sacrificava e queimava incenso nos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'E logo que o reino foi confirmado em sua mão, feriu a seus servos, os que haviam matado ao rei seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mas não matou aos filhos dos que lhe mataram, conforme o que está escrito no livro da lei de Moisés, de onde o SENHOR mandou, dizendo: Não matarão aos pais pelos filhos, nem aos filhos pelos pais: mas cada um morrerá por seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Este feriu também dez mil edomitas no vale das salinas, e tomou a Selá por guerra, e chamou-a Jocteel, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Então Amazias enviou embaixadores a Joás, filho de Jeoacaz filho de Jeú, rei de Israel, dizendo: Vem, e vejamo-nos face a face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'E Joás rei de Israel enviou a Amazias rei de Judá esta resposta: O cardo que está no Líbano enviou a dizer ao cedro que está no Líbano: Da tua filha por mulher a meu filho. E passaram os animais selvagens que estão no Líbano, e pisaram o cardo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Certamente feriste a Edom, e teu coração te envaideceu: gloria-te, pois, mas fica-te em tua casa. E por que te intrometerás em um mal, para que caias tu, e Judá contigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Mas Amazias não deu ouvidos; pelo que subiu Joás rei de Israel, e vieram-se de rosto ele e Amazias rei de Judá, em Bete-Semes, que é de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'E Judá caiu diante de Israel, e fugiram cada um a suas moradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Além disso Joás rei de Israel tomou a Amazias rei de Judá, filho de Joás filho de Acazias, em Bete-Semes: e veio a Jerusalém, e rompeu o muro de Jerusalém desde a porta de Efraim até a porta da esquina, quatrocentos côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'E tomou todo o ouro e a prata, e todos os vasos que foram achados na casa do SENHOR, e nos tesouros da casa do rei, e os filhos em reféns, e voltou-se a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Os demais dos feitos de Joás que executou, e suas façanhas, e como lutou contra Amasias rei de Judá, não estão escritos no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'E descansou Joás com seus pais, e foi sepultado em Samaria com os reis de Israel; e reinou em seu lugar Jeroboão seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'E Amazias, filho de Joás, rei de Judá, viveu depois da morte de Joás filho de Jeoacaz rei de Israel, quinze anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Os demais dos feitos de Amazias não estão escritos no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'E fizeram conspiração contra ele em Jerusalém, e ele fugiu a Laquis; mas enviaram atrás dele a Laquis, e ali o mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Trouxeram-no logo sobre cavalos, e sepultaram-no em Jerusalém com seus pais, na cidade de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Então todo o povo de Judá tomou a Azarias, que era de dezesseis anos, e fizeram-no rei em lugar de Amasias seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Ele edificou Elate, e a restituiu a Judá, depois que o rei descansou com seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'O ano quinze de Amazias filho de Joás rei de Judá, começou a reinar Jeroboão filho de Joás sobre Israel em Samaria; e reinou quarenta e um anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'E fez o que era mau aos olhos do SENHOR, e não se separou de todos os pecados de Jeroboão filho de Nebate, o que fez pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Ele restituiu os termos de Israel desde a entrada de Hamate até o mar da planície, conforme à palavra do SENHOR Deus de Israel, a qual havia ele falado por seu servo Jonas filho de Amitai, profeta que foi de Gate-Hefer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Porquanto o SENHOR olhou a muito amarga aflição de Israel; que não havia escravo nem livre, nem quem desse ajuda a Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'E o SENHOR não havia determinado apagar o nome de Israel de debaixo do céu: portanto, os salvou por mão de Jeroboão filho de Joás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'E o demais dos feitos de Jeroboão, e todas as coisas que fez, e sua valentia, e todas as guerras que fez, e como restituiu a Judá em Israel a Damasco e a Hamate, não está escrito no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'E descansou Jeroboão com seus pais, os reis de Israel, e reinou em seu lugar Zacarias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'No ano vinte e sete de Jeroboão, rei de Israel, começou a reinar Azarias, filho de Amazias, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Quando começou a reinar tinha dezesseis anos, e reinou cinquenta e dois anos em Jerusalém; o nome de sua mãe foi Jecolias, de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'E fez o que era correto aos olhos do SENHOR, conforme todas as coisas que seu pai Amazias havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Contudo, os altos não foram tirados; pois o povo ainda sacrificava e queimava incenso nos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Mas o SENHOR feriu ao rei com lepra, e foi leproso até o dia de sua morte, e habitou em casa separada. Jotão, filho do rei tinha o cargo do palácio, governando o povo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Os demais dos feitos de Azarias, e todas as coisas que fez, não estão escritos no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Azarias descansou com seus pais, e sepultaram-no com seus pais na cidade de Davi; e Jotão, seu filho, reinou em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'No ano trinta e oito de Azarias rei de Judá, reinou Zacarias, filho de Jeroboão, sobre Israel por seis meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'E fez o que era mau aos olhos do SENHOR, como seus ancestrais haviam feito; ele não se afastou dos pecados de Jeroboão, filho de Nebate, o que fez pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Contra ele se conspirou Salum, filho de Jabes, e o feriu em presença do seu povo; e o matou, e reinou em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Os demais dos feitos de Zacarias, eis que estão escritos no livro das crônicas dos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'E esta foi a palavra do SENHOR que havia falado a Jeú, dizendo: Teus filhos até a quarta geração se sentarão no trono de Israel. E assim foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Salum, filho de Jabes, começou a reinar no ano trinta e nove de Uzias rei de Judá, e reinou pelo tempo de um mês em Samaria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Pois subiu Menaém, filho de Gadi, de Tirsa, e veio a Samaria, e feriu Salum, filho de Jabes, em Samaria, e o matou, e reinou em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Os demais dos feitos de Salum, e sua conspiração com que conspirou, eis que estão escritos no livro das crônicas dos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Então feriu Menaém a Tifsa, e a todos os que estavam nela, e também seus termos desde Tirsa; e feriu-a porque não lhe haviam aberto; e fendeu o ventre de todas as suas grávidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'No ano trinta e nove de Azarias, rei de Judá, reinou Menaém, filho de Gadi, sobre Israel, por dez anos, em Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'E fez o que era mau aos olhos do SENHOR; ele não se afastou em todo o seu tempo dos pecados de Jeroboão, filho de Nebate, o que fez Israel pecar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'E veio Pul, rei da Assíria, à terra; e Menaém deu a Pul mil talentos de prata para lhe ajudasse a se firmar no reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'E impôs Menaém este dinheiro sobre Israel, sobre todos os poderosos e ricos: de cada um cinquenta siclos de prata, para dar ao rei da Assíria, e o rei da Assíria voltou, e não ficou ali na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Os demais dos feitos de Menaém, e todas as coisas que fez, acaso não estão escritas no livro das crônicas dos reis de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menaém descansou com seus pais, e reinou em seu lugar seu filho Pecaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'No ano cinquenta de Azarias rei de Judá, reinou Pecaías filho de Menaém sobre Israel em Samaria, dois anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'E fez o que era mau aos olhos do SENHOR: não se separou dos pecados de Jeroboão filho de Nebate, o que fez Israel pecar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'E conspirou contra ele Peca filho de Remalias, capitão seu, e feriu-o em Samaria, no palácio da casa real, em companhia de Argobe e de Arié, e com cinquenta homens dos filhos dos gileaditas; e o matou, e reinou em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Os demais dos feitos de Pecaías, e todas as coisas que fez, eis que estão escritos no livro das crônicas dos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'No ano cinquenta e dois de Azarias rei de Judá, reinou Peca, filho de Remalias sobre Israel em Samaria; e reinou vinte anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'E fez o que era mau aos olhos do SENHOR; não se separou dos pecados de Jeroboão filho de Nebate, o que fez pecar a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Nos dias de Peca rei de Israel, veio Tiglate-Pileser rei dos assírios, e tomou a Ijom, Abel-Bete-Maaca, e Janoa, e Quedes, e Hazor, e Gileade, e Galileia, e toda a terra de Naftali; e transportou-os à Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'E Oseias filho de Elá fez conspiração contra Peca filho de Remalias, e feriu-o, e o matou, e reinou em seu lugar, aos vinte anos de Jotão filho de Uzias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Os demais dos feitos de Peca, e tudo o que fez, eis que está escrito no livro das crônicas dos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'No segundo ano de Peca filho de Remalias rei de Israel, começou a reinar Jotão filho de Uzias rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Quando começou a reinar era de vinte e cinco anos, e reinou dezesseis anos em Jerusalém. O nome de sua mãe foi Jerusa filha de Zadoque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'E ele fez o que era correto aos olhos do SENHOR; fez conforme todas as coisas que havia feito seu pai Uzias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Com tudo isso os altos não foram tirados; que o povo sacrificava ainda, e queimava incenso nos altos. Edificou ele a porta mais alta da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Os demais dos feitos de Jotão, e todas as coisas que fez, não estão escritos no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Naquele tempo começou o SENHOR a enviar contra Judá a Resim rei da Síria, e a Peca filho de Remalias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'E descansou Jotão com seus pais, e foi sepultado com seus pais na cidade de Davi seu pai; e reinou em seu lugar Acaz seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'No ano dezessete de Peca filho de Remalias, começou a reinar Acaz filho de Jotão rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Quando começou a reinar Acaz, era de vinte anos, e reinou em Jerusalém dezesseis anos: e não fez o que era correto aos olhos do SENHOR seu Deus, como Davi seu pai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Antes andou no caminho dos reis de Israel, e ainda fez passar pelo fogo a seu filho, segundo as abominações das nações que o SENHOR expulsou de diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Também sacrificou, e queimou incenso nos altos, e sobre as colinas, e debaixo de toda árvore frondosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Então Resim rei da Síria, e Peca filho de Remalias rei de Israel, subiram a Jerusalém para fazer guerra, e cercar a Acaz; mas não puderam tomá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Naquele tempo Resim rei da Síria restituiu Elate à Síria, e expulsou aos judeus de Elate; e os sírios vieram a Elate, e habitaram ali até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Então Acaz enviou embaixadores a Tiglate-Pileser rei da Assíria, dizendo: Eu sou teu servo e teu filho: sobe, e defende-me da mão do rei da Síria, e da mão do rei de Israel, que se levantaram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'E tomando Acaz a prata e o ouro que se achou na casa do SENHOR, e nos tesouros da casa real, enviou ao rei da Assíria um presente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'E atendeu-lhe o rei da Assíria; pois subiu o rei da Assíria contra Damasco, e tomou-a, e transportou os moradores a Quir, e matou a Resim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'E foi o rei Acaz a encontrar a Tiglate-Pileser rei da Assíria em Damasco; e visto que havia o rei Acaz o altar que estava em Damasco, enviou a Urias sacerdote o desenho e a descrição do altar, conforme a toda sua feitura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'E Urias o sacerdote edificou o altar; conforme a tudo o que o rei Acaz havia enviado de Damasco, assim o fez o sacerdote Urias, antes que o rei Acaz viesse de Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'E logo que veio o rei de Damasco, e viu o altar, aproximou-se o rei a ele, e sacrificou nele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'E acendeu seu holocausto, e seu presente, e derramou suas libações, e espargiu o sangue de seus pacíficos junto ao altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'E o altar de bronze que estava diante do SENHOR, ele o moveu de diante da parte frontal da casa, entre o altar e o templo do SENHOR, e o pôs ao lado do altar até o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'E mandou o rei Acaz ao sacerdote Urias, dizendo: No grande altar acenderás o holocausto da manhã e o presente da tarde, e o holocausto do rei e seu presente, e também o holocausto de todo o povo da terra e seu presente e suas libações; e espargirás sobre ele todo o sangue do holocausto, e todo o sangue do sacrifício; e o altar de bronze será meu para nele consultar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'E fez o sacerdote Urias conforme a todas as coisas que o rei Acaz lhe mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'E cortou o rei Acaz as cintas das bases, e tirou-lhes as fontes; tirou também o mar de sobre os bois de bronze que estavam debaixo dele, e o pôs sobre o piso de pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Também a tenda do sábado que haviam edificado na casa, e a entrada de fora do rei, ele os moveu do templo do SENHOR, por causa do rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Os demais dos feitos de Acaz que pôs por obra, não estão todos escritos no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'E descansou o rei Acaz com seus pais e foi sepultado com seus pais na cidade de Davi: e reinou em seu lugar Ezequias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'No ano décimo segundo de Acaz rei de Judá, começou a reinar Oseias filho de Elá em Samaria sobre Israel; e reinou nove anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'E fez o que era mau aos olhos do SENHOR, ainda que não como os reis de Israel que antes dele haviam sido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Contra este subiu Salmaneser rei dos assírios; e Oseias foi feito seu servo, e pagava-lhe tributo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Mas o rei da Assíria achou que Oseias fazia conspiração: porque havia enviado embaixadores a Sô, rei do Egito, e não pagava tributo ao rei da Assíria, como cada ano: pelo que o rei da Assíria lhe deteve, e lhe aprisionou na casa do cárcere.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'E o rei da Assíria partiu contra todo o país, e subiu contra Samaria, e esteve sobre ela três anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'No ano nove de Oseias tomou o rei da Assíria a Samaria, e transportou a Israel a Assíria, e os pôs em Hala, e em Habor, junto ao rio de Gozã, e nas cidades dos medos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Porque como os filhos de Israel pecassem contra o SENHOR seu Deus, que os tirou da terra do Egito de sob a mão de Faraó rei do Egito, e temessem a deuses alheios,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'E andassem nos estatutos das nações que o SENHOR havia lançado diante dos filhos de Israel, e nos dos reis de Israel, que fizeram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'E os filhos de Israel fizeram secretamente coisas que não eram corretas, contra o SENHOR seu Deus, edificando para si altos em todas as suas cidades, desde as torres das atalaias até as cidades fortes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'E levantaram para si estátuas e bosques em todo morro alto, e debaixo de toda árvore frondosa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'E queimaram ali incenso em todos os altos, à maneira das nações que o SENHOR havia expulsado diante deles, e fizeram coisas muito más para provocar o SENHOR à ira,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Pois serviam aos ídolos, dos quais o SENHOR lhes havia dito: Vós não haveis de fazer isto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'O SENHOR advertia, então, contra Israel e contra Judá, por meio de todos os profetas, e de todos os videntes, dizendo: Convertei-vos de vossos maus caminhos, e guardai meus mandamentos e minhas ordenanças, conforme a todas as leis que eu prescrevi a vossos pais, e que os enviei por meio de meus servos, os profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mas eles não obedeceram, antes endureceram sua cerviz, como a cerviz de seus pais, os quais não creram no SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'E rejeitaram seus estatutos, e seu pacto que ele havia concertado com seus pais, e seus testemunhos que ele havia advertido contra eles; e seguiram a vaidade, e se fizeram vãos, e seguiram as nações que estavam ao redor deles, das quais o SENHOR havia lhes mandado que não fizessem à maneira delas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'E deixaram todos os mandamentos do SENHOR seu Deus, e fizeram para si imagens de dois bezerros, e também bosques, e adoraram a todo o exército do céu, e serviram a Baal:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'E fizeram passar a seus filhos e a suas filhas por fogo; e deram-se a adivinhações e agouros, e entregaram-se a fazer o que era mau aos olhos do SENHOR, provocando-o à ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'O SENHOR, portanto, se irou em grande maneira contra Israel, e tirou-os de diante de seu rosto; que não restou a não ser somente a tribo de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Mas nem ainda Judá guardou os mandamentos do SENHOR seu Deus; antes andaram nos estatutos de Israel, os quais eles haviam feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'E rejeitou o SENHOR toda a semente de Israel, e afligiu-os, e entregou-os em mãos de saqueadores, até lançá-los de sua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Porque cortou a Israel da casa de Davi, e eles se fizeram rei a Jeroboão filho de Nebate; e Jeroboão desviou a Israel de seguir o SENHOR, e fez-lhes cometer grande pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'E os filhos de Israel andaram em todos os pecados de Jeroboão que ele fez, sem desviar-se deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Até que o SENHOR tirou a Israel de diante de seu rosto, como o havia ele dito por meio de todos os profetas seus servos: e Israel foi transportado de sua terra à Assíria, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'E trouxe o rei da Assíria gente de Babilônia, e de Cuta, e de Hava, e de Hamate, e de Sefarvaim, e os pôs nas cidades de Samaria, em lugar dos filhos de Israel; e possuíram a Samaria, e habitaram em suas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'E aconteceu ao princípio, quando começaram a habitar ali, que não temendo eles ao SENHOR, enviou o SENHOR contra eles leões que os matavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Então disseram eles ao rei da Assíria: As nações que tu transportaste e puseste nas cidades de Samaria, não sabem a costume do Deus daquela terra, e ele lançou leões neles, e eis que os matam, porque não sabem a costume do Deus da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'E o rei da Assíria mandou, dizendo: Levai ali a algum dos sacerdotes que trouxestes dali, e vão e habitem ali, e ensinem-lhes o costume do Deus do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'E veio um dos sacerdotes que haviam transportado de Samaria, e habitou em Betel, e ensinou-lhes como haviam de temer ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Mas cada nação fez para si seus deuses, e puseram-nos nos templos dos altos que haviam feito os de Samaria; cada nação em sua cidade onde habitava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Os da Babilônia fizeram a Sucote-Benote, e os de Cuta fizeram a Nergal, e os de Hamate fizeram a Asima;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Os heveus fizeram a Nibaz e a Tartaque; e os de Sefarvaim queimavam seus filhos ao fogo a Adrameleque e a Anameleque, deuses de Sefarvaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'E temiam ao SENHOR; e fizeram dos do povo sacerdotes dos altos, os quais sacrificavam para eles nos templos dos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Temiam ao SENHOR, e honravam a seus deuses, segundo o costume das nações de onde haviam sido transportados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Até hoje fazem como primeiro; que nem temem ao SENHOR, nem guardam seus estatutos, nem suas ordenanças, nem fazem segundo a lei e os mandamentos que prescreveu o SENHOR aos filhos de Jacó, ao qual pôs o nome de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Com os quais havia o SENHOR feito pacto, e lhes mandou, dizendo: Não temereis a outros deuses, nem os adorareis, nem lhes servireis, nem lhes sacrificareis:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Mas ao SENHOR, que vos tirou da terra do Egito com grande poder e braço estendido, a este temereis, e a este adorareis, e a este fareis sacrifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Os estatutos e direitos e lei e mandamentos que vos deu por escrito, cuidareis sempre de praticá-los, e não temereis deuses alheios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'E não esquecereis o pacto que fiz convosco; nem temereis deuses alheios:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Mas temei ao SENHOR vosso Deus, e ele vos livrará da mão de todos vossos inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Porém eles não escutaram; antes fizeram segundo seu costume antigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Assim temeram ao SENHOR aquelas nações, e juntamente serviram a seus ídolos: e também seus filhos e seus netos, segundo que fizeram seus pais, assim fazem até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'No terceiro ano de Oseias filho de Elá rei de Israel, começou a reinar Ezequias filho de Acaz rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Quando começou a reinar era de vinte e cinco anos, e reinou em Jerusalém vinte e nove anos. O nome de sua mãe foi Abi filha de Zacarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Fez o que era correto aos olhos do SENHOR, conforme todas as coisas que havia feito Davi seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Ele tirou os altos, e quebrou as imagens, e arrancou os bosques, e fez pedaços a serpente de bronze que havia feito Moisés, porque até então lhe queimavam incenso os filhos de Israel; e chamou-lhe por nome Neustã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'No SENHOR Deus de Israel pôs sua esperança: depois nem antes dele não houve outro como ele em todos os reis de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Porque se chegou ao SENHOR, e não se separou dele, mas sim que guardou os mandamentos que o SENHOR prescreveu a Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'E o SENHOR foi com ele; e em todas as coisas a que saía prosperava. Ele se rebelou contra o rei da Assíria, e não lhe serviu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Feriu também aos filisteus até Gaza e seus termos, desde as torres das atalaias até a cidade fortificada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'No quarto ano do rei Ezequias, que era o ano sétimo de Oseias filho de Elá rei de Israel, subiu Salmaneser rei dos assírios contra Samaria, e cercou-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'E tomaram-na ao fim de três anos: isto é, no sexto ano de Ezequias, o qual era o ano nono de Oseias rei de Israel, foi Samaria tomado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'E o rei da Assíria transportou a Israel à Assíria, e os pôs em Hala, e em Habor, junto ao rio de Gozã, e nas cidades dos medos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Porquanto não haviam atendido à voz do SENHOR seu Deus, antes haviam quebrado o seu pacto; e todas as coisas que Moisés servo do SENHOR havia mandado, nem as haviam escutado, nem praticado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'E aos catorze anos do rei Ezequias, subiu Senaqueribe rei da Assíria contra todas as cidades fortes de Judá, e tomou-as.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Então Ezequias, rei de Judá, mandou dizer ao rei da Assíria em Laquis: Eu pequei; afasta-te de mim, e suportarei tudo o que me impuseres. E o rei da Assíria impôs a Ezequias rei de Judá trezentos talentos de prata, e trinta talentos de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Deu, portanto, Ezequias toda a prata que foi achada na casa do SENHOR, e nos tesouros da casa real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Então desmontou Ezequias as portas do templo do SENHOR, e as dobradiças que o mesmo rei Ezequias havia coberto de ouro, e deu-o ao rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Depois o rei da Assíria enviou ao rei Ezequias, desde Laquis contra Jerusalém, a Tartã e a Rabe-Saris e a Rabsaqué, com um grande exército: e subiram, e vieram a Jerusalém. E havendo subido, vieram e pararam junto ao aqueduto do tanque de acima,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Chamaram logo ao rei, e saiu a eles Eliaquim filho de Hilquias, que era mordomo, e Sebna escriba, e Joá filho de Asafe, chanceler.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'E disse-lhes Rabsaqué: Dizei agora a Ezequias: Assim diz o grande rei da Assíria: Que confiança é esta em que tu estás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Dizes, (por certo palavras de lábios): Tenho conselho e esforço para a guerra. Mas em que confias, que te rebelaste contra mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Eis que tu confias agora neste bordão de cana quebrada, em Egito, no que se alguém se apoiar, lhe entrará pela mão, e se lhe passará. Assim é Faraó, rei do Egito, para todos os que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'E se me dizeis: Nós confiamos no SENHOR nosso Deus: não é aquele cujos altos e altares tirou Ezequias, e disse a Judá e a Jerusalém: Diante deste altar adorareis em Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Portanto, agora eu te rogo que dês reféns a meu senhor, o rei da Assíria, e eu te darei dois mil cavalos, se tu puderes dar cavaleiros para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Como, pois, farás virar o rosto de um capitão o menor dos servos de meu senhor, ainda que estais confiantes no Egito por seus carros e seus cavaleiros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Além disso, acaso eu vim sem o SENHOR a este lugar, para destruí-lo? Foi o SENHOR que me disse: Sobe a esta terra, e destrói-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Então disse Eliaquim filho de Hilquias, e Sebna e Joá, a Rabsaqué: Rogo-te que fales a teus servos em siríaco, porque nós o entendemos, e não fales conosco judaico a ouvidos do povo que está sobre o muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'E Rabsaqué lhes disse: Enviou-me meu senhor a ti e a teu senhor para dizer estas palavras, e não antes aos homens que estão sobre o muro, para comerem o seu excremento, e beberem a sua própria urina convosco?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Logo Rabsaqué ficou de pé, e clamou em alta voz na língua judaica, e falou, dizendo: Ouvi a palavra do grande rei, o rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Assim disse o rei: Não vos engane Ezequias, porque não vos poderá livrar de minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'E não vos faça Ezequias confiar no SENHOR, dizendo: De certo nos livrará o SENHOR, e esta cidade não será entregue em mão do rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Não ouçais a Ezequias, porque assim diz o rei da Assíria: Fazei comigo paz, e saí a mim, e cada um comerá de sua vide, e de sua figueira, e cada um beberá as águas de seu poço;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Até que eu venha, e vos leve a uma terra como a vossa, terra de grão e de vinho, terra de pão e de vinhas, terra de olivas, de azeite, e de mel; e vivereis, e não morrereis. Não ouçais a Ezequias, porque vos engana quando disse: o SENHOR nos livrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Acaso algum dos deuses das nações livrou sua terra da mão do rei da Assíria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Onde está o deus de Hamate, e de Arpade? Onde está o deus de Sefarvaim, de Hena, e de Iva? Puderam estes livrar a Samaria de minha mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Que deus de todos os deuses das províncias livrou a sua província de minha mão, para que livre o SENHOR de minha mão a Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'E o povo se calou, de maneira que não lhe responderam palavra: porque havia mandamento do rei, o qual havia dito: Não lhe respondais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Então Eliaquim filho de Hilquias, que era mordomo, e Sebna o escriba, e Joá filho de Asafe, chanceler, vieram a Ezequias, com suas roupas rasgadas, e contaram-lhe as palavras de Rabsaqué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'E quando o rei Ezequias o ouviu, rasgou suas roupas, e cobriu-se de saco, e entrou-se na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'E enviou a Eliaquim o mordomo, e a Sebna escriba, e aos anciãos dos sacerdotes, vestidos de sacos a Isaías profeta filho de Amoz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Que lhe dissessem: Assim disse Ezequias: Este dia é dia de angústia, e de repreensão, e de blasfêmia; porque os filhos vieram até o ponto do parto, mas a que dá à luz não tem forças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Talvez ouvirá o SENHOR tua Deus todas as palavras de Rabsaqué, ao qual o rei dos assírios, seu senhor, enviou para afrontar o Deus vivo, e repreenderá pelas palavras que o SENHOR teu Deus ouviu: portanto, eleva oração pelos restantes que ainda continuam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Vieram, pois, os servos do rei Ezequias a Isaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'E Isaías lhes respondeu: Assim direis a vosso senhor: Assim disse o SENHOR; Não temas pelas palavras que ouviste, com as quais me blasfemaram os servos do rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Eis que porei eu nele um espírito, e ouvirá rumor, e se voltará à sua terra: e eu farei que em sua terra caia à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'E regressando Rabsaqué, achou ao rei da Assíria combatendo a Libna; porque havia ouvido que se havia partido de Laquis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'E ouviu dizer de Tiraca rei de Etiópia: Eis que saiu para fazer-te guerra. Então voltou ele, e enviou embaixadores a Ezequias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Assim direis a Ezequias rei de Judá: Não te engane teu Deus em quem tu confias, para dizer: Jerusalém não será entregue em mão do rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Eis que tu ouviste o que fizeram os reis da Assíria a todas as terras, destruindo-as; e hás tu de escapar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Livraram-nas os deuses das nações, que meus pais destruíram, a saber, Gozã, e Harã, e Rezefe, e os filhos de Éden que estavam em Telassar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Onde está o rei de Hamate, o rei de Arpade, o rei da cidade de Sefarvaim, de Hena, e de Iva?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'E tomou Ezequias as cartas da mão dos embaixadores; e depois que as leu, subiu à casa do SENHOR, e estendeu-as Ezequias diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'E orou Ezequias diante do SENHOR, dizendo: SENHOR Deus de Israel, que habitas entre os querubins, tu só és Deus de todos os reinos da terra; tu fizeste o céu e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Inclina, ó SENHOR, teu ouvido, e ouve; abre, ó SENHOR, teus olhos, e olha: e ouve as palavras de Senaqueribe, que enviou a blasfemar ao Deus vivente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'É verdade, ó SENHOR, que os reis da Assíria destruíram as nações e suas terras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'E que puseram no fogo a seus deuses, porquanto eles não eram deuses, mas sim obra de mãos de homens, madeira ou pedra, e assim os destruíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Agora, pois, ó SENHOR Deus nosso, salva-nos, te suplico, de sua mão, para que saibam todos os reinos da terra que só tu, SENHOR, és Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Então Isaías filho de Amoz enviou a dizer a Ezequias: Assim disse o SENHOR, Deus de Israel: O que me rogaste acerca de Senaqueribe rei da Assíria, ouvi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Esta é a palavra que o SENHOR falou contra ele: Menosprezou-te, escarneceu-te a virgem filha de Sião; moveu sua cabeça detrás de ti a filha de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'A quem afrontaste e a quem blasfemaste? E contra quem falaste alto, e levantaste em alto teus olhos? Contra o Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Por meio de teus mensageiros proferiste afronta contra o Senhor, e disseste: Com a multidão de meus carros subi aos cumes dos montes, às costas do Líbano; e cortarei seus altos cedros, suas faias escolhidas; e entrarei à morada de seu termo, à floresta de seu terreno fértil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Eu cavei e bebi as águas alheias, e sequei com as plantas de meus pés todos os rios de lugares bloqueados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Nunca ouviste que há muito tempo eu o fiz, e de dias antigos o formei? E agora o fiz vir, e foi para desolação de cidades fortes em amontoados de ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'E seus moradores, fracos de mãos, quebrantados e confusos, foram qual erva do campo, como hortaliça verde, e feno dos telhados, que antes que venha a maturidade é seco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Eu soube teu assentar-te, teu sair e teu entrar, e teu furor contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Porquanto te iraste contra mim, e teu estrondo subiu a meus ouvidos, eu, portanto, porei meu anzol em tuas narinas, e meu freio em teus lábios, e te farei voltar pelo caminho por onde vieste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'E isto te será por sinal Ezequias: Este ano comerás o que nascerá de si mesmo, e no segundo ano o que nascerá de si mesmo; e ao terceiro ano semeareis, e colhereis, e plantareis vinhas, e comereis o fruto delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'E o que houver escapado, o que haverá restado da casa de Judá, voltará a lançar raiz abaixo, e dará fruto acima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Porque sairão de Jerusalém remanescentes, e os que escaparão, do monte de Sião: o zelo do SENHOR dos exércitos fará isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Portanto, o SENHOR diz assim do rei da Assíria: Não entrará nesta cidade, nem lançará flecha nela; nem virá diante dela escudo, nem será levantado baluarte contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Pelo caminho que veio se voltará, e não entrará nesta cidade, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Porque eu ampararei a esta cidade para salvá-la, por causa de mim, e por causa de Davi meu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'E aconteceu que a mesma noite saiu o anjo do SENHOR, e feriu no campo dos assírios cento oitenta e cinco mil; e quando se levantaram pela manhã, eis que eram todos cadáveres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Então Senaqueribe, rei da Assíria, partiu-se, e se foi e voltou a Nínive, onde ficou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'E aconteceu que, estando ele adorando no templo de Nisroque seu deus, Adrameleque e Sarezer seus filhos o feriram à espada; e fugiram-se à terra de Ararate. E reinou em seu lugar Esar-Hadom seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Naqueles dias caiu Ezequias enfermo de morte, e veio a ele Isaías profeta filho de Amoz, e disse-lhe: o SENHOR disse assim: Dá ordens à tua casa, porque hás de morrer, e não viverás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Então virou ele seu rosto à parede, e orou ao SENHOR, e disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Rogo-te, ó SENHOR, rogo-te faças memória de que andei diante de ti em verdade e íntegro coração, e que fiz as coisas que te agradam. E chorou Ezequias com grande choro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'E antes que Isaías saísse até a metade do pátio, veio a palavra do SENHOR a Isaías, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Volta, e dize a Ezequias, príncipe de meu povo: Assim diz o SENHOR, o Deus de Davi teu pai: Eu ouvi tua oração, e vi tuas lágrimas: eis que eu te saro; ao terceiro dia subirás à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'E acrescentarei a teus dias quinze anos, e te livrarei a ti e a esta cidade da mão do rei da Assíria; e ampararei esta cidade por causa de mim, e por causa de Davi meu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'E disse Isaías: Tomai uma pasta de figos. E tomando-a, puseram sobre a chaga, e sanou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'E Ezequias havia dito a Isaías: Que sinal terei de que o SENHOR me sarará, e que subirei à casa do SENHOR ao terceiro dia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'E respondeu Isaías: Esta sinal terás do SENHOR, de que fará o SENHOR isto que disse: Avançará a sombra dez degraus, ou retrocederá dez degraus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'E Ezequias respondeu: Fácil coisa é que a sombra decline dez degraus: mas, que a sombra volte atrás dez degraus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Então o profeta Isaías clamou ao SENHOR; e fez voltar a sombra pelos degraus que havia descido no relógio de Acaz, dez degraus atrás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Naquele tempo Berodaque-Baladã filho de Baladã, rei da Babilônia, enviou cartas e presentes a Ezequias, porque havia ouvido que Ezequias havia caído enfermo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'E Ezequias os ouviu, e mostrou-lhes toda a casa das coisas preciosas, prata, ouro, e especiaria, e preciosos unguentos; e a casa de suas armas, e tudo o que havia em seus tesouros: nenhuma coisa restou que Ezequias não lhes mostrasse, tanto em sua casa como em todo o seu domínio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Então o profeta Isaías veio ao rei Ezequias, e disse-lhe: Que disseram aqueles homens, e de onde vieram a ti? E Ezequias lhe respondeu: De distantes terras vieram, de Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'E ele lhe voltou a dizer: Que viram em tua casa? E Ezequias respondeu: Viram tudo o que havia em minha casa; nada restou em meus tesouros que não lhes mostrasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Então Isaías disse a Ezequias: Ouve a palavra do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Eis que vêm dias, em que tudo o que está em tua casa, e tudo o que teus pais entesouraram até hoje, será levado a Babilônia, sem restar nada, disse o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'E de teus filhos que sairão de ti, que haverás gerado, tomarão; e serão eunucos no palácio do rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Então Ezequias disse a Isaías: A palavra do SENHOR que falaste, é boa. Depois disse: Mas não haverá paz e verdade em meus dias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Os demais dos feitos de Ezequias, e todo o seu vigor, e como fez o tanque, e o aqueduto, e meteu as águas na cidade, não está escrito no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'E descansou Ezequias com seus pais, e reinou em seu lugar Manassés seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'De doze anos era Manassés quando começou a reinar, e reinou em Jerusalém cinquenta e cinco anos: o nome de sua mãe foi Hefzibá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'E fez o que era mau aos olhos do SENHOR, segundo as abominações das nações que o SENHOR havia lançado diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Porque ele voltou a edificar os altos que Ezequias seu pai havia derrubado, e levantou altares a Baal, e fez bosque, como havia feito Acabe rei de Israel: e adorou a todo o exército do céu, e serviu àquelas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Também edificou altares na casa do SENHOR, da qual o SENHOR havia dito: Eu porei meu nome em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'E edificou altares para todo o exército do céu nos dois átrios da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'E passou a seu filho por fogo, e olhou em tempos, e foi agoureiro, e instituiu necromantes e adivinhos, multiplicando assim o fazer o mal aos olhos do SENHOR, para provocá-lo à ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'E pôs uma imagem entalhada do bosque que ele havia feito, na casa da qual havia o SENHOR dito a Davi e a Salomão seu filho: Eu porei meu nome para sempre nesta casa, e em Jerusalém, à qual escolhi de todas as tribos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'E não voltarei a fazer que o pé de Israel seja movido da terra que dei a seus pais, contanto que guardem e façam conforme a todas as coisas que eu lhes mandei, e conforme a toda a lei que meu servo Moisés lhes mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mas eles não escutaram; e Manassés os induziu a que fizessem mais mal que as nações que o SENHOR destruiu diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'E falou o SENHOR por meio de seus servos os profetas, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Porquanto Manassés rei de Judá fez estas abominações, e fez mais mal que tudo o que fizeram os amorreus que foram antes dele, e também fez pecar a Judá em seus ídolos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Portanto, assim disse o SENHOR o Deus de Israel: Eis que eu trago tal mal sobre Jerusalém e sobre Judá, que o que o ouvir, lhe retinirão ambos ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'E estenderei sobre Jerusalém o cordel de Samaria, e o prumo da casa de Acabe: e eu limparei a Jerusalém como se limpa um prato, que depois que o limpam, viram-no sobre sua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'E desampararei os restantes de minha propriedade, e os entregarei em mãos de seus inimigos; e serão para saque e para roubo a todos seus adversários;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Porquanto fizeram o mal aos meus olhos, e me provocaram à ira, desde o dia que seus pais saíram do Egito até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Além disso, derramou Manassés muito sangue inocente em grande maneira, até encher a Jerusalém de extremidade a extremidade; além de seu pecado com que fez pecar a Judá, para que fizesse o que era mau aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Os demais dos feitos de Manassés, e todas as coisas que fez, e seu pecado que cometeu, não está tudo escrito no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'E descansou Manassés com seus pais, e foi sepultado no jardim de sua casa, no jardim de Uzá; e reinou em seu lugar Amom seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'De vinte e dois anos era Amom quando começou a reinar, e reinou dois anos em Jerusalém. O nome de sua mãe foi Mesulemete filha de Haruz de Jotbá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'E fez o que era mau aos olhos do SENHOR, como havia feito Manassés seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'E andou em todos os caminhos em que seu pai andou, e serviu às imundícias às quais havia servido seu pai, e a elas adorou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'E deixou ao SENHOR o Deus de seus pais, e não andou no caminho do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'E os servos de Amom conspiraram contra ele, e mataram ao rei em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Então o povo da terra feriu a todos os que haviam conspirado contra o rei Amom; e pôs o povo da terra por rei em seu lugar a Josias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Os demais dos feitos de Amom, que efetuara, não está tudo escrito no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'E foi sepultado em seu sepulcro no jardim de Uzá, e reinou em seu lugar Josias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Quando Josias começou a reinar era de oito anos, e reinou em Jerusalém trinta e um anos. O nome de sua mãe foi Jedida filha de Adaías de Bozcate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'E fez o que era correto aos olhos do SENHOR, e andou em todo o caminho de Davi seu pai, sem desviar-se à direita nem à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'E aos dezoito anos do rei Josias, foi que enviou o rei a Safã filho de Azalias, filho de Mesulão, escriba, à casa do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Vai a Hilquias, sumo sacerdote: dize-lhe que recolha o dinheiro que se pôs na casa do SENHOR, que juntaram do povo os guardiões da porta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'E que o ponham em mãos dos que fazem a obra, que têm cargo da casa do SENHOR, e que o entreguem aos que fazem a obra da casa do SENHOR, para reparar as fendas da casa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Aos carpinteiros, aos mestres e pedreiros, para comprar madeira e pedra lavrada para reparar a casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'E que não se lhes conte o dinheiro cujo manejo se lhes confiar, porque eles procedem com fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Então disse o sumo sacerdote Hilquias a Safã escriba: Achei o livro da lei na casa do SENHOR. E Hilquias deu o livro a Safã, e leu-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Vindo logo Safã escriba ao rei, deu ao rei a resposta, e disse: Teus servos juntaram o dinheiro que se achou no templo, e o entregaram em poder dos que fazem a obra, que têm cargo da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Também Safã escriba declarou ao rei, dizendo: Hilquias o sacerdote me deu um livro. E leu-o Safã diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'E quando o rei ouviu as palavras do livro da lei, rasgou suas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Logo mandou o rei a Hilquias o sacerdote, e a Aicã filho de Safã, e a Acbor filho de Micaías, e a Safã escriba, e a Asaías servo do rei, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Ide, e perguntai ao SENHOR por mim, e pelo povo, e por todo Judá, acerca das palavras deste livro que se achou: porque grande ira do SENHOR é a que foi acesa contra nós, porquanto nossos pais não escutaram as palavras deste livro, para fazer conforme tudo o que nos foi escrito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Então foi Hilquias o sacerdote, e Aicã e Acbor e Safã e Asaías, a Hulda profetisa, mulher de Salum filho de Ticvá filho de Harás, guarda das vestiduras, a qual morava em Jerusalém na segunda parte da cidade, e falaram com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'E ela lhes disse: Assim disse o SENHOR o Deus de Israel: Dizei ao homem que vos enviou a mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Assim disse o SENHOR: Eis que eu trago mal sobre este lugar, e sobre os que nele moram, a saber, todas as palavras do livro que leu o rei de Judá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Porquanto me deixaram, e queimaram incenso a deuses alheios, provocando-me à ira em toda obra de suas mãos; e meu furor se acendeu contra este lugar, e não se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Mas ao rei de Judá que vos enviou para que perguntásseis ao SENHOR, direis assim: Assim disse o SENHOR o Deus de Israel: Porquanto ouviste as palavras do livro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'E teu coração se enterneceu, e te humilhaste diante do SENHOR, quando ouviste o que eu pronunciei contra este lugar e contra seus moradores, que viriam a ser assolados e malditos, e rasgaste tuas vestes, e choraste em minha presença, também eu te ouvi, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Portanto, eis que eu te recolherei com teus pais, e tu serás recolhido a teu sepulcro em paz, e não verão teus olhos todo o mal que eu trago sobre este lugar. E eles deram ao rei a resposta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Então o rei enviou aviso, e juntaram a ele todos os anciãos de Judá e de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'E subiu o rei à casa do SENHOR com todos os homens de Judá, e com todos os moradores de Jerusalém, com os sacerdotes e profetas e com todo o povo, desde o menor até o maior; e leu, ouvindo-o eles, todas as palavras do livro do pacto que havia sido achado na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'E pondo-se o rei em pé junto à coluna, fez aliança diante do SENHOR, de que seguiriam o SENHOR, e guardariam seus mandamentos, e seus testemunhos, e seus estatutos, com todo o coração e com toda a alma, e que cumpririam as palavras da aliança que estavam escritas naquele livro. E todo o povo confirmou o pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Então mandou el rei ao sumo sacerdote Hilquias, e aos sacerdotes de segunda ordem, e aos guardiões da porta, que tirassem do templo do SENHOR todos os vasos que haviam sido feitos para Baal, e para o bosque, e para toda o exército do céu; e queimou-os fora de Jerusalém no campo de Cedrom, e fez levar as cinzas deles a Betel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'E tirou aos sacerdotes pagãos, que haviam posto os reis de Judá para que queimassem incenso nos altos nas cidades de Judá, e nos arredores de Jerusalém; e também aos que queimavam incenso a Baal, ao sol e à lua, e às constelações, e a todo o exército do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Fez também tirar o bosque fora da casa do SENHOR, fora de Jerusalém, ao ribeiro de Cedrom, e queimou-o no ribeiro de Cedrom, e tornou-o em pó, e lançou o pó dele sobre os sepulcros dos filhos do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Além disso derrubou as casas dos sodomitas que estavam na casa do SENHOR, nas quais teciam as mulheres tendas para o bosque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'E fez vir todos os sacerdotes das cidades de Judá, e profanou os altos de onde os sacerdotes queimavam incenso, desde Gibeá até Berseba; e derrubou os altares das portas que estavam à entrada da porta de Josué, governador da cidade, que estavam à esquerda da porta da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Porém os sacerdotes dos altos não subiam ao altar do SENHOR em Jerusalém, mas comiam pães sem levedura entre seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Também profanou a Tofete, que está no vale do filho de Hinom, porque ninguém passasse seu filho ou sua filha por fogo a Moloque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Tirou também os cavalos que os reis de Judá haviam dedicado ao sol à entrada do templo do SENHOR, junto à câmara de Natã-Meleque eunuco, a qual ficava nos recintos; e queimou ao fogo os carros do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Derrubou também o rei os altares que estavam sobre o terraço da sala de Acaz, que os reis de Judá haviam feito, e os altares que havia feito Manassés nos dois átrios da casa do SENHOR; e dali correu e lançou o pó no ribeiro de Cedrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Também profanou o rei os altos que estavam diante de Jerusalém, à direita do monte da destruição, os quais Salomão rei de Israel havia edificado a Astarote, abominação dos sidônios, e a Camos abominação de Moabe, e a Milcom abominação dos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'E quebrou as estátuas, e arrancou os bosques, e encheu o lugar deles de ossos de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Igualmente o altar que estava em Betel, e o alto que havia feito Jeroboão filho de Nebate, o que fez pecar a Israel, aquele altar e o alto destruiu; e queimou o alto, e o tornou em pó, e pôs fogo ao bosque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'E voltou-se Josias, e vendo os sepulcros que estavam ali no monte, enviou e tirou os ossos dos sepulcros, e queimou-os sobre o altar para contaminá-lo, conforme à palavra do SENHOR que havia profetizado o homem de Deus, o qual havia anunciado estes negócios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'E depois disse: Que monumento é este que vejo? E os da cidade lhe responderam: Este é o sepulcro do homem de Deus que veio de Judá, e profetizou estas coisas que tu fizeste sobre o altar de Betel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'E ele disse: Deixai-o; ninguém mova seus ossos: e assim foram preservados seus ossos, e os ossos do profeta que havia vindo de Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'E todas as casas dos altos que estavam nas cidades de Samaria, as quais haviam feito os reis de Israel para provocar a ira, tirou-as também Josias, e fez delas como havia feito em Betel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Também matou sobre os altares a todos os sacerdotes dos altos que ali estavam, e queimou sobre eles ossos de homens, e voltou-se a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Então mandou o rei a todo o povo, dizendo: Fazei a páscoa ao SENHOR vosso Deus, conforme o que está escrito no livro desta aliança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Não foi feita tal páscoa desde os tempos dos juízes que governaram a Israel, nem em todos os tempos dos reis de Israel, e dos reis de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Aos dezoito anos do rei Josias foi feita aquela páscoa ao SENHOR em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Também expulsou Josias os necromantes, adivinhos, e ídolos, e todas as abominações que se viam na terra de Judá e em Jerusalém, para cumprir as palavras da lei que estavam escritas no livro que o sacerdote Hilquias havia achado na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Não houve tal rei antes dele que se convertesse ao SENHOR de todo seu coração, e de toda sua alma, e de todas suas forças, conforme a toda a lei de Moisés; nem depois dele nasceu outro tal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Contudo isso, o SENHOR não se desviou do ardor de sua grande ira, com que se havia encendido sua ira contra Judá, por todas as provocações com que Manassés lhe havia irritado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'E disse o SENHOR: Também tirarei de minha presença a Judá, como tirei a Israel, e abominarei a esta cidade que havia escolhido, a Jerusalém, e à casa da qual havia eu dito: Meu nome será ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Os demais dos feitos de Josias, e todas as coisas que fez, não está tudo escrito no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Em aqueles dias Faraó Neco rei do Egito subiu contra o rei da Assíria ao rio Eufrates, e saiu contra ele o rei Josias; mas aquele assim que lhe viu, o matou em Megido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'E seus servos o puseram em um carro, e trouxeram-no morto de Megido a Jerusalém, e sepultaram-no em seu sepulcro. Então o povo da terra tomou a Jeoacaz filho de Josias, e ungiram-lhe e puseram-no por rei em lugar de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'De vinte e três anos era Jeoacaz quando começou a reinar, e reinou três meses em Jerusalém. O nome de sua mãe foi Hamutal, filha de Jeremias de Libna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'E ele fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seus pais haviam feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'E lançou-o preso Faraó Neco em Ribla na província de Hamate, para que ele não reinasse em Jerusalém; e impôs sobre a terra uma multa de cem talentos de prata, e um de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Então Faraó Neco pôs por rei a Eliaquim filho de Josias, em lugar de Josias seu pai, e mudou-lhe o nome no de Jeoaquim; e tomou a Jeoacaz, e levou-o ao Egito, e morreu ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'E Jeoaquim pagou a Faraó a prata e o ouro; mas fez tributar a terra para dar o dinheiro conforme ao mandamento de Faraó, tirando a prata e ouro do povo da terra, de cada um segundo a avaliação de sua riqueza, para dar a Faraó Neco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'De vinte e cinco anos era Jeoaquim quando começou a reinar, e onze anos reinou em Jerusalém. O nome de sua mãe foi Zebida filha de Pedaías, de Ruma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'E fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seus pais haviam feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Em seu tempo subiu Nabucodonosor, rei de Babilônia, ao qual Jeoaquim serviu por três anos; depois voltou-se contra e se rebelou contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'O SENHOR, porém, enviou contra ele tropas de caldeus, e tropas de sírios, e tropas de moabitas, e tropas de amonitas; os quais enviou contra Judá para que a destruíssem, conforme a palavra do SENHOR que havia falado por meio dos seus servos, os profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Certamente foi por ordem do SENHOR que veio isto contra Judá, para tirá-la de sua presença, pelos pecados de Manassés, conforme tudo o que ele fez;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Também pelo sangue inocente que derramou, pois encheu Jerusalém de sangue inocente; o SENHOR, portanto, não quis perdoar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Os demais dos feitos de Jeoaquim, e todas as coisas que fez, não estão escritos no livro das crônicas dos reis de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'E descansou Jeoaquim com seus pais, e reinou em seu lugar seu filho Joaquim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'E nunca mais o rei do Egito saiu de sua terra; porque o rei da Babilônia lhe tomou tudo o que era seu, desde o rio do Egito até o rio de Eufrates.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Tinha Joaquim dezoito anos quando começou a reinar, e reinou em Jerusalém três meses. O nome de sua mãe foi Neusta filha de Elnatã, de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'E fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seu pai havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Naquele tempo subiram os servos de Nabucodonosor rei da Babilônia contra Jerusalém e a cidade foi cercada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Veio também Nabucodonosor rei da Babilônia contra a cidade, quando seus servos a tinham cercado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Então saiu Joaquim rei de Judá, para render-se ao rei da Babilônia, ele, e sua mãe, e seus servos, e seus príncipes, e seus eunucos; e o rei da Babilônia o prendeu no oitavo ano de seu reinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'E tirou dali todos os tesouros da casa do SENHOR, e os tesouros da casa real, e despedaçou todos os utensílios de ouro que havia feito Salomão rei de Israel na casa do SENHOR, como o SENHOR havia dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'E levou em cativeiro toda Jerusalém, todos os príncipes, e todos os homens valentes, até dez mil cativos, e todos os artesãos e ferreiros; que não restou ninguém, exceto os pobres do povo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Também levou cativo Joaquim à Babilônia, assim como a mãe do rei, as mulheres do rei, os seus eunucos, e os poderosos do país; cativos os levou de Jerusalém à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'A todos os homens de guerra, que foram sete mil, e aos oficiais e ferreiros, que foram mil, e a todos os valentes para fazer a guerra, levou cativos o rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'E o rei da Babilônia pôs como rei em lugar de Joaquim a Matanias, tio dele, e mudou-lhe o nome para Zedequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'De vinte e um anos era Zedequias quando começou a reinar, e reinou em Jerusalém onze anos. O nome de sua mãe foi Hamutal filha de Jeremias, de Libna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'E fez o que era mau aos olhos do SENHOR, conforme a tudo o que havia feito Jeoaquim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Assim aconteceu por causa da ira do SENHOR contra Jerusalém e Judá, até que os expulsou de sua presença. E Zedequias se rebelou contra o rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'E aconteceu aos nove anos de seu reinado, no mês décimo, aos dez do mês, que Nabucodonosor rei da Babilônia veio com todo seu exército contra Jerusalém, e cercou-a; e levantaram contra ela rampas de cerco ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'E esteve a cidade cercado até o décimo primeiro ano do rei Zedequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Aos nove do mês prevaleceu a fome na cidade, que não houve pão para o povo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Aberta já a cidade, fugiram de noite todos os homens de guerra pelo caminho da porta que estava entre os dois muros, junto aos jardins do rei, estando os caldeus ao redor da cidade; e o rei se foi caminho da campina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'E o exército dos caldeus seguiu o rei, e tomou-o nas planícies de Jericó, e todo o seu exército se dispersou dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Tomado, pois, o rei, trouxeram-no ao rei da Babilônia a Ribla, e proferiram contra ele sentença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'E degolaram aos filhos de Zedequias em sua presença; e a Zedequias tiraram os olhos, e acorrentado com correntes levaram-no à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'No mês quinto, aos sete do mês, sendo o ano dezenove de Nabucodonosor rei da Babilônia, veio a Jerusalém Nebuzaradã, capitão dos da guarda, servo do rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'E queimou a casa do SENHOR, e a casa do rei, e todas as casas de Jerusalém; e todas as casas dos príncipes queimou a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'E todo o exército dos caldeus que estava com o capitão da guarda, derrubou os muros de Jerusalém ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'E aos do povo que haviam restado na cidade, e aos que se haviam juntado ao rei da Babilônia, e aos que haviam restado da população, transportou-o Nebuzaradã, capitão dos da guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Mas dos pobres da terra deixou Nebuzaradã, capitão dos da guarda, para que lavrassem as vinhas e as terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'E quebraram os caldeus as colunas de bronze que estavam na casa do SENHOR, e as bases, e o mar de bronze que estava na casa do SENHOR, e levaram o bronze disso à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Levaram-se também as caldeiras, e as pás, e as tenazes, e as colheres, e todos os vasos de bronze com que ministravam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Incensários, bacias, os que de ouro, em ouro, e os que de prata, em prata, tudo o levou o capitão dos da guarda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'As duas colunas, um mar, e as bases que Salomão havia feito para a casa do SENHOR: não havia peso de todos estes vasos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'A altura da uma coluna era dezoito côvados e tinha encima um capitel de bronze, e a altura do capitel era de três côvados; e sobre o capitel havia um enredado e romãs ao redor, todo de bronze: e semelhante obra havia na outra coluna com o enredado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Tomou então o capitão dos da guarda a Seraías o sacerdote principal, e a Sofonias o segundo sacerdote, e três guardas da porta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'E da cidade tomou um eunuco, o qual comandava os soldados, e cinco homens dos assistentes do rei, que se acharam na cidade; e ao principal escriba do exército, que fazia o registro da gente do país; e sessenta homens do povo da terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Estes tomou Nebuzaradã, capitão dos da guarda, e levou-os a Ribla ao rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'E o rei da Babilônia os feriu e matou em Ribla, em terra de Hamate. Assim foi transportado Judá de sobre sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'E ao povo que Nabucodonosor rei da Babilônia deixou em terra de Judá, pôs por governador a Gedalias, filho de Aicã filho de Safã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'E ouvindo todos os príncipes do exército, eles e sua gente, que o rei da Babilônia havia posto por governador a Gedalias, vieram-se a ele em Mispá, a saber, Ismael filho de Netanias, e Joanã filho de Careá, e Seraías filho de Tanumete netofatita, e Jazanias filho do maacatita, eles com os seus subordinados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Então Gedalias lhes fez juramento, a eles e aos seus subordinados, e disse-lhes: Não temais de ser servos dos caldeus; habitai na terra, e servi ao rei da Babilônia, e vos irá bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Mas no mês sétimo veio Ismael filho de Netanias, filho de Elisama, da família real, e com ele dez homens, e feriram a Gedalias, e morreu, assim como os judeus e os caldeus que estavam com ele em Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'E levantando-se todo o povo, desde o menor até o maior, com os capitães do exército, foram-se ao Egito por temor dos caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'E aconteceu aos trinta e sete anos do cativeiro de Joaquim rei de Judá, no décimo segundo mês, aos vinte e sete do mês, que Evil-Merodaque rei da Babilônia, no primeiro ano de seu reinado, concedeu favor a Joaquim rei de Judá, tirando-o da prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'E falou-lhe bem, e pôs seu assento em posição de maior honra do que o assento dos reis que estavam com ele na Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'E mudou-lhe as roupas de sua prisão, e comeu sempre diante dele todos os dias de sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'E foi-lhe continuamente dada a sua subsistência diária da parte do rei, por todos os dias de sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adão, Sete, Enos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Cainã, Maalalel, Jarede,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enoque, Matusalém, Lameque,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noé, Sem, Cam, e Jafé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Os filhos de Jafé foram: Gômer, Magogue, Dadai, Javã, Tubal, Meseque, e Tiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Os filhos de Gômer: Asquenaz, Rifate, e Togarma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Os filhos de Javã: Elisá, Társis, Quitim, e Dodanim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Os filhos de Cam: Cuxe, Misraim, Pute, e Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Os filhos de Cuxe: Sebá, Havilá, Sabtá, Raamá, e Sabtecá. E os filhos de Raamá foram: Sebá e Dedã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'E Cuxe gerou a Ninrode: este começou a ser poderoso na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Misraim gerou aos ludeus, aos ananeus, aos leabeus, aos leabeus, aos naftueus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Aos patrusitas, e aos casluítas (destes saíram os Filisteus), e os caftoreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'E Canaã gerou a Sidom, seu primogênito; e a Hete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'E aos jebuseus, aos amorreus, aos girgaseus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Aos heveus, aos arqueus, ao sineus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Aos arvadeus, aos zemareus, e aos hamateus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Os filhos de Sem foram: Elão, Assur, Arfaxade, Lude, Arã, Uz, Hul, Geter, e Meseque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arfaxade gerou a Selá, e Selá gerou a Héber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'E a Héber nasceram dois filhos: o nome do um foi Pelegue, pois em seus dias a terra foi dividida; e o nome de seu irmão foi Joctã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'E Joctã gerou a Almodá, Salefe, Hazarmavé, e Jerá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'E a Adorão, Uzal, Dicla,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Sebá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofir, Havilá, e a Jobabe: todos filhos de Joctã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arfaxade, Selá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Héber, Pelegue, Reú,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serugue, Naor, Terá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'E Abrão, o qual é Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Os filhos de Abraão foram: Isaque e Ismael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'E estas são suas gerações: o primogênito de Ismael foi Nebaiote; depois Quedar, Adbeel, Mibsão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Dumá, Massá, Hadade, Temá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafis, e Quedemá. Estes foram os filhos de Ismael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Quanto aos filhos de Quetura, concubina de Abraão, esta deu à luz Zinrã, Jocsã, Medã, Midiã, Isbaque, e a Suá. Os filhos de Jobsã: Sebá e Dedã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Os filhos de Midiã: Efá, Efer, Enoque, Abida, e Elda; todos estes foram filhos de Quetura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'E Abraão gerou a Isaque: e os filhos de Isaque foram Esaú e Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Os filhos de Esaú: Elifaz, Reuel, Jeús, Jalão, e Corá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Os filhos de Elifaz: Temã, Omar, Zefi, Gatã, Quenaz, Timna, e Amaleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Os filhos de Reuel: Naate, Zerá, Samá, e Mizá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Os filhos de Seir: Lotã, Sobal, Zibeão, Ana, Disom, Eser, e Disã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Os filhos de Lotã: Hori, e Homã: e Timna foi irmã de Lotã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Os filhos de Sobal: Aliã, Manaate, Ebal, Sefi e Onã. Os filhos de Zibeão foram: Aiá, e Aná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Disom foi filho de Aná: e os filhos de Disom foram Hanrão, Esbã, Itrã e Querã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Os filhos de Eser foram: Bilã, Zaavã, e Jaacã. Os filhos de Disã: Uz e Arã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'E estes são os reis que reinaram na terra de Edom, antes que reinasse algum rei sobre os filhos de Israel: Belá, filho de Beor; e o nome de sua cidade era Dinabá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Belá morreu, e reinou em seu lugar Jobabe, filho de Zerá, de Bozra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Jobabe morreu, e reinou em seu lugar Husão, da terra dos Temanitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Husão morreu, e reinou em seu lugar Hadade, filho de Bedade, o qual feriu aos midianitas no campo de Moabe; e o nome de sua cidade era Avite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Hadade morreu, e reinou em seu lugar Sanlá, de Masreca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Sanlá morreu, e reinou em seu lugar Saul de Reobote, que está junto ao rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'E Saul morreu, e reinou em seu lugar Baal-Hanã, filho de Acbor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'E Baal-Hanã morreu, e reinou em seu lugar Hadade, cuja cidade tinha por nome Paí; e o nome de sua mulher era Meetabel, filha de Matrede, a filha de Mezaabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Hadade morreu. E os príncipes em Edom foram: o príncipe Timna, o príncipe Aliá, o príncipe Jetete,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'O príncipe Oolibama, o príncipe Elá, o príncipe Pinom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'O príncipe Quenaz, o príncipe Temã, o príncipe Mibzar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'O príncipe Magdiel, o príncipe Irã. Estes foram os príncipe de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Estes são os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar, Zebulom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dã, José, Benjamim, Naftali, Gade, e Aser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Os filhos de Judá foram: Er, Onã, e Selá. Estes três lhe nasceram de Bete-Suá, Cananeia. E Er, primogênito, de Judá, foi mau diante do Senhor, que o matou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'E Tamar, sua nora, lhe deu à luz Perez e a Zerá. Todos os filhos de Judá foram cinco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Os filhos de Perez: Hezrom e Hamul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'E os filhos de Zerá: Zinri, Etã, Hemã, e Calcol, e Darda; cinco ao todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'O filho de Carmi foi Acar, o perturbador de Israel, porque transgrediu naquilo que estava separado por maldiçãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'O filho de Etã foi Azarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Os filhos que nasceram a Hezrom foram: Jerameel, Rão, e Quelubai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'E Rão gerou a Aminadabe; e Aminadabe gerou a Naasom, príncipe dos filhos de Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'E Naasom gerou a Salmom, e Salmom gerou a Boaz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'E Boaz gerou a Obede, e Obede gerou a Jessé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'E Jessé gerou a Eliabe, seu primogênito, e o segundo Abinadabe, o terceiro Simeia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'O quarto Natanael, o quinto Radai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'O sexto Ozém, o sétimo Davi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'As irmãs dos quais foram Zeruia e Abigail. Os filhos de Zeruia foram três: Abisai, Joabe, e Asael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'E Abigail deu à luz Amasa, cujo pai foi Jéter, o Ismaelita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'E Calebe filho de Hezrom gerou de sua mulher Azuba, e de Jeriote. E os filhos dela foram: Jeser, Sobabe, e Ardom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'E Azuba morreu, e Calebe tmou por mulher a Efrate, a qual lhe gerou a Hur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'E Hur gerou a Uri, e Uri gerou a Bezalel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Depois Hezrom se deitou com a filha de Maquir, pai de Gileade, a qual ele tomou por esposa quando ele tinha sessenta anos, e ela lhe gerou a Segube.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'E Segube gerou a Jair, que teve vinte e três cidades na terra de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'E Gesur e Arã tomaram deles as cidades de Jair, e a Quenate com suas aldeias, sessenta cidades. Todos estes foram filhos de Maquir, pai de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'E depois da morte de Hezrom, em Calebe de Efrata, Abia mulher de Hezrom, lhe gerou a Asur, pai de Tecoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'E os filhos de Jerameel primogênito de Hezrom foram: Rão (seu primogênito), Buna, Orém, Ozém, e Aías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerameel também teve outra mulher chamada Atara, que foi mãe de Onã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'E os filhos de Rão, primogênito de Jerameel, foram: Maaz, Jamim, e Equer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'E os filhos de Onã foram: Samai, e Jada. E os filhos de Samai: Nadabe, e Abisur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'E o nome da mulher de Abisur era Abiail, a qual lhe gerou a Abã e a Molide.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'E os filhos de Nadabe foram: Selede e Apaim. E Selede morreu sem filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'E o filho de Apaim foi Isi; o filho de Isi foi Sesã; e o filho de Sesã foi Alai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'E os filhos de Jada, irmão de Simmai, foram: Jéter e Jônatas. E Jéter morreu sem filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'E os filhos de Jônatas foram: Pelete, e Zaza. Estes foram os filhos de Jerameel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'E Sesã não teve filhos, mas somente filhas. E Sesã tinha um servo egípcio, cujo nome era Jará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Sesã deu sua filha a seu servo Jará, e ela lhe gerou a Atai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'E Atai gerou a Natã, e Natã gerou a Zabade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'E Zabade gerou a Eflal, e Eflal gerou a Obede;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'E Obede gerou a Jeú, e Jeú gerou a Azarias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'E Azarias gerou a Helez, Helez gerou a Eleasá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleasá gerou a Sismai, e Sismai gerou a Salum;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'E Salum gerou a Jecamias, e Jecamias gerou a Elisama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Os filhos de Calebe, irmão de Jerameel, foram: Messa seu primogênito, que foi o pai de Zife; e os filhos de Maressa, pai de Hebrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'E os filhos de Hebrom foram: Corá, Tapua, Requém, e Sema.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'E Sema gerou a Raão, pai de Jorqueão; e Requém gerou a Samai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'E o filho de Samai foi Maom, e Maom foi pai de Bete-Zur.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'E Efá, a concubina de Calebe, lhe gerou a Harã, Moza, e a Gazez. E Harã gerou a Gazez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'E os filhos de Jadai foram: Regém, Jotão, Gesã, Pelete, Efá, e Saafe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaca, concubina de Calebe, lhe gerou a Seber, e a Tiraná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Ela também deu à luz a Saafe, pai de Madmana, e a Seva, pai de Macbena e pai de Gibeá. E a filha de Calebe foi Acsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Estes foram os filhos de Calebe, filho de Hur, primogênito de Efrata: Sobal, pai de Quiriate-Jearim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, pai dos belemitas; e Harefe, pai de Bete-Gader.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'E os filhos de Sobal, pai de Quiriate-Jearim foram: Haroé, a metade dos Manaatitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'E as famílias de Quiriate-Jearim foram os itreus, os puteus, os sumateus, e os misraeus; destes saíram os zorateus e os estaoleus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Os filhos de Salma foram: Belém, e os netofatitas, Atarote, Bete-Joabe; e da metade dos manaatitas, e os zoritas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'E as famílias dos escribas, que habitavam em Jabez, foram os tiratitas, os simeatitas, e os sucatitas; estes foram os queneus que vieram de Hamate, pai da casa de Recabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Estes são os filhos de Davi, que lhe nasceram em Hebrom: Amnom, o primogênito, de Ainoã Jezreelita; o segundo Daniel, de Abigail de Carmelo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'O terceiro, Absalão, filho de Maaca, filha de Talmai, rei de Gesur; o quarto, Adonias, filho de Hagite;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'O quinto, Sefatias, de Abital; o sexto, Itreão, de sua mulher Eglá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Estes seis lhe nasceram em Hebrom, de onde reinou sete anos e seis meses; e em Jerusalém reinou trinta e três anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Estes lhe nasceram em Jerusalém: Simeia, Sobabe, Natã, e Salomão, estes quatro de Bate-Sua, filha de Amiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Nasceram-lhe mais: Ibar, Elisama, Elifelete,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogá, Nefegue, Jafia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eliada, e Elifelete, nove.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Todos estes foram os filhos de Davi, exceto os filhos das concubinas. E Tamar foi irmã deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'E o filho de Salomão foi Roboão, cujo filho foi Abias, cujo filho foi Asa, cujo filho foi Jeosafá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Cujo filho foi Jorão, cujo filho foi Acazias, cujo filho foi Joás;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Cujo filho foi Amazias, cujo filho foi Azarias, cujo filho foi Jotão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Cujo filho foi Acaz, cujo filho foi Ezequias, cujo filho foi Manassés;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Cujo filho foi Amom, cujo filho foi Josias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'E os filhos de Josias foram: Joanã seu primogênito, o segundo Jeoaquim, o terceiro Zedequias, o quarto Salum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Os filhos de Jeoaquim foram: seu filho Jeconias, e seu filho Zedequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'E os filhos de Jeconias, o cativo, foram: seu filho Sealtiel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malquirão, Pedaías, Senazar, Jecamias, Hosama, e Nedabias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'E os filhos de Pedaías foram: Zorobabel, e Simei. E os filhos de Zorobabel foram: Mesulão, Hananias, e sua irmã Selomite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'E os cinco outros: Hasubá, Oel, Berequias, Hasadias, e Jusabe-Hesede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Os filhos de Hananias: Pelatias, e Jesaías, os filhos de Refaías, os filhos de Arnã, os filhos de Obadias, e os filhos de Secanias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'E o filho de Secanias foi Semaías; e os filhos de Samaías foram seis: Hatus, Igal, Bariá, Nearias, e Safate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'E os filhos de Nearias foram três: Elioenai, Ezequias, e Azricão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Os filhos de Elioenai foram sete: Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías, e Anani.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Os filhos de Judá foram: Perez, Hezrom, Carmi, Hur, e Sobal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'E Reaías, filho de Sobal, gerou a Jaate; e Jaate gerou a Aumai e a Laade. Estas são as famílias dos Zoratitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'E estas são as do pai de Etã: Jezreel, Isma, e Idbás. E o nome da irmã deles era Hazelelponi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'E Penuel foi pai de Gedor, e Ézer pai de Husá. Estes foram os filhos de Hur, primogênito de Efrata, pai de Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'E Asur, pai de Tecoa, teve duas mulheres: Helá, e Naará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'E Naará lhe gerou a Auzão, Héfer, Temeni, e a Haastari. Estes foram os filhos de Naará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'E os filhos de Helá foram: Zerete, Zoar, e Etnã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'E Coz gerou a Anube, e a Zobeba, e as famílias de Aarel, filho de Harum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'E Jabez foi mais honrado que seus irmãos; sua mãe o chamara de Jabez, dizendo: Pois com dores eu o dei à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Mas Jabez invocou ao Deus de Israel, dizendo: Ah, se tu me abençoares muito, e ampliares os meus limites, e se tua mão for comigo, e me protegeres do mal, para que eu não sofra! E Deus fez suceder o que ele havia pedido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'E Quelube, irmão de Suá gerou a Maquir, que foi o pai de Estom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'E Estom gerou a Bete-Rafa, Paseia, e a Teína, pai da cidade de Naás; estes foram os homens de Reca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Os filhos de Quenaz foram: Otniel e Seraías. Os filhos de Otniel: Hatate e Meonotai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'E Meonotai gerou a Ofra; e Seraías gerou a Joabe, pai dos moradores do Vale dos Artesãos, porque foram artesãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Os filhos de Calebe, filho de Jefoné foram: Iru, Elá, e Naã; e filho de Elá foi Quenaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Os filhos de Jealelel foram: Zife, Zifa, Tíria, e Asareel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'E os filhos de Ezra foram: Jéter, Merede, Efer, e Jalom. E sua mulher também deu à luz a Miriã, Samai, e a Isbá, pai de Estemoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'E sua mulher Judia lhe deu à luz a Jerede pai de Gedor, a Héber pai de Socó, e a Jecutiel pai de Zanoa. Estes foram os filhos de Bitias, filha de Faraó, a qual Merede teve por esposa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'E os filhos da mulher de Hodias, irmã de Naã, foram: o pai de Queila o garmita, e Estemoa o maacatita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'E os filhos de Simeão foram: Amnom, Rina, Ben-Hanã, e Tilom. E os filhos de Isi foram: Zoete, e Ben-Zoete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Os filhos de Selá, filho de Judá foram: Er, pai de Leca, e Lada, pai de Maressa, e as famílias da casa dos trabalhadores do linho em Bete-Asbeia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Como também Joquim, os homens de Cozeba, Joás, e Sarafe (os quais dominaram sobre os moabitas), e Jasubi-Leem. Estes registros, porém, são antigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Estes foram oleiros, e habitavam em Netaim e Gedera; eles ficaram ali com o rei em sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Os filhos de Simeão foram: Nemuel, Jamim, Jaribe, Zerá, Saul;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Cujo filho foi Salum, cujo filho foi Mibsão, cujo filho foi e Misma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Os filhos de Misma foram: seu filho Hamuel, cujo filho foi Zacur, cujo filho foi Simei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'E Simei teve dezesseis filhos e seis filhas, porém seus irmãos não tiveram muitos filhos, e toda a sua família não se multiplicou tanto como a dos filhos de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'E habitaram em Berseba, Moladá, Hazar-Sual,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'E em Bila, Ezém, Tolade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Betuel, Hormá, Ziclague.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Bete-Marcabote, Hazar-Susim, Bete-Birai, e em Saaraim. Estas foram suas cidades até quando Davi começou a reinar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'E suas aldeias foram: Etã, Aim, Rimom, e Toquém, e Asã, cinco cidades;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'E todas as suas aldeias que estavam ao redor destas cidades, até Baal. Estas foram suas habitações, e suas genealogias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Porém Mesobabe, Janleque, Josias filho de Amazias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel, Jeú filho de Josibias, filho de Seraías, filho de Asiel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'E Elioenai, Jaacobá, Jesoaías, Asaias, Adiel, Jesimiel, Benaia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'E Ziza filho de Sifi, filho de Alom, filho de Jedaías, filho de Sinri, filho de Semaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Estes registrados por seus nomes foram os líderes de suas famílias, e que foram multiplicados muito nas casas de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'E chegaram até a entrada de Gedor, até o oriente do vale, buscando pastos para suas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'E acharam pastos férteis e bons, e a terra era espaçosa, quieta, e descansada, porque os de Cam tinham habitado ali antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Estes, pois, que foram escritos por seus nomes, vieram nos dias de Ezequias rei de Judá, e derrubaram as tendas e habitações dos que se acharam ali, e os destruíram até hoje; e habitaram ali em seu lugar, porque ali havia pastos para suas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Também alguns deles, quinhentos homens dos filhos de Simeão, se foram ao monte de Seir, levando como capitães a Pelatias, Nearias, Refaías, e a Uziel, filhos de Isi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'E mataram os que haviam restado dos amalequitas, e habitaram ali até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Quanto aos filhos de Rúben, primogênito de Israel (porque ele era o primogênito, mas como profanou a cama de de seu pai, seu direito de primogenitura foi dado aos filhos de José, filho de Israel; e não foi contado por primogênito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Pois Judá foi o mais poderoso sobre seus irmãos, e o líder veio dele; mas o direito de primogenitura pertenceu a José).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Os filhos de Rúben, primogênito de Israel, foram, pois: Enoque, Palu, Hezrom e Carmi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Os filhos de Joel foram: seu filho Semaías, seu filho Gogue, seu filho Simei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Seu filho Mica, seu filho Reaías, seu filho Baal;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Seu filho Beera, o qual foi transportado por Tiglate-Pilneser, rei dos Assírios. Este era um líder dos Rubenitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'E seus irmãos por suas famílias, quando foram registrados em suas descendências, tinham por líderes a Jeiel, Zacarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'E Belá, filho de Azaz, filho de Sema, filho de Joel. Eles habitaram em Aroer até Nebo e Baal-Meom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Habitaram também desde o oriente até a entrada do deserto desde o rio Eufrates; porque seu gado tinha se multiplicado na terra de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'E nos dias de Saul fizeram guerra contra os hagarenos, que caíram em suas mãos; e eles habitaram em suas tendas sobre toda a região oriental de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'E os filhos de Gade habitaram na vizinhança deles na terra de Basã até Salca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'E Joel foi o líder em Basã, o segundo Safã, em seguida Janai, e Safate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'E seus irmãos, segundo as famílias de seus pais, foram sete: Micael, Mesulão, Sebá, Jorai, Jacã, Zia, e Héber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Estes foram os filhos de Abiail filho de Huri, filho de Jaroa, filho de Gileade, filho de Micael, filho de Jesisai, filho de Jado, filho de Buz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Aí, filho de Abdiel, filho de Guni, foi chefe da casa de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Eles habitaram em Gileade, em Basã, e em suas aldeias, e em todos os campos de Sarom até os seus extremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Todos estes foram contados segundo suas genealogias nos dias de Jotão, rei de Judá, e no dias de Jeroboão, rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Os filhos de Rúben, e de Gade, e da meia tribo de Manassés, homens guerreiros, homens que traziam escudo e espada, que entesavam arco, e habilidosos em guerra, havia quarenta e quatro mil setecentos e sessenta capazes de ir para a batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'E fizeram guerra contra os Hagarenos, como também a Jetur, Nafis, e Nodabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'E foram ajudados contra ele; assim os hagarenos, e todos quantos estavam com eles, foram enregues em suas mãos, porque clamaram a Deus na batalha, e ele lhes atendeu, pois confiaram nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'E tomaram seu gado, cinquenta mil de seus camelos, duzentas e cinquenta mil ovelhas, dois mil asnos, e cem mil pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'E muitos caíram mortos, porque a guerra era de Deus; e habitaram em seus lugares até o cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'E os filhos da meia tribo de Manassés habitaram naquela terra, e eles se multiplicaram desde Basã até Baal-Hermom, e Senir e o monte de Hermom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'E estes foram os cabeças das casas de seus pais: Efer, Isi, Eliel, Azriel, Jeremias, Hodavias, e Jadiel, homens valentes e fortes, homens renomados, e cabeças das casas de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Porém eles transgrediram contra o Deus de seus pais, e se prostituíram seguindo os deuses dos povos da terra, aos quais o SENHOR havia destruído de diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Por isso o Deus de Israel despertou ao espírito de Pul, rei da Assíria, e ao espírito de Tiglate-Pilneser, rei da Assíria, o qual levou presos os rubenitas, os gaditas e à meia tribo de Manassés, e os trouxe até Hala, Habor, Hara, e ao rio Gozã, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Os filhos de Levi foram: Gérson, Coate, e Merari.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Os filhos de Coate: Anrão, Izar, Hebrom e Uziel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Os filhos de Anrão: Arão, Moisés, e Miriã. E os filhos de Arão foram: Nadabe, Abiú, Eleazar, e Itamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'E Eleazar gerou a Fineias, Fineias gerou a Abisua;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua gerou a Buqui, Buqui gerou a Uzi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Uzi gerou a Zeraías, Zeraías gerou a Meraiote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Meraiote gerou a Amarias, Amarias gerou a Aitube;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Aitube gerou a Zadoque, Zadoque gerou a Aimaaz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Aimaaz gerou a Azarias, Azarias gerou a Joanã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Joanã gerou a Azarias (este é o que administrou o sacerdócio na casa que Salomão edificou em Jerusalém);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azarias gerou a Amarias, Amarias gerou a Aitube;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Aitube gerou a Zadoque, Zadoque gerou a Salum;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Salum gerou a Hilquias, Hilquias gerou a Azarias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azarias gerou a Seraías, Seraías, gerou a Jeozadaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'E Jeozadaque foi levado cativo quando O SENHOR levou Judá e a Jerusalém como prisioneiros, pela mão de Nabucodonosor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Os filhos de Levi foram: Gérson, Coate, e Merari.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'E estes são os nomes dos filhos de Gérson: Libni, e Simei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Os filhos de Coate: Anrão, Izar, Hebrom, e Uziel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Os filhos de Merari: Mali, e Musi. Estas são as famílias de Levi, segundo seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'De Gérson: seu filho Libni, seu filho Jaate, seu filho Zima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Seu filho Joabe, seu filho Ido, seu filho Zerá, e seu filho Jeaterai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Os filhos de Coate foram: seu filho Aminadabe, seu filho Corá, seu filho Assir,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Seu filho Elcana, seu filho Ebiasafe, seu filho Assir,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Seu filho Taate, seu filho Uriel, seu filho Uzias, e seu filho Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'E os filhos Elcana foram: Amasai e Aimote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Quanto a Elcana, os filhos de Elcana foram: seu filho Zofai, seu filho Naate,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Seu filho Eliabe, seu filho Jeroão, e seu filho Elcana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'E os filhos de Samuel foram: o primogênito Vasni, e Abias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Os filhos de Merari: Mali, seu filho Libni, seu filho Simei, seu filho Uzá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Seu filho Simeia, seu filho Hagias, e seu filho Asaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Estes, pois, são os que Davi constituiu para o ofício da música da casa do Senhor, depois que a arca teve repouso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'E eles serviam diante da tenda do tabernáculo da congregação com cânticos, até que Salomão edificou a casa do SENHOR em Jerusalém; e estiveram segundo seu costume em seu serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Estes, pois, foram os que ali estavam com seus filhos: dos filhos dos coatitas, Hemã, o cantor, filho de Joel, filho de Samuel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Filho de Elcana, filho de Jeroão, filho de Eliel, filho de Toá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Filho de Zufe, filho de Elcana, filho Maate, filho de Amasai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Filho de Taate, filho de Assir, filho de Ebiasafe, filho de Corá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Filho de Izar, filho de Coate, filho de Levi, filho de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'E seu irmão Asafe estava à sua direita; Asafe era, filho de Berequias, filho de Simeia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Filho de Micael, filho de Baaseias, filho de Malquias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Filho de Etni, filho de Zerá, filho de Adaías,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Filho de Etã, filho de Zima, filho de Simei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Filho de Jaate, filho de Gérson, filho de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'E seus irmãos, os filhos de Merari, estavam à esquerda; eram eles: Etã, filho de Quisi, filho de Abdi, filho de Maluque,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Filho de Hasabias, filho de Amazias, filho de Hilquias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Filho de Anzi, filho de Bani, filho de Semer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Filho de Mali, filho de Musi, filho de Merari, filho de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'E seus irmãos, os Levitas, foram postos para todo o serviço do tabernáculo da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'E Arão e seus filhos ofereciam incenso sobre o altar da oferta de queima, e sobre o altar do incenso, para toda a obra do lugar santíssimo, e para fazer expiação sobre Israel, conforme tudo quanto Moisés, servo de Deus, havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'E estes foram os filhos de Arão: seu filho Eleazar, seu filho Fineias, seu filho Abisua,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Seu filho Buqui, seu filho Uzi, seu filho Zeraías,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Seu filho Meraiote, seu filho Amarias, seu filho Aitube,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Seu filho Zadoque, e seu filho Aimaaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'E estas foram suas habitações, conforme seus acampamentos e seus termos, dos filhos de Arão da família dos coatitas, porque eles foram sorteados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Deram-lhes, pois, a Hebrom na terra de Judá, e seus campos ao redor dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Porém o território da cidade e suas aldeias foram dadas a Calebe, filho de Jefoné.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'E aos filhos de Arão deram as seguintes cidades de refúgio: Hebrom, e Libna com seus campos; Jathir e Estemoa com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Hilém com seus campos; Debir com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asã com seus campos; e a Bete-Semes com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'E da tribo de Benjamim, a Geba com seus campos; Alemete com seus campos; e Anatote com seus campos. Todas as suas cidades, repartidas por suas famílias, foram treze cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Mas aos filhos de Coate, que restaram da família daquela tribo, deram por sorteio dez cidades da meia tribo de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'E aos filhos de Gérson, segundo suas famílias, deram treze cidades da tribo de Issacar, da tribo de Aser, da tribo de Naftali, e da tribo de Manassés, em Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'E aos filhos de Merari, segundo suas famílias, deram por sorteio doze cidades da tribo de Rúben, da tribo de Gade, e da tribo de Zebulom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Assim os filhos de Israel deram aos Levitas estas cidades com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'E deram-lhes por sorteio, da tribo dos filhos de Judá, da tribo dos filhos de Simeão, e da tribo dos filhos de Benjamim, estas cidades, as quais mencionaram por seus nomes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'E quanto ao resto das famílias dos filhos de Coate deram-lhes cidades com seus termos da tribo de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'E deram-lhes das cidades de refúgio, a Siquém e seus campos nas montanhas de Efraim, e a Gezer com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'A Jocmeão com seus campos, a Bete-Horom com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'A Aijalom com seus campos, e a Gate-Rimom com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Da meia tribo de Manassés, a Aner com seus campos, e a Bileã com seus campos, para os que restaram da família dos filhos de Coate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Aos filhos de Gérson deram da família da meia tribo de Manassés, a Golã em Basã com seus campos e a Astarote com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'E da tribo de Issacar, a Quedes com seus campos, a Daberate com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'A Ramote com seus campos, e a Aném com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'E da tribo de Aser a Masal com seus campos, a Abdom com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'A Hucoque com seus campos, e a Reobe com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'E da tribo de Naftali, a Quedes na Galileia com seus campos, a Hamom com seus campos, e a Quiriataim com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'E aos que restaram dos filhos de Merari, deram da tribo de Zebulom, a Rimono com seus campos, e a Tabor com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'E dalém do Jordão de Jericó, ao oriente do Jordão, deram da tribo de Rúben, a Bezer no deserto com seus campos; a Jaza com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'A Quedemote com seus campos, e a Mefaate com seus campos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'E da tribo de Gade, a Ramote em Gileade com seus campos, a Maanaim com seus campos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'A Hesbom com seus campos, e a Jazer com seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Os filhos de Issacar foram quatro: Tolá, Pua, Jasube, e Sinrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Os filhos de Tolá foram: Uzi, Refaías, Jeriel, Jamai, Ibsão e Samuel, cabeças das famílias de seus pais. De Tolá foram contados por suas genealogias no tempo de Davi vinte e dois mil seiscentos homens guerreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'O filho de Uzi foi Izraías; e os filhos de Izraías foram: Micael, Obadias, Joel, e Issias; todos estes cinco foram líderes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'E havia com eles em suas genealogias, segundo as famílias de seus pais, trinta e seis mil homens de guerra, porque tiveram muitas mulheres e filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'E seus irmãos em todas as famílias de Issacar, todos contados por suas genealogias, foram oitenta e sete mil guerreiros valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Os filhos de Benjamim foram três: Belá, Bequer, e Jediael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Os filhos de Belá foram: Esbom, Uzi, Uziel, Jerimote, e Iri; cinco cabeças de famílias paternas, guerreiros valentes, dos quais foram contados por suas genealogias vinte e dois mil e trinta e quatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Os filhos de Bequer: Zemira, Joás, Eliézer, Elioenai, Onri, Jerimote, Abias, Anatote e Alemete; todos estes foram filhos de Bequer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'E foram contados por suas genealogias, segundo suas descendências, e os cabeças de suas famílias, vinte mil e duzentos guerreiros valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'E o filho de Jediael foi Bilã; e os filhos de Bilã foram: Jeús, Benjamim, Eúde, Quenaaná, Zetã, Társis, e Aisaar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Todos estes filhos de Jediael foram cabeças de famílias, guerreiros valentes, dezessete mil e duzentos que saíam com o exército para a guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Supim e Hupim foram filhos de Ir; e Husim foi filho de Aer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Os filhos de Naftali foram: Jaziel, Guni, Jezer, e Salum, filhos de Bila.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Os filhos de Manassés foram: Asriel, o qual foi nascido de sua concubina, a síria, a qual também lhe deu à luz Maquir, pai de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'E Maquir tomou por mulher a irmã de Hupim e Supim, cuja irmã teve por nome Maaca. O nome do segundo foi Zelofeade. E Zelofeade teve somente filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'E Maaca mulher de Maquir lhe gerou um filho, e chamou seu nome Perez; e o nome de seu irmão foi Seres, cujos filhos foram Ulão e Requém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'E o filho de Ulão foi Bedã. Estes foram os filhos de Gileade, filho de Maquir, filho de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'E sua irmã Hamolequete deu à luz Isode, Abiezer, e Maalá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'E os filhos de Semida foram Aiã, Siquém, Liqui, e Anião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Os filhos de Efraim: Sutela, seu filho Berede, seu filho Taate, seu filho Eleada, seu filho Taate,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Seu filho Zabade, seu filho Sutela, seu filho, Ézer, e Eleade. Mas os homens de Gate, naturais daquela terra, os mataram, porque desceram para tomar seus gados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Por isso seu pai Efraim esteve de luto por muitos dias, e seus irmãos vieram consolá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Depois ele se deitou com sua mulher, ela concebeu, e deu à luz um filho, ao qual chamou por nome Berias, pois o desastre havia ocorrido em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'E sua filha foi Seerá, a qual edificou a Bete-Horom, a baixa e a alta, como também a Uzém-Seerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'E seu filho foi Refa, seu filho Resefe, seu filho Telá, seu filho Taã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Seu filho Laadã, seu filho Amiúde, seu filho Elisama,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Seu filho Num, e seu filho Josué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'E a propriedade e habitação deles foi Betel com suas aldeias, e ao oriente Naarã, e ao ocidente Gezer e suas aldeias, como também Siquém com suas aldeias, até Aia e suas aldeias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'E da parte dos filhos de Manassés, Bete-Seã com suas aldeias, Taanaque com suas aldeias, Megido com suas aldeias, e Dor com suas aldeias. Nestes lugares habitaram os filhos de José, filho de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Os filhos de Aser foram: Imná, Isvá, Isvi, Berias, e sua irmã Sera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Os filhos de Berias foram: Héber, e Malquiel, o qual foi pai de Bizarvite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'E Héber gerou a Jaflete, Semer, Hotão, e sua irmã Suá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Os filhos de Jaflete foram: Pasaque, Bimal, e Asvate. Estes foram os filhos de Jaflete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Os filhos de Semer foram: Aí, Roga, Jeubá, e Arã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Os filhos de seu irmão Helém foram: Zofa, Imná, Seles, e Amal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Os filhos de Zofa foram: Suá, Harnefer, Sual, Beri, Inra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bezer, Hode, Samá, Silsa, Iltrã e Beera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Os filhos de Jéter foram: Jefoné, Pispa, e Ara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'E os filhos de Ula foram; Ara, Haniel, e Rizia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Todos estes foram filhos de Aser, cabeças de famílias paternas, escolhidos guerreiros valentes, chefes de príncipes; e foram contados em suas genealogias no exército para a guerra, em número de vinte e seis mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamim gerou a Belá seu primogênito, Asbel o segundo, Aará o terceiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noá o quarto, e Rafa o quinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'E os filhos de Belá foram: Adar, Gera, Abiúde,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naamã, Aoá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sefufá, e Hurão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'E estes foram os filhos de Eúde, os quais foram os cabeças das famílias dos moradores em Geba, que foram levados cativos a Manaate:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naamã, Aías, e Gera; este os levou cativos, e gerou a Uzá e a Aiúde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'E Saaraim gerou filhos na terra de Moabe, depois que deixou a suas mulheres Husim e Baara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'De sua mulher Hodes ele gerou a Jobabe, Zíbia, Messa, Malcã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeús, Saquias, e Mirma. Estes foram seus filhos, cabeças de famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'E de Husim ele gerou a Abitube, e a Elpaal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'E os filhos de Elpaal foram: Héber, Misã, Semede (o qual edificou a Ono e a Lode com suas aldeias),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Assim como Berias, e Sema, que foram cabeças das famílias dos moradores de Aijalom, os quais afugentaram aos moradores de Gate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'E Aiô, Sasaque, Jeremote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadias, Arade, Eder;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Micael, Ispa, e Joá, foram filhos de Berias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'E Zebadias, Mesulão, Hizqui, Héber,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Ismerai, Izlias, e Jobabe, foram filhos de Elpaal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'E Jaquim, Zicri, Zabdi,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elioenai, Ziletai, Eliel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaías, Beraías, e Sinrate, foram filhos de Simei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'E Ispã, Héber, Eliel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdom, Zicri, Hanã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananias, Elão, Antotias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Ifdeias, e Penuel, foram filhos de Sasaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'E Sanserai, Searias, Atalias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaaresias, Elias, e Zicri, foram filhos de Jeroão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Estes foram cabeças de famílias, chefes segundo suas gerações; estes habitaram em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'E em Gibeão habitou o pai de Gibeão; e o nome de sua mulher era Maaca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'E seu filho primogênito foi Abdom; depois Zur, Quis, Baal, Nadabe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Aiô, Zequer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'E Miclote, que gerou a Simeia. Estes também habitaram perto de irmãos em Jerusalém, vizinhos a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'E Ner gerou a Quis; Quis gerou a Saul, e Saul gerou a Jônatas, Malquisua, Abinadabe, e a Esbaal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'O filho de Jônatas foi Meribe-Baal, e Meribe-Baal gerou a Mica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Os filhos de Mica foram: Pitom, Meleque, Tareia e Acaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'E Acaz gerou a Jeoada; e Jeoada gerou a Alemete, a Azmavete, e a Zinri; e Zinri gerou a Moza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'E Moza gerou a Bineá, cujo filho foi Rafa, cujo filho foi Eleasá, cujo filho foi Azel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Azel teve seis filhos, cujos nomes foram: Azricão, Bocru, Ismael, Searias, Obadias, e Hanã; todos estes foram filhos de Azel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'E os filhos de Eseque, seu irmão, foram: Ulão seu primogênito, Jeús o segundo, e Elifelete o terceiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'E os filhos de Ulão foram guerreiros valentes, hábeis flecheiros; e tiveram muitos filhos e netos, cento e cinquenta. Todos estes foram dos filhos de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'E todo Israel foi contado por genealogias, e eis que foram escritos no livro dos Reis de Israel e de Judá, que foram transportados para a Babilônia por causa de sua transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'E os primeiros habitantes que vieram a suas propriedades em suas cidades, foram os israelitas, os sacerdotes, os levitas, e os servos do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Porém em Jerusalém habitaram alguns dos filhos de Judá, dos filhos de Benjamim, dos filhos de Efraim e de Manassés;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utai, filho de Amiúde, filho de Onri, filho de Inri, filho de Bani, dos filhos de Perez filho de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'E dos silonitas: Asaías o primogênito, e seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'E dos filhos de Zerá, Jeuel e seus irmãos, seiscentos e noventa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'E dos filhos de Benjamim: Salu, filho de Mesulão, filho de Hodavias, filho de Hassenua;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'E Ibneias, filho de Jeroão; e Elá filho de Uzi, filho de Micri; e Mesulão filho de Sefatias, filho de Reuel, filho de Ibneias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'E seus irmãos, segundo suas genealogias, foram novecentos e cinquenta e seis; todos estes homens foram cabeças das famílias de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'E dos sacerdotes: Jedaías, Jeoiaribe, Jaquim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'E Azarias filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, príncipe da casa de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'E Adaías filho de Jeroão, filho de Pasur, filho de Malquias; e Masai filho de Adiel, filho de Jazera, filho de Mesulão, filho de Mesilemite, filho de Imer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Como também seus irmãos, cabeças das famílias de seus pais, mil setecentos e sessenta, homens valentes e hábeis para a obra do serviço da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'E dos Levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, dos filhos de Merari;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'E Baquebacar, Heres, Galal, e Matanias filho de Mica, filho de Zicri, filho de Asafe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'E Obadias filho de Semaías, filho de Galal, filho de Jedutum; e Berequias filho de Asa, filho de Elcana, que habitou nas aldeias de Netofate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'E os porteiros foram: Salum, Acube, Talmom, Aimã, e seus irmãos cujo líder era Salum,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, '(O qual até agora fica junto à porta do rei ao oriente). Estes foram os porteiros do acampamento dos filhos de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'E Salum, filho de Coré, filho de Ebiasafe, filho de Corá, e seus irmãos da família de seu pai, os coraítas, foram encarregados da obra do serviço, guardando os umbrais do tabernáculo; assim como seus pais foram capitães do acampamento do SENHOR, que guardavam a entrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'E Fineias, filho de Eleazar, havia sido antes comandante sobre eles, e o SENHOR era com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'E Zacarias, filho de Meselemias, era porteiro da porta da tenda do ajuntamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Todos estes, escolhidos para porteiros dos umbrais, foram duzentos e doze; e estes foram registrados em suas genealogias, segundo suas aldeias; e Davi e o vidente Samuel os constituíram em seu ofício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Assim eles e seus filhos estiveram junto às portas da casa do SENHOR, a casa do Tabernáculo, como guardas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Os porteiros estavam aos quatro ventos: ao oriente, ao ocidente, ao norte, e ao sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'E seus irmãos que estavam em suas aldeias vinham de tempos em tempos para durante sete dias servirem com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Pois havia naquele ofício chefes dos porteiros, que eram levitas; e eles eram encarregados das câmaras e dos tesouros da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'E passavam a noite ao redor da casa de Deus, porque eram responsáveis pela guarda, e por abri-la a cada manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Alguns destes eram encarregados dos utensílios do serviço, pois os colocavam contados, e contados os tiravam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'E outros deles eram encarregados da mobília, e de todos os utensílios do santuário, como também da farinha, do vinho, do azeite, do incenso, e das especiarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'E alguns dos filhos dos sacerdotes faziam o perfume das especiarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'E Matitias, um dos Levitas, primogênito de Salum o coraíta, era encarregados das coisas que se faziam em assadeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'E alguns de seus irmãos, dos filhos dos coatitas, eram encarregados dos pães da proposição, para os prepararem para todos os sábados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'E destes também havia os cantores, cabeças das famílias dos levitas, os quais estavam isentos de outros serviços em suas câmaras, porque de dia e de noite estavam encarregados naquela obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Estes foram os cabeças das famílias dos levitas, cabeças em suas genealogias, os quais habitaram em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'E em Gibeão habitaram: Jeiel, pai de Gibeão (e o nome de sua mulher era Maaca);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'E seu filho primogênito Abdom, depois Zur, Quis, Baal, Ner, Nadabe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Aiô, Zacarias, e Miclote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'E Miclote gerou a Simeia. E também estes habitaram em Jerusalém junto de seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'E Ner gerou a Quis, Quis gerou a Saul, e Saul gerou a Jônatas, a Malquisua, a Abinadabe, e a Esbaal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'E filho de Jônatas foi Meribe-Baal; e Meribe-Baal gerou a Mica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'E os filhos de Mica foram: Pitom, Meleque, Tareia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'E Acaz, que gerou a Jará, Jará gerou a Alemete, a Azmavete, e a Zinri; e Zinri gerou a Moza;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'E Moza gerou a Bineá, cujo filho foi Refaías, cujo filho foi Eleasá, cujo filho foi Azel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'E Azel teve seis filhos, cujos nomes foram: Azricão, Bocru, Ismael, Searias, Obadias, e Hanã; estes foram os filhos de Azel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Os filisteus guerrearam contra Israel; e os homens de Israel fugiram diante deles, e caíram feridos no monte de Gilboa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'E os filisteus perseguiram a Saul e a seus filhos; e os filisteus mataram Jônatas, Abinadabe, e Malquisua, filhos de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'E a batalha se dificultou sobre Saul; os flecheiros o alcançaram, e ele foi ferido pelos flecheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Então Saul disse a seu escudeiro: Tira a tua espada, e atravessa-me com ela, para que não aconteça que estes incircuncisos venham, e escarneçam de mim.Porém seu escudeiro não quis, porque tinha muito medo. Então Saul tomou a espada, e se lançou sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'E quando seu escudeiro viu que Saul estava morto, ele também se lançou sobre sua espada, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Assim Saul e seus três filhos morreram; e toda a sua casa morreu juntamente com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'E quando todos os homens de Israel que estavam no vale viram que o exército havia fugido, e que Saul e seus filhos estavam mortos, deixaram suas cidades, e fugiram; então os filisteus vieram, e habitaram nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'E no dia seguinte, quando os Filisteus vieram para despojar os mortos, acharam Saul e seus filhos estendidos no monte de Gilboa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Então o despiram, tomaram sua cabeça e suas armas, e as enviaram por toda a terra dos filisteus para anunciarem a seus ídolos e ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'E puseram suas armas no templo de seu deus, e colocaram sua cabeça no templo de Dagom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'E quando todos os de Jabes-Gileade ouviram tudo quanto filisteus haviam feito a Saul,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Todos os homens valentes se levantaram, tomaram o corpo de Saul e os corpos de seus filhos, e os trouxeram a Jabes; e sepultaram seus ossos debaixo de um carvalho em Jabes, e jejuaram durante sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Assim Saul morreu por sua transgressão com que havia transgredido contra o SENHOR, por causa da palavra do SENHOR, a qual ele não obedeceu; e por ter buscado à médium para lhe consultar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'E não ter buscado ao SENHOR. Por isso ele o matou, e passou o reino a Davi, filho de Jessé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Então todo o Israel se ajuntou a Davi em Hebrom, dizendo: Eis que nós somos teu osso e tua carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'E mesmo antes, quando Saul ainda era rei, tu conduzias as tropas de Israel. Também o SENHOR teu Deus te disse: Tu apascentarás o meu povo Israel, e tu serás líder do meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Também vieram todos os anciãos de Israel ao rei em Hebrom, e Davi fez aliança com eles diante do SENHOR; e ungiram a Davi como rei sobre Israel, conforme a palavra do SENHOR por meio de Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Então Davi e todo Israel foram a Jerusalém, a qual era Jebus, pois ali os jebuseus eram os moradores daquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'E os moradores de Jebus disseram a Davi: Tu não entrarás aqui.Porém Davi conquistou a fortaleza de Sião, que é a cidade de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, '(Pois Davi havia dito: O primeiro a derrotar aos jebuseus será chefe e comandante.Então Joabe, filho de Zeruia, subiu primeiro, e foi feito comandante.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'E Davi habitou na fortaleza; por isso que foi chamada de cidade de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'E ele edificou a cidade ao redor, desde as fundações do aterro ao redor; e Joabe reparou o resto da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'E Davi ia cada vez mais crescendo em poder, pois o SENHOR dos exércitos era com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Estes foram os líderes dos guerreiros que Davi teve, os que lhe deram forte apoio em seu reinado, com todo Israel, para o fazerem rei sobre Israel, conforme a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'E este é o número dos guerreiros que Davi teve: Jasobeão, filho de Hacmoni, chefe de capitães, o qual, fazendo uso de sua lança, matou trezentos de um vez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'E depois dele Eleazar, filho de Dodô, o aoíta; ele era um dos três principais guerreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Este esteve com Davi em Pas-Damim, quando os filisteus se ajuntaram para a batalha; e havia ali uma plantação cheia de cevada. Enquanto o povo fugia dos filisteus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Eles se puseram no meio da plantação, defenderam-na, e derrotaram os Filisteus; e o SENHOR lhes deu uma grande vitória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'E três dos trinta comandantes desceram a Davi, na rocha junto à caverna de Adulão, enquanto o acampamento dos filisteus estava no vale de Refaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'E Davi estava então na fortaleza, enquanto havia uma tropa de filisteus em Belém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Davi teve um desejo, e disse: Quem me dera beber da água do poço de Belém, que está junto à porta!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'E aqueles três irromperam pelo acampamento dos filisteus, e tiraram água do poço de Belém, que está junto à porta, tomaram dela, e a trouxeram a Davi. Davi, porém não a quis beber; em vez disso, derramou-a ao SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'E disse: Deus me proíba de fazer isto! Beberia eu o sangue destes homens com suas vidas? Pois eles arriscaram suas vidas para a trazerem.Por isso ele não a quis beber. Isto fizeram aqueles três guerreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'E também Abisai, irmão de Joabe, foi o cabeça de três, o qual usando sua lança sobre trezentos, ele os matou; e foi famoso entre os três.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Dos três ele foi mais ilustre que os outros dois, por isso foi seu cabeça; porém não alcançou os três primeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Também Benaia, filho de Joiada, filho de homem valente, de grandes feitos, de Cabzeel; ele matou dois dos poderosos guerreiros de Moabe; ele também desceu, e matou um leão dentro de uma cova no tempo da neve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Ele também matou um homem egípcio alto, de cinco côvados; o egípcio trazia na mão uma lança como um lançador de tecelão; porém Benaia desceu a ele com um bastão; e arrancou a lança da mão do egípcio, e o matou com sua própria lança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Estas coisas fez Benaia, filho de Joiada, e por isso foi famoso entre aqueles três guerreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Eis que ele foi o mais ilustre dos trinta, mas não alcançou os três primeiros. E Davi o pôs sobre sua guarda pessoal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'E os guerreiros dos exército foram: Asael, irmão de Joabe; Elanã filho de Dodô de Belém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Samote o harodita; Helez o pelonita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, filho de Iques, o tecoíta; Abiezer o anatotita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibecai o husatita; Ilai o aoíta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maarai o netofatita; Helede, filho de Baaná, o netofatita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itai, filho de Ribai, de Gibeá dos filhos de Benjamim; Benaia o piratonita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai do ribeiro de Gaás; Abiel, o arbatita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmavete, o baarumita; Eliaba, o saalbonita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Os filhos de Hasém, o gizonita; Jônatas, filho de Sage, o hararita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Aião filho de Sacar, o hararita; Elifal filho de Ur;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Héfer, o mequeratita; Aías, o pelonita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro, o carmelita; Naarai, filho de Ezbai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, irmão de Natã; Mibar, filho de Hagri;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zeleque, o amonita; Naarai, o berotita, escudeiro de Joabe filho de Zeruia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira, o itrita; Garebe, o itrita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urias, o heteu; Zabade, filho de Alai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, filho de Siza, o rubenita, o qual era chefe dos rubenitas, e com ele trinta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanã, filho de Maaca; Josafá o mitenita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzia, o asteratia; Sama e Jeiel, filhos de Hotão, o aroerita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jedaiel, filho de Sinri, e seu irmão Joá, o tizita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel, o maavita; Jeribai e Josavias, filhos de Elnaão; Itma, o moabita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel; Obede; e Jaasiel, o mezobaíta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Estes, pois, foram os que vieram a Davi a Ziclague, enquanto ele ainda estava escondido por causa de Saul filho de Quis; e eles estiveram entre os guerreiros que o ajudaram na guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Eles estavam armados de arcos, e podiam tanto com a mão direita como a esquerda atirar pedras com funda, e setas com arco. Estes eram dentre os irmãos de Saul, os benjamitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Aiezer, o cabeça; e Joás, filhos de Semaá o gibeatita; e Jeziel, e Pelete, filhos de Azmavete; e Beraca, e Jeú o anatotita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'E Ismaías, o gibeonita, valente entre os trinta, e capitão dos trinta; e Jeremias, Jaaziel, Joanã, Jozabade o gederatita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzai, Jeremote, Bealias, Semarias, e Sefatias o harufita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elcana, Issias, Azareel, Joezer, e Jasobeão, os coraítas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'E Joela e Zebadias, filhos de Jeroão de Gedor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'E alguns dos gaditas passaram a Davi, à fortaleza no deserto, guerreiros valentes, homens de guerra para lutar, armados com escudo e lança; seus rostos eram como rostos de leões, e velozes como as corças sobre os montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ézer o cabeça, Obadias o segundo, Eliabe o terceiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismana o quarto, Jeremias o quinto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Atai o sexto, Eliel o sétimo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Joanã o oitavo, Elzabade o nono,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremias o décimo, Macbanai o décimo primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Estes foram os capitães do exército dos filhos de Gade. O menor tinha autoridade sobre cem homens, e o maior sobre mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Estes foram os que passaram o Jordão no mês primeiro, quando ele estava transbordando sobre todas as suas margens; e fizeram fugir a todos os dos vales ao oriente e ao ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Também alguns dos filhos de Benjamim e de Judá vieram a Davi à fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'E Davi saiu ao encontro deles, e lhes falou, dizendo: Se viestes a mim para paz e para me ajudar, meu coração será unido convosco; mas se é para me entregar a meus inimigos, mesmo sendo meus mãos sem crime, o Deus de nossos pais o veja, e o repreenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Então o Espírito revestiu a Amasai, chefe de trinta, e disse: Teus somos, ó Davi! E contigo estamos, ó filho de Jessé! Paz, paz seja contigo, e paz com os teus ajudadores; pois o teu Deus te ajuda.E Davi os recebeu, e os constituiu entre os capitães das tropas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Também alguns de Manassés passaram a Davi, quando ele veio com os filisteus à batalha contra Saul, ainda que não os ajudaram; porque os líderes dos filisteus, depois de terem feito conselho, o despediram, dizendo: Com nossas cabeças ele passará a seu senhor Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Quando, pois, ele veio a Ziclague, passaram-se a ele dos de Manassés: Adna, Jozabade, Jediaiel, Micael, Jozabade, Eliú, e Ziletai, chefes de milhares dos de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'E estes ajudaram a Davi contra aquela tropa; porque todos eles eram guerreiros valentes, e foram capitães no exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Pois naquele tempo todos os dias, eles vinham a Davi para o ajudar, até que se fez um grande exército, como um exército de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'E este são os números dos chefes armados para a batalha, que vieram a Davi em Hebrom, para passar a ele o reino de Saul, conforme a palavra do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Dos filhos de Judá que traziam escudo e lança, seis mil e oitocentos, armados para a batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Dos filhos de Simeão, guerreiros valentes para batalhar, sete mil e cem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Dos filhos de Levi, quatro mil e seiscentos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Joiada, porém, era o comandante dos descendentes de Arão, e com ele três mil e setecentos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'E Zadoque, era um jovem guerreiro valente, e da família de seu pai vinte e dois líderes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Dos filhos de Benjamim, irmãos de Saul, três mil; porque até então ainda havia muitos deles que ainda trabalhavam pela casa de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Dos filhos de Efraim, vinte mil e oitocentos, guerreiros valentes, homens ilustres nas casas de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Da meia tribo de Manassés, dezoito mil, que foram convocados por nome para virem a tornar Davi rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Dos filhos de Issacar, conhecedores dos tempos, para saberem o que Israel devia fazer, duzentos de seus líderes; e todos os seus irmãos seguiam suas ordens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'E de Zebulom, cinquenta mil, que saíam como exército preparados para a batalha, com todas as armas de guerra; capazes de batalhar com firmeza de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'E de Naftali mil capitães, e com eles trinta e sete mil com escudo e lança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'E dos danitas, preparados para a batalha, vinte e oito mil e seiscentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'E de Aser, dos que saíam como exército, prontos para a batalha, quarenta mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'E dalém do Jordão, dos rubenitas, dos gaditas, e da meia tribo de Manassés, como toda variedade de armas de guerra para batalhar, cento e vinte mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Todos estes homens de guerra, postos em posição de batalha, com coração íntegro, vieram a Hebrom, para constituir Davi rei sobre todo Israel; e também todos os demais de Israel tinham a mesma intenção de constituir Davi o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'E estiveram ali com Davi três dias, comendo e bebendo, porque seus irmãos haviam lhes feito preparativos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'E também os seus vizinhos, até de Issacar, Zebulom, e Naftali, trouxeram pão sobre asnos, camelos, mulos, e bois; e alimento de farinha, bolos de figos e passas, vinho e azeite, bois e ovelhas em abundância, porque havia alegria em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Então Davi teve conselho com os capitães de milhares e de centenas, e com todos os chefes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'E Davi disse a todo a congregação de Israel: Se bem vos parece, e se vem do SENHOR nosso Deus, enviemos depressa mensageiros aos nossos irmãos que restaram em todas as terras de Israel, aos sacerdotes e aos levitas que estão com eles em suas cidades e em seus arredores, para que se ajuntem conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'E tragamos de volta a nós a arca de nosso Deus, porque não a buscamos desde o tempo de Saul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Então toda a congregação disse que assim se fizesse, porque isso pareceu correto aos olhos de todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Assim Davi ajuntou a todo Israel, desde Sior do Egito, até chegar a Hamate, para que trouxessem a arca de Deus de Quriate-Jearim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Então Davi subiu com todo Israel a Baalá, que é Quriate-Jearim, em Judá, para dali trazerem acima a arca de Deus, o SENHOR, que habita entre os querubins, a qual é chamada pelo seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'E levaram a arca de Deus da casa de Abinadabe sobre uma carruagem nova, e Uzá e seu irmão guiavam o carro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'E Davi e todo Israel celebravam diante de Deus com toda força; e com canções, harpas, saltérios, tamboris, címbalos e com trombetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'E quando chegaram à eira de Quidom, Uzá estendeu sua mão para segurar a arca, pois os bois tropeçaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Então a ira do SENHOR se acendeu contra Uzá, e o feriu, por ele ter estendido sua mão à arca; e morreu ali diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'E Davi teve desgosto, porque o SENHOR havia atingido Uzá; por isso ele chamou aquele lugar Perez-Uzá, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'E Davi temeu a Deus naquele dia, dizendo: Como trarei a mim a arca de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Por isso Davi não trouxe a arca a si, à cidade de Davi; em vez disso ele a trouxe à casa de Obede-Edom, o geteu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Assim a arca de Deus ficou na casa de Obede-Edom, em sua casa, por três meses; e o SENHOR abençoou a casa de Obede-Edom, e tudo quanto ele tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Então Hirão, rei de Tiro, enviou mensageiros a Davi, e também madeira de cedro, pedreiros e carpinteiros, para lhe edificarem uma casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'E Davi entendeu que o SENHOR o tinha confirmado por rei sobre Israel, pois seu reino tinha sido exaltado, por causa de seu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'E Davi teve mais esposas em Jerusalém, e Davi ainda gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'E estes são os nomes dos filhos que teve em Jerusalém: Samua, Sobabe, Natã, Salomão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Ibar, Elisua, Elpelete,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogá, Nefegue, Jafia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeliada e Elifelete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Quando, pois, os filisteus ouviram que Davi havia sido ungido rei sobre todo Israel, todos os filisteus subiram em busca de Davi. E quando Davi ouviu falar disso, logo saiu contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'E os filisteus vieram e ocuparam o vale de Refaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Então Davi consultou a Deus, dizendo: Subirei contra os filisteus? E tu os entregarás em minhas mãos?E o SENHOR lhe disse: Sobe, porque eu os entregarei em teus mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Davi subiu, pois, Baal-Perazim, e ali os derrotou. Então Davi disse: Por minha mão Deus rompeu meus inimigos, como se rompem as águas.Por isso chamaram o nome daquele lugar Baal-Perazim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'E ali deixaram seus deuses, e Davi mandou que fossem queimados a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Porém os filisteus voltaram a ocupar o vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Então Davi voltou a consultar a Deus, e Deus lhe disse: Não subas por trás deles; em vez disso rodeia-os, e vem contra eles em frente das amoreiras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'E será que ouvires, quando tu ouvires o ruído do marchar das tropas pelas copas das amoreiras, então sai à batalha; porque Deus sairá adiante de ti para derrotar o acampamento dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'E Davi fez como Deus lhe mandara, e feriram o acampamento dos filisteus desde Gibeão até Gezer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'E a fama de Davi se espalhou por todas aquelas terras; e o SENHOR fez todas aquelas nações temerem a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Davi também fez casas para si em sua cidade, e preparou um lugar para a arca de Deus, e lhe armou uma tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Então Davi disse: Ninguém pode trazer a arca de Deus, a não ser os levitas; porque o SENHOR os escolheu para que transportassem a arca do SENHOR, e para lhe servirem eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'E Davi ajuntou a todo Israel em Jerusalém, para fazerem subir a arca do SENHOR a seu lugar, que ele tinha lhe preparado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Davi também ajuntou aos filhos de Arão e aos levitas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Dos filhos de Coate, Uriel o principal, e seus irmãos, cento e vinte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Dos filhos de Merari, Asaías o principal, e seus irmãos, duzentos e vinte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Dos filhos de Gérson, Joel o principal, e seus irmãos, cento e trinta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Dos filhos de Elisafã, Semaías o principal, e seus irmãos, duzentos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Dos filhos de Hebrom, Eliel o principal, e seus irmãos, oitenta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Dos filhos de Uziel, Amidadabe o principal, e seus irmãos, cento e doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'E Davi chamou aos sacerdotes Zadoque e Abiatar, e a os levitas Uriel, Asaías, Joel, Semaías, Eliel, e Aminadabe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'E disse-lhes: Vós que sois os chefes das famílias entre os levitas, santificai-vos, vós e vossos irmãos, e fazei subir a arca do SENHOR, Deus de Israel, ao lugar que eu lhe preparei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Pois por não terdes feito assim vós da primeira vez, o SENHOR nosso Deus fez nos atingiu, porque não o buscamos conforme o mandamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Assim os sacerdotes e os levitas se santificaram para trazerem a arca do SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'E os filhos dos levitas trouxeram a arca de Deus com as barras sobre seus ombros, assim como Moisés tinha mandado conforme a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'E Davi disse aos chefes dos levitas que constituíssem de seus irmãos cantores com instrumentos musicais, com saltérios, e harpas, e címbalos; para que fizessem sons e levantassem a voz com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Então os levitas constituíram a Hemã, filho de Joel; e de seus irmãos, a Asafe filho de Berequias; e dos filhos de Merari e de seus irmãos, a Etã filho de Cusaías;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'E com eles a seus irmãos da segundo ordem, a Zacarias, Bene e Jaaziel, Semiramote, Jeiel, Uni, Eliabe, Benaia, Maaseias, Matitias, Elifeleu, Micneias, Obede-Edom, e Jeiel, os porteiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'E os cantores: Hemã, Asafe, e Etã, fizeram sons com címbalos de metal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'E Zacarias, Aziel, Semiramote, Jeiel, Uni, Eliabe, Maaseias, e Benaia, com saltérios sobre Alamote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'E Matitias, Elifeleu, Micneias, Obede-Edom, Jeiel, e Azazias, tocavam ao modo de Seminite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'E Quenanias, chefe dos levitas, estava encarregado de conduzir o cântico; ele ensinava o cântico porque era entendido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'E Berequias e Elcana eram porteiros da arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'E os sacerdotes Sebanias, Josafá, Natanael, Amasai, Zacarias, Benaia, e Eliézer, tocavam as trombetas diante da arca de Deus; e Obede-Edom e Jeías eram porteiros da arca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Sucedeu, pois, que Davi, os anciãos de Israel, e os capitães de milhares, foram fazer subir a arca do pacto do SENHOR, de casa de Obede-Edom, com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'E foi que, por Deus estar ajudando os levitas que levavam a arca do pacto do SENHOR, eles sacrificaram sete novilhos e sete carneiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'E Davi ia vestido de um roupão de linho fino, como também todos os levitas que levavam a arca, e os cantores; e Quenanias era o chefe da música e dos cantores. Davi também levava sobre si um éfode de linho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Assim todo Israel fez subir a arca do pacto do SENHOR, com júbilo, som de cornetas e trombetas, e címbalos, e ao som de saltérios e harpas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'E foi que, quando a arca do pacto do SENHOR chegou à cidade de Davi, Mical, filha de Saul, olhou por uma janela, e viu o rei Davi dançando e saltando; e ela o desprezou em seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Trouxeram, pois, a arca de Deus, e a puseram no meio da tenda que Davi tinha lhe armado; e apresentaram ofertas de queima e sacrifícios de gratidão diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'E Davi, quando terminou de apresentar as ofertas de queima e os sacrifícios de gratidão, abençoou ao povo em nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'E repartiu a todos em Israel, tanto homens como mulheres, a cada um um bolo de pão, uma boa porção de carne, e um bolo de passas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'E pôs diante do arca do SENHOR a alguns dos levitas como servidores, para que celebrassem, agradecessem, e louvassem ao SENHOR Deus de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asafe era o cabeça, e Zacarias era o segundo depois; Jeiel, Semiramote, Jeiel, Matitias, Eliabe, Benaia, Obede-Edom, e Jeiel, estavam com seus instrumentos de saltérios e harpas, mas Asafe fazia som com címbalos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Porém os sacerdotes Benaia e Jaaziel estavam continuamente com trombetas diante do arca do pacto de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Então naquele mesmo dia Davi pela primeira vez mandou celebrarem ao SENHOR por meio de Asafe e de seus irmãos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Louvai ao SENHOR, invocai o seu nome, notificai entre os povos os seus feitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Cantai a ele, cantai-lhe salmos; falai de todas as suas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Gloriai-vos em seu santo nome; alegre-se o coração dos que buscam ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Procurai ao SENHOR e à sua força; buscai a sua face continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Lembrai-vos de suas maravilhas que ele fez, de seus prodígios, e dos juízos de sua boca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Vós, descendentes de seu servo Israel, vós filhos de Jacó, seus escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Ele é o SENHOR, o nosso Deus; seus juízos estão em toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Lembrai-vos perpetuamente de seu pacto, e da palavra que ele mandou até mil gerações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Do pacto que estabeleceu com Abraão, e do seu juramento a Isaque;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'O qual confirmou a Jacó por estatuto, a Israel por pacto eterno,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Dizendo: A ti darei a terra de Canaã, a porção de vossa herança;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Quando vós éreis poucos em número, poucos, e estrangeiros nela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Que andavam de nação em nação, de um reino a outro povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'A ninguém ele permitiu que os oprimisse; por causa deles repreendeu a reis,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Dizendo: Não toqueis em meus ungidos, nem façais mal a meus profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Cantai ao SENHOR, toda a terra, anunciai de dia em dia sua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Cantai entre as nações sua glória, e entre todos os povos suas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Porque o SENHOR é grande, e muito digno de ser louvado; ele é mais temível que todos os deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Pois todos os deuses dos povos nada são; porém o SENHOR fez os céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Majestade e esplendor há diante de ele; força e alegria em sua morada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Reconhecei ao SENHOR, ó famílias das nações, reconhecei ao SENHOR a glória e o poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Dai ao SENHOR a glória de seu nome; trazei ofertas, e vinde diante dele; adorai ao SENHOR na glória de sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Assombrai-vos diante dele, vós, toda a terra; o mundo por ele foi estabelecido, para que não se movesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Alegrem-se os céus, e goze-se a terra, e digam nas nações: Reina o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Ressoe o mar, e a plenitude dela: Alegre-se o campo, e todo o que contém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Então cantarão as árvores dos bosques diante do SENHOR, Porque vem a julgar a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Celebrai a o SENHOR, porque é bom; Porque sua misericórdia é eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'E dizei: Salva-nos, ó Deus, saúde nossa: Junta-nos, e livra-nos das nações, Para que confessemos tua santo nome, e nos gloriemos em teus louvores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Bendito seja o SENHOR Deus de Israel, De eternidade a eternidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'E deixou ali, diante do arca do pacto do SENHOR, a Asafe e a seus irmãos, para que ministrassem de contínuo diante da arca, cada coisa em seu dia:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'E a Obede-Edom e a seus irmãos, sessenta e oito; e a Obede-Edom filho de Jedutum, e a Hosa, por porteiros:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Assim a Zadoque o sacerdote, e a seus irmãos os sacerdotes, diante do tabernáculo do SENHOR no alto que estava em Gibeão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Para que sacrificassem continuamente, a manhã e tarde, holocaustos a o SENHOR no altar do holocausto, conforme a todo o que está escrito na lei do SENHOR, que ele prescreveu a Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'E com eles a Hemã e a Jedutum, e os outros escolhidos declarados por seus nomes, para glorificar a o SENHOR, porque é eterna sua misericórdia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Com eles a Hemã e a Jedutum com trombetas e címbalos para tanger, e com outros instrumentos de música de Deus; e a os filhos de Jedutum, por porteiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'E todo o povo se foi cada um a sua casa; e Davi se voltou para abençoar sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'E aconteceu que morando Davi em sua casa, disse Davi ao profeta Natã: Eis aqui eu habito em casa de cedro, e a arca do pacto do SENHOR debaixo de cortinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'E Natã disse a Davi: Faze tudo o que está em tua coração, porque Deus é contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Naquela mesma noite foi palavra de Deus a Natã, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Vai e dize a Davi meu servo: Assim disse o SENHOR: Tu não me edificarás casa em que habite:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Porque não habitei em casa alguma desde o dia que tirei a os filhos de Israel até hoje; antes estive de tenda em tenda, e de tabernáculo em tabernáculo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Em todo quanto andei com todo Israel falei uma palavra a algum dos juízes de Israel, a os quais mandei que apascentassem meu povo, para dizer-lhes: Por que não me edificais uma casa de cedro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Portanto, agora dirás a meu servo Davi: Assim disse o SENHOR dos exércitos: Eu te tomei da malhada, de detrás do gado, para que fosses príncipe sobre meu povo Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'E fui contigo em tudo quanto andaste, e arranquei a todos teus inimigos de diante de ti, e te fiz grande nome, como o nome dos grandes que são na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Assim dispus lugar a meu povo Israel, e o plantei para que habite por si, e que não seja mais comovido: nem os filhos de iniquidade o consumirão mais, como antes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'E desde o tempo que pus os juízes sobre meu povo Israel; mas humilharei a todos teus inimigos. Faço-te ademais saber que o SENHOR te há de edificar casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'E será que, quando teus dias forem cumpridos para ir-te com teus pais, levantarei a tua descendência depois de ti, a qual será de teus filhos, e afirmarei seu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Ele me edificará casa, e eu confirmarei seu trono eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Eu lhe serei por pai, e ele me será por filho: e não tirarei dele minha misericórdia, como a tirei daquele que foi antes de ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Mas eu o confirmarei em minha casa e em meu reino eternamente; e seu trono será firme para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Conforme a todas estas palavras, e conforme a toda esta visão, assim falou Natã a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'E entrou o rei Davi, e esteve diante do SENHOR, e disse: ó SENHOR Deus, quem sou eu, e qual é minha casa, que me trouxeste até este lugar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'E ainda isto, ó Deus, te pareceu pouco, pois que falaste da casa de teu servo para mais longe, e me olhaste como a um homem excelente, ó o SENHOR Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Que mais pode dizer Davi pedindo de ti para glorificar a tua servo? Porém tu conheces a teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Ó SENHOR, por amor de teu servo e segundo teu coração, fizeste toda esta grandeza, para fazer notórias todas as tuas grandezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Ó SENHOR, não há semelhante a ti, nem há Deus a não ser tu, segundo todas as coisas que ouvimos com nossos ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'E que gente há na terra como teu povo Israel, cujo Deus fosse e se redimisse um povo, para fazer-te nome com grandezas e maravilhas, expulsando as nações de diante de teu povo, que tu resgataste do Egito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Tu constituíste a teu povo Israel por povo teu para sempre; e tu, o SENHOR, vieste a ser seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Agora, pois, SENHOR, a palavra que falaste acerca de teu servo e de sua casa, seja firme para sempre, e faze como disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Permaneça, pois, e seja engrandecido teu nome para sempre, a fim de que se diga: o SENHOR dos exércitos, Deus de Israel, é Deus para Israel. E seja a casa de teu servo Davi firme diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Porque tu, Deus meu, revelaste ao ouvido a teu servo que lhe edificarás casa; por isso achou teu servo motivo de orar diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Agora, pois, o SENHOR, tu és o Deus que falaste de teu servo este bem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'E agora quiseste abençoar a casa de teu servo, para que permaneça perpetuamente diante de ti: porque tu, o SENHOR, a abençoaste, e será bendita para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Depois destas coisas aconteceu que Davi feriu aos filisteus, e os humilhou; e tomou Gate e suas vilas das mãos dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Também feriu a Moabe; e os moabitas foram servos de Davi, trazendo-lhe presentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Assim feriu Davi a Hadadezer, rei de Zobá, em Hamate, quando ele foi assegurar seu domínio até o rio Eufrates.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'E tomou-lhes Davi mil carros, e sete mil a cavalo, e vinte mil homens a pé; e Davi aleijou os cavalos de todos os carros, exceto os de cem carros que deixou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'E vindo os sírios de Damasco em ajuda de Hadadezer, rei de Zobá, Davi feriu dos sírios vinte e dois mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'E pôs Davi guarnição na Síria de Damasco, e os sírios foram feitos servos de Davi, trazendo-lhe presentes; porque o SENHOR salvava a Davi por onde quer que fosse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Tomou também Davi os escudos de ouro que levavam os servos de Hadadezer, e trouxe-os a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Assim de Tibate e de Cum, cidades de Hadadezer, Davi tomou muito bronze, de que Salomão fez o mar de bronze, as colunas, e vasos de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'E ouvindo Toú, rei de Hamate, que Davi havia defeito todo o exército de Hadadezer, rei de Zobá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Enviou seu filho Hdorão ao rei Davi para saudar-lhe e para bendizer-lhe por haver guerreado com Hadadezer, e haver lhe vencido; porque Toú tinha guerra com Hadadezer. Enviou-lhe também toda sorte de artigos de ouro, de prata e de metal;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'os quais o rei Davi dedicou a o SENHOR, com a prata e ouro que havia tomado de todas as nações, de Edom, de Moabe, dos filhos de Amom, dos filisteus, e de Amaleque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Além disso Abisai, filho de Zeruia, feriu no vale do sal dezoito mil edomitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'E pôs guarnições em Edom, e todos os edomitas foram servos de Davi; porque o SENHOR guardava a Davi por onde quer que fosse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'E reinou Davi sobre todo Israel, e fazia juízo e justiça a todo seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'E Joabe, filho de Zeruia, era general do exército; e Josafá filho de Ailude, cronista;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'E Zadoque, filho de Aitube, e Abimeleque filho de Abiatar, eram sacerdotes; e Sausa, secretário;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'E Benaia, filho de Joiada, era sobre os quereteus e peleteus; e os filhos de Davi eram os principais próximos do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Depois destas coisas, aconteceu que morreu Naás, rei dos filhos de Amom, e seu filho reinou em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'E disse Davi: Farei misericórdia com Hanã filho de Naás, porque também seu pai fez comigo misericórdia. Assim Davi enviou embaixadores que o consolassem da morte de seu pai. Mas vindos os servos de Davi na terra dos filhos de Amom a Hanã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'os príncipes dos filhos de Amom disseram a Hanã: Pensas que Davi está honrando o teu pai, de maneira que te enviou consoladores? Acaso não é que os servos dele vêm a ti para espionar, e investigar, e reconhecer a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Então Hanã tomou os servos de Davi, rapou-os, e cortou-lhes as vestes ao meio, até as nádegas, e despachou-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Foram-se, pois, e quando foi dada a Davi a notícia acerca daqueles homens, ele mandou que fossem ao encontro deles, porque estavam muito afrontados. E o rei mandou-lhes dizer: Ficai em Jericó até que vos cresça a barba, e então voltareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'E quando os filhos de Amom viram que se haviam feito Davi ter ódio deles, Hanã e os filhos de Amom enviaram mil talentos de prata, para alugarem carruragens e cavaleiros da Mesopotâmia, da Síria de Maaca, e de Zobá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'E alugaram trinta e dois mil carruagens, e ao rei de Maaca com o seu povo, os quais vieram e assentaram seu acampamento diante de Medeba. E juntaram-se também os filhos de Amom de suas cidades, e vieram à guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Ouvindo-o Davi, enviou a Joabe com todo o exército dos homens valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'E os filhos de Amom saíram, e ordenaram sua tropa à entrada da cidade; e os reis que haviam vindo, estavam à parte no acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'E vendo Joabe que a linha da batalha estava contra ele pela frente e por trás, escolheu de todos os mais capacitados que havia em Israel, e pôs seu esquadrão em formação contra os sírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Depois pôs os outros nas mãos de seu irmão Abisai, que os pôes em formação de batalha contra os amonitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'E disse: Se os sírios forem mais fortes que eu, tu me socorrerás; e se os amonitas forem mais fortes que tu, eu te socorrerei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Esforça-te, e sejamos corajosos por nosso povo, e pelas cidades de nosso Deus; e faça o SENHOR o que bem lhe parecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Aproximou-se, então, Joabe e o povo que tinha consigo, para lutar contra os sírios; mas eles fugiram diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'E os filhos de Amom, vendo que os sírios haviam fugido, fugiram também eles diante de Abisai seu irmão, e entraram-se na cidade. Então Joabe se voltou a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'E vendo os sírios que haviam caído diante de Israel, enviaram embaixadores, e trouxeram aos sírios que estavam da outra parte do rio, cujo capitão era Sofaque, general do exército de Hadadezer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Logo que foi dado aviso a Davi, juntou a todo Israel, e passando o Jordão veio a eles, e ordenou contra eles seu exército. E como Davi havia ordenado sua tropa contra eles, os sírios lutaram com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Mas os sírios fugiram diante de Israel; e Davi matou dos sírios sete mil homens das carruagens, e quarenta mil homens a pé; assim matou Sofaque, general do exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'E vendo os sírios de Hadadezer que haviam caído diante de Israel, concordarem em fazer a paz com Davi, e foram seus servos; e nunca mais os sírios quiseram ajudar os filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'E aconteceu à volta do ano, no tempo que costumam os reis sair à guerra, que Joabe tirou as forças do exército, e destruiu a terra dos filhos de Amom, e veio e cercou a Rabá. Mas Davi estava em Jerusalém; e Joabe atacou Rabá, e a destruiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'E tomou Davi a coroa de seu rei de encima de sua cabeça, e achou-a de peso de um talento de ouro, e havia nela pedras preciosas; e foi posta sobre a cabeça de Davi. E ademais de isto tirou da cidade um muito grande despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Tirou também ao povo que estava nela, e cortou-os com serras, e com trilhos de ferro, e machados. O mesmo fez Davi a todas as cidades dos filhos de Amom. E voltou-se Davi com todo o povo a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Depois de isto aconteceu que se levantou guerra em Gezer com os filisteus; e feriu Sibecai Husatita a Sipai, da linhagem dos gigantes; e foram humilhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'E voltou-se a levantar guerra com os filisteus; e feriu Elanã filho de Jair a Lami, irmão de Golias geteu, a haste de cuja lança era como um lançador de tecedores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'E voltou a haver guerra em Gate, de onde havia um homem de grande estatura, o qual tinha seis dedos em pés e mãos, em todos vinte e quatro: e também era filho de Rafa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Insultou ele a Israel, mas feriu-o Jônatas, filho de Simeia irmão de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Estes foram filhos de Rafa em Gate, os quais caíram por mão de Davi e de seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Mas Satanás se levantou contra Israel, e incitou a Davi a que contasse a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'E disse Davi a Joabe e a os príncipes do povo: Ide, contai a Israel desde Berseba até Dã, e trazei-me o número deles para que eu o saiba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'E disse Joabe: Acrescente o SENHOR a seu povo cem vezes outros tantos. Rei senhor meu, não são todos estes servos de meu senhor? Para que procura meu senhor isto, que será pernicioso a Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mas o mandamento do rei pode mais que Joabe. Saiu por tanto Joabe, e foi por todo Israel; e voltou a Jerusalém, e deu a conta do número do povo a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'E achou-se em todo Israel que tiravam espada, onze vezes cem mil; e de Judá quatrocentos e setenta mil homens que tiravam espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Entre estes não foram contados os levitas, nem os filhos de Benjamim, porque Joabe abominava o mandamento do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Assim desagradou este negócio a os olhos de Deus, e feriu a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'E disse Davi a Deus: Pequei gravemente em fazer isto: rogo-te que faças passar a iniquidade de teu servo, porque eu ei feito muito loucamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'E falou o SENHOR a Gade, vidente de Davi, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Vai, e fala a Davi, e dize-lhe: Assim disse o SENHOR: Três coisas te proponho; escolhe de elas uma que eu faça contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'E vindo Gade a Davi, disse-lhe: Assim disse o SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Escolhe-te, ou três anos de fome; ou ser por três meses defeito diante de teus inimigos, e que a espada de teus adversários te alcance; ou por três dias a espada do SENHOR e pestilência na terra, e que o anjo do SENHOR destrua em todo o termo de Israel. Olha, pois, o que responderá ao que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Então Davi disse a Gade: Estou em grande angústia: rogo que eu caia na mão do SENHOR; porque suas misericórdias são muitas em extremo, e que não caia eu em mãos de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Assim o SENHOR deu pestilência em Israel, e caíram de Israel setenta mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'E enviou o SENHOR o anjo a Jerusalém para destruí-la: mas estando ele destruindo, olhou o SENHOR, e arrependeu-se daquele mal,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'E levantando Davi seus olhos, viu ao anjo do SENHOR, que estava entre o céu e a terra, tendo uma espada nua em sua mão, estendida contra Jerusalém. Então Davi e os anciãos se prostraram sobre seus rostos, cobertos de sacos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'E disse Davi a Deus: Não sou eu o que fez contar o povo? Eu mesmo sou o que pequei, e certamente fiz mal; mas estas ovelhas, que fizeram? Ó SENHOR, Deus meu, seja agora tua mão contra mim, e contra a casa de meu pai, e não haja praga em teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'E o anjo do SENHOR ordenou a Gade que dissesse a Davi, que subisse e construísse um altar a o SENHOR na era de Ornã jebuseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Então Davi subiu, conforme a palavra de Gade que lhe havia dito em nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'E voltando-se Ornã viu o anjo; pelo que se esconderam quatro filhos seus que com ele estavam. E Ornã trilhava o trigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'E vindo Davi a Ornã, olhou este, e viu a Davi: e saindo da eira, prostrou-se em terra a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Então disse Davi a Ornã: Dá-me este lugar da eira, em que edifique um altar a o SENHOR, e dá-o a mim por seu devido preço, para que cesse a praga do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'E Ornã respondeu a Davi: Toma-o para ti, e faça meu senhor o rei o que bem lhe parecer: e ainda os bois darei para o holocausto, e os trilhos para lenha, e trigo para o presente: eu o dou tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Então o rei Davi disse a Ornã: Não, mas sim que efetivamente a comprarei por seu justo preço: porque não tomarei para o SENHOR o que é teu, nem sacrificarei holocausto que nada me custe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'E deu Davi a Ornã pelo lugar seiscentos siclos de ouro por peso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'E edificou ali Davi um altar a o SENHOR, em o que ofereceu holocaustos e sacrifícios pacíficos, e invocou a o SENHOR, o qual lhe respondeu por fogo dos céus em o altar do holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'E como o SENHOR falou ao anjo, ele voltou sua espada à bainha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Então vendo Davi que o SENHOR lhe havia ouvido na eira de Ornã jebuseu, sacrificou ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'E o tabernáculo do SENHOR que Moisés havia feito no deserto, e o altar do holocausto, estavam então no alto de Gibeão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Mas Davi não pode ir ali a consultar a Deus, porque estava espantado por causa da espada do anjo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'E disse Davi: Esta é a casa do SENHOR Deus, e este é o altar do holocausto para Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Depois mandou Davi que se juntassem os estrangeiros que estavam na terra de Israel, e assinalou deles pedreiros que lavrassem pedras para edificar a casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Assim preparou Davi muito ferro para os pregos das portas, e para as junturas; e muito metal sem peso, e madeira de cedro sem conta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Porque os sidônios e tírios haviam trazido a Davi madeira de cedro inumerável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'E disse Davi: Salomão meu filho é jovem e tenro, e a casa que se há de edificar a o SENHOR há de ser magnífica por excelência, para nome e honra em todas as terras; agora pois eu lhe prepararei o necessário. E preparou Davi antes de sua morte em grande abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Chamou então Davi a Salomão seu filho, e mandou-lhe que edificasse casa a o SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'E disse Davi a Salomão: Filho meu, em meu coração tive o edificar templo ao nome do SENHOR meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mas veio a mim palavra do SENHOR, dizendo: Tu derramaste muito sangue, e trouxeste grandes guerras: não edificarás casa a meu nome, porque derramaste muito sangue na terra diante de mim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Eis aqui, um filho te nascerá, o qual será homem de repouso, porque eu lhe darei quietude de todos seus inimigos em derredor; por tanto seu nome será Salomão; e eu darei paz e repouso sobre Israel em seus dias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Ele edificará casa a meu nome, e ele me será a mim por filho, e eu lhe serei por pai; e afirmarei o trono de seu reino sobre Israel para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Agora, pois, filho meu, seja contigo o SENHOR, e sejas próspero, e edifiques casa a o SENHOR teu Deus, como ele disse de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'E o SENHOR te dê entendimento e prudência, e ele te dê mandamentos para Israel; e que tu guardes a lei do SENHOR teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Então serás próspero, se cuidares de pôr por obra os estatutos e direitos que o SENHOR mandou a Moisés para Israel. Esforça-te pois, e recobra ânimo; não temas, nem desmaies.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Eis aqui, eu em minha estreiteza preveni para a casa do SENHOR cem mil talentos de ouro, e um milhar de milhares de talentos de prata: não tem peso o metal nem o ferro, porque é muito. Assim aprontei madeira e pedra, a o qual tu acrescentarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Tu tens contigo muitos oficiais, pedreiros, pedreiros, e carpinteiros, e todo homem especialista em toda obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Do ouro, da prata, do metal, e do ferro, não há número. Levanta-te, pois, e à obra; que o SENHOR será contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Assim mandou Davi a todos os principais de Israel que dessem ajuda a Salomão seu filho, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Não é convosco o SENHOR vosso Deus, o qual vos há dado quietude de todas as partes? Porque ele entregou em minha mão os moradores da terra, e a terra há sido sujeitada diante do SENHOR, e diante de seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Ponde, pois, agora vossos corações e vossos ânimos em buscar a o SENHOR vosso Deus; e levantai-vos, e edificai o santuário do Deus o SENHOR, para trazer a arca do pacto do SENHOR, e o santos vasos de Deus, à casa edificada ao nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Sendo, pois, Davi já velho e farto de dias, fez a Salomão seu filho rei sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'E juntando a todos os principais de Israel, e a os sacerdotes e levitas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Foram contados os levitas de trinta anos acima; e foi o número deles por suas cabeças, contados um a um, trinta e oito mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Destes, vinte e quatro mil para dar pressa à obra da casa do SENHOR; e governadores e juízes, seis mil;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Ademais quatro mil porteiros; e quatro mil para louvar a o SENHOR, disse Davi, com os instrumentos que fiz para render louvores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'E repartiu-os Davi em ordens conforme a os filhos de Levi, Gérson e Coate e Merari.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Os filhos de Gérson: Ladã, e Simei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Os filhos de Ladã, três: Jeiel o primeiro, depois Zetã e Joel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Os filhos de Simei, três: Selomote, Haziel, e Harã. Estes foram os príncipes das famílias de Ladã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'E os filhos de Simei: Jaate, Zina, Jeus, e Berias. Estes quatro foram os filhos de Simei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jaate era o primeiro, Zina o segundo; mas Jeus e Berias não multiplicaram em filhos, por o qual foram contados por uma família.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Os filhos de Coate: Anrão, Izar, Hebrom, e Uziel, eles quatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Os filhos de Anrão: Arão e Moisés. E Arão foi apartado para ser dedicado às mais santas coisas, ele e seus filhos para sempre, para que queimassem perfumes diante do SENHOR, e lhe ministrassem, e bendisessem em seu nome, para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'E os filhos de Moisés, homem de Deus, foram contados na tribo de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Os filhos de Moisés foram Gérson e Eliézer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Filho de Gérson foi Sebuel o primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'E filho de Eliézer foi Reabias o primeiro. E Eliézer não teve outros filhos; mas os filhos de Reabias foram muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Filho de Izar foi Selomite o primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Os filhos de Hebrom: Jería o primeiro, Amarias o segundo, Jaaziel o terceiro, e Jecameão o quarto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Os filhos de Uziel: Mica o primeiro, e Issias o segundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Os filhos de Merari: Mali e Musi. Os filhos de Mali: Eleazar e Quis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'E morreu Eleazar sem filhos, mas teve filhas; e os filhos de Quis, seus irmãos, as tomaram por mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Os filhos de Musi: Mali, Éder e Jeremote, eles três.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Estes são os filhos de Levi nas famílias de seus pais, cabeceiras de famílias em suas linhagens, contados por seus nomes, por suas cabeças, os quais faziam obra no ministério da casa do SENHOR, de vinte anos acima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Porque Davi disse: o SENHOR Deus de Israel há dado repouso a seu povo Israel, e o habitar em Jerusalém para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'E também os levitas não levarão mais o tabernáculo, e todos seus vasos para seu ministério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Assim que, conforme as últimas palavras de Davi, foi a contagem dos filhos de Levi de vinte anos acima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'E estavam sob a mão dos filhos de Arão, para ministrar na casa do SENHOR, nos átrios e nas câmaras, e na purificação de toda coisa santificada, e na demais obra do ministério da casa de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Assim para os pães da proposição, e para a flor da farinha para o sacrifício, e para os pães sem levedura, e para as coisas postas em panelas, e para o tostado, e para toda medida e conta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'E para que assistissem cada manhã todos os dias a confessar e louvar a o SENHOR, e assim à tarde;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'E para oferecer todos os holocaustos a o SENHOR os sábados, novas luas, e solenidades, por a conta e forma que tinham, continuamente diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'E para que tivessem a guarda do tabernáculo do testemunho, e a guarda do santuário, e as ordens dos filhos de Arão seus irmãos, no ministério da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Também os filhos de Arão tiveram suas repartições. Os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Mas Nadabe, e Abiú morreram antes que seu pai, e não tiveram filhos: Eleazar e Itamar tiveram o sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'E Davi os repartiu, sendo Zadoque dos filhos de Eleazar, e Aimeleque dos filhos de Itamar, por seus turnos em seu ministério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'E os filhos de Eleazar foram achados, quanto a seus principais varões, muitos mais que os filhos de Itamar; e repartiram-nos assim: Dos filhos de Eleazar havia dezesseis cabeças de famílias paternas; e dos filhos de Itamar pelas famílias de seus pais, oito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Repartiram-nos, pois, por sorte os uns com os outros: porque dos filhos de Eleazar e dos filhos de Itamar havia príncipes do santuário, e príncipes da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'E Semaías escriba, filho de Natanael, dos levitas, escreveu-os diante do rei e dos príncipes, e diante de Zadoque o sacerdote, e de Aimeleque filho de Abiatar, e dos príncipes das famílias dos sacerdotes e levitas; e inscreviam uma família a Eleazar, e a Itamar outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'E a primeira sorte saiu por Jeoiaribe, a segunda por Jedaías;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'A terceira por Harim, a quarta por Seorim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'A quinta por Malquias, a sexta por Miamim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'A sétiam por Coz, a oitava por Abias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'A nona por Jesua, a décima por Secanias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'A décima primeira por Eliasibe, a décima segunda por Jaquim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'A décima terceira por Hupá, a décima quarta por Jesebeabe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'A décima quinta por Bilga, a décima sexta por Imer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'A décima sétima por Hezir, a décima outiva por Hapises;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'A décima nona por Petaías, a vigésima por Jeezquel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'A vigésima primeira por Jaquim, a vigésima segunda por Gamul;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'A vigésima terceira por Delaías, a vigésima quarta por Maazias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Estes foram contados em seu ministério, para que entrassem na casa do SENHOR, conforme a sua ordenança, sob o mando de Arão seu pai, da maneira que lhe havia mandado o SENHOR o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'E dos filhos de Levi que restaram: Subael, dos filhos de Anrão; e dos filhos de Subael, Jedias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'E dos filhos de Reabias, Issias o principal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Dos izaritas, Selomote; e filho de Selomote, Jaate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'E dos filhos de Hebrom; Jerias o primeiro, o segundo Amarias, o terceiro Jaaziel, o quarto Jecameão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Filho de Uziel, Mica; e filho de Mica, Samir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Irmão de Mica, Issias; e filho de Issias, Zacarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Os filhos de Merari: Mali e Musi; filho de Jaazias, Beno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Os filhos de Merari por Jaazias: Beno, e Soão, Zacur e Ibri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'E de Mali, Eleazar, o qual não teve filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Filho de Quis, Jerameel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Os filhos de Musi: Mali, Éder e Jeremote. Estes foram os filhos dos levitas conforme às casas de suas famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Estes também lançaram sortes, como seus irmãos os filhos de Arão, diante do rei Davi, e de Zadoque e de Aimeleque, e dos príncipes das famílias dos sacerdotes e levitas: o principal dos pais igualmente que o menor de seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Assim Davi e os príncipes do exército apartaram para o ministério a os filhos de Asafe, e de Hemã, e de Jedutum, os quais profetizassem com harpas, saltérios, e címbalos: e o número deles foi, de homens idôneos para a obra de seu ministério');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Dos filhos de Asafe: Zacur, José, Netanias, e Asarela, filhos de Asafe, sob a direção de Asafe, o qual profetizava à ordem do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'De Jedutum: os filhos de Jedutum, Gedalias, Zeri, Jesaías, Hasabias, e Matitias, e Simei: seis, sob a mão de seu pai Jedutum, o qual profetizava com harpa, para celebrar e louvar a o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'De Hemã: os filhos de Hemã, Buquias, Matanias, Uziel, Sebuel, Jeremote, Hananias, Hanani, Eliata, Gidalti, Romanti-Ezer, Josbecasa, Maloti, Hotir, e Maaziote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Todos estes foram filhos de Hemã, vidente do rei em palavras de Deus, para exaltar o poder seu: e deu Deus a Hemã catorze filhos e três filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'E todos estes estavam sob a direção de seu pai na música, na casa do SENHOR, com címbalos, saltérios e harpas, para o ministério do templo de Deus, por disposição do rei acerca de Asafe, de Jedutum, e de Hemã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'E o número deles com seus irmãos instruídos em música do SENHOR, todos os aptos, foi duzentos oitenta e oito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'E lançaram sortes para os turnos do serviço, entrando o pequeno com o grande, o mesmo o mestre que o discípulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'E a primeira sorte saiu por Asafe, a José: a segunda a Gedalias, quem com seus irmãos e filhos foram doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'A terceira a Zacur, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'A quarta a Izri, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'A quinta a Netanias, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'A sexta a Buquias, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'A sétima a Jesarela, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'A oitava a Jesaías, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'A nona a Matanias, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'A décima a Simei, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'A décima primeira a Azareel, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'A décima segunda a Hasabias, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'A décima terceira a Subael, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'A décima quarta a Matitias, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'A décima quinta a Jeremote, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'A décima sexta a Hananias, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'A décima sétima a Josbecasa, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'A décima oitava a Hanani, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'A décima nona a Maloti, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'A vigésima a Eliata, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'A vigésima primeira a Hotir, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'A vigésima segunda a Gidalti, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'A vigésima terceira a Maaziote, com seus filhos e seus irmãos, doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'A vigésima quarta a Romanti-Ezer, com seus filhos e seus irmãos, doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Quanto às repartições dos porteiros: Dos coraítas: Meselemias filho de Coré, dos filhos de Asafe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Os filhos de Meselemias: Zacarias o primogênito, Jediael o segundo, Zebadias o terceiro, Jatniel o quarto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elão o quinto, Joanã o sexto, Elioenai o sétimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Os filhos de Obede-Edom: Semaías o primogênito, Jozabade o segundo, Joabe o terceiro, o quarto Sacar, o quinto Natanael;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'O sexto Amiel, o sétimo Issacar, o oitavo Peuletai: porque Deus havia abençoado a Obede-Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Também de Semaías seu filho nasceram filhos que foram senhores sobre a casa de seus pais; porque eram varões muito valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Os filhos de Semaías: Otni, Rafael, Obede, Elzabade, e seus irmãos, homens esforçados; assim Eliú, e Semaquias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Todos estes dos filhos de Obede-Edom: eles com seus filhos e seus irmãos, homens robustos e fortes para o ministério; sessenta e dois, de Obede-Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'E os filhos de Meselemias e seus irmãos, dezoito homens valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'De Hosa, dos filhos de Merari: Sinri o principal, (ainda que não fosse o primogênito, mas seu pai o pôs para que fosse cabeça);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'O segundo Hilquias, o terceiro Tebalias, o quarto Zacarias: todos os filhos de Hosa e seus irmãos foram treze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Entre estes se fez a distribuição dos porteiros, alternando os principais dos varões na guarda com seus irmãos, para servir na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'E lançaram sortes, o pequeno com o grande, pelas casas de seus pais, para cada porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'E caiu a sorte ao oriente a Selemias. E a Zacarias seu filho, conselheiro entendido, lançaram as sortes, e sua sorte foi para o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'E por Obede-Edom, ao sul; e por seus filhos, a casa dos depósitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Por Supim e Hosa ao ocidente, com a porta de Salequete ao caminho da subida, guarda contra guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Ao oriente seis levitas, ao norte quatro de dia; ao sul quatro de dia; e à casa dos depósitos, de dois em dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Em a câmara dos vasos ao ocidente, quatro ao caminho, e dois na câmara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Estes são as repartições dos porteiros, filhos dos coraítas, e dos filhos de Merari.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'E dos levitas, Aías tinha cargo dos tesouros da casa de Deus, e dos tesouros das coisas santificadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Quanto a os filhos de Ladã, filhos de Gérson: de Ladã, os príncipes das famílias de Ladã foram Gérson, e Jeieli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Os filhos de Jeieli, Zetã e Joel seu irmão, tiveram cargo dos tesouros da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Acerca dos anramitas, dos izaritas, dos hebronitas, e dos uzielitas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Sebuel filho de Gérson, filho de Moisés, era principal sobre os tesouros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Em ordem a seu irmão Eliézer, filho deste era Reabias, filho deste Jesaías, filho deste Jorão, filho deste Zicri, do que foi filho Selomote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Este Selomote e seus irmãos tinham cargo de todos os tesouros de todas as coisas santificadas, que havia consagrado o rei Davi, e os príncipes das famílias, e os capitães de milhares e de centenas, e os chefes do exército;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'De o que haviam consagrado das guerras e dos despojos, para reparar a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Assim todas as coisas que havia consagrado Samuel vidente, e Saul filho de Quis, e Abner filho de Ner, e Joabe filho de Zeruia: e todo o que qualquer um consagrava, estava sob a mão de Selomote e de seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Dos izaritas, Quenanias e seus filhos eram governadores e juízes sobre Israel nas obras de fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Dos hebronitas, Hasabias e seus irmãos, homens de vigor, mil e setecentos, governavam a Israel da outra parte do Jordão, ao ocidente, em toda a obra do SENHOR, e no serviço do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Dos hebronitas, Jerias era o principal entre os hebronitas repartidos em suas linhagens por suas famílias. No ano quarenta do reinado de Davi se registraram, e acharam-se entre eles fortes e vigorosos em Jazer de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'E seus irmãos, homens valentes, eram dois mil e setecentos, cabeças de famílias, os quais o rei Davi constituiu sobre os rubenitas, gaditas, e sobre a meia tribo de Manassés, para todas as coisas de Deus, e os negócios do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'E os filhos de Israel segundo seu número, a saber, príncipes de famílias, comandantes, centuriões e oficiais dos que serviam ao rei em todos os negócios das divisões que entravam e saíam cada mês em todos os meses do ano, eram em cada divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Sobre a primeira divisão do primeiro mês estava Jasobeão filho de Zabdiel; e havia em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Dos filhos de Perez foi ele chefe de todos os capitães das companhias do primeiro mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Sobre a divisão do segundo mês estava Dodai aoíta: e Miclote era maior general em sua divisão, na que também havia vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'O chefe da terceira divisão para o terceiro mês era Benaia, filho de Joiada sumo sacerdote; e em sua divisão havia vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Este Benaia era valente entre os trinta e sobre os trinta; e em sua divisão estava Amizabade seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'O quarto chefe para o quarto mês era Asael irmão de Joabe, e depois dele Zebadias seu filho; e em sua divisão havia vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'O quinto chefe para o quinto mês era Samute izraíta: e em sua divisão havia vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'O sexto para o sexto mês era Ira filho de Iques, de Tecoa; e em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'O sétimo para o sétimo mês era Helez pelonita, dos filhos de Efraim; e em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'O oitavo para o oitavo mês era Sibecai husatita, de Zerá; e em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'O nono para o nono mês era Abiezer anatotita, dos benjamitas; e em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'O décimo para o décimo mês era Maarai netofatita, de Zerá; e em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'O décimo primeiro para o décimo primeiro mês era Benaia piratonita, dos filhos de Efraim; e em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'O décimo segundo para o décimo segundo mês era Heldai netofatita, de Otniel; e em sua divisão vinte e quatro mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Assim sobre as tribos de Israel: o chefe dos rubenitas era Eliézer filho de Zicri; dos simeonitas, Sefatias, filho de Maaca:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Dos levitas, Hasabias filho de Quemuel; dos aronitas, Zadoque;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'De Judá, Eliú, um dos irmãos de Davi; dos de Issacar, Onri filho de Micael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Dos de Zebulom, Ismaías filho de Obadias; dos de Naftali, Jeremote filho de Azriel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Dos filhos de Efraim, Oseias filho de Azazias; da meia tribo de Manassés, Joel filho de Pedaías;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'De a outra meia tribo de Manassés em Gileade, Ido filho de Zacarias; dos de Benjamim, Jaasiel filho de Abner;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'E de Dã, Azarel filho de Jeroão. Estes foram os chefes das tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'E não tomou Davi o número dos que eram de vinte anos abaixo, porquanto o SENHOR havia dito que ele havia de multiplicar a Israel como as estrelas do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joabe filho de Zeruia havia começado a contar, mas não acabou, pois por isto veio a ira sobre Israel: e assim o número não foi posto no registro das crônicas do rei Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'E Azmavete filho de Adiel tinha cargo dos tesouros do rei; e dos tesouros dos campos, e das cidades, e das aldeias e castelos, Jônatas filho de Uzia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'E dos que trabalhavam na lavoura das terras, Ezri filho de Quelube;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'E das vinhas Simei ramatita; e do fruto das vinhas para as adegas, Zabdias sifmita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'E dos olivais e figueirais que havia nas campinas, Baal-Hanã gederita; e dos armazéns do azeite, Joás;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Das vacas que pastavam em Sarom, Sitrai saronita; e das vacas que estavam nos vales, Safate filho de Adlai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'E dos camelos, Obil ismaelita; e das asnas, Jedias meronotita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'E das ovelhas, Jaziz hagareno. Todos estes eram superintendentes da riqueza do rei Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'E Jônatas, tio de Davi, era conselheiro, homem prudente e escriba; e Jeiel filho de Hacmoni estava com os filhos do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'E também Aitofel era conselheiro do rei; e Husai arquita amigo do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Depois de Aitofel era Joiada filho de Benaia, e Abiatar. E Joabe era o general do exército do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'E juntou Davi em Jerusalém a todos os principais de Israel, os príncipes das tribos, e os chefes das divisões que serviam ao rei, os comandantes e centuriões, com os superintendentes de toda a riqueza e possessão do rei, e seus filhos, com os eunucos, os poderosos, e todos os seus homens valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'E levantando-se o rei Davi, posto em pé disse: Ouvi-me, irmãos meus, e povo meu. Eu tinha em propósito edificar uma casa, para que nela repousasse a arca do pacto do SENHOR, e para o estrado dos pés de nosso Deus; e havia já aprontei tudo para edificar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mas Deus me disse: Tu não edificarás casa a meu nome: porque és homem de guerra, e derramaste muito sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Porém o SENHOR o Deus de Israel me elegeu de toda a casa de meu pai, para que perpetuamente fosse rei sobre Israel: porque a Judá escolheu por chefe, e da casa de Judá a família de meu pai; e de entre os filhos de meu pai agradou-se de mim para me constituir rei sobre todo Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'E de todos meus filhos (porque o SENHOR me deu muitos filhos,) elegeu a meu filho Salomão para que se sente no trono do reino do SENHOR sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'E me disse: Salomão teu filho, ele edificará minha casa e meus átrios: porque a este me escolhi por filho, e eu lhe serei a ele por pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Assim eu confirmarei seu reino para sempre, se ele se esforçar a executar meus mandamentos e meus juízos, como este dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Agora, pois, diante dos olhos de todo Israel, congregação do SENHOR, e em ouvidos de nosso Deus, guardai e inquiri todos os preceitos do SENHOR vosso Deus, para que possuais a boa terra, e a deixeis por herdade a vossos filhos depois de vós perpetuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'E tu, Salomão, meu filho, conhece o Deus de teu pai, e serve-o com coração completo e ânimo voluntário; porque o SENHOR examina os corações de todos, e entende todas as intenções dos pensamentos. Se tu o buscares, o acharás; mas se o deixares, ele te rejeitará para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Olha, pois, agora que o SENHOR te escolheu para que edifiques casa para santuário: esforça-te, e faze-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'E Davi deu a Salomão seu filho a planta do pórtico, e de suas casas, e de suas oficinas, e de suas salas, e de suas recâmaras, e da casa do propiciatório.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Assim a planta de todas as coisas que tinha em sua vontade, para os átrios da casa do SENHOR, e para todas as câmaras em derredor, para os tesouros da casa de Deus, e para os tesouros das coisas santificadas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Também para as ordens dos sacerdotes e dos levitas, e para toda a obra do ministério da casa do SENHOR, e para todos os vasos do ministério da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'E deu ouro por peso para o de ouro, para todos os vasos de cada serviço: e prata por peso para todos os vasos, para todos os vasos de cada serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Ouro por peso para os candelabros de ouro, e para suas lâmpadas; por peso o ouro para cada candelabro e suas lâmpadas: e para os candelabros de prata, prata por peso para o candelabro e suas lâmpadas, conforme ao serviço de cada candelabro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Assim deu ouro por peso para as mesas da proposição, para cada mesa: do mesmo modo prata para as mesas de prata:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Também ouro puro para os garfos e para as bacias, e para os incensários, e para as taças de ouro, para cada taça por peso; e para as taças de prata, por peso para cada taça:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Ademais, ouro puro por peso para o altar do incenso, e para ele a maneira de carro dos querubins de ouro, que com as asas estendidas cobriam a arca do pacto do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Todas estas coisas, disse Davi, se me representaram pela mão do SENHOR que me fez entender todas as obras do desenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Disse mais Davi a Salomão seu filho: Anima-te e esforça-te, e efetua-o; não temas, nem desmaies, porque o Deus o SENHOR, meu Deus, será contigo: ele não te deixará, nem te desamparará, até que acabes toda a obra para o serviço da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Eis aqui as ordens dos sacerdotes e dos levitas, para todo o ministério da casa de Deus, serão contigo em toda a obra: assim todos os voluntários e inteligentes para qualquer espécie de artifício; e os príncipes, e todo o povo para executar todas as tuas ordens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Depois disse o rei Davi a toda a assembleia: A só Salomão meu filho elegeu Deus; ele é jovem e tenro, e a obra grande; porque a casa não é para homem, mas sim para o SENHOR Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Eu, porém, com todas as minhas forças preparei, para a casa de meu Deus, ouro para as coisas de ouro, e prata para as coisas de prata, e bronze para as de bronze, e ferro para as de ferro, e madeira para as de madeira, e pedras de ônix, e pedras decorativas, e pedras negras, e pedras de diversas cores, e toda sorte de pedras preciosas, e pedras de mármore em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'A mais disto, porquanto tenho meu gosto na casa de meu Deus, eu guardo em meu tesouro particular ouro e prata que, ademais de todas as coisas que aprontei para a casa do santuário, ei dado para a casa de meu Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'A saber, três mil talentos de ouro, de ouro de Ofir, e sete mil talentos de prata refinada para cobrir as paredes das casas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Ouro, pois, para as coisas de ouro, e prata para as coisas de prata, e para toda a obra de mãos dos oficiais. E quem quer fazer hoje oferta a o SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Então os príncipes das famílias, e os príncipes das tribos de Israel, comandantes e centuriões, com os superintendentes da riqueza do rei, ofereceram de sua vontade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'E deram para o serviço da casa de Deus cinco mil talentos de ouro e dez mil moedas, e dez mil talentos de prata, e dezoito mil talentos de bronze, e cinco mil talentos de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'E todo o que se achou com pedras preciosas, deu-as para o tesouro da casa do SENHOR, em mão de Jeiel gersonita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'E folgou-se o povo de haver contribuído de sua vontade; porque com inteiro coração ofereceram a o SENHOR voluntariamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Assim folgou-se muito o rei Davi, e abençoou a o SENHOR diante de toda a congregação; e disse Davi: Bendito sejas tu, ó o SENHOR, Deus de Israel nosso pai, de um século a outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tua é, ó o SENHOR, a magnificência, e o poder, e a glória, a vitória, e a honra; porque todas as coisas que estão nos céus e na terra são tuas. Teu, ó o SENHOR, é o reino, e a altura sobre todos os que estão por cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'As riquezas e a glória estão diante de ti, e tu senhoreias a todos: e em tua mão está a potência e a fortaleza, e em tua mão a grandeza e força de todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Agora, pois, Deus nosso, nós te confessamos, e louvamos teu glorioso nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Porque quem sou eu, e quem é meu povo, para que pudéssemos oferecer de nossa vontade coisas semelhantes? Porque tudo é teu, e o que recebemos de tua mão te damos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Porque nós, estrangeiros e peregrinos somos diante de ti, como todos nossos pais; e nossos dias qual sombra sobre a terra, e não dão espera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Ó SENHOR Deus nosso, toda esta abundância que preparamos para edificar casa a teu santo nome, de tua mão é, e tudo é teu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Eu sei, Deus meu, que tu esquadrinhas os corações, e que a retidão te agrada: por isso eu com retidão de meu coração voluntariamente te ei oferecido tudo isto, e agora vi com alegria que teu povo, que aqui se achou agora, deu para ti espontaneamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'SENHOR, Deus de Abraão, de Isaque, e de Israel, nossos pais, conserva perpetuamente esta vontade do coração de teu povo, e encaminha seu coração a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'E ao meu filho Salomão dá um coração íntegro, para que guarde os teus mandamentos, os teus testemunhos e os teus estatutos, e para que faça todas as coisas, e te edifique a casa para a qual eu preparei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Depois disse Davi a toda à congregação: Bendizei agora ao SENHOR vosso Deus. Então toda a congregação bendisse ao SENHOR Deus de seus pais, e inclinando-se, adoraram diante do SENHOR, e do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'E sacrificaram animais ao SENHOR, e ofereceram ao SENHOR ofertas de queima no dia seguinte, mil bezerros, mil carneiros, mil cordeiros com as suas libações, e muitos sacrifícios por todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'E comeram e beberam diante do SENHOR aquele dia com grande alegria; e deram a segunda vez a investidura do reino a Salomão filho de Davi, e ungiram-no ao SENHOR por príncipe, e a Zadoque por sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'E sentou-se Salomão por rei no trono do SENHOR em lugar de Davi seu pai, e foi próspero; e obedeceu-lhe todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'E todos os príncipes e poderosos, e todos os filhos do rei Davi, prestaram homenagem ao rei Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'E o SENHOR engrandeceu em extremo a Salomão a os olhos de todo Israel, e deu-lhe glória do reino, qual nenhum rei a teve antes dele em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Assim reinou Davi filho de Jessé sobre todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'E o tempo que reinou sobre Israel foi quarenta anos. Sete anos reinou em Hebrom, e trinta e três reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'E morreu em boa velhice, cheio de dias, de riquezas, e de glória: e reinou em seu lugar Salomão seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'E os feitos do rei Davi, primeiros e últimos, estão escritos no livro das crônicas de Samuel vidente, e nas crônicas do profeta Natã, e nas crônicas de Gade vidente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Com todo o relato de seu reinado, e seu poder, e os tempos que passaram sobre ele, e sobre Israel, e sobre todos os reinos daquelas aquelas terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'E Salomão filho de Davi foi estabelecido em seu reino; e o SENHOR seu Deus foi com ele, e lhe engrandeceu muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'E chamou Salomão a todo Israel, comandantes, líderes de centenas, e juízes, e a todos os príncipes de todo Israel, cabeças de famílias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'E foi Salomão, e com ele toda esta congregação, ao alto que havia em Gibeão; porque ali estava o tabernáculo do testemunho de Deus, que Moisés servo do SENHOR havia feito no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Mas Davi havia trazido a arca de Deus de Quriate-Jearim ao lugar que ele lhe havia preparado; porque ele lhe havia estendido uma tenda em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Assim o altar de bronze que havia feito Bezalel filho de Uri filho de Hur, estava ali diante do tabernáculo do SENHOR, ao qual Salomão foi a consultar com aquela congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Subiu, pois, Salomão ali diante do SENHOR, ao altar de bronze que estava no tabernáculo do testemunho, e ofereceu sobre ele mil holocaustos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'E aquela noite apareceu Deus a Salomão, e disse-lhe: Pede o que queres que eu te dê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'E Salomão disse a Deus: Tu fizeste com Davi meu pai grande misericórdia, e a mim me puseste por rei em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Confirme-se, pois, agora, ó SENHOR Deus, tua palavra dada a Davi meu pai; porque tu me puseste por rei sobre um povo em multidão como o pó da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Dá-me agora sabedoria e conhecimento, para sair e entrar diante deste povo: porque quem poderá julgar este teu povo tão grande?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'E disse Deus a Salomão: Porquanto isto foi em teu coração, que não pediste riquezas, riqueza, ou glória, nem a alma dos que te querem mal, nem pediste muitos dias, mas sim que pediste para ti sabedoria e conhecimento para julgar meu povo, sobre o qual te constituí por rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Sabedoria e conhecimento te são dados; e também te darei riquezas, bens, e glória, que nunca houve nos reis que foram antes de ti, nem depois de ti haverá tais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'E voltou Salomão a Jerusalém do alto que estava em Gibeão, de ante o tabernáculo do testemunho; e reinou sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'E juntou Salomão carros e cavaleiros; e teve mil e quatrocentos carros, e doze mil cavaleiros, os quais pôs nas cidades dos carros, e com o rei em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'E pôs o rei prata e ouro em Jerusalém como pedras, e cedro como sicômoros que nascem nos campos em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'E traziam cavalos do Egito e de Coa para Salomão; pois os mercadores do rei os compravam de Coa por um certo preço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'E subiam, e tiravam do Egito, um carro por seiscentas peças de prata, e um cavalo por cento e cinquenta: e assim se tiravam por meio deles para todos os reis dos Heteus, e para os reis da Síria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Determinou, pois, Salomão edificar casa ao nome do SENHOR, e outra casa para seu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'E contou Salomão setenta mil homens que levassem cargas, e oitenta mil homens que cortassem no monte, e três mil e seiscentos que os governassem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'E enviou a dizer Salomão a Hirão rei de Tiro: Faze comigo como fizeste com Davi meu pai, enviando-lhe cedros para que edificasse para si casa em que morasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Eis aqui eu tenho que edificar casa ao nome do SENHOR meu Deus, para consagrá-la, para queimar perfumes aromáticos diante dele, e para a colocação contínua dos pães da proposição, e para holocaustos a manhã e tarde, e os sábados, e luas novas, e festividades do SENHOR nosso Deus; o qual será perpétuo em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'E a casa que tenho que edificar, há de ser grande: porque o Deus nosso é grande sobre todos os deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Mas quem será tão poderoso que lhe edifique casa? Os céus e os céus dos céus não lhe podem compreender; quem, pois, sou eu, que lhe edifique casa, a não ser para queimar perfumes diante dele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Envia-me, pois, agora um homem hábil, que saiba trabalhar em ouro, e em prata, e em bronze, e em ferro, em púrpura, e em carmesim, e em azul, e que saiba esculpir com os mestres que estão comigo em Judá e em Jerusalém, os quais preparou meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Envia-me também madeira de cedro, de faia, de pinho, do Líbano: porque eu sei que teus servos entendem de cortar madeira no Líbano; e eis que meus servos irão com os teus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Para que me preparem muita madeira, porque a casa que tenho de edificar há de ser grande e imponente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'E eis que para os operários teus servos, cortadores da madeira, ei dado vinte mil coros de trigo em grão, e vinte mil coros de cevada, e vinte mil batos de vinho, e vinte mil batos de azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Então Hirão rei de Tiro respondeu por carta, a qual enviou a Salomão: Porque o SENHOR amou a seu povo, te pôs por rei sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'E ademais dizia Hirão: Bendito seja o SENHOR o Deus de Israel, que fez os céus e a terra, e que deu ao rei Davi filho sábio, entendido, de bom senso e prudente, que edifique casa ao SENHOR, e casa para seu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Eu, pois, te enviei um homem hábil e entendido, que foi de Hirão meu pai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Filho de uma mulher das filhas de Dã, mas seu pai foi de Tiro; o qual sabe trabalhar em ouro, e prata, e bronze, e ferro, em pedra e em madeira, em púrpura, e em azul, em linho e em carmesim; assim para esculpir todas as figuras, e tirar toda sorte de desenho que lhe for proposto, e estar com teus homens peritos, e com os do meu senhor Davi, teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Agora, pois, enviará meu senhor a seus servos o trigo e cevada, e azeite e vinho, que disse;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'E nós cortaremos no Líbano a madeira que houveres necessidade, e te a traremos em balsas pelo mar até Jope, e tu a farás levar até Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'E contou Salomão todos os homens estrangeiros que estavam na terra de Israel, depois de havê-los já contado Davi seu pai, e foram achados cento cinquenta e três mil seiscentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'E assinalou deles setenta mil para levar cargas, e oitenta mil que cortassem no monte, e três mil e seiscentos por capatazes para fazer trabalhar ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'E começou Salomão a edificar a casa em Jerusalém, no monte Moriá que havia sido mostrado a Davi seu pai, no lugar que Davi havia preparado na eira de Ornã jebuseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'E começou a edificar no mês segundo, a dois do mês, no quarto ano de seu reinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Estas são as medidas de que Salomão fundou o edifício da casa de Deus. A primeira medida foi do comprimento de sessenta côvados; e a largura de vinte côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'O pórtico que estava na dianteira do comprimento, era de vinte côvados à frente da largura da casa, e sua altura de cento e vinte: e cobriu-o por dentro de ouro puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'E forrou a casa maior com madeira de faia, a qual cobriu de bom ouro, e fez ressaltar sobre ela palmas e correntes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Cobriu também a casa de pedras preciosas por excelência: e o ouro era ouro de Parvaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Assim cobriu a casa, suas vigas, seus umbrais, suas paredes, e suas portas, com ouro; e esculpiu querubins pelas paredes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Fez assim a casa do lugar santíssimo, cujo comprimento era de vinte côvados segundo a largura da frente da casa, e sua largura de vinte côvados: e cobriu-a de bom ouro que pesava seiscentos talentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'E o peso dos pregos teve cinquenta siclos de ouro. Cobriu também de ouro as salas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'E dentro do lugar santíssimo fez dois querubins esculpidos, os quais cobriram de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'O comprimento das asas dos querubins era de vinte côvados: porque a uma asa era de cinco côvados: a qual chegava até a parede da casa; e a outra asa de cinco côvados, a qual chegava à asa do outro querubim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Da mesma maneira a uma asa do outro querubim era de cinco côvados: a qual chegava até a parede da casa; e a outra asa era de cinco côvados, que tocava a asa do outro querubim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Assim as asas destes querubins estavam estendidas por vinte côvados: e eles estavam em pé com os rostos até a casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Fez também o véu de azul, púrpura, carmesim e linho, e fez ressaltar em ele querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Diante da casa fez duas colunas de trinta e cinco côvados de comprimento, com seus capitéis encima, de cinco côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Fez também correntes, como no compartimento interno, e as pôs sobre os capitéis das colunas: e fez cem romãs, as quais pôs nas correntes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'E assentou as colunas diante do templo, a uma à mão direita, e a outra à esquerda; e à da mão direita chamou Jaquim, e à da esquerda, Boaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Fez ademais um altar de bronze de vinte côvados de comprimento, e vinte côvados de largura, e dez côvados de altura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Também fez um mar de fundição, o qual tinha dez côvados do uma borda à outra, inteiramente redondo: sua altura era de cinco côvados, e uma linha de trinta côvados o contornava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'E debaixo dele havia figuras de bois que o circundavam, dez em cada côvado todo ao redor: eram duas ordens de bois fundidos juntamente com o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'E estava assentado sobre doze bois, três dos quais estavam voltados ao norte, e três ao ocidente, e três ao sul, e três ao oriente: e o mar assentava sobre eles, e todas suas traseiras estavam à parte de dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'E tinha de espessura um palmo, e a borda era da feitura da borda de um cálice, ou flor de lírio. E fazia três mil batos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Fez também dez fontes, e pôs cinco à direita e cinco à esquerda, para lavar e limpar nelas a obra do holocausto; mas o mar era para os sacerdotes se lavarem nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Fez também dez candelabros de ouro segundo sua forma, os quais pôs no templo, cinco à direita, e cinco à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Também fez dez mesas e as pôs no templo, cinco à direita, e cinco à esquerda: igualmente fez cem bacias de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'A mais disto fez o átrio dos sacerdotes, e o grande átrio, e as entradas do átrio, e cobriu as portas de elas de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'E assentou o mar ao lado direito até o oriente, em frente do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Fez também Hirão caldeiras, e pás, e bacias; e acabou Hirão a obra que fazia ao rei Salomão para a casa de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Duas colunas, e os globos, os capitéis sobre as cabeças das duas colunas, e duas redes para cobrir as duas bolas dos capitéis que estavam encima das colunas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Quatrocentas romãs nas duas redes, duas ordens de romãs em cada rede, para que cobrissem as duas bolas dos capitéis que estavam encima das colunas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Fez também as bases, sobre as quais assentou as pias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'O mar, e doze bois debaixo dele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'E caldeiras, e pás, e garfos; e todos seus utensílios fez Hirão seu pai ao rei Salomão para a casa do SENHOR, de bronze puríssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'E fundiu-os o rei nas planícies do Jordão, em terra argilosa, entre Sucote e Zeredá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'E Salomão fez todos estes vasos em grande abundância, porque não pode ser achado o peso do bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Assim fez Salomão todos os vasos para a casa de Deus, e o altar de ouro, e as mesas sobre as quais se punham os pães da proposição;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Assim os candelabros e suas lâmpadas, de ouro puro, para que as acendessem diante do compartimento interno conforme à costume.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'E as flores, e as lâmpadas, e as tenazes se fizeram completamente de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Também os apagadores, e as bacias, e as colheres, e os incensários, de ouro puro. Quanto à entrada da casa, suas portas interiores para o lugar santíssimo, e as portas da casa do templo, de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'E acabada que foi toda a obra que fez Salomão para a casa do SENHOR, meteu Salomão nela as coisas que Davi seu pai havia dedicado; e pôs a prata, e o ouro, e todos os vasos, nos tesouros da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Então Salomão juntou em Jerusalém os anciãos de Israel, e todos os príncipes das tribos, os cabeças das famílias dos filhos de Israel, para que trouxessem a arca do pacto do SENHOR da cidade de Davi, que é Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'E juntaram-se ao rei todos os varões de Israel, à solenidade do mês sétimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'E vieram todos os anciãos de Israel, e tomaram os levitas a arca:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'E levaram a arca, e o tabernáculo do testemunho, e todos os vasos do santuário que estavam no tabernáculo: os sacerdotes e os levitas os levaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'E o rei Salomão, e toda a congregação de Israel que se havia a ele reunido diante da arca, sacrificaram ovelhas e bois, que pela abundância não se puderam contar nem numerar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'E os sacerdotes meteram a arca do pacto do SENHOR em seu lugar, no compartimento interno da casa, no lugar santíssimo, sob as asas dos querubins:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Pois os querubins estendiam as asas sobre o assento da arca, e cobriam os querubins por encima assim a arca como suas barras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'E fizeram sair fora as barras, de modo que se vissem as cabeças das barras da arca diante do compartimento interno, mas não se viam desde fora: e ali estiveram até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'No arca nada havia, a não serem as duas tábuas que Moisés havia posto em Horebe, com as quais o SENHOR havia feito aliança com os filhos de Israel, depois que saíram do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'E quando os sacerdotes saíram do santuário, (porque todos os sacerdotes que se acharam haviam sido santificados, e não guardavam suas vezes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'E os levitas cantores, todos os de Asafe, os de Hemã, e os de Jedutum, juntamente com seus filhos e seus irmãos, vestidos de linho fino, estavam com címbalos e saltérios e harpas ao oriente do altar; e com eles cento vinte sacerdotes que tocavam trombetas);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Soavam, pois, as trombetas, e cantavam com a voz todos a uma, para louvar e confessar ao SENHOR: e quando levantavam a voz com trombetas e címbalos e instrumentos de música, quando louvavam ao SENHOR, dizendo: Porque é bom, porque sua misericórdia é para sempre; então a casa, isto é,a casa do SENHOR, se encheu de uma nuvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'E os sacerdotes não podiam ficar em pé para ministrar, por causa da nuvem; porque a glória do SENHOR havia enchido a casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Então disse Salomão: o SENHOR disse que ele habitaria na escuridão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Eu, pois, edifiquei uma casa de morada para ti, e uma habitação em que mores para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'E voltando o rei seu rosto, abençoou a toda a congregação de Israel: e toda a congregação de Israel estava em pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'E ele disse: Bendito seja o SENHOR Deus de Israel, o qual com sua mão cumpriu o que falou por sua boca a Davi meu pai, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Desde o dia que tirei meu povo da terra do Egito, nenhuma cidade escolhi de todas as tribos de Israel para edificar casa de onde estivesse meu nome, nem escolhi homem que fosse príncipe sobre meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Mas a Jerusalém escolhi para que nela esteja meu nome, e a Davi escolhi para que fosse sobre meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'E Davi meu pai teve no coração edificar casa ao nome do SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Mas o SENHOR disse a Davi meu pai: Com respeito a haver tido em teu coração edificar casa a meu nome, bem fizeste em haver tido isto em teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Porém tu não edificarás a casa, mas sim teu filho que sairá de teus lombos, ele edificará casa a meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'E o SENHOR cumpriu sua palavra que havia dito, pois eu me levantei em lugar de Davi meu pai, e sentei-me no trono de Israel, como o SENHOR havia dito, e edifiquei casa ao nome do SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'E nela pus a arca, na qual está o pacto do SENHOR que estabeleceu com os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Pôs-se logo Salomão diante do altar do SENHOR, em presença de toda a congregação de Israel, e estendeu suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Porque Salomão havia feito uma plataforma de bronze, de cinco côvados de comprimento, e de cinco côvados de largura, e de altura de três côvados, e o havia posto em meio do átrio: e pôs-se sobre ela, e ficou de joelhos diante de toda a congregação de Israel, e estendendo suas mãos ao céu, disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Ó SENHOR Deus de Israel, não há Deus semelhante a ti no céu nem na terra, que guardas o pacto e a misericórdia a teus servos que caminham diante de ti de todo seu coração;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Que guardaste a teu servo Davi meu pai o que lhe disseste: tu o disseste de tua boca, mas com tua mão o cumpriste, como parece este dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Agora, pois, SENHOR Deus de Israel, guarda a teu servo Davi meu pai o que lhe prometeste, dizendo: Não faltará de ti homem diante de mim, que se sente no trono de Israel, a condição que teus filhos guardem seu caminho, andando em minha lei, como tu diante de mim andaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Agora, pois, ó SENHOR Deus de Israel, verifique-se tua palavra que disseste a teu servo Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Mas é verdade que Deus habitará com o homem na terra? Eis aqui, os céus e os céus dos céus não podem conter-te: quanto menos esta casa que edifiquei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Mas tu olharás à oração de teu servo, e a seu rogo, ó SENHOR Deus meu, para ouvir o clamor e a oração com que teu servo ora diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Que teus olhos estejam abertos sobre esta casa de dia e de noite, sobre o lugar do qual disseste, Meu nome estará ali; que oigas a oração com que teu servo ora em este lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Assim que ouças o rogo de teu servo, e de teu povo Israel, quando em este lugar fizerem oração, que tu ouvirás desde os céus, desde o lugar de tua morada: que ouças e perdoes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Se alguém pecar contra seu próximo, e ele lhe pedir juramento fazendo-lhe jurar, e o juramento vier diante de teu altar nesta casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Tu ouvirás desde os céus, e operarás, e julgarás a teus servos, dando a paga ao ímpio, voltando-lhe seu proceder sobre sua cabeça, e justificando ao justo em dar-lhe conforme a sua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Se o teu povo Israel cair diante dos inimigos, por haver pecado contra ti, e se converterem, e confessarem teu nome, e rogarem diante de ti nesta casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Tu ouvirás desde os céus, e perdoarás o pecado de teu povo Israel, e os voltarás à terra que deste a eles e a seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Se os céus se fecharem, que não haja chuvas por haver pecado contra ti, se orarem a ti em este lugar, e confessarem teu nome, e se converterem de seus pecados, quando os afligires,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Tu os ouvirás nos céus, e perdoarás o pecado de teus servos e de teu povo Israel, e lhes ensinarás o bom caminho para que andem nele, e darás chuva sobre tua terra, a qual deste por herdade a teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'E se houver fome na terra, ou se houver pestilência, se houver ferrugem ou mofo, locusta ou pulgão; ou se os cercarem seus inimigos na terra de seu domicílio; qualquer praga ou enfermidade que seja;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Toda oração e todo rogo que fizer qualquer homem, ou todo teu povo Israel, qualquer um que conhecer sua chaga e sua dor em seu coração, se estender suas mãos a esta casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Tu ouvirás desde os céus, desde o lugar de tua habitação, e perdoarás, e darás a cada um conforme a seus caminhos, havendo conhecido seu coração; (porque só tu conheces o coração dos filhos dos homens);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Para que te temam e andem em teus caminhos, todos os dias que viverem sobre a face da terra que tu deste aos nossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'E também ao estrangeiro que não for de teu povo Israel, que houver vindo de distantes terras a causa de teu grande nome, e de tua mão forte, e de teu braço estendido, se vierem, e orarem em esta casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Tu ouvirás desde os céus, desde o lugar de tua morada, e farás conforme a todas as coisas pelas quais houver clamado a ti o estrangeiro; para que todos os povos da terra conheçam teu nome, e te temam como teu povo Israel, e saibam que teu nome é invocado sobre esta casa que eu edifiquei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Se teu povo sair à guerra contra seus inimigos pelo caminho que tu os enviares, e orarem a ti até esta cidade que tu escolheste, até a casa que edifiquei a teu nome,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Tu ouvirás desde os céus sua oração e seu rogo, e ampararás seu direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Se pecarem contra ti, (pois não há ser humano que não peque), e te irares contra eles, e os entregares diante de seus inimigos, para que os que os tomarem os levem cativos à terra de inimigos, distante ou próxima,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'e eles se conscientizarem na terra de onde forem levados cativos; se se converterem, e orarem a ti na terra de seu cativeiro, e disserem: Pecamos, fizemos perversidade, agimos com maldade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'se se converterem a ti de todo o seu coração e de toda a sua alma na terra de seu cativeiro, aonde forem levados cativos, e orarem até sua terra que tu deste a seus pais, até a cidade que tu escolheste, e até a casa que edifiquei a teu nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Tu ouvirás desde os céus, desde o lugar de tua morada, sua oração e seu rogo, e ampararás sua causa, e perdoarás a teu povo que pecou contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Agora, pois, ó Deus meu, rogo-te estejam abertos teus olhos, e atentos teus ouvidos à oração em este lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Ó SENHOR Deus, levanta-te agora para habitar em teu repouso, tu e a arca de tua fortaleza; sejam, ó SENHOR Deus, vestidos de saúde teus sacerdotes, e regozijem de bem teus santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'SENHOR Deus, não faças virar o rosto de teu ungido: lembra-te das misericórdias de Davi teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'E quando Salomão acabou de orar, o fogo desceu dos céus, e consumiu o holocausto e as vítimas; e a glória do SENHOR encheu a casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'E não podiam entrar os sacerdotes na casa do SENHOR, porque a glória do SENHOR havia enchido a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'E quando viram todos os filhos de Israel descer o fogo e a glória do SENHOR sobre a casa, caíram em terra sobre seus rostos no pavimento, e adoraram, confessando ao SENHOR e dizendo: Que é bom, que sua misericórdia é para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Então o rei e todo o povo sacrificaram vítimas diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'E ofereceu o rei Salomão em sacrifício vinte e dois mil bois, e cento e vinte mil ovelhas; e assim dedicaram a casa de Deus o rei e todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'E os sacerdotes assistiam em seu ministério; e os levitas com os instrumentos de música do SENHOR, os quais havia feito o rei Davi para confessar ao SENHOR, que sua misericórdia é para sempre; quando Davi louvava por mão deles. Assim os sacerdotes tinham trombetas diante deles, e todo Israel estava em pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Também santificou Salomão o meio do átrio que estava diante da casa do SENHOR, porquanto havia oferecido ali os holocaustos, e a gordura dos pacíficos; porque no altar de bronze que Salomão havia feito, não podiam caber os holocaustos, e o presente, e as gorduras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Então fez Salomão festa sete dias, e com ele todo Israel, uma grande congregação, desde a entrada de Hamate até o ribeiro do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Ao oitavo dia fizeram convocação, porque haviam feito a dedicação do altar em sete dias, e haviam celebrado a solenidade por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'E aos vinte e três do mês sétimo enviou ao povo a suas moradas, alegres e jubilosos de coração pelos benefícios que o SENHOR havia feito a Davi, e a Salomão, e a seu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Acabou pois Salomão a casa do SENHOR, e a casa do rei: e todo o que Salomão teve em vontade de fazer na casa do SENHOR e em sua casa, foi próspero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'E apareceu o SENHOR a Salomão de noite, e disse-lhe: Eu ei ouvido tua oração, e escolhi para mim este lugar por casa de sacrifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Se eu fechar os céus, que não haja chuva, e se mandar à locusta que consuma a terra, ou se enviar pestilência a meu povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Se se humilhar meu povo, sobre os quais nem nome é invocado, e orarem, e buscarem meu rosto, e se converterem de seus maus caminhos; então eu ouvirei desde os céus, e perdoarei seus pecados, e sararei sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Agora estarão abertos meus olhos, e atentos meus ouvidos, à oração em este lugar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Pois que agora escolhi e santifiquei esta casa, para que esteja nela meu nome para sempre; e meus olhos e meu coração estarão aí para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'E tu, se andares diante de mim, como andou Davi teu pai, e fizeres todas as coisas que eu te ei mandado, e guardares meus estatutos e meus direitos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Eu confirmarei o trono de teu reino, como estabeleci com Davi teu pai, dizendo: Não faltará homem de ti que domine em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mas se vós vos desviardes, e deixardes meus estatutos e meus preceitos que vos propus, e fordes e servirdes a deuses alheios, e os adorardes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Eu os arrancarei de minha terra que lhes dei; e esta casa que ei santifiquei a meu nome, eu a lançarei de diante de mim, e a porei por provérbio e fábula em todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'E esta casa que haverá sido ilustre, será espanto a todo o que passar, e dirá: Por que há feito assim o SENHOR a esta terra e a esta casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'E se responderá: Por quanto deixaram ao SENHOR Deus de seus pais, o qual os tirou da terra do Egito, e abraçaram deuses alheios, e os adoraram e serviram: por isso ele trouxe todo este mal sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'E aconteceu que ao fim de vinte anos que Salomão havia edificado a casa do SENHOR e sua casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Reedificou Salomão as cidades que Hirão lhe havia dado, e estabeleceu nelas aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Depois veio Salomão a Hamate de Zobá, e a tomou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'E edificou a Tadmor no deserto, e todas as cidades de armazéns que edificou em Hamate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Assim reedificou a Bete-Horom a de acima, e a Bete-Horom a de abaixo, cidades fortificadas, de muros, portas, e barras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'E a Baalate, e a todas as vilas de armazéns que Salomão tinha; também todas as cidades dos carros e as de cavaleiros; e tudo o que Salomão quis edificar em Jerusalém, e no Líbano, e em toda a terra de seu senhorio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'E a todo o povo que havia restado dos heteus, amorreus, perizeus, heveus, e Jebuseos, que não eram de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Os filhos dos que haviam restado na terra depois deles, aos quais os filhos de Israel não destruíram do todo, fez Salomão tributários até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'E dos filhos de Israel não pôs Salomão servos em sua obra; porque eram homens de guerra, e seus príncipes e seus capitães, e comandantes de seus carros, e seus cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'E tinha Salomão duzentos e cinquenta principais dos governadores, os quais mandavam naquela gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'E passou Salomão à filha de Faraó, da cidade de Davi à casa que ele lhe havia edificado; porque disse: Minha mulher não morará na casa de Davi rei de Israel, porque aquelas habitações de onde entrou a arca do SENHOR, são sagradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Então ofereceu Salomão holocaustos ao SENHOR sobre o altar do SENHOR, que havia ele edificado diante do pórtico,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Para que oferecessem cada coisa em seu dia, conforme ao mandamento de Moisés, nos sábados, nas novas luas, e nas solenidades, três vezes no ano, a saber, na festa dos pães ázimos, na festa das semanas, e na festa das cabanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'E constituiu as repartições dos sacerdotes em seus ofícios, conforme à ordenação de Davi seu pai; e os levitas por suas ordens, para que louvassem e ministrassem diante dos sacerdotes, casa coisa em seu dia; assim os porteiros por sua ordem');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'E não saíram do mandamento do rei, quanto aos sacerdotes e levitas, e os tesouros, e todo negócio:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Porque toda a obra de Salomão estava preparada desde o dia em que a casa do SENHOR foi fundada até que se acabou, até que a casa do SENHOR foi acabada do tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Então Salomão foi a Eziom-Geber, e a Elote, à costa do mar na terra de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Porque Hirão lhe havia enviado navios por mão de seus servos, e marinheiros destros no mar, os quais foram com os servos de Salomão a Ofir, e tomaram de ali quatrocentos e cinquenta talentos de ouro, e os trouxeram ao rei Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'E ouvindo a rainha de Sabá a fama de Salomão, veio a Jerusalém com uma comitiva muito grande, com camelos carregados de aroma, e ouro em abundância, e pedras preciosas, para tentar a Salomão com perguntas difíceis. E logo que veio a Salomão, falou com ele tudo o que havia em seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Porém Salomão lhe declarou todas suas palavras: nenhuma coisa restou que Salomão não lhe declarasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'E vendo a rainha de Sabá a sabedoria de Salomão, e a casa que havia edificado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'E as iguarias de sua mesa, e o assento de seus servos, e o estado de seus criados, e os vestidos deles, seus mestres-salas e seus vestidos, e sua subida por de onde subia à casa do SENHOR, não restou mais espírito nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'E disse ao rei: Verdade é o que havia ouvido em minha terra de tuas coisas e de tua sabedoria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Mas eu não cria as palavras deles, até que ei vindo, e meus olhos viram: e eis que que nem ainda a metade da grandeza de tua sabedoria me havia sido dita; porque tu excedes a fama que eu havia ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Bem-aventurados teus homens, e ditosos estes teus servos, que estão sempre diante de ti, e ouvem tua sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'o SENHOR teu Deus seja bendito, o qual se agradou em ti para te pôr sobre seu trono por rei do SENHOR teu Deus: porquanto teu Deus amou a Israel para firmá-lo perpetuamente, por isso te pôs por rei sobre eles, para que faças juízo e justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'E deu ao rei cento e vinte talentos de ouro, e grande quantidade de aromas, e pedras preciosas: nunca havia tais aromas como os que deu a rainha de Sabá ao rei Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Também os servos de Hirão e os servos de Salomão, que haviam trazido o ouro de Ofir, trouxeram madeira de cipreste, e pedras preciosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'E fez o rei da madeira de cipreste degraus na casa do SENHOR, e nas casas reais, e harpas e saltérios para os cantores: nunca em terra de Judá se havia visto madeira semelhante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'E o rei Salomão deu à rainha de Sabá tudo o que ela quis e lhe pediu, mais de o que havia trazido ao rei. Depois se voltou e foi-se a sua terra com seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'E o peso de ouro que vinha a Salomão cada um ano, era seiscentos sessenta e seis talentos de ouro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Sem o que traziam os mercadores e negociantes; e também todos os reis da Arábia e os príncipes da terra traziam ouro e prata a Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Fez também o rei Salomão duzentos paveses de ouro de martelo, cada um dos quais tinha seiscentos siclos de ouro lavrado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Assim trezentos escudos de ouro batido, tendo cada escudo trezentos siclos de ouro: e os pôs o rei na casa do bosque do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Fez ademais o rei um grande trono de marfim, e cobriu-o de ouro puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'E havia seis degraus ao trono, com um estrado de ouro ao mesmo, e braços da uma parte e da outra ao lugar do assento, e dois leões que estavam junto aos braços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Havia também ali doze leões sobre os seis degraus da uma parte e da outra. Jamais foi feito outro semelhante em reino algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Todos os utensílios do rei Salomão eram de ouro, e todos os utensílios da casa do bosque do Líbano, de ouro puro. Nos dias de Salomão a prata não era de valiosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Porque a frota do rei ia a Társis com os servos de Hirão, e cada três anos faziam vir os navios de Társis, e traziam ouro, prata, marfim, macacos, e pavões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'E excedeu o rei Salomão a todos os reis da terra em riqueza e em sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'E todos os reis da terra procuravam ver o rosto de Salomão, por ouvir sua sabedoria, que Deus havia posto em seu coração:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'E destes, cada um trazia seu presente, vasos de prata, vasos de ouro, vestidos, armas, aromas, cavalos e mulas, todos os anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Teve também Salomão quatro mil estábulos para os cavalos e carros, e doze mil cavaleiros, os quais pôs nas cidades dos carros, e com o rei em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'E teve senhorio sobre todos os reis desde o rio até a terra dos filisteus, e até o termo do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'E pôs o rei prata em Jerusalém como pedras, e cedros como os sicômoros que nascem pelas campinas em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Traziam também cavalos para Salomão, do Egito e de todas as províncias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Os demais feitos de Salomão, primeiros e últimos, não está tudo escrito nos livros de Natã profeta, e na profecia de Aías silonita, e nas profecias do vidente Ido contra Jeroboão filho de Nebate?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'E reinou Salomão em Jerusalém sobre todo Israel quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'E descansou Salomão com seus pais, e sepultaram-no na cidade de Davi seu pai: e reinou em seu lugar Roboão seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'E Roboão foi a Siquém porque em Siquém se havia juntado todo Israel para fazê-lo rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'E quando o ouviu Jeroboão filho de Nebate, o qual estava em Egito, de onde havia fugido por causa do rei Salomão, voltou do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'E enviaram e chamaram-lhe. Veio, pois, Jeroboão, e todo Israel, e falaram a Roboão, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Teu pai agravou nosso jugo: alivia tu, pois, agora algo da dura servidão, e do grave jugo com que teu pai nos pressionou, e te serviremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'E ele lhes disse: Voltai a mim daqui a três dias. E o povo se foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Então o rei Roboão tomou conselho com os anciãos, que haviam estado diante de Salomão seu pai quando vivia, e disse-lhes: Como aconselhais vós que responda a este povo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'E eles lhe falaram, dizendo: Se te conduzires humanamente com este povo, e os agradares, e lhes falares boas palavras, eles te servirão perpetuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mas ele, deixando o conselho que lhe deram os anciãos, tomou conselho com os rapazes que se haviam criado com ele, e que diante dele assistiam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'E disse-lhes: Que aconselhais vós que respondamos a este povo, que me falou, dizendo: Alivia algo do jugo que teu pai pôs sobre nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Então os rapazes que se haviam criado com ele, lhe falaram, dizendo: Assim dirás ao povo que te falou dizendo, Teu pai agravou nosso jugo, mas tu livra-nos da carga: assim lhes dirás: O meu dedo mínimo é mais espesso que os lombos de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Assim que, meu pai vos impôs carga de grave jugo, e eu acrescentarei a vosso jugo: meu pai vos castigou com açoites, e eu com escorpiões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Veio, pois, Jeroboão com todo o povo a Roboão ao terceiro dia: segundo o rei lhes havia mandado dizendo: Voltai a mim daqui a três dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'E respondeu-lhes o rei asperamente; pois deixou o rei Roboão o conselho dos anciãos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'E falou-lhes conforme ao conselho dos rapazes, dizendo: Meu pai agravou vosso jugo, e eu acrescentarei a vosso jugo: meu pai vos castigou com açoites, e eu com escorpiões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'E não escutou o rei ao povo; porque a causa era de Deus, para cumprir o SENHOR sua palavra que havia falado, por Aías silonita, a Jeroboão filho de Nebate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'E vendo todo Israel que o rei não lhes havia ouvido, respondeu o povo ao rei, dizendo: Que parte temos nós com Davi, nem herança no filho de Jessé? Israel, cada um a suas moradas! Davi, olha agora por tua casa! Assim se foi todo Israel a suas casas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Mas reinou Roboão sobre os filhos de Israel que habitavam nas cidades de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Enviou logo o rei Roboão a Adorão, que tinha cargo dos tributos; mas lhe apedrejaram os filhos de Israel, e morreu. Então se esforçou o rei Roboão, e subindo em um carro fugiu a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Assim se separou Israel da casa de Davi até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'E quando veio Roboão a Jerusalém, juntou da casa de Judá e de Benjamim cento e oitenta mil homens escolhidos de guerra, para lutar contra Israel e voltar o reino a Roboão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mas foi palavra do SENHOR a Semaías homem de Deus, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Fala a Roboão filho de Salomão, rei de Judá, e a todos os israelitas em Judá e Benjamim, dizendo-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Assim disse o SENHOR: Não subais nem luteis contra vossos irmãos; volte-se casa um a sua casa, porque eu fiz este negócio. E eles ouviram a palavra do SENHOR, e voltaram-se, e não foram contra Jeroboão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'E habitou Roboão em Jerusalém, e edificou cidades para fortificar a Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'E edificou a Belém, e a Etã, e a Tecoa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'E a Bete-Zur, e a Socó, e a Adulão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'E a Gate, e a Maressa, e a Zife,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'E a Adoraim, e a Laquis, e a Azeca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'E a Zorá, e a Aijalom, e a Hebrom, que eram em Judá e em Benjamim, cidades fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Fortificou também as fortalezas, e pôs nelas capitães, e alimentos, e vinho, e azeite;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'E em todas as cidades, escudos e lanças. Fortificou-as pois em grande maneira, e Judá e Benjamim lhe estavam sujeitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'E os sacerdotes e levitas que estavam em todo Israel, se juntaram a ele de todos seus termos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Porque os levitas deixavam seus campos e suas possessões, e se vinham a Judá e a Jerusalém: pois Jeroboão e seus filhos os lançavam do ministério do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'E ele se fez sacerdotes para os altos, e para os demônios, e para os bezerros que ele havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Além daqueles acudiram também de todas as tribos de Israel os que haviam posto seu coração em buscar ao SENHOR Deus de Israel; e vieram-se a Jerusalém para sacrificar ao SENHOR, o Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Assim fortificaram o reino de Judá, e confirmaram a Roboão filho de Salomão, por três anos; porque três anos andaram no caminho de Davi e de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'E tomou-se Roboão por mulher a Maalate, filha de Jeremote filho de Davi, e a Abiail, filha de Eliabe filho de Jessé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'A qual lhe gerou filhos: a Jeus, e a Samaria, e a Zaaão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Depois dela tomou a Maaca filha de Absalão, a qual lhe pariu a Abias, a Atai, Ziza, e Selomite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Mas Roboão amou a Maaca filha de Absalão sobre todas suas mulheres e concubinas; porque tomou dezoito mulheres e sessenta concubinas, e gerou vinte e oito filhos e sessenta filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'E pôs Roboão a Abias filho de Maaca por cabeça e príncipe de seus irmãos, porque queria fazer-lhe rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'E fez-lhe instruir, e dispersou todos os seus filhos por todas as terras de Judá e de Benjamim, e por todas as cidades fortes, e deu-lhes alimentos em abundância, e buscou para eles muitas mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'E quando Roboão havia confirmado o reino, deixou a lei do SENHOR, e com ele todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'E no quinto ano do rei Roboão subiu Sisaque rei do Egito contra Jerusalém, (porquanto se haviam rebelado contra o SENHOR,)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Com mil e duzentos carros, e com sessenta mil cavaleiros: mas o povo que vinha com ele do Egito, não tinha número; a saber, de líbios, suquitas, e etíopes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'E tomou as cidades fortes de Judá, e chegou até Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Então veio Semaías profeta a Roboão e aos príncipes de Judá, que estavam reunidos em Jerusalém por causa de Sisaque, e disse-lhes: Assim disse o SENHOR: Vós me deixastes, e eu também vos deixei em mãos de Sisaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'E os príncipes de Israel e o rei se humilharam, e disseram: Justo é o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'E quando viu o SENHOR que se haviam humilhado, foi palavra do SENHOR a Semaías, dizendo: Humilharam-se; não os destruirei; antes os salvarei em breve, e não se derramará minha ira contra Jerusalém por mão de Sisaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Porém serão seus servos; para que saibam que é servir a mim, e servir aos reinos das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Subiu, pois, Sisaque, rei do Egito a Jerusalém, e tomou os tesouros da casa do SENHOR, e os tesouros da casa do rei; tudo o levou: e tomou os paveses de ouro que Salomão havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'E em lugar deles fez o rei Roboão paveses de bronze, e entregou-os em mãos dos chefes da guarda, os quais guardavam a entrada da casa do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'E quando o rei ia à casa do SENHOR, vinham os da guarda, e traziam-nos, e depois os voltavam à câmara da guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'E quando ele se humilhou, a ira do SENHOR se separou dele, para não destruí-lo de todo: e também em Judá as coisas foram bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Fortificou-se, pois Roboão, e reinou em Jerusalém: e era Roboão de quarenta e um anos quando começou a reinar, e dezessete anos reinou em Jerusalém, cidade que escolheu o SENHOR de todas as tribos de Israel, para pôr nela seu nome. E o nome de sua mãe foi Naamá, amonita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'E fez o mal, porque não dispôs seu coração para buscar ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'E as coisas de Roboão, primeiras e últimas, não estão escritas nos livros de Semaías profeta e de Ido vidente, no registro das linhagens? E entre Roboão e Jeroboão havia perpétua guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'E descansou Roboão com seus pais, e foi sepultado na cidade de Davi: e reinou em seu lugar Abias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Aos dezoito anos do rei Jeroboão, reinou Abias sobre Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'E reinou três anos em Jerusalém. O nome de sua mãe foi Micaia filha de Uriel de Gibeá. E havia guerra entre Abias e Jeroboão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Então ordenou Abias batalha com um exército de quatrocentos mil homens de guerra valentes e escolhidos: e Jeroboão ordenou batalha contra ele com oitocentos mil homens escolhidos, fortes e valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'E levantou-se Abias sobre o monte de Zemaraim, que é nos montes de Efraim, e disse: Ouvi-me, Jeroboão e todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Não sabeis vós, que o SENHOR Deus de Israel deu o reino a Davi sobre Israel para sempre, a ele e a seus filhos em aliança de sal?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Porém Jeroboão filho de Nebate, servo de Salomão filho de Davi, se levantou e rebelou contra seu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'E se achegaram a ele homens vãos, filhos de iniquidade, e puderam mais que Roboão filho de Salomão, porque Roboão era jovem e tenro de coração, e não se defendeu deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'E agora vós tratais de fortificar-vos contra o reino do SENHOR em mão dos filhos de Davi, porque sois muitos, e tendes convosco os bezerros de ouro que Jeroboão vos fez por deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Não lançastes vós aos sacerdotes do SENHOR, aos filhos de Arão, e aos levitas, e vos haveis feito sacerdotes à maneira dos povos de outras terras, para que qualquer um venha a consagrar-se com um bezerro e sete carneiros, e assim seja sacerdote dos que não são Deuses?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mas em quanto a nós, o SENHOR é nosso Deus, e não lhe deixamos: e os sacerdotes que ministram ao SENHOR são os filhos de Arão, e os levitas na obra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Os quais queimam ao SENHOR os holocaustos cada manhã e cada tarde, e os perfumes aromáticos; e põem os pães sobre a mesa limpa, e o candelabro de ouro com suas lâmpadas para que ardam cada tarde: porque nós guardamos a ordenança do SENHOR nosso Deus; mas vós o deixastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'E eis que Deus está com nós por cabeça, e seus sacerdotes com as trombetas do júbilo para que soem contra vós. Ó filhos de Israel, não luteis contra o SENHOR o Deus de vossos pais, porque não vos sucederá bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Porém Jeroboão preparou uma emboscada para vir a eles pela retaguarda: e estando assim diante deles, a emboscada estava à retaguarda de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'E quando olhou Judá, eis que tinha batalha diante e às costas; por isso que clamaram ao SENHOR, e os sacerdotes tocaram as trombetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Então os de Judá levantaram grito; e assim que eles levantaram grito, Deus derrotou a Jeroboão e a todo Israel diante de Abias e de Judá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'E fugiram os filhos de Israel diante de Judá, e Deus os entregou em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'E Abias e sua gente faziam em eles grande mortandade; e caíram feridos de Israel quinhentos mil homens escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Assim foram humilhados os filhos de Israel naquele tempo: mas os filhos de Judá se fortificaram, porque se apoiavam no SENHOR o Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'E seguiu Abias a Jeroboão, e tomou-lhe algumas cidades, a Betel com suas aldeias, a Jesana com suas aldeias, e a Efraim com suas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'E nunca mais teve Jeroboão poderio nos dias de Abias: e feriu-lhe o SENHOR, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Porém se fortificou Abias; e tomou catorze mulheres, e gerou vinte e dois filhos, e dezesseis filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Os demais feitos de Abias, seus caminhos e seus negócios, estão escritos na história do profeta Ido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'E descansou Abias com seus pais, e foi sepultado na cidade de Davi. E reinou em seu lugar seu filho Asa, em cujos dias teve sossego o país por dez anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'E fez Asa o que era bom e correto aos olhos do SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Porque tirou os altares do culto alheio, e os altos; quebrou as imagens, e arrancou os bosques;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'E mandou a Judá que buscassem ao SENHOR o Deus de seus pais, e praticassem a lei e seus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Tirou também de todas as cidades de Judá os altos e as imagens, e esteve o reino quieto diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'E edificou cidades fortes em Judá, porquanto havia paz na terra, e não havia guerra contra ele em aqueles tempos; porque o SENHOR lhe havia dado repouso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Disse por tanto a Judá: Edifiquemos estas cidades, e as cerquemos de muros com torres, portas, e barras, já que a terra é nossa: porque buscamos ao SENHOR nosso Deus, temos o buscado, e ele nos deu repouso de todas as partes. Edificaram, pois, e foram prósperos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Teve também Asa exército que trazia escudos e lanças: de Judá trezentos mil, e de Benjamim duzentos e oitenta mil que traziam escudos e flechavam arcos; todos eram homens hábeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'E saiu contra eles Zerá etíope com um exército de mil milhares, e trezentos carros; e vinho até Maressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Então saiu Asa contra ele, e ordenaram a batalha no vale de Zefatá junto a Maressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'E clamou Asa ao SENHOR seu Deus, e disse: SENHOR, ninguém há mais que a ti para dar ajuda entre o grande e o que nenhuma força tem. Ajuda-nos, ó SENHOR Deus nosso, porque em ti nos apoiamos, e em teu nome viemos contra este exército. Ó SENHOR, tu és nosso Deus; não prevaleça contra ti o homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'E o SENHOR derrotou os etíopes diante de Asa e diante de Judá; e fugiram os etíopes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'E Asa, e o povo que com ele estava, o seguiu até Gerar: e caíram os etíopes até não haver neles resistência alguma; porque foram derrotados diante do SENHOR e de seu exército. E lhes tomaram muito grande despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Bateram também todas as cidades ao redor de Gerar, porque o terror do SENHOR foi sobre eles: e saquearam todas as cidades, porque havia nelas grande despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Assim atacaram as cabanas onde havia gado, e trouxeram muitas ovelhas e camelos, e voltaram a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'E foi o espírito de Deus sobre Azarias filho de Obede;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'E saiu ao encontro a Asa, e disse-lhe: Ouvi-me, Asa, e todo Judá e Benjamim: o SENHOR é convosco, se vós fordes com ele: e se lhe buscardes, será achado de vós; mas se lhe deixardes, ele também vos deixará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Muitos dias esteve Israel sem verdadeiro Deus e sem sacerdote, e sem ensinador e sem lei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Mas quando em sua tribulação se converteram ao SENHOR Deus de Israel, e lhe buscaram, ele foi achado deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Em aqueles tempos não havia paz, nem para o que entrava, nem para o que saía, mas sim muitas aflições sobre todos os habitantes das terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'E a uma gente destruía à outra, e uma cidade a outra cidade: porque Deus os conturbou com todas as calamidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Esforçai-vos, porém, vós, e não desfaleçam vossas mãos; que recompensa há para vossa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'E quando ouviu Asa as palavras e profecia de Obede profeta, foi confortado, e tirou as abominações de toda a terra de Judá e de Benjamim, e das cidades que ele havia tomado no monte de Efraim; e reparou o altar do SENHOR que estava diante do pórtico do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Depois fez juntar a todo Judá e Benjamim, e com eles os estrangeiros de Efraim, e de Manassés, e de Simeão: porque muitos de Israel se haviam passado a ele, vendo que o SENHOR seu Deus era com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Juntaram-se, pois, em Jerusalém no mês terceiro do ano décimo quinto do reinado de Asa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'E naquele mesmo dia sacrificaram ao SENHOR, dos despojos que haviam trazido, setecentos bois e sete mil ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'E entraram em concerto de que buscariam ao SENHOR o Deus de seus pais, de todo seu coração e de toda sua alma;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'E que qualquer um que não buscasse ao SENHOR o Deus de Israel, morresse, grande ou pequeno, homem ou mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'E juraram ao SENHOR com grande voz e júbilo, a som de trombetas e de buzinas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Do qual juramento todos os de Judá se alegraram; porque de todo o seu coração o juravam, e de toda sua vontade o buscavam: e foi achado deles; e deu-lhes o SENHOR repouso de todas partes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'E ainda a Maaca mãe do rei Asa, ele mesmo a depôs de sua dignidade, porque havia feito um ídolo no bosque: e Asa destruiu seu ídolo, e o despedaçou, e queimou no ribeiro de Cedrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Mas com tudo isso os altos não foram tirados de Israel, ainda que o coração de Asa tenha sido íntegro enquanto viveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'E meteu na casa de Deus o que seu pai havia dedicado, e o que ele havia consagrado, prata e ouro e vasos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'E não havia guerra até os trinta e cinco anos do reinado de Asa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'No ano trinta e seis do reinado de Asa, subiu Baasa rei de Israel contra Judá, e edificou a Ramá, para não deixar sair nem entrar a ninguém ao rei Asa, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Então tirou Asa a prata e o ouro dos tesouros da casa do SENHOR e da casa real, e enviou a Ben-Hadade rei da Síria, que estava em Damasco, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Haja aliança entre mim e ti, como a havia entre meu pai e teu pai; eis que eu te enviei prata e ouro, para que venhas e desfaças a aliança que tens com Baasa rei de Israel, a fim de que se retire de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'E consentiu Ben-Hadade com o rei Asa, e enviou os capitães de seus exércitos à cidades de Israel: e atacaram a Ijom, Dã, e Abel-Maim, e as cidades fortes de Naftali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'E ouvindo isto Baasa, cessou de edificar a Ramá, e deixou sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Então o rei Asa tomou a todo Judá, e levaram-se de Ramá a pedra e madeira com que Baasa edificava, e com ela edificou a Geba e Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Naquele tempo veio Hanani vidente a Asa rei de Judá, e disse-lhe: Por quanto te apoiaste no rei de Síria, e não te apoiaste no SENHOR teu Deus, por isso o exército do rei da Síria escapou de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Os etíopes e os líbios, não eram um exército numerosíssimo, com carros e muitos cavaleiros? Contudo, porque te apoiaste no SENHOR, ele os entregou em tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Porque os olhos do SENHOR contemplam toda a terra, para corroborar aos que têm coração íntegro com ele. Loucamente fizeste nisso; porque de agora em diante haverá guerra contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'E irou-se Asa contra o vidente, lançou-o na casa do cárcere, porque foi em extremo incomodado por causa disto. E oprimiu Asa naquele tempo alguns do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Mas eis que, os feitos de Asa, primeiros e últimos, estão escritos no livro dos reis de Judá e de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'E o ano trinta e nove de seu reinado enfermou Asa dos pés para acima, e em sua enfermidade não buscou ao SENHOR, mas sim aos médicos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'E descansou Asa com seus pais, e morreu no ano quarenta e um de seu reinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'E sepultaram-no em seus sepulcros que ele havia feito para si na cidade de Davi; e puseram-no em uma cama, a qual encheram de aromas e artefatos com fragrâncias, preparadas por perfumistas; e fizeram uma grande fogueira em sua homenagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'E reinou em seu lugar Josafá seu filho, o qual prevaleceu contra Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'E pôs exército em todas as cidades fortes de Judá, e colocou gente de guarnição, em terra de Judá, e também nas cidades de Efraim que seu pai Asa havia tomado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'E foi o SENHOR com Josafá, porque andou nos primeiros caminhos de Davi seu pai, e não buscou aos baalins;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Mas sim que buscou ao Deus de seu pai, e andou em seus mandamentos, e não segundo as obras de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'o SENHOR por tanto confirmou o reino em sua mão, e todo Judá deu a Josafá presentes; e teve riquezas e glória em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'E animou-se seu coração nos caminhos do SENHOR, e tirou os altos e os bosques de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Ao terceiro ano de seu reinado enviou seus príncipes Bene-Hail, Obadias, Zacarias, Natanael e Micaías, para que ensinassem nas cidades de Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'E com eles aos levitas, Semaías, Netanias, Zebadias, e Asael, e Semiramote, e Jônatas, e Adonias, e Tobias, e Tobadonias, levitas; e com eles a Elisama e a Jorão, sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'E ensinaram em Judá, tendo consigo o livro da lei do SENHOR, e rodearam por todas as cidades de Judá ensinando ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'E caiu o pavor do SENHOR sobre todos os reinos das terras que estavam ao redor de Judá; que não ousaram fazer guerra contra Josafá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'E traziam dos filisteus presentes a Josafá, e tributos de prata. Os árabes também lhe trouxeram gados, sete mil e setecentos carneiros e sete mil e setecentos bodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Ia pois Josafá crescendo altamente: e edificou em Judá fortalezas e cidades de depósitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Teve ademais muitas obras nas cidades de Judá, e homens de guerra muito valentes em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'E este é o número deles segundo as casas de seus pais: em Judá, chefes dos milhares: o general Adna, e com ele trezentos mil homens muito esforçados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Depois dele, o chefe Joanã, e com ele duzentos e oitenta mil;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Depois este, Amasias filho de Zicri, o qual se havia oferecido voluntariamente ao SENHOR, e com ele duzentos mil homens valentes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'De Benjamim, Eliada, homem muito valente, e com ele duzentos mil armados de arco e escudo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Depois este, Jozabade, e com ele cento e oitenta mil preparados para a guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Estes eram servos do rei, sem os que havia o rei posto nas cidades de guarnição por toda Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Tinha, pois, Josafá riquezas e glória em abundância, e estabeleceu parentesco com Acabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'E depois de alguns anos desceu a Acabe a Samaria; por o que matou Acabe muitas ovelhas e bois para ele, e para a gente que com ele vinha: e persuadiu-lhe que fosse com ele a Ramote de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'E disse Acabe rei de Israel a Josafá rei de Judá: Queres vir comigo a Ramote de Gileade? E ele respondeu: Como eu, assim também tu; e como teu povo, assim também meu povo: iremos contigo à guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Ademais disse Josafá ao rei de Israel: Rogo-te que consultes hoje a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Então o rei de Israel juntou quatrocentos profetas, e disse-lhes: Iremos à guerra contra Ramote de Gileade, ou ficarei eu quieto? E eles disseram: Sobe, que Deus os entregará em mão do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Mas Josafá disse: Há ainda aqui algum profeta do SENHOR, para que por ele perguntemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'E o rei de Israel respondeu a Josafá: Ainda há aqui um homem pelo qual podemos preguntar ao SENHOR: mas eu lhe aborreço, porque nunca me profetiza coisa boa, a não ser sempre mal. Este é Micaías, filho de Inlá. E respondeu Josafá: Não fale assim o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Então o rei de Israel chamou um eunuco, e disse-lhe: Faze vir logo a Micaías filho de Inlá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'E o rei de Israel e Josafá rei de Judá, estavam sentados cada um em seu trono, vestidos de suas roupas; e estavam sentados na eira à entrada da porta de Samaria, e todos os profetas profetizavam diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'E Zedequias filho de Quenaaná se havia feito chifres de ferro, e dizia: Assim disse o SENHOR: Com estes chifrarás aos sírios até destruí-los de todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'De esta maneira profetizavam também todos os profetas, dizendo: Sobe a Ramote de Gileade, e sei próspero; porque o SENHOR a entregará em mão do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'E o mensageiro que havia ido a chamar a Micaías, lhe falou, dizendo: Eis aqui as palavras dos profetas a uma boca anunciam ao rei bens; eu, pois, te rogo que tua palavra seja como a de um deles, que fales bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'E disse Micaías: Vive o SENHOR, que o que meu Deus me disser, isso falarei. E veio ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'E o rei lhe disse: Micaías, iremos a lutar contra Ramote de Gileade, ou ficarei eu quieto? E ele respondeu: Subi, que sereis prosperados, que serão entregues em vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'E o rei lhe disse: Até quantas vezes te conjurarei pelo nome do SENHOR que não me fales a não ser a verdade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Então ele disse: Eis visto a todo Israel derramado pelos montes como ovelhas sem pastor: e disse o SENHOR: Estes não têm senhor; volte-se cada um em paz em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'E o rei de Israel disse a Josafá: Não te havia eu dito que não me profetizaria bem, mas sim mal?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Então ele disse: Ouvi, pois, a palavra do SENHOR: Eu vi ao SENHOR sentado em seu trono, e todo o exército dos céus estava a sua mão direita e a sua esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'E o SENHOR disse: Quem induzirá a Acabe rei de Israel, para que suba e caia em Ramote de Gileade? E um dizia assim, e outro dizia de outra maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Mas saiu um espírito, que se pôs diante do SENHOR, e disse: Eu lhe induzirei. E o SENHOR lhe disse: De que modo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'E ele disse: Sairei e serei espírito de mentira na boca de todos os profetas. E o SENHOR disse: Incita, e também prevalece: sai, e faze-o assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'E eis que agora pôs o SENHOR espírito de mentira na boca destes teus profetas; mas o SENHOR decretou o mal acerca de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Então Zedequias filho de Quenaaná se chegou a ele, e feriu a Micaías na face, e disse: Por que caminho se separou de mim o espírito do SENHOR para falar a ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'E Micaías respondeu: Eis aqui tu o verás aquele dia, quando te entrarás de câmara em câmara para esconder-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Então o rei de Israel disse: Tomai a Micaías, e voltai-o a Amom governador da cidade, e a Joás filho do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'E direis: O rei disse assim: Ponde a este no cárcere, e sustentai-lhe com pão de aflição e água de angústia, até que eu volte em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'E Micaías disse: Se tu voltares em paz, o SENHOR não falou por mim. Disse ademais: Ouvi o, povos todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Subiu, pois, o rei de Israel, e Josafá rei de Judá, a Ramote de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'E disse o rei de Israel a Josafá: Eu me disfarçarei para entrar na batalha: mas tu veste-te tuas roupas. E disfarçou-se o rei de Israel, e entrou na batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Havia o rei de Síria mandado aos capitães dos carros que tinha consigo, dizendo: Não luteis com pequeno nem com grande, a não ser somente com o rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'E como os capitães dos carros viram a Josafá, disseram: Este é o rei de Israel. E cercaram-no para lutar; mas Josafá clamou, e ajudou-o o SENHOR, e apartou-os Deus dele:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Pois vendo os capitães dos carros que não era o rei de Israel, desistiram de persegui-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Mas disparando um o arco ao acaso, feriu ao rei de Israel entre as junturas e a armadura. Ele então disse ao condutor do carro: Volta tua mão, e tira-me do campo, porque estou gravemente ferido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'E intensificou a batalha aquele dia, por o que esteve o rei de Israel em pé no carro em frente dos sírios até a tarde; mas morreu a pôr do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'E Josafá rei de Judá se voltou em paz a sua casa em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'E saiu-lhe ao encontro Jeú o vidente, filho de Hanani, e disse ao rei Josafá: Ao ímpio dás ajuda, e amas aos que aborrecem ao SENHOR? Pois a ira da presença do SENHOR será sobre ti por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Porém se acharam em ti boas coisas, porque cortaste da terra os bosques, e dispuseste tua coração a buscar a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Habitou, pois, Josafá em Jerusalém; mas dava volta e saía ao povo, desde Berseba até o monte de Efraim, e os reconduzia ao SENHOR, o Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'E pôs na terra juízes em todas as cidades fortes de Judá, por todos os lugares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'E disse aos juízes: Olhai o que fazeis: porque não julgueis em lugar de homem, mas sim em lugar do SENHOR, o qual está convosco no negócio do juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Seja, pois, convosco o temor do SENHOR; guardai e fazei: porque no SENHOR nosso Deus não há iniquidade, nem acepção de pessoas, nem receber suborno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'E pôs também Josafá em Jerusalém alguns dos levitas e sacerdotes, e dos pais de famílias de Israel, para o juízo do SENHOR e para as causas. E voltaram a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'E mandou-lhes, dizendo: Procedereis assim com temor do SENHOR, com verdade, e com coração íntegro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Em qualquer causa que vier a vós de vossos irmãos que habitam nas cidades, entre sangue e sangue, entre lei e preceito, estatutos e direitos, haveis de admoestar-lhes que não pequem contra o SENHOR, porque não venha ira sobre vós e sobre vossos irmãos. Agindo assim, não pecareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'E eis que Amarias sacerdote será o que vos presida em todo negócio do SENHOR; e Zebadias filho de Ismael, príncipe da casa de Judá, em todos os negócios do rei; também os levitas serão oficiais em presença de vós. Esforçai-vos, pois, e agi; porque o SENHOR estará com quem é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Passadas estas coisas, aconteceu que os filhos de Moabe e de Amom, e com eles outros dos amonitas, vieram contra Josafá à guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'E acudiram, e deram aviso a Josafá, dizendo: Contra ti vem uma grande multidão da outra parte do mar, e da Síria; e eis que eles estão em Hazazom-Tamar, que é En-Gedi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Então ele teve temor; e pôs Josafá seu rosto para consultar ao SENHOR, e fez apregoar jejum a todo Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'E juntaram-se os de Judá para pedir socorro ao SENHOR: e também de todas as cidades de Judá vieram a pedir ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Pôs-se então Josafá em pé na reunião de Judá e de Jerusalém, na casa do SENHOR, diante do átrio novo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'E disse: o SENHOR Deus de nossos pais, não és tu Deus nos céus, e te ensenhoreias em todos os reinos das nações? não está em tua mão tal força e potência, que não há quem te resista?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Deus nosso, não lançaste tu os moradores desta terra diante de teu povo Israel, e a deste à semente de Abraão tua amigo para sempre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'E eles habitaram nela, e te edificaram nela santuário a teu nome, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Se mal vier sobre nós, ou espada de castigo, ou pestilência, ou fome, nos apresentaremos diante desta casa, e diante de ti, (porque teu nome está em esta casa,) e de nossas tribulações clamaremos a ti, e tu nos ouvirás e salvarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Agora, pois, eis que os filhos de Amom e de Moabe, e os do monte de Seir, à terra dos quais nem quiseste que passasse Israel quando vinham da terra do Egito, mas sim que se afastassem deles, e não os destruíssem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Eis que eles nos dão o pago, vindo a lançar-nos de tua herdade, que tu nos deste a possuir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Ó Deus nosso! Não os julgarás tu? Porque em nós não há força contra tão grande multidão que vem contra nós: não sabemos o que devemos fazer, mas a ti voltamos nossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'E todo Judá estava em pé diante do SENHOR, com seus meninos, e suas mulheres, e seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'E estava ali Jaaziel filho de Zacarias, filho de Benaia, filho de Jeiel, filho de Matanias, levita dos filhos de Asafe, sobre o qual veio o espírito do SENHOR em meio da reunião;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'E disse: Ouvi, Judá todo, e vós moradores de Jerusalém, e tu, rei Josafá. o SENHOR vos diz assim: Não temais nem vos amedronteis diante desta tão grande multidão; porque não é vossa a guerra, mas sim de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Amanhã descereis contra eles: eis que eles subirão pela encosta de Ziz, e os achareis junto ao ribeiro, antes do deserto de Jeruel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Não haverá para que vós luteis em este caso: parai-vos, ficai parados, e vede a salvação do SENHOR convosco. Ó Judá e Jerusalém, não temais nem desmaieis; saí amanhã contra eles, que o SENHOR será convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Então Josafá se inclinou rosto por terra, e também todo Judá e os moradores de Jerusalém se prostraram diante do SENHOR, e adoraram ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'E levantaram-se os levitas dos filhos de Coate e dos filhos de Corá, para louvar ao SENHOR o Deus de Israel a grande e alta voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'E quando se levantaram pela manhã, saíram pelo deserto de Tecoa. E enquanto eles saíam, Josafá estando em pé, disse: Ouvi-me, Judá e moradores de Jerusalém. Crede no SENHOR vosso Deus, e sereis seguros; crede em seus profetas, e sereis prosperados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'E havido conselho com o povo, pôs a alguns que cantassem ao SENHOR, e louvassem na formosura da santidade, enquanto que saía a gente armada, e dissessem: Glorificai ao SENHOR, porque sua misericórdia é para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'E quando começaram com clamor e com louvor, pôs o SENHOR contra os filhos de Amom, de Moabe, e do monte de Seir, as emboscadas deles mesmos que vinham contra Judá, e mataram-se os uns aos outros:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Pois os filhos de Amom e Moabe se levantaram contra os do monte de Seir, para matá-los e destruí-los; e quando houveram acabado aos do monte de Seir, cada qual ajudou à destruição de seu companheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'E logo que veio Judá ao posto de observação do deserto, olharam até a multidão; mas eis que jaziam eles em terra mortos, que ninguém havia escapado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Vindo então Josafá e seu povo a despojá-los, acharam neles muitas riquezas entre os cadáveres, assim vestidos como preciosos utensílios, os quais tomaram para si, tantos, que não os podiam levar: três dias durou o despojo, porque era muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'E ao quarto dia se juntaram no vale de Beraca; porque ali bendisseram ao SENHOR, e por isto chamaram o nome daquele lugar o vale de Beraca, até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'E todo Judá e os de Jerusalém, e Josafá à cabeça deles, voltaram a Jerusalém com alegria, porque o SENHOR lhes havia dado alegria de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'E vieram a Jerusalém com saltérios, harpas, e buzinas, à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'E foi o pavor de Deus sobre todos os reinos daquela terra, quando ouviram que o SENHOR havia pelejado contra os inimigos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'E o reino de Josafá teve repouso; porque seu Deus lhe deu repouso de todas partes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Assim reinou Josafá sobre Judá: de trinta e cinco anos era quando começou a reinar, e reinou vinte e cinco anos em Jerusalém. O nome de sua mãe foi Azuba, filha de Sili.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'E andou no caminho de Asa seu pai, sem desviar-se dele, fazendo o que era correto aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Com tudo isso os altos não foram tirados; que o povo ainda não havia preparado seu coração ao Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Os demais dos feitos de Josafá, primeiros e últimos, eis que estão escritos nas palavras de Jeú filho de Hanani, do qual é feita menção no livro dos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Passadas estas coisas, Josafá rei de Judá estabeleceu amizade com Acazias rei de Israel, o qual foi dado à impiedade:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'E fez com ele companhia para preparar navios que fossem a Társis; e construíram os navios em Eziom-Geber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Então Eliézer filho de Dodava de Maressa, profetizou contra Josafá, dizendo: Por quanto fizeste companhia com Acazias, o SENHOR destruirá tuas obras. E os navios se romperam, e não puderam ir a Társis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'E descansou Josafá com seus pais, e sepultaram-no com seus pais na cidade de Davi. E reinou em seu lugar Jeorão seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Este teve irmãos, filhos de Josafá, a Azarias, Jeiel, Zacarias, Azarias, Micael, e Sefatias. Todos estes foram filhos de Josafá rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'E seu pai lhes havia dado muitos presentes de ouro e de prata, e coisas preciosas, e cidades fortes em Judá; mas havia dado o reino a Jeorão, porque ele era o primogênito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Foi, pois, elevado Jeorão ao reino de seu pai; e logo que se fez forte, matou à espada a todos seus irmãos, e também alguns dos príncipes de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Quando começou a reinar era de trinta e dois anos, e reinou oito anos em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'E andou no caminho dos reis de Israel, como fez a casa de Acabe; porque tinha por mulher a filha de Acabe, e fez o que era mau aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Mas o SENHOR não quis destruir a casa de Davi, a causa da aliança que com Davi havia feito, e porque lhe havia dito que lhe daria lâmpada a ele e a seus filhos perpetuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Em os dias deste se rebelou Edom, para não estar sob o poder de Judá, e puseram rei sobre si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Então passou Jeorão com seus príncipes, e consigo todos seus carros; e levantou-se de noite, e feriu aos edomitas que lhe haviam cercado, e a todos os comandantes de seus carros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Com tudo isso Edom ficou rebelado, sem estar sob a mão de Judá até hoje. Também se rebelou no mesmo tempo Libna para não estar sob sua mão; porquanto ele havia deixado ao SENHOR o Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Além disto, fez altos nos montes de Judá, e fez que os moradores de Jerusalém fornicassem, e a ele impeliu a Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'E vieram-lhe letras do profeta Elias, que diziam: o SENHOR, o Deus de Davi teu pai, disse assim: Por quanto não andaste nos caminhos de Josafá teu pai, nem nos caminhos de Asa, rei de Judá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Antes andaste no caminho dos reis de Israel, e fizeste que fornicasse Judá, e os moradores de Jerusalém, como fornicou a casa de Acabe; e ademais mataste a teus irmãos, à família de teu pai, os quais eram melhores que tu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Eis que o SENHOR ferirá teu povo de uma grande praga, e a teus filhos e a tuas mulheres, e a toda tua riqueza;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'E a ti com muitas enfermidades, com enfermidade de tuas entranhas, até que as entranhas saiam de ti por causa da enfermidade de cada dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Então despertou o SENHOR contra Jeorão o espírito dos filisteus, e dos árabes que estavam junto aos etíopes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'E subiram contra Judá, e invadiram a terra, e tomaram toda a riqueza que acharam na casa do rei, e a seus filhos, e a suas mulheres; que não lhe restou filho, a não ser Jeoacaz o menor de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Depois de tudo isto o SENHOR o feriu nas entranhas de uma enfermidade incurável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'E aconteceu que, passando um dia atrás outro, ao fim, ao fim de dois anos, as entranhas se lhe saíram com a enfermidade, morrendo assim de enfermidade muito penosa. E seu povo não fez queima em homenagem a ele, como haviam feito a seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Quando começou a reinar era de trinta e dois anos, e reinou em Jerusalém oito anos; e se foi sem deixar saudades. E sepultaram-no na cidade de Davi, mas não nos sepulcros dos reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'E os moradores de Jerusalém fizeram rei em lugar seu a Acazias seu filho menor: porque a tropa havia vindo com os árabes ao campo, havia morto a todos os maiores; por o qual reinou Acazias, filho de Jeorão rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Quando Acazias começou a reinar era de quarenta e dois anos, e reinou um ano em Jerusalém. O nome de sua mãe foi Atalia, filha de Onri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Também ele andou nos caminhos da casa de Acabe: porque sua mãe lhe aconselhava a agir impiamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Fez, pois, o que era mau aos olhos do SENHOR, como a casa de Acabe; porque depois da morte de seu pai, eles lhe aconselharam para sua perdição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'E ele andou nos conselhos deles, e foi à guerra com Jeorão filho de Acabe, rei de Israel, contra Hazael rei da Síria, a Ramote de Gileade, de onde os sírios feriram a Jeorão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'E se voltou para curar-se em Jezreel das feridas que lhe haviam feito em Ramá, lutando com Hazael rei da Síria. E desceu Azarias filho de Jeorão, rei de Judá, a visitar a Jeorão filho de Acabe, em Jezreel, porque ali estava enfermo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Isto, porém, vinha de Deus, para que Acazias fosse abatido vindo a Jeorão: porque sendo vindo, saiu com Jeorão contra Jeú filho de Ninsi, ao qual o SENHOR havia ungido para que exterminasse a casa de Acabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'E foi que, fazendo juízo Jeú com a casa de Acabe, achou aos príncipes de Judá, e aos filhos dos irmãos de Acazias, que serviam a Acazias, e matou-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'E buscando a Acazias, o qual se havia escondido em Samaria, tomaram-no, e trouxeram-no a Jeú, e lhe mataram; e deram-lhe sepultura, porque disseram: É filho de Josafá, o qual buscou ao SENHOR de todo seu coração. E a casa de Acazias não tinha forças para para manter o reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Então Atalia mãe de Acazias, vendo que seu filho era morto, levantou-se e destruiu toda a descendência real da casa de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Porém Jeosebate, filha do rei, tomou a Joás filho de Acazias, e tirou-o dentre os filhos do rei, que foram mortos, e guardou a ele e a sua ama na câmara dos leitos. Assim pois o escondeu Jeosebate, filha do rei Jeorão, mulher de Joiada o sacerdote, (porque ela era irmã de Acazias), de diante de Atalia, e não o mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'E esteve com eles escondido na casa de Deus seis anos. Entretanto Atalia reinava no país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Mas no sétimo ano se animou Joiada, e tomou consigo em aliança aos comandantes de cem, Azarias filho de Jeroão, e a Ismael filho de Joanã, e a Azarias filho de Obede, e a Maaseias filho de Adaías, e a Elisafate filho de Zicri;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Os quais rodeando por Judá, juntaram os levitas de todas as cidades de Judá, e aos príncipes das famílias de Israel, e vieram a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'E toda a multidão fez aliança com o rei na casa de Deus. E ele lhes disse: Eis que o filho do rei, o qual reinará, como o SENHOR o tem dito dos filhos de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'O que haveis de fazer é: a terceira parte de vós, os que entram de semana, estarão de porteiros com os sacerdotes e os levitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'E a terceira parte, à casa do rei; e a terceira parte, à porta do fundamento: e todo o povo estará nos pátios da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'E ninguém entre na casa do SENHOR, a não ser os sacerdotes e levitas que servem: estes entrarão, porque estão consagrados; e todo o povo fará a guarda do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'E os levitas rodearão ao rei por todas as partes, e cada um terá suas armas na mão; e qualquer um que entrar na casa, morra: e estareis com o rei quando entrar, e quando sair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'E os levitas e todo Judá o fizeram tudo como o havia mandado o sacerdote Joiada: e tomou cada um os seus, os que entravam de semana, e os que saíam o sábado: porque o sacerdote Joiada não deu licença às companhias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Deu também o sacerdote Joiada aos comandantes de cem as lanças, paveses e escudos que haviam sido do rei Davi, que estavam na casa de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'E pôs em ordem a todo o povo, tendo cada um sua espada na mão, desde o canto direito do templo até o esquerdo, até o altar e a casa, em derredor do rei por todas as partes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Então tiraram ao filho do rei, e puseram-lhe a coroa e o testemunho, e fizeram-lhe rei; e Joiada e seus filhos lhe ungiram, dizendo logo: Viva o rei!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'E quando Atalia ouviu o estrondo da gente que corria, e dos que bendiziam ao rei, veio ao povo à casa do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'E olhando, viu ao rei que estava junto a sua coluna à entrada, e os príncipes e os trombetas junto ao rei, e que todo o povo da terra fazia alegrias, e soavam buzinas, e cantavam com instrumentos de música os que sabiam louvar. Então Atalia rasgou seus vestidos, e disse: Traição! Traição!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'E tirando o sacerdote Joiada os comandantes de cem e capitães do exército, disse-lhes: Tirai-a fora do recinto; e o que a seguir, morra à espada: porque o sacerdote havia mandado que não a matassem na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Eles, pois, a detiveram, e logo que havia ela passado a entrada da porta dos cavalos da casa do rei, ali a mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'E Joiada fez pacto entre si e todo o povo e o rei, que seriam povo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Depois disto entrou todo o povo no templo de Baal, e derrubaram-no, e também seus altares; e fizeram pedaços suas imagens, e mataram diante dos altares a Matã, sacerdote de Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Logo ordenou Joiada os ofícios na casa do SENHOR sob a mão dos sacerdotes e levitas, segundo Davi os havia distribuído na casa do SENHOR, para oferecer ao SENHOR os holocaustos, como está escrito na lei de Moisés, com alegria e cantares, conforme a ordenação de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Pôs também porteiros às portas da casa do SENHOR, para que por nenhuma via entrasse nenhum imundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Tomou depois os comandantes de cem, e os principais, e os que governavam o povo; e a todo o povo da terra, e levou ao rei da casa do SENHOR; e vindo até o meio da porta maior da casa do rei, assentaram ao rei sobre o trono do reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'E todo o povo do país fez alegrias: e a cidade esteve quieta, depois de terem matado Atalia à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'De sete anos era Joás quando começou a reinar, e quarenta anos reinou em Jerusalém. O nome de sua mãe foi Zíbia, de Berseba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'E fez Joás o que era correto aos olhos do SENHOR todos os dias de Joiada o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'E tomou para ele Joiada duas mulheres; e gerou filhos e filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Depois disto aconteceu que Joás teve vontade de reparar a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'E juntou os sacerdotes e os levitas, e disse-lhes: Saí pelas cidades de Judá, e juntai dinheiro de todo Israel, para que cada ano seja reparada a casa de vosso Deus; e vós ponde diligência no negócio. Mas os levitas não puseram diligência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Por isso o rei chamou a Joiada o principal, e disse-lhe: Por que não procuraste que os levitas tragam de Judá e de Jerusalém ao tabernáculo do testemunho, a oferta que impôs Moisés servo do SENHOR, e da congregação de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Porque a ímpia Atalia e seus filhos haviam destruído a casa de Deus, e ademais haviam gastado nos ídolos todas as coisas consagradas à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Mandou, pois, o rei que fizessem uma arca, a qual puseram fora à porta da casa do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'E fizeram apregoar em Judá e em Jerusalém, que trouxessem ao SENHOR a oferta que Moisés servo de Deus havia imposto a Israel no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'E todos os príncipes e todo o povo se alegraram: e traziam, e lançavam no arca até enchê-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'E quando vinha o tempo para levar a arca ao magistrado do rei por mão dos levitas, quando viam que havia muito dinheiro, vinha o escriba do rei, e o que estava posto pelo sumo sacerdote, e levavam a arca, e esvaziavam-na, e traziam-na de volta a seu lugar; e assim o faziam a cada dia, e recolhiam muito dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'O qual dava o rei e Joiada aos que faziam a obra do serviço da casa do SENHOR, e tomavam pedreiros e oficiais que reparassem a casa do SENHOR, e ferreiros e artesãos de metal para compor a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Faziam, pois, os oficiais a obra, e por suas mãos foi a obra restaurada, e restituíram a casa de Deus a sua condição, e a consolidaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'E quando houveram acabado, trouxeram o que restava do dinheiro ao rei e a Joiada, e fizeram dele vasos para a casa do SENHOR, vasos para o serviço, utensílios para os sacrifícios, colheres, vasos de ouro e de prata. E sacrificavam holocaustos continuamente na casa do SENHOR todos os dias de Joiada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Mas Joiada envelheceu, e morreu farto de dias: de cento e trinta anos era quando morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'E sepultaram-no na cidade de Davi com os reis, porquanto havia feito bem com Israel, e para com Deus, e com sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Depois de Joiada ter morrido, vieram os príncipes de Judá, e fizeram reverência ao rei; e o rei os ouviu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'E abandonaram a casa do SENHOR o Deus de seus pais, e serviram aos bosques e às imagens esculpidas; e a ira veio sobre Judá e Jerusalém por este seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'E enviou-lhes profetas, para que os reconduzissem ao SENHOR, os quais lhes protestaram: mas eles não os escutaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'E o espírito de Deus investiu a Zacarias, filho de Joiada o sacerdote, o qual estando sobre o povo, lhes disse: Assim disse Deus: Por que quebrantais os mandamentos do SENHOR? Não vos virá bem disso; porque por haver deixado ao SENHOR, ele também vos deixará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mas eles fizeram conspiração contra ele, e cobriram-lhe de pedras por mandado do rei, no pátio da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Não teve, pois, memória o rei Joás da misericórdia que seu pai Joiada havia feito com ele, antes matou-lhe seu filho; o qual disse ao morrer: o SENHOR o veja, e o exija.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'À volta do ano subiu contra ele o exército da Síria; e vieram a Judá e a Jerusalém, e destruíram no povo a todos os principais dele, e enviaram todos seus despojos ao rei a Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Porque ainda que o exército da Síria houvesse vindo com pouca gente, o SENHOR lhes entregou em suas mãos um exército muito numeroso; porquanto haviam deixado ao SENHOR o Deus de seus pais. E com Joás fizeram juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'E indo-se dele os sírios, deixaram-no em muitas enfermidades; e conspiraram contra ele seus servos a causa dos sangues dos filhos de Joiada o sacerdote, e feriram-lhe em sua cama, e morreu: e sepultaram-lhe na cidade de Davi, mas não o sepultaram nos sepulcros dos reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Os que conspiraram contra ele foram Zabade, filho de Simeate amonita, e Jozabade, filho de Sin moabita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'De seus filhos, e da multiplicação que fez das rendas, e da restauração da casa do SENHOR, eis que está escrito na história do livro dos reis. E reinou em seu lugar Amazias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'De vinte e cinco anos era Amazias quando começou a reinar, e vinte e nove anos reinou em Jerusalém: o nome de sua mãe foi Jeoadã, de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Fez ele o que era correto aos olhos do SENHOR ainda que não de coração íntegro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'E logo que foi confirmado no reino, matou os seus servos que haviam matado o seu pai, o rei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mas não matou aos filhos deles, segundo o que está escrito na lei no livro de Moisés, de onde o SENHOR mandou, dizendo: Não morrerão os pais pelos filhos, nem os filhos pelos pais; mas cada um morrerá por seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Juntou logo Amazias a Judá, e com arranjo às famílias pôs-lhes capitães de milhares e comandantes de cem por todo Judá e Benjamim; e tomou-os por lista de vinte anos acima, e foram achados neles trezentos mil escolhidos para sair à guerra, que tinham lança e escudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'E de Israel contratou a dinheiro cem mil homens valentes, por cem talentos de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Mas um homem de Deus veio a ele, dizendo-lhe: Rei, não vá contigo o exército de Israel; porque o SENHOR não é com Israel, nem com todos os filhos de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Porém se tu vais, se o fazes, e te esforças para lutar, Deus te fará cair diante dos inimigos; porque em Deus está a força, ou para ajudar, ou para derrubar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'E Amazias disse ao homem de Deus: Que, pois, se fará de cem talentos que dei ao exército de Israel? E o homem de Deus respondeu: Do SENHOR é dar-te muito mais que isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Então Amazias separou o esquadrão da gente que havia vindo a ele de Efraim, para que se fossem a suas casas: e eles se iraram grandemente contra Judá, e voltaram a suas casas encolerizados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Esforçando-se então Amazias, tirou seu povo, e veio ao vale do sal: e feriu dos filhos de Seir dez mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'E os filhos de Judá tomaram vivos outros dez mil, os quais levaram ao cume de um penhasco, e dali os atiraram abaixo, e todos se fizeram em pedaços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Porém os do esquadrão que Amazias havia despedido, porque não fossem com ele à guerra, derramaram-se sobre as cidades de Judá, desde Samaria até Bete-Horom, e feriram deles três mil, e tomaram um grande despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Regressando logo Amasias da matança dos edomitas, trouxe também consigo os deuses dos filhos de Seir, e os pôs para si por deuses, e encurvou-se diante deles, e queimou-lhes incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Acendeu-se, portanto, o furor do SENHOR contra Amasias, e enviou a ele um profeta, que lhe disse: Por que buscaste os deuses de gente estrangeira, que não livraram a seu povo de tuas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'E falando-lhe o profeta estas coisas, ele lhe respondeu: Puseram a ti por conselheiro do rei? Deixa-te disso: por que queres que te matem? E ao cessar, o profeta disse logo: Eu sei que Deus decidiu destruir-te, porque fizeste isto, e não obedeceste a meu conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'E Amazias rei de Judá, havido seu conselho, enviou a dizer a Joás, filho de Jeoacaz filho de Jeú, rei de Israel: Vem, e vejamo-nos face a face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Então Joás rei de Israel enviou a dizer a Amazias rei de Judá: O cardo que estava no Líbano, enviou ao cedro que estava no Líbano, dizendo: Da tua filha a meu filho por mulher. E eis que os animais selvagens que estavam no Líbano, passaram, e pisotearam o cardo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Tu dizes: Eis que feri a Edom; e teu coração se enaltece para gloriar-te: agora fica-te em tua casa; para que te intrometes em mal, para cair tu e Judá contigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mas Amasias não quis ouvir; porque isto era da parte de Deus, que queria os entregar nas mãos de seus inimigos, porquanto haviam buscado os deuses de Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Subiu, pois, Joás rei de Israel, e vieram face a face ele e Amazias rei de Judá, em Bete-Semes, a qual é de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Porém caiu Judá diante de Israel, e fugiu cada um a sua morada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'E Joás rei de Israel prendeu em Bete-Semes a Amazias rei de Judá, filho de Joás filho de Jeoacaz, e levou-o a Jerusalém: e derrubou o muro de Jerusalém desde a porta de Efraim até a porta da esquina, quatrocentos côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Assim tomou todo o ouro e prata, e todos os vasos que se acharam na casa de Deus em casa de Obede-Edom, e os tesouros da casa do rei, e os filhos dos príncipes, e voltou-se a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'E viveu Amazias filho de Joás, rei de Judá, quinze anos depois da morte de Joás filho de Jeoacaz rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Os demais dos feitos de Amazias, primeiros e últimos, não estão escritos no livro dos reis de Judá e de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Desde aquele tempo que Amazias se separou do SENHOR, maquinaram contra ele conspiração em Jerusalém; e havendo ele fugido a Laquis, enviaram atrás ele a Laquis, e ali o mataram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'E trouxeram-no em cavalos, e sepultaram-no com seus pais na cidade de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Então todo o povo de Judá tomou a Uzias, o qual era de dezesseis anos, e puseram-no por rei em lugar de Amazias seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Edificou ele a Elote, e a restituiu a Judá depois que o rei descansou com seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'De dezesseis anos era Uzias quando começou a reinar, e cinquenta e dois anos reinou em Jerusalém. O nome de sua mãe foi Jecolias, de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'E fez o que era correto aos olhos do SENHOR, conforme a todas as coisas que havia feito Amazias seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'E persistiu em buscar a Deus nos dias de Zacarias, entendido em visões de Deus; e nos dias que ele buscou ao SENHOR, ele lhe prosperou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'E saiu, e lutou contra os filisteus, e rompeu o muro de Gate, e o muro de Jabné, e o muro de Asdode; e edificou cidades em Asdode, e na terra dos filisteus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'E deu-lhe Deus ajuda contra os filisteus, e contra os árabes que habitavam em Gur-Baal, e contra os amonitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'E deram os amonitas presentes a Uzias, e divulgou-se seu nome até a entrada do Egito; porque se havia feito altamente poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Edificou também Uzias torres em Jerusalém, junto à porta do ângulo, e junto à porta do vale, e junto às esquinas; e fortificou-as.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Assim edificou torres no deserto, e abriu muitas cisternas: porque teve muitos gados, assim nos vales como nas planícies; e vinhas, e lavouras, assim nos montes como nos campos férteis; porque era amigo da agricultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Teve também Uzias esquadrões de guerreiros, os quais saíam à guerra em exército, segundo que estavam por lista feita por mão de Jeiel escriba e de Maaseias governador, e por mão de Hananias, um dos príncipes do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Todo o número dos chefes de famílias, valentes e esforçados, era dois mil e seiscentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'E sob a mão destes estava o exército de guerra, de trezentos sete mil e quinhentos guerreiros poderosos e fortes para ajudar ao rei contra os inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'E preparou-lhes Uzias para todo o exército, escudos, lanças, capacetes, couraças, arcos, e fundas de tirar pedras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'E fez em Jerusalém máquinas por artifício de peritos, para que estivessem nas torres e nos baluartes, para lançar setas e grandes pedras, e sua fama se estendeu longe, porque se ajudou maravilhosamente, até fazer-se forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mas quando foi fortificado, seu coração se enalteceu até corromper-se; porque se rebelou contra o SENHOR seu Deus, entrando no templo do SENHOR para queimar incenso no altar do incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'E entrou atrás dele o sacerdote Azarias, e com ele oitenta sacerdotes do SENHOR, dos valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'E puseram-se contra o rei Uzias, e disseram-lhe: Não a ti, ó Uzias, o queimar incenso ao SENHOR, mas sim aos sacerdotes filhos de Arão, que são consagrados para queimá-lo: sai do santuário, por que pecaste, e não te será para glória diante do SENHOR Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'E irou-se Uzias, que tinha o incenso na mão para queimá-lo; e em esta sua ira contra os sacerdotes, a lepra lhe surgiu na testa diante dos sacerdotes na casa do SENHOR, junto ao altar do incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'E olhou-lhe Azarias o sumo sacerdote, e todos os sacerdotes, e eis que a lepra estava em sua testa; e fizeram-lhe sair apressadamente daquele lugar; e ele também se deu pressa a sair, porque o SENHOR o havia ferido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Assim o rei Uzias foi leproso até o dia de sua morte, e habitou em uma casa separada, leproso, pelo que havia sido separado da casa do SENHOR; e Jotão seu filho teve cargo da casa real, governando ao povo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Os demais dos feitos de Uzias, primeiros e últimos, escreveu-os Isaías profeta, filho de Amoz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'E descansou Uzias com seus pais, e sepultaram-no com seus pais no campo dos sepulcros reais; porque disseram: Leproso é. E seu filho Jotão reinou Jotão em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'De vinte e cinco anos era Jotão quando começou a reinar, e dezesseis anos reinou em Jerusalém. O nome de sua mãe foi Jerusa, filha de Zadoque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'E fez o que era correto em olhos do SENHOR, conforme a todas as coisas que havia feito Uzias seu pai, salvo que não entrou no templo do SENHOR. E o povo corrompia-se ainda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Edificou ele a porta maior da casa do SENHOR, e no muro da fortaleza edificou muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Ademais edificou cidades nas montanhas de Judá, e preparou palácios e torres nos bosques.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Também teve ele guerra com o rei dos filhos de Amom, aos quais venceu; e deram-lhe os filhos de Amom naquele ano cem talentos de prata, e dez mil coros de trigo, e dez mil de cevada. Isto lhe deram os filhos de Amom, e o mesmo no segundo ano, e no terceiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Assim que Jotão foi fortificado, porque preparou seus caminhos diante do SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Os demais dos feitos de Jotão, e todas suas guerras, e seus caminhos, eis que estão escrito no livro dos reis de Israel e de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Quando começou a reinar era de vinte e cinco anos, e dezesseis reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'E descansou Jotão com seus pais, e sepultaram-no na cidade de Davi; e reinou em seu lugar Acaz seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'De vinte anos era Acaz quando começou a reinar, e dezesseis anos reinou em Jerusalém: mas não fez o que era correto aos olhos do SENHOR, como Davi seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Antes andou nos caminhos dos reis de Israel, e ademais fez imagens de fundição aos baalins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Queimou também incenso no vale dos filhos de Hinom, e queimou seus filhos por fogo, conforme as abominações das nações que o SENHOR havia lançado diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Assim sacrificou e queimou incenso nos altos, e nas colinas, e debaixo de toda árvores espessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Pelo qual o SENHOR seu Deus o entregou em mãos do rei dos sírios, os quais lhe derrotaram, e tomaram dele uma grande presa, que levaram a Damasco. Foi também entregue em mãos do rei de Israel, o qual o derrotou com grande mortandade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Porque Peca, filho de Remalias matou em Judá em um dia cento e vinte mil, todos eles homens valentes; porquanto haviam deixado ao SENHOR o Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Assim Zicri, homem poderoso de Efraim, matou a Maaseias filho do rei, e a Azricão seu mordomo, e a Elcana, segundo depois do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Tomaram também cativos os filhos de Israel de seus irmãos duzentos mil, mulheres, meninos, e meninas, a mais de haver saqueado deles um grande despojo, o qual trouxeram a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Havia então ali um profeta do SENHOR, que se chamava Obede, o qual saiu diante do exército quando entrava em Samaria, e disse-lhes: Eis que o SENHOR o Deus de vossos pais, pela ira contra Judá, os entregou em vossas mãos; e vós os');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'E agora haveis determinado sujeitar a vós a Judá e a Jerusalém por servos e servas: mas não haveis vós pecado contra o SENHOR vosso Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Ouvi-me, pois, agora, e voltai a enviar os cativos que haveis tomado de vossos irmãos: porque o SENHOR está irado contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Levantaram-se então alguns homens dos principais dos filhos de Efraim, Azarias filho de Joanã, e Berequias filho de Mesilemote, e Jeizquias filho de Salum, e Amasa filho de Hadlai, contra os que vinham da guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'E disseram-lhes: Não metais aqui os cativos; porque o pecado contra o SENHOR será sobre nós. Vós tratais de acrescentar sobre nossos pecados e sobre nossas culpas, sendo suficientemente grande nosso delito, e a ira do furor sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Então o exército deixou os cativos e a presa diante dos príncipes e de toda a multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'E levantaram-se os homens nomeados, e tomaram os cativos, e vestiram do despojo aos que deles estavam nus; vestiram-nos e calçaram-nos, e deram-lhes de comer e de beber, e ungiram-nos, e conduziram em asnos a todos os fracos, e levaram-nos até Jericó, cidade das palmeiras, próxima de seus irmãos; e eles voltaram a Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Naquele tempo enviou a pedir o rei Acaz aos reis de Assíria que lhe ajudassem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Porque a mais disto, os edomitas haviam vindo e ferido aos de Judá, e haviam levado cativos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Assim os filisteus haviam invadido as cidades da planície, e ao sul de Judá, e haviam tomado a Bete-Semes, a Aijalom, Gederote, e Socó com suas aldeias, Timna também com suas aldeias, e Ginzo com suas aldeias; e habitavam nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Porque o SENHOR havia humilhado a Judá por causa de Acaz rei de Israel: porquanto ele havia desnudado a Judá, e rebelado-se gravemente contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'E veio contra ele Tiglate-Pileser, rei dos assírios: pois o oprimiu, e não o fortificou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Ainda que Acaz tenha despojado a casa do SENHOR, e a casa real, e as dos príncipes, para dar ao rei dos assírios, contudo isso ele não lhe ajudou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Ademais o rei Acaz no tempo que aquele lhe afligia-se, acrescentou transgressão contra o SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Porque sacrificou aos deuses de Damasco que lhe haviam ferido, e disse: Pois que os deuses dos reis da Síria lhes ajudam, eu também sacrificarei a eles para que me ajudem; bem que foram estes sua ruína, e a de todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'A mais disso recolheu Acaz os vasos da casa de Deus, e quebrou-os, e fechou as portas da casa do SENHOR, e fez-se altares em Jerusalém em todos os cantos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Fez também altos em todas as cidades de Judá, para queimar incenso aos deuses alheios, provocando assim a ira ao SENHOR o Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Os demais de seus feitos, e todos seus caminhos, primeiros e últimos, eis que estão escrito no livro dos reis de Judá e de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'E descansou Acaz com seus pais, e sepultaram-no na cidade de Jerusalém: mas não lhe meteram nos sepulcros dos reis de Israel; e reinou em seu lugar Ezequias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'E Ezequias começou a reinar sendo de vinte e cinco anos, e reinou vinte e nove anos em Jerusalém. O nome de sua mãe foi Abia, filha de Zacarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'E fez o que era correto aos olhos do SENHOR, conforme a todas as coisas que havia feito Davi seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'No primeiro ano de seu reinado, no mês primeiro, abriu as portas da casa do SENHOR, e as reparou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'E fez vir os sacerdotes e levitas, e juntou-os na praça oriental.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'E disse-lhes: Ouvi-me, levitas, e santificai-vos agora, e santificareis a casa do SENHOR o Deus de vossos pais, e tirareis do santuário a imundícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Porque nossos pais se rebelaram, e fizeram o que era mau aos olhos do SENHOR nosso Deus; que lhe deixaram, e apartaram seus olhos do tabernáculo do SENHOR, e lhe voltaram as costas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'E ainda fecharam as portas do pórtico, e apagaram as lâmpadas; não queimaram incenso, nem sacrificaram holocausto no santuário ao Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Portanto a ira do SENHOR veio sobre Judá e Jerusalém, e os entregou à aflição, ao espanto, e ao escárnio, como vedes vós com vossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'E eis que nossos pais caíram à espada, nossos filhos e nossas filhas e nossas mulheres estão em cativeiro por isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Agora, pois, eu determinei fazer aliança com o SENHOR o Deus de Israel, para que afaste de nós a ira de seu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Filhos meus, não vos enganeis agora, porque o SENHOR vos escolheu para que estejais diante dele, e lhe sirvais, e sejais seus ministros, e lhe queimeis incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Então os levitas se levantaram, Maate filho de Amasai, e Joel filho de Azarias, dos filhos de Coate; e dos filhos de Merari, Quis filho de Abdi, e Azarias filho de Jealelel; e dos filhos de Gérson, Joá filho de Zima, e Éden filho de Joá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'E dos filhos de Elisafã, Sinri e Jeuel; e dos filhos de Asafe, Zacarias e Matanias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'E dos filhos de Hemã, Jeiel e Simei; e dos filhos de Jedutum, Semaías e Uziel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Estes juntaram a seus irmãos, e santificaram-se, e entraram, conforme ao mandamento do rei e as palavras do SENHOR, para limpar a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'E entrando os sacerdotes dentro da casa do SENHOR para limpá-la, tiraram toda a imundícia que acharam no templo do SENHOR, ao átrio da casa do SENHOR; a qual tomaram os levitas, para tirá-la fora ao ribeiro de Cedrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'E começaram a santificar o primeiro do mês primeiro, e aos oito do mesmo mês vieram ao pórtico do SENHOR: e santificaram a casa do SENHOR em oito dias, e no dezesseis do mês primeiro acabaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Logo passaram ao rei Ezequias e disseram-lhe: Já limpamos toda a casa do SENHOR, o altar do holocausto, e todos seus instrumentos, e a mesa da proposição com todos seus utensílios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Assim preparamos e santificamos todos os vasos que em sua transgressão havia descartado o rei Acaz, quando reinava: e eis que estão diante do altar do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'E levantando-se de manhã o rei Ezequias reuniu os principais da cidade, e subiu à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'E apresentaram sete novilhos, sete carneiros, sete cordeiros, e sete bodes, para expiação pelo reino, pelo santuário e por Judá. E disse aos sacerdotes filhos de Arão, que os oferecessem sobre o altar do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Mataram, pois, os bois, e os sacerdotes tomaram a sangue, e espargiram-na sobre o altar; mataram logo os carneiros, e espargiram o sangue sobre o altar; também mataram os cordeiros, e espargiram o sangue sobre o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Fizeram depois chegar os bodes da expiação diante do rei e da multidão, e puseram sobre eles suas mãos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'E os sacerdotes os mataram, e expiando espargiram o sangue deles sobre o altar, para reconciliar a todo Israel: porque por todo Israel mandou o rei fazer o holocausto e a expiação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Pôs também levitas na casa do SENHOR com címbalos, e saltérios, e harpas, conforme ao mandamento de Davi, e de Gade vidente do rei, e de Natã profeta: porque aquele mandamento foi por mão do SENHOR, por meio de seus profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'E os levitas estavam com os instrumentos de Davi, e os sacerdotes com trombetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Então mandou Ezequias sacrificar o holocausto no altar; e ao tempo que começou o holocausto, começou também o cântico do SENHOR, com as trombetas e os instrumentos de Davi rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'E toda a multidão adorava, e os cantores cantavam, e os trombetas soavam as trombetas; tudo até acabar-se o holocausto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'E quando acabaram de oferecer, inclinou-se o rei, e todos os que com ele estavam, e adoraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Então o rei Ezequias e os príncipes disseram aos levitas que louvassem ao SENHOR pelas palavras de Davi e de Asafe vidente: e eles louvaram com grande alegria, e inclinando-se adoraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'E respondendo Ezequias disse: Vós vos haveis consagrado agora ao SENHOR; achegai-vos pois, e apresentai sacrifícios e louvores na casa do SENHOR. E a multidão apresentou sacrifícios e louvores; e todo generoso de coração, holocaustos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'E foi o número dos holocaustos que trouxe a congregação, setenta bois, cem carneiros, duzentos cordeiros; tudo para o holocausto do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'E as ofertas foram seiscentos bois, e três mil ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Mas os sacerdotes eram poucos, e não podiam o suficiente a tirar o couro dos holocaustos; e assim seus irmãos os levitas lhes ajudaram até que acabaram a obra, e até que os sacerdotes se santificaram: porque os levitas tiveram maior prontidão de coração para se santificarem que os sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Assim, pois, havia grande abundância de holocaustos, com gorduras de ofertas pacíficas, e libações de cada holocausto. E ficou ordenado o serviço da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'E alegrou-se Ezequias, e todo o povo, de que Deus houvesse preparado o povo; porque a coisa foi prontamente feita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Enviou também Ezequias por todo Israel e Judá, e escreveu cartas a Efraim e Manassés, que viessem a Jerusalém à casa do SENHOR, para celebrar a páscoa ao SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'E havia o rei tomado conselho com seus príncipes, e com toda a congregação em Jerusalém, para celebrar a páscoa no mês segundo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Porque então não a podiam celebrar, porquanto não havia suficientes sacerdotes santificados, nem o povo estava junto em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Isto agradou ao rei e a toda a multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'E determinaram fazer apregoar por todo Israel, desde Berseba até Dã, para que viessem a celebrar a páscoa ao SENHOR Deus de Israel, em Jerusalém: porque em muito tempo não a haviam celebrado ao modo que está escrito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Foram, pois, mensageiros com cartas da mão do rei e de seus príncipes por todo Israel e Judá, como o rei o havia mandado, e diziam: Filhos de Israel, voltai-vos ao SENHOR o Deus de Abraão, de Isaque, e de Israel, e ele se voltará aos restantes que vos escaparam das mãos dos reis da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Não sejais como vossos pais e como vossos irmãos, que se rebelaram contra o SENHOR o Deus de seus pais, e ele os entregou a desolação, como vós vedes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Não endureçais, pois, agora vossa cerviz como vossos pais: dai a mão ao SENHOR, e vinde a seu santuário, o qual ele santificou para sempre; e servi ao SENHOR vosso Deus, e a ira de seu furor se apartará de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Porque se vos virardes ao SENHOR, vossos irmãos e vossos filhos acharão misericórdia diante dos que os têm cativos, e voltarão a esta terra: porque o SENHOR vosso Deus é clemente e misericordioso, e não desviará de vós seu rosto, se vós vos converterdes a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Passaram, pois, os mensageiros de cidade em cidade pela terra de Efraim e Manassés, até Zebulom: mas se riam e ridicularizavam deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Com tudo isso, alguns homens de Aser, de Manassés, e de Zebulom, se humilharam, e vieram a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Em Judá também foi a mão de Deus para dar-lhes um coração para cumprir a mensagem do rei e dos príncipes, conforme à palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'E juntou-se em Jerusalém muito gente para celebrar a solenidade dos pães ázimos no mês segundo; uma vasta reunião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'E levantando-se, tiraram os altares que havia em Jerusalém; tiraram também todos os altares de incenso, e lançaram-nos no ribeiro de Cedrom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Então sacrificaram a páscoa, aos catorze do mês segundo; e os sacerdotes e os levitas se santificaram com vergonha, e trouxeram os holocaustos à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'E puseram-se em sua ordem conforme a seu costume, conforme à lei de Moisés homem de Deus; os sacerdotes espargiam o sangue que recebiam de mãos dos levitas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Porque havia muitos na congregação que não estavam santificados, e por isso os levitas sacrificavam a páscoa por todos os que não se haviam limpado, para santificá-los ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Porque uma grande multidão do povo de Efraim e Manassés, e de Issacar e Zebulom, não se haviam purificado, e comeram a páscoa não conforme a o que está escrito. Mas Ezequias orou por eles, dizendo: SENHOR, que é bom, seja propício a todo aquele que preparou seu coração para buscar a Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Ao SENHOR, o Deus de seus pais, ainda que não esteja purificado segundo a purificação do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'E ouviu o SENHOR a Ezequias, e sarou o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Assim celebraram os filhos de Israel que se acharam em Jerusalém, a solenidade dos pães sem levedura por sete dias com grande alegria: e louvavam ao SENHOR todos os dias os levitas e os sacerdotes, cantando com instrumentos de força ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'E falou Ezequias ao coração de todos os levitas que tinham boa inteligência no serviço do SENHOR. E comeram do sacrificado na solenidade por sete dias, oferecendo sacrifícios pacíficos, e dando graças ao SENHOR o Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'E toda aquela multidão determinou que celebrassem outros sete dias; e celebraram outros sete dias com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Porque Ezequias rei de Judá havia dado à multidão mil novilhos e sete mil ovelhas; e também os príncipes deram ao povo mil novilhos e dez mil ovelhas: e muitos sacerdotes se santificaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Alegrou-se, pois, toda a congregação de Judá, como também os sacerdotes e levitas, e toda a multidão que havia vindo de Israel; assim os estrangeiros que haviam vindo da terra de Israel, e os que habitavam em Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'E fizeram-se grandes alegrias em Jerusalém: porque desde os dias de Salomão filho de Davi rei de Israel, não havia havido coisa tal em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Levantando-se depois os sacerdotes e levitas, bendisseram ao povo: e a voz deles foi ouvida, e sua oração chegou à habitação de seu santuário, ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Feitas todas estas coisas, todos os de Israel que se haviam achado ali, saíram pelas cidades de Judá, e quebraram as estátuas e destruíram os bosques, e derrubaram os altos e os altares por todo Judá e Benjamim, e também em Efraim e Manassés,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'E definiu Ezequias as repartições dos sacerdotes e dos levitas conforme a suas ordens, cada um segundo seu ofício, os sacerdotes e os levitas para o holocausto e pacíficos, para que ministrassem, para que confessassem e louvassem às portas dos acampamentos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'A contribuição do rei de sua riqueza era holocaustos a manhã e tarde, e holocaustos para os sábados, novas luas, e solenidades, como está escrito na lei do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Mandou também ao povo que habitava em Jerusalém, que dessem a porção aos sacerdotes e levitas, para que se esforçassem na lei do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'E quando este edito foi divulgado, os filhos de Israel deram muitas primícias de grão, vinho, azeite, mel, e de todos os frutos da terra: trouxeram também os dízimos de todas as coisas em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Também os filhos de Israel e de Judá, que habitavam nas cidades de Judá, deram do mesmo modo os dízimos das vacas e das ovelhas: e trouxeram os dízimos do santificado, das coisas que haviam prometido ao SENHOR seu Deus, e puseram-nos por amontoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'No mês terceiro começaram a fundar aqueles amontoados, e no mês sétimo acabaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'E Ezequias e os príncipes vieram a ver os amontoados, e bendisseram ao SENHOR, e a seu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'E perguntou Ezequias aos sacerdotes e aos levitas acerca dos amontoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'E respondeu-lhe Azarias, sumo sacerdote, da casa de Zadoque, e disse: Desde que começaram a trazer a oferta à casa do SENHOR, comemos e nos saciamos, e nos sobrou muito: porque o SENHOR abençoou seu povo, e restou esta abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Então mandou Ezequias que preparassem câmaras na casa do SENHOR; e prepararam-nas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'E puseram as primícias e dízimos e as coisas consagradas, fielmente; e deram cargo disso a Conanias levita, o principal, e Simei seu irmão foi o segundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'E Jeiel, Azazias, Naate, Asael, Jeremote, Jozabade, Eliel, Ismaquias, Maate, e Benaia, foram capatazes sob a mão de Conanias e de Simei seu irmão, por mandamento do rei Ezequias e de Azarias, príncipe da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'E Coré filho de Imná levita, porteiro ao oriente, tinha cargo dos donativos de Deus, e das ofertas do SENHOR que se davam, e de tudo o que se santificava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'E a sua mão estava Éden, Benjamim, Jesua, Semaías, Amarias, e Secanias, nas cidades dos sacerdotes, para dar com fidelidade a seus irmãos suas partes conforme a suas ordens, assim ao maior como ao menor:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'A mais dos homens anotados por suas linhagens, de três anos acima, a todos os que entravam na casa do SENHOR, sua porção diária por seu ministério, segundo seus ofícios e classes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Também aos que eram contados entre os sacerdotes pelas famílias de seus pais, e aos levitas de idade de vinte anos acima, conforme a seus ofícios e ordens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Assim aos de sua geração com todos seus meninos, e suas mulheres, e seus filhos e filhas, a toda a família; porque com fidelidade se consagravam às coisas santas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Do mesmo modo em ordem aos filhos de Arão, sacerdotes, que estavam nos campos de suas cidades, por todas as cidades, os homens nomeados tinham cargo de dar suas porções a todos os homens dos sacerdotes, e a toda a linhagem dos levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'De esta maneira fez Ezequias em todo Judá: e executou o que era bom, correto, e verdadeiro, diante do SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Em tudo quanto começou no serviço da casa de Deus, e na lei e mandamentos, buscou a seu Deus, e o fez de todo coração, e foi próspero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Depois destas coisas e desta fidelidade, veio Senaqueribe rei dos assírios, entrou em Judá, e assentou campo contra as cidades fortes, e determinou de entrar nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Vendo, pois, Ezequias a vinda de Senaqueribe, e seu aspecto de combater a Jerusalém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Teve seu conselho com seus príncipes e com seus valentes, sobre fechar as fontes das águas que estavam fora da cidade; e eles lhe apoiaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Juntou-se, pois, muito povo, e fecharam todas as fontes, e o ribeiro que derrama por em meio do território, dizendo: Por que devem achar os reis de Assíria muitas águas quando vierem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Encorajou-se assim Ezequias, e edificou todos os muros caídos, e fez erguer as torres, e outro muro por de fora: fortificou também a Milo na cidade de Davi, e fez muitas espadas e paveses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'E pôs capitães de guerra sobre o povo, e os fez reunir assim na praça da porta da cidade, e falou ao coração deles, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Esforçai-vos e confortai-vos; não temais, nem tenhais medo do rei da Assíria, nem de toda sua multidão que com ele vem; porque mais são com nós que com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Com ele está a força da carne, mas conosco está o SENHOR nosso Deus para ajudar-nos, e lutar nossas batalhas. E firmou-se o povo sobre as palavras de Ezequias rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Depois disto Senaqueribe rei dos assírios, estando ele sobre Laquis e com ele toda sua potência, enviou seus servos a Jerusalém, para dizer a Ezequias rei de Judá, e a todos os de Judá que estavam em Jerusalém:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Assim disse Senaqueribe rei dos assírios: Em quem confiais vós para estar cercados em Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Não vos engana Ezequias para entregar-vos à morte, à fome, e à sede, dizendo: o SENHOR nosso Deus nos livrará da mão do rei da Assíria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Não é Ezequias o que tirou seus altos e seus altares, e disse a Judá e a Jerusalém: Diante somente deste altar adorareis, e sobre ele queimareis incenso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Não sabeis o que eu e meus pais fizemos a todos os povos da terra? Puderam os deuses das nações das terras livrar sua terra de minha mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Que deus havia de todos os deuses daquelas nações que destruíram meus pais, que pudesse salvar seu povo de minhas mãos? Por que poderá vosso Deus livrar-vos de minha mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Agora, pois, não vos engane Ezequias, nem vos persuada tal coisa, nem lhe creiais; que se nenhum deus de todas aquelas nações e reinos pode livrar seu povo de meus mãos, e das mãos de meus pais, quanto menos vosso Deus vos poderá livrar de minha mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'E outras coisas falaram seus servos contra o Deus o SENHOR, e contra seu servo Ezequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Além de tudo isto escreveu cartas em que blasfemava ao SENHOR o Deus de Israel, e falava contra ele, dizendo: Como os deuses das nações dos países não puderam livrar seu povo de minhas mãos, tampouco o Deus de Ezequias livrará ao seu das minhas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'E clamaram a grande voz em judaico ao povo de Jerusalém que estava nos muros, para espantá-los e pôr-lhes temor, para tomar a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'E falaram contra o Deus de Jerusalém, como contra os deuses dos povos da terra, obra de mãos de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Mas o rei Ezequias, e o profeta Isaías filho de Amoz, oraram por isto, e clamaram ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'E o SENHOR enviou um anjo, o qual feriu a todo valente e esforçado, e aos chefes e capitães no campo do rei da Assíria. Voltou-se, portanto, com vergonha de rosto a sua terra; e entrando no templo de seu deus, ali o mataram à espada os que haviam saído de suas entranhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Assim salvou o SENHOR a Ezequias e aos moradores de Jerusalém das mãos de Senaqueribe rei da Assíria, e das mãos de todos: e preservou-os de todas as partes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'E muitos trouxeram oferta ao SENHOR a Jerusalém, e a Ezequias rei de Judá, ricos presentes; e foi muito grande diante de todas as nações depois disto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Naquele tempo Ezequias enfermou de morte: e orou ao SENHOR, o qual lhe respondeu, e deu-lhe um sinal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mas Ezequias não pagou conforme ao bem que lhe havia sido feito: antes se enalteceu seu coração, e foi a ira contra ele, e contra Judá e Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Porém Ezequias, depois de haver-se orgulhado seu coração, se humilhou, ele e os moradores de Jerusalém; e não veio sobre eles a ira do SENHOR nos dias de Ezequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'E teve Ezequias riquezas e glória muito em grande maneira; e fez-se de tesouros de prata e ouro, de pedras preciosas, de aromas, de escudos, e de todas as joias valiosas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Também depósitos para as rendas do grão, do vinho, e azeite; estábulos para toda sorte de animais, e currais para os gados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Fez para si também cidades, e rebanhos de ovelhas e de vacas em grande quantidade; porque Deus lhe havia dado muito riqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Este Ezequias tapou os mananciais das águas de Giom a de acima, e encaminhou-as abaixo ao ocidente da cidade de Davi. E foi próspero Ezequias em tudo o que fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Porém no dos embaixadores dos príncipes de Babilônia, que enviaram a ele para saber do prodígio que havia acontecido naquela terra, Deus o deixou, para provar-lhe, para fazer conhecer tudo o que estava em seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Os demais dos feitos de Ezequias, e de suas misericórdias, eis que tudo está escrito na profecia de Isaías profeta, filho de Amoz, no livro dos reis de Judá e de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'E descansou Ezequias com seus pais, e sepultaram-no na parte superior dos sepulcros dos filhos de Davi, honrando-lhe em sua morte todo Judá e os de Jerusalém: e reinou em seu lugar Manassés seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'De doze anos era Manassés quando começou a reinar, e cinquenta e cinco anos reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Mas fez o que era mau em olhos do SENHOR, conforme as abominações das nações que havia lançado o SENHOR diante dos filhos de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Porque ele reedificou os altos que Ezequias seu pai havia derrubado, e levantou altares aos baalins, e fez bosques, e adorou a todo o exército dos céus, e a ele serviu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Edificou também altares na casa do SENHOR, da qual havia dito o SENHOR: Em Jerusalém será meu nome perpetuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Edificou assim altares a todo o exército dos céus nos dois átrios da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'E passou seus filhos por fogo no vale dos filhos de Hinom; e olhava adivinhações, predições supersticiosas, e feitiçarias, e consultava médiuns e interpretadores de espíritos; ele fez muito mal aos olhos do SENHOR, para irritar-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'A mais disto pôs uma imagem de fundição, que fez, na casa de Deus, da qual havia dito Deus a Davi e a Salomão seu filho: Nesta casa e em Jerusalém, a qual eu escolhi sobre todas as tribos de Israel, porei meu nome para sempre:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'E nunca mais tirarei o pé de Israel da terra que eu entreguei a vossos pais, a condição que guardem e façam todas as coisas que eu lhes ei mandado, toda a lei, estatutos, e ordenanças, por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Fez, pois, Manassés desviar-se a Judá e aos moradores de Jerusalém, para fazer mais mal que as nações que o SENHOR destruiu diante dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'E falou o SENHOR a Manassés e a seu povo, mas eles não escutaram:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Por isso o SENHOR trouxe contra eles os generais do exército do rei dos assírios, os quais aprisionaram com grilhões a Manassés, e acorrentado com correntes levaram-no a Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Mas logo que foi posto em angústias, orou ante o SENHOR seu Deus, humilhado grandemente na presença do Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'E havendo a ele orado, foi atendido; pois que ouviu sua oração, e voltou-o a Jerusalém, a seu reino. Então conheceu Manassés que o SENHOR era Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Depois disto edificou o muro de fora da cidade de Davi, ao ocidente de Giom, no vale, à entrada da porta do peixe, e cercou a Ofel, e levantou-o muito alto; e pôs capitães de exército em todas as cidades fortes por Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Também tirou os deuses alheios, e o ídolo da casa do SENHOR, e todos os altares que havia edificado no monte da casa do SENHOR e em Jerusalém, e lançou-os fora da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Reparou logo o altar do SENHOR, e sacrificou sobre ele sacrifícios pacíficos e de louvor; e mandou a Judá que servissem ao SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Porém o povo ainda sacrificava nos altos, ainda que somente ao SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Os demais dos feitos de Manassés, e sua oração a seu Deus, e as palavras dos videntes que lhe falaram em nome do SENHOR o Deus de Israel, eis que tudo está escrito nos feitos dos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Sua oração também, e como foi ouvido, todos seus pecados, e sua transgressão, os lugares de onde edificou altos e havia posto bosques e ídolos antes que se humilhasse, eis que estas coisas estão escritas nas palavras dos videntes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'E descansou Manassés com seus pais, e sepultaram-no em sua casa: e reinou em seu lugar Amom seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'De vinte e dois anos era Amom quando começou a reinar, e dois anos reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'E fez o que era mau em olhos do SENHOR, como havia feito Manassés seu pai: porque a todos os ídolos que seu pai Manassés havia feito, sacrificou e serviu Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Mas nunca se humilhou diante do SENHOR, como se humilhou Manassés seu pai: antes aumentou o pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'E conspiraram contra ele seus servos, e mataram-no em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Mas o povo da terra feriu a todos os que haviam conspirado contra o rei Amom; e o povo da terra pôs por rei em seu lugar a Josias seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'De oito anos era Josias quando começou a reinar, e trinta e um anos reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Este fez o que era correto aos olhos do SENHOR, e andou nos caminhos de Davi seu pai, sem desviar-se à direita nem à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'A os oito anos de seu reinado, sendo ainda jovem, começou a buscar ao Deus de Davi seu pai; e aos doze anos começou a limpar a Judá e a Jerusalém dos altos, bosques, esculturas, e imagens de fundição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'E derrubaram diante dele os altares dos baalins, e fez pedaços as imagens do sol, que estavam postas encima; despedaçou também os bosques, e as esculturas e estátuas de fundição, e esmigalhou-as, e dispersou o pó sobre os sepulcros dos que a elas haviam sacrificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Queimou ademais os ossos dos sacerdotes sobre seus altares, e limpou a Judá e a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'O mesmo fez nas cidades de Manassés, Efraim, e Simeão, até em Naftali, com seus lugares assolados ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'E quando havia derrubado os altares e os bosques, e quebrado e esmigalhado as esculturas, e destruído todos os ídolos por toda a terra de Israel, voltou-se a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Aos dezoito anos de seu reinado, depois de haver limpado a terra, e a casa, enviou a Safã filho de Azalias, e a Maaseias governador da cidade, e a Joá filho de Jeoacaz, chanceler, para que reparassem a casa do SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Os quais vieram a Hilquias, grande sacerdote, e deram o dinheiro que havia sido posto na casa do SENHOR, que os levitas que guardavam a porta haviam recolhido da mão de Manassés e de Efraim e de todas as restantes de Israel, e de todo Judá e Benjamim, havendo depois voltado a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'E entregaram-no em mão dos que faziam a obra, que eram capatazes na casa do SENHOR; os quais o davam aos que faziam a obra e trabalhavam na casa do SENHOR, para reparar e restaurar o templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Davam também aos oficiais e pedreiros para que comprassem pedra lavrada, e madeira para as juntas, e para cobertura das casas, as quais haviam destruído os reis de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'E estes homens procediam com fidelidade na obra: e eram seus governadores Jaate e Obadias, levitas dos filhos de Merari; e Zacarias e Mesulão dos filhos de Coate, para que ativassem a obra; e dos levitas, todos os entendidos em instrumentos musicais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Também supervisionavam sobre os operários, e eram capatazes dos que se ocupavam em qualquer classe de obra; e dos levitas havia escribas, governadores, e porteiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'E ao tirar o dinheiro que havia sido posto na casa do SENHOR, Hilquias o sacerdote achou o livro da lei do SENHOR dada por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'E dando conta Hilquias, disse a Safã escriba: Eu ei achado o livro da lei na casa do SENHOR. E deu Hilquias o livro a Safã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'E Safã o levou ao rei, e contou-lhe o negócio, dizendo: Teus servos cumpriram tudo o que lhes foi encarregado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Reuniram o dinheiro que se achou na casa do SENHOR, e o entregaram em mão dos comissionados, e em mão dos que fazem a obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'A mais disto, declarou Safã escriba ao rei, dizendo: O sacerdote Hilquias me deu um livro. E leu Safã nele diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'E logo que o rei ouviu as palavras da lei, rasgou suas vestes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'E mandou a Hilquias e a Aicã filho de Safã, e a Abdom filho de Mica, e a Safã escriba, e a Asaías servo do rei, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Andai, e consultai ao SENHOR de mim, e dos restantes de Israel e de Judá, acerca das palavras do livro que se achou; porque grande é o furor do SENHOR que há caído sobre nós, porquanto nossos pais não guardaram a palavra do SENHOR, para fazer conforme tudo o que está escrito neste livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Então Hilquias e os do rei foram a Hulda profetisa, mulher de Salum, filho de Tocate, filho de Harás, guarda das vestimentas, a qual morava em Jerusalém na segunda parte da cidade e disseram-lhe as palavras ditas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'E ela respondeu: o SENHOR o Deus de Israel disse assim: Dizei ao homem que vos enviou a mim, que assim disse o SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Eis que eu trago mal sobre este lugar, e sobre os moradores dele, e todas as maldições que estão escritas no livro que leram diante do rei de Judá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Por quanto me deixaram, e sacrificaram a deuses alheios, provocando-me à ira em todas as obras de suas mãos; portanto meu furor destilará sobre este lugar, e não se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Mas ao rei de Judá, que vos enviou a consultar ao SENHOR, assim lhe direis: o SENHOR o Deus de Israel disse assim: Porquanto ouviste as palavras do livro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'E teu coração se enterneceu, e te humilhaste diante de Deus ao ouvir suas palavras sobre este lugar, e sobre seus moradores, e te humilhaste diante de mim, e rasgaste tuas vestes, e choraste em minha presença, eu também te ei ouvido, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Eis que eu te recolherei com teus pais, e serás recolhido em teus sepulcros em paz, e teus olhos não verão todo o mal que eu trago sobre este lugar, e sobre os moradores dele. E eles referiram ao rei a resposta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Então o rei enviou e juntou todos os anciãos de Judá e de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'E subiu o rei à casa do SENHOR, e com ele todos os homens de Judá, e os moradores de Jerusalém, e os sacerdotes, e os levitas, e todo o povo desde o maior até o menor; e leu a ouvidos deles todas as palavras do livro do pacto que havia sido achado na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'E estando o rei em pé em seu lugar, fez aliança diante do SENHOR de caminhar após o SENHOR, e de guardar seus mandamentos, seus testemunhos, e seus estatutos, de todo seu coração e de toda sua alma, praticando as palavras do pacto que estavam escritas naquele livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'E fez que se obrigassem a ele todos os que estavam em Jerusalém e em Benjamim: e os moradores de Jerusalém fizeram conforme ao pacto de Deus, do Deus de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'E tirou Josias todas as abominações de todas as terras dos filhos de Israel, e fez a todos os que se acharam em Israel servirem ao SENHOR seu Deus. Não se desviaram de seguir o SENHOR o Deus de seus pais, todo o tempo que ele viveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'E Josias fez páscoa ao SENHOR em Jerusalém, e sacrificaram a páscoa aos catorze do mês primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'E pôs aos sacerdotes em seus empregos, e confirmou-os no ministério da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'E disse aos levitas que ensinavam a todo Israel, e que estavam dedicados ao SENHOR: Ponde a arca do santuário na casa que edificou Salomão filho de Davi, rei de Israel, para que não a carregueis mais sobre os ombros. Agora servireis ao SENHOR vosso Deus, e a seu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Preparai-vos segundo as famílias de vossos pais, por vossas ordens, conforme à prescrição de Davi rei de Israel, e de Salomão seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Ficai no santuário segundo a distribuição das famílias de vossos irmãos os filhos do povo, e segundo a divisão da família dos levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Sacrificai logo a páscoa: e depois de santificar-vos, preparai a vossos irmãos, para que façam conforme à palavra do SENHOR dada por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'E ofereceu o rei Josias aos do povo ovelhas, cordeiros, e cabritos dos rebanhos, em número de trinta mil, e três mil bois, tudo para a páscoa, para todos os que se acharam presentes: isto da riqueza do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Também seus príncipes ofereceram com generosidade ao povo, e aos sacerdotes e levitas. Hilquias, Zacarias e Jeiel, príncipes da casa de Deus, deram aos sacerdotes para fazer a páscoa duas mil seiscentas ovelhas, e trezentos bois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Também Conanias, e Semaías e Natanael seus irmãos, e Hasabias, Jeiel, e Jozabade, príncipes dos levitas, deram aos levitas para os sacrifícios da páscoa cinco mil ovelhas, e quinhentos bois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Prontificado assim o serviço, os sacerdotes se colocaram em seus postos, e também os levitas em suas ordens, conforme ao mandamento do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'E sacrificaram a páscoa; e espargiam os sacerdotes o sangue tomado da mão dos levitas, e os levitas tiravam os couros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Tomaram logo do holocausto, para dar conforme as repartições pelas famílias dos do povo, a fim de que oferecessem ao SENHOR, segundo está escrito no livro de Moisés: e também tomaram dos bois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'E assaram a páscoa ao fogo segundo o rito: mas o que havia sido santificado o cozinharam em panelas, em caldeiras, e caldeirões, e repartiram o prontamente a todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'E depois prepararam para si e para os sacerdotes; porque os sacerdotes, filhos de Arão, estiveram ocupados até a noite no sacrifício dos holocaustos e das gorduras; portanto, os levitas prepararam para si, e para os sacerdotes filhos de Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Também os cantores filhos de Asafe estavam em seu posto, conforme ao mandamento de Davi, de Asafe e de Hemã, e de Jedutum vidente do rei; também os porteiros estavam a cada porta; e não era necessário que se afastassem de seu ministério, porque seus irmãos, os levitas, preparavam para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Assim foi aprontei todo o serviço do SENHOR naquele dia, para fazer a páscoa, e sacrificar os holocaustos sobre o altar do SENHOR, conforme ao mandamento do rei Josias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'E os filhos de Israel que se acharam ali, fizeram a páscoa naquele tempo, e a solenidade dos pães sem levedura, por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Nunca tal páscoa foi feita em Israel desde os dias de Samuel o profeta; nem nenhum rei de Israel fez páscoa tal como a que fez o rei Josias, e os sacerdotes e levitas, e todo Judá e Israel, os que se acharam ali, juntamente com os moradores de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Esta páscoa foi celebrada no ano dezoito do rei Josias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Depois de todas estas coisas, logo de haver Josias preparado a casa, Neco rei do Egito subiu a fazer guerra em Carquêmis junto a Eufrates; e saiu Josias contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'E ele lhe enviou embaixadores, dizendo: Que temos eu e tu, rei de Judá? Eu não venho contra ti hoje, mas sim contra a casa que me faz guerra: e Deus disse que me apressasse. Deixa-te de intrometer-te com Deus, que é comigo, não te destrua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mas Josias não voltou seu rosto dele, em vez disso disfarçou-se para dar-lhe batalha, e não atendeu às palavras de Neco, que eram da boca de Deus; e veio a dar-lhe a batalha no campo de Megido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'E os arqueiros atiraram ao rei Josias flechas; e disse o rei a seus servos: Tirai-me daqui, porque estou ferido gravemente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Então seus servos o tiraram daquele carro, e puseram-lhe em outro segundo carro que tinha, e levaram-lhe a Jerusalém, e morreu; e sepultaram-lhe nos sepulcros de seus pais. E todo Judá e Jerusalém fez luto por Josias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'E lamentou Jeremias por Josias, e todos os cantores e cantoras recitam suas lamentações sobre Josias até hoje; e as deram por norma para lamentar em Israel, as quais estão escritas nas Lamentações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Os demais dos feitos de Josias, e suas piedosas obras, conforme o que está escrito na lei do SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'E seus feitos, primeiros e últimos, eis que estão escritos no livro dos reis de Israel e de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Então o povo da terra tomou a Jeoacaz filho de Josias, e fizeram-lhe rei em lugar de seu pai em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'De vinte e três anos era Jeoacaz quando começou a reinar, e três meses reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'E o rei do Egito o tirou de Jerusalém, e condenou a terra em cem talentos de prata e um de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'E o rei do Egito constituiu o seu irmão Eliaquim como rei sobre Judá e Jerusalém, e mudou-lhe o nome em Jeoaquim; e Neco tomou o seu irmão Jeoacaz, e o levou ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Quando começou a reinar Jeoaquim era de vinte e cinco anos, e reinou onze anos em Jerusalém: e fez o que era mau aos olhos do SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'E subiu contra ele Nabucodonosor rei da Babilônia, e acorrentado com correntes o levou à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Também levou Nabucodonosor à Babilônia dos utensílios da casa do SENHOR, e os pôs no seu templo em Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Os demais dos feitos de Jeoaquim, e as abominações que fez, e o que nele se achou, eis que estão escritos no livro dos reis de Israel e de Judá: e reinou em seu lugar Joaquim seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'De oito anos era Joaquim quando começou a reinar, e reinou três meses e dez dias em Jerusalém: e fez o que era mau aos olhos do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Na primavera do ano, o rei Nabucodonosor mandou que o trouxessem à Babilônia, juntamente com os utensílos preciosos da casa do SENHOR; e constituiu o seu irmão Zedequias como rei sobre Judá e Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'De vinte e um anos era Zedequias quando começou a reinar, e onze anos reinou em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'E fez o que era mau aos olhos do SENHOR seu Deus, e não se humilhou diante do profeta Jeremias, que lhe falava da parte do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Rebelou-se também contra Nabucodonosor, ao qual havia jurado por Deus; e endureceu sua cerviz, e obstinou seu coração, para não voltar-se ao SENHOR o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'E também todos os príncipes dos sacerdotes, e o povo, aumentaram a transgressão, seguindo todas as abominações das nações, e contaminando a casa do SENHOR, a qual ele havia santificado em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'E o SENHOR o Deus de seus pais enviou a eles por meio de seus mensageiros, enviando insistentemente: porque ele tinha misericórdia de seu povo, e de sua habitação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mas eles faziam escárnio dos mensageiros de Deus, e menosprezavam suas palavras, ridicularizando-se de seus profetas, até que subiu o furor do SENHOR contra seu povo, de maneira que não havia remédio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Pelo qual trouxe contra eles ao rei dos caldeus, que matou à espada seus rapazes na casa de seu santuário, sem perdoar jovem, nem virgem, nem velho, nem decrépito; todos os entregou em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Também todos os vasos da casa de Deus, grandes e pequenos, os tesouros da casa do SENHOR, e os tesouros do rei e de seus príncipes, tudo o levou à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'E queimaram a casa de Deus, e romperam o muro de Jerusalém, e consumiram ao fogo todos seus palácios, e destruíram todos os seus objetos valiosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Os que restaram da espada foram passados à Babilônia; e foram servos dele e de seus filhos, até que veio o reino dos persas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Para que se cumprisse a palavra do SENHOR pela boca de Jeremias, até que a terra houvesse aproveitado os seus descansos sabáticos; pois durante todo o tempo de sua ruina ela descansou, até que os setenta anos fossem cumpridos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Mas ao primeiro ano de Ciro rei dos persas, para que se cumprisse a palavra do SENHOR por boca de Jeremias, o SENHOR induziu o espírito de Ciro rei dos persas, o qual fez apregoar por todo seu reino, e também por escrito, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Assim diz Ciro rei dos persas: o SENHOR, o Deus dos céus, me deu todos os reinos da terra; e ele me encarregou que lhe edifique casa em Jerusalém, que é em Judá. Quem houver de vós de todo seu povo, o SENHOR seu Deus seja com o tal, e suba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'No primeiro ano de Ciro rei da Pérsia, para que se cumprisse a palavra do SENHOR pela boca de Jeremias, o SENHOR despertou o espírito de Ciro rei da Pérsia, o qual mandou proclamar por todo o seu reino, e também por escrito, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Assim diz Ciro, rei da Pérsia: O SENHOR, Deus dos céus, me deu todos os reinos da terra; e ele me mandou que lhe edificasse uma casa em Jerusalém, que está em Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Quem há entre vós de todo seu povo, seu Deus seja com ele, e suba a Jerusalém que está em Judá, e edifique a casa ao SENHOR Deus de Israel; ele é o Deus que habita em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'E todo aquele que tiver restado em qualquer lugar onde estiver morando, os homens de seu lugar o ajudem com prata, ouro, bens, e animais; além das doações voluntárias para a casa de Deus, que está em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Então se levantaram os chefes das famílias de Judá e de Benjamim, os sacerdotes e os Levitas, e todos aqueles cujo espírito Deus despertou, para subirem a edificar a casa do SENHOR, que está em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'E todos os que estavam em seus arredores fortaleceram suas mãos com objetos de prata e de ouro, com bens e animais, e com coisas preciosas, além de tudo o que foi dado voluntariamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Também o rei Ciro tirou os utensílios da casa do SENHOR, que Nabucodonosor tinha trazido de Jerusalém, e posto na casa de seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'E Ciro, rei da Pérsia, tirou-os por meio do tesoureiro Mitridate, o qual os deu contados a Sesbazar, príncipe de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'E esta é o seu número: trinta bacias de ouro, mil bacias de prata, vinte e nove facas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Trinta taças de ouro, quatrocentas e dez taças de prata, e mil outros utensílios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Todos os utensílios de ouro e de prata foram cinco mil e quatrocentos. Sesbazar trouxe todos estes com os do cativeiro que subiram da Babilônia a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Estes são os filhos da província que subiram do cativeiro, dos transportados que Nabucodonosor, rei de Babilônia, tinha transportado para a Babilônia, e que voltaram a Jerusalém e a Judá, cada um para sua cidade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Os quais vieram com Zorobabel, Jesuá, Neemias, Seraías, Reelaías, Mardoqueu, Bilsã, Mispar, Bigvai, Reum e Baaná. O registro dos homens do povo de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Os filhos de Parós, dois mil cento e setenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Os filhos de Sefatias, trezentos e setenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Os filhos de Ara, setecentos e setenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Os filhos de Paate-Moabe, dos filhos de Jesuá-Joabe, dois mil oitocentos e doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Os filhos de Elão, mil duzentos e cinquenta e quatro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Os filhos de Zatu, novecentos e quarenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Os filhos de Zacai, setecentos e sessenta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Os filhos de Bani, seiscentos e quarenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Os filhos de Bebai, seiscentos e vinte e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Os filhos de Azgade, mil duzentos e vinte e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Os filhos de Adonicão, seiscentos e sessenta e seis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Os filhos de Bigvai, dois mil e cinquenta e seis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Os filhos de Adim, quatrocentos e cinquenta e quatro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Os filhos de Ater, de Ezequias, noventa e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Os filhos de Bezai, trezentos e vinte e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Os filhos de Jora, cento e doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Os filhos de Hasum, duzentos e vinte e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Os filhos de Gibar, noventa e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Os filhos de Belém, cento e vinte e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Os homens de Netofá, cinquenta e seis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Os homens de Anatote, cento e vinte e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Os filhos de Azmavete, quarenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Os filhos de Quiriate-Jearim, Quefira, e Beerote, setecentos e quarenta e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Os filhos de Ramá e Geba, seiscentos e vinte e um;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Os homens de Micmás, cento e vinte e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Os homens de Betel e Ai, duzentos e vinte e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Os filhos de Nebo, cinquenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Os filhos de Magbis, cento e cinquenta e seis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Os filhos do outro Elão, mil duzentos e cinquenta e quatro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Os filhos de Harim, trezentos e vinte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Os filhos de Lode, Hadide, e Ono, setecentos e vinte e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Os filhos de de Jericó, trezentos e quarenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Os filhos de Senaá, três mil seiscentos e trinta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Os sacerdotes: os filhos de Jedaías, da casa de Jesuá, novecentos e setenta e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Os filhos de Imer, mil e cinquenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Os filhos de Pasur, mil duzentos e quarenta e sete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Os filhos de Harim, mil e dezessete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Os Levitas: os filhos de Jesuá e de Cadmiel, dos filhos de Hodavias, setenta e quatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Os cantores: os filhos de Asafe, cento e vinte e oito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Os filhos dos porteiros: os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai; ao todo, cento e trinta e nove.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Os servos do templo: os filhos de Zia, os filhos de Hasufa, os filhos de Tabaote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Os filhos de Queros, os filhos de Sia, os filhos de Padom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Os filhos de Lebana, os filhos de Hagaba, os filhos de Acube;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Os filhos de Hagabe, os filhos de Sanlai, os filhos de Hanã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Os filhos de Gidel, os filhos de Gaar, os filhos de Reaías;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Os filhos de Rezim, os filhos de Necoda, os filhos de Gazão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Os filhos de Uzá, os filhos de Paseia, os filhos de Besai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Os filhos de Asná, os filhos de Meunim, os filhos de Nefusim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Os filhos de Baquebuque, os filhos de Hacufa, os filhos de Harur;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Os filhos de Baslute, os filhos de Meída, os filhos de Harsa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Os filhos de Barcos, os filhos de Sísera, os filhos de Temá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Os filhos de Nesias, os filhos de Hatifa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Os filhos dos servos de Salomão: os filhos de Sotai, os filhos de Soferete, os filhos de Peruda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Os filhos de Jaala, o filhos de Darcom, os filhos de Gidel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Os filhos de Sefatias, os filhos de Hatil, os filhos de Poquerete-Hazebaim, os filhos de Ami.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Todos os servos do templo, e filhos dos servos de Salomão, trezentos e noventa e dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Também estes subiram de Tel-Melá, Tel-Harsa, Querube, Adã, e Imer, porém não puderam mostrar a família de seus pais, nem sua linhagem, se eram de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Os filhos de Delaías, os filhos de Tobias, os filhos de Necoda, seiscentos e cinquenta e dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'E dos filhos dos sacerdotes: os filhos de Habaías, os filhos de Coz, os filhos de Barzilai, o qual tomou mulher das filhas de Barzilai gileadita, e foi chamado pelo nome delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Estes buscaram seu registro de genealogias, mas não foi achado; por isso foram rejeitados do sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'E o governador lhes mandou que não comessem das coisas sagradas, até que houvesse sacerdote com Urim e Tumim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Toda esta congregação junta foi quarenta e dois mil trezentos e sessenta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Sem seus servos e servas, os quais foram sete mil trezentos trinta e sete; também tinham duzentos cantores e cantoras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Seus cavalos foram setecentos e trinta e seis; seus mulos, duzentos e quarenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Seus camelos, quatrocentos trinta e cinco; asnos, seis mil setecentos e vinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'E alguns dos chefes de famílias, quando vieram à casa do SENHOR que estava em Jerusalém, deram ofertas voluntárias para a casa de Deus, para a reconstruírem em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Conforme sua capacidade deram ao tesouro da obra sessenta e uma mil dracmas de ouro, cinco mil libras de prata, e cem vestes sacerdotais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'E os sacerdotes, os Levitas, os do povo, os cantores, os porteiros e os servos do templo, habitaram em suas cidades; como também todo Israel em suas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Tendo, pois, chegado o mês sétimo, e já estando os filhos de Israel nas cidades, o povo se ajuntou como um só homem em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'E levantaram-se Jesuá filho de Jozadaque, e seus irmãos os sacerdotes, e Zorobabel filho de Sealtiel, e seus irmãos, e edificaram o altar do Deus de Israel, para oferecerem sobre ele ofertas de queima, como está escrito na Lei de Moisés, homem de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'E assentaram o altar sobre suas bases, porém com medo sobre si, por causa dos povos das terras; e ofereceram sobre ele ofertas de queima ao SENHOR, ofertas de queima à manhã e à tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'E celebraram a festa dos tabernáculos, como está escrito; fizeram ofertas de queima diariamente conforme a regra exigida a cada dia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'E depois disto, fizeram a oferta de queima contínua, e as das luas novas, e todas as festas santificadas ao SENHOR, como também de qualquer um que dava oferta voluntária ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Desde o primeiro dia do mês sétimo começaram a apresentar ofertas de queima ao SENHOR; porém ainda não estavam postos os fundamentos do templo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Assim deram dinheiro aos pedreiros e carpinteiros; como também comida, bebida, e azeite aos sidônios e aos tírios, para que trazerem do Líbano madeira de cedro ao mar de Jope, conforme a autorização de Ciro, rei da Pérsia, acerca disto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'E no ano segundo de sua vinda à casa de Deus em Jerusalém, no mês segundo, começaram Zorobabel filho de Sealtiel, Jesuá filho de Jozadaque, com os outros irmãos seus, os sacerdotes e os levitas, e todos os que haviam vindo do cativeiro a Jerusalém. E ordenaram aos levitas da idade de vinte anos acima, que cuidassem da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Então Jesuá, seus filhos e seus irmãos, Cadmiel e seus filhos, filhos de Judá, se levantaram como um só homem para supervisionarem os que faziam a obra na casa de Deus; com os filhos de Henadade, seus filhos e seus irmãos, levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'E quando os construtores do templo do SENHOR puseram os fundamentos, então ordenaram aos sacerdotes, já com as vestimentas e com trombetas, e aos levitas filhos de Asafe com címbalos, para louvarem ao SENHOR, conforme a ordenança de Davi, rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'E cantavam em revezamento, louvando e celebrando ao SENHOR:Porque ele é bom, porque sua bondade sobre Israel dura para sempre!E todo o povo gritava com grande júbilo, louvando ao SENHOR, por causa da fundação da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Porém muitos dos sacerdotes e dos levitas e dos chefes de famílias, já velhos, que haviam visto a primeira casa, quando viram a fundação desta casa, choravam em alta voz, mas muitos outros davam grandes gritos de alegria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'De maneira que o povo não conseguia distinguir as vozes de alegria das vozes de choro do povo; porque o povo gritava com tão grande júbilo, que se podia ouvir o som de muito longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Quando, pois, os adversários de Judá e de Benjamim, ouviram que os que tinham vindo do cativeiro estavam edificando o templo ao SENHOR, Deus de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'chegaram-se a Zorobabel, e aos chefes das famílias, e lhes disseram: Deixai-nos edificar convosco, porque assim como vós, buscaremos ao vosso Deus, como também já sacrificamos a ele desde os dias de Esar-Hadom, rei da Assíria, que nos fez subir até aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Porém Zorobabel, e Jesuá, e os demais chefes das famílias de Israel lhes disseram:Não nos convém edificar convosco casa a nosso Deus; mas somente nós a edificaremos ao SENHOR, Deus de Israel, como nos mandou o rei Ciro, rei da Pérsia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Todavia o povo da terra desencorajava o povo de Judá, e os perturbava, para que não edificassem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'E subornaram contra eles conselheiros para frustrarem sua intenção, todos os dias de Ciro rei da Pérsia, e até o reinado de Dario, rei da Pérsia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'E sob o reinado de Assuero, no princípio de seu reinado, escreveram uma acusação contra os moradores de Judá e de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'E nos dias de Artaxerxes, Bislão, Mitridate, Tabeel, e os demais seus companheiros, escreveram a Artaxerxes rei da Pérsia; e o escrito da carta estava feito em siríaco, e composto em siríaco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Reum o comandante, e Sinsai o escrivão, escreveram uma carta contra Jerusalém ao rei Artaxerxes, conforme o seguinte:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Reum, o comandante, e Sinsai secretário, e os demais seus companheiros, os dinaítas, os arfasaquitas, tarpelitas, arfasitas, os arquevitas, os babilônios, susanquitas, deavitas, e elamitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'E os demais povos que o grande e famoso Asnapar transportou, e fez habitar nas cidades de Samaria, e os demais da região dalém do rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Este é o teor da carta que enviaram: Ao rei Artaxerxes. De teus servos dalém do rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Seja conhecido do rei que os judeus que subiram de ti a nós, vieram a Jerusalém; e edificam aquela cidade rebelde e má, e estão restaurando seus muros; e reparado seus fundamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Seja agora conhecido do rei, que se aquela cidade for reconstruída, e os muros forem restaurados, os tributos, taxas, e impostos não serão pagos, e o patrimônio real será prejudicado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Visto que somos assalariados pelo palácio, não nos convém ver a desonra do rei; por isso mandamos informar ao rei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Para que se busque no livro das crônicas de teus pais; e acharás no livro das crônicas, e saberás que aquela cidade foi uma cidade rebelde, prejudicial aos reis e às províncias, e que nela desde antigamente fizeram rebeliões; por isso aquela cidade foi arruinada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Por isso informamos ao rei que, se aquela cidade for reconstruída, e seus muros restaurados, a parte além do rio não será tua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Então o rei enviou esta resposta a Reum, o comandante, e a Sinsai, o escrivão, e aos demais de seus companheiros que habitam em Samaria, como também aos demais da parte além do rio: Paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'A carta que nos enviastes foi lida claramente diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'E eu dei ordem para que se buscasse; e encontraram que aquela cidade na antiguidade se levantou contra os reis, e nela houve rebelião e insurreição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'E que houve reis poderosos em Jerusalém, dominaram toda a região além do rio; e a eles se pagava tributos, taxas e impostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Agora, pois, dai ordem que impeçam aqueles homens, e aquela cidade não seja reconstruída, até que seja dado mandamento de minha parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'E sede cuidadosos para que não falheis nisto; por que haveria de aumentar o dano para o prejuízo real?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Assim que o teor da carta do rei Artaxerxes foi lido diante de Reum, e de Sinsai o escrivão, e seus companheiros, eles foram apressadamente a Jerusalém aos judeus, e os impediram com força e violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Cessou, então, a obra da casa de Deus, a qual estava em Jerusalém; e cessou até o segundo ano do reinado de Dario, rei da Pérsia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'E o profeta Ageu, e Zacarias filho de Ido, profetas, profetizaram aos judeus que estavam em Judá e em Jerusalém, em nome do Deus de Israel, a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Então se levantaram Zorobabel filho de Sealtiel, e Jesuá filho de Jozadaque; e começaram a reconstruir a casa de Deus que está em Jerusalém; e com eles os profetas de Deus, que os ajudavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Naquele tempo veio a eles Tatenai, capitão da região além do rio, e Setar-Bozenai e seus companheiros, e lhes perguntaram assim:Quem vos deu ordem para reconstruir esta casa, e restaurar estes muros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Então assim lhes dissemos quais eram os nomes dos homens que reconstruíam este edifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Mas os olhos de seu Deus estavam sobre os anciãos dos judeus, e não os impediram, até que a causa viesse a Dario; e então responderam por carta sobre isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Teor da carta que Tatenai, o governador além do rio, e Setar-Bozenai, e seus companheiros os afarsaquitas, que estavam além do rio, enviaram ao rei Dario.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Enviaram-lhe uma carta, e assim estava escrito nela: Toda a paz ao rei Dario.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Seja conhecido do rei, que fomos à província de Judeia, à casa do grande Deus, a qual é edificada com grandes pedras; e a madeira é posta nas paredes, e a obra se faz apressadamente, e tem sido próspera a em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Então perguntamos aos anciãos, dizendo-lhes assim: Quem vos deu ordem para reconstruir esta casa, e para restaurar estes muros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'E também lhes perguntamos seus nomes para os informar a ti; para que pudéssemos escrever a ti os nomes dos homens que eram os seus líderes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'E nos deram esta resposta, dizendo: Nós somos servos de Deus do céu e da terra, e reconstruímos a casa que a muitos anos antes tinha sido construída, a qual um grande rei de Israel iniciou e terminou de construir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Mas depois que nossos pais provocaram à ira o Deus dos céus, ele os entregou nas mãos de Nabucodonosor, rei de Babilônia, o caldeu, o qual destruiu esta casa, e transportou o povo para a Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Porém no primeiro ano de Ciro, rei da Babilônia, o rei Ciro fez um decreto para reconstruir esta casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'E até os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tinha tomado do templo que estava em Jerusalém, e os tinha posto no templo da Babilônia, o rei Ciro os tirou do templo da Babilônia, e foram entregues a um chamado Sesbazar, a quem pusera por governador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'E disse-lhe: Toma estes utensílios, vai, e põe-os no templo que está em Jerusalém; e seja reconstruída a casa de Deus em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Então este Sesbazar veio, e pôs os fundamentos da casa de Deus, que está em Jerusalém, e desde então até agora foi reconstruída, e ainda não foi terminada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Agora, pois, se for do agrado do rei, busque-se na casa dos tesouros do rei que está ali na Babilônia, se é verdade que rei Ciro foi feito decreto para reconstruir esta casa de Deus em Jerusalém, e seja nos enviada a vontade do rei acerca disto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Então o rei Dario deu ordem, e buscaram nos arquivos da tesouraria na Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'E foi achado em Ecbatana, no palácio que está na província de Média, um livro, dentro do qual estava escrito assim: Memórial:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'No primeiro ano do rei Ciro, o rei Ciro fez decreto acerca da casa de Deus que estava em Jerusalém, que fosse reconstruído a casa, o lugar em que sejam oferecidos sacrifícios, e que suas paredes sejam cobertas; sua altura será de sessenta côvados, e sua largura de sessenta côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Com três camadas de grandes pedras, e uma camada de madeira nova e que o gasto seja dado da casa do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Além disso, os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tirou do templo que estava em Jerusalém e levou a Babilônia, sejam devolvidos para irem ao templo que está em Jerusalém, a seu lugar, e sejam postos na casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Agora, pois, Tatenai, chefe dalém rio, Setar-Bozenai, e seus companheiros os afarsaquitas que estais além do rio, afastai-vos dali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Deixai-os na obra da casa de Deus; que o governador dos judeus, e os anciãos dos judeus, edifiquem esta casa deste Deus em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Também por mim é promulgado decreto do que haveis de fazer com os anciãos destes judeus, para edificar a casa deste Deus: que do patrimônio do rei, dos tributos dalém do rio, sejam pagos os gastos destes homens varões, para que a obra não seja interrompida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'E o que for necessário, como bezerros, carneiros e cordeiros, para ofertas de queima ao Deus do céu, trigo, sal, vinho e azeite, conforme o que os sacerdotes que estão em Jerusalém disserem, seja lhes dado a cada sem falta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Para que ofereçam sacrifícios de aroma suave ao ao Deus dos céus, e orem pela vida do rei e de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Também é dada por mim ordem, que qualquer um que mudar este decreto, um madeiro de sua casa seja derrubado, levantado, e nele seja empalado; e sua casa se torne um amontoado por causa disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'E o Deus que fez habitar ali seu nome, derrube a todo rei e povo que estenderem sua mão para mudar ou destruir esta casa de Deus, que está em Jerusalém. Eu, Dario, fiz o decreto; apressadamente se cumpra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Então Tatenai, o governador dalém do rio, e Setar-Bozenai, e seus companheiros, assim fizeram apressadamente, conforme o que o rei Dario havia mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'E os anciãos dos judeus iam edificando e prosperando, pela profecia do profeta Ageu, e de Zacarias filho de Ido. E edificaram, e terminaram a construção conforme o mandamento do Deus de Israel, e conforme o mandamento de Ciro e de Dario, e de Artaxerxes rei da Pérsia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'E esta casa foi terminada ao terceiro dia do mês de Adar, que era o sexto ano do reinado do rei Dario.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'E os filhos de Israel, os sacerdotes e os levitas, e os demais dos que vieram do cativeiro, fizeram a consagração desta casa de Deus com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'E ofereceram para a consagração desta casa de Deus cem novilhos, duzentos carneiros, quatrocentos cordeiros; e doze cabritos por expiação do pecado de todo Israel, segundo o número das tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'E puseram aos sacerdotes em suas divisões, e aos levitas em seus grupos, para o serviço a Deus, que está em Jerusalém, conforme o que está escrito no livro de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'E os que vieram do cativeiro celebraram a páscoa aos catorze do mês primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Porque os sacerdotes e os levitas haviam se purificado juntos; todos foram limpos; e fizeram o sacrifício da páscoa por todos os que vieram do cativeiro, e por seus irmãos, os sacerdotes, e por si mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Assim os filhos de Israel que haviam voltado do cativeiro comeram, com todos os que tinham se separado da impureza das nações da terra, para buscarem ao SENHOR Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'E celebraram a festa dos pães sem fermento sete dias com alegria, porque o SENHOR os tinha alegrado, e convertido o coração do rei da Assíria a eles, para fortalecer suas mãos na obra da casa de Deus, o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Passadas estas coisas, no reinado de Artaxerxes, rei da Pérsia, Esdras, filho de Seraías, filho de Azarias, filho de Hilquias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'filho de Salum, filho de Zadoque, filho de Aitube,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'filho de Amarias, filho de Azarias, filho de Meraiote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'filho de Zeraías, filho de Uzi, filho de Buqui,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'filho de Abisua, filho de Fineias, filho de Eleazar, filho de Arão, o sumo sacerdote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'este Esdras subiu da Babilônia; e ele era escriba habilidoso na lei de Moisés, dada pelo SENHOR Deus de Israel; e segundo a mão do SENHOR, seu Deus, sobre ele, o rei lhe deu tudo quanto lhe pedira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'E subiram com ele a Jerusalém alguns dos filhos de Israel, dos sacerdotes, levitas, cantores, porteiros, e servos do templo, no sétimo ano do rei Artaxerxes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'E ele chegou a Jerusalém no mês quinto, no sétimo ano do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Pois no primeiro dia do mês primeiro, foi o princípio da subida da Babilônia; e ao primeiro do mês quinto chegou a Jerusalém, segundo a boa mão de seu Deus sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Porque Esdras tinha decidido em seu coração buscar a lei do SENHOR, e a praticar; e ensinar a Israel seus estatutos e juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'E este é a transcrição da carta que o rei Artaxerxes deu a Esdras, sacerdote e escriba, o escriba das palavras dos mandamentos do SENHOR, e de seus estatutos sobre Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artaxerxes, rei de reis, ao sacerdote Esdras, escriba da Lei de Deus do céu. Paz completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Por mim é promulgado decreto, que todo aquele em meu reino, do povo de Israel, e de seus sacerdotes e levitas, que quiser ir contigo a Jerusalém, vá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Porque de parte do rei e de seus sete conselheiros tu és enviado a investigar a respeito da de Judá e de Jerusalém, conforme a lei de teu Deus que está em tua mão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'E a levar a prata e o ouro que o rei e seus conselheiros voluntariamente deram ao Deus de Israel, cuja habitação está em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'E também toda a prata e o ouro que achares em toda a província de Babilônia, com as ofertas voluntárias do povo e dos sacerdotes, que voluntariamente oferecerem para a casa de seu Deus que está em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Portanto, com este dinheiro, compra novilhos, carneiros, cordeiros, com seus suas ofertas de alimento e suas ofertas de bebidas, e oferece-os sobre o altar da casa de vosso Deus, que está em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Também o que a ti e a teus irmãos parecer bem fazerdes do restante da prata e do ouro, fazei -o conforme a vontade de vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'E os utensílios que te foram entregues para o serviço da casa de teu Deus, restitui-os diante do Deus de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'E o demais que for necessário para a casa de teu Deus que caiba a ti dar, tu o darás da casa dos tesouros do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'E por mim mesmo, o rei Artaxerxes, é dado decreto a todos os tesoureiros que estão além do rio, que tudo quanto o sacerdote Esdras, escriba da lei do Deus dos céus, vos pedir, apressadamente lhe seja concedido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Até cem talentos de prata, e até cem coros de trigo, e até cem batos de vinho, e até cem batos de azeite; e sal sem limite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Tudo o que for ordenado pelo Deus do céu, prontamente se faça para a casa do Deus do céu; pois para que teria de haver grande ira contra o reino do rei e de seus filhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Também vos fazemos saber, acerca de todos os sacerdotes, levitas, cantores, porteiros, servos do templo, e trabalhadores da casa de Deus, ninguém possa lhes impor tributo, imposto, ou taxa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'E tu, Esdras, conforme a sabedoria de teu Deus que está contigo, põe oficiais e juízes, que julguem a todo o povo que está além do rio, a todos os que conhecem as Leis de teu Deus; e ao que não as conhecerem, tu lhes ensinará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'E todo aquele que não cumprir a Lei de teu Deus e a lei do rei, prontamente seja julgado, ou à morte, ou à expulsão, ou à multa, ou à prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Bendito seja o SENHOR, Deus de nossos pais, que pôs tal coisa no coração do rei, para glorificar a casa do SENHOR, que está em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'E sobre mim inclinou bondade diante do rei e de seus conselheiros, e de todos os príncipes poderosos do rei. Assim eu me esforcei segundo a mão do SENHOR meu Deus sobre mim, e ajuntei os líderes de Israel para subirem comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Estes, pois, são os chefes de suas famílias, com suas genealogias, dos que subiram comigo da Babilônia durante o reinando do rei Artaxerxes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Dos filhos de Fineias, Gérson; dos filhos de Itamar, Daniel; dos filhos de Davi, Hatus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Dos filhos de Secanias e dos filhos de Parós, Zacarias, e com ele por genealogias foram contados cento e cinquenta homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Dos filhos de Paate-Moabe, Elioenai, filho de Zeraías, e com ele duzentos homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Dos filhos de Secanias, o filho de Jaaziel, e com ele trezentos homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Dos filhos de Adim, Ebede, filho de Jônatas, e com ele cinquenta homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Dos filhos de Elão, Jesaías, filho de Atalias, e com ele setenta homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'E dos filhos de Sefatias, Zebadias, filho de Micael, e com ele oitenta homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Dos filhos de Joabe, Obadias, filho de Jeiel, e com ele duzentos e dezoito homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'E dos filhos de Selomite, o filho de Josifias, e com ele cento e sessenta homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'E dos filhos de Bebai, Zacarias, filho de Bebai, e com ele vinte e oito homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'E dos filhos de Azgade, Joanã, filho de Catã, e com ele cento e dez homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'E dos filhos de Adonicão, os últimos, cujos nomes são: Elifelete, Jeiel, e Semaías, e com eles sessenta homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'E dos filhos de Bigvai, Utai e Zabude, e com eles setenta homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'E ajuntei-os junto ao rio que vai a Aava, e acampamos ali três dias; então procurem entre o povo e entre os sacerdotes, não achei ali nenhum dos filhos de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Por isso enviei a Eliezer, Ariel, Semaías, Elnatã, Jaribe, Elnatã, Natã, Zacarias, e a Mesulão, os chefes; como também a Joiaribe e a Elnatã, os sábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'E os enviei a Ido, chefe no lugar de Casifia; e lhes instruí as palavras que deviam dizer a Ido, e a seus irmãos, os servos do templo no lugar de Casifia, para que nos trouxessem trabalhadores para a casa de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'E nos trouxeram, segundo a boa mão de nosso Deus sobre nós, um homem entendido dos filhos de Mali, filho de Levi, filho de Israel; cujo nome era Serebias com seus filhos e seus irmãos, dezoito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'E a Hasabias, e com ele a Jesaías dos filhos de Merari, seus irmãos e a seus filhos, vinte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'E dos servos do templo, a quem Davi e os príncipes puseram para o trabalho dos Levitas, duzentos e vinte servos do templo; todos eles foram indicados por nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Então proclamei ali um jejum junto ao rio de Aava, para nos humilharmos diante de nosso Deus, para lhe pedirmos um caminho seguro para nós, nossos filhos, e todos os nossos bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Pois tive vergonha de pedir ao rei tropas e cavaleiros para nos defenderem do inimigo no caminho; porque tínhamos falado ao rei, dizendo: A mão de nosso Deus está para o bem sobre todos os que o buscam; mas sua força e ira está sobre todos os que o abandonam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Assim jejuamos, e pedimos isto a nosso Deus; e ele atendeu a nossas orações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Então separei doze dos chefes dos sacerdotes, a Serebias e Hasabias, e com eles dez de seus irmãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'E pesei-lhes a prata, o ouro, e os utensílios, que eram a oferta para a casa de nosso Deus que o rei, seus conselheiros, seus príncipes, e todo os israelitas que se acharam, haviam oferecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Assim pesei nas mãos deles seiscentos e cinquenta talentos de prata, e cem talentos de utensílios de prata, e cem talentos de ouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'E vinte bacias de ouro, de mil dracmas; e dois vasos bronze reluzente, tão preciosos como o ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'E disse-lhes: Vós sois consagrados ao SENHOR, e estes utensílios são santos; como também a prata e o ouro, que são oferta voluntária ao SENHOR, Deus de vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Vigiai, e guardai estas coisas, até que as peseis diante dos líderes dos sacerdotes e dos levitas, e dos chefes das famílias de Israel em Jerusalém, nas câmaras da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Então os sacerdotes e os levitas receberam o peso da prata e do ouro e dos utensílios, para o trazerem a Jerusalém, à casa de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Assim nos partimos do rio de Aava, ao dia doze do mês primeiro, para irmos a Jerusalém; e a mão do nosso Deus estava sobre nós, e nos livrou de mão de inimigos e dos assaltantes no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'E chegamos a Jerusalém, e repousamos ali três dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Ao quarto dia foram pesados a prata, o ouro, e os utensílios, na casa de nosso Deus, por meio de Meremote, filho do sacerdote Urias, e com ele Eleazar filho de Fineias; e com eles os levitas Jozabade filho de Jesuá, e Noadias filho de Binui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Tudo foi conferido em número e em peso; e ao mesmo tempo o peso foi registrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'E os transportados, os que vieram do cativeiro, deram como oferta de queima ao Deus de Israel doze novilhos por todos os israelitas, noventa e seis carneiros, setenta e sete cordeiros, e doze bodes como sacrifício pelo pecado; tudo isto como oferta de queima ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Então deram as ordens do rei aos comissários do rei, e aos governadores dalém do rio, os quais ajudaram ao povo e à casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Acabadas, pois, estas coisas, os príncipes se achegaram a mim, dizendo: O povo de Israel, os sacerdotes e os levitas, não têm se separado dos povos destas terras, segundo suas abominações: dos cananeus, heteus, perizeus, jebuseus, amonitas, moabitas, egípcios, e amorreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Pois tomaram de suas filhas para si e para seus filhos, e assim a descendência santa se misturou com os povos destas terras; e os príncipes e os oficiais foram os primeiros nesta transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Quando eu ouvi isto, rasguei a minha roupa e meu manto; e arranquei dos cabelos de minha cabeça e de minha barba, e me sentei atônito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Então se juntaram a mim todos os que se tremiam pelas palavras do Deus de Israel, por causa da transgressão dos que eram do cativeiro; mas eu fiquei sentado, atônito, até o sacrifício da tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'E perto do sacrifício da tarde eu me levantei de minha aflição; e já tendo rasgado minha roupa e meu manto, inclinei-me de joelhos, e estendi minhas mãos ao SENHOR meu Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'E disse: Meu Deus, estou confuso e envergonhado de levantar a ti, meu Deus, o meu rosto; pois nossas perversidades se multiplicaram sobre nossa cabeça, e nossa culpa cresceu até os céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Desde os dias de nossos pais até o dia de hoje estamos em grande culpa; e por nossas perversidades nós, nossos reis, e nossos sacerdotes, somos entregues nas mãos dos reis das terras, à espada, ao cativeiro, ao roubo, e à vergonha de rosto, como se vê hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Mas agora, por um breve momento, houve favor da parte do SENHOR nosso Deus, para deixar um restante livre, e para nos dar uma estaca em seu santo lugar, a fim de iluminar nossos olhos, ó Deus nosso, e nos dar um pouco de alívio em nossa escravidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Porque somos escravos; porém em nossa escravidão nosso Deus não nos desamparou, mas, sim, inclinou sobre nós bondade diante dos reis da Pérsia, para nos dar alívio, para levantarmos a casa de nosso Deus, e restaurarmos suas ruínas, e para nos dar um muro em Judá e em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Mas agora, ó Deus nosso, o que diremos depois disto? Porque abandonamos os teus mandamentos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Os quais mandaste por meio de teus servos, os profetas, dizendo: A terra em que entrais para tomar posse é um terra imunda, por causa das imundícias dos povos daquelas terras, por suas abominações com que a encheram de um extremo ao outro de sua contaminação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Agora, pois, não dareis vossas filhas aos seus filhos, nem tomareis suas filhas para vossos filhos, e nunca procurareis sua paz nem seu bem; para que vos fortaleçais, e comais o bem da terra, e a deixeis por herança a vossos filhos para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'E depois de tudo o que nos sobreveio por causa de nossas más obras, e de nossa grande culpa, ainda que tu, Deus nosso, puniste menos do que merecíamos por nossas perversidades, e nos deixaste um remanescente como este;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Voltaremos, pois, agora, a anular teus mandamentos, e a nos aparentarmos com os povos destas abominações? Não te indignarias tu contra nós até nos consumir, até não haver resto nem remanescente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Ó SENHOR, Deus de Israel, tu és justo; pois restamos como remanescente, assim como se vê hoje. Eis que estamos diante de ti em nossa culpa; ainda que por causa disso ninguém há que possa subsistir diante de tua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'E enquanto Esdras estava orando, confessando, chorando, e prostrando-se diante da casa de Deus, ajuntou-se a ele uma multidão muito grande de israelitas, homens, mulheres, e crianças; pois o povo chorava muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Então Secanias, filho de Jeiel, dos filhos de Elão, respondeu a Esdras, dizendo: Nós temos transgredido contra nosso Deus, pois nos casamos com mulheres estrangeiras dos povos da terra; mas quanto a isto, ainda há esperança para Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Agora, pois, façamos um pacto com o nosso Deus, de que despediremos todas as mulheres e os todos os nascidos delas, conforme o conselho do Senhor, e dos que tremem ao mandamento de nosso Deus; e faça-se conforme à lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Levanta-te, porque cabe a ti este negócio, e nós seremos contigo; esforça-te, e age.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Então Esdras se levantou, e fez os chefes dos sacerdotes e dos levitas, e a todo Israel, jurarem que fariam conforme essa palavra; e eles juraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'E Esdras se levantou de diante da casa de Deus, e entrou na câmara de Joanã, filho de Eliasibe; e depois de chegar lá, não comeu pão nem bebeu água, porque estava entristecido pela transgressão dos que eram do cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Então proclamaram em Judá e em Jerusalém a todos os que vieram do cativeiro, que se reunissem em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'E que de todo aquele que não viesse em três dias, segundo o conselho dos príncipes e dos anciãos, fosse tomada toda a sua riqueza, e ele fosse separado da comunidade dos do cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Então todos os homens de Judá e de Benjamim se reuniram em Jerusalém em três dias, aos vinte do mês, no nono mês; e todo o povo se sentou na praça da casa de Deus, tremendo por causa deste negócio, e por causa das grandes chuvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Assim o sacerdote Esdras se levantou, e lhes disse: Vós transgredistes, por terdes se casado com mulheres estrangeiras, aumentando assim a culpa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Agora, pois, confessai ao SENHOR, Deus de vossos pais, e fazei a sua vontade, e separai-vos dos povos das terras, e das mulheres estrangeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'E toda a congregação respondeu, dizendo em alta voz: Assim se faça, conforme a tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Porém o povo é muito, e o tempo chuvoso, e não há condições de ficar fora das casas; nem esta obra é de um dia ou de dois, porque somos muitos os que transgredimos neste negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Portanto fiquem encarregados nossos príncipes por toda a congregação; e todos os que em nossas cidades que houverem se casado com mulheres estrangeiras, venham a tempos determinados, e com eles os anciãos de cada cidade, e seus juízes, até que desviemos de nós o ardor da ira de nosso Deus por esta causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Somente Jônatas, filho de Asael, e Jazeias, filho de Ticvá, apoiados por Mesulão e o levita Sabetai, se opuseram a isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'E assim fizeram os que vieram do cativeiro; e foram separados pelo sacerdote Esdras os homens, chefes de famílias, segundo a casa de seus pais, todos eles por nomes, para se sentarem ao dia primeiro do mês décimo, para investigarem este negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'E ao primeiro dia do mês primeiro, terminaram de investigar os homens que haviam se casado com mulheres estrangeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'E dos filhos dos sacerdotes que haviam se casado com mulheres estrangeiras, foram achados estes: dos filhos de Jesuá, filho de Jozadaque, e de seus irmãos: Maaseias, Eliézer, Jaribe, e Gedalias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'E prometeram despedir suas mulheres e, reconhecendo sua culpa, ofereceram um carneiro do rebanho pela transgressão deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'E dos filhos de Imer: Hanani e Zebadias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'E do filhos de Harim, Maaseias, Elias, Semaías, Jeiel, e Uzias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'E dos filhos de Pasur: Elioenai, Maaseias, Ismael, Natanael, Jozabade, e Elasá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'E dos filhos dos levitas: Jozabade, Simei, Quelaías (este é Quelita), Petaías, Judá, e Eliézer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'E dos cantores: Eliasibe; e dos porteiros: Salum, Telém, e Uri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'E dos demais israelitas: Dos filhos de Parós: Ramias, Jezias, Malquias, Miamim, Eleazar, e Malquias, e Benaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'E dos filhos de Elão: Matanias, Zacarias, Jeiel, Abdi, Jeremote, Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'E dos filhos de Zatu: Elioenai, Eliasibe, Matanias, e Jeremote, Zabade, e Aziza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'E dos filhos de Bebai: Jeoanã, Hananias, Zabai, Atlai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'E dos filhos de Bani: Mesulão, Maluque, Adaías, Jasube, Seal, e Jeremote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'E dos filhos de Paate-Moabe: Adna, Quelal, Benaías, Maaseias, Matanias, Bezalel, Binui e Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'E dos filhos de Harim: Eliézer, Issias, Malquias, Semaías, Simeão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamim, Maluque, e Semarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Dos filhos de Hasum: Matenai, Matatá, Zabade, Elifelete, Jeremai, Manassés, Simei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Dos filhos de Bani: Maadai, Anrão, Uel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaías, Bedias, Queluí,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanias, Meremote, Eliasibe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matanias, Matenai, e Jaasai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'E Bani, e Binui, Simei,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemias, Natã, Adaías,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Macnadbai, Sasai, Sarai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azareel, Selemias, Semarias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Salum, Amarias, José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'E dos filhos de Nebo: Jeiel, Matitias, Zabade, Zebina, Jadai, Joel, e Benaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Todos estes haviam tomado mulheres estrangeiras; e alguns deles tiveram filhos com tais mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Palavras de Neemias, filho de Hacalias.E aconteceu no mês de Quisleu, no ano vigésimo, enquanto eu estava na fortaleza de Susã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Veio Hanani, um de meus irmãos, ele e alguns homens de Judá, e perguntei-lhes pelos judeus que haviam escapado, que restaram do cativeiro, e por Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'E me disseram: Os remanescentes, os que restaram do cativeiro lá na província, estão em grande miséria e desprezo; e o muro de Jerusalém está fendido, e suas portas queimadas a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'E aconteceu que, quando eu ouvi estas palavras, sentei-me e chorei, e fiquei de luto por alguns dias; e jejuei e orei diante do Deus dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'E disse: Ó SENHOR, Deus dos céus, Deus grande e temível, que guarda o pacto e a bondade aos que o amam e guardam seus mandamentos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Estejam, pois, os teus ouvidos atentos, e teus olhos abertos, para ouvires a oração de teu servo, que eu oro hoje diante de ti dia e noite, pelos filhos de Israel, teus servos; e confesso os pecados dos filhos de Israel que pecamos contra ti; também eu e a casa de meu pai pecamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Agimos muito corruptamente contra ti, e não guardamos os mandamentos, nem o estatutos nem os juízos, que mandaste ao teu servo Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Lembra-te, pois, da palavra que mandaste a teu servo Moisés, dizendo: Se vós transgredirdes, eu vos dispersarei entre os povos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Mas se vos converterdes a mim, e guardardes meus mandamentos, e os praticardes; então ainda que os rejeitados estejam nos confins dos céus, de lá eu os ajuntarei, e os trarei ao lugar que escolhi para fazer habitar ali o meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Eles são teus servos e teu povo, que resgataste com teu grande poder, e com tua mão forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Por favor, SENHOR, estejam teus ouvidos atentos à oração do teu servo, e a oração de teus servos, que desejam temer o teu nome; e, por favor, faze ter sucesso hoje a teu servo, e dá-lhe favor diante deste homem!Pois eu era copeiro do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Sucedeu, pois, no mês de Nisã, no ano vigésimo do rei Artaxerxes, que havendo vinho diante dele, tomei o vinho, e o dei ao rei. Porém eu nunca havia estado triste diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Por isso o rei me perguntou: Por que o teu rosto está triste, mesmo não estando doente? Isto não pode ser outra coisa, senão tristeza de coração. Tive então muito medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'E disse ao rei: Viva o rei para sempre! Como meu rosto não estaria triste, quando a cidade, o lugar dos sepulcros de meus pais, está arruinada, e suas portas consumidas a fogo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'E o rei me disse: O que pedes? Então orei ao Deus dos céus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'E respondei ao rei: Se for do agrado do rei, e se teu servo é agradável diante de ti, peço que me envies a Judá, à cidade dos sepulcros de meus pais, para reconstruí-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Então o rei me disse (enquanto a rainha estava sentada junto a ele): Por quanto tempo durará tua viagem, e quando voltarás? E agradou ao rei me enviar, depois que eu lhe defini um certo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Disse mais ao rei: Se for do agrado do rei, sejam dadas a mim cartas para os governadores dalém do rio, para que me permitam passar em segurança até que eu chegue a Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Como também um carta para Asafe, guarda do jardim do rei, para que me dê madeira para consertar as portas da fortaleza do templo, para o muro da cidade, e para a casa onde entrarei.E o rei me concedeu, segundo a boa mão do SENHOR sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Então vim aos governadores dalém do rio, e lhes dei as cartas do rei. E o rei enviou comigo capitães do exército e cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Quando então Sambalate, o horonita, e Tobias, o servo amonita, ouviram, desagradou-lhes muito que alguém viesse para buscar o bem aos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Cheguei, pois, a Jerusalém, e fiquei ali três dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'E de noite me levantei, eu e uns poucos homens comigo, e não declarei a ninguém o que Deus tinha posto em meu coração que fizesse em Jerusalém; e animal nenhum estava comigo, a não ser o o em que eu cavalgava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'E de noite saí pela porta do Vale até a fonte do Dragão e à porta do Esterco; e observei os muros de Jerusalém que estavam fendidos, e suas portas estavam consumidas a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'E passei à porta da Fonte, e ao tanque do rei; e não houve lugar por onde o animal em que eu estava montado pudesse passar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Então de noite subi pelo vale, e observei o muro; então voltei, e entrei pela porta do Vale, e assim me retornei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'E os oficiais não sabiam aonde eu tinha ido, nem o que tinha feito; nem mesmo aos judeus e aos sacerdotes, nem aos nobres e oficiais, nem aos demais que faziam a obra, havia eu declarado coisa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Então eu lhes disse: Com certeza vedes a miséria em que estamos, que Jerusalém está arruinada, e suas portas queimadas a fogo. Vinde, e reconstruamos o muro de Jerusalém, e não sejamos mais humilhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Então lhes declarei como a mão de meu Deus havia sido boa sobre mim, e também as palavras do rei, que ele tinha me dito. Então disseram: Levantemo-nos, e edifiquemos. Assim esforçaram suas mãos para uma boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Porém, quando Sambalate o horonita, Tobias o servo amonita, e Gesém o árabe, ouviram isto,zombaram de nós, e nos desprezaram, dizendo: O que é isto que vós fazeis? Por acaso estais vos rebelando contra o rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Então lhes respondi, dizendo-lhes: O Deus dos céus é quem nos dará sucesso; e nós, servos dele, nos levantaremos e edificaremos; pois vós não tendes parte, nem direito, nem memória em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'E Eliasibe, o sumo sacerdote, levantou-se com seus irmãos os sacerdotes, e edificaram a porta das Ovelhas. Eles a consagraram, e levantaram suas portas; eles a consagraram até a torre de Meá, e até a torre de Hananel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'E ao lado dela os homens de Jericó edificaram; e ao seu lado edificou Zacur, filho de Inri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'E os filhos de Hassenaá edificaram a porta do Peixe; puseram-lhe vigas, e levantaram suas portas com suas fechaduras e seus ferrolhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'E ao seu lado reparou Meremote filho de Urias, filho de Coz; e ao seu lado reparou Mesulão filho de Berequias, filho de Mesezabel; e ao seu lado reparou Zadoque filho de Baaná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'E ao seu lado os tecoítas repararam; porém os seus mais ilustres se recusaram a prestar serviço a seu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'E a porta Velha Joiada filho de Paseia, e Mesulão filho de Besodias repararam; puseram-lhe vigas, e levantaram suas portas com suas fechaduras e seus ferrolhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'E ao seu lado repararam Melatias o gibeonita, e Jadom meronotita, homens de Gibeom e de Mispá, que está sob o domínio do governador dalém do rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'E ao seu lado reparou Uziel filho de Haraías, um dos ourives; e ao seu lado reparou Hananias, um dos perfumistas. Assim restauraram a Jerusalém até o muro largo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'E ao seu lado reparou Refaías filho de Hur, líder da metade da região de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'E ao seu lado reparou Jedaías filho de Harumafe, assim como em frente de sua casa; e ao seu lado reparou Hatus filho de Hasbaneias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Malquias filho de Harim, e Hassube filho de Paate-Moabe, repararam a outra medida, como também a torre dos Fornos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'E ao seu lado reparou Salum filho de Haloés, líder da metade da região de Jerusalém; ele e suas filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Hanum e os moradores de Zanoa repararam a porta do Vale. Estes a edificaram, levantaram suas portas com suas fechaduras e seus ferrolhos, como também mil côvados no muro, até a porta do Esterco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Malquias filho de Recabe, líder da região de Bete-Haquerém, reparou a porta do Esterco; ele a edificou, levantou suas portas com suas fechaduras e seus ferrolhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Salum filho de Col-Hozé, líder da região de Mispá, reparou a porta da Fonte; ele a edificou, a cobriu, e levantou suas portas com suas fechaduras e seus ferrolhos; como também o muro do tanque de Selá junto ao jardim do rei, e até as degraus que descem da cidade de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Depois dele reparou Neemias filho de Azbuque, líder de metade da região de Bete-Zur, até em frente dos sepulcros de Davi, e até o tanque artificial, e até a casa dos Guerreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Depois dele repararam os levitas, Reum filho de Bani; ao seu lado reparou Hasabias, líder de metade da região de Queila, em sua região.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Depois dele repararam seus irmãos, Bavai filho de Henadade, líder de metade da região de Queila.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Ao seu lado reparou Ezer filho de Jesua, líder de Mispá, outra medida; em frente da subida à casa de armas da esquina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Depois dele reparou com grande fervor Baruque filho de Zabai a outra medida; desde a esquina até a porta da casa de Eliasibe, o sumo sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Depois dele reparou Meremote filho de Urias filho de Coz a outra medida, desde a entrada da casa de Eliasibe, até o fim da casa de Eliasibe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'E depois dele repararam os sacerdotes, os que habitavam na vizinhança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Depois deles repararam Benjamim e Hassube, em frente da casa deles; e depois deles reparou Azarias, filho de Maaseias, filho de Ananias, perto de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Depois dele reparou Binui filho de Henadade, outra medida; desde a casa de Azarias até a esquina, e até o canto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, filho de Uzai, em frente da esquina e a torre que sai da casa superior do rei, que está junto ao pátio da prisão. Depois dele, Pedaías filho de Parós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'E os servos do templo, que habitavam em Ofel, repararam até em frente da porta das Águas ao oriente, e à torre alta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Depois os tecoítas repararam outra medida; em frente da torre grande e alta, até o muro de Ofel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Os sacerdotes repararam desde a porta dos Cavalos, cada um em frente de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Depois deles reparou Zadoque filho de Imer, em frente de sua casa; e depois dele reparou Semaías filho de Secanias, guarda da porta oriental.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Depois dele reparou Hananias filho de Selemias, e Hanum, o sexto filho de Zalafe, outra medida. Depois dele reparou Mesulão, filho de Berequias, em frente de sua câmara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Depois dele reparou Malquias um dos ourives, até a casa dos servos do templo e dos mercadores; em frente da porta da Inspeção, e até a câmara do canto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'E entre a câmara do canto até a porta das Ovelhas, os ourives e os mercadores repararam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'E foi que, quando Sambalate ouviu que nós edificávamos o muro, ele se indignou muito, e escarneceu dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'E falou diante de seus irmãos e do exército de Samaria, dizendo: O que fazem estes fracos judeus? Será isso lhes permitido? Farão eles sacrifícios? Acabarão isso algum dia? Ressuscitarão dos amontoados de entulho as pedras que foram queimadas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'E com ele estava Tobias, o amonita, que disse: Ainda que edifiquem, contudo, se uma raposa vier, ela sozinha será capaz de derrubar seu muro de pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Ouve, ó Deus nosso, que somos desprezados, e devolve a humilhação deles sobre suas cabeças; e entrega-os para o despojo, na terra do cativeiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'E não cubras a perversidade deles, nem o pecado deles seja riscado diante de teu rosto; pois provocaram à ira diante dos construtores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Edificamos, pois o muro, e todo o muro foi completado até metade de sua altura; porque o coração do povo estava disposto a trabalhar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'E foi que, quando Sambalate e Tobias, e os árabes, os amonitas, e os de Asdode, ouviram que os muros de Jerusalém estavam sendo reparados, que as brechas já começavam a serem fechadas, eles ficaram muito irados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'E todos conspiraram entre si para virem guerrear contra Jerusalém, e causarem confusão nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Porém nós oramos a nosso Deus; e pusemos guarda contra eles, dia e noite, por causa deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Então Judá disse: As forças dos carregadores se enfraqueceram, e o entulho é muito; e nós não podemos reconstruir o muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Porém nossos inimigos diziam: Eles não saibam, nem vejam, até que entremos em meio deles, e os matemos; assim faremos cessar a obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'E foi que, quando os judeus que habitavam entre eles vieram, dez vezes nos disseram: Por todos os lados para que virardes, eles estão contra nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Então pus guardas nos lugares baixos, atrás do muro, e nos lugares altos; e pus ao povo por suas famílias com suas espadas, suas lanças, e seus arcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Depois olhei, me levantei, e disse aos nobres, aos oficiais, e aos demais do povo: Não os temais; lembrai-vos do Senhor grande e temível, e lutai por vossos irmãos, por vossos filhos e vossas filhas, por vossas mulheres e vossas casas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'E foi que, quando nossos inimigos ouviram falar que já sabíamos de tudo,e que Deus havia frustrado o plano deles, todos voltamos ao muro, cada um à sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Sucedeu, porém, que desde aquele dia a metade dos meus servos trabalhava na obra, e outra metade deles tinha lanças, escudos, arcos, e couraças; e os líderes estavam por detrás de toda a casa de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Os que edificavam o muro, e os que traziam as cargas e os que carregavam, com uma mão faziam a obra, e na outra tinham armas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'E cada um dos construtores trazia sua espada cingida a seus lombos, e assim edificavam; e o que tocava a trombeta estava junto a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'E eu disse aos nobres, aos oficiais, e aos demais do povo: A obra é grande e extensa, e nós estamos separados no muro, longe uns dos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'No lugar onde ouvirdes o som da trombeta, ali vos ajuntareis conosco; nosso Deus lutará por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Assim trabalhávamos na obra; e a metade deles tinham lanças desde a subida do amanhecer até o surgir das estrelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Também naquele tempo eu disse ao povo: Cada um passe a noite com seu servo dentro de Jerusalém, para que de noite nos sirvam de guarda, e de dia na obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'E nem eu, nem meus irmãos, nem meus servos, nem os homens da guarda que me seguiam, nos despíamos de nossas roupas; cada um mantinha sua arma até para a água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Então houve um grande clamor do povo e de suas mulheres contra seus irmãos, os judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Pois havia quem dizia: Nós, nossos filhos e nossas filhas, somos muitos; por isso tomamos trigo, para que comamos e vivamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Também havia quem dizia: Colocamos em penhor nossas terras, nossas vinhas, e nossas casas, para comprarmos trigo durante a fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'E havia quem dizia: Pedimos emprestado até para o tributo do rei sobre nossas terras e nossas vinhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Agora, pois, nossa carne é como a carne de nossos irmãos, e nossos filhos como seus filhos; porém eis que nós sujeitamos nossos filhos e nossas filhas por servos, e até algumas de nossas filhas estão subjugadas, que não estão em poder de nossas mãos, e outros têm para si nossas terras e nossas vinhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Quando eu ouvi seu clamor, fiquei muito irado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Então eu meditei em meu coração, e depois briguei com os nobres e com os oficiais, dizendo-lhes: Emprestais com juros cada um a seu irmão?E convoquei contra eles uma grande reunião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'E disse-lhes: Nós resgatamos nossos irmãos judeus que haviam sido vendidos às nações, conforme o que nos era possível, e vós novamente venderíeis a vossos irmãos, ou seriam eles vendidos a nós? E ficaram calados, e não acharam o que responder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'E eu disse mais: Não é bom o que fazeis. Por acaso não andareis no temor a nosso Deus, para que não haja humilhação da parte das nações que são nossas inimigas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Também eu, meus irmãos, e meus servos, temos lhes emprestado a juros dinheiro e grão. Abandonemos esta cobrança de juros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Devolvei a eles hoje mesmo suas terras, suas vinhas, seus olivais, e suas casas; e a centésima parte do dinheiro e do trigo, do vinho e do azeite que exigis deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Então disseram: Devolveremos, e nada lhes exigiremos; faremos assim como tu dizes. Então chamei aos sacerdotes, e lhes fiz jurar que fariam conforme esta promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Também sacudi minha roupa, e disse: Assim sacuda Deus de sua casa e de seu trabalho a todo homem que não cumprir esta promessa; e assim seja sacudido e esvaziado. E toda a congregação: Amém! E louvaram ao SENHOR. E o povo fez conforme esta promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Também desde o dia que fui nomeado governador deles na terra de Judá, desde o ano vinte até o ano trinta e dois do rei Artaxerxes, doze anos, nem eu nem meus irmãos comemos o pão do governador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Mas os primeiros governadores que foram antes de mim, oprimiram ao povo, e tomaram deles pão e pelo vinho, além de quarenta siclos de prata; ainda mais, seus servos dominavam opressivamente sobre o povo; porém eu não fiz assim, por causa do temor a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Além disso, concentrei meus esforços na obra deste muro, e não compramos terra alguma; e todos meus servos se ajuntaram ali para a obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Também cento e cinquenta homens dos judeus, dos oficiais, e dos que vinha até nós dentre as ns nações que estão ao nosso redor, se punham à minha mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'E o que se preparava para cada dia era um boi, e seis ovelhas escolhidas; também preparavam aves para mim, e cada dez dias todas as variedades de muito vinho; e nem por isso exigi o pão do governador, porque a servidão deste povo era grave.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Lembra-te de mim para o bem, ó meu Deus; e de tudo o que fiz a este povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Sucedeu, pois, que, quando Sambalate, Tobias, e Gesém o árabe, e os demais de nossos inimigos, ouviram que eu tinha edificado o muro, e que não havia mais brecha nele (ainda que até aquele tempo não tinha posto as portas nas entradas),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Sambalate e Gesém mandaram dizer: Vem, e nos reunamos em alguma das aldeias no vale de Ono. Mas eles haviam pensado em fazer o mal a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'E enviei-lhes mensageiros, dizendo: Eu faço uma grande obra, por isso não posso descer; porque eu pararia a obra, para a deixar, e ir me encontrar convosco?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'E mandaram a mesma mensagem a mim quatro vezes, e eu lhes respondi da mesma maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Então Sambalate enviou a mim seu servo pela quinta vez, com uma carta aberta em sua mão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Em que estava escrito: Ouve-se falar entre as nações, e Gesém disse, que tu e os judeus pensais vos rebelar; e por isso tu edificas o muro, para que tu sejas o rei deles, conforme o que se diz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'E que puseste profetas para proclamem de ti em Jerusalém, dizendo: Este é o rei em Judá! Assim o rei ouvirá conforme estas palavras. Vem, pois, agora, e nos reunamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Porém eu mandei lhes dizer: Nada do que dizes aconteceu, mas sim és tu que inventas de tua própria mente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Porque todos eles procuravam nos atemorizar, dizendo: As mãos deles se enfraquecerão da obra, e ela não será feita.Esforça pois minhas mãos, ó Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'E quando eu vim à casa de Semaías filho de Delaías, filho de Meetabel (que estava encerrado), ele me disse: Vamos juntos à casa de Deus dentro do templo, e cerremos as portas do templo, porque virão para te matar; sim, de noite virão para te matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Porém eu disse: Um homem como eu fugiria? E poderia alguém como eu entrar no templo para preservar sua vida? De maneira nenhuma entrarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'E percebi, e vi que Deus não tinha o enviado, mas sim que ele falou aquela profecia contra mim, porque Tobias e Sambalate haviam lhe subornado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Para isto ele foi subornado, para me atemorizar, a fim de que assim eu fizesse, e pecasse; para que tivessem alguma coisa para falarem mal de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Lembra-te, meu Deus, de Tobias e de Sambalate, conforme estas suas obras, e também da profetiza Noadia, e dos outros profetas que procuravam me atemorizar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'O muro foi terminado ao dia vinte e cinco do mês de Elul, em cinquenta e dois dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'E foi que, quando todos os nossos inimigos ouviram, todas as nações ao nosso redor temeram, e abateram-se muito em seus olhos, porque reconheceram que foi nosso Deus que fizera esta obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Também naqueles dias muitas foram escritas de alguns dos nobres de Judá a Tobias, e as de Tobias vinham a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Porque muitos em Judá haviam feito juramento com ele, porque ele era genro de Secanias, filho de Ara; e seu filho Joanã havia tomado a filha de Mesulão, filho de Berequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Também contavam diante de mim suas boas obras, e levavam a ele minhas palavras. E Tobias me enviava cartas para me atemorizar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Sucedeu, pois, que, quando o muro já havia sido edificado, e já tinha posto as portas, e sido estabelecidos os porteiros, os cantores e os Levitas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Mandei o meu irmão Hanani, e Hananias, chefe do palácio de Jerusalém (porque era um homem fiel e temente a Deus, mais que muitos),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'E disse-lhes: Não se abram as portas de Jerusalém até que o sol aqueça; e enquanto ainda estiverem presentes, fechem as portas, e as trancai. E ponham-se guardas dos moradores de Jerusalém, cada um em sua guarda, e cada um diante de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'E a cidade era espaçosa e grande, porém pouca gente havia dentro dela, e as casas ainda não haviam sido reconstruídas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Então Deus pôs em meu coração que juntasse os nobres, os oficiais, e o povo, para que fossem registrados pela ordem de suas genealogias; e achei o livro da genealogia dos que haviam subido antes, e achei nele escrito o seguinte:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Estes são os filhos da província que subiram do cativeiro, dos que foram levados por Nabucodonosor, rei de Babilônia, e que voltaram a Jerusalém e a Judá, cada um à sua cidade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Os quais vieram com Zorobabel, Jesua, Neemias, Azarias, Raamias, Naamani, Mardoqueu, Bilsã, Misperete, Bigvai, Neum, Baaná. Este é o número dos homens do povo de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Os filhos de Parós, dois mil cento e setenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Os filhos de Sefatias, trezentos e setenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Os filhos de Ara, seiscentos e cinquenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Os filhos de Paate-Moabe, dos filhos de Jesua e de Joabe, dois mil oitocentos e dezoito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Os filhos de Elão, mil duzentos e cinquenta e quatro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Os filhos de Zatu, oitocentos e quarenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Os filhos de Zacai, setecentos e sessenta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Os filhos de Binui, seiscentos e quarenta e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Os filhos de Bebai, seiscentos e vinte e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Os filhos de Azgade, dois mil seiscentos e vinte e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Os filhos de Adonicão, seiscentos e sessenta e sete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Os filhos de Bigvai, dois mil e sessenta e sete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Os filhos de Adim, seiscentos e cinquenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Os filhos de Ater, de Ezequias, noventa e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Os filhos de Hasum, trezentos e vinte e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Os filhos de Bezai, trezentos e vinte e quatro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Os filhos de Harife, cento e doze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Os filhos de Gibeom, noventa e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Os homens de Belém e de Netofá, cento e oitenta e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Os homens de Anatote, cento e vinte e oito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Os homens de Bete-Azmavete, quarenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Os homens de Quiriate-Jearim, Cefira e Beerote, setecentos e quarenta e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Os homens de Ramá e de Geba, seiscentos e vinte e um;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Os homens de Micmás, cento e vinte e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Os homens de Betel e de Ai, cento e vinte e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Os homens da outra Nebo, cinquenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Os filhos do outro Elão, mil duzentos e cinquenta e quatro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Os filhos de Harim, trezentos e vinte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Os filhos de Jericó, trezentos e quarenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Os filhos de Lode, de Hadide, e Ono, setecentos vinte e um;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Os filhos de Senaá, três mil novecentos e trinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Os sacerdotes: os filhos de Jedaías, da casa de Jesua, novecentos e setenta e três;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Os filhos de Imer, mil e cinquenta e dois;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Os filhos de Pasur, mil duzentos quarenta e sete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Os filhos de Harim, mil dez e sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Os levitas: os filhos de Jesua, de Cadmiel, dos filhos de Hodeva, setenta e quatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Os cantores: os filhos de Asafe, cento e quarenta e oito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Os porteiros: os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai, cento e trinta e oito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Os servos do templo: os filhos de Zia, os filhos de Hasufa, os filhos de Tabaote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Os filhos de Queros, os filhos de Sia, os filhos de Padom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Os filhos de Lebana, os filhos de Hagaba, os filhos de Salmai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Os filhos de Hanã, os filhos de Gidel, os filhos de Gaar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Os filhos de Reaías, os filhos de Rezim, os filhos de Necoda,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Os filhos de Gazão, os filhos de Uzá, os filhos de Paseia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Os filhos de Besai, os filhos de Meunim, os filhos de Nefusesim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Os filhos de Baquebuque, os filhos de Hacufa, os filhos de Harur,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Os filhos de Baslite, os filhos de Meída, os filhos de Harsa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Os filhos de Barcos, os filhos de Sísera, os filhos de Tamá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Os filhos de Nesias, os filhos de Hatifa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Os filhos dos servos de Salomão: os filhos de Sotai, os filhos de Soferete, os filhos de Perida,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Os filhos de Jaala, os filhos de Darcom, os filhos de Gidel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Os filhos de Sefatias, os filhos de Hatil, os filhos de Poquerete-Hazebaim, os filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Todos os servos do templo, e filhos dos servos de Salomão, trezentos e noventa e dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Também estes subiram de Tel-Melá, Tel-Harsa, Querube, Adom, e Imer, porém não puderam mostrar a casa de seus pais, nem sua linhagem, se eram de Israel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Os filhos de Delaías, os filhos de Tobias, os filhos de Necoda, seiscentos e quarenta e dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'E dos sacerdotes: os filhos de Habaías, os filhos de Coz, os filhos de Barzilai, o qual tomara mulher das filhas de Barzilai, o gileadita, e chamou-se pelo nome delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Estes buscaram seu registro de genealogias, porém não se achou; por isso, como impuros, foram excluídos do sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'E o governador lhes disse que não comessem das coisas mais santas, até que houvesse sacerdote com Urim e Tumim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Toda esta congregação junta era quarenta e dois mil trezentos e sessenta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Exceto seus servos e suas servas, que eram sete mil trezentos e trinta e sete; e tinham duzentos e quarenta e cinco cantores e cantoras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Seus cavalos, setecentos e trinta e seis; seus mulos, duzentos e quarenta e cinco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Os camelos, quatrocentos e trinta e cinco; asnos, seis mil setecentos e vinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'E alguns dos chefes das famílias fizeram doações para a obra. O governador deu para o tesouro mil dracmas de ouro, cinquenta bacias, e quinhentas trinta vestes sacerdotais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'E alguns dos chefes das famílias deram para o tesouro da obra, vinte mil dracmas de ouro, e duas mil e duzentas libras de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'E o que o resto do povo deu foi vinte mil dracmas de ouro, duas mil libras de prata, e sessenta e sete vestes sacerdotais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'E os sacerdotes, os Levitas, e os porteiros, os cantores, os do povo, os servos do templo, e todo Israel, habitaram em suas cidades.E vindo o mês sétimo, estando os filhos de Israel em suas cidades,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'E todo o povo se juntou como um só homem na praça diante da porta das Águas, e disseram ao escriba Esdras que trouxesse o livro da lei de Moisés, que o SENHOR havia mandado a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'E Esdras, o sacerdote, trouxe a lei diante da congregação, tanto de homens como de mulheres, e de todos os que tivessem entendimento para ouvir, no primeiro dia do sétimo mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'E leu no livro diante da praça que está diante da porta das Águas, desde o amanhecer até o meio-dia, na presença de homens, mulheres e entendidos; e os ouvidos de todo o povo estavam atentos ao livro da lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'E o escriba Esdras estava sobre uma plataforma de madeira, que haviam feito para aquilo; e junto a ele estavam Matitias, Sema, Anaías, Urias, Hilquias, e Maaseias, à sua direita; e a sua esquerda, Pedaías, Misael, Malquias, Hasum, Hasbadana, Zacarias, e Mesulão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'E Esdras abriu o livro perante os olhos de todo o povo, porque estava mais alto que todo o povo; e quando ele o abriu, todo o povo se pôs de pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Então Esdras louvou ao SENHOR, o grande Deus. E todo o povo respondeu: Amém! Amém! levantando suas mãos; e inclinaram-se, e adoraram ao SENHOR com os rostos em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'E Jesua, Bani, e Serebias, Jamim, Acube, Sabetai, Hodias, Maaseias, Quelita, Azarias, Jozabade, Hanã, Pelaías, e os levitas, ensinavam ao povo a lei; e o povo estava em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'E leram no livro da lei de Deus o declarando, e explicando o sentido, para que pudessem entender o que era lido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'E Neemias (que era o governador), e o sacerdote Esdras, escriba, e os levitas que ensinavam ao povo, disseram a todo o povo: Este dia é consagrado ao SENHOR nosso Deus; não vos entristeçais, nem choreis. Porque todo o povo chorava enquanto ouvia as palavras da lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'E disse-lhes mais: Ide, comei gorduras, e bebei doçuras, e enviai porções aos que não têm preparado; porque este é um dia consagrado ao nosso Senhor; portanto não vos entristeçais, porque a alegria do SENHOR é vossa força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'E os levitas faziam todo o povo ficar calado, dizendo: Calai-vos, que é dia santo, e não vos entristeçais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Então todo o povo foi embora para comer, beber, enviar porções, e celebrar alegremente, porque entenderam as palavras que lhes haviam ensinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'E no dia seguinte se juntaram os líderes das famílias de todo o povo, os sacerdotes, os levitas, o e o escriba Esdras, para estudarem as palavras da lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'E acharam escrito na lei que o SENHOR havia mandado por meio de Moisés, que os filhos de Israel habitassem em tendas na solenidade do mês sétimo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Por isso eles anunciaram publicamente, e proclamaram por todas as suas cidades e por Jerusalém, dizendo: Saí ao monte, trazei ramos de oliveiras, e ramos de oliveiras silvestres, e ramos de murta, ramos de palmeiras, e ramos de toda árvore espessa, para fazer tendas como está escrito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Saiu, pois, povo, e os trouxeram, e fizeram para si tendas, cada um sobre seu terraço, em seus pátios, nos pátios da casa de Deus, na praça da porta das Águas, e na praça da porta de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'E toda a congregação dos que voltaram do cativeiro fizeram tendas, e em tendas habitaram; porque os filhos de Israel, desde os dias de Josué filho de Num até aquele dia, não haviam feito assim. E houve alegria muito grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'E a cada dia Esdras leu no livro da lei de Deus, desde o primeiro dia até o último; e celebraram a solenidade durante sete dias, e ao oitavo dia houve uma assembleia solene, conforme a ordenança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'No dia vinte e quatro do mesmo mês, os filhos de Israel se reuniram em jejum, com sacos, e com terra sobre si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'E a descendência de Israel já havia se separado de todos os estrangeiros; então puseram-se de pé, confessaram seus pecados, e as iniquidades de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Pois, levantados de pé em seu lugar, leram no livro da lei de SENHOR seu Deus uma quarta parte do dia, e em outra quarta parte confessaram e adoraram ao SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'E Jesua, Bani, Cadmiel, Serebias, Buni, Sebanias, Bani e Quenai, se puseram de pé na escadaria dos Levitas, e clamaram em alta voz ao SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'E os levitas Jesua, Cadmiel, Bani, Hasbaneias, Serebias, Hodias, Sebanias e Petaías, disseram: Levantai-vos, bendizei ao SENHOR vosso Deus para todo o sempre: Bendito o teu glorioso nome, que está exaltado sobre toda bênção e louvor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Tu és o único, SENHOR! Tu fizeste o céu, o céu dos céus, e toda o seu exército; a terra e tudo quanto nela há; os mares e tudo quanto neles há; e tu vivificas a todos; os exércitos dos céus te adoram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Tu és, SENHOR, o Deus que escolheste a Abrão, e o tiraste de Ur dos caldeus, e puseste nele o nome Abraão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'E achaste o coração dele fiel diante de ti, e fizeste com ele o pacto para lhe dar a terra dos cananeus, dos heteus, dos amorreus, dos perizeus, dos jebuseus, e dos girgaseus, para a dares à sua descendência; e cumpriste as tuas palavras, porque és justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'E olhaste para a aflição de nossos pais no Egito, e ouviste o clamor deles junto ao mar Vermelho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'E deste sinais e maravilhas a Faraó, e a todos os seus servos, e a todo o povo de sua terra; porque sabias que os tratariam com soberba; e assim fizeste famoso o teu nome, tal como o é hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'E dividiste o mar diante deles, e passaram por meio do mar a seco; e lançaste a seus perseguidores nas profundezas, como uma pedra em águas violentas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'E com coluna de nuvem os guiaste de dia, e com coluna de fogo de noite, para os iluminares no caminho por onde haviam de ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'E sobre o monte de Sinai desceste, e falaste com eles desde o céu; e deste-lhes regras justas, leis verdadeiras, e estatutos e mandamentos bons.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'E ensinaste a eles teu santo sábado; e lhes mandaste preceitos e estatutos, por meio de teu servo Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'E deste-lhes pão do céu em sua fome, e em sua sede lhes tiraste águas da pedra; e disseste a eles que entrassem para tomar posse da terra, pela qual juraste com mão erguida, que a darias a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Porém eles, nossos pais, agiram com soberba; endureceram sua cerviz, e não deram ouvidos a teus mandamentos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'E recusaram te ouvir, e não se lembraram de tuas maravilhas que havias feito com eles; ao invés disso, endureceram sua cerviz, e em sua rebelião levantaram um líder para voltarem à sua escravidão. Porém tu, que és Deus que perdoas, clemente e misericordioso, tardio para se irar, e grande em bondade, não os desamparaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Até quando fizeram para si bezerro de fundição, e disseram: Este é teu Deus que te tirou do Egito; e cometeram grandes blasfêmias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Tu, contudo, pela tua grande misericórdia não os abandonaste no deserto; a coluna de nuvem nunca se afastou deles de dia, para os guiar pelo caminho, nem a coluna de fogo de noite, para os iluminar no caminho pelo qual haviam de ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'E deste o teu bom Espírito para os ensinar, e não tiraste o teu maná de suas bocas, e lhes deste água em sua sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Assim os sustentaste por quarenta anos no deserto; de nenhuma coisa tiveram falta; suas roupas não se envelheceram, nem seus pés se incharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Também lhes deste reinos e povos, e os repartistes por cantos; assim tomaram posse da terra de Siom, a terra do rei de Hesbom, e a terra de Ogue, rei de Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'E multiplicaste seus filhos como as estrelas do céu, e os trouxeste à terra, da qual tinhas dito a seus pais, que entrariam para tomarem posse dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Assim os filhos vieram, e tomaram posse daquela terra; e abateste diante deles aos moradores do território, os cananeus, e os entregaste em suas mãos, como também a seus reis, e aos povos do território, para que fizessem deles à sua vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'E tomaram cidades fortificadas e terra fértil, e tomaram posse de casas cheias de toda fartura, cisternas cavadas, vinhas e olivais, e muitas árvores frutíferas; e comeram, se fartaram, engordaram, e se deleitaram pela tua grande bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Porém eles foram desobedientes, e se rebelaram contra ti; desprezaram tua lei, e mataram teus profetas que lhes alertavam para que convertessem a ti; assim fizeram grandes abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Por isso tu os entregaste nas mãos de seus inimigos, os quais os afligiram; e no tempo de sua angústia clamaram a ti, e tu desde os céus os ouviste; e segundo tua grande misericórdia tu lhes davas libertadores, que os salvaram da mão de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mas assim que tinham repouso, voltavam a fazer o mal diante de ti; e tu os abandonavas nas mãos de seus inimigos, para que os dominassem. E eles se convertiam, e clamavam a ti, e tu os ouvias desde os céus; e segundo tua misericórdia muitas vezes os livraste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'E os alertaste, para os fazer voltar à tua lei; porém eles agiram com soberba, e não deram ouvidos teus mandamentos; ao invés disso, pecaram contra teus juízos, os quais quem praticar, por causa deles viverá; e deram as costas, endureceram sua cerviz, e não deram ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Porém os suportaste por muitos anos, e os alertaste com teu Espírito por meio de teus profetas, mas não deram ouvidos; por isso tu os entregaste nas mãos dos povos das terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Mas por tua grande misericórdia não os destruíste por completo, nem os desamparaste; porque tu és Deus clemente e misericordioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Agora pois, Deus nosso, Deus grande, poderoso e temível, que guardas o pacto e a bondade, não consideres pouco toda a opressão que alcançou a nós, nossos reis, nossos príncipes, nossos sacerdotes, nossos profetas, nossos pais, e todo o teu povo, desde os dias dos reis da Assíria até o dia de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Tu, porém, és justo em tudo quanto veio sobre nós; porque agiste fielmente, mas nós agimos perversamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'E nossos reis, nossos príncipes, nossos sacerdotes, e nossos pais, não praticaram tua lei, nem deram ouvidos a teus mandamentos e teus testemunhos, com que os alertavas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Porque eles, mesmo em seu reino, nos muitos bens que lhes deste, e na terra espaçosa e fértil que entregaste a deles, não te serviram, nem se converteram de suas más obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Eis que hoje somos servos, na terra que havias dado a nossos pais para que comessem seus fruto e o seu bem, eis que nela somos servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'E sua grande renda é para os reis que puseste sobre nós por nossos pecados; e eles à sua vontade dominam sobre nossos corpos e sobre nossos animais, e estamos em grande angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'A por causa de tudo isso nós fazemos um pacto fiel, e o escrevemos, e nossos príncipes, nossos Levitas, e nossos sacerdotes o selaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'E os que selaram foram: Neemias o governador, filho de Hacalias, e Zedequias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraías, Azarias, Jeremias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pasur, Amarias, Malquias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hatus, Sebanias, Maluque,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremote, Obadias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginetom, Baruque,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesulão, Abias, Miamim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazias, Bilgai, Semaías: estes eram o sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'E os Levitas: Jesua filho de Azanias, Binui dos filhos de Henadade, Cadmiel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'E seus irmãos Sebanias, Hodias, Quelita, Pelaías, Hanã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Mica, Reobe, Hasabias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zacur, Serebias, Sebanias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodias, Bani, e Beninu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Os líderes do povo: Parós, Paate-Moabe, Elão, Zatu, Bani,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bani, Azgade, Bebai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonias, Bigvai, Adim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ezequias, Azur,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodias, Hasum, Besai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Harife, Anatote, Nebai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesulão, Hezir,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesezabel, Zadoque, Jadua,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatias, Hanã, Anaías,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Oseias, Hananias, Hassube,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Haoés, Pílea, Sobeque,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Reum, Hasabna, Maaseias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Aías, Hanã, Anã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Maluque, Harim, e Baaná.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'E o resto do povo, os sacerdotes, os levitas, os porteiros, os cantores, os servos do templo, e todos os que se haviam se separado dos povos das terras para a lei de Deus, suas mulheres, seus filhos e suas filhas, e todo o que tinha compreensão e entendimento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Firmemente se juntaram a seus irmãos, os mais nobres dentre eles, e se comprometeram em um juramento sujeito a maldição, que andariam na lei de Deus, que foi dada por meio de Moisés, servo de Deus, e que guardariam e cumpririam todos os mandamentos do SENHOR nosso Senhor, e seus juízos e seus estatutos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'E que não daríamos nossas filhas aos povos da região, nem tomaríamos suas filhas para nossos filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'E que, se os povos da região trouxessem para vender mercadorias e comida no dia de sábado, nada tomaríamos deles no sábado, nem em dia santo; e deixaríamos livre o sétimo ano, inclusive toda e qualquer cobrança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Também pusemos preceitos sobre nós, impondo-nos a cada ano dar a terça parte de um siclo, para a obra da casa de nosso Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Para os pães da proposição, para a oferta contínua de alimentos, e para a oferta de queima contínua, dos sábados, das novas luas, e das festas solenes, e para as coisas sagradas, e para os sacrifícios pelo pecado para reconciliar a Israel, e para toda a obra da casa de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Também lançamos as sortes entre os sacerdotes, os levitas, e o povo, acerca da oferta da lenha, que havia de se trazer à casa de nosso Deus, segundo as casas de nossos pais, em tempos determinados, a cada ano, para queimar sobre o altar do SENHOR nosso Deus, como está escrito na lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'E que a cada ano traríamos as primícias de nossa terra, e todos os primeiros frutos de toda árvore, para a casa de SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'E também os primogênitos de nossos filhos e de nossas animais, como está escrito na lei; e que traríamos os primogênitos de nossas vacas e de nossas ovelhas à casa de nosso Deus, aos sacerdotes que ministram na casa de nosso Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'E que traríamos as primícias de nossas massas, e nossas ofertas alçadas, e do fruto de toda árvore, do suco de uva e do azeite, aos sacerdotes, às câmaras da casa de nosso Deus, e os dízimos de nossa terra aos levitas; e que os levitas receberiam os dízimos em todas as cidades onde trabalhamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'E que um sacerdote, filho de Arão, estaria com os levitas, quando os levitas recebessem os dízimos; e que os levitas trariam o dízimo dos dízimos à casa de nosso Deus, às câmaras da casa do tesouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Porque para aquelas câmaras os filhos de Israel, e os filhos de Levi, devem trazer a oferta de grão, de suco de uva, e de azeite; e ali estarão os vasos do santuário, como também os sacerdotes que ministram, os porteiros, e os cantores; e assim não abandonaríamos a casa de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'E os líderes do povo habitaram em Jerusalém; porém os demais do povo lançaram sortes para trazerem um de dez para habitar na santa cidade de Jerusalém, e as nove partes nas outras cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'E o povo abençoou a todos os homens que voluntariamente se ofereceram para habitarem em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'E estes são os chefes da província que habitaram em Jerusalém (porém os israelitas, os sacerdotes e os levitas, os servos do templo, e os filhos dos servos de Salomão, nas cidades de Judá, habitaram cada um em sua possessão, em suas cidades).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Habitaram, pois, em Jerusalém, alguns dos filhos de Judá, e dos filhos de Benjamim. Dos filhos de Judá: Ataías, filho de Uzias, filho de Zacarias, filho de Amarias, filho de Sefatias, filho de Maalaleel, dos filhos de Perez;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'E Maaseias filho de Baruque, filho de Col-Hozé, filho de Hazaías, filho de Adaías, filho de Joiaribe, filho de Zacarias, filho de Siloni.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Todos os filhos de Perez que habitaram em Jerusalém foram quatrocentos setenta e oito homens valentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'E estes são os filhos de Benjamim: Salu filho de Mesulão, filho de Joede, filho de Pedaías, filho de Colaías, filho de Maaseias, filho de Itiel, filho de Jesaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'E após ele, Gabai, Salai, novecentos e vinte e oito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'E Joel, filho de Zicri, era o supervisor deles; e Judá filho de Senua, o segundo sobre a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Dos sacerdotes: Jedaías filho de Joiaribe, Jaquim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraías filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, governador da casa de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'E seus irmãos, que faziam a obra da casa, oitocentos vinte e dois; e Adaías filho de Jeroão, filho de Pelalias, filho de Anzi, filho de Zacarias, filho de Pasur, filho de Malquias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'E seus irmãos, chefes de famílias, duzentos e quarenta e dois; e Amassai filho de Azareel, filho de Azai, filho de Mesilemote, filho de Imer,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'E seus irmãos, homens valentes, cento e vinte e oito; e o supervisor sobre eles era Zabdiel, filho de Gedolim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'E dos Levitas: Semaías filho de Hassube, filho de Azricão, filho de Hasabias, filho de Buni;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Sabetai e Jozabade, dos chefes dos Levitas, supervisores da obra de fora da casa de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'E Matanias filho de Mica, filho de Zabdi, filho de Asafe, o chefe, o que começava a ação de graças na oração; e Baquebuquias o segundo de entre seus irmãos; e Abda filho de Samua, filho de Galal, filho de Jedutum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Todos os levitas na santa cidade foram duzentos e oitenta e quatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'E os porteiros, Acube, Talmom, com seus irmãos, os guardas das portas: cento e setenta e dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'E o demais dos israelitas, dos sacerdotes, dos levitas, estevem em todas as cidades de Judá, cada um em sua propriedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'E os servos do templo habitavam em Ofel; e Zia e Gispa governavam sobre os servos do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'E o supervisor dos levitas em Jerusalém foi Uzi, filho de Bani, filho de Hasabias, filho de Matanias, filho de Mica; dos filhos de Asafe estavam os cantores diante da obra da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Porque tinha mandamento do rei acerca deles, e determinação acerca dos cantores para cada dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'E Petaías filho de Mesezabel, dos filhos de Zerá, filho de Judá, estava à mão do rei em todo negócio do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'E quanto às aldeias em suas terras, alguns dos filhos de Judá habitaram em Quiriate-Arba, nas suas aldeias circunvizinhas, em Dibom e suas aldeias circunvizinhas, e em Jecabzeel e suas aldeias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'E em Jesua, Molada, Bete-Pelete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'Hazar-Sual, Berseba, e em suas aldeias circunvizinhas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'E em Ziclague, e em Meconá, e em suas aldeias circunvizinhas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'E em En-Rimom, Zorá Jarmute;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoa, Adulão, e em suas aldeias; em Laquis e suas terras; Azeca e suas aldeias circunvizinhas. E habitaram desde Berseba até o vale de Hinom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'E os filhos de Benjamim desde Geba habitaram em Micmás, Aia, e Betel e suas aldeias circunvizinhas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Em Anatote, Nobe, Ananias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazor, Ramá, Gitaim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadide, Zeboim, Nebalate;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lode, e Ono, no vale dos artífices.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'E alguns dos Levitas, nos repartições de Judá e de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Estes são os sacerdotes e Levitas que subiram com Zorobabel filho de Sealtiel, e com Jesua: Seraías, Jeremias, Esdras,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarias, Maluque, Hatus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Secanias, Reum, Meremote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Ido, Ginetoi, Abias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Miamim, Maadias, Bilga,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaías, e Joiaribe, Jedaías,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Salu, Amoque, Hilquias, Jedaías. Estes eram os chefes dos sacerdotes e seus irmãos nos dias de Jesua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'E os levitas foram:Jesua, Binui, Cadmiel, Serebias, Judá, e Matanias: este e seus irmãos eram responsáveis pelas ações de graças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'E Bacbuquias e Uni, seus irmãos, em frente deles em suas responsabilidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'E Jesua gerou a Joiaquim, e Joiaquim gerou a Eliasibe e Eliasibe gerou a Joiada,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'E Joiada gerou a Jônatas, e Jônatas gerou a Jadua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'E nos dias de Joiaquim os sacerdotes chefes das famílias foram: de Seraías, Meraías; de Jeremias, Hananias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'De Esdras, Mesulão; de Amarias, Joanã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'De Maluqui, Jônatas; de Sebanias, José;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'De Harim, Adna; de Meraiote, Helcai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'De Ido, Zacarias; de Ginetom, Mesulão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'De Abias, Zicri; de Miniamim, e de Moadias, Piltai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'De Bilga, Samua; de Semaías, Jônatas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'De Joiaribe, Matenai; de Jedaías, Uzi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'De Salai, Calai; de Amoque, Éber;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'De Hilquias, Hasabias; de Jedaías, Natanael.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Os Levitas nos dias de Eliasibe, de Joiada, e de Joanã e Jadua, foram escritos por chefes de famílias; como também os sacerdotes, até o reinado de Dario o persa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Os filhos de Levi, chefes de famílias, foram escritos no livro das crônicas até os dias de Joanã, filho de Eliasibe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'E os chefes dos Levitas foram:Hasabias, Serebias, e Jesua filho de Cadmiel, e seus irmãos em frente deles, para louvarem e darem graças, conforme o mandamento de Davi, homem de Deus, cada um com sua responsabilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanias, e Bacbuquias, Obadias, Mesulão, Talmom, Acube, eram porteiros que faziam guarda às entradas das portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Estes foram nos dias de Joiaquim, filho de Jesua, filho de Jozadaque, como também nos dias do governador Neemias, e do sacerdote Esdras, o escriba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'E na dedicação dos muros de Jerusalém buscaram aos Levitas de todos os lugares, para os trazerem a Jerusalém, a fim de fazerem a dedicação com alegrias, com ações de graças, e com cânticos, com címbalos, liras e harpas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'E assim ajuntaram os filhos dos cantores, tanto da planície ao redor de Jerusalém como das aldeias de Netofati;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Como também da casa de Gilgal, e dos campos de Geba, e de Azmavete; porque os cantores haviam edificado para si aldeias ao redor de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'E os sacerdotes e os levitas se purificaram, e depois purificaram ao povo, às portas, e ao muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Então eu fiz subir aos príncipes de Judá sobre o muro, e ordenei dois coros grandes que foram em procissão: um à direita sobre o muro em direção à porta do Esterco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'E após eles ia Hosaías, e a metade dos príncipes de Judá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'E Azarias, Esdras, Mesulão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Judá, Benjamim, Semaías, e Jeremias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'E dos filhos dos sacerdotes com trombetas, Zacarias filho de Jônatas, filho de Semaías, filho de Matanias, filho de Micaías, filho de Zacur, filho de Asafe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'E seus irmãos Semaías, e Azareel, Milalai, Gilalai, Maai, Natanael, Judá e Hanani, com os instrumentos musicais de Davi, homem de Deus; e o escriba Esdras ia diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Indo assim para a porta da Fonte, e em frente deles, subiram pelas escadarias da cidade de Davi, pela subida do muro, desde acima da casa de Davi até a porta das Águas ao oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'E o segundo coro ia do lado oposto, e eu atrás dele; e a metade do povo ia sobre o muro, desde a torre dos Fornos até a muralha larga;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'E desde a porta de Efraim até a porta Velha, e à porta do Peixe, e a torre de Hananeel, e a torre dos Cem, até a porta das Ovelhas; e pararam na porta da Prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Então ambos os coros pararam na casa de Deus; como também eu, e a metade dos oficiais comigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'E os sacerdotes, Eliaquim, Maaseias, Miniamim, Micaías, Elioenai, Zacarias, e Hananias, com trombetas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Como também Maaseias, Semaías, Eleazar, e Uzi, Joanã, Malquias, Elão, e Ezer. E os cantores cantavam alto, juntamente com o supervisor Jezraías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'E sacrificaram naquele dia grandes sacrifícios, e alegraram-se; porque Deus os tinha alegrado muito; alegraram-se também a mulheres e as crianças; e o júbilo de Jerusalém foi ouvido até de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Também naquele dia foram postos homens sobre as câmaras para os tesouros, as ofertas alçadas, as primícias, e os dízimos, para juntarem nelas, dos campos das cidades, as porções da lei para os sacerdotes e os levitas; porque Judá estava alegre por causa dos sacerdotes e dos levitas que estavam servindo ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'E faziam a guarda de seu Deus, e a guarda da purificação, como também os cantores e os porteiros, conforme o mandamento de Davi e de seu filho Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Porque nos dias de Davi e de Asafe, desde a antiguidade, havia chefes dos cantores, e cânticos de louvor e de ações de graças a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'E todo Israel nos dias de Zorobabel, e nos dias de Neemias, dava as porções dos cantores e dos porteiros, cada uma em seu dia; e consagravam porções aos levitas, e os levitas as consagravam aos filhos de Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Naquele dia se leu no livro de Moisés perante os ouvidos do povo, e foi achado nele escrito que os amonitas e os moabitas eternamente não podiam entrar na congregação de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Porque não saíram ao encontro dos filhos de Israel com pão e água; em vez disso, contrataram a Balaão contra eles, para os amaldiçoar; ainda que nosso Deus tornou a maldição em bênção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Sucedeu, pois, que, quando eles ouviram esta lei, separaram de Israel toda mistura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'E antes disto, Eliasibe, o sacerdote, sendo superintendente da câmara da casa de nosso Deus, tinha se aparentado com Tobias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'E tinha lhe preparado uma câmara grande, na qual antes se guardavam as ofertas de alimentos, o incenso, os vasos, os dízimos de grão, de vinho e de azeite, que estava ordenado dar aos levitas, aos cantores, e aos porteiros; como também a oferta alçada para os sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Porém enquanto tudo isto acontecia,eu não estava em Jerusalém; porque no ano trinta e dois de Artaxerxes rei da Babilônia, eu vim ao rei; mas ao fim de alguns dias obtive permissão para me ausentar do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'E vim a Jerusalém, e entendi o mal que Eliasibe tinha feito por Tobias, preparando-lhe uma câmara nos pátios da casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'E isso me desagradou muito; por isso lancei todas as coisas da casa de Tobias para fora da câmara;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'E mandei purificar as câmaras, e trouxe de volta os utensílios da casa de Deus, com as ofertas de alimento, e o incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Também entendi que as porções dos Levitas não estavam sendo dadas a eles; e que os levitas e cantores que faziam o serviço haviam fugido cada um para seu campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Então repreendi aos oficiais, e disse: Por que a casa de Deus está abandonada? Porém eu os juntei, e os restaurei em seu posto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Então todo Judá trouxe o dízimo do grão, do suco de uva e do azeite, aos depósitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'E pus por tesoureiros sobre os depósitos ao sacerdote Selemias e ao escriba Zadoque, e dos Levitas, a Pedaías; e próximo a eles Hanã filho de Zacur, filho de Matanias; pois eram considerados fiéis, e assim foram encarregados de distribuírem a seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Por isto, meu Deus, lembra-te de mim, ó Deus, e não risques minhas bondades que eu fiz na casa de meu Deus, e em seus serviços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Naqueles dias vi em Judá alguns que pisavam em lagares no sábado, e que traziam feixes, e carregavam asnos, como também vinho, uvas, figos, e todo tipo de carga, que traziam a Jerusalém no dia de sábado; e os adverti quanto ao dia em que vendiam alimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Também tírios estavam nela que traziam peixe e toda mercadoria, e vendiam no sábado aos filhos de Judá, e em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Assim repreendi aos nobres de Judá, e disse-lhes: Que mal é este que fazeis, profanando o dia de sábado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Por acaso não fizeram assim vossos pais, e nosso Deus trouxe todo este mal sobre nós e sobre esta cidade? Porém vós acrescentais ainda mais ira sobre Israel profanando o sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Sucedeu pois, que quando ia escurecendo às portas de Jerusalém antes do sábado, disse que eu mandei que se fechassem as portas, e mandei que não as abrissem até depois do sábado; e pus às portas alguns de meus servos, para que carga nenhuma entrasse no dia de sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Assim os comerciantes e vendedores de toda mercadoria passaram a noite fora de Jerusalém uma ou duas vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Por isso eu lhes adverti, dizendo: Por que vos passais a noite diante do muro? Se o fizerdes outra vez, agirei com violência contra vós. Desde então não vieram no sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Também disse aos levitas que se purificassem, e viessem a guardar as portas, para santificar o dia de sábado. Nisto também, meu Deus, lembra-te de mim, e perdoa-me segundo a grandeza de tua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Vi também naqueles dias judeus que tinham se casado com mulheres de asdoditas, amonitas, e moabitas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'E seus filhos a metade falavam asdodita, e não sabiam falar judaico, mas sim a língua de outros povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Por isso eu os repreendi, e os amaldiçoei, e espanquei alguns deles, e arranquei-lhes os cabelos, e os fiz jurar por Deus, dizendo: Não dareis vossas filhas a seus filhos, e não tomareis de suas filhas, nem para vossos filhos, nem para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Por acaso não pecou nisto Salomão, rei de Israel? Ainda que entre muitas nações não houve rei semelhante a ele, que era amado pelo seu Deus, e Deus o tinha posto por rei sobre todo Israel, contudo as mulheres estrangeiras o fizeram pecar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'E aceitaríamos ouvir de vós, para fazerdes todo este mal tão grande de transgredir contra nosso Deus, casando-se com mulheres estrangeiras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'E um dos filhos de Joiada, filho de Eliasibe o sumo sacerdote era genro de Sambalate o horonita; por isso eu o afugentei de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Lembra-te deles, meu Deus, pois contaminam o sacerdócio, como também o pacto do sacerdócio e dos levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Assim eu os limpei de todo estrangeiro, e ordenei as responsabilidades dos sacerdotes e dos levitas, cada um em sua obra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Como também para as ofertas de lenha em tempos determinados, e para as primícias. Lembra-te de mim, meu Deus, para o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'E aconteceu nos dias de Assuero (o Assuero que reinou desde a Índia até Cuxe sobre cento e vinte e sete províncias),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Que naqueles dias, quando o rei Assuero se sentou sobre o trono de seu reino, na fortaleza de Susã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'No terceiro ano de seu reinado, ele fez um banquete a todos seus príncipes e a seus servos, tendo diante dele o exército de Pérsia e da Média, os maiorais e os governadores das províncias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Para mostrar as riquezas da glória de seu reino, e o esplendor de sua majestosa grandeza, por muitos dias: cento e oitenta dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'E acabados aqueles dias, o rei fez um banquete a todo o povo que se achava na fortaleza de Susã, desde o maior até o menor, durante sete dias, no pátio do jardim do palácio real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'As cortinas eram de linho branco e azul celeste, amarradas com cordões de linho fino e púrpura, argolas de prata e colunas de mármore; os leitos eram de ouro e de prata, sobre um piso de pórfiro, mármore, madrepérola e pedras preciosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'E dava-se de beber em taças de ouro, e as taças eram diferentes umas das outras; e havia muito vinho real, conforme a generosidade do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'E de acordo com a lei, a bebida era sem restrições; porque assim o rei tinha mandado a todos os oficiais de sua casa; que fizessem conforme a vontade de cada um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Também a rainha Vasti fez banquete para as mulheres, na casa real do rei Assuero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'No sétimo dia, quando o coração do rei estava alegre do vinho, mandou a Meumã, Bizta, Harbona, Bigtá, Abagta, Zetar, e Carcas, sete eunucos que serviam diante do rei Assuero,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Que trouxessem à rainha Vasti com a coroa real diante do rei, para mostrar aos povos e aos príncipes sua beleza; pois ela tinha linda aparência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Porém a rainha Vasti recusou vir à ordem do rei por meio dos eunucos; por isso o rei se enfureceu muito, e sua ira se acendeu nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Então o rei perguntou aos sábios que entendiam dos tempos (porque assim era o costume do rei para com todos os que sabiam a lei e o direito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'E os mais próximos dele eram Carsena, Setar, Adamata, Társis, Meres, Marsena, e Memucã, sete príncipes da Pérsia e da Média, que viam o rosto do rei, e se sentavam nas posições principais do reino)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'O que se devia fazer segundo a lei com a rainha Vasti, por não ter cumprido a ordem do rei Assuero por meio dos eunucos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Então Memucã disse na presença do rei e dos príncipes: A rainha Vasti pecou não somente contra o rei, mas também contra todos os príncipes, e contra todos os povos que há em todas as províncias do rei Assuero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Pois o que a rainha fez será notícia a todas as mulheres, de modo que desprezarão seus maridos em seus olhos, quando lhes for dito: O rei Assuero mandou trazer diante de si à rainha Vasti, porém ela não veio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Então neste dia as princesas da Pérsia e da Média dirão o mesmo a todos os príncipes do rei, quando ouvirem o que a rainha fez; e assim haverá muito desprezo e indignação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Se for do agrado do rei, seja feito de sua parte um mandamento real, e escreva-se nas leis da Pérsia e da Média, e que não se possa revogar: que Vasti nunca mais venha diante do rei Assuero; e o reino dela seja dado a outra que seja melhor que ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'E quando o mandamento que o rei ordenar for ouvido em todo o seu reino (ainda que seja grande), todas as mulheres darão honra a seus maridos, desde o maior até o menor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'E esta palavra foi do agrado dos olhos do rei e dos príncipes, e o rei fez conforme o que Memucã havia dito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Então enviou cartas a todas a províncias do rei, a cada província segundo sua escrita, e a cada povo segundo sua língua, que todo homem fosse senhor em sua casa, e falasse isto conforme a língua de cada povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Passadas estas coisas, e tendo já sido apaziguado o furor do rei Assuero, ele se lembrou de Vasti, e do que ela havia feito, e do que havia sido sentenciado contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Então os servos do rei, que lhe serviam, disseram: Busquem-se ao rei moças virgens de boa aparência;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'E o rei ponha comissários em todas as províncias de seu reino, para que juntem todas as moças virgens de boa aparência na fortaleza de Susã, na casa das mulheres, ao cuidado de Hegai, eunuco do rei, vigilante das mulheres; e sejam lhes dado seus enfeites;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'E a moça que agradar aos olhos do rei, reine em lugar de Vasti.E isto foi do agrado dos olhos do rei, e ele assim fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Havia um homem judeu na fortaleza de Susã, cujo nome era Mardoqueu, filho de Jair, filho de Simei, filho de Quis, um homem da linhagem de Benjamim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'O qual tinha sido levado de Jerusalém com os cativos que foram levados com Jeconias rei de Judá, a quem Nabucodonosor, rei da Babilônia, havia levado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'E ele tinha criado a Hadassa, que é Ester, filha de seu tio, porque não tinha pai nem mãe; e ela tinha bela forma, e era linda de aparência; e como seu pai e sua mãe tinham morrido, Mardoqueu a havia tomado como sua filha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Sucedeu pois, que quando se divulgou o mandamento do rei e seu lei, e sendo reunidas muitas moças na fortaleza de Susã, ao cuidado de Hegai, também levaram Ester para casa do rei, ao cuidado de Hegai, vigilante das mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'E a moça foi do agrado de seus olhos, e alcançou favor diante dele; por isso ele se apressou em lhe dar seus enfeites e suas porções de alimento, dando-lhe também sete moças escolhidas da casa do rei; e ele a passou com suas moças ao melhor lugar da casa das mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ester, porém, não declarou seu povo nem sua parentela; porque Mardoqueu tinha lhe mandado que não declarasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'E todo dia Mardoqueu passeava diante do pátio da casa das mulheres, para saber como Ester estava, e que estava acontecendo com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'E quando chegava a vez de cada uma das moças para vir ao rei Assuero, ao fim de haver estado doze meses, conforme à lei acerca das mulheres (porque assim se cumpriam os dias de seus enfeites, isto é, seis meses com óleo de mirra, e seis meses com especiarias, e outros enfeites de mulheres),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Então assim a moça vinha ao rei; tudo quanto ela pedia se lhe dava, para vir com isso da casa das mulheres até a casa do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Ela vinha à tarde, e pela manhã voltava à segunda casa das mulheres, ao cuidado de Saasgaz eunuco do rei, vigilante das concubinas; ela não voltava mais ao rei, a não ser se o rei a desejasse, e fosse chamada por nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Chegando, pois, a vez de Ester, filha de Abiail, tio de Mardoqueu (que e havia tinha tomado por filha), para vir ao rei, nenhuma coisa pediu a não ser o que Hegai eunuco do rei, vigilante das mulheres, havia dito; e Ester alcançava o favor aos olhos de todos quantos a viam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Assim Ester foi levada ao rei Assuero a sua casa real no décimo mês, que é o mês de Tebete, no sétimo ano de seu reinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'E o rei amou a Ester mais que todas as mulheres, e alcançou diante dele favor e benevolência mais que todas as virgens; e ele pôs a coroa real em sua cabeça, e a fez rainha em lugar de Vasti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Então o rei fez um grande banquete a todos seus príncipes e servos, o banquete de Ester; e deu repouso às províncias, e deu presentes, conforme a generosidade do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'E quando as virgens se ajuntaram pela segunda vez, Mardoqueu estava sentado à porta do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Ester, porém,não tinha declarado sua parentela nem seu povo, assim como Mardoqueu havia lhe mandado; porque Ester fazia o que Mardoqueu mandava, assim como quando ele a criava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Naqueles dias, estando Mardoqueu sentado à porta do rei, Bigtã e Teres, dois eunucos do rei, dos guardas da porta, ficaram muito indignados, e procuravam matar o rei Assuero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'E isso foi percebido por Mardoqueu; então ele avisou à rainha Ester, e Ester disse ao rei em nome de Mardoqueu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Tendo o caso sido investigado, assim foi achado; e ambos foram pendurados em uma forca. E isso foi registrado nas crônicas diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Depois destas coisas, o rei Assuero engrandeceu a Hamã filho de Hamedata agagita, e o exaltou, e pôs seu assento acima de todos os príncipes que estavam com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'E todos os servos do rei que estavam à porta do rei se inclinavam e prostravam diante de Hamã, porque assim o rei tinha mandado acerca dele; porém Mardoqueu não se inclinava nem se prostrava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Então os servos do rei que estavam à porta do rei disseram a Mardoqueu: Por que transgrides o mandamento do rei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Sucedeu, pois, que, tendo eles dito isto dia após dia, e ele não tendo lhes dado ouvidos, avisaram dele a Hamã, para verem se as palavras de Mardoqueu continuariam; porque ele tinha lhes declarado que era judeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Quando Hamã viu que Mardoqueu não se inclinava nem se prostrava diante dele, ele se encheu de furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Porém, tendo já sido informado do povo de Mardoqueu, ele achou pouco matar apenas Mardoqueu; então Hamã procurou destruir a todos os judeus, o povo de Mardoqueu, que havia no reino de Assuero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'No primeiro mês (que é o mês de Nisã), no décimo segundo ano do rei Assuero, foi lançada Pur, isto é, a sorte, diante de Hamã, para cada dia e para cada mês; e a sorte indicou o décimo segundo mês, o mês de Adar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Então Hamã disse ao rei Assuero: Há um povo disperso e dividido entre os povos em todas as províncias de teu reino, cujas leis são diferentes das de todo o povo, e não obedecem às leis do rei; por isso não convém ao rei tolerá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Se for do agrado do rei, escreva-se que sejam destruídos; e eu porei dez mil talentos de prata nas mãos dos executarem a ação, para que sejam postos na tesouraria do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Então o rei tirou seu anel de sua mão, e o deu a Hamã filho de Hamedata agageu, inimigo dos judeus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'E o rei disse a Hamã: Essa prata te seja dada; e também esse povo, para fazeres dele o que quiseres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Então chamaram aos escrivães do rei no primeiro mês, no dia treze do mesmo, e foi escrito conforme a tudo o que Hamã mandou, aos príncipes do rei, e aos governadores que havia sobre cada província, e aos líderes de cada povo, a cada província conforme sua escrita, e a cada povo conforme sua língua; em nome do rei Assuero foi escrito, e com o anel do rei foi selado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'E foram enviadas cartas por meio de mensageiros a todas as províncias do rei, para destruírem, matarem, e exterminarem a todos os judeus, desde o menino até o velho, crianças e mulheres em um dia, no dia treze do décimo segundo mês (que é o mês de Adar), e para saquearem suas posses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'A cópia do texto foi entregue como decreto para que anunciasse em todas as províncias em público a todos os povos, para que estivessem preparados para aquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Assim os mensageiros, obrigados pela palavra do rei, saíram, e o decreto foi anunciado na fortaleza de Susã. E o rei e Hamã se sentaram para beber; porém a cidade de Susã estava confusa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Quando Mardoqueu soube de tudo quanto havia acontecido, Mordecai rasgou suas vestes, e vestiu-se de saco e de cinza, e saiu andando por meio da cidade, clamando com grande e amargo clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'E chegou até diante da porta do rei, porque ninguém vestido de saco podia entrar pela porta do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'E em toda província e lugar onde a palavra do rei e seu decreto chegava, havia entre os judeus grande luto, jejum, choro, e lamentação; e muitos se deitaram em sacos e cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Então as virgens de Ester e seus eunucos vieram e a informaram; então a rainha teve grande dor, e enviou roupas para vestir a Mardoqueu, e tirar o saco que estava sobre ele; porém ele não as aceitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Então Ester chamou a Hatá, um dos eunucos do rei, que ele tinha posto para a servir, e o mandou a Mardoqueu, para saber o que era aquilo, e por quê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Assim, pois Hatá veio a Mardoqueu à praça da cidade que estava diante da porta do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'E Mardoqueu lhe contou tudo o que tinha lhe acontecido, assim como a soma de prata que Hamã havia dito que daria para a tesouraria do rei por causa dos judeus, para os destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Também lhe deu a cópia da escritura do decreto que tinha sido publicado em Susã para que fossem destruídos, a fim de a mostrar a Ester e a ela informar, e lhe mandar que fosse ao rei para lhe pedir e suplicar diante dele em favor de seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Veio, pois, Hatá, e contou a Ester as palavras de Mardoqueu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Então Ester respondeu a Hatá, e mandou-lhe dizer a Mardoqueu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Todos os servos do rei e o povo das províncias do rei sabem que todo homem ou mulher que entra ao pátio interno na presença rei sem ser chamado, sua sentença é a morte, a não ser se o rei estender o cetro de ouro, para que viva; e eu nestes trinta dias não fui chamada para vir ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'E contaram a Mardoqueu as palavras de Ester.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Então Mardoqueu disse que respondessem a Ester: Não penses em tua alma, que escaparás na casa do rei mais que todos os outros judeus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Porque se te calares agora, haverá alívio e libertação para os judeus de outra parte; porém tu e a casa de teu pai perecereis. E quem sabe se foi para tempo como este que chegaste a ser rainha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Então Ester disse que respondessem a Mardoqueu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Vai, e junta a todos os judeus que se acham em Susã, e jejuai por mim, e não comais nem bebais durante três dias, nem de noite nem de dia; eu e minhas virgens também assim jejuaremos; e assim virei ao rei, ainda que não seja segundo à lei; e se eu perecer, perecerei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Então Mardoqueu se foi, e fez conforme tudo quanto Ester lhe mandara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Aconteceu, pois, que ao terceiro dia Ester se vestiu de vestes reais, e se pôs no pátio de dentro da casa do rei, de frente ao aposento do rei; e o rei estava sentado em seu trono real no aposento real, em frente da porta do aposento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'E foi que, quando ele viu a rainha Ester, que estava no pátio, ela alcançou favor em seus olhos; e o rei apontou para Ester o cetro de ouro que tinha em sua mão. Então Ester se aproximou, e tocou a ponta do cetro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Então o rei disse: O que tens, rainha Ester? E qual é a tua petição? Até a metade do reino será dada a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'E Ester respondeu: Se for do agrado do rei, venha o rei hoje com Hamã ao banquete que lhe tenho preparado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Então o rei disse: Fazei Hamã se apressar a fazer o que Ester disse. Assim o rei veio com Hamã ao banquete que Ester havia preparado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'O rei perguntou a Ester no banquete do vinho: Qual é a tua petição, para que te seja concedida? Qual é o teu pedido? Ainda que seja a metade do reino, será feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Então Ester respondeu, dizendo: Minha petição e minha demanda é:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Se tenho achado favor aos olhos do rei, e se agrada ao rei conceder minha petição e fazer cumprir o meu pedido, que o rei venha com Hamã ao banquete que lhes prepararei; e amanhã farei conforme o que o rei tem dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Então Hamã saiu naquele dia contente e alegre de coração; porém, quando viu a Mardoqueu à porta do rei, e que ele não se levantava nem se movia por ele, então Hamã se encheu de furor contra Mardoqueu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Porém Hamã se conteve, e veio a sua casa, e mandou vir seus amigos, e a Zeres sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'E Hamã lhes contou a glória de seus riquezas, e a multidão de seus filhos, e tudo em que o rei tinha lhe engrandecido e lhe exaltado sobre os príncipes e servos do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Hamã também disse: Até a rainha Ester a ninguém fez vir com o rei ao banquete que ela preparou, a não ser a mim; e ainda amanhã sou convidado dela juntamente com o rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Porém tudo isto não me satisfaz, enquanto eu ver o judeu Mardoqueu sentado à porta do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Então sua mulher Zeres e todos os seus amigos lhe disseram: Seja feita uma forca de cinquenta côvados de altura, e amanhã dize ao rei para que nela enforquem a Mardoqueu; e então vai alegre com o rei ao banquete. E este conselho foi do agrado de Hamã, e ele mandou fazer a forca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Naquela noite o rei perdeu o sono. Então ele mandou trazer o livro das memórias das crônicas: e elas foram lidas na presença do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'E achou-se escrito que Mardoqueu havia denunciado Bigtã e de Teres, dois eunucos do rei, da guarda da porta, que tinham procurado matar o rei Assuero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Então o rei disse: Que honra e que condecoração se fez a Mardoqueu por isto? E os servos do rei que o serviam disseram: Nada foi feito com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Então o rei disse: Quem está no pátio? (Pois Hamã tinha vindo ao pátio de fora da casa do rei, para dizer ao rei que enforcassem a Mardoqueu na forca que tinha preparado para ele).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'E os servos do rei lhe responderam: Eis que Hamã está no pátio. E o rei mandou que ele entrasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Quando Hamã entrou, o rei lhe perguntou: Que se fará ao homem a quem rei deseja honrar? Então Hamã pensou em seu coração: A quem o rei desejará mais dar honra que a mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Por isso Hamã respondeu ao rei: Ao homem a quem o rei deseja honrar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Tragam o vestido real de que o rei costuma se vestir, o cavalo em que o rei costuma cavalgar, e ponha-se a coroa real sobre sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'E entregue-se o vestido e o cavalo na mão de um dos mais importantes príncipes do rei, e vistam a tal homem a quem o rei deseja honrar, e levem-no a cavalo pelas ruas da cidade, e proclamem diante dele: Assim se fará ao homem a quem o rei deseja honrar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Então o rei disse a Hamã: Apressa-te, toma o vestido e o cavalo, como disseste, e faze assim para com o judeu Mardoqueu, que se senta à porta do rei; não omitas coisa alguma de tudo quanto disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'E Hamã tomou o vestido e o cavalo, e vestiu a Mardoqueu; e o levou a cavalo pelas ruas da cidade, e proclamou diante dele: Assim se fará ao homem a quem o rei deseja honrar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Depois disto Mardoqueu voltou à porta do rei. Porém Hamã se retirou correndo para sua casa, aborrecido, e com sua cabeça coberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'E Hamã contou a sua mulher Zeres e a todos seus amigos tudo o que tinha lhe acontecido; então seus sábios e sua mulher Zeres lhe disseram: Se Mardoqueu, diante de quem começaste a cair, é da semente dos judeus, tu não prevalecerás contra ele; ao contrário, certamente cairás diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Enquanto eles ainda estavam falando com ele, os eunucos do rei chegaram, apressados, para levarem Hamã ao banquete que Ester havia preparado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Veio, pois, o rei com Hamã para beber com a rainha Ester.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'O rei disse também a Ester no segundo dia do banquete do vinho: Qual é tua petição, rainha Ester, para que te seja concedida? Qual é o teu pedido? Ainda que seja a metade do reino, será feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Então a rainha Ester respondeu e disse: Ó rei, se tenho achado favor em teus olhos, e se for do agrado do rei, seja me dada minha vida por minha petição, e meu povo por meu pedido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Porque estamos vendidos, eu e meu povo, para sermos destruídos, mortos e exterminados. Se apenas fôssemos ser vendidos como escravos e escravas, eu ficaria calada, pois tal opressão não compensaria incomodar ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Então o rei Assuero respondeu à rainha Ester: Quem é esse, e onde está esse, que se atreveu a pensar em fazer assim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'E Ester disse: O homem opressor e inimigo é este malvado Hamã. Então Hamã se perturbou diante do rei e da rainha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'E o rei, em seu furor, se levantou do banquete do vinho, e foi ao jardim do palácio; e Hamã ficou em pé para suplicar à rainha Ester por sua vida; pois entendeu que o rei já havia decidido o mal contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Quando o rei voltou do jardim do palácio ao lugar do banquete do vinho, Hamã estava caído sobre o leito em que Ester estava. Então disse o rei: Por acaso ele também queria abusar da rainha diante de mim nesta casa? Assim que esta palavra saiu da boca do rei, cobriram o rosto de Hamã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Então Harbona, um dos eunucos que estavam na presença do rei, disse: Eis que há uma forca de cinquenta côvados de altura que Hamã fez para Mardoqueu, o qual falou para o bem do rei, junto à casa de Hamã. Então o rei disse: Enforcai-o nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Assim enforcaram a Hamã na forca que ele tinha mandado preparar para Mardoqueu; então o furor do rei se apaziguou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Naquele mesmo dia o rei Assuero deu à rainha Ester a casa de Hamã, inimigo dos judeus; e Mardoqueu veio diante do rei, porque Ester lhe declarara o que ele era dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'E o rei tirou o seu anel que tinha tomado de Hamã, e o deu a Mardoqueu. E Ester pôs a Mardoqueu sobre o comando da casa de Hamã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Ester falou novamente diante do rei, e lançou-se a seus pés, chorando e suplicando-lhe que revogasse a maldade de Hamã, agagita, e seu plano que tinha tramado contra os judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Então o rei apontou para Ester o cetro de ouro; e Ester se levantou, e se pôs em pé diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'E disse: Se for do agrado do rei, e se tenho achado favor diante dele, e se for correto perante o rei, e se eu lhe agrado em seus olhos, escreva-se que sejam revogadas as cartas do plano de Hamã, filho de Hamedata, agagita, que ele escreveu para destruir os judeus que estão em todas as províncias do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Pois como poderei eu ver o mal que sobrevirá a meu povo? Como poderei eu ver a destruição dos meus parentes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Então o rei Assuero respondeu à rainha Ester e ao judeu Mardoqueu: Eis que dei a Ester a casa de Hamã, e a ele enforcaram na forca, por ter tentado matar os judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Escrevei, pois, vós aos judeus como bem vos parecer em nome do rei, e selai o com o anel do rei; porque a escritura que é selada com o anel do rei, não pode ser revogada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Então foram chamados os escrivães do rei naquele mesmo instante, no terceiro mês (que é Sivã), ao dia vinte e três do mesmo; e escreveu-se conforme tudo quanto Mardoqueu mandou, aos judeus, como também aos sátrapas, aos governadores, e aos líderes das províncias, que se estendem da Índia até Cuxe, cento e vinte e sete províncias, a cada província segundo sua escrita, e a cada povo conforme sua língua; como também aos judeus conforme sua escrita, e conforme sua língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'E escreveu-se em nome do rei Assuero, e selou-se com o anel do rei; e as cartas foram enviados por meio dos mensageiros por correios a cavalo, que cavalgavam sobre velozes cavalos, os quais pertenciam ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Que o rei concedia aos judeus que havia em todas a cidades, que se ajuntassem e se pusessem em defesa de suas vidas, para destruírem, matarem e exterminarem todas as tropas de povo e província que viesse contra eles, até a crianças como a mulheres, e os despojassem de seus bens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Em um mesmo dia, em todas as províncias do rei Assuero, no dia treze do décimo segundo mês, que é o mês de Adar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'A cópia da carta dada como decreto em todas as províncias foi anunciada publicamente a todos os povo, para que os judeus estivessem preparados para aquele dia, para se vingarem de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Os mensageiros, sobre cavalos velozes, saíram apressadamente, impelidos pela ordem do rei; e o decreto também foi publicado na fortaleza de Susã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Então Mardoqueu saiu de diante do rei com vestido real de azul celeste e branco, como também com uma grande coroa de ouro, e um manto de linho e púrpura; e a cidade de Susã jubilou e se alegrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'E para os judeus houve luz, alegria, júbilo, e honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Também em cada província e em cada cidade aonde chegava a palavra do rei e seu decreto, havia entre os judeus alegria e júbilo, banquetes e dia de prazer. E muitos dos povos da terra se tornaram como judeus, porque o temor aos judeus havia caído sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'E no décimo segundo mês (que é o mês de Adar), no dia treze do mesmo, em que chegou o prazo para a palavra do rei se seu decreto serem executados, no mesmo dia em que os inimigos dos judeus esperavam vencê-los, sucedeu o contrário, porque foram os judeus que venceram aqueles que os odiavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Os judeus se ajuntaram em suas cidades em todas as províncias do rei Assuero, para atacarem os que procuravam lhes fazer mal; e ninguém pôde subsistir diante deles, porque o temor a eles tinha caído sobre todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'E todos os governadores das províncias, e os sátrapas, e os líderes, e os oficiais do rei, auxiliavam os judeus; porque o temor a Mardoqueu tinha caído sobre eles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Porque Mardoqueu era grande na casa do rei, e sua fama ia por todas as províncias; pois o homem Mardoqueu havia se engrandecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Assim os judeus feriram a todos os seus inimigos com golpes de espada, matança, e destruição; e fizeram o que quiseram daqueles que os odiavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'E na fortaleza de Susã os judeus mataram e destruíram quinhentos homens,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Inclusive a Parsandata, Dalfom, Aspata,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Porata, Adalia, Aridata,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Farmasta, Arisai, Aridai, e a Vaisata,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Os dez filhos de Hamã filho de Hamedata, inimigo dos judeus; porém não puseram suas mãos no despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'No mesmo dia veio diante do rei a contagem dos mortos na fortaleza de Susã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'E o rei disse à rainha Ester: Na fortaleza de Susã, os judeus mataram e destruíram a quinhentos homens, e aos dez filhos de Hamã; nas demais províncias do rei, o que teriam feito? Qual pois é tua petição, para que te seja concedida? Ou qual mais é teu pedido, para que te seja feito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Então Ester disse: Se for do agrado do rei, conceda-se também amanhã aos judeus em Susã, que façam conforme a lei de hoje; e que enforquem na forca os dez filhos de Hamã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Então o rei disse que assim se fizesse; e deu-se a ordem em Susã, e enforcaram aos dez filhos de Hamã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'E os judeus que estavam em Susã se ajuntaram também no dia catorze do mês de Adar, e mataram trezentos homens em Susã; porém não puseram suas mãos no despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Também os demais judeus que estavam nas províncias do rei se ajuntaram e para se porem em defesa de sua vida, e terem repouso de seus inimigos; e mataram a setenta e cinco mil daqueles que os odiavam; porém não puseram suas mãos no despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Sucedeu isto no dia treze do mês de Adar; e repousaram no dia catorze do mesmo, e fizeram dele um dia de banquetes e de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Também os judeus que estavam em Susã se ajuntaram nos dias treze e catorze do mesmo mês; e no dia quinze do mesmo repousaram, e fizeram daquele dia um dia de banquetes e de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Por isso os judeus das aldeias, que habitavam nas cidades se muros, fizeram o dia catorze do mês de Adar um dia de alegria, de banquetes, e dia de festejo; e de mandarem presentes uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'E Mardoqueu escreveu estas coisas, e enviou cartas a todos os judeus que havia em todas as províncias do rei Assuero, próximos e distantes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Ordenando-lhes que comemorassem o décimo quarto dia do mês de Adar, e o décimo quinto do mesmo, todos os anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Como os dias em que os judeus tiveram repouso de seus inimigos; e o mês que tornou para eles de tristeza em alegria, e de luto em dia de festejo; para que os fizessem dias de banquetes e de alegria, e de mandarem presentes uns aos outros, e de doações aos pobres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'E os judeus aceitaram fazer o que já tinham começado assim como o que Mardoqueu havia lhes escrito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Porque Hamã filho de Hamedata, o agagita, inimigo de todos os judeus, tinha planejado destruir todos os judeus, e lançou Pur, isto é, sorte, para os oprimir e os destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Mas quando isto veio diante do rei, ele deu ordem por cartas, que seu plano maligno, que tramara contra os judeus, tornasse sobre sua cabeça; assim enforcaram a ele e a seus filhos na forca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Por isso aqueles dias foram chamados Purim, por causa do nome Pur. Portanto, por causa de todas as palavras daquela carta; e do que testemunharam quanto a isso, e do que veio sobre eles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Os judeus confirmaram e comprometeram a si mesmos e a seus descendentes, e a todos os que se fossem próximos deles, que não deixariam de comemorar estes dois dias conforme o que foi escrito deles, e conforme seu tempo determinado, todos os anos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'E que estes dias seriam lembrados e comemorados em todas as gerações, famílias, províncias, e cidades; e que estes dias de Purim não seriam ignorados pelos judeus, e que sua lembrança nunca teria fim entre seus descendentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Depois disto a rainha Ester, filha de Abiail, e o judeu Mardoqueu, escreveram com todo poder, para confirmarem pela segunda vez esta carta de Purim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'E foram enviadas cartas a todos os judeus, às cento e vinte e sete províncias do rei Assuero, com palavras de paz e de verdade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Para confirmarem estes dias de Purim em seus tempos determinados, conforme o judeu Mardoqueu e a rainha Ester tinham lhes confirmado, e como eles mesmos já o confirmaram para si e para seus descendentes; acerca do jejum e de seu clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'E o mandamento de Ester confirmou estas palavras dadas acerca de Purim, e escreveu-se em um livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'E o rei Assuero impôs um tributo sobre a terra e sobre as ilhas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'E todas as obras de seu poder e de seu valor, e a declaração da grandeza de Mardoqueu, a quem o rei engrandeceu, por acaso não estão escritas no livro das crônicas dos reis da Média e da Pérsia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Pois o judeu Mardoqueu foi o segundo depois do rei Assuero, e grande entre os judeus, e agradável à multidão de seus irmãos, procurando o bem de seu povo, e falando prosperidade para todo o seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Havia um homem na terra de Uz, cujo nome era Jó; e este homem era íntegro e correto, temente a Deus, e que se afastava do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'E nasceram-lhe sete filhos e três filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'E seu patrimônio era sete mil ovelhas, três mil camelos, quinhentas juntas de bois, e quinhentas jumentas; ele também tinha muitíssimos servos, de maneira que este homem era o maior de todos do oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'E seus filhos iam nas casas uns dos outros para fazerem banquetes, cada um em seu dia; e mandavam convidar as suas três irmãs, para que comessem e bebessem com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'E acontecia que, acabando-se o revezamento dos dias de banquetes, Jó enviava e os santificava, e se levantava de madrugada para apresentar ofertas de queima conforme o número de todos eles. Pois Jó dizia: Talvez meus filhos tenham pecado, e tenham amaldiçoado a Deus em seus corações. Assim Jó fazia todos aqueles dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'E em certo dia, os filhos de Deus vieram para se apresentarem diante do SENHOR, e Satanás também veio entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Então o SENHOR disse a Satanás: De onde vens? E Satanás respondeu ao SENHOR, dizendo: De rodear a terra, e de passear por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'E o SENHOR disse a Satanás: Tendes visto meu servo Jó? Pois ninguém há na terra semelhante a ele, homem íntegro e correto, temente a Deus, e que se afasta de mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Então Satanás respondeu ao SENHOR, dizendo: Por acaso Jó teme a Deus em troca de nada?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Por acaso tu não puseste uma cerca ao redor dele, de sua casa, e de tudo quanto ele tem? Tu abençoaste o trabalho de suas mãos, e seu patrimônio tem crescido sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Mas estende agora tua mão, e toca em tudo quanto ele tem; e verás se ele não te amaldiçoa em tua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'E o SENHOR disse a Satanás: Eis que tudo quanto ele tem está em tua mão; somente não estendas tua mão contra ele. E Satanás saiu de diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'E sucedeu um dia que seus filhos e filhas estavam comendo e bebendo vinho na casa de seu irmão primogênito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Que veio um mensageiro a Jó, que disse: Enquanto os bois estavam arando, e as jumentas se alimentando perto deles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Eis que os sabeus atacaram, e os tomaram, e feriram os servos a fio de espada; somente eu escapei para te trazer a notícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Enquanto este ainda estava falando, veio outro que disse: Fogo de Deus caiu do céu, que incendiou as ovelhas entre os servos, e os consumiu; somente eu escapei para te trazer-te a notícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Enquanto este ainda estava falando, veio outro que disse: Os caldeus formaram três tropas, e atacaram os camelos, e os tomaram, e feriram os servos a fio de espada; somente eu escapei para te trazer a notícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Enquanto este ainda estava falando, veio outro que disse: Teus filhos e tuas filhas estavam comendo e bebendo vinho em casa de seu irmão primogênito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'E eis que veio um grande vento do deserto, e atingiu os quatro cantos da casa, que caiu sobre os jovens, e morreram; somente eu escapei para te trazer a notícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Então Jó se levantou, rasgou sua capa, rapou sua cabeça, e caindo na terra, adorou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'E disse: Nu saí do ventre de minha mãe, e nu para lá voltarei. O SENHOR deu, e o SENHOR tomou; bendito seja o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Em tudo isto Jó não pecou, nem atribuiu a Deus falta alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'E veio outro dia em que os filhos de Deus vieram para se apresentarem diante do SENHOR, e e Satanás também veio entre eles para se apresentar diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Então o SENHOR disse a Satanás: De onde vens? E Satanás respondeu ao SENHOR, e dizendo: De rodear a terra, e de passear por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'E o SENHOR disse a Satanás: Tendes visto meu servo Jó? Pois ninguém há semelhante a ele na terra, homem íntegro e correto, temente a Deus e que se afasta do mal; e que ainda mantém sua integridade, mesmo depois de teres me incitado contra ele, para o arruinar sem causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Então Satanás respondeu ao SENHOR, dizendo: Pele por pele, e tudo quanto o homem tem, dará por sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Mas estende agora tua mão, e toca em seus ossos e sua carne, e verás se ele não te amaldiçoa em tua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'E o SENHOR disse a Satanás: Eis que ele está em tua mão; mas preserva sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Então Satanás saiu de diante do SENHOR, e feriu a Jó de chagas malignas desde a planta de seus pés até a topo de sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'E Jó tomou um caco para se raspar com ele, e ficou sentado no meio da cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Então sua mulher lhe disse: Ainda manténs a tua integridade? Amaldiçoa a Deus, e morre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Porém ele lhe disse: Tu falas como uma tola. Receberíamos o bem de Deus, e o mal não receberíamos? Em tudo isto Jó não pecou com seus lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Quando três amigos de Jó, Elifaz temanita, Bildade suíta, e Zofar naamita, ouviram todo este mal que lhe tinha vindo sobre ele, vieram cada um de seu lugar; porque haviam combinado de juntamente virem para se condoerem dele, e o consolarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Eles, quando levantaram seus olhos de longe, não o reconheceram; e choraram em alta voz; e cada um deles rasgou sua capa, e espalharam pó ao ar sobre suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Assim se sentaram com ele na terra durante sete dias e sete noites, e nenhum lhe falava palavra alguma, pois viam que a dor era muito grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Depois disto Jó abriu sua boca, e amaldiçoou seu dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Pois Jó respondeu, e disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Pereça o dia em que nasci, e a noite em que se disse: Um homem foi concebido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Torne-se aquele dia em trevas; Deus não lhe dê atenção desde acima, nem claridade brilhe sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Reivindiquem-no para si trevas e sombra de morte; nuvens habitem sobre ele; a escuridão do dia o espante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Tome a escuridão aquela noite; não seja contada entre os dias do ano, nem faça parte do número dos meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Ah se aquela noite fosse solitária, e música de alegria não viesse a ela!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Amaldiçoem-na os que amaldiçoam o dia, os que se preparam para levantar seu pranto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Escureçam-se as estrelas de sua manhã; espere a luz, e não venha, e as pálpebras não vejam o amanhecer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Pois não fechou as portas do ventre onde eu estava, nem escondeu de meus olhos o sofrimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Por que eu não morri desde a madre, ou perdi a vida ao sair do ventre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Por que joelhos me receberam? E por que seios me amamentaram?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Pois agora eu jazeria e repousaria; dormiria, e então haveria repouso para mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Com os reis e os conselheiros da terra, que edificavam para si os desertos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Ou com os príncipes que tinham ouro, que enchiam suas casas de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Ou por que não fui como um aborto oculto, como as crianças que nunca viram a luz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Ali os maus deixam de perturbar, e ali repousam os cansados de forças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Ali os prisioneiros juntamente repousam; e não ouvem a voz do opressor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Ali estão o pequeno e o grande; e o servo livre está de seu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Por que se dá luz ao sofredor, e vida aos amargos de alma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Que esperam a morte, e ela não chega, e que a buscam mais que tesouros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Que saltam de alegram e ficam contentes quando acham a sepultura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'E também ao homem cujo caminho é oculto, e a quem Deus o encobriu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Pois antes do meu pão vem meu suspiro; e meus gemidos correm como águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Pois aquilo eu temia tanto veio a mim, e aquilo que tinha medo me aconteceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Não tenho tido descanso, nem tranquilidade, nem repouso; mas perturbação veio sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Então Elifaz o temanita respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Se tentarmos falar contigo, ficarás incomodado? Mas quem poderia deter as palavras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Eis que tu ensinavas a muitos, e fortalecias as mãos fracas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Tuas palavras levantavam aos que tropeçavam, e fortificavas os joelhos que desfaleciam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Mas agora isso que aconteceu contigo, tu te cansas; e quando isso te tocou, te perturbas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Por acaso não era o teu temor a Deus a tua confiança, e a integridade dos teus caminhos tua esperança?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Lembra-te agora, qual foi o inocente que pereceu? E onde os corretos foram destruídos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Como eu tenho visto, os que lavram injustiça e semeiam opressão colhem o mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Com o sopro de Deus eles perecem, e pelo vento de sua ira são consumidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'O rugido do leão, a voz do leão feroz, e os dentes dos leões jovens são quebrantados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'O leão velho perece por falta de presa, e os filhotes da leoa se dispersam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Uma palavra me foi dita em segredo, e meu ouvidos escutaram um sussurro dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Em imaginações de visões noturnas, quando o sono profundo cai sobre os homens,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Espanto e tremor vieram sobre mim, que espantou todos os meus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Então um vento passou por diante de mim, que fez arrepiar os pelos de minha carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Ele parou, mas não reconheci sua feição; uma figura estava diante de meus olhos, e ouvi uma voz quieta, que dizia:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Seria o ser humano mais justo que Deus? Seria o homem mais puro que seu Criador?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Visto que ele não confia em seus servos, e considera seus anjos como loucos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Quanto mais naqueles que habitam em casas de lodo, cujo fundamento está no pó, e são esmagáveis como a traça!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Desde a manhã até a tarde são despedaçados, e perecem sempre, sem que ninguém perceba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Por acaso sua excelência não se perde com eles mesmos? Eles morrem sem sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Clama agora! Haverá alguém que te responda? E a qual dos santos te voltarás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Pois a ira acaba com o louco, e o zelo mata o tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Eu vi ao louco lançar raízes, porém logo amaldiçoei sua habitação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Seus filhos estarão longe da salvação; na porta são despedaçados, e não há quem os livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'O faminto devora sua colheita, e a tira até dentre os espinhos; e o assaltante traga sua riqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Porque a aflição não procede do pó da terra, nem a opressão brota do chão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Mas o ser humano nasce para a opressão, assim como as faíscas das brasas se levantam a voar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Porém eu buscaria a Deus, e a ele confiaria minha causa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Pois ele é o que faz coisas grandiosas e incompreensíveis, e inúmeras maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Ele é o que dá a chuva sobre a face da terra, e envia águas sobre os campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Ele põe os humildes em lugares altos, para que os sofredores sejam postos em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Ele frustra os planos dos astutos, para que suas mãos nada consigam executar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Ele prende aos sábios em sua própria astúcia; para que o conselho dos perversos seja derrubado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'De dia eles se encontram com as trevas, e ao meio-dia andam apalpando como de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Porém livra ao necessitado da espada de suas bocas, e da mão do violento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Pois ele é esperança para o necessitado, e a injustiça tapa sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Eis que bem-aventurado é o homem a quem Deus corrige; portanto não rejeites o castigo do Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Pois ele faz a chaga, mas também põe o curativo; ele fere, mas suas mãos curam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Em seis angústias ele te livrará, e em sete o mal não te tocará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Na fome ele te livrará da morte, e na guerra livrará do poder da espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Do açoite da língua estarás encoberto; e não temerás a destruição quando ela vier.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Tu rirás da destruição e da fome, e não temerás os animais da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Pois até com as pedras do campo terás teu pacto, e os animais do campo serão pacíficos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'E saberás que há paz em tua tenda; e visitarás tua habitação, e não falharás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Também saberás que tua semente se multiplicará, e teus descendentes serão como a erva da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Na velhice virás à sepultura, como o amontoado de trigo que se recolhe a seu tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Eis que é isto o que temos constatado, e assim é; ouve-o, e pensa nisso tu para teu bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Mas Jó respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Oh se pesassem justamente minha aflição, e meu tormento juntamente fosse posto em uma balança!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Pois na verdade seria mais pesada que a areia dos mares; por isso minhas palavras têm sido impulsivas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Porque as flechas do Todo-Poderoso estão em mim, cujo veneno meu espírito bebe; e temores de Deus me atacam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Por acaso o asno selvagem zurra junto à erva, ou o boi berra junto a seu pasto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Por acaso se come o insípido sem sal? Ou há gosto na clara do ovo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Minha alma se recusa tocar essas coisas,que são para mim como comida detestável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Ah se meu pedido fosse realizado, e se Deus me desse o que espero!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Que Deus me destruísse; ele soltasse sua mão, e acabasse comigo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Isto ainda seria meu consolo, um alívio em meio ao tormento que não me poupa; pois eu não tenho escondido as palavras do Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Qual é minha força para que eu espere? E qual meu fim, para que eu prolongue minha vida?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'É, por acaso, a minha força a força de pedras? Minha carne é de bronze?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Tenho eu como ajudar a mim mesmo, se todo auxílio me foi tirado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Ao aflito, seus amigos deviam ser misericordiosos, mesmo se ele tivesse abandonado o temor ao Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Meus irmãos foram traiçoeiros comigo, como ribeiro, como correntes de águas que transbordam,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Que estão escurecidas pelo gelo, e nelas se esconde a neve;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Que no tempo do calor se secam e, ao se aquecerem, desaparecem de seu lugar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Os cursos de seus caminhos se desviam; vão se minguando, e perecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'As caravanas de Temã as veem; os viajantes de Sabá esperam por elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Foram envergonhados por aquilo em que confiavam; e ao chegarem ali, ficaram desapontados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Agora, vós vos tornastes semelhantes a elas; pois vistes o terror, e temestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Por acaso eu disse: Trazei-me algo? Ou: Dai presente a mim de vossa riqueza?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Ou: Livrai-me da mão do opressor? Ou: Resgatai-me das mãos dos violentos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Ensinai-me, e eu me calarei; e fazei-me entender em que errei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Como são fortes as palavras de boa razão! Mas o que vossa repreensão reprova?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Pretendeis repreender palavras, sendo que os argumentos do desesperado são como o vento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'De fato vós lançaríeis sortes sobre o órfão, e venderíeis vosso amigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Agora, pois, disponde-vos a olhar para mim; e vede se eu minto diante de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Mudai de opinião, pois, e não haja perversidade; mudai de opinião, pois minha justiça continua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Há perversidade em minha língua? Não poderia meu paladar discernir as coisas más?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Por acaso o ser humano não tem um trabalho duro sobre a terra, e não são seus dias como os dias de um assalariado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Como o servo suspira pela sombra, e como o assalariado espera por seu pagamento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Assim também me deram por herança meses inúteis, e me prepararam noites de sofrimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Quando eu me deito, pergunto: Quando me levantarei? Mas a noite se prolonga, e me canso de me virar na cama até o amanhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Minha carne está coberta de vermes e de crostas de pó; meu pele está rachada e horrível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Meus dias são mais rápidos que a lançadeira do tecelão, e perecem sem esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Lembra-te que minha vida é um sopro; meus olhos não voltarão a ver o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Os olhos dos que me veem não me verão mais; teus olhos estarão sobre mim, porém deixarei de existir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'A nuvem se esvaece, e passa; assim também quem desce ao mundo dos mortos nunca voltará a subir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Nunca mais voltará à sua casa, nem seu lugar o conhecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Por isso eu não calarei minha boca; falarei na angústia do meu espírito, e me queixarei na amargura de minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Por acaso sou eu o mar, ou um monstro marinho, para que me ponhas guarda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Quando eu digo: Minha cama me consolará; meu leito aliviará minhas queixa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Então tu me espantas com sonhos, e me assombras com visões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Por isso minha alma preferia a asfixia e a morte, mais que meus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Odeio a minha vida; não viverei para sempre; deixa-me, pois que meus dias são inúteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'O que é o ser humano, para que tanto o estimes, e ponhas sobre ele teu coração,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'E o visites a cada manhã, e a cada momento o proves?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Até quando não me deixarás, nem me liberarás até que eu engula minha saliva?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Se pequei, o eu que te fiz, ó Guarda dos homens? Por que me fizeste de alvo de dardos, para que eu seja pesado para mim mesmo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'E por que não perdoas minha transgressão, e tiras minha maldade? Porque agora dormirei no pó, e me buscarás de manhã, mas não existirei mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Então Bildade, o suíta, respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Até quando falarás tais coisas, e as palavras de tua boca serão como um vento impetuoso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Por acaso Deus perverteria o direito, ou o Todo-Poderoso perverteria a justiça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Se teus filhos pecaram contra ele, ele também os entregou ao castigo por sua transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Se tu buscares a Deus com empenho, e pedires misericórdia ao Todo-Poderoso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Se fores puro e correto, certamente logo ele se levantará em teu favor, e restaurará a morada de tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Ainda que teu princípio seja pequeno, o teu fim será muito grandioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Pois pergunta agora à geração passada, e considera o que seus pais descobriram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Pois nós somos de ontem e nada sabemos, pois nossos dias sobre a terra são como a sombra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Por acaso eles não te ensinarão, e te dirão, e falarão palavras de seu coração?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Pode o papiro crescer sem lodo? Ou pode o junco ficar maior sem água?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Estando ele ainda verde, sem ter sido cortado, ainda assim se seca antes de toda erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Assim são os caminhos de todos os que esquecem de Deus; e a esperança do corrupto perecerá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Sua esperança será frustrada, e sua confiança será como a teia de aranha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Ele se apoiará em sua casa, mas ela não ficará firme; ele se apegará a ela, mas ela não ficará de pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Ele está bem regado diante do sol, e seus ramos brotam por cima de sua horta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Suas raízes se entrelaçam junto à fonte, olhando para o pedregal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Se lhe arrancarem de seu lugar, este o negará, dizendo: Nunca te vi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Eis que este é o prazer de seu caminho; e do solo outros brotarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Eis que Deus não rejeita ao íntegro, nem segura pela mão aos malfeitores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Ainda ele encherá tua boca de riso, e teus lábios de júbilo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Os que te odeiam se vestirão de vergonha, e nunca mais haverá tenda de perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Mas Jó respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Na verdade sei que é assim; mas como pode o ser humano ser justo diante de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Ainda se quisesse disputar com ele, não conseguiria lhe responder uma coisa sequer em mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Ele é sábio de coração, e poderoso em forças. Quem se endureceu contra ele, e teve paz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Ele transporta as montanhas sem que o saibam; e as transtorna em seu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Ele remove a terra de seu lugar, e faz suas colunas tremerem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Ele dá ordem ao sol, e ele não brilha; e sela as estrelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Ele é o que sozinho estende os céus, e anda sobre as alturas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Ele é o que fez a Usra, o Órion, as Plêiades, e as constelações do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Ele é o que faz coisas grandes e incompreensíveis, e inúmeras maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Eis que ele passa diante de mim, sem que eu não o veja; ele passará diante de mim, sem que eu saiba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Eis que, quando ele toma, quem pode lhe impedir? Quem poderá lhe dizer: O que estás fazendo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Deus não reverterá sua ira, e debaixo dele se encurvam os assistentes de Raabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Como poderia eu lhe responder, e escolher minhas palavras contra ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'A ele, ainda que eu fosse justo, não lhe responderia; a meu juiz pediria misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Ainda que eu lhe chamasse, e ele respondesse, mesmo assim não creria que ele tivesse dado ouvidos à minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Pois ele tem me quebrantado com tempestade, e multiplicado minhas feridas sem causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Ele não me permite respirar; em vez disso, me farta de amarguras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Quanto às forças, eis que ele é forte; e quanto ao juízo, ele diria: Quem me convocará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Ainda que eu seja justo, minha boca me condenaria; se eu fosse inocente, então ela me declararia perverso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Mesmo se eu for inocente, não estimo minha alma; desprezo minha vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'É tudo a mesma coisa; por isso digo: ele consome ao inocente e ao perverso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Quando o açoite mata de repente, ele ri do desespero dos inocentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'A terra está entregue nas mãos dos perversos. Ele cobre o rosto de seus juízes. Se não é ele, então quem é?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Meus dias foram mais rápidos que um homem que corre; fugiram, e não viram o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Passaram como barcos de papiro, como a águia que se lança à comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Se disser: Esquecerei minha queixa, mudarei o aspecto do meu rosto, e sorrirei,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Ainda teria pavor de todas as minhas dores; pois sei que não me terás por inocente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Se eu já estou condenado, então para que eu sofreria em vão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Ainda que me lave com água de neve, e limpe minhas mãos com sabão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Então me submergirias no fosso, e minhas próprias vestes me abominariam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Pois ele não é homem como eu, para que eu lhe responda, e venhamos juntamente a juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Não há entre nós árbitro que ponha sua mão sobre nós ambos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Tire de sobre mim sua vara, e seu terror não me espante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Então eu falaria, e não teria medo dele. Pois não está sendo assim comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Minha alma está cansada de minha vida. Darei liberdade à minha queixa sobre mim; falarei com amargura de minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Direi a Deus: Não me condenes; faz-me saber por que brigas comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Parece -te bem que me oprimas, que rejeites o trabalho de tuas mãos, e favoreças o conselho dos perversos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Tens tu olhos de carne? Vês tu como o ser humano vê?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'São teus dias como os dias do ser humano, ou teus anos como os anos do homem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Para que investigues minha perversidade, e pesquises meu pecado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Tu sabes que eu não sou mau; todavia ninguém há que me livre de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tuas mãos me fizeram e me formaram por completo; porém agora tu me destróis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Por favor, lembra-te que me preparaste como o barro; e me farás voltar ao pó da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Por acaso não me derramaste como o leite, e como o queijo me coalhaste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'De pele e carne tu me vestiste; e de ossos e nervos tu me teceste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Vida e misericórdia me concedeste, e teu cuidado guardou meu espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Porém estas coisas escondeste em teu coração; eu sei que isto esteve contigo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Se eu pecar, tu me observarás, e não absolverás minha culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Se eu for perverso, ai de mim! Mesmo se eu for justo, não levantarei minha cabeça; estou farto de desonra, e de ver minha aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Se minha cabeça se exaltar, tu me caças como um leão feroz, e voltas a fazer em coisas extraordinárias contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Renovas tuas testemunhas contra mim, e multiplicas tua ira sobre mim; combates vêm sucessivamente contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Por que me tiraste da madre? Bom seria se eu não tivesse respirado, e nenhum olho me visse!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Teria sido como se nunca tivesse existido, e desde o ventre materno seria levado à sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Por acaso não são poucos os meus dias? Cessa pois e deixa-me, para que eu tenha um pouco de alívio,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Antes que eu me vá para não voltar, à terra da escuridão e da sombra de morte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Terra escura ao extremo, tenebrosa, sombra de morte, sem ordem alguma, onde a luz é como a escuridão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Então Zofar, o naamita, respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Por acaso a multidão de palavras não seria respondida? E o homem falador teria razão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Por acaso tuas palavras tolas faria as pessoas se calarem? E zombarias tu, e ninguém te envergonharia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Pois disseste: Minha doutrina é pura, e eu sou limpo diante de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Mas na verdade, queria eu que Deus falasse, e abrisse seus lábios contra ti,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'E te fizesse saber os segredos da sabedoria, porque o verdadeiro conhecimento tem dois lados; por isso sabe tu que Deus tem te castigado menos que mereces por tua perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Podes tu compreender os mistérios de Deus? Chegarás tu à perfeição do Todo-Poderoso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Sua sabedoria é mais alta que os céus; que poderás tu fazer? E mais profunda que o mundo dos mortos; o que podes tu saber?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Sua medida é mais comprida que a terra, e mais larga que o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Se ele passar, e prender, ou se ajuntar para o julgamento,quem poderá o impedir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Pois ele conhece as pessoas vãs, e vê a maldade; por acaso ele não a consideraria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'O homem tolo se tornará entendido quando do asno selvagem nascer um humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Se tu preparares o teu coração, e estenderes a ele tuas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Se alguma maldade houver em tua mão, lança-a de ti, e não deixes a injustiça habitar em tuas tendas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Então levantarás teu rosto sem mácula; estarás firme, e não temerás;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'E esquecerás teu sofrimento, ou lembrarás dele como de águas que já passaram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'E tua vida será mais clara que o meio-dia; ainda que haja trevas, tu serás como o amanhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'E serás confiante, porque haverá esperança; olharás em redor, e repousarás seguro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'E te deitarás, e ninguém te causará medo; e muitos suplicarão a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Porém os olhos dos maus se enfraquecerão, e o refúgio deles perecerá; a esperança deles será a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Porém Jó respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Verdadeiramente vós sois o povo; e convosco morrerá a sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Também eu tenho entendimento como vós; e não sou inferior a vós; e quem há que não saiba coisas como essas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Eu sou o motivo de riso de meus amigos, eu que invocava a Deus, e ele me respondia; o justo e íntegro serve de riso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'A desgraça é menosprezada na opinião de quem está tranquilo, que está pronto para os que tropeçam com os pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'As tendas dos ladrões têm descanso, e os que irritam a Deus estão seguros; os que trazem seu deus em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Verdadeiramente pergunta agora aos animais, que eles te ensinarão; e às aves dos céus, que elas te explicarão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Ou fala com a terra, que ela te ensinará; até os peixes do mar te contarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Quem entre todas estas coisas não entende que a mão do SENHOR faz isto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Em sua mão está a alma de tudo quanto vive, e o espírito de toda carne humana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Por acaso o ouvido não distingue as palavras, e o paladar prova as comidas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Nos velhos está o conhecimento, e na longa idade o entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Com Deus está a sabedoria e a força; o conselho e o entendimento lhe pertencem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Eis que o que ele derruba não pode ser reconstruído; e ninguém pode libertar o homem a quem ele aprisiona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Eis que, quando ele detém as águas, elas se secam; quando ele as deixa sair, elas transtornam a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Com ele está a força e a sabedoria; Seu é o que erra, e o que faz errar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Ele leva os conselheiros despojados, e faz os juízes enlouquecerem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Ele solta a atadura dos reis, e ata um cinto a seus lombos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Ele leva os sacerdotes despojados, e transtorna os poderosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Ele tira a fala daqueles a quem os outros confiam, e tira o juízo dos anciãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Ele derrama menosprezo sobre os príncipes, e afrouxa o cinto dos fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Ele revela as profundezas das trevas, e traz a sombra de morte à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Ele multiplica as nações, e ele as destrói; ele dispersa as nações, e as reúne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Ele tira o entendimento dos líderes do povo da terra, e os faz vaguear pelos desertos, sem caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Nas trevas andam apalpando, sem terem luz; e os faz cambalear como a bêbados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Eis que meus olhos têm visto tudo isto; meus ouvidos o ouviram, e entenderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Assim como vós o sabeis, eu também o sei; não sou inferior a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Mas eu falarei com o Todo-Poderoso, e quero me defender para com Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Pois na verdade vós sois inventores de mentiras; todos vós sois médicos inúteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Bom seria se vos calásseis por completo, pois seria sabedoria de vossa parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Ouvi agora meu argumento, e prestai atenção aos argumentos de meus lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Por acaso falareis perversidade por Deus, e por ele falareis engano?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Fareis acepção de sua pessoa? Brigareis em defesa de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Seria bom para vós se ele vos investigasse? Enganareis a ele como se engana a algum homem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Certamente ele vos repreenderá, se em oculto fizerdes acepção de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Por acaso a majestade dele não vos espantará? E o temor dele não cairá sobre sobre vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vossos conceitos são provérbios de cinzas; vossas defesas são como defesas de lama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Calai-vos diante de mim, e eu falarei; e venha sobre mim o que vier.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Por que tiraria eu minha carne com meus dentes, e poria minha alma em minha mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Eis que, ainda que ele me mate, nele esperarei; porém defenderei meus caminhos diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Ele mesmo será minha salvação; pois o hipócrita não virá perante ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Ouvi com atenção minhas palavras, e com vossos ouvidos minha declaração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Eis que já tenho preparado minha causa; sei que serei considerado justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Quem é o que brigará comigo? Pois então eu me calaria e morreria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Somente duas coisas não faças comigo; então eu não me esconderei de teu rosto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Afasta tua mão de sobre mim, e teu terror não me espante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Chama, e eu responderei; ou eu falarei, e tu me responde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Quantas culpas e pecados eu tenho? Faze-me saber minha transgressão e meu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Por que escondes teu rosto, e me consideras teu inimigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Por acaso quebrarás a folha arrebatada pelo vento? E perseguirás a palha seca?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Por que escreves contra mim amarguras, e me fazes herdar as transgressões de minha juventude?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Também pões meus pés no tronco, e observas todos os meus caminhos. Tu pões limites às solas dos meus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Eu me consumo como a podridão, como uma roupa que a traça rói.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'O homem, nascido de mulher, é curto de dias, e farto de inquietação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Ele sai como uma flor, e é cortado; foge como a sombra, e não permanece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Contudo sobre este abres teus olhos, e me trazes a juízo contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Quem tirará algo puro do imundo? Ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Visto que seus dias já estão determinados, e contigo está o número de seus meses, tu lhe puseste limites, dos quais ele não passará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Desvia-te dele, para que ele tenha repouso; até que, como o empregado, complete seu dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Porque há ainda alguma esperança para a árvore que, se cortada, ainda se renove, e seus renovos não cessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Ainda que sua raiz se envelheça na terra, e seu tronco morra no solo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Ao cheiro das águas ela brotará, e dará ramos como uma planta nova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Porém o homem morre, e se abate; depois de expirar, onde ele está?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'As águas se vão do lago, e o rio se esgota, e se seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Assim o homem se deita, e não se levanta; até que não haja mais céus, eles não despertarão, nem se erguerão de seu sono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Queria eu me esconder no mundo dos mortos, e me ocultar até que tua ira se afastasse, e me pusesses um limite de tempo,e te lembrasses de mim!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Se o homem morrer, voltará a viver? Todos os dias de meu combate esperarei, até que venha minha dispensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Tu me chamarás, e eu te responderei; e te afeiçoarás à obra de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Pois então tu contarias meus passos, e não ficarias vigiando meu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Minha transgressão estaria selada numa bolsa, e tu encobririas minhas perversidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'E assim como a montanha cai e é destruída, e a rocha muda de seu lugar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'E a água desgasta as pedras, e as enxurradas levam o pó da terra, assim também tu fazes perecer a esperança do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Sempre prevaleces contra ele, e ele passa; tu mudas o aspecto de seu rosto, e o despedes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Se seus filhos vierem a ter honra, ele não saberá; se forem humilhados, ele não perceberá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Ele apenas sente as dores em sua própria carne, e lamenta por sua própria alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Então Elifaz, o temanita, respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Por acaso o sábio dará como resposta vão conhecimento, e encherá seu ventre de vento oriental?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Repreenderá com palavras que nada servem, e com argumentos que de nada aproveitam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Porém tu destróis o temor, e menosprezas a oração diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Pois tua perversidade conduz tua boca, e tu escolheste a língua dos astutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Tua boca te condena, e não eu; e teus lábios dão testemunho contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Por acaso foste tu o primeiro ser humano a nascer? Ou foste gerado antes dos morros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Ouviste tu o segredo de Deus? Reténs tu apenas contigo a sabedoria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'O que tu sabes que nós não saibamos? O que tu entendes que não tenhamos entendido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Entre nós também há os que tenham cabelos grisalhos, também há os que são muito mais idosos que teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Por acaso as consolações de Deus te são poucas? As mansas palavras voltadas a ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Por que o teu coração te arrebata, e por que centelham teus olhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Para que vires teu espírito contra Deus, e deixes sair tais tais palavras de tua boca?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'O que é o homem, para que seja puro? E o nascido de mulher, para que seja justo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Eis que Deus não confia em seus santos, nem os céus são puros diante de seus olhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Quanto menos o homem, abominável e corrupto, que bebe a maldade como água?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Escuta-me; eu te mostrarei; eu te contarei o que vi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, '(O que os sábios contaram, o que não foi encoberto por seus pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'A somente os quais a terra foi dada, e estranho nenhum passou por meio deles):');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Todos os dias do perverso são sofrimento para si, o número de anos reservados ao opressor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Ruídos de horrores estão em seus ouvidos; até na paz lhe sobrevém o assolador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Ele não crê que voltará da escuridão; ao contrário, a espada o espera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Anda vagueando por comida, onde quer que ela esteja. Ele sabe que o dia das trevas está prestes a acontecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Angústia e aflição o assombram, e prevalecem contra ele como um rei preparado para a batalha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Porque ele estendeu sua mão contra Deus, e se embraveceu contra o Todo-Poderoso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Corre contra ele com dureza de pescoço, e como seus escudos grossos e levantados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Porque cobriu seu rosto com sua gordura, e engordou as laterais de seu corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'E habitou em cidades desoladas cidades, em casas desabitadas; que estavam prestes a desmoronar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Ele não enriquecerá, nem seu patrimônio subsistirá, nem suas riquezas se estenderão pela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Não escapará das trevas; a chama secará seus ramos, e ao sopro de sua boca desparecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Não confie ele na ilusão para ser enganado; pois a sua recompensa será nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Não sendo ainda seu tempo, ela se cumprirá; e seu ramo não florescerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Sacudirá suas uvas antes de amadurecerem como a vide, e derramará sua flor como a oliveira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Pois a ajuntamento dos hipócritas será estéril, e fogo consumirá as tendas do suborno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Eles concebem a maldade, e dão à luz a perversidade; e o ventre deles prepara enganos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Porém Jó respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Ouvi muitas coisas como estas; todos vós sois consoladores miseráveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Por acaso terão fim as palavras de vento? Ou o que é que te provoca a responderes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Também eu poderia falar como vós, se vossa alma estivesse no lugar da minha alma; eu poderia amontoar palavras contra vós, e contra vós sacudir minha cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Porém eu vos confortaria com minha boca, e a consolação de meus lábios serviria para aliviar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Ainda que eu fale, minha dor não cessa; e se eu me calar, em que me alivio?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Na verdade agora ele me tornou exausto; tu assolaste toda a minha companhia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Testemunha disto é que já me enrugaste; e minha magreza já se levanta contra mim para em meu rosto dar testemunho contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sua ira me despedaça, e ele me odeia; range seus dentes contra mim; meu adversário aguça seus olhos contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Abrem sua boca contra mim; com desprezo esbofeteiam meu rosto, e todos se ajuntam contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Deus me entregou ao perverso, e me fez cair nas mãos dos malignos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Tranquilo eu estava, porém ele me quebrantou; e pegou-me pelo pescoço, e me despedaçou; e fez de mim seu alvo de pontaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Seus flecheiros me cercaram-me, partiu meus rins, e não me poupou; meu fel derramou em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Quebrantou-me de quebrantamento sobre quebrantamento; correu contra mim como um guerreiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Costurei saco sobre minha pele, e revolvi minha cabeça no pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Meu rosto está vermelho de choro, e minhas pálpebras estão escurecidas ao extremo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Apesar de não haver injustiça em minhas mãos, e de minha oração ser pura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ó terra! Não cubras o meu sangue, e não haja lugar para meu clamor!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Eis que mesmo agora minha testemunha está nos céus, e meu defensor nas alturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Meus amigos zombam de mim, mas meus olhos estão derramando para Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Ah, se fosse possível defender a causa com Deus em favor do homem, como o filho do homem em favor de seu amigo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Pois poucos anos restam, e seguirei o caminho por onde não voltarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Meu espírito está arruinado, meus dias vão se extinguindo, e a sepultura já etá pronta para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Comigo há ninguém além de zombadores, e meus olhos são obrigados a ficar diante de suas provocações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Concede-me, por favor, uma garantia para comigo; quem outro há que me dê a mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Pois aos corações deles tu encobriste do entendimento; portanto não os exaltarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Aquele que denuncia a seus amigos em proveito próprio, também os olhos de seus filhos desfalecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Ele tem me posto por ditado de povos, e em meu rosto é onde eles cospem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Por isso meus olhos se escureceram de mágoa, e todos os membros de meu corpo são como a sombra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Os íntegros pasmarão sobre isto, e o inocente se levantará contra o hipócrita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'E o justo prosseguirá seu caminho, e o puro de mãos crescerá em força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Mas, na verdade, voltai-vos todos vós, e vinde agora, pois sábio nenhum acharei entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Meus dias se passaram, meus pensamentos foram arrancados, os desejos do meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Tornaram a noite em dia; a luz se encurta por causa das trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Se eu esperar, o mundo dos mortos será minha casa; nas trevas estenderei minha cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'À cova chamo: Tu és meu pai; e aos vermes: Vós sois minha mãe e minha irmã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Onde pois estaria agora minha esperança? E minha esperança quem a poderá ver?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Descerão aos ferrolhos do mundo dos mortos? Descansaremos juntos no pó da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Então Bildade, o suíta, respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Quando é que dareis fim às palavras? Prestai atenção, e então falaremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Por que somos considerados animais, e tolos em vossos olhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Ó tu, que despedaças tua alma com tua ira; será a terra abandonada por tua causa, e será movida a rocha de seu lugar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Na verdade, a luz dos perverso se apagará, e a faísca de seu fogo não brilhará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'A luz se escurecerá em sua tenda, e sua lâmpada sobre ele se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Os seus passos fortes serão encurtados, e seu próprio intento o derrubará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Pois será lançado à rede pelos seus próprios pés, e sobre fios enredados andará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Laço o pegará pelo calcanhar; a armadilha o prenderá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Uma corda lhe está escondida debaixo da terra, e uma armadilha para ele está no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Assombros o espantarão ao redor, e o farão correr por onde seus passos forem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Sua força se tornará em fome, e a perdição está pronta ao seu lado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Partes de sua pele serão consumidas; o primogênito da morte devorará os membros de seu corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Será arrancado de sua tenda em que confiava, e será levado ao rei dos assombros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Em sua tenda morará o que não é seu; enxofre se espalhará sobre a sua morada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Por debaixo suas raízes se secarão, e por cima seus ramos serão cortados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Sua memória perecerá da terra, e não terá nome pelas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Será lançado da luz para as trevas, e expulso será do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Não terá filho nem neto entre seu povo, nem sobrevivente em suas moradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Os do ocidente se espantarão com o seu dia, e os do oriente ficarão horrorizados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Assim são as moradas do perverso, e este é o lugar daquele que não reconhece a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Porém Jó respondeu dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Até quando atormentareis minha alma, e me quebrantareis com palavras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Já dez vezes me humilhastes; não tendes vergonha em me maltratar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Mesmo se eu tiver errado, meu erro cabe apenas a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Visto que vos exaltais contra mim, e contra mim usais minha desgraça,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Sabei, pois, que foi Deus que me transtornou, e com sua rede me cercou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Eis que eu clamo: Violência! Porém não sou respondido; grito, porém não há justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Ele entrincheirou meu caminho, de modo que não consigo passar; e pôs trevas sobre minhas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Ele me despojou de minha honra, e tirou a coroa de minha cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Ele me derrubou por todos os lados, e pereço; e arrancou minha esperança como a uma árvore.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'E fez inflamar contra mim sua ira, e me considerou para consigo como a um de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Juntas vieram suas tropas; prepararam contra mim seu caminho, e se acamparam ao redor de minha tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Ele afastou meus irmãos para longe de mim; e os que me conheciam agora me estranham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Meus parentes me deixaram, e meus conhecidos se esqueceram de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Os moradores de minha casa e minhas servas me tiveram por estranho; estrangeiro me tornei em seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Chamei a meu servo, e ele não respondeu; de minha própria boca eu lhe suplicava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Meu hálito é estranho à minha mulher, e sou repugnante aos filhos de minha mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Até os meninos me desprezam; quando eu me levanto, falam contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Todos os meus amigos próximos me abominam; e até aqueles que eu amava se viraram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Meus ossos se grudaram à minha pele e à minha carne; e escapei só com a pele de meus dentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Compadecei-vos de mim, meus amigos, compadecei-vos de mim; pois a mão de Deus me tocou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Por que vós me perseguis como Deus, e não vos fartais de minhas carne?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ah se minhas palavras fossem escritas! Ah se fossem escritas em um livro!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Que com ponta de ferro e com chumbo fossem esculpidas em pedra para sempre!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Pois eu sei que meu Redentor vive, e ao fim se levantará sobre a terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'E mesmo depois de consumida minha pele, então em minha carne verei a Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Ao qual eu verei para mim, e meus olhos o verão, e não outro. Isto é o que minhas entranhas anseiam dentro de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Se disserdes: Como o perseguiremos? Pois a raiz do problema se acha em mim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Temei vós mesmos a espada; pois furor há nos castigos pela espada; para que assim saibais que haverá julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'E Zofar, o naamita, respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Por isso meus meus pensamentos me fazem responder; por causa da agitação dentro de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Eu ouvi a repreensão que me envergonha; mas o espírito desde o meu entendimento responderá por mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Por acaso não sabes isto, que foi desde a antiguidade, desde que o ser humano foi posto no mundo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Que o júbilo dos perversos é breve, e a alegria do hipócrita dura apenas um momento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Ainda que sua altura subisse até o céu, e sua cabeça chegasse até as nuvens,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Mesmo assim com o seu excremento perecerá para sempre; os que houverem o visto, dirão: Onde ele está?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Como um sonho voará, e não será achado; e será afugentado como a visão noturna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'O olho que já o viu nunca mais o verá; nem seu lugar olhará mais para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Seus filhos procurarão o favor dos pobres; e suas mãos devolverão a sua riqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Seus ossos estão cheios de sua juventude, que juntamente com ele se deitará no pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Se o mal é doce em sua boca, e o esconde debaixo de sua língua;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Se o guarda para si, e não o abandona; ao contrário, o retém em sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Sua comida se mudará em suas entranhas, veneno de cobras será em seu interior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Engoliu riquezas, porém as vomitará; Deus as tirará de seu ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Veneno de cobras subará; língua de víbora o matará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Não verá correntes, rios, e ribeiros de mel e de manteiga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Restituirá o trabalho e não o engolirá; da riqueza de seu comério não desfrutará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Pois oprimiu e desamparou aos pobres; roubou a casa que não edificou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Por não ter sentido sossego em seu ventre, nada preservará de sua tão desejada riqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nada lhe restou para que devorasse; por isso sua riqueza não será duradoura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Estando cheio de sua fartura, ainda estará angustiado; todo o poder da miséria virá sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Quando ele estiver enchendo seu vendre, Deus mandará sobre ele o ardor de sua ira, e a choverá sobre ele em sua comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Ainda que fuja das armas de ferro, o arco de bronze o atravessará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Ele a tirará de seu corpo, e a ponta brilhante atingirá seu fígado; haverá sobre ele assombros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Todas as trevas estão reservadas para seus tesouros escondidos; um fogo não assoprado o consumirá; acabará com o que restar em sua tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Os céus revelarão sua maldade, e a terra se levantará contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'As riquezas de sua casa serão transportadas; nos dias de sua ira elas se derramarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Esta é a parte que Deus dá ao homem perverso, a herança que Deus lhe prepara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Porém Jó respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Ouvi atentamente minhas palavras, e seja isto vossas consolações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Suportai-me, e eu falarei; e depois de eu ter falado, então zombai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Por acaso eu me queixo de algum ser humano? Porém ainda que assim fosse,por que meu espírito não se angustiaria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Olhai-me, e espantai-vos; e ponde a mão sobre a boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Pois quando eu me lembro disto,me assombro, e minha carne é tomada de tremor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Por que razão os perversos vivem, envelhecem, e ainda crescem em poder?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Seus filhos progridem com eles diante de seus rostos; e seus descendentes diante de seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Suas casas têm paz, sem temor, e a vara de Deus não está contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Seus touros procriam, e não falham; suas vacas geram filhotes, e não abortam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Suas crianças saem como um rebanho, e seus filhos saem dançando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Levantam a voz ao som de tamboril e de harpa e se alegram ao som de flauta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Em prosperidade gastam seus dias, e em um momento descem ao mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Assim dizem a Deus: Afasta-te de nós, porque não queremos conhecer teus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Quem é o Todo-Poderoso, para que o sirvamos? E de que nos aproveitará que oremos a ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Eis que sua prosperidade não se deve às mãos deles. Longe de mim esteja o conselho dos perversos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Quantas vezes sucede que a lâmpada dos perversos se apaga, e sua perdição vem sobre eles, e Deus em sua ira lhes reparte dores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Eles serão como palha diante do vento, como o restos de palha que o turbilhão arrebata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Vós dizeis: Deus guarda sua violência para seus filhos. Que Deus pague ao próprio perverso,para que o conheça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Seus olhos vejam sua ruína, e beba da ira do Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Pois que interesse teria ele em sua casa depois de si, quando o número for cortado o número de seus meses?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Poderia alguém ensinar conhecimento a Deus, que julga até os que estão no alto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Alguém morre na sua força plena, estando todo tranquilo e próspero,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Seus baldes estando cheios de leite, e o tutano de seus ossos umedecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Porém outro morre com amargura de alma, nunca tendo experimentado a prosperidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Juntamente jazem no pó, e os vermes os cobrem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Eis que eu sei vossos pensamentos, e os mais intentos que planejais contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Porque dizeis: Onde está a casa do príncipe?, e: Onde está tenda das moradas dos perversos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Por acaso não perguntastes aos que passam pelo caminho, e não conheceis seus sinais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Que os maus são preservados no dia da destruição, e são livrados no dia das fúrias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Quem lhe denunciará seu caminho em sua face? E quem lhe pagará pelo que ele fez?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Finalmente ele é levado à sepultura, e no túmulo fazem vigilância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Os torrões do vale lhe são doces; e todos o seguem; e adiante dele estão inúmeros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Como, pois, me consolais em vão, já que vossas em vossas respostas só resta falsidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Então Elifaz, o temanita, respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Por acaso o homem será de algum proveito a Deus? Pode ele se beneficiar de algum sábio?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'É útil ao Todo-Poderoso que sejas justo? Ganha ele algo se os teus caminhos forem íntegros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Acaso ele te repreende e vem contigo a juízo por causa da tua reverência?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ou não será por causa de tua grande malícia, e de tuas maldades que não têm fim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Porque tomaste penhor a teus irmãos sem causa, e foste tu que tiraste as roupas dos nus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Não deste de beber água ao cansado, e negaste o pão ao faminto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Porém o homem poderoso teve a terra; e o homem influente habitava nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Às viúvas despediste vazias, e os braços dos órfãos foram quebrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Por isso que há laços ao redor de ti, e espanto repentino te perturbou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Ou trevas, para que não vejas; e inundação de água te cobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Por acaso Deus não está na altura dos céus? Olha, pois, para o cume das estrelas, como estão elevadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Porém tu dizes: O que Deus sabe? Como ele julgará por entre a escuridão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'As nuvens são seu esconderijo, e ele não vê; ele passeia pela abóbada do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Por acaso deste atenção para o velho caminho que pisaram os homens injustos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Tais foram cortados antes de tempo; sobre o fundamento deles foi derramada uma enchente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Eles diziam a Deus: Afasta-te de nós! O que o Todo-Poderoso pode fazer por nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Sendo ele o que havia enchido suas casas de bens. Seja, porém, longe de mim o conselho dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Os justos virão e se alegrarão; e o inocente os escarnecerá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Dizendo: Certamente nossos adversários foram destruídos, e o que sobrou deles o fogo consumiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Reconcilia-te, pois, com Deus,e terás paz; assim o bem virá a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Aceita, pois, a instrução de sua boca, e põe suas palavras em teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Se te converteres ao Todo-Poderoso, serás edificado; se afastares a maldade de tua tenda,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'E lançares teu ouro no pó, o ouro de Ofir junto às rochas dos ribeiros,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Então o próprio Todo-Poderoso será teu ouro, e tua prata maciça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Porque então te deleitarás no Todo-Poderoso, e levantarás teu rosto a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Orarás a ele, e ele te ouvirá; e tu lhe pagarás teus votos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Aquilo que tu determinares se cumprirá a ti, e em teus caminhos a luz brilhará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Quando alguém for abatido, e tu disseres: Haja exaltação, Então Deus salvará ao humilde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Ele libertará até ao que não é inocente, que será livrado pela pureza de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Porém Jó respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Até hoje minha queixa é uma amargura; a mão de Deus sobre mim é mais pesada que meu gemido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ah se eu soubesse como poderia achá-lo! Então eu me chegaria até seu trono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Apresentaria minha causa diante dele, e encheria minha boca de argumentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Eu saberia as palavras que ele me responderia, e entenderia o que me diria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Por acaso ele brigaria comigo com seu grande poder? Não, pelo contrário, ele me daria atenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Ali o íntegro pleitearia com ele, e eu me livraria para sempre de meu Juiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Eis que se eu for ao oriente, ele não está ali; se for ao ocidente, e não o percebo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Se ao norte ele opera, eu não o vejo; se ele se esconde ao sul, não o enxergo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Porém ele conhece meu caminho: Provar-me-á, e sairei como ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Meus pés seguiram seus passos; guardei seu caminho, e não me desviei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Nunca retirei de mim o preceito de seus lábios, e guardei as palavras de sua boca mais que minha porção de comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Porém se ele está decidido, quem poderá o desviar? O que sua alma quiser, isso fará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Pois ele cumprirá o que está determinado para mim; ele ainda tem muitas coisas como estas consigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Por isso eu me perturbo em sua presença. Quando considero isto,tenho medo dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Deus enfraqueceu meu coração; o Todo-Poderoso tem me perturbado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Pois não estou destruído por causa das trevas, nem por causa da escuridão que encobriu meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Por que os tempos não são marcados pelo Todo-Poderoso? Por que os que o conhecem não veem seus dias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Há os que mudam os limites de lugar, roubam rebanhos, e os apascentam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Levam o asno do órfão; penhoram o boi da viúva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Desviam do caminho aos necessitados; os pobres da terra juntos se escondem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Eis que como asnos selvagens no deserto eles saem a seu trabalho buscando insistentemente por comida; o deserto dá alimento a ele e a seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'No campo colhem sua forragem, e vindimam a vinha do perverso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Passam a noite nus, por falta de roupa; sem terem coberta contra o frio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Pelas correntes das montanhas são molhados e, não tendo abrigo, abraçam-se às rochas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Há os que arrancam ao órfão do peito, e do pobre tomam penhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Ao nus fazem andar sem vestes, e fazem os famintos carregarem feixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Entre suas paredes espremem o azeite; pisam os lagares, e ainda têm sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Desde a cidade as pessoas gemem, e as almas dos feridos clamam; Mas Deus não dá atenção ao erro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Há os que se opõem à luz; não conhecem seus caminhos, nem permanecem em suas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'De manhã o homicida se levanta, mata ao pobre e ao necessitado, e de noite ele age como ladrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'O olho do adúltero aguarda o crepúsculo, dizendo: Olho nenhum me verá; E esconde seu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Nas trevas vasculham as casas, de dia eles se trancam; não conhecem a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Porque a manhã é para todos eles como sombra de morte; pois são conhecidos dos pavores de sombra de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Ele é ligeiro sobre a superfície das águas; maldita é sua porção sobre a terra; não se vira para o caminho das vinhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'A seca e o calor desfazem as águas da neve; assim também o mundo dos mortos faz aos que pecaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'A mãe se esquecerá dele; doce será para os vermes; nunca mais haverá memória dele,e a perversidade será quebrada como um árvore.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Aflige à mulher estéril, que não dá à luz; e nenhum bem faz à viúva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Mas Deus arranca aos poderosos com seu poder; quando Deus se levanta, não há vida segura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Se ele lhes dá descanso, nisso confiam; mas os olhos de Deus estão postos nos caminhos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'São exaltados por um pouco de tempo,mas logo desaparecem; são abatidos, encerrados como todos, e cortados como cabeças das espigas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Se não é assim, quem me desmentirá, ou anulará minhas palavras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Então Bildade, o suíta, respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'O domínio e o temor estão com ele; ele faz paz em suas alturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Por acaso suas tropas têm número? E sobre quem não se levanta sua luz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Como, pois, o ser humano seria justo para com Deus? E como seria puro aquele que nasce de mulher?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Eis que até a luz não tem brilho; nem as estrelas são puras diante de seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Quanto menos o ser humano, que é uma larva, e o filho de homem, que é um verme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Porém Jó respondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Como tende ajudado ao que não tem força, e sustentado ao braço sem vigor!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Como tende aconselhado ao que não tem conhecimento, e lhe explicaste detalhadamente a verdadeira causa!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'A quem tens dito tais palavras? E de quem é o espírito que sai de ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Os mortos tremem debaixo das águas com os seus moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'O mundo dos mortos está nu diante de Deus,e não há cobertura para a perdição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Ele estende o norte sobre o vazio, suspende a terra sobre o nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Ele amarra as águas em suas nuvens, todavia a nuvem não se rasga debaixo dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Ele encobre a face de seu trono, e sobre ele estende sua nuvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Ele determinou limite à superfície das águas, até a fronteira entre a luz e as trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'As colunas do céu tremem, e se espantam por sua repreensão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Ele agita o mar com seu poder, e com seu entendimento fere abate a Raabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Por seu Espírito adornou os céus; sua mão perfurou a serpente veloz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Eis que estas são somente as bordas de seus caminhos; e quão pouco é o que temos ouvido dele! Quem, pois, entenderia o trovão de seu poder?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'E Jó prosseguiu em falar seu discurso, e disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Vive Deus, que tirou meu direito, o Todo-Poderoso, que amargou minha alma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Que enquanto meu fôlego estiver em mim, e o sopro de Deus em minhas narinas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Meus lábios não falarão injustiça, nem minha língua pronunciará engano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Nunca aconteça que eu diga que vós estais certos; até eu morrer nunca tirarei de mim minha integridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Eu me apegarei à minha justiça, e não a deixarei ir; meu coração não terá de que me acusar enquanto eu viver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Seja meu inimigo como o perverso, e o que se levantar contra mim como o injusto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Pois qual é a esperança do hipócrita quando ele for cortado, quando Deus arrancar sua alma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Por acaso Deus ouvirá seu clamor quando a aflição vier sobre ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Ele se deleitará no Todo-Poderoso? Invocará a Deus a todo tempo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Eu vos ensinarei acerca da mão de Deus; não esconderei o que há com o Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Eis que todos vós tendes visto isso; então por que vos deixais enganar por ilusão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Esta é a porção do homem perverso para com Deus, a herança que os violentos receberão do Todo-Poderoso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Se seus filhos se multiplicarem, serão para a espada; e seus descendentes não se fartarão de pão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Os que lhe restarem, pela praga serão sepultados; e suas viúvas não chorarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Se ele amontoar prata como o pó da terra, e se preparar roupas como lama,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Mesmo ele tendo preparado, é o justo que se vestirá, e o inocente repartirá a prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Ele constrói sua casa como a traça, como uma barraca feita por um vigilante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'O rico dormirá, mas não será recolhido; ele abrirá seus olhos, e nada mais há para si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Medos o tomarão como águas; um turbilhão o arrebatará de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'O vento oriental o levará, e ele partirá; e toma-o de seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'E o atacará sem o poupar, enquanto ele tenta fugir de seu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Baterá palmas por causa dele, e desde seu lugar lhe assoviará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Certamente há minas para a prata, e o ouro lugar onde o derretem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'O ferro é tirado do solo, e da pedra se funde o cobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'O homem põe fim às trevas, e investiga em toda extremidade, as pedras que estão na escuridão e nas mais sombrias trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Abre um poço onde não há morador, lugares esquecidos por quem passa a pé; pendurados longe da humanidade, vão de um lado para o outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Da terra o pão procede, e por debaixo ela é transformada como que pelo fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Suas pedras são o lugar da safira, e contém pó de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'A ave de rapina não conhece essa vereda; os olhos do falcão não a viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Os filhotes de animais ferozes nunca a pisaram, nem o feroz leão passou por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'O homem põe sua mão no rochedo, e revolve os montes desde a raiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Cortou canais pelas rochas, e seus olhos veem tudo o que é precioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Ele tapa os rios desde suas nascentes, e faz o oculto sair para a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Porém onde se achará a sabedoria? E onde está o lugar da inteligência?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'O ser humano não conhece o valor dela, nem ela é achada na terra dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'O abismo diz: Não está em mim; E o mar diz: Nem comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Nem por ouro fino se pode comprar, nem se pesar em troca de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Não pode ser avaliada com ouro de Ofir, nem com ônix precioso, nem com safira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Não se pode comparar com ela o ouro, nem o cristal; nem se pode trocar por joia de ouro fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'De coral nem de quartzo não se fará menção; porque o preço da sabedoria é melhor que o de rubis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'O topázio de Cuxe não se pode comparar com ela; nem pode ser avaliada com o puro ouro fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'De onde, pois, vem a sabedoria? E onde está o lugar da inteligência?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Porque encoberta está aos olhos de todo vivente, e é oculta a toda ave do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'O perdição e a morte dizem: Com nossos ouvidos ouvimos sua fama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Deus entende o caminho dela, e ele conhece seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Porque ele enxerga até os confins da terra, e vê tudo o que há debaixo de céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Quando ele deu peso ao vento, e estabeleceu medida para as águas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Quando ele fez lei para a chuva, e caminho para o relâmpago dos trovões,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Então ele a viu, e relatou; preparou-a, e também a examinou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'E disse ao homem: Eis que o temor ao Senhor é a sabedoria, e o desviar-se do mal é a inteligência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'E Jó continuou a falar seu discurso, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Ah quem me dera que fosse como nos meses passados! Como nos dias em que Deus me guardava!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Quando ele fazia brilhar sua lâmpada sobre minha cabeça, e eu com sua luz caminhava pelas trevas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Como era nos dias de minha juventude, quando a amizade de Deus estava sobre minha tenda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Quando o Todo-Poderoso ainda estava comigo, meus filhos ao redor de mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Quando eu lavava meus passos com manteiga, e da rocha me corriam ribeiros de azeite!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Quando eu saía para a porta da cidade, e na praça preparava minha cadeira,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Os rapazes me viam, e abriam caminho; e os idosos se levantavam, e ficavam em pé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Os príncipes se detinham de falar, e punham a mão sobre a sua boca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'A voz dos líderes se calava, e suas línguas se apegavam a céu da boca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'O ouvido que me ouvia me considerava bem-aventurado, e o olho que me via dava bom testemunho de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Porque eu livrava ao pobre que clamava, e ao órfão que não tinha quem o ajudasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'A bênção do que estava a ponto de morrer vinha sobre mim; e eu fazia o coração da viúva ter grande alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Vestia-me de justiça, e ela me envolvia; e meu juízo era como um manto e um turbante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Eu era olhos para o cego, e pés para o manco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Aos necessitados eu era pai; e a causa que eu não sabia, investigava com empenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'E quebrava os queixos do perverso, e de seus dentes tirava a presa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'E eu dizia: Em meu ninho expirarei, e multiplicarei meus dias como areia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Minha raiz se estendia junto às águas, e o orvalho ficava de noite em meus ramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Minha honra se renovava em mim, e meu arco se revigorava em minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Ouviam-me, e esperavam; e se calavam ao meu conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Depois de minha palavra nada replicavam, e minhas razões gotejavam sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Pois esperavam por mim como pela chuva, e abriam sua boca como para a chuva tardia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Se eu me ria com eles, não acreditavam; e não desfaziam a luz de meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Eu escolhia o caminho para eles, e me sentava à cabeceira; e habitava como rei entre as tropas, como o consolador dos que choram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Porém agora riem de mim os mais jovens do que eu, cujos pais eu havia desdenhado até de os pôr com os cães de meu rebanho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'De que também me serviria força de suas mãos, nos quais o vigor já pereceu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Por causa da pobreza e da fome andavam sós; roem na terra seca, no lugar desolado e deserto em trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Que colhiam malvas entre os arbustos, e seu alimento eram as raízes dos zimbros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Do meio das pessoas eram expulsos, e gritavam contra eles, como a um ladrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Habitavam nos barrancos dos ribeiros secos, nos buracos da terra, e nas rochas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Bramavam entre os arbustos, e se ajuntavam debaixo das urtigas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Eram filhos de tolos, filhos sem nome, e expulsos do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Porém agora sirvo-lhes de chacota, e sou para eles um provérbio de escárnio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Eles me abominam e se afastam de mim; porém não hesitam em cuspir no meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Pois Deus desatou minha corda, e me oprimiu; por isso tiraram de si todo constrangimento perante meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'À direita os jovens se levantam; empurram meus pés, e preparam contra mim seus caminhos de destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Destroem meu caminho, e promovem minha miséria, sem necessitarem que alguém os ajude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Eles vêm contra mim como que por uma brecha larga, e revolvem-se entre a desolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Pavores se voltam contra mim; perseguem minha honra como o vento, e como nuvem passou minha prosperidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Por isso agora minha alma se derrama em mim; dias de aflição têm me tomado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'De noite meus ossos se furam em mim, e meus pulsos não descansam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Por grande força de Deus minha roupa está estragada; ele me prendeu como a gola de minha roupa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Lançou-me na lama, e fiquei semelhante ao pó e à cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Clamo a ti, porém tu não me respondes; eu fico de pé, porém tu ficas apenas olhando para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Tu te tornaste cruel para comigo; com a força de tua mão tu me atacas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Levantas-me sobre o vento, e me fazes cavalgar sobre ele; e dissolves o meu ser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Porque eu sei que me levarás à morte; e à casa determinada a todos os viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Porém não se estende a mão para quem está em ruínas, quando clamam em sua opressão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Por acaso eu não chorei pelo que estava em dificuldade, e minha alma não se angustiou pelo necessitado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Quando eu esperava o bem, então veio o mal; quando eu esperava a luz, veio a escuridão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Minhas entranhas fervem, e não se aquietam; dias de aflição me confrontam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Ando escurecido, mas não pelo sol; levanto-me na congregação, e clamo por socorro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Tornei-me irmão dos chacais, e companheiro dos avestruzes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Minha pele se escureceu sobre mim, e meus ossos se inflamam de febre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Por isso minha harpa passou a ser para lamentação, e minha flauta para vozes dos que choram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Eu fiz um pacto com meus olhos; como, pois, eu olharia com cobiça para a virgem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Pois qual é a porção dada por Deus acima, e a herança dada pelo Todo-Poderoso das alturas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Por acaso a calamidade não é para o perverso, e o desastre para os que praticam injustiça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Por acaso ele não vê meus caminhos, e conta todos os meus passos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Se eu andei com falsidade, e se meu pé se apressou para o engano,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Pese-me ele em balanças justas, e Deus saberá minha integridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Se meus passos se desviaram do caminho, e meu coração seguiu meus olhos, e se algo se apegou às minhas mãos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Que eu semeie, e outro coma; e meus produtos sejam arrancados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Se foi meu coração se deixou seduzir por alguma mulher, ou se estive espreitei à porta de meu próximo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Que minha mulher moa para outro, e outros se encurvem sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Pois tal seria um crime vergonhoso, e delito a ser sentenciado por juízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Pois seria um fogo que consumiria até à perdição, e destruiria toda a minha renda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Se desprezei o direito de meu servo ou de minha serva quando eles reclamaram comigo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Que faria eu quando Deus se levantasse? E quando ele investigasse a causa,o que eu lhe responderia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Aquele que me fez no ventre materno também não fez a ele? E não nos preparou de um mesmo modo na madre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Se eu neguei aos pobres o que eles desejavam, ou fiz desfalecer os olhos da viúva;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'E se comi meu alimento sozinho, e o órfão não comeu dele');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '(Porque desde a minha juventude cresceu comigo como se eu fosse seu pai,e desde o ventre de minha mãe guiei a viúva);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Se eu vi alguém morrer por falta de roupa, e o necessitado sem algo que o cobrisse,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Se sua cintura não me bendisse, quando ele se esquentava com as peles de meus cordeiros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Se levantei minha mão contra o órfão, quando vi que seria favorecido na corte judicial,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Que minha escápula caia do meu ombro, e meu braço se quebre de sua articulação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Porque o castigo de Deus era um assombro para mim, e eu não teria poder contra sua majestade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Se eu pus no ouro minha esperança, ou disse ao ouro fino: Tu és minha confiança;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Se eu me alegrei de que minha riqueza era muita, e de que minha mão havia obtido muito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Se olhei para o sol quando brilhava, e à lua quando estava bela,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'E meu coração se deixou enganar em segredo, e minha boca beijou minha mão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Isto também seria um delito a ser sentenciado por juiz; porque teria negado ao Deus de cima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Se eu me alegrei da desgraça daquele que me odiava, e me agradei quando o mal o encontrou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Sendo que nem deixei minha boca pecar, desejando sua morte com maldição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Se a gente da minha casa nunca tivesse dito: Quem não se satisfez da carne dada por ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'O estrangeiro não passava a noite na rua; eu abria minhas portas ao viajante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Se encobri minhas transgressões como as pessoas fazem, escondendo meu delito em meu seio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Porque eu tinha medo da grande multidão, e o desprezo das famílias me atemorizou; então me calei, e não saí da porta:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Quem me dera se alguém me ouvisse! Eis que minha vontade é que o Todo-Poderoso me responda, e meu adversário escrevesse um relato da acusação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Certamente eu o carregaria sobre meu ombro, e o poria em mim como uma coroa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Eu lhe diria o número de meus passos, e como um príncipe eu me chegaria a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Se minha terra clamar contra mim, e seus sulcos juntamente chorarem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Se comi seus frutos sem pagar dinheiro, ou fiz expirar a alma de seus donos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Em lugar de trigo que me produza cardos, e ervas daninhas no lugar da cevada. Aqui terminam as palavras de Jó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Então aqueles três homens cessaram de responder a Jó, porque ele era justo em seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Porém se acendeu a ira de Eliú, filho de Baraquel, buzita, da família de Rão; contra Jó se acendeu sua ira, porque justificava mais a si mesmo que a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Também sua ira se acendeu contra seus três amigos, porque não achavam o que responder, ainda que tinham condenado a Jó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'E Eliú tinha esperado a Jó naquela discussão, porque tinham mais idade que ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Porém quando Eliú viu que não havia resposta na boca daqueles três homens, sua ira se acendeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Por isso Eliú, filho de Baraquel, buzita, respondeu, dizendo: Eu sou jovem e vós sois idosos; por isso fiquei receoso e tive medo de vos declarar minha opinião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Eu dizia: Os dias falem, e a multidão de anos ensine sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Certamente há espírito no ser humano, e a inspiração do Todo-Poderoso os faz entendedores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Não são somente os grandes que são sábios, nem somente os velhos entendem o juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Por isso eu digo: escutai-me; também eu declararei minha opinião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Eis que eu aguardei vossas palavras, e dei ouvidos a vossas considerações, enquanto vós buscáveis argumentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Eu prestei atenção a vós, porém eis que ninguém há de vós que possa convencer a Jó, nem que responda a suas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Portanto não digais: Encontramos a sabedoria; que Deus o derrote, e não o homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Jó não dirigiu suas palavras a mim, nem eu lhe responderei com vossos dizeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Estão pasmos, não respondem mais; faltam-lhes palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Esperei, pois, porém agora não falam; porque já pararam, e não respondem mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Também eu responderei minha parte; também eu declararei minha opinião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Porque estou cheio de palavras, e o espírito em meu ventre me obriga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Eis que meu ventre é como o vinho que não tem abertura; e que está a ponto de arrebentar como odres novos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Falarei, para que eu me alivie; abrirei meus lábios, e responderei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Não farei eu acepção de pessoas, nem usarei de títulos lisonjeiros para com o homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Pois não sei lisonjear; caso contrário,meu Criador logo me removeria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Portanto, Jó, ouve, por favor, meus dizeres, e dá ouvidos a todas as minhas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Eis que já abri minha boca; minha língua já fala debaixo do meu céu da boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Meus dizeres pronunciarão a integridade do meu coração, e o puro conhecimento dos meus lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'O Espírito de Deus me fez, e o sopro do Todo-Poderoso me deu vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Se puderes, responde-me; dispõe-te perante mim, e persiste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Eis que para Deus eu sou como tu; do barro também eu fui formado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Eis que meu terror não te espantará, nem minha mão será pesada sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Certamente tu disseste a meus ouvidos, e eu ouvi a voz de tuas palavras,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Que diziam: Eu sou limpo e sem transgressão; sou inocente, e não tenho culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Eis que Deus buscou pretextos contra mim, e me tem por seu inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Ele pôs meus pés no tronco, e observa todas as minhas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Eis que nisto não foste justo, eu te respondo; pois Deus é maior que o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Por que razão brigas contra ele por não dar resposta às palavras do ser humano?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Contudo Deus fala uma ou duas vezes, ainda que o ser humano não entenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Em sonho ou em visão noturna, quando o sono profundo cai sobre as pessoas, e adormecem na cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Então o revela ao ouvido das pessoas, e os sela com advertências;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Para desviar ao ser humano de sua obra, e do homem a soberba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Para desviar a sua alma da perdição, e sua vida de passar pela espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Também em sua cama é castigado com dores, com luta constante em seus ossos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'De modo que sua vida detesta até o pão, e sua alma a comida deliciosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Sua carne desaparece da vista, e seus ossos, que antes não se viam, aparecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Sua alma se aproxima da cova, e sua vida dos que causam a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Se com ele, pois, houver algum anjo, algum intérprete; um dentre mil, para anunciar ao ser humano o que lhe é correto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Então Deus terá misericórdia dele, e lhe dirá: Livra-o, para que não desça à perdição; já achei o resgate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Sua carne se rejuvenescerá mais do que era na infância, e voltará aos dias de sua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Ele orará a Deus, que se agradará dele; e verá sua face com júbilo, porque ele restituirá ao ser humano sua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Ele olhará para as pessoas, e dirá: Pequei, e perverti o que era correto, o que de nada me aproveitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Porém Deus livrou minha alma para que eu não passasse à cova, e agora minha vida vê a luz!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Eis que Deus faz tudo isto duas ou três vezes com o ser humano,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Para desviar sua alma da perdição, e o iluminar com a luz dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Presta atenção, Jó, e ouve-me; cala-te, e eu falarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Se tiveres o que dizer, responde-me; fala, porque eu quero te justificar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'E se não, escuta-me; cala-te, e eu ensinarei sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Eliú respondeu mais, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Ouvi, vós sábios, minhas palavras; e vós, inteligentes, dai-me ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Porque o ouvido prova as palavras, assim como o paladar experimenta a comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Escolhamos para nós o que é correto, e conheçamos entre nós o que é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Pois Jó disse: Eu sou justo, e Deus tem me tirado meu direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Por acaso devo eu mentir quanto ao meu direito? Minha ferida é dolorosa mesmo que eu não tenha transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Que homem há como Jó, que bebe o escárnio como água?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'E que caminha na companhia dos que praticam maldade, e anda com homens perversos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Porque disse: De nada aproveita ao homem agradar-se em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Portanto vós, homens de bom-senso, escutai-me; longe de Deus esteja a maldade, e do Todo- Poderoso a perversidade!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Porque ele paga ao ser humano conforme sua obra, e faz a cada um conforme o seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Certamente Deus não faz injustiça, e o Todo-Poderoso não perverte o direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Quem o pôs para administrar a terra? E quem dispôs a todo o mundo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Se ele tomasse a decisão, e recolhesse para si seu espírito e seu fôlego,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Toda carne juntamente expiraria, e o ser humano se tornaria em pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Se pois há em ti entendimento, ouve isto: dá ouvidos ao som de minhas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Por acaso quem odeia a justiça poderá governar? E condenarás tu ao Poderoso Justo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Pode, por acaso, o rei ser chamado de vil, e os príncipes de perversos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Quanto menos a aquele que não faz acepção de pessoas de príncipes, nem valoriza mais o rico que o pobre! Pois todos são obras de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Em um momento morrem; e à meia noite os povos são sacudidos, e passam; e o poderoso será tomado sem ação humana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Porque seus olhos estão sobre os caminhos do homem, e ele vê todos os seus passos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Não há trevas nem sombra de morte em que os que praticam maldade possam se esconder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Pois ele não precisa observar tanto ao homem para que este possa entrar em juízo com Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Ele quebranta aos fortes sem precisar de investigação, e põe outros em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Visto que ele conhece suas obras, de noite os trastorna, e ficam destroçados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Ele os espanca à vista pública por serem maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Pois eles se desviaram de segui-lo, e não deram atenção a nenhum de seus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Assim fizeram com que viesse a ele o clamor do pobre, e ele ouvisse o clamor dos aflitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'E se ele ficar quieto, quem o condenará? Se ele esconder o rosto, quem o olhará? Ele está quer sobre um povo, quer sobre um único ser humano,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Para que a pessoa hipócrita não reine, e não haja ciladas ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Por que não tão somente se diz: Suportei teu castigo não farei mais o que é errado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Ensina-me o que não vejo; se fiz alguma maldade, nunca mais a farei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Será a recompensa da parte dele como tu queres, para que a recuses? És tu que escolhes, e não eu; o que tu sabes, fala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'As pessoas de entendimento dirão comigo, e o homem sábio me ouvirá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Jó não fala com conhecimento, e a suas palavras falta prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Queria eu que Jó fosse provado até o fim, por causa de suas respostas comparáveis a de homens malignos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Pois ao seu pecado ele acrescentou rebeldia; ele bate as mãos de forma desrespeitosa entre nós, e multiplica suas palavras contra Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Eliú respondeu mais, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Pensas tu ser direito dizeres: Maior é a minha justiça do que a de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Porque disseste: Para que ela te serve? Ou: Que proveito terei dela mais que meu pecado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Eu darei reposta a ti, e a teus amigos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Olha para os céus, e vê; e observa as nuvens, que são mais altas que tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Se tu pecares, que mal farás contra ele? Se tuas transgressões se multiplicarem, que mal lhe farás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Se fores justo, que lhe darás? Ou o que ele receberá de tua mão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Tua perversidade poderia afetar a outro homem como tu; e tua justiça poderia ser proveitosa a algum filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Os aflitos clamam por causa da grande opressão; eles gritam por causa do poder dos grandes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Porém ninguém diz: Onde está Deus, meu Criador, que dá canções na noite,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Que nos ensina mais que aos animais da terra, e nos faz sábios mais que as aves do céu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Ali clamam, porém ele não responde, por causa da arrogância dos maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Certamente Deus não ouvirá a súplica vazia, nem o Todo-Poderoso dará atenção a ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Quanto menos ao que disseste: que tu não o vês! Porém o juízo está diante dele; portanto espera nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Mas agora, já que a ira dele ainda não está castigando, e ele não deu completa atenção à arrogância,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Por isso Jó abriu sua boca em vão, e multiplicou palavras sem conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Prosseguiu Eliú ainda, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Espera-me um pouco, e eu te mostrarei que ainda há palavras a favor de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Desde longe trarei meu conhecimento, e a meu Criador atribuirei a justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Porque verdadeiramente minhas palavras não serão falsas; contigo está um que tem completo conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Eis que Deus é grande, porém despreza ninguém; grande ele é em poder de entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Ele não permite o perverso viver, e faz justiça aos aflitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Ele não tira seus olhos do justo; ao contrário, ele os faz sentar com os reis no trono, e assim são exaltados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'E se estiverem presos em grilhões, e detidos com cordas de aflição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Então ele lhes faz saber as obras que fizeram, e suas transgressões, das quais se orgulharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'E revela a seus ouvidos, para que sejam disciplinados; e lhes diz, para que se convertam da maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Se ouvirem, e o servirem, acabarão seus dias em prosperidade, e seus anos em prazeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Porém se não ouvirem, perecerão pela espada, e morrerão sem conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'E os hipócritas de coração acumulam a ira divina; e quando ele os amarrar, mesmo assim não clamam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'A alma deles morrerá em sua juventude, e sua vida entre os pervertidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Ele livra o aflito de sua aflição, e na opressão ele revela a seus ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Assim também ele pode te desviar da boca da angústia para um lugar amplo, onde não haveria aperto; para o conforto de tua mesa, cheia dos melhores alimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Mas tu estás cheio do julgamento do perverso; o julgamento e a justiça te tomam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Por causa da furor, guarda-te para que não sejas seduzido pela riqueza, nem que um grande suborno te faça desviar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Pode, por acaso, a tua riqueza te sustentar para que não tenhas aflição, mesmo com todos os esforços de teu poder?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Não anseies pela noite, em que os povos são tomados de seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Guarda-te, e não te voltes para a maldade; pois por isto que tens sido testado com miséria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Eis que Deus é exaltado em seu poder; que instrutor há como ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Quem lhe indica o seu caminho? Quem poderá lhe dizer: Cometeste maldade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Lembra-te de engrandeceres sua obra, a qual os seres humanos contemplam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Todas as pessoas a veem; o ser humano a enxerga de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Eis que Deus é grande, e nós não o compreendemos; não se pode descobrir o número de seus anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Ele traz para cima as gotas das águas, que derramam a chuva de seu vapor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'A qual as nuvens destilam, gotejando abundantemente sobre o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Poderá alguém entender a extensão das nuvens, e os estrondos de seu pavilhão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Eis que estende sobre ele sua luz, e cobre as profundezas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Pois por estas coisas ele julga aos povos, e dá alimento em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Ele cobre as mãos com o relâmpago, e dá ordens para que atinja o alvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'O trovão anuncia sua presença; o gado também prenuncia a tempestade que se aproxima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Disto também o meu coração treme, e salta de seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Ouvi atentamente o estrondo de sua voz, e o som que sai de sua boca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Ao qual envia por debaixo de todos os céus; e sua luz até os confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Depois disso brama com estrondo; troveja com sua majestosa voz; e ele não retém seus relâmpagos quando sua voz é ouvida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Deus troveja maravilhosamente com sua voz; ele faz coisas tão grandes que nós não compreendemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Pois ele diz à neve: Cai sobre à terra; Como também à chuva: Sê chuva forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Ele sela as mãos de todo ser humano, para que todas as pessoas conheçam sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'E os animais selvagens entram nos esconderijos, e ficam em suas tocas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Da recâmara vem o redemoinho, e dos ventos que espalham vem o frio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Pelo sopro de Deus se dá o gelo, e as largas águas se congelam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Ele também carrega de umidade as espessas nuvens, e por entre as nuvens ele espalha seu relâmpago.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Então elas se movem ao redor segundo sua condução, para que façam quanto ele lhes manda sobre a superfície do mundo, na terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Seja que ou por vara de castigo, ou para sua terra, ou por bondade as faça vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Escuta isto, Jó; fica parado, e considera as maravilhas de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Por acaso sabes tu quando Deus dá ordem a elas, e faz brilhar o relâmpago de sua nuvem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Conheces tu os equilíbrios das nuvens, as maravilhas daquele que é perfeito no conhecimento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Tu, cujas vestes se aquecem quando a terra se aquieta por causa do vento sul,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'acaso podes estender com ele os céus, que estão firmes como um espelho fundido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Ensina-nos o que devemos dizer a ele; pois discurso nenhum podemos propor, por causa das nossas trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Seria contado a ele o que eu haveria de falar? Por acaso alguém falaria para ser devorado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'E agora não se pode olhar para o sol, quando brilha nos céus, quando o vento passa e os limpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Do norte vem o esplendor dourado; em Deus há majestade temível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Não podemos alcançar ao Todo-Poderoso; ele é grande em poder; porém ele a ninguém oprime em juízo e grandeza de justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Por isso as pessoas o temem; ele não dá atenção aos que se acham sábios de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Então o SENHOR respondeu a Jó desde um redemoinho, e disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Quem é esse que obscurece o conselho com palavras sem conhecimento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Agora cinge teus lombos como homem; e eu te perguntarei, e tu me explicarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Onde estavas tu quando eu fundava a terra? Declara- me,se tens inteligência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Quem determinou suas medidas, se tu o sabes? Ou quem estendeu cordel sobre ela?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Sobre o que estão fundadas suas bases? Ou quem pôs sua pedra angular,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Quando as estrelas do amanhecer cantavam alegremente juntas, e todos os filhos de Deus jubilavam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Ou quem encerrou o mar com portas, quando transbordou, saindo da madre,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Quando eu pus nuvens por sua vestidura, e a escuridão por sua faixa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Quando eu passei sobre ele meu decreto, e lhe pus portas e ferrolhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'E disse: Até aqui virás, e não passarás adiante, e aqui será o limite para a soberba de tuas ondas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Desde os teus dias tens dado ordem à madrugada? Ou mostraste tu ao amanhecer o seu lugar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Para que tomasse os confins da terra, e os perversos fossem sacudidos dela?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'E a terra se transforma como barro sob o selo; todas as coisas sobre ela se apresentam como vestidos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'E dos perversos é desviada sua luz, e o braço erguido é quebrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Por acaso chegaste tu às fontes do mar, ou passeaste no mais profundo abismo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Foram reveladas a ti as portas da morte, ou viste as portas da sombra de morte?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Entendeste tu as larguras da terra? Declara, se sabes tudo isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Onde está o caminho por onde mora a luz? E quanto às trevas, onde fica o seu lugar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Para que as tragas a seus limites, e conheças os caminhos de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Certamente tu o sabes, pois já eras nascido, e teus dias são inúmeros!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Por acaso entraste tu aos depósitos da neve, e viste os depósitos do granizo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Que eu retenho até o tempo da angústia, até o dia da batalha e da guerra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Onde está o caminho em que a luz se reparte, e o vento oriental se dispersa sobre a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Quem repartiu um canal às correntezas de águas, e caminho aos relâmpagos dos trovões,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Para chover sobre a terra onde havia ninguém, sobre o deserto, onde não há gente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Para fartar a terra deserta e desolada, e para fazer crescer aos renovos da erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Por acaso a chuva tem pai? Ou quem gera as gotas do orvalho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'De qual ventre procede o gelo? E quem gera a geada do céu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'As águas se tornam duras como pedra, e a superfície do abismo se congela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Podes tu atar as cadeias das Plêiades, ou desatar as cordas do Órion?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Podes tu trazer as constelações a seu tempo, e guiar a Ursa com seus filhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Sabes tu as ordenanças dos céus? Ou podes tu dispor do domínio deles sobre a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Ou podes levantar tua voz até às nuvens, para que a abundância das águas te cubra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Podes tu mandar relâmpagos, para que saiam, e te digam: Eis-nos aqui?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Quem pôs a sabedoria no íntimo? Ou quem deu entendimento à mente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Quem pode enumerar as nuvens com sabedoria? E os odres dos céus, quem pode os despejar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Quando o pó se endurece, e os torrões se apegam uns aos outros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Caçarás tu a presa para o leão? Ou saciarás a fome dos leões jovens,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'Quando estão agachados nas covas, ou estão à espreita no matagal?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Quem prepara aos corvos seu alimento, quando seus filhotes clamam a Deus, andando de um lado para o outro por não terem o que comer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Sabes tu o tempo em que as cabras montesas dão filhotes? Ou observaste tu as cervas quando em trabalho de parto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Contaste os meses que elas cumprem, e sabes o tempo de seu parto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Quando se encurvam, produzem seus filhos, e lançam de si suas dores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Seus filhos se fortalecem, crescem como o trigo; saem, e nunca mais voltam a elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Quem despediu livre ao asno montês? E quem ao asno selvagem soltou das ataduras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Ao qual eu dei a terra desabitada por casa, e a terra salgada por suas moradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Ele zomba do tumulto da cidade; não ouve os gritos do condutor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'A extensão dos montes é seu pasto; e busca tudo o que é verde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Por acaso o boi selvagem quererá te servir, ou ficará junto de tua manjedoura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Ou amarrarás ao boi selvagem com sua corda para o arado? Ou lavrará ele aos campos atrás de ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Confiarás nele, por ser grande sua força, e deixarás que ele faça teu trabalho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Porás tua confiança nele, para que ele colha tua semente, e a junte em tua eira?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'As asas da avestruz batem alegremente, mas são suas asas e penas como as da cegonha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Ela deixa seus ovos na terra, e os esquenta no chão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'E se esquece de que pés podem os pisar, e os animais do campo podem os esmagar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Age duramente para com seus filhos, como se não fossem seus, sem temer que seu trabalho tenha sido em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Porque Deus a privou de sabedoria, e não lhe repartiu entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Porém quando se levanta para correr, zomba do cavalo e do seu cavaleiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'És tu que dás força ao cavalo, ou que vestes seu pescoço com crina?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Podes tu o espantar como a um gafanhoto? O sopro de suas narinas é terrível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Ele escarva a terra, alegra-se de sua força, e sai ao encontro das armas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Ele zomba do medo, e não se espanta; nem volta para trás por causa da espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Contra ele rangem a aljava, o ferro brilhante da lança e do dardo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Sacudido-se com furor, ele escarva a terra; ele não fica parado ao som da trombeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Ao som das trombetas diz: Eia! E desde longe cheira a batalha, o grito dos capitães, e o barulho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Por acaso é por tua inteligência que o gavião voa, e estende suas asas para o sul?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Ou é por tua ordem que a água voa alto e põe seu ninho na altura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Nas penhas ela mora e habita; no cume das penhas, e em lugares seguros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Desde ali espia a comida; seus olhos avistam de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Seus filhotes sugam sangue; e onde houver cadáveres, ali ela está.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Então o SENHOR respondeu mais a Jó, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Por acaso quem briga contra o Todo-Poderoso pode ensiná-lo? Quem quer repreender a Deus, responda a isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Então Jó respondeu ao SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Eis que eu sou insignificante; o que eu te responderia? Ponho minha mão sobre minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Uma vez falei, porém não responderei; até duas vezes, porém não prosseguirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Então o SENHOR respondeu a Jó desde o redemoinho, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Cinge-te agora os teus lombos como homem; eu te perguntarei, e tu me explica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Por acaso tu anularias o meu juízo? Tu me condenarias, para te justificares?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Tens tu braço como Deus? Ou podes tu trovejar com tua voz como ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Orna-te, pois, de excelência e alteza; e veste-te de majestade e glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Espalha os furores de tua ira; olha a todo soberbo, e abate-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Olha a todo soberbo, e humilha-o; e esmaga aos perversos em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Esconde-os juntamente no pó; ata seus rostos no oculto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'E eu também te reconhecerei; pois tua mão direita te terá livrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Observa o beemote, ao qual eu fiz contigo; ele come erva come como o boi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Eis que sua força está em seus lombos, e seu poder na musculatura de seu ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Ele torna sua cauda dura como o cedro, e os nervos de suas coxas são entretecidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Seus ossos são como tubos de bronze; seus membros, como barras de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Ele é a obra-prima dos caminhos de Deus; aquele que o fez o proveu de sua espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Pois os montes lhe produzem pasto; por isso todos os animais do campo ali se alegram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Ele se deita debaixo das árvores sombrias; no esconderijo das canas e da lama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'As árvores sombrias o cobrem, cada uma com sua sombra; os salgueiros do ribeiro o cercam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Ainda que o rio se torne violento, ele não se apressa; confia ainda que o Jordão transborde até sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Poderiam, por acaso, capturá-lo à vista de seus olhos, ou com laços furar suas narinas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Poderás tu pescar ao leviatã com anzol, ou abaixar sua língua com uma corda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Podes pôr um anzol em seu nariz, ou com um espinho furar sua queixada?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Fará ele súplicas a ti, ou falará contigo suavemente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Fará ele pacto contigo, para que tu o tomes por escravo perpétuo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Brincarás tu com ele como com um passarinho, ou o atarás para tuas meninas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Os companheiros farão banquete dele? Repartirão dele entre os mercadores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Poderás tu encher sua pele de espetos, ou sua cabeça com arpões de pescadores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Põe tua mão sobre ele; te lembrarás da batalha, e nunca mais voltarás a fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Eis que a esperança de alguém de vencê-lo falhará; pois, apenas ao vê-lo será derrubado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Ninguém há tão ousado que o desperte; quem pois, ousa se opor a mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Quem me deu primeiro, para que eu o recompense? Tudo o que há debaixo dos céus é meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Eu não me calarei a respeito de seus membros, nem de suas forças, e da graça de sua estatura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Quem descobrirá sua vestimenta superficial? Quem poderá penetrar sua couraça dupla?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Quem poderia abrir as portas de seu rosto? Ao redor de seus dentes há espanto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Seus fortes escudos são excelentes; cada um fechado, como um selo apertado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Um está tão próximo do outro, que vento não pode entrar entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Estão grudados uns aos outros; estão tão travados entre si, que não se podem separar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Cada um de seus roncos faz resplandecer a luz, e seus olhos são como os cílios do amanhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'De sua boca saem tochas, faíscas de fogo saltam dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'De suas narinas sai fumaça, como de uma panela fervente ou de um caldeirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Seu fôlego acende carvões, e de sua boca sai chama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'A força habita em seu pescoço; diante dele salta-se de medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'As dobras de sua carne estão apegadas entre si; cada uma está firme nele, e não podem ser movidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Seu coração é rígido como uma pedra, rígido como a pedra de baixo de um moinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Quando ele se levanta, os fortes tremem; por seus abalos se recuam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Se alguém lhe tocar com a espada, não poderá prevalecer; nem arremessar dardo, ou lança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Ele considera o ferro como palha, e o aço como madeira podre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'A flecha não o faz fugir; as pedras de funda são para ele como sobras de cascas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Considera toda arma como sobras de cascas, e zomba do mover da lança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Por debaixo de si tem conchas pontiagudas; ele esmaga com suas pontas na lama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Ele faz ferver as profundezas como a uma panela, e faz do mar como um pote de unguento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'Ele faz brilhar o caminho atrás de si; faz parecer ao abismo com cabelos grisalhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Não há sobre a terra algo que se possa comparar a ele. Ele foi feito para não temer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Ele vê tudo que é alto; ele é rei sobre todos os filhos dos animais soberbos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'E Jó respondeu ao SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Eu sei que tudo podes, e nenhum de teus pensamentos pode ser impedido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Tu dizes: Quem é esse que obscurece o conselho sem conhecimento? Por isso eu falei do que não entendia; coisas que eram maravilhosas demais para mim, e eu não as conhecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Escuta-me, por favor, e eu falarei; eu te perguntarei, e tu me ensina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Com os ouvidos eu ouvira falar de ti; mas agora meus olhos te veem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Por isso me abomino, e me arrependo no pó e na cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'E sucedeu que, depois que o SENHOR acabou de falar essas palavras a Jó, o SENHOR disse a Elifaz temanita: Minha ira se acendeu contra ti e contra teus dois amigos; porque não falastes de mim o que era correto, como meu servo Jó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Por isso tomai para vós sete bezerros e sete carneiros, ide a meu servo Jó, e fazei ofertas de queima em vosso favor, e meu servo Jó orará por vós; pois certamente atenderei a ele para eu não vos tratar conforme vossa loucura; pois não falastes de mim o que era correto, como meu servo Jó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Então Elifaz o temanita, Bildade o suíta, e Zofar o naamita foram, e fizeram como o SENHOR havia lhes dito; e o SENHOR atendeu a Jó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'E o SENHOR livrou Jó de seu infortúnio, enquanto ele orava por seus amigos; e o SENHOR acrescentou a Jó o dobro de tudo quanto ele tinha antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Então vieram e ele todos os seus irmãos, e todas as suas irmãs, e todos os que o conheciam antes; e comeram com ele pão em sua casa, e condoeram-se dele, e o consolaram acerca de toda a calamidade que o SENHOR tinha trazido sobre ele; e cada um deles lhe deu uma peça de dinheiro, e uma argola de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'E assim o SENHOR abençoou o último estado de Jó mais que o seu primeiro; porque teve catorze mil ovelhas, seis mil camelos, mil juntas de bois, e mil asnas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Também teve sete filhos e três filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'E chamou o nome da uma Jemima, e o nome da segunda Quézia, e o nome da terceira Quéren-Hapuque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'E em toda a terra não se acharam mulheres tão belas como as filhas de Jó; e seu pai lhes deu herança entre seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'E depois disto Jó viveu cento e quarenta anos; e viu seus filhos, e os filhos de seus filhos, até quatro gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Então Jó morreu, velho, e farto de dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Bem-aventurado o homem que não anda no conselho dos maus, nem fica parado no caminho dos pecadores, nem se senta junto dos escarnecedores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Mas sim, que tem seu prazer na Lei do SENHOR; e medita em sua Lei de dia e de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Porque ele será como uma árvore, plantada junto a ribeiros de águas, que dá fruto a seu devido tempo, e suas folhas não caem; e tudo quanto fizer prosperará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Os maus não são assim; mas são como a palha que o vento dispersa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Por isso os maus não subsistirão no julgamento, nem os pecadores no ajuntamento dos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Porque o SENHOR conhece o caminho dos justos; porém o caminho dos maus perecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Por que as nações se rebelam, e os povos planejam em vão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Os reis da terra se levantam, e os governantes tomam conselhos reunidos contra o SENHOR, e contra seu Ungido, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Rompamos as correntes deles, e lancemos fora de nós as cordas deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Aquele que está sentado nos céus rirá; o Senhor zombará deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Então ele lhes falará em sua ira; em seu furor ele os assombrará, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'E eu ungi a meu Rei sobre Sião, o monte de minha santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'E eu declararei o decreto do SENHOR: Ele me disse: Tu és meu Filho; eu hoje te gerei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Pede-me, e eu te darei as nações por herança, e por tua propriedade os confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Com cetro de ferro tu as quebrarás; como vaso de oleiro tu as despedaçarás;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Portanto agora, reis, sede prudentes; vós, juízes da terra, deixai serdes instruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Servi ao SENHOR com temor; e alegrai-vos com tremor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Beijai ao Filho, para que ele não se ire, e pereçais no caminho; porque em breve a ira dele se acenderá. Bem-aventurados são todos os que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Salmo de Davi, quando ele fugia da presença de seu filho Absalão: Ah SENHOR, como têm se multiplicado meus adversários! Muitos se levantam contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Muitos dizem de minha alma: Não há salvação para ele em Deus.(Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Porém tu, SENHOR, és escudo para mim; minha glória, e o que levanta minha cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Com minha voz eu clamei ao SENHOR; e ele me ouviu desde o monte de sua santidade. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Eu me deitei, e dormi; acordei, porque o SENHOR me sustentava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Eu não temerei ainda que sejam dez mil pessoas que se ponham ao redor de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Levanta-te, SENHOR, salva-me, meu Deus; pois feriste os queixos de todos meus inimigos; e quebraste os dentes dos maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'A salvação vem do SENHOR; sobre o teu povo seja tua bênção. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Salmo de Davi para o regente, com instrumentos de cordas: Quando eu clamar, ouve-me, ó Deus de minha justiça; na angústia tu me alivias; tem misericórdia de mim, e ouve a minha oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Filhos dos homens, até quando tornareis minha glória em infâmia, e amareis as coisas vãs? Até quando buscareis a mentira? (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Sabei pois, que o SENHOR separou para si aquele que é fiel; o SENHOR ouvirá, quando a ele eu clamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Quando estiverdes perturbados, não pequeis; meditai em vosso coração sobre a vossa cama, e fazei silêncio. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Sacrificai sacrifícios de justiça, e confiai no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Muitos dizem: Quem nos mostrará o bem?Levanta sobre nós, SENHOR, a luz de teu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Tu me deste alegria em meu coração, maior do que quando o trigo e o vinho deles se multiplicaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Eu deitarei, e dormirei em paz; porque só tu, SENHOR, me fazes descansar seguro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Salmo de Davi para o regente, com instrumentos de sopro: SENHOR, escuta as minhas palavras; entende aquilo que estou meditando;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Ouve a voz do meu clamor, meu Rei e meu Deus; porque a ti eu oro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'SENHOR, pela manhã ouvirás minha voz; pela manhã apresentarei meu clamor a ti, e ficarei esperando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Porque tu não és Deus que tens prazer na maldade; contigo não habitará o mau.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Os arrogantes não ficarão de pé diante dos teus olhos; tu odeias todas os praticantes de maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Tu destruirás aos que falam mentiras; o SENHOR abomina ao homem sanguinário e enganador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Mas eu, pela grandeza de tua bondade, entrarei em tua casa; adorarei inclinado para o templo de tua santidade em temor a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'SENHOR, guia-me em tua justiça, por causa dos meus adversários; prepara diante de mim o teu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Porque não há verdade na boca deles; seu interior são meras destruições; a garganta deles é uma sepultura aberta; com suas línguas elogiam falsamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Declara-os culpados, ó Deus, e que caiam de seus próprios conselhos; expulsa-os por causa da abundância de suas transgressões, porque eles se rebelaram contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Mas se alegrem todos os que confiam em ti; clamai de alegria para sempre; porque tu os proteges; e fiquem contentes em ti aqueles que amam o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Porque tu, SENHOR, abençoarás ao justo; como com um escudo tu o rodearás com tua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Salmo de Davi para o regente, com instrumentos de cordas, uma harpa de oito cordas: SENHOR, não me repreendas na tua ira; e não me castigues em teu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Tem misericórdia de mim, SENHOR; porque eu estou enfraquecido; cura-me, SENHOR, porque meus ossos estão afligidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Até minha alma está muito aflita; e tu, SENHOR, até quando?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Volta, SENHOR; livra minha alma; salva-me por tua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Porque na morte não há lembrança de ti; no mundo dos mortos quem te louvará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Já estou cansado do meu gemido; toda a noite eu inundo a minha cama; com minhas lágrimas molho meu leito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Meus olhos estão desolados de mágoa, e têm se envelhecido por causa de todos os meus adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Sai para longe de mim, todos vós praticantes de maldade; porque o SENHOR já ouviu a voz do meu choro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'O SENHOR tem ouvido a minha súplica; o SENHOR aceitará a minha oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Todos os meus inimigos se envergonharão e ficarão muito perturbados; voltarão para trás, e repentinamente se envergonharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Cântico de Davi, que cantou ao SENHOR, depois das palavras de Cuxe, descendente de Benjamim: SENHOR, meu Deus, em ti confio; salva-me de todos os que me perseguem, e livra-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Para que não rasguem minha alma como um leão, sendo despedaçada sem haver quem a livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'SENHOR, meu Deus, se eu fiz isto: se há perversidade em minhas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Se eu paguei com mal ao que tinha paz comigo (mas fiz escapar ao que me oprimia sem causa);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Então que o inimigo persiga a minha alma, e a alcance; e pise em terra a minha vida; e faça habitar minha honra no pó. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Levanta-te, SENHOR, em tua ira; exalta-te pelos furores de meus opressores; e desperta para comigo; tu mandaste o juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Então o ajuntamento de povos te rodeará; portanto volta a te elevar a ti mesmo sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'O SENHOR julgará aos povos; julga-me, SENHOR, conforme a minha justiça, e conforme a sinceridade que há em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Que tenha fim a maldade dos maus; mas firma ao justo, tu, ó justo Deus, que provas os corações e os sentimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Meu escudo pertence a Deus, que salva os corretos de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Deus é um justo juiz; e um Deus que se ira todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Ele afia a espada para aquele que não se arrepende; ele já armou e preparou seu arco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'E para ele já preparou armas mortais; suas flechas utilizará contra os perseguidores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Eis que o injusto está com dores de perversidade; e está em trabalho de parto, e gerará mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Ele cavou um poço e o fez fundo; mas caiu na cova que ele próprio fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Seu trabalho se voltará contra sua própria cabeça; e sua violência descerá sobre o topo de sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Eu louvarei ao SENHOR conforme sua justiça; cantarei ao nome do SENHOR, o Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Salmo de Davi para o regente, com “Gitite”: Ah DEUS, nosso Senhor, quão glorioso é o teu nome sobre toda a terra! Pois tu puseste tua majestade acima dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Da boca das crianças, e dos que mamam, tu fundaste força, por causa de teus adversários, para fazer cessar ao inimigo e ao vingador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Quando eu vejo teus céus, obra de teus dedos; a lua e as estrelas, que tu preparaste;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'O que é o homem, para que tu te lembres dele? E o que é o filho do homem, para que o visites?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'E tu o fizeste um pouco menor que os anjos; e com glória e honra tu o coroaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Tu o fazes ter controle sobre as obras de tuas mãos; tudo puseste debaixo de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Ovelhas e bois, todos eles, e também os animais do campo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'As aves dos céus, e os peixes do mar; e os que passam pelos caminhos dos mares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Ó DEUS, nosso Senhor! Quão glorioso é o teu nome sobre toda a terra!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Salmo de Davi, para o regente, em “Mute-Laben”: Louvarei a ti, SENHOR com todo o meu coração; contarei todas as tuas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Em ti eu ficarei contente e saltarei de alegria; cantarei a teu nome, ó Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Meus inimigos voltaram para trás; eles caem e perecem diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Porque tu fizeste conforme meu direito e minha causa; tu te sentaste no teu tribunal e julgaste com justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Severamente repreendeste às nações, destruíste ao perverso; tu tiraste o nome dele para sempre e eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Ao inimigo, as destruições já se acabaram para sempre. E tu arrasaste as cidades, e já pereceu sua memória com elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Mas o SENHOR se sentará para governar eternamente; ele já preparou seu trono para julgar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Ele mesmo julgará ao mundo com justiça; e corretamente fará justiça aos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'O SENHOR será um refúgio para o aflito; um refúgio em tempos de angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'E confiarão em ti os que conhecem o teu nome; porque tu, SENHOR, nunca desamparaste aos que te buscam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Cantai ao SENHOR, que habita em Sião! Contai entre os povos as obras dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Porque ele investiga os derramamentos de sangue, e lembra-se deles; não se esquece do clamor dos que sofrem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Tem misericórdia de mim, SENHOR; olha para o meu sofrimento, causado pelos que me odeiam; tu, que me levantas para fora das portas da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Para que eu conte todos os teus louvores nas portas da filha de Sião, e me alegre em tua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'As nações se afundaram na cova que elas fizeram; o pé delas ficou preso na rede que esconderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'O SENHOR foi conhecido pelo juízo que fez; o perverso foi enlaçado pelas obras de suas próprias mãos. (Higaiom, Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Os perversos voltarão ao mundo dos mortos; e também todas as nações que se esquecem de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Porque o necessitado não será esquecido para sempre; nem a esperança dos oprimidos perecerá eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Levanta-te, SENHOR, não prevaleça o homem contra ti; sejam julgadas as nações diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Põe medo neles, SENHOR; saibam as nações que eles são meros mortais. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Por que, SENHOR, tu estás longe? Por que tu te escondes em tempos de angústia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Com arrogância o perverso persegue furiosamente ao miserável; sejam presos nas ciladas que planejaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Pois o perverso se orgulha do desejo de sua alma; ele bendiz ao ganancioso, e blasfema do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Pela arrogância de seu rosto o perverso não se importa; Deus não existe em todos as seus pensamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Em todo tempo seus caminhos atormentam; teus juízos estão longe do rosto dele, em grande altura; ele sopra furiosamente todos os seus adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Ele diz em seu coração: Eu nunca serei abalado; porque de geração após geração nunca sofrerei mal algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sua boca está cheia de maldição, e de enganos, e de falsidade; debaixo de sua língua há sofrimento e maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Eles se sentam postos para as ciladas das aldeias; nos esconderijos ele mata ao inocente; seus olhos observam secretamente ao contra o pobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Ele arma ciladas no esconderijo, como o leão em seu covil; arma ciladas para roubar ao miserável; rouba ao miserável, trazendo-o em sua rede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Ele se encolhe, se agacha, para que os pobres caiam em suas armadilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Ele diz em seu coração: Deus já se esqueceu; já escondeu o seu rosto, nunca mais o verá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Levanta-te, SENHOR Deus, ergue tua mão; não te esqueças dos miseráveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Por que o perverso blasfema de Deus? Ele diz eu seu coração que tu nada lhe exigirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Tu estás o vendo; porque tu olhas para o trabalho e o cansaço, para o entregar em tuas mãos; em ti o pobre põe confiança; tu és o que ajuda ao órfão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Quebra tu o braço do perverso e do maligno; faz cobrança da maldade dele, até que tu aches nada mais dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'O SENHOR é Rei eterno e para todo o sempre; as nações perecerão de sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'SENHOR, tu ouviste o desejo dos humildes; tu fortalecerás os seus corações, e teus ouvidos os ouvirão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Para fazer justiça ao órfão e ao afligido; para que o homem não mais continue a praticar o terror.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Salmo de Davi, para o regente: No SENHOR eu confio; como, pois, tu dizeis à minha alma: Fugi para vossa montanha, como um pássaro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Porque eis que os maus estão armando o arco; eles estão pondo suas flechas na corda, para atirarem às escuras com elas aos corretos de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Se os fundamentos são destruídos, o que o justo pode fazer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'O SENHOR está em seu santo Templo, o trono do SENHOR está nos céus; seus olhos observam com atenção; suas pálpebras provam aos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'O SENHOR prova ao justo; mas sua alma odeia ao perverso e ao que ama a violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Sobre os perversos choverá laços, fogo e enxofre; e o pagamento para seu cálice será vento tempestuoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Porque o SENHOR é justo, e ama as justiças; seu rosto presta atenção ao que é correto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Salmo de Davi, para o regente, com harpa de oito cordas: Salva, SENHOR, porque os bons estão em falta; porque são poucos os fiéis dentre os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Cada um fala falsidade ao seu próximo, com lábios elogiam falsamente; falam com duas intenções no coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Que o SENHOR corte a todos os lábios que falam falsos elogios, e toda língua que fala grandes mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Pois dizem: Com nossa língua prevaleceremos; nossos lábios são nossos; que é senhor sobre nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'O SENHOR diz: Pela opressão aos humildes, pelo gemido dos necessitados, eu agora me levantarei; porei em segurança àquele a quem ele sopra desejando oprimir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'As palavras do SENHOR são palavras puras, como prata refinada em forno de barro, purificada sete vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Tu, SENHOR, os guardarás; desta geração os livrarás para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Os maus andam cercando, enquanto os mais vis dos filhos dos homens são exaltados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Salmo de Davi, para o regente: Até quando, SENHOR, te esquecerás de mim? Para sempre? Até quando tu esconderás de mim o teu rosto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Até quando refletirei em minha alma, tendo tristeza em meu coração o dia todo? Até quando o meu inimigo se levantará contra mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Olha para mim, e ouve-me, SENHOR meu Deus; ilumina os meus olhos, para que eu não adormeça na morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Para que meu inimigo não diga: Eu o venci;e meus inimigos se alegrem, se eu vier a cair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Mas eu confio em tua bondade; em tua salvação meu coração se alegrará;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Cantarei ao SENHOR, porque ele tem me feito muito bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Salmo de Davi, para o regente: O tolo diz em seu coração: Não há Deus.Eles têm se pervertido, fazem obras abomináveis; não há quem faça o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'O SENHOR olhou desde os céus para os filhos dos homens, para ver se havia alguém prudente, que buscasse a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Todos se desviaram, juntamente se contaminaram; não há quem faça o bem, nem um sequer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Será que não têm conhecimento todos os que praticam a maldade? Eles devoram a meu povo como se comessem pão, e não clamam ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Ali eles se encherão de medo, porque Deus está com a geração dos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Vós envergonhais os planos do humilde, mas o SENHOR é o refúgio dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ah, que de Sião venha a salvação de Israel! Quando o SENHOR restaurar o seu povo de seu infortúnio, Jacó jubilará, Israel se alegrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Salmo de Davi: SENHOR, quem morará em tua tenda? Quem habitará no monte de tua santidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Aquele que anda sinceramente, e pratica a justiça; e com seu coração fala a verdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Aquele que não murmura com sua língua; não faz mal ao seu companheiro, nem aceita insulto contra seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Em seus olhos despreza à pessoa que é digna de reprovação, mas honra aos que temem ao SENHOR; mantém seu juramento até sob seu próprio prejuízo, e não muda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Tal pessoa não empresta seu dinheiro com juros; nem aceita suborno contra o inocente; quem faz isto, nunca se abalará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Cântico de Davi: Guarda-me, ó Deus; porque eu confio em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Tu, minha alma, disseste ao SENHOR: Tu és meu Senhor; minha bondade não chega até ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Mas aos santos que estão na terra, e a os ilustres, nos quais está todo o meu prazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'As dores se multiplicarão daqueles que se apressam para servir a outros deuses; eu não oferecerei seus sacrifícios de derramamento de sangue, e não tomarei seus nomes em meus lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'O SENHOR é a porção da minha herança e o meu cálice; tu sustentas a minha sorte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Em lugares agradáveis foram postos os limites do meu terreno; sim, eu recebo uma bela propriedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Eu louvarei ao SENHOR, que me aconselhou; até de noite meus sentimentos me ensinam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Ponho ao SENHOR continuamente diante de mim; porque ele está à minha direita; nunca serei abalado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Por isso meu coração está contente, e minha glória se alegra; certamente minha carne habitará em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Porque tu não deixarás a minha alma no mundo dos mortos, nem permitirás que teu Santo veja corrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tu me farás conhecer o caminho da vida; fartura de alegrias há em tua presença; agrados estão em tua mão direita para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Oração de Davi: Ouve, SENHOR, a minha justiça; presta atenção ao meu choro, dá ouvidos à minha oração de lábios que não enganam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'De diante de teu rosto saia o meu julgamento; teus olhos observarão o que é justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Tu já provaste o meu coração, tu me visitaste de noite; tu me investigaste, e nada achaste; decidi que minha boca não transgredirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Quanto às obras dos homens, conforme a palavra de teus lábios eu me guardei dos caminhos do violento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Guiando meu andar em teus caminhos, para que meus passos não tropecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Eu clamo a ti, ó Deus, porque tu me respondes; inclina teus ouvidos a mim, escuta a minha palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Revela maravilhosamente tuas misericórdias, tu salvas aos que confiam em ti com tua mão direita daqueles se se levantam contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Guarda-me como a pupila do olho; esconde-me debaixo da sombra de tuas asas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'De diante dos perversos que me oprimem; dos meus mortais inimigos que me cercam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Eles se enchem de gordura; com sua boca falam arrogantemente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Agora eles têm nos cercado em nossos passos; eles fixam seus olhos para nos derrubar ao chão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Semelhantes ao leão, que deseja nos despedaçar, e ao leãozinho, que fica em esconderijos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Levanta-te, SENHOR, confronta-o, derruba-o; livra minha alma d as mãos do perverso com tua espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Dos homens com tua mão, SENHOR, dos homens que são do mundo, cuja parte está n esta vida, cujo ventre enches de teu secreto tesouro; os filhos se fartam, e deixam sua sobra para suas crianças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Mas eu olharei para teu rosto em justiça; serei satisfeito de tua semelhança, quando eu despertar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Para o regente. Do servo do SENHOR, chamado Davi, o qual falou as palavras deste cântico ao SENHOR, no dia em que o SENHOR o livrou das mãos de todos os seus inimigos, e das mãos de Saul. Ele disse: Eu te amarei, SENHOR, tu és minha força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'O SENHOR é minha rocha, e minha fortaleza, e meu libertador, meu Deus, meu rochedo, em quem confio; é meu escudo, e a força da minha salvação, meu alto refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Eu clamei ao SENHOR digno de louvor; e fiquei livre de meus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Cordas de morte me cercaram; e riachos de maldade me encheram de medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Cordas do mundo dos mortos me envolveram; laços de morte me confrontaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Em minha angústia, clamei ao SENHOR, e roguei a meu Deus; desde o seu Templo ele ouviu a minha voz; e o meu clamor diante de seu rosto chegou aos ouvidos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Então a terra de abalou e tremeu; e os fundamentos dos montes de moveram e foram abalados, porque ele se irritou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Fumaça subiu de seu nariz, e fogo consumidor saiu de sua boca; carvões foram acesos por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Ele moveu os céus, e desceu; e as trevas estavam debaixo de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Ele montou sobre um querubim, e fez seu voo; e voou veloz sobre as assas do vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Ele pôs as trevas como seu esconderijo; pôs a sua tenda ao redor dele; trevas das águas, nuvens dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Do brilho de sua presença suas nuvens se espalharam, e também a saraiva, e as brasas de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'E o SENHOR trovejou nos céus; e o Altíssimo soltou sua voz; saraiva e brasas de fogo caíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Ele mandou suas flechas, e os dispersou; e lançou muitos raios, e os perturbou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'E as profundezas das águas foram vistas, e os fundamentos do mundo foram descobertos por tua repreensão, SENHOR, pelo sopro do vento do teu nariz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Desde o alto ele enviou, e me tomou; tirou-me de muitas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Ele me livrou do meu forte inimigo, e daqueles que me odeiam; porque eles eram mais poderosos do que eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Eles me confrontaram no dia de minha calamidade; mas o SENHOR ficou junto de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Ele me tirou para um lugar amplo; ele me libertou, porque se agradou de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'O SENHOR me recompensou conforme a minha justiça; conforme a pureza das minhas mãos ele me retribuiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Porque eu guardei os caminhos do SENHOR; nem me afastei do meu Deus praticando o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Porque todos os juízos dele estavam diante de mim; e não rejeitei seus estatutos para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Mas eu fui fiel com ele; e tomei cuidado contra minha maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Assim o SENHOR me recompensou conforme a minha justiça; conforme a pureza de minhas mãos perante seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Com o bondoso tu te mostras bondoso; e com o homem fiel tu te mostras fiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Com o puro tu te mostras puro; mas com o perverso tu te mostras agressivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Porque tu livras ao povo aflito, e humilhas aos olhos que se exaltam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Porque tu acendes minha lâmpada; o SENHOR meu Deus ilumina as minhas trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Porque contigo eu marcho contra um exército; e com meu Deus eu salto um muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'O caminho de Deus é perfeito; a palavra do SENHOR é refinada; ele é escudo para todos os que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Porque quem é Deus, a não ser o SENHOR? E quem é rocha, a não ser o nosso Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Deus é o que me veste de força; e o que dá perfeição ao meu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Ele faz meus pés como o das cervas; e me põe em meus lugares altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Ele ensina minhas mãos para a guerra, de modo que um arco de bronze se quebra em meus braços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Também tu me deste o escudo de tua salvação, e tua mão direita me sustentou; e tua mansidão me engrandeceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Tu alargaste os meus passos abaixo de mim; e meus pés não vacilaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Persegui a meus inimigos, e eu os alcancei; e não voltei até os exterminá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Eu os perfurei, que não puderam mais se levantar; caíram debaixo dos meus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Porque tu me preparaste com força para a batalha; fizeste se curvarem abaixo de mim aqueles que contra mim tinham se levantado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'E tu me deste a nuca de meus inimigos; destruí aos que me odiavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Eles clamaram, mas não havia quem os livrasse; clamaram até ao SENHOR, mas ele não lhes respondeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Então eu os reduzi a pó, como a poeira ao vento; eu os joguei fora como a lama das ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Tu me livraste das brigas do povo; tu me puseste como cabeça das nações; o povo que eu não conhecia me serviu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Ao me ouvirem, logo me obedeceram; estrangeiros se sujeitaram a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Estrangeiros se enfraqueceram; e tremeram de medo desde suas extremidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'O SENHOR vive, e bendito seja minha rocha; e exaltado seja o Deus de minha salvação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'O Deus que dá minha vingança, e sujeita aos povos debaixo de mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Aquele que me livra dos meus inimigos; tu também me exaltas sobre aqueles que se levantam contra mim; tu me livras do homem violento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Por isso, SENHOR, eu te louvarei entre as nações, e cantarei ao teu Nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Que faz grandes as salvações de seu Rei, e pratica a bondade para com o seu ungido, com Davi, e sua semente, para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Salmo de Davi, para o regente: Os céus declaram a glória de Deus; e o firmamento anuncia a obra de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Dia após dia ele fala; e noite após noite ele mostra sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Não há língua, nem palavras, onde não se ouça a voz deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Por toda a terra sai sua corda, e suas palavras até o fim do mundo; para o sol ele pôs uma tenda neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'E ele é como o noivo, que sai de sua câmara; e se alegra como um homem valente, para correr seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Desde uma extremidade dos céus é sua saída, e seu curso até as outras extremidades deles; e nada se esconde de seu calor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'A lei do SENHOR é perfeita, e restaura a alma; o testemunho do SENHOR é fiel, e da sabedoria aos simples.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Os preceitos do SENHOR são corretos, e alegram ao coração; o mandamento do SENHOR é puro, e ilumina aos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'O temor ao SENHOR é limpo, e permanece para sempre; os juízos do SENHOR são verdade; juntamente são justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'São mais desejáveis que ouro, mais do que muito ouro fino; e mais doces que o mel, e o licor de seus favos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Também por eles teu servo é advertido; por guardá-los, há muita recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Quem pode entender seus próprios erros? Limpa-me dos que me são ocultos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Também retém a teu servo de arrogâncias, para que elas não me controlem; então eu serei sincero, e ficarei limpo de grande transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Sejam agradáveis as palavras de minha boca, e o pensamento do meu coração, diante de ti, ó SENHOR, minha rocha e meu Libertador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Salmo de Davi, para o regente: Que o SENHOR te responda no dia da angústia; o nome do Deus de Jacó te ponha em lugar seguro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Que ele envie a ti ajuda desde seu santuário; e desde Sião ele te sustenha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Que ele se lembre de todas as tuas ofertas, e aceite a tua oferta de queima. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Que ele de a ti conforme o teu coração, e faça cumprir todo o teu propósito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Nós alegraremos muito por tua salvação, e no nome do nosso Deus levantaremos bandeiras; que o SENHOR cumpra todos os teus pedidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Agora eu sei que o SENHOR salva a seu ungido; desde os céus de sua santidade ele lhe responderá, com o poder salvador de sua mão direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Alguns confiam em carruagens, e outros em cavalos; mas nós nos lembraremos do nome do SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Eles se encurvam, e caem; mas nós nos levantamos, e ficamos em pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Salva -nos,SENHOR! Que o Rei nos ouça no dia de nosso clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Salmo de Davi para o regente: SENHOR, em tua força o rei se alegra; e como ele fica contente com tua salvação!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Tu lhe deste o desejo de seu coração; e tu não negaste o pedido de seus lábios. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Porque tu foste até ele com bênçãos de bens; tu puseste na cabeça dele uma coroa de ouro fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Ele te pediu vida, e tu lhe deste; muitos dias, para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Grande é a honra dele por tua salvação; honra e majestade tu lhe concedeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Porque tu o pões em bênçãos para sempre; tu fazes abundante a alegria dele com tua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Porque o rei confia no SENHOR; e ele nunca se abalará com a bondade do Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Tua mão alcançará a todos o os teus inimigos; tua mão direita encontrará aos que te odeiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Tu os porás como que num forno de fogo no tempo em que se encontrarem em tua presença; o SENHOR em sua ira os devorará; e fogo os consumirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Tu destruirás o fruto deles de sobre a terra; e também a semente deles dos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Porque eles quiseram o mal contra ti; planejaram uma cilada, mas não tiveram sucesso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Porque tu os porás em fuga; com tuas flechas nas cordas tu lhes apontarás no rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Exalta-te, SENHOR, em tua força; cantaremos e louvaremos o teu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Salmo de Davi para o regente, como em “cerva da manhã”: Deus meu, Deus meu, por que me desamparaste? Longe estás de meu livramento e das palavras de meu gemido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Deus meu, eu clamo de dia, e tu não me respondes; também clamo de noite, e não tenho sossego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Porém tu és Santo, que habitas nos louvores de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Nossos pais confiaram em ti; eles confiaram, e tu os livraste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Eles clamaram a ti, e escaparam do perigo; eles confiaram em ti, e não foram envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Mas eu sou um verme, e não um homem; sou humilhado pelos homens, e desprezado pelo povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Todos os que me veem zombam de mim; abrem os lábios e sacodem a cabeça, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Ele confiou no “SENHOR”; agora que ele o salve e o liberte; pois se agrada nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Tu és o que me tiraste do ventre; e o que me deu segurança, estando eu junto aos seios de minha mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Eu fui lançado sobre ti desde que saí d o útero; desde o ventre de minha mãe tu és meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Não fiques longe de mim, porque a minha angústia está perto; pois não há quem me ajude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Muitos touros me cercaram; fortes de Basã me rodearam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Abriram contra mim suas bocas, como leão que despedaça e ruge.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Eu me derramei como água, e todos os meus ossos se soltaram uns dos outros; meu coração é como cera, e se derreteu por entre meus órgãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Minha força se secou como um caco de barro, e minha língua está grudada no céu da boca; e tu me pões no pó da morte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Porque cães ficaram ao meu redor; uma multidão de malfeitores me cercou; perfuraram minhas mãos e meus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Eu poderia contar todos os meus ossos; eles estão me olhando, e prestando atenção em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Eles repartem entre si minhas roupas; e sobre minha vestimenta eles lançam sortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Porém tu, SENHOR, não fiques longe; força minha, apressa-te para me socorrer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Livra minha alma da espada; e minha vida da violência do cão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Salva-me da boca do leão; e responde-me dos chifres dos touros selvagens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Então eu contarei teu nome a meus irmãos; no meio da congregação eu te louvarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Vós que temeis ao SENHOR, louvai a ele! E vós, de toda a semente de Jacó, glorificai a ele! Prestai culto a ele, vós de toda a semente de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Porque ele não desprezou nem abominou a aflição do aflito, nem escondeu seu rosto dele; mas sim, quando o aflito clamou, ele o ouviu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Meu louvor será para ti na grande congregação; eu pagarei meus juramentos perante os que o temem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Os humilhados comerão, e ficarão fartos; louvarão ao SENHOR aqueles que o buscam; vosso coração viverá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Todos os extremos da terra se lembrarão disso, e se converterão ao SENHOR; e todas as gerações das nações adorarão diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Porque o reino pertence ao SENHOR; e ele governa sobre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Todos os ricos da terra comerão e adorarão, e perante o rosto dele se prostrarão todos os que descem ao pó, e que não podem manter viva sua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'A descendência o servirá; ela será contada ao Senhor, para a geração seguinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Chegarão, e anunciarão a justiça dele ao povo que nascer, porque ele assim fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Salmo de Davi: O SENHOR é meu pastor, nada me faltará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Ele me faz deitar em pastos verdes, e me leva a águas quietas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Ele restaura minha alma, e me guia pelos caminhos da justiça por seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Ainda que eu venha a andar pelo vale da sombra da morte, não temerei mal algum, porque tu estás comigo; tua vara e teu cajado me consolam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Tu preparas uma mesa diante de mim à vista de meus adversários; unges a minha cabeça com azeite, meu cálice transborda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Certamente o bem e a bondade me seguirão todos os dias de minha vida; e habitarei na casa do SENHOR por muitos e muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Salmo de Davi: Ao SENHOR pertence a terra, e sua plenitude; o mundo, e os que nele habitam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Porque ele a fundou sobre os mares; e sobre os rios ele a firmou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Quem subirá ao monte do SENHOR? E quem ficará de pé no lugar de sua santidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Aquele que é limpo de mãos, e puro de coração, que não entrega sua alma para as coisas vãs, nem jura enganosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Este receberá a bênção do SENHOR, e a justiça do Deus de sua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Esta é a geração dos que o buscam, dos que procuram a tua face: a geração de Jacó. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Levantai, portas, vossas cabeças; e levantai-vos vós, entradas eternas; para que entre o Rei da Glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Quem é o Rei da Glória? O SENHOR forte e poderoso, o SENHOR poderoso na guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Levantai, portas, vossas cabeças; e levantai-vos vós, entradas eternas; para que entre o Rei da Glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Quem é este Rei da Glória? O SENHOR dos exércitos; ele é o Rei da Glória! (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Salmo de Davi: A ti, SENHOR, levanto minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Meu Deus, eu confio em ti; não me deixes envergonhado, nem que meus inimigos se alegrem por me vencerem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Certamente todos os que esperam em ti, nenhum será envergonhado; envergonhados serão os que traem sem motivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Tu me fazes conhecer os teus caminhos; ensina-me teus lugares onde se deve andar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Guia-me em tua verdade, e ensina-me; porque tu és o Deus de minha salvação; eu espero por ti o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Lembra-te, SENHOR, de tuas misericórdias e de tuas bondades; porque elas são desde a eternidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Não te lembres dos pecados de minha juventude e das minhas transgressões; mas sim, conforme tua misericórdia, lembra-te de mim por tua bondade, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'O SENHOR é bom e correto; por isso ele ensinará o caminho aos pecadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Ele guiará os humildes ao bom juízo; e ensinará aos humildes seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Todos os caminhos do SENHOR são bondade e verdade, para aqueles que guardam seu pacto e seus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Pelo teu nome, SENHOR, perdoa a minha maldade, porque ela é grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Qual é o homem que teme ao SENHOR? Ele lhe ensinará o caminho que deve escolher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Sua alma habitará no bem; e sua semente isto é, sua descendência possuirá a terra em herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'O segredo do SENHOR é para os que o temem; e ele lhes faz conhecer seu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Meus olhos estão continuamente voltados para o SENHOR, porque ele tirará meus pés da rede de caça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Olha para mim, e mim, e tem piedade de mim, porque eu estou solitário e miserável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'As aflições de meu coração têm se multiplicado; tira-me de minhas angústias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Presta atenção para minha miséria e meu cansativo trabalho; e tira todos os meus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Presta atenção a meus inimigos, porque eles estão se multiplicando; eles me odeiam com ódio violento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Guarda minha alma, e livra-me; não me deixes envergonhado, porque eu confio em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Sinceridade e justiça me guardem, porque eu espero em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Ó Deus, resgata a Israel de todas as suas angústias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Salmo de Davi: Faze-me justiça, SENHOR, pois eu ando em minha sinceridade; e eu confio no SENHOR, não me abalarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Prova-me, SENHOR, e testa-me; examina meus sentimentos e meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Porque tua bondade está diante dos meus olhos; e eu ando em tua verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Não me sento com homens vãos, nem converso com desonestos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Eu odeio a reunião dos malfeitores; e não me sento com os perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Lavo minhas mãos em inocência, e ando ao redor do teu altar, SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Para que eu declare com voz de louvores, e para contar todas as tuas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'SENHOR, eu amo a morada de tua Casa, e o lugar onde habita a tua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Não juntes minha alma com os pecadores, nem minha vida com homens sanguinários;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Nas mãos deles há más intenções; e sua mão direita é cheia de suborno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mas eu ando em minha sinceridade; livra-me e tem piedade de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Meu pé está em um caminho plano; louvarei ao SENHOR nas congregações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Salmo de Davi: O SENHOR é minha luz e minha salvação; a quem temerei? O SENHOR é a força da minha vida; de quem terei medo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Quando os maus chegaram perto de mim, meus adversários e meus inimigos contra mim, para devorarem minha carne; eles mesmos tropeçaram e caíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Ainda que um exército me cercasse, eu não temeria; ainda que uma guerra se levantasse contra mim, nisto mantenho confiança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Pedi uma coisa ao SENHOR, e a ela buscarei: que eu possa morar na casa do SENHOR todos os dias de minha vida, para ver a beleza do SENHOR, e consultá-lo em seu Templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Porque no dia mal ele me esconderá em seu abrigo; ele me encobrirá no oculto de sua tenda; e me porá sobre as rochas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'E minha cabeça será exaltada acima de meus inimigos, que estão ao redor de mim; e eu sacrificarei na tenda dele sacrifícios com alta voz; cantarei e louvarei ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Ouve, SENHOR, minha voz, quando eu clamo; tem piedade de mim, e responde-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Ele diz a ti, meu coração: Buscai a minha face.Eu busco a tua face, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Não escondas de mim a tua face, nem rejeites a teu servo com ira; tu tens sido meu socorro; não me deixes, nem me desampares, ó Deus de minha salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Porque meu pai e minha mãe me abandonaram, mas o SENHOR me recolherá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Ensina-me, SENHOR, o teu caminho; e guia-me pela via correta, por causa dos meus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Não me entregues à vontade dos meus adversários, porque se levantaram contra mim falsas testemunhas, e também ao que sopra violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Se eu não tivesse crido que veria a bondade do SENHOR na terra dos viventes, certamente já teria perecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Espera no SENHOR, esforça-te, e ele fortalecerá o teu coração; espera pois ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Salmo de Davi: A ti, SENHOR, rocha minha, eu clamo; não te silencies para comigo; para que não aconteça de, se tu calares quanto a mim, eu não me torne semelhante aos que descem à cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Ouve a voz de minhas súplicas, quando eu clamar a ti, ao levantar às minhas mãos ao templo de tua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Não me jogues fora com os perversos, nem com os praticantes da maldade, que falam de paz com sem próximo, porém há o mal no coração deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Dá-lhes conforme as obras deles, e conforme a maldade de seus atos; dá-lhes conforme a obra das mãos deles, retribui-lhes como eles merecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Porque eles não dão atenção para os atos do SENHOR, nem para a obra de suas mãos; então ele os derrubará e não os edificará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Bendito seja o SENHOR, porque ele ouviu a voz de minhas súplicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'O SENHOR é a minha força e meu escudo; meu coração confiou nele, e foi socorrido; por isso meu coração salta de alegria; e com meu canto eu o louvarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'O SENHOR é a força deles, e o poder das salvações de seu Ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Salva a teu povo, e abençoa a tua herança; e apascenta-os, e levanta-os para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Salmo de Davi: Reconhecei ao SENHOR, vós filhos dos poderosos, reconhecei ao SENHOR sua glória e força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Reconhecei ao SENHOR a glória de seu nome; adorai ao SENHOR na honra da santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'A voz do SEHOR percorre por sobre as águas; o Deus da glória troveja; o SENHOR está sobre muitas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'A voz do SENHOR é poderosa; a voz do SENHOR é gloriosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'A voz do SENHOR quebra aos cedros; o SENHOR quebra aos cedros do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Ele os faz saltar como bezerros; ao Líbano e a Sírion como a filhotes de bois selvagens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'A voz do SENHOR faz chamas de fogo se separarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'A voz do SENHOR faz tremer o deserto; o SENHOR faz tremer o deserto de Cades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'A voz do SENHOR faz as cervas terem filhotes, e tira a cobertura das florestas; e em seu templo todos falam de sua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'O SENHOR se sentou sobre as muitas águas como dilúvio; e o SENHOR se sentará como rei para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'O SENHOR dará força a seu povo; o SENHOR abençoará a seu povo com paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Salmo e canção de Davi para a dedicação da casa: Eu te exaltarei, SENHOR, porque tu me levantaste, e fizeste com que meus inimigos não se alegrassem por causa de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'SENHOR, meu Deus; eu clamei a ti, e tu me curaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'SENHOR, tu levantaste minha alma para fora do mundo dos mortos; tu guardaste minha vida, para que eu não descesse à sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Cantai ao SENHOR, vós que sois santos dele, e celebrai a memória de sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Porque sua ira dura por um momento; mas seu favor dura por toda a vida; o choro fica pela noite, mas a alegria vem pela manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Eu disse em minha boa situação: Nunca serei abalado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'SENHOR, pelo teu favor, tu firmaste minha montanha; mas quando tu encobriste o teu rosto, fiquei perturbado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'A ti, DEUS, eu clamei; e supliquei ao SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Dizendo: Que proveito há em meu sangue, ou em minha descida a cova? Por acaso o pó da terra te louvará, ou anunciará tua fidelidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Ouve -me, SENHOR, e tem piedade de mim; sê tu, SENHOR, o meu ajudador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Tu tornaste meu pranto em dança; tu desamarraste o meu saco de lamentação, e me envolveste de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Por isso a minha glória cantará para ti, e não se calará; SENHOR, Deus meu, para sempre eu te louvarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Salmo de Davi, para o regente: Eu confio em ti, SENHOR; não me deixes envergonhado para sempre; livra-me por tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Inclina a mim os teus ouvidos, faze-me escapar depressa do perigo; sê tu por minha rocha firme, por casa fortíssima, para me salvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Porque tu és minha rocha e minha fortaleza; guia-me e conduz-me por causa do teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Tira-me da rede que me prepararam em segredo, pois tu és minha força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Em tuas mãos eu confio meu espírito; tu me resgataste, SENHOR, Deus da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Odeio os que dedicam sua atenção a coisas vãs e enganosas; porém eu confio no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Em tua bondade eu me alegrarei e ficarei cheio de alegria, porque tu viste minha situação miserável; tu reconheceste as angústias de minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'E tu não me entregastes nas mãos do meu inimigo; tu puseste meus pés num lugar amplo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Tem misericórdia de mim, SENHOR, porque eu estou angustiado; meus olhos, minha alma e meu ventre foram consumidos pelo sofrimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Porque minha vida foi destruída pela aflição, e meus anos pelos suspiros; minha força descaiu por minha maldade; e meus ossos se enfraqueceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Por causa de todos os meus adversários eu fui humilhado até entre os meus próximos; e fui feito horrível entre os meus conhecidos; os que me veem na rua fogem de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'No coração deles eu fui esquecido, como se estivesse morto; me tornei como um vaso destruído.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Porque ouvi a murmuração de muitos, temor há ao redor; juntamente tramam contra mim, planejam como matar minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Mas eu confio em ti, SENHOR, eu te chamo de meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Meus tempos estão em tuas mãos; livra-me da mão dos meus inimigos e daqueles que me perseguem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Faz brilhar o teu rosto sobre teu servo; salva-me por tua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'SENHOR, não me deixes envergonhado, pois eu clamo a ti; que os perversos se envergonhem, calem-se eles no mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Emudeçam os lábios mentirosos, que falam coisas duras contra o justo, com arrogância e desprezo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Como é grade a tua bondade, que guardaste para aqueles que te temem! Tu trabalhaste para os que confiam em ti, na presença dos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'No esconderijo de tua presença tu os escondes das arrogâncias dos homens; em tua tenda tu os encobres da rivalidade das línguas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Bendito seja o SENHOR, pois ele fez maravilhosa sua bondade para comigo, como uma cidade segura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Eu dizia em minha aflição: Estou cortado de diante de teus olhos.Porém tu ouviste a voz de minhas súplicas quando clamei a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Amai ao SENHOR, todos vós santos dele; o SENHOR guarda aos fiéis, e retribui abundantemente ao que usa de arrogância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Sede fortes, e ele fortalecerá vosso coração, todos vós que esperais no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Instrução de Davi: Bem-aventurado aquele cuja transgressão é perdoada, cujo pecado é encoberto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Bem-aventurado o homem a quem o SENHOR não considera a maldade, e em cujo espírito não há engano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Enquanto fiquei calado, meus ossos ficaram cada vez mais fracos com meu gemido pelo dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Porque de dia e de noite tua mão pesava sobre mim; meu humor ficou seco como no verão. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Eu reconheci meu pecado a ti, e não escondi minha maldade. Eu disse: Confessarei ao SENHOR minhas transgressões;E tu perdoaste a maldade do meu pecado. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Por isso cada santo deve orar a ti em todo tempo que achar; até no transbordar de muitas águas, elas não chegarão a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tu és meu esconderijo, tu me guardas da angústia; tu me envolves de canções alegres de liberdade. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Eu te instruirei, e de ensinarei o caminho que deves seguir; eu te aconselharei, e porei meus olhos em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Não sejais como o cavalo ou como a mula, que não têm entendimento; cuja boca é presa com o cabresto e o freio, para que não cheguem a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'O perverso terá muitas dores, mas aquele que confia no SENHOR, a bondade o rodeará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Alegrai-vos no SENHOR, e enchei de alegria vós justos, e cantai alegremente todos os corretos de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Cantai ao SENHOR, vós que sois justos; aos corretos convém louvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Louvai ao SENHOR com harpa; cantai a ele com alaúde e instrumento de dez cordas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Cantai-lhe uma canção nova; tocai instrumento bem com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Porque a palavra do SENHOR é correta; e todas suas obras são fiéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Ele ama a justiça e o juízo; a terra está cheia da bondade do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Pala palavra do SENHOR foram feitos os céus; e todo o seu exército foi feito pelo sopro de sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Ele junta as águas do mar como se estivessem empilhadas; aos abismos ele põe como depósitos de tesouros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Toda a terra, tenha temor ao SENHOR; todos os moradores do mundo prestem reverência a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Porque ele falou, e logo se fez; ele mandou, e logo apareceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'O SENHOR desfez a intenção das nações; ele destruiu os planos dos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'O conselho do SENHOR permanece para sempre; as intenções de seu coração continuam de geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Bem-aventurada é a nação em que seu Deus é o SENHOR; o povo que ele escolheu para si por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'O SENHOR olha desde os céus; ele vê a todos os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Desde sua firme morada ele observa a todos os moradores da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Ele forma o coração de todos eles; ele avalia todas as obras deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'O rei não se salva pela grandeza de seu exército, nem o valente escapa do perigo pela sua muita força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'O cavalo é falho como segurança, com sua grande força não livra do perigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Eis que os olhos do SENHOR estão sobre aqueles que o temem, sobre os que esperam pela sua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Para livrar a alma deles da morte, e para os manter vivos durante a fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Nossa alma espera no SENHOR; ele é nossa socorro e nosso escudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Porque nele nosso coração se alegra, porque confiamos no nome de sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Que tua bondade, SENOR, esteja sobre nós, assim como nós esperamos em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Salmo de Davi, quando ele mudou seu comportamento perante Abimeleque, que o expulsou, e ele foi embora: Louvarei ao SENHOR em todo tempo; haverá louvor a ele continuamente em minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Minha alma se orgulhará no SENHOR; os humildes ouvirão, e se alegrarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Engrandecei ao SENHOR comigo, e juntos exaltemos o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Busquei ao SENHOR. Ele me respondeu, e me livrou de todos os meus temores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Os que olham para ele ficam visivelmente alegres, e seus rostos não são envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Este miserável clamou, e o SENHOR ouviu; e ele o salvou de todas as suas angústias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'O anjo do SENHOR fica ao redor daqueles que o temem, e os livra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Experimentai, e vede que o SENHOR é bom; bem-aventurado é o homem que confia nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Temei ao SENHOR vós, os seus santos; porque nada falta para aqueles que o temem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Os filhos dos leões passam necessidades e têm fome; mas os que buscam ao SENHOR não têm falta de bem algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Vinde, filhos, ouvi a mim; eu vos ensinarei o temor ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Quem é o homem que deseja vida, que ama viver por muitos dias, para ver o bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Guarda a tua língua do mal, e os teus lábios de falar falsidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Desvia-te do mal, e faze o bem; busca a paz, e segue-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Os olhos do SENHOR estão sobre os justos, e seus ouvidos atentos ao seu clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'A face do SENHOR está contra aqueles que fazem o mal, para tirar da terra a memória deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Os justos clamam, e o SENHOR os ouve. Ele os livra de todas as suas angústias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'O SENHOR está perto daqueles que estão com o coração partido, e sava os aflitos de espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Muitas são as adversidades do justo, mas o SENHOR o livra de todas elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Ele guarda todos os seus ossos; nenhum deles é quebrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'O mal matará o perverso, e os que odeiam o justo serão condenados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'O SENHOR resgata a alma de seus servos, e todos os que nele confiam não receberão condenação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Salmo de Davi: Disputa, SENHOR contra os meus adversários; luta contra os que lutam contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Pega os teus pequeno e grande escudos, e levanta-te em meu socorro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'E tira a lança, e fecha o caminho ao encontro de meus perseguidores; dize à minha alma: Eu sou tua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Envergonhem-se, e sejam humilhados os que buscam matar a minha alma; tornem-se para trás, e sejam envergonhados os que planejam o mal contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Sejam como a palha perante o vento; e que o anjo do SENHOR os remova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Que o caminho deles seja escuro e escorregadio; e o anjo do SENHOR os persiga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Porque sem motivo eles esconderam de mim a cova de sua rede; sem motivo eles cavaram para minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Venha sobre ele a destruição sem que ele saiba de antemão; e sua rede, que ele escondeu, que o prenda; que ele, assolado, caia nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'E minha alma se alegrará no SENHOR; ela se encherá de alegria por sua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Todos os meus ossos dirão: SENHOR, quem é como tu, que livras ao miserável daquele que é mais forte do que ele, e ao miserável e necessitado, daquele que o rouba?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Levantam-se más testemunhas; exigem de mim coisas que não sei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Ele retribuem o bem com o mal, desolando a minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Mas eu, quando ficavam doentes, minha roupa era de saco; eu afligia a minha alma com jejuns, e minha oração voltava ao meu seio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Eu agia para com eles como para um amigo ou irmão meu; eu andava encurvado, como que de luto pela mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mas quando eu vacilava, eles se alegravam e se reuniam; inimigos se reuniam sem que eu soubesse; eles me despedaçavam em palavras,e não se calavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Entre os fingidos zombadores em festas, eles rangiam seus dentes por causa de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Senhor, até quando tu somente observarás? Resgata minha alma das assolações deles; minha única vida dos filhos dos leões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Assim eu te louvarei na grande congregação; numa grande multidão eu celebrarei a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Não se alegrem meus inimigos por causa de mim por um mau motivo, nem acenem com os olhos aquele que me odeiam sem motivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Porque eles não falam de paz; mas sim, planejam falsidades contra os pacíficos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'E abrem suas bocas contra mim, dizendo: Ha-ha, nós vimos com nossos próprios olhos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Tu, SENHOR, tens visto isso; não fiques calado; SENHOR, não fiques longe de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Levanta-te e acorda para meu direito, Deus meu, e Senhor meu, para minha causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Julga-me conforme a tua justiça, SENHOR meu Deus; e não deixes eles se alegrarem de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Não digam eles em seus corações: Ahá, vencemos, alma nossa!nem digam: Nós já o devoramos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Que eles se envergonhem, e sejam juntamente humilhados os que se alegram pelo meu mal; vistam-se de vergonha e confusão os que se engrandecem contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Cantem de alegria e sejam muito contentes os que amam a minha justiça; e continuamente digam: Seja engrandecido o SENHOR, que ama o bem-estar de seu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'E minha língua falará de tua justiça, louvando a ti o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Salmo de Davi, servo do SENHOR, para o regente: A transgressão do perverso diz ao meu coração que não há temor a Deus perante seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Porque ele é tão orgulhoso diante de seus olhos que não achar nem odiar sua própria maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'As palavras da boca dele são malícia e falsidade; ele deixou de fazer o que é sábio e bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Ele planeja maldade em sua cama; fica no caminho que não é bom; não rejeita o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'SENHOR, tua bondade alcança os céus, e tua fidelidade chega até as mais altas nuvens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Tua justiça é como as montanhas de Deus, teus juízos como um grande abismo; tu, SENHOR, guardas a vida dos homens e dos animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Como é preciosa, SENHOR, a tua bondade! Porque os filhos dos homens se abrigam à sombra de tuas asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Eles se fartam da comida de tua casa, e tu lhes dás de beber do ribeiro de teus prazeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Porque contigo está a fonte da vida; em tua luz vemos a luz verdadeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Estende tua bondade sobre os que te conhecem; e tua justiça sobre os corretos de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Não venha sobre mim o pé dos arrogantes, e que a não dos perversos não me mova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Ali cairão os que praticam a maldade; eles foram lançados, e não podem se levantar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Salmo de Davi: Não te irrites com os malfeitores, nem tenhas inveja dos que praticam perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Porque assim como a erva, eles logo serão cortados; e como a verdura eles cairão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Confia no SENHOR, e faze o bem; habita a terra, e te alimentarás em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'E agrada-te no SENHOR; e ele te dará os pedidos de teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Conduz teu caminho ao SENHOR, e confia nele; e ele lhe fará o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'E ele manifestará tua justiça como a luz; e teu direito como o sol do meio-dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Descansa-te no SENHOR, e espera por ele; não te irrites contra aquele cujo caminho prospera, nem com o homem que planeja maldades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Detém a ira, abandona o furor; não te irrites de maneira alguma para fazer o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Porque os malfeitores serão exterminados; mas os que esperam no SENHOR herdarão a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'E ainda um pouco, e o perverso não mais existirá; e tu olharás para o lugar dele, e ele não aparecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Mas os mansos herdarão a terra, e se agradarão com muita paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'O perverso trama contra o justo, e range seus dentes contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'O Senhor ri dele, porque vê que já vem o dia dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'O perversos pegarão a espada e armarão seu arco, para abaterem ao miserável e necessitado, para matarem os corretos no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Mas sua espada entrará em seus corações, e seus arcos serão quebrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'O pouco que o justo tem é melhor do que a riqueza de muitos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Porque os braços dos perversos serão quebrados, mas o SENHOR sustenta os justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'O SENHOR conhece os dias dos corretos, e a herança deles permanecerá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Eles não serão envergonhados no tempo mau, e terão fartura nos dias de fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Mas os perversos perecerão, e os inimigos do SENHOR desaparecerão tal como as melhores partes dos cordeiros; eles de desfarão na fumaça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'O perverso toma emprestado, e paga de volta; mas o justo se compadece e dá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Porque os que são por ele abençoados herdarão a terra; mas os que são por ele amaldiçoados serão removidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Os passos do homem justo são preparados pelo SENHOR; e ele tem prazer em seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Quando cai, ele não fica derrubado, pois o SENHOR sustenta a sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Eu já fui jovem, e já envelheci; mas nunca vi o justo desamparado, nem a sua semente a pedir pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'O dia todo ele se compadece, e empresta; e sua semente é abençoada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Afasta-te do mal, e faze o bem; e faça sua habitação eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Porque o SENHOR ama o juízo, e não desampara a seus santos: eles estão guardados para sempre; mas a semente dos perversos será removida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Os justos herdarão a terra, e para sempre nela habitarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'A boca do justo fala de sabedoria, e sua língua fala do bom juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'A Lei de seu Deus está em seu coração; seus passos não serão abalados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'O perverso espia ao justo, e procura matá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Mas o SENHOR não o deixa em suas mãos; nem também o condenará, quando for julgado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Espera no SENHOR, guarda o seu caminho, e ele te exaltará, para herdares a terra; tu verás que os perversos serão removidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Eu vi ao perverso violento crescer como a árvore verde, natural da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Porém ele já foi embora, e eis que ele não existe mais; eu o procurei, e não foi achado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Olha ao sincero, e vê o correto; porque o fim de tal homem é a paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Mas os transgressores serão juntamente destruídos; o fim dos perversos será eliminado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Porém a salvação dos justos vem do SENHOR, que é a força deles no tempo de angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'E o SENHOR os socorrerá, e os livrará; ele os livrará dos perversos, e os salvará, porque nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Salmo de Davi, para lembrança: SENHOR, não me repreendas em tua ira, e não me castigues em teu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Porque tuas flechas me atingiram, e tua mão pesou sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Na minha carne nada há que esteja saudável, por causa de tua ira; não há paz em meus ossos por causa do meu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Porque minhas maldades ultrapassam minha cabeça; elas são como carga pesada demais para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Minhas feridas fedem, e estão apodrecidas, por eu ter sido tão tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Eu estou perturbado e abatido; ando o dia todo em sofrimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Porque meus lombos ardem muito, e nada há que esteja saudável em minha carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Estou enfraquecido e despedaçado; eu gemo pelo sofrimento do meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'SENHOR, todo o meu sofrimento está diante de ti, e meu gemido não te é oculto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Meu coração dá palpitações, e minha força me deixou; e a luz dos meus olhos já não está comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Meus amigos e companheiros observam de longe minha calamidade; e os meus vizinhos ficam afastados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Os que procuram matar a minha alma me armam laços; e os que procuram o meu mal falam insultos e todo o dia planejam maldades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Mas eu estou como o surdo, não ouço; e como o mudo, que não abre sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'E eu estou como um homem que não ouve, e cuja boca não pode responder com repreensões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Por isso, SENHOR, eu espero em ti; Senhor, meu Deus, tu me ouvirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Porque eu dizia: Não se alegrem de mim!Quando meu pé vacilou, eles se engrandeceram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Porque eu estou prestes a ficar como manco, e minha dor está continuamente perante mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Por isso eu te conto minha maldade; estou aflito por causa do meu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Porém meus inimigos estão vivos, e se fortalecem; e os que me odeiam por maldade se multiplicam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Assim como os que retribuem o bem com o mal, eles se opõem a mim, porque eu sigo o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Não me desampares, SENHOR, meu Deus, não fiques longe de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Apressa-te ao meu socorro, SENHOR, salvação minha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Salmo de Davi, para o regente, conforme “Jedutum”: Eu dizia: Vigiarei os meus caminhos, para eu não pecar com minha língua; vigiarei minha boca com freio, enquanto o perverso ainda estiver em frente a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Eu fiquei calado, nada falei de bom; e minha dor se agravou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Meu coração se esquentou dentro de mim, fogo se acendeu em minha meditação; então eu disse com minha língua:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Conta-me, SENHOR, o meu fim, e a duração dos meus dias, para que eu saiba como eu sou frágil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Eis que a palmos tu ordenaste os meus dias, e o tempo de minha vida é como nada diante de ti; pois todo homem que existe é um nada. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Certamente o homem anda pela aparência, certamente se inquietam em vão; ajuntam bens,e não sabem que os levará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'E agora, SENHOR, o que eu espero? Minha esperança está em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Livra-me de todas as minhas transgressões; não me ponhas como humilhado pelo tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Eu estou calado, não abrirei a minha boca, porque tu fizeste assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Tira teu tormento de sobre mim; estou consumido pelo golpe de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Ao castigares alguém com repreensões pela maldade, logo tu desfaz o que lhe agrada como traça; certamente todo homem é um nada. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Ouve a minha oração, SENHOR; e dá ouvidos ao meu clamor; não te cales de minhas lágrimas, porque eu sou como um peregrino para contigo; estrangeiro, como todos os meus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Não prestes atenção em mim em tua ira, antes que eu vá, e pereça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Salmo de Davi, para o regente: Esperei com esperança no SENHOR, e ele se inclinou a mim, e ouviu o meu clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Ele me tirou de uma cova de tormento, de um lamaceiro de barro; e pôs os meus pés sobre uma rocha; ele firmou meus passos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'E pôs em minha boca uma canção nova, um louvor para nosso Deus: muitos o verão, e temerão, e confiarão no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Bem-aventurado é o homem que põe no SENHOR sua confiança; e não dá atenção aos arrogantes e aos que caminham em direção à mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Tu, SENHOR meu Deus, multiplicaste para conosco tuas maravilhas e teus planos; eles não podem ser contados em ordem diante de ti; se eu tentasse contá-los e falá-los, eles são muito mais do que incontáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Tu não te agradaste de sacrifício e oferta; porém tu me furaste as orelhas; tu não pediste nem oferta de queima nem oferta para expiação de pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Então eu disse: Eis que venho; no rolo do livro está escrito sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Meu Deus, eu desejo fazer a tua vontade; e tua Lei está no meio dos meus sentimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Eu anuncio a justiça na grande congregação; eis que não retenho meus lábios; tu, SENHOR sabes disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Eu não escondo tua justiça no meio de meu coração; eu declaro tua fidelidade e tua salvação; não escondo tua bondade e tua verdade na grande congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Tu, SENHOR, não detenhas para comigo tuas misericórdias; tua bondade e tua fidelidade me guardem continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Porque inúmeros males me cercaram; minhas maldades me prenderam, e eu não pude as ver; elas são muito mais do que os cabelos de minha cabeça, e meu coração me desamparou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Seja agradável para ti, SENHOR, tu me livrares; SENHOR, apressa-te ao meu socorro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Envergonhem-se, e sejam juntamente humilhados os que buscam a minha alma para a destruírem; tornem-se para trás e sejam envergonhados os que querem o meu mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Sejam eles assolados como pagamento de sua humilhação, os que dizem de mim: “Ha-ha!”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Fiquem contentes e se alegrem-se em ti todos aqueles que te buscam; digam continuamente os que amam tua salvação: Engrandecido seja o SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'E eu estou miserável e necessitado; mas o SENHOR cuida de mim; tu és meu socorro e meu libertador; Deus meu, não demores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Salmo de Davi, para o regente: Bem-aventurado aquele que dá atenção ao miserável; o SENHOR o livrará no dia do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'O SENHOR o guardará, e o manterá vivo; ele será bem-aventurado na terra; e tu não o entregarás à vontade de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'O SENHOR o sustentará no leito de enfermidade; na doença dele tu mudas toda a sua cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Eu disse: SENHOR, tem piedade de mim, sara a minha alma, porque eu pequei contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Meus inimigos falam mal de mim, dizendo: Quando ele morrerá? Quando o nome dele perecerá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'E se algum deles vem me ver, fala coisas sem valor, e seu coração junta maldade; ele sai, e fala disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Todos os que me odeiam murmuram juntamente de mim; contra mim eles planejam o mal para mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Uma doença maligna está posta sobre ele; e aquele que está deitado não se levantará mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Até o homem que era meu amigo íntimo, em quem eu confiava, que comia do meu pão; grandemente levantou contra mim seu calcanhar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Porém tu, SENHOR, tem piedade de mim, e levanta-me; e eu lhes darei o pagamento que merecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Por isto eu sei que tu te agradas de mim: porque meu inimigo não se declara vencedor sobre mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'E quanto a mim, tu me sustentas em minha sinceridade; e tu me puseste diante de ti para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Bendito seja o SENHOR, Deus de Israel, para todo o sempre! Amém e Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Salmo de instrução para o regente; dos filhos de Coré: Assim como a corça geme de desejo pelas correntes de águas, assim também minha alma geme de desejo por ti, Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Minha alma tem sede de Deus, do Deus vivente: Quando entrarei, e me apresentarei diante de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Minhas lágrimas têm sido meu alimento dia e noite, porque o dia todo me dizem: Onde está o teu Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Disto eu me lembro, e derramo minha alma em mim com choros, porque eu ia entre a multidão, e com eles entrava na casa de Deus, com voz de alegria e louvor, na festa da multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Minha alma, por que tu estás abatida, e te inquietas em mim? Espera em Deus; pois eu o louvarei pelas suas salvações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Deus meu, minha alma está abatida dentro de mim; por isso eu me lembro de ti desde a terra do Jordão, e dos hermonitas, desde o monte Mizar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Um abismo chama outro abismo, ao ruído de suas cascatas; todos as tuas ondas e vagas têm passado sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Mas de dia o SENHOR mandará sua misericórdia, e de noite a canção dele estará comigo; uma oração ao Deus de minha vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Direi a Deus, minha rocha: Por que tu te esqueces de mim? Por que eu ando em sofrimento pela opressão do inimigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Meus adversários me afrontam com uma ferida mortal em meus ossos, ao me dizerem todo dia: Onde está o teu Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus; porque eu ainda o louvarei; ele é a minha salvação e o meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Faze-me justiça, ó Deus, e defende minha causa contra a nação impiedosa; livra-me do homem enganador e perverso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Pois tu és o Deus de minha força. Por que tu me rejeitas? Por que ando em sofrimento pela opressão do inimigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Envia tua luz e tua verdade, para que elas me guiem, para que me levem ao monte de tua santidade e a tuas habitações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'E eu entre ao altar de Deus, ao Deus da minha maior alegria, e eu te louve com harpa, ó Deus, meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus, porque eu ainda o louvarei; ele é a minha salvação e o meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Instrução para o regente; dos filhos de Coré: Ó Deus, com nossos ouvidos ouvimos, nossos pais nos contaram a obra que tu fizeste nos seus dias, nos dias antigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Para plantá-los, expulsaste as nações com a tua própria mão; para fazê-los crescer, afligiste os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Porque não conquistaram a terra pelas espadas deles, nem o braço deles os salvou; mas sim tua mão direita e o teu braço, e a luz de teu rosto; porque tu os favoreceste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Deus, tu és meu Rei; ordena salvações a Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Por ti venceremos nossos adversários; por teu nome passaremos por cima dos que se levantam contra nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Porque minha confiança não está em meu arco; nem minha espada me salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Pois tu nos salvaste de nossos adversários, e envergonhaste aos que nos odeiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Nós exaltamos a Deus o dia todo; e louvaremos o teu nome para sempre. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Mas agora tu tens nos rejeitado e envergonhado; e tu não tens saído junto com nossos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Tu nos fazes fugir do adversário, e aqueles que nos odeiam saqueiam de nós para si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Tu nos entregas como ovelhas para serem comidas, e nos espalhas entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Tu vendes a teu povo ao preço de nada, e não aumentas o seu valor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Tu nos pões como humilhação por nossos vizinhos; como escárnio e zombaria pelos que estão ao redor de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Tu nos pões como provérbio de escárnio entre as nações; como balançar de cabeça entre os povos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Minha humilhação está o dia todo diante de mim; e a vergonha cobre o meu rosto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Pela voz do adversário e do que insulta; por causa do inimigo e do vingador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Tudo isto veio sobre nós; porém não nos esquecemos de ti, nem traímos o teu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Nosso coração não se voltou para trás, nem nossos passos de desviaram de teu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Tu tens nos afligido num lugar de chacais, e nos cobriste com sobra de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Se tivéssemos esquecido do nome do nosso Deus, e estendido nossas mãos a um outro deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'por acaso Deus não o descobriria? Pois ele conhece os segredos do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Mas por causa de ti somos mortos o dia todo; somos considerados como ovelhas para o matadouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Desperta; por que estás dormindo, Senhor? Acorda, não nos rejeites para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Por que escondes tua face, e te esqueces de nossa humilhação e de nossa opressão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Pois nossa alma está abatida ao pó; nosso ventre está junto à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Levanta-te para nosso socorro; e resgata-nos por tua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Instrução e canção de amor, para o regente; dos filhos de Coré, conforme “os lírios”: Meu coração derrama palavras boas; digo meus versos sobre o Rei; minha língua é pena de um habilidoso escriba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Tu és o mais belo dos filhos dos homens; graça foi derramada em teus lábios, por isso Deus te bendisse para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Põe tua espada ao redor de tua coxa, ó valente; com tua glória e tua honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'E em tua glória prosperamente cavalga, sobre a palavra da verdade e da justa mansidão; e tua mão direita ensinará coisas temíveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Tuas flechas são afiadas no coração dos inimigos do Rei; povos cairão debaixo de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Deus, teu trono é eterno e dura para sempre; o cetro de teu reino é cetro de equidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Tu amas a justiça e odeias a maldade; por isso Deus, o teu Deus te ungiu com azeite de alegria, mais que a teus companheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Todos as tuas roupas cheiram a mirra, aloés e cássia; alegram-te desde os palácios de marfim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Filhas de reis estão entre tuas damas de honra; e a rainha está à tua direita, ornada com o valioso ouro de Ofir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Ouve, filha, e olha, e inclina os teus ouvidos; e esquece-te de teu povo, e da casa de teu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Então o rei desejará tua beleza; inclina-te a ele, pois ele é teu Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'E a filha de Tiro, os ricos dentre o povo, suplicarão teu favor com presentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Gloriosa é a filha do Rei dentro do palácio; de fios de ouro é a sua roupa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Com roupas bordadas a levarão ao Rei; as virgens atrás dela, suas companheiras, serão trazidas a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Serão trazidas com alegria e grande satisfação; entrarão no palácio do Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Em vez de teus pais, serão teus filhos; tu os porás por príncipes sobre toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Farei memória de teu nome em toda geração após geração; por isso os povos te louvarão para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Cântico sobre “Alamote”; para o regente, dos filhos de Coré: Deus é nosso refúgio e força; socorro oportuno nas angústias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Por isso não temeremos, ainda que a terra se mova, e ainda que as montanhas passem ao interior dos mares; Ainda que suas águas rujam e se perturbem, e as montanhas tremam por sua braveza. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, '');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Há um rio cujos ribeiros alegram a cidade de Deus, o santuário das habitações do Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Deus está no meio dela; ela não será abalada; Deus a ajudará ao romper da manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'As nações gritarão, os reinos se abalarão; quando ele levantou a sua voz, a terra se dissolveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'O SENHOR dos exércitos está conosco; o Deus de Jacó é nosso alto refúgio. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Vinde, observai os feitos do SENHOR, que faz assolações na terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Que termina as guerras até o fim da terra; ele quebra o arco e corta a lança; ele queima os carros com fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Ficai quietos, e sabei que eu sou Deus; eu serei exaltado entre as nações; serei exaltado sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'O SENHOR dos exércitos está conosco; o Deus de Jacó é nosso alto refúgio. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Salmo para o regente, dos filhos de Coré: Vós todos os povos, batei palmas; clamai a Deus com voz de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Porque o SENHOR Altíssimo é temível, o grande Rei sobre toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Ele subjugará aos povos debaixo de nós, e as nações debaixo de nossos pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Ele escolhe para nós nossa herança, a glória de Jacó, a quem ele amou. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Deus sobe com gritos de alegria; o SENHOR, com voz de trombeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Cantai louvores a Deus, cantai; cantai louvores ao nosso Rei, cantai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Porque Deus é o Rei de toda a terra; cantai louvores com entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Deus reina sobre as nações; Deus se senta sobre o trono de sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Os chefes dos povos se juntaram ao povo do Deus de Abraão, porque os escudos da terra pertencem a Deus, e ele é muito exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Cântico e salmo, dos filhos de Coré: O SENHOR é grande e muito louvável, na cidade de nosso Deus, no monte de sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Belo de se ver e alegria de toda a terra é o monte de Sião, nas terras do norte; a cidade do grande Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Deus está em seus palácios, e é conhecido como alto refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Porque eis que os reis se reuniram; eles juntamente passaram');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Eles, quando a viram, ficaram maravilhados; assombraram-se, fugiram apressadamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Ali o temor os tomou, e sentiram dores como as de parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Com o vento do oriente tu quebras os navios de Társis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Assim como nós ouvimos, também vimos na cidade do SENHOR dos exércitos, na cidade do nosso Deus; Deus a firmará para sempre. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Deus, nós reconhecemos tua bondade no meio de teu templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Conforme o teu nome, ó Deus, assim é o louvor a ti, até os confins da terra; tua mão direita está cheia de justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Alegre-se o monte de Sião, fiquem contentes as filhas de Judá, por causa de teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Andai ao redor de Sião, e a circundai; contai suas torres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Ponde vosso coração em seus muros de defesa, prestai atenção em seus palácios, para que conteis deles à geração seguinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Porque este Deus é nosso Deus para todo o sempre; ele nos acompanhará até a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Salmo para o regente, dos filhos de Coré: Ouvi isto, vós todos os povos; dai ouvidos, todos os moradores do mundo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'vós, povo, filhos dos homens, tanto os ricos como os pobres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Minha boca falará da sabedoria; e o pensamento do meu coração estará cheio de entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Inclinarei meus ouvidos a uma parábola; ao som da harpa declararei o meu enigma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Por que temeria eu nos dias do mal, quando a maldade dos meus adversários me cercar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Eles confiam em seus bens, e se orgulham da abundância de suas riquezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Mas ninguém pode livrar o seu irmão, nem pagar a Deus o seu resgate,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'porque a redenção da sua alma é caríssima, e sempre será insuficiente');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'para viver eternamente, e jamais ver a cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Pois se vê que os sábios morrem, que o tolo e o bruto igualmente perecem; e deixam suas riquezas a outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Seu pensamento interior é que suas casas serão perpétuas, que suas moradas durarão de geração em geração;dão às terras os seus próprios nomes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Mas o ser humano, ainda que em honra, não dura para sempre; semelhante é aos animais, que perecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Este é o caminho dos tolos e dos seus seguidores, que se agradam de suas palavras. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'São como ovelhas trazidas ao mundo dos mortos; a morte se alimentará deles. Os corretos os dominarão pela manhã; a forma deles se consumirá no mundo dos mortos, a sua habitação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Mas Deus resgatará a minha alma da violência do mundo dos mortos, pois ele me tomará consigo. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Não temas quando um homem enriquece, quando a glória de sua casa se engrandece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Pois ele, quando morrer, nada levará; nem sua glória o seguirá abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Ainda que, em vida, tenha pronunciado a si mesmo a bênção “Louvam-te ao fazeres o bem a ti”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'ele, porém, se juntará à geração de seus pais; nunca mais verão a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'O homem em posição de honra que não tem entendimento é semelhante aos animais, que perecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Salmo de Asafe: Deus, o SENHOR Deus fala e chama a terra, desde onde o sol nasce até onde ele se põe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Desde Sião, a perfeição da beleza, Deus mostra seu imenso brilho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Nosso Deus virá, e não ficará calado; fogo queimará adiante dele, e ao redor dele haverá grande tormenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Ele chamará aos céus do alto, e à terra, para julgar a seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Ajuntai-me meus santos, que confirmam meu pacto por meio de sacrifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'E os céus anunciarão sua justiça, pois o próprio Deus é o juiz. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Ouve, povo meu, e eu falarei; eu darei testemunho contra ti, Israel; eu sou Deus, o teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Eu não te repreenderei por causa de teus sacrifícios, porque tuas ofertas de queima estão continuamente perante mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Não tomarei bezerro de tua casa, nem bodes de teus currais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Porque todo animal das matas é meu, e também os milhares de animais selvagens das montanhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Conheço todas as aves das montanhas, e as feras do campo estão comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Se eu tivesse fome, não te diria, porque meu é o mundo, e tudo o que nele há.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Comeria eu carne de touros, ou beberia sangue de bodes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Oferece a Deus sacrifício de louvor, e paga ao Altíssimo os teus votos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'E clama a mim no dia da angústia; e eu te farei livre, e tu me glorificarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mas Deus diz ao perverso: Para que tu recitas meus estatutos, e pões meu pacto em tua boca?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Pois tu odeias a repreensão, e lança minhas palavras para detrás de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Se vês ao ladrão, tu consentes com ele; e tens tua parte com os adúlteros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Com tua boca pronuncias o mal, e tua língua gera falsidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Tu te sentas e falas contra teu irmão; contra o filho de tua mãe tu dizes ofensas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Tu fazes estas coisas, e eu fico calado; pensavas que eu seria como tu? Eu te condenarei, e mostrarei teus males diante de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Entendei, pois, isto, vós que vos esqueceis de Deus; para que eu não vos faça em pedaços, e não haja quem vos livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Quem oferece sacrifício de louvor me glorificará, e ao que cuida de seu caminho, eu lhe mostrarei a salvação de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Salmo de Davi, para o regente, quando o profeta Natã veio até ele, depois dele ter praticado adultério com Bate-Seba: Tem misericórdia de mim, ó Deus, conforme a tua bondade; desfaz minhas transgressões conforme a abundância de tuas misericórdias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Lava-me bem de minha perversidade, e purifica-me de meu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Porque eu reconheço minhas transgressões, e meu pecado está continuamente diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Contra ti, somente contra ti pequei, e fiz o mal segundo teus olhos; para que estejas justo no que dizeres, e puro no que julgares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Eis que em perversidade fui formado, e em pecado minha mãe me concebeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Eis que tu te agradas da verdade interior, e no oculto tu me fazes conhecer sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Limpa-me do pecado com hissopo, e ficarei limpo; lava-me, e eu serei mais branco que a neve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Faça-me ouvir alegria e contentamento, e meus ossos, que tu quebraste, se alegrarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Esconde tua face de meus pecados, e desfaz todas as minhas perversidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Cria em mim um coração puro, ó Deus; e renova um espírito firme em meu interior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Não me rejeites de tua face, e não tires teu Espírito Santo de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Restaura a alegria de tua salvação, e que tu me sustentes com um espírito de boa vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Então eu ensinarei aos transgressores os teus caminhos, e os pecadores se converterão a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Livra-me das transgressões por derramamento de sangue, ó Deus, Deus de minha salvação; e minha língua louvará alegremente tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Abre, Senhor, os meus lábios, e minha boca anunciará louvor a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Porque tu não te agradas de sacrifícios, pois senão eu te daria; tu não te alegras de ofertas de queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Os sacrifícios a Deus são um espírito quebrado em arrependimento; tu não desprezarás um coração quebrado e triste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Faze bem a Sião conforme tua boa vontade; edifica os muros de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Então tu te agradarás dos sacrifícios de justiça, nas ofertas de queima, e nos sacrifícios queimados por completo; então oferecerão bezerros sobre teu altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Instrução de Davi, para o regente, quando Doegue, o edomita, veio, e contou a Saul, dizendo: Davi veio à casa de Aimeleque: Por que tu, homem poderoso, te orgulhas no mal? A bondade de Deus continua o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Tua língua planeja maldades; é como navalha afiada, que gera falsidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Tu amas mais o mal que o bem, e a mentira mais do que falar justiça. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Tu amas todas as palavras de destruição, ó língua enganadora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Porém Deus te derrubará para sempre; ele te tomará, e te arrancará para fora da tenda; e te eliminará de toda a terra dos viventes. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'E os justos o verão, e temerão; e rirão dele, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Eis aqui o homem que não pôs sua força em Deus, mas preferiu confiar a abundância de suas riquezas, e fortaleceu em sua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Mas eu serei como a oliveira verde na casa de Deus; confio na bondade de Deus para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Eu te louvarei para sempre, por causa do que fizeste; e terei esperança em teu nome, porque tu és bom perante teus santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Instrução de Davi, para o regente, sobre “Maalate”: O tolo diz em seu coração: Não há Deus.Eles se corrompem, e cometem abominável perversidade, ninguém há que faça o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Deus olhou desde os céus para os filhos dos homens, para ver se havia alguém prudente, que buscasse a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Todos se desviaram, juntamente se fizeram detestáveis; ninguém há que faça o bem, nem um sequer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Será que não tem conhecimento os praticantes de maldade, que devoram a meu povo, como se comessem pão? Eles não clamam a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Ali eles terão grande medo, onde não havia medo; porque Deus espalhou os ossos daquele que te cercava; tu os humilhaste, porque Deus os rejeitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ah, que de Sião venha a salvação de Israel! Quando Deus restaurar seu povo de seu infortúnio, Jacó jubilará, Israel se alegrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Instrução de Davi, para o regente, para instrumentos de cordas, quando os zifeus vieram, e disseram a Saul: “Não está Davi escondido entre nós?”: Deus, salva-me por teu nome; e faze-me justiça por teu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Deus, ouve minha oração; inclina teus ouvidos aos dizeres de minha boca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Porque estranhos se levantam contra mim, e homens terríveis procuram matar a minha alma; não põem a Deus diante dos olhos deles. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Eis que Deus é o que me socorre; o Senhor está com aqueles que sustentam a minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Ele retribuirá com o mal aos que me espiam contra mim; tu os elimina por tua verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'De boa vontade eu te oferecerei sacrifícios; louvarei o teu nome, SENHOR, porque é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Porque tu tens me livrado de toda angústia; e meus olhos verão o fim de meus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Instrução de Davi, para o regente, com instrumento de cordas: Deus, inclina os teus ouvidos à minha oração; e não te escondas de minha súplica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Presta atenção em mim, e responde-me; clamo por meu sofrimento, e grito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Por causa da voz do inimigo, e pela opressão do perverso; porque me preparam suas maldades, e com furor eles me odeiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Meu coração sofre dores em meu interior, e terrores de morte caíram sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Temor e tremor vêm sobre mim, e o horror me toma por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Então eu digo: Ah, quem me dera se eu tivesse asas como uma pomba! Eu voaria, e pousaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Eis que eu fugiria para longe, e ficaria no deserto. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Eu me apressaria para escapar do vento violento e da tempestade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Devora-os, Senhor, divide a língua deles; porque tenho visto violência e briga na cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Dia e noite cercam sobre seus muros; perversidade e opressão há dentro dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Coisas destrutivas estão dentro dela; e a falsidade e o engano não sai de suas praças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Porque não é um inimigo o que me insulta, pois se fosse eu o suportaria; nem é alguém que me odeia o que se engrandece contra mim, pois se fosse eu me esconderia dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Mas és tu, homem semelhante a mim; meu guia, e meu conhecido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Que juntos agradavelmente dávamos conselhos um ao outro; na casa de Deus andávamos entre a multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Que a morte os tome de surpresa, e desçam ao mundo dos mortos ainda vivos; porque maldades há na morada deles, e no interior de cada um deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Eu clamarei a Deus, e o SENHOR me salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'À tarde, e pela manhã, e ao meio dia, orarei e clamarei; e ele ouvirá a minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Ele resgatou em paz a minha alma da batalha que havia contra mim; porque muitos vieram para me prejudicar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Deus ouvirá, e os humilhará, ele que governa desde os princípios dos tempos. (Selá)Porque eles não mudam de comportamento, nem temem a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Meu antigo amigo se voltou contra os que tinham paz com ele, e violou seu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Sua boca é agradável como a manteiga, mas seu coração deseja a guerra; suas palavras parecem mais suaves que o azeite, mas são espadas prontas para o ataque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Entrega tuas preocupações ao SENHOR, e ele te sustentará; ele não permitirá que o justo fique caído para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Porém tu, SENHOR, farás com que eles desçam ao poço da perdição; os homens sanguinários e enganadores não viverão a metade de seus dias; e eu confiarei em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Salmo “Mictão” de Davi para o regente, conforme “pombas silenciosas ao longe”, quando os filisteus o prenderam em Gate: Tem misericórdia de mim, ó Deus, porque o homem procura me devorar; todo o dia ele me oprime em lutas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Os inimigos que me espiam querem me devorar todo dia; porque muitos lutam contra mim, ó Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'No dia em que eu tiver medo, eu confiarei em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Por causa de Deus eu louvarei sua palavra; confio em Deus, não temerei; o que a carne pode fazer contra mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Todos os dias eles distorcem minhas palavras; todos os pensamentos deles sobre mim são para o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Eles se reúnem e se escondem; eles espiam os meus passos, como que esperando a morte de minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Por acaso eles escaparão em suas maldades? Derruba com ira aos povos, ó Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Tu contaste as voltas que dei por causa de meu sofrimento; põe minhas lágrimas em teu odre; não estão elas em teu livro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'No dia em que eu clamar, então meus inimigos se voltarão para trás; isto eu sei, que Deus está comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Por causa de Deus eu louvarei sua palavra; por causa do SENHOR eu louvarei sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Em Deus eu confio, não temerei; o que o homem pode me fazer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Tuas promessas, SENHOR, estão sobre mim; oferecerei agradecimentos a ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Porque tu resgataste minha alma da morte, e meus pés não deixaste tropeçar; para eu andar diante de Deus na luz dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Salmo “Mictão” para o regente, conforme “Altachete”; de Davi, quando fugia de diante de Saul, na caverna: Tem misericórdia de mim, ó Deus, tem misericórdia de mim; porque minha alma confia em ti, e eu me refugio sob a sombra de tuas asas, até que os meus problemas passem de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Clamarei ao Deus Altíssimo; a Deus, que cumprirá sua obra em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Ele enviará desde os céus e me livrará, humilhando ao que procura me demorar. (Selá)Deus enviará sua bondade e sua verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Minha alma está no meio dos leões, estou deitado entre brasas ardentes, filhos de homens, cujos dentes são lanças e flechas, e a língua deles são espada afiada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Exalta-te sobre os céus, ó Deus; esteja tua glória sobre toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Prepararam uma rede de armadilha para os meus passos, minha alma estava abatida; cavaram perante mim uma cova, porém eles mesmos caíram nela. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Firme está meu coração, ó Deus; meu coração está firme; eu cantarei, e louvarei com músicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Desperta-te, ó glória minha! Desperta, lira e harpa; despertarei ao amanhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Eu te louvarei entre os povos, Senhor; cantarei louvores a ti entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Pois tua bondade é grande, alcança até os céus; e a tua fidelidade até as nuvens mais altas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Exalta-te sobre os céus, ó Deus; esteja tua glória sobre toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Salmo “Mictão” de Davi, para o regente, conforme “Altachete”: Congregação, por acaso falais verdadeiramente o que é justo? Vós, Filhos dos homens, julgais corretamente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Na verdade vós praticais perversidades em vosso coração; sobre a terra pesais a violência de vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Os perversos se desviam desde o ventre da mãe; afastam-se desde o ventre os mentirosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'O veneno deles é semelhante ao veneno de serpente; são como a cobra surda, que tapa seus ouvidos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Para não ouvirem a voz dos encantadores, do encantador sábio em encantamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Deus, quebra os dentes deles em suas bocas; arranca os queixos dos filhos dos leões, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Que eles escorram como águas, que vão embora; quando ele armar sua flecha, sejam eles cortados em pedaços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Como a lesma, que se desmancha, que assim saiam embora; como o aborto de mulher, assim também nunca vejam o sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Antes que vossas panelas sintam os espinhos, tanto vivos, como aquecidos, ele os arrebatará furiosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'O justo se alegrará ao ver a vingança; e lavará seus pés no sangue do perverso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Então o homem dirá: Certamente há recompensa para o justo; certamente há Deus, que julga na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Salmo “Mictão” de Davi, para o regente, conforme “Altachete”, quando Saul enviou pessoas para vigiarem sua casa e o matarem: Livra-me de meus inimigos, ó Deus meu; protege-me dos que se levantam contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Livra-me dos que praticam perversidade, e salva-me dos homens sanguinários;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Porque eis que eles põem ciladas à minha alma; fortes se juntam contra mim; ainda que eu não tenha cometido transgressão nem pecado, ó SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Eles correm sem eu ter culpa; desperta para me encontrar, e olha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Tu, SENHOR, Deus dos exércitos, Deus de Israel, desperta para julgar a todas estas nações; não tenhas misericórdia de nenhum dos enganadores que praticam perversidade. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Eles voltam ao anoitecer, latem como cães, e rodeiam a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Eis que vomitam com as bocas deles, seus lábios são como espadas; porque dizem: Quem ouve?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Porém tu, SENHOR, rirás deles; zombarás de todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Por causa de sua força, eu te aguardarei; porque Deus é o meu refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'O Deus que tem bondade para comigo me antecederá; Deus me fará ver o fim dos meus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Não os mates, para que meu povo não se esqueça; faze-os fugir de um lado para o outro pelo teu poder, e abate-os; ó Senhor, escudo nosso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Por causa do pecado da boca deles e da palavra de seus lábios; e sejam presos em sua arrogância pelas maldições e pelas mentiras que contam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Destrói -os em tua ira; destrói -os para que nunca mais existam; para que saibam que Deus governa em Jacó até os limites da terra. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Eles voltam ao anoitecer, latem como cães, e rodeiam a cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Andam de um lado para o outro por comida, e rosnam se não estiverem saciados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Mas eu cantarei sobre tua força; e pela manhã com alegria louvarei tua bondade; porque tu tens sido meu alto refúgio e abrigo no dia da minha angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Cantarei louvores a ti, que és minha força; porque Deus é o meu refúgio, ó Deus de bondade para comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Salmo “Mictão” de Davi, de ensinamento, para o regente, conforme “Susanedute”, quando lutou contra os de Arã-Naraim e Arã-Zobá, e Joabe voltou vitorioso, tendo ferido no Vale do Sal a doze mil dos de Edom: Deus, tu nos rejeitaste, e nos quebraste; tu te encheste de ira. Por favor, restaura-nos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Tu fizeste a terra tremer, e a abriste; cura suas rachaduras, porque ela está abalada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Mostraste ao teu povo coisas duras; nos fizeste beber vinho perturbador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Tu deste uma bandeira aos que te temem, para que fujam do arco. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Para que teus amados escapem; salva-nos com tua mão direita, e responda-nos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Deus falou em seu santuário: Eu me alegrarei; repartirei a Siquém e medirei o vale de Sucote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Meu é Gileade, e meu é Manassés; e Efraim é a força de minha cabeça; Judá é meu legislador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moabe é minha bacia de lavar; sobre Edom lançarei minha sandália; gritarei de alegria sobre a Filístia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Quem me levará a uma cidade fortificada? Quem me guiará até Edom?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Não serás tu, ó Deus, que tinha nos rejeitado? Não saías tu, ó Deus, com nossos exércitos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Dá-nos socorro para a angústia; porque a salvação de origem humana é inútil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Com Deus faremos coisas grandiosas; e ele atropelará nossos adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Salmo de Davi, para o regente, com instrumento de cordas: Ouve, ó Deus, o meu clamor; presta atenção à minha oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Desde o limite da terra eu clamo a ti, pelo sofrimento do meu coração; leva-me para uma rocha alta para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Pois tu tens sido o meu refúgio e torre forte perante o inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Eu habitarei em tua tenda para sempre; tomarei refúgio me escondendo sob tuas asas. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Pois tu, ó Deus, ouviste meus votos; tu tens me dado a herança dos que temem o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Acrescentarás dias e mais dias ao Rei; seus anos serão como de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Ele habitará para sempre diante de Deus; prepara que tua bondade e fidelidade o guardem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Assim cantarei ao teu nome para sempre, para eu pagar meus votos dia após dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Salmo de Davi para o regente, conforme “Jedutum”: Certamente minha alma se aquieta por causa de Deus; dele vem minha salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Certamente ele é minha rocha, minha salvação e meu refúgio; não serei muito abalado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Até quando atacareis um homem? Todos vós sereis mortos; sereis como um parede tombada e uma cerca derrubada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Eles somente tomam conselhos sobre como lançá-lo abaixo de sua alta posição; agradam-se de mentiras; falam bem com suas bocas, mas amaldiçoam em seus interiores. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Tu, porém, ó minha alma, aquieta-te em Deus; porque ele é minha esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Certamente ele é minha rocha, minha salvação e meu refúgio; não me abalarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Em Deus está minha salvação e minha glória; em Deus está minha força e meu refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Confiai, povo, nele em todo o tempo; derramai vosso coração diante dele; Deus é nosso refúgio. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Pois os filhos dos seres humanos são nada; os filhos do homem são mentira; pesados juntos são mais leves que o vazio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Não confieis na opressão, nem no roubo; nem sejais inúteis; quando tiverdes bens, não ponhais neles vosso coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Deus falou uma vez; eu ouvi duas vezes: que de Deus vem o poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Também é tua, Senhor, a bondade; pois tu pagarás a cada homem conforme sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Salmo de Davi, quando ele estava no deserto de Judá: Deus, tu és meu Deus. Eu te busco ao amanhecer; minha alma tem sede de ti, minha carne muito te deseja, em terra seca, cansativa, sem águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Para que eu te veja em teu santuário, para ver tua força e tua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Porque tua bondade é melhor que a vida; meus lábios te louvarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Assim te bendirei em minha vida; por teu nome levantarei minhas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Minha alma será saciada, como que de gorduras e muita comida; e minha boca te louvará com lábios alegres,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Quando eu me lembrar de ti em minha cama; nas vigílias da noite meus pensamentos estarão em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Porque tu tens sido meu socorro; e à sombra de tuas asas cantarei de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Minha alma está apegada a ti; tua mão direita me sustenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Porém aqueles que procuram assolar a minha alma irão para as profundezas da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Eles serão derrubados pela força da espada; serão repartidos entre raposas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Mas o Rei se alegrará em Deus; todo o que por ele jurar se alegrará, porque a boca dos mentirosos será tapada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Salmo de Davi, para o regente: Ouve, Deus, minha voz, em minha meditação de súplica; guarda minha vida do terror do inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Esconde-me do grupo dos malignos, e do ajuntamento dos praticantes de maldade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Que afiam sua língua como se fosse espada; e armaram palavras amargas como se fossem flechas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Para atirarem no inocente às escondidas; disparam apressadamente contra ele, e não têm medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Eles são ousados para fazerem coisas más, comentam sobre como esconder armadilhas, e dizem: Quem as verá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Eles buscam por perversidades; procuram tudo o que pode ser procurado, até o interior de cada homem, e as profundezas do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Mas Deus os atingirá com flecha de repente; e logo serão feridos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'E a língua deles fará com que tropecem em si mesmos; todo aquele que olhar para eles se afastará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'E todos os homens terão medo, e anunciarão a obra de Deus, e observarão cuidadosamente o que ele fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'O justo se alegará no SENHOR, e confiará nele; e todos os corretos de coração o glorificarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Salmo e cântico de Davi, para o regente: A ti, Deus, pertence a tranquilidade e o louvor em Sião; e a ti será pago o voto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Tu, que ouves as orações; toda carne virá a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Perversidades têm me dominado, porém tu tiras a culpa de nossas transgressões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Bem-aventurado é aquele a quem tu escolhes, e o fazes aproximar, para que habite em teus cômodos; seremos fartos do bem de tua casa, na santidade de teu templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Tu nos responderá de forma justa por meio de coisas temíveis. O Deus de nossa salvação é a confiança de todos os limites da terra, e dos lugares mais distantes do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Ele é o que firma os montes com sua força, revestido de poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Ele é o que amansa o ruído dos mares, o ruído de suas ondas, e o tumulto dos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Até os que habitam nos lugares mais distantes temem teus sinais; tu fazes alegres o nascer e o pôr do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Tu visitas a terra, e a regas; tu a enriqueces; o rio de Deus está cheio de águas; tu preparas a terra, e lhes dá trigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Enche seus regos de águas,fazendo-as descer em suas margens; com muita chuva a amoleces, e abençoas o que dela brota.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Coroas o ano com tua bondade; e teus caminhos transbordam fartura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Eles são derramados sobre os pastos do deserto; e os morros se revestem de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Os campos se revestem de rebanhos, e os vales são cobertos de trigo; e por isso se alegram e cantam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Cântico e salmo para o regente: Gritai de alegria a Deus toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Cantai a glória do nome dele; reconhecei a glória de seu louvor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Dizei a Deus: Tu és temível em tuas obras; pela grandeza de tua força os teus inimigos se sujeitarão a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Toda a terra te adorará, e cantará a ti; cantarão ao teu nome. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Vinde, e vede os atos de Deus; a obra dele é temível aos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Ele fez o mar ficar seco, passaram o rio a pé; ali nos alegramos nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Ele governa com seu poder para sempre; seus olhos vigiam as nações; não se exaltem os rebeldes. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Vós povos, bendizei a nosso Deus, e fazei ouvir a voz do louvor a ele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Que conserva nossas almas em vida, e não permite que nossos pés se abalem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Porque tu, Deus, tem nos provado; tu nos refinas como se refina a prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Tu nos levaste a uma rede; prendeste-nos em nossas cinturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Fizeste um homem cavalgar sobre nossas cabeças; passamos pelo fogo e pela água, porém tu nos tiraste para um lugar confortável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Entrarei em tua casa com ofertas de queima; pagarei a ti os meus votos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Que meus lábios pronunciaram, e minha boca falou, quando eu estava angustiado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Eu te oferecerei ofertas de queima de animais gordos, com incenso de carneiros; prepararei bois com bodes. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Vinde, ouvi, todos vós que temeis a Deus, e eu contarei o que ele fez à minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Clamei a ele com minha boca, e ele foi exaltado pela minha língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Se eu tivesse dado valor para a maldade em meu coração, o Senhor não teria me ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Mas certamente Deus me ouviu; ele prestou atenção à voz de minha oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Bendito seja Deus, que não ignorou minha oração, nem sua bondade se desviou de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Salmo e cântico, para o regente, com instrumento de cordas: Que Deus tenha misericórdia de nós, e nos abençoe; que ele brilhe seu rosto sobre nós. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Para que o teu caminho seja conhecido na terra, e todos as nações conheçam tua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Louvem os povos a ti, ó Deus, louvem a ti todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Que as nações se alegrem e cantem de alegria, pois tu julgarás aos povos com equidade, e guiarás as nações na terra. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Louvem os povos a ti, ó Deus, louvem a ti todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Que a terra dê seu fruto, e que Deus, nosso Deus, nos abençoe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Deus nos abençoará, e todos os limites da terra o temerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Salmo e canção de Davi, para o regente: Deus se levantará, e seus inimigos serão dispersos, e os que o odeiam fugirão de sua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Assim como a fumaça se espalha, tu os espalharás; assim como a cera que se derrete diante do fogo, assim também os perversos perecerão diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Mas os justos se alegrarão, e saltarão de prazer perante Deus, e se encherão de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Cantai a Deus, cantai louvores ao seu nome; exaltai aquele que anda montado sobre as nuvens, pois EU-SOU é o seu nome; e alegrai -vos diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Ele é o pai dos órfãos, e juiz que defende as viúvas; Deus na habitação de sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Deus que faz os solitários viverem em uma família, e liberta os prisioneiros; mas os rebeldes habitam em terra seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Deus, quando tu saías perante teu povo, enquanto caminhavas pelo deserto (Selá),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'A terra se abalava, e os céus se derramavam perante a presença de Deus; neste Sinai, diante da presença de Deus, o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Tu fizeste a chuva cair abundantemente, e firmaste tu herança, que estava cansada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Nela o teu rebanho habitou; por tua bondade, Deus, sustentaste ao miserável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'O Senhor falou; grande é o exército das que anunciam as boas novas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Reis de exércitos fugiam apressadamente; e aquela que ficava em casa repartia os despojos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Ainda que estivésseis cercados por ambos os lados, estais protegidos como que por asas de pomba, cobertas de prata, e suas penas revestidas de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Quando o Todo-Poderoso espalhou os reis, houve neve em Salmom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'O monte de Deus é como o monte de Basã; é um monte bem alto, como o monte de Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Por que olhais com inveja, ó montes altos? A este monte Deus desejou para ser sua habitação; e o SENHOR habitará nele para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'As carruagens de Deus são várias dezenas de milhares; o Senhor está entre elas, como em Sinai, em seu santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Tu subiste ao alto, levaste cativos, recebeste bens dos homens, até dos rebeldes, para que ali o SENHOR Deus habitasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Bendito seja o Senhor; dia após dia ele nos carrega; Deus é nossa salvação. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Nosso Deus é um Deus de salvação; e com o Senhor DEUS há livramento para a morte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Pois Deus ferirá a cabeça de seus inimigos, o topo da cabeça, onde ficam os cabelos, daquele que anda na prática de suas transgressões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'O Senhor disse: Eu os farei voltar de Basã; eu os farei voltar das profundezas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Para que metas teu pé no sangue dos teus inimigos; e nele também terá uma parte a língua de cada um de teus cães.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Viram teus caminhos, ó Deus; os caminhos de meu Deus, meu Rei, no santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Os cantores vieram adiante, depois os instrumentistas; entre eles as virgens tocadoras de tamborins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Bendizei a Deus nas congregações; bendizei ao SENHOR, desde a fonte de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Ali está o pequeno Benjamim, que domina sobre eles; os chefes de Judá e a congregação deles; os chefes de Zebulom, e os chefes de Nafitali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Teu Deus ordenou tua força; fortalece, ó Deus, o que já operaste por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Ao teu templo, em Jerusalém, os Reis te trarão presentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Repreende a fera das canas, a multidão de touros, juntamente com as bezerras dos povos; aos que humilham a si mesmos em troca de peças e prata; dissipa aos povos que gostam da guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Embaixadores virão do Egito; Cuxe correrá para estender suas mãos a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Reinos da terra, cantai a Deus; cantai louvores ao Senhor. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Ele anda montado por entre os céus desde os tempos antigos; eis que sua voz fala poderosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Reconhecei o poder de Deus; sobre Israel está sua exaltação, e sua força está nas altas nuvens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Deus, tu és temível desde teus santuários; o Deus de Israel é o que dá força e poder ao povo. Bendito seja Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Salmo de Davi, para o regente, conforme “os lírios”: Salva-me, ó Deus, porque as águas têm entrado e encoberto a minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Afundei-me em um profundo lamaçal, onde não se pode ficar em pé; entrei nas profundezas das águas, e a corrente está me levando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Já estou cansado de clamar, minha garganta enrouqueceu; meus olhos desfaleceram, enquanto espero pelo meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Os que me odeiam sem motivo são mais numerosos que os cabelos de minha cabeça; são poderosos os que procuram me arruinar, os que por falsidades se fazem meus inimigos; tive que pagar de volta aquilo que não furtei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Tu, Deus, sabes como sou tolo; e meus pecados não estão escondidos perante ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Não sejam envergonhados por minha causa aqueles que te esperam, ó Senhor DEUS dos exércitos; não sejam humilhados por minha causa os que te buscam, ó Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Porque por causa de ti aguentei ser insultado; a humilhação cobriu o meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Tornei-me estranho aos meus irmãos; e desconhecido aos filhos de minha mãe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Porque o zelo por tua casa me devorou; e os insultos dos que te insultam caíram sobre mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Minha alma chorou e jejuou; porém mais insultos vieram sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Vesti-me de saco, mas fui ridicularizado por eles num ditado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Os que se sentam à porta falam mal de mim; e os bebedores de álcool cantam piadas contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Mas eu oro a ti, SENHOR, no tempo aceitável. Pela grandeza de tua bondade, responde-me, ó Deus, pela fidelidade de tua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Livra-me do lamaçal, e não me deixes afundar; seja eu resgatado dos que me odeiam, e das profundezas das águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Não permitas que as correntes de águas me cubram, e que a profundeza não me devore, nem o poço feche sua boca sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Responde-me, SENHOR; pois boa é tua bondade; olha para mim conforme tua piedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'E não escondas teu rosto de teu servo; porque estou angustiado; ouve-me depressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Vem para perto de minha alma, e a liberta; resgata-me por causa de meus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Tu conheces como me insultam, me envergonham e me humilham; diante de ti estão todos os meus adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Insultos têm quebrado meu coração, e estou fraquíssimo; e esperei compaixão, porém houve nenhuma; também esperei por pessoas que me consolassem, mas não os achei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Deram-me fel como alimento; e em minha sede me deram vinagre para beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Torne-se a mesa diante deles como que um laço; e aquilo que lhes dá segurança lhes seja uma armadilha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Sejam escurecidos os olhos deles, para que não possam ver; e que seus quadris vacilem continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Derrama tua indignação sobre eles; e que sejam tomados pelo ardor de tua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'A habitação deles seja desolada; e que não haja morador nas tendas deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Porque perseguem aquele a quem tu feriste, e contam histórias da dor daqueles a quem tu machucaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Conta como maldade a maldade deles; e não sejam eles agraciados por tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Sejam riscados dos livro da vida; e não estejam eles escritos junto com os justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Mas eu estou miserável e em dores; ó Deus, que tua salvação me proteja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Louvarei o nome de Deus com cântico; e o engrandecerei com agradecimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Isto agradará ao SENHOR mais do que o sacrifício de um boi ou de um bezerro com chifres e unhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Os mansos verão, e se alegrarão; vós que buscais a Deus, vosso coração viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Porque o SENHOR ouve aos necessitados, e não despreza os prisioneiros que lhe pertencem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Louvem a ele os céus, a terra, os mares, e tudo que neles se move;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Porque Deus salvará a Sião, e construirá as cidades de Judá; e habitarão ali, e a terão como posse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'E a semente de seus servos a herdará; e os que amam o nome dele habitarão nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Memorial de Davi, para o regente: Livra-me Deus; apressa-te para me socorrer, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Envergonhem-se, e sejam confundidos os que procuram matar a minha alma; voltem-se para trás, e sejam humilhados os que gostam de me fazer o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Virem-se para trás por causa de sua vergonha os que dizem: “Há, há!”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Alegrem-se e fiquem contentes em ti todos aqueles que te buscam; aqueles que amam tua salvação digam continuamente: Engrandecido seja Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Eu, porém, estou miserável e necessitado; ó Deus, apressa-te a mim; tu és meu socorro e meu libertador; não demores, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Em ti, SENHOR, confio; nunca me deixes ser envergonhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Resgata-me e livra-me por tua justiça; inclina a mim teus ouvidos, e salva-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sê tu minha rocha e minha habitação, para continuamente eu me abrigar nela; tu tens ordenado que eu seja salvo, porque tu és minha rocha forte e minha fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Meu Deus, livra-me da dominação do perverso, das mãos do injusto e cruel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Pois tu és minha esperança, ó Senhor DEUS; tu és minha confiança desde minha juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Tenho me apoiado em ti desde o ventre de minha mãe; das entranhas dela me tiraste; eu louvo continuamente a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Para muitos fui como prodígio, porém tu és meu forte refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Minha boca seja cheia de louvores a ti por tua glória o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Não me rejeites no tempo da velhice; não me desampares quando minha força se acabar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Porque meus inimigos falam contra mim, e os que espiam minha alma tomam conselhos juntos uns com os outros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Dizendo: Deus o desamparou; persegui, e o tomai, pois já não há quem o livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Deus, não fiques longe de mim; Deus meu, apressa-te para me socorrer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Sejam envergonhados e pereçam os adversários de minha alma; cubram-se de humilhação e confusão aqueles que procuram fazer mal a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Porém eu continuamente manterei a esperança, e darei todo o louvor a ti ainda mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Minha boca contará tua justiça, e tua salvação o dia todo, ainda que eu não saiba sua medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Irei adiante pelos poderes do Senhor DEUS; anunciarei tua justiça, que é somente tua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Deus, tu tens me ensinado desde minha juventude; e até agora conto tuas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'E agora, que estou velho e de cabelos grisalhos, não me desampares, Deus; enquanto eu não tiver anunciado a força de teu braço a esta geração, e teu poder a todos que vierem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'E tua justiça, Senhor, alcança as alturas; porque tu tens feito grandes coisas. Quem é como tu, ó Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Tu, que me fizeste ver muitos males e aflições, voltarás a me dar vida; e voltarás a me tirar dos abismos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Tu aumentarás minha honra e voltarás para me consolar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Eu também te louvarei com instrumento de cordas pela tua fidelidade, ó meu Deus; cantarei a ti com harpa, ó Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Meus lábios terão muita alegria, porque cantarei a ti; e também se alegrará a minha alma, que tu tens resgatado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Minha língua também falará de tua justiça o dia todo, pois já estão envergonhados e humilhados aqueles que procuram me fazer mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Para Salomão Deus, dá teus juízos ao rei, e tua justiça ao filho do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Ele julgará a teu povo com justiça, e a teus aflitos com juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Os montes trarão paz ao povo, e os morros trarão justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Ele julgará os pobres do povo, livrará os filhos do necessitado, e quebrará o opressor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Temerão a ti enquanto durarem o sol e a luz, geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Ele descerá como chuva sobre a erva cortada, como as chuvas que regam a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Em seus dias o justo florescerá, e haverá abundância de paz, até que não haja mais a lua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'E ele terá domínio de mar a mar; e desde o rio até os limites da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Os moradores dos desertos se inclinarão perante sua presença, e seus inimigos lamberão o pó da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Os reis de Társis e das ilhas trarão presentes; os reis de Sabá e Seba apresentarão bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'E todos os reis se inclinarão a ele; todas as nações o servirão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Porque ele livrará ao necessitado que clamar, e também ao aflito que não tem quem o ajude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Ele será piedoso para o pobre e necessitado, e salvará as almas dos necessitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Ele livrará suas almas da falsidade e da violência, e o sangue deles lhe será precioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'E ele viverá; e lhe darão ouro de Sabá, e continuamente orarão por ele; o dia todo o bendirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Haverá bastante trigo na terra sobre os cumes dos montes; seu fruto brotará como o Líbano; e desde a cidade florescerão como a erva da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Seu nome permanecerá para sempre; enquanto o sol durar, seu nome continuará; e se bendirão nele; todas as nações o chamarão de bem-aventurado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Bendito seja o SENHOR Deus, o Deus de Israel! Somente ele faz tais maravilhas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'E bendito seja seu glorioso nome eternamente; e que sua glória encha toda a terra! Amem, e amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Aqui terminam as orações de Davi, filho de Jessé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Salmo de Asafe: Sim, certamente Deus é bom para Israel, para os limpos de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Eu porém, quase que meus pés se desviaram; quase nada faltou para meus passos escorregarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Porque eu tinha inveja dos arrogantes, quando via a prosperidade dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Porque não há problemas para eles até sua morte, e o vigor deles continua firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Não são tão oprimidos como o homem comum, nem são afligidos como os outros homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Por isso eles são rodeados de arrogância como um colar; estão cobertos de violência como se fosse um vestido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Seus olhos incham de gordura; são excessivos os desejos do coração deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Eles são escarnecedores e oprimem falando mal e falando arrogantemente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Elevam suas bocas ao céu, e suas línguas andam na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Por isso seu povo volta para cá, e as águas lhes são espremidas por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'E dizem: Como Deus saberia? Será que o Altíssimo tem conhecimento disto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Eis que estes são perversos, sempre estão confortáveis e aumentam seus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Cheguei a pensar: Certamente purifiquei meu coração e lavei minhas mãos na inocência inutilmente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Porque sou afligido o dia todo, e castigado toda manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Se eu tivesse dito isto, eu falaria dessa maneira; eis que teria decepcionado a geração de teus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Quando tentei entender, isto me pareceu trabalhoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Até que entrei nos santuários de Deus, e entendi o fim de tais pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Certamente tu os fazes escorregarem, e os lança em assolações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Como eles foram assolados tão repentinamente! Eles se acabaram, e se consumiram de medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Como o sonho depois de acordar, ó Senhor, quando tu acordares desprezarás a aparência deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Porque meu coração tem se amargurado, e meus rins têm sentido dolorosas picadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Então me comportei como tolo, e nada sabia; tornei-me como um animal para contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Porém agora estarei continuamente contigo; tu tens segurado minha mão direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Tu me guiarás com teu conselho, e depois me receberás em glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'A quem tenho no céu além de ti? E quando estou contigo, nada há na terra que eu deseje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Minha carne e meu coração desfalecem; porém Deus será a rocha do meu coração e minha porção para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Porque eis que os que ficaram longe de ti perecerão; tu destróis todo infiel a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mas quanto a mim, bom me é me aproximar de Deus; ponho minha confiança no Senhor DEUS, para que eu conte todas as tuas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Instrução de Asafe: Deus, por que nos rejeitaste para sempre? Por que tua ira fumega contra as ovelhas do teu pasto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Lembra-te do teu povo, que tu compraste desde a antiguidade; a tribo de tua herança, que resgataste; o monte Sião, em que habitaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Percorre as ruínas duradouras, tudo que o inimigo destruiu no santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Os teus inimigos rugiram no meio de tuas assembleias; puseram por sinais de vitória os símbolos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Eles eram como o que levantam machados contra os troncos das árvores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'E agora, com machados e martelos, quebraram todas as obras entalhadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Puseram fogo no teu santuário; profanaram levando ao chão o lugar onde o teu nome habita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Disseram em seus corações: Nós os destruiremos por completo; serão queimadas todas as assembleias de Deus na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Já não vemos os nossos sinais; já não há mais profeta; e ninguém entre nós sabe até quando será assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Deus, até quando o adversário insultará? O inimigo blasfemará o teu nome para sempre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Por que está afastada a tua mão direita? Tira-a do teu peito!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Deus é o meu Rei desde a antiguidade; ele opera salvação no meio da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Tu dividiste o mar com a tua força; quebraste as cabeças dos monstros nas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Despedaçaste as cabeças do leviatã; e o deste como alimento ao povo do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Tu dividiste a fonte e o ribeiro; tu secaste os rios perenes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'A ti pertence o dia, a noite também é tua; tu preparaste a luz e o sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Tu estabeleceste todos os limites da terra; tu formaste o verão e o inverno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Lembra-te disto: que o inimigo insultou ao SENHOR; e um povo tolo blasfemou o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Não entregues a vida da tua pombinha para os animais selvagens; não te esqueças para sempre da vida dos teus pobres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Olha para o teu pacto, porque os lugares escuros da terra estão cheios de habitações violentas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Não permitas que o oprimido volte humilhado; que o aflito e o necessitado louvem o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Levanta-te, Deus; luta em favor de tua causa; lembra-te do insulto que o tolo faz a ti o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Não te esqueças da voz dos teus adversários; o barulho dos que se levantam contra ti sobe cada vez mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Para o regente, conforme “altachete”; salmo e cântico de Asafe: Louvamos a ti, ó Deus; louvamos, e perto está o teu nome; são anunciadas as tuas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'O que eu recebi, no tempo determinado, julgarei de forma justa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'A terra e todos os seus moradores são dissolvidos; porém eu fortifiquei suas colunas. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Eu disse aos orgulhosos: Não sejais orgulhosos!E aos perversos: Não exalteis o vosso poder!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Não confieis em vosso poder, nem faleis com arrogância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Porque a exaltação não vem do oriente, nem do ocidente, nem do deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Mas sim de Deus, que é o Juiz; ele abate a um, e exalta a outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Porque o SENHOR tem um copo na mão; com vinho espumado, cheio de mistura, e ele o derramará; e os perversos da terra o beberão e sugarão até seus restos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Mas eu o anunciarei para sempre; cantarei louvores ao Deus de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'E cortarei todas as arrogâncias dos perversos; mas os rostos dos justos serão exaltados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Salmo e cântico de Asafe, para o regente, com instrumentos de cordas: Deus é conhecido em Judá; grande é o seu nome em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'E em Salém está seu tabernáculo, e sua morada em Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Ali ele quebrou as flechas do arco; o escudo, a espada, e a guerra. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Tu és mais ilustre e glorioso que montes de presas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Os ousados de coração foram despojados; dormiram seu sono; e dos homens valentes, nenhum encontrou poder em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Por tua repreensão, ó Deus de Jacó, carruagens e cavalos caíram no sono da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Tu, terrível és tu; e quem subsistirá perante ti com tua ira?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Desde os céus tu anunciaste o juízo; a terra tremeu, e se aquietou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Quando Deus se levantou para o julgamento, para salvar a todos os mansos da terra. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Porque a ira humana serve para o teu louvor; com o restante da ira te cingirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Fazei votos, e os pagai ao SENHOR vosso Deus; todos os que estão ao redor dele tragam presentes ao Temível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Ele cortará o espírito dos governantes; ele é temível aos reis da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Salmo de Asafe, para o regente, conforme “Jedutum”: Clamo a Deus com minha voz, minha voz a Deus; e ele inclinará seus ouvidos a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'No dia da minha angústia busquei ao Senhor; minha mão estava continuamente estendida; minha alma não se deixava consolar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Eu ficava me lembrando de Deus, e gemendo; ficava pensativo, e meu espírito desfalecia. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Tu mantiveste abertas as pálpebras dos meus olhos; eu estava perturbado, e não conseguia falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Eu ficava imaginando os dias antigos, e os anos passados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'De noite eu me lembrava de minha canção; meditava em meu coração; e meu espírito ficava procurando entender.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Será que o Senhor rejeitará para sempre? E nunca mais mostrará seu favor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'A sua bondade se acabou para sempre? Ele deu fim à sua promessa de geração em geração?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Deus se esqueceu de ter misericórdia? Ele encerrou suas compaixões por causa de sua ira? (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Então eu disse: Esta é a minha dor: os anos em que a mão do Altíssimo agia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Eu me lembrarei das obras do SENHOR; porque me lembrarei de tuas antigas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Meditarei em todos as tuas obras, e falarei de teus feitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Deus, santo é o teu caminho; quem é deus tão grande como nosso Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Tu és o Deus que faz maravilhas; tu fizeste os povos conhecerem teu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Com teu braço livraste teu povo, os filhos de Jacó e de José. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'As águas te viram, ó Deus; as águas te viram, e tremeram; também os abismos foram abalados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Grandes nuvens derramaram muitas águas; os céus fizeram barulho; e também tuas flechas correram de um lado ao outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'O ruído de teus trovões estava nos ventos; relâmpagos iluminaram ao mundo; a terra se abalou e tremou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Pelo mar foi teu caminho; e tuas veredas por muitas águas; e tuas pegadas não foram conhecidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Guiaste a teu povo como a um rebanho, pela mão de Moisés e de Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Instrução de Asafe: Povo meu, escuta minha doutrina; inclinai vossos ouvidos às palavras de minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Abrirei minha boca em parábolas; falarei mistérios dos tempos antigos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Os quais ouvimos e conhecemos, e nossos pais nos contaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nós não os encobriremos a seus filhos, contaremos à próxima geração sobre os louvores do SENHOR, o seu poder, e suas maravilhas que ele fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Porque ele firmou um testemunho em Jacó, e pôs a Lei em Israel, a qual ele instruiu aos nossos pais, para que eles ensinassem a seus filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Para que a geração seguinte dela soubesse; e os filhos que nascessem contassem a seus filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'E assim pusessem sua esperança em Deus; e não se esquecessem dos feitos de Deus, mas sim, que guardassem os mandamentos dele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'E não fossem como seus pais, que foram uma geração teimosa e rebelde; geração que não firmou seu coração, e cujo espírito não foi fiel a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Os filhos de Efraim, mesmo tendo arcos e flechas, viraram-se para trás no dia da batalha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Não guardaram o pacto de Deus, e recusaram a andar conforme sua Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'E se esqueceram de seus feitos, e de suas maravilhas que ele tinha lhes feito ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Ele fez maravilhas perante seus pais na terra do Egito, no campo de Zoã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Ele dividiu o mar, e os fez passarem por ele; ele fez as águas ficarem paradas como se estivessem amontoadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'E ele os guiou com uma nuvem durante o dia, e por toda a noite com uma luz de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Ele partiu as rochas no deserto, e lhes deu de beber como que de abismos profundos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Porque ele tirou correntes da rocha, e fez as águas descerem como rios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'E ainda prosseguiram em pecar contra ele, irritando ao Altíssimo no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'E tentaram a Deus nos seus corações, pedindo comida para o desejo de suas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'E falaram contra Deus, e disseram: Poderia Deus preparar uma mesa de comida no deserto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Eis que ele feriu a rocha, e águas correram dela e ribeiros fluíram em abundância; será que ele também poderia nos dar pão, ou preparar carne a seu povo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Por isso o SENHOR os ouviu, e se irritou; e fogo se acendeu contra Jacó, e furor também subiu contra Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Porque eles não creram em Deus, nem confiaram na salvação que dele vem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Mesmo assim, ele deu ordens às altas nuvens, e abriu as portas dos céus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'E choveu sobre eles o maná, para comerem; e lhes deu trigo dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Cada homem daquele povo comeu o pão dos anjos; ele lhes mandou comida para se fartarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Ele fez soprar o vento do oriente nos céus, e trouxe o vento do sul com seu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Ele fez chover sobre eles carne como a poeira da terra; e aves de asas como a areia do mar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'E as fez cair no meio de seu acampamento, ao redor de suas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Então comeram, e fartaram-se abundantemente; e satisfez o desejo deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Porem, estando eles ainda não satisfeitos, enquanto a comida ainda estava em suas bocas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'a ira de Deus subiu contra eles; matou os mais robustos deles e abateu os jovens de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Com tudo isto ainda pecaram, e não creram nas maravilhas que ele fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Por isso gastaram seus dias em futilidades, e seus anos em terrores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Quando ele matava alguns dentre eles, então buscavam por ele, e se convertiam, e buscavam a Deus de madrugada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'E se lembravam de que Deus era sua rocha, e que o Deus Altíssimo era o seu libertador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Porém falavam bem dele da boca para fora, e mentiam com suas línguas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Porque o coração deles não era comprometido para com ele, e não foram fiéis ao pacto dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Porém ele, sendo misericordioso, perdoava a maldade deles, e não os destruía; e muitas vezes desviou de mostrar sua ira, e não despertou todo o seu furor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Porque se lembrou de que eles eram carne, e como o vento, que vai, e não volta mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Quantas vezes o provocaram no deserto, e o maltrataram na terra desabitada!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Pois voltavam a tentar a Deus, e perturbavam ao Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Não se lembraram de sua mão, nem do dia em que os livrou do adversário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Como quando ele fez seus sinais no Egito, e seus atos maravilhosos no campo de Zoã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'E transformou seus rios e suas correntes em sangue, para que não bebessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Enviou entre eles variedades de moscas, que os consumiu; e rãs, que os destruíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'E deu suas colheitas ao pulgão, e o trabalho deles ao gafanhoto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Com saraiva destruiu suas vinhas, e suas figueiras-bravas com granizo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'E entregou seu gado à saraiva; e seus animais a brasas ardentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Mandou entre eles o ardor de sua ira: fúria, irritação e angústia, enviando mensageiros do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Ele preparou o caminho de sua ira; não poupou suas almas da morte, e entregou seus animais à peste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'E feriu mortalmente a todo primogênito no Egito; as primícias nas forças nas tendas de Cam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'E levou a seu povo como a ovelhas; e os guiou pelo deserto como a um rebanho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Ele os conduziu em segurança, e não temeram. O mar encobriu seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'E os trouxe até os limites de sua terra santa, até este monte, que sua mão direita adquiriu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'E expulsou as nações de diante deles, e fez com que eles repartissem as linhas de sua herança, e fez as tribos de Israel habitarem em suas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Porém eles tentaram e provocaram ao Deus Altíssimo; e não guardaram os testemunhos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'E voltaram a ser tão infiéis como os seus pais; desviaram-se como um arco enganoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'E provocaram a ira dele com seus altares pagãos, e com suas imagens de escultura moveram-no de ciúmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Deus ouviu isto, e se indignou; e rejeitou gravemente a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Por isso ele abandonou o tabernáculo em Siló, a tenda que ele havia estabelecido como habitação entre as pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'E entregou o símbolo de seu poder em cativeiro, e sua glória na mão do adversário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'E entregou seu povo à espada, e enfureceu-se contra sua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'O fogo consumiu a seus rapazes, e suas virgens não tiveram músicas de casamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Seus sacerdotes caíram à espada, e suas viúvas não lamentaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Então o Senhor despertou como que do sono, como um homem valente que se exalta com o vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'E feriu a seus adversários, para que recuassem, e lhes pôs como humilhação perpétua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Porém ele rejeitou a tenda de José, e não escolheu a tribo de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Mas escolheu a tribo de Judá, o monte de Sião, a quem ele amava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'E edificou seu santuário como alturas; como a terra, a qual ele fundou para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'E ele escolheu a seu servo Davi; e o tomou dos apriscos de ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Ele o tirou de cuidar das ovelhas geradoras de filhotes, para que ele apascentasse ao seu povo Jacó; e à sua herança Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'E ele os apascentou com um coração sincero, e os guiou com as habilidades de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Salmo de Asafe: Ó Deus, as nações invadiram a tua herança; contaminaram ao teu santo Templo; tornaram Jerusalém em amontoados de ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Deram os cadáveres dos teus servos por comida para as aves dos céus; a carne dos teus consagrados aos animais da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Derramaram o sangue deles como água ao redor de Jerusalém, e não havia quem os enterrasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Somos humilhados pelos nossos vizinhos; zombados e escarnecidos pelos que estão ao nosso redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Até quando, SENHOR? Ficarás tu irado para sempre? Teus ciúmes arderão como o fogo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Derrama o teu furor sobre as nações que não te conhecem, sobre os reinos que não clamam pelo teu nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'porque devoraram Jacó, e arruinaram suas habitações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Não nos castigue pelas perversidades do passado; apressa-te, que as tuas misericórdias venham até nós, porque estamos muito fracos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Socorre-nos, ó Deus da nossa salvação, para glorificar o teu nome; livra-nos, e perdoa os nossos pecados por causa do teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Qual é a finalidade de que as nações digam: Onde está o Deus deles?Que a vingança do sangue derramado dos teus servos seja conhecida entre as nações, diante dos nossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Chegue diante de ti o gemido dos prisioneiros; conforme o teu grande poder, salva a vida dos sentenciados à morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'E retribui a nossos vizinhos em seus corpos sete vezes tanto dos insultos que te insultaram, ó Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Assim nós, o teu povo, e as ovelhas de teu pasto, te louvaremos para sempre; de geração em geração cantaremos louvores a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Para o regente, conforme “Susanedute”. Samo de Asafe: Ó Pastor de Israel, inclina teus ouvidos a mim,tu que pastoreias a José como a ovelhas, que habitas entre os querubins, mostra teu brilho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Perante Efraim, Benjamim e Manassés, desperta o teu poder, e vem para nos salvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Restaura-nos, Deus, e faz brilhar o teu rosto; e assim seremos salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Ó SENHOR Deus dos exércitos, até quando ficarás irritado contra a oração de teu povo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Tu os alimentas com pão de lágrimas, e lhes faz beber lágrimas com grande medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Puseste-nos como a briga de nossos vizinhos, e nossos inimigos zombam de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Restaura-nos, ó Deus dos exércitos, e faz brilhar o teu rosto; e assim seremos salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Tu transportaste tua vinha do Egito, tiraste as nações, e a plantaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Preparaste um lugar para ela, e a fizeste estender suas raízes, e ela encheu a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Os montes foram cobertos pela sombra dela, e seus ramos se tornaram como o dos mais fortes cedros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Ela espalhou seus ramos até o mar, e seus brotos até o rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Por que pois quebraste seus muros, de modo que os que passam arrancam seus frutos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'O porco do campo a destruiu; os animais selvagens a devoraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Ó Deus dos exércitos, volta, te pedimos; olha desde os céus, e vê, e visita esta vinha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'E a videira que tua mão direita plantou; o ramo que fortificaste para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Ela está queimada pelo fogo, e cortada; perecem pela repreensão de tua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Seja tua mão sobre o homem de tua mão direita, sobre o filho do homem a quem fortificaste para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Assim não desviaremos de ti; guarda-nos em vida, e chamaremos o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'SENHOR Deus dos exércitos, restaura-nos; faz brilhar o teu rosto, e assim seremos salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Salmo de Asafe, para o regente, conforme “Gitite”: Cantai de alegria a Deus, que é nossa força; mostrai alegria ao Deus de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Levantai uma canção, e dai-nos o tamborim; a agradável harpa com a lira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Tocai trombeta na lua nova; e na lua cheia, no dia de nossa celebração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Porque isto é um estatuto em Israel, e uma ordem do Deus de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Ele o pôs como testemunho em José, quando tinha saído contra a terra do Egito, onde ouvi uma língua que eu não entendia:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Tirei seus ombros de debaixo da carga; suas mãos foram livrados dos cestos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Na angústia clamaste, e livrei-te dela; te respondi no esconderijo dos trovões; provei a ti nas águas de Meribá. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Ouve -me, povo meu, e eu te darei testemunho; ó Israel, se tu me ouvisses!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Não haverá entre ti deus estranho, e não te prostrarás a um deus estrangeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Eu sou o SENHOR teu Deus, que te fiz subir da terra do Egito; abre tua boca por completo, e eu a encherei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Mas meu povo não ouviu minha voz, e Israel não me quis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Por isso eu os entreguei ao desejo de seus próprios corações, e andaram conforme seus próprios conselhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Ah, se meu povo me ouvisse, se Israel andasse em meus caminhos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Em pouco tempo eu derrotaria seus inimigos, e viraria minha mão contra seus adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Os que odeiam ao SENHOR, a ele se submeteriam, e o tempo da punição deles seria eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'E ele sustentaria Israel com a abundância de trigo; e eu te fartaria com o mel da rocha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Salmo de Asafe: Deus está na congregação dos poderosos, e julga no meio dos deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Até quando julgareis injustamente, e favoreceis a aparência dos perversos? (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Fazei justiça ao pobre e ao órfão; defendei o afligido e o pobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Livrai ao pobre e necessitado, resgatai -o das mãos dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Eles nada conhecem, nem entendem; continuamente andam em trevas; abalam-se todos os fundamentos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Eu disse: Sois deuses; e todos vós sois filhos do Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Porém morrereis como homens, e caireis como qualquer um dos líderes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Levanta-te, ó Deus; julga a terra, pois tu és o dono de todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Cântico e Salmo de Asafe: Deus, não fiques em silêncio; não estejas indiferente, nem fiques quieto, ó Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Porque eis que teus inimigos fazem barulho, e aqueles que te odeiam levantam a cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Planejam astutos conselhos contra teu povo, e se reúnem para tramar contra teus preciosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Eles disseram: Vinde, e os destruamos, para que não sejam mais um povo, e nunca mais seja lembrado o nome de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Porque tomaram conselhos com uma só intenção; fizeram aliança contra ti:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'As tendas de Edom, e dos ismaelitas, de Moabe, e dos agarenos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'De Gebal, e de Amom, e de Amaleque; dos filisteus, com os moradores de Tiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'A Assíria também se aliou a eles; eles foram a força dos filhos de Ló. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Faze a eles como a Midiã, como a Sísera, como a Jabim no ribeiro de Quisom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Que pereceram em Endor; vieram a ser esterco da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Faze a eles e a seus nobres como a Orebe, e como Zeebe; e a todos os seus príncipes como a Zebá, e como a Zalmuna,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Que disseram: Tomemos posse para nós dos terrenos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Deus meu, faze-os como a um redemoinho, como a palhas perante o vento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Como o fogo, que queima uma floresta, e como a labareda que incendeia as montanhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Persegue-os assim com tua tempestade, e assombra-os com o teu forte vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Enche os rostos deles de vergonha, para que busquem o teu nome, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Sejam envergonhados e assombrados para sempre, e sejam humilhados, e pereçam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Para que saibam que tu, (e teu nome é EU-SOU), és o Altíssimo sobre toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Para o regente, com “Gitite”. Salmo dos filhos de Coré: Quão agradáveis são tuas moradas, SENHOR dos exércitos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Minha alma está desejosa, ao ponto de desmaiar, pelos pátios do SENHOR; meu coração e minha carne clamam ao Deus vivente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Até o pardal acha casa, e a andorinha ninho para si, onde ponha filhotes perto de teus altares, ó SENHOR dos exércitos, Rei meu e Deus meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Bem-aventurados os que habitam em tua casa; eles louvam a ti continuamente. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Bem-aventurados aqueles cuja força está em ti, em cujos corações estão os caminhos corretos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Eles, ao passarem pelo Vale de Baca, fazem dele uma fonte; e a chuva o cobre de bênçãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Eles vão de força em força; cada um deles comparece diante de Deus em Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'SENHOR Deus dos exércitos, escuta minha oração; inclina os teus ouvidos, ó Deus de Jacó. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Olha o nosso escudo, ó Deus; e observa o rosto do teu ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Porque melhor é um dia nos teus pátios, do que mil fora. Prefiro estar à porta da casa do meu Deus, a morar nas tendas dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Porque o SENHOR Deus é sol e escudo; o SENHOR concederá graça e honra; ele não negará o bem aos que andam em integridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Ó SENHOR dos exércitos, bem-aventurado é o homem que confia em ti!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Salmo para o regente, dos filhos de Coré: Foste favorável, ó SENHOR, à tua terra; restauraste Jacó de seu infortúnio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Perdoaste a perversidade de teu povo; encobriste todos os seus pecados. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Removeste toda a tua indignação; do ardor de tua ira te desviaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Restaura-nos, ó Deus de nossa salvação; e cessa tua ira de sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Acaso estarás irado contra nós para sempre? Estenderás a tua ira de geração em geração?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Não voltará a dar-nos vida, para que o teu povo se alegre em ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Mostra-nos tua bondade, SENHOR, e dá para nós tua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Escutarei o que o Deus, o SENHOR, falar, pois ele falará de paz ao seu povo, e aos seus santos, contanto que não voltem à loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Certamente sua salvação está perto daqueles que o temem, para que a glória habite em nossa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'A bondade e a verdade se encontrarão; a justiça e a paz se beijarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'A verdade brotará da terra, e a justiça olhará desde os céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'E o SENHOR também dará o bem; e a nossa terra dará o seu fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'A justiça irá adiante dele, e ele nos porá no caminho de seus passos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Oração de Davi: Inclina teus ouvidos, SENHOR, e ouve-me, porque estou aflito e necessitado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Guarda minha alma, porque eu sou dedicado a ti; ó Deus, salva o teu servo, que confia em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Tem misericórdia de mim, SENHOR, porque clamo a ti o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Alegra a alma de teu servo; porque a ti, Senhor, levanto a minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Pois tu, Senhor, és bom, perdoador, e grande em bondade para todos os que clamam a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Inclina, SENHOR, teus ouvidos à minha oração; e presta atenção à voz de minhas súplicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'No dia de minha angústia clamarei a ti, pois tu me responderás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Não há semelhante a ti entre os deuses, ó Senhor; e nem obras como as tuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Todas as nações que tu fizeste virão e se prostrarão diante de ti, Senhor; e elas glorificarão o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Pois tu és grande, e fazes maravilhas; somente tu és Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Ensina-me, SENHOR, o teu caminho, e eu andarei em tua verdade; une meu coração com o temor ao teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Louvarei a ti, ó Senhor meu Deus, com todo o meu coração; e glorificarei o teu nome para sempre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Pois grande é a tua bondade para comigo, e tu resgataste minha alma das profundezas do mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Ó Deus, pessoas arrogantes têm se levantado contra mim; e muitos violentos procuram matar a minha alma, e te desprezam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Porém tu, Senhor, és Deus misericordioso e piedoso; tardio para se irar, e abundante em bondade e verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Volta-te para mim, e tem piedade de mim; dá tua força a teu servo, e salva o filho de tua serva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Faze-me um sinal de bondade, para que os que me odeiam vejam, e se envergonhem; porque tu, SENHOR, tens me ajudado e consolado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Salmo e cântico, dos filhos de Coré: Seu fundamento está nos santos montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'O SENHOR ama os portões de Sião mais que todas as habitações de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Gloriosas coisas são faladas de ti, ó cidade de Deus. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Farei menção de Raabe e Babilônia aos que me conhecem; eis que da Filístia, Tiro e Cuxe se dirá: Este é nascido ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'E de Sião se dirá: Este e aquele outro nasceram ali. E o próprio Altíssimo a manterá firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'O SENHOR contará, quando escrever dos povos: Este nasceu ali. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Assim como os cantores e instrumentistas; todas as minhas fontes estão em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Cântico e Salmo dos filhos de Coré, para o regente, conforme “Maalate Leanote”. Instrução feita por Hemã, o Ezraíta: Ó SENHOR Deus de minha salvação, dia e noite clamo diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Que minha oração chegue à tua presença; inclina os teus ouvidos ao meu clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Porque minha alma está cheia de aflições, e minha vida está quase no mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Já estou contado entre os que descem à cova; tornei-me um homem sem forças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Abandonado entre os mortos, como os feridos de morte que jazem na sepultura, aos quais tu já não te lembra mais, e já estão cortados para fora do poder de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Puseste-me na cova mais profunda, nas trevas e nas profundezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'O teu furor pesa sobre mim, e me oprimiste com todas as tuas ondas. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Afastaste de mim os meus conhecidos, fizeste-me abominável para com eles; estou preso, e não posso sair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Meus olhos estão fracos por causa da opressão; clamo a ti, SENHOR, o dia todo; a ti estendo minhas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Farás tu milagres aos mortos? Ou mortos se levantarão, e louvarão a ti? (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Tua bondade será contada na sepultura? Tua fidelidade na perdição?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Serão conhecidas tuas maravilhas nas trevas? E tua justiça na terra do esquecimento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Porém eu, SENHOR, clamo a ti; e minha oração vem ao teu encontro de madrugada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Por que tu, SENHOR, rejeitas minha alma, e escondes tua face de mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Tenho sido afligido e estou perto da morte desde a minha juventude; tenho sofrido teus temores, e estou desesperado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Os ardores de tua ira têm passado por mim; teus terrores me destroem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Rodeiam-me como águas o dia todo; cercam-me juntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Afastaste de mim meu amigo e meu companheiro; meus conhecidos estão em trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Instrução de Etã Ezraíta: Cantarei das bondades do SENHOR para sempre; de geração em geração com minha boca anunciarei tua fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Porque eu disse: Tua bondade durará para sempre; confirmaste tua fidelidade até nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Tu disseste: Eu fiz um pacto com o meu escolhido, jurei a meu servo Davi. Eu lhe disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Confirmarei tua semente para sempre, e farei teu trono continuar de geração em geração. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Que os céus louvem as tuas maravilhas, SENHOR; pois tua fidelidade está na congregação dos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Porque quem no céu pode se comparar ao SENHOR? E quem é semelhante ao SENHOR entre os filhos dos poderosos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Deus é terrível na assembleia dos santos, e mais temível do que todos os que estão ao seu redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Ó SENHOR Deus dos exércitos, quem é poderoso como tu, SENHOR? E tua fidelidade está ao redor de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Tu dominas a arrogância do mar; quando suas ondas se levantam, tu as aquietas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Quebraste a Raabe como que ferida de morte; com teu braço forte espalhaste os teus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Teus são os céus, também tua é a terra; o mundo e sua plenitude, tu os fundaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'O norte e o sul, tu os criaste; Tabor e Hermon têm muita alegria em teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Tu tens um braço poderoso; forte é tua mão, e alta está tua mão direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Justiça e juízo são a base de teu trono; bondade e verdade vão adiante de teu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Bem-aventurado é o povo que entende o grito de alegria; ó SENHOR, eles andarão na luz de tua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Em teu nome se alegrarão o dia todo, e em tua justiça serão exaltados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Porque tu és a glória de sua força, e por tua boa vontade nosso poder é exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Porque ao SENHOR pertence nosso escudo; e o Santo de Israel é nosso Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Então em visão falaste ao teu santo, e disseste: Pus o socorro sobre um valente; exaltei a um escolhido dentre o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Achei a Davi, meu servo; eu o ungi com meu óleo santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Com ele minha mão será firme; e também meu braço o fortalecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'O inimigo não tomará suas riquezas, nem o filho da perversidade o afligirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Porém eu espancarei seus adversários, e ferirei aos que o odeiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'E minha fidelidade e minha bondade serão com ele; e em meu nome seu poder será exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Porei a mão dele no mar, e sua mão direita nos rios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Ele me chamará: Tu és meu Pai, meu Deus, e a rocha da minha salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Eu também o porei como primogênito, mais alto que todos os reis da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Manterei minha bondade para com ele para sempre, e meu pacto com ele será firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Conservarei sua semente para sempre, e o trono dele como os dias dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Se seus filhos deixarem minha Lei, e não andarem em meus juízos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Se profanarem os meus estatutos, e não guardarem os meus mandamentos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Então punirei a transgressão deles com vara, e a perversidade deles com açoite,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Porém nunca tirarei minha bondade dele, nem falharei em minha fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Não quebrarei o meu pacto, e o que saiu dos meus lábios não mudarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Uma vez jurei por minha Santidade, e nunca mentirei a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'A semente dele durará para sempre, e o trono dele será como o sol perante mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Assim como a lua, ele será confirmado para sempre; e a testemunha no céu é fiel. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Porém tu te rebelaste, e o rejeitaste; ficaste irado contra o teu Ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Anulaste o pacto do teu servo; desonraste a coroa dele lançando-a contra a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Derrubaste todos os seus muros; quebraste suas fortificações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Todos os que passam pelo caminho o despojaram; ele foi humilhado por seus vizinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Levantaste a mão direita de seus adversários; alegraste a todos os inimigos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Também deixaste de afiar sua espada; e não o sustentaste na batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Fizeste cessar sua formosura; e derrubaste seu trono à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Encurtaste os dias de sua cidade; cobriste-o de vergonha. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Até quando, SENHOR? Tu te esconderás para sempre? Arderá teu furor como o fogo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Lembra-te de que curta é minha vida; por que criarias em vão todos os filhos dos homens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Que homem vive, que não experimente a morte? Escaparia a alma dele do poder do mundo dos mortos? (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Senhor, onde estão as tuas bondades do passado, que juraste a Davi por tua fidelidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Lembra-te, Senhor, da humilhação de teus servos, que eu trago em meu peito, causada por todos e grandes povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Com humilhação os teus inimigos insultam, SENHOR, com a qual insultam os passos do teu ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Bendito seja o SENHOR para todo o sempre. Amém, e Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Oração de Moisés, homem de Deus: Senhor, tu tens sido nossa habitação, de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Antes que os montes surgissem, e tu produzisses a terra e o mundo, desde à eternidade até a eternidade tu és Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Tu fazes o homem voltar ao pó, e dizes: Retornai-vos, filhos dos homens!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Porque mil anos aos teus olhos são como o dia de ontem, que passou, e como a vigília da noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Tu os levas como correntes de águas; são como o sono; de madrugada são como a erva que brota:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'De madrugada floresce, e brota; à tarde é cortada, e se seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Porque perecemos com tua ira, e nos assombramos com teu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Tu pões nossas perversidades perante ti, nosso pecado oculto perante a luz do teu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Porque todos os nossos dias se vão por causa de tua irritação; acabamos nossos anos como um suspiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Os dias de nossa vida chegam até os setenta anos; e os que são mais fortes, até os oitenta anos; e o melhor deles é canseira e opressão, porque logo é cortado, e saímos voando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Quem conhece a força de tua ira? O teu furor é conforme o temor a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Ensina -nos a contar nossos dias de tal maneira que alcancemos um coração sábio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Retorna, SENHOR! Até quando? Tem compaixão para com teus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Farta-nos de manhã com tua bondade; e nos alegraremos e seremos cheios de alegria por todos os nossos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Alegra-nos conforme os dias em que tu nos afligiste, os anos em que vimos o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Que tua obra apareça aos teus servos, e tua glória sobre seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'E que o agrado do SENHOR nosso Deus seja sobre nós; e confirma as obras de nossas mãos sobre nós; sim, a obra de nossas mãos, confirma!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Aquele que mora no esconderijo do Altíssimo, à sombra do Todo-Poderoso habitará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Direi ao SENHOR: Tu és meu refúgio e minha fortaleza; Deus meu, em quem confio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Porque ele te livrará do laço do caçador e da peste maligna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Com suas penas ele te cobrirá, e debaixo de suas asas estarás protegido; a verdade dele é escudo grande e protetor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Não terás medo do terror da noite, nem da flecha que voa de dia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Nem da peste que anda às escuras, nem da mortandade que assola ao meio-dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Cairão mil ao teu lado, e dez mil à tua direita, mas a ti nada alcançará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Somente verás com teus olhos, e observarás o pagamento dos perversos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Porque tu fizeste como morada ao SENHOR: o meu refúgio, o Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Mal nenhum te sucederá, nem praga alguma chegará à tua tenda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Porque ele ordenou aos anjos quanto a ti, para que guardem todos os teus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Pelas mãos te levarão, para que não tropeces teu pé em alguma pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Tu pisarás sobre o leão e a cobra; passarás esmagando ao filho do leão e à serpente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Por ele ter me amado tanto, eu também o livrarei; em alto retiro eu o porei, porque ele conhece o meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Ele me chamará, e eu o responderei; estarei com ele na angústia; dela eu o livrarei, e o honrarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Eu o satisfarei com uma longa vida, e lhe mostrarei a minha salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Salmo e cântico para o dia do Sábado: Bom é louvar ao SENHOR, e cantar louvores ao teu nome, ó Altíssimo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Para anunciar tua bondade pela manhã, e tua fidelidade durante as noites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Com o instrumento de dez cordas, com a lira, e com música de harpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Porque tu, SENHOR, tens me alegrado com teus feitos; cantarei de alegria pelas obras de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Ó SENHOR, como são grandes tuas obras! Muito profundos são teus pensamentos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'O homem bruto não os conhece, nem o tolo entende isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Quando os perversos crescem como a erva, e florescem todos os praticantes de maldade, assim então serão destruídos para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Mas tu és Altíssimo para sempre, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Porque eis que teus inimigos, SENHOR, porque eis que teus inimigos pereceram; serão dispersos todos os praticantes de maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Porém tu exaltaste o meu poder, como que um chifre de touro selvagem; eu fui ungido com óleo fresco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'E meus olhos verão o fim dos meus inimigos; meus ouvidos ouvirão o fim dos malfeitores que se levantam contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'O justo florescerá como a palma; crescerá como o cedro do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Os justos estão plantados na casa do SENHOR, crescerão nos pátios do nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Até na velhice ainda darão fruto; serão fortes e verdes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Para anunciarem que o SENHOR é correto; ele é minha rocha, e não há perversidade nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'O SENHOR reina. Ele está vestido de majestade; o SENHOR está vestido de poder, com o qual se envolveu. O mundo está firmado, não se abalará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Teu trono está firme desde o passado; tu és desde a eternidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'SENHOR, os rios levantam; os rios levantam seus ruídos; os rios levantam suas ondas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Porém o SENHOR nas alturas é mais forte que os ruídos de muitas águas, mais que as fortes ondas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Muito fiéis são teus testemunhos; a santidade embeleza tua casa, SENHOR, para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Ó Deus das vinganças, SENHOR Deus das vinganças, mostra-te com teu brilho!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Exalta-te, ó Juiz da terra! Retribui com punição aos arrogantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Até quando os perversos, SENHOR, até quando os perversos se alegrarão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Eles falam demais, e dizem palavras soberbas; todos os que praticam a maldade se orgulham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Eles despedaçam ao teu povo, SENHOR, e humilham a tua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Eles matam a viúva e o estrangeiro, e tiram a vida dos órfãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'E dizem: O SENHOR não vê isso, e o Deus de Jacó não está prestando atenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Entendei, ó tolos dentre o povo; e vós que sois loucos, quando sereis sábios?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Por acaso aquele que criou os ouvidos não ouviria? Aquele que formou os olhos não veria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Aquele que disciplina as nações não castigaria? É ele o que ensina o conhecimento ao homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'O SENHOR conhece os pensamentos do homem, que são inúteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Bem-aventurado é o homem a quem tu disciplinas, SENHOR, e em tua Lei o ensinas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Para tu lhe dares descanso dos dias de aflição, até que seja cavada a cova para o perverso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Pois o SENHOR não abandonará o seu povo, nem desamparará a sua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Porque o juízo restaurará a justiça, e todos os corretos de coração o seguirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Quem se levantará em meu favor contra os malfeitores? Quem se porá em meu favor contra os praticantes de perversidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Se o SENHOR não tivesse sido meu socorro, minha alma logo teria vindo a morar no silêncio da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Quando eu dizia: Meu pé está escorregando;Tua bondade, ó SENHOR, me sustentava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Quando minhas preocupações se multiplicavam dentro de mim, teus consolos confortaram a minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Por acaso teria comunhão contigo o trono da maldade, que faz leis opressivas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Muitos se juntam contra a alma do justo, e condenam o sangue inocente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mas o SENHOR é meu alto retiro, e meu Deus a rocha de meu refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'E ele fará voltar sobre eles suas próprias perversidades, e por suas maldades ele os destruirá; o SENHOR nosso Deus os destruirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Vinde, cantemos alegres ao SENHOR; gritemos de alegria à rocha de nossa salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Cheguemos adiante de sua presença com agradecimentos; cantemos salmos a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Porque o Senhor é o grande Deus, e maior Rei do que todos os deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Na mão dele estão as profundezas da terra; e a ele pertencem os altos montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Dele também é o mar, pois ele o fez; e suas mãos formaram a terra seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Vinde, adoremos, e prostremo-nos; ajoelhemo-nos perante o SENHOR, que nos fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Porque ele é o nosso Deus, e nós somos o povo do seu pasto, e as ovelhas de sua mão. Se hoje ouvirdes a voz dele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Não endureçais vosso coração, como em Meribá, como no dia da tentação no deserto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Onde vossos pais me tentaram; eles me provaram, mesmo já tendo visto minha obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Por quarenta anos aguentei com desgosto d esta geração, e disse: Este povo se desvia em seus corações; e eles não conhecem meus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Por isso jurei em minha ira que eles não entrarão no meu lugar de descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Cantai ao SENHOR uma nova canção; cantai ao SENHOR toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Cantai ao SENHOR, bendizei ao seu nome; anunciai todos os dias sua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Contai sua glória por entre as nações, e suas maravilhas por entre todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Porque o SENHOR é grande e muito digno de louvor; ele é mais temível que todos os deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Porque todos os deuses dos povos são ídolos, porém o SENHOR fez os céus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Majestade e glória há diante dele; força e beleza há em seu santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Reconhecei ao SENHOR, ó famílias dos povos; reconhecei que ao SENHOR pertence a glória e a força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Reconhecei ao SENHOR a glória de seu nome; trazei ofertas, e entrai nos pátios dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Adorai ao SENHOR na glória da santidade; temei perante sua presença toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Dizei entre as nações: O SENHOR reina; o mundo está firme, e não se abalará; ele julgará aos povos de forma correta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Alegrem-se os céus, e enchei de alegria a terra; faça barulho o mar e sua plenitude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Saltem contentes o campo e tudo que nele há, e que todas as árvores dos bosque cantem de alegria,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Diante do SENHOR; porque ele vem; porque ele vem para julgar a terra. Ele julgará ao mundo com justiça, e aos povos com sua verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'O SENHOR reina; que a terra se encha de alegria; alegrem-se as muitas ilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Nuvens e escuridão há ao redor dele; justiça e juízo são a base de seu trono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Fogo vai adiante dele, que inflama seus adversários ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Seus relâmpagos iluminam o mundo; a terra os vê, e treme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Os montes se derretem como cera na presença do SENHOR, na presença do Senhor de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Os céus anunciam sua justiça, e todos os povos veem sua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Sejam envergonhados todos os que servem a imagens, e os que se orgulham de ídolos; prostrai-vos diante dele todos os deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sião ouviu, e se alegrou; e as filhas de Judá tiveram muita alegria, por causa de teus juízos, SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Pois tu, SENHOR, és o Altíssimo sobre toda a terra; tu és muito mais elevado que todos os deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vós que amais ao SENHOR: odiai o mal; ele guarda a alma de seus santos, e os resgata da mão dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'A luz é semeada para o justo, e a alegria para os corretos de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Vós justos, alegrai-vos no SENHOR; e agradecei em memória de sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Salmo: Cantai ao SENHOR uma canção nova, porque ele fez maravilhas; sua mão direita e seu santo braço lhe fez ter a salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'O SENHOR fez ser conhecida sua salvação; perante os olhos das nações ele mostrou sua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Ele se lembrou de sua bondade e de sua fidelidade para com a casa de Israel; todos os confins da terra viram a salvação de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Gritai de alegria ao SENHOR, toda a terra; clamai, cantai alegres, e tocai salmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Tocai ao SENHOR com harpa; com harpa, e com a voz da música;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Com trombetas, e som de cornetas, clamai alegremente diante do Rei SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Faça barulho o mar com sua plenitude; o mundo com os que nele habitam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Que os rios batam palmas, que as montanhas juntamente se alegrem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Diante do SENHOR, porque ele vem para julgar a terra; ele julgará ao mundo com justiça, e aos povos de forma correta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'O SENHOR reina, tremam as nações; ele é o que se senta entre os querubins, mova-se a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'O SENHOR é grande em Sião; ele é mais elevado que todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Louvem o teu grande e temível nome, porque ele é santo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Assim como também a fortaleza do Rei, que ama o juízo; tu firmaste as coisas corretas; tu fizeste juízo e justiça em Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Exaltai ao SENHOR nosso Deus, e prostrai-vos perante o suporte dos seus pés, porque ele é santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moisés e Arão estavam entre seus sacerdotes, e Samuel entre os que chamavam o seu nome; eles clamavam ao SENHOR, e ele os respondia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Na coluna da nuvem ele lhes falava; eles guardavam seus testemunhos e os estatutos que ele tinha lhes dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Ó SENHOR nosso Deus, tu os respondia; tu lhes foste Deus perdoador, ainda que vingasse as coisas que eles praticavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Exaltai ao SENHOR nosso Deus, e prostrai-vos perante seu santo monte; pois santo é o SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Salmo de louvor: Gritai de alegria ao SENHOR toda a terra!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Servi ao SENHOR com alegria; vinde com alegre canto perante sua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Sabei que o SENHOR é Deus; foi ele, e não nós, que nos fez seu povo, e ovelhas de seu pasto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Entrai pelas portas dele com agradecimento, por seus pátios com canto de louvor; agradecei a ele, e bendizei o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Porque o SENHOR é bom, sua bondade dura para sempre; e a fidelidade dele continua de geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Salmo de Davi: Cantarei sobre a bondade e o juízo; a ti, SENHOR, tocarei melodia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'No caminho correto eu meditarei; mas quando virás a mim? Em sinceridade de meu coração andarei dentro de minha casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Não porei perante meus olhos obra maligna; odeio as ações dos que desviam, tais coisas não me tomarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'O coração perverso se afastará de mim; não conhecerei ao mau.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Destruirei ao que fala mal de seu próximo as escondidas, e não tolerarei ao que tem olhos cobiçosos e coração arrogante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Meus olhos estarão sobre os fiéis da terra, para que se sentem comigo; aquele que anda no caminho correto, esse me servirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Aquele que usa de engano não habitará em minha casa; aquele que fala mentiras não conseguirá ficar firme perante meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Pelas madrugadas destruirei a todos os perversos da terra, para tirar da cidade do SENHOR todos os que praticam maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Oração do aflito, quando ele se viu desfalecido, e derramou sua súplica diante do SENHOR: Ó SENHOR, ouve minha oração; e que meu clamor chegue a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Não escondas de mim o teu rosto no dia da minha angústia; inclina a mim teu ouvidos; no dia em que eu clamar, apressa-te para me responder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Porque os meus dias têm se desfeito como fumaça; e meus ossos se têm se queimado como n um forno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Meu coração, tal como a erva, está tão ferido e seco, que me esqueci de comer meu pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Por causa da voz do meu gemido, meus ossos têm se grudado à minha carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Estou semelhante a uma ave no deserto, estou como uma coruja num lugar desabitado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Fico alerta e estou como um pardal solitário sobre o telhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Os meus inimigos me insultam o dia todo; os que me odeiam juram maldições contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Porque estou comendo cinza como se fosse pão, e misturo minha bebida com lágrimas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Por causa de tua irritação e tua ira; porque tu me levantaste e me derrubaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Meus dias têm sido como a sombra, que declina; e eu estou secando como a erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Porém tu, SENHOR, permaneces para sempre; e tua lembrança continua geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Tu te levantarás, e terás piedade de Sião; porque chegou o tempo determinado para se apiedar dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Pois os teus servos se agradam de suas pedras, e sentem compaixão do pó de suas ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Então as nações temerão o nome do SENHOR; e todos os reis da terra temerão a tua glória;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Quando o SENHOR edificar a Sião, e aparecer em sua glória;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'E der atenção à oração do desamparado, e não desprezar sua oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Isto será escrito para a geração futura; e o povo que for criado louvará ao SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Porque ele olhará desde o alto de seu santuário; o SENHOR olhará desde os céus para a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Para ouvir o gemido dos prisioneiros; para soltar aos sentenciados à morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Para eles anunciarem o nome do SENHOR em Sião, e seu louvor em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Quando os povos se reunirem, e os reinos, para servirem ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Ele abateu minha força no caminho; abreviou os meus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Eu dizia: Meu Deus, não me leves no meio dos meus dias; teus anos são eternos,geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Desde muito antes fundaste a terra; e os céus são obra de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Eles se destruirão, porém tu permanecerás; e todos eles como vestimentas se envelhecerão; como roupas tu os mudarás, e serão mudados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Porém tu és o mesmo; e teus anos nunca se acabarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Os filhos de teus servos habitarão seguros,e a semente deles será firmada perante ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Salmo de Davi: Louva ao SENHOR, ó minha alma; e que todo o meu interior louve ao seu santo nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Louva ao SENHOR, ó minha alma; e não te esqueças de nenhum dos benefícios dele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Que perdoa todas as tuas perversidades, e te sara de todas as tuas enfermidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Que resgata tua vida da perdição; que te coroa com bondade e misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Que farta tua boca de coisas boas, e tua juventude é renovada como a águia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'O SENHOR faz justiça e juízos a todos os oprimidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Ele fez Moisés conhecer seus caminhos, e os filhos de Israel conhecerem as obras dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Misericordioso e piedoso é o SENHOR, que demora para se irar, e é grande em bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Ele não reclamará perpetuamente, nem manterá sua ira para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Ele não nos trata conforme nossos pecados, nem nos retribui conforme nossas perversidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Porque, assim como os céus estão bem mais elevados que a terra, assim também prevalece a bondade dele sobre aqueles que o temem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Assim como o oriente está longe do ocidente, assim também ele tira para longe de nós nossas transgressões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Assim como um pai se compadece dos filhos, assim também o SENHOR se compadece daqueles que o temem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Porque ele sabe como fomos formados; ele se lembra de que somos pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Os dias do homem são como a erva, como a flor do campo, assim ele floresce.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Mas quando o vento passa por ele, logo perece; e seu lugar deixa de ser conhecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Porém a bondade do SENHOR continua de eternidade em eternidade sobre os que o temem; e a justiça dele está sobre os filhos de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Sobre os que guardam o seu pacto dele, e sobre os que se lembram de dos mandamentos dele, para os praticarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'O SENHOR firmou o seu trono nos céus, e seu reino domina sobre tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Bendizei ao SENHOR, ó anjos dele; vós, fortes valentes, que guardais sua palavra, ao ouvirem a voz de sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Bendizei ao SENHOR todos os seus exércitos; vós que servis a ele, que fazeis o que lhe agrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Bendizei ao SENHOR todas as suas obras, em todos os lugares de seu domínio; louva, minha alma, ao SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Louva, minha alma, ao SENHOR; ó SENHOR meu Deus, tu és grandioso; de majestade e de glória estás vestido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Tu estás coberto de luz, como que uma roupa; estendes os céus como cortinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Ele, que fixou seus cômodos sobre as águas; que faz das nuvens sua carruagem; que se move sobre as asas do vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Que faz de seus anjos ventos, e de seus servos fogo flamejante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Ele fundou a terra sobre suas bases; ela jamais se abalará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Com o abismo, como um vestido, tu a cobriste; sobre os montes estavam as águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Elas fugiram de tua repreensão; pela voz de teu trovão elas se recolheram apressadamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Os montes subiram e os vales desceram ao lugar que tu lhes tinha fundado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Tu lhes puseste um limite, que não ultrapassarão; não voltarão mais a cobrir a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Ele envia fontes aos vales, para que corram por entre os montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Elas dão de beber a todos os animais do campo; os asnos selvagens matam a sede com elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Junto a elas habitam as aves dos céus, que dão sua voz dentre os ramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Ele rega os montes desde seus cômodos; a terra se farta do fruto de tuas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Ele faz brotar a erva para os animais, e as plantas para o trabalho do homem, fazendo da terra produzir o pão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'E o vinho, que alegra o coração do homem, e faz o rosto brilhar o rosto com o azeite; com o pão, que fortalece o coração do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'As árvores do SENHOR são fartamente nutridas,os cedros do Líbano, que ele plantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Onde as aves fazem ninhos, e os pinheiros são as casas para as cegonhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Os altos montes são para as cabras selvagens; as rochas, refúgio para os coelhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Ele fez a lua para marcar os tempos, e o sol sobre seu poente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Ele dá ordens à escuridão, e faz haver noite, quando saem todos os animais do mato.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Os filhos dos leões, rugindo pela presa, e para buscar de Deus sua comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Quando o sol volta a brilhar, logo se recolhem, e vão se deitar em suas tocas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Então o homem sai para seu trabalho e sua obra até o entardecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Como são muitas as suas obras, SENHOR! Tu fizeste todas com sabedoria; a terra está cheia de teus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Este grande e vasto mar, nele há inúmeros seres, animais pequenos e grandes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Por ali andam os navios e o Leviatã que formastes, para que te alegrasses nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Todos eles aguardam por ti, que lhes dês seu alimento a seu tempo devido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'O que tu dás, eles recolhem; tu abres tua mão, e eles se fartam de coisas boas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Quando tu escondes teu rosto, eles ficam perturbados; quando tu tiras o fôlego deles, logo eles morrem, e voltam ao seu pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Tu envias o teu fôlego, e logo são criados; e assim tu renovas a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'A glória do SENHOR será para sempre; alegre-se o SENHOR em suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Quando ele olha para a terra, logo ela treme; quando ele toca nos montes, eles soltam fumaça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Cantarei ao SENHOR em toda a minha vida; tocarei música ao meu Deus enquanto eu existir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Meus pensamentos lhe serão agradáveis; eu me alegrarei no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Os pecadores serão consumidos da terra, e os maus não existirão mais. Bendizei, ó minha alma, ao SENHOR! Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Agradecei ao SENHOR, chamai o seu nome; anunciai suas obras entre os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Cantai a ele, tocai músicas para ele; falai de todas as suas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Tende orgulho de seu santo nome; alegre-se o coração dos que buscam ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Buscai ao SENHOR e à sua força; buscai a presença dele continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Lembrai-vos de suas maravilhas, que ele fez; de seus milagres, e dos juízos de sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Vós, que sois da semente de seu servo Abraão; vós, filhos de Jacó, seus escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Ele é o SENHOR, nosso Deus; seus juízos estão em toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Ele se lembra para sempre de seu pacto, da palavra que ele mandou até mil gerações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'O qual ele firmou com Abraão, e de seu juramento a Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'O qual também confirmou a Jacó como estatuto, a Israel como pacto eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Dizendo: A ti darei a terra de Canaã, a porção de vossa herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Sendo eles poucos em número; eram poucos, e estrangeiros nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'E andaram de nação em nação, de um reino a outro povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Ele não permitiu a ninguém que os oprimisse; e por causa deles repreendeu a reis,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Dizendo: Não toqueis nos meus ungidos, e não façais mal a meus profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'E chamou a fome sobre a terra; ele interrompeu toda fonte de alimento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Enviou um homem adiante deles: José, que foi vendido como escravo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Amarraram seus pés em correntes; ele foi preso com ferros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Até o tempo que sua mensagem chegou, a palavra do SENHOR provou o valor que ele tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'O rei mandou que ele fosse solto; o governante de povos o libertou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Ele o pôs como senhor de sua casa, e por chefe de todos os seus bens,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Para dar ordens a suas autoridades, e instruir a seus anciãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Então Israel entrou no Egito; Jacó peregrinou na terra de Cam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'E fez seu povo crescer muito, e o fez mais poderoso que seus adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'E mudou o coração dos outros,para que odiassem ao seu povo, para que tratassem mal a seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Então enviou seu servo Moisés, e a Arão, a quem tinha escolhido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Que fizeram entre eles os sinais anunciados, e coisas sobrenaturais na terra de Cam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Ele mandou trevas, e fez escurecer; e não foram rebeldes a sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Ele transformou suas águas em sangue, e matou a seus peixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'A terra deles produziu rãs em abundância, até nos quartos de seus reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Ele falou, e vieram vários bichos e piolhos em todos os seus limites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Tornou suas chuvas em saraiva; pôs fogo ardente em sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'E feriu suas vinhas e seus figueirais; e quebrou as árvores de seus territórios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Ele falou, e vieram gafanhotos, e incontáveis pulgões;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'E comeram toda a erva de sua terra; e devoraram o fruto de seus campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Também feriu a todos os primogênitos em sua terra; os primeiros de todas as suas forças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'E os tirou dali com prata e ouro; e dentre suas tribos não houve quem tropeçasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Até o Egito se alegrou com a saída deles, porque seu temor tinha caído sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Ele estendeu uma nuvem como cobertor, e um fogo para iluminar a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Eles pediram, e fez vir codornizes; e os fartou com pão do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Ele abriu uma rocha, e dela saíram águas; e correram como um rio pelos lugares secos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Porque se lembrou de sua santa palavra, e de seu servo Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Então ele tirou dali a seu povo com alegria; e seus eleitos com celebração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'E lhes deu as terras das nações; e do trabalho das nações tomaram posse;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Para que guardassem seus estatutos, e obedecessem a leis dele. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Aleluia! Agradecei ao SENHOR, porque ele é bom, porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Quem falará das proezas do SENHOR? Quem dirá louvores a ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Bem-aventurados são os que guardam o juízo; e aquele que pratica justiça em todo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Lembra-te de mim, SENHOR, conforme tua boa vontade para com teu povo; concede-me tua salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Para eu ver o bem de teus escolhidos; para eu me alegrar com a alegria de teu povo; para eu ter orgulho de tua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Pecamos com nossos pais, fizemos o mal, agimos perversamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Nossos pais no Egito não deram atenção a tuas maravilhas, nem se lembraram da abundância de tuas bondades; mas ao invés disso se rebelaram junto ao mar, perto do mar Vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Apesar disso ele os livrou por causa de seu nome, para que seu poder fosse conhecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'E repreendeu ao mar Vermelho, e este se secou; e os fez caminharem pelas profundezas do mar,como que pelo deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'E os livrou das mãos daquele que os odiava, e os resgatou das mãos do inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'E as águas cobriram seus adversários; não sobrou nem um sequer deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Então creram nas palavras dele, e cantaram louvores a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Porém logo se esqueceram das obras dele, e não esperaram pelo seu conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Mas foram levados pelo mau desejo no deserto, e tentaram a Deus no lugar desabitado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Então ele lhes concedeu o que pediam, porém enviou magreza a suas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'E tiveram inveja de Moisés no acampamento; e de Arão, o santo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'A terra se abriu, e engoliu a Datã; e encobriu ao grupo de Abirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'E o fogo consumiu o seu grupo; a chama queimou os perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Fizeram um bezerro em Horebe; e se inclinaram perante uma imagem de fundição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'E mudaram sua glória na figura de um boi, que come erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Esqueceram-se de Deus, o salvador deles, que tinha feito coisas grandiosas no Egito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Maravilhas na terra de Cam, coisas temíveis no mar Vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Por isso ele disse que teria os destruído, se Moisés, seu escolhido, não tivesse se posto na fenda diante dele, para desviar sua ira, para não os destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Eles também desprezaram a terra desejável, e não creram na palavra dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'E ao invés disso murmuraram em suas tendas, e não deram ouvidos à voz do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Por isso ele levantou sua mão contra eles, jurando que os derrubaria no deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'E que derrubaria sua semente entre as nações; e os dispersaria pelas terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Eles também passaram a adorar Baal-Peor, e a comer sacrifícios dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'E o provocaram à ira com as obras deles; e por isso surgiu a praga entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Então se levantou Fineias, e interveio, e cessou aquela praga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'E isto lhe foi reconhecido como justiça, de geração em geração, para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Também o irritaram muito junto às águas de Meribá; e houve mal a Moisés por causa deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Porque provocaram o seu espírito, de modo que ele falou imprudentemente com seus lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Eles não destruíram os povos que o SENHOR tinha lhes mandado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Mas ao invés disso, se misturaram com as nações, e aprenderam as obras delas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'E serviram a seus ídolos; e vieram a lhes ser por laço de armadilha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Além disso, sacrificaram seus filhos e suas filhas a demônios,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'E derramaram sangue inocente, o sangue de seus filhos e de suas filhas, os quais eles sacrificaram aos ídolos de Canaã; e a terra foi profanada com este sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'E contaminaram-se com suas obras; e se prostituíram com suas ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Por isso a ira do SENHOR se acendeu contra seu povo; e ele odiou sua propriedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'E os entregou nas mãos das nações estrangeiras, e aqueles que os odiavam passaram a dominá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'E seus inimigos os oprimiram, e foram humilhados sob as mãos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Muitas vezes ele os livrou; mas eles voltavam a irritá-lo com seus pensamentos, e foram abatidos pela sua perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Apesar disso, ele observou a angústia deles, e ouviu quando eles clamaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'E ele se lembrou de seu pacto em favor deles, e sentiu pena conforme suas muitas bondades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'E fez com que todos os que os mantinham em cativeiro tivessem misericórdia deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Salva-nos, SENHOR nosso Deus, e ajunta-nos dentre as nações, para darmos graças ao teu santo nome, e termos orgulho em louvar a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Bendito seja o SENHOR, Deus de Israel, desde sempre e para sempre! E todo o povo diga Amém! Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Agradecei ao SENHOR, porque ele é bom; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Digam isso os resgatados pelo SENHOR, os quais ele resgatou das mão do adversário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'E os que ele ajuntou de todas as terras, do oriente e do ocidente, do norte e do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Os que andaram sem rumo no deserto, por caminhos solitários; os que não acharam cidade para morarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Famintos e sedentos, suas almas neles desfaleciam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Mas eles clamaram ao SENHOR em suas angústias, e ele os livrou de suas aflições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'E os levou ao caminho correto, para irem a uma cidade de moradia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Agradeçam ao SENHOR por sua bondade, e suas maravilhas perante os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Porque ele fartou a alma sedenta, e encheu de bem a alma faminta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Os que estavam sentados em trevas e sombra de morte, presos com aflição e ferro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Porque se rebelaram contra os mandamentos de Deus, e rejeitaram o conselho do Altíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Por isso ele abateu seus corações com trabalhos cansativos; eles tropeçaram, e não houve quem os socorresse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Porém eles clamaram ao SENHOR em suas angústias, e ele os livrou de suas aflições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Ele os tirou das trevas e da sombra da morte, e quebrou suas correntes de prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Agradeçam ao SENHOR pela sua bondade, e suas maravilhas perante os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Porque ele quebrou as portas de bronze, e despedaçou os ferrolhos de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Os tolos foram afligidos por causa de seu caminho de transgressões e por suas perversidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'A alma deles perdeu o interesse por todo tipo de comida, e chegaram até às portas da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Porém eles clamaram ao SENHOR em suas angústias, e ele os livrou de suas aflições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Ele enviou sua palavra, e os sarou; e ele os livrou de suas covas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Agradeçam ao SENHOR por sua bondade, e suas maravilhas perante os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'E sacrifiquem sacrifícios de gratidão; e anunciai as obras dele com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Os que descem ao mar em navios, trabalhando em muitas águas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Esses veem as obras do SENHOR, e suas maravilhas nas profundezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Porque quando ele fala, ele faz levantar tormentas de vento, que levanta suas ondas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Elas sobem aos céus, e descem aos abismos; a alma deles se derrete de angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Eles cambaleiam e vacilam como bêbados, e toda a sabedoria deles se acaba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Então eles clamaram ao SENHOR em suas angústias, e ele os tirou de suas aflições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Ele fez cessar as tormentas, e as ondas se calaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Então se alegraram, porque houve calmaria; e ele os levou ao porto que queriam chegar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Agradeçam ao SENHOR por sua bondade, e suas maravilhas perante os filhos dos homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'E exaltem a ele na assembleia do povo, e o glorifiquem na reunião dos anciãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Ele torna os rios em deserto, e as saídas de águas em terra seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'A terra frutífera em salgada, pela maldade dos que nela habitam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Ele torna o deserto em lagoa, e a terra seca em nascentes de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'E faz aos famintos habitarem ali; e eles edificam uma cidade para morarem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'E semeiam campos, e plantam vinhas, que produzem fruto valioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'E ele os abençoa, e se multiplicam muito, e o gado dele não diminui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Mas quando eles se diminuem e se abatem, por causa da opressão, mal e aflição;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Ele derrama desprezo sobre os governantes, e os faz andar sem rumo pelos desertos, sem terem caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Mas ao necessitado, ele levanta da opressão a um alto retiro, e faz famílias como a rebanhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Os corretos, ao verem, ficam alegres, e todo perverso se calará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Quem é sábio, que preste atenção a estas coisas, e reflita nas bondades do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Cântico e Salmo de Davi: Preparado está meu coração, ó Deus; cantarei e tocarei música com minha glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Desperta-te, lira e harpa; eu despertarei ao amanhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Louvarei a ti entre os povos, SENHOR, e tocarei música a ti entre as nações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Porque tua bondade é maior que os céus, e tua fidelidade mais alta que as nuvens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Exalta-te sobre os céus, ó Deus; e tua glória sobre toda a terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Para que teus amados sejam libertados; salva -nos com tua mão direita, e responde-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Deus falou em seu santuário: Eu me alegrarei; repartirei a Siquém, e medirei ao vale de Sucote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Meu é Gileade, meu é Manassés; e Efraim é a fortaleza de minha cabeça; Judá é meu legislador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moabe é minha bacia de lavar; sobre Edom lançarei meu sapato; sobre a Filístia eu triunfarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Quem me levará a uma cidade fortificada? Quem me guiará até Edom?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Por acaso não serás tu, ó Deus? Tu que tinha nos rejeitado, e não saías mais com nossos exércitos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Dá-nos ajuda para livrarmos da angústia, porque o socorro humano é inútil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Em Deus faremos proezas; e ele pisoteará nossos adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Salmo de Davi, para o regente: Ó Deus a quem eu louvo, não fiques calado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Porque a boca do perverso, e a boca enganadora já se abriram contra mim; falaram de mim com língua falsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'E me cercaram com palavras de ódio; e lutaram contra mim sem motivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Fizeram-se contra mim por causa de meu amor; porém eu me mantenho em oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Retribuíram o bem com o mal, e o meu amor com ódio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Põe algum perverso contra ele, e que haja um acusador à sua direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Quando for julgado, que saia condenado; e que a oração dele seja considerada como pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Sejam os dias dele poucos, e que outro tome sua atividade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Sejam seus filhos órfãos, e sua mulher seja viúva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'E que seus filhos andem sem rumo, e mendiguem; e busquem para si longe de suas ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Que o credor tome tudo o que ele tem, e estranhos saqueiem seu trabalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Haja ninguém que tenha piedade dele, e haja ninguém que se compadeça de seus órfãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Sejam seus descendentes cortados de vez; e que o nome deles seja apagado da geração seguinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Que a perversidade de seus pais seja lembrada pelo SENHOR, e que o pecado de sua mãe não seja apagado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Porém que tais coisas estejam sempre perante o SENHOR, e corte-se a lembrança deles da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Porque ele não se lembrou de fazer o bem; ao invés disso, perseguiu ao homem humilde e necessitado, e ao de coração quebrado, para o matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Já que ele amou a maldição, então que ela lhe sobrevenha; e já que ele não quis a bênção, que esta se afaste dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'E ele seja revestido de maldição, como se lhe fosse sua roupa, como água dentro do seu corpo, e como óleo em seus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Que ela seja como uma roupa com que ele se cubra, e como cinto com que ele sempre põe ao seu redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Isto seja o pagamento do SENHOR para os meus adversários, e para os que falam mal contra minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Porém tu, Senhor DEUS, me trata bem por causa do teu nome; por ser boa a tua misericórdia, livra-me;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Porque estou aflito e necessitado; e meu coração está ferido dentro de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Eu vou como a sombra, que declina; estou sendo sacudido como um gafanhoto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Meus joelhos estão fracos de tanto jejuar; minha carne está magra, sem gordura alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'E eu por eles sou humilhado; quando me veem, sacodem suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Socorre-me, SENHOR Deus meu; salva-me conforme a tua bondade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Para que saibam que esta é a tua mão; e que assim tu a fizeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Maldigam eles, mas bendize tu; levantem-se eles, mas sejam envergonhados; e o teu servo se alegre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Que meus adversários se vistam de vergonha, e cubram-se com sua própria humilhação, como se fosse uma capa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Agradecerei grandemente ao SENHOR com minha boca, e no meio de muitos eu o louvarei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Porque ele se põe à direita do necessitado, para o livrar daqueles que atacam a sua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Salmo de Davi: O SENHOR disse a meu Senhor: Senta-te à minha direita, até que eu ponha teus inimigos por escabelo de teus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'O SENHOR enviará o cetro de tua força desde Sião, dizendo: Domina tu no meio de teus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Teu povo será voluntário no dia do teu poder; com santas honras, desde o ventre do amanhecer, tu terás o orvalho de tua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'O SENHOR jurou, e não se arrependerá: Tu és Sacerdote eterno, segundo a ordem de Melquisedeque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'O Senhor está à tua direita; ele ferirá aos reis no dia de sua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Julgará entre as nações; ele as encherá de corpos mortos; e ferirá a cabeça de uma grande terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Ele beberá do ribeiro no caminho, então levantará a cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Aleluia! Louvarei ao SENHOR com todo o coração, no conselho e na congregação dos corretos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Grandes são as obras do SENHOR; procuradas por todos os que nelas se agradam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Glória e majestade são o seu agir, e sua justiça permanece para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Ele fez memoráveis as suas maravilhas; piedoso é misericordioso é o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Ele deu alimento aos que o temem; ele se lembrará para sempre de seu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Ele anunciou o poder se suas obras a seu povo, dando-lhes a herança de nações estrangeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'As obras de suas mãos são verdade e juízo, e todos os seus mandamentos são fiéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Eles ficarão firmes para sempre, e são feitos em verdade e justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Ele enviou resgate a seu povo, ordenou seu pacto para sempre; santo e temível é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'O temor ao SENHOR é o princípio da sabedoria; inteligentes são todos o que isto praticam. O louvor a ele dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Aleluia! Bem-aventurado é o homem que teme ao SENHOR, e que tem muito prazer em seus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Sua descendência será poderosa na terra; a geração dos corretos será bendita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Em sua casa haverá bens e riquezas, e sua justiça permanece para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'A luz brilha nas trevas para os corretos, para quem é piedoso, misericordioso e justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'O homem bom é misericordioso, e empresta; ele administra suas coisas com prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Certamente ele nunca se abalará; o justo será lembrado para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Ele não temerá o mau rumor; o seu coração está firme, confiante no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Seu firme coração não temerá, até que ele veja o fim de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Ele distribui, e dá aos necessitados; sua justiça permanece para sempre; seu poder será exaltado em glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'O perverso verá, e ficará incomodado; rangerá seus dentes, e se consumirá. O desejo dos perversos perecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Aleluia! Louvai, vós servos do SENHOR, louvai o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Seja o nome do SENHOR bendito, desde agora para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Desde o nascer do sol até o poente, seja louvado o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'O SENHOR está elevado acima de todas as nações; e sua glória acima dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Quem é como o SENHOR nosso Deus? Ele que habita nas alturas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Que se abaixa para ver o que há nos céus e na terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Que do levanta o pobre do pó da terra, e levanta o necessitado da sujeira;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Para fazê-lo sentar com os príncipes, com os príncipes de seu povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Que faz a estéril habitar em família, como alegre mãe de filhos. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Quando Israel saiu do Egito, quando a casa de Jacó saiu de um povo estrangeiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Judá se tornou seu santuário, e Israel os seus domínios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'O mar viu, e fugiu; e o Jordão recuou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Os montes saltaram como carneiros, os morros como cordeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'O que houve, ó mar, que fugiste? Ó Jordão, que recuaste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Ó montes, que saltastes como carneiros? Ó morros, como cordeiros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Trema tu, ó terra, pela presença do Senhor, pela presença do Deus de Jacó,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Que tornou a rocha em lago de águas; ao pedregulho em fonte de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Não a nós, SENHOR; não a nós, mas a teu nome dá glória; por tua bondade, por tua fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Porque as nações dirão: Onde está o Deus deles?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Porém nosso Deus está nos céus, ele faz tudo o que lhe agrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Os ídolos deles são prata e ouro, obras de mãos humanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Têm boca, mas não falam; têm olhos, mas não veem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Têm ouvidos, mas não ouvem; tem nariz, mas não cheiram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Têm mãos, mas não apalpam; têm pés, mas não andam; nem falam com suas gargantas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Tornem-se como eles os que os fazem, e todos os que neles confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Ó Israel, confia no SENHOR; ele é sua ajuda e seu escudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Ó casa de Arão, confiai no SENHOR; ele é sua ajuda e seu escudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Vós que temeis ao SENHOR, confiai no SENHOR; ele é sua ajuda e seu escudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'O SENHOR tem se lembrado de nós; ele há de abençoar; ele abençoará a casa de Israel; ele abençoará a casa de Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Ele abençoará aos que temem ao SENHOR; tanto os pequenos como os grandes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'O SENHOR vos aumentará, vós e vossos filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Benditos sois vós que pertenceis ao SENHOR, que fez os céus e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Quanto aos céus, os céus são do SENHOR; mas a terra ele deu aos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Os mortos não louvam ao SENHOR, nem os que descem ao silêncio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Porém nós bendiremos ao SENHOR, desde agora e para sempre. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Amo o SENHOR, porque ele escuta minha voz e minhas súplicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Porque ele tem inclinado a mim seus ouvidos; por isso eu clamarei a ele em todos os meus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Cordas da morte me cercaram, e angústias do mundo dos mortos me encontraram; achei opressão e aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Mas clamei ao nome do SENHOR, dizendo: Ah SENHOR, livra minha alma!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'O SENHOR é piedoso e justo; e nosso Deus é misericordioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'O SENHOR protege os simples; eu estava com graves problemas, mas ele me livrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Minha alma, volta ao teu descanso, pois o SENHOR tem te tratado bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Porque tu, SENHOR,livraste minha alma da morte, meus olhos das lágrimas, e meu pé do tropeço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Andarei diante do SENHOR na terra dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Eu cri, por isso falei; estive muito aflito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Eu dizia em minha pressa: Todo homem é mentiroso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'O que pagarei ao SENHOR por todos os benefícios dele para mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Tomarei o copo da salvação, e chamarei o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Certamente pagarei meus votos ao SENHOR, na presença de todo o seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Preciosa é aos olhos do SENHOR a morte de seus santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ah SENHOR, verdadeiramente eu sou teu servo; sou teu servo, filho de tua serva; tu me soltaste das correntes que me prendiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Sacrificarei a ti sacrifício de agradecimento, e chamarei o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Certamente pagarei meus votos ao SENHOR, na presença de todo o seu povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Nos pátios da casa do SENHOR, em meio de ti, ó Jerusalém. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Louvai ao SENHOR, todas as nações; celebrai a ele, todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Porque sua bondade prevaleceu sobre nós, e a fidelidade do SENHOR dura para sempre. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Agradecei ao SENHOR, porque ele é bom; pois sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Diga agora Israel, que sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Diga agora casa de Arão, que sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Digam agora os que temem ao SENHOR, que sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Na angústia clamei ao SENHOR; e o SENHOR me respondeu, e me pôs num lugar amplo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'O SENHOR está comigo, não temerei; o que poderá me fazer o homem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'O SENHOR está comigo entre os que ajudam; por isso verei o fim daqueles que me odeiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Melhor é buscar refúgio no SENHOR do que confiar no homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Melhor é buscar refúgio no SENHOR do que confiar em príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Todas as nações me cercaram; mas foi no nome do SENHOR que eu as despedacei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Cercaram-me, cercaram-me mesmo; mas foi no nome do SENHOR que eu as despedacei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Cercaram-me como abelhas, mas se apagaram como fogo de espinhos; porque foi no nome do SENHOR que eu as despedacei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Com força me empurraste para que eu caísse; mas o SENHOR me ajudou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'O SENHOR é minha força e minha canção, porque ele tem sido minha salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Nas tendas dos justos há voz de alegria e salvação; a mão direita do SENHOR faz proezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'A mão direita do SENHOR se levanta; a mão direita do SENHOR faz proezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Eu não morrerei, mas viverei; e contarei as obras do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'É verdade que o SENHOR me castigou, porém ele não me entregou à morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Abri para mim as portas da justiça; entrarei por elas e louvarei ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Esta é a porta do SENHOR, pela qual os justos entrarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Eu te louvarei porque tu me respondeste e me salvaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'A pedra que os construtores rejeitaram se tornou cabeça de esquina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Pelo SENHOR isto foi feito, e é maravilhoso aos nossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Este é o dia em que o SENHOR agiu; alegremos e enchamos de alegria nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ah, SENHOR, salva-nos! Ah, SENHOR, faze -nos prosperar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Bendito aquele que vem no nome do SENHOR; nós vos bendizemos desde a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'O SENHOR é o verdadeiro Deus, que nos deu luz; atai os sacrifícios da festa, para levá-los aos chifres do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tu és meu Deus, por isso eu te louvarei. Eu te exaltarei, meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Agradecei ao SENHOR, porque ele é bom; pois sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Álefe:Bem-aventurados são os puros em seus caminhos, os que andam na lei do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Bem-aventurados são os que guardam os testemunhos dele, e o buscam com todo o coração;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'E não praticam perversidade, mas andam nos caminhos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tu mandaste que teus mandamentos fossem cuidadosamente obedecidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Ah! Como gostaria que meus caminhos fossem dirigidos a guardar teus estatutos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Então não me envergonharia, quando eu observasse todos os teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Louvarei a ti com um coração correto, enquanto aprendo os juízos de tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Eu guardarei teus estatutos; não me abandones por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Bete:Com que um rapaz purificará o seu caminho? Sendo obediente conforme a tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Eu te busco como todo o meu coração; não me deixes desviar de teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Guardei a tua palavra em meu coração, para eu não pecar contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Bendito és tu, SENHOR; ensina-me teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Com meus lábios contei todos os juízos de minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Eu me alegro mais com o caminho de teus estatutos, do que com todas as riquezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Meditarei em teus mandamentos, e darei atenção a teus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Terei prazer em teus estatutos; não me esquecerei de tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Guímel:Trata bem o teu servo, para que eu viva, e obedeça tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Abre meus olhos, para que eu veja as maravilhas de tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Eu sou peregrino na terra, não escondas de mim os teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Minha alma está despedaçada de tanto desejar os teus juízos em todo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Tu repreendes aos malditos arrogantes, que se desviam de teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Tira-me de minha humilhação e desprezo, pois eu guardei teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Até mesmo os príncipes se sentaram, e falaram contra mim; porém o teu servo estava meditando em teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Pois teus testemunhos são meus prazeres e meus conselheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Dálete:Minha alma está grudada ao pó; vivifica-me conforme tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Eu te contei os meus caminhos, e tu me respondeste; ensina-me conforme teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Faze-me entender o caminho de teus preceitos, para eu falar de tuas maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Minha alma se derrama de tristeza; levanta-me conforme tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Desvia de mim o caminho de falsidade; e sê piedoso dando-me tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Eu escolhi o caminho da fidelidade; e pus diante de mim os teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Estou apegado a teus testemunhos; ó SENHOR, não me envergonhes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Correrei pelo caminho de teus mandamentos, porque tu alargaste o meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Hê:Ensina-me, SENHOR, o caminho de teus estatutos, e eu o guardarei até o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Dá-me entendimento, e eu guardarei a tua lei, e a obedecerei de todo o meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Faze-me andar na trilha de teus mandamentos, porque nela tenho prazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Inclina meu coração a teus testemunhos, e não à ganância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Desvia meus olhos para que não olhem para coisas inúteis; vivifica-me pelo teu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Confirma tua promessa a teu servo, que tem temor a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Desvia de mim a humilhação que eu tenho medo, pois teus juízos são bons.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Eis que amo os teus mandamentos; vivifica-me por tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Vau:E venham sobre mim tuas bondades, SENHOR; e também a tua salvação, segundo tua promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Para que eu tenha resposta ao que me insulta; pois eu confio em tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'E nunca tires de minha boca a palavra da verdade, pois eu espero em teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Assim obedecerei a tua lei continuamente, para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'E andarei livremente por longas distâncias, pois busquei teus preceitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Também falarei de teus testemunhos perante reis, e não me envergonharei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'E terei prazer em teus mandamentos, que eu amo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'E levantarei as minhas mãos a teus mandamentos, que eu amo; e meditarei em teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Záin:Lembra-te da palavra dada a teu servo, à qual mantenho esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Isto é meu consolo na minha aflição, porque tua promessa me vivifica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Os arrogantes têm zombado de mim demasiadamente; porém não me desviei de tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Eu me lembrei de teus juízos muito antigos, SENHOR; e assim me consolei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Eu me enchi de ira por causa dos perversos, que abandonam tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Teus estatutos foram meus cânticos no lugar de minhas peregrinações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'De noite tenho me lembrado de teu nome, SENHOR; e tenho guardado tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Isto eu tenho feito, porque guardo teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Hete:O SENHOR é minha porção; eu disse que guardaria tuas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Busquei a tua face com todo o meu coração; tem piedade de mim segundo tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Eu dei atenção a meus caminhos, e dirigi meus pés a teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Eu me apressei, e não demorei a guardar os teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Bandos de perversos me roubaram; porém não me esqueci de tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'No meio da noite eu me levanto para te louvar, por causa dos juízos de tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Sou companheiro de todos os que te temem, e dos que guardam os teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'A terra está cheia de tua bondade, SENHOR; ensina-me os teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tete:Tu fizeste bem a teu servo, SENHOR, conforme tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Ensina-me bom senso e conhecimento, pois tenho crido em teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Antes de ter sido afligido, eu andava errado; mas agora guardo tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Tu és bom, e fazes o bem; ensina-me os teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Os arrogantes forjaram mentiras contra mim; mas eu com todo o meu coração guardo os teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'O coração deles se incha como gordura; mas eu tenho prazer em tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Foi bom pra mim ter sido afligido, para assim eu aprender os teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Melhor para mim é a lei de tua boca, do que milhares de peças de ouro ou prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Iode:Tuas mãos me fizeram e me formaram; faze-me ter entendimento, para que eu aprenda teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Os que te temem olham para mim e se alegram, porque eu mantive esperança em tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Eu sei, SENHOR, que teus juízos são justos; e que tu me afligiste por tua fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Seja agora tua bondade para me consolar, segundo a promessa que fizeste a teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Venham tuas misericórdias sobre mim, para que eu viva; pois tua lei é o meu prazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Sejam envergonhados os arrogantes, porque eles me prejudicaram com mentiras; porém eu medito em teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Virem-se a mim os que te temem e conhecem os teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Seja meu coração correto em teus estatutos, para eu não ser envergonhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Cafe:Minha alma desfalece por tua salvação; em tua palavra mantenho esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Meus olhos desfaleceram por tua promessa, enquanto eu dizia: Quando tu me consolarás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Porque fiquei como um odre na fumaça, porém não me esqueci teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Quantos serão os dias de teu servo? Quando farás julgamento aos meus perseguidores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Os arrogantes me cavaram covas, aqueles que não são conforme a tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Todos os teus mandamentos são verdade; com mentiras me perseguem; ajuda-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Estou quase que destruído por completo sobre a terra; porém eu não deixei teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Vivifica-me conforme tua bondade, então guardarei o testemunho de tua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Lâmede:Para sempre, SENHOR, tua palavra permanece nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Tua fidelidade dura de geração em geração; tu firmaste a terra, e assim ela permanece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Elas continuam por tuas ordens até hoje, porque todos são teus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Se a tua lei não fosse meu prazer, eu já teria perecido em minha aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Nunca esquecerei de teus mandamentos, porque tu me vivificaste por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Eu sou teu, salva-me, porque busquei teus preceitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Os perversos me esperaram, para me destruírem; porém eu dou atenção a teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'A toda perfeição eu vi fim; mas teu mandamento é extremamente grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Mem:Ah, como eu amo a tua lei! O dia todo eu medito nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Ela me faz mais sábio do que meus inimigos por meio de teus mandamentos, porque ela está sempre comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Sou mais inteligente que todos os meus instrutores, porque medito em teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Sou mais prudente que os anciãos, porque guardei teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Afastei meus pés de todo mau caminho, para guardar tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Não me desviei de teus juízos, porque tu me ensinaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Como são doces tuas palavras ao meu paladar! Mais que o mel em minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Obtenho conhecimento por meio de teus preceitos; por isso odeio todo caminho de mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Nun:Tua palavra é lâmpada para meus pés e luz para meu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Eu jurei, e assim cumprirei, de guardar os juízos de tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Eu estou muito aflito, SENHOR; vivifica-me conforme a tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Agrada-te das ofertas voluntárias de minha boca, SENHOR; e ensina-me teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Continuamente arrisco minha alma, porém não me esqueço de tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Os perversos me armaram um laço de armadilha, mas não me desviei de teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Tomei teus testemunhos por herança para sempre, pois eles são a alegria de meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Inclinei meu coração para praticar os teus testemunhos para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Sâmeque:Odeio os inconstantes, mas amo a tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tu és meu refúgio e meu escudo; eu espero em tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Afastai-vos de mim, malfeitores, para que eu guarde os mandamentos de meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Sustenta-me conforme a tua promessa, para que eu viva; e não me faças ser humilhado em minha esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Segura-me, e estarei protegido; então continuamente pensarei em teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Tu atropelas a todos que se desviam de teus estatutos; pois o engano deles é mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Tu tiras a todos os perversos da terra como se fossem lixo; por isso eu amo teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Meu corpo se arrepia de medo de ti; e temo os teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Áin:Eu fiz juízo e justiça; não me abandones com os meus opressores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Sê tu a garantia do bem de teu servo; não me deixes ser oprimido pelos arrogantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Meus olhos desfaleceram de esperar por tua salvação, e pela palavra de tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Age para com teu servo segundo tua bondade, e ensina-me teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Eu sou teu servo. Dá-me entendimento; então conhecerei teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'É tempo do SENHOR agir, porque estão violando tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Por isso eu amo teus mandamentos mais que o ouro, o mais fino ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Por isso considero corretos todos os teus mandamentos quanto a tudo, e odeio todo caminho de falsidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Pê:Maravilhosos são teus testemunhos, por isso minha alma os guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'A entrada de tuas palavras dá luz, dando entendimento aos simples.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Abri minha boca, e respirei; porque desejei teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Olha-me, e tem piedade de mim; conforme teu costume para com os que amam o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Firma meus passos em tua palavra, e que nenhuma perversidade me domine.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Resgata-me da opressão dos homens; então guardarei teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Brilha teu rosto sobre teu servo, e ensina-me teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Ribeiros d\'água descem de meus olhos, porque eles não guardam tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Tsadê:Tu és justo, SENHOR; e corretos são teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Tu ensinaste teus testemunhos justos e muito fiéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Meu zelo me consumiu, porque meus adversários se esqueceram de tuas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Refinada é a tua palavra, e teu servo a ama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Eu sou pequeno e desprezado; porém não me esqueço de teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Tua justiça é justa para sempre, e tua lei é verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Aperto e angústia me encontraram; ainda assim teus mandamentos são meus prazeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'A justiça de teus testemunhos dura para sempre; dá-me entendimento, e então viverei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Cofe:Clamei com todo o meu coração; responde-me, SENHOR; guardarei teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Clamei a ti; salva-me, e então guardarei os teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Eu me antecedi ao amanhecer, e gritei; e mantive esperança em tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Meus olhos antecederam as vigílias da noite, para meditar em tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Ouve minha voz, segundo tua bondade, SENHOR; vivifica-me conforme teu juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Aproximam-se de mim os que praticam maldade; eles estão longe de tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Porém tu, SENHOR, estás perto de mim; e todos os teus mandamentos são verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Desde antigamente eu soube de teus testemunhos, que tu os fundaste para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Rexe:Olha a minha aflição, e livra-me dela; pois não me esqueci de tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Defende minha causa, e resgata-me; vivifica-me conforme tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'A salvação está longe dos perversos, porque eles não buscam teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Muitas são tuas misericórdias, SENHOR; vivifica-me conforme teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Muitos são meus perseguidores e meus adversários; porém eu não me desvio de teus testemunhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Eu vi aos enganadores e os detestei, porque eles não guardam tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Vê, SENHOR, que eu amo teus mandamentos; vivifica-me conforme a tua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'O princípio de tua palavra é fiel, e o juízo de tua justiça dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Xin:Príncipes me perseguiram sem causa, mas meu coração temeu a tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Eu me alegro em tua palavra, tal como alguém que encontra um grande tesouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Odeio e abomino a falsidade; mas amo a tua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Louvo a ti sete vezes ao dia, por causa dos juízos de tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Muita paz têm aqueles que amam a tua lei; e para eles não há tropeço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Espero por tua salvação, SENHOR; e pratico teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Minha alma guarda teus testemunhos, e eu os amo muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Eu guardo teus preceitos e teus testemunhos, porque todos os meus caminhos estão diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Tau:Chegue meu clamor perante teu rosto, SENHOR; dá-me entendimento conforme tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Venha minha súplica diante de ti; livra-me conforme tua promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Meus lábios falarão muitos louvores, pois tu me ensinas teus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Minha língua falará de tua palavra, porque todos os teus mandamentos são justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Que tua mão me socorra, porque escolhi seguir teus preceitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Desejo tua salvação, SENHOR; e tua lei é o meu prazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Que minha alma viva e louve a ti; e que teus juízos me socorram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Tenho andado sem rumo, como uma ovelha perdida; busca a teu servo, pois eu não me esqueci de teus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Cântico dos degraus: Em minha angústia clamei ao SENHOR, e ele me respondeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Ó SENHOR, livra minha alma dos lábios mentirosos, da língua enganadora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'O que ele te dará, e o que ele fará contigo, ó língua enganadora?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Flechas afiadas de um guerreiro, com brasas de zimbro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Ai de mim, que peregrino em Meseque, e habito nas tendas de Quedar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Minha alma morou tempo demais com os que odeiam a paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Eu sou da paz; mas quando falo, eles entram em guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Cântico dos degraus: Levanto meus olhos aos montes. De onde virá meu socorro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Meu socorro vem do SENHOR, que fez os céus e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Ele não deixará o teu pé se abalar, nem cochilará o teu guardião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Eis que não cochilará nem dormirá o Guardião de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'O SENHOR é o teu guardião; o SENHOR é a sombra à tua direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'O sol não te ferirá durante o dia, nem a lua durante a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'O SENHOR te guardará de todo mal; ele guardará a tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'O SENHOR guardará tua saída e tua entrada, desde agora e para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Cântico dos degraus, de Davi: Alegro-me com os que me dizem: Vamos à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Nossos pés estão adentro de tuas portas, ó Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalém está edificada como uma cidade bem unida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Para onde as tribos sobem, as tribos do SENHOR, como testemunho de Israel, para agradecerem ao nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Porque ali estão as cadeiras do julgamento; as cadeiras da casa de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Orai pela paz de Jerusalém; prosperem os que te amam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Paz haja em teus muros, e prosperidade em tuas fortalezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Por meus irmãos e amigos, assim falarei: Paz haja em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Pela Casa do SENHOR nosso Deus, buscarei o bem para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Cântico dos degraus: Levanto meus olhos a ti, que moras nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Eis que, assim como os olhos dos servos olham para a mão de seus senhores, e os olhos da serva para a mão de sua senhora, assim também nossos olhos olharão para o SENHOR nosso Deus, até que ele tenha piedade de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Tem piedade de nós, SENHOR! Tem piedade de nós; pois temos sido humilhados em excesso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Nossa alma está cheia da zombaria dos insolentes, e da humilhação dos arrogantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Cântico dos degraus, de Davi: Diga, Israel: O que seria de nós se o SENHOR não estivesse conosco?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Se o SENHOR não estivesse conosco, quando os homens se levantaram contra nós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Eles teriam nos devorado vivos, quando o furor deles se acendeu contra nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'As águas teriam nos coberto, e a corrente de águas teria passado por sobre nossas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Águas violentas teriam passado por sobre nossas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Bendito seja o SENHOR, que não nos entregou como presa aos dentes deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Nossa alma escapou como um pássaro da armadilha dos caçadores; a cadeia se quebrou, e nós escapamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Nosso socorro está no nome do SENHOR, que fez o céu e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Os que confiam no SENHOR são como o monte de Sião, que não se abala, e permanece para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Assim como montanhas estão ao redor de Jerusalém, assim também o SENHOR está ao redor de seu povo, desde agora para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Porque o cetro da maldade não repousará sobre a sorte dos justos, para que os justos não estendam suas mãos à perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'SENHOR, trata bem aos bons, e aos corretos em seus corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Mas aos que se dirigem a seus caminhos tortuosos, o SENHOR os mandará embora junto com os que praticam perversidade. Paz seja sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Cântico dos degraus: Quando o SENHOR restaurou Sião de seu infortúnio, estivemos como os que sonham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Então nossa boca se encheu de riso, e nossa língua de alegria; então diziam entre as nações: O SENHOR fez grandes coisas para estes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Grandes coisas o SENHOR fez para nós; por isso estamos alegres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Restaura-nos, ó SENHOR, como as correntes de águas no sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Os que semeiam em lágrimas colherão com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Aquele que sai chorando com semente para semear voltará com alegria, trazendo sua colheita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Cântico dos degraus, de Salomão: Se o SENHOR não estiver edificando a casa, em vão trabalham nela seus construtores; se o SENHOR não estiver guardando a cidade, em vão o guarda vigia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Inutilmente levantais de madrugada e descansais tarde, para comerdes o pão de dores; porque assim ele dá sono a quem ele ama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Eis que os filhos são um presente do SENHOR; o fruto do ventre é uma recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Como flechas na mão do guerreiro, assim são os filhos da juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Bem-aventurado é o homem que enche deles seu porta-flechas; eles não serão envergonhados, quando falarem com os inimigos à porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Cântico dos degraus: Bem-aventurado todo aquele que teme ao SENHOR, e anda em seus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Porque comerás do trabalho de tuas mãos; tu serás bem-aventurado, e bem lhe sucederá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Tua mulher será como a videira frutífera, ao lado de tua casa; e teus filhos como plantas de oliveira ao redor de tua mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Eis que assim é bendito o homem que teme ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'O SENHOR te abençoará desde Sião, e tu verás o bem de Jerusalém todos os dias de tua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'E verás os filhos de teus filhos, e a paz sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Cântico dos degraus: Diga Israel: Desde minha juventude muitas vezes me afligiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Desde minha juventude, muitas vezes me afligiram, porém não prevaleceram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Lavradores lavraram sobre minhas costas, fizeram compridos os seus sulcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'O SENHOR é justo; ele cortou as cordas dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Sejam envergonhados, e voltem para trás todos os que odeiam a Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Sejam como a erva dos telhados, que se seca antes que cresça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Com que o ceifeiro não enche sua mão, nem o braço daquele que amarra os molhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Nem também os que passam, dizem: A bênção do SENHOR seja sobre vós; nós vos bendizemos no nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Cântico dos degraus: Das profundezas clamo a ti, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Ouve, Senhor, a minha voz; sejam teus ouvidos atentos à voz de minhas súplicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Se tu, SENHOR, considerares todas as perversidades, quem resistirá, Senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Mas contigo está o perdão, para que tu sejas temido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Mantenho esperança no SENHOR, a minha alma espera; e persisto em sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Minha alma espera ansiosamente pelo Senhor, mais que os guardas esperam pela manhã, mais que os vigilantes pelo alvorecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Espere, Israel, pelo SENHOR; porque com o SENHOR há bondade, e com ele muito resgate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'E ele resgatará Israel de todas as suas perversidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Cântico dos degraus, de Davi: SENHOR, meu coração não se exaltou, nem meus olhos se levantaram; nem andei em grandezas, nem em coisas maravilhosas para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Ao invés disso, eu me sosseguei e calei minha alma, tal como uma criança com sua mãe; como um bebê está minha alma comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Ó Israel, espere no SENHOR, desde agora para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Cântico dos degraus: Lembra-te, SENHOR, de Davi, e de todas as aflições dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Ele, que jurou ao SENHOR, e fez um voto ao Poderoso de Jacó,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'dizendo: Não entrarei na tenda de minha casa, nem subirei no leito de minha cama;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Não darei sono aos meus olhos, nem cochilo às minhas pálpebras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Enquanto eu não achar um lugar para o SENHOR, moradas para o Poderoso de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Eis que ouvimos dela em Efrata, e a achamos nos campos de Jaar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Entraremos em suas moradas, e nos prostraremos perante o escabelo de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Levanta-te, SENHOR, a teu repouso; tu e a arca de teu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Que teus sacerdotes se vistam de justiça, e teus santos gritem de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Por causa de Davi teu servo, não rejeites o rosto de teu ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'O SENHOR jurou a Davi com fidelidade; dela não se desviará. Ele disse: Do fruto do teu ventre porei sobre o teu trono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Se teus filhos guardarem meu pacto e meus testemunhos que eu lhes ensinar, também seus filhos se sentarão sobre teu trono para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Porque o SENHOR escolheu a Sião, desejou-a para sua habitação,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Dizendo: Este é o meu repouso para sempre; aqui habitarei, pois assim desejei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Abençoarei seu sustento abundantemente, e fartarei seus necessitados de pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'E a seus sacerdotes vestirei de salvação; e seus santos gritarão de alegria abundantemente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Ali farei brotar o poder de Davi; e preparei uma lâmpada para o meu ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'A seus inimigos vestirei de vergonha; mas sobre ele florescerá sua coroa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Cântico dos degraus, de Davi: Vede como é bom e agradável que irmãos convivam em união!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'É como o óleo precioso sobre a cabeça, que desce pela barba, a barba de Arão; que desce pelas bordas de suas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'É como o orvalho de Hermom, que desce sobre os montes de Sião; porque ali o SENHOR ordenou a bênção e a vida para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Cântico dos degraus: Bendizei, pois, ao SENHOR, todos vós servos do SENHOR, que prestais serviço à casa do SENHOR durante as noites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Levantai vossas mãos ao Santuário, e bendizei ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Que o SENHOR, o criador do céu e da terra, te abençoe desde Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Aleluia! Louvai o nome do SENHOR; louvai -o vós, servos do SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Que prestais serviço na Casa do SENHOR, nos pátios da Casa do nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Louvai ao SENHOR, porque o SENHOR é bom; cantai louvores ao seu nome, porque é agradável;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Porque o SENHOR escolheu para si a Jacó, a Israel como propriedade sua;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Porque eu sei que o SENHOR é grande, e nosso Senhor está acima de todos os deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'O SENHOR faz tudo o que quer, nos céus, na terra, nos mares, e em todos os abismos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Ele faz as nuvens subirem desde os confins da terra, faz os relâmpagos com a chuva; ele produz os ventos de seus tesouros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Ele feriu os primogênitos do Egito, desde os homens até os animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Ele enviou sinais e prodígios no meio de ti, Egito; contra Faraó, e contra todos os seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Ele feriu muitas nações, e matou reis poderosos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Seom, rei dos amorreus, e Ogue, rei de Basã; e todos os reinos de Canaã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'E deu a terra deles como herança; como herança a Israel, seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Ó SENHOR, teu nome dura para sempre; e tua memória, SENHOR, de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Porque o SENHOR julgará a seu povo; e terá compaixão de seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Os ídolos das nações são prata e ouro; são obra de mãos humanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Têm boca, mas não falam; têm olhos, mas não veem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Têm ouvidos, mas não ouvem; não têm respiração em sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Tornem-se como eles os que os fazem, e todos os que confiam neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Casa de Israel, bendizei ao SENHOR! Casa de Arão, bendizei ao SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Casa de Levi, bendizei ao SENHOR! Vós que temeis ao SENHOR, bendizei ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Bendito seja o SENHOR desde Sião, ele que habita em Jerusalém. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Agradecei ao SENHOR, porque ele é bom, porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Agradecei ao Deus dos deuses, porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Agradecei ao SENHOR dos senhores; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Ao que faz grandes maravilhas sozinho por si mesmo; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Ao que fez os céus com entendimento; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Ao que estendeu a terra sobre as águas; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Ao que fez as grandes fontes de luz; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Ao sol, para governar o dia; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'À lua e as estrelas, para governarem a noite; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Ao que feriu aos egípcios em seus primogênitos; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'E tirou Israel do meio deles; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Com mão forte, e com braço estendido; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Ao que separou o mar Vermelho em duas partes; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'E fez Israel passar por meio dele; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'E derrubou a Faraó com seu exército no mar Vermelho; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Ao que guiou seu povo pelo deserto; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Ao que feriu grandes reis; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'E matou reis poderosos; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Seom; rei amorreu; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'E Ogue, rei de Basã; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'E deu a terra deles como herança; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Como herança a seu servo Israel; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'O que em nossa humilhação se lembrou de nós; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'E nos tirou livres de nossos adversários; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'O que dá alimento a todo ser vivo feito de carne; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Agradecei ao Deus dos céus; porque sua bondade dura para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Junto aos rios da Babilônia nos sentamos e choramos, enquanto nos lembramos de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Sobre os salgueiros que há no meio dela penduramos nossas harpas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Porque ali os que tinham nos capturado nos pediam letras de canções, e os que nos destruíram, que os alegrássemos, dizendo: Cantai para nós algumas das canções de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Como cantaríamos canções do SENHOR em terra estrangeira?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Se eu me esquecer de ti, ó Jerusalém, que minha mão direita se esqueça de sua habilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Que minha língua grude no céu da boca se eu não me lembrar de ti, se eu não pôr Jerusalém acima de todas as minhas alegrias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Lembra-te, SENHOR, dos filhos de Edom no dia de Jerusalém, que diziam: Arruinai -a,arruinai -a,até ao seus fundamentos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Ah filha de Babilônia, que serás destruída! Bem-aventurado a quem te retribuir o que fizeste conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Bem-aventurado aquele que tomar dos teus filhos, e lançá-los contra as pedras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Salmo de Davi: Louvarei a ti com todo o meu coração; na presença dos deuses cantarei louvores a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Eu me prostrarei ao teu santo templo, e louvarei o teu nome por tua bondade e por tua verdade; porque engrandeceste tua palavra e teu nome acima de tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'No dia em que clamei, tu me respondeste; e me fortaleceste com força em minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Todos os reis da terra louvarão a ti, SENHOR, quando ouvirem as palavras de tua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'E cantarão sobre os caminhos do SENHOR, pois grande é a glória do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Porque mesmo sendo SENHOR elevado, ele presta atenção ao humilde; porém ele reconhece o arrogante de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Enquanto ando no meio da angústia, tu me vivificas; tu estendes tua mão contra a ira de meus inimigos; e tua mão direita me salva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'O SENHOR fará por completo o que ele tem para mim; ó SENHOR, tua bondade dura para sempre; não abandones as obras de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Salmo de Davi, para o regente: SENHOR, tu me examinas e me conheces.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tu sabes o meu sentar e o meu caminhar; de longe entendes meus pensamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Tu cercas o meu andar e meu deitar; conheces desde antes os meus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Mesmo não havendo ainda palavra alguma em minha língua, eis, SENHOR, que já sabes tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Tu me envolves por detrás e pela frente, e pões tua mão sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Teu conhecimento é maravilhoso demais para mim, tão alto que não posso alcançá -lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Para onde eu escaparia de teu Espírito? E para onde fugiria de tua presença?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Se eu subisse até os céus, lá tu estás; se eu fosse me deitar no mundo dos mortos, eis que tu também ali estarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Se eu tomasse as asas do amanhecer, e morasse nos limites do mar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Até ali tua mão me guiaria, e tua mão direita me seguraria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Se eu dissesse: Certamente as trevas me encobrirão; e a luz ao redor de mim será como a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Porém nem mesmo as trevas me esconderão de ti; ao invés disso, pois a noite é tão clara quanto o dia, e aos teus olhos as trevas são como a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Porque tu és dono do meu ser, e me cobriste no ventre da minha mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Eu te louvarei porque de um jeito assombroso e maravilhoso eu fui feito; maravilhosas são tuas obras; e minha alma sabe muito bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Meus ossos não estavam escondidos de ti quando eu fui feito em oculto, e formado como tramas de tecido nas profundezas da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Teus olhos viram meu corpo ainda sem forma, e tudo estava escrito em teu livro; até os dias estavam determinados quando nenhum deles ainda havia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Como são preciosos para mim os teus pensamentos, Deus! Como é grande a quantidade deles!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Se eu os contasse, seriam muito mais numerosos que a areia; quando acordo, ainda estou contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Ah, Deus, tomara que mates ao perverso! E vós, homens sanguinários, afastai-vos de mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Porque eles falam de ti com maldade, e teus inimigos se exaltam em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Por acaso, SENHOR, eu não odiaria aos que te odeiam? E não detestaria os que se levantam contra ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Eu os odeio com ódio completo; eu os considero como inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Examina-me, Deus, e conhece meu coração; prova-me, e conhece meus pensamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'E vê se em mim há algum mau caminho; e guia-me pelo caminho eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Salmo de Davi, para o regente: Livra-me do homem mau, SENHOR; guarda-me dos homens violentos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Que pensam maldades no coração; todo dia se reúnem para fazerem guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Eles afiam suas línguas como a cobra; veneno de serpentes há debaixo de seus lábios. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Guarda-me, SENHOR, das mãos do perverso; guarda-me do homens violentos, que pensam em empurrar os meus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Os arrogantes me armaram ciladas e cordas; estenderam uma rede de um lado do caminho; e puseram laços de armadilhas para mim. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Eu disse ao SENHOR: Tu és meu Deus; inclina teus ouvidos à voz de minhas súplicas, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Ó Senhor DEUS, força de minha salvação, cobriste minha cabeça no dia da batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Não concedas ao perverso os desejos dele, SENHOR; não permitas suceder seu plano maligno, pois senão se exaltariam. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Quanto à cabeça dos que me cercam, que a opressão de seus próprios lábios os cubra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Caiam sobre eles brasas vivas; faça-os cair no fogo e em covas profundas, para que não se levantem mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'O homem de língua maligna não se firmará na terra; o mal perseguirá o homem violento até derrubá -lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Eu sei que o SENHOR cumprirá a causa do aflito, o direito dos necessitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Certamente os justos agradecerão ao teu nome; os corretos habitarão perante teu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Salmo de Davi: Ó SENHOR, eu clamo a ti; apressa-te a mim; ouve minha voz, quando eu clamar a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Apresente-se minha oração como incenso diante de ti; e o levantar de minhas mãos como a oferta do anoitecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Põe, SENHOR, uma guarda em minha boca; vigia a abertura dos meus lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Não inclines meu coração para as coisas más, para fazer o mal junto com homens que praticam maldade; e não coma eu das delícias deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Que o justo me faça o favor de me espancar e me repreender; isto me será azeite sobre a cabeça; minha cabeça não rejeitará, porque ainda orarei contra as maldades deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Quando seus juízes forem lançados contra a rocha, então ouvirão minhas palavras, porque são agradáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Tal como alguém que fendeu e partiu a terra, assim também nossos ossos foram espalhados à boca do mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Porém meus olhos estão voltados para ti, ó Senhor DEUS; em ti confio; não desampares minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Guarda-me do perigo da armadilha que me prepararam; e dos laços da cilada dos que praticam perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Caiam os perversos cada um em suas próprias redes, e eu passe adiante em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Instrução de Davi; oração quando ele estava na caverna: Com minha voz clamo ao SENHOR; com minha voz suplico ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Diante dele derramo meu pedido; diante dele contei minha angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Estando meu espírito angustiado em mim, tu conheceste meu percurso; no caminho em que eu andava esconderam um laço de armadilha para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Eu olho à direita, e eis que não há quem me conheça; não há nenhum refúgio para mim; nem ninguém se importava com minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Eu clamo a ti, SENHOR, dizendo: Tu és meu refúgio, e minha porção na terra dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Presta atenção aos meus gritos, porque estou muito oprimido; resgata-me daqueles que me perseguem, pois são mais fortes que eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Tira minha alma da prisão, para que eu louve o teu nome; os justos me rodearão, porque tu me tratarás bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Salmo de Davi: Ó SENHOR, ouve minha oração; inclina teus ouvidos às minhas súplicas; responde-me segundo tua fidelidade e tua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'E não entres em juízo com teu servo; porque nenhum ser vivo será justo diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Pois o inimigo persegue minha alma, atropela na terra a minha vida; e me obriga a viver na escuridão, como os que há muito tempo morreram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Por isso meu espírito se enche de angústia em mim, e meu coração está desesperado dentro de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Lembro-me dos dias antigos, eu considero todos os teus feitos; medito nas obras de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Levanto minhas mãos a ti; minha alma tem sede de ti como a terra seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Responde-me depressa, SENHOR; porque meu espírito está muito fraco; não escondas tua face de mim, pois eu seria semelhante aos que descem à cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'De madrugada faze com que eu ouça tua bondade, porque em ti confio; faze-me saber o caminho que devo seguir, porque a ti levanto minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Livra-me de meus inimigos, SENHOR; pois em ti eu me escondo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Ensina-me a fazer a tua vontade, pois tu és meu Deus; teu bom Espírito me guie por terra plana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Vivifica-me por teu nome, SENHOR; por tua justiça tira minha alma da angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'E por tua bondade extermina os meus inimigos; e destrói a todos os que afligem a minha alma; pois eu sou teu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Salmo de Davi: Bendito seja o SENHOR, rocha minha, que ensina minhas mãos para a batalha, e meus dedos para a guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Ele é minha bondade e meu castelo; meu alto refúgio, e meu libertador; ele é meu escudo, em quem confio; e aquele que faz meu povo se submeter a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Ó SENHOR, o que é o homem para que lhe dês atenção? E o filho do homem, para que com ele te importes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'O homem é semelhante a um sopro; seus dias, como a sombra que passa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Ó SENHOR, abaixa teus céus, e desce; toca os montes, e fumeguem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Lança relâmpagos, e os dispersa; envia tuas flechas, e os derrota.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Estende tuas mãos desde o alto; livra-me, e resgata-me das muitas águas, das mãos dos filhos de estrangeiros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Cuja boca fala coisas inúteis, e sua mão direita é a mão direita da mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Ó Deus, a ti cantarei uma canção nova; com harpa e instrumento de dez cordas tocarei música a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Tu és o que dás vitória aos reis, e livras a Davi, teu servo, da espada maligna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Livra-me e resgata-me das mãos dos filhos de estrangeiros; cuja boca fala mentiras, e sua mão direita é mão direita de falsidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Para que nossos filhos sejam como plantas, que crescem em sua juventude; e nossas filhas sejam como esquinas entalhadas ao modo do palácio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Nossos celeiros sejam cheios de todos os tipos de mantimentos; nosso gado seja aos milhares, e dezenas de milhares em nossos campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Nossos bois sejam vigorosos; não haja nem assalto, nem fugas, nem gritos em nossas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Bem-aventurado é o povo que assim lhe acontece; bem-aventurado é o povo cujo Deus é o SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Cântico de Davi: Eu te exaltarei, meu Deus e Rei; e bendirei teu nome para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Todo dia eu te bendirei, e louvarei teu nome para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'O SENHOR é grande e muito louvável; sua grandeza é incompreensível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Geração após geração louvará tuas obras, e anunciarão tuas proezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Eu falarei da honra gloriosa de tua majestade, e de teus feitos maravilhosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'E falarão do poder de teus assombrosos feitos; e eu contarei tua grandeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Declararão a lembrança de tua grande bondade; e anunciarão tua justiça alegremente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Piedoso e misericordioso é o SENHOR; ele demora para se irar, e tem grande bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'O SENHOR é bom para com todos; e suas misericórdias estão sobre todas as obras que ele fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Todas as tuas obras louvarão a ti, SENHOR; e teus santos te bendirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Contarão a glória de teu reino, e falarão de teu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Para anunciarem aos filhos dos homens suas proezas, e a honra gloriosa de seu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Teu reino é um reino eterno, e teu domínio dura geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'O SENHOR segura todos os que caem, e levanta todos os abatidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Os olhos de todos esperam por ti, e tu lhes dás seu alimento ao seu tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Tu abres tua mão, e sacias o desejo de todo ser vivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'O SENHOR é justo em todos os seus caminhos, e bondoso em todas as suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'O SENHOR está perto de todos os que o chamam; de todos os que clamam a ele sinceramente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Ele faz a vontade dos que o temem; e ouve o clamor deles, e os salva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'O SENHOR protege a todos os que o amam; porém destrói a todos os perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Minha boca anunciará louvores ao SENHOR; e todo ser feito de carne louvará seu santo nome para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Aleluia! Louva ao SENHOR, ó minha alma!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Louvarei ao SENHOR durante toda a minha vida; cantarei louvores a meu Deus enquanto eu existir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Não ponhas tua confiança em príncipes; em filhos de homens, em quem não há salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'O espírito dele s sai, e volta para sua terra; naquele mesmo dia seus pensamentos perecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Bem-aventurado aquele que tem o Deus de Jacó como sua ajuda, cuja esperança está no SENHOR seu Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Que fez os céus e a terra, o mar, e tudo o que neles há; que guarda a fidelidade para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Que faz juízo aos oprimidos, que dá pão aos famintos; o SENHOR solta aos presos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'O SENHOR abre os olhos dos cegos; o SENHOR levanta aos abatidos; o SENHOR ama aos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'O SENHOR guarda os estrangeiros; sustenta o órfão e a viúva; mas põe dificuldades ao caminho dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'O SENHOR reinará eternamente. Ó Sião, o teu Deus reinará geração após geração. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Louvai ao SENHOR, porque é bom cantar louvores ao nosso Deus; porque agradável e merecido é o louvor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'O SENHOR edifica a Jerusalém; e ajunta os dispersos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Ele sara aos de coração partido, e os cura de suas dores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Ele conta o número das estrelas; chama todas elas pelos seus nomes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'O nosso Senhor é grande e muito poderoso; seu entendimento é incomensurável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'O SENHOR levanta aos mansos; e abate aos perversos até a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Cantai ao SENHOR em agradecimento; cantai louvores ao nosso Deus com harpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Ele que cobre o céu com nuvens, que prepara chuva para a terra, que faz os montes produzirem erva;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Que dá ao gado seu pasto; e também aos filhos dos corvos, quando clamam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ele não se agrada da força do cavalo, nem se contenta com as pernas do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'O SENHOR se agrada dos que o temem, daqueles que esperam por sua bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Louva, Jerusalém, ao SENHOR; celebra ao teu Deus, ó Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Porque ele fortifica os ferrolhos de tuas portas; ele abençoa a teus filhos dentro de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Ele é o que dá paz às tuas fronteiras; e te farta com o melhor trigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Que envia sua ordem à terra; sua palavra corre velozmente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Que dá a neve como a lã; espalha a geada como a cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Que lança seu gelo em pedaços; quem pode subsistir ao seu frio?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Ele manda sua palavra, e os faz derreter; faz soprar seu vento, e escorrem-se as águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Ele declara suas palavras a Jacó; e seus estatutos e seus juízos a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Ele não fez assim a nenhuma outra nação; e não conhecem os juízos dele. Louvai ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Aleluia! Louvai ao SENHOR desde os céus; louvai-o nas alturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Louvai-o todos os seus anjos; louvai-o todos os seus exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Louvai-o, sol e lua; louvai-o, todas as estrelas luminosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Louvai-o, céus dos céus, e as águas que estais sobre os céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Louvem ao nome do SENHOR; porque pela ordem dele foram criados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'E os firmou para todo o sempre; e deu tal decreto, que não será traspassado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Louvai ao SENHOR vós da terra: os monstros marinhos, e todos os abismos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'O fogo e a saraiva, a neve e o vapor; o vento tempestuoso, que executa sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Os montes e todos os morros; árvores frutíferas, e todos os cedros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'As feras, e todo o gado; répteis, e aves que tem asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Os reis da terra, e todos os povos; os príncipes, e todos os juízes da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Os rapazes, e também as moças; os velhos com os jovens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Louvem ao nome do SENHOR; pois só o nome dele é exaltado; sua majestade está sobre a terra e o céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'E ele exaltou o poder de seu povo: o louvor de todos os seus santos, os filhos de Israel, o povo que está perto dele. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Aleluia! Cantai ao SENHOR um cântico novo; haja louvor a ele na congregação dos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Alegre-se Israel em seu Criador; os filhos de Sião se encham de alegria em seu Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Louvem seu nome com danças; cantai louvores a ele com tamborim e harpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Porque o SENHOR se agrada de seu povo; ele ornará os mansos com salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Saltem de prazer seus santos pela glória; fiquem contentes sobre suas camas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Exaltações a Deus estarão em suas gargantas; e espada afiada estará em sua mão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Para se vingarem das nações, e repreenderem aos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Para prenderem a seus reis com correntes, e seus nobres com grilhões de ferro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Para executarem sobre eles a sentença escrita; esta será a glória de todos os seus santos. Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Aleluia! Louvai a Deus em seu santuário; louvai-o no firmamento de seu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Louvai-o por suas proezas; louvai-o conforme a imensidão de sua grandeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Louvai-o com com de trombeta; louvai-o com lira e harpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Louvai-o com tamborim e flauta; louvai-o com instrumentos de cordas e de sopro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Louvai-o com címbalos bem sonoros; louvai-o com címbalos de sons de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Tudo quanto tem fôlego, louve ao SENHOR! Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Provérbios de Salomão, filho de Davi, rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Para conhecer a sabedoria e a instrução; para entender as palavras da prudência;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Para obter a instrução do entendimento; justiça, juízo e equidades;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Para dar inteligência aos simples, conhecimento e bom senso aos jovens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'O sábio ouvirá, e crescerá em conhecimento; o bom entendedor obterá sábios conselhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Para entender provérbios e sua interpretação; as palavras dos sábios, e seus enigmas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'O temor ao SENHOR é o principio do conhecimento; os tolos desprezam a sabedoria e a instrução.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Filho meu, ouve a instrução de teu pai; e não abandones a doutrina de tua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Porque serão um ornamento gracioso para tua cabeça; e colares para teu pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Filho meu, se os pecadores tentarem te convencer, não te deixes influenciar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Se disserem: Vem conosco, vamos espiar derramamento de sangue; preparemos uma emboscada ao inocente sem razão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Vamos tragá-los vivos, como se fosse o mundo dos mortos; e inteiros, como os que descem à cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Acharemos toda espécie de coisas valiosas, encheremos nossas casas de despojos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Lança tua sorte entre nós, compartilharemos todos de uma só bolsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Filho meu, não sigas teu caminho com eles; desvia teu pé para longe de onde eles passarem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Porque os pés deles correm para o mal, e se apressam para derramar sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Certamente é inútil se estender a rede diante da vista de todas as aves;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Porém estes estão esperando o derramamento de seu próprio sangue; e preparam emboscada para suas próprias almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Assim são os caminhos de todo aquele que tem ganância pelo lucro desonesto; ela tomará a alma daqueles que a tem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'A sabedoria grita pelas ruas; nas praças ela levanta sua voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Ela clama nas encruzilhadas, onde passam muita gente; às entradas das portas, nas cidades ela diz suas mensagens:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Até quando, ó tolos, amareis a tolice? E vós zombadores, desejareis a zombaria? E vós loucos, odiareis o conhecimento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Convertei-vos à minha repreensão; eis que vos derramarei meu espírito, e vos farei saber minhas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Mas porque eu clamei, e recusastes; estendi minha mão, e não houve quem desse atenção,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'E rejeitastes todo o meu conselho, e não quisestes minha repreensão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Também eu rirei em vosso sofrimento, e zombarei, quando vier vosso medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Quando vier vosso temor como tempestade, e a causa de vosso sofrimento como ventania, quando vier sobre vós a opressão e a angústia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Então clamarão a mim; porém eu não responderei; de madrugada me buscarão, porém não me acharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Porque odiaram o conhecimento; e escolheram não temer ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Não concordaram com meu conselho, e desprezaram toda a minha repreensão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Por isso comerão do fruto do seu próprio caminho, e se fartarão de seus próprios conselhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Pois o desvio dos tolos os matará, e a confiança dos loucos os destruirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Porém aquele que me ouvir habitará em segurança, e estará tranquilo do temor do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Filho meu, se aceitares minhas palavras, e depositares em ti meus mandamentos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Para fazeres teus ouvidos darem atenção à sabedoria, e inclinares teu coração à inteligência;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'E se clamares à prudência, e à inteligência dirigires tua voz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Se tu a buscares como a prata, e a procurares como que a tesouros escondidos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Então entenderás o temor ao SENHOR, e acharás o conhecimento de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Porque o SENHOR dá sabedoria; de sua boca vem o conhecimento e o entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Ele reserva a boa sabedoria para os corretos; ele é escudo para os que andam em sinceridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Para guardar os caminhos do juízo; e conservar os passos de seus santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Então entenderás a justiça e o juízo, e a equidade; e todo bom caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Quando a sabedoria entrar em teu coração, e o conhecimento for agradável à tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'O bom senso te guardará, e o entendimento te preservará:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, '- Para te livrar do mau caminho, e dos homens que falam perversidades;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Que deixam as veredas da justiça para andarem pelos caminhos das trevas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Que se alegram em fazer o mal, e se enchem de alegria com as perversidades dos maus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Cujas veredas são distorcidas, e desviadas em seus percursos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, '- Para te livrar da mulher estranha, e da pervertida, que lisonjeia com suas palavras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Que abandona o guia de sua juventude, e se esquece do pacto de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Porque sua casa se inclina para a morte, e seus caminhos para os mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Todos os que entrarem a ela, não voltarão mais; e não alcançarão os caminhos da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, '- Para andares no caminho dos bons, e te guardares nas veredas dos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Porque os corretos habitarão a terra; e os íntegros nela permanecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Porém os perversos serão cortados da terra, e os infiéis serão arrancados dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Filho meu, não te esqueças de minha lei; e que teu coração guarde meus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Porque te acrescentarão extensão de dias, e anos de vida e paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Que a bondade e a fidelidade não te desamparem; amarra-as junto ao teu pescoço; escreve-as na tábua de teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Então tu acharás graça e bom entendimento, aos olhos de Deus e dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Confia no SENHOR com todo o teu coração; e não te apoies em teu próprio entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Dá reconhecimento a ele em todas os teus caminhos; e ele endireitará tuas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Não sejas sábio aos teus próprios olhos; teme ao SENHOR, e afasta-te do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Isto será remédio para teu corpo, e alívio para teus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Honra ao SENHOR com teus bens, e com a primeira parte de toda a tua renda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'E teus celeiros se encherão de fartura, e teus tanques transbordarão de vinho novo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Filho meu, não rejeites a correção do SENHOR, nem te desagrades de sua repreensão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Porque o SENHOR repreende a quem ele ama, assim como o pai ao filho, a quem ele quer bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Bem-aventurado o homem que encontra sabedoria, e o homem que ganha conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Porque seu produto é melhor que o produto da prata; e seu valor, mais do que o do ouro fino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Ela é mais preciosa do que rubis; e tudo o que podes desejar não se pode comparar a ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Extensão de dias há em sua mão direita; em sua esquerda riquezas e honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Seus caminhos são caminhos agradáveis; e todas as suas veredas são paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Ela é uma árvore de vida para os que dela pegam; e bem-aventurados são todos os que a retêm.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'O SENHOR com sabedoria fundou a terra; ele preparou os céus com a inteligência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Com seu conhecimento se fenderam os abismos, e as nuvens gotejam orvalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Filho meu, que estes não se afastem de teus olhos; guarda a sabedoria e o bom-senso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Porque serão vida para tua alma, e graça para teu pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Então andarás por teu caminho em segurança; e com teus pés não tropeçarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Quando te deitares, não terás medo; tu deitarás, e teu sono será suave.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Não temas o pavor repentino; nem da assolação dos perversos, quando vier.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Porque o SENHOR será tua esperança; e ele guardará teus pés para que não sejam presos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Não detenhas o bem daqueles que possuem o direito, se tiveres em tuas mãos poder para o fazeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Não digas a teu próximo: Vai, e volta depois, que amanhã te darei; se tu tiveres contigo o que ele te pede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Não planejes o mal contra teu próximo, pois ele mora tendo confiança em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Não brigues contra alguém sem motivo, se ele não fez mal contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Não tenhas inveja do homem violento, nem escolhas seguir algum dos caminhos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Porque o SENHOR abomina os perversos; mas ele guarda o seu segredo com os justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'A maldição do SENHOR está na casa do perverso; porém ele abençoa a morada dos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Certamente ele zombará dos zombadores; mas dará graça aos humildes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Os sábios herdarão honra; porém os loucos terão sobre si confusão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Ouvi, filhos, a correção do pai; e prestai atenção, para que conheçais o entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Pois eu vos dou boa doutrina; não deixeis a minha lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Porque eu era filho do meu pai; tenro, e único perante a face de minha mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'E ele me ensinava, e me dizia: Que teu coração retenha minhas palavras; guarda meus mandamentos, e vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Adquire sabedoria, adquire entendimento; e não te esqueças nem te desvies das palavras de minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Não a abandones, e ela te guardará; ama-a, e ela te conservará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'O principal é a sabedoria; adquire sabedoria, e acima de tudo o que adquirires, adquire entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Exalta-a, e ela te exaltará; quando tu a abraçares, ela te honrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Ela dará a tua cabeça um ornamento gracioso; ela te entregará uma bela coroa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Ouve, filho meu, e recebe minhas palavras; e elas te acrescentarão anos de vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Eu te ensino no caminho da sabedoria; e te faço andar pelos percursos direitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Quando tu andares, teus passos não se estreitarão; e se tu correres, não tropeçarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Toma a correção para si, e não a largues; guarda-a, porque ela é tua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Não entres pela vereda dos perversos, nem andes pelo caminho dos maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Rejeita-o! Não passes por ele; desvia-te dele, e passa longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Pois eles não dormem se não fizerem o mal; e ficam sem sono, se não fizerem tropeçar a alguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Porque comem pão da maldade, e bebem vinho de violências.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mas o caminho dos justos é como a luz brilhante, que vai, e ilumina até o dia ficar claro por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'O caminho dos perversos é como a escuridão; não sabem nem em que tropeçam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Filho meu, presta atenção às minhas palavras; e ouve as minhas instruções.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Não as deixes ficarem longe de teus olhos; guarda-as no meio de teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Porque são vida para aqueles que as encontram; e saúde para todo o seu corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Acima de tudo o que se deve guardar, guarda o teu coração; porque dele procedem as saídas da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Afasta de ti a perversidade da boca; e põe para longe de ti a corrupção dos lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Teus olhos olhem direito; tuas pálpebras estejam corretas diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Pondera o curso de teus pés; e todos os teus caminhos sejam bem ordenados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Não te desvies nem para a direita, nem para a esquerda; afasta teus pés do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Filho meu, presta atenção à minha sabedoria, inclina teus ouvidos ao meu entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Para que guardes o bom-senso; e teus lábios conservem o conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Porque os lábios da mulher pervertida gotejam mel; e sua boca é mais suave que o azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Porém seu fim é mais amargo que o absinto; é afiado como a espada de dois fios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Os pés dela descem à morte; seus passos pegam o mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Para que não ponderes a vereda da vida, os percursos delas são errantes, e tu não os conhecerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'E agora, filhos, escutai-me; e não vos desvieis das palavras de minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Mantenha teu caminho longe dela; e não te aproximes da porta da casa dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Para que não dês tua honra a outros, nem teus anos de vida aos cruéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Para que estranhos não se fartem de teu poder, e teus trabalhos não sejam aproveitados em casa alheia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'E gemas em teu fim, quando tua carne e teu corpo estiverem consumidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'E digas: Como eu odiei a correção, e meu coração desprezou a repreensão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'E não escutei a voz de meus ensinadores, nem ouvi a meus mestres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Quase me achei em todo mal, no meio da congregação e do ajuntamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Bebe água de tua própria cisterna, e das correntes de teu próprio poço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Derramar-se-iam por fora tuas fontes, e pelas ruas os ribeiros de águas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Sejam somente para ti, e não para os estranhos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Seja bendito o teu manancial, e alegra-te com a mulher de tua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Seja ela uma cerva amorosa e gazela graciosa; que os seios dela te fartem em todo tempo; e anda pelo caminho do amor dela continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'E por que tu, filho meu, andarias perdido pela estranha, e abraçarias o peito da mulher alheia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Pois os caminhos do homem estão perante os olhos do SENHOR; e ele pondera todos os seus percursos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'O perverso será preso pelas suas próprias perversidades; e será detido pelas cordas de seu próprio pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Ele morrerá pela falta de correção; e andará sem rumo pela grandeza de sua loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Filho meu, se ficaste fiador por teu próximo, se deste tua garantia ao estranho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Se tu foste capturado pelas palavras de tua própria boca, e te prendeste pelas palavras de tua boca,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Então faze isto agora, meu filho, e livra-te, pois caíste nas mãos de teu próximo; vai, humilha-te, e insiste exaustivamente ao teu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Não dês sono aos teus olhos, nem cochilo às tuas pálpebras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Livra-te, como a corça do caçador, como o pássaro do caçador de aves.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Vai até a formiga, preguiçoso; olha para os caminhos dela, e sê sábio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Ela, mesmo não tendo chefe, nem fiscal, nem dominador,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Prepara seu alimento no verão, na ceifa ajunta seu mantimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Ó preguiçoso, até quando estarás deitado? Quando te levantarás de teu sono?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Um pouco de sono, um pouco de cochilo; um pouco de descanso com as mãos cruzadas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Assim a pobreza virá sobre ti como um assaltante; a necessidade chegará a ti como um homem armado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'O homem mal, o homem injusto, anda com uma boca perversa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Ele acena com os olhos, fala com seus pés, aponta com seus dedos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Perversidades há em seu coração; todo o tempo ele trama o mal; anda semeando brigas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Por isso sua perdição virá repentinamente; subitamente ele será quebrado, e não haverá cura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Estas seis coisas o SENHOR odeia; e sete sua alma abomina:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Olhos arrogantes, língua mentirosa, e mãos que derramam sangue inocente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'O coração que trama planos malignos, pés que se apressam a correr para o mal;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'A falsa testemunha, que sopra mentiras; e o que semeia brigas entre irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Filho meu, guarda o mandamento de teu pai; e não abandones a lei de tua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Amarra-os continuamente em teu coração; e pendura-os ao teu pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Quando caminhares, isto te guiará; quando deitares, isto te guardará; quando acordares, isto falará contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Porque o mandamento é uma lâmpada, e a lei é luz; e as repreensões para correção são o caminho da vida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Para te protegerem da mulher má, das lisonjas da língua da estranha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Não cobices a formosura dela em teu coração; nem te prenda em seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Porque pela mulher prostituta chega-se a pedir um pedaço de pão; e a mulher de outro homem anda à caça de uma alma preciosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Por acaso pode alguém botar fogo em seu peito, sem que suas roupas se queimem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Ou alguém pode andar sobre as brasas, sem seus pés se arderem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Assim será aquele que se deitar com a mulher de seu próximo; não será considerado inocente todo aquele que a tocar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Não se despreza ao ladrão, quando furta para saciar sua alma, tendo fome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Mas, se for achado, ele pagará sete vezes mais; ele terá que dar todos os bens de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Porém aquele que adultera com mulher alheia tem falta de entendimento; quem faz isso destrói sua própria alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Ele encontrará castigo e desgraça; e sua desonra nunca será apagada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Porque ciúmes são a fúria do marido, e ele de maneira nenhuma terá misericórdia no dia da vingança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Ele não aceitará nenhum pagamento pela culpa; nem consentirá, ainda que aumentes os presentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Filho meu, guarda minhas palavras; e deposita em ti meus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Guarda meus mandamentos, e vive; e minha lei, como as pupilas de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Ata-os aos teus dedos; escreve-os na tábua do teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Dize à sabedoria: Tu és minha irmã; E à prudência chama de parente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Para que te guardem da mulher alheia, da estranha, que lisonjeia com suas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Porque da janela de minha casa, pelas minhas grades eu olhei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'E vi entre os simples, prestei atenção entre os jovens, um rapaz que tinha falta de juízo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Que estava passando pela rua junto a sua esquina, e seguia o caminho da casa dela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'No crepúsculo, ao entardecer do dia, no escurecer da noite e nas trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'E eis que uma mulher lhe saiu ao encontro, com roupas de prostituta, e astuta de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Esta era barulhenta e insubordinada; os pés dela não paravam em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'De tempos em tempos ela fica fora de casa,nas ruas, espreitando em todos os cantos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Então ela o pegou, e o beijou; e com atrevimento em seu rosto, disse-lhe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Sacrifícios pacíficos tenho comigo; hoje paguei meus votos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Por isso saí para te encontrar; para buscar apressadamente a tua face, e te achei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Já preparei minha cama com cobertas; com tecidos de linho fino do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Já perfumei meu leito com mirra, aloés e canela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Vem comigo; iremos nos embebedar de paixões até a manhã, e nos alegraremos de amores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Porque meu marido não está em casa; ele viajou para longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Ele tomou uma bolsa de dinheiro em sua mão; e só volta para casa no dia determinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Ela o convenceu com suas muitas palavras sedutoras; com a lisonja de seus lábios ela o persuadiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Ele foi logo após ela, como o boi vai ao matadouro; e como o louco ao castigo das prisões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Até que uma flecha atravesse seu fígado; como a ave que se apressa para a armadilha, e não sabe que está armada contra sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Agora pois, filhos, escutai-me; e prestai atenção às palavras de minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Que teu coração não se desvie para os caminhos dela, e não andes perdido pelas veredas dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Porque ela derrubou a muitos feridos; e o total dos mortos por ela foram muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'A casa dela são caminhos para o mundo dos mortos, que descem para as câmaras da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Por acaso a sabedoria não clama, e a inteligência não solta sua voz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Nos lugares mais altos, junto ao caminho, nas encruzilhadas das veredas, ela se põe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Ao lado das portas, à entrada da cidade; na entrada dos portões, ela grita:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Varões, eu vos clamo; dirijo minha voz aos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Vós que sois ingênuos, entendei a prudência; e vós que sois loucos, entendei de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Ouvi, porque falarei coisas nobres; e abro meus lábios para a justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Porque minha boca declarará a verdade; e meus lábios abominam a maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Todas as coisas que digo com minha boca são justas; não há nelas coisa alguma que seja distorcida ou perversa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Todas elas são corretas para aquele que as entende; e justas para os que encontram conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Aceitai minha correção, e não prata; e o conhecimento mais que o ouro fino escolhido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Porque a sabedoria é melhor do que rubis; e todas as coisas desejáveis nem sequer podem ser comparadas a ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Eu, a Sabedoria, moro com a Prudência; e tenho o conhecimento do conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'O temor ao SENHOR é odiar o mal: a soberba e a arrogância, o mal caminho e a boca perversa, eu os odeio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'A mim pertence o conselho e a verdadeira sabedoria; eu tenho prudência e poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Por meio de mim os reis governam, e os príncipes decretam justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Por meio de mim os governantes dominam; e autoridades, todos os juízes justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Eu amo os que me amam; e os que me buscam intensamente me acharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Bens e honra estão comigo; assim como a riqueza duradoura e a justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Meu fruto é melhor que o ouro, melhor que o ouro refinado; e meus produtos melhores que a prata escolhida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Eu faço andar pelo caminho da justiça, no meio das veredas do juízo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Para eu dar herança aos que me amam, e encher seus tesouros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'O SENHOR me adquiriu no princípio de seu caminho; desde antes de suas obras antigas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Desde a eternidade eu fui ungida; desde o princípio; desde antes do surgimento da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Quando ainda não havia abismos, eu fui gerada; quando ainda não havia fontes providas de muitas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Antes que os montes fossem firmados; antes dos morros, eu fui gerada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Quando ele ainda não tinha feito a terra, nem os campos; nem o princípio da poeira do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Quando preparava os céus, ali eu estava; quando ele desenhava ao redor da face do abismo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Quando firmava as nuvens de cima, quando fortificava as fontes do abismo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Quando colocava ao mar o seu limite, para que as águas não ultrapassassem seu mandado; quando estabelecia os fundamentos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Então eu estava com ele como um pupilo; e eu era seu agrado a cada dia, alegrando perante ele em todo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Alegrando na habitação de sua terra; e concedendo meus agrados aos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Portanto agora, filhos, ouvi-me; porque bem-aventurados serão os que guardarem meus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Ouvi a correção, e sede sábios; e não a rejeiteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Bem-aventurado é o homem que me ouve; que vigia em minhas portas diariamente, que guarda as ombreiras de minhas entradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Porque aquele que me encontrar, encontrará a vida; e obterá o favor do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Mas aquele que pecar contra mim fará violência à sua própria alma; todos os que me odeiam amam a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'A verdadeira sabedoria edificou sua casa; ela lavrou suas sete colunas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Ela sacrificou seu sacrifício, misturou seu vinho, e preparou sua mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Mandou suas servas, e está convidando desde os pontos mais altos da cidade, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Qualquer um que for ingênuo, venha aqui.Aos que têm falta de entendimento, ela diz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Vinde, comei do meu pão; e bebei do vinho que misturei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Abandonai a tolice; e vivei; e andai pelo caminho da prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Aquele que repreende ao zombador, toma desonra para si mesmo; e o que tenta corrigir ao perverso acaba sendo manchado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Não repreendas ao zombador, para que ele não te odeie; repreende ao sábio, e ele te amará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Ensina ao sábio, e ele será mais sábio ainda; instrui ao justo, e ele aumentará seu conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'O temor ao SENHOR é o princípio da sabedoria; e o conhecimento dos santos é a prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Porque por mim teus dias serão multiplicados; e anos de vida a ti serão aumentados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Se fores sábio, serás sábio para ti; e se fores zombador, somente tu aguentarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'A mulher louca é causadora de tumultos; ela é tola, e não sabe coisa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'E se senta à porta de sua casa, sobre uma cadeira, nos lugares altos da cidade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Para chamar aos que passam pelo caminho, e passam por suas veredas, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Qualquer um que for ingênuo, venha aqui! E aos que tem falta de entendimento, ela diz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'As águas roubadas são doces; e o pão escondido é agradável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Porém aquele que a ouve não sabe que ali estão os mortos; os convidados dela estão nas profundezas do mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Provérbios de Salomão:O filho sábio alegra ao pai; mas o filho tolo é tristeza para sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Tesouros da perversidade para nada aproveitam; porém a justiça livra da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'O SENHOR não permite a alma do justo passar fome, porém arruína o interesse dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Aquele que trabalha com mão preguiçosa empobrece; mas a mão de quem trabalha com empenho enriquece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Aquele que ajunta no verão é filho prudente; mas o que dorme na ceifa é filho causador de vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Há bênçãos sobre a cabeça dos justos; mas a violência cobre a boca dos perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'A lembrança do justo será uma bênção; mas o nome dos perversos apodrecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'O sábio de coração aceita os mandamentos; mas o louco de lábios será derrubado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Aquele que anda em sinceridade anda seguro; mas o que perverte seus caminhos será conhecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Aquele que pisca os olhos maliciosamente gera dores; e o louco de lábios será derrubado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'A boca do justo é um manancial de vida; mas a boca dos perversos está coberta de violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'O ódio desperta brigas; mas o amor cobre todas as transgressões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Nos lábios do bom entendedor se acha sabedoria, mas uma vara está às costas daquele que não tem entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Os sábios guardam consigo sabedoria; mas a boca do tolo está perto da perturbação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'A prosperidade do rico é a sua cidade fortificada; a pobreza dos necessitados é sua perturbação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'A obra do justo é para a vida; os frutos do perverso, para o pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'O caminho para a vida é d aquele que guarda a correção; mas aquele que abandona a repreensão anda sem rumo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Aquele que esconde o ódio tem lábios mentirosos; e o que produz má fama é tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Na abundância de palavras não há falta de transgressão; mas aquele que refreia seus lábios é prudente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'A língua do justo é como prata escolhida; o coração dos perversos vale pouco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Os lábios dos justo apascentam a muitos; mas os tolos, por falta de entendimento, morrem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'É a bênção do SENHOR que enriquece; e ele não lhe acrescenta dores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Para o tolo, fazer o mal é uma diversão; mas para o homem bom entendedor, divertida é a sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'O temor do perverso virá sobre ele, mas o desejo dos justos será concedido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Assim como o vento passa, assim também o perverso não mais existirá; mas o justo tem um alicerce eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Assim como vinagre para os dentes, e como fumaça para os olhos, assim também é o preguiçoso para aqueles que o mandam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'O temor ao SENHOR faz aumentar os dias; mas os anos dos perversos serão encurtados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'A esperança dos justos é alegria; mas a expectativa dos perversos perecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'O caminho do SENHOR é fortaleza para os corretos, mas ruína para os que praticam maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'O justo nunca será removido, mas os perversos não habitarão a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'A boca do justo produz sabedoria, mas a língua perversa será cortada fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Os lábios do justo sabem o que é agradável; mas a boca dos perversos é cheia de perversidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'A balança enganosa é abominação ao SENHOR; mas o peso justo é seu prazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Quando vem a arrogância, vem também a desonra; mas com os humildes está a sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'A integridade dos corretos os guia; mas a perversidade dos enganadores os destruirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Nenhum proveito terá a riqueza no dia da ira; mas a justiça livrará da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'A justiça do íntegro endireitará seu caminho; mas o perverso cairá por sua perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'A justiça dos corretos os livrará; mas os transgressores serão presos em sua própria perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Quando o homem mau morre, sua expectativa morre; e a esperança de seu poder perece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'O justo é livrado da angústia; e o perverso vem em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'O hipócrita com a boca prejudica ao seu próximo; mas os justos por meio do conhecimento são livrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'No bem dos justos, a cidade se alegra muito; e quando os perversos perecem, há alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Pelo bênção dos sinceros a cidade se exalta; mas pela boca dos perversos ela se destrói.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Aquele que não tem entendimento despreza a seu próximo; mas o homem bom entendedor se mantêm calado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Aquele que conta fofocas revela o segredo; mas o fiel de espírito encobre o assunto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Quando não há conselhos sábios, o povo cai; mas na abundância de bons conselheiros consiste o livramento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Certamente aquele que se tornar fiador de algum estranho passará por sofrimento; mas aquele odeia firmar compromissos ficará seguro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'A mulher graciosa guarda a honra, assim como os violentos guardam as riquezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'O homem bondoso faz bem à sua alma; mas o cruel atormenta sua própria carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'O perverso recebe falso pagamento; mas aquele que semeia justiça terá uma recompensa fiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Assim como a justiça leva para a vida; assim também aquele que segue o mal é levado para sua própria morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'O SENHOR abomina os perversos de coração; porém ele se agrada que caminham com sinceridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Com certeza o mal não será absolvido; mas a semente dos justos escapará livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'A mulher bela mas sem discrição é como uma joia no focinho de uma porca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'O desejo dos justos é somente para o bem; mas a esperança dos perversos é a fúria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Há quem dá generosamente e tem cada vez mais; e há quem retém mais do que é justo e empobrece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'A alma generosa prosperará, e aquele que saciar também será saciado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'O povo amaldiçoa ao que retém o trigo; mas bênção haverá sobre a cabeça daquele que o vende.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Aquele que com empenho busca o bem, busca favor; porém o que procura o mal, sobre ele isso lhe virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Aquele que confia em suas riquezas cairá; mas os justos florescerão como as folhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Aquele que perturba sua própria casa herdará vento; e o tolo será servo do sábio de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'O fruto do justo é uma árvore de vida; e o que ganha almas é sábio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Ora, se o justo recebe seu pagamento na terra, quanto mais o perverso e o pecador!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Aquele que ama a correção ama o conhecimento; mas aquele que odeia a repreensão é um bruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'O homem de bem ganha o favor do SENHOR; mas ao homem de pensamentos perversos, ele o condenará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'O homem não prevalecerá pela perversidade; mas a raiz dos justos não será removida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'A mulher virtuosa é a coroa de seu marido; mas a causadora de vergonha é como uma podridão em seus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Os pensamentos dos justos são de bom juízo; mas os conselhos dos perversos são enganosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'As palavras dos perversos são para espreitar o derramamento de sangue de inocentes; mas a boca dos corretos os livrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Os perversos serão transtornados, e não existirão mais; porém a casa dos justos permanecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Cada um será elogiado conforme seu entendimento; mas o perverso de coração será desprezado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Melhor é o que estima pouco a si mesmo mas tem quem o sirva, do que aquele que elogia e si mesmo, mas nem sequer tem pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'O justo dá atenção à vida de seus animais; mas até as misericórdias dos perversos são cruéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Aquele que lavra sua terra se saciará de pão; mas o que segue coisas inúteis tem falta de juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'O perverso deseja armadilhas malignas; porém a raiz dos justos produzirá seu fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'O perverso é capturado pela transgressão de seus lábios, mas o justo sairá da angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Cada um se sacia do bem pelo fruto de sua própria boca; e a recompensa das mãos do homem lhe será entregue de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'O caminho do tolo é correto aos seus próprios olhos; mas aquele que ouve o bom conselho é sábio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'A ira do tolo é conhecida no mesmo dia, mas o prudente ignora o insulto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Aquele que fala a verdade conta a justiça; porém a testemunha falsa conta o engano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Há alguns que falam palavras como que golpes de espada; porém a língua do sábios é como um remédio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'O lábio da verdade ficará para sempre, mas a língua da falsidade dura por apenas um momento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Há engano no coração dos que tramam o mal; mas os que aconselham a paz têm alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Nenhuma adversidade sobrevirá ao justos; mas os perversos se encherão de mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Os lábios mentirosos são abomináveis ao SENHOR, mas dos que falam a verdade são seu prazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'O homem prudente é discreto em conhecimento; mas o coração dos tolos proclama a loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'A mão dos que trabalham com empenho dominará, e os preguiçosos se tornarão escravos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'A ansiedade no coração do homem o abate; mas uma boa palavra o alegra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'O justo age cuidadosamente para com seu próximo, mas o caminho dos perversos os faz errar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'O preguiçoso não assa aquilo que caçou, mas a riqueza de quem trabalha com empenho lhe é preciosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na vereda da justiça está a vida; e no caminho de seu percurso não há morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'O filho sábio ouve a correção do pai; mas o zombador não escuta a repreensão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Cada um comerá do bem pelo fruto de sua boca, mas a alma dos infiéis deseja a violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Quem toma cuidado com sua boca preserva sua alma; mas aquele que abre muito seus lábios será arruinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'A alma do preguiçoso deseja, mas nada consegue; porém a alma dos trabalham com empenho prosperará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'O justo odeia a palavra mentirosa, mas o perverso age de forma repugnante e vergonhosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'A justiça guarda aquele que tem um caminho íntegro; mas a perversidade transtornará ao pecador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Há alguns que fingem ser ricos, mesmo nada tendo; e outros que fingem ser pobres, mesmo tendo muitos bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'O resgate da vida de cada um são suas riquezas; mas o pobre não ouve ameaças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'A luz dos justos se alegra, mas a lâmpada dos perversos se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'A arrogância só produz brigas; mas com os que aceitam conselhos está a sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'A riqueza ganha sem esforço será perdida; mas aquele que a obtém pelas próprias mãos terá cada vez mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'A esperança que demora enfraquece o coração, mas o desejo cumprido é como uma árvore de vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Quem despreza a boa palavra perecerá; mas aquele que teme ao mandamento será recompensado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'A doutrina do sábio é manancial de vida, para se desviar das ciladas da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'O bom entendimento alcança o favor, mas o caminho dos infiéis é áspero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Todo prudente age com conhecimento, mas o tolo espalha sua loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'O mensageiro perverso cai no mal, mas o representante fiel é como um remédio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Haverá pobreza e vergonha ao que rejeita a correção; mas aquele que atende à repreensão será honrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'O desejo realizado agrada a alma, mas os tolos abominam se afastar do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Quem anda com os sábios se torna sábio; mas aquele que acompanha os tolos sofrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'O mal perseguirá os pecadores, mas os justos serão recompensados com o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'O homem de bem deixará herança aos filhos de seus filhos; mas a riqueza do pecador está reservada para o justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'A lavoura dos pobres gera muita comida; mas há alguns que se destroem por falta de juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Aquele que retém sua vara odeia a seu filho; porém aquele que o ama, desde cedo o castiga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'O justo come até sua alma estar saciada; mas o ventre dos perversos passará por necessidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Toda mulher sábia edifica sua casa; porém a tola a derruba com suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Aquele que anda corretamente teme ao SENHOR; mas o que se desvia de seus caminhos o despreza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Na boca do tolo está a vara da arrogância, porém os lábios dos sábios os protegem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Não havendo bois, o celeiro fica limpo; mas pela força do boi há uma colheita abundante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'A testemunha verdadeira não mentirá, mas a testemunha falsa declara mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'O zombador busca sabedoria, mas não acha nenhuma; mas o conhecimento é fácil para o prudente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Afasta-te do homem tolo, porque nele não encontrarás lábios inteligentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'A sabedoria do prudente é entender seu caminho; mas a loucura dos tolos é engano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Os tolos zombam da culpa, mas entre os corretos está o favor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'O coração conhece sua própria amargura, e o estranho não pode partilhar sua alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'A casa dos perversos será destruída, mas a tenda dos corretos florescerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Há um caminho que parece correto para o homem, porém o fim dele são caminhos de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Até no riso o coração terá dor, e o fim da alegria é a tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Quem se desvia de coração será cheio de seus próprios caminhos, porém o homem de bem será recompensado pelos seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'O ingênuo crê em toda palavra, mas o prudente pensa cuidadosamente sobre seus passos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'O sábio teme, e se afasta do mal; porém o tolo se precipita e se acha seguro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Quem se ira rapidamente faz loucuras, e o homem de maus pensamentos será odiado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Os ingênuos herdarão a tolice, mas os prudentes serão coroados com o conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Os maus se inclinarão perante a face dos bons, e os perversos diante das portas do justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'O pobre é odiado até pelo seu próximo, porém os amigos dos ricos são muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Quem despreza a seu próximo, peca; mas aquele que demonstra misericórdia aos humildes é bem-aventurado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Por acaso não andam errados os que tramam o mal? Mas há bondade e fidelidade para os que planejam o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Em todo trabalho cansativo há proveito, mas o falar dos lábios só leva à pobreza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'A coroa dos sábios é a sua riqueza; a loucura dos tolos é loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'A testemunha verdadeira livra almas, mas aquele que declara mentiras é enganador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'No temor ao SENHOR há forte confiança; e será refúgio para seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'O temor ao SENHOR é manancial de vida, para se desviar dos laços da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Na multidão do povo está a honra do rei, mas a falta de gente é a ruína do príncipe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Quem demora para se irar tem muito entendimento, mas aquele de espírito impetuoso exalta a loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'O coração em paz é vida para o corpo, mas a inveja é como podridão nos ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Quem oprime ao pobre insulta ao seu Criador; mas aquele que mostra compaixão ao necessitado o honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Por sua malícia, o perverso é excluído; porém o justo até em sua morte mantém a confiança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'No coração do prudente repousa a sabedoria; mas ela será conhecida até entre os tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'A justiça exalta a nação, mas o pecado é a desgraça dos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'O rei se agrada do seu servo prudente; porém ele mostrará seu furor ao causador de vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'A resposta suave desvia o furor, mas a palavra pesada faz a ira aumentar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'A língua dos sábios faz bom uso da sabedoria, mas a boca dos tolos derrama loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Os olhos do SENHOR estão em todo lugar, observando os maus e os bons.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Uma língua sã é árvore de vida; mas a perversidade nela é faz o espírito em pedaços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'O tolo despreza a correção de seu pai; mas aquele que presta atenção à repreensão age com prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Na casa dos justo há um grande tesouro; mas na renda do perverso há perturbação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Os lábios dos sábios derramam conhecimento; mas o coração dos tolos não age assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'O sacrifício dos perversos é abominável ao SENHOR, mas a oração dos justos é seu agrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Abominável ao SENHOR é o caminho do perverso; porém ele ama ao que segue a justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'A correção é ruim para aquele que deixa o caminho; e quem odeia a repreensão morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'O mundo dos mortos e a perdição estão perante o SENHOR; quanto mais os corações dos filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'O zombador não ama aquele que o repreende, nem se chegará aos sábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'O coração alegre anima o rosto, mas pela dor do coração o espírito se abate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'O coração prudente buscará o conhecimento, mas a boca dos tolos se alimentará de loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Todos os dias do oprimido são maus, mas o coração alegre é como um banquete contínuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Melhor é o pouco tendo o temor ao SENHOR, do que um grande tesouro tendo em si inquietação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Melhor é a comida de hortaliças tendo amor, do que a de boi cevado tendo em si ódio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'O homem que fica irritado facilmente gera brigas; mas aquele que demora para se irar apaziguará o confronto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'O caminho do preguiçoso é como uma cerca de espinhos; mas a vereda dos corretos é bem aplanada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'O filho sábio alegra ao pai, mas o homem tolo despreza a sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'A loucura é alegria para aquele que tem falta de prudência; mas o homem de bom entendimento andará corretamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Os planos fracassam quando não há bom conselho; mas com abundância de conselheiros eles se confirmam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'O homem se alegra com a resposta de sua boca; e como é boa a palavra a seu devido tempo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'O caminho da vida leva o prudente para cima, para que se desvie do mundo dos mortos, que está abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'O SENHOR destruirá a casa dos arrogantes, mas confirmará os limites do terreno da viúva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Os pensamentos do mau são abomináveis ao SENHOR, mas ele se agrada das palavras dos puros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Quem pratica a ganância perturba sua própria casa; mas quem odeia subornos viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'O coração do justo pensa bem naquilo que vai responder, mas a boca dos perversos derrama maldades em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Longe está o SENHOR dos perversos, mas ele escuta a oração dos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'A luz dos olhos alegra o coração; a boa notícia fortalece os ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Os ouvidos que escutam a repreensão da vida habitarão entre os sábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Quem rejeita correção menospreza sua própria alma; mas aquele que escuta a repreensão adquire entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'O temor ao SENHOR corrige sabiamente; e antes da honra vem a humildade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Do homem são os planejamentos do coração, mas a reposta da boca vem do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Todos os caminhos do homem são puros aos seus próprios olhos; mas o SENHOR pesa os espíritos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Confia tuas obras ao SENHOR, e teus pensamentos serão firmados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'O SENHOR fez tudo para seu propósito; e até ao perverso para o dia do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'O SENHOR abomina todo orgulhoso de coração; certamente não ficará impune.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Com misericórdia e fidelidade a perversidade é reconciliada; e com o temor ao SENHOR se desvia do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Quando os caminhos do homem são agradáveis ao SENHOR, ele faz até seus inimigos terem paz com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Melhor é o pouco com justiça, do que a abundância de rendas com injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'O coração do homem planeja seu caminho, mas é o SENHOR que dirige seus passos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Nos lábios do rei estão palavras sublimes; sua boca não transgride quando julga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'O peso e a balança justos pertencem ao SENHOR; a ele pertencem todos os pesos da bolsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Os reis abominam fazer perversidade, porque com justiça é que se confirma o trono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Os lábios justos são do agrado dos reis, e eles amam ao que fala palavras direitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'A ira do rei é como mensageiros de morte; mas o homem sábio a apaziguará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'No brilho do rosto do rei há vida; e seu favor é como uma nuvem de chuva tardia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Obter sabedoria é tão melhor do que o ouro! E obter sabedoria é mais excelente do que a prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'A estrada dos corretos se afasta do mal; e guarda sua alma quem vigia seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Antes da destruição vem a arrogância, e antes da queda vem a soberba de espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'É melhor ser humilde de espírito com os mansos, do que repartir despojos com os arrogantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Aquele que pensa prudentemente na palavra encontrará o bem; e quem confia no SENHOR é bem-aventurado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'O sábio de coração será chamado de prudente; e a doçura dos lábios aumentará a instrução.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Manancial de vida é o entendimento, para queles que o possuem; mas a instrução dos tolos é loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'O coração do sábio dá prudência à sua boca; e sobre seus lábios aumentará a instrução.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Favo de mel são as palavras suaves: doces para a alma, e remédio para os ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Há um caminho que parece direito ao homem, porém seu fim são caminhos de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'A alma do trabalhador faz ele trabalhar para si, porque sua boca o obriga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'O homem maligno cava o mal, e em seus lábios há como que um fogo ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'O homem perverso levanta contenda, e o difamador faz até grandes amigos se separarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'O homem violento ilude a seu próximo, e o guia por um caminho que não é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Ele fecha seus olhos para imaginar perversidades; ele aperta os lábios para praticar o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Cabelos grisalhos são uma coroa de honra, caso se encontrem no caminho de justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Melhor é o que demora para se irritar do que o valente; e melhor é aquele que domina seu espírito do que aquele que toma uma cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'A sorte é lançada no colo, mas toda decisão pertence ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Melhor é um pedaço seco de comida com tranquilidade, do que uma casa cheia de carne com briga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'O servo prudente dominará o filho causador de vergonha, e receberá parte da herança entre os irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'O crisol é para a prata, e o forno para o ouro; mas o SENHOR prova os corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'O malfeitor presta atenção ao lábio injusto; o mentiroso inclina os ouvidos à língua maligna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Quem ridiculariza o pobre insulta o seu Criador; aquele que se alegra da calamidade não ficará impune.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'A coroa dos idosos são os filhos de seus filhos; e a glória dos filhos são seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Não é adequado ao tolo falar com elegância; muito menos para o príncipe falar mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'O presente é como uma pedra preciosa aos olhos de seus donos; para onde quer que se voltar, tentará ter algum proveito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Quem perdoa a transgressão busca a amizade; mas quem repete o assunto afasta amigos íntimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'A repreensão entra mais profundamente no prudente do que cem açoites no tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Na verdade quem é mal busca somente a rebeldia; mas o mensageiro cruel será enviado contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'É melhor ao homem encontrar uma ursa roubada de seus filhotes,do que um tolo em sua loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Quanto ao que devolve o mal no lugar do bem, o mal nunca se afastará de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Começar uma briga é como deixar águas rolarem; por isso, abandona a discussão antes que haja irritação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Quem absolve ao perverso e quem condena ao justo, ambos são abomináveis ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Para que serve o dinheiro na mão do tolo, já que ele não tem interesse em obter sabedoria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'O amigo ama em todo tempo, e o irmão nasce para ajudar na angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'O homem imprudente assume compromisso, ficando como fiador de seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Quem ama a briga, ama a transgressão; quem constrói alta sua porta busca ruína.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'O perverso de coração nunca encontrará o bem; e quem distorce as palavras de sua língua cairá no mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Quem gera o louco cria sua própria tristeza; e o pai do imprudente não se alegrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'O coração alegre é um bom remédio, mas o espírito abatido faz os ossos se secarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'O perverso toma o presente do seio, para perverter os caminhos da justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'A sabedoria está diante do rosto do prudente; porém os olhos do tolo estão voltados para os confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'O filho tolo é tristeza para seu pai, e amargura para aquela que o gerou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Também não é bom punir ao justo, nem bater nos príncipes por causa da justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Quem entende o conhecimento guarda suas palavras; e o homem de bom entendimento é de espírito calmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Até o tolo, quando está calado, é considerado como sábio; e quem fecha seus lábios, como de bom senso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Quem se isola busca seu próprio desejo; ele se volta contra toda sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'O tolo não tem prazer no entendimento, mas sim em revelar sua própria opinião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Na vinda do perverso, vem também o desprezo; e com a desonra vem a vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'A boca do homem são como águas profundas; e o manancial de sabedoria como um ribeiro transbordante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Não é bom favorecer ao perverso para prejudicar ao justo num julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Os lábios do tolo entram em briga, e sua boca chama pancadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'A boca do tolo é sua própria destruição, e seus lábios são armadilha para sua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'As palavras do fofoqueiro são como alimentos deliciosos, que descem até o interior do ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'O preguiçoso em fazer sua obra é irmão do causador de prejuízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'O nome do SENHOR é uma torre forte; o justo correrá até ele, e ficará seguro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Os bens do rico são como uma cidade fortificada, e como um muro alto em sua imaginação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Antes da ruína o coração humano é orgulhoso; e antes da honra vem a humildade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Quem responde antes de ouvir age como tolo e causa vergonha para si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'O espírito do homem o sustentará quando doente; mas o espírito abatido, quem o levantará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'O coração do prudente adquire conhecimento; e o ouvido dos sábios busca conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'O presente do homem alarga seu caminho, e o leva perante a face dos grandes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Aquele que primeiro mostra sua causa parece ser justo; mas somente até que outro venha, e o investigue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'O sorteio cessa disputas, e separa poderosos de se confrontarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'O irmão ofendido é mais difícil que uma cidade fortificada; e as brigas são como ferrolhos de uma fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Do fruto da boca do homem seu ventre se fartará; dos produtos de seus lábios se saciará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'A morte e a vida estão no poder da língua; e aquele que a ama comerá do fruto dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Quem encontrou esposa, encontrou o bem; e obteve o favor do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'O pobre fala com súplicas; mas o rico responde com durezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'O homem que tem amigos pode ser prejudicado por eles; porém há um amigo mais chegado que um irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Melhor é o pobre que anda em sua honestidade do que o perverso de lábios e tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'E não é bom a alma sem conhecimento; e quem tem pés apressados comete erros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'A loucura do homem perverte seu caminho; e seu coração se ira contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'A riqueza faz ganhar muitos amigos; mas ao pobre, até seu amigo o abandona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'A falsa testemunha não ficará impune; e quem fala mentiras não escapará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Muitos suplicam perante o príncipe; e todos querem ser amigos daquele que dá presentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Todos os irmãos do pobre o odeiam; ainda mais seus amigos se afastam dele; ele corre atrás deles com palavras, mas eles nada lhe respondem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Quem adquire entendimento ama sua alma; quem guarda a prudência encontrará o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'A falsa testemunha não ficará impune; e quem fala mentiras perecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'O luxo não é adequado ao tolo; muito menos ao servo dominar sobre príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'A prudência do homem retém sua ira; e sua glória é ignorar a ofensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'A fúria do rei é como o rugido de um leão; mas seu favor é como orvalho sobre a erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'O filho tolo é uma desgraça ao seu pai; e brigas da esposa são como uma goteira duradoura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'A casa e as riquezas são a herança dos pais; porém a mulher prudente vem do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'A preguiça faz cair num sono profundo; e a alma desocupada passará fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Quem guarda o mandamento cuida de sua alma; e quem despreza seus caminhos morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Quem faz misericórdia ao pobre empresta ao SENHOR; e ele lhe pagará sua recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Castiga a teu filho enquanto há esperança; mas não levantes tua alma para o matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Aquele que tem grande irá será punido; porque se tu o livrares, terás de fazer o mesmo de novo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Ouve o conselho, e recebe a disciplina; para que sejas sábio nos teus últimos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Há muitos pensamentos no coração do homem; porém o conselho do SENHOR prevalecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'O que se deseja do homem é sua bondade; porém o pobre é melhor do que o homem mentiroso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'O temor ao SENHOR encaminha para a vida; aquele que o tem habitará satisfeito, nem mal algum o visitará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'O preguiçoso põe sua mão no prato, e nem sequer a leva de volta à boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Fere ao zombador, e o ingênuo será precavido; e repreende ao prudente, e ele aprenderá conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Aquele que prejudica ao pai ou afugenta a mãe é filho causador de vergonha e de desgraça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Filho meu, deixa de ouvir a instrução, então te desviarás das palavras de conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'A má testemunha escarnece do juízo; e a boca dos perversos engole injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Julgamentos estão preparados para zombadores, e açoites para as costas dos tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'O vinho é zombador, a bebida forte é causadora de alvoroços; e todo aquele que errar por causa deles não é sábio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'O temor ao rei é como um rugido de leão; e quem se ira contra ele peca contra sua própria alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'É honroso ao homem terminar a disputa; mas todo tolo nela se envolve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'O preguiçoso não lavra no inverno; por isso ele mendigará durante a ceifa, pois nada terá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'O conselho no coração do homem é como águas profundas; mas o homem prudente consegue tirá-lo para fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Muitos homens, cada um deles afirma ter bondade; porém o homem fiel, quem o encontrará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'O justo caminha em sua integridade; bem-aventurados serão seus filhos depois dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'O rei, ao se sentar no trono do juízo, com seus olhos dissipa todo mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Quem poderá dizer: “Purifiquei meu coração; estou limpo de meu pecado”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Dois pesos e duas medidas, ambos são abominação ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Até o jovem é conhecido pelas suas ações, se sua obra for pura e correta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'O ouvido que ouve e o olho que vê, o SENHOR os fez ambos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Não ames ao sono, para que não empobreças; abre teus olhos, e te fartarás de pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Preço ruim, preço ruim, diz o comprador; mas quando vai embora, então se gaba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Há ouro, e muitos rubis; mas os lábios do conhecimento são joia preciosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Toma a roupa daquele que fica por fiador de estranho; toma como penhor daquele que fica por fiador da estranha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'O pão da mentira é agradável ao homem; mas depois sua boca se encherá de pedregulhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Os planos são confirmados por meio do conselho; e com conselhos prudentes faze a guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Quem anda fofocando revela segredos; por isso não te envolvas com aquele que fala demais com seus lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Aquele que amaldiçoar a seu pai ou a sua mãe terá sua lâmpada apagada em trevas profundas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'A herança ganha apressadamente no princípio, seu fim não será abençoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Não digas: Devolverei o mal; Espera pelo SENHOR, e ele te livrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'O SENHOR abomina pesos falsificados; e balanças enganosas não são boas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Os passos do homem pertencem ao SENHOR; como, pois, o homem entenderá seu caminho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Armadilha ao homem é prometer precipitadamente algo como sagrado, e somente depois pensar na seriedade dos votos que fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'O rei sábio espalha os perversos, e os atropela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'O espírito humano é uma lâmpada do SENHOR, que examina todo o interior do ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'A bondade e a fidelidade protegem o rei; e com bondade seu trono é sustentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'A beleza dos jovens é sua força; e a honra dos velhos é seus cabelos brancos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Os golpes das feridas purificam os maus; como também as pancadas no interior do corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Como ribeiros de águas é o coração do rei na mão do SENHOR, ele o conduz para onde quer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Todo caminho do homem é correto aos seus próprios olhos; mas o SENHOR pesa os corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Praticar justiça e juízo é mais aceitável ao SENHOR do que sacrifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Olhos orgulhosos e coração arrogante: a lavoura dos perversos é pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Os planos de quem trabalha com empenho somente levam à abundância; mas os de todo apressado somente à pobreza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Trabalhar para obter tesouros com língua mentirosa é algo inútil e fácil de se perder; os que assim fazem buscam a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'A violência praticada pelos perversos os destruirá, porque se negam a fazer o que é justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'O caminho do homem transgressor é problemático; porém a obra do puro é correta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'É melhor morar num canto do terraço do que numa casa espaçosa com uma mulher briguenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'A alma do perverso deseja o mal; seu próximo não lhe agrada em seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Castigando ao zombador, o ingênuo se torna sábio; e ensinando ao sábio, ele ganha conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'O justo considera prudentemente a casa do perverso; ele transtorna os perversos para a ruína.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Quem tapa seu ouvido ao clamor do pobre, ele também clamará, mas não será ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'O presente em segredo extingue a ira; e a dádiva no colo acalma o forte furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Alegria para o justo é fazer justiça; mas isso é pavor para os que praticam maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'O homem que se afasta do caminho do entendimento repousará no ajuntamento dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Quem ama o prazer sofrerá necessidade; aquele que ama o vinho e o azeite nunca enriquecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'O resgate em troca do justo é o perverso; e no lugar do reto fica o transgressor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'É melhor morar em terra deserta do que com uma mulher briguenta e que se irrita facilmente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Há tesouro desejável e azeite na casa do sábio; mas o homem tolo é devorador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Quem segue a justiça e a bondade achará vida, justiça e honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'O sábio passa por cima da cidade dos fortes e derruba a fortaleza em que confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Quem guarda sua boca e sua língua guarda sua alma de angústias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, '“Zombador” é o nome do arrogante e orgulhoso; ele trata os outros com uma arrogância irritante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'O desejo do preguiçoso o matará, porque suas mãos se recusam a trabalhar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Ele fica desejando suas cobiças o dia todo; mas o justo dá, e não deixa de dar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'O sacrifício dos perversos é abominável; quanto mais quando a oferta é feita com má intenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'A testemunha mentirosa perecerá; porém o homem que ouve a verdade falará com sucesso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'O homem perverso endurece seu rosto, mas o correto confirma o seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Não há sabedoria, nem entendimento, nem conselho contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'O cavalo é preparado para o dia da batalha, mas a vitória vem do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'É preferível ter um bom nome do que muitas riquezas; e ser favorecido é melhor que a prata e o o ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'O rico e o pobre se encontram; todos eles foram feitos pelo SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'O prudente vê o mal, e se esconde; mas os ingênuos passam e sofrem as consequências.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'A recompensa da humildade e do temor ao SENHOR são riquezas, honra, e vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Há espinhos e ciladas no caminho do perverso; quem cuida de sua alma deve ficar longe de tal caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Instrui ao menino em seu caminho, e até quando envelhecer, não se desviará dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'O rico domina sobre os pobres, e quem toma emprestado é servo daquele que empresta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Aquele que semeia perversidade colherá sofrimento; e a vara de sua ira se acabará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Quem tem olhos bondosos será abençoado, porque deu de seu pão ao pobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Expulsa ao zombador, e a briga terminará; cessará a disputa e a vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Quem ama a pureza do coração fala graciosamente com os lábios, e o rei será seu amigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Os olhos do SENHOR protegem o conhecimento; porém ele transtornará as palavras do enganador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'O preguiçoso diz: Há um leão lá fora! Ele me matará nas ruas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'A boca da mulher pervertida é uma cova profunda; aquele contra quem o SENHOR se irar cairá nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'A tolice está amarrada ao coração do menino; mas a vara da correção a mandará para longe dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Aquele que oprime ao pobre para proveito próprio e aquele que dá suborno ao rico certamente empobrecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Inclina o teu ouvido e escuta as palavras dos sábios; dispõe teu coração ao meu conhecimento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'porque é agradável que as guardes dentro de ti, e estejam prontas para os teus lábios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'para que tua confiança esteja no SENHOR, eu as ensino a ti hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Por acaso não te escrevi excelentes coisas sobre o conselho e o conhecimento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'para te ensinar a certeza das palavras da verdade, para que possas responder palavras de verdade aos que te enviarem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Não roubes ao pobre, porque ele é pobre; nem oprimas ao aflito junto à porta do julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Porque o SENHOR defenderá a causa deles em juízo, e quanto aos que os roubam, ele lhes roubará a alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Não seja companheiro de quem se irrita facilmente, nem andes com o homem furioso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Para que não aprendas o caminho dele, e te ponhas em armadilhas para tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Não estejas entre os que se comprometem em acordos com as mãos, ou os que ficam por fiadores de dívidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Se não tens como pagar, por que razão tirariam tua cama debaixo de ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Não mudes os limites antigos que teus pais fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Viste um homem habilidoso em sua obra? Perante a face dos reis ele será posto; ele não será posto diante de pessoas sem honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Quando te sentares para comer com algum dominador, presta muita atenção para o que estiver diante de ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'E põe uma faca à tua garganta, se tiveres muito apetite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Não desejes as comidas gostosas dele, porque são pão de mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Não trabalhes exaustivamente para ser rico; modera-te por meio de tua prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Porás teus olhos fixos sobre aquilo que é nada? Porque certamente se fará asas, e voará ao céu como uma águia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Não comas o pão de quem tem olho maligno, nem cobices suas comidas gostosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Porque ele calcula seus gastos consigo mesmo. Assim ele dirá: Come e bebe; Mas o coração dele não está contigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Vomitarias o pedaço que comeste, e perderias tuas palavras agradáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Não fales aos ouvidos do tolo, porque ele desprezará a prudência de tuas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Não mudes os limites antigos, nem ultrapasses as propriedades dos órfãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Porque o Defensor deles é poderoso; ele disputará a causa deles contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Aplica teu coração à disciplina, e teus ouvidos às palavras de conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Não retires a disciplina do jovem; quando o bateres com a vara, nem por isso morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Tu o baterás com a vara, e livrarás a alma dele do mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Meu filho, se teu coração for sábio, meu coração se alegrará, e eu também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Meu interior saltará de alegria quando teus lábios falarem coisas corretas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Teu coração não inveje aos pecadores; porém permanece no temor ao SENHOR o dia todo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Porque certamente há um bom futuro para ti, e tua expectativa não será cortada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Ouve, filho meu, e sê sábio; e conduz teu coração no caminho correto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Não esteja entre os beberrões de vinho, nem entre os comilões de carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Porque o beberrão e o comilão empobrecerão; e a sonolência os faz vestir trapos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Ouve a teu pai, que te gerou; e não desprezes a tua mãe, quando ela envelhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Compra a verdade, e não a vendas; faze o mesmo com a sabedoria, a disciplina e a prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'O pai do justo muito se alegrará; aquele que gerar o sábio se encherá de alegria por causa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Teu pai e tua mãe se alegrarão; aquela te te gerou se encherá de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Meu filho, dá para mim teu coração, e que teus olhos prestem atenção em meus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Porque a prostituta é como uma cova profunda, e a estranha como um poço estreito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Também ela fica espreitando como um ladrão, e acrescenta transgressores entre os homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'De quem são os ais? De quem são os sofrimentos? De quem são as lutas? De quem são as queixas? De quem são as feridas desnecessárias? De quem são os olhos vermelhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'São daqueles que gastam tempo junto ao vinho, daqueles que andam em busca da bebida misturada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Não prestes atenção ao vinho quando se mostra vermelho, quando brilha no copo e escorre suavemente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Pois seu fim é como mordida de cobra, e picará como uma víbora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Teus olhos verão coisas estranhas, e teu coração falará perversidades;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'E serás como o que dorme no meio do mar, e como o que dorme no topo do mastro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'E dirás: Espancaram-me, mas não senti dor; bateram em mim, mas não senti; quando virei a despertar? Vou buscar mais uma bebida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Não tenhas inveja dos homens malignos, nem desejes estar com eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Porque o coração deles imagina destruição, e os lábios deles falam de opressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Pela sabedoria a casa é edificada, e pelo entendimento ela fica firme;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'E pelo conhecimento os cômodos se encherão de riquezas preciosas e agradáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'O homem sábio é poderoso; e o homem que tem conhecimento aumenta sua força;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Porque com conselhos prudentes farás tua guerra; e a vitória é alcançada pela abundância de conselheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'A sabedoria é alta demais para o tolo; na porta do julgamento ele não abre sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Quem planeja fazer o mal será chamado de vilão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'O pensamento do tolo é pecado; e o zombador é abominável aos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Se te mostrares fraco no dia da angústia, como é pouca tua força!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Livra os que estão tomados para a morte, os que estão sendo levados para serem mortos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Pois se tu disseres: Eis que não sabíamos,Por acaso aquele que pesa os corações não saberá? Aquele que guarda tua alma não conhecerá? Ele retribuirá ao homem conforme sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Come mel, meu filho, porque é bom; e o favo de mel é doce ao teu paladar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Assim será o conhecimento da sabedoria para tua alma; se a encontrares haverá recompensa para ti; e tua esperança não será cortada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Tu, perverso, não espies a habitação do justo, nem assoles seu quarto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Porque o justo cai sete vezes, e se levanta; mas os perversos tropeçam no mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Quando teu inimigo cair, não te alegres; nem teu coração fique contente quando ele tropeçar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Para que não aconteça de o SENHOR veja, e o desagrade, e desvie dele sua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Não te irrites com os malfeitores, nem tenhas inveja dos perversos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Porque o maligno não terá um bom futuro; a lâmpada dos perversos se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Meu filho, teme ao SENHRO e ao rei; e não te envolvas com os rebeldes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Porque a destruição deles se levantará de repente; e quem sabe que ruína eles terão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Estes provérbios também são para os sábios: fazer acepção de pessoas num julgamento não é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Aquele que disser ao ímpio: Tu és justo,Os povos o amaldiçoarão, as nações o detestarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Mas para aqueles que o repreenderem, haverá coisas boas; e sobre eles virá uma boa bênção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Quem responde palavras corretas é como se estivesse beijando com os lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Prepara tua obra de fora, e a deixa pronta no campo; somente depois edifica tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Não sejas testemunha contra teu próximo sem causa; por que enganarias com teus lábios?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Não digas: Assim como ele fez a mim, assim também farei a ele; pagarei a cada um conforme sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Passei junto ao campo do preguiçoso, e junto à vinha do homem sem juízo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'E eis que ela estava toda cheia de espinheiros, e sua superfície coberta de urtigas; e sua cerca de pedra estava derrubada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Quando eu a vi, aprendi em meu coração, e ao olhá -la,recebi instrução:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Um pouco de sono, cochilando um pouco, cruzando as mãos por um pouco de tempo deitado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'E assim tua pobreza virá como um assaltante; tua necessidade chegará como um homem armado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Estes também são provérbios de Salomão, que foram copiados pelos homens de Ezequias, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'É glória de Deus encobrir alguma coisa; mas a glória dos Reis é investigá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Para a altura dos céus, para a profundeza da terra, assim como para o coração dos reis, não há como serem investigados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Tira as escórias da prata, e sairá um vaso para o fundidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Tira o perverso de diante do rei, e seu trono se firmará com justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Não honres a ti mesmo perante o rei, nem te ponhas no lugar dos grandes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Porque é melhor que te digam: Sobe aqui;Do que te rebaixem perante a face do príncipe, a quem teus olhos viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Não sejas apressado para entrar numa disputa; senão, o que farás se no fim teu próximo te envergonhar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Disputa tua causa com teu próximo, mas não reveles segredo de outra pessoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Para que não te envergonhe aquele que ouvir; pois tua má fama não pode ser desfeita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'A palavra dita em tempo apropriado é como maçãs de ouro em bandejas de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'O sábio que repreende junto a um ouvido disposto a escutar é como pendentes de ouro e ornamentos de ouro refinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Como frio de neve no tempo da colheita, assim é o mensageiro fiel para aqueles que o enviam; porque ele refresca a alma de seus senhores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Como nuvens e ventos que não trazem chuva, assim é o homem que se orgulha de falsos presentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Com paciência para não se irar é que se convence um líder; e a língua suave quebra ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Achaste mel? Come o que te for suficiente; para que não venhas a ficar cheio demais, e vomites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Não exagere teus pés na casa de teu próximo, para que ele não se canse de ti, e te odeie.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Martelo, espada e flecha afiada é o homem que fala falso testemunho contra seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Confiar num infiel no tempo de angústia é como um dente quebrado ou um pé sem firmeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Quem canta canções ao coração aflito é como aquele que tira a roupa num dia frio, ou como vinagre sobre salitre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Se aquele que te odeia tiver fome, dá-lhe pão para comer; e se tiver sede, dá-lhe água para beber;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Porque assim amontoarás brasas sobre a cabeça dele, e o SENHOR te recompensará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'O vento norte traz a chuva; assim como a língua caluniadora traz a ira no rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'É melhor morar num canto do terraço do que com uma mulher briguenta numa casa espaçosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Como água refrescante para a alma cansada, assim são boas notícias de uma terra distante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'O justo que se deixa levar pelo perverso é como uma fonte turva e um manancial poluído.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Comer muito mel não é bom; assim como buscar muita glória para si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'O homem que não pode conter seu espírito é como uma cidade derrubada sem muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Assim como a neve no verão, como a chuva na colheita, assim também não convém a honra para o tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Como um pássaro a vaguear, como a andorinha a voar, assim também a maldição não virá sem causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Açoite para o cavalo, cabresto para o asno; e vara para as costas dos tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Não respondas ao tolo conforme sua loucura; para que não te faças semelhante a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Responde ao tolo conforme sua loucura, para que ele não seja sábio aos seus próprios olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Quem manda mensagens pelas mãos do tolo é como quem corta os pés e bebe violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Assim como não funcionam as pernas do aleijado, assim também é o provérbio na boca dos tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Dar honra ao tolo é como amarrar uma pedra numa funda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Como espinho na mão do bêbado, assim é o provérbio na boca dos tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Como um flecheiro que atira para todo lado, assim é aquele que contrata um tolo ou que contrata alguém que vai passando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Como um cão que volta a seu vômito, assim é o tolo que repete sua loucura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Viste algum homem sábio aos seus próprios olhos? Mais esperança há para o tolo do que para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'O preguiçoso diz: Há uma fera no caminho; há um leão nas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Como a porta se vira em torno de suas dobradiças, assim o preguiçoso se vira em sua cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'O preguiçoso põe sua mão no prato, e acha cansativo demais trazê-la de volta a sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'O preguiçoso se acha mais sábio aos próprios olhos do que sete que respondem com prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Aquele que, enquanto está passando, se envolve em briga que não é sua, é como o que pega um cão pelas orelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Como o louco que lança faíscas, flechas e coisas mortíferas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Assim é o homem que engana a seu próximo, e diz: Não estava eu só brincando?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Sem lenha, o fogo se apaga; e sem fofoqueiro, a briga termina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'O carvão é para as brasas, e a lenha para o fogo; e o homem difamador para acender brigas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'As palavras do fofoqueiro são como alimentos deliciosos, que descem ao interior do ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Como um vaso de fundição coberto de restos de prata, assim são os lábios inflamados e o coração maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Aquele que odeia dissimula em seus lábios, mas seu interior abriga o engano;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Quando ele te falar agradavelmente com sua voz, não acredites nele; porque há sete abominações em seu coração;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Cujo ódio está encoberto pelo engano; sua maldade será descoberta na congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Quem cava uma cova, nela cairá; e quem rola uma pedra, esta voltará sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'A língua falsa odeia aos que ela atormenta; e a boca lisonjeira opera ruína.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Não te orgulhes do dia de amanhã; porque não sabes o que o dia trará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Que o estranho te louve, e não tua própria boca; o estrangeiro, e não teus próprios lábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'A pedra é pesada, e a areia tem seu peso; mas a provocação do tolo é mais pesada do que estas ambas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'O furor é cruel, e a ira impetuosa; mas quem resistirá firme perante à inveja?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Melhor é a repreensão clara do que o amor escondido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Fiéis são as feridas feitas por um amigo, mas os beijos de um inimigo são enganosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'A alma saciada rejeita o favo de mel; mas para a alma faminta, toda coisa amarga é doce.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Como a ave, que vagueia de seu ninho, assim é o homem que anda vagueando de seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'O óleo e o perfume alegram ao coração; assim é a doçura de um amigo com um conselho sincero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Não abandones o teu amigo, nem o amigo de teu pai; nem entres na casa de teu irmão no dia de tua adversidade; melhor é o vizinho que está perto do que o irmão que está longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Sê sábio, meu filho, e alegra meu coração; para que eu tenha algo a responder para aquele que me desprezar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'O prudente vê o mal, e se esconde; mas os ingênuos passam adiante, e sofrem as consequências.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Toma a roupa daquele que fica por fiador de estranho; toma penhor daquele que fica por fiador da estranha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Aquele que bendiz ao seu amigo em alta voz durante a madrugada lhe será considerado como maldição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'A mulher briguenta é semelhante a uma goteira contínua em tempo de grande chuva;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Tentar contê-la é como tentar conter o vento, ou impedir que o óleo escorra de sua mão direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'O ferro é afiado com ferro; assim também o homem afia o rosto de seu amigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Aquele que guarda a figueira comerá de seu fruto; e o que dá atenção ao seu senhor será honrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Assim como a água reflete o rosto, assim também o coração reflete o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'O mundo dos mortos e a destruição nunca estão fartos; assim também os olhos do homem nunca estão satisfeitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Como o crisol é para a prata, e o forno para o ouro, assim o homem é provado pelos louvores que lhe dizem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Ainda que esmagues ao tolo em um pilão junto com os grãos, ainda assim sua loucura não se separaria dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Procura conhecer a condição de tuas ovelhas; põe teu coração sobre o gado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'porque o tesouro não dura para sempre; nem uma coroa dura de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Quando a erva aparecer, e surgirem a folhagem, e se juntarem as ervas dos montes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Os cordeiros serão para tuas roupas, e os bodes para o preço do campo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'E o leite das cabras será o suficiente para tua alimentação, para a alimentação de tua casa, e para o sustento de tuas servas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Os perversos fogem mesmo quando não há quem os persiga, mas os justos são confiantes como um leão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Pela rebelião numa terra, seus governantes são muitos; mas por meio de um homem prudente e conhecedor seu governo permanecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'O homem pobre que oprime aos necessitados é como uma chuva devastadora que causa falta de pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Os que abandonam a lei louvam ao perverso; porém os que guardam a lei lutarão contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Os homens maus não entendem a justiça; mas os que buscam ao SENHOR entendem tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Melhor é o pobre que anda em sua honestidade do que o perverso de caminhos, ainda que seja rico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'O que guarda a lei é um filho prudente, mas o companheiro de comilões envergonha a seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Aquele que aumenta seus bens por meio de juros e lucros desonestos está juntando para o que se compadece dos pobres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Aquele que desvia seus ouvidos de ouvir a lei, até sua oração será abominável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Aquele que faz as pessoas corretas errarem em direção a um mau caminho, ele mesmo cairá em sua cova; mas os que não tiverem pecado herdarão o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'O homem rico é sábio aos seus próprios olhos; mas o pobre prudente o examina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Quando os justos estão contentes, muita é a alegria; mas quando os perversos se levantam, os homens se escondem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Quem encobre suas transgressões nunca prosperará, mas aquele que as confessa e as abandona alcançará misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Bem-aventurado o homem que sempre mantém seu temor; mas aquele que endurece seu coração cairá no mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Leão rugidor e urso faminto é o governante perverso sobre um povo pobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'O príncipe que tem falta de entendimento aumenta as opressões; mas aquele que odeia o lucro desonesto prolongará seus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'O homem atormentado pelo sangue de alguma alma fugirá até a cova; ninguém o detenha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Aquele que anda sinceramente será salvo; mas o que se desvia em seus caminhos cairá de uma só vez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Aquele que lavrar sua terra terá fartura de pão; mas o que segue coisas inúteis terá fartura de pobreza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'O homem fiel terá muitas bênçãos; mas o que se apressa para enriquecer não ficará impune.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Fazer acepção de pessoas não é bom; porque até por um pedaço de pão o homem pode transgredir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Quem tem pressa para ter riquezas é um homem de olho mau; e ele não sabe que a miséria virá sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Aquele que repreende ao homem obterá mais favor depois do que aquele que lisonjeia com a língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Aquele que furta seu pai ou sua mãe e diz: Não é pecado,É companheiro do homem destruidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Quem tem alma orgulhosa levanta brigas; mas aquele que confia no SENHOR prosperará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Aquele que confia em seu próprio coração é tolo; mas o que anda em sabedoria escapará em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Quem dá ao pobre não terá falta; mas o que esconde seus olhos terá muitas maldições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Quando os perversos ganham poder, os homens se escondem; mas quando perecem, os justos se multiplicam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'O homem que age com teimosia, mesmo depois de muitas repreensões, será tão destruído que não terá mais cura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Quando os justos se engrandecem, o povo se alegra; mas quando o perverso domina, o povo geme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'O homem que ama a sabedoria alegra a seu pai; mas o companheiro de prostitutas gasta os bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'O rei por meio da justiça firma a terra; mas o amigo de subornos a transtorna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'O homem que lisonjeia a seu próximo arma uma rede para seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Na transgressão do homem mau há uma armadilha; mas o justo se alegra e se enche de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'O justo considera a causa judicial dos pobres; mas o perverso não entende este conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Homens zombadores trazem confusão a cidade; mas os sábios desviam a ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'O homem sábio que disputa no julgamento contra um tolo, mesmo se perturbado ou rindo, não terá descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Homens sanguinários odeiam o honesto; mas os corretos procuram o seu bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'O louco mostra todo o seu ímpeto; mas o sábio o mantém sob controle.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'O governante que dá atenção a palavras mentirosas, todos os seus servos serão perversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'O pobre e o enganador se encontram: o SENHOR ilumina aos olhos de ambos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'O rei que julga aos pobres por meio da verdade, seu trono se firmará para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'A vara e a repreensão dão sabedoria; mas o rapaz deixado solto envergonha a sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Quando os perversos se multiplicam, multiplicam-se as transgressões; mas os justos verão sua queda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Castiga a teu filho, e ele te fará descansar, e dará prazeres à tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Não havendo visão profética, o povo fica confuso; porém o que guarda a lei, ele é bem-aventurado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'O servo não será corrigido por meio de palavras; porque ainda que entenda, mesmo assim ele não responderá corretamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Viste um homem precipitado em suas palavras? Mais esperança há para um tolo do que para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Aquele que mima a seu servo desde a infância, por fim ele quererá ser seu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'O homem que se irrita facilmente levanta brigas; e o furioso multiplica as transgressões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'A arrogância do homem o abaterá; mas o humilde de espírito obterá honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Aquele que reparte com o ladrão odeia sua própria alma; ele ouve maldições e não o denuncia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'O temor do homem arma ciladas; mas o que confia no senhor ficará em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Muitos buscam a face do governante; mas o julgamento de cada um vem do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'O justos odeiam ao homem perverso; e o injusto odeia aos que andam no caminho correto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Palavras de Agur, filho de Jaque, o de fala solene; Este homem diz a Itiel; a Itiel e a Ucal:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Certamente eu sou o mais bruto dos homens, e não tenho entendimento humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Não aprendi sabedoria, nem tenho conhecimento do Santo Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Quem subiu ao céu, e desceu? Quem juntou os ventos com suas mãos? Quem amarrou as águas numa capa? Quem estabeleceu todos os limites da terra? Qual é o seu nome? e qual é o nome de seu filho, se tu o sabes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Toda palavra de Deus é pura; é escudo para os que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Nada acrescentes às suas palavras, para que ele não te repreenda, e sejas mostrado como mentiroso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Duas coisas eu te pedi; não as negues a mim antes que eu morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Afasta de mim a inutilidade e palavra mentirosa; e não me dês nem pobreza nem riqueza, mantém-me com o pão que me for necessário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Para que não aconteça de eu ficar farto e te negar, dizendo: Quem é o SENHOR?Nem também que eu empobreça, e venha a furtar, e desonre o nome do meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Não difames do servo ao seu senhor, para que ele não te amaldiçoe e fiques culpado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Há gente que amaldiçoa a seu pai e não bendiz à sua mãe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Há gente que é pura aos seus próprios olhos, mas que não foi lavada de sua imundície;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Há gente cujos olhos são arrogantes, e cujas sobrancelhas são levantadas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Há gente cujos dentes são espadas, e cujos queixos são facas, para devorarem aos aflitos da terra aos aflitos, e aos necessitados dentre os homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'A sanguessuga tem duas filhas: “Dá” e “Dá”; estas três coisas nunca se fartam, e quatro nunca dizem “É o suficiente”:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'O mundo dos mortos, o ventre feminino estéril, a terra que não se farta de água, e o fogo que nunca diz estar satisfeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Os olhos que zombam do pai ou desprezam obedecer à mãe, os corvos do riacho os arrancarão, e os filhotes de abutre os comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Estas três coisas me maravilham, e quatro que não entendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'O caminho da águia no céu, o caminho da serpente na rocha, o caminho do navio no meio do mar, e o caminho do homem com uma moça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Assim é o caminho da mulher adúltera: ela come, limpa sua boca, e diz: Não fiz mal algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Por três coisas a terra se alvoroça, e por quatro que não pode suportar:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Pelo servo que governa como rei; pelo tolo que se enche de comida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Pela mulher odiada, quando se casa; e pela serva quando toma o lugar de sua senhora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Estas quatro coisas são pequenas sobre a terra, porém muito sábias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'As formigas não são criaturas fortes, mas no verão preparam sua comida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Os roedores são um “povo” fraco, mas fazem suas casas nas rochas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Os gafanhotos não têm rei; mas todos saem em bandos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'As lagartixas podem ser pegas com as mãos, e mesmo assim estão nos palácios dos reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Estes três tem um bom andar, e quatro que se movem muito bem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'O leão, forte entre os animais, que não foge de ninguém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'O galo, o bode, e o rei com seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Se agiste como tolo, exaltando-te, e se planejaste o mal, põe tua mão sobre a boca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Porque como o forçar do leite produz manteiga, e o forçar do nariz produz sangue, assim também o forçar da ira produz briga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Palavras do rei Lemuel, a profecia que sua mãe o ensinava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'O que posso te dizer,meu filho, ó filho do meu ventre? O que te direi,filho de minhas promessas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Não dês tua força às mulheres, nem teus caminhos para coisas que destroem reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Lemuel, não convém aos reis beber vinho; nem aos príncipes desejar bebida alcoólica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Para não acontecer de que bebam, e se esqueçam da lei, e pervertam o direito de todos os aflitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dai bebida alcoólica aos que estão a ponto de morrer, e vinho que têm amargura na alma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Para que bebam, e se esqueçam de sua pobreza, e não se lembrem mais de sua miséria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Abre tua boca no lugar do mudo pela causa judicial de todos os que estão morrendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Abre tua boca, julga corretamente, e faze justiça aos oprimidos e necessitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Mulher virtuosa, quem a encontrará? Pois seu valor é muito maior que o de rubis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'O coração de seu marido confia nela, e ele não terá falta de bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Ela lhe faz bem, e não o mal, todos os dias de sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Ela busca lã e linho, e com prazer trabalha com suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Ela é como um navio mercante; de longe traz a sua comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Ainda de noite ela se levanta, e dá alimento a sua casa; e ordens às suas servas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Ela avalia um campo, e o compra; do fruto de suas mãos planta uma vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Ela prepara seus lombos com vigor, e fortalece seus braços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Ela prova que suas mercadorias são boas, e sua lâmpada não se apaga de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Ela estende suas mãos ao rolo de linha, e com suas mãos prepara os fios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Ela estende sua mão ao aflito, e estica os braços aos necessitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ela não terá medo da neve por sua casa, pois todos os de sua casa estão agasalhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Ela faz cobertas para sua cama; de linho fino e de púrpura é o seu vestido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Seu marido é famoso às portas da cidade,quando ele se senta com os anciãos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Ela faz panos de linho fino, e os vende; e fornece cintos aos comerciantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Força e glória são suas roupas, e ela sorri pelo seu futuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Ela abre sua boca com sabedoria; e o ensinamento bondoso está em sua língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Ela presta atenção aos rumos de sua casa, e não come pão da preguiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Seus filhos se levantam e a chamam de bem-aventurada; seu marido também a elogia, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Muitas mulheres agem com virtude, mas tu és melhor que todas elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'A beleza é enganosa, e a formosura é passageira; mas a mulher que teme ao SENHOR, essa será louvada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dai a ela conforme o fruto de suas mãos, e que suas obras a louvem às portas da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Palavras do Pregador, filho de Davi, rei em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Futilidade das futilidades! - diz o Pregador - futilidade das futilidades! Tudo é fútil!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Que proveito tem o homem de todo o seu trabalho que ele trabalha abaixo do sol?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Geração vai, e geração vem; porém a terra permanece para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'O sol nasce, e o sol se põe; e se apressa ao seu lugar onde nasceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'O vento vai ao sul, e rodeia para o norte; continuamente o vento vai rodeando e voltando aos lugares onde circulou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Todos os rios vão para o mar, e contudo o mar não se enche; ao lugar onde os ribeiros correm, para ali eles voltam a correr.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Todas estas coisas são tão cansativas, que ninguém consegue descrever; os olhos não ficam satisfeitos de ver, nem os ouvidos se enchem de ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'O que foi, isso será; e o que se fez, isso será feito; de modo que nada há de novo abaixo do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Existe algo que se possa dizer: Vê isto, que é novo?Isso já existia nos tempos passados, que foram antes de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Não há lembrança das coisas que já aconteceram; e das coisas que vão acontecer, também delas não haverá lembrança entre aqueles que vierem depois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Eu o Pregador, me tornei rei sobre Israel em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'E dei meu coração a investigar e pesquisar com sabedoria sobre tudo o que acontece abaixo do céu; esta cansativa ocupação Deus deu aos filhos dos homens, para que nela fossem forçados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Vi todas as obras que são feitas abaixo do sol, e eis que tudo é futilidade e aflição de espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'O que é torto não pode ser endireitado; o que está em falta não pode ser contado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Eu falei ao meu coração, dizendo: Eis que eu me tornei grande, e aumentei em sabedoria, sobre todos os que tinham sido antes de mim em Jerusalém; e meu coração experimentou uma abundância de sabedoria e conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'E dei meu coração para entender sabedoria, e para entender loucuras e tolices; e percebi que também isto era aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Porque na muita sabedoria há muito aborrecimento, e aquele que aumenta em conhecimento aumenta em angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Disse eu em meu coração: Vamos! Eu te provarei com alegria, por isso dá atenção ao que é bom! Porém eis que isto também era futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Eu disse ao riso: Estás doido; e à alegria: De que esta serve?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Decidi como experiência entregar minha carne ao vinho (guiando porém meu coração com sabedoria) e praticar a loucura, para eu ver o que era melhor aos filhos dos homens fazerem abaixo do céu durante os dias de suas vidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Fiz para mim obras grandiosas; construí casas para mim; plantei vinhas para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Fiz para mim pomares e jardins; e plantei neles árvores de toda espécie de frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Fiz para mim tanques de águas, para regar com eles o bosque em que se plantavam as árvores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Adquiri escravos e escravas, e tive escravos nascidos em casa; também tive grande rebanho de vacas e ovelhas, mais do que todos os que houve antes de mim em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Também juntei para mim prata, ouro, e tesouros de reis e de províncias; reservei para mim cantores e cantoras, e dos prazeres dos filhos dos homens: várias mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Então me engrandeci e aumentei, mais do que todos quantos houve antes de mim em Jerusalém; além disto minha sabedoria ficou comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'E tudo quanto meus olhos desejaram, eu não lhes neguei; nem privei meu coração de alegria alguma, pois meu coração se alegrou de todo o meu trabalho; e esta foi minha parte que obtive de todo o meu trabalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'E eu olhei para todas as obras que minhas mãos fizeram, como também para o trabalho ao qual me dispus a trabalhar; e eis que tudo era fútil como perseguir o vento, e que não havia proveito algum abaixo do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Então passei a observar a sabedoria, as loucuras e a tolice; porque o que o homem pode fazer depois do rei, que já não tenha sido feito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Então eu vi que a sabedoria é melhor do que a tolice, assim como a luz é melhor do que as trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Os olhos do sábio estão em sua cabeça, mas o tolo anda em trevas; então eu também entendi que o mesmo futuro acontece a todos eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Por isso eu disse em meu coração: Assim como acontece ao tolo, também acontecerá a mim; por que então eu me tornei mais sábio? Então disse em meu coração que isto também era inútil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Porque não haverá lembrança para sempre, nem do sábio, nem do tolo; porque de tudo quanto agora há, nos dias futuros será esquecido; e o sábio morre assim como o tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Por isso detestei a vida, porque a obra que é feita abaixo do sol me faz sofrer; pois tudo é fútil como perseguir o vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Eu também detestei todo o meu trabalho em que trabalhei abaixo do sol, porque o deixarei ao homem que virá depois de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Pois quem sabe se ele será sábio ou tolo? Contudo ele terá controle de todo o meu trabalho em que trabalhei, e que sabiamente conduzi abaixo do sol; também isso é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Por isso eu fiz meu coração perder a esperança de todo o meu trabalho em que trabalhei abaixo do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Porque há um tipo de homem que trabalha com sabedoria, conhecimento e habilidade; porém deixará tudo como herança a um outro homem que não trabalhou naquilo; também isto é fútil e muito desagradável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Pois que proveito o homem tem por todo o seu trabalho e cansaço de seu coração em que ele trabalha abaixo do sol?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Porque todos os seus dias são dores, e aflição é sua rotina; até de noite seu coração não descansa; também isto é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Não há nada melhor ao homem do que comer, beber, e fazer sua alma se alegrar de seu trabalho; eu também vi que isto vem da mão de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, '(Pois quem melhor comeria ou teria pressa, a não ser eu mesmo?)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Porque ao homem bom perante sua face, Deus dá sabedoria, conhecimento e alegria; porém ao pecador ele dá trabalho cansativo, para juntar e recolher, para o dar ao bom diante da sua face; também isto é fútil como perseguir o vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Para todas as coisas há um tempo determinado, e todo propósito abaixo do céu tem seu tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Tempo de nascer e tempo de morrer; tempo de plantar e tempo de arrancar o que foi plantado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Tempo de matar e tempo de curar; tempo de derrubar e tempo de construir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Tempo de chorar e tempo de rir; tempo de lamentar, e tempo de saltar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Tempo de espalhar pedras e tempo de juntar pedras; tempo de abraçar e tempo de evitar abraçar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Tempo de buscar e tempo de perder; tempo de guardar e tempo de jogar fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Tempo de rasgar e tempo de costurar; tempo de ficar calado e tempo de falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Tempo de amar e tempo de odiar; tempo de guerra e tempo de paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Que proveito tem o trabalhador naquilo em que ele trabalha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Tenho visto a ocupação que Deus deu aos filhos dos homens, para com ela os manter ocupados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Tudo ele fez belo ao seu tempo; também pôs a sensação de eternidade no coração deles, sem que o homem consiga entender a obra que Deus fez, desde o princípio até o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Tenho percebido que não há coisa melhor para eles do que se alegrarem e fazerem o bem em suas vidas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'E também que todo homem coma, beba e fique contente com todo o seu trabalho; isto é um presente de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Eu sei que tudo quanto Deus faz durará para sempre; a isso nada será acrescentado e nada será diminuído; e Deus faz assim para que haja temor perante sua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'O que tem sido agora, já foi antes; e o que vier a ser também já foi; Deus busca de volta o que foi passado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Vi mais abaixo do sol: que no lugar do juízo havia ali perversidade; e que no lugar da justiça havia ali perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Eu disse em meu coração: Deus julgará ao justo e ao perverso, porque ali há tempo para todo propósito e para toda obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Eu disse em meu coração quanto aos filhos dos homens, que Deus lhes provaria, para lhes mostrar que eles são como animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Porque o que acontece aos filhos dos homens, isso mesmo também acontece aos animais; o mesmo acontece a eles todos; assim como um morre, assim também morre o outro; e todos tem uma mesma respiração; e a vantagem dos homens sobre os animais é nenhuma, pois todos são fúteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Todos vão a um mesmo lugar; todos vieram do pó da terra, e todos voltarão ao pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Quem tem certeza de que o fôlego de vida dos homens sobe para cima, e que o fôlego de vida dos animais desce para debaixo da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Por isso tenho visto que não há coisa melhor do que o homem se alegrar de suas obras, porque essa é a parte que lhe pertence; pois quem pode levá-lo a ver o que será depois de sua morte?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Depois me virei, e observei todas as opressões que são feitas abaixo do sol; e eis que vi as lágrimas dos oprimidos, que não tinham consolador; a força estava do lado dos seus opressores, porém eles não tinham quem os consolasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Por isso eu considerei os mortos, que já morreram, serem mais merecedores de elogios do que os vivos, que ainda vivem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'E melhor que estes ambos, é aquele que ainda não existe; que não viu as más obras, que são feitas abaixo do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Também vi eu que todo o trabalho, e toda a habilidade em obras, causa ao homem a inveja de seu próximo; também isto é fútil como perseguir o vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'O tolo junta suas mãos, e come sua própria carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'É melhor uma mão cheia com descanso, do que ambas as mãos cheias com trabalho e perseguição ao vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Então eu me voltei, e vi uma futilidade abaixo do sol:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Havia um que era sozinho, sem filho, nem irmão; e seu trabalho não tem fim, nem seus olhos se fartam de riquezas; nem diz: Para quem estou trabalhando, e privando minha alma do que é bom? Também isso é futilidade e enfadonha ocupação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Dois são melhores do que um, porque eles têm melhor recompensa por seu trabalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Porque se vierem a cair, um levanta ao seu companheiro; mas ai daquele que está só, pois caso caia, não há outro que o levante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Também se dois deitarem juntos, eles se aquecem; mas o sozinho, como se aquecerá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'E se alguém prevalecer contra um, os dois resistirão contra ele; porque o cordão de três dobras não se quebra tão depressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Melhor é o garoto pobre e sábio, do que o rei velho e tolo, que não aceita mais receber advertência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Porque da prisão ele sai para reinar, ainda que tenha nascido pobre em seu próprio reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Vi todos os vivos que andam abaixo do sol com o garoto sucessor, que estará em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Não tem fim todo o povo, todo o que houve antes deles; assim como também os descendentes não se alegrarão por ele, de modo que isto também é fútil como perseguir o vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Guarda teu pé, quando entrares na casa de Deus, e prefira te achegares para ouvir do que para dar sacrifícios de tolos, pois não sabem que fazem mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Não te precipites com tua boca, nem te apresse com teu coração, a pronunciar palavra alguma perante a face de Deus; porque Deus está nos céus, e tu estás sobre a terra; por isso tuas palavras sejam poucas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Porque assim como da muita ocupação vêm os sonhos, assim também a voz do tolo vem das muitas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Quando tu prometeres cumprir algum voto a Deus, não demores em pagá-lo; porque ele não se agrada de tolos. Paga o que votares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Melhor é que não votes, do que votares, e não pagares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Não permitas a tua boca, que faça a tua carne pecar; nem digas perante a face do mensageiro, que foi um erro; porque farias irar a Deus tanto com tua voz, a ponto dele destruir a obra de tuas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Porque na abundância de sonhos há coisas inúteis, assim como na abundância de palavras; porém teme a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Se tu vires em algum território a opressão dos pobres, e a violência contra o direito e a justiça, não te maravilhes de tal caso; porque aquele que tem maior autoridade supervisiona as outras autoridades menores; e há outros de ainda maior autoridade que eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Mas o proveito da terra é para todos; até o rei se serve do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Aquele que amar o dinheiro, nunca se fartará de dinheiro; e quem amar a riqueza, nunca se fartará com seus bens; isto também é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Onde os bens se multiplicam, ali se multiplicam também os que a comem; e que proveito pois tem seus donos, a não ser somente ver a riqueza com seus olhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Doce é o sono do trabalhador, quer coma pouco, quer muito; porém a fartura do rico não o deixa dormir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Há um mal causador de sofrimentos que vi abaixo do sol: as riquezas que seus donos guardam para seu próprio mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Porque as mesmas riquezas se perdem com negócios malsucedidos; e quando gera algum filho, nada lhe fica em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Assim como ele saiu do ventre de sua mão, nu ele voltará, indo assim como veio; e nada tomará de seu trabalho, para levar em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'De modo que isto também é um mal causador de sofrimentos, que exatamente como veio, assim se vai; e que proveito ele teve em trabalhar para o vento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Além disso, ele comeu em trevas todos os seus dias; sofreu muito, e teve enfermidades e irritações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Eis o que eu vi, algo bom e belo: comer, beber, e experimentar o que é bom de todo o seu trabalho em que trabalhou abaixo do sol, durante os dias de sua vida, que Deus lhe deu; porque isto é a parte que lhe pertence.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'E todo homem a quem Deus deu riquezas e bens, e lhe deu poder para comer delas, e tomar sua parte, e se alegrar de seu trabalho; isto é presente de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Pois ele não se lembrará muito dos dias de sua vida, porque Deus lhe responde com alegria de seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Há um mal que vi abaixo do sol, e é muito frequente entre os homens:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Um homem a quem Deus deu riquezas, bens, e honra; e nada lhe falta de tudo quanto a sua alma deseja; porém Deus não lhe dá poder para dessas coisas comer; ao invés disso, um estranho as come; isso é futilidade e um mal causador de sofrimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Se o homem gerar cem filhos, e viver muitos anos, e os dias de seus anos forem muitos, porém se sua alma não se fartar daquilo que é bom, nem tiver sepultamento, digo que ter sido abortado teria sido melhor para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Pois veio em futilidade, e se vai em trevas; e nas trevas seu nome é encoberto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Alguém que nunca tivesse visto o sol, nem o conhecido, teria mais descanso do que ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'E ainda que vivesse mil anos duas vezes, e não experimentasse o que é bom, por acaso não vão todos para o mesmo lugar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Todo o trabalho do homem é para sua boca; porém sua alma nunca se satisfaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Porque que vantagem tem o sábio sobre o tolo? E o que mais tem o pobre, em saber andar perante os vivos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Melhor é a vista dos olhos do que o vaguear da cobiça; também isto é fútil como perseguir o vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Seja o que for, seu nome já foi chamado; e já se sabe o que o homem é; e que não pode disputar contra aquele que é mais poderoso do que ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Pois quanto mais palavras há, maior é a futilidade; e que proveito tem homem com elas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Pois quem é que sabe o que é bom na vida para o homem, durante os dias de sua vida inútil, os quais ele gasta como sombra? Pois quem contará ao homem o que haverá depois dele abaixo do sol?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Melhor é uma boa reputação do que o bom óleo perfumado; e o dia da morte de alguém é melhor que o dia de seu nascimento');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Melhor é ir à casa do luto do que a casa do banquete, porque isto é o fim de todos os homens; e os vivos tomam isto em seus corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Melhor é o sofrimento do que o riso, porque com a tristeza do rosto o coração se aperfeiçoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'O coração dos sábios está na casa do luto, mas o coração dos tolos está na casa da alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Melhor é ouvir a repreensão do sábio do que alguém ouvir a canção dos tolos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Pois o riso dos tolos é como o ruído de espinhos debaixo de uma panela; também isto é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Verdadeiramente a opressão faz até o sábio enlouquecer, e o suborno corrompe o coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Melhor é o fim das coisas do que o princípio delas; melhor é o paciente de espírito que o arrogante de espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Não te apresses em teu espírito para te irares, porque a ira repousa no colo dos tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Nunca digas: Por que os dias passados foram melhores que estes de agora? Pois não haveria sabedoria nisto que perguntarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Boa é a sabedoria com a herança; e proveito há para os que veem ao sol;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Porque a sabedoria serve de proteção, assim como o dinheiro serve de proteção; mas a maior vantagem do conhecimento é que a sabedoria dá vida aos que a possuem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Observa a obra de Deus, pois quem poderá endireitar o que ele entortou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'No dia da prosperidade, alegra-te; mas no dia da adversidade, considera; pois Deus faz um em contraposição ao outro, para que o homem não consiga descobrir o que haverá depois dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Tudo isto vi nos meus dias de futilidade: há justo que perece em sua justiça, e há perverso que prolonga sua vida em sua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Não sejas justo demais, nem sejas sábio demais; para que destruirias a ti mesmo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Não sejas perverso demais, nem sejas tolo; para que morrerias antes de teu tempo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'É bom que retenhas isto, e também não retires tua mão disto, pois quem teme a Deus escapa de tudo isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'A sabedoria fortalece ao sábio, mais do que dez homens de autoridade que estejam na cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Verdadeiramente não há homem justo sobre a terra, que faça o bem, e nunca peque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Além disso, não dês atenção a todas as palavras que forem ditas, para que não venhas a ouvir que teu servo te amaldiçoa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Pois teu coração sabe que também tu já amaldiçoaste a outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Tudo isto investiguei com sabedoria. Eu disse: Terei para mim mais sabedoria;porém ela ficava ainda mais longe de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Quem pode encontrar o que está distante e tão profundo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Decidi em meu coração conhecer, investigar e buscar a sabedoria e a razão; e saber o mal que há na tolice e na loucura das maluquices.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'E eu encontrei uma coisa mais amarga que a morte: a mulher cujo coração são redes e armadilhas, e suas mãos são amarras; quem for bom perante Deus escapará dela; mas o pecador ficará preso nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Olha isto:(diz o pregador, enquanto ele procurava entender as coisas,uma por uma)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Aquilo que minha alma tem buscado, ainda não achei; um homem entre mil eu achei; mas uma mulher entre todas estas não achei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Eis que somente achei isto: que Deus fez os homens corretos, porém foram eles que buscaram muitos desejos ruins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Quem é semelhante ao sábio? E quem sabe a interpretação das coisas? A sabedoria do homem faz seu rosto brilhar, e a dureza de seu rosto é alterada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Eu digo: obedece às ordens do rei, por causa do juramento que fizeste a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Não te apresses de sair da presença dele, nem persistas em alguma coisa má; pois tudo que ele deseja, ele faz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Naquilo que há a palavra do rei, ali há autoridade; e quem lhe dirá: O que estás fazendo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Quem obedecer ao mandamento não experimentará mal algum; e o coração do sábio sabe a hora e a maneira corretas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Porque para todo propósito há uma hora e uma maneira correta; por isso o mal do homem é muito sobre ele:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Pois ele não sabe o que irá acontecer. Quem pode lhe avisar o que vai acontecer, e quando?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Não há homem nenhum que tenha domínio sobre o espírito, para reter ao espírito; nem tem domínio sobre dia da morte, nem meios de escapar d esta guerra; nem a perversidade livrará a seus donos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Tudo isto vi quando fiz coração considerar toda obra que se faz abaixo do sol: há um tempo em que um homem passa a dominar outro homem, para sua própria ruína.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Também assim vi os perversos sepultados, e vinham, e saíam do lugar santo; e eles foram esquecidos na cidade em que assim fizeram; isso também é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Dado que o julgamento pela obra má não é feito imediatamente, por causa disso o coração dos filhos dos homens está cheio de vontade neles, para fazer o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Ainda que um pecador faça o mal cem vezes e sua vida se prolongue, mesmo assim eu sei, que as coisas boas acontecerão aos que temem a Deus, aos que temerem diante da sua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Porém ao perverso não sucederá o bem, e não prolongará seus dias, que serão como uma sombra, pois ele não tem temor diane de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Há outra futilidade que é feita sobre a terra: que há justos a quem acontece conforme as obras dos perversos, e há perversos a quem acontece conforme as obras dos justos. Digo que isso também é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Assim elogiei a alegria, pois o homem não tem nada melhor abaixo do sol do que comer, beber e se alegrar; que isso acompanhe seu trabalho nos dias de sua vida, que Deus lhe dá abaixo do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Enquanto entregava meu coração a entender a sabedoria, e ver a ocupação que é feita abaixo do sol (ainda que nem de dia, nem de noite, o homem veja sono em seus olhos),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Então vi toda a obra de Deus, que o homem não pode compreender a obra que é feita abaixo do sol; mesmo que o homem trabalhe para a buscar, ele não a encontrará; ainda que o sábio diga que a conhece, ele não pode compreendê -la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Por isso fiz meu coração considerar todas estas coisas, para entender com clareza tudo isto: que os justos, e os sábios, e suas obras, estão nas mãos de Deus; até o amor e o ódio, o homem nada sabe o que há à sua frente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Tudo acontece de modo semelhante a todos; o mesmo acontece ao justo e ao perverso; ao bom e ao puro, assim como ao impuro; tanto ao que sacrifica, como ao que não sacrifica; tanto ao bom, como ao pecador; ao que jura, assim como ao que teme fazer juramento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Esta coisa má existe entre tudo o que é feito abaixo do sol, que a todos aconteça o mesmo; e que o coração dos filhos homens esteja cheio de maldade, e que haja loucuras em seus corações durante suas vidas, e depois eles vão para entre os mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Porque para aquele que está junto a todos os vivos há esperança (pois melhor é um cão vivo do que um leão morto).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Porque os vivos sabem que vão morrer; mas os mortos não sabem coisa alguma, nem também tem mais recompensa; pois a lembrança deles já foi esquecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Até seu amor, até seu ódio, e até sua inveja já pereceu e nenhuma parte nunca mais lhes pertence, em tudo quanto se faz abaixo do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Vai, come com alegria teu pão, e bebe com bom coração o teu vinho; pois Deus se agrada de tuas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Em todo tempo sejam brancas as tuas roupas, e nunca falte óleo sobre tua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Aproveite a vida com a mulher que tu amas, todos os dias da tua fútil vida, que Deus te deu abaixo do sol, todos os teus fúteis dias; porque esta é a parte que te pertence nesta vida e em teu trabalho no qual trabalhaste abaixo do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Tudo quanto vier à tua mão para fazer, faze conforme as tuas forças; porque no mundo dos mortos, para onde tu vais, não há obra, nem planos, nem conhecimento, nem sabedoria alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Voltei-me, e vi abaixo do sol, que a corrida não é dos velozes, nem dos guerreiros a batalha, nem dos sábios o pão, nem dos prudentes as riquezas, nem dos conhecedores o favor; mas que o tempo e a ocasião imprevista acontece a todos estes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Porque também o homem não sabe seu tempo, assim como os peixes que são capturados pela maligna rede; e como os passarinhos que são presos na armadilha; assim também os filhos dos homens são pegos pelo tempo mau, quando cai de repente sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Também vi esta sabedoria abaixo do sol, que considerei grande:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Havia uma pequena cidade, em que havia poucas pessoas; e veio contra ela um grande rei, e a cercou, e levantou contra ela grandes barreiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'E se achou nela um homem pobre sábio, que livrou aquela cidade com sua sabedoria; porém ninguém se lembrou daquele pobre homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Então eu disse: Melhor é a sabedoria do que a força; ainda que a sabedoria do pobre tenha sido desprezada, e suas palavras não tenham sido ouvidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'As palavras dos sábios devem ser ouvidas em quietude, mais do que o grito daquele que domina sobre os tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Melhor é a sabedoria do que as armas de guerra; porém um só pecador destrói muitas coisas boas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Assim como as moscas mortas fazem cheirar mal do óleo do perfumador, assim também um pouco de tolice se sobrepõe à sabedoria e honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'O coração do sábio está à sua direita; mas o coração do tolo está à sua esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'E até quando o tolo vai pelo caminho, falta-lhe bom-senso em seu coração, e diz a todos que é ele é tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Se o espírito de um chefe se levantar contra ti, não deixes teu lugar, porque a calma aquieta grandes ofensas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Há um mal que vi abaixo do sol, um tipo de erro que é proveniente dos que têm autoridade:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Põem o tolo em cargos elevados, mas os ricos sentam em lugares baixos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Vi servos a cavalo, e príncipes que andavam a pé como se fossem servos sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Quem cavar uma cova, nela cairá; e quem romper um muro, uma cobra o morderá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Quem extrai pedras, por elas será ferido; e quem parte lenha, correrá perigo por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Se o ferro está embotado, e não afiar o corte, então deve se pôr mais forças; mas a sabedoria é proveitosa para se ter sucesso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Se a cobra morder sem estar encantada, então proveito nenhum tem a fala do encantador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'As palavras da boca do sábio são agradáveis; porém os lábios do tolo o devoram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'O princípio das palavras de sua boca é tolice; e o fim de sua boca é uma loucura ruim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'O tolo multiplica as palavras, porém ninguém sabe o que virá no futuro; e quem lhe fará saber o que será depois dele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'O trabalho dos tolos lhes traz cansaço, porque não sabem ir à cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Ai de ti, ó terra cujo rei é um menino, e cujos príncipes comem pela madrugada!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Bem-aventurada é tu, ó terra, cujo rei é filho de nobres, e cujos príncipes comem no tempo devido, para se fortalecerem, e não para se embebedarem!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Pela muita preguiça o teto se deteriora; e pala frouxidão das mãos a casa tem goteiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Para rir se fazem banquetes, e o vinho alegra aos vivos; mas o dinheiro responde por tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Nem mesmo em pensamento amaldiçoes ao rei, nem também no interior de teu quarto amaldiçoes ao rico, porque as aves dos céus levam o que foi falado, e os que tem asas contam o que foi dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Lança teu pão sobre as águas, porque depois de muitos dias tu o encontrarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Dá uma parte a sete, e até a oito; porque não sabes que mal haverá sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Se as nuvens estiverem cheias, há chuva sobre a terra; e se a árvore cair, seja para ou sul ou seja para o norte, no lugar em que a árvore cair, ali ela ficará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Quem ficar dando atenção ao vento, nunca semeará; e o que olhar para as nuvens nunca ceifará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Assim como tu não sabes qual é o caminho do vento, nem como se formam os ossos do feto no ventre da grávida, assim também tu não sabes a obra de Deus, que faz todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Pela manhã semeia tua semente, e à tarde não retires tua mão; pois tu não sabes qual tentativa dará certo, se uma, se outra, ou se ambas as tentativas serão boas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Certamente a luz é agradável, e ver o sol é bom para os olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Mesmo se o homem viver muitos anos, e em todos eles se alegrar, ele também deve se lembrar dos dias de trevas, porque serão muitos. Tudo o que acontece é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Alegra-te, rapaz, em tua juventude; e agrada o teu coração nos dias de tua juventude; e anda pelos caminhos do teu coração, e na vista de teus olhos; sabe, porém, que por todas estas coisas, Deus te trará a julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Portanto afasta o desagrado de teu coração, e tira de tua carne o mal; pois a adolescência e a juventude são futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Portanto lembra-te de teu Criador nos dias de tua juventude, antes que venham os dias ruins, e cheguem os anos, dos quais venhas a dizer: Não tenho neles contentamento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Antes que se escureçam o sol, a luz, a lua e as estrelas; e voltem as nuvens após a chuva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'No dia em que os guardas da casa tremerem, e os homens fortes se encurvarem; e cessarem os moedores, por terem diminuído, e se escurecerem os que olham pelas janelas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'E as portas da rua se fecharem, enquanto se abaixa o ruído da moedura; e se levantar a voz das aves, e todas as vozes do canto se encurvarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Como também quando temerem as coisas altas, e houver espantos no caminho; e florescer a amendoeira, e o gafanhoto se tornar pesado, e acabar o apetite; porque o homem vai para sua casa eterna, e os que choram andarão ao redor da praça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Antes que se afrouxe a correia de prata, e de despedace a vasilha de ouro; e se quebre o vaso junto à fonte, e se despedace a roda junto ao poço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'E o pó volte à terra, assim como era; e o espírito volte a Deus, que o deu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Futilidade das futilidades! - diz o pregador - Tudo é futilidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Além do Pregador ter sido sábio, ele também ensinou conhecimento ao povo. Ele ouviu, investigou e pôs em ordem muitos provérbios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'O Pregador procurou achar palavras agradáveis, e escreveu coisas corretas, palavras de verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'As palavras dos sábios são como aguilhões, e como pregos bem fixados pelos mestres das congregações, que foram dadas pelo único Pastor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Além destas coisas, filho meu, tem cuidado; fazer muitos livros é algo que não tem fim; e estudar muito cansa a carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'De tudo o que foi ouvido, a conclusão é: teme a Deus, e guarda os mandamentos dele; porque isto é o dever de todo homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Porque Deus trará a julgamento toda obra, até mesmo tudo o que está encoberto, seja bom ou mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Cântico dos cânticos, que é de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Ela: Beije-me ele com os beijos de sua boca, porque teu amor é melhor do que o vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'O cheiro dos teus perfumes é agradável; teu nome é como perfume sendo derramado, por isso as virgens te amam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Toma-me contigo, e corramos; traga-me o rei aos seus quartos. Moças: Em ti nos alegraremos e nos encheremos de alegria; nos agradaremos mais de teu amor do que do vinho; Ela: Elas estão certas em te amar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Eu sou morena, porém bela, ó filhas de Jerusalém: morena como as tendas de Quedar, bela como as cortinas de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Não fiquem me olhando por eu ser morena, pois o sol brilhou sobre mim; os filhos de minha mãe se irritaram contra mim, e me puseram para cuidar de vinhas; porém minha própria vinha, que me pertence, não cuidei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Dize-me, amado de minha alma: onde apascentas o teu gado? Onde o recolhes ao meio- dia? Para que ficaria eu como que coberta com um véu por entre os gados de teus colegas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Ele: Se tu, a mais bela entre as mulheres, não sabes, sai pelos rastros das ovelhas, e apascenta tuas cabras junto às tendas dos pastores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Eu te comparo, querida, às éguas das carruagens de Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Agradáveis são tuas laterais da face entre os enfeites, teu pescoço entre os colares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Enfeites de ouro faremos para ti, com detalhes de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Ela: Enquanto o rei está sentado à sua mesa, meu nardo dá a sua fragrância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Meu amado é para mim como um saquinho de mirra que passa a noite entre meus seios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Meu amado é para mim como um ramalhete de hena nas vinhas de Engedi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Ele: Como tu és bela, minha querida! Como tu és bela! Teus olhos são como pombas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Ela: Como tu és belo, meu amado! Como tu és agradável! E o nosso leito se enche de folhagens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'As vigas de nossa casa são os cedros, e nossos caibros os ciprestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Eu sou a rosa de Sarom, o lírio dos vales.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Ele: Como um lírio entre os espinhos, assim é minha querida entre as moças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Ela: Como a macieira entre as árvores do bosque, assim é o meu amado entre os rapazes; debaixo de sua sombra desejo muito sentar, e doce é o seu fruto ao meu paladar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Ele me leva à casa do banquete, e sua bandeira sobre mim é o amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Sustentai-me com passas, fortalecei-me com maçãs; porque estou fraca de amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Esteja sua mão esquerda abaixo de minha cabeça, e sua direita me abraça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Eu vos ordeno, filhas de Jerusalém: jurai pelas corças e pelas cervas do campo, que não acordeis, nem desperteis ao amor, até que ele queira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Esta é a voz do meu amado: vede-o vindo, saltando sobre os montes, pulando sobre os morros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Meu amado é semelhante ao corço, ou ao filhote de cervos; eis que está atrás de nossa parede, olhando pelas janelas, observando pelas grades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Meu amado me responde, e me diz: Ele: Levanta-te, querida minha, minha bela, e vem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Porque eis que o inverno já passou; a chuva se acabou, e foi embora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'As flores aparecem na terra, o tempo da cantoria chegou; e ouve-se a voz da rolinha em nossa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'A figueira está produzindo seus figos verdes, e as vides florescentes dão cheiro; levanta-te, querida minha, minha bela, e vem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Pomba minha, que andas pelas fendas das rochas no oculto das ladeiras, mostra-me tua face, faze-me ouvir tua voz; porque tua voz é doce, e tua face agradável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Tomai-nos as raposas, as raposinhas, que danificam as vinhas, porque nossas vinhas estão florescendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Meu amado é meu, e eu sou sua; ele apascenta entre os lírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Antes do dia se romper, e das sombras fugirem, volta, amado meu, faze-te semelhante ao corço, ao filhote de cervos, sobre os montes de Beter.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Ela:Durante as noites busquei em minha cama a quem minha alma ama; busquei-o, mas não o achei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Por isso me levantarei, e percorrerei a cidade, pelas ruas e pelas praças; buscarei a quem minha alma ama; busquei-o, mas não o achei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Os guardas que rondavam pela cidade me encontraram. Eu lhes perguntei: Vistes a quem minha alma ama?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Pouco depois de me afastar deles, logo achei a quem minha alma ama. Eu o segurei, e não o deixei ir embora, até eu ter lhe trazido à casa de minha mãe, ao cômodo daquela que me gerou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Eu vos ordeno, filhas de Jerusalém: jurai pelas corças e pelas cervas do campo que não acordeis nem desperteis ao amor, até que ele queira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Quem é esta, que sobe do deserto como colunas de fumaça, perfumada com mirra, incenso, e com todo tipo de pó aromático de mercador?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Eis a cama móvel de Salomão! Sessenta guerreiros estão ao redor dela, dentre os guerreiros de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Todos eles portando espadas, habilidosos na guerra; cada um com sua espada à cintura, para o caso de haver um ataque repentino de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'O rei Salomão fez para si uma liteira de madeira do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Suas colunas ele fez de prata, seu assoalho de ouro, seu assento de púrpura; por dentro coberta com a obra do amor das filhas de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Saí, ó filhas de Sião, e contemplai ao rei Salomão, com a coroa a qual sua mãe o coroou, no dia de seu casamento, no dia da alegria do seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Ele: Como tu és bela, minha querida! Como tu és bela! Teus olhos por trás do véu são como pombas; teu cabelo é como um rebanho de cabras, que descem do monte Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Teus dentes são como ovelhas tosquiadas, que sobem do lavatório; todas elas têm gêmeos, e nenhuma delas é estéril.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Teus lábios são como uma fita de escarlate, e tua boca é bonita; tuas têmporas são como pedaços de romã por detrás do véu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Teu pescoço é como a torre de Davi, construída como fortaleza; mil escudos estão nela pendurados, todos escudos de guerreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Teus dois seios são como dois filhos gêmeos da corça, que pastam entre os lírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Antes do dia nascer, e das sombras fugirem, irei ao monte de mirra, e ao morro do incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Tu és bela, minha querida! Não há defeito algum em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Vem comigo do Líbano, ó esposa minha, vem comigo do Líbano; desce do cume de Amaná, do cume de Senir e de Hermom, das montanhas das leoas, dos montes dos leopardos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Tomaste meu coração, minha irmã, minha esposa; tomaste o meu coração com um de teus olhos, com um colar de teu pescoço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Como são agradáveis os teus amores, minha irmã, minha esposa! São bem melhores do que o vinho; e o cheiro de teus unguentos é melhor que todas as especiarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Favos de mel descem de teus lábios, ó esposa; mel e leite estão debaixo de tua língua; e o cheiro de teus vestidos é como o cheiro do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Jardim fechado és tu, minha irmã, minha esposa; manancial fechado, uma fonte selada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tuas plantas são uma horta de romãs, com frutos excelentes: hena e nardo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nardo, açafrão, cálamo e canela; com todo tipo de árvores de incenso: mirra, aloés, com todas as melhores especiarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Tu és uma fonte de jardins, um poço de águas vivas que corre do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Ela: Levanta-te, vento norte! E vem, ó vento sul! Assopra em meu jardim, para que espalhem os seus aromas! Que meu amado venha a seu jardim, e coma de seus excelentes frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Ele: Já cheguei ao meu jardim, minha irmã, minha esposa; colhi minha mirra com minha especiaria; comi meu mel, bebi meu vinho com meu leite. Autor do poema (ou os amigos dos noivos): Comei, amigos; bebei, ó amados, e embebedai-vos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Ela: Eu estava dormindo, mas meu coração vigiava; era a voz de meu amado, batendo: Abre-me, minha irmã, minha querida, minha pomba, minha perfeita! Porque minha cabeça está cheia de orvalho, meus cabelos das gotas da noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Já tirei minha roupa; como voltarei a vesti-la? Já lavei meus pés; como vou sujá-los de novo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Meu amado meteu sua mão pelo buraco da porta,e meu interior se estremeceu por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Eu me levantei para abrir a meu amado; minhas mãos gotejavam mirra, e meus dedos derramaram mirra sobre os puxadores da fechadura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Eu abri a porta ao meu amado, porém meu amado já tinha saído e ido embora; minha alma como que saía de si por causa de seu falar. Eu o busquei, mas não o achei; eu o chamei, mas ele não me respondeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Os guardas que rondavam pela cidade me encontraram; eles me bateram e me feriram; os guardas dos muros tiraram de mim o meu véu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Eu vos ordeno, filhas de Jerusalém: jurai que, se achardes o meu amado, dizei a ele que estou doente de amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Moças: Ó tu mais bela entre as mulheres, como é o teu amado, ao qual tu amas mais do que qualquer outro? Como é este teu amado, mais amado do que qualquer outro, pelo qual assim nos ordenas jurar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Ela: Meu amado é radiante e rosado; ele se destaca entre dez mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sua cabeça é como o mais fino ouro; seus cabelos são crespos, pretos como o corvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Seus olhos são como pombas junto às correntes de águas, lavados em leite, colocados como joias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'As laterais de seu rosto como um canteiro de especiarias, como caixas aromáticas; seus lábios são como lírios, que gotejam fragrante mirra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Suas mãos são como anéis de ouro com pedras de crisólitos; seu abdome como o brilhante marfim, coberto de safiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Suas pernas são como colunas de mármore, fundadas sobre bases de ouro puro; seu aspecto é como o Líbano, precioso como os cedros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Sua boca é cheia de doçura, e ele é desejável em todos os sentidos; assim é o meu amado; assim é o meu querido, ó filhas de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Moças: Para onde foi o teu amado, ó tu mais bela entre as mulheres? Para que direção se virou o teu amado, para o procurarmos contigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Ela: Meu amado desceu ao seu jardim, aos canteiros de especiarias, para apascentar seu rebanho nos jardins, e para colher lírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Eu sou do meu amado, e meu amado é meu; ele apascenta entre os lírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Ele: Tu és bela, minha querida, como Tirza, agradável como Jerusalém; és formidável como bandeiras de exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Afasta teus olhos de mim, pois eles me deixam desconcertado. Teu cabelo é como um rebanho de cabras, que descem de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Teus dentes são como um rebanho de ovelhas, que sobem do lavatório; todas produzem gêmeos, e não há estéril entre elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Como um pedaço de romã, assim são as laterais de teu rosto abaixo de teu véu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Sessenta são as rainhas, e oitenta as concubinas; e as donzelas são inúmeras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Porém uma é a minha pomba, minha perfeita, a única de sua mãe, a mais querida daquela que a gerou. As moças a viram, e a chamaram de bem-aventurada; as rainhas e as concubinas a elogiaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Quem é esta, que aparece como o nascer do dia, bela como a lua, brilhante como o sol, formidável como bandeiras de exércitos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Desci ao jardim das nogueiras, para ver os frutos do vale; para ver se as videiras estavam floridas, e se as romãzeiras brotavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Sem eu perceber, minha alma me pôs nas carruagens de meu nobre povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Moças: Volta! Volta, Sulamita! Volta! Volta, e nós te veremos! Ele: Por que quereis ver a Sulamita, como a dança de duas companhias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Ele: Como são belos os teus pés nas sandálias, ó filha de príncipe! Os contornos de tuas coxas são como joias, como obra das mãos de um artesão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Teu umbigo é como uma taça redonda, que não falta bebida; teu abdome é como um amontoado de trigo, rodeado de lírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Teus dois seios são como dois filhos gêmeos da corça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Teu pescoço é como uma torre de marfim; teus olhos são como os tanques de peixes de Hesbom, junto à porta de Bate-Rabim. Teu nariz é como a torre do Líbano, que está de frente a Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Tua cabeça sobre ti, como o monte Carmelo, e o trançado dos cabelos cabeça como púrpura; o rei está como que atado em tuas tranças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Como tu és bela! Como tu és agradável, ó amor em delícias!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Esta tua estatura é semelhante à palmeira, e teus seios são como cachos de uvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Eu disse: Subirei à palmeira, pegarei dos seus ramos; e então teus seios serão como os cachos da videira, e a fragrância de teu nariz como o das maçãs.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'E tua boca seja como o bom vinho; Ela: Vinho que se entra a meu amado suavemente, e faz falarem os lábios dos que dormem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Eu sou do meu amado, e ele me deseja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Vem, amado meu! Saiamos ao campo, passemos as noites nas aldeias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Saiamos de madrugada até às vinhas, vejamos se as videiras florescem, se suas flores estão se abrindo, se as romãzeiras já estão brotando; ali te darei os meus amores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'As mandrágoras espalham seu perfume, e junto a nossas portas há todo tipo de excelentes frutos, novos e velhos; eu os guardei para ti, meu amado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Como gostaria que tu fosses como meu irmão, que mamava os seios de minha mãe. Quando eu te achasse na rua, eu te beijaria, e não me desprezariam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Eu te levaria e te traria à casa de minha mãe, aquela que me ensinou, e te daria a beber do vinho aromático, do suco de minhas romãs.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Esteja sua mão esquerda debaixo de minha cabeça, e sua direita me abrace.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Eu vos ordeno, filhas de Jerusalém: jurai que não acordeis, nem desperteis ao amor, até que ele queira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Outras pessoas: Quem é esta, que sobe da terra desabitada, reclinada sobre seu amado? Ela: Debaixo de uma macieira te despertei; ali tua mãe te fez nascer com dores; ali te fez nascer aquela que te gerou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Põe-me com um selo sobre teu coração, como selo sobre teu braço; porque o amor é forte como a morte; os ciúmes são duros como o mundo dos mortos; suas brasas são brasas de fogo, labaredas poderosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Muitas águas não poderiam apagar este amor, nem os rios afogá-lo; ainda que alguém desse todos os bens de sua casa por este amor, certamente o desprezariam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Irmãos dela: Temos uma irmã pequena, que ainda não têm seios; que faremos a esta nossa irmã, no dia que dela falarem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Se ela for um muro, edificaremos sobre ela um palácio de prata; e se ela for uma porta, então a cercaremos com tábuas de cedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Ela: Eu sou um muro, e meus seios como torres; então eu era aos olhos dele, como aquela que encontra a paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomão teve uma vinha em Baal-Hamom; ele entregou esta vinha a uns guardas, e cada um lhe trazia como faturamento de seus frutos mil moedas de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Minha vinha, que me pertence, está à minha disposição; as mil moedas de prata são para ti, Salomão, e duzentas para os guardas de teu fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Ele: Ó tu que habitas nos jardins, teus colegas prestam atenção à tua voz: faze com que eu também possa ouvi-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Ela: Vem depressa, meu amado! E faze-te semelhante ao corço, ao filhote de cervos, nas montanhas de ervas aromáticas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Visão de Isaías, filho de Amoz, a qual ele viu sobre Judá e Jerusalém, nos dias de Uzias, Jotão, Acaz e Ezequias, reis de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Ouvi, ó céus; e escutai tu, terra, porque o SENHOR está falando: Eu criei filhos, e os fiz crescerem; porém eles se rebelaram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'O boi conhece a seu dono, e o jumento sabe a manjedoura de seu possuidor; mas Israel não conhece, meu povo não entende.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ai da nação pecadora, do povo cheio de perversidade, semente de malfeitores, de filhos corruptos! Abandonaram ao SENHOR, provocaram a ira ao Santo de Israel, dele se afastaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Para que seríeis espancados ainda mais? Vós vos rebelaríeis mais ainda. Toda a cabeça está enferma, e todo o coração fraco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Desde a planta do pé até a cabeça, não há nele coisa sã. Só há feridas, inchaços e chagas podres, sem terem sido espremidas, feito curativos ou aliviadas com azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Vossa terra é uma ruína; vossas cidades foram queimadas; vossa terra os estranhos devastaram diante de vossa presença, e está arruinada como que destruída por estranhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'E a filha de Sião ficou como uma cabana na vinha, como um barraco no pepinal, como uma cidade cercada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Se o SENHOR dos exércitos não tivesse nos deixado alguns sobreviventes, teríamos sido como Sodoma, seríamos semelhantes aos de Gomorra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Ouvi a palavra do SENHOR, vós líderes de Sodoma! Ouvi a Lei do nosso Deus, vós povo de Gomorra!:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Para que me serve tantos sacrifícios vossos?,diz o SENHOR; Já estou farto de sacrifícios de queima de carneiros, e da gordura de animais cevados. Não me alegro com o sangue de bezerros, nem com o de cordeiros ou bodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Quando vindes a aparecer perante minha face, quem vos pediu isso de vossas mãos, de pisardes em meus pátios?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Não tragais mais ofertas inúteis; vosso incenso para mim é abominação; não aguento mais as luas novas, os sábados, e as chamadas para o povo se reunir; todas estas se tornaram reuniões malignas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Vossas luas novas e vossas solenidades, minha alma as odeia e elas me perturbam; estou cansado de as suportar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Por isso quando estendeis vossas mãos, escondo meus olhos de vós; até quando fazeis muitas orações, eu não vos ouço; porque vossas mãos estão cheias de sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Lavai-vos! Purificai-vos! Tirai a maldade de vossas atitudes perante meus olhos; parai de fazer maldades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Aprendei a fazer o bem; procurai o que é justo; ajudai ao oprimido; fazei justiça ao órfão; defendei a causa da viúva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Vinde, então, e façamos as contas,diz o SENHOR: ainda que vossos pecados sejam como a escarlate, eles ficarão brancos como a neve; ainda que sejam vermelhos como o carmesim, eles se tornarão como a lã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Se quiserdes e ouvirdes, comereis o que é bom da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Porém se recusardes e fordes rebeldes, sereis devorados pela espada;pois foi assim que a boca do SENHOR falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Como a cidade fiel se tornou uma prostituta! Ela estava cheia de juízo, justiça habitava nela; porém agora homicidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Tua prata se tornou em escórias; teu vinho se misturou com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Teus príncipes são rebeldes, e companheiros de ladrões; cada um deles ama os subornos, e perseguem recompensas; não fazem justiça ao órfão, e não chega perante eles a causa das viúvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Por isso diz o Senhor DEUS dos exércitos, o Poderoso de Israel: Ah, tomarei satisfações quanto aos meus adversários, e me vingarei de meus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'E tornarei minha minha mão contra ti, e purificarei por completo tuas escórias; e tirarei toda a tua impureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'E restituirei a teus juízes, como da primeira vez, e a teus conselheiros, como no princípio; e depois disso te chamarão cidade da justiça, cidade fiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sião será resgatada por meio do juízo; e os que retornarem a ela, por meio da justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Mas para os transgressores e pecadores, serão juntamente quebrados; e os que deixarem ao SENHOR serão consumidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Porque pelos carvalhos que cobiçastes serão confundidos; e pelos bosques que escolhestes sereis envergonhados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Porque sereis como o carvalho ao qual suas folhas caem, e como o bosque que não tem água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'E o forte se tornará em estopa, e sua obra, em faísca; e ambos serão juntamente queimados, e não haverá quem os apague.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Palavra vista por Isaías, filho de Amoz, quanto a Judá e a Jerusalém:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'E acontecerá no últimos dias, que o monte da cada do SENHOR se firmará no cume dos montes, e se levantará por cima dos morros; e correrão em direção a ele todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'E muitos povos irão, e dirão: Vinde, subamos ao monte do SENHOR, à casa do Deus de Jacó, para que ele nos ensine sobre seus caminhos, e andemos em suas veredas; Porque de Sião virá a Lei, e de Jerusalém a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'E ele julgará entre as nações, e repreenderá a muitos povos; e trocarão suas espadas em enxadas, e suas lanças em foices; não se levantará mais espada nação contra nação, nem aprenderão mais a fazer guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Casa de Jacó, vinde, e andemos à luz do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Mas tu, SENHOR, desamparaste a teu povo, à casa de Jacó; porque se encheram dos costumes do oriente, e são místicos como os filisteus; e se associam a filhos de estrangeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'A terra deles está cheia de prata e de ouro, e os tesouros deles não têm fim; a terra deles está cheia de cavalos, e as carruagens deles não têm fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'A terra deles também está cheia de ídolos; eles se inclinam perante as obras de suas próprias mãos, perante o que seus próprios dedos fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Ali as pessoas se abatem, e os homens se humilham; por isso tu não os perdoarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Entra nas rochas, e esconde-te no pó, por causa da temível presença do SENHOR, e da glória de sua majestade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Os olhos arrogantes dos homens serão abatidos, e o orgulho dos homens será humilhado; e só o SENHOR será exaltado naquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Porque o dia do SENHOR dos exércitos será contra o soberbo e o arrogante; e contra todo de que se acha exaltado, para que seja abatido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'E contra todos os cedros do Líbano, altos e elevados; e contra todos os carvalhos de Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'E contra todos os altos montes, e contra todos os morros elevados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'E contra toda torre alta, e contra todo muro fortificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'E contra todos os navios de Társis, e contra todas as pinturas desejadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'E a soberba do homem será humilhada, e o orgulho dos homens será abatido; e só o SENHOR será exaltado naquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'E todos os ídolos serão eliminados por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Então entrarão nas cavernas das rochas, e nos buracos da terra, por causa da temível presença do SENHOR, e por causa de sua majestade, quando ele se levantar, para espantar a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Naquele dia, o homem lançará seus ídolos de prata, e seus ídolos de ouro, que fizeram para se prostrarem diante deles, às toupeiras e aos morcegos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'E se porão nas fendas das rochas, e nas cavernas das penhas, por causa da temível presença do SENHOR, e por causa da glória de sua majestade, quando ele se levantar para espantar a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Portanto, cessai de confiar no homem, cujo fôlego está em suas narinas; pois o que há nele que mereça se dar algum valor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Porque eis que o Senhor DEUS dos exércitos tirará de Jerusalém e de Judá o apoio e o sustento: todas as fontes de comida e de água,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'O guerreiro, o soldado, o juiz, o profeta, o adivinho, e o ancião;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'O chefe de cinquenta, o nobre, o conselheiro, o sábio entre os artífices, e o que tem habilidade de falar palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'E lhes darei garotos como seus príncipes, e rapazes dominarão sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'E o povo será oprimido; um será contra o outro, e cada um contra seu próximo; o jovem se atreverá contra o ancião, e o reles contra o nobre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Porque um homem tomará seu irmão da casa de seu pai, e dirá: Tu tens capa; sê nosso governante, e estejam estas ruínas debaixo de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Então em tal dia ele levantará sua mão, dizendo: Não posso solucionar este problema; também em minha casa não há pão nem vestido algum; não me ponhais como governante do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Porque Jerusalém tropeçou, e Judá está caído; pois sua língua e suas obras são contra o SENHOR, para irritar os seus gloriosos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'A aparência de seus rostos dão testemunho contra eles, e mostram abertamente seus pecados; assim como Sodoma, não os disfarçam. Ai da alma deles, porque estão fazendo mal a si mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Dizei a justo, que o bem lhe sucederá,que comerão do fruto de suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Ai do perverso! O mal lhe sucederá,porque lhe será feito conforme o trabalho de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Os dominadores de meu povo são garotos, e mulheres dominam sobre ele; ah, meu povo, os que te guiam te enganam e confundem o caminho de tuas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'O SENHOR se apresenta para brigar a causa judicial, e se põe para julgar aos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'O SENHOR vem a juízo contra os anciãos de seu povo, e contra seus líderes: Pois vós consumistes a vinha, o despojo do pobre está em vossas casas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Por que vós esmagastes ao meu povo, e moestes o rosto dos pobres?,diz o Senhor DEUS dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Além disso o SENHOR diz: Dado que as filhas de Sião se exaltam, e andam com o pescoço levantado, e procuram seduzir com os olhos, e vão andando a passos curtos, fazendo ruídos com os ornamentos dos pés,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Por isso o Senhor fará chagas no topo das cabeças das filhas de Sião, e descobrirá suas partes íntimas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Naquele dia o Senhor tirará delas os enfeites: tornozeleiras, testeiras, gargantilhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Brincos, pulseiras, véus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Chapéus, braceletes, cintos, bolsinhas de perfume, amuletos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Anéis, pingentes de nariz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Vestidos de festa, mantas, capas, bolsas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Transparências, saias de linho, toucas e túnicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'E será que, no lugar de aromas haverá fedor; e no lugar de cinto haverá corda; e no lugar de cabelos cacheados haverá calvície, e no lugar de roupa luxuosa haverá roupa de saco; e queimadura no lugar de beleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Teus homens cairão à espada; teus guerreiros na batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'E as portas delas gemerão, e chorarão; e ela, ficando desolada, se sentará no chão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'E sete mulheres tomarão um mesmo homem naquele dia, dizendo: Nós comeremos de nosso pão, e nos vestiremos de nossas roupas; queremos somente que teu nome seja posto sobre nós; livra-nos de nossa vergonha!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Naquele dia o Renovo do SENHOR será belo e glorioso; e o fruto da terra de excelente valor, para os de Israel que escaparem do perigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'E será que aquele que continuar em Sião e aquele que for deixado em Jerusalém será chamado santo; todo aquele que em Jerusalém está escrito para a vida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Quando o Senhor lavar a imundícia das filhas de Sião, e limpar o sangue de Jerusalém do meio dela, com o espírito de juízo, e com o espírito de queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'E o SENHOR criará sobre toda moradia do monte de Sião, e sobre seus ajuntamentos, uma nuvem de dia, e uma fumaça, e um brilho de fogo inflamado de noite; porque sobre toda glória haverá proteção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'E haverá uma tenda para sombra contra o calor do dia, e para refúgio e abrigo contra a tempestade e contra a chuva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Agora cantarei a meu amado o cântico de meu querido de sua vinha: meu amado tem uma vinha, em um morro fértil;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'E a cercou, e limpou das pedras, e a plantou de excelentes videiras, e edificou no meio dela uma torre; e também fundou nela um lagar; e esperava que desse uvas boas, porém deu uvas imprestáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'E agora, ó moradores de Jerusalém, e vós homens de Judá? Julgai, eu vos peço, entre mim e minha vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'O que mais podia ser feito à minha vinha, que eu não tenha já feito? Se eu esperava uvas boas, como, pois, veio dar uvas imprestáveis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Por isso agora eu vos farei saber o que farei à minha vinha: tirarei sua cerca, para que sirva de pastagem; derrubarei seu muro, para que seja pisada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'E eu a tornarei uma terra abandonada; não será podada, nem cavada; mas crescerão nela cardos e espinhos; e darei ordens às nuvens, para que não chovam chuva sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Porque a vinha do SENHOR dos exércitos é a casa de Israel, e os homens de Judá são suas plantas agradáveis; porém ele esperava juízo, e eis aqui opressão; ele esperava justiça, e eis aqui clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Ai dos que juntam uma casas, e acumulam propriedades de terra, até que não tenha sobrado mais lugar, para que somente vós fiqueis como moradores no meio da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'O SENHOR dos exércitos disse aos meus ouvidos: Verdadeiramente muitas casas se tornarão desertas, até as grandes e valiosas ficarão sem moradores!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'E dez jeiras de vinha darão apenas um bato; e um ômer de semente dará apenas um efa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Ai dos que se levantam cedo pela manhã, para buscarem bebida alcoólica, e continuam até a noite, até que o vinho os esquente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'E harpas, liras, tamborins, gaitas e vinho há em seus banquetes; porém não olham para a obra do SENHOR, nem prestam atenção no agir das mãos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Por isso meu povo será levado cativo, porque não tem conhecimento; e seus nobres sofrem de fome, e sua multidão está seca de sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Por isso o mundo dos mortos alargou seu apetite, e sua boca se abriu tanto que não se pode medir, para que caia a nobreza de Jerusalém,sua multidão, com todo o seu ruído de festa,e com os que nela festejam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Então os seres humanos serão abatidos, e os homens serão humilhados; e os olhos dos arrogantes se humilharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Mas o SENHOR dos exércitos será exaltado com juízo; e Deus, o Santo, será santificado com justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'E os cordeiros pastarão como se fosse seus próprios pastos, e os estranhos comerão do alimento proveniente dos lugares abandonados dos ricos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Ai dos que puxam perversidade com cordas de futilidade, e pelo pecado como que com cordas de carruagens!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'E dizem: Que ele se apresse, acelere sua obra, para que a vejamos; e aproxime-se e venha o conselho do Santo de Israel, para que possamos saber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Ai dos que chamam o mal de bem, e o bem de mal; que trocam as trevas pela luz, e a luz pelas trevas; e trocam o amargo pelo doce, e o doce pelo amargo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Ai dos que se acham sábios aos seus próprios olhos, e prudentes para si mesmos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Ai dos que se acham corajosos para beberem vinho, e homens fortes para misturarem bebida alcoólica!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Ai d os que inocentam o perverso por causa de suborno, e se desviam da justiça dos justos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Por isso, como a língua de fogo consome a estopa, e a chama queima a palha, assim sua raiz será como podridão, e sua flor se desfará como o pó; pois rejeitaram a Lei do SENHOR dos exércitos, e desprezaram a palavra do Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Por isso se acendeu a ira do SENHOR contra seu povo, e estendeu sua mão contra ele, e o feriu; e as montanhas tremeram, e seus cadáveres foram como lixo no meio das ruas; com tudo isto ele não retrocedeu sua ira; ao contrário, sua mão ainda está estendida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'E ele levantará uma bandeira para as nações distantes, e lhes assoviará desde os confins da terra; e eis que virão com rapidez apressadamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Não haverá entre eles cansado ou quem tropece; ninguém cochilará, nem dormirá; nem se desatará o cinto de seus lombos, nem será arrebentada a tira de seus calçados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Suas flechas estarão afiadas, e todos os seus arcos prontos para atirar; os cascos de seus cavalos serão comparáveis a rochas, e as rodas de suas carruagens como redemoinhos de vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'O rugido deles será como o de um leão feroz, e bramarão como filhotes de leão; e rugirão, e tomarão a presa, e a levarão, e não haverá quem a resgate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'E bramarão contra ela naquele dia como o bramido do mar; então olharão para a terra, e eis que há trevas e aflição; e a luz se escurecerá em suas nuvens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'No ano em que o rei Uzias morreu, eu vi o Senhor sentado sobre um alto e elevado trono; e as bordas de seu manto enchiam o templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafins estavam por cima dele, cada um tinha seis asas; com duas cobriam seus rostos, com duas cobriam seus pés, e com duas voavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'E clamavam uns aos outros, dizendo: Santo! Santo! Santo é o SENHOR dos exércitos! Toda a terra está cheia de sua glória!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'E as molduras das portas se moviam com a voz do que clamava; e a casa se encheu de fumaça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Então eu disse: Ai de mim, que vou perecer! Pois sou homem de lábios impuros, e moro no meio de um povo de lábios impuros, e meus olhos viram ao Rei, o SENHOR dos exércitos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Porém um dos serafins voou até mim, trazendo em sua mão uma brasa viva, a qual ele tinha tirado do altar com uma tenaz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'E com ela tocou em minha boca, e disse: Eis que isto tocou em teus lábios; assim já foi afastada de ti tua culpa, e purificado estás de teu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Depois disso ouvi a voz do Senhor, que dizia: A quem enviarei? E quem irá por nós? Então eu disse: Eis-me aqui! Envia-me!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Então ele me disse: Vai, e diz a este povo: certamente ouvireis, mas não entendereis; certamente vereis, mas não percebereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Faze o coração deste povo se encher de gordura, e os ouvidos deles ficarem pesados, para que não vejam com seus olhos, nem ouçam com seus ouvidos, nem entendam com seus corações, e assim não se convertam, nem eu os cure.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'E eu disse: Até quando, Senhor?E ele respondeu: Até que as cidades sejam devastadas, e não fique morador algum, nem homem algum nas casas, e a terra seja devastada por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Porque o SENHOR removerá as pessoas dela,e no meio da terra será grande o abandono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Mas ainda a décima parte ficará nela, e voltará a ser consumida; e como uma grande árvore ou como o carvalho, em que depois de serem derrubados, ainda fica a base do tronco, assim a santa semente será a base dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Sucedeu, pois, nos dias de Acaz, filho de Jotão, filho de Uzias, rei de Judá, que, Rezim, rei da Síria, e Peca, filho de Remalias, rei de Israel, subiram a Jerusalém para fazerem guerra contra ela; mas não conseguiram vencer a batalha contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'E avisaram à casa de Davi, dizendo: Os sírios se aliaram aos de Efraim. Então o coração dele se agitou, e também o coração de seu povo, tal como as árvores do bosque que se agitam com o vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Então o SENHOR disse a Isaías: Agora tu e teu filho Sear-Jasube, saí ao encontro de Acaz, ao final do aqueduto do tanque superior, na estrada do campo do lavandeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'E dize-lhe: Tem cuidado, mas fica calmo; não temas, nem desanime teu coração por causa dessas duas pontas fumegantes de lenha, por causa do ardor da ira de Rezim, dos sírios, e do filho de Remalias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Pois o sírio teve maligno conselho contra ti, com Efraim e com o filho de Remalias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Vamos subir contra Judá, e o aflijamos, e o repartamos entre nós; e façamos reinar como rei no meio dele ao filho de Tabeal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Assim diz o Senhor DEUS: Isso não subsistirá, nem sucederá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Pois a cabeça da Síria é Damasco, e o cabeça de Damasco Rezim; e dentro de sessenta e cinco anos Efraim será quebrado, e não será mais povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'E a cabeça de Efraim é Samaria, e o cabeça de Samaria é o filho de Remalias. Se não crerdes, não ficareis firmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'E o SENHOR continuou a falar a Acaz, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Pede para ti um sinal do SENHOR teu Deus; pede ou de baixo nas profundezas, ou de cima nas alturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Mas Acaz disse: Não pedirei, nem tentarei ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Então Isaías disse: Ouvi agora, ó casa de Davi: Achais pouco cansardes aos homens, para cansardes também a paciência do meu Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Por isso o Senhor, ele mesmo, vos dará um sinal: eis que a virgem conceberá, e fará nascer um filho, e ela chamará seu nome Emanuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Manteiga e mal ele comerá, pois saberá como rejeitar o mal e escolher o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Mas antes que este menino saiba rejeitar o mal e escolher o bem, a terra da qual tendes pavor será desamparada de seus dois reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'O SENHOR fará vir sobre ti, sobre o teu povo, e sobre a casa de teu pai, dias que nunca vieram, desde o dia em que Efraim se desviou de Judá, quando vier o rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Porque acontecerá que naquele dia o SENHOR assoviará às moscas que estão na extremidade dos rios do Egito, e às abelhas que andam na terra da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'E virão, e todas elas pousarão nos vales desabitados, e nas fendas das rochas, e em todos os espinheiros, e em todos os arbustos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Naquele dia o Senhor raspará com uma navalha alugada dalém do rio, por meio do rei da Assíria, a cabeça e os pelos dos pés; e até a barba será tirada por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'E acontecerá naquele dia, que alguém estará criando uma vaca jovem e duas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'E será que, por causa da abundância de leite que lhe derem, ele comerá manteiga; e comerá manteiga e mel todo aquele que for deixado no meio da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Será também naquele dia, que todo lugar em que antes havia mil videiras do valor de dez mil moedas de prata, se tornará lugar para espinhos e para cardos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Que com arco e flechas ali entrarão; porque toda a terra será espinhos e cardos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'E também todos os montes onde costumavam ser cavados com enxadas, não se irá a eles por medo dos espinhos e dos cardos; porém servirão para se enviar bois, e para que gado miúdo pise.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Disse-me também o SENHOR: Toma para ti um grande letreiro, e escreve nele com pena para uso humano: Maer-Salal- Has-Baz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Então tomei comigo testemunhas fiéis: o sacerdote Urias, e Zacarias filho de Jeberequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'E vim até a profetisa, que concebeu e teve um filho; e o SENHOR me disse: Chama o nome dele de Maer-Salal-Has-Baz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'porque antes que o menino saiba falar “papai” ou “mamãe”, as riquezas de Damasco e os despojos de Samaria serão tomados pelo rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'E o SENHOR continuou a a falar comigo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Dado que este povo rejeitou as águas de Siloé, que correm calmamente, e se alegrou com Resim e com o filho de Remalias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Por isso eis que o Senhor fará subir sobre eles as águas do rio fortes e impetuosas: que é o rei da Assíria com todo o sua glória; e subirá sobre todas as suas correntes de águas, e transbordará por todas as suas margens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'E passará por Judá, e o inundará, chegando até o pescoço; e ao estender suas asas, encherá a largura de tua terra, ó Emanuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Ajuntai-vos, povos, e sereis quebrados; e ouvi, todos vós que sois de terras distantes; vesti vossos cintos, e sereis quebrados; preparai vossos cintos para a batalha,mas sereis quebrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Reuni-vos para tomar conselho, mas ele será desfeito; falai alguma palavra, porém ela não se confirmará, porque Deus é conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Porque assim o SENHOR me disse com mão forte; e ele me ensinou a não andar pelo caminho deste povo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Não chameis de conspiração a tudo quanto este povo chama de conspiração; e não temais o que eles temem, nem vos assombreis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Mas ao SENHOR dos exércitos, a ele santificai; e ele seja ele vosso temor, e ele seja vosso assombro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Então ele será como santuário para vós; porém como pedra de ofensa, e por pedra de tropeço para as duas casas de Israel; como laço e como rede para os moradores de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'E muitos dentre eles tropeçarão e cairão; e serão quebrados, enlaçados, e presos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Liga o testemunho; sela a Lei entre meus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Esperarei ao SENHOR, que esconde seus rosto da casa de Jacó; e a ele aguardarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Eis aqui, eu e os filhos que o SENHOR me deu, somos como sinais e como maravilhas em Israel, pelo SENHOR dos exércitos, que habita no monte de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'E quando vos disserem: Consultai aos que se comunicam com os mortos e aos encantadores que murmuram, sussurrando entre os dentes.Por acaso não deveria o povo consultar ao seu Deus? Perguntarão aos mortos por causa dos vivos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Respondei: À Lei e ao testemunho!Se não falarem segundo esta palavra, não haverá amanhecer para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'E passarão pela terra,duramente oprimidos e famintos; e será que, quando tiverem fome e ficarem enfurecidos, então amaldiçoarão ao seu rei e ao seu Deus, olhando para cima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'E olhando para a terra, eis aflição e trevas; haverá angustiante escuridão, e para as trevas serão empurrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Mas não haverá escuridão para aquela que foi angustiada tal como nos primeiros tempos, quando ele afligiu a terra de Zebulom e a terra de Naftali; mas depois ele a honrará junto ao caminho do mar, dalém do Jordão, a Galileia das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'O povo que andava em trevas viu uma grande luz; os que habitavam em terra de sombra de morte, uma luz brilhou sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Tu multiplicaste a este povo, aumentaste-lhe a alegria. Eles se alegraram diante de ti como a alegria da ceifa, como quando ficam contentes ao repartir despojos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Pois tu quebraste o jugo de sua carga, e a vara de seus ombros, o bastão daquele que opressivamente o conduzia, como no dia dos midianitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Quando toda a batalha daqueles que batalhavam era feita com ruído, e as roupas se revolviam em sangue, e eram queimadas para servir de combustível ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Porque um menino nos nasceu, um filho nos foi dado; e o governo está sobre seus ombros; e seu nome se chama Maravilhoso, Conselheiro, Deus Forte, Pai da Eternidade, Príncipe da Paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'À grandeza de seu governo e à paz não haverá fim, sobre o trono de Davi, e sobre seu reino, para o firmar e fortalecer com juízo e justiça desde agora e para sempre; o zelo do SENHOR dos exércitos fará isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'O Senhor enviou uma palavra a Jacó, e ela caiu sobre Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'E todo o povo a saberá: Efraim, e os moradores de Samaria, em soberba e arrogância de coração, dizem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Os tijolos caíram, mas construiremos de novo com pedras talhadas; as figueiras bravas foram cortadas, mas as trocaremos por cedros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Por isso o SENHOR levantará os adversários de Resim contra ele, e instigará seus inimigos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Pela frente virão os sírios, e por trás os filisteus; e devorarão a Israel com a boca aberta. Nem com tudo isto sua ira cessará, e ainda sua mão está estendida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Porque este povo não se converteu àquele que o feriu, nem busca ao SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Por isso o SENHOR cortará de Israel a cabeça, a cauda, o ramo e o junco de Israel em um único dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'O ancião e o homem respeitado, este é a cabeça; e o profeta que ensina falsidade é a cauda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Pois os guias deste povo são enganadores; e os que por eles forem guiados estão a ponto de serem destruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Por causa disso o Senhor não terá alegria em seus rapazes, e não terá piedade de seus órfãos e de suas viúvas; porque todos eles são hipócritas e malfeitores, e toda boca fala tolices; nem com tudo isto sua ira cessará, e sua mão ainda está estendida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Pois a perversidade queima como fogo, que consumirá cardos e espinhos, e incendiará aos emaranhados das árvores da floresta; e subirão como nuvens de fumaça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Pelo furor do SENHOR dos exércitos a terra se inflamará, e o povo será como o combustível do fogo; cada um não terá piedade do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Se cortar à direita, ainda terá fome; e se comer da esquerda, ainda não se saciará; cada um comerá a carne de seu próprio braço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manassés a Efraim, e Efraim a Manassés; e eles ambos serão contra Judá; e nem com tudo isto sua ira cessará, e sua mão ainda está estendida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Ai dos que decretam ordenanças injustas, e dos que escribas que escrevem coisas opressivas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Para afastarem aos pobres de seu direito, e para tomarem o direito dos pobres de meu povo; para despojarem as viúvas, e para roubarem aos órfãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Mas que fareis no dia da visitação e da assolação, que virá de longe? A quem recorrereis por socorro? E onde deixareis vossa glória?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Nada podem fazer,a não ser se abaterem entre os presos, e caírem entre os mortos. Com tudo isto, sua ira não cessará, e sua mão ainda está estendida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Ai da Assíria, a vara de minha ira; porque minha indignação é pão em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Eu a enviarei contra um povo corrompido, e lhe darei ordem contra um povo do qual me enfureço; para que roube ao roubo, e despoje ao despojo, e para que o pisem como a lama das ruas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Ainda que ela não pense assim, nem pretenda isso seu coração; em vez disso, deseja em seu coração destruir e eliminar não poucas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Pois diz: Por acaso os meus generais, não são todos eles reis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Não é Calno como Carquemis? Não é Hamate como Arpade? Não é Samaria como Damasco?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Assim como minha mão tomou aos reinos dos ídolos, cujas imagens eram melhores que Jerusalém e as de Samaria,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Por acaso não farei eu a Jerusalém e a seus ídolos da mesma maneira que fiz a Samaria e a seus ídolos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Porque acontecerá que, quando o Senhor tiver acabado toda sua obra no monte de Sião em Jerusalém, então: Visitarei para castigar o fruto da arrogância da rei da Assíria e a pompa do orgulho de seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Pois ele diz: Fiz isso com a força de minha mão e com minha sabedoria, pois sou esperto; e tirei as fronteiras dos povos, e roubei seus bens, e como guerreiro abati aos moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'E minha mão tomou as riquezas dos povos como a um ninho; e como se juntam ovos abandonados, assim eu juntei toda a terra; e não houve quem movesse asa, ou abrisse boca, ou fizesse ruído.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Por acaso o machado se glorificará contra aquele que com ele corta? Ou a serra se engrandecerá contra aquele que a manuseia? Seria como se fosse o bastão que movesse aos que o levantam, como se a vara fosse capaz de levantar, como se ela não fosse apenas madeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Por isso o Senhor DEUS dos exércitos enviará magreza entre seus gordos; e em lugar de sua glória ele inflamará um incêndio, como um incêndio de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'E a Luz de Israel virá a ser fogo, e seu Santo, labareda, que queima e consome seus espinhos e seus cardos em um dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Também consumirá a glória de sua floresta, e de seu campo fértil, desde a alma até a carne; e será como quando um doente se definha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'E o resto das árvores de sua floresta será tão pouco em número, que um menino será capaz de contá-las.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'E acontecerá naquele dia, que os restantes de Israel e os que escaparam da casa de Jacó nunca mais confiarão naquele que os feriu; ao invés disso, confiarão verdadeiramente no SENHOR, o Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Os restantes se converterão, os restantes de Jacó, ao Deus Forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Porque ainda que teu povo, ó Israel, seja como a areia do mar, apenas o restante dele se converterá; a destruição já está decretada, transbordante em justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Pois a destruição que foi decretada, o Senhor DEUS dos exércitos a executará no meio de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Por isso assim diz o Senhor DEUS dos exércitos: Não temas, povo meu, que habita em Sião, ao assírio, quando te ferir com vara, e contra ti levantar seu bastão da maneira dos egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Pois em breve se completará a indignação e a minha ira, para os consumir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Pois o SENHOR dos exércitos levantará um açoite contra ele, como a matança de Midiã junto à rocha de Orebe; e sua vara estará sobre o mar, a qual ele levantará da maneira que ele fez aos egípcios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'E acontecerá naquele dia, que sua carga será tirada de teu ombro, e seu jugo de teu pescoço; e o jugo será despedaçado por causa da unção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Eles, os assírios,chegaram a Aiate, passaram por Migrom, em Micmás puseram seus instrumentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Passaram o vau, se abrigaram em Geba. Ramá está tremendo, Gibeá de Saul está fugindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Grita com tua voz, ó filha de Galim! Ouve, Laís! Pobre de ti, Anatote!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena foge; os moradores de Gebim procuram refúgios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Ainda hoje parará em Nobe; moverá sua mão contra o monte da Filha de Sião, o morro de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Eis que o Senhor DEUS dos exércitos cortará os galhos com violência; e os de alta estatura serão cortados, e os elevados serão abatidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'E cortará os emaranhados da floresta com machado de ferro; e o Líbano cairá pelo Grandioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'E uma vara brotará do tronco cortado de Jessé; e um ramo crescerá de suas raízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'E repousará sobre ele o Espírito do SENHOR: o Espírito de sabedoria e de entendimento, o Espírito de conselho e força, o Espírito de conhecimento e temor ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'E seu prazer será no temor ao SENHOR; e não julgará segundo a vista de seus olhos, nem repreenderá segundo o ouvir de seus ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Mas julgará com justiça aos pobres, e repreenderá com equidade aos humildes da terra; porém ferirá a terra com a vara de sua boca, e com o espírito de seus lábios matará ao perverso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'E a justiça será o cinto de sua cintura; a fidelidade o cinto de seus lombos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'E o lobo morará com o cordeiro, e o leopardo se deitará com o cabrito; e o bezerro, o filhote de leão, e o animal cevado andarão juntos, e um menino pequeno os guiará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'A vaca e a ursa se alimentarão juntas, seus filhos juntos se deitarão; e o leão comerá palha como o boi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'A criança que ainda mama brincará sobre a toca da serpente, e a que for desmamada porá sua mão na cova da víbora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Não se fará mal nem dano algum em todo o meu santo monte, porque a terra se encherá do conhecimento do SENHOR, como as águas cobrem o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'E acontecerá naquele dia, que as nações buscarão a raiz de Jessé, posta como bandeira dos povos; e seu repouso será glorioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'E acontecerá naquele dia, que o Senhor voltará a pôr sua mão para adquirir de novo aos restantes de seus povo, que restarem da Assíria, do Egito, Patros, Cuxe, Elão, Sinear, Hamate, e das ilhas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'E levantará uma bandeira entre as nações, e juntará aos desterrados de Israel, e reunirá aos dispersos de Judá desde os quatro confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'E a inveja de Efraim terminará, e os adversários de Judá serão cortados; Efraim não invejará a Judá, e Judá não oprimirá a Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Em vez disso, voarão sobre os ombros dos filisteus ao ocidente, e juntos despojarão aos do oriente; porão suas mãos sobre Edom e Moabe, e os filhos de Amom lhes obedecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'E o SENHOR dividirá a porção de mar do Egito, e moverá sua mão contra o rio com a força de seu vento; e o ferirá em sete correntes, e fará com que se possa atravessá-lo com sandálias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'E haverá um caminho para os restantes de seu povo, que restarem da Assíria, assim como aconteceu a Israel, no dia em que subiu da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'E tu dirás naquele dia: Eu te agradeço, SENHOR, pois, ainda que tenhas te irado contra mim, tua ira foi removida, e tu me consolas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Eis que Deus é minha salvação; nele confiarei, e não terei medo; porque minha força e minha canção é o SENHOR DEUS; e ele tem sido minha salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'E alegremente tirareis águas das fontes da salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'E direis naquele dia: Agradecei ao SENHOR, falai em alta voz ao seu nome; informai seus feitos entre os povos, anunciai quão exaltado é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Cantai ao SENHOR, porque ele fez coisas grandiosas; que isto seja conhecido em toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Grita e canta de alegria, ó moradora de Sião; porque o Santo de Israel é grande no meio de ti!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Revelação sobre a Babilônia, vista por Isaías, filho de Amoz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Levantai uma bandeira sobre um alto monte, levantai a voz a eles; movei a mão ao alto, para que entrem pelas portas dos príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Eu dei ordens aos meus santificados; também chamei aos meus guerreiros para minha ira, aos que se alegram com minha glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Há um ruído de tumulto sobre os montes, como o de um imenso povo; ruído de multidões de reinos de nações reunidas; o SENHOR dos exércitos está revistando um exército para a guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Eles vêm de uma terra distante, desde a extremidade do céu; o SENHOR e os instrumentos de seu furor, para destruir toda aquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Gritai lamentando, pois o dia do SENHOR está perto; vem como assolação pelo Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Por isso todas as mãos ficarão fracas, e o coração de todos os homens se derreterá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'E ficarão aterrorizados; serão tomados por dores e angústias; sofrerão como mulher com dores de parto; cada um terá medo de seu próximo, seus rostos serão rostos em chamas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Eis que o dia do SENHOR vem horrendo, com furor e ira ardente, para pôr a terra em assolação, e destruir os pecadores nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Porque as estrelas dos céus e suas constelações não darão sua luz; o sol se escurecerá ao nascer, e a lua não brilhará com sua luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Porque visitarei para punir sobre o mundo a maldade, e sobre os maus sua perversidade; e porei fim à arrogância dos soberbos, e abaterei o orgulho dos tiranos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Farei com que um varão seja mais raro que o ouro maciço, e um homem mais que o ouro fino de Ofir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Por isso farei estremecer aos céus, e a terra se moverá de seu lugar, por causa do furor do SENHOR dos exércitos, e por causa de sua ardente ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'E será que, como uma corça em fuga, e como uma ovelha que ninguém recolhe, cada um se voltará para seu povo, e cada um fugirá para sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Qualquer um que for achado, será traspassado; e qualquer um que se juntar a ele cairá pela espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'E suas crianças serão despedaçadas perante seus olhos; suas casas serão saqueadas, e suas mulheres estupradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Eis que despertarei contra eles aos medos, que não se importarão com a prata, nem desejarão ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'E com seus arcos despedaçarão aos rapazes, e não terão piedade do fruto do ventre; o olho deles não terá compaixão das crianças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Assim será Babilônia, a joia dos reinos, a beleza e o orgulho dos caldeus, semelhante a Sodoma e Gomorra, quando Deus as arruinou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Nunca mais será habitada, nem nela se morará, de geração em geração; nem o árabe armará ali sua tenda, nem os pastores farão descansar ali seus rebanhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Mas os animais selvagens do deserto ali descansarão, e suas casas se encherão de animais medonhos; e ali habitarão corujas, e bodes selvagens saltarão ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'E as hienas uivarão em suas fortalezas, e chacais em seus confortáveis palácios. Pois está chegando bem perto o seu tempo, e os dias dela não se prolongarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Porque o SENHOR terá piedade de Jacó, e ainda escolherá a Israel, e os porá em sua terra; e estrangeiros se juntarão a eles, e se apegarão à casa de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'E os povos os receberão, e os levarão a seus lugares, e a casa de Israel terá posse deles como servos e servas, na terra do SENHOR; e capturarão aos que tinham lhes capturado, e dominarão sobre seus opressores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'E será que, no dia em que o SENHOR te der descanso de teu trabalho e de teu tormento, e da dura escravidão que te escravizaram,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Então levantarás estas palavras de escárnio contra o rei da Babilônia, e dirás: Vede como foi o fim do opressor, como a cidade dourada se acabou!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'O SENHOR quebrou o bastão dos perversos, o cetro dos que dominavam,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Que feria aos povos com furor com golpes sem fim, que com ira dominava as nações, perseguindo sem compaixão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'A terra descansa, já está sossegada; gritam de prazer com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Até os pinheiros se alegram por causa de ti, e os cedros do Líbano, dizendo: Desde que tu caíste, ninguém mais sobe contra nós, para nos cortar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'O mundo dos mortos desde suas profundezas se agitou por causa de ti, para sair ao teu encontro em tua chegada; por causa de ti ele despertou aos mortos, todos os líderes da terra, e fez levantar de seus tronos a todos os reis das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Eles todos responderão e te dirão: Tu enfraqueceste tal como nós, e te tornaste semelhante a nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Tua soberba foi derrubada ao mundo dos mortos, assim como o som de tuas harpas; larvas se espalharão por debaixo de ti, e vermes te cobrirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Como caíste do céu, ó “luminoso”, filho do amanhecer! Cortado foste até a terra, tu que enfraquecias as nações!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'E tu dizias em teu coração: Subirei ao céu; levantarei o meu trono acima das estrelas de Deus, e me sentarei no monte da congregação, nas regiões distantes do norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Subirei sobre as alturas das nuvens, e serei semelhante ao Altíssimo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Porém tu serás derrubado ao mundo dos mortos, às profundezas da cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Os que te olharem prestarão atenção em ti, pensarão, e dirão: É este o homem que abalava a terra, e fazia os reinos tremerem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Que fazia do mundo como um deserto, e arruinava suas cidades? Que nunca soltava seus prisioneiros para suas casas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Todos os reis das nações, eles todos, jazem com honra, cada um em sua própria casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Porém tu és lançado de tua sepultura, como um ramo repugnante, como as roupas dos que foram mortos, traspassados à espada; como os que descem às pedras da cova, como um corpo pisoteado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Não se juntará a eles na sepultura, porque destruíste tua terra, e mataste a teu povo; a semente dos malignos não será nomeada para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Preparai a matança para seus filhos por causa da maldade de seus pais; para que não se levantem, e tomem posse da terra, e encham a face do mundo de cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Porque me levantarei contra eles,diz o SENHOR dos exércitos; e cortarei para eliminar da Babilônia o nome e os restantes, o filho e o neto, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'E eu a porei como propriedade de corujas, e poças d ́água; e a varrerei com a vassoura da destruição,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'O SENHOR dos exércitos jurou, dizendo: Com certeza acontecerá assim como pensei, e será comprido assim como determinei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Quebrarei a Assíria em minha terra, e em minhas montanhas eu a esmagarei; para que seu jugo se afaste deles, e sua carga seja tirada de seus ombros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Este é o plano determinado para toda a terra; e esta é a mão que está estendida sobre todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Pois o SENHOR dos exércitos já determinou; quem invalidará? E sua mão já está estendida; quem a retrocederá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'No ano em que o rei Acaz morreu, houve esta revelação:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Não te alegres, ó tu, Filisteia inteira, por ter sido quebrada a vara que te feria; porque da raiz da cobra sairá uma víbora, e seu fruto será uma venenosa serpente voadora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'E os mais pobres serão apascentados, e os necessitados deitarão em segurança; porém farei tua raiz morrer de fome, e ela matará teus sobreviventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Uiva, ó porta! Grita, ó cidade! Tu, Filisteia inteira, estás a ser derretida; porque do norte vem fumaça, e não há solitário em seus batalhões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Que, pois, se responderá aos mensageiros d aquela nação? Que o SENHOR fundou a Sião, e que nela os oprimidos de seu povo terão refúgio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Revelação sobre Moabe: Certamente em uma noite é destruída Ar-Moabe; e é devastada; certamente em uma noite é destruída Quir-Moabe, e é devastada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Os moradores sobem ao templo, e a Dibom, aos lugares altos, para chorar; Moabe grita de lamento por Nebo e por Medeba; em todas as suas cabeças há calva, e toda barba está raspada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Eles se vestem de sacos em suas ruas; em seus terraços, e em suas praças todos andam gritando de lamento, e descem chorando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Tanto Hesbom como Eleale vão gritando, até Jaaz se ouve sua voz; por causa disso os soldados armados de Moabe gritam, a alma de cada um está abalada dentro de si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Meu coração dá gritos por Moabe, seus fugitivos foram até Zoar e Eglate-Selisia; pois sobem com choro pela subida de Luíte, pois no caminho de Horonaim levantam um grito de desespero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Pois as águas de Ninrim se acabaram; pois a grama se secou, as plantas pereceram, e não há mais vegetal verde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Por isso levarão os bens que acumularam e seus pertences ao ribeiro dos salgueiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Porque o pranto rodeia aos limites de Moabe; até Eglaim chega seu grito de lamento, e até Beer-Elim sua lamentação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Pois as águas de Dimom estão cheias de sangue, porém porei em Dimom ainda outros mais: um leão aos que escaparem de Moabe, e aos sobreviventes da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Enviai os cordeiros ao dominador da terra desde Sela pelo deserto, ao monte da filha de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Pois será que, como o pássaro vagueante, lançado do ninho, assim serão as filhas de Moabe junto aos vaus de Arnom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Toma conselho, faze juízo, põe tua sombra no pino do meio dia como a noite; esconde aos exilados, e não exponhas os fugitivos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Habitem entre ti teus prisioneiros, Moabe; sê tu refúgio para eles da presença do destruidor, porque o opressor terá fim, a destruição terminará, e os esmagadores serão consumidos de sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Porque o trono se firmará em bondade, e sobre ele no tabernáculo de Davi em verdade se sentará um que julgue, e busque o juízo, e se apresse para a justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Já ouvimos a soberba de Moabe, o arrogante ao extremo; sua arrogância, soberba e furor, mas seus orgulhos não são firmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Por isso Moabe gritará de lamento por Moabe; todos eles gritarão de lamento; gemereis pelos fundamentos de Quir-Haresete, pois estão quebrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Pois os campos de Hesbom enfraqueceram, e também a vinha de Sibma, os senhores das nações esmagaram suas melhores plantas, que chegavam a Jezer, e alcançavam o deserto; seus ramos se estendiam, e passavam até o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Por isso lamentarei com pranto por Jezer, a vide de Sibma; eu te regarei com minhas lágrimas, ó Hesbom e Eleale; pois a alegria de teus frutos de verão e de tua colheita caiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'E foram tirados a alegria e o prazer do campo frutífero; e nas vinhas não se canta, nem grito de alegria se faz; o pisador não pisará as uvas nos lagares; eu pus fim aos clamores de alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Por isso meus órgãos fazem ruído por Moabe como um harpa; e meu interior por Quir- Heres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'E será que, quando o povo de Moabe se apresentar e se cansar nos lugares altos, e entrarem em seus templo para orar, nada conseguirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Esta é a palavra que o SENHOR falou sobre Moabe desde então.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Mas agora assim fala o SENHOR, dizendo: Dentro de três anos, (tais como anos de empregado), então se tornará desprezível a glória de Moabe, com toda a sua grande multidão; e os restantes serão muito poucos e sem poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Revelação sobre Damasco: Eis que Damasco será tirada de tal maneira que não será mais uma cidade, mas sim, um amontoado de ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'As cidades de Aroer serão abandonadas; serão para os rebanhos, e ali se deitarão, sem haver quem os espante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'E a fortaleza de Efraim se acabará, como também o reino de Damasco, e os restantes dos sírios; serão como a glória dos filhos de Israel,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'E será naquele dia, que a glória de Jacó se definhará, e a gordura de sua carne emagrecerá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Pois será como o ceifeiro, que colhe os grãos, e com seu braço ceifa as espigas; será também como o que colhe espigas no vale de Refaim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Porém ainda ficarão nele algumas sobras, como no sacudir da oliveira, dois ou três azeitonas ficam na ponta mais alta dos ramos, e quatro ou cinco em seus ramos frutíferos,diz o SENHOR, o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Naquele dia o homem dará atenção ao seu Criador, e seus olhos olharão ao Santo de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'E não dará atenção aos altares, obra de suas próprias mãos, nem olharão para o que seus próprios dedos fizeram, nem para os mastros de Aserá, nem para os altares de incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Naquele dia suas cidades fortificadas serão como plantas abandonadas e os mais altos ramos, os quais eles abandonaram por causa dos filhos de Israel. E haverá assolação,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Pois te esqueceste do Deus de tua salvação, e não te lembraste da rocha de tua fortaleza. Por isso, tu cultivarás belas plantas, e as cercarás de ramos estranhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'No dia que as plantares, tu as farás crescer, e pela manhã farás com que tua semente brote; porém a colheita será perdida no dia de sofrimento e de dores insuportáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Ai da multidão dos muitos povos, que bramam como o bramido do mar; e do rugido das nações, que rugem como o rugido de águas impetuosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'As nações rugirão, como o rugido de muitas águas, porém Deus as repreenderá, e elas fugirão para longe. Serão levadas a fugirem como restos de palhas nos montes diante do vento, como coisas que rolam perante um redemoinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Ao tempo da tarde eis que há pavor; mas antes que amanheça não há mais: Esta é a parte daqueles que nos despojam, e o futuro reservado para aqueles que nos saqueiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Ai da terra dos zumbidos de asas, que está além dos rios de Cuxe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Que envia embaixadores pelo mar, e em navios de junco sobre as águas, com a ordem: Ide, mensageiros velozes, a uma nação de gente alta e de pele lisa, a um povo temido desde seus territórios afora, uma nação dominadora e esmagadora, cuja terra os rios dividem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Vós todos, habitantes do mundo, e vós, moradores da terra, vede quando for levantada a bandeira nos montes, e ouvi quando for tocada a trombeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Porque assim me disse o SENHOR: Estarei quieto olhando desde minha morada, como o calor ardente da luz do sol, como a nuvem de orvalho no calor da ceifa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Porque antes da ceifa, quando a flor já se acabou, e as uvas brotam prestes a amadurecer, então ele podará as vides com a foice e, tendo cortado os ramos, ele os tirará dali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Eles serão deixados juntos para as aves dos montes, e para os animais da terra; e sobre eles as aves passarão o verão, e todos os animais da terra passarão o inverno sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Naquele tempo, será trazido um presente ao SENHOR dos exércitos por um povo alto e de pele lisa, e um povo temível desde seus territórios afora; uma nação dominadora e esmagadora, cuja terra rios dividem, ao lugar que pertence ao nome do SENHOR dos exércitos, ao monte de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Revelação sobre o Egito: Eis que o SENHOR vem montado numa veloz nuvem, e ele virá ao Egito; e os ídolos do Egito tremerão perante sua presença; e o coração dos egípcios se derreterá dentro de si;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Porque instigarei egípcios contra egípcios, e cada um lutará contra seu irmão, e cada um contra seu próximo; cidade contra cidade, reino contra reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'E o espírito dos egípcios se esvaziará dentro de si, e destruirei seu conselho; então eles perguntarão ao ídolos, encantadores, adivinhos que consultam espíritos de mortos, e feiticeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'E entregarei os egípcios nas mãos de um duro senhor, e um rei rigoroso dominará sobre eles,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'E as águas do mar se acabarão; e o rio se esvaziará e se secará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'E os rios terão mau cheiro; os canais do Egito serão esvaziados e se secarão; as canas e os juncos murcharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'A relva junto ao rio, junto às margens dos rio, e todas as plantações junto ao rio se secarão, serão removidas, e se perderão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'E os pescadores gemerão e todos os que lançam anzol no rio lamentarão; e os que estendem rede sobre as águas perderão o ânimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'E ficarão envergonhados os que trabalham com linho fino e os que tecem panos brancos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Os fundamentos serão quebrados, e os empregados sentirão aflição na alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Na verdade, os príncipes de Zoã são uns tolos; o conselho dos “sábios” de Faraó se tornou imprudente. Como é que dizeis a Faraó: Sou filho de sábios, sou descendente dos antigos reis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Onde estão agora os teus sábios? Avisem-te, pois, e informem o que o SENHOR dos exércitos determinou contra o Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Os príncipes de Zoã se tornaram tolos, os príncipes de Nofe estão enganados; e o Egito será levado ao erro pelos que são pedra de esquina de suas tribos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'O SENHOR derramou um espírito de confusão em seu interior, e levaram o Egito a errar em toda a sua obra, tal como o bêbado que se revolve em seu vômito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'E não haverá obra alguma que a cabeça ou a cauda, o ramo ou o junco, possa fazer para proveito do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Naquele dia os egípcios serão como mulheres; e tremerão e temerão por causa do mover da mão do SENHOR dos exércitos, que moverá contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'E a terra de Judá será um assombro ao egípcios; todo aquele que dela lhe mencionarem, terá medo dentro de si, por causa da determinação do SENHOR dos exércitos, que determinou contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Naquele dia haverá cinco cidades na terra do Egito que falem a língua de Canaã e prestem juramento ao SENHOR dos exércitos; uma delas será chamada Cidade da Destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Naquele dia haverá um altar ao SENHOR no meio do Egito, e uma coluna ao SENHOR junto a sua fronteira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'E isso servirá como sinal e como testemunho ao SENHOR dos exércitos na terra do Egito; pois clamarão ao SENHOR por causa de seus opressores, e ele lhes mandará um salvador e defensor que os livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'E o SENHOR se fará conhecido no Egito, e os egípcios conhecerão ao SENHOR naquele dia; e eles o servirão com sacrifícios e ofertas, e farão votos ao SENHOR, e os cumprirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'E o SENHOR ferirá aos egípcios: ferirá mas os curará; e eles se converterão ao SENHOR, e ele aceitará suas orações, e os curará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Naquele dia haverá uma estrada do Egito à Assíria; e os assírios virão ao Egito, e os egípcios à Assíria; e os egípcios prestarão culto junto com os assírios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Naquele dia Israel será o terceiro entre o Egito e a Assíria, uma bênção no meio da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Porque o SENHOR dos exércitos os abençoará, dizendo: Bendito seja o meu povo do Egito, e a Assíria, obra de minhas mãos, e Israel, minha herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'No ano em que o general enviado por Sargom, rei da Assíria, veio a Asdode, guerreou contra Asdode, e a tomou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Naquele tempo o SENHOR falou por meio de Isaías, filho de Amoz, dizendo: Vai, tira a roupa de saco de teus lombos, e descalça a sandália de teus pés.E assim ele fez, andando nu e descalço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Então o SENHOR disse: Assim como meu servo Isaías anda nu e descalço, como sinal e presságio relativo ao Egito e a Cuxe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'assim o rei da Assíria levará em cativeiro a prisioneiros do Egito e a prisioneiros de Cuxe, tanto jovens, como velhos, nus e descalços, e descobertas as nádegas, para envergonhar ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'E terão medo e vergonha por causa de Cuxe, em quem esperavam, e por causa do Egito, no qual se orgulhavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'E os moradores do litoral dirão naquele dia: Vede o que houve com aqueles em quem esperávamos, a quem buscávamos socorro, para nos livrarmos da presença do rei da Assíria! E agora,como escaparemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Revelação sobre o deserto do mar:Assim como os turbilhões de vento passam pelo Negueve, assim algo vem do deserto, de uma terra temível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Uma visão terrível me foi informada: o enganador engana, e o destruidor destrói. Levanta-te, Elão! Faze o cerco, Média! Pois estou pondo fim em todos os gemidos que ela causou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Por isso meus lombos estão cheios de sofrimento; fui tomado por dores, tais como as dores de parto; fiquei perturbado ao ouvir, e estou horrorizado de ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Meu coração se estremece, o terror me apavora; o anoitecer, que eu desejava, agora me causa medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Eles preparam a mesa, estendem tapetes, comem e bebem. Levantai-vos, príncipes! Passai óleo nos escudos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Porque assim me disse o Senhor: Vai, põe um vigilante, e ele diga o que estiver vendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Caso ele veja uma carruagem, um par de cavaleiros, pessoas montadas em asnos, ou pessoas montadas em camelos, ele deve prestar atenção, muita atenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'E ele gritou como um leão: Senhor, na torre de vigia estou continuamente de dia; e em minha guarda me ponho durante noites inteiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'E eis que está vindo uma carruagem de homens, um par de cavaleiros.Então ele respondeu: Caiu! Caiu a Babilônia, e todas as imagens esculpidas de seus deuses foram quebradas contra a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Ó meu povo debulhado por batidas, e trigo de minha eira! O que ouvi do SENHOR dos exércitos, Deus de Israel, isso eu vos disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Revelação sobre Dumá: Alguém está gritando de Seir. Guarda, o que houve de noite? Guarda, o que houve de noite?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'O guarda disse: Vem a manhã, e também a noite; se quereis perguntar, perguntai; voltai-vos, e vinde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Revelação sobre a Arábia:Nos matos da Arábia passareis a noite, ó caravanas de dedanitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Saí ao encontro dos sedentos com água; os moradores da terra de Temá com seu pão encontram aos que estavam fugindo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Pois fogem de diante de espadas, de diante da espada desembainhada, e diante do arco armado, e de diante do peso da guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Porque assim me disse o Senhor: Dentro de um ano (tal como ano de empregado), será arruinada toda a glória de Quedar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'E os que restarem do número de flecheiros, os guerreiros dos filhos de Quedar, serão reduzidos a poucos.Pois assim disse o SENHOR, Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Revelação sobre o vale da visão:O que há contigo, agora, para que tenhas subido toda aos terraços?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Tu cheia de barulhos, cidade tumultuada, cidade alegre! Teus mortos não morreram pela espada, nem morreram na guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Todos os teus líderes juntamente fugiram; foram presos sem nem usarem o arco; todos os teus que foram achados juntamente foram amarrados, ainda que tenham fugido para longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Por isso eu disse: Desviai vossa vista de mim, pois chorarei amargamente; não insistais em me consolar pela destruição da filha do meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Pois foi dia de alvoroço, de atropelamento, e de confusão, proveniente do Senhor DEUS dos exércitos, no vale da visão; dia de muros serem derrubados, e de gritarem ao monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'E Elão tomou a aljava, e houve homens em carruagens, e cavaleiros. Quir descobriu os escudos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'E foi que teus melhores vales se encheram de carruagens de guerra; e cavaleiros se puseram em posição de ataque junto ao portão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'E tiraram a cobertura de Judá; e naquele dia olhastes para as armas da casa do bosque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'E vistes as brechas dos muros da cidade de Davi, que eram muitas; e ajuntastes águas no tanque de baixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Também contastes as casas de Jerusalém; e derrubastes casas para fortalecer os muros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Fizestes também um reservatório entre os dois muros para as águas do tanque velho; porém não destes atenção para aquele que fez estas coisas, nem olhastes para aquele que as formou desde a antiguidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'E naquele dia o Senhor DEUS dos exércitos chamou ao choro, ao lamento, ao raspar de cabelos, e ao vestir de saco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'E eis aqui alegria e festejo, matando vacas e degolando ovelhas, comendo carne, bebendo vinho, e dizendo: Comamos e bebamos, porque amanhã morreremos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Mas o SENHOR dos exércitos se revelou a meus ouvidos, dizendo: Certamente esta maldade não vos será perdoada até que morrais, diz o Senhor DEUS dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Assim disse o Senhor DEUS dos exércitos: Vai, visita este mordomo, Sebna, que administra a casa real,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'E dize-lhe: O que é que tens aqui? Ou quem tu tens aqui, que te dá direito a cavares aqui tua sepultura, como quem cava em lugar alto sua sepultura, e talha na rocha morada para si?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Eis que o SENHOR te lançará fora, ó homem, e te agarrará!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Certamente ele te lançará rodando, como uma bola numa terra larga e espaçosa. Ali morrerás, e ali estarão tuas gloriosas carruagens, para desonra da casa do teu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'E te removerei de tua posição, e te arrancarei de teu assento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'E será naquele dia, que chamarei a meu servo Eliaquim, filho de Hilquias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'E eu o vestirei com tua túnica, e porei nele o teu cinto, e entregarei teu governo nas mãos dele, e ele será como um pai aos moradores de Jerusalém e à casa de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'E porei a chave da casa de Davi sobre seu ombro; quando ele abrir, e ninguém fechará; e quando ele fechar, ninguém abrirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'E eu o fincarei como a um prego em um lugar firme; e ele será um trono de honra à casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'E nele pendurarão toda a honra da casa de seu pai, dos renovos e dos descendentes, todos as vasilhas menores; desde as vasilhas de taças, até todas as vasilhas de jarros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Naquele dia, - diz o SENHOR dos exércitos, - o prego fincado em lugar firme será tirado; e será cortado, e cairá; e a carga que nele está será cortada; porque assim o SENHOR disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Revelação sobre Tiro:Uivai, navios de Társis, pois ela está arruinada, sem sobrar casa alguma, nem entrada nela. Desde a terra do Chipre isto lhes foi informado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Calai-vos, moradores do litoral; vós mercadores de Sidom, que vos enchíeis pelos que atravessavam o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'E sua renda era os grãos de Sior, a colheita do Nilo, que vinha por muitas águas. Ela era o centro de comércio das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Envergonha-te, Sidom; pois o mar falou, a fortaleza do mar disse: Eu não tive dores de parto, nem de mim nasceu criança; nunca criei meninos nem eduquei virgens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Quando as notícias chegarem ao Egito, eles se angustiarão com as informações de Tiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Passai-vos a Társis; uivai, moradores do litoral!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'É esta a vossa alegre cidade? A que existia desde os tempos antigos? Eram os pés dela que a levavam para alcançar lugares distantes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Quem foi, pois, que determinou isto contra Tiro, a que dava coroas, que cujos mercadores eram príncipes, e cujos comerciantes eram os mais ilustres da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Foi o SENHOR dos exércitos que determinou isto, para envergonhar o orgulho de sua beleza, e humilhar a todos os ilustres da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Passa-te como o rio à tua terra, ó filha de Társis, pois já não há mais fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Ele estendeu sua mão sobre o mar, e abalou aos reinos; o SENHOR deu uma ordem contra Canaã, para destruir suas fortalezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'E disse: Nunca mais te encherás de alegria, ó oprimida virgem, filha de Sidom; levanta-te, passa ao Chipre; e alinda ali não terás descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Olhai para a terra dos Caldeus, este que deixou de ser povo. A Assíria a fundou para os que moravam no deserto; levantaram suas fortalezas, e derrubaram seus palácios; transformou-a em ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Uivai, navios de Társis; porque destruída está vossa fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'E será naquele dia, que Tiro será esquecida por setenta anos, como dias de um rei; mas ao fim de setenta anos, haverá em Tiro algo como a canção da prostituta:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Toma uma harpa, rodeia a cidade, ó prostituta esquecida; toca boa música, e canta várias canções, para que tu sejas lembrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Pois será que, ao fim de setenta anos, o SENHOR visitará a Tiro, e voltará à sua atividade, prostituindo-se com todos os reinos do mundo que há sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Mas seu comércio e seus ganhos como prostituta serão consagrados ao SENHOR; não serão guardados nem depositados; mas seu comércio será para os que habitam perante o SENHOR, para que comam até se saciarem, e tenham roupas de boa qualidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Eis que o SENHOR esvazia a terra, e a assola; e transtorna sua superfície, e espalha seus moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'E isso acontecerá, tanto ao povo, como ao sacerdote; tanto ao servo, como a seu senhor; tanto à serva, como a sua senhora; tanto ao comprador, como ao vendedor; tanto a quem empresta, como ao que toma emprestado; tanto ao credor, como ao devedor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'A terra será esvaziada por completo, e será saqueada por completo; pois o SENHOR pronunciou esta palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'A terra chora e se murcha; o mundo enfraquece e se murcha; estão enfraquecidos os mais elevados do povo da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Pois a terra está contaminada por causa de seus moradores; pois transgridem as leis, mudam os estatutos, e anulam o pacto eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Pois isso, a maldição consome a terra; e os que nela habitam pagam por sua culpa; por isso serão queimados os moradores da terra, e poucos homens restarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'O suco de uva chora, a vinha se enfraquece; todos os alegres de coração agora suspiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'A alegria dos tamborins parou, acabou o ruído dos que saltavam de prazer; a alegria da harpa parou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Não beberão vinho com canções; a bebida alcoólica será amarga aos que a beberem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'A cidade da confusão está quebrada; todas as casas estão fechadas; ninguém pode entrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Um clamor de lamento por causa do vinho se ouve nas ruas; toda a alegria se escureceu; o prazer da terra sumiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Só restou assolação na cidade; o portão foi feito em ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Porque assim será por entre a terra, e no meio destes povos; como quando se sacode a oliveira, e como as uvas que sobram depois de terminada a vindima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Eles levantarão sua voz, e cantarão com alegria; por causa da glória do SENHOR, gritarão de alegria desde o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Por isso glorificai ao SENHOR no oriente; e no litoral ao nome do SENHOR, o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Dos confins da terra ouvimos canções para a glória do Justo; mas eu digo: Fraqueza minha, fraqueza minha; ai de mim! Os enganadores enganam, e com enganação os enganadores agem enganosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Temor, cova e laço vem sobre ti, ó morador da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'E será que, aquele que fugir do som de temor cairá na cova; e aquele que subir da cova, o laço o prenderá; pois as janelas do alto se abrem; e os fundamentos da terra tremerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'A terra será quebrada por completo; a terra será totalmente partida, e será muito abalada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'A terra balançará como um bêbado; e será abalada como uma choupana; e sua transgressão pesará sobre ela; cairá, e nunca mais se levantará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'E será que naquele dia o SENHOR visitará para punir aos exércitos do alto na altura, e aos reis da terra sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'E juntamente serão amontoados como presos numa masmorra; e serão encarcerados num cárcere; e muitos dias depois serão visitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'E a lua será envergonhada, e o sol humilhado, quando o SENHOR dos exércitos reinar no monte de Sião, e em Jerusalém; e então perante seus anciãos haverá glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Ó SENHOR, tu és meu Deus; eu te exaltarei, e louvarei o teu nome, pois tu tens feito maravilhas, teus conselhos antigos, com fidelidade e verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Pois tu fizeste da cidade um amontoado de pedras; da cidade fortificada uma ruína; fizeste com que os edifícios dos estrangeiros deixassem de ser cidade, e nunca mais voltem a ser construídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Por isso, um poderoso povo te glorificará, a cidade de nações terríveis te temerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Pois tu foste a fortaleza do pobre, a fortaleza do necessitado, em sua angústia; refúgio contra a tempestade, e sombra contra o calor; porque o sopro dos violentos é como uma tempestade contra o muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Tal como o calor em lugar seco, assim tu abaterás o ímpeto dos estrangeiros; tal como uma espessa nuvem diminui o calor, assim será humilhada a canção dos violentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'E neste monte o SENHOR dos exércitos fará para todos os povos um banquete de animais cevados, um banquete de vinhos finos; de gorduras de tutanos, e de vinhos finos, bem purificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'E neste monte devorará o véu funerário que está sobre todos os povos, e a coberta com que todas as nações se cobrem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Ele devorará a morte para sempre, e o Senhor DEUS enxugará as lágrimas de todos os rostos; e tirará a humilhação de seu povo de toda a terra; pois o SENHOR assim disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'E naquele dia se dirá: Eis que este é o nosso Deus, em quem temos posto nossa esperança para nos salvar; este é o SENHOR, em quem esperamos; em sua salvação teremos prazer e nos alegraremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Pois a mão do SENHOR descansará neste monte; Moabe, porém, será esmagado debaixo dele, tal como se esmaga a palha no amontoado de esterco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'E estenderão suas mãos no meio dela, tal como um nadador estende para nadar; e o SENHOR abaterá a arrogância deles com a habilidade de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'E lançará abaixo as fortalezas de teus muros; ele as abaterá e derrubará até o chão, ao pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Naquele dia, se cantará este cântico na terra de Judá: Temos uma cidade forte! Deus lhe pôs a salvação por muros e antemuros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Abri as portas, para que por elas entre a nação justa, que guarda fidelidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Tu guardarás em completa paz aquele que tem firme entendimento, pois ele confia em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Confiai no SENHOR para sempre, pois no SENHOR DEUS está a rocha eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Pois ele abate aos que habitam em lugares altos, a cidade elevada; certamente ele a abaixará até o chão, e a derrubará até o pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Pés a pisotearão; os pés dos afligidos, os passos dos pobres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'O caminho do justo é todo plano; tu que és reto nivelas o andar do justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Também no caminho dos teus juízos esperamos em ti; em teu nome e em tua lembrança está o desejo de nossa alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Com minha alma te desejei de noite, e com meu espírito dentro de mim te busquei de madrugada; pois quando teus juízos estão sobre a terra, os moradores do mundo aprendem a justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Ainda que se faça favor ao perverso, nem assim ele aprende a justiça; até na terra dos corretos ele pratica maldade, e não dá atenção à majestade do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Ó SENHOR, tua mão está levantada, mas eles não a veem; porém eles verão e serão envergonhados pelo zelo que tens do teu povo; e o fogo consumirá a teus adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Ó SENHOR, tu nos fornecerá paz; pois todos os nossos feitos tu fizeste por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Ó SENHOR nosso Deus, outros senhores fora de ti nos dominaram; mas somente em ti, em teu nome, mantínhamos nossos pensamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Eles estão mortos, não voltarão a viver; fantasmas não ressuscitarão; por isso tu os visitaste e os destruíste, e eliminaste toda a memória deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Tu, SENHOR, engrandeceste esta nação; engrandeceste esta nação, e te fizeste glorioso; alargaste os limites da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Ó SENHOR, na aflição eles te buscaram; quando tu os castigaste, uma oração eles sussurraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Tal como a grávida quando chega a hora do parto, sofre e dá gritos por suas dores, assim fomos nós diante de tua presença, SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Concebemos e tivemos dores, porém geramos nada além de vento. Não trouxemos libertação à terra, nem os moradores do mundo caíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Os teus mortos viverão, junto com meu cadáver, assim ressuscitarão; festejai e sede alegres, vós que habitais no pó! Pois o teu orvalho é orvalho de luz, e a terra gerará de si seus mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Vai, ó povo meu; entra em teus quartos, e fecha tuas portas ao redor de ti; esconde-te por um momento, até que a ira tenha passado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Porque eis que o SENHOR sairá de seu lugar para punir a maldade dos moradores da terra sobre eles; e a terra mostrará seus sangues, e não mais cobrirá seus mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Naquele dia, o SENHOR punirá, com sua dura, grande e forte espada, ao Leviatã, a ágil serpente; ao Leviatã, a serpente tortuosa; e matará o dragão que está no mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Naquele dia, cantai à preciosa vinha:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Eu, o SENHOR, a vigio, e a rego a cada momento; para que ninguém a invada, eu a vigiarei de noite e de dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Já não há furor em mim. Caso alguém ponha contra mim espinhos e cardos, eu lutarei contra eles em batalha, e juntos os queimarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Ou, se quiserem depender de minha força, então façam as pazes comigo, e sejam comigo feitas as pazes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Dias virão em que Jacó lançará raízes, florescerá, e brotará Israel; e encherão superfície do mundo de frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Por acaso ele o feriu, como feriu aos que o feriram? Ou ele o matou, como morreram os que o por ele foram mortos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Com moderação brigaste contra ela, quando a rejeitaste; quando a tirou com seu vento forte, no dia do vento do Oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Portanto assim será perdoada a maldade de Jacó, e este será o fruto completo da remoção de seu pecado: quando tornar todas as pedras dos altares como pedras de cal despedaçadas, e os mastros de Aserá e os altares de incenso não ficarem mais de pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Pois a cidade fortificada será abandonada, o lugar de habitação deixado e desabitado como o deserto; ali os bezerros pastarão, e ali se deitarão e comerão seus ramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Quando seus ramos se secarem, serão quebrados; mulheres virão, e os queimarão; pois este povo não tem entendimento. Por isso, aquele que o criou não terá compaixão dele; aquele que o formou não lhe concederá graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'E será naquele dia, que o SENHOR debulhará o trigo, desde o rio Eufrates até o ribeiro do Egito; porém vós, filhos de Israel, sereis colhidos um a um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'E será naquele dia, que uma grande trombeta será tocada; então os que estiverem perdidos na terra da Assíria e os que tiverem sido lançados à terra do Egito voltarão, e adorarão ao SENHOR no monte santo em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Ai da coroa de arrogância dos bêbados de Efraim, cujo belo ornamento é como uma flor que murcha, que está sobre a cabeça do vale fértil dos derrotados pelo vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Eis que o Senhor tem um valente e poderoso, que vem como tempestade de granizo, tormenta destruidora; e como tempestade de impetuosas águas que inundam; com sua mão ele os derrubará em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'A coroa de arrogância dos bêbados de Efraim será pisada sob os pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'E o seu belo ornamento, que está sobre a cabeça do vale fértil, será como a flor que murcha; como o primeiro fruto antes do verão, que, quando alguém o vê, pega e o come.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Naquele dia o SENHOR dos exércitos será por coroa gloriosa, e por bela tiara, para os restantes de seu povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'E por espírito de juízo, para o que se senta para julgar, e por fortaleza aos que fazem a batalha recuar até a porta da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Mas também estes vacilam com o vinho, e com a bebida alcoólica perdem o caminho: o sacerdote e o profeta vacilam com a bebida alcoólica, foram consumidos pelo vinho; perdem o caminho pela bebida forte, andam confusos na visão, e tropeçam no ato de julgar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Pois todas as suas mesas estão cheias de vômito; não há lugar que não haja imundície.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'A quem ele ensinará o conhecimento? E a quem se explicará a mensagem? A bebês recém-desmamados de leite, tirados dos peitos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Pois tudo tem sido mandamento sobre mandamento, mandamento sobre mandamento, regra sobre regra, regra sobre regra; um pouco aqui, um pouco ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Pois por lábios estranhos e por língua estrangeira se falará a este povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Ao qual dissera: Este é o lugar de descanso; dai descanso ao cansado; e este é o repouso; porém não quiseram ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Assim, pois, a palavra do SENHOR lhes será mandamento sobre mandamento, mandamento sobre mandamento, regra sobre regra, regra sobre regra; um pouco aqui, um pouco ali; para que vão, e caiam para trás, e se quebrem, e sejam enlaçados e capturados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Portanto ouvi a palavra do SENHOR, vós homens escarnecedores, dominadores deste povo, que está em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Pois dizeis: Fizemos um pacto com a morte, e com o mundo dos mortos fizemos um contrato: quando passar a abundância de açoites, não chegará a nós; pois pusemos a mentira como nosso refúgio, e abaixo da falsidade nos escondemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Por isso, assim diz o Senhor DEUS: Eis que eu fundo em Sião uma pedra; uma pedra provada, pedra preciosa de esquina, firmemente fundada; quem crer, não se desesperará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'E porei o juízo como linha de medida, e a justiça como prumo; o granizo varrerá o refúgio da mentira, e as águas inundarão o esconderijo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'E vosso pacto com a morte se anulará, e vosso contrato com o mundo dos mortos não será cumprido; e quando a abundância de açoites passar, então por ela sereis esmagados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Logo que começar a passar, ela vos tomará, porque todas as manhãs passará, de dia e de noite; e será que só de ser dada a notícia, já haverá aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Porque a cama será tão curta, que ninguém poderá se estender nela; e o cobertor tão estreito, que ninguém poderá se cobrir com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Porque o SENHOR se levantará como no monte de Perazim, e se enfurecerá como no vale de Gibeão, para fazer sua obra, sua estranha obra; e operar seu ato, seu estranho ato.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Agora, pois, não escarneçais, para que vossas cordas não vos prendam com ainda mais força; pois eu ouvi do Senhor DEUS dos exércitos sobre uma destruição que já foi determinada sobre toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Inclinai os ouvidos, e ouvi minha voz; prestai atenção, e ouvi o que eu digo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Por acaso o lavrador lavra o dia todo para semear, ou fica o dia todo abrindo e revolvendo a sua terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Quando ele já igualou sua superfície, por acaso ele não espalha endro, e derrama cominho, ou lança do melhor trigo, ou cevada escolhida, ou centeio, cada qual em seu lugar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Pois seu Deus o ensina, instruindo sobre o que se deve fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Porque o endro não é debulhado com uma marreta pesada, nem sobre o cominho se passa por cima com uma roda de carroça; em vez disso, com uma vara se separa os grãos de endro, e com um pau os de cominho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'O trigo é triturado, mas não é batido para sempre; ainda que seja esmagado com as rodas de sua carroça, ele não é triturado com seus cavalos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Até isto procede do SENHOR dos exércitos. Ele é maravilhoso em conselhos, e grande em sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ai de Ariel! Ariel, a cidade em que Davi se acampou. Acrescentai ano a ano, completem-se as festas de sacrifícios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Contudo oprimirei a Ariel, e haverá pranto e tristeza; e ela me será como um altar de sacrifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Pois eu me acamparei ao seu redor, e te cercarei com rampas, e levantarei cercos contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Então serás abatida; falarás junto ao chão, e tua fala será fraca desde o pó da terra, como a de um morto, e tua fala sussurrará desde o pó da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'E a multidão de teus adversários será como o pó fino, e a multidão dos violentos como a palha que passa; e isto acontecerá de repente, em um momento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Pelo SENHOR dos exércitos serás visitada com trovões, terremotos, e grande ruído; com impetuoso vento, tempestade, e labareda de fogo consumidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'E tal como um sonho ou visão noturna, assim será a multidão de todas as nações que batalharão contra Ariel, assim também como todos os que lutaram contra ela e seus muros, e a oprimiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Será também como um faminto que sonha estar comendo, porém, ao acordar, sua alma está vazia; ou como o sedento que sonha estar bebendo, porém, ao acordar, eis que está fraco e com sede na alma; assim será toda a multidão de nações que batalharem contra o monte de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Parai, e maravilhai-vos; cegai-vos, e sede cegos! Estão bêbados, mas não de vinho; cambaleiam, mas não por bebida alcoólica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Pois o SENHOR derramou sobre vós espírito de sono profundo; ele fechou vossos olhos (os profetas), e cobriu vossos cabeças (os videntes).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'E toda visão vos será como as palavras de um livro selado que, quando se dá a um letrado, dizendo: Lê isto, por favor;Esse dirá: Não posso, porque está selado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'E quando se dá o livro a alguém que não saiba ler, dizendo: Lê isto, por favor; Esse dirá: Não sei ler.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Pois o Senhor disse: Visto que este povo se aproxima de mim com a boca, e me honram com seus lábios, porém seus corações se afastam de mim, e fingem que me temem por meio de mandamentos humanos que aprendem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Por isso, eis que continuarei a fazer coisas espantosas com este povo; coisas espantosas e surpreendentes; porque a sabedoria de seus sábios perecerá, e a inteligência dos inteligentes se esconderá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Ai dos que querem se esconder do SENHOR, encobrindo suas intenções; e fazem suas obras às escuras, e dizem: Quem nos vê? Quem nos conhece?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Como é grande vossa perversão! Pode, por acaso, o oleiro ser considerado igual ao barro? Pode a obra dizer de seu criador que “ele não me fez”? Ou o vaso formado dizer de seu formador: “Ele nada entende”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Por acaso não será que,daqui a pouco tempo, o Líbano se tornará um campo fértil? E o campo fértil será considerado uma floresta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'E naquele dia os surdos ouvirão as palavras do livro; e os olhos dos cegos desde a escuridão e desde as trevas as verão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'E os mansos terão cada vez mais alegria no SENHOR; e os necessitados entre os homens se alegrarão no Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Pois os violentos serão eliminados, e os zombadores serão consumidos; e todos os que gostam de maldade serão extintos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Os que acusam aos homens por meio de palavras, e armam ciladas contra quem os repreende na porta da cidade,e os que prejudicam ao justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Portanto, assim o Senhor DEUS, que libertou a Abraão, diz à casa de Jacó: Jacó não será mais envergonhado, nem seu rosto ficará pálido,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Pois quando ele vir seus filhos, obra de minhas mãos, no meio de si, então santificarão ao meu nome; santificarão ao Santo de Jacó, e temerão ao Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'E os confusos de espírito virão a ter entendimento, e os murmuradores aprenderão doutrina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Ai dos filhos rebeldes!,diz o SENHOR, Eles, que tomam conselho, mas não de mim; que fazem um pacto, porém sem o meu Espírito, para acrescentarem pecado sobre pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Eles, que descem ao Egito sem me perguntarem, para se fortificarem com a força de Faraó, e confiarem estar protegidos na sombra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Entretanto, a força de Faraó se tornará vossa vergonha, e a confiança na sombra do Egito será humilhação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Ainda que seus príncipes estejam em Zoã, e seus embaixadores tenham chegado a Hanes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Todos se envergonharão por causa de um povo que em nada lhes será útil, nem de ajuda, nem de proveito; mas, ao invés disso, lhes será vergonha e humilhação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Revelação sobre os animais selvagens do deserto de Negueve: Por entre uma terra da aflição e da angústia, de onde vem o leão forte, o leão velho, a cobra e a serpente voadora, eles levam seus bens nas costas de jumentos, e seus tesouros sobre corcovas de camelos, a um povo que em nada lhes será útil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Porque o Egito os ajudará em vão, e inutilmente. Por isso, a este eu tenho chamado: “Raabe, que nada faz”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Agora vai, e escreve isso numa placa na presença deles, e registra isso num livro, para que dure até o último dia, para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Porque eles são um povo rebelde, são filhos mentirosos, filhos que não querem ouvir a Lei do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Que dizem aos videntes: Não tenhais visões, e aos profetas: Não nos reveleis o que é correto! Dizei coisas agradáveis para nós, revelai ilusões!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Desviai-vos do caminho, afastai-vos da vereda! Deixai de nos fazer deparar com o Santo de Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Portanto, assim diz o Santo de Israel: Visto que rejeitais esta palavra, e vós confiais na opressão e no engano, e nisto vos apoiais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'por isso esta maldade vos será como uma rachadura, prestes a cair, que já encurva um alto muro, cuja queda será repentina e rápida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'E será quebrado como a quebra de um vaso de oleiro, tão esmigalhado que nada se preservará; não se poderá achar um caco sequer entre seus pedacinhos que sirva para transportar brasas de uma fogueira, ou tirar água de um tanque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Pois assim diz o Senhor DEUS, o Santo de Israel: Com arrependimento e descanso, ficaríeis livres; com calma e confiança teríeis força; mas vós não quisestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Ao invés disso, dissestes: Não, é melhor fugirmos sobre cavalos. Cavalgaremos em rápidos cavalos! Por isso vós fugireis, mas vossos perseguidores serão ainda mais rápidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Ao grito de um, mil fugirão, e ao grito de cinco, todos vós fugireis; até que sejais deixados solitários,como um mastro no cume do monte, como uma bandeira num morro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Por isso o SENHOR esperará para ter piedade de vós; e por isso ele se exaltará, para se compadecer de vós; pois o SENHOR é Deus de juízo; bem-aventurados todos os que nele esperam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Pois o povo habitará em Sião, em Jerusalém; certamente não continuarás a chorar; ele terá piedade de ti sob a voz do teu clamor; quando a ouvir, ele te responderá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'De fato, o Senhor vos dará pão de angústia, e água de opressão; porém teus instrutores nunca mais se esconderão de ti; ao contrário, teus olhos verão os teus instrutores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'E quando virardes para a direita ou para a esquerda, teus ouvidos ouvirão a palavra do que está atrás de ti, dizendo: Este é o caminho; andai por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'E considerarás tuas esculturas recobertas de prata e tuas imagens revestidas de ouro como impuras; tu as jogarás fora como se fossem panos imundos, e dirás a cada uma delas: Fora daqui!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Então ele dará chuva sobre tuas sementes que tu tiveres semeado a terra, assim como pão produzido da terra; e esta será fértil e farta; naquele dia teu gado pastará em grandes pastos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Os bois e os jumentos que lavram a terra comerão forragem de boa qualidade, limpa com a pá e o forcado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'E em todo monte alto e todo morro elevado haverá ribeiros e correntes de águas, no dia da grande matança, quando as torres caírem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'E a luz da lua será como a luz do sol, e a luz do sol será sete vezes maior, como a luz de sete dias, quando o SENHOR atar a fratura de seu povo, e curar a chaga de sua ferida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Eis que o nome do SENHOR vem de longe; sua ira está ardendo, e a carga é pesada; seus lábios estão cheios de ira, e sua língua está como um fogo consumidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'E seu sopro como um rio que inunda, chegando até o pescoço, para sacudir as nações com a peneira da inutilidade; e um freio nos queixos dos povos os fará andar perdidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Um cântico haverá entre vós, tal como na noite em que se santifica uma festa; haverá também alegria de coração, tal como aquele que anda com uma flauta para vir ao monte do SENHOR, à Rocha de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'E o SENHOR fará com que ouçam a glória de sua voz, e com que vejam a descida de seu braço, com indignação de ira, e labareda de fogo consumidor, raios, tempestade, e pedra de granizo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Pois com a voz do SENHOR, a Assíria será feita em pedaços; ele a ferirá com a vara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'E será que, em todos os golpes do bordão da firmeza que o SENHOR lhe der, será acompanhado de tamborins e harpas; e com ataques agitados ele a atacará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Pois Tofete já está preparada desde muito tempo, e já está pronta para o rei; ele a fez profunda e larga; sua pira tem muito fogo e lenha; o sopro do SENHOR, como uma correnteza de enxofre, a acenderá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Ai dos que descem ao Egito em busca de ajuda, e põem sua esperança em cavalos, e confiam em carruagens, por serem muitas, e em cavaleiros, por serem fortes; e não dão atenção ao Santo de Israel, nem buscam ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Porém ele é sábio também; ele fará vir o mal, e não volta atrás em suas palavras; ele se levantará contra a casa dos malfeitores, e contra a ajuda dos que praticam perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Pois os egípcios não são Deus, mas sim, homens; seus cavalos são carne, e não espírito; e o SENHOR estenderá sua mão, e fará tropeçar o que ajuda, e cair o ajudado; e todos juntos serão consumidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Porque assim me disse o SENHOR: Tal como o leão e o filhote de leão rugem sobre sua presa, ainda que contra ele seja chamada uma multidão de pastores; ele não se espanta por suas vozes, nem se intimida por seu grande número; assim também o SENHOR dos exércitos descerá para lutar sobre o monte de Sião, e sobre o seu morro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Tal como as aves voam ao redor de seu ninho,assim o SENHOR dos exércitos protegerá a Jerusalém; por sua proteção ele a livrará, e por sua passagem ele a salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Convertei-vos a aquele contra quem os filhos de Israel se rebelaram tão profundamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Porque naquele dia cada um rejeitará seus ídolos de prata, e seus ídolos de ouro, que vossas mãos fizeram para vós pecardes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'E a Assíria cairá pela espada, mas não de homem; uma espada que não é humana a consumirá; e ela fugirá da espada, e seus rapazes serão submetidos a trabalhos forçados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Sua rocha se enfraquecerá de medo, e seus príncipes terão pavor da bandeira; isto diz o SENHOR, cujo fogo está em Sião, e sua fornalha em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Eis que um rei reinará com justiça, e príncipes governarão conforme o juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'E cada homem será como um abrigo contra o vento, e refúgio contra a tempestade; como ribeiros de águas em lugares secos, como a sombra de uma grande rocha num lugar deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'E os olhos dos que vem não se ofuscarão; e os ouvidos dos que ouvem estarão atentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'E o coração dos imprudentes entenderá o conhecimento, e a língua dos gagos estará pronta para falar com clareza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Nunca mais o tolo será chamado de nobre, nem o avarento de generoso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Pois o tolo fala tolices, e seu coração opera maldade, para praticar perversidade e falar enganos contra o SENHOR, para deixar vazia a alma do faminto, e fazer com que o sedento não tenha o que beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Os instrumentos do avarento são maléficos; ele trama planos malignos para destruir aos aflitos com palavras falsas, mesmo quando o pobre fala com justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mas o nobre pensa em coisas nobres, e em coisas nobres ele permanece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Levantai-vos, mulheres que estais em repouso, e ouvi a minha voz; ó filhas, que estais tão confiantes, dai ouvidos às minhas palavras:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Daqui a um ano e alguns dias, sereis perturbadas, vós, que estais tão confiantes; porque a produção de uvas não terá sucesso, e a colheita não virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Tremei vós que estais em repouso, e sede perturbadas, vós que estais tão confiantes; despi-vos, e ficai nuas, e vesti vossos lombos com roupa de saco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Lamentai-vos batendo em vossos peitos por causa dos campos agradáveis e das vides frutíferas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Por causa da terra do meu povo, na qual espinhos e cardos crescerão; e por causa das casas de alegria na cidade alegre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Pois o palácio será abandonado, a cidade ruidosa ficará deserta; a colina e as torres de guarda serão esvaziadas para sempre, para alegria dos jumentos selvagens, e servirão de pasto para o gado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Até que seja derramado sobre nós o Espírito do alto; então o deserto se tornará um lugar fértil, e o lugar fértil será considerado uma floresta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'E o juízo habitará no deserto, e a justiça morará no campo fértil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'E a consequência da justiça será paz; e o produto da justiça, repouso e segurança para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'E meu povo habitará na morada da paz, em moradias bem seguras, em tranquilos lugares de descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, '(Granizo, porém, derrubará a floresta, e a cidade será abatida).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Bem-aventurados sois vós, os que semeais sobre todas as águas; e deixais livres os pés do boi e do jumento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Ai de ti, assolador, que não foste assolado, e que enganas sem ter sido enganado! Quando terminares de assolar, tu é que serás assolado; quando terminares de enganar, então te enganarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Ó SENHOR, tem misericórdia de nós! Em ti temos esperança. Que tu sejas nossa força nas madrugadas, e nossa salvação no tempo de aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Ao som do ruído estrondoso, fugirão; quando tu te levantas, as nações se dispersam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Então, nações,vossos despojos serão colhidos tal como os insetos colhem; tal como os gafanhotos saltam, assim saltarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Exaltado é o SENHOR, pois habita nas alturas; ele encheu a Sião de juízo e justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Ele é a segurança de teus tempos, e a fonte de tua salvação, sabedoria e conhecimento; o temor ao SENHOR é seu tesouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Eis que os embaixadores deles estão gritando de fora; os mensageiros de paz estão chorando amargamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'As estradas estão vazias, não há quem passe pelos caminhos; o pacto foi desfeito, cidades foram desprezadas, ninguém é considerado importante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'A terra lamenta e se definha; o Líbano se envergonha e se seca; Sarom se tornou com um deserto; e Basã e Carmelo foram sacudidos, tiradas suas folhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Agora eu me levantarei,diz o SENHOR; agora me elevarei; agora serei exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Concebestes palha, gerais restos de cascas; vosso sopro vos consumirá como o fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'E os povos serão como incêndios de cal; tal como espinhos cortados, eles se queimarão no fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Vós que estais longe, ouvi o que eu tenho feito; e vós que estais perto, conhecei o meu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Os pecadores em Sião estão assombrados; o tremor tomou os perversos; eles dizem: Quem dentre nós pode conviver com o fogo consumidor? Quem dentre nós pode conviver com as labaredas eternas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'O que anda em justiça, e que fala o que é correto; que rejeita o ganho proveniente de opressões, que com suas mãos faz o gesto de “não” aos subornos, que tapa seus ouvidos para não ouvir sobre crimes de sangue, e fecha seus olhos para não ver o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Este morará nas alturas; fortalezas de rochas serão seu abrigo; ele será provido de pão, e suas águas serão garantidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Teus olhos verão o rei em sua formosura; e verão uma terra que se estende até longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Teu coração pensará sobre o assombro, dizendo: Onde está o escriba? Onde está o tesoureiro? Onde está o que contava as torres?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Não verás mais aquele povo atrevido, povo de fala tão profunda, que não se pode compreender, de língua tão estranha, que não se pode entender.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Olhai para Sião, a cidade de nossas solenidades; teus olhos verão Jerusalém, morada tranquila, tenda que não será derrubada, cujas estacas nunca serão arrancadas, e nenhuma de suas cordas se arrebentará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Mas ali o SENHOR será grandioso para nós: ele será um lugar de rios e correntes largas; nenhum barco a remo passará por eles, nem navio grande navegará por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Pois o SENHOR é nosso juiz; o SENHOR é nosso legislador; o SENHOR é nosso Rei, ele nos salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Tuas cordas se afrouxaram; não puderam manter firme o seu mastro, nem estenderam a vela; então uma grande quantidade de despojos será repartida; até os aleijados tomarão despojos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'E nenhum morador dirá: Estou enfermo; porque o povo que nela habitar será perdoado de sua perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Vós nações, achegai-vos para ouvir; e vós povos, escutai; que a terra ouça, e tudo quanto ela contém; o mundo, e tudo quanto ele produz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Pois a ira do SENHOR está sobre todas as nações, e seu furor sobre todo os exércitos delas; ele as destruirá, e as entregará à matança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'E seus mortos serão lançados fora, e de seus corpos sairá seu fedor; e os montes se derreterão com seu sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'E todo o exército do céu se desfará, e os céus se enrolarão como um rolo de pergaminho; e todo o seu exército cairá, como cai a folha da vide, como cai o figo da figueira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Pois minha espada se embebedou no céu; eis que descerá sobre Edom, sobre o povo a quem condenei à destruição, para o julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'A espada do SENHOR está cheia de sangue, está untada de gordura de sangue de cordeiros e de bodes, da gordura de rins de carneiros; porque o SENHOR tem sacrifício em Bozra, e grande matança na terra dos edomitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'E os bois selvagens descerão com eles, e os bezerros com os touros; e a terra deles beberá sangue até se fartar, e seu pó da terra de gordura será untado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Porque será o dia da vingança do SENHOR, ano de pagamentos pela briga contra Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'E seus ribeiros se tornarão em piche, e seu solo em enxofre; e sua terra em piche ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Nem de noite, nem de dia se apagará, para sempre sua fumaça subirá; de geração em geração será assolada; para todo o sempre ninguém passará por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Mas o pelicano e a coruja tomarão posse dela, a ave selvagem e o corvo nela habitarão; pois o SENHOR estenderá sobre ela o cordel da assolação e o prumo da ruína.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Chamarão ao seus nobres ao reino, porém nenhum haverá ali; e todos os seus príncipes se tornarão coisa nenhuma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'E em seus palácios crescerão espinhos; urtigas e cardos em suas fortalezas; e será habitação de chacais e habitação de avestruzes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'E os animais do deserto se encontrarão com os lobos, e o bode berrará ao seu companheiro; os animais noturnos ali pousarão, e acharão lugar de descanso para si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Ali a coruja fará seu ninho e porá ovos,e tirará seus filhotes, e os recolherá debaixo de sua sombra; também ali os abutres se ajuntarão uns com os outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Buscai no livro do SENHOR, e lede; nenhuma destas criaturas falhará, nenhuma destas faltará com sua companheira; pois de minha própria boca ele mandou, e seu próprio Espírito as ajuntará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Pois ele mesmo lhes deu terreno, e sua mão repartiu para elas com o cordel; para sempre terão posse dela, geração após geração nela habitarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'O deserto e o lugar seco terão prazer disto; e o lugar desabitado se alegrará e florescerá como a rosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Abundantemente florescerá, e também se encherá de alegria e júbilo; a glória do Líbano lhe será dada, a honra do Carmelo e de Sarom; eles verão a glória do SENHOR, a honra de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Fortalecei as mãos fracas, e firmai os joelhos que tremem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Dizei aos perturbados de coração: Fortalecei-vos! Não temais! Eis que nosso Deus virá para a vingança, aos pagamentos de Deus; ele virá e vos salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Então os olhos dos cegos serão abertos, e os ouvidos dos surdos se abrirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Então os aleijados saltarão como cervos, e a língua dos mudos falará alegremente; porque águas arrebentarão no deserto, e ribeiros no lugar desabitado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'E a terra seca se tornará em lagoas, e a terra sedenta em mananciais de águas; nas habitações em que repousavam os chacais, haverá erva com canas e juncos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'E ali haverá uma estrada, e um caminho que se chamará caminho da santidade; o impuro não passará por ele, mas será para os que podem andar pelo caminho; até mesmo os tolos que por ele passarem não errarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Ali não haverá leão, nem animal selvagem subirá a ele, nem se achará nele; porém os redimidos por ele andarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'E os resgatados do SENHOR voltarão, e virão a Sião com júbilo, e alegria eterna haverá sobre suas cabeças; eles terão prazer e alegria, e a tristeza e o gemido deles fugirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'E aconteceu no décimo quarto ano do rei Ezequias, que Senaqueribe, rei da Assíria, subiu contra todas as cidades fortificadas de Judá, e as tomou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Então o rei da Assíria enviou a Rabsaqué, de Laquis a Jerusalém, ao rei Ezequias, com um grande exército; e ele parou junto ao duto do tanque superior, junto ao caminho do campo do lavandeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Então saíram ao encontro dele Eliaquim, filho de Hilquias, o administrador da casa real; Sebna, o escriba, e Joá, filho de Asafe, o cronista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'E Rabsaqué lhes disse: Dizei, pois, a Ezequias: Assim diz o grande rei, o rei da Assíria: Que confiança é essa, em que confias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Eu, de fato, digo, que teus conselhos e poder de guerra são apenas palavras vazias. Em quem, pois, confias, para te rebelares contra mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Eis que confias no Egito, aquele bastão de cana quebrada, em quem se alguém se apoiar, entrará pela mão e a perfurará; assim é Faraó, rei do Egito, para com todos os que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Porém, se me disseres: Confiamos no SENHOR, nosso Deus; Por acaso não é este aquele cujos altos e cujos altares Ezequias tirou, e disse a Judá e a Jerusalém: Perante este altar adorareis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Agora, pois, submeta-te à proposta do meu senhor, o rei da Assíria; e eu te darei dois mil cavalos, se tu podes dar dois mil cavaleiros para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Como, pois, te oporias a um chefe dentre os menores servos do meu senhor, apenas confiando nas carruagens e cavaleiros do Egito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Ora, subi eu sem o SENHOR contra esta terra, para destruí-la? O próprio SENHOR me disse: Sobe contra esta terra, e destrói-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Então Eliaquim, Sebna e Joá disseram a Rabsaqué: Pedimos que fale a teus servos em aramaico, porque nós o entendemos; e não nos fale na língua judaica, aos ouvidos do povo, que está sobre o muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Porém Rabsaqué disse: Por acaso meu senhor me mandou falar estas palavras só a teu senhor e a ti, e não também aos homens que estão sentados sobre o muro, que juntamente convosco comerão suas próprias fezes, e beberão sua própria urina?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Então Rabsaqué se pôs de pé, clamou em alta voz na língua judaica, e disse: Ouvi as palavras do grande rei, o rei da Assíria!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Assim diz o rei: Que Ezequias não vos engane, pois ele não poderá vos livrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Nem deixeis que Ezequias vos faça confiar no SENHOR, dizendo: Com certeza o SENHOR nos livrará; esta cidade não será entregue nas mãos do rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Não escuteis a Ezequias; porque assim diz o rei da Assíria: fazei as pazes comigo, e saí até mim; e cada um com de sua vide, e de sua figueira, e cada um beba a água de sua própria cisterna;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Até que eu venha, e vos leve a uma terra como a vossa, terra de trigo e de suco de uva, terra de pão e de vinhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Que Ezequias não vos engane, dizendo: O SENHOR nos livrará; por acaso os deuses das nações livraram cada um sua terra das mãos do rei da Assíria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Onde estão os deuses de Hamate e de Arpade? Onde estão os deuses de Sefarvaim? Por acaso eles livraram a Samaria das minhas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Quem são dentre todos os deuses destas terras, que livraram sua terra das minhas mãos? Como, pois, o SENHOR livrará a Jerusalém das minhas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Porém eles ficaram calados, e nenhuma palavra lhe responderam; porque tinham ordem do rei, dizendo: Não lhe respondereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Então Eliaquim, filho de Hilquias, o administrador da casa real, e Sebna, o escriba, e Joá filho de Asafe, o cronista, vieram a Ezequias com as roupas rasgadas, e lhe contaram as palavras de Rabsaqué.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'E aconteceu que, quando o rei Ezequias ouviu isso,ele rasgou suas roupas, cobriu-se de saco, e entrou na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Então ele enviou Eliaquim o administrador da casa real, Sebna o escriba, e os anciãos dos sacerdotes, cobertos de sacos, ao profeta Isaías, filho de Amoz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'E lhe disseram: Assim diz Ezequias: Este dia é um dia de angústia, de repreensão, e de blasfêmia; pois os filhos chegaram ao parto, porém não há força para que possam nascer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Talvez o SENHOR venha a ouvir as palavras de Rabsaqué, a quem seu senhor, o rei da Assíria, enviou, para afrontar ao Deus vivente; e repreenda as palavras que o SENHOR teu Deus tem ouvido. Faze, pois, oração pelos restantes, que ainda se encontram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'E os servos do rei vieram até Isaías,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'E Isaías lhes disse: Assim direis a vosso senhor: Assim diz o SENHOR: Não temas das palavras que ouviste, com as quais os servos do rei da Assíria me blasfemaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Eis que porei nele um espírito de tal maneira que, quando ouvir um rumor, ele voltará à sua terra; e eu o derrubarei pela espada em sua própria terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Então Rabsaqué voltou, e achou ao rei da Assíria lutando contra Libna, pois tinha ouvido que ele já tinha saído de Laquis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'E ele, ao ouvir dizer que Tiraca, rei de Cuxe, tinha saído para fazer guerra contra ele, então, após ouvir, enviou mensageiros a Ezequias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Assim falareis a Ezequias, rei de Judá, dizendo: Que teu Deus, em quem confias, não te engane, dizendo: Jerusalém não será entregue nas mãos do rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Eis que tens ouvido o que os reis da Assíria fizeram a todas as terras, destruindo-as por completo. E tu, escaparias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Por acaso as livraram os deuses das nações as quais meus pais destruíram, tal como Gozã, Harã e Rezefe, e os filhos de Éden que estavam em Telassar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Onde está o rei da Hamate, o rei de Arpade, o rei de Sefarvaim, ou Hena e Iva?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'E Ezequias, recebendo as cartas das mãos dos mensageiros, e tendo as lido, subiu à casa do SENHOR, e Ezequias as estendeu perante o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Então Ezequias orou ao SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Ó SENHOR dos exércitos, Deus de Israel, que habitas entre os querubins; tu, só tu, és Deus de todos os reinos da terra; tu fizeste os céus e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Inclina teu ouvido, ó SENHOR, e ouve; abre os teus olhos, SENHOR, e olha; e ouve todas as palavras de Senaqueribe que ele enviou para afrontar o Deus vivente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'É verdade, SENHOR, que os reis da Assíria assolaram a todas as terras e seus territórios,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'E lançaram seus deuses ao fogo, porque não eram deuses, mas sim obras de mãos humanas, madeira e pedra; por isso os destruíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Agora, SENHOR nosso Deus, livra-nos das mãos dele, e assim todos os reinos da terra saberão que tu, só tu, és o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Então Isaías, filho de Amós, mandou dizer a Ezequias: Assim diz o SENHOR, Deus de Israel: Quanto ao que me pediste sobre Senaqueribe, rei da Assíria,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Esta é a palavra que o SENHOR falou sobre ele: A virgem, a filha de Sião, te despreza, zomba de ti; a filha de Jerusalém balança a cabeça após ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'A quem afrontaste? De quem blasfemaste? E contra quem levantaste a voz, e levantaste aos olhos arrogantemente? Contra o Santo de Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Por meio de teus servos afrontaste ao Senhor, e disseste: Com a minha multidão de carruagens eu subi aos cumes dos montes, aos lugares remotos do Líbano; e cortarei seus altos cedros, e seus melhores ciprestes, e virei a seu extremo cume, ao bosque de seu campo fértil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Eu cavei, e bebi as águas; e com as plantas dos meus pés secarei todos os rios do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Por acaso não ouviste que desde muito antes eu fiz isto, e deste os dias antigos o tinha planejado? Agora eu fiz isto acontecer, para que tu fosses o que destruirias as cidades fortificadas, reduzindo-as a amontoados de ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Por isso os moradores delas, com as mãos impotentes, ficaram atemorizados e envergonhados; eram como a erva do campo, e a grama verde, o capim dos telhados e o trigo queimado antes de crescer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Porém eu sei o teu sentar, o teu sair, o teu entrar, e o teu furor contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Por causa de teu furor contra mim, e teu tumulto que subiu aos meus ouvidos, por isso porei meu anzol em teu nariz, e meu freio em tua boca; e te farei voltar pelo caminho em que vieste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'E isto será por sinal para ti, Ezequias: este ano se comerá daquilo que nascer de si mesmo, e no segundo ano do que daí proceder; porém no terceiro ano semeai e colhei; e plantai vinhas, e comei seus frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Pois os sobreviventes da casa de Judá, o remanescente, voltará a formar raízes abaixo, e dará fruto acima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Porque de Jerusalém sairá o remanescente, e do monte de Sião os que sobreviverem; o zelo do SENHOR dos exércitos fará isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Portanto assim diz o SENHOR quanto ao rei da Assíria: Ele não entrará nesta cidade, nem lançará flecha nela; nem também virá diante dela com escudo, nem levantará cerco contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Pelo mesmo caminho que veio, nele voltará; mas nesta cidade ele não entrará, diz o SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Porque eu defenderei esta cidade para a livrar, por causa de mim e por causa do meu servo Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Então o anjo do SENHOR saiu, e feriu no acampamento dos assírios cento e oitenta mil deles; e levantando-se pela manhã cedo, eis que todos eram cadáveres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Assim Senaqueribe, rei da Assíria, partiu-se, e foi embora, voltou, e ficou em Nínive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'E sucedeu que, enquanto ele estava prostrado na casa de seu deus Nisroque, seus filhos Adrameleque e Sarezer o feriram a espada; então eles escaparam para a terra de Ararate; e Esar-Hadom, seu filho, reinou em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Naqueles dias Ezequias ficou doente, perto de morrer. E veio até ele Isaías, filho de Amoz, e lhe disse: Assim diz o SENHOR: Põe em ordem a tua casa, porque morrerás, e não viverás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Então Ezequias virou o seu rosto para a parede, e orou ao SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'E disse: Ó SENHOR, lembra-te, eu te peço, de que andei diante de ti com fidelidade e com coração íntegro, e fiz o que era agradável aos teus olhos! E Ezequias chorou com muito lamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Então veio a palavra do SENHOR a Isaías, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Vai, e diz a Ezequias: Assim diz o SENHOR, o Deus de teu pai Davi: Eu ouvi tua oração, e vi tuas lágrimas. Eis que acrescento quinze anos aos teus dias de vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'E das mãos do rei da Assíria eu livrarei a ti, e a esta cidade; e defenderei esta cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'E isto te será por sinal da parte do SENHOR, de que o SENHOR cumprirá esta palavra que falou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Eis que voltarei voltar a sombra dos degraus nos quais o sol desceu na escadaria de Acaz; dez degraus atrás.Assim voltou o sol dez degraus, pelos degraus que já tinha descido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Escritura de Ezequias, rei de Judá, quando ficou doente, e se sarou de sua enfermidade:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Disse eu: No melhor de minha vida, irei às portas do mundo dos mortos; privado estou do resto dos meus anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Eu disse: Não verei mais ao SENHOR, o SENHOR na terra dos viventes; não mais olharei aos homens com os que habitam o mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Minha morada foi removida e tirada de mim, como uma tenda de pastor; enrolei minha vida como um tecelão; ele me cortará fora do tear; desde o dia até a noite tu me acabarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Fiquei esperando até a manhã; como um leão ele quebrou todos os meus ossos; desde o dia até a noite tu me acabarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Como o grou, ou a andorinha, assim eu fazia barulho; e gemia como uma pomba; ao alto eu levantava meus olhos. Ó SENHOR, estou oprimido! Sê tu minha segurança!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Que direi? Tal como ele me falou, assim fez; passarei lentamente por todos os meus anos, por causa da amargura de minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Ó Senhor, por estas coisas é que se vive, e em todas elas está a vida de meu espírito. Então cura-me, e deixa-me viver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Eis que para meu próprio bem tive grande amargura; tu, porém, com amor livraste minha alma da cova do perecimento; porque lançaste para trás de ti todos os meus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Porque o mundo dos mortos não te louvará, nem a morte te glorificará; nem esperarão em tua fidelidade os que descem a cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'O vivente, o vivente, esse é o que te louvará, tal como hoje eu faço; o pai ensinará aos filhos tua fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'O SENHOR tem me salvado! Por isso tocaremos canções com instrumentos de cordas todos os dias de nossa vida na casa do SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Pois Isaías havia dito: Tomem uma pasta de figos, e passem-na sobre a inflamação, que ele sarará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Ezequias também tinha dito: Qual será o sinal de que subirei à casa do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Naquele tempo, Merodaque-Baladã, filho de Baladã, rei da Babilônia, enviou mensageiros com cartas e um presente a Ezequias, porque tinha ouvido que ele havia ficado doente e já tinha se curado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'E Ezequias se alegrou com eles, e lhes mostrou a casa de teu tesouro, a prata, o ouro, as especiarias, os melhores óleos, e toda a sua casa de armas, e tudo quanto se achou em seus tesouros; coisa nenhuma houve, nem em sua casa, nem em todo o seu domínio, que Ezequias não lhes mostrasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Então o profeta Isaías veio ao rei Ezequias, e lhe disse: O que aqueles homens disseram? E de onde eles vieram a ti?E Ezequias disse: Eles vieram a mim de uma terra distante, da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'E ele lhe disse: O que viram em tua casa?E Ezequias disse: Eles viram tudo quanto há em minha casa; coisa nenhuma há em meus tesouros que eu não tenha lhes mostrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Então Isaías disse a Ezequias: Ouve a palavra do SENHOR dos exércitos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Eis que vem dias em que tudo quanto houver em tua casa, e que teus pais acumularam até o dia de hoje, será levado à Babilônia; nada restará, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'E até de teus filhos, que procederem de ti, e tu gerares, tomarão; e eles serão eunucos no palácio do rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Então Ezequias disse a Isaías: Boa é a palavra do SENHOR que falaste.Disse também: Pois haverá paz e segurança em meus dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Consolai, consolai a meu povo, diz vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Falai ao coração de Jerusalém, e proclamai a ela, que seu esforço de guerra está terminado, que sua perversidade está perdoada; porque já recebeu punição em dobro da mão do SENHOR por todo os seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Voz do que clama no deserto: Preparai o caminho do SENHOR; endireitai na terra estéril vereda ao nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Todo vale será levantado, e todo monte e morro serão abaixados; e o torto se endireitará, e o terreno acidentado se tornará plano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'E a glória do SENHOR se manifestará; e toda carne juntamente verá; pois assim falou a boca do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Uma voz: Clama!E ele disse: O que clamarei? Que toda carne é erva, e toda a sua bondade como as flores do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'A erva se seca, as flores caem, porque o Espírito do SENHOR nelas sopra; verdadeiramente o povo é erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'A erva se seca, as flores caem; porém a palavra do nosso Deus continua firme para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Ó Sião, que anuncias boas novas, sobe até um monte alto! Ó Jerusalém, que anuncias boas novas, levanta tua voz com força; levanta-a, não temas; dize as cidades de Judá: Eis aqui o vosso Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Eis que o Senhor DEUS virá com poder; e seu braço governará por ele; eis que sua retribuição virá com ele, e seu pagamento diante de si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Como pastor ele apascentará seu rebanho; em seus braços recolherá aos cordeirinhos, e os levará em seu colo; ele guiará mansamente as que tiveram filhotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Quem mediu com seu punho as águas, e tomou a medida dos céus aos palmos? E quem recolheu numa caixa de medida o pó da terra, e pesou os montes com pesos, e os morros com balanças?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Quem guiou o Espírito do SENHOR? E que conselheiro o ensinou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Com quem ele tomou conselho? Quem lhe deu entendimento, e lhe ensinou o caminho do juízo, e lhe ensinou conhecimento, e lhe mostrou o caminho do entendimento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Eis que as nações lhe são consideradas como uma gota de balde, e como o pó miúdo das balanças; eis que ele levanta as ilhas como poeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Nem todo o Líbano seria suficiente para o fogo, nem seus animais bastam para servirem de oferta de queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Todas as nações são como nada perante ele; menos que nada e vazio ele as considera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'A quem, pois, comparareis a Deus? Ou que semelhança atribuireis a ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'O artífice funde a imagem, e o ourives a cobre de ouro, e cadeias de prata lhe funde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'O empobrecido, que não tem o que oferecer, escolhe madeira que não se estraga, e busca um artífice habilidoso, para preparar uma imagem que não se mova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Por acaso não sabeis? Por acaso não ouvis? Ou desde o princípio não vos disseram? Por acaso não tendes entendido desde os fundamentos da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Ele é o que está sentado sobre o globo da terra, cujos moradores são para ele como gafanhotos; ele é o que estende os céus como uma cortina, e os estica como uma tenda, para neles habitar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Ele é o que torna os príncipes em nada, e faz juízes da terra serem como o vazio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Mal foram plantados, mal foram semeados, mal seu caule forma raízes na terra; e logo ele sopra neles, e se secam, e um vento forte os leva como palha fina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'A quem, pois, me comparareis, que eu lhe seja semelhante?,diz o Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Levantai vossos olhos ao alto, e vede quem criou estas coisas, que faz sair numerado seu exército; e chama a todos eles pelos nomes, pela grandeza de suas forças, e por ser forte em poder, nenhuma delas faltará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Por que dizes, ó Jacó, e falas, ó Israel: Meu caminho está escondido do SENHOR, e meu juízo passa longe de meu Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Por acaso não sabes, nem ouviste, que o eterno Deus, o SENHOR, o criador dos confins da terra, não se cansa, nem se fatiga, e que seu entendimento é incompreensível?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Ele dá força ao cansado, e multiplica as forças daquele que não tem vigor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Até os jovens se cansam e se fatigam; e os rapazes caem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Mas os que confiam no SENHOR renovarão as forças, subirão com asas como águias; correrão, e não se cansarão; caminharão, e não se fatigarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Calai-vos perante mim, ó terras litorâneas; e os povos renovem as forças; aproximem-se, e então falem; juntamente nos aproximemos ao juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Quem o chamou desde o oriente, e com justiça o chamou ao seu pé? Ele lhe deu as nações perante sua face, e o fez dominar sobre reis, e os entregou à sua espada como o pó, como a palha fina levada por seu arco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Ele os persegue, e passa em segurança; por um caminho onde com seus pés nunca tinha ido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Quem operou e fez isto,chamando as gerações desde o princípio? Eu, o SENHOR, do princípio aos últimos, eu mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'As terras litorâneas viram, e tremeram; os confins da terra tremeram; eles se aproximaram, e chegaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Cada um ajudou ao outro, e a seu companheiro disse: Sê forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'E o artífice encorajou ao ourives, o que alisa com o martelo ao que bate na bigorna, dizendo da soldagem: Boa é. Então com pregos o firmou, para que não se mova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Porém tu, ó Israel, servo meu; tu, Jacó, a quem escolhi, semente de Abraão, meu amigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Tu, a quem tomei desde os confins da terra, e te chamei desde seus mais extremos, e te disse: Tu és meu servo; a ti escolhi, e não te rejeitei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Não temas, porque eu estou contigo; não te assombres, porque eu sou teu Deus. Eu te fortaleço, te ajudo, e te sustento com a minha mão direita de justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Eis que serão envergonhados e humilhados todos os que se indignaram contra ti; eles se tornarão como o nada; e os que brigarem contigo perecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Ainda que os procures, tu não os acharás; os que lutarem contra ti se tornarão como o nada; e os que guerrearem contra ti, como coisa nenhuma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Porque eu, o SENHOR teu Deus, te seguro pela tua mão direita, e te digo: Não temas; eu te ajudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Não temas, ó verme de Jacó, povinho de Israel; eu te ajudo,diz o SENHOR e teu Redentor, o Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Eis que eu te pus como debulhador afiado, novo, que tem dentes pontiagudos. Aos montes debulharás, e moerás; e aos morros tornarás como a palhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Tu os padejarás, e o vento os levará; e o redemoinho os espalhará; porém tu te alegrarás no SENHOR, e te orgulharás no Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Os pobres e necessitados buscam águas, mas nada acham; sua língua se seca de sede. Eu, o SENHOR, os ouvirei; eu, o Deus de Israel, não os desampararei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Abrirei rios em lugares altos, e fontes no meio dos vales; tornarei o deserto em tanques de águas, e a terra seca em mananciais de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Plantarei no deserto o cedro, a acácia, a murta, e a oliveira; juntamente porei na terra vazia a faia, o olmeiro e o cipreste;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Para que vejam, saibam, reflitam, e juntamente entendam que a mão do SENHOR fez isto; e o Santo de Israel isto criou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Apresentai vossa demanda!,diz o SENHOR. Trazei vossos argumentos!, diz o Rei de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Tragam e anunciem-nos as coisas que irão acontecer; anunciai quais foram as coisas passadas, para que possamos dar atenção a elas, e saibamos o fim delas; ou dizei-nos as coisas futuras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Anunciai as coisas que ainda virão, para que saibamos que vós sois deuses; ou fazei o bem ou o mal, para que nos assombremos, e juntamente vejamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Eis que vós sois nada, e vossa obra não tem valor algum; abominação é quem vos escolhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Eu suscitei a um do norte, que virá oriente, e invocará meu nome; e virá sobre os príncipes como se fossem lama, e como o oleiro pisa o barro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Quem anunciou coisa alguma desde o princípio, para que o possamos saber, ou desde antes, para que digamos “correto é”? Porém não há quem anuncie tal coisa nem quem diga coisa alguma, nem quem ouça vossas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Eu sou o primeiro que digo a Sião: Eis que ali estão! E a Jerusalém darei um anunciador de boas novas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'E olhei, porém ninguém havia. Até entre estes nenhum conselheiro havia a quem eu perguntasse, e ele me respondesse algo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Eis que todos são falsidade, suas obras são nada. Suas obras de fundição são vento e sem valor algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Eis aqui meu servo, a quem sustento; meu escolhido, em quem minha alma se agrada. Sobre ele eu pus o meu Espírito; ele trará justiça às nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Ele não gritará, nem levantará seu clamor; ele não fará ouvir sua voz nas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'A cana esmagada ele não quebrará, nem apagará o pavio que fumega; com a verdade ele trará justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Ele não se apagará, nem será quebrado, até que ponha a justiça na terra; e as terras litorâneas esperarão por sua doutrina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Assim diz Deus, o SENHOR, que criou os céus, e os esticou; estendeu a terra, e a tudo quanto ela produz; que dá respiração ao povo que nela habita,e espírito aos que nela andam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Eu, o SENHOR, te chamei em justiça, e te tomarei pela mão. E eu te guardarei, e te darei como pacto para o povo e luz para as nações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Para abrir os olhos cegos, para tirar da prisão os presos, tirar do cárcere os que habitam em trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Eu, EU-SOU; este é o meu nome! Não darei a minha glória a outro, nem o meu louvor às imagens de escultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Eis que as coisas anteriores já aconteceram; e as novas eu vos anuncio; e antes que surjam, delas eu vos informo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Cantai ao SENHOR um cântico novo, um louvor a ele desde o limite da terra; vós que navegais pelo mar, e tudo quanto nele há; vós terras do litoral e seus moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Levantem a voz o deserto e suas cidades, com as aldeias que Quedar habita; cantem os que habitam nas rochas, e gritem de alegria do cume dos montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Deem glória ao SENHOR, e anunciem louvor a ele nas terras do litoral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'O SENHOR sairá como guerreiro, como homem de guerra despertará o seu zelo; ele gritará, e fará grade ruído; e dominará a seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Por muito tempo fiquei calado, quieto estive, e me retive; mas agora darei gritos como a que está de parto, suspirando e juntamente ofegando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Aos montes e morros tornarei em deserto, e toda sua erva farei secar; e tornarei aos rios em ilhas, e as lagoas secarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'E guiarei aos cegos por um caminho que nunca conheceram; eu os farei caminhar pelas veredas que não conheciam; tornarei as trevas em luz perante eles, e as coisas tortas farei direitas; estas coisas lhes farei, e nunca os desampararei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Mas serão conduzidos para trás e se envergonharão os que confiam em imagens de escultura, e dizem às imagens de fundição: Vós sois nossos deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Surdos, ouvi; e vós cegos, olhai para que possais ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Quem é cego, senão o meu servo? Ou surdo, como o meu mensageiro, a quem envio? Quem é cego como o aliançado, e cego como o servo do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Tu vês muitas coisas, porém não as guardas; mesmo abrindo os ouvidos, contudo nada ouve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'O SENHOR se agradou, por causa de sua justiça, em engrandecer sua lei, e em fazê -la gloriosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Mas este é um povo roubado e saqueado; todos estão enlaçados em covas, e escondidos em cárceres; são postos como despojos, e ninguém há que os resgate; estão como objetos de roubo, e ninguém diz “Restitui -os”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Quem dentre vós dá ouvidos a isto? Quem presta atenção e ouve o que há de ser no futuro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Quem entregou a Jacó como roubo, e a Israel a ladrões? Por acaso não foi o SENHOR, aquele contra quem pecamos? Pois não queriam andar em seus caminhos, e não deram ouvidos à sua lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Por isso ele derramou sobre eles o furor de sua ira, e a força da guerra; e os pôs em labaredas ao redor; porém ainda assim não entenderam; e ele os pôs para queimar, porém ainda assim não puseram nisso o coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Porém agora assim diz o SENHOR, o teu Criador, ó Jacó, e o teu Formador, ó Israel: Não temas, porque eu te resgatei; chamei a ti por teu nome; tu és meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Quando passares pelas águas, estarei contigo; e ao passares pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem a chamas arderão em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Porque eu sou o SENHOR teu Deus, o Santo de Israel, teu Salvador; dei ao Egito, a Cuxe, e a Seba como teu resgate, em teu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Visto que foste precioso em meus olhos, assim foste glorificado, e eu te amei; por isso dei homens em troca de ti, e povos em troca de tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Não temas, pois estou contigo; eu trarei tua semente desde o oriente, e te ajuntarei desde o ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Direi ao norte: Dá!, E ao sul: Não retenhas! Trazei meus filhos de longe, e minhas filhas desde os confins da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Todos os chamados do meu nome, e os que criei para minha gloria; eu os formei; sim, eu os fiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Trazei ao povo cego, que tem olhos; e aos surdos, que tem ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Todas as nações se reúnam, e os povos se ajuntem. Quem deles isto isto anuncia, e nos faz ouvir as coisas do passado? Mostrem suas testemunhas, para que se justifiquem, e se ouça, e se diga: É verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vós sois minhas testemunhas (diz o SENHOR); e meu servo, a quem escolhi; para que saibais, e creiais em mim, e entendais que eu sou o próprio, e que antes de mim nenhum Deus se formou, e depois de minha nenhum haverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Eu, eu sou o SENHOR; e fora de mim não há salvador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Eu anunciei, eu salvei, e eu fiz ouvir, e deus estrangeiro não houve entre vós, e vós sois minhas testemunhas, (diz o SENHOR), que eu sou Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'E desde antes de haver dia, eu o sou; e ninguém há que possa livrar das minhas mãos. Eu estou agindo, quem pode impedir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Assim diz o SENHOR o teu Redentor, o Santo de Israel: Por causa de vós eu enviei inimigos a Babilônia, e a todos eu os fiz descerem como fugitivos, inclusive os Caldeus, nos navios em que se orgulhavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Eu sou o SENHOR, vosso Santo; o Criador de Israel, o vosso Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Assim diz o SENHOR, aquele que preparou no mar um caminho, e nas águas impetuosas uma vereda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Aquele que trouxe carruagens e cavalos, exército e forças; todos juntamente caíram, e não mais se levantaram; estão extintos, foram apagados como um pavio:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Não vos lembreis das coisas passadas, nem considereis as antigas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Eis que farei uma coisa nova, agora surgirá; por acaso não a reconhecereis? Pois porei um caminho no deserto, e rios na terra vazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Os animais do campo me honrarão; os chacais e os filhotes de avestruz; porque porei águas no deserto, rios na terra vazia, para dar de beber a meu povo, meu escolhido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Este povo formei para mim, eles declararão louvor a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Porém tu não me invocaste, ó Jacó; pois te cansaste de mim, ó Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Não me trouxeste o gado miúdo de tuas ofertas de queima, nem me honraste com teus sacrifícios; eu não vos oprimi com ofertas, nem te cansei com incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Não me compraste com dinheiro cana aromática, nem me saciaste com a gordura de teus sacrifícios; mas me oprimiste com teus pecados, e me cansaste com tuas maldades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Eu, eu sou o que anulo tuas transgressões por causa de mim; e te teus pecados eu não me lembro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Faze-me lembrar, entremos em juízo juntos; mostra teus argumentos,para que possas te justificar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Teu primeiro pai pecou; e teus intérpretes transgrediram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Por isso profanei os líderes do santuário, e entreguei Jacó à desgraça, e Israel à humilhação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Agora, pois, ouve, ó Jacó, meu servo; tu, ó Israel, a quem escolhi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Assim diz o SENHOR, aquele que te fez, e te formou desde o ventre, que te socorre: não temas, ó Jacó, meu servo; tu Jesurum, a quem escolhi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Porque derramarei água sobre o sedento, e rios sobre a terra seca; derramarei meu Espírito sobre tua semente, e minha bênção sobre teus descendentes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'E brotarão entre a erva, como salgueiros junto a ribeiros de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Um dirá: Eu sou do SENHOR; e outro se chamará pelo nome de Jacó; e um terceiro escreverá em sua mão: Eu sou do SENHOR, e tomará para si o nome de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Assim diz o SENHOR, Rei de Israel, e seu Redentor, o SENHOR dos exércitos:Eu sou o primeiro, e sou o último; e além de mim não há Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Quem, como eu, anunciará isto? Que declare e explique para mim, visto que determinei um povo eterno! Anunciem-lhes as coisas futuras, as que estão para vir!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Não vos assombreis, nem temais; por acaso eu não vos contei e anunciei com antecedência? Pois vós sois minhas testemunhas. Por acaso há outro Deus além de mim? Não há outra Rocha, não que eu conheça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Todos os que formam imagens de escultura são nada, e as coisas que eles se agradam são de nenhum proveito; e elas mesmas são suas testemunhas: nada veem, nem entendem; por isso serão envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Quem é que forma um deus e funde uma imagem de escultura que não lhe tem proveito algum?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Eis que todos os companheiros dele serão envergonhados, pois os artífices nada são além de homens. Ajuntem-se todos, e fiquem de pé; eles se assombrarão, e juntamente serão envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'O ferreiro, com a ferramenta de corte, trabalha nas brasas, e forma o ídolo com martelos; e ele o faz com a força de seu braço; ele, porém, tem fome e perde as forças, e se não beber água, desfalece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'O carpinteiro estende a linha de medir, e o desenha com um marcador; ele o confecciona com formões, e o desenha com um compasso; e o faz à semelhança de um homem, conforme a beleza humana, para habitar numa casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Ele corta para si cedros, e toma um cipreste ou um carvalho, e reserva para si das árvores da floresta; ele planta um pinheiro, e a chuva o faz crescer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Então tal madeira servirá ao homem para queimar, e toma parte deles para se aquecer, e os acende, e aquece o pão; ele também faz um deus, e o adora; fabrica dela uma imagem de escultura, e se prostra diante dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Sua metade ele queima no fogo; com a outra metade como carne; prepara assado, e dele se sacia; também se esquenta, e diz: Ah! Já me aqueci! Já vi o fogo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Então do resto ele faz um deus, para imagem de escultura para si; ele se ajoelha a ela, e a adora, e ora a ela, e diz: Livra-me, pois tu és meu deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Eles nada sabem, nem entendem; porque seus olhos foram encobertos para que não vejam; e seus corações, para que não entendam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'E nenhum deles pensa sobre isso em seu coração, e não tem conhecimento nem entendimento para dizer: A metade queimei no fogo; e aqueci pão sobre suas brasas; assei carne, e a comi; e faria eu do resto uma abominação? Prostraria eu ao que saiu de uma árvore?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Ele se alimenta de cinzas; seu coração enganado o desviou, de modo que ele já não pode livrar a sua alma, nem dizer: Por acaso não é uma mentira o que há na minha mão direita?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Lembra-te destas coisas, ó Jacó e Israel, pois tu és meu servo; eu te formei. Meu servo és, ó Israel; eu não me esquecerei de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Eu elimino tuas transgressões como a névoa, e teus pecados como a nuvem; volta a mim, pois eu já te resgatei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Cantai louvores, vós céus, porque o SENHOR assim fez; gritai de alegria, vós partes baixas da terra; vós montes, fazei ruídos de júbilo, também vós bosques, e todas as árvores neles; porque o SENHOR regatou a Jacó, e glorificou a si mesmo em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Assim diz o SENHOR, o teu redentor, aquele que te formou desde o ventre: Eu sou o SENHOR que tudo faço; que sozinho estico os céus, e que estendo a terra por mim mesmo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Que desfaço os sinais dos inventores de mentiras, e faço de todos aos adivinhos; que faço aos sábios retrocederem, e torno o conhecimento deles em loucura;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Sou aquele que confirma a palavra de seu servo, e cumpre o conselho de seus mensageiros; que diz a Jerusalém: Tu serás habitada; E às cidades de Judá: Sereis reconstruídas; e eu erguerei seus lugares arruinados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Que diz à profundeza: Seca-te; e eu secarei teus rios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Que diz de Ciro: Ele é meu pastor, e cumprirá toda a minha vontade, dizendo à Jerusalém: Serás edificada; e ao Templo: Terás posto teu fundamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Assim diz o SENHOR a seu ungido, Ciro, ao qual tomou pela sua mão direita, para abater as nações diante dele, e tirar a proteção dos lombos dos reis; para abrir diante de sua presença as portas, e as portas não se fecharão:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Eu irei adiante de ti, e nivelarei os caminhos acidentados; quebrarei as portas de bronze, e despedaçarei os ferrolhos de ferro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'E te darei os tesouros das escuridões, e as riquezas escondidas; para que possas saber que eu sou o SENHOR, que te chama pelo teu nome, o Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Em favor de meu servo Jacó e de meu escolhido Israel, eu te chamei pelo teu nome; eu te pus teu título, ainda que tu não me conhecesses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Eu sou o SENHOR, e ninguém mais; fora de mim não há Deus; eu te revestirei, ainda que tu não me conheças;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Para que saibam desde o oriente e desde o ocidente que fora de mim não há outro. Eu sou o SENHOR, e ninguém mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Eu formo a luz e crio as trevas; eu faço a paz, e crio a adversidade; eu, o SENHOR, faço todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Gotejai vós, céus, de cima, e as nuvens destilem justiça; abra-se a terra, e produza-se salvação, e a justiça juntamente frutifique; eu, o SENHOR, as criei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Ai daquele que briga com seu formador: apenas um caco entre outros cacos de barro! Por acaso o barro dirá ao seu formador: Que fazes? Ou tua obra: Não tem mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Ai daquele que diz ao pai: O que é que tu geras? E à mulher: O que é que tu fazes nascer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Assim diz o SENHOR, o Santo de Israel, e seu formador: Perguntai-me sobre as coisas futuras; por acaso me dais ordens sobre os meus filhos, e sobre as obras de minhas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Eu fiz a terra, e criei nela o homem; fui eu, minhas próprias mãos estenderam os céus, e dei ordens sobre todo o seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Eu o despertei em justiça, e todos os seus caminhos endireitarei; ele edificará minha cidade, e soltará meus cativos; não por preço, nem por subornos,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Assim diz o SENHOR: O trabalho do Egito, e o comércio dos cuxitas e dos sabeus, homens de alta estatura, passarão a ti, e serão teus; eles irão após ti, passarão acorrentados; e a ti se prostrarão, a ti suplicarão, dizendo: Certamente Deus está contigo, e nenhum outro Deus há.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Verdadeiramente tu és o Deus que se encobre; o Deus de Israel, o Salvador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Serão envergonhados, e também humilhados, todos eles; juntamente irão embora com vergonha os que fabricam imagens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Mas Israel é salvo pelo SENHOR, com salvação eterna; não sereis envergonhados nem humilhados para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Porque assim diz o SENHOR, que criou os céus, o Deus que formou a terra, e a fez; ele a firmou, não a criou para ser vazia, ao contrário,criou para que fosse habitada: Eu sou o SENHOR, e ninguém mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Não falei em oculto, nem em algum lugar escuro da terra; não disse à semente de Jacó: Buscai-me, em vão; eu sou o SENHOR, que fala justiça, e anuncio coisas corretas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Ajuntai-vos, e vinde; achegai-vos juntamente os que escapastes das nações. Os que carregam suas imagens de escultura de madeira, e rogam a um Deus que não pode salvar, nada conhecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Anunciai, e achegai-vos; e consultai juntamente em conselho; quem fez ouvir isto desde a antiguidade? Quem desde então tem anunciado? Por acaso não sou eu, o SENHOR? E não há ouro Deus além de mim, Deus justo e Salvador; ninguém, a não ser eu mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Virai-vos a mim, e sede salvos, vós todos os limites da terra; porque eu sou Deus, e ninguém mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Por mim mesmo tenho jurado; já saiu da minha boca palavra de justiça, e não voltará atrás: que a mim se dobrará todo joelho, e toda língua prestará juramento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'De mim se dirá: Certamente no SENHOR há justiça e poder; Até a ele chegarão, mas serão envergonhados todos os que o odeiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Porém no SENHOR todos os que são da semente de Israel serão justificados e se gloriarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel se abaixa, Nebo se curva; seus ídolos são postos sobre os animais e sobre o gado; as cargas de vossos fardos são exaustivas para os animais já cansados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Juntamente se encurvam e se abaixam; não podem salvar a carga, mas eles mesmos vão ao cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Ouvi-me, ó casa de Jacó, e todo o restante da casa de Israel; vós a quem eu carreguei desde o ventre, a quem levei desde o útero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'E até vossa velhice eu serei o mesmo, e ainda até à idade dos cabelos grisalhos eu vos carregarei; eu vos fiz, e eu vos levarei; eu vos carregarei e vos livrarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'A quem me considerareis semelhante, e com quem me igualareis, e me comparareis, para que sejamos semelhantes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Eles gastam o ouro da bolsa, e pesam a prata com balanças; pagam ao ourives, e daquilo ele faz um deus, e se prostram e adoram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Sobre os ombros o temam, o carregam, e o põem em seu lugar; ali ele fica, de seu lugar não se move; e se chamarem por ele, resposta nenhuma ele dá, nem o livra de sua aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Lembrai-vos disto, e sede corajosos; fazei memória disso no coração, ó transgressores!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Lembrai-vos das coisas passadas desde a antiguidade; porque eu sou Deus, e nenhum outro deus há, e ninguém há semelhante a mim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Que declaro o fim desde o princípio, e desde a antiguidade as coisas que ainda não aconteceram; que digo: Minha intenção será firme, e farei toda a minha vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Que chamo a ave de rapina desde o oriente, ao homem da minha intenção desde as terras distantes; porque assim disse; e assim o cumprirei; eu o formei, também o farei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Ouvi-me, ó duros de coração; vós que estais longe da justiça:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Eu trago para perto minha justiça, ela não ficará longe; e minha salvação não tardará; mas porei salvação em Sião, a Israel minha glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Desce, e senta-te no pó da terra, ó virgem filha da Babilônia; senta-te no chão; já não há mais trono, ó filha dos caldeus; pois nunca mais serás chamada de tenra e delicada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Toma as pedras de moer, e mói farinha; descobre o teu véu, expõe as pernas, descobre as coxas, e passa os rios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Tua nudez será descoberta, e tua vergonha será vista; tomarei vingança, e a ninguém pouparei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'O nome de nosso Redentor é o SENHOR dos exércitos, o Santo de Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Senta-te calada, e entra nas trevas, ó filha dos caldeus; porque nunca mais serás chamada de senhora dos reinos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Tive muita ira contra meu povo; profanei minha herança, e os entreguei em tuas mãos; porém tu não lhes foste misericordiosa, e até sobre os velhos puseste teu jugo muito pesado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'E dizias: Serei senhora para sempre; Até agora não pensaste estas coisas em teu coração, nem te lembraste do fim que elas teriam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Agora, pois, ouve isto, ó amante dos prazeres, que habitas tão segura, que dizes em teu coração: Somente eu, e ninguém mais; não ficarei viúva, nem saberei como é perder um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Porém ambas estas coisas virão sobre ti, em um momento no mesmo dia: perda de filhos e viuvez; em completa totalidade virão sobre ti, por causa de tuas muitas feitiçarias, por causa da abundância de teus muitos encantamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Pois confiaste em tua maldade, e disseste: Ninguém me vê.Tua sabedoria e teu conhecimento, esses te fizeram desviar, e disseste em teu coração: Somente eu, e ninguém mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Então virá sobre ti um mal do qual não saberás a origem, e destruição cairá sobre ti, a qual não poderás solucionar; porque virá sobre ti de repente tão tempestuosa assolação, que não poderás reconhecer com antecedência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Fica ainda com teus encantamentos, e com as tuas muitas feitiçarias, em que trabalhaste desde a tua juventude; para ver se talvez ter algum proveito, ou quem sabe provoques algum medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Tu te cansaste com tantos conselhos que recebeste; levantem-se, pois, agora, os que observam o céu, os que contemplam as estrelas, os adivinhos das luas novas; e salvem-te daquilo que virá sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Eis que eles serão como a palha: o fogo os queimará, não poderão livrar suas vidas do poder das chamas; essas não serão brasas para se aquecer, nem fogo para meramente se sentar perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Assim serão para ti aqueles com quem trabalhaste, aqueles com quem fizeste negócios desde a tua juventude. Cada um deles andará sem rumo em seu próprio caminho; ninguém te salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Ouvi isto, casa de Jacó, que vos chamais pelo nome de Israel, e saístes das águas de Judá; que jurais pelo nome do SENHOR, e fazeis menção do Deus de Israel, porém não em verdade, nem em justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'E até da santa cidade se chamam; e confiam no Deus de Israel; EU-SOU dos exércitos é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'As coisas passadas desde antes anunciei, procederam da minha boca, e eu as declarei publicamente; rapidamente eu as fiz, e elas aconteceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Porque eu sabia que tu eras obstinado, e teu pescoço era um nervo de ferro, e tua testa de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Por isso eu anunciei a ti com antecedência, e te declarei antes que acontecesse, para que não viesses a dizer: Meu ídolo fez estas coisas, ou minha imagem de escultura ou imagem de fundição, foi ela que isso ordenou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Já tens escutado. Olha bem para tudo isto: por acaso vós não diríeis que isto é verdade? A partir de agora eu te faço ouvir coisas novas, ocultas, e que nunca antes soubeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Agora foram criadas, e não antes; e antes de hoje não as ouvistes; para que não viesses a dizer: Eis que eu já as sabia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Tu não as ouviste, nem as soubeste, nem também teu ouvido havia sido aberto antes; porque eu sabia que agirias enganosamente, e que foste chamado de transgressor desde o ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Por causa do meu nome adiarei a minha ira, e por louvor a mim me conterei para contigo, para que eu não venha a te eliminar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Eis que eu te purifiquei, porém não como a prata; eu te escolhi na fornalha da aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Por causa de mim, por causa de mim eu o farei; pois como permitiria meu nome ser profanado? E minha glória não darei a outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Ouvi-me, ó Jacó, e tu, ó Israel, por mim chamado; eu sou o mesmo; eu sou o primeiro, eu também sou o último.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Também minha mão fundou a terra, e minha mão direita estendeu os céus; quando eu os chamo, logo eles juntamente aparecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Ajuntai-vos, todos vós, e ouvi, quem há dentre eles, anunciou estas coisas? O SENHOR o amou, e executará sua vontade contra a Babilônia, e seu braço será contra os caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Eu, eu mesmo tenho dito; também eu já o chamei. Eu o farei vir, e ele prosperará em seu caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Achegai-vos a mim, ouvi isto: não falei em oculto desde o princípio; ao contrário,desde o tempo em que aquilo se fez, ali eu estava; e agora o Senhor DEUS me enviou, e seu Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Assim diz o SENHOR, teu Redentor, o Santo de Israel: Eu sou o SENHOR teu Deus, que te ensina o que é proveitoso, e te guia pelo caminho que deves andar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Ah, se tu tivesses me dado ouvidos a meus mandamentos! Então tua paz teria sido como um rio, e tua justiça como as ondas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Também tua semente teria sido como a areia, e os que procedem do teu corpo, como suas pedrinhas, cujo nome nunca seria cortado, nem destruído de minha face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Saí da Babilônia, fugi dos caldeus; declarai com voz de júbilo, anunciai, e levai isto até o fim da terra; dizei: O SENHOR resgatou a seu servo Jacó!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'E não tinham sede, quando ele os levava pelos desertos; fez correr para eles água da rocha; e quando ele fendia as rochas, águas manavam delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Porém para os perversos não haverá paz,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Ouvi-me, terras costeiras, e escutai, vós povos de longe; o SENHOR me chamou desde o ventre, desde as entranhas de minha mãe ele fez menção do meu nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'E fez da minha boca como uma espada afiada, com a sombra de sua mão ele me cobriu; e me pôs como uma flecha polida, e me guardou em sua aljava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'E me disse: Tu és meu servo, Israel, por quem serei glorificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Porém eu disse: Inutilmente tenho trabalhado; por nada e em vão gastei minhas forças; todavia meu direito está perante o SENHOR, e minha recompensa perante meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'E agora diz o SENHOR, que me formou desde o ventre para si por servo, que trazer Jacó de volta a si; porém Israel não se deixará ajuntar; contudo, nos olhos do SENHOR serei honrado, e meu Deus será minha força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Disse também: É pouco demais que sejas meu servo apenas para restaurares as tribos de Jacó e restabeleceres os sobreviventes de Israel; eu também te dei como luz das nações, para seres minha salvação até o limite da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Assim diz o SENHOR, o Redentor de Israel, seu Santo, à alma desprezada, ao que a nação abomina, ao servo dos que dominam: Reis o verão e se levantarão, príncipes também; e eles se prostrarão por causa do SENHOR, que é fiel, por causa do Santo de Israel, que te escolheu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Assim diz o SENHOR: No tempo do favor eu te ouvi, e no dia da salvação eu te ajudei; e eu te guardarei, e te darei por pacto do povo, para restaurares a terra, para fazer tomar posse das propriedades assoladas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Para que tu digas aos presos: Saí; e aos que estão em trevas: Aparecei; eles se alimentarão nos caminhos, e em todos os lugares altos haverá pasto para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Nunca terão fome nem sede; nem o calor, nem o sol os afligirá; porque aquele que se compadece deles os guiará, e os levará mansamente a mananciais de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'E farei com que todos os meus montes se tornem um caminho; e minhas estradas serão levantadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Eis que estes virão de longe; e eis que alguns do norte, e do ocidente, e outros da terra de Sinim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Cantai de júbilo, ó céus, e alegra-te tu, ó terra; e vós montes, gritai de alegria; porque o SENHOR consolou a seu povo, e terá compaixão de seus aflitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Mas Sião diz: O SENHOR me desamparou; e o Senhor se esqueceu de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Pode, por acaso, uma mulher se esquecer do filho que ainda amamenta, de modo que não se compadeça do filho de seu próprio ventre? Ainda que elas se esquecessem, contudo, eu não me esquecerei de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Eis que eu te tenho escrito nas minhas palmas de ambas as mãos; teus muros estão continuamente perante mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Teus filhos depressa virão; e teus destruidores e teus assoladores sairão de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Levanta teus olhos ao redor e olha; todos estes que se ajuntam vêm a ti; tão certo como eu vivo, diz o SENHOR, que de todos estes te vestirás, como de ornamento, e vestirás deles ao teu redor, como uma noiva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Pois ainda que teus desertos sejam lugares solitários, e tua terra esteja destruída, agora te verás apertada de moradores, e os que te consumiram se afastarão para longe de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Até mesmo os filhos que nascerem depois de teres perdido os primeiros dirão aos teus ouvidos: Este lugar é muito apertado para mim! Dá-me espaço para que eu possa habitar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'E dirás em teu coração: Quem a estes me gerou? Pois eu estava sem filhos e solitária; quem, pois, me criou a estes? Eis que eu fui deixada sozinha; e estes, onde estavam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Assim diz o Senhor DEUS: Eis que levantarei minha mão às nações, e erguerei minha bandeira aos povos; então trarão teus filhos nos braços, e tuas filhas serão levadas sobre os ombros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'E reis serão teus tutores, e suas princesas tuas amas; perante ti se inclinarão com o rosto em terra, e lamberão o pó de teus pés; e saberás que eu sou o SENHOR; aqueles que esperam por mim não serão envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Pode, por acaso, se tirar a presa de um guerreiro, ou fazer escapar os presos capturados por um justo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Porém assim diz o SENHOR: Sim, os presos serão tirados do valente, e a presa do tirano escapará; porque eu brigarei com os que brigam contigo, e resgatarei teus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'E darei de comer a teus opressores sua própria carne, e com seu próprio sangue se embriagarão, como com vinho; e todos saberão que eu sou o SENHOR teu Salvador, e teu Redentor, o Poderoso de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Assim diz o SENHOR: Onde está a carta de divórcio de vossa mãe, com que eu a mandei embora? Ou a qual dos meus credores foi que eu vos vendi? Eis que por vossas maldades fostes vendidos, e por vossas transgressões vossa mãe foi expulsa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Por que razão quando eu vim ninguém apareceu? Chamei, e ninguém respondeu. Por acaso minha mão se encurtou tanto, que já não posso resgatar? Ou não há mais poder em mim para livrar? Eis que com minha repreensão faço secar o mar, torno os rios em deserto, até federem seus peixes por não haver água, e morrem de sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Eu visto aos céus de negro, e ponho um saco como sua cobertura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'O Senhor DEUS me deu língua de instruídos, para que eu saiba falar no tempo devido uma boa palavra ao cansado; ele me desperta todas as manhãs, desperta o meu ouvido para que eu ouça como os instruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'O Senhor DEUS abriu os meus ouvidos, e não sou rebelde; nem me viro para trás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Dei minhas costas aos que me feriam, e os lados do meu rosto aos que me arrancavam os pelos; não escondo minha face de humilhações e cuspidas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Porque o Senhor DEUS me ajuda; portanto não me envergonho; por isso pus meu rosto como pedra muito dura; porque sei que não serei envergonhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Perto está aquele que me justifica; quem se oporá a mim? Compareçamos juntos; quem é meu adversário? Venha até mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Eis que o Senhor DEUS me ajuda; quem é que o que me condenará? Eis que todos eles tal como vestidos se envelhecerão, e a traça os comerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Quem há entre vós que tema ao SENHOR, e ouça a voz de seu servo? Aquele que andar em trevas, e não tiver luz nenhuma, confie no nome do SENHOR, e dependa de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Eis que todos vós que acendeis fogo, e vos envolveis com chamas, andai entre as labaredas de vosso fogo, e entre as chamas que acendestes; isto recebereis de minha mão, e em tormentos jazereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Ouvi-me, vós que seguis a justiça, os que buscais ao SENHOR; olhai para a rocha de onde fostes cortados, e para a escavação do poço de onde fostes cavados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Olhai para Abraão vosso pai, e para Sara que vos gerou; porque, sendo ele sozinho eu o chamei, o abençoei e o multipliquei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Pois o SENHOR consolará a Sião; ele consolará a todos os seus lugares desertos, e fará a seu deserto como a Éden, e seu lugar vazio como o jardim do SENHOR; alegria e contentamento se achará nela; agradecimentos e voz de melodia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Prestai atenção a mim, povo meu; e minha nação, inclinai teus ouvidos a mim; porque a Lei procederá de mim, e meu porei meu juízo como luz para os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Perto está minha justiça, já partiu minha salvação, e meus braços julgarão aos povos; as terras litorâneas aguardarão por mim, e por meu braço esperarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Levantai vossos olhos aos céus, e olhai para a terra abaixo; porque os céus desaparecerão como fumaça, e a terra se envelhecerá como um vestido; e seus moradores semelhantemente morrerão; porém minha salvação durará para sempre, e minha justiça não será terminará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Ouvi-me, vós que conheceis a justiça, vós povo em cujo coração está minha Lei; não temais a humilhação dos homens, nem vos perturbeis por seus insultos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Porque a traça os roerá como um vestido; e o verme os comerá com a lã; mas minha justiça durará para sempre, e minha salvação geração após gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Desperta-te! Desperta-te! Reveste-te de força, ó braço do SENHOR! Desperta-te como nos dias do passado, como nas gerações antigas; por acaso não és tu aquele que cortaste em pedaços a Raabe, que feriste ao dragão marinho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Não és tu aquele que secaste o mar, as águas do grande abismo, e que fizeste o caminho das profundezas do mar, para que passassem os redimidos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Assim voltarão os regatados do SENHOR, e virão a Sião cantando; e alegria perpétua haverá sobre suas cabeças; júbilo e alegria terão; tristeza e gemido fugirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Eu, eu sou aquele que vos consola; quem és tu, para que tenhas medo do homem mortal, ou do filho do homem que é como grama,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'E te esqueças do SENHOR, aquele que te fez, que estendeu os céus e fundou a terra, e temes continuamente o dia todo à fúria do opressor, como se ele estivesse pronto para destruir? Onde está essa fúria do opressor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'O preso logo será solto, e não morrerá na cova, nem seu pão lhe faltará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Pois eu sou o SENHOR teu Deus, que divido o mar, e bramam suas ondas. EU-SOU dos exércitos é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'E ponho minhas palavras em tua boca, e te cubro com a sombra de minha mão; para plantar os céus, e para fundar a terra, e para dizer a Sião: Tu és meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Desperta-te! Desperta-te! Levanta-te, ó Jerusalém, que bebeste da mão do SENHOR o cálice de seu furor; bebeste e sugaste os resíduos do cálice do cambaleio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'De todos os filhos que ela gerou, nenhum há que a guie mansamente; e de todos os filhos que ela criou, nenhum há que a segure pela mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Estas duas coisas te aconteceram; quem terá compaixão de ti? Assolação e ruína; fome e espada; por meio de quem te consolarei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Os teus filhos desmaiaram, jazem nas entradas de todos os caminhos, como um antílope numa rede; cheios estão do furor do SENHOR, e da repreensão de teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Portanto agora ouve isto, ó oprimida e embriagada, mas não de vinho:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Assim diz o teu Senhor, o SENHOR, e teu Deus, que defende a causa de seu povo: eis que eu tomo da tua mão o cálice do cambaleio, os resíduos do cálice de meu furor; nunca mais o beberás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Porém eu o porei nas mãos dos que afligiram, que dizem à tua alma: Abaixa-te, e passaremos sobre ti; e pões as tuas costas como chão, como caminho aos que passam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Desperta-te! Desperta-te! Veste-te de tua força, ó Sião! Veste-te de teus belos vestidos, ó Jerusalém, cidade Santa! Porque nunca mais entrará em ti nem incircunciso nem impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Sacode-te do pó, levanta-te, e senta-te, ó Jerusalém! Solta-te das ataduras de teu pescoço, ó cativa filha de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Porque assim diz o SENHOR: Por nada fostes vendidos, também sem ser por dinheiro sereis resgatados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Porque assim diz o Senhor DEUS: Meu povo em tempos passados desceu ao Egito para lá peregrinar; e a Assíria sem razão o oprimiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'E agora, o que tenho de fazer aqui?,Diz o SENHOR, Pois meu povo foi tomado sem motivo algum; e os que dominam sobre ele uivam, diz o SENHOR; E meu nome continuamente, durante o dia todo, é blasfemado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Por isso meu povo conhecerá o meu nome, por esta causa naquele dia; porque eu mesmo sou o que digo, eis-me aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Como são agradáveis sobre os montes os pés daquele que dá boas notícias, que anuncia a paz; que fala notícias do bem; que anuncia a salvação; do que diz a Sião: Teu Deus reina!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Eis a voz dos teus vigilantes; eles levantam a voz, juntamente gritam de alegria; porque olho a olho verão quando o SENHOR trazer de volta a Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Gritai de alegria, jubilai juntamente, ó lugares abandonados de Jerusalém; porque o SENHOR consolou a seu povo, redimiu a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'O SENHOR expôs o seu santo braço perante os olhos de todas as nações; e todos os confins da terra verão a salvação de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Retirai-vos! Retirai-vos! Saí daí! Não toqueis em coisa impura! Saí do meio dela! Purificai-vos vós que levais os vasos do SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Pois vós não saireis apressadamente, nem ireis fugindo; porque o SENHOR irá adiante de vossa face, o Deus de Israel será vossa retaguarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Eis que meu servo agirá prudentemente; ele será exaltado e elevado, e muito sublime.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Como muitos se espantaram de ti, de que a aparência dele estava tão desfigurada, mais do que qualquer outro; que seu aspecto já não parecia com os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Assim ele salpicará a muitas nações, e sobre ele os reis fecharão suas bocas; porque aquilo que nunca lhes havia sido anunciado, isso verão; e aquilo que nunca tinham ouvido, disso entenderão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Quem creu em nossa pregação? E a quem se manifestou o braço do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Pois foi crescendo como renovo perante ele, e como raiz de terra seca; não tinha boa aparência nem formosura; e quando olhávamos para ele, não havia nele boa aparência, para que o desejássemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Ele era desprezado e rejeitado entre os homens, era homem de dores, e experiente em enfermidade; ele era como alguém de quem os outros escondiam o rosto; era desprezado, e não lhe estimávamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Verdadeiramente ele tomou sobre si nossas enfermidades, e nossas dores levou sobre si; e nós o considerávamos como afligido, ferido por Deus, e oprimido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Porém ele foi ferido por nossas transgressões, e esmagado por nossas perversidades; o castigo que nos traz a paz estava sobre ele, e por suas feridas fomos curados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Todos nós andávamos sem rumo como ovelhas; cada um se desviava por seu caminho; porém o SENHOR fez vir sobre ele a perversidade de todos nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Ele foi oprimido e afligido, porém não abriu sua boca; tal como cordeiro ele foi levado ao matadouro, e como ovelha muda perante seus tosquiadores, assim ele não abriu sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Com opressão e julgamento ele foi removido; e quem falará de sua geração? Porque ele foi cortado da terra dos viventes; pela transgressão do meu povo ele foi ferido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'E puseram sua sepultura com perversos, e com um rico em sua morte; pois ele nunca fez injustiça, nem houve engano em sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Porém agradou ao SENHOR esmagá-lo, fazendo-o ficar enfermo; quando sua alma for posta como expiação do pecado, ele verá semente, e prolongará os dias; e o bom prazer do SENHOR prosperará em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'A consequência do trabalho de sua alma ele verá e se fartará; com seu conhecimento o meu servo, o justo, justificará a muitos, pois levará sobre si as perversidades deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Por isso lhe darei a porção de muitos, e e com os poderosos ele repartirá despojo, pois derramou sua alma na morte, e foi contado com os transgressores; e levou sobre si o pecado de muitos, e intercedeu pelos transgressores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Canta alegremente, ó estéril, que não geravas; grita de prazer com alegre canto, e jubila tu que não tiveste dores de parto; pois mais são os filhos da solitária do que os filhos da casada, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Aumenta o espaço de tua tenda, e as cortinas de tuas habitações sejam estendidas; não o impeças; alonga tuas cordas, e fixa bem tuas estacas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Porque transbordarás à direita e à esquerda; e tua semente tomará posse das nações, e farão habitar as cidades assoladas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Não temas, pois não serás envergonhada; e não te envergonhes, pois não serás humilhada; ao contrário, te esquecerás da vergonha da tua juventude, e não te lembrarás mais da desonra de tua viuvez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Porque teu marido é o Criador; EU-SOU dos exércitos é o seu nome; e o Santo de Israel é o teu Redentor; ele será chamado: o Deus de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Pois o SENHOR te chamou como mulher abandonada, e triste de espírito; como uma mulher da juventude que havia sido rejeitada, diz o teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Por um curto momento te deixei; porém com grandes misericórdias te recolherei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Num acesso de ira escondi minha face de ti por um momento; porém com bondade eterna terei compaixão de ti, diz o SENHOR teu Redentor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Porque isto será para mim como as águas de Noé, quando jurei que as águas de Noé não mais passaria sobre a terra; assim jurei, que não me irarei contra ti, nem te repreenderei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Porque montes se removerão e morros se retirarão, porém minha bondade não se removerá de ti, nem o pacto de minha paz se retirará, diz o SENHOR, que tem compaixão de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Tu, oprimida, afligida por tempestade, e desconsolada: eis que eu porei tuas pedras com ornamentos, e te fundarei sobre safiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'E farei de rubis as tuas torres; e tuas portas de carbúnculos, e todos os teus limites com pedras preciosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'E todos os teus filhos serão ensinados pelo SENHOR; e a paz de teus filhos será abundante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Com justiça serás firmada; afasta-te da opressão, porque já não temerás; assim como também do assombro, porque este não se aproximará de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Se alguém lutar contra ti,não será por mim; quem lutar contra ti cairá por causa de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Eis que fui eu que criei ao ferreiro que assopra as brasas no fogo, e que produz a ferramenta para sua obra; também fui eu que criei ao destruidor, para causar ruína.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Nenhuma ferramenta preparada contra ti terá sucesso; e toda língua que se levantar contra ti em juízo, tu a condenarás; esta é a herança dos servos do SENHOR; e a justiça deles provém de mim, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Ó todos vós que tendes sede, vinde às águas; e vós que não tendes dinheiro, vinde, comprai, e comei; vinde, comprai, sem dinheiro e sem preço, vinho e leite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Por que gastais dinheiro naquilo que não é pão, e vosso trabalho naquilo que não pode trazer satisfação? Ouvi-me com atenção, e comei o que é bom, e vossa alma se deleite com a gordura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Inclinai vossos ouvidos, e vinde a mim; ouvi, e vossa alma viverá; porque convosco farei um pacto eterno, tal como as firmes bondades prometidas a Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Eis que eu o dei para ser testemunha aos povos, como príncipe e governante dos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Eis que chamarás a uma nação que não conheceste, e uma nação que nunca te conheceu correrá para ti, por causa do SENHOR teu Deus, o Santo de Israel; porque ele te glorificou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Buscai ao SENHOR enquanto se pode achar; invocai-o enquanto ele está perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Que o perverso deixe seu caminho, e o homem maligno deixe seus pensamentos, e converta ao SENHOR; então dele terá compaixão; converta ao nosso Deus, porque ele grandemente perdoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Pois meus pensamentos não são vossos pensamentos, nem vossos caminhos são meus caminhos, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Porque tal como os céus são mais altos que a terra, assim também meus caminhos são mais altos que vossos caminhos, e meus pensamentos mais altos que vossos pensamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Porque tal como a chuva e a neve desce dos céus, e para lá não volta, mas rega a terra, e a faz produzir, brotar, e dar semente ao semeador, e pão ao que come;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Assim também será minha palavra, que não voltará a mim vazia; ao contrário, ela fará o que me agrada, e cumprirá aquilo para que a enviei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Porque com alegria saireis, e em paz sereis guiados; os montes e os morros cantarão de alegria perante vossa presença, e todas as árvores do campo baterão palmas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Em lugar do espinheiro crescerá o cipreste, e em lugar da urtiga crescerá a murta; e isso será para o SENHOR como um nome, como um sinal eterno, que nunca se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Assim diz o SENHOR: Guardai o que é justo, e praticai a justiça; porque minha salvação já está perto de vir, e minha justiça de se manifestar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Bem-aventurado o homem que fizer isto, e o filho do homem que permanece nisto; que se guarda para não profanar o sábado, e guarda sua mão para não cometer algum mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'E não fale o filho do estrangeiro, que tiver se ligado ao SENHOR, dizendo: Certamente o SENHOR me excluiu de seu povo; nem fale o eunuco: Eis que sou uma árvore seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Porque assim diz o SENHOR: Aos eunucos, que guardam os meus sábados, e escolhe aquilo em que me agrado, e permanecem em meu pacto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Eu também lhes darei em minha casa, e dentro de meus muros, lugar e nome, melhor que o de filhos e filhas; darei um nome eterno a cada um deles, que nunca se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'E aos filhos dos estrangeiros, que se ligarem ao SENHOR, para o servirem, e para amarem o nome do SENHOR, e para serem seus servos, todos os que guardarem o sábado, não o profanando, e os que permanecerem em meu pacto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Eu os levarei ao meu santo monte, e lhes farei se alegrarem em minha casa de oração; suas ofertas de queima e seus sacrifícios serão aceitos em meu altar; porque minha casa será chamada “Casa de oração para todos os povos”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Assim diz o Senhor DEUS, que junta os dispersos de Israel: Ainda outros mais lhe ajuntarei, além dos que já lhe foram ajuntados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Todos vós, animais do campo, vinde comer!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Todos os seus vigilantes são cegos, nada sabem; todos são cães mudos, não podem latir; andam adormecidos, estão deitados, e amam cochilar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'E estes são cães gulosos, não conseguem se satisfazer; e eles são pastores que nada sabem entender; todos eles se viram a seus caminhos, cada um à sua ganância, cada um por si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Eles dizem: Vinde, trarei vinho, e nos encheremos de bebida alcoólica; e o dia de amanhã será como hoje, e muito melhor!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'O justo perece, e ninguém há que pense nisso em seu coração; e os bons são levados, sem que ninguém dê atenção, que o justo é levado de diante do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Ele entrará em paz; descansarão em suas camas aqueles que vivem corretamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Mas chegai-vos aqui, filhos da adivinha, descendência adúltera, e que cometeis pecados sexuais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'De quem fazeis piadas de escárnio? Contra quem alargais a boca, e colocais a língua para fora? Por acaso não sois filhos da transgressão, e descendentes da falsidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Não sois vós, que vos inflamais com os ídolos abaixo de toda árvore verde, e sacrificais os filhos nos vales, abaixo das fendas dos penhascos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Nas pedras lisas dos ribeiros está tua parte; estas, estas são aquilo que te pertence; a estas também derramas ofertas de líquidos, e lhe apresenta ofertas. Por acaso ficaria eu contente com estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Sobre altos e elevados montes pões tua cama; e a eles sobes para oferecer sacrifícios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'E debaixo das portas e dos umbrais pões teus memoriais; porque a não a mim, mas a outros tu te descobres, e sobes, alargas tua cama, e fazes pacto com eles; amas a cama deles, a nudez que tu vês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'E foste ao rei com óleo, e multiplicaste teus perfumes; e enviaste teus embaixadores para longe, e desceste até o mundo dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Em tua longa viagem te cansaste, porém não disseste: Não tenho mais esperança.Achaste força em tua mão, por isso não desanimaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Mas de quem tiveste receio e temeste? Por que mentiste, e não te lembraste de mim, nem pensaste em mim em teu coração? Por eu ter me calado desde muito tempo, agora não me temes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Eu declararei abertamente a tua justiça, e tuas obras; mas elas não te trarão proveito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Quando tu vieres a clamar, que os ídolos que juntaste te livrem; porém o vento levará a todos eles, e um sopro os arrebatará; mas aquele que confia em mim herdará a terra, e tomará posse do meu santo monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'E será dito: Aplanai! Aplanai! Preparai o caminho! Tirai os tropeços do caminho do meu povo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Porque assim diz o Alto e Sublime, que habita na eternidade, e cujo nome é santo: Na altura e no lugar santo habito; e também com o contrito e abatido espírito, para vivificar o espírito dos abatidos, e para vivificar o coração dos contritos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Pois não brigarei para sempre, nem ficarei continuamente indignado; pois perderia todas as forças diante de mim o espírito, as almas que eu criei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Pela maldade de sua cobiça eu me indignei, e o feri; eu me escondi, e me indignei; porém ele se rebelou seguindo o caminho de seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Tenho visto seus caminhos; porém eu o sararei, e o guiarei, e voltarei a dar consolo, a ele a os que por ele lamentam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Eu crio os frutos dos lábios; paz, paz para os que estão longe e para os que estão perto,diz o SENHOR, e eu os sararei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mas os perversos são como o mar bravo, que não pode se aquietar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Os perversos, (diz meu Deus), não tem paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Clama em alta voz, não te retenhas; levanta tua voz como trombeta; e anuncia a meu povo sua transgressão, e à casa de Jacó seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Porém eles me buscam diariamente, e tem prazer em conhecer os meus caminhos, como se fossem um povo que pratica justiça, e não abandona o juízo de seu Deus; perguntam-me pelos juízos de justiça, e tem prazer em se achegarem a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Eles dizem: Por que nós jejuamos, e tu não dás atenção a isso? Por que afligimos nossas almas, e tu não o reconheces?Eis que nos dia em que jejuais, continuais a buscar apenas aquilo que vos agrada, e sobrecarregais todos os que trabalham para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Eis que jejuais para brigas e discussões, e para dardes socos de maldade; não jejueis como fazeis hoje, para que vossa vossa voz seja ouvida no alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Seria este o jejum que eu escolheria, que o homem um dia aflija sua alma, incline sua cabeça como o junco, e estenda debaixo de si saco e cinza? Chamarias tu a isto jejum e dia agradável ao SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Por acaso não é este o jejum que eu escolheria: que soltes os nós de perversidade, que desfaças as amarras do jugo, e que libertes aos oprimidos, e quebres todo jugo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Por acaso não é também que repartas teu pão com o faminto, e aos pobres desamparados recolhas em casa, e vendo ao nu, que o cubras, e não te escondas de tua carne?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Quando fizeres isto, então tua luz surgirá como o amanhecer, e tua cura logo chegará; e tua justiça irá adiante de ti; a glória do SENHOR será tua retaguarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Então clamarás, e o SENHOR te responderá; gritarás, e dirá: Eis-me aqui; se tirares do meio de ti o jugo, o estender de dedo, e o falar perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'E se abrires tua alma ao faminto, e fartares à alma afligida; então tua luz nascerá das trevas, e tua escuridão será como o meio-dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'E o SENHOR te guiará continuamente, fartará a tua alma mesmo em grandes secas, e fortalecerá teus ossos; e tu serás como um jardim regado, como um manancial de águas, cujas águas nunca faltam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'E os que de ti procederem edificarão os lugares antes arruinados, e levantarás os fundamentos das gerações passadas; e te chamarão reparador das coisas que se romperam, e restaurador das ruas para se morar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Se quanto ao sábado recusares fazer tua vontade no meu santo dia, e chamares ao sábado de agradável, santificado ao SENHOR, e glorioso, e tu o honrares, não seguindo teus caminhos, nem buscando tua própria vontade, falando o que não se deve,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Então tu te agradarás no SENHOR, e te farei montar sobre as alturas da terra; e te darei sustento com a herança de teu pai Jacó; porque assim a boca do SENHOR falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Eis que a mão do SENHOR não está encolhida, para que não possa salvar; nem seu ouvido surdo, para não poder ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Porém vossas perversidades fazem separação entre vós e vosso Deus; e vossos pecados encobrem o rosto dele de vós, para que não ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Porque vossas mãos estão contaminadas de sangue, e vossos dedos de maldade; vossos lábios falam falsidade, vossa língua pronuncia perversidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Ninguém há que clame pela justiça, nem ninguém que defenda causa em juízo por meio da verdade; confiam naquilo que é inútil, e falam mentiras; são causadores de opressão, e geram injustiça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Chocam ovos de serpente, e tecem teias de aranha; quem comer de seus ovos morrerá, e sairá uma cobra venenosa se forem pisados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Suas teias não servem para vestimentas, nem poderão se cobrir com suas obras; suas obras são obras de injustiça, e atos de violência há em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Seus pés correm para o mal, e se apressam para derramarem sangue inocente; seus pensamentos são pensamentos de injustiça, destruição e ruína há em suas estradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'O caminho da paz eles não conhecem, nem há justiça em seus percursos; entortam suas veredas para si mesmos; todo aquele que anda por elas não experimentará paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Por isso o juízo está longe de nós, nem a justiça nos alcança; esperamos luz, porém eis que há somente trevas; esperamos brilho, porém andamos às escuras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Apalpamos as paredes como cegos, e como se não tivéssemos olhos andamos apalpando; tropeçamos ao meio-dia como se fosse noite; entre os fortes estamos como mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Todos nós bramamos como ursos, e continuamente gememos como pombas; esperamos pela justiça, e nada acontece; esperamos pela salvação, porem ela está longe de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Pois nossas transgressões se multiplicaram diante de ti, e nossos pecados dão testemunho contra nós; pois nossas transgressões estão conosco, e conhecemos nossas perversidades,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Tais como: transgredir e mentir contra o SENHOR, e se desviar de seguir a nosso Deus; falar de opressão e rebelião, conceber e falar palavras de falsidade do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Por isso que o direito retrocedeu, e a justiça ficou de longe; pois a verdade tropeçou na praça, e a correta decisão não pode entrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'E a verdade se perde, e quem se desvia do mal corre o risco de ser saqueado; e o SENHOR o viu, pareceu mal em seus olhos, por não haver justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'E vendo que ninguém havia, maravilhou-se de que não houvesse intercessor algum; por isso seu próprio braço lhe trouxe a salvação, e sua própria justiça o susteve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Pois ele se vestu de justiça como uma armadura, e pôs o capacete da salvação em sua cabeça; e vestiu-se de roupas de vingança como vestimenta, e cobriu-se de selo como uma capa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Ele lhes retribuirá conforme suas obras: furor a seus adversários, pagamento a seus inimigos; às terras litorâneas ele pagará de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Então temerão o nome do SENHOR desde o ocidente, e sua glória desde o oriente; pois ele vem como uma correnteza impetuosa, empurrada pelo sopro do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'E um Redentor virá a Sião, para aqueles que se arrependerem de sua transgressão em Jacó, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Quanto a mim, este é meu pacto com eles,diz o SENHOR; meu Espírito que está sobre ti, e minhas palavras que pus em tua boca, não se afastarão de tua boca nem da boca de teus descendentes, nem da boca dos descendentes de teus descendentes, diz o SENHOR, desde agora e para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Levanta-te! Brilha! Porque já chegou a tua luz; e a glória do SENHOR já está raiando sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Porque eis que as trevas cobrirão a terra, e a escuridão aos povos; porém sobre ti o SENHOR virá raiando, e sua glória será vista sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'E as nações virão à tua luz, e os reis ao brilho que raiou a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Levanta teus olhos ao redor, e vê; todos estes se ajuntaram, e vem a ti; teus filhos virão de longe, e tuas filhas serão criadas ao teu lado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Então verás, e te alegrarás; teu coração palpitará e se encherá de alegria, porque a abundância do mar a ti se voltará, as riquezas das nações a ti chegarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Multidão de camelos te cobrirá; dromedários de Midiã e Efá, todos virão de Sabá; trarão ouro e incenso, e declararão louvores ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Todas as ovelhas de Quedar se ajuntarão a ti; os carneiros de Nebaiote te servirão; com agrado subirão ao meu altar, e eu glorificarei a casa de minha glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Quem são estes que vêm voando como nuvens, e como pombas às suas janelas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Pois as ilhas me esperarão, e primeiro os navios de Társis, para trazer teus filhos de longe, sua prata e seu ouro com eles; para o nome do SENHOR teu Deus, e para o Santo de Israel, porque ele te glorificou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'E filhos de estrangeiros edificarão teus muros, e seus reis te servirão; porque em minha ira eu te feri, porém em meu favor tive misericórdia de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'E tuas portas estarão continuamente abertas, nem de dia nem de noite se fecharão; para que tragam a ti as riquezas das nações, e seus reis a ti sejam trazidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Pois a nação e reino que não te servirem perecerão; e tais nações serão assoladas por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'A glória do Líbano virá a ti, a faia, o pinheiro, e o cipreste juntamente, para ornamentarem o lugar do meu santuário, e glorificarei o lugar de meus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Também virão a ti inclinados os filhos dos que te oprimiram, e se prostrarão às pisadas de teus pés todos os que blasfemaram de ti; e te chamarão a cidade do SENHOR, a Sião do Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Em vez de abandonada e odiada, de tal modo que ninguém passava por ti,eu farei de ti uma excelência eterna, alegria de geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'E mamarás o leite das nações, e mamarás os peitos dos reis; e saberás que eu sou o SENHOR, teu Salvador e teu Redentor, o Poderoso de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Em vez de bronze trarei ouro, e em vez de ferro trarei prata, e em vez de madeira bronze, e em vez de pedras ferro; e farei pacíficos teus oficiais, e justos aqueles que cobram de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nunca mais se ouvirá falar de violência em tua terra; nem ruína, nem destruição dentro de tuas fronteiras; em vez disso, a teus muros chamarás Salvação, e a tuas portas Louvor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nunca mais o sol te servirá para luz do dia, nem com seu brilho a lua te iluminará; mas o SENHOR será tua luz eterna, e teu Deus o teu ornamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nunca mais o teu sol irá se por, nem tua lua minguará; porque o SENHOR será tua luz eterna, e os dias de teu luto se acabarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'E todos os de teu povo serão justos; para sempre terão posse da terra; serão renovo de minha plantação, obra de minhas mãos, para que eu seja glorificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'O menor será mil, e o de menor tamanho será um povo forte; eu, o SENHOR, o farei depressa em seu devido tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'O Espírito do Senhor DEUS está sobre mim; pois o SENHOR me ungiu, para dar boas novas aos mansos; ele me enviou para sarar aos feridos de coração, para anunciar liberdade aos cativos, e libertação aos prisioneiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Para anunciar o ano do favor do SENHOR, e o dia da vingança de nosso Deus; para consolar todos os tristes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Para ordenar aos tristes de Sião, que lhes seja dado ornamento no lugar de cinza, óleo de alegria no lugar de tristeza, vestes de louvor no lugar de espírito angustiado; para que sejam chamados de carvalhos da justiça, plantação do SENHOR; para que ele seja glorificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'E edificarão os lugares arruinados desde os tempos antigos, restaurarão os desde antes destruídos, e renovarão as cidades arruinadas, destruídas desde muitas gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'E estrangeiros apascentarão vossos rebanhos, e filhos de outras nações serão vossos lavradores e vossos trabalhadores nas vinhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Porém vós sereis chamados sacerdotes do SENHOR; chamarão a vós de trabalhadores a serviço de nosso Deus; comereis dos bens das nações, e da riqueza deles vós vos orgulhareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Em vez de vossa vergonha, tereis porção dobrada; e em vez de humilhação, terão alegria sobre sua parte; pois em sua terra terão posse do dobro, e terão alegria eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Porque eu, o SENHOR, amo a justiça, e odeio o roubo com sacrifício de queima; e farei que sua obra seja em verdade, e farei um pacto eterno com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'E sua descendência será conhecida entre as nações, e seus descendentes em meio aos povos; todos quantos os virem, os reconhecerão, que são descendência abençoada pelo SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Eu estou muito jubilante no SENHOR, minha alma se alegra em meu Deus; porque ele me vestiu de roupas de salvação; ele me cobriu com a capa da justiça, tal como o noivo quando se veste da roupa sacerdotal, e como a noiva se enfeita com suas joias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Porque tal como a terra produz seus renovos, e como o jardim faz brotar o que nele se semeia, assim também o Senhor DEUS fará brotar justiça e louvor diante de todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Por Sião eu não me calarei, e por Jerusalém não me aquietarei, enquanto sua justiça não sair como um brilho, e sua salvação como uma tocha acesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'E as nações verão tua justiça, e todos os reis verão tua glória; e te chamarão por um novo nome, que a boca do SENHOR determinará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'E serás coroa de glória na mão do SENHOR, e diadema real na mão de teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Nunca mais te chamarão de abandonada, nem se referirão mais a tua terra como assolada; mas sim te chamarão de: “Nela Está Meu Prazer”, e à tua terra de “A Casada”, porque o SENHOR se agrade de ti, e tua terra se casará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Porque tal como o rapaz se casa com a virgem, assim também teus filhos se casarão contigo; e como o noivo se alegra da noiva, assim o teu Deus se alegrará de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Jerusalém, obre os teus muros eu pus guardas, que o dia todo e a noite toda continuamente não se calarão; vós que fazeis menção do SENHOR, não haja silêncio em vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Nem deis descanso a ele, até que ele estabeleça, até que ele ponha a Jerusalém como louvor na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'O SENHOR jurou por sua mão direita e pelo seu forte braço: Nunca mais darei teu trigo como comida a teus inimigos, nem estrangeiros beberão teu suco da uva em que trabalhaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Mas sim aqueles que o ajuntarem o comerão, e louvarão ao SENHOR; e os que o colherem beberão nos pátios do meu santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Passai! Passai pelas portas! Preparai o caminho ao povo! Aplanai! Aplanai a estrada, limpai -a das pedras! Levantai uma bandeira aos povos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Eis que o SENHOR fez ouvir até a extremidade da terra: Dizei à filha de Sião: eis que tua salvação está vindo; eis que traz sua recompensa consigo, e seu pagamento vem diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'E os chamarão de povo santo, redimidos do SENHOR; e tu serás chamada “A Procurada, a Cidade Não Desemparada”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Quem é este, que vem de Edom, de Bozra, com vestes salpicadas de vermelho, este ornado em sua vestimenta, que marcha com grande força? Eu, o que falo em justiça, poderoso para salvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Por que tu estás de roupa vermelha, e tuas vestes como de alguém que pisa num lagar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Eu sozinho pisei o lagar, e ninguém dos povos houve comigo; e os pisei em minha ira, e os esmaguei em meu furor; e o sangue deles salpicou sobre minhas roupas, e sujei toda a minha vestimenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Porque o dia da vingança estava em meu coração; e o ano de meus redimidos havia chegado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'E olhei, e não havia quem me ajudasse; e me espantei de que não houvesse quem me apoiasse; por isso meu braço me trouxe a salvação, e meu furor me apoiou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'E atropelei os povos em minha ira, e os embebedei em meu furor; e fiz descer o sangue deles até a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Farei menção das bondades do SENHOR, e dos louvores ao SENHOR, conforme tudo quanto o SENHOR fez para nós; e do grande bem à casa de Israel, que ele tem lhes concedido segundo suas misericórdias, e segundo a abundância de suas bondades;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Pois ele dizia: Certamente eles são meu povo, são filhos que não mentirão; assim ele se tornou o Salvador deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Em toda a angústia deles, ele também se angustiou, e o anjo de sua presença os salvou; por seu amor e por sua piedade ele os redimiu; e os tomou, e os carregou em todos os dias antigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Porém eles foram rebeldes, e entristeceram seu Espírito Santo; por isso ele se tornou inimigo deles, e ele mesmo lutou contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Contudo ele se lembrou dos dias antigos, de Moisés, e de seu povo. Onde está aquele que os fez subir do mar com os pastores de seu rebanho? Onde está aquele que punha no meio deles seu Espírito Santo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Onde está aquele que fez seu glorioso braço andar à direita de Moisés, que dividiu as águas perante a presença deles, para fazer seu nome eterno;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Que os guiou pelos abismos como cavalo no deserto, de tal modo que nunca tropeçaram?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Tal como um animal que desce aos vales, o Espírito do SENHOR lhes deu descanso; assim guiaste a teu povo, para fazeres teu nome ser glorioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Olha desde os céus, e vê desde tua santa e gloriosa habitação; onde está teu zelo e tuas forças? A comoção dos sentimentos de teu interior e de tuas misericórdias se retiveram para comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Porém tu és nosso Pai, porque Abraão não sabe de nós, nem Israel nos conhece. Tu, SENHOR, és nosso Pai; desde os tempos antigos o teu nome é Nosso Redentor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Por que, ó SENHOR, tu nos fazes andar fora de teus caminhos? Por que endureces nosso coração para que não tenhamos temor a ti? Volta, por favor a teus servos, às tribos de tua herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Por um pouco de tempo teu santo povo a possuiu; nossos adversários pisaram teu santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Nós nos tornamos como aqueles de quem nunca dominaste, semelhantes aos que nunca foram chamados pelo teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Ah, se tu rompesses os céus, e descesses, os montes se tremeriam de diante de tua presença,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Tal como o fogo acende a madeira, e o fogo faz ferver as águas; para assim fazeres notório o teu nome a teus adversários, de modo que as nações tremessem de tua presença!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Como quando fazias coisas temíveis, as quais nunca esperávamos; quando tu descias, e os montes se tremiam diante de tua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Nem desde os tempos antigos se ouviu, nem com os ouvidos se percebeu, nem olho viu outro Deus além de ti, que age em favor daquele que nele espera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Tu foste ao encontro do alegre, e do que pratica justiça, e aos que se lembram de ti em teus caminhos. Eis que te enfureceste porque pecamos por muito tempo. Seremos salvos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Porém todos nós somos como um imundo, e todas as nossas justiças são como roupas contaminadas; e todos nós caímos como uma folha, e nossas culpas nos levam como o vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'E ninguém há que invoque a teu nome, que se desperte para se apegar a ti; pois tu escondeste teu rosto de nós, e nos consumiste por nossas perversidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Porém agora, SENHOR, tu és nosso Pai; nós somos barro, e tu és nosso oleiro; e todos nós somos obra de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Não te enfureças tanto, SENHOR, nem te lembres da nossa perversidade para sempre; vê, olha agora, que todos nós somos teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Tuas santas cidades se tornaram um deserto; Sião se tornou um deserto; Jerusalém está assolada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Nossa santa e nossa gloriosa casa, em que nossos pais te louvavam, foi queimada a fogo; e todas as coisas com que nos agradávamos se tornaram ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Será que continuarás a te conter sobre estas coisas, SENHOR? Continuarás quieto, e nos oprimindo tanto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Fui buscado por aqueles que não perguntavam por mim; fui achado por aqueles que não me buscavam; a uma nação que não se chamava pelo meu nome eu disse: Eis-me aqui! Eis-me aqui!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Estendi minhas mãos o dia todo a um povo rebelde, que anda por um caminho que não é bom, seguindo seus próprios pensamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Povo que me irrita perante mim continuamente, sacrificando em jardins, e queimando incenso sobre tijolos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Sentando-se junto às sepulturas, e passando as noites em lugares secretos; comendo carne de porco, e tendo caldo de coisas abomináveis em suas vasilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'E dizem: Fica onde estás, e não te aproximes de de mim; pois sou mais santo do que tu; Estes são fumaça em minhas narinas, e fogo que arde o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Eis que está escrito diante de mim: Não me calarei; mas eu pagarei, e lhes pagarei diretamente e por completo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Por vossas perversidades e juntamente pelas perversidades de vossos pais,diz o SENHOR, que com incensos perfumaram nos montes, e me provocaram nos morros; por isso eu lhes medirei de volta por completo o pagamento de suas obras anteriores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Assim diz o SENHOR: Tal como quando se acha suco num cacho de uvas, dizem: Não o desperdices, pois há proveito nele; assim eu farei por meus servos; não destruirei a todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Mas produzirei descendência de Jacó, e de Judá um herdeiro, que seja dono de meus montes; e meus escolhidos tomarão posse da terra,e meus servos ali habitarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'E Sarom servirá de pasto de ovelhas, e o vale de Acor como lugar de repouso de gado, para o meu povo, que me buscou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Porém a vós, que vos afastais do SENHOR, vós que esqueceis do meu santo monte, que preparais mesa para o ídolo da sorte, e que misturais bebida para o ídolo do destino;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Eu vos destinarei à espada, e todos vós encurvareis à matança; pois eu chamei, e vós não respondestes; falei, e não ouvistes; mas fizestes o que era mal aos meus olhos, e escolhestes aquilo de que não me agrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Por isso assim diz o Senhor DEUS: Eis que meus servos comerão, porém vós passareis fome; eis que meus servos beberão, porém vós tereis sede; eis que meus servos se alegrarão, porém vós vos envergonhareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Eis que meus servos cantarão de coração contente, porém vós gritareis de tristeza do coração; e uivareis pela angústia de espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'E deixarei vosso nome a meus eleitos como maldição; e o Senhor DEUS te matará; porém ele chamará aos seus servos por outro nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Quem se bendisser na terra, se bendirá no Deus da verdade; e quem jurar na terra, jurará pelo Deus da verdade; porque serão esquecidas as angústias passadas, e porque elas estarão encobertas de diante de meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Porque eis que eu crio novos céus e nova terra; e não haverá mais lembrança das coisas passadas, nem mais virão à mente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Porém vós ficai contentes e alegrai-vos para sempre naquilo que eu crio; porque eis que crio a Jerusalém uma alegria, e a seu povo um contentamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'E me alegrarei de Jerusalém, e estarei muito contente com meu povo; e nunca mais se ouvirá nela voz de choro, nem voz de clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Não haverá mais ali bebês de poucos dias, nem velho que não cumpra seus dias; porque o jovem morrerá aos cem anos, porém o pecador de cem anos de idade será amaldiçoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'E edificarão casas, e as habitarão; e plantarão vinhas, e comerão o fruto delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Eles não edificarão para que outros habitem, nem plantarão para que outros comam; porque os dias de meu povo serão como os dias das árvores, e meus escolhidos usarão das obras de suas mãos até a velhice.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Não trabalharão em vão, nem terão filhos para a aflição; porque são a semente dos benditos do SENHOR, e seus descendentes com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'E será que, antes que clamem, eu responderei; enquanto ainda estiverem falando, eu ouvirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'O lobo e o cordeiro ambos se alimentarão juntos, e o leão comerá palha como o boi, e pó será a comida da serpente; nenhum mal nem dano farão em todo o meu santo monte,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Assim diz o SENHOR: Os céus são meu trono, e a terra o escabelo dos meus pés. Qual seria a casa que vós edificaríeis para mim? E qual seria o lugar de meu descanso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Pois minha mão fez todas estas coisas, e todas estas coisas passaram a existir,diz o SENHOR; mas para tal eu olharei: aquele que é pobre e abatido de espírito, e treme por minha palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Quem mata boi fere de morte a um homem; quem sacrifica cordeiro degola a um cão; quem apresenta oferta, oferece sangue de proco; quem oferece incenso adora a um ídolo; também estes escolhem seus próprios caminhos, e sua alma tem prazer em suas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Eu, então, escolherei a punição para eles, e farei vir sobre eles os seus temores; pois clamei, mas ninguém respondeu; falei, mas não escutaram; ao invés disso fizeram o que era mal aos meus olhos, e escolheram aquilo que não me agrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Ouvi a palavra do SENHOR, vós que tremeis por sua palavra; vossos irmãos, que vos odeiam, e vos expulsaram para longe por causa do meu nome, dizem: Que o SENHOR seja glorificado, para que vejamos vossa alegria; eles, porém, serão envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Haverá uma voz de grande ruído, uma voz do Templo: é a voz do SENHOR, que dá pagamento a seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Antes que estivesse em trabalho de parto, ela já deu à luz; antes que viessem as dores, ela já fez sair de si um filho macho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Quem jamais ouviu tal coisa? Quem viu coisa semelhante? Poderia uma terra gerar filho em um só dia? Nasceria uma nação de uma só vez? Mas logo que Sião esteve de parto, já teve o nascimento de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Por acaso não iniciaria eu o nascimento e não geraria?,diz o SENHOR, Geraria eu, e fecharia o ventre materno?, diz o teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Alegrai-vos com Jerusalém, e enchei-vos de alegria por causa dela, todos vós que a amais; alegrai-vos muito com ela, todos vós que chorastes por ela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Para que mameis e vos sacieis dos consoladores seios dela; para que sugueis e vos deleiteis com a abundância de sua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Porque assim diz o SENHOR: Eis que estenderei sobre ela a paz como um rio, e a glória das nações como um ribeiro que transborda; então mamareis; sereis levados ao colo, e sobre os joelhos vos afagarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Tal como alguém a quem sua mãe consola, assim também eu vos consolarei; e em Jerusalém sereis consolados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'E vereis; então vossos corações se alegrarão, e vossos ossos se avivarão como a erva que brota. E a mão do do SENHOR será conhecida pelos seu servos, e se enfurecerá contra seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Porque eis que o SENHOR virá com fogo, e suas carruagens como um redemoinho de vento; para transformar sua ira em furor, e sua repreensão em chamas de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Porque com fogo e com sua espada o SENHOR julgará toda carne; e os mortos pelo SENHOR serão muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Os que se consagram e se purificam nos jardins para seguirem aquele que está no meio deles; os que comem carne de porco, abominações, e ratos, juntamente serão consumidos, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Porque eu conheço suas obras e seus pensamentos. O tempo vem, em que juntarei todas as nações e línguas; e elas virão, e verão minha glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'E porei nelas um sinal; e a uns que delas sobreviverem enviarei às nações: a Társis, Pul e Lude; aos flecheiros, a Tubal e Javã; até as terras costeiras mais distantes, que não ouviram minha fama, nem viram minha glória; e anunciarão minha glória entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'E trarão a todos os vossos irmãos dentre todas as nações como oferta ao SENHOR, sobre cavalos, e em carruagens, liteiras, mulas e dromedários, ao meu santo monte, a Jerusalém, diz o SENHOR, tal como os filhos de Israel trazem ofertas em vasos limpos à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'E também tomarei a alguns deles para serem sacerdotes e para Levitas,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Porque assim como os novos céus e a nova terra, que farei, estarão perante mim,diz o SENHOR, assim também estará vossa descendência e vosso nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'E será que, desde uma lua nova até a outra, e desde um sábado até o outro, todos virão para adorar perante mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'E sairão, e verão os cadáveres dos homens que se rebelaram contra mim; porque o verme deles nunca morrerá, nem seu fogo se apagará; e serão horríveis a todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Palavras de Jeremias, filho de Hilquias, um dos sacerdotes que estiveram em Anatote, na terra de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Ao qual veio a palavra do SENHOR nos dias de Josias, filho de Amom, rei de Judá, no décimo terceiro ano de seu reinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Veio também nos dias de Jeoaquim, filho de Josias, rei de Judá, até o fim do décimo primeiro ano de Zedequias, filho de Josias, rei de Judá, até que Jerusalém foi levada cativa no quinto mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Veio, pois, a palavra do SENHOR a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Antes que te formasse no ventre eu te conheci, e antes que saísses do útero eu te santifiquei, te dei por profeta às nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'E eu disse: Ah! Senhor DEUS! Eis que não sei falar, pois sou um menino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Porém o SENHOR me disse: Não digas: sou menino; porque a todos a quem eu te enviar tu irás, e falarás tudo quanto eu te mandar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Não temas diante deles, porque estou contigo para te livrar, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Então o SENHOR estendeu sua mão, e tocou em minha boca. E o SENHOR me disse: Eis que tenho posto minhas palavras em tua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Olha que eu te pus neste dia sobre nações e sobre reinos, para arrancar e para derrubar, e para destruir e para arruinar, e para edificar e para plantar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'E a palavra do SENHOR veio a mim, dizendo: O que tu vês, Jeremias? E eu disse: Vejo uma vara de amendoeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'E disse-me o SENHOR: Viste bem; porque eu apresso minha palavra para cumpri-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'E veio a mim palavra do SENHOR segunda vez, dizendo: O que tu vês? E eu disse: Vejo uma panela fervente; e sua face está voltada para o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Então o SENHOR me disse: Do norte o mal será solto sobre todos os moradores do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Porque eis que eu convoco todas as famílias dos reinos do norte,diz o SENHOR; e virão, e cada um porá seu trono à entrada das portas de Jerusalém, e junto a todos seus muros ao redor, e em todas as cidades de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'E pronunciarei meus juízos contra eles por causa de toda a sua maldade, pois me deixaram, e queimaram incenso a deuses estranhos, e se encurvaram a objetos de suas próprias mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Tu pois, prepara tua roupa, e te levanta-te; e fala-lhes tudo quanto eu te mandar; não tenhas medo diante deles, para que eu não te faça ter medo diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Porque eis que eu te ponho hoje como cidade fortificada, e como coluna de ferro, e como muro de bronze contra todo o país; contra os reis de Judá, seus príncipes, seus sacerdotes, e contra o povo do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'E lutarão contra ti, mas não te vencerão; porque eu sou contigo, diz o SENHOR, para te livrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'E veio a mim palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Vai, e clama aos ouvidos de Jerusalém, dizendo: Assim diz o SENHOR: Lembro-me de ti, da tua bondade que tinhas em tua juventude, do amor do teu noivado, quando andavas após mim no deserto, em terra não semeada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Israel era santidade ao SENHOR, era os primeiros de sua colheita. Todos os que o prejudicavam cometiam pecado e o mal vinha sobre eles, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Ouvi a palavra do SENHOR, ó casa de Jacó, e todas as famílias da casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Assim diz o SENHOR: Que maldade vossos pais acharam em mim, para terem se afastado de mim, de modo que seguiram coisas inúteis, e eles mesmos se tornarão inúteis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Eles nem disseram: Onde está o SENHOR, que nos fez subir de terra do Egito, que nos guiou pelo deserto, por uma terra deserta e esburacada, por uma terra seca e de sombra de morte, por uma terra pela qual ninguém passava, nem ali homem algum habitava?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'E eu vos trouxe à terra de Carmelo, para que comêsseis seu fruto e seu bem; mas entrastes, e contaminastes minha terra, e fizestes minha propriedade abominável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Os sacerdotes não disseram: Onde está o SENHOR? E os que teriam de usar a lei não me conheceram; e os líderes se rebelaram contra mim, e os profetas profetizaram em nome de Baal, e seguiram aquilo que não tem proveito algum');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Por isso ainda brigarei em juízo convosco, diz o SENHOR, e disputarei com os filhos de vossos filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Pois passai às ilhas do Chipre e vede; e enviai mensageiros a Quedar, e prestai atenção, e vede se aconteceu alguma coisa semelhante a esta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Se alguma nação tenha mudado de deuses, ainda que eles não sejam deuses. Mas meu povo trocou sua glória pelo que não tem proveito algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Espantai-vos, céus, por causa disto, e horrorizai-vos; ficai bastante desolados, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Pois meu povo fez dois males: deixaram a mim, que sou fonte de água viva, para cavarem para si cisternas, cisternas rachadas, que não retêm águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Por acaso Israel é um servo? É um escravo de nascimento? Por que, então,ele se tornou uma presa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Os filhotes de leão bramaram sobre ele, deram sua voz; e tornaram sua terra uma assolação; suas cidades estão queimadas, sem morador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Até os filhos de Nofe e de Tafnes te quebraram o topo da cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Não foi tu mesmo que procuraste isto para ti, de abandonar ao SENHOR teu Deus, enquanto andavas pelo caminho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Ora, o que tu tens a ver com o caminho do Egito, para que bebas água do Nilo? E o que tens a ver com o caminho de Assíria, para que bebas água do rio Eufrates?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'A tua maldade te castigará e tuas infidelidades te repreenderão; então conhece e vê como é mal e amargo teres abandonado ao SENHOR teu Deus, e não teres tido temor a mim, diz o Senhor DEUS dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Pois muito tempo atrás, eu quebrei teu jugo, e rompi tuas amarras, e tu disseste: Não servirei. Porém sobre todo morro alto e abaixo de toda árvore frondosa tu te deitavas como prostituta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'E eu te plantei de boa vide; ela toda era semente confiável. Como, pois, te tornaste para mim ramos de vide estranha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Ainda que te laves com potassa, e passes muito sabão sobre ti, teu pecado está marcado diante de mim, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Como podes dizer: Nunca me contaminei, nunca andei atrás dos baalins? Olha o teu caminho no vale; reconhece o que fizeste, ó dromedária ligeira, que anda errante seus percursos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'jumenta selvagem acostumada ao deserto, que aspira o vento por causa do desejo da alma; de seu cio quem a deteria? Todos os que a buscarem não se cansarão; no mês dela a acharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Impede que teus pés andem descalços, e tua garganta tenha sede. Porém tu disseste: Não há mais esperança; não, porque amo estranhos, e tenho que ir atrás deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Tal como o ladrão se envergonha quando é pego, assim se envergonharão os da casa de Israel; eles, seus reis, seus príncipes, seus sacerdotes, e seus profetas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Que dizem à madeira: Tu és meu pai; e à pedra: Tu me geraste: pois viraram as costas em minha direção, e não o rosto; porém no tempo de sua angústia dizem: Levanta-te, e livra-nos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Onde estão os teus deuses que fizeste para ti? Eles que se levantem, se é que eles podem te livrar no tempo de tua aflição; porque, ó Judá, os teus deuses foram tantos quantos o número de tuas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Por que discutis comigo? Todos vós transgredistes contra mim, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Em vão afligi vossos filhos; eles não aceitaram correção. Vossa própria espada matou vossos profetas como um leão destruidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Ó geração, considerai vós a palavra do SENHOR. Por acaso eu fui um deserto ou uma terra de escuridão a Israel? Então por que meu povo tem dito: Somos senhores; nunca mais viremos a ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Por acaso a virgem se esquece de seus enfeites, ou a noiva de seus adornos? Porém meu povo se esqueceu de mim há inúmeros dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Como enfeitas teu caminho para buscar amor! Pois até às malignas ensinaste teus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Até nas bordas de tuas roupas se achou o sangue das almas dos pobres inocentes; não o achaste em arrombamento, mas em todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'E dizes: Sou inocente, pois certamente sua ira já se afastou de mim. Eis que eu disputarei em juízo contigo, porque disseste: Não tenho pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Por que tu te desvias tanto, mudando teus caminhos? Também serás envergonhada pelo Egito, tal como foste envergonhada pela Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Também sairás daqui com as mãos sobre tua cabeça; porque o SENHOR rejeitou tuas confianças, e nelas não terás sucesso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Dizem: Se um homem deixar sua mulher, e ela for embora dele, e se juntar a outro homem, por acaso ele voltará a ela? Não será tal terra contaminada por completo? Tu porém tem te prostituído com muitos amantes; mas volta-te a mim, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Levanta teus olhos aos lugares altos, e vê onde não tenhas te prostituído; tu te sentavas para eles nos caminhos, como árabe no deserto; e assim contaminaste a terra com tuas prostituições e com tua malícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Por isso as águas foram retidas, e não houve a chuva tardia; porém tu tens a testa de uma prostituta, e não aceitas ter vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Não foi agora que clamaste a mim: Meu Pai, tu és o guia de minha juventude?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Por acaso ele manterá sua ira para sempre?Ele a guardará para sempre? Eis que isto tu falas, porém tu tens feito tantas maldades quanto pudeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Disse-me mais o SENHOR nos dias do rei Josias: Viste o que fez a rebelde Israel? Ela foi sobre todo monte alto e debaixo de toda árvore frondosa, e ali ela se prostituiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'E eu disse depois que ele fez tudo isto: Volta para mim; mas ela não voltou. E sua traiçoeira irmã Judá viu isto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'E eu vi, que por todas estas causas nas quais prostituiu a infiel Israel, eu a tinha mandado embora, e dado-lhe a carta de seu divórcio; porém a traiçoeira Judá sua irmã não temeu; ao contrário; ela também foi se prostituir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'E aconteceu que foi pela leviandade de sua prostituição que a terra foi contaminada, e ela adulterou com a pedra e com a madeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'E mesmo com tudo isto, a traiçoeira, sua irmã Judá, não se converteu a mim de todo o seu coração, mas sim falsamente, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'E disse-me o SENHOR: Israel mostrou-se mais justa em sua alma, mais do que a traiçoeira Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Vai, e proclama estas palavras ao norte, e diz: Volta-te, ó infiel Israel, diz o SENHOR; não farei cair minha ira sobre vós: pois sou misericordioso, diz o SENHOR; não guardarei a ira para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Tão somente reconhece tua maldade, pois transgrediste contra o SENHOR teu Deus, e espalhaste teus caminhos aos estrangeiros debaixo de toda árvore frondosa, e não ouviste minha voz, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Convertei-vos, filhos infiéis, diz o SENHOR, pois sou vosso marido; e eu os tomarei um de uma cidade, e dois de uma família, e vos levarei a Sião;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'E vos darei pastores conforme meu coração, que vos apascentem de conhecimento e de inteligência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'E será que, quando vos multiplicardes e frutificardes na terra naqueles dias, diz o SENHOR, nunca mais dirão: Arca do pacto do SENHOR; nem virá ao pensamento, nem se lembrarão dela, nem a visitarão, nem será feita novamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Naquele tempo chamarão a Jerusalém: trono do SENHOR, e todas as nações se ajuntarão a ela no nome do SENHOR em Jerusalém; e nunca mais seguirão a teimosia de seu coração maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Naqueles tempos os da casa de Judá andarão com a casa de Israel, e virão juntamente da terra do norte à terra que eu fiz herdar a vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Mas eu disse: Como te porei por filhos, e te darei a terra desejável, a rica propriedade dos exércitos das nações? E disse: tu me chamarás: Meu pai, e não te desviarás de detrás de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Porém, tal como a esposa trai o seu companheiro, assim traístes contra mim, ó casa de Israel, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Uma voz se ouve sobre os lugares altos: é o pranto das súplicas dos filhos de Israel; porque perverteram seu caminho, e se esqueceram do SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Convertei-vos, filhos rebeldes; eu sararei vossas rebeliões.Eis-nos aqui; chegamos a ti, porque tu és o SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Certamente confiar nos morros é inútil, na multidão dos montes; certamente a salvação de Israel está no SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Pois a vergonha consumiu o trabalho de nossos pais desde nossa juventude; suas ovelhas, suas vacas, seus filhos e suas filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Jazemos em nossa vergonha, e nossa humilhação nos cobre; porque pecamos contra o SENHOR nosso Deus, nós e nossos pais, desde nossa juventude até hoje; e não obedecemos a voz do SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Se te converteres, ó Israel,diz o SENHOR, converte-te a mim; e se tirares tuas abominações de diante de mim, não andarás mais sem rumo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'E jurarás, dizendo, Vive o SENHOR, com verdade, com juízo, e com justiça; e nele as nações se bendirão, e nele se orgulharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Porque assim diz o SENHOR aos homens de Judá e de Jerusalém: Fazei lavoura para vós, e não semeeis sobre espinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Circuncidai-vos ao SENHOR, e tirai os prepúcios de vosso coração, ó homens de Judá e moradores de Jerusalém; para que minha ira não venha a sair como fogo, e se incendeie, e não haja quem apague, pela maldade de vossas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Anunciai em Judá, e fazei ouvir em Jerusalém, e dizei: Tocai trombeta na terra. Clamai em alta voz, e dizei: Ajuntai-vos, e entremos nas cidades fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Erguei bandeia para Sião, retirai-vos, não vos detenhais; porque eu trago um mal do norte, e grande destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'O leão já subiu de seu refúgio, e o destruidor de nações já se partiu; ele saiu de seu lugar para pôr tua terra em assolação; tuas cidades serão destruídas, de modo que não haja nelas morador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Por isso vesti-vos de saco, lamentai e uivai; porque o ardor da ira do SENHOR não se desviou de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'E será naquele dia, diz o SENHOR, que o coração do rei e o coração dos príncipes desfalecerão; os sacerdotes ficarão pasmos, e os profetas se maravilharão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Então eu disse: Ah, Senhor DEUS! Verdadeiramente enganaste grandemente a este povo e a Jerusalém, dizendo: Tereis paz; porém a espada chega até a alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Naquele tempo se dirá a este povo e a Jerusalém: Um vento seco dos lugares altos do deserto veio ao caminho da filha do meu povo; não para padejar, nem para limpar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Um vento forte demais para estas coisas virá de mim; agora também eu pronunciarei juízos contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Eis que ele virá subindo como as nuvens, e suas carruagens como o redemoinho de vento; seus cavalos serão mais velozes que as águias;Ai de nós, porque somos assolados!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Lava teu coração da maldade para que sejas salva; ó Jerusalém! Até quando deixarás os teus meus pensamentos permanecerem em meio a ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Porque uma voz se anuncia desde Dã, e fala de calamidade desde o monte de Efraim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Disto mencionai às nações: eis aqui! Proclamai contra Jerusalém: Guardas vêm de uma terra remota, e levantam sua voz contra as cidades de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Como guardas dos campos, assim eles estão ao redor contra ela; pois ela se rebelou contra mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Teu caminho e teus atos te causaram estas coisas; esta é tua maldade, tão amarga, que chega ao teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Ai minhas entranhas, minhas entranhas! Estou com grandes dores nas paredes do meu coração; meu coração se inquieta, não consigo me calar; porque tu, ó alma minha, ouves o som da trombeta, o clamor da guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Destruição sobre destruição se anuncia, pois toda a terra já está arruinada; de repente foram destruídas minhas tendas, num instante minhas cortinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Até quando verei a bandeira, e ouvirei a voz da trombeta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'De fato meu povo está louco, já não me conhecem; são filhos tolos, sem entendimento; são “sábios” para fazer o mal, mas para fazer o bem nada sabem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Vi a terra, e eis que estava sem forma e vazia; e vi os céus, e não tinham sua luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Vi os montes, e eis que estavam tremendo; e todos os morros se sacudiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Vi, e eis que nenhum homem havia; e todas as aves do céu tinham fugido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Vi, e eis que a terra fértil tinha se tornado um deserto, e todas as suas cidades foram derrubadas, por causa do SENHOR, por causa do ardor de sua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Porque assim diz o SENHOR: Toda esta terra será assolada; porém não a destruirei por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Por isto a terra lamentará, e os céus acima se tornarão negros; porque assim falei, assim o propus, e não me arrependerei, nem desviarei disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Do ruído dos cavaleiros e dos flecheiros, os moradores de todas as cidades fugirão; entrarão nos bosques, e subirão em penhascos; todas as cidades ficarão abandonadas, e não haverá nelas morador algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'E que farás tu, ó assolada? Ainda que te vistas de vermelho, ainda que te adornes com ornamentos de ouro, ainda que pintes teus olhos, em vão te enfeitarias; os teus amantes te desprezam, e buscarão matar a tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Porque ouço uma voz, como de mulher que está de parto, uma angústia como de parto de primeiro filho; é a voz da filha de Sião, que lamenta e estende suas mãos, dizendo: Ai de mim agora! Pois minha alma desmaia por causa dos assassinos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Correi pelas ruas de Jerusalém, e olhai agora, e informai-vos, e buscai em suas praças, para ver se achais algum homem, se há alguém que faça juízo, que busque a verdade; e eu a perdoarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'E ainda que digam: Vive o SENHOR; contudo juram falsamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Ah SENHOR, por acaso teus olhos não enxergam a verdade? Tu os feriste, mas não lhes doeu; tu os consumiste, mas não aceitaram receber correção; endureceram seus rostos mais que rocha; não quiseram se converter.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Eu porém disse: Certamente eles são pobres; enlouqueceram, pois não conhecem o caminho do SENHOR, o juízo de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Irei aos grandes, e falarei com eles; porque eles conhecem o caminho do SENHOR, o juízo de seu Deus.Porém eles também quebraram o jugo; também romperam as amarras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Por isso um leão do bosque os ferirá; um lobo do deserto os destruirá; um leopardo vigiará sobre suas cidades; qualquer um que delas sair, será despedaçado; pois suas transgressões se multiplicaram, foram numerosas suas infidelidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Como te perdoaria por isto? Teus filhos me deixaram, e juram pelo que não é Deus. Eu os saciei, porém eles adulteraram, e se aglomeraram em casa de prostitutas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Como cavalos bem alimentados, levantam-se pela manhã; cada um relinchava à mulher de seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Não teria eu de fazer visitação sobre isto?diz o SENHOR. De uma nação como esta não vingaria minha alma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Subi seus muros, e destruí; mas não destruais por completo. Tirai os ramos de seus muros, porque não pertencem ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Pois a casa de Israel e a casa de Judá traíram enganosamente contra mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Negaram ao SENHOR, e disseram: Não é ele; não virá mal sobre nós; não veremos espada, nem fome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'e até os profetas serão como o vento, pois a palavra não está neles; assim acontecerá a eles mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Portanto assim diz o SENHOR Deus dos exércitos: Visto que falastes esta palavra, eis que tornarei minhas palavras em tua boca em fogo, e a este povo será lenha; e o fogo os consumirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Eis que trarei sobre vós uma nação de longe, ó casa de Israel,diz o SENHOR; uma nação forte, nação bastante antiga; uma nação cuja língua não saberás, e o que falarem não entenderás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Sua aljava é como uma sepultura aberta; todos eles são poderosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'E comerão tua colheita e teu pão, que teus filhos e tuas filhas comeriam; comerão tuas ovelhas e tuas vacas, comerão tuas vides e tuas figueiras; e derrubarão por meio da espada tuas cidades fortes em que confias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Porém naqueles dias, diz o SENHOR, não vos acabarei por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'E será que quando disserdes: Por que o SENHOR nosso Deus fez conosco todas estas coisas? Então lhes dirás: Assim como vós me abandonastes e servistes a deuses estrangeiros em vossa terra, assim também servireis a estrangeiros numa terra que não é vossa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Anunciai isto na casa de Jacó, e fazei com que isto se ouça em Judá, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Ouvi agora isto, ó povo tolo e insensato, que têm olhos e não veem, que têm ouvidos e não ouvem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Por acaso não me temereis?diz o SENHOR; Não vos assombrareis perante mim, que pus a areia por limite ao mar por ordenança eterna, a qual não passará? Ainda que se levantarem suas ondas, mas elas não prevalecerão; ainda que bramem, não a passarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Porém este povo tem coração teimoso e rebelde; viraram-se, e se foram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Nem sequer dizem em seu coração: Temamos agora ao SENHOR nosso Deus, que dá chuva temporã e tardia em seu tempo; os tempos estabelecidos da ceifa ele nos guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Vossas perversidades têm desviado estas coisas; e vossos pecados afastaram de vós o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Porque foram achados perversos em meu povo; eles espiavam como quem põe laços; puseram armadilhas para prenderem homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Como uma gaiola cheia de pássaros, assim estão suas casas cheias de engano: assim eles se fizeram grandes e ricos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Eles se engordaram e ficaram lustrosos, e ultrapassaram os limites das obras do mal; não julgam causa nenhuma, nem sequer a causa do órfão; porém fizeram-se prósperos; nem julgam o direito dos necessitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Por acaso eu não os puniria por causa disto? Diz o SENHOR; e de tal nação não se vingará minha alma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Uma coisa espantosa e horrível está sendo feita na terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Os profetas profetizam falsamente, e os sacerdotes exercem liderança por suas próprias mãos; e meu povo assim o quer. Mas o que fareis quando isto chegar ao fim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Fugi, ó filhos de Benjamim, do meio de Jerusalém; e tocai trombeta em Tecoa, e levantai um sinal de fumaça sobre Bete-Haquerém; porque do norte já se vê o desastre e grande destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Destruirei a filha de Sião ainda que seja formosa e delicada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'A ela virão pastores com seus rebanhos; levantarão contra ela tendas ao redor; e cada um apascentará em seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Preparai guerra contra ela; levantai-vos e subamos até o meio-dia! Ai de nós! que vai caindo já o dia, que as sombras da tarde já estão se estendendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Levantai-vos, e subamos de noite, e destruamos seus palácios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Porque assim diz o SENHOR dos exércitos: Cortai árvores, e levantai cercos junto a Jerusalém; esta é a cidade que tem de ser punida; opressão há no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Tal como a fonte jorra suas águas, assim também ela constantemente jorra sua malícia; violência e destruição se ouve nela; continuamente há enfermidade e feridas perante mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Corrige-te, Jerusalém, para que minha alma não se afaste de ti, para que eu não te torne desolada, uma terra não habitada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Assim diz o SENHOR dos exércitos: Sacudirão por completo o restante de Israel tal como a vide; volta tua mão aos cestos como alguém que colhe uvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'A quem falarei e testemunharei, para que ouçam? Eis que que seus ouvidos são incircuncisos, e não podem escutar; eis que a palavra do SENHOR lhes é coisa vergonhosa, não gostam dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Por isso estou cheio dá fúria do SENHOR, e cansado estou de retê -la; eu a derramarei sobre os meninos pelas ruas, e sobre a reunião dos jovens juntamente; porque até o marido com a mulher serão presos, e o velho com o cheio de dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'E suas casas passarão a ser de outros, suas propriedades e juntamente suas mulheres; porque estenderei minha mão contra os moradores da terra, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Porque desde o menor deles até o maior deles, cada um deseja com ganância; e desde o profeta até o sacerdote, todos agem com falsidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'E curam a ferida da filha de meu povo apenas superficialmente, dizendo, Paz, paz; sem que haja paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Eles se envergonham de fazerem abominação? Não, não se envergonham de maneira nenhuma, nem sequer sabem ter vergonha. Por isso cairão entre os que caem; tropeçarão quando eu os visitar, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Assim diz o SENHOR: Ficai parados nos caminhos, e vede, e perguntai pelas veredas antigas, qual é o bom caminho, e andai por ele; então achareis descanso para vossa alma. Mas disseram: Não andaremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Também pus vigilantes sobre vós, que dissessem: Prestai atenção à voz da trombeta. Mas eles disseram: Não prestaremos atenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Portanto ouvi, ó nações, e saiba disto, o multidão que nelas está;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Ouve tu, ó terra: Eis que eu trarei mal sobre este povo: o fruto de seus pensamentos; pois não dão atenção a minhas palavras, e rejeitam a minha lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Afinal, para que vem a mim o incenso de Sabá, e a boa cana aromática de uma terra distante? Vossas ofertas de queima não me são aceitáveis, nem vossos sacrifícios me são agradáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Portanto assim diz o SENHOR: Eis que porei tropeços a este povo, e cairão neles juntamente os pais e os filhos; o vizinho e seu companheiro perecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Assim diz o SENHOR: Eis que vem um povo da terra do norte; e uma grande nação se levantará dos confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Eles trarão arco e lança; são cruéis, que não terão misericórdia; a voz deles rugirá como o mar, e sobre cavalo cavalgarão, como homens dispostos para a guerra contra ti, ó filha de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Nós ouvimos a fama deles, e nossas mãos perderam a força; fomos tomados pela angústia, e dor como de mulher no parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Não saiais ao campo, nem andeis pelo caminho; porque a espada do inimigo e o terror está ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Tu, filha de meu povo, veste-te de saco, e revolve-te em cinza; chora de luto como por um filho único, pranto de amarguras; porque logo virá sobre nós o destruidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Eu te pus por avaliador e por fortaleza entre meu povo, para que reconheças, e examines o caminho deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Todos eles são os mais teimosos rebeldes, que vivem enganando; são duros como cobre e ferro: todos eles são corruptos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'O fole já se queimou, o chumbo já se consumiu pelo fogo; em vão é feita a fundição, pois os maus não são arrancados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Eles são chamados prata rejeitada, porque o SENHOR os rejeitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Palavra que veio do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Põe-te à porta da casa do SENHOR, e clama ali esta palavra, e dize: Ouvi palavra do SENHOR, toda Judá, vós que entrais por estas portas para adorar ao SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Melhorai vossos caminhos e vossos atos, e eu vos farei habitar neste lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Não confieis em palavras falsas, que dizem: Templo do SENHOR! Templo do SENHOR! Este é o templo do SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Mas se verdadeiramente melhorardes vossos caminhos e vossas obras; se verdadeiramente fizerdes justiça entre o homem e seu próximo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'E não oprimirdes ao estrangeiro que peregrina entre vós, ao órfão, e à viúva, nem derramardes sangue inocente neste lugar, nem seguirdes deuses estrangeiros para vosso mal;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Eu vos farei morar neste lugar, na terra que dei a vossos pais desde os tempos antigos para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Eis que vós os confiais em palavras falsas, que não têm proveito algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Por acaso furtareis, matareis, e adulterareis, e jurareis falsamente, e queimareis incenso a Baal, e andareis atrás de deuses estrangeiros, a quem não conheceis,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'E então vireis e vos poreis perante mim nesta casa, que se chama pelo meu nome, e direis: Libertos somos, para fazer todas estas abominações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Por acaso esta casa, que se chama pelo meu nome, é uma caverna de assaltantes perante vossos olhos? Eis que também vi isso, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Porém ide agora a meu lugar, que era em Siló, onde fiz habitar meu nome no princípio; e vede o que lhe fiz pela maldade do meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Portanto agora, visto que vós tendes feito todas estas obras, diz o SENHOR, e vos falei, insistindo em falar, mas não ouvistes, e eu os chamei, mas não respondestes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Farei também a esta casa, que se chama pelo meu nome, em que vós confiais, e a este lugar que dei a vós e a vossos pais, tal como fiz a Siló:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'E eu vos lançarei fora de minha presença, tal como lancei a todos os vossos irmãos, toda a geração de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Por isso não ores tu por este povo, nem levantes por eles clamor nem oração, nem rogues a mim, pois eu não te ouvirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Não vês o que eles costumam fazer nas cidades de Judá e nas ruas de Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Os filhos coletam a lenha, e os pais acendem o fogo, e as mulheres amassam a massa, para fazerem bolos à rainha dos céus e dedicarem ofertas de bebidas a deuses estrangeiros, para me provocarem à ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Por acaso eles me provocam à ira?diz o SENHOR, eles não acabam provocando mais a si mesmos, para vergonha de seus próprios rostos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Por isso assim diz o Senhor DEUS: Eis que que minha ira e meu furor serão derramados sobre este lugar: sobre os homens, sobre os animais, sobre as árvores do campo, e sobre os frutos da terra; e se acenderá, e não se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Acrescentai vossas ofertas de queima sobre vossos sacrifícios, e comei carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Pois não falei a vossos pais nem lhes mandei, no dia em que os tirei da terra do Egito, coisa alguma sobre oferta de queima e sobre e de sacrifício;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Porém isto lhes mandei, dizendo: Escutai minha voz, e eu serei vosso Deus, e vós sereis meu povo; e andai em todo caminho que eu vos mandar, para que o bem vos aconteça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Mas eles não ouviram, nem inclinaram seus ouvidos; ao invés disso, caminharam em seus próprios conselhos, na teimosia de seu coração maligno, e foram para trás, e não para frente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Desde o dia em que vossos pais saíram da terra do Egito até hoje, eu vos enviei a todos os meus servos os profetas, e enviando-os dia após dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Mas eles não me ouviram, nem inclinaram seu ouvidos; ao invés disso, teimaram ainda mais, e fizeram pior que seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Por isso tu lhes dirás todas estas palavras, mas eles não te ouvirão; e tu os chamarás, mas eles não te responderão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Então tu lhes dirás: Esta é a nação que não escutou a voz do SENHOR seu Deus, nem aceitou correção; a verdade pereceu, e foi cortada de suas bocas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Tosquia o teu cabelo, e lança-o fora, e levanta pranto sobre os lugares altos; porque o SENHOR tem rejeitado e abandonado a nação que causou sua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Porque os filhos de Judá fizeram o mal perante meus olhos, diz o SENHOR; puseram suas abominações na casa que se chama pelo meu nome, para contaminá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'E edificaram os altos de Tofete, que ficam no vale do filho de Hinom, para queimarem no fogo seus filhos e suas filhas, o que eu nunca mandei, nem pensei em meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Por isso eis que virão dias, diz o SENHOR, que não se dirá mais Tofete, nem Vale do filho de Hinom, mas sim Vale da Matança; e serão enterrados em Tofete, por não haver lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'E os cadáveres deste povo serão para comida das aves dos céus e dos animais da terra; e ninguém os espantará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'E farei cessar das cidades de Judá e da ruas de Jerusalém a voz de júbilo e voz de alegria, voz de noivo e voz de noiva; porque a terra se tornará desolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Naquele tempo, diz o SENHOR, tirarão os ossos dos reis de Judá, e os ossos de seus príncipes, e os ossos dos sacerdotes, e os ossos dos profetas, e os ossos dos moradores de Jerusalém, para fora de suas sepulturas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'E os estenderão ao sol, à lua, e a todo o exército do céu, a quem amaram, e a quem serviram, e atrás de quem se foram, e a quem buscaram, e a quem se prostraram. Não serão recolhidos nem sepultados: serão por esterco sobre a superfície da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'E a morte será preferida à vida por todos os restantes que restarem desta má geração, que restarem em todos os lugares onde eu os lancei, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Dize-lhes também: Assim diz o SENHOR: Por acaso os que caem não se levantam? Os que se desviam, não voltam ao caminho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Então por que este povo de Jerusalém continuam se desviando permanentemente? Eles se mantêm no engano, não querem voltar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Escutei e ouvi; não falam daquilo que é correto, ninguém há que se arrependa de sua maldade, dizendo: O que é que fiz? Cada um se virou ao seu percurso, tal como cavalo que corre com ímpeto para a batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Até a cegonha no céu conhece seus tempos certos, e a rolinha, o grou e a andorinha dão atenção ao tempo de sua vinda; mas meu povo não conhece o juízo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Como, pois, dizeis: Nós somos sábios, e a lei do SENHOR está conosco? Certamente eis que a falsa pena dos escribas tem se feito em mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Os sábios serão envergonhados, espantados, e presos; eis que rejeitaram a palavra do SENHOR; que sabedoria, então, eles têm?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Por isso darei suas mulheres a outros, e suas propriedades a quem as possuam: pois desde o menor até o maior, cada um se enche de avareza, desde o profeta até o sacerdote, todos agem com falsidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'E curam a ferida da filha de meu povo apenas superficialmente, dizendo: Paz, paz; sem que haja paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Por acaso eles se envergonham de terem feito abominação? Não, eles não se envergonharam; eles nem sequer sabem o que é ter vergonha; por isso cairão entre os que caírem, tropeçarão no tempo em que eu os castigar, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Certamente eu os apanharei,diz o SENHOR. Não haverá uvas na vide, nem figos na figueira, e até a folha cairá; e aquilo que lhes dei passará deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Por que ainda estamos sentados? Ajuntai-vos, e entremos nas cidades fortes; e ali pereçamos: pois o SENHOR nosso Deus tem nos matado, e nos deu a beber bebida de fel, porque pecamos contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Esperávamos paz, mas nada de bom houve; esperávamos tempo de cura, e eis aqui terror.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Desde Dã se ouve o ronco de seus cavalos; toda a terra treme pelo som do relinchar de seus fortes; e eles vêm e devoram a terra e sua abundância, a cidade e seus moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Porque eis que eu envio entre vós serpentes, e cobras venenosas, contra as quais não há encantamento; e elas vos morderão, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Até meu consolo está em tristeza; meu coração desfalece em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Eis a voz do clamor da filha de meu povo, desde uma da terra distante: Por acaso não está o SENHOR em Sião? Não está nela o seu rei? Por que me provocaram à ira com suas imagens de escultura, com coisas estrangeiras inúteis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Passou a ceifa, acabou-se o verão, e nós não fomos salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Quebrantado estou pelo quebrantamento da filha de meu povo; estou de luto, fui tomado pelo assombro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Por acaso não há bálsamo em Gileade, ou não há ali médico? Então por que não houve cura para a filha de meu povo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Ah, se minha cabeça se tornasse em águas, e meus olhos em um manancial de águas! Então eu choraria dia e noite pelos mortos da filha de meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Ah, se houvesse para mim no deserto uma hospedaria para caminhantes! Então eu deixaria o meu povo, e me afastaria deles; pois todos eles são adúlteros, são um bando de traiçoeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Eles estendem suas línguas, como se lhes fossem arcos, para atirarem mentira; e se fortaleceram na terra, mas não por meio da verdade; porque se avançam de mal em mal, e não me conhecem, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Guardai-vos cada um de seu amigo, nem em irmão algum tende confiança: porque todo irmão só faz enganar, e todo amigo anda com falsidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'E cada um engana a seu amigo, e não falam a verdade; ensinaram sua língua a falar mentira, e agem perversamente até se cansarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Tua habitação é em meio ao engano; por meio do engano se negam a me conhecer,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Portanto assim diz o SENHOR dos exércitos: Eis que que eu os fundirei, e os provarei; pois de que outra maneira agiria eu com a filha de meu povo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'A língua deles é uma flecha mortífera, que fala engano; com sua boca fala paz com seu próximo, mas em seu interior lhe arma ciladas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Por acaso eu não os puniria por estas coisas? Diz o SENHOR. Por acaso minha alma não se vingaria de tal nação?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Sobre os montes levantarei choro e pranto, e lamentação as moradas do deserto; porque foram desoladas até não haver quem por ali passe, nem ali se ouve bramido de gado; desde as aves do céu e até os animais da terra fugiram, e foram embora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'E tornarei Jerusalém em amontoados de pedras,para morada de chacais; e tornarei as cidades de Judá em ruínas, de modo que não haja morador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Quem é homem sábio, que entenda isto? E a quem falou a boca do SENHOR, para que possa anunciá-lo? Por que razão a terra pereceu, queimada como deserto, de modo que não há quem nela passe?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'E disse o SENHOR: Foi porque abandonaram minha lei, que dei diante deles, nem deram ouvidos a minha voz, nem caminharam conforme a ela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Ao invés disso, eles seguiram atrás da teimosia de seu coração, e atrás dos Baalins, que seus pais lhes ensinaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Por isso assim diz o SENHOR dos exércitos, Deus de Israel: Eis que a este povo eu lhes darei de comer absinto, e lhes darei de beber água de fel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'E os espalharei entre nações que nem eles, nem seus pais conheceram; e mandarei espada atrás deles, até que eu os acabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Assim diz o SENHOR dos exércitos: Considerai, e chamai carpideiras, que venham; e enviai as mais hábeis, que venham:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'E se apressem, e levantem pranto sobre nós, e desfaçam-se nossos olhos em lágrimas, e nossas pálpebras se destilem em águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Porque uma voz de pranto foi ouvida de Sião: Como fomos destruídos! Nós nos tornamos muito envergonhados, por termos deixado a terra, por nossas moradas terem sido arruinadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Ouvi pois, vós mulheres, a palavra do SENHOR, e vossos ouvidos recebam a palavra de sua boca; e ensinai pranto a vossas filhas, e cada uma lamentação a sua companheira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Porque a morte subiu a nossas janelas, e entrou em nossos palácios; para arrancar os meninos das ruas, os rapazes das praças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Fala: Assim disse o SENHOR: Os cadáveres dos homens cairão como esterco sobre a face do campo, e como espigas de cereal atrás do ceifeiro, que não há quem as recolha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Assim diz o SENHOR: Não se orgulhe o sábio em sua sabedoria, nem o valente se orgulhe em sua valentia, nem o rico se orgulhe em suas riquezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Mas aquele que se orgulhar, orgulhe-se nisto: em me entender e me conhecer, que eu sou o SENHOR, que faço bondade, juízo, e justiça na terra; porque destas coisas eu me agrado,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Eis que vêm dias, diz o SENHOR, em que castigarei todo circunciso e todo incircunciso:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'A Egito, a Judá, a Edom, aos filhos de Amom e de Moabe, e a todos os dos cantos mais distantes, que moram no deserto; pois todas as nações são incircuncisas; mas toda a casa de Israel é incircuncisa no coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Ouvi a palavra que o SENHOR fala sobre vós, ó casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Assim diz o SENHOR: Não aprendais o caminho das nações, nem vos espanteis dos sinais do céu; ainda que as nações as temam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Porque as ordenanças dos povos são inúteis; pois cortam madeira do bosque, obra de mãos de artífice, com machado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Com prata e ouro a enfeitam; com pregos e martelo a firmam, para que não se abale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'São como espantalhos numa plantação, não podem falar; têm que ser levados, pois não podem andar. Não tenhais temor deles; pois nem podem fazer o mal, nem neles há capacidade de fazer o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Pois ninguém há semelhante a ti, SENHOR! Grande és tu, e grande é teu nome em poder!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Quem não temeria a ti, ó Rei das nações? Porque a ti pertence o temor; porque entre todos os sábios das nações, e em todos seus reinos, não há semelhante a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'E juntamente se tornaram irracionais e tolos. Ensino inútil é o ídolo de madeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Trazem prata estendida de Társis, e ouro de Ufaz; para trabalho do artífice, e das mãos do fundidor; eles os vestem de azul celeste e de púrpura; todos eles são obra de trabalhadores habilidosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mas o SENHOR Deus é a verdade; ele é Deus vivo e o Rei eterno; a terra treme pela sua ira, e as nações não podem suportar sua fúria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Assim lhes direis: Os deuses que não fizeram os céus nem a terra perecerão da terra e de debaixo deste céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Mas o SENHOR é aquele que fez a terra com seu poder, que preparou o mundo com sua sabedoria, e estendeu os céus com seu entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Quando ele pronuncia sua voz, logo há ruído de águas no céu, e faz subir vapores dos confins da terra; faz os relâmpagos com a chuva, e faz sair o vento de seus tesouros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Todo homem se tornou irracional e sem conhecimento; envergonha-se todo fundidor de imagem de escultura, pois sua imagem fundida é uma mentira, e nelas não há espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Elas são inúteis, obras de engano; no tempo de sua punição, virão a perecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'A Porção de Jacó não é como eles; porque ele é o Formador de tudo, e Israel é a tribo de sua herança; EU-SOU dos exércitos é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Recolhe tuas mercadorias da terra; tu que habitas em cerco,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Porque assim diz o SENHOR: Eis que desta vez lançarei como que por uma funda aos moradores da terra; e eu os oprimirei, de modo que sejam achados em opressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Ai de mim, por causa do meu quebrantamento! Minha ferida me causa grande dor. E eu havia dito: Isto de fato é uma enfermidade, e terei que suportá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Minha tenda está destruída, e todas as minhas cordas arrebentadas; meus filhos saíram de perto de mim, e nenhum deles há; ninguém há que estenda minha tenda, nem que levante minhas cortinas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Porque os pastores se tornaram irracionais, e não buscaram ao SENHOR; por isso não agiram prudentemente, e todo o seu rebanho se dispersou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Eis que vem uma voz de aviso, e um grande tremor da terra do norte; para tornar em desolação as cidades de Judá, em morada de chacais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Eu sei, SENHOR, que não pertence ao homem o seu caminho, nem ao homem que anda a direção de seus passos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Corrige-me, SENHOR, porém com moderação; não em tua ira, para que não me destruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Derrama tua ira sobre as nações que não te conhecem, e sobre os povos que não invocam o teu nome; pois devoraram a Jacó; eles o devoraram, consumiram e assolaram sua morada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Palavra que veio do SENHOR, a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Ouvi as palavras deste pacto, e falai aos homens de Judá, e aos moradores de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Dize-lhes, pois: Assim diz o SENHOR, Deus de Israel: Maldito o homem que não ouvir as palavras deste pacto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Que mandei a vossos pais no dia que os tirei da terra do Egito, do forno de ferro, dizendo: Ouvi a minha voz, e as fazei conforme a tudo quanto eu vos mando; então vós sereis meu povo, e eu serei vosso Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Para que eu confirme o juramento que fiz a vossos pais, que lhes daria uma terra em que mana leite e mel, tal como hoje.E eu respondi, e disse: Amém, SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'E disse-me o SENHOR: Proclama todas estas palavras nas cidades de Judá e nas ruas de Jerusalém, dizendo: Ouvi as palavras deste pacto, e praticai-as;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Porque insistentemente adverti a vossos pais o dia que eu os tirei da terra do Egito até o dia de hoje, repetidamente advertindo, dizendo: Ouvi minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Porém não ouviram, nem inclinaram seus ouvidos; ao invés disso, seguiram cada um a teimosia de seu coração maligno. Por isso trouxe sobre eles todas as palavras deste pacto, que mandei que cumprissem, mas não cumpriram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'E disse-me o SENHOR: Achou-se conspiração entre os homens de Judá, e entre os moradores de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Voltaram às maldades de seus primeiros pais, que se recusaram a ouvir minhas palavras; ao invés disso, eles seguiram deuses estrangeiros, para lhes servirem; a casa de Israel e a casa de Judá violaram meu pacto, que eu tinha feito com seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Portanto, assim diz o SENHOR: Eis que trarei sobre eles calamidade, da qual não poderão escapar; e clamarão a mim, mas eu não os ouvirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Então as cidades de Judá e os moradores de Jerusalém irão, e clamarão aos deuses a quem queimam incensos; porém de maneira nenhuma poderão os salvar no tempo de sua calamidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Porque teus deuses foram tão numerosos quanto tuas cidades, ó Judá; e tão numerosos quanto tuas ruas, ó Jerusalém, vós pusestes altares da vergonha, altares para queimar incensos a Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Tu, pois, não ores por este povo, nem levantes por eles clamor nem oração; porque eu não ouvirei no dia em que clamarem a mim em meio a calamidade deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Que direito tem minha amada em minha casa, visto que muitos têm feito tão grandes abominações? Podem carnes “santificadas” te livrar, de modo que te alegras com tua maldade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'O SENHOR chamava o teu nome de Oliveira verde, formosa de belos frutos. Porém agora,à voz de grande tumulto, ele acendeu fogo sobre ela, e seus ramos foram quebrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Pois o SENHOR dos exércitos, que te plantou, pronunciou calamidade contra ti, por causa da maldade da casa de Israel e da casa de Judá, que fizeram entre si mesmos, para me provocarem à ira queimando incenso a Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'E o SENHOR me fez saber, e conhecer; então tu me fizeste ver suas ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'E eu estava como cordeiro manso, que levam para degolar, pois não entendia que tramavam planos contra mim, dizendo: Destruamos a árvore com seu fruto, e o cortemos da terra dos viventes, e não haja mais lembrança de seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mas, ó SENHOR dos exércitos, justo juiz, que provas os sentimentos e pensamentos, veja eu tua vingança deles; porque a ti mostrei minha causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Portanto assim diz o SENHOR quanto aos homens de Anatote, que buscam matar tua alma, dizendo: Não profetizes em nome do SENHOR, para que não morras por meio de nossas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Portanto assim diz o SENHOR dos exércitos: Eis que eu os punirei; os rapazes morrerão a espada; seus filhos e suas filhas morrerão de fome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'E não restará sobrevivente deles, pois eu trarei calamidade sobre os homens de Anatote, no ano em que serão punidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Justo és tu, SENHOR, mesmo quando eu discuto contigo; falarei, porém, de juízos contigo. Por que o caminho dos perversos prospera, e todos os que agem enganosamente têm boa vida?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Tu os plantaste, e firmaram raízes; eles progridem, e dão fruto; tu estás perto de suas bocas, porém longe de seus sentimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mas tu, SENHOR, me conheces; tu me vês, e provas o meu coração para contigo. Arranca-os como a ovelhas para o matadouro, e reserva-os para o dia da matança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Até quando lamentará a terra, e a erva de todo o campo ficará seca? Pela maldade dos que nela habitam, os animais e as aves perecem; porque dizem: Ele não verá ele nosso fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Se ao correres com os que estão a pé, eles te cansam, como competirás com os cavalos? E se somente em terra de paz te sentes seguro, como agirás tu nos matagais junto ao Jordão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Porque até teus irmãos e a casa de teu pai passaram a agir traiçoeiramente contra ti, até eles gritaram atrás de ti. Não creias neles, quando te falarem coisas boas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Deixei minha casa, abandonei minha herança, entreguei a amada de minha alma nas mãos de seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Minha herança se tornou para mim como um leão na floresta: ela levantou sua voz contra mim; por isso que eu a odeio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Não é minha herança para mim uma ave de rapina de muitas cores? Não estão contra ela aves de rapina ao redor? Vinde, ajuntai-vos, todas os animais do campo, vinde para devorá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Muitos pastores destruíram minha vinha, pisaram meu campo; tornaram meu campo desejado em um deserto devastado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Tornaram-no em desolação, e lamenta a mim, desolado; toda a terra está desolada, porque ninguém há que pense nisso no coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Sobre todos os lugares altos do deserto vieram destruidores; porque a espada do SENHOR devora desde um extremo da terra até o outro extremo; não haverá paz para nenhuma carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Semearam trigo, e ceifarão espinhos; cansaram-se, mas não tiveram proveito algum. Envergonhai-vos de vossos frutos, por causa da ardente ira do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Assim diz o SENHOR quanto a todos os meus maus vizinhos, que tocam a minha herança, a qual dei por herança a meu povo Israel: Eis que eu os arrancarei de sua terra, e arrancarei a casa de Judá do meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'E será que, depois de os arrancar, voltarei, terei compaixão deles, e os farei voltar cada um à sua herança, e cada um à sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'E será que, se cuidadosamente aprenderem os caminhos de meu povo, para jurar em meu nome, dizendo: Vive o SENHOR, assim como ensinaram a meu povo a jurar por Baal; eles serão edificados em meio do meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Porém, se não quiserem ouvir, arrancarei à tal nação por completo, e a destruirei, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Assim me disse o SENHOR: Vai, e compra para ti um cinto de linho, e o põe sobre teus lombos; e não o metas em água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'E comprei o cinto conforme à palavra do SENHOR, e o pus sobre meus lombos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'E veio a mim a palavra do SENHOR pela segunda vez, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Toma o cinto que compraste, que está sobre teus lombos, levanta-te, e vai ao Eufrates, e ali o escondes na fenda de uma rocha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Então eu fui, e o escondi em Eufrates, como o SENHOR tinha me mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'E sucedeu, que ao fim de muitos dias, o SENHOR me disse: Levanta-te, vai ao Eufrates, e toma dali o cinto que ali te mandei esconder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Então fui ao Eufrates, cavei, e tomei o cinto do lugar de onde o havia escondido; e eis que o cinto tinha se apodrecido; para nada mais prestava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Então veio a mim palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Assim diz o SENHOR: assim farei apodrecer a arrogância de Judá, e a grande arrogância de Jerusalém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Este povo maligno, que recusa ouvir minhas palavras, que caminha conforme a teimosia de seu coração, e segue atrás de deuses estrangeiros para lhes servir, e para se encurvar a eles; e tal será como este cinto, que para nenhuma coisa presta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Porque assim como o cinto está junto aos lombos do homem, assim fiz juntar a mim toda a casa de Israel e toda a casa de Judá,diz o SENHOR, para que me fossem por povo e por nome, e por louvor e por glória; porém não quiseram escutar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Por isso dize-lhes esta palavra: Assim diz o SENHOR, Deus de Israel: Todo odre se encherá de vinho. E te dirão: Por acaso nós não sabemos muito bem que todo odre se encherá de vinho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Então dize-lhes: Assim diz o SENHOR: Eis que eu encherei de embriaguez todos os moradores desta terra, e aos reis que se sentam sobre o trono de Davi, e aos sacerdotes e aos profetas, e a todos os moradores de Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'E eu os despedaçarei um contra o outro, e juntamente os pais com os filhos, diz o SENHOR; não perdoarei, nem pouparei, nem terei compaixão; nada me impedirá de destruí-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Escutai e ouvi: não sejais arrogantes, pois o SENHOR falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dai glória ao SENHOR vosso Deus, antes que ele faça escurecer, e antes que vossos pés tropecem nos montes no meio da escuridão, e espereis luz, e ele a torne em sombra de morte e cause trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Mas se não ouvirdes isto, minha alma chorará em segredo por causa de vossa arrogância; e chorando amargamente, meus olhos se desfarão em lágrimas, porque o rebanho do SENHOR foi levado cativo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Dize ao rei e à rainha-mãe: Humilhai-vos, sentai-vos rebaixados; porque a coroa de vossa glória já caiu de vossas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'As cidades do Negueve estão fechadas, e ninguém há que as abra; toda Judá foi levada, ela foi levada cativa por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Levantai vossos olhos, e vede os que vêm do norte; onde está o rebanho que te foi dado, a ovelhas de tua glória?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'O que dirás quando ele te punir? Pois tu os ensinaste a serem príncipes e cabeça sobre ti. Por acaso as dores não te tomarão, como uma mulher em parto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'E quando disseres em teu coração: Por que estas coisas me aconteceram? A resposta é: Foi pela grandeza de tua maldade que tuas roupas foram descobertas, e foste violentada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Pode o negro mudar a sua pele, ou o leopardo suas manchas? Assim também podeis vós fazer o bem, sendo tão acostumados a praticar o mal?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Portanto eu os espalharei como os restos de palha que passam com o vento do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Isto é o que terás, a porção de tuas medidas que te reservo, diz o SENHOR; pois tu te esqueceste de mim, e confiaste na mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Asim também eu descobrirei também tuas roupas até sobre teu rosto, e tua desonra ficará à mostra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Eu vi as tuas abominações: teus adultérios, teus relinchos, a maldade de tua prostituição sobre os morros no campo. Ai de ti, Jerusalém! Até quando continuarás sem te purificares?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Palavra do SENHOR que veio a Jeremias, quanto à seca:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Judá está de luto, e suas portas se enfraqueceram; lamentam até o chão, e o clamor de Jerusalém está a subir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'E os mais ilustres deles enviaram seus inferiores à água; eles vêm aos tanques, e não acham água; voltam com seus vasos vazios; eles se envergonham, se sentem humilhados, e cobrem suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Pois o chão se rachou, por não haver chuva na terra; envergonhados estão os trabalhadores, e cobrem suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'E até as cervas nos campos geram filhotes, e os abandonam, pois não há erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'E os asnos monteses se põem nos lugares altos, aspiram o vento como os chacais; seus olhos se enfraquecem, pois não há erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ainda nossas maldades dão testemunho contra nós, SENHOR, age por amor de teu nome; pois nossas rebeldias se multiplicaram, contra ti pecamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Ó tu, esperança de Israel, Redentor seu em tempo de angústia! Por que serias tu como um peregrino na terra, e como um caminhante que apenas se recolhe para passar a noite?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Por que serias tu como um homem atônito, e como um guerreiro que não pode salvar? Tu porém estás no meio de nós nós, ó SENHOR, e nós somos chamados pelo teu nome! Não nos desampares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Assim diz o SENHOR quanto a este povo: Já que amaram tanto se moverem, e detiveram seus pés, por isso o SENHOR não se agrada deles; agora se lembrará da maldade deles, e punirá por causa de seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Disse-me mais o SENHOR: Não rogues pelo bem deste povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Quando jejuam, não ouvirei seu clamor, e quando oferecem sacrifícios de queima e ofertas de cereais, não os aceitarei; em vez disso, eu os consumirei por meio da espada, da fome, e da pestilência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Então eu disse: Ah, Senhor DEUS! Eis que os profetas lhes dizem: Não vereis espada, nem tereis fome; eu, porém, vos darei uma paz verdadeira neste lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Então o SENHOR me disse: Os profetas profetizam falsidade em meu nome; eu não os enviei, nem lhes mandei, nem lhes falei; eles vos profetizam visão falsa, adivinhação, inutilidade, e engano de seus próprios corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Portanto assim diz o SENHOR quanto aos profetas que profetizam em meu nome, sem que eu tenha lhes enviado, que dizem “não haverá nem espada nem fome nesta terra”: Com espada e com fome tais profetas serão consumidos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'E o povo a quem eles profetizam será lançado fora nas ruas de Jerusalém, por causa da fome e da espada; e não haverá quem os enterre, eles, suas mulheres, seus filhos, e suas filhas; e sobre eles derramarei sua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Portanto tu lhes dirás esta palavra: Corram meus olhos em lágrimas noite e dia, e não cessem; porque a virgem filha de meu povo está quebrada de grande quebrantamento, de praga muito dolorosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Se saio ao campo, eis os mortos a espada; e se entro na cidade, eis os doentes de fome; e até os profetas e os sacerdotes andam rodeando na terra, e nada sabem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Rejeitaste a Judá por completo? Tua alma detesta a Sião? Por que nos feriste de modo que não haja cura para nós? Esperávamos paz, mas nada há de bom; esperávamos tempo de cura, e eis o terror!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Ó SENHOR, reconhecemos nossa perversidade, a maldade de nossos pais; pois pecamos contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Não nos rejeites por amor de teu nome, nem desonres ao trono de tua glória; lembra-te, não invalides o teu pacto conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Por acaso há entre as futilidades das nações alguém que faz chover? Ou podem os céus dar chuvas? Não és somente tu, SENHOR, nosso Deus? Por isso em ti esperamos, pois tu fazes todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Disse-me, porém, o SENHOR: Ainda que Moisés e Samuel se pusessem diante de mim, minha boa vontade não seria com este povo. Lança-os de diante de mim, e saiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'E será que, quando te perguntarem: Para onde sairemos? Tu lhes dirás: Assim diz o SENHOR: Os que são para a morte, para a morte; e os que são para a espada, para a espada; e os que são para a fome, para a fome; e os que são para o cativeiro, para o cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Pois eu lhes darei quatro tipos de castigos, diz o SENHOR: espada para matar, cães para despedaçar, e aves do céu e animais da terra para devorar e para destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'E farei deles que sejam motivo de horror a todos os reinos da terra, por causa de Manassés filho de Ezequias rei de Judá, pelo que ele fez em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Pois quem terá compaixão de ti, ó Jerusalém? Ou quem se entristecerá por tua causa? Ou quem se desviaria para perguntar se estás bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tu me deixaste, diz o SENHOR, voltaste para trás de mim; por isso estenderei minha mão contra ti, e te destruirei; já estou cansado de sentir pena.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'E eu os padejarei com pá até as portas da terra, e os deixarei sem filhos; destruirei meu povo, pois não voltaram atrás de seus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Suas viúvas se multiplicaram mais que a areia dos mares; eu lhes trouxe sobre a mãe dos rapazes um destruidor ao meio dia; sobre ela eu fiz cair de angústia e terrores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Enfraqueceu-se a que teve sete filhos; a sua alma perdeu o fôlego; seu sol se lhe pôs, sendo ainda de dia; envergonhou-se, e ficou humilhada; e os que dela restarem, eu os entregarei a espada diante de seus inimigos,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Ai de mim, minha mãe, que me geraste homem de brigas e homem de confrontos a toda a terra! Nunca lhes emprestei a juros, nem deles emprestado; e mesmo assim todos eles me amaldiçoam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Disse o SENHOR: Certamente eu te livrarei para o bem; certamente intervirei por ti no tempo do mal, e no tempo de angústia, por causa do inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Pode, por acaso o ferro comum quebrar o ferro do norte, ou o bronze?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Tuas riquezas e teus tesouros darei ao despojo por preço nenhum, por todos os teus pecados, e em todos os teus limites;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'E te levarei com teus inimigos a uma terra que não conheces; porque fogo se acendeu em minha ira, que arderá sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Tu sabes, ó SENHOR; lembra-te de mim, visita-me, e vinga-me de meus perseguidores. Na lentidão de tua ira não me elimines; tu sabes que é por causa de ti que sofro insultos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Achando-se tuas palavras, logo eu as comi; e tua palavra me foi por prazer e por alegria a meu coração; pois me chamo pelo teu nome, ó SENHOR Deus dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Não me sentei em companhia de zombadores, nem com eles me alegrei; por causa de tua mão, eu me sentei sozinho, pois me encheste de indignação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Por que minha dor é contínua, e minha ferida intratável, que não permite cura? Por acaso serias tu para mim como uma ilusão, como águas que não se pode confiar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Portanto assim diz o SENHOR: Se te converteres, eu te restaurarei, e diante de mim estarás; e se tirares o que é de precioso ao invés do vil, serás como minha boca. Convertam-se eles a ti, e tu não te convertas a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Pois eu te porei para este povo para seres como um forte muro de bronze; e lutarão contra ti, mas não te vencerão; pois eu estou contigo para te guardar e te livrar,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'E eu te livrarei da mão dos maus, e te resgatarei da mão dos terríveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Não tomes para ti mulher, nem tenhas filhos nem filhas neste lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Porque assim diz o SENHOR quanto aos filhos e às filhas que nascerem neste lugar, e às suas mães que os tiverem e aos pais que os gerarem nesta terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'De dolorosas enfermidades morrerão; não serão pranteados nem sepultados; servirão de esterco sobre a face da terra; e com espada e com fome serão consumidos, e seus cadáveres servirão de alimento para as aves do céu e para os animais da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Porque assim diz o SENHOR: Não entres em casa de luto, nem vás para lamentar, nem mostre compaixão deles; pois deste povo eu tirei minha paz, bondade e misericórdia, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'E nesta terra morrerão grandes e pequenos; não serão sepultados, nem pranteados, nem por eles se cortarão, ou rasparão seus cabelos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Nem repartirão pão aos que estiverem de luto, para consolá-los de seus mortos; nem lhes darão a beber copo de consolações pelo pai ou pela mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Nem também entres em casa de banquete, para te sentares com eles para comer e beber;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Eis que farei cessar neste lugar, diante de vossos olhos e em vossos dias, toda voz de prazer e toda voz de alegria, toda voz de noivo e toda voz de noiva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'E será que quando anunciares a este povo todas estas palavras, eles te dirão: Por que o SENHOR falou sobre nós este mal tão grande? E que maldade é a nossa, ou que pecado é o nosso, que cometemos contra o SENHOR nosso Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Então lhes dirás: Porque vossos pais me deixaram, diz o SENHOR, e seguiram deuses estrangeiros, os serviram e a eles se prostraram; e me abandonaram, e não guardaram minha Lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'E vós fizestes pior que vossos pais; pois eis que vós caminhais cada um atrás da teimosia de seu coração maligno, sem me obedecerem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Por isso eu vos lançarei fora desta terra, para uma terra que nem vós nem vossos pais conhecestes; e lá servireis a deuses estrangeiros de dia e de noite, porque não terei misericórdia de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Porém eis que vêm dias, diz o SENHOR, que não se dirá mais: Vive o SENHOR, que trouxe os filhos de Israel da terra do Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Mas sim: Vive o SENHOR, que trouxe os filhos de Israel da terra do norte, e de todas as terras aonde ele tinha os lançado; pois eu os farei voltar à sua terra, a qual dei a seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Eis que enviarei muitos pescadores, diz o SENHOR, que os pescarão; e depois enviarei muitos caçadores, que os caçarão de todo monte, e de todo morro, e até das fendas das rochas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Pois meus olhos estão sobre todos seus caminhos; eles não estão escondidos de mim, nem a maldade deles está oculta de diante de meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Mas primeiro pagarei em dobro a iniquidade e o pecado deles, pois contaminaram minha terra com os cadáveres de suas coisas detestáveis, e encheram minha herança de suas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Ó SENHOR, fortaleza minha, e força minha, e meu refúgio no tempo da aflição; a ti virão nações desde os confins da terra, e dirão: Certamente o que nossos pais possuíam era mentira e inutilidade; não havia nessas coisas proveito algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Pode, por acaso, o homem fazer deuses para si? Eles, porém, não são deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Portanto eis que desta vez lhes farei conhecer, lhes farei conhecer minha mão e meu poder, e saberão que EU-SOU é o meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'O pecado de Judá está escrito com cinzel de ferro, com ponta de diamante; está esculpido na tábua de seu coração, e nas pontas de vossos altares;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Enquanto seus filhos se lembram de seus altares e de seus bosques, junto às árvores verdes, sobre os altos morros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Ó minha montanha no campo! Tua riqueza e todos os teus tesouros darei como despojo por causa do pecado de teus altos em todos teus limites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Assim por causa de ti deixarás de ter a herança que eu te dei, e te farei servir a teus inimigos em uma terra que não conheces; porque acendestes fogo em minha ira, que arderá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Assim diz o SENHOR: Maldito o homem que confia no homem, e põe sua confiança na força humana,) e seu coração se afasta do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Pois será como um arbusto no deserto, e não sente quando vier o bem; ao invés disso morará nas securas no deserto, em terra salgada e inabitável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Bendito o homem que confia no SENHOR, cuja confiança é o SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Porque ele será como a árvore plantada junto a águas, que estende suas raízes junto à corrente; não tem preocupação quando vier o calor, e sua folha permanece verde; e no ano de seca não se cansa, nem deixa de dar fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'O coração é mais enganoso que todas as coisas, e perverso; quem pode conhecê-lo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Eu, o SENHOR, que examino o coração, e provo os sentimentos, para dar a cada um conforme seus caminhos, conforme o fruto de suas ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Como a perdiz que choca os ovos que não pôs, assim é o que junta riquezas, mas não com justiça; no meio de seus dias ele deixará de tê-las, e em seu fim ele será tolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Trono de glória, elevado desde o princípio, é o lugar de nosso santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Ó SENHOR, esperança de Israel! Todos os que te abandonam serão envergonhados; e os que de mim se afastam, serão escritos no chão; pois abandonaram ao SENHOR, a fonte de águas vivas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Sara-me, ó SENHOR, e serei sarado; salva-me, e serei salvo; pois tu és meu louvor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Eis que eles me dizem: Onde está a palavra do SENHOR? Cumpra-se ela agora!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Mas eu não me apressei para deixar de ser ser pastor após ti, nem desejei o dia de calamidade, tu o sabes. O que saiu de minha boca foi em tua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Não sejas tu assombro para mim; tu és minha esperança no dia mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Envergonhem-se os que me perseguem, e eu não me envergonhe; assombre-se eles, e eu não me assombre: traze sobre eles o dia mal, e destrói-os com destruição dobrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Assim me disse o SENHOR: Vai, e põe-te à porta dos filhos do povo, pela qual entram e saem os reis de Judá, e a todas as portas de Jerusalém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'E dize-lhes: Ouvi a palavra do SENHOR, vós reis de Judá, e todo Judá, e todos os moradores de Jerusalém que entrais por esta portas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Assim diz o SENHOR: Guardai-vos por vossas vidas, e não tragais carga no dia do sábado, para fazê-las entrar pelas portas de Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Nem tireis carga de vossas casas no dia do sábado, nem façais obra alguma; ao invés disso, santificai o dia do sábado, assim como mandei a vossos pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Porém eles não deram ouvidos, nem escutaram; ao invés disso, tornaram-se teimosos,) para não ouvirem, nem receberem correção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Será, pois, se vós me ouvirdes cuidadosamente, diz o SENHOR, não fazendo entrar carga pelas portas desta cidade no dia do sábado, e santificardes o dia do sábado, não fazendo nele nenhuma obra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Então entrarão pelas portas desta cidade reis e os príncipes que se sentem sobre o trono de Davi, montados em carros e em cavalos; eles e seus príncipes, e os homens de Judá, e os moradores de Jerusalém; e esta cidade será habitada para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'E pessoas virão das cidades de Judá, dos arredores de Jerusalém, da terra de Benjamim, dos campos, do monte, e do Negueve, trazendo ofertas de queima, sacrifícios, ofertas de alimento e incensos, e trazendo sacrifícios de louvor à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Porém se não me ouvirdes para santificardes o dia do sábado, e para não trazerdes carga nem fazê-la entrar pelas portas de Jerusalém no dia de sábado, eu acenderei fogo em suas portas, que consumirá os palácios de Jerusalém, e não se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Palavra que veio do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Levanta-te, e desce à casa do oleiro; e ali te farei ouvir minhas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Então desci à casa do oleiro, e eis que ele estava fazendo uma obra sobre a roda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'E o vaso de barro que ele estava fazendo se quebrou na mão do oleiro; então ele voltou a fazer dele outro vaso, conforme o que ao oleiro pareceu melhor fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Então veio a mim palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Por acaso não poderei eu fazer de vós como este oleiro, ó casa de Israel?diz o SENHOR. Eis que tal como o barro na mão do oleiro, assim sois vós em minha mão, ó casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Caso em algum momento eu falar contra uma nação e contra um reino, para arrancar, dissipar, e destruir,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Se tal nação se converter de sua maldade, contra a qual falei, eu mudarei de ideia quanto ao mal que tinha pensado lhe fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Caso em algum momento eu falar de uma nação e de um reino, para edificar e para plantar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Se ela fizer o mal diante dos meus olhos, não obedecendo à minha voz, eu mudarei de ideia quanto ao bem que tinha dito lhe fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Então agora, fala, pois, a todo homem de Judá, e aos moradores de Jerusalém, dizendo: Assim diz o SENHOR: Eis que eu determino o mal contra vós, e faço planos contra vós; convertei-vos agora, cada um de seu mau caminho, e melhorai vossos caminhos e vossas ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Porém dizem: Não há esperança; porque seguiremos nossas próprias intenções, e faremos cada um o pensamento de seu maligno coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Portanto assim diz o SENHOR: Perguntai agora entre as nações, quem tenha ouvido tal coisa. Grande horror fez a virgem de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Por acaso pode faltar neve nas rochas das montanhas do Líbano? Ou pode deixar de haver as águas frias que correm de terras distantes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Porém meu povo se esqueceu de mim, queimando incenso à inutilidade, e fazem- lhes tropeçar em seus caminhos, nas veredas antigas, para que andassem por veredas de caminho não aplanado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Para tornar sua terra em desolação, e em assovios perpétuos; todo aquele que passar por ela se espantará e balançará sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Tal como vento oriental, eu os espalharei diante do inimigo; eu lhes mostrarei as costas, e não o rosto, no dia de sua perdição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Então disseram: Vinde, e façamos planos contra Jeremias; porque a Lei não perecerá do sacerdote, nem o conselho do sábio, nem a palavra do profeta. Vinde e o firamos com a língua, e não prestemos atenção a nenhuma de suas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Ó SENHOR, presta atenção a mim, e ouve a voz dos que brigam comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Por acaso se pagará ao bem com o mal? Pois já cavaram uma cova para a minha alma! Lembra-te que me pus diante de ti para falar pelo bem deles, para desviar deles a tua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Portanto entrega os filhos deles à fome, e derrama-os pelo poder da espada; e restem suas mulheres sem filhos e viúvas; e seus maridos sejam postos a morte, e seus rapazes sejam feridos à espada na guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Ouçam-se gritos de suas casas, quando tu trouxeres tropas contra eles de repente; pois cavaram uma cova para me prender, e armaram laços para meus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Mas tu, SENHOR, conheces todo o plano deles contra mim para me matar; não perdoes sua maldade, nem apagues o pecado deles de diante de tua presença, e tropecem diante de ti; faze assim com eles no tempo de tua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Assim diz o SENHOR: Vai, e compra uma jarra de barro de oleiro, e toma contigo dos anciãos do povo e dos anciãos dos sacerdotes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'E sai ao vale do filho de Hinom, que fica à entrada da porta oriental; e ali declara as palavras que eu te disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'E dize: Ouvi a palavra do SENHOR, ó reis de Judá, e moradores de Jerusalém. Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que trarei calamidade sobre este lugar, de tal modo que quem o ouvir, lhe retinirão os ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Pois me abandonaram, e profanaram este lugar, e queimaram nele incenso a outros deuses, que nunca tinham conhecido, nem eles, nem seus pais, nem os reis de Judá; e encheram este lugar com sangue de inocentes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'E edificaram altos a Baal, para queimarem a fogo seus filhos como ofertas de queima para Baal; coisa esta que nunca lhes mandei, nem falei, nem jamais pensei em meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Por isso eis vêm dias, diz o SENHOR, que este lugar não se chamará mais Tofete, nem Vale do filho de Hinom, mas sim Vale da Matança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'E tornarei vazio o conselho de Judá e de Jerusalém neste lugar; e os farei cair à espada diante de seus inimigos, e nas mãos dos que buscam tirar suas vidas; e darei seus cadáveres por comida às aves do céu e aos animais da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'E farei desta cidade espanto e assovio; todo aquele que passar por ela se espantará e assoviará por causa de todas as suas pragas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'E farei com que comam a carne de seus filhos e a carne de suas filhas; e cada um comerá a carne de seu próximo durante o cerco e a opressão com que os seus inimigos e os que buscam tirar suas vidas lhes oprimirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Então quebrarás a jarra perante os olhos dos homens que tiverem ido contigo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'E lhes dirás: Assim diz o SENHOR dos exércitos: Assim quebrarei a este povo e a esta cidade, como quem quebra um vaso de oleiro, que não pode mais ser restaurado; e em Tofete serão enterrados, pois não haverá outro lugar para enterrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Assim farei a este lugar, diz o SENHOR, e a seus moradores, para fazer desta cidade como a Tofete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'E as casas de Jerusalém, e as casas dos reis de Judá, serão imundas tal como o lugar de Tofete; todas as casas sobre cujos telhados foi queimado incenso a todo o exército do céu, e derramaram ofertas de bebida a deuses estrangeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Então voltou Jeremias de Tofete, onde o SENHOR tinha lhe mandado profetizar, e se pôs em pé no pátio da casa do SENHOR, e disse a todo o povo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que eu trago sobre esta cidade e sobre todas as suas vilas todo o mal que falei contra ela; pois endureceram seu pescoço para não ouvirem minhas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'E Pasur, filho de Imer, o sacerdote, que era o principal supervisor na casa do SENHOR, ouviu a Jeremias enquanto profetizava estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Então Pasur feriu ao profeta Jeremias, e o pôs no tronco que ficava à porta superior de Benjamim, a qual fica na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'E foi no dia seguinte que Pasur tirou a Jeremias do tronco. Disse-lhe então Jeremias: O SENHOR não chama teu nome Pasur, mas sim “Terror por todos os lados”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Porque assim diz o SENHOR: Eis que eu farei de ti um terror a ti mesmo, e a todos os teus amigos; e cairão pelo espada de seus inimigos, e teus olhos o verão; e a todo Judá entregarei na mão do rei da Babilônia, e os levará cativos a Babilônia, e os ferirá à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Entregarei também toda a riqueza desta cidade, e todo seu trabalho, e todas suas coisas preciosas; e entregarei todos os tesouros dos reis de Judá nas mãos de seus inimigos, e os saquearão, e os tomarão, e os levarão a Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'E tu, Pasur, e todos os moradores de tua casa ireis ao cativeiro, e entrarás na Babilônia, e ali morrerás; e ali serás sepultado, tu, e todos os teus amigos, aos quais profetizaste falsamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Persuadiste-me, ó SENHOR, e eu fiquei persuadido; mais forte foste que eu, e prevaleceste; sirvo de escárnio o dia todo; cada deles zomba de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Pois desde que falo, grito; eu clamo violência e destruição; pois a palavra do SENHOR tem me servido de insulto e zombaria o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Então eu disse: Não me lembrarei dele, nem falarei mais em seu nome; porém ela foi em meu coração como um fogo ardente contido em meus ossos; resisti até me cansar, mas não pude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Porque ouço a murmuração de muitos, temor por todos os lados: Anunciai, e anunciaremos. Todos os meus amigos observam meu manquejar, dizendo: Talvez se enganará; então prevaleceremos contra ele, e nos vingaremos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mas o SENHOR está comigo como temível guerreiro; por isso meus perseguidores tropeçarão, e não prevalecerão; eles serão muito envergonhados, por não terem agido prudentemente; terão humilhação perpétua, que jamais será esquecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Tu, SENHOR dos exércitos, que examinas o justo, que vês os sentimentos e pensamentos, faz-me ver a tua vingança sobre eles; pois a ti revelei a minha causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Cantai ao SENHOR, louvai ao SENHOR; pois ele livra a alma do necessitado da mão dos malfeitores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Maldito seja o dia em que nasci! O dia em que minha mãe me teve não seja bendito!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Maldito seja o homem que deu as novas a meu pai, dizendo, Um filho macho te nasceu, trazendo-lhe assim muita alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'E seja tal homem como as cidades que o SENHOR assolou sem se arrepender; e ouça gritos de manhã, e clamores ao meio dia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Por ele não ter me matado no ventre, de modo que minha mãe teria sido minha sepultura, e o ventre uma gravidez perpétua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Para que saí do ventre? Para ver trabalho e dor, e meus dias serem gastos com vergonha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Palavra que veio do SENHOR a Jeremias, quando o rei Zedequias lhe enviou a Pasur filho de Malquias, e a Sofonias, sacerdote, filho de Maaseias, para que lhe dissessem:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Pergunta agora por nós ao SENHOR; pois Nabucodonosor, rei da Babilônia, está fazendo guerra contra nós; talvez o SENHOR faça conosco segundo todas as suas maravilhas, e o mande embora de sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'E Jeremias lhes disse: Direis assim a Zedequias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Assim diz o SENHOR Deus de Israel: Eis que eu virarei para trás as armas de guerra que estão em vossas mãos, com as quais lutais contra o rei da Babilônia e os Caldeus que vos têm cercado fora da muralha; e eu os juntarei no meio desta cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'E eu mesmo lutarei contra vós com mão estendida e com braço forte; e com ira, indignação, e grande furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'E ferirei aos moradores desta cidade; tanto aos homens quanto aos animais; morrerão de grande pestilência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'E depois, assim diz o SENHOR, entregarei a Zedequias rei de Judá, e a seus servos, e ao povo, e aos que restarem na cidade da pestilência, da espada, e da fome, nas mãos de Nabucodonosor rei de Babilônia, nas mãos de seus inimigos, e na mão dos que buscam tirar suas vidas. Ele os matará ao fio de espada; não lhes poupará, nem terá deles compaixão, nem misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'E a este povo dirás: Assim diz o SENHOR: Eis que ponho diante de vós caminho de vida e caminho de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Aquele que permanecer nesta cidade, morrerá a espada, ou pela fome, ou pela pestilência; mas o que sair e se render aos Caldeus, que têm vos cercado, viverá, e terá sua vida como despojo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Porque pus meu rosto contra esta cidade para o mal, e não para o bem, diz o SENHOR; nas mãos do rei de Babilônia será entregue, e ele a queimará a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'E à casa do rei de Judá dirás: Ouvi palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Casa de Davi, assim diz o SENHOR: Julgai de manhã com justiça, e livrai a vítima de roubo da mão do opressor; para que minha ira não saia como fogo, e incendeie de modo que não haja quem apague, por causa da maldade de vossas ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Eis que eu sou contra ti, ó moradora do vale, da rocha do planalto, diz o SENHOR; contra vós que dizeis: Quem descerá contra nós? E quem entrará em nossas moradas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Eu vos punirei conforme o fruto de vossas ações, diz o SENHOR, e acenderei fogo em seu bosque, que consumirá tudo o que estiver ao redor dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Assim diz o SENHOR: Desce à casa do rei de Judá, e fala ali esta palavra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'E dize: Ouve a palavra do SENHOR, ó rei de Judá, que te sentas sobre o trono de Davi; tu, teus servos, e teu povo, que entrais por estas portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Assim diz o SENHOR: Fazei juízo e justiça, e livrai a vítima de roubo da mão do opressor, e não oprimais, nem façais violência contra o estrangeiro, o órfão, ou à viúva, nem derrameis sangue inocente neste lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Porque se verdadeiramente cumprirdes esta palavra, os reis que se sentam em lugar de Davi sobre seu trono entrarão montados sobre carruagens e sobre cavalos pelas portas desta casa; eles, e seus servos, e seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Porém se não obedecerdes estas palavras, por mim mesmo tenho jurado, diz o SENHOR, que esta casa se tornará deserta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Porque assim diz o SENHOR quanto à casa do rei de Judá: Tu és para mim como Gileade, e o topo do Líbano; porém certamente te tornarei em deserto, e cidades desabitadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Pois prepararei contra ti destruidores, cada um com suas armas; e cortarão teus mais valiosos cedros, e os lançarão no fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'E muitas nações passarão junto a esta cidade; e cada um dirá a seu companheiro: Por que o SENHOR fez isto com esta grande cidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'E responderão: Porque deixaram o pacto do SENHOR seu Deus, e adoraram a deuses estrangeiros, e os serviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Não choreis pelo morto, nem dele vos lastimeis; mas chorai mesmo por aquele que vai embora; porque nunca mais voltará, nem verá a terra onde nasceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Porque assim diz o SENHOR quanto a Salum, filho de Josias, rei de Judá, que reinava em lugar de Josias seu pai, que saiu deste lugar: Nunca mais voltará;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Em vez disso, morrerá no lugar aonde o levaram cativo, e nunca mais verá esta terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Ai daquele que edifica sua casa com injustiça, e seus cômodos sem fazer o que é correto, que usa do serviço de seu próximo de graça, sem lhe dar o pagamento de seu trabalho!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Que diz: Edificarei para mim uma casa ampla, com cômodos arejados; e lhe abre janelas, e a cobre de cedro, e a pinta de vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Por acaso é acumulando cedro que serás rei? Por acaso teu pai não comeu e bebeu, e fez juízo e justiça, e então teve o bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Ele julgou a causa do aflito e do necessitado, e então esteve bem. Por acaso conhecer a mim não é isto?diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Mas teus olhos e teu coração não são para outra coisa, a não ser para tua ganância, para derramar sangue inocente, e para praticar opressão e violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Portanto assim diz o SENHOR quanto a Jeoaquim, filho de Josias, rei de Judá: Não lamentarão por ele, dizendo: Ai meu irmão!, ou Ai minha irmã!, Nem lamentarão por ele, dizendo: Ai senhor! Ai sua majestade!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Com sepultamento de asno será sepultado; arrastando e lançando -o longe, fora das portas de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Sobe ao Líbano, e clama, levanta tua voz em Basã, e grita desde Abarim; porque todos teus amantes estão destruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Falei contigo em tuas prosperidades; mas disseste: Não ouvirei. Este tem sido o teu caminho desde tua juventude, que nunca deste ouvidos à minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'O vento apascentará a todos os teus pastores, e teus amantes irão ao cativeiro; então certamente te envergonharás e te humilharás por causa de toda a tua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Tu, que habitas no Líbano, que fazes teu ninho nos cedros: como gemerás quando te vierem as dores, os sofrimentos como de mulher em parto!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Vivo eu,diz o SENHOR, que se Conias, filho de Jeoaquim rei de Judá, fosse um anel em minha mão direita, até dali eu te arrancaria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'E eu te entregarei na mão dos que buscam a tua vida, e na mão daqueles a quem tu temes: na mão de Nabucodonosor rei da Babilônia, e nas mão dos Caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'E lançarei a ti e a tua mãe, que te fez nascer, em uma terra estrangeira, em que não nascestes; e lá morrereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Mas a terra à qual suas almas anseiam voltar, para lá nunca voltarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'É este homem Conias um pote quebrado, ou um vaso de quem ninguém se agrada? Por que ele e sua geração foram arremessados fora, e lançados a uma terra que não conhecem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Terra, terra, terra: ouve a palavra do SENHOR!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Assim diz o SENHOR: Escrevei este homem como sem filhos, homem a quem nada prosperará nos dias de sua vida; pois nenhum homem de sua semente prosperará em se sentar sobre o trono de Davi, e em reinar em Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Ai dos pastores que destroem e dispersam as ovelhas de meu rebanho!,Diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Portanto assim diz o SENHOR Deus de Israel quanto aos pastores que apascentam meu povo: Vós dispersastes minhas ovelhas, e as afugentastes, e não cuidastes delas; eis que eu cuidarei contra vós pela maldade de vossas ações,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'E eu mesmo recolherei o restante de minhas ovelhas de todas as terras para onde as afugentei, e as farei voltar a seus apriscos; e crescerão, e se multiplicarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'E porei sobre elas pastores que as apascentem; e nunca mais temerão, nem se assombrarão, nem haverá falta de uma sequer,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Eis que vêm os dias,diz o SENHOR, que levantarei por Davi um justo Renovo, e sendo rei, reinará; o qual prosperará, e fará juízo e justiça na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Em seus dias Judá será salvo, e Israel habitará em segurança; e este será seu nome com que o chamarão: O SENHOR é nossa justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Portanto eis que vêm dias,diz o SENHOR, que não mais dirão: Vive o SENHOR, que fez subir os filhos de Israel da terra do Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Mas sim: Vive o SENHOR, que fez subir e trouxe a geração da casa de Israel da terra do norte, e de todas as terras para onde eu os afugentei; e habitarão em sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Quanto aos profetas: meu coração está quebrantado em meu interior, todos os meus ossos tremem; estou como um homem bêbado, como um homem dominado pelo vinho, por causa do SENHOR, e por causa de suas santas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Pois a terra está cheia de adúlteros: e por causa da maldição a terra lamenta; as cabanas do deserto se secaram; pois o percurso deles tem sido mau, e a força deles não é correta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Pois tanto o profeta como o sacerdote são corruptos; até em minha casa achei sua maldade,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Portanto o caminho deles lhes será como lugares escorregadios na escuridão; serão empurrados, e nele cairão; porque eu trarei mal sobre eles no ano de sua punição,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Nos profetas de Samaria vi coisas desagradáveis: profetizavam por Baal, e faziam errar a meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Mas nos profetas de Jerusalém tenho vejo coisas horríveis: cometem adultérios, e andam com falsidade, e fortalecem as mãos dos malfeitores, para que ninguém se converta de sua maldade. Para mim, todos eles são como Sodoma, e seus moradores como Gomorra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Por isso assim diz o SENHOR dos exércitos sobre os profetas: Eis que eu lhes darei de comer absinto, e lhes farei beber águas de veneno; porque dos profetas de Jerusalém tem saído a corrupção por sobre toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Assim diz o SENHOR dos exércitos: Não deis ouvidos às palavras dos profetas que profetizam para vós; eles vos iludem; falam visão de seus próprios corações, e não da boca do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Dizem continuamente aos que me desprezam: O SENHOR diz: Tereis paz; E a qualquer um que segue a teimosia de seu próprio coração, dizem: Não virá mal algum sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Pois quem esteve no conselho do SENHOR, e viu e ouviu sua palavra? Quem prestou atenção a sua palavra, e a ouviu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Eis que a tempestade da ira do SENHOR já saiu; e a tempestade é violenta, que atingirá violentamente sobre a cabeça dos maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Não se afastará a ira do SENHOR, enquanto não tiver executado e cumprido os pensamentos de seu coração; nos últimos dias entendereis isso claramente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Eu não enviei aqueles profetas, porém eles foram correndo; eu não lhes falei, porém eles profetizaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Mas se eles tivessem estado em meu conselho, então teriam anunciado minhas palavras a meu povo; e teriam feito com que deixassem seu mau caminho e a maldade de suas ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Por acaso sou eu Deus apenas de perto,diz o SENHOR, e não também Deus de longe?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Pode alguém se esconder num esconderijo,diz o SENHOR, que eu não o veja? Por acaso não sou eu, diz o SENHOR, que encho os céus e a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Tenho ouvido o que aqueles profetas dizem, profetizando mentiras em meu nome, dizendo: Sonhei, sonhei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Até quando será isto no coração dos profetas que profetizam mentiras, dos que profetizam o engano de seu coração?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Que pretendem, por meio de seus sonhos que cada um conta a seu próximo, fazer com que meu povo se esqueça de meu nome, tal como seus pais se esqueceram de meu nome por causa de Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'O profeta que tiver sonho, conte o sonho; e aquele que tiver minha palavra, conte minha palavra de forma fiel. O que a palha tem a ver com o trigo?,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Por acaso não é minha palavra como o fogo?diz o SENHOR, E como um martelo que esmigalha a pedra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Portanto eis que eu sou contra os profetas,diz o SENHOR, que furtam minhas palavras cada um de seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Eis que eu sou contra os profetas,diz o SENHOR, que usam suas línguas, e declaram: Assim ele disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Eis que eu sou contra os que profetizam sonhos mentirosos,diz o SENHOR, e os contam, e fazem meu povo errar com suas mentiras e com suas lisonjas. E eu não os enviei, nem lhes mandei; e proveito nenhum fizeram a este povo, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'E quando este povo, ou o profeta, ou o sacerdote, te peguntar, dizendo: Qual é a revelação, a carga do SENHOR? Então tu lhes dirás: Que carga? Eu os abandonarei, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'E quanto ao profeta, o sacerdote, ou alguém do povo, que disser: Carga do SENHOR; eu enviarei castigo sobre tal homem e sobre sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Assim direis cada um a seu próximo, e cada um a seu irmão: O que o SENHOR respondeu?, e, O que o SENHOR falou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'E nunca mais mencionareis a carga do SENHOR; porque a palavra de cada um lhe servirá por carga; pois pervertestes as palavras do Deus vivente, do SENHOR dos exércitos, nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Assim dirás ao profeta: O que o SENHOR te respondeu? e, O que o SENHOR falou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Mas se disserdes: Carga do SENHOR; então por isso o assim diz o SENHOR: Porque dissestes esta palavra, Carga do SENHOR, tendo eu vos mandado, dizendo: Não digais “Carga do SENHOR”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Portanto eis que eu esquecerei totalmente; e lançarei fora de minha presença a vós, e à cidade que dei para vós e para vossos pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'E porei sobre vós humilhação perpétua e vergonha eterna, que nunca será esquecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'O SENHOR me mostrou, e eis dois cestos de figos postos diante do templo do SENHOR, depois de Nabucodonosor, rei da Babilônia, haver levado cativo a Jeconias, filho de Jeoaquim, rei de Judá, e aos príncipes de Judá, e aos carpinteiros e ferreiros de Jerusalém, e os ter trazido à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Um cesto tinha figos muito bons, como os primeiros figos a ficarem maduros; e a outra cesta tinha figos muito ruins, que não podiam ser comidos de tão ruins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'E disse-me o SENHOR: O que tu vês, Jeremias? E eu disse: Figos: os figos bons, muito bons; e os ruins, muito ruins, que de tão ruins não podem ser comidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Então veio a mim palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Assim diz o SENHOR Deus de Israel: Tal como a estes bons figos, assim também conhecerei aos levados de Judá cativos, aos quais mandei embora deste lugar à terra de Caldeus, para o bem deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'E porei meus olhos sobre eles para o bem, e os farei voltar a esta terra; eu os edificarei, e não os destruirei; eu os plantarei, e não os arrancarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'E lhes darei coração para que me conheçam, que eu sou o SENHOR; e eles serão meu povo, e eu lhes serei seu Deus; porque se converterão a mim de todo seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'E tal como os figos ruins, que de tão ruins não podem ser comidos, assim diz o SENHOR, assim também farei a Zedequias rei de Judá, e a seus príncipes, e ao resto de Jerusalém que restarem nesta terra, e aos que habitam na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'E os farei de motivo de horror para o mal a todos os reinos da terra; de insulto, de ditado, de ridículo, e de maldição a todos os lugares para onde eu os expulsei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'E enviarei entre eles espada, fome, e pestilência, até que sejam eliminados de sobre a terra que dei a eles e a seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Palavra que veio a Jeremias quanto a todo o povo de Judá, no quarto ano de Jeoaquim, filho de Josias, rei de Judá, (o qual é o primeiro ano de Nabucodonosor rei de Babilônia);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'A qual o profeta Jeremias falou a todo o povo de Judá, e a todos os moradores de Jerusalém, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Desde o ano treze de Josias, filho de Amom, rei de Judá, até este dia, isto é, há vinte e três anos, tem vindo a mim a palavra do SENHOR; e eu tenho vos falado, insistentemente vos falando; porém vós não escutastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'E o SENHOR enviou a vós todos seus servos os profetas, insistentemente os enviando; porém vos não escutastes, nem inclinastes vossos ouvidos para escutar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Quando diziam: Convertei-vos agora, cada um de seu mau caminho, e da maldade de vossas ações, e habitai na terra que o SENHOR deu a vós e a vossos pais para todo o sempre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'E não segui deuses estrangeiros, para os servirdes e encurvardes a eles, nem me provoqueis à ira com a obra de vossas mãos; para que eu não vos faça mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Porém vós não me destes ouvidos, diz o SENHOR, para me provocardes à ira com a obra de vossas mãos, para o vosso mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Portanto assim diz o SENHOR dos exércitos: Visto quanto não tendes ouvido minhas palavras,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Eis que eu enviarei, e tomarei a todas as famílias do norte, diz o SENHOR, e a Nabucodonosor rei de Babilônia, meu servo, e os trarei contra esta terra, e contra seus moradores, e contra todas estas nações ao redor; e os destruirei, e os farei de espanto, assovio, e de desolações perpétuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'E eliminarei dentre eles a voz de júbilo e voz de alegria, voz de noivo e voz de noiva, o ruído das pedras de moer, e a luz de lâmpada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'E toda esta terra se tornará em desolação, e em espanto; e estas nações servirão ao rei da Babilônia por setenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'E será que, quando os setenta anos forem completados, punirei ao rei da Babilônia e àquela nação por sua maldade, diz o SENHOR, assim como a terra dos Caldeus; e a tornarei em desolações para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'E trarei sobre aquela terra todas as minhas palavras que falado contra ela: tudo o que está escrito neste livro, que Jeremias profetizou contra todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Porque também deles se servirão muitas nações e grandes reis; assim lhes pagarei conforme seus feitos, conforme a obra de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Porque assim me disse o SENHOR Deus de Israel: Toma de minha mão este copo de vinho do meu furor, e dá de beber dele a todas as nações às quais eu te envio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'E beberão, tremerão, e enlouquecerão, por causa da espada que eu envio entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'E eu tomei o copo da mão do SENHOR, e dei de beber a todas as nações às quais o SENHOR tinha me enviado:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'A Jerusalém, às cidades de Judá; e a seus reis e seus príncipes, para torná-los em desolação, em espanto, em assovio, e em maldição, tal como é hoje;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'A Faraó rei do Egito, e a seus servos, seus príncipes, e a todo o seu povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'E a todas os povos ali misturados; e a todos os reis da terra de Uz, e a todos os reis da terra dos filisteus, e a Asquelom, Gaza, e Ecrom; e aos restantes de Asdode;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'A Edom, Moabe, e aos filhos de Amom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'E a todos os reis de Tiro, e a todos os reis da Sidom, e aos reis das terras litorâneas que estão além do mar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'E a Dedã, e Tema, e Buz, e a todos os dos cantos mais distantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'E a todos os reis de Arábia, e a todos os reis dos povos misturados que habitam no deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'E a todos os reis de Zinri, e a todos os reis de Elão, e a todos os reis de Média;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'E a todos os reis do norte, os de perto e os de longe, tanto uns como os outros; e a todos os reinos da terra que estão sobre a face da terra; e o rei de Sesaque beberá depois deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Pois tu lhes dirás: Assim diz o SENHOR dos exércitos, Deus de Israel: Bebei, e embriagai-vos, vomitai, caí, e não vos levanteis, por causa da espada que eu envio entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'E será que, se não querem tomar o copo de tua mão para beber, então tu lhes dirás: Assim diz o SENHOR dos exércitos: Certamente bebereis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Pois eis que na cidade que se chama pelo meu nome eu começo a castigar; e vós ficaríeis impunes? Não ficareis impunes, porque eu estou chamando espada contra todos os moradores da terra, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Tu, pois, profetizarás a eles todas estas palavras, e lhes dirás: O SENHOR bramará desde o alto, e levantará sua voz a sua santa morada; bramará intensamente sobre sua morada; dará forte grito, tal como os que pisam as uvas, contra todos os moradores da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Chegará o estrondo até o extremo da terra; porque o SENHOR disputa com as nações; entrará em juízo com todos; e entregará os perversos à espada, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Assim diz o SENHOR dos exércitos: Eis que a calamidade sai de nação em nação, e uma grande tempestade se levantará desde os confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'E os mortos pelo SENHOR naquele dia serão desde um extremo da terra até o outro extremo; não serão lamentados, nem recolhidos, nem sepultados; serão como esterco sobre a face da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Uivai, pastores, e clamai; e revolvei-vos na cinza, líderes do rebanho; porque já se cumpriram vossos dias para serdes mortos; e sereis dispersos e caireis como um vaso precioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'E não haverá meio de fuga para os pastores, nem escape para os líderes do rebanho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Haverá voz do grito dos pastores, e uivo dos lideres do rebanho; porque o SENHOR assolou os seus pastos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'E as pastagens quietas serão devastadas por causa do furor da ira do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Ele deixou seu abrigo tal como filhote de leão; pois assolada foi a terra deles, pelo furor do opressor, e pelo furor de sua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'No princípio do reinado de Jeoaquim, filho de Josias, rei de Judá, veio esta palavra do SENHOR,dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Assim diz o SENHOR: Põe-te no pátio da casa do SENHOR, e fala a todas as cidades de Judá, que vêm para adorar na casa do SENHOR, todas as palavras que te mandei que lhes falasses; não diminuas uma só palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Pode ser que ouçam, e se convertam cada um de seu mal caminho; então eu me arrependeria do mal que pretendo lhes fazer pela maldade de suas ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Dize-lhes, pois: Assim diz o SENHOR: Se não me ouvirdes para andardes em minha Lei, a qual dei diante de vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Para dar atenção às palavras de meus servos, os profetas, que eu vos envio, insistentemente os enviando, mas não os ouvistes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Então farei desta casa como a Siló, e tornarei esta cidade em maldição a todas as nações da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'E os sacerdotes, os profetas, e todo o povo, ouviram a Jeremias falar estas palavras na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'E sucedeu que, acabando Jeremias de falar tudo o que o SENHOR tinha lhe mandado falar a todo o povo, os sacerdotes e os profetas e todo o povo lhe pegaram, dizendo: Certamente morrerás;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Pois profetizaste em nome do SENHOR, dizendo: Esta casa será como Siló, e esta cidade será assolada até não restar morador.E juntou-se todo o povo contra Jeremias na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'E os príncipes de Judá, ao ouvirem estas coisas, subiram da casa do rei à casa do SENHOR; e sentaram-se à entrada da porta nova do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Então os sacerdotes e os profetas falaram aos príncipes e a todo o povo, dizendo: Pena de morte deve ter este homem, pois profetizou contra esta cidade, como ouvistes com vossos próprios ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'E Jeremias falou a todos os príncipes e a todo o povo, dizendo: O SENHOR me enviou para profetizar contra esta casa e contra esta cidade todas as palavras que ouvistes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Agora, portanto, melhorai vossos caminhos e vossas ações, e ouvi à voz do SENHOR vosso Deus; então o SENHOR mudará de ideia quanto ao mal que falou contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Eu, porém, eis que estou em vossas mãos: fazei de mim como parecer melhor e mais correto aos vossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Mas sabei certamente que, se vós me matardes, então trareis sangue inocente sobre vós, e sobre esta cidade, e sobre seus moradores; porque em verdade o SENHOR me enviou a vós para falar aos vossos ouvidos todas estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Então os príncipes e todo o povo disseram aos sacerdotes e profetas: Este homem não é merecedor de pena de morte, porque em nome do SENHOR nosso Deus ele nos falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'E se levantaram alguns dos anciãos da terra, e falaram a todo o ajuntamento do povo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Miqueias, o morastita, profetizou nos dias de Ezequias rei de Judá, e falou a todo o povo de Judá, dizendo: Assim diz o SENHOR dos exércitos: Sião será arada como campo, e Jerusalém se tornará em amontoados de pedras, e o monte do templo em lugares altos de mato.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Por acaso foi ele morto por Ezequias rei de Judá e todo Judá? Por acaso Ezequias não temeu ao SENHOR, e orou na presença do SENHOR, e o SENHOR mudou de ideia quanto ao mal que tinha falado contra eles? E nós, faremos pois tão grande mal contra nossas próprias almas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Houve também um homem que profetizava em nome do SENHOR: Urias, filho de Semaías de Quiriate-Jearim, o qual profetizou contra esta cidade e contra esta terra, conforme todas as palavras de Jeremias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'E quando ouviu suas palavras o rei Jeoaquim, e todos seus grandes, e todos seus príncipes, então o rei procurou matá-lo; e Urias, ao ouvir isso, teve medo, fugiu, e foi ao Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Porém o rei Jeoaquim enviou alguns homens a Egito: Elnatã filho de Acbor, e outros homens com ele, ao Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Os quais tiraram a Urias do Egito, e o trouxeram ao rei Jeoaquim, que o feriu à espada, e lançou seu cadáver nas sepulturas do povo comum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Porém a mão de Aicã, filho de Safã, foi com Jeremias, para que não o entregassem nas mãos do povo para o matarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'No princípio do reinado de Jeoaquim,filho de Josias, rei de Judá, veio do SENHOR esta palavra a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Assim me disse o SENHOR: Faz para ti amarras e jugos, e os põe sobre teu pescoço;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'E envia-os ao rei de Edom, ao rei de Moabe, ao rei dos filhos de Amom, ao rei de Tiro, e ao rei de Sidom, pelas mãos dos mensageiros que vêm a Jerusalém a Zedequias, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'E manda-lhes que digam a seus senhores: Assim diz o SENHOR dos exércitos, Deus de Israel: Assim direis a vossos senhores:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Eu fiz a terra, o homem, e os animais que estão sobre a face da terra, com meu grande poder e com meu braço estendido, e a dou a quem for do meu agrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'E agora dei todas estas terras na mão de Nabucodonosor, rei de Babilônia, meu servo, e até mesmo os animais do campo eu lhe dei, para que o sirvam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'E todas as nações servirão a ele, a seu filho, e ao filho de seu filho, até que também venha o tempo de sua própria terra; então servirá a muitas nações e grandes reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'E será que a nação e o reino que não servir a Nabucodonosor, rei da Babilônia, e que não puser seu pescoço sob do jugo do rei de Babilônia, então com espada, com fome e com pestilência castigarei tal nação, diz o SENHOR, até que eu os consuma por meio de sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'E vós não deis ouvidos a vossos profetas, nem a vossos adivinhos, nem a vossos sonhos, nem a vossos videntes, nem a vossos encantadores, que vos falam, dizendo: Não servireis ao rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Pois eles vos profetizam mentiras, para vos afastardes de vossa terra, e para que eu vos afugente, e pereçais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Mas a nação que pôr seu pescoço sob o jugo do rei da Babilônia, e o servir, a essa eu deixarei ficar em seu terra, e a cultivará, e nela habitará diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'E falei também a Zedequias, rei de Judá, conforme todas estas palavras, dizendo: Ponde vossos pescoços sob o jugo do rei da Babilônia, e servi a ele e a seu povo; então vivereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Por que morreríeis, tu e teu povo, pela espada, pela fome, pela pestilência, tal como disse o SENHOR sobre a nação que não servir ao rei da Babilônia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Não escuteis as palavras dos profetas que vos falam, dizendo: Não servireis ao rei da Babilônia; pois eles vos profetizam mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Pois eu não os enviei, diz o SENHOR, e eles profetizam falsamente em meu nome, para que eu vos afugente, e pereçais, vós e os profetas que vos profetizam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Também falei aos sacerdotes e a todo este povo, dizendo: Assim diz o SENHOR: Não escuteis as palavras de vossos profetas, que vos profetizam, dizendo: Eis que os vasos da casa do SENHOR voltarão da Babilônia em breve. Pois eles vos profetizam mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Não escuteis a eles; servi ao rei de Babilônia, e então vivereis; por que se tornaria esta cidade em deserto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Porém se eles são profetas, e se a palavra do SENHOR é com eles, orem agora ao SENHOR dos exércitos, que os objetos de valor que restaram na casa do SENHOR, na casa do rei de Judá, e em Jerusalém, não vão para a Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Porque assim diz o SENHOR dos exércitos quanto às colunas, ao mar, às bases, e ao restante dos objetos de valor que restaram nesta cidade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Que Nabucodonosor, rei da Babilônia, não tomou, quando levou cativo de Jerusalém a Babilônia a Jeconias, filho de Jeoaquim, rei de Judá, e a todos os nobres de Judá e de Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Assim pois diz o SENHOR dos exércitos, Deus de Israel, quanto aos objetos de valor que restaram na casa do SENHOR, e na casa do rei de Judá, e em Jerusalém:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Para a Babilônia serão levados, e ali ficarão até o dia em que eu os punirei, diz o SENHOR; então depois eu os farei subir, e os restituirei a este lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'E aconteceu no mesmo ano, no princípio do reinado de Zedequias, rei de Judá, no quarto ano, no quinto mês, que Hananias, filho de Azur, profeta que era de Gibeom, falou para mim na casa do SENHOR diante dos sacerdotes e de todo o povo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Assim fala o SENHOR dos exércitos, Deus de Israel, dizendo: Quebrarei o jugo do rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Dentro do tempo de dois anos, trarei de volta a este lugar todos os objetos de valor da casa do SENHOR, que Nabucodonosor, rei da Babilônia, tomou deste lugar para os levar à Babilônia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'E eu trarei de volta a este lugar a Jeconias filho de Jeoaquim, rei de Judá, e a todos os levados cativos de Judá que entraram na Babilônia, diz o SENHOR; pois quebrarei o jugo do rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Então o profeta Jeremias disse ao profeta Hananias, diante dos sacerdotes e diante de todo o povo que estava na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Disse, pois, o profeta Jeremias: Amém! Assim o faça o SENHOR! Que o SENHOR confirme as tuas palavras, com que profetizaste; para que os objetos de valor da casa do SENHOR, e sejam trazidos de volta todos os cativos da Babilônia para este lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Porém ouve agora esta palavra, que eu falo aos teus ouvidos e aos ouvidos de todo o povo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Os profetas que foram antes de mim e antes de ti, desde os tempos antigos, profetizaram contra muitas terras e grandes reinos, guerra, aflição, e pestilência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'O profeta que profetizar paz, quando suceder a palavra daquele profeta, será reconhecido tal profeta, que o SENHOR verdadeiramente o enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Então o profeta Hananias tomou o jugo do pescoço do profeta Jeremias, e o quebrou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'E falou Hananias diante dos olhos de todo o povo, dizendo: Assim diz o SENHOR: Desta maneira quebrarei o jugo de Nabucodonosor, rei da Babilônia, dentro do tempo de dois anos, de sobre o pescoço de todas as nações. E Jeremias saiu dali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Mas depois que o profeta Hananias quebrou o jugo do pescoço do profeta Jeremias, veio a palavra do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Vai, e fala a Hananias, dizendo: Assim diz o SENHOR: Jugos de madeira quebraste, mas farás em seu lugar jugos de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Jugo de ferro pus sobre o pescoço de todas estas nações, para que sirvam a Nabucodonosor rei da Babilônia, e a ele servirão; e até os animais do campo eu lhe dei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'E disse o profeta Jeremias ao profeta Hananias: Agora ouve, Hananias: o SENHOR não te enviou, porém tu fizeste este povo confiar em mentiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Por isso assim diz o SENHOR: Eis que eu te expulso de sobre a face da terra; morrerás neste ano, porque falaste rebelião contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'E morreu o profeta Hananias no mesmo ano, no sétimo mês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Estas são as palavras da carta que o profeta Jeremias enviou de Jerusalém ao restante dos anciãos levados cativos, como também aos sacerdotes e aos profetas, e a todo o povo, que Nabucodonosor havia transportado de Jerusalém para a Babilônia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Depois da saída do rei Jeconias, da rainha-mãe, dos príncipes de Judá e Jerusalém, e dos carpinteiros e ferreiros de Jerusalém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Enviada pela mão de Elasá, filho de Safã, e de Gemarias, filho de Hilquias, os quais Zedequias rei de Judá enviou a Nabucodonosor rei da Babilônia, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Assim diz o SENHOR dos exércitos, Deus de Israel, a todos os levados cativos, os quais fiz transportar de Jerusalém à Babilônia:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Edificai casas, e nelas habitai; plantai hortas, e comei o fruto delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Tomai esposas, e gerai filhos e filhas, e tomai esposas para vossos filhos, e dai vossas filhas a homens, para que gerem filhos e filhas; e ali multiplicai-vos, e não vos diminuais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'E buscai a paz da cidade para onde eu vos levei, e orai por ela ao SENHOR; porque na paz dela vós tereis paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Os vossos profetas, que há entre vós, e vossos adivinhos não vos enganem; nem escutais a vossos sonhos, que vós sonhais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Pois eles vos profetizam falsamente em meu nome; eu não os enviei, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Porque assim diz o SENHOR: Certamente que, quando se cumprirem setenta anos na Babilônia, eu vos visitarei; e cumprirei sobre vós minha boa palavra, trazendo-vos de volta a este lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Porque eu sei os pensamentos que penso quanto a vós, diz o SENHOR, pensamentos de paz, e não de mal, para vos dar um futuro com esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Então me invocareis, e ireis, e orareis a mim, e eu vos ouvirei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'E vós me buscareis e achareis, quando me buscardes de todo o vosso coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'E serei achado por vós, diz o SENHOR, e vos restauarei de vosso infortúnio, e vos ajuntarei de todas as nações, e de todos os lugares para onde eu vos lancei, diz o SENHOR; e vos farei voltar ao lugar de onde vos fiz serdes levados cativos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Visto que dizeis: “O SENHOR tem nos levantado profetas na Babilônia”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'por isso assim diz o SENHOR acerca do rei que se assenta sobre o trono de Davi, e de todo o povo que mora nesta cidade, os vossos irmãos que não saíram convosco ao cativeiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Assim diz o SENHOR dos exércitos: Eis que enviarei contra eles espada, fome, e pestilência; e farei deles como a figos podres, que de tão ruins não podem ser comidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'E os perseguirei com espada, com fome e com pestilência; e os farei de horror a todos os reinos da terra, de maldição e de espanto, e de assovio e de humilhação entre todas a nações às quais eu os tiver lançado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Porque não deram ouvidos às minhas palavras, diz o SENHOR, que lhes enviei por meus servos os profetas, insistindo em os enviar; próem não escutastes, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Vós, pois, ouvi a palavra do SENHOR, todos os do cativeiro que enviei de Jerusalém à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Assim diz o SENHOR dos exércitos, Deus de Israel, quanto a Acabe filho de Colaías, e quanto a Zedequias filho de Maaseias, que vos profetizam falsamente em meu nome: Eis que os entregarei na mão de Nabucodonosor rei da Babilônia, e ele os ferirá diante de vossos olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'E todos os exilados de Judá que estão na Babilônia, os usarão como objeto de maldição, dizendo: Que o SENHOR faça a ti como a Zedequias e como a Acabe, aos quais o rei de Babilônia assou no fogo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'porque fizeram loucura em Israel, e cometeram adultério com as mulheres de seus próximos; e falaram falsamente em meu nome palavra que não lhes mandei; e disso eu sei, e sou testemunha, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'E a Semaías o neelamita falarás, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Assim diz o SENHOR dos exércitos, Deus de Israel, dizendo: Enviaste em teu nome cartas a todo o povo que está em Jerusalém, e a Sofonias, filho do sacerdote Maaseias, e a todos os sacerdotes, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'O SENHOR te pôs por sacerdote em lugar do sacerdote Joiada, para que sejas supervisor na casa do SENHOR sobre todo homem furioso e profetizante, para o lançares na prisão e no tronco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Agora, pois, por que não repreendeste a Jeremias de Anatote, que vos profetiza?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Porque por isso ele nos mandou dizer na Babilônia: O cativeiro será duradouro; edificai casas, e nelas morai; plantai hortas, e comei o fruto delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'E o sacerdote Sofonias leu esta carta aos ouvidos do profeta Jeremias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Então veio a palavra do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Manda dizer a todos os do cativeiro: Assim diz o SENHOR quanto a Semaías, o neelamita: Visto que Semaías vos profetizou, sem que eu tenha o enviado, e vos fez confiar em mentiras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Portanto assim diz o SENHOR: Eis que castigarei Semaías o neelamita, e a sua descendência; ele não terá ninguém que habite entre este povo, nem verá o bem que eu farei a meu povo, diz o SENHOR; pois ele falou rebelião contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Palavra que veio do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Assim diz o SENHOR Deus de Israel, dizendo: Escreve para ti em um livro todas as palavras que tenho te falado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Porque eis que vêm dias, diz o SENHOR, em que restaurarei o meu povo, Israel e Judá, de seus infortúnios, diz o SENHOR, e os trarei de volta à terra que dei a seus pais, e a possuirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'E estas são as palavras que o SENHOR falou quanto a Israel e a Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Porque assim diz o SENHOR: Ouvimos voz de tremor; há temor, e não paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Perguntai pois, e olhai se o homem dá à luz; então por que vejo que todo homem com as mãos sobre seus lombos, como se fosse mulher de parto? E por que todos os rostos ficaram pálidos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ai! Pois aquele dia é tão grande, que não houve outro semelhante; é tempo de angústia para Jacó; porém será livrado dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Pois será naquele dia,diz o SENHOR dos exércitos, que eu quebrarei seu jugo de teu pescoço, e romperei tuas amarras; e estrangeiros nunca mais se servirão dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Em vez disso servirão ao SENHOR, seu Deus, e a Davi, seu rei, o qual lhes levantarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Tu pois, servo meu Jacó, não temas, diz o SENHOR, nem te espantes, ó Israel; porque eis que te salvarei de longe, e a tua descendência da terra do seu cativeiro; e Jacó voltará, descansará e sossegará, e não haverá quem o atemorize.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Pois estou contigo,diz o SENHOR, para te salvar; e pois exterminarei todas as nações entre a quais te espalhei; porém eu não exterminarei, mas te castigarei com moderação, e não te deixarei impune.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Porque assim diz o SENHOR: Teu quebrantamento é incurável, tua ferida é grave.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Não há quem julgue tua causa quanto a tua enfermidade; não há para ti remédios que curem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Todos os teus amantes se esqueceram de ti e não te buscam; pois te feri com ferida de inimigo, com castigo como de alguém cruel, por causa da grandeza de tua maldade, e da multidão de teus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Por que gritas por causa de teu quebrantamento? Tua dor é incurável; pois pela grandeza de tua maldade, e pela multidão de teus pecados te fiz estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Porém serão devorados todos os que te devoram; e todos os teus adversários, todos eles irão ao cativeiro; e roubados serão os que te roubam, e a todos os que te despojam entregarei para que sejam despojados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Mas eu te farei ter saúde, e sararei tuas feridas, diz o SENHOR; pois te chamaram de rejeitada, dizendo: Esta é Sião, a quem ninguém busca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Assim diz o SENHOR: Eis que restaurarei as tendas de Jacó de seu infortúnio, e me compadecerei de suas moradas; e a cidade será reedificada de suas ruínas, e o templo será posto no lugar de costume.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'E sairá deles louvor, e voz dos que estão cheios de alegria; e eu os multiplicarei, e não serão diminuídos; eu os glorificarei, e não serão menosprezados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'E seus filhos serão como no passado; e sua congregação será confirmada diante de mim; e punirei a todos os seus opressores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'E seu líder será dele, e seu governador saíra do meio dele; e eu o farei chegar perto, e ele se achegará a mim; pois quem jamais confiou em seu próprio coração para se achegar a mim? diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'E vós sereis meu povo, e eu serei vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Eis que a tempestade do SENHOR sai com furor, a tempestade impetuosa, que sobre a cabeça dos ímpios cairá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'A ardente ira do SENHOR não retrocederá enquanto não tiver feito e cumprido os pensamentos de seu coração; no fim dos dias entendereis isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Naquele tempo,diz o SENHOR, eu serei o Deus de todas as famílias de Israel, e elas serão o meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Assim diz o SENHOR: O povo dos que escaparam da espada encontrou graça no deserto; este é Israel, quando eu o fizer descansar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'O SENHOR apareceu a mim já há muito tempo, dizendo: Com amor eterno eu tenho te amado; por isso com bondade te sustento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Novamente te edificarei, e serás edificada, ó virgem de Israel; novamente serás adornada com teus tamborins, e sairás na dança dos que se alegram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Novamente plantarás vinhas nos montes de Samaria; os plantadores plantarão, e delas desfrutarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Pois haverá dia em que os vigilantes no monte de Efraim gritarão: Levantai-vos, e subamos a Sião, ao SENHOR nosso Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Porque assim diz o SENHOR: Cantai por Jacó com alegria, e jubilai por causa da principal de nações; anunciai, louvai, e dizei: Salva, SENHOR, o teu povo, o restante de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Eis que eu os trarei da terra do norte, e os juntarei desde os confins da terra, entre os quais haverá cegos e aleijados, mulheres grávidas e as que tiveram parto juntamente; em grande multidão voltarão para cá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Virão com choro, e com suplicações os trarei; e os guiarei a ribeiros de águas, por um caminho plano, em que não tropeçarão; porque sou um pai para Israel, e Efraim é meu primogênito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Ouvi a palavra do SENHOR, ó nações, e a anunciai nas terras litorâneas de longe, e dizei: Aquele que espalhou a Israel o juntará e o guardará, tal como um pastor a seu gado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Pois o SENHOR resgatou a Jacó, o livrou da mão do mais forte que ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'E virão, e jubilarão no lugar alto de Sião, e correrão para o bem do SENHOR: ao trigo, ao suco de uva, ao azeite, e aos cordeiros e bezerros; e a alma deles será como um jardim regado, e nunca mais se enfraquecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Então a virgem se alegrará na dança, como também os jovens e os velhos juntamente; e tornarei seu pranto em alegria, e os consolarei, e os alegrarei em sua tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'E encherei a alma dos sacerdotes de fartura, e meu povo será saciado com o meu bem, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Assim diz o SENHOR: Uma voz foi ouvida em Ramá, lamentação e choro amargo: Raquel chora por seus filhos; não quer ser consolada por causa de seus filhos, pois já não existem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Assim diz o SENHOR: Reprime tua voz de choro, e teus olhos de lágrimas; pois há recompensa para teu trabalho, diz o SENHOR, pois voltarão da terra do inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'E há esperança para o teu futuro,diz o SENHOR, pois os teus filhos voltarão a suas próprias fronteiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'De fato ouvi Efraim se queixar, dizendo: Castigaste-me, e fui castigado como um novilho não domado; converte-me e serei convertido; pois tu és o SENHOR meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Pois depois que me desviei, arrependi-me; depois que entendi, golpeei-me na coxa; envergonhei-me, e me senti humilhado, porque levei a vergonha de minha juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Por acaso não é Efraim um filho precioso para mim? Não é ele um filho do meu agrado? Pois mesmo tendo eu falado contra ele, eu me lembro dele constantemente. Por isso minhas entranhas se comovem por ele; certamente terei compaixão dele,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Levanta para ti sinais, põe para ti marcos altos; presta atenção à vereda, ao caminho por onde vieste; volta-te, ó virgem de Israel, volta-te para estas tuas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Até quando andarás sem rumo, ó filha rebelde? Pois o SENHOR criará uma coisa nova sobre a terra: uma fêmea cercará ao varão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Novamente dirão esta palavra na terra de Judá e em suas cidades, quando eu os restaurar de seu infortúnio: O SENHOR te abençoe, ó morada de justiça, ó monte santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'E nela habitarão Judá, e em todas as suas cidades juntamente: os lavradores, e os que caminham com o rebanho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Porque terei saciado a alma cansada, e enchido toda alma entristecida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, '(Nisto me despertei, e olhei; e meu sonho me foi agradável).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Diz o SENHOR: Eis que vêm dias, em que semearei a casa de Israel e a casa de Judá com semente de homens e com semente de animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'E será que, como tive atenção com eles para arrancar e para derrubar, para transtornar para destruir, e afligir, assim terei atenção com eles para edificar e plantar,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Naqueles dias nunca mais dirão: Os pais comeram uvas verdes, mas foram os dentes dos filhos que se estragaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Ao contrário, cada um morrerá por sua própria maldade; todo homem que comer as uvas verdes estragará seus dentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Eis que vêm dias,diz o SENHOR, em que farei um novo pacto com a casa de Jacó e a casa de Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Não como o pacto que fiz com seus pais, no dia em que os tomei pela mão para os tirar da terra do Egito; pois invalidaram meu pacto, ainda que eu tenha me casado com eles,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Mas este é o pacto que farei com a casa de Israel depois daqueles dias,diz o SENHOR: Darei minha lei em seu interior, e a escreverei em seus corações; e eu serei o Deus deles, e eles serão meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'E não ensinará mais ninguém a seu próximo, nem ninguém a seu irmão, dizendo: Conhece ao SENHOR; pois todos me conhecerão, desde o menor deles até o maior, diz o SENHOR; porque perdoarei a maldade deles, e nunca mais me lembrarei mais de seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Assim diz o SENHOR, que dá o sol para a luz do dia, e as ordenanças da lua e das estrelas para a luz da noite; que divide o mar, e bramam suas ondas; EU-SOU dos exércitos é seu nome:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Se estas ordenanças se desviarem diante de mim,diz o SENHOR, também a semente de Israel deixará de ser nação diante de mim para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Assim diz o SENHOR: Se os céus acima ser medidos, e se podem investigar abaixo os fundamentos da terra, então também eu rejeitarei toda a semente de Israel por tudo quanto fizeram, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Diz o SENHOR: Eis que vêm dias em que a cidade de Jerusalém será edificada ao SENHOR, desde a torre de Hananeel até a porta da esquina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'E a linha de medir sairá também diante dela, até sobre à colina de Garebe, e virará ao redor até Goa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'E todo o vale dos cadáveres e da cinza, e todas os campos até o ribeiro de Cedrom, até a esquina da porta dos cavalos ao oriente, serão consagrados ao SENHOR; nunca mais será arrancada nem derrubada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Palavra que veio do SENHOR a Jeremias, no décimo ano de Zedequias rei de Judá, que foi o décimo oitavo ano de Nabucodonosor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, '(Quando então o exército do rei da Babilônia tinha cercado a Jerusalém; e o profeta Jeremias estava preso no pátio da guarda, que estava na casa do rei de Judá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Pois Zedequias rei de Judá tinha lhe prendido, dizendo: Por que profetizas tu dizendo: Assim diz o SENHOR: “Eis que eu entrego esta cidade na mão do rei da Babilônia, e ele a tomará,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'E Zedequias rei de Judá não escapará da mão dos caldeus; ao contrário, certamente será entregue na mão do rei da Babilônia, e falará com ele face a face, e seus olhos verão seus olhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'E levará Zedequias à Babilônia, e ali ficará até que eu o visite, diz o SENHOR; se lutardes com os Caldeus, não vencereis”?)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Disse, pois, Jeremias: A palavra do SENHOR veio a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Eis que Hanameel, filho de Salum teu tio, está vindo a ti para dizer: Compra para ti minha propriedade que está em Anatote; pois tu tens o direito de resgate para comprá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'E veio a mim Hanameel, filho de meu tio, conforme à palavra do SENHOR, ao pátio da guarda, e me disse: Compra agora minha propriedade que está em Anatote, na terra de Benjamim; pois teu é o direito de herança, e teu é o resgate; compra -a para ti. Então entendi que isto era a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Assim comprei a propriedade de Hanameel, filho de meu tio, a qual está em Anatote; e pesei para ele o dinheiro: dezessete siclos de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'E assinei o documento, e o selei, e o fiz testemunhar a testemunhas; e pesei o dinheiro em balanças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Tomei logo o documento de compra selado, que continha os termos e condições, e a cópia aberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'E dei o documento de compra a Baruque, filho de Nerias, filho de Maasias, diante da vista de Hanameel filho de meu tio, e diante da vista das testemunhas que assinaram o documento de compra, e diante da vista de todos os judeus que estavam sentados no pátio da guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'E mandei a Baruque diante da vista deles, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Toma estes documentos, este documento de compra, tanto o que está selado como este documento aberto, e põe-nos em um vaso de barro, para que durem muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Pois assim diz o SENHOR dos exércitos, Deus de Israel: Ainda se comprarão casas, campos, e vinhas nesta terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'E depois que dei o documento de compra a Baruque filho de Nerias, orei ao SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ah Senhor DEUS! Eis que tu fizeste os céus e a terra com teu grande poder, e com teu braço estendido; não há coisa alguma que seja difícil para ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Tu, que mostras bondade a milhares, e retribuis a maldade dos pais no seio de seus filhos depois deles; o grande, poderoso Deus; EU-SOU dos exércitos é o seu nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Grande em conselho, e magnífico em feitos; pois teus olhos estão abertos sobre todos os caminhos dos filhos dos homens, para dar a cada um conforme seus caminhos, e conforme o fruto de suas obras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Que puseste sinais e maravilhas na terra do Egito até o dia de hoje, e em Israel, e entre os homens; e fizeste para ti um nome tal como é este dia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'E tiraste teu povo Israel da terra do Egito com sinais e maravilhas, com mão forte e braço estendido, e com grande espanto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'E deste-lhes esta terra, da qual juraste a seus pais lhes dar, terra que mana leite e mel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'E entraram, e tomaram posse dela; porém não obedeceram à tua voz, nem andaram em tua lei; nada fizeram do que lhes mandaste fazer; por isso fizeste vir sobre eles todo este mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Eis aqui os cercos! Já vieram à cidade para tomá-la; e a cidade está entregue nas mãos dos caldeus que lutam contra ela, por causa da espada, da fome e da pestilência; e o que falaste se cumpriu, e eis que tu estás vendo isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Porém tu, ó Senhor DEUS, me disseste: Compra para ti o campo por dinheiro, e faze com que testemunhas testemunhem; mesmo estando a cidade já entregue nas mãos dos caldeus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Então veio a palavra do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Eis que eu sou o SENHOR, Deus de toda carne: Existe, por acaso, algo difícil demais para mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Portanto assim diz o SENHOR: Eis que eu entrego esta cidade nas mãos dos caldeus, e na mão de Nabucodonosor rei de Babilônia, e ele a tomará;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'E os caldeus que lutam contra esta cidade entrarão, e incendiarão esta cidade com fogo, e a queimarão, juntamente com as casas sobre cujas terraços ofereceram incenso a Baal e fizeram ofertas de bebidas a deuses estrangeiros, para me provocarem à ira;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Pois os filhos de Israel e os filhos de Judá têm feito somente o mal diante dos meus olhos desde sua juventude; porque os filhos de Israel nada têm feito, a não ser somente me provocar à ira com a obra de suas mãos,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Pois esta cidade tem me causado minha ira e meu furor desde o dia que a edificaram até hoje, de tal maneira que eu a removerei de minha presença;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Por toda a maldade dos filhos de Israel e dos filhos de Judá, que têm feito para me provocarem à ira; eles, seus reis, seus príncipes, seus sacerdotes, seus profetas, os homens de Judá, e os moradores de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'E viraram para mim as costas, e não o rosto. Ainda que eu tenha lhes ensinado, insistindo em ensinar, contudo se recusaram a ouvir para receberem correção;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Ao invés disso, puseram suas abominações na casa que se chama pelo meu nome, para a profanarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'E edificaram os altos de Baal, que ficam no vale do filho de Hinom, para fazer seus filhos e suas filhas passarem pelo fogo a Moloque, o que nunca lhes mandei, nem pensei em meu coração, para que fizessem tal abominação, para fazerem pecar a Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'E portanto agora assim diz o SENHOR Deus de Israel, quanto a esta cidade, da qual vós dizeis: Já está entregue nas mãos do rei de Babilônia à espada, à fome, e à pestilência:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Eis que eu os ajuntarei de todas as terras para onde eu os tiver lançado com minha ira, meu furor e grande indignação; e os farei voltar a este lugar, e os farei habitar em segurança;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'E eles serão meu povo, e eu lhes serei seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'E lhes darei um só coração e um só caminho, para que me temam todos os dias, para o bem deles, e de seus filhos depois deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'E farei com eles um pacto eterno, que não lhes deixarei de fazer o bem, e porei o temor a mim no coração deles, para que nunca se afastem de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'E me alegrarei com eles fazendo-lhes bem, e fielmente os plantarei nesta terra, com todo meu coração e com toda a minha alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Pois assim diz o SENHOR: Assim como trouxe sobre este povo todo este grande mal, assim também trarei sobre eles todo o bem que eu lhes prometo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'E campos serão comprados nesta terra da qual vós dizeis: Está desolada, sem homens e sem animais; está entregue nas mãos dos caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Campos serão comprados por dinheiro, e se assinarão documentos, e os selarão, e farão testemunhas testificarem, na terra de Benjamim, nos arredores de Jerusalém, e nas cidades de Judá; nas cidades das montanhas, e nas cidades das planícies, e nas cidades do Negueve; porque eu os restaurarei de seu infortúnio, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'E veio a palavra do SENHOR a Jeremias pela segunda vez, estando ele ainda preso no pátio da guarda, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Assim diz o SENHOR que faz isto; o SENHOR, que forma isto para o confirmar; EU-SOU é o seu nome:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Clama a mim, e eu te responderei; e te direi coisas grandes e difíceis que tu não conheces.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Pois assim diz o SENHOR, Deus de Israel, quanto às casas desta cidade, e às casas dos reis de Judá, que foram derrubadas com as rampas de cerco e com espada:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Vieram lutar contra os caldeus, para enchê-las de cadáveres de homens, aos quais feri em minha ira e meu furor; pois escondi meu rosto desta cidade, por causa de toda a sua malícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Eis que eu lhes trarei saúde e cura, e os sararei; e lhes manifestarei abundância de paz e de verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'E restaurarei Judá de seu infortúnio, e israel de seu infortúnio, e os edificarei como no princípio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'E os purificarei de toda a sua maldade com que pecaram contra mim; e perdoarei todas as suas maldades com que pecaram contra mim, e que se rebelaram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'E esta cidade será para mim como nome de alegria, de louvor e de glória, entre todas as nações da terra, que ouvirem todo o bem que eu lhes faço; e se espantarão e tremerão por causa de todo o bem e de toda a paz que eu lhes darei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Assim diz o SENHOR: Neste lugar, do qual dizeis que está desolado, sem homens nem animais, nas cidades de Judá e nas ruas de Jerusalém, que estão desoladas, sem homem, nem morador, nem animal, ainda se ouvirá');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Voz de júbilo e voz de alegria, voz de noivo e voz de noiva, e voz dos que dizem: Louvai ao SENHOR dos exércitos, pois o SENHOR é bom; pois sua bondade dura para sempre; e também dos que trazem louvor à casa do SENHOR; porque restaurarei o país de seu infortúnio para o que era no princípio, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Assim diz o SENHOR dos exércitos: Neste lugar desolado, sem homem nem animal, e em todas as suas cidades, haverá novamente morada de pastores, que façam deitar o gado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Nas cidades das montanhas, nas cidades das planícies, nas cidades do Negueve, na terra de Benjamim, e ao redor de Jerusalém e nas cidades de Judá, novamente passará o gado pelas mãos dos contadores, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Eis que vêm dias, diz o SENHOR, em que eu confirmarei a boa palavra que prometi à casa de Israel e à casa de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Naqueles dias e naquele tempo farei brotar a Davi um Renovo de justiça; e ele fará juízo e justiça na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Naqueles dias Judá será salvo, e Jerusalém habitará em segurança, e isto é o que a chamarão: O SENHOR é nossa justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Pois assim diz o SENHOR: Não faltará a Davi homem que se sente sobre o trono da casa de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Nem aos sacerdotes levitas faltará homem de diante de mim que ofereça oferta de queima, e queime oferta de alimentos, e faça sacrifício todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'E veio a palavra do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Assim diz o SENHOR: Se puderdes invalidar meu pacto do dia e meu pacto da noite, de tal modo que não haja dia e noite a seu tempo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Também se poderá invalidar meu pacto com meu servo Davi, para que não tenha filho que reine sobre seu trono, e com os levitas e sacerdotes, trabalhadores a meu serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Assim como não se pode contar o exército do céu, nem se pode medir a areia do mar, assim também multiplicarei a descendência de Davi meu servo, e os levitas que me servem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'E veio a palavra do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Por acaso não tens visto o que este povo fala? Eles dizem: As duas famílias que o SENHOR havia escolhido agora ele as rejeitou. E desprezam a meu povo, como se não o considerassem mais como nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Assim diz o SENHOR: Se meu pacto com o dia e a noite não durasse, se eu não tivesse estabelecido as leis do céu e a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Então também rejeitaria a descendência de Jacó, e de Davi meu servo, para que não tomasse da sua descendência aos que governem sobre a descendência de Abraão, Isaque, e Jacó. Pois eu os restaurarei de seu infortúnio, e deles terei misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Palavra que veio do SENHOR a Jeremias, (quando Nabucodonosor rei da Babilônia, e todo o seu exército, e todos os reinos da terra que estavam sob o domínio de sua mão, e todos os povos, lutavam contra Jerusalém e contra todas as suas cidades), dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Assim diz o SENHOR Deus de Israel: Vai, e fala a Zedequias rei de Judá, e dize-lhe: Assim diz o SENHOR: Eis que eu dou esta cidade na mão do rei de Babilônia, e ele a queimará no fogo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'E tu não escaparás de sua mão; ao contrário, certamente serás preso, e serás entregue na mão dele; e teus olhos verão os olhos do rei da Babilônia, e ele te falará face a face, e entrarás na Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Ainda assim, ouve a palavra do SENHOR, ó Zedequias rei de Judá; assim diz o SENHOR quanto ti: Tu não morrerás à espada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Em paz morrerás, e conforme às cerimônias de queimas por teus pais, os primeiros reis, que foram antes de ti, assim queimarão por ti, e prantearão por ti, dizendo: Ai, senhor!; pois eu disse esta palavra, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'E o profeta Jeremias falou a Zedequias, rei de Judá, todas estas palavras em Jerusalém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Enquanto o exército do rei de Babilônia lutava contra Jerusalém e contra todas as cidades de Judá que haviam restado: contra Laquis, e contra Azeca; pois essas cidades fortificadas haviam restado dentre as cidades de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Palavra que veio do SENHOR a Jeremias, depois que o rei Zedequias fez um pacto com todo o povo em Jerusalém, para lhes proclamar liberdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Que cada um libertasse seu servo, e cada um sua serva, hebreu ou hebreia; de maneira que ninguém usasse dos seus irmãos judeus como servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'E atenderam todos os príncipes, e todo o povo, que entraram no pacto de cada um libertar a seu servo e cada um libertar sua serva, de maneira que ninguém usasse mais deles como servos, atenderam, e os liberaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Porém depois se arrependeram, e trouxeram de volta os servos e as servas que haviam libertado, e os sujeitaram para serem servos e servas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Então veio a palavra do SENHOR a Jeremias, de parte do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Assim diz o SENHOR, Deus de Israel: Eu fiz um pacto com vossos pais no dia em que os tirei da terra do Egito, da casa de servos, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Ao fim de sete anos libertareis cada um a seu irmão hebreu que te for vendido, e tiver servido a ti por seis anos; e o deixarás livre de ti; mas vossos pais não me ouviram, nem inclinaram seu ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'E recentemente vós havíeis vos convertido, e tínheis feito o correto em meus olhos, proclamando cada um liberdade a seu próximo; e havíeis feito um pacto diante de minha presença, na casa sobre que se chama pelo meu nome:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Porém mudastes de ideia e profanastes o meu nome, e trouxestes de volta cada um a seu servo e cada um sua serva, os quais já havíeis libertado à vontade deles; e os sujeitastes para que sejam vossos servos e servas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Portanto assim diz o SENHOR: Vós não me ouvistes em proclamar cada um liberdade a seu irmão, e cada um a seu companheiro; eis que eu vos proclamo liberdade, diz o SENHOR, para a espada, para a pestilência, e para a fome; e eu vos tornarei em motivo de espanto a todos os reinos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'E entregarei os homens que transgrediram meu pacto, que não cumpriram as palavras do pacto que fizeram diante de mim, dividindo em duas partes o bezerro e passando entre de seus pedaços:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Os príncipes de Judá e os príncipes de Jerusalém, os eunucos e os sacerdotes, e todo o povo da terra, que passaram entre os pedaços do bezerro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Eu os entregarei na mão de seus inimigos, e na mão dos que buscam tirar sua vida; e seus cadáveres serão alimento para as aves do céu, e para os animais da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'E até a Zedequias, rei de Judá, e a seus príncipes, entregarei na mão de seus inimigos, e na mão dos que buscam tirar sua vida, e na mão do exército do rei da Babilônia, que se retiraram de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Eis que eu darei ordem, diz o SENHOR, e os farei voltarem a esta cidade; e lutarão contra ela, e a tomarão, e a queimarão a fogo; e tornarei em desolação as cidades de Judá, de modo que não haja morador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Palavra que veio do SENHOR a Jeremias nos dias de Jeoaquim filho de Josias, rei de Judá, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Vai à casa dos recabitas, e fala com eles, e leva-os à casa do SENHOR, a uma das câmaras; e dá-lhes de beber vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Tomei então a Jazanias filho de Jeremias, filho de Habazinias, e a seus irmãos, e a todos os seus filhos, e todos da casa dos recabitas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'E os levei à casa do SENHOR, à câmara dos filhos de Hanã, filho de Jigdalias, homem de Deus, a qual estava junto à câmara dos príncipes, que é acima da câmara de Maaseias filho de Salum, guarda da porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'E pus diante dos filhos da casa dos recabitas taças e copos cheios de vinho, e disse-lhes: Bebei vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Porém eles disseram: Não beberemos vinho; porque Jonadabe filho de Recabe, nosso pai, nos mandou, dizendo: Nunca bebereis vinho, nem vós nem vossos filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Nem edificareis casa, nem semeareis semente, nem plantareis vinha, nem a tereis; em vez disso habitareis em tendas todos os vossos dias, para que vivais muitos dias sobre a face da terra onde vós peregrinais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'E nós temos obedecido à voz de Jonadabe, filho de Recabe, nosso pai; em tudo quanto ele nos mandou, de maneira que não bebemos vinho em todos os nossos dias, nós, nem nossas mulheres, nossos filhos, e nossas filhas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Nem edificamos casas para nossa habitação; nem temos vinha, nem campo, nem sementeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'E habitamos em tendas, e assim temos obedecido e feito conforme a tudo quanto nos mandou Jonadabe nosso pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Sucedeu, porém, que quando Nabucodonosor rei de Babilônia subiu a esta terra, dissemos: Vinde, e vamos a Jerusalém, por causa do exército dos caldeus e por causa do exército dos sírios; e assim ficamos em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Então veio a palavra do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Vai, e dize aos homens de Judá, e aos moradores de Jerusalém: Por acaso nunca aceitareis ensino para obedecer a minhas palavras? Diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'As palavras de Jonadabe, filho de Recabe, que mandou a seus filhos que não bebessem vinho, foram obedecidas; pois não o beberam até hoje, por terem ouvido ao mandamento de seu pai; e eu vos tenho falado, insistindo em falar, mas vós não me ouvistes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'E enviei a vós a todos os meus servos, os profetas, insistindo em enviá-los, para dizerem: Convertei-vos agora cada um de seu mal caminho, e fazei boas as vossas ações, e não sigais a outros deuses para lhes servi-los, e assim vivereis na terra que dei a vós e a vossos pais; porém não inclinastes vossos ouvidos, nem me obedecestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Dado que os filhos de Jonadabe, filho de Recabe, guardaram o mandamento de seu pai que lhes mandou, mas este povo não me tem obedece,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Portanto assim diz o SENHOR Deus dos exércitos, Deus de Israel: Eis que eu trarei sobre Judá e sobre todos os moradores de Jerusalém todo o mal que falei contra eles; pois eu lhes falei, mas não ouviram; eu os chamei, mas não responderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'E disse Jeremias aos da casa dos recabitas: Assim diz o SENHOR dos exércitos, Deus de Israel: Por obedecerdes ao mandamento de Jonadabe vosso pai, e guardardes todos os seus mandamentos, e fizerdes conforme a tudo quanto ele vos mandou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Portanto, assim diz o SENHOR dos exércitos, Deus de Israel: Nunca faltará homem da descendência de Jonadabe, filho de Recabe, que esteja diante de minha presença, todos os dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Sucedeu, no quarto ano de Jeoaquim, filho de Josias, rei de Judá, que veio esta palavra do SENHOR a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Toma para ti um rolo de livro, e escreve nele todas as palavras que falei a ti sobre Israel e sobre Judá, e sobre todas as nações, desde o dia que comecei a falar a ti, desde os dias de Josias até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Talvez a casa de Judá ouça todo o mal que eu penso lhes fazer; para que cada um se converta de seu mau caminho; então eu perdoarei a maldade e o pecado deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Então Jeremias chamou a Baruque, filho de Nerias; e Baruque escreveu da boca de Jeremias, em um rolo de livro, todas as palavras que o SENHOR havia lhe falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'E Jeremias mandou a Baruque, dizendo: Eu estou preso, não posso entrar na casa de SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Portanto entra tu, e lê do rolo que escreveste de minha boca as palavras do SENHOR aos ouvidos do povo, na casa do SENHOR, no dia do jejum; e também as lerás aos ouvidos de todo Judá, os que vêm de suas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Talvez a oração deles chegue à presença do SENHOR, e cada um se converta de seu mau caminho; porque grande é a ira e o furor que o SENHOR tem pronunciado contra este povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'E Baruque filho de Nerias fez conforme a tudo quanto o profeta Jeremias havia lhe mandado, lendo naquele livro as palavras do SENHOR na casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'E aconteceu no quinto ano de Jeoaquim filho de Josias, rei de Judá, no nono mês, que proclamaram jejum diante do SENHOR, a todo o povo em Jerusalém, como também a todo o povo que vinha das cidades de Judá a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Então Baruque leu naquele livro as palavras de Jeremias na casa do SENHOR, na câmara de Gemarias, filho de Safã, o escriba, no pático de cima, à entrada da porta nova da casa do SENHOR, aos ouvidos de todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'E Miqueias, filho de Gemarias, filho de Safã, quando ouviu todas as palavras do SENHOR daquele livro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Desceu à casa do rei, à câmara do escriba; e eis que estavam ali sentados todos os príncipes: Elisama, o escriba; Delaías filho de Semeías; Elnatã filho de Acbor; Gemarias filho de Safã; Zedequias filho de Ananias; como também a todos os príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'E Miqueias lhes anunciou todas as palavras que tinha ouvido enquanto Baruque lia no livro aos ouvidos do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Então todos os príncipes enviaram a Jeudi filho de Netanias, filho de Selemias, filho de Cusi, para que dissesse a Baruque: Toma o rolo em que leste aos ouvidos do povo, e vem. Então Baruque filho de Nerias tomou o rolo em sua mão, e veio a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'E lhe disseram: Senta-te agora, e o lê aos nossos ouvidos. E Baruque leu aos seus ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'E sucedeu que, quando ouviram todas aquelas palavras, cada um se voltou espantado uns aos outros, e disseram a Baruque: Sem dúvida alguma anunciaremos ao rei todas estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'E perguntaram a Baruque, dizendo: Conta-nos agora: como escreveste todas estas palavras? Da boca de Jeremias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'E Baruque lhes disse: Ele me ditava de sua boca todas estas palavras, e eu escrevia no livro com tinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Então disseram os príncipes a Baruque: Vai, e esconde-te, tu e Jeremias, e ninguém saiba onde estais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'E foram ao encontro do rei no pátio, porém o rolo depositaram na câmara de Elisama, o escriba; e contaram aos ouvidos do rei todas aquelas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Então o rei enviou a Jeudi para que tomasse o rolo; e o tomou da câmara de Elisama, o escriba, e Jeudi o leu aos ouvidos do rei, e aos ouvidos de todos os príncipes que estavam junto ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, '(E o rei estava na casa de inverno, no nono mês; e havia diante dele um braseiro aceso);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'E sucedeu que, havendo Jeudi lido três ou quatro colunas, rasgou-o com uma lâmina de escrever, e o lançou no fogo que tinha no braseiro, até que todo o rolo se consumiu no fogo que estava no braseiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'E não temeram, nem rasgaram suas vestes, o rei e todos seus servos que ouviram todas estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'E ainda que Elnatã, Delaías e Gemarias tenham rogado ao rei que não queimasse aquele rolo, mesmo assim ele se recusou a os ouvir;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Em vez disso, o rei mandou a Jerameel filho do rei, a Seraías filho de Azriel, e a Selemias filho de Abdeel, que prendessem ao escriba Baruque e ao profeta Jeremias; mas o SENHOR havia os escondido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Então veio a palavra do SENHOR a Jeremias, depois do rei ter queimado o rolo, e as palavras que Baruque tinha escrito da boca de Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Toma de novo outro rolo, e escreve nele todas as primeiras palavras que estavam no primeiro rolo, o qual queimou Jeoaquim, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'E dirás a Jeoaquim rei de Judá: Assim diz o SENHOR: Tu queimaste este rolo, dizendo: Por que escreveste nele, dizendo: Certamente virá o rei da Babilônia, e destruirá esta terra, e fará com que não fiquem nela homens nem animais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Portanto assim diz o SENHOR quanto a Joaquim rei de Judá: Ele não terá quem se sente sobre o trono de Davi; e seu cadáver será lançado ao calor do dia e à geada da noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'E punirei a ele, assim como sua semente e os seus servos, por sua perversidade; e trarei sobre eles, sobre os moradores de Jerusalém, e sobre os homens de Judá, todo o mal que tenho lhes dito mas não quiseram ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Então Jeremias tomou outro rolo, e o deu a Baruque filho de Nerias, o escriba; o qual escreveu nele da boca de Jeremias todas as palavras do livro que Jeoaquim, rei de Judá, tinha queimado a fogo; e ainda foram acrescentadas a elas muitas outras palavras semelhantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'E o rei Zedequias, filho de Josias, reinou em lugar de Conias filho de Jeoaquim, ao qual Nabucodonosor, rei da Babilônia, tinha constituído por rei na terra de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Porém nem ele, nem seus servos, nem o povo da terra, deram ouvidos às palavras do SENHOR, que falou por meio do profeta Jeremias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Porém o rei Zedequias mandou a Jucal filho de Selemias, e a Sofonias filho de Maaseias sacerdote, para que dissessem ao profeta Jeremias: Roga agora por nós ao SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'E Jeremias tinha liberdade de entrar e sair entre o povo, pois não o tinham posto na casa do cárcere.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'E o exército de Faraó havia saído do Egito. E os caldeus que tinham cercado a Jerusalém, ao ouvirem esta notícia, foram embora de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Então veio palavra do SENHOR a Jeremias, o profeta, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Assim diz o SENHOR Deus de Israel: Assim direis ao rei de Judá, que vos enviou a mim para me perguntar: Eis que o exército de Faraó que saiu para vosso socorro voltará a sua terra, ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'E os caldeus voltarão, e lutarão contra esta cidade; e a tomarão, e a queimarão a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Assim diz o SENHOR: Não enganeis vossas almas, dizendo: Sem dúvida os caldeus irão embora de nós; pois não irão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Porque mesmo se ferísseis todo o exército dos caldeus que lutam contra vós, e restassem deles apenas homens feridos, ainda assim cada um se levantaria em sua tenda, e queimaria esta cidade a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'E aconteceu que, quando o exército dos caldeus havia saído de Jerusalém por causa do exército de Faraó,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Jeremias saiu de Jerusalém para ir à terra de Benjamim, para ali receber sua parte no meio do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Porém quando ele chegou à porta de Benjamim, estava ali um capitão dos da guarda, cujo nome era Jerias, filho de Selemias, filho de Hananias; o qual prendeu ao profeta Jeremias, dizendo: Estás te rendendo aos caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'E disse Jeremias diz: Não é verdade; eu não estou me rendendo aos caldeus. Porém ele não lhe deu ouvidos; em vez disso, Jerias prendeu a Jeremias, e o levou aos príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'E os príncipes se iraram muito contra Jeremias, e o feriram; e o puseram na prisão, na casa do escriba Jônatas, pois a tinham tornado em cárcere.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Jeremias entrou na casa da masmorra, e nas celas; e havendo Jeremias estado ali por muitos dias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'O rei Zedequias enviou, e mandou trazê-lo; e o rei lhe perguntou em sua casa em segredo, e disse: Há alguma palavra do SENHOR? E Jeremias disse: Há. E ele disse: Na mão do rei da Babilônia serás entregue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Disse mais Jeremias ao rei Zedequias: Em que pequei contra ti, contra teus servos, e contra este povo, para que me pusésseis no cárcere?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'E onde estão vossos profetas que vos profetizavam, dizendo: Não virá o rei da Babilônia contra vós, nem contra esta terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Agora pois, ouve, por favor, ó rei, meu senhor: chegue, por favor, minha súplica diante de ti, e não me deixes voltar à casa do escriba Jônatas, para que eu não morra ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Então o rei Zedequias mandou que pusessem a Jeremias no pátio da guarda, e que lhe dessem uma porção de pão por dia, da rua dos padeiros, até todo o pão da cidade ter se acabado. Assim Jeremias ficou no pátio da guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Então Sefatias filho de Matã, Gedalias filho de Pasur, Jucal filho de Selemias, e Pasur filho de Melquias, ouviram as palavras que Jeremias falava a todo o povo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Assim diz o SENHOR: Quem ficar nesta cidade morrerá pela espada, pela fome, ou pela pestilência; mas quem sair aos caldeus viverá, pois sua alma lhe será por despojo, e viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Assim diz o SENHOR: Certamente esta cidade será entregue nas mãos do exército do rei da Babilônia, que a tomará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'E os príncipes disseram ao rei: Morra agora este homem; porque assim ele enfraquece as mãos dos homens de guerra que restaram nesta cidade, e as mãos de todo o povo, falando-lhes tais palavras; pois este homem não busca a paz deste povo, mas sim o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'E disse o rei Zedequias: Eis que ele está em vossas mãos; pois o rei não poderia fazer contra vós coisa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Então eles tomaram a Jeremias, e o lançaram na cisterna de Malquias filho de rei, que estava no pátio da guarda; e meteram a Jeremias com cordas. Porém na cisterna não havia água, mas sim lama; e Jeremias se atolou na lama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'E Ebede-Meleque, o cuxita, um eunuco que estava na casa do rei, tendo ouvido que haviam posto Jeremias na cisterna, e estando o rei sentado à porta de Benjamim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Logo Ebede-Meleque saiu da casa do rei, e falou ao rei, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Ó rei, meu senhor o rei, estes homens fizeram o mal em tudo quanto têm feito com o profeta Jeremias, ao qual lançaram na cisterna; porque ali ele morrerá de fome, pois não há mais pão na cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Então o rei mandou a Ebede-Meleque, o cuxita, dizendo: Toma sob tuas ordens trinta homens daqui, e tira ao profeta Jeremias da cisterna, antes que morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'E Ebede-Meleque tomou sob suas ordens os homens, e foi à casa do rei, ao lugar debaixo da tesouraria, e tomou dali trapos velhos rasgados, e trapos velhos gastos; e os desceu a Jeremias com cordas na cisterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'E disse Ebede-Meleque o cuxita a Jeremias: Põe agora esses trapos velhos, rasgados, e gastos abaixo das axilas de teus braços, por debaixo das cordas. E Jeremias assim fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'E tiraram a Jeremias com as cordas, e o fizeram subir da cisterna; e Jeremias ficou no pátio da guarda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Então o rei Zedequias enviou, e mandou trazer a si ao profeta Jeremias à terceira entrada que estava na casa do SENHOR. E disse o rei a Jeremias: Pergunto-te uma coisa; não me encubras nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'E Jeremias disse a Zedequias: Se eu te declarar, por acaso não me matarás? E se eu te aconselhar, não me darás ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Então o rei Zedequias jurou a Jeremias em segredo, dizendo: Vive o SENHOR que nos fez esta alma, que não te matarei, nem te entregarei nas mãos destes homens que buscam tirar tua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Então Jeremias disse a Zedequias: Assim diz o SENHOR Deus dos exércitos, Deus de Israel: Se voluntariamente saíres aos príncipes do rei de Babilônia, então tua alma viverá, e esta cidade não será queimada a fogo; e viverás tu e tua casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mas se não saíres aos príncipes do rei de Babilônia, então esta cidade será entregue nas mãos dos caldeus, e a queimarão a fogo; e tu não escaparás de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'E disse o rei Zedequias a Jeremias: Eu temo por causa dos judeus que se renderam aos caldeus; que não venham a me entregar em suas mãos, e me maltratem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'E disse Jeremias: Não te entregarão. Ouve, por favor, a voz do SENHOR que eu te falo, e terás bem, e tua alma viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Mas se tu não quiseres sair, esta é a palavra que o SENHOR me mostrou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Eis que todas as mulheres que restaram na casa do rei de Judá serão levadas aos príncipes do rei da Babilônia; e elas mesmas dirão: Os teus amigos te enganaram, e prevaleceram contra ti; teus pés se atolaram na lama, e eles se viraram para trás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Assim todas as tuas mulheres e teus filhos serão levados aos caldeus, e tu não escaparás de suas mãos; ao contrário, pela mão do rei da Babilônia serás preso, e esta cidade será queimada a fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Então Zedequias disse a Jeremias: Ninguém saiba estas palavras, e então não morrerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'E se os príncipes ouvirem que eu falei contigo, vierem a ti, e te disserem: Declara-nos agora o que falaste com o rei; não nos escondas, e não te mataremos; dize também o que o rei te falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Então tu lhes dirás: Supliquei ao rei que não me fizesse voltar a casa de Jônatas para eu não morrer ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'E depois vieram todos os príncipes a Jeremias, e lhe perguntaram; e ele lhes respondeu conforme toda as palavras que o rei tinha lhe mandado. Então lhe deixaram, pois a conversa não tinha sido ouvida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'E Jeremias ficou no pátio da guarda até o dia em que Jerusalém foi tomada; e ali ainda estava quando Jerusalém foi tomada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'No nono ano de Zedequias rei de Judá, no décimo mês, veio Nabucodonosor rei da Babilônia com todo seu exército contra Jerusalém, e a cercaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'E no décimo primeiro ano de Zedequias, no quarto mês, aos nove do mês, foi rompida a cidade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'E entraram nela todos os príncipes do rei de Babilônia, e se sentaram à porta do meio: Nergal-Sarezer, Sangar-Nebo, Sarsequim, Rabsáris, Nergal-sarezer, Rabmague, e todos os demais príncipes do rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'E sucedeu que, Zedequias, rei de Judá, e todos os homens de guerra, quando os viram, fugiram, e saíram de noite da cidade pelo caminho do jardim do rei, pela porta entre os dois muros; e saíram pelo caminho de Arabá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Porém o exército dos caldeus os perseguiu, e alcançaram a Zedequias nas plancíes de Jericó; e o prenderam, e o fizeram subir a Nabucodonosor rei da Babilônia, a Ribla, na terra de Hamate; e ele sentenciou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'E o rei da Babilônia degolou os filhos de Zedequias em Ribla diante de seus olhos; o rei da Babilônia também degolou a todos os nobres de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'E cegou os olhos de Zedequias, e o aprisionou com cadeias de bronze, para o levar à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'E os caldeus queimaram a casa do rei e as casas do povo a fogo, e derrubaram os muros de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'E o restante do povo que tinha restado na cidade, e os que haviam a ele se rendido, com todo o resto do povo que tinha restado, Nabuzaradã, capitão da guarda, transportou-os à Babilônia');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Porém Nabuzaradã, capitão da guarda, fez restar na terra de Judá os mais pobres do povo, que não tinham nada, e lhes deu vinhas e campos naquele tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Mas Nabucodonosor, rei da Babilônia, havia dado ordem a Nabuzaradã, capitão da guarda, quanto a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Toma-o, olha por ele, e não lhe faças mal algum; mas faças com ele como ele te disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Então enviou Nabuzaradã capitão da guarda, e Nabusasbã, Rabsaris, e Nergal-Sarezer, e Rabmague, e todos os príncipes do rei da Babilônia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Enviaram, pois, e tomaram a Jeremias do pátio da guarda, e o entregaram a Gedalias filho de Aicã, filho de Safã, para que o levasse para casa; e ele ficou entre o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'E tinha vindo a palavra do SENHOR a Jeremias, enquanto ele estava preso no pátio da guarda, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Vai, e fala a Ebede-Meleque o cuxita, dizendo: Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que trarei minhas palavras sobre esta cidade para o mal, e não para o bem; e serão naquele dia perante tua presença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Porém naquele dia eu te livrarei, diz o SENHOR, e não serás entregue nas mãos dos homens a quem tu temes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Pois certamente te livrarei, e não cairás à espada, mas sim que terás tua alma como despojo, porque confiaste em mim, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Palavra que veio do SENHOR a Jeremias, depois que Nabuzaradã, capitão da guarda, o deixara ir de Ramá; quando o tomou, estando ele acorrentado com cadeias no meio de todos os presos de Jerusalém e de Judá que foram levados cativos à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Pois o capitão da guarda tomou a Jeremias, e lhe disse: O SENHOR teu Deus falou este mal contra este lugar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'E o SENHOR trouxe e fez o que havia falado; porque pecastes contra o SENHOR, e não obedecestes a sua voz, por isso vos aconteceu isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'E agora, eis que soltei hoje das cadeias que estavam sobre tuas mãos. Se parece bom aos teus olhos vir comigo à Babilônia, vem, e eu olharei por teu bem; mas se te parece mau aos teus olhos vir comigo a Babilônia, não o faça; olha, toda a terra está diante de ti; onde te parecer melhor e mais correto aos teus olhos ir, para ali vai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Mas antes de Jeremias ter se virado, o capitão lhe disse mais: Volta para Gedalias, filho de Aicã, filho de Safã, ao qual o rei da Babilônia pôs sobre todas as cidades de Judá, e habita com ele em meio do povo; ou vai aonde te parecer mais correto aos teus olhos ir. E deu-lhe alimento para o caminho, e um presente; e o despediu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Assim foi Jeremias a Gedalias filho de Aicã, a Mispá, e habitou com ele em meio do povo que tinha restado na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'E quando todos os príncipes do exércitos que estavam no campo, eles e seus homens, ouviram que o rei da Babilônia tinha posto a Gedalias filho de Aicã sobre a terra, e que tinha lhe encarregado dos homens, mulheres, e crianças, e os pobres da terra, os quais não foram levados em cativeiro à Babilônia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Vieram, pois, a Gedalias em Mispá. Eram eles: Ismael, filho de Netanias, Joanã e Jônatas, filhos de Careá, Seraías, filho de Tanumete, os filhos de Efai, o netofatita, e Jezanias, filho do maacatita; eles e seu homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'E Gedalias filho de Aicã, filho de Safã, jurou a eles e a seus homens, dizendo: Não temais servir aos caldeus; habitai na terra, e servi ao rei da Babilônia, e tereis bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'E eis que eu habito em Mispá, para estar diante dos caldeus que vierem a nós; e vós, colhei o vinho, os frutos do verão, e o azeite, e os ponde em vossos vasos, e habitai em vossas cidades que tomastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'E da mesma maneira todos os judeus que estavam em Moabe, e entre os filhos de Amom, e em Edom, e os que estavam em todas as terras, ouviram dizer que o rei da Babilônia tinha deixado alguns em Judá, e que tinha posto sobre eles a Gedalias filho de Aicã, filho de Safã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Todos estes judeus voltaram então de todas as partes para onde haviam sido lançados, e vieram à terra de Judá, a Gedalias em Mispá; e colheram vinho e muitos frutos de verão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'E Joanã filho de Careá, e todos os comandantes dos exércitos que estavam em campo, vieram a Gedalias em Mispá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'E lhe disseram: Com certeza tu sabes que Baalis, rei dos filhos de Amom, enviou a Ismael filho de Netanias, para te matar, não é verdade? Porém Gedalias filho de Aicã não creu neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Então Joanã filho de Careá falou a Gedalias em segredo, em Mispá, dizendo: Eu irei agora, e ferirei a Ismael filho de Netanias, e ninguém saberá; por que haveria ele de te matar, e todos os judeus que se ajuntaram a ti se dispersarem, e perecerem o restante de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Mas Gedalias filho de Aicã disse a Joanã filho de Careá: Não faças isto, pois o que tu dizes de Ismael é falso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Sucedeu, porém, no sétimo mês, que Ismael filho de Netanias, filho de Elisama, da semente real, veio com alguns capitães do rei, dez homens com ele, até Gedalias filho de Aicã em Mispá; e comeram pão juntos ali em Mispá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Então levantou-se Ismael filho de Netanias, e os dez homens que com ele estavam, e feriram à espada a Gedalias filho de Aicã, filho de Safã, matando assim a aquele a quem o rei da Babilônia tinha posto sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Assim também Ismael feriu a todos os judeus que estavam com ele, com Gedalias em Mispá, e aos soldados caldeus que ali se acharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Aconteceu, pois, no dia seguinte, depois que havia matado a Gedalias, quando ninguém sabia ainda,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Que vieram homens de Siquém, de Siló, e de Samaria, oitenta homens, tendo a barba raspada, e as roupas rasgadas, e tendo ferido seus próprios corpos; e traziam em suas mãos oferta de alimentos e incenso para levar à casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'E Ismael filho de Netanias saiu ao encontro deles desde Mispá, chorando; e sucedeu que, quando os encontrou, disse-lhes: Vinde a Gedalias, filho de Aicã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'E sucedeu que, quando eles chegaram ao meio da cidade, Ismael filho de Netanias os degolou, e os lançou no meio de um poço, ele e os homens que com ele estavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Mas entre aqueles se acharam dez homens que disseram a Ismael: Não nos mates; porque temos tesouros escondidos no campo, de trigos, e cevada, azeite, e mel. E ele os deixou, e não os matou entre seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'E o poço em que Ismael lançou todos os cadáveres dos homens que feriu por causa de Gedalias, era o mesmo que o rei Asa havia feito por causa de Baasa, rei de Israel. A este Ismael, filho de Netanias, encheu de mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Depois Ismael levou cativo a todo o resto do povo que estava em Mispá; às filhas do rei, e a todo o povo que em Mispá tinha restado, o qual tinha Nabuzaradã capitão da guarda havia encarregado a Gedalias filho de Aicã. Então Ismael os levou cativos, e foi embora, para passar aos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'E quando Joanã filho de Careá, e todos os comandantes dos exércitos que estavam com ele, ouviram todo o mal que Ismael filho de Netanias tinha feito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Tomaram a todos os homens, e foram lutar contra Ismael filho de Netanias; e o acharam junto às muitas águas que ficam em Gibeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'E aconteceu que, quando todo o povo que estava com Ismael viu a Joanã filho de Careá, e a todos os comandantes dos exércitos que estavam com ele, alegraram-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'E todo o povo que Ismael tinha levado cativo de Mispá, viraram-se, e se voltaram, e foram a Joanã filho de Careá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Porém Ismael filho de Netanias escapou com oito homens diante de Joanã, e se foi aos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Então Joanã filho de Careá, e todos os comandantes dos exércitos que com ele estavam, tomaram todo o resto do povo que tinham trazido de volta de Ismael filho de Netanias, de Mispá, depois dele ter ferido a Gedalias filho de Aicã: homens valentes de guerra, mulheres, e crianças; e os eunucos, que tinha trazido de volta de Gibeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'E foram, e habitaram em Gerute-Quimã, que é perto de Belém, a fim de saírem dali para entrarem no Egito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Por causa dos caldeus; pois eles temiam por Ismael filho de Netanias ter ferido a Gedalias filho de Aicã, ao qual o rei de Babilônia tinha posto sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Então chegaram todos os comandantes dos exércitos, e Joanã filho de Careá, e Jezanias filho de Hosaías, e todo o povo desde o menor até o maior,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'E disseram ao profeta Jeremias: Chegue, por favor, nossa suplicação diante de ti, e roga por nós ao SENHOR teu Deus, por todo este restante; pois de muitos restamos apenas uns poucos, como teus olhos nos veem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Para que o SENHOR teu Deus nos ensine caminho por onde devemos andar, e o que temos de fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'E Jeremias profeta lhes disse: Eu ouvi. Eis que orarei ao SENHOR vosso Deus, conforme vossas palavras; e será que toda palavra que o SENHOR vos responder, eu vos anunciarei; não vos esconderei palavra alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Então eles disseram a Jeremias: O SENHOR seja entre nós testemunha da verdade e da fidelidade, se não fizermos conforme a toda palavra com que o SENHOR teu Deus te enviar a nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Seja bem ou seja mal, obedeceremos à voz do SENHOR nosso Deus, ao qual te enviamos; para que, obedecendo à voz do SENHOR nosso Deus, tenhamos bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'E aconteceu que ao fim de dez dias veio a palavra do SENHOR a Jeremias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Então ele chamou a Joanã filho de Careá, e a todos os comandantes dos exércitos que com ele estavam, e a todo o povo desde o menor até o maior;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'E disse-lhes: Assim diz o SENHOR Deus de Israel, ao qual me enviastes para que eu apresentasse vossa suplicação diante de sua presença:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Se ficardes nesta terra, então eu vos edificarei, e não vos destruirei; eu vos plantarei, e não vos arrancarei; pois ressentido estou do mal que tenho vos feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Não temais ao rei da Babilônia, do qual tendes medo; não o temais, diz o SENHOR, pois eu estou convosco para vos salvar e vos livrar de sua mão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'E vos concederei misericórdia, de modo que ele tenha misericórdia de vós, e vos faça voltar a vossa terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Mas se disserdes: Não ficaremos nesta terra, desobedecendo à voz do SENHOR vosso Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'E dizendo: Não, em vez disso iremos à terra do Egito, na qual não veremos guerra, nem ouviremos som de trombeta, nem teremos fome de pão, e ali ficaremos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Então assim ouvi a palavra do SENHOR, ó restantes de Judá; assim diz o SENHOR dos exércitos, Deus de Israel: Se dirigirdes vossos rostos para entrar no Egito, e irdes para peregrinar ali,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Será que a espada que vós temeis, ali ela vos tomará na terra do Egito, e a fome que vos deixa preocupados, ali no Egito ela vos pegará; e ali morrereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Assim será com todos os homens que dirigirem seus rostos para irem ao Egito, para ali peregrinar: morrerão pela espada, pela fome, e pela pestilência; não haverá um deles sequer que reste vivo, nem que escape do mal que eu trarei sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Tal como se derramou minha ira e minha indignação sobre os moradores de Jerusalém, assim também se derramará minha indignação sobre vós, quando entrardes no Egito; e servireis de maldição e de espanto; de amaldiçoamento e de humilhação; e não vereis mais a este lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'O SENHOR já falou quanto vós, ó restantes de Judá: Não entreis no Egito; Tende certeza de que eu vos advirto hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Porque levais vossas próprias almas ao erro; pois vós me enviastes ao SENHOR vosso Deus, dizendo: Ora por nós ao SENHOR nosso Deus; e conforme a tudo quanto o SENHOR nosso Deus disser, assim nos faz saber, e o faremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'E eu já vos fiz saber hoje, porém não destes ouvidos à voz do SENHOR vosso Deus, nem a tudo pelo que ele me enviou a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Agora, portanto, tende certeza de que pela espada, pela fome, e pela pestilência, morrereis no lugar onde desejastes entrar para ali peregrinardes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'E sucedeu que, quando Jeremias acabou de falar a todo o povo todas as palavras do SENHOR Deus deles, pelas quais o SENHOR Deus deles tinha o enviado a eles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Então Azarias filho de Hosaías, e Joanã filho de Careá, e todos os homens arrogantes disseram a Jeremias: Tu falas mentira! O SENHOR nosso Deus não te enviou para dizer: Não entreis em Egito para ali peregrinar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Mas é Baruque filho de Nerias que te incita contra nós, para nos entregar nas mãos dos caldeus, para nos matar ou nos fazer transportar cativos à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Assim Joanã filho de Careá, e todos os comandantes dos exércitos, e todo o povo, não obedeceram à voz do SENHOR para ficarem na terra de Judá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Em vez disse, Joanã filho de Careá, e todos os comandantes dos exércitos, tomaram a todo o restante de Judá, que tinham voltado de todas as nações para onde haviam sido lançados, para morarem na terra de Judá:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Homens, mulheres, crianças, as filhas do rei, e a toda alma que Nabuzaradã capitão da guarda tinha deixado com Gedalias filho de Aicã filho de Safã, e também ao profeta Jeremias, e a Baruque filho de Nerias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'E vieram à terra do Egito, porque não obedeceram à voz do SENHOR; e chegaram até Tafnes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Então veio a palavra do SENHOR a Jeremias em Tafnes, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Toma em tua mão pedras grandes, e as esconde entre o barro no forno que está à porta da casa de Faraó em Tafnes, diante dos olhos de homens judeus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'E dize-lhes: Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que eu enviarei, e tomarei a Nabucodonosor rei da Babilônia, meu servo, e porei seu trono sobre estas pedras que escondi; e ele estenderá sua tenda real sobre elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'E ele virá, e ferirá a terra do Egito: os que estão condenados para a morte, à morte; os que para o cativeiro, ao cativeiro, e os que para a espada, à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'E acenderei fogo às casas dos deuses do Egito; e ele as queimará, e os levará cativos; e ele se vestirá da terra do Egito, tal como o pastor se veste de sua capa; e ele sairá de lá em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'E quebrará as estátuas de Bete-Semes, que fica na terra do Egito, e queimará a fogo as casas dos deuses do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Palavra que veio a Jeremias quanto a todos os judeus habitantes na terra do Egito, que moravam em Migdol, Tafnes, Nofe, e na terra de Patros, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Vós vistes todo o mal que eu trouxe sobre Jerusalém e sobre todas as cidades de Judá; e eis que hoje elas estão desoladas, e ninguém nelas habita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Por causa da maldade deles, que fizeram para me irritar, indo oferecer incenso, e servindo a outros deuses que nunca conheceram, nem eles, nem vós, nem vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'E enviei até vós todos os meus servos, os profetas, persistindo em enviá-los, dizendo: Não façais, pois, esta coisa abominável, e eu odeio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Porém não obedeceram, nem inclinaram seus ouvidos para se converterem de sua maldade, para não oferecer incenso a outros deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Por isso se derramou minha indignação e minha ira, e acendeu-se nas cidades de Judá e nas ruas de Jerusalém, e tornaram-se em desolação e em destruição tal como está hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Agora pois, assim diz o SENHOR dos exércitos, Deus de Israel: Por que fazeis tão grande mal contra vossas almas, para serdes eliminados homem e mulher, criança e bebê de peito, do meio de Judá, sem que vos sobre um restante sequer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Irritando-me com as obras de vossas mãos, oferecendo incenso a outros deuses na terra do Egito, para onde entrastes para morar; de modo que sereis eliminados, e servireis de maldição e de humilhação entre todas as nações da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Por acaso já vos esquecestes das maldades de vossos pais, das maldades dos reis de Judá, das maldades de suas mulheres, e das vossas próprias maldades, e das maldades de vossas mulheres, que foram feitas na terra de Judá e nas ruas de Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Até hoje não se contristaram, nem temeram, nem andaram em minha lei, nem em meus estatutos que pus diante de vós e diante de vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Portanto assim diz o SENHOR dos exércitos, Deus de Israel: Eis que eu dirijo meu rosto a vós para o mal, e para destruir a todo Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'E tomarei os restantes de Judá que dirigiram seus rostos para entrarem na terra do Egito para ali morar, e na terra do Egito serão todos consumidos; cairão a espada, e serão consumidos pela fome; desde o menor até o maior, pela espada e pela fome morrerão. E servirão de maldição e de espanto; de amaldiçoamento e de humilhação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Pois castigarei aos que moram na terra do Egito, tal como castiguei a Jerusalém, com espada, fome e pestilência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'De maneira que, dos restantes de Judá que entraram na terra do Egito para morar ali, não haverá quem escape, nem quem reste vivo, para voltar à terra de Judá, da qual eles anseiam para voltar a habitar lá; pois não voltarão, a não ser alguns fugitivos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Então todos os homens que sabiam que suas mulheres haviam oferecido incenso a outros deuses, e todas as mulheres que estavam presentes, uma grande multidão, e todo o povo que habitava na terra do Egito, em Patros, responderam a Jeremias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Quanto a palavra que tu nos falaste em nome do SENHOR, não daremos ouvidos a ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Em vez disso certamente faremos toda a palavra que saiu de nossa boca, para oferecer incenso à rainha dos céus, e para lhe apresentar ofertas de bebidas, tal como temos feito, nós e nossos pais, nossos reis e nossos príncipes, nas cidades de Judá, e nas ruas de Jerusalém, quando nos fartávamos de pão, vivíamos bem, e não víamos calamidade alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Mas desde que cessamos de oferecer incenso à rainha do céus, e de derramar ofertas de bebidas, tivemos falta de tudo, e fomos consumidos pela espada e pela fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'E quando oferecemos incenso à rainha do céus, e lhe derramamos ofertas de bebidas, por acaso nós lhe fizemos bolos para lhe prestar culto, e lhe derramamos ofertas de bebidas, sem nossos maridos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Então Jeremias disse a todo o povo, aos homens e às mulheres, e a todo o povo que lhe tinha respondido isto, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Por acaso não se lembrou o SENHOR, e não veio a sua mente o incenso que oferecestes nas cidades de Judá, e nas praças de Jerusalém, vós e vossos pais, vossos reis e vossos príncipes, e o povo da terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'De tal maneira que o SENHOR não podia mais aguentar, por causa da maldade de vossas ações, por causa das abominações que fizestes; por isso vossa terra se tornou em desolação, em espanto, e em maldição, até não restar morador, tal como hoje está.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Pois oferecestes incenso e pecastes contra o SENHOR, e não obedecestes à voz do SENHOR, nem andastes em seu lei, seus estatutos, e seus testemunhos; por isso veio sobre vós este mal, tal como há hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Disse mais Jeremias a todo o povo, e a todas as mulheres: Ouvi a palavra do SENHOR, todos vós de Judá, que estais na terra do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Assim diz o SENHOR dos exércitos, Deus de Israel, dizendo: Vós e vossas mulheres não somente falastes por vossas bocas, mas também com vossas mãos o cumpristes, dizendo: Certamente faremos nossos votos que fizemos, de oferecer incensos à rainha dos céus, e lhe apresentar ofertas de bebidas; Com certeza confirmastes vossos votos, e com certeza cumpristes vossos votos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Portanto ouvi a palavra do SENHOR, todos vós de Judá que habitais na terra do Egito: Eis que juro por meu grande nome, diz o SENHOR, que nunca mais meu nome será chamado pela boca homem algum de Judá, em toda a terra do Egito, dizendo: Vive o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Eis que eu os observarei para o mal, e não para o bem; e todos os homens de Judá que estão na terra do Egito serão consumidos pela espada e pela fome, até que se acabem por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'E os que escaparem do espada voltarão da terra do Egito para a terra de Judá, poucos em número; e todo o restante de Judá, que entrou em Egito para ali morar, saberá qual palavra se confirmará, se a minha ou a sua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'E isto tereis por sinal, diz o SENHOR, de que neste lugar eu vos castigo, para que saibais que certamente minhas palavras se confirmarão contra vós para o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Assim diz o SENHOR: Eis que eu entregarei ao Faraó Ofra, rei do Egito, nas mãos de seus inimigos, e nas mão dos que buscam sua morte, assim como entreguei a Zedequias rei de Judá nas mãos de Nabucodonosor rei de Babilônia, seu inimigo, e que buscava sua morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Palavra que o profeta Jeremias falou a Baruque filho de Nerias, quando ele escrevia num livro aquelas palavras da boca de Jeremias, no quinto ano de Jeoaquim filho de Josias, rei de Judá, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Assim diz o SENHOR Deus de Israel, quanto a ti, Baruque:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Tu disseste: Ai de mim agora! Pois o SENHOR me acrescentou tristeza sobre minha dor; já estou cansado de meu gemido, e não acho descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Assim lhe dirás: Assim diz o SENHOR: Eis que o que edifiquei eu destruo; e o que plantei eu arranco, até toda esta terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'E tu buscarias para ti grandezas? Não as busques; porque eis que eu trago o mal sobre toda carne, diz o SENHOR, mas conservarei tua vida em todos os lugares para onde fores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Palavra do SENHOR que veio ao profeta Jeremias, contra as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Quanto ao Egito: contra o exército de Faraó Neco, rei do Egito, que estava junto ao rio Eufrates em Carquemis, ao qual Nabucodonosor rei da Babilônia feriu no quarto ano de Jeoaquim filho de Josias, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Preparai os escudos maior e o menor, e vinde à guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Selai os cavalos, e subi, vós os cavaleiros, e apresentai-vos com capacetes; limpai as lanças, vesti-vos de couraças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Por que razão vejo os medrosos tornando atrás? E seus guerreiros são abatidos, e vão fugindo, sem olharem para trás; o terror está por todos os lados,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Não fuja o ligeiro, nem escape o guerreiro; para o norte, junto à margem do rio do Eufrates, tropeçaram e caíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Quem é este que sobe como o Nilo, cujas águas se movem como rios?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'O Egito vem subindo como o Nilo, e suas águas se agitam como rios, e disse: Subirei, e cobrirei a terra; destruirei a cidade, e os que nela habitam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Subi, cavalos, e rangei, carruagens; e saiam os guerreiros; os de Cuxe e os de Pute que tomam escudo, e os de Lude que tomam e encurvam o arco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Porém esse dia pertence ao Senhor DEUS dos exércitos, o dia de vingança, para ele se vingar de seus adversários; e a espada devorará, se fartará, e se embriagará do sangue deles; pois o Senhor DEUS dos exércitos tem para si um sacrifício na terra do norte, junto ao rio Eufrates.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Sobe a Gileade, e toma bálsamo, ó virgem filha do Egito; em vão multiplicas os remédios, pois não há cura para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'As nações ouviram da tua vergonha, e teu clamor encheu a terra: pois um guerreiro tropeçou contra outro guerreiro, e ambos juntamente caíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Palavra que o SENHOR falou ao profeta Jeremias quanto à vinda de Nabucodonosor, rei da Babilônia, para ferir a terra do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Anunciai no Egito, e declarai em Migdol; declarai também em Nofe e em Tafnes; dizei: Firma uma posição, e prepara-te; pois a espada está para devorar o que há ao redor de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Por que teus guerreiros foram derrubados? Não puderam ficar de pé, pois o SENHOR os empurrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Ele multiplicou os que tropeçaram; caíram cada um sobre o outro, e disseram: Levanta-te e voltemo-nos a nosso povo, e à terra de nosso nascimento, por causa da espada opressora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Ali gritarão: O Faraó rei do Egito, é apenas um barulho; ele deixou passar o tempo determinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Vivo eu, diz o Rei, cujo nome é EU-SOU dos exércitos, que como o Tabor entre os montes, e como o Carmelo no mar, assim ele virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Faz para ti a bagagem para a ida ao cativeiro, ó moradora, filha do Egito; porque Nofe se tornará em desolação, e será devastada até não haver ali morador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'O Egito é uma bezerra formosa; mas a mosca carniceira vem do norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Até seus soldados mercenários em meio dela são como bezerros cevados; porém também eles se virarão para trás, e juntamente fugirão; eles não permanecerão em postos, porque o dia de sua ruína, o tempo de sua punição, veio sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Seu ruído sairá como de serpente; pois seus inimigos virão com poder; a ela virão com machados, como se fossem cortadores de lenha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Cortarão o seu bosque,diz o SENHOR, ainda que não possam ser contados; porque são mais que gafanhotos, não se pode enumerá- los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'A filha do Egito será envergonhada; entregue será nas mãos do povo do norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Diz o SENHOR dos exércitos, Deus de Israel: Eis que eu punirei a Amom de Nô, a Faraó e ao Egito; a seus deuses e a seus reis; tanto a Faraó como aos que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'E os entregarei nas mãos dos que buscam tirar sua vida, e nas mãos de Nabucodonosor rei de Babilônia, e nas mãos de seus servos; porém depois será habitada como nos dias anteriores,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Mas tu não temas, meu servo Jacó, nem te espantes, ó Israel; porque eis que te salvarei desde as terras de longe, e teus descendentes da terra de seu cativeiro. E Jacó voltará, descansará, e viverá em paz; e não haverá quem o atemorize.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Tu, meu servo Jacó, não temas,diz o SENHOR; pois eu estou contigo; porque destruirei por completo todas as nações entre as quais eu te lancei; porem a ti não destruirei por completo, mas te castigarei com moderação, e não te deixarei impune.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Palavra do SENHOR que veio ao profeta Jeremias sobre os filisteus, antes que Faraó ferisse a Gaza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Assim diz o SENHOR: Eis que águas sobem do norte, e se tornarão em correnteza transbordante, e inundarão a terra e sua plenitude, as cidades, e moradores delas; os homens gritarão, e todos os moradores da terra uivarão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Ao ruído dos cascos de seus fortes cavalos,o tremor de suas caruagens, e o estrondo de suas rodas; os pais não olharão para os filhos por causa da fraqueza das mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Por causa do dia que vem, para arruinar a todos os filisteus, para cortar a Tiro e a Sidom todo ajudador que restar; pois o SENHOR destruirá aos filisteus, ao resto da ilha de Caftor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Veio calvície sobre Gaza; Ascalom e o resto de seu vale foram cortados fora. Até quando te ferirás com arranhões?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ah, espada do SENHOR! Até quando não te aquietarás? Volta-te em tua bainha, descansa, e aquieta-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Como te aquietarias? Pois o SENHOR lhe deu mandado contra Ascalom, e contra o litoral, e ali ele a ordenou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Sobre Moabe.Assim diz o SENHOR dos exércitos, Deus de Israel: Ai de Nebo! Pois foi arruinada; envergonhada está Quiriataim, já foi tomada; Misgabe está envergonhada e espantada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Já não há mais exaltação em Moabe; em Hesbom tramaram o mal contra ela, dizendo: Vinde, e a eliminemos das nações. Também tu, Madmém, serás cortada fora; a espada irá atrás de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Ouve-se uma voz de clamor de Horonaim: Ruína e grande destruição!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moabe foi destruída; fizeram com que se ouvisse o grito de seus pequenos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Pois na subida de Luíte subirão com grande choro; pois na descida de Horonaim os inimigos de Moabe ouviram clamor de destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fugi, livrai vossa vida, e sereis como um arbusto no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Pois por causa de tua confiança confiaste em tuas obras e em teus tesouros, tu também serás tomada; e Quemos irá ao cativeiro, seus sacerdotes e juntamente seus príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Pois virá o destruidor a cada uma das cidades, e nenhuma cidade escapará; e perecerá também o vale, e será destruída a planície,pois assim diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Dai asas a Moabe, para que ele saia voando; pois suas cidades se tornarão desertas até não restar quem more nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Maldito aquele que fizer enganosamente a obra do SENHOR, e maldito aquele que detiver sua espada do sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Tranquilo esteve Moabe desde sua juventude, e sobre suas impurezas esteve quieto; e não foi esvaziado de vaso em vaso, nem nunca foi ao cativeiro; por isso seu sabor ficou nele, e seu cheiro não mudou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Por isso eis que vêm dias, diz o SENHOR, em que eu lhe enviarei derramadores que o derramarão; e esvaziarão seus vasos, e romperão seus jarros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'E Moabe se envergonhará de Quemos, assim como a casa de Israel se envergonhou de Betel, que era sua confiança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Como direis: Somos guerreiros, homens valentes para a guerra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moabe é destruído, e suas cidades invadidas, e seus melhores rapazes descem ao degoladouro, diz o rei, cujo nome é EU-SOU dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Próxima está a vinda da perdição de Moabe; e seu desastre vem com muita pressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Condoei-vos dele todos vós que estais ao seu redor, e todos vós que sabeis seu nome. Dizei: Como se quebrou a vara forte, o belo cajado!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Desce da tua glória, e senta-te no lugar seco, ó moradora, filha de Dibom; pois o destruidor de Moabe subiu contra ti, e arruinou tuas fortalezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Para-te no caminho, e olha, ó moradora de Aroer; pergunta ao que vai fugindo, e à que escapou, dize: O que aconteceu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Responderão: Moabe está envergonhado, porque foi quebrantado; uivai e gritai; anunciai em Arnom que Moabe foi destruído,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'O julgamento também veio juízo sobre a terra da planície: sobre Holom, sobre Jazá, e sobre Mefate;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Sobre Dibom, sobre Nebo, e sobre Bete-Diblataim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Sobre Quiriataim, sobre Bete-Gamul, e sobre Bete-Meom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Sobre Queriote, sobre Bosra, e sobre todas as cidades da terra de Moabe, as de longe e as de perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'O poder de Moabe foi cortado, e seu braço quebrado,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Embriagai-o, pois contra o SENHOR se engrandeceu; e Moabe se revolverá sobre seu vômito, e ele também será por escárnio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Pois para ti não foi Israel por escárnio? Por acaso ele foi achado entre ladrões, para que balances a cabeça quando falas dele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Deixai as cidades, e habitai em rochedos, ó moradores de Moabe; e sejais como a pomba que faz ninho nas brechas da boca da caverna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Temos ouvido a soberba de Moabe, que é soberbo demais, assim como sua arrogância e seu orgulho, sua altivez e a altura de seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Eu conheço sua insolência,diz o SENHOR; porém não será assim; suas mentiras lhe serão em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Por isso eu uivarei por Moabe, e gritarei por todo Moabe; gemerão por causa dos homens de Quir-Heres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Com o choro de Jazer chorarei por ti, ó vide de Sibma; teus sarmentos passaram o mar, e chegaram até o mar de Jazer; porém o destruidor veio sobre os frutos de teu verão, e sobre tua vindima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Assim foram tirados a alegria e o regozijo dos campos férteis, e da terra de Moabe: pois fiz cessar o vinho dos lagares; já não pisarão uvas com júbilo; o grito não será de júbilo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Houve um grito desde Hesbom até Eleale e até Jaaz; deram sua voz desde Zoar até Horonaim e Eglate-Selísia; pois também as águas de Ninrim serão assoladas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'E eu,diz o SENHOR, farei cessar de Moabe quem sacrifique no lugar alto, e quem ofereça incenso a seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Portanto meu coração ressoará como flautas por causa de Moab; também meu coração ressoará como flautas pelos homens de Quir-Heres; pois as riquezas que tinham acumulado se perderam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Pois em toda cabeça haverá calva, e toda barba será cortada; sobre todas mãos há arranhões, e sobre todos os lombos há sacos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Sobre todas os terraços de Moabe e em suas ruas, em todo ele haverá pranto; pois eu quebrantei a Moabe como a um vaso desagradável,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Como foi quebrantado! Como uivam! Como Moabe virou as costas, e se envergonhou! Assim Moabe servirá de escárnio e de espanto a todos os que estão ao seu redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Pois assim diz o SENHOR: Eis que voará como águia, e estenderá suas asas sobre Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Tomadas são as cidades, e invadidas são as fortalezas; e o coração dos guerreiros de Moabe naquele dia será como o coração de mulher em dores de parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'E Moabe será destruído de modo que deixará de ser povo, pois se engrandeceu contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Medo, cova, e laço vem sobre ti, ó morador de Moabe,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'O que fugir do medo, cairá na cova; e o que subir da cova, ficará preso do laço; porque eu trarei sobre ele, sobre Moabe, o ano de sua punição,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Os que fugiam da força, paravam à sombra de Hesbom; porém fogo saiu de Hesbom, e labareda do meio de Seom, e queimou a testa de Moabe, e o topo da cabeça dos filhos do tumulto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Ai de ti, Moabe! Pereceu o povo de Quemos; pois teus filhos foram levados cativos, e tuas filhas foram em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Porém restaurarei Moabe de seu infortúnio nos últimos dias, diz o SENHOR. Até aqui é o julgamento de Moabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Sobre os filhos de Amom.Assim diz o SENHOR: Por acaso Israel não tem filhos, nem tem herdeiro? Por que, pois, Malcã tomou posse de Gade, e seu povo habitou em suas cidades?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Portanto eis que vêm dias,diz o SENHOR, em que farei ouvir em Rabá dos filhos de Amom clamor de guerra; e se tornará em um amontoado de ruínas, e suas vilas serão queimadas a fogo; e Israel tomará posse daqueles que tinham lhes tomado, disse o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Uiva, ó Hesbom, porque Ai é destruída; clamai, ó filhas de Rabá, vesti-vos de sacos, lamentai, e rodeai pelas cercas, porque Malcã irá em cativeiro, seus sacerdotes e juntamente seus príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Por que te orgulhas dos vales? Teu vale se desfez, ó filha rebelde, que confia em seus tesouros, dizendo: Quem virá contra mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Eis que trago medo sobre ti,diz o Senhor o SENHOR dos exércitos, de todos os que estão ao redor de ti; e sereis forçados a fugir, cada um por si, e não haverá quem consiga reunir os que andam sem rumo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Mas depois disso restaurarei os filhos de Amom de seu infortúnio, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Sobre Edom.Assim diz o SENHOR dos exércitos: Por acaso não há mais sabedoria em Temã? Pereceu o conselho dos prudentes? Estragou-se sua sabedoria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fugi, voltai-vos, escondei-vos em profundezas para habitar, ó moradores de Dedã; porque trarei sobre ele a calamidade de Esaú no tempo em que eu o punir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Se recolhedores de uva viessem contra ti, por acaso não deixarão sobras? Se ladrões de noite viessem não te danificariam apenas o que achassem suficiente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Mas eu despirei a Esaú, descobrirei seus esconderijos, e não poderá se esconder; será destruída sua descendência, e também seus irmãos e seus vizinhos; e deixará de existir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Deixa teus órfãos, eu os criarei; e em mim confiarão tuas viúvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Pois assim diz o SENHOR: Eis que os que não estavam condenados a beberem do cálice, certamente o beberão; e ficarias tu impune por completo? Não ficarás impune, e certamente beberás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Pois jurei por mim mesmo,diz o SENHOR, que Bozra se tornará em espanto, humilhação, deserto e maldição; e todas as suas cidades se tornarão desolações perpétuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Ouvi uma notícia do SENHOR que um mensageiro foi às nações, para dizer: Juntai-vos, e vinde contra ela, e levantai-vos para a guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Porque eis te fiz pequeno entre as nações, desprezado entre os homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'O terror que tu causas te enganou, assim como a arrogância de teu coração; tu que habitas nas cavernas das rochas, que tens a altura dos montes; ainda que levantes teu ninho como a águia, de lá eu te derrubarei,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Assim Edom servirá de espanto; todo aquele que passar por ela se espantará, e assoviará por causa de todas as suas pragas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Tal como a destruição de Sodoma e de Gomorra, e de suas cidades vizinhas,diz o SENHOR, ninguém habitará ali, nem filho de homem morará nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Eis que será como o leão que sobe da mata do Jordão contra a morada do forte; porque repentinamente o farei correr dela, e ordenarei contra ela a quem eu escolher; pois quem é semelhante a mim? E quem manda em mim? E quem é o pastor que pode subsistir diante de mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Portanto ouvi o conselho do SENHOR, que ele determinou sobre Edom; e seus pensamentos, que decidiu sobre os moradores de Temã: Certamente os menores do rebanho os arrastarão, e destruirão suas moradas com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'A terra treme do estrondo da queda deles; e o grito de sua voz foi ouvida até no mar Vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Eis que como águia subirá e voará, e estenderá suas asas sobre Bozra; e o coração dos guerreiros de Edom será naquele dia como o coração de mulher em dores de parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Sobre Damasco. Envergonharam-se Hamate e Arpade, porque ouviram más notícias; derreteram-se em mar de angústia, não podem se sossegar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Enfraquecida está Damasco; virou-se para fugir, e foi tomada de medo; angústia e dores a tomaram, como de mulher que está de parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Como não foi abandonada a famosa cidade, a cidade de minha alegria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Por isso seus rapazes cairão em suas ruas, e todos os homens de guerra serão mortos naquele dia,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'E acenderei fogo no muro de Damasco, que consumirá as casas de Ben-Hadade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Sobre Quedar e dos reinos de Hazor, os quais Nabucodonosor, rei da Babilônia, feriu.Assim diz o SENHOR: Levantai-vos, subi contra Quedar, e destruí os filhos de oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Tomarão suas tendas e seu gados; suas cortinas, e todos os seus vasos; e seus camelos, levarão para si; e lhes gritarão: O medo está ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fugi, afastai-vos para muito longe, buscai profundezas para habitar, ó moradores de Hazor, diz o SENHOR; porque Nabucodonosor, rei da Babilônia, tomou conselho contra vós, e pensou um plano contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Levantai-vos, subi contra uma nação tranquila, que habita em segurança,diz o SENHOR, que nem têm portas nem ferrolhos, que vivem sozinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'E seus serão camelos para presa, e a multidão de seus gados para despojo; e os espalharei por todos os lados, até os cantos mais distantes; e por todos os lados lhes trarei sua ruína,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'E Hazor se tornará uma morada de chacais, desolada para sempre; ninguém habitará ali, nem filho de homem morará nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Palavra do SENHOR que veio ao profeta Jeremias, sobre Elão, no princípio do reinado de Zedequias rei de Judá, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Assim diz o SENHOR dos exércitos: Eis que quebrarei o arco de Elão, o principal de seu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'E trarei sobre Elão os quatro ventos dos quatro cantos do céu, e os espalharei por todos estes ventos; não haverá nação para onde não venham exilados de Elão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'E farei com que Elão tenha medo diante de seus inimigos, e diante dos que buscam tirar sua vida; e trarei o mal sobre eles, o furor de minha ira,diz o SENHOR; e mandarei a espada atrás deles, até que os acabe por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'E porei meu trono em Elão, e destruirei dali o rei e os príncipes,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Mas será nos últimos dias, que restaurarei Elão de seu infortúnio, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Palavra que o SENHOR falou sobre a Babilônia, sobre a terra dos caldeus, por meio do profeta Jeremias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Anunciai entre as nações, declarai, e levantai bandeira; declarai, e não encubrais: dizei: Tomada é Babilônia, Bel é envergonhado, Merodaque é despedaçado; envergonhados são seus ídolos, despedaçados estão suas imagens de idolatria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Pois subiu contra ela uma nação do norte, a qual tornará sua terra em desolação, e não haverá morador nela; desde os homens até os animais fugiram e se afastaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Naqueles dias e naquele tempo,diz o SENHOR, os filhos de Israel virão, eles e juntamente os filhos de Judá; virão andando e chorando, e buscarão ao SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Perguntarão por Sião, pelo caminho para onde voltarão seus rostos, dizendo: Vinde, e juntai-vos ao SENHOR com um pacto eterno, que jamais será esquecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Meu povo tem sido ovelhas perdidas; seus pastores as fizeram errar, pelos montes as desviaram; andaram de monte em morro, esqueceram-se de seu lugar de descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Todos quantos as achavam, as comiam; e adversários diziam: Nenhuma culpa teremos, pois pecaram contra o SENHOR, a morada da justiça contra o SENHOR, a esperança de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Fugi do meio da Babilônia, e saí da terra dos caldeus; e sede como os bodes adiante do rebanho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Porque eis que eu levantarei e farei subir contra a Babilônia um ajuntamento de grandes povos da terra do norte; e se prepararão contra ela, e dali será tomada; suas flechas serão como de um habilidoso guerreiro, que não voltarão em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'E a Caldeia será objeto de saque; todos os que a saquearem serão fartos,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Visto que vós vos alegrastes, que vos enchestes de prazer, vós saqueadores de minha propriedade; visto que vos inchastes como bezerra gorda, e relinchastes como cavalos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Por isso vossa mãe será muito envergonhada, será humilhada a que vos gerou; eis que ela será a última das nações: deserto, secura, e desolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Por causa da ira do SENHOR não será habitada; ela, porém será totalmente desolada; qualquer um passar pela Babilônia se espantará e assoviará por causa de todas as suas pragas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Preparai-vos em linha de batalha contra Babilônia ao redor, todos vós que armais arcos; atirai contra ela, não poupeis as flechas; pois ela pecou contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Gritai contra ela ao redor, pois já se rendeu; caíram seus fundamentos, derrubados são seus muros, pois esta é vingança do SENHOR. Vingai-vos dela; fazei com ela assim como ela fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Exterminai da Babilônia o semeador, e o que usa a foice no tempo da ceifa; por causa da espada opressora, cada um se voltará ao seu povo, cada um fugirá para sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel é um cordeiro desgarrado, que leões afugentaram; o rei da Assíria foi o primeiro que o devorou; e este, Nabucodonosor rei da Babilônia, o último, que lhe quebrou os ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Portanto assim diz o SENHOR dos exércitos, Deus de Israel: Eis que punirei ao rei de Babilônia e a sua terra assim como puni ao rei da Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'E voltarei a trazer Israel à sua morada, no Carmelo e em Basã se alimentará; nos montes de Efraim e de Gileade sua alma farta será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Naqueles dias e naquele tempo,diz o SENHOR, a maldade de Israel será buscada, mas não será encontrada; e buscados os pecados de Judá, mas não se acharão; porque perdoarei aos restantes que eu deixar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Sobe contra ela, a terra de Merataim, e contra os moradores de Pecode; assola e destrói por completo atrás deles,diz o SENHOR, e faze conforme a tudo o que te mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Há barulho de guerra na terra, e de grande destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Como foi cortado e quebrado o martelo de toda a terra! Como Babilônia se tornou em espanto entre as nações!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Pus armadilha para ti, e também foste capturada, ó Babilônia, antes de tu perceberes; foste achada, e também presa, porque lutaste contra o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'O SENHOR abriu o teu arsenal, e tirou os instrumentos de sua ira; porque esta é a obra do Senhor DEUS dos exércitos, na terra dos caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Vinde contra ela desde o lugar mais distante; abri seus celeiros; tornai-a em amontoados, e destruí-a por completo; que nada reste dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Matai à espada todos os seus novilhos; que ela desça ao matadouro. Ai deles! Porque veio o seu dia, o tempo de sua punição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Eis a voz dos que fugiram e escaparam da terra de Babilônia, para anunciar em Sião a vingança do SENHOR nosso Deus, a vingança de seu templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Convocai contra a Babilônia os flecheiros, todos os que armam arcos; assentai o acampamento ao redor dela; ninguém escape dela, pagai-lhe conforme sua obra; conforme tudo o que ela fez, fazei-lhe; porque agiu arrogantemente contra o SENHOR, contra o Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Portanto seus rapazes cairão em suas ruas; e todos os seus homens de guerra serão exterminados naquele dia,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Eis que eu contra ti, ó soberbo,diz o Senhor DEUS dos exércitos; porque veio o teu dia, o tempo em que te castigarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'E o soberbo tropeçará e cairá, e ninguém haverá que o levante; e acenderei fogo em suas cidades, que consumirá todos os seus arredores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Assim diz o SENHOR dos exércitos: Os filhos de Israel e os filhos de Judá juntamente foram oprimidos; e todos os que os tomaram cativos os detiveram; recusaram-se soltá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Porém o Redentor deles é forte; EU-SOU dos exércitos é o seu nome; certamente defenderá a causa deles, para dar descanso à terra, e incomodar os moradores da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Espada virá sobre os caldeus, diz o SENHOR, e sobre os moradores da Babilônia, sobre seus príncipes, e sobre seus sábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Espada virá sobre os adivinhos, e se tornarão tolos; espada virá sobre seus guerreiros, e perderão as forças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Espada virá sobre seus cavalos, sobre seus carros, e sobre todo os estrangeiros que estão no meio dela, e serão como mulheres; espada virá sobre seus tesouros, e serão saqueados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Sequidão virá sobre suas águas, e se secarão; pois é terra de idolatrias, e se enlouquecem por seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Por isso nela habitarão animais selvagens do deserto com hienas; habitarão também nela filhotes de avestruz; e nunca mais será habitada, nem servirá de morada geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Assim como Deus destruiu Sodoma, Gomorra e suas cidades vizinhas,diz o SENHOR, assim também não habitará ali homem, nem filho de homem a morará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Eis que um povo vem do norte; e uma grande nação, e muitos reis se levantarão dos lugares distantes da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Eles manejam arco e lança; são cruéis, e não terão compaixão; sua voz soará como o mar, e montarão sobre cavalos; ficarão em posição como de homem para a batalha, contra ti, ó filha da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'O rei da Babilônia ouviu a notícia deles, e suas mãos perderam as forças; tomado foi por angústia e dor, como mulher de parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Eis que como leão subirá da mata do Jordão contra a morada do forte; pois repentinamente o farei correr dali. E ordenarei contra ela a quem eu escolher; pois quem é semelhante a mim? E quem manda em mim? Ou quem é o pastor que pode subsistir diante de mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Portanto ouvi o conselho do SENHOR, que decretou contra a Babilônia; e seus pensamentos, que ele determinou sobre a terra dos caldeus: Certamente os menores do rebanho serão arrastados, certamente destruirá sua habitação com deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Do ruído da tomada da Babilônia a terra tremeu, e o grito se ouviu entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Assim diz o SENHOR: Eis que eu levanto um vento destruidor contra a Babilônia, e contra os moradores de Lebe-Camai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'E enviarei padejadores à Babilônia, que a padejarão, e esvaziarão sua terra; porque virão contra ela por todos os lados no dia da calamidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Que o flecheiro não arme o seu arco, nem deixes que ponham sua couraça; não poupeis a seus rapazes, destruí todo o seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'E os mortos cairão na terra dos caldeus, e os perfurados em suas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Porque Israel e Judá não foram abandonados por seu Deus, o SENHOR dos exércitos, ainda que sua terra foi cheia de pecado contra o Santo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fugi do meio de Babilônia, e livrai cada um sua alma; não pereçais por causa de sua maldade; pois é tempo de vingança do SENHOR, em que ele lhe dará o pagamento dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'A Babilônia era um copo de ouro na mão do SENHOR, que embriagava toda a terra; de seu vinho beberam as nações; por isso as nações se enlouqueceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Repentinamente Babilônia caiu, e se despedaçou: uivai por ela; tomai bálsamo para sua dor, talvez sare.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Sararíamos Babilônia, porém ela não se sarou; deixai-a, e vamo-nos cada um a sua terra; pois seu julgamento chegou até o céu, e subiu até as nuvens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'O SENHOR trouxe à luz nossas justiças; vinde, e contemos em Sião a obra do SENHOR nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Limpai as flechas, preparai os escudos; o SENHOR levantou o espírito dos reis da Média; pois seu pensamento é contra Babilônia para destruí-la; pois esta é vingança do SENHOR, a vingança de seu templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Levantai bandeira sobre os muros da Babilônia, reforçai a guarda, ponde vigilantes, preparai ciladas; pois assim o SENHOR tanto planejou como fez o que disse sobre os moradores de Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Tu que habitas sobre muitas águas, rica em tesouros, chegou o teu fim, o limite de tua ganância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'O SENHOR dos exércitos jurou por si mesmo, dizendo: Eu te encherei de homens como de gafanhotos, que darão gritos de guerra contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Ele é o que fez a terra com sua força, o que estabeleceu o mundo com sua sabedoria, e estendeu os céus com seu entendimento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Quando ele dá sua voz, há um grande estrondo de águas no céu, e faz subir as nuvens desde os confins da terra; ele faz os relâmpagos com a chuva, e tira o vento de seus tesouros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Todo homem tem se tornado bruto, e sem conhecimento; envergonha-se todo artífice da imagem de escultura, porque sua imagem de fundição é mentira, e não há espírito nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Elas são inúteis, obra de enganos; no tempo de seu castigo perecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'A porção de Jacó não é como eles; pois ele é o Formador de tudo; e Israel é a vara de sua herança; EU-SOU dos exércitos é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Tu és para mim um martelo, e armas de guerra; contigo despedaçarei nações, e contigo destruirei reinos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Contigo despedaçarei o cavalo e seus cavaleiro, contigo despedaçarei a carruagem, e os que nela sobem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Contigo despedaçarei o homem e a mulher, contigo despedaçarei o velho e o jovem, contigo despedaçarei o rapaz e a moça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Contigo despedaçarei o pastor e seu rebanho; contigo despedaçarei o lavrador e suas juntas de bois; e contigo despedaçarei governadores e príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Mas retribuirei à Babilônia e a todos os moradores da Caldeia todo a sua maldade, que fizeram em Sião diante de vossos olhos,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Eis que eu sou contra ti, ó monte destruidor, que destróis toda a terra,diz o SENHOR, e estenderei minha mão contra ti, e te farei rolar das rochas, e te tonarei um monte queimado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'E não tomarão de ti pedra para esquina, nem pedra para fundamentos; porque te tornarás em assolações perpétuas,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Levantai bandeira na terra, tocai trombeta entre as nações, preparai nações contra ela; convocai contra ela os reinos de Ararate, Mini, e Asquenaz; ordenai contra ela capitães, fazei subir cavalos como gafanhotos eriçados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Preparai contra ela as nações; os reis da Média, seus capitães, e todos seus chefes, e também toda a terra em que eles governam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Então a terra tremerá, e se afligirá; porque todos os pensamentos do SENHOR estão firmes contra a Babilônia, para tornar a terra de Babilônia em desolação, de modo que não haja morador nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Os guerreiros de Babilônia pararam de lutar, ficaram-se nas fortalezas; faltou-lhes sua força, tornaram-se como mulheres; incendiaram-se suas casas, quebraram-se seus ferrolhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Corredor se encontrará com corredor, mensageiro se encontrará com mensageiro, para anunciar ao rei de Babilônia que sua cidade é tomada por todas os lados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'E os vaus foram tomados, os canaviais foram queimados a fogo, e os homens de guerra foram assombrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Pois assim diz o SENHOR dos exércitos, Deus de Israel: A filha de Babilônia é como uma eira; já é tempo de trilhá-la; daqui a pouco lhe virá o tempo da ceifa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Comeu-me, esmagou-me Nabucodonosor rei de Babilônia; tornou-me como um vaso vazio, tragou-me como um chacal, seu ventre se encheu do que eu tinha de melhor, e me lançou fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'A violência feita contra mim e minha carne venha sobre a Babilônia, dirá a moradora de Sião; e meu sangue sobre os moradores da Caldeia, dirá Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Portanto assim diz o SENHOR: Eis que eu defenderei a tua causa, e vingarei por ti; secarei seu mar, e farei que seu manancial fique seco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'E Babilônia se tornará em amontoados, em morada de chacais, espanto e assovio, sem morador algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Juntamente rugirão como leões; como filhotes de leões bramarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Quando estiverem esquentados, eu lhes porei seus banquetes, e farei com que se embriaguem, para que se alegrem, e durmam um sono eterno, e não despertem,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Eu os levarei abaixo como cordeiros ao matadouro, como carneiros e bodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Como foi capturada Sesaque, e tomada a que era o louvor de toda a terra! Como Babilônia se tornou em espanto entre as nações!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'O mar subiu sobre a Babilônia; pela multidão de suas ondas foi coberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Suas cidades se tornaram desoladas, uma terra seca e deserta, terra que ninguém habita, nem filho de homem passa por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'E punirei a Bel na Babilônia, e tirarei de sua boca o que tragou; e nunca mais as nações virão a ele; e o muro da Babilônia cairá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Saí do meio dela, ó povo meu, e livrai cada um sua alma do ardor da ira do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'E para que vosso coração não perca as forças, e tenhais medo por causa das notícias que forem ouvidas pela terra; pois em um ano virá notícias, e depois em outro ano mais notícias; e haverá violência na terra, dominador sobre dominador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Portanto eis que vêm dias em que punirei as imagens de escultura da Babilônia, e toda a sua terra será envergonhada, e todos seus mortos cairão no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'E os céus, a terra, e tudo quanto neles há, cantarão vitória sobre a Babilônia; porque do norte virão destruidores contra ela,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Pois Babilônia cairá por causa dos mortos de Israel, assim como por causa da Babilônia caíram mortos de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Vós que escapastes do espada, ide embora, não pareis; lembrai-vos do SENHOR até longe, e Jerusalém venha à vossa mente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Direis, porém: Estamos envergonhados, porque ouvimos a humilhação; a vergonha cobriu nossos rostos, porque vieram estrangeiros contra os santuários da casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Portanto eis que vêm dias,diz o SENHOR, em que punirei suas imagens de escultura, e em toda a sua terra gemerão os feridos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Mesmo se a Babilônia subisse ao céu e se fortificasse no alto seu poder, ainda assim de mim virão destruidores contra ela,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Ouve-se som de gritos da Babilônia, e grande quebrantamento da terra dos caldeus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Pois o SENHOR destrói a Babilônia, e eliminará dela seu grande ruído; e suas ondas bramarão, como muitas águas será o ruído da voz deles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Pois o destruidor vem contra ela, contra Babilônia; seus guerreiros serão presos, o arco deles será quebrado; porque o SENHOR, Deus de retribuições, certamente dará a pagamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'E embriagarei a seus príncipes e seus sábios, a seus governadores, seus chefes e seus guerreiros; e dormirão sonho perpétuo, e não despertarão, diz o Rei, cujo nome é EU-SOU dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Assim diz o SENHOR dos exércitos: Os largos muros da Babilônia serão derrubado por completo, e suas altas portas serão incendiadas a fogo; os povos trabalharão para nada, as nações para o fogo, e se cansarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Palavra que o profeta Jeremias enviou a Seraías, filho de Nerias, filho de Maasias, quando ele foi com Zedequias rei de Judá para a Babilônia, no quarto ano de seu reinado. E Seraías era o camareiro-chefe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Escreveu, pois, Jeremias em um livro todo o mal que viria sobre a Babilônia, todas estas palavras que estavam escritas contra a Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'E Jeremias disse a Seraías: Quando chegares à Babilônia, tu deves ler e dizer todas estas palavras,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Então dirás: Ó SENHOR, tu falaste sobre este lugar, que o cortarias fora, até não ficar nele morador, nem homem nem animal, e que se tornaria em desolação perpétua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'E será que, quando acabares de ler este livro, tu o atarás a uma pedra, e o lançarás no meio do Eufrates,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'E dirás: Assim Babilônia será afundada, e não se levantará da calamidade que eu trago sobre ela; e se cansarão. Até aqui são as palavras de Jeremias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Zedequias era de idade de vinte e um anos quando começou a reinar, e reinou onze anos em Jerusalém. Sua mãe se chamava Hamutal, filha de Jeremias, de Libna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'E ele fez o que era mal aos olhos do SENHOR, conforme tudo o que Jeoaquim fizera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'E por isso a ira do SENHOR foi contra Jerusalém e Judá, até que ele os expulsou de sua presença; assim Zedequias se rebelou contra o rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'E aconteceu no nono ano de seu reinado, no decimo mês, aos dez dias do mês, que veio Nabucodonosor rei da Babilônia, ele e todo seu exército, contra Jerusalém, e contra ela montaram um acampamento, e ao redor por todos os lados levantaram cercos contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Assim a cidade esteve cercada até o décimo primeiro ano do rei Zedequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'No quarto mês, aos nove do mês, quando a fome havia dominado a cidade, até não haver pão para o povo da terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Então a cidade foi arrombada, e todos os homens de guerra fugiram, e saíram da cidade de noite, pelo caminho de porta de entre os dois muros, que era perto do jardim do rei, e foram-se pelo caminho de Arabá, enquanto os caldeus estavam ao redor da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Porém o exército dos caldeus perseguiu o rei, e alcançaram a Zedequias nas planícies de Jericó; e todo o seu exército se dispersou dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Então prenderam ao rei, e fizeram-lhe vir ao rei de Babilônia, a Ribla na terra de Hamate, onde pronunciou sentença contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'E o rei da Babilônia degolou os filhos de Zedequias diante de seus olhos; e também degolou a todos os príncipes de Judá em Ribla.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Mas Zedequias porém cegou os olhos, e o acorrentou com grilhões de bronze; e o rei da Babilônia o levou à Babilônia, e o pôs na casa do cárcere até o dia de sua morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'E no quinto mês, aos dez do mês (que era o décimo nono ano do reinado de Nabucodonosor, rei de Babilônia), Nebuzaradã, capitão da guarda, que servia diante do rei de Babilônia, veio a Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'E queimou a casa do SENHOR, a casa do rei, e todas as casas de Jerusalém; e queimou com fogo todo grande edifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'E todo o exército dos caldeus que estava com o capitão da guarda derrubou todos os muros que estavam ao redor de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'E Nebuzaradã, capitão da guarda, levou presos os pobres do povo, e ao demais do povo, que restaram na cidade, e os rebeldes que se haviam se rendido ao rei de Babilônia, e todo o resto dos artesãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Mas dos pobres do país Nebuzaradã, capitão da guarda, deixou para serem cultivadores de vinhas e lavradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'E os caldeus quebraram as colunas de bronze que estavam na casa do SENHOR, as bases, e o mar de bronze que estavam na casa do SENHOR, e levaram todo o bronze à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Tomaram também os caldeirões, as pás, os cortadores de pavios, as bacias, os pratos, e todos os vasos de bronze com que faziam o serviço no templo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'E o capitão da guarda tomou os copos, os incensários, as bacias, as panelas, os castiçais, os pratos, e vasos de ofertas de líquidos: tudo o que era de ouro ou de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'As duas colunas, o mar, e os doze bois de bronze que estavam debaixo das bases, que o rei Salomão tinha feito na casa do SENHOR. não se podia pesar o bronze de todos estes vasos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Quanto às colunas, a altura de cada coluna era de dezoito côvados, e um fio de doze côvados a rodeava; e sua espessura era de quatro dedos, e era oca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'E tinha sobre si um capitel de bronze, e a altura do capitel era de cinco côvados, com uma rede e romãs ao redor do capitel, tudo de bronze; e semelhante a esta era o da segunda coluna, com suas romãs.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'E havia noventa e seis romãs em cada lado; ao todo elas eram cem sobre a rede ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'O capitão da guarda também tomou a Seraías o sacerdote principal, e a Sofonias o segundo sacerdote, e três guardas da porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'E da cidade tomou a um eunuco que era comandante sobre os homens de guerra, e a sete homens que serviam na presença do rei, que se acharam na cidade; e também ao principal escrivão do exército, que registrava o povo da terra para a guerra; e a sessenta homens do povo da terra, que se acharam no meio da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Então Nebuzaradã, capitão da guarda, os tomou, e os levou ao rei de Babilônia, a Ribla.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'E o rei de Babilônia os feriu e os matou em Ribla na terra de Hamate. Assim Judá foi levado cativo de sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Este é o povo que Nabucodonosor levou cativo; no sétimo ano, três mil e vinte e três judeus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'No décimo oitavo ano Nabucodonosor, levou cativas de Jerusalém oitocentas e trinta e duas pessoas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'No vigésimo terceiro ano de Nabucodonosor, Nebuzaradã capitão da guarda levou cativas setecentas e quarenta e cinco pessoas dos judeus; no total foram quatro mil e seiscentas pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Sucedeu, pois, no trigésimo sétimo ano de cativeiro de Joaquim rei de Judá, no décimo segundo mês, aos vinte e cinco do mês, que Evil-Merodaque, rei da Babilônia, no primeiro ano de seu reinado, concedeu perdão a Joaquim rei de Judá, e o tirou da casa de prisão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'E falou com ele benignamente; e pôs sua cadeira com mais honra do que as cadeiras dos reis que estavam com ele em Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'E mudou-lhe também as roupas de sua prisão, e continuamente comeu pão diante dele, todos os dias de sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'E continuamente foi-lhe dada provisão pelo rei da Babilônia, uma porção diária, até o dia de sua morte, por todos os dias de sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Como se senta solitária a cidade que era tão populosa! A grande entre as nações tornou-se como viúva, a senhora de províncias passou a ser escrava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Amargamente chora na noite, suas lágrimas em seu rosto; entre todos os seus amantes não há quem a console; todos os seus amigos a traíram, inimigos se tornaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Judá foi ao cativeiro com aflição e grande servidão; ela habita entre as nações, mas não acha descanso; todos os seus perseguidores a alcançam em meio ao aperto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Os caminhos de Sião estão em pranto, pois ninguém vem aos festivais; todas as suas portas estão desertas, seus sacerdotes gemem, suas virgens se afligem, e ela sofre de amargura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Seus oponentes estão no comando, seus inimigos prosperam; pois o SENHOR a afligiu por causa das suas muitas transgressões; suas crianças foram em cativeiro adiante do adversário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Partiu-se toda a beleza da filha de Sião; seus líderes estão como cervos, não acham pasto algum; eles andam fracos, fugindo do perseguidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Nos dias da sua aflição, e de suas andanças perdidas, Jerusalém lembra-se de todas as suas preciosidades, que tinha nos tempos antigos; quando seu povo caiu na mão do adversário, não houve quem a ajudasse; os adversários a viram, e zombaram da sua queda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalém pecou gravemente; por isso ela se tornou impura; todos os que a honravam a desprezam, porque viram a sua nudez; ela geme, e se vira para trás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Sua imundície estava até nas roupas; nunca se importou com o seu futuro; por isso caiu espantosamente, sem ter quem a consolasse. Olha, SENHOR, a minha aflição, porque o inimigo está engrandecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'O adversário tomou todas as suas coisas de valor; ela viu as nações entrarem no seu templo - aquelas que proibiste de entrarem na tua congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Todo o seu povo anda suspirando em busca de pão; trocaram todas os seus bens por comida a fim de sobreviverem Olha, SENHOR, e vê que estou desprezada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Todos vós que estais passando, não vos importais? Olhai, e vede se há dor como a minha, que me foi imposta, que o SENHOR me afligiu no dia da sua ira ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Desde o alto ele enviou fogo em meus ossos, o qual os dominou; ele estendeu uma rede a meus pés, fez-me voltar para trás; tornou-me assolada, sofrendo dores o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'O jugo de minhas transgressões está amarrado por sua mão, elas estão ligadas, postas sobre o meu pescoço; ele abateu minhas forças. O Senhor me entregou nas suas mãos daqueles contra quem não posso me levantar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'O Senhor derrotou todos os meus fortes em meio de mim; convocou contra mim um ajuntamento para quebrar os meus rapazes; o Senhor tem pisado a virgem filha de Judá como se fosse um lagar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Por estas coisas que eu choro; meus olhos, de meus olhos correm águas; pois afastou-se de mim consolador que daria descanso à minha alma: meus filhos estão desolados, porque o inimigo prevaleceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Sião estendeu suas mãos, não há quem a console; o SENHOR deu ordens contra Jacó, para que seus inimigos o cercassem: Jerusalém se tornou imunda entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'O SENHOR é justo; eu que me rebelei contra sua boca. Ouvi, pois, todos os povos, e vede minha dor; minhas virgens e meus rapazes foram em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Clamei a meus amantes, porém eles me enganaram; meus sacerdotes e meus anciãos pereceram na cidade; pois buscam comida para si tentarem sobreviver.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Olha, SENHOR, que estou angustiada; tormentam-se minhas entranhas, meu coração está transtornado em meio de mim, pois gravemente me rebelei; de fora desfilhou -me a espada, de dentro está como a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Eles me ouvem gemendo, porém não tenho consolador. Todos meus inimigos, quando ouvem minha aflição se alegram, pois tu o fizeste. Quando tu trouxeres o dia que anunciaste, eles serão como eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Toda a maldade deles venha diante de ti, e faze com eles assim como fizeste comigo por causa de todas as minhas transgressões; pois meus gemidos são muitos, e meu coração está desfalecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Como o Senhor cobriu a filha de Sião com sua ira! Ele derrubou a formosura de Israel do céu à terra, e não se lembrou do estrado de seus pés no dia de sua ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'O Senhor, destruiu sem compaixão todas as moradas de Jacó; derrubou em seu furor as fortalezas da filha de Judá, desonrou o reino e seus príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Cortou no furor de sua ira todo o poder de Israel; tirou sua mão direita de diante do inimigo; e se acendeu contra Jacó como labareda de fogo que consome ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Armou seu arco como inimigo, pôs sua mão direita como adversário, e matou todas as coisas agradáveis à vista; derramou sua indignação como fogo na tenda da filha de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'O Senhor tornou-se como inimigo, destruiu a Israel; destruiu todos os seus palácios, arruinou as suas fortalezas; e multiplicou na filha de Judá a lamentação e a tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'E com violência arrancou sua tenda, como se fosse de uma horta, destruiu o lugar de sua congregação; o SENHOR fez esquecer em Sião as solenidades e os sábados, E tem lançado no furor de sua ira rei e sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'O Senhor rejeitou seu altar, detestou seu santuário, entregou na mão do inimigo os muros de seus palácios; levantaram gritaria na casa do SENHOR como em dia de festa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'O SENHOR determinou destruir o muro da filha de Sião; estendeu o cordel, não deteve sua mão de destruir; tornou em lamento o antemuro e o muro; juntamente foram destruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Suas portas foram lançadas por terra, destruiu e quebrou seus ferrolhos; sua rei e seus príncipes estão entre as nações onde não há a Lei; nem seus profetas acham visão alguma do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Sentados na terra e calados estão os anciãos da filha de Sião; lançaram pó sobre suas cabeças, vestiram-se de saco; as virgens de Jerusalém baixaram suas cabeças à terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Meus olhos se consumiram de lágrimas, atormentam-se minhas entranhas; meu fígado se derramou por terra por causa do quebrantamento da filha de meu povo, porque crianças e bebês de mama desfalecem pelas ruas da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Eles dizem às suas mães: Onde está o trigo e o vinho?, enquanto desfalecem como feridos pelas ruas da cidade, derramando suas almas no colo de suas mães.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Que testemunho te trarei, ou a quem te compararei, ó filha de Jerusalém? A quem te assemelharei para te consolar, ó virgem, filha de Sião? Pois teu quebrantamento é tão grande quanto o mar; quem te curará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Teus profetas previram para ti futilidades e enganos; e não expuseram tua maldade para evitar teu cativeiro; em vez disso te predisseram profecias mentirosas e ilusórias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Todos os que passam pelo caminho, batem palmas para zombar de ti; assoviaram, e moveram suas cabeças por causa da filha de Jerusalém, dizendo: É esta a cidade que diziam ser a perfeita beleza, a alegria de toda a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Todos os teus inimigos abrem suas bocas contra ti, assoviam, e rangem os dentes; dizem: Nós a devoramos; pois este é o dia que esperávamos; nós o achamos, e o vimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'O SENHOR fez o que tinha determinado; cumpriu sua palavra que ele havia mandado desde os dias antigos; destruiu sem ter compaixão; e alegrou o inimigo sobre ti, e levantou o poder de teus adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'O coração deles clamou ao Senhor. Ó muralha da filha de Sião, derrama lágrimas como um ribeiro dia e noite; não te dês descanso, nem cessem as meninas de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Levanta-te, grita de noite, no começo das vigílias; derrama teu coração como águas diante da presença do Senhor; levanta tuas mãos a ele pela vida de tuas criancinhas, que desfalecem de fome nas entradas de todas as ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Olha, SENHOR, e considera a quem fizeste de tal modo; por acaso as mulheres comerão do seu próprio fruto, as criancinhas que carregam nos braços? Por acaso serão o sacerdote e o profeta mortos no santuário do Senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Jovens e velhos jazem por pelas ruas; minhas virgens e meus rapazes caíram à espada; tu os mataste no dia de tua ira, degolaste sem ter compaixão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Convocaste meus temores ao redor, como se fosse um dia solene; não houve quem escapasse no dia do ira do SENHOR, nem que restasse vivo; aos que criei e sustentei, meu inimigo os consumiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Eu sou o homem que viu a aflição pela vara de seu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Guiou-me e levou-me a trevas, e não à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Com certeza se virou contra mim, revirou sua mão o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Fez envelhecer minha carne e minha pele, quebrou meus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Edificou contra mim, e cercou -me de fel e de trabalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Fez-me habitar em lugares escuros, como os que já morrera há muito tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Cercou-me por todos lados, e não posso sair; tornou pesados os meus grilhões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Até quando clamo e dou vozes, fechou os ouvidos à minha oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Cercou meus caminhos com pedras lavradas, retorceu as minhas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Foi para mim como um urso que espia, como um leão escondido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Desviou meus caminhos, e fez-me em pedaços; deixou-me desolado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Armou seu arco, e me pôs como alvo para a flecha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Fez entrar em meus rins as flechas de sua aljava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Servi de escárnio a todo o meu povo, de canção ridícula deles o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Fartou-me de amarguras, embebedou-me de absinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Quebrou os meus dentes com cascalho, cobriu-me de cinzas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'E afastou minha alma da paz, fez-me esquecer da boa vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Então eu disse: Pereceram minha força e minha esperança no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Lembra-te da minha aflição e do meu sofrimento, do absinto e do fel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Minha alma se lembra e se abate em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Disto me recordarei na minha mente, por isso terei esperança:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'É pelas bondades do SENHOR que não somos consumidos, porque suas misericórdias não têm fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Elas são novas a cada manhã; grande é a tua fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'O SENHOR é minha porção, diz a minha alma; portanto nele esperarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Bom é o SENHOR para os que nele esperam, para a alma que o busca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'É bom esperar e tranquilo aguardar a salvação do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'É bom ao homem levar o jugo em sua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Sente-se só, e fique quieto; pois ele o pôs sobre si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Ponha sua boca no pó; talvez haja esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Dê a face ao que o ferir; farte-se de insultos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Pois o Senhor não rejeitará para sempre:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Mesmo que cause aflição, ele também se compadecerá segundo a grandeza de suas misericórdias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Pois não é sua vontade afligir nem entristecer os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Esmagar debaixo de seus pés a todos os prisioneiros da terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Perverter o direito do homem diante da presença do Altíssimo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Prejudicar ao homem em sua causa: o Senhor não aprova) tais coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Quem é que pode fazer suceder algo que diz, se o Senhor não tiver mandado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Por acaso da boca do Altíssimo não sai tanto a maldição como a bênção?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Por que o homem vivente se queixa da punição de seus próprios pecados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Examinemos nossos caminhos, investiguemos, e nos voltemos ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Levantemos nossos corações e as mãos a Deus nos céus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Dizendo: Nós transgredimos e fomos rebeldes; tu não perdoaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Cobriste-te de ira, e nos perseguiste; mataste sem teres compaixão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Cobriste-te de nuvens, para que nossa oração não passasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tu nos tornaste como escória e rejeito no meio dos povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Todos os nossos inimigos abriram sua boca contra nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Medo e cova vieram sobre nós, devastação e destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Rios de águas correm de meus olhos, por causa da destruição da filha de meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Meus olhos destilam, e não cessam; não haverá descanso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Até que o SENHOR preste atenção, e veja desde os céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Meus olhos afligem minha alma, por causa de todas as filhas de minha cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Sem motivo meus inimigos me caçam como a um passarinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Tentaram tirar minha vida na masmorra, e lançaram pedras sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'As águas inundaram sobre minha cabeça; eu disse: É o meu fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Invoquei o teu nome, SENHOR, desde a cova profunda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Ouviste minha voz: não escondas o teu ouvido ao meu suspiro, ao meu clamor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Tu te achegaste no dia em que te invoquei; disseste: Não temas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Defendeste, Senhor, as causas de minha alma; redimiste minha vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Viste, SENHOR, a maldade que me fizeram; julga minha causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Viste toda a vingança deles, todos os seus pensamentos contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Ouvido os seus insultos, ó SENHOR, todos os seus pensamentos contra mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'As coisas ditas pelos que se levantam contra mim, e seu planos contra mim o dia todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Olha para tudo quanto eles fazem; com canções zombam de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Retribui-lhes, SENHOR, conforme a obra de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Dá-lhes angústia de coração, tua maldição a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Persegue-os com ira, e destrua-os de debaixo dos céus do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Como se escureceu o ouro! Como mudou o bom e fino ouro! As pedras do Santuário estão espalhadas pelas esquinas de todas as ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Os preciosos filhos de Sião, estimados como o ouro puro, como agora são considerados como vasos de barro, obra das mãos de oleiro!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Até os chacais dão o peito para amamentar a seus filhotes; porém a filha de meu povo se tornou cruel, como os avestruzes no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Por causa da sede a língua da criança de peito se grudou a seu céu da boca; os meninos pedem pão, e ninguém há lhes reparta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Os que comiam das melhores iguarias, agora desfalecem nas ruas; os que se criaram em carmesim abraçam o lixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Pois maior é o castigo da filha de meu povo do que o do pecado de Sodoma, Que foi transtornada em um momento, e não assentaram sobre ela companhias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Seus nazireus eram mais alvos que a neve, mais brancos que o leite. Seus corpos eram mais avermelhados que rubis, e mais polidos que a safira;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Mas agora sua aparência se escureceu mais que o carvão; não são mais reconhecidos nas ruas; sua pele está apegada a seus ossos, ficou seca como um pau.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Mais felizes foram os mortos pela espada do que os mortos pela fome; porque estes se abatem traspassados pela falta dos frutos do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'As mãos das mulheres compassivas cozeram a seus filhos; serviram-lhes de comida na destruição da filha de meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'O SENHOR cumpriu o seu furor, derramou o ardor de sua ira; e acendeu fogo em Sião, que consumiu seus fundamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Nem os reis da terra, nem todos os que habitam no mundo, criam que o adversário e o inimigo entraria pelas portas de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Assim foi por causa dos pecados de seus profetas, por causa das maldades de seus sacerdotes, que derramaram o sangue dos justos em meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Titubearam como cegos nas ruas, andaram contaminados de sangue, de maneira que ninguém podia tocar suas vestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Gritavam-lhes: Afastai-vos, imundos! Afastai-vos, afastai-vos, não toqueis. Quando fugiram e andaram sem rumo, foi dito entre as nações: Aqui não morarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'A face do SENHOR os dispersou, não os olhará mais: não respeitaram a face dos sacerdotes, nem tiveram compaixão dos velhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Quanto a nós, desfaleceram-se nossos olhos esperando por socorro para nós; aguardávamos atentamente uma nação que não podia salvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Caçaram nossos passos, de modo que não podíamos andar por nossas ruas; achegou-se o nosso fim, nossos dias se completaram, pois nosso fim veio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Nossos perseguidores foram mais velozes que as águias do céu; sobre os montes nos perseguiram, no deserto armaram ciladas para nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'O fôlego de nossas narinas, o ungido do SENHOR, do qual dizíamos: Abaixo de sua sombra teremos vida entre as nações; foi preso em suas covas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Goza-te e alegra-te, filha de Edom, que habitas na terra de Uz: porém o cálice também passará por ti; tu te embriagarás, e te desnudarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Cumpriu-se o castigo por tua maldade, ó filha de Sião; nunca mais te levará em cativeiro. Ele punirá tua maldade, ó filha de Edom; revelará os teus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Lembra-te, SENHOR, do que tem nos acontecido; presta atenção e olha nossa humilhação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Nossa herança passou a ser de estrangeiros, nossas casas de forasteiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Órfãos somos sem pai, nossas mães são como viúvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Bebemos nossa água por dinheiro; nossa lenha temos que pagar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Perseguição sofremos sobre nossos pescoços; estamos cansados, mas não temos descanso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Nós nos rendemos aos egípcios e aos assírios para nos saciarmos de pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Nossos pais pecaram, e não existem mais; porém nós levamos seus castigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Servos passaram a nos dominar; ninguém há que nos livre de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Com risco de vida trazemos nosso pão, por causa da espada do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Nossa pele se tornou negra como um forno, por causa do ardor da fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Abusaram das mulheres em Sião, das virgens nas cidades de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Os príncipes foram enforcados por sua mãos; não respeitaram as faces dos velhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Levaram os rapazes para moer, e os moços caíram debaixo da lenha que carregavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Os anciãos deixaram de se sentarem junto as portas, os rapazes de suas canções.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Acabou a alegria de nosso coração; nossa dança se tornou em luto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Caiu a coroa de nossa cabeça; ai agora de nós, porque pecamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Por isso nosso coração ficou fraco, por isso nossos olhos escureceram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Por causa do monte de Sião, que está desolado; raposas andam nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Tu, SENHOR, permanecerás para sempre; e teu trono de geração após geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Por que te esquecerias de nós para sempre e nos abandonarias por tanto tempo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Converte-nos, SENHOR, a ti, e seremos convertidos; renova o nossos dias como antes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'A não ser que tenhas nos rejeitado totalmente, e estejas enfurecido contra nós ao extremo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'E sucedeu que, aos trinta anos, no quarto mês, aos cinco do mês, estando eu em meio dos exilados, junto ao rio Quebar, os céus se abriram, e vi visões de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Aos cinco do mês, que foi no quinto ano do cativeiro do rei Joaquim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'verdadeiramente veio a palavra do SENHOR ao sacerdote Ezequiel, filho de Buzi, na terra dos caldeus, junto ao rio Quebar; e ali a mão do SENHOR esteve sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Então olhei, e eis que um vento tempestuoso vinha do norte, uma grande nuvem, e um fogo incandescente, e ao seu redor um resplendor, e no meio do fogo uma coisa que parecia como de âmbar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'E no meio dela havia a semelhança de quatro animais; e esta era sua aparência; eles tinham semelhança humana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'E cada um tinha quatro rostos, e cada um quatro asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'E suas pernas eram retas, e a planta de seus pés como a planta de pé de bezerro; e reluziam como o bronze polido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'E tinham mãos humanas debaixo de suas asas, em seus quatro lados; assim os quatro tinham seus rostos e suas asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Suas asas se juntavam umas às outras. Não viravam quando se moviam; cada um andava na direção de seu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'E a aparência de seus rostos era como rosto de homem; e rosto de leão à direita nos quatro; e à esquerda rosto de boi nos quatro; também havia nos quatro um rosto de águia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Assim eram seus rostos. E suas asas estavam estendidas por cima, cada um duas, as quais se juntavam; e as outras duas cobriam seus corpos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'E cada um se movia na direção de seu rosto; para onde o espírito se dirigia, eles iam; não viravam quando se moviam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Quanto à semelhança dos animais, sua aparência era como pedaços de carvão acesos, como aparência de tochas acesas; o fogo se movia entre os animais; e brilhava intensamente, e do fogo saíam relâmpagos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'E os animais corriam e voltavam, à semelhança de relâmpagos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'E enquanto eu estava vendo os animais, eis que uma roda estava na terra junto aos animais, junto a seus quatro rostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'E a aparência das rodas, e sua feitura, era como da cor do berilo; e as quatro tinham uma mesma semelhança; sua aparência e sua obra era como se uma roda estivesse no meio de outra roda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Quando andavam, moviam-se sobre seus quatro lados; não viravam quando se moviam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'E seus aros eram altos e espantosos; e seus aros estavam cheios de olhos ao redor das quatro rodas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'E quando os animais andavam, as rodas andavam junto a eles: e quando os animais se levantavam da terra, levantavam-se também as rodas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Para onde o espírito queria ir, iam, para onde era o espírito ia; e as rodas também se levantavam com eles, pois o espírito dos animais estava nas rodas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Quando eles andavam, elas andavam; e quando eles paravam, elas paravam; e quando se levantavam da terra, as rodas se levantavam com eles; pois o espírito dos animais estava nas rodas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'E sobre as cabeças dos animais havia algo semelhante a um firmamento, da cor de um cristal espantoso, estendido acima sobre suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'E debaixo do firmamento estavam suas asas deles estendidas uma à outra; a cada um tinha duas, e outras duas com que cobriam seus corpos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'E ouvi o ruído de suas asas quando se moviam, como o som de muitas águas, como a voz do Onipotente, o ruído de uma multidão, como o som de um exército. Quando paravam, abaixavam suas asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'E quando se paravam e abaixavam suas asas, ouvia-se uma voz de cima do firmamento que estava sobre suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'E acima do firmamento que estava sobre suas cabeças, havia a figura de um trono, que parecia com a pedra de safira; e sobre a figura do trono havia uma semelhança que parecia com um homem sentado acima dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'E vi o que parecia com o âmbar, com a aparência de fogo ao seu redor do lado de dentro, da aparência de sua cintura para cima; e de sua cintura para baixo, vi que parecia como fogo, e havia um resplendor ao redor dele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Tal como a aparência do arco celeste, que surge nas nuvens em dia de chuva, assim era o aparência do resplendor ao redor. Esta foi a visão da semelhança da glória do SENHOR. E quando eu a vi, caí sobre meu rosto, e ouvi voz de um que falava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'E Disse-me: Filho do homem, fica de pé, e falarei contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Então entrou em mim o Espírito enquanto falava comigo, e fez-me ficar de pé, e ouvi àquele que estava falando comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'E disse-me: Filho do homem, eu te envio aos filhos de Israel, às nações rebeldes que se rebelaram contra mim; eles e seus pais têm transgredido contra mim até este dia de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Pois são filhos duros de rosto e obstinados de coração; eu te envio a eles; e tu lhes dirás: Assim diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'E eles, quer ouçam, quer deixem de ouvir,(pois são uma casa rebelde) mesmo assim saberão que houve profeta entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'E tu, filho do homem, não os temas, nem temas suas palavras, ainda que estejas entre sarças e espinheiros, e tu habites com escorpiões; não temas suas palavras, nem te espantes pela presença deles, ainda que sejam uma casa rebelde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Tu falarás minhas palavras, quer ouçam, quer deixem de ouvir; pois são rebeldes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Porém tu, filho do homem, ouve o que eu te falo; não sejas rebelde como a casa rebelde; abre a tua boca, e come o que eu te dou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Então eu vi e eis que uma mão foi estendida para mim, e eis que nela havia um rolo de livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'E o estendeu diante de mim, e estava escrito pela frente, e por detrás: e nele estavam escritas lamentações, suspiros, e ais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Depois me disse: Filho do homem, come o que achares; come este rolo, vai, e fala à casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Então abri minha boca, e me fez comer aquele rolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'E disse-me: Filho do homem, faze com que teu ventre coma, e enche tuas entranhas deste rolo que eu te dou. Então o comi, e foi em minha boca doce como o mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'E disse-me: Filho do homem, vai, entra na casa de Israel, e fala-lhes com minhas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Pois tu não és enviado a um povo de fala estranha nem de língua difícil, mas sim à casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Nem a muitos povos de fala estranha nem de língua difícil, cujas palavras não podes entender; se eu a eles te enviasse, eles te dariam ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Porém a casa de Israel não quererá te ouvir, pois não querem ouvir a mim; pois toda a casa de Israel é obstinada de testa e dura de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Eis que eu fiz teu rosto forte contra os rostos deles, e tua testa forte contra a testa deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Fiz tua testa como o diamante, mais forte que a pederneira; não os temas, nem te espantes da presença deles, ainda que sejam uma casa rebelde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Disse-me mais: Filho do homem, toma em teu coração todas a minhas palavras que te falarei, e ouve com os teus ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Então vai, e chega aos do cativeiro, aos filhos de teu povo, e tu lhes falarás e lhes dirás: Assim diz o Senhor DEUS; quer ouçam, quer deixem de ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Então o Espírito me levantou, e ouvi detrás de mim uma voz de grande estrondo, que dizia: Bendita seja a glória do SENHOR desde seu lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Ouvi também o som das asas dos animais, que tocavam umas às outras, e o som das rodas em frente deles, e som de grande estrondo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Assim o Espírito me levantou, e me tomou; e fui com amargura, pela indignação de meu espírito; mas a mão do SENHOR era forte sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'E vim aos do cativeiro, a Tel-Abibe, que moravam junto ao rio de Quebar, e eu morava onde eles moravam; e ali permaneci sete dias atônito entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'E aconteceu que, ao fim de sete dias, veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Filho do homem, eu te pus por vigia sobre a casa de Israel; portanto tu ouvirás a palavra de minha boca, e os alertarás de minha parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Quando eu disser ao perverso: Certamente morrerás, e tu não o alertares, nem falares, para alertar ao perverso acerca de seu perverso caminho, a fim de o conservar em vida, o perverso morrerá por sua maldade, porém demandarei seu sangue de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Mas se tu alertares ao perverso, e ele não se converter de sua perversidade, e de seu perverso caminho, ele morrerá por sua maldade, e tu terás livrado tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Semelhantemente, quando o justo se desviar de sua justiça, e fizer maldade, e eu puser algum tropeço diante dele, ele morrerá, porque tu não o alertaste; por seu pecado morrerá, e suas justiças que havia feito não serão lembradas; mas seu sangue demandarei de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Porém se tu alertares ao justo, para que o justo não peque, e ele não pecar, certamente viverá, porque foi alertado; e tu terás livrado tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'E a mão do SENHOR estava ali sobre mim; e disse-me: Levanta-te, e sai ao vale; e ali falarei contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Então eu me levantei, e saí ao vale; e eis que a glória do SENHOR estava ali, como a glória que vi junto ao rio de Quebar; e caí sobre meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Então o Espírito entrou em mim, e fez-me ficar de pé; e falou comigo, e disse-me: Entra, e fecha-te dentro de tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Pois tu, ó filho do homem, eis que porão cordas sobre ti, e com elas te amarrarão, por isso não sairás entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'E farei com que tua língua se apegue ao teu céu da boca, e ficarás mudo, e não lhes servirás de repreensor; pois são uma casa rebelde');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mas quando eu falar contigo, abrirei a tua boca, e lhes dirás: Assim diz o Senhor DEUS; quem ouvir, ouça; e quem deixar de ouvir,deixe; pois são uma casa rebelde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'E tu, filho do homem, toma para ti um tijolo, põe-o diante de ti, e desenha sobre ele a cidade de Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'E põe um cerco contra ela, e edifica contra ela uma fortaleza, e levanta uma rampa contra ela; e põe acampamentos contra ela, e ordena contra ela aríetes ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'E tu, toma para ti uma assadeira de ferro, e põe-a como muro de ferro entre ti e a cidade; e endireita tua face contra ela, e assim será cercada, e a cercarás. Isto será um sinal para a casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'E tu deita sobre teu lado esquerdo, e põe sobre ele a maldade da casa de Israel; conforme o número de dias que deitares sobre ele, levarás suas maldades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Pois eu te dei os anos da maldade deles conforme o número de dias: trezentos e noventa dias; e tu levarás a maldade da casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'E quando completardes estes, voltarás a deitar sobre teu lado direito, e levarás a maldade da casa de Judá por quarenta dias; dei para ti um dia para cada ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Portanto dirigirás teu rosto ao cerco de Jerusalém firmarás teu rosto, e manterás teu braço descoberto; e profetizarás contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'E eis que porei sobre ti cordas, e não te virarás de teu lado ao para o outro, enquanto não houveres completado os dias de teu cerco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'E tu, toma para ti trigo, cevada, favas, lentilhas, milho miúdo, e aveia, e põe-os em uma vasilha, e faz para ti pão deles, conforme o número de dias que dormires sobre teu lado; trezentos e noventa dias comerás disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'E a comida que comerás será do peso de vinte siclos cada dia; de tempo em tempo a comerás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Também beberás a água por medida: a sexta parte de um him; de tempo em tempo beberás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'E a comerás como se fosse pão de cevada; e a cozerás com as fezes que saem do homem, diante dos olhos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'E disse o SENHOR: Assim os filhos de Israel comerão seu pão imundo entre as nações, para onde eu os lançarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Então eu disse: Ah Senhor DEUS! Eis que minha alma não foi contaminada; porque nunca comi coisa morta nem despedaçada, desde minha juventude até agora, nem nunca entrou em minha boca carne imunda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'E ele me disse: Eis que te dou fezes de vacas em lugar dos fezes humanas; e prepararás teu pão com elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Então me disse: Filho do homem, eis que destruirei o sustento do pão em Jerusalém, e comerão o pão por peso, e com angústia; e beberão a água por medida, e com espanto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Para que lhes falte o pão e o água, e se espantem uns aos outros, e se consumam em suas maldades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'E tu, filho do homem, toma para ti uma espada afiada que te sirva como navalha de barbeiro; toma, e faze-a passar por tua cabeça e por tua barba; depois toma para ti um peso de balança, e reparte os cabelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Uma terceira parte queimarás com fogo no meio da cidade, quando se completarem os dias do cerco; então tomarás outra terceira parte, ferindo com espada ao redor dela; e a outra terceira parte espalharás ao vento; pois eu desembainharei a espada atrás deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Tomarás também dali alguns poucos cabelos, e os atarás nas bordas de tua roupa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'E tomarás outra vez deles, e os lançarás no meio do fogo, e com fogo os queimarás; dali sairá um fogo contra toda a casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Assim diz o Senhor DEUS: Esta é Jerusalém, a qual eu pus no meio das nações, e das terras ao redor dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Porém ela se rebelou contra meus juízos mais que as nações, e contra meus estatutos mais que as terras que estão ao redor dela; pois rejeitaram meus juízos, e não andaram conforme meus estatutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Portanto assim diz o Senhor DEUS: Por haverdes vos rebelado mais que as nações que estão ao redor de vós, não haverdes andado em meus estatutos, nem obedecido minhas leis, nem sequer conforme as leis das nações que estão ao redor de vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Por isso assim diz o Senhor DEUS: Eis que eu, eu mesmo, estou contra ti; e farei julgamentos no meio de ti diante dos olhos das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'E farei em ti o que nunca fiz, nem jamais farei coisa semelhante, por causa da todas as tuas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Por isso os pais comerão aos filhos no meio de ti, e os filhos comerão a seus pais; e farei em ti julgamentos, e espalharei a todos os ventos todos os teus sobreviventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Portanto, vivo eu,diz o Senhor DEUS, (por teres profanado meu santuário com todas as tuas coisas detestáveis, e com todas as tuas abominações), que certamente eu também te quebrantarei; meu olho não perdoará, nem terei eu misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'A terceira parte de ti morrerá de pestilência, e será consumida de fome no meio de ti; a outra terceira parte cairá à espada ao redor de ti; e outra terceira parte espalharei a todos os ventos, e atrás deles desembainharei a espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Assim se cumprirá minha ira, e farei repousar meu furor neles, e me consolarei; e saberão que eu, o SENHOR, tenho falado em meu zelo, quando tiver cumprido meu furor neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'E te tonarei em desolação e em humilhação entre as nações que estão ao redor de ti, diante dos olhos de todos os que passarem por perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'E a humilhação e a infâmia servirão de lição e espanto às nações que estão ao redor de ti, quando eu executar em ti julgamentos com ira e com furor, e com enfurecidos castigos. Eu, o SENHOR, falei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Quando eu enviar contra eles as más flechas da fome, que servirão para destruição, as quais eu mandarei para vos destruir, então aumentarei a fome sobre vós, e destruirei vosso sustento de pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'E enviarei sobre vós a fome, e animais ruins, que vos deixarão sem filhos; e a pestilência e o sangue passarão por ti; e trarei a espada sobre ti. Eu, o SENHOR, falei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Filho do homem, põe teu rosto direcionado aos montes de Israel, e profetiza contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'E digas: Montes de Israel, ouvi palavra do Senhor DEUS; assim diz o Senhor DEUS aos montes e aos morros, aos ribeiros e aos vales: Eis que eu, eu mesmo, trarei a espada sobre vós, e destruirei vossos altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'E vossos altares serão arruinados, e vossas imagens do sol serão quebradas; e derrubarei vossos mortos diante de vossos ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'E porei os cadáveres dos filhos de Israel diante de seus ídolos; e espalharei vossos ossos ao redor de vossos altares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Em todas as vossas habitações as cidades serão destruídas, e os altos serão arruinados, para que vossos altares sejam destruídos e arruinados; e vossos ídolos se quebrem, e deixem de existir; e vossas imagens do sol sejam cortadas, e desfeitas vossas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'E os mortos cairão no meio de vós; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Porém deixarei um restante, para que tenhais alguns que escapem da espada entre as nações, quando fordes dispersos pelas terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Então os que escaparem de vós se lembrarão de mim entre as nações para onde forem levados em cativeiro; lembrarão de como eu me quebrantei por causa de seu coração infiel, que se desviou de mim, e por causa de seus olhos, que se prostituíram atrás seus ídolos; e terão nojo de si mesmos, por causa das maldades que fizeram em todas as suas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'E saberão que eu sou o SENHOR; não foi em vão que falei que lhes faria este mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Assim diz o Senhor DEUS: Bate com tua mão, e pisa com teu pé, e dize: Ai de todas as malignas abominações da casa de Israel! Pois cairão pela espada, pela fome, e pela pestilência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'O que estiver longe morrerá de pestilência; e o que estiver perto cairá a espada; e o que restar e for cercado morrerá de fome; assim cumprirei meu furor contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Então sabereis que eu sou o SENHOR, quando seus mortos estiverem em meio de seus ídolos, ao redor de seus altares, em todo morro alto, em todos os cumes dos montes, debaixo de toda árvore verde, e debaixo de todo carvalho espesso, lugares onde ofereciam incenso de cheiro suave a todos os seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Pois estenderei minha mão sobre eles, e tornarei a terra em desolação e vazio, mais que o deserto da região de Dibla, em todas as suas habitações; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Depois a palavra do SENHOR veio a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'E tu, filho do homem, assim diz o Senhor DEUS à terra de Israel: É o fim, o fim vem sobre os quatro cantos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Agora veio o fim sobre ti; pois enviarei minha ira sobre ti, e te julgarei conforme teus caminhos; e trarei sobre ti todas as tuas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'E meu olho não te poupará, nem terei compaixão; ao invés disso trarei teus caminhos sobre ti, e tuas abominações estarão no meio de ti; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Assim diz o Senhor DEUS: Uma calamidade, eis que vem uma calamidade incomparável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Vem o fim, o fim vem; despertou-se contra ti; eis que vem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'A manhã vem para ti, ó morador da terra; o tempo vem, chegado é o dia em que haverá desespero, e não gritos de alegria sobre os montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Agora logo derramarei meu furor sobre ti, cumprirei minha ira contra ti; e te julgarei conforme teus caminhos; e porei sobre ti todas as tuas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'E meu olho não poupará, nem terei compaixão; trarei sobre ti conforme teus caminhos, e no meio de ti estarão tuas abominações; e sabereis que eu, o SENHOR, sou o que firo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Eis aqui o dia, eis que vem; a manhã já saiu; já floresceu a vara, a soberba já gerou brotos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'A violência se levantou em vara de maldade; nada restará deles, nem de sua multidão, nem de sua riqueza, nem de seu prestígio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'O tempo veio, achegou-se o dia; o comprador não se alegre, nem o vendedor entristeça; porque a ira está sobre toda sua multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Pois o vendedor não voltará ao que foi vendido, enquanto estiverem vivos; porque a visão sobre toda sua multidão não será cancelada; e por causa de sua iniquidade, ninguém poderá preservar sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Já tocaram trombeta, e prepararam tudo; porém ninguém vai à batalha, pois minha ira está sobre toda sua multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Por fora a espada, por dentro a pestilência e a fome; o que estiver no campo morrerá à espada; e o que estiver na cidade, a fome e a pestilência o consumirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'E os sobreviventes que deles escaparem estarão pelos montes como pombas dos vales, todos gemendo, cada um por sua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Todas mãos serão fracas, e todos joelhos serão frouxos como águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'E se vestirão de saco, e o tremor os cobrirá; em todos os rostos haverá vergonha, e todas as suas cabeças serão raspadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Lançarão sua prata pelas ruas, e seu ouro será como algo imundo; nem sua prata nem seu ouro poderá livrá-los no dia do furor do SENHOR; não saciarão suas almas, nem encherão suas entranhas; pois isto é o tropeço de sua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'E tornaram a glória de seu ornamento em orgulho, e nela fizeram nela imagens de suas abominações e de suas coisas detestáveis; por isso eu a tornarei em coisa imunda para eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'E a entregarei em mãos de estrangeiros para ser saqueada, e aos perversos da terra para servir de despojo; e a profanarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'E desviarei meu rosto deles, e profanarão meu lugar secreto; pois nele entrarão destruidores, e o profanarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Faze correntes, porque a terra está cheia de julgamentos de sangues, e a cidade está cheia de violência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Por isso farei vir os mais malignos das nações, que tomarão posse de suas casas; e farei cessar a arrogância dos poderosos, e seus santuários serão profanados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'A aflição está vindo; e buscarão a paz, porém não haverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Virá desastre sobre desastre, e haverá rumor sobre rumor; então buscarão visão de profeta; porém a Lei perecerá do sacerdote, e também o conselho dos anciãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'O rei lamentará, e o príncipe se vestirá de assolamento, e as mãos do povo da terra serão atemorizadas; conforme seu caminho farei com eles, e com os seus juízos os julgarei; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'E sucedeu no sexto ano, no sexto mês,aos cinco do mês, estando eu sentado em minha casa, e os anciãos de Judá estavam sentados diante de mim, que ali a mão do Senhor DEUS caiu sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'E olhei, e eis uma semelhança, com aparência de fogo; desde a aparência de sua cintura para baixo, era fogo; e desde sua cintura para cima, com a aparência de um resplendor, como a cor de âmbar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'E estendeu a forma de uma mão, e tomou-me pelos cabelos de minha cabeça; e o espírito me levantou entre a terra e o céu, e me trouxe a Jerusalém em visões de Deus, até a entrada da porta de dentro que está voltada ao norte, onde estava o lugar da imagem dos ciúmes, que provoca ciúmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'E eis que a a glória do Deus de Israel estava ali, conforme a visão que eu tinha visto no vale.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'E disse-me: Filho do homem, levanta agora teus olhos para o norte. E levantei meus olhos para o norte, e eis que ao lado norte, junto à porta do altar, estava a imagem dos ciúmes na entrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Então me disse: Filho do homem, vês tu o que eles estão fazendo? As grandes abominações que a casa de Israel faz aqui, para me afastar de meu santuário? Porém ainda voltarás a ver abominações maiores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'E levou-me à porta do pátio; então olhei, e eis que havia um buraco na parede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'E disse-me: Filho do homem, cava agora naquela parede. E cavei na parede, e eis que havia uma porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Então me disse: Entra, e vê as malignas abominações que eles fazem aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'E entrei, e olhei, e eis toda figura de répteis, e animais abomináveis, e todos os ídolos da casa de Israel, que estavam pintados na parede ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'E diante deles estavam setenta homens dos anciãos da casa de Israel, com Jazanias filho de Safã, que estava no meio deles, cada um com seu incensário em sua mão; e uma espessa nuvem de perfume subia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Então me disse: Filho do homem, viste as coisas que os anciãos da casa de Israel fazem nas trevas, cada um em suas câmaras pintadas? Pois eles dizem: O SENHOR não nos vê; o SENHOR abandonou a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'E disse-me: Ainda voltarás a ver abominações maiores que estes fazem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'E me levou à entrada da porta da casa do SENHOR, que está ao lado norte; e eis ali mulheres que estavam sentadas, chorando a Tamuz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Então me disse: Viste isto,filho do homem? Ainda voltarás a ver abominações maiores que estas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'E ele me levou ao pátio de dentro da casa do SENHOR; e eis que estavam à entrada do templo do SENHOR, entre o pórtico e o altar, cerca de vinte e cinco homens, com suas costas voltadas ao templo do SENHOR e seus rostos ao oriente, e eles se prostravam ao oriente, para o sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Então me disse: Viste isto,filho do homem? Por acaso é pouco para a casa de Judá fazer as abominações que fazem aqui? Pois eles têm enchido a terra de violência, e voltam a irritar-me, porque eis que põem o ramo em suas narinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Por isso eu também os tratarei com furor; meu olho não poupará, nem terei compaixão; e ainda que gritem em meus ouvidos com alta voz, mesmo assim não os ouvirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Então ele gritou em meus ouvidos com alta voz, dizendo: Fazei chegar os encarregados de punir a cidade, e cada com sua armas destruidoras em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'E eis que seis homens vinham do caminho da porta alta, que está voltada para o norte, e cada um trazia em sua mão sua arma destruidora. E entre eles havia um homem vestido de linho, com um estojo de escrivão em sua cintura; e entraram, e se puseram junto ao altar de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'E a glória do Deus de Israel levantou-se do querubim sobre o qual estava, até a entrada da casa; e chamou ao homem vestido de linho, que tinha o estojo de escrivão à sua cintura,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'E o SENHOR lhe disse: Passa por meio da cidade, por meio de Jerusalém; e põe uma sinal na testa dos homens que suspiram e que gemem por causa de todas as abominações que se cometem no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'E aos outros disse a meus ouvidos: Passai pela cidade depois dele, e feri; vossos olhos não poupem, nem tenhais compaixão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Matai velhos, rapazes e virgens, meninos e mulheres, até os acabardes por completo; porém não chegueis a toda pessoa sobre a qual houver o sinal; e começai desde meu santuário. Então começaram desde os anciãos que estavam diante do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'E disse-lhes: Contaminai a casa, e enchei os pátios de mortos; saí. Então saíram, e feriram na cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'E aconteceu que, havendo os ferido, e eu ficando de resto, caí sobre meu rosto, clamei, e disse: Ah, Senhor DEUS! Por acaso destruirás todo o restante de Israel, derramando tua ira sobre Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Então me disse: A maldade da casa de Israel e de Judá é extremamente grande; e a terra se encheu de sangues, e a cidade se encheu de perversidade; pois dizem: O SENHOR abandonou a terra, e o SENHOR não vê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Por isso quanto a mim, meu olho não poupará, nem terei compaixão; retribuirei o caminho deles sobre suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'E eis que o homem vestido de linho, que tinha o estojo na cintura, trouxe resposta, dizendo: Fiz conforme o que me mandaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Então olhei, e eis que sobre o firmamento que estava sobre a cabeça dos querubins, havia como uma pedra de safira, com a aparência de um trono, que apareceu sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'E falou ao homem vestido de linho, dizendo: Entra por entre as rodas debaixo dos querubins e enche tuas mãos de brasas acesas dentre os querubins, e as espalha sobre a cidade. E entrou diante de meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'E os querubins estavam à direita da casa quando aquele homem entrou; e a nuvem encheu o pátio de dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Então a glória do SENHOR se levantou de sobre o querubim para a entrada da casa; e a casa se encheu de uma nuvem, e o pátio se encheu do resplendor da glória do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'E o som das asas dos querubins era ouvido até o pátio de fora, como a voz do Deus Todo-Poderoso quando fala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'E sucedeu que, quando ele mandou ao homem vestido de linho, dizendo: Toma fogo dentre as rodas, dentre os querubins, então ele entrou, e ficou junto às rodas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'E um querubim estendeu sua mão dentre os querubins ao fogo que estava entre os querubins, e tomou-o, e o deu nas mãos do que estava vestido de linho; o qual o tomou, e saiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'E apareceu nos querubins a forma de uma mão humana debaixo de suas asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Então olhei, e eis que quatro rodas estavam junto aos querubins, uma roda junto a um querubim, e outra roda junto ao outro querubim; e o aparência das rodas era como o de pedra de berilo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Quanto à aparência delas, as quatro tinham uma mesma forma, como se estivesse uma roda no meio da outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Quando se moviam, movimentavam-se sobre seus quatro lados; não se viravam quando moviam, mas para o lugar aonde se voltava a cabeça, iam atrás; nem se viravam quando moviam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'E toda o seu corpo, suas costas, suas mãos, suas asas, e as rodas, estavam cheias de olhos ao redor; os quatro tinham suas rodas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Quanto às rodas, eu ouvi que foram chamadas de “roda giratória”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'E cada um tinha quatro rostos: o primeiro rosto era de querubim; o segundo rosto, de homem; o terceiro rosto, de leão; e o quarto rosto, de águia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'E os querubins se levantaram; este é o mesmo ser que vi no rio de Quebar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'E quando os querubins se moviam, as rodas se moviam junto com eles; e quando os querubins levantavam suas asas para se levantarem da terra, as rodas também não se viravam de junto a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Quando eles paravam, elas paravam; e quando eles se levantavam, elas levantavam com eles: porque o espírito dos seres estava nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Então a glória do SENHOR saiu de sobre a entrada da casa, e se pôs sobre os querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'E os querubins levantaram suas asas, e subiram da terra diante de meus olhos, quando saíram; e as rodas estavam ao lado deles; e pararam à entrada da porta oriental da casa do SENHOR, e a glória do Deus de Israel estava por cima deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Estes são os seres que vi debaixo do Deus de Israel no rio de Quebar; e notei que eram querubins.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Cada um tinha quatro rostos, e cada um quatro asas; e havia semelhança de mãos humanas debaixo de seus asas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'E a semelhança de seus rostos era a dos rostos que vi junto ao rio de Quebar, suas aparências, e eles mesmos; cada um se movia na direção de seu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Então o Espírito me levantou, e me trouxe à porta oriental da Casa do SENHOR, que está voltada para o oriente; e eis que estavam à entrada da porta vinte e cinco homens; e no meio deles vi a Jazanias filho de Azur, e a Pelatias filho de Benaías, príncipes do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'E disse-me: Filho do homem, estes são os homens que tramam perversidade, e dão mau conselho nesta cidade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Os quais dizem: Não está perto o tempo de edificar casas; esta cidade é a caldeira, e nós a carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Por isso profetiza contra eles; profetiza, ó filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'E caiu sobre mim o Espírito do SENHOR, e disse-me: Dize: Assim diz o SENHOR: Assim vós dizeis, ó casa de Israel; porque eu sei todas as coisas que sobem a vosso espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Multiplicastes vossos mortos nesta cidade, e enchestes suas ruas de mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Portanto, assim diz o Senhor DEUS: Vossos mortos que deitastes no meio dela, esses são a carne, e ela é a caldeira; porém eu vos tirarei do meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Temestes a espada, e a espada trarei sobre vós, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'E vos tirarei do meio dela, e vos entregarei nas mãos de estrangeiros; e eu farei julgamentos entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Pela espada caireis; na fronteira de Israel vos julgarei, e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Esta cidade não vos servirá de caldeira, nem sereis vós a carne no meio dela; na fronteira de Israel eu vos julgarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'E sabereis que eu sou o SENHOR; pois vós não andastes em meus estatutos, nem fizestes meus juízos; em vez disso fizestes conforme os juízos das nações que estão ao redor de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'E aconteceu que, enquanto eu estava profetizando, Pelatias filho de Benaías faleceu. Então caí sobre meu rosto, clamei com alta voz, e disse: Ah, Senhor DEUS! Consumirás tu o resto de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Então veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Filho do homem, teus irmãos, são teus irmãos, os homens de teu parentesco e toda a casa de Israel, ela toda são a quem os moradores de Jerusalém disseram: Afastai-vos do SENHOR; a terra é dada a nós em possessão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Por isso dize: Assim diz o Senhor DEUS: Ainda que os tenha lançado longe entre as nações, e tenha os dispersado pelas terras, contudo por um pouco tempo eu lhes serei por santuário nas terras para onde vieram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Por isso dize: Assim diz o Senhor DEUS: Eu vos ajuntarei dos povos, e vos recolherei das terras as quais fostes dispersos, e vos darei a terra de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'E virão para lá, e tirarão dela todas suas coisas detestáveis e todas as suas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'E lhes darei um mesmo coração, e um espírito novo darei em suas entranhas; e tirarei o coração de pedra de sua carne, e lhes darei coração de carne;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Para que andem em meus estatutos e guardem meus juízos e os pratiquem; e eles serão meu povo, e eu serei seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Mas quanto a aqueles cujo coração anda conforme o desejo de suas coisas detestáveis e de suas abominações, eu retribuirei seu caminho sobre suas cabeças, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Depois os querubins levantaram suas asas, e as rodas ao lado deles; e a glória do Deus de Israel estava por cima deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'E a glória do SENHOR subiu do meio da cidade, e se pôs sobre o monte que está ao oriente da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Depois o Espírito me levantou, e levou-me à Caldeia, aos do cativeiro, em visão do Espírito de Deus. E a visão que vi foi embora acima de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'E falei aos do cativeiro todas as palavras do SENHOR que ele havia me mostrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Filho do homem, tu habitas em meio de uma casa rebelde, os quais têm olhos para ver mas não veem, têm ouvidos para ouvir, mas não ouvem; pois eles são uma casa rebelde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Portanto tu, filho do homem, prepara-te bagagem de partida, e parte-te de dia diante dos olhos deles; e tu partirás de teu lugar para outro lugar diante dos olhos deles; pode ser que vejam, ainda que eles sejam uma casa rebelde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Assim tirarás tuas bagagem, como bagagem de partida, durante dia diante de seus olhos; então tu sairás à tarde diante de seu olhos, como quem sai para se partirem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Diante de seus olhos cava um buraco na parede, e tira por ele a bagagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Diante de seus olhos os levarás sobre teus ombros, ao anoitecer os tirarás; cobrirás teu rosto, para que não vejas a terra; pois eu fiz de ti por sinal à casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'E eu fiz assim como me foi mandado; tirei minha bagagem de dia, como bagagem de partida, e à tarde cavei um buraco na parede com a mão; tirei-os de noite, e os levei sobre os ombros diante dos olhos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'E veio a mim palavra do SENHOR pela manhã, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Filho do homem, por acaso a casa de Israel, aquela casa rebelde, não te perguntou: O que estás fazendo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Dize-lhes: Assim diz o Senhor DEUS: esta revelação é para o príncipe em Jerusalém, e para toda a casa de Israel que está em meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Dize: Eu sou vosso sinal; tal como eu fiz, assim se fará a eles; serão removidos; irão em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'E o príncipe que está entre eles, levará nos ombros sua bagagem de noite, e sairá; na parede cavarão uma abertura para saírem por ela; cobrirá seu rosto para não ver com seus olhos a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Também estenderei minha rede sobre ele, e ele será preso em meu laço, e eu o levarei à Babilônia, à terra de caldeus; porém ele não a verá, ainda que morrerá ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'E a todos os que estiverem ao redor dele para ajudá-lo, e a todas as suas tropas espalharei a todos os ventos, e desembainharei espada atrás deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Assim saberão que eu sou o SENHOR, quando eu os espalhar entre as nações, e os dispersar pelas terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Porém deixarei alguns poucos sobreviventes da espada, da fome, e da pestilência, para que contem todas as suas abominações entre as nações para onde forem; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Então veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Filho do homem, come teu pão com tremor, e bebe tua água com estremecimento e com ansiedade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'E dize ao povo da terra: Assim diz o Senhor DEUS sobre os moradores de Jerusalém, e sobre a terra de Israel: Comerão seu pão com ansiedade, e com espanto beberão sua água; porque sua terra será desolada de seu conteúdo, por causa da violência de todos os que nela habitam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'E as cidades habitadas serão desoladas, e a terra se tornará em deserto; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Filho do homem, que ditado é este que vós tendes vós terra de Israel, que diz: Os dias se prolongarão, e toda visão perecerá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Portanto dize-lhes: Assim diz o Senhor DEUS: Farei cessar este ditado, e não usarão mais esta frase em Israel. Ao invés disso, dize-lhes: Os dias chegaram, e o cumprimento de toda visão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Porque não haverá mais uma visão falsa sequer, nem haverá adivinhação lisonjeira no meio da casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Pois eu, o SENHOR, falarei; a palavra que eu falar se cumprirá; não se prolongará mais; porque em vossos dias, ó casa rebelde, falarei a palavra e a cumprirei, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Também veio a mim palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Filho do homem, eis que os da casa de Israel dizem: A visão que este vê é para muitos dias, e ele profetiza para tempos distantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Por isso dize-lhes: Assim diz o Senhor DEUS: Nenhuma das minhas palavras se prolongará mais; e palavra que eu falei se cumprirá, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Filho do homem, profetiza contra os profetas de Israel que profetizam; e dize aos que profetizam de seu próprio coração: Ouvi a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Assim diz o Senhor DEUS: Ai dos profetas tolos, que andam atrás de seu próprio espírito, e que nada viram!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Teus profetas são como raposas nos desertos, ó Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Não subistes às brechas, nem restaurastes o muro para a casa de Israel, para estardes na batalha no dia do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Eles veem falsidade e adivinhação de mentira. Falam: O SENHOR disse, mas o SENHOR não os enviou; e ainda esperam que a palavra se cumpra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Por acaso não vedes visão falsa, e não falais adivinhação de mentira, quando dizeis, O SENHOR disse, sem que eu tenha falado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Portanto assim diz o Senhor DEUS: Dado que falais falsidade e vedes mentira, portanto eis que eu sou contra vós, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'E minha mão será contra os profetas que veem falsidade, e adivinham mentira; não estarão na congregação do meu povo, nem estarão inscritos no livro da casa de Israel, nem voltarão para a terra de Israel; e sabereis que eu sou o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Portanto, por andarem enganando a meu povo, dizendo: Paz, sem que houvesse paz, e quando um edifica uma parede, eis que eles a rebocam com cal solta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Dize aos que rebocam com cal solta, que cairá; haverá uma grande pancada de chuva, e vós ó grandes pedras de granizo, caireis, e um vento tempestuoso a fenderá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'E eis que, quando a parede tiver caído, não vos dirão: Onde está a reboco com que rebocastes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Por isso assim diz o Senhor DEUS: Farei com que rompa um vento tempestuoso em meu furor e haverá uma grande pancada de chuva em minha ira, e grande pedras de granizo em indignação, para destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'E derrubarei a parede que vós rebocastes com cal solta, e a lançarei em terra, e seu fundamento ficará descoberto; assim cairá, e perecereis no meio dela; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Assim cumprirei meu furor contra a parede, e contra os que a rebocaram com lodo solto; e vos direi: Já não há a parede, nem os que a rebocavam,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Os profetas de Israel que profetizam sobre Jerusalém, e veem para ela visão de paz, sem que haja paz,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'E tu, filho do homem, dirige teu rosto às filhas de teu povo que profetizam de seu próprio coração, e profetiza contra elas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'E dize: Assim diz o Senhor DEUS: Ai daquelas que costuram almofadas para todos os pulsos, e fazem lenços sobre as cabeças de todos os tamanhos para caçarem as almas! Por acaso caçareis as almas de meu povo, e guardareis a vossas próprias almas em vida?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Vós me profanastes para com meu povo por punhados de cevada e por pedaços de pão, matando as almas que não deviam morrer, e mantendo em vida as almas que não deviam viver, mentindo a meu povo, que escuta a mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Por isso assim diz o Senhor DEUS: Eis que eu contra vossas almofadas, com que caçais as almas como se fossem pássaros; eu as arrancarei de vossos braços, e soltarei as almas, as almas que caçais como pássaros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'E rasgarei vossos lenços, e livrarei meu povo de vossas mãos, e não mais estarão em vossas mãos para serem caçadas; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Pois com mentira entristecestes o coração do justo, ao qual eu não lhe causei dor, e fortalecestes as mãos do perverso, para que não se desviasse de seu mau caminho para se manter vivo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Portanto não mais vereis falsidade, nem mais adivinhareis adivinhação. Mas livrarei meu povo de vossas mãos, e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'E vieram a mim alguns dos anciãos de Israel, e se sentaram diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Então veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Filho do homem, estes levantaram ídolos em seus corações e puseram o tropeço de sua maldade diante de seus rostos. Por acaso devo eu deixar que me consultem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Portanto fala com eles, e dize-lhes: Assim diz o Senhor DEUS: Qualquer homem da casa de Israel que levantar a seus ídolos em seu coração, e puser o tropeço de sua maldade diante de seu rosto, e vier ao profeta, eu, o SENHOR responderei ao que vier conforme a multidão de seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Para eu tomar a casa de Israel em seus corações, pois todos se tornaram estranhos de mim por causa de seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Portanto dize à casa de Israel: Assim diz o Senhor DEUS: Convertei-vos, virai-vos de costas a vossos ídolos, e desviai vossos rostos de todas as vossas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Porque qualquer homem da casa de Israel, e dos estrangeiros que moram em Israel, que houver deixado de me seguir, e levantar seus ídolos em seu coração, e puser diante de seu rosto o tropeço de sua maldade, e vier ao profeta para me consultar por meio dele, eu, o SENHOR, lhe responderei por mim mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'E porei meu rosto contra tal homem, e farei com que ele seja um sinal e um ditado, e o cortarei do meio do meu povo; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'E se o profeta se enganar e falar alguma palavra, eu o SENHOR enganei ao tal profeta; e estenderei minha mão contra ele, e eu o destruirei do meio de meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'E levarão sua maldade; tal como a maldade do que pergunta, assim será a maldade do profeta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Para que a casa de Israel não mais se desvie de me seguir, nem se contaminem mais com todas as seus transgressões; e então serão meu povo, e eu serei seu Deus, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Filho do homem, quando uma terra pecar contra mim, rebelando-se gravemente, então estenderei minha mão contra ela, quebrarei o sustento de pão dela, mandarei nela fome, e cortarei dela homens e animais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'E ainda que estivessem no meio dela estes três homens, Noé, Daniel, e Jó, eles por sua justiça livrariam somente suas almas,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'E se eu fizer passar os animais perigosos pela terra, e eles a despojarem, e ela for tão assolada que ninguém possa passar por ela por causa dos animais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'E estes três homens estivessem no meio dela, vivo eu,diz o Senhor DEUS, que nem a filhos nem a filhas livrariam; somente eles ficariam livres, e a terra seria assolada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ou se eu trouxer a espada sobre a tal terra, e disser: Espada, passa pela terra; e eu exterminar dela homens e animais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Ainda que estes três homens estivessem nela, vivo eu,diz o Senhor DEUS, que não livrariam filhos nem filhas; somente eles ficariam livres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Ou se eu mandar pestilência sobre tal terra, e derramar meu furor sobre ela com sangue, para exterminar dela homens e animais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Ainda que Noé, Daniel, e Jó estivessem no meio dela, vivo eu,diz o Senhor DEUS, que não livrariam filho nem filha; eles por sua justiça livrariam suas próprias almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Porque assim diz o Senhor DEUS: Quanto mais se eu enviar meus quatro calamitosos julgamentos, espada, fome, animais perigosos, e pestilência, contra Jerusalém, para exterminar dela homens e animais!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Porém eis que restarão nela alguns sobreviventes, filhos e filhas, que serão transportados. Eis que eles chegarão até vós, e vereis seu caminho e seus feitos; e ficareis consolados do mal que eu trouxe sobre Jerusalém, de tudo que trouxe sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'E eles vos consolarão quando virdes seu caminho e seus feitos; e sabereis que não sem razão que fiz tudo quanto fiz nela,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Filho do homem, em que é a madeira da videira é melhor que toda madeira? Ou o que é o sarmento entre as madeiras do bosque?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Por acaso tomam dele madeira para fazer alguma obra? Toma-se dele alguma estaca para pendurar nela algum vaso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Eis que é posto no fogo para ser consumido; suas duas pontas o fogo consome, e seu meio fica queimado. Por acaso serviria para alguma obra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Eis que quando estava inteiro não se fazia dele obra; menos ainda depois de consumido pelo fogo, tendo se queimado, servir para obra alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Portanto assim diz o Senhor DEUS: Tal como a madeira da videira entre as madeiras do bosque, a qual entreguei ao fogo para que seja consumida, assim entregarei os moradores de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Pois porei meu rosto contra eles; ainda que tenham saído do fogo, o fogo os consumirá; e sabereis que eu sou o SENHOR, quando tiver posto meu rosto contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'E tonarei a terra em desolação, pois transgrediram gravemente,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Filho do homem, notifica a Jerusalém suas abominações,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'E dize: Assim diz o Senhor DEUS a Jerusalém: Tua origem e teu nascimento procedem da terra de Canaã; teu pai era amorreu, e tua mãe Heteia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'E quanto a teu nascimento, no dia que nasceste não foi cortado o teu umbigo, nem foste lavada com água para ficares limpa; nem foste esfregada com sal, nem foste envolvida em faixas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Não houve olho algum que se compadecesse de ti, para te fazer algo disto, tendo misericórdia; ao invés disso, foste lançada sobre a face do campo, por nojo de tua alma, no dia em que nasceste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'E quando passei junto a ti, vi-te suja em teu sangue, e te disse em teu sangue: Vive; e te disse em teu sangue: Vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Eu te multipliquei como o broto do campo, e cresceste, e engrandeceste; e chegaste à grande formosura; os seios te cresceram, e teu pelo cresceu; porém estavas nua e descoberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'E quando passei junto a ti, e te vi, e eis que teu tempo era tempo de amores; e estendi meu manto sobre ti, e cobri tua nudez; e prestei juramento a ti, e entrei em pacto contigo, e foste minha diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Então te lavei com água, e te enxaguei de teu sangue, e te ungi com óleo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'E te vesti de bordado, calcei-te com couro, cingi-te de linho fino, e te cobri de seda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'E te adornei com ornamentos, e pus braceletes em teus braços, e colar em teu pescoço;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'E pus joias pendente em teu nariz, argolas em tuas orelhas, e uma linda coroa em tua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'E foste adornada de ouro e de prata, e teu vestido foi linho fino, e seda, e bordado; comeste farinha fina, mel, e azeite; foste muito formosa, e prosperaste até ser rainha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'A tua fama percorreu entre as nações por causa da tua beleza; porque era perfeita, por causa da minha glória que eu havia posto sobre ti, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Porém confiaste na tua beleza, e te prostituíste por causa da tua fama, e derramaste tuas prostituições a todo que passava, para que fosse dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'E tomaste de teus vestidos, fizeste altares de diversas cores, e te prostituíste sobre eles: coisa semelhante não virá, nem será assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Tomaste também os vasos de teu ornamento, que eu te dei de meu ouro e de minha prata, e fizeste para ti imagens de homens, e te prostituíste com elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'E tomaste teus vestidos bordados, e as cobriste; e puseste meu óleo e meu perfume diante delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'E o meu pão também que eu te dei, a farinha fina, o azeite, e o mel, com que eu te sustentava, puseste diante delas, como cheiro suave; e assim foi, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Além disto, tomaste teus filhos e tuas filhas, que havias gerado para mim, e os sacrificaste a elas para que fossem consumidas. Por acaso são poucas as tuas prostituições?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'E mataste meus filhos, e os entregastes a elas para que passassem pelo fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'E em todas as tuas abominações e tuas prostituições, não te lembraste dos dias de tua juventude, quando estavas nua e descoberta, quando estavas suja em teu sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'E sucedeu que, depois de toda tua maldade (Ai, ai de ti! diz o Senhor DEUS),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Edificaste para ti uma câmara, e fizeste para ti altares em todas as ruas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Em cada canto de caminho edificaste teu altar, fizeste abominável tua formosura, e abriste tuas pernas a todo que passava; e assim multiplicaste tuas prostituições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'E te prostituíste com os filhos do Egito, teus vizinhos, grandemente promíscuos; e multiplicaste tuas prostituições, para me provocar à ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Por isso eis que estendi minha mão sobre ti, e diminuí tua provisão; e te entreguei à vontade das que te odeiam, as filhas dos filisteus, as quais se envergonhavam de teu caminho pecaminoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Também te prostituíste com os filhos da Assíria, por seres insaciável; e te prostituindo com eles, nem ainda te fartaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Ao invés disso multiplicaste tuas prostituições na terra de Canaã até a Caldeia; e nem ainda com isso com isto te fartaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Como está fraco o teu coração, diz o Senhor DEUS, tendo tu feito todas estas coisas, obras de uma poderosa prostituta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Edificando tu tuas câmaras ao canto de cada caminho, e fazendo teus altares em cada rua; e nem sequer foste como a prostituta, pois desprezaste o pagamento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Mas foste como uma mulher adúltera, que em lugar de seu marido recebe a estranhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Todas as prostitutas são pagas; mas tu deste teus pagamentos a todos os teus amantes; e lhes deste presentes, para que viessem a ti dos lugares ao redor, por causa de tuas prostituições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Assim acontece contigo o contrário das mulheres que se prostituem, porque ninguém te buscou para prostituir; pois quando pagas ao invés de receber pagamento, tu tens sido o contrário das outras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Portanto, ó prostituta, ouve a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Assim diz o Senhor DEUS: Visto que se derramou teu dinheiro, e tuas vergonhas foram descobertas por tuas prostituições com teus amantes, como também com todos os ídolos de tuas abominações, e no sangue de teus filhos, os quais lhes deste;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Por isso eis que ajuntarei todos os teus amantes com os quais tiveste prazer, e também todos os que amaste, com todos quantos tu odiaste; e os ajuntarei contra ti ao redor, e descobrirei tua nudez diante deles, para que vejam toda a tua nudez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'E eu te julgarei pelas leis das adúlteras, e das que derramam sangue; e te entregarei ao sangue do furor e do ciúme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'E te entregarei na mão deles; e eles destruirão tua câmara, derrubarão teus altares, e te despirão de teus vestidos; e tomarão as joias de teu ornamento, e te deixarão nua e descoberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Então farão subir contra ti uma multidão, e te apedrejarão com pedras, e te atravessarão com suas espadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'E queimarão tuas casas a fogo, e executarão julgamentos contra ti, diante dos olhos de muitas mulheres; e te farei cessar de ser prostituta, nem darás mais pagamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Assim farei descansar meu furor sobre ti, meu ciúme se afastará de ti; eu me aquietarei, e não mais me indignarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Porque não te lembraste dos dias de tua juventude, e me provocaste à ira com tudo isto, por isso eis que também eu tornarei o teu caminho sobre tua cabeça, diz o Senhor DEUS; por acaso não cometeste tu tal promiscuidade além de todas as tuas abominações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Eis que todo aquele que usa de provérbios fará provérbio sobre ti, dizendo: Tal mãe, tal filha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Tu és filha de tua mãe, que tinha nojo de seu marido e de seus filhos; e tu és irmã de tuas irmãs, que tinham nojo de seus maridos e de seus filhos; vossa mãe foi Heteia, e vosso pai amorreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'E tua irmã maior é Samaria, ela e suas filhas, a qual habita à tua esquerda; e tua irmã menor que tu é Sodoma com suas filhas, a qual habita à tua direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Porém não andaste em seus caminhos, nem fizeste conforme suas abominações; mas em vez disso, como se fosse muito pouco, tu te corrompeste ainda mais que elas em todos os teus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Vivo eu, diz o Senhor DEUS, que tua irmã Sodoma e suas filhas não fizeram tanto como fizeste tu e tuas filhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Eis que esta foi a maldade de tua irmã Sodoma: ela e suas filhas tiveram soberba, fartura de pão, e abundância de conforto; porém nunca ajudaram a mão do pobre e do necessitado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'E se tornaram arrogantes, e fizeram abominação diante de mim, por isso eu as tirei quando vi isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Também Samaria não cometeu sequer a metade de teus pecados; e tu multiplicaste tuas abominações mais que elas, e fizeste tuas irmãs parecerem justas em comparação a todas as tuas abominações que fizeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Tu também, leva tua vergonha, tu que julgaste em favor de tuas irmãs por meio de teus pecados, que fizeste mais abomináveis que elas; mais justas são que tu; envergonha-te, pois, tu também, e leva tua vergonha, pois justificaste a tuas irmãs.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Eu, pois, os restaurarei de seu infortúnio, os cativos de Sodoma e de suas filhas, e os cativos de Samaria e de suas filhas, e os cativos do teu cativeiro entre elas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Para que leves tua vergonha, e sejas envergonhada por tudo que fizeste, dando-lhes tu consolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Enquanto tuas irmãs, Sodoma com suas filhas e Samaria com suas filhas, voltarão ao seu primeiro estado; também tu e tuas filhas voltareis a vosso primeiro estado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Não foi tua irmã Sodoma mencionada em tua boca no tempo de tuas soberbas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Antes que tua maldade fosse descoberta? Semelhantemente agora é teu tempo de humilhação pelas filhas de Síria e de todos que estavam ao redor dela, e as filhas dos filisteus ao redor, que te desprezam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Tu levarás a punição por tua perversidade e tuas abominações, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Porque assim diz o Senhor DEUS: Eu farei contigo conforme tu fizeste, que desprezaste o juramento, quebrando o pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Contudo eu me lembrarei do meu pacto contigo nos dias de tua juventude, e estabelecerei contigo um pacto eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Então te lembrarás de teus caminhos, e te envergonharás, quando receberes a tuas irmãs maiores que tu com as menores que tu, pois eu as darei a ti por filhas, porém não por teu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'E estabelecerei meu pacto contigo, e saberás que eu sou o SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Para que te lembres disso, e te envergonhes, e nunca mais abras a boca por causa de tua vergonha, quando eu me reconciliar contigo de tudo quanto fizeste, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Filho do homem, propõe um enigma, e fala uma parábola à casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'E dize: Assim diz o Senhor DEUS: Uma grande águia, de grandes asas e de comprida plumagem, cheia de penas de várias cores, veio ao Líbano, e tomou o mais alto ramo de um cedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Arrancou o topo de seus renovos, e o trouxe à terra de comércio; na cidade de mercadores ela o pôs.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'E tomou da semente da terra, e a lançou em um campo fértil; tomando-a, plantou-a junto a grandes águas, como se fosse um salgueiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'E brotou, e tornou-se uma videira larga, porém de baixa estatura; seus ramos olhavam para ela, e suas raízes estavam debaixo dela; e tornou-se uma videira, que produzia ramos e brotava renovos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'E houve outra grande águia, de grandes asas e cheia de penas; e eis que esta videira juntou suas raízes para perto dela, e estendeu seus ramos para ela desde o lugar onde estava plantada, para que fosse regada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Em uma boa terra, junto a muitas águas ela estava plantada, para produzir ramos e dar fruto, para que fosse uma videira excelente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Dize: Assim diz o Senhor DEUS: Por acaso a videira terá sucesso? Não arrancará a águia suas raízes, e cortará seu fruto, e se secará? Todas as folhas que dela brotavam se secarão; e nem é necessário um braço grande, nem muita gente, para a arrancar desde suas raízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Mas eis que, mesmo estando plantada, terá ela sucesso? Por acaso, quando o vento oriental a tocar, ela não se secará por completo? Nos canteiros de seus renovos se secará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Então veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Dize agora à casa rebelde: Por acaso não sabeis o que significam estas coisas? Dize-lhes: Eis que o rei da Babilônia veio a Jerusalém, tomou o teu rei e seus príncipes, e os levou consigo à Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'E tomou um da família real, fez pacto com ele, fazendo-lhe prestar juramento; e tomou os poderosos da terra consigo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Para que o reino ficasse humilhado, e não se levantasse; mas podendo continuar a existir se guardasse seu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Porém rebelou-se contra ele, enviando seus mensageiros ao Egito, para que lhe dessem cavalos e muita gente. Por acaso terá sucesso, ou escapará aquele que faz tais coisas? Poderá quebrar o pacto, e ainda assim escapar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Vivo eu, diz o Senhor DEUS, que morrerá em meio da Babilônia, no lugar do rei que o fez reinar, cujo juramento desprezou, e cujo pacto quebrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'E Faraó não lhe fará coisa alguma nem com grande exército, nem com muita multidão na batalha, quando levantarem cerco e edificarem fortificações para destruírem muitas vidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Porque desprezou o juramento, quebrando o pacto; e eis que havia firmado compromisso; havendo pois feito todas todas estas coisas, não escapará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Por isso assim diz o Senhor DEUS: Vivo eu, que meu juramento que ele desprezou, e meu pacto que ele quebrou, isto retribuirei sobre sua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'E estenderei sobre ele minha rede, e ficará preso em minha malha; e eu o levarei à Babilônia, e ali entrarei em juízo contra ele, por sua rebeldia com que se rebelou contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'E todos os seus fugitivos com todas as suas tropas cairão à espada, e os que restarem serão dispersos a todos os ventos; e sabereis que fui eu, o SENHOR, que falei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Assim diz o Senhor DEUS: Também eu tomarei do topo daquele alto cedro, e o plantarei; do mais alto de seus renovos cortarei o mais tenro, e eu o plantarei sobre um monte alto e sublime;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'No monte alto de Israel o plantarei, e produzirá ramos, dará fruto, e se tronará um cedro excelente; e habitarão debaixo dele todas as aves, todos os que voam; e na sombra de seus ramos habitarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Assim todas os árvores do campo saberão que eu, o SENHOR, rebaixei a árvore alta, levantei a árvore baixa, sequei a árvore verde, e tornei verde a árvore seca. Eu, o SENHOR, falei, e farei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'O que vós pensais, vós que dizeis este provérbio sobre a terra de Israel, dizendo: Os pais comeram uvas verdes, mas foram os dentes dos filhos que se estragaram?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Vivo eu,diz o Senhor DEUS, que nunca mais direis este provérbio em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Eis que todas as almas são minhas; tanto a alma do pai como alma do filho são minhas; a alma que pecar, essa morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Se um homem for justo, e fizer juízo e justiça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Não comer sobre os montes, nem levantar seus olhos para os ídolos da casa de Israel, nem contaminar a mulher de seu próximo, nem se achegar à mulher menstruada,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'E a ninguém oprimir; devolver ao devedor o seu penhor, não cometer roubo, der de seu pão ao faminto, e cobrir com roupa ao nu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Não emprestar a juros, nem receber lucros; e desviar sua mão da injustiça, e fizer juízo entre dois homens com base na verdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'E andar em meus estatutos, e guardar meus juízos, para agir com base na verdade, este justo certamente viverá,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'E se ele gerar um filho ladrão, derramador de sangue, que fizer a seu irmão alguma destas coisas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, '(Ainda que o pai não faça tais coisas): como comer sobre os montes, contaminar a mulher de seu próximo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Oprimir o pobre e o necessitado, cometer roubos, não devolver o penhor, levantar seus olhos para os ídolos, praticar abominação,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Emprestar a juros, e receber lucro. Por acaso viveria? Não viverá. Ele fez todas estas abominações; certamente morrerá; o seu sangue será sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'E eis que se, por sua vez ele gerar um filho, que vir todos os pecados que seu pai fez, e olhar para não fazer conforme a eles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Não comer sobre os montes, nem levantar seus olhos para os ídolos da casa de Israel; nem contaminar a mulher de seu próximo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Nem oprimir a ninguém; nem retiver o penhor, nem cometer roubos; der de seu pão ao faminto, e cobrir com roupa ao nu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Desviar sua mão de fazer mal a o pobre, não receber juros nem lucro; e praticar meus juízos, e andar em meus estatutos, este não morrerá pela maldade de seu pai; certamente viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Seu pai, dado que fez opressão, roubou os bens do irmão, e fez o que não era bom no meio de seu povo, eis que morrerá por sua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Porém dizeis: Por que o filho não será punido pela maldade do pai? Porque o filho fez juízo e justiça, guardou todas o meus estatutos, e as praticou, certamente viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'A alma que pecar, essa morrerá; o filho não será punido pela maldade do pai, nem o pai será punido pela maldade do filho; a justiça do justo será sobre ele, e a perversidade do perverso será sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Mas se o perverso se converter de todos os seus pecados que cometeu, e passar a guardar todos os meus estatutos, e fizer juízo e justiça, certamente viverá; não morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Todas as suas transgressões que cometeu não lhe serão lembradas; por sua justiça que praticou, viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Por acaso eu prefiro a morte do ímpio?,diz o Senhor DEUS, E não que ele se converta de seus caminhos, e viva?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Mas se o justo se desviar de sua justiça, e passar a praticar maldade, e fizer conforme a todas as abominações que o perverso faz, por acaso ele viveria? Todas as suas justiças que praticou não serão lembradas; por sua transgressão com que transgrediu, e por seu pecado com que pecou, por causa deles morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Porém dizeis: O caminho do Senhor não é justo. Ouvi agora, ó casa de Israel: por acaso o meu caminho não é justo? Ou não são os vossos caminhos que são injustos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Se o justo de desviar de sua justiça, e passar a praticar maldade, ele morrerá por ela; pela maldade que cometeu, morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Porém se o perverso se desviar de sua perversidade que cometeu, e passar a praticar juízo e justiça, esse conservará sua alma em vida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Porque observou, e se converteu de todas as suas transgressões que cometera, certamente viverá, não morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Contudo a casa de Israel diz: O caminho do Senhor não é justo. Por acaso os meus caminhos não são justos, ó casa de Israel? Ou não são vossos caminhos que são injustos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Portanto eu vos julgarei a cada um conforme seus próprios caminhos, ó casa de Israel,diz o Senhor DEUS. Convertei-vos e desviai-vos de todas as vossas transgressões; e assim a maldade não será vossa queda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Lançai fora de vós todas as vossas transgressões com que transgredistes, e fazei para vós um novo coração e um novo espírito. Pois por que tendes que morrer, ó casa de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Porque eu não me agrado da morte do que morre,diz o Senhor DEUS; convertei-vos, pois, e vivereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'E tu, levanta uma lamentação sobre os príncipes de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'E dize: Quem foi tua mãe? Uma leoa deitada entre os leões; entre os leõezinhos ela criou seus filhotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'E fez crescer um de seus filhotes, que veio a ser um leãozinho; e ele aprendeu a caçar presa, e a devorar homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'E as nações ouviram dele; ele foi preso na cova delas, e o trouxeram com ganchos à terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'E quando ela viu que havia esperado muito, e que sua esperança era perdida, tomou outro de seus filhotes, e o pôs por leãozinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'E ele andou entre os leões; tornou-se um leãozinho, aprendeu a caçar presa, e devorou homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'E conheceu suas viúvas, e destruiu suas cidades; e a terra e tudo que ela continha foram devastadas à voz de seu bramido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Então foram contra sobre ele as nações das províncias de seu ao redor; estenderam sobre ele sua rede, e ele foi preso na cova delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'E o puseram em cárcere com ganchos, e o levaram ao rei da Babilônia; meteram-no em fortalezas, para que sua voz não fosse mais ouvida nos montes de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Tua mãe era como uma videira em teu sangue, plantada junto às águas; que frutificava e era cheia de ramos, por causa das muitas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'E ela tinha varas fortes para cetros de senhores; e sua estatura se levantava por encima entre os ramos; e sua altura podia ser vista com a multidão de seus ramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Porém foi arrancada com furor, derrubada na terra, e vento oriental secou seu fruto; suas fortes varas foram quebradas, e se secaram; o fogo as consumiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'E agora está plantada no deserto, em terra seca e sedenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'E saiu fogo da uma vara de seus ramos, que consumido seu fruto; de modo que nela não há mais vara forte, cetro para senhorear.Esta é a lamentação, e para lamentação servirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'E aconteceu no sétimo ano, no quinto mês,aos dez do mês, que vieram alguns dos anciãos de Israel para consultarem ao SENHOR, e se sentaram diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Então veio a mim palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Filho do homem, fala aos anciãos de Israel, e dize-lhes: Assim diz o Senhor DEUS: Viestes vós para me consultar? Vivo eu, que eu não deixarei ser consultado por vós, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Por acaso tu os julgarias, julgarias tu, ó filho do homem? Notifica-lhes as abominações de seus pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'E dize-lhes: Assim diz o Senhor DEUS: No dia em que escolhi a Israel, fiz juramento para a descendência da casa de Jacó, e me tornei conhecido por eles na terra do Egito, e fiz juramento para eles, dizendo: Eu sou o SENHOR vosso Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Naquele dia eu lhes fiz juramento de que os tiraria da terra do Egito para uma terra que eu já tinha observado para eles, que corre leite e mel, a qual é a mais bela de todas as terras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Então eu lhes disse: Cada um lance fora as abominações de seus olhos, e não vos contamineis com os ídolos do Egito. Eu sou o SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Porém eles se rebelaram contra mim, e não quiseram me ouvir; não lançaram fora as abominações de seus olhos, nem deixaram os ídolos do Egito; por isso disse que derramaria meu furor sobre eles, para cumprir meu ira contra eles no meio da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Porém fiz por favor a meu nome, para que não fosse profanado diante olhos das nações no meio das quais estavam, pelas quais eu fui conhecido diante dos olhos delas, ao tirá-los da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Por isso eu os tirei da terra do Egito, e os levei ao deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'E lhes dei meus estatutos, e lhes declarei meus juízos, os quais se o homem os fizer, por eles viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'E também lhes dei meus sábados para que servissem de sinal entre mim e eles, para que soubessem que eu sou o SENHOR, que os santifico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Mas a casa de Israel se rebelou contra mim no deserto: não andaram em meus estatutos, rejeitaram meus juízos, os quais se o homem os fizer, por eles viverá; e profanaram grandemente meus sábados. Então eu disse que derramaria meu furor sobre eles no deserto, para os consumir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Porém fiz por favor a meu nome, para que não fosse profanado diante dos olhos das nações, diante de cujos olhos os tirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Contudo eu lhes jurei no deserto de que não os traria para a terra que havia lhes dado, que corre leite e mel, a qual é a mais bela de todas as terras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Porque rejeitaram meus juízos, não andaram em meus estatutos, e profanaram meus sábados; porque seus corações seguiam seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Porém meu olho os poupou, não os destruindo, nem os consumindo no deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Em vez disso, eu disse a seus filhos no deserto: Não andeis nos estatutos de vossos pais, nem guardeis seus juízos, nem vos contamineis com seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Eu sou o SENHOR vosso Deus; andai em meus estatutos, guardai meus juízos, e os praticai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'E santificai meus sábados, e sirvam de sinal entre mim e vós, para que saibais que eu sou o SENHOR, vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mas os filhos se rebelaram contra mim; não andaram em meus estatutos, nem guardaram meus juízos fazê-los, os quais se o homem os cumprir, por eles viverá; e profanaram meus sábados. Então eu disse que derramaria meu furor sobre eles, para cumprir minha ira contra eles no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Porém contive minha mão, e fiz por favor a meu nome, para que não fosse profanado diante dos olhos das nações, diante de cujos olhos os tirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'E também lhes jurei no deserto que os espalharia entre as nações, e que os dispersaria pelas terras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Porque não praticaram meus juízos, rejeitaram meus estatutos, profanaram meus sábados, e seus olhos seguiram os ídolos de seus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Por isso eu também lhes dei estatutos que não eram bons, e juízos pelos quais não viveriam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'E os contaminei em suas ofertas, em que faziam passar pelo fogo todo primogênito, para eu os assolar, a fim de que soubessem que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Portanto, filho do homem, fala à casa de Israel, e dize-lhes: Assim diz o Senhor DEUS: Até nisto vossos pais me afrontaram quando transgrediram contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Porque quando eu os trouxe para a terra da qual eu tinha jurado que lhes daria, então olharam para todo morro alto e para toda árvore espessa, e ali sacrificaram suas sacrifícios, e ali deram suas ofertas irritantes, e ali derramaram suas ofertas de bebidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'E eu lhes disse: Que alto é esse para onde vós vais? E seu nome foi chamado Bamá até o dia de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Por isso dize à casa de Israel: Assim diz o Senhor DEUS: Por acaso não vos contaminais assim como vossos pais, e vos prostituís segundo suas abominações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Quando ofereceis vossas ofertas, e fazeis passar vossos filhos pelo fogo, vós estais contaminados com todos os vossos ídolos até hoje. E deixaria eu ser consultado por vós, ó casa de Israel? Vivo eu, diz o Senhor DEUS, que não deixarei ser consultado por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'E o que vós tendes pensado de maneira nenhuma sucederá. Pois vós dizeis: Seremos como as nações, como as famílias das terras, servindo à madeira e à pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Vivo eu, diz o Senhor DEUS, que reinarei sobre vós com mão forte, braço estendido, e ira derramada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'E vos tirarei dentre os povos, e vos ajuntarei das terras em que estais espalhados, com mão forte, braço estendido, e ira derramada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'E eu vos levarei ao deserto de povos, e ali entrarei em juízo convosco face a face,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Tal como entrei em juízo com vossos pais no deserto da terra do Egito, assim entrarei em juízo convosco, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'E vos farei passar debaixo da vara, e vos levarei em vínculo do pacto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'E separarei dentre vós os rebeldes, e os que se transgrediram contra mim; da terra de suas peregrinações eu os tirarei, mas à terra de Israel não voltarão; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'E quanto a vós, ó casa de Israel, assim diz o Senhor DEUS: Ide, servi cada um a seus ídolos, e depois, se não quereis me ouvir; mas não profaneis mais meu santo nome com vossas ofertas, e com vossos ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Porque em meu santo monte, no monte alto de Israel, diz o Senhor DEUS, ali me servirá toda a casa de Israel, ela toda, naquela terra; ali eu os aceitarei, e ali demandarei vossas ofertas, e as primícias de vossas dádivas, com todas as vossas coisas santas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Com cheiro suave vos aceitarei, quando eu vos tirar dentre os povos, e vos ajuntar das terras em que estais espalhados; e serei santificado em vós diante dos olhos das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'E sabereis que eu sou o SENHOR, quando eu vos trouxer de volta à terra de Israel, à terra da qual jurei que daria a vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'E ali vos lembrareis de vossos caminhos e de todos os vossos atos em que vos contaminastes; e tereis nojo de vós mesmos, por causa de todos os vossos pecados que tendes cometido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'E sabereis que eu sou o SENHOR, quando fizer convosco por favor a meu nome, não conforme vossos maus caminhos, nem conforme vossos atos corruptos, ó casa de Israel, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'E veio a mim palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Filho do homem, dirige teu rosto em direção ao sul, derrama tua palavra ao sul, e profetiza contra o bosque do campo do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'E dize ao bosque do sul: Ouve a palavra do SENHOR! Assim diz o Senhor DEUS: Eis que eu acenderei em ti um fogo, que consumirá em ti toda árvore verde, e toda árvore seca; a chama do fogo não se apagará, e com ela serão queimados todos os rostos, desde o sul até o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'E toda carne verá que eu, o SENHOR, o acendi; não se apagará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Então eu disse: Ah, Senhor DEUS! Eles dizem de mim: Por acaso não é este um inventor de parábolas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Filho do homem, dirige teu rosto contra Jerusalém, pronuncia contra os santuários, e profetiza contra a terra de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'E dize à terra de Israel: Assim diz o SENHOR: Eis que eu sou contra ti, e tirarei minha espada de sua bainha, e exterminarei de ti o justo e o perverso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'E dado que exterminarei de ti ao justo e o perverso, por isso minha espada sairá de sua bainha contra todos, desde o sul até o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'E todos saberão que eu, o SENHOR, tirei minha espada de sua bainha; ela nunca mais voltará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Porém tu, filho do homem, suspira com quebrantamento de lombos, e com amargura; suspira diante dos olhos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'E será que, quando te disserem: Por que tu suspiras? Então dirás: Por causa da notícia que vêm; e todo coração se dissolverá, todas as mãos se enfraquecerão, todo espírito se angustiará, e todos joelhos se desfarão em águas; eis que já vem, e ela se cumprirá, diz o Senhor DEUS');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Filho do homem, profetiza, e dize: Assim diz o Senhor DEUS: Dize: A espada, a espada está afiada, e também polida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Para degolar matança está afiada, para reluzir como relâmpago está polida. Por acaso nos alegraremos? A vara de meu filho despreza toda árvore.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'E ele a deu para polir, para usar dela com a mão; esta espada está afiada, e esta polida está, para a entregar na mão do matador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Grita e uiva, ó filho do homem; porque esta será contra meu povo, será contra todos os príncipes de Israel. Entregues à de espada são os do meu povo; portanto bate na coxa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Pois tem que haver provação. E o que seria se a vara que despreza não mais existir?diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Por isso tu, filho do homem, profetiza, e bate uma mão com outra; por que a espada se dobrará até a terceira vez, a espada dos que forem mortos; esta é espada da grande matança que os cercará,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Para que os corações desmaiem, e os tropeços se multipliquem; eu pus a ponta da espada contra todas as suas portas. Ah! Ela feita foi para reluzir, e preparada está para degolar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Ó espada,move-te; vira-te à direita, prepara-te, vira-te à esquerda, para onde quer que tua face te apontar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'E também eu baterei minhas mãos uma com a outra, e farei descansar minha ira. Eu, o SENHOR, falei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'E veio a mim a palavra de SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'E tu, filho do homem, propõe para ti dois caminhos por onde venha a espada do rei da Babilônia; ambos procederão de uma mesma terra; e põe um marco num lugar, põe um marco no começo do caminho da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Propõe um caminho, por onde venha a espada contra Rabá dos filhos de Amom, e contra Judá, contra a fortificada Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Porque o rei de Babilônia parará em uma encruzilhada, no começo de dois caminhos, para usar de adivinhação; ele sacudiu flechas, consultou ídolos, olhou o fígado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'A adivinhação será para a direita, sobre Jerusalém, para ordenar capitães, para abrir a boca à matança, para levantar a voz em grito, para pôr aríetes contra as portas, para levantar cercos, e edificar fortificações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'E isto será como uma adivinhação falsa aos olhos daqueles que com juramentos firmaram compromisso com eles; porém ele se lembrará da maldade, para que sejam presos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Portanto, assim diz o Senhor DEUS: Dado que fizestes relembrar vossas maldades, manifestando vossas rebeliões, e revelando vossos pecados em todas vossos atos; por teres feito relembrar, sereis presos com a mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'E tu, profano e perverso príncipe de Israel, cujo dia do tempo do fim da maldade virá,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Assim diz o Senhor DEUS: Tira o turbante, tira a coroa; esta não será a mesma; ao humilde exaltarei, e ao exaltado humilharei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Ruína! Ruína! Ruína a farei; e ela não será restaurada, até que venha aquele a quem lhe pertence por direito, e a ele a darei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'E tu, filho do homem, profetiza, e dize: Assim diz o Senhor DEUS sobre os filhos de Amom, e sua humilhação; Dize pois: A espada, a espada está desembainhada, polida para a matança, para destruir, para reluzir como relâmpago,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Enquanto te profetizam falsidade, enquanto te adivinham mentira; para te porem sobre os pescoços dos perversos condenados à morte, cujo dia virá no tempo do fim da maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Torna tua espada à sua bainha! No lugar onde foste criado, na terra de teu nascimento eu te julgarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'E derramarei sobre ti minha ira; assoprarei contra ti o fogo do meu furor, e te entregarei na mão de homens violentos, habilidosos em destruir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Para o fogo tu serás combustível; teu sangue estará no meio da terra; não haverá memória de ti; porque eu, o SENHOR, falei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'E tu, filho do homem, Por acaso julgarás tu, por acaso julgarás tu a cidade derramadora de sanguinária? Notifica-lhe, pois, todas as suas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'E dize: Assim disse o Senhor DEUS: Cidade que derrama sangue no meio de si, para que venha seu tempo, e que faz ídolos contra si mesma para se contaminar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Fizeste-te culpada com teu sangue que derramaste, e te contaminaste com teus ídolos que fizeste; e fizeste aproximar teus dias, e chegado a teus anos; por isso te entreguei por humilhação às nações, e por escárnio a todas as terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'As que estão perto e as que estão longe de ti escarnecerão de ti, que és imunda de nome, e cheia de inquietação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Eis que os príncipes de Israel, cada um conforme seu poder, estiveram em ti para derramarem sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Desprezaram ao pai e à mãe em ti; trataram ao estrangeiro com opressão no meio de ti; oprimiram ao órfão e à viúva em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Desprezaste minhas coisas santas, e profanaste meus sábados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Caluniadores houve em ti, para derramarem sangue; e comeram sobre os montes em ti; praticaram lascívia no meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Descobriram a nudez do pai) em ti; abusaram da contaminada por menstruação em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'E um cometeu abominação com a mulher de seu próximo; e outro contaminou lascivamente sua nora; e outro abusou de sua irmã, filha de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Suborno receberam em ti para derramarem sangue; juros e lucro tomaste, e exploraste gananciosamente o teu próximo, oprimindo-o; e esqueceste de mim, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Mais eis que bati minhas mãos por causa de tua ganância que cometeste, e por causa de teu sangue, que houve no meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Conseguirá, por acaso, ficar firme teu coração? Serão fortes tuas mãos nos dias em que eu agir contra ti? Eu, o SENHOR, falei, e farei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'E eu te dispersarei pelas nações, e te espalharei pelas terras; e acabarei de ti tua imundícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Assim serás profanada em ti aos olhos das nações, e saberás que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Filho do homem, a casa de Israel se tornou para mim em escórias; todos eles são cobre, estanho, ferro, e chumbo, no meio do forno; eles se tornaram escórias de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Portanto assim diz o Senhor DEUS: Dado que todos vós vos tornastes em escórias, por isso eis que eu vos ajuntarei no meio de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Como se ajunta prata, bronze, ferro, chumbo e estanho em meio do forno, para soprar fogo sobre eles para fundir, assim vos ajuntarei em minha ira e em meu furor, e ali vos deixarei, e vos fundirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Eu vos reunirei, e soprarei sobre vós no fogo de meu furor, e no meio dela sereis fundidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Como se funde a prata no meio do forno, assim sereis fundidos no meio dela; e sabereis que eu, o SENHOR, derramei meu furor sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Filho do homem, diz a ela: Tu não és uma terra limpa, nem molhada de chuva no dia da indignação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Há uma conspiração de seus profetas no meio dela, como um leão que brame, que arrebata a presa; devoraram almas, tomam bens e coisas preciosas, aumentam suas viúvas no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Seus sacerdotes violentam minha lei, e profanam minhas coisas sagradas; não fazem diferença entre o santo e o profano, nem distinguem o impuro do puro; e escondem seus olhos de meus sábados. Assim eu sou profanado no meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Seus príncipes no meio dela são como lobos que arrebatam presa para derramarem sangue, para destruírem almas, para obterem lucro desonesto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'E seus profetas os rebocam com cal solta, profetizando-lhes falsidade, e adivinhando- lhes mentira, dizendo: Assim diz o Senhor DEUS; sem que o SENHOR tenha falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'O povo da terra faz graves extorsões, e pratica roubos; fazem violência ao aflito e necessitado, e oprimem sem motivo ao estrangeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'E busquei dentre eles um homem que tapasse o muro, e que se pusesse na brecha diante de mim pela terra, para que eu não a destruísse; porém a ninguém achei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Por isso derramarei sobre eles minha indignação; com o fogo de minha ira os consumirei; retribuirei o caminho deles sobre suas próprias cabeças,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Filho do homem, houve duas mulheres, filhas de uma mesma mãe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Estas se prostituíram no Egito; em suas juventudes se prostituíram. Ali foram apertados os seus peitos, e ali foram apalpados os seios de sua virgindade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'E seus nomes eram: Oolá, a maior, e Oolibá sua irmã; e elas foram minhas, e tiveram filhos e filhas. Estes eram seus nomes: Samaria é Oolá, e Jerusalém Oolibá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'E Oolá prostituiu-se, mesmo sendo minha; e apaixonou-se por seus amantes, os assírios seus vizinhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Vestidos de azul, governadores e príncipes, todos rapazes cobiçáveis, cavaleiros que andavam a cavalo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Assim ela cometeu suas prostituições com eles, os quais eram os mais apreciados dos filhos da Assíria, e com todos aqueles por quem ela se apaixonou; contaminou-se com todos os ídolos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'E não deixou suas fornicações que trouxe do Egito; pois com ela se deitaram em sua juventude, e eles apalparam os seios de sua virgindade, e derramaram sua prostituição sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Por isso a entreguei na mão de seus amantes, na mão dos filhos da Assíria, por quem tinha se apaixonado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Eles descobriram sua nudez, tomaram seus filhos e suas filhas, e a mataram à espada; e veio a ser famosa entre as mulheres, pois fizeram julgamentos contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Sua irmã Oolibá viu isso, porém corrompeu sua paixão mais que ela; e suas prostituições foram mais numerosas que as prostituições de sua irmã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Apaixonou-se pelos filhos da Assíria, pelos governadores e príncipes, seus vizinhos, vestidos com luxo, cavaleiros que andavam a cavalo, todos eles rapazes cobiçáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'E vi que ela estava contaminada; ambas tinham um mesmo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'E ela aumentou suas prostituições; pois viu homens pintados na parede, as imagens de caldeus pintadas de vermelho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Vestidos com cintos ao redor de seus lombos, e enormes turbantes em suas cabeças, tendo todos eles aparência de capitães, à semelhança dos filhos da Babilônia, nascidos na terra da Caldeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'E apaixonou-se deles logo que seus olhos os viram, e enviou-lhes mensageiros à Caldeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Então os filhos da Babilônia vieram até ela à cama dos amores, e a contaminaram com suas prostituições; e ela também se contaminou com eles; então sua alma desgostou deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Assim ela expôs suas prostituições, e expôs sua nudez; então minha alma desgostou dela, assim como já tinha desgostado de sua irmã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Porém ela multiplicou suas prostituições, relembrando-se dos dias de sua juventude, nos quais havia se prostituído na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'E apaixonou-se por seus amantes, cuja carne é como carne de asnos, e cujo fluxo é como fluxo de cavalos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Assim relembraste a obscenidade de tua juventude, quando os egípcios apalpavam teus peitos, por causa dos seios de tua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Portanto, Oolibá, assim diz o Senhor DEUS: Eis que eu levantarei contra ti os teus amantes, dos quais tua alma desgostou, e eu os trarei contra ti ao redor:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Os filhos da Babilônia, e todos os caldeus, Pecode, Soa, e Coa, todos os filhos da Assíria com eles; rapazes cobiçáveis, governadores e príncipes todos eles, capitães e líderes, todos os que andam a cavalo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'E virão sobre ti com armamentos, carruagens, carretas, e com ajuntamento de povos. Escudos grandes e pequenos, e capacetes serão postos contra ti ao redor; e eu os designarei para que façam o julgamento, e eles te julgarão conforme seus julgamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'E porei meu zelo contra ti, e te tratarão com furor; tirarão teu nariz e tuas orelhas, e o que restar de ti cairá a espada. Eles tomarão teus filhos e tuas filhas, e o que restar de ti será consumido pelo fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Também te despirão de tuas vestes, e tomarão as tuas belas joias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Assim farei cessar de ti tua obscenidade e tua prostituição da terra do Egito; e não levantarás mais teus olhos a eles, nem te lembrarás mais do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Porque assim diz o Senhor DEUS: Eis que eu te entregarei nas mãos daqueles a quem tu odeias, nas mãos daqueles dos quais tua alma se desgostou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Eles te tratarão com ódio, e tomarão todo o ganho de teu trabalho, e te deixarão nua e despida; e será exposta a nudez de tuas prostituições, tua obscenidade, e tuas promiscuidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Estas coisas serão feitas contigo porque te prostituíste atrás das nações, com as quais te contaminaste com seus ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Tu andaste no caminho de tua irmã; por isso darei o cálice dela em tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Assim diz o Senhor DEUS: Tu beberás cálice fundo e largo de tua irmã; tu serás motivo de riso e escárnio, pois ele cabe muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'De embriaguez e de dor tu serás cheia; o cálice de tua irmã Samaria é cálice de medo e de desolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Tu, pois, o beberás, o esvaziarás, e quebrarás seus cacos; e arrancarás teus peitos; porque eu falei,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Portanto assim diz o Senhor DEUS: Dado que te esqueceste de mim, e me lançaste por trás de tuas costas, por isso, leva tu também as consequências de tua obscenidade e de tuas prostituições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'E disse-me o SENHOR: Filho do homem, julgarás tu a Oolá, e a Oolibá, e lhes denunciarás suas abominações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Pois elas cometeram adultério, e há sangue em suas mãos, e com seus ídolos cometeram adultério; e até a seus filhos que me haviam gerado fizeram passar pelo fogo, para os consumir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Ainda isto me fizeram: contaminaram meu santuário naquele mesmo dia, e profanaram meus sábados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Pois havendo sacrificado seus filhos a seus ídolos, vieram ao meu santuário no mesmo dia para profaná-lo; e eis que assim fizeram em meio da minha casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'E além disto, mandaram avisar a homens que viriam de longe, aos quais havia sido enviado mensageiro. E eis que vieram; e por causa deles te lavaste, pintaste os teus olhos, e te enfeitaste de joias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'E te sentaste sobre uma cama luxuosa; diante da qual foi preparada uma mesa, e puseste sobre ela meu perfume e meu óleo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'E ouviu-se nela voz de multidão alegre; e junto dos homens ordinários, foram trazidos os beberrões do deserto; e puseram braceletes em suas mãos, e belas coroas sobre suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Então eu disse à envelhecida em adultérios: Agora eles se prostituirão com ela, assim como ela faz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'E se deitaram com ela como quem se deita com mulher prostituta; assim se deitaram com Oolá e com Oolibá, mulheres indecentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Por isso homens justos as julgarão pela lei que pune as adúlteras, e pela lei que pune as que derramam sangue; pois são adúlteras, e há sangue há nas mãos delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Porque assim diz o Senhor DEUS: Farei subir uma multidão contra elas, e as entregarei a terror e ao saque;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'E a multidão as apedrejará com pedras, e as cortarão com suas espadas; matarão seus filhos e suas filhas, e queimarão com fogo suas casas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Assim acabarei com a obscenidade da terra, para que todas as mulheres aprendam a não fazer conforme vossa obscenidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'E porão sobre vós a culpa por vossa obscenidade, e levareis os pecados de vossos ídolos; e sabereis que eu sou o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'No nono ano, no décimo mês, aos dez do mês, veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Filho do homem, escreve para ti o nome deste dia, hoje mesmo; porque o rei da Babilônia chegou a Jerusalém hoje mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'E fala uma parábola à casa rebelde, e dize-lhes: Assim diz o Senhor DEUS: Põe uma panela, põe -a,e também deita água dentro dela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Ajunta seus pedaços de carne nela; todos bons pedaços, pernas e espáduas; enche - a dos melhores ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Toma do melhor do rebanho, e acende também os ossos debaixo dela; faze-a ferver bem; e assim seus ossos serão cozidos dentro dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Portanto assim diz o Senhor DEUS: Ai da cidade sanguinária, cuja sujeira está nela, e cuja sujeira não saiu dela! Tira dela pedaço por pedaço, não caia sorte sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Porque seu sangue está em meio dela; sobre uma pedra exposta ela o pôs; não o derramou sobre a terra, para que fosse coberto com pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Para que eu faça subir a ira, para me vingar, eu pus seu sangue sobre a pedra exposta, para que não seja coberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Portanto assim diz o Senhor DEUS: Ai da cidade sanguinária! Também eu farei uma grande fogueira,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Amontoa lenha, acende o fogo, consome a carne, e a tempera com especiarias; e sejam queimados os ossos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Depois põe a panela vazia sobre suas brasas, para que se esquente, e seu cobre queime, e se funda sua imundícia no meio dela, e se consuma sua sujeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'De trabalhos ela me cansou, e sua muita sujeira não saiu dela. Sua sujeira irá para o fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Em tua imundícia há obscenidade, porque eu te purifiquei, porém tu não te purificaste; não mais serás purificada de tua imundícia, enquanto eu não fizer repousar minha ira sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Eu, o SENHOR, falei; virá a acontecer, e o farei. Não me tonarei atrás, não pouparei, nem me arrependerei; conforme teus caminhos e teus atos te julgarão, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Filho do homem, eis que com um golpe tirarei de ti o desejo de teus olhos; não lamentes, nem chores, nem escorram de ti lágrimas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Geme em silêncio, não faças luto pelos mortos; ata teu turbante sobre ti, e põe teus sapatos em teus pés; e não te cubras os lábios, nem comas pão de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'E falei ao povo pela manhã, e minha mulher morreu à tarde; e pela manhã fiz como me fora mandado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'E o povo me disse: Por acaso não nos farás saber o que significam para nós estas coisas que tu estás fazendo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Então eu lhes disse: A palavra do SENHOR veio a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Dize à casa de Israel: Assim diz o Senhor DEUS: Eis que eu profanarei meu santuário, a orgulho de vossa fortaleza, o desejo de vossos olhos, e o agrado de vossas almas; e vossos filhos e vossas filhas que deixastes cairão a espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'E fareis como eu fiz: não cobrireis vossos lábios, nem comereis pão de homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'E vossos turbantes estarão sobre vossas cabeças, e vossos sapatos em vossos pés; não lamentareis nem chorareis, em vez disso vos consumireis por causa de vossas maldades, e gemereis uns com outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Assim Ezequiel vos será por sinal; conforme tudo o que ele fez, vós fareis. Quando isto acontecer, então sabereis que eu sou o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'E tu, filho do homem, por acaso não será no dia que eu lhes tirar sua fortaleza, o seu belo orgulho, o desejo de seus olhos, e o agrado de suas almas, seus filhos e suas filhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Que no mesmo dia um que tiver escapado virá a ti para trazer as notícias aos teus ouvidos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Naquele dia tua boca se abrirá para falar com o escapado, e falarás, e não ficarás mais calado; e tu lhes serás por sinal, e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Filho do homem, dirige tua face contra os filhos de Amom, e profetiza sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'E diz aos filhos de Amom: Ouvi a palavra do Senhor DEUS; assim diz o Senhor DEUS: Dado que disseste: Ha, ha! Acerca de meu santuário quando foi profanado, e acerca da terra de Israel quando foi desolada, e acerca da casa de Judá quando foram ao cativeiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Por isso, eis, eu te entregarei como possessão aos filhos do oriente, e estabelecerão suas acampamentos em ti, e porão suas tendas em ti; eles comerão teus frutos e beberão teu leite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'E tornarei a Rabá em estábulo de camelos, e os filhos de Amom em curral de ovelhas; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Porque assim diz o Senhor DEUS: Dado que bateste palmas, e bateste o pés, e te alegraste na alma em todo teu desprezo sobre a terra de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Por isso, eis que eu estenderei minha mão contra ti, e te entregarei às nações para seres saqueada; e eu te cortarei dentre os povos, e te destruirei dentre as terras; eu te eliminarei, e saberás que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Assim diz o Senhor DEUS: Dado que Moabe e Seir dizem: Eis que a casa de Judá é como todas as nações,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Por isso, eis que eu abrirei a lateral de Moabe desde as cidades, desde suas cidades que estão em suas fronteiras, as melhores terras: Bete-Jesimote, e Baal-Meom, e até Quiriataim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Serão para os filhos do oriente, com a terra dos filhos de Amom; e a entregarei por possessão, para que não haja lembrança dos filhos de Amom entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Também farei julgamentos em Moabe; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Assim diz o Senhor DEUS: Dado que Edom se vingou contra a casa de Judá, e se tornaram extremamente culpados ao se vingarem deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Por isso assim diz o Senhor DEUS: Eu também estenderei minha mão contra a terra de Edom: exterminarei dela homens e animais, e a tornarei desolada; desde Temã e Dedã cairão à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'E me vingarei contra Edom pela mão do meu povo Israel; e farão em Edom segundo minha ira, e conhecerão minha vingança, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Assim diz o Senhor DEUS: Dado que os filisteus agiram com vingança, quando se vingaram com desprezo na alma, destruindo por hostilidades antigas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Por isso assim diz o Senhor DEUS: Eis que eu estendo minha mão contra os filisteus, e exterminarei os queretitas, e destruirei o resto da costa do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'E farei neles grandes vinganças, com castigos de furor; e saberão que eu sou o SENHOR, quando me vingar deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'E sucedeu no décimo primeiro ano, no primeiro dia do mês, que veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Filho do homem, dado que Tiro falou sobre Jerusalém: Ha, ha!, quebrada está a porta das nações; ela se virou para mim; eu me encherei de riquezas, agora que ela está assolada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Por isso, assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Tiro; e farei subir contra ti muitas nações, tal como o mar faz subir suas ondas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'E demolirão os muros de Tiro, e derrubarão suas torres; varrerei dela seu pó, e a deixarei como uma rocha exposta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Servirá para estender redes no meio do mar, porque assim eu falei,diz o Senhor DEUS; e será saqueada pelas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'E suas filhas que estiverem no campo serão mortas à espada; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Porque assim diz o Senhor DEUS: Eis que desde o norte eu trarei contra Tiro a Nabucodonosor, rei da Babilônia, rei de reis, com cavalos, carruagens, cavaleiros, tropas, e muito povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Tuas filhas no campo ele matará à espada; e porá contra ti fortalezas, fará cerco contra ti, e levantará escudos contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'E fará aríetes baterem contra teus muros, e derrubará tuas torres com suas espadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Com a multidão de seus cavalos o pó deles te cobrirá; teus muros tremerão com o estrondo dos cavaleiros, das rodas, e das carruagens, quando ele entrar por tuas portas como quem entra por uma cidade em ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Com as unhas de seus cavalos pisará todas as tuas ruas; matará teu povo à espada, e as colunas de tua fortaleza cairão por terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'E roubarão tuas riquezas, e saquearão tuas mercadorias; derrubarão teus muros, e arruinarão tuas preciosas casas; e lançarão tuas pedras, tua madeira e teu pó no meio das águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'E farei cessar o ruído de tuas canções, e o som de tuas harpas não será mais ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'E te farei como uma rocha exposta; servirás para estender redes; e nunca mais serás reconstruída; porque eu, o SENHOR falei,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Assim diz o Senhor DEUS a Tiro: Por acaso não se estremecerão as ilhas com o estrondo de tua queda, quando os feridos gemerem, quando houver grande matança no meio de ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Então todos os príncipes do mar descerão de seus tronos, tirarão de si seus mantos, e despirão suas roupas bordadas; com tremores se vestirão, sobre a terra se sentarão, e estremecerão em todo momento, e ficarão espantados por causa de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'E levantarão lamentação por causa de ti, e te dirão: Como pereceste tu, povoada dos mares, famosa cidade, que foi forte no mar; ela e seus moradores, que punham seu espanto a todos os moradores dela?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Agora as terras costeiras se estremecerão no dia de tua queda; e as ilhas que estão no mar se espantarão com o teu fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Porque assim diz o Senhor DEUS: Quando eu te tornar uma cidade desolada, como as cidades que não se habitam; quando eu fizer subir sobre ti um abismo, e muitas águas te cobrirem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Então eu te farei descer com os que descem à cova, junto dos povos do passado; e te porei nas profundezas da terra, como os lugares desertos antigos, com os que descem à cova, para que não sejas habitada; então darei glória na terra dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Eu te tonarei em espanto, e não mais existirás; e ainda que te busquem, nunca mais serás achada,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Tu, pois, filho do homem, levanta uma lamentação sobre Tiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'E dize a Tiro, que habita nas entradas do mar, e faz comércio com dos povos em muitas terras costeiras: Assim diz o Senhor DEUS: Ó Tiro, tu dizes: Eu sou perfeita em beleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Teus limites estão no coração dos mares; os que te edificaram aperfeiçoaram a tua beleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Fabricaram todos os teus conveses com faias de Senir; trouxeram cedros do Líbano para fazerem mastros para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Fizeram teus remos com carvalhos de Basã; fizeram teus bancos com ciprestes das ilhas do Chipre, unidos com marfim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Linho bordado do Egito era tua cortina, para te servir de vela; de azul e púrpura das ilhas de Elisá era teu toldo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Os moradores de Sidom e de Arvade eram teus remadores; teus sábios, ó Tiro, que estavam em ti, eles foram teus pilotos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Os anciãos de Gebal e seus sábios eram em ti os que reparavam tuas fendas; todos os navios do mar e seus marinheiros delas foram em ti para negociar tuas mercadorias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persas e lídios, e os de Pute, eram em teu exército teus soldados; escudos e capacetes penduraram em ti; eles te deram tua pompa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Os filhos de Arvade e teu exército estavam sobre teus muros ao redor, e os gamaditas em tuas torres; penduravam seus escudos sobre teus muros ao redor; eles aperfeiçoavam tua beleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Társis negociava contigo, por causa da abundância de todas as variedades de riquezas; com prata, ferro, estanho, e chumbo, negociavam em tuas feiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javã, Tubal, e Meseque eram teus mercadores; com almas humanas e com vasos de metal, fizeram negócios contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Da casa de Togarma traziam cavalos, cavaleiros e mulos, para tuas feiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Os filhos de Dedã eram teus mercadores; muitas ilhas eram o comércio sob teu controle; chifres de marfim e madeira de ébano te deram como presente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'A Síria negociava contigo por causa da abundância de tuas obras; turquesas, púrpura, materiais bordados, linhos finos, corais, e rubis, traziam em tuas feiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Eles, Judá e a terra de Israel, eram teus mercadores; com trigo de Minite, e panague, mel, e azeite, e resina, fizeram negócios contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damasco negociava contigo, por causa da abundância de tuas obras, pela abundância de todas as variedades de bens; com vinho de Helbom, e lã branca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Também Dã e Javã de Uzal comercializavam em tuas feiras; ferro lavrado, cássia, e cana aromática havia em teu comércio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedã negociava contigo, com panos preciosos para carros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'A Arábia, e todos os príncipes de Quedar, eles eram mercadores sob teu controle; com cordeiros, carneiros, e bodes; nestas coisas negociavam contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Os mercadores de Sabá e de Raamá eram teus mercadores; com toda especiaria importante, toda pedra preciosa, e ouro, comercializavam em tuas feiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Harã, Cané, e Éden, os mercadores de Sabá, da Assíria, e Quilmade negociavam contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Estes negociavam contigo em toda variedade de mercadorias: com tecidos azuis, com bordados, e com caixas de roupas preciosas, amarradas com cordões, e postos em cedro, em teu comércio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Os navios de Társis transportavam os artigos do teu negócio; e te encheste, e te tornaste muito pesada no meio dos mares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Teus remadores te trouxeram a muitas águas; o vento oriental te quebrou no meio dos mares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Tuas riquezas, tuas feiras, teu negócio, teus marinheiros, teus pilotos; os que reparavam tuas fendas, teus comerciantes, e todos teus soldados que há em ti, com toda a tua companhia que está no meio de ti, cairão no meio dos mares, no dia de tua queda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Ao estrondo das vozes de teus marinheiros tremerão os arredores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'E todos os que usam remo; marinheiros, e todos os pilotos do mar descerão de seus navios, e pararão na terra:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'E farão ouvir sua voz sobre ti; gritarão amargamente, lançarão pó sobre suas cabeças, e se revolverão na cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'E se farão calvos por causa de ti, se vestirão de sacos, e chorarão por ti com amargura da alma, com amarga lamentação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'E levantarão lamentação sobre em seu pranto, e lamentarão sobre ti dizendo: Quem foi como Tiro, como a que agora está silenciada no meio do mar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Quando tuas mercadorias vinham dos mares, fartaste muitos povos; enriqueceste os reis da terra com a abundância de tuas riquezas e de teus negócios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Agora foste quebrada dos mares, nas profundezas das águas; caíram teu negócio e toda a tua companhia no meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Todos os moradores dos litorais foram espantados por causa de ti, e seus reis ficaram horrorizados; seus rostos se conturbaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Os mercadores nos povos assoviam por causa de ti; tu te tornaste em motivo de espanto, e nunca mais voltarás a existir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Filho do homem, dize ao príncipe de Tiro: Assim diz o Senhor DEUS: Dado que teu coração se exalta, e dizes: Eu sou um deus; no trono de de Deus me sento no meio dos mares (sendo tu homem e não Deus); e consideras teu coração como coração de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, '(Eis que tu és mais sábio que Daniel; não há segredo algum que possa se esconder de ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Com tua sabedoria e teu entendimento obtiveste riquezas, e adquiriste ouro e prata em teus tesouros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Com a tua grande sabedoria aumentaste tuas riquezas em teu comércio; e por causa de tuas riquezas teu coração tem se exaltado).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Portanto assim diz o Senhor DEUS: Dado que consideras teu coração como coração se fosse de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Por isso eis que eu trarei sobre ti estrangeiros, os mais violentos das nações, os quais desembainharão suas espadas contra a beleza de tua sabedoria, e contaminarão o teu resplendor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'À cova te farão descer, e morrerás da morte dos que morrem no meio dos mares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Por acaso dirás: Eu sou Deus, diante de teu matador? Tu és homem, e não Deus, nas mãos de quem te matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'De morte de incircuncisos morrerás, pela mão de estrangeiros; porque assim eu falei, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Filho do homem, levanta uma lamentação sobre o rei de Tiro, e dize-lhe: Assim diz o Senhor DEUS: Tu eras o carimbo da perfeição, cheio de sabedoria, e perfeito em formosura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Estiveste no Éden, o jardim de Deus; toda pedra preciosa era tua cobertura; sárdio, topázio, diamante, turquesa, ônix, jaspe, safira, carbúnculo, e esmeralda; e de ouro era a obra de tuas molduras e de teus engastes em ti; no dia em que foste criado estavam preparados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Tu eras querubim ungido, cobridor; e eu te estabeleci, no santo monte de Deus estavas; no meio de pedras de fogo tu andavas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Íntegro eras em teus caminhos, desde o dia em que foste criado, até que se achou maldade em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Pela abundância de teu comércio encheram o meio de ti de violência; por isso eu te expulsei como profanado do monte de Deus, e te farei perecer, ó querubim cobridor, do meio das pedras de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Teu coração se exaltou por causa de tua formosura, corrompeste tua sabedoria por causa de teu resplendor; eu te lancei por terra; diante dos reis eu te pus, para que olhem para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Por causa da multidão de tuas maldades e da perversidade de teu comércio, profanaste teus santuários; por isso eu fiz sair um fogo do meio de ti, o qual te consumiu; e te tornei em cinza sobre a terra, diante dos olhos de todos quantos te veem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Todos os que te conhecem entre os povos estão espantados por causa de ti; em grande horror te tornaste, e nunca mais voltarás a existir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Filho do homem, dirige teu rosto contra Sidom, e profetiza contra ela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'E dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Sidom, e serei glorificado no meio de ti; e saberão que eu sou o SENHOR, quando nela fizer juízos, e nela me santificar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Pois enviarei a ela pestilência e sangue em suas ruas; e mortos cairão no meio dela pela espada que está contra ela ao redor; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'E a casa de Israel nunca mais terá espinho que a fira, nem abrolho que cause dor, de todos os que desprezam ao redor deles; e saberão que eu sou o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Assim diz o Senhor DEUS: Quando eu ajuntar a casa de Israel dos povos entre os quais estão dispersos, e eu me santificar entre eles diante dos olhos das nações, então habitarão em sua terra, que dei a meu servo Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'E habitarão nela em segurança, edificarão casas, e plantarão vinhas; e habitarão em segurança, quando eu fizer juízos contra todos os que os desprezam ao redor deles; e saberão que eu sou o SENHOR, o Deus deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'No décimo ano, no décimo mês, aos doze do mês, veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Filho do homem, dirige teu rosto contra Faraó, rei do Egito; e profetiza contra ele e contra todo o Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Fala, e dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, Faraó rei do Egito, o grande dragão que jaz no meio de seus rios, que diz: Meu rio é meu, eu o fiz para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Porém eu porei anzóis em teus queixos, e apegarei os peixes de teus rios a tuas escamas, e te tirarei do meio de teus rios, e todos os peixes de teus rios se apegarão a tuas escamas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'E te deixarei no deserto, a ti e a todos os peixes de teus rios; sobre a face do campo aberto cairás; não serás recolhido, nem ajuntado; para os animais da terra e para as aves do céu te dei por alimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'E todos os moradores do Egito saberão que eu sou o SENHOR, pois foram um bordão de cana para a casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Quando eles te tomaram pela mão, te quebraste, e lhes rompeste todo os ombros; e quando se recostaram a ti, te quebraste, e lhes fizeste instáveis todos os lombos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Portanto, assim diz o Senhor o SENHOR: Eis que eu trarei contra ti espada, e destruirei de ti homens e animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'E a terra do Egito se tornará desolada e deserta; e saberão que eu sou o SENHOR; porque ela disse: O rio é meu, eu o fiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Portanto eis que eu sou contra ti, e contra teus rios; e tornarei a terra do Egito em desertas e assoladas solidões, desde Migdol e Sevene, até o limite de Cuxe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Não passará por ela pé de homem, nem pata de animal passará por ela; nem será habitada por quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Porque tornarei a terra do Egito em desolação, em meio a terras desoladas; e suas cidades no meio das cidades desertas ficarão desoladas por quarenta anos; e espalharei os egípcios entre as nações, e os dispersarei pelas terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Porém assim diz o Senhor DEUS: Ao fim de quarenta anos ajuntarei os egípcios dos povos entre os quais forem espalhados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'E restaurarei o Egito de seu infortúnio, e os trarei de volta à terra de Patros, à terra de seu nascimento; e ali serão um reino inferior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Será mais inferior que os outros reinos; e nunca mais se erguerá sobre as nações; porque eu os diminuirei, para que não dominem as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'E não será mais motivo de confiança para a casa de Israel, para fazê-la lembrar de sua maldade, quando olharam para eles; e saberão que eu sou o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'E sucedeu no ano vinte e sete, no primeiro mês,no primeiro dia do mês, que veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Filho do homem, Nabucodonosor rei da Babilônia mobilizou seu exército para uma grande campanha contra Tiro. Toda cabeça se tornou calva, e todo ombro se despelou; porém não houve ganho para ele nem para seu exército pela campanha que executou contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Portanto assim diz o Senhor DEUS: Eis que eu darei a Nabucodonosor, rei da Babilônia, a terra do Egito; e ele levará sua riqueza, tomará seus despojos, e saqueará sua presa, e isto será o ganho para seu exército.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Como pagamento por seu trabalho que executou contra ela, eu lhe dei a terra do Egito; porque trabalharam por mim,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Naquele dia farei crescer o poder da casa de Israel, e te darei abertura de boca no meio deles; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Filho do homem, profetiza, e dize: Assim diz o Senhor DEUS: Gritai: Ai daquele dia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Porque perto está o dia, perto está o dia do Senhor; dia de nuvens; será o tempo das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'E a espada virá ao Egito, e haverá grande dor em Cuxe, quando caírem os mortos no Egito; e tomarão sua multidão, e serão destruídos seus fundamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Cuxe, Pute, Lude, e todo o povo misturado, e Cube, e os filhos da terra do pacto cairão com eles à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Assim diz o SENHOR: Também cairão os que sustentam ao Egito, e a soberba de sua força irá abaixo; desde Migdol e Sevene cairão nele à espada, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'E serão assolados no meio das terras assoladas, e suas cidades estarão no meio das cidades desertas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'E saberão que eu sou o SENHOR, quando puser fogo ao Egito, e forem destruídos todos os que o ajudavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Naquele dia sairão de diante de mim mensageiros em navios, para espantarem a confiante Cuxe, e haverá grandes dores neles, como no dia do Egito; porque eis que está vindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Assim diz o Senhor DEUS: Farei cessar a multidão do Egito pela mão de Nabucodonosor, rei da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Ele, e com ele seu povo, os mais terríveis das nações, serão trazidos para destruir a terra; e desembainharão suas espadas contra o Egito, e encherão a terra de mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'E secarei os rios, entregarei a terra em mãos de malignos, e destruirei a terra e tudo o que ela contém pela mão de estrangeiros; eu, o SENHOR falei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Assim diz o Senhor DEUS: Também destruirei aos ídolos, e darei fim às imagens idolátricas de Mênfis; não haverá mais príncipe da terra do Egito, e porei medo na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'E desolarei a Patros, porei fogo a Zoã, e farei juízos em Nô.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'E derramarei minha ira sobre Pelúsio, a fortaleza do Egito, e exterminarei a multidão de Nô.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'E porei fogo ao Egito; Pelúsio terá grande dor, Nô será destroçada, e Mênfis terá angústias contínuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Os rapazes de Áven e de Pibesete cairão à espada; e elas irão em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'E em Tafnes o dia se escurecerá, quando eu quebrar ali o jugo do Egito, e nela cessar a soberba de sua força; uma nuvem a cobrirá, e suas filhas irão em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Pois farei julgamentos no Egito, e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'E sucedeu no décimo primeiro ano, no primeiro mês, aos sete do mês, que veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Filho do homem, quebrei o braço de Faraó, rei do Egito; e eis que não será enfaixado com remédios, nem lhe porão faixa para o envolver, a fim de curá-lo para que possa segurar espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Portanto, assim diz o Senhor DEUS: Eis que sou contra Faraó, rei do Egito, e quebrarei seus braços, tanto o forte como o quebrado; e farei cair a espada de sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'E espalharei os egípcios entre as nações, e os dispersarei pelas terras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'E fortalecerei os braços do rei da Babilônia, e porei minha espada em sua mão; porém quebrarei os braços de Faraó, e diante dele gemerá com gemidos de ferido de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Fortalecerei, pois, os braços do rei de Babilônia, enquanto que os braços de Faraó cairão; e saberão que eu sou o SENHOR, quando eu tiver posto minha espada na mão do rei da Babilônia, e ele a estender sobre a terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'E espalharei os egípcios entre as nações, e os dispersarei pelas terras; assim saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'E sucedeu no décimo primeiro ano, no terceiro mês, ao primeiro dia do mês, que veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Filho do homem, dize a Faraó rei do Egito, e a sua multidão: A quem és semelhante em tua grandeza?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Eis que a Assíria era um cedro no Líbano, belo de ramos, de grande sombra com sua folhagem, e alto de estatura; e seu topo estava entre ramos espessos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'As águas o fizeram crescer, o abismo o ergueu; com suas correntes ia ao redor de sua base, e enviava seus canais de águas a todas as árvores do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Por isso sua altura se ergueu acima de todas as árvores do campo; seus galhos se multiplicaram, e seus ramos que gerava se alongaram por causa das muitas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Todas as aves do céus faziam ninhos em seus ramos, e todos os animais do campo tinham filhotes abaixo de sua folhagem; e todos os grandes povos habitavam à sua sombra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Assim era belo em sua grandeza, na extensão de seus ramos; porque sua raiz estava junto a muitas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Os cedros não o encobriram no jardim de Deus; as faias não eram semelhantes a seus ramos, nem os castanheiros eram semelhantes a seus renovos; nenhuma árvore no jardim de Deus era semelhante a ele em sua beleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Eu o fiz belo com a multidão de seus ramos; e todos os árvores do Éden, que estavam no jardim de Deus, tiveram inveja dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Portanto assim diz o Senhor DEUS: Dado que te elevaste em estatura, e levantou seu topo no meio de ramos espessos, e seu coração se exaltou em sua altura,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Por isso eu o entreguei na mão do mais poderoso das nações, para que o tratasse; por sua perversidade o lancei fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'E estrangeiros o cortaram, os mais terríveis das nações, e o deixaram; seus ramos caíram sobre os montes e por todos os vales, e seus renovos foram quebrados por todas as correntes da terra; e todos os povos da terra saíram de sua sombra, e o deixaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Todas as aves do céu habitaram sobre sua ruína, e todos os animais do campo estiveram sobre seus ramos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Para que todas as árvores bem regadas com águas não se elevem em sua estatura, nem levantem seu topo no meio dos ramos espessos, nem todas as que bebem águas se tornem poderosas de tão altas; porque todos estão entregues à morte, no meio dos filhos dos homens, para abaixo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Assim diz o Senhor DEUS: No dia em que ele desceu ao mundo dos mortos, mandei fazer luto, fiz cobrir o abismo por ele, e detive seus rios, e as muitas águas foram retidas; cobri o Líbano de trevas por ele, e e por ele todas os árvores do campo se desfaleceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Do estrondo de sua queda eu fiz tremer as nações, quando eu o fiz descer ao mundo dos mortos com os que descem à cova; e todas os árvores de Éden, as mais valiosas e melhores do Líbano, todas as que bebem águas, consolaram-se abaixo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Também eles desceram com ele ao mundo dos mortos, com os mortos à espada, e os que foram seu braço, e habitavam à sua sombra em meio das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'A quem, pois, tu és semelhante em glória e em grandeza entre as árvores do Éden? Porém tu serás derrubado com as árvores do Éden para abaixo da terra; entre os incircuncisos jazerás, com os mortos à espada. Este é Faraó e toda a sua multidão,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'E sucedeu no décimo segundo ano, no décimo segundo mês, no primeiro dia do mês, que veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Filho do homem, levanta uma lamentação sobre Faraó, rei do Egito, e dize-lhe: Tu te comparavas a um jovem leão entre as nações, porém tu eras como um monstro marinho nos mares, que te contorcias em teus rios, e turbavas as águas com teus pés, e enlameavas seus rios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Assim diz o Senhor DEUS: Portanto estenderei sobre ti minha rede com ajuntamento de muitos povos, e te puxarão para cima em minha rede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Então te deixarei em terra, não campo aberto eu te lançarei; e farei que com que fiquem sobre ti todas as aves do céu, e fartarei de ti os animais de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'E porei tua carne sobre os montes, e encherei os vales com tua altura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'E regarei com teu sangue a terra onde nadas, até os montes; e as correntes se encherão de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'E quando eu te extinguir, cobrirei os céus, e farei escurecer suas estrelas; cobrirei o sol cobrirei com nuvem, e a lua não fará brilhar sua luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Todas os luminares de luz no céu escurecerei sobre ti, e trarei trevas sobre tua terra,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'E perturbarei o coração de muitos povos, quando levarei a tua destruição entre as nações, a terras que tu não conheceste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'E farei com que muitos povos fiquem espantados por causa de ti, e seus reis se encham de medo por causa de ti, quando eu mover minha espada diante de seus rostos; e todos se estremecerão, cada um em sua alma, em todo momento, no dia de tua queda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Porque assim diz o Senhor DEUS: A espada do rei da Babilônia virá sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Farei cair tua multidão com as espadas dos guerreiros, todos eles são os mais terríveis das nações; e destruirão a soberba do Egito, e toda sua multidão será destruída.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'E destruirei todas os seus animais de sobre as muitas águas; nem mais as turbará pé de homem, nem unha de animais as turbarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Então farei suas águas se assentarem, e farei seus rios fluírem como azeite,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Quando eu tornar a terra do Egito em desolação, e a terra for desolada de tudo que ela tem, quando eu ferir a todos os que nela moram, então saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Esta é a lamentação que lamentarão; as filhas das nações a lamentarão; por causa do Egito e de toda a sua multidão a lamentarão,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'E sucedeu no décimo segundo ano, aos quinze do mês, que veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Filho do homem, pranteia sobre a multidão do Egito, e faze-a descer, a ela e às vilas das nações pomposas, nas profundezas da terra, com os que descem à cova:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Por acaso és tu mais belo que os outros? Desce, e deita-te com os incircuncisos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Entre os mortos à espada cairão; para a espada está entregue; arrastai a ela e a toda a sua multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Os mais poderosos dos guerreiros falarão a ele desde o meio do mundo dos mortos, com seus ajudadores: Desceram; jazeram os incircuncisos, mortos a espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Ali está a Assíria com toda a sua companhia; ao derredor dele estão seus sepulcros; todos eles foram mortos, que caíram pela espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Seus sepulcros foram postos do lado da cova, e sua companhia está ao redor de seu sepulcro; todos eles foram mortos, caídos pela espada, e causaram terror na terra dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Ali está Elão com toda a sua multidão ao redor de seu sepulcro; todos eles foram mortos, caídos pela espada, os quais desceram incircuncisos às profundezas da terra, os quais causaram terror deles na terra dos viventes, porém levaram sua vergonha com os que desceram à cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'No meio dos mortos lhe puseram uma cama com toda a sua multidão; ao redor dele estão seus sepulcros: todos eles são incircuncisos, mortos pela espada, porque o terror deles se espalhou pela terra dos viventes, porém levaram sua vergonha com os que descem à cova; no meio dos mortos foi posto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Ali está Meseque e Tubal, com toda a sua multidão; ao redor dele estão seus sepulcros; todos eles são incircuncisos, mortos pela espada, porque causaram terror deles na terra dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Porém não jazerão com os guerreiros que caíram dos incircuncisos, os quais desceram ao mundo dos mortos com suas armas de guerra, e puseram suas espadas debaixo de suas cabeças; mas suas maldades estarão sobre seus ossos, porque foram o terror do guerreiros na terra dos viventes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Também tu serás quebrado no meio dos incircuncisos, e jazerás com os mortos à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Ali está Edom, seus reis e todos os seus príncipes, os quais com sua força foram postos com os mortos à espada; estes jazem com os incircuncisos, e com os que desceram à cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Ali estão os príncipes do norte, todos eles, e todos os sidônios, que desceram com os mortos, que foram envergonhados pelo terror de seu poder, e jazem incircuncisos com os mortos à espada, e levam sua vergonha com os que desceram à cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Faraó os verá, e se consolará com toda a sua multidão; Faraó com todo seu exército, mortos à espada,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Porque eu causei meu terror na terra dos viventes; por isso jazerá no meio dos incircuncisos, com os mortos a espada, Faraó e toda a sua multidão,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Filho do homem, fala aos filhos de teu povo, e dize-lhes: Quando eu trouxer espada sobre a terra, e o povo da terra tomar um homem de seu próprio território, e puser como seu vigilante,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'E ele vir que a espada está vindo sobre a terra, e tocar trombeta, e alertar ao povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Se alguém ouvir o som da trombeta, e não der atenção ao alerta, quando a espada vier, e o tomar, seu sangue será sobre sua própria cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Ouviu o som da trombeta, e não deu atenção ao alerta; seu sangue será sobre ele; mas o que der atenção ao alerta salvará sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Porém se o vigilante vir que a espada está vindo, e não tocar a trombeta, e o povo não for alertado, e a espada vier, e tomar alguém do povo,por causa de sua maldade foi tomado, mas exigirei seu sangue da mão do vigilante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'A ti, pois, filho do homem, eu te pus como vigilante para casa de Israel; por isso ouvirás a palavra de minha boca, e os alerta de minha parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Quando eu disser ao perverso: Ó perverso, certamente morrerás; se tu não falares para o perverso se dissuadir de seu caminho, o perverso morrerá por sua maldade, mas exigirei o sangue dele de tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Mas quando tu alertares ao perverso de seu caminho, para que dele se converta, e ele não se converter de seu caminho, ele morrerá em sua maldade, porém tu livraste tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Portanto tu, filho do homem, dize à casa de Israel: Assim vós tendes falado: Nossas transgressões e nossos pecados estão sobre nós, e por causa deles estamos desfalecendo; como então viveremos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Dize-lhes: Vivo eu, diz o Senhor DEUS, que não tenho prazer na morte do perverso, mas sim em que o perverso se converta de seu caminho, e viva. Convertei-vos! Convertei-vos de vossos caminhos; por que razão morrereis, ó casa de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Portanto tu, filho do homem, dize aos filhos de teu povo: A justiça do justo não o livrará no dia em que ele transgredir; e quanto à perversidade do perverso não o fará cair no dia em que ele se converter de sua perversidade; e o justo não poderá viver por sua justiça, no dia que pecar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Quando eu ao justo: Certamente viverá, e ele, confiante em sua justiça, passar a praticar perversidade, todas suas justiças não serão lembradas, mas na perversidade que fez, por ela morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'E quando eu disser ao perverso: Certamente morrerás; se ele se converter de seu pecado, e praticar juízo e justiça,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Se o perverso restituir o penhor, devolver o que tiver roubado, e caminhar nos estatutos da vida, não fazendo maldade, certamente viverá; não morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Nenhum de seus pecados que tinha cometido lhe será lembrado; praticou juízo e justiça; certamente viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Porém os filhos de teu povo dizem: Não é correto o caminho do Senhor; é o caminho deles que não é correto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Se o justo se desviar de sua justiça, e fizer perversidade, por causa dela morrerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'E se o perverso se converter de sua perversidade, e passar a praticar juízo e justiça, por causa deles viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Porém dizeis: Não é correto o caminho do Senhor. Eu vos julgarei a cada um conforme seus próprios caminhos, ó casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'E aconteceu no décimo segundo ano de nosso cativeiro, no décimo mês, aos cinco do mês, que veio a mim um que havia escapado de Jerusalém, dizendo: A cidade já foi ferida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Ora, a mão do SENHOR estivera sobre mim à tarde, antes que o escapado viesse, e abrira minha boca, até que chegou a mim pela manhã; e minha boca se abriu, e nunca mais fiquei mudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Então veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Filho do homem, os moradores destes lugares arruinados na terra de Israel, falando o seguinte: Abraão era um só, e tomou posse da terra; porém nós somos muitos; esta terra nos foi dada por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Portanto dize-lhes: Assim diz o Senhor DEUS: Comeis com sangue, levantais vossos olhos a vossos ídolos, e derramais sangue; e possuireis a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Confiais em vossas espadas, cometeis abominação, e contaminais cada um a mulher de seu próximo; e possuireis a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tu lhes dirás assim: Assim diz o Senhor DEUS: Vivo eu, que os que estiverem em lugares arruinados cairão à espada, e ao que estiver sobre a face do campo entregarei às feras, para que o devorem; e os que estão em fortalezas e em cavernas morrerão de pestilência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Porque tornarei a terra em desolação e ruínas, e a soberba de sua força cessará; e os montes de Israel serão desolados de tal maneira que ninguém passe por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Então saberão que eu sou o SENHOR, quando eu tornar a terra em desolação e ruínas, por causa de todas as suas abominações que fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'E tu, ó filho do homem, os filhos de teu povo falam de ti junto às paredes e às portas das casas, e um fala com o outro, cada um com seu irmão, dizendo: Vinde, pois, e ouvi que palavra vem do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'E eles vem a ti, como o povo costuma vir, e se sentam diante de ti como se fosse meu povo, e ouvem tuas palavras, mas não as praticam; em vez disso lisonjeiam com suas bocas, porém seus corações buscam o interesse próprio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'E eis que tu és para eles como um cantor de amores, de bela voz e que canta bem; então ouvem tuas palavras, mas não as praticam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Porém quando isso vier a acontecer (eis que virá) saberão que houve profeta no meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Filho do homem, profetiza contra os pastores de Israel; profetiza, e dize-lhes, aos pastores: Assim diz o Senhor DEUS: Ai dos pastores de Israel, que se apascentam a si mesmos! Por acaso não devem os pastores apascentarem as ovelhas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Comeis a gordura, e vos vestis da lã; degolais o cevado, porém não apascentais as ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Não fortaleceis as fracas, nem curais a doente; não pondes curativo na que está ferida; não trazeis de volta a desgarrada, e a perdida não buscais; porém dominais sobre elas com rigor e dureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Assim se espalharam, porque não há pastor; e se tornaram alimento para toda fera do campo, porque se espalharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Minhas ovelhas andaram sem rumo por todos os montes, e em todo morro alto; minhas ovelhas foram espalhadas por toda a face da terra, e ninguém há que as procure, ninguém que as busque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Por isso, ó pastores, ouvi a palavra do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Vivo eu, diz o Senhor DEUS, que dado que minhas ovelhas foram entregues ao saque, e minhas ovelhas serviram de alimento para toda fera do campo, por não haver pastor; e meus pastores não procuram minhas ovelhas, ao invés disso apascentaram a si mesmos, e não apascentam minhas ovelhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Por isso, ó pastores, ouvi a palavra do SENHOR:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Assim diz o Senhor DEUS: Eis que eu sou contra os pastores; exigirei deles minhas ovelhas, e farei com que cessem de apascentar as ovelhas; e os pastores não apascentarão mais a si mesmos; pois eu livrarei minhas ovelhas da boca deles, e elas não mais lhes servirão de alimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Porque assim diz o Senhor DEUS: Eis que eu, eu mesmo, procurarei minhas ovelhas, e as buscarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Assim como o pastor busca seu rebanho no dia em que está em meio de suas ovelhas espalhadas, assim buscarei minhas ovelhas, e as livrarei de todos os lugares por onde foram espalhadas, no dia de nuvem e de escuridão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'E eu as tirarei dos povos, e as ajuntarei das terras; eu as trarei para sua terra, e as apascentarei nos montes de Israel, junto às correntes de águas, e em todas as habitações do país.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Em bons pastos eu as apascentarei, e nos altos montes de Israel será sua pastagem; ali se deitarão em boa pastagem, e em prósperos pastos serão apascentadas sobre os montes de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Eu apascentarei minhas ovelhas, e eu farei elas se deitarem em segurança, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Eu buscarei a perdida, e trarei de volta a desgarrada; porei curativo na que estiver ferida, e fortalecerei a enferma; mas a gorda e a forte destruirei. Eu as apascentarei com julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'E quanto a vós, ovelhas minhas, assim diz o Senhor DEUS: Eis que eu julgarei entre ovelha e ovelha, entre carneiros e bodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Por acaso não vos basta que comais o bom pasto, para terdes que pisotear com vossos pés o resto de vossos pastos? E não vos basta as águas limpas, para sujardes o resto das águas com vossos pés?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Minhas ovelhas terão de comer o que foi pisoteado por vossos pés, e beber o que foi sujo por vossos pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Por isso assim lhes diz o Senhor DEUS: Eis que eu, eu mesmo, julgarei entre a ovelha gorda e a ovelha magra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Porque empurrais com o lado e com o ombro, e com vossos chifres chifrais todas as fracas, até que as espalhais para fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Portanto eu salvarei minhas ovelhas, para que nunca mais sirvam de saque; e julgarei entre ovelha e ovelha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'E levantarei sobre elas um pastor, e ele as apascentará: a meu servo Davi; ele as apascentará, e ele será o pastor delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Eu, o SENHOR serei o Deus delas, e meu servo Davi será príncipe no meio delas. Eu, o SENHOR, falei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'E farei com elas um pacto de paz, e farei cessar os maus animais da terra; e habitarão no deserto em segurança, e dormirão nos bosques.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'E farei com que elas e os lugares ao redor de meu monte sejam bênção; e farei descer a chuva em seu tempo; chuvas de bênção serão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'E as árvores do campo darão seu fruto, e a terra dará seu produto, e estarão em segurança sobre sua terra; e saberão que eu sou o SENHOR, quando quebrar as varas de seu jugo, e as livrar da mão dos que se servem delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'E não mais servirão de presa às nações, nem as feras da terra as devorarão; pois habitarão em segurança, e não haverá quem as espante;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'E lhes despertarei uma plantação de renome, e não mais serão consumidos de fome na terra, nem serão mais envergonhadas pelas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Assim saberão que eu, o SENHOR, seu Deus, estou com elas, e elas são o meu povo, a casa de Israel, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'E vós, ovelhas minhas, sois ovelhas humanas do meu pasto; eu sou vosso Deus, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Filho do homem, dirige teu rosto contra o monte de Seir, e profetiza contra ele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'E dize-lhe: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó monte de Seir; estenderei minha mão contra ti, e te tornarei em desolação e devastação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Tornarei as tuas cidades em ruínas, e tu serás desolado; e saberás que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Porque tiveste inimizade perpétua, e fizeste os filhos de Israel serem dispersos pelo poder da espada no tempo de sua aflição, no tempo do castigo final.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Por isso, vivo eu, diz o Senhor DEUS, que eu te preparei para o sangue, e o sangue te perseguirá; dado que não odiaste o sangue, o sangue te perseguirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'E tornarei o monte de Seir em extrema desolação, e exterminarei quem passar por ele,e quem voltar por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'E encherei seus montes de seus mortos; em teus morros, em teus vales, e em todas as tuas correntes de águas, cairão os mortos à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Eu te tornarei em desolações perpétuas, e tuas cidades nunca mais serão habitadas; assim sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Dado que disseste: As duas nações, as duas terras serão minhas, e delas tomaremos posse, ainda que o SENHOR ali estivesse;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Por isso, vivo eu, diz o Senhor DEUS, que agirei conforme tua ira e conforme tua inveja com que agiste, por causa de teu ódio contra eles; e serei conhecido por entre eles, quando eu te julgar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'E saberás que eu, o SENHOR, ouvi todas as tuas blasfêmias que disseste contra os montes de Israel, dizendo: Já estão destruídos; já nos foram entregues para que os devoremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Assim vos engradecestes contra mim com vossa boca, e multiplicastes vossas palavras contra mim. Eu ouvi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Assim diz o Senhor DEUS: Enquanto toda a terra se alegrará, eu te tornarei em desolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Tal como te alegraste sobre a herança da casa de Israel, porque foi desolada, assim eu também farei a ti; o monte de Seir, e todo o Edom se tornarão em desolação; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'E tu, filho do homem, profetiza ao os montes de Israel, e dize: Ó montes de Israel, ouvi a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Assim diz o Senhor DEUS: Dado que o inimigo disse sobre vós: Ha, ha! Até os antigos lugares altos se tornaram propriedade nossa!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Portanto profetiza, e dize: Assim diz o Senhor DEUS: Por isso, por terem vos desolado e devorado desde o redor, para que fôsseis possuídos pelo resto das nações, e fostes trazidos aos lábios dos fofoqueiros, à infâmia do povo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Por isso, ó montes de Israel, ouvi a palavra do Senhor DEUS: assim diz o Senhor DEUS aos montes e aos morros, às correntes e aos vales, às ruínas, aos lugares devastados, e às cidades abandonadas, que foram saqueadas e escarnecidas pelo resto das nações que há ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Por isso assim diz o Senhor DEUS: Certamente no fogo do meu zelo falei contra o resto das nações, e contra todo Edom, que se apropriaram de minha terra por herança, com alegria de todo coração, com desprezo na alma, para que fosse saqueada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Portanto profetiza sobre a terra de Israel, e dize aos montes, aos morros, às correntes, e aos vales: Assim diz o Senhor DEUS: Eis que falei em meu zelo e em meu furor, porque levastes sobre vós a humilhação das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Por isso assim diz o Senhor DEUS: Eu prometo que as nações que estão ao redor de vós levarão sua humilhação sobre si mesmas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Porém vós, ó montes de Israel, produzireis vossos ramos, e dareis vosso fruto a meu povo Israel; porque logo virão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Porque eis que estou convosco; e me voltarei a vós, e sereis lavrados e semeados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'E farei multiplicar homens sobre vós, a toda a casa de Israel, a ela toda; e as cidades serão habitadas, e as ruínas serão reedificadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'E multiplicarei homens e animais sobre vós; e se multiplicarão, e crescerão; e vos farei habitar como no passado, e vos farei melhor que em vossos princípios; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'E farei andar homens sobre vós: o meu povo Israel; e eles te possuirão, e tu lhes serás sua herança, e nunca mais exterminarás seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Assim diz o Senhor DEUS: Dado que dizem de vós: Tu és devoradora de homens, e exterminadora dos filhos de teu povo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Por isso, não devorarás mais homens, e nem mais exterminarás os filhos de teus povos, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'E nunca mais te deixarei ouvir a vergonha dos povos, e nunca mais levarás sobre ti a humilhação das nações, nem mais exterminarás os filhos de teu povo, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Filho do homem, quando a casa de Israel morava em sua terra, eles a contaminaram com seus caminhos e com suas ações; o caminho deles diante de mim foi como imundície de menstruada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Por isso derramei minha ira sobre eles, por causa do sangue que derramaram sobre a terra, e por causa de seus ídolos com que a contaminaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'E os dispersei pelas nações, e foram espalhados pelas terras; eu os julguei conforme seus caminhos e conforme seus atos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'E quando chegaram às nações para onde foram, profanaram meu santo nome, pois deles se dizia: Estes são povo do SENHOR, e da terra dele saíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Porém eu os poupei em favor a meu santo nome, o qual a casa de Israel profanou entre as nações para onde foram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Portanto dize à casa de Israel: Assim diz o Senhor DEUS: Eu não faço isso por vós, ó casa de Israel, mas sim por causa de meu santo nome, o qual vós profanastes entre as nações para onde fostes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Pois santificarei meu grande nome, que foi profanado entre as nações, o qual vós profanastes no meio delas; e as nações saberão que eu sou o SENHOR, diz o Senhor DEUS, quando eu for santificado em vós, diante de olhos delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Porque eu vos tomarei das nações, e vos ajuntarei de todas as terras, e vos trarei para vossa própria terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Então aspergirei água pura sobre vós, e sereis purificados; eu vos purificarei de todas vossas imundícies, e de todos os vossos ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'E vos darei um novo coração, e porei um novo espírito dentro de vós; e tirarei de vossa carne o coração de pedra, e vos darei um coração de carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'E porei meu Espírito dentro de vós, e farei com que andeis em meus estatutos, guardeis meus juízos, e os pratiqueis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'E habitareis na terra que dei a vossos pais; e vós sereis meu povo, e eu serei vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'E eu vos livrarei de todas as vossas imundícies; e chamarei ao trigo, e o multiplicarei, e não vos darei fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Também multiplicarei o fruto dos árvores, e o produto do campo, para que nunca mais recebais a humilhação da fome entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Então vos lembrareis de vossos maus caminhos, e de vossos atos que não foram bons; e tereis nojo de vós mesmos por vossas maldades, e por vossas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Não faço isto por vós, diz o Senhor DEUS, notório vos seja; envergonhai-vos e humilhai-vos de vossos caminhos, ó casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Assim diz o Senhor DEUS: No dia que vos purificar de todas as vossas maldades, então farei as cidades serem habitadas, e as ruínas serão reedificadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'E a terra assolada será lavrada, em lugar de ser assolada diante dos olhos de todos os que passavam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'E dirão: Esta terra que era assolada ficou como o jardim do Éden; e as cidades abandonadas, assoladas e arruinadas estão fortalecidas e habitadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Então as nações que restarem ao vosso redor saberão que eu, o SENHOR, reedifico as cidades destruídas, e replanto as assoladas; eu, o SENHOR, falei e farei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Assim diz o Senhor DEUS: Ainda permitirei serei buscado pela casa de Israel para lhes fazer isto: eu os multiplicarei de pessoas como a ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Tal como as ovelhas santificadas, como as ovelhas de Jerusalém em suas solenidades, assim também as cidades desertas serão cheias de rebanhos de pessoas; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'A mão do SENHOR veio sobre mim, e me tirou por meio do Espírito do SENHOR, e me pôs no meio de um vale que estava cheio de ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'E me fez passar perto deles ao redor; e eis que havia muitos sobre a face do vale, e eis que estavam sequíssimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'E perguntou-me: Filho do homem, por acaso viverão estes ossos? E eu respondi: Senhor DEUS, tu o sabes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Então disse-me: Profetiza sobre estes ossos, e dize-lhes: Ossos secos, ouvi a palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Assim diz o Senhor DEUS a estes ossos: Eis que eu farei entrar espírito em vós, e vivereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'E porei nervos sobre vós, farei subir carne sobre vós, cobrirei de pele sobre vós, porei espírito em vós, e vivereis; e sabereis que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Então profetizei como havia me sido mandado; e houve um ruído enquanto eu profetizava, e eis que se fez um tremor, e os ossos se aproximaram, cada osso a seu osso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'E olhei, e eis que havia nervos sobre eles, e a carne subiu, e a pele cobriu por cima deles; porém não havia espírito neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Então me disse: Profetiza ao espírito, profetiza, ó filho do homem, e dize ao espírito: Assim diz o Senhor DEUS: Vem dos quatro ventos, ó espírito, e sopra sobre estes mortos, para que vivam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'E profetizei como havia me sido mandado; então o espírito entrou neles, e viveram, e se puseram de pé, um exército extremamente grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Então me disse: Filho do homem, estes ossos são toda a casa de Israel. Eis que eles dizem: Nossos ossos se secaram, e nossa esperança pereceu; fomos exterminados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Portanto profetiza, e dize-lhes: Assim diz o Senhor DEUS: Eis que eu abrirei vossos sepulturas, ó povo meu, e vos farei subir de vossas sepulturas, e vos trarei à terra de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'E sabereis que eu sou o SENHOR, quando eu abrir vossas sepulturas, e vos fizer subir de vossas sepulturas, ó povo meu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'E porei meu espírito em vós, e vivereis, e vos porei em vossa terra; e sabereis que eu, o SENHOR, falei e fiz, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Tu, pois, ó filho do homem, toma para ti agora uma vara de madeira, e escreve nela: A Judá, e aos filhos de Israel, seus companheiros. Toma para ti depois outra vara de madeira, e escreve nela: A José, vara de Efraim, e a toda a casa de Israel, seus companheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'E junta-as um à outra, para que sejam um para ti como uma só vara de madeira; e serão uma em tua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'E quando te falarem os filhos de teu povo, dizendo: Por acaso não nos explicarás que tu queres dizer com isso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Então tu lhes dirás: Assim diz o Senhor DEUS: Eis que eu tomo a vara de José que esteve na mão de Efraim, e das tribos de Israel seus companheiros, e os juntarei com ele à vara de Judá, e as farei uma só vara, e serão uma minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'E as varas sobre as quais houverdes escrito estarão em tua mão diante dos olhos deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Dize-lhes, pois: Assim diz o Senhor DEUS: Eis que eu tomarei os filhos de Israel dentre as nações para onde foram, e os ajuntarei desde os arredores e os trarei à sua própria terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'E deles farei uma nação na terra, nos montes de Israel; e um único rei será rei deles todos; e nunca mais serão duas nações, nem nunca mais serão divididos em dois reinos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'E nunca mais se contaminarão com seus ídolos, nem com suas abominações, nem com qualquer de suas transgressões; e os livrarei de todas as suas habitações em que pecaram, e os purificarei; assim eles serão meu povo, e eu serei o Deus deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'E meu servo Davi será rei sobre eles, e todos eles terão um só pastor; e andarão em meus juízos, guardarão meus estatutos, e os praticarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'E habitarão na terra que dei a meu servo Jacó, na qual vossos pais habitaram; e nela habitarão eles, seus filhos, e os filhos de seus filhos para sempre; e meu servo Davi será o príncipe deles eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'E farei com eles um pacto de paz; será um pacto perpétuo com eles; e os porei, e os multiplicarei, e porei meu santuário no meio deles para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'E com eles estará meu tabernáculo; serei o Deus deles, e ele serão meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'E as nações saberão que eu, o SENHOR, santifico a Israel, quando meu santuário estiver no meio deles para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'E veio a mim a palavra do SENHOR, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Filho do homem, dirige teu rosto contra Gogue, da terra de Magogue, príncipe-chefe de Meseque e Tubal, e profetiza contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'E dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Gogue, príncipe-chefe de Meseque e de Tubal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'E eu te farei virar, e porei anzóis em tuas queixos, e te levarei com todo o teu exército, cavalos e cavaleiros, todos eles vestidos com armadura completa, uma grande multidão com escudos pequenos e grandes, todos eles manejando espada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Persas, cuxitas, e os de Pute com eles; todos eles com escudo e capacete;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gômer, e todas as suas tropas; a casa de Togarma, dos lados do norte, e todas as suas tropas; muitos povos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Prepara-te, e apronta-te, tu, e toda as tuas multidões que se juntaram a ti, e sê tu guardião delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Depois de muitos dias serás tu visitado; ao fim de anos virás à terra que foi restaurada da espada, ajuntada de muitos povos, aos montes de Israel, que sempre serviram de assolação; mas aquele povo foi trazido das nações, e todos eles habitarão em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Então tu subirás, virás como uma tempestade devastadora; serás como nuvem para cobrir a terra, tu, todas as tuas tropas, e muitos povos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Assim diz o Senhor DEUS: E será naquele dia, que subirão palavras em teu coração, e pensarás mau pensamento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'E dirás: Subirei contra terra das aldeias sem muros, virei contra os que estão em repouso, que habitam em segurança, todos eles habitam sem muros, não têm ferrolhos nem portas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Para tomar despojo e para saquear presa; para virar tua mão contra as terras desertas que agora estão habitadas, e contra o povo que foi ajuntado das nações, que é dono de gados e de posses, que mora no meio da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Seba, Dedã, os mercadores de Társis, e todos seus filhotes de leões te dirão: Por acaso vens para tomar despojos? Reuniste tua multidão para saquear presa, para lavar prata e ouro, para tomar gados e posses, para tomar grandes despojos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Portanto profetiza, ó filho do homem, e dize a Gogue: Assim diz o Senhor DEUS: Por acaso naquele dia, quando meu povo Israel habitar em segurança, tu não o reconhecerás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Virás, pois, de teu lugar, das regiões do norte, tu e muitos povos contigo, todos eles a cavalo, uma grande reunião, e imenso exército;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'E subirás contra meu povo Israel como uma nuvem para cobrir a terra; isto será no fim dos dias; então eu te trarei contra minha terra, para que as nações me conheçam, quando eu houver me santificado em ti, ó Gogue, diante de seus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Assim diz o Senhor DEUS: Não és tu aquele de quem eu disse nos tempos passados, por meio dos meus servos, os profetas de Israel, que naqueles dias profetizaram vários anos que eu te traria contra eles?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Porém será naquele tempo, quando Gogue vier contra a terra de Israel, diz o Senhor DEUS, que minha fúria subirá ao meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Porque falei em meu zelo, no fogo de minha ira, que naquele dia haverá grande tremor sobre a terra de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'De tal maneira que diante de mim tremerão os peixes do mar, as aves do céu, os animais do campo, todos os répteis andam se arrastrando sobre a terra, e todos os seres humanos que estão sobre a face da terra; e os montes serão derrubados, os precipícios cairão, e todos os muros cairão por terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Pois chamarei contra ele a espada em todos os meus montes, diz o Senhor DEUS; a espada de cada um será contra seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'E disputarei contra ele com pestilência e com sangue; e farei haver uma grande pancada de chuva, grandes pedras de granizo, fogo e enxofre sobre ele, sobre suas tropas, e sobre os muitos povos que estiverem com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Assim me engrandecerei e me santificarei, e serei conhecido em olhos de muitas nações; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Tu pois, ó filho do homem, profetiza contra Gogue, e dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Gogue, príncipe-chefe de Meseque e Tubal;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Eu te virarei, te arrastarei, te farei subir das regiões do norte, e te trarei sobre os montes de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Tirarei teu arco de tua mão esquerda, e farei cair tuas flechas de tua mão direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Nos montes de Israel cairás tu, todas tuas tropas, e os povos que estão contigo; eu te dei como alimento para toda ave e todo pássaro de asas, e aos animais do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Sobre a face do campo cairás; porque assim eu falei, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'E enviarei fogo em Magogue, e sobre os que habitam em segurança nas terras costeiras; e saberão que eu sou o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'E farei notório meu santo nome no meio de meu povo Israel, e nunca mais deixarei profanar meu santo nome; e as nações saberão que eu sou o SENHOR, o Santo em Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Eis que isto vem e acontecerá, diz o Senhor DEUS; este é o dia do qual tenho falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'E os moradores das cidades de Israel sairão, e acenderão fogo e queimarão armas, escudos grandes e pequenos, arcos, flechas, bastões de mão, e lanças; e as queimarão no fogo por sete anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'E não trarão lenha do campo, nem a cortarão dos bosques; em vez disso, queimarão as armas no fogo; e tomarão daqueles que deles tomaram, despojarão aos que os despojaram, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'E será naquele tempo, que ali darei a Gogue um lugar de sepultura em Israel, o vale dos que passam ao oriente do mar, e este será um obstáculo aos que passarem; e ali sepultarão a Gogue e a toda sua multidão; e o chamarão de “o vale da multidão de Gogue”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'E durante sete meses a casa de Israel os enterrará para purificar a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Pois todo o povo do país os enterrará, e será notório para eles o dia em que eu for glorificado, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'E separarão homens para que continuamente percorram a terra de Israel, e enterrem aos passantes que restaram sobre a face da terra, para que purifiquem; ao fim de sete meses completarão a busca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'E os que passam pela terra, caso passem e vejam algum osso humano, levantará junto a ele um marco, até que os coveiros o enterrem no vale da multidão de Gogue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'E também o nome da cidade será Hamoná; assim purificarão a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Tu, pois, ó filho do homem, assim diz o Senhor DEUS; Dize às aves, a todos os pássaros, e a todos os animais do campo: Ajuntai-vos, e vinde; reuni-vos de todas partes ao meu sacrifício que eu sacrifiquei por vós, um sacrifício grande nos montes de Israel; comei carne, e bebei sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Comereis carne de guerreiros, e bebereis sangue de príncipes da terra; de carneiros, de cordeiros, de bodes, e de bezerros, todos eles cevados de Basã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'E comereis gordura até vos fartardes, e bebereis sangue até vos embebedardes, do meu sacrifício que eu sacrifiquei por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'E vos fartareis à minha mesa, de cavalos, de cavaleiros, de guerreiros, e de todos os homens de guerra, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'E porei minha glória entre as nações; e todas as nações verão meu julgamento que fiz, e minha mão que pus sobre elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'E daquele dia em diante a casa de Israel saberá que eu sou o SENHOR seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'E as nações saberão que os da casa de Israel foram levados ao cativeiro por sua própria maldade, porque se rebelaram contra mim; então escondi meu rosto deles, e os entreguei na mão de seus adversários, e todos caíram à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Conforme a imundície deles e conforme suas rebeliões eu fiz com eles; e deles escondi meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Portanto assim diz o Senhor DEUS: Agora restaurarei Jacó de seu infortúnio, terei misericórdia de toda a casa de Israel, e zelarei por meu santo nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Quando eles tiverem levado sobre si sua vergonha, e toda sua rebeldia com que se rebelaram contra mim, quando habitarem seguros em sua terra, e não houver quem os espante;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Quando eu trouxé-los de volta dos povos, e os juntar das terras de seus inimigos, e for eu santificado neles diante dos olhos de muitas nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Então saberão que eu sou o SENHOR seu Deus, porque eu os fiz serem levados em cativeiro entre as nações, e os ajuntarei de volta em sua terra, sem deixar mais nenhum deles lá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Nem esconderei mais deles meu rosto; pois derramarei meu Espírito sobre a casa de Israel, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'No vigésimo quinto ano de nosso cativeiro, no princípio do ano, aos dez do mês, aos catorze anos depois que a cidade foi ferida, naquele mesmo dia veio sobre mim a mão do SENHOR, e me levou para lá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Em visões de Deus me levou à terra de Israel, e me pôs sobre um monte muito alto, sobre o qual havia como um edifício de uma cidade ao sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'E havendo me levado ali, eis um homem cuja aparência era como a aparência de bronze, e tinha um cordel de linho em sua mão, e uma cana de medir; e ele estava em pé à porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'E aquele homem me falou: Filho do homem, olha com teus olhos, ouve com teus ouvidos, e põe teu coração em tudo quanto eu te mostrar, pois foste trazido aqui para que eu te mostrasse. Anuncia, pois, à casa de Israel tudo o que vires.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'E eis, um muro fora do templo ao redor; e na mão daquele homem uma cana de medir de seis côvados, cada côvado de um côvado e um palmo; e mediu a largura do edifício de uma cana, e a altura, de outra cana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Então ele veio à porta que estava voltada para o oriente, subiu por seus degraus, e mediu o umbral da porta de uma cana de largura, e o outro umbral de outra cana de largura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'E cada câmara tinha uma cana de comprimento, e uma cana de largo; e entre as câmaras eram cinco côvados; e o umbral da porta junto ao alpendre da porta por dentro, uma cana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Também mediu o alpendre da porta por de dentro, uma cana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Então mediu o alpendre da porta, de oito côvados, e seus pilares de dois côvados; e o alpendre da porta por dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'E as câmaras pequenas da porta do oriente eram três de um lado e três do outro; todas as três de uma mesma medida; também os pilares de um lado e do outro tinham uma mesma medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'E mediu a largura da entrada da porta, de dez côvados; o comprimento do portal era de treze côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'E o espaço de diante das câmaras pequenas era de um côvado de um lado, e de um côvado do outro lado; e cada câmara tinha seis côvados de um lado, e seis côvados do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Então mediu a porta desde o teto da uma câmara pequena até o teto da outra, vinte e cinco côvados de largura, porta contra porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Também fez medição com os pilares de sessenta côvados, o pilar do pátio ao redor da porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'E desde a dianteira da porta de entrada até a dianteira do alpendre da porta interior havia cinquenta côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Havia também janelas estreitas nas câmaras pequenas, e em seus pilares por dentro ao redor da porta, e assim também nos alpendres; e as janelas estavam ao redor por dentro; e em cada poste havia palmeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Então me levou ao átrio exterior, e eis que havia nele câmaras, e um pavimento feito no pátio ao redor; trinta câmaras havia naquele pavimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'E o pavimento ao lado das portas era equivalente ao comprimento das portas (este era o pavimento inferior).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'E mediu a largura desde a dianteira da porta inferior até a dianteira do pátio interior pelo lado de fora: cem côvados pelo oriente e pelo norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'E quanto à porta que estava voltada para o norte no átrio exterior, mediu seu comprimento e sua largura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'E suas câmaras pequenas eram três de um lado, e três de outro; e seus pilares e seus alpendres eram da mesma medida da primeira porta: cinquenta côvados era seu comprimento, e a largura era de vinte e cinco côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'E suas janelas, e seus alpendres, e suas palmeiras, eram da medida da porta que estava voltada para o oriente; e subiam a ela por sete degraus; e seus alpendres eram diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'E havia uma porta do pátio interior que ficava em frente da porta ao norte; e assim também outra ao oriente; e mediu de porta a porta cem côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Então me levou em direção ao sul, e eis que havia uma porta para o sul; e mediu seus pilares e seus alpendres, conforme a estas medidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'E também tinha janelas, assim com havia janelas nos seus alpendres ao redor; o comprimento era de cinquenta côvados, e a largura de vinte e cinco côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'E suas subidas eram de sete degraus, com seus alpendres diante deles; e tinha palmeiras de um lado e do outro em seus pilares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Também havia uma porta no pátio interior voltada para o sul; e mediu de porta a porta para o sul, cem côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Então ele me levou ao pátio interior pela porta do sul; e mediu a porta do sul conforme a estas medidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'E suas câmaras pequenas, e seus pilares e seus alpendres eram conforme a estas medidas; e também tinham janelas ao redor de seus alpendres; o comprimento era de cinquenta côvados, e de a largura de vinte e cinco côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'E os alpendres ao redor eram de vinte e cinco côvados de comprimento e cinco côvados de largura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'E seus alpendres estavam no pátio externo, com palmeiras em seus pilares; e suas subidas eram de oito degraus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Depois me levou ao pátio interior, para o oriente, e mediu a porta conforme a estas medidas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Assim como suas câmaras pequenas, seus pilares, e seus alpendres, conforme a estas medidas; e também tinha suas janelas ao redor de seus alpendres; o comprimento era de cinquenta côvados, e a largura de vinte e cinco côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'E seus alpendres estavam no pátio externo, com palmeiras em seus postes de um lado e do outro; e suas subidas eram de oito degraus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Então me levou à porta do norte, e mediu conforme a estas medidas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Suas câmaras pequenas, seus pilares, e seus arcos, também tinham janelas ao redor; o comprimento era de cinquenta côvados, e a largura de vinte e cinco côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'E seus pilares estavam no pátio exterior, com palmeiras em seus pilares de um lado e do outro; e suas subidas eram de oito degraus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'E sua câmara e sua porta estavam junto dos pilares das portas, onde lavavam a oferta de queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'E no alpendre da porta havia duas mesas da um lado, e outras duas do outro, para nelas degolar a oferta de queima, o sacrifício pelo pecado, e o pela culpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'E ao lado de fora da subida para a entrada da porta do norte havia duas mesas; e do outro lado que estava no alpendre da porta, havia duas mesas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Quatro mesas de um lado, e quatro mesas do outro lado, junto à porta; oito mesas, sobre as quais degolavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'E as quatro mesas para a oferta de queima eram de pedras lavradas, de um côvado e meio de comprimento, e um côvado e meio de largura, e um côvado de altura; sobre elas eram postos os instrumentos com que degolavam a oferta de queima e o sacrifício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'E havia ganchos de um palmo, dispostos por dentro ao redor; e sobre as mesas a carne da oferta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'E de fora da porta interior estavam as câmaras dos cantores no pátio de dentro que era do lado da porta do norte; as quais estavam voltadas para o sul; uma estava ao lado da porta do oriente que estava voltada para o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'E me falou: Esta câmara que está voltada para o sul é para os sacerdotes que têm a guarda do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Mas a câmara que está voltada para o norte é para os sacerdotes que têm a guarda do altar; estes são os filhos de Zadoque, dentre os filhos de Levi os que se achegam ao SENHOR, para o servir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'E mediu o pátio, cem côvados de comprimento, e cem côvados de largura, quadrado; e o altar estava diante do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Então ele me levou ao alpendre do templo, e mediu cada pilar do alpendre, cinco côvados de um lado, e cinco côvados do outro; e a largura da porta era três côvados de um lado, e três côvados do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'O comprimento do alpendre era vinte côvados, e a largura onze côvados; e era com degraus, pelos quais se subia; e havia colunas junto aos pilares, uma de um lado, e outra do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Então ele me levou ao templo e mediu os pilares, seis côvados a largura de um lado, e seis côvados do outro, que era a largura da tenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'E a largura da entrada era de dez côvados; e os lados da entrada, de cinco côvados de um lado, e cinco do outro. Também mediu seu comprimento de quarenta côvados, e a largura de vinte côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Então entrou, e mediu o pilar da entrada de dois côvados, e a entrada de seis côvados; e a largura da entrada de sete côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Também mediu seu comprimento, de vinte côvados, e a largura de vinte côvados, diante do templo; e me disse: Este é o Santo dos Santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Depois mediu a parede do templo, de seis côvados; e quatro côvados era a largura das câmaras que ficavam de lado ao redor do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'E as câmaras laterais eram em três andares câmara sobre câmara, e havia trinta para cada andar; e havia apoios na parede ao redor do templo, sobre os quais as câmaras se apoiavam, pois não se apoiavam na parede do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'E havia maior largura nas câmaras laterais mais para cima, pois o entorno do templo subia de andar em andar ao redor do templo; por isso o templo era mais largo acima; e se subia da câmara baixa se subia à alta pela do meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'E olhei para a altura da casa ao redor; os fundamentos das câmaras laterais eram de uma cana inteira de seis côvados maiores de tamanho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'A largura da parede das câmaras externas era de cinco côvados, e o espaço que restava era o lugar das câmaras laterais que eram junto ao templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'E entre as câmaras havia a largura de vinte côvados ao redor do templo por todos os lados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'E as entradas de cada câmara estavam voltadas para o espaço vazio; uma entrada para o norte, e outra entrada para o sul; e a largura do espaço vazio era de cinco côvados ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'E o edifício que estava diante do lugar separado ao lado do ocidente era da largura de setenta côvados; e a parede do edifício era de cinco côvados de largura ao redor, e seu comprimento era de noventa côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'E mediu o templo, cem côvados de comprimento; e o lugar separado, e o edifício, e suas paredes, de comprimento de cem côvados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'E a largura da dianteira do templo, e do lugar separado ao oriente, era de cem côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Também mediu o comprimento do edifício que estava diante do lugar separado que estava detrás dele, e suas galerias de um lado e do outro eram de cem côvados, com o templo interno, e os alpendres do pátio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Os umbrais, e as janelas estreitas, e as galerias ao redor dos três andares, de frente ao umbral, estavam cobertas de madeira ao redor, desde o chão até as janelas; e as janelas estavam cobertas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Até o que havia acima da porta, e até o templo interior e exterior, e até toda a parede em redor, por dentro e por fora, tudo por medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'E era feita com querubins e palmeiras, de maneira que cada palmeira ficava entre um querubim e outro; e cada querubim tinha dois rostos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Um rosto de homem voltado para palmeira da uma lado, e um rosto de leão voltado para a palmeira do outro lado, assim era por todo o templo ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Desde o chão até encima da entrada foram feitos os querubins e as palmeiras, e também por toda a parede do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Os umbrais do templo eram quadrados; e a dianteira do santuário tinha a aparência como a da outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'O altar de madeira era de três côvados de altura, e seu comprimento de dois côvados; e seus cantos, seu comprimento, e suas laterais eram de madeira. E ele me falou: Esta é a mesa que está diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'E o templo e o santuário, ambos tinham duas portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'E em cada portada havia duas divisões que podiam se virar; duas divisões em uma porta, e duas na outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'E nelas, nas portas do templo, foram feitos querubins e palmeiras, assim como estavam feitos nas paredes; e havia uma viga espessa de madeira na dianteira do alpendre por fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'E havia janelas estreitas e palmeiras de um lado e do outro, pelas laterais do alpendre, assim como nas câmaras laterais do templo, e nas vigas espessas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Depois disto ele me fez sair para o pátio externo, para o lado norte, e me levou às câmaras que estavam de frente ao lugar vazio, e que estavam de frente ao edifício voltado para o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Pela frente à entrada do norte o comprimento era de cem côvados, e a largura era de cinquenta côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Em frente dos vinte côvados que tinha no átrio de dentro, e em frente do solado que tinha o pátio exterior, havia galerias de frente umas às outras em três andares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'E diante das câmaras havia um corredor de dez côvados de largura, do lado de dentro, com um caminho de um côvado; e suas entradas para o norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'E as câmaras de cima eram mais estreitas, pois as galerias eram mais altas que as outras, isto é,que as de baixo, e que as do andar do meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Porque elas estavam em três andares,porém não tinham colunas como as colunas dos pátios; por isso eram mais estreitas que as de baixo e as do meio, desde o chão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'E o muro que estava por fora de frente às câmaras, voltado para o pátio exterior diante das câmaras, tinha cinquenta côvados de comprimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Porque o comprimento das câmaras do pátio de fora era de cinquenta côvados; e eis que de frente ao templo havia cem côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'E debaixo destas câmaras estava a entrada do oriente, para entrar nelas do pátio de fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Na largura do muro do pátio ao oriente, diante do lugar vazio, e diante do edifício, havia câmaras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'E o caminho que havia diante delas era semelhante ao das câmaras que estavam ao norte, conforme seu comprimento, assim como sua largura; e todas as suas saídas eram conforme suas formas e conforme suas entradas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'E conforme as entradas das câmaras que estavam para o sul, havia também uma entrada no princípio do caminho, do caminho diante do muro direito para o oriente, quando se entra por elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Então ele me disse: As câmaras do norte e as câmaras do sul, que estão diante do lugar vazio, elas são câmaras santas, nas quais os sacerdotes que se achegam ao SENHOR comerão as coisas mais santas; ali porão as coisas mais santas, e as ofertas de alimento, e a expiação pelo pecado e a pela culpa; pois o lugar é santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Quando os sacerdotes entrarem, não sairão do lugar santo para o pátio de fora; em vez disso, ali deixarão suas vestes com que tenham ministrado, porque são santas; e se vestirão com outras vestes, e assim se achegarão ao que é do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'E quando acabou de medir o templo interno, ele me tirou pelo caminho da porta que estava voltada para o oriente, e o mediu em redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Mediu o lado oriental com a cana de medir, quinhentas canas da cana de medir em redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Mediu ao lado do norte, quinhentas canas da cana de medir em redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Mediu ao lado do sul, quinhentas canas da cana de medir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Rodeou ao lado do ocidente, e mediu quinhentas canas da cana de medir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Aos quatro lados o mediu; e havia um muro ao redor com quinhentas canas de comprimento, e quinhentas canas de largura, para fazer separação entre o santo e o profano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Então ele me levou-me à porta; a porta que está voltada para oriente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'E eis que a glória do Deus de Israel vinha desde o caminho do oriente; e seu som era como o som de muitas águas, e a terra resplandeceu por causa de sua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'E a aparência da visão que vi era como a visão que eu tinha visto quando vim para destruir a cidade; e as visões eram como a visão que vi junto ao rio de Quebar; e caí sobre meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'E a glória do SENHOR entrou no templo pelo caminho da porta que estava voltada para o oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Então o Espírito me ergueu, e me levou ao pátio interno; e eis que a glória do SENHOR encheu o templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'E ouvi um que falava comigo desde o templo; e um homem estava em pé junto a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'E disse-me: Filho do homem, este é o lugar de meu trono, e o lugar das plantas de meus pés, onde habitarei no meio dos filhos de Israel para sempre; e a nação de Israel nunca mais contaminará meu santo nome, nem eles, nem seus reis, com suas prostituições, e com seus cadáveres de seus reis em seus altos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Quando colocavam o umbral deles junto a meu umbral, e o batente deles junto a meu batente, e era uma parede entre mim e eles; e contaminaram meu santo nome com suas abominações que fizeram; por isso eu os consumi em minha ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Agora lançaram longe de mim sua prostituição e os cadáveres de seus reis; e habitarei no meio deles para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Tu, filho do homem, mostra à nação de Israel este templo, para que se envergonhem de suas maldades, e tenham a medida do modelo do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'E se eles se envergonharem de tudo quanto fizeram, faze-lhes saber a forma da casa, e seu modelo, e suas saídas e suas entradas, e todas as suas formas, e todas os seus estatutos, e todas as suas formas, e todas as suas leis; e escreve diante de seus olhos, para que guardem toda a sua forma e todos os seus estatutos, e os façam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Esta é a lei do templo: sobre o cume do monte, todo o seu contorno em redor será santíssimo. Eis que esta é a lei do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'E estas são as medidas do altar em côvados (o côvado de um côvado e um palmo). A base, de um côvado de altura e de um côvado de largura; e o contorno de sua borda ao redor, de um palmo. Este será o fundamento do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'E desde a base de sobre o chão até a aresta inferior, dois côvados, e a largura de um côvado; e desde a aresta menor até a aresta maior, quatro côvados, e a largura de um côvado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'E a fornalha do altar, de quatro côvados, e da fornalha do altar para cima havia quatro pontas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'E o altar tinha doze côvados de comprimento e doze de largura, quadrado em seus quatro lados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'E a aresta, de catorze côvados de comprimento e catorze de largura em seus quatro lados; e o contorno ao redor dela era de meio côvado, e a base dela de um côvado em redor; e seus degraus estavam voltados para o oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'E ele me disse-me: Filho do homem, assim diz o Senhor DEUS: Estes são os estatutos do altar, no dia em que ele for feito, para oferecer sobre ele oferta de queima, e para espargir sangue sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'E aos sacerdotes Levitas que são da descendência de Zadoque, que se achegam a mim, diz o Senhor DEUS, para me servirem, tu darás um bezerro, filho de vaca, para expiação pelo pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'E tomarás de seu sangue, e porás nas pontas do altar,e nas quatro esquinas da aresta, e no contorno ao redor; assim o limparás e o expiarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Então tomarás o bezerro da expiação pelo pecado, e o queimarão no lugar específico do templo, fora do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'E no segundo dia oferecerás um bode macho sem defeito, para expiação pelo pecado; e purificarão o altar como o purificaram com o bezerro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Quando tu acabares de expiar, oferecerás um bezerro sem defeito, filhote de vaca, e um carneiro sem defeito do rebanho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'E tu os oferecerás diante do SENHOR; e os sacerdotes deitarão sal sobre eles, e os oferecerão por oferta de queima ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Por sete dias prepararás um bode macho em cada dia de purificação; também prepararão um bezerro filhote de vaca, e um carneiro do rebanho, todos sem defeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Por sete dias expiarão o altar, e o purificarão; e eles o consagrarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'E quando eles acabarem estes dias será ao oitavo dia; e dali em adiante, os sacerdotes prepararão sobre o altar vossos sacrifícios de queima e vossas ofertas de gratidão; e eu vos aceitarei, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Então ele me fez voltar ao caminho da porta de fora do santuário, a qual estava voltada para o oriente; e ela estava fechada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'E o SENHOR me disse: Esta porta estará fechada; não se abrirá, nem ninguém entrará por ela, porque o SENHOR Deus de Israel entrou por ela; por isso estará fechada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'O príncipe; somente o príncipe, ele se sentará nela, para comer pão diante do SENHOR; pelo caminho do alpendre da porta entrará, e pelo mesmo caminho sairá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Depois me levou pelo caminho da porta do norte, diante da casa; e olhei, e eis que a glória do SENHOR havia enchido a casa do SENHOR; então caí sobre meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'E o SENHOR me disse: Filho do homem, presta atenção, olha com teus olhos, e ouve com teus ouvidos tudo quanto eu falar contigo sobre todas os estatutos da casa do SENHOR, e todas as suas leis; e presta atenção na entrada da casa, e em todas as saídas do santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'E dize aos rebeldes, à casa de Israel: Assim diz o Senhor DEUS: Já basta de todas as vossas abominações, ó casa de Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Pois trouxestes estrangeiros, incircuncisos de coração e incircuncisos de carne, para estarem em meu santuário, para profanarem minha casa; pois oferecestes meu pão, a gordura e o sangue; e invalidaram meu pacto, por causa de todas as vossas abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'E não mantivestes a ordem de minhas coisas sagradas; em vez disso pusestes por vós mesmos guardas estrangeiros para minha ordem em meu santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Assim diz o Senhor DEUS: Nenhum estrangeiro, incircunciso de coração e incircunciso de carne, entrará em meu santuário, dentre todos os estrangeiros que estão entre os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Mas os Levitas que se afastaram para longe de mim, que se desviaram de mim para seguirem seus ídolos, quando Israel se desviou, esses levarão sobre si sua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Contudo serão trabalhadores em meu santuário, como porteiros às portas da casa, e servirão na casa: eles degolarão a oferta de queima e o sacrifício para o povo, e estarão diante deles para os servirem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Pois os serviram diante de seus ídolos, e foram tropeço de maldade para a casa de Israel; por isso jurei de mão levantada contra eles, diz o Senhor DEUS, que levarão sua iniquidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'E não se achegarão a mim para serem meus sacerdotes, nem se achegarão a nenhuma de minhas coisas sagradas; às coisas santíssimas; em vez disso levarão sobre si sua vergonha e suas abominações que fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Portanto os porei por guardas da ordem da casa, em todo o seu serviço, e em tudo o que houver de se fazer nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Mas os sacerdotes Levitas, filhos de Zadoque, que guardaram a guarda de meu santuário quando os filhos de Israel se desviaram de mim, eles se achegarão a mim para me servirem; e estarão diante de mim para me oferecerem a gordura e o sangue, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Eles entrarão em meu santuário, e eles se achegarão à minha mesa para me servirem; e guardarão minha ordem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'E será que, quando entrarem pelas portas do pátio interno, se vestirão de vestes de linho; não haverá sobre eles lã, quando servirem nas portas do pátio interno, e no interior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Turbantes de linho estarão em suas cabeças, e calções de linho sobre seus lombos; não se vestirão com algo que lhes cause suor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'E quando eles saírem ao pátio de fora, ao pátio de fora ao povo, despirão suas vestes com que eles prestaram serviço, as deixarão nas câmaras do santuário, e se vestirão de outras vestes, para que não santifiquem ao povo com suas vestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'E não raparão sua cabeça, nem deixarão crescer o cabelo; mas sim apararão o cabelo de suas cabeças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'E nenhum dos sacerdotes beberá vinho quando forem entrar no pátio interno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Não tomarão por mulheres nem viúva, nem divorciada, mas sim tomarão virgens da descendência da casa de Israel, ou viúva que for viúva de sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'E ensinarão meu povo a fazer diferença entre o santo e o profano, e lhes farão saber a diferença entre o impuro e o puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'E na disputa judicial eles estarão para julgar; conforme meus juízos o julgarão; e guardarão minhas leis e meus estatutos em todas as minhas solenidades, e santificarão meus sábados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'E não chegarão perto de pessoa alguma morta para se contaminarem; apenas pelo pai, mãe, filho, filha, irmão, ou irmã que não tenha tido marido, é que poderão se contaminar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'E depois de sua purificação lhe contarão sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'E no dia que ele entrar no lugar santo, no pátio interno, para prestar serviço no lugar santo, oferecerá sua expiação pelo pecado, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'E isto lhes será por herança: eu serei sua herança; por isso não lhes dareis propriedade de terra em Israel; eu sou a propriedade deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Comerão a oferta de alimentos e o sacrifícios pelo pecado e pela culpa; e toda coisa dedicada em Israel pertencerá a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'E as primícias de todos os primeiros frutos de tudo, e toda oferta de tudo o que se oferecer de todas as vossas ofertas, pertencerá aos sacerdotes; dareis também as primícias de todas vossas massas ao sacerdote, para que faça repousar a bênção em tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Os sacerdotes não poderão comer coisa alguma morta por si mesma ou despedaçada, tanto de aves como de animais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'E quando repartirdes por sortes a terra em herança, proporcionareis uma oferta ao SENHOR: um lugar santo na terra; o comprimento será de vinte e cinco mil canas, e a largura de dez mil; este será santificado em todo o seu contorno ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Deste terreno serão para o santuário quinhentas canas de comprimento, e quinhentas de largura, em quadrado ao redor; terá cinquenta côvados ao redor para seus espaços abertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'E desta medida medirás o comprimento de vinte e cinco mil côvados,e a largura de dez mil; e ali estará o santuário, e o lugar santíssimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Este será o lugar santo da terra. Eles será para os sacerdotes que trabalham no santuário, que se achegam para servir ao SENHOR; e lhes servirá de lugar para casas, e de lugar santo para o santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'E os levitas trabalhadores do templo terão como propriedade uma área de vinte e cinco mil côvados de comprimento, e dez mil de largura, com vinte câmaras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'E para propriedade da cidade dareis cinco mil canas de largura e vinte e cinco mil de comprimento, em frente da oferta para o santuário; esta será para toda a casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'E o príncipe terá sua parte de um lado e do outro da oferta ao santuário e da propriedade da cidade, diante da oferta para o santuário, e diante da propriedade da cidade, desde o canto ocidental para o ocidente, e desde o canto oriental para o oriente; e será o comprimento, em frente de uma das partes, desde o limite ocidental até o limite oriental.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Esta terra será sua propriedade em Israel, e meus príncipes nunca mais oprimirão a meu povo; ao invés disso entregarão a terra para a casa de Israel, conforme suas tribos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Assim diz o Senhor DEUS: Já basta, ó príncipes de Israel! Acabai a violência e a assolação; fazei juízo e justiça; tirai vossas imposições de meu povo, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Tereis balanças justas, efa justo, e bato justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'O efa e o bato serão de uma mesma medida; que o bato contenha a décima parte de um ômer, e o efa a décima parte de um ômer; a medida deles será conforme o ômer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'E o siclo será de vinte geras: vinte siclos, mais vinte e cinco siclos, mais quinze siclos, vos serão uma mina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Esta será a oferta que oferecereis: a sexta parte de um efa de ômer do trigo; também dareis a sexta parte de um efa de ômer da cevada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'E quanto ao estatuto do azeite, oferecereis um bato de azeite, (o bato que é a décima parte de um coro, que é um ômer de dez batos; porque dez batos são um ômer).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'E uma cordeira de cada duzentas do rebanho, da mais regada terra de Israel, para oferta de alimento, para oferta de queima e oferta de gratidão, para fazer expiação por eles, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Todo o povo do país terá que dar esta oferta para o príncipe de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'E o príncipe terá que dar as ofertas de queima, as ofertas de alimento, e as ofertas de bebidas, nas solenidades, nas luas novas, nos sábados, e em todas as festas da casa de Israel; ele fará a expiação pelo pecado, a oferta de alimento, a oferta de queima, e as ofertas de gratidão, para fazer expiação pela casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Assim diz o Senhor DEUS: Ao primeiro mês,ao primeiro dia do mês, tomarás um bezerro sem defeito filho de vaca, e purificarás o santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'E o sacerdote tomará do sangue do sacrifício pela expiação, e porá dele sobre os umbrais da casa, e sobre as quatro pontas da aresta do altar, e sobre os umbrais da porta do pátio interno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Assim também farás no sétimo dia do mês pelos que pecaram sem intenção ou por ignorância; assim expiarás a casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'No primeiro mês,aos catorze dias do mês, tereis a páscoa, festa de sete dias; será comido pão sem fermento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'E no mesmo dia o príncipe preparará por si e por todo o povo do país um bezerro de expiação pelo pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'E nos sete dias da festa ele preparará oferta de queima ao SENHOR, de sete bezerros e sete carneiros sem defeito, cada dia dos sete dias; e um bode como expiação pelo pecado a cada dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Também preparará uma oferta de alimento: um efa para cada bezerro, e um efa para cada carneiro; e um him de azeite para cada efa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'No sétimo mês,aos quinze dias do mês, na festa, ele fará o mesmo todos os sete dias, quanto ao sacrifício pela expiação, à oferta de queima, à oferta de alimento, e ao azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Assim diz o Senhor DEUS: A porta do pátio de dentro que está voltada para oriente ficará fechada durante os seis dias de trabalho, porém no dia do sábado será aberta; também no dia de lua nova será aberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'E o príncipe entrará pelo caminho do alpendre da porta de fora, e estará em pé junto ao umbral da porta, enquanto os sacerdotes prepararão sua oferta de queima e suas ofertas de gratidão; e ele ficará adorando junto ao umbral da porta, e depois sairá; porém a porta não será fechada até o anoitecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'E o povo da terra ficará prostrado diante do SENHOR junto à entrada da mesma porta, nos sábados e nas luas novas,.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'E a oferta de queima que o príncipe oferecerá ao SENHOR no dia do sábado será seis cordeiros sem defeito e um carneiro sem defeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'E a oferta de alimento será um efa para cada carneiro; e para cada cordeiro um presente será o quanto ele puder dar, e um him de azeite para cada efa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Mas no dia da nova lua será um bezerro sem mancha, seis cordeiros, e um carneiro, que deverão ser sem defeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'E preparará por oferta de alimento um efa para o bezerro, e um efa para o carneiro; mas para os cordeiros, conforme o quanto puder; e um him de azeite para cada efa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'E quando o príncipe entrar, ele entrará pelo caminho do alpendre da porta, e sairá pelo mesmo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Mas quando o povo da terra vier para diante do SENHOR nas solenidades, aquele que entrar pelo caminho da porta do norte para adorar sairá pelo caminho da porta do sul; e aquele que entrar pelo caminho da porta do sul sairá pelo caminho da porta do norte; não voltará pelo caminho da porta por onde entrou, mas sairá pela que estiver à frente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'E o príncipe entrará no meio deles quando eles entrarem, e quando eles saírem, sairão juntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'E nas festas e nas solenidades será a oferta de alimento um efa para cada bezerro, e um efa para cada carneiro; mas para os cordeiros, conforme o que ele puder dar; e um him de azeite para cada efa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'E quando o príncipe fizer uma oferta voluntária de queima, ou ofertas de gratidão como oferta voluntária ao SENHOR, então lhe abrirão a porta que está voltada para o oriente; e ele fará sua oferta de queima e suas ofertas de gratidão assim como tiver feito no dia do sábado; depois sairá, e fecharão a porta depois dele sair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'E a cada dia prepararás um cordeiro sem defeito de um ano sem defeito como oferta de queima ao SENHOR; todas as manhãs o prepararás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'E juntamente com ele todas as manhãs prepararás uma oferta de alimento, a sexta parte de um efa, e a terça parte de um him de azeite para misturar com a flor de farinha; será uma oferta de alimento para o SENHOR, continuamente, por estatuto perpétuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Assim prepararão o cordeiro e a oferta de alimento, todas as manhãs, em contínua oferta de queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Assim diz o Senhor DEUS: Quando o príncipe der de presente algo de sua herança a algum de seus filhos, isto pertencerá a seus filhos; será propriedade deles por herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Porém se ele der de presente algo de sua herança a alguém de seus servos, pertencerá a ele até o ano da liberdade; então voltará ao príncipe, porque sua herança é de seus filhos; eles a herdarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'E o príncipe não tomará nada da herança do povo, para os destituir da propriedade deles; de sua propriedade particular ele deixará de herança para seus filhos, para que meu povo não seja disperso, cada um de sua propriedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Depois disto ele me trouxe pela entrada que estava ao lado da porta, às câmaras santas dos sacerdotes, as quais estavam voltadas para o norte; e havia ali um lugar no final, para o ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'E me disse: Este é o lugar onde os sacerdotes cozerão o sacrifício pela culpa e o pelo pecado; ali cozerão a oferta de alimento, para não a trazerem ao pátio de fora para santificar ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Então ele me levou ao pátio de fora, e me fez passar pelos quatro cantos do pátio; e eis que em cada canto do pátio havia outro pátio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Nos quatro cantos do pátio havia outros pátios fechados de quarenta côvados de comprimento, e trinta de largura; estes quatro cantos tinham uma mesma medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'E havia uma parede ao redor deles, ao redor dos quatro; e lugares de cozinhar abaixo ao redor das paredes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'E me disse: Estas são as cozinhas, onde os trabalhadores da casa cozerão o sacrifício do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Depois disto ele me fez voltar à entrada da casa; e eis que águas saíam de debaixo do umbral da casa para o oriente, pois a fachada da casa estava para o oriente; e as águas desciam de debaixo, desde o lado direito da casa, do lado sul do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'E tirou-me pelo caminho da porta do norte, e me fez rodear pelo caminho de fora, até a porta externa, pelo caminho voltado ao oriente; e eis que as águas corriam desde o lado direito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'E quando aquele homem saiu para o oriente, tinha um cordel de medir em sua mão; ele mediu mil côvados, e me fez passar pelas águas, que chegavam até os tornozelos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'E mediu mil côvados,e me fez passar pelas águas, que chegavam até os joelhos. Mediu mais mil, e me fez passar pelas águas, que chegavam até os lombos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'E mediu mais mil, e já era um rio que eu não podia passar, porque as águas ficaram tão profundas que o rio não se podia atravessar, a não ser a nado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Então me disse: Viste isto,filho do homem? Depois ele me levou e me fez voltar pela margem do ribeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'E enquanto eu voltava, eis que na margem do ribeiro do ribeiro havia muitíssimas árvores, de um lado e do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Então me disse: Estas águas saem para a região do oriente, descem à planície, e entram no mar: e quando saem para o mar, as águas se tornam saudáveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'E será que toda alma vivente que se move por onde quer que estes dois ribeiros passarem, viverá; e haverá muitíssimos peixes por ali terem passado estas águas, e ficarão saudáveis; e tudo viverá por onde quer que este este ribeiro passar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Será também que pescadores estarão junto a ele; desde En-Gedi até En-Eglaim haverá lugares para se estender redes; seus peixes serão segundo suas espécies, como os peixes do grande mar, muitos em grande quantidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Porém seus charcos e seus pântanos não ficarão saudáveis; estarão entregues ao sal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'E junto ao ribeiro, em sua margem de um lado e do outro, crescerá toda árvore para comer; sua folha nunca cairá, nem perecerá seu fruto; em todos os seus meses produzirá frutos, porque suas águas saem do santuário; e seu fruto servirá para comer, e sua folha para remédio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Assim diz o Senhor DEUS: Este é o limite em que tomareis a terra em herança segundo as doze tribos de Israel: José terá duas partes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'E a herdareis igualmente uns como os outros; pela qual jurei de mão levantada que a daria a vossos pais; portanto esta terra se tornará vossa herança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'E este será o limite da terra para o lado norte: desde o grande mar, a caminho de Hetlom vindo a Zedade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamate, Berota, Sibraim (que está entre o limite de Damasco e o limite de Hamate); Hazer- Haticom, que está junto ao limite de Haurã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'E o limite será desde o mar até Haser-Enom, ao limite de Damasco ao norte, e ao limite de Hamate; este será o lado norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Ao lado do oriente medireis desde entre Haurã e Damasco, e desde entre Gileade e a terra de Israel, junto ao Jordão; desde o limite do mar do oriente; este será o lado do oriente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'E ao lado sul, ao sul, será desde Tamar até as águas das inimizades; desde Cades e o ribeiro até o grande mar: e este será o lado sul, ao sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'E o lado do ocidente será o grande mar, desde o limite até chegar a Hamate: este será o lado do ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Repartireis, pois, esta terra entre vós segundo as tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'E será que a sorteareis em herança para vós, e para os estrangeiros que peregrinam entre vós, que geraram filhos entre vós; e vos serão como nativos entre os filhos de Israel; repartirão herança convosco, entre as tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'E será que na tribo onde o estrangeiro peregrinar, ali lhe dareis sua herança,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'E estes são os nomes das tribos: Desde o extremo norte, do lado do caminho de Hetlom, vindo para Hamate, Hazar-Enom, ao limite de Damasco, para o norte, ao lado de Hamate; sendo seus extremos do oriente e do ocidente: esta é a porção de Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Junto ao limite de Dã, desde o extremo oriente até o extremo ocidente: esta é a porção de Aser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Junto ao limite de Aser, desde o extremo oriente até o extremo ocidente: esta é a porção de Naftali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Junto ao limite de Naftali, desde o extremo oriente até o extremo ocidente: esta é a porção de Manassés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Junto ao limite de Manassés, desde o extremo oriente até o extremo ocidente: esta é a porção de Efraim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Junto ao limite de Efraim, desde o extremo oriente até o extremo ocidente: esta é a porção de Rúben.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Junto ao limite de Rúben, desde o extremo oriente até o extremo ocidente: esta é a porção de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'E junto ao limite de Judá, desde o lado do oriente até o lado do ocidente, será a oferta que reservareis, de vinte e cinco mil canas de largura, e de comprimento, como uma das demais partes, desde o lado do oriente até o lado do ocidente; e o santuário estará no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'A oferta que reservareis ao SENHOR será de vinte e cinco mil canas de comprimento e dez mil de largura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'E ali será a oferta santa dos sacerdotes, de vinte e cinco mil canas ao norte, dez mil de largura ao ocidente, dez mil de largura ao oriente, e de vinte e cinco mil de comprimento ao sul; e o santuário do SENHOR estará no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Será para os sacerdotes santificados dos filhos de Zadoque, que guardaram minha ordem, que não se desviaram quando os filhos de Israel se desviaram, como se desviaram os outros levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Eles terão uma oferta da oferta da terra, a parte santíssima, junto ao limite dos levitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'E o Levitas terão na vizinhança do limite dos sacerdotes vinte e cinco mil canas de comprimento e de dez mil de largura; todo o comprimento será vinte e cinco mil, e a largura dez mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Não venderão disto, nem trocarão, nem transferirão as primícias da terra, pois é coisa consagrada ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'E as cinco mil canas de largura que restam das vinte e cinco mil, serão de uso comum para a cidade, para habitação e arrebaldes; e a cidade estará no meio delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'E estas serão suas medidas: o lado norte quatro mil e quinhentas canas,o lado sul quatro mil e quinhentas, o lado do oriente quatro mil e quinhentas, e o lado do ocidente quatro mil e quinhentas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'E o arrebaldes da cidade serão ao norte de duzentas e cinquenta canas,ao sul de duzentas e cinquenta, ao oriente de duzentas e cinquenta, e ao ocidente de duzentas e cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'E quanto ao que restar do comprimento, na vizinhança da oferta santa, será dez mil canas ao oriente e dez mil ao ocidente, que será vizinho à oferta santa; sua produção será alimento dos trabalhadores da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'E os trabalhadores da cidade, de todas as tribos de Israel, trabalharão nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Toda a oferta será de vinte e cinco mil canas por vinte e cinco mil, em quadrado; reservareis a oferta santa, com a propriedade da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'E o que restar será para o príncipe, de um lado e do outro da oferta santa, e da propriedade da cidade, desde a distância de vinte e cinco mil canas da oferta, até o extremo oriente, e ao ocidente desde a distância de vinte e cinco mil canas da oferta até o extremo ocidente, na vizinhança das porções das tribos,será para o príncipe; e a oferta santa, e o santuário da casa será no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'E desde a propriedade dos Levitas, e desde a propriedade da cidade, será no meio daquilo que pertencerá ao príncipe. Entre o limite de Judá e o limite de Benjamim será para o príncipe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'E quanto às demais tribos: desde o extremo oriente até o extremo ocidente: esta é a porção de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'E junto ao limite de Benjamim, desde o extremo oriente até o extremo ocidente: esta é a porção de Simeão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'E junto ao limite de Simeão, desde o extremo oriente até o extremo ocidente: esta é a porção de Issacar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'E junto ao limite de Issacar, desde o extremo oriente até o extremo ocidente: esta é a porção de Zebulom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'E junto ao limite de Zebulom, desde o extremo oriente até o extremo ocidente: esta é a porção de Gade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'E junto ao limite de Gade, ao sul, no lado sul, será o limite desde Tamar até as águas das inimizades de Cades, junto ao ribeiro, até o grande mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Esta é a terra que repartireis em herança às tribos de Israel, e estas são suas porções,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'E estas são as saídas da cidade: ao lado norte quatro mil e quinhentos côvados de medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'E as portas da cidade serão conforme os nomes das tribos de Israel; três portas ao norte: uma porta de Rúben, uma porta de Judá, e uma porta de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'E ao lado do oriente quatro mil e quinhentos côvados,e três portas: uma porta de José, uma porta de Benjamim, e uma porta de Dã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'E ao lado sul quatro mil e quinhentos côvados de medida, e três portas: uma porta de Simeão, uma porta de Issacar, e uma porta de Zebulom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'E ao lado do ocidente quatro mil e quinhentos côvados, e suas três portas: uma porta de Gade, uma porta de Aser, e uma porta de Naftali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Ao redor terá dezoito mil côvados. E o nome da cidade desde aquele dia será: O SENHOR Está Ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'No ano terceiro do reinado de Jeoaquim, rei de Judá, Nabucodonosor, rei da Babilônia, veio a Jerusalém, e a cercou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'E o Senhor entregou em suas mãos a Jeoaquim, rei de Judá, e uma parte dos vasos da casa de Deus, e os trouxe à terra de Sinar, para a casa de seu deus; e pôs os vasos na casa do tesouro de seu deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'E o rei disse a Aspenaz, chefe de seus eunucos, que trouxesse alguns dos filhos de Israel, da família real, e dos príncipes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Rapazes em quem não houvesse defeito físico algum, de boa aparência, entendidos em toda sabedoria, sábios em conhecimento, de boa inteligência, e que tivessem habilidade em prestar assistência no palácio do rei; e que os ensinassem as letras e a língua dos caldeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'E o rei lhes determinou uma porção diária de alimento, da comida do rei, e do vinho que bebia; e que assim fossem tratados por três anos, para que ao fim eles estivessem diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'E foram entre eles, dos filhos de Judá, Daniel, Ananias, Misael e Azarias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Aos quais o chefe dos eunucos pôs outros nomes: a Daniel, Beltessazar; a Ananias, Sadraque; a Misael, Mesaque; e a Azarias, Abednego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'E Daniel propôs em seu coração de não se contaminar com a porção diária de alimento da comida do rei, nem no vinho que ele bebia; então pediu ao chefe dos eunucos para não se contaminar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, '(Pois Deus concedeu a Daniel o agrado e o favor do chefe dos eunucos.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'E disse o chefe dos eunucos a Daniel: Tenho medo de meu senhor o rei, que determinou vossa comida e vossa bebida; pois, e se ele perceber que vossos rostos estão com pior aparência que os dos rapazes que são semelhantes a vós? Assim poríeis minha cabeça em risco diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Então disse Daniel a Melsar, a quem o chefe dos eunucos havia ordenado sobre Daniel, Ananias, Misael, e Azarias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Faze um teste, eu te peço, com teus servos por dez dias, e dê-nos legumes para comer, e água para beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Então se vejam diante de ti nossos rostos, e os rostos dos rapazes que comem da porção de alimento da comida do rei; e faze com teus servos conforme o que vires.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'E ele consentiu-lhes nisto, e fez teste com eles por dez dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'E ao fim dos dez dias foi visto que eles estavam com rostos de melhor aparência e mais bem nutridos que os outros rapazes que comiam da porção de alimento do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Foi assim que Melsar lhes tirou a porção de alimento deles, e o vinho que deviam beber, e continuou a lhes dar legumes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Quanto a estes quatro rapazes, Deus lhes deu conhecimento e inteligência em todas as letras e sabedoria; Daniel, porém, teve entendimento em toda visão e sonhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'E quando terminaram os dias dos quais o rei tinha dito que os trouxessem, o chefe dos eunucos os trouxe diante de Nabucodonosor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'E o rei falou com eles, e entre todos eles não foi achado alguém como Daniel, Ananias, Misael, e Azarias; e assim se tornaram assistentes diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'E em todo negócio de sabedoria e inteligência que o rei lhes demandou, achou-os dez vezes melhores que todos os magos e astrólogos que havia em todo o seu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'E Daniel esteve até o primeiro ano do rei Ciro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'E no segundo ano do reinado de Nabucodonosor, sonhou Nabucodonosor sonhos, e seu espírito se perturbou, de modo que perdeu o sono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'E o rei mandou chamar magos, astrólogos, encantadores, e sábios dos caldeus, para que explicassem ao rei seus sonhos. Eles vieram, e se apresentaram diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'E o rei lhes disse: Sonhei um sonho, e meu espírito está perturbado para saber o sonho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Então os caldeus falaram ao rei em língua aramaica: Ó rei, vive para sempre vive! Dize o sonho a teus servos, e mostraremos a interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Então o rei respondeu aos caldeus, e disse: Minha decisão é firme: se não me mostrardes o sonho e sua interpretação, sereis despedaçados, e vossas casas se tornarão em monturos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Mas se mostrardes o sonho e sua interpretação, recebereis de mim presentes, recompensas e grande honra; portanto, mostrai-me o sonho e sua interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Responderam pela segunda vez, e disseram: Diga o rei o sonho a seus servos, e mostraremos sua interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'O rei respondeu, e disse: Eu bem sei que vós quereis ganhar tempo; porque sabeis que minha decisão é firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Pois se não me mostrardes o sonho, haverá uma única sentença para vós. Pois preparastes uma resposta mentirosa e perversa para dizer diante de mim, até que o tempo se mude; portanto, dizei-me o sonho, para que eu tenha certeza de que podeis me mostrar sua interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Os caldeus responderam diante do rei, e disseram: Ninguém há sobre a terra que possa mostrar a palavra do rei; pois nenhum rei, príncipe, nem governante, jamais exigiu coisa semelhante a algum mago, astrólogo, ou caldeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Pois a coisa que o rei exige é tão difícil que não há quem a possa revelar diante do rei, a não ser os deuses, cuja morada não é entre a raça humana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Por isso o rei se irou muito e se enfureceu; então mandou matar a todos os sábios da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'E publicou-se o decreto, e os sábios foram condenados à morte; e buscaram a Daniel e a seus companheiros para serem mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Então Daniel falou de forma cautelosa e prudente a Arioque, capitão dos da guarda do rei, que tinha saído para matar os sábios de Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Ele respondeu e disse a Arioque, capitão do rei: Por que houve este mandamento do rei tão repentinamente? Então Arioque explicou o ocorrido a Daniel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'E Daniel entrou, e pediu ao rei que lhe desse tempo para que ele mostrasse a interpretação ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Então Daniel foi para sua casa, e contou o ocorrido a Ananias, Misael, e Azarias, seus companheiros,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Para que pedissem misericórdia do Deus do céu sobre este mistério, e que Daniel e seus companheiros não perecessem juntamente com os demais sábios da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Então o mistério foi revelado a Daniel em visão de noite; então Daniel louvou ao Deus do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel falou, e disse: Bendito seja o nome de Deus para todo o sempre! Porque a ele pertence a sabedoria e o poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'E ele é o que muda os tempos e as estações; ele tira os reis, e confirma os reis; ele é o que dá a sabedoria aos sábios, e a conhecimento aos entendidos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Ele revela o profundo e o escondido; conhece o que está nas trevas, e a luz mora com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'A ti, ó Deus de meus pais, te agradeço e louvo, pois tu me deste sabedoria e poder, e agora me fizeste saber o que te pedimos; porque tu nos fizeste saber o assunto do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Depois disto Daniel veio a Arioque, ao qual o rei tinha constituído para matar os sábios da Babilônia; ele veio, e disse-lhe assim: Não mates os sábios da Babilônia; leva-me diante do rei, que eu mostrarei ao rei a interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Então Arioque levou depressa a Daniel diante do rei, e disse-lhe assim: Achei um homem dos do cativos de Judá, o qual mostrará ao rei a interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Respondeu o rei, e disse a Daniel (cujo nome era Beltessazar): Podes tu me explicar o sonho que vi, e sua interpretação?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel respondeu diante do rei, e disse: O mistério que o rei demanda, nem sábios, nem astrólogos, nem magos, nem adivinhos podem explicar ao rei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Mas há um Deus nos céus, o qual revela os mistérios; ele, pois, fez saber ao rei Nabucodonosor o que haverá de acontecer no fim dos dias. Teu sonho, e as visões de tua cabeça sobre tua cama, são o seguinte:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Enquanto tu, ó rei, estava em tua cama, vieram teus pensamentos saber o irá acontecer no futuro; pois aquele que revela os mistérios te mostrou o que haverá de acontecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'E a mim foi revelado este mistério, não porque em mim há mais sabedoria que em todos os viventes, mas sim para que eu explique a interpretação ao rei, e assim entendas os pensamentos de teu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Tu, ó rei, estavas vendo, e eis uma grande estátua. Esta estátua, que era muito grande, e tinha um esplendor excelente, estava em pé diante de ti; e sua aparência era terrível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'A cabeça da estátua era de ouro puro; seus peito e seus braços, de prata; seu ventre e suas coxas, de bronze;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Suas pernas de ferro; seus pés, em parte de ferro, e em parte de barro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Estavas tu vendo, até que uma pedra foi cortada sem auxílio de mãos, a qual feriu a estátua em seus pés de ferro e de barro, e os esmigalhou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Então foi juntamente esmigalhado o ferro, o barro, o bronze, a prata e o ouro, e se tornaram como o pó das eiras de verão; e o vento os levou, e nunca se achou algum lugar para eles. Mas a pedra que feriu a estátua, se tornou um grande monte, que encheu toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Este é o sonho; a interpretação dele também diremos diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Tu, ó rei, és rei de reis; pois o Deus do céu te deu o reino, poder, força, e majestade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'E onde quer que habitam filhos de homens, animais do campo, e aves do céu, ele os entregou em tuas mãos, e fez com que tivesses domínio sobre tudo; tu és a cabeça de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'E depois de ti se levantará outro reino inferior ao; e outro terceiro reino de bronze, o qual dominará toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'E o quarto reino será forte como o ferro; e tal como o ferro esmigalha e despedaça tudo, e tal como o ferro que quebra todas estas coisas, assim também ele esmigalhará e quebrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'E o que viste dos pés e dos dedos, em parte de barro de oleiro, e em parte de ferro, isso será um o reino dividido; mas haverá nele algo da força do ferro, conforme o que viste o ferro misturado com o barro mole.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'E os dedos dos pés em parte de ferro, e em parte de barro, são que em parte o reino será forte, e em parte será frágil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Quanto ao que viste, o ferro misturado com barro mole, misturar-se-ão com semente humana, mas não se ligarão um ao outro, como o ferro não se mistura com o barro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Mas nos dias destes reis, o Deus do céu levantará um reino que nunca será destruído; e este reino não será deixado para outro povo; ao contrário, esmigalhará e consumirá todos estes reinos, e tal reino permanecerá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Por isso viste que do monte foi cortada uma pedra sem auxílio de mãos, a qual esmigalhou o ferro, o bronze, o barro, a prata, e o ouro. O grande Deus mostrou ao rei o que irá acontecer no futuro. O sonho é verdadeiro, e sua interpretação é fiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Então o rei Nabucodonosor caiu com o rosto ao chão, prostrou-se diante de Daniel, e mandou que lhe sacrificassem oferta de alimento e incensos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'O rei respondeu a Daniel, e disse: Certamente vosso Deus é o Deus dos deuses, o Senhor dos reis, e o revelador dos mistérios, pois pudeste revelar este mistério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Então o rei engrandeceu a Daniel, e lhe deu muitos e grandes presentes, e o pôs por governador de toda a província da Babilônia, e por príncipe dos governadores sobre todos os sábios de Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'E Daniel pediu do rei, e ele pôs sobre os negócios da província de Babilônia a Sadraque, Mesaque, e Abednego; porém Daniel ficou na corte do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'O rei Nabucodonosor fez uma estátua de ouro, cuja altura era de sessenta côvados, sua largura de seis côvados; ergueu-a no campo de Dura, na província da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'E o rei Nabucodonosor mandou juntar os sátrapas, os prefeitos e governadores, os juízes, tesoureiros, conselheiros, os oficiais, e a todos os líderes das províncias, para que viessem à consagração da estátua que o rei Nabucodonosor havia erguido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Então se reuniram os sátrapas, os prefeitos e governadores, os juízes, tesoureiros, conselheiros, os oficiais, e todos os líderes das províncias, para a consagração da estátua que o rei Nabucodonosor havia erguido; e estavam em pé diante da estátua que Nabucodonosor havia erguido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'E o arauto proclamava em alta voz: Manda-se a vós, ó povos, nações, e línguas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Que quando ouvirdes o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, vos prostrareis e adorareis a estátua de ouro que o rei Nabucodonosor ergueu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'E qualquer um que não se prostrar e a adorar, na mesma hora será lançado dentro de uma fornalha de fogo ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Por isso no mesmo instante em todos os povos ouviram o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, todos os povos, nações, e línguas se prostraram, e adoraram a estátua de ouro que o rei Nabucodonosor havia erguido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Por isso no mesmo instante alguns homens caldeus se chegaram, e acusaram dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Eles falaram ao rei Nabucodonosor: Ó rei, vive para sempre!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Tu, ó rei, fizeste um decreto que todo aquele que ouvisse o som da trombeta, do pífano, do da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, se prostrasse e adorasse a estátua de ouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'E qualquer um que não se prostrasse e adorasse, fosse lançado dentro de uma fornalha de fogo ardente');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Há uns homens judeus, os quais constituíste sobre os negócios da província da Babilônia; Sadraque, Mesaque, e Abednego; estes homens, ó rei, não te respeitaram; não servem a teus deuses, nem adoram a estátua de ouro que tu ergueste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Então Nabucodonosor com ira e furor, mandou trazer a Sadraque, Mesaque, e Abednego. Então trouxeram estes homens diante do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nabucodonosor lhes disse: É verdade, Sadraque, Mesaque, e Abednego, que vós não servis a meus deuses, nem adorais a estátua de ouro que ergui?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Agora pois, se estais prontos, quando ouvirdes o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, prostrai-vos e adorai a estátua que eu fiz. Porém se não a adorardes, na mesma hora sereis lançados dentro da fornalha de fogo ardente; e quem é o Deus que vos livrará de minhas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadraque, Mesaque, e Abednego responderam ao rei Nabucodonosor: Não necessitamos de responder sobre este negócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Eis que nosso Deus a quem servimos pode nos livrar da fornalha de fogo ardente; e ele nos livrará de tua mão, ó rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'E se não, sabe tu, ó rei, que não serviremos a teus deuses, nem adoraremos a estátua que ergueste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Então Nabucodonosor se encheu de furor, e o aspecto de seu rosto se mudou contra Sadraque, Mesaque, e Abednego. Então ele falou, e mandou que o forno fosse aceso sete vezes mais do que costumava se acender.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'E mandou aos homens mais fortes que havia em seu exército, que atassem a Sadraque, Mesaque, e Abednego, para lançá-los na fornalha de fogo ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Então estes homens foram atados com suas capas, suas calças, seus turbantes, e suas vestes, e foram lançados dentro da fornalha de fogo ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'E visto que a palavra do rei era urgente, e a fornalha estava muitíssimo quente, a chama do fogo matou aqueles homens que tinham levantado a Sadraque, Mesaque, e Abednego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'E estes três homens, Sadraque, Mesaque, e Abednego, caíram atados dentro da fornalha de fogo ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Então o rei Nabucodonosor se espantou, e se levantou depressa, então perguntou aos seus conselheiros: Não lançamos três homens atados dentro do fogo? Eles responderam ao rei: É verdade, ó rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Ele disse mais: Eis que vejo quatro homens soltos andando no meio do fogo, e não há neles dano algum; e a aparência do quarto é semelhante a um filho de deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Então Nabucodonosor se aproximou da porta da fornalha de fogo ardente, e falou: Sadraque, Mesaque, e Abednego, servos do Deus altíssimo, saí e vinde!Então Sadraque, Mesaque, e Abednego saíram do meio do fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'E juntaram-se os sátrapas, os prefeitos, os governadores, e os conselheiros do rei, para olharem estes homens, como o fogo não havia causado efeito algum em seus corpos, nem o cabelo de seus cabeças fora queimado, nem suas capas se mudaram, nem cheiro de fogo passara por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nabucodonosor falou: Bendito seja o Deus de Sadraque, Mesaque, e Abednego, que enviou seu anjo, e livrou seus servos, que confiaram nele; pois violaram o mandamento do rei, e entregaram seus corpos para que servissem nem adorassem algum outro deus, a não ser o seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Portanto eu faço um decreto, que todo povo, nação, e língua, que disser blasfêmia contra o Deus de Sadraque, Mesaque, e Abednego, seja despedaçado, e sua casa seja se torne um amontoado de entulhos; pois não há outro deus que possa livrar como este.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Então o rei fez com que Sadraque, Mesaque, e Abednego fossem prósperos na província da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'O rei Nabucodonosor, a todos os povos, nações, e línguas, que moram em toda a terra: paz vos seja multiplicada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Pareceu-me bem fazer conhecidos os sinais e maravilhas que o Deus altíssimo fez comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Como são grandes os seus sinais, e como são poderosas as suas maravilhas! O reino dele é um reino eterno, e seu domínio de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Eu, Nabucodonosor, estava tranquilo em minha casa, e próspero em meu palácio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Eu vi um sonho que me espantou; e as imaginações em minha cama e as visões da minha cabeça me perturbaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Por isso eu fiz um decreto para que trouxessem diante de mim todos os sábios da Babilônia, para que me fizessem saber a interpretação do sonho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Então vieram magos, astrólogos, caldeus, e adivinhos; e eu disse o sonho diante deles, mas não conseguiram me mostrar sua interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Porém por fim veio diante de mim Daniel, cujo nome é Beltessazar, segundo o nome de meu deus; e em Daniel há o espírito dos deuses santos. Então eu disse o sonho diante dele:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Beltessazar, príncipe dos magos, de quem eu sei que há em ti espírito dos deuses santos, e que nenhum mistério é difícil para ti, dize-me as visões de meu sonho que eu vi, e sua interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Estas foram as visões de minha cabeça em minha cama: eu estava vendo, e eis uma árvore grande em altura, no meio da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Esta árvore crescia, e se fortalecia; sua altura chegava até o céu, e podia ser vista até dos confins de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Sua folhagem era bela, seu fruto abundante, e havia nela alimento para todos. Debaixo dela os animais do campo achavam sombra, em seus ramos as aves do céu faziam morada, e todos os seres se alimentavam dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Eu estava vendo nas visões de minha cabeça em minha cama, e eis que um vigilante e santo descia do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Ele gritava fortemente e dizia assim: Cortai a árvore, e podai seus ramos; derrubai sua folhagem, e dispersai seu fruto; fujam os animais debaixo dela, e as aves de seus ramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Porém deixai o tronco com suas raízes na terra, e com correntes de ferro e de bronze na erva do campo; e seja molhado com o orvalho do céu, e sua parte seja com os animais na grama da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Seu coração seja mudado, para que não seja coração de homem, e seja-lhe dado um coração de animal; e passem sobre ele sete tempos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Esta sentença é por decreto dos vigilantes, esta exigência pela palavra dos santos; para que os viventes saibam que o Altíssimo tem o domínio dos reinos humanos, e ele os dá a quem ele quer, e constitui sobre eles até o mais inferior dos seres humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Este foi o sonho que eu, o rei Nabucodonosor, vi. Tu, pois, Beltessazar, dize a interpretação, porque todos os sábios do meu reino não puderam me revelar sua interpretação; mas tu podes, porque há em ti o espírito dos deuses santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Então Daniel, cujo nome era Beltessazar, ficou atônito por um certo tempo, e seus pensamentos o espantavam. O rei falou: Beltessazar, não fiques espantado com o sonho nem com sua interpretação. Beltessazar respondeu: Meu senhor, que o sonho seja para os que te odeiam, e sua interpretação para teus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'A árvore que viste, que crescera e se fizera forte, cuja altura chegava até o céu, e podia ser vista por toda a terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Cuja folhagem era formosa, seu fruto abundante, e em que havia alimento para todos; debaixo da qual moravam os animais do campo, e em seus ramos habitavam as aves do céu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Ela és tu, ó rei, que cresceste, e te fizeste forte; pois tua grandeza cresceu, e chegou até o céu; e teu domínio até o fim da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'E quanto ao que o rei viu, um vigilante e santo que descia do céu, e dizia: Cortai a árvore e destruí-a; mas o tronco com suas raízes deixai na terra, com correntes de ferro e de bronze na erva do campo; e seja molhado do orvalho do céu, e sua parte seja com os animais do campo, até que passem sobre ele sete tempos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Esta é a interpretação, ó rei; esta é a sentença do Altíssimo, que virá sobre o rei, meu senhor:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Expulsar-te-ão dentre os homens, e tua morada será com os animais do campo; serás alimentado com erva como aos bois, e serás molhado com orvalho do céu; e sete tempos passarão sobre ti, até que entendas que o Altíssimo tem o domínio sobre os reinos humanos, e ele os dá a quem ele quer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'E quanto ao que foi dito, que deixassem o tronco com das raízes da árvore, significa que teu reino se te será restabelecido, depois que tiveres entendido que o céu reina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Portanto, ó rei, aceita meu conselho, e desfaze teus pecados por meio da justiça, e tuas maldades por meio da misericórdia para com os pobres; para que talvez haja uma prolongamento de tua paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Tudo isso veio sobre o rei Nabucodonosor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Pois ao fim de doze meses, enquanto passeava sobre o palácio real da Babilônia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'O rei falou: Não é esta a grande Babilônia, que eu edifiquei para ser a capital do reino, com a força de meu poder, e para a glória de minha majestade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Enquanto a palavra ainda estava na boca do rei, uma voz caiu do céu: A ti se diz, ó rei Nabucodonosor: perdeste o teu reino,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'E te expulsarão dentre os homens. Tua morada será com os animais do campo, e com erva serás alimentado, como os bois; e sete tempos passarão sobre ti, até que entendas que o Altíssimo tem o domínio dos reinos dos homens, e ele os dá a quem ele quer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Na mesma hora a palavra se cumpriu sobre Nabucodonosor, e foi lançado dentre os homens. Ele passou a comer erva como os bois, e seu corpo foi molhado com o orvalho do céu, até que seu pelo cresceu como as penas da águia, e suas unhas como as garras das aves.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Mas ao fim daqueles dias, eu, Nabucodonosor levantei meus olhos ao céu, e meu entendimento voltou a mim; então eu bendisse ao Altíssimo, e louvei e glorifiquei ao que vive para sempre, cujo domínio é eterno, e seu reino de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'E todos os moradores da terra são contados como nada; e ele faz no exército do céu, e nos habitantes da terra segundo sua vontade; ninguém há que possa deter sua mão, e lhe dizer: Que fazes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'No mesmo tempo meu entendimento voltou a mim, e a dignidade do meu reino, minha majestade e meu resplendor voltaram a mim; e meus conselheiros e meus grandes me buscaram; e eu fui restabelecido em meu reino, e maior glória me foi acrescentada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Agora eu, Nabucodonosor louvo, exalto e glorifico ao Rei do céu, porque todas as suas obras são verdade, e seus caminhos juízo; e ele pode humilhar aos que andam com arrogância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'O rei Belsazar fez um grande banquete a mil de seus maiorais, e bebeu vinho diante destes mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Tendo Belsazar experimentado o vinho, mandou trazer os vasos de ouro e de prata que seu pai Nabucodonosor tirara do templo de Jerusalém, para que bebessem com eles o rei e seus maiorais, suas mulheres e suas concubinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Então trouxeram os vasos de ouro que foram tirados do templo da casa de Deus, que estava em Jerusalém; e beberam com eles o rei e seus maiorais, suas mulheres e suas concubinas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Beberam vinho, e louvaram aos deuses de ouro e de prata, de bronze, de ferro, de madeira, e de pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Naquela mesma hora saíram dedos de uma mão de homem, e escreveram diante do castiçal na caiadura da parede do palácio real, e o rei viu parte da mão que estava escrevendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Então o semblante do rei se mudou, e seus pensamentos o perturbaram; as juntas de seus lombos se desataram, e seus joelhos se bateram um com o outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'O rei clamou em alta voz que trouxessem astrólogos, caldeus, e adivinhos. O rei falou, e disse aos sábios da Babilônia: Qualquer um que ler esta escritura, e me mostrar sua interpretação, será vestido de púrpura, terá uma corrente de ouro a seu pescoço, e será o terceiro líder no reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Então vieram todos os sábios do rei, mas não puderam ler a escritura, nem fazer saber ao rei sua interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Então o rei Belsazar ficou muito perturbado, e se mudou seu semblante; seus maiorais estavam perturbados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'A rainha, por causa das palavras do rei e de seus maiorais, entrou na casa do banquete. A rainha disse: Ó rei, vive para sempre! Não te perturbem teus pensamentos, nem se mude teu semblante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Em teu reino há um homem no qual mora o espírito dos deuses santos; e nos dias de teu pai se achou nele luz, inteligência e sabedoria, como a sabedoria dos deuses; e teu pai, o rei Nabucodonosor (o rei, teu pai), o constituiu por príncipe sobre os magos, os astrólogos, os caldeus e os adivinhadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Pois nele foi achado um espírito extraordinário, conhecimento, e entendimento, interpretando sonhos, resolvendo enigmas, e desfazendo dúvidas. Ele é Daniel, a quem o rei pôs por nome Beltessazar. Chame-se agora a Daniel, e ele mostrará a interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Então Daniel foi trazido diante do rei. E o rei disse a Daniel: És tu aquele Daniel dos cativos de Judá, que meu pai trouxe de Judá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Pois tenho ouvido de ti que o espírito dos deuses está em ti, e que em ti se acha luz, entendimento e extraordinária sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'E agora foram trazidos diante de mim sábios e astrólogos, para que lessem esta escritura, e me fizessem saber sua interpretação; mas eles não puderam mostrar a interpretação destas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Eu, porém, tenho ouvido sobre ti que podes dar interpretações, e solucionar dúvidas. Agora, se puderes puderes ler esta escritura, e fazer-me saber sua interpretação, serás vestido de púrpura, corrente de ouro terás em teu pescoço, e serás o terceiro líder no reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Então Daniel respondeu, e disse diante do rei: Fiquem contigo tuas dádivas, e dá teus presentes a outro; contudo lerei a escritura ao rei, e lhe farei saber a interpretação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Quanto a ti, ó rei, o Deus Altíssimo deu a teu pai Nabucodonosor o reino, a grandeza, a glória, e a majestade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'E pela grandeza que ele lhe deu, todos os povos, nações, e línguas tremiam e temiam diante dele. Ele matava a quem queria, e concedia vida a quem queria; ele engrandecia a quem queria, e abatia a quem queria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mas quando seu coração se exaltou, e seu espírito se endureceu em soberba, ele foi deposto do trono de seu reino, e a glória lhe foi tirada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'E foi expulso dentre os filhos dos homens; e sua mente se tornou semelhante à dos animais, e com asnos selvagens foi sua morada. Foi alimentado com erva tal como os bois, e seu corpo foi molhado com o orvalho do céu, até que entendeu que o Deus altíssimo tem o domínio sobre os reinos humanos, e constitui sobre eles a quem ele quer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'E tu, Belsazar, filho dele, não humilhaste teu coração, mesmo sabendo de tudo isto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Em vez disso exaltaste a ti mesmo contra o Senhor do céu; pois trouxeram diante de ti os vasos de sua casa, e tu, teus maiorais, tuas mulheres e tuas concubinas, bebestes vinho neles; além disto, louvaste a deuses de prata, ouro, bronze, de ferro, madeira e pedra, que não veem, nem ouvem, nem têm conhecimento algum; porém ao Deus em cuja mão está tua vida e todos os teus caminhos, a ele não glorificaste;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Então dele foi enviada aquela parte da mão que esculpiu esta escritura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'E esta é a escritura que foi escrita: MENE, MENE, TEQUEL, PARSIM.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Esta é a interpretação daquilo: MENE: Contou Deus o teu reino, e o acabou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'TEQUEL: Pesado foste na balança, e foste achado em falta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'PERES: Dividido foi teu reino, e entregue aos a medos e aos persas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Então Belsazar deu ordens, e vestiram a Daniel de púrpura, puseram uma corrente de ouro em seu pescoço, e anunciaram que ele seria o terceiro líder no reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Naquela mesma noite Belsazar, rei dos caldeus, foi morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'E Dario, o medo, tomou o reino, sendo da idade de sessenta e dois anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Pareceu bem a Dario constituir sobre o reino cento vinte governadores que estivessem em todo o reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'E sobre eles três supervisores, dos quais Daniel era um, a quem estes governadores deviam prestar contas, para que o rei não sofresse dano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Então o mesmo Daniel era superior a estes governadores e supervisores, porque nele havia um espírito extraordinário; por isso o rei pensava em constituí-lo sobre todo o reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Então os supervisores e governadores procuravam achar alguma acusação contra Daniel a respeito do reino; mas não conseguiram achar acusação ou falta alguma, porque ele era fiel, e nenhum erro nem falta foi achada nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Então esses homens disseram: Não acharemos acusação alguma contra este Daniel, a não ser se a acharmos contra ele na lei de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Então esses supervisores e governadores foram juntos ao rei, e lhe disseram assim: Ó rei Dario, vive para sempre!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Todos os supervisores do reino, os prefeitos, governadores, conselheiros e capitães, concordaram em sugerir a promulgação de um decreto real, e estabelecer um estatuto forte, que qualquer um que, no intervalo de trinta dias, fizer alguma petição a qualquer deus ou humano, a não ser a ti, ó rei, seja lançado na cova dos leões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Agora, ó rei, confirma o decreto, e assina a escritura, para que não se mude, conforme à lei dos medos e dos persas, que não se pode revogar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Por esta causa o rei Dario assinou o decreto por escrito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'E Daniel, quando soube que a escritura estava assinada, entrou em sua casa, e com as janelas de seu quarto abertas, voltadas para Jerusalém, punha-se de joelhos três vezes ao dia, e orava, e confessava diante de seu Deus, assim como costumava fazer antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Então aqueles homens se juntaram, e encontraram Daniel orando e suplicando diante de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Então se aproximaram e falaram diante do rei acerca do decreto real: Por acaso não assinaste o decreto que todo aquele que pedir a qualquer deus ou humano no intervalo de trinta dias, a não ser a ti, ó rei, seja lançado na cova dos leões? O rei respondeu: Esta palavra é certa, conforme a lei dos medos e dos persas, que não se pode revogar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Então disseram diante do rei: Daniel, que é um dos cativos de Judá, não respeitou a ti, ó rei, nem ao decreto que assinaste; em vez disso três vezes ao dia ele faz sua oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Quando o rei ouviu isso, pesou-lhe muito, e tentou pensar em como livrar Daniel; e até o pôr do sol trabalhou para livrá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Então aqueles homens foram juntos ao rei, e disseram ao rei: Sabe, ó rei, que é a lei dos medos e dos persas, que nenhum decreto um ordenança que o rei estabeleceu pode ser mudada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Então o rei mandou trazerem a Daniel, e o lançaram na cova dos leões. E o rei falou a Daniel: O teu Deus, a quem tu serves continuamente, ele te livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'E foi trazida uma pedra, e foi posta sobre a abertura da cova, a qual o rei selou com seu anel, e com o anel de seus grandes, para que a sentença acerca de Daniel não fosse mudada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Então o rei foi a seu palácio, e passou a noite em jejum; não permitiu que lhe trouxessem instrumentos musicais diante de si, e ele perdeu o sono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Então o rei se levantou pela manhã cedo, e foi depressa à cova dos leões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'E chegando perto da cova, chamou a Daniel com voz triste; e o rei falou a Daniel: Daniel, servo do Deus vivente! O teus Deus, a quem tu continuamente serves, pôde te livrar dos leões?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Então Daniel falou ao rei: Ó rei, vive para sempre!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Meu Deus enviou seu anjo, que fechou a boca dos leões, para que não me fizessem dano; porque diante dele se achou inocência em mim; e também contra ti, ó rei, não cometi delito algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Então o rei se alegrou muito por causa dele, e mandou tirar a Daniel da cova; assim Daniel foi tirado da cova, e nenhum dano se achou nele, pois havia confiado em seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Então o rei mandou trazerem aqueles homens que tinham acusado a Daniel, e foram lançados na cova dos leões, eles, seus filhos, e suas mulheres; e nem sequer haviam chegado ao fundo da cova, quando os leões os tomaram, e quebraram todos os seus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Então o rei Dario escreveu a todos os povos, nações, e línguas, que moram em toda a terra: Paz vos seja multiplicada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'De minha parte é feito um decreto, que em todo o domínio de meu reino, todos tremam e temam a presença do Deus de Daniel; porque ele é o Deus vivente, que permanece para sempre; seu reino não se pode destruir, e seu domínio dura até o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Ele resgata e livra, e faz sinais e maravilhas no céu e na terra; ele livrou a Daniel do poder dos leões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'E este Daniel foi próspero no reino de Dario, e no reinado de Ciro, o persa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'No primeiro ano de Belsazar, rei da Babilônia, Daniel viu um sonho, e visões de sua cabeça em sua cama; logo escreveu o sonho, e anotou o resumo das coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel disse: Eu estava vendo em minha visão de noite, e eis que os quatro ventos do céu atormentavam o grande mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'E quatro grandes animais subiam do mar, diferentes um do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'O primeiro era como leão, e tinha asas de águia. Eu estava olhando, até que suas asas lhe foram arrancadas; e foi levantado da terra; e posto de pé como um ser humano, e foi lhe dado um coração humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'E eis outra segundo animal, semelhante a um urso, a qual se levantou por um lado, e tinha em sua boca três costelas entre seus dentes; e foi lhe dito assim: Levanta-te, devora muita carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Depois disto eu estava olhando, e eis outro, semelhante a um leopardo, e tinha quatro asas de ave em suas costas; este animal também tinha quatro cabeças; e foi lhe dado domínio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Depois disto eu estava olhando nas visões da noite, e eis o quarta besta, terrível e espantoso, e muito forte. Ele tinha grandes dentes de ferro; devorava e quebrava em pedaços, e as sobras pisava com seus pés: e era diferente de todos os animais que foram antes dele; e tinha dez chifres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Enquanto eu estava observando os chifres, eis que outro chifre pequeno subia entre eles, e três dos primeiros chifres foram arrancados de diante dele; e eis que neste chifre havia olhos como olhos humanos, e uma boca que falava coisas arrogantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Eu estive olhando até que foram postos tronos, e um Ancião de dias se sentou; sua veste era branca como a neve, e o cabelo de sua cabeça como lã limpa; seu trono era chamas de fogo, e suas rodas fogo ardente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Um rio de fogo manava e saía de diante dele; milhares de milhares lhe serviam, e milhões de milhões estavam de pé diante dele: o julgamento começou, e os livros foram abertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Então eu estive olhando por causa da voz das palavras arrogantes que o chifre falava; estive olhando, até que mataram o animal, e seu corpo foi destruído, e entregue para ser queimado no fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'E quanto aos outros animais, seu domínio foi tirado; porém lhes fora dada prolongação de vida até um certo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Eu estava vendo em minhas visões de noite, e eis que estava vindo nas nuvens do céu como um filho do homem; e ele chegou até o Ancião de dias, e o fizeram chegar diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'E foi lhe dado domínio, honra, e reino, de modo que todos os povos, nações e línguas lhe serviram; seu domínio é um domínio eterno, que não passará, e seu reino não será destruído.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Quanto a mim, Daniel, meu espírito foi perturbado dentro do corpo, e as visões de minha cabeça me espantaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Cheguei-me a um dos que estavam em pé, e lhe perguntei a verdade acerca de tudo isto. E ele me disse, e me fez saber a interpretação das coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Estas grandes animais, que são quatro, são quatro reis, que se levantarão da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Mas os santos do Altíssimo receberão o reino; e possuirão o reino para todo o sempre, eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Então tive desejo de saber a verdade acerca do quarto animal, que era tão diferente de todos os outros, muito terrível, que tinha dentes de ferro, e unhas de bronze, que devorava, quebrava em pedaços, e as sobras pisava com seus pés;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Assim como dos dez chifres que estavam em sua cabeça, e do outro que havia subido, de diante do qual três tinham caído; daquele chifre que tinha olhos, e boca que falava coisas arrogantes, e cuja aparência era maior que a de seus companheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Eu estava vendo que este chifre fazia guerra contra os santos, e os vencia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Até que veio o Ancião de dias, e o juízo foi dado em favor dos santos do Altíssimo; e veio o tempo que os santos possuíram o reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Ele disse assim: O quarto animal será um quarto reino na terra, o qual será diferente de todos os reinos; e devorará toda a terra, e a pisará, e a quebrará em pedaços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'E os dez chifres significam que daquele reino se levantarão dez reis; e após deles se levantará outro, o qual será diferente dos primeiros, e humilhará a três reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'E falará palavras contra o Altíssimo, e destruirá os santos do Altíssimo; e pensará em mudar os tempos e a lei; e serão entregues em sua mão por um tempo, e tempos, e metade de um tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Porém o julgamento começará, e tirarão seu domínio, para que seja destruído e aniquilado até o fim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'E o reino, o domínio, e a majestade dos reinos debaixo de todo o céu, será dado ao povo dos santos do Altíssimo; seu reino será um reino eterno, e todos os domínios lhe servirão e obedecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Até aqui foi o fim do relato. Quanto a mim, Daniel, meus pensamentos me espantavam muito, e mudou-se meu semblante em mim; mas guardei o relato em meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'No terceiro ano do reinado do rei Belsazar, apareceu uma visão a mim, Daniel, depois daquela que tinha me aparecido no princípio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'E vi em uma visão, (e aconteceu quando vi, que eu estava na fortaleza de Susã, que é na província de Elão) vi pois em uma visão, enquanto eu estava junto ao rio Ulai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'E levantei meus olhos, e vi, e eis um carneiro que estava diante do rio, o qual tinha dois chifres; e os dois chifres eram altos, porém um era mais alto que o outro; e o mais alto subiu por último.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Vi que o carneiro estava ferindo com os chifres ao ocidente, ao norte, e ao sul, e nenhum dos animais podia o deter, nem havia quem se livrasse de seu poder; e fazia conforme sua vontade, e se engrandecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'E enquanto eu estava considerando, eis que um bode vinha do ocidente sobre a face de toda a terra, e ele não tocava a terra; e aquele bode tinha um chifre muito visível entre seus olhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'E ele veio até o carneiro que tinha os dois chifres, o qual eu tinha eu visto que estava diante do rio, e correu contra ele com o ímpeto de sua força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'E o vi chegar junto ao carneiro, e irritou-se contra ele, feriu o carneiro, e quebrou seus dois chifres, pois não havia no carneiro força para detê-lo; então derrubou-o na terra, e o pisou; não houve quem livrasse ao carneiro de seu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'E o bode se engrandeceu muito; porém, quando estava em sua maior força, aquele grande chifre foi quebrado, e em seu lugar subiram outros quatro muito visíveis, na direção dos quatro ventos do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'E de um deles saiu um chifre pequeno, o qual cresceu muito ao sul, ao oriente, e à terra formosa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'E engrandeceu-se até o exército do céu; e lançou por terra a alguns do exército e das estrelas, e as pisou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Engrandeceu-se até contra o príncipe do exército, e por ele foi tirado o contínuo sacrifício, e o lugar de seu santuário foi derrubado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'E por causa da transgressão, o exército lhe foi entregue, assim como o contínuo sacrifício; e lançou a verdade em terra, e teve sucesso naquilo que fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Depois ouvi um santo que falava; e outro santo disse ao que falava: Até quando durará a visão do contínuo sacrifício, e da transgressão assoladora, de modo que o santuário e o exército são entregues para serem pisoteados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'E ele me disse: Até duas mil e trezentas tardes e manhãs; e o santuário será purificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'E aconteceu que, tendo eu, Daniel visto a visão, e buscando entendê-la, eis que alguém semelhante a um homem se pôs diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'E ouvi uma voz de homem entre as margens de Ulai, que gritou e disse: Gabriel, explica a visão a este.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Então ele veio para perto de onde eu estava; e quando ele veio, me assombrei, e caí sobre meu rosto. Porém ele me disse: Entende, filho do homem; porque esta visão será para o tempo do fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'E enquanto ele estava falando comigo, adormeci sobre meu rosto em terra; então ele me tocou, e fez ficar de pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'E disse: Eis que eu te farei saber o que irá acontecer no fim da ira; pois será no tempo certo, o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Aquele carneiro que viste com dois chifres, são os reis da Média e da Pérsia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Porém o bode peludo é o rei da Grécia; e o chifre grande que tinha entre seus olhos é o primeiro rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'E quanto a ter sido quebrado, e terem surgido quatro em seu lugar, significa que quatro reinos surgirão daquela nação, mas não com a força dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'E ao fim do império deles, quando os transgressores se acabarem, se levantará um rei de rosto feroz, e entendido em astúcias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'E sua força ganhará vigor, mas não com sua própria força; e destruirá terrivelmente, e terá sucesso naquilo que fizer; e destruirá os fortes e o povo dos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'E com sua inteligência fará prosperar o engano em seu poder; e em seu coração se engrandecerá, e com tranquilidade destruirá a muitos; e se levantará contra o Príncipe dos príncipes, porém sem mão será quebrantado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'E a visão da tarde e a manhã que foi dita é verdadeira; tu, porém guarda em segredo a visão, porque é para muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'E eu, Daniel, enfraqueci, e fiquei doente por alguns dias; depois me levantei, e tratei dos negócios do do rei; porém continuei espantado acerca da visão, e não havia quem a entendesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'No ano primeiro de Dario, filho de Assuero, da nação dos medos, o qual foi posto por rei sobre o reino dos caldeus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'No primeiro ano de seu reinado, eu, Daniel, entendi pelos livros o número de anos, dos quais o SENHOR falara ao profeta Jeremias, que havia de acabar a assolação de Jerusalém, era setenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Então dirigi meu rosto ao Senhor Deus, para o buscar com oração e rogos, em jejum, saco, e cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'E orei ao SENHOR meu Deus, e declarei, dizendo: Ó Senhor, Deus grande e temível, que guarda o pacto e a misericórdia com os que o amam e guardam seus mandamentos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Nós pecamos, cometemos maldade; agimos perversamente, e fomos rebeldes, por termos nos desviado de teus mandamentos e de teus juízos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Não demos ouvido a teus servos, os profetas, que em teu nome falaram a nossos reis, nossos príncipes, nossos pais, e a todo o povo da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'A ti, Senhor, pertence a justiça, mas a nós a vergonha de rosto, tal como hoje estamos,todo homem de Judá, os moradores de Jerusalém, e todo Israel, os de perto e os de longe, em todas as terras para onde os tens lançado por causa de sua transgressão com que transgrediram contra ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ó SENHOR, a nós pertence a vergonha de rosto, a nossos reis, nossos príncipes, e nossos pais; porque contra ti pecamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Ao SENHOR nosso Deus, pertence a misericórdia e os perdões, ainda que contra ele tenhamos nos rebelado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'E não obedecemos à voz do SENHOR nosso Deus, para andar em suas leis, as quais ele nos deu por meio de seus servos os profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'E todo Israel transgrediu tua lei, desviando-se para não ouvir tua voz; por isso a maldição, e o juramento que está escrito na lei de Moisés, servo de Deus, foram derramados sobre nós; porque contra ele pecamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'E ele confirmou sua palavra que falou sobre nós, e sobre nossos juízes que nos julgavam, trazendo sobre nós tão grande mal, que nunca havia sido feito debaixo do céu como o que foi feito em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Assim como está escrito na Lei de Moisés, todo aquele mal veio sobre nós; contudo não suplicamos à face do SENHOR nosso Deus, para nos convertermos de nossas maldades, e entender a tua verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'O SENHOR vigiou sobre o mal, e o trouxe sobre nós; porque justo é o SENHOR nosso Deus em todas suas obras que fez; pois não obedecemos a sua voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Agora pois, ó Senhor nosso Deus, que tiraste teu povo da terra do Egito com mão poderosa, e fizeste famoso o teu nome até hoje; temos pecado, agimos com maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ó Senhor, segundo todas tuas justiças, desvie agora tua ira e teu furor de sobre a tua cidade Jerusalém, teu santo monte; pois por causa de nossos pecados, e pela maldades de nossos pais, Jerusalém e teu povo foram humilhados por todos os que estão ao nosso redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Agora pois, ó Deus nosso, ouve a oração de teu servo, e suas súplicas, e faze que teu rosto resplandeça sobre teu santuário assolado, por causa do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Inclina, ó Deus meu, teus ouvidos, e ouve; abre teus olhos, e olha para nossas assolações, e para a cidade que é chamada pelo teu nome; pois não apresentamos nossas súplicas diante de ti confiando em nossas justiças, mas sim em tuas muitas misericórdias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Ouve, Senhor; ó Senhor, perdoa; presta atenção, Senhor, e faze sem demorar, por causa de ti mesmo, Deus meu; pois a tua cidade e teu povo são chamados pelo teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Enquanto eu ainda estava falando e orando, e confessando meu pecado e o pecado de meu povo Israel, e apresentando minha súplica diante do SENHOR meu Deus, pelo monte santo de meu Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Estava eu falando em oração, e aquele varão Gabriel, ao qual eu tinha visto em visão antes, veio voando apressadamente, e me tocou cerca da hora do sacrifício da tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'E me explicou, e falou comigo, dizendo: Daniel, agora saí para te fazer entender o sentido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'No princípio de tuas súplicas a palavra saiu, e eu vim para te declarar, pois tu és muito querido. Considera, pois a palavra, e entende a visão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Setenta semanas estão determinadas sobre teu povo e sobre tua santa cidade, para acabar a transgressão, para encerrar o pecado, para expiar a maldade, e para trazer a justiça eterna; para selar a visão e a profecia, e para ungir o Santo dos santos');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Sabe pois e entendas: desde a saída da palavra para restaurar e edificar a Jerusalém até o Messias, o Príncipe, haverá sete semanas, e sessenta e duas semanas; voltará a ser construída com praças e muro, porém em tempos angustiosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'E depois das sessenta e duas semanas o Messias será exterminado, e nada terá para si; e o povo do príncipe que virá destruirá à cidade e o santuário; o fim dela será com inundação, e até o fim da guerra estão determinadas assolações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'E firmará um pacto com muitos por uma semana; e na metade da semana fará cessar o sacrifício e a oferta de alimentos; depois sobre a asa das abominações será o assolador, e isto até que seja derramado o fim determinado sobre o assolador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'No terceiro ano de Ciro rei da Pérsia, foi revelada uma palavra a Daniel, cujo nome era chamado Beltessazar; e a palavra é verdadeira, e sobre uma grande guerra; e ele entendeu a palavra, e teve entendimento da visão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Naqueles dias eu, Daniel, me entristeci durante três semanas completas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Não comi alimento agradável, nem carne nem vinho entrou em minha boca, nem me untei com unguento, até que se completassem três semanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'E aos vinte e quatro dias do primeiro mês, estava eu na margem do grande rio Tigre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Então levantei meus olhos, e olhei, e eis um homem vestido de linho, e cingidos seus lombos de ouro fino de Ufaz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'E seu corpo era como berilo, seu rosto parecia um relâmpago; seus olhos eram como tochas de fogo, e seus braços e seus pés como de cor de bronze polido; e a voz de suas palavras era como a voz de uma multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'E somente eu, Daniel, vi aquela visão, e os homens que estavam comigo não a viram; porém caiu sobre eles um grande temor, de tal modo que fugiram e se esconderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Fiquei, pois, eu só, e vi esta grande visão, e não ficou em mim força alguma; antes minha boa aparência se tornou em palidez, sem reter força alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Porém ouvi a voz de suas palavras; e enquanto ouvia a voz de suas palavras, eu caí em profundo sono sobre meu rosto, com meu rosto em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'E eis que uma mão me tocou, e fez que eu me movesse sobre meus joelhos, e sobre as palmas de minhas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'E disse-me: Daniel, homem muito querido, entende as palavras que falarei contigo, e levanta-te sobre teus pés; porque agora sou enviado a ti. E enquanto ele falava comigo esta palavra, eu estava tremendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'E ele me disse: Não temas, Daniel; porque desde o primeiro dia em que deste teu coração a entender, e a te afligir na presença de teu Deus, foram ouvidas tuas palavras; e foi por causa de tuas palavras que eu vim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Mas o príncipe do reino da Pérsia se pôs contra mim por vinte e um dias; e eis que Miguel, um dos principais chefes, veio para me ajudar, e eu fiquei ali com os reis da Pérsia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Agora vim para te fazer entender o que irá acontecer a teu povo nos últimos dias; porque a visão ainda é para muitos dias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'E tendo ele falado comigo estas palavras, abaixei meu rosto em terra, e emudeci.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'E eis que alguém semelhante aos filhos dos homens tocou meus lábios. Então abri minha boca, e falei, e disse ao que estava diante de mim: Meu senhor, por causa da visão minhas dores se tornam sobre mim, sem que eu retenha força alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Como pode, pois, o servo de meu senhor falar com este meu senhor? Pois desde agora não resta força em mim, e não me ficou fôlego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'E aquele que parecia com um homem me tocou outra vez, e me confortou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'E disse: Não temas, homem querido, paz seja contigo; sê forte! Sê forte! E tendo ele falado comigo, fortaleci-me, e disse: Fale meu senhor, pois tu me fortaleceste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'E ele disse: Sabes por que vim ti? Pois agora voltarei para lutar contra o príncipe da Pérsia; e quando eu sair, eis que virá o príncipe da Grécia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Porém eu te declararei o que está escrito na escritura de verdade; e ninguém há que se esforce comigo contra eles, a não ser Miguel, vosso príncipe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'E eu, no primeiro ano de Dario o medo, estive para confortá-lo e fortalecê-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'E agora eu te declararei a verdade. Eis que ainda haverá três reis na Pérsia, e o quarto acumulará mais riquezas que todos; e fortificando-se com suas riquezas, despertará a todos contra o reino da Grécia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Depois se levantará um rei poderoso, que reinará com grande domínio, e fará conforme sua vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Mas quando ele estiver erguido, seu reino será quebrantado, e repartido nos quatro ventos do céu; porém não a seus descendentes, nem conforme seu domínio com que ele reinou; porque seu reino será arrancado, e será para outros fora destes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'E o rei do sul se fortalecerá; mas um de seus príncipes se fortalecerá mais que ele, e reinará; e seus domínio será um grande domínio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Mas ao fim de alguns anos eles se aliarão, e a filha do rei do sul virá ao rei do norte para fazer os acordos. Porém ela não poderá reter a força de seu poder; por isso nem ele, nem seu poder persistirá; porque ela será entregue, e os que a tiverem trazido, e seu pai, e ao que a fortalecia naqueles tempos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Mas do renovo de suas raízes um se levantará em seu lugar; e virá com exército, e entrará na fortaleza do rei do norte, e agirá contra eles, e prevalecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'E até seus deuses com seus príncipes, com seus vasos preciosos de prata e de ouro, levará cativos ao Egito; e por alguns anos ele deixará de atacar o rei do norte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'O qual virá ao reino o rei do sul, e voltará para sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Porém os filhos dele se agitarão para a guerra,e ajuntarão uma multidão de grandes exércitos; e certamente avançará, inundará, e passará; e quando voltar, se agitará em guerra até sua fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Então o rei do sul se enfurecerá, e sairá, e lutará contra ele, o rei do norte; e mobiliza uma grande multidão, porém toda aquela multidão será entregue em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Quando for perdida aquele multidão, seu coração se exaltará; e ainda que derrube muitos milhares; contudo não prevalecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'E o rei do norte voltará, e porá em campo uma multidão maior que a primeira, e a fim do tempo de alguns anos avançará com grande exército e com muitos suprimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'E naqueles tempos muitos se levantarão contra o rei do sul; e filhos dos violentos de teu povo se levantarão para confirmar a visão, e cairão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Então o rei do norte virá, e levantará cerco, e tomará a cidade forte; e os poderes do sul não poderão subsistir, nem os melhores de seu povo, nem haverá força que possa subsistir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'E o que virá contra ele fará sua própria vontade, e não haverá quem possa subsistir diante dele; ele estará na terra gloriosa, e o poder de destruir estará em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Ele decidirá vir com o poder de todo seu reino; e os corretos com ele, e assim fará; e lhe dará uma filha de mulheres para destruir o reino; mas ela não terá sucesso, nem será para proveito dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Depois virará seu rosto para as terras costeiras, e tomará muitas; mas um príncipe fará cessar sua humilhação por ele, e ainda fará tornar sobre ele sua humilhação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Então virará seu rosto para as fortalezas de sua terra; mas tropeçará e cairá, e não será mais achado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'E em seu lugar se levantará um que fará passar um cobrador de impostos para glória real; mas em poucos dias será quebrantado, não por causa de ira nem de batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Depois se levantará em seu lugar um ser desprezível, ao qual não darão a honra real; mas virá durante a quietude, e tomará o reino por meio de enganos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'E exércitos em grande volume serão repelidos diante dele, e serão quebrantados; assim como também o príncipe do pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'E depois de fizerem acordos com ele, ele usará engano, e subirá; será fortalecido mesmo com pouca gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Quando houver tranquilidade nas mais prósperas regiões da província, ele virá e fará o que nunca fizeram seus pais, nem os pais de seus pais; ele repartirá presa, despojos, e riquezas entre os seus; e voltará seus pensamentos contra as fortalezas; porém somente por um tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'E despertará sua forças e sua coragem contra o rei do sul, com grande exército; e o rei do sul se agitará para a guerra com grande e muito poderoso exército; mas não prevalecerá, porque tramarão planos contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Até os que comerem de sua comida o destruirão; e seu exército será repelido, e muitos cairão mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'E o coração destes dois reis será para fazer mal, e em uma mesma mesa falarão mentiras; mas isto não terá sucesso, pois ainda haverá o fim no tempo determinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'E voltará para sua terra com grande riqueza, e seu coração será contra o pacto santo; e ele fará o que decidir, e voltará a sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'A certo tempo voltará a vir ao sul; mas a última vinda não será como a primeira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Porque navios de Quitim virão contra ele, de modo que ele se entristecerá, voltará, e se indignará contra o pacto santo, e ele fará o que decidir; pois quando voltar, ele dará atenção aos que tiverem abandonado o pacto santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'E tropas virão da parte dele, e profanarão o santuário e a fortaleza; tirarão o contínuo sacrifício, e porão uma abominação assoladora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'E com lisonjas ele perverterá aos violadores do pacto; mas o povo que conhece a seu Deus com força resistirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'E os entendidos do povo ensinarão a muitos; porém cairão à espada e a fogo, por meio de cativeiro e de despojo, por muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'E quando eles caírem, serão ajudados por um pequeno socorro; contudo muitos se aliarão a eles através de enganos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'E alguns dos sábios cairão para serem refinados, purificados e limpos, até o tempo do fim; porque isto ainda será para o tempo determinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'E o rei fará a sua vontade; e se exaltará, e se engrandecerá sobre todo deus; ele falará coisas arrogantes contra o Deus dos deuses, e será próspero, até que a ira se complete; pois o que está determinado será feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Ele não respeitará os deuses de seus pais, nem para o preferido das mulheres; nem respeitará deus algum, pois se engrandecerá sobre todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Mas em seu lugar honrará ao deus das fortalezas, um deus que seus pais nem sequer conheceram; ele o horará com ouro, prata, pedras preciosas, e com coisas de grande valor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'E ele atacará fortes fortalezas com o deus estrangeiro; aos que o reconhecerem, ele aumentará a honra; e ele os fará terem domínio sobre muitos, e repartirá a terra por preço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'E no tempo do fim o rei do sul lutará contra ele; e o rei do norte levantará como tempestade contra ele, com carruagens, cavaleiros, e muitos navios; e entrará pelas terras, arruinará como se fosse inundação, e passará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'E virá à terra gloriosa, e muitos povos cairão; mas estes escaparão de sua mão: Edom, Moabe, e os líderes dos filhos de Amom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'E estenderá sua mão a outras terras, e a terra do Egito não escapará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'E se apoderará dos tesouros de ouro e prata, e de todas as coisas valiosas do Egito, os líbios e os cuxitas o seguirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Porém notícias do oriente e do norte o espantarão; e ele sairá com grande furor para destruir e matar muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'E armará a tendas de seu palácio entre os mares, no glorioso monte santo; mas ele virá a seu fim, e não haverá quem o ajude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'E naquele tempo se levantará Miguel, o grande príncipe que está a favor dos filhos de teu povo; e será tempo de angústia tal que nunca houve desde que as nações surgiram até aquele tempo; mas naquele tempo o teu povo será livrado, todo aquele os que se achar escrito no livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'E muitos dos que dormem no pó da terra ressuscitarão, uns para a vida eterna, e outros para a vergonha e o desprezo eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'E os sábios brilharão como o resplendor do céu; e os que conduzem muitos à justiça brilharão como as estrelas, para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Porém tu, Daniel, guarda em segredo estas palavras e sela o livro até o tempo do fim; muitos correrão de um lado para o outro, e o conhecimento se multiplicará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Então eu, Daniel, olhei, e eis outros dois que estavam de pé, um à margem do rio, e o outro à outra margem do rio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'E ele disse ao homem vestido de linho, que estava sobre as águas do rio: Quando será o fim destas maravilhas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'E ouvi o homem vestido de linho, que estava sobre as águas do rio, e levantou sua mão direita e sua esquerda ao céu, e jurou por aquele que vive eternamente; que será depois de um tempo, tempos, e a metade de um tempo. Quando acabarem de despedaçar o poder do povo santo, todas estas coisas serão cumpridas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'E eu ouvi, mas não entendi. Por isso eu disse: Meu senhor, o que será o cumprimento destas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'E ele disse: Caminha, Daniel, pois estas palavras estão guardadas em segredo e seladas até o tempo do fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Muitos serão purificados, limpos, e refinados; porém os maus agirão malignamente, e nenhum dos maus entenderá, porém os sábios entenderão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'E desde o tempo em que o contínuo sacrifício for tirado, e posta a abominação assoladora, haverá mil duzentos e noventa dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Bem-aventurado o que esperar, e chegar até mil trezentos e trinta e cinco dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Tu, porém, caminha até o fim; porque repousarás, e ressuscitarás em tua herança no fim dos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'A palavra do SENHOR que veio a Oseias, filho de Beeri, nos dias de Uzias, Jotão, Acaz, e Ezequias, reis de Judá, e nos dias de Joeroboão, filho de Joás, rei de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'O princípio da palavra do SENHOR por Oseias.Disse, pois, o SENHOR a Oseias: Vai, toma para ti uma mulher de prostituição, e filhos de prostituições; porque a terra se prostitui munto, afastando-se do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Então ele foi, e tomou a Gômer, filha de Diblaim, a qual concebeu, e lhe deu à luz um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'E o SENHOR lhe disse: Chama o nome dele de Jezreel; porque daqui a pouco farei punição pelo sangue de Jezreel sobre a casa de Jeú, e farei cessar o reino da casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'E será que naquele dia quebrarei o arco de Israel no vale de Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'E ela voltou a conceber, e deu à luz uma filha. Então o SENHOR lhe disse: Chama o nome dela de Não-Amada, porque não mais amarei a casa de Israel para os perdoar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Mas a casa de Judá amarei, e os salvarei pelo SENHOR seu Deus; e não os salvarei por arco, nem por espada, nem por batalha, nem por cavalos, nem por cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'E depois de haver desmamado a Não-Amada, ela concebeu e deu à luz um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'E o SENHOR disse: Chama o nome dele de Não-Meu-Povo; porque vós não sois meu povo, por isso eu não serei vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Todavia o número dos filhos de Israel será como a areia do mar, que não se pode medir nem contar. E acontecerá que, onde foi lhes dito: Vós não sois meu povo, será lhes dito: Vós sois filhos do Deus vivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'E os filhos de Judá e de Israel serão reunidos em um, e levantarão para si uma única cabeça, e subirão da terra; pois o dia de Jezreel será grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Dizei a vossos irmãos: Meu Povo, e vossas irmãs: Amada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Repreendei vossa mãe, repreendei; porque ela não é minha mulher, nem eu seu marido; que tire suas prostituições diante de si, e seus adultérios dentre seus peitos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Para não acontecer que eu a deixe nua, e a ponha como no dia em que nasceu, e a faça como um deserto, e a deixe como terra seca, e a mate de sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'E não terei compaixão de seus filhos, porque são filhos de prostituições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Pois sua mãe se prostituiu; a que os concebeu age de forma vergonhosa; porque disse: Irei atrás meus amantes, que dão meu pão e minha água, minha lã e meu linho, meu azeite e minha bebida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Portanto eis que cercarei teu caminho com espinhos, e levantarei uma parede de sebe, de modo que ela não poderá achar suas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'E ela correrá atrás de seus amantes, mas não os alcançará; ela os buscará, mas não os achará. Então dirá: Irei, e me voltarei ao meu primeiro marido; porque era melhor para mim então do que agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'E ela não reconhecia que era eu que lhe dava o trigo, o vinho, e o azeite, e lhe multiplicava a prata e o ouro que usavam para Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Portanto tomarei de volta meu trigo a seu tempo, e meu vinho à sua estação, e tirarei minha lã e meu linho que servia para cobrir sua nudez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'E agora deixarei exposta sua loucura diante dos olhos de seus amantes, e ninguém a livrará de minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'E farei cessar toda a sua alegria, suas festas, suas novas luas e seus sábados, e todas as suas festividades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'E destruirei suas vides e suas figueiras, das quais diz: Estas são meu salário, que meus amantes me deram. E as reduzirei a uma matagal, e os animais do campo as comerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'E eu a punirei pelos dias em que ela queimava incensos a Baal, e se adornava de seus pendentes e de suas joias, e seguia seus amantes, tendo se esquecido de mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Porém eis que eu a atrairei, e a levarei ao deserto, e falarei a seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'E desde ali lhe darei suas vinhas, e o vale de Acor por porta de esperança; e ali ela cantará como nos tempos de sua juventude, como no dia em que subiu da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'E será naquele dia, diz o SENHOR, me chamarás de meu marido, e não mais me chamarás de meu Baal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Porque tirarei de sua boca os nomes dos baalins, e nunca mais serão lembrados por seus nomes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'E naquele dia farei por eles uma aliança com os animais do campo, as aves do céu, e os répteis da terra; e quebrarei o arco, a espada, e a batalha da terra, e os farei deitar em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'E te farei minha esposa para sempre; eu te farei minha esposa em justiça, juízo, bondade e misericórdias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'E te farei minha esposa em fidelidade, e tu conhecerás ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'E será que naquele tempo responderei,diz o SENHOR, eu responderei ao céu, e ele responderá à terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'E a terra responderá ao trigo, ao vinho, e ao azeite; e eles responderão a Jezreel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'E eu a semearei para mim na terra; amarei a Não-Amada; e direi a Não-Meu-Povo: Tu és meu povo; e ele dirá: Tu és meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'E disse-me o SENHOR: Vai, ama a mulher amada por seu companheiro, apesar de ser adúltera, assim como SENHOR ama os filhos de Israel, que dão atenção a outros deuses, e amam os bolos de uvas dedicados aos ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Então eu a comprei para mim por quinze peças de prata, e um ômer e meio de cevada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'E disse a ela: Tu viverás comigo por muitos dias; não te prostituirás, nem serás de outro homem; nem e eu esperarei por ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Porque os filhos de Israel viverão muitos dias sem rei e sem príncipe; sem sacrifício e sem estátua; sem éfode e sem ídolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Depois os filhos de Israel voltarão e buscarão ao SENHOR seu Deus, e a Davi seu rei; e temendo virão ao SENHOR e à sua bondade no fim dos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Ouvi a palavra do SENHOR, ó filhos de Israel; porque o SENHOR briga com os moradores da terra; porque não há fidelidade, nem misericórdia, nem conhecimento de Deus na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Perjúrio, mentira, matança, roubo e adultério prevalecem; derramamentos de sangue se acumulam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Por isso a terra lamentará, e qualquer um que morar nela desfalecerá, com os animais do campo e as aves do céu; e até os peixes do mar morrerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Porém ninguém brigue nem repreenda a alguém, porque teu povo é como os que brigam com o sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Por isso cairás de dia, e o profeta cairá contigo de noite; e destruirei tua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Meu povo é destruído por falta de conhecimento. Porque tu rejeitaste o conhecimento, eu também te rejeitei do meu sacerdócio; e visto que te esqueceste a lei de teu Deus, também eu me esquecerei de teus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Quanto mais eles se multiplicaram, mais pecaram contra mim; tornarei sua honra em vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Os sacerdotes comem do pecado de meu povo, e desejam a maldade das pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Portanto tal como o povo, assim será com o sacerdote; e punirei contra ele seus caminhos, e lhe retribuirei conforme seus atos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'E comerão, mas não se fartarão; eles se prostituirão, mas não se multiplicarão, porque abandonaram ao SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Para buscarem a prostituição, o vinho, e o mosto, que tiram o entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Meu povo consulta a seu pedaço de madeira, e seu bastão lhes dá resposta, porque o espírito de prostituições o engana, para se prostituírem contra o Deus deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Sobre os topos dos montes sacrificam, e queimam incenso sobre os morros, debaixo de carvalhos, álamos, e olmeiros que tenham boa sombra; por isso vossas filhas se prostituem, e vossas noras cometem adultério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Eu não punirei vossas filhas que se prostituem, nem vossas noras que cometem adultério; porque os próprios homens se juntam com as mulheres promíscuas, e fazem sacrifícios com as prostitutas de ritos idólatras; de fato, o povo sem entendimento se arruína.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Se tu, Israel, queres te prostituir, ao menos não faças Judá culpado. Não venhais a Gilgal, nem subais a Bete-Áven; nem jureis: Vive o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Porque Israel se rebelou como bezerra teimosa; agora o SENHOR os apascentará como a um cordeiro num campo extenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim se associou a ídolos; deixa-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Quando sua bebida se acaba, eles se voltam à prostituição; seus líderes amam a vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Um vento os atou em suas asas, e se envergonharão por causa de seus sacrifícios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Ouvi isto, ó sacerdotes, prestai atenção, ó casa de Israel; escutai, ó casa do rei; porque contra vós é este julgamento; pois tendes sido um laço em Mispá, e uma rede estendida sobre Tabor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Os rebeldes têm se aprofundado na matança, mas eu repreenderei a todos eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Eu conheço a Efraim, e Israel não está oculto para mim; pois agora, ó Efraim, te prostituis, e Israel está contaminado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Seus atos não lhe permitem se converterem a seu Deus, porque o espírito de prostituições está no meio deles, e não conhecem ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'E a soberba de Israel dará testemunho contra ele. Israel e Efraim cairão em sua maldade, e Judá cairá juntamente com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Com suas ovelhas e com suas vacas irão buscar o SENHOR, mas não o encontrarão; ele se retirou deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Agiram traiçoeiramente contra o SENHOR, porque geraram filhos estrangeiros; agora a lua nova os consumirá com suas propriedades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Tocai a corneta em Gibeá, a trombeta em Ramá; gritai em Bete-Áven; atrás de ti, ó Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim será desolado no dia do castigo; nas tribos de Israel eu fiz saber o que certamente acontecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Os príncipes de Judá são como os mudam os limites; derramarei como água meu furor sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraim é oprimido, e quebrantado no julgamento, porque quis seguir regras inúteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Por isso eu serei como traça a Efraim, e como podridão à casa de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Quando Efraim viu sua enfermidade, e Judá a sua ferida, então Efraim subiu à Assíria, e procurou o grande rei; porém ele não poderá vos sarar, nem curar vossa ferida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Porque eu serei como leão a Efraim, e como leão jovem à casa de Judá; eu mesmo a despedaçarei, e irei embora; eu a levarei, e não haverá quem a livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Irei, e voltarei a meu lugar, até que se reconheçam culpados, e busquem minha face. Em sua angústia, eles me buscarão ansiosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Vinde, e voltemo-nos ao SENHOR; porque ele despedaçou, mas nos curará; ele feriu, mas nos porá curativo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Depois de dois dias ele nos dará vida; ao terceiro dia nos ressuscitará, e diante dele viveremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Conheçamos, e prossigamos em conhecer ao SENHOR; sua vinda está preparada como o nascer do sol; ele virá a nós como a chuva, como a chuva da primavera, que rega a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Que farei a ti, ó Efraim? Que farei a ti, ó Judá? Vossa bondade é como a neblina da manhã, como o orvalho da madrugada, que logo desaparece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Por isso eu os cortei com os profetas; pelas palavras de minha boca os matei; e teus juízos sairão como a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Pois eu quero misericórdia, e não sacrifício; e conhecimento de Deus mais que ofertas de queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Porém eles, assim como Adão, transgrediram o pacto; ali agiram traiçoeiramente contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gileade é a cidade dos que praticam a injustiça; manchada está de sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Tal como um bando de assaltantes à espera de um homem, assim é o grupo de sacerdotes; matam no caminho para Siquém; eles praticam abominações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Na casa de Israel tenho visto coisa detestável; ali Efraim se prostitui, Israel se contamina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Também para ti, ó Judá, há uma ceifa, quando eu restaurar o meu povo de seu infortúnio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Ainda que eu esteja disposto a curar Israel, expostas estão a perversidade de Efraim e as maldades de Samaria, porque praticam a falsidade; o ladrão vem, e o bando de assaltantes despoja do lado de fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'E nem percebem em seus corações eu me lembro de toda a maldade deles; agora seus atos os cercam; diante de mim estão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Com sua maldade alegram ao rei, e com suas mentiras aos príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Todos eles cometem adultério; semelhantes são ao forno aceso pelo padeiro, que deixa de atiçar depois da massa estar feita, até que esteja levedada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'No dia do nosso rei, os príncipes ficam doentes pelo calor do vinho; ele estende sua mão com os zombadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Porque preparam seus corações para suas ciladas como a um forno; toda a noite seu padeiro dorme, pela manhã arde como fogo flamejante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Todos eles se aquecem como um forno, e devoraram os seus juízes; todos os seus reis caem; ninguém há entre eles que clame a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim se mistura com os povos; Efraim é um bolo que não foi virado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Estrangeiros devoram sua riqueza, sem que ele perceba; e até o cabelo grisalho se espalha por ele, e ele não percebeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'A soberba de Israel dá testemunho contra ele, porém não se convertem ao SENHOR seu Deus, nem o buscam, apesar de tudo isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'E foi Efraim como pomba imprudente, sem inteligência; chamam ao Egito, vão à Assíria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Quando forem, estenderei minha rede sobre eles; eu os farei cair como as aves do céu. Eu os castigarei conforme o que se tem ouvido quando eles se reúnem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Ai deles, porque se afastaram de mim; destruição sobre eles, porque se rebelaram contra mim; eu os livraria, porém falam mentiras contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'E não clamam a mim com seus corações quando gemem sobre suas camas; eles se reúnem para o trigo e o vinho, porém de mim se afastam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Eu os treinei, e fortalecei seus braços, porém pensam o mal contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Eles se voltam, mas não para o Altíssimo. Eles são como um arco defeituoso; seus príncipes caem à espada por causa da insolência de suas línguas; por isso serão escarnecidos na terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Põe a trombeta em tua boca. O inimigo vem como uma águia contra a casa do SENHOR, porque violaram meu pacto, e transgrediram minha lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Então clamarão a mim: Deus meu, nós, Israel, te conhecemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israel rejeitou o bem; o inimigo o perseguirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Eles fizeram reis, mas não de mim; constituíram príncipes, porém sem que eu soubesse; de sua prata e de seu ouro fizeram ídolos para si, para que sejam exterminados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'O teu bezerro foi rejeitado, ó Samaria; minha ira está acesa contra eles; até quando não suportarão a pureza?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Porque isso procede de Israel, um artífice o fez; isso não é Deus; por isso o bezerro de Samaria será desfeito em pedaços.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Porque semearam vento, colherão tempestade; não haverá colheita, nem a produção dará farinha; mesmo se a der, estrangeiros a tragarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israel é tragado; agora são como um vaso que ninguém dá valor entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Porque subiram à Assíria como um asno selvagem solitário; Efraim pagou em troca de amantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Ainda que paguem às nações, agora eu os reunirei; e começarão a ser diminuídos pela carga imposta pelo rei dos príncipes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Porque Efraim multiplicou os altares para pecar, os altares feitos para cometer pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Eu lhe escrevi as grandezas de minha lei, porém foram consideradas coisa estranha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Quanto aos sacrifícios de ofertas a mim, eles sacrificam a carne, e a comem; porém o SENHOR não os aceita. Agora ele se lembrará de sua perversidade, e punirá seus pecados; eles voltarão ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Porque Israel se esqueceu de seu Criador, e edificou templos; Judá multiplicou cidades fortificadas; porém eu mandarei fogo em suas cidades, que consumirá seus palácios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Não te alegres tanto, ó Israel, como os outros povos, pois tu te prostituis, afastando-te de teu Deus; tu amas o salário de prostituta em todas as eiras de trigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'A eira e o lagar não os manterão; e o suco de uva lhes faltará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Não permanecerão na terra do SENHOR; em vez disso, Efraim voltará ao Egito, e na Assíria comerão coisa imunda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Não derramarão ofertas de bebida ao SENHOR, nem seus sacrifícios lhe serão agradáveis; seu pão será para eles como pão de lamento; todos os que comerem dele, serão imundos; porque o pão deles será para saciar sua própria fome, e não virá para a casa do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Que fareis no dia solene, no dia festa do SENHOR?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Porque eis que eles vão embora por causa da destruição; o Egito os recolherá, Mênfis os sepultará; urtigas herdarão sua prata, espinhos crescerão em suas tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Chegaram os dias da punição, chegaram os dias da retribuição; os israelitas saberão; o profeta é considerado louco, o homem espiritual é visto como tolo, por causa da grandeza de tua maldade e do grande ódio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'O profeta é um guarda de Efraim para meu Deus; mas para ele há laços de caçador em todos os seus caminhos, e ódio na casa de seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Corromperam-se profundamente, como nos dias de Gibeá: Deus se lembrará de suas perversidades, seus pecados punirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Eu achei a Israel como uvas no deserto; eu vi a vossos pais como a primeira fruta da figueira em seu princípio. Porém eles foram a Baal-Peor, dedicaram-se a esta vergonha, e se tornaram tão abomináveis quanto aquilo que amaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'A glória de Efraim voará como ave; não haverá nascimento, nem gravidez, nem concepção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Ainda que venham a criar seus filhos, contudo eu os privarei deles, de modo que reste nenhum. Ai deles quando deles eu me afastar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Vi que Efraim era como Tiro, plantada num lugar agradável; mas Efraim trará seus filhos ao matador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Dá-lhes, SENHOR, o que lhes darás? Dá-lhes ventre que aborte, e seios sem leite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Por causa de toda a sua malícia em Gilgal, ali eu os odiei; por causa da malícia de suas obras eu os expulsarei de minha casa; eu não mais os amarei; todos os seus príncipes são rebeldes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim foi ferido, sua raiz se secou, não darão fruto; e que ainda que gerem, eu matarei os desejáveis frutos de seu ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Meu Deus os rejeitará porque não o ouviram; e andarão sem rumo entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel é uma vinha frondosa, que dá fruto para si; quanto mais se multiplicavam seus frutos, mais multiplicou altares, quanto mais sua terra prosperava, mais enfeitaram suas colunas dedicadas à idolatria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'O coração deles está dividido, agora serão culpados; ele quebrará seus altares, destruirá seus monumentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Pois dirão agora: Não temos rei porque não tivemos temor ao SENHOR; porém o que um rei poderia fazer por nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Falaram palavras jurando falsamente ao fazerem pactos; por isso que a disputa judicial brota como erva venenosa nos sulcos dos campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Os moradores de Samaria estarão atemorizados por causa do bezerro Bete-Áven; pois seu povo por causa dele lamentará, e seus sacerdotes, que nele se alegravam, lamentarão por sua glória, que se foi dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Além disso, ele será levado à Assíria como presente ao grande rei; Efraim receberá vergonha, Israel será envergonhado por causa de seu conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'O rei de Samaria será eliminado como um graveto sobre a superfície das águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'E os altos cultuais de Áven, o pecado de Israel, serão destruídos; espinhos e cardos crescerão sobre seus altares. E dirão aos montes: Cobri-nos; e aos morros: Caí sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Desde os dias de Gibeá tu tens cometido pecado, ó Israel; ali continuaram; por acaso a guerra em Gibeá não alcançou os filhos da perversidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Quando eu quiser, eu os castigarei; e povos se reunirão contra eles, para que sejam presos por causa de sua dupla transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efraim é uma bezerra domada, que amava trilhar; mas eu porei um jugo sobre seu belo pescoço; farei com que Efraim seja montado; Judá lavrará, Jacó fará sulcos na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Semeai para vós justiça, colhei para vós bondade; lavrai para vós lavoura; porque é o tempo de buscar ao SENHOR, até que ele venha, e faça chover justiça sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Lavrastes maldade, colhestes perversidade; comestes o fruto de mentira; porque confiaste em teu caminho, na multidão de teus guerreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Portanto entre teu povo se levantará tumulto, e todas as tuas fortalezas serão destruídas, assim como Salmã destruiu a Bete-Arbel no dia da batalha; ali a mãe foram despedaçada com seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Assim Betel fará convosco, por causa de vossa grande malícia; ao amanhecer o rei de Israel será exterminado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Quando Israel era menino, eu o amei, e do Egito chamei a meu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Quanto mais os chamavam, mais eles se afastavam de sua presença; sacrificavam aos Baalins, e ofereciam incenso às imagens de escultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Eu, todavia, ensinei Efraim a andar, tomando-os pelos seus braços; porém não reconheceram que eu os curava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Com cordas humanas eu os puxei, com cordas de amor; e fui para eles como os que levantam o jugo de sobre suas cabeças, e lhes dei alimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Israel não voltará à terra do Egito, mas o assírio será seu rei, porque recusam se converter.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'E a espada moverá sobre suas cidades; destruirá os ferrolhos de seus portões, e acabará com seus planos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Porém meu povo insiste em se desviar de mim; ainda que chamem ao Altíssimo, ninguém de fato o exalta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Como posso te abandonar, ó Efraim? Como posso te entregar, ó Israel? Como posso fazer de ti como Admá, ou te tornar como a Zeboim? Meu coração se comove dentro de mim, todas as minhas compaixões estão acesas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Não executarei o furor de minha ira, não voltarei a destruir Efraim; porque eu sou Deus, e não homem, o Santo no meio de ti; e não entrarei na cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Ao SENHOR seguirão; ele rugirá como leão; quando ele rugir os filhos virão tremendo desde o ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Tremendo virão do Egito como um pássaro, e da terra da Assíria como uma pomba; e eu os farei habitar em suas casas, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Efraim me cercou com mentira, e a casa de Israel com engano; mas Judá ainda andava com Deus, e era é fiel ao Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim se alimenta de vento, e persegue o vento oriental o dia todo; multiplica a mentira e a destruição; e fazem aliança com a Assíria, e azeite se leva ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'O SENHOR também tem uma briga judicial com Judá, e punirá Jacó conforme seus caminhos; ele lhe retribuirá conforme seus atos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'No ventre da mãe pegou pelo calcanhar de seu irmão, e em sua força lutou com Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Lutou com o anjo, e prevaleceu; chorou, e lhe suplicou; em Betel o achou, e ali falou conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'O próprio SENHOR, Deus dos exércitos; o SENHOR é seu memorial.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Tu pois, converte-te a teu Deus; guarda tu a misericórdia e a justiça, e espera em teu Deus continuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'O mercador tem balança enganosa em sua mão, pois ama oprimir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'E Efraim diz: Certamente eu sou rico; tenho obtido para mim muitos bens; em todo o meu trabalho ninguém pode achar em mim perversidade que seja pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Porém eu sou o SENHOR teu Deus, desde a terra do Egito; eu ainda te farei morar em tendas, como nos dias solenes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'E falei aos profetas, e eu multipliquei a visão profética; e por meio dos profetas propus parábolas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Visto que Gileade é injusta, certamente seus moradores são inúteis. Em Gilgal sacrificam bois, e até seus altares são como amontoados de pedras nos sulcos dos campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Mas Jacó fugiu à terra de Arã, e Israel serviu em troca de uma mulher, e por uma mulher apascentou ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Mas o SENHOR por um profeta fez subir a Israel do Egito, e por um profeta foi preservado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Porém Efraim o ofendeu amargamente; por isso deixará a culpa de seus sangues sobre ele, e seu Senhor lhe retribuirá sua desonra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Quando Efraim falava, havia tremor; ele era exaltado em Israel; mas se tornou culpado por causa de Baal, e morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Agora pecam cada vez mais, e de sua prata fizeram para si uma imagem de fundição, ídolos segundo seu entendimento, todos eles obra de artesãos; acerca dos quais dizem: As pessoas que sacrificam beijam bezerros!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Por isso serão como a névoa da manhã, como o orvalho da madrugada que passa; como a palha que o vento leva da eira, e como a fumaça que sai da chaminé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Porém eu sou o SENHOR teu Deus, desde a terra do Egito; portanto não conhecerás a Deus algum a não ser a mim, porque não há Salvador além de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Eu te conheci no deserto, na terra seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Depois se fartaram em seus pastos; quando ficaram fartos, seus corações se exaltaram; por isso se esqueceram de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Por isso eu serei para eles como leão; como leopardo os espiarei no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Como ursa de quem tomaram os filhotes os encontrarei, e rasgareis os peitorais de seu coração; e ali os devorarei como leão; os animais do campo os despedaçarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Estás perdido, ó Israel, porque é em mim que está tua ajuda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Onde está agora o teu rei, para que te proteja em todas as tuas cidades? E teus juízes, dos quais disseste: Dá-me um rei e príncipes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Eu te dei um rei em minha ira, e o tirei em meu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'A maldade de Efraim está registrada; seu pecado está guardado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Dores de parto lhe virão; ele é um filho tolo, pois senão ele não continuaria no estado em que os filhos nascem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Eu os resgatarei do poder do mundo dos mortos; eu os livrarei da morte. Onde estão, Ó morte, tuas pestilências? Onde está, ó mundo dos mortos, tua perdição? A compaixão será escondida de meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Ainda que ele frutifique entre os irmãos, virá o vento oriental, vento do SENHOR, subindo do deserto, e sua fonte se secará, sua nascente se secará; ele saqueará o tesouro de tudo o que for precioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samaria levará sua culpa, porque se rebelou contra seu Deus. Cairão a espada; suas crianças serão despedaçadas, e suas grávidas terão seus ventres abertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Converte-te, ó Israel, ao SENHOR teu Deus; porque caíste por tua maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Tomai convosco palavras, e convertei-vos ao SENHOR; dizei-lhe: Tira toda a maldade, e aceita o que é bom; então ofereceremos nossos lábios como bezerros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Os assírios não nos salvarão; não cavalgaremos sobre cavalos, e nunca mais chamaremos à obra de nossas mãos de nossos deuses; porque em ti o órfão alcançará misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Eu curarei sua rebelião, eu os amarei voluntariamente, porque minha ira terá se afastado deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Eu serei a Israel como o orvalho; ele florescerá como lírio, e estenderá suas raízes como o cedro do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Seus ramos se estenderão; sua beleza como a da oliveira, e sua fragrância como o cedro do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Voltarão, e habitarão abaixo de sua sombra: serão vivificados como o trigo, e florescerão como a videira; sua fama será como o vinho do Líbano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Ó Efraim, o que mais eu tenho a ver com os ídolos? Eu o responderei, e dele cuidarei; serei a ele como a faia verde; de mim vem o teu fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Quem é sábio entenda estas coisas, e o prudente as reconheça; porque os caminhos do SENHOR são retos, e os justos andarão neles; mas os transgressores neles cairão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Palavra do SENHOR que veio a Joel, filho de Petuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Ouvi isto, anciãos, e escutai, todos os moradores do país. Por acaso isto aconteceu em vossos dias, ou nos dias de vossos pais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Contai disso a vossos filhos, e vossos filhos a seus filhos, e seus filhos à outra geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'O que restou do gafanhoto cortador o gafanhoto comedor comeu; e o que restou do gafanhoto comedor o gafanhoto devorador comeu, e o que restou do gafanhoto devorador o gafanhoto destruidor comeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Despertai, vós bêbados, e chorai; gemei todos vós que bebeis vinho, por causa do suco de uva, porque foi tirado de vossa boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Porque uma nação subiu sobre minha terra, poderosa e sem número; seus dentes são dentes de leão, e têm presas de leoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Assolou minha videira, e devastou minha figueira; desnudou-a por completo e a derrubou; seus ramos ficaram brancos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Chora tu como a virgem vestida de saco por causa do marido de sua juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'As ofertas de cereais e de bebidas se acabaram da casa do SENHOR; os sacerdotes, servos do SENHOR, estão de luto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'O campo foi assolado, a terra está de luto; porque o trigo foi destruído, o suco de uva se secou, o azeite está em falta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Envergonhai-vos, trabalhadores; gemei, plantadores de vinhas, pelo trigo e pela a cevada; porque a colheita do campo pereceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'A vide se secou, a figueira definhou, assim como a romeira, a palmeira, e a macieira; todas as árvores do campo se secaram; por isso a alegria se secou entre os filhos dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Cingi-vos e lamentai, sacerdotes; gemei, ministros do altar; vinde e deitai em sacos, trabalhadores de meu Deus; porque as ofertas de alimentos e de bebidas foram tiradas da casa de vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Santificai um jejum; convocai uma reunião solene; congregai os anciãos e todos os moradores desta terra na casa do SENHOR vosso Deus, e clamai ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ai daquele dia! Porque perto está o dia do SENHOR, e virá do Todo-Poderoso como destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Por acaso não foi tirado o alimento de diante de nossos olhos, a alegria e o prazer da casa de nosso Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'As sementes se apodreceram debaixo de seus torrões, os celeiros foram assolados, os depósitos foram derrubados; porque o trigo se secou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Como geme o gado! As manadas dos vacas estão confusas, porque não têm pasto! Os rebanhos das ovelhas estão desolados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'A ti, ó SENHOR, eu clamo; porque o fogo consumiu os pastos do deserto, e chama incendiou todas as árvores do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Até os animais do campo clamam a ti, porque os rios de águas se secaram, e o fogo consumiu os pastos do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Tocai a trombeta em Sião, e alertai em alta voz no meu santo monte; perturbem-se todos os moradores do país; porque o dia do SENHOR vem, porque perto está.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Dia de trevas e de escuridão, dia de nuvens e densas trevas, como a madrugada espalhada sobre os montes; um povo grande e poderoso, como nunca houve desde a antiguidade, nem depois dele jamais haverá, de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Diante dele o fogo consome, e atrás dele a chama arde; a terra adiante dele é como o jardim do Éden, mas atrás dele como deserto devastado; nada há que dele possa escapar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Sua aparência é como a aparência de cavalos, e correrão como cavaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Saltarão como estrondo de carruagens sobre as topos dos montes, como som de chama de fogo que consome a palha, como povo poderoso, em posição de combate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Diante dele os povos se angustiarão, todos os rostos se afligirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Como guerreiros correrão, como homens de guerra subirão a muralha; e cada um irá em seus caminhos, e não torcerão suas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Nenhum apertará ao outro; irão cada um em seu percurso; irrompem sem desfazerem suas fileiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Irão pela cidade, correrão pela muralha, subirão nas casas, entrarão pelas janelas como ladrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'A terra se abala diante deles, o céu se estremece; o sol e a lua se escurecem, e as estrelas retiram seu brilho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'E o SENHOR levanta sua voz diante de seu exército; porque suas tropas são muito grandes; porque forte é aquele que cumpre sua palavra; porque o dia do SENHOR é grande, e muito terrível; quem poderá o suportar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Por isso agora o SENHOR diz: Convertei-vos a mim com todo o vosso coração, com jejum, choro e pranto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Rasgai vosso coração, e não vossas vestes.Convertei-vos ao SENHOR vosso Deus, porque ele é piedoso e misericordioso, que demora para se irar, e é grande em bondade, e que se arrepende de castigar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Quem sabe talvez ele volte atrás e se arrependa, e deixe após si uma bênção, uma oferta de alimento de de bebida ao SENHOR vosso Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Tocai a trombeta em Sião, santificai um jejum, convocai uma reunião solene.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Reuni o povo, santificai a congregação, juntai os anciãos, reuni as crianças e os que mamam; saia o noivo de seu cômodo, e a noiva de seu quarto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Os sacerdotes, trabalhadores do SENHOR, chorem entre o alpendre e o altar, e digam: Poupa a teu povo, SENHOR, e não entregues tua herança à humilhação, para que as nações a dominem. Por que entre os povos diriam: Onde está o Deus deles?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Então o SENHOR terá zelo por sua terra, e poupará a seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'E o SENHOR responderá e dirá a seu povo: Eis que eu vos envio pão, suco de uva, e azeite, e deles sereis saciados; e nunca mais vos entregarei à humilhação entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'E afastarei de vós o exército do norte, e o lançarei na terra seca e deserta; sua frente será para o mar oriental, e sua retaguarda para o mar ocidental, e exalará seu mau cheiro; subirá sua podridão, porque fez grandes coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Não temas, ó terra; alegra-te e encha-te de alegria, porque o SENHOR tem feito grandes coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Não temais, vós animais do campo; porque os pastos do deserto voltarão a ficar verdes, porque as árvores darão seu fruto, a figueira e a videira mostrarão seu vigor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'E vós, filhos de Sião, alegrai-vos e enchei-vos de alegria no SENHOR vosso Deus; porque ele vos dará a primeira chuva com justiça, e fará descer sobre vós as primeiras e últimas chuvas do ano, assim como era antes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'E as eiras se encherão de trigo, e os lagares transbordarão de suco de uva e azeite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Assim vos restituirei dos anos em que comeram o cortador, o comedor, o devorador e o destruidor, o meu grande exército que enviei contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'E comereis abundantemente até vos saciar; e louvareis o nome do SENHOR vosso Deus, que fez maravilhas convosco; e nunca mais meu povo será envergonhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'E sabereis que eu estou no meio de Israel, e que eu sou o SENHOR vosso Deus, e não há outro; e meu povo nunca mais será envergonhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'E será depois que derramarei meu Espírito sobre toda carne; e vossos filhos e vossas filhas profetizarão; vossos velhos terão sonhos, e vossos jovens terão visões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'E também sobre os servos e sobre as servas, naqueles dias derramarei o meu Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'E mostrarei maravilhas no céu e na terra; sangue, fogo, e colunas de fumaça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'O sol se tornará em trevas, e a lua em sangue, antes que venha o grande e temível dia do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'E será que todo aquele que invocar o nome do SENHOR será salvo; porque no monte de Sião e em Jerusalém haverá livramento, assim como o SENHOR disse, entre os que restarem, aos quais o SENHOR chamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Porque eis que naqueles dias e naquele tempo eu restaurarei Judá e Jerusalém de seu infortúnio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Então ajuntarei todas as nações, e as farei descer ao vale de Josafá; e ali entrarei em juízo com elas por causa do meu povo, e de minha herança Israel, aos quais dispersaram entre as nações, e repartiram minha terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'E lançaram sortes sobre meu povo, e deram os rapazes em troca de prostitutas, e venderam as moças em troca de vinho para beberem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Além disso, o que tendes a ver comigo vós, Tiro e Sidom, e todas as regiões da Filístia? Quereis vos vingar de mim? E se quereis vos vingar de mim, apressadamente eu vos retribuirei o pagamento sobre vossa cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Pois levastes minha prata e meu ouro, e minhas coisas valiosas e boas pusestes em vossos templos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'E vendestes os filhos de Judá e os filhos de Jerusalém aos filhos dos gregos, para os distanciar de sua pátria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Eis que eu os levantarei do lugar para onde os vendestes, e retribuirei vosso pagamento sobre vossa cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'E venderei vossos filhos e vossas filhas na mão dos filhos de Judá, e eles os venderão aos sabeus, uma nação distante; porque o SENHOR falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Proclamai isto entre as nações, convocai uma guerra; despertai aos guerreiros, acheguem-se, venham todos os homens de guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Fazei espadas de vossas enxadas, e lanças de vossas foices; diga o fraco: Sou forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Ajuntai-vos e vinde, todas as nações ao redor, e reuni-vos. (Ó SENHOR, faze vir ali os teus fortes!)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Levantem-se as nações, e subam ao vale de Josafá; porque ali eu me sentarei para julgar todas as nações ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Lançai a foice, porque a colheita já está madura. Vinde, descei; porque o lagar está cheio, os tanques transbordam; porque a maldade deles é grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Multidões! Multidões no vale da decisão! Porque perto está o dia do SENHOR no vale da decisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'O sol e a lua se escurecerão, e as estrelas recolherão seu brilho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'E o SENHOR bramará desde Sião, e dará sua voz desde Jerusalém, e os céus e a terra tremerão; mas o SENHOR será o refúgio de seu povo, e a fortaleza dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Então sabereis que eu sou o SENHOR vosso Deus, que habito em Sião, o meu santo monte; e Jerusalém será santa, e estrangeiros não mais passarão mais por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'E será naquele tempo, que os montes destilarão suco de uva, e os morros fluirão leite, e por todos os ribeiros de Judá correrão águas; e sairá uma fonte da casa do SENHOR, que regará o vale de Sitim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'O Egito será uma assolação, e Edom se tornará um deserto assolado, por causa da violência que fizeram aos filhos de Judá, em cuja terra derramaram sangue inocente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Mas Judá permanecerá para sempre, e Jerusalém de geração em geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'E purificarei o sangue que não tinha purificado; e o SENHOR habitará em Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'As palavras de Amós, que estava entre os pastores de Tecoa, as quais ele viu sobre Israel nos dias de Uzias rei de Judá, e nos dias de Jeroboão, filho de Joás, rei de Israel, dois anos antes do terremoto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'E disse: O SENHOR bramará desde Sião, e dará sua voz desde Jerusalém; e as habitações dos pastores se prantearão, e o topo do Carmelo se secará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Assim diz o SENHOR: Por três transgressões de Damasco, e pela quarta, não desviarei seu castigo; porque trilharam a Gileade com trilhos de ferro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Por isso meterei fogo na casa de Hazael, que consumirá os palácios de Ben-Hadade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'E quebrarei o ferrolho de Damasco, e exterminarei o morador do vale de Áven, e o dono do cetro de de Bete-Éden; e o povo da Síria será levado em cativeiro a Quir, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Assim diz o SENHOR: Por três transgressões de Gaza, e pela quarta, não desviarei seu castigo; pois levaram a todos do povo em cativeiro, para os entregar a Edom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Por isso meterei fogo no muro de Gaza, que consumirá seus palácios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'E exterminarei o morador de Asdode, e o dono do cetro de Asquelom; e tornarei minha mão contra Ecrom, e o resto dos filisteus perecerá, diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Assim diz o SENHOR: Por três transgressões de Tiro, e pela quarta, não desviarei seu castigo; porque entregaram todo o povo em cativeiro a Edom, e não se lembraram do pacto de irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Por isso meterei fogo no muro de Tiro, que consumirá seus palácios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Assim diz o SENHOR: Por três transgressões de Edom, e pela quarta, não desviarei seu castigo; porque perseguiu seu irmão à espada, e extinguiu suas misericórdias; e sua ira o despedaçou continuamente, e mantém sua indignação eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Por isso meterei fogo em Temã, que consumirá os palácios de Bosra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Assim diz o SENHOR: Por três transgressões dos filhos de Amom, e pelo quarta, não desviarei seu castigo; porque rasgaram o ventre das grávidas de Gileade, para expandirem seus territórios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Por isso acenderei fogo no muro de Rabá, que consumirá seus palácios com grito no dia de batalha, com tempestade no dia do vento forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'E seu rei irá ao cativeiro, e junto dele seus príncipes, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Assim diz o SENHOR: Por três transgressões de Moabe, e pela quarta, não desviarei seu castigo; porque queimou os ossos do rei de Edom até os tornar em cal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Por isso meterei fogo em Moabe, que consumirá os palácios de Queriote; e Moabe morrerá em tumulto, com grito e som de trombeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'E exterminarei o juiz do meio dele, e matarei a todos seus príncipes com ele,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Assim diz o SENHOR: Por três transgressões de Judá, e pela quarta, não desviarei seu castigo; porque rejeitaram a lei do SENHOR, e não guardaram seus estatutos; e foram enganados por suas mentiras, as quais seus pais seguiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Por isso meterei fogo em Judá, que consumirá os palácios de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Assim diz o SENHOR: Por três transgressões de Israel, e pela quarta, não desviarei seu castigo; porque vendem o justo em troca de dinheiro, e o pobre por um par de sapatos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Eles pisam a cabeça dos pobres no pó da terra, e distorcem o caminho dos humildes; um homem e seu pai vão a uma mesma moça, para profanarem o meu santo nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'E se deitam junto a qualquer altar com roupas tomadas em penhor, e bebem vinho tomado como multa da casa de seus deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Eu, pelo contrário, destruí diante deles os amorreus, cuja altura era como a altura dos cedros, e eram fortes como carvalhos; e destruí seu fruto acima, e suas raízes abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Também vos fiz a vós subir da terra do Egito, e por quarenta anos vos conduzi pelo deserto, para que possuísseis a terra dos amorreus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'E levantei alguns de vossos filhos para profetas, e de vossos rapazes para que fossem nazireus. Não é isto assim, filhos de Israel?Diz o SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Mas aos nazireus destes de beber vinho; e aos profetas mandastes, dizendo: Não profetizeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Pois eis que eu vos esmagarei em vosso lugar, tal como uma carroça cheia de feixes esmaga;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'De modo que o veloz não conseguirá escapar, nem o forte conseguirá usar de sua força, nem o guerreiro livrará sua vida;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'E o que maneja o arco não subsistirá, nem o veloz de pés se livrará, nem o que monta em cavalo livrará sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'O mais corajoso entre os guerreiros fugirá nu naquele dia, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Ouvi esta palavra que o SENHOR fala contra vós, ó filhos de Israel, contra toda família que eu fiz subir da terra do Egito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Somente reconheci a vós mesmos de todas as famílias da terra; por isso punirei contra vós todas as vossas injustiças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Por acaso irão dois juntos, se não estiverem de acordo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Rugirá o leão no bosque se não houver presa? Dará o leãozinho seu som desde sua cova, se nada tiver capturado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Cairá o ave no laço na terra, se não houver armadilha para ela? Se levantará o laço da terra, se nada houver prendido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Tocará a trombeta na cidade, e o povo não se estremecerá? Haverá alguma calamidade na cidade que o SENHOR não tenha feito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Certamente o Senhor DEUS não fará coisa alguma sem ter revelado seu segredo a seus servos os profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Quando o leão ruge, quem não temerá? Quando o Senhor DEUS fala, quem não profetizará?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Anunciai nos palácios de Asdode e nos palácios da terra do Egito, e dizei: Reuni-vos sobre os montes de Samaria, e vede os grandes tumultos no meio dela, e as opressões no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'E não sabem fazer o que é correto, diz o SENHOR; em seus palácios acumulam bens obtidos por violência e destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Portanto o Senhor DEUS diz assim: Um inimigo! Ele está ao redor da terra, e derrubará de ti a tua fortaleza, e teus palácios serão saqueados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Assim diz o SENHOR: Tal como o pastor livra da boca do leão duas pernas ou a ponta de uma orelha, assim os filhos de Israel que moram em Samaria serão livrados, com um canto da cama, e um pedaço do leito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Ouvi e testemunhai contra a casa de Jacó, diz o SENHOR Deus dos exércitos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Que no dia em que eu punir as transgressões de Israel sobre ele, também farei punição sobre os altares de Betel; e as pontas do altar serão cortadas, e cairão por terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'E ferirei a casa do inverno com a casa do verão, e as casas de marfim se acabarão; e muitas casas terão fim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Ouvi esta palavra, vós vacas de Basã, que estais no monte de Samaria; que oprimis os pobres, que quebrantais os necessitados, que dizeis a seus senhores: Trazei nossa bebida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'O Senhor DEUS jurou por sua santidade: Eis que vêm dias sobre vós em que vos levarão em ganchos, e a vossos descendentes em anzóis de pesca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'E saireis pelas brechas cada uma atrás da outra, e sereis lançadas para Harmom, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Ide a Betel, e transgredi; em Gilgal aumentai as transgressões, e de manhã trazei vossos sacrifícios, vossos dízimos ao terceiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'E oferecei sacrifício de louvores com lêvedo, e anunciai ofertas voluntárias; pois é assim que quereis, ó filhos de Israel,diz o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Eu também vos dei bocas vazias em todas vossas cidades, e falta de pão em todos os vossos lugares, contudo não vos convertestes a mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Além disso eu vos retive a chuva três meses antes da colheita; e fiz chover sobre uma cidade, e sobre outra cidade não fiz chover; sobre um campo choveu; mas o outro campo sobre o qual não choveu, se secou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'De modo que os moradores de duas ou três cidades perambulavam até uma cidade para beberem água, mas não se saciavam; contudo não vos convertestes a mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Eu vos feri com ferrugem e doenças nas plantas; a multidão de vossos jardins e vossas vinhas, vossas figueiras e vossas oliveiras o gafanhoto comeu; contudo não vos convertestes a mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Enviei entre vós a pestilência, à maneira do Egito; matei à espada vossos rapazes, e deixei que capturassem vossos cavalos; e fiz subir o mau cheiro de vossos exércitos até vossas narinas; contudo não vos convertestes a mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Transtornei a alguns dentre vós, como quando Deus transtornou a Sodoma e a Gomorra, e fostes como tição escapado do fogo; contudo não vos convertestes a mim, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Portanto assim farei a ti, ó Israel; e visto que te farei isto, ó Israel, prepara-te para te encontrares com teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Porque eis que ele é que forma os montes, cria o vento, e informa seu pensamento ao ser humano; ele é o que torna a manhã em trevas, e pisa sobre as alturas da terra; EU-SOU, o Deus dos exércitos, é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Ouvi esta palavra que eu levanto sobre vós, uma lamentação, ó casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'A virgem Israel caiu, não poderá mais se levantar; abandonada está sobre sua terra, ninguém há que a levante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Porque assim diz o Senhor DEUS: A cidade que enviou mil soldados sobrará com cem; e a que enviou cem sobrará com dez, na casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Porque assim diz o SENHOR à casa de Israel: Buscai-me, e vivereis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Porém não busqueis a Betel nem venhais a Gilgal, nem passeis a Berseba; porque Gilgal será levada em cativeiro, e Betel será reduzida a nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Buscai ao SENHOR, e vivereis; para que não aconteça que surja como fogo à casa de José, e a consuma, sem haver em Betel quem o apague.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Vós perverteis o juízo em absinto, e abandonam a justiça no chão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Ele é o que fez as Plêiades e o Órion, e torna as trevas em manhã, e faz escurecer o dia em noite; ele chama as águas do mar, e as derrama sobre a face da terra; EU-SOU é o seu nome:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Ele causa súbita destruição sobre o forte, e torna em ruínas a fortaleza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Na porta da cidade eles odeiam ao que repreende, e abominam ao que fala com justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Portanto, visto que pisoteais ao pobre e tomais dele um carga de trigo; assim edificastes casas de pedras lavradas, mas não habitareis nelas; plantastes belas vinhas, mas não bebereis o vinho delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Pois sei que vossas transgressões são muitas e vossos pecados são grandes; afligis o justo, e recebeis suborno, e negam o direito dos necessitados na porta da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Por isso o prudente em tal tempo fica calado, porque é um tempo mau.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Buscai o bem, e não o mal, para que vivais; e assim o SENHOR Deus dos exércitos estará convosco, como dizeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Odiai o mal, amai o bem, e praticai justiça na porta da cidade; talvez o SENHOR Deus dos exércitos tenha piedade do restante do povo de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Portanto assim diz o SENHOR Deus dos exércitos, o Senhor: Em todas as praças haverá pranto, e em todas as ruas dirão: Ai! ai! E chamarão o lavrador ao choro, e os que sabem prantear ao lamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'E em todas as vinhas haverá pranto, porque passarei por meio de ti,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Ai dos que desejam o dia do SENHOR! Para que quereis este dia do SENHOR? Será trevas, e não luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Será como se alguém fugisse do leão, e o urso se encontrasse com ele; ou como se entrasse em alguma casa e apoiasse sua mão à parede, e fosse picado por uma cobra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Por acaso não será o dia do SENHOR trevas e não luz, uma escuridão sem claridade alguma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Eu odeio, desprezo vossas solenidades, e não aguento vossas reuniões religiosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Ainda que me ofereçais holocaustos e vossas ofertas de alimentos, não os aceitarei; nem darei atenção a vossas ofertas de gratidão de vossos animais cevados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Afasta de mim os teus muitos cânticos; também não ouvirei as melodias de teus instrumentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Em vez disso, corra o juízo como as águas, e a justiça como um ribeiro impetuoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Por acaso vós oferecestes a mim sacrifícios e ofertas de alimento no deserto durante os quarenta anos, ó casa de Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Em vez disso, levastes as imagens de vosso rei Sicute, e de Quium, a estrela de vossos deus, que fizestes para vós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Portanto eu vos levarei cativos, para além de Damasco, diz o SENHOR, cujo nome é Deus dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Ai dos que estão tranquilos em Sião, e dos que se sentem seguros no monte de Samaria, que são os príncipes da principal das nações, aos quais o povo de Israel vem!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Passai a Calné, e vede; e dali ide à grande Hamate; depois descei a Gate dos filisteus; por acaso são aqueles reinos melhores que estes, ou seu território maior que vosso território?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Vós que pensais estar distante o dia mau, e aproximais o assento da violência;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Eles se deitam em camas de marfim, e se estendem sobre seus leitos; comem os cordeiros do rebanho, e os bezerros de em meio do curral;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Cantam ao som da harpa, e inventam para si instrumentos musicais, como Davi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Bebem vinho em tigelas, e se ungem com o óleo mais valioso; mas não se afligem pela ruína de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Por isso agora serão os primeiros a serem levados presos ao cativeiro, e o banquete dos que vivem no conforto se acabará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'O Senhor DEUS jurou por si mesmo; o SENHOR Deus dos exércitos diz: Eu abomino a arrogância de Jacó, e odeio seus palácios; por isso entregarei a cidade e tudo que ela tem ao inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'E acontecerá que, se dez homens restarem em uma casa, mesmo eles morrerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'E quando seu parente vier para queimar os cadáveres,para tirar os ossos de casa, então dirá ao que estiver dentro da da casa: Há ainda alguém contigo? E ele responderá: Não. Então aquele dirá: Cala-te! Não menciones o nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Porque eis que o SENHOR mandará, e ferirá a casa maior com quebrantamento, e a casa menor com despedaçamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Por acaso correm os cavalos pelos rochedos? Pode-se arar ali com bois? Porém vós pervertestes o juízo em veneno, e o fruto da justiça no amargo absinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Vós que vos alegrais por nada, que dizeis: Não conquistamos Carnaim por nossa própria força?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Diz o SENHOR Deus dos exércitos: Pois eis que eu levantarei contra vós, ó casa de Israel, uma nação que vos oprimirá desde a entrada de Hamate até o ribeiro de Arabá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Assim o Senhor DEUS me fez ver: eis que ele formava gafanhotos, no começo do crescimento da plantação tardia; e eis que era a plantação tardia, depois da colheita do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'E aconteceu que, quando eles terminaram de comer a plantação da terra, eu disse: Senhor DEUS, perdoa, por favor; como Jacó poderá sobreviver? Pois é pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Então o SENHOR se arrependeu disso: Isto não acontecerá,disse o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Assim o Senhor DEUS me fez ver: eis que o Senhor DEUS pretendeu executar juízo com fogo; e consumiu um grande abismo, assim como consumiu uma parte da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Então eu disse: Senhor DEUS, cessa, por favor; como Jacó poderá sobreviver? Pois é pequeno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'E o SENHOR se arrependeu disso: Isto também não acontecerá, disse o Senhor DEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Assim ele me fez ver: Eis que o Senhor estava sobre um muro que havia sido feito conforme o prumo, e havia um prumo em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'E o SENHOR me disse: O que vês, Amós? E eu disse: Um prumo. Então o Senhor disse: Eis que eu porei um prumo no meio de meu povo Israel; não mais o tolerarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'E os altos de idolatria de Isaque serão arruinados, e os santuários de Israel serão arruinados; e me levantarei com espada contra a casa de Jeroboão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Então Amazias, o sacerdote de Betel, mandou mensagem a Jeroboão, rei de Israel, dizendo: Amós tem conspirado contra ti no meio da casa de Israel; o país não poderá suportar todas as suas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Porque assim diz Amós: Jeroboão morrerá a espada, e Israel certamente será levado de sua terra em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Depois Amazias disse a Amós: Vidente, vai embora, e foge para a terra de Judá, e ali come o teu pão, e ali profetiza;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Porém não profetizes mais em Betel, porque ali estão o santuário do rei, e o palácio real.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Então Amós respondeu a Amazias: Eu não era profeta, nem filho de profeta; mas eu era criador de gado, e colhedor de frutos de sicômoros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Porém o SENHOR me tomou do trabalho com o gado, e o SENHOR me disse: Vai, e profetiza a meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Agora pois, ouve a palavra do SENHOR. Tu dizes: Não profetizes contra Israel, nem fales contra a casa de Isaque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Por isso, assim diz o SENHOR: Tua mulher se prostituirá na cidade, teus filhos e tuas filhas cairão à espada, e tua terra será repartida; tu morrerás em uma terra impura, e Israel será levado cativo de sua terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Assim o SENHOR me fez ver: eis um cesto com frutos de verão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'E ele disse: O que vês, Amós? E eu disse: Um cesto com frutos de verão. Então o SENHOR me disse: Chegou o fim sobre meu povo Israel; não mais o tolerarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'E os cânticos do templo serão gemidos naquele dia,diz o Senhor DEUS; os cadáveres serão muitos, em todo lugar serão lançados. Silêncio!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Ouvi isto, vós que tragais os necessitados, e arruinais os pobres da terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Dizendo: Quando passará a lua nova, para vendermos o alimento? E o sábado, para abriremos os depósitos de trigo, e diminuirmos a medida, aumentarmos o preço, e fraudarmos com balanças enganosas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Para comprarmos os pobres por dinheiro, e os necessitados por um par de sapatos, e venderemos os refugos do trigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'O SENHOR jurou pela glória de Jacó: Eu nunca me esquecerei das obras deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'A terra não se abalará por causa disto, e todo habitante dela não chorará? Certamente ela se levantará como um rio, se agitará, e se afundará como o rio do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'E será naquele dia,diz o Senhor DEUS, que farei o sol se pôr ao meio-dia, e escurecerei a terra no dia claro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'E tornarei vossas festas em luto, e todas as vossas canções em pranto; e farei com que todos se vistam de saco, e se façam calvas sobre todas as cabeças; e farei com que haja luto como de um filho único, e seu fim será como um dia amargo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Eis que vêm dias,diz o Senhor DEUS, nos quais enviarei fome à terra; fome não de pão, nem sede de água, mas sim de ouvir as palavras do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'E irão sem rumo de mar a mar, do norte até o oriente; correrão de um lado para o outro em busca da palavra do SENHOR, mas não a encontrarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Naquele tempo as belas virgens e os rapazes desmaiarão de sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Quanto aos que juram pelo pecado de Samaria, e dizem: Vive o teu deus de Dã; e: Vive o caminho de Berseba; esses cairão, e nunca mais se levantarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Vi o Senhor que estava sobre o altar, e disse: Fere o topo das colunas, para que se estremeçam os umbrais; despedaça-os sobre as cabeça de todos; e os últimos deles matarei à espada; não haverá entre eles que fuja, nem quem se livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Ainda que cavassem até o mundo dos mortos, dai minha mão os tomaria; e se subissem até o céu, dali eu os faria descer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'E se se escondessem no topo do Carmelo, ali eu os buscaria e os tomaria; e ainda que se escondessem de diante de meus olhos no fundo do mar, até ali mandia uma serpente para os morder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'E se forem levados em cativeiro diante de seus inimigos, ali mandarei a espada que os matará; e porei meus olhos sobre eles para o mal, e não para o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Pois o Senhor DEUS dos exércitos é o que toca a terra, e ela se derrete, e choram todos os que nela moram; ela toda subirá como um rio, e se afundará como o rio do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Ele edificou suas câmaras no céu, e fundou seu alicerce sobre a terra; ele chama as águas do mar e as derrama sobre a terra. EU-SOU é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Vós, filhos de Israel, por acaso não sois para mim como os filhos de Etíopes? Diz o SENHOR. Por acaso eu não fiz subir a Israel desde a terra do Egito, assim como os filisteus desde Caftor, e os sírios desde Quir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Eis que os olhos do Senhor DEUS estão contra este reino pecador, e eu o exterminarei da face da terra; mas não exterminarei por completo a casa de Jacó, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Porque eis que dou ordem para que a casa de Israel seja cirandada entre todas as nações, assim como o grão é cirandado na peneira, e nenhum grão cairá na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Morrerão à espada todos os pecadores de meu povo, que dizem: O mal não chegará a nós, nem nos encontrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Naquele dia voltarei a levantar a caída tenda de Davi; fecharei seus brechas, repararei suas ruínas, e a reconstruirei como nos dias antigos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Para que tomem posse do restante de Edom, e todas as nações que se chamam pelo meu nome, diz o SENHOR, que faz isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Eis que vêm dias, diz o SENHOR, em que o que ara alcançará ao que colhe, e o que pisa as uvas ao que leva a semente; e os montes destilarão suco de uva, e todos os morros se derreterão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'E restaurarei meu povo Isarael de seu infortúnio; então reconstruirão as cidades assoladas, e nelas habitarão; e plantarão vinhas, e beberão o vinho delas; e farão jardins, e comerão o fruto deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Pois eu os plantarei em sua terra, e nunca mais serão arrancados de sua terra, que eu lhes dei, diz o SENHOR, teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Visão de Obadias. Assim diz o Senhor DEUS quanto a Edom: Temos ouvido notícias do SENHOR, e mensageiro foi enviado entre as nações; levantai-vos, e nos levantaremos em batalha contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Eis que eu te faço pequeno entre as nações; tu és muito desprezado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'A arrogância de teu coração te enganou, tu que habitas nas fendas das rochas, em teu alta morada; que dizes em teu coração: Quem me derrubará ao chão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Se te elevares como a águia, e se puseres teu ninho entre as estrelas, dali eu te derrubarei,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Se ladrões viessem a ti, ou assaltantes de noite, não furtariam apenas o que lhes bastasse? Se vindimadores viessem a ti, por acaso eles não deixariam algumas sobras? Porém tu, como estás arrasado!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Como Esaú foi saqueado! Como seus tesouros foram tomados!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Todos os teus aliados te moveram até as fronteiras; os que têm acordo de paz contigo te enganaram, prevaleceram contra ti; os que comem do teu pão porão armadilha para ti, (nele não há entendimento).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Não será naquele dia,diz o SENHOR, que farei perecer os sábios de Edom, e o entendimento da montanha de Esaú?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'E teus guerreiros, ó Temã, ficarão atemorizados; para que cada um da montanha de Esaú seja exterminado pela matança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Por causa da violência feita a teu irmão Jacó, a vergonha te cobrirá; e serás exterminado para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'No dia em que estavas diante dele, no dia em que estrangeiros levavam cativo seu exército, e estranhos entravam por suas portas e repartiam a posse de Jerusalém, tu também eras como um deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Pois tu não devias olhar com prazer para o dia de teu irmão, o dia em que ele foi exilado; não devias te alegrar dos filhos de Judá no dia da ruína deles, nem falar com arrogância no dia da angústia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Nem devias ter entrado pela porta de meu povo no dia de sua calamidade; não devias ter olhado seu mal no dia de sua calamidade, nem ter roubado seus bens no dia de sua calamidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Nem devias ter ficado parado nas encruzilhadas, para exterminar os que dela escapassem; nem devias ter entregue os sobreviventes no dia da angústia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Porque perto está o dia do SENHOR sobre todas as nações; como tu fizeste, assim se fará a ti; o pagamento devido voltará sobre tua cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Pois tal como vós bebestes no meu santo monte, assim também todas as nações beberão continuamente; beberão, e engolirão, e serão como se nunca tivessem existido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Mas no monte de Sião haverá livramento, e ele voltará a ser santo; e a casa de Jacó tomará posse de suas propriedades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'E a casa de Jacó será fogo, a casa de José será chama, e os da casa de Esaú serão palha; e se incendiarão contra eles, e os consumirão, de modo que não haverá sobrevivente na casa de Esaú, porque o SENHOR falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'E os do Negueve possuirão a montanha de Esaú, e os da planície tomarão posse da terra dos filisteus; possuirão também os campos de Efraim, e os campos de Samaria; e Benjamim tomará posse de Gileade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'E os cativos deste exército dos filhos de Israel possuirão o que era dos cananeus até Sarepta; e os cativos de Jerusalém, que estão em Sefarade, possuirão as cidades do Negueve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'E salvadores se levantarão no monte de Sião, para julgarem ao monte de Esaú; e o reino pertencerá ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'E veio a palavra do SENHOR a Jonas, filho de Amitai, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Levanta-te, vai à grande cidade de Nínive, e prega contra ela; porque sua maldade subiu diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Porém Jonas se levantou para fugir da presença do SENHOR a Társis, e desceu a Jope; e achou um navio que partia para Társis. Então pagou sua passagem e entrou nele, para ir com eles a Társis a fim de se distanciar do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Mas o SENHOR fez levantar um grande vento no mar; e fez-se uma tempestade tão grande no mar, que o navio estava a ponto de se quebrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Então os marinheiros tiveram medo, e cada um clamava a seu deus; e lançaram no mar os objetos que havia no navio, para com eles diminuir o peso. Jonas, porém, havia descido ao interior do navio, e se pôs a dormir profundamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'E o capitão do navio se aproximou dele, e lhe disse: Que há contigo, dorminhoco? Levanta-te, e clama a teu deus; talvez ele se lembre de nós, para que não pereçamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'E disseram cada um a seu companheiro: Vinde, e lancemos sortes, para sabermos por causa de quem este mal veio sobre nós. Então lançaram sortes, e a sorte caiu sobre Jonas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Então eles lhe disseram: Conta-nos, por favor, por que nos este mal nos veio. Qual é a tua profissão, e de onde vens? Qual é a tua terra, e de que povo és?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'E ele lhes respondeu: Sou hebreu, e temo ao SENHOR, o Deus dos céu, que fez o mar e a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Então aqueles homens tiveram um grande medo, e lhe disseram: Por que fizeste isto? Pois aqueles homens sabiam que ele estava fugindo do SENHOR, porque ele já havia lhes dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Então lhe disseram: O que faremos contigo, para que o mar se nos aquiete?Porque o mar cada vez mais se embravecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'E ele lhes respondeu: Tomai-me, e lançai-me ao mar, e o mar se vos aquietará; porque eu sei que foi por minha causa que esta grande tempestade veio sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Mas os homens se esforçavam para remar, tentando voltar à terra firme; porém não conseguiam, porque o mar cada vez mais se embravecia sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Então clamaram ao SENHOR, e disseram: Ó SENHOR, nós te pedimos para não perecermos por causa da alma deste homem, nem ponhas sangue inocente sobre nós; porque, tu, SENHOR, fizeste como te agradou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Então tomaram a Jonas, e o lançaram ao mar; e o mar se aquietou de seu furor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Por isso aqueles homens temeram ao SENHOR com grande temor; e ofereceram sacrifício ao SENHOR, e prometeram votos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Mas o SENHOR havia preparado um grande peixe para que tragasse a Jonas; e Jonas esteve três dias e três noites no ventre do peixe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'E Jonas orou ao SENHOR seu Deus, desde as entranhas do peixe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'E disse: Clamei de minha angústia ao SENHOR, e ele me respondeu; do ventre do mundo dos mortos gritei, e tu ouviste minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Pois tu me lançaste no profundo, no meio dos mares, e a correnteza me cercou; todas as tuas ondas e tuas vagas passaram sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'E eu disse: Lançado estou de diante de teus olhos; porém voltarei a ver o teu santo templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'As águas me cercaram até a alma, o abismo me rodeou; as algas se enrolaram à minha cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Desci aos fundamentos dos montes; a terra trancou suas fechaduras a mim para sempre; porém tu tiraste minha vida da destruição, ó SENHOR meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Quando minha alma desfalecia em mim, eu me lembrei do SENHOR; e minha oração chegou a ti em teu santo templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Os que dão atenção a coisas inúteis e ilusórias abandonam sua própria misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Mas eu porém sacrificarei a ti com voz de gratidão; pagarei o que prometi. A salvação vem do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'E o SENHOR falou ao peixe, e este vomitou a Jonas em terra firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'E a palavra do SENHOR veio pela segunda vez a Jonas, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Levanta-te, e vai à grande cidade de Nínive, e prega contra ela a pregação que eu te falo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Então Jonas se levantou, e foi a Nínive, conforme a palavra do SENHOR. E Nínive era cidade extremamente grande, de três dias de caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'E Jonas começou a entrar pela cidade, caminho de um dia, e pregava dizendo: Daqui a quarenta dias Nínive será destruída.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'E os homens de Nínive creram em Deus; e convocaram um jejum, e se vestiram de sacos, desde o maior até o menor deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Pois quando esta palavra chegou ao rei de Nínive, ele se levantou de seu trono, e lançou de si sua roupa, e cobriu-se de saco, e se sentou em cinzas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'E convocou e anunciou em Nínive, por mandado do rei e de seus maiorais, dizendo: Nem pessoas nem animais, nem bois nem ovelhas, provem coisa alguma, nem se lhes dê alimento, nem bebam água;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'E que as pessoas e os animais se cubram de saco, e clamem fortemente a Deus; e convertam- se cada um de seu mau caminho, e da violência que está em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Quem sabe Deus mude de ideia e se arrependa, e se afaste do ardor de sua ira, para não perecermos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'E Deus viu a atitude deles, que se converteram de seu mau caminho; então Deus se arrependeu do mal que tinha dito que lhes faria, e não o fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Mas Jonas se desgostou muito, e se encheu de ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'E orou ao SENHOR, e disse: Ah, SENHOR, não foi isto o que eu dizia enquanto ainda estava em minha terra? Por isso me preveni fugindo a Társis; porque sabia eu que tu és Deus gracioso e misericordioso, que demoras a te irar, tens grande misericórdia, e te arrependes do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Agora pois, ó SENHOR, peço-te que me mates, porque é melhor para mim morrer do que viver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'E o SENHOR lhe disse: É correta essa tua ira?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'E Jonas saiu da cidade, e se sentou ao oriente da cidade, e fez para si ali uma barraca, e se sentou debaixo dela à sombra, até ver o que seria da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'E o SENHOR Deus preparou uma planta, e a fez crescer sobre Jonas para que fizesse sombra sobre sua cabeça, e lhe aliviasse de seu mal-estar; e Jonas se alegrou grandemente por causa da planta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Mas Deus preparou uma lagarta no dia seguinte ao amanhecer, a qual feriu a planta, e ela se secou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'E aconteceu que, ao levantar do sol, Deus preparou um quente vento oriental; e o sol feriu a Jonas na cabeça, de modo que ele se desmaiava, e desejava a morte, dizendo: Melhor é para mim morrer do que viver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Então Deus disse a Jonas: É correta a tua ira pela planta?E ele respondeu: É correto eu me irar até a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'E o SENHOR disse: Tu tiveste pena da planta, na qual não trabalhaste, nem tu a fizeste crescer, que em uma noite nasceu, e em outra noite pereceu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'E não teria eu pena de Nínive, aquela grande cidade onde há mais de cem e vinte mil pessoas que não sabem a diferença entre sua mão direita e a esquerda, e muitos animais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Palavra do SENHOR que veio a Miqueias, o morastita, nos dias de Jotão, Acaz, e Ezequias, reis de Judá; que ele viu sobre Samaria e Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Ouvi vós todos os povos; presta atenção tu, ó terra, e tudo o que nela há; pois o Senhor DEUS será testemunha contra vós, o Senhor desde seu santo templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Porque eis que SENHOR está saindo de seu lugar, e descerá, e pisará os lugares altos da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'E os montes debaixo dele se derreterão, e os vales se fenderão como a cera diante do fogo, como as águas se derramam por um precipício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Tudo isto é por causa da transgressão de Jacó e dos pecados da casa de Israel. Qual é a transgressão de Jacó? Não é Samaria? E quais são os altos de Judá? Não é Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Por isso tornarei a Samaria em amontoado de pedras no campo, em plantação de vinhas; e derrubarei suas pedras no vale, e descobrirei seus fundamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'E todas suas imagens de escultura serão esmigalhadas, e todos seus salários de prostituta serão queimados com fogo, e destruirei todos os seus ídolos; porque do salário de prostituta os ajuntou, e para salário de prostituta voltarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Portanto lamentarei e uivarei, e andarei descalço e nu; farei uivos como de chacais, e lamentos como de filhotes de avestruzes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Porque suas feridas são incuráveis, que já chegaram até Judá; isto já chegou até a porta do meu povo, até Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Não anunciai isto em Gate, nem choreis tanto; revolve-te no pó em Bete-Le-Afra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Passa-te com vergonha descoberta, ó moradora de Safir; a moradora de Zaanã não sai; pranto há em Bete-Ezel; seu apoio foi tomado de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Porque a moradora de Marote anseiam à espera do bem; pois um mal desceu do SENHOR até a porta de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Liga os cavalos à carruagem, ó moradora de Laquis (ela é o princípio do pecado à filha de Sião), porque em ti foram achadas as transgressões de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Portanto, tu darás presentes de despedida a Moresete-Gate; as casas de Aczibe serão enganosas aos reis de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Ainda trarei a ti um conquistador, ó moradora de Maressa; a glória de Israel virá até Adulão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Faz em ti calva, e rapa-te por causa dos filhos a quem gostavas; aumenta tua calva como a águia; porque foram levados de ti em cativeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Ai dos que planejam injustiça, e dos que tramam o mal em suas camas! Quando vem a manhã o efetuam, porque têm o poder em suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'E cobiçam campos, e os roubam; cobiçam casas, e as tomam; oprimem ao homem e a sua casa, ao homem e a sua propriedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Portanto, assim diz o SENHOR: Eis que eu planejo um mal contra esta família, da qual não conseguireis livrar vossos pescoços, nem andareis erguidos; porque o tempo será mau.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Naquele tempo surgirá um provérbio sobre vós, e se lamentará um pranto de lamentação, dizendo: Fomos arruinados por completo; trocada foi a porção de meu povo. Como fomos saqueados! Nossos campos foram repartidos, passados a outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Portanto a ninguém terás que delimite a propriedade de terra por meio de sortes na congregação do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Não profetizeis! Falam eles. Não lhes profetizarão, mas a vergonha não se desviará deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Por acaso se dirá, ó casa de Jacó: O espírito do SENHOR perdeu a paciência? São estas as suas obras? Por acaso minhas palavras não fazem bem ao que age corretamente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Mas recentemente meu povo se levantou como inimigo; tomastes da roupa a capa daqueles que passavam confiantes, voltando da batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Vós expulsais as mulheres de meu povo de suas queridas casas; de suas crianças tirastes minha glória para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Levantai-vos, e ide embora, porque esta terra não serve mais para descanso; pois está contaminada, ela se destruirá, com grande destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Se houver alguém que siga o vento, e fale mentiras e falsidade, dizendo: Eu te profetizarei vinho e de bebida alcoólica, este tal será o profeta deste povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Certamente eu te ajuntarei por completo, ó Jacó; reunirei o restante de Israel; eu o porei junto, como ovelhas de Bosra, como rebanho no meio de seu curral farão estrondo de multidão de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Aquele que rompe obstáculos subirá adiante deles; eles romperão, e passarão pela porta, e sairão por ela; e seu rei irá adiante deles, e o SENHOR estará em sua dianteira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'E eu disse: Ouvi agora, vós líderes de Jacó, e governantes da casa de Israel; por acaso não é vossa responsabilidade saber o que é justo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Vós odiais o bem e amais o mal; vós roubais a pele dos outros, e a carne de seus ossos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Vós sois os que comeis a carne de meu povo, e lhes tirais sua pele, e lhes quebrais seus ossos; e os despedaçais como para a panela, como carne dentro do caldeirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Então clamareis ao SENHOR, mas ele não vos responderá; ao invés disso esconderá sua face diante de vós naquele tempo, pois praticastes maus atos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Assim diz o SENHOR contra os profetas que fazem o meu povo errar, que quando recebem comida proclamam paz, mas declaram guerra contra quem não lhes dá de comer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Portanto se vos fará noite por causa da profecia, e trevas por causa da adivinhação; e o sol se porá sobre estes profetas, e o dia se escurecerá sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'E os videntes se envergonharão, e os adivinhos serão humilhados; todos cobrirão o lábio, porque não haverá resposta de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Porém eu estou cheio do poder do Espírito do SENHOR, e de juízo, e de força, para anunciar a Jacó sua transgressão, e a Israel seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Ouvi agora isto, vós líderes da casa de Jacó, e governantes da casa de Israel, que abominais a justiça, e perverteis tudo o que é justo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Vós edificais a Sião com sangue, e a Jerusalém com injustiça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Seus líderes julgam por suborno, seus sacerdotes ensinam por salário, e seus profetas adivinham por dinheiro; e se apoiam no SENHOR dizendo: Por acaso o SENHOR não está entre nós? Nenhum mal virá sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Portanto por causa de vós Sião será arada como campo, e Jerusalém se tornará um amontoado de pedras, e o monte do templo como os lugares altos de um bosque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Mas acontecerá nos últimos dias que o monte da casa do SENHOR será firmado no cume de montes, e será mais elevado que os morros; e os povos correrão a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'E muitas nações virão e dirão: Vinde, e subamos ao monte do SENHOR, à casa do Deus de Jacó; e ele nos ensinará seus caminhos, e nós andaremos em suas veredas; porque a lei virá de Sião, e a palavra do SENHOR de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'E ele julgará entre muitos povos, e corrigirá poderosas nações até muito longe; e adaptarão suas espadas para enxadas, e suas lanças para foices; nação não erguerá espada contra nação, nem mais aprenderão a fazer guerra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'E cada um se sentará debaixo de sua videira e debaixo de sua figueira, e não haverá quem lhes cause medo; porque a boca do SENHOR dos exércitos assim falou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Pois todos os povos andam cada um no nome de seus deuses; nós, porém, andaremos no nome do SENHOR nosso Deus para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Naquele dia,diz o SENHOR, reunirei a que mancava, e ajuntarei a que havia sido expulsa, e a que eu tinha maltratado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'E farei da que mancava um povo restante, da que havia sido expulsa uma nação poderosa; e o SENHOR reinará sobre eles no monte de Sião desde agora para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'E tu, ó torre de vigilância do rebanho, tu fortaleza da filha de Sião, virá a ti o primeiro domínio; o reino chegará à filha de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Agora por que gritas tanto? Não há rei em ti? Pereceu teu conselheiro, para que tenhas sido tomada por dores como as de parto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Sofre dores e contorce-te, ó filha de Sião, como mulher em trabalho de parto; porque agora sairás da cidade, e morarás no campo, e virás até a Babilônia; porém ali tu serás livrada, ali o SENHOR te redimirá da mão de teus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Mas agora muitas nações se reuniram contra ti, e dizem: Seja profanada, e nossos olhos vejam a desgraça de Sião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Mas elas não sabem os pensamentos do SENHOR, nem entendem seu conselho; de que ele as ajuntou como a feixes para a eira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Levanta-te e trilha, ó filha de Sião, porque tornarei teu chifre de ferro, e tuas unhas de bronze, e esmiuçarás muitos povos; e consagrarás ao SENHOR seus ganhos, e seus bens ao Senhor de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Agora ajunta-te em tropas, ó filha de tropas; fazem cerco ao nosso redor; ferirão ao juiz de Israel com vara no rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Porém tu, Belém Efrata, ainda que sejas pequena entre as famílias de Judá, de ti me sairá o que será governador em Israel; e suas saídas são desde o princípio, desde os dias antigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Por isso ele os entregará até o tempo em que a que estiver de parto der à luz; então o resto de seus irmãos voltarão a estar com os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'E eles se levantará, e governará com a força do SENHOR, com a grandeza do nome do SENHOR seu Deus; e eles habitarão seguros,porque agora ele será engrandecido até os confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'E este será nossa paz; quando a Assíria vier a nossa terra, e quando pisar nossos palácios, então levantaremos contra ela sete pastores, e oito príncipes dentre os homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'E dominarão a terra da Assíria pela espada, e a terra de Ninrode em suas entradas; assim ele nos livrará do assírios, quando vierem contra nossa terra e invadirem nossas fronteiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'E o restante de Jacó estará no meio de muitos povos, como o orvalho do SENHOR, como gotas sobre a erva, que não esperam ao homem, nem aguardam os filhos de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'E o restante de Jacó estará entre as nações, no meio de muitos povos, como o leão entre os animais do bosque, como o leão jovem entre os rebanhos de ovelhas, o qual quando passa, atropela e despedaça, de modo que ninguém há que possa livrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Tua mão se erguerá sobre teus adversários, e todos os teus inimigos serão exterminados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'E será naquele dia,diz o SENHOR, que destruirei teus cavalos do meio de ti, e acabarei com tuas carruagens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Também destruirei as cidades da tua terra, e derrubarei todas as tuas fortalezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Também destruirei as feitiçarias de tua mão, e não terás mais adivinhadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Também destruirei as tuas imagens de escultura e tuas colunas de idolatria do meio de ti, e nunca mais te encurvarás diante da obra de tuas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Também arrancarei teus bosques do meio de ti, e arruinarei tuas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'E com ira e com furor farei vingança das nações que não me deram ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Ouvi agora o que o SENHOR diz: Levanta-te, briga com os montes, e ouçam os morros a tua voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Ouvi vós, montes, e vós, fortes fundamentos da terra, a briga do SENHOR; porque o SENHOR tem uma briga judicial com seu povo, e disputará judicialmente com Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Ó povo meu, o que eu tenho feito a ti? Em que eu te incomodei? Responde-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Pois eu te fiz subir da terra do Egito, e da casa de escravidão eu te livrei; e enviei diante de ti a Moisés, Arão, e Miriã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Ó povo meu, lembra-te agora do Balaque, rei de Moabe, planejou, e do que Balaão, filho de Beor, lhe respondeu, e do que aconteceu desde Sitim até Gilgal, para que conheças as justiças do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Com que me encontrarei com o SENHOR, e adorarei ao alto Deus? Virei diante ele com ofertas de queima, com bezerros de um ano?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'O SENHOR se agradará de milhares de carneiros, ou de dez mil ribeiros de azeite? Darei meu primogênito por minha transgressão, o fruto de meu ventre pelo pecado de minha alma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Ele já declarou a ti, ó ser humano, o que é bom; e que mais o SENHOR pede de ti, a não ser fazer o que é justo, amar a bondade, e andar humildemente com teu Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'A voz do SENHOR clama à cidade (e sábio é temer o teu nome): Ouvi a vara, e a quem a estabeleceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Não há ainda na casa do perverso riquezas da perversidade, e medida enganosamente menor, o que é abominável?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Posso eu tolerar quem tem balanças falsas e bolsa de pesos enganosos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Pois seus ricos estão cheios de violência, e seus moradores falaram mentiras, e suas línguas são enganosas em suas bocas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Por isso eu também te enfraquecerei, ferindo-te e assolando-te por teus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Tu comerás, mas não te saciarás; e fome haverá no meio de ti; tu pegarás, mas não levarás contigo; e o que levares, eu o entregarei à espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Tu semearás, mas não colherás; pisarás azeitonas, mas não te ungirás com óleo; pisarás uvas, mas não beberás vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Pois são os mandamentos de Onri, e todas as obras da casa de Acabe, que são obedecidos; e vós praticais seus conselhos. Por isso eu te tornarei desolada, e teus moradores serão motivo de assovio. Assim levareis a humilhação de meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Ai de mim! Porque sou como quando os frutos do verão são colhidos, como quando são tiradas as sobras das uvas da vindima, de modo que não resta cacho de uvas para comer; minha alma deseja frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Já pereceu o misericordioso da terra, e não há quem seja justo entre os seres humanos; todos armam ciladas em busca de sangue; cada um arma rede de caça a seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Suas mãos são habilidosas em fazer o mal; o príncipe dá ordens e o juiz julga por propina; e o grande fala o mau desejo de sua alma, e colaboram com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'O melhor dentre eles é como o espinho; o mais justo é como o espinheiro. O dia de teus vigilantes, teu castigo, vem; agora será sua confusão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Não creiais em amigo, nem confieis em príncipe; guardas as portas de tua boca daquela que dorme ao teu lado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Porque o filho despreza o pai, a filha se levanta contra sua mãe, a nora contra sua sogra; e os inimigos do homem são os de sua própria casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Eu, porém, observarei ao SENHOR, esperarei ao Deus de minha salvação; meu Deus me ouvirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ó minha inimiga, não te alegres de mim; pois ainda que tenha caído, eu me levantarei; ainda que eu esteja assentado em trevas, o SENHOR será minha luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Suportarei a ira do SENHOR, porque pequei contra ele; suportarei até que ele julgue minha causa e execute meu direito; ele me trará para a luz; eu verei sua justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'E minha inimiga verá isso,e a vergonha a cobrirá; ela que me dizia: Onde está o SENHOR teu Deus? Meus olhos a verão; agora ela será pisada como a lama das ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'No dia em que teus muros forem reconstruídos, naquele dia as fronteiras se ampliarão para longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Naquele dia virão a ti da Assíria até as cidades fortes, das cidades fortes até o rio, e de mar a mar, e de monte a monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Porém esta terra será desolada por causa de seus moradores, por causa do fruto de suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Apascenta teu povo com teu cajado, o rebanho de tua herança, que mora só no bosque, no meio do campo fértil; que se alimentem em Basã e Gileade, como nos dias antigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Eu lhes farei ver maravilhas, como nos dias em que saíste da terra do Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'As nações verão, e se envergonharão de todo o seu poder; porão a mão sobre a boca, ensurdecerão seus ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Lamberão o pó como a serpente; como os répteis da terra sairão tremendo de seus esconderijos; eles ficarão apavorados com o SENHOR nosso Deus, e temerão a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Quem é Deus como tu, que perdoa a maldade, e ignora a transgressão do restante de sua herança? Ele não retém para sempre sua ira, porque ele tem prazer na bondade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Ele voltará a ter misericórdia de nós; ele esmagará nossas maldades. Tu lançarás os pecados deles nas profundezas do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Tu concederás a Jacó a fidelidade, e a Abraão a bondade, que juraste a nossos pais desde os dias antigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Revelação sobre Nínive. Livro da visão de Naum o elcosita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'O SENHOR é Deus zeloso e vingador; o SENHOR é vingador e furioso; o SENHOR se vinga de seus adversários, e que guarda ira contra seus inimigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'O SENHOR é tardio para se irar, porém grande em poder; e não terá ao culpado por inocente. O SENHOR caminha entre a tempestade e o turbilhão, e as nuvens são o pó de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Ele repreende o mar, e o faz secar; e deixa secos todos os rios. Basã e o Carmelo se definham, e a flor do Líbano murcha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Os montes tremem diante dele, e os morros se derretem; e a terra se abala em sua presença, e o mundo, e todos os que nele habitam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Quem pode subsistir diante de seu furor? E quem pode persistir diante do ardor de sua ira? Seu furor se derrama como fogo, e as rochas se partem diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'O SENHOR é bom, é fortaleza no dia da angústia; ele conhece os que nele confiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Mas com inundação impetuosa ele acabará com Nínive, e perseguirá seus inimigos até às trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'O que vós tramais contra o SENHOR, ele mesmo destruirá; a angústia não se levantará duas vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Mesmo estando entretecidos como espinhos, e embriagados como beberrões, eles serão consumidos como a palha seca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'De ti saiu um que trama o mal contra o SENHOR, um conselheiro maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Assim diz o SENHOR: Ainda que sejam prósperos, e muitos em número, mesmo assim eles serão exterminados, e passarão. Eu te afligi, Judá, porém não te afligirei mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Mas agora quebrarei seu jugo de sobre ti, e romperei tuas amarras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Porém contra ti, assírio, o SENHOR mandou que nunca mais seja gerado alguém de teu nome; da casa de teu deus arrancarei as imagens de escultura e de fundição. Farei para ti um sepulcro, porque tu és desprezível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Eis que sobre os montes estão os pés daquele que anuncia boas novas, do que faz ouvir a paz. Celebra tuas festas, Judá; cumpre os teus votos, porque nunca mais o maligno passará por ti; ele foi exterminado por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'O despedaçador está subindo contra ti; guarda a fortaleza, olha para o caminho, prepara os lombos, junta o poder de tuas forças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Porque o SENHOR restituirá a glória de Jacó, como a glória de Israel, ainda que saqueadores tenham os saqueado, e destruído os seus ramos de videira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Os escudos de seus guerreiros são vermelhos, os homens valentes andam vestidos de escarlate; as carruagens brilham no dia em que são preparadas, as lanças se sacodem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'As carruagens se movem furiosamente pelas ruas, percorrem as vias; sua aparência é como tochas, correm como relâmpagos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Seus nobres são convocados, porém tropeçam enquanto marcham; eles se apressam ao seu muro, e a proteção é preparada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'As comportas dos rios são abertas, e o palácio é arruinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Está decretado: ela será levada cativa, e suas criadas a acompanharão com voz de pombas, batendo seus peitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Nínive é como um antigo tanque, cujas águas estão fugindo. Dizem: Parai, parai; porém ninguém sequer olha para trás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Saqueai prata, saqueai ouro; não há fim das riquezas e do luxo, de todo tipo de objetos valiosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Ela está esvaziada, devastada e arruinada; os corações desmaiam, os joelhos tremem, os lombos doem, e os rostos deles todos ficam abatidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Onde está a morada dos leões, e o lugar onde os leões jovens se alimentavam, onde o leão, a leoa, e os filhotes de leão passeavam, e não havia quem os espantasse?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'O leão caçava o suficiente para seus filhotes, e estrangulava para as suas leoas, e enchia suas cavernas de presa, e suas moradas de coisas capturadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Eis que eu sou contra ti,diz o SENHOR dos exércitos. Queimarei as tuas carruagens em fumaça, e espada consumirá teus jovens leões; exterminarei a tua presa da terra, e nunca mais a voz de teus mensageiros será ouvida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Ai da cidade sanguinária, toda cheia de mentiras e de saques; o roubo não cessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Ali há o som de açoite, e o estrondo do mover de rodas; os cavalos atropelam, e as carruagens vão se sacudindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'O cavaleiro ataca, a espada brilha, e a lança resplandece; e ali haverá muitos mortos, e multidão de cadáveres; haverá corpos sem fim, e tropeçarão nos corpos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Por causa da multidão das prostituições da prostituta muito charmosa, mestra de feitiçarias, que vende os povos com suas prostituições, e as famílias com suas feitiçarias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Eis que estou contra ti,diz o SENHOR dos exércitos, e descobrirei tuas saias sobre tua face, e mostrarei tua nudez às nações, tua vergonha aos reinos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'E lançarei sobre ti coisas abomináveis, e te envergonharei, e te tornarei em ridículo público.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'E será que todos os que te virem fugirão de ti, e dirão: Nínive está destruída; quem terá compaixão dela? Onde buscarei para ti consoladores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'És tu melhor que Nô-Amom, que estava situada entre os rios, cercada de águas, cuja fortificação era o mar, e o rio como muralha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Cuxe e Egito era sua fortaleza sem limites; Pute e Líbia estavam para tua ajuda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Porém ela foi levada em cativeiro; também suas crianças foram despedaçadas nas esquinas de todas as ruas; e sobre seus nobres lançaram sortes, e todos seus maiorais foram aprisionados com grilhões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Tu também estarás bêbada, e te esconderás; tu também buscarás fortaleza por causa do inimigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Todas as tuas fortalezas são como figueiras com os primeiros figos, que ao serem sacudidas, caem na boca de quem quer comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Eis que teu exército será como mulheres no meio de ti; as portas de tua terra se abrirão a teus inimigos; fogo consumirá teus ferrolhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Reserva para ti água para o cerco, fortifica as tuas fortalezas; entra na lama, pisa o barro, conserta o forno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Ali o fogo te consumirá, a espada te cortará, te consumirá como o inseto devorador. Multiplica-te como o inseto devorador; multiplica-te como o gafanhoto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Multiplicaste teus mercadores mais que as estrelas do céu; o inseto devorador estende as asas, e sai voando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Teus oficiais são como gafanhotos, e teus capitães como enxames de gafanhotos que pousam em nas paredes nos dias de frio; quando o sol se levanta eles voam, de modo que não se pode saber seu lugar onde estiveram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Teus pastores cochilam, ó rei da Assíria, teus nobres descansam; teu povo se espalhou pelos montes, e ninguém o ajuntará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Não há cura para tua ferida; tua chaga é fatal; todos os que ouviram tua fama baterão palmas por causa de ti, pois sobre quem tua maldade não passou continuamente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Revelação que o profeta Habacuque viu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Até quando, SENHOR, eu clamarei, e tu não ouvirás? Até quando gritarei a ti: Violência!, e tu não salvarás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Por que me fazes ver a injustiça, e vês a opressão? Pois assolação e violência estão em frente de mim, há brigas, e disputas se levantam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Por isso que a lei é enfraquecida, e o juízo nunca se cumpre: porque o perverso cerca o justo, por o juízo é distorcido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Vede entre as nações, e prestai atenção, e espantai-vos, espantai-vos; porque uma obra será feita em vossos dias, que quando for contada, não acreditareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Porque eis que eu levanto os caldeus, uma nação amarga e veloz, que caminha pelas larguras da terra para tomar posse de moradas que não são suas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Ela é espantosa é e terrível; que impõe seu próprio julgamento e sua própria honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'E seus cavalos são mais rápidos que os leopardos, e mais ferozes que lobos de tarde; e seus cavaleiros avançam; seus cavaleiros virão de longe, e voarão como águias que se apressam para devorar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Todos eles vêm para fazer violência; seus rostos estão orientados; e juntarão cativos como areia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'E escarnecerão dos reis, e zombarão dos príncipes; rirão de todas as fortalezas, porque amontoarão terra, e as tomarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Logo mudarão, e passarão adiante como o vento; porém culpado será quem confiar na força de seu deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Não és tu desde o princípio, ó SENHOR, meu Deus, meu Santo? Não morreremos. Ó SENHOR, tu os puseste para executar o julgamento; e tu, ó Rocha, os estabeleceste para castigar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Teus olhos são puros demais para veres o mal, e não podes observar a opressão; ora, por que olharias aos enganadores, e calarias quando o perverso devora ao mais justo que ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Tornarias as pessoas como como os peixes do mar, como répteis que não têm quem os governe?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Ele tira a todos com anzol, em sua malha os ajunta, e os colhe em seu rede; por isso ele se alegra e tem prazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Por isso ele faz sacrifícios à sua malha, e oferece incensos à sua rede; porque com elas enriqueceu sua porção, e engordou sua comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Continuará ele, pois, a esvaziar a sua malha, e a matar as nações continuamente sem ter compaixão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Sobre minha guarda estarei, e sobre a fortaleza ficarei, e vigiarei para ver o que ele me falará, e o que eu responderei à minha queixa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Então o SENHOR me respondeu, e disse: Escreve a visão, e a põe claramente em tábuas, para que mesmo quem esteja correndo consiga ler.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Pois a visão ainda é para um tempo determinado, mas ao fim ela dará testemunho, e não será mentirosa; ainda que se tardar, espera-o, porque virá; não se atrasará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Eis que o soberbo não tem a alma correta em si; mas o justo viverá por sua fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Pois também o vinho é enganador, é como um homem arrogante, que não fica quieto em casa; seu apetite se alarga como o mundo dos mortos, e é semelhante à morte, que não se farta; e ajunta a si todas as nações, e reúne a si todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Por acaso todos estes não levantarão um insulto e provérbios de ridicularizações contra ele? E dirão: Ai daquele que acumula o que não era seu, e daquele de se enriquece por meio de extorsão! Até quando?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Por acaso não se levantarão de repente seus credores, e se despertarão os que te fazem tremer? Tu serás despojado por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Visto que tu despojaste muitas nações, todos os povos restantes te despojarão; por causa do sangue das pessoas, e da violência contra a terra, as cidades e todos os seus moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Ai daquele que obtém riquezas para sua casa por meios malignos, para pôr no alto seu ninho, para tentar se livrar do poder da calamidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Tramaste plano vergonhoso para tua casa, exterminaste muitos povos, e pecaste contra tua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Porque a pedra clamará desde a parede, e a trave desde a estrutura de madeiras lhe responderá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Ai daquele que edifica a cidade com sangues, e do que estabelece a vila com perversidade!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Eis que isto não vem da parte do SENHOR dos exércitos, que os povos trabalham para o fogo, e as nações se cansam em vão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Porque a terra se encherá de conhecimento da glória do SENHOR, como as águas cobrem o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Ai daquele que dá bebidas a seu próximo, tu que embebedas com teu furor, para que possas vê-los nus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Tu te encherás de vergonha no lugar de honra; bebe tu também, e descobre o prepúcio; o cálice da mão direita do SENHOR voltará sobre ti, e haverá vergonha sobre a tua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Porque a violência cometida contra o Líbano te cobrirá, e a destruição dos animais selvagens o assombrará; por causa dos sangues das pessoas, e da violência contra a terra, as cidades, e todos os seus moradores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Que proveito há na imagem de escultura, que seu formador a esculpiu? E na imagem de fundição, que ensina mentiras? Quem a formou nela confia, tendo feito ídolos mudos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Ai daquele que diz ao pedaço de madeira: Desperta-te; e à pedra muda: Levanta-te! Poderá essa coisa ensinar? Eis que está coberta de ouro e prata, mas não há dentro dela espírito algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Porém o SENHOR está em seu santo templo; que toda a terra se cale diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Oração do profeta Habacuque, conforme “Siguionote”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Ó SENHOR, ouvido tenho tua fama; temi, Ó SENHOR, a tua obra; renova-a no meio dos anos; faze-a conhecida no meio dos anos; na ira lembra-te da misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Deus veio de Temã, o Santo do monte de Parã (Selá). Sua glória cobriu os céus, e a terra se encheu de seu louvor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'E houve resplendor como o da luz; raios brilhantes saíam de sua mão; e ali sua força estava escondida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'A praga ia adiante dele, e a pestilência seguia seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Ele parou, e sacudiu a terra; ele olhou, e abalou as nações; e os montes antigos foram despedaçados, os morros antigos caíram. Seus caminhos são eternos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Vi as tendas de Cusã em aflição; as cortinas da terra de Midiã tremeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Por acaso o SENHOR se irritou contra os rios? Foi tua ira contra os ribeiros? Foi tua ira contra o mar, quando cavalgaste sobre teus cavalos, e tuas carruagens de vitória?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Teu arco foi descoberto, as flechas foram preparadas pela tua palavra (Selá). Fendeste a terra com rios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Os montes te viram, e tiveram dores; a inundação das águas passou. O abismo deu sua voz, e levantou suas mãos ao alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'O sol e a lua pararam em suas moradas; à luz de tuas flechas passaram, com o resplendor de tua lança relampejante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Com indignação marchaste pela terra, com ira trilhaste as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Saíste para a salvar o teu povo, para salvar o teu ungido. Feriste o líder da casa do ímpio, descobrindo-o dos pés ao pescoço. (Selá)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Perfuraste com suas próprias lanças os líderes de suas tropas, que vieram impetuosamente para me dispersarem. A alegria deles era como a de devorarem os pobres às escondidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Pisaste pelo mar com teus cavalos, pela turbulência de grandes águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Quando eu ouvi, meu ventre se perturbou; por causa do ruído meus lábios tremeram; podridão veio em meus ossos, e em meu lugar me perturbei; descansarei até o dia da angústia, quando virá contra o povo que nos ataca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Ainda que a figueira não floresça, nem haja fruto nas vides, e falte o produto da oliveira, os campos não produzam alimento, as ovelhas sejam arrebatadas, e não haja vacas nos currais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Mesmo assim eu me alegrarei no SENHOR, terei prazer no Deus de minha salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'DEUS, o Senhor, é minha fortaleza; ele fará meus pés como os das corças, e me fará andar sobre meus lugares altos.(Para o regente, com instrumentos de cordas).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Palavra do SENHOR que veio a Sofonias filho de Cuxi, filho de Gedalias, filho de Amarias, filho de Ezequias, nos dias de Josias filho de Amom, rei de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Destruirei tudo de sobre a face da terra,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Destruirei as pessoas e os animais; destruirei as aves do céu, e os peixes do mar, e as pedras de tropeço com os perversos; e exterminarei os seres humanos de sobre a face da terra,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'E estenderei minha mão contra Judá, e contra todos os moradores de Jerusalém; e exterminarei deste lugar o restante de Baal, e o nome dos idólatras com os sacerdotes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'E os que se encurvam sobre os terraços ao exército do céu; e aos que se encurvam jurando pelo SENHOR, mas também jurando por Milcom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'E aos que dão as costas ao SENHOR, aos que não buscam ao SENHOR, nem perguntam por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Cala-te na presença do Senhor DEUS, porque o dia do SENHOR está perto; porque o SENHOR tem preparado um sacrifício, e santificou a seus convidados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'E será que, no dia do sacrifício do SENHOR, punirei os príncipes, os filhos do rei, e todos os que vestem roupas estrangeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Também punirei naquele dia todos os que saltam sobre o umbral, os que enchem as casas de seus senhores de produtos de violência e de engano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'E naquele dia,diz o SENHOR, haverá voz de clamor desde a porta dos peixes, lamentação desde a segunda parte da cidade,e grande quebrantamento desde os morros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Lamentai, vós moradores do vale, porque todo o povo mercador está destruído; todos os que pesavam dinheiro são exterminados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'E será naquele tempo, que farei busca em Jerusalém com lâmpadas, e punirei os homens que estão acomodados como sedimentos de vinho, os quais dizem em seu coração: O SENHOR nem fará bem nem mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Por isso a riqueza deles será despojada, e suas casas serão arruinadas; edificarão casas, mas não habitarão nelas; e plantarão vinhas, mas não beberão seu vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Perto está o grande dia do SENHOR; perto está, e com muita pressa se aproxima; a voz do Dia do SENHOR; ali o guerreiro gritará amargamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Aquele dia será dia de fúria; dia de angústia e de aflição, dia de devastação e de ruína; dia de trevas e de escuridão, dia de nuvens e de espessa obscuridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Dia de trombeta e de alarme contra as cidades forte e contra as torres as altas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'E angustiarei as pessoas, que andarão como cegas, porque pecaram contra o SENHOR; e o sangue delas será derramado como pó, e sua carne será como esterco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Nem sua prata nem seu ouro poderá os livrar no dia do furor do SENHOR; pois toda esta terra será consumida pelo fogo de seu zelo; porque ele certamente fará destruição repentina com todos os moradores da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Ajuntai-vos, ajuntai-vos, ó nação desagradável,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Antes que o decreto se concretize, e o dia se passe como a palha; antes que o ardor da ira do SENHOR venha sobre vós, antes que o dia da ira do SENHOR venha sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Buscai ao SENHOR todos vós mansos da terra, que praticam seu juízo; buscai justiça, buscai mansidão; talvez sejais preservados no dia da ira do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Porque Gaza será desamparada, e Asquelom desolada; Asdode será expelida ao meio dia, e Ecrom será arrancada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Ai dos que moram à margem do mar, da nação dos quereteus! A palavra do SENHOR é contra vós, ó Canaã, terra dos filisteus; e eu vos destruirei, até que não haja morador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'E a margem do mar se tornará pastagens, com abrigos de pastores, e currais de rebanhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'E aquela região será para o restante da casa de Judá, para que nela apascentem; ao anoitecer se deitarão nas casas de Asquelom, porque o SENHOR, seu Deus, os visitará, e os restaurará de seu infortúnio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Eu ouvi os escárnios de Moabe, e os insultos dos filhos de Amom com que escarneceram a meu povo, e se engrandeceram contra suas fronteiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Portanto vivo eu,diz o SENHOR dos exércitos, Deus de Israel, que Moabe será como Sodoma, e os filhos de Amom como Gomorra; campo de urtigas, e mina de sal, e desolação perpétua; o restante de meu povo os saqueará, e o restante de minha nação tomará posse daquilo que era deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Isto terão por sua soberba, porque escarneceram e se engrandeceram contra o povo do SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'O SENHOR será terrível contra eles, porque ele consumirá a todos os deuses da terra; e cada um desde seu lugar o adorará, todas as regiões costeiras das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Também vós cuxitas sereis mortos pela minha espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'E ele estenderá sua mão contra o norte, e destruirá a Assíria, e tornará Nínive em desolação e em secura como deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'E no meio dela os rebanhos de gado se deitarão, todas os animais das nações; também o corvo a coruja passarão a noite em seus pilares; sua voz se ouvirá nas janelas; assolação será nos umbrais, porque sua estrutura de cedro estará descoberta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Esta é a cidade alegre que habita segura, que diz em seu coração: Nenhuma outra há como eu sou. Como ela se tornará em desolação, em repouso de animais! Qualquer um que passar perto dela assoviará e sacudirá sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Ai da suja e contaminada, da cidade opressora!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Ela não ouve a voz, nem aceita o castigo; não confia no SENHOR, não se achega a seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Seus príncipes no meio dela são leões que rugem; seus juízes são lobos da noite que nada deixam para a manhã seguinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Seus profetas são levianos, homens enganadores; seus sacerdotes profanam o santuário, e violentam a lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'O SENHOR é justo em meio dela, não faz perversidade; de manhã ele tira seu juízo à luz, nunca falha; mas o injusto não conhece a vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Exterminei as nações; suas muralhas estão arruinadas, suas ruas estão desertas, de maneira que ninguém passe por elas; suas cidades estão desoladas de maneira que ninguém restou, nenhum morador sequer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Eu dizia: Certamente me temerás, aceitarás a correção; para que assim sua morada não seja destruída por tudo aquilo que eu havia determinado sobre ela. Porém eles se levantaram de manhã e corromperam todos os seus atos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Portanto esperai em mim,diz o SENHOR, pelo dia em que me levantarei para o despojo; porque minha determinação é ajuntar as nações, reunir os reinos, para derramar sobre eles minha indignação, todo o ardor de minha ira; pois toda a terra será consumida pelo o fogo do meu zelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Então certamente darei lábio puro aos povos, para que todos invoquem o nome do SENHOR, para que lhe sirvam em unidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Dalém dos rios de Cuxe, meus adoradores, a filha de meus dispersos, me trarão oferta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Naquele dia não serás envergonhada por nenhum de teus atos com que transgrediste contra mim; porque então tirarei do meio de ti os que se alegram por tua soberba, e nunca mais te exaltarás por causa do meu monte santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Mas farei restar no meio de ti um povo humilde e pobre; e eles confiarão no nome do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'O restante de Israel não cometerá perversidade, nem falarão mentiras, nem se achará em suas bocas língua enganosa; em vez disso eles serão apascentados e se deitarão, e não haverá quem os espante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Canta alegremente, ó filha de Sião; grita de alegria, ó Israel; alegra-te e anima-te de todo coração, ó filha de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'O SENHOR afastou os julgamentos contra ti, exterminou teu inimigo; o SENHOR, Rei de Israel, está no meio de ti; nunca mais verás mal algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Naquele dia se dirá a Jerusalém: Não temas, Sião, não se enfraqueçam tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'O SENHOR está no meio de ti, guerreiro que salva; ele terá prazer em ti com alegria; ele te aquietará em seu amor, se encherá de alegria por causa de ti com júbilo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Ajuntarei aos que se entristecem de saudade das reuniões solenes; eles eram teus; para eles a humilhação dela era uma peso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Eis que naquele tempo acabarei com todos os teus opressores; e salvarei a manca, e ajuntarei a expulsa; e os tornarei louvor e renome em toda terra em que foram envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Naquele tempo eu vos trarei de volta, naquele tempo eu vos ajuntarei; pois vos tornarei renome e louvor entre todos os povos da terra, quando eu vos resutaurar de vosso infortúnio diante de vossos olhos, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'No segundo ano segundo do rei Dario, no sexto mês, no primeiro dia do mês, veio a palavra do SENHOR, por meio do profeta Ageu, a Zorobabel filho de Sealtiel, governador de Judá, e a Josué filho de Jeozadaque, sumo sacerdote, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Assim fala o SENHOR dos exércitos: Este povo diz: O tempo não chegou, o tempo da casa do SENHOR ser reconstruída.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Veio, pois, a palavra do SENHOR por meio do profeta Ageu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Por acaso é para vós tempo de morar em vossas casas com telhado, e esta casa ficar deserta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Pois assim diz o SENHOR dos exércitos: Considerai vossos caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Semeais muito, mas colheis pouco; comeis, mas não vos fartais; bebeis, mas não vos satisfazeis; vós vos vestis, mas não vos aqueceis; e o assalariado recebe seu salário em bolsa furada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Assim diz o SENHOR dos exércitos: Considerai vossos caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Subi vós à montanha, trazei madeira, e reconstruí a casa; e dela me agradarei, e serei glorificado,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Esperastes por muito, e alcançastes pouco; e quando o trouxestes para casa, eu soprei nisso. Por que isto?,diz o SENHOR dos exércitos. Porque minha casa está deserta, e cada um de vós corre para sua própria casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Por isso que os céus detêm o orvalho de vós, e a terra detém seus frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'E chamei a seca sobre a terra, sobre os montes, sobre o trigo, sobre o suco de uva, sobre o azeite, e sobre tudo o que a terra produz, e sobre os homens sobre e os animais, e sobre todo trabalho manual.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Então Zorobabel filho de Sealtiel, Josué filho de Jeozadaque, sumo sacerdote, e todo o resto do povo, ouviram a voz do SENHOR seu Deus, e as palavras do profeta Ageu, como o SENHOR Deus deles havia o enviado; e o povo temeu diante do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Então Ageu, mensageiro do SENHOR, falou mensagem do SENHOR ao povo, dizendo: Eu estou convosco, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'E o SENHOR despertou o espírito de Zorobabel, filho de Sealtiel, governador de Judá, e o espírito de Josué filho de Jeozadaque, sumo sacerdote, e o espírito de todo o resto do povo; e vieram e começaram a obra na casa do SENHOR dos exércitos, Deus deles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'No vigésimo quarto dia do sexto mês, no segundo ano do rei Dario.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'No sétimo mês, no vigésimo primeiro dia mês, veio a palavra do SENHOR por meio do profeta Ageu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Fala agora a Zorobabel filho de Sealtiel, governador de Judá, e a Josué filho de Jeozadaque, sumo sacerdote, e ao resto do povo, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Quem restou dentre vós que tenha visto esta casa em sua primeira glória? E como a vedes agora? Não é esta como nada diante de vossos olhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Agora, pois, esforça-te, Zorobabel, diz o SENHOR; esforça-te também Josué, filho de Jeozadaque, sumo sacerdote; e esforça-te, todo o povo da terra, diz o SENHOR, e trabalhai; porque eu estou convosco, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Conforme o pacto que estabeleci convosco quando saístes do Egito, assim meu Espírito está em meio de vós; não temais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Porque assim diz o SENHOR dos exércitos: Ainda uma vez, daqui a pouco, eu farei tremer os céus e a terra, o mar e a terra seca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'E farei tremer a todas as nações, e virá as coisas preciosas de todas as nações; e encherei esta casa de glória, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Minha é a prata, e meu é o ouro, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'A glória desta última casa será maior que a da primeira, diz o SENHOR dos exércitos; e neste lugar darei paz, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Ao vigésimo quarto dia do nono mês, no segundo ano de Dario, veio a palavra do SENHOR por mão do profeta Ageu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Assim diz o SENHOR dos exércitos: Pergunta agora aos sacerdotes acerca da lei, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Se alguém levar carnes santas na borda de sua veste, e com sua borda tocar o pão, a comida, o vinho, o azeite, ou qualquer outra comida, por acaso isso será santificado?E os sacerdotes responderam: Não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'E Ageu disse: Se um impuro por causa de um corpo morto tocar alguma destas coisas, ela será impura? E os sacerdotes responderam: Impura será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Então Ageu respondeu: Assim é este povo, esta nação, diante de mim, diz o SENHOR; e assim é toda obra de suas mãos; e todo o que ali oferecem é impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Agora pois, considerai desde este dia em diante, antes que se ponha pedra sobre pedra no templo do SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Antes que fossem estas coisas, vinham ao amontoado de grão de vinte medidas,e obtinham somente dez; vinham ao lagar para tirar cinquenta vasos do lagar, mas obtinham somente vinte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Eu vos feri com ferrugem, mofo, e granizo em toda obra de vossas mãos; mas não vos convertestes a mim,diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Considerai, pois, isto, desde este dia em diante, desde o dia vigésimo quatro dia do nono mês, desde o dia em o fundamento do templo do SENHOR foi posto; considerai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Ainda há semente no celeiro? A videira, a figueira, a romeira, e oliveira ainda não têm dado frutos; mas a partir de hoje eu vos abençoarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'E a palavra do SENHOR veio pela segunda vez a Ageu, ao vigésimo quarto dia do mês, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Fala a Zorobabel, governador de Judá, dizendo: Eu farei tremer os céus e a terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'E transtornarei o trono dos reinos, e destruirei a força dos reinos das nações; e transtornarei as carruagens, e os que nelas se sentam; e os cavalos e os que neles montam cairão, cada um pela espada de seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Naquele dia, diz o SENHOR dos exércitos, eu te tomarei, Zorobabel, filho de Sealtiel, servo meu, diz o SENHOR, e te porei como anel de selar; porque eu te escolhi, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'No oitavo mês do segundo ano de Dario, a palavra do SENHOR veio ao profeta Zacarias, filho de Berequias, filho de Ido, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'O SENHOR se irou muito contra vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Portanto dize-lhes: Assim diz o SENHOR dos exércitos: Voltai-vos a mim, diz o SENHOR dos exércitos, e eu me voltarei a vós, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'E não sejais como vossos pais, aos quais os profetas antigos clamavam, dizendo: Assim diz o SENHOR dos exércitos: Convertei-vos de vossos maus caminhos e de vossos maus atos; porém não escutaram, nem me deram ouvidos, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Onde estão vossos pais? E os profetas, vivem eles para sempre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Porém quanto às minhas palavras e meus estatutos que havia mandado a meus servos os profetas, não alcançaram a vossos pais? Assim eles, arrependendo-se, diziam: Tal como o SENHOR dos exércitos planejou fazer segundo nossos caminhos e nossos antos, assim ele fez conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'No vigésimo quarto dia do décimo primeiro mês (que é o mês de Sebate), no ano segundo de Dario, a palavra do SENHOR veio ao profeta Zacarias, filho de Berequias, filho de Ido, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Vi de noite, e eis um homem montado sobre um cavalo vermelho, parado entre as murtas que estavam num vale profundo; e atrás dele estavam cavalos vermelhos, castanhos, e brancos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'E eu disse: Meu senhor, o que são estes? E o anjo que falava comigo me disse: Eu te mostrarei o que estes são.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Então o homem que estava entre os murtas respondeu, dizendo: Estes são os que o SENHOR enviou para andarem pela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'E eles responderam ao anjo do SENHOR que estava entre os murtas, e disseram: Nós já andamos pela terra, e eis que toda a terra está tranquila e quieta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Então o anjo do SENHOR disse: Ó SENHOR dos exércitos, até quando não terás compaixão de Jerusalém e das cidades de Judá, contra as quais ficaste irado estes setenta anos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'E o SENHOR respondeu ao anjo que falava comigo palavras boas, palavras de consolo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'E o anjo que falava comigo me disse: Fala em voz alta, dizendo: Assim diz o SENHOR dos exércitos: Tenho grande zelo por Jerusalém e por Sião;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'E tenho muito grande ira contra as nações tranquilas; porque eu estava pouco irado, porém elas pioraram o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Portanto assim diz o SENHOR: Eu me voltarei a Jerusalém com misericórdia; minha casa será reconstruída nela, diz o SENHOR dos exércitos, e a corda de medir será estendida sobre Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Fala em voz alta mais, dizendo: Assim diz o SENHOR dos exércitos: Minhas cidades novamente transbordarão de prosperidade; porque o SENHOR novamente consolará a Sião, e novamente escolherá a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Depois levantei meus olhos, e olhei, e eis que havia quatro chifres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'E perguntei ao anjo que falava comigo: O que são estes? E ele me disse: Estes são os chifres que dissiparam Judá, a Israel, e Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'E o SENHOR me mostrou quatro ferreiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Então eu disse: O que estes vêm a fazer? E ele falou, dizendo: Estes são os chifres que dispersaram Judá, de modo que ninguém levantava sua cabeça. Estes ferreiros vieram para derrubar os chifres das nações, que levantaram seus chifres contra a terra de Judá para dispersá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Voltei a levantar meus olhos, e olhei, e eis um homem que tinha em sua mão uma corda de medir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'E eu perguntei: Para onde vais? E ele me respondeu: Vou medir a Jerusalém, para ver quanta é sua largura e quanto é o seu comprimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'E eis que o anjo que falava comigo saiu, e outro anjo veio ao seu encontro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'E disse-lhe: Corre, fala a este rapaz, dizendo: Jerusalém será habitada sem muros por causa da multidão de pessoas e de animais que estarão no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'E eu, diz o SENHOR, serei seu muro de fogo ao redor, e serei sua glória no meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Ei! Ei! Fugi agora da terra do norte, diz o SENHOR, Porque eu vos espalhei pelos quatro ventos dos céu, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Ei Sião! Escapa-te tu, que habitas com a filha da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Porque assim diz o SENHOR dos exércitos: Foi por causa da glória que ele me enviou às nações que vos despojaram; porque quem vos toca, toca a menina de seu olho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Pois eis que levantarei minha mão contra eles, e serão saqueados por seus próprios servos, e sabereis que o SENHOR dos exércitos me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Canta e alegra-te, ó filha de Sião; porque eis que venho, e habitarei no meio de ti, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'E naquele dia muitas nações se ajuntarão ao SENHOR, e serão meu povo, e habitarei no meio de ti; e saberás que o SENHOR dos exércitos me enviou a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'E o SENHOR herdará a Judá como sua propriedade na terra santa, e novamente escolherá a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Calem-se todos diante do SENHOR, porque ele se levantou de sua santa morada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Depois ele me mostrou o sumo sacerdote Josué, que estava diante do anjo do SENHOR; e Satanás estava à sua direita para o acusar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Mas o SENHOR disse a Satanás: O SENHOR te repreenda, Satanás; o SENHOR, que escolheu a Jerusalém, te repreenda. Não é este homem um tição tirado do fogo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'E Josué estava vestido com roupas impuras enquanto estava diante do anjo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Então o anjo falou aos que estavam diante de dele, dizendo: Tirai dele essas roupas impuras. E a ele disse: Eis que tirei de ti tua perversidade, e te vestirei de roupas refinadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Depois disse: Ponham um turbante limpo sobre sua cabeça. E puseram um turbante limpo sobre sua cabeça, e puseram-lhe roupas, enquanto o anjo do SENHOR estava junto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'E o anjo do SENHOR exortou a Josué, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Assim diz o SENHOR dos exércitos: Se andares em meus caminhos, e guardares minha ordenança, também tu julgarás minha casa e guardarás meus pátios; e te darei passagem entre os que aqui estão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Ouvi, pois, Josué sumo sacerdote, tu, e teus colegas que se sentam diante de ti; porque são um sinal; pois eis que eu trarei a meu servo, o Renovo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Porque eis que, quanto à pedra que pus diante de Josué, sobre esta pedra há sete olhos; eis que gravarei nela uma inscrição, diz o SENHOR dos exércitos, e tirarei a injustiça desta terra em um dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Naquele dia, diz o SENHOR dos exércitos, cada um de vós convidará a seu próximo para debaixo da videira, e para debaixo da figueira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'E o anjo que falava comigo voltou e me despertou, tal como se desperta um homem de seu sono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'E ele me disse: O que vês? E eu respondi: Eis que vejo um castiçal de ouro maciço, com um recipiente de azeite sobre seu topo, e sete lâmpadas sobre ele; e cada uma das sete lâmpadas tinha um tubo em seu topo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'E duas oliveiras junto a ele, uma à direita do recipiente, e uma à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'E eu perguntei ao anjo que falava comigo, dizendo: Meu senhor, o que é isto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'E o anjo que falava comigo respondeu dizendo: Tu não sabes que é isto? E eu disse: Não, meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'E ele falou comigo, dizendo: Esta é palavra do SENHOR a Zorobabel, que diz: Não se fará por força, nem por violência, mas sim por meu espírito, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Quem és tu, montanha grande? Diante de Zorobabel se tornarás em planície; ele trará a pedra angular com gritos de: Graça! graça seja!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'E palavra do SENHOR veio a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'As mãos de Zorobabel fundaram esta casa, também suas mãos a completarão, para que saibais que o SENHOR dos exércitos me enviou a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Pois quem despreza o dia das pequenas coisas? Pois esses sete olhos se alegrarão ao verem o prumo na mão de Zorobabel (esses são os olhos do SENHOR, que passam por toda a terra).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'E eu respondi, perguntando: O que são as duas oliveiras à direita e à esquerda do castiçal?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'E também lhe perguntei: O que são aqueles dois ramos de oliveiras que estão de lado dos dois tubos de ouro que derramam azeite dourado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'E ele falou comigo, dizendo: Tu não sabes o que é isto? E eu disse: Não, meu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Então ele disse: Estes são os dois ungidos que estão diante do Senhor de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'E outra vez levantei meus olhos, e olhei, e eis um rolo que voava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'E ele me perguntou: O que vês? E eu disse: Vejo um rolo que voa, cujo comprimento é de vinte, e sua largura de dez côvados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Então me disse: Esta é a maldição que sairá por toda a face da terra, porque qualquer um que furtar (conforme está de um lado do rolo) será removido; e todo aquele que jura falsamente, (conforme está do outro lado do rolo) será removido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Eu a mando,diz o SENHOR dos exércitos, para que venha à casa do ladrão, e à casa do que jura falsamente pelo meu nome; e fique no meio de sua casa, e a destrua com suas colunas e suas pedras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'E o anjo que falava comigo veio e me disse: Levanta agora teus olhos, e vê o que é que está chegando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'E eu perguntei: O que é isto? E ele disse: Isto é um cesto de medir que está saindo.E disse mais: Este é o olho deles em toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'E eis que uma tampa de chumbo foi levantada, e uma mulher estava sentada no meio do cesto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'E ele disse: Esta é a Perversidade. E a lançou dentro do cesto, e lançou o peso de chumbo em sua abertura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'E levantei meus olhos, e vi, e eis que duas mulheres saíram, e havia vento sob suas asas (pois tinham asas como de cegonha), e levantaram o cesto entre a terra e o céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Então eu disse ao anjo que falava comigo: Para onde elas estão levando o cesto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'E ele me respondeu: Para lhe edificarem uma casa na terra de Sinar e, quando estiver pronta, e seja posto em sua base.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'E outra vez levantei meus olhos, e vi, e eis que quatro carruagens saíram dentre dois montes, e estes montes eram montes de bronze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Na primeira carruagem havia cavalos vermelhos, e na segunda carruagem cavalos pretos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'E na terceira carruagem cavalos brancos, e na quarto carruagem cavalos malhados. E os cavalos eram fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'E perguntei ao anjo que falava comigo: O que é isto, meu senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'E o anjo me respondeu: Estes são os quatro espíritos dos céus, que saem de onde estavam diante do Senhor de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'A carruagem em que estão os cavalos pretos vai para a terra do norte; os brancos vão atrás deles, e os malhados vão para a terra do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'E os fortes cavalos saíram, e procuraram ir a andarem pela terra. E ele disse: Ide, andai pela terra. E eles andaram pela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'E ele me chamou, e falou comigo, dizendo: Eis que aqueles que foram para a terra do norte fizeram descansar meu Espírito na terra do norte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'E a palavra do SENHOR veio a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Toma dos que foram levados cativos: Heldai, e de Tobias, e de Jedaías, que voltaram da Babilônia; e naquele mesmo dia vem, e entra na casa de Josias, filho de Sofonias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Toma prata e ouro, e faze coroas, e põe sobre a cabeça do sumo sacerdote Josué, filho de Jeozadaque;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'E fala com ele, dizendo: Assim diz o SENHOR dos exércitos: Eis aqui o homem cujo nome é Renovo; ele brotará de seu lugar, e edificará o templo do SENHOR;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ele mesmo edificará o templo do SENHOR, e levará sobre si majestade; e se sentará e dominará em seu trono, e será sacerdote em seu trono; e haverá conselho de paz entre ambos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'E as coroas serão para Helem, Tobias, e Jedaías, e Hem, filho de Sofonias, como memorial no templo do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'E os que estão longe virão e participarão da construção do templo do SENHOR, e vós sabereis que o SENHOR dos exércitos me enviou a vós. Isto acontecerá se verdadeiramente ouvirdes à voz do SENHOR vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Aconteceu, pois, no quarto ano do rei Dario, que a palavra do SENHOR veio a Zacarias noquarto dia do nono mês, que é Quisleu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Quando os de Betel enviaram Sarezer e Regém-Meleque e seus homens, para suplicarem o favor do SENHOR,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'E para dizerem aos sacerdotes que estavam na casa do SENHOR dos exércitos e aos profetas o seguinte: Devemos chorar e jejuar no quinto mês, como já temos feito há tantos anos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Então a palavra do SENHOR dos exércitos veio a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Fala a todo o povo desta terra, e aos sacerdotes, dizendo: Quando jejuastes e chorastes no quinto e no sétimo mês durante estes setenta anos, por acaso jejuastes verdadeiramente para mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'E quando comeis e bebeis, não foi para vós que comeis e bebeis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Não são estas as palavras que o SENHOR pregou por meio dos antigos profetas, quando Jerusalém estava habitada e tranquila, com suas cidades ao seu redor, e o Sul e a campina eram habitadas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'E a palavra do SENHOR veio a Zacarias, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Assim falou o SENHOR dos exércitos, dizendo: Julgai juízo verdadeiro, e praticai piedade e misericórdia cada um com seu irmão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Não oprimais à viúva, nem ao órfão, nem ao estrangeiro, nem ao pobre; e ninguém planeje o mal em seu coração contra seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Porém não quiseram prestar atenção; ao invés disso deram as costas e taparam suas orelhas para não ouvirem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'E fizeram seus corações duros como diamante, para não ouvirem a Lei nem as palavras que o SENHOR dos exércitos enviou por seu Espírito através dos antigos profetas; por isso veio grande ira da parte do SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Por causa disso, tal como eles não ouviram quando eu clamei, assim tamb em quando eles clamaram eu não ouvi,diz o SENHOR dos exércitos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'E eu os espalhei com turbilhão entre todas as nações, que eles não conheciam, e a terra foi assolada atrás deles, de maneira que ninguém passava por ela, nem voltava; porque tornaram a terra desejada em ruínas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Depois veio a palavra do SENHOR dos exércitos, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Assim diz o SENHOR dos exércitos: Tenho grande zelo por Sião, e com grande furor zelo por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Assim diz o SENHOR: Eu voltarei a Sião, e habitarei no meio de Jerusalém. E Jerusalém será chamada Cidade da Verdade, e o monte do SENHOR dos exércitos, Monte Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Assim diz o SENHOR dos exércitos: Novamente idosos e idosas se sentarão nas praças de Jerusalém, e cada um terá seu bordão em sua mão, por causa da abundância de dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'E as ruas da cidade se encherão de meninos e meninas, brincando em suas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Assim diz o SENHOR dos exércitos: Se isto era extraordinário demais aos olhos do restante do povo naqueles dias, seria também extraordinário demais aos meus olhos? Diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Assim disse o SENHOR dos exércitos: Eis que salvarei o meu povo da terra do oriente, e da terra do ocidente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Eu os trarei, e habitarão no meio de Jerusalém; e eles serão meu povo, e eu serei o Deus deles em verdade e em justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Assim diz o SENHOR dos exércitos: Sejam fortes vossas mãos, vós que nestes dias ouvistes estas palavras da boca dos profetas que estiveram no dia em que foi posto o fundamento da casa do SENHOR dos exércitos, para que o templo fosse edificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Porque antes daqueles dias não houve salário para homem, nem salário para animal, e o que entrava e o que saía não tinha paz por causa do inimigo, porque eu mandei a todos, cada um contra seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Mas agora com o resto deste povo não farei como nos dias passados, diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Porque a semente será próspera, a vide dará seu fruto, a terra dará seu produto, e os céus darão seu orvalho; e farei o resto deste povo herdar tudo isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'E será, ó casa de Judá e casa de Israel, que, assim como fostes maldição entre as nações, assim também eu vos salvarei, e sereis bênção. Não temais, fortaleçam-se vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Porque assim diz o SENHOR dos exércitos: Assim como eu pensei vos fazer o mal quando vossos pais me provocaram à ira, diz o SENHOR dos exércitos, e não me arrependi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Assim também voltei a pensar em fazer o bem a Jerusalém e à casa de Judá nestes dias; não temais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Estas são as coisas que deveis fazer: falai verdade cada qual com seu próximo; julgai em vossas portas verdade e juízo de paz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'E ninguém planeje o mal em seu coração contra seu próximo, nem ameis o juramento falso; porque eu odeio todas estas coisas, diz o SENHOR');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'E a palavra do SENHOR dos exércitos veio a mim, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Assim diz o SENHOR dos exércitos: O jejum do quarto, do quinto, do sétimo, e do décimo mês, se voltarão à casa de Judá serão para prazer e alegria, e para festividades solenes. Amai, pois, a verdade e a paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Assim diz o SENHOR dos exércitos: Ainda será que povos e moradores de muitas cidades virão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'E irão os moradores de uma cidade à outra, dizendo: Vamos suplicar o favor do SENHOR, e buscar ao SENHOR dos exércitos. Eu também irei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Assim muitos povos e poderosas nações virão para buscar ao SENHOR dos exércitos em Jerusalém, e suplicar o favor do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Assim diz o SENHOR dos exércitos: Naqueles dias será que dez homens de todas as línguas das nações, pegarão na orla da veste de um judeu, dizendo: Iremos convosco, porque temos ouvido que Deus está convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Revelação da palavra do SENHOR contra terra de Hadraque e de Damasco, seu repouso; porque os olhos da humanidade e de todas as tribos de Israel estão voltados ao SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'E também contra Hamate que faz fronteira com ela; Tiro e Sidom, ainda que seja muito sábia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tiro edificou para si fortalezas, e amontoou prata como pó da terra, e ouro como lama das ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Eis que o Senhor a desapossará, e no mar ferirá sua fortaleza, e ela será consumida pelo fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Asquelom verá, e temerá; Gaza também, e terá grande dor; assim como Ecrom, pois aquilo em que confiavam se envergonhará; o rei de Gaza perecerá, e Asquelom não será habitada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'E um povo misturado habitará em Asdode, e eu acabarei com a arrogância dos filisteus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'E tirarei seu sangue de sua boca, e suas abominações dentre seus dentes; porém os que restarem serão para nosso Deus, e serão como príncipes em Judá; e Ecrom será como o jebuseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'E me acamparei ao redor de minha casa contra o exército inimigo,para que não passe nem volte; para que o opressor não passe mais por eles; porque agora eu vi com meus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Alegra-te muito, ó filha de Sião; dá vozes de júbilo, ó filha de Jerusalém; eis que teu rei virá a ti, justo e salvador, humilde, e montado sobre um asno, sobre um jumentinho, filho de jumenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'E destruirei as carruagens de Efraim, e os cavalos de Jerusalém; os arcos de guerra também serão quebrados; e ele falará paz às nações; e seu domínio será de mar a mar, e desde o rio até os confins da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Quanto a ti, pelo sangue de teu pacto, eu libertei teus prisioneiros da cova em que não havia água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Voltai-vos à fortaleza, ó prisioneiros que tendes esperança; hoje também vos anuncio que vos recompensarei em dobro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Pois encurvarei a Judá para mim como arco, porei a Efraim como flecha; e despertarei teus filhos, ó Sião, contra teus filhos, ó Grécia; e farei de ti, Sião, como espada de guerreiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'E o SENHOR será visto acima deles, e sua flecha sairá como relâmpago; o Senhor DEUS tocará trombeta, e irá como os turbilhões do sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'O SENHOR dos exércitos os protegerá, e eles consumirão, e sujeitarão com pedras da funda; também beberão e farão gritarias como bêbados de vinho; e se encherão como a bacia de sacrifício, ou como os cantos do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'E o SENHOR, Deus deles, os salvará naquele dia como o rebanho de seu povo; porque serão como pedras de coroa, erguidas na terra dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Pois como será grande sua prosperidade, e tamanha sua beleza! O trigo fortalecerá os rapazes, e o suco de uva as virgens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Pedi, vós, ao SENHOR chuva no tempo da chuva tardia; o SENHOR faz relâmpagos, e lhes dará chuva abundante, e erva no campo a cada um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Pois os ídolos falam ilusão, e os adivinhos veem falsidade, e falado sonhos ilusórios; com ilusão consolam; por isso eles foram embora como ovelhas, humilhadas, porque não havia pastor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Minha ira se acendeu contra os pastores, e castigarei os bodes; mas o SENHOR dos exércitos visitará seu rebanho, a casa de Judá, e fará com que sejam como seu cavalo de honra na batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'De ele sairá a pedra angular, a estaca, e o arco da guerra; dele juntamente sairá todo dominador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'E serão como guerreiros que pisam o inimigo na lama das ruas na batalha; e lutarão, porque o SENHOR estará com eles; e envergonharão aos que montam em cavalos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'E eu fortalecerei a casa de Judá, e salvarei a casa de José; e voltarei a estabelecê-los, porque me compadeci deles; e serão como se eu não tivesse os rejeitado, porque eu sou o SENHOR, Deus deles, que os ouvirei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'E Efraim será como guerreiro, e seu coração se alegrará como de vinho; seus filhos verão, e ficarão contentes; seus corações se alegrarão no SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Eu assoviarei a eles, e os ajuntarei, porque eu os resgatarei; e serão muitos assim como eram muitos no passado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'E eu os semearei entre os povos, e se lembrarão de mim em lugares remotos; e viverão com seus filhos, e voltarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Eu os trarei de volta da terra do Egito, e os recolherei da Assíria; e os trarei à terra de Gileade e do Líbano, mas não será espaço suficiente para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Ele passará pela mar da aflição, ferirá as ondas do mar, e todas as profundezas do rio se secarão; e a arrogância dos assírios será derrubada, e o cetro do Egito será tomado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'E eu os fortificarei no SENHOR, e andarão em seu nome, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Abre tuas portas, ó Líbano, para que o fogo consuma teus cedros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Lamenta, ó cipreste, porque o cedro caiu, porque os maiorais foram destruídos. Lamentai, ó carvalhos de Basã, porque o forte bosque foi derrubado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Ouve-se voz de lamentação de pastores, porque sua glória foi destruída; ouve-se voz dos bramidos de leões jovens, porque a arrogância do Jordão foi destruída.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Assim diz o SENHOR meu Deus: Apascenta as ovelhas da matança,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Cujos compradores as matam, e ninguém os considera culpados; e os que as vendem dizem: Bendito seja o SENHOR, porque estou rico; nem seus pastores se compadecem delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Certamente não mais pouparei os moradores da terra,diz o SENHOR; mas eis que eu entregarei os homens, cada um na mão de seu próximo, e em mão de seu rei; e despedaçarão esta terra, e eu não os livrarei de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Então eu apascentei as ovelhas da matança, as pobres do rebanho. E tomei para mim duas varas; a uma chamei Agrado e à outra chamei União; e apascentei as ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'E acabei com três pastores em um mês, pois minha alma estava impaciente com eles, e também a almas deles me odiavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'E eu disse: Não vos apascentarei; a que morrer, morra; e a que se perder, se perca; e as que restarem, que uma devore a carne da outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'E peguei minha vara Agrado, e a quebrei, para desfazer meu pacto que tinha estabelecido com todos os povos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Assim foi desfeito naquele dia, e assim as pobres do rebanho que me observavam reconheceram que isto era palavra do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Pois eu havia lhes dito: Se vos parece bem aos vossos olhos, dai-me meu salário; e se não, deixai-o. E pesaram meu salário: trinta moedas de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'O SENHOR, pois, me disse: Lança-as ao oleiro, este belo preço que me avaliaram.E tomei as trinta moedas de prata, e as lancei na casa do SENHOR ao oleiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Então quebrei logo minha segunda vara União, rompendo a fraternidade entre Judá e Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'E o SENHOR me disse mais: Toma ainda para ti os instrumentos de um pastor insensato;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Porque eis que eu levantarei um pastor na terra, que não cuidará das perdidas, não buscará a pequena, não tratará de curar a que estiver machucada, nem apascentará a sã; em vez disso, ele comerá a carne da que estiver gorda, e quebrará suas unhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Ai do pastor inútil, que desampara o rebanho! Espada virá contra seu braço, e contra seu olho direito; seu braço se secará por completo, e seu olho direito será obscurecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Revelação da palavra do SENHOR sobre Israel: O SENHOR, que estende o céu, e funda a terra, e forma o espírito do ser humano em seu interior, diz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Eis que eu farei de Jerusalém um copo de cambalear a todos os povos de ao redor; e também será sobre Judá, durante o cerco contra Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'E será naquele dia, que farei de Jerusalém uma pedra pesada a todos os povos; todos os que a carregarem serão seriamente feridos, ainda que todas as nações da terra se ajuntarão contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Naquele dia,diz o SENHOR, ferirei com espanto a todo cavalo, e com loucura ao cavaleiro; mas sobre a casa de Judá abrirei meus olhos, e a todo cavalo dos povos ferirei com cegueira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Então os líderes de Judá dirão em seu coração: Os moradores de Jerusalém serão minha força no SENHOR dos exércitos seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Naquele dia farei dos líderes de Judá como um braseiro de fogo debaixo da lenha, e como tocha de fogo debaixo de gravetos; e consumirão todos os povos ao redor à direita e à esquerda; e Jerusalém continuará habitada em seu lugar, em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'E o SENHOR salvará primeiramente as tendas de Judá, para que a glória da casa de Davi e a glória dos moradores de Jerusalém não se exaltem sobre Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Naquele dia o SENHOR defenderá os moradores de Jerusalém; e o que mais fraco dentre eles, naquele dia será como Davi; e a casa de Davi será como Deus, como o anjo do SENHOR diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'E será naquele dia que eu buscarei destruir todas as nações que vierem contra Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Porém sobre a casa de Davi e sobre os moradores de Jerusalém derramarei o Espírito de graça e de orações; e olharão a mim, a quem traspassaram; e farão pranto sobre ele, como pranto da morte de filho único; e chorarão amargamente por causa dele, tal como se chora pelo primogênito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Naquele dia haverá grande pranto em Jerusalém, como o pranto de Hadade-Rimom no vale de Megido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'E a terra prateará, cada família por si só; a família da casa de Davi por si, e suas mulheres por si; a família da casa de Natã por si, e suas mulheres por si;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'A família da casa de Levi por si, e suas mulheres por si; a família de Simei por si, e suas mulheres por si;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Todos as demais famílias, cada família por si, e suas mulheres por si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Naquele dia haverá uma fonte aberta para a casa de Davi e para os moradores de Jerusalém, contra o pecado e a impureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'E será naquele dia,diz o SENHOR dos exércitos, que eliminarei da terra os nomes dos ídolos, de modo nunca mais serão lembrados; e também eliminarei da terra os profetas e o espírito impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'E será que, quando alguém vier a profetizar, seu pai e sua mãe que o geraram lhe dirão: Não viverás, porque tens falado mentira no nome do SENHOR; e seu pai e sua mãe que o geraram o traspassarão quando profetizar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'E será naquele dia, que os profetas se envergonharão, cada um de sua visão, quando profetizarem; e nunca mais se vestirão de manto de pelos para mentir');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Em vez disso, dirá: Não sou profeta; sou lavrador da terra, porque fui feito servo de um homem desde minha juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'E se lhe perguntarem: Que feridas são estas em tuas mãos? Ele responderá: Com elas fui ferido na casa de meus amigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Desperta-te, ó espada, contra o pastor e contra o homem que é companheiro,diz o SENHOR dos exércitos. Fere ao pastor, e as ovelhas se dispersarão; e voltarei minha mão sobre os pequenos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'E será em toda a terra,diz o SENHOR, que as duas partes serão exterminadas nela, e perecerão; mas a terceira parte restará nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'E porei esta terceira parte no fogo, e a refinarei como se refina a prata; e eu os provarei como se prova o ouro. Eles invocarão o meu nome, e eu lhes ouvirei; direi: São meu povo; e eles dirão: O SENHOR é meu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Eis que vem o dia do SENHOR, e teus despojos serão repartidos no meio de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Porque eu ajuntarei todas as nações em batalha contra Jerusalém; e a cidade será tomada, as casas serão saqueadas, e as mulheres forçadas; e a metade da cidade irá em cativeiro, mas o restante do povo não será exterminado da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Então o SENHOR virá, e lutará contra essas nações, como ele lutou no dia da batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'E naquele dia seus pés estarão sobre o monte das Oliveiras, que está em frente de Jerusalém ao oriente; e o monte das Oliveiras se fenderá por meio para oriente e para o ocidente, fazendo um vale muito grande; e metade do monte se moverá ao norte, e a outra metade ao sul.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Então fugireis pelo vale dos montes (porque o vale dos montes chegará até Azal); e fugireis como fugistes por causa do terremoto nos dias de Uzias, rei de Judá; então o SENHOR meu Deus virá, e todos os santos contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'E será naquele dias, que não haverá luz clara, nem espessa escuridão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'E será um dia que, o SENHOR sabe como, não será dia nem noite; mas acontecerá no tempo do anoitecer haverá luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Naquele dia também acontecerá, que de Jerusalém correrão águas vivas, a metade delas para o mar oriental, e a outra ao mar ocidental, tanto no verão como no inverno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'E o SENHOR será rei sobre toda a terra. Naquele dia o SENHOR será um, e seu nome um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'E toda esta terra se tornará como planície desde Geba até Rimom, ao sul de Jerusalém; porém esta será elevada, e habitada em seu lugar, desde a porta de Benjamim até o lugar da primeira porta, até a porta da esquina; e desde a torre de Hananel até os lagares do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'E habitarão nela, e nunca mais haverá maldição sobre ela; porque Jerusalém habitará em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'E esta será a praga com que o SENHOR ferirá a todos os povos que guerrearam contra Jerusalém: a carne deles se apodrecerá estando eles sobre seus pés, seus olhos se apodrecerão em suas órbitas, e sua língua se lhes apodrecerá em sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Naquele dia também acontecerá que haverá grande tumulto do SENHOR entre eles; por isso cada um pegará na mão de seu próximo, e sua mão se levantará contra a mão de seu próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'E Judá também lutará em Jerusalém. E a riqueza de todas as nações de ao redor será ajuntada: ouro, prata, e roupas, em grande abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Assim também como esta praga, será a praga para os cavalos, os jumentos, os camelos, os asnos, e todos os animais que estiverem naqueles acampamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'E será que, todos os que restarem de todas as nações que vieram contra Jerusalém subirão de ano em ano para adorarem ao rei, o SENHOR dos exércitos, e a celebrarem a festa dos tabernáculos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'E acontecerá que, se alguma das famílias da terra não subir a Jerusalém para adorar ao rei, o SENHOR dos exércitos, não virá chuva sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'E se a família do Egito não subir, e não vier, não virá chuva sobre eles; virá a praga com que o SENHOR ferirá as nações que não subirem para celebrar a festa dos tabernáculos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Esta será a punição pelo pecado do Egito, e pelo pecado de todas as nações que não subirem para celebrar a festa dos tabernáculos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Naquele tempo sobre as sinos dos cavalos estará: CONSAGRADO AO SENHOR; e as panelas na casa do SENHOR serão como as bacias diante do altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'E todas as panelas em Jerusalém e em Judá serão consagradas ao SENHOR dos exércitos, de modo que todos os que sacrificarem, virão e delas tomarão, e nelas cozerão; e naquele dia não haverá mais cananeu algum na casa do SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Revelação da palavra do SENHOR a Israel, por meio de Malaquias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Eu vos tenho amado,diz o SENHOR; mas vos dizeis: Em que nos amaste? Não era Esaú irmão de Jacó?, diz o SENHOR, todavia amei a Jacó,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'E odiei a Esaú; e tornei seus montes em desolação, e sua herança para os chacais do deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Ainda que Edom diga: Fomos devastados, mas voltaremos a edificar as ruínas; assim diz o SENHOR dos exércitos: Eles edificarão, e eu destruirei; e serão chamados de “território da perversidade” e “povo contra quem o SENHOR está irado para sempre”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'E vossos olhos verão, e direis: Seja o SENHOR engrandecido até além do território de Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'O filho honra ao pai, e o servo a seu senhor; se pois sou eu pai, onde está minha honra? E se sou senhor, onde está o temor a mim?,diz o SENHOR dos exércitos a vós, sacerdotes, que desprezais o meu nome. Mas vós dizeis: Em que temos desprezado o teu nome?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Quando trazeis sobre meu altar pão contaminado. E dizeis: Em que te contaminamos? Quando dizeis: A mesa do SENHOR é desprezível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'E quando trazeis animal cego para o sacrifício, isso não é mal? E quando trazeis o aleijado ou o enfermo, isso não é mal? Apresenta isso a teu governador; por acaso ele se agradará de ti, ou ele te aceitará? diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Agora pois, suplicai o favor de Deus que ele tenha compaixão de nós; será, por acaso, que com isto que tendes feito por vossas mãos, ele vos aceitará?,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Quem, pois, há de vós que feche as portas? Pelo menos assim vós não acenderíeis o fogo de meu altar em vão! Eu não tenho prazer em vós,diz o SENHOR dos exércitos, e não me agrado da oferta de vossas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Pois desde o oriente até o ocidente o meu nome será grande entre as nações; e em todo lugar se oferecerá a meu nome incenso e oferta pura; porque meu nome será grande entre as nações,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Mas vós o profanais quando dizeis: A mesa do SENHOR está contaminada; e seu produto, o alimento, é desprezível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Além disso, dizeis: É cansativo demais! E o desprezais, diz o SENHOR dos exércitos; vós trazeis o roubado, o aleijado, e o enfermo, e trazeis a oferta. Por acaso aceitaria isso de vossas mãos?, diz o SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Maldito seja o mentiroso, que tem macho em seu rebanho, e promete, mas sacrifica o defeituoso ao SENHOR; pois eu sou o Grande Rei,diz o SENHOR dos exércitos, e meu nome é temível entre as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Agora pois, ó sacerdotes, este mandamento é para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Se não o ouvirdes, e se não guardardes no coração de dar glória a meu nome,diz o SENHOR dos exércitos, enviarei maldição sobre vós, e amaldiçoarei vossas bênçãos. Aliás, eu já as tenho amaldiçoado, porque não tendes guardado isso no vosso coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Eis que eu repreenderei a vossa semente, e espalharei lixo sobre os vossos rostos, o lixo de vossas festas, e com ele sereis removidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Então sabereis que eu vos enviei este mandamento, para que meu pacto seja com Levi,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Meu pacto foi com ele de vida e de paz, as quais eu lhe dei para haver temor; e ele me temeu, e teve medo diante de meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'A lei de verdade estava em sua boca, e não se achou injustiça em seus lábios; ele andava comigo em paz e em justiça, e converteu a muitos da maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Porque os lábios do sacerdote devem guardar o conhecimento, e de sua boca devem buscar a lei; porque ele é mensageiro do SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mas vós vos desviastes do caminho; fizestes tropeçar a muitos na lei; corrompestes o pacto de Levi,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Por isso eu também vos tornei desprezíveis e indignos diante de todo o povo, visto que não guardais meus caminhos, e na lei fazeis acepção de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Não temos todos um mesmo Pai? Não foi um mesmo Deus que nos criou? Por que, então, traímos cada um a seu irmão, profanando o pacto de nossos pais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Judá tem agido com traição, e abominação se comete em Israel e em Jerusalém; porque Judá profana o santuário do SENHOR, o qual ele ama, e se casou com filha de deus estranho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'O SENHOR removerá das tendas de Jacó ao homem que fizer isto, ao que vela, e ao que responde, e ao que traz oferta ao SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Também fazeis esta segunda coisa: cobris o altar do SENHOR de lágrimas, de pranto, e de gemidos; por isso ele não dará mais atenção à oferta, nem a aceitará com prazer de vossa mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Vós dizeis: Por que razão? Porque o SENHOR foi testemunha entre ti e a mulher de tua juventude, contra a qual tu tens traído, sendo ela a tua companheira, e a mulher de teu pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'E não fez ele somente um ainda que lhe sobre o espírito? E por que um? Para buscar uma descendência de Deus. Guardai-vos pois em vosso espírito, e ninguém de vós seja infiel à mulher de vossa juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Porque o SENHOR Deus de Israel diz que ele odeia o divórcio, e quem cobre a sua roupa de violência, diz o SENHOR dos exércitos. Guardai-vos pois em vosso espírito, e não sejais infiéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Cansais ao SENHOR com vossas palavras. E ainda dizeis: Em que nós o cansamos? Quando dizeis: Qualquer um que faz o mal é bom aos olhos ao SENHOR, que se agrada deles; ou: Onde está o Deus do juízo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Eis que eu enviarei o meu mensageiro, que preparará o caminho adiante de mim; e de repente virá a seu templo o Senhor a quem vós buscais, o mensageiro do pacto a quem vós desejais. Eis que ele vem,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mas quem poderá suportar o dia de sua vinda? Quem conseguirá ficar de pé quando ele aparecer? Porque ele será como fogo do ourives, e como o sabão de lavandeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'E ele se sentará como refinador e purificador da prata; pois ele limpará os filhos de Levi, e os refinará como o ouro e como a prata; então trarão ao SENHOR oferta com justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'E a oferta de Judá e de Jerusalém será suave ao SENHOR, como nos dias antigos, e como nos anos passados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'E eu me achegarei a vós para o julgamento; e prontamente serei testemunha contra os feiticeiros e adúlteros, e contra os que juram falsamente, e os que oprimem o empregado em seu salário, a viúva, e o órfão, e pervertem o direito do estrangeiro, e não me temem,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Porque eu o SENHOR, não me mudo; por isso que vós, filhos de Jacó, não sois consumidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Desde os dias de vossos pais vos desviastes de minhas leis, e não as guardastes. Voltai-vos a mim, e eu me voltarei a vós,diz o SENHOR dos exércitos. Mas vós dizeis: Em que temos de voltar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Pode o ser humano roubar a Deus? Vós, pois, me roubais. Mas vós dizeis: Em que te roubamos? Nos dízimos e nas ofertas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Com maldição sois amaldiçoados porque vós me roubais, toda a nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Trazei todos os dízimos à casa do tesouro, para que haja alimento em minha casa; e provai-me nisto, diz o SENHOR dos exércitos, se não vos abrir as janelas dos céu, e derramar sobre vós bênção transbordante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'E por causa de vós repreenderei ao devorador, para não corrompa vosso fruto da terra; e vossa vide no campo não será estéril,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'E todas as nações vos chamarão bem-aventurados; porque vós sereis terra agradável,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Vossas palavras têm sido duras contra mim,diz o SENHOR. Mas vós dizeis: O que temos falado contra ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Vós dizeis: É inútil servir a Deus; pois que proveito temos tido em guardarmos seus mandamentos e andarmos lamentando diante do SENHOR dos exércitos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Chamemos de sortudos os soberbos, pois os que praticam perversidade prosperam; mesmo tentando a Deus, eles escapam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Então aqueles que temeram ao SENHOR falaram cada um a seu próximo, e o SENHOR prestou atenção e ouviu; e foi escrito um livro de memória diante dele para os que temem ao SENHOR, e para os que se honraram o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'E eles serão minha propriedade especial no dia que eu preparo,diz o SENHOR dos exércitos; e os pouparei como o homem que poupa a seu filho que lhe serve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Então voltareis a ver a diferença entre o justo e o perverso, entre o que serve a Deus e o que não lhe serve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Porque eis que aquele dia vem ardendo como forno; e todos os soberbos e todos os que praticam perversidade serão palha; e o dia que vem os incendiará,diz o SENHOR dos exércitos, de tal maneira que não lhes deixará nem raiz nem ramo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Mas a vós os que temeis meu nome, o Sol da justiça nascerá, e trará cura em suas asas; e saireis, e saltareis de alegria como bezerros do estábulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'E esmagareis os perversos, os quais serão cinza debaixo das plantas de vossos pés, no dia que eu preparo,diz o SENHOR dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Lembrai-vos da lei de meu servo Moisés, que lhe mandei em Horebe estatutos e regras para todo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Eis que eu vos envio o profeta Elias, antes que venha o grande e temível dia do SENHOR.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Ele converterá o coração dos pais aos filhos, e o coração dos filhos aos pais; para que não seja que eu venha e fira a terra com maldição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Livro da geração de Jesus Cristo, filho de Davi, filho de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraão gerou a Isaque; e Isaque gerou a Jacó; e Jacó gerou a Judá e a seus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'E Judá gerou de Tamar a Perez e a Zerá; e Perez gerou a Esrom, e Esrom gerou a Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'E Arão gerou a Aminadabe; e Aminadabe gerou a Naassom; e Naassom gerou a Salmom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'E Salmom gerou de Raabe a Boaz; e Boaz gerou de Rute a Obede; e Obede gerou a Jessé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'E Jessé gerou ao rei Davi; e o rei Davi gerou Salomão da que fora mulher de Urias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'E Salomão gerou a Roboão; e Roboão gerou a Abias; e Abias gerou a Asa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'E Asa gerou a Josafá; e Josafá gerou a Jorão; e Jorão gerou a Uzias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'E Uzias gerou a Jotão; e Jotão gerou a Acaz; e Acaz gerou a Ezequias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'E Ezequias gerou a Manassés; e Manassés gerou a Amom; e Amom gerou a Josias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'E Josias gerou a Jeconias, e a seus irmãos no tempo do exílio babilônico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'E depois do exílio babilônico Jeconias gerou a Salatiel; e Salatiel gerou a Zorobabel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'E Zorobabel gerou a Abiúde; e Abiúde gerou a Eliaquim; e Eliaquim gerou a Azor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'E Azor gerou a Sadoque; e Sadoque gerou a Aquim; e Aquim gerou a Eliúde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'E Eliúde gerou a Eleazar; e Eleazar gerou a Matã; e Matã gerou a Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'E Jacó gerou a José, o marido de Maria, da qual nasceu Jesus, chamado o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'De maneira que todas as gerações desde Abraão até Davi são catorze gerações; e desde Davi até o exílio babilônico catorze gerações; e desde o exílio babilônico até Cristo catorze gerações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'E o nascimento de Jesus Cristo foi assim: estando sua mãe Maria desposada com José, antes que se ajuntassem, ela foi achada grávida do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Então José, seu marido, sendo justo, e não querendo a expor à infâmia, pensou em deixá-la secretamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'E ele, pretendendo isto, eis que um anjo do Senhor lhe apareceu em sonho, dizendo: José, filho de Davi, não temas receber Maria, tua mulher, porque o que nela está concebido é do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'E ela dará à luz um filho, e tu chamarás seu nome Jesus; porque ele salvará seu povo de seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'E tudo isto aconteceu para que se cumprisse o que foi dito pelo Senhor por meio do profeta, que disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Eis que a virgem conceberá, e dará à luz um filho, e chamarão seu nome Emanuel, que traduzido é: Deus conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'E despertando José do sonho, fez como o anjo do Senhor tinha lhe mandado, e recebeu sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'E ele não a conheceu intimamente,até que ela deu à luz o filho dela, o primogênito, e lhe pôs por nome JESUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'E sendo Jesus já nascido em Belém da Judeia, nos dias do rei Herodes, eis que vieram uns magos do oriente a Jerusalém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Dizendo: Onde está o Rei nascido dos Judeus? Porque vimos sua estrela no oriente, e viemos para adorá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'E o rei Herodes, ao ouvir isto, ficou perturbado, e com ele toda Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'E tendo reunido todos os chefes dos sacerdotes e escribas do povo, perguntou-lhes onde o Cristo havia de nascer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'E eles lhe disseram: Em Belém da Judeia, porque assim está escrito pelo profeta:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'E tu Belém, terra de Judá, de maneira nenhuma és a menor entre as lideranças de Judá, porque de ti sairá o Guia que apascentará meu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Então Herodes, chamando secretamente os magos, perguntou-lhes com precisão sobre o tempo em que a estrela havia aparecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'E enviando-os a Belém, disse: Ide, e investigai cuidadosamente pelo menino; e quando o achardes, avisai-me, para que também eu venha e o adore.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Depois de ouvirem o rei, eles foram embora. E eis que a estrela que tinham visto no oriente ia adiante deles, até que ela chegou, e ficou parada sobre onde o menino estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'E eles, vendo a estrela, jubilaram muito com grande alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'E entrando na casa, acharam o menino com sua mãe Maria, e prostrando-se o adoraram. E abrindo seus tesouros, ofereceram-lhe presentes: ouro, incenso, e mirra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'E sendo por divina revelação avisados em sonho que não voltassem a Herodes, partiram para sua terra por outro caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'E tendo eles partido, eis que um anjo do Senhor apareceu a José em sonho, dizendo: Levanta-te, toma o menino e sua mãe, e foge para o Egito; e fica lá até que eu te diga, porque Herodes buscará o menino para o matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Então ele se despertou, tomou o menino e sua mãe de noite, e foi para o Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'E esteve lá até a morte de Herodes, para que se cumprisse o que foi dito pelo Senhor por meio do profeta, que disse: Do Egito chamei o meu Filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Então Herodes, ao ver que tinha sido enganado pelos magos, irou-se muito, e mandou matar todos os meninos em Belém e em todos os limites de sua região, da idade de dois anos e abaixo, conforme o tempo que tinha perguntado com precisão dos magos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Então se cumpriu o que foi dito pelo profeta Jeremias, que disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Uma voz se ouviu em Ramá, lamentação, choro, e grande pranto; Raquel chorava por seus filhos, e não quis ser consolada, pois já não existem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Mas depois de Herodes ter morrido, eis que um anjo do Senhor apareceu no Egito a José em sonho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Dizendo: Levanta-te, toma o menino e sua mãe, e vai para a terra de Israel, porque já morreram os que procuravam a morte do menino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Então ele se levantou, tomou o menino e sua mãe, e veio para a terra de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Porém ao ouvir que Arquelau reinava na Judeia em lugar de seu pai Herodes, ele teve medo de ir para lá; mas avisado por divina revelação em sonho, foi para a região da Galileia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'E veio a habitar na cidade chamada Nazaré, para que se cumprisse o que foi dito pelos profetas, que: Ele será chamado de Nazareno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'E naqueles dias veio João Batista, pregando no deserto da Judeia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'E dizendo: Arrependei-vos, porque perto está o Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Porque este é aquele que foi declarado pelo profeta Isaías, que disse: Voz do que clama no deserto: “Preparai o caminho do Senhor; endireitai suas veredas”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Este João tinha sua roupa de pelos de camelo e um cinto de couro ao redor de sua cintura, e seu alimento era gafanhotos e mel silvestre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Então vinham até ele moradores de Jerusalém, de toda a Judeia, e de toda a região próxima do Jordão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'E eram por ele batizados no Jordão, confessando os seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Mas quando ele viu muitos dos fariseus e dos saduceus que vinham ao seu batismo, disse-lhes: Ninhada de víboras! Quem vos ensinou a fugir da ira futura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Dai, pois, frutos condizentes com o arrependimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'E não imagineis, dizendo em vós mesmos: “Temos por pai a Abraão”, porque eu vos digo que até destas pedras Deus pode fazer surgir filhos a Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'E agora mesmoo machado está posto à raiz das árvores; portanto toda árvore que não dá bom fruto é cortada e lançada ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Realmente eu vos batizo com água para arrependimento, mas aquele que vem após mim é mais poderoso do que eu; suas sandálias não sou digno de levar. Ele vos batizará com o Espírito Santo e com fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Ele tem sua pá na mão; limpará sua eira, e recolherá seu trigo no celeiro; mas queimará a palha com fogo que nunca se apaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Então Jesus veio da Galileia ao Jordão até João para ser por ele batizado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Mas João lhe impedia, dizendo: Eu preciso ser batizado por ti, e tu vens a mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Porém Jesus lhe respondeu: Permite por agora, porque assim nos convém cumprir toda a justiça. Então ele o permitiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'E tendo Jesus sido batizado, subiu logo da água. E eis que os céus se lhe abriram, e ele viu o Espírito de Deus descendo como uma pomba, vindo sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'E eis uma voz dos céus, dizendo: Este é o meu Filho amado, em quem me agrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Então Jesus foi levado pelo Espírito ao deserto para ser tentado pelo diabo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'E depois de jejuar quarenta dias e quarenta noites, teve fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'E o tentador se aproximou dele, e disse: Se tu és o Filho de Deus, dize que estas pedras se tornem pães.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Mas Jesus respondeu: Está escrito: Não só de pão viverá o ser humano, mas de toda palavra que sai da boca de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Então o diabo o levou consigo à santa cidade, e o pôs sobre o ponto mais alto do Templo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'E disse-lhe: Se tu és o Filho de Deus, lança-te abaixo, porque está escrito que: Mandará a seus anjos acerca de ti, e te tomarão pelas mãos, para que nunca com teu pé tropeces em pedra alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jesus lhe disse: Também está escrito: Não tentarás o Senhor teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Outra vez o diabo o levou consigo a um monte muito alto, e lhe mostrou todos os reinos do mundo, e a glória deles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'E disse-lhe: Tudo isto te darei se, prostrado, me adorares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Então Jesus disse: Vai embora, Satanás! Porque está escrito: Ao Senhor teu Deus adorarás, e só a ele cultuarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Então o diabo o deixou; e eis que chegaram anjos, e o serviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Mas quando Jesus ouviu que João estava preso, voltou para a Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'E deixando Nazaré, veio a morar em Cafarnaum, cidade marítima, nos limites de Zebulom e Naftali,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'para que se cumprisse o que foi anunciado pelo profeta Isaías, que disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'A terra de Zebulom e a terra de Naftali, caminho do mar, além do Jordão, a Galileia dos gentios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'O povo sentado em trevas viu uma grande luz; aos sentados em região e sombra da morte, a luz lhes apareceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Desde então Jesus começou a pregar e a dizer: Arrependei-vos, porque perto está o Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Enquanto Jesus andava junto ao mar da Galileia, viu dois irmãos: Simão, chamado Pedro, e seu irmão André, lançarem a rede ao mar, porque eram pescadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'E disse-lhes: Vinde após mim, e eu vos farei pescadores de gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Então eles logo deixaram as redes e o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'E passando dali, viu outros dois irmãos: Tiago, filho de Zebedeu, e seu irmão João, em um barco, com seu pai Zebedeu, que estavam consertando suas redes; e ele os chamou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'E eles logo deixaram o barco e seu pai, e o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'E Jesus rodeava toda a Galileia, ensinando em suas sinagogas, pregando o Evangelho do Reino, e curando toda enfermidade e toda doença no povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Sua fama corria por toda a Síria, e traziam-lhe todos que sofriam de algum mal, tendo diversas enfermidades e tormentos, e os endemoninhados, epiléticos, e paralíticos; e ele os curava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'E muitas multidões da Galileia, de Decápolis, de Jerusalém, da Judeia, e dalém do Jordão o seguiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'E quando Jesus viu as multidões, subiu a um monte; e sentando-se, achegaram-se a ele os seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Então ele abriu sua boca e lhes ensinou, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Benditos são os humildes de espírito, porque deles é o Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Benditos são os que choram, porque eles serão consolados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Benditos são os mansos, porque eles herdarão a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Benditos são os que têm fome e sede de justiça, porque eles serão saciados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Benditos são os misericordiosos, porque eles alcançarão misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Benditos são os limpos de coração, porque eles verão a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Benditos são os pacíficos, porque eles serão chamados filhos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Benditos são os que sofrem perseguição por causa da justiça, porque deles é o Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Benditos sois vós, quando vos insultarem, perseguirem, e mentirem, falando contra vós todo mal por minha causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Jubilai e alegrai-vos, porque grande é vossa recompensa nos céus; pois assim perseguiram aos profetas que foram antes de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vós sois o sal da terra; mas se o sal perder seu sabor, com que se salgará? Para nada mais presta, a não ser para se lançar fora, e ser pisado pelas pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vós sois a luz do mundo; não se pode esconder uma cidade fundada sobre o monte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Nem se acende a lâmpada para se pôr debaixo de um cesto, mas sim na luminária, e ilumina a todos quantos estão na casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Assim brilhe vossa luz diante das pessoas, para que vejam vossas boas obras, e glorifiquem ao vosso Pai, que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Não penseis que vim para revogar a Lei ou os Profetas; não vim para revogar, mas sim para cumprir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Porque em verdade vos digo que, até que o céu e a terra passem, nem um jota nem um til passará da Lei até que tudo aconteça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Portanto qualquer um que desobedecer a um destes menores mandamentos, e assim ensinar às pessoas, será chamado o menor no Reino dos céus; porém qualquer que os cumprir e ensinar, esse será chamado grande no Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Porque eu vos digo que se a vossa justiça não for maior que a dos escribas e dos fariseus, de maneira nenhuma entrareis no Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Ouvistes o que foi dito aos antigos: “Não cometerás homicídio”; “mas qualquer um que cometer homicídio será réu do julgamento”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Porém eu vos digo que qualquer um que se irar contra seu irmão sem razão será réu do julgamento. E qualquer um que disser a seu irmão: “Idiota!” será réu do tribunal. E qualquer que lhe disser: “Louco!” será réu do fogo do inferno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Portanto, se trouxeres tua oferta ao altar, e ali te lembrares que teu irmão tem algo contra ti,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Deixa ali tua oferta diante do altar e vai primeiro reconciliar-te com teu irmão, e então vem oferecer a tua oferta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Faze acordo depressa com teu adversário, enquanto estás com ele no caminho, para não acontecer que o adversário te entregue ao juiz, e o juiz te entregue ao oficial, e te lancem na prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Em verdade te digo que não sairás dali enquanto não pagares a última moeda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Ouvistes o que foi dito aos antigos: “Não adulterarás”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Porém eu vos digo que qualquer um que olhar para uma mulher para a cobiçar, em seu coração já adulterou com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Se o teu olho direito te faz pecar, arranca-o e lança-o de ti; porque é melhor para ti que um dos teus membros se perca do que o teu corpo todo seja lançado no inferno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'E se a tua mão direita te faz pecar, corta-a e lança-a de ti; porque é melhor para ti que um dos teus membros se perca do que o teu corpo todo seja lançado no inferno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Também foi dito: “Qualquer um que se divorciar sua mulher, dê a ela carta de separação”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Porém eu vos digo que qualquer um que se divorciar de sua mulher, a menos que seja por causa de pecado sexual, faz com que ela adultere; e qualquer um que se casar com a divorciada comete adultério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Também ouvistes que foi dito aos antigos: “Não jurarás falsamente”, “mas cumprirás ao Senhor os teus juramentos”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Porém eu vos digo que de maneira nenhuma jureis; nem pelo céu, porque é o trono de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Nem pela terra, porque é o suporte de seus pés; nem por Jerusalém, porque é a cidade do grande Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Nem por tua cabeça jurarás, pois nem sequer um cabelo podes tornar branco ou preto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Mas seja vosso falar: “sim”, “sim”, “não”, “não”; porque o que disso passa procede do maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Ouvistes o que foi dito: “Olho por olho, e dente por dente”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Mas eu vos digo que não resistais a quem for mau; em vez disso, a qualquer um que te bater à tua face direita, mostra-lhe também a outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'E ao que quiser disputar contigo, e te tomar tua túnica, deixa-lhe também a capa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'E se qualquer um te obrigar a caminhar uma milha, vai com ele duas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Dá a quem te pedir; e não te desvies de quem quiser de ti tomar emprestado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Ouvistes o que foi dito: “Amarás teu próximo”, e “odiarás teu inimigo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Porém eu vos digo: amai vossos inimigos, bendizei os que vos maldizem, fazei bem aos que vos odeiam, e orai pelos que vos maltratam e vos perseguem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Para que sejais filhos de vosso Pai que está nos céus; porque ele faz seu sol sair sobre maus e bons, e chover sobre justos e injustos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Pois se amardes os que vos amam, que recompensa tereis? Não fazem os cobradores de impostos também o mesmo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'E se saudardes somente os vossos irmãos, o que fazeis de mais? Não fazem os cobradores de impostos também assim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Portanto, sede vós perfeitos, assim como vosso Pai que está nos céus é perfeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Ficai atentos para que não façais vossa esmola diante das pessoas a fim de que sejais vistos por elas; de outra maneira não tereis recompensa de vosso Pai que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Portanto, quando fizeres esmola, não faças tocar trombeta diante de ti, como fazem os hipócritas nas sinagogas e nas ruas, para serem honrados pelas pessoas; em verdade vos digo que já receberam sua recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Mas quando tu fizeres esmola, não saiba tua mão esquerda o que faz a tua direita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Para que a tua esmola seja em segredo, e teu Pai, que vê em segredo, ele te recompensará em público.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'E quando orares, não sejas como os hipócritas; porque eles amam orar em pé nas sinagogas e nas esquinas das ruas para serem vistos pelas pessoas. Em verdade vos digo que já receberam sua recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Porém tu, quando orares, entra em teu quarto, fecha tua porta, e ora a teu Pai, que está em segredo; e teu Pai, que vê em segredo, ele te recompensará em público.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'E quando orardes, não façais repetições inúteis como os gentios, que pensam que por muito falarem serão ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Não sejais, pois, semelhantes a eles; porque vosso Pai sabe o que necessitais, antes que vós peçais a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vós, portanto, orareis assim: Pai nosso, que estás nos céus, santificado seja o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Venha o teu Reino. Seja feita a tua vontade, tanto na terra, assim como no céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'O pão nosso de cada dia nos dá hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'E perdoa-nos nossas dívidas, assim como nós também perdoamos aos nossos devedores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'E não nos conduzas à tentação, mas livra-nos do mal; porque teu é o Reino, o poder, e a glória, para sempre, Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Porque se perdoardes às pessoas suas ofensas, vosso Pai celestial também vos perdoará;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Mas se não perdoardes às pessoas suas ofensas, também vosso Pai não vos perdoará vossas ofensas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'E quando jejuardes, não vos mostreis tristonhos, como os hipócritas; porque eles desfiguram seus rostos, para parecerem aos outros que jejuam. Em verdade vos digo que eles já receberam sua recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Porém tu, quando jejuares, unge a tua cabeça e lava o teu rosto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Para não pareceres às pessoas que jejuas, mas sim ao teu Pai, que está em segredo; e teu Pai, que vê em segredo, ele te recompensará em público.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Não ajunteis para vós tesouros na terra, onde e a traça e a ferrugem gastam, e onde os ladrões invadem e roubam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Mas ajuntai para vós tesouros no céu, onde nem a traça nem a ferrugem gastam, e onde os ladrões não invadem nem roubam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Porque onde estiver o vosso tesouro, ali estará também o vosso coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'A lâmpada do corpo é o olho; portanto, se o teu olho for puro, todo o teu corpo será cheio de luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Porém se o teu olho for maligno, todo o teu corpo será cheio de trevas. Assim, se a luz que há em ti são trevas, como são grandes essas trevas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Ninguém pode servir a dois senhores; pois ou odiará um e amará outro; ou se apegará a um, e desprezará o outro. Não podeis servir a Deus e às riquezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Por isso vos digo: não andeis ansiosos por vossa vida, sobre o que haveis de comer, ou que haveis de beber; nem por vosso corpo, sobre com que vos haveis de vestir. Não é a vida mais que o alimento, e o corpo mais que a roupa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Olhai para as aves do céu, que não semeiam, nem ceifam, nem ajuntam em celeiros; e contudo vosso Pai celestial as alimenta. Não sois vós muito mais importantes que elas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'E qual de vós poderá, por sua ansiedade, acrescentar um côvado à sua estatura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'E por que andais ansiosos pela roupa? Prestai atenção aos lírios do campo, como crescem; eles nem trabalham nem fiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Mas eu vos digo que nem mesmo Salomão, em toda a sua glória, se vestiu como um deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Se Deus veste desta maneira a erva do campo, que hoje existe, e amanhã é lançada no forno, não vestirá ele muito mais a vós, que tendes pouca fé?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Não andeis, pois, ansiosos, dizendo: “Que comeremos?” Ou “Que beberemos?” Ou “Com que nos vestiremos?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Porque os gentios buscam todas estas coisas, e vosso Pai celestial sabe que necessitais destas coisas, todas elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Mas buscai primeiramente o Reino de Deus e a sua justiça, e todas estas coisas vos serão acrescentadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Não andeis, pois, ansiosos pelo dia de amanhã, porque o amanhã cuidará de si mesmo. Basta a cada dia o seu mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Não julgueis, para que não sejais julgados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Porque com o juízo que julgardes sereis julgados; e com a medida que medirdes vos medirão de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Ora, por que vês o cisco que está no olho de teu irmão e não enxergas a trave que está em teu próprio olho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ou como dirás a teu irmão: “Deixa-me tirar o cisco do teu olho”, se eis que há uma trave em teu próprio olho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hipócrita! Tira primeiro a trave do teu olho, e então verás claramente para tirar o cisco do olho de teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Não deis o que é santo aos cães, nem lanceis vossas pérolas diante dos porcos, para não acontecer de as pisarem com os pés e, virando-se, vos despedacem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Pedi, e vos será dado; buscai, e achareis; batei, e vos será aberto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Pois qualquer um que pede recebe; e quem busca acha; e ao que bate lhe é aberto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'E quem há dentre vós que, se seu filho pedir pão, lhe dará uma pedra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'E se pedir peixe, lhe dará uma serpente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Ora, se vós, ainda que sejais maus, sabeis dar bons presentes a vossos filhos, quanto mais o vosso Pai, que está nos céus, dará coisas boas aos que lhe pedirem!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Portanto tudo o que quiserdes que os outros vos façam, fazei-lhes vós também assim; porque esta é a Lei e os Profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Entrai pela porta estreita; porque larga é a porta, e espaçoso o caminho que leva à perdição; e muitos são os que por ela entram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Porque estreita é a porta, e apertado o caminho que leva à vida; e são poucos os que a acham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Tende cuidado, porém, com os falsos profetas, que vêm a vós com roupa de ovelhas, mas por dentro são lobos vorazes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Vós os conhecereis pelos seus frutos. Por acaso se colhem uvas dos espinheiros, ou figos dos abrolhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Assim toda boa árvore dá bons frutos, mas a arvore má dá frutos maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'A boa árvore não pode dar frutos maus, nem a árvore má dar bons frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Toda árvore que não dá bom fruto é cortada e lançada ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Portanto vós os conhecereis pelos seus frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Não é qualquer um que me diz: “Senhor, Senhor” que entrará no Reino dos céus; mas sim aquele que faz a vontade do meu Pai que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Muitos me dirão naquele dia: “Senhor, Senhor! Não profetizamos em teu nome? E em teu nome não expulsamos os demônios? E em teu nome não fizemos muitas maravilhas?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Então claramente lhes direi: “Nunca vos conheci. Afastai-vos de mim, transgressores!”)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Portanto todo o que ouve estas minhas palavras e as pratica, eu o compararei ao homem prudente, que construiu sua casa sobre a rocha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela não caiu, porque estava fundada sobre a rocha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Porém todo o que ouve estas minhas palavras e não as pratica, eu o compararei ao homem tolo, que construiu sua casa sobre a areia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela caiu, e sua queda foi grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'E aconteceu que, quando Jesus terminou estas palavras, as multidões estavam admiradas de sua doutrina,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'porque ele os ensinava como tendo autoridade, e não como os escribas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Quando ele desceu do monte, muitas multidões o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'E eis que um leproso veio e prostrou-se diante dele, dizendo: Senhor, se quiseres, podes me limpar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Jesus estendeu a mão e o tocou, dizendo: Quero, sê limpo. E logo ele ficou limpo de sua lepra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Então Jesus lhe disse: Tem o cuidado de dizeres a ninguém; mas vai mostrar-te ao sacerdote, e oferece a oferta que Moisés ordenou, para que lhes haja testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Quando Jesus entrou em Cafarnaum, veio a ele um centurião, rogando-lhe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'E dizendo: Senhor, o meu servo jaz em casa, paralítico, e gravemente atormentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'E Jesus lhe disse: Eu irei, e o curarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'E o centurião respondeu: Senhor, não sou digno de que entres sob meu telhado; mas dize somente uma palavra, e o meu servo sarará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Pois eu também sou homem debaixo de autoridade, e tenho debaixo de meu comando soldados; e digo a este: “Vai”, e ele vai; e ao outro: “Vem”, e vem; e a meu servo: “Faze isto”, e ele faz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Quando Jesus ouviu isto,maravilhou-se, e disse aos que o seguiam: Em verdade vos digo que nem mesmo em Israel encontrei tanta fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Mas eu vos digo que muitos virão do oriente e do ocidente, e se sentarão à mesa com Abraão, Isaque, e Jacó, no Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Os filhos do reino, porém, serão lançados nas trevas de fora; ali haverá pranto e ranger de dentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Então Jesus disse ao centurião: Vai, e assim como creste, a ti seja feito.E naquela mesma hora o servo dele foi sarado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'E quando Jesus veio à casa de Pedro, viu a sogra dele, deitada e com febre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Ele tocou a mão dela, e a febre a deixou. Então ela se levantou e começou a servi-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Quando chegou o anoitecer, trouxeram-lhe muitos endemoninhados. Ele expulsou-lhes os espíritos com a palavra, e curou todos os que estavam doentes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Para que se cumprisse o que havia sido dito pelo profeta Isaías, que disse: Ele tomou sobre si as nossas enfermidades, e levou as nossas doenças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'E Jesus, ao ver muitas multidões ao redor de si, mandou que passassem para a outra margem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Então um escriba se aproximou, e disse-lhe: Mestre, eu te seguirei aonde quer que fores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Jesus lhe respondeu: As raposas têm covis, e as aves do céu ninhos; mas o Filho do homem não tem onde recostar a cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'E outro dos seus discípulos lhe disse: Senhor, permite-me ir primeiro enterrar meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Porém Jesus lhe disse: Segue-me, e deixa aos mortos enterrarem seus mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Então ele entrou no barco, e seus discípulos o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'E eis que se levantou no mar uma tormenta tão grande que o barco era coberto pelas ondas; porém ele dormia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'E seus discípulos se aproximaram para acordá-lo, dizendo: Senhor, salva-nos! Estamos sendo destruídos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'E ele lhes respondeu: Por que temeis, homens de pouca fé? Então ele se levantou e repreendeu os ventos e o mar. E houve grande calmaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'E aqueles homens se maravilharam, dizendo: Quem é este, que até os ventos e o mar lhe obedecem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'E quando chegou à outra margem, à terra dos gergesenos, vieram-lhe ao encontro dois endemoninhados que tinham saído dos sepulcros. Eles eram tão ferozes que ninguém podia passar por aquele caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'E eis que gritaram, dizendo: Que temos contigo, Jesus, Filho de Deus? Vieste aqui nos atormentar antes do tempo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Enquanto isso longe deles estava uma manada de muitos porcos pastando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'E os demônios rogaram-lhe, dizendo: Se nos expulsares, permite-nos entrar naquela manada de porcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'E ele lhes disse: Ide. Então eles saíram, e entraram na manada de porcos; e eis que toda aquela manada de porcos se lançou de um precipício ao mar, e morreram nas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'E os que cuidavam dos porcos fugiram; e ao chegarem à cidade, anunciaram todas estas coisas, inclusive o que havia acontecido aos endemoninhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'E eis que toda aquela cidade saiu ao encontro de Jesus; e quando o viram, rogaram-lhe que se retirasse do território deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Então ele entrou no barco, passou para a outra margem, e veio à sua própria cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'E eis que lhe trouxeram um paralítico, deitado em um leito. Quando Jesus viu a fé deles, disse ao paralítico: Tem bom ânimo, filho! Teus pecados são perdoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'E eis que alguns dos escribas disseram entre si: Ele blasfema.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Mas Jesus, vendo seus pensamentos, disse: Por que pensais o mal em vossos corações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Pois o que é mais fácil? Dizer: “Teus pecados são perdoados”, ou dizer: “Levanta-te, e anda”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Ora, para que saibais que o Filho do homem tem autoridade na terra para perdoar pecados,(Ele, então, disse ao paralítico): Levanta-te, toma o teu leito, e vai para tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'E este se levantou e foi para sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Quando as multidões viram isto,ficaram maravilhadas, e glorificaram a Deus, que tinha dado tal autoridade aos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'E Jesus, ao passar dali, viu um homem sentado na coletoria de impostos, chamado Mateus; e disse-lhe: Segue-me. Então este se levantou e o seguiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'E aconteceu que, enquanto Jesus estava reclinado à mesa na casa de Mateus, eis que muitos cobradores de impostos e pecadores vieram e se reclinaram à mesa juntamente com Jesus e seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'E quando os fariseus viram isto, perguntaram aos seus discípulos: Por que o vosso Mestre come com cobradores de impostos e pecadores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Porém Jesus ouviu, e respondeu-lhes: Os que têm saúde não precisam de médico, mas sim os que estão doentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Mas ide aprender o que significa: “Quero misericórdia, e não sacrifício”. Porque eu não vim chamar os justos, mas sim os pecadores, ao arrependimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Então os discípulos de João vieram a ele, e perguntaram: Por que nós e os fariseus jejuamos muitas vezes, mas os teus discípulos não jejuam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'E Jesus lhes respondeu: Podem, por acaso, os convidados do casamento andar tristes enquanto o noivo está com eles? Mas dias virão, quando o noivo lhes for tirado, e então jejuarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'E ninguém põe remendo de pano novo em roupa velha; porque tal remendo rasga a roupa, e o rompimento se torna pior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Nem põem vinho novo em odres velhos; pois senão os odres se rompem, o vinho se derrama, e os odres se perdem; mas põem o vinho novo em odres novos, e ambos juntamente se conservam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Enquanto ele lhes dizia estas coisas, eis que um chefe de sinagoga veio prostrar-se diante dele, e disse: Minha filha faleceu ainda agora; mas vem, e põe tua mão sobre ela, e ela viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Então Jesus se levantou e o seguiu com seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, '(Eis, porém, que uma mulher enferma de um fluxo de sangue havia doze anos veio por detrás dele, e tocou a borda de sua roupa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Porque dizia consigo mesma: Se eu tão-somente tocar a roupa dele, serei curada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jesus se virou e a viu. Então disse: Tem bom ânimo, filha, a tua fé te sarou. E desde aquela hora a mulher ficou com saúde.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Quando Jesus chegou à casa daquele chefe, viu os tocadores de flauta e a multidão que fazia alvoroço,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'E disse-lhes: Retirai-vos, porque a menina não está morta, mas sim dormindo. E riram dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Mas quando a multidão foi expulsa, ele entrou, pegou a mão dela, e a menina se levantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'E esta notícia se espalhou por toda aquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'E saindo Jesus dali, dois cegos o seguiram, gritando: Tem compaixão de nós, Filho de Davi!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'E quando ele entrou em casa, os cegos vieram a ele. Jesus lhes perguntou: Credes que posso fazer isto? Eles lhe responderam: Sim, Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Então tocou os olhos deles, dizendo: Seja feito convosco conforme a vossa fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'E os olhos deles se abriram. Então Jesus os advertiu severamente, dizendo: Tende o cuidado de que ninguém saiba disso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Porém eles saíram e divulgaram a notícia acerca dele por toda aquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Enquanto eles saíam, eis que lhe trouxeram um homem mudo e endemoninhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Quando o demônio foi expulso, o mudo passou a falar. Então as multidões ficaram maravilhadas, e disseram: Nunca se viu algo assim em Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Mas os fariseus diziam: É pelo chefe dos demônios que ele expulsa os demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Jesus percorria todas as cidades e aldeias, ensinando em suas sinagogas, pregando o Evangelho do Reino, e curando toda enfermidade e toda doença entre o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Quando ele viu as multidões, teve compaixão delas, porque andavam cansadas e desamparadas, como ovelhas que não têm pastor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Então disse aos seus discípulos: Em verdade a colheita é grande, porém os trabalhadores são poucos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Portanto rogai ao Senhor da colheita que envie trabalhadores à sua colheita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Jesus chamou a si os seus doze discípulos, e deu-lhes poder sobre os espíritos imundos, para os expulsarem, e curarem toda enfermidade e toda doença.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'E os nomes dos doze apóstolos são estes: o primeiro, Simão, chamado Pedro, e seu irmão André; Tiago, filho de Zebedeu, e seu irmão João;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filipe e Bartolomeu; Tomé, e Mateus o coletor de impostos; Tiago, filho de Alfeu; e Lebeu, por sobrenome Tadeu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simão o zeloso, e Judas Iscariotes, o mesmo que o traiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Jesus enviou estes doze, e lhes mandou, dizendo: Não ireis pelo caminho dos gentios, nem entrareis em cidade de samaritanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Em vez disso, ide às ovelhas perdidas da casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'E quando fordes, proclamai, dizendo: “Perto está o Reino dos céus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Curai os doentes, limpai os leprosos, ressuscitai os mortos, expulsai os demônios; recebestes de graça, dai de graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Não possuais ouro, nem prata, nem cobre em vossos cintos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Nem bolsas para o caminho, nem duas túnicas, nem sandálias, nem bordão extra; pois o trabalhador é digno de seu alimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'E em qualquer cidade ou aldeia que entrardes, informai-vos de quem nela seja digno, e ficai ali até que saiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'E quando entrardes na casa, saudai-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Se a casa for digna, venha sobre ela a vossa paz; mas se ela não for digna, volte para vós a vossa paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'E quem quer que não vos receber, nem ouvir vossas palavras, quando sairdes daquela casa ou cidade, sacudi o pó de vossos pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Em verdade vos digo que no dia do julgamento mais tolerável será para a região de Sodoma e Gomorra do que para aquela cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Eis que eu vos envio como ovelhas em meio de lobos; portanto, sede prudentes como as serpentes e inofensivos como pombas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Porém tende cuidado com as pessoas; porque vos entregarão em tribunais, e vos açoitarão em suas sinagogas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'E até perante governadores e reis sereis levados por causa de mim, para que haja testemunho a eles e aos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Mas quando vos entregarem, não estejais ansiosos de como ou que falareis; porque naquela mesma hora vos será dado o que deveis falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Porque não sois vós os que falais, mas sim o Espírito do vosso Pai que fala em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'E irmão entregará irmão à morte, e pai ao filho; e filhos se levantarão contra os pais, e os matarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'E sereis odiados por todos por causa de meu nome; mas aquele que perseverar até o fim, esse será salvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Quando, então, vos perseguirem nesta cidade, fugi para outra; porque em verdade vos digo que não acabareis de percorrer as cidades de Israel, até que venha o Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'O discípulo não é superior ao mestre, nem o servo superior ao seu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Seja suficiente ao discípulo ser como o seu mestre, e ao servo como o seu senhor; se ao chefe da casa chamaram de Belzebu, quanto mais aos membros de sua casa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Portanto, não os temais; porque nada há encoberto que não se revelará, nada oculto que não se saberá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'O que eu vos digo em trevas, dizei na luz; e o que ouvis ao ouvido, proclamai sobre os telhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'E não temais os que matam o corpo, mas não podem matar a alma; temei mais aquele que pode destruir tanto a alma como o corpo no inferno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Não se vendem dois pardais por uma pequena moeda? Mas nem um deles cairá em terra contra a vontade de vosso Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'E até os cabelos de vossas cabeças estão todos contados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Assim, não tenhais medo; mais valeis vós que muitos pardais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Portanto, todo aquele que me der reconhecimento diante das pessoas, também eu o reconhecerei diante de meu Pai, que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Porém qualquer um que me negar diante das pessoas, também eu o negarei diante de meu Pai, que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Não penseis que vim trazer paz à terra. Não vim trazer paz, mas sim espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Porque eu vim pôr em discórdia “o homem contra seu pai, a filha contra sua mãe, e a nora contra sua sogra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'E os inimigos do homem serão os de sua própria casa”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Quem ama pai ou mãe mais que a mim não é digno de mim; e quem ama filho ou filha mais que a mim não é digno de mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'E quem não toma sua cruz e segue após mim não é digno de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Quem achar sua vida a perderá; e quem, por causa de mim, perder sua vida, a achará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Quem vos recebe, recebe a mim; e quem me recebe, recebe aquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Quem recebe um profeta por reconhecê-lo como profeta receberá recompensa de profeta; e quem recebe um justo por reconhecê-lo como justo receberá recompensa de justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'E qualquer um que der ainda que somente um copo de água fria a um destes pequenos por reconhecê-lo como discípulo, em verdade vos digo que de maneira nenhuma perderá sua recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Quando Jesus acabou de dar as ordens aos seus doze discípulos, partiu dali para ensinar e para pregar em suas cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'E João, ao ouvir na prisão as obras de Cristo, enviou -lhe dois de seus discípulos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Perguntando-lhe: És tu aquele que havia de vir, ou esperamos outro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jesus lhes respondeu: Ide anunciar a João as coisas que ouvis e vedes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Os cegos veem, e os mancos andam; os leprosos são limpos, e os surdos ouvem; os mortos são ressuscitados, e aos pobres é anunciado o Evangelho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'E bendito é aquele que não deixar de crer em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Depois que eles se foram, Jesus começou a dizer às multidões acerca de João: Que saístes ao deserto para ver? Uma cana que se move pelo vento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Mas que saístes para ver? Um homem vestido com roupas delicadas? Eis que os que usam roupas delicadas estão nas casas dos reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mas que saístes para ver? Um profeta? Sim, eu vos digo, e muito mais que um profeta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Porque este é aquele sobre o qual está escrito: “Eis que diante de tua face envio o meu mensageiro, que preparará o teu caminho diante de ti.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Em verdade vos digo que, dentre os nascidos de mulheres, não se levantou outro maior que João Batista; porém o menor no Reino dos céus é maior que ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'E desde os dias de João Batista até agora, o Reino dos céus é forçado, e os que usam de força o tomam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Porque todos os profetas e a Lei profetizaram até João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'E se estais dispostos a aceitar, este é o Elias que havia de vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Quem tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mas com quem compararei esta geração? Semelhante é às crianças que se sentam nas praças, e chamam aos seus colegas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'E dizem: “Tocamos flauta para vós, mas não dançastes; cantamos lamentações para vós, mas não chorastes.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Porque veio João, sem comer nem beber, e dizem: “Ele tem demônio.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Veio o Filho do homem, que come e bebe, e dizem: “Eis aqui um homem comilão e beberrão, amigo de cobradores de impostos e pecadores!” Mas a sabedoria prova-se justa por meio de seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Então ele começou a acusar as cidades em que a maioria de seus milagres haviam sido feitos, por não terem se arrependido:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Ai de ti Corazim! Ai de ti Betsaida! Porque se em Tiro e em Sidom tivessem sido feitos os milagres que em vós foram feitos, há muito tempo teriam se arrependido com saco e com cinza!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Porém eu vos digo que mais tolerável será para Tiro e Sidom, no dia do juízo, que para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'E tu, Cafarnaum, que estás exaltada até o céu, ao mundo dos mortos serás derrubada! Pois se em Sodoma tivessem sido feitos os milagres que foram feitos em ti, ela teria permanecido até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Porém eu vos digo que mais tolerável será para os da região de Sodoma, no dia de juízo, que para ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Naquele tempo Jesus pronunciou: Graças te dou, Pai, Senhor do céu e da terra, porque escondeste estas coisas aos sábios e entendidos, e as revelaste às crianças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Sim, Pai, porque assim foi agradável a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Todas as coisas me foram entregues pelo meu Pai; e ninguém conhece o Filho, a não ser o Pai; nem ninguém conhece o Pai, a não ser o Filho, e a quem o Filho o quiser revelar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Vinde a mim todos vós que estais cansados e sobrecarregados, e eu vos farei descansar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Tomai sobre vós o meu jugo e aprendei de mim, porque sou manso e humilde de coração; e encontrareis descanso para as vossas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Pois o meu jugo é suave, e minha carga é leve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Naquele tempo Jesus estava indo pelas plantações de cereais no sábado. Seus discípulos tinham fome, e começaram a arrancar espigas e a comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Quando os fariseus viram, disseram-lhe: Eis que os teus discípulos fazem o que não é lícito fazer no sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Ele, porém, lhes disse: Não lestes o que Davi fez quando teve fome, ele e os que com ele estavam,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Como ele entrou na casa de Deus, e comeu os pães da proposição, que a ele não era lícito comer, nem também aos que com ele estavam, a não ser somente aos sacerdotes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ou não lestes na Lei que, nos sábados, os sacerdotes no Templo profanam o sábado, sem se tornarem culpados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Eu, porém, vos digo que o maior que o Templo está aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Mas se vós soubésseis o que significa: “Quero misericórdia, e não sacrifício”, não condenaríeis os inocentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Porque o Filho do homem é Senhor até do sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'E partindo dali, Jesus entrou na sinagoga deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'E eis que havia ali um homem que tinha uma mão definhada; e eles, a fim de o acusarem, perguntaram-lhe: É lícito curar nos sábados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'E ele lhes respondeu: Qual de vós será a pessoa que, caso tenha uma ovelha, e se a tal cair em uma cova no sábado, não usará de sua força para a levantar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Ora, quanto mais vale um ser humano que uma ovelha! Assim, pois, é lícito fazer o bem nos sábados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Então disse para aquele homem: Estende a tua mão.E ele a estendeu, e foi-lhe restaurada, sã como a outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Então os fariseus saíram e se reuniram para planejar contra ele, como o matariam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Mas Jesus, sabendo disso, retirou-se dali. Muitas multidões o seguiram, e ele curou todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'E ele lhes ordenava que não o tornassem conhecido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Para que se cumprisse o que foi dito pelo profeta Isaías:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Eis aqui meu servo a quem escolhi, meu amado em quem minha alma se agrada; sobre ele porei o meu Espírito, e ele anunciará justiça às nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Ele não fará brigas, nem gritará; ninguém ouvirá sua voz pelas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'A cana esmagada ele não despedaçará, o pavio que fumega ele não apagará, até que conduza a justiça à vitória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'E em seu nome as nações esperarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Então lhe trouxeram um endemoninhado cego e mudo; e ele o curou de tal maneira que o cego e mudo passou a falar e a ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'E todas as multidões se admiravam e diziam: Não é este o Filho de Davi?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Mas quando os fariseus ouviam isso, diziam: Ele não expulsa os demônios, a não ser por Belzebu, o chefe dos demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Porém Jesus, entendendo os pensamentos deles, disse-lhes: Todo reino dividido contra si mesmo é destruído; e toda cidade ou casa dividida contra si mesma não permanecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Ora, se Satanás expulsa a Satanás, contra si mesmo está dividido; como, pois, permanecerá o seu reino?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'E se eu expulso os demônios por Belzebu, então por quem vossos filhos os expulsam? Portanto, eles mesmos serão vossos juízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mas se eu pelo Espírito de Deus expulso os demônios, logo o Reino de Deus já chegou sobre vos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Ou como pode alguém entrar na casa do valente, e saquear seus bens, sem primeiro amarrar ao valente? Depois disso saqueará sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Quem não é comigo é contra mim; e quem não ajunta comigo, espalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Por isso eu vos digo: todo pecado e blasfêmia serão perdoados aos seres humanos; mas a blasfêmia contra o Espírito não será perdoada aos seres humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'E qualquer um que falar palavra contra o Filho do homem lhe será perdoado; mas qualquer um que falar contra o Espírito Santo, não lhe será perdoado, nem na era presente, nem na futura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ou fazei a árvore boa, e seu fruto bom; ou fazei a árvore má, e seu fruto mau; pois pelo fruto se conhece a árvore.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Ninhada de víboras, como podeis vós falar boas coisas, sendo maus? Pois a boca fala do que o coração tem de sobra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'A pessoa boa tira coisas boas do bom tesouro do coração, e a pessoa má tira coisas más do tesouro mau.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Eu, porém, vos digo que de toda palavra imprudente que as pessoas falarem, dela prestarão contas no dia do juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Porque por tuas palavras serás justificado, e por tuas palavras serás condenado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Então responderam uns dos escribas e dos fariseus, dizendo: Mestre, queremos ver de ti algum sinal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Mas ele lhes deu a seguinte resposta: Uma geração má e adúltera pede sinal; mas não lhe será dado, exceto o sinal do profeta Jonas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Porque assim como Jonas esteve três dias e três noites no ventre da baleia, assim também o Filho do homem estará três dias e três noites no coração da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Os de Nínive se levantarão no Juízo com esta geração, e a condenarão; porque se arrependeram com a pregação de Jonas. E eis aqui quem é maior que Jonas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'A rainha do sul se levantará no Juízo com esta geração, e a condenará; porque veio dos confins da terra para ouvir a sabedoria de Salomão. E eis aqui quem é maior que Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Quando o espírito imundo sai de alguém, anda por lugares secos buscando repouso, e não o acha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Então diz: “Voltarei para minha casa de onde saí”. E quando chega, a encontra desocupada, varrida, e adornada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Então vai, e toma consigo outros sete espíritos piores que ele; eles entram, e moram ali; e a última condição de tal pessoa se torna pior que a primeira. Assim também acontecerá com esta geração má.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Enquanto ele ainda estava falando às multidões, eis que sua mãe e seus irmãos estavam fora, querendo falar com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'E alguém lhe disse: Eis que tua mãe e teus irmãos estão fora, querendo falar contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Porém ele disse em resposta ao que o avisou: Quem é minha mãe? E quem são meus irmãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Então estendeu sua mão sobre seus discípulos, e disse: Eis aqui minha mãe e meus irmãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Pois qualquer um que fizer a vontade do meu Pai, que está nos céus, esse é meu irmão, e irmã, e mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Naquele dia, Jesus saiu de casa e se sentou junto ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'E ajuntaram-se perto dele tantas multidões, de maneira que ele entrou num barco e se sentou; e toda a multidão ficou na praia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'E ele lhes falou muitas coisas por parábolas. Ele disse: Eis que o semeador saiu a semear.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'E enquanto semeava, caiu parte das sementes junto ao caminho, e vieram as aves e a comeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'E outra parte caiu entre pedras, onde não havia muita terra, e logo nasceu, porque não tinha terra funda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Mas quando o sol surgiu, queimou-se; e por não ter raiz, secou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'E outra parte caiu entre espinhos, e os espinhos cresceram e a sufocaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'E outra parte caiu em boa terra, e rendeu fruto: um a cem, outro a sessenta, e outro a trinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Quem tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Então os discípulos se aproximaram, e lhe perguntaram: Por que falas a eles por parábolas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'E ele lhes respondeu: Porque a vós é dado saber os mistérios do Reino dos céus, mas a eles não é dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Pois a quem tem, lhe será dado, e terá em abundância; mas a quem não tem, até aquilo que tem lhe será tirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Por isso falo a eles por parábolas; porque vendo, não veem; e ouvindo, não ouvem, nem entendem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Assim neles se cumpre a profecia de Isaías, que diz: De fato ouvireis, mas não entendereis; De fato vereis, mas não enxergareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Porque o coração deste povo está insensível; Com seus ouvidos dificilmente ouvem, e seus olhos fecharam; A fim de não haver que seus olhos vejam, seus ouvidos ouçam, Seus corações entendam, e se arrependam, E eu os cure.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Mas benditos são os vossos olhos, porque veem; e os vossos ouvidos, porque ouvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Pois em verdade vos digo que muitos profetas e justos desejaram ver o que vós vedes, mas não viram; e desejaram ouvir o que vós ouvis, mas não ouviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Portanto, ouvi vós a parábola do semeador:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Quando alguém ouve a palavra do Reino e não a entende, o maligno vem e arranca o que foi semeado em seu coração; este é o que foi semeado junto ao caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'E o que foi semeado entre as pedras é o que ouve a palavra, e logo a recebe com alegria,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'mas não tem raiz em si mesmo. Em vez disso, dura um pouco, mas quando vem a aflição ou a perseguição pela palavra, logo se tornam infiéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'E o que foi semeado entre os espinhos é o que ouve a palavra, mas a ansiedade com o tempo presente e a sedução das riquezas sufocam a palavra, e fica sem dar fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Mas o que foi semeado em boa terra, este é o que ouve e entende a palavra, e o que dá e produz fruto, um a cem, outro a sessenta, e outro a trinta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'E ele lhes declarou outra parábola, dizendo: O Reino dos céus é semelhante a um homem que semeia boa semente em seu campo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Mas, enquanto as pessoas dormiam, o inimigo dele veio, semeou joio entre o trigo, e foi embora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'E, quando a erva cresceu e produziu fruto, então apareceu também o joio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Então os servos do dono da propriedade chegaram, e lhe perguntaram: “Senhor, não semeaste boa semente no teu campo? De onde, pois, veio o joio?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'E ele lhes respondeu: “Um inimigo fez isto”. Em seguida, os servos lhe perguntaram: “Queres, pois, que vamos e o tiremos?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Ele, porém, lhes respondeu: “Não, para não haver que, enquanto tirais o joio, arranqueis com ele também o trigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Deixai-os crescer ambos juntos até a colheita; e no tempo da colheita direi aos que colhem: ‘Recolhei primeiro o joio, e amarrai-o em molhos, para o queimarem; mas ao trigo ajuntai no meu celeiro’.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Ele lhes propôs outra parábola: O Reino dos céus é semelhante a um grão de mostarda que alguém tomou e semeou no seu campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'De fato, dentre todas as sementes, esta é a menor. Mas quando cresce, é a maior das hortaliças; e se torna tamanha árvore, que as aves do céu vêm e se aninham em seus ramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Ele lhes disse outra parábola: O Reino dos céus é semelhante ao fermento que uma mulher tomou e misturou em três medidas de farinha,) até que tudo ficasse fermentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Tudo isto Jesus falou por parábolas às multidões. Sem parábolas ele não lhes falava,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'para que se cumprisse o que foi falado pelo profeta, que disse: Abrirei a minha boca em parábolas; Pronunciarei coisas escondidas desde a fundação do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Então Jesus despediu as multidões, e foi para casa. Seus discípulos se aproximaram dele, e disseram: Explica-nos a parábola do joio do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'E ele lhes respondeu: O que semeia a boa semente é o Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'E o campo é o mundo; e a boa semente, estes são os filhos do Reino; e o joio são os filhos do maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'E o inimigo, que o semeou, é o diabo; e a colheita é o fim da era; e os que colhem são os anjos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Portanto, como o joio é colhido e queimado no fogo, assim também será no fim desta era.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'O Filho do homem enviará seus anjos, e eles recolherão do seu Reino todas as causas do pecado, assim como os que praticam injustiça,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'e os lançarão na fornalha de fogo. Ali haverá choro e ranger de dentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Então os justos brilharão como o sol, no Reino de seu Pai. Quem tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'O Reino dos céus também é semelhante a um tesouro escondido num campo, que um homem, depois de achá-lo, escondeu. Então, em sua alegria, vai, vende tudo quanto tem, e compra aquele campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'O Reino dos céus também é semelhante a um homem negociante, que buscava boas pérolas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Quando este achou uma pérola de grande valor, foi, vendeu tudo quanto tinha, e a comprou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'O Reino dos céus também é semelhante a uma rede lançada ao mar, que colhe toda espécie de peixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'E quando está cheia, os pescadores puxam-na à praia, sentam-se, e recolhem os bons em cestos, mas os ruins lançam fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Assim será ao fim da era; os anjos sairão, e separarão dentre os justos os maus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'e os lançarão na fornalha de fogo. Ali haverá choro e ranger de dentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'E Jesus lhes perguntou: Entendestes todas estas coisas?Eles lhe responderam: Sim, Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'E ele lhes disse: Portanto todo escriba que se tornou discípulo no Reino dos céus é semelhante a um chefe de casa, que do seu tesouro tira coisas novas e velhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'E aconteceu que, quando Jesus acabou essas parábolas, retirou-se dali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'E vindo à sua terra, ensinava-os na sinagoga deles, de tal maneira que ficavam admirados, e diziam: De onde vêm a este tal sabedoria, e os milagres?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Não é este o filho do carpinteiro? E não se chama sua mãe Maria, e seus irmãos Tiago, José, Simão, e Judas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Não estão todas as suas irmãs conosco? Ora, de onde vem a este tudo isto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'E se ofenderam por causa dele. Mas Jesus lhes disse: Não há profeta sem honra, a não ser em sua terra, e em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'E não fez ali muitos milagres por causa da incredulidade deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Naquele tempo Herodes, o tetrarca, ouviu relato a respeito de Jesus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'e disse aos seus servos: Este é João Batista; ele ressuscitou dos mortos, e por isso os milagres operam nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Porque Herodes havia prendido a João, acorrentado-o, e posto na prisão, por causa de Herodias, mulher do seu irmão Filipe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'pois João lhe dizia: Não te lícito que a tenhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Herodes queria matá-lo, mas tinha medo do povo, pois o consideravam profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Porém, enquanto era celebrado o aniversário de Herodes, a filha de Herodias dançou no meio das pessoas,e agradou a Herodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Por isso prometeu a ela dar tudo o que pedisse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'E ela, tendo sido induzida por sua mãe, disse: Dá-me aqui num prato a cabeça de João Batista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'E o rei se entristeceu; mas devido ao juramento, e aos que estavam presentes, ordenou que isso fosse concedido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Então mandou degolarem João na prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Sua cabeça foi trazida num prato, e dada à garota, e ela a levou à sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'E seus discípulos vieram, tomaram o corpo, e o enterraram; e foram avisar a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Depois de Jesus ouvir, retirou-se dali num barco, a um lugar deserto, sozinho; mas assim que as multidões ouviram acerca disso, seguiram-no a pé das cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Quando Jesus saiu, viu uma grande multidão. Ele se compadeceu deles, e curou dentre eles os enfermos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'E chegando o entardecer, os seus discípulos se aproximaram dele, e disseram: O lugar é deserto, e já é tarde. Despede as multidões, para irem às aldeias, e comprarem para si de comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Mas Jesus lhes respondeu: Eles não precisam ir. Vós mesmos, dai-lhes de comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'E eles lhe disseram: Nada temos aqui além de cinco pães e dois peixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Então disse: Trazei-os aqui a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Ele mandou às multidões que se sentassem sobre a grama. Então tomou os cinco pães e os dois peixes, levantou os olhos ao céu, e os abençoou. Em seguida partiu os pães, deu-os aos discípulos, e os discípulos às multidões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'E todos comeram, e se fartaram. E do que sobrou dos pedaços levantaram doze cestos cheios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'E os que comeram foram quase cinco mil homens, sem contar as mulheres e as crianças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'E logo Jesus mandou os seus discípulos entrarem no barco, e que fossem adiante dele para a outra margem, enquanto ele despedia as multidões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Depois de despedir as multidões, subiu ao monte, à parte, para orar. Tendo chegado a noite, ele estava ali sozinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'E o barco já estava no meio do mar, atormentado pelas ondas, porque o vento era contrário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Mas à quarta vigília da noite Jesus foi até eles, andando sobre o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Quando os discípulos o viram andar sobre o mar, apavoraram-se, dizendo: É um fantasma! E gritaram de medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mas Jesus logo lhes falou, dizendo: Tende coragem! Sou eu, não tenhais medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'E Pedro lhe respondeu, dizendo: Senhor, se és tu, manda-me vir a ti sobre as águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'E ele disse: Vem. Então Pedro desceu do barco e andou sobre as águas, para vir em direção a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Mas quando viu o vento forte, teve medo; e começando a afundar, gritou: Senhor, salva-me!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Imediatamente Jesus estendeu a mão, segurou-o, e disse-lhe: Homem de pouca fé, por que duvidaste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'E quando subiram no barco, o vento se aquietou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Então os que estavam no barco vieram e o adoraram, dizendo: Verdadeiramente tu és o Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'E havendo passado para a outra margem, chegaram à terra de Genesaré.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'E quando os homens daquele lugar o reconheceram, deram aviso por toda aquela região ao redor, e lhe trouxeram todos os que estavam enfermos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'E rogavam-lhe que tão somente tocassem a borda de sua roupa; e todos os que tocavam ficaram curados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Então alguns escribas e fariseus de Jerusalém se aproximaram de Jesus, e perguntaram:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Por que os teus discípulos transgridem a tradição dos anciãos? Pois não lavam suas mãos quando comem pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Porém ele lhes respondeu: E vós, por que transgredis o mandamento de Deus por vossa tradição?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Pois Deus mandou, dizendo: Honra ao teu pai e à tua mãe; e quem maldisser ao pai ou à mãe seja sentenciado à morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Mas vós dizeis: “Qualquer um que disser ao pai ou à mãe: ‘Todo o proveito que terias de mim é oferta exclusiva para Deus’, não precisa honrar seu pai ou à sua mãe”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'E assim invalidastes o mandamento de Deus por vossa tradição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hipócritas! Isaías bem profetizou sobre vós, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Este povo com sua boca se aproxima de mim, e com os lábios me honra; mas o seu coração está longe de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Em vão, porém, me veneram, ensinando doutrinas que são regras humanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Assim chamou a multidão para si, e disse-lhes: Ouvi e entendei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Não é o que entra na boca que contamina o ser humano; mas sim o que sai da boca, isso contamina o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Então os seus discípulos se aproximaram dele, e lhe perguntaram: Tu sabes que os fariseus se ofenderam quando ouviram esta palavra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Mas ele respondeu: Toda planta que meu Pai celestial não plantou será arrancada pela raiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Deixai-os, são guias cegos de cegos. E se o cego guiar outro cego, ambos cairão na cova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'E Pedro lhe disse: Explica-nos esta parábola.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Porém Jesus disse: Até vós ainda estais sem entender?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Não percebeis ainda que tudo o que entra na boca vai ao ventre, mas depois é lançado na privada?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Porém as coisas que saem da boca procedem do coração; e elas contaminam o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Pois do coração procedem maus pensamentos, mortes, adultérios, pecados sexuais, furtos, falsos testemunhos, blasfêmias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Estas coisas são as que contaminam o ser humano; mas comer sem lavar as mãos não contamina o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'E, tendo Jesus partido dali, foi para as partes de Tiro e de Sidom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'E eis que uma mulher Cananeia, que tinha saído daquela região, clamou-lhe: Senhor, Filho de Davi, tem misericórdia de mim! Minha filha está miseravelmente endemoninhada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Mas ele não lhe respondeu palavra. Então seus discípulos se aproximaram dele, e rogaram-lhe, dizendo: Manda-a embora, porque ela está gritando atrás de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'E ele respondeu: Não fui enviado para ninguém além das ovelhas perdidas da casa de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Então ela veio e se prostrou diante dele, dizendo: Senhor, socorre-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Mas ele respondeu: Não é bom tomar o pão dos filhos e lançá-lo aos cachorrinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Ela, porém, disse: Sim, Senhor. Porém os cachorrinhos também comem, das migalhas que caem da mesa dos seus senhores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Então Jesus lhe respondeu: Ó mulher, grande é a tua fé. A ti seja feito como tu queres. E desde aquela hora sua filha ficou curada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'E tendo Jesus partido dali, veio ao mar da Galileia. Ele subiu a um monte, e ali se sentou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'E vieram a ele muitas multidões, que tinham consigo mancos, cegos, mudos, aleijados, e muitos outros; e os lançaram aos pés de Jesus, e ele os curou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Desta maneira, as multidões se maravilhavam quando viam os mudos falarem, os aleijados ficarem sãos, os mancos andarem, e os cegos verem; então glorificaram ao Deus de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Jesus chamou a si os seus discípulos, e disse: Estou compadecido com a multidão, porque já há três dias que estão comigo, e não têm o que comer. E não quero os deixar ir em jejum, para que não desmaiem no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'E os seus discípulos lhe responderam: De onde conseguiremos tantos pães no deserto, para saciar tão grande multidão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Jesus lhes perguntou: Quantos pães tendes? E eles disseram: Sete; e uns poucos peixinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Então mandou as multidões que se sentassem pelo chão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Tomou os sete pães e os peixes, deu graças e os partiu. Em seguida, ele os deu aos seus discípulos, e os discípulos à multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'E todos comeram e se saciaram; e levantaram dos pedaços que sobraram sete cestos cheios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'E foram os que comeram quatro mil homens, sem contar as mulheres e as crianças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Depois de despedir as multidões, Jesus entrou em um barco, e veio à região de Magdala.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Então os fariseus e os saduceus se aproximaram dele e, a fim de tentá-lo, pediram-lhe que lhes mostrasse algum sinal do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Mas ele lhes respondeu: Quando chega a tarde, dizeis: “Haverá tempo bom, pois o céu está vermelho”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'E pela manhã: “Hoje haverá tempestade, pois o céu está de um vermelho sombrio”. Hipócritas! Vós bem sabeis distinguir a aparência do céu, mas os sinais dos tempos não podeis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Uma geração má e adúltera pede um sinal; mas nenhum sinal lhe será dado, a não ser o sinal do profeta Jonas.Então os deixou, e foi embora');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'E quando os seus discípulos vieram para a outra margem, esqueceram-se de tomar pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'E Jesus lhes disse: Ficai atentos, e tende cuidado com o fermento dos fariseus e saduceus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'E eles argumentaram entre si, dizendo: É porque não tomamos pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Jesus percebeu, e disse-lhes: Por que estais argumentando entre vós mesmos, ó homens de pouca fé, que não tomastes pão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ainda não entendeis, nem vos lembrais dos cinco pães dos cinco mil, e quantos cestos levantastes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Nem dos sete pães dos quatro mil, e quantos cestos levantastes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Como não entendeis que não foi pelo pão que eu vos disse para tomardes cuidado com o fermento dos fariseus e saduceus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Então entenderam que ele não havia dito que tomassem cuidado com o fermento de pão, mas sim com a doutrina dos fariseus e saduceus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'E tendo Jesus vindo às partes da Cesareia de Filipe, perguntou aos seus discípulos: Quem as pessoas dizem que eu, o Filho do homem, sou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'E eles responderam: Alguns João Batista, outros Elias, e outros Jeremias ou algum dos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Ele lhes disse: E vós, quem dizeis que eu sou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'E Simão Pedro respondeu: Tu és o Cristo, o Filho do Deus vivo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'E Jesus lhe replicou: Bendito és tu, Simão, filho de Jonas; pois não foi carne e sangue que o revelou a ti, mas sim meu Pai, que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'E eu também te digo que tu és Pedro, e sobre esta pedra edificarei a minha igreja; e as portas do mundo dos mortos não prevalecerão contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'E a ti darei as chaves do Reino dos céus; e tudo o que ligares na terra terá sido ligado nos céus; e tudo o que desligares na terra terá sido desligado nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Então mandou aos seus discípulos que a ninguém dissessem que ele era Jesus, o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Desde então Jesus começou a mostrar a seus discípulos que ele tinha que ir a Jerusalém, e sofrer muito pelos anciãos, pelos chefes dos sacerdotes, e pelos escribas, e ser morto, e ser ressuscitado ao terceiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'E Pedro o tomou à parte, e começou a repreendê-lo, dizendo: Misericórdia de ti, Senhor! De maneira nenhuma isso te aconteça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mas ele se virou, e disse a Pedro: Para trás de mim, Satanás! Tu és um obstáculo, porque não compreendes as coisas de Deus, mas sim as humanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Então Jesus disse a seus discípulos: Se alguém quiser vir após mim, negue-se a si mesmo, tome sobre si a sua cruz, e siga-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Pois qualquer um que quiser salvar a sua vida a perderá; porém qualquer um que por causa de mim perder a sua vida, este a achará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Pois que proveito há para alguém, se ganhar o mundo todo, mas perder a sua alma? Ou que dará alguém em resgate da sua alma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Pois o Filho do homem virá na glória do seu Pai com os seus anjos, e então recompensará a cada um segundo as suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Em verdade vos digo, que há alguns, dos que aqui estão, que não experimentarão a morte, até que vejam o Filho do homem vir em seu Reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Seis dias depois, Jesus tomou consigo Pedro, Tiago, e seu irmão João, e os levou a sós a um monte alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Então transfigurou-se diante deles; seu rosto brilhou como o sol, e suas roupas se tornaram brancas como a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'E eis que lhes apareceram Moisés e Elias, falando com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Pedro, então, disse a Jesus: Senhor, bom é para nós estarmos aqui. Se queres, façamos aqui três tendas: uma para ti, uma para Moisés, e uma para Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Enquanto ele ainda estava falando, eis que uma nuvem brilhante os cobriu. E eis que uma voz da nuvem disse: Este é o meu Filho amado, em quem me agrado; a ele ouvi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Quando os discípulos ouviram, caíram sobre seus rostos, e tiveram muito medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Jesus se aproximou deles, tocou-os, e disse: Levantai-vos, e não tenhais medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'E quando eles levantaram seus olhos, não viram a ninguém, a não ser a Jesus somente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'E enquanto desciam do monte, Jesus lhes disse a seguinte ordem: Não conteis a visão a ninguém, até que o Filho do homem seja ressuscitado dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'E os seus discípulos lhe perguntaram: Por que, então, os escribas dizem que Elias tem que vir primeiro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jesus lhes respondeu: Em verdade Elias virá primeiro, e restaurará todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Digo-vos, porém, que Elias já veio, mas não o reconheceram. Em vez disso fizeram dele tudo o que quiseram. Assim também o Filho do homem sofrerá por meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Então os discípulos entenderam que ele lhes falara a respeito de João Batista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'E quando chegaram à multidão, veio a ele um homem, que se ajoelhou diante dele, e disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Senhor, tem misericórdia do meu filho, que é epilético, e sofre muito mal; porque cai muitas vezes no fogo, e muitas vezes na água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'E eu o trouxe aos teus discípulos, mas não o puderam curar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jesus respondeu: Ó geração incrédula e perversa! Até quando estarei convosco? Até quando vos suportarei? Trazei-o a mim aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'E Jesus o repreendeu. Então o demônio saiu dele, e o menino sarou desde aquela hora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Depois os discípulos se aproximaram de Jesus em particular, e perguntaram: Por que nós não o pudemos expulsar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'E Jesus lhes respondeu: Por causa da vossa incredulidade; pois em verdade vos digo, que se tivésseis fé como um grão de mostarda, diríeis a este monte: “Passa-te daqui para lá”, E ele passaria. E nada vos seria impossível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Mas este tipo de demônio não sai, a não ser por oração e jejum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'E enquanto eles estavam na Galileia, Jesus lhes disse: O Filho do homem será entregue em mãos de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'E o matarão, e ele será ressuscitado ao terceiro dia.E eles se entristeceram muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'E quando entraram em Cafarnaum, os cobradores da taxa de duas dracmas vieram a Pedro, e perguntaram: Vosso mestre não paga as duas dracmas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Ele respondeu: Sim. Quando ele entrou em casa, Jesus o antecipou, dizendo: Que te parece, Simão? De quem os reis da terra cobram tributos ou taxas? Dos seus filhos, ou dos outros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Pedro lhe respondeu: Dos outros.Jesus lhe disse: Logo, os filhos são livres de pagar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Mas para não os ofendermos, vai ao mar, e lança o anzol. Toma o primeiro peixe que subir, e quando lhe abrir a boca, acharás uma moeda de quatro dracmas. Toma-a, e dá a eles por mim e por ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Naquela hora os discípulos se aproximaram de Jesus, e perguntaram: Ora, quem é o maior no Reino dos céus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Então Jesus chamou a si uma criança, e a pôs no meio deles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'e disse: Em verdade vos digo, que se vós não converterdes, e fordes como crianças, de maneira nenhuma entrareis no Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Assim, qualquer um que for humilde como esta criança, este é o maior no reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'E qualquer um que receber a uma criança como esta em meu nome, recebe a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Mas qualquer um que conduzir ao escândalo a um destes pequeninos que creem em mim, melhor lhe fora que uma grande pedra de moinho lhe fosse pendurada ao pescoço, e se afundasse no fundo do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Ai do mundo por causa dos escândalos! Pois é necessário que os escândalos venham, mas ai daquela pessoa por quem o escândalo vem!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Portanto, se a tua mão ou o teu pé te conduz ao escândalo, corta-os, e lança-os de ti; melhor te é entrar manco ou aleijado na vida do que, tendo duas mãos ou dois pés, ser lançado no fogo eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'E se o teu olho te conduz ao escândalo, arranca-o, e lança-o de ti. Melhor te é entrar com um olho na vida do que, tendo dois olhos, ser lançado no inferno de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Olhai para que não desprezeis a algum destes pequeninos; porque eu vos digo que os seus anjos nos céus sempre veem a face do meu Pai, que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Pois o Filho do homem veio para salvar o que havia se perdido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Que vos parece? Se alguém tivesse cem ovelhas, e uma delas se desviasse, por acaso não iria ele pelos montes, deixando as noventa e nove, em busca da desviada?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'E se acontecesse de achá-la, em verdade vos digo que ele se alegra mais daquela, do que das noventa e nove que se não desviaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Da mesma maneira, não é da vontade do vosso Pai, que está nos céus, que um sequer destes pequeninos se perca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Porém, se teu irmão pecar contra ti, vai repreendê-lo entre ti e ele só; se te ouvir, ganhaste o teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Mas se não ouvir, toma ainda contigo um ou dois, para que toda palavra se confirme pela boca de duas ou três testemunhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'E se não lhes der ouvidos, comunica à igreja; e se também não der ouvidos à igreja, considera-o como gentio e cobrador de impostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Em verdade vos digo que tudo o que vós ligardes na terra será ligado no céu; e tudo o que desligardes na terra será desligado no céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'E digo-vos também que, se dois de vós concordarem na terra acerca de qualquer coisa que pedirem, isso lhes será feito por meu Pai, que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Pois onde dois ou três estiverem reunidos em meu nome, ali eu estou no meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Então Pedro aproximou-se dele, e perguntou: Senhor, até quantas vezes meu irmão pecará contra mim, e eu lhe perdoarei? Até sete?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jesus lhe respondeu: Eu não te digo até sete, mas sim até setenta vezes sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Por isso o Reino dos céus é comparável a um certo rei, que quis fazer acerto de contas com os seus servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'E começando a fazer acerto de contas, foi-lhe apresentado um que lhe devia dez mil talentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Como ele não tinha com que pagar, o seu senhor mandou que ele, sua mulher, filhos, e tudo quanto tinha fossem vendidos para se fazer o pagamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Então aquele servo caiu e ficou prostrado diante dele, dizendo: “Senhor, tem paciência comigo, e tudo te pagarei”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'O senhor daquele servo compadeceu-se dele, então o soltou e lhe perdoou a dívida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Todavia, depois daquele servo sair, achou um servo, colega seu, que lhe devia cem denários; então o agarrou e o sufocou, dizendo: “Paga-me o que me deves!”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Então o seu colega se prostrou diante dos seus pés, e lhe suplicou, dizendo: “Tem paciência comigo, e tudo te pagarei”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Mas ele não quis. Em vez disso foi lançá-lo na prisão até que pagasse a dívida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Quando os servos, colegas dele, viram o que se passava, entristeceram-se muito. Então vieram denunciar ao seu senhor tudo o que havia se passado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Assim o seu senhor o chamou, e lhe disse: “Servo mau! Toda aquela dívida te perdoei, porque me suplicaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Não tinhas tu a obrigação de ter tido misericórdia do sevo colega teu, assim como eu tive misericórdia de ti?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'E, enfurecido, o seu senhor o entregou aos torturadores até que pagasse tudo o que lhe devia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Assim também meu Pai celestial vos fará, se não perdoardes de coração cada um ao seu irmão suas ofensas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'E aconteceu que, quando Jesus acabou estas palavras, partiu da Galileia, e veio para a região da Judeia, além do Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'E muitas multidões o seguiram, e ele os curou ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Então os fariseus se aproximaram dele e, provando-o, perguntaram-lhe: É lícito ao homem se divorciar da sua mulher por qualquer causa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Porém ele lhes respondeu: Não tendes lido que aquele que os fez no princípio, macho e fêmea os fez,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'e disse: Portanto o homem deixará pai e mãe, e se unirá a sua mulher, e os dois serão uma única carne?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Assim eles já não são mais dois, mas sim uma única carne; portanto, o que Deus juntou, o ser humano não separe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Eles lhe disseram: Por que, pois, Moisés mandou lhe dar carta de separação, e divorciar-se dela?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Jesus lhes disse: Por causa da dureza dos vossos corações Moisés vos permitiu divorciardes de vossas mulheres; mas no princípio não foi assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Porém eu vos digo que qualquer um que se divorciar de sua mulher, a não ser por causa de pecado sexual, e se casar com outra, adultera; e o que se casar com a divorciada também adultera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Os seus discípulos lhe disseram: Se assim é a condição do homem com a mulher, não convém se casar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Porém ele lhes disse: Nem todos recebem esta palavra, a não ser aqueles a quem é dado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Pois há castrados que nasceram assim do ventre da mãe; e há castrados que foram castrados pelos homens; e há castrados que castraram a si mesmos por causa do Reino dos céus. Quem pode receber isto,receba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Então lhe trouxeram crianças, para que pusesse as mãos sobre elas e orasse, mas os discípulos os repreendiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Mas Jesus disse: Deixai as crianças, e não as impeçais de vir a mim, porque delas é o Reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Ele pôs as mãos sobre elas, e depois partiu-se dali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'E eis que alguém se aproximou, e perguntou-lhe: Bom Mestre, que bem farei para eu ter a vida eterna?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'E ele lhe disse: Por que me chamas bom? Ninguém há bom, a não ser um: Deus. Porém se queres entrar na vida, guarda os mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Perguntou-lhe ele: Quais?E Jesus respondeu: Não cometerás homicídio, não adulterarás, não furtarás, não darás falso testemunho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'honra ao teu pai e à tua mãe; e amarás ao teu próximo como a ti mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'O rapaz lhe disse: Tenho guardado tudo isso desde a minha juventude. Que me falta ainda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Disse-lhe Jesus: Se queres ser completo, vai, vende o que tens, e dá aos pobres. Assim terás um tesouro no céu. Então vem, segue-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Mas quando o rapaz ouviu esta palavra, foi embora triste, porque tinha muitos bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jesus, então, disse aos seus discípulos: Em verdade vos digo que dificilmente o rico entrará no reino dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Aliás, eu vos digo que é mais fácil um camelo passar pela abertura de uma agulha do que o rico entrar no reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Quando os seus discípulos ouviram isso,espantaram-se muito, e disseram: Quem, pois, pode se salvar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jesus olhou para eles,e lhes respondeu: Para os seres humanos, isto é impossível; mas para Deus tudo é possível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Então Pedro se pôs a falar, e lhe perguntou: Eis que deixamos tudo, e te seguimos; o que, pois, conseguiremos ter?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'E Jesus lhes disse: Em verdade vos digo que vós que me seguistes, na regeneração, quando o Filho do homem se sentar no trono de sua glória, vós também vos sentareis sobre doze tronos, para julgar as doze tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'E qualquer um que houver deixado casas, ou irmãos, ou irmãs, ou pai, ou mãe, ou mulher, ou filhos, ou terras por causa do meu nome, receberá cem vezes tanto, e herdará a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Porém muitos primeiros serão últimos; e últimos, primeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Pois o reino dos céus é semelhante a um homem, dono de propriedade, que saiu de madrugada para empregar trabalhadores para a sua vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Ele entrou em acordo com os trabalhadores por um denário ao dia, e os mandou à sua vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'E quando saiu perto da hora terceira, viu outros que estavam desocupados na praça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Então disse-lhes: “Ide vós também à vinha, e vos darei o que for justo”. E eles foram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Saindo novamente perto da hora sexta e nona, fez o mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'E quando saiu perto da décima primeira hora, achou outros que estavam desocupados, e lhes perguntou: “Por que estais aqui o dia todo desocupados?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Eles lhe disseram: “Porque ninguém nos empregou”. Ele lhes respondeu: “Ide vós também à vinha, e recebereis o que for justo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'E chegando o anoitecer, o senhor da vinha disse ao seu mordomo: “Chama aos trabalhadores, e paga-lhes o salário, começando dos últimos, até os primeiros”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Então vieram os de cerca da hora décima primeira, e receberam um denário cada um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Quando os primeiros vieram, pensavam que receberiam mais; porém eles também receberam um denário cada um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Assim, ao receberem, murmuraram contra o chefe de casa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'dizendo: “Estes últimos trabalharam uma única hora, e tu os igualaste conosco, que suportamos a carga e o calor do dia”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Ele, porém, respondeu a um deles: “Amigo, nada de errado estou fazendo contigo. Não concordaste tu comigo por um denário?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Toma o que é teu, e vai embora; e quero dar a este último tanto quanto a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Acaso não me é lícito fazer do que é meu o que eu quiser? Ou o teu olho é mau, porque eu sou bom?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Assim os últimos serão primeiros; e os primeiros, últimos; pois muitos são chamados, mas poucos escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'E enquanto Jesus subia a Jerusalém, tomou consigo os doze discípulos à parte no caminho, e lhes disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Eis que estamos subindo a Jerusalém, e o Filho do homem será entregue aos chefes dos sacerdotes e aos escribas, e o condenarão à morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'E o entregarão aos gentios, para que dele escarneçam, e o açoitem, e crucifiquem; mas ao terceiro dia ressuscitará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Então se aproximou dele a mãe dos filhos de Zebedeu, com os seus filhos. Ela o adorou para lhe pedir algo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'E ele lhe perguntou: O que queres? Ela lhe disse: Dá ordem para que estes meus dois filhos se sentem, um à tua direita e outro à tua esquerda, no teu Reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Porém Jesus respondeu: Não sabeis o que pedis. Podeis vós beber o cálice que eu beberei, e ser batizados com o batismo com que eu sou batizado? Eles lhe disseram: Podemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'E ele lhes disse: De fato meu cálice bebereis, e com o batismo com que eu sou batizado sereis batizados; mas sentar-se à minha direita, e à minha esquerda, não me cabe concedê-lo, mas será para os que por meu Pai está preparado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'E quando os dez ouviram isso,indignaram-se contra os dois irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Então Jesus os chamou a si, e disse: Vós bem sabeis que os chefes dos gentios os dominam, e os grandes usam de autoridade sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Mas não será assim entre vós. Ao contrário, quem quiser se tornar grande entre vós seja o vosso assistente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'e quem quiser ser o primeiro entre vós seja o vosso servo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'assim como o Filho do homem não veio para ser servido, mas sim para servir, e para dar a sua vida em resgate por muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Quando eles saíram de Jericó, uma grande multidão o seguiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'E eis que dois cegos assentados junto ao caminho, ao ouvirem que Jesus passava, clamaram: Senhor, Filho de Davi, tem misericórdia de nós!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'E a multidão os repreendia, para que se calassem, mas eles clamavam ainda mais: Senhor, Filho de Davi, tem misericórdia de nós!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Então Jesus parou, chamou-os, e perguntou: Que quereis que eu vos faça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Eles lhe responderam: Senhor, que nossos olhos sejam abertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'E Jesus, compadecido deles, tocou-lhes os olhos. E logo os olhos deles enxergaram, e o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'E quando se aproximaram de Jerusalém, e chegaram a Betfagé, ao monte das Oliveiras, então Jesus mandou dois discípulos, dizendo-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Ide à aldeia em vossa frente, e logo achareis uma jumenta amarrada, e um jumentinho com ela; desamarra-a, e trazei-os a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'E se alguém vos disser algo, direis: “O Senhor precisa deles, mas logo os devolverá”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Ora, tudo isto aconteceu para que se cumprisse o que foi dito pelo profeta, que disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Dizei à filha de Sião: “Eis que o teu rei vem a ti, manso, e sentado sobre um jumento; um jumentinho, filho de uma animal de carga”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Os discípulos foram, e fizeram como Jesus havia lhes mandado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Então trouxeram a jumenta e o jumentinho, puseram as suas capas sobre eles, e fizeram -no montar sobre elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'E uma grande multidão estendia suas roupas pelo caminho, e outros cortavam ramos das árvores, e os espalhavam pelo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'E as multidões que iam adiante, e as que seguiam, clamavam: Hosana ao Filho de Davi! Bendito o que vem no nome do Senhor! Hosana nas alturas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Enquanto ele entrava em Jerusalém, toda a cidade se alvoroçou, perguntando: Quem é este?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'E as multidões respondiam: Este é Jesus, o Profeta de Nazaré de Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Jesus entrou no Templo de Deus; então expulsou todos os que estavam vendendo e comprando no Templo, e virou as mesas dos cambistas e as cadeiras dos que vendiam pombas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'E disse-lhes: Está escrito: “Minha casa será chamada casa de oração”; mas vós a tornastes em covil de ladrões!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'E cegos e mancos vieram a ele no Templo, e ele os curou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Quando os chefes dos sacerdotes e os escribas viram as maravilhas que ele fazia, e as crianças gritando no Templo: “Hosana ao Filho de Davi!”, eles ficaram indignados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'E perguntaram-lhe: Ouves o que estas crianças dizem?E Jesus lhes respondeu: Sim. Nunca lestes: “Da boca das crianças e dos bebês providenciaste o louvor?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Então ele os deixou, e saiu da cidade para Betânia, e ali passou a noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'E pela manhã, enquanto voltava para a cidade, teve fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Quando ele viu uma figueira perto do caminho, veio a ela, mas nada nela achou, a não ser somente folhas. E disse-lhe: Nunca de ti nasça fruto, jamais!E imediatamente a figueira se secou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Os discípulos viram, e ficaram maravilhados, dizendo: Como a figueira se secou de imediato?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Porém Jesus lhes respondeu: Em verdade vos digo: se tiverdes fé, e não duvidardes, vós não somente fareis isto à figueira, mas até se disserdes a este monte: “Levanta-te, e lança-te no mar”, isso se fará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'E tudo o que pedirdes em oração, crendo, recebereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Depois de entrar no templo, quando ele estava ensinando, os chefes dos sacerdotes e os anciãos do povo se aproximaram dele, perguntando: Com que autoridade fazes isto? E quem te deu esta autoridade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jesus lhes respondeu: Eu também vos farei uma pergunta. Se vós a responderdes a mim, também eu vos responderei com que autoridade faço isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'De onde era o batismo de João? Do céu, ou dos seres humanos?E eles pensaram entre si mesmos, dizendo: Se dissermos: “Do céu”, ele nos dirá: “Por que, então, não crestes nele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Mas se dissermos: “Dos seres humanos”, temos medo da multidão, pois todos consideram João como profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Então responderam a Jesus: Não sabemos. E ele lhes disse: Nem eu vos digo com que autoridade faço isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Mas que vos parece? Um homem tinha dois filhos. Aproximando-se do primeiro, disse: “Filho, vai hoje trabalhar na minha vinha.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Porém ele respondeu: “Não quero”; mas depois se arrependeu, e foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'E, aproximando-se do segundo, disse da mesma maneira. E ele respondeu: “Eu vou,senhor”, mas não foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Qual dos dois fez a vontade do pai?Eles lhe responderam: O primeiro. Jesus lhes disse: Em verdade vos digo que os cobradores de impostos e as prostitutas estão indo adiante de vós ao Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Pois João veio a vós mesmos no caminho de justiça, mas não crestes nele; enquanto que os cobradores de impostos e as prostitutas nele creram. Vós, porém, mesmo tendo visto isto,nem assim vos arrependestes, a fim de nele crer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Ouvi outra parábola. Havia um homem, dono de uma propriedade. Ele plantou uma vinha, cercou- a, fundou nela um lagar, e construiu uma torre. Depois a arrendou a uns lavradores, e partiu-se para um lugar distante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Quando chegou o tempo dos frutos, enviou seus servos aos lavradores, para receberem os frutos que a ele pertenciam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Mas os lavradores tomaram os seus servos, e feriram um, mataram outro, e apedrejaram outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Outra vez enviou outros servos, em maior número que os primeiros, mas fizeram-lhes o mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'E por último lhes enviou o seu filho, dizendo: “Respeitarão ao meu filho”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mas quando os lavradores viram o filho, disseram entre si: “Este é o herdeiro. Venhamos matá-lo, e tomemos a sua herança”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Então o agarraram, lançaram-no para fora da vinha, e o mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Ora, quando o senhor da vinha chegar, o que fará com aqueles lavradores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Eles lhe responderam: Aos maus dará uma morte má, e arrendará a vinha a outros lavradores, que lhe deem os frutos em seus tempos de colheita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jesus lhes disse: Nunca lestes nas Escrituras: “A pedra que os construtores rejeitaram, essa se tornou cabeça da esquina. Isto foi feito pelo Senhor, e é maravilhoso aos nossos olhos”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Portanto eu vos digo que o reino de Deus será tirado de vós, e será dado a um povo que produza os frutos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'E quem cair sobre esta pedra será quebrado; mas sobre quem ela cair, ela o tornará em pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Quando os chefes dos sacerdotes e os fariseus ouviram estas suas parábolas, entenderam que Jesus estava falando deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'E procuravam prendê-lo, mas temeram as multidões, pois elas o consideravam profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Então Jesus voltou a lhes falar por parábolas, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'O reino dos céus é semelhante a um rei que fez uma festa de casamento para o seu filho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'e mandou a seus servos que chamassem os convidados para a festa de casamento, mas não quiseram vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Outra vez ele mandou outros servos, dizendo: “Dizei aos convidados: ‘Eis que já preparei meu jantar: meus bois e animais cevados já foram mortos, e tudo está pronto. Vinde à festa de casamento’”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Porém eles não deram importância e foram embora, um ao seu campo, e outro ao seu comércio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'e outros agarraram os servos dele, e os humilharam e os mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Quando o rei Então enviou os seus exércitos, destruiu aqueles homicidas, e incendiou a cidade deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Em seguida, disse aos seus servos: “Certamente a festa de casamento está pronta, porém os convidados não eram dignos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Ide, pois, às saídas dos caminhos, e convidai à festa de casamento tantos quantos achardes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Aqueles servos saíram pelos caminhos, e ajuntaram todos quantos acharam, tanto maus como bons; e a festa de casamento se encheu de convidados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Mas quando o rei entrou para ver os convidados, percebeu ali um homem que não estava vestido com roupa adequada para a festa de casamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Então lhe perguntou: “Amigo, como entraste aqui sem ter roupa para a festa?” E ele emudeceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Então o rei disse aos servos: “Amarrai-o nos pés e nas mãos, tomai-o, e lançai-o nas trevas de fora. Ali haverá pranto e o ranger de dentes”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Pois muitos são chamados, porém poucos escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Então os fariseus foram embora, e se reuniram para tramar como o apanhariam em cilada por algo que dissesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Depois lhe enviaram seus discípulos, juntamente com os apoiadores de Herodes, e perguntaram: Mestre, bem sabemos que tu és verdadeiro, e que com verdade ensinas o caminho de Deus, e que não te importas com a opinião de ninguém, porque não dás atenção à aparência humana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Dize-nos, pois, o que te parece: é lícito dar tributo a César, ou não?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Mas Jesus, entendendo a sua malícia, disse: Por que me tentais, hipócritas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Mostrai-me a moeda do tributo.E eles lhe trouxeram um denário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'E ele lhes perguntou: De quem é esta imagem, e a inscrição?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Eles lhe responderam: De César. Então ele lhes disse: Dai, pois, a César o que é de César, e a Deus o que é de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Quando ouviram isso, eles ficaram admirados; então o deixaram e se retiraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Naquele mesmo dia chegaram a ele os saduceus, que dizem não haver ressurreição, e perguntaram-lhe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'dizendo: Mestre, Moisés disse: Se um homem morrer sem ter filhos, seu irmão se casará com sua mulher, e gerará descendência ao seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Ora, havia entre nós sete irmãos. O primeiro se casou, e depois morreu; e sem ter tido filhos, deixou sua mulher ao seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'E da mesma maneira também foi com o segundo, o terceiro, até os sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Por último, depois de todos, a mulher também morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Assim, na ressurreição, a mulher será de qual dos sete? Pois todos a tiveram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jesus, porém, lhes respondeu: Errais, por não conhecerdes as Escrituras, nem o poder de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Porque na ressurreição, nem se tomam, nem se dão em casamento; mas são como os anjos de Deus no céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'E sobre a ressurreição dos mortos, não lestes o que Deus vos falou:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó? Deus não é Deus dos mortos, mas sim dos vivos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Quando as multidões ouviram isto,ficaram admiradas de sua doutrina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'E os fariseus, ao ouvirem que ele havia feito os saduceus se calarem, reuniram-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'E um deles, especialista da Lei, tentando-o, perguntou-lhe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Mestre, qual é o grande mandamento na Lei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'E Jesus lhe respondeu: Amarás ao Senhor teu Deus com todo o teu coração, com toda a tua alma, e com todo o teu entendimento:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'este é o primeiro e grande mandamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'E o segundo, semelhante a este, é: Amarás o teu próximo como a ti mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Destes dois mandamentos dependem toda a Lei e os Profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'E, estando os fariseus reunidos, Jesus lhes perguntou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'dizendo: Que pensais vós acerca do Cristo? De quem ele é filho? Eles lhe responderam: De Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Jesus lhes disse: Como, pois, Davi, em espírito, o chama Senhor, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Disse o Senhor a meu Senhor: “Senta-te à minha direita, até que eu ponha os teus inimigos como estrado de teus pés”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Ora, se Davi o chama Senhor, como é seu filho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'E ninguém podia lhe responder palavra; nem ninguém ousou desde aquele dia a mais lhe perguntar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Então Jesus falou às multidões e aos seus discípulos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'dizendo: Os escribas e os fariseus se sentam sobre o assento de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Portanto, tudo o que eles vos disserem que guardeis, guardai, e fazei. Mas não façais segundo as suas obras, porque eles dizem e não fazem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Pois eles amarram cargas pesadas e difíceis de levar, e as põem sobre os ombros das pessoas; porém eles nem sequer com o seu dedo as querem mover.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'E fazem todas as suas obras a fim de serem vistos pelas pessoas: por isso alargam seus filactérios,) e fazem compridas as franjas de suas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Eles amam os primeiros assentos nas ceias, as primeiras cadeiras nas sinagogas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'as saudações nas praças, e serem chamados: “Rabi, Rabi” pelas pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Mas vós, não sejais chamados Rabi, porque o vosso Mestre é um: o Cristo; e todos vós sois irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'E não chameis a ninguém na terra vosso pai; porque o vosso Pai é um: aquele que está nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Nem sejais chamados mestres; porque o vosso mestre é um: o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Porém o maior de vós será vosso servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'E o que a si mesmo se exaltar será humilhado; e o que a si mesmo se humilhar será exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Mas ai de vós, escribas e fariseus, hipócritas! Porque fechais o Reino dos céus em frente das pessoas; pois nem vós entrais, nem permitis a entrada do que estão para entrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Ai de vós, escribas e fariseus, hipócritas! Porque devorais as casas das viúvas, e isso com pretexto de longas orações; por isso recebereis mais grave condenação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Ai de vós, escribas e fariseus, hipócritas! Porque rodeais o mar e a terra para fazerdes um prosélito; e quando é feito, vós o tornais filho do inferno duas vezes mais que a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Ai de vós, guias cegos, que dizeis: “Qualquer um que jurar pelo templo, nada é; mas qualquer um que jurar pelo ouro do templo, devedor é”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Tolos e cegos! Pois qual é maior: o ouro, ou o templo que santifica o ouro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Também dizeis: “Qualquer um que jurar pelo altar, nada é; mas quem jurar pela oferta que está sobre ele, devedor é”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Tolos e cegos! Pois qual é maior: a oferta, ou o altar que santifica a oferta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Portanto, quem jurar pelo altar, jura por ele, e por tudo o que está sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'E quem jurar pelo templo, jura por ele, e por aquele que nele habita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'E quem jurar pelo Céu, jura pelo trono de Deus, e por aquele que sobre ele está sentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Ai de vós, escribas e fariseus, hipócritas! Porque dais o dízimo da hortelã, do endro, e do cominho, e desprezais o que é mais importante da Lei: a justiça, a misericórdia, e a fidelidade; estas coisas devem ser feitas, sem se desprezar as outras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Guias cegos, que coais um mosquito, e engolis um camelo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Ai de vós, escribas e fariseus, hipócritas! Porque limpais o exterior do copo ou do prato, mas por dentro estão cheios de extorsão e cobiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Fariseu cego! Limpa primeiro o interior do copo e do prato, para que também o exterior deles fique limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Ai de vós, escribas e fariseus, hipócritas! Porque sois semelhantes aos sepulcros caiados, que por fora realmente parecem belos, mas por dentro estão cheios de ossos de cadáveres, e de toda imundícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Assim também vós, por fora, realmente pareceis justos às pessoas, mas por dentro estais cheios de hipocrisia e de injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Ai de vós, escribas e fariseus, hipócritas! Porque edificais os sepulcros dos profetas, adornais os monumentos dos justos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'e dizeis: “Se estivéssemos nos dias dos nossos pais, nunca teríamos sido cúmplices deles quando derramaram o sangue dos profetas”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Assim vós mesmos dais testemunho de que sois filhos dos que mataram os profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Completai, pois, a medida de vossos pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Serpentes, ninhada de víboras! Como escapareis da condenação do inferno?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Por isso, eis que eu vos envio profetas, sábios, e escribas; a uns deles matareis e crucificareis, e a outros deles açoitareis em vossas sinagogas, e perseguireis de cidade em cidade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'para que venha sobre vós todo o sangue justo que foi derramado sobre a terra, desde o sangue do justo Abel, até o sangue de Zacarias, filho de Baraquias, ao qual matastes entre o templo e o altar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Em verdade vos digo que tudo isto virá sobre esta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalém, Jerusalém, que matas os profetas, e apedrejas os que te são enviados! Quantas vezes eu quis ajuntar os teus filhos, como a galinha ajunta os seus pintos debaixo das asas; porém não quisestes!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Eis que vossa casa vos será deixada desolada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Pois eu vos digo que a partir de agora não me vereis, até que digais: “Bendito aquele que vem no nome do Senhor”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Jesus saiu do templo, e se foi. Então seus discípulos se aproximaram dele para lhe mostrarem os edifícios do complexo do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Mas Jesus lhes disse: Não vedes tudo isto? Em verdade vos digo, que não será deixada aqui pedra sobre pedra, que não seja derrubada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'E, depois de se assentar no monte das Oliveiras, os discípulos se aproximaram dele reservadamente, perguntando: Dize-nos, quando serão estas coisas, e que sinal haverá da tua vinda, e do fim da era?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'E Jesus lhes respondeu: Permanecei atentos, para que ninguém vos engane.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Porque muitos virão em meu nome, dizendo: “Eu sou o Cristo”, e enganarão a muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'E ouvireis de guerras, e de rumores de guerras. Olhai que não vos espanteis; porque é necessário, que tudo isto aconteça, mas ainda não é o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Pois se levantará nação contra nação, e reino contra reino; e haverá fomes, pestilências, e terremotos em diversos lugares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Mas todas estas coisas são o começo das dores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Então vos entregarão para serdes afligidos, e vos matarão; e sereis odiados por todas as nações, por causa de meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'E muitos se tornarão infiéis; e trairão uns aos outros, e uns aos outros se odiarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'E muitos falsos profetas se levantarão, e enganarão a muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'E, por se multiplicar a injustiça, o amor de muitos se esfriará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Mas o que perseverar até o fim, esse será salvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'E este Evangelho do Reino será pregado em todo o mundo, como testemunho a todas as nações, e então virá o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Portanto, quando virdes que a abominação da desolação, dita pelo profeta Daniel, está no lugar santo, (quem lê, entenda),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'então os que estiveram na Judeia fujam para os montes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'o que estiver no sobre o telhado não desça para tirar alguma coisa de sua casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'e o que estiver no campo não volte atrás para tomar as suas roupas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Mas ai das grávidas e das que amamentarem naqueles dias!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Orai, porém, para que a vossa fuga não aconteça no inverno, nem no sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Pois haverá então grande aflição, como nunca houve desde o princípio do mundo até agora, nem jamais haverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'E se aqueles dias não fossem encurtados, ninguém se salvaria; mas por causa dos escolhidos, aqueles dias serão encurtados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Então, se alguém vos disser: “Olha o Cristo aqui”, ou “Olha ele ali”, não creiais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'pois se levantarão falsos cristos e falsos profetas; e farão tão grandes sinais e prodígios que, se fosse possível, enganariam até os escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Eis que eu tenho vos dito com antecedência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Portanto, se vos disserem: “Eis que ele está no deserto”, não saiais; “Eis que ele está em um recinto”, não creiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Porque, assim como o relâmpago, que sai do oriente, e aparece até o ocidente, assim também será a vinda do Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Pois onde estiver o cadáver, ali se ajuntarão os abutres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'E logo depois da aflição daqueles dias, o sol se escurecerá, a lua não dará o seu brilho, as estrelas cairão do céu, e as forças dos céus se estremecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Então aparecerá no céu o sinal do Filho do homem. Naquela hora todas as tribos da terra lamentarão, e verão ao Filho do homem, que vem sobre as nuvens do céu, com poder e grande glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'E enviará os seus anjos com grande som de trombeta, e ajuntarão os seus escolhidos desde os quatro ventos, de uma extremidade à outra dos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Aprendei a parábola da figueira: “Quando os seus ramos já ficam verdes, e as folhas brotam, sabeis que o verão está perto”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Assim também vós, quando virdes todas estas coisas, sabei que já está perto, às portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Em verdade vos digo que esta geração não passará, até que todas estas coisas aconteçam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'O céu e a terra passarão, mas minhas palavras de maneira nenhuma passarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Porém daquele dia e hora, ninguém sabe, nem os anjos do céu, a não ser meu Pai somente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Assim como foram os dias de Noé, assim também será a vinda do Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Pois, assim como nos dias antes do dilúvio comiam, bebiam, casavam, e davam-se em casamento, até o dia em que Noé entrou na arca;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'e não sabiam, até que veio o dilúvio, e levou todos, assim também será a vinda do Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Naquela hora dois estarão no campo; um será tomado, e o outro será deixado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Duas estarão moendo em um moinho; uma será tomada, e a outra será deixada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Vigiai, pois, porque não sabeis em que hora o vosso Senhor virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Porém sabei isto: se o dono de casa soubesse a que hora da noite o ladrão viria, vigiaria, e não deixaria invadir a sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Portanto também vós estai prontos, porque o Filho do homem virá na hora que não esperais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Pois quem é o servo fiel e prudente, ao qual o seu senhor pôs sobre os seus trabalhadores, para lhes dar alimento no tempo devido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Feliz será aquele servo a quem, quando o seu senhor vier, achar fazendo assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Em verdade vos digo que ele o porá sobre todos os seus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Porém se aquele servo mau disser em seu coração: “Meu senhor está demorando a chegar”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'e começar a espancar os servos companheiros seus, e a comer, e a beber com os beberrões,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'o senhor daquele servo chegará num dia que ele não espera, e numa hora que ele não sabe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'e o despedaçará, e porá sua parte com os hipócritas; ali haverá pranto e ranger de dentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Então o Reino dos céus será semelhante a dez virgens, que tomaram suas lâmpadas, e saíram ao encontro do noivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'E cinco delas eram prudentes, e cinco tolas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'As tolas, quando tomaram as suas lâmpadas, não tomaram azeite consigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Mas as prudentes tomaram azeite nos seus frascos, com as suas lâmpadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'O noivo demorou, por isso todas cochilaram e adormeceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Mas à meia-noite houve um grito: “Eis que vem o noivo! Ide ao seu encontro!”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Então todas aquelas virgens se levantaram, e prepararam suas lâmpadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'E as tolas disseram às prudentes: “Dai-nos do vosso azeite, porque as nossas lâmpadas estão se apagando”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Mas as prudentes responderam: “Não,para que não falte a nós e a vós; em vez disso, ide aos vendedores, e comprai para vós mesmas”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Enquanto elas foram comprar, veio o noivo. As que estavam preparadas entraram com ele à festa do casamento, e fechou-se a porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Depois vieram também as outras virgens, dizendo: “Senhor, Senhor, abre-nos!”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mas ele respondeu: “Em verdade vos digo que não vos conheço”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Portanto, vigiai, porque não sabeis o dia nem a hora em que o Filho do homem virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Pois é como um homem, que partindo-se para fora do país, chamou seus servos, e lhes entregou os seus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'E a um deu cinco talentos, a outro dois, e ao terceiro um, a cada um conforme a sua habilidade, e logo depois partiu em viagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Em seguida, o que havia recebido cinco talentos foi fazer negócios com eles, e obteve outros cinco talentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'E, semelhantemente, o que havia recebido dois ganhou também outros dois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mas o que tinha recebido um foi cavar a terra, e escondeu o dinheiro do seu senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Muito tempo depois, o senhor daqueles servos veio, e fez contas com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'O que havia recebido cinco talentos chegou lhe trazendo outros cinco talentos, e disse:”Senhor, cinco talentos me entregaste, eis que ganhei com eles outros cinco talentos”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'E o seu senhor lhe disse: “Muito bem, servo bom e fiel! Sobre o pouco foste fiel, sobre o muito te porei; entra na alegria do teu senhor”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'E chegando-se também o que havia recebido dois talentos, disse: “Senhor, dois talentos me entregaste, eis que ganhei com eles outros dois talentos”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Seu senhor lhe disse: “Muito bem, servo bom e fiel! Sobre o pouco foste fiel, sobre o muito te porei; entra na alegria do teu senhor”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Mas, chegando também o que havia recebido um talento, disse: “Senhor, eu te conhecia, que és homem duro, que colhes onde não semeaste, e ajuntas onde não espalhaste;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'E eu, atemorizado, fui e escondi o teu talento na terra; eis aqui tens o que é teu”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Porém seu senhor lhe respondeu: “Servo mau e preguiçoso! Sabias que colho onde não semeei, e ajunto onde não espalhei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Devias, portanto, ter depositado o meu dinheiro como os banqueiros e, quando eu voltasse, receberia o que é meu com juros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Por isso, tirai dele o talento, e dai-o ao que tem dez talentos”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Pois a todo aquele que tiver, lhe será dado, e terá em abundância; porém ao que não tiver, até o que tem lhe será tirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, '“E lançai o servo inútil às trevas de fora (ali haverá pranto e ranger de dentes)”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'E quando o Filho do homem vier em sua glória, e todos os santos anjos com ele, então ele se assentará sobre o trono de sua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'E serão ajuntadas diante dele todas as nações, e separará as pessoas umas das outras, assim como o pastor separa as ovelhas dos bodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'E porá as ovelhas à sua direita, porém os bodes à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Então o Rei dirá o rei aos que estiverem à sua direita: “Vinde, benditos de meu Pai! Herdai o Reino que está preparado para vós desde a fundação do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Pois tive fome, e me destes de comer; tive sede, e me destes de beber; fui forasteiro, e me acolhestes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'estive nu, e me vestistes; estive doente, e cuidastes de mim; estive na prisão, e me visitastes”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Então os justos lhe perguntarão: “Senhor, quando te vimos com fome, e te demos de comer, ou com sede, e te demos de beber?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'E quando te vimos forasteiro, e te acolhemos, ou nu, e te vestimos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'E quando te vimos doente, ou na prisão, e viemos te visitar?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'E o Rei lhes responderá: “Em verdade vos digo que, todas as vezes que fizestes a um destes menores dos meus irmãos, fizestes a mim”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Então dirá também aos que estiverem à esquerda: “Apartai-vos de mim, malditos, ao fogo eterno, preparado para o Diabo e os seus anjos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Pois tive fome, e não me destes de comer; tive sede, e não me destes de beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Fui forasteiro, e não me acolhestes; estive nu, e não me vestistes; estive doente, e na prisão, e não me visitastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Então também eles lhe perguntarão: “Senhor, quando te vimos com fome, ou com sede, ou forasteiro, ou nu, ou doente, ou na prisão, e não te servimos?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Então ele lhes responderá, dizendo: “Em verdade vos digo que, todas as vezes que não fizestes a um destes menores, não fizestes a mim”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'E estes irão ao tormento eterno, porém os justos à vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'E aconteceu que, quando Jesus terminou todas estas palavras, disse aos seus discípulos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Vós bem sabeis que daqui a dois dias é a Páscoa, e o Filho do homem será entregue para ser crucificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Então os chefes dos sacerdotes, os escribas, e os anciãos do povo se reuniram na casa do sumo sacerdote, que se chamava Caifás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'E conversaram a fim de, usando mentira, prenderem Jesus, e o matarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Porém diziam: Não na festa, para que não haja tumulto entre o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Enquanto Jesus estava em Betânia, na casa de Simão o leproso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'veio a ele uma mulher com um vaso de alabastro, de óleo perfumado de grande valor, e derramou sobre a cabeça dele, enquanto estava sentado à mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'E quando os seus discípulos viram, ficaram indignados, dizendo: Para que este desperdício?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Pois esse óleo perfumado podia ter sido vendido por muito, e o dinheiro dado aos pobres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Porém Jesus, sabendo disso,disse-lhes: Por que perturbais a esta mulher? Ora, ela me fez uma boa obra!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Pois vós sempre tendes os pobres convosco, porém nem sempre me tereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Pois ela, ao derramar este óleo perfumado sobre o meu corpo, ela o fez para preparar o meu sepultamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Em verdade vos digo que, onde quer que este Evangelho em todo o mundo for pregado, também se dirá o que ela fez, para que seja lembrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Então um dos doze, chamado Judas Iscariotes, foi aos chefes dos sacerdotes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'e disse: O que quereis me dar, para que eu o entregue a vós? E eles lhe determinaram trinta moedas de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'E desde então ele buscava oportunidade para o entregar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'E no primeiro dia da festa dos pães sem fermento, os discípulos vieram a Jesus lhe perguntar: Onde queres que te preparemos para comer a Páscoa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'E ele respondeu: Ide à cidade a um tal, e dizei-lhe: “O Mestre diz: ‘Meu tempo está perto. Contigo celebrarei a Páscoa com os meus discípulos’”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Os discípulos fizeram como Jesus havia lhes mandado, e prepararam a Páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'E vindo o anoitecer, ele se assentou à mesa com os doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'E enquanto comiam, disse: Em verdade vos digo que um de vós me trairá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Eles ficaram muito tristes, e cada um deles começou a lhe perguntar: Por acaso sou eu, Senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'E ele respondeu: O que mete comigo a mão no prato, esse me trairá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'De fato, o Filho do homem vai assim como dele está escrito; mas ai daquele homem por quem o Filho do homem é traído! Bom seria a tal homem se não houvesse nascido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'E Judas, o que o traía, perguntou: Por acaso sou eu, Rabi? Jesus lhe disse: Tu o disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'E enquanto comiam, Jesus tomou o pão, abençoou-o, e o partiu. Então o deu aos discípulos, e disse: Tomai, comei; isto é o meu corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Em seguida tomou o cálice, deu graças, e o deu a eles, dizendo: Bebei dele todos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'porque este é o meu sangue, o sangue do novo testamento, o qual é derramado por muitos, para o perdão de pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'E eu vos digo que desde agora não beberei deste fruto da vide, até aquele dia, quando convosco o beber, novo, no reino do meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'E depois de cantarem um hino, saíram para o monte das Oliveiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Então Jesus lhes disse: Todos vós vos falhareis em serdes fiéis a mim esta noite; porque está escrito: “Ferirei o pastor, e as ovelhas do rebanho serão dispersas”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Mas, depois que eu for ressuscitado, irei adiante de vós para a Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Pedro, porém, respondeu-lhe: Ainda que todos falhem contigo, eu nunca falharei em minha fidelidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jesus lhe disse: Em verdade te digo que, nesta mesma noite, antes do galo cantar, tu me negarás três vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pedro lhe respondeu: Ainda que eu tenha de morrer contigo, em nenhuma maneira te negarei. E todos os discípulos disseram o mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Então Jesus veio com eles a um lugar chamado Getsêmani, e disse aos discípulos: Ficai sentados aqui, enquanto eu vou ali orar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Enquanto trazia consigo Pedro e os dois filhos de Zebedeu, ele começou a se entristecer e a se angustiar muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Então lhes disse: Minha alma está completamente triste até a morte. Ficai aqui, e vigiai comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'E indo um pouco mais adiante, prostrou-se sobre o seu rosto, orando, e dizendo: Meu Pai, se é possível, passe de mim este cálice; porém, não seja como eu quero, mas sim como tu queres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Então voltou aos seus discípulos, e os encontrou dormindo; e disse a Pedro: Então, nem sequer uma hora pudestes vigiar comigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Vigiai e orai, para que não entreis em tentação. De fato, o espírito está pronto, mas a carne é fraca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Ele foi orar pela segunda vez, dizendo: Meu Pai, se este cálice não pode passar de mim sem que eu o beba, faça-se a tua vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Quando voltou, achou-os outra vez dormindo, pois os seus olhos estavam pesados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Então os deixou, e foi orar pela terceira vez, dizendo as mesmas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Depois veio aos seus discípulos, e disse-lhes: Agora dormi e descansai. Eis que chegou a hora em que o Filho do homem é entregue em mãos de pecadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Levantai-vos, vamos! Eis que chegou o que me trai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Enquanto ele ainda estava falando, eis que veio Judas, um dos doze, e com ele uma grande multidão, com espadas e bastões, da parte dos chefes dos sacerdotes e dos anciãos do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'O seu traidor havia lhes dado sinal, dizendo: Aquele a quem eu beijar, é esse. Prendei-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Logo ele se aproximou de Jesus, e disse: Felicitações, Rabi! e o beijou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jesus, porém, lhe perguntou: Amigo, para que vieste? Então chegaram, agarraram Jesus, e o prenderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'E eis que um dos que estavam com Jesus estendeu a mão, puxou de sua espada, e feriu o servo do sumo sacerdote, cortando-lhe uma orelha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Jesus, então, lhe disse: Põe de volta tua espada ao seu lugar, pois todos os que pegarem espada, pela espada perecerão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Ou, por acaso, pensas tu que eu não posso agora orar ao meu Pai, e ele me daria mais de doze legiões de anjos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Como, pois, se cumpririam as Escrituras que dizem que assim tem que ser feito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Naquela hora Jesus disse às multidões: Como a um ladrão saístes com espadas e bastões para me prender? Todo dia eu me sentava convosco, ensinando no templo, e não me prendestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Porém tudo isto aconteceu para que as Escrituras dos profetas se cumpram.Então todos os discípulos o abandonaram, e fugiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Os que prenderam Jesus o trouxeram à casa de Caifás, o sumo sacerdote, onde os escribas e os anciãos estavam reunidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'E Pedro o seguia de longe, até o pátio do sumo sacerdote; e entrou, e se assentou com os servos, para ver o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Os chefes dos sacerdotes, os anciãos, e todo o conselho buscavam falso testemunho contra Jesus, para poderem matá-lo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'mas não encontravam. E ainda que muitas falsas testemunhas se apresentavam, contudo não encontravam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Mas, por fim, vieram duas falsas testemunhas, que disseram: Este disse: “Posso derrubar o Templo de Deus e reconstruí-lo em três dias”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Então o sumo sacerdote se levantou, e lhe perguntou: Não respondes nada ao que eles testemunham contra ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Porém Jesus ficava calado. Então o sumo sacerdote lhe disse: Ordeno-te pelo Deus vivo que nos digas se tu és o Cristo, o Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jesus lhe disse: Tu o disseste. Porém eu vos digo que, desde agora, vereis o Filho do homem, sentado à direita do Poderoso, e vindo sobre as nuvens do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Então o sumo sacerdote rasgou suas roupas, e disse: Ele blasfemou! Para que necessitamos mais de testemunhas? Eis que agora ouvistes a sua blasfêmia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Que vos parece?E eles responderam: Culpado de morte ele é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Então lhe cuspiram no rosto, e lhe deram socos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Outros lhe deram bofetadas, e diziam: Profetiza-nos, ó Cristo, quem é o que te feriu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Pedro estava sentado fora no pátio. Uma serva aproximou-se dele, e disse: Também tu estavas com Jesus, o galileu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Mas ele o negou diante de todos, dizendo: Não sei o que dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'E quando ele saiu em direção à entrada, outra o viu, e disse aos que ali estavam: Também este estava com Jesus, o nazareno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'E ele o negou outra vez com um juramento: Não conheço esse homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Pouco depois, os que ali estavam se aproximaram, e disseram a Pedro: Verdadeiramente também tu és um deles, pois a tua fala te denuncia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Então ele começou a amaldiçoar e a jurar: Não conheço esse homem!E imediatamente o galo cantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Então Pedro se lembrou da palavra de Jesus, que lhe dissera: Antes do galo cantar, tu me negarás três vezes. Assim ele saiu, e chorou amargamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Vinda a manhã, todos os chefes dos sacerdotes e anciãos do povo juntamente se aconselharam contra Jesus, para o matarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'E o levaram amarrado, e o entregaram a Pôncio Pilatos, o governador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Então Judas, o que o havia traído, ao ver que Jesus já estava condenado, devolveu, sentindo remorso, as trinta moedas de prata aos chefes dos sacerdotes e aos anciãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'e disse: Pequei, traindo sangue inocente. Porém eles disseram: Que nos interessa? Isso é problema teu!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Então ele lançou as moedas de prata no templo, saiu, e foi enforcar-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Os chefes dos sacerdotes tomaram as moedas de prata, e disseram: Não é lícito pô-las no tesouro das ofertas, pois isto é preço de sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Então juntamente se aconselharam, e compraram com elas o campo do oleiro, para ser cemitério dos estrangeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Por isso aquele campo tem sido chamado campo de sangue até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Assim se cumpriu o que foi dito pelo profeta Jeremias, que disse: Tomaram as trinta moedas de prata, preço avaliado pelos filhos de Israel, o qual eles avaliaram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'e as deram pelo campo do oleiro, conforme o que o Senhor me mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jesus esteve diante do governador, e o governador lhe perguntou: És tu o Rei dos Judeus? E Jesus lhe respondeu: Tu o dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'E, sendo ele foi acusado pelos chefes dos sacerdotes e pelos anciãos, nada respondeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Pilatos, então, lhe disse: Não ouves quantas coisas estão testemunhando contra ti?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Mas Jesus não lhe respondeu uma só palavra, de maneira que o governador ficou muito maravilhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Na festa o governador costuma soltar um preso ao povo, qualquer um que quisessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'E tinham então um preso bem conhecido, chamado Barrabás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Quando, pois, se ajuntaram, Pilatos lhes perguntou: Qual quereis que vos solte? Barrabás, ou Jesus, que é chamado Cristo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Pois ele sabia que foi por inveja que o entregaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'E, enquanto ele estava sentado no assento de juiz, sua mulher lhe enviou a seguinte mensagem: Nada faças com aquele justo, pois hoje sofri muito em sonhos por causa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Mas os chefes dos sacerdotes e os anciãos persuadiram as multidões a pedirem Barrabás, e a exigirem a morte de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'O governador lhes perguntou: Qual destes dois quereis que vos solte? E responderam: Barrabás!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilatos lhes disse: Que, pois, farei de Jesus, que é chamado Cristo? Todos lhe disseram: Seja crucificado!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'E o governador perguntou: Ora, que mal ele fez? Porém gritavam mais: Seja crucificado!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Quando, pois, Pilatos viu que nada adiantava, em vez disso se fazia mais tumulto, ele pegou água, lavou as mãos diante da multidão, e disse: Estou inocente do sangue deste justo. A responsabilidade é vossa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'E todo o povo respondeu: O sangue dele venha sobre nós, e sobre os nossos filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Então soltou-lhes Barrabás, enquanto que mandou açoitar Jesus, e o entregou para ser crucificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Em seguida, os soldados do governador levaram Jesus consigo ao pretório, ajuntaram-se a ele toda a unidade miltar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Eles o despiram e o cobriram com um manto vermelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'E, depois de tecerem uma coroa de espinhos, puseram-na sobre a sua cabeça, e uma cana em sua mão direita. Em seguida, puseram-se de joelhos diante dele, zombando-o, e diziam: Felicitações, Rei dos Judeus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'E cuspiram nele, tomaram a cana, e deram-lhe golpes na cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Depois de terem o zombado, despiram-lhe a capa, vestiram-no com suas roupas, e o levaram para crucificar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Ao saírem, encontraram um homem de Cirene, por nome Simão; e obrigaram-no a levar sua cruz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'E quando chegaram ao lugar chamado Gólgota, que significa “o lugar da caveira”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'deram-lhe de beber vinagre misturado com fel. E, depois de provar, não quis beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'E havendo-o crucificado, repartiram suas roupas, lançando sortes; para que se cumprisse o que foi dito pelo profeta: Repartiram entre si minhas roupas, e sobre minha túnica lançaram sortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Então se sentaram, e ali o vigiavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'E puseram, por cima de sua cabeça, sua acusação escrita: ESTE É JESUS, O REI DOS JUDEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Então foram crucificados com ele dois criminosos, um à direita, e outro à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Os que passavam blasfemavam dele, balançando suas cabeças,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'e dizendo: Tu, que derrubas o Templo, e em três dias o reconstróis, salva a ti mesmo! Se és Filho de Deus, desce da cruz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'E da mesma maneira também os chefes dos sacerdotes, com os escribas e os anciãos, escarnecendo dele,diziam:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Salvou outros, a si mesmo não pode salvar. Se é Rei de Israel, desça agora da cruz, e creremos nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Confiou em Deus, livre-o agora, se lhe quer bem; pois disse: “Sou Filho de Deus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'E os ladrões que estavam crucificados com ele também lhe insultavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Desde a hora sexta houve trevas sobre toda a terra até a hora nona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'E perto da hora nona, Jesus gritou em alta voz: Eli, Eli, lamá sabactâni?, Isto é: Deus meu, Deus meu, porque me desamparaste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'E alguns dos que ali estavam, quando ouviram, disseram: Ele está chamando Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Logo um deles correu e tomou uma esponja. Então a encheu de vinagre, colocou-a em uma cana, e lhe dava de beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Porém os outros disseram: Deixa, vejamos se Elias vem livrá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Jesus gritou outra vez em alta voz, e entregou o espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'E eis que o véu do Templo se rasgou em dois, de cima até embaixo, a terra tremeu, e as pedras se fenderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Os sepulcros se abriram, e muitos corpos de santos que tinham morrido foram ressuscitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'E, depois de ressuscitarem, saíram dos sepulcros, vieram à santa cidade, e apareceram a muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'E o centurião, e os que com ele vigiavam Jesus, ao verem o terremoto e as coisas que haviam sucedido, tiveram muito medo, e disseram: Verdadeiramente ele era Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Muitas mulheres, que desde a Galileia haviam seguido Jesus, e o serviam, estavam ali, olhando de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Entre elas estavam Maria Madalena, e Maria mãe de Tiago e de José, e a mãe dos filhos de Zebedeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'E chegado o entardecer, veio um homem rico de Arimateia, por nome José, que também era discípulo de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Ele chegou a Pilatos, e pediu o corpo de Jesus. Então Pilatos mandou que o corpo lhe fosse entregue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'José tomou o corpo, e o envolveu em um lençol limpo, de linho fino,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'e o pôs em seu sepulcro novo, que tinha escavado numa rocha; em seguida rolou uma grande pedra à porta do sepulcro, e foi embora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'E ali estavam Maria Madalena e a outra Maria, sentadas de frente ao sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'No dia seguinte, que é o depois da preparação, os chefes dos sacerdotes, e os fariseus se reuniram com Pilatos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'e disseram: Senhor, nos lembramos que aquele enganador, enquanto ainda vivia, disse: “Depois de três dias serei ressuscitado”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Portanto, manda que o sepulcro esteja em segurança até o terceiro dia, para que não aconteça dos seus discípulos virem de noite, e o furtem, e digam ao povo que ele ressuscitou dos mortos; e assim o último engano será pior que o primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilatos lhes disse: Vós tendes uma guarda. Ide fazer segurança como o entendeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'E eles se foram, e fizeram segurança no sepulcro com a guarda, selando a pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'No fim do sábado, quando já começava a clarear para o primeiro dia da semana, Maria Madalena, e a outra Maria vieram ver o sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'E eis que houve um grande terremoto; porque um anjo do Senhor desceu do céu, chegou, e moveu a pedra da entrada, e ficou sentado sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'A aparência dele era como um relâmpago, e sua roupa branca como neve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'E de medo dele os guardas tremeram muito, e ficaram como mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Mas o anjo disse às mulheres: Não vos atemorizeis, pois eu sei que buscais Jesus, o que foi crucificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Ele não está aqui, pois já ressuscitou, como ele disse. Vinde ver o lugar onde o Senhor jazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Ide depressa dizer aos seus discípulos que ele ressuscitou dos mortos; e eis que vai adiante de vós para a Galileia; ali o vereis. Eis que eu tenho vos dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Então elas saíram apressadamente do sepulcro, com temor e grande alegria, e correram para anunciar aos seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'E, enquanto elas iam anunciar aos seus discípulos, eis que Jesus veio ao encontro delas, e disse: Saudações. Elas se aproximaram, pegaram os pés dele, e o adoraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Jesus, então, lhes disse: Não temais. Ide anunciar aos meus irmãos para eles irem à Galileia, e ali me verão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Enquanto elas iam, eis que alguns da guarda vieram à cidade, e anunciaram aos chefes dos sacerdotes tudo o que havia acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Então eles se reuniram com os anciãos, depois de decidirem em conjunto, deram muito dinheiro aos soldados,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'dizendo: Falai: “Os discípulos dele vieram de noite, e o furtaram enquanto estávamos dormindo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'E, se isto for ouvido pelo governador, nós o persuadiremos, e vos manteremos seguros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Eles tomaram o dinheiro e fizeram como foram instruídos. E este dito foi divulgado entre os judeus até hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Os onze discípulos se foram para a Galileia, ao monte onde Jesus havia lhes ordenado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'E quando o viram, o adoraram; porém alguns duvidaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Jesus se aproximou deles, e lhes falou: Todo o poder me é dado no céu e na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Portanto ide, fazei discípulos a todas as nações, batizando-os em nome do Pai, do Filho, e do Espírito Santo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'ensinando-lhes a guardar todas as coisas que eu vos tenho mandado. E eis que eu estou convosco todos os dias, até o fim dos tempos. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Princípio do Evangelho de Jesus Cristo, Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Como está escrito nos profetas: Eis que eu envio o meu mensageiro diante de tua face, que preparará o teu caminho diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai suas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'João veio a batizar no deserto, e a pregar o batismo de arrependimento para perdão dos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'E toda a província da Judeia e os de Jerusalém saíam até ele; e eram todos batizados por ele no rio Jordão, confessando os seus pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'João se vestia de pelos de camelo, e um cinto de couro em sua cintura; e comia gafanhotos e mel do campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Ele pregava assim: Após mim vem aquele que é mais forte do que eu. A ele não sou digno de me abaixar para desatar a tira das suas sandálias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'De fato eu tenho vos batizado com água, porém ele vos batizará com Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'E aconteceu que, naqueles dias, Jesus de Nazaré da Galileia veio, e foi batizado por João no Jordão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'E assim que saiu da água, viu os céus se abrirem, e o Espírito, que como pomba descia sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'E veio uma voz dos céus: Tu és meu Filho amado, em quem me agrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'E logo o Espírito o impeliu ao deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Ele esteve ali no deserto quarenta dias, tentado por Satanás. Ele estava com os animais selvagens, e os anjos o serviam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Depois que João foi preso, Jesus veio para a Galileia, pregando o Evangelho do Reino de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'e dizendo: O tempo se cumpriu, e o Reino de Deus está perto; arrependei-vos, e crede no Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'E enquanto andava junto ao mar da Galileia, ele viu Simão e seu irmão André, que lançavam uma rede ao mar, porque eram pescadores;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Jesus lhes disse: Vinde após mim, e farei serdes pescadores de gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Então logo deixaram suas redes, e o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'E passando dali um pouco mais adiante, viu Tiago filho de Zebedeu, e seu irmão João, que estavam no barco, consertando as redes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'E logo os chamou; então eles deixaram o seu pai Zebedeu no barco com os empregados, foram após ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Eles entraram em Cafarnaum; e assim que chegou o sábado, Jesus entrou na sinagoga e começou a ensinar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'E ficavam admirados com o seu ensinamento, pois, diferentemente dos escribas, ele os ensinava como quem temautoridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'E havia na sinagoga deles um homem com um espírito imundo, que gritou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'dizendo: Ah, que temos contigo, Jesus Nazareno? Vieste para nos destruir? Bem sei quem és: o Santo de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Jesus o repreendeu, dizendo: Cala-te, e sai dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'E o espírito imundo, provocando convulsão nele, e gritando em alta voz, saiu dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Assim todos ficaram admirados, e perguntavam entre si: Que é isto? Que novo ensinamento é este que, com autoridade, ordena até aos espíritos imundos, e eles lhe obedecem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'E logo sua fama se espalhou por toda a região da Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Logo depois de saírem da sinagoga, vieram à casa de Simão e de André, com Tiago e João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'A sogra de Simão estava deitada com febre, e logo falaram dela a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Então ele aproximou-se dela, tomou-a pela mão, e a levantou; logo a febre a deixou, e ela começou a servi-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Ao entardecer, quando o sol já se punha, trouxeram-lhe todos os doentes e endemoninhados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'e toda a cidade se juntou à porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Ele curou muitos que se achavam mal de diversas enfermidades, e expulsou muitos demônios. Ele não deixava os demônios falarem, porque o conheciam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'De madrugada, ainda escuro, ele se levantou para sair, foi a um lugar deserto, e ali esteve a orar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simão e os que estavam com ele o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Quando o acharam, disseram-lhe: Todos estão te procurando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Jesus lhes respondeu: Vamos para as aldeias vizinhas, para que eu também pregue ali, pois vim para isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Ele pregava em suas sinagogas por toda a Galileia, e expulsava os demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Um leproso aproximou-se dele, rogando-lhe, pondo-se de joelhos diante dele, e dizendo-lhe: Se quiseres, tu podes limpar-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'E Jesus, movido de compaixão, estendeu a mão, tocou-o, e disse-lhe: Quero; sê limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Quando disse isso, logo a lepra saiu dele, e ficou limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Jesus advertiu-o, e logo o despediu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'dizendo-lhe: Cuidado, não digas nada a ninguém. Mas vai, mostra-te ao Sacerdote, e oferece por teres ficado limpo o que Moisés mandou, para lhes servir de testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Porém, quando ele saiu, começou a anunciar muitas coisas, e a divulgar a notícia, de maneira que Jesus já não podia entrar publicamente na cidade; em vez disso, ficava do lado de fora em lugares desertos, e pessoas de todas as partes vinham até ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Dias depois, Jesus entrou outra vez em Cafarnaum, e ouviu-se que estava em casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Logo juntaram-se tantos, que nem mesmo perto da porta cabiam; e ele lhes falava a palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'E vieram a ele uns que traziam um paralítico carregado por quatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Como não podiam se aproximar dele por causa da multidão, descobriram o telhado onde ele estava, fizeram um buraco, e baixaram por ele o leito em que jazia o paralítico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Quando Jesus viu a fé deles, disse ao paralítico: Filho, os teus pecados te são perdoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'E estavam ali sentados alguns escribas, que pensavam em seus corações:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Por que este homem fala essas blasfêmias? Quem pode perdoar pecados, a não ser somente Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Imediatamente Jesus percebeu em seu espírito que assim pensavam em si mesmos. Então perguntou-lhes: Por que pensais assim em vossos corações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'O que é mais fácil? Dizer ao paralítico: “Os teus pecados estão perdoados”, ou dizer, “Levanta-te, toma o teu leito, e anda”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Mas para que saibais que o Filho do homem tem poder na terra para perdoar pecados,(disse ao paralítico):');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'A ti eu digo: levanta-te, toma o teu leito, e vai para a tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'E logo ele se levantou, tomou o leito, e saiu na presença de todos, de tal maneira, que todos ficaram admirados, e glorificaram a Deus, dizendo: Nunca vimos algo assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Jesus voltou a sair para o mar; toda a multidão veio até ele, e ele os ensinava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'E enquanto passava, ele viu Levi, filho de Alfeu, sentado no posto de coleta de impostos, e disse-lhe: Segue-me.Então Levi se levantou e o seguiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'E aconteceu que enquanto estava sentado à mesa na casa dele, muitos cobradores de impostos e pecadores também estavam também sentados à mesa com Jesus e os seus discípulos; porque eram muitos, e o haviam seguido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Quando os escribas e os fariseus o viram comer com os cobradores de impostos e pecadores, disseram a seus discípulos: Por que é que ele come e bebe com os cobradores de impostos e os pecadores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Jesus ouviu e lhes respondeu: Os que têm saúde não precisam de médico, mas sim os que estão doentes. Eu não vim para chamar os justos, mas sim os pecadores ao arrependimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Os discípulos de João e os dos fariseus estavam jejuando; então vieram lhe perguntar: Por que os discípulos de João e os dos fariseus jejuam, e os teus discípulos não jejuam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Jesus lhes respondeu: Podem os convidados do casamento jejuar enquanto o noivo estiver com eles? Enquanto tiverem o noivo consigo, eles não podem jejuar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Mas dias virão, quando o noivo lhes for tirado; e então naqueles dias jejuarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Ninguém costura remendo de pano novo em roupa velha; senão o remendo novo rompe o velho, e se faz pior rasgo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'E ninguém põe vinho novo em odres velhos; senão o vinho novo rompe os odres, derrama-se o vinho, e os odres se danificam; mas o vinho novo deve ser posto em odres novos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'E aconteceu que, enquanto Jesus passava pelas plantações no sábado, os seus discípulos, andando, começaram a arrancar espigas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Os fariseus lhe disseram: Olha! Por que estão fazendo o que não é lícito no sábado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'E ele lhes disse: Nunca lestes o que fez Davi, quando teve necessidade e fome, ele e os que com ele estavam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Como ele entrou na Casa de Deus, quando Abiatar era sumo sacerdote, e comeu os pães da proposição (dos quais não é lícito comer, a não ser aos sacerdotes), e também deu aos que com ele estavam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Disse-lhes mais: O sábado foi feito por causa do ser humano, não o ser humano por causa do sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Por isso o Filho do homem é Senhor até do sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Jesus entrou outra vez na sinagoga; e estava ali um homem que tinha uma mão definhada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'E prestavam atenção nele, se o curaria no sábado, para o acusarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'E Jesus disse ao homem que tinha a mão definhada: Levanta-te, e vem para o meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'E disse-lhes:É lícito no sábado fazer o bem, ou o mal? Salvar uma pessoa, ou matá-la? E mantiveram-se calados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'E olhando ao redor para eles com indignação, sentindo pena da dureza dos seus corações, disse ao homem: Estende a tua mão. E ele estendeu; e sua mão foi restaurada, sã como a outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Assim que os fariseus saíram, tiveram reunião com os herodianos contra ele, para combinarem sobre como o matariam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'E Jesus retirou-se com os seus discípulos para o mar; e seguiu-o uma grande multidão da Galileia, da Judeia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'de Jerusalém, da Idumeia, dalém do Jordão, e os das proximidades de Tiro e de Sidom; uma grande multidão, tendo ouvido quão grandes coisas fazia, vieram a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'E disse aos seus discípulos que um barquinho ficasse continuamente perto dele, por causa das multidões; para que não o apertassem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Pois havia curado muitos, de maneira que todos quantos tinham algum mal lançavam-se sobre ele a fim de tocá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'E os espíritos imundos, quando o viam, prostravam-se diante dele, e exclamavam: Tu és o Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Mas Jesus os repreendia muito, para que não manifestassem quem ele era.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Ele subiu ao monte, e chamou para si os que quis; então vieram a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'E constituiu doze para que estivessem com ele, para enviá-los a pregar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'para que tivessem poder de curar as enfermidades e expulsar os demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Eram eles: Simão, a quem pôs por nome Pedro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Tiago filho de Zebedeu, e João, irmão de Tiago; e pôs-lhes por nome Boanerges, que significa “filhos do trovão”;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'e André, Filipe, Bartolomeu, Mateus, Tomé; Tiago filho de Alfeu; Tadeu; Simão o zelote;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'e Judas Iscariotes, o que o traiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Quando foram para uma casa, outra vez se ajuntou uma multidão, de maneira que nem sequer podiam comer pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Os seus familiares, ao ouvirem isso, saíram para detê-lo, porque diziam: “Ele stá fora de si”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'E os escribas que haviam descido de Jerusalém diziam: Ele tem Belzebu, e é pelo chefe dos demônios que expulsa demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Então Jesus os chamou, e lhes disse por parábolas: Como pode Satanás expulsar Satanás?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Se algum reino estiver dividido contra si mesmo, tal reino não pode durar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'e se alguma casa estiver dividida contra si mesma, tal casa não pode durar firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'E se Satanás se levantar contra si mesmo, e for dividido, não pode durar, mas tem fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Ninguém pode roubar os bens do valente, quando se entra na casa dele, se antes não amarrar ao valente; depois disso roubará a sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Em verdade vos digo que todos os pecados serão perdoados aos filhos dos homens, e todas as blasfêmias com que blasfemarem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'mas quem blasfemar contra o Espírito Santo ficará sem perdão para sempre; em vez disso, é culpado do juízo eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Pois diziam: “Ele tem espírito imundo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Então chegaram os seus irmãos e a sua mãe; e estando de fora, mandaram chamá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'A multidão estava sentada ao redor dele. Então disseram-lhe: Eis que a tua mãe e os teus irmãos estão lá fora a te procurar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Ele lhes respondeu: Quem é a minha mãe ou os meus irmãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'E, olhando em redor aos que estavam sentados perto dele, disse: Eis aqui minha mãe e meus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Pois quem fizer a vontade de Deus, esse é meu irmão, minha irmã, e mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Jesus começou outra vez a ensinar junto ao mar, e uma grande multidão se ajuntou a ele, de maneira que ele entrou num barco e ficou sentado no mar; e toda a multidão estava em terra junto ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'E ensinava-lhes muitas coisas por parábolas; e dizia-lhes em seu ensinamento:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Ouvi: eis que o semeador saiu a semear;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'E aconteceu que, enquanto semeava, uma parte das sementes caiu junto ao caminho, e os pássaros do céu vieram, e a comeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'E outra caiu em pedregulhos, onde não havia muita terra; e logo nasceu, porque não tinha terra profunda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Mas, quando saiu o sol, queimou-se; e porque não tinha raiz, secou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'E outra caiu entre espinhos; e os espinhos cresceram e a sufocaram, e não deu fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Mas outra caiu em boa terra, e deu fruto, que subiu, e cresceu; e um deu trinta, outro sessenta, e outro cem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'E disse-lhes: Quem tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'E quando Jesus esteve só, os que estavam junto dele, com os doze, perguntaram-lhe acerca da parábola.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'E respondeu-lhes: A vós é concedido saber o mistério do Reino de Deus; mas aos que são de fora, todas estas coisas se fazem por meio de parábolas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'para que vendo, vejam, e não percebam; e ouvindo, ouçam, e não entendam; para não haver de se converterem, e lhes sejam perdoados os pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'E disse-lhes: Não sabeis o significado desta parábola? Como, pois, entendereis todas as parábolas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'O semeador semeia a palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'E estes são os de junto ao caminho: nos quais a palavra é semeada; mas depois de a ouvirem, Satanás logo vem, e tira a palavra que foi semeada nos seus corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'E, semelhantemente, estes são os que se semeiam em pedregulhos: os que havendo ouvido a palavra, logo a recebem com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Mas não têm raiz em si mesmos; em vez disso, são temporários. Depois, quando se levanta a tribulação ou aperseguição por causa da palavra, logo caem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'E estes são os que se semeiam entre espinhos: os que ouvem a palavra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'mas as preocupações deste mundo, a sedução das riquezas, e as cobiças por outras coisas, entram, sufocam a palavra, e ela fica sem gerar fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'E estes são os que foram semeados em boa terra: os que ouvem a palavra, recebem-na, e dão fruto, um trinta, e outro sessenta, e outro cem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'E ele lhes disse: Por acaso a lâmpada vem a ser posta debaixo de uma caixa ou sob da cama? Não deve ela ser posta na luminária?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Pois não há nada encoberto que não haja de ser revelado; e nada se faz para ficar encoberto, mas sim, para ser vir à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Se alguém tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'E disse-lhes: Prestai atenção ao que ouvis: com a medida que medirdes a vós mesmos se medirá, e será acrescentado a vós que ouvis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Pois ao que tem, lhe será dado; e ao que não tem, até o que tem lhe será tirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'E dizia: Assim é o Reino de Deus, como se um homem lançasse semente na terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'e dormisse, e se levantasse, de noite e de dia, e a semente brotasse, e crescesse, sem que ele saiba como.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Pois a terra de si mesma frutifica, primeiro a erva, depois a espiga, depois o grão cheio na espiga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'E quando o fruto se mostra pronto, logo mete a foice, pois a colheita chegou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'E dizia: A que assemelharemos o Reino de Deus? Ou com que parábola o compararemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Com um grão da mostarda que, quando semeado na terra, é a menor de todas as sementes na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Mas, depois de semeado, cresce, e se torna a maior de todas as hortaliças, e cria grandes ramos, de maneira que os pássaros do céu podem fazer ninhos sob a sua sombra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'E com muitas parábolas como essas Jesus lhes falava a palavra, conforme o que podiam ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'E não lhes falava sem parábola; mas aos seus discípulos explicava tudo em particular.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Naquele dia, chegando o entardecer, disse-lhes: Passemos para o outro lado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Então despediram a multidão, e o levaram consigo assim como estava no barco; mas havia também outros barquinhos com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'E levantou-se uma grande tempestade de vento; as ondas atingiam por cima do barco, de maneira que já se enchia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Jesus estava na popa dormindo sobre uma almofada. Então despertaram-no, e disseram-lhe: Mestre, não te importas que pereçamos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Então ele se levantou, repreendeu o vento, e disse ao mar: Cala-te, aquieta-te! E o vento se aquietou, e fez-se grande bonança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'E perguntou-lhes: Por que sois tão covardes? Como não tendes fé?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'E ficaram muito atemorizados, e diziam uns aos outros: Quem é este, que até o vento e o mar lhe obedecem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'E chegaram ao outro lado do mar, à terra dos Gadarenos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Assim que Jesus saiu do barco, veio das sepulturas ao seu encontro um homem com um espírito imundo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'que morava nas sepulturas, e nem mesmo com correntes conseguiam prendê-lo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'pois muitas vezes fora preso com grilhões e correntes; mas as correntes eram por ele feitas em pedaços, os grilhões eram esmigalhados, e ninguém o conseguia controlar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'E sempre dia e noite andava gritando pelos montes e pelas sepulturas, e ferindo-se com pedras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Quando ele viu Jesus de longe, correu e prostrou-se diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'E gritou em alta voz: Que tenho eu contigo Jesus, Filho do Deus Altíssimo? Imploro-te por Deus que não me atormentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, '(Pois Jesus havia lhe dito: “Sai deste homem, espírito imundo”.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Então perguntou-lhe: Qual é o teu nome? E respondeu: Legião é o meu nome, porque somos muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'E rogava-lhe muito que não os expulsasse daquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Havia ali perto dos montes uma grande manada de porcos pastando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'E todos aqueles demônios rogaram-lhe, dizendo: Manda-nos para aqueles porcos, para que entremos neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Imediatamente Jesus lhes permitiu. Então aqueles espíritos imundos saíram para entrar nos porcos; e a manada lançou-se abaixo no mar; (eram quase dois mil) e afogaram-se no mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Os que apascentavam os porcos fugiram, e avisaram na cidade e nos campos; e as pessoas foram ver o que havia acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Então aproximaram-se de Jesus, e viram o endemoninhado sentado, vestido, e em sã consciência o que tivera a legião; e ficaram apavorados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'E os que haviam visto contaram-lhes o que acontecera ao endemoninhado, e sobre os porcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Então começaram a rogar-lhe que saísse do território deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Quando Jesus entrava no barco, o que fora endemoninhado rogou-lhe que estivesse com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Jesus se recusou, porém lhe disse: Vai para a tua casa, aos teus, e anuncia-lhes quão grandes coisas o Senhor fez contigo, e como teve misericórdia de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Então ele foi embora, e começou a anunciar em Decápolis quão grandes coisas Jesus havia feito com ele; e todos se admiravam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Depois de Jesus passar outra vez num barco para o outro lado, uma grande multidão se ajuntou a ele; e ele ficou junto ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'E eis que veio um dos líderes de sinagoga, por nome Jairo; e quando o viu, prostrou-se aos seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'E implorava-lhe muito, dizendo: Minha filhinha está a ponto de morrer. Rogo-te que venhas pôr as mãos sobre ela, para que seja curada, e viva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Jesus foi com ele. Uma grande multidão o seguia, e o apertavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'E havia uma certa mulher, que tinha um fluxo de sangue havia doze anos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'que tinha sofrido muito por meio de muitos médicos, e gastado tudo quanto possuía, e nada havia lhe dado bom resultado; ao invés disso, piorava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Quando ela ouviu falar de Jesus, veio entre a multidão por detrás, e tocou a roupa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Pois dizia: Se tão somente tocar as suas roupas, serei curada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'E imediatamente a fonte do seu sangue parou se secou; e sentiu no corpo que já havia sido curada daquele flagelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Jesus logo notou em si o poder que dele havia saído. Então virou-se na multidão, e perguntou: Quem tocou as minhas roupas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'E seus discípulos lhe disseram: Eis que a multidão te aperta, e perguntas: Quem me tocou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'E ele olhava em redor, para ver quem havia lhe feito isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Então a mulher temendo, e tremendo, sabendo o que havia sido feito em si, veio, prostrou-se diante dele, e disse-lhe toda a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'E ele lhe disse: Filha, a tua fé te salvou. Vai em paz, e estejas curada deste teu flagelo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Estando ele ainda falando, alguns vieram da casa do líder de sinagoga, e disseram: A tua filha já morreu; por que ainda estás incomodando o Mestre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Mas Jesus, assim que ouviu essa palavra que havia sido falada, disse ao líder de sinagoga: Não temas; crê somente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'E não permitiu que ninguém o seguisse, a não ser Pedro, Tiago, e João irmão de Tiago.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Ele chegou à casa do líder de sinagoga, e viu o alvoroço, os que choravam muito e pranteavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'E ao entrar, disse-lhes: Por que fazeis alvoroço e chorais? A menina não morreu, mas está dormindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'E riram dele. Porém ele, depois de pôr todos fora, tomou consigo o pai e a mãe da menina, e os que estavam com ele. Em seguida, entrou onde a menina estava deitada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Ele pegou a mão da menina, e lhe disse: “Talita cumi”, (que significa: “Menina, eu te digo, levanta-te”).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'E logo a menina se levantou e andou, pois já tinha doze anos de idade. E ficaram grandemente espantados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'E mandou-lhes muito que ninguém o soubesse; e mandou que dessem a ela de comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Jesus partiu-se dali, veio à sua terra, e seus discípulos o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'E chegando o sábado, começou a ensinar na sinagoga; e muitos, quando o ouviram, espantavam-se, dizendo: De onde lhe vem estas coisas? E que sabedoria é esta que lhe foi dada? E tais maravilhas feitas por suas mãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Não é este o carpinteiro, filho de Maria, e irmão de Tiago, de José, de Judas, e de Simão? E não estão aqui as suas irmãs conosco?E ofenderam-se nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'E Jesus lhes dizia: Todo profeta tem honra, menos em sua terra, entre os parentes, e em sua própria casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Ele não pôde ali fazer milagre algum, a não ser somente para uns poucos enfermos, sobre os quais pôs as mãos e os curou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'E ficou admirado da incredulidade deles. Ele percorreu as aldeias do redor, ensinando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'E chamou a si os doze, e começou a enviar de dois em dois; e deu-lhes poder sobre os espíritos imundos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'E mandou-lhes que não tomassem nada para o caminho, a não ser somente um bordão; nem bolsa, nem pão, nem dinheiro no cinto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'mas que calçassem sandálias, e não se vestissem de duas túnicas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'E dizia-lhes: Onde quer que entrardes em alguma casa, ficai ali até que dali saiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'E todos os que não vos receberem, nem vos ouvirem, quando sairdes dali, sacudi o pó que estiver debaixo de vossos pés, em testemunho contra eles. Em verdade vos digo, que mais tolerável será a os de Sodoma ou Gomorra no dia do juízo, do que a os d aquela cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Eles, então, se foram, e pregaram que as pessoas se arrependessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Eles expulsaram muitos demônios, e a muitos enfermos ungiram com azeite, e os curaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'O rei Herodes ouviu falar disso (porque o nome de Jesus já era notório). E dizia: João Batista ressuscitou dos mortos, e por isso estas maravilhas operam nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Outros diziam: É Elias; e outros diziam: É profeta, ou como algum dos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Quando, porém, Herodes ouviu falar disso, falou: Ele é João, de quem cortei a cabeça. Ele ressuscitou dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Pois o próprio Herodes havia mandado prender João, e acorrentá-lo na prisão, por causa de Herodias, mulher do seu irmão Filipe, porque havia se casado com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Pois João dizia a Herodes: Não te é lícito possuir a mulher do teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Assim Herodias o odiava, e queria matá-lo, mas não podia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'pois Herodes temia João, sabendo que era um homem justo e santo, e o estimava. E quando o ouvia, fazia muitas coisas, o ouvia de boa vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Mas veio um dia oportuno, em que Herodes, no dia do seu aniversário, dava uma ceia aos grandes de sua corte, aos comandantes militares, e aos principais da Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Então a filha dessa Herodias entrou dançando, e agradou a Herodes e aos que estavam sentados com ele. O rei disse à garota: Pede-me quanto quiseres, que eu darei a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'E jurou a ela: Tudo o que me pedirdes te darei, até a metade do meu reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Então ela saiu, e perguntou à sua mãe: Que pedirei? E ela respondeu: A cabeça de João Batista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'E entrando ela logo apressadamente ao rei, pediu, dizendo: Quero que imediatamente me dês num prato a cabeça de João Batista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'E o rei entristeceu-se muito; mas, por causa dos juramentos, e dos que estavam juntamente à mesa, não quis recusar a ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Então logo o rei enviou o executor com a ordem de trazer ali sua cabeça. Ele, foi, e o decapitou na prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Em seguida, trouxe a sua cabeça num prato, e o deu à garota; e a garota a deu à sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Quando os discípulos dele ouviram isso, vieram, pegaram o seu cadáver, e o puseram num sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Os apóstolos juntaram-se de volta a Jesus, e contaram-lhe tudo, tanto o que haviam feito, como o que haviam ensinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'E ele lhes disse: Vinde vós à parte a um lugar deserto, e descansai um pouco; pois havia muitos que iam e vinham, e não tinham tempo para comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'E foram-se num barco a um lugar deserto à parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Mas as multidões os viram ir, e muitos o reconheceram. Então correram para lá a pé de todas as cidades, chegaram antes deles, e vieram para perto dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Quando Jesus saiu do barco, viu uma grande multidão, e teve compaixão deles porque eram como ovelhas que não têm pastor. Assim, começou a lhes ensinar muitas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'E quando já era tarde, os seus discípulos vieram a ele, e disseram: O lugar é deserto, e a hora já é tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Despede-os, para eles irem aos campos e aldeias circunvizinhos, e comprarem pão para si; pois não têm o que comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Mas ele respondeu: Dai-lhes vós mesmos de comer. E eles lhe responderam: Iremos, e compraremos duzentos denários de pão, para lhes darmos de comer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'E ele lhes disse: Quantos pães tendes? Ide ver. Quando souberam, disseram: Cinco, e dois peixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'E mandou-lhes que fizessem sentar a todos em grupos sobre a grama verde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'E sentaram-se repartidos de cem em cem, e de cinquenta em cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Ele tomou os cinco pães e os dois peixes, levantou os olhos ao céu, abençoou, e partiu os pães, e os deu aos seus discípulos, para que os pusessem diante deles. E os dois peixes repartiu com todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Todos comeram e se saciaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'E dos pedaços de pão e dos peixes levantaram doze cestos cheios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Os que comeram os pães eram quase cinco mil homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Logo depois, ordenou seus discípulos a subirem no barco, e ir adiante para o outro lado, em Betsaida, enquanto ele despedia a multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'E, depois de os despedir, foi ao monte para orar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Ao anoitecer, o barco estava no meio do mar, e Jesus sozinho em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'E viu que se cansavam muito remando, porque o vento lhes era contrário. Então, perto da quarta vigília da noite, veio a eles andando sobre o mar, e queria passar por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Mas quando eles o viram andando sobre o mar, pensaram que era uma fantasma, e gritaram,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'pois todos o viam, e ficaram perturbados. Então logo falou com eles, dizendo: Tende coragem! Sou eu, não tenhais medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'E subiu a eles no barco, e o vento se aquietou. Eles ficaram muito espantados e maravilhados entre si,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'pois não haviam entendido o que tinha acontecido com os pães, porque o coração deles estava endurecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Eles terminaram de atravessar o mar, chegaram à terra de Genesaré, e ali aportaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Quando eles saíram do barco, logo as pessoas o reconheceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Então gente de toda a região em redor veio correndo, e começaram a trazer em camas os doentes, aonde quer que ouviam que ele estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'E aonde quer que ele entrava, em povoados, cidades, ou aldeias, colocavam os enfermos nas praças, e rogavam-lhe que ao menos tocassem a borda de sua roupa; e todos os que o tocavam ficavam sarados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Os fariseus, e alguns dos escribas, que tinham vindo de Jerusalém, reuniram-se com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'E, quando viram que alguns dos discípulos dele comiam pão com mãos impuras, isto é, sem lavar, repreendiam-lhes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, '(Pois os fariseus, e todos os judeus, mantendo a tradição dos antigos, se não lavarem bastante as mãos, não comem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'E, quando voltam da rua, se não se lavarem, não comem; e há muitas outras coisas que se encarregam de guardar, como lavar os copos, as vasilhas, os utensílios de metal, e os leitos).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Depois os fariseus e os escribas lhe perguntaram: Por que os teus discípulos não andam conforme a tradição dos antigos, em vez de comerem pão com as mãos sem lavar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'E ele lhes respondeu: Bem profetizou Isaías acerca de vós, hipócritas! Como está escrito: Este povo me honra com os lábios, mas o seu coração está longe de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Eles, porém, me honram em vão, ensinando como doutrinas mandamentos humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Pois vós deixais o mandamento de Deus, e mantendes a tradição humana, como lavar as vasilhas e os copos; e fazeis muitas outras coisas semelhantes a estas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'E dizia-lhes: Vós dispensais o mandamento de Deus para guardardes a vossa tradição;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'porque Moisés disse: Honra o teu pai e a tua mãe. E quem maldisser ao pai ou à mãe terá de morrer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Mas vós dizeis: Se o homem disser ao pai ou à mãe: Tudo o que te puder aproveitar de mim é corbã (isto é, oferta),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'então não lhe deixais mais nada fazer por seu pai ou por sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Assim invalidaias a palavra de Deus por vossa tradição, que ordenastes; e fazeis muitas coisas semelhantes a estas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'E chamando para si toda a multidão, disse-lhes: Ouvi-me todos, e entendei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nada há fora do ser humano que nele entre que o possa contaminar; mas o que dele sai, isso é o que contamina o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Se alguém tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Quando Jesus deixou a multidão e entrou em casa, seus discípulos lhe perguntaram sobre a parábola.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'E ele lhes disse: Também vós estais assim sem entendimento? Não entendeis que tudo o que de fora entra no ser humano não o pode contaminar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Pois não entra no seu coração, mas, sim, no ventre, e sai para a privada. (Assim, ele declarou como limpas todas as comidas).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'E dizia: O que sai do ser humano, isso contamina o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Pois é de dentro do coração humano que vêm os maus pensamentos, os adultérios, os pecados sexuais, os homicídios,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'os roubos, as ganâncias, as maldades, o engano, a depravação, o olho malicioso, a blasfêmia, a soberba, a insensatez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Todos estes males procedem de dentro, e contaminam o ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Jesus levantou-se dali e foi para a região de Tiro e de Sidom. Ele entrou numa casa, e não queria que ninguém soubesse disso, mas não pôde se esconder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Pois uma mulher, cuja filhinha tinha um espírito imundo, assim que ouviu falar dele, veio, e prostrou-se a seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Esta mulher era grega, de nacionalidade sirofenícia; e rogava-lhe que expulsasse o demônio de sua filha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Mas Jesus lhe disse: Deixa primeiro que os filhos se fartem; porque não é bom tomar o pão dos filhos, e lançá-lo aos cachorrinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Porém ela lhe respondeu: Sim Senhor; mas também os cachorrinhos comem debaixo da mesa, das migalhas que os filhos deixam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Então ele lhe disse: Por esta palavra, vai, o demônio já saiu da tua filha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Quando ela chegou à sua casa, encontrou que o demônio já havia saído, e a filha estava deitada sobre a cama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Então Jesus voltou a sair da região de Tiro e de Sidom, e veio para o mar da Galilea, por meio da região de Decápolis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'E trouxeram-lhe um surdo que dificilmente falava, e rogaram-lhe que pusesse a mão sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'E tomando-o em separado da multidão, pôs os seus dedos nos ouvidos dele, cuspiu, e tocou-lhe a língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Depois, levantando os olhos ao céu, suspirou, e disse: Efatá, (isto é, abre-te).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Imediatamente os ouvidos dele se abriram, e o que prendia sua língua se soltou, e passou a falar bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Jesus lhes mandou que a ninguém dissessem; porém, quanto mais lhes mandava, mais divulgavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'E ficavam muito admirados, dizendo: Ele faz tudo bem! Aos surdos faz ouvir, e aos mudos falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Naqueles dias, quando havia uma multidão muito grande, e não tinham o que comer, Jesus chamou os seus discípulos a si, e disse-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Tenho compaixão da multidão, porque já há três dias que estão comigo, e não têm o que comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'E se eu os deixar ir sem comer para suas casas desmaiarão no caminho; porque alguns deles vieram de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Os seus discípulos lhe responderam: De onde poderá alguém saciar estes de pão aqui no deserto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Jesus lhes perguntou: Quantos pães tendes? E eles disseram: Sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Então mandou à multidão que se sentassem no chão. Em seguida, tomou os sete pães, e tendo dado graças, partiu-os, e os deu a seus discípulos, para que os pusessem diante deles. E eles os puseram diante da multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'E tinham uns poucos peixinhos, e havendo dado graças, disse que também os pusessem diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Eles comeram, e se saciaram; e levantaram, do que sobrou dos pedaços, sete cestos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Os que comeram eram quase quatro mil. Depois os despediu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'E logo entrou no barco com os seus discípulos, e veio para a região de Dalmanuta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Os fariseus vieram, e começaram a disputar com ele, pedindo-lhe sinal do céu, para o testar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'E ele, suspirando profundamente em seu espírito, disse: Por que esta geração pede um sinal? Em verdade vos digo, que não se dará sinal a esta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Então os deixou, voltou a entrar no barco, e foi para a outro lado do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'E os seus discípulos haviam se esquecido de tomar pão, e nada tinham, a não ser um pão com eles no barco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'E Jesus lhes deu a seguinte ordem: Prestai atenção: tende cuidado com o fermento dos fariseus e o fermento de Herodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'E indagavam-se com os outros, dizendo: É porque não temos pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Jesus soube e lhes disse: Por que indagais que não tendes pão? Não percebeis ainda, nem entendeis? Ainda tendes o vosso coração endurecido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Tendes olhos, e não vedes? Tendes ouvidos, e não ouvis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'E não vos lembrais de, quando parti os cinco pães entre os cinco mil, quantos cestos cheios de pedaços levantastes?Responderam-lhe: Doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'E quando parti os sete entre os quatro mil, quantas cestas cheias de pedaços levantastes? Eles disseram: Sete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Ele lhes perguntou: Como não entendeis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Então veio a Betsaida. E trouxeram-lhe um cego, e rogaram-lhe que o tocasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Ele tomou o cego pela mão e o tirou para fora da aldeia. Depois cuspiu nos olhos dele e, pondo as mãos encima dele, perguntou-lhe se via alguma coisa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Ele levantou os olhos e disse: Vejo as pessoas; pois vejo como árvores que andam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Então Jesus pôs de novo as mãos sobre os seus olhos, e o fez olhar para cima. Assim ele ficou restabelecido, e passou a ver todos claramente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Então o mandou para sua casa, dizendo: Não entres na aldeia, nem contes a ninguém da aldeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Jesus saiu com os seus discípulos para as aldeias de Cesareia de Filipe; e no caminho perguntou a seus discípulos: Quem as pessoas dizem que eu sou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Eles responderam: João Batista, e outros, Elias; e outros, algum dos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'E ele lhes perguntou: E vós, quem dizeis que eu sou? Pedro lhe respondeu: Tu és o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'E lhes ordenou que a ninguém dissessem aquilo dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'E começou a lhes ensinar que era necessário que o Filho do homem sofresse muito, e fosse rejeitado pelos anciãos e pelos chefes dos sacerdotes e escribas, e que fosse morto, e depois de três dias ressuscitasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Ele dizia essa palavra abertamente. Então Pedro o tomou à parte, e começou a repreendê-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mas Jesus virou-se e, olhando para os seus discípulos, repreendeu Pedro, dizendo: Sai de diante de mim, satanás! Pois tu não compreendes as coisas de Deus, mas sim as humanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Então chamou a si a multidão com os seus discípulos, e disse-lhes: Quem quiser vir após mim, negue a si mesmo, tome a sua cruz, e siga-me;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'pois quem quiser salvar a sua vida, a perderá; mas quem perder a sua vida por causa de mim e do Evangelho, esse a salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Pois que proveito teria alguém, se ganhasse o mundo todo, e perdesse a sua alma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Ou que daria alguém em resgate de sua alma?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Porque todo aquele que se envergonhar de mim e de minhas palavras nesta geração adúltera e pecadora, também o Filho do homem, quando vier na glória de seu Pai com os santos anjos, envergonhar-se-á dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'E disse-lhes também: Em verdade vos digo, que há alguns dos que aqui estão, que não experimentarão a morte, até que vejam o reino de Deus vindo com poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Seis dias depois, Jesus tomou consigo Pedro, Tiago, e João, e os levou à parte, sozinhos, para um alto monte; e transfigurou-se diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'E suas roupas ficaram resplandescentes, muito brancas como a neve, como nenhum lavadeiro na terra seria capaz de branquear.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'E apareceu-lhes Elias com Moisés, e falavam com Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Então Pedro disse a Jesus: Mestre, é bom para nós estarmos aqui; façamos três tendas: uma para ti, uma para Moisés, e uma para Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Pois ele não sabia o que dizia, pois estavam assombrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Então desceu uma nuvem, que os cobriu com a sua sombra, e veio uma voz da nuvem, que dizia: Este é meu Filho amado; a ele ouvi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'De repente, quando olharam em redor, não viram mais ninguém, a não ser só Jesus com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Enquanto desciam do monte, Jesus lhes mandou que a ninguém contassem o que haviam visto, até que o Filho do homem ressuscitasse dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'E eles guardaram o caso entre si, perguntando uns aos outros o que seria aquilo de “ressuscitar dos mortos”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Então lhe perguntaram: Por que os escribas dizem que Elias tem que vir primeiro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'E ele lhes respondeu: De fato Elias vem primeiro, e restaura todas as coisas. Então, como está escrito sobre o Filho do homem tem que sofrer muito, e ser desprezado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Porém eu vos digo que Elias já veio, e fizeram-lhe tudo o que quiseram, como está escrito sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'E quando veio aos discípulos, ele viu uma grande multidão ao redor deles; e uns escribas estavam discutindo com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Logo que toda a multidão o viu, ficou admirada. Então correram a ele, e o cumprimentaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Jesus perguntou aos escribas: O que estais discutindo com eles?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'E um da multidão respondeu: Mestre, trouxe a ti o meu filho, que tem um espírito mudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'E onde quer que o toma, faz-lhe ter convulsões, solta espuma, range os dentes, e vai ficando rígido. Eu disse aos teus discípulos que o expulsassem, mas não conseguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Jesus lhe respondeu: Ó geração incrédula! Até quando estarei ainda convosco? Até quando vos suportarei? Trazei-o a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Então trouxeram-no a ele. E quando o viu, logo o espírito o fez ter uma convulsão e, caindo em terra, rolava, e espumava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'E perguntou ao seu pai: Quanto tempo há que isto lhe sobreveio? E ele lhe disse: Desde a infância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'E muitas vezes o lançou também no fogo e na água para o destruir. Mas, se podes algo, tem compaixão de nós, e ajuda-nos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'E Jesus lhe disse: Se podes crer, tudo é possível ao que crê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Logo o pai do menino, clamando, com lágrimas, disse: Creio, Senhor! Ajuda-me na minha incredulidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Quando Jesus viu que a multidão corria e se ajuntava, repreendeu o espírito imundo, dizendo-lhe: Espírito mudo e surdo, eu te ordeno, sai dele, e nunca mais entres nele!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Então o espírito, gritando, e fazendo-o ter muita convulsão, saiu. E o menino ficou como morto, de maneira que muitos diziam que estava morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Então Jesus o tomou pela mão, e o ergueu; e ele se levantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'E quando entrou em casa, seus discípulos lhe perguntaram à parte: Por que nós não conseguimos o expulsar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'E lhes respondeu: Este tipo não pode sair por coisa alguma, a não ser com oração e jejum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Depois partiram dali, e caminharam pela Galileia. Mas Jesus não queria que ninguém soubesse,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Porque ensinava a seus discípulos, e lhes dizia: O Filho do homem será entregue em mãos de homens, e o matarão; e estando ele morto, ressuscitará ao terceiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mas eles não entendiam esta palavra, e temiam lhe perguntar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'E veio a Cafarnaum, e entrando em casa, perguntou-lhes: Que indagais entre vós pelo caminho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Mas eles se calaram; porque eles haviam discutido uns com os outros pelo caminho, qual deles seria o maior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'E sentando-se ele, chamou aos doze, e disse-lhes: Se alguém quiser ser o primeiro, seja o últimos de todos, e servo de todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'E tomando um menino, ele o pôs no meio deles, e tomando-o entre seus braços, disse-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Qualquer que em meu nome receber a um dos tais meninos, recebe a mim; e qualquer que me receber, não é a mim que recebe, mas, sim, àquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'E respondeu-lhe João, dizendo: Mestre, vimos um que em teu nome expulsava os demônios, e ele não nos segue. Então o proibimos, porque não nos segue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Porém Jesus disse: Não o proibais; porque ninguém há que faça milagre em meu nome, e logo possa falar mal de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Pois quem não é contra nós, é por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Porque qualquer que vos der um copo d\'água para beber em meu nome, porque sois de Cristo, em verdade vos digo, que não perderá sua recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'E qualquer que ofender a um destes pequenos que creem em mim, melhor lhe fora que lhe pusesse ao pescoço uma grande pedra de moinho, e que fosse lançado no mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'E se a tua mão te faz pecar, corta-a; melhor te é entrar na vida mutilado, do que tendo duas mãos ir ao inferno, ao fogo que nunca se apaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Onde seu verme não morre, e o fogo nunca se apaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'E se teu pé te faz pecar, corta-o; melhor te é entrar na vida manco, do que tendo dois pés ser lançado no inferno, no fogo que nunca se apaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Onde seu verme não morre, e o fogo nunca se apaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'E se teu olho te faz pecar, lança-o fora; melhor te é entrar no Reino de Deus com um olho, do que tendo dois olhos ser lançado no fogo do inferno,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'onde seu verme não morre, e o fogo nunca se apaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Porque cada um será salgado com fogo, e cada sacrifício será salgado com sal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'O sal é bom; mas se o sal se tornar insípido, com que o temperareis? Tende sal em vós mesmos, e paz uns com os outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'E levantando-se dali, Jesus se foi aos limites da Judeia, por dalém do Jordão; e as multidões voltaram a se juntar a ele, e voltou a lhes ensinar, como tinha costume.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'E vindo a ele os fariseus, perguntaram-lhe se era lícito ao homem deixar a sua mulher, testando-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Mas ele lhes respondeu: O que Moisés vos mandou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'E eles disseram: Moisés permitiu escrever carta de divórcio, e deixá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'E Jesus lhes respondeu: Foi pela dureza dos vossos corações que ele vos escreveu este mandamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Porém, desde o princípio da criação, macho e fêmea Deus os fez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Por isso, deixará o homem a seu pai e a sua mãe, e se unirá à sua mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'E os dois serão uma só carne; assim, já não são dois, mas sim uma só carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Portanto, o que Deus juntou, não separe o homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'E em casa seus discípulos voltaram a lhe perguntar sobre isto mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'E disse-lhes: Qualquer um que deixar a sua mulher, e se casar com outra, adultera contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'E se a mulher deixar o seu marido, e se casar com outro, adultera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'E lhe traziam crianças para que ele as tocasse, mas os discípulos repreendiam aos que as traziam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Porém Jesus, vendo, indignou-se, e lhe disse: Deixai vir as crianças a mim, e não as impeçais; porque delas é o Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Em verdade vos digo, que qualquer um que não receber o Reino de Deus como criança, em maneira nenhuma nele entrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Então, tomando-as entre seus braços, e pondo as mãos sobre elas, ele as abençoou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'E quando ele saiu para caminhar, um homem correu até ele; e pondo-se de joelhos diante dele, perguntou-lhe: Bom Mestre, que farei para herdar a vida eterna?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'E Jesus lhe disse: Por que me chamas bom? Ninguém é bom, a não ser um: Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Sabes os mandamentos: Não adulterarás; não matarás; não furtarás; não darás falso testemunho; não serás enganador; honra o teu pai e a tua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Porém ele lhe respondeu: Mestre, tudo isto guardei desde a minha juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'E olhando Jesus para ele, amou-o, e disse-lhe: Uma coisa te falta: vai, vende tudo quanto tens, e dá aos pobres; e terás um tesouro no céu; e vem, segue-me, toma tua cruz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Mas ele, pesaroso desta palavra, foi-se triste; porque tinha muitas propriedades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Então Jesus olhando ao redor, disse a seus discípulos: Como é difícil aos que têm riquezas entrar no Reino de Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'E os discípulos se espantaram destas suas palavras; mas Jesus, voltando a responder, disse-lhes: Filhos, como é difícil aos que confiam em riquezas entrar no Reino de Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Mais fácil é passar um camelo pelo olho de uma agulha, do que entrar um rico no Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'E eles se espantavam ainda mais, dizendo uns para os outros: Quem, pois, poderá se salvar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Porém, olhando Jesus para eles, disse: Para os seres humanos, é impossível; mas para Deus, não; porque para Deus tudo é possível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'E Pedro começou a lhe dizer: Eis que nós deixamos tudo, e te seguimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jesus respondeu: Em verdade vos digo, que não há ninguém que tenha deixado casa, ou irmãos, ou irmãs, ou pai, ou mãe, ou esposa, ou filhos, ou campos, por amor de mim e do Evangelho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'que não receba cem vezes tanto, agora neste tempo, casas, e irmãos, e irmãs, e mães, e filhos, e campos, com perseguições; e a vida eterna, no tempo que virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Porém muitos primeiros serão últimos, e últimos, primeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'E iam pelo caminho, subindo para Jerusalém; e Jesus ia diante deles, e espantavam-se, e seguiam-no atemorizados. E voltando a tomar consigo aos doze, começou-lhes a dizer as coisas que lhe viriam a acontecer:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Eis que subimos a Jerusalém, e o Filho do homem será entregue aos chefes dos sacerdotes, e aos escribas; e o condenarão à morte, e o entregarão aos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'E escarnecerão dele, e o açoitarão, e cuspirão nele, e o matarão; e ao terceiro dia ressuscitará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'E vieram a ele Tiago e João, filhos de Zebedeu, dizendo: Mestre, queríamos que nos fizesses o que pedirmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'E ele lhes disse: O que quereis que eu vos faça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'E eles lhe disseram: Concede-nos que em tua glória nos sentemos, um à tua direita, e outro à tua esquerda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Mas Jesus lhes disse: Não sabeis o que pedis; podeis vós beber o copo que eu bebo, e ser batizados com o batismo com que eu sou batizado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'E eles lhe disseram: Podemos. Porém Jesus lhes disse: Em verdade, o copo que eu bebo, bebereis; e com o batismo com que eu sou batizado, sereis batizados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Mas sentar-se à minha direita, e à minha esquerda, não é meu concedê-lo, mas sim, para aqueles a quem está preparado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'E quando os dez ouviram isto, começaram a se irritar contra Tiago e João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Mas Jesus, chamando-os a si, disse-lhes: Já sabeis que os que são vistos como governadores dos gentios, agem como senhores deles; e os grandes usam de autoridade sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Mas entre vós não será assim; antes qualquer que entre vós quiser ser grande, será vosso servidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'E qualquer que de vós quiser ser o primeiro, será servo de todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Porque também não veio o Filho do homem para ser servido, mas para servir, e dar sua vida em resgate por muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'E vieram a Jericó. E saindo ele, e seus discípulos, e uma grande multidão de Jericó, estava Bartimeu, um cego, filho de Timeu, sentado junto ao caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'E ouvindo que era Jesus o nazareno, começou a clamar, e a dizer: Jesus, Filho de Davi! Tem misericórdia de mim!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'E muitos o repreendiam, para que se calasse; mas ele clamava ainda mais: Filho de Davi! Tem misericórdia de mim!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Jesus parou, e disse que o chamassem. Então chamaram ao cego, dizendo-lhe: Tem bom ânimo, levanta-te, ele está te chamando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Então ele lançou sua capa, levantou-se, e veio a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Jesus, lhe perguntou: Que queres que eu te faça? E o cego lhe disse: Mestre, que eu veja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jesus lhe disse: Vai; a tua fé te salvou. E logo consegiu ver. Então seguiu Jesus pelo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'E quando se aproximaram de Jerusalém, de Betfagé, e de Betânia, junto ao monte das Oliveiras, Jesus enviou dois de seus discípulos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'dizendo-lhes: Ide ao vilarejo que está adiante de vós; e assim que nela entrardes, achareis um jumentinho amarrado, sobre o qual ninguém se sentou; soltai-o, e trazei-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'E se alguém vos disser: Por que fazeis isso?, dizei: O Senhor precisa dele, e logo o devolverá para cá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Eles foram, e acharam o jumentinho amarrado à porta, do lado de fora em uma esquina, e o soltaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'E alguns dos que ali estavam lhes perguntaram: Que fazeis, soltando o jumentinho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Eles lhes disseram como Jesus lhes havia mandado, e os deixaram ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Então trouxeram o jumentinho a Jesus. Lançaram sobre ele suas roupas, e Jesus sentou-se sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Muitos estendiam suas roupas pelo caminho, e outros cortavam ramos das árvores, e os espalhavam pelo caminho..');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'E os que iam adiante, e os que seguiam, clamavam: Hosana, bendito o que vem no Nome do Senhor!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Bendito o Reino que vem no Nome do Senhor, o Reino do nosso pai Davi! Hosana nas alturas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Jesus entrou em Jerusalém, e no Templo. E depois que ter visto tudo em redor, e sendo já tarde, ele saiu para Betânia com os doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'E no dia seguinte, quando saíram de Betânia, ele teve fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'E vendo de longe uma figueira que tinha folhas, veio ver se acharia alguma coisa nela; mas ao chegar perto dela, nada achou, a não ser folhas, pois não era o tempo de figos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Então Jesus lhe disse: Nunca mais ninguém coma fruto de ti! E seus discípulos ouviram isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Depois vieram a Jerusalém. E entrando Jesus no Templo, começou a expulsar os que vendiam e compravam no Templo; e revirou as mesas dos cambiadores, e as cadeiras dos que vendiam pombas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'E não consentia que ninguém levasse vaso algum pelo Templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'E ensinava, dizendo-lhes: Não está escrito: Minha casa será chamada casa de oração de todas as nações? Mas vós fizestes dela esconderijo de ladrões!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Os escribas e os chefes dos sacerdotes ouviram isso, e buscavam uma maneira de o matar; pois o temiam, porque toda a multidão estava admirada do ensino dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'E como já era tarde, Jesus saiu fora da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'E passando pela manhã, viram que a figueira estava seca desde as raízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Pedro se lembrou disso, e disse-lhe: Mestre, eis que a figueira que amaldiçoaste, se secou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'E respondendo Jesus, disse-lhes: Tende fé em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Porque em verdade vos digo que qualquer um que disser a este monte: Levanta-te, e lança-te no mar; e não duvidar em seu coração, mas crer que se fará o que diz, tudo o que disser lhe será feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Portanto eu vos digo que tudo o que pedirdes orando, crede que recebereis, e vós o tereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'E quando estiverdes orando, perdoai, se tendes algo contra alguém, para que o vosso Pai, que está nos céus, vos perdoe vossas ofensas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Mas se vós não perdoardes, também o vosso Pai, que está nos céus, não vos perdoará vossas ofensas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Depois voltaram a Jerusalém; e, enquanto ele andava pelo Templo, vieram a ele os chefes dos sacerdotes, os escribas, e os anciãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'E disseram-lhe: Com que autoridade fazes estas coisas? E quem te deu esta autoridade, para fazerdes estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jesus lhes respondeu: Também eu vos farei uma pergunta, e respondei-me; então vos direi com que autoridade faço estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'O batismo de João era do céu ou dos homens? Respondei-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'E eles argumentavam entre si, dizendo: Se dissermos do céu, ele dirá: Por que, pois, não crestes nele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Porém, se dissermos dos homens, tememos ao povo, porque todos consideravam que João era verdadeiramente profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Então responderam a Jesus: Não sabemos. E Jesus lhes replicou: Também eu não vos direi com que autoridade faço estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Então Jesus começou a lhes dizer por parábolas: Um homem plantou uma vinha, cercou-a, fundou nela um esmagador de uvas, edificou uma torre, e a arrendou a uns lavradores; e partiu-se d aquela terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'E, quando chegou o tempo, mandou um servo aos lavradores, para que recebesse dos lavradores do fruto da vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Mas eles, tomando-o à força, feriram-no, e mandaram-no vazio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'E voltou a lhes mandar outro servo; e eles, apedrejando-o, feriram-no na cabeça e voltaram a mandá-lo maltratado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'E voltou a mandar outro, ao qual mataram, e mandou muitos outros, e a uns feriram, e a outros mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Tendo ele, pois, ainda um, o seu filho amado, mandou-lhes também por último a este, dizendo: Pelo menos respeitarão o meu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mas aqueles lavradores disseram entre si: Este é o herdeiro; vinde, e o matemos; então a herança será nossa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'E pegando dele, mataram -no, e lançaram -no fora da vinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Que, pois, o senhor da vinha fará? Ele virá, destruirá aos lavradores, e dará a vinha a outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Acaso ainda não lestes esta escritura: “A pedra que os edificadores rejeitaram, esta foi feita por cabeça de esquina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Pelo Senhor foi feito isto, e é maravilhoso em nossos olhos”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'E buscavam prendê-lo, mas temiam a multidão; porque entendiam que era contra eles que dizia aquela parábola; então o deixaram e se retiraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'E mandaram-lhe alguns dos fariseus e dos herodianos, para que o apanhassem em alguma palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Eles se aproximaram e lhe disseram: Mestre, sabemos que és homem de verdade, e não te interessa agradar a ninguém, porque não te importas com a aparência humana, mas com verdade ensinas o caminho de Deus. É lícito pagar tributo a César, ou não? Devemos pagar, ou não devemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'E ele, entendendo a hipocrisia deles, disse-lhes: Por que estais me tentando? Trazei-me uma moeda, para que eu a veja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'E trouxeram. E perguntou-lhes: De quem é esta imagem, e a inscrição? E eles lhe disseram: De César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Então Jesus, lhes respondeu: Dai, pois, a César o que é de César, e a Deus o que é de Deus. E admiram-se dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'E vieram a ele os saduceus, que dizem não haver ressurreição, e perguntaram-lhe:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Mestre, Moisés nos escreveu que, se o irmão de alguém morresse, e deixasse mulher, mas não filhos, que seu irmão se casasse com a viúva, e gerasse descendência ao seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Houve, pois, sete irmãos, e o primeiro casou-se com a mulher, e morrendo, não deixou descendente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Casou-se com ela também o segundo, e morreu; e nem este deixou descendente; e o terceiro da mesma maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Os sete casaram-se com ela, mas não deixaram descendente. Finalmente, depois de todos, morreu também a mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Na ressurreição, pois, quando ressuscitarem, ela será a mulher de qual deles? Porque os sete a tiveram por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'E Jesus lhes respondeu: Acaso não é por isso que errais, por não conhecerdes as Escrituras, nem o poder de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Pois, quando ressuscitarem dos mortos, nem se casarão, nem se darão em casamento; mas serão como os anjos que estão nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'E quanto aos mortos que ressuscitarão, não lestes no livro de Moisés, como Deus lhe falou com a sarça, dizendo: Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Deus não é Deus de mortos, mas de vivos. Portanto errais muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Então aproximou-se dele um dos escribas, que os havia ouvido discutir. Como ele sabia que Jesus havia lhes respondido bem, perguntou-lhe: Qual é o primeiro mandamento de todos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'E Jesus lhe respondeu: O primeiro de todos os mandamentos é: “Ouve Israel, o Senhor nosso Deus é o único Senhor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'amarás, pois, ao Senhor teu Deus com todo o teu coração, com toda a tua alma, com todo o teu entendimento, e com todas as tuas forças.” Este é o primeiro mandamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'E o segundo é semelhante: “Amarás ao teu próximo como a ti mesmo”. Não há outro mandamento maior que estes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'E o escriba lhe disse: Muito bem, Mestre, com verdade disseste que há um só Deus, e não há outro além dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'E que amá-lo com todo o coração, com todo o entendimento, com toda a alma, e com todas as forças; e amar ao próximo como a si mesmo, é mais que todas as ofertas de queima e sacrifícios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Jesus viu que ele havia respondido sabiamente, e disse-lhe: Não estás longe do Reino de Deus. E ninguém mais ousou lhe perguntar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'E Jesus respondia e dizia, enquanto ensinava no templo: Como os escribas dizem que o Cristo é filho de Davi?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Porque o mesmo Davi disse pelo Espírito Santo: Disse o Senhor ao meu Senhor, senta-te à minha direita, até que eu ponha os teus inimigos debaixo dos teus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Ora, se o próprio Davi o chama de Senhor, como, pois, é so eu filho?E a grande multidão o ouvia de boa vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'E dizia-lhes em seu ensino: Cuidado com os escribas, que gostam de andar com roupas compridas, das saudações nas praças,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'das primeiras cadeiras nas sinagogas, e dos primeiros assentos nas ceias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'que devoram as casas das viúvas, com pretexto de longas orações. Esses receberão mais grave condenação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Quando Jesus estava sentado de frente à arca do tesouro, observava como a multidão lançava dinheiro na arca do tesouro; e muitos ricos lançavam muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'E uma pobre viúva veio, e lançou duas pequenas moedas, de pouco valor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Então Jesus chamou a si os seus discípulos, e disse-lhes: Em verdade vos digo que esta pobre viúva lançou mais que todos os que lançaram na arca do tesouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Porque todos lançaram daquilo que lhes sobra; mas esta, da sua pobreza lançou tudo o que tinha, todo o seu sustento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Quando ele estava saindo do templo, um de seus discípulos lhe disse: Mestre, olha que pedras, e que edifícios!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Jesus respondeu, dizendo-lhe: Vês estes grandes edifícios? Não será deixada pedra sobre pedra, que não seja derrubada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Depois, sentando-se ele no monte das Oliveiras, de frente ao templo, Pedro, Tiago, João, e André perguntaram-lhe à parte:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Dize-nos, quando serão essas coisas? E que sinal haverá de quando todas essas coisas se cumprirão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'E Jesus, respondendo-lhes, começou a dizer: Cuidado! ninguém vos engane;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'porque muitos virão em meu nome, dizendo: “Sou eu”, e enganarão a muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'E quando ouvirdes de guerras e de rumores de guerras, não vos perturbeis; porque assim deve acontecer; mas ainda não será o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Porque nação se levantará contra nação, e reino contra reino, e haverá terremotos em muitos lugares, e haverá fomes e tumultos. Estes serão os princípios das dores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Mas cuidai de vós mesmos; porque vos entregarão em tribunais e em sinagogas; sereis açoitados, e sereis levados diante de governadores e reis, por causa de mim, para que lhes haja testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Mas antes o Evangelho deve ser pregado entre todas as nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Porém, quando vos levarem para vos entregar, não estejais ansiosos antecipadamente do que deveis dizer, nem o planejeis; mas o que naquela hora for dado, isso falai. Porque não sois vós os que falais, mas o Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'E o irmão entregará ao irmão à morte, e o pai ao filho; e os filhos se levantarão contra os pais, e os matarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'E sereis odiados por todos por causa do meu nome; mas quem perseverar até o fim, esse será salvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'E quando virdes a abominação da desolação, que foi dita pelo profeta Daniel, estar onde não deve, (quem lê, entenda), então os que estiverem na Judeia, fujam para os montes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'E quem estiver sobre telhado, não desça para a casa, nem entre para tomar alguma coisa de sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'E quem estiver no campo, não volte atrás, para tomar sua roupa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Mas ai das grávidas, e das que amamentarem naqueles dias!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Orai, porém, para que a vossa fuga não aconteça no inverno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Porque aqueles dias serão de tal aflição, qual nunca foi desde o princípio da criação das coisas, que Deus criou, até agora, nem jamais será.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'E se o Senhor não encurtasse aqueles dias, ninguém se salvaria; mas por causa dos escolhidos, que escolheu, ele encurtou aqueles dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Então se alguém vos disser: “Eis aqui o Cristo”; ou “ei-lo ali”, não creiais nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Porque se levantarão falsos cristos, e falsos profetas, que farão sinais e prodígios, para enganar, se possível, até os escolhidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Vós, porém, tende cuidado; eis que tenho vos dito tudo com antecedência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Mas naqueles dias, depois daquela aflição, o sol se escurecerá, e a lua não dará seu brilho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'as estrelas do céu cairão, e as forças que estão nos céus se abalarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Então verão o Filho do homem vir nas nuvens, com grande poder e glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Ele então enviará os seus anjos, e ajuntará os seus escolhidos dos quatro ventos, desde a extremidade da terra, até a extremidade do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'E aprendei a parábola da figueira: Quando o seu ramo já vai ficando tenro, e brota folhas, bem sabeis que o verão já está perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Assim também vós, quando virdes suceder estas coisas, sabei que já está perto, às portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Em verdade vos digo que não passará esta geração, até que todas estas coisas aconteçam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'O céu e a terra passarão, mas as minhas palavras em maneira nenhuma passarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Porém daquele dia e hora ninguém sabe, nem os anjos que estão no céu, nem o Filho, a não ser somente o Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Olhai, vigiai, e orai; porque não sabeis quando será o tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Assim como o homem que, partindo-se para fora de sua terra, deixou sua casa, e deu autoridade aos seus servos, e a cada um o seu trabalho, e mandou ao porteiro que vigiasse,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'assim também vigiai, porque não sabeis quando virá o Senhor da casa; se à tarde, se à meia-noite, se ao cantar do galo, se pela manhã,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'para que ele não venha de repente, e vos ache dormindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'E as coisas que vos digo, digo a todos: Vigiai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'E dali a dois dias era a Páscoa, e a festa dos pães sem fermento; e os chefes dos sacerdotes, e os escribas buscavam um meio de prendê-lo através de um engano, e o matarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Diziam, porém: “Não na festa, para que não aconteça tumulto entre o povo.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'E estando ele em Betânia, na casa de Simão o Leproso, sentado à mesa, veio uma mulher, que tinha um vaso de alabastro, de óleo perfumado de nardo puro, de muito preço, e quebrando o vaso de alabastro, derramou-o sobre a cabeça dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'E houve alguns que em si mesmos se indignaram, e disseram: “Para que foi feito este desperdício do óleo perfumado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Porque isto podia ter sido vendido por mais de trezentos denários, e seria dado aos pobres.” E reclamavam contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Porém Jesus disse: “Deixai-a; por que a incomodais? Ela me fez boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Porque pobres sempre tendes convosco; e quando quiserdes, podeis lhes fazer bem; porém a mim, nem sempre me tendes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Esta fez o que podia; adiantou-se para ungir o meu corpo, para a sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Em verdade vos digo, que onde quer que em todo o mundo este Evangelho for pregado, também o que esta fez será dito em sua memória.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'E Judas Iscariotes, um dos doze, foi aos chefes dos sacerdotes, para o entregar a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'E eles ouvindo, alegraram-se; e prometeram lhe dar dinheiro; e buscava como o entregaria em tempo oportuno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'E o primeiro dia dos pães sem fermento, quando sacrificavam o cordeiro da Páscoa, seus discípulos lhe disseram: “Onde queres que vamos preparar para comerdes a Páscoa?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'E mandou dois de seus discípulos, e disse-lhes: “Ide à cidade, e um homem que leva um cântaro de água vos encontrará, a ele segui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'E onde quer que ele entrar, dizei ao senhor da casa: O Mestre diz: Onde está o cômodo onde comerei Páscoa com meus discípulos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'E ele vos mostrará um grande salão, ornado e preparado; ali fazei os preparativos para nós.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'E seusdiscípulos saíram, e vieram à cidade, e acharam como havia lhes dito, e prepararam a Páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'E chegada a tarde, veio com os doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'E quando se sentaram à mesa, e comeram, Jesus disse: “Em verdade vos digo, que um de vós, que está comendo comigo, me trairá.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'E eles começaram a se entristecer, e a lhe dizer um após outro: “Por acaso sou eu?” E outro: “Por acaso sou eu?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Porém ele lhes respondeu: “É um dos doze, o que está molhando a mão comigo no prato.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Em verdade o Filho do homem vai, como está escrito sobre ele; mas ai daquele homem por quem o Filho do homem é traído; bom lhe fosse ao tal homem não haver nascido.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'E enquanto eles comiam, Jesus tomou o pão; e bendizendo, partiu-o, deu-lhes, e disse: “Tomai, comei, isto é o meu corpo.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'E tomando o copo, e dando graças, deu-lhes; e todos beberam dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'E disse-lhes: “Isto é o meu sangue, o do novo testamento, que é derramado por muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Em verdade vos digo, que não beberei mais do fruto da vide, até aquele dia, quando o beber novo no Reino de Deus.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'E depois de cantarem um hino, saíram para o monte das Oliveiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'E Jesus lhes disse: “Todos vós vos ofendereis em mim esta noite; porque está escrito: Ferirei ao pastor, e as ovelhas serão dispersas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Mas depois de eu haver ressuscitado, irei adiante de vós para a Galileia.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'E Pedro lhe disse: “Ainda que todos se ofendam, porém eu não.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Jesus lhe disse: “Em verdade te digo, que hoje, nesta noite, antes que o galo cante duas vezes, me negarás três vezes.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mas Pedro, insistindo, dizia: “Ainda que me seja necessário morrer contigo, em maneira nenhuma te negarei.” E todos diziam também da mesma maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'E vieram ao lugar, cujo nome era Getsêmani, e disse a seus discípulos: “Sentai-vos aqui, enquanto eu oro.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'E tomou consigo Pedro, Tiago, e João, e começou a ficar muito apavorado e angustiado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'E disse-lhes: “Minha alma totalmente está triste até a morte; ficai-vos aqui, e vigiai.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Então ele foi um pouco mais adiante, e prostrou-se em terra. E orou, que se fosse possível, afastasse dele aquela hora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'E disse: “Aba, Pai, todas as coisas te são possíveis; passa de mim este copo; porém não se faça o que eu quero, mas sim o que tu queres.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Depois veio de volta, e os achou dormindo; e disse a Pedro: “Simão, estás dormindo? Não podes vigiar uma hora?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Vigiai, e orai, para que não entreis em tentação; o espírito em verdade está pronto, mas a carne é fraca.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'E depois que se foi novamente, orou, dizendo as mesmas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Quando voltou, achou-os outra vez dormindo; porque os olhos deles estavam pesados, e não sabiam o que lhe responder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'E veio a terceira vez, e disse-lhes: “Ainda estais dormindo e descansando? Basta, chegada é a hora. Eis que o Filho do homem é entregue em mãos dos pecadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Levantai-vos, vamos; eis que o que me trai está perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'E logo, enquanto ele ainda estava falando, veio Judas, que era um dos doze, e com ele uma grande multidão, com espadas e bastões, da parte dos chefes dos sacerdotes, dos escribas, dos anciãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'E o que o traía lhes tinha dado um sinal comum, dizendo: “Ao que eu beijar, é esse; prendei-o, e levai-o em segurança.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'E quando veio, logo foi-se a ele, e disse-lhe: “Rabi, Rabi”, e o beijou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Então o agarraram, e o prenderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'E um dos que estavam ali presentes puxou a espada, feriu o servo do sumo sacerdote, e cortou-lhe a orelha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Jesus começou a lhes dizer: “Viestes me prender com espadas e bastões, como se eu fosse um bandido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Todo dia eu estava convosco no templo, ensinando, e não me prendestes; mas assim se faz para que as Escrituras se cumpram.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Então todos o deixaram, e fugiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'E certo rapaz o seguia, envolto num lençol sobre o corpo nu. E os rapazes o agarraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Mas ele largou o lençol, e fugiu deles nu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'E levaram Jesus ao sumo sacerdote; e ajuntaram-se a ele todos os chefes dos sacerdotes, os anciãos, e os escribas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'E Pedro o seguiu de longe até dentro do pátio do sumo sacerdote, e ficou sentado com os oficiais, esquentando-se ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'E os chefes dos sacerdotes, e todo o tribunal buscavam algum testemunho contra Jesus, para o matarem, e não o achavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Porque muitos davam falso testemunho contra ele, mas os testemunhos não concordavam entre si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'E alguns se levantavam e davam falso testemunho contra ele, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '“Nós o ouvimos dizer: Eu derrubarei este templo feito por mãos, e em três dias construirei outro feito não por mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'E nem assim o testemunho deles era concordante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Então o sumo sacerdote levantou-se no meio, e perguntou a Jesus: “Não respondes nada? O que estes testemunham contra ti?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Mas ele ficou calado, e nada respondeu. O sumo sacerdote voltou a lhe perguntar: “És tu o Cristo, o Filho daquele que é Bendito?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jesus respondeu: “Eu sou. E vereis o Filho do homem sentado à direita do Poderoso, e vindo com as nuvens do céu.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'E o sumo sacerdote, rasgando suas roupas, disse: “Para que mais necessitamos de testemunhas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vós ouvistes a blasfêmia. Que vos parece?” E todos o condenaram como culpado de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'E alguns começaram a cuspir nele, e a cobrir o rosto dele; e a dar-lhe de socos, e dizer-lhe: “Profetiza”. E os oficiais lhe davam bofetadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'E, enquanto Pedro estava no pátio abaixo, veio uma das servas do sumo sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Quando ela viu Pedro, que estava sentado esquentando-se, olhou para ele, e disse: “Também tu estavas com Jesus, o Nazareno.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Mas ele negou, dizendo: “Não o conheço, nem sei o que dizes.”; e saiu para o alpendre. Então o galo cantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'A serva o viu outra vez, e começou a dizer aos que ali estavam: “Este é um deles”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Mas ele o negou de novo. E pouco depois, outra vez os que ali estavam disseram a Pedro: “Verdadeiramente tu és um deles; pois também és galileu”, e a tua fala é semelhante”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Então ele começou a amaldiçoar e a jurar, dizendo: “Não conheço esse homem de quem dizeis.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'O galo cantou a segunda vez. E Pedro se lembrou da palavra que Jesus havia lhe dito: “Antes que o galo cante duas vezes, tu me negarás três vezes.” Então ele retirou-se dali e chorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'E logo ao amanhecer, os chefes dos sacerdotes tiveram uma reunião com os anciãos, com os escribas, e com todo o tribunal; e, amarrando a Jesus, levaram -no e o entregaram a Pilatos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'E Pilatos lhe perguntou: És tu o Rei dos Judeus? E ele lhe respondeu: Tu o dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'E os chefes dos sacerdotes o acusavam de muitas coisas, porém ele nada respondia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'E outra vez Pilatos lhe perguntou: Não respondes nada? Olha quantas coisas testemunham contra ti!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Mas Jesus nada mais respondeu, de maneira que Pilatos ficou surpreso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Na festa, Pilatos lhes soltava um preso, qualquer um que pedissem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'E havia um chamado Barrabás, preso com outros revoltosos, que numa rebelião havia cometido uma morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'E a multidão, gritando, começou a pedir, como sempre lhes havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'E Pilatos lhes respondeu: Quereis que eu vos solte o Rei dos Judeus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, '(Porque ele sabia que os chefes dos sacerdotes haviam o entregue por inveja).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mas os chefes dos sacerdotes incitaram a multidão, para que, em vez disso, lhes soltasse Barrabás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'E Pilatos, respondendo, disse-lhes outra vez: Que, pois, quereis que eu faça com aquele a quem chamais Rei dos Judeus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'E eles voltaram a clamar: Crucifica-o!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Mas Pilatos lhes disse: Por quê? Que mal ele fez? E eles gritavam ainda mais: Crucifica-o!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Então Pilatos, querendo satisfazer à multidão, soltou-lhes Barrabás; e entregou Jesus açoitado, para que fosse crucificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'E os soldados o levaram para o pátio, que é o pretório; e convocaram toda a tropa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'E o vestiram de púrpura; teceram uma coroa de espinhos, e puseram nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'E começaram a saudá-lo: Viva! Ó Rei dos Judeus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'E feriram a sua cabeça com uma cana, cuspiram nele, e, ajoelhados, o adoraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Quando o escarneceram, despiram-lhe a púrpura, vestiram-no com as suas próprias roupas, e o levaram afora, para o crucificarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'E forçaram um Simão cireneu, que estava passando, vindo do campo, o pai de Alexandre e de Rufo, para que levasse sua cruz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'E o levaram ao lugar de Gólgota, que traduzido é: o lugar da caveira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'E ofereceram-lhe a beber vinho misturado com mirra; mas ele não o tomou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'E havendo o crucificado, repartiram a roupas dele, lançando-lhes sortes, para o que cada um levaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Era a hora terceira, e o crucificaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'E a descrição de sua acusação estava acima escrita: O REI DOS JUDEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'E crucificaram com ele dois ladrões, um à sua direita, e outro à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'E cumpriu-se a Escritura que diz: E foi contado com os malfeitores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'E os que passavam blasfemavam dele, balançando suas cabeças, e dizendo: Ah! tu que derrubas o templo, e em três dias o edificas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'salva a ti mesmo, e desce da cruz!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'E da mesma maneira também os chefes dos sacerdotes, com os escribas, diziam aos outros, escarnecendo: Ele salvou a outros, a si mesmo não pode salvar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Que o Cristo, o Rei de Israel, desça agora da cruz, para que o vejamos, e creiamos! Os que estavam crucificados com ele também o insultavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'E vinda a hora sexta, vieram trevas sobre toda a terra, até a hora nona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'E na hora nona, Jesus exclamou em alta voz: ELOÍ, ELOÍ, LAMÁ SABACTÂNI, que traduzido é: Deus meu, Deus meu, por que me desamparaste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'E alguns dos que ali estavam, quando ouviram, disseram: Eis que ele está chamando Elias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'E um correu, encheu de vinagre uma esponja; e pondo-a em uma cana, dava-lhe de beber, dizendo: Deixai, vejamos se Elias virá tirá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'E Jesus bradou em grande voz, então expirou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'E o véu do Templo se rasgou em dois do alto abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'E o centurião que estava ali diante dele, vendo que havia expirado bradando assim, disse: Verdadeiramente este homem era Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'E também estavam ali algumas mulheres olhando de longe, entre as quais estava também Maria Madalena, e Maria (mãe de Tiago o menor e de José), e Salomé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'as quais também, quando ele estava na Galileia, o seguiam, e o serviam; e outras muitas, que haviam subido com ele a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'E quando já vinha o final da tarde, porque era a preparação, que é o dia antes de sábado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Veio José de Arimateia, honrado membro do conselho, que também esperava o Reino de Deus, e com ousadia foi a Pilatos, e pediu o corpo de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatos se surpreendeu de que já fosse morto. E chamou a si o centurião, e perguntou-lhe se já era morto já havia muito tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Quando ele recebeu a explicação do centurião, deu o corpo a José,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'o qual comprou um lençol fino, e tirando-o da cruz, envolveu-o no lençol fino. Em seguida, ele o pôs num sepulcro escavado em uma rocha, e rolouuma pedra à porta do sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Maria Madalena e Maria mãe de José olharam onde o puseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Havendo passado o sábado, Maria Madalena, e Maria mãe de Tiago, e Salomé, compraram especiarias, para irem o ungir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'E de manhã muito cedo, o primeiro dia da semana, vieram ao sepulcro, ao nascer do sol.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'E diziam umas às outras: Quem rolará para nós a pedra da porta do sepulcro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Pois era muito grande. E quando observaram, viram que já a pedra estava havia sido rolada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'e entrando no sepulcro, viram um rapaz sentado à direita, vestido com uma roupa comprida branca; e elas se espantaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Mas ele lhes disse: Não vos espanteis. Vós buscais a Jesus Nazareno crucificado. Ele já ressuscitou, não está aqui. Eis aqui o lugar onde o puseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Porém ide, dizei a seus discípulos e a Pedro, que ele vai adiante de para a Galileia; ali o vereis, como ele vos disse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Então elas, saindo apressadamente, fugiram do sepulcro, porque temor e espanto as haviam tomado; e não disseram nada a ninguém, porque tinham medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'E havendo ressuscitado pela manhã, no primeiro dia da semana, Jesus apareceu primeiramente a Maria Madalena, da qual havia expulsado sete demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ela se foi, e anunciou aos que estiveram com ele, que estavam tristes e chorando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Quando ouviram que ele estava vivo, e que havia sido visto por ela, eles não creram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'E depois ele apareceu em outra forma a dois deles, que estavam indo pelo caminho ao campo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'E estes foram anunciar aos outros; mas também não creram neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Finalmente ele apareceu aos onze, estando eles sentados juntos; e repreendeu pela incredulidade e dureza de coração deles, por não terem crido nos que já o haviam visto ressuscitado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'E disse-lhes: Ide por todo o mundo, pregai o Evangelho a toda criatura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Quem crer e for batizado será salvo; mas quem não crer será condenado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'E estes sinais seguirão aos que crerem: em meu nome expulsarão demônios; falarão novas línguas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'pegarão serpentes com as mãos; e se beberem algo mortífero, não lhes fará dano algum; porão as mãos sobre os enfermos, e sararão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Então o Senhor, depois de haver lhes falado, foi recebido acima no céu, e sentou-se à direita de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'E eles saíram e pregaram por todas as partes, com o Senhor operando com eles, e confirmando a palavra com os sinais que se seguiam. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Como muitos empreenderam pôr em ordem o relato das coisas que entre nós se cumpriram,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'conforme os que as viram que desde o princípio, e foram servidores das palavra, nos transmitiram,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'pareceu-me bom que também eu, que tenho me informado com exatidão desde o princípio, escrevesse-as em ordem a ti, caríssimo Teófilo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'para que conheças a certeza das coisas de que foste ensinado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Houve nos dias de Herodes, rei da Judeia, um sacerdote chamado Zacarias, da ordem de Abias; sua mulher das filhas de Arão, e o seu nome era Isabel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'E ambos eram justos diante de Deus; andavam sem repreensão em todos os mandamentos e preceitos do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Mas não tinham filho, porque Isabel era estéril, e ambos tinham idade avançada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'E aconteceu que, quando ele fazia o trabalho sacerdotal diante de Deus, na ordem da sua turma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'conforme o costume do sacerdócio, foi sorteado a entrar no santuário do Senhor para oferecer o incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'E toda a multidão do povo estava fora orando, à hora do incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Então um anjo do Senhor lhe apareceu em pé, à direita do altar do incenso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Quando Zacarias o viu, perturbou-se, e o medo o tomou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Mas o anjo lhe disse: Zacarias, não temas, pois a tua oração foi ouvida. E Isabel, tua mulher, dará à luz um filho, e lhe porás o nome de João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'E terás prazer e alegria, e muitos se alegrarão do seu nascimento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'pois ele será grande diante do Senhor, e não beberá vinho nem bebida alcoólica, e será cheio do Espírito Santo, já desde o ventre da sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'E converterá muitos dos filhos de Israel ao Senhor seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'E irá adiante dele no espírito e virtude de Elias, para converter os corações dos pais aos filhos, e os rebeldes à prudência dos justos; a fim de preparar um povo pronto ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Então Zacarias disse ao anjo: Como terei certeza disso? Pois sou velho, e a minha mulher de idade avançada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'O anjo lhe respondeu: Eu sou Gabriel, que fico presente diante de Deus, e fui enviado para te falar e te dar estas boas notícias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Eis que ficarás mudo, e não poderás falar até o dia em que essas coisas aconteçam, porque não creste nas minhas palavras, que se cumprirão no devido tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'E o povo estava esperando Zacarias, e se surpreenderam de que ele demorava no santuário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Quando ele saiu, não conseguia lhes falar; e entenderam que havia tido alguma visão no santuário. Ele lhes fazia gestos, e continuou mudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'E sucedeu que, terminados os dias do seu serviço, voltou à sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'E depois daqueles dias Isabel, sua mulher, Isabel, engravidou-se, e por cinco meses se escondeu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Pois isto o Senhor me fez nos dias em que ele me olhou, para acabar a minha humilhação entre as pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'E no sexto mês o anjo Gabriel foi enviado por Deus a uma cidade da Galileia, chamada Nazaré,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'a uma virgem prometida em casamento com um homem chamado José, da descendência de Davi; e o nome da virgem era Maria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'O anjo entrou onde ela estava, e disse: Alegra-te, agraciada; o Senhor é contigo, bendita és tu entre as mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Quando ela o viu, perturbou-se muito por suas palavras, e se perguntava que saudação seria esta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Então o anjo lhe disse: Maria, não temas, porque encontraste graça diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'E eis que em teu ventre conceberás, darás à luz um filho, e chamarás o seu nome de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Ele será grande, e será chamado Filho do Altíssimo; e o Senhor Deus lhe dará o trono de Davi, seu ancestral.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'E reinará eternamente na casa de Jacó; o seu reino não terá fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Maria disse ao anjo: Como será isso? Pois não conheço intimamente homem algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'O anjo lhe respondeu: O Espírito Santo virá sobre ti, e o poder do Altíssimo te cobrirá com a sua sombra. Por isso o Santo que nascerá de ti será chamado Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'E eis que Isabel, tua prima, também está grávida de um filho na sua velhice; e este é o sexto mês para a que era chamada de estéril.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Pois para Deus nada será impossível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Então Maria disse: Eis aqui a serva do Senhor; cumpra-se em mim conforme a tua palavra. E o anjo ausentou-se dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'E naqueles dias, Maria levantou-se, e foi apressada à região montanhosa, a uma cidade de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Ela entrou na casa de Zacarias, e cumprimentou Isabel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'E aconteceu que, quando Isabel ouviu o cumprimento de Maria, a criança saltou no seu ventre, e Isabel foi cheia do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Então exclamou em alta voz: Bendita és tu entre as mulheres, e bendito é o fruto do teu ventre!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Como me acontece isto, que a mãe de meu Senhor venha a mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Pois eis que, quando a voz do teu cumprimento chegou aos meus ouvidos, a criança saltou de alegria no meu ventre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'E bendita a que creu, pois se cumprirão as coisas que do Senhor lhe foram ditas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Então Maria disse: A minha alma engrandece ao Senhor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'e o meu espírito se alegra em Deus meu Salvador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Porque ele olhou para a humilde condição da sua serva; pois eis que desde agora todas as gerações me chamarão bendita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Pois o Poderoso me fez grandes coisas; e santo é o seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'E a sua misericórdia é de geração em geração sobre os que o temem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Com o seu braço manifestou poder; dispersou os soberbos no pensamento dos seus corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Derrubou os poderosos dos tronos, e elevou os humildes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Encheu de bens aos famintos, e despediu vazios os ricos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Auxiliou ao seu servo Israel, lembrando-se da sua misericórdia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'como falou aos nossos ancestrais, a Abraão, e à sua descendência, para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Maria esteve com ela por quase três meses; então voltou para sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'E completou-se à Isabel o tempo de dar à luz, e teve um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Os seus vizinhos e parentes ouviram que o Senhor havia feito a ela grande misericórdia, e alegraram-se com ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'E aconteceu que ao oitavo dia vieram circuncidar o menino, e o chamavam Zacarias, do nome do seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'E sua mãe respondeu: Não, porém será chamado João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'E disseram-lhe: Ninguém há entre os teus parentes que se chame deste nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'E perguntaram por gestos ao seu pai como queria que lhe chamassem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Ele pediu uma tábua, e escreveu: O seu nome é João. E todos se surpeenderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'E logo a sua boca se abriu, e a sua língua se soltou; e voltou a falar, louvando a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'E veio temor sobre todos os seus vizinhos; e em toda a região montanhosa da Judeia todas essas coisas foram divulgadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'E todos os que ouviam, guardavam em seus corações, dizendo: Quem será este menino? E a mão do Senhor estava com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'E Zacarias, seu pai, foi cheio do Espírito Santo, e profetizou, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Bendito seja o Senhor Deus de Israel, porque visitou e redimiu o seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'E nos levantou uma poderosa salvação na casa de seu servo Davi,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'como falou pela boca dos seus santos profetas, desde o princípio do mundo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Que nos livraria dos nossos inimigos e da mão de todos os que nos odeiam,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'para manifestar misericórdia aos nossos ancestrais, e se lembrar do seu santo pacto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'do juramento que fez a Abraão, nosso ancestral;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'de nos conceder que, libertos da mão dos nossos inimigos, o serviríamos sem temor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'em santidade e justiça diante dele, todos os dias da nossa vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'E tu, menino, serás chamado profeta do Altíssimo; porque irás adiante da face do Senhor, para preparar os seus caminhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'para dar a seu povo conhecimento da salvação, na remissão de seus pecados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'por causa da profunda misericórdia do nosso Deus, pela qual o raiar da manhã nos visitou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'para iluminar os que estão sentados nas trevas e sombra de morte; a fim de guiar os nossos pés pelo caminho da paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'E o menino crescia e se fortalecia em espírito. E esteve nos desertos até o dia em que se mostrou a Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'E aconteceu naqueles dias que saiu um decreto da parte de César Augusto, para que todo a terra se registrasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, '(Esse primeiro censo foi feito quando Quirino era o governador da Síria.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'E todos foram se registrar, cada um à sua própria cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'E José também subiu da Galileia, da cidade de Nazaré à Judeia, à cidade de Davi, que se chama Belém; (porque ele era da casa e família de Davi.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Para se registrar com Maria, sua mulher, com ele prometida em casamento, que estava grávida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'E aconteceu que, enquanto eles ali, completaram-se os dias em que ela havia de dar à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'E deu à luz seu filho primogênito, e o envolveu em panos, e o deitou numa manjedoura; porque não havia lugar para eles na hospedaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'E naquela mesma localidade havia pastores que estavam no campo, e vigiavam o seu rebanho durante as vigílias da noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'E eis que um anjo do Senhor lhe apareceu, e a glória do Senhor os cercou de resplendor. Então tiveram grande temor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'E o anjo lhes disse: Não temais; pois eis que vos dou notícias de grande alegria, que será para todo o povo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'que hoje na cidade de Davi vos nasceu o Salvador, que é Cristo, o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'E isto vos será por sinal: achareis o menino envolto em panos, deitado numa manjedoura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'E no mesmo instante apareceu com o anjo uma multidão de exércitos celestiais, louvando a Deus, e dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Glória nas alturas a Deus, paz na terra, e aos seres humanos boa vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'E aconteceu que, quando os anjos se ausentaram deles para o céu, os pastores disseram uns aos outros: Vamos, pois, até Belém, e vejamos isso que aconteceu, e o Senhor nos informou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Então foram apressadamente, e acharam Maria, e José, e o menino deitado na manjedoura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Quando o viram, contaram o que lhes havia sido dito sobre o menino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'E todos os que ouviram se admiraram com o que os pastores lhes diziam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Mas Maria guardava todas essas palavras, considerando -as no seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Os pastores voltaram glorificando e louvando a Deus por tudo o que haviam ouvido e visto, como lhes havia sido dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Quando se completaram os oito dias para circuncidar o menino, foi chamado o seu nome Jesus, o qual havia sido posto pelo anjo antes que fosse concebido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'E quando se completaram os dias da purificação dela, segundo a Lei de Moisés, o levaram a Jerusalém, para o apresentarem ao Senhor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'conforme o que está escrito na Lei do Senhor: Todo macho primogênito será consagrado ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'E para darem a oferta segundo o que se diz na Lei do Senhor: um par de rolinhas ou dois pombinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'E eis que havia em Jerusalém um homem de nome Simeão; e esse homem era justo e devoto, e esperava a consolação de Israel; e o Espírito Santo estava sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'E havia lhe sido revelado pelo Espírito Santo que ele não veria a morte antes de ter visto o Cristo do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'E pelo Espírito foi ao Templo; e quando os pais trouxeram o menino Jesus, para fazerem com ele conforme o costume da Lei,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Então ele o tomou em seus braços, louvou a Deus, e disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Agora, Senhor, despedes o teu servo em paz, conforme a tua palavra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'pois os meus olhos viram a tua salvação,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'a qual preparaste diante de todos os povos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Luz para iluminar as gentios, e para a glória do teu povo Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'E José e sua mãe se admiraram das coisas que se diziam sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Simeão os abençoou, e disse a Maria, sua mãe: Eis que este é posto para queda e levantamento de muitos em Israel; e para sinal que terá oposição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(também uma espada atravessará a tua própria alma) para que os pensamentos de muitos corações se manifestem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'E estava ali a profetiza Ana, filha de Fanuel, da tribo de Aser. Ela já tinha idade avançada, e havia vivido com o marido sete anos desde sua virgindade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'E era viúva de cerca de oitenta e quatro anos, e não se afastava do Templo, servindo a Deus com jejuns e orações, de noite e de dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'E ela veio na mesma hora; ela agradeci ao Senhor, e falava dele a todos os que esperavam a redenção em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'E quando acabaram de cumprir tudo, segundo a Lei do Senhor, voltaram à Galileia, para a sua cidade de Nazaré.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'E o menino crescia e se fortalecia em espírito, e cheio de sabedoria; e a graça de Deus estava sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Todos os anos, seus pais iam a Jerusalém, para a festa da Páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'E quando Jesus tinha doze anos, subiram a Jerusalém, conforme o costume do festival;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'E quando aqueles dias terminaram, eles partiram de volta, mas o menino Jesus ficou em Jerusalém sem que José e sua mãe soubessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Porém, como pensavam que ele vinha pelo caminho entre os companheiros de viagem, eles andaram o caminho de um dia; e o procuraram entre os parentes e conhecidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'E como não o acharam, voltaram a Jerusalém em busca dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'E aconteceu que, três dias depois, o acharam no templo, sentado no meio dos mestres, ouvindo-os, e perguntando-lhes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'E todos os que o ouviam admiravam a sua inteligência e respostas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Quando eles o viram, ficarm surpresos. E sua mãe lhe disse: Filho, por que fizeste assim conosco? Eis que teu pai e eu com ansiedade te procurávamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Ele lhes disse: Por que me procuráveis? Não sabeis que devo estar nos negócios de meu Pai?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'E eles não entenderam as palavras que lhes dizia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Então desceu com eles, e veio a Nazaré, e os obedecia. E a sua mãe guardava todas essas coisas no seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Jesus crescia em sabedoria, em estatura, e em graça para com Deus e as pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'No ano quinze do império de Tibério César, sendo Pôncio Pilatos o governador da Judeia, Herodes tetraca da Galileia, e seu irmão Filipe o tetrarca da Itureia e da província de Traconites, e Lisânias o tetrarca de Abilene;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'sendo Anás e Caifás os sumos sacerdotes, a palavra de Deus veio a João, filho de Zacarias, no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Ele percorreu toda a região ao redor do Jordão, pregando o batismo de arrependimento, para o perdão dos pecados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'conforme o que está escrito no livro das palavras do profeta Isaías, que diz: “Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Todo vale se encherá, e todo monte e colina se abaixará; os tortos serão endireitados, e os caminhos ásperos se suavizarão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'e todos verão a salvação de Deus.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'João dizia às multidões que vinham ser batizadas por ele: “Raça de víboras, quem vos ensinou a fugir da ira que está para chegar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Dai, pois, frutos condizentes com o arrependimento, e não comeceis a dizer em vós mesmos: ‘Temos Abraão por pai’; pois eu vos digo que até destas pedras Deus pode produzir filhos a Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'E também o machado já está posto à raiz das árvores; portanto, toda árvore que não dá bom fruto é cortada e lançada ao fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'E as multidões lhe perguntavam: Então o que devemos fazer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'E ele lhes respondeu: Quem tiver duas túnicas, reparta com o não tem; e quem tiver comida, faça da mesma maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'E chegaram também uns cobradores de impostos, para serem batizados; e disseram-lhe: Mestre, que devemos fazer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'E ele lhes disse: Não exijais mais do que vos está ordenado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'E uns soldados também lhe perguntaram: E nós, que devemos fazer? E ele lhes disse: Não maltrateis nem defraudeis a ninguém; e contentai-vos com vossos salários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'E, enquanto o povo estava em expectativa, e todos pensando em seus corações se talvez João seria o Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'João respondeu a todos: De fato, eu vos batizo com água, mas vem um que é mais poderoso do que eu, de quem eu não sou digno de desatar a tira das sandálias; ele vos batizará com o Espírito Santo e com fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Sua pá está na sua mão, e limpará sua eira, e juntará o trigo no seu celeiro; porém queimará a palha com fogo que nunca se apaga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Assim, exortando com muitas outras coisas, João anunciava a boa notícia ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Porém, quando Herodes, o tetrarca, foi repreendido por ele por causa de Herodias, mulher do seu irmão Filipe, e por todas as maldades que Herodes havia feito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'acrescentou a todas ainda esta: encarcerou João na prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'E aconteceu que, quando todo o povo era batizado, Jesus também foi batizado, e enquanto orava, o céu se abriu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'e o Espírito Santo desceu sobre ele em forma corpórea, como pomba; e veio do céu uma voz que dizia: Tu és o meu Filho amado, em ti me agrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'E o mesmo Jesus começou quando tinha cerca de trinta anos, sendo (como se pensava) filho de José, filho de Eli,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'filho de Matate, filho de Levi, filho de Melqui, filho de Janai, filho de José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'filho de Matatias, filho de Amós, filho de Naum, filho de Esli, filho de Nagai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'filho de Maate, filho de Matatias, filho de Semei, filho de José, filho de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'filho de Joaná, filho de Resa, filho de Zorobabel, e filho de Salatiel, filho de Neri.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'filho de Melqui, filho de Adi, e filho de Cosã, filho de Elmodã, filho de Er.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'filho de José, filho de Eliézer, filho de Jorim, filho de Matate, filho de Levi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'filho de Simeão, filho de Judá, filho de José, filho de Jonã, filho de Eliaquim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'filho de Meleá, filho de Mainã, filho de Matatá, filho de Natã, filho de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Filho de Jessé, filho de Obede, filho de Boaz, filho de Salmom, filho de Naassom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Filho de Aminadabe, filho de Arão, filho de Esrom, filho de Peres, filho de Judá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'filho de Jacó, filho de Isaque, filho de Abraão, filho de Terá, filho de Naor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'filho de Serugue, filho de Ragaú, filho de Faleque, filho de Éber, filho de Salá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Filho de Cainã, filho de Arfaxade, filho de Sem, filho de Noé, filho de Lameque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Filho de Matusalém, filho de Enoque, filho de Jarede, filho de Maleleel, filho de Cainã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'filho de Enos, filho de Sete, filho de Adão, e Adão de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'E Jesus, cheio do Espírito Santo, voltou do Jordão, e foi levado pelo Espírito ao deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'E por quarenta dias foi tentado pelo diabo; e não comeu coisa alguma naqueles dias; e terminados eles, depois teve fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Então o diabo lhe disse: Se tu és Filho de Deus, diz a esta pedra que se transforme em pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Jesus lhe respondeu: Está escrito que não só de pão viverá o ser humano, mas de toda palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'E o diabo o levou a um alto monte, e lhe mostrou todos os reinos do mundo num instante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'E o diabo lhe disse: Darei a ti todo este poder e sua glória; pois a mim foram entregues, e os dou a quem quero.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Portanto, se tu me adorares, tudo será teu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'E Jesus lhe respondeu: Para trás de mim, Satanás!Porque está escrito: Adorarás ao Senhor teu Deus, e servirás só a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Então o levou a Jerusalém, e o pôs sobre a parte mais alta do templo, e disse-lhe: Se tu és o Filho de Deus, lança-te daqui abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Porque está escrito que: Mandará aos seus acerca de ti que te guardem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'E que: te sustentarão pelas mãos, para que nunca tropeces com o teu pé em alguma pedra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Jesus lhe respondeu: Dito está: Não tentes ao Senhor teu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'E quando o diabo acabou toda a tentação, ausentou-se dele por algum tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Então Jesus, no poder do Espírito, voltou para a Galileia, e sua fama se espalhou por toda a região ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Ele ensinava em suas sinagogas, e era recebido com honra por todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Ele veio a Nazaré, onde havia sido criado, e entrou, conforme o seu costume, num dia de Sábado, na sinagoga; e levantou-se para ler.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Foi-lhe dado o livro do profeta Isaías; e quando abriu o livro, achou o lugar onde estava escrito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'O Espírito do Senhor está sobre mim, porque ele me ungiu para evangelizar os pobres, me enviou para curar os contritos de coração;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'para proclamar liberdade aos cativos e dar vista aos cegos, para enviar livres os oprimidos, para proclamar o ano agradável do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Ele fechou o livro, e devolveu-o ao assistente, e se sentou. Os olhos de todos na sinagoga estavam fixos nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Então ele começou a lhes dizer: Hoje esta escritura se cumpriu em vossos ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'E todos davam testemunho dele, e se admiravam das palavras graciosas que saíam da sua boca; e diziam: Não é este o filho de José?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'E ele lhes disse: Sem dúvida me direis este provérbio: Médico, cura a ti mesmo; faz também aqui na tua terra natal todas as coisas que ouvimos terem sido feitas em Cafarnaum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'E disse: Em verdade vos digo que nenhum profeta é bem recebido na sua terra natal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Porém em verdade vos digo que hava muitas viúvas em Israel nos dias de Elias, quando o céu se fechou por três anos e seis meses, de modo que em todo o país houve grande fome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Mas a nenhuma delas Elias foi enviado, a não ser a uma mulher viúva de Sarepta de Sidom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'E havia muitos leprosos em Israel no tempo do profeta Eliseu; mas nenhum deles foi limpo, a não ser Naamã, o sírio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'E todos na sinagoga, quando ouviram essas coisas, encheram-se de ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Então se levantaram, expulsaram-no da cidade, e o levaram até o topo do monte em que sua cidade era construída, para dali o lançarem abaixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Porém ele passou por meio deles, e se retirou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Ele desceu a Cafarnaum, cidade de Galileia; e ali os ensinava nos sábados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'E admiravam o seu ensino, pois a sua palavra era com autoridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'E estava na sinagoga um homem que tinha um espírito de um demônio imundo, e gritou com alta voz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'dizendo: Ah, que temos contigo, Jesus Nazareno? Vieste para nos destruir? Sei quem és: o Santo de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'E Jesus o repreendeu, dizendo: Cala-te, e, sai dele. E o demônio o derrubou no meio do povo, e saiu dele sem lhe fazer dano algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'E espanto veio sobre todos; e falavam entre si uns aos outros, dizendo: Que palavra é esta, que até aos espíritos imundos ele manda com autoridade e poder, e eles saem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'E sua fama era divulgada em todos os lugares em redor daquela região.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Jesus levantou-se da sinagoga, e entrou na casa de Simão. A sogra de Simão estava doente de uma grande febre, e rogaram-lhe por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Ele se inclinou a ela, e repreendeu a febre, que a deixou. Ela imediatamente se levantou e começou a lhes servir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Quando o sol estava se pondo, troxeram-lhe todos os que estavam enfermos de varias doenças. Ele punha as mãos sobre cada um deles e os curava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'E também de muitos saíam demônios, gritando, e dizendo: Tu és o Cristo, o Filho de Deus. Ele os repreendia, e não os deixava falar, porque sabiam que ele era o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'E sendo já dia, ele saiu, e foi a um lugar deserto. As multidões o buscavam; então vieram a ele, e queriam detê-lo, para que não os deixasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Porém ele lhes disse: Também é necessário que eu anuncie a outras cidades o evangelho do Reino de Deus; pois para isso sou enviado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'E ele pregava nas sinagogas da Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'E aconteceu que as multidões o comprimiam para ouvir a palavra de Deus, quando ele estava junto ao lago de Genesaré.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Então ele viu dois barcos que estavam próximos da margem do lago, e os pescadores haviam descido deles, e estavam lavando as redes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Ele entrou num daqueles barcos, que era o de Simão, e lhe pediu que o afastasse um pouco da terra. Depois se sentou, e do barco ensinou às multidões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Quando acabou de falar, disse a Simão: Vai à água profunda, e lançai as vossas redes para pescar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Simão lhe respondeu: Mestre, trabalhamos toda a noite, mas nada pegamos; mas pela tua palavra lançarei a rede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Eles fizeram assim, e recolheram grande quantidade de peixes, e sua rede estava se rompendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Então acenaram aos companheiros que estavam no outro barco, para que viessem os ajudar. Vieram, e encheram ambos os barcos, de tal maneira que quase afundavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Quando Simão Pedro viu isso, prostrou-se aos pés de Jesus, dizendo: Afasta-te de mim, Senhor, porque sou um homem pecador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Pois ele estava cheio de espanto, como todos os que estavam com ele, por causa da coleta de peixes que haviam feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'E semelhantemente, também, Tiago e João, filhos de Zebedeu, que eram colegas de Simão. E Jesus disse a Simão: Não temas, de agora em diante pescarás gente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Eles levaram os barcos para a terra, deixaram tudo, e o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'E aconteceu que, quando ele estava numa daquelas cidades, eis que um homem cheio de lepra viu Jesus; então prostrou-se sobre o rosto, e lhe rogou, dizendo: Senhor, se quiseres, podes me tornar limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Ele estendeu a mão, e o tocou, dizendo: Quero; sê limpo. E logo a lepra desapareceu dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'E mandou-lhe que não o dissesse a ninguém: Mas vai, mostra-te ao sacerdote, e oferece por tua purificação, como Moisés mandou, para lhes dar testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Porém a sua fama se espalhava ainda mais; e ajuntavam-se muitas multidões para o ouvir, e para serem por ele curadas de suas enfermidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Porém ele se retirava para os desertos, e ali orava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'E aconteceu num daqueles dias que estava ensinando, e estavam ali sentados fariseus e instrutores da lei, que tinham vindo de todas as aldeias da Galileia, da Judeia, e de Jerusalém; e o poder do Senhor estava ali para os curar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'E eis que uns homens traziam numa cama um homem que estava paralítico; e procuravam levá-lo para dentro, a fim de o porem diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Como não acharam por onde pudessem levá-lo para dentro, por causa da multidão, subiram ao telhado, e pelas telhas o baixaram com o leito para o meio do povo, diante de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Ele viu a fé deles, e disse-lhe: Homem, teus pecados são perdoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'E os escribas e os fariseus começaram a questionar, dizendo: Quem é este que fala blasfêmias? Quem pode perdoar pecados, senão só Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Porém Jesus, conhecendo os seus pensamentos, respondeu-lhes: O que pensais em vossos corações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'O que é mais fácil? Dizer: Teus pecados são perdoados? Ou dizer: Levanta-te, e anda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Para que saibais que o Filho do homem tem poder sobre a terra para perdoar pecados, (disse ao paralítico:) Eu te digo, levanta-te, toma o teu leito, e vai para a tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'E ele levantou-se imediatamente diante deles, tomou o leito em que estava deitado, e foi para a sua casa, glorificando a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'E todos ficaram admirados, e glorificaram a Deus; e ficaram cheios de temor, dizendo: Hoje vimos maravilhas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Depois destas coisas, ele saiu; e viu um cobrador de impostos, chamado Levi, sentado na coletoria de tributos, e disse-lhe: Segue-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Ele deixou tudo, levantou-se, e o seguiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'E Levi lhe fez um grande banquete em sua casa; e havia ali uma grande multidão de publicanos e de outros que estavam sentados com eles à mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'E seus escribas e fariseus murmuravam contra os seus discípulos, dizendo: Por que comeis e bebeis com cobradores de impostos e pecadores?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Jesus lhes respondeu: Os que estão sãos não precisam de médico, mas sim os que estão doentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Eu não vim para chamar os justos, mas sim, os pecadores, ao arrependimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Então eles lhe disseram: Por que os discípulos de João jejuam muitas vezes, e fazem orações, como também os dos fariseus, mas os teus comem e bebem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Mas ele lhes disse: Podeis vós fazer jejuar os convidados do casamento, enquanto o noivo está com eles?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Porém virão dias em que o esposo lhes será tirado; então naqueles dias jejuarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'E dizia-lhes também uma parábola: Ninguém põe remendo de pano novo em roupa velha; de outra maneira, o novo rompe, e o remendo do novo não será adequado ao velho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'E ninguém põe vinho novo em odres velhos; de outra maneira, o vinho novo romperá os odres, e se derramará, e os odres são destruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Mas o vinho novo deve ser posto em odres novos, e ambos se conservam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'E ninguém que beber do velho quer logo o novo; porque diz: O velho é melhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'E aconteceu que, no segundo sábadodepois do primeiro, Jesus passou pelas plantações, e seus discípulos iam arrancando espigas, e comiam, debulhando-as com as mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'E alguns dos fariseus lhes disseram: Por que fazeis o que não é lícito fazer nos sábados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'E Jesus lhes respondeu: Nunca lestes isto, o que Davi fez quando teve fome, ele e os que com ele estavam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Como entrou na casa de Deus, tomou, e comeu os pães da apresentação, e deu também aos que estavam com ele, pães que não é lícito comer, a não ser só os sacerdotes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'E dizia-lhes: O Filho do homem é Senhor até do sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'E aconteceu também em outro sábado que entrou na sinagoga, e estava ensinado; e ali estava um homem que tinha a mão direita definhada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'E os escribas e fariseus o observavam, se o curaria no sábado; para acharem de que o acusar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Mas ele bem sabia dos seus pensamentos; e disse ao homem que tinha a mão definhada: Levanta-te, e põe-te em pé no meio. E ele se levantou e se pôs de pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Então Jesus lhes disse: Uma coisa vos perguntarei: É lícito nos sábados fazer bem, ou fazer mal? Salvar uma pessoa, ou matá-la?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'E ele, olhando para todos em redor, disse ao homem: Estende a tua mão. E ele assim o fez; e a mão foi lhe restituída sã como a outra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Então encheram-se de ira; e conversaram uns com os outros sobre o que fariam a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'E aconteceu que naqueles dias ele foi ao monte para orar; e passou a noite orando a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'E quando já era dia, chamou a si os seus discípulos, e escolheu doze deles, a quem também chamou de apóstolos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simão, a quem também chamou de Pedro, e seu irmão André; Tiago, e João; Filipe, e Bartolomeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mateus, Tomé; Tiago filho de Alfeu, e Simão chamado “o Zelote”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judas de Tiago, e Judas Iscariotes, o mesmo que foi o traidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Ele desceu com eles, parou num lugar plano, e também com ele uma grande quantidade dos seus discípulos, e grande multidão do povo de toda a Judeia, de Jerusalém, da costa marítima de Tiro, e de Sidom,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'que tinham vindo para o ouvir, e para serem curados das suas enfermidades, como também os atormentados por espíritos imundos; e foram curados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'E toda a multidão procurava tocá-lo; porque dele saía poder, e curava a todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Ele levantou os olhos aos seus discípulos, e disse: Benditos sois vós, os pobres, porque o Reino de Deus é vosso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Benditos sois vós que agora tendes fome, porque sereis saciados. Benditos sois vós que agora chorais, porque rireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Benditos sereis quando as pessoas vos odiarem, quando vos separarem, vos insultarem, e rejeitarem o vosso nome como mau, por causa do Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Contentai-vos nesse dia, e saltai de alegria, porque eis que grande é a vossa recompensa nos céus; pois assim os pais deles faziam aos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Mas ai de vós, ricos, porque já tendes a vossa consolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Ai de vós que estais saciados, porque tereis fome. Ai de vós que agora rides, porque lamentareis, e chorareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Ai de vós quando todos falarem bem de vós; porque assim os pais deles faziam aos falsos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Mas a vós, que estais ouvindo, digo: amai os vossos inimigos; fazei bem aos que vos odeiam;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'bendizei aos que vos maldizem, e orai pelos que vos maltratam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Ao que te ferir numa face, oferece-lhe também a outra; e ao que te tirar a capa, não recuses a túnica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Dá a quem te pedir; e ao que te tomar o que é teu, não o peças de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'E como vós quereis que as pessoas vos façam, fazei-lhes vós também da mesma maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'E se amardes aos que vos amam, que mérito tereis? Pois também os pecadores amam os que os amam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'E se fizerdes bem aos que vos fazem bem, que mérito tereis? Pois também os pecadores fazem o mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'E se emprestardes àqueles de quem esperais receber de volta, que mérito tereis? Pois também os pecadores emprestam aos pecadores, para receberam de volta o tanto equivalente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Em vez disso, amai aos vossos inimigos, fazei o bem, e emprestai, sem nada esperar disso; e grande será a vossa recompensa, e sereis filhos do Altíssimo; porque é benigno até para com os ingratos e maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Portanto, sede misericordiosos, como também o vosso Pai é misericordioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; liberai, e vos liberarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dai, e será vos dado; medida boa, comprimida, sacudida e transbordante vos darão no vosso colo; pois com a mesma medida que medirdes vos medirão de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'E disse-lhes uma parábola: Acaso pode o cego guiar outro cego? Não cairão ambos no buraco?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'O discípulo não está acima do seu mestre; mas todo aquele que estiver completamente capacitado será como o seu mestre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'E por que tu prestas atenção no cisco que está no olho do teu irmão, e não enxergas a trave que está no teu próprio olho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Ou como podes dizer a teu irmão: “Irmão, deixa-me tirar o cisco que está no teu olho”, se tu mesmo não prestas atenção na trave que está no teu olho? Hipócrita, tira primeiro a trave de teu olho, e então verás bem para tirar o cisco que está no olho do teu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Pois não há boa árvore que dê mau fruto, nem árvore má que dê bom fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Porque cada árvore se conhece pelo seu próprio fruto; pois não se colhem figos dos espinheiros, nem se tiram uvas dos abrolhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'A boa pessoa tira o bem do bom tesouro do seu coração, e a pessoa má tira o mal do mau tesouro do seu coração; pois a sua boca fala daquilo que o coração tem em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'E por que me chamais: “Senhor!”, “Senhor!”, e não fazeis o que eu digo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Todo aquele que vem a mim, ouve as minhas palavras, e as pratica, eu vos mostrarei a quem é semelhante:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Semelhante é ao homem que construiu uma casa, cavou, abriu bem fundo, e pôs o fundamento sobre a rocha; e quando veio a enchente, a corrente bateu com ímpeto naquela casa, e não a pôde abalar, porque estava fundada sobre a rocha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Mas aquele que ouve e não pratica é semelhante ao homem que construiu uma casa sobre a terra, sem fundamento, na qual a corrente bateu com ímpeto, e logo caiu; e foi grande a queda daquela casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'E depois de acabar todos os seus discursos aos ouvidos do povo, ele entrou em Cafarnaum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'E o servo de um certo centurião, a quem muito estimava, que estava doente, e a ponto de morrer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'E quando o centurião ouviu falar sobre Jesus, enviou-lhe uns anciãos dos judeus, rogando-lhe que viesse curar o seu servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Eles vieram a Jesus, e rogaram-lhe com urgência, dizendo: Ele é digno de lhe concederes isto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'porque ele ama a nossa nação, e ele mesmo construiu a nossa sinagoga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jesus foi com eles; mas quando já não estava longe da casa, o centurião lhe enviou uns amigos, dizendo-lhe: “Senhor, não te incomodes, porque não sou digno que entres abaixo do meu telhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Por isso que nem mesmo me considerei digno de vir a ti; mas diz uma palavra, e o meu servo sarará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Porque também eu sou homem subordinado à autoridade, e tenho soldados sob o meu comando, e digo a este: \'Vai\', e ele vai; e a outro: \'Vem\', e ele vem; e a meu servo: \'Faz isto\', e ele faz”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Quando Jesus ouviu isso, admirou-se dele; então se virou, e disse à multidão que o seguia: Digo-vos que nem mesmo em Israel achei tanta fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'E quando os que foram enviados voltaram para casa, acharam são o servo doente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'E aconteceu no dia seguinte, que Jesus ia a uma cidade chamada Naim, e com ele iam muitos de seus discípulos, e uma grande multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'E quando chegou perto da porta da cidade, eis que levavam um defunto, filho único de sua mãe, que era viúva; e com ela ia grande multidão da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Quando o Senhor a viu, comoveu-se de intima compaixão por ela, e disse-lhe: Não chores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Então se aproximou, tocou o caixão (e os que a levavam, pararam), e disse: Jovem, a ti eu digo: levanta-te.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'E o defunto se sentou e começou a falar; e ele o entregou à sua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Todos se encheram de temor, e glorificavam a Deus, dizendo: “Um grande profeta se levantou entre nós, e Deus visitou o seu povo!”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'E essa sua fama correu por toda a Judeia, e por toda a região em redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'E os discípulos de João lhe anunciaram essas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Então João chamou dois de seus discípulos, e os enviou a Jesus, dizendo: “És tu aquele que havia de vir, ou esperamos outro?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'E quando aqueles homens vieram a ele, disseram: “João Batista nos enviou a ti, dizendo: \'És tu aquele que havia de vir, ou esperamos outro?\'”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'E naquela mesma hora ele curou a muitos de enfermidades, males, e espíritos maus, e a deu vista a muitos cegos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Jesus lhes respondeu: Ide, e anunciai a João as coisas que tendes visto e ouvido: que os cegos veem, os mancos andam, os leprosos são purificados, os surdos ouvem, os mortos ressuscitam, e aos pobres é anunciado o Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'E bendito é aquele que não se ofender em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'E quando os mensageiros de João se foram, Jesus começou a dizer às multidões acerca de João: Que saístes para ver no deserto? Alguma cana sacudida pelo vento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Mas que saístes para ver? Um homem vestido de roupas delicadas? Eis que os que vestem roupas delicadas e vivem no luxo estão nos palácios reais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Mas que saístes para ver? Um profeta? Sim, vos digo, e muito mais que profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Este é aquele de quem está escrito: Eis que envio o meu mensageiro adiante de tua face, o qual preparará o teu caminho diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Pois eu vos digo, que dentre os nascidos de mulheres, não há profeta maior que João, o Batista; mas o menor no Reino dos céus é maior que ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'E todo o povo e os cobradores de impostos ouviram, concordaram que Deus era justo, e foram batizados com o batismo de João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Mas os fariseus e os estudiosos da Lei rejeitaram o conselho de Deus contra si mesmos, e não foram batizados por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'E o Senhor disse: “A quem, pois, compararei as pessoas desta geração? E a quem são semelhantes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'São semelhantes às crianças sentadas na praça, que gritam umas às outras: \'Tocamo-vos flautas, mas não dançastes; cantamos-vos lamentações, mas não chorastes\'.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Porque veio João Batista, que não comia pão, nem bebia vinho, e dizeis: \'Ele tem demônio\';');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Veio o Filho do homem, que come e bebe, e dizeis: \'Eis um homem comilão e bebedor de vinho, amigo dos cobradores de impostos e dos pecadores\'.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Mas a sabedoria foi considerada justa por todos os seus filhos”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'E um dos fariseus lhe pediu que comesse com ele; então entrou na casa do fariseu, e sentou-se à mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'E eis que uma mulher da cidade, que era pecadora, quando soube que ele estava na casa do fariseu, trouxe um vaso de alabastro de óleo perfumado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'E estando atrás, aos seus pés, chorando, começou a molhar-lhe os pés com lágrimas; e os enxugava com os cabelos da sua cabeça; e beijava-lhe os pés, e os ungia com o óleo perfumado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'E quando o fariseu que o havia convidado viu isso, falou consigo mesmo: Se ele fosse profeta, saberia quem e qual é a mulher que o toca; porque ela é pecadora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'E Jesus lhe respondeu: “Simão, tenho uma coisa a te dizer”; e ele disse: “Dize-a, Mestre”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Jesus disse: “Certo credor tinha dois devedores. Um lhe devia quinhentas moedas de prata, e o outro cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Como não tinham com que pagar, perdoou-lhes a dívida de ambos. Diz, pois, qual deles o amará mais?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simão respondeu: Tenho para mim que aquele a quem mais perdoou. E ele lhe disse: Julgaste corretamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Ele se voltou à mulher, e disse a Simão: Vês tu esta mulher? Entrei na tua casa, e não me deste água para os pés; porém esta molhou os meus pés com lágrimas, e os enxugou com os seu cabelos da cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Tu não me beijaste; porém esta, desde que entrou, não parou de me beijar os pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Não ungiste a minha cabeça com óleo, porém esta ungiu os meus pés com óleo perfumado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Por isso te digo, os muitos pecados dela são perdoados, porque muito amou; mas ao que pouco se perdoa, pouco ama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'E disse a ela: Os teus pecados são perdoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'E os que estavam sentados começaram a dizer entre si: Quem é este, que até perdoa pecados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'E disse à mulher: A tua fé te salvou; vai em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'E aconteceu depois disso, que Jesus andava de cidade em cidade, e de aldeia em aldeia, pregando e anunciando o evangelho do reino de Deus; e com ele os doze,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'e algumas mulheres que haviam sido curadas de espíritos malignos e de enfermidades: Maria, chamada Madalena, da qual saíram sete demônios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'e Joana, a mulher de Cuza, mordomo de Herodes; e Susana, e muitas outras, que lhe serviam com seus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'E quando se ajuntou uma multidão, e vindo a ele de todas as cidades, disse por parábola:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Saiu um semeador a semear sua semente; e quando semeava, caiu uma parte junto ao caminho, e foi pisada, e as aves do céu a comeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'E outra parte caiu sobre a pedra; e nascida, secou-se, porque não tinha umidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'E outra parte caiu entre espinhos, e nascendo com ela, os espinhos a sufocaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'E outra parte caiu em boa terra, e nascida, produziu fruto a cem por um. Depois que disse coisas, clamava: Quem tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'E os seus discípulos lhe perguntaram: Que parábola é esta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Ele disse: A vós é dado conhecer os mistérios do reino de Deus; mas aos outros por parábolas, para que vendo, não vejam; e ouvindo, não entendam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Esta é, pois, a parábola: a semente é a palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Os que estão junto ao caminho são os que ouvem; depois vem o diabo, e tira-lhes do coração a palavra, para que não creiam nem se salvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'E os que estão sobre a pedra são os que, quando ouvem, recebem a palavra com alegria, mas esses não têm raiz, pois creem por algum tempo, mas no tempo da tentação se desviam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'E o que caiu entre espinhos são os que ouviram, e indo, sufocam-se com as preocupações, e riquezas, e prazeres da vida, e não produzem bom fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'E o que caiu em boa terra, estes são os que, ouvindo a palavra, conservam-na num coração honesto e bom, e dão fruto que permanece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'E ninguém, quando acende uma lâmpada, cobre-a com algum vaso, ou a põe debaixo da cama; em vez disso põe na luminária, para que os que entram vejam a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Porque não há coisa oculta que não venha a se manifestar; nem coisa escondida que não venha a ser conhecida, e chegada à luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Portanto, prestai atenção a como ouvis; pois àquele que tiver lhe será dado; e àquele que não tiver, até o que lhe parece ter, dele será tirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'E vieram a ele sua mãe e seus irmãos, mas não conseguiam chegar a ele por causa da multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'E foi-lhe anunciado, dizendo: “Tua mãe e teus irmãos estão fora, e querem te ver”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Porém, ele lhes respondeu: “Minha mãe e meus irmãos são aqueles que ouvem a palavra de Deus e a praticam”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'E aconteceu, num daqueles dias, que Jesus entrou em um barco com seus discípulos, e disse-lhes: “Passemos para o outro lado do lago”. E partiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'E enquanto navegavam, Jesus adormeceu; então desceu uma tempestade de vento no lago, e enchiam-se de água, e estavam em perigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Então se aproximaram dele e o despertaram, dizendo: “Mestre, Mestre, estamos perecendo!” E ele se levantou, repreendeu o vento e as ondas da água; e pararam, e fez-se bonança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'E disse-lhes: “Onde está a vossa fé?” Mas eles, temendo, admiravam-se, e diziam uns aos outros: “Quem é este, que manda até aos ventos, e à água, e lhe obedecem?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'E navegaram para a terra dos gadarenos, que é do lado oposto à Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'E quando ele desceu à terra, veio da cidade ao seu encontro um homem, que havia muito tempo que tinha demônios, e não andava vestido, nem habitava em casa nenhuma, mas sim, nos sepulcros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Ele viu Jesus, então exclamou, prostrou-se diante dele, e disse com grande voz: “O que eu tenho contigo, Jesus, Filho do Deus Altíssimo? Rogo-te que não me atormentes.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Porque ele mandava ao espírito imundo que saísse daquele homem; pois muitas vezes apoderava-se dele. E o mantinham preso com cadeias e grilhões; porém ele quebrava o que lhe prendia, e era conduzido pelo demônio aos desertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'E Jesus lhe perguntou: “Qual é teu nome?” E ele disse: “Legião” (porque muitos demônios tinham entrado nele).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'E rogavam-lhe que não os mandasse ir para o abismo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'E havia ali uma manada de muitos porcos, que pastavam no monte; e rogaram-lhe que lhes concedesse entrar neles; e ele lhes concedeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Os demônios saíram daquele homem e entraram nos porcos; e a manada se lançou de um precipício no lago e se afogou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Quando os que cuidavam dos porcos viram o que havia acontecido, fugiram; então foram anunciar na cidade e nos campos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'E saíram para ver o acontecido, e vieram até Jesus; e acharam ao homem de quem os demônios tinham saído, vestido e em pleno juízo, sentado aos pés de Jesus; e temeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'E os que tinham visto contaram-lhes também como aquele endemoninhado havia sido liberto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'E toda o povo da terra dos gadarenos ao redor lhe rogou que se retirasse deles; porque foram tomados por grande temor. Então ele entrou no barco e voltou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'E aquele homem, de quem os demônios tinham saído, rogou-lhe para que lhe permitisse estar com ele; mas Jesus o despediu, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '“Volta para tua casa, e conta como foram grandes as coisas que Deus te fez”. Ele se foi, e pregou por toda a cidade, como foram grandes as coisas que Jesus lhe tinha feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'E aconteceu que, quando Jesus voltou, a multidão o recebeu; porque todos o estavam esperando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'E eis que chegou um homem, cujo nome era Jairo, e era chefe da sinagoga. Então ele se prostrou aos pés de Jesus e rogou-lhe que entrasse em sua casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'porque tinha uma filha única, com doze anos de idade, que estava a ponto de morrer. E enquanto ele ia, as multidões o apertavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'E uma mulher que tinha um fluxo de sangue, havia doze anos, e já tinha gastado todos os seus pertences com médicos, e não pôde ser curada por nenhum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Ela se aproximou de Jesus por detrás, e tocou a borda de sua roupa; e logo o fluxo de seu sangue parou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'E Jesus disse: “Quem me tocou?” Enquanto todos negavam, disse Pedro e os que com ele estavam: Mestre, as multidões te apertam e empurram, e dizes: Quem me tocou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jesus disse: “Alguém me tocou, pois sei que poder saiu de mim”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Então a mulher, vendo que não podia se esconder, veio tremendo, prostrou-se diante dele, e declarou-lhe diante de todo o povo a causa por que o havia tocado, e como logo havia sarado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'E ele lhe disse: “Tem bom ânimo, filha; a tua fé te sarou; vai em paz”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Estando ele ainda falando, veio um da casa do chefe da sinagoga, que lhe disse: “Tua filha já está morta, não incomodes o Mestre.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Porém quando Jesus o ouviu, respondeu-lhe: “Não temas; crê somente, e ela será curada”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'E quando entrou na casa, a ninguém deixou entrar, a não ser a Pedro, Tiago, João, e ao pai e à mãe da menina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'E todos choravam e lamentavam por ela; mas ele disse: “Não choreis; ela não está morta, mas dorme”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'E riam dele, porque sabiam que estava morta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Porém ele, depois de expulsá-los todos, segurou a mão dela e clamou: “Levanta-te, menina”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Então seu espírito voltou, e ela logo se levantou; e Jesus mandou que dessem de comer a ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'E seus pais ficaram maravilhados, mas ele lhes mandou que a ninguém dissessem o que havia acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Jesus convocou seus doze discípulos, e lhes deu poder e autoridade sobre todos os demônios, e para curarem enfermidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'E os enviou para pregar o reino de Deus e para curar os enfermos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'E disse-lhes: “Não tomeis nada convosco para o caminho: nem vara, nem bolsa, nem pão, nem dinheiro, nem tenhais duas túnicas cada um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'E em qualquer casa que entrardes, ficai ali, e dali saí.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'E a todo os que não vos receberem, quando sairdes daquela cidade, sacudi até o pó dos vossos pés, em testemunho contra eles”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Então eles partiram, e percorreram todas as aldeias, anunciando o Evangelho, e curando em todos os lugares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'E o tetrarca Herodes ouvia falar todas as coisas que ele fazia; e estava perplexo, porque alguns diziam que João tinha ressuscitado dos mortos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'e outros, que Elias havia aparecido; e outros, que algum profeta dos antigos havia ressuscitado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'E Herodes disse: “A João mandei degolar; quem, pois, é este, de quem tais coisas ouço?” E procurava vê-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'E quando os apóstolos, voltaram, contaram a Jesus todas as coisas que tinham feito. Então ele os tomou consigo, e retirou-se à parte a um lugar deserto de uma cidade chamada Betsaida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'E quando as multidões souberam, seguiram-no. Ele as recebeu, e lhes falava do Reino de Deus, e curava aos que precisavam de cura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'E o dia já começava a declinar. Então os doze se aproximaram dele, e lhe disseram: “Despede a multidão, para irem aos lugares e aldeias ao redor, se agasalhem, e achem o que comer; porque aqui estamos em lugar deserto”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mas ele lhes disse: “Dai-lhes vós de comer”. E eles disseram: “Não temos mais que cinco pães e dois peixes; a não ser se formos nós mesmos comprar de comer para todo este povo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Porque havia ali quase cinco mil homens. Então disse aos seus discípulos: “Fazei-os se sentarem em grupos de cinquenta em cinquenta”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'E assim procederam, fazendo todos se sentarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Então ele tomou os cinco pães e os dois peixes e, olhando para o céu, abençoou-os e partiu-os, e os deu a seus discípulos, para os porem diante da multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'E todos comeram, e saciaram-se; e levantaram doze cestos de pedaços que sobraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'E aconteceu que, quando ele estava orando só, e seus discípulos estavam com ele, que ele lhes perguntou: “Quem as multidões dizem que eu sou?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'E eles responderam: “Uns, João Batista; outros, Elias; e outros, que algum dos profetas antigos ressuscitou”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'E disse-lhes: “E vós, quem dizeis que eu sou?” E Pedro respondeu: “O Cristo de Deus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Então ele os alertou, e mandou-lhes que não dissessem a ninguém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'dizendo: “É necessário que o Filho do homem sofra muitas coisas; que seja rejeitado pelos anciãos, pelos chefes dos sacerdotes, e pelos escribas; que seja morto, e que seja ressuscitado ao terceiro dia”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'E dizia a todos: “Se alguém quer vir após mim, negue-se a si mesmo, tome cada dia sua cruz, e siga- me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Pois quem quiser salvar sua vida a perderá; porém quem, por minha causa, perder a sua vida, esse a salvará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Porque, que aproveita para alguém ganhar o mundo todo, e perder ou prejudicar a si mesmo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Pois quem se envergonhar de mim e das minhas palavras, dele o Filho do homem se envergonhará, quando vier na sua glória, e na do Pai, e dos santos anjos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'E em verdade vos digo que, dentre os que aqui estão, há alguns que não experimentarão a morte, até que vejam o Reino de Deus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'E aconteceu que, quase oito dias depois dessas palavras, ele tomou consigo a Pedro, João, e a Jacó, e subiu ao monte para orar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'E ele, enquanto estava orando, a aparência do seu rosto se transfigurou, e sua roupa ficou branca e brilhante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'E eis que estavam falando com ele dois homens, que eram Moisés e Elias,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'os quais apareceram com glória, e falavam de sua partida, que estava para se cumprir em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Pedro e os que estavam com ele estavam cheios de sono; e quando despertaram, viram a glória dele, e aqueles dois homens que estavam com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'E aconteceu que, quando eles estavam saíndo da presença dele, Pedro disse a Jesus: “Mestre, é bom estarmos nós aqui. Façamos três tendas, uma para ti, uma para Moisés, e uma para Elias”, não sabendo o que dizia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'E enquanto ele dizia isso, veio uma nuvem que os cobriu com a sua sombra; e, quando entraram na nuvem, temeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'E veio uma voz da nuvem, que dizia: “Este é o meu Filho amado; a ele ouvi”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'E, depois de terminada aquela voz, Jesus se encontrava só; e eles se calaram, e por aqueles dias não contaram a ninguém nada do que tinham visto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'E aconteceu no dia seguinte que, descendo eles do monte, uma grande multidão lhe saiu ao encontro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'E eis que um homem da multidão clamou: “Mestre, rogo-te que vejas a meu filho, que é o único que tenho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'e eis que um espírito o toma, e de repente grita, e o convulsiona até espumar, e somente sai dele quando o maltrata severamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'E roguei aos teus discípulos que o exupulsassem, mas não conseguiram”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'E Jesus respondeu: “Ó geração incrédula e perversa! Até quando estarei ainda convosco, e vos suportarei? Traze aqui teu filho”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'E quando ainda vinha chegando, o demônio o derrubou, e o convulsionou. Porém Jesus repreendeu o espírito imundo, curou ao menino, e o devolveu ao seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'E todos ficaram perplexos com a grandeza de Deus. E enquanto todos se maravilhavam de tudo o que Jesus fazia, disse aos seus discípulos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '“Ponde vós em vossos ouvidos estas palavras: que o Filho do homem será entregue nas mãos dos homens”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mas eles não entendiam essa palavra, e era-lhes encoberta, para que não a compreendessem; e temiam perguntar-lhe sobre essa palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'E levantou-se entre eles uma discussão sobre qual deles seria o maior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Mas Jesus, conhecendo o pensamento de seus corações, pegou uma criança, e a pôs junto a si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'Então disse-lhes: “Quem receber esta criança em meu nome, a mim me recebe; e quem receber a mim, recebe o que me enviou; porque aquele que entre todos vós for o menor, esse será grande”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'João respondeu: “Mestre, vimos um que em teu nome expulsava os demônios, e nós o proibimos, porque não segue conosco”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'E Jesus lhe disse: “Não o proibais, porque quem não é contra nós, é por nós”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'E aconteceu que, quando completaram-se os dias em que ele viria a ser recebido no alto, ele se determinou a ir para Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'E mandou mensageiros adiante de si; e eles se foram, e entraram numa aldeia de samaritanos, para lhe fazerem os preparativos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Mas não o receberam, porque seu rosto demonstrava que ele ia para Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Quando seus discípulos, Tiago e João, viram isso, disseram: “Senhor, queres que digamos que desça fogo do céu e os consuma, como Elias também fez?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Porém ele se virou, repreendeu-os, e disse: Vós não sabeis de que espírito sois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Porque o Filho do homem não veio para destruir as almas dos seres humanos, mas sim para salvá-las.E foram para outra aldeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'E aconteceu que, enquanto eles iam pelo caminho, alguém lhe disse: “Senhor, eu te seguirei para onde quer que fores”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'E Jesus lhe disse: “As raposas têm tocas, e as aves do céu, ninhos; mas o Filho do homem não tem onde deitar a cabeça”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'E disse a outro: “Segue-me”. Porém ele disse: “Senhor, deixa-me que primeiro eu vá, e eu enterre meu pai”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Mas Jesus lhe disse: “Deixa os mortos enterrarem os seus próprios mortos; tu, porém, vai, e anuncia o reino de Deus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'E outro também disse: “Senhor, eu te seguirei; mas deixa-me primeiro despedir dos que estão em minha casa”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'E Jesus lhe disse: “Ninguém que colocar a sua mão no arado e olhar para trás é apto para o reino de Deus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'E depois disso, o Senhor ordenou ainda outros setenta, e os mandou de dois em dois adiante de sua face, para toda cidade e lugar aonde ele havia de vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'E lhes dizia: “A colheita verdadeiramente é grande, mas os trabalhadores são poucos; portanto rogai ao Senhor da colheita para que ele envie trabalhadores para a sua colheita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Ide; eis que eu vos mando como cordeiros no meio dos lobos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Não leveis bolsa, nem sacola, nem sandálias; e a ninguém saudeis pelo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'E em qualquer casa que entrardes, dizei primeiro: Paz seja nesta casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'E se ali houver algum filho da paz, a vossa paz repousará sobre ele; e se não, ela voltará para vós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'E ficai na mesma casa, comendo e bebendo do que eles vos derem; pois o trabalhador é digno do seu salário. Não vos mudeis de casa em casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'E em qualquer cidade que entrardes, e vos receberem, comei do que puserem diante de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'E curai os enfermos que nela houver, e dizei-lhes: Chegado é para vós o reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Mas em qualquer cidade em que entrardes e não vos receberem, saí pelas ruas, e dizei:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Até o pó da vossa cidade que ficou em nós, sacudimos sobre vós; porém disto sabeis, que o reino de Deus é chegado até vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'E eu vos digo, que mais tolerável será naquele dia para Sodoma, do que para aquela cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Ai de ti, Corazim! Ai de ti, Betsaida! Porque se em Tiro e em Sidom tivessem sido feitas as maravilhas que foram feitas entre vós, há muito tempo que teriam se arrependido em saco e em cinza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Portanto, para Tiro e Sidom será mais tolerável no juízo, do que para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'E tu, Cafarnaum, que pensas estar elevada ao céu, até o mundo dos mortos serás derrubada!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Quem vos ouve, ouve a mim; e quem vos rejeita, rejeita a mim; e quem me rejeita, rejeita aquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'E os setenta voltaram com alegria, dizendo: Senhor, até os demônios se sujeitam a nós por teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'E disse-lhes: Eu vi a Satanás, que caía do céu como um raio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Eis que vos dou poder para pisar sobre serpentes e escorpiões, e sobre toda a força do inimigo, e nada vos fará dano nenhum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Mas não vos alegreis de que os espíritos se sujeitem a vós; em vez disso, alegrai-vos por vossos nomes estarem escritos nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Naquela hora Jesus se alegrou em espírito, e disse: Graças te dou, o Pai, Senhor do céu e da terra; porque tu escondeste estas coisas aos sábios e instruídos, e as revelaste às crianças. Sim, Pai, porque assim lhe agradou diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Todas as coisas me foram entregues pelo meu Pai; e ninguém sabe quem é o Filho, a não ser o Pai; nem quem é o Pai, a não ser o Filho, e a quem o Filho o quiser revelar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'E virando-se para seus discípulos, disse -lhes à parte: Bem-aventurados os olhos que veem o que vós vedes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Porque vos digo, que muitos profetas e reis desejaram ver o que vós vedes, e não o viram; o ouvir o que vós ouvis, e não o ouviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'E eis que um certo estudioso da Lei se levantou, tentando-o, e dizendo: Mestre, o que devo fazer para ter para herdar a vida eterna?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'E ele lhe disse: O que está escrito na Lei? Como tu a lês?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'E respondendo ele, disse: Amarás ao Senhor teu Deus de todo teu coração, e de toda tua alma, e de todas tuas forças, e de todo teu entendimento; e amarás a teu próximo como a ti mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'E disse-lhe: Respondeste bem; faze isso, e viverás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Mas ele, querendo se justificar, disse a Jesus: E quem é o meu próximo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'E respondendo Jesus, disse: Um homem descia de Jerusalém a Jericó, e foi atacado por assaltantes, que também tiraram suas roupas, espancaram-no, e se foram, deixando-o meio morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'E por acaso descia um certo sacerdote pelo mesmo caminho, e vendo -o,passou longe dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'E semelhantemente também um levita, chegando junto a aquele lugar, veio, e vendo -o,passou longe dele');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Porém um certo samaritano, que ia pelo caminho, veio junto a ele, e vendo-o, teve compaixão dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'E chegando-se, amarrou-lhe um curativo nas feridas, pondo-lhe nelas azeite e vinho; e pondo-o sobre o animal que o transportava, levou-o para uma hospedaria, e cuidou dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'E partindo-se no outro dia, tirou dois dinheiros, e os deu para o hospedeiro; e disse-lhe: Cuide dele; e tudo o que gastares a mais, eu te pagarei quando voltar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Quem, pois, destes três te parece que foi o próximo daquele que foi atacado por assaltantes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Ele disse: Aquele que agiu tendo misericórdia com ele.Então Jesus lhe disse: Vai, e faze da mesma maneira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'E aconteceu que eles, enquanto eles caminhavam, ele entrou em uma aldeia; e uma certa mulher, de nome Marta, o recebeu em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'E esta tinha uma irmã, chamada Maria, a qual, sentando-se também aos pés de Jesus, ouvia sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Marta, porém, ficava muito ocupada com muitos serviços; e ela, vindo, disse: Senhor, não te importas que minha irmã me deixe sozinha para servir? Dize a ela, pois, que me ajude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'E respondendo Jesus, disse-lhe: Marta, Marta, tu és preocupada com muitas coisas, e perturbada por elas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Mas somente uma coisa é necessária. E Maria escolheu a parte boa, a qual não lhe será tirada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'E aconteceu que ele estava orando em um certo lugar. Quando terminou, lhe disse um de seus discípulos: Senhor, ensina-nos a orar, como João também ensinou a seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'E ele lhes disse: Quando orardes, dizei: Pai nosso, que estás nos céus, santificado seja o teu nome; venha o teu Reino; seja feita a tua vontade, assim na terra como no céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Dá-nos cada dia nosso pão diário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'E perdoa-nos nossos pecados, pois também perdoamos a todo aquele que nos deve. E não nos ponhas em tentação, mas livra-nos do mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Disse-lhes também: Qual de vós que, tendo um amigo, se for a ele à meia-noite, e lhe disser: Amigo, empresta-me três pães.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Porque um amigo meu veio de viagem até mim, e nada tenho para lhe apresentar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'E ele de dentro, respondendo, disser: Não me perturbe! A porta já está fechada, e meus filhos estão comigo na cama; não posso me levantar para te dar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Digo-vos, que ainda que ele não se levante para lhe dar por seu seu amigo, contudo, por sua teimosia ele se levantará, e lhe dará tudo quanto ele precisar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'E eu vos digo: pedi, e será vos dado; buscai, e achareis; batei, e vos será aberto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Porque todo o que pede, recebe; e quem busca, acha; e quem bate, lhe será aberto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'E que pai, dentre vós, a quem o filho pedir pão, lhe dará uma pedra? Ou, se também lhe pedir peixe, no lugar do peixe lhe dará uma serpente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Ou se também pedir um ovo, lhe dará um escorpião?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Pois se vós, sendo maus, sabeis dar bons presentes para vossos filhos, quanto mais dará vosso Pai celestial, o Espírito Santo, a aqueles que lhe pedirem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'E Jesus estava expulsando um demônio, e este era mudo. E aconteceu que, saindo o demônio, o mudo falou, e as multidões se maravilharam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Porém alguns deles diziam: Ele expulsa aos demônios por Belzebu, príncipe dos demônios!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'E outros, tentando -o,pediam-lhe um sinal do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Mas ele, conhecendo seus pensamentos, disse-lhes: Todo reino dividido contra si mesmo é transformado num vazio, e a casa contra casa cai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'E se também Satanás está dividido contra si mesmo, como durará o seu reino? Porque dizeis: Por Belzebu ele expulsa aos demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'E se eu expulso aos demônios por Belzebu, por quem os seus filhos expulsam? Portanto eles serão vossos juízes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mas se eu expulso aos demônios pelo dedo de Deus, portanto o Reino de Deus chegou a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Quando o valente, armado, guarda seu palácio, seus bens estão em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Mas vindo outro mais valente que ele, e vencendo-o, toma -lhe toda sua armadura, em que confiava, e reparte seus despojos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Quem não é comigo, é contra mim; e quem comigo não ajunta, espalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Quando o espírito imundo tem saído da pessoa, ele anda por lugares secos, buscando repouso; e não o achando, diz: Voltarei para minha casa, de onde saí.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'E vindo, acha-a varrida e adornada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Então vai, e toma consigo outros sete espíritos piores que ele, e entrando, habitam ali; e as últimas coisas de tal pessoa são piores que as primeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'E aconteceu que, dizendo ele estas coisas, uma mulher da multidão, levantando a voz, lhe disse: Bem-aventurado o ventre que te trouxe, e os peitos que mamaste!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Mas ele disse: Antes bem-aventurados os que ouvem a palavra de Deus, e a guardam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'E ajuntando as multidões, começou a dizer: Maligna é esta geração; busca sinal, mas sinal não lhe será dado, a não ser o sinal de Jonas o profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Porque como Jonas foi sinal para os ninivitas, assim também será o Filho do homem para esta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'A rainha do Sul se levantará em juízo com as pessoas desta geração, e as condenará; pois até dos fins da terra veio para ouvir a sabedoria de Salomão; e eis que mais que Salomão está aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Os homens de Nínive se levantarão em juízo com esta geração, e a condenarão; pois com a pregação de Jonas se converteram; e eis que mais que Jonas está aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'E ninguém, acendendo a lâmpada, a põe em lugar oculto, nem debaixo da caixa, mas na luminária, para que os que entrarem vejam a luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'A lâmpada do corpo é o olho. Sendo pois teu olho bom, também todo teu corpo será luminoso; porém se for mau, também todo teu corpo será tenebroso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Olha pois que a luz que em ti há não sejam trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Então se sendo teu corpo todo luminoso, não tendo parte alguma escura, ele todo será iluminado, como quando a lâmpada com seu brilho te ilumina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'E estando ele ainda falando, um fariseu lhe rogou que viesse para jantar com ele; e entrando, sentou-se à mesa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'E vendo -o o fariseu, maravilhou-se de que não tinha se lavado antes de jantar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'E o Senhor lhe disse: Agora vós, os fariseus, limpais o exterior do copo e do prato; porém vosso interior está cheio de roubo e maldade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Loucos, o que fez o exterior não fez também o interior?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Porém daí de esmola o que tendes; e eis que tudo vos será limpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Mais ai de vós, fariseus, que dizimais a hortelã, e a arruda, e toda hortaliça; e pelo juízo e amor de Deus passais longe. Estas coisas era necessário fazer, e não deixar as outras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Ai de vós, fariseus, que amais os primeiros assentos nas sinagogas, e as saudações nas praças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Ai de vós, escribas e fariseus, hipócritas, que sois como as sepulturas disfarçadas, e as pessoas que andam sobre elas não sabem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'E respondendo um dos estudiosos da Lei, disse-lhe: Mestre, quando dizes isto também afrontas a nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Porém ele disse: Ai de vós também, estudiosos da Lei, que carregais as pessoas com cargas pesadas para levar, e vós mesmos nem ainda com um de vossos dedos tais cargas tocais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Ai de vós, que construís os sepulcros dos profetas, e vossos pais os mataram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Bem testemunhais pois, que também consentis nas obras de vossos pais; porque eles os mataram, e vós edificais seus sepulcros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Portanto também diz a sabedoria de Deus: Profetas e apóstolos lhes mandarei; e deles a uns matarão, e a outros lançarão fora;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Para que desta geração seja requerido o sangue de todos os profetas, que foi derramado desde a fundação do mundo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Desde o sangue de Abel, até o sangue de Zacarias, que foi morto entre o altar e a casa de Deus; assim vos digo, será requerido desta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Ai de vós, estudiosos da Lei, que tomastes a chave do conhecimento; vós mesmos não entrastes, e impedistes aos que estavam entrando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'E dizendo-lhes estas coisas, os escribas e os fariseus começaram a apertá-lo fortemente, e tentar lhe fazer falar de muitas coisas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'armando-lhe ciladas, e procurando caçar alguma coisa de sua boca, para o poderem acusar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Juntando-se, entretanto, muitos milhares da multidão, tanto que se atropelavam uns aos outros, começou a dizer primeiramente a seus discípulos: Guardai-vos do fermento dos fariseus, que é hipocrisia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'E nada há encoberto que não haja de ser descoberto; nem oculto que não haja de ser sabido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Portanto tudo o que dissestes nas trevas, será ouvido na luz; e o que falastes ao ouvido nos quartos, será pregado sobre os telhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'E digo-vos, amigos meus, não temais aos que matam o corpo, e depois não têm mais o que possam fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Mas eu vos mostrarei a quem deveis temer; temei a aquele, que depois de matar, também tem poder para lançar no inferno; sim, a este temei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Não se vendem cinco passarinhos por duas pequenas moedas? E nem um deles está esquecido diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'E até os cabelos de vossa cabeça estão todos contados; não temais, pois; mais valeis vós que muitos passarinhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'E vos digo que todo aquele que me confessar diante dos seres humanos, também o Filho do homem o confessará diante dos anjos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Mas quem me negar diante dos seres humanos será negado diante dos anjos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'E a todo aquele que disser alguma palavra contra o Filho do homem, lhe será perdoado, mas ao que blasfemar contra o Espírito Santo, não lhe será perdoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'E quando vos trouxerem às sinagogas, aos magistrados e autoridades, não estejais ansiosos, como, ou que, em vossa defesa deveis dizer, ou que deveis falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Porque na mesma hora o Espírito Santo vos ensinará o que deveis falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'E um da multidão lhe disse: Mestre, dize a meu irmão que reparta a herança comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Mas ele lhe disse: Homem, quem me pôs por juiz, ou repartidor sobre vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'E disse-lhes: Olhai, e tomai cuidado com a ganância; porque a vida de alguém não consiste na abundância dos bens que possui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'E propôs-lhes uma parábola, dizendo: A terra de um homem rico tinha frutificado bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'E ele questionava a si mesmo, dizendo: Que farei? Porque não tenho onde juntar meus frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'E disse: Farei isto: derrubarei meus celeiros, e construirei maiores, e ali juntarei toda esta minha colheita, e estes meus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'E direi à minha alma: Alma, muitos bens tens guardados, para muitos anos; descansa, come, bebe, alegra-te!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Porém Deus lhe disse: Louco, esta noite te pedirão tua alma; e o que tens preparado, de quem será?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Assim é o que junta tesouros para si, mas não é rico em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'E disse a seus discípulos: Portanto vos digo, não estejais ansiosos por vossa vida, que comereis; nem pelo corpo, que vestireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Mais é a vida que o alimento, e mais o corpo que o vestido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Considerai os corvos, que nem semeiam, nem ceifam; nem tem armazém, nem celeiro; e Deus os alimenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'E quem de vós pode, com sua ansiedade, acrescentar um côvado à sua altura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Pois, se não podeis nem mesmo com algo pequeno, por que estais ansiosos com o resto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Considerai os lírios, como crescem; não trabalham, nem fiam; e digo-vos, que nem mesmo Salomão, em toda sua glória, chegou a se vestir como um deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'E se assim Deus veste a erva, que hoje está no campo, e amanhá é lançada no forno, quanto mais vestirá a vós, homens de pouca fé?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Vós, pois, não pergunteis que comereis, ou que bebereis; e não andeis preocupados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Porque todas estas coisas, os gentios do mundo as buscam; mas vosso Pai sabe que necessitais destas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Mas buscai o Reino de Deus, e todas estas coisas vos serão acrescentadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Não temas, ó pequeno rebanho; porque vosso Pai se agradou de dar a vós o Reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Vendei o que tendes, e daí esmola. Fazei para vós bolsas que não se envelheçam; tesouro nos céus que nunca se deprecia; onde ladrão não chega, nem a traça destrói.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Porque aonde estiver vosso tesouro, ali estará também vosso coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Estejam devidamente vestidos vossos quadris, e acesas as lâmpadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'E sede vós semelhantes às pessoas que esperam a seu senhor quando voltar do casamento; para que quando ele vier, e bater, logo possam lhe abrir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Bem-aventurados aqueles servos, os quais, quando o Senhor vier, os achar vigiando; em verdade vos digo que ele se vestirá, e os fará se sentarem à mesa,e chegando-se, os servirá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'E ainda que venha à segunda vigília; e que venha a terceira vigília, e assim os achar, bem-aventurados são tais servos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Isto, porém, sabei: que se o chefe da casa soubesse à que hora o ladrão viria, ele vigiaria, e não deixaria sua casa sofrer dano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Vós, pois, também estejais prontos; porque o Filho do homem virá à hora que não imaginais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'E Pedro lhe disse: Senhor, dizes tu esta parábola para nós, ou também para todos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'E o Senhor disse: Qual é, pois, o mordomo fiel e prudente, a quem seu senhor puser sobre seus servos, para que lhes dê alimento no tempo certo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Bem-aventurado aquele servo ao qual, quando seu senhor vier, o achar fazendo assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Em verdade vos digo, que o porá sobre todos os seus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mas se aquele servo disser em seu coração: Meu senhor está demorando para vir; e começar a espancar aos servos e servas, e a comer, e a beber, e a se embebedar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Virá o senhor daquele servo, no dia em que ele não espera, e na hora que ele não sabe; e será partido em dois, e porá sua porção com os incrédulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'E o servo que sabia a vontade de seu senhor, e não se preparou, nem fez conforme a sua vontade, será muito espancado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Mas o que não sabia, e fez coisas dignas de pancadas, será pouco espancado. E a qualquer que muito for dado, muito se lhe pedirá, e ao que muito se confiou, muito mais lhe será exigido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Eu vim para lançar fogo na terra; e o que mais posso querer, se já está aceso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Porém há um batismo que tenho que ser batizado; e como me angustio até que se venha a cumprir!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Vós pensais que vim para dar paz à terra? Não, eu vos digo; mas antes vim para trazer divisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Porque daqui em diante cinco estarão divididos em uma casa; três contra dois, e dois contra três.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'O pai estará dividido contra o filho, e o filho contra o pai; a mãe contra a filha, e a filha contra a mãe; a sogra contra sua nora, e a nora contra sua sogra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'E ele dizia também para as multidões: Quando vedes a nuvem que vem do ocidente, logo dizeis: Lá vem chuva; E assim acontece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'E quando venta do sul, dizeis: Haverá calor; E assim acontece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hipócritas! Sabeis entender a aparência da terra e do céu; e como não entendeis este tempo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'E por que também não julgais por vós mesmos o que é justo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Pois quando fores com teu adversário à autoridade, procura te livrares dele no caminho, para que ele não venha a te levar ao juiz, e o juiz te entregue ao oficial de justiça, e o oficial de justiça te lance na prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Eu te digo que não sairás dali enquanto não pagares até a última moeda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'E naquele mesmo tempo estavam ali presentes alguns, que lhe contavam dos galileus cujo sangue Pilatos tinha misturado com seus sacrifícios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'E respondendo Jesus, disse-lhes: Vós pensais que estes galileus foram mais pecadores, por terem sofrido estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Não, eu vos digo; antes, se vós não vos arrependerdes, todos de modo semelhante perecereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ou aqueles dezoito, sobre os quais a torre em Siloé caiu, matando-os; pensais que eram mais culpados dos que todos as pessoas que moravam em Jerusalém?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Não, eu vos digo; antes, se vós não vos arrependerdes, todos de modo semelhante perecereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'E dizia esta parábola: Um certo homem tinha uma figueira plantada em sua vinha, e veio até ela para buscar fruto, e não achou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'E disse ao que cuidava da vinha: Eis que há três anos, que venho para buscar fruto nesta figueira, e não o acho; corta-a; por que ainda ocupa inutilmente a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'E respondendo ele, disse-lhe: Senhor, deixa-a ainda este ano, até que eu a escave ao redor, e a adube;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'E se der fruto, deixa-a ficar; se não, tu a cortarás depois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'E ensinava em uma das sinagogas num sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'E eis que estava ali uma mulher, que havia dezoito anos que tinha um espírito de enfermidade; e andava encurvada, e de maneira nenhuma ela podia se endireitar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'E Jesus vendo-a, chamou-a para si, e disse-lhe: Mulher, livre estás de tua enfermidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'E pôs as mãos sobre ela, e logo ela se endireitou, e glorificava a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'E o chefe da sinagoga, irritado por Jesus ter curado no sábado, respondendo, disse à multidão: Há seis dias em que se deve trabalhar; nestes dias, pois, vinde para ser curados, e não no dia de sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Porém o Senhor lhe respondeu, e disse: Hipócrita, no sábado cada um de vós não desata seu boi ou jumento da manjedoura, e o leva para dar de beber?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'E não convinha soltar desta ligadura no dia de sábado a esta mulher,que é filha de Abraão, a qual, eis que Satanás já a havia ligado há dezoito anos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'E ele, dizendo estas coisas, todos seus adversários ficaram envergonhados; e todo o povo se alegrava de todas as coisas gloriosas que eram feitas por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'E dizia: A que o Reino de Deus é semelhante? E a que eu o compararei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Semelhante é ao grão da mostarda, que um homem, tomando-o, lançou-o em sua horta; e cresceu, e fez-se uma grande árvore, e as aves dos céus fizeram ninhos em seus ramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'E disse outra vez: A que compararei o Reino de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Semelhante é ao fermento, que a mulher, tomando-o, o escondeu em três medidas de farinha, até tudo ficar levedado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'E andava de cidade em cidade, e de aldeia em aldeia ensinando, e caminhando para Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'E disse-lhe um: Senhor, são também poucos os que se salvam? E ele lhes disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Trabalhai para entrar pela porta estreita; porque eu vos digo, que muitos procuraram entrar, e não puderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Porque quando o chefe da casa se levantar, e fechar a porta, e se estiverdes de fora, e começardes a bater à porta, dizendo: Senhor, senhor, abre-nos! E respondendo ele, vos disser: Não vos conheço, nem sei de onde vós sois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Então começareis a dizer: Em tua presença temos comido e bebido, e tens ensinado em nossas ruas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'E ele dirá: Digo-vos que não vos conheço, nem sei de onde vós sois; afastai-vos de mim, vós todos praticantes de injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Ali haverá choro e ranger de dentes, quando virdes a Abraão, a Isaque, a Jacó, e a todos os profetas no Reino de Deus; mas vós sendo lançados fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'E virão pessoas do oriente, e do ocidente, e do norte, e do sul, e se sentarão à mesa no Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'E eis que há alguns dos últimos que serão primeiros, e há alguns dos primeiros que serão últimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Naquele mesmo dia, chegaram uns fariseus, dizendo-lhe: Sai, e vai-te daqui, porque Herodes quer te matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'E disse-lhes: Ide, e dizei a aquela raposa: eis que expulso demônios, e faço curas hoje e amanhã, e ao terceiro dia eu terei completado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Porém é necessário que hoje, e amanhã, e no dia seguinte eu caminhe; porque um profeta não pode morrer fora de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalém, Jerusalém, que matas aos profetas, e apedrejas aos que te são enviados: quantas vezes eu quis juntar teus filhos, como a galinha junta seus pintos debaixo de suas asas, e não quisestes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Eis que vossa casa é deixada deserta para vós. E em verdade vos digo, que não me vereis até que venha o tempo em que digais: Bendito aquele que vem no nome do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'E aconteceu que, entrando ele num sábado para comer pão na casa de um dos chefes dos fariseus, eles estavam o observando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'E eis que um certo homem com o corpo inchado estava ali diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'E respondendo Jesus, falou aos estudiosos da Lei, e aos fariseus, dizendo: É lícito curar no sábado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Porém eles ficaram calados; e ele, tomando -o,o curou, e o despediu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'E ele, respondendo-lhes, disse: De qual que vós cairá o jumento, ou o boi em algum poço que, mesmo no sábado, não o tire logo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'E nada podiam lhe responder a estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'E vendo como os convidados escolhiam os primeiros assentos, disse-lhes uma parábola:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Quando fores convidados para o casamento de alguém, não te sentes no primeiro assento, para que não aconteça de se outro convidado mais digno que tu estiver,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'E venha o que convidou a ti e a ele, e te diga: Dá lugar a este; E então, com vergonha, tenhas que tomar o último lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Mas quando fores convidado, vai, e senta-te no último lugar; para que quando vier o que te convidou, te diga: Amigo, sobe para este assento melhor. Então terás honra diante dos que estiverem sentados contigo à mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Porque qualquer que exaltar a si mesmo, e aquele que humilhar a si mesmo, será exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'E dizia também ao que tinha lhe convidado: Quando fizeres um jantar, ou uma ceia, não chames a teus amigos, nem a teus irmãos, nem a teus parentes, nem a teus vizinhos ricos, para que eles também em algum tempo não te convidem de volta, e tu sejas recompensado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Mas quando fizeres convite, chama aos pobres, aleijados, mancos e cegos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'E serás bem-aventurado, porque não eles não têm como te recompensar; pois tu serás recompensado na ressurreição dos justos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'E um dos que juntamente estavam sentados à mesa,ouvindo isto, disse-lhe: Bem-aventurado aquele que comer pão no Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Porém ele lhe disse: Um certo homem fez um grande jantar, e convidou a muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'E na hora do jantar, mandou seu servo para dizer aos convidados: Vinde, que tudo já está preparado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'E cada um deles todos começou a dar desculpas. O primeiro lhe disse: Comprei um campo, e tenho que ir vê-lo; peço-te desculpas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'E outro disse: Comprei cinco pares de bois, e vou testá-los; peço-te desculpas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'E outro disse: Casei-me com uma mulher, e portanto não posso vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'E aquele servo, ao voltar, anunciou estas coisas a seu senhor. Então o chefe da casa, irritado, disse a seu servo: Sai depressa pelas ruas e praças da cidade, e traze aqui aos pobres, e aleijados, e mancos e cegos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'E o servo disse: Senhor, está feito como mandaste, e ainda há lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'E o senhor disse ao servo: Sai pelos caminhos, e trilhas, e força-os a entrar, para que minha casa se encha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Porque eu vos digo, que nenhum daqueles homens que foram convidados experimentará da minha ceia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'E muitas multidões iam com ele; e virando-se, disse-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Se alguém vier a mim, e não odiar a seu pai, e mãe, e mulher, e filhos, e irmãos, e irmãs, e ainda também sua própria vida, não pode ser meu discípulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'E qualquer que não levar sua cruz, e vier após mim, não pode ser meu discípulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Porque qual de vós, querendo edificar uma torre, não se senta primeiro para fazer as contas dos gastos, para ver se tem o suficiente para a completar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Para que não aconteça que, depois de ter posto seu fundamento, e não podendo a completar, comecem a escarnecer dele todos os que o virem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Dizendo: Este homem começou a construir, e não pôde terminar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ou qual rei, indo a guerra para lutar contra outro rei, não se senta primeiro para consultar, se pode ir ao encontro com dez mil soldados,vindo contra ele vinte mil?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Se não puder,estando o outro ainda longe, manda -lhe representantes diplomáticos, e roga pela paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Assim, portanto, qualquer de vós que não renuncia a tudo, não pode ser meu discípulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Bom é o sal; porém se o sal perder o sabor, com o que ele será temperado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Nem para a terra, nem para adubo serve; lançam-no fora. Quem tem ouvidos para ouvir, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'E chegavam-se a ele todos os cobradores de impostos e pecadores para o ouvirem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'E os fariseus e escribas murmuravam, dizendo: Este recebe aos pecadores, e come com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'E ele lhes propôs esta parábola, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Quem de vós, tendo cem ovelhas, e perdendo uma delas, não deixa no deserto as noventa e nove, e vai em busca da perdida, até que a encontre?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'E encontrando-a, não a ponha sobre seus ombros, com alegria?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'E vindo para casa, não convoque aos amigos, e vizinhos, dizendo-lhes: Alegrai-vos comigo, porque já achei minha ovelha perdida?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Digo-vos, que assim haverá mais alegria no céu por um pecador que se arrepende, do que por noventa e nove justos que não precisam de arrependimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ou que mulher, tendo dez moedas de prata, se perder a uma moeda, não acende a lâmpada, e varre a casa, e busca cuidadosamente até a achar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'E achando -a, não chame as amigas e as vizinhas, dizendo: Alegrai-vos comigo, porque já achei a moeda perdida!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Assim vos digo, que há alegria diante dos anjos de Deus por um pecador que se arrepende.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'E disse: Um certo homem tinha dois filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'E disse o mais jovem deles ao pai: Pai, dá-me a parte dos bens que me pertencem. E ele lhe repartiu os bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'E depois de não muitos dias, o filho mais jovem, juntando tudo, partiu-se para uma terra distante, e ali desperdiçou seus bens, vivendo de forma irresponsável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'E ele, tendo já gastado tudo, houve uma grande fome naquela terra, e ele começou a sofrer necessidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'E foi, se chegou a um dos cidadãos daquela terra; e este o mandou a seus campos para alimentar porcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'E ele ficava com vontade de encher seu estômago com os grãos que os porcos comiam, mas ninguém as dava para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'E ele, pensando consigo mesmo, disse: Quantos empregados de meu pai tem pão em abundância, e eu aqui morro de fome!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Eu levantarei, e irei a meu pai, e lhe direi: Pai, pequei contra o céu, e diante de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'E já não sou digno de ser chamado teu filho; faze-me como a um de teus empregados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'E levantando-se, foi a seu pai. E quando ainda estava longe, o seu pai o viu, e teve compaixão dele; e correndo, caiu ao seu pescoço, e o beijou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'E o filho lhe disse: Pai, pequei contra o céu, e diante de ti; e já não sou digno de ser chamado teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Mas o pai disse a seus servos: Trazei a melhor roupa, e o vesti; e ponde um anel em sua mão, e sandálias nos seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'E trazei o bezerro engordado, e o matai; e comamos, e nos alegremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Porque este meu filho estava morto, e reviveu; tinha se perdido, e foi achado. E começaram a se alegrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'E seu filho mais velho estava no campo; e quando veio, chegou perto da casa, ouviu a música, e as danças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'E chamando para si um dos servos, perguntou-lhe: O que era aquilo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'E ele lhe disse: Teu irmão chegou; e teu pai matou o bezerro engordado, porque ele voltou são.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Porém ele se irritou, e não queria entrar. Então o seu pai, saindo, rogava-lhe que entrasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Mas o filho respondendo, disse ao pai: Eis que eu te sirvo há tantos anos, e nunca desobedeci tua ordem, e nunca me deste um cabrito, para que eu me alegrasse com meus amigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Porém, vindo este teu filho, que gastou teus bens com prostitutas, tu lhe mataste o bezerro engordado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'E ele lhe disse: Filho, tu sempre estás comigo, e todas as minhas coisas são tuas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Mas era necessário se alegrar e animar; porque este teu irmão estava morto, e reviveu; e tinha se perdido, e foi encontrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'E dizia também a seus discípulos: Havia um certo homem rico, o qual tinha um mordomo; e este lhe foi acusado de fazer perder seus bens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'E ele, chamando-o, disse-lhe: Como ouço isto sobre ti? Presta contas de teu trabalho, porque não poderás mais ser meu mordomo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'E disse o mordomo para si mesmo: O que farei, agora que meu senhor está me tirando o trabalho de mordomo? Cavar eu não posso; mendigar eu tenho vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Eu sei o que farei, para que, quando eu for expulso do meu trabalho de mordomo, me recebam em suas casas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'E chamando a si a cada um dos devedores de seu senhor, disse ao primeiro: Quanto deves a meu senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'E ele disse: Cem medidas de azeite. E disse-lhe: Pega a tua conta, senta, e escreve logo cinquenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Depois disse a outro: E tu, quanto deves? E ele disse: Cem volumes de trigo. E disse-lhe: Toma tua conta, e escreve oitenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'E aquele senhor elogiou o injusto mordomo, por ter feito prudentemente; porque os filhos deste mundo são mais prudentes do que os filhos da luz com esta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'E eu vos digo: fazei amigos para vós com as riquezas da injustiça, para que quando vos faltar, vos recebam nos tabernáculos eternos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Quem é fiel no mínimo, também é fiel no muito; e quem é injusto no mínimo, também é injusto no muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Pois se nas riquezas da injustiça não fostes fiéis, quem vos confiará as verdadeiras riquezas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'E se nas coisas dos outros não fostes fiéis, quem vos dará o que é vosso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nenhum servo pode servir a dois senhores; porque ou irá odiar a um, e a amar ao outro; ou irá se achegar a um, e desprezar ao outro. Não podeis servir a Deus e às riquezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'E os fariseus também ouviram todas estas coisas, eles que eram avarentos. E zombaram dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'E disse-lhes: Vós sois os que justificais a vós mesmos diante dos seres humanos; mas Deus conhece vossos corações. Porque o que é excelente para os seres humanos é odiável diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'A Lei e os profetas foram até João; desde então, o Reino de Deus é anunciado, todo homem tenta entrar nele pela força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'E é mais fácil passar o céu e a terra do que cair um traço de alguma letra da Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Qualquer que deixa sua mulher, e casa com outra, adultera; e qualquer que se casa com a deixada pelo marido, também adultera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Havia porém um certo homem rico, e vestia-se de púrpura, e de linho finíssimo, e festejava todo dia com luxo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Havia também um certo mendigo, de nome Lázaro, o qual ficava deitado à sua porta cheio de feridas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'E desejava se satisfazer com as migalhas que caíam da mesa do rico; porém vinham também os cães, e lambiam suas feridas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'E aconteceu que o mendigo morreu, e foi levado pelos anjos para o colo de Abraão. E o rico também morreu, e foi sepultado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'E estando no mundo dos mortos em tormentos, ele levantou seus olhos, e viu a Abraão de longe, e a Lázaro em seu colo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'E ele, chamando, disse: Pai Abraão, tem misericórdia de mim, e manda a Lázaro que molhe a ponta de seu dedo na água, e refresque a minha língua; porque estou sofrendo neste fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Porém Abraão disse: Filho, lembra-te que em tua vida recebeste teus bens, e Lázaro do mesmo jeito recebeu males. E agora este é consolado, e tu és atormentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'E, além de tudo isto, um grande abismo está posto entre nós e vós, para os que quisessem passar daqui para vós não possam; nem também os daí passarem para cá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'E disse ele: Rogo-te, pois, ó pai, que o mandes à casa de meu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Porque tenho cinco irmãos, para que lhes dê testemunho; para que também não venham para este lugar de tormento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Disse-lhe Abraão: Eles têm a Moisés e aos profetas, ouçam-lhes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'E ele disse: Não, pai Abraão; mas se alguém dos mortos fosse até eles, eles se arrependeriam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Porém Abraão lhe disse: Se não ouvem a Moisés e aos profetas, também não se deixariam convencer, ainda que alguém ressuscite dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'E disse aos discípulos: É impossível que não venham ofensas, mas ai daquele por quem estas ofensas vierem!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Melhor lhe seria que lhe atasse ao pescoço uma grande pedra de moinho, e fosse lançado no mar, do que ofender a um destes pequenos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Olhai por vós. E se teu irmão pecar contra ti, repreende-o; e se ele se arrepender, perdoa-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'E se pecar contra ti sete vezes ao dia, e se sete vezes ao dia voltar a ti, dizendo: Estou arrependido. Perdoa-lhe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'E os apóstolos disseram ao Senhor: Acrescenta-nos fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'E o Senhor disse: Se tivésseis fé como um grão de mostarda, diríeis a esta árvore de amoras: Arranca-te daqui pelas tuas raízes, e planta-te no mar, ela vos obedeceria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'E qual de vós terá um servo, lavrando ou apascentando gado que, voltando do campo, logo lhe diga: Chega, e senta à mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'E não lhe diga antes: Prepara-me o jantar, e apronta-te, e serve-me, até que eu tenha comido e bebido; e depois, come e bebe tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Por acaso o senhor agradece a tal servo, porque fez o que lhe foi mandado? Acho que não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Assim também vós, quando fizerdes tudo o que vos for mandado, dizei: Somos servos inúteis, porque fizemos somente o que devíamos fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'E aconteceu que, indo ele para Jerusalém, passou por meio da Samaria e da Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'E entrando em uma certa aldeia, saíram-lhe ao encontro dez homens leprosos, os quais pararam de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'E levantaram a voz, dizendo: Jesus, Mestre, tem misericórdia de nós!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'E ele, vendo-os, disse-lhes: Ide, e mostrai-vos aos sacerdotes.E aconteceu que, enquanto eles iam, ficaram limpos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'E vendo um deles que estava são, voltou, glorificando a Deus a alta voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'E caiu com o rosto a seus pés, agradecendo-lhe; e este era samaritano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'E respondendo Jesus, disse: Não foram os dez limpos? E onde estão os nove?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Não houve quem voltasse para dar glória a Deus, a não ser este estrangeiro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'E disse-lhe: Levanta-te, e vai; tua fé te salvou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'E perguntado pelos fariseus sobre quando o Reino de Deus viria, respondeu-lhes, e disse: O Reino de Deus não vem com aparência visível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Nem dirão: Eis aqui, ou Eis ali, porque eis que o Reino de Deus está entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'E disse aos discípulos: Dias virão, quando desejareis ver um dos dias do Filho do homem, e não o vereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'E vos dirão: Eis que ele está aqui, ou Eis que ele está ali, não vades, nem sigais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Porque como o relâmpago, que relampeja desde o começo do céu, e brilha até ao fim do céu, assim será também o Filho do homem em seu dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Mas é necessário primeiro sofrer muito, e ser rejeitado por esta geração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'E como aconteceu nos dias de Noé, assim será também nos dias do Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Comiam, bebiam, se casavam, e se davam em casamento, até o dia em que Noé entrou na arca; e veio o dilúvio, e destruiu a todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Como também da mesma maneira aconteceu nos dias de Ló, comiam, bebiam, compravam, vendiam, plantavam, e construíam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Mas o dia em que Ló saiu de Sodoma, choveu fogo e enxofre do céu, e destruiu a todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Assim será também no dia em que o Filho do homem se manifestar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Naquele dia, o que estiver no telhado, e suas ferramentas em casa, não desça para pegá-las; e o que estiver no campo, não volte para trás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Lembrai-vos da mulher de Ló.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Qualquer que procurar salvar sua vida a perderá; e qualquer que a perder, irá salvá-la.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Digo-vos que naquela noite, dois estarão em uma cama; um será tomado, e o outro será deixado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Duas estarão juntas moendo; uma será tomada, e a outra será deixada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Dois estarão no campo; um será tomado, e o outro será deixado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'E respondendo, disseram-lhe: Onde, Senhor?E ele lhes disse: Onde estiver o corpo, ali os abutres se juntarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'E Jesus lhes disse também uma parábola sobre o dever de sempre orar, e nunca se cansar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Dizendo: Havia um certo juiz em uma cidade, que não temia a Deus, nem respeitava pessoa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Havia também naquela mesma cidade uma certa viúva, e vinha até ele, dizendo: Faze-me justiça com meu adversário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'E por um certo tempo ele não quis; mas depois disto, disse para si: Ainda que eu não tema a Deus, nem respeite pessoa alguma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Porém, porque esta viúva me incomoda, eu lhe farei justiça, para que ela pare de vir me chatear.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'E disse o Senhor: Ouvi o que diz o juiz injusto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'E Deus não fará justiça para seus escolhidos, que clamam a ele de dia e de noite? Demorará com eles?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Digo-vos que depressa lhes fará justiça. Porém, quando o Filho do homem vier, por acaso ele achará fé na terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'E disse também a uns, que tinham confiança de si mesmos que eram justos, e desprezavam aos outros, esta parábola:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Dois homens subiram ao Templo para orar, um fariseu, e o outro cobrador de impostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'O fariseu, estando de pé, orava consigo desta maneira: Ó Deus, eu te agradeço, porque não sou como os outros homens, ladrões, injustos e adúlteros; nem sou como este cobrador de impostos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Jejuo duas vezes por semana, e dou dízimo de tudo quanto possuo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'E o cobrador de impostos, estando em pé de longe, nem mesmo queria levantar os olhos ao céu, mas batia em seu peito, dizendo: Ó Deus, tem misericórdia de mim, que sou pecador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Digo-vos que este desceu mais justificado à sua casa do que aquele outro; porque qualquer que a si mesmo se exalta, será humilhado; e qualquer que a si mesmo se humilha, será exaltado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'E traziam-lhe também crianças pequenas, para que as tocasse; e os discípulos, vendo, os repreendiam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Mas Jesus, chamando-lhes para si, disse: Deixai as crianças virem a mim, e não as impeçais; porque das tais é o Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Em verdade vos digo, que qualquer que não receber o Reino de Deus como criança, não entrará nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'E um certo líder lhe perguntou, dizendo: Bom mestre, o que tenho que fazer para herdar a vida eterna?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'E Jesus lhe disse: Por que me chamas de bom? Ninguém é bom, a não ser um: Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu sabes os mandamentos: não adulterarás, não matarás, não furtarás, não darás falso testemunho, honra a teu pai e a tua mãe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'E ele disse: Todas estas coisas tenho guardado desde minha juventude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Porém Jesus, ouvindo isto, disse-lhe: Ainda uma coisa te falta: vende tudo quanto tens, e reparte-o entre os pobres, e terás um tesouro no céu; e vem, segue-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Mas ele, ouvindo isto, ficou muito triste, porque era muito rico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'E vendo Jesus que ele tinha ficado muito triste, disse: Como é difícil os que têm muitos bens entrarem no Reino de Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Porque é mais fácil um camelo entrar pelo olho de uma agulha do que um rico entrar no Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'E os que ouviram isto,disseram: Quem então pode se salvar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'E ele disse: As coisas que são impossíveis para os seres humanos são possíveis para Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'E Pedro disse: Eis que deixamos tudo, e temos te seguido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'E ele lhes disse: Em verdade vos digo, que há ninguém que, tenha deixado casa, ou pais, ou irmãos, ou mulher, ou filhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Que não venha a receber de volta muito mais nestes tempos, e nos tempos vindouros receba a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'E tomando consigo aos doze, disse-lhes: Eis que estamos subindo a Jerusalém, e se cumprirá no Filho do homem tudo o que está escrito pelos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Porque ele será entregue aos gentios, e escarnecido, injuriado e cuspido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'E depois de açoitá-lo, o matarão; e ao terceiro dia ressuscitará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'E eles nada entendiam destas coisas; e esta palavra lhes era oculta; e não entendiam o que estava sendo lhes dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'E aconteceu que ele, chegando perto de Jericó, estava um cego sentado junto ao caminho, mendigando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'E este, ouvindo a multidão passar, perguntou: O que era aquilo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'E disseram-lhe que Jesus Nazareno estava passando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Então clamou, dizendo: Jesus, Filho de Davi, tem misericórdia de mim!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'E os que estavam mais a frente o repreendiam, para que calasse; porém ele clamava ainda mais: Filho de Davi, tem misericórdia de mim!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Então Jesus, parando, mandou que o trouxessem para si; e chegando ele, perguntou-lhe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Dizendo: Que queres que eu te faça?E ele disse: Senhor, que eu veja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'E Jesus lhe disse: Vê, tua fé te salvou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'E logo ele viu, e o seguia, glorificando a Deus. E o todo o povo, vendo isto,dava louvores a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'E Jesus entrou e foi passando por Jericó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'E eis que havia ali um homem, chamado pelo nome de Zaqueu, e este era chefe dos cobradores de impostos, e era rico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'E procurava ver quem era Jesus, e não podia, por causa da multidão, pois era pequeno de altura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'E correndo com antecedência, subiu em uma árvore de frutos que parecem figos, para o ver; porque ele passaria por ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'E quando Jesus chegou a aquele lugar, olhando para cima, o viu, e disse-lhe: Zaqueu, apressa-te, e desce; porque hoje é necessário que eu fique em tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'E apressando-se, desceu, e o recebeu com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'E todos, vendo isto,murmuravam, dizendo: Ele entrou para se hospedar com um homem pecador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'E Zaqueu, levantando-se, disse ao Senhor: Senhor, eis que dou a metade de meus bens aos pobres; e se eu consegui algo enganando a alguém, eu o devolvo quatro vezes mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'E Jesus lhe disse: Hoje houve salvação nesta casa, porque ele também é filho de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Porque o Filho do homem veio para buscar, e para salvar o que tinha se perdido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'E ouvindo eles estas coisas, Jesus prosseguiu, e disse uma parábola, porque estava perto de Jerusalém, e pensavam que logo o Reino seria manifesto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Disse, pois: Um certo homem nobre partiu para uma terra distante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'E chamando dez servos seus, deu-lhes dez minas, e disse-lhes: Investi até que eu venha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'E seus cidadãos o odiavam; e mandaram representantes depois dele, dizendo: Não queremos que este reine sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'E aconteceu que, quando ele voltou, tendo tomado o reino, disse que lhe chamassem a aqueles servos, a quem tinha dado o dinheiro, para saber o que cada um tinha ganho fazendo investimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'E veio o primeiro, dizendo: Senhor, tua mina rendeu outras dez minas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'E ele lhe disse: Ótimo, bom servo! Por teres sido fiel no pouco, terás autoridade sobre dez cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'E veio o segundo, dizendo: Senhor, tua mina rendeu cinco minas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'E disse também a este: E tu governarás cinco cidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'E veio outro, dizendo: Eis aqui tua mina, que guardei em um lenço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Porque tive medo de ti, que és um homem rigoroso, que tomas o que não puseste, e colhes o que não semeaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Porém ele lhe disse: Servo mau, por tua boca eu te julgarei; tu sabias que eu era um homem rigoroso, que tomo o que não pus, e que colho o que não semeei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Por que, então, não puseste meu dinheiro no banco; e quando eu viesse, o receberia de volta com juros?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'E disse aos que estavam com ele: Tirai-lhe a mina, e dai-a ao que tem as dez minas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'E eles lhe disseram: Senhor, ele já tem dez minas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'O senhor respondeu: Porque eu vos digo, que todo aquele que tiver, lhe será dado; mas ao que não tiver, até o que tem, lhe será tirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Porém a aqueles meus inimigos, que não quiseram que eu reinasse sobre eles, trazei - os aqui, e matai -os diante de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'E dito isto, ele foi caminhando adiante, subindo para Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'E aconteceu que, chegando perto de Betfagé, e de Betânia, ao monte chamado das Oliveiras, mandou a dois de seus discípulos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Dizendo: Ide à aldeia que está em frente; onde, ao entrardes, achareis um potro atado, em que ninguém jamais se sentou; soltai-o, e trazei -o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'E se alguém vos perguntar: Por que o soltais? Direis assim a ele: Porque o Senhor precisa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'E indo os que tinham sido mandados, acharam como lhes disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'E soltando o potro, seus donos lhe disseram: Por que soltais o potro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'E eles disseram: O Senhor precisa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'E o trouxeram a Jesus; e lançando suas roupas sobre o potro, puseram Jesus montado nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'E indo ele andando, estendiam suas roupas pelo caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'E quando já chegava perto da descida do monte das Oliveiras, toda a multidão de discípulos, com alegria começou a louvar a Deus em alta voz, por todas as maravilhas que tinham visto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Dizendo: Bendito o Rei que vem em nome do Senhor; paz no céu, e glória nas alturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'E alguns dos fariseus da multidão lhe disseram: Mestre, repreende a teus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'E respondendo ele, disse-lhes: Digo-vos, que se estes se calarem, as pedras clamariam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'E quando já estava chegando, viu a cidade, e chorou por causa dela,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Dizendo: Ah, se tu também conhecesses, pelo menos neste teu dia, aquilo que lhe traria paz! Mas agora isto está escondido de teus olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Porque dias virão sobre ti, em que teus inimigos lhe cercarão com barricadas, e ao redor te sitiarão, e lhe pressionarão por todos os lados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'E derrubarão a ti, e a teus filhos; e não deixarão em ti pedra sobre pedra, porque não conheceste o tempo em que foste visitada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'E entrando no Templo, começou a expulsar a todos os que vendiam e compravam ali,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Dizendo-lhes: Está escrito: Minha casa é casa de oração; Mas vós a tendes feito um esconderijo de ladrões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'E ensinava diariamente no Templo; e os chefes dos sacerdotes, e os escribas, e os chefes do povo, procuravam matá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'E não achavam como fazer, porque todo o povo o ouvia com muita atenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'E aconteceu, num daqueles dias que, enquanto ele estava ensinando ao povo no Templo, e anunciando o Evangelho, vieram até ele os chefes dos sacerdotes, e os escribas com os anciãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'E falaram-lhe, dizendo: Dize-nos, com que autoridade fazes estas coisas? Ou quem é o que te deu esta autoridade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'E respondendo ele, disse-lhes: Também eu vos perguntarei algo, e dizei-me:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'O batismo de João era do céu, ou dos homens?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'E eles discutiam entre si, dizendo: Se dissermos: Do céu, ele nos dirá: Por que, então, vós não o crestes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'E se dissermos: Dos homens, todo o povo nos apedrejará; pois estão convencidos de que João era profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'E responderam que não sabiam de onde era.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'E Jesus lhes disse: Nem eu vos direi com que autoridade eu faço estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'E começou a dizer ao povo esta parábola: Um certo homem plantou uma vinha, e a arrendou a uns lavradores, e viajou para outro país por muito tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'E certo tempo depois mandou um servo aos lavradores, para que lhe dessem do fruto da vinha; mas os lavradores, espancando-o, mandaram -no sem coisa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'E voltou a mandar outro servo; mas eles, espancando e humilhando também a ele,o mandaram sem nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'E voltou a mandar ao terceiro; mas eles, ferindo também a este, o expulsaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'E o senhor da vinha disse: Que farei? Mandarei a meu filho amado; talvez quando o verem, o respeitarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mas os lavradores, vendo-o, discutiram entre si, dizendo: Este é o herdeiro; vamos matá-lo, para que a herança venha a ser nossa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'E expulsando-o da vinha, o mataram. O que, então, lhes fará o senhor da vinha?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Virá, e destruirá a estes lavradores, e dará a vinha a outros.E eles, ouvindo isto, disseram: Que isto nunca aconteça!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Mas Jesus,olhando para eles, disse: Por que, então, isto está escrito: A pedra que os construtores rejeitaram, essa foi posta como a principal da esquina?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Todo aquele que cair sobre aquela pedra, se quebrará em pedaços; e aquele sobre quem ela cair, se fará pó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'E os chefes dos sacerdotes e os escribas queriam detê-lo naquela mesma hora, mas temiam ao povo; porque entenderam que foi contra eles que ele tinha dito a parábola.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'E, observando-o, mandaram espiões, que fingissem ser justos, para o pegarem por meio de algo que ele dissesse, e o entregarem ao poder e autoridade do governador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'E perguntaram-lhe, dizendo: Mestre, nós sabemos que falas e ensinas corretamente, e que não te importas com as aparências, mas na verdade tu ensinas o caminho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'É lícito para nós dar tributo a César, ou não?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'E ele, entendendo a astúcia deles, disse-lhes: Por que me tentais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Mostrai-me uma moeda; ela tem a imagem e a inscrição de quem?E eles, respondendo, disseram: De César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Então lhes disse: Dai pois a César o que é de César, e a Deus o que é de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'E não puderam lhe pegar em algo que ele tenha dito diante do povo; e maravilhados de sua resposta, calaram-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'E chegando-se alguns dos saduceus, que negam haver a ressurreição, perguntaram-lhe,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Dizendo: Mestre, Moisés nos escreveu, que se o irmão de alguém morrer, tendo mulher, e morrer sem filhos, o irmão deve tomar a mulher, e gerar descendência a seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Houve, pois, sete irmãos, e o primeiro tomou mulher, e morreu sem filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'E o segundo a tomou; e também este morreu sem filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'E o terceiro a tomou, e assim também os sete, e não deixaram filhos, e morreram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'E por fim, depois de todos, morreu também a mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Na ressurreição, pois, ela será mulher de qual deles? Pois os sete a tiveram por mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'E respondendo Jesus, disse-lhes: Os filhos destes tempos se casam, e se dão em casamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Mas os que forem considerados dignos de alcançarem aqueles tempos futuros, e da ressurreição dos mortos, nem se casarão, nem se darão em casamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Porque já não podem mais morrer; pois são iguais aos anjos; e são filhos de Deus, pois são filhos da ressurreição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'E até Moisés mostrou, junto à sarça, que os mortos ressuscitam, quando ele chama ao Senhor de Deus de Abraão, e Deus de Isaque, e Deus de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Ora, ele não é Deus de mortos, mas de vivos; pois todos vivem por causa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'E alguns dos escribas, respondendo, disseram: Mestre, bem disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'E não ousavam lhe perguntar mais nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'E ele lhes disse: Como dizem que o Cristo é filho de Davi?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Pois o próprio Davi diz no livro dos Salmos: Disse o Senhor a meu Senhor: Senta-te à minha direita,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Até que eu ponha teus inimigos por escabelo de teus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Se Davi o chama de Senhor, como, então, é seu filho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Enquanto todo o povo estava ouvindo, ele disse a seus discípulos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Tomai cuidado com os escribas, que querem andar roupas compridas, e amam as saudações nas praças, e as primeiras cadeiras nas sinagogas, e os primeiros assentos nos jantares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Que devoram as casas das viúvas, e fingem fazer longas orações. Estes receberão mais grave condenação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'E ele, olhando, viu os ricos lançarem suas ofertas na arca do tesouro do templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'E viu também uma pobre viúva lançar ali duas pequenas moedas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'E disse: Em verdade vos digo, que esta pobre viúva lançou mais do que todos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Porque todos aqueles outros lançaram para as ofertas de Deus daquilo que lhes sobrava; mas esta viúva,de sua pobreza, lançou todo sustento quanto tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'E alguns estavam falando do Templo, que estava adornado com formosas pedras e ofertas. Então Jesus disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'D estas coisas que vedes, dias virão, em que não se deixará pedra sobre pedra, que não seja derrubada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'E perguntaram-lhe, dizendo: Mestre, quando então serão essas coisas? E que sinal haverá, quando essas coisas vierem a acontecer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Então ele disse: Olhai para que não vos enganem, porque muitos virão em meu nome, dizendo: Eu sou o Cristo. E o tempo já está perto; portanto não os sigais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'E quando ouvirdes de guerras, e de rebeliões, não vos espanteis. Porque é necessário que estas coisas aconteçam primeiro; mas ainda não é o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Então lhe disse: Então se levantará nação contra nação, e reino contra reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'E haverá em vários lugares grandes terremotos e fomes, e pragas; haverá também coisas espantosas, e grandes sinais do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Mas antes de tudo isto, eles vos impedirão e vos perseguirão, vos entregando em sinagogas e prisões, e vos trazendo diante de reis, e governadores, por causa do meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'E isto vos acontecerá para haver testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Ponde, então, em vossos corações, de que não planejeis como direis em vossa defesa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Porque eu vos darei boca e sabedoria, para que todos os que forem contra vós não posam vos contradizer ou resistir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'E vós sereis entregues até pelos pais, e irmãos, e parentes, e amigos; e alguns de vós serão mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'E vós sereis odiados por todos por causa do meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Mas nem um cabelo de vossa cabeça parecerá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Por vossa paciência ganhareis vossas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Porém quando virdes a Jerusalém cercada de exércitos, sabei então, que próxima está sua desolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Então, os que estiverem na Judeia, fujam para os montes; e os que estiverem no meio dela, saiam, e os que estiverem nos campos, não entrem nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Porque estes são dias de vingança, para que todas as coisas que estão escritas se cumpram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Mas ai das grávidas, e das que amamentarem naqueles dias; porque grande calamidade haverá na terra, e ira contra este povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'E cairão pela lâmina de espada, e serão levados cativos para todas as nações; e Jerusalém será pisada pelos gentios, até que os tempos dos gentios se cumpram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'E haverá sinais no Sol, na Lua, e nas estrelas; e na terra sofrimento entre as nações, como o rugir e agitar do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'As pessoas se enfraquecendo de medo, e da espera das coisas que virão ao mundo, porque os poderes dos céus serão abalados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'E então verão o Filho do homem vir em uma nuvem com grande poder e glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Ora, quando estas coisas começarem a acontecer, olhai para cima, e levantai vossas cabeças, porque vosso resgate está perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'E disse-lhes uma parábola: Olhai a figueira, e todas as árvores;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Quando vós vedes elas já brotando, sabeis por vós mesmos que o verão já está perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Assim também vós, quando virdes acontecer estas coisas, sabei que o Reino de Deus já está perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Em verdade vos digo, que esta geração não passará, até que tudo aconteça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'O céu e a terra passarão, mas minhas palavras de maneira nenhuma passarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'E olhai por vós, para que vossos corações não venham a se encher de ressaca e embriaguez, e das preocupações d esta vida; e vos venha aquele dia de surpresa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Porque virá como uma armadilha sobre todos os que habitam sobre a face de toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Então vigiai sempre, orando para que sejais considerados dignos de escaparem de todas as coisas que irão acontecer, e de ficarem de pé diante do Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'E ensinava durante os dias no Templo, porém, às noites saía e as passava no monte, chamado as Oliveiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'E todo o povo vinha até ele de manhã cedo ao templo, para o ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Estava perto a festa dos pães sem fermento, chamada de páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'E os chefes dos sacerdotes, e os escribas procuravam um meio de o matar, pois eles temiam ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'E Satanás entrou no Judas que era chamado Iscariotes, que era um dos doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'E foi, e falou com os chefes dos sacerdotes e os oficiais, sobre como o entregaria para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'E estes se alegraram, e concordaram em lhe dar dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'E lhes prometeu, e buscava oportunidade para o entregar quando não houvesse uma multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'E veio o dia dos pães sem fermento, em que se devia fazer o sacrifício da páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'E Jesus mandou a Pedro, e a João, dizendo: Ide, preparai-nos a páscoa, para que a comamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'E eles lhe disseram: Onde queres que a preparemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'E ele lhes disse: Eis que, quando entrardes na cidade, um homem com um vaso de água vos encontrará; segui-o até a casa onde ele entrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'E direis ao dono da casa: O Mestre te diz: Onde está o salão onde comerei a páscoa com meus discípulos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Então ele vos mostrará um grande salão já arrumado; preparai-a ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'E indo eles, acharam como lhes tinha dito; e prepararam a páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'E vinda a hora, sentou-se à mesa,e com ele os doze apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'E disse-lhes: Muito desejei comer convosco esta páscoa, antes que eu sofra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Porque eu vos digo, que dela não mais comerei, até que isto se cumpra no Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'E tomando o copo, e tendo agradecido a Deus,disse: Tomai-o, e reparti -o entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Porque vos digo, que do fruto da videira eu não beberei, até que o Reino de Deus venha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'E tomando o pão, e tendo agradecido a Deus,partiu-o, e o deu a eles, dizendo: Isto é o meu corpo, que é dado por vós; fazei isto em memória de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'De modo semelhante também com o copo, depois da ceia, disse: Este copo é o Novo Testamento em meu sangue, que é derramado por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Porém eis que a mão do que me trai está comigo à mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'E realmente o Filho do homem vai conforme o que está determinado; mas ai daquele homem por quem é traído!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'E começaram a perguntar entre si, qual deles seria o que faria isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'E houve também uma briga entre eles, sobre qual deles era considerado o maior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'E Jesus lhes disse: Os reis dos gentios os dominam, e os que exercem autoridade sobre eles são chamados de benfeitores;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Mas não seja assim entre vós; antes o maior de vós seja como o menor; e o que lidera, como o que serve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Porque qual é maior? O que se senta à mesa,ou o que serve? Por acaso não é o que se senta à mesa? Porém eu estou entre vós como aquele que serve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'E vós sois os que tendes permanecido comigo em minhas tentações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'E eu vos determino um Reino, assim como meu pai o determinou a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Para que em meu Reino, comais e bebais à minha mesa; e vos senteis sobre tronos, julgando as doze tribos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Disse também o Senhor: Simão, Simão; eis que Satanás vos pediu, para vos peneirar como trigo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Mas eu roguei por ti, que tua fé não se acabe; e quando tu te converteres, fortaleça teus irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'E ele lhe disse: Senhor, estou preparado para ir contigo até à prisão, e à morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Mas ele disse: Pedro, eu te digo que hoje o galo não cantará, antes que me negues três vezes que me conheces.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'E disse a eles: Quando vos mandei sem bolsa, e sem sacola, e sem sandálias, por acaso algo vos faltou?E disseram: Nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Então, ele lhes disse: Mas agora, quem tem bolsa, tome-a, como também a sacola; e o que não tem espada, venda sua roupa, e compre uma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Porque eu vos digo, que ainda é necessário que se cumpra em mim aquilo que está escrito: E ele foi contado com os malfeitores. Porque aquilo que é sobre mim tem que se cumprir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'E eles disseram: Senhor, eis aqui duas espadas.E ele lhes disse: É o suficiente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'E saindo, foi, como de costume, para o monte das Oliveiras; e os seus discípulos também o seguiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'E quando chegou a aquele lugar, disse-lhes: Orai para que não entreis em tentação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'E se afastou deles, à distância de um tiro de pedra. E pondo-se de joelhos, orava,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Dizendo: Pai, se tu quiseres, passa este copo de mim; porém não se faça minha vontade, mas a tua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'E apareceu-lhe um anjo do céu, que o fortalecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'E estando em angústia, orava mais intensamente. E seu suor se fez como gotas de sangue, que desciam até o chão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'E ele, levantando-se da oração, veio a seus discípulos, e os achou dormindo por causa da tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'E disse-lhes: Por que estais dormindo? Levantai-vos, e orai, para que não entreis em tentação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'E enquanto ele ainda estava falando, eis que uma multidão chegou; e um dos doze, o que se chamava Judas, ia adiante deles, e se aproximou de Jesus, para o beijar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'E Jesus lhe disse: Judas, com um beijo trais ao Filho do homem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'E os que estavam com ele, vendo o que iria acontecer, disseram-lhe: Senhor, feriremos com a espada?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'E um deles feriu a um servo do chefe dos sacerdotes, e cortou-lhe a orelha direita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'E respondendo Jesus, disse: Para com isto! E tocando-lhe a orelha, o curou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'E disse Jesus aos chefes dos sacerdotes, e aos oficiais do Templo, e aos anciãos, que tinham vindo contra ele: Como se eu fosse ladrão, saístes com espadas e bastões?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Estando eu convosco todo dia no Templo, contra mim não me prendestes; mas esta é a vossa hora, e sob a autoridade das trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'E prendendo-o, o trouxeram e o puseram na casa do sumo sacerdote. E Pedro o seguia de longe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'E acenderam fogo no meio do pátio, e sentaram-se juntos, e Pedro se sentou entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'E uma serva, vendo-o sentado junto ao fogo, fixando o olhos nele, disse: Este também estava com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Porém ele o negou, dizendo: Mulher, eu não o conheço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'E pouco depois, outro o viu, e disse: Também tu és um deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'E quando já tinha passado quase uma hora, outro afirmava, dizendo: Verdadeiramente também este estava com ele, porque também é galileu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'E Pedro disse: Homem, não sei o que dizes.E logo, estando ele ainda falando, cantou o galo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'E o Senhor, virando-se, olhou para Pedro; e Pedro se lembrou da palavra do Senhor, como lhe tinha dito: Antes que o galo cante, tu me negarás três vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'E Pedro, saindo, chorou amargamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'E os homens que tinham prendido a Jesus zombavam dele, ferindo-o;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'E cobrindo-o, feriam-no no rosto; e perguntavam-lhe, dizendo: Profetiza, quem é o que te feriu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'E diziam muitas outras coisas contra ele, insultando-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'E quando já era de dia, juntaram-se os anciãos do povo, e os chefes dos sacerdotes, e os escribas, e o trouxeram ao seu conselho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Dizendo Tu és o Cristo? Dize-nos.E ele lhes disse: Se eu vos disser, não o crereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'E também se eu perguntar, não me respondereis, nem me soltareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'A partir de agora o Filho do homem se sentará à direita do poder de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'E todos disseram: Então tu és o Filho de Deus?E ele lhes disse: Vós dizeis que eu sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'E eles disseram: Para que precisamos de mais testemunho? Pois nós mesmos o ouvimos de sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'E levantando-se toda a multidão deles, o levaram a Pilatos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'E começaram a acusá-lo, dizendo: Encontramos este homem,que perverte a nação, e proíbe dar tributo a César, dizendo que ele mesmo é Cristo, o Rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'E Pilatos lhe perguntou, dizendo: Tu és o Rei dos judeus?E respondendo, ele lhe disse: Tu o dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'E Pilatos disse aos chefes dos sacerdotes, e às multidões: Não acho culpa nenhuma neste homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mas eles insistiam, dizendo: Ele incita ao povo, ensinando por toda a Judeia, começando desde a Galileia até aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Então Pilatos, ouvindo falar da Galileia, perguntou se aquele homem era galileu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'E quando soube que era da jurisdição de Herodes, ele o entregou a Herodes, que naqueles dias também estava em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'E Herodes, ao ver Jesus, alegrou-se muito, porque havia muito tempo que desejava o ver, pois ouvia muitas coisas sobre ele; e esperava ver algum sinal feito por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'E perguntava-lhe com muitas palavras, mas ele nada lhe respondia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'E estavam lá os chefes dos sacerdotes, e os escribas, acusando-o com veemência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'E Herodes, com seus soldados, desprezando-o, e escarnecendo dele, o vestiu com uma roupa luxuosa, e o enviou de volta a Pilatos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'E no mesmo dia Pilatos e Herodes se fizeram amigos; porque antes tinham inimizade um contra o outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'E Pilatos, convocando aos chefes dos sacerdotes, aos líderes, e ao povo, disse-lhes:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Vós me trouxestes a este homem, como que perverte o povo; e eis que eu, examinando-o em vossa presença, nenhuma culpa eu acho neste homem, das de que o acusais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'E nem também Herodes; porque a ele eu vos remeti; e eis que ele nada fez para que seja digno de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Então eu o castigarei, e depois o soltarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'E ele tinha de soltar-lhes alguém durante a festa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Porém todos clamavam juntos, dizendo: Tirai-o daqui! E soltai Barrabás para nós!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '(O qual por uma rebelião feita na cidade, e por uma morte, tinha sido lançado na prisão).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilatos falou-lhes então outra vez, querendo soltar Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Mas eles clamavam, dizendo: Crucifica -o! crucifica-o!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'E ele lhes disse a terceira vez: Pois que mal este fez? Nenhuma culpa de morte nele eu achei. Então eu o castigarei, e depois o soltarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mas eles continuavam, com grandes gritos, pedindo que fosse crucificado. E seus gritos, e os dos chefes dos sacerdotes, prevaleceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Então Pilatos julgou que se fizesse o que pediam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'E soltou-lhes ao que fora lançado na prisão por uma rebelião e uma morte, que era o que pediam; porém a Jesus lhes entregou à sua vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'E enquanto o levavam, tomaram a um Simão Cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse atrás de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'E seguia-o uma grande multidão do povo, e de mulheres, as quais também ficavam desconsoladas, e lamentavam por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'E Jesus, virando-se para elas, disse: Filhas de Jerusalém, não choreis por mim, mas chorai por vós mesmas, e por vossos filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Porque eis que vêm dias em que dirão: Bem-aventuradas as estéreis, e os ventres que não deram a luz, e os peitos que não amamentaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Então começarão a dizer aos montes: Cai sobre nós; E aos morros: Cobri-nos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Porque, se fazem isto à árvore verde, o que se fará com a árvore seca?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'E também levaram outros dois, que eram malfeitores, para matar com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'E quando chegaram ao lugar, chamado a Caveira, o crucificaram ali, e aos malfeitores, um à direita, e outro à esquerda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'E Jesus dizia: Pai, perdoa-lhes, porque não sabem o que fazem. E, repartindo suas roupas, lançaram sortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'E o povo estava olhando; e os líderes também zombavam com eles, dizendo: Salvou a outros, salve agora a si mesmo, se é o Cristo, o escolhido de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'E os soldados também escarneciam dele, aproximando-se dele, e mostrando-lhe vinagre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'E dizendo: Se tu és o Rei dos judeus, salva a ti mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'E também estava acima dele um título escrito com letras gregas, romanas e hebraicas: ESTE É O REI DOS JUDEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'E um dos malfeitores que estavam pendurados o insultava, dizendo: Se tu és o Cristo, salva a ti mesmo, e a nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Porém o outro, respondendo, repreendia-o, dizendo: Tu ainda não temes a Deus, mesmo estando na mesma condenação?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'E nós realmente estamos sendo punidos justamente, porque estamos recebendo de volta merecidamente por aquilo que praticamos; mas este nada fez de errado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'E disse a Jesus: Senhor, lembra-te de mim, quando chegares em teu Reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'E Jesus lhe disse: Em verdade te digo, hoje estarás comigo no paraíso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'E era já quase a hora sexta, e houve trevas em toda a terra, até a hora nona.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'E o sol se escureceu, e o véu do templo se rasgou ao meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'E Jesus, clamando em alta voz, disse: Pai, em tuas mãos eu entrego meu espírito.E tendo dito isto, parou de respirar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'E o centurião, vendo o o que tinha acontecido, deu glória a Deus, dizendo: Verdadeiramente este homem era justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'E todas as multidões que se juntavam para observar, vendo o que tinha acontecido, voltaram, batendo nos peitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'E todos os seus conhecidos, e as mulheres que acompanhando -o desde a Galileia, tinham o seguido, estavam longe, vendo estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'E eis que um homem, de nome José, membro do conselho de justiça,sendo homem bom e justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(Que não tinha concordado, nem com o conselho, nem em atos que fizeram), da cidade de Arimateia, da terra dos judeus, e que também esperava pelo Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Este, chegando a Pilatos, pediu o corpo de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'E tendo o tirado, o envolveu em um tecido de linho, e o pôs em um sepulcro, escavado em uma rocha, onde nunca ainda tinha sido posto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'E era o dia da preparação, e o sábado estava começando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'E as mulheres que vieram com ele da Galileia também o seguiram, e viram o sepulcro, e como seu corpo foi posto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'E elas, ao voltarem, prepararam materiais aromáticos e óleos perfumados. E descansaram o sábado, conforme o mandamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'E no primeiro dia da semana, de madrugada bem cedo, foram ao sepulcro, levando consigo os materiais aromáticos que tinham preparado; e algumas outras junto delas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'E acharam a pedra já revolvida do sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'E entrando, não acharam o corpo do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'E aconteceu, que estando elas perplexas, eis que dois homens apareceram junto a elas, com roupas luminosas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'E estando elas com muito medo, e abaixando o rosto para o chão, eles lhes disseram: Por que buscam entre os mortos aquele que vive?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Ele não está aqui, mas já ressuscitou. Lembrai-vos de como ele vos falou, quando ainda estava na Galileia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Dizendo: É necessário que o Filho do homem seja entregue nas mãos de homens pecadores, e que seja crucificado, e ressuscite ao terceiro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'E se lembraram das palavras dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'E, voltando do sepulcro, anunciaram todas estas coisas aos onze, e a todos os outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'E eram Maria Madalena, e Joana, e Maria mãe de Tiago, e as outras que estavam com elas, que diziam estas coisas aos apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'E para eles, as palavras delas pareciam não ter sentido; e não creram nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Porém Pedro, levantando-se, correu ao sepulcro; e abaixando-se, viu os tecidos postos separadamente; e saiu maravilhado com o que tinha acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'E eis que dois deles iam naquele mesmo dia a uma aldeia, cujo nome era Emaús, que estava a sessenta estádios de distância de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'E iam falando entre si de todas aquelas coisas que tinham acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'E aconteceu que, enquanto eles estavam conversando entre si, e perguntando um ao outro, Jesus se aproximou, e foi junto deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Mas seus olhos foram retidos, para que não o reconhecessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'E disse-lhes: Que conversas são essas, que vós discutis enquanto andam, e ficais tristes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'E um deles,cujo nome era Cleofas, respondendo-o, disse-lhe: És tu o único viajante em Jerusalém que não sabe as coisas que nela tem acontecido nestes dias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'E ele lhes disse: Quais?E eles lhe disseram: As sobre Jesus de Nazaré, a qual foi um homem profeta, poderoso em obras e em palavras, diante de Deus, e de todo o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'E como os chefes dos sacerdotes, e nossos líderes o entregaram à condenação de morte, e o crucificaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'E nós esperávamos que ele fosse aquele que libertar a Israel; porém além de tudo isto, hoje é o terceiro dia desde que estas coisas aconteceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Ainda que também algumas mulheres dentre nós nos deixaram surpresos, as quais de madrugada foram ao sepulcro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'E não achando seu corpo, vieram, dizendo que também tinham visto uma aparição de anjos, que disseram que ele vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'E alguns do que estão conosco foram ao sepulcro, e o acharam assim como as mulheres tinham dito; porém não o viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'E ele lhes disse: Ó tolos, e que demoram no coração para crerem em tudo o que os profetas falaram!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Por acaso não era necessário que o Cristo sofresse estas coisas, e então entrar em sua glória?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'E começando de Moisés, e por todos os profetas, lhes declarava em todas as Escrituras o que estava escrito sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'E chegaram à aldeia para onde estavam indo; e ele agiu como se fosse para um lugar mais distante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'E eles lhe rogaram, dizendo: Fica conosco, porque já é tarde, e o dia está entardecendo;E ele entrou para ficar com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'E aconteceu que, estando sentado com eles à mesa,tomou o pão, o benzeu, o partiu, e o deu a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'E os olhos deles se abriram, e o reconheceram, e ele lhes desapareceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'E diziam um ao outro: Por acaso não estava nosso coração ardendo em nós, quando ele falava conosco pelo caminho, e quando nos desvendava as Escrituras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'E levantando-se na mesma hora, voltaram para Jerusalém, e acharam reunidos aos onze, e aos que estavam com eles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Que diziam: Verdadeiramente o Senhor ressuscitou, e já apareceu a Simão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'E eles contaram as coisas que lhes aconteceram no caminho; e como foi reconhecido por eles quando partiu o pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'E enquanto eles falavam disto, o próprio Jesus se pôs no meio deles, e lhes disse: Paz seja convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'E eles, espantados, e muito atemorizados, pensavam que viam algum espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'E ele lhes disse: Por que estais perturbados, e por que sobem dúvidas em vossos corações?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Vede minhas mãos, e os meus pés, que sou em mesmo. Tocai-me, e vede, porque um espírito não tem carne nem ossos, como vós vedes que eu tenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'E dizendo isto, lhes mostrou as mãos e os pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'E eles, não crendo ainda, por causa da alegria, e maravilhados, Jesus disse-lhes: Tendes aqui alguma coisa para comer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Então eles lhe apresentaram parte de um peixe assado e de um favo de mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Ele pegou, e comeu diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'E disse-lhes: Estas são as palavras que eu vos disse, enquanto ainda estava convosco, que era necessário que se cumprissem todas as coisas que estão escritas sobre mim na Lei de Moisés, nos profetas, e nos Salmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Então ele lhes abriu o entendimento, para que entendessem as Escrituras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'E disse-lhes: Assim está escrito, e assim era necessário que o Cristo sofresse, e que ao terceiro dia ressuscitasse dos mortos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'E que em seu nome fosse pregado arrependimento e perdão de pecados em todas as nações, começando de Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'E destas coisas vós sois testemunhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'E eis que eu envio a promessa de meu Pai sobre vós; porém ficai vós na cidade de Jerusalém, até que vos seja dado poder do alto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'E os levou para fora até Betânia, e levantando suas mãos, os abençoou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'E aconteceu que, enquanto os abençoava, ele se afastou deles, e foi conduzido para cima ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'E eles, adorando-o, voltaram para Jerusalém com grande alegria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'E estavam sempre no Templo, louvando e bendizendo a Deus. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'No princípio era a Palavra, e a Palavra estava junto de Deus, e a Palavra era Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Esta estava no princípio junto de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Por esta foram feitas todas as coisas, e sem ela não se fez coisa nenhuma do que foi feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Nela estava a vida, e a vida era a luz dos seres humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'E a luz brilha nas trevas; e as trevas não a compreenderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Houve um homem enviado por Deus, cujo nome era João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Este veio por testemunho, para que testemunhasse da Luz, para que todos por ele cressem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Ele não era a Luz; mas foi enviado para que testemunhasse da Luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Esta era a luz verdadeira, que ilumina a todo ser humano que vem ao mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'No mundo estava, e por ele foi feito o mundo; e o mundo não o conheceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Ao seu próprio veio, e os seus não o receberam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Mas a todos quantos o receberam, deu-lhes poder de serem feitos filhos de Deus: aos que creem em seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Os quais não são gerados de sangue, nem de vontade da carne, nem de vontade de homem, mas sim de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'E aquela Palavra se fez carne, e habitou entre nós; (e vimos sua glória, como glória do unigênito do Pai) cheio de graça e de verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'E João dele testemunhou, e clamou, dizendo: Este era aquele, de quem eu dizia: O que vem após mim é antes de mim; porque era primeiro que eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'E de sua plenitude recebemos todos também graça por graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Porque a Lei foi dada por Moisés; a graça e a verdade foi feita por Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'A Deus nunca ninguém o viu; o unigênito Filho, que está no seio do Pai, ele o declarou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'E este é o testemunho de João, quando os judeus mandaram alguns sacerdotes e levitas de Jerusalém, que lhe perguntassem: Tu quem és?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'E confessou, e não negou; e confessou: Eu não sou o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'E lhe perguntaram: Que, então? És tu Elias? E ele disse: Não sou. Eles disseram: Tu és o Profeta? E ele respondeu: Não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Disseram-lhe pois: Quem és? Para darmos resposta aos que nos enviaram. Que dizes de ti mesmo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Disse: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'E os enviados eram dos fariseus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'E perguntaram-lhe, e disseram-lhe: Por que pois batizas, se tu não és o Cristo, nem Elias, nem o profeta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'João lhes respondeu, dizendo: Eu batizo com água; mas em meio de vós, está a quem vós não conheceis,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Este é aquele que vem após mim, o qual já foi antes de mim, do qual eu não sou digno de desatar a tira de sua sandália.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Estas coisas aconteceram em Betábara, do outro lado do Jordão, onde João estava batizando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'O dia seguinte viu João a Jesus vir a ele, e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Este é aquele do qual eu disse: Após mim vem um homem que já foi antes de mim; porque já era primeiro que eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'E eu não o conhecia; mas para que fosse manifesto a Israel, por isso vim eu batizando com água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'E João testemunhou, dizendo: Eu vi o Espírito como pomba descer do céu, e repousou sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'E eu não o conhecia, mas aquele que me mandou a batizar com água, esse me disse: Sobre aquele que vires descer ao Espírito, e repousar sobre ele, esse é o que batiza com Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'E eu o vi, e testemunhado tenho, que este é o Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'O seguinte dia estava outra vez ali João, e dois de seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'E vendo por ali andar a Jesus, disse: Eis o Cordeiro de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'E os dois discípulos ouviram -lhe dizer aquilo, e seguiram a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'E Jesus, virando-se, e vendo-os seguir, disse-lhes: Que buscais? E eles lhe disseram: Rabi, (que traduzido, quer dizer, Mestre) onde moras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Disse-lhes ele: Vinde, e vede-o; Vieram, e viram onde morava, e na companhia dele naquele dia; e já era quase a hora décima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Era André, o irmão de Simão Pedro, um dos dois que ouvira aquilo de João, e o haviam seguido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Este achou primeiro a seu irmão Simão, e disse-lhe: Já achamos ao Messias(que traduzido, é o Cristo).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'E levou-o a Jesus. E Jesus, olhando para ele, disse: Tu és Simão, filho de Jonas; tu serás chamado Cefas. (que se traduz Pedro).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'O dia seguinte Jesus quis ir à Galileia, achou Filipe, e disse-lhe: Segue-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'E Filipe era de Betsaida, da cidade de André e de Pedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filipe achou Natanael, e disse-lhe: Achamos aquele de quem Moisés escreveu na Lei, e os Profetas: a Jesus, o filho de José, de Nazaré.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'E disse-lhe Natanael: Pode haver alguma coisa boa de Nazaré? Filipe lhe disse: Vem, e vê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesus viu Natanael vir, e disse dele: Eis verdadeiramente um israelita, em quem não há engano!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natanael lhe disse: De onde tu me conheces? Respondeu Jesus, e disse-lhe: Antes que Filipe te chamasse, estando tu debaixo da figueira, eu te vi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natanael respondeu, e disse-lhe: Rabi, tu és o Filho de Deus, tu és o Rei de Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jesus respondeu, e disse-lhe: Porque te disse: Debaixo da figueira te vi, crês? Tu verás coisas maiores que estas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'E disse-lhe: Em verdade, em verdade vos digo, que daqui em diante vereis o céu aberto, e aos anjos de Deus subir e descer sobre o Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'E no terceiro dia houve um casamento em Caná da Galileia; e a mãe de Jesus estava ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'E também Jesus foi convidado com seus discípulos ao casamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'E tendo faltado vinho, a mãe de Jesus lhe disse: Não têm vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jesus lhe disse: O que eu tenho contigo, mulher? A minha hora ainda não chegou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Sua mãe disse aos serventes: Fazei tudo quanto ele vos disser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'E estavam ali postos seis vasos de pedra, conforme à purificação dos judeus, em cada uma cabiam duas ou três metretas.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Disse-lhes Jesus: Enchei estes vasos com água. E encheram-nas até encima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'E disse-lhes: Agora tirai, e a levai ao mestre de cerimônia. Então levaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'E quando o mestre de cerimônia experimentou a água feita vinho (sem saber de onde era, porém os serventes que haviam tirado a água sabiam), o mestre de cerimônia chamou o noivo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'E disse-lhe: Todos põem primeiro o vinho bom, e quando os convidados já estão bêbados, então se dá o pior; porém tu guardaste o bom vinho até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Este princípio de sinais Jesus fez em Caná da Galileia, e manifestou sua glória; e seus discípulos creram nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Depois disto desceu a Cafarnaum, ele e sua mãe, seus irmãos, e seus discípulos, e ficaram ali não muitos dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'E estava perto a Páscoa dos judeus, e Jesus subiu a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'E achou no Templo os que vendiam bois, ovelhas, e pombas, e os cambistas sentados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'E tendo feito um açoite com cordas, lançou todos para fora do Templo, assim como as ovelhas, e os bois; e espalhou o dinheiro dos cambistas, e virou as mesas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'E aos que vendiam pombas, disse: Tirai isto daqui; e não torneis a casa de meu Pai uma casa de comércio!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'E lembraram-se seus discípulos que está escrito: O zelo de tua casa me tem me devorado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Responderam pois os Judeus, e disseram-lhe: Que sinal nos mostras de que fazes estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Respondeu Jesus, e disse-lhes: Derrubai este Templo, e em três dias o levantarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Os judeus, pois, disseram: Durante quarenta e seis anos este Templo foi edificado, e tu o levantarás tu em três dias?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Porém ele falava do Templo de seu corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Portanto, quando ressuscitou dos mortos, seus discípulos se lembraram que ele lhes tinha dito isto; e creram na Escritura, e na palavra que Jesus tinha lhes dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'E estando ele em Jerusalém pela páscoa, na festa, muitos creram em seu nome, ao verem os sinais que ele fazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Mas o mesmo Jesus a si mesmo não confiava neles, porque conhecia a todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'E não necessitava de que alguém lhe desse testemunho de ser humano algum, pois ele bem sabia o que havia no interior do ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'E havia um homem dos fariseus, cujo nome era Nicodemos, chefe dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Este veio a Jesus de noite, e disse-lhe: Rabi, bem sabemos que és Mestre vindo de Deus; porque ninguém pode fazer estes sinais que tu fazes, se Deus não for com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Respondeu Jesus e disse-lhe: Em verdade, em verdade te digo, que aquele que não voltar a nascer, não pode ver o Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nicodemos lhe disse: Como pode o homem nascer, sendo já velho? Pode ele voltar a entrar no ventre de sua mãe, e nascer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Respondeu Jesus: Em verdade, em verdade te digo, que aquele que não nascer de água e do Espírito, não pode entrar no Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'O que é nascido de carne, carne é; e o que é nascido do Espírito, espírito é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Não te maravilhes de que te disse: necessário vos é voltar a nascer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'O vento sopra onde quer, e ouves o seu som; porém não sabes de onde vem, nem para onde vai; assim é todo aquele que é nascido do Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodemos respondeu, e disse-lhe: Como pode isto acontecer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesus respondeu, e disse-lhe: Tu és mestre de Israel, e isto não sabes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Em verdade, em verdade te digo, que o que sabemos, falamos; e o que temos visto, testemunhamos; e não aceitais nosso testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Se eu vos disse coisas terrenas, e não credes, como crereis, se vos disser as celestiais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'E ninguém subiu ao céu, a não ser o que desceu do céu: o Filho do homem, que está no céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'E como Moisés levantou a serpente no deserto, assim deve o Filho do homem ser levantado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Para que todo aquele que nele crer não pereça, mas tenha a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Porque Deus amou ao mundo de tal maneira, que deu o seu Filho unigênito; para que todo aquele que nele crê não pereça, mas tenha a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Porque Deus não mandou seu Filho ao mundo para que condenasse ao mundo; mas sim para que o mundo por ele fosse salvo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Quem nele crer não é condenado; mas quem não crê já está condenado; pois não tem crido no nome do unigênito Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'E esta é a condenação: que a luz veio ao mundo, e as pessoas amaram mais as trevas que a luz, porque suas obras eram más.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Porque todo aquele que faz o mal odeia a luz e não vem à luz, para que suas obras não sejam reprovadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Mas quem pratica a verdade vem à luz, para que suas obras sejam manifestas, que são feitas em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Depois disto Jesus veio com seus discípulos à terra da Judeia; e estava ali com eles, e batizava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'E João também batizava em Enom, junto a Salim, porque havia ali muitas águas; e vinham ali, e eram batizados,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Porque João ainda não tinha sido lançado na prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Houve pois uma discussão dos Discípulos de João com os judeus sobre a purificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'E vieram a João, e disseram-lhe: Rabi, aquele que estava contigo dalém do Jordão, ao qual tu deste testemunho, eis que batiza, e todos vem a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'João respondeu, e disse: O ser humano não pode receber coisa alguma, se não lhe for dada do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vós mesmos me sois testemunhas, que disse: Eu não sou o Cristo; mas que sou enviado diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Aquele que tem a esposa, é o esposo; mas o amigo do esposo, que o apoia, e lhe ouve, alegra-se muito pela voz do esposo. Assim pois já este meu gozo é cumprido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'A ele convém crescer, porém a mim diminuir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Aquele que vem de cima, é sobre todos; aquele que vem da terra, da terra é, e da terra fala. Aquele que vem do céu é sobre todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'E daquilo que viu e ouviu, isto testemunha; e ninguém aceita seu testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Aquele que aceitou seu testemunho, esse selou que Deus é verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Porque aquele que Deus enviou, as palavras de Deus fala; porque não lhe dá Deus o Espírito por medida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'O Pai ama ao Filho, e todas as coisas lhe deu em sua mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Aquele que crê no Filho tem vida eterna; porém aquele que é desobediente ao Filho não verá a vida eterna, mas a ira de Deus continua sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Quando, pois, o Senhor entendeu que os fariseus ouviram que Jesus fazia e batizava mais discípulos que João');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(ainda que Jesus mesmo não batizava, mas sim seus discípulos),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Ele deixou a Judeia, e foi outra vez para a Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'E foi necessário passar por Samaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Veio pois a uma cidade de Samaria, chamada Sicar, junto à propriedade que Jacó deu a seu filho José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'E ali estava a fonte de Jacó. Então Jesus, cansado do caminho, sentou-se assim junto à fonte; era isto quase à hora sexta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Veio uma mulher de Samaria para tirar água; Disse-lhe Jesus: Dá-me de beber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(Porque seus discípulos haviam ido à cidade para a comprar de comer).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Disse-lhe pois a mulher samaritana: Como, sendo tu judeu, me pedes de beber, que sou mulher samaritana? (Porque os judeus não se comunicam com o samaritanos.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Respondeu Jesus, e disse-lhe: Se tu conhecesses o dom de Deus, e quem é o que te diz: Dá-me de beber, tu lhe pedirias, e ele te daria água viva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Disse a mulher: Senhor, tu não tens com que a tirar, e o poço é fundo; de onde pois tens a água viva?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'És tu maior que nosso pai Jacó, que nos deu o poço? E ele mesmo dele bebeu, e seus filhos, e seu gado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus respondeu, e disse-lhe: Todo aquele que beber desta água voltará a ter sede;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Porém aquele que beber da água que eu lhe der, para sempre não terá sede, mas a água que eu lhe der se fará nele fonte de água, que salte para vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Disse-lhe a mulher: Senhor, dá-me desta água, para que eu não tenha mais sede, nem venha aqui para tirar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Disse-lhe Jesus: Vai, chama a teu marido, e vem cá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'A mulher respondeu, e disse: Não tenho marido. Disse-lhe Jesus: Bem disseste: Marido não tenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Porque cinco maridos tiveste, e o que agora tens não é teu marido; isto com verdade disseste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Disse-lhe a mulher: Senhor, vejo que és profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Nossos pais adoraram neste monte, e vós dizeis que em Jerusalém é o lugar onde se deve adorar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Disse-lhe Jesus: Mulher, crê em mim, que a hora vem, quando nem neste monte, nem em Jerusalém, adorareis ao Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vós adorais o que não sabeis; nós adoramos o que sabemos, porque a salvação vem dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Porém a hora vem, e agora é, quando os verdadeiros adoradores adorarão ao Pai em espírito e em verdade; porque também o Pai busca a tais que o adorem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Deus é Espírito, e os que o adoram devem adorá -lo em espírito e em verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Disse-lhe a mulher: Eu sei que o Messias vem (que se chama o Cristo); quando ele vier, todas as coisas nos anunciará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Disse-lhe Jesus: Eu sou o que contigo falo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'E nisto vieram seus discípulos; e maravilharam-se de que falasse com uma mulher; mas ninguém lhe disse: Que perguntas? ou, O que falas com ela?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Deixou, pois, a mulher seu vaso de água, e foi à cidade, e disse ao povo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Vinde, vede um homem que me disse tudo quanto tenho feito; por acaso não é este o Cristo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Saíram, pois, da cidade, e vieram a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'E enquanto isso, os discípulos lhe pediam, dizendo: Rabi, come.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Porém ele lhes disse: Uma comida tenho que comer, que vós não sabeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Diziam, pois, os discípulos uns aos outros: Por acaso alguém lhe trouxe de comer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Disse-lhes Jesus: Minha comida é fazer a vontade daquele que me enviou, e cumprir sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Não dizeis vós, que ainda há quatro meses até que venha a ceifa? Eis que vos digo: Levantai vossos olhos, e vede as terras; porque já estão brancas para a ceifa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'E o que ceifa, recebe recompensa, e junta fruto para vida eterna; para que ambos se alegrem, tanto o que semeia, quanto o que ceifa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Porque nisto é verdadeiro o ditado, que: Um é o que semeia, e outro o que ceifa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Eu vos enviei para ceifar onde vós não trabalhastes; outros trabalharam, e vós entrastes no trabalho deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'E muitos dos samaritanos daquela cidade creram nele pela palavra da mulher, que testemunhava, dizendo: Ele me disse tudo quanto eu tenho feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Vindo pois os samaritanos a ele, suplicaram-lhe que ficasse com eles; e ele ficou ali dois dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'E creram ainda muitos mais pela palavra dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'E diziam à mulher: Já não cremos por teu dito; porque nós mesmos temos o ouvido, e sabemos que verdadeiramente este é o Cristo, o Salvador do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'E depois de dois dias partiu dali, e foi-se para a Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Porque o mesmo Jesus testemunhou que não tem o Profeta honra em sua própria terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Vindo pois para a Galileia, os Galileus o receberam, havendo visto todas as coisas que fizera em Jerusalém no dia da festa, porque também eles foram ao dia da festa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Veio pois Jesus outra vez a Caná da Galileia, onde da água fizera vinho. E estava ali um nobre, cujo filho estava enfermo em Cafarnaum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Ouvindo este que Jesus vinha da Judeia para a Galileia, foi ter com ele, e suplicava-lhe que descesse, e curasse a seu filho, porque já estava à morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Disse-lhe pois Jesus: Se não virdes sinais e milagres não crereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'O nobre lhe disse: Senhor, desce, antes que meu filho morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Disse-lhe Jesus: Vai, teu filho vive. E o homem creu na palavra que Jesus lhe disse, e se foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'E estando ele já descendo, seus servos lhe saíram ao encontro, e lhe anunciaram, dizendo: Teu filho vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Perguntou-lhes pois, a que hora se achara melhor; e disseram-lhe: Ontem às sete horas a febre o deixou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Entendeu pois o pai, que aquela era a mesma hora em que Jesus lhe disse: Teu filho vive. E creu nele, e toda sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Este segundo sinal Jesus voltou a fazer, quando ele veio d a Judeia a Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Depois disto houve uma festa dos judeus, e subiu Jesus para Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'E há em Jerusalém à porta das ovelhas um tanque, que em hebraico se chama Betesda, que tem cinco entradas cobertas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Nestes jazia grande multidão de enfermos, cegos, mancos, e de corpo ressecado, aguardando o movimento da água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Porque um anjo descia de vez em quando ao tanque, e agitava a água; e o primeiro que descia nele, depois do movimento da água, sarava de qualquer enfermidade que tivesse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'E estava ali um certo homem, que havia trinta e oito anos que estava enfermo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Vendo Jesus a este deitado, e sabendo, que já havia muito tempo que ali jazia, disse-lhe: Queres sarar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Respondeu-lhe o enfermo: Senhor, não tenho homem algum para que, quando a água se agita, me ponha no tanque; e enquanto eu venho, outro desce antes de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Disse-lhe Jesus: Levanta-te, toma teu leito, e anda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'E logo aquele homem sarou; e tomou seu leito, e andou. E era Sábado aquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Disseram pois os judeus para aquele que fora curado: É Sábado, não te é lícito levar o leito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Respondeu-lhes ele: Aquele que me curou, esse me disse: Toma teu leito, e anda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Perguntaram-lhe pois: Quem é o homem que te disse: Toma teu leito e anda?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'E o que fora curado, não sabia quem o era, porque Jesus se havia retirado, porque naquele lugar havia uma grande multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Depois Jesus achou-o no Templo, e disse-lhe: Eis que já estás são; não peques mais, para que não te suceda alguma coisa pior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Aquele homem foi anunciar aos judeus que Jesus era o que o curara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'E por isso os judeus perseguiam Jesus e procuravam matá-lo, porque ele fazia estas coisas no sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'E Jesus lhes respondeu: Meu Pai até agora trabalha, e eu também trabalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Por isto ainda mais procuravam os Judeus matá-lo, porque não só quebrava o sábado, mas também dizia que Deus era seu próprio Pai, fazendo-se igual a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Respondeu pois Jesus, e disse-lhes: Em verdade, em verdade vos digo, que não pode o Filho fazer coisa alguma de si mesmo, a não ser aquilo que ele veja o Pai fazer; porque todas as coisas que ele faz, semelhantemente o Filho também as faz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Porque o Pai ama ao Filho, e todas as coisas que faz lhe mostra; e maiores obras que estas lhe mostrará, para que vós vos maravilheis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Porque como o Pai aos mortos ressuscita e vivifica, assim também o Filho aos que quer vivifica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Porque também o Pai a ninguém julga, mas todo o juízo deu ao Filho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Para que todos honrem ao Filho, como honram ao Pai. Quem não honra ao Filho, não honra ao Pai que o enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Em verdade, em verdade vos digo, que quem ouve minha palavra, e crê ao que me enviou, tem vida eterna, e não virá em condenação, mas passou da morte para a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Em verdade, em verdade vos digo, que a hora vem, e agora é, quando os mortos ouvirão a voz do Filho de Deus, e aos que ao ouvirem, viverão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Porque como o Pai tem vida em si mesmo, assim deu também ao Filho que tivesse vida em si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'E deu-lhe poder, para fazer juízo, porque é o Filho do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Não vos maravilheis disto; porque a hora vem, em que todos os que estão nos sepulcros ouvirão sua voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'E sairão os que fizeram bem, para a ressurreição de vida; e os que fizeram mal, à ressurreição de condenação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Não posso eu de mim mesmo fazer alguma coisa. Como ouço, assim julgo; e meu juízo é justo; porque não busco minha vontade, mas a vontade do Pai que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Se eu testemunho de mim mesmo, meu testemunho não é verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Outro há que testemunha de mim, e sei que o testemunho, que testemunha de mim, é verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vós enviastes mensageiros a João, e ele deu testemunho à verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Porém eu não recebo testemunho humano; mas digo isto para que sejais salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Ele era uma lâmpada ardente e brilhante; e vós quisestes por um pouco de tempo alegrar em sua luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Mas eu tenho maior testemunho que o de João; porque as obras que o Pai me deu que cumprisse, as mesmas obras que eu faço, testemunham de mim que o Pai me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'E o Pai que me enviou, ele mesmo testemunhou de mim. Nunca ouvistes sua voz, nem vistes sua aparência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'E não tendes sua palavra permanecendo em vós; porque ao que ele enviou, a esse vós não credes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Investigai as Escrituras; porque vós pensais que nelas tendes a vida eterna, e elas são as que de mim testemunham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'E não quereis vir a mim, para que tenhais vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Não recebo honra humana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Mas eu bem vos conheço que não tendes o amor de Deus em vós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Eu vim em nome de meu Pai, e vós não me aceitais; se outro vier em seu próprio nome, a esse aceitareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Como podeis vós crer, se tomais honra uns dos outros, e não buscais a honra que vem somente de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Não penseis que eu vos tenha de acusar para com o Pai; o que vos acusa é Moisés, em quem vós esperais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Porque se vós crêsseis em Moisés, também a mim me creríeis; porque de mim ele escreveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Mas se não credes em seus escritos, como crereis em minhas palavras?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Depois disto Jesus partiu para a outro lado do mar da Galileia, que é o de Tibérias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'E uma grande multidão o seguia, porque viam seus sinais que ele fazia nos enfermos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'E subiu Jesus ao monte, e sentou-se ali com seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'E já a Páscoa, a festa dos judeus, estava perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Levantando pois Jesus os olhos, e vendo que uma grande multidão vinha a ele, disse a Filipe: De onde comparemos pães, para que estes comam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, '(Mas ele disse isto para o testar; pois ele bem sabia o que havia de fazer.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Respondeu-lhe Filipe: Duzentos dinheiros de pão não lhes bastarão, para que cada um deles tome um pouco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Disse-lhe um de seus discípulos, André, o irmão de Simão Pedro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Um menino está aqui que tem cinco pães de cevada e dois peixinhos; mas que é isto entre tantos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'E disse Jesus: Fazei sentar as pessoas; e havia muita erva naquele lugar. Sentaram-se, pois, os homens, em número de cinco mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'E tomou Jesus os pães, e havendo dado graças, repartiu-os aos discípulos, e os discípulos aos que estavam sentados, semelhantemente também dos peixes, quanto queriam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'E quando já estiveram fartos, disse ele a seus discípulos: Recolhei os pedaços que sobraram, para que nada se perca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Então eles os recolheram, e encheram doze cestos de pedaços dos cinco pães de cevada, que sobraram aos que tinham comido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Vendo, pois, aquelas pessoas o sinal que Jesus fizera, disseram: Este é verdadeiramente o Profeta que havia de vir ao mundo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Sabendo pois Jesus que viriam, e o tomariam, para fazê-lo rei, voltou a se retirar sozinho ao monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'E quando veio o entardecer, seus discípulos desceram para o mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'E entrando no barco, vieram do outro lado do mar para Cafarnaum. E era já escuro, e Jesus ainda não tinha vindo a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'E o mar se levantou, porque um grande vento soprava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'E havendo já navegado quase vinte e cinco, ou trinta estádios, viram a Jesus andando sobre o mar, e se aproximando do barco; e temeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mas ele lhes disse: Sou eu, não temais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Eles, então, o receberam com agrado no barco; e logo o barco chegou à terra para onde iam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'O dia seguinte, vendo a multidão, que estava do outro lado do mar, que não havia ali mais que um barquinho, em que seus discípulos entraram; e que Jesus não entrara com seus discípulos naquele barquinho, mas que seus discípulos sós se haviam ido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(Porém outros barquinhos vieram de Tibérias, perto do lugar onde comeram o pão, havendo o Senhor dado graças.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Vendo pois a multidão que Jesus não estava ali, nem seus discípulos, entraram eles também nos barcos, e vieram a Cafarnaum em busca de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'E achando-o do outro lado do mar, disseram: Rabi, quando chegaste aqui?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Respondeu-lhes Jesus, e disse: Em verdade, em verdade vos digo, que me buscais, não pelos sinais que vistes, mas pelo pão que comestes, e vos fartastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Trabalhai não pela comida que perece, mas sim pela comida que permanece para vida eterna, a qual o Filho do homem vos dará; porque Deus Pai a este selou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Disseram-lhe pois: Que faremos, para trabalharmos as obras de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Respondeu Jesus, e disse-lhes: Esta é a obra de Deus: que creiais naquele que ele enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Disseram-lhe pois: Que sinal, pois, fazes tu para que o vejamos, e em ti creiamos? O que tu operas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nossos pais comeram o maná no deserto, como está escrito: Pão do céu ele lhes deu para comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Então Jesus lhes disse: Em verdade, em verdade vos digo, que Moisés não vos deu o pão do céu; mas meu Pai vos dá o verdadeiro pão do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Porque o pão de Deus é aquele que desce do céu e dá vida ao mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Disseram-lhe pois: Senhor, dá-nos sempre d este pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'E Jesus lhes disse: Eu sou o pão da vida; quem vem a mim de maneira nenhuma terá fome, e quem crê em mim nunca terá sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Mas já tenho vos dito que também me vistes, e não credes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Tudo o que o Pai me dá virá a mim; e ao que vem a mim, em maneira nenhuma o lançarei fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Porque eu desci do céu, não para fazer minha vontade, mas sim a vontade daquele que me enviou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'E esta é a vontade do Pai, que me enviou: que de tudo quanto me deu, nada perca, mas que eu o ressuscite no último dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'E esta é a vontade daquele que me enviou, que todo aquele que vê ao Filho, e nele crê, tenha a vida eterna; e eu o ressuscitarei no último dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Então os judeus murmuravam dele, porque ele tinha dito: Eu sou o pão que desceu do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'E diziam: Não é este Jesus o filho de José, cujos pai e mãe nós conhecemos? Como, pois, ele diz: Desci do céu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Respondeu, então, Jesus, e disse-lhes: Não murmureis entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Ninguém pode vir a mim se o Pai que me enviou não o trouxer; e eu o ressuscitarei no último dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Escrito está nos profetas: E todos serão ensinados por Deus. Portanto todo aquele que do Pai ouviu e aprendeu, esse vem a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Não que alguém tenha visto ao Pai, a não ser aquele que é de Deus; este tem visto ao Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Em verdade, em verdade vos digo, que aquele que crê em mim tem vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Eu sou o pão da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vossos pais comeram o maná no deserto, e morreram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Este é o pão que desceu do céu, para que o ser humano coma dele e não morra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Eu sou o pão vivo, que desceu do céu; se alguém comer deste pão, para sempre viverá. E o pão que eu darei é minha carne, a qual darei pela vida do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Discutiam, pois, os Judeus entre si, dizendo: Como este pode nos dar sua carne para comer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jesus, então, lhes disse: Em verdade, em verdade vos digo, que se não comerdes a carne do Filho do homem e beberdes seu sangue, não tereis vida em vós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Quem come minha carne e bebe meu sangue tem vida eterna, e eu o ressuscitarei no último dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Porque minha carne verdadeiramente é comida; e meu sangue verdadeiramente é bebida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Quem come minha carne e bebe meu sangue, em mim permanece, e eu nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Como o Pai vivo me enviou, e eu vivo pelo Pai, assim quem come a mim também por mim viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Este é o pão que desceu do céu. Não como vossos pais, que comeram o maná e morreram; quem comer este pão viverá para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Estas coisas ele disse na sinagoga, ensinando em Cafarnaum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Muitos pois de seus discípulos, ao ouvirem isto, disseram: Dura é esta palavra; quem a pode ouvir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Sabendo pois Jesus em si mesmo, que seus discípulos murmuravam disto, disse-lhes: Isto vos ofende?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Que seria pois, se vísseis ao Filho do homem subir aonde estava primeiro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'O Espírito é o que vivifica, a carne para nada aproveita; as palavras que eu vos digo são espírito e são vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Mas há alguns de vós que não creem.Porque Jesus já sabia desde o princípio quem eram os que não criam, e quem era o que o entregaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'E dizia: Por isso tenho vos dito que ninguém pode vir a mim, se não lhe for concedido por meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Desde então muitos de seus discípulos voltaram atrás, e já não andavam com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Disse, então, Jesus aos doze: Por acaso também vós quereis ir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Respondeu-lhe pois Simão Pedro: Senhor, a quem iremos? Tu tens as palavras da vida eterna;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'E nós cremos e conhecemos que tu és o Cristo, o Filho do Deus vivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jesus lhes respondeu: Por acaso não fui eu que vos escolhi, os doze? Porém um de vós é um diabo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'E ele dizia isto de Judas de Simão Iscariotes; porque ele o entregaria, o qual era um dos doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'E depois disto andava Jesus na Galileia; e já não queria andar na Judeia, porque os judeus procuravam matá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'E já estava perto a festa dos tabernáculos dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Disseram-lhe pois seus irmãos: Parti daqui, e vai-te para a Judeia, para que também teus discípulos vejam as tuas obras que fazes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Pois ninguém que procura ser conhecido faz coisa alguma em oculto. Se fazes estas coisas, manifesta-te ao mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Porque nem mesmo os seus irmãos criam nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Então Jesus lhes disse: Meu tempo ainda não é chegado; mas vosso tempo sempre está pronto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'O mundo não pode vos odiar, mas a mim me odeia, porque dele testemunho que suas obras são más.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Subi vós para esta festa; eu não subo ainda a esta festa, porque ainda meu tempo não é cumprido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'E havendo-lhes dito isto, ficou na Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Mas havendo seus irmãos já subido, então subiu ele também à festa, não abertamente, mas como em oculto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Buscavam-no pois os judeus na festa, e diziam: Onde ele está?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'E havia grande murmuração dele nas multidões. Alguns diziam: Ele é Bom;e outros diziam: Não; ele, porém, engana a multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Todavia ninguém falava dele abertamente, com medo dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Porém no meio da festa subiu Jesus ao Templo, e ensinava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'E maravilhavam-se os Judeus, dizendo: Como este sabe as Escrituras, não as havendo aprendido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Respondeu-lhes Jesus, e disse: Minha doutrina não é minha, mas sim daquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Se alguém quiser fazer sua vontade, da doutrina conhecerá, se é de Deus, ou se eu falo de mim mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Quem fala de si mesmo busca sua própria honra; mas quem busca a honra daquele que o enviou, esse é verdadeiro, e não há nele injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Não vos deu Moisés a Lei? Mas ninguém de vós cumpre a Lei. Por que procurais me matar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Respondeu a multidão, e disse: Tens demônio; quem procura te matar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Respondeu Jesus, e disse-lhes: Uma obra fiz, e todos vos maravilhais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Por isso Moisés vos deu a circuncisão (não porque seja de Moisés, mas dois pais) e no sábado circuncidais ao homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Se o homem recebe a circuncisão no sábado, para que a Lei de Moisés não seja quebrada, irritai-vos comigo, porque no sábado curei por completo um homem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Não julgueis segundo a aparência, mas julgai juízo justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Diziam, pois, alguns dos de Jerusalém: Não é este ao que procuram matar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'E eis que ele fala livremente, e nada lhe dizem; por acaso é verdade que os chefes sabem que este realmente é o Cristo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Mas este bem sabemos de onde é: Porém quando vier o Cristo, ninguém saberá de onde é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Exclamava pois Jesus no Templo, ensinando, e dizendo: E a mim me conheceis, e sabeis de onde sou; e eu não vim de mim mesmo; mas aquele que me enviou é verdadeiro, ao qual vós não conheceis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Porém eu o conheço, porque dele sou, e ele me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Procuravam pois prendê-lo, mas ninguém pôs a mão nele, porque sua hora ainda não era vinda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'E muitos da multidão creram nele, e diziam: Quando o Cristo vier, fará ainda mais sinais do que os que este tem feito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Ouviram os fariseus que a multidão murmurava estas coisas sobre ele; e os fariseus e os chefes dos Sacerdotes mandaram oficiais para prendê-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Disse-lhes pois Jesus: Ainda um pouco de tempo estou convosco, e então me irei para aquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Vós me buscareis, mas não me achareis; e onde eu estou vós não podeis vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Disseram, pois, os judeus uns aos outros: Para onde este se irá, que não o acharemos? Por acaso ele irá aos dispersos entre os gregos, e a ensinar aos gregos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Que palavra é esta que disse: Vós me buscareis, mas não me achareis; e onde eu estou vós não podeis vir?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'E no último e grande dia da festa se pôs Jesus em pé, e exclamou, dizendo: Se alguém tem sede, venha a mim, e beba.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Quem crê em mim, como diz a Escritura, rios de água viva correrão do interior de seu corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '(E ele disse isto do Espírito que receberiam aqueles que nele cressem; pois o Espírito Santo ainda não era vindo,porque Jesus ainda não havia sido glorificado).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Então muitos da multidão, ouvindo esta palavra, diziam: Verdadeiramente este é o Profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Outros diziam: Este é o Cristo; e outros diziam: Por acaso vem o Cristo da Galileia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Não diz a Escritura que o Cristo virá da semente de Davi, e da aldeia de Belém, de onde era Davi?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Por isso havia divisão de opiniões na multidão por causa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'E alguns deles queriam prendê-lo, mas ninguém pôs a mão nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Vieram pois os oficiais dos sacerdotes e fariseus; e eles lhes disseram: Por que não o trouxestes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Os oficiais responderam: Ninguém jamais falou assim como este homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Responderam-lhes, pois, os fariseus: Estais vós também enganados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Por acaso algum dos chefes ou dos fariseus creu nele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Mas esta multidão, que não sabe a Lei, maldita é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Disse-lhes Nicodemos, o que viera a ele de noite, que era um deles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Por acaso nossa Lei julga ao homem sem primeiro o ouvir, e entender o que faz?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Responderam eles, e disseram: És tu também da Galileia? Pesquisa, e vê que nenhum profeta se levantou da Galileia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'E cada um foi para sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Porém Jesus foi para o monte das Oliveiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'E pela manhã cedo voltou ao Templo, e todo o povo veio a ele; e sentando-se, ensinava-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'E trouxeram-lhe os escribas e fariseus uma mulher tomada em adultério;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'E pondo-a no meio, disseram-lhe: Mestre, esta mulher foi tomada no momento em que estava adulterando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'E na Lei nos mandou Moisés, que as tais sejam apedrejadas; tu pois que dizes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'E isto diziam eles, tentando-o, para que tivessem de que o acusar. Mas inclinando-se Jesus, escrevia com o dedo na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'E enquanto continuavam lhe perguntando, ele se endireitou, e disse-lhes: Aquele de vós que está sem pecado, seja o primeiro que atire pedra contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'E voltando a se inclinar, escrevia na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Porém ouvindo eles isto, e acusados pela própria consciência, saíram um a um, começando dos mais velhos até os últimos; e Jesus ficou só, e a mulher, que estava no meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'E endireitando-se Jesus, e não vendo a ninguém além da mulher, disse-lhe: Mulher, onde estão aqueles teus acusadores? Ninguém te condenou?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'E disse ela: Ninguém, Senhor. E disse-lhe Jesus: Nem eu também te condeno; vai, e não peques mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Falou-lhes pois Jesus outra vez, dizendo: Eu sou a luz do mundo; quem me seguir não andará em trevas, mas terá luz de vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Disseram-lhe pois os Fariseus: Tu testemunhas de ti mesmo; teu testemunho não é verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Respondeu Jesus, e disse-lhes: Ainda que eu testemunho de mim mesmo, meu testemunho é verdadeiro; porque sei de onde vim, e para onde vou; porém vós não sabeis, de onde venho, nem para onde vou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vós julgais segundo a carne, eu não julgo a ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'E se eu também julgo, meu juízo é verdadeiro; porque não sou eu só, mas eu, e o Pai que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'E também em vossa Lei está escrito que o testemunho de duas pessoas é verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Eu sou o que testemunho de mim mesmo; e também de mim testemunha o Pai, que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Disseram-lhe pois: Onde está teu Pai? Respondeu Jesus: Nem a mim me conheceis, nem a meu Pai; se vós a mim conhecêsseis, também conheceríeis a meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Estas palavras falou Jesus junto à arca do tesouro, ensinando no Templo; e ninguém o prendeu, porque sua hora ainda não era chegada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Disse-lhes pois Jesus outra vez: Eu me vou, e me buscareis, e morrereis em vosso pecado; para onde eu vou vós não podeis vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Diziam, pois, os Judeus: Ele, por acaso, matará a si mesmo? Pois diz: Para onde eu vou vós não podeis vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'E ele lhes dizia: Vós sois de baixo, eu sou de cima; vós sois deste mundo, eu não sou deste mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Por isso eu vos disse, que morrereis em vossos pecados; porque se não credes que eu sou, morrereis em vossos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Disseram-lhe pois: Quem és tu? Jesus lhes disse: Sou o mesmo que desde o princípio tenho vos dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Muitas coisas tenho que dizer e julgar de vós; mas verdadeiro é aquele que me enviou; e eu, o que dele tenho ouvido, isso falo ao mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Mas não entenderam que ele estava lhes falando do Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jesus, então, lhes disse: Quando levantardes ao Filho do homem, então entendereis que eu sou, e que nada faço de mim mesmo; mas isto digo, como meu Pai me ensinou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'E aquele que me enviou está comigo. O Pai não me tem deixado só, porque sempre faço o que lhe agrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Falando ele estas coisas, muitos creram nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Dizia, pois, Jesus aos judeus que criam nele: Se vós permanecerdes em minha palavra, verdadeiramente sereis meus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'E conhecereis a verdade, e a verdade vos libertará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Responderam-lhe: Somos descendência de Abraão, e nunca servimos a ninguém; como, pois, dizes: Sereis livres?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Respondeu-lhes Jesus: Em verdade, em verdade vos digo, que todo aquele que comete pecado é servo do pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'E o servo não fica em casa para sempre; o Filho fica para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Portanto, se o Filho vos libertar, verdadeiramente sereis livres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Bem sei que sois descendência de Abraão; porém procurais matar-me, porque minha palavra não encontra lugar em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Eu, o que vi junto a meu Pai, isso falo; e vós, o que também vistes junto a vosso pai isso fazeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Responderam, e lhe disseram: Nosso pai é Abraão. Disse-lhes Jesus: Se fôsseis filhos de Abraão, faríeis as obras de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Porém agora procurais matar a mim, o homem que tenho vos falado a verdade que de Deus tenho ouvido; Abraão não fez isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vós fazeis as obras de vosso pai.Disseram-lhe pois: Nós não somos nascidos de pecado sexual; nós temos um Pai: Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Disse-lhes pois Jesus: Se Deus fosse vosso Pai, verdadeiramente me amaríeis; porque eu saí e venho de Deus; pois não vim de mim mesmo, porém ele me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Por que não entendeis meu discurso? Porque não podeis ouvir minha palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vós sois filhos de vosso pai, o Diabo, e quereis fazer os desejos de vosso pai; ele foi homicida desde o princípio, e não permaneceu na verdade, porque nele não há verdade; quando fala mentira, fala do seu próprio; porque é mentiroso, e pai da mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Porém a mim, porque vos digo a verdade, não credes em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Quem de vós me convence de pecado? E se digo a verdade, por que não credes em mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Quem é de Deus, ouve as palavras de Deus; portanto vós não as ouvis porque não sois de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Responderam, pois, os Judeus, e lhe disseram: Nós não dizemos com razão que és samaritano, e tens o demônio?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Respondeu Jesus: Eu não tenho demônio, antes honro a meu Pai; e vós me desonrais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Mas eu não busco minha glória; há quem a busque, e julgue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Em verdade, em verdade vos digo, que se alguém guardar minha palavra, jamais verá a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Disseram-lhe pois os Judeus: Agora conhecemos que tens o demônio. Abraão e os profetas morreram; e tu dizes: Se alguém guardar minha palavra, jamais experimentará a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'És tu maior que nosso pai Abraão, que morreu? Os profetas também morreram. Quem tu dizes ser?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Respondeu Jesus: Se eu me glorifico a mim mesmo, minha glória é nada; meu Pai, o qual vós dizeis ser vosso Deus, ele é o que me glorifica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'E vós não o conheceis, mas eu o conheço; e se disser que não o conheço, serei mentiroso como vós; mas eu o conheço, e guardo sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraão, vosso pai, saltou de alegria por ver o meu dia; ele viu, e se alegrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Disseram-lhe, pois. os Judeus: Ainda não tens cinquenta anos, e viste a Abraão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesus lhes disse: Em verdade, em verdade vos digo, que antes que Abraão fosse, eu sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Então tomaram pedras para atirarem nele. Mas Jesus se escondeu, e saiu do Templo, atravessando por meio deles, e assim se foi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'E indo Jesus passando, viu a um homem cego desde o nascimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'E seus discípulos lhe perguntaram, dizendo: Rabi, quem pecou? Este, ou seus pais, para que nascesse cego?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Respondeu Jesus: Nem este pecou, nem seus pais; mas sim para que as obras de Deus nele se manifestem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'A mim me convém trabalhar as obras daquele que me enviou, enquanto é dia; a noite vem, quando ninguém pode trabalhar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Enquanto estiver no mundo, eu sou a luz do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Dito isto, cuspiu em terra, e fez lama do cuspe, e untou com aquela lama os olhos do cego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'E disse-lhe: Vai, lava-te no tanque de Siloé (que se traduz Enviado). Foi pois, e lavou-se; e voltou vendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Então os vizinhos, e os que de antes o viram que era cego, diziam: Não é este aquele que estava sentado, e mendigava?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Outros diziam: É este. E outros: Parece-se com ele. Ele dizia: Sou eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Então lhe diziam: Como teus olhos se abriram?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Respondeu ele, e disse: Aquele homem chamado Jesus fez lama, untou meus olhos, e me disse: Vai ao tanque de Siloé, e lava-te. E fui, e me lavei, e vi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Disseram-lhe, pois: Onde ele está? Disse ele: Não sei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Levaram aos Fariseus o ex-cego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'E era sábado, quando Jesus fez a lama, e abriu os olhos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Então voltaram também os Fariseus a perguntar-lhe como vira, e ele lhes disse: Pôs lama sobre os meus olhos, e me lavei, e vejo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Então que alguns dos Fariseus diziam: Este homem não é de Deus, pois não guarda o sábado. Outros diziam: Como pode um homem pecador fazer tais sinais? E havia divisão entre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Voltaram a dizer ao cego: Tu que dizes dele, que abriu teus olhos? E ele disse: Que é profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Portanto os judeus não criam nele, de que houvesse sido cego, e passasse a ver, até que chamaram aos pais dos que passou a ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'E perguntaram-lhes, dizendo: É este vosso filho, aquele que dizeis que nasceu cego? Como pois agora vê?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Responderam-lhes seus pais, e disseram: Sabemos que este é nosso filho, e que nasceu cego;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Mas como agora ele vê, não sabemos; ou, quem lhe abriu os olhos, não sabemos; ele tem idade suficiente,perguntai a ele, ele falará por si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Isto disseram seus pais, pois temiam aos judeus. Porque já os Judeus tinham combinado, que se alguém confessasse que ele era o Cristo, seria expulso da sinagoga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Por isso disseram seus pais: Ele tem idade suficiente,perguntai a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Chamaram pois segunda vez ao homem que era cego, e disseram-lhe: Dá glória a Deus; nós sabemos que esse homem é pecador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Respondeu pois ele, e disse: Se é pecador, não o sei; uma coisa sei, que havendo eu sido cego, agora vejo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'E voltaram a lhe dizer: O que ele te fez? Como ele abriu os teus olhos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Ele lhes respondeu: Eu já vos disse, e ainda não o ouvistes; para que quereis voltar a ouvir? Por acaso vós também quereis ser discípulos dele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Então lhe insultaram, e disseram: Tu sejas discípulo dele; mas nós somos discípulos de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Bem sabemos nós que Deus falou a Moisés; mas este nem de onde é, não sabemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Aquele homem respondeu, e disse-lhes: Porque nisto está a maravilha: que vós não sabeis de onde ele é; e a mim abriu meus olhos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'E bem sabemos que Deus não dá ouvidos aos pecadores; mas se alguém é temente a Deus, e faz sua vontade, a este dá ouvidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Desde o princípio dos tempos nunca se ouviu de que alguém que tenha aberto os olhos de um que tenha nascido cego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Se este não fosse vindo de Deus, nada poderia fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Eles responderam, e lhe disseram: Tu és todo nascido em pecados, e nos ensina? E o lançaram fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Ouviu Jesus que o haviam lançado fora, e achando-o, disse-lhe: Crês tu no Filho de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Respondeu ele, e disse: Quem é, Senhor, para que nele creia?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'E disse-lhe Jesus: Tu já o tens visto; e este é o que fala contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'E ele disse: Creio, Senhor; E adorou-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'E disse Jesus: Eu vim a este mundo para juízo, para os que não veem, vejam; e os que veem, ceguem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'E ouviram isto alguns dos fariseus, que estavam com ele; e lhe disseram: Também nós somos cegos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Disse-lhes Jesus: Se fôsseis cegos, não teríeis pecado; mas agora dizeis: Vemos; portanto vosso pecado permanece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Em verdade, em verdade vos digo, que aquele que no curral das ovelhas não entra pela porta, mas sobe por outra parte, é ladrão, e assaltante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Mas aquele que entra pela porta é o pastor de ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'A este o porteiro abre, e as ovelhas ouvem sua voz, e a suas ovelhas chama nome por nome, e as leva fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'E quando tira fora suas ovelhas, vai adiante delas, e as ovelhas o seguem, porque conhecem sua voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Mas ao estranho em maneira nenhuma seguirão, ao invés disso dele fugirão; porque não conhecem a voz dos estranhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Esta parábola Jesus lhes disse; porém eles não entenderam que era o que lhes falava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Voltou pois Jesus a lhes dizer: Em verdade, em verdade vos digo, que sou a porta das ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Todos quantos vieram antes de mim, são ladrões e assaltantes; mas as ovelhas não os ouviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Eu sou a porta; se alguém entrar por mim, será salvo; e entrará, e sairá, e achará pasto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'O ladrão não vem para outra coisa,a não ser roubar, e matar, e destruir; eu vim para que tenham vida, e a tenham em abundância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Eu sou o bom Pastor; o bom Pastor dá sua vida pelas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Mas o empregado, e que não é o pastor, as cujas ovelhas não são próprias, vê o lobo vir, e deixa as ovelhas, e foge; o lobo as arranca, e dispersa as ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'E o empregado foge, porque é empregado, e não tem cuidado das ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Eu sou o bom Pastor, e as minhas conheço, e das minhas sou conhecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Como o Pai me conhece, assim também eu conheço ao Pai; e ponho minha vida pelas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Ainda tenho outras ovelhas que não são deste curral; a estas também me convém trazer, e ouvirão minha voz, e haverá um rebanho, e um pastor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Por isso me ama o Pai, porque ponho minha vida para tomá-la de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Ninguém a tira de mim, mas eu de mim mesmo a ponho; poder tenho para a pôr, e poder tenho para tomá-la de volta. Este mandamento recebi de meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Voltou pois a haver divisão entre os Judeus, por causa destas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'E muitos deles diziam: Ele tem demônio, e está fora de si; para que o ouvis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Diziam outros: Estas palavras não são de endemoninhado; por acaso pode um demônio abrir os olhos dos cegos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'E era a festa da renovação do Templo em Jerusalém, e era inverno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'E andava Jesus passeando no Templo, na entrada de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Rodearam-no, então, os Judeus, e lhe disseram: Até quando farás nossa alma em dúvida? Se tu és o Cristo, dize-nos abertamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Respondeu-lhes Jesus: Já vos tenho dito, e não credes. As obras que eu faço em nome de meu Pai, essas testemunham de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Mas vós não credes, porque não sois de minhas ovelhas, como já vos tenho dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Minhas ovelhas ouvem minha voz, e eu as conheço, e elas me seguem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'E eu lhes dou a vida eterna, e para sempre não perecerão, e ninguém as arrancará de minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Meu Pai, que as deu para mim, é maior que todos; e ninguém pode arrancá-las da mão de meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Eu e o Pai somos um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Voltaram pois os Judeus a tomar pedras para o apedrejarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Respondeu-lhes Jesus: Muitas boas obras de meu Pai vos tenho mostrado; por qual obra destas me apedrejais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Responderam-lhe os judeus dizendo: Por boa obra não te apedrejamos, mas pela blasfêmia; e porque sendo tu homem, a ti mesmo te fazes Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Respondeu-lhes Jesus: Não está escrito em vossa Lei: Eu disse: Sois deuses?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Pois se a Lei chamou deuses a aqueles, para quem a palavra de Deus foi feita, (e a Escritura não pode ser quebrada);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'A mim,a quem o Pai santificou, e ao mundo enviou, dizeis vós: Blasfemas; porque disse: Sou Filho de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Se não faço as obras de meu Pai, não creiais em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Porém se eu as faço, e não credes em mim, crede nas obras; para que conheçais e creiais que o Pai está em mim, e eu nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Então procuravam outra vez prendê-lo; e ele saiu de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'E voltou a ir para o outro lado do Jordão, ao lugar onde João primeiro batizava; e ficou ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'E muitos vinham a ele, e diziam: Em verdade que nenhum sinal fez João; mas tudo quanto João disse deste era verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'E muitos ali creram nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'E estava doente um certo Lázaro, de Betânia, a aldeia de Maria e de sua irmã Marta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(E era Maria a que ungiu ao Senhor com o óleo, e com seus cabelos lhe limpou os pés; a que cujo irmão Lázaro era o que estava doente).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Enviaram pois suas irmãs uma mensagem a ele, dizendo: Senhor, eis que aquele a quem tu amas está doente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'E ouvindo Jesus, disse: Esta doença não é para morte, mas para glória de Deus; para que o Filho de Deus seja por ela glorificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'E Jesus amava a Marta, e a sua irmã, e a Lázaro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Quando, pois, ele ouviu que estava doente, ficou ainda dois dias no lugar onde estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Então depois disto voltou a dizer aos discípulos: Vamos outra vez à Judeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Disseram-lhe os discípulos: Rabi, ainda agora os Judeus procuravam te apedrejar; e tu voltas novamente para lá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Respondeu Jesus: Não há doze horas no dia? Se alguém anda de dia, não tropeça, porque vê a luz deste mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Mas se alguém anda de noite, tropeça; porque nele não há luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Ele falou estas coisas; e depois disto, disse-lhes: Lázaro, nosso amigo, dorme; mas vou para despertá-lo do sono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Disseram pois seus discípulos: Senhor, se ele dorme, será salvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Mas Jesus dizia isto de sua morte; porém eles pensavam que falava do repouso do sono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Então pois lhes disse Jesus claramente: Lázaro está morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'E me alegro, por causa de vós, que eu não estivesse lá, para que creiais; porém vamos até ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Disse pois Tomé, chamado o Dídimo, aos colegas discípulos: Vamos nós também, para que com ele morramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Vindo pois Jesus, encontrou que já havia quatro dias que estava na sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, '(E Betânia era como quase quinze estádios de Jerusalém).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'E muitos dos judeus tinham vindo até Marta e Maria, para consolá-las por seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Ouvindo pois Marta que Jesus vinha, saiu-lhe ao encontro; mas Maria ficou sentada em casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Disse pois Marta a Jesus: Senhor, se tu estivesses aqui, meu irmão não teria morrido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Porém também sei agora, que tudo quanto pedires a Deus, Deus o dará a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Disse-lhe Jesus: Teu irmão ressuscitará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta lhe disse: Eu sei que ele ressuscitará, na ressurreição, no último dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Disse-lhe Jesus: Eu sou a ressurreição, e a vida; quem crê em mim, ainda que esteja morto, viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'E todo aquele que vive, e crê em mim, para sempre não morrerá. Crês nisto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Disse-lhe ela: Sim, Senhor; já cri que tu és o Cristo, o Filho de Deus, que viria ao mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'E dito isto, ela se foi, e chamou em segredo a Maria, sua irmã, dizendo: Aqui está o Mestre, e ele te chama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Ouvindo ela isto,logo se levantou, e foi até ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '(Porque Jesus ainda não havia chegado à aldeia; mas estava no lugar onde Marta lhe saíra ao encontro).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Vendo pois os judeus que com ela estavam em casa, e a consolavam, que Maria com pressa se levantara, e saíra, seguiram-na, dizendo: Ela vai para a sepultura, para chorar lá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Vindo pois Maria aonde Jesus estava, e vendo-o, caiu a seus pés, dizendo-lhe: Senhor, se tu estivesses aqui, meu irmão não teria morrido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Quando Jesus a viu chorar, e aos judeus, que vinham chorando com ela, comoveu-se em espírito, e ficou perturbado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'E disse: Onde o pusestes? Disseram-lhe: Senhor, vem, e vê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jesus chorou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Disseram pois os Judeus: Vede como ele o amava!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'E alguns deles disseram: Não podia este, que abriu os olhos ao cego, ter feito também que este não morresse?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Comovendo-se pois Jesus outra vez em si mesmo, veio à sepultura; e era esta uma caverna, e estava uma pedra posta sobre ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Disse Jesus: Tirai a pedra. Marta, a irmã do morto, disse-lhe: Senhor, já cheira mal, porque já é de quatro dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jesus disse-lhe: Não te disse, que se creres, verás a glória de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Tiraram, pois, a pedra de onde o morto jazia. E Jesus levantou os olhos para cima, e disse: Pai, graças te dou, porque me tens ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Porém eu bem sabia que sempre me ouves; mas por causa da multidão, que está ao redor, assim disse; para que creiam que tu me enviaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'E havendo dito isto, clamou com grande voz: Lázaro, sai fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'E o que estava morto saiu, com as mãos e os pés atados, e seu rosto envolto em um lenço. Disse-lhes Jesus: Desatai-o, e deixai-o ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Pelo que, muitos dos Judeus, que tinham vindo a Maria, e haviam visto o que Jesus fizera, creram nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Mas alguns deles foram aos fariseus, e lhes disseram o que Jesus havia feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Então os sacerdotes e os fariseus juntaram o conselho, e disseram: Que faremos? Porque este homem faz muitos sinais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Se assim o deixamos, todos crerão nele, e virão os romanos, e nos tomarão tanto o lugar quanto a nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'E Caifás, um deles, que era sumo sacerdote daquele ano, lhes disse: Vós nada sabeis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Nem considerais que nos convém, que um homem morra pelo povo, e toda a nação não pereça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'E ele não disse isto de si mesmo; mas que, como era o sumo sacerdote daquele ano, profetizou que Jesus morreria pelo povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'E não somente por aquele povo, mas também para que juntasse em um aos filhos de Deus, que estavam dispersos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Então desde aquele dia se aconselhavam juntos para o matarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'De maneira que Jesus já não andava mais abertamente entre os judeus, mas foi-se dali para a terra junto ao deserto, a uma cidade chamada Efraim; e ali andava com seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'E estava perto a páscoa dos judeus, e muitos daquela terra subiram a Jerusalém antes da páscoa, para se purificarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Buscavam pois a Jesus, e diziam uns aos outros estando no Templo: Que vos parece? Que ele não virá à festa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'E os sacerdotes e os fariseus tinham dado ordem de que, se alguém soubesse onde ele estava, o denunciasse, para que o pudessem prender.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Veio, pois, Jesus seis dias antes da páscoa a Betânia, onde estava Lázaro, o que havia morrido, a quem ressuscitara dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Fizeram-lhe, pois, ali uma ceia, e Marta servia; e Lázaro era um dos que juntamente com ele estavam sentados à mesa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Tomando então Maria um arrátel de óleo perfumado de nardo puro, de muito preço, ungiu os pés de Jesus, e limpou os pés dele com seus cabelos; e encheu-se a casa do cheiro do óleo perfumado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Então disse Judas de Simão Iscariotes, um de seus discípulos, o que o trairia:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Por que se não vendeu este óleo perfumado por trezentos dinheiros, e se deu aos pobres?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'E isto disse ele, não pelo cuidado que tivesse dos pobres; mas porque era ladrão, e tinha a bolsa, e trazia o que se lançava nela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Disse pois Jesus: Deixa-a; para o dia de meu sepultamento guardou isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Porque aos pobres sempre os tendes convosco; porém a mim não me tendes sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Muita gente dos judeus soube pois, que ele estava ali; e vieram, não somente por causa de Jesus, mas também para verem a Lázaro, a quem ressuscitara dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'E os chefes dos sacerdotes se aconselharam de também matarem a Lázaro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Porque muitos dos judeus iam por causa dele, e criam em Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'No dia seguinte, ouvindo uma grande multidão, que viera à festa, que Jesus vinha a Jerusalém,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Tomaram ramos de plantas e lhe saíram ao encontro, e clamavam: Hosana! Bendito aquele que vem no nome do Senhor, o Rei de Israel!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'E Jesus achou um jumentinho, e sentou-se sobre ele, como está escrito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Não temas, ó filha de Sião; eis que teu Rei vem sentado sobre o filhote de uma jumenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Porém seus discípulos não entenderam isto ao princípio; mas sendo Jesus já glorificado, então se lembraram que isto dele estava escrito, e que isto lhe fizeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'A multidão pois, que estava com ele, testemunhava, que a Lázaro chamara da sepultura, e o ressuscitara dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Pelo que também a multidão lhe saiu ao encontro, porque ouvira que fizera este sinal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Disseram pois os fariseus entre si: Vedes que nada aproveitais? Eis que o mundo vai após ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'E havia alguns gregos dos que haviam subido para adorarem na festa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Estes pois vieram a Filipe, que era de Betsaida de Galileia, e rogaram-lhe, dizendo: Senhor, queríamos ver a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Veio Filipe, e disse-o a André; e André então e Filipe o disseram a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Porém Jesus lhes respondeu, dizendo: Chegada é a hora em que o Filho do homem será glorificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Em verdade, em verdade vos digo, se o grão de trigo, ao cair na terra, não morrer, ele fica só; porém se morrer, dá muito fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Quem ama sua vida a perderá; e quem neste mundo odeia sua vida, a guardará para a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Se alguém me serve, siga-me; e onde eu estiver, ali estará também meu servo. E se alguém me servir, o Pai o honrará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Agora minha alma está perturbada; e que direi? Pai, salva-me desta hora; mas por isso vim a esta hora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Pai, glorifica teu Nome. Veio, pois, uma voz do céu, que dizia: E já o tenho glorificado, e outra vez o glorificarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'A multidão pois que ali estava, e a ouviu, dizia que havia sido trovão. Outros diziam: Algum anjo falou com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Respondeu Jesus e disse: Esta voz não veio por causa de mim, mas sim por causa de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Agora é o juízo deste mundo; agora será lançado fora o príncipe deste mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'E eu, quando for levantado da terra, trarei todos a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, '(E isto dizia, indicando de que morte ele morreria.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Respondeu-lhe a multidão: Temos ouvido da Lei que o Cristo permanece para sempre; e como tu dizes que convém que o Filho do homem seja levantado? Quem é este Filho do homem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Disse-lhes pois Jesus: Ainda por um pouco de tempo a luz está convosco; andai enquanto tendes luz, para que as trevas vos não apanhem. E quem anda em trevas não sabe para onde vai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Enquanto tendes luz, crede na luz, para que sejais filhos da luz.Estas coisas falou Jesus, e indo-se, escondeu-se deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'E ainda que perante eles tinha feito tantos sinais, não criam nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Para que se cumprisse a palavra do profeta Isaías, que disse: Senhor, quem creu em nossa pregação? E a quem o braço do Senhor foi revelado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Por isso não podiam crer, porque outra vez Isaías disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Os olhos lhes cegou, e o coração lhes endureceu; para não acontecer que vejam dos olhos, e entendam do coração, e se convertam, e eu os cure.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Isto disse Isaías, quando viu sua glória, e falou dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Contudo ainda até muitos dos chefes também creram nele; mas não o confessavam por causa dos fariseus; para não serem expulsos da sinagoga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Porque amavam mais a glória humana do que a glória de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'E exclamou Jesus, e disse: Quem crê em mim, não crê somente em mim, mas também naquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'E quem vê a mim, vê a aquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Eu sou a luz que vim ao mundo, para que todo aquele que crê em mim, não permaneça em trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'E se alguém ouvir minhas palavras, e não crer, eu não o julgo; porque não vim para julgar o mundo, mas sim para salvar o mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Quem me rejeitar e não receber minhas palavras, já tem quem o julgue: a palavra que eu tenho falado, essa o julgará no último dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Porque eu não tenho falado de mim mesmo; porém o Pai que me enviou, ele me deu mandamento do que devo dizer, e do que devo falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'E sei que seu mandamento é vida eterna. Portanto o que eu falo, falo assim como o Pai tem me dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'E antes da festa da páscoa, sabendo Jesus que sua hora já era vinda, para que deste mundo passasse para o Pai, havendo amado aos seus, que estavam no mundo, até o fim os amou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'E terminada a ceia, o diabo já havia metido no coração de Judas de Simão Iscariotes, que o traísse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Sabendo Jesus que o Pai já tinha lhe dado todas as coisas nas mãos, e que ele era vindo de Deus, e para Deus ele iria,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Levantou-se da ceia, e tirou as roupas, e tomando uma toalha, envolveu- a em si;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Depois pôs água em uma bacia, e começou a lavar os pés dos discípulos, e limpá-los com a toalha com que estava envolto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Veio, pois, a Simão Pedro; e ele lhe disse: Senhor, tu a mim lavas meus pés?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Respondeu Jesus, e disse-lhe: O que eu faço tu não o sabes agora; mas depois o entenderás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Disse-lhe Pedro: Nunca lavarás meus pés. Respondeu-lhe então Jesus: Se eu não te lavar, não tens parte comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Disse-lhe Simão Pedro: Senhor, lava não só meus pés, mas também as mãos e a cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Disse-lhe Jesus: Aquele que está lavado não necessita lavar, a não ser os pés, mas está todo limpo. E vós limpos estais, porém não todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Porque ele bem sabia quem o trairia; por isso disse: Nem todos estais limpos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Quando então, tendo eles lavado os pés, e tomado suas roupas, voltou a se sentar à mesa,e disse-lhes: Entendeis o que vos tenho feito?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vós me chamais Mestre, e Senhor, e bem dizeis; que eu o sou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Pois se eu, o Senhor, e o Mestre, tenho lavado vossos pés, também vós deveis lavar vossos pés uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Porque vos tenho dado exemplo, para que como eu vos tenho feito, façais vós também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Em verdade, em verdade vos digo, que o servo não é maior que seu senhor; nem enviado maior que aquele que o enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Se sabeis estas coisas, sereis bem-aventurados se as fizerdes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Não digo de todos; bem sei eu aos que tenho escolhido; mas para que se cumpra a Escritura, que diz: O que come comigo, levantou contra mim seu calcanhar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Desde agora, antes que se faça, digo-o a vós, para que, quando se fizer, creiais que eu sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Em verdade, em verdade vos digo, que se alguém receber ao que eu enviar, a mim me recebe; e quem a mim me receber, recebe a aquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Havendo Jesus dito isto, perturbou-se em espírito, e testemunhou, e disse: Em verdade, em verdade vos digo, que um de vós me trairá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Pelo que os discípulos se olhavam uns para os outros, duvidando de quem ele dizia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'E um dos discípulos, a quem Jesus amava, estava sentado à mesa encostado no seio de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'A este pois fez sinal Simão Pedro, que perguntasse quem era aquele de quem ele dizia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'E declinando-se ele ao peito de Jesus, disse-lhe: Senhor, quem é?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Respondeu Jesus: Aquele a quem eu der o pedaço molhado de pão. E molhando o pedaço de pão, deu-o a Judas de Simão Iscariotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'E após o pedaço de pão, entrou nele Satanás. Disse-lhe pois Jesus: O que fazes, faze-o depressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'E nenhum dos que estavam sentados à mesa entendeu para que ele lhe dissera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Pois alguns pensavam que, porque Judas tinha a bolsa, Jesus havia lhe dito: Compra o que para o que nos é necessário para a festa; ou que alguma coisa desse aos pobres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Havendo ele pois tomado o pedaço de pão, logo saiu. E já era noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Tendo, pois, ele saído, disse Jesus: Agora o Filho do homem é glorificado, e Deus é glorificado nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Se Deus nele é glorificado, também Deus o glorificará em si mesmo, e logo o glorificará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Filhinhos, ainda um pouco estou convosco. Vós me buscareis; e tal como eu aos Judeus: Para onde eu vou, vós não podeis vir; assim também o digo a vós agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Um novo mandamento vos dou: que vos ameis uns aos outros; tal como eu vos amei, também ameis vós uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Nisto todos conhecerão que sois meus discípulos: se vós tiverdes amor uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Disse-lhe Simão Pedro: Senhor, para onde vais? Respondeu-lhe Jesus: Para onde eu vou tu não podes me seguir agora; porém depois me seguirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Disse-lhe Pedro: Senhor, por que agora não posso te seguir? Por ti eu darei minha vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Respondeu-lhe Jesus: Por mim darás tua vida? Em verdade, em verdade te digo, que o galo não cantará, até que três vezes me negues.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Não se perturbe vosso coração; credes em Deus, crede também em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Na casa de meu Pai há muitas moradas; senão, eu vos diria; vou para vos preparar lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'E quando eu for, e vos preparar lugar, outra vez virei, e vos tomarei comigo, para que vós também estejais onde eu estiver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'E já sabeis para onde vou, e sabeis o caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Disse-lhe Tomé: Senhor, não sabemos para onde vais; e como podemos saber o caminho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesus lhe disse: Eu sou o caminho, e a verdade, e a vida. Ninguém vem ao Pai, a não ser por mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Se vós conhecêsseis a mim, também conheceríeis a meu Pai; e desde agora já o conheceis, e o tendes visto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Disse-lhe Filipe: Senhor, mostra-nos ao Pai, e basta-nos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jesus lhe disse: Tanto tempo há que estou convosco, e ainda não me tens conhecido, Filipe? Quem a mim tem visto, já tem visto ao Pai; e como dizes tu: Mostra-nos ao Pai?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Não crês tu que eu estou no Pai, e que o Pai está em mim? As palavras que eu vos falo, não as falo de mim mesmo, mas o Pai que está em mim, ele é o que faz as obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Crede em mim que eu estou no Pai, e que o Pai está em mim; e quando não, crede em mim por causa das próprias obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Em verdade, em verdade vos digo, que aquele que crê em mim, as obras que eu faço também ele as fará; e fará maiores que estas. Porque eu vou a meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'E tudo quanto pedirdes em meu nome, eu o farei; para que o Pai seja glorificado no Filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Se alguma coisa pedirdes em meu nome, eu a farei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Se me amais, guardai meus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'E eu rogarei ao Pai, e ele vos dará outro Consolador, para que fique sempre convosco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Ao Espírito de verdade, a quem o mundo não pode receber; porque não o vê, nem o conhece; mas vós o conheceis, porque habita convosco, e estará em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Não vos deixarei órfãos; eu virei a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Ainda um pouco, e o mundo não me verá mais; mas vós me vereis; porque eu vivo, e vós vivereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Naquele dia conhecereis que estou em meu Pai, e vós em mim, e eu em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Quem tem meus mandamentos, e os guarda, esse é o que me ama; e quem a mim me ama, será amado de meu Pai, e eu o amarei, e a ele me manifestarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Disse-lhe Judas (não o Iscariotes): Senhor, que há, porque a nós te manifestarás, e não ao mundo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Respondeu Jesus, e disse-lhe: Se alguém me ama, guardará minha palavra, e meu Pai o amará, e viremos a ele, e faremos morada com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Quem não me ama, não guarda minhas palavras. E a palavra que ouvis não é minha, mas sim do Pai que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Estas coisas tenho dito a vós, estando ainda convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Mas aquele Consolador, o Espírito Santo, ao qual o Pai enviará em meu nome, esse vos ensinará tudo, e tudo quanto tenho dito vós, ele vos fará lembrar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'A paz vos deixo, minha paz vos dou; vou dá- la a vós, não como o mundo a dá. Não se perturbe vosso coração, nem se atemorize.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Já ouvistes que vos tenho dito: Vou, e venho a vós. Se me amásseis, verdadeiramente vos alegraríeis, porque tenho dito: Vou ao Pai; pois meu Pai maior é que eu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'E já agora o disse a vós antes que aconteça, para que quando acontecer, o creiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Já não falarei muito convosco; pois o príncipe deste mundo já vem, e ele nada tem em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Mas para que o mundo saiba que eu amo ao Pai, e assim faço como o Pai me mandou; levantai-vos, vamos embora daqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Eu sou a videira verdadeira, e meu Pai é o lavrador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Todo ramo que em mim não dá fruto, ele o tira; e todo o que da fruto, ele o limpa, para que dê mais fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Vós já estais limpos pela palavra que vos tenho falado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Estai em mim, e eu em vós; como o ramo de si mesmo não pode dar fruto, se não estiver na videira, assim vós também não, se não estiverdes em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Eu sou a videira, vós sois os ramos; quem está em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Se alguém não estiver em mim, é lançado fora, como o ramo, e seca-se; e os colhem, e os lançam no fogo, e ardem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Se vós estiverdes em mim, e minhas palavras estiverem em vós, tudo o que quiserdes pedireis, e será feito para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Nisto é glorificado meu Pai, em que deis muito fruto; e assim sereis meus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Como o Pai me amou, também eu vos amei; estai neste meu amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Se guardardes meus mandamentos, estareis em meu amor. Como eu tenho guardado os mandamentos de meu Pai, e estou em seu amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Estas coisas eu tenho vos dito para que minha alegria esteja em vós, e vossa alegria seja completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Este é meu mandamento: que vos ameis uns aos outros, assim como eu vos amei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Ninguém tem maior amor que este: que alguém ponha sua vida por seus amigos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vós sois meus amigos, se fizerdes o que eu vos mando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Já não vos chamo mais servos; porque o servo não sabe o que faz seu senhor; mas eu tenho vos chamado de amigos, porque tudo quanto ouvi de meu Pai eu tenho vos feito conhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Não fostes vós que me escolhestes, porém eu vos escolhi, e tenho vos posto para que vades, e deis fruto, e vosso fruto permaneça; para que tudo quanto pedirdes ao Pai em meu nome, ele vos dê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Isto vos mando, para que vos ameis uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Se o mundo vos odeia, sabei que odiou a mim antes que a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Se vós fôsseis do mundo, o mundo amaria ao seu; mas porque não sois do mundo, antes eu vos escolhi do mundo, por isso o mundo vos odeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Lembrai-vos da palavra que vos tenho dito: não é o servo maior que seu senhor. Se me perseguiram, também vos perseguirão; se guardaram minha palavra, também guardarão a vossa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Mas tudo isto vos farão por causa do meu nome; porque não conhecem a aquele que me enviou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Se eu não tivesse vindo, nem lhes houvesse falado, não teriam pecado; mas agora já não têm pretexto pelo seu pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Quem me odeia, também odeia a meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Se eu entre eles não tivesse feito obras, que nenhum outro fizera, não teriam pecado; mas agora as viram, e contudo odiaram a mim, e a meu Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Mas isto é para que se cumpra a palavra que está escrita em sua Lei: Sem causa me odiaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Mas quando vier o Consolador, que eu do Pai vos enviarei, aquele Espírito de verdade, que sai do Pai, ele testemunhará de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'E também vós testemunhareis, pois estivestes comigo desde o princípio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Estas coisas tenho vos dito para que não vos ofendeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Expulsarão a vós das sinagogas; mas a hora vem, quando qualquer que vos matar, pensará fazer serviço a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'E estas coisas vos farão, porque nem ao Pai, nem a mim me conheceram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Porém tenho vos dito isto para que, quando aquela hora vier, disso vos lembreis, que já o dissera a vós; mas isto eu não vos disse desde o princípio, porque eu estava convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'E agora vou para aquele que me enviou; e nenhum de vós me pergunta: Para onde vais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Porém, porque vos disse estas coisas, a tristeza encheu vosso coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Mas vos digo a verdade, que vos convém que eu vá; porque se eu não for, o Consolador não virá a vós; porém se eu for, eu o enviarei a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'E vindo ele, convencerá ao mundo do pecado, e da justiça, e do juízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Do pecado, porque não creem em mim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'E da justiça, porque vou para meu Pai, e não me vereis mais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'E do juízo, porque o Príncipe deste mundo já está julgado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Ainda tenho muitas coisas que vos dizer, mas agora ainda não podeis suportá-las.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Porém quando vier aquele Espírito de verdade, ele vos guiará em toda verdade. Porque de si mesmo não falará; mas falará tudo o que ouvir; E ele vos anunciará as coisas que virão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Ele me glorificará, porque tomará do que é meu, e vos anunciará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Tudo quanto tem o Pai é meu; por isso eu disse, que tomará do que é meu, e vos anunciará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Um pouco, e não me vereis; e mais um pouco, e me vereis; porque vou ao Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Disseram pois alguns de seus discípulos uns aos outros: Que é isto que ele nos diz: Um pouco, e não me vereis; e mais um pouco, e me vereis; e porque vou ao Pai?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Então diziam: Que é isto que ele diz? Um pouco? Não sabemos o que diz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Conheceu pois Jesus que lhe queriam perguntar, e disse-lhes: Perguntais entre vós sobre isto que disse: Um pouco, e não me vereis; e mais um pouco, e me vereis?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Em verdade, em verdade vos digo, que vós chorareis, e lamentareis, e o mundo se alegrará, e vós estareis tristes; mas vossa tristeza se tornará em alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'A mulher quando está no parto tem tristeza, porque sua hora é vinda; mas havendo nascido a criança, já não se lembra da aflição, pela alegria de um homem ter nascido no mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Assim também vós agora na verdade tendes tristeza; mas novamente vos verei, e vosso coração se alegrará, e ninguém tirará vossa alegria de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'E naquele dia nada me perguntareis. Em verdade, em verdade vos digo, que tudo quanto pedirdes a meu Pai em meu nome, ele vos dará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Até agora nada pedistes em meu nome; pedi, e recebereis, para que vossa alegria seja completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Estas coisas vos falei por parábolas; porém a hora vem quando não mais vos falarei por parábolas; mas vos falarei abertamente sobre o Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Naquele dia pedireis em meu nome; e não vos digo, que eu suplicarei ao Pai por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Pois o próprio Pai vos ama, porque vós me amastes, e crestes que eu saí de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Saí do Pai, e vim ao mundo; novamente deixo o mundo, e vou ao Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Disseram-lhe seus Discípulos: Eis que agora falas abertamente, e nenhuma parábola dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Agora sabemos que sabes todas as coisas; e não necessitas que ninguém te pergunte. Por isso cremos que saíste de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Respondeu-lhes Jesus: Agora credes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Eis que a hora vem, e já é chegada, quando sereis dispersos, cada um por si, e me deixareis só. Porém não estou só, porque o Pai está comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Estas coisas tenho vos dito para que tenhais paz em mim; no mundo tereis aflição; mas tende bom ânimo; eu venci o mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Jesus falou estas coisas, levantou seus olhos ao céu, e disse: Pai, chegada é a hora; glorifica a teu Filho, para que também teu Filho glorifique a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Assim como lhe deste poder sobre toda carne, para que a todos quantos lhe deste, lhes dê a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'E esta é a vida eterna: que conheçam a ti, o único Deus verdadeiro, e a Jesus Cristo, a quem tens enviado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Eu já te glorifiquei na terra; consumado tenho a obra que me deste para eu fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'E agora glorifica-me tu, ó Pai, junto de ti mesmo, com aquela glória que eu tinha junto de ti, antes que o mundo existisse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Manifestei teu nome aos seres humanos que me deste do mundo. Eles eram teus, e tu os deste a mim; e eles guardaram tua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Agora eles sabem que tudo quanto me deste vem de ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Porque as palavras que tu me deste eu lhes dei; e eles as receberam, e verdadeiramente reconheceram que eu saí de ti, e creram que tu me enviaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Eu rogo por eles; não rogo pelo mundo, mas sim por aqueles que tu me deste, porque são teus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'E todas as minhas coisas são tuas; e as tuas coisas são minhas; e nelas sou glorificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'E eu já não estou no mundo; porém estes ainda estão no mundo, e eu venho a ti. Pai Santo, guarda-os em teu nome, a aqueles que tens me dado, para que sejam um, como nós somos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Quando eu com eles estava no mundo, em teu nome eu os guardava. A aqueles que tu me deste eu os tenho guardado; e nenhum deles se perdeu, a não ser o filho da perdição, para que a Escritura se cumpra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Mas agora venho a ti, e falo isto no mundo, para que em si mesmos tenham minha alegria completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Tua palavra lhes dei, e o mundo os odiou, porque não são do mundo, assim como eu não sou do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Não suplico que os tires do mundo, mas que os guardes do maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Eles não são do mundo, assim como eu não sou do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Santifica-os em tua verdade; tua palavra é a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Assim como tu me enviaste, eu os enviei ao mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'E por eles a mim mesmo me santifico, para que também eles seja santificados em verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'E não suplico somente por estes, mas também por aqueles que crerão em mim, por sua palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Para que todos sejam um; como tu, Pai, em mim, e eu em ti, que também eles em nós sejam um; para que o mundo creia que tu tens me enviado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'E eu tenho lhes dado a glória que tu me deste, para que sejam um, tal como nós somos um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Eu neles, e tu em mim; para que sejam completos em um; e para que o mundo conheça que tu me enviaste, e que tu os amaste, assim como me amaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Pai, aqueles que tens me dado, quero que onde eu estiver, eles também estejam comigo; para que vejam minha glória, que tens me dado, pois tu me amaste desde antes da fundação do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Pai justo, o mundo também não tem te conhecido, e estes têm conhecido que tu me enviaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'E eu fiz teu nome ser conhecido por eles, e eu farei com que seja conhecido, para que o amor com que me amaste esteja neles, e eu neles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Havendo Jesus dito estas coisas, saiu com seus discípulos para além do ribeiro de Cedrom, onde havia um jardim, em que ele entrou ele, e seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'E também Judas, o que o traía, conhecia aquele lugar; porque muitas vezes se juntara ali Jesus com seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Tendo Judas, pois, tomado a tropa e alguns dos oficiais dos sacerdotes e dos fariseus, veio ali com lanternas, tochas, e armas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Sabendo pois Jesus todas as coisas que viriam sobre ele, adiantou-se, e disse-lhes: A quem buscais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Responderam-lhe: A Jesus Nazareno. Disse-lhes Jesus: Eu sou. E Judas, o que o traía, também estava com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Quando pois lhes disse: Eu sou, voltaram para trás, e caíram em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Voltou pois a lhes perguntar: A quem buscais? E eles disseram: A Jesus Nazareno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Respondeu Jesus: Já vos disse que eu sou. Portanto se buscais a mim, deixai a estes irem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Para que se cumprisse a palavra, que tinha dito: Dos que me deste, a nenhum deles perdi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simão Pedro, pois, que tinha espada, puxou dela, e feriu ao servo do sacerdote, e cortou a sua orelha direita. E era o nome do servo Malco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Disse pois Jesus a Pedro: Põe tua espada na bainha; não beberei eu o copo que o Pai tem me dado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'O grupo de soldados pois, e o comandante, e os oficiais dos judeus juntamente tomaram a Jesus, e o amarraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'E o levaram primeiramente a Anás, porque era sogro de Caifás, o qual era o sumo sacerdote daquele ano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'E era Caifás o que havia aconselhado aos judeus de que convinha que um homem morresse pelo povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'E Simão Pedro seguia a Jesus com outro discípulo. E este discípulo era conhecido do sacerdote, e entrou com Jesus no pátio do sumo sacerdote.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'E Pedro estava fora à porta. Saiu pois o outro discípulo, que era conhecido do sacerdote, e falou à porteira, e pôs dentro a Pedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Disse pois a serva porteira a Pedro: Não és tu também dos discípulos deste homem? Disse ele: Não sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'E estavam ali os servos, e os oficiais, que haviam feito uma fogueira de brasas, porque fazia frio, e se esquentavam. Estava Pedro com eles, e se esquentava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Perguntou pois o sacerdote a Jesus sobre seus discípulos, e sobre sua doutrina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus lhe respondeu: Eu abertamente falei ao mundo; eu sempre ensinei na sinagoga e no Templo, onde os Judeus de todos os lugares se juntam, e nada falei em oculto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Por que perguntas a mim? Pergunta aos que o ouviram, que é o que lhes falei. Eis que estes sabem que é o que tenho dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'E dizendo ele isto, um dos oficiais, que ali estava, deu a Jesus uma bofetada, dizendo: Assim respondes ao sumo sacerdote?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Respondeu-lhe Jesus: Se falei mal, dá testemunho do mal; e se bem, por que me feres?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, '(Pois Anás o mandara amarrado ao sumo sacerdote Caifás.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'E Simão Pedro estava ali, e se esquentava; disseram-lhe pois: Não és tu também de seus discípulos? Ele negou, e disse: Não sou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Disse um dos servos do sacerdote, parente daquele a quem Pedro cortara a orelha: Eu não te vi no jardim com ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Pedro negou pois outra vez, e logo cantou o galo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Levaram pois a Jesus de Caifás para o tribunal. E era pela manhã; e não entraram no tribunal, para que não se contaminassem, mas que pudessem comer a Páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Saiu pois Pilatos até eles fora, e disse: Que acusação trazeis contra este homem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Responderam, e disseram-lhe: Se este não fosse malfeitor, não o entregaríamos a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Disse-lhes pois Pilatos: Tomai-o vós, e julgai-o segundo vossa lei. Disseram-lhe pois os Judeus: Não nos é lícito matar a alguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Para que se cumprisse a palavra de Jesus, que tinha dito, dando a entender de que morte havia de morrer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Então Pilatos voltou a entrar no tribunal, e chamou a Jesus, e disse-lhe: És tu o Rei dos Judeus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Respondeu-lhe Jesus: Tu dizes isso de ti mesmo, ou outros te disseram de mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatos respondeu: Por acaso eu sou Judeu? Tua gente e os chefes dos sacerdotes te entregaram a mim; que fizeste?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Respondeu Jesus: Meu Reino não é deste mundo; se meu Reino fosse deste mundo, meus trabalhadores lutariam, para que eu não fosse entregue aos Judeus; mas agora meu Reino não é daqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Disse-lhe pois Pilatos: Logo tu és Rei? Respondeu Jesus: Tu dizes que eu sou Rei. Para isto eu nasci, e para isto vim ao mundo: para dar testemunho à verdade. Todo aquele que é da verdade ouve minha voz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Disse-lhe Pilatos: O que é a verdade? E havendo dito isto, voltou a sair aos Judeus, e disse-lhes: Nenhum crime acho nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Mas vós tendes por costume que eu vos solte um pela páscoa. Quereis pois que vos solte ao Rei dos Judeus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Voltaram pois todos a clamar, dizendo: Não a este, mas a Barrabás!E Barrabás era um ladrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Então Pilatos tomou a Jesus, e o açoitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'E trançando os soldados uma coroa de espinhos, puseram-na sobre sua cabeça, e o vestiram de uma roupa vermelha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'E diziam: Tenhas alegria, Rei dos Judeus! E davam-lhe bofetadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Saiu pois Pilatos outra vez fora, e disse-lhes: Eis que eu o trago para fora até vós, para que saibais que nenhum crime acho nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jesus foi pois trazido para fora, levando a coroa de espinhos, e a roupa vermelha-roxa. E Pilatos disse-lhes: Eis aqui o homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Quando então os chefes dos sacerdotes e os trabalhadores o viram, eles clamaram, dizendo: Crucifica -o! Crucifica -o! Disse-lhes Pilatos: Tomai-o vós, e crucificai -o; porque eu nenhum crime acho nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Responderam-lhe os Judeus: Nós temos Lei, e segundo nossa Lei ele deve morrer, porque se fez Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Quando pois Pilatos ouviu esta palavra, ficou mais atemorizado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'E entrou outra vez no tribunal, e disse a Jesus: De onde és tu? Mas Jesus não lhe deu resposta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Disse-lhe pois Pilatos: Não falas comigo? Não sabes que tenho poder para te crucificar, e tenho poder para te soltar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Respondeu Jesus: Nenhum poder terias contra mim, se não te fosse dado de cima; portanto o que me entregou a ti tem maior pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Desde então Pilatos procurava soltá-lo; mas os Judeus clamavam, dizendo: Se soltas a este, não és amigo de César; qualquer que se faz Rei, contradiz a César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Então Pilatos, ouvindo este dito, levou fora a Jesus, e sentou-se no tribunal, no lugar chamado Litóstrotos, ou pavimento,e em hebraico Gabatá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'E era a preparação da páscoa, e quase à hora sexta, e disse aos Judeus: Eis aqui vosso Rei!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Mas eles bradaram: Tira, tira, crucifica-o! Disse-lhes Pilatos: Crucificarei a vosso Rei?Responderam os chefes dos sacerdotes: Não temos outro rei, a não ser César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Então o entregou a eles, para que fosse crucificado. E tomaram a Jesus, e levaram -no.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'E levando ele sua cruz, saiu para o lugar chamado a Caveira, que em hebraico se chama Gólgota.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Onde o crucificaram, e com ele outros dois, um de cada lado, e a Jesus no meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'E Pilatos também escreveu um título, e o pôs encima da cruz, e estava nele escrito: JESUS NAZARENO, REI DOS JUDEUS.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Leram pois muitos dos Judeus este título; porque o lugar onde Jesus estava crucificado era perto da cidade; e estava escrito em hebraico, em grego, e em latim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Diziam pois os chefes dos sacerdotes dos judeus a Pilatos: Não escrevas: Rei dos Judeus, mas que disse: Sou Rei dos Judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Respondeu Pilatos: O que escrevi, escrevi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Havendo pois os soldados crucificado a Jesus, tomaram suas roupas, e fizeram quatro partes, para cada soldado uma parte, e a túnica. E era a túnica sem costura, toda tecida desde cima até baixo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Disseram pois uns aos outros: Não a partamos, mas lancemos sortes sobre ela, de quem será; para que se cumprisse a Escritura, que diz: Entre si partiram minhas roupas, e sobre minha veste lançaram sortes. Os soldados, pois, fizeram isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'E estavam junto à cruz de Jesus, sua mãe, e a irmã de sua mãe, Maria mulher de Cleofas, e Maria Madalena.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'E vendo Jesus a sua mãe, e ao discípulo a quem amava, que ali estava, disse a sua mãe: Mulher, eis aí teu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Depois disse ao discípulo: Eis aí tua mãe. E desde aquela hora o discípulo a recebeu em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Depois disto, sabendo Jesus que já todas as coisas estavam feitas, para que a Escritura se cumprisse, ele disse: Tenho sede.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Estava pois ali um vaso cheio de vinagre, e encheram uma esponja de vinagre, e envolvendo-a com hissopo, levaram-na a sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Quando pois Jesus tomou o vinagre, disse: Está consumado; e abaixando a cabeça, deu o Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Os Judeus pois, para que os corpos não ficassem no sábado na cruz, pois era a preparação (porque era o grande dia do Sábado), suplicaram a Pilatos que as pernas deles fossem quebradas, e fossem tirados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Vieram pois os soldados, e na verdade quebraram as pernas do primeiro, e do outro, que fora crucificado com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Mas vindo a Jesus, e vendo-o já morto, não quebraram as suas pernas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Mas um dos soldados lhe furou com uma lança o lado, e logo saiu sangue e água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'E o que viu isto, o testemunhou; e seu testemunho é verdadeiro, e sabe que é verdade o que diz, para que vós também creiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Porque estas coisas aconteceram para que se cumprisse a Escritura que diz: Osso dele não será quebrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'E além disso, outra Escritura diz: Verão aquele a quem perfuraram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'E depois José de Arimateia, (que era discípulo de Jesus, porém oculto por medo dos Judeus) suplicou a Pilatos que pudesse tirar o corpo de Jesus; e Pilatos permitiu. Veio pois e tirou o corpo de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'E veio também Nicodemos, (aquele que antes de noite tinha vindo a Jesus) trazendo um composto de mirra e aloés, de quase cem arráteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Tomaram pois o corpo de Jesus, e o envolveram em lençóis com as especiarias, como é costume dos judeus sepultarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'E havia um jardim naquele lugar onde fora crucificado; e no jardim havia um sepulcro novo, em que ainda nunca alguém havia sido posto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Ali pois (por causa da preparação da páscoa dos Judeus, e porque aquele sepulcro estava perto) puseram a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'E no primeiro dia da semana Maria Madalena veio de madrugada, sendo ainda escuro, ao sepulcro; e viu a pedra já tirada do sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Correu pois, e veio a Simão Pedro, e ao outro discípulo a quem Jesus amava, e disse-lhes: Tomaram o Senhor do sepulcro, e não sabemos onde o puseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Pedro saiu pois e o outro discípulo também,e vieram ao sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'E corriam estes dois juntos: e o outro discípulo correu adiante mais depressa que Pedro, e chegou primeiro ao sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'E abaixando-se, viu estar os lençóis; entretanto não entrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Chegou pois Simão Pedro seguindo-o, e entrou no sepulcro, e viu estar os lençóis ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'E o lenço que fora posto sobre sua cabeça, não o viu estar com os lençóis, mas estava dobrado em um lugar à parte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Então pois entrou também o outro discípulo, que primeiro chegara ao sepulcro, e viu, e creu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Porque ainda não sabiam a Escritura, que era necessário que ressuscitasse dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Voltaram pois os Discípulos para a casa deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'E Maria estava fora chorando junto ao sepulcro. Estando ela pois chorando, abaixou-se para ver o sepulcro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'E viu a dois anjos vestidos de branco, sentados um à cabeceira, e o outro aos pés, onde estava posto o corpo de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'E disseram-lhe eles: Mulher, por que choras? Disse-lhes ela: Porque levaram a meu Senhor, e não sei onde o puseram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'E havendo dito isto, virou-se para trás, e viu Jesus em pé, e não sabia que era Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Disse-lhe Jesus: Mulher, por que choras? A quem buscas? Ela, pensando que era o jardineiro, disse-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Disse-lhe Jesus: Maria! Ela, virando-se, disse-lhe: Rabôni! (que quer dizer Mestre).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Disse-lhe Jesus: Não me toques; porque ainda não subi para o meu Pai; porém vai a meus irmãos, e dize- lhes: Subo para meu Pai, e para vosso Pai; para meu Deus, e para vosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Veio Maria Madalena, e anunciou aos discípulos, que vira ao Senhor, e que estas coisas lhe dissera.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Vinda pois já a tarde, o primeiro dia da semana, e fechadas as portas onde os Discípulos, por medo dos judeus, tinham se reunido, veio Jesus, e pôs-se no meio deles,e disse-lhes: Tenhais paz!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'E dizendo isto, mostrou-lhes suas mãos, e seu lado. Então os discípulos se alegraram, vendo ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Disse-lhes pois Jesus outra vez: Tenhais Paz! Como o Pai me enviou, assim eu vos envio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'E havendo dito isto, soprou sobre eles,e disse-lhes: Recebei o Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'A quem quer que perdoardes os pecados, lhes são perdoados; e a quem quer que vós retiverdes os pecados, lhes são retidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'E a Tomé, um dos doze, chamado o Dídimo, não estava com eles, quando Jesus veio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Disseram-lhe pois os outros discípulos: Vimos ao Senhor. Porém ele lhes disse: Se em suas mãos não vir o sinal dos cravos, e não pôr meu dedo no lugar dos cravos, e não pôr minha mão em seu lado, em maneira nenhuma crerei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'E oito dias depois, estavam os discípulos outra vez dentro, e com eles Tomé; e veio Jesus, fechadas já as portas, e pôs-se no meio, e disse: Tenhais paz!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Depois disse a Tomé: Põe teu dedo aqui, e vê minhas mãos; e chega tua mão, e toca-a em meu lado; e não sejas incrédulo, mas sim crente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'E respondeu Tomé e disse-lhe: Senhor meu, e Deus meu!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Disse-lhe Jesus: Porque me viste, Tomé, creste; bem-aventurados aqueles que não virem, e crerem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jesus fez também ainda muitos outros sinais ainda em presença de seus discípulos, que neste livro não estão escritos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Porém estes estão escritos, para que creiais que Jesus é o Cristo, o Filho de Deus; e para que crendo, tenhais vida em seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Depois disto Jesus se manifestou outra vez aos discípulos, junto ao mar de Tibérias; e manifestou -se assim:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Estavam juntos Simão Pedro, e Tomé (chamado o Dídimo), e Natanael (o de Caná de Galileia), e os filhos de Zebedeu, e outros dois de seus discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Disse-lhes Simão Pedro: Vou pescar. Dizem-lhe eles: Também nós vamos contigo. Foram, e subiram logo no barco; e aquela noite nada pescaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'E fazendo-se já manhã, Jesus se pôs na praia; porém os discípulos não sabiam que era Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Então Jesus lhes disse: Filhinhos, tendes algo para comer? Responderam-lhe: Não.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'E ele lhes disse: Lançai a rede do lado direito do barco, e achareis. Lançaram-na pois, e já não a podiam tirar pela multidão dos peixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Disse pois aquele discípulo, a quem Jesus amava, a Pedro: É o Senhor! Ouvindo pois Simão Pedro que era o Senhor, vestiu-se com a roupa, (porque estava nu), e lançou-se ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'E os outros discípulos vieram com o barquinho (porque não estavam longe da terra, mas sim a cerca de duzentos côvados) trazendo a rede de peixes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Quando pois desceram à terra, viram já as brasas postas, e um peixe posto nelas, e mais pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Disse-lhes Jesus: Trazei dos peixes que pescastes agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simão Pedro subiu, e puxou a rede para a terra, cheia de cento e cinquenta e três grandes peixes; e sendo tantos, a rede não se rompeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Disse-lhes Jesus: Vinde, jantai. E nenhum dos discípulos ousava lhe perguntar: Tu quem és? sabendo que era o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Então Jesus veio, e tomou o pão, e deu-o a eles; e da mesma maneira o peixe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'E esta era já a terceira vez que Jesus se manifestou a seus discípulos, depois de haver ressuscitado dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Havendo eles pois já jantado, disse Jesus a Simão Pedro: Simão filho de Jonas, tu me amas mais do que estes outros? Disse-lhes ele: Sim, Senhor, tu sabes que te amo. Disse-lhe: Alimenta meus cordeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Voltou a lhe a dizer a segunda vez: Simão, filho de Jonas, tu me amas? Disse-lhe: Sim, Senhor, tu sabes que te amo. Disse-lhe: Apascenta minhas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Disse-lhe a terceira vez: Simão, filho de Jonas, tu me amas? Entristeceu-se Pedro de que já pela terceira vez lhe dissesse: Tu me amas? E disse-lhe: Senhor, tu sabes todas as coisas, tu sabes que eu te amo. Disse-lhe Jesus: Alimenta minhas ovelhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Em verdade, em verdade te digo, que quando eras mais jovem, tu mesmo te vestias, e andava por onde querias; mas quando fores já velho, estenderás tuas mãos, e outro te vestirá, e te levará para onde tu não queres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'E disse isto, fazendo entender que Pedro glorificaria a Deus com sua morte. E tendo dito isto, Jesus lhe disse: Segue-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'E virando-se Pedro, viu que o seguia aquele discípulo a quem Jesus amava, o que também na ceia se recostara a seu peito, e dissera: Senhor, quem é o que te trairá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Vendo Pedro a este, disse a Jesus: Senhor, e este, que lhe acontecerá?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Disse-lhe Jesus: Se eu quero que ele fique até que eu venha, que te importa? Segue-me tu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Saiu, pois, esta conversa entre os irmãos, que aquele discípulo não morreria. Contudo Jesus não lhe disse que não morreria, mas sim: Se eu quero que ele fique até que eu venha, que te importa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Este é o discípulo que testemunha destas coisas, e estas coisas escreveu; e sabemos que seu testemunho é verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Ainda há, porém, muitas outras coisas que Jesus fez, que se sobre cada uma delas se escrevessem, penso que nem mesmo o mundo poderia caber os livros escritos. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Eu fiz o primeiro livro, ó Teófilo, sobre todas as coisas que Jesus começou, tanto a fazer como a ensinar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Até o dia em que ele foi recebido acima, depois de pelo Espírito Santo ter dado mandamentos aos apóstolos que tinha escolhido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Aos quais também, depois de ter sofrido, apresentou-se vivo com muitas evidências; sendo visto por eles durante quarenta dias, e falando -lhes das coisas relativas ao reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'E, reunindo-os, mandou-lhes que não saíssem de Jerusalém, mas que esperassem a promessa do Pai que (disse ele) de mim ouvistes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Porque João batizou com água, mas vós sereis batizados com o Espírito Santo, não muitos dias depois destes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Então aqueles que tinham se reunido lhe perguntaram, dizendo: Senhor, tu restaurarás neste tempo o Reino a Israel?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'E ele lhes disse: Não pertence a vós saber os tempos ou estações que o Pai pôs em sua própria autoridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Mas vós recebereis poder do Espírito Santo, que virá sobre vós; e vós sereis minhas testemunhas, tanto em Jerusalém como em toda a Judeia, e Samaria, e até ao último lugar da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'E tendo ele dito estas coisas, enquanto eles o viam, ele foi levantado acima, e uma nuvem o tirou dos olhos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'E enquanto eles estavam com os olhos fixos ao céu, depois dele ter ido, eis que dois homens de roupas brancas se puseram junto a eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Os quais também disseram: Homens galileus, por que estais olhando para o céu? Este Jesus, que foi tomado de vós acima ao céu, assim virá, da maneira como o vistes ir ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Então eles voltaram a Jerusalém do monte que se chama das Oliveiras, o qual está perto de Jerusalém à distância de um caminho de sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'E ao entrarem, subiram ao cômodo superior, onde ficaram Pedro, Tiago, João, André, Filipe, Tomé, Bartolomeu, Mateus, Tiago filho de Alfeu, Simão Zelote e Judas irmão de Tiago.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Todos estes perseveravam concordando em orações, e petições, com as mulheres, com Maria a mãe de Jesus, e com os irmãos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'E em algum d aqueles dias, havendo uma multidão reunida de cerca de cento e vinte pessoas, Pedro se levantou no meio dos discípulos e disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Homens irmãos, era necessário que se cumprisse a Escritura, que o Espírito Santo, por meio da boca de Davi, predisse quanto a Judas, que foi o guia daqueles que prenderam a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Porque ele foi contado conosco, e obteve uma porção neste ministério.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Este pois, adquiriu um campo por meio do pagamento da maldade, e tendo caído de cabeça para baixo, partiu-se ao meio, e todos os seus órgãos internos caíram para fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'E isso foi conhecido por todos os que habitam em Jerusalém, de maneira que aquele campo se chama em sua própria língua Aceldama, isto é, campo de sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Porque está escrito no livro dos Salmos: Sua habitação se faça deserta, e não haja quem nela habite; e outro tome seu trabalho de supervisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Portanto é necessário, que dos homens que nos acompanharam todo o tempo em que o Senhor Jesus entrava e saía conosco,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Começando desde o batismo de João, até o dia em que diante de nós ele foi recebido acima, se faça um destes testemunha conosco de sua ressurreição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'E apresentaram dois: a José, chamado Barsabás, que tinha por sobrenome o Justo; e a Matias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'E orando, disseram: Tu, Senhor, conhecedor dos corações de todos, mostra a qual destes dois tu tens escolhido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Para que ele tome parte deste ministério e apostolado, do qual Judas se desviou para ir a seu próprio lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'E lançaram-lhes as sortes; e caiu a sorte sobre Matias. E ele passou a ser contado junto com os onze apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'E ao se cumprir o dia de Pentecostes, estavam todos concordando no mesmo lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'E de repente houve um ruído do céu, como de um vento forte e violento, e encheu toda a casa onde eles estavam sentados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'E foram vistas por eles línguas repartidas como que de fogo, e se pôs sobre cada um deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'E eles foram todos cheios do Espírito Santo, e começaram a falar em outras línguas, conforme o Espírito lhes dava a discursarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'E havia judeus que estavam morando em Jerusalém, homens devotos, de toda nação abaixo do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'E acontecendo esta voz, ajuntou-se a multidão; e ela estava confusa, porque cada um os ouvia falar em sua própria língua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'E todos estavam admirados, e se maravilhavam, dizendo uns aos outros: Ora, estes que estão falando, não são todos eles galileus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'E como nós ouvimos cada um deles em nossa própria língua, na qual nascemos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Partos, Medos, Elamitas, os habitantes da Mesopotâmia, da Judeia, Capadócia, Ponto, Ásia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frígia, Panfília, Egito e regiões da Líbia perto de Cirene, e romanos estrangeiros, tanto judeus como prosélitos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Cretenses e Árabes, os ouvimos em nossas próprias línguas eles falarem das grandezas de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'E todos estavam admirados e confusos, dizendo uns aos outros: O que isso quer dizer?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'E outros, ridicularizando, diziam: Eles estão cheios de vinho doce.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Mas Pedro, pondo-se de pé com os onze, levantou sua voz, e lhes falou: Homens judeus, e todos os que habitais em Jerusalém, seja isto conhecido, e ouvi minhas palavras:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Porque estes não estão bêbados, como vós pensais, sendo ainda a terceira hora do dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Mas isto é o que foi dito por meio do profeta Joel:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'E será nos últimos dias, diz Deus, que: Eu derramarei do meu Espírito sobre toda carne, e vossos filhos e filhas profetizarão, e vossos rapazes terão visões, e vossos velhos sonharão sonhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'E também sobre meus servos e sobre minhas servas, naqueles dias eu derramarei do meu Espírito, e profetizarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'E darei milagres acima no céu, e sinais abaixo na terra; sangue, fogo, e vapor de fumaça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'O sol se converterá em trevas, e a lua em sangue, antes que venha o grande e notório dia do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'E será que todo aquele que chamar ao nome do Senhor será salvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Homens israelitas, ouvi estas palavras: Jesus o nazareno, homem aprovado por Deus entre vós, com maravilhas, milagres e sinais, que Deus fez por meio dele no meio de vós, assim como vós mesmos também sabeis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Este, sendo entregue pelo determinado conselho e conhecimento prévio de Deus, sendo tomando, pelas mãos de injustos o crucificastes e matastes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Ao qual Deus ressuscitou, tendo soltado as dores da morte; porque não era possível ele ser retido por ela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Porque Davi diz sobre ele: Eu sempre via ao Senhor diante de mim, porque ele está à minha direita, para que eu não seja abalado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Por isso meu coração está contente, e minha língua se alegra, e até mesmo minha carne repousará em esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Pois tu não abandonarás minha alma no mundo dos mortos, nem entregarás a teu santo, para que veja corrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu tens me feito conhecer os caminhos da vida; tu me encherás de alegria com tua face.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Homens irmãos, é lícito eu vos dizer abertamente sobre o patriarca Davi, que morreu, e foi sepultado, e a sepultura dele está conosco até o dia de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Portanto, sendo ele profeta, e sabendo que Deus tinha lhe prometido com juramento que, da sua descendência segundo a carne, levantaria ao Cristo para se sentar no seu trono;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Vendo -o com antecedência, falou da ressurreição do Cristo, que a alma dele não foi abandonada no mundo dos mortos, nem a carne dele viu corrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'A este Jesus Deus ressuscitou; do qual todos nós somos testemunhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Portanto, tendo sido exaltado à direita de Deus, e recebido do Pai a promessa do Espírito Santo, derramou isto que agora estais vendo e ouvindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Porque Davi não subiu aos céus; mas sim, ele diz: Disse o Senhor a meu Senhor: Senta-te à minha direita,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Até que eu ponha teus inimigos por escabelo de teus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Saiba então com certeza toda a casa de Israel, que Deus o fez Senhor e Cristo a este Jesus, que vós crucificastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'E eles, ao ouvirem estas coisas,foram afligidos como que perfurados de coração, e disseram a Pedro, e aos outros apóstolos: Que faremos, homens irmãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'E Pedro lhes disse: Arrependei-vos, e batize-se cada um de vós no nome de Jesus Cristo, para perdão dos pecados; e vós recebereis o dom do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Porque a promessa é para vós, e para vossos filhos, e para todos que ainda estão longe, a tantos quantos Deus, nosso Senhor, chamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'E com muitas outras palavras ele dava testemunho, e exortava, dizendo: Salvai-vos desta geração perversa!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Então os que receberam a palavra dele de boa vontade foram batizados; e foram adicionados naquele dia quase três mil almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'E eles perseveravam na doutrina dos apóstolos, na comunhão, no partir do pão, e nas orações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'E houve temor em toda alma; e muitos milagres e sinais foram feitos pelos apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'E todos os que criam estavam juntos, e tinham todas as coisas em comum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'E eles vendiam suas propriedades e bens, e as repartiam com todos, conforme a necessidade que cada um tinha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'E perseverando a cada dia em concordância no Templo, e partindo o pão de casa em casa, comiam juntos com alegria e sinceridade de coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Louvando a Deus, e tendo graça, sendo do agrado de todo o povo. E a cada dia o Senhor acrescentava à igreja aqueles que estavam sendo salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'E Pedro e João estavam subindo juntos para o Templo à hora da oração (a nona hora);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'E um certo homem estava sendo trazido, que era aleijado desde o ventre de sua mãe, ao qual todo dia colocavam à porta do Templo, chamada Porta Formosa, para pedir esmola aos que entravam no Templo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'O qual, ao ver Pedro e João perto de entrarem no Templo, ele lhes pediu uma esmola.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'E Pedro, olhando fixamente para ele, junto com João, disse: Olha para nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'E o aleijado ficou prestando atenção neles, esperando receber deles alguma coisa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'E Pedro disse: Prata e ouro eu não tenho; mas o que eu tenho, isso eu te dou: no nome de Jesus Cristo, o nazareno, levanta-te, e anda!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'E, tomando-o pela mão direita, levantou -o; e logo os seus pés e tornozelos ficaram firmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'E ele, saltando, pôs-se de pé, e andou, e entrou com eles no Templo, andando, e saltando, e louvando a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'E todo o povo o viu andar, e louvar a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'E eles o reconheceram, que este era o que se sentava para pedir esmola perto da porta formosa do Templo; e ficaram cheios de surpresa e espanto, por causa do que tinha lhe acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'E o aleijado que tinha sido curado, tendo se apegado a Pedro e a João, todo o povo correu maravilhado a eles ao alpendre, que se chama de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Quando Pedro viu isso, respondeu ao povo: “Homens israelitas, por que vos maravilhais disto? Ou por que vós olhais tão atentamente para nós, como se por nosso próprio poder ou devoção divina o tivéssemos feito andar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'O Deus de Abraão, e de Isaque, e de Jacó, o Deus de nossos pais, glorificou a seu filho Jesus, ao qual vós entregastes, e diante do rosto de Pilatos o negastes, mesmo ele julgando que fosse solto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Mas vós negastes ao santo e justo, e pedistes que um homem assassino fosse vos dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'E vós matastes ao Príncipe da vida, ao qual Deus ressuscitou dos mortos, do que nós somos testemunhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'E pela fé em seu nome, o nome dele deu firmeza a este, que vedes e conheceis; e a fé que é por meio dele deu a este perfeita saúde na presença de todos vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'E agora, irmãos, eu sei que vós fizestes isso por ignorância, assim como também vossos líderes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Mas Deus cumpriu assim o que já antes pela boca de todos os seus profetas ele tinha anunciado, que o Cristo tinha de sofrer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Arrependei-vos, pois, e convertei-vos, para que vosso pecados sejam apagados, quando vierem os tempos do refrigério da presença do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'E ele enviar a Jesus Cristo, que já vos foi pregado anteriormente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Ao qual convém que o céu receba até os tempos da restauração de todas as coisas, que Deus falou pela boca de todos os seus santos profetas, desde o princípio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Porque Moisés disse aos nossos pais: O Senhor, vosso Deus, levantará dentre vossos irmãos um profeta como eu; a ele ouvireis em tudo o que ele vos falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'E será que toda pessoa que não ouvir este profeta será exterminada do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'E também todos os profetas, desde Samuel e os posteriores, todos os que falaram, também anunciaram com antecedência destes dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vós sois os filhos dos profetas e do pacto que Deus estabeleceu com nossos pais, dizendo a Abraão: E em tua semente serão abençoadas todas as famílias da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Deus, ao ressuscitar seu filho Jesus, primeiro o enviou a vós, para que nisto vos abençoasse: afastando cada um de vós de vossas maldades”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'E enquanto eles ainda estavam falando ao povo, vieram sobre eles os sacerdotes, e o oficial do Templo, e os saduceus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Muito incomodados por eles ensinarem ao povo, e anunciarem no nome de Jesus a ressurreição dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'E puseram as mãos sobre eles, e os puseram na prisão até o dia seguinte, porque já era tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'E muitos dos que ouviram a palavra, creram; e era o número dos homens de cerca de cinco mil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'E aconteceu no dia seguinte, que os chefes, e anciãos, e escribas, se reuniram em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'E Anás, o sumo sacerdote, e Caifás, e João, e Alexandre, e todos quantos havia da linhagem do governo sacerdotal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'E pondo-os no meio, perguntaram -lhes: Por meio de que poder ou por qual nome vós fizestes isto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Então Pedro, cheio do Espírito Santo, lhes disse: Chefes do povo, e anciões de Israel,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Se hoje somos interrogados quanto a uma boa ação feita a um enfermo, pela qual este foi curado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Seja conhecido a todos vós, e a todos o povo de Israel, que pelo nome de Jesus Cristo, o nazareno, aquele que vós crucificastes, ao qual Deus ressuscitou dos mortos, por ele este homem está são diante de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Este é a pedra que foi desprezada por vós, edificadores; a qual foi feita por cabeça de esquina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'E em nenhum outro há salvação; porque nenhum outro nome há abaixo do céu, dado entre os seres humanos, em quem devemos ser salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'E eles, ao verem a ousadia de Pedro, e de João; e informados que eles eram homens sem instrução e ordinários, maravilharam-se; e eles sabiam que eles tinham estado com Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'E vendo estar com eles o homem que tinha sido curado, nada tinham a dizer contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'E mandando-os saírem fora do Conselho, discutiam entre si,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Dizendo: O que faremos a estes homens? Porque um sinal notório foi feito por eles, manifesto a todos os que habitam em Jerusalém, e não podemos negar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Mas para que esta notícia não seja ainda mais divulgada entre o povo, façamos sérias ameaças a eles, para que nunca mais falem a ninguém neste nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'E chamando-os, ordenaram-lhes que nunca mais falassem nem ensinassem no nome de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mas, respondendo Pedro, e João, disseram-lhes: Julgai se é justo diante de Deus, ouvir a vós mais do que a Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Porque nós não podemos deixar de falar daquilo que temos visto e ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Mas eles, tendo os ameaçado ainda mais, nada acharam de motivo para os castigar, e os deixaram ir por causa do povo; porque todos glorificavam a Deus pelo que tinha acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Porque era de mais de quarenta anos o homem em quem este milagre de cura tinha sido feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'E eles, tendo sido soltos, vieram aos seus companheiros, e lhes contaram tudo o que os chefes dos sacerdotes e os anciãos tinham lhes dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'E eles, ao ouvirem isto, levantaram concordantes a voz a Deus, e disseram: Senhor, tu és o Deus que fizeste o céu, a terra, o mar, e todas as coisas que neles há;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Que pela boca de teu servo Davi disseste: Por que os gentios se irritam, e os povos gastam seus pensamentos em coisas vãs?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Os reis da terra se levantaram, e os príncipes se juntaram em um mesmo propósito contra o Senhor, e contra o seu Ungido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Porque verdadeiramente contra teu Santo Filho Jesus, ao qual tu ungiste, se ajuntaram, tanto Herodes, como Pôncio Pilatos, com os gentios e os povos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Para fazerem tudo o que a tua mão e o teu conselho desde antes tinha determinado para acontecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'E agora, Senhor, observa as ameaças deles, e dá a teus servos, que com toda ousadia falem tua palavra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Estendendo tua mão para a cura, e que se façam sinais e milagres pelo nome de teu Santo filho Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'E tendo orado, agitou-se o lugar em que eles estavam juntos, e foram todos cheios do Espírito Santo, e falavam a palavra de Deus com ousadia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'E a multidão dos que criam, era de um só oração e uma só alma; e ninguém dizia ser próprio coisa alguma de seus bens, mas todas as coisas lhes eram comuns.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'E com grande poder os apóstolos davam testemunho da ressurreição do Senhor Jesus; e em todos eles havia grande graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Porque também nenhum necessitado havia entre eles; porque todos os que possuíam propriedades de terras, ou casas, vendendo -as,traziam o valor das coisas vendidas, e o depositavam junto aos pés dos apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'E a cada um se repartia segundo cada qual tinha necessidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'E José, chamado pelos apóstolos pelo sobrenome de Barnabé (que traduzido é filho da consolação), levita, natural do Chipre,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Tendo ele uma propriedade de terra, vendeu -a,e trouxe o valor, e o depositou junto aos pés dos apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'E um certo homem, de nome Ananias, com Safira, sua mulher, vendeu uma propriedade de terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'E escondeu parte do valor, sabendo também a mulher dele; e trazendo uma certa parte, depositou -a junto aos pés dos apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'E Pedro disse: Ananias, por que Satanás encheu teu coração, para que mentisses ao Espírito Santo, e escondesses parte do valor da propriedade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Se mantivesses tua propriedade,ela não seria mantida contigo? E, tendo sido vendida, o dinheiro da venda não estava em teu poder? Por que decidiste isto em teu coração? Não mentiste aos seres humanos, mas sim a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'E Ananias, ao ouvir estas palavras, caiu e deixou de respirar. E veio um grande temor sobre todos os que ouviram isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'E os rapazes, tendo se levantado, levaram-no fora, e o sepultaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'E passando o intervalo de cerca de três horas, entrou também sua mulher, não sabendo o que tinha acontecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'E Pedro disse a ela: Dize-me, vendestes por aquele tanto aquela propriedade?E ela disse: Sim, por aquele tanto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'E Pedro lhe disse: Por que vós fizestes acordo para tentar ao Espírito do Senhor? Eis que estão à porta os pés daqueles que sepultaram a teu marido, e eles também te levarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'E imediatamente ela caiu junto aos pés deles, e deixou de respirar. E os rapazes, ao entrarem, encontraram-na morta; e levando- a fora, sepultaram-na junto ao marido dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'E veio um grande temor em toda a igreja, e em todos que ouviram estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'E pelas mãos dos apóstolos foram feitos muitos sinais e milagres entre o povo. E estavam todos em concordância no alpendre de Salomão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Mas dos outros, ninguém ousava se juntar a eles; porém o povo os honrava muito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'E cada vez mais os que criam no Senhor se aumentavam, multidões tanto de homens como de mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'De maneira que traziam os enfermos às ruas, e os botavam em camas e macas, para que, vindo Pedro, pelo menos a sombra dele cobrisse a alguns deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'E também das cidades vizinhas vinha uma multidão a Jerusalém, trazendo enfermos, e atormentados por espíritos imundos, os quais todos eram curados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'E levantando-se o sumo sacerdote, e todos os que estavam com ele (que eram do grupo sectário dos saduceus), eles se encheram de inveja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'E puseram suas mãos nos apóstolos, e os colocaram na prisão pública.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Mas um anjo do Senhor, durante a noite, abriu as portas da prisão; e levando-os para fora, disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Ide; ficai em pé, e falai no Templo ao povo todas as palavras desta vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'E eles, ouvindo isto,entraram de manhã cedo no templo, e ensinavam. Mas vindo o sumo sacerdote, e os que estavam com ele, chamaram ao Conselho Principal, e a todos os anciãos dos filhos de Israel, e mandaram à prisão, para que os trouxessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Mas quando os oficiais vieram, não os acharam na prisão; e voltando, anunciaram,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Dizendo: Nós achamos a prisão fechada, em toda segurança, e com os guardas que estavam fora junto às portas; mas quando as abrimos, a ninguém achamos dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Quando o sumo sacerdote, o chefe da guarda do Templo, e os chefes dos sacerdotes ouviram estas palavras, eles duvidaram deles quanto o que aquilo viria a ser.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'E vindo alguém, anunciou-lhes, dizendo: Eis que os homens que vós pusestes na prisão estão no Templo, e ensinam ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Então foi o chefe da guarda do Templo com os oficiais, e os trouxe, mas não com violência, porque temiam ao povo, para que não fossem apedrejados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'E quando os trouxeram, apresentaram-nos ao Supremo Conselho. E o sumo sacerdote perguntou a eles, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Não vos ordenamos expressamente para não ensinardes mais neste nome? E eis que vós enchestes a Jerusalém com vossa doutrina, e quereis trazer sobre nós o sangue deste homem!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'E Pedro, respondendo com os apóstolos, disseram: Maior obrigação é obedecer a Deus do que às pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'O Deus de nossos Pais ressuscitou a Jesus, ao qual vós matastes, pendurando -o no madeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'A este Deus exaltou com sua mão direita por Príncipe e Salvador, para dar a Israel arrependimento e perdão de pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'E nós somos testemunhas dele quanto a estas palavras, e também o Espírito Santo, o qual Deus tem dado a aqueles que lhe obedecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'E eles, ouvindo isto,retalharam-se de raiva, e planejaram matá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Mas, levantando-se no Supremo Conselho um certo fariseu, de nome Gamaliel, instrutor da Lei, bem honrado por todo o povo, ele mandou levarem aos apóstolos para fora por um pouco de tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'E lhes disse: Homens israelitas, olhai por vós mesmos, quanto ao que haveis de fazer a estes homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Porque antes destes dias se levantou Teudas, dizendo ser alguém; ao qual se ajuntaram cerca de quatrocentos homens; ao qual foi morto, e todos os que acreditavam nele foram dispersos, e reduzidos a nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Depois deste se levantou Judas, o galileu, nos dias do censo; e perverteu muito do povo atrás dele; e este também pereceu, e todos os que acreditavam nele foram dispersos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'E agora, eu vos digo, afastai-vos destes homens, e deixai-os; porque se este conselho ou esta obra for humana, ela se desfará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Mas se é de Deus, vós não a podereis desfazer; para que não venhais a ser achados de também lutardes contra Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'E concordaram com ele. E chamando aos apóstolos, tendo os açoitado, mandaram -lhes que não mais falassem no nome de Jesus; e os deixaram ir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Então eles saíram da presença do Supremo Conselho, alegres por terem sido considerados dignos de serem humilhados por causa do nome dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'E todos os dias no Templo, e pelas casas, não paravam de ensinar e de anunciar a Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Naqueles dias, ao se multiplicar o número de discípulos, houve uma murmuração dos gregos contra os hebreus, de que suas viúvas estavam sendo desprezadas no serviço diário de entrega de comida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'E os doze, chamando à multidão dos discípulos, disseram: Não é bom que nós deixemos a palavra de Deus para servirmos às mesas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Portanto, irmãos, buscai sete homens dentre vós, de quem haja bom testemunho, cheios do Espírito Santo e de sabedoria, aos quais constituamos sobre esta importante tarefa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Nós, porém, perseveraremos na oração e no serviço da palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'E esta palavra foi do agrado diante de toda a multidão, e escolheram a Estêvão, homem cheio de fé e do Espírito Santo, e Filipe, Prócoro, Nicanor, Timom, Parmenas e a Nicolão, o prosélito de Antioquia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Aos quais se apresentaram diante dos apóstolos; e eles, orando, puseram as mãos sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'E a palavra de Deus crescia, e o número dos discípulos se multiplicava muito em Jerusalém; e grande multidão dos sacerdotes obedecia à fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'E Estêvão, cheio de fé e poder, fazia milagres e grandes sinais entre o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'E levantaram-se alguns da sinagoga, que era chamada sinagoga dos libertos, cireneus, e alexandrinos, e dos que eram da Cilícia, e da Ásia, e discutiam contra Estêvão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'E eles não podiam resistir à sabedoria e ao Espírito com que ele falava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Então eles subornaram a uns homens, para que dissessem: Nós o ouvimos falando palavras blasfemas contra Moisés e contra Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'E incitaram ao povo, aos anciãos e aos escribas; e vieram sobre Estêvão,e o detiveram, e o levaram ao Supremo Conselho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'E apresentaram falsas testemunhas, que diziam: Este homem não para de falar palavras blasfemas contra este santo lugar, e contra a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Porque nós o ouvimos dizer que este Jesus Nazareno vai destruir este lugar, e mudar os costumes que Moisés nos entregou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Então todos os que estavam sentados no Supremo Conselho, observando-o com atenção, viram o rosto dele como de um anjo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'E disse o chefe dos sacerdotes: Essas coisas são assim mesmo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'E ele disse: Homens irmãos e pais, ouvi: o Deus da glória apareceu a nosso pai Abraão, estando ele na Mesopotâmia, antes de habitar em Harã;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'E disse-lhe: Sai de tua terra, e de tua parentela, e vem a terra que eu te mostrarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Então ele saiu da terra dos caldeus, e habitou em Harã. E dali, depois que morreu seu pai, ele partiu para esta terra, em que agora vós habitais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'E Deus não lhe deu herança nela, nem mesmo a pegada de um pé; mas prometeu que a daria a ele em propriedade, e a sua semente depois dele, não tendo ele filho ainda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'E Deus falou assim: Tua semente será peregrina em terra alheia, e a escravizarão, e a maltratarão por quatrocentos anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'E à nação a quem eles servirem, eu a julgarei, (disse Deus). E depois disso eles sairão, e me servirão neste lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'E ele lhe deu o pacto da circuncisão; e assim gerou a Isaque, e o circuncidou ao oitavo dia; e Isaque gerou a Jacó, e Jacó aos doze patriarcas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'E os patriarcas, tendo inveja de José, venderam -no ao Egito; mas Deus era com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'E o livrou de todas as suas aflições, e lhe deu graça e sabedoria diante de Faraó, rei do Egito; e o pôs por governador sobre o Egito, e toda a sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'E veio fome sobre toda a terra do Egito e de Canaã, e grande aflição; e nossos pais não achavam alimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Mas Jacó, ao ouvir que havia cereal no Egito, ele enviou nossos pais a primeira vez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'E na segunda vez,José foi reconhecido pelos seus irmãos, e a família de José foi conhecia por Faraó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'E José mandou chamar a seu pai Jacó, e toda a sua parentela, setenta e cinco almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'E Jacó desceu ao Egito, e morreu; ele, e nossos pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'E foram levados a Siquém, e postos na sepultura que Abraão, por uma quantia em dinheiro, tinha comprado dos filhos de Emor, pai de Siquém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Mas quando chegou perto o tempo da promessa que Deus tinha prometido a Abraão, o povo cresceu e se multiplicou no Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Até que se levantou outro rei, que não tinha conhecido a José.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Este, usando de astúcia para com nossa parentela, maltratou a nossos pais, até fazendo com que eles rejeitassem suas crianças, para que não sobrevivessem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Naquele tempo nasceu Moisés, e ele era muito formoso para Deus, e ele foi criado por três meses na casa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'E tendo sido abandonado, a filha de Faraó o tomou, e o criou para si como filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'E Moisés foi instruído em toda a sabedoria dos egípcios; e era poderoso em palavras e ações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'E quando lhe foi completado o tempo de quarenta anos de idade, veio ao seu coração o desejo de visitar a seus irmãos, os filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'E vendo um deles sofrendo injustamente, defendeu -o,e vingou pelo que tinha sido oprimido, matando ao egípcio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'E ele pensava que seus irmãos tivessem entendido que Deus ia lhes dar liberdade por meio da mão dele; mas eles não entenderam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'E no dia seguinte, estando uns deles lutando, ele foi visto por eles, e ordenou-lhes fazerem as pazes, dizendo: Homens, vós sois irmãos, por que fazeis mal um ao outro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Mas aquele que maltratava a seu próximo empurrou-o, dizendo: Quem te pôs por chefe e juiz sobre nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Queres tu também matar a mim, assim como ontem mataste ao egípcio?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'E com esta palavra Moisés fugiu, e foi peregrino na terra de Midiã, onde ele gerou dois filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'E completados quarenta anos, um anjo do Senhor lhe apareceu no deserto do monte Sinai, em uma sarça inflamada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Moisés, ao ver isso,maravilhou-se da visão; e ao aproximar-se para ver, veio até ele a voz do Senhor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Dizendo: Eu sou o Deus de teus pais, o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó. E Moisés, estando tremendo, não ousava olhar com atenção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'E o Senhor lhe disse: Descalça-te as sandálias de teus pés, porque o lugar em que estás é terra santa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Eu tenho visto com atenção a aflição de meu povo que está no Egito, e ouvi o gemido deles, e eu desci para livrá-los; então vem agora, eu te enviarei ao Egito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'A este Moisés, ao qual tinham negado, dizendo: Quem te pôs por chefe e juiz, A este Deus enviou por chefe e libertador, pela mão do anjo que lhe apareceu na sarça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Este os levou para fora, fazendo milagres e sinais na terra do Egito, e no mar Vermelho, e no deserto, por quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Este é o Moisés que disse aos filhos de Israel: O Senhor, vosso Deus, vos levantará um profeta dentre vossos irmãos, como a mim; a ele ouvireis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Este é aquele que esteve na congregação do povo no deserto com o anjo que tinha lhe falado no monte Sinai, e com nossos pais; o qual recebeu as palavras vivas, para dar a nós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Ao qual nossos pais não quiseram obedecer; mas o rejeitaram, e seus corações voltaram ao Egito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Ao dizerem a Arão: Faz-nos deuses, que irão adiante de nós; porque quanto a este Moisés, que nos levou para fora da terra do Egito, nós não sabemos o que aconteceu com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'E naqueles dias eles fizeram o bezerro, o ofereceram sacrifício ao ídolo, e se alegraram nas obras de suas próprias mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'E Deus se virou contra eles,e os entregou, para que servissem ao exército do céu, assim como está escrito no livro dos profetas: Por acaso, casa de Israel, vós oferecestes a mim animais mortos, e sacrifícios no deserto por quarenta anos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Mas tomastes para si a tenda de Moloque, e a estrela de vosso Deus Renfã, figuras que vós fizeste para adorá-las; e eu por isso vos expulsarei para além da Babilônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'No deserto estava entre nossos pais o Tabernáculo do testemunho, assim como ele tinha ordenado, falando a Moisés, que o fizesse segundo o modelo que tinha visto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'O qual, recebendo -o também nossos Pais, eles levaram com Josué para a possessão dos gentios que Deus expulsou diante de nossos Pais, até os dias de Davi;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'O qual foi do agrado diante de Deus, e pediu para achar um tabernáculo para o Deus de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'E Salomão lhe construiu uma casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Mas o Altíssimo não habita em templos feitos por mãos, assim como o profeta diz:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'O céu é o meu trono, e a terra é o estrado dos meus pés; que casa vós construireis para mim?, diz o Senhor; ou Qual é o lugar do meu repouso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Por acaso não foi minhão mão que fez todas estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Vós, obstinados e incircuncisos de coração e de ouvidos! Vós sempre resistis ao Espírito Santo! Tal como vossos pais foram,assim também sois vós!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Qual dos profetas vossos pais não perseguiram? E eles mataram a todos os que anunciaram com antecedência a vinda do Justo, do qual agora vós tendes sido traidores e homicidas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Que recebestes a Lei por ordem de anjos, e não a guardastes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Eles, ao ouvirem estas coisas, retalharam-se de raiva em seus corações, e rangiam os dentes contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mas ele, estando cheio do Espírito Santo, olhando firmemente para o céu, viu à glória de Deus, e a Jesus, que estava à direita de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'E disse: Eis que vejo os céus abertos, e o Filho do homem, que está a direita de Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Mas eles, clamando com alta voz, taparam seus próprios ouvidos, e correram juntos contra ele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'E, lançando -o fora da cidade, o apedrejaram; e as testemunhas puseram as roupas deles junto aos pés de um rapaz chamado Saulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'E apedrejaram a Estêvão, que estava clamando e dizendo: Senhor Jesus, recebe o meu espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'E pondo-se de joelhos, clamou com alta voz: Senhor, não os culpes por este pecado.E tendo dito isto, morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'E Saulo também consentia na morte dele. E naquele dia foi feita uma grande perseguição contra a igreja que estava em Jerusalém; e todos foram dispersos pelas regiões da Judeia, e de Samaria, exceto os apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'E alguns homens devotos levaram juntos a Estêvão para enterrá-lo,e fizeram grande pranto por causa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'E Saulo tentava destruir a igreja, entrando nas casas, e puxando a homens e mulheres, entregava-os à prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Os que, pois, estavam dispersos, passavam anunciando a palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'E Filipe, tendo descido à cidade de Samaria, pregava-lhes a Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'E as multidões prestavam atenção em concordância às coisas que eram ditas por Filipe, ao ouvirem e verem os sinais que ele fazia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Porque os espíritos imundos, clamando em alta voz, saíam de muitos que os tinham; e muitos paralíticos e aleijados foram curados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'E havia grande alegria naquela cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'E havia um certo homem, de nome Simão, que antes naquela cidade usava de magia, e fazia o povo de Samaria ficar admirado, dizendo de si mesmo ser alguém grande;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'A quem eles todos davam atenção, desde o menor até o maior, diziam: Este é o grande poder de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'E davam atenção a ele, porque com suas magias ele há muito tempo tinha lhes causado admiração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Mas quando creram em Filipe, que lhes anunciava o Evangelho do Reino de Deus, e o nome de Jesus Cristo, eles foram batizados, tanto homens como mulheres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'E até mesmo Simão creu; e tendo sido batizado, ele continuou com Filipe; e vendo os sinais e maravilhas que eram feitas, ele ficou admirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'E os apóstolos que estavam em Jerusalém, ao ouvirem que Samaria tinha recebido a palavra de Deus, enviaram-lhes a Pedro e a João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Os quais, tendo descido, oraram por eles, para que recebessem ao Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, '(Porque ainda sobre nenhum deles tinha descido; mas somente tinham sido batizados no nome do Senhor Jesus).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Então puseram as mãos sobre eles, e receberam o Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'E Simão ao ver que pela imposição das mãos dos apóstolos se dava o Espírito Santo, ofereceu-lhes dinheiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Dizendo: Dai também a mim este poder, que sobre qualquer um em quem eu puser as mãos, receba o Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Mas Pedro lhe disse: Teu dinheiro seja contigo para perdição, porque pensaste que o dom de Deus pudesse ser obtido por meio de dinheiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Tu não tens parte nem porção nesta palavra; porque teu coração não é correto diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Arrepende-te, pois, desta tua maldade, e ora a Deus, para que talvez este pensamento de teu coração te seja perdoado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Porque eu vejo que tu estás em fel amargo, e atado em injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Mas respondendo Simão, disse: Orai vós por mim ao Senhor, para que nada do que dissestes venha sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Tendo eles pois dado testemunho e falado a palavra do Senhor, voltaram a Jerusalém, e em muitas aldeias dos samaritanos anunciaram o Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'E um anjo do Senhor falou a Filipe, dizendo: Levanta-te, e vai para o sul, ao caminho que desce de Jerusalém para Gaza, que é deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'E ele levantou-se, e foi, e eis que um homem etíope, eunuco, administrador subordinado a Candace, a rainha dos etíopes, que estava sobre o controle de todos os bens dela, tinha vindo a Jerusalém para adorar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'E ele estava voltando, sentado em sua carruagem, e lia ao profeta Isaías.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'E o Espírito disse a Filipe: Aproxima-te, e ajunta-te a esta carruagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'E Filipe, correndo, ouviu que ele estava lendo ao profeta Isaías, e disse: Tu entendes o que estás lendo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'E ele disse: Como eu poderia, se alguém não me ensinar? E pediu a Filipe que subisse e se sentasse com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'E o lugar da Escritura que ele estava lendo era este: Como ovelha ele foi levado ao matadouro, e como um cordeiro mudo fica diante do que o tosquia, assim também ele não abriu sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Em sua humilhação foi tirado seu julgamento; e quem anunciará sua geração? Porque da terra sua vida é tirada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'E respondendo o eunuco a Filipe, disse: Eu te rogo, de quem o profeta diz isto? De si mesmo, ou de alguém outro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'E Filipe, abrindo sua boca, e começando desta escritura, anunciou-lhe o Evangelho de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'E enquanto eles iam caminhando, chegaram a uma certa porção de água; e o eunuco disse: Eis aqui água; o que me impede de ser batizado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'E Filipe disse: Se tu crês de todo coração, então é lícito;E respondendo ele, disse: Creio que Jesus Cristo é o Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'E ele mandou parar a carruagem; e desceram ambos à água, tanto Filipe como o eunuco; e ele o batizou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'E quando eles subiram da água, o Espírito do Senhor arrebatou a Filipe, e o eunuco não mais o viu, porque ele foi em seu caminho com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Mas Filipe se achou em Azoto; e passando, anunciava ao Evangelho em todas as cidades, até que veio a Cesareia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'E Saulo, ainda assoprando ameaças e mortes contra os discípulos do Senhor, foi ao chefe dos sacerdotes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'E pediu-lhe cartas para Damasco, para as sinagogas, para que se achasse alguns deste caminho, tanto homens como mulheres, ele os trouxesse presos a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'E indo, aconteceu que chegando perto de Damasco, repentinamente brilhou ao redor dele uma luz do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'E caindo em terra, ouviu ma voz lhe dizendo: Saulo, Saulo, por que me persegues?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'E ele disse: Quem és, Senhor?E o Senhor disse: Eu sou Jesus, a quem tu persegues; duro é para ti dar coices contra os aguilhões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'E ele, tremendo e atônito, disse: Senhor, que queres que eu faça?E o Senhor lhe disse: Levanta-te, e entra na cidade; e ali te será dito o que deves fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'E os homens que viajavam com ele pararam emudecidos, ouvindo, de fato, a voz, porém não vendo ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'E Saulo se levantou da terra e, tendo aberto seus olhos, não via ninguém; e sendo guiado pela mão, levaram-no a Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'E ele estava três dias sem ver; e não comeu, nem bebeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'E havia em Damasco um certo discípulo, de nome Ananias; e disse-lhe o Senhor em visão: Ananias!E ele respondeu: Eis-me aqui, Senhor!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'E o Senhor lhe disse: Levanta-te, e vai a rua chamada Direita, e pergunta na casa de Judas por um chamado Saulo, de Tarso; porque que ele ora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'E ele viu em visão que um homem, de nome Ananias, entrava, e sobre ele punha a mão, para que voltasse a ver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'E Ananias respondeu: Senhor, eu ouvi de muitos sobre este homem, quantos males ele tem feito aos teus santos em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'E aqui ele tem poder dos chefes dos sacerdotes para prender a todos os que invocam o teu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mas o Senhor lhe disse: Vai, porque este me é um vaso escolhido para levar meu nome diante dos gentios, e dos reis, e dos filhos de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Porque eu mostrarei a ele o quanto ele deve sofrer por causa do meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'E Ananias foi, e entrou na casa; e pondo as mãos sobre ele, disse: Irmão Saulo, o Senhor, que é Jesus, aquele que apareceu a ti no caminho, me enviou para que tu voltes a ver, e sejas cheio do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'E logo lhe caíram como que escamas dos olhos, e imediatamente voltou a ver; e levantando-se, foi batizado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'E ao comer, ele se fortaleceu. E Saulo ficou alguns dias com os discípulos que estavam em Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'E logo nas sinagogas pregava a Cristo, dizendo que aquele era o Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'E todos os que o ouviam ficavam admirados, e diziam: Não é este aquele que em Jerusalém tentava destruir aos que invocavam este nome? E não foi para isso que ele veio aqui, para os levar presos aos chefes dos sacerdotes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Mas Saulo se esforçava muito mais, e confundia aos judeus que habitavam em Damasco, provando que aquele era o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'E passados vários dias, os judeus tiveram conselho entre si para o matarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Mas as ciladas deles foram conhecidas por Saulo; e eles vigiavam as portas, tanto de dia como de noite, para poderem matá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Porém os discípulos, tomando-o de noite, levaram-no abaixo pelo muro em um cesto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'E Saulo, tendo vindo a Jerusalém, procurava se juntar aos discípulos; mas todos tinham medo dele, não crendo que fosse discípulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Mas Barnabás, tomando-o consigo, trouxe -o aos apóstolos, e contou-lhes como no caminho tinha visto ao Senhor, e tinha lhe falado, e como em Damasco tinha falado ousadamente no nome de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'E ele estava junto deles, entrando e saindo em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'E falando ousadamente no nome do Senhor Jesus; falava e discutia também contra os gregos; mas eles procuravam matá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'E os irmãos, ao perceberem isto, o levaram até Cesareia, e o enviaram a Tarso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Então as igrejas por toda a Judeia, e Galileia, e Samaria, tinham paz, e eram edificadas; e andando no temor do Senhor, e na consolação do Espírito Santo, se multiplicavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'E aconteceu que, Pedro, passando por todos os lugares, veio também aos santos que habitavam em Lida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'E ali ele achou a um certo homem chamado Enéas, que havia oito anos que jazia numa cama, que era paralítico.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'E Pedro lhe disse: Enéas, Jesus Cristo te cura; levanta-te, e faz tua cama. E logo ele se levantou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'E todos os que habitavam em Lida e Sarona o viram, os quais se converteram ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'E havia em Jope uma certa discípula, de nome Tabita, que traduzido se diz Dorcas. Esta estava cheia de boas obras e doações que ela fazia aos necessitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'E aconteceu naqueles dias, que tendo ela ficado doente, morreu; e tendo a lavado, puseram-na no compartimento superior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'E como Lida era perto de Jope, os discípulos, ao ouvirem que Pedro estava ali, mandaram-lhe dois homens, rogando -lhe que não demorasse a vir a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'E Pedro, tendo se levantado, foi com eles; o qual chegou, e o levaram ao compartimento superior, e todas as viúvas o rodearam, chorando, e mostrando -lhe as túnicas e roupas que Dorcas tinha feito quando estava com elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Mas Pedro, pondo para fora a todas; pôs-se de joelhos, e orou; e virando-se para o corpo, disse: Tabita, levanta-te;E ela abriu seus olhos, e vendo a Pedro, sentou-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'E ele, dando-lhe a mão, levantou-a; e tendo chamado aos santos, e às viúvas, apresentou-a viva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'E isto ficou conhecido por toda Jope, e muitos creram no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'E aconteceu que ele ficou muitos dias em Jope, com um certo Simão curtidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'E havia um certo homem em Cesareia, de nome Cornélio, centurião, do esquadrão chamado Italiano;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Devoto, e temente a Deus, com toda a sua casa; e que fazia muitas doações ao povo, e continuamente orava a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Ele viu claramente em visão, cerca da hora nona do dia, a um anjo de Deus, que vinha a ele, e lhe dizia: Cornélio!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'E ele, olhando-lhe atentamente, e muito atemorizado, disse: O que é, Senhor?E disse-lhe: Tuas orações e doações subiram à memória diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'E agora envia homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Este está hospedado na casa de um Simão curtidor, cuja casa é junto ao mar; este te dirá o que deves fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'E tendo partido o anjo que falava com Cornélio, ele chamou a dois de seus servos, e a um soldado devoto, dos que permaneciam continuamente com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'E tendo lhes contado tudo, enviou-os a Jope.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'E no dia seguinte, enquanto estes iam pelo caminho, e chegando perto da cidade, Pedro subiu ao telhado para orar, quase à hora sexta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'E tendo ele fome, quis comer; e enquanto estavam lhe preparando, caiu sobre ele um êxtase.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'E ele viu o céu aberto, e descia a ele um certo objeto, como um grande lençol, amarrado pelas quatro pontas, e abaixando-se à terra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Em que havia de todos os animais quadrúpedes da terra, e animais selvagens, e répteis, e aves do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'E veio-lhe uma voz, dizendo: Pedro, mata e come.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Mas Pedro disse: De maneira nenhuma, Senhor; porque nunca comi coisa alguma ordinária ou impura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'E a voz voltou a dizer,pela segunda vez: O que Deus purificou, não faças tu como se fosse ordinário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'E isto aconteceu três vezes; e o objeto voltou a ser recolhido acima ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'E enquanto Pedro estava pensando perplexo consigo mesmo o que seria aquela visão que ele tinha visto, eis que os homens que tinham sido enviados por Cornélio, perguntando pela casa de Simão, pararam à porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'E chamando, perguntaram se Simão, que tinha por sobrenome Pedro, estava hospedado ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'E estando Pedro pensando naquela visão, o Espírito lhe disse: Eis que três homens te buscam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Então levanta-te, desce, e vai com eles, sem duvidar; porque eu os enviei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'E Pedro, tendo descido aos homens que tinham lhe sido enviados por Cornélio, disse: Eis que eu sou a quem buscais; qual é o motivo pelo qual estais aqui?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'E eles disseram: Cornélio, que é centurião, homem justo e temente a Deus, e que tem bom testemunho de toda a nação dos judeus, foi revelado por um santo anjo para te chamar até a casa dele, e ouvir de tuas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Então chamando-os para dentro, recebeu-os em casa. Mas no dia seguinte, Pedro foi com eles; e foram com ele alguns dos irmãos de Jope.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'E no dia seguinte chegaram a Cesareia. E Cornélio estava esperando por eles, tendo chamado a seus parentes e amigos mais íntimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'E sucedeu que, ao Pedro entrar, Cornélio se encontrou com ele, e caindo aos pés dele, adorou-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Mas Pedro o levantou, dizendo: Levanta-te; eu mesmo também sou um ser humano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'E tendo conversado com ele, entrou; e achou a muitos que ali tinham se reunido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'E disse-lhes: Vós sabeis como não é lícito a um homem judeu juntar-se de estrangeiros, ou aproximar-se deles; mas Deus me mostrou que a ninguém chame de ordinário ou impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Portanto eu, tendo sido chamado, vim sem qualquer oposição de minha parte. Então eu pergunto: por que motivo me mandastes chamar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'E Cornélio disse: Há quatro dias que, até esta hora eu estava jejuando, e orava à hora nona em minha casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'E eis que um homem se pôs diante de mim com uma roupa brilhante, e disse: Cornélio, tura oração tem sido ouvida, e tuas doações têm sido lembradas diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Envia pois a Jope, e manda chamar a Simão, que tem por sobrenome Pedro; este se hospeda na casa de Simão o curtidor, junto ao mar; quando ele vier, falará contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Então logo eu enviei a ti; e bem fizeste em vir até aqui; agora pois estamos todos aqui presentes diante de Deus, para ouvir tudo quanto Deus tem te ordenado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'E Pedro, abrindo a boca, disse: Reconheço que é verdade que Deus não faz acepção de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Mas sim, em toda nação, aquele que o teme, e pratica a justiça, este lhe é agradável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'A palavra que Deus enviou aos filhos de Israel, anunciando o Evangelho da paz por meio de Jesus Cristo; este é o Senhor de todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vós sabeis da palavra que veio por toda a Judeia, começando desde a Galileia, depois do batismo que João pregou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'E sobre Jesus de Nazaré; como Deus o ungiu com o Espírito Santo, e com poder; o qual percorreu os lugares fazendo o bem, e curando a todos os oprimidos pelo diabo; porque Deus era com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'E nós somos testemunhas de todas as coisas que ele fez; tanto na terra dos judeus, como em Jerusalém; ao qual mataram, pendurando -o em um madeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'A este Deus ressuscitou ao terceiro dia, e fez com que fosse manifesto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Não a todo o povo, mas sim a testemunhas determinadas por Deus com antecedência: a nós, que juntamente com ele comemos e bebemos, depois dele ter ressuscitado dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'E ele nos mandou pregar ao povo, e dar testemunho de que ele é o que foi ordenado por Deus para ser Juiz dos vivos e dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'A este todos os profetas dão testemunho, de que todos os que nele crerem receberão perdão dos pecados por meio do seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'E estando Pedro ainda falando estas palavras, o Espírito Santo caiu sobre todos os que ouviam a palavra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'E os crentes que eram da circuncisão, tantos quantos tinham vindo com Pedro, ficaram muito admirados de que também sobre os gentios fosse derramado o dom do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Porque eles os ouviam falar em diversas línguas, e a engrandecer a Deus. Então Pedro respondeu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Por acaso pode alguém impedir a água, para que não sejam batizados estes, que também, assim como nós, receberam o Espírito Santo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'E mandou que fossem batizados no nome do Senhor. Então lhe pediram que continuasse com eles por alguns dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'E os apóstolos, e os irmãos que estavam na Judeia, ouviram que também os gentios receberam a palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'E quando Pedro subiu a Jerusalém, discutiam contra ele os que eram da circuncisão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Dizendo: Tu entraste na casa de homens incircuncisos, e comeste com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Mas Pedro começou a lhes explicar tudo em ordem, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Eu estava orando na cidade de Jope, e vi em êxtase uma visão: um certo objeto que descia como um grande lençol, pelas quatro pontas abaixado desde o céu, e vinha até mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'No qual, olhando eu com atenção, considerei e vi quatro quadrúpedes da terra, e animais selvagens, e répteis, e aves do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'E eu ouvi uma voz que me dizia: Levanta-te Pedro, mata e come.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Mas eu disse: De maneira nenhuma, Senhor; porque nunca comi coisa alguma ordinária, nem coisa imunda entrou em minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'E a voz me respondeu do céu pela segunda vez: O que Deus purificou, não o faças tu como ordinário.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'E isto aconteceu por três vezes; e voltou-se tudo a recolher acima ao céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'E eis que logo três homens, enviados a mim de Cesareia, pararam junto à casa onde eu estava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'E o Espírito me disse que eu fosse com eles, sem duvidar; e também estes seis irmãos foram comigo, e entramos na casa daquele homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'E ele nos contou como tinha visto um anjo estar em sua casa, e tinha lhe dito: Envia alguns homens a Jope, e manda chamar a Simão, que tem por sobrenome Pedro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'O qual te falará palavras, em que tu sejas salvo, e também toda a tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'E quando comecei a falar, caiu o Espírito Santo sobre eles, assim como também no princípio tinha caído sobre nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'E eu me lembrei da palavra do Senhor, como ele tinha dito: Verdadeiramente João batizou com água, mas vós sereis batizados com o Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Portanto, se Deus deu a eles igual dom, assim como também a nós, que temos crido no Senhor Jesus Cristo; quem era eu, pois, para que pudesse proibir a Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'E ao ouvirem estas coisas, se acalmaram, e glorificavam a Deus, dizendo: Portanto também aos gentios Deus deu arrependimento para a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'E os que foram dispersos por causa da perseguição que aconteceu por causa de Estêvão, passaram até a Fenícia, e Chipre, e Antioquia; não falando a ninguém a palavra, a não ser somente aos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'E havia deles alguns homens cipriotas e cirenenses, os quais ao entrarem em Antioquia, falaram aos gregos, anunciando o Evangelho do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'E a mão do Senhor era com eles, e um grande número creu, e se converteu ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'E esta notícia sobre eles chegou aos ouvidos da igreja que estava em Jerusalém; e enviaram a Barnabé, para ir até Antioquia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'O qual, ao chegar lá,e tendo visto a graça de Deus, alegrou-se; e exortou a todos, para que com o propósito do coração permanecessem no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Porque ele era um bom homem, e cheio do Espírito Santo, e de fé; e uma grande multidão foi acrescentada ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'E Barnabé foi para Tarso, para buscar a Saulo; e achando-o, trouxe-o a Antioquia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'E sucedeu que, durante um ano completo eles se congregaram naquela igreja, e ensinavam a uma grande multidão; e em Antioquia os discípulos foram chamados pela primeira vez de cristãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'E naqueles dias desceram de Jerusalém alguns profetas a Antioquia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'E levantando-se um deles, por nome Ágabo, declarou pelo Espírito, que estava para haver uma grande fome em todo o mundo; que veio a acontecer no tempo de Cláudio César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'E os discípulos determinaram de cada um, conforme o que pudesse, mandar algum socorro para serviço dos irmãos que habitavam na Judeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'O que também fizeram, enviando -o aos anciãos pela mão de Barnabé e de Saulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'E por aquele mesmo tempo o rei Herodes pôs as mãos para maltratar a alguns da igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'E matou a Tiago, o irmão de João, pela espada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'E vendo que isto agradava aos judeus, ele fez ainda mais, para também prender a Pedro (e eram os dias dos pães sem fermento).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Do qual, também detendo, lançou-o na prisão, entregando -o a quatro quaternos de soldados, que o guardassem; pretendendo tirá-lo para mostrá-lo ao povo depois da Páscoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Então Pedro era mantido na prisão; mas a igreja fazia fervorosa oração a Deus por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'E quando Herodes estava para tirá-lo para apresentá-lo,naquela mesma noite Pedro estava dormindo entre dois soldados, acorrentado com duas correntes; e os guardas diante da porta guardavam a prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'E eis que veio acima um anjo do Senhor, e uma luz brilhou na prisão; e tocando em Pedro em sua lateral, despertou-o, dizendo; Levanta-te, depressa!E as correntes caíram de suas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'E o anjo lhe disse: Arruma-te, e amarra as tuas sandálias.E ele fez assim. E disse-lhe: Põe tua capa sobre ti, e segue-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'E saindo, o seguia; e não sabia que era verdade o que se fazia pelo anjo, mas pensava que estava tendo alguma visão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'E ao passarem a primeira e a segunda guarda, chegaram à porta de ferro, que leva à cidade, a qual foi aberta por si mesma; e tendo saído, foram a uma rua, e logo o anjo partiu dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'E tendo Pedro voltado a si, disse: Agora eu sei verdadeiramente que o Senhor enviou a seu anjo, e me livrou da mão de Herodes, e de toda a expectativa do povo dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'E ele, reconhecendo isto,foi à casa de Maria, a mãe de João, que tinha por sobrenome Marcos, onde muitos estavam juntos, e oravam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'E Pedro, tendo batido a porta da entrada,veio uma moça de nome Rode, para escutar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'E ela, reconhecendo a voz de Pedro, de alegria não abriu a porta da entrada, em vez disso ela correu para dentro, e anunciou que Pedro estava fora à porta da entrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'E lhe disseram: Tu estás delirando.Mas ela, insistindo que assim era. E eles diziam: É o anjo dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Mas Pedro continuava a bater; e ao abrirem, viram-no, e ficaram espantados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Mas ele, fazendo-lhes gestos para que calassem, contou-lhes como o Senhor tinha lhe tirado da prisão, e disse: Anunciai isto a Tiago e aos irmãos.E tendo saído, foi para outro lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'E vindo o dia, havia não pouca perturbação entre os soldados, sobre o que, pois, tinha acontecido com Pedro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'E quando Herodes o buscou, e não o achou, tendo investigado aos guardas, mandou que eles fossem levados para serem mortos. E partindo da Judeia para Cesareia, ficou ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'E Herodes estava extremamente irritado com os de Tiro e de Sidom; porém eles, vindo em concordância até ele, e persuadindo a Blasto, que era o camareiro do rei, pediram paz, porque a terra deles dependia dos alimentos da terra do rei Herodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'E num dia marcado, Herodes vestiu roupas reais, e sentando no tribunal, fez-lhes um discurso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'E o povo exclamava: Voz de deus, e não de homem!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'E no mesmo instante um anjo do Senhor o feriu, porque ele não deu a glória a Deus; e tendo sido comido por vermes, deixou de respirar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'E a palavra de Deus crescia, e se multiplicava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'E Barnabé e Saulo, tendo cumprido aquele serviço, voltaram a Jerusalém, tomando também consigo a João, o que tinha por sobrenome Marcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'E havia em Antioquia, na igreja que estava ali, alguns profetas e mestres: Barnabé e Simeão, chamado Níger, e Lúcio cireneu, e Manaem, que tinha sido criado na infância junto com Herodes o Tetrarca, e Saulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'E tendo eles prestado serviço ao Senhor, e jejuado, o Espirito Santo disse: Separai-me a Barnabé e a Saulo, para a obra para a qual eu os tenho chamado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Então jejuando, e orando, e pondo as mãos sobre eles, os despediram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Portanto estes, enviados pelo Espírito Santo, desceram a Selêucia, e dali navegaram para o Chipre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'E tendo chegado a Salamina, anunciavam a palavra de Deus nas sinagogas dos judeus; e também tinham a João como trabalhador para os auxiliar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'E tendo eles atravessado a Ilha até Pafo, acharam a um certo mago, falso profeta, judeu, cujo nome era Barjesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'O qual estava com o procônsul Sérgio Paulo, homem prudente. Este, tendo chamado a si a Barnabé, e a Saulo, procurava muito ouvir a palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Mas resistia-lhes Elimas, o mago (que assim significa seu nome), procurando afastar o procônsul da fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Mas Saulo, que também se chama Paulo, cheio do Espírito Santo, e olhando fixamente para ele, disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Ó filho do diabo, cheio de toda enganação e toda malícia, inimigo de toda justiça, não cessarás de perverter os corretos caminhos do Senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'E agora, eis que a mão do Senhor está contra ti, e serás cego, não vendo o sol por algum tempo.E no mesmo instante caiu sobre ele um embaçamento, e trevas; e ele, andando ao redor, procurava alguém que o guiasse pela mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Então o procônsul, vendo o que tinha acontecido, creu, espantado pela doutrina do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'E tendo partido de Pafo, Paulo e os que estavam com ele foram a Perges, cidade da Panfília. Mas João, separando-se deles, voltou a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'E eles, tendo passado de Perges, vieram a Antioquia, cidade da Pisídia; e ao entrarem na sinagoga n um dia de sábado, sentaram-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'E depois da leitura da Lei e dos profetas, os chefes da sinagoga lhes mandaram, dizendo: Homens irmãos, se em vós há alguma palavra de exortação ao povo, dizei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'E Paulo, levantando-se e fazendo gesto com a mão, disse: Homens israelitas, e vós os que temeis a Deus, ouvi:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'O Deus deste povo de Israel escolheu a nossos pais, e exaltou ao povo, sendo eles estrangeiros na terra do Egito, e com o braço levantando, ele os tirou dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'E pelo tempo de cerca de quarenta anos, ele suportou os costumes deles no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'E tendo destruído a sete nações na terra de Canaã, repartiu-lhes as terras por sorte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'E depois disto, cerca de quatrocentos e cinquenta anos, ele lhes deu juízes, até o profeta Samuel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'E depois disto, pediram a um Rei, e ele lhes deu a Saul, filho de Quis, homem da tribo de Benjamim, durante quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'E tirando a este, levantou-lhes por rei a Davi, ao qual também deu testemunho, e disse: Eu achei a Davi, filho de Jessé, um homem conforme o meu coração, que fará toda a minha vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Da descendência deste, conforme a promessa, Deus levantou a Jesus por Salvador de Israel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Tendo João primeiro, antes de sua vinda, pregado o batismo de arrependimento a todo o povo de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Mas quando João cumpriu sua carreira, disse: Quem vós pensais que eu sou? Eu não sou o Cristo,mas eis que após mim vem aquele, cujas sandálias dos pés eu não sou digno de desatar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Homens irmãos, filhos da descendência de Abraão, e os que dentre vós temem a Deus, a vós é enviada a palavra desta salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Porque os que habitavam em Jerusalém, e seus líderes, não conhecendo a este, ao condenarem -no,cumpriram as vozes dos profetas, que são lidas todos os sábados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'E mesmo achando nenhum motivo para morte, pediram a Pilatos que fosse morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'E tendo eles cumprido todas as coisas que estavam escritas sobre ele, tirando -o do madeiro, puseram -no na sepultura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Mas Deus o ressuscitou dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'O qual foi visto durante muitos dias pelos que haviam subido com ele da Galileia, que são suas testemunhas para com o povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'E nós vos anunciamos o Evangelho da promessa que foi feita aos pais; ao qual Deus já nos cumpriu a nós, filhos deles, ressuscitando a Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Assim como está escrito no salmo segundo: Tu és meu Filho, hoje eu te gerei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'E quanto a que o ressuscitasse dos mortos, para nunca mais voltar à corrupção, assim disse: Eu vos darei as fiéis beneficências de Davi.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Por isso que também em outro salmo ele diz: Não permitirás que teu Santo veja corrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Porque na verdade, tendo Davi servido ao conselho de Deus, morreu, foi posto junto a seus pais, e viu corrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Mas aquele a quem Deus ressuscitou nenhuma corrupção viu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Seja-vos pois conhecido, homens irmãos, que por este vos é anunciado o perdão dos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'E de tudo o que pela lei de Moisés não pudestes ser justificados, neste é justificado todo aquele que crê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Então vede, para que não venha sobre vós o que está escrito nos livros dos profetas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Vós desprezadores, vede e espantai-vos, e desaparecei-vos; porque eu opero obra em vossos dias, obra na qual não crereis, se alguém vos contar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'E tendo os judeus saído da sinagoga,os gentios rogaram -lhes que no sábado seguinte eles lhes falassem estas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'E tendo terminado a reunião da sinagoga, muitos dos judeus, e dos religiosos prosélitos, seguiram a Paulo e a Barnabé; os quais, falando-lhes, exortavam-nos a permanecerem na graça de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'E no sábado seguinte ajuntou-se quase toda a cidade para ouvir a palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Mas os Judeus, ao verem as multidões, ficaram cheios de inveja, e falavam contrariamente ao que Paulo dizia, falando contrariamente e blasfemando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Mas Paulo e Barnabé, usando de ousadia, disseram: Era necessário que a palavra de Deus fosse primeiro falada a vós; mas já que a rejeitais, e não vos julgais dignos da vida eterna, eis que nós nos viramos em direção aos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Porque assim o Senhor nos mandou, dizendo: Eu te pus como luz para os gentios, para que tu sejas como salvação até às extremidades da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'E os gentios, tendo ouvido isto,alegraram-se, e glorificavam ao Senhor; e creram todos quantos estavam determinados para a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'E a palavra do Senhor era divulgada por toda aquela região.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Mas os judeus incitaram algumas mulheres devotas e honradas, e aos líderes da cidade, e levantaram perseguição contra Paulo e Barnabé, e os expulsaram de seus limites.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Mas eles, sacudindo contra eles o pó dos seus pés, vieram a Icônio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'E os discípulos se enchiam de alegria e do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'E aconteceu em Icônio, que entraram juntos na sinagoga dos judeus, e falaram de tal maneira que creu uma grande multidão, tanto de judeus como de gregos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Mas os judeus incrédulos incitaram e irritaram os ânimos dos gentios contra os irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Então eles ficaram ali por muito tempo, falando ousadamente no Senhor, o qual dava testemunho à palavra de sua graça, concedendo que sinais e milagres fossem feitos pelas mãos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'E a multidão da cidade se dividiu; e uns eram a favor dos judeus, e outros a favor dos apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'E fazendo-se uma rebelião, tanto de judeus como de gentios, juntos com seus líderes, para falarem mal deles, e os apedrejarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'E eles, sabendo disto,fugiram para as cidades da Licaônia, chamadas Listra e Derbe; e à região ao redor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'E ali eles anunciavam ao Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'E um certo homem em Listra estava sentado, tendo incapacidade nos pés, aleijado desde o ventre de sua mãe, que nunca tinha andado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Este ouviu Paulo falando; o qual, olhando com atenção, e vendo que ele tinha fé para ser curado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Disse em alta voz: Levanta-te direito sobre teus pés.E ele saltou e andou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'E as multidões, vendo o que Paulo tinha feito, levantaram suas vozes, dizendo em língua licaônica: Os deuses se fizeram semelhantes a homens, e desceram até nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'E chamaram a Barnabé de Júpiter; e a Paulo, de Mercúrio; porque este era o líder ao falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'E o sacerdote de Júpiter, que estava diante da cidade deles, trazendo touros e grinaldas à entrada da porta, ele, junto com as companhias, queria oferecer sacrifício a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Mas os apóstolos Barnabé e Paulo, ao ouvirem isto,rasgaram suas roupas, e saltaram entre a multidão, clamando,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'E dizendo: Homens, por que fazeis estais coisas? Também nós somos homens como vós, sujeitos às mesmas emoções; e vos anunciamos o Evangelho para que vos convertais destas vaidades para o Deus vivo, que fez o céu, a terra, o mar, e tudo quanto neles há.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'O qual nas gerações passadas deixou os os gentios andarem seus próprios caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Ainda que, contudo, não tenha deixado a si mesmo sem testemunho, fazendo o bem desde o céu, dando-nos chuvas, e tempos frutíferos, e enchendo nossos corações de alimento e alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'E tendo disto isto, apenas detiveram as multidões de que não fizessem sacrifícios a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Mas vieram alguns judeus de Antioquia, e de Icônio, e persuadiram a multidão; e apedrejando a Paulo, arrastaram -no para fora da cidade, pensando que ele estivesse morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Mas, tendo os discípulos ficado ao seu redor, ele se levantou, e entrou na cidade; e no dia seguinte saiu com Barnabé para Derbe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'E tendo anunciado o Evangelho àquela cidade, e feito muitos discípulos, eles voltaram a Listra, e a Icônio, e a Antioquia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Confirmando os ânimos dos discípulos, e exortando-os para que permanecessem na fé, e que nos é necessário entrar no Reino de Deus por meio de muitas aflições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'E tendo escolhido por votação anciãos para cada igreja, orando com jejuns, eles foram enviados ao Senhor, no qual tinham crido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'E tendo passado por Pisídia, vieram à Panfília.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'E tendo falado a palavra em Perges, desceram a Atália.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'E dali navegaram para Antioquia, onde tinham sido encomendados à graça de Deus para a obra que eles já tinham cumprido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'E ao chegarem, e reunirem a igreja, relataram quão grandes coisas Deus tinha feito com eles; e como ele tinha aberto a porta da fé aos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'E eles ficaram ali não pouco tempo com os discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'E alguns que tinham descido da Judeia ensinavam aos irmãos, dizendo: Se vós não vos circuncidardes conforme o costume de Moisés, não podeis ser salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Então, havendo não pequena resistência e confronto de Paulo e Barnabé contra eles, ordenaram que Paulo, Barnabé e alguns outros deles subissem aos apóstolos e aos anciãos a Jerusalém sobre esta questão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Então sendo eles preparados para a viagem e despedidos pela igreja, passaram pela Fenícia e Samaria, contando sobre a conversão dos gentios; e davam grande alegria a todos os irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'E tendo chegado a Jerusalém, eles foram recebidos pela igreja, e pelos apóstolos e anciãos; e lhes anunciaram quão grandes coisas Deus tinha feito com eles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Mas que alguns do grupo dos fariseus que tinham crido, levantaram-se, dizendo que era necessário circuncidá-los, e mandar -lhes que guardem a Lei de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'E os apóstolos e anciãos se reuniram para dar atenção a este assunto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'E havendo muita discussão, Pedro se levantou, e lhes disse: Homens irmãos, vós sabeis que há muito tempo Deus meu escolheu entre nós, para que por minha boca os gentios ouvissem a palavra do Evangelho, e cressem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'E Deus, que conhece os corações, deu-lhes testemunho, dando-lhes o Espírito Santo, assim como também a nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'E nenhuma diferença fez entre nós e eles, purificando seus corações pela fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Então agora, por que tentais a Deus, pondo um jugo sobre o pescoço dos discípulos; que nem nossos pais, nem nós podemos levar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Mas cremos que, pela graça do Senhor Jesus Cristo, nós somos salvos, assim como também eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'E toda a multidão se calou; e ouviram a Barnabé e a Paulo, que contavam quão grandes sinais e milagres Deus tinha feito por meio deles entre os gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'E tendo estes se calado, Tiago respondeu, dizendo: Homens irmãos, ouvi-me:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simão informou como primeiro Deus visitou aos gentios, para tomar deles um povo para seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'E com isso concordam as palavras dos profetas, como está escrito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Depois disto eu voltarei, e reconstruirei o tabernáculo de Davi, que caído está; e reconstruirei de suas ruínas, e voltarei a levantá-lo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Para que o resto da humanidade busque ao Senhor, e todos os gentios sobre os quais meu nome é invocado, diz o Senhor, que faz todas estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'São conhecidas por Deus desde a antiguidade todas as suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Portanto eu julgo que aqueles que dos gentios se convertem a Deus não devem ser perturbados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Mas que lhes escrevamos para que se abstenham das contaminações dos ídolos, e do pecado sexual, e da carne sufocada, e do sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Porque Moisés, desde as gerações antigas, tem em cada cidade quem o pregue nas sinagogas, sendo lido todo sábado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Então pareceu bem aos apóstolos, e aos anciãos, com toda a igreja, eleger deles alguns homens, para serem enviados com Paulo e Barnabé a Antioquia: Judas, que tinha por sobrenome Barsabás; e a Silas, homens líderes entre os irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'E escreveram por meio deles o seguinte: Os apóstolos e os anciãos, e os irmãos – para os irmãos dentre os gentios, que estão em Antioquia, Síria e Cilícia; saudações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Dado que ouvimos que alguns dos que saíram de nós vos perturbaram com palavras, e causaram incômodo a vossas almas, dizendo que deveis vos circuncidar e guardar a Lei, aos quais não mandamos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Pareceu-nos bem, reunidos em concordância, escolher alguns homens, e enviá-los até vós, com nossos amados Barnabé e Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Homens que têm arriscado suas vidas pelo nome de nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Então enviamos a Judas e a Silas, os quais vos dirão as mesmas coisas pessoalmente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Porque pareceu bem ao Espírito Santo e a nós, de nenhuma carga a mais vos impor, a não ser estas coisas necessárias:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Que vos abstenhais das coisas sacrificadas aos ídolos, do sangue, da carne sufocada, e do pecado sexual; das quais, se vos guardardes, fareis bem. Que o bem vos suceda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Sendo, pois, eles despedidos, vieram a Antioquia, e reunindo a multidão, entregaram a carta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'E ao lerem, alegraram-se pela consolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'E então Judas e Silas, sendo também profetas, com muitas palavras exortaram e firmaram aos irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'E ficando ali por algum tempo, permitiram que voltassem em paz dos irmãos para os apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Mas a Silas pareceu bem continuar ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'E Paulo e Barnabé ficaram em Antioquia, ensinando e evangelizando, com também muitos outros, a palavra do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'E depois de alguns dias, Paulo disse a Barnabé: Voltemos a visitar a nossos irmãos em cada cidade onde tenhamos anunciado a palavra do Senhor, para ver como estão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'E Barnabé aconselhou para que tomassem consigo a João, chamado Marcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Mas Paulo achou adequado que não tomassem consigo a aquele que desde a Panfília tinha se separado deles, e não tinha ido com eles para aquela obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Houve então entre eles tal discórdia, que eles se separaram um do outro; e Barnabé, tomando consigo a Marcos, navegou para o Chipre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Mas Paulo, escolhendo a Silas, partiu-se, enviado pelos irmãos para a graça de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'E ele passou pela Síria e Cilícia, firmando as igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'E ele veio a Derbe e Listra; e eis que estava ali um certo discípulo, de nome Timóteo, filho de uma certa mulher judia crente, mas de pai grego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Do qual era bem testemunhado pelos irmãos que estavam em Listra e Icônio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'A este Paulo quis que fosse com ele; e tomando-o, circuncidou-o, por causa dos judeus, que estavam naqueles lugares; porque todos conheciam o pai dele, que era grego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'E eles, passando pelas cidades, entregavam-lhes as ordenanças que foram determinadas pelos apóstolos e anciãos em Jerusalém, para que as guardassem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'E assim as Igrejas eram firmadas na fé, e cada dia aumentavam em número.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'E passando pela Frígia, e pela região da Galácia, foi-lhes impedido pelo Espírito Santo de falarem a palavra na Ásia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'E quando eles vieram a Mísia, tentaram ir à Bitínia; mas o Espírito não lhes permitiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'E tendo passado por Mísia, desceram a Trôade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'E uma visão foi vista por Paulo durante a noite: um homem Macedônio se pôs diante dele,rogando-lhe, e dizendo: Passa à Macedônia, e ajuda-nos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'E quando ele viu a visão, logo procuramos partir para a Macedônia, concluindo que o Senhor estava nos chamando para anunciarmos o Evangelho a eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Então, tendo navegado desde Trôade, viemos correndo caminho direto a Samotrácia, e no dia seguinte a Neápolis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'E dali a Filipos, que é a primeira cidade desta parte da Macedônia, e é uma colônia; e estivemos naquela cidade por alguns dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'E no dia de sábado saímos para fora da cidade, onde costumava ser feita oração; e tendo nos sentado, falamos às mulheres que tinham se ajuntado ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'E uma certa mulher, por nome Lídia, vendedora de púrpura, da cidade de Tiatira, que servia a Deus; ela nos ouviu; o coração da qual o Senhor abriu, para que prestasse atenção ao que Paulo dizia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'E quando ela foi batizada, e também sua casa, ela nos rogou, dizendo: Se vós tendes julgado que eu seja fiel ao Senhor, entrai em minha casa e ficai ali.E ela insistiu para conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'E aconteceu, que ao estarmos nós indo à oração, saiu ao nosso encontro uma moça que tinha espírito de pitonisa; a qual ao fazer adivinhações trazia grande lucro a seus senhores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Esta, seguindo após Paulo e nós, clamava, dizendo: Estes homens são servos do Deus Altíssimo, que nos anunciam o caminho da salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'E ela fazia isto por muitos dias. Mas Paulo, estando descontente com isto, virou-se, e disse ao espírito: Em nome de Jesus Cristo eu te mando que saias dela.E na mesma hora o espírito saiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'E os senhores dela, vendo que a esperança de lucro deles tinha ido embora, pegaram a Paulo e a Silas, e os levaram à praça, diante dos governantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'E apresentando-os aos magistrados, disseram: Estes homens perturbam nossa cidade, sendo judeus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'E eles anunciam costumes que não nos é lícito receber, nem fazer; pois somos romanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'E a multidão se levantou juntamente contra eles; e os oficiais, rasgando suas roupas, mandaram que fossem açoitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'E tendo sido lhes dado muitos açoites, os lançaram na prisão, mandando ao carcereiro que os guardasse em segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'O qual, tendo recebido tal ordem, lançou-os na cela mais interna, e prendeu-lhes os pés no tronco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'E perto da meia-noite, Paulo e Silas estavam orando, e cantando hinos a Deus; e os outros presos os escutavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'E de repente houve um terremoto tão grande que os alicerces da prisão se moviam; e logo todas as portas se abriram, e todas as correntes que prendiam a todos se soltaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'E o carcereiro, tendo acordado e visto abertas todas as portas da prisão; puxou a espada, e estava a ponto de se matar, pensando que os presos tinham fugido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Mas Paulo clamou em alta voz, dizendo: Não te faças nenhum mal, porque todos nós estamos aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'E tendo pedido luzes, saltou para dentro, e termendo muito, ele se prostrou diante de Paulo e Silas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'E levando-os para fora, disse: Senhores, o que me é necessário fazer para eu me salvar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'E eles lhe disseram: Crê no Senhor Jesus Cristo, e serás salvo, tu e a tua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'E lhe falaram da palavra do Senhor, e a todos os que estavam em sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'E ele, tomando-os consigo, naquela mesma hora da noite, lavou -lhes as feridas dos açoites, e logo foi batizado, ele e todos os seus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'E tendo os levado a sua casa, pôs comida diante deles à mesa; e alegrou-se muito, tendo crido em Deus com toda a sua casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'E sendo já de dia, os magistrados mandaram aos guardas, dizendo: Solta aqueles homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'E o carcereiro anunciou estas palavras a Paulo, dizendo: Os magistrados têm mandado vos soltar; portanto agora saí, e ide em paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Mas Paulo lhes disse: Eles nos açoitaram publicamente, e sem sermos sentenciados, sendo nós homens romanos, lançaram-nos na prisão, e agora nos lançam fora às escondidas? Assim não! Mas que eles mesmos venham e nos tirem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'E os guardas voltaram para dizer aos magistrados estas palavras; e eles temeram ao ouvirem que eram romanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'E tendo vindo, rogaram-lhes; e tirando-os, pediram -lhes que saíssem da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'E eles, tendo saído da prisão, entraram na casa de Lídia; e vendo aos irmãos, consolaram-lhes; e saíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'E viajando por Anfípolis e Apolônia, vieram a Tessalônica, onde havia uma sinagoga de judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'E Paulo, como era de seu costume, entrou a eles, e por três sábados argumentava com eles pelas Escrituras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Declarando -as,e propondo -lhes,que era necessário que o Cristo morresse, e ressuscitasse dos mortos; e que (dizia ele) este Jesus é o Cristo, a quem eu vos anuncio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'E alguns deles creram, e se ajuntaram a Paulo e Silas; e dos gregos devotos grande multidão; e não poucas das mulheres principais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Mas os judeus incrédulos, movidos de inveja, tomaram consigo alguns homens malignos dos mercados, e juntando uma multidão, tumultuaram a cidade; e atacando a casa de Jasão, procuravam trazê-los ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'E não os achando, puxaram a Jasão, e a alguns irmãos às maiores autoridades da cidade, clamando: Estes que tem perturbado ao mundo também vieram até aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Aos quais Jasão tem recolhido, e todos estes fazem contra as ordens de César, dizendo que há outro rei, chamado Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'E eles tumultuaram a multidão, e às autoridades da cidade, que ouviam estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Mas tendo recebido fiança de Jasão e dos demais, eles os soltaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'E logo os irmãos enviaram de noite a Paulo e a Silas até Bereia; os quais, ao chegarem lá, foram à sinagoga dos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'E estes foram mais nobres do que os que estavam em Tessalônica, porque os quais receberam a palavra com toda boa vontade, examinando a cada dia as escrituras, para ver se estas coisas eram assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Portanto muitos deles realmente creram, e das mulheres gregas honradas; e dos homens, não poucos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mas quando os judeus de Tessalônica souberam que também em Bereia a palavra de Deus era anunciada por Paulo, vieram também para lá, e incitaram as multidões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Mas então no mesmo instante os irmãos despediram a Paulo, para que fosse ao mar; mas Silas e Timóteo continuaram ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'E os que conduziram a Paulo, levaram-no até Atenas; e tendo recebido ordem para Silas e Timóteo, para que viessem a ele o mais rápido que pudessem,eles foram embora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'E enquanto Paulo os esperava em Atenas, seu espírito se incomodava dentro dele, ao ver a cidade tão dedicada à idolatria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Então ele disputava muito na sinagoga, com os judeus, e com os religiosos; e no mercado a cada dia, com os que vinham até ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'E alguns dos filósofos epicureus e estoicos discutiam com ele; e uns diziam: O que quer dizer este tagarela?E outros: Parece que ele é pregador de deuses estranhos.Porque ele lhes anunciava o Evangelho de Jesus e a ressurreição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'E tomando-o, trouxeram -no ao areópago, dizendo: Podemos nós saber que doutrina nova é esta que tu falas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Porque tu trazes coisas estranhas aos nossos ouvidos; então queremos saber o que isto quer dizer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(E todos os atenienses e visitantes estrangeiros não se ocupavam de nenhuma outra coisa, a não ser em dizer e ouvir alguma novidade).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'E Paulo, estando no meio do areópago, disse: Homens atenienses, eu vejo em tudo como vós sois muito religiosos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Porque enquanto eu passava pela cidade e via vossos santuários, achei também um altar, em que estava escrito: AO DEUS DESCONHECIDO. Este a quem vós prestais devoção sem conhecer, este é o que eu vos anuncio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'O Deus que fez o mundo, e todas as coisas que nele há; este, sendo Senhor do céu e da terra, não habita em tempos feitos por mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'E nem também é servido por mãos humanas; como que necessitasse de alguma coisa; porque ele é que dá a todos vida, respiração, e todas as coisas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'E de um sangue ele fez toda nação humana, para habitarem sobre a face da terra, determinando os tempos desde antes ordenados, e o limites da morada deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Para que buscassem ao Senhor, se talvez pudessem apalpá-lo e encontrá-lo,apesar dele não estar longe de cada um de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Porque nele vivemos, e nos movemos, e somos; assim como também alguns de vossos poetas disseram; porque também nós somos descendência dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Sendo então descendência de Deus, nós não devemos pensar que a divindade seja semelhante a ouro, ou a prata, ou a pedra esculpida por artifício e imaginação humana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Portanto Deus, tendo desconsiderado os tempos da vossa ignorância, agora anuncia a todos as pessoas, em todo lugar, para que se arrependam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Porque ele tem estabelecido um dia em que ele julgará ao mundo em justiça por meio do homem a quem determinou; dando certeza a todos, tendo o ressuscitado dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'E ao ouvirem da ressurreição dos mortos, alguns zombavam; e outros diziam: Nós ouviremos sobre isto de ti na próxima vez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'E assim Paulo saiu do meio deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Porém, tendo chegado alguns homens até ele, creram; entre os quais estava também Dionísio o areopagita, e uma mulher de nome Dâmaris, e outros com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'E depois disto ele partiu de Atenas, e veio a Corinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'E achando a um certo judeu, de nome Áquila, natural de Ponto, que recentemente tinha vindo da Itália, e Priscila, sua mulher (porque Cláudio tinha mandado que todos os judeus saíssem de Roma), veio até eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'E porque era do mesmo ofício, ficou com eles, e trabalhava; porque tinham o ofício de fazerem tendas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'E ele disputava na sinagoga a cada sábado; e persuadia a judeus e a gregos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'E quando Silas e Timóteo desceram da Macedônia, Paulo foi pressionado pelo Espírito, dando testemunho aos judeus de que o Cristo era Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Mas tendo eles resistido e blasfemado, ele sacudiu as roupas, e lhes disse: Vosso sangue seja sobre vossa cabeça; eu estou limpo; e a partir de agora irei aos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'E tendo saído dali, entrou na cada de um, de nome Justo, que servia a Deus, cuja casa era vizinha à sinagoga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'E Crispo, o chefe da sinagoga, creu no Senhor com toda a sua casa; e muitos dos coríntios, tendo ouvido, creram e foram batizados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'E o Senhor disse em visão de noite a Paulo: Não temas, mas fala, e não te cales.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Porque eu estou contigo, e ninguém porá mão em ti para te fazer mal, porque eu tenho muito povo nesta cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'E ele ficou ali por um ano e seis meses, ensinando entre eles a palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Mas sendo Gálio o procônsul da Acaia, os judeus se levantaram em concordância contra Paulo, e o trouxeram ao tribunal,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Dizendo: Este persuade as pessoas a servirem a Deus contra a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'E Paulo, querendo abrir a boca, Gálio disse aos judeus: Se houvesse algum mau ato ou crime grande, ó judeus, com razão eu vos suportaria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Mas se a questão é de palavra s,e de nomes, e da Lei que há entre vós, vede -o vós mesmos; porque destas coisas eu não quero ser juiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'E ele os tirou do tribunal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Mas todos os gregos, tomando a Sóstenes, o chefe da sinagoga, feriram -no diante do tribunal; e a nada destas coisas Gálio dava importância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'E Paulo, ficando ali ainda muitos dias, ele se despediu dos irmãos, e dali navegou para a Síria, e juntos com ele estavam Priscila e Áquila; tendo rapado a cabeça em Cencreia, porque ele tinha feito voto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'E chegou a Éfeso, e os deixou ali; mas ele, entrando na sinagoga, disputava com os judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'E eles, pedindo -lhe que continuasse com eles por mais algum tempo, ele não concordou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Porém despediu-se deles, dizendo: De toda maneira tenho que estar na festa que vem em Jerusalém; mas outra vez, se Deus quiser, voltarei a vós.E ele saiu de Éfeso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'E tendo vindo a Cesareia, subiu e, saudando à igreja, desceu a Antioquia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'E passando ali algum tempo, ele partiu, passando em sequência pela região da Galácia e Frígia, firmando a todos os discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'E chegou a Éfeso um certo judeu, de nome Apolo, natural de Alexandria, homem eloquente, bem capacitado nas Escrituras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Este era instruído no caminho do Senhor; e fervoroso de espírito, falava e ensinava corretamente as coisas do Senhor; ainda que soubesse somente o batismo de João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'E este começou a falar ousadamente na sinagoga; e Áquila e Priscila, ao o ouvirem, tomaram-no consigo, e explicaram mais detalhadamente o caminho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'E ele, querendo passar a Acaia, os irmãos o exortaram, e escreveram aos discípulos que o recebessem; o qual, tendo chegado, auxiliou muito aos que tinham crido pela graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Porque vigorosamente ele provava publicamente os erros dos judeus, mostrando pelas Escrituras que Jesus era o Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'E enquanto Apolo estava em Corinto, aconteceu que, tendo Paulo passado por todas as regiões altas, ele veio a Éfeso; e achando ali alguns discípulos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Disse-lhes: Vós já recebestes o Espírito Santo desde que crestes?E eles lhe disseram: Nós nem tínhamos ouvido falar que havia Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'E ele lhes disse: Em que vós fostes batizados?E eles disseram: No batismo de João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Então Paulo disse: João verdadeiramente batizou com o batismo do arrependimento, dizendo ao povo que cressem naquele que viria após ele, isto é, em Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Ao ouvirem isto, eles foram batizados no nome do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'E Paulo, impondo-lhes as mãos, veio sobre eles o Espírito Santo; e falavam em línguas, e profetizavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'E todos os homens eram cerca de doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'E ele, entrando na sinagoga, falava ousadamente durante três meses, disputando e persuadindo as coisas do Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Mas quando alguns se endureceram, e não creram, e falando mal do Caminho diante da multidão, ele se desviou deles; e separou aos discípulos, disputando a cada dia na escola de um certo Tirano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'E isto aconteceu durante dois anos; de tal maneira que todos os que habitavam na Ásia tinham ouvido a palavra do Senhor Jesus, tanto judeus como gregos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'E Deus fazia milagres extraordinários pelas mãos de Paulo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'De tal maneira que até os lenços e aventais de seu corpo eram levados aos enfermos, e as doenças os deixavam, e os espíritos malignos saíam deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'E alguns exorcistas dos judeus, itinerantes, tentaram invocar o nome do Senhor Jesus sobre os que tinham espíritos malignos, dizendo: Nós vos repreendemos por Jesus, a quem Paulo prega.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'E eram sete filhos de Ceva, judeu, chefe dos sacerdotes, os que faziam isto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Mas o espírito maligno respondeu: Eu conheço Jesus, e sei quem é Paulo; mas vós, quem sois?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'E o homem em quem estava o espírito maligno saltou sobre eles, e dominando-os, foi mais forte do que eles; de tal maneira que eles fugiram nus e feridos daquela casa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'E isto se fez conhecido a todos que habitavam em Éfeso, tanto a judeus como a gregos; e caiu temor sobre todos eles; e assim foi engrandecido o nome do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'E muitos dos que criam vinham, confessando e declararando as suas atitudes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Também muitos dos que praticavam ocultismo trouxeram seus livros, e os queimaram na presença de todos; e calcularam o preço deles, e acharam que custavam cinquenta mil moedas de prata.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Assim a palavra do Senhor crescia e prevalecia poderosamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'E quando se cumpriram estas coisas, Paulo propôs em espírito que, passando pela Macedônia e Acaia, ir até Jerusalém, dizendo: Depois de eu estar lá, também tenho que ver Roma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'E ele, tendo enviado à Macedônia dois daqueles que o serviam, Timóteo e Erasto, ele ficou por algum tempo na Ásia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Mas naquele tempo aconteceu um não pequeno alvoroço quanto ao Caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Porque um certo artífice de prata, de nome Demétrio, que fazia objetos de prata para o templo de Diana, e dava não pouco lucro aos artesãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Aos quais, tendo os reunido com os trabalhadores de semelhantes coisas, disse: Homens, vós sabeis que deste ofício temos nossa prosperidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'E vós estais vendo e ouvindo que este Paulo, não somente em Éfeso, mas até quase em toda a Ásia, tem persuadido e apartado uma grande multidão, dizendo que não são deuses os que são feitos com as mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'E não somente há perigo de que isto torne nosso ofício em desprezo, mas também que até o tempo da grande deusa Diana seja considerado inútil, e que a grandiosidade dela, a quem toda a Ásia e o mundo venera, venha a ser destruída.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'E eles, ao ouvirem estas coisas,encheram-se de ira, e clamaram, dizendo: Grande é a Diana dos efésios!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'E toda a cidade se encheu de tumulto, e em concordância eles invadiram ao teatro, tomando consigo Gaio e Aristarco, macedônios, companheiros de Paulo na viagem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'E Paulo, querendo comparecer diante do povo, os discípulos não o permitiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'E também alguns dos líderes da Ásia, que eram amigos dele, enviaram-lhe aviso, rogando -lhe para que não se apresentasse no teatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Então gritavam, alguns de uma maneira, outros de outra; porque a aglomeração estava confusa; e a maioria não sabia por que causa estavam aglomerados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'E tiraram da multidão a Alexandre, os judeus o pondo para a frente. E Alexandre, acenando com a mão, queria se defender ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Mas ao saberem que ele era judeu, levantou-se uma voz de todos, clamando por cerca de duas horas: Grande é a Diana dos efésios!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'E o escrivão, tendo apaziguado a multidão, disse: Homens efésios, quem não sabe que a cidade dos efésios é a guardadora do templo da grande deusa Diana, e da imagem que desceu do céu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Portanto, sendo que estas coisas não podem ser contraditas, vós deveis vos acalmar, e nada façais precipitadamente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Porque vós trouxestes aqui estes homens, que nem são sacrílegos, nem blasfemam de vossa deusa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Então se Demétrio e os artesãos que estão com ele tem algum assunto contra ele, os tribunais estão abertos, e há procônsules; que se acusem uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'E se procurais alguma outra coisa, será decidido em uma reunião legalizada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Porque corremos perigo de que hoje sejamos acusados de rebelião, tendo causa nenhuma para dar como explicação para este tumulto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'E tendo dito isto, despediu o ajuntamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'E tendo acabado o tumulto, Paulo chamou a si os discípulos e, abraçando-os, saiu para ir à Macedônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'E tendo passado por aquelas regiões, e exortando-os com muitas palavras, ele veio à Grécia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'E ficando ali por três meses, e havendo contra ele uma cilada posta pelos judeus quando ele estava a ponto de navegar para a Síria, ele decidiu voltar pela Macedônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'E o acompanhou até a Ásia Sópater, de Bereia; e dos tessalonicenses, Aristarco e Segundo, e Gaio de Derbe, e Timóteo; e dos da Ásia, Tíquico e Trófimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Estes, indo adiante, nos esperaram em Trôade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'E depois dos dias dos pães não fermentados, nós navegamos de Filipos, e em cinco dias viemos até eles, onde ficamos por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'E no primeiro dia da semana, tendo os discípulos se reunido para partir o pão, Paulo discutia com eles, estando para partir no dia seguinte; e ele estendeu a discussão até a meia noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'E havia muitas luminárias no compartimento onde estavam reunidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'E estando um certo rapaz, de nome Êutico, sentado em uma janela, tendo sido tomado por um sono profundo, e,estando Paulo ainda falando por muito tempo, Êutico,derrubado pelo sono, caiu desde o terceiro andar abaixo; e foi levantado morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mas Paulo, tendo descido, debruçou sobre ele e, abraçando -o,disse: Não fiqueis perturbados, porque sua alma ainda está nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'E voltou a subir, e tendo partido e experimentado o pão, ele falou longamente até o nascer do dia; e assim ele partiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'E trouxeram o rapaz vivo, e ficaram não pouco consolados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'E nós, tendo ido adiante ao navio, navegamos até Assôs, onde estaríamos para receber a Paulo, porque assim ele tinha ordenado; e ele ia a pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'E quando ele se encontrou conosco em Assôs, nós o tomamos, e fomos a Mitilene.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'E navegando dali, chegamos no dia seguinte em frente a Quios; e no outro dia aportamos em Samos; e ficando em Trogílio, no dia seguinte viemos a Mileto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Porque Paulo tinha decidido navegar desviando-se de Éfeso, para não lhe haver de gastar tempo na Ásia; porque ele se apressava para estar em Jerusalém do dia de Pentecostes, caso lhe fosse possível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Mas ele enviou mensagem desde Mileto até Éfeso, chamando aos anciãos da igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'E quando vieram a Paulo,ele lhes disse: Vós sabeis que desde o primeiro dia que entrei na Ásia, o modo como eu estive todo aquele tempo convosco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Servindo ao Senhor com toda humildade, muitas lágrimas, e tentações, que sobrevieram a mim pelas ciladas dos judeus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Como eu, daquilo que vos era proveitoso, nada deixei de anunciar a vós, e ensinar publicamente e pelas casas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Dando testemunho, tanto a judeus como a gregos, do arrependimento para se converter a Deus, e da fé em nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'E agora eis que, estando eu atado ao Espírito, estou indo a Jerusalém, não sabendo o que me acontecerá;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'A não ser pelo que o Espírito Santo em cada cidade me dá testemunho, dizendo que prisões e aflições me esperam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Mas de nenhuma dessas coisas eu dou importância, nem tenho minha vida por preciosa, para que com alegria eu cumpra minha carreira, e o trabalho que recebi do Senhor Jesus, para dar testemunho do Evangelho da graça de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'E agora, eis que eu sei que todos vós, a quem eu passei pregando o Reino de Deus, não vereis mais o meu rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Portanto eu vos dou claro testemunho de que eu estou limpo do sangue de todos vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Porque eu não deixei de vos anunciar todo o conselho de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Portanto prestai atenção por vós mesmos, e por todo o rebanho sobre os quais o Espírito Santo tem vos posto como supervisores, para apascentardes a igreja de Deus, a qual ele adquiriu por meio de seu próprio sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Porque isto eu sei, que depois de minha partida, entrarão entre vós lobos cruéis, que não pouparão ao rebanho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'E que dentre vós mesmos se levantarão homens a falarem coisas perversas, para atraírem após si aos discípulos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Por isso vigiai, lembrando que por três anos, noite e dia eu não parei de vos alertar com lágrimas a cada um de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'E agora, irmãos, eu vos entrego a Deus, e à palavra de sua graça; ele que é poderoso para vos edificar e vos dar herança entre todos os santificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Eu não cobicei de ninguém a prata, nem ouro, nem roupa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'E vós mesmos sabeis que, para as minhas necessidades e as dos que estavam comigo, estas minhas mãos me serviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Em tudo eu vos tenho mostrado que trabalhando assim, é necessário dar suporte aos enfermos; e lembrar-se das palavras do Senhor Jesus, que disse: Mais bem-aventurado é dar do que receber.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'E tendo dito isto, pondo-se de joelhos, ele orou com todos eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'E houve um grande pranto de todos; e reclinando-se sobre o pescoço de Paulo, beijavam-no;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Entristecendo-se muito, principalmente pela palavra que ele tinha dito, que não mais veriam o rosto dele; e o acompanharam até o navio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'E quando aconteceu de termos saído deles, e navegado, percorremos diretamente, e viemos a Cós, e n o dia seguinte a Rodes, e dali a Pátara.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'E tendo achado um navio que passava para a Fenícia, nós embarcamos nele, e partimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'E tendo Chipre à vista, e deixando-a à esquerda, navegamos para a Síria, e viemos a Tiro; porque o navio tinha de deixar ali sua carga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'E nós ficamos ali por sete dias; e achamos aos discípulos, os quais diziam pelo Espírito a Paulo, que não subisse a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'E tendo passado ali aqueles dias, nós saímos e seguimos nosso caminho, acompanhando-nos todos com suas mulheres e filhos até fora da cidade; e postos de joelhos na praia, oramos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'E saudando-nos uns aos outros, subimos ao navio; e eles voltaram para as casas deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'E nós, acabada a navegação de Tiro, chegamos a Ptolemaida; e tendo saudado aos irmãos, ficamos com eles por um dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'E n o dia seguinte, Paulo e nós que estávamos com ele, saindo dali, viemos a Cesareia; e entrando na casa de Filipe, o evangelista (que era um dos sete), nós ficamos com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'E este tinha quatro filhas, que profetizavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'E ficando nós ali por muitos dias, desceu da Judeia um profeta, de nome Ágabo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'E ele, tendo vindo a nós, e tomando a cinta de Paulo, e atando-se os pés e as mãos, disse: Isto diz o Espírito Santo: Assim os judeus em Jerusalém atarão ao homem a quem pertence esta cinta, e o entregarão nas mãos dos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'E nós, tendo ouvido isto, rogamos a ele, tanto nós como os que eram daquele lugar, que ele não subisse a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Mas Paulo respondeu: O que vós estais fazendo, ao chorarem e afligirem o meu coração? Porque eu estou pronto, não somente para ser atado, mas até mesmo para morrer em Jerusalém, pelo nome do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'E como ele não deixou ser persuadido, nós nos aquietamos, dizendo: Faça-se a vontade do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'E depois daqueles dias, nós nos arrumamos, e subimos a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'E foram também conosco alguns dos discípulos de Cesareia, trazendo consigo a um certo Mnáson, cipriota, discípulo antigo, com o qual íamos nos hospedar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'E quando chegamos a Jerusalém, os irmãos nos receberam com muito boa vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'E n o dia seguinte, Paulo entrou conosco a casa de Tiago, e todos os anciãos vieram ali.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'E tendo os saudado, ele lhes contou em detalhes o que Deus tinha feito entre os gentios por meio do trabalho dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'E eles, ao ouvirem, glorificaram ao Senhor, e lhe disseram: Tu vês, irmão, quantos milhares de judeus há que creem, e todos são zelosos da lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'E foram informados quanto a ti, que a todos os judeus, que estão entre os gentios, que tu ensinas a se afastarem de Moisés, dizendo que não devem circuncidar seus filhos, nem andar segundo os costumes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Então o que se fará? Em todo caso a multidão deve se ajuntar, porque ouvirão que tu já chegaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Portanto faça isto que te dizemos: temos quatro homens que fizeram voto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Toma contigo a estes, e purifica-te com eles, e paga os gastos deles, para que rapem a cabeça, e todos saibam que não há nada do que foram informados sobre ti, mas sim, que tu mesmo andas guardando a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'E quanto aos que creem dentre os gentios, nós já escrevemos, julgando que nada disto guardassem, a não ser somente que se abstenham do que se abstenham das coisas sacrificadas aos ídolos, e do sangue, e da carne sufocada, e do pecado sexual.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Então Paulo, tendo tomado consigo a aqueles homens, e purificando-se com eles no dia seguinte, entrou no Templo, anunciando que já estavam cumpridos dos dias da purificação, quando fosse oferecida por eles, cada um sua oferta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'E tendo os sete dias quase quase completados, os judeus da Ásia, vendo-o, tumultuaram a todo o povo, e lançaram as mãos sobre ele para o deterem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Clamando: Homens israelitas, ajudai -nos; este é o homem que por todos os lugares ensina a todos contra o nosso povo, e contra a Lei, e contra este lugar; e além disto, ele também pôs gregos dentro do Templo, e contaminou este santo lugar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, '(Porque antes eles tinham visto na cidade a Trófimo junto dele, ao qual pensavam que Paulo tinha trazido para dentro do Templo).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'E toda a cidade se tumultuou, e houve um ajuntamento do povo; e tendo detido a Paulo, trouxeram-no para fora do Templo; e logo as portas foram fechadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'E eles, procurando matá-lo, a notícia chegou ao comandante e aos soldados, de que toda Jerusalém estava em confusão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'O qual, tendo tomado logo consigo soldados e centuriões, correu até eles. E eles, vendo ao comandante e aos soldados, pararam de ferir a Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Então o comandante, tendo se aproximado, prendeu-o, e mandou que ele fosse atado em duas correntes; e perguntou quem ele era, e o que ele tinha feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'E na multidão clamavam uns de uma maneira,e outros de outra maneira; mas como ele não podia saber com certeza por causa do tumulto, ele mandou que o levassem para a área fortificada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'E ele, tendo chegado às escadas, aconteceu que ele foi carregado pelos soldados, por causa da violência da multidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Porque a multidão do povo o seguia, gritando: Tragam-no para fora!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'E Paulo, estando perto de entrar na área fortificada, disse ao comandante: É permitido a mim te falar alguma coisa?E ele disse: Tu sabes grego?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Por acaso não és tu aquele egípcio, que antes destes dias tinha levantando uma rebelião, e levou ao deserto quatro mil homens assassinos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Mas Paulo lhe disse: Na verdade eu sou um homem judeu de Tarso, cidade não pouca importância da Cilícia; mas eu te rogo para que tu me permitas falar ao povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'E tendo lhe permitido, Paulo pôs-se de pé nas escadas, acenou com a mão ao povo; e tendo havido grande silêncio, falou -lhes em língua hebraica, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Homens irmãos, e pais, ouvi agora minha defesa para convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'E tendo ouvido que ele lhes falava em língua hebraica, fizeram ainda mais silêncio. E ele disse:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Eu verdadeiramente sou um homem judeu, nascido em Tarso da Cilícia, e criado nesta cidade aos pés de Gamaliel, ensinado ao mais correto modo da Lei paterna e zeloso de Deus, assim como todos vós sois hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Eu,que persegui este caminho até a morte, atando tanto a homens como a mulheres, e os entregando a prisões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Assim como também o sumo sacerdote me é testemunha, e todo o conselho dos anciãos; dos quais eu, tendo tomado cartas para os irmãos, fui a Damasco para que os que estivessem ali, eu também os trouxesse amarrados a Jerusalém, para que fossem castigados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Mas aconteceu que, estando eu no caminho, e chegando perto de Damasco, quase ao meio dia, de repente uma grande luz do céu brilhou ao redor de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Eu cai ao chão, e ouvi uma voz, que me dizia: Saulo, Saulo, por que me persegues?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'E eu respondi: Quem és, Senhor? E ele me disse: Eu sou Jesus, o nazareno, a quem tu persegues.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'E os que estavam comigo verdadeiramente viram a luz, e ficaram muito atemorizados; mas eles não ouviram a voz daquele que falava comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'E eu disse: Que farei, Senhor? E o Senhor me disse: Levanta-te, e vai a Damasco, e ali te será dito tudo o que te é ordenado fazer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'E quando eu não conseguia ver, por causa da glória daquela luz, eu fui levado pela mão dos que estavam comigo, e assim cheguei a Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'E um certo Ananias, homem devoto conforme a Lei, que tinha bom testemunho de todos os judeus que moravam ali;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Tendo vindo até mim, e ficando diante de mim,ele me disse: Irmão Saulo, recupere a vista; E naquela mesma hora eu pude vê-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'E ele disse: O Deus de nossos pais te predeterminou para que tu conheças a vontade dele, e vejas aquele justo, e tu ouças a voz de sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Porque tu serás testemunha dele para com todos as pessoas, daquilo que tens visto e ouvido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'E agora, por que estás parado? Levanta-te, e sê batizado, e lava teus pecados, invocando o nome do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'E aconteceu a mim, tendo eu voltado a Jerusalém, e estando orando no Templo, veio-me um êxtase;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'E eu vi aquele que me dizia: Apressa-te, e sai logo de Jerusalém, porque não aceitarão teu testemunho sobre mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'E eu disse: Senhor, eles sabem que eu prendia e açoitava nas sinagogas aqueles que criam em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'E quando o sangue de Estêvão, tua testemunha, se derramava, eu também estava presente, e consentia em sua morte, e guardava as roupas daqueles que o matavam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'E ele me disse: Vai, porque eu te enviarei para longe, aos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'E eles o ouviram até esta palavra, e em seguida levantaram suas vozes, dizendo: Extermina-o da terra! Porque não é bom que ele viva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'E enquanto eles gritavam, tiravam suas capas, e lançavm pó ao ar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'O comandante mandou que o levassem à área fortificada, dizendo que o interrogassem com açoites, para saber por que causa clamavam assim contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'E quando estavam o atando com correias, Paulo disse ao centurião que estava ali: É lícito para vós açoitar a um homem romano, sem ter sido condenado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'E o centurião, tendo ouvido isto,foi e avisou ao comandante, dizendo: Olha o que estás a ponto de fazer, porque este homem é romano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'E o comandante, tendo se aproximado, disse-lhe: Dize-me, tu és romano?E ele disse: Sim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'E o comandante respondeu: Eu com muita soma de dinheiro obtive esta cidadania romana.E Paulo disse: E eu a tenho desde que nasci.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Então logo se afastaram dele aqueles que estavam para interrogá-lo; e até o comandante teve temor, ao entender que Paulo era romano, e que tinha o atado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'E n o dia seguinte, querendo saber corretamente a causa de por que ele era acusado pelos judeus, ele o soltou das correntes, e mandou vir aos chefes dos sacerdotes e todo o Supremo Conselho deles; e tendo trazido a Paulo, apresentou -o diante deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'E Paulo, olhando fixamente a os d o Supremo Conselho, disse: Homens irmãos, com toda boa consciência eu tenho andado diante de Deus até o dia de hoje.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Mas o sumo sacerdote Ananias mandou aos que estavam perto dele, que o espancassem na boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Então Paulo lhe disse: Deus vai te espancar, parede caiada! Estás tu aqui sentado para me julgar conforme a Lei, e contra a Lei mandas me espancarem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'E os que estavam ali disseram: Tu insultas ao sumo sacerdote de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'E Paulo disse: Eu não sabia, irmãos, que ele era o sumo sacerdote; porque está escrito: Não falarás mal do chefe do teu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'E Paulo, sabendo que uma parte era de saduceus, e outra de fariseus, ele clamou no Supremo Conselho: Homens irmãos, eu sou fariseu, filho de fariseu; pela esperança e ressurreição dos mortos eu estou sendo julgado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'E ele, tendo dito isto, houve uma confusão entre os fariseus e saduceus; e a multidão se dividiu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Porque os saduceus dizem que não há ressurreição, nem anjo ou espírito; mas os fariseus declaram ambas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'E houve uma grande gritaria; e levantando-se os escribas da parte dos fariseus, disputavam, dizendo: Nenhum mal achamos neste homem; e se algum espírito ou anjo falou com ele, não briguemos contra Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'E havendo grande confusão, o comandante, temendo que Paulo não fosse despedaçado por eles, mandou descer a tropa, e tirá-lo do meio deles, e levá-lo à área fortificada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'E n a noite seguinte o Senhor, aparecendo-lhe, disse: Tem bom ânimo, Paulo! Porque assim como deste testemunho de mim em Jerusalém, assim é necessário que tu dês testemunho também em Roma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'E tendo vindo o dia, alguns dos judeus fizeram uma conspiração, e prestaram juramento sob pena de maldição, dizendo que não comeriam nem beberiam enquanto não matassem a Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'E eram mais de quarenta os que fizeram este juramento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Os quais foram até os chefes dos sacerdotes e os anciãos, e disseram: Fizemos juramento sob pena de maldição, de que nada experimentaremos enquanto não matarmos a Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Agora vós, então, juntamente com o Supremo Conselho, fazei saber ao comandante que amanhã ele o traga a vós, como se fosse para que investigueis mais detalhadamente; e antes que ele chegue, nós estamos prontos para o matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'E o filho da irmã de Paulo, tendo ouvido esta cilada, veio e entrou na área fortificada, e avisou a Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'E Paulo, tendo chamado a si um dos centuriões, disse: Leva este rapaz ao comandante, porque ele tem algo para lhe avisar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Então ele o tomou, levou ao comandante, e disse: O prisioneiro Paulo, tendo me chamado, rogou -me que eu te trouxesse este rapaz, que tem algo a te dizer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'E o comandante, tomando-o pela mão, e indo para um lugar reservado, perguntou -lhe: O que tens para me avisar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'E ele disse: Os judeus combinaram de te pedirem que amanhã tu leves a Paulo ao Supremo Conselho, como se fosse para que lhe perguntem mais detalhadamente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Porém tu, não acredites neles; porque mais de quarenta homens deles estão lhe preparando cilada, os quais sob pena de maldição fizeram juramento para não comerem nem beberem enquanto não o tiverem matado; e eles já estão preparados, esperando de ti a promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Então o comandante despediu ao rapaz, mandando -lhe: A ninguém digas que tu me revelaste estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'E ele, chamando a si certos dois dos centuriões, disse: Aprontai duzentos soldados para irem até Cesareia; e setenta cavaleiros, e duzentos arqueiros, a partir das terceira hora da noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'E preparem animais para cavalgarem, para que pondo neles a Paulo, levem -no a salvo ao governador Félix.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'E ele lhe escreveu uma carta, que continha este aspecto:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Cláudio Lísias, a Félix, excelentíssimo governador, saudações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Este homem foi preso pelos judeus, e estando já a ponte de o matarem, eu vim com a tropa e o tomei, ao ser informado que ele era romano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'E eu, querendo saber a causa por que o acusavam, levei-o ao Supremo Conselho deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'O qual eu achei que acusavam de algumas questões da Lei deles; mas que nenhum crime digno de morte ou de prisão havia contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'E tendo sido avisado de que os judeus estavam para pôr uma cilada contra este homem, logo eu o enviei a ti, mandando também aos acusadores que diante de ti digam o que tiverem contra ele. Que tu estejas bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Tendo então os soldados tomado a Paulo, assim como lhes tinha sido ordenado, trouxeram-no durante a noite a Antipátride.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'E n o dia seguinte, deixando irem com ele os cavaleiros, voltaram à área fortificada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Os quais, tendo chegado a Cesareia, e entregado a carta ao governador, apresentaram-lhe também a Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'E o governador, tendo lido a carta, perguntou de que província ele era; e ao entender que era da Cilícia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'disse: “Eu te ouvirei quando também chegarem os teus acusadores”. E mandou que o guardassem no palácio de Herodes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'E cinco dias depois, desceu o sumo sacerdote Ananias, com os anciãos e um certo orador Tértulo; os quais compareceram diante do governador contra Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'E sendo chamado, Tértulo começou a acusá -lo,dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Visto que há muita paz por causa de ti, e que por teu governo muitos bons serviços estão sendo feitos a esta nação, excelentíssimo Félix, totalmente e em todo lugar, com todo agradecimento o reconhecemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Mas para que eu não gaste muito o teu tempo, rogo -te que tu nos ouças brevemente, conforme a tua clemência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Porque nós temos achado que este homem é uma peste, e levantador de rebeliões entre todos os judeus pelo mundo, e o principal defensor da seita dos nazarenos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'O qual também tentou profanar o Templo; ao qual também prendemos, e quisemos julgar conforme a nossa Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Mas tendo vindo sobre nós o comandante Lísias, com grande violência, tirou -o das nossas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'investigando-o tu mesmo, poderás entender todas estas coisas das quais o acusamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'E os judeus também concordaram, dizendo serem estas coisas assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Mas Paulo, fazendo gesto ao governador para que falasse, respondeu: Sabendo eu que por muitos anos tu tens sido juiz desta nação, com maior ânimo eu me defendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Pois tu podes entender que há não mais que doze dias, eu tinha subido a Jerusalém para adorar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'E nem me acharam falando com alguém no Templo, nem incitando ao povo, nem nas sinagogas, nem na cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'E nem podem provar as coisas das quais agora estão me acusando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Mas isto eu te confesso, que conforme o Caminho que eles chamam de seita, assim eu sirvo ao Deus dos meus pais, crendo em tudo que está escrito na Lei e nos profetas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Tendo esperança em Deus, ao qual estes mesmos também esperam, que vai haver ressurreição dos mortos, tanto dos justos como dos injustos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'E nisto eu pratico, em que tanto para com Deus como para com os seres humanos eu sempre tenha uma consciência limpa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'E muitos anos depois, vim para fazer doações e ofertas à minha nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'N isto,tendo eu me purificado, nem com multidões, nem com tumulto, alguns judeus da Ásia me acharam,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Os quais era necessário que estivessem aqui presentes diante de ti, se tivessem alguma coisa contra mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Ou digam estes mesmos, se eles acharam alguma má ação em mim quando eu estava perante o Supremo Conselho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'A não ser somente esta palavra com que, quando eu estava entre eles, clamei, que pela ressurreição dos mortos eu estou sendo julgado hoje por vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Tendo ouvido estas coisas, Félix, que sabia mais detalhadamente sobre o Caminho, adiou-lhes, dizendo: Quando o comandante Lísias descer, eu procurarei saber melhor de vossos assuntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'E ele mandou ao centurião que guardassem a Paulo, e estivesse com alguma liberdade, e impedir a ninguém dos seus amigos lhe prestasse serviço, ou vir até ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'E alguns dias depois, tendo vindo Félix com a mulher dele Drusila, que era judia, mandou chamar a Paulo, e o ouviu sobre a fé em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'E ele, tendo discursado sobre a justiça, o domínio próprio, e o julgamento que está por vir, Félix temeu, e respondeu: Por agora vai; e tendo outra oportunidade, eu te chamarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Ele também esperava que lhe fosse dado algum dinheiro por Paulo, para que o soltasse; por isso ele também muitas vezes o mandava chamar, e conversava com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Mas tendo completado dois anos, Félix teve por sucessor a Pórcio Festo. E Félix, querendo agradar dos judeus, deixou Paulo preso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Então Festo, tendo entrado na província, subiu dali três dias depois de Cesareia a Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'E o sumo sacerdote e os líderes dos judeus compareceram diante dele contra Paulo, e lhe rogaram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Pedindo favor contra ele, para que o fizesse vir a Jerusalém, preparando cilada para o matarem no caminho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Mas Festo respondeu que Paulo estava guardado em Cesareia, e que ele logo estava indo para lá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Ele disse: Então aqueles dentre vós que podem, desçam com igo,e se houver alguma coisa errada neste homem, acusem-no.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'E ele, tendo ficado entre eles mais de dez dias, desceu a Cesareia; e tendo se sentado no tribunal no dia seguinte, mandou que trouxessem a Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'E tendo ele vindo, os judeus que haviam descido de Jerusalém o rodearam, trazendo contra Paulo muitas e graves acusações, que não podiam provar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Ele, disse em sua defesa: Eu não pequei nem contra a Lei dos judeus, nem contra o Templo, nem contra César, em coisa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Mas Festo, querendo agradar aos judeus, respondendo a Paulo, disse: Tu queres subir a Jerusalém e ser julgado sobre estas coisas diante de mim?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'E Paulo disse: Eu estou diante do tribunal de César, onde eu tenho que ser julgado; a nenhum dos judeus eu fiz mal, assim como também tu sabes muito bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Porque se eu fiz algum mal, ou cometi algo digno de morte, eu não recuso morrer; mas se nada há das coisas que este me acusam, ninguém pode me entregar a eles. Eu apelo a César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Então Paulo, tendo conversado com o Conselho, respondeu: Tu apelaste a César; a César irás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'E passados alguns dias, o Rei Agripa e Berenice vieram a Cesareia para saudar a Festo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'E quando tinham ficado ali muitos dias, Festo contou ao rei os assuntos de Paulo, dizendo: Um certo homem foi deixado aqui preso por Félix;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Por causa do qual, estando eu em Jerusalém, os chefes dos sacerdotes e os anciãos dos judeus compareceram a mim,pedindo julgamento contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Aos quais eu respondi não ser costume dos romanos entregar a algum homem à morte, antes que o acusado tenha seus acusadores face a face, e tenha oportunidade para se defender da acusação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Portanto, tendo eles se reunido aqui, fazendo nenhum adiamento, no dia seguinte, estando eu sentado no tribunal, mandei trazer ao homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Do qual os acusadores estando aqui presentes, trouxeram como acusação nenhuma das coisas que eu suspeitava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Mas tinham contra ele algumas questões relativas às própria s crença s deles, e de um certo morto Jesus, o qual Paulo afirmava estar vivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'E eu, estando em duvida sobre como interrogar esta causa, disse, perguntando se ele queria ir a Jerusalém, e lá ser julgado sobre estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Porém Paulo, tendo apelado para ser guardado ao interrogatório do imperador, mandei que o guardassem, até que eu o enviasse a César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'E Agripa disse a Festo: Eu também queria ouvir a este homem.E ele disse: E amanhã tu o ouvirás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Então no dia seguinte, tendo vindo Agripa e Berenice, com muita pompa, e entrando no auditório com os comandantes e os homens mais importantes da cidade, trouxeram a Paulo por ordem de Festo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'E Festo disse: Rei Agripa, e todos os homens que estais presentes aqui conosco, vós vedes este homem,a quem toda a multidão dos judeus, tanto em Jerusalém como aqui, tem apelado a mim, clamando que ele não deve mais viver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Mas tendo eu achado nada que ele tenha feito que fosse digno de morte, e também tendo ele mesmo apelado ao imperador, eu decidi enviá-lo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Do qual eu não tenho coisa alguma certa para escrever ao meu senhor; por isso que eu o trouxe diante de vós; e principalmente diante de ti, rei Agripa, para que, sendo feita a investigação, eu tenha algo para escrever.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Porque não me parece razoável enviar a um prisioneiro, sem também informar as acusações contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'E Agripa disse a Paulo: É permitido a ti falar por ti mesmo.Então Paulo, estendendo a mão, respondeu em sua defesa:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Eu me considero feliz, rei Agripa, de que diante de ti eu esteja hoje fazendo minha defesa de todas as coisas de que sou acusado pelos judeus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Principalmente por eu saber que tu sabes de todos os costumes e questões que há entre os judeus; por isso eu te rogo que tu me ouças com paciência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Ora, a minha vida é conhecida por todos os judeus, desde a minha juventude, que desde o princípio tem sido entre os de minha nação em Jerusalém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Eles me conhecem desde o começo, se quiserem testemunhar, de que conforme a mais rigorosa divisão de nossa religião, eu vivi como fariseu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'E agora, pela esperança da promessa que por Deus foi dada aos nossos pais, eu estou aqui sendo julgado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'À qual nossas doze tribos, servindo continuamente a Deus de dia e de noite, esperam chegar; pela qual esperança, rei Agripa, eu sou acusado pelos judeus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Por que se julga como incrível entre vós que Deus ressuscite aos mortos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Eu realmente tinha pensado comigo mesmo, que contra o nome de Jesus eu tinha que fazer muitas oposições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'O que eu também fiz em Jerusalém; e tendo recebido autoridade dos chefes dos sacerdotes, eu pus em prisões a muitos dos santos; e quando eles eram mortos, eu também dava meu voto contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'E tendo lhes dado punição muitas vezes por todas as sinagogas, eu os forcei a blasfemarem. E estando extremamente enfurecido contra eles, até nas cidades estrangeiras eu os persegui;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Nas quais, indo eu até Damasco, com autoridade e comissão dos chefes dos sacerdotes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Ao meio dia, vi no caminho, rei, uma luz do céu, que brilhava muito mais que o sol, e que encheu de claridade ao redor de mim e dos que iam comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'E todos nós, tendo caído ao chão, eu ouvi uma voz que falava a mim, e dizia em língua hebraica: Saulo, Saulo, por que me persegues? Duro é para ti dar coices contra os aguilhões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'E eu disse: Quem és, Senhor? E ele disse: Eu sou Jesus, a quem tu persegues.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Mas levanta-te, e fica de pé, porque para isto eu apareci a ti, para te predeterminar como trabalhador e testemunha, tanto das coisas que já tens visto, como das coisas que eu ainda aparecerei a ti;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Livrando-te d este povo, e dos gentios, aos quais agora eu te envio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Para abrir os olhos deles, e das trevas converterem à luz, e do poder de Satanás converterem a Deus; para que recebam perdão dos pecados, e herança entre os santificados pela fé em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Portanto, rei Agripa, eu não fui desobediente à visão celestial.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Mas sim, primeiramente aos que estavam em Damasco e Jerusalém, e por toda a terra da Judeia, e aos gentios anunciei que se arrependessem, e se convertessem a Deus, fazendo obras dignas de arrependimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Por causa disto os judeus me pegaram no Templo, e procuravam me matar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Porém tendo eu obtido socorro de Deus, permaneço até o dia de hoje, dando testemunho tanto a pequenos como a grandes; não dizendo nada além dos que as coisas que os profetas e Moisés tinham dito que estavam para acontecer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Isto é,que o Cristo sofreria, e sendo o primeiro da ressurreição dos mortos, ia anunciar a luz a este povo e aos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'E tendo Paulo dito isto em sua defesa, Festo disse em alta voz: Tu estás louco, Paulo; as muitas escrituras te fizeram enlouquecer!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Mas ele respondeu: Eu não estou louco, excelentíssimo Festo; mas eu declaro palavras de verdade e de um são juízo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Porque o rei, a quem eu estou falando livremente, ele sabe muito bem destas coisas; porque eu não creio que nenhuma disto lhe seja oculto; por que isto não foi feito num canto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Rei Agripa, tu crês nos profetas? Eu sei que tu crês.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'E Agripa disse a Paulo: Por pouco tu me convences a me tornar cristão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'E Paulo disse: Meu desejo a Deus é que, por pouco ou por muito, não somente tu, mas todos os que estão me ouvindo hoje, tais vos tornásseis assim como eu sou, a não ser por estas correntes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'E tendo ele dito isto, o rei se levantou, e também o governador, Berenice, e os que estavam sentados com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'E reunindo-se à parte, falavam uns aos outros, dizendo: Este homem nada faz que seja digno de morte ou de prisões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'E Agripa disse a Festo: Este homem podia ser solto, se ele não tivesse apelado a César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'E quando foi determinado que tínhamos que navegar para a Itália, entregaram a Paulo e alguns outros prisioneiros, a um centurião, por nome Júlio, do esquadrão imperial.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'E embarcando -nos em um navio adramitino, estando a navegar pelos lugares costeiros da Ásia, nós partimos, estando conosco Aristarco, o macedônio de Tessalônica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'E no dia seguinte, chegamos a Sidom; e Júlio, tratando bem a Paulo, permitiu -lhe que fosse aos amigos, para receber cuidado deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'E tendo partido dali, nós fomos navegando abaixo do Chipre, porque os ventos estavam contrários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'E tendo passado ao longo do mar da Cilícia e Panfília, viemos a Mira em Lícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'E o centurião, tendo achado ali um navio de Alexandria, que estava navegando para a Itália, nos fez embarcar nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'E indo navegando lentamente já por muitos dias, chegando com dificuldade em frente a Cnido, o vento, não nos permitindo continuar por ali,navegamos abaixo de Creta, em frente a Salmone.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'E tendo com dificuldade percorrido sua costa, chegamos a um certo lugar, chamado Bons Portos, perto do qual estava a cidade de Laseia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'E tendo passado muito tempo, e sendo a navegação já perigosa, porque também já tinha passado o jejum, Paulo os exortava,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Dizendo-lhes: Homens, eu vejo que a navegação vai ser com violência e muito dano, não somente de carga e do navio, mas também de nossas vidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Porém o centurião cria mais no capitão e no dono do navio do que no que Paulo dizia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'E não sendo aquele porto adequado para passar o inverno, a maioria preferiu partir dali, para ver se podiam chegar a Fênix, que é um porto de Creta, voltada para o lado do vento sudoeste e noroeste, para ali passarem o inverno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'E ao ventar brandamente ao sul, pareceu-lhes que eles já tinham o que queriam; e levantando a vela, foram por perto da costa de Creta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Mas não muito depois houve contra ela um vento violento, chamado Euroaquilão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'E tendo o navio sido tomado por ele, e não podendo navegar contra o vento, nós deixamos sermos levados por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'E correndo abaixo de uma pequena ilha, chamada Clauda, com dificuldade conseguimos manter o barquinho de reserva;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'O qual, tendo sido levado para cima, usaram de suportes para reforçarem o navio; e temendo irem de encontro aos bancos de areia, eles baixaram as velas e deixaram ir à deriva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'E sendo muito afligidos pela tempestade, no dia seguinte jogaram a carga para fora do navio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'E no terceiro dia,com as nossas próprias mãos jogamos fora os instrumentos do navio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'E não aparecendo ainda o sol, nem estrelas havia muitos dias, e sendo afligidos por não pouca tempestade, desde então tínhamos perdido toda a esperança de sermos salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'E havendo muito tempo que não havia o que comer, então Paulo, ficando de pé no meio deles, disse: Homens, vós devíeis ter dado atenção a mim, e não terdes partido de Creta, e assim evitar esta situação ruim e prejuízo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Mas agora eu vos exorto a terdes bom ânimo; porque haverá nenhuma perda de vida de vós, além somente da perda do navio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Porque esta mesma noite esteve comigo um anjo de Deus, a quem eu pertenço e a quem eu sirvo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Dizendo: Não temas, Paulo; é necessário que tu sejas apresentado a César; e eis que Deus tem te dado a vida a todos quantos navegam contigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Portanto, homens, tende bom ânimo; porque eu creio em Deus que assim será, conforme o que me foi dito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Mas é necessário que sejamos lançados a uma ilha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'E quando veio a décima quarta noite, sendo lançados de um lado para o outro no mar Adriático, por volta da meia noite os marinheiros suspeitaram de que estavam se aproximando de alguma terra firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'E tendo lançado o prumo, acharam vinte braças; e passando um pouco mais adiante, voltando a lançar o prumo, acharam quinze braças.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'E temendo de irem de encontro a lugares rochosos, lançaram da popa quatro âncoras, desejando que o dia viesse logo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'E quando os marinheiros estavam procurando fugir do navio, e baixando o barquinho de reserva ao mar, como que queriam largar as âncoras da proa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paulo disse ao centurião e aos soldados: Se estes não ficarem no navio, vós não podeis vos salvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Então os soldados cortaram os cabos do barquinho de reserva, e o deixaram cair.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'E até enquanto o dia estava vindo, Paulo exortava a todos que comessem alguma coisa, dizendo: Hoje já é o décimo quarto dia, em que estais esperando, continuando sem comer, nada tendo experimentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Portanto eu vos exorto para que comais alguma coisa, pois é bom para vossa saúde; porque nenhum cabelo cairá de vossa cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'E tendo dito isto, e tomando o pão, ele agradeceu a Deus na presença de todos; e partindo -o,começou a comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'E todos, tendo ficado mais encorajados, também pegaram algo para comer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'E éramos todos no navio duzentas e setenta e seis almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'E estando saciados de comer, eles tiraram peso do navio, lançando o trigo ao mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'E tendo vindo o dia, não reconheciam a terra; mas enxergaram uma enseada que tinha praia, na qual planejaram, se pudessem, levar o navio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'E tendo levantado as âncoras, deixaram -no ir ao mar, soltando também as amarras dos lemes, e levantando a vela maior ao vento, foram de levando -o à praia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Mas tendo caído em um lugar onde dois mares se encontram, encalharam ali o navio; e fixa a proa, ficou imóvel, mas a popa estava se destruindo com a força das ondas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Então o conselho dos soldados foi de que matassem aos presos, para que nenhum deles fugisse a nado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Mas o centurião, querendo salvar a Paulo, impediu a intenção deles; e mandou que aqueles que pudessem nadar fossem os primeiros a se lançassem ao mar e chegassem à terra firme.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'E depois os demais, uns em tábuas, e outros em pedaços do navio. E assim aconteceu, que todos se salvaram em terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'E tendo sobrevivido, então souberam que a ilha se chamava Malta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'E os nativos demonstraram para conosco uma benevolência incomum; porque, tendo acendido uma fogueira, recolheram a nós todos, por causa da chuva que estava caindo, e por causa do frio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'E tendo Paulo recolhido uma quantidade de gravetos, e pondo-os no fogo, saiu uma víbora do calor, e fixou os dentes na mão dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'E quando os nativos vieram o animal pendurado na mão dele, disseram uns aos outros: Certamente este homem é assassino, ao qual, tendo sobrevivido do mar, a justiça não o deixa viver.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Porém, ele, tendo sacudido o animal ao fogo, sofreu nenhum mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'E eles esperavam que ele fosse inchar, ou cair morto de repente. Mas tendo esperado muito, e vendo que nenhum incômodo tinha lhe sobrevindo, mudaram de opinião, e diziam que ele era um deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'E perto daquele mesmo lugar o homem mais importante da ilha, por nome Públio, tinha algumas propriedades; o qual nos recebeu e nos hospedou por três dias gentilmente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'E aconteceu que o pai de Públio estava de cama, doente de febres e disenteria; ao qual Paulo entrou, e tendo orado, pôs as mãos sobre ele, e o curou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Tendo então isto acontecido, também vieram a ele outros que tinham enfermidades, e foram curados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Os quais nos honraram com muitas honras; e estando nós para navegar, nos entregaram as coisas necessárias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'E três meses depois, nós partimos em um navio de Alexandria, que tinha passado o inverno na ilha; o qual tinha como símbolo os gêmeos Castor e Pólux.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'E chegando a Siracusa, ficamos ali três dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'De onde, tendo indo ao redor da costa, chegamos a Régio; e um dia depois, ventando ao sul, viemos o segundo dia a Putéoli.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Onde, tendo achado alguns irmãos, eles nos rogaram que ficássemos com eles por sete dias; e assim viemos a Roma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'E os irmãos, ao ouvirem notícias sobre nós, desde lá nos saíram ao encontro até a praça de Ápio, e as três tavernas; e Paulo, tendo os visto, agradeceu a Deus, e tomou coragem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'E quando chegamos a Roma, o centurião entregou os prisioneiros ao chefe da guarda, mas a Paulo foi permitido morar por si mesmo à parte, junto com o soldado que o guardava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'E aconteceu que, três dias depois, Paulo chamou juntos os chefes dos judeus; e ao se reunirem, disse-lhes: Homens irmãos, tendo eu nada feito contra o povo, ou contra os costumes dos pais, mesmo assim eu vim preso desde Jerusalém, entregue em mãos dos romanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Os quais, tendo me investigado, queriam me soltar, por não haver em mim nenhum crime de morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Mas os judeus, dizendo em contrário, eu fui forçado a apelar a César; mas não como que eu tenha que acusar a minha nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Então por esta causa eu vos chamei até mim, para vos ver e falar; porque pela esperança de Israel eu estou agora preso nesta corrente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Mas eles lhe disseram: Nós nem recebemos cartas da Judeia relacionadas a ti, nem algum dos irmãos, tendo vindo aqui, tem nos informado ou falado de ti algum mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Mas nós queríamos ouvir de ti o que tu pensas; porque, quanto a esta seita, conhecemos que em todo lugar há quem fale contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'E tendo eles lhe determinado um dia, muitos vieram até onde ele estava morando; aos quais ele declarava e dava testemunho do Reino de Deus; e procurava persuadi-los quanto a Jesus, tanto pela Lei de Moisés, como pelos profetas, desde a manhã até a tarde.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'E alguns criam nas coisas que ele dizia; mas outros não criam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'E estando discordantes entre si, despediram-se, tendo Paulo disto esta palavra: O Espírito Santo corretamente falou a nossos pais por meio de Isaías o profeta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Dizendo: Vai a este povo, e dize: De fato ouvireis, mas de maneira nenhuma entendereis; e de fato vereis, mas de maneira nenhuma enxergareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Porque o coração deste povo está insensível, seus ouvidos ouvem com dificuldade, e seus olhos estão fechados; para que em maneira nenhuma vejam com os olhos, nem ouçam com os ouvidos, nem entendam com o coração, e se convertam, e eu os cure.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Portanto seja conhecido por vós que a salvação de Deus foi enviada aos gentios; e eles a ouvirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'E havendo ele dito isto, os judeus foram embora, havendo entre eles grande discussão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'E Paulo ficou dois anos inteiros em sua própria casa alugada; e recebia a todos quantos vinham a ele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Pregando o Reino de Deus, e ensinando com ousadia a doutrina do Senhor Jesus Cristo, sem impedimento algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulo, servo de Jesus Cristo, chamado para ser apóstolo, separado para o evangelho de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'que antes havia prometido por meio dos seus profetas nas santas Escrituras,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'acerca do seu Filho (que, quanto à carne, nasceu da descendência de Davi,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'e declarado Filho de Deus em poder, segundo o Espírito de santidade, pela ressurreição dos mortos): Jesus Cristo, nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Por ele recebemos graça e apostolado, para a obediência da fé entre todas as nações, por causa do seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Entre elas sois também vós, chamados para serdes de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'A todos que estais em Roma, amados de Deus, e chamados de santos: convosco haja graça e paz da parte de Deus, nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Em primeiro lugar, agradeço ao meu Deus por meio de Jesus Cristo, por todos vós, porque a vossa fé é anunciada no mundo todo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Pois Deus, a quem sirvo em meu espírito no evangelho do seu Filho, é minha testemunha de como sem cessar faço menção de vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'rogando sempre em minhas orações, que agora, de alguma maneira, finalmente, tenha eu a oportunidade de, pela vontade de Deus, vir vos visitar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Pois eu desejo ver-vos, para compartilhar convosco algum dom espiritual, para que sejais fortalecidos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'isto é, para eu ser consolado juntamente convosco pela fé mútua, tanto a vossa, como a minha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Porém, irmãos, não quero que ignoreis que muitas vezes pretendi vir à vossa presença (mas fui impedido até agora), a fim de que eu também tivesse algum fruto entre vós, como também entre os demais gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Eu sou devedor, tanto a gregos como a bárbaros, tanto a sábios como a não sábios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Portanto, quanto a mim, pronto estou para anunciar o evangelho também a vós, que estais em Roma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Porque não me envergonho do Evangelho de Cristo, pois é o poder de Deus para a salvação de todo aquele que crê, primeiramente do judeu, e também do grego.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Pois no Evangelho se revela a justiça de Deus de fé em fé; como está escrito: O justo viverá pela fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Porque a ira de Deus se manifesta do céu contra toda irreverência e injustiça das pessoas que bloqueiam a verdade pela injustiça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'pois o que se pode conhecer de Deus é evidente a eles, porque Deus lhes manifestou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Pois as suas características invisíveis, inclusive o seu eterno poder e divindade, desde a criação do mundo são entendidas e claramente vistas por meio das coisas criadas, para que não tenham desculpa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Porque, ainda que tenham conhecido Deus, não o glorificaram como Deus, nem foram gratos; em vez disso, perderam o bom senso em seus pensamentos, e seus tolos corações ficaram em trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Chamando a si mesmos de sábios, tornaram-se tolos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'e trocaram a glória de Deus indestrutível por semelhança de imagem do ser humano destrutível, e de aves, de quadrúpedes, e de répteis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Por isso, Deus os entregou à imundície, nos desejos dos seus corações, para desonrarem os seus corpos entre si.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Trocaram a verdade de Deus pela mentira, e adoraram e serviram à criatura mais do que ao Criador, que é bendito eternamente, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Por isso, Deus os entregou a paixões infames. Pois até suas mulheres trocaram o hábito sexual natural pelo que era contra a natureza;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'e também, de semelhante maneira, os machos abandonaram o hábito sexual natural com a mulher, e acenderam sua sensualidade uns com os outros, homens com homens, praticando indecência, e recebendo em si mesmos a devida retribuição pelo seu erro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'E como recusaram reconhecer a Deus, o mesmo Deus os entregou a uma mente corrompida, para fazerem coisas impróprias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Assim, estão cheios de toda injustiça, pecado sexual, malícia, ganância, maldade; estão repletos de inveja, homicídio, brigas, engano, malignidade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'são murmuradores, difamadores, e odeiam a Deus; são insolentes, soberbos, presunçosos, inventores de males, e desobedientes aos pais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'não têm entendimento, quebram acordos, são insensíveis, e recusam-se a perdoar ou a mostrar misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Apesar de conhecerem o juízo de Deus (de que os que fazem tais coisas merecem a morte), não somente as fazem, como também aprovam os que as praticam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Por isso, tu, que julgas, não tens desculpa; quem quer que sejas! Pois condenas a ti mesmo naquilo que julgas o outro, porque tu, que julgas, fazes as mesmas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'E sabemos que o julgamento de Deus é segundo a verdade sobre os que fazem tais coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'E tu, humano, que julgas os que praticam tais coisas, ao fazê-las, pensas que escaparás do julgamento de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ou desprezas tu as riquezas de sua bondade, tolerância, e paciência, ignorando que é a bondade de Deus que te conduz ao arrependimento?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Mas, conforme a tua dureza e o teu coração que não se arrepende, tu ajuntas ira para ti no dia da ira e da manifestação do justo julgamento de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'que recompensará a cada um segundo as suas obras:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'vida eterna aos que procuram glória, honra, e imortalidade, fazendo o bem com perseverança;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'mas indignação e ira aos que agem com egoísmo, obedecendo à injustiça, e não à verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Haverá aflição e angústia a toda pessoa que pratica o mal, primeiramente ao judeu, e também ao grego;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'porém, glória, honra, e paz, a todo aquele que pratica o bem, primeiramente ao judeu, e também ao grego;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'porque com Deus não há acepção de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Pois todos os que sem Lei pecaram, sem Lei também perecerão; e todos os que pecaram sob a Lei, pela Lei serão julgados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'porque não são os que ouvem a Lei que são justos diante de Deus, mas sim, os que praticam a Lei que serão justificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Pois quando os gentios, que não têm a Lei, praticam naturalmente as coisas que são da Lei, estes, ainda que não tenham a Lei, são lei para si mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Eles mostram a obra da Lei escrita em seus corações, dando-lhes testemunho juntamente a sua consciência, e os pensamentos, ora acusando-os, ora defendendo-os.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Isso acontecerá no dia em que Deus julgará os segredos dos seres humanos por meio de Jesus Cristo, conforme o meu Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Eis que tu, que és chamado de judeu, e descansas confiando na Lei, e te orgulhas em Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'conheces a vontade dele, e aprovas as melhores coisas, por seres instruído na lei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'e confias ser guia dos cegos, luz dos que estão nas trevas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'instrutor dos tolos, professor das crianças, e que consideras a lei como a forma do conhecimento e da verdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'tu, pois, que ensinas ao outro, não ensinas a ti mesmo? Tu que pregas que não se deve furtar, furtas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Tu que dizes que não se deve adulterar, adulteras? Tu que odeias os ídolos, profanas templos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Tu, que te orgulhas da Lei, pela transgressão da Lei desonras a Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'porque, como está escrito: “O nome de Deus é blasfemado entre os gentios por vossa causa”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Pois a circuncisão tem proveito de fato se guardares a Lei; porém, se tu és transgressor da Lei, a tua circuncisão se torna incircuncisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Ora, se o incircunciso obedecer às exigências da Lei, por acaso não será a sua incircuncisão considerada como circuncisão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'E se o que de natureza é incircunciso cumprir a Lei, ele julgará a ti, que mesmo com a norma escrita e a circuncisão és transgressor da Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Pois judeu não é o de aparência externa, nem circuncisão é a na carne,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'mas é judeu o que é no interior, e circuncisão é a de coração, no espírito, e não em uma norma escrita. Esse é elogiado não pelas pessoas, mas sim, por Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Qual, pois, é a vantagem do judeu? Ou qual é a utilidade da circuncisão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Muita, em toda maneira. Pois, em primeiro lugar, as palavras de Deus lhes foram confiadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Então, quê? Se alguns foram infiéis, a infidelidade deles anulará a fidelidade de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'De maneira nenhuma! Antes seja Deus verdadeiro, e todo ser humano mentiroso, como está escrito: “Para que sejas justificado em tuas palavras, e prevaleças quando julgares”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'E, se a nossa injustiça evidencia a justiça de Deus, que diremos? Acaso Deus é injusto em impor a sua ira? (Falo na lógica humana).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'De maneira nenhuma! De outro modo, como Deus julgará o mundo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Pois se, através da minha mentira, a verdade de Deus foi mais abundante para a sua glória, por que ainda sou também julgado como pecador?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'E por que não dizer: “Façamos o mal, para que venha o bem”, como alguns nos caluniam, afirmando que nós dizemos isto? (A condenação destes é justa).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Então, quê? Somos nós melhores? Não, de maneira nenhuma. Pois já delatamos que todos, tanto judeus como gregos, estão debaixo do pecado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'como está escrito: Não há justo, nem um sequer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Ninguém há que entenda, ninguém há que busque a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Todos se desviaram, e juntamente se tornaram inúteis. “Não há quem faça o bem, não há um sequer”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, '“Suas gargantas são sepulcro aberto; com suas línguas enganam”; “veneno de serpentes está sob seus lábios”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, '“Suas bocas estão cheias de maldição e amargura”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, '“Seus pés são velozes para derramar sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Destruição e miséria há em seus caminhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'e não conheceram o caminho da paz”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, '“Diante dos seus olhos não há temor a Deus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Ora, sabemos que tudo o que a Lei diz, diz aos que estão na Lei, para que toda boca se cale, e todo o mundo seja condenável perante Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Assim, ninguém será justificado diante dele pelas obras da Lei, porque o que vem pela Lei é o conhecimento do pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Mas agora, independentemente da Lei, a justiça de Deus se manifestou, tendo testemunho da Lei e dos Profetas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'isto é, a justiça de Deus por meio da fé em Jesus Cristo, para todos e sobre todosos que creem; pois não há diferença;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'porque todos pecaram, e estão destituídos da glória de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'e são justificados gratuitamente pela sua graça, por meio da redenção que há em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Deus propôs Jesus por sacrifício de reconciliação, pela fé em seu sangue, para demonstrar a sua justiça. Ele deixou de considerar os pecados antes cometidos, sob a paciência de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'para demonstrar a sua justiça neste presente tempo, a fim de que ele seja justo, e justificador daquele que tem fé em Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Onde, pois, está o orgulho? Este é excluído. Por qual lei? A das obras? Não, mas sim, pela Lei da fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Concluímos, portanto, que o ser humano é justificado pela fé, independentemente das obras da Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Por acaso Deus é somente dos judeus, e não também dos gentios? Certamente que dos gentios também;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'já que há um só Deus, que justificará pela fé os circuncisos, e por meio da fé os incircuncisos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Por acaso anulamos a Lei pela fé? De maneira nenhuma. Pelo contrário, confirmamos a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Então, que diremos que Abraão, nosso ancestral segundo a carne, obteve?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Pois se Abraão foi justificado pelas obras, ele tem do que se orgulhar, mas não diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Pois o que diz a Escritura? Abraão creu em Deus, e isso lhe foi lhe imputado como justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Ora, ao que trabalha, seu pagamento não é considerado um favor, mas sim, uma dívida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Porém, ao que não tem obra, mas crê naquele que torna justo o ímpio, sua fé lhe é reputada como justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Desta maneira, também Davi afirma que bendito é aquele a quem Deus atribui justiça independentemente das obras:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Benditos são os que têm as transgressões perdoadas, e seus pecados são cobertos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Bendito é o homem a quem o Senhor não atribui pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Ora, essa bendição é somente para os circuncisos, ou também para os incircuncisos? Pois dizemos que a fé a Abraão foi reputada como justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Como, pois, lhe foi reputada? Enquanto ele estava na circuncisão ou na incircuncisão? Não na circuncisão, mas sim, na incircuncisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'E ele recebeu o sinal da circuncisão como selo da justiça da fé quando ainda era incircunciso, para que fosse pai de todos os que creem, ainda que não estejam circuncidados, para que a justiça também lhes seja imputada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'e para que fosse pai da circuncisão, dos que não somente são circuncidados, mas que também andam nos passos da fé do nosso pai Abraão, quando ainda não era circuncidado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Pois não foi pela Lei que a promessa de ser herdeiro do mundo foi feita a Abraão ou à sua descendência, mas sim, pela justiça da fé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'porque, se é da Lei que são os herdeiros, logo a fé se torna vazia, e a promessa é anulada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Pois a Lei produz ira, porque onde não há Lei, também não há transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Por isso é pela fé, para que seja conforme a graça, a fim de que a promessa seja confirmada a todos os descendentes, não somente aos que são da Lei, mas também aos que são da fé de Abraão, que é Pai de todos nós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(como está escrito: “Eu te constituí pai de muitas nações”) diante daquele em quem ele creu, Deus, que vivifica os mortos, e chama as coisas que não são como se já fossem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Com esperança, Abraão creu, contra as expectativas, que se tornaria pai de muitas nações, conforme o que lhe fora dito: “Assim será a tua descendência”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Ele não fraquejou na fé, não dando atenção ao seu próprio corpo já praticamente morto (pois já era de quase cem anos), nem ao estado de morte do ventre de Sara;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'nem duvidou da promessa de Deus; pelo contrário, fortaleceu-se na fé, dando glória a Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'e teve plena certeza de que aquele que havia prometido também era poderoso para cumprir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Por esse motivo que também isso lhe foi imputado como justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Ora, não só por causa dele está escrito que lhe foi imputado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'mas também por nós, a quem será imputado, aos que creem naquele que ressuscitou dos mortos a Jesus, nosso Senhor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'que foi entregue por nossos pecados, e ressuscitou para a nossa justificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Portanto, agora que somos justificados pela fé, temos paz com Deus por meio do nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Por meio dele também temos acesso pela fé a esta graça, na qual estamos firmes, e nos alegramos na esperança da glória de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'E não somente isso, mas também nos alegramos nas tribulações, sabendo que a tribulação produz paciência;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'a paciência produz experiência, e a experiência produz esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'E a esperança não frustra, porque o amor de Deus está derramado em nossos corações pelo Espírito Santo que nos foi dado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Pois quando ainda éramos fracos, Cristo morreu a seu tempo pelos ímpios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Ora, dificilmente alguém morre por um justo, ainda que talvez alguém possa ousar morrer por uma boa pessoa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Mas Deus prova o seu amor por nós através de Cristo haver morrido por nós, quando ainda éramos pecadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Por isso, muito mais agora, que já somos justificados por seu sangue, seremos por ele salvos da ira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Pois, se quando éramos inimigos, fomos reconciliados com Deus pela morte do seu Filho, muito mais, tendo sido reconciliados, seremos salvos pela sua vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'E não somente isso, mas também nos alegramos em Deus por meio do nosso Senhor Jesus Cristo, por quem agora recebemos a reconciliação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Portanto, assim como por um homem o pecado entrou no mundo, e pelo pecado a morte, assim também a morte passou a todos os seres humanos, porque todos pecaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Pois, antes da Lei, o pecado já existia no mundo; porém, quando não há Lei, o pecado não é considerado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Mas a morte reinou desde Adão até Moisés, até sobre aqueles que não pecaram à semelhança da transgressão de Adão, o qual era uma figura daquele que estava para vir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mas o dom gratuito não é como a transgressão; porque, se pela transgressão de um, muitos morreram, muito mais a graça de Deus, e o dom pela graça de um homem, Jesus Cristo, têm sido abundantes sobre muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'E o dom não é como a transgressão de um que pecou; porque o julgamento de uma só transgressão trouxe condenação, mas o dom gratuito, de muitas transgressões, trouxe justificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Pois, se pela transgressão de um, a morte reinou por causa desse, muito mais os que recebem a abundância da graça, e do dom da justiça reinarão em vida por um só, Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Portanto, assim como uma transgressão resultou em condenação sobre todos os seres humanos, assim também um ato de justiça resultou em justificação da vida sobre todos os seres humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Pois, assim como pela desobediência de um só homem muitos foram feitos pecadores, assim também, pela obediência de um só, muitos serão justificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'A Lei veio para que a transgressão aumentasse; mas onde o pecado aumentou, a graça superabundou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'a fim de que, assim como o pecado reinou para a morte, também a graça reine pela justiça para a vida eterna, por meio de Jesus Cristo, nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Que diremos, pois? Continuaremos no pecado, para que a graça aumente?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'De maneira nenhuma! Nós, que morremos para o pecado, como ainda viveremos nele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ou não sabeis que todos os que somos batizados em Cristo Jesus, somos batizados em sua morte?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Por isso, estamos sepultados com ele pelo batismo na morte; para que, assim como Cristo ressuscitou dos mortos para a glória do Pai, assim também nós andemos em novidade de vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Pois, se fomos unidos a ele na semelhança de sua morte, também o seremos na da sua ressurreição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'E sabemos isto: que o nosso velho ser foi crucificado com ele, para que o corpo do pecado seja extinto, a fim de que não mais sirvamos ao pecado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'pois o que está morto já está absolvido do pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Ora, se já morremos com Cristo, cremos que também com ele viveremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Porque sabemos que, depois que Cristo foi ressuscitado dos mortos, já não morre mais; a morte já não mais o domina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Pois, ao morrer, ele morreu para o pecado de uma vez por todas; mas, ao viver, vive para Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Assim também vós, considerai que estais mortos para o pecado, mas vivendo para Deus, em Cristo Jesus, nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Portanto, não reine o pecado em vosso corpo mortal, para obedecer a ele em seus maus desejos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Nem apresenteis os membros do vosso corpo ao pecado como instrumentos de injustiça; em vez disso, apresentai-vos a Deus, como vivos dentre os mortos, e vossos membros como instrumentos de justiça para Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Pois o pecado não vos dominará, porque não estais sob a Lei, mas sim, sob a graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Então, quê? Pecaremos, já que não estamos sob a Lei, mas sob a graça? De maneira nenhuma!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Não sabeis vós, que a quem vos apresentardes por servos para obedecer, sois servos daquele a quem obedeceis? Ou do pecado para a morte, ou da obediência para a justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Porém, graças a Deus que vós éreis servos do pecado, mas agora, de coração obedeceis à forma de doutrina a que vós fostes entregues;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'e, sendo libertos do pecado, vos tornastes servos da justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Estou falando na lógica humana, pela fraqueza de vossa carne. Pois, assim como apresentastes os membros do vosso corpo como servos da impureza e da maldade para a maldade, assim também apresentai agora os vossos membros como servos da justiça para a santificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Porque quando éreis servos do pecado, estáveis livres da justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Afinal, que fruto obtivestes das coisas de que agora vos envergonhais? Pois o fim delas é a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Mas agora, libertos do pecado, e feitos servos de Deus, tendes o vosso fruto para a santificação, e por fim a vida eterna;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'porque o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Não sabeis vós, irmãos (pois estou falando com os que entendem a Lei), que a Lei domina o ser humano por todo o tempo que vive?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Pois a mulher casada está, pela Lei, ligada ao marido enquanto o ele viver; porém, depois do marido morrer, ela está livre da Lei do marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Ou seja, enquanto o marido viver, ela será chamada de adúltera, se for de outro homem; mas depois de morto o marido, ela está livre da Lei, de maneira que não será adúltera se for de outro homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Assim, meus irmãos, também vós estais mortos para a Lei por meio do corpo de Cristo, para que sejais de outro, daquele que foi ressuscitado dos mortos, a fim de frutificarmos para Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Pois, quando estávamos na carne, as paixões dos pecados, que eram pela Lei, operavam nos membros do nosso corpo, a fim de frutificarem para a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Mas agora estamos livres da Lei, estando mortos para aquilo em que estávamos presos, para que sirvamos em novidade de espírito, e não na velhice da norma escrita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Que diremos, pois? É a Lei pecado? De maneira nenhuma! Todavia, eu não teria conhecido o pecado, se não fosse pela Lei; porque não conheceria a cobiça, se a Lei não dissesse: Não cobiçarás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Mas o pecado, aproveitando-se do mandamento, operou em mim toda variedade de cobiça. Pois sem a Lei o pecado estaria morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Antes eu vivia sem a Lei; mas quando veio o mandamento, o pecado reviveu, e eu morri;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'e descobri que o mandamento, que era para a vida, resultou-me para a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Pois o pecado, aproveitando o mandamento, me enganou, e por ele me matou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Portanto, a Lei é santa, e o mandamento é santo, justo, e bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Então o que é bom se tornou para mim morte? De maneira nenhuma! Mas foi o pecado, para que se mostrasse como pecado, que operou a morte em mim por meio do bem, a fim de que, por meio do mandamento, o pecado se tornasse excessivamente pecaminoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Pois sabemos que a Lei é espiritual; mas eu sou carnal, vendido como servo do pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Porque não entendo o que faço, pois o que quero, isso não faço; mas o que eu odeio, isso faço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'E se faço o que não quero, consinto que a Lei é boa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'De maneira que agora não sou mais eu que faço aquilo, mas sim, o pecado que habita em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Porque sei que em mim, isto é, em minha carne, não habita bem algum; porque o querer está em mim; porém o fazer o bem eu não consigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Pois o bem que quero, não faço; mas o mal que não quero, isso faço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Ora, se faço o que não quero, não sou eu que faço, mas sim, o pecado que habita em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Acho, então, esta Lei: que quando quero fazer o bem, o mal está comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Pois, quanto ao ser interior, tenho prazer na Lei de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'mas em meus membros vejo outra lei, que batalha contra a lei do meu entendimento, e me prende sob a lei do pecado, que está nos meus membros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Miserável homem que sou! Quem me livrará deste corpo de morte?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Agradeço a Deus por Jesus Cristo, nosso Senhor. Assim, eu mesmo com o entendimento sirvo à Lei de Deus, mas, com a carne, à Lei do pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Portanto, agora, nenhuma condenação há para os que estão em Cristo Jesus, que não andam segundo a carne, mas sim segundo o Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Porque a Lei do Espírito de vida, em Cristo Jesus, me livrou da Lei do pecado e da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Pois o que era impossível para a Lei, porque estava enferma pela carne, Deus fez: ele enviou o seu próprio Filho em semelhança da carne pecadora, e por causa do pecado, condenou o pecado na carne,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'para que a exigência da lei se cumprisse em nós, que andamos, não segundo a carne, mas sim, segundo o Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Pois os que são segundo a carne costumam pensar nas coisas da carne, mas os que são segundo o Espírito, nas coisas do Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Pois a mentalidade da carne é morte, mas a mentalidade do Espírito é vida e paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Pois a mentalidade da carne é inimizade contra Deus, pois não se sujeita à Lei de Deus, porque nem sequer pode.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Portanto os que estão na carne não podem agradar a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Porém vós não estais na carne, mas sim, no Espírito, se é que o Espírito de Deus habita em vós. Porém, se alguém não tem o Espírito de Cristo, esse não lhe pertence.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'E se Cristo está em vós, apesar do corpo estar morto por causa do pecado, o Espírito é vida por causa da justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'E se o Espírito daquele que dos mortos ressuscitou a Jesus habita em vós, aquele que dos mortos ressuscitou Cristo também dará vida aos vossos corpos mortais por meio do seu Espírito, que habita em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Por isso, irmãos, somos devedores, não à carne, para vivermos segundo a carne;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'porque, se viverdes segundo a carne, morrereis; mas se pelo Espírito mortificardes as obras do corpo, vivereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Pois todos quantos são guiados pelo Espírito de Deus são filhos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Pois não recebestes o espírito de escravidão, para voltardes ao medo; mas recebestes o Espírito de adoção como filhos, pelo qual clamamos: Aba, Pai!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'O próprio Espírito dá testemunho com o nosso espírito de que somos filhos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'E, se somos filhos, logo somos também herdeiros; herdeiros de Deus, e coerdeiros de Cristo; se sofremos com ele, é para que também com ele sejamos glorificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Pois considero que as aflições deste tempo presente nem se comparam com a glória que nos será revelada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Pois a criação espera ansiosamente a revelação dos filhos de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'porque a criação ficou sujeita à futilidade (não por vontade própria, mas sim por causa daquele que a sujeitou),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'na esperança de que também a mesma criação seja liberta da escravidão da degradação para a liberdade da glória dos filhos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Pois sabemos que toda a criação geme e sofre dores como as de parto até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'E não somente isso, mas também nós, que temos os primeiros frutos do Espírito, gememos em nós mesmos, esperando a adoção, isto é, a redenção do nosso corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Pois fomos salvos na esperança. Ora, a esperança que se vê não é esperança; afinal, por que alguém ainda espera o que já vê?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Mas, se esperamos o que não vemos, com paciência esperamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'E da mesma maneira também o Espírito ajuda em nossas fraquezas. Pois não sabemos orar como se deve, mas o próprio Espírito intercede por nós com gemidos inexprimíveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'E aquele que examina os corações sabe qual é a intenção do Espírito, pois ele intercede pelos santos, segundo a vontade de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'E sabemos que todas as coisas juntamente contribuem para o bem daqueles que amam a Deus, dos que são chamados segundo o seu propósito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Pois aos que desde antes conheceu, também os predestinou para serem conformes à imagem do seu Filho, para que ele seja o primogênito entre muitos irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'E aos que predestinou, a esses também chamou; e aos que chamou, a esses também justificou; e aos que justificou, a esses também glorificou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Então, que diremos acerca dessas coisas? Se Deus é por nós, quem será contra nós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Aquele que nem mesmo ao seu próprio Filho poupou, como não nos dará também com ele todas as coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Quem fará acusação contra os escolhidos de Deus? Deus é quem justifica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Quem os condenará? Cristo é o que morreu; além disto é o que também ressuscitou; o que também está à direita de Deus, e que intercede por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Quem nos separará do amor de Cristo? A aflição, a angústia, a perseguição, a fome, a nudez, o perigo, ou a espada?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Como está escrito: “Pois por causa de ti somos entreges à morte o dia todo; somos contados como ovelhas para o matadouro”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Mas em todas estas coisas somos mais que vencedores, por meio daquele que nos amou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Pois tenho certeza que nem a morte, nem a vida, nem anjos, nem principados, nem poderes, nem o presente, nem o futuro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'nem altura, nem profundeza, nem qualquer outra criatura poderá nos separar do amor de Deus, que está em Cristo Jesus, nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Digo a verdade em Cristo, não minto, e minha consciência dá testemunho comigo pelo Espírito Santo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'de que tenho grande tristeza e contínuo tormento em meu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Porque desejaria eu mesmo ser separado de Cristo em proveito dos meus irmãos, que são meus parentes segundo a carne;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'que são israelitas, e a quem pertencem a adoção como filhos, a glória, os pactos, a Lei, o culto, e as promessas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'deles são os patriarcas, e deles, quanto à carne, é Cristo, que é sobre todos, Deus bendito eternamente, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Não que a palavra de Deus tenha falhado; porque nem todos os que são de Israel são verdadeiros israelitas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Nem por serem descendentes de Abraão são todos filhos, mas: “Em Isaque será chamada a tua descendência”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Isto é, não são os filhos da carne que são os filhos de Deus; mas sim os filhos da promessa que são contados como descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Pois esta é a palavra da promessa: Aproximadamente a este tempo virei, e Sara terá um filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'E não somente isso, mas também Rebeca, quando esteve grávida por intermédio de um só, Isaque, nosso ancestral');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, '(pois, como não eram ainda nascidos, não haviam feito bem ou mal, para que o propósito de Deus, segundo a escolha, continuasse; não pelas obras, mas por causa daquele que chama),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'foi dito a ela: O mais velho servirá o mais jovem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'como está escrito: “Amei Jacó, mas odiei Esaú”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Que diremos, então? Que há injustiça da parte de Deus? De maneira nenhuma!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Pois ele diz a Moisés: “Terei misericórdia de quem eu tiver misericórdia, e me compadecerei de quem eu me compadecer”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Portanto, não depende daquele que quer, nem daquele que se esforça, mas sim, de Deus, que se compadece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Pois a Escritura diz a Faraó: “Para isto mesmo te levantei: para mostrar em ti o meu poder, e para que o meu nome seja anunciado em toda a terra”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Portanto, ele tem misericórdia de quem quer, e endurece a quem quer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Tu, então, me dirás: “Por que ele ainda se queixa? Pois quem resiste à sua vontade?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Mas antes, quem és tu, ó, humano, para questionares a Deus? Por acaso a coisa formada dirá ao que a formou: “Por que me fizeste assim?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Ou não tem o oleiro poder sobre o barro, para da mesma massa fazer um vaso para honra, e outro para desonra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'E se Deus, querendo mostrar a sua ira, e dar a conhecer o seu poder, suportou com muita paciência os vasos da ira, preparados para a perdição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'a fim de fazer conhecidas as riquezas da sua glória nos vasos da misericórdia, que preparou com antecedência para a glória,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'que somos nós, aos quais ele chamou, não somente dentre os judeus, mas também dentre os gentios?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Como também diz em Oseias: “Ao que era Não-Meu-Povo, chamarei de Meu-Povo; e a que não era Não-Amada, chamarei de Amada”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'E será que, no lugar onde lhes foi dito: “Vós não sois meu povo, Aí serão chamados filhos do Deus vivo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Também Isaías clama acerca de Israel: “Ainda que o número dos filhos de Israel seja como a areia do mar, apenas o remanescente será salvo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'porque o Senhor concluirá e executará brevemente a sentença em justiça; pois ele fará uma breve sentença sobre a terra”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'E como Isaías predisse: “Se o Senhor dos Exércitos não houvesse nos deixado descendência, nós nos teríamos tornado como Sodoma, e como Gomorra teríamos sido semelhantes”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Então, que diremos? Que os gentios, que não buscavam a justiça, alcançaram a justiça, mas a justiça que é pela fé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'porém, Israel, que buscava a Lei da justiça, não alcançou a Lei da justiça');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Por quê? Porque não a buscavam pela fé, mas sim, como que pelas obras da Lei;pois tropeçaram na pedra de tropeço,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'como está escrito: “Eis que ponho em Sião uma pedra de tropeço, e uma rocha de escândalo; e todo aquele que nela crer não será envergonhado”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Irmãos, o bom desejo do meu coração, e a oração que faço a Deus por Israel, é que sejam salvos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Pois lhes dou testemunho de que eles têm zelo por Deus, mas não com entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Pois, como ignoraram a justiça de Deus, e procuraram estabelecer a sua própria justiça, eles não se sujeitaram à justiça de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Porque o fim da Lei é Cristo, para justiça de todo aquele que crê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Pois Moisés descreve a justiça que é pela Lei: “A pessoa que praticar estas coisas viverá por elas”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Mas a justiça que é pela fé assim diz: “Não digas em teu coração: ‘Quem subirá ao céu?’ (Isto é, trazer Cristo abaixo),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'ou: ‘Quem descerá ao abismo?’” (Isto é, trazer Cristo dentre os mortos).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Porém, o que diz? “A palavra está perto de ti, na tua boca, e no teu coração”. Esta é a palavra da fé, que pregamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Pois, se com a tua boca declarares que Jesus é Senhor, e em teu coração creres que Deus o ressuscitou dos mortos, serás salvo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Pois com o coração se crê para a justiça, e com a boca se confessa para a salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Porque a Escritura diz: “Todo aquele que nele crê não será envergonhado.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Pois não há diferença entre judeu e grego, porque um mesmo é o Senhor de todos, rico para todos os que o invocam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Pois: “Todo aquele que invocar o nome do Senhor será salvo.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Mas como invocarão em quem não creram? E como crerão naquele de quem não ouviram? E como ouvirão sem haver quem pregue?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'E como pregarão se não forem enviados? Como está escrito: “Como são agradáveis os pés dos que anunciam o evangelho da paz, dos que anunciam as boas novas!”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Mas nem todos obedeceram ao Evangelho, pois Isaías diz: “Senhor, quem creu na nossa pregação?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Portanto, a fé vem pelo ouvir, e o ouvir pela palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mas pergunto: por acaso não ouviram? Sim, certamente. Pois: “Sua voz saiu por toda a terra, e suas palavras até os confins do mundo.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Mas pergunto: por acaso Israel não entendeu? Primeiramente Moisés disse: “Eu vos provocarei ciúmes com os que não são do povo; com uma nação insensata vos provocarei à ira.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'E Isaías ousou dizer: “Fui achado pelos que não me buscavam; fui revelado aos que por mim não perguntavam.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Mas sobre Israel diz: “Todo o dia estendi as minhas mãos a um povo rebelde e hostil.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Então pergunto: por acaso Deus rejeitou seu povo? De maneira nenhuma! Pois também eu sou israelita, da descendência de Abraão, da tribo de Benjamim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Deus não rejeitou seu povo, o qual desde antes conhecia. Ou não sabeis o que a Escritura diz de Elias? Como ele fala a Deus, contra Israel, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '“Senhor, mataram os teus profetas, e derrubaram os teus altares; só eu fiquei, e buscam tirar-me a vida.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mas o que lhe disse a divina resposta? “Reservei para mim sete mil homens que não dobraram os joelhos a Baal.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Portanto, também agora no presente tempo ficou um remanescente, escolhido pela graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'E, se é pela graça, logo não é pelas obras; de outra maneira, a graça já não é graça. E se é pelas obras, logo não é pela graça; de outra maneira a obra já não é obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Então, quê? O que Israel busca, isso não obteve; mas os escolhidos o obtiveram, e os demais foram endurecidos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'como está escrito: “Deus lhes deu espírito de insensibilidade; olhos que não veem, e ouvidos que não ouvem; até o dia de hoje.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'E Davi diz: “A mesa deles se torne em laço e armadilha; em tropeço e retribuição para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Seus olhos se escureçam, para que não vejam, e suas costas fiquem constantemente encurvadas.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Então, pergunto: por acaso tropeçaram para que caíssem? De maneira nenhuma! Mas pela queda deles a salvação veio aos gentios, para lhes provocarem ciúmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Ora, se a queda deles é o enriquecimento do mundo, e se o prejuízo deles é o enriquecimento dos gentios, quanto mais a sua plenitude!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Pois falo a vós mesmos, gentios; como sou apóstolo dos gentios, honro meu ministério,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'a fim de que, de alguma maneira, eu provoque ciúmes aos do meu povo, e salve alguns deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Pois, se a rejeição deles é a reconciliação do mundo, o que será sua admissão, senão vida dentre os mortos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'E se as primícias são santas, a massa também é; e se a raiz é santa, os ramos também são.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Porém, se alguns dos ramos foram quebrados e separados, e sendo tu oliveira selvagem, foste enxertado no lugar deles, e feito participante da raiz, e nutrido pela boa oliveira,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'não te orgulhes de ser melhor que os ramos. Mesmo se te orgulhares, não és tu que sustentas a raiz, mas sim, a raiz a ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Tu, então, dirás: “Os ramos foram quebrados para que eu fosse enxertado.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'É verdade. Por causa da incredulidade eles foram quebrados, e tu, por causa da fé estás firme. Não tenhas orgulho, mas sim temor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'pois, se Deus não poupou os ramos naturais, ele poderá não poupar a ti também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Olha, pois, a bondade e severidade de Deus; a severidade sobre os que caíram, mas a bondade sobre ti, se continuares na bondade; de outra maneira, também tu serás cortado fora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'E também eles, se não continuarem na incredulidade, serão enxertados, porque Deus é poderoso para enxertá-los de volta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Pois, se tu foste cortado da oliveira naturalmente selvagem, e contra a natureza enxertado na oliveira boa, quanto mais estes, que são naturais, serão enxertados na sua própria oliveira!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Não quero, irmãos, que ignoreis este mistério, para que não sejais sábios apenas a vós mesmos: o endurecimento veio em parte sobre Israel, até que a plenitude dos gentios tenha entrado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'e assim, todo o Israel será salvo, como está escrito: “O Libertador virá de Sião, e afastará as irreverências de Jacó.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'E este será o meu pacto com eles, quando eu tirar os seus pecados.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Assim, quanto ao Evangelho, eles são inimigos, para benefício vosso; mas quanto à escolha divina, são amados, por causa dos patriarcas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Pois os dons gratuitos e o chamado da parte de Deus não podem ser cancelados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Pois, assim como vós também antigamente fostes desobedientes a Deus, agora recebestes misericórdia pela desobediência deles,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'assim também agora eles foram desobedientes, a fim de que, pela misericórdia que foi a vós concedida, eles também recebam misericórdia;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'porque Deus pôs todos debaixo da desobediência, a fim de ter misericórdia para com todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ó profundidade das riquezas, tanto da sabedoria como do conhecimento de Deus! Quão incompreensíveis são os seus juízos, e inimagináveis os seus caminhos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Pois quem entendeu a mentalidade do Senhor? Ou quem foi o seu conselheiro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Ou quem lhe deu primeiro, para ser por ele recompensado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Porque dele, por ele, e para ele, são todas as coisas! A ele seja a glória eternamente! Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Rogo-vos, pois, irmãos, pelas misericórdias de Deus, que apresenteis os vossos corpos como sacrifício vivo, santo e agradável a Deus, que é o vosso culto racional.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'E não vos conformeis com a presente era; em vez disso, transformai-vos pela renovação da vossa mentalidade, para que experimenteis qual seja a boa, agradável, e perfeita vontade de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Pois, pela graça que me foi dada, digo a cada um dentre vós que não se estime mais do que convém se estimar; em vez disso, cada um estime a si mesmo com bom senso, conforme a medida de fé que Deus repartiu a cada um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Porque assim como em um corpo temos muitos membros, e nem todos os membros têm a mesma função,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'assim também nós, ainda que muitos, somos um único corpo em Cristo; porém, individualmente, membros uns dos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Temos, contudo, diferentes dons, segundo a graça que nos foi dada: se é o de profecia, seja segundo a medida da fé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'se é o de serviço, seja em servir; se é o de ensino, seja em ensinar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'se é o de exortação, seja em exortar; o que reparte, reparta com generosidade; o que lidera, lidere com empenho, o que usa de misericórdia, faça-o com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'O amor seja sem hipocrisia. Odiai o mal, e apegai-vos ao bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Amai-vos cordialmente uns aos outros com amor de irmãos, preferindo honrar uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Não sejais vagarosos em mostrardes empenho. Sede fervorosos de espírito. Servi ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Alegrai-vos na esperança. Sede pacientes na aflição. Perseverai na oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Compartilhai com os santos em suas necessidades. Buscai ser hospitaleiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Abençoai os que vos perseguem; abençoai, e não amaldiçoeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Alegrai-vos com os que se alegram, e chorai com os que choram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Estimai-vos uns aos outros como semelhantes. Não fiqueis pensando com soberba; em vez disso, acompanhai-vos dos humildes. Não sejais sábios em vós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'A ninguém pagueis o mal com o mal; buscai fazer o que é certo diante de todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'No que for possível de vossa parte, tende paz com todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Não vos vingueis por vós mesmos, amados. Em vez disso, dai lugar à ira divina,porque está escrito: A mim pertence a vingança, eu retribuirei, diz o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Portanto, se o teu inimigo tiver fome, dá-lhe de comer; se tiver sede, dá-lhe de beber. Pois, quando fizeres isto, estarás amontoando brasas de fogo sobre a cabeça dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Não sejas vencido pelo mal, mas vence o mal com o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Toda pessoa esteja sujeita às autoridades superiores, porque não há autoridade que não seja da parte de Deus; e as autoridades que existem são ordenadas por Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Por isso, quem se opõe à autoridade resiste à ordem de Deus; e os que lhe resistem trarão a si mesmos condenação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Pois os que possuem autoridade não causam temor às boas obras, mas sim, às más. Queres tu não ter medo de autoridade? Faz o bem, e dela receberás elogio,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'porque ela é serva de Deus para o teu bem. Porém, se fizeres o mal, teme; porque ela não traz a espada em vão. Pois é serva de Deus, vingadora, para castigar a quem faz o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Portanto, é necessário estar sujeito não somente por causa do castigo, mas também por causa da consciência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Por isso também pagais impostos; porque são servidores de Deus, atendendo a essa função.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Portanto, dai a cada um o que deveis; a quem imposto, imposto; a quem taxa, taxa; a quem temor, temor; a quem honra, honra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'A ninguém devais coisa alguma, a não ser o amor uns aos outros, pois quem ama o outro tem cumprido a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Porque estes mandamentos: não adulterarás, não matarás, não roubarás, não dirás falso testemunho, não cobiçarás; e qualquer outro mandamento que há, nesta frase se resumem: “Amarás ao teu próximo como a ti mesmo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'O amor não faz mal ao próximo. Assim, o cumprimento da Lei é o amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Além disso, conheceis o tempo, que já é hora de despertarmos do sono, porque a salvação está agora mais perto de nós do que quando começamos a crer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'A noite está se acabando, e o dia, chegando. Deixemos, pois, as obras das trevas, e vistamo-nos das armas da luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Andemos de maneira decente, como de dia; não em orgias e bebedeiras; não em pecados sexuais ou depravações; não em brigas, nem em inveja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Em vez disso, revesti-vos do Senhor Jesus Cristo, e não fiqueis pensando em realizar os desejos da carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Recebei a quem for fraco na fé, mas não para envolvê-lo em temas controversos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Um crê que pode comer de tudo, e outro, que é fraco, come somente vegetais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'O que come não despreze o que não come, e o que não come não julgue o que come, porque Deus o aceitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Quem és tu para julgares o servo alheio? É ao seu próprio senhor que ele fica firme ou cai. E ele ficará firme, porque Deus é poderoso para o firmar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Um faz diferença entre um dia e outro; porém outro considera iguais todos os dias. Cada um mantenha certeza em sua própria mente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'O que faz diferença entre dias, para o Senhor a faz; e aquele que não faz diferença entre dias, para o Senhor não a faz. O que come, come para o Senhor, porque dá graças a Deus; e o que não come, deixa de comer para o Senhor, e dá graças a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Pois nenhum de nós vive para si mesmo; e nenhum morre para si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Porque, se vivemos, para o Senhor vivemos; e se morremos, para o Senhor morremos. Portanto, quer vivamos, quer morramos, do Senhor somos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Pois para isto Cristo também morreu, ressuscitou, e voltou a viver, para ser Senhor tanto dos mortos como dos vivos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Tu, porém, por que julgas o teu irmão? Ou tu também, por que desprezas o teu irmão? Pois todos nós seremos apresentados diante do tribunal de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Porque está escrito: “Tão certo como eu vivo, diz o Senhor, que todo joelho se dobrará diante de mim, e toda língua confessará a Deus”;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'de maneira que cada um de nós dará conta de si mesmo a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Portanto, não julguemos mais uns aos outros; em vez disso, decidi nunca pôr alguma pedra de obstáculo ou de tropeço diante do seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Eu sei, e tenho certeza no Senhor Jesus, que nada é impuro por si mesmo; a não ser para quem o considera impuro: aquilo para ele se torna impuro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Mas, se por causa do que comes o teu irmão se entristece, tu já não estás andando segundo o amor. Não destruas por tua comida aquele por quem Cristo morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Não seja insultado o vosso bem,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'porque o reino de Deus não é comida nem bebida, mas sim justiça, paz, e alegria no Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Pois quem nessas coisas serve a Cristo é agradável a Deus e aprovado pelas pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Sigamos, pois, as coisas que resultam em paz e edificação de uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Não destruas a obra de Deus por causa da comida. É verdade que todas as coisas são limpas, porém mau é ao ser humano comer causando ofensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Não é bom comer carne, nem beber vinho, nem qualquer coisa que faça o teu irmão tropeçar, ou se ofender, ou enfraquecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'A convicção que tu tens, tenha-a para ti mesmo diante de Deus. Feliz é quem não se culpa naquilo que aprova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Mas aquele que tem dúvida, se comer, é culpado, porque não foi pela fé; e tudo que não é pela fé é pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Mas nós, que somos fortes, devemos suportar as fraquezas dos fracos, e não agradar a nós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Portanto, cada um de nós agrade ao próximo no que é bom para a edificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Pois também Cristo não agradou a si mesmo; mas, como está escrito: “Os insultos dos que te insultavam caíram sobre mim”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Pois todas as coisas que foram escritas com antecedência foram escritas para o nosso ensino; para que, pela paciência e consolação das Escrituras, tenhamos esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'O Deus da paciência e da consolação vos dê a mesma mentalidade uns para com os outros, segundo Cristo Jesus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'a fim de que, em comum acordo, como uma só boca, glorifiqueis ao Deus e Pai de nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Portanto, recebei uns aos outros, assim como também Cristo nos recebeu para a glória de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'E digo que Jesus Cristo se tornou servidor da circuncisão por causa da verdade de Deus, para confirmar as promessas feitas aos patriarcas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'e para que os gentios glorifiquem a Deus por causa de sua misericórdia, como está escrito: “Por isso entre os gentios te confessarei, e ao teu nome cantarei.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'E outra vez diz: “Alegrai-vos, gentios, com o povo dele.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'E outra vez: “Louvai ao Senhor todas as nações, e celebrai-o todos os povos.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'E outra vez Isaías diz: “Haverá a raiz de Jessé, e aquele que se levantará para governar as nações; nele os gentios esperarão.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'O Deus da esperança vos encha de toda alegria e paz na fé, para que abundeis em esperança no poder do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Porém, meus irmãos, convencido estou acerca de vós de que também estais cheios de bondade, plenos de todo conhecimento, e capazes de também aconselhardes uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Mas, irmãos, em parte vos escrevi com mais ousadia, como que para vos relembrar, por causa da graça que me foi dada por Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'a fim de que eu seja um servidor de Jesus Cristo entre os gentios, ministrando o evangelho de Deus, para que a oferta dos gentios seja agradável, santificada pelo Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Assim eu me orgulho em Jesus Cristo das coisas relacionadas a Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Pois eu não ousaria falar coisa alguma, a não ser o que Cristo fez por meio de mim, para tornar os gentios obedientes, por meio da palavra e da obra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'com poder de sinais e milagres, no poder do Espíritode Deus; de maneira que desde Jerusalém e redondezas até Ilírico, cumpri a pregação do Evangelho de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'E assim quis muito anunciar o Evangelho onde Cristo não houvesse sido pregado, para que eu não construísse sobre fundamento alheio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'ao contrário, como está escrito: “Aqueles a quem dele não foi anunciado o verão; e os que não ouviram entenderão.”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Por isso também muitas vezes tenho sido impedido de ir até vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Mas agora, como nessas regiões não há mais lugar em que eu precise trabalhar, e já por muitos anos tive grande desejo de ir até vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'quando eu for para a Espanha pois espero vos ver no caminho, e receber ajuda de vossa parte para a viagem, depois de primeiramente ficar um tempo satisfazendo o desejo de estar convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Mas por ora, vou a Jerusalém, a fim de auxiliar os santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Pois, aos da Macedônia e Acaia pareceu bem fazer uma contribuição para os pobres dentre os santos que estão em Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Isso lhes pareceu bem, como quem está em dívida para com eles; porque, se os gentios foram participantes dos seus bens espirituais, devem também ajudá-los com os materiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Assim que eu concluir isso, e garantir a entrega desse fruto a eles, partirei para a Espanha passando para vos visitar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'E sei que, quando chegar até vós, virei com a plenitude da bênção do Evangelho de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Rogo-vos, porém, irmãos, pelo nosso Senhor Jesus Cristo, e pelo amor do Espírito, que luteis comigo em orações a Deus por mim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'para que eu esteja livre dos rebeldes na Judeia, e que este meu serviço em Jerusalém seja bem aceito pelos santos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'a fim de que eu possa chegar até vós com alegria, pela vontade de Deus, e que eu possa descansar convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'E o Deus da paz esteja com todos vós. Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Eu vos recomendo a nossa irmã Febe, que é servidora da Igreja que está em Cencreia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'para que a recebais no Senhor, como convém aos santos; e para que a ajudeis em qualquer coisa que necessitar de vós; pois ela tem ajudado a muitos, inclusive a mim mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Saudai a Priscila e a Áquila, meus cooperadores em Cristo Jesus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'que arriscaram seus pescoços por minha vida; a eles não somente eu agradeço, como também todas as igrejas dos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Saudai também a igreja que se reúne na casa deles. Saudai Epêneto, meu amado, que é o primeiro fruto da Acaia para Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Saudai Maria, que trabalhou muito por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Saudai Andrônico e Júnia, meus parentes, e meus companheiros na prisão, que são notáveis entre os apóstolos, e também estavam antes de mim em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Saudai Amplias, meu amado no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Saudai Urbano, nosso cooperador em Cristo, e Estáquis, meu amado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Saudai Apeles, aprovado em Cristo. Saudai os que são da casa de Aristóbulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Saudai Herodião, meu parente. Saudai os que são da casa de Narciso, que estão no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Saudai Trifena e Trifosa, que trabalham no Senhor. Saudai a amada Pérside, que trabalhou muito no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Saudai Rufo, o escolhido no Senhor, e a mãe dele, e minha também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Saudai Asíncrito, Flegonte, Hermas, Pátrobas, Hermes e os irmãos que estão com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Saudai Filólogo, Júlia, Nereu e sua irmã, Olimpas, e todos os santos que estão com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Saudai-vos uns aos outros com beijo santo. As igrejas de Cristo vos saúdam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'E rogo-vos, irmãos, que sejais cuidadosos com os que causam divisões e ofensas contrárias a doutrina que aprendestes; e afastai-vos deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'pois tais pessoas não servem ao nosso Senhor Jesus Cristo, mas sim, ao próprio ventre; e com palavras suaves e elogios enganam os corações dos ingênuos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Pois a vossa obediência chegou ao conhecimento de todos. Por isso eu me alegro por vossa causa; quero, porém, que sejais sábios no bem, e inocentes quanto ao mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'E o Deus de paz esmagará Satanás em pedaços debaixo dos vossos pés. A graça de nosso Senhor Jesus Cristo seja convosco. Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Saúdam-vos o meu cooperador Timóteo, e os meus parentes Lúcio, Jáson, e Sosípatro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Eu, Tércio, que escrevi esta carta, vos saúdo no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaio, hospedeiro meu e toda a igreja, vos saúda. Erasto, tesoureiro da cidade, vos saúda, e também o irmão Quarto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'A graça de nosso Senhor Jesus Cristo seja com todos vós, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Ora, para aquele que tem o poder de vos manter firmes segundo o meu Evangelho e a pregação de Jesus Cristo, conforme a revelação do mistério, que foi encoberto desde o princípio dos tempos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Mas agora se manifestou, e se tornou conhecido pelas Escrituras dos profetas, segundo o mandado do Deus eterno, para a obediência da fé entre todas as nações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Ao único Deus sábio seja a glória, por meio de Jesus Cristo, para todo o sempre! Amém! Escrita de Corinto aos Romanos, e enviada por Febe, servidora da igreja de Cencreia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulo, chamado apóstolo de Jesus Cristo pela vontade de Deus, e o irmão Sóstenes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'À igreja de Deus que está em Corinto, aos santificados em Cristo Jesus, chamados santos, com todos os que em todo lugar invocam o nome de nosso Senhor Jesus Cristo, Senhor deles, e nosso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Graça seja convosco, e a paz de Deus nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Sempre agradeço ao meu Deus por causa de vós, pela graça de Deus, que é dada a vós em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Que em todas as coisas estais enriquecidos nele, em toda palavra, e em todo conhecimento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Assim como o testemunho de Jesus Cristo foi confirmado entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'De maneira que nenhum dom vos falta, enquanto esperais a manifestação do nosso Senhor Jesus Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'o qual também vos firmará até o fim, irrepreensíveis no dia de nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Deus é fiel, por quem fostes chamados para a comunhão do seu Filho Jesus Cristo, nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Mas eu vos rogo, irmãos, pelo nome do nosso Senhor Jesus Cristo, que todos faleis uma mesma coisa, e não haja divisões entre vós; antes estejais juntos com o mesmo entendimento, e com a mesma opinião.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Porque, irmãos meus, me foi informado de vós, pelos da casa de Cloé, que há brigas entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'E digo isto, que cada um de vós diz: “Eu sou de Paulo” e “Eu sou de Apolo” e “Eu sou de Cefas” e “Eu sou de Cristo”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Cristo está dividido? Paulo foi crucificado por vós? Ou fostes vós batizados no nome de Paulo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Agradeço a Deus que batizei nenhum de vós, a não ser Crispo e Gaio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'para que ninguém diga que eu tenha batizado em meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Também batizei aos da casa de Estefanas; além desses, não sei se batizei algum outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Porque Cristo não me enviou para batizar, mas sim, para evangelizar; não com sabedoria de palavras, para que a cruz de Cristo não se torne inútil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Porque a palavra da cruz é loucura para os que perecem; mas para os que se salvam é poder de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Porque está escrito: Destruirei a sabedoria dos sábios, e aniquilarei a inteligência dos inteligentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Onde está o sábio? Onde está o escriba? Onde está o questionador destes tempos? Por acaso Deus não fez de loucura a sabedoria deste mundo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Porque já que, na sabedoria de Deus, o mundo não conheceu a Deus pela sabedoria, Deus se agradou de salvar aos crentes pela loucura da pregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Porque os judeus pedem sinal, e os gregos buscam sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Mas nós pregamos a Cristo crucificado, que é escândalo para os Judeus, e loucura para os gregos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Porém aos que são chamados, tanto judeus como gregos, Cristo é poder de Deus e sabedoria de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Porque a loucura de Deus é mais sábia que os seres humanos; e a fraqueza de Deus é mais forte que os seres humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Vede, pois, o vosso chamado, irmãos; pois dentre vós não há muitos sábios segundo a carne, nem muitos poderosos, nem muitos da elite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Mas Deus escolheu as coisas loucas deste mundo para envergonhar as sábias; e Deus escolheu as fracas deste mundo, para envergonhar as fortes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'E Deus escolheu as coisas desprezíveis deste mundo, e as sem valor, e as que não são, para aniquilar as que são.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Para que ninguém orgulhe de si diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Mas vós sois dele em Jesus Cristo, o qual de Deus nos foi feito sabedoria, e justiça, e santificação, e resgate.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Para que, como está escrito: Aquele que se orgulha, orgulhe-se no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'E eu, irmãos, quando vim até vós, não vim vos anunciar o testemunho de Deus com excelência de palavras, ou sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Porque não quis saber coisa alguma entre vós, a não ser Jesus Cristo, e a sua crucificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'E eu estive convosco em fraqueza, em temor, e em grande tremor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'E a minha palavra e a minha pregação não foram em palavras persuasivas de sabedoria humana, mas sim, em demonstração do Espírito e de poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Para que a vossa fé não fosse em sabedoria humana, mas sim, em poder de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Contudo, falamos sabedoria entre os maduros, porém uma sabedoria não deste mundo, nem dos líderes deste mundo, que perecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Mas falamos a sabedoria de Deus, escondida em mistério, a qual Deus ordenou antes dos tempos para a nossa glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'A qual nenhum dos líderes deste mundo conheceu. Porque, se a tivessem conhecido, nunca crucificariam ao Senhor da glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Porém, assim como está escrito: As coisas que o olho não viu, e que no coração humano não subiram, são as que Deus preparou para os que o amam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Mas Deus as revelou para nós pelo seu Espírito. Porque o Espírito investiga todas as coisas, até as profundezas de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Pois quem dentre os seres humanos sabe as coisas que são do ser humano, senão o espírito do ser humano que nele está? Assim também ninguém sabe as coisas de Deus, senão o Espírito de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Nós, porém, não recebemos o espírito do mundo, mas sim, o Espírito que é de Deus; para que saibamos as coisas que nos são dadas por Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'As quais também falamos, não com palavras que a sabedoria ensina, mas com as que o Espírito Santo ensina, interpretando coisas espirituais por meios espirituais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Mas o ser humano natural não compreende as coisas que são do Espírito de Deus, porque lhe são loucura; e não as pode entender, porque se compreendem espiritualmente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Porém quem é espiritual compreende todas as coisas, mas não é compreendido por ninguém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Pois quem conheceu a mente do Senhor, para que o possa instruir? Mas nós temos a mente de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'E eu, irmãos, não pude vos falar como a espirituais, mas como a carnais, como a meninos em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Com leite eu vos criei, e não com alimento sólido, porque não podíeis; nem mesmo agora ainda podeis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'porque ainda sois carnais. Pois, havendo entre vós inveja, brigas, e divisões, por acaso não sois carnais, e andais fazendo conforme o costume humano?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Porque dizendo um: “Eu sou de Paulo”, e outro: “Eu sou de Apolo”, por acaso não sois carnais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Ora, quem é Paulo, e quem é Apolo, senão servidores, pelos quais crestes, conforme o Senhor deu a cada um?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Eu plantei; Apolo regou; mas foi Deus quem deu o crescimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'De maneira que nem o que planta é algo, nem o que rega; mas sim Deus, que dá o crescimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'E o que planta, e o que rega, são um; mas cada um receberá a sua recompensa segundo o seu trabalho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Porque somos cooperadores de Deus; vós sois a plantação de Deus, o edifício de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Segundo a graça de Deus que me foi dada, eu pus como sábio construtor o fundamento; e outro edifica sobre ele; mas olhe cada um como constrói sobre ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Porque ninguém pode pôr fundamento diferente do que já está posto, o qual é Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'E se alguém sobre este fundamento edificar ouro, prata, pedras preciosas, madeira, feno, palha,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'a obra de cada um se manifestará; porque o dia a esclarecerá; pois pelo fogo se descobre; e qual é a obra de cada um, o fogo fará a prova.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Se a obra de alguém que construiu sobre ele permanecer, receberá recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Se a obra de alguém se queimar, o construtor sofrerá perda; porém o tal se salvará, contudo, como que passado pelo fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Não sabeis vós, que sois o templo de Deus? E que o Espírito de Deus habita em vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Se alguém destruir o templo de Deus, Deus ao tal destruirá; porque o templo de Deus é santo, o qual sois vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Ninguém se engane; se alguém entre vós nestes tempos pensa ser sábio, que se faça de louco, para que seja sábio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Pois a sabedoria deste mundo é loucura para Deus; porque está escrito: Ele toma aos sábios pela sua própria astúcia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'E outra vez: O Senhor conhece os pensamentos dos sábios, que são vãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Portanto ninguém se orgulhe em seres humanos; porque tudo é vosso,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'seja Paulo, seja Apolo, seja Cefas, seja o mundo, seja a vida, seja a morte, seja o presente, seja o futuro; tudo é vosso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Mas vós sois de Cristo; e Cristo, de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Que as pessoas nos reconheçam como servidores de Cristo, e guardiões dos mistérios de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'E além disso, exige-se dos guardiões que cada um seja fiel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mas a mim, pouco me importa de ser julgado por vós, ou por qualquer juízo humano; nem eu julgo a mim mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Porque em nada me sinto culpável; mas nem por isso estou justificado; porém o que me julga é o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Então nada julgueis antes do tempo, até que o Senhor venha, o qual também trará à luz as coisas ocultas nas trevas, e manifestará as intenções dos corações; e então cada um receberá aprovação de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'E isto, irmãos, fiz a comparação relativa a mim e a Apolo por causa de vós; para que em nós aprendais a não fazer suposições além do que está escrito; para que não fiqueis arrogantes por preferir um contra o outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Pois quem te faz diferentemente superior? E o que tens tu, que não tenhas recebido? E se o recebeste, por que te orgulhas, como se não o tivesse recebido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Vós já estais satisfeitos, já estais ricos, e reinastes sem nós; e bom seria se vós reinásseis, para que também nós reinássemos convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Pois acho que Deus colocou a nós, os apóstolos, por último, como sentenciados à morte; pois somos como espetáculo ao mundo, tanto aos anjos como aos seres humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Nós somos loucos por causa de Cristo, mas vós sábios em Cristo; nós fracos, mas vós fortes; vós ilustres, mas nós desonrados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Até esta presente hora sofremos fome e sede, e estamos nus, e somos golpeados, e não temos morada certa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'E ficamos exaustos, trabalhando com as nossas próprias mãos; somos insultados, e bendizemos; somos perseguidos, e nós suportamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Somos blasfemados, e respondemos humildemente; somos feitos como a escória do mundo, e como o lixo de todos, até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Não escrevo estas coisas para vos envergonhar; mas sim, para vos advertir como a meus amados filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Porque ainda que tivésseis dez mil tutores em Cristo, contudo não tendes muitos pais. Porque eu tornei vosso pai em Cristo Jesus por meio do Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Portanto eu vos chamo para que sejais meus imitadores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Por isso eu vos enviei Timóteo, que é meu amado e fiel filho no Senhor; ele vos lembrará dos meus caminhos em Cristo, como por todos os lugares ensino em cada igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Mas alguns andam arrogantes, como se eu não fosse até vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Porém logo irei vos visitar, se o Senhor quiser; e então conhecerei, não as palavras dos que andam arrogantes, mas sim o poder deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Porque o Reino de Deus não consiste de palavras, mas sim de poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Que quereis? Que eu venha até vós com a vara da disciplina, ou com amor e espírito de mansidão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Totalmente se ouve que há entre vós pecados sexuais, e tais pecados sexuais que nem mesmo entre os gentios se nomeia, como alguém que tomou como mulher a esposa de seu pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'E vós estais orgulhosos! Ao invés disso, vós não deveríeis se entristecer, para que fosse tirado do meio de vós o que cometeu esta atitude?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Porque eu, agindo como ausente de corpo, porém presente de espírito, já julguei como se estivesse presente, aquele que fez isto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'No nome do nosso Senhor Jesus Cristo, quando vós vos reunirdes, e o meu espírito junto de vós, com o poder de nosso Senhor Jesus Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'De ao tal entregar a Satanás, para destruição da carne, para que o espírito seja salvo, no dia do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Vosso orgulho não é bom. Não sabeis que um pouco de fermento faz levedar toda a massa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Limpai pois o velho fermento, para que sejais nova massa, assim como vós sois de fato sem fermento. Porque Cristo, nosso cordeiro da páscoa, foi sacrificado por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Portanto façamos festa, não no velho fermento, nem no fermento do mal e da perversão, mas em pães não levedados de sinceridade e de verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Eu já vos escrevi por carta, que não vos mistureis com pecadores sexuais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Porém não totalmente com os pecadores deste mundo, ou com os gananciosos, ou ladrões, ou com os idólatras; porque então vos seria necessário sair do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Mas agora vos escrevo, que não vos mistureis se alguém, chamando a si de irmão, for pecador sexual, ou ganancioso, ou idólatra, ou maldizente, ou beberrão, ou ladrão. Com o tal nem mesmo comais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Por que eu tenho que julgar também aos que estão de fora? Não julgais vós aos que estão de dentro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Mas Deus julga aos que estão de fora. Tirai pois dentre vós a este maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Algum de vós, tendo um assunto contra outro, ousa ir a juízo perante os injustos, e não perante os santos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Não sabeis que os santos julgarão ao mundo? E se o mundo é julgado por vós, por acaso sois vós indignos de julgar as coisas mínimas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Não sabeis que julgaremos aos anjos? Quanto mais as coisas desta vida!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Pois se tiverdes assuntos em juízo, relativos a coisas desta vida, vós pondes como juízes aos que são menos estimados pela igreja?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Eu digo isto para vos envergonhar. Não há entre vós algum sábio, nem pelo menos um, que não possa julgar entre seus irmãos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Mas irmão vai a juízo contra outro irmão, e isto perante incrédulos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Porém já é uma falta entre vós, por entre vós haverdes disputas. Por que não aceitais serdes injustiçados? Por que não aceitais o prejuízo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Mas vós mesmos injustiçais e prejudicais, e isto aos irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Ou não sabeis que os injustos não herdarão o Reino de Deus? Não erreis: nem os pecadores sexuais, nem os idólatras, nem os adúlteros, nem os sexualmente efeminados, nem os homens que fazem sexo com homens,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Nem os ladrões, nem os gananciosos, nem os beberrões, nem os maldizentes, nem os extorsores herdarão o Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'E isto alguns de vós éreis. Mas já estais lavados, e santificados, e justificados no nome do Senhor Jesus, e pelo Espírito de nosso Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Todas as coisas me são lícitas, mas nem todas as coisas convêm; todas as coisas me são lícitas, porém eu não deixarei me sujeitar por coisa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'A comida é para o estômago, e o estômago é para a comida; mas Deus os aniquilará, tanto a um, como ao outro. Porém o corpo não é para o pecado sexual, mas para o Senhor, e o Senhor é para o corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'E Deus ressuscitou ao Senhor, e também por seu poder nos ressuscitará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Não sabeis vós que vossos corpos são membros de Cristo? Tomarei pois os membros de Cristo, e os farei membros de uma prostituta? De maneira nenhuma!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Ou não sabeis que o que se junta sexualmente com uma prostituta se torna um só corpo com ela? Porque a Escritura diz: Os dois serão uma só carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Mas o que se junta com o Senhor, com ele se torna um só espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fugi do pecado sexual. Todo pecado que o ser humano comete é fora do corpo; mas o que pratica pecado sexual, peca contra seu próprio corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Ou não sabeis que vosso corpo é templo do Espírito Santo, o qual está em vós, o qual tendes de Deus, e que não sois de vós mesmos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Porque vós fostes comprados por alto preço; então glorificai a Deus em vosso corpo, e em vosso espírito, que são de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'E sobre as coisas que me escrevestes, bom é para o homem não tocar mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Mas por causa dos pecados sexuais, tenha cada um sua própria mulher, e cada uma tenha seu próprio marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Que o marido satisfaça sua mulher como devido, e semelhantemente a mulher ao marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'A mulher não tem poder sobre seu próprio corpo, mas sim o marido; e também da mesma maneira o marido não tem poder sobre seu próprio corpo, mas sim a mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Não vos priveis um ao outro, a não ser por consentimento de ambos por algum tempo, para que vos ocupeis com jejum, e para a oração; e voltai-vos outra vez a se juntarem, para que Satanás não vos tente, por causa de vossa falta de domínio próprio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Mas isto vos digo como permissão, não como mandamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Porque eu queria que todos fossem como eu mesmo; mas cada um tem seu próprio dom de Deus, um de um jeito assim, e outro de um jeito diferente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Mas digo aos solteiros, e às viúvas que lhes é bom se permanecessem como eu estou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Mas se não podem se conter, casem-se; porque é melhor se casar do que se inflamar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Porém aos casados eu mando, não eu, mas o Senhor, que a mulher não se separe do marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'E se se separar, fique sem casar, ou se reconcilie com o marido; e que o marido não deixe a mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Mas aos outros digo eu, não o Senhor: se algum irmão tem mulher descrente, e ela consente em habitar com ele, não a deixe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'E se alguma mulher tem marido descrente, e ele consente em habitar com ela, não o deixe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Porque o marido descrente é santificado pela mulher; e a mulher descrente é santificada pelo marido. Pois de outra maneira vossos filhos seriam impuros; porém agora são santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Mas se o descrente se separar, separe-se também. Em tal situação o irmão ou a irmã não estão sujeitos à servidão; mas Deus nos chamou para a paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Porque o que tu sabes, mulher, se salvarás ao marido? Ou o que tu sabes, marido, se salvarás a mulher?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Porém cada um ande assim como Deus lhe repartiu, cada um como o Senhor o chamou; e assim ordeno em todas as igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'É alguém chamado, estando já circunciso? Não desfaça a circuncisão. É alguém chamado estando ainda incircunciso? Não se circuncide.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'A circuncisão nada vale, e a incircuncisão nada vale; mas o que vale é a obediência aos mandamentos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Cada um fique no propósito em que foi chamado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Foste tu chamado sendo escravo? Não te preocupes com isto; mas se tu podes te tornares livre, aproveita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Porque o que foi chamado no Senhor enquanto era escravo, para o Senhor é livre; da mesma maneira também, o que foi chamado, sendo livre, se torna escravo de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vós fostes comprados por alto preço; portanto não vos façais escravos dos seres humanos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Irmãos, cada um continue com Deus no estado em que foi chamado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'E quanto às virgens, não tenho mandamento do Senhor; porém eu dou minha opinião, dado que tenho recebido misericórdia do Senhor para que eu seja confiável.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Considero pois isto como bom, por causa da necessidade atual, que é bom à pessoa continuar assim como está.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Estás ligado à mulher, não busques se separar. Estás livre de mulher, não busques mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Mas se também te casares, não pecas; e se a virgem se casar, não peca. Porém os tais terão aflições na carne, que eu gostaria de livrá-los.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Porém digo isto, irmãos, porque o tempo que resta é breve; para que também os que tem mulheres, sejam como se não as tivessem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'E os que choram, como se não chorassem; e os que se alegram, como se não se alegrassem; e os que compram, como se não possuíssem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'E os que usam das coisas deste mundo, como se delas não abusassem; porque a aparência deste mundo é passageira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'E eu queria que estivésseis sem preocupações. O solteiro se preocupa com as coisas do Senhor, como irá agradar ao Senhor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Porém o que é casado se preocupa com as coisas do mundo, como irá agradar à mulher.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'A mulher casada e a virgem são diferentes: a que está para casar tem preocupação com as coisas do Senhor, para ser santa, tanto de corpo como de Espírito; mas a casada tem preocupação com as coisas do mundo, como irá agradar ao marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Porém digo isto para vosso próprio proveito; não para vos enlaçar, mas para vos guiar ao que é decente, e servirem ao Senhor sem distração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Mas se alguém lhe parece que indecentemente trata com sua virgem, se ela passar da idade da juventude, e assim convier se fazer, que tal faça o que quiser, não peca, casem-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Porém o que está firme em seu coração, não tendo necessidade, mas tem poder sobre sua própria vontade, e isto decidiu em seu próprio coração, de guardar sua virgem, faz bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Portanto, o que a dá em casamento, faz bem; mas o que não a dá em casamento, faz melhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'A mulher casada está ligada pela Lei todo o tempo em que seu marido vive; mas se seu marido morrer, fica livre para se casar com quem quiser, contanto que seja no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Porém mais bem-aventurada é, se assim continuar, segundo minha opinião. E também eu penso, que tenho o Espírito de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'E quanto às coisas sacrificadas aos ídolos, sabemos que todos temos conhecimento. O conhecimento incha de orgulho,mas o amor edifica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'E se alguém acha saber alguma coisa, ainda nada conhece como se deve conhecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Mas se alguém ama a Deus, o tal dele é conhecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Portanto, quanto ao comer das coisas sacrificadas aos ídolos: sabemos que o ídolo nada é no mundo, e que não há qualquer outro Deus, a não ser um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Porque, ainda que também haja alguns que se chamem deuses, seja no céu, seja na terra (como há muitos deuses e muitos senhores),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Todavia para nós há só um Deus, o Pai, do qual são todas as coisas, e nós para ele; e um só Senhor Jesus Cristo, pelo qual são todas as coisas, e nós por ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Mas não há em todos este conhecimento; porém alguns até agora comem com consciência do ídolo, como se fossem sacrificadas aos ídolos; e sendo sua consciência fraca, fica contaminada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Ora, a comida não nos faz agradáveis a Deus. Porque seja o que comamos, nada temos de mais; e seja o que não comamos, nada nos falta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Mas tomai cuidado para que esta vossa liberdade não seja de maneira alguma escândalo para os fracos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Porque se alguém vir a ti, que tens este conhecimento, sentado à mesa no templo dos ídolos, não será a consciência do que é fraco induzida a comer das coisas sacrificadas aos ídolos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'E por causa de teu conhecimento, perecerá assim o irmão fraco, pelo qual Cristo morreu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Assim que, pecando contra os irmãos e ferindo sua fraca consciência, pecais contra Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Portanto, se a comida escandalizar a meu irmão, nunca mais comerei carne, para que eu não escandalize a meu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Não sou eu apóstolo? Não sou livre? Não vi eu a Jesus Cristo nosso Senhor? Não sois vós minha obra no Senhor?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Se para os outros não sou apóstolo, ao menos para vós eu o sou; porque vós sois o selo de meu apostolado no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Esta é a minha defesa para com os que me condenam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Não temos nós poder de comer e de beber?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Não temos nós direito de trazer conosco uma mulher irmã, como também os demais apóstolos, e os irmãos do Senhor, e Cefas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Ou só eu, e Barnabé, não temos direito de não trabalhar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Quem vai para a guerra a seu próprio custo? Quem planta a vinha, e não come do seu fruto? Ou quem apascenta o gado, e não come do leite do gado?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Digo eu isto segundo a lógica humana? Ou não diz a Lei também o mesmo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Porque na Lei de Moisés está escrito: ao boi que trilha não atarás a boca. Por acaso Deus tem preocupação com os bois?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Ou totalmente diz por nós? Porque por nós isto está escrito; porque o que lavra, com esperança deve lavrar; e o que trilha com esperança, de sua esperança deve ser participante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Se nós vos semeamos as coisas espirituais, é muito que ceifemos as vossas coisas carnais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Se outros são participantes deste poder sobre vós, porque não tanto mais nós? Mas nós não usamos deste poder; antes tudo suportamos, para não darmos impedimento algum ao Evangelho de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Não sabeis vós, que os que administram as coisas sagradas, comem daquilo que é sagrado? E os que continuamente estão junto ao altar, com o altar participam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Assim também ordenou o Senhor, aos que anunciam o Evangelho, que vivam do Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Porém eu de nenhuma destas coisas usei; e nem isto escrevi, para que assim se faça comigo; porque melhor me seria morrer, do que esvaecer este meu orgulho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Porque se anunciar o Evangelho, para mim não é orgulho, pois a obrigação me é imposta. E ai de mim, se não anunciar o Evangelho!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Porque se eu faço de boa mente, tenho recompensa; mas se eu fizer de má vontade, a responsabilidade me é confiada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Então que recompensa tenho? Que evangelizando, proponha o Evangelho de Cristo sem receber nada de volta, para não abusar do meu poder no Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Porque, estando eu livre de todos, me fiz servo de todos, para ganhar ainda mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'E me fiz como judeu para os judeus, para ganhar aos judeus; como que estivesse debaixo da Lei, para os que estão debaixo da Lei, para ganhar aos que estão debaixo da Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Ao que estão sem Lei, como se estivesse sem Lei (porém não estando sem Lei para com Deus; mas para com Cristo debaixo da Lei), para ganhar os que estão sem Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Me fiz de fraco para os fracos, para ganhar aos fracos; tudo me fiz para todos, para por todos os meios vir a salvar a alguns.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'E isto eu faço por causa do Evangelho, para que eu também dele seja participante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Não sabeis vós que os que correm nas competições, realmente todos correm, mas somente um leva o prêmio? Correi de tal maneira, que o alcanceis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'E todo aquele que luta, tenha domínio próprio sobre tudo. Pois aqueles fazem para receber uma coroa corruptível, porém nós para uma incorruptível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Então assim eu corro, não como para um lugar incerto; assim luto, não como que dando socos no ar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Em vez disso, eu subjugo meu corpo, e o reduzo à servidão, para que quando estiver pregando para os outros, eu mesmo não seja reprovado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Ora, irmãos, eu não quero que ignoreis que todos os nossos pais estiveram debaixo da nuvem, e todos pelo mar passaram;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'E todos foram batizados na nuvem e no mar em Moisés;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'E todos comeram de um mesmo alimento espiritual;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'E todos beberam de uma mesma bebida espiritual; porque bebiam da pedra espiritual que os seguia; e a pedra era Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Mas da maioria deles Deus não se agradou; por isso foram deixados no deserto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'E estas coisas nos servem de exemplos, para que não desejemos coisas ruins, como eles desejaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'E não sejais idólatras, como alguns deles foram,como está escrito: O povo se sentou para comer, e para beber, e levantaram-se para se alegrarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'E não pequemos sexualmente, como alguns deles assim pecaram, e em um dia vinte e três mil caíram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'E não tentemos a Cristo, como também alguns deles tentaram, e pereceram pelas serpentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'E não murmureis, como também alguns deles murmuraram, e pereceram pelo destruidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'E todas estas coisas lhes aconteceram como exemplos, e estão escritas para nosso aviso, em quem os fins dos tempos têm chegado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Portanto, aquele que pensa estar de pé, olhe para que não caia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nenhuma tentação vos veio, que não fosse humana; porém Deus é fiel; que não vos deixará tentar mais do que o que podeis, antes com a tentação também dará a saída, para que a possais suportar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Portanto, meus amados, fugi da idolatria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Eu vos falo como que para prudentes; jugai vós mesmos o que eu digo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Por acaso o copo da bênção, que nós bendizemos, não é a comunhão do sangue de Cristo? O pão que partimos, não é a comunhão do corpo de Cristo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Porque assim como há um só pão, nós muitos somos um só corpo; porque todos participamos de um só pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Vede a Israel segundo a carne: por acaso os que comem os sacrifícios não são participantes do altar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Então o que eu digo? Que o ídolo é alguma coisa? Ou que o sacrifício ao ídolo seja alguma coisa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Mas eu digo, que as coisas que os gentios sacrificam, são sacrificadas para os demônios, e não a Deus. E não quero que sejais participantes dos demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Não podeis beber o copo do Senhor e o copo dos demônios; não podeis ser participantes da mesa do Senhor e da mesa dos demônios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Tentamos provocar ciúmes ao Senhor? Somos nós mais fortes que ele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Todas as coisas me são lícitas, mas nem todas as coisas convêm; todas as coisas me são licitas, mas nem todas as coisas edificam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Ninguém busque para si próprio, antes cada um busque o bem do outro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'De tudo o que se vende no açougue, comei, sem vos questionar por causa da consciência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Porque a terra é do Senhor, e também sua plenitude.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'E se alguém dos descrentes vos convidar, e quiserdes ir, comei de tudo o que for posto diante de vós, sem vos questionar por causa da consciência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Mas se alguém vos disser: “Isto é sacrifício a ídolos”, não comais, por causa daquele que vos advertiu, e por causa da consciência. Porque a terra e sua plenitude pertencem ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Mas digo da consciência do outro, não a tua. Por que, então, minha liberdade é julgada pela consciência do outro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'E se eu participo da comida pela graça, por que sou ofendido naquilo que dou graças?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Portanto, ao comer, ou ao beber, ou ao fazer qualquer coisa, fazei tudo para a glória de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Sede sem escândalo, nem a judeus, nem a gregos, nem à Igreja de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Assim como eu também agrado a todos em tudo, não buscando meu próprio proveito, mas sim o de muitos, para que assim possam se salvar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Sede meus imitadores, assim como eu também sou de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Eu vos louvo, irmãos, de que em tudo vos lembrais de mim, e retendes minhas ordens, assim como eu vos entreguei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Mas quero que saibais, que a cabeça de todo homem é Cristo; e a cabeça da mulher é o homem; e a cabeça de Cristo é Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Todo homem que ora ou profetiza, tendo alguma coisa sobre a cabeça, desonra sua própria cabeça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Mas toda mulher que ora ou profetiza com a cabeça descoberta, desonra sua própria cabeça; porque é o mesmo que se a tivesse raspada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Porque se a mulher não se cobre, raspe-se também; mas se para a mulher é vergonhoso se cortar ou se raspar, que se cubra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Porque o homem não deve cobrir a cabeça, pois é a imagem e a glória de Deus; mas a mulher é a glória do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Porque o homem não provem da mulher, mas sim a mulher do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Porque também o homem não foi criado por causa da mulher, mas a mulher foi criada por causa do homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Portanto a mulher deve ter sobre a cabeça sinal de autoridade, por causa dos anjos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Porém, nem o homem é sem a mulher, nem a mulher sem o homem, no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Porque assim como a mulher vem do homem, assim também é o homem pela mulher; porém tudo vem de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Julgai-vos entre vós mesmos: é decente que a mulher ore a Deus descoberta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Ou não vos ensina a mesma natureza, que ter cabelo longo é desonra para o homem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Mas a mulher ter cabelo longo, lhe é honra, porque os cabelos lhe são dados por cobertura?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Porém se alguém parece ser inclinado a disputas, nós não temos tal costume, nem as igrejas de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Mas isto eu vos declaro, que não vos louvo, porque vós vos ajuntais, não para melhor, mas para pior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Porque, em primeiro lugar, eu ouço que, quando vos ajuntais, há divisões entre vós; e em parte eu acredito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Porque é necessário que haja diferenças de opinião entre vós, para que os que são aprovados sejam evidenciados entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Quando, pois, vós vos reunis, não é para comer da ceia do Senhor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Porque cada um, comendo antes, toma sua própria ceia; e um fica com fome, e outro fica bêbado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Por acaso não tendes casas para comer e para beber? Ou desprezais a Igreja de Deus, e envergonhais os que não têm? Que vos direi? Eu vos elogiarei? Nisto eu não vos elogio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Porque eu recebi do Senhor o que também vos entreguei; que o Senhor Jesus, na noite em que foi traído, tomou o pão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'E tendo dado graças, o partiu, e disse: Tomai, comei; isto é o meu corpo, que é partido por vós; fazei isto em memória de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Semelhantemente também, depois de cear, tomou o copo, dizendo: Este copo é o novo Testamento em meu sangue. Fazei isto todas as vezes que o beberdes, em memória de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Porque todas as vezes que comerdes deste pão, e beberdes deste copo, anunciai a morte do Senhor, até que ele venha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Portanto quem comer deste pão, ou beber deste copo do Senhor indignamente, será culpado do corpo e do sangue do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Portanto examine-se cada um a si mesmo, e assim coma deste pão, e beba deste copo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Porque quem come e bebe indignamente, para si mesmo come e bebe condenação, não discernindo o corpo do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Por esta causa há entre vós muitos fracos e doentes, e muitos que dormem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Porque se nós julgássemos a nós mesmos, não seríamos julgados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Mas quando somos julgados, somos repreendidos pelo Senhor; para que não sejamos condenados com o mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Portanto, meus irmãos, quando vos ajuntardes para comer, esperai uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Porém se alguém tiver fome, coma em casa; para que não vos ajunteis para sofrerdes julgamento. Quanto às demais coisas, as ordenarei quando vier.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'E quanto aos dons espirituais, irmãos, não quero que sejais ignorantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vós sabeis que éreis gentios, vós vos desviáveis para os ídolos mudos, conforme éreis guiados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Por isso eu vos deixo claro que ninguém que fala pelo Espírito de Deus chama a Jesus de maldito; e ninguém pode dizer que Jesus é o Senhor, a não ser pelo Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'E há variedade de dons, mas o Espírito é o mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'E há variedade de trabalhos na Igreja,mas o Senhor é o mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'E há variedade de operações, mas é o mesmo Deus que opera tudo em todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Mas a cada um é dada a manifestação do Espírito, para o que for conveniente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Porque a um é dada, pelo Espírito, palavra de sabedoria; e a outro palavra de conhecimento, pelo mesmo Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'e a outro fé pelo mesmo Espírito; e a outro dons de curas, pelo mesmo Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'E a outro operações de milagres; e a outro profecia; e a outro o dom de discernir aos espíritos; e a outro variedade de línguas; e a outro interpretação de línguas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Mas todas estas coisas quem opera é um e o mesmo Espírito, repartindo particularmente a cada um como quer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Porque assim como o corpo é um, e tem muitos membros, e todos os membros deste único corpo, sendo muitos, compõem um só corpo; assim também é Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Porque também todos nós somos batizados em um só Espírito, para um só corpo, quer judeus, quer gregos, quer servos, quer livres; e para todos nós foi dado de beber um só Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Porque também o corpo não é um só membro, mas muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Se o pé disser: Por eu não ser mão, não sou do corpo;Por isso, ele não é do corpo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'E se a orelha disser: Por eu não ser olho, não sou do corpo;Por isso, ela não é do corpo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Se todo o corpo fosse olho, onde estaria o ouvido? Se fosse todo ouvido, onde estaria o olfato?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mas agora Deus pôs os membros no corpo, a cada qual deles como ele quis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Porque se todos fossem um só membro, onde estaria o corpo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Mas há agora muitos membros, porém um só corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'E o olho não pode dizer à mão: Não tenho necessidade de ti;Nem a cabeça aos pés: Não tenho necessidade de vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Antes até os membros do corpo que nos parecem ser os mais fracos, são muito mais necessários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'E os que pensamos serem os menos honrados do corpo, a esses muito mais honramos; e os nossos mais desprezíveis têm muito mais respeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Porém os nosso mais respeitáveis não têm tanta necessidade; mas assim Deus juntou o corpo, dando muito mais honra ao que tinha falta dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Para que não haja divisão no corpo, mas que os membros tenham igual cuidado uns com os outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'E seja que, caso um membro sofra, também os membros sofrem juntos; e caso um membro seja honrado, todos os membros se alegram juntos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'E vós sois o corpo de Cristo, e membros em particular.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'E Deus pôs a uns na Igreja: em primeiro lugar apóstolos, em segundo profetas, em terceiro mestres; depois milagres, dons de curas, socorros, lideranças, variedades de línguas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Por acaso são todos apóstolos? São todos profetas? São todos mestres? São todos com dons de milagres?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Tem todos dons de curas? Falam todos várias línguas? Interpretam todos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Porém desejai com zelo pelos melhores dons; e eu vos mostro um caminho ainda mais excelente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Ainda que eu falasse as línguas dos seres humanos e dos anjos, e não tivesse amor, seria como o metal que soa, ou como o sino que retine.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'E ainda que tivesse o dom de profecia, e soubesse todos os mistérios, e todo o conhecimento; e ainda que tivesse toda a fé, de tal maneira que movesse os montes de lugar, e não tivesse amor, nada seria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'E ainda que eu distribuísse todos os meus bens para alimentar aos pobres, e ainda que entregasse meu corpo para ser queimado, e não tivesse amor, nada me aproveitaria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'O amor é paciente, é bondoso; o amor não é invejoso; o amor não é orgulhoso, não é arrogante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'O amor não trata mal; não busca os próprios interesses, não se ira, não é rancoroso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Não se alegra com a injustiça, mas se alegra com a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Tudo aguenta, tudo crê, tudo espera, tudo suporta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'O amor nunca falha. Porém as profecias serão aniquiladas; as línguas acabarão, e o conhecimento será aniquilado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Porque em parte conhecemos, e em parte profetizamos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Mas quando vier o que é completo, Ou: perfeito então o que é em parte será aniquilado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Quando eu era menino, falava como menino, sentia como menino, pensava como menino; mas quando me tornei homem, aniquilei as coisas de menino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Porque agora vemos por espelho em enigma, mas então veremos face a face; agora conheço em parte, mas então conhecerei assim como sou conhecido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'E agora continuam a fé, a esperança, e o amor, estes três; porém o maior destes é o amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Segui o amor, e desejai com zelo pelos dons espirituais; porém principalmente que profetizeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Porque o que fala língua estranha,não fala aos seres humanos, mas sim a Deus; porque ninguém o entende, mas em espírito fala mistérios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Mas o que profetiza, fala aos seres humanos para edificação, convencimento, e consolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'O que fala língua estranha edifica a si mesmo; mas o que profetiza edifica à igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'E eu quero que todos vós faleis línguas, porém mais ainda que profetizeis; porque o que profetiza é maior que o que fala línguas, a não ser que também interprete, para que a igreja receba edificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'E agora irmãos, se eu viesse até vos falando línguas, o que vos aproveitaria, se não vos falasse ou por revelação, ou por conhecimento, ou por profecia, ou por doutrina?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'E até as coisas inanimadas, que produzem som, seja flauta, seja harpa, se não derem distinção de sons, como saberá o que se toca com a flauta, ou com a harpa?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Porque também se a trombeta der som incerto, quem se preparará para a guerra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Assim mesmo também vós, se com a língua não derdes palavra compreensível, como se entenderá o que se diz? Porque estareis falando para o ar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Por exemplo, há tantos tipos de vozes no mundo, e nenhuma delas é muda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Portanto, se eu não souber o propósito da voz, serei estrangeiro para o que fala, e o que fala será estrangeiro para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Assim também vós, dado que desejais os dons espirituais, procurai neles abundar, para edificação da igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Portanto, o que fala em língua estranha,ore para que possa interpretar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Porque se eu orar em língua estranha,meu espírito ora, mas meu entendimento fica sem fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Então é o que? Orarei com o espírito, mas também orarei com o entendimento; cantarei com o espírito, mas também cantarei com o entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'De outra maneira, se tu bendisseres com o espírito, como aquele que não tem conhecimento dirá amém por teu bendizer? Pois ele não sabe o que tu dizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Porque em verdade tu bem dás graças; mas o outro não é edificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Graças dou a meu Deus, que mais línguas falo que todos vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Porém eu quero mais falar na igreja cinco palavras com meu entendimento, para que eu também possa instruir aos outros, do que dez mil palavras em língua estranha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Irmãos, não sejais meninos no entendimento, mas sede meninos na malícia, e adultos no entendimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Na Lei está escrito: A este povo falarei por gente de outras línguas, e por outros lábios; e ainda assim não me ouvirão, diz o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Então as línguas estranhas são por sinal, não para os que creem, mas para os que não creem; e a profecia não é para os que não creem, mas para os que creem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Pois se toda a igreja se reunir, e todos falarem línguas estranhas, e entrarem alguns sem entendimento ou descrentes, não dirão que estais loucos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Mas se todos profetizarem, e algum sem entendimento ou descrente entrar, por todos é convencido, e por todos é julgado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'E assim os segredos de seu coração ficam manifestos, e assim, lançando-se sobre seu rosto, adorará a Deus, reconhecendo publicamente que Deus está entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Então o que há, irmãos? Quando vos reunis, tem cada um de vós salmo, tem doutrina, tem língua estranha,tem revelação, tem interpretação, tudo se faça para edificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'E se alguém falar em língua estranha, sejam dois, ou no máximo três, e alternando-se, e um que interprete.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Mas se não houver intérprete, cale-se na igreja, fale porém consigo mesmo, e com Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'E falem dois ou três profetas, e os outros julguem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Mas se a outro, que estiver sentada, for revelada alguma coisa, cale-se o primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Porque todos vós podeis profetizar, um após o outro, para que todos aprendam, e sejam todos fortalecidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'E os espíritos dos profetas estão sujeitos aos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Porque Deus não é de confusão, mas de paz, como em todas as igrejas dos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Vossas mulheres fiquem caladas nas igrejas; porque não lhes é permitido falar, mas que estejam sujeitas, como também a Lei o diz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'E se quiserem aprender alguma coisa, perguntem a seus próprios maridos em casa; porque é impróprio as mulheres falarem na igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Por acaso a palavra de Deus saiu de vós? Ou ela somente chegou a vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Se alguém pensa ser profeta, ou espiritual, reconheça que as coisas que escrevo são mandamento do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Porém se alguém ignora, que ignore.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Portanto, irmãos, desejai com zelo profetizar, e não impeçais o falar línguas estranhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Fazei tudo decentemente e com ordem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Também irmãos, eu vos declaro o Evangelho, que já vos tenho anunciado, o qual também recebestes, no qual também estais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Pelo qual também sois salvos, se retiverdes a palavra naquela maneira, em que eu vos tenho anunciado; a não ser se tenhais crido em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Porque primeiramente vos entreguei o que também recebi, que Cristo morreu por nossos pecados, segundo as Escrituras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'E que foi sepultado, e que ressuscitou ao terceiro dia, segundo as Escrituras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'E que foi visto por Cefas, depois pelos doze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Depois foi visto de uma fez por mais de quinhentos irmãos, dos quais a maioria ainda vive, e também alguns já dormem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Depois foi visto por Tiago; depois por todos os apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'E por último de todos também foi visto por mim, como que a um nascido fora do tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Porque eu sou o menor dos apóstolos, que não sou digno de ser chamado apóstolo, porque persegui a Igreja de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Mas pela graça de Deus sou o que sou; e sua graça concedida a mim não foi vã; ao invés disso trabalhei muito mais que todos eles; porém não eu, mas a graça de Deus que está comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Portanto, seja eu, sejam eles, assim pregamos, e assim crestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'E se é pregado que Cristo ressuscitou dos mortos, como dizem alguns dentre vós, que não há ressurreição dos mortos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'E se não há ressurreição dos mortos, então Cristo não ressuscitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'E se Cristo não ressuscitou, então é vã nossa pregação, e vã também é vossa fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'E assim também somos encontrados como falsas testemunhas de Deus; pois testemunhamos de Deus, que ressuscitou a Cristo, ao qual porém não ressuscitou, se na verdade os mortos não ressuscitam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Porque se os mortos não ressuscitam, então Cristo também não ressuscitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'E se Cristo não ressuscitou, vossa fé é vá, e ainda estais em vossos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Portanto também pereceram os que dormiram em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Se nesta vida esperamos somente em Cristo, somos os mais miseráveis de todas as pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Mas de fato Cristo ressuscitou dos mortos, e foi feito as primícias dos que dormiram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Pois dado que a morte veio por um homem, também por um homem veio a ressurreição dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Porque assim como em Adão todos morrem, assim também em Cristo todos serão vivificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Mas cada um em sua ordem; Cristo, as primícias; depois os que são de Cristo, em sua vinda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Depois será o fim, quando entregar o Reino de Deus e ao Pai, quando aniquilar todo domínio, e toda autoridade e poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Porque convém que ele reine, até que tenha posto todos os inimigos debaixo de seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'O último inimigo, que será aniquilado, é a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Porque ele sujeitou todas as coisas debaixo de seus pés. Porém quando diz que todas as coisas lhe estão sujeitas, está claro que se excetua aquele que todas as coisas lhe sujeitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'E quando todas as coisas lhe forem sujeitas, então também o mesmo Filho se sujeitará a aquele, que todas as coisas lhe sujeitou, para que Deus seja tudo em todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'De outra maneira, que farão os que se batizam pelos mortos, se totalmente os mortos não ressuscitam? Por que, então, se batizam pelos mortos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Por que também nós à toda hora estamos em perigo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'A cada dia eu morro pelo orgulho que tenho por vós, em Cristo Jesus nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Se por motivo humano lutei contra feras em Éfeso, qual é o meu proveito? Se os mortos não ressuscitam, comamos e bebamos, que amanhã morreremos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Não erreis. As más companhias corrompem os bons costumes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Despertai para a justiça, e não pequeis; porque alguns ainda não têm o conhecimento de Deus. Eu digo isto para vossa vergonha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mas alguém dirá: Como ressuscitarão os mortos? E com que corpo virão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Louco, o que tu semeias não é vivificado, se primeiro não morrer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'E o que semeias, não semeias o corpo que irá brotar, mas o grão nu, como o de trigo, ou de qualquer outro grão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Mas Deus lhe dá o corpo como quer, e a cada semente seu próprio corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Toda carne não é a mesma carne; mas uma é a carne humana, e outra a carne dos animais, e outra a dos peixes, e outra a das aves.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'E há corpos celestiais, e corpos terrestres; mas uma é a glória dos celestiais, e outra a dos terrestres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Outra é a glória do Sol, e outra a glória da Lua, e outra a glória das estrelas; porque uma estrela difere em glória de outra estrela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Assim também será a ressurreição dos mortos. Semeia-se o corpo em corrupção, ressuscitará em incorrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Semeia-se em desonra, ressuscitará em glória. Semeia-se em fraqueza, ressuscitará em força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Semeia-se corpo natural, ressuscitará corpo espiritual. Há corpo animal, e há corpo espiritual.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Assim também está escrito: O primeiro homem, Adão, foi feito em alma vivente;O último Adão em espírito vivificante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Mas não é primeiro o espiritual; mas sim o carnal, depois o espiritual.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'O primeiro homem da terra é terrestre; o segundo homem, que é o Senhor, é do Céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Assim como é o terrestre, também são os terrestres; e assim como é o celestial, também são os celestiais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'E assim como trouxemos a imagem do terrestre, assim também traremos a imagem do celestial.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Porém isto digo, irmãos, que a carne e o sangue não podem herdar o Reino de Deus, nem a corrupção herda a incorrupção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'eis que eu vos digo um mistério: nem todos em verdade dormiremos; porém todos seremos transformados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Em um momento, em um piscar de olhos, à ultima trombeta; porque a trombeta soará, e os mortos ressuscitarão incorruptíveis, e nós seremos transformados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Porque é necessário que este corpo corruptível vista a incorrupção, e este corpo mortal vista a imortalidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'E quando este corpo se vestir de incorrupção, e este corpo mortal se vestir de imortalidade, então se cumprirá a palavra que está escrita: Na vitória, a morte é tragada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Onde está, ó morte, o teu aguilhão? Onde está, ó mundo dos mortos, a tua vitória?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'O aguilhão da morte é o pecado, e a força do pecado é a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Mas graças a Deus, que nos dá vitória por meio do nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Portanto, meus amados irmãos, sede firmes, imóveis e sempre abundantes na obra do Senhor, sabendo que o vosso trabalho não é vão no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'E quanto à coleta que se faz para os santos, fazei também como ordenei às igrejas da Galácia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Cada primeiro dia da semana, cada um de vós ponha alguma coisa à pate, reservando para isso conforme a prosperidade que tiver obtido, para que, quando eu vier, não se façam coletas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'E quando eu vier, enviarei aos que por cartas aprovardes, para que levem vossa doação para Jerusalém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'E se for necessário que eu também vá, irão comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Mas virei até vós, depois de passar pela Macedônia (porque passarei pela Macedônia).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'E pode ser que eu fique um tempo convosco ou também passar o inverno, para que me envieis para onde quer que eu for.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Porque eu não quero vos ver agora apenas de passagem; mas espero ficar convosco por algum tempo, se o Senhor o permitir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Porém ficarei em Éfeso até o Pentecostes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Porque uma porta grande e eficaz se abriu para mim, e há muitos adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'E se vier Timóteo, olhai para que ele esteja sem temor convosco; porque assim como eu, ele também faz a obra do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Portanto ninguém o despreze; mas enviai-o em paz, para que ele venha a mim; porque eu o espero com os irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'E quanto ao irmão Apolo, muito roguei que ele viesse com os irmãos até vós; mas ele de maneira nenhuma teve vontade de vir por agora; porém oferecendo-se a ele boa oportunidade, ele virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Vigiai, ficai firmes na fé, sede corajosos, e vos esforçai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Todas as vossas coisas sejam feitas em amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Vós sabeis que os da casa de Estéfanas foram os primeiros da Acaia, e que eles têm se dedicado ao trabalho dos santos; rogo-vos, pois, irmãos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Que também vos sujeiteis a eles, e a todo aquele que opera e trabalha junto conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'E eu me alegro com a vinda de Estéfanas, e de Fortunato, e de Acaico, porque estes supriram o que de vossa parte me faltava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Porque eles confortaram meu espírito, e também o vosso. Então reconhecei aos tais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'As igrejas da Ásia vos saúdam. Áquila e Priscila vos saúdam-vos afetuosamente no Senhor, e também a igreja que está na casa deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Todos os irmãos vos saúdam. Saudai-vos uns as outros com beijo santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Saudação de minha própria mão, de Paulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Se alguém não ama ao Senhor Jesus Cristo seja anátema. Vem, Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'A graça do Senhor Jesus Cristo esteja convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Meu amor esteja com todos vós em Cristo Jesus. Amém. A primeira Carta aos Coríntios foi escrita de Filipos, e enviada por Estéfanas, Fortunato, Acaico e Timóteo');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, e o irmão Timóteo, para a igreja de Deus que está em Corinto, com todos os santos que estão em toda a Acaia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Graça e paz de Deus nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o Pai das misericórdias, e o Deus de toda consolação,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Que nos consola em toda aflição nossa, para que também possamos consolar aos que estiverem em alguma aflição, com a consolação com que nós mesmos por Deus somos consolados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Porque assim como os sofrimentos de Cristo são abundantes em nós, assim também por Cristo é abundante nossa consolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Porém se nós somos afligidos, é para vossa consolação e salvação, que opera enquanto se suporta os mesmos sofrimentos que nós também sofremos; se estamos consolados, também é para vossa consolação e salvação');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'E nossa esperança por vós é firme, sabendo que, como sois participantes dos sofrimentos, assim também sois da consolação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Porque, irmãos, não queremos que ignoreis nossa aflição que nos sobreveio na Ásia, em que fomos excessivamente oprimidos, mais do que podíamos suportar, de tal modo que já tínhamos perdido a esperança de sobrevivermos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Por isso já tínhamos em nós mesmos a sentença de morte, para que não confiássemos em nós mesmos, mas sim em Deus, que ressuscita aos mortos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'O qual nos livrou de tamanha morte, e ainda nos livra; nele esperamos que também ainda nos livrará;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Junto do vosso auxílio com oração por nós, a fim de que, pelo favor concedido a nós por causa de muitas pessoas, por muitos sejam dadas graças a Deus por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Porque nosso orgulho é este: o testemunho de nossa consciência, que com simplicidade e sinceridade de Deus, não com sabedoria carnal, mas com a graça de Deus, nós nos comportamos no mundo, e especialmente convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Porque nenhuma outra coisa vos escrevemos, a não ser as que já sabeis, ou também entendeis; e espero que as entendereis por completo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Assim como também já em parte tendes nos entendido, que somos vosso orgulho, como também vós sois o nosso orgulho no dia do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'E com esta confiança eu quis primeiro vir até vós, para que tivésseis uma segunda graça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'E por vós passar para a Macedônia; e da Macedônia vir outra vez até vós; e depois ser enviado por vós até a Judeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Quando eu planejei isso, por acaso fiz de forma irresponsável? Ou o que eu planejo, planejo segundo a carne, para que eu diga sim e não ao mesmo tempo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Porém assim como Deus é fiel, nossa palavra para vós não foi sim e não ao mesmo tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Porque o Filho de Deus, Jesus Cristo, o que por nós foi pregado entre vós, isto é, por mim, e Silvano, e Timóteo, não foi sim e não, mas nele foi o “sim”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Porque todas as promessas nele são “sim”, e nele se diga Amém, para glória de Deus por meio de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Mas o que nos confirma convosco, e o que nos ungiu, é Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'O qual também nos selou, e nos deu o penhor do Espírito em nosso corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Porém invoco a Deus por testemunha sobre minha alma, que para vos poupar, até agora não vim a Corinto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Não que sejamos senhores de vossa fé; porém somos cooperadores de vossa alegria. Porque pela fé estais firmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Porém decidi isto mesmo comigo, de não mais vir até vós com tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Porque se eu vos entristecer, então quem será o que me alegrará, senão aquele que por mim foi entristecido?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'E isto mesmo vos escrevi, para que quando vier, não tenha tristeza dos que deveriam me alegrar, confiando de vós todos, que minha alegria é a alegria de todos vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Porque em muita aflição e angústia de coração eu vos escrevi com muitas lágrimas, não para que vos entristecêsseis, mas para que entendêsseis o amor que tenho em abundância para convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Porém se alguém me entristeceu, não entristeceu a mim somente, mas em parte (para que não se exagere) a todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Basta ao tal esta repreensão feita pela maioria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'De maneira que, ao invés disso, deveis lhe perdoar e consolar, para que ele não seja consumido pela excessiva tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Por isso vos peço que confirmeis o amor para com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Pois também para isso eu escrevi, para vos conhecer por meio de prova se vós sois obedientes em tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'E ao que perdoardes alguma coisa, também eu lhe perdoo; pois a quem eu tenho perdoado, se também eu perdoei, por causa de vós o fiz na presença de Cristo; para que Satanás não tire proveito de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Porque não ignoramos seus pensamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Além disso, quando vim a Troas para pregar o Evangelho de Cristo, e abrindo-se porta para mim no Senhor, não tive repouso em meu espírito, por não achar a meu irmão Tito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Porém, despedindo-me deles, eu parti para a Macedônia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'E graças a Deus, que sempre nos faz triunfar em Cristo, e por nós em todo lugar manifesta o cheiro de seu conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Porque para Deus somos o bom cheiro de Cristo, nos que se salvam, e nos que se perdem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Para estes certamente cheiro de morte, para a morte; mas para aqueles cheiro de vida, para a vida. E quem é idôneo para estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Porque nós não somos como muitos, que tentam vender a palavra de Deus; mas nós a falamos em Cristo, diante de Deus, com sinceridade, como enviados de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Por acaso começamos a recomendarmos a nós mesmos outra vez? Ou necessitamos, como alguns necessitam, de cartas de recomendação para vós, ou de vossa recomendação?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vós sois nossa carta de recomendação,escrita em nossos corações, conhecida e lida por todos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Manifestando que sois a carta de Cristo, administrada por nós, e escrita, não com tinta, mas com o Espírito do Deus vivente; não em tábuas de pedra, mas em tábuas de carne do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'E tal confiança temos por Cristo para com Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Não que sejamos capazes de pensar alguma coisa de nós como se fosse de nós mesmos, mas nossa capacidade é de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'O qual também nos fez capazes para sermos ministros do Novo Testamento, não da letra, mas do Espírito; porque a letra mata, mas o Espírito vivifica.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'E se o ministério da morte em letras, impresso em pedras, foi com glória, de maneira que os filhos de Israel não podiam fixar os olhos no rosto de Moisés, por causa da glória de seu rosto, que se extinguia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Por acaso o ministério do Espírito não terá ainda mais glória?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Porque se o ministério da condenação teve glória, o ministério da justiça excede muito mais em glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Pois o que já foi glorioso, em comparação, deixou de ter glória, por causa da glória superior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Porque se o que se extinguiu teve glória, muito mais glória tem o que permanece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Visto que temos tal esperança, falamos com muita ousadia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Não como Moisés, que punha um véu sobre o seu rosto, para que os filhos de Israel não enxergassem o fim do que se extinguia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Porém suas mentes foram endurecidas, porque até hoje fica o mesmo véu ainda coberto na leitura do antigo pacto, o qual é extinto por Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Mas até hoje, quando se lê as palavras de Moisés, o véu está posto sobre o coração deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Porém quando se converterem ao Senhor, então o véu será tirado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'O Senhor é o Espírito; e onde está o Espírito do Senhor, aí há liberdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'E todos nós, com o rosto descoberto, refletindo como que um espelho a glória do Senhor, somos transformados de glória em glória, segundo a mesma imagem, como pelo Espírito do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Por isso, tendo este ministério, segundo a misericórdia que nos foi feita, não desfalecemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Mas já rejeitamos as coisas ocultas e vergonhosas, não andando com astúcia, nem falsificando a Palavra de Deus, mas pela manifestação da verdade fazemos recomendação de nós mesmos à consciência de todos os seres humanos, à vista de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Porém se o nosso Evangelho está encoberto, é para os que se perdem que está encoberto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'Nos quais o deus destes tempos cegou os entendimentos, isto é,os incrédulos, para que não lhes brilhe a luz do Evangelho da glória de Cristo, que é a imagem de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Porque nós não pregamos a nós mesmos, mas sim a Cristo Jesus, o Senhor; e a nós mesmos como vossos servos, por causa de Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Porque o Deus que disse que das trevas brilhasse a luz é o mesmo que brilhou em nossos corações, para a iluminação do conhecimento da glória de Deus no rosto de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Porém temos este tesouro em vasos de barro, para que a excelência do poder seja de Deus, e não de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Somos em tudo afligidos, mas não esmagados; perplexos, mas não desesperados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Perseguidos, mas não desamparados; abatidos, porém não destruídos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Sempre por todas as partes trazendo a mortificação do Senhor Jesus no corpo, para que também a vida de Jesus se manifeste em nossos corpos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Porque nós, que vivemos, estamos sempre entregues à morte por causa de Jesus, para que também a vida de Jesus se manifeste em nossa carne mortal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'De maneira que a morte opera em nós, mas em vós opera a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'E nós temos o mesmo Espírito de fé, assim como está escrito: Cri, e por isso falei;Nós também cremos, e por isso também falamos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'sabendo que o que ressuscitou ao Senhor Jesus, também nos ressuscitará por meio de Jesus, e nos apresentará juntos de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Porque todas estas coisas são por causa de vós, para que a graça aumente por meio de muitas pessoas,superabundando os agradecimentos à glória de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Por isso não desfalecemos; mas ainda que nosso ser exterior se destrua, todavia o interior se renova a cada dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Porque nossa leve e momentânea aflição nos produz um peso eterno de excelentíssima glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Por isso nós não prestamos atenção para as coisas visíveis, mas sim para as invisíveis; porque as coisas visíveis são temporárias, mas as invisíveis são eternas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Porque sabemos que, se nossa casa terrestre deste tabernáculo se desfizer, temos um edifício de Deus, uma casa não feita por mãos, mas eterna, nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Porque nesta casa gememos, desejando sermos revestidos de nossa habitação do céu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Dado que, se estivermos vestidos, não seremos achados nus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Pois de fato nós, os que estamos neste tabernáculo, gememos pressionados, não porque queremos ser despidos, mas sim, revestidos; para que a mortalidade seja devorada pela vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'E para isto mesmo que Deus nos preparou, ele que também deu o penhor do Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Por isso sempre temos confiança, e sabemos que, enquanto habitarmos no corpo, estamos ausentes do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(Pois andamos pela fé, e não pela vista).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Temos, porém, confiança, e queremos mais deixar o corpo, e habitar com o Senhor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Por isso também desejamos muito ser agradáveis a ele, quer presentes no nosso corpo,quer ausentes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Pois todos devemos comparecer diante do Tribunal de Cristo, para que cada um receba o pagamento das coisas que fez no corpo, seja bem ou mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Conhecendo, pois, o temor ao Senhor, persuadimos as pessoas para a fé, e a Deus somos claramente visíveis; mas espero, também, que estejamos claramente visíveis em vossas consciências.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Porque não nos recomendamos novamente para vós; mas damos oportunidade de vos orgulhardes de nós; para que tenhais o que responder aos que se orgulham da aparência, e não do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Pois se nós enlouquecemos, é para Deus; se estamos sensatos, é para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Porque é o amor de Cristo que nos controla; pois temos certeza que, se um morreu por todos, logo todos morreram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'E ele morreu por todos, para que os que vivem não vivam mais para si, mas sim, para aquele que por eles morreu e ressuscitou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Portanto daqui em diante a ninguém conhecemos segundo a carne, e ainda que também tenhamos conhecido a Cristo segundo a carne, todavia agora não o conhecemos assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Portanto, se alguém está em Cristo, uma nova criatura é; as coisas velhas já passaram, eis que tudo se fez novo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'E tudo isto vem de Deus, o qual por Jesus Cristo nos reconciliou consigo, e nos deu o ministério da reconciliação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Porque Deus estava em Cristo reconciliando consigo ao mundo, não lhes atribuindo seus pecados; e pôs em nós a palavra da reconciliação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Assim, pois, nós somos embaixadores da parte de Cristo, como se Deus rogasse por nós; por isso,rogamos em Cristo: Reconciliai-vos com Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Pois ele fez com que aquele que não conheceu pecado se tornasse pecado por nós; para que nós nele fôssemos feitos justiça de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'E nós, como trabalhadores conjuntamente com ele, rogamos que não tenhais recebido a graça de Deus em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Porque ele diz: Em tempo agradável te ouvi, e no dia da salvação te socorri; eis agora o tempo agradável, eis agora o dia da salvação');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Escândalo nenhum damos em coisa alguma, para que nosso trabalho não seja acusado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Mas em tudo nos fizemos agradáveis como trabalhadores de Deus, em muita tolerância, em aflições, em necessidades, em angústias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'Em açoites, em prisões, em tumultos, em trabalhos, em vigílias, em jejuns;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'Em pureza, em conhecimento, em paciência, em bondade, no Espírito Santo, em amor não fingido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Em palavra da verdade, em poder de Deus, com armas da justiça, à esquerda, e à direita;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Por honra e por desonra; por infâmia e por boa fama; considerados como enganadores, e como verdadeiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Como estranhos, e conhecidos; como morrendo, e eis que estamos vivendo; como castigados e ainda não mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Como entristecidos, porém sempre alegres; como pobres, porém enriquecendo a muitos; como nada tendo, e possuindo tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Para vós, ó coríntios, está aberta nossa boca; e nosso coração está ampliado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Nós não temos lhes estreitado, mas vós estais estreitos em nossos sentimentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'E em recompensa disto (falo como a filhos) alargai vós também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Não vos ajunteis em outro jugo com os descrentes. Porque, que parceria tem a justiça com injustiça? E que parceria tem a luz com as trevas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'E que acordo há entre Cristo e Belial? Ou que parte tem o crente com o incrédulo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'E que acordo há entre o Templo de Deus e os ídolos? Porque vós sois o templo do Deus vivente, como Deus disse: Neles habitarei, e entre eles andarei; e eu serei seu Deus, e eles serão meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Portanto: saí do meio deles, e vos separai, diz o Senhor; e não toqueis coisa impura, e eu vos aceitarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'E eu vos serei por Pai, e vós sereis para mim filhos e filhas,diz o Senhor Todo Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Amados, por termos tais promessas, limpemo-nos de toda impureza da carne e do espírito, aperfeiçoando a santificação no temor de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Dai lugar a nós em vossos corações; contra ninguém agimos mal, a ninguém corrompemos, a ninguém abusamos para nosso proveito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Não digo isto para vos condenar; porque já disse antes que vós estais em nossos corações, para juntamente morrermos e vivermos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Muita confiança eu tenho em vós; eu tenho muito orgulho de vós; eu estou cheio de consolação; excedo sobremaneira de alegria em todas as nossas aflições.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Porque até quando viemos à Macedônia, nenhum repouso teve nossa carne; mas em tudo fomos afligidos: lutas por fora, temores por dentro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mas Deus, que consola aos abatidos, nos consolou com a vinda de Tito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'E não somente com a vinda dele, mas também com a consolação com que foi consolado quanto a vós, contando-nos vossas saudades, vosso choro e vosso zelo por mim, de maneira que me alegrei ainda mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Porque, ainda que eu tenha vos entristecido com a carta, não me arrependo, ainda que tenha me causado pesar; porque vejo que aquela carta vos entristeceu, ainda que por pouco tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Agora eu me alegro, não porque vós vos entristecestes, mas porque vos entristecestes para o arrependimento. Porque vós vos entristecestes segundo a vontade de Deus; de maneira que em nada sofrestes dano por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Pois a tristeza segundo a vontade de Deus opera arrependimento para a salvação, de que ninguém se arrepende; mas a tristeza do mundo opera a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Porque vede isto mesmo, quanto empenho que vossa tristeza segundo Deus produziu em vós! E também defesa própria, indignação, temor, saudades, zelo, e desejo de justiça! Em tudo vos mostrastes estar puros quanto a este assunto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Portanto, ainda que tenha escrito para vós, eu não fiz isso por causa daquele que fez o dano, nem por causa daquele que sofreu o dano; mas sim para que nosso empenho por vós diante de Deus vos fosse revelado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Por isso fomos consolados com vosso consolo; e muito mais nos alegramos com a alegria de Tito, de que seu espírito foi revigorado por todos vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Porque se em alguma coisa me orgulhei de vós diante dele, não fiquei envergonhado; mas assim como falamos de vós com verdade, assim também nosso orgulho diante de Tito se confirmou verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'E os sentimentos dele por vós estão ainda maiores, por se lembrar da obediência de todos vós, de como o recebestes com temor e tremor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Por isso eu me alegro de que em tudo posso confiar em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Também, irmãos, vos fazemos saber a graça de Deus dada às igrejas da Macedônia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Que em muita provação de aflição, a abundância de sua alegria, e sua profunda pobreza abundaram nas riquezas de sua generosidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Pois dou testemunho de que foram voluntários segundo sua capacidade e até além de sua capacidade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Pedindo-nos com muito entusiasmo que aceitássemos a graça e a comunhão deste serviço para os santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'E não somente fizeram como nós esperávamos, mas também entregaram a si mesmos, primeiramente ao Senhor, e depois a nós, pela vontade de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'De maneira que convocamos a Tito para que, assim como tinha começado antes, assim também terminasse esta graça entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Portanto, assim como em tudo abundais: em fé, em palavra, em conhecimento, em todo empenho, e em vosso amor por nós; sede também abundantes nesta graça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Eu não digo isto como que mandando, mas sim para também, por meio do empenho dos outros, provar a sinceridade de vosso amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Porque já conheceis a graça de nosso Senhor Jesus Cristo, que, sendo rico, por causa de vós se fez pobre; para que com a pobreza dele, vós enriquecêsseis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'E nisto dou minha opinião: porque isto vos convém, não somente a fazer, mas também a querer, dado que começastes desde o ano passado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Portanto agora completai também o que já foi começado; para que, assim como houve ânimo no querer, assim também o seja no que tendes de completar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Porque se existe a boa vontade, a doação é aceitável conforme o que se tem, e não conforme o que não se tem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Porque não digo isto para que outros tenham alívio, e vós opressão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Mas para que igualmente, neste tempo presente, vossa abundância seja para suprir a falta dos outros, para que também a abundância deles seja para suprir vossa falta, para que haja igualdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Como está escrito: O que muito colhe, não teve mais; e o que colhe pouco, não teve menos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Porém graças a Deus, que ele pôs o mesmo empenho por vós no coração de Tito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Pois aceitou nosso chamado, e com muito entusiasmo partiu voluntariamente até vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'E enviamos com ele o irmão que é elogiado no Evangelho por todas as igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'E não somente isto, mas também foi escolhido pelas igrejas como companheiro de nossa viagem com esta graça, que é administrada por nós para a glória do mesmo Senhor, e a prontidão de vosso ânimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Assim evitamos que ninguém nos critique nesta abundância que é administrada por nós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Procurando o que é honesto, não somente diante do Senhor, mas também diante das pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Também enviamos com eles ao nosso irmão, ao qual muitas vezes em muitas coisas já provamos que ele é cuidadoso, e agora ainda muito mais cuidadoso pela muita confiança que ele tem em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Quanto a Tito, ele é meu companheiro e cooperador para convosco; quanto a nossos irmãos, eles são representantes das igrejas, e glória de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Portanto, mostrai para com eles a prova de vosso amor, e de nosso orgulho por vós, diante das igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Porque não é necessário vos escrever sobre o trabalho que se faz para os santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Porque eu sei a prontidão de vosso ânimo, do qual eu me orgulho de vós para os Macedônios, que Acaia já está pronta desde o ano passado; e o zelo que começou de vós tem estimulado a muitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Porém enviei a estes irmãos, para que nosso orgulho quanto a vós neste assunto não seja vão; para que (como eu já disse) possais estar prontos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Para que, se caso vierem alguns macedônios comigo, e vos encontrarem despreparados, não nos envergonhemos (para não dizermos vós), por causa da confiança neste orgulho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Portanto achei necessário dizer a estes irmãos que viessem primeiro até vós, e preparassem primeiro vossa generosidade, já antes prometida, para que esteja pronta como boa vontade e não como avareza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Digo, porém isto, que o que semeia pouco, também pouco colherá; e o que semeia generosamente, também generosamente colherá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Cada qual faça como propõe em seu coração, não com tristeza, ou por obrigação; porque Deus ama ao que dá com alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'E Deus é poderoso para fazer abundar em vós toda graça, para que sempre tendo de tudo, em tudo suficientes, abundeis em toda boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Assim como está escrito: Ele espalhou e deu aos pobres; sua justiça permanece para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Ora, aquele que dá a semente ao que semeia, também vos dê pão para comer, e multiplique sua sementeira, e aumente os frutos de vossa justiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Para que em tudo enriqueçais em toda generosidade, a qual opera por nós, resultando em graças a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Porque o trabalho deste serviço está suprindo não somente a falta dos santos, mas também se torna abundante em muitas graças a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Porque pela prova deste trabalho, glorificarão a Deus quanto à submissão de vossa confissão ao Evangelho de Cristo, e da bondade da comunhão para com eles e para com todos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'E por sua oração por vós, tendo saudades de vós, por causa da excelente graça de Deus sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'E graças a Deus por seu dom indescritível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Além disto eu mesmo, Paulo, pela mansidão e bondade de Cristo, vos rogo, (eu que em verdade sou humilde entre vós quando presente, porém ousado para convosco quando ausente);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Rogo pois, que quando eu estiver presente, não tenha que mostrar ousadia com a confiança de que penso que terei de me mostrar ousado para com alguns que nos consideram como se andássemos segundo a carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Pois ainda que andemos na carne, não batalhamos segundo a carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Porque as armas de nossa batalha não são carnais, mas sim poderosas em Deus, para destruirmos fortalezas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Assim destruímos pensamentos e toda arrogância que se levanta contra o conhecimento de Deus, e levamos como prisioneiro todo pensamento para a obediência a Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'E estamos prontos para vingar toda desobediência, quando vossa obediência for completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Olhais as coisas pela aparência? Se alguém confia de si mesmo que é de Cristo, pense o tal outra vez consigo mesmo que, assim como ele é de Cristo, assim também nós somos de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Porque se eu também ainda mais me quiser orgulhar do nosso poder que o Senhor nos deu para edificação, e não para vossa destruição, não me envergonharei;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Para que não pareça que eu queira vos amedrontar por meio de cartas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Porque eles dizem que as cartas são em verdade graves e fortes, mas a presença do corpo é fraca, e a palavra desprezível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Pense isto o tal, que assim como somos na palavra por cartas quando ausentes, assim também seremos por obra quando estivermos presentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Porque não ousamos a nos classificar ou comparar com alguns que louvam a si mesmos; mas estes tem falta de entendimento ao medirem a si mesmos consigo mesmos, e ao compararem a si mesmos consigo mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Nós, porém, não nos orgulharemos além da medida, mas sim conforme a medida da extensão que Deus repartiu conosco, medida que também vos alcança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Porque em nada estendemos além do que devíamos, como se não tivéssemos vos alcançado; pois fomos nós os primeiros a vir até vós no Evangelho de Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Não nos orgulhamos além da medida no trabalho de outros, mas temos esperança de que, quando vossa fé crescer, seremos engrandecidos abundantemente entre vós conforme nossa extensão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Para pregarmos o evangelho em outros lugares além de vós; e não na extensão de outros pregadores, para nos orgulharmos de coisas que já estavam prontas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Porém o que se orgulha, se orgulhe no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Porque não é o que louva a si mesmo, mas sim o que louva ao Senhor; esse é o aprovado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Gostaria que me suportásseis um pouco em minha loucura; mas ainda assim suportai-me.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Pois estou zeloso de vós com zelo de Deus, porque tenho vos preparado para vos apresentar como uma virgem pura, a um marido, isto é, a Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Mas temo que, assim como a serpente enganou a Eva com sua astúcia, também assim em alguma maneira vossas mentes se corrompam da simplicidade que está em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Porque se aquele que vem pregasse a outro Jesus que nós não temos pregado, ou se recebêsseis outro espírito que não recebestes, ou evangelho diferente do que aceitastes, certamente vós o aceitaríeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Porque penso que eu em nada fui inferior aos mais excelentes apóstolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'E se também sou rude na palavra, contudo não o sou no conhecimento; mas em tudo já estamos totalmente manifestos entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Por acaso pequei ao humilhar a mim mesmo, para que vós fôsseis exaltados, por eu ter vos anunciado gratuitamente o Evangelho de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Eu tomei o que era de outras igrejas, ao receber salário, para servir a vós; e quando eu estava presente convosco, e tendo necessidade, a ninguém incomodei com algum encargo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Porque os irmãos que vieram da Macedônia supriram minha falta; e em tudo eu me guardei de vos ser incômodo, e ainda me guardarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'A verdade de Cristo está em mim, de modo que este meu orgulho não me será impedido nas regiões da Acaia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Por que? Porque não vos amo? Deus o sabe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mas o que eu faço, ainda o farei, para cortar a oportunidade daqueles que buscam oportunidade para serem considerados como nós naquilo em que se orgulham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Porque tais falsos apóstolos são trabalhadores fraudulentos, fingindo serem apóstolos de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'E isto não é algo maravilhoso; porque o mesmo Satanás se transforma fingindo ser anjo de luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Portanto não é muita surpresa se também seus trabalhadores se transformam, fingindo serem trabalhadores da justiça; o fim dos quais será conforme as suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Outra vez digo, que ninguém pense que sou tolo; ou se não, recebei a mim como se eu fosse tolo, para que eu também me orgulhe um pouco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'O que eu estou dizendo, não estou dizendo conforme o Senhor, mas sim como um tolo, nesta firme orgulho confiante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Porque muitos se orgulham segundo a carne; e também eu me orgulharei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Porque vós, sendo tão sábios, tolerais com boa vontade os tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Pois vós tolerais se alguém vos põe como escravos, se alguém vos explora, se alguém se aproveita de vós, se alguém age com arrogância, se alguém vos fere no rosto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Eu digo como algo desonroso, como se tivéssemos estado fracos; mas naquilo em que algum outro é atrevido, eu também sou atrevido (falo como tolo).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Eles são hebreus? Eu também. Eles são israelitas? Eu também. Eles são semente de Abraão? Eu também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Eles são servidores de Cristo? (Falo como tolo:) eu sou mais ainda; em trabalhos, muito mais; em feridas, mais; em prisões, muito mais; em perigo de morte, muitas vezes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Eu já recebi dos judeus cinco vezes quarenta açoites menos um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Por três vezes já fui espancado com varas, uma vez fui apedrejado, três vezes sofri naufrágios, passei uma noite e um dia à deriva no mar profundo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Muitas vezes em viagens, em perigos de rios, em perigos de assaltantes, em perigos dos da minha nação, em perigos dos gentios, em perigos na cidade, em perigos no deserto, em perigos no mar, em perigos entre falsos irmãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'Em trabalho e fadiga, muitas vezes em vigílias, em fome e em sede, em jejuns muitas vezes, em frio e nudez.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Além das coisas de fora, a cada dia me vem preocupações de todas as igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Quem enfraquece, que eu também não enfraqueça? Quem não tropeça no pecado,que eu não me queime por dentro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Se é necessário se orgulhar, eu me orgulharei das coisas relativas à minha fraqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'O Deus e Pai de nosso Senhor Jesus Cristo, que é bendito eternamente, sabe que eu não estou mentindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Em Damasco, o governador subordinado ao Rei Aretas pôs guardas na cidade dos damascenos, querendo me prender.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'E me fizeram descer num cesto por uma janela da muralha da cidade, e assim escapei das mãos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Verdadeiramente não me convém me orgulhar; porque eu virei para as visões e revelações do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Conheço um homem em Cristo que, catorze anos atrás, foi arrebatado até o terceiro céu (se no corpo, não sei; se fora do corpo, não sei; Deus o sabe).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'E sei que o tal homem (se no corpo, se fora do corpo, não sei; Deus o sabe),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Foi arrebatado ao paraíso, e ouviu palavras inexprimíveis, que ao homem não é lícito falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'D este tal eu me orgulharei, mas de mim mesmo não me orgulharei, a não ser em minhas fraquezas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Porque se eu quiser me orgulhar, não serei tolo; porque direi a verdade; porém eu me contenho, para que ninguém me considere mais do que aquilo que vê em mim, ou ouve de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'E para que eu não ficasse arrogante pela excelência das revelações, me foi dado um espinho na carne, que é um mensageiro de Satanás, para me atormentar, para que eu não ficasse arrogante.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Três vezes eu orei ao Senhor por causa disso, para que isso de afastasse de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Mas ele me disse: “Minha graça te basta, porque meu poder se aperfeiçoa na fraqueza”. Por isso, com muito prazer, eu me orgulharei nas minhas fraquezas, para que o poder de Cristo habite em mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Por isso tenho prazer nas fraquezas, nos insultos, nas necessidades, nas perseguições, nas angústias por causa de Cristo; porque quando estou fraco, então fico forte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Eu me fiz de tolo ao me orgulhar; mas vós me obrigastes a isso; porque eu devia ser louvado por vós, pois eu em coisa nenhuma fui inferior aos “superapóstolos”, ainda que eu nada seja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Os sinais do meu apostolado foram efetuados entre vós em toda paciência, em sinais, milagres e maravilhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Afinal, qual foi a coisa em que fostes inferiores às outras igrejas, a não ser em que eu mesmo não vos fui incômodo? Perdoai-me esta injustiça!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Eis que estou prestes a vir pela terceira vez até vós, e não vos serei incômodo como um peso. Porque eu não busco o que é vosso, mas sim a vós. Porque os filhos não devem guardar bens para os pais, mas sim os pais para os filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'E eu de muita boa vontade me gastarei, e me deixarei gastar por vossas almas, ainda que quanto mais eu vos amo, menos sou amado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Mas que assim seja, que eu não fui incômodo para convosco. Mas, como eu era astuto, eu vos tomei por engano!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Por acaso eu me aproveitei de vós, por meio de alguém que enviei até vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Eu roguei a Tito, e enviei ao irmão com ele; por acaso Tito se aproveitou de vós? Por acaso não andamos nós no mesmo espírito, e nos mesmos passos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Pensais ainda que nós nos desculpamos convosco? Falamos diante de Deus em Cristo; e fazemos tudo isto, ó amados, para vossa edificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Porque eu temo que, quando vier, eu não vos encontre da maneira que eu quero; e vós me encontreis da maneira que não quereis; para que não haja brigas, invejas, iras, rivalidades, difamações, fofocas, arrogâncias e tumultos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Para que, quando eu vier outra vez, meu Deus não me humilhe para convosco, e chore por muitos dos que antes pecaram, e ainda se não arrependeram da imundícia, e fornicação, e promiscuidade que cometeram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Esta é a terceira vez que venho até vós; pela boca de duas ou três testemunhas toda palavra será firmada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Eu já tinha dito antes, e disse quando estive presente pela segunda vez, e agora ausente o escrevo aos que pecaram anteriormente, e a todos os demais, que se vier outra vez, não lhes serei tolerante;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Pois buscais prova de que Cristo fala em mim, o qual em vós não é fraco, mas que é poderoso entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Porque ainda que tenha sido crucificado por fraqueza, contudo ele vive pelo poder de Deus. Porque também nós somos fracos nele, porém com ele viveremos pelo poder de Deus em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Examinai-vos a vós mesmos, se estais na fé; provai-vos a vós mesmos. Ou não conheceis a vós mesmos, que Jesus Cristo está em vós? A menos que vós estejais reprovados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Mas espero que vós entendereis que nós não somos reprovados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'E eu desejo pedindo a Deus que nenhum mal façais; não para que sejamos achados aprovados, mas para que vós façais o bem, e nós sejamos como reprovados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Porque nada podemos fazer contra a verdade, mas sim pela verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Pois nós nos alegramos quando estamos fracos, e vós estais fortes; e isto também desejamos: o vosso aperfeiçoamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Por isso eu escrevo estas coisas ausente; para que, quando estiver presente não use de rigor, segundo o poder que o Senhor tem me dado, para edificação, e não para destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Quanto às demais coisas, irmãos, alegrai-vos, sede íntegros, consolai-vos, tenhais um mesmo entendimento, vivei em paz; e o Deus de amor e paz será convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Saudai-vos uns aos outros com beijo santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Todos os santos vos saúdam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'A graça do Senhor Jesus Cristo, e o amor de Deus, e a comunhão do Espírito Santo seja com todos vós. Amém. A Segunda Carta aos Coríntios foi escrita de Filipos, na Macedônia, e enviada por Tito e Lucas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulo, apóstolo (não da parte dos seres humanos, nem por meio de homem algum, mas sim por Jesus Cristo, e por Deus Pai, que o ressuscitou dos mortos),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'e todos os irmãos que estão comigo, para as igrejas da Galácia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Graça seja convosco, e também a paz de Deus Pai, e do nosso Senhor Jesus Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'que deu a si mesmo pelos nossos pecados, para nos tirar da presente era maligna, conforme a vontade do nosso Deus e Pai,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'ao qual seja a glória para todo o sempre, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Admiro-me de que tão rapidamente desviastes daquele que vos chamou na graça de Cristo, em troca de outro evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Não que haja outro evangelho,porém há alguns que vos inquietam, e querem perverter o Evangelho de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Porém, ainda que nós mesmos, ou um anjo do céu vos anuncie outro evangelho além do que já vos anunciamos, maldito seja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Como já havíamos dito, volto também agora a dizer: se alguém vos anunciar outro evangelho além do que já recebestes, maldito seja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Pois agora estou buscando a aprovação das pessoas, ou a de Deus? Ou procuro agradar a pessoas? Pois, se ainda tentasse agradar a pessoas, eu não seria servo de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Mas faço-vos saber, irmãos, que o Evangelho anunciado por mim não se baseia em pessoas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'pois não o recebi, nem aprendi de ser humano algum, mas sim pela revelação de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Pois já ouvistes da minha conduta no judaísmo, como em excesso eu perseguia e tentava destruir a Igreja de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'e como no judaísmo eu era mais avançado que muitos de minha idade em minha nação, e era extremamente zeloso das tradições de meus pais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mas quando Deus (que me separou desde o ventre da minha mãe, e por sua graça me chamou) se agradou');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'de revelar o seu Filho em mim, para eu evangelizar os gentios, de imediato, não fui pedir conselho com pessoa alguma;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'nem subi a Jerusalém para os que já eram apóstolos antes de mim; em vez disso, parti para a Arábia, e voltei outra vez a Damasco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Então, depois de três anos, subi a Jerusalém para visitar Pedro, e estive com ele por quinze dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'E vi nenhum outro dos apóstolos, a não ser Tiago, o irmão do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Ora, das coisas que vos escrevo, eis que, diante de Deus, não estou mentindo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Depois fui para as regiões da Síria e da Cilícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Eu, porém, não era conhecido de rosto pelas igrejas da Judeia que estão em Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'mas somente haviam ouvido que “Aquele que antes nos perseguia agora anuncia a fé que antes tentava destruir”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'E glorificavam a Deus por causa de mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Depois de passados catorze anos, subi outra vez a Jerusalém com Barnabé, levando comigo também Tito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'E, por causa de uma revelação, subi, e lhes declarei o Evangelho que prego entre os gentios. Isso, porém, foi em particular, com os mais influentes, para que eu eu não corresse ou tivesse corrido em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Porém nem mesmo Tito, que estava comigo, sendo grego, foi obrigado a se circuncidar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'E isso por causa de falsos irmãos, que haviam se infiltrado, e entraram secretamente para espionar a nossa liberdade que temos em Cristo Jesus, a fim de nos tornar escravos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'A eles nem sequer por um momento cedemos a nos sujeitarmos, para que a verdade do Evangelho permanecesse em vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'E quanto aos de maior influência (o que haviam sido antes não me importa; Deus não se interessa na aparência humana); esses, pois, que eram influentes, nada me acrescentaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Pelo contrário, quando viram que o Evangelho aos incircuncisos havia sido confiado a mim, assim como a Pedro, aos circuncisos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(pois aquele que operou em Pedro para o apostolado da circuncisão, esse operou também em mim para os gentios)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'e quando Tiago, Cefas, e João, que eram considerados como colunas, reconheceram a graça que me foi dada, eles estenderam as mãos direitas de comunhão a mim e a Barnabé, para que nós fôssemos aos gentios, e eles aos circuncisos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'sob a condição de que nos lembrássemos dos pobres; isso também procurei fazer com empenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'E quando Pedro veio a Antioquia, estive contra ele face a face, pois ele devia ser repreendido;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'porque, antes que alguns que Tiago enviou chegassem, ele comia com os gentios; mas depois que chegaram, ele se retirou e se separou, temendo os que eram da circuncisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'E também com ele os outros judeus fingiram, de maneira que até Barnabé se deixou levar pela hipocrisia deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Mas quando vi que não estavam agindo corretamente conforme a verdade do Evangelho, disse na presença de todos a Pedro: “Se tu, que és judeu, vives como gentio, e não como judeu, por que obrigas os gentios a viverem como judeus?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Nós, que somos judeus por natureza, e não pecadores dentre os gentios,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'sabemos que o ser humano não é justificado pelas obras da Lei, mas sim pela fé em Jesus Cristo. Também nós temos crido em Cristo Jesus, para que fôssemos justificados pela fé em Cristo, e não pelas obras da Lei; pois ninguém se justificará pelas obras da Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Mas se nós, que buscamos ser justificados em Cristo, também nós mesmos somos achados pecadores, por isso Cristo contribui com o pecado? De maneira nenhuma!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Pois, se volto a construir as coisas que já destruí, provo que eu mesmo cometi transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Pois pela Lei estou morto para a Lei, a fim de que eu viva para Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Já estou crucificado com Cristo. Estou vivendo não mais eu, mas Cristo vive em mim; e vivo a minha vida na carne por meio da fé no Filho de Deus, que me amou, e entregou a si mesmo por mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Não anulo a graça de Deus; pois, se a justiça é por meio da Lei, logo Cristo morreu por nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ó insensatos gálatas, quem vos iludiu para não obedecerdes à verdade? Diante dos vossos olhos Jesus Cristo foi retratado entre vós como crucificado!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Só isto eu queria saber de vós: recebestes o Espírito pelas obras da Lei ou pela pregação da fé?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Sois vós tão insensatos que, depois de começardes no Espírito, agora terminareis na carne?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Experimentastes tantas coisas em vão? Se é que foi mesmo em vão!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Ora, aquele que vos dá o Espírito e que opera maravilhas entre vós faz isso por causa das obras da Lei ou da pregação da fé?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Assim como “Abraão creu em Deus, e foi lhe reputado como justiça”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'entendei, pois, que os que são da fé são filhos de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'E a Escritura, prevendo que Deus justificaria os gentios pela fé, prenunciou o Evangelho a Abraão, dizendo: Todas nas nações serão abençoadas em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Portanto, os que são da fé são abençoados com o crente Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Pois todos os que são das obras da Lei estão sob maldição, porque está escrito: Maldito todo aquele que não permanecer em todas as coisas que estão escritas no livro da Lei, para fazê-las.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'E é evidente que pela Lei ninguém será justificado, porque: O justo viverá pela fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'A Lei não provém da fé; porém: Quem fizer estas coisas por elas viverá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Cristo nos resgatou da maldição da Lei ao se fazer maldição para o nosso benefício (pois está escrito: Maldito todo aquele que for pendurado em um madeiro.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'com a finalidade de que a bênção de Abraão chegasse aos gentios em Cristo Jesus, para que recebêssemos a promessa do Espírito por meio da fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Irmãos, estou falando em termos humanos: ainda que seja o pacto de uma pessoa, depois de confirmado, ninguém o anula, nem lhe acrescenta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Ora, as promessas foram ditas a Abraão e à sua descendência. E não diz: “E às descendências” como que falando de muitos, mas sim como a um: “E à tua descendência”, que é Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Mas digo isto: o pacto foi confirmado anteriormente por Deus em Cristo; e a Lei que veio quatrocentos e trinta anos depois não o invalida de maneira que anule a promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Pois, se a herança é pela Lei, já não é pela promessa; mas foi por meio da promessa que Deus a concedeu gratuitamente a Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Para que, pois, é a Lei? Ela foi ordenada por causa das transgressões, até que chegasse o descendente a quem a promessa havia sido feita; e foi posta pelos anjos na mão de um mediador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Ora, o mediador não é de um só, mas Deus é um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Acaso, pois, a Lei é contra as promessas de Deus? De maneira nenhuma! Pois, se a Lei houvesse sido entregue para que pudesse dar vida, na verdade a justiça teria sido pela Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Mas a Escritura prendeu tudo debaixo do pecado a fim de que a promessa fosse dada aos crentes por meio da fé em Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Porém, antes que a fé viesse, estávamos vigiados sob a Lei, e presos, até que a fé fosse revelada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Dessa maneira, a Lei foi nosso tutor em condução a Cristo, para que pela fé fossemos justificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Mas depois que a fé chegou, já não estamos mais sob um tutor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'pois todos vós sois filhos de Deus por meio da fé em Cristo Jesus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'pois todos vós que fostes batizados em Cristo já vos revestistes de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Assim, não há judeu nem grego; não há servo nem livre; não há macho nem fêmea. Pois todos vós sois um em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'E, se vós sois de Cristo, então sois descendência de Abraão, e herdeiros conforme a promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Digo, porém, que, enquanto o herdeiro é criança, em nada é diferente do servo, ainda que seja senhor de tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Mas está sob tutores e administradores, até o tempo determinado pelo pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Assim também nós, quando éramos crianças, estávamos escravizados debaixo dos princípios elementares do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Mas quando o tempo se completou, Deus enviou o seu Filho, nascido de mulher, nascido sob a Lei,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'para redimir os que estavam sob a Lei, a fim de que nós recebêssemos a adoção como filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'E, como sois filhos, Deus enviou aos vossos corações o Espírito do seu Filho, que clama: “Aba, Pai!”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Portanto, tu já não és mais servo, mas sim filho; e se és filho, também és herdeiro de Deus por meio de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Quando, porém, não conhecíeis a Deus, vós servíeis aos que por natureza não são deuses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Mas agora, que conheceis Deus, mais que isso, por Deus sois conhecidos, por que voltais outra vez aos fracos e miseráveis princípios elementares, aos quais quereis servir de novo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vós guardais dias, meses, tempos, e anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Temo a vosso respeito de que talvez eu tenha trabalhado para convosco em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Rogo-vos, irmãos, que sejais como eu, pois também eu sou como vós. Nenhum mal me fizestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'E vós sabeis que foi com uma enfermidade da carne que vos anunciei o Evangelho pela primeira vez;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'E não cedestes à tentação de ter desprezo ou repugnância por meu aspecto físico; ao contrário, vós me recebestes como a um mensageiro de Deus, como ao próprio Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'O que houve, pois, com a vossa alegria? Pois eu vos dou testemunho de que, se fosse possível, teríeis arrancado os vossos próprios olhos para dá-los a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Tornei-me, por acaso, vosso inimigo por ter vos dito a verdade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Eles têm interesse por vós, mas não com boa intenção; mas querem vos isolar de mim,para que vós mostreis interesse por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'É bom, porém, mostrar interesse para o bem sempre, e não somente quando estou presente convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Meus filhinhos, por quem volto a sofrer dores de parto, até que Cristo seja formado em vós:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'queria eu estar agora presente convosco, e mudar meu tom de voz, pois estou perplexo a vosso respeito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Respondei-me vós, que quereis estar sob a Lei: não ouvis a Lei?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Pois está escrito que Abraão tinha dois filhos: um da escrava, e outro da livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'O da escrava nasceu segundo a carne, mas o da livre, pela promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Isto serve de ilustração, pois estes são dois pactos: um é o do monte Sinai, que gera filhos para a escravidão, que é Agar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Pois esta Agar é o monte Sinai, na Arábia, e corresponde à Jerusalém de agora, e é escravizada com os filhos dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mas a Jerusalém de cima é livre; esta é a mãe de todos nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Pois está escrito: Alegra-te, ó estéril, que não geras filhos; extravasa gritando de júbilo, tu, que não estás de parto; porque muitos mais são os filhos da solitária, que os da que tem marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Nós, porém, irmãos, como Isaque, somos filhos da promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Porém, assim como naquele tempo o que nasceu segundo a carne perseguia o que nasceu segundo o Espírito, assim também é agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Mas o que diz a Escritura? Expulsa a escrava e o filho dela, porque de maneira nenhuma o filho da escrava herdará com o filho da livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Portanto, irmãos, não somos filhos da escrava, mas sim da livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Estai, pois, firmes na liberdade com que Cristo nos libertou, e não volteis a vos prender com o jugo da escravidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Eis que eu, Paulo, vos digo, que se vos deixardes circuncidar, Cristo vos será útil em nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'E de novo atesto que todo homem que se deixar circuncidar está obrigado a obedecer a toda a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Desligados estais de Cristo, vós que quereis ser justos pela Lei; da graça caístes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Pois, por meio do Espírito, pela fé, aguardamos a esperança da justiça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'porque, em Cristo Jesus, nem a circuncisão nem a incircuncisão tem valor algum; mas sim a fé, que opera por meio do amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Estáveis correndo bem; quem vos impediu de obedecerdes à verdade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Esta persuasão não parte daquele que vos chama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Um pouco de fermento leveda toda a massa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Acerca de vós, confio no Senhor de que não mudareis a vossa mentalidade; mas aquele que vos perturba, seja quem for, sofrerá o julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Mas se eu, irmãos, ainda prego a circuncisão, por que, então, sou perseguido? Então a ofensa da cruz está anulada!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Gostaria que aqueles que estão vos perturbando castrassem a si mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Pois vós, irmãos, fostes chamados para a liberdade. Somente não useis a liberdade como oportunidade para a carne; em vez disso, servi-vos uns aos outros pelo amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Pois toda a Lei se cumpre em uma só regra, que é: Amarás ao teu próximo como a ti mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Se, porém, mordeis e devorais uns aos outros, cuidado para não vos destruirdes mutuamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Mas eu digo: andai no Espírito, e não executeis o mau desejo da carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Pois a carne deseja contra o Espírito, e o Espírito contra a carne; e estes se opõem mutuamente, para que não façais o que quereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Mas, se sois guiados pelo Espírito, não estais debaixo da Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'As obras da carne são evidentes. São elas: adultério, pecado sexual, impureza, devassidão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'idolatria, feitiçaria, inimizades, brigas, ciúmes, iras, rivalidades egoístas, desavenças, facções,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'invejas, homicídios, bebedices, orgias, e coisas semelhantes a essas, das quais eu havia vos dito anteriormente; assim como eu também haviavos dito antes que os que praticam tais coisas não herdarão o Reino de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Mas o fruto do Espírito é: amor, alegria, paz, paciência, benignidade, bondade, fidelidade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'mansidão, domínio próprio. Contra essas coisas não há lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Os que são de Cristo crucificaram a carne com as paixões e os maus desejos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Se vivemos no Espírito, também no Espírito andemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Não nos tornemos presunçosos, irritando uns aos outros, e invejando uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Irmãos, se alguém for surpreendido em algum pecado, vós que sois espirituais, restaurai o tal com espírito de mansidão, prestando atenção a ti mesmo, para que também não sejas tentado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Levai as cargas uns dos outros, e assim cumprireis a lei de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Pois, se alguém pensa ser alguma coisa, sendo nada, engana a si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Cada um, porém, examine a sua própria obra, e então terá orgulho em si mesmo sozinho, e não em outro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'pois cada um levará a sua própria carga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Mas aquele que é instruído na palavra compartilhe todas as boas coisas com aquele que o instrui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Não vos enganeis: Deus não se deixa escarnecer; pois, o que o ser humano semear, isso também colherá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Pois quem semear para a sua carne, da carne colherá degradação; mas quem semear para o Espírito, do Espírito colherá a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Porém não cansemos de fazer o bem, pois no tempo devido colheremos, se não desistirmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Portanto, enquanto temos oportunidade, façamos o bem a todos; mas principalmente aos familiares da fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Olhai como são grandes as letras que vos escrevi da minha mão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Todos os que querem mostrar boa aparência na carne, estes vos obrigam a vos circuncidarem, somente para não serem perseguidos por causa da cruz de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Pois nem mesmo os que se circuncidam guardam a Lei; mas querem que vos circuncideis, para se orgulharem de vossa carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Mas longe de mim esteja me orgulhar, a não ser na cruz do nosso Senhor Jesus Cristo; por meio dela, o mundo está crucificado para mim, e eu para o mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Pois em Cristo Jesus, nem a circuncisão tem valor algum, nem a incircuncisão; mas sim a nova criatura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'E todos os que andarem conforme esta regra, paz e misericórdia estejam sobre eles, e sobre o Israel de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'De agora em diante, ninguém me perturbe, porque trago no meu corpo as marcas do Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'A graça do nosso Senhor Jesus Cristo seja com o vosso espírito, irmãos. Amém! Escrita de Roma para os Gálatas');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulo, apóstolo de Jesus Cristo pela vontade de Deus, aos santos que estão em Éfeso, e fiéis em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Graça e paz, de Deus nosso Pai, e do Senhor Jesus Cristo, sejam convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Bendito seja o Deus e Pai do nosso Senhor Jesus Cristo, que nos abençoou com todas as bênçãos espirituis nos lugares celestiais em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Assim como nos escolheu nele antes da fundação do mundo, para que fôssemos santos e irrepreensíveis diante dele em amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'E nos predestinou como filhos adotados por meio de Jesus Cristo para si mesmo, conforme o bom prazer de sua vontade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'para louvor da glória de sua graça, pela qual nos fez aceitáveis no Amado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'Nele temos a libertação pelo seu sangue, o perdão dos pecados, conforme as riquezas da sua graça,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'que ele fez transbordar em nós em toda sabedoria e prudência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'E nos revelou o mistério da sua vontade, conforme o seu bom prazer, que propôs nele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'para a administração do cumprimento dos tempos, isto é, voltar a reunir todas as coisas em Cristo, tanto as que estão nos céus, quanto as que estão na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Nele também fomos feitos herança, havendo sido predestinados conforme o propósito daquele que faz todas as coisas segundo o conselho da sua vontade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'para que fôssemos para louvor da sua glória, nós os que primeiro esperamos em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'E também vós, depois que ouvistes a palavra da verdade, o evangelho da vossa salvação, e nele crestes, nele fostes selados com o Espírito Santo da promessa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'que é a garantia da nossa herança, até a libertação da propriedade de Deus, para louvor da sua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Por isso eu, desde que ouvi da fé que há entre vós no Senhor Jesus, e do amor a todos os santos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'não paro de agradecer a Deus por vós, lembrando-me de vós em minhas orações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Oro para que o Deus de nosso Senhor Jesus Cristo, o Pai glorioso, vos dê o Espírito de sabedoria e de revelação no conhecimento dele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'e que sejam iluminados os olhos do vosso entendimento, para que conheçais qual é a esperança para a qual ele chamou, quais são as riquezas da gloriosa herança dele nos santos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'e qual é a superabundante grandeza do seu poder para nós, que cremos, conforme a operação da sua poderosa força,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'a qual ele operou em Cristo, ressuscitando-o dos mortos; e o colocou à direita dele nos céus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'acima de todo governo, autoridade, poder, domínio, e de todo nome que se nomeia, não só nesta era, mas também na futura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Ele também sujeitou todas as coisas debaixo dos seus pés, e o constituiu por cabeça sobre todas as coisas para a Igreja,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'que é o seu corpo, a plenitude daquele que enche tudo em todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'E vós estáveis mortos em ofensas e pecados,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'nos quais antes andastes conforme o proceder deste mundo, conforme o príncipe do poder do ar, do espírito que agora opera nos filhos da desobediência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Entre esses também todos nós antes andávamos nos desejos da nossa carne, fazendo a vontade da carne e dos pensamentos; e éramos por natureza filhos da ira, como também os outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Mas Deus, que é rico em misericórdia, pelo seu muito amor com que nos amou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'estando nós ainda mortos em nossas ofensas, nos deu vida juntamente com Cristo (pela graça sois salvos),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'nos ressuscitou, juntamente com ele, e nos fez sentar nos lugares celestiais, em Cristo Jesus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'para mostrar nos tempos futuros as abundantes riquezas da sua graça, pela sua bondade conosco em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Porque pela graça sois salvos, por meio da fé; e isto não vem de vós; é dom de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'não por obras, para que ninguém tenha orgulho de si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Pois nós fomos feitos por ele, criados em Cristo Jesus para as boas obras, que Deus preparou para que nelas andássemos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Portanto, lembrai-vos de que vós, antes, éreis gentios na carne, e chamados de não-circuncidados pelos que se chamam participantes da circuncisão na carne, feita por mãos humanas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'que naquele tempo estáveis sem Cristo, excluídos da comunidade de Israel, e estranhos aos pactos da promessa, não tendo esperança, e sem Deus no mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Mas agora em Cristo Jesus, vós que antes estáveis longe, chegastes para perto pelo sangue de Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'pois ele é a nossa paz. Dos dois povos ele fez um, e derrubou do meio o muro da separação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Na sua carne ele desfez a inimizade da Lei dos mandamentos que consistia em ordenanças, para criar em si mesmo os dois em um novo homem, fazendo a paz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'e pela cruz reconciliar com Deus a ambos num só corpo, matando nela a inimizade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Ele veio, e proclamou o evangelho da paz a vós que estáveis longe, e aos que estavam perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Pois por meio dele ambos temos acesso ao Pai por um mesmo Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Portanto, já não sois estrangeiros, nem forasteiros, mas sim, concidadãos dos santos, e membros da família de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'edificados sobre o fundamento dos apóstolos e dos profetas, do qual Jesus Cristo é a pedra principal da esquina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Nele o edifício todo, bem ajustado, cresce para ser um templo santo no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Nele também vós sois juntamente edificados para serdes morada de Deus em Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Por isso eu, Paulo, sou prisioneiro de Cristo Jesus, para o benefício de vós, gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Se é que já ouvistes da responsabilidade acerca da graça de Deus, que me foi dada para vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'que por revelação me foi dado a conhecer este mistério (conforme já vos escrevi um pouco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'quando o ledes, podeis entender o meu entendimento deste mistério de Cristo).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Esse mistério em outras gerações não foi dado a conhecer aos seres humanos, como agora foi revelado pelo Espírito aos seus santos apóstolos e profetas:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'isto é, que os gentios são conjuntamente herdeiros, membros de um mesmo corpo, e participantes da sua promessa em Cristo por meio do evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Eu fui feito servidor desse evangelho conforme o dom da graça de Deus, que me foi dada segundo a operação do seu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'A mim, o menor de todos os santos, foi dada esta graça de anunciar entre os gentios, por meio do Evangelho, as inimagináveis riquezas de Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'E para esclarecer a todos qual é a comunhão do mistério que desde as eras passadas esteve oculto em Deus, que criou todas as coisas por meio de Jesus Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'para que a multiforme sabedoria de Deus seja agora manifestada pela igreja aos domínios e autoridades nos lugares celestes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'conforme o eterno propósito que ele cumpriu em Cristo Jesus, nosso Senhor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'no qual temos coragem e acesso confiante pela fé nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Portanto, eu vos peço que não vos desanimeis em minhas aflições por vós. Elas são a vossa glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Por causa disso me ponho de joelhos diante do Pai do nosso Senhor Jesus Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'do qual toda a família nos céus e na terra recebe nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Oro para que, conforme a sua riquíssima glória, ele vos conceda que sejais fortalecidos com poder pelo seu Espírito no interior de cada um,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'para que Cristo habite em vossos corações pela fé. Oro para que vós estejais enraizados e firmados no amor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'e assim possais compreender, com todos os santos, qual é a largura, comprimento, profundidade, e altura,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'e conhecer o amor de Cristo, que excede o entendimento, para que sejais cheios de toda a plenitude de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'E quanto àquele que é poderoso para fazer tudo muito mais abundantemente do que pedimos ou pensamos, segundo o poder que opera em nós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'a ele seja a glória na Igreja, em Cristo Jesus, por todas as gerações para todo o sempre, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Portanto, eu, o prisioneiro no Senhor, rogo-vos que andeis como é digno do chamado com que fostes chamados,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'com toda humildade e mansidão; com paciência, tolerando uns aos outros em amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Procurai guardar a unidade do Espírito pelo vínculo da paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Há um só corpo, e um só Espírito, como também fostes chamados em uma só esperança do vosso chamado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Um só Senhor, uma só fé, um só batismo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'um só Deus, e Pai de todos, que é acima de todos, por meio de todos, e em todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Mas a graça foi dada a cada um de nós conforme a medida do dom de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Por isso diz: Quando ele subiu ao alto, levou cativo o cativeiro, e deu dons às pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '(O que significa este “ele subiu”, senão que ele também antes tinha descido às partes mais baixas da terra?)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Aquele que desceu é também o mesmo que subiu muito acima de todos os céus, para preencher todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'E ele mesmo deu uns como apóstolos, outros como profetas outros como evangelistas, e outros como pastores e instrutores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'para o aperfeiçoamento dos santos, para a obra do serviço, para a edificação do corpo de Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'até que todos cheguemos à unidade da fé e do conhecimento do Filho de Deus, à maturidade, à medida da estatura da plenitude de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'O fim disso é que não mais sejamos crianças inconstantes, levadas de um lado para outro por todo vento de doutrina, pelo engano dos pessoas que, para enganar, usam de fraudes com astúcia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Pelo contrário, sigamos a verdade em amor, e cresçamos em tudo naquele que é a cabeça: Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'É dele que todo o corpo, bem ajustado e unido por todos os ligamentos, conforme a operação de cada parte na medida devida, proporciona o crescimento do corpo, para a sua própria edificação em amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Portanto digo isso, e dou testemunho no Senhor, que não andeis mais como os outros gentios andam, na futilidade das suas mentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Esses têm o entendimento nas trevas, e estão separados da vida de Deus pela ignorância que há neles, pela dureza do seu coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Como se tornaram insensíveis, eles se entregaram à sensualidade, para cometerem com avidez toda impureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mas não foi assim que vós aprendestes de Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'se é que o ouvistes, e fostes ensinados nele, como a verdade está em Jesus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'quanto ao comportamento passado, que deveis abandonar o velho ser humano, que se corrompe pelos maus desejos de engano;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'que deveis vos renovar no espírito da vossa mente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'e que deveis vos revestir do novo ser humano, que é criado conforme Deus na verdadeira justiça e santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Portanto, abandonai a mentira, e falai a verdade cada um ao seu próximo; pois somos membros uns dos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Quando irardes, não pequeis; o sol não se ponha sobre a vossa ira;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'nem deis lugar ao diabo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'O que furtava, não furte mais; em vez disso, trabalhe, operando com as mãos o bem, para que tenha o que repartir com o que tiver necessidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Não saia de vossa boca palavra imoral; mas sim a boa para a edificação conforme a necessidade; para que comunique graça aos que a ouvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'E não entristeçais o Espírito Santo de Deus, no qual fostes selados para o dia da libertação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Toda amargura, raiva, ira, gritaria, e maledicência sejam tiradas do meio de vós, assim como toda malícia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Em vez disso, sede benignos uns com os outros, misericordiosos, perdoando-vos uns aos outros, como também Deus vos perdoou em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Portanto, sede imitadores de Deus, como filhos amados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'e andai em amor, como também Cristo nos amou, e se entregou por nós como oferta e sacrifício de cheiro suave a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Mas o pecado sexual, e toda impureza ou cobiça, nem mesmo se nomeie entre vós, como convém a santos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'nem imoralidades, nem palavras tolas, nem escárnios, que não convêm; em vez disso, atos de gratidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Pois sabeis disto, que nenhum pecador no sexo, ou impuro, ou ganancioso, que é idólatra, tem herança no reino de Cristo e de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Ninguém vos engane com palavras vazias; pois por essas coisas a ira de Deus vem sobre os filhos da desobediência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Portanto não sejais parceiros deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Pois antes vós éreis trevas, mas agora sois luz no Senhor; andai como filhos da luz');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(porque o fruto do Espírito consiste em toda bondade, justiça, e verdade),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'buscando descobrir o que agrada ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'E não participeis das obras infrutíferas das trevas, pelo contrário, reprovai-as.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'pois é vergonhoso até dizer o que eles fazem em segredo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Mas todas essas coisas, quando são reprovadas, tornam-se visíveis pela luz, porque tudo o que se se torna visível é luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Por isso se diz: Desperta tu, que dormes, e levanta-te dos mortos, e Cristo te iluminará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Portanto vede cuidadosamente como vos conduzis, não como tolos, mas sim como sábios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'aproveitai o tempo, porque os dias são maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Por isso, não sejais imprudentes, mas entendei qual é a vontade do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'E não fiqueis bêbados com vinho, em que há devassidão, mas enchei-vos do Espírito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'falando entre vós com salmos, hinos e cânticos espirituais; cantando e louvando ao Senhor no vosso coração;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'agradecendo sempre por tudo a Deus, o Pai, no nome do nosso Senhor Jesus Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'sujeitando-vos uns aos outros no temor a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Mulheres, sujeitai-vos aos vossos próprios maridos, assim como ao Senhor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'porque o marido é o cabeça da mulher, como também Cristo é o cabeça da Igreja, e ele é o salvador do corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Mas, assim como a Igreja está sujeita a Cristo, assim também as mulheres estejam em tudo sujeitas aos seus próprios maridos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Maridos, amai as vossas próprias esposas, assim como também Cristo amou a Igreja, e se entregou por ela;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'a fim de a santificar, havendo a purificado com a lavagem com água, pela palavra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'a fim de apresentar a si mesmo uma igreja gloriosa, sem mancha, nem ruga, nem algo semelhante; mas sim, santa e irrepreensível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Assim os maridos devem amar as suas próprias esposas como os seus próprios corpos. Quem ama a sua esposa, ama a si mesmo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'pois ninguém jamais odiou a sua própria carne; mas a alimenta e sustenta, assim como também o Senhor à Igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'pois somos membros de seu corpo, da sua carne, e dos seus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Por isso o homem deixará oseu pai e a sua mãe, e se ajuntará com a sua mulher; e os dois serão uma só carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Esse é um grande mistério, mas estou dizendo quanto a Cristo e à Igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Assim também vós, cada um individualmente, ame a sua própria esposa como a si mesmo, e a mulher respeite o marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Filhos, sede obedientes aos vossos pais no Senhor, porque isso é justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Honra teu pai, e tua mãe (que é o primeiro mandamento com promessa);');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'para que te vá bem, e vivas muito tempo sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Pais, não provoqueis à ira os vossos filhos, mas criai-os na disciplina e correção do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Servos, obedecei aos vossos senhores segundo a carne, com temor e tremor, em sinceridade do vosso coração, assim como a Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'não servindo somente quando vistos, como para agradar pessoas; mas sim, como servos de Cristo, fazendo de coração a vontade de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'servindo de boa vontade como ao Senhor, e não aos pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Pois sabeis que cada um receberá do Senhor todo o bem que fizer, seja servo, seja livre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Senhores, fazei o mesmo a eles, abandonando as ameaças, pois sabeis também que o Senhor vosso e deles está nos céus, e que com ele não há acepção de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Por fim, meus irmãos, fortalecei-vos no Senhor e na força do seu poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Revesti-vos de toda a armadura de Deus, para que possais estar firmes contra as ciladas do diabo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Pois temos de lutar não contra carne e sangue, mas sim contra os domínios e poderes, contra os senhores das trevas deste mundo, contra os males espirituais nos lugares celestes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Portanto pegai toda a armadura de Deus, para que possais resistir no dia mal, e depois que fizerdes tudo, continuar firmes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Estai, pois, firmes, com a vossa cintura envolvida com o cinturão da verdade, e vestidos com a couraça da justiça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'e calçados os pés com a prontidão do evangelho da paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Sobretudo pegai o escudo da fé, com o qual podereis apagar todas as flechas inflamadas do maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Pegai também o capacete da salvação, e a espada do Espírito, que é a palavra de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'orando em todo tempo com toda oração e súplica no Espírito, e vigiando nisso com toda perseverança e súplica por todos os santos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'e por mim; a fim de que, quando eu abrir a boca, me seja dada palavra com ousadia, para tornar conhecido o mistério do evangelho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'pelo qual sou embaixador acorrentado; para que dele eu possa falar com ousadia, como devo falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Para que também vós possais saber o que acontece comigo, e o que eu faço, Tíquico, o irmão amado, e fiel servidor do Senhor vos informará de tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Eu o enviei até vós para isso, para que saibais o que acontece conosco, e ele conforte os vossos corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Paz seja com os irmãos, e amor com fé, da parte de Deus Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'A graça seja com todos os que amam ao nosso Senhor Jesus Cristo com amor que não falha. Amém! Escrita de Roma para os efésios, e enviada por Tíquico');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulo e Timóteo, servos de Jesus Cristo, a todos os santos em Cristo Jesus, que estão em Filipos, com os supervisores e servidores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Haja convosco a graça e paz de Deus nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Agradeço ao meu Deus todas as vezes que me lembro de vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'sempre em todas as minhas orações, com alegria, fazendo oração por todos vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'por causa da vossa cooperação com o Evangelho desde o primeiro dia até agora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'E disto tenho certeza: aquele que começou a boa obra em vós irá completá-la até o dia de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Para mim é justo eu sentir isso de todos vós, pois vos tenho no coração, porque todos vós sois participantes comigo da graça, tanto nas minhas prisões, como na defesa e confirmação do Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Pois Deus é minha testemunha de como sinto saudades de todos vós, com o afeto de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'E isto oro: que o vosso amor seja mais e mais abundante em conhecimento e em toda percepção,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'para que aproveis as melhores coisas, a fim de que sejais sinceros, sem ofensa, até o dia de Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'cheios dos frutos da justiça, que, por meio de Jesus Cristo, são para glória e louvor a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Mas quero, irmãos, que saibais que as coisas me aconteceram foram para o avanço do Evangelho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'de maneira que se tornou evidente a toda a guarda pretoriana, e a todos os demais, que as minhas prisões são em Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'e que a maioria dos irmãos no Senhor, depois de ganharem confiança com as minhas prisões, ousam falar a Palavra muito mais, sem medo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'É verdade que também alguns pregam a Cristo por inveja e rivalidade, porém outros, também, de boa vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Uns em verdade anunciam a Cristo por rivalidade egoísta, não sinceramente, supondo que irão acrescentar aflição às minhas prisões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Mas outros anunciam por amor, sabendo que fui posto para a defesa do Evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Que, pois? Afinal de qualquer maneira, ou com fingimento, ou em verdade, Cristo é anunciado; e nisto me alegro, e continuarei a me alegrar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'pois sei que isso me resultará em livramento pela vossa oração e pelo socorro do Espírito de Jesus Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'conforme a minha intensa expectativa e esperança, de que em nada me envergonharei. Ao contrário, com toda a confiança, como sempre, assim também agora Cristo será engrandecido no meu corpo, seja pela vida, seja pela morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Pois, para mim, o viver é Cristo, e o morrer é lucro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Mas, se este viver na carne for o fruto do meu trabalho, então não sei o que prefiro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'pois estou pressionado por ambos os lados: tenho desejo de ser desligado, e estar com Cristo, o que é muito melhor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'entretanto, ficar na carne é mais necessário por causa de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'E nisto confio e sei, que ficarei, e continuarei com todos vós, para que avanceis, e vos alegreis na fé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'a fim de que a vossa alegria em Cristo Jesus seja abundante, por causa de mim, através da minha presença, de volta, convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Tão somente procedei de maneira digna do Evangelho de Cristo, para que, seja quando eu venha e vos veja, seja ausente, ouça a vosso respeito de que estais num mesmo espírito, com um mesmo ânimo, combatendo juntos pela fé do Evangelho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'e que em nada vos amedronteis pelos adversários, o que para eles é, de fato, indício de perdição, mas para vós de salvação, e isso vem de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Pois vos foi dado gratuitamente, quanto a Cristo, não somente o crer nele, mas também o sofrer por ele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'de maneira que tendes o mesmo combate, que vistes em mim, e agora de mim ouvis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Portanto, se há alguma consolação em Cristo, se há algum conforto de amor, se há alguma comunhão do Espírito, se há afetos e compaixões,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'completai a minha alegria: que penseis da mesma maneira, tenhais o mesmo amor, sejais unidos de ânimo, tendo um mesmo modo de pensar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Nada façais por rivalidade egoísta ou por vanglória; ao contrário, por humildade cada um considere o outro superior a si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Cada um não cuide somente do que é seu; mas cada um cuide também do que é dos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Isto seja, para que esteja em vós este modo de pensar, que também esteve em Cristo Jesus:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'mesmo ele sendo em forma de Deus, não considerou a igualdade a Deus como algo para se obter vantagem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Ao contrário, ele esvaziou a si mesmo, tomando a forma de servo, e se tornou semelhante aos homens;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'e, quando se encontrava em forma humana, ele humilhou a si mesmo, sendo obediente até a morte, e morte de cruz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Por isso Deus também o exaltou supremamente, e lhe deu um nome que é acima de todo nome;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'a fim de que no nome de Jesus se dobre todo joelho dos que estão nos céus, na terra, e debaixo da terra,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'e toda língua confesse que Jesus Cristo é o Senhor, para a glória de Deus Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Portanto, meus amados, assim como sempre obedecestes, não somente na minha presença, mas muito mais agora em minha ausência, assim exercei a vossa salvação com temor e tremor;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'pois é Deus quem opera em vós tanto o querer como o agir, conforme a sua boa vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Fazei tudo sem murmurações nem brigas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'para que sejais irrepreensíveis e puros, filhos de Deus, inculpáveis no meio de uma geração corrupta e perversa, na qual brilhais como luminárias no mundo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'e mantende a palavra da vida, para que no dia de Cristo eu possa me orgulhar de que não tenho corrido nem trabalhado em vão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Mesmo se eu for derramado como oferta sobre o sacrifício e serviço vossa fé, alegro-me e contento-me com todos vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'e, pelo mesmo motivo, alegrai-vos e contentai-vos comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Tenho esperança no Senhor Jesus de em breve vos enviar Timóteo, para que também eu me anime quando souber notícias de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Pois não tenho ninguém de mesmo ânimo que se importe sinceramente convosco,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'pois todos buscam as suas próprias coisas, e não as de Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Mas vós sabeis a prova que ele passou, porque serviu comigo no Evangelho como um filho ao pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Assim, pois, espero enviá-lo, tão logo eu veja o que há de haver comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Mas confio no Senhor de que também eu mesmo virei em breve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Julguei necessário, porém, enviar-vos Epafrodito, meu irmão, cooperador, e companheiro de batalha, mensageiro enviado por vós, e auxiliador naquilo que necessito;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'porque ele tinha muitas saudades de todos vós, e estava muito angustiado por haverdes ouvido de que ele havia ficado doente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'E ele ficou mesmo doente, quase a morrer; mas o Deus dele teve misericórdia, não somente dele, mas também de mim, para que eu não tivesse tristeza após tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Por isso eu o enviei mais depressa, a fim de que, vendo-o de novo, alegrei-vos e eu fique menos triste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Recebei-o, pois, no Senhor, com toda alegria; e honrai ao que são como ele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'pois, por causa da obra de Cristo, ele chegou perto da morte, arriscando a sua própria vida para suprir em meu benefício a falta do vosso serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'No restante, meus irmãos, alegrai-vos no Senhor. Não me é incômodo escrever as mesmas coisas, e isso é para a vossa segurança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Cuidado com os cães! Cuidado com os que operam o mal! Cuidado com a mutilação!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Pois a circuncisão somos nós, que servimos a Deus pelo Espírito, orgulhamo-nos em Cristo Jesus, e não confiamos na carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Embora eu também tenho como confiar na carne. Se outro alguém pensa que pode confiar na carne, ainda mais eu:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'circuncidado ao oitavo dia, da descendência de Israel, da tribo de Benjamim, hebreu de hebreus; segundo a lei, fariseu;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'segundo o zelo, perseguidor da Igreja; segundo a justiça que há na lei, irrepreensível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mas o que para mim era ganho considerei como perda, por causa de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'E, na verdade, considero também todas as coisas como perda, por causa da superioridade de conhecer a Cristo Jesus, meu Senhor. Por ele aceitei perder todas essas coisas, e as considero como dejetos, a fim de que eu possa ganhar a Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'e que eu seja achado nele, não tendo a minha justiça proveniente da Lei, mas sim a que é pela fé em Cristo, a justiça da parte de Deus pela fé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'para eu conhecer a ele, assim como o poder de sua ressurreição e a comunhão em seus sofrimentos, tornando-me conforme a ele em sua morte;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'para que, de alguma maneira, eu alcance a ressurreição dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Não que eu já a tenha obtido, ou que já seja perfeito; mas sigo a fim de alcançar aquilo para o qual eu também fui alcançado por Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Irmãos, não considero como se já tivesse a obtido; mas uma coisa faço: esqueço as coisas que ficam para trás, e avanço para as que estão adiante,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'e assim persigo o alvo, rumo ao prêmio do chamado de cima, de Deus em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Por isso, todos nós que somos maduros, tenhamos essa mesma mentalidade; e se em algo pensais de maneira diferente, Deus também vos revelará isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Porém, naquilo a que já chegamos, andemos conforme a mesma regra, e tenhamos a mesma mentalidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Sede meus imitadores, irmãos, e observai atentamente os que assim andam, como o exemplo que tendes em nós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'pois, como muitas vezes eu vos disse, e agora também digo chorando, muitos andam como inimigos da cruz de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'O fim deles é a perdição. O Deus deles é o ventre, e têm orgulho do que deviam se envergonhar. Eles se importam mais com as coisas terrenas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Mas nós somos cidadãos dos céus, de onde também esperamos um Salvador, o Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Ele transformará o nosso degradante corpo, para que seja conforme o seu corpo glorioso, segundo a operação do seu poder de sujeitar para si todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Portanto, meus amados e queridos irmãos, minha alegria e coroa, permanecei assim, firmes no Senhor, amados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Rogo a Evódia e rogo a Síntique que tenham uma mesma mentalidade no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Peço também de ti, verdadeiro companheiro, que ajude a essas que lutaram no Evangelho comigo, como também com Clemente, e com os demais cooperadores, cujos nomes estão no livro da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Alegrai-vos sempre no Senhor. Volto a dizer: alegrai-vos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'A vossa bondade seja conhecida por todas as pessoas. Perto está o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Não estejais ansiosos por coisa alguma; mas em tudo, por meio de orações e súplicas com ações de gratidão, sejam os vossos pedidos conhecidos por Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'e a paz de Deus, que excede todo entendimento, guardará os vossos corações e as vossas mentes em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'No restante, meus irmãos, tudo o que é verdadeiro, tudo o que é respeitável, tudo o que é justo, tudo o que é puro, tudo o que é amável, tudo o que é de boa fama, se há alguma virtude, e se há algo digno de elogio, nisto pensai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'O que também aprendestes, recebestes, ouvistes, e vistes em mim, isso fazei; e o Deus da paz será convosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Alegrei-me muito no Senhor de que finalmente voltastes a vos lembrardes de mim; aliás, já estáveis lembrando, porém não tínheis oportunidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Não digo isso por causa de alguma necessidade, pois já aprendi a contentar-me com o que tenho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Sei estar humilhado, e sei ter em abundância; em toda maneira e em todas as coisas estou instruído, tanto a estar farto, como a ter fome; tanto a ter em abundância, como a sofrer necessidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Posso todas as coisas em Cristo que me fortalece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Todavia, fizestes bem em compartilhardes da minha aflição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'E também vós, filipenses, sabeis que, no princípio do evangelho, quando parti da Macedônia, nenhuma igreja compartilhou comigo no dar e no receber, a não ser vós somente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'pois até em Tessalônica por uma e duas vezes me enviastes o que eu necessitava.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Não que eu busque doações, mas busco o fruto que aumente o crédito de vossa conta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Mas de tudo tenho recebido, e tenho em abundância; estou plenamente abastecido, depois que recebi de Epafrodito o que de vossa parte me foi enviado,como cheiro suave, e sacrifício aceitável e agradável a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'E meu Deus suprirá todas a vossas necessidades segundo as suas riquezas em glória em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Ao nosso Deus e Pai seja a glória para todo o sempre, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Saudai a todos os santos em Cristo Jesus. Os irmãos que estão comigo vos saúdam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Todos os santos vos saúdam, mas principalmente os da casa de César.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'A graça do nosso Senhor Jesus Cristo esteja com todos vós. Amém! Para os filipenses. Escrita de Roma, enviada por Epafrodito');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulo, apóstolo de Jesus Cristo pela vontade de Deus, e o irmão Timóteo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'aos santos e fiéis irmãos em Cristo, que estão em Colossos. Haja em vós a graça e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Agradecemos ao Deus e Pai do nosso Senhor Jesus Cristo, sempre orando por vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'pois ouvimos falar da vossa fé em Cristo Jesus, e do amor que tendes para com todos os santos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'por causa da esperança que está reservada para vós nos céus. Anteriormente ouvistes dessa esperança pala palavra da verdade do evangelho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'que já chegou a vós, como também em todo o mundo; e vai frutificando assim como entre vós, desde o dia em que ouvistes e conhecestes a graça de Deus em verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Aprendestes o evangelho por Epafras, nosso amado cooperador, que é um fiel servidor de Cristo em vosso favor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Ele também nos declarou o vosso amor no Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Por isso também, desde o dia que o ouvimos, não paramos de orar por vós, e de pedir que sejais cheios do conhecimento da sua vontade, em toda sabedoria e entendimento espiritual;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'para que possais andar dignamente diante do Senhor, agradando-lhe em tudo, frutificando em toda boa obra, e crescendo no conhecimento de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'capacitados em todo fortalecimento, segundo o poder da sua glória, em toda perseverança e paciência com alegria,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'agradecendo ao Pai, que nos capacitou a participar da herança dos santos na luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Ele nos tirou do domínio das trevas, e nos transportou para o reino do seu amado Filho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'em quem temos a libertação pelo seu sangue: o perdão dos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Ele é a imagem do Deus invisível, o primogênito de toda a criação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'porque nele foram criadas todas as coisas que há nos céus e na terra, visíveis e invisíveis, sejam tronos, sejam domínios, sejam governos, sejam autoridades; todas as coisas foram criadas por ele e para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Ele existe antes de todas as coisas, e nele todas as coisas se mantêm.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'E ele é a cabeça do corpo, da Igreja; ele é o princípio e o primogênito dentre os mortos, para que tenha a primazia entre todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Pois foi do agrado do Pai que toda a plenitude habitasse nele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'e, havendo por ele feito a paz pelo sangue da sua cruz, por meio dele reconciliasse consigo mesmo todas as coisas, tanto as que estão na terra, como as que estão nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Vós éreis separados dele, e inimigos no entendimento, em más obras. Porém agora ele vos reconciliou,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'no seu corpo de carne, pela morte, para vos apresentar diante dele santos, irrepreensíveis e inculpáveis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'se, de fato, permaneceis fundados e firmes na fé, e não vos afastais da esperança do evangelho que ouvistes, que é pregado a toda criatura que há abaixo do céu, e do qual eu, Paulo, fui feito servidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Agora me alegro nos meus sofrimentos por vós, e cumpro na minha carne o restante das aflições de Cristo, em benefício do seu corpo, que é a Igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Dela eu fui feito servidor segundo a responsabilidade da parte de Deus que me foi dada para o vosso benefício, a fim de cumprir a palavra de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'o mistério que estava oculto desde os princípios dos tempos e das gerações; mas agora foi manifesto aos seus santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'A eles Deus quis fazer que conhecessem as riquezas da glória deste mistério entre os gentios, que é Cristo em vós, a esperança da glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Ele é quem anunciamos, advertindo a toda pessoa, e ensinando a toda pessoa, com toda sabedoria; a fim de que apresentemos toda pessoa como completa em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Para isso eu também trabalho, lutando conforme a eficácia dele, que age em mim com poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Pois quero que saibais como é grande a luta que tenho para o benefício de vós, dos que estão em Laodiceia, e de tantos quantos não viram meu rosto fisicamente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'para que os seus corações sejam consolados, e estejam unidos em amor, e em todas as riquezas da pleno entendimento, para conhecimento do mistério de Deus, e do Pai, e de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Nele estão ocultos todos os tesouros da sabedoria e do conhecimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Digo isso para que ninguém vos engane com palavras persuasivas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Pois ainda que esteja ausente em corpo, todavia em espírito estou convosco, alegrando-me, e vendo a vossa ordem e a firmeza de vossa fé em Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Portanto, assim como recebestes Cristo Jesus, o Senhor, assim também andai nele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'com raízes firmes e edificados nele, e confirmados na fé, como fostes ensinados, abundando nela com gratidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Cuidado que ninguém vos tome cativos por meio de filosofias e de enganos vãos, conforme a tradição humana, conforme os elementos do mundo, e não conforme Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Pois nele habita corporalmente toda a plenitude da divindade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'E vós vos tornais plenos nele, que é o cabeça de todo governo e autoridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'Nele também fostes circuncidados com uma circuncisão não feita por mãos, mas sim, no abandono do corpo dos pecados da carne, pela circuncisão de Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'sepultados com ele no batismo, no qual também com ele fostes ressuscitados pela fé no poder de Deus, que o ressuscitou dos mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'E quando vós estáveis mortos em pecados, na incircuncisão da vossa carne, Deus vos deu vida juntamente com ele, perdoando-vos todas as ofensas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Ele riscou a certidão de nossa dívida em ordenanças, a qual era contra nós, e a removeu, cravando-a na cruz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'ele despojou os domínios e autoridades, publicamente os envergonhou, e nela triunfou sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Portanto, ninguém vos julgue pelo comer, ou pelo beber, ou por causa de celebração religiosa, ou pela lua nova, ou pelos sábados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'essas coisas são a sombra das coisas futuras, mas a realidade pertence a Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Ninguém, pois, se faça de juiz contra vós, insistindo nos pretextos de “humildade” e de “culto aos anjos”, envolvendo-se em coisas que nunca viu, vangloriando-se em sua mentalidade carnal,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'e não se ligando à cabeça, da qual todo o corpo, suprido e organizado pelas juntas e ligamentos, vai crescendo com o crescimento da parte de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Portanto, se estais mortos com Cristo para os elementos do mundo, por que vos sujeitais a ordenanças como se vivêsseis no mundo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'tais como: “não pegues”, “não proves”, “não toques”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Todas elas se acabam com o uso, e se baseiam em mandamentos e doutrinas humanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Elas realmente têm aparência de sabedoria em culto voluntário, humildade, e tratamento severo ao corpo; mas não têm valor algum contra a satisfação da carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Portanto, se fostes ressuscitados com Cristo, buscai as coisas de cima, onde Cristo está sentado à direita de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Pensai nas coisas de cima, não nas que estão na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Pois já morrestes, e a vossa vida está escondida com Cristo em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Quando Cristo, que é a nossa vida, se manifestar, então também vós vos manifestareis com ele em glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Portanto, mortificai as partes carnais que há em vós que são terrenas; são elas: o pecado sexual, a impureza, a paixão depravada, o desejo maligno, e a ganância, que é idolatria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Por causa delas que a ira de Deus vem sobre os filhos da desobediência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Nessas coisas também vós andastes antes, quando vivíeis nelas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Mas agora, abandonai, vós também, todas estas coisas: a ira, a fúria, a malícia, a maledicência, e as palavras vergonhosas da vossa boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Não mintais uns aos outros, pois já vos despistes do velho ser humano com os seus costumes,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'e vos revestistes do novo, que se renova em conhecimento, conforme a imagem daquele que o criou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Nisso não há grego, nem judeu, nem circunciso, nem incircunciso, bárbaro, cita, escravo, nem livre; mas Cristo é tudo, e em todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Por isso, como escolhidos de Deus, santos e amados, revesti-vos de sentimentos de misericórdia, bondade, humildade, mansidão, e paciência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Suportai-vos uns aos outros, e perdoai-vos uns aos outros, se alguém tiver queixa contra outro. Como Cristo vos perdoou, assim também fazei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'E acima de tudo isto, revesti-vos do amor, que é o vínculo da perfeição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'E a paz de Deus, para a qual também fostes chamados em um só corpo, governe em vossos corações, e sede gratos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'A palavra de Cristo habite abundantemente em vós com toda sabedoria, ensinando-vos e advertindo-vos uns aos outros; e cantai ao Senhor com salmos, hinos, e cânticos espirituais, com graça no vosso coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'E tudo quanto fizerdes, por palavras ou por obras, fazei tudo no nome do Senhor Jesus, dando por meio dele graças ao Deus e Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Mulheres, sede submissas aos vossos próprios maridos, como convém no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Maridos, amai às esposas, e não as trateis amargamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Filhos, obedecei em tudo aos pais, porque isso é agradável ao Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Pais, não provoqueis aos vossos filhos, para que não percam o ânimo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Escravos, obedecei em tudo aos vossos senhores segundo a carne, não servindo apenas quando observados, como que para satisfazer às pessoas, mas sim, com sinceridade de coração, temendo a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'E tudo quanto fizerdes, fazei de coração, como que para o Senhor, e não para as pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Pois sabeis que recebereis do Senhor a recompensa da herança, porque servis ao Senhor Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Mas aquele que fizer injustiça receberá conforme a injustiça que cometer; e não há acepção de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Senhores, procedei de maneira justa e imparcial com os vossos servos, sabendo que também vós tendes um Senhor nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Perseverai na oração, vigiando nela com gratidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Orai também ao mesmo tempo por nós, para que Deus nos abra uma porta para a palavra, para que falemos do mistério de Cristo, mistério pelo qual estou preso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Para que eu o anuncie claramente, como devo falar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Convivei com sabedoria com os que estão de fora, aproveitando o tempo oportuno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'A vossa palavra seja sempre com graça, temperada com sal, para que saibais como deveis responder a cada um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Tíquico, irmão amado, fiel trabalhador e colaborador no Senhor, vos fará saber tudo o que vem acontecendo comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Foi para isso que eu o enviei até vós, para que saiba como estais, e console os vossos corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Juntamente com ele está Onésimo, irmão fiel e amado, que é um de vós. Eles vos farão saber tudo o que está havendo por aqui.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarco, que está preso comigo, vos saúda; e também Marcos, primo de Barnabé. Acerca dele, já recebestes ordens; se ele for até vós, recebei-o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'E também Jesus, chamado Justo. Dentre os circuncisos, esses são os únicos cooperadores meus no Reino de Deus, e têm sido consolação para mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Epafras, que é um de vós, servo de Cristo, vos saúda. Ele sempre luta por vós em orações, para que fiqueis íntegros e plenos em toda a vontade de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Pois dou testemunho dele de que ele tem grande zelo por vós, pelos que estão em Laodiceia, e pelos que estão em Hierápolis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Lucas, o médico amado, vos saúda; e também Demas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Saudai aos irmãos que estão em Laodiceia, e também a Ninfas, e à igreja que está na casa dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'E depois que esta carta for lida entre vós, fazei que ela também seja lida na igreja dos laodicenses, e que vós leiais também a de Laodiceia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'E dizei a Árquipo: Presta atenção ao trabalho que recebeste do Senhor, para que o cumpras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Esta saudação é da minha mão, de Paulo. Lembrai-vos das minhas prisões. A graça esteja convosco. Amém. (Escrita de Roma aos colossenses, e enviada por Tíquico e Onésimo.)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulo, Silvano, e Timóteo, à igreja dos tessalonicenses, em Deus Pai, e no Senhor Jesus Cristo; haja convosco a graça e a paz de Deus, nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Sempre damos graças a Deus por todos vós, fazendo menção de vós em nossas orações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'E, diante do nosso Deus e Pai, nós nos lembramos sem cessar da obra da vossa fé, do trabalho do amor, e da firmeza da esperança no nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Sabemos, irmãos amados por Deus, que por ele fostes escolhidos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'pois o nosso evangelho não foi até vós somente com palavras, mas também com poder, com o Espírito Santo, e com plena certeza; assim como sabeis de que maneira estivemos entre vós para o vosso benefício.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'E vos tornastes imitadores nossos e do Senhor. Mesmo em meio a muita aflição, recebestes a palavra com a alegria do Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Dessa maneira vos tornastes referências a todos os crentes na Macedônia e Acaia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Pois de vós ressoou a palavra do Senhor, não somente na Macedônia e Acaia, mas a vossa fé em Deus também se espalhou em todo lugar, de tal maneira que não precisamos falar coisa alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Pois eles mesmos anunciam como fomos recebidos por vós, e como vos convertestes, deixando os ídolos, para servir ao Deus vivo e verdadeiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'e para esperar dos céus o seu Filho, a quem ele ressuscitou dos mortos: Jesus, que nos livra da ira futura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Pois vós mesmos, irmãos, sabeis que a nossa passagem por entre vós não foi inútil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Porém, mesmo que antes, em Filipos, tenhamos sofrido e sido maltratados, como sabeis, tivemos no nosso Deus ousadia para vos falar o evangelho de Deus em meio a muita oposição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Pois a nossa exortação não foi com engano, nem com impureza, nem fraude;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'mas, como fomos aprovados por Deus para que o evangelho nos fosse confiado, assim falamos; não para agradar as pessoas, mas sim a Deus, que prova os nossos corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Pois, como sabeis, nunca usamos palavras de lisonja, nem pretexto de ganância; Deus é testemunha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Não buscamos a glória humana, nem de vós, nem de outros, ainda que tínhamos autoridade, como apóstolos de Cristo, para demandar de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Porém fomos suaves entre vós, como uma mãe que dá carinho aos seus filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Assim nós, tendo tanta afeição por vós, queríamos de boa vontade compartilhar convosco não somente o evangelho de Deus, mas também as nossas próprias almas, porque éreis queridos por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Pois vos lembrais, irmãos, do nosso trabalho e fadiga; porque enquanto vos pregávamos o evangelho de Deus, trabalhávamos noite e dia para que não fôssemos um peso para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vós e Deus sois testemunhas de como foi santa, justa, e irrepreensível a maneira da qual nos comportamos convosco, que credes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Assim como sabeis que, como um pai aos seus filhos, exortávamos, consolávamos, e testemunhávamos a cada um de vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'para que andásseis de maneira digna diante de Deus, que vos chama para o seu reino e glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Por isso também agradecemos sem cessar a Deus, que, quando recebestes a palavra da Deus pregada por nós, a recebestes, não como palavra de homens, mas (conforme em verdade é) como a palavra de Deus, a qual também opera em vós, que credes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Pois vós, irmãos, vos tornastes imitadores das igrejas de Deus que estão na Judeia em Cristo Jesus; porque também sofrestes as mesmas coisas dos vossos próprios compatriotas, como também eles dos judeus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'que também mataram o Senhor Jesus e os seus próprios profetas, e nos perseguiram, e não agradam a Deus, e são contrários a todos:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'eles nos impedem de falar aos gentios, para que sejam salvos. Assim eles estão se enchendo constantemente de pecados, mas, por fim, ira veio sobre eles até o fim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Porém, irmãos, quando nos separamos de vós por algum tempo, em presença, não no coração, buscamos mais, com muito desejo, ver o vosso rosto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'por isso quisemos, pelo menos eu, Paulo, vos visitar uma vez e outra; mas Satanás nos impediu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Pois, qual é nossa esperança, alegria, ou coroa de orgulho, diante do nosso Senhor Jesus Cristo na sua vinda? Acaso não sois vós?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Porque vós sois o nosso orgulho e alegria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Por isso, como não podíamos mais suportar, decidimos ficar sozinhos em Atenas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'e enviamos Timóteo, nosso irmão e servidor de Deus, e cooperador nosso no Evangelho de Cristo, para vos fortalecer e vos encorajar quanto a vossa fé;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'a fim de que ninguém se abale por essas aflições; pois vós mesmos sabeis que para isso fomos destinados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Pois quando ainda estávamos convosco vós dizíamos com antecedência que seríamos afligidos, como aconteceu, e vós sabeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Por isso, como não podia mais suportar, eu o enviei para saber de vossa fé. Eu temia que o tentador houvesse vos tentado, e o nosso trabalho houvesse sido inútil.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Mas agora, depois que Timóteo voltou a nós da vossa presença, e nos trouxe boas notícias da vossa fé e amor, e de como sempre tendes boa lembrança de nós, e desejais muito nos ver, como também nós a vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'por isso, irmãos, ficamos consolados acerca de vós em toda a nossa aflição e necessidade, pela vossa fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Pois agora vivemos, se vós estais firmes no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Pois como agradecemos a Deus por vós, por toda a alegria com que nos alegramos por vossa causa, diante do nosso Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'E de noite e de dia com extrema intensidade oramos para que possamos ver o vosso rosto, e supramos o que falta na vossa fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'E que o mesmo Deus, nosso Pai, e o nosso Senhor Jesus Cristo, preparem o nosso caminho até vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'E o Senhor vos faça crescer e exceder em amor uns pelos outros, e por todos, à semelhança de nós por vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'a fim de que fortaleça os vossos corações, irrepreensíveis em santidade diante do nosso Deus e Pai, na vinda do nosso Senhor Jesus Cristo com todos os seus santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Portanto, irmãos, no restante, vos rogamos e exortamos no Senhor Jesus, que, assim como recebestes de nós como deveis andar e agradar a Deus, que façais assim cada vez mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Pois vós sabeis quais mandamentos vos demos pelo Senhor Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Pois esta é a vontade de Deus: a vossa santificação, que não pratiqueis pecado sexual;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'que cada um de vós saiba ser ter o seu instrumento em santidade e honra;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'não na paixão do desejo malicioso, como os gentios que não conhecem Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Ninguém oprima ou engane ao seu irmão nisso, porque o Senhor é vingador de todas essas coisas, como também antes vos dissemos e demos testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Pois Deus não nos chamou para a impureza, mas sim para a santificação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Portanto quem rejeita isso, rejeita não ao ser humano, mas sim a Deus, que nos deu também o seu Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Mas quanto ao amor fraternal, não precisais que eu vos escreva, pois vós mesmos estais instruídos por Deus que vos ameis uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Pois, de fato, já fazeis assim a todos os irmãos de toda a Macedônia. Porém, irmãos, vos exortamos que façais isso ainda mais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'E procurai viver quietos, trantando dos vossos próprios assuntos, e trabalhando com as vossas próprias mãos, como já vos mandamos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'para que andeis de maneira respeitosa com os que estão de fora, e não necessiteis de nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Mas irmãos, não quero que desconheçais acerca dos que morreram, para que não vos entristeçais como os outros que não têm esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Pois, se cremos que Jesus morreu e ressuscitou, assim também aos que morreram em Jesus, Deus os trará de volta com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Pois dizemos isto pela palavra do Senhor, que nós, os que ficarmos vivos até a vinda do Senhor, não iremos antes dos que morreram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Pois o mesmo Senhor descerá do céu com grande aclamação, com voz de arcanjo, e com trombeta de Deus; e os que morreram em Cristo ressuscitarão primeiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Em seguida nós, os que ficarmos vivos, seremos arrebatados juntamente com eles nas nuvens, para encontrar o Senhor no ar, e assim estaremos com o Senhor para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Portanto consolai-vos uns aos outros com essas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Mas irmãos, acerca dos tempos e das estações, não necessitais de que eu vos escreva;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'pois vós mesmos bem sabeis que o dia do Senhor virá como um ladrão de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Pois quando disserem: “Paz e segurança”, então virá sobre eles repentina destruição, como as dores de parto da grávida, e de maneira nenhuma escaparão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mas vós, irmãos, não estais em trevas, para que aquele dia vos tome de surpresa como um ladrão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Todos vós sois filhos da luz e filhos do dia; não somos da noite nem das trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Portanto, não durmamos, como os outros; em vez disso, vigiemos e sejamos sóbrios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Pois os que dormem, dormem de noite; e os que ficam bêbados embebedam-se de noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Mas nós, que somos do dia, sejamos sóbrios, e nos vistamos da couraça da fé e do amor, e do capacete da esperança da salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Porque Deus não nos destinou para a ira, mas, sim, para obtermos a salvação, por meio do nosso Senhor Jesus Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'que morreu por nós, a fim de que, se estivermos vigiando ou dormindo, nós vivamos juntamente com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Portanto exortai-vos uns aos outros, e edificai-vos uns aos outros, como já fazeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Irmãos, nós vos rogamos que reconheçais os que trabalham entre vós, e que lideram sobre vós no Senhor, e vos advertem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'e os estimai muito com amor, por causa do trabalho deles. Tende paz entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Rogamo-vos também, irmãos, que advirtais os desordeiros, consoleis os de pouco ânimo, apoieis aos fracos, e tenhais paciência com todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Tende cuidado para que ninguém retribua o mal com o mal, mas sempre segui o bem, tanto uns com os outros, como com todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Alegrai-vos sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Orai sem cessar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Agradecei em tudo, pois essa é a vontade de Deus em Cristo Jesus para vós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Não apagueis o Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Não desprezeis as profecias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Examinai tudo, e mantende o que é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Não haja entre vós qualquer forma de mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'E o próprio Deus da paz vos santifique em tudo; e que todo o vosso espírito, alma e corpo sejam preservados irrepreensíveis na vinda do nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Fiel é aquele que vos chama, e ele também o fará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Irmãos, orai por nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Saudai a todos os irmãos com beijo santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Eu vos mando pelo Senhor que esta carta seja lida a todos os santos irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'A graça de nosso Senhor Jesus Cristo seja convosco. Amém. A primeira carta aos tessalonicenses foi escrita de Atenas');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulo, e Silvano, e Timóteo, à igreja dos tessalonicenses, em Deus nosso Pai, e no Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Haja entre vós graça e paz de nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Nós sempre devemos dar graças a Deus por vós, irmãos, como é o correto, porque vossa fé cresce muito, e o amor de cada um de todos vós pelos outros é cada vez maior;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'De maneira que nós mesmos nos orgulhamos de vós nas igrejas de Deus, por causa de vossa paciência e fé, em todas as vossas perseguições aflições que suportais;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Que é prova clara do justo julgamento de Deus, para que sejais considerados dignos do Reino de Deus, pelo qual também sofreis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Pois é justo diante de Deus pagar com aflição aos que vos afligem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'E a vós que sois afligidos, alívio conosco, quando o Senhor Jesus aparecer do céu com os anjos de seu poder,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'Com labareda de fogo, vingando os que não conhecem a Deus, e os que não obedecem ao Evangelho do nosso Senhor Jesus Cristo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Os quais serão punidos com o castigo da eterna perdição, longe da face do Senhor, e da glória de sua força;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Quando ele vier para ser glorificado em seus santos, e naquele dia se fazer admirável em todos os que creem (porque nosso testemunho entre vós foi crido).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Por isso que também sempre rogamos por vós, que nosso Deus vos faça dignos do chamamento, e cumpra todo bom desejo e a obra da fé com poder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Para que o nome de nosso Senhor Jesus Cristo seja glorificado em vós, e vós nele, segundo a graça de nosso Deus, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Ora irmãos, nós vos rogamos quanto à vinda de nosso Senhor Jesus Cristo, e à nossa reunião com ele,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Que vós não vos abaleis facilmente em vosso entendimento, e não vos perturbeis, nem por espírito, nem por palavra, nem por carta como que escrita por nós, como se o dia de Cristo já estivesse perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Ninguém vos engane em maneira nenhuma; porque não virá esse dia sem que primeiro venha a apostasia, e se manifeste o homem do pecado, o filho da perdição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'O qual se opõe e se levanta sobre tudo o que se chama Deus, ou sobre tudo que é adorado; por isso ele se sentará no templo de Deus, como se fosse Deus, fazendo-se parecer Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Não vos lembrais, que enquanto ainda estava convosco, eu vos dizia estas coisas?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'E agora sabeis o que o detém, para que a seu próprio tempo seja manifestado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Porque o mistério da injustiça já opera; só há aquele que agora o detém, até que seja tirado do meio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'E então será manifestado aquele injusto, ao qual o Senhor destruirá, pelo sopro de sua boca, e o aniquilará pelo aparecimento de sua vinda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Aquele injusto cuja vinda é conforme o agir de Satanás, com todo poder, e sinais, e milagres falsos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'E com todo engano de injustiça nos que perecem; porque não receberam o amor da verdade para se salvarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'E por isso Deus lhes enviará a ação do erro, para que creiam na mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Para que sejam condenados todos os que não creram na verdade, mas tiveram prazer na injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mas sempre devemos dar graças a Deus por vós, irmãos, que sois amados pelo Senhor, pois Deus vos escolheu desde o princípio para a salvação, em santificação do Espírito, e fé na verdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Para a qual ele vos chamou por meio do nosso Evangelho, para a obtenção da glória de nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Portanto, irmãos, ficai firmes, e retende as tradições que vos foram ensinadas, seja por palavra, seja por carta nossa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'E ele mesmo, o nosso Senhor Jesus Cristo, e nosso Deus e Pai, que nos amou e em graça nos deu uma eterna consolação e boa esperança;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Ele console vossos corações, e vos fortaleça em toda boa palavra e obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Nas demais coisas, irmãos, rogai por nós, para que a palavra do Senhor continue seu percurso, e seja glorificada, assim como também entre vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'E para que sejamos livres de homens corruptos e maus, porque a fé não é de todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Mas fiel é o Senhor, que vos fortalecerá e vos guardará do maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'E confiamos no Senhor quanto a vós, de que vós estais fazendo e continuareis a fazer o que vos mandamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'E o Senhor guie vossos corações para o amor de Deus e a paciência de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Mas nós vos mandamos, irmãos, no nome de nosso Senhor Jesus Cristo, que mantenhais distância de todo irmão que anda desordenadamente, e não segundo a tradição que recebeu de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Porque vós mesmos sabeis como deveis nos imitar; porque nós não fomos desordenados entre vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Nem comemos de graça o pão de qualquer um, mas sim com trabalho e cansaço trabalhamos de noite e de dia, para não sermos incômodos a nenhum de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Não porque não tivéssemos autoridade para fazer isso, mas porque nós mesmos dávamos exemplo a vós, para assim nos imitardes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Porque, quando ainda estávamos convosco, isto vos mandamos: que se alguém não quiser trabalhar, também não coma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Porque ouvimos que alguns entre vós andam desordenadamente, não trabalhando, mas se intrometendo no que os outros fazem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Mas aos tais mandamos e exortamos, por nosso Senhor Jesus Cristo, que trabalhem sem causar incômodo, e comam seu próprio pão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'E vós, irmãos, não vos canseis de fazer o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Mas se alguém não obedecer à nossa palavra contida nesta carta, adverti-o, e não vos mistureis com ele, para que ele se envergonhe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'E não o considereis como inimigo, mas alertai -o como um irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'E o mesmo Senhor da paz vos dê sempre paz em toda maneira. O Senhor seja com todos vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'A saudação de minha própria mão, Paulo, que é minha assinatura em toda carta; assim escrevo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'A graça de nosso Senhor Jesus Cristo seja com todos vós. Amém. A segunda carta aos tessalonicenses foi escrita de Atenas');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulo, apóstolo de Jesus Cristo segundo o mandado de Deus, nosso Salvador, e do Senhor Jesus Cristo, nossa esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Para Timóteo, meu verdadeiro filho na fé. Graça, misericórdia e paz da parte de Deus, nosso Pai, e de Cristo Jesus, nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Assim como te roguei quando eu estava indo à Macedônia, fica em Éfeso, para advertires a alguns que não ensinem outra doutrina,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Nem prestem atenção a mitos nem a genealogias intermináveis, que mais produzem discussões que a edificação da parte de Deus na fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'O fim do mandamento é o amor que vem de um coração puro, e de uma boa consciência, e de uma fé não fingida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Alguns se desviaram dessas coisas, e se entregaram a discursos inúteis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'querendo ser mestres da Lei, mas não entendendo, nem o que dizem, nem o que afirmam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Nós, porém, sabemos que a Lei é boa, se alguém usa dela legitimamente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'pois sabemos isto: que a Lei não foi feita para o justo, mas sim, para os injustos e insubordinados, para os ímpios e pecadores, para os irreligiosos e profanos, para os matadores dos pais e das mães, para os homicidas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'para os que cometem pecados sexuais, para os homens que efetuam sexualidade com homens, para os que roubam a liberdade das pessoas, para os mentirosos, para os que juram falsamente, e qualquer outra coisa contrária à sã doutrina,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'conforme o evangelho da glória do Deus bendito, que foi confiado a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'E agradeço àquele que tem me fortalecido, Cristo Jesus, nosso Senhor, porque me considerou fiel, pondo-me no serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Antes eu era um blasfemo, perseguidor, e opressor; porém recebi misericórdia, pois foi por ignorância que eu agia com incredulidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Mas a graça do nosso Senhor Jesus Cristo foi mais abundante, com a fé e amor que há em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Esta é uma palavra fiel e digna de toda aceitação: que Cristo Jesus veio ao mundo para salvar os pecadores, dos quais eu sou o principal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Mas por isso me foi concedida misericórdia, para que em mim, o principal, Jesus Cristo mostrasse toda a sua paciência como exemplo aos que haviam de crer nele para a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Ao Rei dos tempos, imortal, invisível, o único Deus sábio, seja a honra, e a glória, para todo o sempre, amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Este mandamento, filho Timóteo, te dou: que, conforme as profecias antes feitas acerca de ti, que batalhes por elas a boa batalha;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'mantendo a fé e a boa consciência, que alguns rejeitaram, e naufragaram na fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Dentre esses foram Himeneu e Alexandre. Eu os entreguei a Satanás, para aprenderem a não blasfemar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Por isso eu te exorto, antes de tudo, que se façam pedidos, orações, intercessões e atos de gratidão por todas as pessoas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'pelos reis, e por todos os que estão em posição superior, para que tenhamos uma vida quieta e sossegada, em toda devoção divina e honestidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Pois isso é bom e agradável diante de Deus nosso Salvador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'que quer que todas as pessoas se salvem e venham ao conhecimento da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Pois há um só Deus, e um só Mediador entre Deus e os seres humanos: o humano Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Ele mesmo se deu como resgate por todos, como testemunho ao seu tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Para isso fui constituído pregador e apóstolo, instrutor dos gentios na fé e na verdade (estou dizendo a verdade em Cristo, não mentindo).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Portanto, quero que os homens orem em todo lugar, levantando mãos santas, sem ira nem briga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'De semelhante maneira, as mulheres se adornem com roupa respeitosa, com pudor e sobriedade, não com tranças, ouro, pérolas, ou roupas caras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'mas sim, com boas obras, como é adequado às mulheres que declaram reverência a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'A mulher aprenda quietamente, com toda submissão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Porém não permito que a mulher ensine, nem use de autoridade sobre o marido, mas sim, que esteja em silêncio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Pois primeiro foi formado Adão, depois Eva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'E Adão não foi enganado; mas a mulher foi enganada, e caiu em transgressão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Porém ela se salvará tendo parto, se permanecerem na fé, amor, e santificação com sobriedade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Esta palavra é fiel: se alguém deseja ser bispo, deseja uma excelente obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'É dever, portanto, que o bispo seja irrepreensível, marido de uma mulher, sóbrio, comedido, decente, hospitaleiro, apto para ensinar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Não dado ao vinho, não violento, não ganancioso, mas sim moderado, não briguento, não cobiçoso por dinheiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'que governe bem a sua própria casa, e tenha os seus filhos em submissão com toda dignidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(Pois, se alguém não sabe governar a sua própria casa, como cuidará da igreja de Deus?)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Não um novo convertido; para que não se torne arrogante, e caia na condenação do diabo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'É dever também que tenha bom testemunho dos que estão de fora, para que não caia em reprovação pública e na cilada do diabo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'De maneira semelhante, os diáconos sejam de boa conduta, não contraditórios, não dados a muito vinho, não cobiçosos de ganho desonesto,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'mas mantenham o mistério da fé em consciência pura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'E também esses sejam primeiro testados, depois sirvam, se forem irrepreensíveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'De semelhante maneira, as mulheres sejam de boa conduta, não maldizentes, sóbrias, e fiéis em todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Os diáconos sejam maridos de uma mulher, e governem bem os filhos e as suas próprias casas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Pois os que servirem bem obtêm para si uma posição honrosa e muita confiança na fé que há em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Escrevo-te essas coisas esperando ir a ti em breve;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'mas, seu eu demorar, para que saibais como se deve comportar na casa de Deus, que é a igreja do Deus vivo, a coluna e o alicerce da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'E, sem dúvida nenhuma, grande é o mistério da devoção divina: Deus foi revelado em carne, justificado em Espírito, visto pelos anjos, pregado aos gentios, crido no mundo, e recebido acima em glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Mas o Espírito diz expressamente que nos últimos tempos alguns se afastarão da fé, dando atenção a espíritos enganadores, e a doutrinas de demônios,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'por meio da hipocrisia de mentirosos, que têm a sua própria consciência cauterizada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Eles proibirão o casamento, e mandarão se abster dos alimentos que Deus criou para que sejam usados com gratidão pelos fiéis e pelos que conheceram a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Pois toda criatura de Deus é boa, e não há nada a rejeitar, se for recebida com gratidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Porque ela é santificada pela palavra de Deus e pela oração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Se informares essas coisas aos irmãos, serás um bom servidor de Jesus Cristo, alimentado com as palavras da fé e de boa doutrina que tens seguido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Mas rejeita os mitos profanos e de velhas, e exercita-te na devoção divina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Pois o exercício do corpo tem pouco proveito; mas a devoção divina é proveitosa para tudo, pois tem as promessas da vida atual e da futura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Esta palavra é fiel, e digna de toda aceitação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Pois para isto também trabalhamos e somos insultados, porque esperamos o Deus vivo, que é o Salvador de todos, especialmente dos crentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Manda essas coisas, e ensina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Ninguém despreze a tua juventude, mas sê exemplo aos crentes, na palavra, no comportamento, no amor, em espírito, na fé, e na pureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Persiste na leitura, na exortação e no ensino, até que eu venha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Não desprezes o dom que está em ti, que te foi dado por profecia, com a imposição das mãos dos presbíteros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Medita nessas coisas, e nelas te ocupe, para que o teu progresso seja visível por todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Tem cuidado de ti mesmo e da doutrina; persevera nessas coisas; porque, se fizeres isso, salvarás tanto a ti mesmo como aos que te ouvem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Não repreendas ao idoso asperamente, mas exorta-o como a um pai; aos jovens, como a irmãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'às idosas, como a mães; e às moças, como a irmãs, em toda pureza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Honra as viúvas que são verdadeiramente viúvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Mas, se alguma viúva tiver filhos ou netos, aprendam primeiro a exercer piedade com a sua própria família, e a recompensar os seus pais; porque isso é bom e agradável diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'A que é verdadeiramente viúva e desamparada espera em Deus, e persevera noite e dia em rogos e orações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Mas a que se entrega aos prazeres, enquanto vive, está morta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Manda, pois, essas coisas, para que sejam irrepreensíveis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Porém, se alguém não cuida dos seus, e principalmente dos de sua própria família, negou a fé, e é pior que um incrédulo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'A viúva, para ser registrada, não deve ter menos de sessenta anos, e haver sido mulher de um marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Ela deve ter testemunho de boas obras: se criou filhos, se foi hospitaleira, se lavou os pés dos santos, se socorreu os aflitos, se seguiu toda boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mas não admitas as viúvas jovens; porque, quando têm desejos sensuais contra Cristo, querem se casar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'e têm condenação, por haverem anulado a primeira fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'E, além disso, também aprendem a andar ociosas de casa em casa; e não somente ociosas, mas também fofoqueiras e curiosas, falando o que não se deve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Por isso, quero que as mais jovens se casem, gerem filhos, administrem a casa, e não deem nenhuma oportunidade ao adversário de maldizer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Pois algumas já se desviaram e seguiram Satanás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Se algum crente ou alguma crente tem viúvas, que as ajude, e não sobrecarregue a igreja, para que ela possa ajudar as que são de verdade viúvas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Os presbíteros ou: anciãos que lideram bem sejam estimados como dignos de honra dobrada, principalmente os que trabalham na palavra e na doutrina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Pois a Escritura diz: “Ao boi que debulha não atarás a boca”; e: “o trabalhador é digno do seu salário”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Não aceites acusação contra um presbítero, a não ser com duas ou três testemunhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Aos que pecarem, repreende-os na presença de todos, para que os outros também tenham temor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Ordeno-te, diante de Deus, do Senhor Jesus Cristo, e dos anjos escolhidos, que guardes essas coisas sem preconceitos, fazendo nada por favoritismo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'A ninguém imponhas as mãos apressadamente, nem participes dos pecados alheios; conserva-te puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Não bebas mais somente água, mas usa também de um pouco de vinho, por causa do teu estômago, e das tuas frequentes enfermidades.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Os pecados de algumas pessoas são evidentes antes mesmo do juízo, mas os de algumas são manifestos depois.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Semelhantemente, também, as boas obras são evidentes; e as que não são assim não se podem esconder.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Todos os servos que estão sob escravidão estimem aos seus senhores como dignos de toda honra; para que o nome de Deus e a doutrina não sejam blasfemados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'E os que têm senhores crentes não os desprezem por serem irmãos; pelo contrário, que os sirvam melhor, pois os participantes do benefício são crentes e amados. Ensina e exorta estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Se alguém ensina doutrina diferente, e não concorda com as sãs palavras do nosso Senhor Jesus Cristo e com a doutrina que é conforme a devoção divina,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'é presunçoso, e nada sabe. Em vez disso, se interessa de maneira doentia por questões e disputas de palavras, das quais nascem invejas, brigas, blasfêmias, suspeitas maldosas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'discussões inúteis de pessoas corrompidas de entendimento, e privadas da verdade, que pensam que a devoção divina é um meio de lucrar. Afasta-te dos tais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Mas grande lucro é a devoção divina acompanhada de contentamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Pois nada trouxemos ao mundo, e é evidente que nada podemos levar dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Mas se tivermos alimento e algo com que nos cobrirmos, estejamos contentes com isso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Mas os que querem ser ricos caem em tentação, armadilha, e em muitos desejos insensatos e nocivos, que afundam as pessoas na destruição e perdição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Pois o amor ao dinheiro é raiz de todos os tipos de males. Alguns o cobiçam, e então se desviaram da fé, e perfuraram a si mesmos com muitas dores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Porém tu, homem de Deus, foge dessas coisas. Segue a justiça, a devoção divina, a fé, o amor, a paciência, a mansidão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Que lutes a boa luta da fé; agarra a vida eterna para a qual também foste chamado, e confessaste a boa confissão diante de muitas testemunhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Mando-te diante de Deus, que dá vida a todas as coisas, e de Cristo Jesus, que diante de Pôncio Pilatos testemunhou a boa confissão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'que guardes este mandamento sem mancha nem motivo de repreensão, até a aparição do nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Essa nos seus tempos mostrará o bendito e único Soberano, o Rei dos reis, e Senhor dos senhores;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'o único a ter imortalidade, e que habita em luz inacessível; aquele a quem nenhum ser humano viu, nem pode ver; a ele seja honra e poder para sempre! Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Manda aos ricos desta era que não sejam soberbos, nem ponham a esperança na incerteza das riquezas, mas sim no Deus vivo, que nos dá abundantemente todas as coisas que são para alegria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'que façam o bem, sejam ricos em boas obras, dispostos a compartilhar, e generosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'que acumulem para si mesmos um bom fundamento para o futuro, para que obtenham a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Timóteo, guarda o depósito que te foi confiado, evitando conversas vãs e profanas, e controvérsias do que é falsamente chamado de “conhecimento”;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'que alguns declararam seguir, e se desviaram da fé. A graça seja contigo. Amém. A primeira carta a Timóteo foi escrita de Laodiceia, que é a principal cidade da Frígia Pacaciana.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulo, apóstolo de Jesus Cristo, pela vontade de Deus, segundo a promessa da vida que está em Cristo Jesus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'a Timóteo, meu amado filho. Graça, misericórdia, e paz, da parte de Deus Pai, e de Cristo Jesus, nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Agradeço a Deus, a quem desde os meus antepassados sirvo com uma consciência pura, de que sem cessar tenho memória de ti nas minhas orações noite e dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Lembro-me das tuas lágrimas, e desejo muito te ver, para me encher de alegria;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Trago à memória a fé não fingida que há em ti, fé que habitou primeiro na tua avó Loide, e na tua mãe Eunice; e tenho certeza que também em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Por essa causa lembro-te de reacenderes o dom de Deus que está em ti pela imposição das minhas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Pois Deus não nos deu espírito de medo; mas sim de força, de amor, e de moderação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Portanto não te envergonhes do testemunho do nosso Senhor, nem de mim, que sou prisioneiro dele; em vez disso, participa das aflições do Evangelho segundo o poder de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Ele nos salvou, e chamou com um chamado santo; não conforme as nossas obras, mas sim, conforme a sua própria intenção, e a graça que nos foi dada em Cristo Jesus antes dos princípios dos tempos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'mas agora é manifesta pela aparição do nosso Salvador Jesus Cristo, que anulou a morte, e trouxe para a luz a vida e a imortalidade por meio do evangelho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'do qual eu fui constituído pregador e apóstolo, e instrutor dos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Por causa disso também sofro essas coisas; porém não me envergonho. Pois sei em quem tenho crido, e tenho certeza de que ele é poderoso para guardar o que lhe confiei até aquele dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Preserva o exemplo das sãs palavras que tens ouvido de mim, na fé e no amor que há em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Guarda o bem que te foi confiado por meio do Espírito Santo que habita em nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Sabes isto, que todos os que estão na Ásia Romana me abandonaram, entre os quais estavam Fígelo e Hermógenes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'O Senhor conceda misericórdia à casa de Onesíforo, pois muitas vezes ele me consolou, e não se envergonhou de eu estar em cadeias;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Pelo contrário, quando veio a Roma, com empenho me procurou, e me encontrou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'O Senhor lhe conceda que naquele dia ele encontre misericórdia diante do Senhor. E tu sabes muito bem como ele me ajudou em Éfeso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Portanto tu, meu filho, fortifica-te na graça que há em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'E o que de mim ouviste entre muitas testemunhas, confia-o a pessoas fiéis, que sejam competentes para ensinar também a outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Tu, pois, sofre as aflições como bom soldado de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Nenhum soldado em batalha se envolve com assuntos desta vida, pois tem como objetivo agradar àquele que o alistou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'E, também, se alguém está competindo como atleta, não recebe a coroa se não seguir as regras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'O lavrador que trabalha deve ser o primeiro a receber da partilha dos frutos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Considera o que digo; que o Senhor te dê entendimento em tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Lembra-te de Jesus Cristo, ressuscitado dos mortos, da descendência de Davi, segundo o meu evangelho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Por esse evangelho sofro aflições, e até prisões, como um criminoso; mas a palavra de Deus não está presa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Por isso tudo suporto por causa dos escolhidos, a fim de que também eles obtenham a salvação que está em Cristo Jesus com glória eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Esta afirmação é fiel: se morrermos com ele, também com ele viveremos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'se sofrermos, também com ele reinaremos; se o negamos, também ele nos negará;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'se formos infiéis, ele continua fiel; ele não pode negar a si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Lembra-os disso, alertando-os diante do Senhor, que não tenham brigas de palavras, que não têm proveito algum, a não ser para a ruína dos ouvintes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Procura apresentar-te aprovado a Deus como um trabalhador que não tem de que se envergonhar, que usa bem a palavra da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Mas evita conversas profanas e inútes; pois tendem a produzir maior irreverência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'E a palavra deles se espalhará como uma gangrena; entre os quais são Himeneu e Fileto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Esses se desviaram da verdade, dizendo que a ressurreição já aconteceu; e perverteram a fé de alguns.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Porém o fundamento de Deus continua firme, e tem este selo: o Senhor conhece os que são seus, e que todo aquele que faz uso do nome de Cristo, se afaste da injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Numa grande casa não há somente utensílios de ouro e de prata, mas também de madeira e de barro; e uns para honra, porém outros para desonra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Portanto, se alguém se purificar destas coisas, será utensílio para honra, santificado e adequado para uso do Dono, e preparado para toda boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Foge também dos desejos da juventude; e segue a justiça, a fé, o amor, e a paz, com os que, de coração puro, invocam o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'E rejeita as questões tolas e sem instrução, como sabes que elas produzem brigas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'E ao servo do Senhor não convém brigar, mas sim ser manso com todos, apto para ensinar e suportar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'deve instruir com mansidão aos que se opõem, pois talvez Deus lhes dê arrependimento para conhecerem a verdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'e se libertem da armadilha do diabo, em que foram presos à vontade dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Sabe porém isto, que nos últimos dias virão tempos difíceis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Pois haverá alguns que serão egoístas, gananciosos, presunçosos, soberbos, blasfemos, desobedientes a pais e a mães, ingratos, profanos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'sem afeto natural, irreconciliáveis, caluniadores, sem dominio próprio, cruéis, sem amor com os bons,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'traidores, precipitados, orgulhosos, que amam mais os prazeres que a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Eles têm uma aparência de devoção divina, mas negam o poder dela. Afasta-te desses também.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Pois dentre esses são os que entram pelas casas, e levam cativas as mulheres insensatas carregadas de pecados, levadas com vários maus desejos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'que sempre estão aprendendo, e jamais conseguem chegar ao conhecimento da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'E assim como Janes e Jambres se opuseram a Moisés, assim também esses se opõem a verdade; esses são corruptos de entendimento, e reprovados quanto à fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Eles, porém, não avançarão; pois a insensatez deles será evidente a todos, como também foi a daqueles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Porém tu tens seguido a minha doutrina, conduta, intenção, fé, paciência, amor, perseverança,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'perseguições, aflições; as quais me aconteceram em Antioquia, em Icônio e em Listra; tais perseguições sofri, e o Senhor me livrou de todas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'E também todos os que querem viver devotamente em Cristo Jesus sofrerão perseguição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Mas os que são maus e enganadores irão de mal a pior, enganando e sendo enganados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Tu, porém, continua nas coisas que aprendeste e das quais foste convencido, pois sabes de quem as aprendeste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'e que desde tua infância conheceste as Sagradas Escrituras, que podem te fazer sábio para a salvação pela fé em Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Toda a Escritura é divinamente inspirada e proveitosa para ensinar, para mostrar o erro, para corrigir, e para instruir na justiça;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'para que o homem de Deus seja completo, plenamente instruído para toda boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Portanto te convoco diante de Deus e do Senhor Jesus Cristo, que irá julgar os vivos e os mortos em sua aparição e seu reino:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'prega a palavra; insiste em tempo e fora de tempo; mostra os erros; repreende e exorta, com toda paciência e ensino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Pois virá tempo em que não suportarão a sã doutrina; em vez disso, terão comichão no ouvido e amontoarão para si instrutores conforme os seus próprios desejos maus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'desviarão os ouvidos da verdade, e se voltarão aos mitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Tu, porém, vigia-te em todas as coisas; suporta as aflições, faz a obra de evangelista, cumpre o teu serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Pois já sou uma oferta de derramamento, e o tempo da minha partida está perto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Lutei a boa luta, terminei a carreira, guardei a fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Desde agora a coroa da justiça me está reservada, a qual o Senhor, o justo Juiz, me dará naquele dia; e não somente a mim, mas também a todos os que amarem a sua vinda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Procura vir logo até mim,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'porque Demas me desamparou: ele amou o tempo presente, e partiu para Tessalônica; Crescente para a Galácia, e Tito para a Dalmácia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Só Lucas está comigo. Toma Marcos, e o traz contigo, porque ele me é muito útil para o serviço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Enviei Tíquico a Éfeso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Quando vieres, traz a capa que deixei em Trôade na casa de Carpo, e os livros, principalmente os pergaminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexandre, o que trabalha com cobre, me causou muitos males; o Senhor retribua a ele conforme suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Toma cuidado com ele também, porque ele se opôs muito às nossas palavras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Na minha primeira defesa ninguém esteve comigo para me ajudar, pelo contrário, todos me desampararam. Que isso não seja levado em consideração contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mas o Senhor me ajudou e me fortaleceu, a fim de que por mim a pregação fosse completamente divulgada, e todos os gentios a ouvissem; e fui livrado da boca do leão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'E o Senhor me livrará de toda obra má, e me preservará para o seu reino celestial. A ele seja glória para todo o sempre. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Cumprimenta Prisca e Áquila, e a casa de Onesíforo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erasto ficou em Corinto, e deixei Trófimo doente em Mileto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Procura vir antes do inverno. Êubulo, Pudente, Lino, Cláudia e todos os irmãos te cumprimentam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'O Senhor Jesus Cristo seja com o teu espírito. A graça seja convosco. Amém. A segunda carta a Timóteo (o primeiro bispo escolhido para a igreja dos efésios) foi escrita em Roma, quando Paulo foi apresentado pela segunda vez ao imperador Nero');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulo, servo de Deus e apóstolo de Jesus Cristo, segundo a fé dos escolhidos de Deus, e o conhecimento da verdade, que é segundo a devoção divina;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'em esperança da vida eterna, a qual Deus, que não pode mentir, prometeu antes dos princípios dos tempos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'E a seu devido tempo a manifestou: a sua palavra, por meio da pregação, que me foi confiada segundo o mandamento de Deus nosso Salvador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Para Tito, meu verdadeiro filho, segundo a fé em comum; haja em ti graça, misericórdia e paz de Deus Pai, e do Senhor Jesus Cristo, nosso Salvador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Por esta causa eu te deixei em Creta, para que tu continuasses a pôr em ordem as coisas que estavam faltando, e de cidade em cidade constituísses presbíteros, conforme eu te mandei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Se alguém for irrepreensível, marido de uma mulher, que tenha filhos fiéis, que não possam ser acusados de serem devassos ou desobedientes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Porque o supervisor deve ser irrepreensível, como administrador da casa de Deus, não arrogante, que não se ira facilmente, não beberrão, não agressivo, nem ganancioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Mas que ele seja hospitaleiro, ame aquilo que é bom, moderado, justo, santo, e tenha domínio próprio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Retendo firme a fiel palavra que é conforme o que foi ensinado; para que ele seja capaz, tanto para exortar na sã doutrina, como também para mostrar os erros dos que falam contra ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Porque também há muitos insubordinados, que falam coisas vãs, e enganadores, especialmente aqueles da circuncisão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Aos quais devem se calar, que transtornam casas inteiras, ensinando o que não se deve, por causa da ganância.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Um próprio profeta deles disse: Os cretenses sempre são mentirosos, animais malignos, ventres preguiçosos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Este testemunho é verdadeiro; por isso repreende-os severamente, para que sejam sãos na fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Não dando atenção a mitos judaicos, e a mandamentos de homens, que desviam da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Realmente todas as coisas são puras para os puros; mas para os contaminados e infiéis, nada é puro; e até o entendimento e a consciência deles estão contaminados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Eles declaram que conhecem a Deus, mas com as obras eles o negam, pois são abomináveis e desobedientes, e reprovados para toda boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Tu, porém, fala o que convém à sã doutrina;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Aos velhos, que sejam sóbrios, respeitáveis, prudentes, sãos na fé, no amor e na paciência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Às velhas, da mesma maneira, tenham bons costumes, como convém a santas; não caluniadoras, não viciadas em muito vinho, mas sim instrutoras daquilo que é bom;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Para ensinarem às moças a serem prudentes, a amarem a seus maridos, a amarem a seus filhos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'A serem moderadas, puras, boas donas de casa, sujeitas a seus próprios maridos, para que a palavra de Deus não seja blasfemada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Exorta semelhantemente aos rapazes, que sejam moderados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Em tudo mostra a ti mesmo como exemplo de boas obras; na doutrina, mostra incorrupção, dignidade, sinceridade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Uma palavra sã e irrepreensível, para que qualquer opositor se envergonhe, nada tendo de mal para dizer contra vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Que os servos sejam sujeitos a seus próprios senhores, sendo agradáveis em tudo, e não falando contra eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Não lhes furtando, mas sim mostrando toda a boa lealdade; para que em tudo adornem a doutrina de Deus nosso Salvador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Porque a graça salvadora de Deus se manifestou a todos os homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Ensinando-nos que, ao renunciarmos à irreverência e aos maus desejos mundanos, vivamos neste tempo presente de maneira sóbria, justa e devota.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Aguardando a bem-aventurada esperança e o aparecimento da glória do grande Deus e nosso Salvador Jesus Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'O qual deu a si mesmo por nós, para nos libertar de toda injustiça, e para purificar para si mesmo um povo particular, zeloso de boas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Fala estas coisas, exorta, e repreende com toda autoridade. Ninguém te despreze.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Relembra-os para se sujeitarem aos governantes e às autoridades, sejam obedientes, e estejam preparados para toda boa obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Não insultem a ninguém, não sejam briguentos, mas sim pacientes, mostrando toda mansidão para com todos os homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Porque nós também éramos tolos, desobedientes, enganados, servindo a vários maus desejos e prazeres, vivendo em malícia e inveja, detestáveis, odiando uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Mas quando a bondade e amor de Deus nosso Salvador para a humanidade apareceu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Não pelas obras de justiça que nós tivéssemos feito, mas sim segundo sua misericórdia, ele nos salvou pelo banho do novo nascimento, e da renovação do Espírito Santo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Ao qual ele derramou abundantemente em nós por meio de Jesus Cristo nosso Salvador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Para que, ao termos sido justificados por sua graça, sejamos feitos herdeiros segundo a esperança da vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Esta palavra é fiel, e isto quero que insistas em confirmar, para que os que creem em Deus procurem se dedicar às boas obras; estas coisas são boas e proveitosas aos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Mas evita as questões tolas, e às genealogias e discussões, e às disputas quanto à Lei, porque elas são inúteis e vás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Ao homem rebelde, depois da primeira e da segunda repreensão, rejeita -o.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Sabendo que o tal está pervertido, e está pecando, estando a si mesmo condenado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Quando eu enviar Artemas até ti, ou Tíquico, procura vir até mim a Nicópolis, porque eu decidi passar lá o inverno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Auxilia com empenho a Zenas, o especialista na Lei, e a Apolo, na viagem deles, para que nada lhes falte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'E que também os nossos aprendam a se dedicarem às boas obras para os usos necessários, para que não sejam infrutíferos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Todos os que estão comigo te saúdam. Saúda tu aos que nos amam na fé. A graça seja com todos vós. Amém! A carta a Tito, o primeiro bispo escolhido da igreja dos cretenses, foi escrita de Nicópolis na Macedônia');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulo, prisioneiro de Cristo Jesus, e o irmão Timóteo, a Filemom, o amado, e nosso cooperador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'E à amada Ápia, e a Arquipo nosso companheiro de batalha, e à igreja que está em tua casa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Haja em vós graça e paz de Deus nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Eu dou graças a meu Deus sempre me lembrando de ti em minhas orações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Ao ouvir de teu amor e a fé que tu tens para com o Senhor Jesus, e para com todos os santos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Para que a comunhão de tua fé seja eficaz no reconhecimento de todo o bem que há em vós por Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Porque nós temos grande alegria e consolo em teu amor, pelo qual, por meio de ti, irmão, os sentimentos dos santos foram aliviados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Por isso, ainda que em Cristo eu tenha grande confiança para te mandar aquilo que te é conveniente,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Em vez disso por amor eu te peço, ainda que eu seja tal, Paulo, o velho, e também agora um prisioneiro de Jesus Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Eu te peço por meu filho Onésimo, ao qual eu gerei durante minhas prisões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Aquele que antes te era inútil, mas agora útil para mim e para ti, eu o enviei de volta;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'E tu, como os meus mais íntimos sentimentos, recebe-o;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Eu até que gostaria de retê-lo comigo, para que como teu substituto ele me servisse nas prisões do Evangelho;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Mas eu nada quis fazer sem tua opinião, para que tua bondade não fosse como que por obrigação, mas sim de livre vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Porque talvez por isso que ele tenha se separado de ti por algum tempo, para que tu o recebesses de volta para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Não mais como a um servo, mas sim mais que um servo, como a um amado irmão, especialmente para mim, e muito mais de ti, tanto na carne como no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Portanto, se tu me tens como companheiro, então recebe-o como a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'E se ele te fez algum dano, ou te deve alguma coisa,põe isto na minha conta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Eu, Paulo, de minha própria mão o escrevi, eu pagarei; para eu não te dizer que tu me deves a ti mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Assim, irmão, que eu tenha algum benefício de ti no Senhor; alivia meus sentimentos no Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Tendo confiança de tua obediência eu te escrevi, sabendo que tu farás ainda mais do que eu digo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'E enquanto isso também me prepara um lugar para eu ficar; porque eu espero que por vossas orações eu seja entregue a vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Saúdam-te: Epafras (meu companheiro de prisão em Cristo Jesus),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marcos, Aristarco, Demas e Lucas (meus cooperadores).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'A graça de nosso Senhor Jesus Cirsto seja com vosso espírito. Amém! Escrita em Roma para Filemom, e enviada pelo servo Onésimo');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Deus falou antigamente muitas vezes, e de muitas maneiras, aos ancestrais pelos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Mas nestes últimos falou a nós por meio do seu Filho, a quem constituiu por herdeiro de todas as coisas, e pelo qual também fez o universo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'O Filho é o resplendor da sua glória, a expressa imagem da sua pessoa, e sustenta todas as coisas pela sua palavra de poder. E, depois de fazer por si mesmo a purificação dos nossos pecados, sentou-se à direita da Majestade nas alturas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'e se tornou muito superior aos anjos, assim como herdou um nome mais excelente que eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Pois a qual dos anjos Deus jamais disse: “Tu és meu Filho, eu hoje te gerei”, E em outra vez: “Eu lhe serei por Pai, e ele me será por Filho”?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'E outra vez, quando introduz o primogênito ao mundo, diz: E todos os anjos de Deus o adorem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Quanto aos anjos, porém, ele diz: Ele faz de seus anjos espíritos; e de seus trabalhadores, labareda de fogo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Mas ao Filho diz: Ó Deus, o teu trono é para todo o sempre. Cetro de equidade é o cetro do teu Reino.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Amaste a justiça, e odiaste a transgressão; por isso, Deus, o teu Deus, te ungiu com óleo de alegria mais que os teus companheiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'E: Tu Senhor, no princípio fundaste a terra, e os céus são obras de tuas mãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Eles perecerão, mas tu continuas. Todos eles como roupa se envelhecerão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'como uma manta tu os envolverás, e serão mudados; porém tu és o mesmo, e os teus anos não cessarão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'E a qual dos anjos ele jamais disse: Senta-te à minha direita, até que eu ponha os teus inimigos como estrado de teus pés?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Por acaso não são todos eles espíritos servidores, enviados para auxílio dos que herdarão a salvação?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Portanto, devemos prestar atenção com muito mais empenho para as coisas que já ouvimos, para que nunca venhamos a cometer deslizes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Pois, se a palavra pronunciada pelos anjos foi confirmada, e toda transgressão e desobediência recebeu justa retribuição,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'como nós escaparemos, se descuidarmos de tão grande salvação? Ela, que começou a ser anunciada pelo Senhor, foi-nos confirmada pelos que ouviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Deus também deu testemunho com eles, por meio de sinais, milagres, várias maravilhas, e distribuições do Espírito Santo, segundo a sua vontade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Pois não foi aos anjos que ele sujeitou o mundo futuro, do qual estamos falando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Mas em certo lugar alguém testemunhou, dizendo: O que é o homem, para que te lembres dele? Ou o filho do homem, para que o visites?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Tu o fizeste um pouco menor que os anjos, de glória e de honra o coroaste, e o estabeleceste sobre as obras das tuas mãos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Sujeitaste todas as coisas debaixo de seus pés.Pois ao lhe sujeitar todas as coisas, nada deixou que não fosse sujeito a ele; porém agora ainda não vemos todas as coisas sendo sujeitas a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Porém vemos coroado de glória e de honra, por causa do sofrimento de morte, aquele Jesus, que havia sido feito um pouco menor que os anjos, a fim de que, pela graça de Deus, experimentasse a morte por todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Pois convinha a aquele, para quem e por quem são todas as coisas, que, quando trouxesse muitos filhos à glória, aperfeiçoasse por meio de aflições o Autor da salvação deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Porque tanto o que santifica como os que são santificados, todos são provenientes de um; por isso ele não se envergonha de lhes chamar de irmãos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'dizendo: Anunciarei o teu nome aos meus irmãos, cantarei louvores a ti no meio da congregação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'E outra vez: Nele confiarei. E outra vez: Eis-me aqui, com os filhos que Deus me deu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Portanto, uma vez que os filhos compartilham da carne e do sangue, também ele, semelhantemente, participou das mesmas coisas, a fim de pela morte aniquilar ao que tinha o poder da morte, isto é, o diabo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'e libertar a todos os que, por medo da morte, estavam sujeitos à servidão durante a vida toda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Pois, evidentemente, não é aos anjos que ele ajuda, mas sim, ajuda à descendência de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Por isso era necessário que em tudo ele se tornasse semelhante aos irmãos, para ser misericordioso e fiel Sumo Sacerdote nas coisas relativas a Deus, para fazer sacrifício de perdão dos pecados do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Pois, naquilo em que ele mesmo sofreu ao ser tentado, ele pode socorrer aos que são tentados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Portanto, santos irmãos, participantes do chamado celestial, considerai o Apóstolo e Sumo Sacerdote da nossa declaração de fé, Cristo Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Ele é fiel àquele que o constituiu, assim como Moisés também foi em toda a casa de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Pois ele é estimado como digno de maior glória do que Moisés, assim como mais honra do que a casa tem quem a construiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Porque toda casa é construída por alguém; mas aquele que construiu todas as coisas é Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'De fato, Moisés foi fiel como servo em toda a casa de Deus, para testemunho das coisas que haviam de ser ditas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'mas Cristo é fiel como Filho sobre a sua casa. E nós somos sua casa, se até o fim mantivermos firmes a confiança e o orgulho da nossa esperança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Portanto, como diz o Espírito Santo: Hoje, se ouvirdes a sua voz,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'não endureçais os vossos corações, como na provocação, no dia da tentação no deserto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'onde os vossos pais me tentaram, me provaram, e viram as minhas obras por quarenta anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Por isso me indignei contra essa geração, e disse: “Eles sempre se desviam nos corações, e não conheceram os meus caminhos”;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Então jurei na minha ira: “Eles não entrarão no meu repouso”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Cuidado, irmãos, para que nunca haja em algum de vós coração mau e infiel, que se afaste do Deus vivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Em vez disso, encorajai-vos uns aos outros a cada dia, durante o tempo chamado “hoje”; a fim de que nenhum de vós se endureça pelo engano do pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Pois nós temos nos tornado participantes de Cristo, se, de fato, mantivermos firme a confiança do princípio até o fim;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'como é dito: Hoje, se ouvirdes a sua voz, não endureçais os vossos corações, como na provocação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Porque alguns, mesmo ouvindo, provocaram-no à ira, mas não todos aqueles que saíram do Egito por meio de Moisés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'E contra quais ele se indignou por quarenta anos? Não foi contra os que pecaram, cujos corpos caíram no deserto?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'E a quem ele jurou que não entrariam no seu repouso, senão aos que foram desobedientes?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Assim vemos que não puderam entrar por causa da incredulidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Temamos, pois, para que, havendo sido deixada a promessa de entrar no seu repouso, não pareça que algum de vós tenha ficado para trás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Pois também a nós foi pregado o evangelho, assim como a eles; mas a palavra da pregação nada lhes aproveitou, porque não estava combinada com a fé naqueles que a ouviram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Porque nós, os que cremos, entramos no repouso, como ele disse: Então jurei na minha ira: “Eles não entrarão no meu repouso”; ainda que as suas obras já estivessem terminadas desde a fundação do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Pois, em certo lugar, ele disse assim a respeito do dia sétimo: E Deus repousou no sétimo dia de todas as suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'E, outra vez neste texto: Não entrarão no meu repouso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Portanto, uma vez que resta alguns entrarem no repouso, e que aqueles a quem primeiramente foi pregado o evangelho não entraram por causa da desobediência,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'outra vez ele determina um certo dia, o “hoje”, dizendo por meio de Davi muito tempo depois (como já foi dito): Hoje, se ouvirdes a sua voz, não endureçais os vossos corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Pois se Josué tivesse lhes dado repouso, ele não teria falado depois a respeito de outro dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Portanto, ainda resta um repouso como o do sábado para o povo de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Pois aquele que entrou no seu repouso também repousou das suas obras, assim como Deus das suas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Procuremos, pois, entrar naquele repouso; para que ninguém caia no mesmo exemplo de desobediência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Porque a palavra de Deus é viva e eficaz, e mais afiada do que toda espada de dois gumes, e que penetra até a divisão da alma e do espírito, das juntas e das medulas, e é apta para julgar os pensamentos e intenções do coração.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'E não há criatura alguma encoberta diante dele; ao contrário, todas as coisas estão nuas e expostas aos olhos daquele a quem temos de prestar contas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Já que temos um grande Sumo Sacerdote, Jesus, o Filho de Deus, que passou através dos céus, mantenhamos firme a nossa declaração de fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Pois não temos um Sumo Sacerdote que não possa se compadecer das nossas fraquezas; mas sim, um que foi provado em tudo, conforme a nossa semelhança, mas sem pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Portanto, acheguemo-nos com confiança ao trono da graça, para que possamos receber misericórdia e encontrar graça para sermos socorridos no tempo adequado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Pois todo sumo sacerdote tomado dentre os homens é constituído em prol das pessoas nas coisas relativas a Deus, para apresentar tanto ofertas como sacrifícios pelos pecados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'e ele é capaz de se compadecer dos ignorantes e dos errados, pois ele mesmo também está rodeado de fraqueza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'E, por causa desta fraqueza,ele tem o dever de apresentar oferenda, tanto pelos pecados do povo, como também de si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'E ninguém toma para si esta honra, a não ser aquele que é chamado por Deus, como Arão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Assim também Cristo não glorificou a si mesmo para se fazer Sumo Sacerdote; mas sim, àquele que lhe disse: Tu és meu Filho, eu hoje te gerei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Como também diz em outro texto: Tu és Sacerdote para sempre, segundo a ordem de Melquisedeque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Ele, nos dias de seu corpo carnal, ofereceu com grande clamor e lágrimas, tanto orações como súplicas para aquele que podia o livrar da morte, e foi ouvido por causa da devoção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Ainda que fosse o Filho, ele aprendeu a obediência por meio das coisas que sofreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'E, depois de ter sido consumado, ele foi feito autor da eterna salvação a todos os que lhe obedecem;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'e nomeado por Deus como Sumo Sacerdote, segundo a ordem de Melquisedeque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Nosso comentário a respeito disso é extenso e difícil de explicar, porque vos tornastes negligentes para ouvir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Pois, pelo tempo, vós já devíeis ser mestres; porém novamente tendes necessidade de serdes ensinados os princípios básicos das palavras de Deus; e vos fizestes como se precisásseis de leite, e não de alimento sólido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Pois qualquer um que depende de leite é inexperiente na palavra da justiça; porque ainda é um bebê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Mas o alimento sólido é para os maduros, os quais, pelo costume, têm os sentidos treinados para discernirem tanto o bem como o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Portanto deixemos os tópicos elementares da doutrina de Cristo, e prossigamos adiante até a maturidade, sem lançarmos de novo o fundamento da conversão de obras mortas, e da fé em Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'da doutrina dos batismos, da imposição das mãos, da ressurreição dos mortos, e do juízo eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'E isso faremos, se Deus permitir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Pois é impossível que os que uma vez foram iluminados, e experimentaram o dom celestial, e foram feitos participantes do Espírito Santo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'e experimentaram a boa palavra de Deus, e os poderes do mundo futuro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'e então caíram, outra vez renová-los para o arrependimento, porque estão novamente crucificando o Filho de Deus para si mesmos, e o expondo à vergonha pública.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Pois a terra que absorve a chuva que com frequência vem sobre ela, e produz vegetação proveitosa para aqueles por quem e lavrada, recebe a bênção de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Contudo, se ela produz espinhos e abrolhos, é reprovada, e perto está da maldição. O seu fim é ser queimada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Mas, ainda que estejamos falando assim, quanto a vós mesmos, amados, confiamos melhores coisas, relacionadas à salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Pois Deus não é injusto para se esquecer da vossa obra, e do trabalho do amor que mostrastes para com o nome dele, quando servistes aos santos, e continuais a servir.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Mas desejamos que cada um de vós mostre o mesmo empenho até o fim, para que a vossa esperança seja completa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'a fim de que não vos torneis negligentes, mas sim, imitadores dos que pela fé e pela paciência herdam as promessas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Pois Deus, quando prometeu a Abraão, como ninguém maior havia por quem jurar, jurou por si mesmo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'dizendo: Certamente muito te abençoarei, e muito te multiplicarei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'E assim, esperando pacientemente, Abraão obteve a promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Pois as pessoas juram por alguém maior, e o juramento como confirmação é o fim de todo conflito entre elas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Assim Deus, querendo mostrar mais abundantemente a imutabilidade de sua intenção aos herdeiros da promessa, garantiu com um juramento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'a fim de que, por meio de duas coisas imutáveis, nas quais é impossível que Deus minta, nós, que buscamos refúgio, tenhamos encorajamento para agarrar a esperança posta diante de nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Temos essa esperança como uma segura e firme âncora da alma, que entra ao interior, além do véu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'onde, como precursor, Jesus entrou para nosso benefício, pois ele se tornou Sumo Sacerdote para sempre, segundo a ordem de Melquisedeque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Porque este Melquisedeque, rei de Salém, sacerdote do Deus Altíssimo, o qual se encontrou com Abraão, que estava retornando da matança dos reis, e o abençoou;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'a quem também Abraão deu o dízimo de tudo; primeiramente significa Rei de justiça, e depois também rei de Salém, que é, rei de paz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'sem pai, sem mãe, sem genealogia, sem ter princípio de dias, nem fim de vida; porém, sendo feito semelhante ao Filho de Deus, permanece sacerdote para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Considerai, pois, como ele era grande, a quem até o patriarca Abraão deu o dízimo dos despojos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'E, realmente, os que dentre os filhos de Levi recebem o sacerdócio têm ordem, segundo a Lei, de receberem os dízimos do povo, isto é, dos seus irmãos, mesmo sendo eles também descendentes de Abraão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Mas aquele que não é contado na genealogia deles recebeu dízimos de Abraão, e abençoou ao que tinha as promessas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Ora, sem contradição alguma, o menor é abençoado pelo maior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Em um caso, homens mortais recebem dízimos; mas no outro, aquele de quem se dá testemunho de que vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'E, por assim dizer, até Levi, que recebe os dízimos, pagou dízimos através de Abraão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'pois ele ainda estava no corpo de seu ancestral quando Melquisedeque se encontrou com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Portanto, se a perfeição tivesse sido de fato pelo sacerdócio Levítico (pois sob ele o povo recebeu a Lei), que mais necessidade havia de se levantar outro Sacerdote segundo a ordem de Melquisedeque, e não ser chamado segundo a ordem de Arão?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Pois, ao se mudar o sacerdócio, necessariamente também se faz mudança de Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Porque aquele de quem estas coisas são ditas pertence a outra tribo, da qual ninguém serviu ao altar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'visto ser evidente que o nosso Senhor é procedente de Judá, tribo da qual Moisés nada falou a respeito de sacerdócio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'E isso ainda é muito mais evidente se, à semelhança de Melquisedeque, levanta-se outro sacerdote,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'que foi constituído, não conforme a Lei de um mandamento carnal, mas sim, conforme o poder de uma vida indestrutível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Pois assim ele dá testemunho: Tu és Sacerdote para sempre, segundo a ordem de Melquisedeque.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Porque há uma revogação do mandamento anterior, por causa da sua fraqueza e inutilidade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'pois a Lei não tornou perfeito nada. Porém, uma esperança melhor é introduzida, e por meio dela nos aproximamos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'E isso não foi feito sem juramento (pois os outros se tornaram sacerdotes sem juramento,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'mas ele foi estabelecido com um juramento daquele que lhe disse: O Senhor jurou, e não se arrependerá: Tu és Sacerdote para sempre, segundo a ordem de Melquisedeque).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Assim, Jesus foi feito fiador de um pacto ainda melhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Dos outros, são muitos os que se tornaram sacerdotes, pois pela morte foram impedidos de continuar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'mas ele, porque permanece para sempre, tem um sacerdócio definitivo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Portanto, ele também pode salvar de maneira completa os que se aproximam de Deus por meio dele, visto que ele vive para sempre para interceder por eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Pois nos era conveniente tal Sumo Sacerdote: santo, inocente, incontaminado, separado dos pecadores, e feito mais elevado que os céus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'que não precisasse, como os sumos sacerdotes, de oferecer sacrifícios diariamente, primeiramente pelos seus próprios pecados, e depois pelos do povo. Pois ele fez isto de uma vez por todas quando ofereceu a si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Porque a Lei constitui por sumos sacerdotes homens que têm fraqueza; mas a palavra do juramento, que veio depois da Lei, constitui o Filho, que se tornou perfeito para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Ora, o ponto-chave do que falamos é que temos um Sumo Sacerdote que está sentado à direita do trono da Majestade nos céus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'servidor do Santuário, e do verdadeiro Tabernáculo, que Senhor ergueu, e não o homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Pois todo sumo sacerdote é constituído para apresentar tanto ofertas como sacrifícios; por isso era necessário que também este tivesse alguma coisa a oferecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Mas, se ele ainda estivesse na terra, nem sequer seria sacerdote, já que ainda há os sacerdotes que apresentam as ofertas segundo a Lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Esses servem a um esboço, uma sombra das coisas celestiais, como Moisés foi divinamente avisado, antes de construir o Tabernáculo. Porque Deus disse: Olha, faze tudo conforme o modelo que te foi mostrado no monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Mas agora Jesus obteve um ofício mais relevante, como é também Mediador de um melhor pacto, que está firmado em melhores promessas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Pois, se aquele primeiro tivesse sido infalível, nunca haveria se buscado lugar para o segundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Porque, enquanto Deus repreendia os do povo, disse-lhes: Eis que vêm dias, diz o Senhor, que, sobre o povo de Israel e sobre o povo de Judá, estabelecerei um novo pacto;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'não conforme o pacto que fiz com os seus ancestrais no dia em que eu os tomei pelas mãos, para os tirar da terra do Egito. Pois não permaneceram naquele meu pacto, e parei de lhes dar atenção, diz o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Este, pois, é o pacto que farei com o povo de Israel depois daqueles dias, diz o Senhor: Porei minhas leis nas mentes deles, e as escreverei em seus corações. Eu serei o Deus deles, e eles serão o meu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'E não terão de ensinar cada um ao seu próximo, ou ao seu irmão, dizendo: “Conhece ao Senhor”; porque todos me conhecerão, desde o menor deles até o maior.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Pois serei misericordioso com as suas injustiças, e não mais me lembrarei dos seus pecados e das suas transgressões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Quando ele disse: “Novo pacto”, ele tornou o primeiro ultrapassado. Ora, o que se torna ultrapassado e envelhece está perto de desaparecer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'O primeiro pacto também tinha ordenanças de culto, e o santuário terrestre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Pois um tabernáculo foi preparado, o primeiro, em que havia o candelabro, a mesa, e os pães da proposição. Esse é chamado o Santo Lugar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Mas após o segundo véu estava o tabernáculo que se chama Santo dos Santos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'que tinha o incensário de ouro, e a arca do pacto, toda coberta de ouro. Nela estavam: o vaso de ouro contendo o maná, a vara de Arão que florescera, e as tábuas do pacto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'E acima dela, os querubins de glória, que faziam sombra ao propiciatório. Acerca dessas coisas não é oportuno agora falar em detalhes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Ora, estando estas coisas assim preparadas, os sacerdotes entram a todo tempo no primeiro tabernáculo, para cumprirem as atividades de culto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Mas no segundo, somente o sumo sacerdote, uma vez por ano, não sem sangue, que oferece por si mesmo, e pelos pecados de ignorância do povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Desta maneira, o Espírito Santo dá a entender que o caminho para o Santuário não havia sido revelado enquanto o primeiro Tabernáculo ainda estava de pé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Esse é uma figura para o tempo presente, em que são oferecidos ofertas e sacrifícios que não podem, quanto a consciência, tornar perfeito a quem faz o serviço;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'pois consistem somente em comidas e bebidas, e vários lavamentos, e ordenanças para o corpo, que foram impostas até o tempo da correção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mas quando veio Cristo, o Sumo Sacerdote dos bens futuros, por meio de um Tabernáculo maior e mais perfeito, não feito por mãos, isto é, não desta criação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'ele entrou de uma vez por todas no Santuário, e obteve uma redenção eterna, não pelo sangue de bodes e bezerros, mas sim, pelo seu próprio sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Pois, se o sangue de touros e bodes, e as cinzas de uma novilha espalhadas sobre os imundos, santifica para a purificação do corpo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'quanto mais o sangue do Cristo que, pelo Espírito eterno, ofereceu a si mesmo, imaculado, a Deus, purificará a vossa consciência das obras mortas, para servirdes ao Deus vivo!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'E por isso ele é o Mediador de um Novo Testamento, a fim de que, com a ocorrência de uma morte para redenção das transgressões sob o primeiro Testamento, os que foram chamados recebam a promessa da herança eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Pois onde há um testamento, é necessário que ocorra a morte do testador;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'porque um testamento se confirma nos mortos, visto que não é válido enquanto o testador vive.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Por isso o primeiro testamento também não foi consagrado sem sangue;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Porque, depois de Moisés haver pronunciado a todo o povo todo mandamento segundo a Lei, ele tomou o sangue de bezerros e de bodes, com água, lã purpúrea, e hissopo, e aspergiu, tanto o próprio livro, como todo o povo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'dizendo: Este é o sangue do pacto que Deus ordenou para vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'E semelhantemente aspergiu com o sangue o Tabernáculo, e todos os utensílios do serviço de culto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Segundo a Lei, quase todas as coisas são purificadas com sangue, e sem derramamento de sangue não há perdão de pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Portanto era necessário que os esboços das coisas que estão nos céus fossem purificados com esses sacrifícios; mas as próprias coisas celestiais, com sacrifícios melhores que esses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Pois Cristo não entrou num santuário feito por mãos, mera figura do verdadeiro; mas sim, no próprio Céu, para agora comparecer por nós diante da face de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Também não entrou para oferecer a si mesmo muitas vezes, como o sumo sacerdote entra a cada ano no santuário com sangue alheio;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, '(de outra maneira lhe seria necessário padecer muitas vezes desde a fundação do mundo), mas agora, no fim dos tempos, ele se manifestou de uma vez por todas para aniquilar o pecado pelo sacrifício de si mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'E, como está ordenado aos seres humanos morrerem uma vez, e depois disso, o juízo,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'assim também Cristo, que se ofereceu uma vez para tirar os pecados de muitos, aparecerá pela segunda vez, sem pecado, aos que o esperam, para a salvação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Pois, como a Lei tem uma sombra dos bens futuros, e não a própria imagem das coisas, ela nunca pode, por meio dos mesmos sacrifícios que se oferecem a cada ano, continuamente, tornar perfeitos os que se aproximam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Caso contrário, deixariam de ser oferecidos, pois os adoradores, uma vez purificados, não teriam mais consciência alguma de pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Porém nesses sacrifícios a cada ano se faz uma nova lembrança dos pecados,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'porque é impossível que o sangue de touros e de bodes tire pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Por isso que, quando ele entrou no mundo, disse: Sacrifício e oferta não quiseste, mas me preparaste um corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Ofertas de queima e ofertas pelo pecado não te agradaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Então eu disse: “Eis-me aqui; (no rolo do livro está escrito de mim) venho para fazer a tua vontade, ó Deus”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Depois de ter dito acima: “Sacrifício, oferta, ofertas de queima, e ofertas pelo pecado não quiseste, nem te agradaram”, (os quais se oferecem segundo a Lei),');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'então disse: “Eis-me aqui, venho para fazer a tua vontade, ó Deus”. Assim, ele cancela o primeiro pacto,para estabelecer o segundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Pela sua vontade somos santificados por meio da oferta sacrificial do corpo de Jesus Cristo, feita de uma vez por todas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Todo sacerdote comparece a cada dia para servir e oferecer muitas vezes os mesmos sacrifícios, que nunca podem tirar os pecados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Mas Jesus,depois que ofereceu um sacrifício pelos pecados, assentou-se para sempre à direita de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'e espera desde então, até que os seus inimigos sejam postos por escabelo dos seus pés.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Pois com uma só oferta ele aperfeiçoou para sempre os que são santificados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'E também o Espírito Santo nos dá testemunho acerca disso; pois, depois de haver anteriormente dito:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Este é o pacto que farei com eles depois daqueles dias, diz o Senhor: Porei minhas leis em seus corações, e as escreverei em suas mentes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Então ele diz: E não mais me lembrarei dos seus pecados e das suas transgressões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Ora, onde há perdão dessas coisas, não há mais oferta pelo pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Portanto, irmãos, já que temos a confiança de entrar no Santuário pelo sangue de Jesus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'pelo caminho novo e vivo que ele consagrou para nós através do véu, isto é, pela sua carne;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'e já que temos um grande Sacerdote sobre a casa de Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'aproximemo-nos com um coração sincero em plena certeza de fé, tendo os corações aspergidos e purificados da má consciência, e o corpo lavado com água pura;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'mantenhamos firme a esperança que declararmos ter, sem abalo algum, pois aquele que prometeu é fiel;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'e sejamos atenciosos uns para com os outros, a fim de incentivar o amor e as boas obras;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'não abandonando a nossa reunião, como é o costume de alguns. Ao contrário, encorajemos uns aos outros, e tanto mais quanto vedes aquele dia se aproximando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Pois se nós, depois de havermos recebido o conhecimento da verdade, persistirmos pecando por vontade própria, já não resta mais sacrifício pelos pecados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'em vez disso, certa terrível expectativa de julgamento, e um fogo de indignação que consumirá os adversários.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Se alguém que rejeita a Lei de Moisés morre sem misericórdia com base na palavra de duas ou três testemunhas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'de quanto pior castigo vós pensais que será julgado merecedor aquele que pisou o Filho de Deus, menosprezou) o sangue do Testamento no qual ele foi santificado, e insultou o Espírito da graça?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Pois nós conhecemos aquele que disse: A vingança é minha; eu retribuirei, diz o Senhor. E outra vez: O Senhor julgará o seu povo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Cair nas mãos do Deus vivo é algo terrível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Lembrai-vos, porém, dos dias passados, em que, depois de serdes iluminados, suportastes grande combate de aflições,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'quando, em parte, fostes expostos em público tanto a insultos, como a tribulações, e em parte, fostes companheiros daqueles que assim foram tratados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Pois também vos compadecestes das minhas prisões, e com alegria aceitastes a espoliação dos vossos bens, pois sabeis em vós mesmos que tendes nos Céus um bem melhor e permanente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Portanto, não rejeiteis a vossa confiança, que tem uma grande recompensa;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'pois precisais de paciência, a fim de que, depois que houverdes feito a vontade de Deus, recebais o que foi prometido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Pois ainda um pouquinho de tempo, e aquele que vem virá, e não tardará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Mas o justo viverá pela fé; e se ele retroceder, a minha alma não tem prazer nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Mas nós não somos dos que retrocedem para a perdição, mas sim dos que creem para a conservação da alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Ora, a fé é a certeza das coisas que se esperam, e a prova das coisas que não se veem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Pois por ela os antigos obtiveram testemunho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Pela fé entendemos que o universo foi aprontado pela palavra de Deus, de maneira que as coisas que se veem não foram feitas de algo visível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Pela fé, Abel ofereceu a Deus melhor sacrifício do que Caim; por isso obteve testemunho de que era justo, pois Deus testemunhou de suas ofertas; e mesmo estando morto, ainda fala por meio dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Pela fé, Enoque foi transportado para não experimentar a morte; e não foi achado, porque Deus havia o transportado; pois antes da sua transportação ele obteve testemunho de ter agradado a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Ora, sem fé é impossível agradar a Deus. Pois é necessário que aquele que se aproxima de Deus creia que ele existe, e que ele é recompensador dos que o buscam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Pela fé, Noé, divinamente advertido das coisas que ainda se não viam, temeu; e, para salvamento de sua família construiu a arca. Por meio da fé ele condenou o mundo, e foi feito herdeiro da justiça segundo a fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Pela fé, Abraão, quando foi chamado para ir ao lugar que havia de receber por herança, obedeceu, e saiu sem que soubesse aonde ia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Pela fé, ele habitou na terra de promessa, como em terra que não fosse sua, morando em tendas com Isaque e com Jacó, herdeiros com ele da mesma promessa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Pois ele esperava a cidade que tem fundamentos firmes, da qual o arquiteto e construtor é Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Pela fé, também, a própria Sara recebeu a capacidade de conceber descendência, e já na idade avançada ela deu à luz, pois considerou fiel aquele que havia prometido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Assim, de um que estava à beira da morte, nasceu uma descendência numerosa como as estrelas do céu, e incontável como a areia na praia do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Permanecendo na fé, todos esses morreram sem receberem as promessas. Mas as viram de longe, creram, e felicitaram-se nelas, declarando que eram estrangeiros e peregrinos na terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Pois os que dizem tais coisas mostram claramente que estão buscando a sua própria pátria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Ora, se estivessem pensando naquela de onde saíram, eles tinham oportunidade de voltar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Mas agora desejam uma melhor, isto é, a celestial. Por isso Deus não se envergonha deles, de ser chamado o Deus deles, porque já lhes preparou uma cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Pela fé, Abraão, quando foi provado, ofereceu Isaque; aquele que havia recebido as promessas ofereceu o seu único filho,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'do qual foi dito: Em Isaque será chamada a tua descendência.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Abraão considerou que Deus era poderoso até para ressuscitar Isaque dos mortos; de onde também, de forma figurada, ele o recuperou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Pela fé, Isaque abençoou Jacó e Esaú quanto às coisas futuras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Pela fé, Jacó, enquanto morria, abençoou a cada um dos filhos de José, e adorou apoiado sobre a ponta do seu cajado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Pela fé, José, no fim de sua vida, mencionou a saída dos filhos de Israel, e deu ordem acerca dos seus ossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Pela fé, Moisés, quando nasceu, foi escondido três meses pelos seus pais, pois viram que o menino era belo, e não se intimidaram com o mandamento do rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Pela fé, Moisés, sendo já crescido, recusou ser chamado filho da filha de faraó;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'pois preferiu ser maltratado com o povo de Deus a ter por um tempo o prazer do pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Ele considerou que as humilhações por causa de Cristo eram riquezas maiores que os tesouros no Egito; pois sua atenção estava fixada na recompensa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Pela fé, ele deixou o Egito sem temer a ira do rei, pois perseverou como que vendo aquele que é invisível.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Pela fé, ele celebrou a Páscoa e o derramamento do sangue, para que o destruidor dos primogênitos não os tocasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Pela fé, atravessaram o mar Vermelho, como que por terra seca, o que, quando os Egípcios tentaram, afogaram-se.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Pela fé, os muros de Jericó caíram, depois de serem rodeados por sete dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Pela fé, Raabe, a prostituta, não pereceu com os incrédulos, pois acolheu em paz os espias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'E que mais direi? Pois me faltará tempo se eu contar a respeito de Gideão, Baraque, e também de Sansão, Jefté, Davi, e também de Samuel e dos profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Pela fé, esses venceram reinos, exercitaram justiça, alcançaram promessas, fecharam bocas de leões,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'apagaram o poder do fogo, escaparam do fio de espada, da fraqueza tiraram forças, tonaram-se fortes na batalha, puseram em fuga os exércitos dos estrangeiros;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'As mulheres receberam de volta os seus mortos pela ressurreição; e outros foram torturados, não aceitando a soltura, para alcançarem uma melhor ressurreição;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'e outros experimentaram provação de insultos e açoites, e até correntes e prisões;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'foram apedrejados, serrados, tentados, morreram pela espada; andaram vestidos de peles de ovelhas e de cabras; necessitados, afligidos, maltratados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(o mundo não era digno deles) andando sem rumo em desertos, montanhas, covas, e nas cavernas da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'E todos esses, mesmo tendo testemunho pela fé, não alcançaram a promessa,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'pois Deus havia preparado algo melhor para nós, para que, sem nós, eles não fossem aperfeiçoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Portanto nós também, posto que estamos rodeados por uma tão grande nuvem de testemunhas, deixemos toda sobrecarga, e o pecado envolvente, e corramos com paciência a corrida que nos está proposta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'olhando para Jesus, Autor e aperfeiçoador da fé. Ele, pela alegria que lhe estava proposta, suportou a cruz, desprezando a humilhação, e se assentou à direita do trono de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Considerai, pois, aquele que suportou tal hostilidade dos pecadores contra si mesmo, para que não fiqueis exaustos, nem vossas almas se debilitem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Enquanto lutais contra o pecado, ainda não resististes ao sangue,)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'mas já vos esquecestes do encorajamento que ele fala convosco como a filhos: Meu filho, não desprezes a disciplina do Senhor, nem te canses de ser reprendido por ele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'pois o Senhor disciplina a quem ama, e açoita a todo filho a quem recebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Se suportais a disciplina, Deus vos trata como filhos; pois que filho há a quem o pai não discipline?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Mas se estais sem disciplina, da qual todos são feitos participantes, sois então ilegítimos, e não filhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Além disso, tivemos os pais de nossa carne como disciplinadores, e nós os respeitávamos. Por acaso não nos sujeitaremos muito mais ao Pai dos espíritos, a fim de vivermos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Pois eles nos disciplinavam, por um pouco de tempo, como bem lhes parecia; mas Deus nos disciplina para proveito nosso,a fim de sermos participantes da sua santidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'De fato, enquanto presente, nenhuma disciplina parece ser motivo de alegria, mas sim de sofrimento; mas depois produz fruto pacífico de justiça aos que por ela foram exercitados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Portanto, levantai as mãos cansadas e os joelhos frouxos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'e “fazei caminhos retos para os vossos pés”, para que o que está manco não se desloque, mas sim, que sare.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Buscai a paz com todos, e a santificação, sem a qual ninguém verá o Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Vigiai com empenho para que ninguém perca de receber da graça de Deus; para não acontecer que alguma raiz de amargura brote, seja incômoda, e muitos sejam contaminados por ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Ninguém seja pecador sexual, ou profano como Esaú, que por uma refeição vendeu o seu direito de primogenitura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Pois vós sabeis que depois, quando ele quis herdar a benção, foi rejeitado, porque não achou lugar para arrependimento, ainda que com lágrimas o tenha buscado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Porque não chegastes a um monte palpável, aceso com fogo, e à escuridão, às trevas, e à tempestade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'ao som da trombeta, e à voz das palavras, que os que a ouviam, rogaram que não mais se lhes falasse palavra alguma;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(pois não podiam suportar o que lhes era ordenado: Se até um animal tocar o monte, seja apedrejado ou perfurado com um dardo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'E a visão era tão terrível, que Moisés disse: Estou assombrado e tremendo).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Mas vós chegastes ao monte Sião, à cidade do Deus vivo, a Jerusalém celestial, e aos muitos milhares de anjos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'à universal congregação e igreja dos primogênitos inscritos nos Céus, e a Deus, o Juiz de todos, e aos espíritos dos justos já aperfeiçoados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'e a Jesus, o Mediador de um Novo Testamento, e ao sangue da aspersão, que fala melhores coisas que o de Abel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Tende o cuidado de não rejeitardes ao que fala. Pois, se não escaparam aqueles que rejeitaram ao que os advertia divinamente na terra, muito menos nós, se nos desviarmos daquele que nos adverte dos Céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'A voz dele fez a terra tremer naquela ocasião, mas agora prometeu, dizendo: Ainda uma vez faço tremer não somente a terra, mas também o Céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Esta expressão,“Ainda uma vez”, mostra a remoção das coisas abaladas, como coisas criadas, para que as inabaláveis permaneçam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Por isso, já que recebemos um Reino inabalável, mantenhamos a graça, e por ela sirvamos a Deus de maneira que o agrade, com devoção e temor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'pois o nosso Deus é um fogo consumidor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Permaneça o amor fraternal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Não vos esqueçais de mostrardes hospitalidade, porque através dela alguns, sem saber, acolheram anjos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Lembrai-vos dos prisoneiros, como se estivésseis presos com eles; e dos que são maltratados, como se vós mesmos também estivessem sendo em vossos corpos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'O matrimônio seja honrado entre todos, e o leito conjugal sem contaminação; mas Deus julgará os pecadores sexuais e os adúlteros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'A vossa maneira de viver seja sem ganância, contentando-vos com as coisas que tendes. Pois ele disse: Não te deixarei, nem te desampararei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'De maneira que devemos ter a confiança de dizer: O Senhor é meu ajudador; não temerei o que o ser humano poderá fazer a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Lembrai-vos de vossos líderes, que vos falaram a palavra de Deus. Observai o resultado da maneira como viveram, e imitai a fé deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Cristo é o mesmo ontem, hoje, e eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Não vos deixeis levar por doutrinas várias e estranhas. Pois bom ao coração é ser fortificado pela graça, e não por alimentos, que não resultaram em proveito algum aos que com eles se ocuparam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Temos um altar, do qual os que servem no tabernáculo não têm autoridade para comer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'porque os corpos dos animais, cujo sangue pelo pecado é trazido ao Santuário pelo Sumo sacerdote, são queimados fora do acampamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Por isso também Jesus, para santificar o povo pelo seu próprio sangue, sofreu fora do portão da cidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Assim, saiamos até ele, fora do acampamento, carregando a sua humilhação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Pois não temos aqui cidade permanente, mas buscamos a futura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Portanto, por meio dele, ofereçamos continuamente sacrifício de louvor a Deus, isto é, o fruto dos lábios que declaram honra ao seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'E não vos esqueçais de fazer o bem e de compartilhar, pois Deus se agrada com tais sacrifícios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Obedecei aos vossos líderes, e sede submissos a eles,pois eles vigiam pelas vossas almas, como os que prestarão contas delas; para que o façam com alegria, e não gemendo, porque isso não vos seria proveitoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Orai por nós; porque confiamos que temos boa consciência, e desejamos nos comportar da maneira correta em tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'E eu vos rogo ainda mais que façais isto, para que eu vos seja restituído mais depressa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'O Deus da paz, que, pelo sangue do eterno Testamento eterno, voltou a trazer dentre os mortos o grande Pastor das ovelhas, o nosso Senhor Jesus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'vos aperfeiçoe em toda boa obra, para fazerdes a sua vontade, operando em vós o que é agradável diante dele, por meio de Jesus Cristo, a quem seja a glória para todo o sempre. Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Eu vos rogo, porém, irmãos, que suportai esta palavra de exortação; pois eu vos escrevi de maneira breve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Sabei que o irmão Timóteo já está solto. Se ele vier depressa, com ele eu vos verei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Saudai a todos os vossos líderes, e a todos os santos. Os da Itália vos saúdam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'A graça seja com todos vós. Amém. Escrita da Itália para os Hebreus, e enviada por Timóteo');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Tiago, servo de Deus e do Senhor Jesus Cristo, às doze tribos que estão na dispersão, saudações!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Meus irmãos, tende toda alegria quando vos encontrardes em várias provações,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'sabendo que a prova da vossa fé produz perseverança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'E que a perseverança tenha uma realização completa, para que sejais completos e íntegros, faltando em nada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Se algum de vós tem falta de sabedoria, peça a Deus, que concede generosamente a todos sem repreender, e lhe será dada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Porém deves pedi-la em fé, duvidando em nada; pois quem duvida é semelhante à onda do mar que é levada pelo vento, e lançada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Tal pessoa não pense que receberá algo do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'O homem de dupla mentalidade é inconstante em todos os seus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Mas o irmão que é humilde se orgulhe quando é exaltado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'e o que é rico quando é abatido, porque ele passará como a flor da erva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Pois o sol sai com ardor, então seca a erva, a sua flor cai, e a beleza do seu aspecto perece; assim também o rico murchará nos seus caminhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Bendito é o homem que suporta a provação; pois, quando for aprovado, receberá a coroa da vida, que o Senhor prometeu aos que o amam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Ninguém, quando for tentado, diga: “Sou tentado por Deus”; porque Deus não é tentado pelo mal, e ele mesmo tenta ninguém;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Mas cada um é tentado quando é atraído e seduzido pelo seu próprio mau desejo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Depois do mau desejo ter concebido, dá à luz o pecado; e o pecado, quando é completado, gera a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Não vos enganeis, meus amados irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Toda boa dádiva e todo dom perfeito vem do alto, e desce do Pai das luzes, em quem não há mudança nem sombra de variação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Conforme a sua própria vontade, ele nos gerou pela palavra da verdade, para que fôssemos os primeiros frutos dentre as suas criaturas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Portanto, meus amados irmãos, toda pessoa seja pronta para ouvir, tardia para falar, tardia para se irar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'porque a ira humana não cumpre a justiça de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Por isso, rejeitai toda impureza e abundância de malícia, e recebei com mansidão a palavra implantada em vós, que pode salvar as vossas almas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'e sede praticantes da palavra, e não somente ouvintes, enganando a vós mesmos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Pois, se alguém é ouvinte da palavra e não praticante, esse é semelhante a um homem que observa num espelho o seu rosto natural;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'porque observou a si mesmo e saiu, e logo se esqueceu de como era.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Mas aquele que dá atenção à lei perfeita, a da liberdade, e nela persevera, não sendo ouvinte que esquece, mas sim praticante da obra, esse tal será bendito no que fizer.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Se alguém entre vós pensa ser religioso, mas não controla a sua língua, então engana o seu próprio coração, e a religião desse é vã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'A religião pura e não contaminada para com Deus e Pai é esta: visitar os órfãos e as viúvas nas suas aflições, e guardar a si mesmo sem a corrupção do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Meus irmãos, não tenhais a fé do nosso glorioso Senhor Jesus Cristo em acepção de pessoas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Pois se algum homem entrar na vossa congregação com anéis de ouro e trajes preciosos, e também entrar algum pobre com roupa de pouco valor,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'e derdes atenção ao que usa o traje precioso, e lhe disserdes: “Senta aqui, num lugar de honra”, mas ao pobre disserdes: “Fica ali em pé” ou “senta-te aqui abaixo do apoio dos meus pés”,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'por acaso não fizestes discriminação entre vós mesmos, e não vos tornastes juízes de maus pensamentos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Ouvi, meus amados irmãos: acaso Deus não escolheu os pobres deste mundo para serem ricos na fé, e herdeiros do reino que ele prometeu aos que o amam?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Vós, porém, desonrastes o pobre. Acaso não são os ricos que vos oprimem e vos arrastam para os tribunais?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Não são eles que blasfemam o bom nome pelo qual sois chamados?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Se de fato cumpris a lei real conforme a Escritura: Amarás o teu próximo como a ti mesmo, bem fazeis;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Mas se fazeis acepção de pessoas, cometeis pecado, e sois denunciados pela lei como transgressores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Pois quem guarda toda a lei, mas falha em um item, tornou-se culpado de todos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Porque aquele que disse: “Não cometerás adultério”, também disse: “Não matarás”. Portanto, se não cometeres adultério, mas matares, te tornaste um transgressor da lei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Falai assim e procedei assim: como os que serão julgados pela lei da liberdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'porque o julgamento será sem misericórdia sobre quem não agiu com misericórdia; mas a misericórdia triunfa sobre o julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Meus irmãos, qual é o proveito se alguém disser que tem fé, mas não tiver obras? Acaso a fé pode salvá-lo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'E se um irmão ou irmã estiverem nus, e necessitarem do alimento diário,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'e algum de vós lhes disser: “Ide em paz, aquecei-vos e saciai-vos”; e não lhes derdes as coisas necessárias ao corpo, qual é o proveito disso?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Assim também a fé, se não tiver obras, é morta em si mesma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Mas alguém dirá: Tu tens fé e eu tenho obras. Mostra-me a tua fé pelas tuas obras, e eu, pelas minhas obras, te mostrarei a minha fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Tu crês que há um só Deus? Fazes bem; os demônios também creem, e estremecem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Ó tolo, queres te certificar de que a fé sem as obras é morta?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Acaso não foi o nosso pai Abraão justificado pelas obras, quando ofereceu o seu filho Isaque sobre o altar?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Vês que a fé cooperou com as suas obras, e que pelas obras a fé foi aperfeiçoada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'E cumpriu-se a Escritura que diz: “E Abraão creu em Deus, e isso lhe foi considerado como justiça”, e ele foi chamado amigo de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vedes, então, que o ser humano é justificado pelas obras, e não somente pela fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'E de igual modo não foi também a prostituta Raabe justificada pelas obras, quando recebeu os mensageiros, e ajudou para que saíssem por outro caminho?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Pois assim como o corpo sem o espírito está morto, assim também a fé sem obras está morta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Meus irmãos, não sejais muitos de vós mestres, porque sabeis que receberemos um julgamento mais rigoroso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Pois todos tropeçamos em muitas coisas. Se alguém não tropeça no que diz, tal homem é completo, e também capaz de refrear todo o corpo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Eis que pomos freios nas bocas dos cavalos para nos obedecerem, e assim manobramos todo o corpo deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Vede também os navios, sendo tão grandes, e levados por impetuosos ventos, são manobrados com um pequeníssimo leme para onde quer que queira o impulso daquele que dirige.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Assim também a língua é um pequeno membro, mas se orgulha de grandes coisas. Vede como um pequeno fogo incendeia um grande bosque!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'A língua também é um fogo, o mundo da injustiça; assim a língua está posta entre os nossos membros, contaminando o corpo todo, inflamando o curso da natureza humana, e sendo inflamada pelo inferno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Pois toda espécie, tanto de animais selvagens como de aves, tanto de répteis como de animais marinhos, é dominível e tem sido dominada pela espécie humana;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Mas nenhum ser humano consegue dominar a língua; ela é um mal difícil de se controlar, cheia de veneno mortal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Com ela bendizemos o Deus e Pai, e com ela amaldiçoamos os seres humanos, que são feitos à semelhança de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Da mesma boca procedem benção e maldição. Meus irmãos, isso não deve ser assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Acaso uma fonte jorra do mesmo manancial água doce e água amarga?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Meus irmãos, pode a figueira dar azeitonas, ou a videira figos? Assim também, nenhuma fonte dá tanto água salgada como doce.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Quem dentre vós for sábio e inteligente, que mostre pela boa conduta as suas obras em humildade de sabedoria.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Porém, se tendes amarga inveja e rivalidade no vosso coração, não vos orgulheis, nem mintais contra a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Esta sabedoria não é a que vem do alto, mas sim, terrena, animal, e demoníaca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Pois onde há inveja e rivalidade, ali há perturbação e toda obra perversa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Mas a sabedoria do alto é primeiramente pura, depois pacífica, moderada, tratável, cheia de misericórdia e de bons frutos, imparcial e sem hipocrisia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'E o fruto da justiça é semeado na paz para os que praticam a paz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'De onde vêm as guerras e brigas entre vós? Acaso não vêm disto, das vossas cobiças que guerreiam nos membros do vosso corpo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Cobiçais, e nada tendes; matais e sois invejosos, mas não conseguis obter; combateis e guerreais, mas nada tendes, porque não pedis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Pedis, e não recebeis, porque pedis mal, para gastardes nos vossos prazeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Adúlteros e adúlteras, não sabeis que a amizade do mundo é inimizade contra Deus? Portanto, quem quiser ser amigo do mundo constitui-se inimigo de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ou pensais ser em vão que a Escritura diz: “O Espírito que habita em nós ansia com ciúmes?”');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Porém ele concede uma graça maior. Por isso diz: Deus resiste aos soberbos, mas concede graça aos humildes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Sujeitai-vos, pois, a Deus; resisti ao diabo, e ele fugirá de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Aproximai-vos de Deus, e ele se aproximará de vós. Limpai as vossas mãos, pecadores, e vós de dupla mentalidade, purificai os vossos corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Reconhecei vossas misérias, lamentai e chorai. Torne-se o vosso riso em pranto, e a vossa alegria em tristeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humilhai-vos diante do Senhor, e ele vos exaltará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Irmãos, não faleis mal uns dos outros. Quem fala mal de um irmão, e julga o seu irmão, fala mal da lei, e julga a lei. E se julgas a lei, não és um cumpridor da lei, mas, sim, juiz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Um só é o Legislador, que pode salvar e destruir. Quem és tu, que julgas o outro?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Atenção! Vós que dizeis: “Hoje ou amanhã iremos a uma tal cidade, e lá passaremos um ano negociando e lucrando”;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'mas não sabeis o amanhã. Pois o que é a vossa vida? É um vapor, que por pouco tempo aparece, e logo se desvanece.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Em vez disso, devíeis dizer: Se o Senhor quiser, e vivermos, faremos isso ou aquilo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Mas agora vos orgulhais nas vossas presunções; todo orgulho como esse é maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Portanto, quem sabe fazer o bem, e não o faz, comete pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Cuidado, ricos! Chorai e gemei pelas vossas misérias que virão sobre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'As vossas riquezas estão podres, e as vossas roupas estão comidas pela traça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'O vosso ouro e a vossa prata estão enferrujados, e a ferrugem deles será testemunho contra vós, e comerá a vossa carne como fogo. Acumulastes tesouro para os dias finais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Eis que o salário dos trabalhadores que colheram nos vossos campos, que por vós foi retido fraudulentamente, está clamando; e os clamores dos que fizeram a colheita chegaram os ouvidos do Senhor dos exércitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vivestes em luxo sobre a terra, e tivestes prazeres. Engordastes os vossos corações como num dia de matança.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Condenastes e matastes o justo; ele não vos resistiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Portanto, irmãos, sede pacientes até a vinda do Senhor. Eis que o lavrador espera o precioso fruto da terra, aguardando-o com paciência, até que receba a primeira chuva e a chuva tardia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Sede vós também pacientes. Fortalecei os vossos corações, porque a vinda do Senhor está próxima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Irmãos, não vos queixeis uns contra os outros, para que não sejais condenados. Eis que o Juiz está à porta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Meus irmãos, tomai como exemplo de aflições e de paciência os profetas que falaram no nome do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Eis que considerarmos benditos os que suportam o sofrimento. Ouvistes da paciência de Jó, e vistes o resultado da parte do Senhor; porque o Senhor é muito misericordioso, e cheio de compaixão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Mas, acima de tudo, meus irmãos, não jureis, nem pelo céu nem pela terra, nem façais qualquer outro juramento. Mas que de vós o sim seja sim, e o não, não; para que não caiais em condenação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Alguém entre vós está aflito? Ore. Alguém está contente? Cante louvores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Alguém entre vós está doente? Chame os anciãos da igreja, e orem sobre ele, ungindo-o com azeite no nome do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'E a oração da fé sarará o doente, e o Senhor o levantará; e se houver cometido pecados, lhe serão perdoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Confessai as vossas culpas uns aos outros, e orai uns pelos outros, para que sejais curados. A oração de um justo muito pode efetuar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elias era tão humano quanto nós, e orou insistentemente para não chover; e não choveu sobre a terra por três anos e seis meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'E orou outra vez, e o céu deu chuva, e a terra produziu o seu fruto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Irmãos, se algum entre vós houver se desviado da verdade, e alguém o converter,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'saiba que aquele que converter um pecador do erro de seu caminho, salvará uma alma da morte, e cobrirá uma multidão de pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pedro, apóstolo de Jesus Cristo, aos forasteiros que estão espalhados em Ponto, Galácia, Capadócia, Ásia e Bitínia,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'escolhidos segundo o pré-conhecimento de Deus Pai, por meio da santificação do Espírito, para a obediência e a aspersão do sangue de Jesus Cristo. Que a graça e a paz vos sejam multiplicadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo. Segundo sua grande misericórdia, ele nos regenerou para uma esperança viva, por meio da ressurreição de Jesus Cristo dentre os mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'E o resultado disso é uma herança incorruptível, incontaminável, e que não pode ser enfraquecida. Ela está guardada nos céus para vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'que pela fé estais guardados no poder de Deus para a salvação, pronta para se revelar no último tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Nisso vos alegrais, ainda que agora seja necessário que estejais por um pouco de tempo entristecidos com várias provações,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'para que a prova de vossa fé, muito mais preciosa que o ouro que perece (mesmo sendo provado pelo fogo), seja achada em louvor, honra, e glória, na revelação de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'A ele, sem terdes visto, vós o amais. Ainda que não estejais o vendo agora, mas crendo nele, vós estais alegres com júbilo indescritível e glorioso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Assim estais alcançando o resultado da vossa fé: a salvação das vossas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Dessa salvação os profetas que profetizaram a respeito da graça direcionada a vós procuraram entender, e com empenho investigaram,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'procurando saber qual era o tempo ou ocasião que o Espírito de Cristo dentro deles indicava, quando dava prévio testemunho dos sofrimentos de Cristo e das glórias seguintes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'A eles foi revelado que não foi para eles mesmos, mas sim para nós, que eles prestaram serviço com estas coisas. E agora, elas vos foram anunciadas pelos que, pelo Espírito Santo enviado do céu, vos pregaram o Evangelho. Tais coisas os anjos desejam atentamente observar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Portanto, preparai as vossas mentes, sede sóbrios, e esperai completamente na graça que vos será trazida na revelação de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'E, como filhos obedientes, não vos conformeis com os maus desejos do passado, de quando éreis ignorantes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Ao contrário; assim como aquele que vos chamou é santo, sede vós também santos em todo o vosso comportamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Pois está escrito: Sede santos, porque eu sou santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'E, se vós chamais de Pai aquele que, sem acepção de pessoas, julga segundo a obra de cada um, vivei em temor o tempo de vossa peregrinação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'e sabei que não foi por coisas destrutíveis, como prata ou ouro, que fostes resgatados do vosso vão comportamento que recebestes de vossos pais,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'mas sim pelo sangue precioso, como de um cordeiro sem falha e sem contaminação: o sangue de Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Ele já era conhecido desde antes da fundação do mundo, mas foi manifesto nestes últimos tempos por causa de vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'que, por meio dele, credes em Deus, que o ressuscitou dos mortos e lhe deu glória, para que a vossa fé e esperança estejam em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Uma vez que purificastes vossas almas na obediência da verdade por meio do Espírito, para o sincero amor fraternal, amai-vos intensamente uns aos outros com um coração puro,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'visto que nascestes de novo, não de semente que perece, mas sim imperecível, pela viva palavra de Deus, que permanece para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Pois toda carne é como a erva, e toda glória humana como a flor da erva. A erva se seca, e sua flor cai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'mas a palavra do Senhor permanece para sempre.E esta é a palavra que foi evangelizada entre vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Abandonai, portanto, toda malícia, toda enganação, fingimentos, invejas, e todas as falas maldosas,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'e desejai ansiosamente, como bebês recém-nascidos, o leite da Palavra, não falsificado, para que por meio dele estejais crescendo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'se, de fato, já experimentastes que o Senhor é bom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Aproximai-vos dele, que é uma pedra viva, rejeitada pelos seres humanos, mas escolhida e preciosa para Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Também vós, como pedras vivas, sois edificados como casa espiritual e sacerdócio santo, para oferecerdes sacrifícios espirituais, agradáveis a Deus por meio de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Por isso também está contido na Escritura: Eis que eu ponho em Sião uma pedra principal de esquina, escolhida e preciosa. Quem nela crer de maneira nenhuma será envergonhado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Assim, para vós, que credes, ela é preciosa. Mas para os rebeldes: A pedra que os construtores rejeitaram, essa se tornou a principal de esquina,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'assim como: pedra de tropeço, e pedra que leva à queda. Eles tropeçam na palavra por serem rebeldes. Para isso eles foram destinados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mas vós sois a geração escolhida, o sacerdócio real, a nação santa, e o povo adquirido; a fim de que anuncieis as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Antes, vós não éreis povo, mas agora sois povo de Deus. Antes, não havíeis recebido misericórdia, mas agora recebestes misericórdia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Amados, como a peregrinos e estrangeiros, eu vos peço que vos abstenhais dos desejos carnais, que batalham contra a alma,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'e que tenhais um bom comportamento vosso entre os pagãos; para que, naquilo que de vós, como de malfeitores, falam mal, no dia da visitação glorifiquem a Deus por causa das vossas boas obras que tiverem visto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Portanto sujeitai-vos a toda autoridade humana, por causa do Senhor; seja ao rei, como superior;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'seja aos governantes, como enviados por ele, com o objetivo de castigar os malfeitores, e de conceder honra aos que fazem o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Pois esta é a vontade de Deus, que, ao fazerdes o bem, caleis a ignorância dos homens tolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Comportai-vos como pessoas livres, mas não useis a liberdade como pretexto para a malícia. Em vez disso, sede como servos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Honrai a todos: amai aos irmãos, temei a Deus, honrai ao rei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Servos, sujeitai-vos com todo temor aos vossos senhores, não somente aos bons e brandos, mas também aos que maltratam.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Pois coisa agradável é se alguém, por causa da consciência a respeito de Deus, experimente dores, sofrendo injustamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Afinal, que mérito há em suportar serdes espancados por cometerdes pecado? Contudo, se, quando fazeis o bem, sois afligidos e suportais, isso é a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Pois para isto fostes chamados, porque também Cristo sofreu por nós, deixando-nos exemplo, para que sigais os seus passos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Ele não cometeu pecado, nem engano foi achado em sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Quando o insultavam, ele não insultava de volta. Quando sofria, ele não ameaçava; em vez disso, entregava-se ao que julga de maneira justa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Ele levou nossos pecados em seu próprio corpo sobre o madeiro; para que nós, estando mortos para os pecados, vivamos para a justiça. Pela ferida dele fostes sarados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Porque vós éreis como ovelhas desviadas do caminho; mas agora vós estais convertidos ao Pastor e Supervisor de vossas almas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Semelhantemente vós, esposas, estejais sujeitas aos próprios maridos, para que, ainda que alguns não obedeçam à Palavra, por meio do comportamento das esposas, sem palavra, sejam ganhos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'quando eles observarem o vosso comportamento puro e com temor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'A vossa beleza não seja a exterior, como tranças de cabelos, joias de ouro, ou vestuário,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'mas sim, a pessoa interior no coração, o embelezamento incorruptível de um espírito manso e tranquilo, que é precioso diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Pois assim também se embelezavam antigamente as mulheres santas, que esperavam em Deus, e eram sujeitas aos seus maridos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Dessa maneira Sara obedecia a Abraão, chamando-lhe de senhor. Vós sois filhas dela se fizerdes o bem e não temerdes espanto algum.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Semelhantemente vós maridos, convivei com elas com entendimento, dando honra à mulher, como a vaso mais fraco, como sendo elas e vós juntamente herdeiros da graça da vida; a fim de que as vossas orações não sejam impedidas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'E por fim, sede todos de uma mesma mentalidade, compassivos, tenhais amor pelos irmãos, e sede misericordiosos e benevolentes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Não retribuais o mal com mal, ou insulto com insulto; ao contrário, bendizei, sabendo que para isto fostes chamados, para que herdeis a bênção.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Pois: quem quer amar a vida e ver dias bons, refreie sua língua do mal, e que seus lábios não falem engano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Afaste-se do mal, e faça o bem; busque a paz, e siga-a.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Porque os olhos do Senhor estão sobre os justos, e seus ouvidos atentos às suas orações; mas a face do Senhor é contra os que fazem o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'E quem vos fará mal se fordes adeptos do bem?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Porém, mesmo se sofrerdes por causa da justiça, benditos sois. Não tenhais medo deles, nem vos perturbeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Mas santificai a Deus como Senhor em vossos corações; e estai sempre preparados para responder com mansidão e respeito a todo aquele que vos pedir a razão da esperança que há em vós,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'tendo uma boa consciência; para que, naquilo que falam mal de vós como malfeitores, os que insultam o vosso bom comportamento em Cristo sejam envergonhados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Pois é melhor que sofrais fazendo o bem, se assim a vontade de Deus quer, do que fazendo o mal.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Porque também Cristo sofreu uma vez pelos pecados, o justo pelos injustos; para que nos levasse a Deus. Ele estava, de fato, morto na carne, mas vivificado pelo Espírito,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'no qual ele também foi pregar aos espíritos em prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Estes são os que antigamente foram rebeldes, quando uma vez a paciência de Deus aguardava nos dias de Noé, enquanto era preparada a arca. Nela, poucas almas (isto é, oito) foram salvas por meio da água.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Esta é uma representação do batismo, que agora também nos salva, não como remoção da sujeira do corpo, mas sim como o pedido de boa consciência a Deus, por meio da ressurreição de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Ele está à direita de Deus, depois de haver subido ao céu; e os anjos, as autoridades, e os poderes estão sob o seu comando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Visto que Cristo sofreu por nós na carne, armai-vos também com o mesmo modo de pensar, pois quem sofreu na carne terminou com o pecado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'para que, no resto do tempo na carne, não viva mais segundo os maus desejos humanos, mas sim segundo a vontade de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Pois já basta, no tempo passado da vida, termos feito a vontade dos pagãos, e andado em promiscuidades, desejos maliciosos, bebedeiras, orgias, festas de embriaguez, e abomináveis idolatrias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Como eles estranham vós não agirdes como eles, que correm em busca da extrema devassidão, por isso falam mal de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Eles terão de prestar contas ao que está pronto para julgar os vivos e os mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Pois por isso o evangelho também foi pregado aos mortos, para que, mesmo que tenham sido julgados na carne segundo os critérios humanos, vivam em espírito segundo os critérios de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'O fim de todas as coisas está próximo; portanto sede sóbrios, e vigiai em orações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Mas, acima de tudo, tende fervoroso amor uns para com os outros; porque o amor cobrirá uma multidão de pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Proporcionai hospitalidade uns aos outros, sem murmurações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Cada um sirva aos outros segundo o dom que recebeu, como bons administradores da variada graça de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Se alguém fala, que seja como as palavras de Deus; se alguém serve, que sirva segundo a força que Deus dá; a fim de que em tudo Deus seja glorificado por meio de Jesus Cristo. E a ele pertencem a glória e o poder para todo o sempre, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Amados, não estranheis o fogo ardente que vem sobre vós para vos provar, como se algo estranho estivesse vos acontecendo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Em vez disso, alegrai-vos em serdes participantes das aflições de Cristo; para que, também na revelação de sua glória vos alegreis com júbilo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Se vós sois insultados por causa do nome de Cristo, benditos sois; porque o Espírito da glória e de Deus repousa sobre vós; o qual por eles é insultado, mas por vós é glorificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Porém nenhum de vós sofra como homicida, ladrão, malfeitor, ou como alguém que se intromete em assuntos alheios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Mas se sofre como cristão, não se envergonhe; ao contrário, glorifique a Deus por isso;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Pois já é tempo do julgamento começar pela casa de Deus; e se é primeiro conosco, qual será o fim daqueles que são desobedientes ao Evangelho de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'E se o justo se salva com dificuldade, em que situação aparecerá o ímpio e pecador?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Portanto, os que sofrem segundo a vontade de Deus, confiem suas almas ao fiel Criador, fazendo o bem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Aos anciãos da igreja que estão entre vós, eu, que sou ancião como eles, e testemunha dos sofrimentos de Cristo, e participante da glória que se revelará, seriamente peço:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Pastoreai o rebanho de Deus que está entre vós, não por obrigação, mas sim voluntariamente; não por ganância, mas sim com sincera prontidão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'nem como que dominando os que estão aos vossos cuidados, mas sim como exemplos ao rebanho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'E quando o Pastor Principal aparecer, vós recebereis a indestrutível coroa da glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Semelhantemente vós, jovens, sede sujeitos aos anciãos; e todos vós sede sujeitos uns aos outros, revestidos de humildade; pois: Deus resiste aos soberbos, mas dá graça aos humildes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Humilhai-vos, pois, debaixo da poderosa mão de Deus, para que ele vos exalte no tempo adequado,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'lançando sobre ele toda a vossa ansiedade; porque ele tem cuidado de vós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Sede sóbrios! Vigiai! Pois o vosso adversário, o diabo, anda ao redor, rugindo como um leão, buscando a quem possa devorar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Resisti a ele, firmes na fé; sabendo que as mesmas aflições acontecem com os vossos irmãos no mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'E o Deus de toda graça, que nos chamou para a sua eterna glória em Cristo Jesus, depois de sofrerdes um pouco, ele vos aperfeiçoe, confirme, fortifique, e estabeleça fundamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'A ele sejam a glória e o poder para todo o sempre. Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Por Silvano, vosso fiel irmão, como o considero, eu vos escrevi brevemente, exortando e dando testemunho de que esta é a verdadeira graça de Deus, na qual estais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Saúda-vos a igreja escolhida convosco, que está na Babilônia, e também o meu filho Marcos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Saudai-vos uns aos outros com beijo de amor. A paz seja com todos vós que estais em Cristo Jesus. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simão Pedro, servo e apóstolo de Jesus Cristo, aos que obtiveram conosco a igualmente preciosa fé pela justiça de nosso Deus e Salvador Jesus Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Graça e paz vos seja multiplicada pelo conhecimento de Deus, e de Jesus nosso Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Como seu divino poder ele tem nos dado tudo o que pertence à vida e à devoção divina, por meio do conhecimento daquele que nos chamou à glória e virtude;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Pelas quais nos são dadas grandíssimas e preciosas promessas, para que por meio delas sejais participantes da natureza divina, tendo escapado da corrupção que há no mundo pelo mau desejo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'E por isso mesmo, pondo todo o empenho, acrescentai a vossa fé virtude; e à virtude, conhecimento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'E ao conhecimento, domínio próprio; e ao domínio próprio, paciência; e à paciência, devoção divina;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'E à devoção divina, amor fraternal; e ao amor fraternal, amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Porque se em vós existirem e abundarem estas coisas, elas não vos deixarão ociosos nem estéreis no conhecimento de nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Porque aquele em quem não há estas coisas é cego, nada vendo de longe, tendo se esquecido da purificação de seus antigos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Portanto, irmãos, procurai ainda mais confirmar vosso chamamento e escolha da parte de Deus; porque fazendo isso nunca tropeçareis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Porque assim vos será abundantemente fornecida a entrada no reino eterno de nosso Senhor e Salvador Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Por isso eu não deixarei de sempre vos relembrar destas coisas, ainda que as saibais, e estejais firmes na verdade presente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'E eu considero justo, enquanto eu estiver neste tabernáculo, de vos despertar com relembranças;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Sabendo que breve está a saída do meu meu tabernáculo, conforme também nosso Senhor Jesus Cristo tem revelado a mim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Mas também procurarei que depois de minha partida vós sejais capazes de ter lembrança destas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Porque nós não vos anunciamos o poder e vinda de nosso Senhor Jesus Cristo seguindo mitos criados pela inteligência humana, mas sim como testemunhas oculares de sua grandiosidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Porque de Deus Pai ele recebeu honra e glória, tendo sido lhe enviada tal voz de magnífica glória: Este é meu amado Filho, em quem me agrado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'E nós ouvimos esta voz enviada do Céu, estando nós com ele no santo monte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'E temos a muito confiável palavra dos profetas; a qual vós fazeis bem ao prestardes atenção, como a uma luz que ilumina em lugar escuro, até que o dia clareie e a estrela da manhã se levante em vossos corações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Sabendo primeiramente isto: que nenhuma profecia da Escritura é de interpretação particular.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Porque a profecia jamais foi produzida pela vontade humana, mas os santos homens de Deus falaram conduzidos pelo Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'E também houve falsos profetas entre o povo, assim como também haverá falsos instrutores entre vós, que disfarçadamente introduzirão heresias de perdição, e negarão ao Senhor que os comprou, trazendo sobre eles mesmos repentina destruição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Muitos seguirão suas perdições, e por meio deles o caminho da verdade será insultado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'E por ganância, eles vos farão de mercadoria com palavras falsamente inventadas; sobre os quais desde muito tempo não está a condenação sem efeito, e sua perdição não cochila.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Porque se Deus não perdoou aos anjos que pecaram, em vez disso lançando-os no inferno, entregou-os às cadeias da escuridão, tendo sido reservados para o julgamento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Nem perdoou ao mundo antigo, mas guardou a Noé, anunciador da justiça, com outros sete, trazendo o dilúvio sobre o mundo dos ímpios;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'E condenou as cidades de Sodoma e Gomorra à destruição, reduzindo-as a cinza, e pondo-as como exemplo para os que vivessem impiamente;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'E livrou ao justo Ló, que estava cansado do corrupto modo de viver dos maus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(Porque, enquanto aquele justo habitava entre eles, todo dia ele atormentava sua justa alma, ao ver e ouvir as injustas obras deles).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Assim o Senhor sabe livrar os devotos das tentações, e reservar aos injustos para o dia do julgamento, para serem punidos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Porém principalmente aos que segundo a carne andam em mau desejo de impureza, e desprezam as autoridades; atrevidos, agradando a si mesmos, não tendo medo de insultar as coisas dignas de glórias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Ainda que até os anjos, sendo maiores em força e poder, não trazem juízo insultuoso contra elas diante do Senhor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Mas estes, como animais irracionais, que seguem a natureza, gerados para a prisão e destruição, insultando aquilo que não entendem, perecerão na corrupção deles;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Recebendo o pagamento da injustiça, tendo como prazer seus maus desejos durante o dia, sendo manchas e defeitos, tendo prazer em seus enganos, participando do banquete convosco;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Tendo os olhos cheios de adultério, e nunca parando de pecar; iludindo as almas inconstantes, tendo o coração exercitado na ganância, filhos da maldição;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Que, tendo deixado o caminho direito, se desviaram, seguindo o caminho de Balaão, filho de Bosor, que amou o pagamento da injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Mas ele teve a repreensão de sua transgressão; o mudo animal de jugo, falando em voz humana, impediu a loucura do profeta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Estes são fontes sem água, nuvens levadas pela tempestade; para os quais a escuridão das trevas está reservada para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Porque ao falarem coisas muito arrogantes de vaidade, iludem com os maus desejos da carne, e com perversões, aqueles que já tinham realmente escapado dos que andam no erro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Prometendo-lhes liberdade, mas sendo eles mesmos servos da corrupção; porque aquele de quem alguém é vencido, do tal também se faz servo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Porque se, por causa do conhecimento do Senhor e Salvador Jesus Cristo, tiverem escapado das imundícies do mundo, e novamente se envolverem nelas, e forem vencidos, o fim será pior que o começo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Porque melhor teria lhes sido se não tivessem conhecido o caminho da justiça do que, depois de conhecerem, terem se desviado do santo mandamento que havia lhes sido entregue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Mas isto lhes sobreveio conforme um verdadeiro provérbio, que diz: O cão voltou ao seu próprio vômito; e a porca lavada voltou ao chiqueiro da lama.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Amados, eu já vos escrevo esta segunda carta, em ambas as quais eu desperto vosso sincero entendimento por meio da relembrança;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Para que vos lembreis das palavras que anteriormente foram ditas pelos santos profetas, e do nosso mandamento, dos apóstolos do Senhor e Salvador.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Sabendo primeiro isto: que nos últimos dias virão escarnecedores, andando segundo seus próprios maus desejos,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'E dizendo: Onde está a promessa da vinda dele? Pois desde que os pais dormiram, todas as coisas continuam como desde o princípio da criação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Porque eles ignoram isto por sua própria vontade, que pela palavra de Deus desde os tempos antigos é que foram os céus, e que a terra saiu da água, e sobre a água continua.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Pelas quais o mundo anterior foi destruído, coberto com as águas do dilúvio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'E os céus e a terra de agora, pela mesma palavra estão reservados, e são guardados para o fogo até o dia do juízo, e da perdição das pessoas ímpias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Mas amados, desta uma coisa não ignoreis: que um dia para o Senhor é como mil anos, e mil anos como um dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'O Senhor não é tardio em sua promessa (como alguns a consideram tardia); mas ele é paciente para conosco, não querendo que alguns pereçam, mas sim que todos venham ao arrependimento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Mas o dia do Senhor virá como um ladrão durante a noite, no qual os céus se desfarão com grande estrondo, e os elementos queimando se dissolverão, e a terra e as obras que nela há serão queimadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Visto, pois, que todas estas coisas estão para serem desfeitas, de que maneira vós deveis ser em santo comportamento e piedade,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'esperando, e tendo pressa para a vinda do dia de Deus, pelo qual os céus, incendiados, se desfarão, e os elementos, inflamados, se derreterão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Porém, segundo a sua promessa, aguardamos novos céus e nova terra, em que a justiça habita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Por isso, amados, aguardando essas coisas, procurai que por ele sejais achados incontaminados e irrepreensíveis em paz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'E considerai como salvação a paciência de nosso Senhor; assim como também nosso irmão Paulo vos escreveu, segundo a sabedoria que lhe foi dada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Como também em duas as suas cartas, ele fala nelas destas coisas; entre as quais há algumas coisas difíceis de entender, as quais os ignorantes e os inconstantes distorcem, assim como também as outras Escrituras, para a própria perdição deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Portanto vós, amados, sabendo disto com antecedência, guardai-vos para que, pelo engano dos maus, não sejais juntamente arrebatados, e caiais de vossa firmeza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Mas crescei em graça e conhecimento de nosso Senhor e Salvador Jesus Cristo. A ele seja a glória, tanto agora como no dia da eternidade, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'O que era desde o princípio, o que ouvimos, o que vimos com os nossos olhos, o que temos contemplado, e nossas mãos tocaram, quanto à Palavra da vida,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(pois a vida já foi manifesta, e nós a vimos, demos testemunho, e vos anunciamos a vida eterna, que estava com o Pai, e a nós foi manifesta)');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'o que vimos e ouvimos, isso vos anunciamos, para que também vós tenhais comunhão conosco. E a nossa comunhão é com o Pai, e com o seu Filho Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Estas coisas vos escrevemos para que a vossa alegria seja completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'E esta é a mensagem que dele ouvimos, e vos anunciamos: que Deus é luz, e não há nele nada de trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Se dissermos que temos comunhão com ele, e andarmos em trevas, mentimos, e não praticamos a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Porém, se andamos na luz, como ele está na luz, temos comunhão uns com os outros, e o sangue de Jesus Cristo, seu Filho, nos purifica de todo pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Se dissermos que não temos pecado, enganamos a nós mesmos, e a verdade não está em nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Se confessarmos nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Se dissermos que não pecamos, nós o fazemos de mentiroso, e a palavra dele não está em nós.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Meus filhinhos, vos escrevo estas coisas para que não pequeis; mas se alguém pecar, temos um advogado com o Pai: Jesus Cristo, o justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'E ele é o sacrifício para perdão dos nossos pecados; e não somente dos nossos, mas também dos de todo o mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'E nisto sabemos que o conhecemos, se guardamos os seus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Aquele que diz: “Eu o conheço”, mas não guarda os seus mandamentos, é mentiroso, e nele não está a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Mas quem guarda a sua palavra, nele verdadeiramente o amor de Deus tem se aperfeiçoado; nisso sabemos que estamos nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Aquele que diz que está nele também deve andar como ele andou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Irmãos, não vos escrevo um mandamento novo, mas sim o mandamento antigo, que tivestes desde o princípio. Este mandamento antigo é a palavra que ouvistes desde o princípio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Mas também vos escrevo um mandamento novo, que é verdadeiro nele e em vós; pois as trevas passaram, e a verdadeira luz já ilumina.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Aquele que diz que está na luz, e odeia seu irmão, até agora está nas trevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Aquele que ama o seu irmão está na luz, e nele não há motivo algum para pecar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Mas aquele que odeia seu irmão está nas trevas, anda nas trevas, e não sabe para onde vai, pois as trevas lhe cegaram os olhos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Filhinhos, vos escrevo porque pelo nome dele os vossos pecados são perdoados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Pais, vos escrevo porque conheceis aquele que é desde o princípio. Jovens, vos escrevo porque vencestes o maligno. Crianças, vos escrevo porque conheceis o Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Pais, vos escrevi porque conheceis aquele que é desde o princípio. Jovens, vos escrevi porque sois fortes, a palavra de Deus está em vós, e vencestes o maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Não ameis o mundo, nem as coisas que há no mundo. Se alguém ama o mundo, o amor do Pai não está nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Pois tudo o que há no mundo, a cobiça da carne, a cobiça dos olhos, e a ostentação da vida, não é do Pai, mas do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'O mundo passa, e também a sua cobiça; mas aquele que faz a vontade de Deus permanece para sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Filhinhos, é a última hora. E como ouvistes que o anticristo vem, já agora muitos anticristos chegaram. Por isso sabemos que é a última hora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Eles saíram de nós, mas não eram dos nossos, pois se fossem dos nossos, continuariam conosco; mas o que aconteceu foi para tornar claro que todos eles não eram dos nossos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Vós, porém, tendes a unção do Santo, e conheceis todas as coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Eu vos escrevi, não porque não conheceis a verdade, mas sim, porque a conheceis, e porque nenhuma mentira vem da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Quem é o mentiroso, senão aquele que nega que Jesus é o Cristo? Esse é o anticristo, que nega o Pai e o Filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Quem nega o Filho também não tem o Pai; aquele que confessa o filho também tem o Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Portanto o que ouvistes desde o princípio permaneça em vós. Se o que ouvistes desde o princípio permanecer em vós, também permanecereis no Filho e no Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'E esta é a promessa que ele nos prometeu: a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Estas coisas vos escrevi acerca dos que vos tentam vos enganar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'E a unção que recebeste dele continua em vós, e não tendes necessidade de que alguém vos ensine; mas, como a mesma unção vos ensina tudo, e é verdadeira, e não mentira, e como ela vos ensinou, assim nele permanecereis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'E agora, filhinhos, permanecei nele; a fim de que, quando ele se manifestar, tenhamos confiança, e não sejamos envergonhados diante dele na sua vinda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Se sabeis que ele é justo, sabeis que todo aquele que pratica a justiça é nascido dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Vede quão grande amor o Pai tem nos dado, que fôssemos chamados filhos de Deus. Por isso o mundo não nos conhece, pois não conhece a ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Amados, agora somos filhos de Deus, e ainda não está manifesto o que seremos. Porém sabemos que, quando ele se manifestar, seremos semelhantes a ele, pois o veremos como ele é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'E todo aquele que tem nele essa esperança purifica a si mesmo, como também ele é puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Todo aquele que pratica o pecado também pratica injustiça, pois o pecado é injustiça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'E sabeis que ele apareceu para tirar os nossos pecados; e nele não há pecado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Todo aquele que nele permanece não pratica o pecado; todo aquele que costuma pecar não o viu nem o conheceu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Filhinhos, ninguém vos engane. Quem pratica a justiça é justo, assim como ele é justo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Quem pratica o pecado é do diabo, pois o diabo peca desde o princípio. Para isto o Filho de Deus se manifestou, para desfazer as obras do diabo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Todo aquele que é nascido de Deus não pratica o pecado, pois a sua semente reside nele; e não pode praticar o pecado, porque é nascido de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Nisto são reconhecíveis os filhos de Deus, e os filhos do diabo: todo aquele que não pratica a justiça, e não ama o seu irmão, não é de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Pois esta é a mensagem que ouvistes desde o princípio: que nos amemos uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Não sejamos como Caim, que era do maligno, e matou o seu irmão. E por que o matou? Porque as suas obras eram más, e as do seu irmão justas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Meus irmãos, não vos surpreendeis se o mundo vos odeia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Nós sabemos que já passamos da morte para a vida, pois amamos os irmãos. Quem não ama seu irmão permanece na morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Todo aquele que odeia o seu irmão é homicida. E sabeis que nenhum homicida tem a vida eterna habitando nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Nisto conhecemos o amor: ele deu a sua vida por nós. E nós devemos dar as nossas vidas pelos irmãos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Se alguém tiver bens do mundo, e vir o seu irmão em necessidade, e não se compadecer dele, como pode o amor de Deus estar nele?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Meus filhinhos, amemos não de palavra, nem de língua, mas sim com ação e verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'E nisto sabemos que somos da verdade, e teremos segurança nos nossos corações diante dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Pois, se o nosso coração nos condena, maior é Deus que o nosso coração, e conhece tudo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Amados, se nosso coração não nos condena, temos confiança diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'E qualquer coisa que pedirmos, dele receberemos; porque guardamos os seus mandamentos, e fazemos o que lhe agrada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'E este é o seu mandamento: que creiamos no nome do seu Filho Jesus Cristo, e nos amemos uns aos outros, como ele nos mandou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'E a pessoa que guarda os seus mandamentos está nele, e ele nela. E nisto sabemos que ele está em nós: pelo Espírito que ele nos deu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Amados, não creiais em todo espírito, mas provai se os espíritos são da parte de Deus; porque muitos falsos profetas têm vindo ao mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Nisto conhecereis o Espírito de Deus: todo espírito que confessa que Jesus Cristo veio em carne é de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'e todo espírito que não confessa que Jesus Cristo veio em carne não é de Deus; e este é o do anticristo, do qual já ouvistes que virá, e que já agora está no mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Filhinhos, vós sois de Deus, e tendes vencido esses; pois maior é o que está em vós do que o que está no mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Eles são do mundo, por isso falam do mundo, e o mundo os ouve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Nós somos de Deus. Aquele que conhece Deus ouve-nos; aquele que não é de Deus não nos ouve. Nisto conhecemos o Espírito da verdade e o espírito do erro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Amados, nos amemos uns aos outros; porque o amor é de Deus, e todo aquele que ama é nascido de Deus e conhece a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Aquele que não ama não conhece a Deus, porque Deus é amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Nisto se manifestou o amor de Deus por nós: que Deus enviou o seu Filho unigênito ao mundo, para que por meio dele vivamos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Nisto está o amor, não que nós tenhamos amado a Deus, mas sim, que ele nos amou, e enviou seu Filho como sacrifício para perdão dos nossos pecados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Amados, se Deus assim nos amou, também nós devemos amar uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Ninguém jamais viu Deus; se nos amamos uns aos outros, Deus está em nós, e o amor dele em nós é aperfeiçoado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Nisto sabemos que estamos nele, e ele em nós, porque ele nos deu do seu Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'E vimos e damos testemunho de que o Pai enviou o Filho para ser Salvador do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Todo aquele que confessar que Jesus é o Filho de Deus, Deus está nele, e ele em Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'E nós conhecemos e cremos no amor que Deus tem por nós. Deus é amor, e quem está no amor está em Deus, e Deus nele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Nisto o amor é aperfeiçoado em nós, para que no dia do juízo tenhamos confiança, pois, como ele é, assim somos nós neste mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'No amor não há medo; pelo contrário, o perfeito amor expulsa o medo; pois o medo envolve castigo; e o que teme não está aperfeiçoado em amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Nós o amamos, porque ele nos amou primeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Se alguém diz: “Eu amo a Deus”, e odeia seu irmão, é mentiroso. Pois quem não ama seu irmão, ao qual viu, como pode amar a Deus, a quem nunca viu?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'E dele temos este mandamento: quem ama a Deus, ame também seu irmão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Todo aquele que crê que Jesus é o Cristo é nascido de Deus; e todo aquele que ama ao que gerou, também ama ao que dele é nascido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Nisto sabemos que amamos os filhos de Deus: quando amamos a Deus, e guardamos os seus mandamentos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Pois este é o amor de Deus: que guardemos os seus mandamentos. E os seus mandamentos não são pesados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Pois todo aquele que é nascido de Deus vence o mundo; e esta é a vitória que vence o mundo: a nossa fé.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Quem é o que vence o mundo, senão aquele que crê que Jesus é o Filho de Deus?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Este é aquele que veio por água e sangue: Jesus, o Cristo. Não só pela água, mas pela água e pelo sangue. E o Espírito é o que lhe dá testemunho, porque o Espírito é a verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Pois são três os que dão testemunho no céu: o Pai, a Palavra, e o Espírito Santo; e estes três são um.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'E três são os que testemunham na terra: o Espírito, a água e o sangue; e estes três estão em unidade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Se recebemos o testemunho humano, o testemunho de Deus é maior; pois este é o testemunho de Deus, que testificou de seu Filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Quem crê no Filho de Deus tem testemunho em si mesmo; quem não crê em Deus o fez de mentiroso, porque não creu no testemunho que Deus deu acerca do seu Filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'E este é o testemunho: que Deus nos deu a vida eterna; e essa vida está no seu Filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Quem tem o Filho tem a vida; quem não tem o Filho de Deus não tem a vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Estas coisas escrevi para vós que credes no nome do Filho de Deus, para que saibais que tendes a vida eterna, e que creiais no nome do Filho de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'E esta é a confiança que diante dele: que se pedirmos alguma coisa conforme a sua vontade, ele nos ouve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'E se sabemos que nos ouve em tudo o que pedimos, sabemos que alcançamos as coisas que lhe pedimos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Se alguém vê o seu irmão cometer um pecado que não é para a morte, orará, e lhe dará vida, para os que não pecarem para a morte. Há pecado para a morte, pelo qual não digo que ore.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Toda injustiça é pecado; e há pecado que não é para a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Sabemos que todo aquele que é nascido de Deus não pratica o pecado; mas o que é gerado de Deus guarda a si mesmo, e o maligno não o toca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Sabemos que somos de Deus, e que o mundo todo jaz no maligno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'E sabemos que o Filho de Deus veio, e nos deu entendimento para conhecermos o Verdadeiro; e no Verdadeiro estamos, em seu Filho Jesus Cristo. Este é o verdadeiro Deus, e a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Filhinhos, guardai-vos dos ídolos. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'O ancião, à senhora eleita, e a seus filhos, aos quais eu amo em verdade; e não somente eu, mas também todos os que têm conhecido a verdade;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Por causa da verdade que está em nós, e estará para sempre conosco.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Graça, misericórdia, e paz de Deus Pai, e do Senhor Jesus Cristo, o Filho do Pai, seja convosco em verdade e amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Muito me alegrei por eu ter encontrado alguns de teus filhos andando na verdade, assim como recebemos o mandamento do Pai.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'E agora, senhora, eu te rogo, não como te escrevendo um novo mandamento, mas o que tivemos desde o princípio: que nos amemos uns aos outros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'E este é o amor: que andemos segundo seus mandamentos. E este é o mandamento, como já ouvistes desde o princípio: que nele andeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Porque muitos enganadores têm surgido no mundo que não declaram que Jesus Cristo veio em carne. Este é o enganador e o anticristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Vigiai por vós mesmos, para que não percamos o que trabalhamos; mas sim que recebamos uma recompensa completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Todo aquele que transgride e não continua na doutrina de Cristo não tem a Deus; quem continua na doutrina de Cristo tem tanto ao Pai quanto ao Filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Se alguém vem a vós, e não traz esta doutrina, não recebais em vossa casa, nem o saudeis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Porque quem o saúda compartilha com suas más obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Muitas coisas eu tenho que vos escrever, porém não eu quis fazê-lo com papel e tinta; mas espero vir a vós, e vos falar face a face, para que nossa alegria seja completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Os filhos de tua irmã, a eleita, te saúdam. Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'O ancião, ao amado Gaio, a quem amo em verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Amado, eu desejo que estejas bem em todas as coisas, e que tenhas saúde, assim como bem está a tua alma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Pois muito me alegrei quando irmãos chegaram, e testemunharam da tua verdade, como tu andas na verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Não tenho maior alegria do que esta: a de ouvir que meus filhos andam na verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Amado, tu ages fielmente em tudo o que fazes aos irmãos, inclusive aos forasteiros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Estes, diante da igreja, testemunharam do teu amor; aos quais, tu agirás bem ao supri-los de modo digno da vontade de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Pois foi por causa do Nome dele que partiram em jornada, sem nada aceitar dos gentios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Portanto devemos acolher tais pessoas, para que sejamos cooperadores da verdade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Eu tenho escrito aos da igreja; porém Diótrefes, que busca ser o comandante deles, não nos recebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Por isso, se eu vier, trarei à memória os seus feitos, falando ele contra nós com palavras maliciosas; e não satisfeito com isso, não recebe aos irmãos, proíbe aos que se dispõem a fazer, e os expulsa da igreja.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Amado, não imites o mal, mas sim o bem. Quem faz o bem é de Deus, mas quem faz o mal nunca viu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demétrio tem alcançado bom testemunho de todos, inclusive da própria verdade. Também nós damos testemunho, e vós sabeis que o nosso testemunho é verdadeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Eu tinha muitas coisas para escrever, porém não quero escrever a ti sobre elas com tinta e pena;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'mas espero te ver em breve, e falaremos face a face. Paz seja contigo. Os amigos daqui te saúdam. Saúda os amigos daí, cada um por nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, '');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, servo de Jesus Cristo, e irmão de Tiago, para aqueles que foram chamados, santificados por Deus Pai, e guardados por Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Misericórdia a vós, e a paz e o amor vos sejam multiplicados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Amados, procurando eu vos escrever com todo empenho sobre a nossa salvação comum, eu tive por necessário vos escrever e exortar a batalhar pela fé que de uma vez foi entregue aos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Porque alguns entraram disfarçadamente entre vós, que desde antes estavam escritos para a condenação; pessoas ímpias, que distorcem a graça de Deus em perversão, e negam ao único Soberano Deus e nosso Senhor Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Mas eu quer vos lembrar, sabendo vós disto de uma vez por todas: que o Senhor, tendo liberto o povo para fora da terra do Egito, depois destruiu os que não creram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'E aos anjos que não guardaram sua origem, mas deixaram sua própria habitação, ele os reservou debaixo de grande escuridão em prisões eternas até o julgamento do grande dia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Assim como Sodoma e Gomorra, e as cidades circunvizinhas, que como aquelas, tendo cometido pecados sexuais, e seguido uma carne ilícita, foram postas como exemplo, recebendo a punição do fogo eterno.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Porém estes, também semelhantemente adormecidos, contaminam a carne, e rejeitam a soberania, e insultam as coisas dignas de glórias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Mas Miguel, o arcanjo, quando ele discutia com o diabo, e disputava por causa do corpo de Moisés, não ousou contra ele pronunciar juízo de maldição, porém disse: O Senhor te repreenda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Mas estes insultam tudo aquilo que não conhecem; e tudo o que eles entendem naturalmente, como animais irracionais, nisso eles se corrompem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Ai deles; porque eles entraram pelo caminho de Caim, e se dispuseram ao engano de Balaão por interesse por interesse de lucro, e pereceram pela rebelião de Coré.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Estes são manchas em vossas demonstrações de amor, participando dos banquetes convosco, apascentando a si mesmos sem temor; eles são nuvens sem água, levadas pelos ventos sem direção; são como árvores murchas, infrutíferas, duas vezes mortas e arrancadas pela raiz;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Ondas furiosas do mar, que espumam suas próprias vergonhas; estrelas errantes, para as quais a escuridão das trevas está reservada eternamente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'E Enoque, o sétimo depois de Adão, também profetizou sobre estes, dizendo: Eis que o Senhor veio, com dezenas de milhares de seus santos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Para fazer julgamento contra todos, e reprovar a todos os seus ímpios, por todas as suas obras de irreverência, que impiamente cometeram, e por todas as duras palavras que os ímpios pecadores falaram contra ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Estes são murmuradores, reclamadores, que andam segundo seus próprios maus desejos; e sua s boca s fala m palavras de arrogância, mostrando admiração às pessoas para tirarem proveito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Mas vós, amados, lembrai-vos das palavras que foram preditas pelos apóstolos de nosso Senhor Jesus Cristo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Como eles vos diziam, que no último tempo haveria escarnecedores, que andariam segundo seus próprios desejos ímpios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Estes são os que separam a si mesmos, mundanos, que não têm o Espírito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Mas vós, amados, edificai a vós mesmos em vossa santíssima fé, orando no Espírito Santo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Conservai a vós mesmos no amor de Deus, esperando a misericórdia de nosso Senhor Jesus Cristo para a vida eterna.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'E tende misericórdia de alguns, usando de discernimento;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Mas a outros salvai em temor, arrancando -os do fogo, odiando até a roupa contaminada pela carne.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'E para aquele que é poderoso para vos guardar de tropeçar, e vos apresentar irrepreensíveis com alegria diante de sua glória;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Ao único sábio Deus, nosso Salvador, seja a glória e majestade, poder e autoridade, agora, e para todo o sempre, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Revelação de Jesus Cristo, a qual Deus lhe deu, para mostrar a seus servos as coisas que devem acontecer em breve; e as enviou por meio de seu anjo, e as informou ao seu servo João.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'O qual deu testemunho da palavra de Deus, e do testemunho de Jesus Cristo, e de tudo o que ele viu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Bem-aventurado é aquele que lê, e também os que ouvem as palavras desta profecia, e guardam as coisas nela escritas; porque o tempo está próximo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'João, às sete igrejas que estão na Ásia. Graça e paz sejam convosco, provenientes daquele que é, e que era, e que virá; e dos sete Espíritos que estão diante do trono dele;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'E de Jesus Cristo, que é a fiel testemunha, o primogênito dos mortos, e Chefe dos reis da terra; àquele que nos amou, e em seu sangue nos lavou de nossos pecados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'E nos fez reis e sacerdotes a Deus e seu Pai; a ele seja a glória e o poder para todo o sempre, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Eis que ele vem com as nuvens, e todo olho o verá, até mesmo aqueles que o perfuraram; e todas as tribos da terra lamentarão sobre ele; sim, Amém.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Eu sou o Alfa e o Ômega, o princípio e o fim,Diz o Senhor, que é, e que era, e que virá, o Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Eu, João, (que também sou vosso irmão, e companheiro na aflição, e no Reino, e na paciência de Jesus Cristo), estava na ilha chamada Patmos, por causa da palavra de Deus, e por causa do testemunho de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'No dia do Senhor, eu fui arrebatado em espírito, e atrás de mim eu ouvi uma grande voz, como de trombeta,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Dizendo: Eu sou o Alfa e o Ômega, o primeiro e o último; e o que tu estás vendo, escreve em um livro, e envia às sete igrejas que estão na Ásia: a Éfeso, e a Esmirna, e a Pérgamo, e a Tiatira, e a Sardes, e a Filadélfia, e a Laodiceia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'E eu me virei para ver a voz que tinha falado comigo; e ao me virar, vi sete castiçais de ouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'E no meio dos sete castiçais, um semelhante a o Filho do homem, vestido até os pés de uma roupa comprida, e o tórax envolvido com um cinto de ouro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'E a cabeça e os cabelos dele eram brancos como a lã, brancos como a neve; e seus olhos como chama de fogo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'E os pés dele semelhantes a um metal valioso e reluzente, e ardentes como em fornalha; e a voz dele, como de muitas águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'E tinha em sua mão direita sete estrelas; e de sua boca saía uma espada aguda de dois fios; e seu rosto como o sol brilhando em sua força.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'E quando eu o vi, cai aos pés dele como que morto; e ele pôs sua mão direita sobre mim, e me disse: Não temas; eu sou o primeiro e o último;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Eu sou o que vivo, e fui morto; e eis que eu vivo para todo o sempre; Amém. E eu tenho as chaves do mundo dos mortos, e da morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Escreve as coisas que tens visto, e as que são, e as que estão para acontecer;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'O mistério das sete estrelas, que viste em minha mão direita, e os sete castiçais de ouro: as sete estrelas são os anjos ou mensageiros das sete igrejas; e os sete castiçais que viste, são as sete igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Escreve ao anjo da igreja de Éfeso: Isto diz aquele que tem as sete estrelas em sua mão direita, que anda no meio dos sete castiçais de ouro:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Eu conheço as tuas obras, e teu trabalho, e a tua paciência, e que tu não podes tolerar os maus; e provaste aos que se dizem ser apóstolos e não são; e reconheceste que eles eram mentirosos;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'E suportaste sofrimentos, e tens paciência; e trabalhaste pelo meu nome, e não te cansaste.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Mas eu tenho contra ti, que deixaste o teu primeiro amor.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Então lembra-te de onde tu caíste, e arrepende-te, e faze as primeiras obras; senão em breve eu virei a ti, e tirarei teu castiçal de seu lugar, se tu não te arrependeres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Mas isto tu tens: que odeias as obras dos nicolaítas, as quais eu também odeio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: Ao que vencer, eu lhe darei de comer da árvore da vida, que está no meio do paraíso de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'E escreve ao anjo da igreja dos de Esmirna: Isto diz o o primeiro e o último, que foi morto, e vive:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Eu conheço tuas obras, e aflição, e pobreza (mas tu és rico) e a blasfêmia dos que dizem serem judeus, e não são, mas na verdade são sinagoga de Satanás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Nada temas das coisas que virás a sofrer; eis que o diabo está para lançar alguns de vós em prisão, para que sejais tentados; e vós tereis aflição de dez dias. Sê fiel até a morte, e eu te darei a coroa da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: o que vencer, não sofrerá o dano da segunda morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'E escreve ao anjo da igreja que está em Pérgamo: Isto diz aquele que tem a espada aguda de dois fios:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Eu conheço tuas obras, e onde habitas, que é onde está o trono de Satanás; e tu reténs meu nome, e não negaste minha fé, até mesmo nos dias em que Antipas, que era minha fiel testemunha, o qual foi morto entre vós, onde Satanás habita.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Mas eu tenho algumas poucas coisas contra ti: que tu tens lá aos que retêm a doutrina de Balaão, o qual ensinava a Balaque a lançar tropeço diante dos filhos de Israel, para que comessem dos sacrifícios aos ídolos, e façam pecados sexuais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Assim tu tens também aos que retém a doutrina dos nicolaítas, que eu odeio.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Arrepende-te; senão, em breve virei a ti, e batalharei contra eles com a espada de minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: Ao que vencer, eu lhe darei de comer do maná escondido, e lhe darei uma pedrinha branca, e na pedrinha um novo nome escrito, o qual ninguém conhece, a não ser aquele que o recebe.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'E escreve ao anjo da igreja que está em Tiatira: Isto diz o Filho de Deus, que tem seus olhos como chama de fogo, e seus pés semelhantes a um metal valioso reluzente:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Eu conheço tuas obras, e amor, e serviço, e fé, e tua paciência, e tuas obras, e que as últimas são mais que as primeiras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Mas eu tenho algumas poucas coisas contra ti: que tu deixas a mulher Jezabel, que se diz profetiza, ensinar e enganar meus servos, para que façam pecados sexuais, e comam dos sacrifícios aos ídolos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'E eu dei a ela tempo para que se arrependesse de seu pecado sexual; mas ela não se arrependeu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Eis que eu a lanço a uma cama, e aos que cometem adultério com ela, em grande aflição, se não se arrependerem de suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'E ao filhos deles eu os matarei de morte; e todas as igrejas saberão que eu sou aquele que investigo os rins e os corações; e a cada um de vós eu darei segundo vossas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Mas eu digo a vós, e aos outros que estão em Tiatira, a todos quantos não tem esta dourina, e não conheceram as profundezas de Satanás (como dizem); eu não porei outra carga sobre vós;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Mas o que vós tendes, retende até que eu venha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'E ao que vencer, e guardar minhas obras até o fim, eu lhe darei autoridade sobre as nações;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'E as dominará com vara de ferro; como vasos de oleiro serão quebradas em pedaços; assim como eu também recebi do meu Pai;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'E eu lhe darei a estrela da manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'E escreve ao anjo da igreja que está em Sardes: Isto diz aquele que tem os sete espíritos de Deus, e as sete estrelas: Eu conheço tuas obras; que tu tens nome de que vives, e estás morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sê vigilante, e firma o resto que está a ponto de morrer; porque eu não achei tuas obras completas diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Então lembra-te do que tu tens recebido e ouvido, e guarda, e arrepende-te. Portanto, se tu não vigiares, eu virei sobre ti como ladrão, e tu não saberás a que hora eu virei sobre ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Mas também em Sardo tu tens alguns poucos nomes, ou seja, pessoas que não contaminaram suas roupas, e andarão comigo em roupas brancas, porque são dignos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'O que vencer, este será vestido de roupas brancas; e seu nome em maneira nenhuma riscarei do livro da vida; e eu declararei seu nome diante do meu Pai, e diante de seus anjos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'E escreve ao anjo da igreja que está em Filadélfia: Isto diz o Santo, o Verdadeiro, que tem a chave de Davi; que abre e ninguém fecha; que fecha e ninguém abre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Eu conheço as tuas obras; eis que eu te dei diante de ti uma porta aberta, e ninguém a pode fechar; porque tu tens pouca força, e guardaste minha palavra, e não negaste o meu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Eis que eu entrego alguns da sinagoga de Satanás, dos que dizem ser judeus, e não são, mas mentem; eis que eu farei com que venham, e fiquem prostrados diante dos teus pés, e saibam que eu te amo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Porque tu guardaste a palavra da minha paciência, também eu te guardarei da hora da provação que está para vir sobre todo o mundo, para testar aos que habitam sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Eis que eu venho em breve; guarda o que tu tens, para que ninguém tome tua coroa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Ao que vencer, eu o farei coluna no templo do meu Deus; e dele nunca mais sairá; e sobre ele escreverei o nome do meu Deus, e o nome da cidade do meu Deus, Nova Jerusalém, que desce do céu do meu Deus, e também meu novo nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'E escreve ao anjo da igreja dos laodicenses: Isto diz o Amém, a testemunha fiel e verdadeira, o principal da criação de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Eu conheço as tuas obras, que tu nem és frio, nem quente; melhor seria que tu fosses frio ou quente!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Portanto porque tu és morno, e nem frio nem quente, eu te vomitarei da minha boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Porque tu dizes: Eu sou rico, e tenho me enriquecido, e de nada tenho falta; E não sabes que estás miserável, coitado, pobre, cego e nu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Eu te aconselho a comprar de mim ouro provado do fogo, para que te enriqueças; e roupas brancas, para que te vistas; e a vergonha de tua nudez não apareça; e unge teus olhos com colírio, para que vejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Eu repreendo e castigo a todos quantos eu amo; portanto sê zeloso, e te arrepende.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Eis que eu estou à porta, e bato; se alguém ouvir a minha voz, e abrir a porta, entrarei até ele, e cearei com ele, e ele comigo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Ao que vencer, eu lhe concederei que se sente comigo em meu trono; assim como eu também venci, e me sentei com meu Pai no trono dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Depois destas coisas eu olhei, e eis que uma porta estava aberta no céu; e a primeira voz que eu ouvi, como uma trombeta ao falar comigo, disse: Sobe aqui, e eu te mostrarei as coisas que devem acontecer depois destas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'E logo eu fui arrebatado em espírito; e eis que um trono estava posto no céu, e alguém sentado sobre o trono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'E o que estava sentado era de aparência semelhante à pedra jaspe e sárdio; e o arco colorido celeste estava ao redor do trono, de aparência semelhante à esmeralda.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'E ao redor do trono havia vinte e quatro tronos; e vi sobre os tronos vinte e quatro anciãos vestidos de roupas brancas; e sobre as cabeças deles tinham coroas de ouro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'E do trono saíam relâmpagos, e trovões, e vozes; e sete lâmpadas de fogo ardiam diante do trono, as quais são os sete espíritos de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'E diante do trono havia um mar de vidro, semelhante ao cristal, e no meio do trono, e ao redor do trono, quatro animais cheios de olhos, em frente e atrás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'E o primeiro animal era semelhante a um leão, e o segundo animal semelhante a um bezerro, e o terceiro animal tinha o rosto como de homem, e o quarto animal era como uma águia voando.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'E os quatro animais tinham cada um em si seis asas ao redor, e por dentro eram cheios de olhos; e não tem repouso de dia nem de noite, dizendo: Santo, Santo, Santo é o Senhor Deus, o Todo-Poderoso, que era, e que é, e que virá.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'E quando os animais dão glória, honra, e agradecimento ao que estava sentado sobre o trono, ao que vive para todo o sempre;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Então os vinte e quatro anciãos se prostram diante do que estava sentado sobre o trono, e adoram ao que vive para todo o sempre, e lançam suas coroas diante do trono, dizendo:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Digno és tu, Senhor, de receberes glória, honra e poder; porque tu criaste todas as coisas, e por causa da tua vontade elas são e foram criadas!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'E eu vi na mão direita do que estava sentado sobre o trono um livro escrito por dentro e por fora, selado com sete selos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'E vi um forte anjo, proclamando em alta voz: Quem é digno de abrir o livro, e soltar seus selos?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'E ninguém no céu, nem na terra podia abrir o livro, nem olhar para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'E eu chorei muito, porque ninguém foi achado digno de abrir o livro, nem de o ler, nem olhar para ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'E um dos anciãos me disse: Não chores; eis que o Leão da tribo de Judá, a raiz de Davi, venceu, para abrir o livro e soltar seus sete selos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'E eu olhei, e eis que no meio do trono, e dos quatro animais, e no meio dos anciãos, um Cordeiro que estava como se tivesse sido morto, e tinha sete chifres, e sete olhos, que são os sete espíritos de Deus enviados para toda a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'E ele veio, e tomou o livro da mão direita daquele que estava sentado sobre o trono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'E quando ele tomou o livro, os quatro animais, e os vinte e quatro anciãos se prostraram diante do Cordeiro, tendo cada um harpas, e recipientes de ouro cheios de perfumes, que são as orações dos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'E ele cantavam um novo cântico, dizendo: Digno tu és de tomar o livro, e abrir seus selos; porque tu foste morto, e com teu sangue para Deus nos compraste, de toda tribo, língua, povo, e nação;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'E para nosso Deus tu nos fizeste reis se sacerdotes; e nós reinaremos sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'E eu olhei, e ouvi uma voz de muitos anjos ao redor do trono, e dos animais, e dos anciãos; e o número deles era de centenas de milhões, e milhares de milhares;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Que diziam em alta voz: Digno é o Cordeiro que foi morto, de receber poder, e riquezas, e sabedoria, e força, e honra, e glória, e louvor!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'E eu ouvi toda criatura que está no céu, e na terra, e abaixo da terra, e no mar, e todas as coisas que nelas há, dizendo: Ao que está sentado sobre o trono, e ao Cordeiro, seja o louvor, a honra, a glória, e o poder, para todo o sempre!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'E os quatro animais diziam: Amém!E os vinte e quatro anciãos se prostraram e adoraram ao que vive para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'E eu vi quando o Coreiro abriu um dos selos; e ouvi um dos quatro animais dizendo com voz como de trovão: Vem, e vê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'E eu olhei, e eis um cavalo branco; e o que estava sentado sobre ele tinha um arco; e uma coroa lhe foi dada, e ele saiu como conquistador, e para que conquistasse.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'E quando ele abriu o segundo selo, eu ouvi o segundo animal dizendo: Vem, e vê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'E saiu outro cavalo vermelho; e ao que estava sentado sobre ele foi concedido que tirasse a paz da terra, e que uns aos outros se matassem; e uma grande espada lhe foi dada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'E quando ele abriu o terceiro celo, eu ouvi o terceiro animal dizer: Vem, e vê.E olhei, e eis um cavalo preto, e o que estava sentado sobre ele tinha uma balança na mão dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'E ouvi uma voz no meio dos quatro animais, dizendo: Uma medida de trigo por um dinheiro, e três medidas de cevada por um dinheiro; e não danifiques ao azeite e ao vinho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'E quando ele abriu o quarto selo, eu ouvi a voz do quarto animal dizendo: Vem, e vê.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'E eu olhei, e eis um cavalo amarelo-esverdeado, e o que estava sentado sobre ele, seu nome era Morte; e o mundo dos mortos o seguia. E foi-lhes dada autoridade para matar a quarta parte da terra, com espada, com fome, com morte por doença,e com os animais ferozes da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'E quando ele abriu o quinto selo, eu vi debaixo do altar as almas dos que foram mortos por causa da palavra de Deus, e por causa do testemunho que tinham.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'E clamavam com grande voz, dizendo: Até quando, Santo e Verdadeiro Soberano, não julgas e vingas nosso sangue daqueles que habitam sobre a terra?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'E foram dados a cada um deles compridas roupas brancas; e foi-lhes dito que repousassem ainda um pouco de tempo, até que se completassem os seus companheiros servos e seus irmãos, que ainda viriam a ser mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'E eu vi quando ele abriu o sexto selo, e eis que houve um grande tremor de terra; e o sol se tornou preto como um saco feito de pelos de animais, e a lua se tornou como sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'E as estrelas do céu caíram sobre a terra como a figueira lança de si seus figos verdes, abalada por um grande vento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'E o céu se removeu como um rolo de livro que se enrola; e todos os montes e ilhas se moveram de seus lugares.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'E os reis da terra, e os grandes, e os rigos, e os comandantes, e os poderosos, e todo escravo, e todo livre se esconderam nas cavernas e nas rochas das montanhas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'E diziam aso montes, e às rochas: Caí sobre nós, e escondei-nos do rosto daquele que está sentado sobre o trono, e da ira do Cordeiro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Porque chegou o dia da grande ira dele; e quem pode rá ficar a salvo?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'E depois destas coisas eu vi quatro anjos que estavam sobre os quatro cantos da terra, retendo os quatro ventos da terra, para que nenhum vento soprasse sobre a terra, nem sobre o mar, nem sobre árvore alguma.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'E eu vi outro anjo subir do lado onde o sol nasce, que tinha o selo do Deus vivente, e clamou com grande voz aos quatro anjos, aos quais tinha sido dado poder para danificar a terra e o mar,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Dizendo: Não danifiques a terra, nem o mar, nem as árvores, até que tenhamos selado aos servos do nosso Deus nas testas deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'E ouvi o número dos que foram selados; e cento e quarenta e quatro mil foram selados de todas as tribos dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Da tribo de Judá, doze mil foram selados; da tribo de Rúben, doze mil foram selados; da tribo de Gade, doze mil foram selados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Da tribo de Aser, doze mil foram selados; da tribo de Naftali, doze mil foram selados; da tribo de Manassés, doze mil foram selados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Da tribo de Simeão, doze mil foram selados; da tribo de Levi, doze mil foram selados; da tribo de Issacar, doze mil foram selados;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Da tribo de Zebulom, doze mil foram selados; da tribo de José, doze mil foram selados; da tribo de Benjamim, doze mil foram selados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Depois destas coisas eu olhei, e eis uma grande multidão, a qual ninguém podia contar, de todas as nações, e tribos, e povos, e línguas, que estavam diante do trono e diante do Cordeiro, vestidos de roupas brancas, e com ramos de palmas nas mãos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'E clamavam com grande voz, dizendo: A salvação pertence a nosso Deus, que está sentado sobre o trono, e ao Cordeiro!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'E todos os anjos estavam ao redor do trono, e dos anciãos, e dos quatro animais; e se prostraram sobre seus rostos diante do trono, e adoraram a Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Dizendo: Amém! Sejam louvor, glória, sabedoria, agradecimento, honra, poder, e força a nosso Deus, para todo o sempre, Amém!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'E um dos anciãos respondeu, dizendo-me: Estes que estão vestidos de roupas compridas brancas, quem são? E de onde eles vieram?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'E eu lhe disse: Senhor, tu sabes.E ele me disse: Estes são os que vieram da grande tribulação; e lavaram suas roupas compridas e as branquearam no sangue do Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Por isso eles estão diante do trono de Deus, e servem a ele dia e noite no templo dele; e aquele que está sentado sobre o trono armará sua tenda e habitará com eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Eles não mais terão fome, nem mais terão sede; nem o sol, nem calor algum cairá sobre eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Porque o Cordeiro, que está no meio do trono, os apascentará, e os guiará até fontes vivas de águas; e Deus limpará toda lágrima dos olhos deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'E quando ele abriu o sétimo selo, houve silêncio no céu por cerca de meia hora.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'E eu vi os sete anjos, que estavam diante diante de Deus; e foram lhes dadas sete trombetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'E veio outro anjo, e se ficou junto ao altar, tendo um incensário de ouro; e muitos incensos lhe foram dados, para que oferecesse com as orações de todos os santos sobre o altar de ouro que está diante do trono.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'E a fumaça dos incensos com as orações dos santos subiu desde a mão do anjo até diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'E o anjo tomou o incensário, e o encheu do fogo do altar, e o lançou sobre a terra; e houve vozes, trovões, relâmpagos e terremotos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'E os sete anjos, que tinham as sete trombetas, se prepararam para as tocarem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'E o primeiro anjo tocou sua trombeta; e houve saraiva e fogo misturado com sangue; e foram lançados sobre a terra; e a terça parte das árvores se queimou, e toda a erva verde foi queimada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'E o segundo anjo tocou sua trombeta; e como um grande monte ardendo em fogo foi lançado ao mar; e a terça parte do mar se tornou sangue;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'E morreu a terça parte das criaturas que tinham vida no mar; e a terça parte das embarcações foi destruída.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'E o terceiro anjo tocou sua trombeta; e uma grande estrela caiu do céu ardendo como uma tocha; e ela caiu na terça parte dos rios, e nas fontes de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'E o nome da estrela se chama Absinto; e a terça parte das águas se tornou absinto; e muitos homens morreram por causa das águas, porque elas se tornaram amargas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'E o quarto anjo tocou sua trombeta; e a terça parte do sol foi ferida, e também a terça parte da lua, e a terça parte das estrelas; para que a terça parte deles se escurecesse, e o dia não clareasse pela sua terça parte; e se tornasse semelhante à noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'E olhei, e ouvi um anjo que estava voando pelo meio do céu, dizendo em alta voz: Ai ai ai dos que habitam sobre a terra por causa das demais vozes das trombetas dos três anjos que ainda vão tocar!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'E o quinto anjo tocou sua trombeta; e eu vi uma estrela que caiu do céu sobre a terra; e foi-lhe dada a chave do poço do abismo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'E o poço do abismo foi aberto; e subiu fumaça do poço, como a fumaça de uma grande fornalha; e o sol e o ar se escureceram por causa da fumaça do poço.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'E da fumaça saíram gafanhotos sobre a terra; e foi dado a eles poder como o poder que os escorpiões da terra têm.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'E foi-lhes dito que não fizessem dano à erva da terra, nem a nenhuma planta verde, nem a nenhuma árvore; mas sim somente aos homens que não têm o sinal de Deus em suas testas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'E foi-lhes concedido que não os matassem, mas sim que os atormentassem por cinco meses; e o tormento deles era semelhante ao tormento do escorpião, quando fere ao homem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'E naqueles dias os homens buscarão a morte, e não a acharão; e desejarão morrer, e a morte fugirá deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'E a aparência dos gafanhotos era semelhante à de cavalos preparados para a batalha; e sobre as cabeças deles havia como coroas, semelhantes ao ouro; e seus rostos eram como rostos de homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'E tinham cabelos como cabelos de mulheres; e seus dentes eram como os de leões.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'E tinham couraças como couraças de ferro; e o ruído de suas asas era como o ruído de carruagens de muitos cavalos correndo para a batalha.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'E tinham caudas semelhantes às de escorpiões; e ferrões em suas caudas; e seu poder era de por cinco meses causarem dano aos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'E tinham como rei sobre eles ao anjo do abismo; o nome dele em hebraico é Abadom, e em grego tem por nome Apoliom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Um ai já passou; eis que depois disto ainda vêm dois ais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'E o sexto anjo tocou sua trombeta; e eu ouvi uma voz dos quatro chifres do altar de ouro, que estava diante de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'A qual dizia ao sexto anjo, que tinha a trombeta: Solta os quatro anjos que estão presos junto ao grande rio Eufrates.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'E foram soltos os quatro anjos, que tinham sido preparados para a hora, dia, mês e ano, para matarem a terça parte dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'E o número dos exércitos de cavaleiros era duzentos milhões; e eu ouvi o número deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'E assim eu vi os cavalos n esta visão; e os que cavalgavam sobre eles tinham couraças de fogo, de jacinto e de enxofre; e as cabeças dos cavalos eram como cabeças de leões; e de suas bocas saía fogo, fumaça e enxofre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Por estes três a terça parte dos homens foi morta, pela fogo, pela fumaça e pelo enxofre que saía de suas bocas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Porque o poder deles está em sua boca, e em suas caudas; porque suas caudas são semelhantes a serpentes tendo cabeças, e com elas causam dano.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'E o resto dos homens, que não foram mortos por estas pragas, não se arrependeram das obras de suas mãos, para não adorarem aos demônios, e ídolos de ouro, de prata, de bronze, de pedra e de madeira, que não podem ver, nem ouvir, nem andar;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'E não se arrependeram de seus homicídios, nem de suas feitiçarias, nem de seu pecado sexual, nem de seus roubos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'E eu vi outro forte anjo descendo do céu, vestido com uma nuvem; e por cima de sua cabeça estava o arco colorido celeste; e o rosto dele era como o sol, e os pés dele como coluna de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'E na mão dele tinha um livrinho aberto; e pôs seu pé direito sobre o mar, e o esquerdo sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'E clamou em alta voz, como quando o leão ruge; e quando ele clamou, os sete trovões falaram suas vozes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'E quando os sete trovões falaram suas vozes, eu estava a pondo de escrevê -las; mas eu ouvi uma voz do céu me dizer: Sela as coisas que os sete trovões falaram, e não as escrevas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'E o anjo que eu vi estar sobre o mar e sobre a terra levantou sua mão ao céu,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'E jurou por aquele que vive para todo o sempre, o qual criou o céu e as coisas que nele há, e a terra e as coisas que nela há, e o mar e as coisas que nele há, que não haverá mais tempo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Mas que nos dias da voz do sétimo anjo, quando sua trombeta estiver a ponto de tocar, o mistério de Deus se cumprirá, assim como ele bem anunciou a seus servos e profetas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'E a voz que eu tinha ouvido do céu voltou a falar comigo, e disse: Vai, e toma o livrinho aberto da mão do anjo que está sobre o mar e sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'E eu fui até o anjo, dizendo-lhe: Dá-me o livrinho.E ele me disse: Toma-o, e come-o; e fará amargo o teu ventre, mas em tua boca será doce como mel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'E eu tomei o livrinho da mão do anjo, e comi; e ele era em minha boca doce como o mel; mas quando eu o comi, meu ventre ficou amargo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'E ele me disse: É necessário tu profetizares outra vez a muitos povos, nações, línguas e reis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'E foi me dada uma cana semelhante a uma vara de medir; e o anjo ficou de pé,dizendo: Levanta-te, e mede o templo de Deus, e o altar, e os que nele adoram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Mas deixa fora ao pátio, que está fora do templo, e não o meças; porque ele foi dado às nações; e pisarão a santa cidade por quarenta e dois meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'E eu darei autoridade às minhas duas testemunhas, e elas profetizarão por mil duzentos e sessenta dias, vestidas de sacos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Estas são as duas oliveiras, e os dois castiçais, que estão diante do Deus da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'E se alguém quiser lhes maltratar, fogo sai da sua boca, e devora aos inimigos delas; e se alguém quiser lhes maltratar, é necessário que assim seja morto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Estas têm autoridade para fechar o céu, para que não chova nos dias da sua profecia; e têm poder sobre as águas para as transformar em sangue, e para ferir a terra com toda praga, tantas vezes quantas quiserem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'E quando elas terminarem seu testemunho, a besta, que sobe do abismo, fará guerra contra elas, e as vencerá, e as matará.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'E os cadáveres delas jazerão na praça da grande cidade, que espiritualmente se chama Sodoma e Egito, onde nosso Senhor também foi crucificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'E os dos povos, tribos, línguas e nações verão os cadáveres delas por três dias e meio, e não permitirão que os cadáveres delas sejam postos em sepulcros.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'E os que habitam sobre a terra se alegrarão sobre elas, e ficarão contentes, e enviarão presentes uns aos outros, porque estes dois profetas atormentarão aos que habitam sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'E depois d aqueles três dias e meio, entrou nelas o espírito de vida de Deus, e se puseram sobre seus pés, e caiu grande temor sobre os que as viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'E elas ouviram uma grande voz do céu lhes dizendo: Subi aqui! E elas subiram ao céu em uma nuvem; e seus inimigos as viram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'E naquela mesma hora houve um grande terremoto, e a décima parte da cidade caiu, e no terremoto foram mortos sete mil nomes humanos; e os restantes ficaram muito atemorizados, e deram glória ao Deus do céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'O segundo ai já passou; eis que o terceiro ai logo vem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'E o sétimo anjo tocou a trombeta, e houve grandes vozes no céu, dizendo: Os reinos do mundo se tornaram do nosso Senhor, e do seu Cristo, e ele reinará para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'E os vinte e quatro anciãos, que estão sentados diante de Deus em seus tronos, prostraram-se sobre seus rostos, e adoraram a Deus,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Dizendo: Graças te damos, Senhor Deus, o Todo-Poderoso, o que é, e que era, e que virá; porque tu tomaste teu grande poder, e tens reinado;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'E as nações se irarão, porém veio a tua ira, e o tempo dos mortos, para serem julgados, e para tu dares a recompensa a teus servos, os profetas, e aos santos, e aos que temem o teu nome, a pequenos e a grandes; e para destruir aos que destroem a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'E o templo de Deus se abriu no céu, e a arca de seu pacto foi vista no templo dele; e houve relâmpagos, e vozes, e trovões, e terremotos, e grande saraiva.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'E um grande sinal foi visto no céu: uma mulher vestida do sol, e a lua debaixo dos pés dela, e sobre sua cabeça uma coroa de doze estrelas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'E ela estava grávida, gritando, tendo dores de parto, e sendo atormentada pelo trabalho de parto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'E foi visto outro sinal no céu; e eis que era um grande dragão vermelho, que tinha sete cabeças e dez chifres, e sobre suas cabeças sete coroas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'E sua cauda levava após si a terça parte das estrelas do céu, e as lançou sobre a terra; e o dragão ficou parado diante da mulher, que estava a ponto de gerar filho; para que, quando ela gerasse, o dragão devorasse o filho dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'E ela gerou um filho macho, que com vara de ferro ia dominar todas as nações; e o filho dela foi arrebatado para Deus e para o trono dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'E a mulher fugiu para o deserto, onde ela tinha lugar preparado por Deus, para que lá a alimentassem por mil duzentos e sessenta dias.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'E houve batalha no céu: Miguel e seus anjos batalhavam contra o dragão; e batalhava também contra eles o dragão e seus anjos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Mas eles não prevaleceram, nem mais o lugar deles foi achado nos céus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'E foi lançado o grande dragão, a serpente antiga, chamada o diabo e Satanás, que engana a todo o mundo, ele foi lançado na terra, e seus anjos também foram lançados com ele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'E eu ouvi uma grande voz no céu, dizendo: Agora veio a salvação, e a força, e o reino de nosso Deus, e o poder de seu Cristo; porque já foi lançado abaixo o acusador de nossos irmãos, o qual os acusava diante de nosso Deus dia e noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'E eles o venceram pelo sangue do Cordeiro, e pela palavra do testemunho deles; e eles não amaram suas vidas até a morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Por isso alegrai-vos, céus, e os que nele habitais! Ai dos que habitam na terra, e no mar! Porque o diabo desceu até vos, tendo grande ira, sabendo que ele tem pouco tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'E quando o dragão viu que tinha sido lançado na terra, ele perseguiu a mulher que tinha gerado ao filho macho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'E foram dadas à mulher duas asas de grande água, para que voasse ao deserto, ao lugar dela, onde ali ela é alimentada por um tempo, e tempos, e a metade de um tempo, longe da face da serpente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'E a serpente lançou de sua boca água como de um rio, atrás da mulher, para fazer com que esta mulher seja levada pela correnteza.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'E a terra ajudou a mulher, e a terra abriu a sua boca, e engoliu ao rio que o dragão tinha lançado de sua boca.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'E o dragão se irou contra a mulher, e saiu para fazer guerra contra os demais da semente dela, os que guardam os mandamentos de Deus e têm o testemunho de Jesus Cristo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, 'E eu fiquei parado sobre a areia do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'E eu vi subir do mar uma besta, que tinha sete cabeças e dez chifres, e sobre seus chifres dez diademas; e sobre suas cabeças um nome de blasfêmia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'E a besta que eu vi era semelhante a um leopardo, e seus pés como de urso, e sua boca como boca de leão; e o dragão lhe deu seu poder, e seu trono, e grande autoridade.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'E eu vi uma de suas cabeças como ferida de morte, e sua ferida mortal foi curada; e toda a terra se maravilhou, indo atrás da besta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'E adoraram ao dragão, ao qual tinha dado poder à besta; e também adoraram à besta, dizendo: Quem é semelhante à besta? Quem pode batalhar contra ela?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'E foi-lhe dada um boca que falava grandes coisas e blasfêmias; e foi-lhe dada autoridade para fazer assim por quarenta e dois meses.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'E ela abriu sua boca em blasfêmia contra Deus, para blasfemar do nome dele, e do tabernáculo dele, e daqueles que habitam no céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'E foi-lhe concedido fazer guerra aos santos, e os vencer; e foi-lhe dada autoridade sobre toda tribo, língua, e nação.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'E todos os que habitam sobre a terra a adorarão, o nomes dos quais não estão escritos no livro da vida do Cordeiro, que tem sido morto desde a fundação do mundo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Se alguém tem ouvido s, ouça.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Se alguém leva em cativeiro, em cativeiro irá; se alguém matar à espada, é necessário que à espada ele seja morto. Aqui está a paciência e a fé dos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'E eu vi outra besta subindo da terra, e tinha dois chifres semelhantes aos de um cordeiro; e ela falava como um dragão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'E ela exercita todo o poder da primeira besta em sua presença; e faz que a terra, e os que nela habitam, adorem à primeira besta, cuja ferida mortal havia sido curada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'E ela faz grandes sinais, de maneira que faz até fogo descer do céu até a terra, diante dos homens.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'E engana aos que habitam na terra por meio de sinais, que lhe foram concedidos fazer na presença da besta; dizendo aos que habitam na terra para fazerem uma imagem para a besta que tinha recebido a ferida da espada, e ainda assim viveu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'E foi-lhe concedido dar espírito à imagem da besta, para que a imagem da besta também falasse, e fizesse com que todos os que não adorassem à imagem da besta fossem mortos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'E fez com que todos, os pequenos e os grandes, os ricos e os pobres, os livres e os escravos, fosse lhes dada uma marca sobre sua mão direita ou sobre suas testas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'E que ninguém possa comprar ou vender, a não ser aquele que tenha a marca ou o nome da besta, ou o número do nome dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Aqui está a sabedoria: aquele que tem entendimento, calcule o número da besta, porque é número humano; e seu número é seiscentos e sessenta e seis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'E eu olhei, e eis que o Cordeiro estava de pé sobre o monte Sião, e com ele cento e quarenta e quatro mil, tendo o nome do Pai dele escrito em suas testas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'E eu ouvi uma voz do céu como voz de muitas águas, e como voz de um grande trovão; e ouvi uma voz de tocadores de harpas, que tocavam com suas harpas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'E cantavam um cântico novo diante do trono, e diante dos quatro animais, e dos anciãos; e ninguém podia aprender aquele cântico, a não ser os cento e quarenta e quatro mil que tinham sido comprados da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Estes são os que não se contaminaram com mulheres, porque são virgens; estes são os que seguem ao Cordeiro onde quer que ele vá; estes foram comprados d entre os homens, sendo primícias para Deus e para o Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'E não foi encontrado engano na boca deles, porque eles são irrepreensíveis diante do trono de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'E eu vi outro anjo voando tendo o evangelho eterno, para evangelizar aos que habitam sobre a terra, e a toda nação, tribo, língua e povo;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Dizendo em alta voz: Temei a Deus, e dai glória a ele; porque chegou a hora do julgamento dele; e adorai àquele que fez o céu, a terra, o mar e as fontes de águas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'E seguiu outro anjo, dizendo: Ela caiu! Caiu a Babilônia, a grande cidade, porque ela deu de beber a todas as nações do vinho da ira de seu pecado sexual.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'E o terceiro anjo os seguiu, dizendo em alta voz: Se alguém adora a besta e a sua imagem, e recebe a marca dela sobre sua testa, ou sobre sua mão,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Também o tal beberá do vinho da ira de Deus, que foi posto sem mistura no cálice de sua ira; e será atormentado com fogo e enxofre, diante dos santos anjos e diante do Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'E a fumaça do tormento deles sobe para todo o sempre; e não têm descanso de dia nem de noite os que adoram a besta e a sua imagem, e se alguém recebe a marca de seu nome.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Aqui está a paciência dos santos; aqui estão os que guardam os mandamentos de Deus e a fé em Jesus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'E eu ouvi uma voz do céu, que me dizia: Escreve: Bem-aventurados os mortos que morrem no Senhor a partir de agora; sim, diz o Espírito, para que se descansem de seus trabalhos; e suas obras os seguem.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'E eu olhei, e eis uma nuvem branca, e um semelhante a um filho do homem, sentado sobre a nuvem; tendo sobre sua cabeça uma coroa de ouro, e em sua mão uma foice afiada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'E outro anjo saiu do templo, clamando em alta voz ao que estava sentado sobre a nuvem: Envia a tua foice, e ceifa; pois chegou a ti a hora de ceifar, porque a plantação da terra já está madura.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'E aquele que está sentado sobre a nuvem lançou sua foice na terra, e a terra foi ceifada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'E outro anjo saiu do templo que está no céu, o qual também tinha uma foice afiada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'E outro anjo, que tinha poder sobre o fogo, saiu do altar; e ele clamou em alta voz ao que tinha a foice afiada, dizendo: Envia tua foice afiada, e recolhe os cachos da vinha da terra; porque suas uvas já estão maduras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'E o anjo lançou sua foice à terra, e recolheu as uvas d a vinha da terra, e as lançou no lagar da grande ira de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'E o lagar foi pisado fora da cidade, e saiu sangue do lagar até os freios dos cavalos, por mil e seiscentos estádios.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'E eu vi outro grande e admirável sinal no céu: sete anjos, que tinham as sete últimas pragas; porque nelas a ira de Deus se torna completa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'E eu vi como um mar de vidro misturado como fogo; e aos que venceram a besta, a sua imagem, e sua marca, e o número de seu nome, os quais estavam de pé junto ao mar de vidro, e tinham harpas de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'E cantavam o cântico de Moisés, o servo de Deus, e o cântico do Cordeiro, dizendo: Grandes e maravilhosas são tuas obras, ó Senhor Deus Todo-Poderoso! Teus caminhos são justos e verdadeiros, ó Rei dos santos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Quem não te temeria, ó Senhor, e não glorificaria o teu nome? Porque só tu és santo; porque todas as nações virão, e adorarão diante de ti, porque teus juízos foram manifestos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'E depois disto eu olhei, e eis que o templo do tabernáculo do testemunho foi aberto no céu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'E os sete anjos, que tinham as sete pragas, saíram do templo, vestidos de linho puro e brilhante, e cingidos com cintos de ouro ao redor dos peitos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'E um dos quatro animais deu aos sete anjos sete taças de ouro, cheias da ira de Deus, aquele que vive para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'E o templo se encheu com a fumaça da glória de Deus, e do seu poder; e ninguém podia entrar no templo, enquanto as sete pragas dos sete anjos não estivessem completas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'E eu ouvi uma grande voz do templo, dizendo aos sete anjos: Ide, e derramai as taças da ira de Deus sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'E foi o primeiro, e derramou sua taça sobre a terra; e se fez uma chaga ruim e maligna nos homens que tinham a marca da besta, e que adoravam a imagem dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'E o segundo anjo derramou sua taça sobre o mar, e este se tornou em sangue como de morto, e toda alma vivente no mar morreu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'E o terceiro anjo derramou sua taça sobre os rios, e sobre as fontes de águas, e se tornaram em sangue.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'E eu ouvi ao anjo das águas, dizendo: Justo és tu, Senhor, que és, e que eras, e que virás a ser, porque julgaste estas coisas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Porque eles derramaram o sangue dos santos e dos profetas, também tu lhes deste sangue a beber; porque disto eles são merecedores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'E ouvi um outro do altar, dizendo: Sim, Senhor Deus Todo-Poderoso, verdadeiros e justos são teus juízos!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'E o quarto anjo derramou sua taça sobre o sol; e foi-lhe concedido, que queimasse aos homens com fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'E os homens foram queimados com grande calor, e blasfemaram do nome de Deus, que tem poder sobre estas pagas; e eles não se arrependeram, para lhe darem glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'E o quinto anjo derramou sua taça sobre o trono da besta, e seu reino se tornou em trevas, e mordiam de dor suas línguas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'E eles blasfemaram a Deus do céu por causa de suas dores e por causa de suas chagas; e não se arrependeram de suas obras.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'E o sexto anjo derramou sua taça sobre o grande rio Eufrates; e sua água se secou, para que se preparasse o caminho dos Reis do oriente,onde o sol nasce.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'E da boca do dragão, e da boca da besta, e da boca do falso profeta, eu vi saírem três espíritos imundos, semelhantes a rãs.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Porque são espíritos de demônios, e fazem sinais sobrenaturais, os quais vão aos reis da terra, e de todo o mundo, para os ajuntarem à batalha daquele grande dia do Deus Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(Eis que eu venho como ladrão. Bem-aventurado aquele que vigia e guarda suas roupas, para que não ande nu, e vejam seu impudor).');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'E foram reunidos no lugar que em hebraico se chama Armagedom.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'E o sétimo anjo derramou sua taça sobre o ar; e saiu uma grande voz do templo do céu, do trono, dizendo: Está feito.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'E houve vozes, e trovões, e relâmpagos; e houve um grande terremoto, o qual nunca tinha acontecido desde que existiam homens sobre a terra, tão forte e grande assim.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'E a grande cidade se fendeu em três partes, e as cidades das nações caíram; e a grande Babilônia veio em memória diante de Deus, para dar a ela o cálice do vinho da indignação da ira dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'E toda ilha fugiu, e os montes não foram achados.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'E uma grande saraiva, como de peso de um talento, caiu do céu sobre os homens; e os homens blasfemaram a Deus por causa da praga da saraiva, porque a sua praga era muito grande.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'E veio um dos sente anjos que tinham as sete taças, e falou comigo, dizendo-me: Vem, eu te mostrarei a condenação da grande prostituta, que está sentada sobre muitas águas;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Com a qual os reis da terra se prostituíram, e os que habitam na terra se embriagaram com o vinho da prostituição dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'E ele me levou em espírito a um deserto, e eu vi uma mulher sentada sobre uma besta de cor de escarlate, que estava cheio de nomes de blasfêmia. E ele tinha sete cabeças e dez chifres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'E a mulher estava vestida de púrpura e de escarlate, e adorada com ouro, pedras preciosas, e pérolas; e em sua mão tinha um cálice de ouro cheio das abominações e da impureza de sua prostituição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'E na testa dela estava escrito um nome: “Mistério: A grande Babilônia, a mãe das prostituições e abominações da terra”.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'E vi que a mulher estava bêbada do sangue dos santos, e do sangue das testemunhas de Jesus. E eu, ao vê-la, fiquei maravilhado com grande espanto.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'E o anjo me disse: Por que tu ficaste maravilhado? Eu te direi o mistério da mulher, e da besta que a traz, a qual tem as sete cabeças e os dez chifres.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'A besta que tu viste, era, e não é; e está para subir do abismo, e irá para a perdição; e os que habitam sobre a terra (cujos nomes não estão escritos no livro da vida desde a fundação do mundo), ficarão maravilhados ao verem a besta que era, e não é, e ainda é.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Aqui está o entendimento que tem sabedoria: as sete cabeças são sete montes, sobre os quais a mulher está sentada;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'E também são sete reis, os cinco são caídos; e um é, o outro ainda não chegou; e quando chegar, é necessário que ele continue por um pouco de tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'E a besta que era, e não é, este é também o oitavo; e é um dos sete, e vai para a perdição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'E os dez chifres que tu viste são dez reis, que aina não receberam o reino; mas receberão autoridade como reis por uma hora, juntamente com a besta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Estes tem uma mesma intenção, e entregarão seu poder e autoridade à besta.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Estes batalharão contra o Cordeiro, e o Cordeiro os vencerá, porque ele é o Senhor dos senhores, e o Rei dos reis); e os que estão com ele são os chamados, escolhidos, e fiéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'E ele me disse: As águas que viste, onde a prostituta está sentada, são povos, multidões, nações e línguas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'E os dez chifres que tu viste na besta, estes odiarão a prostituta, e a farão desolada, e nua; e comerão a carne dela, e a queimarão com fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Porque Deus deu em seus corações, que cumpram a intenção dele; e tenham uma mesma intenção, e deem o reino deles à besta, até que as palavras de Deus se cumpram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'E a mulher que tu viste é a grande cidade, que tem o reinado sobre os reis da terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'E depois destas coisas eu vi outro anjo descendo do céu, tendo grande poder; e a terra foi iluminada pela sua glória.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'E ele clamou fortemente em alta voz, dizendo: Caiu! Caiu a grande Babilônia, e ela se tornou habitação de demônios, e prisão de todo espírito imundo, e prisão de toda ave impura e odiável;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Porque todas as nações têm bebido do vinho da ira da prostituição dela, e os reis da terra se prostituíram com ela, e os comerciantes da terra se enriqueceram com o poder da sensualidade dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'E eu ouvi outra voz do céu, dizendo: Saí dela, povo meu! Para que não sejais participantes dos pecados dela, e para que não recebais das pragas dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Porque os pecados dela se acumularam até o céu, e Deus se lembrou das maldades dela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Retribuí a ela assim como ela tem vos retribuído, e duplicai a ela em dobro, conforme as obras dela; no cálice em que ela preparou, preparai em dobro para ela.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'O quanto ela glorificou a si mesma, e viveu sensualmente, tanto quanto dai a ela de tormento e pranto; porque ela em seu coração diz: Eu estou sentada como rainha e não sou viúva, e nenhum pranto eu verei.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Portanto em um dia virão as pragas sobre ela: morte, pranto e fome; e ela será queimada com fogo; porque forte é o Senhor Deus, que a julga.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'E os reis da terra, que se prostituíram com ela, e viveram sensualmente, prantearão por ela, quando virem a fumaça de sua queima.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Estando de longe, por medo do tormento dela, dizendo: Ai, ai daquela grande cidade de Babilônia, aquela forte cidade! Porque em uma hora veio o teu julgamento.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'E os comerciantes da terra choram e lamentam sobre ela, porque ninguém mais compra as mercadorias deles:');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Mercadoria de ouro, e de prata, e de pedras preciosas, e de pérolas, e de linho fino, e de púrpura, e de seda, e de escarlate; e de toda madeira aromática, e de todo objeto de marfim, e de todo objeto de madeira valiosíssima, e liga de cobre, e de ferro, e de mármore;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'E canela, e perfumes, e óleo aromático, e incenso, e vinho, e azeite, e farinha fina, e trigo, e gado, e ovelhas; e de cavalos, e de carruagens, e de corpos e almas humanas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'E o fruto do mau desejo de tua alma foi embora de ti; e todas as coisas deliciosas e excelentes foram embora de ti; e tu não mais as acharás.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Os comerciantes destas coisas, que por ela se enriqueceram, estarão de longe por medo do tormento dela, chorando e lamentando,');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'E dizendo: Ai, ai daquela grande cidade, que estava vestida de linho fino, e púrpura, e escarlate; e adornada com ouro, pedras preciosas, e pérolas! Porque em uma hora tantas riquezas foram assoladas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'E todo capitão de embarcação, e todos d a multidão que estavam em barcos, e marinheiros, e todos os que trabalham no mar, se puseram de longe;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'E vendo a fumaça da queima dela, clamaram, dizendo: Havia algo comparável a esta grande cidade?');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'E eles lançaram pó em suas cabeças, e clamaram, chorando e lamentando, dizendo: Ai, ai daquela grande cidade, em que todos os que tinham barcos no mar se enriqueceram da opulência dela! Porque em uma hora ela foi assolada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Alegra-te sobre ela, céu; e também vós santos apóstolos e profetas; porque Deus já tem julgado dela vossa causa.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'E um forte anjo levantou uma pedra, como uma grande pedra de moinho, e a lançou no mar, dizendo: Com tal violência Babilônia será lançada, aquela grande cidade, e não mais será achada.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'E voz de harpistas, e de músicos, e de flautistas, e de tocadores de trombeta, não mais se ouvirá em ti; e nenhum artesão de toda arte não mais se achará em ti; e ruído de moinho não mais se ouvirá em ti.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'E luz de lâmpada não mais iluminará em ti; e voz de noivo e de noiva não mais se ouvirá em ti; porque teus comerciantes eram os grandes da terra, porque por tuas feitiçarias todas as nações foram enganadas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'E nela se achou o sangue dos profetas e dos santos, e de todos os que foram mortos sobre a terra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'E depois destas coisas, eu ouvi uma voz de uma grande multidão no céus, que dizia: Aleluia! Salvação, glória, honra, e poder ao Senhor, nosso Deus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Porque verdadeiros e justos são seus juízos; pois ele julgou a grande prostituta, que com sua prostituição corrompia a terra, e vingou da mão dela o sangue dos servos dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'E disseram pela segunda vez: Aleluia!E a fumaça dela sobe para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'E os vinte e quatro anciãos, e os quatro animais, se prostraram, e adoraram a Deus (que estava sentado no trono) e diziam: Amém! Aleluia!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'E saiu uma voz do trono, dizendo: Louvai ao nosso Deus, todos vós os servos dele, e vós que o temeis, tanto pequenos como grandes;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'E eu ouvi como a voz de uma grande multidão, e como a voz de muitas águas, e como a voz de fortes trovões, dizendo: Aleluia! Porque o Senhor Deus Todo-Poderoso reina!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Alegremos, e fiquemos muito contentes, e demos glória a ele, pois já chegou a festa de casamento do Cordeiro, e a sua esposa já se preparou.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'E foi concedido a ela que se vestisse de linho fino puro e brilhante;pois o linho fino são as justiças dos santos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'E ele me disse: Escreve: Bem-aventurados são aqueles que foram chamados para a ceia da festa de casamento do Cordeiro.E ele me disse: Estas são as verdadeiras palavras de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'E eu me lancei aos pés dele para o adorar; mas ele me disse: Olha, não faça isso! Eu também sou companheiro servo teu, e de teus irmãos, que têm o testemunho de Jesus; adora a Deus; porque o testemunho de Jesus é o espírito da profecia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'E eu vi o céu aberto; e eis um cavalo branco; e o que estava sentado sobre ele era chamado Fiel e Verdadeiro, e em justiça ele julga e guerreia.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'E os olhos dele eram como uma chama de fogo; e sobre a cabeça dele havia muitas diademas, e ele tinha um nome escrito, que ninguém sabia, a não ser ele mesmo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'E ele estava vestido de uma roupa tingida em sangue, e o nome dele é chamado Palavra de Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'E os exércitos no céu o seguiam em cavalos brancos, vestidos de linho fino branco e puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'E da boca dele saía uma espada afiada, para com ela ferir às nações; e ele as dominará com vara de ferro; e ele pisa o lagar do vinho da ira e da indignação do Deus Todo-Poderoso.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'E ele tem sobre sua roupa e sobre sua coxa escrito este nome: Rei dos Reis, e Senhor dos Senhores.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'E eu vi um anjo que estava no sol; e ele clamou em alta voz, dizendo a todas as aves que voavam no meio do céu: Vinde, e ajuntai-vos para a ceia do grande Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Para que comais a carne dos reis, e a carne dos governantes, e a carne dos fortes, e a carne dos que se sentam sobre eles; e a carne de todos os livres e servos; e dos pequenos e dos grandes.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'E eu vi a besta, e os reis da terra, e os exércitos deles juntos, para fazerem guerra contra aquele que estava sentado sobre o cavalo, e contra o exército dele.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'E a besta foi presa, e com ela o falso profeta, que diante dela fazia os sinais sobrenaturais, com os quais tinha enganado aos que receberam a marca da besta, e adoraram à imagem dela. Estes dois foram lançados vivos no lago do fogo ardente em enxofre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'E os restantes foram mortos com a espada que saía da boca daquele que estava sentado sobre o cavalo; e as aves se saciaram com as carnes deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'E eu vi um anjo descendo do céu, tendo a chave do abismo; e uma grande corrente em sua mão;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'E ele deteve ao dragão, e à antiga serpente, que é o diabo e Satanás, e o amarrou por mil anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'E o lançou no abismo, e ali o prendeu, e o selou sobre ele; para que não mais enganasse às nações, até que se completem os mil anos; e depois disto é necessário que ele seja solto por um pouco de tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'E eu vi tronos, e sentaram sobre eles, e foi concedido a eles o julgamento; e eu vi as almas daqueles que tinham sido degolados por causa do testemunho de Jesus, e por causa da palavra de Deus; e que não tinham adorado à besta, nem à imagem dela; e que não receberam a marca dela sobre suas testas, e sobre suas mãos; e eles viveram e reinaram com Cristo por mil anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Mas os outros mortos não reviveram, enquanto não se completassem os mil anos. Esta é a primeira ressurreição.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Bem-aventurado e santo é aquele que tem parte na primeira ressurreição; sobre estes a segunda morte não tem poder; mas sim, eles serão sacerdotes de Deus e de Cristo, e reinarão com ele por mil anos.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'E quando se completarem os mil anos, Satanás será solto de sua prisão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'E ele sairá para enganar às nações, que estão nos quatro cantos da terra; a Gogue, e a Magogue, para os ajuntar em batalha; dos quais o numero é como a areia do mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'E eles subiram sobre a largura da terra, e cercaram o acampamento dos santos, e a cidade amada; e desceu fogo do céu vindo de Deus; e os consumiu.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'E o diabo, que os enganava, foi lançado no lago de fogo e enxofre, onde estão a besta e o falso profeta; e serão atormentados dia e noite para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'E eu vi a um grande trono branco, e ao que estava sentado sobre ele; do rosto dele a terra e o céu fugiram, e não foi achado lugar para eles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'E eu vi aos mortos, grandes e pequenos, estarem de pé diante de Deus; e os livros foram abertos; e outro livro foi aberto (que é o livro da vida); e os mortos foram julgados pelas coisas que estavam escritas nos livros, segundo as obras deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'E o mar entregou os mortos que nele havia; e a morte e o mundo dos mortos entregaram os mortos que neles havia; e foram julgados cada um segundo as obras deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'E a morte e o mundo dos mortos foram lançados no lago de fogo; esta é a segunda morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'E todo aquele que não fosse achado escrito no livro da vida foi lançado no lago de fogo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'E eu vi um novo céu e uma nova terra; porque o primeiro céu e a primeira terra já passaram; e e já não havia mar.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'E eu, João, vi a cidade santa, a nova Jerusalém, descendo do céu vinda de Deus, preparada como noiva, adornada para seu marido.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'E eu ouvi uma grande voz do céu, dizendo: Eis que o tabernáculo de Deus está com os homens, e com eles habitará, e eles serão seu povo, e o próprio Deus estará com eles, e será seu Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'E Deus limpará toda lágrima dos olhos deles; e não haverá mais morte, nem pranto, nem clamor, nem mais haverá dor; porque as primeiras coisas já passaram.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'E o que estava sentado sobre o trono disse: Eis que eu faço novas todas as coisas.E ele me disse: Escreve, porque esta palavras são verdadeiras e fiéis.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'E ele me disse: Está feito. Eu sou o Alfa e o Ômega, o princípio e o fim. Quem tiver sede, de graça eu lhe darei da fonte da água da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Quem vencer herdará todas as coisas; e eu serei Deus dele, e ele será meu filho.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Mas quanto aos covardes, e aos incrédulos, e aos abomináveis, e aos homicidas, e aos pecadores sexuais, e aos feiticeiros, e aos idólatras, e a todos os mentirosos, a parte deles será no lago que queima com fogo e enxofre, que é a segunda morte.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'E veio a mim um dos sete anjos que tinham as sete taças cheias das sete últimas pragas; e ele falou comigo, dizendo: Vem, e eu te mostrarei a noiva, a mulher do Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'E ele me levou em espírito a um grande e alto monte; e ele me mostrou a grande cidade, a santa Jerusalém, descendo do céu vinda de Deus;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'E tendo a glória de Deus; e sua luz era semelhante a uma pedra preciosíssima, como a pedra de jaspe, como cristal brilhante;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'E tinha um grande e alto muro tendo doze portas; e nas portas doze anjos, e nomes escritos nelas, que são os nomes das doze tribos dos filhos de Israel.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'No oriente tinha três portas; no norte três portas, no sul três portas, e no ocidente três portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'E o muro da cidade tinha doze fundamentos, e neles os nomes dos doze apóstolos do Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'E aquele que estava falando comigo tinha uma cana de ouro, para medir a cidade, e suas portas, e seu muro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'E a cidade estava posta na forma de um quadrado; e o seu comprimento era tanto quanto sua largura. E ele mediu a cidade com a cana até doze mil estádios; e seu comprimento, largura e altura eram iguais.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'E ele mediu seu muro de cento e quarenta e quatro côvados, conforme a medida humana, que é também a do anjo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'E a constituição de seu muro era de jaspe; e a cidade era de ouro puro, semelhante a vidro puro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'E os fundamentos do muro da cidade estavam adornados com toda pedra preciosa; o primeiro fundamento era jaspe; o segundo, safira; o terceiro, calcedônia; o quarto, esmeralda;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'O quinto, sardônica; o sexto, sárdio; o sétimo, crisólito; o oitavo, berilo; o nono, topázio; o décimo, crisópraso; o décimo primeiro, jacinto; o décimo segundo, ametista.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'E as doze portas eram doze pérolas; cada uma das portas era de uma pérola; e a praça da cidade era de ouro puro, como vidro transparente.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'E nela eu não vi templo, porque o templo dela é o Senhor Deus Todo-Poderoso, e o Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'E a cidade não necessita de sol nem de lua para que brilhem nela; porque a glória de Deus a ilumina, e sua lâmpada é o Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'E as nações dos salvos andarão na luz dela; e os reis da terra trarão a ela a glória e honra deles.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'E suas portas não se fecharão de dia; porque ali não haverá noite.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'E a ela serão trazidas a glória e a honra das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'E de maneira nenhuma entrará nela algo que contamine, faça abominação e mentira; a não ser somente aqueles que estão escritos no livro da vida do Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'E ele me mostrou o rio puro da água da vida, claro como cristal, que vinha do trono de Deus e do Cordeiro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'No meio de sua praça, e de um lado e do outro do rio, estava a árvore da vida, que produz doze frutos, dando seu fruto a cada mês; e as folhas das árvores são para a saúde das nações.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'E não haverá mais maldição alguma; e nela estará o trono de Deus e do Cordeiro, e seus servos o servirão.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'E eles verão o rosto dele, e o nome dele estará em suas testas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'E ali não haverá mais noite, e não terão necessidade de lâmpada, nem de luz do sol; porque o Senhor Deus os ilumina; e reinarão para todo o sempre.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'E ele me disse: Estas palavras são fiéis e verdadeiras; e o Senhor, o Deus dos santos profetas, enviou o seu anjo para mostrar a seus servos as coisas que devem acontecer em breve.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Eis que logo venho; bem-aventurado é aquele que guarda as palavras da profecia deste livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'E eu, João, sou aquele que vi e ouvi estas coisas. E quando eu as ouvi e vi, prostrei-me para adorar diante dos pés do anjo, que me mostrava estas coisas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'E ele me disse: Olha, não faça isto! Porque eu sou um companheiro servo teu, e de teus irmãos, os profetas, e dos que guardam as palavras deste livro. Adora a Deus.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'E ele me disse: Não seles as palavras da profecia deste livro, porque perto está o tempo.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Quem é injusto, faça injustiça ainda; e quem é sujo, suje-se ainda; e quem é justo, seja ainda justificado; e quem é santo, seja ainda santificado.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Eis que logo venho, e minha recompensa está comigo, para retribuir a cada um assim como for sua obra.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Eu sou o Alfa e o Ômega, o principio e o fim, o primeiro e o último.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Bem-aventurados os que guardam os mandamentos dele, para que tenham direito à árvore da vida, e possam entrar na cidade pelas portas.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Mas de fora estarão os cães, os feiticeiros, os pecadores sexuais, os homicidas, os idólatras, e todo aquele que ama e pratica a mentira.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Eu, Jesus, enviei o meu anjo, para vos dar testemunho destas coisas nas igrejas. Eu sou a raiz e descendência de Davi; sou a brilhante estrela da manhã.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'E o Espírito e a noiva dizem: Vem!E quem o ouve, diga: Vem!E quem tem sede, venha; e quem quiser, tome de graça da água da vida.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Porque eu também dou testemunho a todo aquele que ouvir as palavras da profecia deste livro, que se alguém acrescentar a estas, Deus lhe acrescentará as pragas que estão escritas neste livro;');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'E se alguém tirar das palavras do livro desta profecia, Deus tirará sua parte do livro da vida, e da cidade santa, e das coisas que estão escritas neste livro.');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Aquele que dá testemunho destas coisas diz: Certamente logo venho. Amém! Sim, vem, Senhor Jesus!');
INSERT INTO `PorBLivreTR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'A graça do nosso Senhor Jesus Cristo seja com todos vós. Amém!');
